export const nvltSentences: Sentence[] = [
  {"id":"s_work_nvlt_1_1","chapterId":"ch_work_nvlt_1","text":"卷一天部上據明本補","sortOrder":1},
  {"id":"s_work_nvlt_1_2","chapterId":"ch_work_nvlt_1","text":"○天日月星雲風","sortOrder":2},
  {"id":"s_work_nvlt_1_4","chapterId":"ch_work_nvlt_1","text":"《周易》曰：大哉乾元，萬物資始，乃統天，雲行雨施，品物流形，大明終始。六位時成，時乘六龍以御天，乾道变化，各正性命。","sortOrder":4},
  {"id":"s_work_nvlt_1_5","chapterId":"ch_work_nvlt_1","text":"又曰：立天之道，曰陰與陽。","sortOrder":5},
  {"id":"s_work_nvlt_1_6","chapterId":"ch_work_nvlt_1","text":"又曰：天行健。","sortOrder":6},
  {"id":"s_work_nvlt_1_7","chapterId":"ch_work_nvlt_1","text":"《尚書》曰：乃命羲和，钦若昊天。","sortOrder":7},
  {"id":"s_work_nvlt_1_8","chapterId":"ch_work_nvlt_1","text":"又曰：皇天震怒，命我文考，肅將天威。","sortOrder":8},
  {"id":"s_work_nvlt_1_9","chapterId":"ch_work_nvlt_1","text":"《禮記》曰：天地之道，博也，厚也，高也，明也，悠也，久也，日月星辰系焉。萬物覆焉。","sortOrder":9},
  {"id":"s_work_nvlt_1_10","chapterId":"ch_work_nvlt_1","text":"《論語》曰：天何言哉，四時行焉，百物生焉。","sortOrder":10},
  {"id":"s_work_nvlt_1_11","chapterId":"ch_work_nvlt_1","text":"《老子》曰：天得一以清。","sortOrder":11},
  {"id":"s_work_nvlt_1_12","chapterId":"ch_work_nvlt_1","text":"《春秋繁露》曰：天有十端，天地陰陽水土金木火人，凡十端，天亦喜［《太平御覽》一喜上有有字。］怒之氣，哀樂之心，與人相副，以類合之，天人一也。","sortOrder":12},
  {"id":"s_work_nvlt_1_13","chapterId":"ch_work_nvlt_1","text":"《爾雅》曰：穹蒼，蒼天也，春為蒼天，夏為昊天，秋為旻天，冬為上天。","sortOrder":13},
  {"id":"s_work_nvlt_1_14","chapterId":"ch_work_nvlt_1","text":"《春秋元命苞》曰：天不足西北，陽極於九，故天周九九八十一萬里。","sortOrder":14},
  {"id":"s_work_nvlt_1_15","chapterId":"ch_work_nvlt_1","text":"浑天儀曰：天如雞子，天大地小，天表里有水，地［《开元占經》一，《太平御覽》二，地上有天字。］各乘氣而立，載水而浮，天轉如車轂之運。","sortOrder":15},
  {"id":"s_work_nvlt_1_16","chapterId":"ch_work_nvlt_1","text":"《黃帝素問》曰：積陽為天，故天者清陽也。","sortOrder":16},
  {"id":"s_work_nvlt_1_17","chapterId":"ch_work_nvlt_1","text":"《莊子》曰：天之蒼蒼，其正色邪，其遠而無所至極邪。","sortOrder":17},
  {"id":"s_work_nvlt_1_18","chapterId":"ch_work_nvlt_1","text":"《申子》曰：天道無私，是以恒正，天常正，是以清明。","sortOrder":18},
  {"id":"s_work_nvlt_1_19","chapterId":"ch_work_nvlt_1","text":"《文子》曰：高莫高於天，下莫下於泽，天高泽下，聖人法之。","sortOrder":19},
  {"id":"s_work_nvlt_1_20","chapterId":"ch_work_nvlt_1","text":"《太玄》曰：有九天，一為中天，二為羨天，三為從天，四為更天，五為睟天，六為廓天，七為鹹天，八為沈天，九為成天。","sortOrder":20},
  {"id":"s_work_nvlt_1_21","chapterId":"ch_work_nvlt_1","text":"又曰：天以不見為玄。","sortOrder":21},
  {"id":"s_work_nvlt_1_22","chapterId":"ch_work_nvlt_1","text":"《皇覽記》［《太平御覽》二作皇覽冢墓記。］曰：好道者，言黃帝乘龍升雲，登朝霞，上至列闕，倒影經過天宮。","sortOrder":22},
  {"id":"s_work_nvlt_1_23","chapterId":"ch_work_nvlt_1","text":"《禮統》曰：天地者，元氣之所生萬物之祖也。","sortOrder":23},
  {"id":"s_work_nvlt_1_24","chapterId":"ch_work_nvlt_1","text":"《廣雅》曰：太初，氣之始也，清濁未分，太始，形之始也，清者為精，濁者為形，太素，质之始也，已有素朴而未散也，二氣相接，剖判分離，輕清者為天。","sortOrder":24},
  {"id":"s_work_nvlt_1_25","chapterId":"ch_work_nvlt_1","text":"《呂氏春秋》曰：天有九野，何謂九野，中央曰鈞天，東方曰蒼天，東北曰变天。北方曰玄天，西北曰幽天，西方曰皓天，西南曰朱天，南方曰炎天，東南曰陽天。","sortOrder":25},
  {"id":"s_work_nvlt_1_26","chapterId":"ch_work_nvlt_1","text":"《列子》曰：杞國有人，忧天崩墜，身無所寄，废於寢食。又有忧彼之忧者，晓之曰：天積氣耳，無處無氣，奈何而崩墜乎，其人曰：天果積氣，日月星宿，不當墜也，晓者曰：日月星宿，亦積氣中之有光曜者，正复使墜，亦不能有中傷。","sortOrder":26},
  {"id":"s_work_nvlt_1_27","chapterId":"ch_work_nvlt_1","text":"《說苑》曰：齊桓公問管仲，王者何所貴，對曰：貴天，桓公仰觀天，管仲曰：所謂之天者，非謂蒼蒼莽莽之天也，君人者以百姓為天。","sortOrder":27},
  {"id":"s_work_nvlt_1_28","chapterId":"ch_work_nvlt_1","text":"《白虎通》曰：天者身也，天之為言镇也，居高理下，為人镇也，男女惣名為人，天地所以無惣名何，天圓地方，不相類也，天左旋，地右周，猶君臣陰陽相對向也。","sortOrder":28},
  {"id":"s_work_nvlt_1_29","chapterId":"ch_work_nvlt_1","text":"張衡《靈憲》曰：太素之前，幽清寂寞，不可為象，惟虛惟無，蓋道之根也，道根既建，由無生有，太素始萌，萌而示兆，斯謂庞洪，蓋道之幹也，道幹既育，萬物成體，於是刚柔始分，清濁異位，天成於外而體陽，故圓以動，斯謂天元，道之實也，天有元位。","sortOrder":29},
  {"id":"s_work_nvlt_1_30","chapterId":"ch_work_nvlt_1","text":"徐整《三五歷紀》曰：天地混沌如雞子，盤古生其中，萬八千歲，天地开辟，陽清為天，陰濁為地，盤古在其中，一日九变，神於天，聖於地，天日高一丈，地日厚一丈，盤古日長一丈，如此萬八千歲，天數極高，地數極深，盤古極長，後乃有三皇，數起於一，立於三，成於五，盛於七，處於九，故天去地九萬里。","sortOrder":30},
  {"id":"s_work_nvlt_1_31","chapterId":"ch_work_nvlt_1","text":"《蜀志》曰：吳使張溫來聘，溫問秦密曰：天有頭乎，密曰：有之，溫曰：在何方，密曰：詩雲，乃眷西顧，以此推之，頭在西方，溫曰：天有耳乎，密曰：天處高而聽卑，詩雲，鶴鳴九皋，聲聞於天，若其無耳，何以聽之，溫曰：天有足乎，密曰：詩雲，天步艱難，若其無足，何以步之，溫曰：天有姓乎，密曰：姓劉，何以然，曰：其子姓劉，以此知之。","sortOrder":31},
  {"id":"s_work_nvlt_1_32","chapterId":"ch_work_nvlt_1","text":"《楚辭·天問》曰：圖［《天問》作圜，《初學記》一，《太平御覽》二作圓。］則九重，孰營度之，八柱何當，東南何虧，(言天有八山為柱，皆何當值，東南不足，誰虧缺之。)日月安屬，列星安陳。","sortOrder":32},
  {"id":"s_work_nvlt_1_33","chapterId":"ch_work_nvlt_1","text":"【詩】晉傳言［《初學記》一作傅玄。］兩儀詩曰：兩儀始分，元氣上清，列宿垂象，六位時成，日月西邁，流景東征，悠悠萬物，殊品齊名，聖人忧世，實念群生。","sortOrder":33},
  {"id":"s_work_nvlt_1_34","chapterId":"ch_work_nvlt_1","text":"又天行篇曰：天行一何健，日月無高蹤，百川赴陽穀，三辰因泰蒙。","sortOrder":34},
  {"id":"s_work_nvlt_1_35","chapterId":"ch_work_nvlt_1","text":"又歌曰：天時泰兮昭以陽，清風起兮景雲翔，仰觀兮辰象，日月兮運周，俯视兮河海，百川兮東流。","sortOrder":35},
  {"id":"s_work_nvlt_1_36","chapterId":"ch_work_nvlt_1","text":"【賦】晉成公綏天地賦曰：天地至神，難以一言定稱，故體而言之，則曰兩儀，假而言之，則曰乾坤，氣而言之，則曰陰陽，性而言之，則曰柔刚，色而言之，則曰玄黃，名而言之，則曰天地，若乃懸象成文，列宿有章，三辰燭燿，五緯重光，眾星回而環極，招搖運而指方，白虎時據於參代，［冯校本作井，初學記一作昴。］青龍垂尾於氐房，玄龟匿首於女虛，朱鳥奋翼於星張，帝皇正坐於紫宮，辅臣列位於文昌，垣屏絡驿而珠連，三台差池而雁行，軒轅華布而曲列，攝提鼎峙而相望。","sortOrder":36},
  {"id":"s_work_nvlt_1_37","chapterId":"ch_work_nvlt_1","text":"【贊】晉郭璞《釋天地圖贊》曰：祭地肆瘞，郊天致煙，氣升太一，精淪九泉，至敬不文，明德惟鮮。","sortOrder":37},
  {"id":"s_work_nvlt_1_38","chapterId":"ch_work_nvlt_1","text":"【表】宋顏延之請立浑天儀表曰：張衡創物，蔡邕造論，戎夏相袭，世重其術。臣昔奉使入關，值大軍旋旆，浑儀在路，肆觀奇秘，絕代異寶，旋及王府，考諸前志，誠應夙聞，尚書，璇璣玉衡，以齊七政，崔瑗所謂數術窮天地，製作侔造化，經志所雲，圖憲所本，故體度不渝，精测尚矣，則七晷運变，無匪康時，九代貞觀，不絕司歷，臣夙懷末意，懼於非任，今忝惟職統，敢昧死以聞。","sortOrder":38},
  {"id":"s_work_nvlt_1_40","chapterId":"ch_work_nvlt_1","text":"《易》曰：日月麗乎天。","sortOrder":40},
  {"id":"s_work_nvlt_1_41","chapterId":"ch_work_nvlt_1","text":"又曰：離為日。","sortOrder":41},
  {"id":"s_work_nvlt_1_42","chapterId":"ch_work_nvlt_1","text":"又曰：日中則昃，月盈則食，天地盈虛，與時消息，而况於人乎，况於鬼神乎。","sortOrder":42},
  {"id":"s_work_nvlt_1_43","chapterId":"ch_work_nvlt_1","text":"《毛詩》曰：日居月諸，胡迭而微。","sortOrder":43},
  {"id":"s_work_nvlt_1_44","chapterId":"ch_work_nvlt_1","text":"《禮記》曰：玄端而朝日於東門之外。","sortOrder":44},
  {"id":"s_work_nvlt_1_45","chapterId":"ch_work_nvlt_1","text":"《左氏傳》曰：趙衰，冬日之日也，趙盾，夏日之日也。","sortOrder":45},
  {"id":"s_work_nvlt_1_46","chapterId":"ch_work_nvlt_1","text":"《五經通義》曰：日中有三足乌。","sortOrder":46},
  {"id":"s_work_nvlt_1_47","chapterId":"ch_work_nvlt_1","text":"《春秋內事》曰：日者陽德之母。","sortOrder":47},
  {"id":"s_work_nvlt_1_48","chapterId":"ch_work_nvlt_1","text":"《白虎通》曰：日行遲，月行疾者何，君舒臣勞也，日月所以懸著何，助天行化，昭明下地也，日月径千里。","sortOrder":48},
  {"id":"s_work_nvlt_1_49","chapterId":"ch_work_nvlt_1","text":"《風俗通》曰：成帝問劉向，俗說文帝被徵，後期，不得立，日為再中。","sortOrder":49},
  {"id":"s_work_nvlt_1_50","chapterId":"ch_work_nvlt_1","text":"《爾雅》曰：觚竹北戶西王母日下，謂之四荒，岠齊州以南戴日為丹穴，東至日所出為太平，西至日所入為太蒙。","sortOrder":50},
  {"id":"s_work_nvlt_1_51","chapterId":"ch_work_nvlt_1","text":"《廣雅》曰：日名朱明，一名耀靈，一名東君，一名大明，亦名陽乌。","sortOrder":51},
  {"id":"s_work_nvlt_1_52","chapterId":"ch_work_nvlt_1","text":"《說文》曰：日，實也，太陽之精，字從口一，象形也。","sortOrder":52},
  {"id":"s_work_nvlt_1_53","chapterId":"ch_work_nvlt_1","text":"又曰：初出為旭，［《初學記》一，《太平御覽》三作纂要曰：日初出曰旭。］日昕曰晞，日溫曰煦，日在午曰亭午，在未曰昳，日晚曰旰，日將落曰薄暮，日西落，光反照於東，謂之反景，在上曰反景，在下曰倒景，煦，日溫也，皓，日晝貌也，暉，日光也，旰，日晚也，翌，日明也，晓，日白也。","sortOrder":53},
  {"id":"s_work_nvlt_1_54","chapterId":"ch_work_nvlt_1","text":"《易坤靈圖》曰：至德之明，日月若連璧。","sortOrder":54},
  {"id":"s_work_nvlt_1_55","chapterId":"ch_work_nvlt_1","text":"《京房易傳》曰：日月大光，天下和平，上下俱昌，延年益寿，長世無極。","sortOrder":55},
  {"id":"s_work_nvlt_1_56","chapterId":"ch_work_nvlt_1","text":"《禮斗威儀》曰：政理太平，則時日五色。","sortOrder":56},
  {"id":"s_work_nvlt_1_57","chapterId":"ch_work_nvlt_1","text":"《漢書》曰：文帝時，新垣平言，臣候日再中，居頃之，日却复中，乃更以十七年為元年。","sortOrder":57},
  {"id":"s_work_nvlt_1_58","chapterId":"ch_work_nvlt_1","text":"《列子》曰：孔子東遊，見兩小兒辯斗，問其故，一兒曰：我以日始出去人近，日中時遠也，一兒曰：我以為日初出時遠，而日中時近，一兒曰：日初出，大如車蓋，及其中，才如盤盂，此不為遠者小而近者大乎，一兒曰：日初出，沧沧涼涼，及其中，如探湯，此不為近者，熱而遠者涼乎，孔子不能决也，兩兒笑曰：孰謂汝多知乎。","sortOrder":58},
  {"id":"s_work_nvlt_1_59","chapterId":"ch_work_nvlt_1","text":"《贾誼書》曰：湯曰：學聖王之道，譬其如日，靜居而獨思，譬其若火，夫人舍學聖王之道，而靜居獨思，譬其去日之明於庭，而就火之光於室也，然可以小見，不可以大知。","sortOrder":59},
  {"id":"s_work_nvlt_1_60","chapterId":"ch_work_nvlt_1","text":"應劭《漢官儀》曰：太山東南，名曰日觀，日觀者，雞鳴時見日。","sortOrder":60},
  {"id":"s_work_nvlt_1_61","chapterId":"ch_work_nvlt_1","text":"《論衡》曰：儒者論日旦出扶桑，暮入細柳，扶桑，東方之地，細柳，西方之地。","sortOrder":61},
  {"id":"s_work_nvlt_1_62","chapterId":"ch_work_nvlt_1","text":"《家語》曰：楚王渡江，得萍實，大如拳，赤如日，［事具草部。］","sortOrder":62},
  {"id":"s_work_nvlt_1_63","chapterId":"ch_work_nvlt_1","text":"《帝王世紀》曰：周文王夢日月著其身。","sortOrder":63},
  {"id":"s_work_nvlt_1_64","chapterId":"ch_work_nvlt_1","text":"《瑞應圖》曰：日月扬光者，人君之象也，君不假臣下之權，則日月扬光。","sortOrder":64},
  {"id":"s_work_nvlt_1_65","chapterId":"ch_work_nvlt_1","text":"《山海經》曰：猗天山，蘇門山，日月所出。","sortOrder":65},
  {"id":"s_work_nvlt_1_66","chapterId":"ch_work_nvlt_1","text":"又曰：大荒之中，暘穀，上有扶桑，十日所浴，九日居下［原作上，據冯校本改。］枝，一日居上［原作下，據冯校本改。］枝，皆載乌。","sortOrder":66},
  {"id":"s_work_nvlt_1_67","chapterId":"ch_work_nvlt_1","text":"又曰：有女子，名曰羲和，浴日於甘泉，羲和者，帝俊之妻，是生十日。","sortOrder":67},
  {"id":"s_work_nvlt_1_68","chapterId":"ch_work_nvlt_1","text":"《淮南子》曰：尧時十日併出，草木燋枯，尧命羿仰射十日，中其九，乌皆死，墮羽翼。","sortOrder":68},
  {"id":"s_work_nvlt_1_69","chapterId":"ch_work_nvlt_1","text":"又曰：若木在建木西，有十日，華照下地。","sortOrder":69},
  {"id":"s_work_nvlt_1_70","chapterId":"ch_work_nvlt_1","text":"又曰：日出於暘穀，浴於鹹池，拂於扶桑，是謂晨明，登於扶桑之上，爰始將行，是謂朏明，至於曲阿，是謂朝明，臨於曾泉，是謂蚤食，次於桑野，是謂晏食，臻於衡陽，是謂禺中，對於崑吾，是謂正中，靡於鳥次，［西南曰大壑。］是謂小遷，至於悲穀，是謂晡時，回於女紀，是謂大遷，經於泉隅，是謂高舂，頓於連石，是謂下舂，至於悲泉，爰息其乌，［《初學記》一，《太平御覽》三作六螭，淮南子天文篇作其馬。］是謂懸車，薄於虞泉，是謂黃昏，淪於蒙穀，是謂定昏。","sortOrder":70},
  {"id":"s_work_nvlt_1_71","chapterId":"ch_work_nvlt_1","text":"又曰：魯陽公與韓構難，戰酣，日暮，援戈而捴之，日反三舍。","sortOrder":71},
  {"id":"s_work_nvlt_1_72","chapterId":"ch_work_nvlt_1","text":"又曰：積陽之熱氣生火，火氣之精者為日。","sortOrder":72},
  {"id":"s_work_nvlt_1_73","chapterId":"ch_work_nvlt_1","text":"又曰：日中有踆乌，［踆，趾也，謂三足乌也。］河圖葉光篇曰：積精為日。","sortOrder":73},
  {"id":"s_work_nvlt_1_74","chapterId":"ch_work_nvlt_1","text":"皇甫謐《年歷》曰：日者眾陽之宗，陽精外發，故日以晝明，名曰曜靈。","sortOrder":74},
  {"id":"s_work_nvlt_1_75","chapterId":"ch_work_nvlt_1","text":"《楚辭》曰：曒將出兮東方，照吾槛兮扶桑，［槛，楯也。］","sortOrder":75},
  {"id":"s_work_nvlt_1_76","chapterId":"ch_work_nvlt_1","text":"又曰：角宿未旦，曜靈安藏，［角，東方星也，曜靈，日也，言東方未旦之時，藏其精光也。］又天問曰：羿焉畢日，乌焉解羽。","sortOrder":76},
  {"id":"s_work_nvlt_1_77","chapterId":"ch_work_nvlt_1","text":"又招魂曰：十日併出，流金鑠石。","sortOrder":77},
  {"id":"s_work_nvlt_1_78","chapterId":"ch_work_nvlt_1","text":"【詩】魏劉楨詩曰：仰视白日光，皎皎高且懸，兼燭八紘內，物類無頗偏。","sortOrder":78},
  {"id":"s_work_nvlt_1_79","chapterId":"ch_work_nvlt_1","text":"晉張載詩曰：白日隨天回，暾暾圓如規，踴躍湯穀中，上登扶桑枝。","sortOrder":79},
  {"id":"s_work_nvlt_1_80","chapterId":"ch_work_nvlt_1","text":"又詩曰：十日出湯穀，弭節馳萬里，經天曜四海，倏忽潛濛汜。","sortOrder":80},
  {"id":"s_work_nvlt_1_81","chapterId":"ch_work_nvlt_1","text":"晉傅玄詩曰：湯穀發清曜，九日栖高枝，原得併天御，六龍齊玉羁。","sortOrder":81},
  {"id":"s_work_nvlt_1_82","chapterId":"ch_work_nvlt_1","text":"梁李鏡遠詩曰：始臨東嶽觀，俄昇若木枝，萍實詎儔彩，合扇且慚規，北林耿初曜，員窗鑒早曦，照庭餘雪盡，映簷溜滴垂，徘徊匝花树，煜爚滿春池，柳陰裁靡靡，帘影复離離，曾泉豈停舍，桑榆忽在斯，回戈安得中，長繩不可羁，冲情愛景落，清宴惜光馳，溫暉徒己荷，深心竊自知。","sortOrder":82},
  {"id":"s_work_nvlt_1_83","chapterId":"ch_work_nvlt_1","text":"梁劉孝綽詠日應令詩曰：弭節馳湯穀，照曜出扶桑，園葵一何幸，傾葉奉離光。","sortOrder":83},
  {"id":"s_work_nvlt_1_84","chapterId":"ch_work_nvlt_1","text":"【歌】後漢李尤九曲歌曰：年歲晚暮時已斜，安得力士翻日車。","sortOrder":84},
  {"id":"s_work_nvlt_1_85","chapterId":"ch_work_nvlt_1","text":"晉傅玄日昇歌詠曰：東光昇朝暘，羲和初攬辔，六龍併騰驤，逸景何晃晃，旭日照萬方，皇德配天地，神明［原訛盟，據冯校本改。］鑒幽荒。","sortOrder":85},
  {"id":"s_work_nvlt_1_86","chapterId":"ch_work_nvlt_1","text":"又三光篇曰：三光垂象表，天地有晷度，聲和音响應，形立影自附，素日抱玄乌，明月懷靈兔。","sortOrder":86},
  {"id":"s_work_nvlt_1_87","chapterId":"ch_work_nvlt_1","text":"【贊】晉郭璞十日贊曰：十日併出，草木焦枯，羿乃控絃，仰落陽乌，可為洞感，天人懸符。","sortOrder":87},
  {"id":"s_work_nvlt_1_89","chapterId":"ch_work_nvlt_1","text":"《釋名》曰：月，闕也，滿則缺也，晦，灰也，月［《釋名》一作火。］死為灰，月光盡似之也，朔，蘇也，月死复蘇生也，絃，月半之名也，其形一旁曲，一旁直，若張弓絃也，望，月滿之名也，日月遙相望者也。","sortOrder":89},
  {"id":"s_work_nvlt_1_90","chapterId":"ch_work_nvlt_1","text":"《廣雅》曰：夜光謂之月。","sortOrder":90},
  {"id":"s_work_nvlt_1_91","chapterId":"ch_work_nvlt_1","text":"《山海經》曰：大荒之中，有方山，日月所出入也。","sortOrder":91},
  {"id":"s_work_nvlt_1_92","chapterId":"ch_work_nvlt_1","text":"《五經通義》曰：月中有兔與蟾蜍何，月，陰也，蟾蜍，陽也，而與兔併明，陰系陽也。","sortOrder":92},
  {"id":"s_work_nvlt_1_93","chapterId":"ch_work_nvlt_1","text":"《文選》：月上軒而飛光。","sortOrder":93},
  {"id":"s_work_nvlt_1_94","chapterId":"ch_work_nvlt_1","text":"《乾凿度》曰：月三日成魄，八日成光，蟾蜍體就，穴鼻始明，［穴，决也，决鼻，兔也。］尸［原訛尹，據冯校本改。］子曰：使星司夜，月司時，猶使雞司晨也。","sortOrder":94},
  {"id":"s_work_nvlt_1_95","chapterId":"ch_work_nvlt_1","text":"《尚書大傳》曰：晦而月見西方謂之眺，［眺，條也，條健，行疾濬也。］朔而月見東方謂之侧匿［侧匿猶縮懦也，行遲濬也。］。","sortOrder":95},
  {"id":"s_work_nvlt_1_96","chapterId":"ch_work_nvlt_1","text":"《禮記》曰：月者三日成魄，三月而成時。","sortOrder":96},
  {"id":"s_work_nvlt_1_97","chapterId":"ch_work_nvlt_1","text":"《史記·天官書》曰：月行中道，安寧和平。","sortOrder":97},
  {"id":"s_work_nvlt_1_98","chapterId":"ch_work_nvlt_1","text":"又曰：太陰之精上為日，［據《开元占經》十一作月。］月者，天地之陰，金之精也。","sortOrder":98},
  {"id":"s_work_nvlt_1_99","chapterId":"ch_work_nvlt_1","text":"《禮含文嘉》曰：君致尊而製命，則日月貞明。","sortOrder":99},
  {"id":"s_work_nvlt_1_100","chapterId":"ch_work_nvlt_1","text":"《春秋孔演圖》曰：仁義之道，日月循緯。","sortOrder":100},
  {"id":"s_work_nvlt_1_101","chapterId":"ch_work_nvlt_1","text":"《漢書》曰：元後母李氏，夢月入其懷而生後。","sortOrder":101},
  {"id":"s_work_nvlt_1_102","chapterId":"ch_work_nvlt_1","text":"《禮斗威儀》曰：政太平則月圓而多辉，政升平則月清而明。","sortOrder":102},
  {"id":"s_work_nvlt_1_103","chapterId":"ch_work_nvlt_1","text":"張衡《靈憲》曰：月者陰精之宗，積而成獸，象蜍兔。","sortOrder":103},
  {"id":"s_work_nvlt_1_104","chapterId":"ch_work_nvlt_1","text":"又曰：姮娥奔月，是為蟾蜍，《淮南子》曰：月，天之使也，積陰之寒氣，大者為水，水氣之精者為月。","sortOrder":104},
  {"id":"s_work_nvlt_1_105","chapterId":"ch_work_nvlt_1","text":"又曰：月者陰之宗，是以月毀而魚腦减。","sortOrder":105},
  {"id":"s_work_nvlt_1_106","chapterId":"ch_work_nvlt_1","text":"又曰：羿請不死之藥於西王母，姮娥竊之奔月宮，姮娥，羿妻也，服藥得仙。奔入月中為月精。","sortOrder":106},
  {"id":"s_work_nvlt_1_107","chapterId":"ch_work_nvlt_1","text":"又曰：畫隨灰而月晕闕，［以芦灰隨晕環，闕其一面，則月晕亦闕於上也。］","sortOrder":107},
  {"id":"s_work_nvlt_1_108","chapterId":"ch_work_nvlt_1","text":"又曰：方諸見月，則津而為水，［方諸，陰燧大蛤也，熟摩拭令熱，以向月，則水生，銅盤受之，下水數石也。］","sortOrder":108},
  {"id":"s_work_nvlt_1_109","chapterId":"ch_work_nvlt_1","text":"《呂氏春秋》曰：月群陰之本，月望則蚌蛤實，群陰盈，月晦則蚌蛤虛，群陰揫，夫月形於天，而群陰化為川。","sortOrder":109},
  {"id":"s_work_nvlt_1_110","chapterId":"ch_work_nvlt_1","text":"又曰：月纏二十八宿。","sortOrder":110},
  {"id":"s_work_nvlt_1_111","chapterId":"ch_work_nvlt_1","text":"《文子》曰：百星之明，不如一月之光。","sortOrder":111},
  {"id":"s_work_nvlt_1_112","chapterId":"ch_work_nvlt_1","text":"京房《易飛候》曰：正月有偃月，必有嘉王。","sortOrder":112},
  {"id":"s_work_nvlt_1_113","chapterId":"ch_work_nvlt_1","text":"皇甫謐《年歷》曰：月群陰之宗，光內日影以霄曜，名曰夜光。","sortOrder":113},
  {"id":"s_work_nvlt_1_114","chapterId":"ch_work_nvlt_1","text":"《物理論》曰：京房說，月與星至陰也，有形無光，日照之乃光，如以鏡照日，而有影見。","sortOrder":114},
  {"id":"s_work_nvlt_1_115","chapterId":"ch_work_nvlt_1","text":"《舊歷說》曰：日猶火也，月猶水也，火則施光，水則含影，故朏生於向日，魄生於背日，當日則光盈，近日則明滅。","sortOrder":115},
  {"id":"s_work_nvlt_1_116","chapterId":"ch_work_nvlt_1","text":"《楚辭》曰：夜光何德，死而又育，厥利維何，顧兔在腹。","sortOrder":116},
  {"id":"s_work_nvlt_1_117","chapterId":"ch_work_nvlt_1","text":"又曰：何泛濫之浮雲，欻擁蔽於明月，思耿耿而原見，然陰曀而不達。","sortOrder":117},
  {"id":"s_work_nvlt_1_118","chapterId":"ch_work_nvlt_1","text":"傅鹹擬天問曰：月中何有，白兔捣藥，興福降祉。","sortOrder":118},
  {"id":"s_work_nvlt_1_119","chapterId":"ch_work_nvlt_1","text":"【詩】晉陆機詩曰：安寢北堂上，明月入我牖，照之有餘煇，攬之不盈手。","sortOrder":119},
  {"id":"s_work_nvlt_1_120","chapterId":"ch_work_nvlt_1","text":"宋孝武帝斋中望月詩曰：褰幕荡暄氣，入夜漸流清，微微風始發，暧暧月初明，思因往物深，悲以歸雲盈。","sortOrder":120},
  {"id":"s_work_nvlt_1_121","chapterId":"ch_work_nvlt_1","text":"宋鮑照玩月詩曰：蛾眉蔽珠栊，玉鉤隔琐窗。三五二八時，千里與君同。夜移衡漢落，徘徊帷幌中。","sortOrder":121},
  {"id":"s_work_nvlt_1_122","chapterId":"ch_work_nvlt_1","text":"齊虞羲詠秋月詩曰：影麗高台端，光入長門殿。初生似玉鉤，裁滿如团扇。泛濫浮陰來，金波時不見。傥遇賞心者，照之西園宴。","sortOrder":122},
  {"id":"s_work_nvlt_1_123","chapterId":"ch_work_nvlt_1","text":"梁簡文帝望月詩曰：流辉入畫堂，初照上梅梁，形同七子鏡，影類九秋霜，桂花那不落，团扇與誰裝，空聞北窗彈，未舉西園觴。","sortOrder":123},
  {"id":"s_work_nvlt_1_124","chapterId":"ch_work_nvlt_1","text":"又望月詩曰：今夜月光來，正上相思台，可怜無遠近，光照悉徘徊。","sortOrder":124},
  {"id":"s_work_nvlt_1_125","chapterId":"ch_work_nvlt_1","text":"梁孝元帝望江中月影詩曰：澄江涵皓月，水影若浮天，風來如可泛，流急不成圓，秦鉤斷复接，和璧碎還聯，裂紈依岸草，斜桂逐行船，即此春江上，無俟百枝然。","sortOrder":125},
  {"id":"s_work_nvlt_1_126","chapterId":"ch_work_nvlt_1","text":"梁邵陵王萧纶詠新月詩曰：霜氛含月彩，霭霭下南樓，霧浓光若晝，雲駛影疑流，梁沈約詠月詩曰：月華臨靜夜，夜靜滅氛埃，方暉竟戶入，圓影隙中來，高樓切思婦，西園遊上才，網軒映珠缀，應門照绿苔，洞房殊未晓，清光信悠哉。","sortOrder":126},
  {"id":"s_work_nvlt_1_127","chapterId":"ch_work_nvlt_1","text":"梁何遜望初月詩曰：初宿長淮上，破鏡出雲明，今夕千餘里，双蛾映水生，的的與沙净，艳艳逐波輕。","sortOrder":127},
  {"id":"s_work_nvlt_1_128","chapterId":"ch_work_nvlt_1","text":"梁庾肩吾和徐主簿望月詩曰：樓上徘徊月，窗中愁思人，照雪光偏冷，臨花色轉春，星流時入晕，桂長欲侵輪，原以重光曲，承君歌扇尘。","sortOrder":128},
  {"id":"s_work_nvlt_1_129","chapterId":"ch_work_nvlt_1","text":"又望月詩曰：桂殿月偏來，留光引上才，園隨漢東蚌，晕逐淮南灰，渡河光不濕，移輪轍巨开，此夜臨清景，還承終宴杯。","sortOrder":129},
  {"id":"s_work_nvlt_1_130","chapterId":"ch_work_nvlt_1","text":"梁萧子范望秋月詩曰：河漢東西陰，清光此夜出，入帳華珠被，斜筵照寶瑟，霜惨庭上蘭，風鳴簷下橘，獨見傷心者，孤燈坐幽室。","sortOrder":130},
  {"id":"s_work_nvlt_1_131","chapterId":"ch_work_nvlt_1","text":"梁虞騫视月詩曰：清夜未雲疲，珠帘聊可發，泠泠玉潭水，映見蛾眉月，靡靡露方垂，暉暉光稍没，佳人复千里，餘影徒揮忽。","sortOrder":131},
  {"id":"s_work_nvlt_1_132","chapterId":"ch_work_nvlt_1","text":"梁劉瑗在縣中庭看月詩曰：移榻坐庭陰，初絃時复臨，侍兒能勸酒，貴客解彈琴，柏葉生鬟內，桃花出髻心，月光移數尺，方知夜已深。","sortOrder":132},
  {"id":"s_work_nvlt_1_133","chapterId":"ch_work_nvlt_1","text":"梁劉孝綽望月有所思詩曰：秋月始纖纖，微光垂步簷，曈昽入床簟，仿佛鑒窗帘，帘螢隱光息，帘虫映光織，玉羊東北上，金虎西南昃，長門隔清夜，高堂蒙容色，如何當此時，懷情滿胸臆。","sortOrder":133},
  {"id":"s_work_nvlt_1_134","chapterId":"ch_work_nvlt_1","text":"又林下映月詩曰：明明三五月，垂影當高树，攒柯半玉蟾，總葉彰金兔，茲林有夜坐，嘯歌無與晤，侧光聊可書，含毫且成賦。","sortOrder":134},
  {"id":"s_work_nvlt_1_135","chapterId":"ch_work_nvlt_1","text":"又望月詩曰：輪光缺不半，扇影出將圓，流光照漭瀁，波動映淪涟。","sortOrder":135},
  {"id":"s_work_nvlt_1_136","chapterId":"ch_work_nvlt_1","text":"梁鮑泉江上望月詩曰：客行鉤始懸，此夜月將絃，川澄光尚動，流駛影難圓，蒼蒼隨遠色，瀁々逐漪涟，無因轉還汎，回首眷前賢。","sortOrder":136},
  {"id":"s_work_nvlt_1_137","chapterId":"ch_work_nvlt_1","text":"周王襃詠月赠人詩曰：月色當秋夜，斜暉映薄帷，上絃如半璧，初魄似蛾眉，渡雲光忽駛，中天影更遲，高陽懷許掾，對此益相思。","sortOrder":137},
  {"id":"s_work_nvlt_1_138","chapterId":"ch_work_nvlt_1","text":"隋江總賦得三五明月滿詩曰：三五兔辉成，浮雲冷复輕，只輪非戰反，团扇少歌聲，雲前來往色，水上動搖明，况复高樓照，何嗟攬不盈。","sortOrder":138},
  {"id":"s_work_nvlt_1_139","chapterId":"ch_work_nvlt_1","text":"【賦】宋周祗月賦曰：二氣理化，精者能鏡，陽得一以朗旦，月代終而夕映，其状也，氣融絜而照遠，质明润而貞虛，弱不废照，清不激汙。","sortOrder":139},
  {"id":"s_work_nvlt_1_140","chapterId":"ch_work_nvlt_1","text":"宋謝靈運怨晓月賦曰：臥洞房兮當何悅，滅華燭兮弄晓月，昨三五兮既滿，今二八兮將缺，浮雲褰兮收泛滟，明舒照兮殊皎絜，墀除兮鏡鑒，房栊兮澄澈。","sortOrder":140},
  {"id":"s_work_nvlt_1_141","chapterId":"ch_work_nvlt_1","text":"宋謝莊月賦曰：陳王初丧應劉，端忧多暇，悄焉疚懷，弗怡中夜，於時斜漢左界，北陆南躔，白露暧空，素月流天，沉吟齊章，殷勤陳篇，抽毫進牍，以命仲宣，仲宣跪而稱曰：臣聞日以陽德，月以陰靈，擅扶光於東沼，嗣若英於西溟，引玄兔於帝台，集素娥於後庭，若夫氣霁地表，雲斂天末，洞庭始波，木葉微脱，菊散芳於山椒，雁流哀於江瀨，升清质之悠悠，降澄暉之霭霭，列宿掩縟，長河韜映，柔祇雪凝，圓靈水鏡，連觀霜縞，周除冰净，歌曰：美人邁兮音尘闕，隔千里兮共明月，臨風叹兮將焉歇，川路長兮不可越。","sortOrder":141},
  {"id":"s_work_nvlt_1_142","chapterId":"ch_work_nvlt_1","text":"梁沈約八詠，望秋月曰：秋月明如練，照曜三爵台。徘徊九華殿，九華玳瑁梁。華榱與璧璫，以茲雕麗色。持照明月光，凝華入黼帳。清暉懸洞房，先過飛燕戶。却映班姬床，湛秀质兮似規，委清光兮如素，照愁軒之蓬發，影金階之輕步，居人臨此笑以歌，別客對之傷旦暮，經衰圃，映寒丛，凝清夜，帶秋風，隨庭雪以偕素，與池荷而共紅，照玉墀之皎皎，含霜霭之濛濛，隱巖崖而半隔，出帷幌而才通，散朱庭之奕奕，入青琐而玲瓏。","sortOrder":142},
  {"id":"s_work_nvlt_1_144","chapterId":"ch_work_nvlt_1","text":"《說文》曰：萬物之精，上為列星。","sortOrder":144},
  {"id":"s_work_nvlt_1_145","chapterId":"ch_work_nvlt_1","text":"《尚書考靈曜》曰：五星若編珠，旋璣中星星調，則風雨時。","sortOrder":145},
  {"id":"s_work_nvlt_1_146","chapterId":"ch_work_nvlt_1","text":"《春秋說題辭》曰：星之為言精也，陽之榮也，陽精為日，日分為星，故其字日生為星。","sortOrder":146},
  {"id":"s_work_nvlt_1_147","chapterId":"ch_work_nvlt_1","text":"《尚書·洪范》曰：庶民為星，星有好風，星有好雨，月之從星，則以風雨，［月經於箕則多風，離於畢則多雨也。］","sortOrder":147},
  {"id":"s_work_nvlt_1_148","chapterId":"ch_work_nvlt_1","text":"《周禮》曰：保章氏，掌天星，以志日月星辰之变動，以觀天下之遷，辨其吉凶，以星土辨九州之地，所封之域，皆有分星，以觀妖祥。","sortOrder":148},
  {"id":"s_work_nvlt_1_149","chapterId":"ch_work_nvlt_1","text":"《左氏傳》曰：魯莊公七年夏四月辛卯，夜，恒星不見，夜明也，夜中，星陨如雨，與雨偕也。","sortOrder":149},
  {"id":"s_work_nvlt_1_150","chapterId":"ch_work_nvlt_1","text":"《春秋運斗枢》曰：北斗七星，第一天枢，第二旋，第三機，第四權，第五衡，第六开陽，第七搖光，第一至四為魁，第五至第七為摽，摽合為斗，居陰布陽，故稱北。","sortOrder":150},
  {"id":"s_work_nvlt_1_151","chapterId":"ch_work_nvlt_1","text":"《尚書中候》曰：帝尧即政，景星出翼。","sortOrder":151},
  {"id":"s_work_nvlt_1_152","chapterId":"ch_work_nvlt_1","text":"《禮稽命徵》曰：作樂製禮，得天心，則景星見。","sortOrder":152},
  {"id":"s_work_nvlt_1_153","chapterId":"ch_work_nvlt_1","text":"《春秋元命苞》曰：嘉置弧北指一大星為老人星，治平則見，見則王寿，常以秋分，候之南郊。","sortOrder":153},
  {"id":"s_work_nvlt_1_154","chapterId":"ch_work_nvlt_1","text":"《論語讖》仲尼曰：吾聞尧率舜等遊首山，觀河渚，有五老飛為流星，上入昴。","sortOrder":154},
  {"id":"s_work_nvlt_1_155","chapterId":"ch_work_nvlt_1","text":"《莊子》曰：傅說得之以相武丁，奄有天下，乘東維，騎箕尾，而比於列星。","sortOrder":155},
  {"id":"s_work_nvlt_1_156","chapterId":"ch_work_nvlt_1","text":"《尸子》曰：自井中视星，所見不過數星，自丘上以望，則見始出也，非明益也，势使然也，私心，井中也，公心，丘上也。","sortOrder":156},
  {"id":"s_work_nvlt_1_157","chapterId":"ch_work_nvlt_1","text":"《呂氏春秋》曰：宋景公時，熒惑在心，公召子韦問焉，子韦曰：禍當君，雖然，可移於宰相，公曰：宰相所與治國家也，曰：移於民，公曰：民死，寡人將誰為君，曰：可移於歲，公曰：歲飢民饿必死，為人後而殺其民，誰以我為君乎，子韦曰：君有至德之言三，天必三賞君，熒惑必徙三舍，行［呂氏春秋製樂行上有舍字。］七星，星當一年，君延年二十一矣，熒惑果徙三舍。","sortOrder":157},
  {"id":"s_work_nvlt_1_158","chapterId":"ch_work_nvlt_1","text":"《列仙傳》曰：東方朔，楚人也，後賣藥五湖，知其歲星焉。","sortOrder":158},
  {"id":"s_work_nvlt_1_159","chapterId":"ch_work_nvlt_1","text":"《史記》曰：天曜而景星見，景星，德星也，其状無常，常出有道之國。","sortOrder":159},
  {"id":"s_work_nvlt_1_160","chapterId":"ch_work_nvlt_1","text":"《漢書》曰：五星不失行，則年穀丰昌。","sortOrder":160},
  {"id":"s_work_nvlt_1_161","chapterId":"ch_work_nvlt_1","text":"又曰：五星同色，天下偃兵，百姓安寧，歌舞以行，不見灾疾，五穀蕃昌。","sortOrder":161},
  {"id":"s_work_nvlt_1_162","chapterId":"ch_work_nvlt_1","text":"《魏志》曰：桓帝時，有黃星見於楚宋之分，後五十年而公破袁紹之應，［事具帝王部。］","sortOrder":162},
  {"id":"s_work_nvlt_1_163","chapterId":"ch_work_nvlt_1","text":"《會稽典錄》曰：嚴遵字子陵，與世祖俱受業長安，建武五年，下詔徵遵，設樂陽明殿，命宴會，暮留宿，遵以足荷上，其夜客星犯天子宿，明旦，太史以聞，上曰：此無異也，昨夜與嚴子陵俱臥耳。","sortOrder":163},
  {"id":"s_work_nvlt_1_164","chapterId":"ch_work_nvlt_1","text":"孫氏《瑞應圖》曰：景星者，大星也，状如半月，生於晦朔，助月為明，王者不敢私人則見。","sortOrder":164},
  {"id":"s_work_nvlt_1_165","chapterId":"ch_work_nvlt_1","text":"又曰：王者承天，則老人星臨其國。","sortOrder":165},
  {"id":"s_work_nvlt_1_166","chapterId":"ch_work_nvlt_1","text":"李郃傳曰：公好天文之術，和帝遣使者觀風俗，有二使向益州，夏月，郃露坐，問二人曰：君發京師，寧知二使何時發，二人驚問曰：何以知之，公指星曰：有二使星來向益部。","sortOrder":166},
  {"id":"s_work_nvlt_1_167","chapterId":"ch_work_nvlt_1","text":"《續晉陽春秋》曰：桓玄庶母馬氏，本袁真之妓也，與同列薛氏郭氏夏夜同出，月下有銅盆，水在其侧，見一流星墮盆中，驚喜共视，星如二寸火珠，於水底冏然明净，乃相謂曰：此吉祥也，當誰應之，於是薛郭更以瓢杓接取，併不得，馬最後取，星正入瓢中，便飲之，既而若有感焉，俄而懷玄，玄雖篡位不終，而數年之中，榮貴極矣。","sortOrder":167},
  {"id":"s_work_nvlt_1_168","chapterId":"ch_work_nvlt_1","text":"《異苑》曰：陳仲弓從諸子侄造荀季和父子，於時德星聚，太史奏，五百里內有賢人聚。","sortOrder":168},
  {"id":"s_work_nvlt_1_169","chapterId":"ch_work_nvlt_1","text":"【詩】晉傅玄眾星詩曰：朗月併眾星，日出擅其明，冬寒地為裂，春和草木榮，陽德雖普濟，非陰亦不成。","sortOrder":169},
  {"id":"s_work_nvlt_1_170","chapterId":"ch_work_nvlt_1","text":"又詩曰：東方大明星，光景照千里，少年舍家遊，思心晝夜起。","sortOrder":170},
  {"id":"s_work_nvlt_1_171","chapterId":"ch_work_nvlt_1","text":"北齊邢子［原訛於，據冯校本改。］才贺老人星詩曰：瑞動星光照，化穆月輪重，庶徵符祉箓，將以贊時邕。","sortOrder":171},
  {"id":"s_work_nvlt_1_172","chapterId":"ch_work_nvlt_1","text":"【贊】晉郭璞星圖贊曰：茫茫地理，粲烂天文，四靈垂象，萬類群分，眇觀六沴，咎徵惟君。","sortOrder":172},
  {"id":"s_work_nvlt_1_173","chapterId":"ch_work_nvlt_1","text":"【表】晉傅玄贺老人星表曰：老人星見，揮景光明，聖主寿延，享祚元吉，自天之祐，莫不抃舞。","sortOrder":173},
  {"id":"s_work_nvlt_1_174","chapterId":"ch_work_nvlt_1","text":"又贺老人星表曰：老人星見，體色光明，嘉占元吉，弘無量之祐，隆克昌之祚，普天同慶，率土含［原作會，據冯校本改。］歡。","sortOrder":174},
  {"id":"s_work_nvlt_1_175","chapterId":"ch_work_nvlt_1","text":"晉卞壸贺老人星表曰：陛下聖德應乾，嘉瑞屢臻，玄象垂耀，老人啟徵，萬寿無疆。","sortOrder":175},
  {"id":"s_work_nvlt_1_176","chapterId":"ch_work_nvlt_1","text":"晉王述慶老人星表曰：老人星見，光色明朗，玄象暉煥，表爾休祥，率土民庶，慶賴罔極，北齊邢子才贺老人星表曰：冥貺未已，靈應猶臻，以某夜老人星見，達旦扬光，經旬未滅，雖三星共色，五老同遊，擬之於此，故無與匹，自非玄風感極，聖敬回天，何能使休徵秘祉，相尋而至，故以朝夕相趍，史無停筆。","sortOrder":176},
  {"id":"s_work_nvlt_1_178","chapterId":"ch_work_nvlt_1","text":"《歸藏》曰：有白雲出自蒼梧，入於大梁。","sortOrder":178},
  {"id":"s_work_nvlt_1_179","chapterId":"ch_work_nvlt_1","text":"《周易》曰：雲從龍。","sortOrder":179},
  {"id":"s_work_nvlt_1_180","chapterId":"ch_work_nvlt_1","text":"又曰：密雲不雨，自我西郊。","sortOrder":180},
  {"id":"s_work_nvlt_1_181","chapterId":"ch_work_nvlt_1","text":"又曰：坎為雲，《毛詩》曰：英英白雲，露彼菅茅。","sortOrder":181},
  {"id":"s_work_nvlt_1_182","chapterId":"ch_work_nvlt_1","text":"又曰：薈兮蔚兮，南山朝跻，［薈蔚，雲興也。］","sortOrder":182},
  {"id":"s_work_nvlt_1_183","chapterId":"ch_work_nvlt_1","text":"《左氏傳》：郯子曰：黃帝以雲紀官，故為雲師而雲名。","sortOrder":183},
  {"id":"s_work_nvlt_1_184","chapterId":"ch_work_nvlt_1","text":"又曰：凡分至啟閉，必書雲物，為備故也。","sortOrder":184},
  {"id":"s_work_nvlt_1_185","chapterId":"ch_work_nvlt_1","text":"《易通卦验》曰：冬至初陽，雲出箕，如树木之状，立春青陽，雲出房，如積冰，春分正陽，雲出張，如白鵠，穀雨太陽，雲出張，如車蓋，立夏初陰，雲出觜，赤如珠，夏至少陰，雲如水波，寒露正陰，雲如冠纓，霜降大陰，雲出，上如羊，下如磻石。","sortOrder":185},
  {"id":"s_work_nvlt_1_186","chapterId":"ch_work_nvlt_1","text":"《禮統》曰：雲者，運氣，布恩普也。","sortOrder":186},
  {"id":"s_work_nvlt_1_187","chapterId":"ch_work_nvlt_1","text":"《周禮》曰：保章氏，以五雲之物，辨吉凶水旱，降丰荒之祲，［二至二分觀雲色，青為虫，白為丧，赤為兵荒，黑為水，黃為丰。］","sortOrder":187},
  {"id":"s_work_nvlt_1_188","chapterId":"ch_work_nvlt_1","text":"《禮記》曰：天降時雨，山川出雲。","sortOrder":188},
  {"id":"s_work_nvlt_1_189","chapterId":"ch_work_nvlt_1","text":"《東方朔傳》曰：凡占長吏不［《太平御覽》八作東。］耕，當视天，有黃雲來覆車，五穀大熟。","sortOrder":189},
  {"id":"s_work_nvlt_1_190","chapterId":"ch_work_nvlt_1","text":"《河圖》曰：崑崙山五色雲氣。","sortOrder":190},
  {"id":"s_work_nvlt_1_191","chapterId":"ch_work_nvlt_1","text":"京房《易飛候》曰：视四方常有大雲，五色具，其下賢人隱，青雲润泽蔽雲［《开元占經》九十四，《太平御覽》八作日。］在西北，為舉賢良。","sortOrder":191},
  {"id":"s_work_nvlt_1_192","chapterId":"ch_work_nvlt_1","text":"《尚書大傳》曰：於時俊乂百工，相和而歌卿雲，帝舜乃唱之曰：卿雲烂兮，禮缦缦兮，日月光華，旦或旦兮。","sortOrder":192},
  {"id":"s_work_nvlt_1_193","chapterId":"ch_work_nvlt_1","text":"又曰：五嶽皆觸石而出雲，膚寸而合，不崇朝而雨。","sortOrder":193},
  {"id":"s_work_nvlt_1_194","chapterId":"ch_work_nvlt_1","text":"《春秋孔演圖》曰：黃帝之將興，黃雲升於堂，文命之候，玄龍御雲，天命於湯，白雲入房，［事具祥瑞部。］","sortOrder":194},
  {"id":"s_work_nvlt_1_195","chapterId":"ch_work_nvlt_1","text":"《孝經援神契》曰：天子孝，天龍負圖，地龟出土，天孽消滅，景雲出遊，［事具祥瑞部。］","sortOrder":195},
  {"id":"s_work_nvlt_1_196","chapterId":"ch_work_nvlt_1","text":"《史記》曰：若煙非煙，若雲非雲，鬱鬱紛紛，萧索輪囷，是謂卿雲，［事具祥瑞部。］","sortOrder":196},
  {"id":"s_work_nvlt_1_197","chapterId":"ch_work_nvlt_1","text":"《漢書》曰：高祖在碭山，上常有雲氣。","sortOrder":197},
  {"id":"s_work_nvlt_1_198","chapterId":"ch_work_nvlt_1","text":"又曰：武帝封禪，晝有白雲入封中，［事具祥瑞部。］","sortOrder":198},
  {"id":"s_work_nvlt_1_199","chapterId":"ch_work_nvlt_1","text":"《漢武帝故事》曰：上禪肅然，白雲為蓋。","sortOrder":199},
  {"id":"s_work_nvlt_1_200","chapterId":"ch_work_nvlt_1","text":"又曰：宣帝祠甘泉，紫雲從西北來，散於殿前，［事具祥瑞部。］","sortOrder":200},
  {"id":"s_work_nvlt_1_201","chapterId":"ch_work_nvlt_1","text":"《呂氏春秋》曰：山雲草莽，水雲魚鱗，旱雲煙火，雨雲水氣，無不比類其所生以示人。","sortOrder":201},
  {"id":"s_work_nvlt_1_202","chapterId":"ch_work_nvlt_1","text":"孫氏《瑞應圖》曰：景雲者，太平之應也，一曰：非氣非煙，五色紛缊，謂之慶雲，［事具祥瑞部。］","sortOrder":202},
  {"id":"s_work_nvlt_1_203","chapterId":"ch_work_nvlt_1","text":"《魏志》曰：文帝生於沛國谯郡，時有雲氣青色，而圓如車蓋，當其上終日，望氣者以為至貴之證，非人臣之氣。","sortOrder":203},
  {"id":"s_work_nvlt_1_204","chapterId":"ch_work_nvlt_1","text":"《莊子》曰：廣成子謂黃帝曰：汝治天下，雲氣不待簇［冯校本作族。］而雨。","sortOrder":204},
  {"id":"s_work_nvlt_1_205","chapterId":"ch_work_nvlt_1","text":"又曰：華封人謂尧曰：夫聖人鶉居而鷇食，天下有道，與物皆昌，乘彼白雲，至於帝乡，［事具人部聖篇。］","sortOrder":205},
  {"id":"s_work_nvlt_1_206","chapterId":"ch_work_nvlt_1","text":"《孟子》曰：油然作雲，沛然下雨。","sortOrder":206},
  {"id":"s_work_nvlt_1_207","chapterId":"ch_work_nvlt_1","text":"《帝王世紀》曰：尧母慶都，生而神異，常有黃雲覆其上，［事具帝王部尧篇。］","sortOrder":207},
  {"id":"s_work_nvlt_1_208","chapterId":"ch_work_nvlt_1","text":"《搜神記》曰：蓟子訓到洛，見公卿數十處，後數十處皆有雲起，［事具神仙部。］","sortOrder":208},
  {"id":"s_work_nvlt_1_209","chapterId":"ch_work_nvlt_1","text":"《兵書》曰：韓雲如布，趙雲如牛，楚雲如日，宋雲如車，魯雲如馬，衛雲如犬，周雲如輪，秦雲如行人，魏雲如鼠，齊雲如絳衣，越雲如龍，蜀雲如囷。","sortOrder":209},
  {"id":"s_work_nvlt_1_210","chapterId":"ch_work_nvlt_1","text":"《楚辭》曰：雲霏霏而承宇。","sortOrder":210},
  {"id":"s_work_nvlt_1_211","chapterId":"ch_work_nvlt_1","text":"又曰：青雲衣兮白霓裳。","sortOrder":211},
  {"id":"s_work_nvlt_1_212","chapterId":"ch_work_nvlt_1","text":"又曰：冠青雲之崔嵬。","sortOrder":212},
  {"id":"s_work_nvlt_1_213","chapterId":"ch_work_nvlt_1","text":"【詩】魏文帝浮雲詩曰：西北有浮雲，亭亭如車蓋，惜哉時不遇，忽與飄風會，吹我東南行，行行至吳會。","sortOrder":213},
  {"id":"s_work_nvlt_1_214","chapterId":"ch_work_nvlt_1","text":"魏劉楨詩曰：玄雲起高嶽，終朝弥八方。","sortOrder":214},
  {"id":"s_work_nvlt_1_215","chapterId":"ch_work_nvlt_1","text":"晉傅玄詩曰：白雲翩翩翔天庭，流景仿佛非君形，白雲飄飄，舍我高翔，青雲徘徊，為我愁腸。","sortOrder":215},
  {"id":"s_work_nvlt_1_216","chapterId":"ch_work_nvlt_1","text":"梁簡文帝詠雲詩曰：浮雲舒五色，馬腦映霜天，玉葉散秋影，金風飄紫煙。","sortOrder":216},
  {"id":"s_work_nvlt_1_217","chapterId":"ch_work_nvlt_1","text":"梁沈約和王中書白雲詩曰：白雲自帝乡，氛氲屢回没，蔽虧崑山树，含吐瑤台月，秋風西北起，飄我過城闕，城闕已參差，白雲复離離，皎絜在天漢，倒影入華池，將過丹丘野，時至碧林垂，九重迎飛燕，萬里送翔螭，梁吳均詠雲詩曰：飄飄上碧虛，藹藹隱青林，氛氲如有意，萦鬱詎無心。","sortOrder":217},
  {"id":"s_work_nvlt_1_218","chapterId":"ch_work_nvlt_1","text":"又詠雲詩曰：白雲蒼梧來，過拂章華台，逢河散复卷，經風合且开。","sortOrder":218},
  {"id":"s_work_nvlt_1_219","chapterId":"ch_work_nvlt_1","text":"【賦】楚荀况雲賦曰：有物於此，居則同靜，致下則動，其高以鉅，圓者中規，方者中矩，大齊天地，德厚尧禹，精微於毫毛，充盈於天宇，冬日作寒，夏日作暑。","sortOrder":219},
  {"id":"s_work_nvlt_1_220","chapterId":"ch_work_nvlt_1","text":"晉陆機浮雲賦曰：有輕虛之艳象，無實體之真形，原厥本初，浮沉混併，六律籥應，八風時邁，玄陰觸石，甘泽雱霈，势不崇朝，露彼無外，若層台高觀，重樓叠閣，或如鐘首之鬱律，乍似寒門之寥廓，金柯分，玉葉散，绿翘明，巖英煥，鸞翔鳳翥，鸿驚鶴奋，鯨鲵溯波，鲛鱷冲遁，朱絲亂紀，羅袿失領，飛仙凌虛，隨風遊騁，有若芙蓉群披，蕣華惣會，車渠繞理，馬腦縟文。","sortOrder":220},
  {"id":"s_work_nvlt_1_221","chapterId":"ch_work_nvlt_1","text":"又白雲賦曰：摅神景於八幽，合洪化乎煙煴，充宇宙以播象，协元氣而齊勋，發憤靈石，擢性洪流，興曜曾泉，升跡融丘，盈八紘以餘憤，雖弥天其未泄，豈假期於遷晷，邁崇朝而倏忽，紅蕊發而菡萏，金翘援而含葩，神收鬼化，弼性违序，鳥殊類而比栖，獸異跡而同處，蛟引翳而併潛，龍攀鸿而双舉，鸞舞角以軒罢，鷙企翮而延佇，長城曲蜿，采閣相扶，耸瑤台之截嶭，構琼闼之離娄，雄虹矯而垂天，翠鳥軒而扶日。","sortOrder":221},
  {"id":"s_work_nvlt_1_222","chapterId":"ch_work_nvlt_1","text":"晉成公綏雲賦曰：於是玄氣仰散，歸雲四旋，冰消瓦離，弈弈翩翩，去則滅軌以無跡，來則幽闇以杳冥，舒則弥纶覆四海，卷則消液入無形，或狎獵鱗次，參差交错，上捷業以梁倚，下壘峗而相薄，状崴嵬其不安，吁可畏而欲落，或粲烂綺藻，若畫若規，繁縟成文，一績一離，［績，《初學記》一作續。］或繡文錦章，依微要妙，綿邈凌虛，輕翔浮漂。","sortOrder":222},
  {"id":"s_work_nvlt_1_223","chapterId":"ch_work_nvlt_1","text":"晉楊乂［原訛入，據冯校本改。］雲賦曰：天地定位，淳和肇分，刚柔初降，陰陽煙煴，於是山泽通氣，華岱興雲，則縹緲翩綿，鬱若升煙，蹇槃萦以詰屈兮，若虬龍之蟠蜿，嶷岐岐以嶽立兮，状有似乎列仙，東西絡繹，南北油裔，隨風徘徊，流行菴藹，豁兮仰披，杳兮四會，凝寒冰於朱夏，飛素雪於玄冥，洒膏液於天漢，騰鸿泉於泰清，乾坤以之交泰，品物以之流形，江海以之深滿，川穀以之丰盈，毛羽以之光泽，草木以之葩榮，萌芽以之挺殖，苗秀以之積成，始於觸石而出，膚寸而征，終於霑濡六合，浸润群生，荡涤尘秽，含吐嘉祥，施畅凯風，惠加春陽，擬神化於後土，與三曜兮齊光。","sortOrder":223},
  {"id":"s_work_nvlt_1_224","chapterId":"ch_work_nvlt_1","text":"【贊】魏陳王曹植吹雲贊曰：天地变化，是生神物，吹雲吐润，浮氣蓊鬱。","sortOrder":224},
  {"id":"s_work_nvlt_1_226","chapterId":"ch_work_nvlt_1","text":"《爾雅》曰：四氣和為通正，謂之景風，南風謂之凯風，東風謂之穀風，北風謂之涼風，西風謂之泰風。","sortOrder":226},
  {"id":"s_work_nvlt_1_227","chapterId":"ch_work_nvlt_1","text":"《尚書》曰：休徵，曰聖，時風若。［若，順也，君能通理，則曰風順時也。］","sortOrder":227},
  {"id":"s_work_nvlt_1_228","chapterId":"ch_work_nvlt_1","text":"又曰：周公居東二年，天大風，禾盡偃，大木斯拔，王啟金縢之書，迎周公，天乃返風，禾盡起。","sortOrder":228},
  {"id":"s_work_nvlt_1_229","chapterId":"ch_work_nvlt_1","text":"《左氏傳》曰：六鶂退飛過宋都，風也。","sortOrder":229},
  {"id":"s_work_nvlt_1_230","chapterId":"ch_work_nvlt_1","text":"《老子》曰：飄風不終朝，《毛詩》曰：習習穀風，以陰以雨。","sortOrder":230},
  {"id":"s_work_nvlt_1_231","chapterId":"ch_work_nvlt_1","text":"又曰：終風且曀，［終日而風為終風。］","sortOrder":231},
  {"id":"s_work_nvlt_1_232","chapterId":"ch_work_nvlt_1","text":"又曰：凯風自南，吹彼棘心，［南風謂之凯風。］","sortOrder":232},
  {"id":"s_work_nvlt_1_233","chapterId":"ch_work_nvlt_1","text":"又曰：冬日烈烈，飄風發發。","sortOrder":233},
  {"id":"s_work_nvlt_1_234","chapterId":"ch_work_nvlt_1","text":"《禮記》曰：立冬之日，東風解冻。","sortOrder":234},
  {"id":"s_work_nvlt_1_235","chapterId":"ch_work_nvlt_1","text":"《禮稽命徵》曰：出號令，合民心，則祥風至。","sortOrder":235},
  {"id":"s_work_nvlt_1_236","chapterId":"ch_work_nvlt_1","text":"《孝經援神契》曰：德至八方，則祥風至。","sortOrder":236},
  {"id":"s_work_nvlt_1_237","chapterId":"ch_work_nvlt_1","text":"《尚書大傳》曰：舜將禪禹，八風脩通。","sortOrder":237},
  {"id":"s_work_nvlt_1_238","chapterId":"ch_work_nvlt_1","text":"又曰：成王時，越裳重譯而來朝，曰：久矣天之無烈風迅雨，意中國有聖人乎。","sortOrder":238},
  {"id":"s_work_nvlt_1_239","chapterId":"ch_work_nvlt_1","text":"《莊子》曰：列子御風而行，泠然，旬有五日而後反。","sortOrder":239},
  {"id":"s_work_nvlt_1_240","chapterId":"ch_work_nvlt_1","text":"《國語》曰：海鳥爰居，止於魯國東門之外，三日，展禽曰：今其有灾乎，是歲也，海多大風。","sortOrder":240},
  {"id":"s_work_nvlt_1_241","chapterId":"ch_work_nvlt_1","text":"《荆州星占》曰：箕星一名舌，動則大風至。","sortOrder":241},
  {"id":"s_work_nvlt_1_242","chapterId":"ch_work_nvlt_1","text":"《風俗通》曰：飛廉，風伯也，風師，箕星也。","sortOrder":242},
  {"id":"s_work_nvlt_1_243","chapterId":"ch_work_nvlt_1","text":"《管公明傳》曰：公明言树上已有少女微風，其雨應至矣，［事具雨部。］","sortOrder":243},
  {"id":"s_work_nvlt_1_244","chapterId":"ch_work_nvlt_1","text":"周生《列子》曰：夫獦葉之風，不應八節。","sortOrder":244},
  {"id":"s_work_nvlt_1_245","chapterId":"ch_work_nvlt_1","text":"《風土記》曰：六月則有東南長風，俗名黃雀，長風時，海魚变為黃雀，因為名也。","sortOrder":245},
  {"id":"s_work_nvlt_1_246","chapterId":"ch_work_nvlt_1","text":"括地圖曰：奇肱氏能為飛車，從風遠行，湯時，西風吹奇肱車至於豫州，湯破其車，不以示民，十年，西風至，乃复使作車，遣歸，去玉門四萬里。","sortOrder":246},
  {"id":"s_work_nvlt_1_247","chapterId":"ch_work_nvlt_1","text":"《論衡》曰：儒者論太平瑞應，皆言五日一風，風不鳴條。","sortOrder":247},
  {"id":"s_work_nvlt_1_248","chapterId":"ch_work_nvlt_1","text":"《述征記》曰：長安宮南有靈台，有相風銅乌，或雲，此乌遇千里風，乃動。","sortOrder":248},
  {"id":"s_work_nvlt_1_249","chapterId":"ch_work_nvlt_1","text":"《神仙傳》曰：葛玄行，遇神廟，乘車不下，須臾，有大風逐玄，埃尘涨天，玄大怒曰：小邪敢爾，即舉手指風，風便止。","sortOrder":249},
  {"id":"s_work_nvlt_1_250","chapterId":"ch_work_nvlt_1","text":"劉欣期《交州記》曰：風母，出九德縣，似猿，見人若慚，屈頸，打殺，得風還活。","sortOrder":250},
  {"id":"s_work_nvlt_1_251","chapterId":"ch_work_nvlt_1","text":"《風俗通》曰：風或清明來久長，不搖树本枝葉，離地二三丈者，此有龍德在其下，風或清，不及地二三尺者，此君子之風。","sortOrder":251},
  {"id":"s_work_nvlt_1_252","chapterId":"ch_work_nvlt_1","text":"《楚辭》曰：光風轉蕙汎崇蘭，［事具草部。］","sortOrder":252},
  {"id":"s_work_nvlt_1_253","chapterId":"ch_work_nvlt_1","text":"又曰：裊裊兮秋風，洞庭波兮木葉下。","sortOrder":253},
  {"id":"s_work_nvlt_1_254","chapterId":"ch_work_nvlt_1","text":"《十洲記》曰：炎州，在南海中，上有風生獸，似豹，青色，状如狸，以鐵椎鍛其頭，數十下乃死，張其口向風，須臾而起。","sortOrder":254},
  {"id":"s_work_nvlt_1_255","chapterId":"ch_work_nvlt_1","text":"【詩】晉庾闡江都遇風詩曰：天吳踴靈壑，將駕奔冥霄，飛廉振折木，流景登扶搖，洪川佇宿浪，躍水迎晨潮，仰眄蹙玄雲，俯聽聒悲飆。","sortOrder":255},
  {"id":"s_work_nvlt_1_256","chapterId":"ch_work_nvlt_1","text":"梁簡文帝詠風詩曰：飄飖散芳势，汎漾下蓬萊，傳涼入鏤槛，發氣滿瑤台，委禾周邦偃，飛鶂宋都回，亟搖故葉落，屢荡新花开，暫舞驚凫去，時送蕊香來，已拂巫山雨，何用卷寒灰。","sortOrder":256},
  {"id":"s_work_nvlt_1_257","chapterId":"ch_work_nvlt_1","text":"梁孝元帝詠風詩曰：樓上起朝妆，風花下砌傍，入鏡先飄粉，翻衫好染香，度舞飛長袖，傳歌共繞梁，欲因吹少女，還捋拂大王。","sortOrder":257},
  {"id":"s_work_nvlt_1_258","chapterId":"ch_work_nvlt_1","text":"梁劉孝綽詠風詩曰：裊裊秋聲，習習春吹，鳴茲玉树，煥此銅池，羅帷自舉，袖衿乃披，慚非楚侍，濫賦雄雌。","sortOrder":258},
  {"id":"s_work_nvlt_1_259","chapterId":"ch_work_nvlt_1","text":"梁王台卿詠風詩曰：侵望不可識，去來非有情，乍見珠帘卷，時覺洞房清，暫拂蘭池上，掆淡玉尘生，一辨雄雌異，還惡庶人輕。","sortOrder":259},
  {"id":"s_work_nvlt_1_260","chapterId":"ch_work_nvlt_1","text":"梁何遜詠風詩曰：可聞不可見，能重复能輕，鏡前飄落粉，琴上响餘聲。","sortOrder":260},
  {"id":"s_work_nvlt_1_261","chapterId":"ch_work_nvlt_1","text":"梁庾肩吾詠風詩曰：宋地鶂飛初，湘川燕起餘，扫壇聊動竹，吹薤欲成書，蒼梧洞猶在，合浦树應疏，陽乌一轉翅，千里定非虛。","sortOrder":261},
  {"id":"s_work_nvlt_1_262","chapterId":"ch_work_nvlt_1","text":"梁贺文摽詠春風詩曰：排帘動輕幔，汎水拂垂楊，本持飄落蕊，翻送舞衣香。","sortOrder":262},
  {"id":"s_work_nvlt_1_263","chapterId":"ch_work_nvlt_1","text":"陳祖孫登詠風詩曰：飖颺楚王宮，徘徊繞竹丛，帶葉俱吟树，將花共舞空，飄香双袖里，亂曲五絃中，试上高台聽，悲响定無窮。","sortOrder":263},
  {"id":"s_work_nvlt_1_264","chapterId":"ch_work_nvlt_1","text":"【賦】楚宋玉風賦曰：楚襄王遊蘭台之宮，宋玉景差侍，有風飒然而至，王乃披襟而當之，曰：快哉此風，寡人與庶人共者耶，宋玉對曰：夫風生於地，起於青蘋之末，侵淫谿穀，盛怒於土囊之口，緣於太山之阿，舞於松柏之下，故其清涼雄風，則飄舉升降，乘凌高城，入於深宮，徘徊於桂椒之間，翱翔於激水之上，獵蕙草，離秦衡，槩新夷，被稊楊，北上玉堂，經於洞房，故其風清清泠泠，愈病析酲，發明耳目，寧體便人，此所謂大王之雄風也，夫塕然起於窮巷之間，動沙塸，吹死灰，此所謂庶人之雌風也。","sortOrder":264},
  {"id":"s_work_nvlt_1_265","chapterId":"ch_work_nvlt_1","text":"後漢趙壹迅風賦曰：惟巽卦之為體，吐坤［原作神，據冯校本改。］氣而成風，纖微無所不入，廣大無所不充，經營八荒之外，宛轉毫毛之中，察本莫見其始，揆末莫睹其終，啾啾颼颼，吟嘯相求，阿那徘徊，聲若歌謳，摶之不可得，系之不可留。","sortOrder":265},
  {"id":"s_work_nvlt_1_266","chapterId":"ch_work_nvlt_1","text":"晉李充風賦曰：尋之不見其終，迎之莫知其來，四方為之易位，八維為之輪回，遊聚則天地為一，消散則六合洞开。","sortOrder":266},
  {"id":"s_work_nvlt_1_267","chapterId":"ch_work_nvlt_1","text":"晉陆冲風賦曰：爰太玄之遐始，惟浮沉之剖分，詳乾坤之至德，莫風氣之獨尊。配無形於大象，化萬品於煙煴，釋凝润於黃壤，降霈泽於蒼元，生無常域，潛無定栖，擢昧聚發，尋虛散歸，肆六合以騁邁，括毫毛而徘徊，引沉性於未萌，挫登形於已就，宣刚柔之流化，导四氣之靈候，若乃祝融司節，炎精赫弈，斂朱唇而長嘯，承音响而來薄，猥熻熠以盈扉，洌纏綿以結幕，九域荡搖，區宇揮霍。","sortOrder":267},
  {"id":"s_work_nvlt_1_268","chapterId":"ch_work_nvlt_1","text":"晉湛方生風賦曰：有氣曰風，出自幽冥，萧然而起，寂爾而停，雖宇宙之宏遠，倏俄頃而屢經，同神功於不疾，等至道於無情，胡馬感而增思，風母殒而复生，啟惨冬之潛蟄，達青春之勾萌，因嚴霜以厲威，順和泽以开榮，故君德喻其靡草，風人假以為名，及其猛势將奋，屯雲結陰，洪氣鬱彿，殷雷發音，勃然鼓作，拂高陵深，天無澄景，嶺無停林，六鶂為之退飛，萬竅為之哀吟，亦有飄泠之氣，不疾不徐，飗飗微扇，亹亹清舒，王乔以之控鵠，列子以之乘虛，若乃春惠始和，重褐初釋，遨步蘭皋，遊眄平陌，响詠空嶺，朗吟竹柏，穆开林以流惠。疏神襟以清涤，軒濠梁之逸興，畅方外之冥適。","sortOrder":268},
  {"id":"s_work_nvlt_1_269","chapterId":"ch_work_nvlt_1","text":"晉江逌風賦曰：惟浑成之既載兮，統天地以資始，網宇宙以結羅兮，洞萬形而通紀，莫適柔健，靡测陰陽，於音罔徵，在體無方，假姿眾象，借韻宮商，若飔厲狂震，觸物怒號，卷扬江海，回拔陵崤，巨鶂迸慑以退翼，爰居丧宿而遐逃。","sortOrder":269},
  {"id":"s_work_nvlt_1_270","chapterId":"ch_work_nvlt_1","text":"晉王凝之風賦曰：起玄朔之重雲，驅東極之洪涛，越四溟而蓬勃，經五嶺而萧條，其鼓水也，無川不涉，靡流不往，溟海天回，江湖雲荡。","sortOrder":270},
  {"id":"s_work_nvlt_1_271","chapterId":"ch_work_nvlt_1","text":"齊王融擬風賦曰：奄兮日采之既移，忽兮群景之將馳，靡輕筠之碧業，泛曾松之翠枝，總高羽而萧瑟，韻珠露之參差，此烈士之英風，長寥亮其如斯。","sortOrder":271},
  {"id":"s_work_nvlt_1_272","chapterId":"ch_work_nvlt_1","text":"齊謝朓擬風賦曰：开翠帷之影藹，响行珮之輕鳴，扬淮南之妙舞，發齊後之妍聲，子雲寂寞，叔夜高張，煙霞洞色，苓荑結芳，斯則幽人之風也，梁沈約擬風賦曰：若夫搖玉树，响金扉，拂九層之羽蓋，轉八鳳之珠旂，時卷瑤台翠帳，乍動佚女輕衣，此蓋羽客之仙風也。","sortOrder":272},
  {"id":"s_work_nvlt_1_273","chapterId":"ch_work_nvlt_1","text":"又八詠曰：臨春風，春風起春树，遊絲暧如網，落花雰似霧，先汎天津池。還過細柳枝，蝶逢飛搖漾，燕值羽參差，扬桂旆，動芝蓋，开燕裾，吹趙帶，趙帶飛參差，燕裾合复離，容儀已照灼，春風复回薄，氛氲桃李花，青跗含素萼，既為風所开，复為風所落，搖绿蒂，扤紫茎，舞春雪，雜流鶯，迎行雨於高唐，送歸鸿於碣石，拂明鏡之冬尘，解羅衣之秋襞，既铿锵以動珮。又氛氲而流射，始搖荡以入閨，終徘徊而緣隙，明珠帘於繡戶，散芳尘於綺席，佳人不在茲，春風為誰惜。","sortOrder":273},
  {"id":"s_work_nvlt_1_274","chapterId":"ch_work_nvlt_1","text":"《藝文類聚》　唐·欧陽詢","sortOrder":274},
  {"id":"s_work_nvlt_2_1","chapterId":"ch_work_nvlt_2","text":"卷二天部下據明本補","sortOrder":1},
  {"id":"s_work_nvlt_2_2","chapterId":"ch_work_nvlt_2","text":"○雪雨霁雷電霧虹","sortOrder":2},
  {"id":"s_work_nvlt_2_4","chapterId":"ch_work_nvlt_2","text":"《毛詩》曰：北風其涼，雨雪其雱。","sortOrder":4},
  {"id":"s_work_nvlt_2_5","chapterId":"ch_work_nvlt_2","text":"又曰：今我來斯，雨雪霏霏。","sortOrder":5},
  {"id":"s_work_nvlt_2_6","chapterId":"ch_work_nvlt_2","text":"又曰：上天同雲，雨雪雰雰。","sortOrder":6},
  {"id":"s_work_nvlt_2_7","chapterId":"ch_work_nvlt_2","text":"又曰：雨雪瀌々，見晛日消，［晛，日氣也。］","sortOrder":7},
  {"id":"s_work_nvlt_2_8","chapterId":"ch_work_nvlt_2","text":"《左氏傳》曰：楚子次於乾谿，雨雪，王皮冠，秦复陶，［秦所遺羽衣也。］翠被豹舄，執鞭以出。","sortOrder":8},
  {"id":"s_work_nvlt_2_9","chapterId":"ch_work_nvlt_2","text":"《山海經》曰：由首之山，小威之山，空桑之山，併冬夏有雪。","sortOrder":9},
  {"id":"s_work_nvlt_2_10","chapterId":"ch_work_nvlt_2","text":"《金匮》曰：武王伐紂，都洛邑未成，陰寒，大雪深丈餘，甲子旦，不知何五大夫，乘馬車，從兩騎，止門外，王使太師尚父謝賓，幸臨之，尚父使人持一器粥出，進五車兩騎，軍［《太平御覽》十二作畢。］使者具以告，尚父曰：五車兩騎，四海之神與河伯雨師耳，尚父各以其名進之，五神皆驚，相视而叹。","sortOrder":10},
  {"id":"s_work_nvlt_2_11","chapterId":"ch_work_nvlt_2","text":"《穆天子傳》曰：雨雪，天子獵於钘山之西阿。","sortOrder":11},
  {"id":"s_work_nvlt_2_12","chapterId":"ch_work_nvlt_2","text":"又曰：北風雨雪，天子遊黃台之丘，骛於苹泽，日中大寒，北風雨雪，有冻人，天子作黃竹詩，［事具文部。］","sortOrder":12},
  {"id":"s_work_nvlt_2_13","chapterId":"ch_work_nvlt_2","text":"《晏子春秋》曰：景公時，雨雪三日，公被狐白之裘，晏子入，公曰：怪哉，雨雪三日不寒，《晏子》曰：古之賢君，飽而知人飢，溫而知人寒，公曰：善，出裘發粟，以與飢寒者。","sortOrder":13},
  {"id":"s_work_nvlt_2_14","chapterId":"ch_work_nvlt_2","text":"王孫子曰：昔衛君重裘累茵而坐，見路有負薪而哭之者，問曰：何故也，對曰：雪下衣薄，是以哭之，於是衛君懼，見於顏色，曰：為君而不知民，孰以我為君，於是开府金，出仓粟，以赈貧窮。","sortOrder":14},
  {"id":"s_work_nvlt_2_15","chapterId":"ch_work_nvlt_2","text":"《史記》曰：東郭先生，衣弊，履不完，行雪中，履有上無下，足盡踐地，［事具人部。］","sortOrder":15},
  {"id":"s_work_nvlt_2_16","chapterId":"ch_work_nvlt_2","text":"《漢書·蘇武傳》曰：单於幽武，置大窖中，絕不與飲食，天雨雪，武臥齧雪，與旃毛併咽之，數日不死，匈奴以為神，《漢武內傳》曰：西王母雲，仙之上藥，有玄霜絳雪。","sortOrder":16},
  {"id":"s_work_nvlt_2_17","chapterId":"ch_work_nvlt_2","text":"《琴操》曰：曾子耕太山之下，天雨雪，冻，旬日不得歸，思其父母，作梁山歌。","sortOrder":17},
  {"id":"s_work_nvlt_2_18","chapterId":"ch_work_nvlt_2","text":"《論衡》曰：雲霧，雨之徵也，夏則為露，冬則為霜，溫則為雨，寒則為雪，雨露冻凝者，皆由地發，不從天降。","sortOrder":18},
  {"id":"s_work_nvlt_2_19","chapterId":"ch_work_nvlt_2","text":"《孟子》曰：滕文公卒，葬有日矣，天大雨雪，甚，至牛目，群臣請弛期，太子不許，惠子諫曰：昔王季葬渦山之尾，栾水齧其墓，見棺前和，文王曰：先君欲見群臣百姓矣，乃出為帳，三日後葬，今先王欲小留而撫社稷，故使雪甚，弛期而更為，曰：此文王之義也。","sortOrder":19},
  {"id":"s_work_nvlt_2_20","chapterId":"ch_work_nvlt_2","text":"《氾勝之書》曰：取雪汁以渍原蠶矢，渍之五六日，釋，因摩之，雜穀种，使稼能早，故謂雪五穀之精也。","sortOrder":20},
  {"id":"s_work_nvlt_2_21","chapterId":"ch_work_nvlt_2","text":"秦子曰：今欲馳光日下，顯白雪中，不可得已。","sortOrder":21},
  {"id":"s_work_nvlt_2_22","chapterId":"ch_work_nvlt_2","text":"晉諸公贊曰：東羸王滕［本書八十三引異苑作東瀛王騰，《太平御覽》十二引晉書作東瀛公騰。］於常山屯營，時大積雪，常山門前方數丈融液，滕怪而掘之，得玉馬，高尺餘。","sortOrder":22},
  {"id":"s_work_nvlt_2_23","chapterId":"ch_work_nvlt_2","text":"《錄異傳》曰：漢時大雪，積地丈餘，洛陽令身出按行，見民家皆除雪出，至袁安門，無有路，謂安已死，令人除雪，入戶，見安僵臥，問何以不出，安曰：大雪人皆饿，不宜幹人，令以為賢，舉為孝廉。","sortOrder":23},
  {"id":"s_work_nvlt_2_24","chapterId":"ch_work_nvlt_2","text":"皇甫謐《高士傳》曰：焦先［原訛光，據本書六十四引改，下同。］野火燒其庐，先因露寢，遭大雪至，先袒臥不移，人以為死，就视如故，［事具居處部庐篇。］","sortOrder":24},
  {"id":"s_work_nvlt_2_25","chapterId":"ch_work_nvlt_2","text":"《世說》曰：謝太傅寒雪日內集，與兒女講論文義，俄而雪骤，公欣然曰：白雪紛紛何所似，兄子胡兒曰：散鹽空中差可擬，兄女曰：未若柳絮因風起。","sortOrder":25},
  {"id":"s_work_nvlt_2_26","chapterId":"ch_work_nvlt_2","text":"《語林》曰：王子猷居山陰，大雪夜，眠覺，开室酌酒，四望皎然，因起徬徨。詠左思招隱詩，忽憶戴安道，時戴在剡溪，即便夜乘輕舩就戴，經宿方至，既造門，不前便返，人問其故，王曰：吾本乘興而行，興盡而返，何必見戴。","sortOrder":26},
  {"id":"s_work_nvlt_2_27","chapterId":"ch_work_nvlt_2","text":"《楚辭·招魂》曰：魂兮來歸，北方不可以止，增冰峨峨，飛雪千里。","sortOrder":27},
  {"id":"s_work_nvlt_2_28","chapterId":"ch_work_nvlt_2","text":"又曰：霰雪紛其無垠。","sortOrder":28},
  {"id":"s_work_nvlt_2_29","chapterId":"ch_work_nvlt_2","text":"又曰：霰雪霏霏，糅其增加。","sortOrder":29},
  {"id":"s_work_nvlt_2_30","chapterId":"ch_work_nvlt_2","text":"又曰：霰雪紛紛而薄木。","sortOrder":30},
  {"id":"s_work_nvlt_2_31","chapterId":"ch_work_nvlt_2","text":"又曰：桂棹兮蘭枻，斫冰兮積雪。","sortOrder":31},
  {"id":"s_work_nvlt_2_32","chapterId":"ch_work_nvlt_2","text":"《釋名》曰：雪，綏也，水下遇寒而凝，綏綏然下也。","sortOrder":32},
  {"id":"s_work_nvlt_2_33","chapterId":"ch_work_nvlt_2","text":"《韓詩外傳》曰：凡草木花多五出，雪花獨六出，雪花曰霙，雪雲曰同雲。","sortOrder":33},
  {"id":"s_work_nvlt_2_34","chapterId":"ch_work_nvlt_2","text":"《西京雜記》曰：太平之代，雪不封條，凌弭毒害而已，自上而下曰雨雪，［此七字，《初學記》二引作詩傳，當另作一條。］","sortOrder":34},
  {"id":"s_work_nvlt_2_35","chapterId":"ch_work_nvlt_2","text":"《左傳》曰：平地尺為大雪，雪有七尺雪，［此五字亦見《初學記》二，引春秋考異郵為註，疑本為古左氏傳說，與公羊說同。］","sortOrder":35},
  {"id":"s_work_nvlt_2_36","chapterId":"ch_work_nvlt_2","text":"崔鸿《北涼錄》曰：先酒泉南有銅鉇。［《初學記》二，《太平御覽》二作扆，出，言虜犯者大雨雪，沮渠蒙遜遣工取之，得銅萬斤。］","sortOrder":36},
  {"id":"s_work_nvlt_2_37","chapterId":"ch_work_nvlt_2","text":"《毛詩》曰：蜉蝣掘閱，麻衣如雪。","sortOrder":37},
  {"id":"s_work_nvlt_2_38","chapterId":"ch_work_nvlt_2","text":"班婕妤《怨歌行》曰：新裂齊紈素，皎絜如霜雪。","sortOrder":38},
  {"id":"s_work_nvlt_2_39","chapterId":"ch_work_nvlt_2","text":"孫康家貧，常映雪讀書，清介，交遊不雜。［本條《初學記》二，御覽十二引作宋齊語，此脱書名。］","sortOrder":39},
  {"id":"s_work_nvlt_2_40","chapterId":"ch_work_nvlt_2","text":"宋玉曰：陽春白雪，國中屬和者，不過十人。","sortOrder":40},
  {"id":"s_work_nvlt_2_41","chapterId":"ch_work_nvlt_2","text":"《莊子》曰：藐姑射山，有神人居焉，肌膚若冰雪。","sortOrder":41},
  {"id":"s_work_nvlt_2_42","chapterId":"ch_work_nvlt_2","text":"《洛神賦》曰：飄飖兮若流風之回雪。","sortOrder":42},
  {"id":"s_work_nvlt_2_43","chapterId":"ch_work_nvlt_2","text":"【詩】宋鮑照詠雪詩曰：胡風吹朔雪，千里度龍山，集君瑤台里，飛舞兩楹前。","sortOrder":43},
  {"id":"s_work_nvlt_2_44","chapterId":"ch_work_nvlt_2","text":"齊虞羲望雪詩曰：歲杪雲晝昏，玄池冰夜結，遠風金河起，吹我玉山雪。","sortOrder":44},
  {"id":"s_work_nvlt_2_45","chapterId":"ch_work_nvlt_2","text":"梁簡文帝雪朝詩曰：同雲凝暮序，嚴陰屯廣隰，落梅飛四註，翻霙舞三袭，實斷望如連，恒分似相及，已觀池影亂，复视帘珠濕。","sortOrder":45},
  {"id":"s_work_nvlt_2_46","chapterId":"ch_work_nvlt_2","text":"又詠雪詩曰：晚霰飛銀砾，浮雲暗未开，入池消不積，因風隨复來，思婦流黃素，溫姬玉鏡台，看花言可折，定自非春梅。","sortOrder":46},
  {"id":"s_work_nvlt_2_47","chapterId":"ch_work_nvlt_2","text":"又詠雪顛倒使韻曰：鹽飛亂蝶舞，花落飄粉奁。","sortOrder":47},
  {"id":"s_work_nvlt_2_48","chapterId":"ch_work_nvlt_2","text":"梁沈約詠餘雪詩曰：陰庭覆素芷，南階褰绿葹，玉台新落構，青山已半虧。","sortOrder":48},
  {"id":"s_work_nvlt_2_49","chapterId":"ch_work_nvlt_2","text":"梁任昉同謝朏花雪詩曰：土膏候年動，積雪表辰暮，散葩似浮玉，飛英若總素，東序皆白珩，西氵邕盡翔鷺，山經陋蜜榮，骚人貶琼树。","sortOrder":49},
  {"id":"s_work_nvlt_2_50","chapterId":"ch_work_nvlt_2","text":"梁丘遲望雪詩曰：氛氲發紫漢，雜沓被朱城，倏忽銀台構，俄頃玉树生，綿綿九軌合，昭昭四區明。","sortOrder":50},
  {"id":"s_work_nvlt_2_51","chapterId":"ch_work_nvlt_2","text":"梁裴子野上朝值雪詩曰：沐雪款千門，櫛風朝萬戶，集霰渝丹黻，流雲飄繡柱，滴瀝垂土膏，阑幹懸石乳。","sortOrder":51},
  {"id":"s_work_nvlt_2_52","chapterId":"ch_work_nvlt_2","text":"又詠雪詩曰：飄飖千里雪，倏忽度龍沙，從雲合且散，因風卷复斜，拂草如連蝶，落树似飛花，若赠離居者，折以代瑤華。","sortOrder":52},
  {"id":"s_work_nvlt_2_53","chapterId":"ch_work_nvlt_2","text":"梁吳均詠雪詩曰：微風搖庭树，細雪下帘隙，萦空如霧轉，凝階似花積，不見楊柳春，徒看桂枝白。","sortOrder":53},
  {"id":"s_work_nvlt_2_54","chapterId":"ch_work_nvlt_2","text":"又詠雪詩曰：雪逐春風來，過集巫山野，澜漫雖可愛，翻扬［原訛陽，據冯校本改。］詎堪把，問君何所思，昔日同心者，坐須風雪霁，相期雒城下。","sortOrder":54},
  {"id":"s_work_nvlt_2_55","chapterId":"ch_work_nvlt_2","text":"梁何遜詠雪詩曰：凝階似月夜，拂树晓疑春，萧散忽如盡，徘徊已复新，若逐微風起，誰言非玉尘。","sortOrder":55},
  {"id":"s_work_nvlt_2_56","chapterId":"ch_work_nvlt_2","text":"梁劉孝綽對雪詩曰：桂華殊皎皎，柳絮亦霏霏，詎比鹹池曲，飄飖千里飛，恥均班女扇，羞洒曹人衣，浮光亂粉壁，積照朗彤闈。","sortOrder":56},
  {"id":"s_work_nvlt_2_57","chapterId":"ch_work_nvlt_2","text":"梁庾肩吾詠花雪詩曰：瑞雪墜尧年，因風入綺錢，飛花洒庭树，凝瑛結井泉，寒光晦八極，同雲暗九天，已飄黃竹路，共慶白渠田。","sortOrder":57},
  {"id":"s_work_nvlt_2_58","chapterId":"ch_work_nvlt_2","text":"陳徐陵詠雪詩曰：琼林玄圃葉，桂树日南華，豈若天庭瑞，輕雪帶風斜，三農喜盈尺，六出舞崇花，明朝闕門外，應見海神車。","sortOrder":58},
  {"id":"s_work_nvlt_2_59","chapterId":"ch_work_nvlt_2","text":"【賦】晉孫楚雪賦曰：尧九載以山栖兮，湯請祷於桑林，罔二聖以濟世兮，孰繁衍以迄今，嗟亢陽之逾時兮，情反侧以寢興，丰隆洒雪，交错翻紛，膏泽偃液，普润中田，肅肅三麥，實獲丰年。","sortOrder":59},
  {"id":"s_work_nvlt_2_60","chapterId":"ch_work_nvlt_2","text":"晉李顒雪賦曰：何時雪之嘉泽，亦應变而俱凝，隨同雲而下降，固霑渥之所興。","sortOrder":60},
  {"id":"s_work_nvlt_2_61","chapterId":"ch_work_nvlt_2","text":"宋謝惠連雪賦曰：歲將暮，時既昏，寒風積，愁雲繁，梁王不悅，遊於兔園，俄而微霰零，密雪下，王乃歌北風於衛詩，詠南山於周雅，相如於是避席而起，逡巡而揖曰：臣聞，雪宮建於東國，雪山峙於西域，岐昌發詠於來思，姬滿申歌於黃竹，曹風以麻衣比色，楚謠以幽蘭俪曲，盈尺則呈瑞於丰年，袤丈則表沴於陰德，連氛累藹，揜日韜霞，霙淅瀝而先集，雪紛糅而遂多，其為状也，散漫交错，氛氲萧索，藹藹浮浮，瀌々奕奕，連翩飛洒，徘徊委積，始緣甍而冒棟，終开帘而入隙，既因方而為珪，亦遇圓而成璧，眄隰則萬頃同縞，瞻山則千巖俱白，於是台如重璧，逵似連璐，庭列瑤階，林挺琼树，若乃積素未虧，白日朝鮮，烂兮若燭龍衔曜照崑山，及其流滴垂冰，緣霤承隅，粲兮若冯夷剖蚌列明珠，亂曰：白羽雖白，质已輕兮，白玉雖白，空守貞兮，未若茲雪，因時興滅，玄陰凝，不昧其絜，太陽曜，不固其節，節豈我名，絜豈我貞，凭雲升降，從風飄零，值物賦象，任地列形，素因遇立，污隨染成，縱心皓然，何慮何營。","sortOrder":61},
  {"id":"s_work_nvlt_2_62","chapterId":"ch_work_nvlt_2","text":"周劉璠雪賦曰：天地否閉，凝而成雪，應乎玄冬之晨，在於冱寒之節，蒼雲暮同，嚴風晓別，散亂徘徊，雰霏皎絜，违朝陽之曜煦，就凌陰之惨冽，混二儀而併色，覆萬有而皆空，既奪朱而成素，實矯異而為同，始飄飖而稍落，遂紛糅而無窮，晓攝光而映净，夜合影而通昽，似北荒之明月，比西崑之阆風。","sortOrder":62},
  {"id":"s_work_nvlt_2_63","chapterId":"ch_work_nvlt_2","text":"宋謝莊雜言詠雪曰：火洲滅，日壑清，龍關沙蒸，河徼雲驚，晷未沉而井閟，宇方霾而海溟，始葐蒀以蕤轉，終徘徊而煙曳，状素鏡之晨光，寫金波之夜晢。","sortOrder":63},
  {"id":"s_work_nvlt_2_64","chapterId":"ch_work_nvlt_2","text":"【贊】晉庾肅之雪贊曰：百籁哀吟，廣莫長揮，霰雨馺洒，皓雪其霏，輕质飄飖，與風回散，望之凝映，浩若天漢，即之皎絜，色逾玉粲。","sortOrder":64},
  {"id":"s_work_nvlt_2_65","chapterId":"ch_work_nvlt_2","text":"晉羊孚雪贊曰：資清以化，乘氣以霏，遇象能鮮，即絜成暉。","sortOrder":65},
  {"id":"s_work_nvlt_2_66","chapterId":"ch_work_nvlt_2","text":"宋謝惠連雪贊曰：氣遍霜繁，年丰雪積，彼厲我和，爾素子白，其德懿矣，玩之庭隙，權陋瑤台，暫踐盈尺。","sortOrder":66},
  {"id":"s_work_nvlt_2_67","chapterId":"ch_work_nvlt_2","text":"梁沈約雪贊曰：火競乃上炎，陰矯亦下润，獨有凝雨姿，貞晼而無殉，排雲寧自高，晞光本非吝，委穀不辭深，因巖豈知峻，絜貌雖同賞，英心共誰振。","sortOrder":67},
  {"id":"s_work_nvlt_2_69","chapterId":"ch_work_nvlt_2","text":"《爾雅》曰：暴雨謂之冻，小雨謂之霡霂，久雨謂之霪，霪謂之霖。","sortOrder":69},
  {"id":"s_work_nvlt_2_70","chapterId":"ch_work_nvlt_2","text":"《管子》曰：春秋祭［《太平御覽》十作發。］五政，一曰：論幼孤，赦有罪，二曰：賦爵列，授祿位，三曰：修溝洫，复亡人，四曰：治封疆，正阡陌，五曰：無殺麑{鹿夭}，無絕華萼，五政苟時，春雨乃來。","sortOrder":70},
  {"id":"s_work_nvlt_2_71","chapterId":"ch_work_nvlt_2","text":"《尸子》曰：神農氏治天下，欲雨則雨，五日為行雨，旬為穀雨，旬五日為時雨，正四時之製，萬物鹹利，故謂之神。","sortOrder":71},
  {"id":"s_work_nvlt_2_72","chapterId":"ch_work_nvlt_2","text":"《東觀漢記》曰：沛獻王辅，善京氏易，永平五年，少雨，上御雲台卦，自以周易林占之，其繇曰：蚁封穴戶，大雨將至，以問辅，辅曰：蹇，艮下坎上，艮為山，坎為水，山出雲為雨，蚁穴居，時［《初學記》二，御覽十作知。］雨將至，故以蚁為興居，［居字《初學記》，御覽無。］","sortOrder":72},
  {"id":"s_work_nvlt_2_73","chapterId":"ch_work_nvlt_2","text":"黃子發相雨［原訛與，據冯校本改。］《書》曰：常戊申日，候日欲入時，日上有觀雲，不問大小，视四方黑者大雨，青者小雨。","sortOrder":73},
  {"id":"s_work_nvlt_2_74","chapterId":"ch_work_nvlt_2","text":"《戰國策》曰：魏文侯與虞人期獵，是日飲酒樂，天雨，文侯曰：雖樂，豈可不一會期哉，乃往，［事具獵部。］","sortOrder":74},
  {"id":"s_work_nvlt_2_75","chapterId":"ch_work_nvlt_2","text":"《楚辭》曰：雷填填兮雨冥冥，令飄風兮先駈，使冻雨兮洒尘。","sortOrder":75},
  {"id":"s_work_nvlt_2_76","chapterId":"ch_work_nvlt_2","text":"《尚書大傳》曰：天之無烈風淫雨，意中國有聖人乎，［淫雨謂之霖。］","sortOrder":76},
  {"id":"s_work_nvlt_2_77","chapterId":"ch_work_nvlt_2","text":"河圖帝通紀曰：雨者，天地之施也。","sortOrder":77},
  {"id":"s_work_nvlt_2_78","chapterId":"ch_work_nvlt_2","text":"《曾子》曰：天地之氣和則雨。","sortOrder":78},
  {"id":"s_work_nvlt_2_79","chapterId":"ch_work_nvlt_2","text":"《山海經》曰：為應龍之状，乃得大雨。","sortOrder":79},
  {"id":"s_work_nvlt_2_80","chapterId":"ch_work_nvlt_2","text":"《尚書·洪范》休徵曰：肅時雨若。［君仁敬則時雨從之。］","sortOrder":80},
  {"id":"s_work_nvlt_2_81","chapterId":"ch_work_nvlt_2","text":"《毛詩》曰：有渰萋萋，興雲祁祁，雨我公田，遂及我私。","sortOrder":81},
  {"id":"s_work_nvlt_2_82","chapterId":"ch_work_nvlt_2","text":"又曰：月離於畢，俾滂沱矣。","sortOrder":82},
  {"id":"s_work_nvlt_2_83","chapterId":"ch_work_nvlt_2","text":"《左氏傳》：衛大旱，卜有事於山川，不吉，甯《莊子》曰：昔周飢，克殷而年丰，今邢無道，諸侯無伯，天其或者欲使衛讨邢乎，從之，師興而雨。","sortOrder":83},
  {"id":"s_work_nvlt_2_84","chapterId":"ch_work_nvlt_2","text":"《家語》曰：齊有一足之鳥，飛公朝，下於殿前，舒翅而跳，齊侯遣使訪孔子。孔子曰：此鳥名商羊，昔童兒有屈其一腳，振訊兩臂而跳，且謠曰：天將大雨，商羊鼓舞，今齊有之，其應至，將有水為灾。","sortOrder":84},
  {"id":"s_work_nvlt_2_85","chapterId":"ch_work_nvlt_2","text":"《老子》曰：骤雨不終日。","sortOrder":85},
  {"id":"s_work_nvlt_2_86","chapterId":"ch_work_nvlt_2","text":"《春秋說題辭》曰：一歲三十六雨，天地之氣宣，十日小雨，應天文，十五日大雨，以斗運也。","sortOrder":86},
  {"id":"s_work_nvlt_2_87","chapterId":"ch_work_nvlt_2","text":"《山海經》曰：羽山其上多雨，而符陽之山多怪雨，雲風之所出也。","sortOrder":87},
  {"id":"s_work_nvlt_2_88","chapterId":"ch_work_nvlt_2","text":"《莊子》曰：時雨降矣，而猶浸灌，不亦勞乎。","sortOrder":88},
  {"id":"s_work_nvlt_2_89","chapterId":"ch_work_nvlt_2","text":"又曰：宋景公時，大旱三年，卜之，以人祠乃雨，公下堂頓首曰：吾所以求雨，將自當之，言未卒，天下大雨方千里者何，德於天而惠於民也。","sortOrder":89},
  {"id":"s_work_nvlt_2_90","chapterId":"ch_work_nvlt_2","text":"《六韜》曰：文［說苑十三作武王事。］王問散宜生，卜伐殷，吉乎，曰：不吉，鑽龟，龟不兆，數蓍，蓍不交而如折，將行之日，雨，辎重車至軫，行之日，幟折為三，散宜生曰：此凶，四不祥，不可舉事，太公進曰：是非子之所知也，祖行之日，雨辎重車至軫，是洗濯甲兵也。","sortOrder":90},
  {"id":"s_work_nvlt_2_91","chapterId":"ch_work_nvlt_2","text":"《鹽鐵論》曰：周公太平之時，雨不破塊，旬而一雨，必以夜。","sortOrder":91},
  {"id":"s_work_nvlt_2_92","chapterId":"ch_work_nvlt_2","text":"《列仙傳》曰：赤松子者，神農時雨師也，［事具仙部。］","sortOrder":92},
  {"id":"s_work_nvlt_2_93","chapterId":"ch_work_nvlt_2","text":"謝承《後漢書》曰：百里嵩為徐州刺史，境遭旱，嵩行部，傳車所經，甘雨辄至。［事具職官部刺史篇。］","sortOrder":93},
  {"id":"s_work_nvlt_2_94","chapterId":"ch_work_nvlt_2","text":"《管辂別傳》曰：辂過清河太守，時天旱，辂曰：今夕當雨，树中已有少女微風。树間又有陰鳥和鳴。又少男風起，眾鳥亂翔，其應至矣，須臾，風雲興，玄氣四合，大雨註傾。","sortOrder":94},
  {"id":"s_work_nvlt_2_95","chapterId":"ch_work_nvlt_2","text":"《風俗通》曰：玄冥，雨師也。","sortOrder":95},
  {"id":"s_work_nvlt_2_96","chapterId":"ch_work_nvlt_2","text":"《論衡》曰：道至天者，祥風起，甘雨降，雨霁而陰曀者，謂之甘雨。","sortOrder":96},
  {"id":"s_work_nvlt_2_97","chapterId":"ch_work_nvlt_2","text":"《風土記》曰：六月有大雨，名濯枝雨。","sortOrder":97},
  {"id":"s_work_nvlt_2_98","chapterId":"ch_work_nvlt_2","text":"《益部耆舊傳》曰：趙瑤為阆中令，遭旱，請雨於靈星，應時大雨。","sortOrder":98},
  {"id":"s_work_nvlt_2_99","chapterId":"ch_work_nvlt_2","text":"《楚國先賢傳》曰：樊英忽謂學者曰：成都市火甚盛，因含水西向漱之，後有從蜀郡來者，雲是日大火，須臾大雨，火遂滅，［事具火部。］","sortOrder":99},
  {"id":"s_work_nvlt_2_100","chapterId":"ch_work_nvlt_2","text":"【詩】魏陳王曹植喜雨詩曰：天覆何弥廣，苞育此群生，弃之必憔悴，惠之則滋榮，慶雲從北來，鬱述西南征，時雨中夜降，長雷周我庭，嘉种獲膏壤，登秋畢有成。","sortOrder":100},
  {"id":"s_work_nvlt_2_101","chapterId":"ch_work_nvlt_2","text":"魏阮瑀詩曰：苦雨滋玄冬，引日弥且長，丹墀自殲殪，深树猶沾裳，客行易感悴，我心摧已傷，登台望江沔，陽侯沛洋洋。","sortOrder":101},
  {"id":"s_work_nvlt_2_102","chapterId":"ch_work_nvlt_2","text":"晉張載霖雨詩曰：霖雨餘旬朔，濛昧日夜墜，何以解愁懷，置酒招親類，悲歌結流風，逸响回秋氣。","sortOrder":102},
  {"id":"s_work_nvlt_2_103","chapterId":"ch_work_nvlt_2","text":"晉張协苦雨詩曰：黑蜧躍重川，商羊舞野庭，飛廉應南箕，丰隆迎號屏，雲根臨八極，雨足洒四溟，霖瀝過二旬，散漫亚九齡，階下伏泉踴，堂上水苔生，尺燼重尋桂，紅粒貴瑤琼。","sortOrder":103},
  {"id":"s_work_nvlt_2_104","chapterId":"ch_work_nvlt_2","text":"又雜詩曰：金風扇素節，丹霞啟陰期，騰雲似涌煙，密雨如散絲，寒花發黃彩，秋草含绿滋。","sortOrder":104},
  {"id":"s_work_nvlt_2_105","chapterId":"ch_work_nvlt_2","text":"又雜詩曰：朝霞迎白日，丹氣臨陽穀，翳翳結繁雲，森森散雨足。","sortOrder":105},
  {"id":"s_work_nvlt_2_106","chapterId":"ch_work_nvlt_2","text":"晉傅玄詩曰：徂暑未一旬，重陽翳朝霞，厥初月離畢，積日遂滂沱，屯雲結不解，長溜周四阿，霖雨如倒井，黃潦起洪波，湍深激牆隅，門庭若决河，炊爨不复舉，竈中生蛙虾。","sortOrder":106},
  {"id":"s_work_nvlt_2_107","chapterId":"ch_work_nvlt_2","text":"宋謝莊喜雨詩曰：鹅起知風舞，蛇楚润識雲流，洌泉承夜湛，零雨望晨浮，合穎行盛茂，分穗方盈畴。","sortOrder":107},
  {"id":"s_work_nvlt_2_108","chapterId":"ch_work_nvlt_2","text":"宋謝惠連喜雨詩曰：朱明振炎氣，溽暑扇溫飆，羨彼明月辉，離畢經中宵，思此西郊雲，既雨盈崇朝，上天愍憔悴，商羊自吟謠。","sortOrder":108},
  {"id":"s_work_nvlt_2_109","chapterId":"ch_work_nvlt_2","text":"宋鮑照喜雨詩曰：營社達群陰，屯宮掩積陽，族雲飛泉室，震風沉羽乡，升雰浃地維，傾润泻天潢，弥木抽翠條，炎卉耀朱芳，關市欣九賦，京廪开萬箱。","sortOrder":109},
  {"id":"s_work_nvlt_2_110","chapterId":"ch_work_nvlt_2","text":"又苦雨詩曰：連陰積浇灌，滂沱下霖亂，沉雲日夕昏，骤雨淫朝旦，蹊濘走獸希，枝寒鳥飛晏，密霧冥下溪，聚雲屯高岸。","sortOrder":110},
  {"id":"s_work_nvlt_2_111","chapterId":"ch_work_nvlt_2","text":"齊謝朓觀雨詩曰：朔風吹飛雨，萧條江上來，既洒百常觀，复集九成台，空濛如薄霧，散漫似輕埃。","sortOrder":111},
  {"id":"s_work_nvlt_2_112","chapterId":"ch_work_nvlt_2","text":"梁簡文帝賦得入階雨詩曰：細雨階前入，洒砌复沾帷，渍花枝覺重，濕鳥翻飛遲，傥令斜日照，併欲似遊絲。","sortOrder":112},
  {"id":"s_work_nvlt_2_113","chapterId":"ch_work_nvlt_2","text":"梁孝元帝詠細雨詩曰：風輕不動葉，雨細未沾衣，入樓如霧上，拂馬似尘飛。","sortOrder":113},
  {"id":"s_work_nvlt_2_114","chapterId":"ch_work_nvlt_2","text":"梁劉苞望夕雨詩曰：崇朝遘行雨，薄晚屯密雲，緣階起素沫，竟水散圓文，河柳低未舉，山桃落已芬，清樽久不荐，淹流遂待君。","sortOrder":114},
  {"id":"s_work_nvlt_2_115","chapterId":"ch_work_nvlt_2","text":"梁虞蹇［疑作騫。］擬雨詩曰：清風送涼氣，薄暮荡炎氛，虹照涟漪水，電出嵯峨雲，落暉散長足，細雨織斜文。","sortOrder":115},
  {"id":"s_work_nvlt_2_116","chapterId":"ch_work_nvlt_2","text":"梁劉孝綽秋雨臥疾詩曰：贾君徭役少，潘生民務稀，及此同多暇，高臥掩重闈，寂寂榆桑晚，滂沱曀不晞，電隙時光帳，風帘乍扣扉。","sortOrder":116},
  {"id":"s_work_nvlt_2_117","chapterId":"ch_work_nvlt_2","text":"梁劉孝威和皇太子春林晚雨詩曰：雲树交為密，雨日共成虹，電舒長男氣，枝搖少女風，葉珠垂滴水，簷繩下溜空，蝶濡飛不颺，花沾色更紅，明離信養德，能事畢春宮，誰堪偶鳳吹，唯有浮丘公。又望雨詩曰：清陰荡暄濁，飛雨入階廊，瞻空亂無緒，望霤耿成行，交枝含晚润，雜葉帶新光，浮芥離還聚，沿漚滅复張，浴禽飄落毳，亂荇散餘香，寄言楚台客，雄風詎獨涼。","sortOrder":117},
  {"id":"s_work_nvlt_2_118","chapterId":"ch_work_nvlt_2","text":"梁庾肩吾從駕喜雨詩曰：西嶽浮樽桂，東皇事浴阑，赦詔還京兆，歸神出灌壇，濕風含洒氣，陰雲助麥寒，典農欣受職，治粟喜當官，复此隨車雨，民知天可安。","sortOrder":118},
  {"id":"s_work_nvlt_2_119","chapterId":"ch_work_nvlt_2","text":"梁朱超對雨詩曰：當夏苦炎埃，習靜對花台，落照依山盡，浮涼帶雨來，重雲吐飛電，高棟响行雷，洒树輕花發，滴沼細萍开，泛沫榮階草，奔流起砌苔。","sortOrder":119},
  {"id":"s_work_nvlt_2_120","chapterId":"ch_work_nvlt_2","text":"北齊劉逖對雨有懷詩曰：重輪宵犯畢，行雨旦浮空，細落疑含霧，斜飛覺帶風，濕槐仍足绿，沾桃更上紅，無由似玄豹，縱意坐山中。","sortOrder":120},
  {"id":"s_work_nvlt_2_121","chapterId":"ch_work_nvlt_2","text":"周庾信和趙王喜雨詩曰：玄霓臨日穀，封蚁對雲台，投地欲起電，倚柱稍驚雷，白沙如濕粉，莲花類玉杯，驚鳥洒翼度，濕雁斷行來，浮桥七星起，高堰六門开，厥田終上上，原野自莓莓。","sortOrder":121},
  {"id":"s_work_nvlt_2_122","chapterId":"ch_work_nvlt_2","text":"又喜雨詩曰：離光初繞電，震氣始乘雷，雲逐魚鱗起，渠隨龍骨开，崩沙雜水去，臥树擁槎來，嘉苗双合穎，熟稻再含胎。","sortOrder":122},
  {"id":"s_work_nvlt_2_123","chapterId":"ch_work_nvlt_2","text":"又對雨詩曰：繁雲猶暗嶺，積雨未开庭，階含侵角路，镬滿溜疏萍，濕楊生細椹，烂草变初螢，徒勞看蚁封，無事祀靈星。","sortOrder":123},
  {"id":"s_work_nvlt_2_124","chapterId":"ch_work_nvlt_2","text":"陳陰铿閒居對雨詩曰：四溟飛旦雨，三径絕來遊，震位雷聲發，離宮電影浮，山雲遙似帶，庭葉近成舟，茅簷下亂滴，石窦引環流，寄言一高士，如何麥不收。","sortOrder":124},
  {"id":"s_work_nvlt_2_125","chapterId":"ch_work_nvlt_2","text":"又詩曰：蘋藻降靈祗，聰明谅在斯，觸石朝雲起，從星夜月離，八川奔巨壑，萬頃溢澄陂，绿野含膏润，青山帶濯枝，嘉禾方合穎，秀麥已分岐，寄語紛纶學，持竿詎必知。","sortOrder":125},
  {"id":"s_work_nvlt_2_126","chapterId":"ch_work_nvlt_2","text":"【賦】魏文帝愁霖賦曰：脂餘車而秣馬，將言旋乎鄴都，玄雲黯其四塞，雨濛濛而袭予，涂漸洳以沉滯，潦淫衍而橫湍，豈在餘之憚勞，哀行旅之艱難，仰皇天而太息，悲白日之不暘，思若木以照路，假龍燭之末光。","sortOrder":126},
  {"id":"s_work_nvlt_2_127","chapterId":"ch_work_nvlt_2","text":"魏陳王曹植愁霖賦曰：迎朔風而爰邁兮，雨微微而逮行，悼朝陽之隱曜兮，怨北辰之潛精，車結轍以盤桓兮，馬踯躅以悲鳴，攀扶桑而仰觀兮，假九日於天皇，瞻沉雲之泱漭兮，哀吾原之不將。","sortOrder":127},
  {"id":"s_work_nvlt_2_128","chapterId":"ch_work_nvlt_2","text":"又愁霖賦曰：夫何季秋之淫雨兮，既弥日而成霖，瞻玄雲之晻晻兮，聽長霤之淋淋，中宵夜而叹息，起飾帶而撫琴。","sortOrder":128},
  {"id":"s_work_nvlt_2_129","chapterId":"ch_work_nvlt_2","text":"魏應玚愁霖賦曰：聽屯雷之恒音兮，聞左右之叹聲，情惨愦而含欷兮，起披衣而遊庭，三辰幽而重關，蒼曜隱而無形，雲暧暧而周馳，雨濛濛而霧零，排房帳而北入，振蓋服之沾衣，還空床而寢息，夢白日之餘暉，惕中{宀悟}而不效兮。意凄悷而增悲。","sortOrder":129},
  {"id":"s_work_nvlt_2_130","chapterId":"ch_work_nvlt_2","text":"晉潘尼苦雨賦曰：氣觸石而結蒸兮，雲膚合而仰浮，雨紛射而下註兮，潦波涌而橫流，豈信宿之雲多，乃逾月而成霖，瞻中塘之浩汗，聽長霤之涔涔，始蒙瀎而徐墜，終滂霈而難禁，悲列宿之匿景，悼太陽之幽沉，雲暫披而骤合，雨乍息而亟零，旦漎々以達暮，夜淋淋以極明，黿鼍遊於門闼，蛙虾嬉乎中庭，懼二源之併合，畏黔首之為魚，處者含瘁於窮巷，行者叹息於長衢。","sortOrder":130},
  {"id":"s_work_nvlt_2_131","chapterId":"ch_work_nvlt_2","text":"晉陆雲愁霖賦曰：在朱明之季月，反極陽之重陰，興介丘之膚寸，墜崩雲之洪沉，穀風扇而攸遠，苦雨播而成淫，天泱漭以懷惨，民嚬蹙而愁霖，於是天地發揮，陰陽交激，萬物混而同汲，玄黃浩而無质，雷凭虛以振庭，電凌牖而曜室，霤鼎沸以駿奔，潦風馳而競疾，豈南山之暴跻，將溟海之暫溢，毒其雨之未晞，悲夏日之方永，瞻大晨以積息，仰天衢而引領。","sortOrder":131},
  {"id":"s_work_nvlt_2_132","chapterId":"ch_work_nvlt_2","text":"晉傅鹹患雨賦曰：夫何遠寓之多懷，患淫雨之有經，自流火以迄今，歷九旬而無寧，庶太清之垂曜，睹日月之光明，雲乍披而旋合，霤暫輟而复零，將收雷之要月，弃嘉穀於已成，前渴焉而不降，後患之而弗晴，惟二儀之神化，奚水旱之有併，湯亢陽於七載兮，尧洪汎乎九齡，天道且猶若茲，况人事之不平。","sortOrder":132},
  {"id":"s_work_nvlt_2_133","chapterId":"ch_work_nvlt_2","text":"又喜雨賦曰：於是祀［當作祝。］融炽景，羲和警辔，亢陽火憤，野無生類。悠悠亿兆，同茲惨悴，伊我皇之仁德兮，配焘育於二儀，屢刻躬而勤政兮，廣請祷於靈祗，孰謂天高，其聽不遼，孰謂神遠，厥應孔昭，絜齊致虔，於茲三朝。陰鬱怫而騰起，陽菴薆而自消，飛廉扇穀風之翼翼，靈嶽興慶雲之飄飖，遂乃重陰四會，溟邈無垠，方中降雨，亘夜迄今，生我百穀，粒我蒸民，昔洪水滔天於唐尧之朝，亢旱為灾於殷湯之世，下民其咨，莫能俾乂，歷稔九七，仅免斯害，猶以畴咨為美談，躬祷為勋代。","sortOrder":133},
  {"id":"s_work_nvlt_2_134","chapterId":"ch_work_nvlt_2","text":"晉成公綏陰霖賦曰：百川泛濫，潢潦橫流，沉竈生蛙，中庭運舟。","sortOrder":134},
  {"id":"s_work_nvlt_2_135","chapterId":"ch_work_nvlt_2","text":"又時雨賦曰：兩儀协合，二氣煙煴，洪川起波，名山興雲。","sortOrder":135},
  {"id":"s_work_nvlt_2_136","chapterId":"ch_work_nvlt_2","text":"宋傅亮喜雨賦曰：惟二儀之順動，數有積而時偏，墊襄陵於唐籍，慼雲漢於周篇，匪叔葉之或遘，在盛王其固然，伊元嘉之初載，肇休明於此年，懿玉燭之方熙，慍積陽之獨愆，涸涼泉於井穀，委嘉穎於中田，嗟我皇之翼翼，怅臨朝而輟娱，踵冲謙於禹湯，协至誠於在餘，且東作之未晏，庶雨露之夙濡，遵懸子徙廛，尤魯侯之焚巫，祗桑林之六祷，修季宰之再雩，誠在幽其必貫，感何遠而不孚，聆晨鸛於高垤，候宵畢於天隅，發曾雲於觸石，晦重陽於八區，春霆殷以遠响，興雨霈而載涂，洒丰浸於中畴，覃餘润於嘉蔬，殷啬人於菑畝，衍將繁於中衢，嗣良頌於多稔，兆嘉夢於樵漁，矧具［原訛其，據冯校本改。］臣之逢運。又均休而等虞，陶曲成於暮稔，金歸駕於董疏。","sortOrder":136},
  {"id":"s_work_nvlt_2_137","chapterId":"ch_work_nvlt_2","text":"梁張缵秋雨賦曰：霡霂興乎爽節，膚寸起於曾岑，乃娱情而脱體，猶冬陽與夏陰，褰南帷以寓目，敞北戶而披衿，商律戒於茲辰，涼雨感而已作，甘泉集而溟溟，油雲興而漠漠，溫飆革於早暮，炎涼改於今昨，乍斜簷而上階，或從風而洒幕，周小庭而密下，泫高枝而疏落，渌池泛澹，員波儵烁，低昂弱筱，葳蕤丛薄。","sortOrder":137},
  {"id":"s_work_nvlt_2_139","chapterId":"ch_work_nvlt_2","text":"《說文》曰：霁，雨止也。","sortOrder":139},
  {"id":"s_work_nvlt_2_140","chapterId":"ch_work_nvlt_2","text":"《魏略》曰：延康元年，大霖雨五十餘日，魏有天下，乃霁，將受大祚之應也。","sortOrder":140},
  {"id":"s_work_nvlt_2_141","chapterId":"ch_work_nvlt_2","text":"《晉中興書》曰：鹹和四年，陰霖五十餘日，蘇峻滅後乃霁。","sortOrder":141},
  {"id":"s_work_nvlt_2_142","chapterId":"ch_work_nvlt_2","text":"《長沙耆舊傳》曰：文虔字仲孺，時霖雨废民業，太守忧色，虔補戶曹掾，虔奉教斋戒，在社三日，夜夢見白頭翁謂曰：爾來何遲，虔具白所夢，太守曰：昔禹夢繡衣男子，稱沧水使者，禹知水脈當通，若掾此夢，將可比也，明日，果大霁。","sortOrder":142},
  {"id":"s_work_nvlt_2_143","chapterId":"ch_work_nvlt_2","text":"扶南傳曰：金陣［原作障，據冯校本改。］國，入四月便雨，六月乃止，少有晴日。","sortOrder":143},
  {"id":"s_work_nvlt_2_144","chapterId":"ch_work_nvlt_2","text":"【詩】晉嵇含悅晴詩曰：劲風歸巽林，玄雲起重基，朝霞炙琼树，夕景映玉芝，翔鳳晞輕翮，應龍曝纖鬐，百穀偃而立，大木顛复持。","sortOrder":144},
  {"id":"s_work_nvlt_2_145","chapterId":"ch_work_nvlt_2","text":"宋謝瞻答康樂秋霁詩曰：夕霁風氣涼，閒房有餘清，开軒滅華燭，月露皓已盈。","sortOrder":145},
  {"id":"s_work_nvlt_2_146","chapterId":"ch_work_nvlt_2","text":"梁簡文帝开霁詩曰：景落商飆靖，煙开四郊謐，偃蹇暮山虹，遊扬下峰日，水文城上動，城樓水中出，竟徵共治功，空臥淮陽秩。","sortOrder":146},
  {"id":"s_work_nvlt_2_147","chapterId":"ch_work_nvlt_2","text":"梁王筠夕霁詩曰：連山卷族雲，長林息眾籁，密树含绿滋，遙峰凝翠霭，物華方入賞，跋予心期會。","sortOrder":147},
  {"id":"s_work_nvlt_2_148","chapterId":"ch_work_nvlt_2","text":"周庾信初晴詩曰：濕花飛未遠，陰雲斂尚低，燕［原訛鸞，據冯校本改。］燥還為石，龍殘便是泥。","sortOrder":148},
  {"id":"s_work_nvlt_2_149","chapterId":"ch_work_nvlt_2","text":"【賦】魏文帝喜霁賦曰：乃命駕而言歸，啟吉日而北巡，厭群萌之至原，感上下之明神，密雲興之坱北，［當作圠。］甘雨降以洒尘，既洒尘而為涂，惟平路之未晞，激清風以漂潦，發皎日之陽暉，振餘策而長驅，忽臨食而忘飢。","sortOrder":149},
  {"id":"s_work_nvlt_2_150","chapterId":"ch_work_nvlt_2","text":"魏陳王曹植喜霁賦曰：禹身誓於陽旰，［當從淮南子脩務篇作盱。］卒錫圭而告成，湯感旱於殷時，造桑林而敷誠，動玉輞而雲披，鳴鸞鈴而日陽，指北極以為期，吾將倍道以兼行。","sortOrder":150},
  {"id":"s_work_nvlt_2_151","chapterId":"ch_work_nvlt_2","text":"晉陆雲喜霁賦曰：靖屏翳之洪隧，戢太山之觸石，凌風絕而謐寧，歸雲反而徽霍，改望舒之離畢，曜六龍於紫閣，於是朱明啟候，凯風來南，复火正之權司兮，默後土於重陰，夷中原之多潦兮，反高岸於嵩岑，萎禾竦而振穎兮，偃木竖而為林，陰陽交泰，萬物方遒，炎神送暑，素靈迎秋，四時逝而代謝，大火忽其西流，年冉冉其易頹，時靡靡而難留。","sortOrder":151},
  {"id":"s_work_nvlt_2_152","chapterId":"ch_work_nvlt_2","text":"【文】宋孝武帝祈晴文曰：幽明失序，就陰則滯，連雲霖淫，註而不替，润既违時，泽而非惠，幸輟霖而吐景，權停風而斂翳，昭鸞辂於天郊，光龍旂於田际，耒耨得施，黍稷獲藝，增高廪於嘉年，登十千於茲歲。","sortOrder":152},
  {"id":"s_work_nvlt_2_154","chapterId":"ch_work_nvlt_2","text":"《易》曰：鼓之以雷霆，润之以風雨。","sortOrder":154},
  {"id":"s_work_nvlt_2_155","chapterId":"ch_work_nvlt_2","text":"又曰：震為雷，動萬物者，莫疾於雷。","sortOrder":155},
  {"id":"s_work_nvlt_2_156","chapterId":"ch_work_nvlt_2","text":"《禮記》曰：仲春之月，日夜分，雷乃發聲，仲秋之月，雷乃收聲。","sortOrder":156},
  {"id":"s_work_nvlt_2_157","chapterId":"ch_work_nvlt_2","text":"大戴禮夏小正曰：正月，雉震鳴鸲，鼓其翼也，正月必雷，雷不正聞，唯雉聞。","sortOrder":157},
  {"id":"s_work_nvlt_2_158","chapterId":"ch_work_nvlt_2","text":"《毛詩》曰：殷其雷，在南山之陽。","sortOrder":158},
  {"id":"s_work_nvlt_2_159","chapterId":"ch_work_nvlt_2","text":"又曰：虺虺其雷。","sortOrder":159},
  {"id":"s_work_nvlt_2_160","chapterId":"ch_work_nvlt_2","text":"《左傳》曰：藏冰以時，則雷出不震，弃冰不用，則雷不發而震。","sortOrder":160},
  {"id":"s_work_nvlt_2_161","chapterId":"ch_work_nvlt_2","text":"《尚書·中候》曰：秦穆公出狩，天震大雷，下有火，化為白雀，衔丹書，集公車，［事具祥瑞部。］","sortOrder":161},
  {"id":"s_work_nvlt_2_162","chapterId":"ch_work_nvlt_2","text":"《史記》曰：高祖母曰劉媪，嘗息大泽之陂，夢與神遇，時雷電冥晦，［事具帝王部。］","sortOrder":162},
  {"id":"s_work_nvlt_2_163","chapterId":"ch_work_nvlt_2","text":"《山海經》曰：翔次之山，有鳥名橐{非己}，服其毛羽，令人不畏雷也。","sortOrder":163},
  {"id":"s_work_nvlt_2_164","chapterId":"ch_work_nvlt_2","text":"《淮南子》曰：陰陽相薄，感而為雷。","sortOrder":164},
  {"id":"s_work_nvlt_2_165","chapterId":"ch_work_nvlt_2","text":"焦贛《易林》曰：白日扬光，雷車避藏，雲雨不下，各自正乡。","sortOrder":165},
  {"id":"s_work_nvlt_2_166","chapterId":"ch_work_nvlt_2","text":"《物理論》曰：積風成雷。","sortOrder":166},
  {"id":"s_work_nvlt_2_167","chapterId":"ch_work_nvlt_2","text":"《易》曰：雷風相薄。","sortOrder":167},
  {"id":"s_work_nvlt_2_168","chapterId":"ch_work_nvlt_2","text":"《洪范五行傳》曰：夫雷，人君象也，入能除害，出能興利。","sortOrder":168},
  {"id":"s_work_nvlt_2_169","chapterId":"ch_work_nvlt_2","text":"河圖帝紀通曰：雷，天地之鼓也。","sortOrder":169},
  {"id":"s_work_nvlt_2_170","chapterId":"ch_work_nvlt_2","text":"又曰：黃帝以雷精起。","sortOrder":170},
  {"id":"s_work_nvlt_2_171","chapterId":"ch_work_nvlt_2","text":"《鶡冠子》曰：夫耳之主聰，目之主明，一葉蔽目，不見太山，兩豆［原訛頭，據冯校本改。］塞耳，不聞雷霆。","sortOrder":171},
  {"id":"s_work_nvlt_2_172","chapterId":"ch_work_nvlt_2","text":"《論衡》曰：圖畫之功，［《初學記》一，《太平御覽》十三作工。］圖雷之状，畾畾如連鼓形。又圖一人若力士，謂之雷公，使之左手引連鼓，右手椎之。","sortOrder":172},
  {"id":"s_work_nvlt_2_173","chapterId":"ch_work_nvlt_2","text":"《晉陽秋》曰：王襃母，性畏雷，及母死，每雷震，辄就墓侧啟曰：襃在此，襃在此。","sortOrder":173},
  {"id":"s_work_nvlt_2_174","chapterId":"ch_work_nvlt_2","text":"盛弘之《荆州記》曰：胡［水經註二十九作湖。］陽縣，春秋蓼國，樊重之邑也，重母畏雷，為石室避之，悉以文石為階砌，今猶存。","sortOrder":174},
  {"id":"s_work_nvlt_2_175","chapterId":"ch_work_nvlt_2","text":"王韶《孝子傳》曰：竺弥父生時畏雷，每至天陰，辄至墓，伏墳悲哭，有白兔在其左右。","sortOrder":175},
  {"id":"s_work_nvlt_2_176","chapterId":"ch_work_nvlt_2","text":"《華陽國志》曰：曹公從容謂先主曰：天下英雄，唯使君與操，本初之徒，不足數也，先主方食，失匕箸，會雷大震，先主曰：聖人言，迅雷風烈必变，良有以也，一震之威，乃可致此，公亦悔失言。","sortOrder":176},
  {"id":"s_work_nvlt_2_177","chapterId":"ch_work_nvlt_2","text":"雷於天地為長子，以其萬物為出入也，雷二月出地百八十日，雷出則萬物出，八月入地百八十日，雷入則萬物入，入則除害，出則興利，人君之象也，［本條《初學記》一引於郎顗上書下，北堂書鈔一百五十二，《太平御覽》十三作洪范五行傳，此脱書名。］","sortOrder":177},
  {"id":"s_work_nvlt_2_178","chapterId":"ch_work_nvlt_2","text":"孟奧北征記曰：凌雲台東南角一百步，有白石室，名為避雷室。","sortOrder":178},
  {"id":"s_work_nvlt_2_179","chapterId":"ch_work_nvlt_2","text":"《續搜神記》曰：義興人姓周，永和中，出都，日暮，道邊有一新草小屋，有一女出門，望見周，曰：日已暮，周求寄宿，向一更中，聞外有小兒唤阿香，官唤汝推雷車，女子乃辭去，明朝视宿處，乃見一新冢。","sortOrder":179},
  {"id":"s_work_nvlt_2_180","chapterId":"ch_work_nvlt_2","text":"《爾雅》曰：疾雷謂之霆。","sortOrder":180},
  {"id":"s_work_nvlt_2_181","chapterId":"ch_work_nvlt_2","text":"《穀梁傳》曰：陰陽相薄，感而為雷，激而為霆，《五經通義》曰：震與霆，皆霹靂也，公羊註曰：雷疾而甚者為震，震與霆，皆謂霹靂也，雷謂電之先，［○初學記一作電謂之雷光也。］","sortOrder":181},
  {"id":"s_work_nvlt_2_182","chapterId":"ch_work_nvlt_2","text":"《易》曰：天地解而雷雨作，雷雨作而百穀草木皆甲坼。","sortOrder":182},
  {"id":"s_work_nvlt_2_183","chapterId":"ch_work_nvlt_2","text":"《山海經》曰：飛魚如豚，赤文無羽，食之辟兵，不畏雷也。","sortOrder":183},
  {"id":"s_work_nvlt_2_184","chapterId":"ch_work_nvlt_2","text":"《淮南子》曰：丛輕折軸，眾呼成雷，庶女叫天而雷下击，景公台損，支體傷折，海水大出。","sortOrder":184},
  {"id":"s_work_nvlt_2_185","chapterId":"ch_work_nvlt_2","text":"漢書［《太平御覽》十三作續漢書。］曰：桓帝建和二年，六月乙卯，雷震憲陵寢屋，是梁太後聽兄冀枉誅乔也。","sortOrder":185},
  {"id":"s_work_nvlt_2_186","chapterId":"ch_work_nvlt_2","text":"蔡順母平生畏雷，［本條《初學記》一，《太平御覽》十三作周斐汝南先賢傳，此脱書名。］自亡後，每有雷，順辄還［《初學記》，御覽作環。］冢泣曰：順在此。","sortOrder":186},
  {"id":"s_work_nvlt_2_187","chapterId":"ch_work_nvlt_2","text":"《論衡》曰：雷霆迅疾，击折树木，坏败屋室，時犯殺人，俗以為天取龍，其犯殺人，謂之有陰過。","sortOrder":187},
  {"id":"s_work_nvlt_2_188","chapterId":"ch_work_nvlt_2","text":"《雜兵書》曰：雷電霹靂，破軍內若树木屋舍，急徙去，吉也，雷電風所從來，不可逆而伐，宜慎之。","sortOrder":188},
  {"id":"s_work_nvlt_2_189","chapterId":"ch_work_nvlt_2","text":"論語讖曰：雷震百里，聲相附近，宋均註曰：雷動百里，故因以為言也，雷聲謂諸侯之政教所至，相附近也。","sortOrder":189},
  {"id":"s_work_nvlt_2_190","chapterId":"ch_work_nvlt_2","text":"《說文》曰：雷霆餘聲鈐鈐，［《太平御覽》十三作鈴鈴。］所以挺出萬物也。","sortOrder":190},
  {"id":"s_work_nvlt_2_191","chapterId":"ch_work_nvlt_2","text":"【詩】晉傅玄雜言詩曰：雷隱隱，感妾心，傾耳清聽非車音。","sortOrder":191},
  {"id":"s_work_nvlt_2_192","chapterId":"ch_work_nvlt_2","text":"又曰：童女掣電策，童男挽雷車。","sortOrder":192},
  {"id":"s_work_nvlt_2_193","chapterId":"ch_work_nvlt_2","text":"又驚雷歌曰：驚雷奋兮震萬里，威陵宇宙兮動四海，六合不維兮誰能理。","sortOrder":193},
  {"id":"s_work_nvlt_2_194","chapterId":"ch_work_nvlt_2","text":"【賦】晉李顒雷賦曰：伊有陽之肇化兮，陶萬殊於天壤，結鬱蒸而成雷兮，鼓訇稜之逸响，若乃駭氣奔激，震响交搏，濆淪隱辚，崩騰磊落，來無轍跡，去無阡陌，君子恐懼而修省，聖人因象以製作。","sortOrder":194},
  {"id":"s_work_nvlt_2_196","chapterId":"ch_work_nvlt_2","text":"《毛詩》曰：燁燁震電。","sortOrder":196},
  {"id":"s_work_nvlt_2_197","chapterId":"ch_work_nvlt_2","text":"《易》曰：離為電。","sortOrder":197},
  {"id":"s_work_nvlt_2_198","chapterId":"ch_work_nvlt_2","text":"又曰：雷電噬嗑。","sortOrder":198},
  {"id":"s_work_nvlt_2_199","chapterId":"ch_work_nvlt_2","text":"《月令》曰：仲春始電。","sortOrder":199},
  {"id":"s_work_nvlt_2_200","chapterId":"ch_work_nvlt_2","text":"《晉書》曰：王戎视日不昡，目烂烂若巖下電。","sortOrder":200},
  {"id":"s_work_nvlt_2_201","chapterId":"ch_work_nvlt_2","text":"《山海經》曰：列缺，電名。","sortOrder":201},
  {"id":"s_work_nvlt_2_202","chapterId":"ch_work_nvlt_2","text":"《莊子》曰：陰氣伏於黃泉，陽氣上通於天，陰陽分爭故為電，玉女投壶，天為之笑則電，［此十字，本書十七引作神異經，此脱書名，當另作一條。］","sortOrder":202},
  {"id":"s_work_nvlt_2_203","chapterId":"ch_work_nvlt_2","text":"《河圖握拒起》曰：大電繞枢星，炤郊野，感符寶而生黃帝。［事具符命部。］","sortOrder":203},
  {"id":"s_work_nvlt_2_204","chapterId":"ch_work_nvlt_2","text":"《淮南子》曰：電以為鞭策，［電，激氣也。］","sortOrder":204},
  {"id":"s_work_nvlt_2_205","chapterId":"ch_work_nvlt_2","text":"甘泉賦曰：電倏閃於牆藩。","sortOrder":205},
  {"id":"s_work_nvlt_2_206","chapterId":"ch_work_nvlt_2","text":"【賦】晉顧凯之雷電賦曰：太極紛纶，元氣澄練，陰陽相薄，為雷為電，是以宣尼敬威忽变，夫其聲無定响，光不恒照，砰訇輪轉，儵閃羅曜，若乃太陰下淪，少陽初升，蟄虫將啟，動靈先應，殷殷徐振，不激不凭，林鍾統節，褥暑煙煴，星月不朗，衣床若焚，爾乃清風前飒，荡濁流尘，丰隆破响，列缺开雲，當時倦容，廓焉精新，豈直驚安竦寐，乃以畅精悟神，天怒將凌，赤電先發，窥巖四照，映流双絕，雷電赫以驚衡，山海磕其崩裂。","sortOrder":206},
  {"id":"s_work_nvlt_2_208","chapterId":"ch_work_nvlt_2","text":"《爾雅》曰：地氣發，天不應，曰霧，霧謂之晦。","sortOrder":208},
  {"id":"s_work_nvlt_2_209","chapterId":"ch_work_nvlt_2","text":"《帝王世紀》曰：黃帝時，天大霧三日，帝遊洛川之上，見大魚，殺三牲以醮之，天乃甚雨，七日七夜，魚流，始得圖書。","sortOrder":209},
  {"id":"s_work_nvlt_2_210","chapterId":"ch_work_nvlt_2","text":"黃帝玄女之宮戰法曰：黃帝與蚩尤對，力戰九不勝，黃帝歸於太山，三日三夜，天霧冥冥，有一婦人，人首鳥形，黃帝稽首再拜，伏不敢起，婦人曰：吾所謂玄女者，子欲何問，黃帝曰：小子欲萬戰萬勝，萬隱萬匿，首當何從起。","sortOrder":210},
  {"id":"s_work_nvlt_2_211","chapterId":"ch_work_nvlt_2","text":"《曾子》曰：陰陽之氣亂則霧。","sortOrder":211},
  {"id":"s_work_nvlt_2_212","chapterId":"ch_work_nvlt_2","text":"《龍魚河圖》曰：山冬天霧十日已上不除者，山崩之候。","sortOrder":212},
  {"id":"s_work_nvlt_2_213","chapterId":"ch_work_nvlt_2","text":"《地鏡圖》曰：古之王者，行遊諸侯，其所居國，國必有三日浸，变而為日中之霧。","sortOrder":213},
  {"id":"s_work_nvlt_2_214","chapterId":"ch_work_nvlt_2","text":"陳留風俗傳曰：雍丘縣有祠，名曰夏後公祠，神井能致霧。","sortOrder":214},
  {"id":"s_work_nvlt_2_215","chapterId":"ch_work_nvlt_2","text":"漢武帝內傳曰：東方朔乘雲飛去，仰望，大霧覆之，不知所在。","sortOrder":215},
  {"id":"s_work_nvlt_2_216","chapterId":"ch_work_nvlt_2","text":"《東觀漢記》曰：馬援謂官屬曰：吾在浪泊西里乌［東觀漢記作摀。］間虜未滅之時，下潦上霧，毒氣薰蒸，仰视乌鳶，跕跕墮水中。","sortOrder":216},
  {"id":"s_work_nvlt_2_217","chapterId":"ch_work_nvlt_2","text":"謝承《後漢書》曰：河南張楷，性好道術，能作五里霧，時關西人裴優，亦能作三里霧，自以不如楷，往從學之，楷避不肯見。","sortOrder":217},
  {"id":"s_work_nvlt_2_218","chapterId":"ch_work_nvlt_2","text":"《英雄記》曰：曹公赤壁之役，行至雲夢大泽中，遇大霧，迷失道。","sortOrder":218},
  {"id":"s_work_nvlt_2_219","chapterId":"ch_work_nvlt_2","text":"《魏略》曰：劉雄鳴每出行，雲霧中識道不迷惑，時人因謂能為雲霧。","sortOrder":219},
  {"id":"s_work_nvlt_2_220","chapterId":"ch_work_nvlt_2","text":"望氣經曰：六月三日有霧，歲熟。","sortOrder":220},
  {"id":"s_work_nvlt_2_221","chapterId":"ch_work_nvlt_2","text":"《博物志》曰：王肅［《太平御覽》十五作爾。］張衡馬均，昔俱冒霧行，一人無恙，一人病，一人死，問其故，無恙者雲，我飲酒，病者飽食，死者空腹。","sortOrder":221},
  {"id":"s_work_nvlt_2_222","chapterId":"ch_work_nvlt_2","text":"王隱《晉書》曰：樂廣為尚書郎，尚書令衛瓘見奇之，命諸子造焉，曰：此人之水鏡，每見，令人瑩然，若披雲霧睹青天。","sortOrder":222},
  {"id":"s_work_nvlt_2_223","chapterId":"ch_work_nvlt_2","text":"《神仙傳》曰：栾巴為尚書，忽一旦天大霧，對坐不相見，失巴所在，尋問之，雲其日還成都，親故別，時亦風雨晦冥。","sortOrder":223},
  {"id":"s_work_nvlt_2_224","chapterId":"ch_work_nvlt_2","text":"袁山松宜都山川記曰：郡西北有丹山，天晴，嶺忽有霧起，回轉如煙，不過再朝，雨必降。","sortOrder":224},
  {"id":"s_work_nvlt_2_225","chapterId":"ch_work_nvlt_2","text":"【詩】梁孝元帝詠霧詩曰：三晨生遠霧，五里暗城闉，從風疑細雨，映日似遊尘，乍若飛煙散，時如佳氣新。","sortOrder":225},
  {"id":"s_work_nvlt_2_226","chapterId":"ch_work_nvlt_2","text":"又詩曰：晓霧晦階前，垂珠帶葉邊，五里浮長隰，三晨暗遠天，旁通似佳氣，却望若非煙，疏帘還复密，斷棟更疑連，還思逢樂廣，能令雲霧褰。","sortOrder":226},
  {"id":"s_work_nvlt_2_227","chapterId":"ch_work_nvlt_2","text":"梁伏挺行舟值早霧詩曰：水霧雜山煙，冥冥見晓天，聽猿方忖岫，聞瀨始知川，漁人惑隩浦，行舟迷溯沿，日中氛霭盡，空水共澄鮮。","sortOrder":227},
  {"id":"s_work_nvlt_2_228","chapterId":"ch_work_nvlt_2","text":"周王襃詠霧應詔詩曰：七條开早陌，五里闇朝氛，帶樓疑海氣，含蓋似浮雲，方從河水上，預奉绿圖文。","sortOrder":228},
  {"id":"s_work_nvlt_2_230","chapterId":"ch_work_nvlt_2","text":"《禮記月令》曰：季春之月，虹始見，孟冬之月，虹藏不見。","sortOrder":230},
  {"id":"s_work_nvlt_2_231","chapterId":"ch_work_nvlt_2","text":"《釋名》曰：虹，陽氣之動，虹，攻也，純陽攻陰氣也。","sortOrder":231},
  {"id":"s_work_nvlt_2_232","chapterId":"ch_work_nvlt_2","text":"又曰：夫人陰陽不合，婚姻错亂，淫風流行，男女互相奔隨之時，此則氣盛，故以其盛時合之也。","sortOrder":232},
  {"id":"s_work_nvlt_2_233","chapterId":"ch_work_nvlt_2","text":"《說文》曰：霓，屈虹，青赤，或白色，陰氣也。","sortOrder":233},
  {"id":"s_work_nvlt_2_234","chapterId":"ch_work_nvlt_2","text":"《毛詩》曰：螮蝀在東，莫之敢指，一名挈貳，［按挈貳見爾雅釋天，此有脱文。］","sortOrder":234},
  {"id":"s_work_nvlt_2_235","chapterId":"ch_work_nvlt_2","text":"《河圖稽曜鉤》曰：镇星散為虹蜺。","sortOrder":235},
  {"id":"s_work_nvlt_2_236","chapterId":"ch_work_nvlt_2","text":"《春秋運斗枢》：枢星散為虹蜺。","sortOrder":236},
  {"id":"s_work_nvlt_2_237","chapterId":"ch_work_nvlt_2","text":"《尚書考靈曜》鄭玄註曰：日旁氣白者為虹。","sortOrder":237},
  {"id":"s_work_nvlt_2_238","chapterId":"ch_work_nvlt_2","text":"《莊子》曰：陽炙陰為虹。","sortOrder":238},
  {"id":"s_work_nvlt_2_239","chapterId":"ch_work_nvlt_2","text":"《黃帝占軍訣》曰：攻城，有虹從外南方入飲城中者，從虹攻之勝，白虹繞城不匝，從虹所在乃击。","sortOrder":239},
  {"id":"s_work_nvlt_2_240","chapterId":"ch_work_nvlt_2","text":"蔡邕《月令章句》曰：虹，螮蝀也，陰陽交接之氣，著於形色者也，雄曰虹，雌曰蜺，蜺常依陰雲而晝見於日冲，無雲不見，大陰亦不見，率以日西見於東方，故詩雲，螮蝀在於東，蜺常在於旁，四時常有之，唯雄虹見藏有月。","sortOrder":240},
  {"id":"s_work_nvlt_2_241","chapterId":"ch_work_nvlt_2","text":"《戰國策》曰：唐睢謂秦王曰：聂政刺韓劚，白虹貫日。","sortOrder":241},
  {"id":"s_work_nvlt_2_242","chapterId":"ch_work_nvlt_2","text":"《列士傳》曰：荆軻為燕太子謀刺秦王，白虹貫日。","sortOrder":242},
  {"id":"s_work_nvlt_2_243","chapterId":"ch_work_nvlt_2","text":"《異苑》曰：古者有夫妻，荒年菜食而死，俱化成青絳，故俗呼美人虹。","sortOrder":243},
  {"id":"s_work_nvlt_2_244","chapterId":"ch_work_nvlt_2","text":"又曰：晉陵薛原，義熙初，有虹飲其釜澳，吸响便竭，原輦酒灌之，隨投隨涸，便吐金滿器，於是灾弊日祛，而丰富歲臻。","sortOrder":244},
  {"id":"s_work_nvlt_2_245","chapterId":"ch_work_nvlt_2","text":"《楚辭·天問》曰：白蜺婴茀，胡為此堂，［蜺，雲之有色，似龍，茀，白雲萎蛇者也。］","sortOrder":245},
  {"id":"s_work_nvlt_2_246","chapterId":"ch_work_nvlt_2","text":"又曰：虹蜺紛其朝覆兮，夕淫淫而霖雨。","sortOrder":246},
  {"id":"s_work_nvlt_2_247","chapterId":"ch_work_nvlt_2","text":"【賦】梁江淹赤虹賦曰：俄而赤蜺電出，蚴虬神驤，暧昧以变，依稀不常，非虛非實，乍滅乍光，赩赫山顶，照燎水陽，雖圖緯之有載，曠世識之未逢，既咨嗟而踯躅，聊周流而從容，餘形可覽，殘色未去，曜萎蕤而在草，映青葱而結树，霞晃朗而下飛，日通籠而上度。","sortOrder":247},
  {"id":"s_work_nvlt_2_248","chapterId":"ch_work_nvlt_2","text":"【詩】董思恭詠虹詩曰：春暮萍生早，日落雨飛餘，橫彩分長漢，倒色媚青渠，梁前朝影出，桥上晚光舒，原逐旌旗轉，飄飄侍直庐。","sortOrder":248},
  {"id":"s_work_nvlt_2_249","chapterId":"ch_work_nvlt_2","text":"蘇味道詠虹詩曰：紆餘帶星渚，窈窕架天潯，空因壮士見，還共美人沈，逸势含良玉，神光藻瑞金，獨留長劍彩，終負昔賢心。","sortOrder":249},
  {"id":"s_work_nvlt_2_250","chapterId":"ch_work_nvlt_2","text":"《藝文類聚》　唐·欧陽詢","sortOrder":250},
  {"id":"s_work_nvlt_3_1","chapterId":"ch_work_nvlt_3","text":"卷三歲時上據明本補","sortOrder":1},
  {"id":"s_work_nvlt_3_2","chapterId":"ch_work_nvlt_3","text":"○春夏秋冬","sortOrder":2},
  {"id":"s_work_nvlt_3_4","chapterId":"ch_work_nvlt_3","text":"《爾雅》曰：春為青陽，一曰發生。","sortOrder":4},
  {"id":"s_work_nvlt_3_5","chapterId":"ch_work_nvlt_3","text":"《尚書》曰：寅賓出日，平秩東作，日中星鳥，以殷仲春。","sortOrder":5},
  {"id":"s_work_nvlt_3_6","chapterId":"ch_work_nvlt_3","text":"《禮記月令》曰：孟春之月，東風解冻，蟄虫始振，魚上冰，獭祭魚，鸿雁來，乃擇元辰，天子躬耕帝籍，是月也，天氣下降，地氣上騰，天地和同，草木萌動，仲春之月，桃始華，仓庚鳴，鷹化為鳩，是月也，玄鳥至之日，祀於高禖，季春之月，桐始華，虹始見，萍始生，舟牧覆舟，五覆五反，天子始乘舟，布德行惠，鳴鳩拂其羽，戴勝降於桑。","sortOrder":6},
  {"id":"s_work_nvlt_3_7","chapterId":"ch_work_nvlt_3","text":"《周禮》曰：仲春詔後，率外內命婦，始蠶於北郊，帥六宮之夫人，生穜稑之种而獻之於王。","sortOrder":7},
  {"id":"s_work_nvlt_3_8","chapterId":"ch_work_nvlt_3","text":"《釋名》曰：春之為言蠢也，物蠢而生。","sortOrder":8},
  {"id":"s_work_nvlt_3_9","chapterId":"ch_work_nvlt_3","text":"《尸子》曰：春為忠，東方為春，春，動也，是故鳥獸孕寧，草木華生，萬物鹹遂，忠之至。","sortOrder":9},
  {"id":"s_work_nvlt_3_10","chapterId":"ch_work_nvlt_3","text":"《尚書大傳》曰：東方者，動方也，物之動也，何以謂之春，春，出也，物之出，故謂東方春也。","sortOrder":10},
  {"id":"s_work_nvlt_3_11","chapterId":"ch_work_nvlt_3","text":"《周官》曰：羅氏，仲春羅春鳥，獻鳩，以養老也。","sortOrder":11},
  {"id":"s_work_nvlt_3_12","chapterId":"ch_work_nvlt_3","text":"《易緯通卦验》曰：震，東方也，主春分，日出青氣，出直震，此正氣出也，氣出右，萬物半死，氣出左，蛟龍出，震氣不至，則歲中少雷，萬物華而不實，人民疾熱，應在其冲。","sortOrder":12},
  {"id":"s_work_nvlt_3_13","chapterId":"ch_work_nvlt_3","text":"又曰：立春條風至，雉雊，雞乳，冰解，楊柳津，春分明庶風至，雷雨行，桃李華。","sortOrder":13},
  {"id":"s_work_nvlt_3_14","chapterId":"ch_work_nvlt_3","text":"《毛詩》曰：春日載陽，有鳴仓庚，春日遲遲，采蘩祁祁，女心傷悲，迨及公子同歸。","sortOrder":14},
  {"id":"s_work_nvlt_3_15","chapterId":"ch_work_nvlt_3","text":"《尚書緯》曰：東方春，龍房位，其規仁，好生不賊。","sortOrder":15},
  {"id":"s_work_nvlt_3_16","chapterId":"ch_work_nvlt_3","text":"《莊子》曰：春氣發而百草生，正得秋而萬寶成，夫春與秋，豈得而然哉，天道已行矣。","sortOrder":16},
  {"id":"s_work_nvlt_3_17","chapterId":"ch_work_nvlt_3","text":"《孝經緯》曰：周天七衡六間，曰立春，後十五日，斗指寅，為雨水，後十五日，斗指甲，為驚蟄，後十五日，斗指卯，為春分，後十五日，斗指乙，為清明，後十五日，斗指辰，為穀雨。","sortOrder":17},
  {"id":"s_work_nvlt_3_18","chapterId":"ch_work_nvlt_3","text":"《論語》曰：暮春者，春服既成，冠者五六人，童子六七人，浴乎沂，風乎舞雩，詠而歸。","sortOrder":18},
  {"id":"s_work_nvlt_3_19","chapterId":"ch_work_nvlt_3","text":"《老子》曰：眾人熙熙，若享大牢，如登春台。","sortOrder":19},
  {"id":"s_work_nvlt_3_20","chapterId":"ch_work_nvlt_3","text":"《淮南子》曰：春女悲，秋士哀，知物化矣。","sortOrder":20},
  {"id":"s_work_nvlt_3_21","chapterId":"ch_work_nvlt_3","text":"又曰：女夷鼓歌，以司天和，以養百穀禽獸草木。［女夷，主春夏長養之神。］","sortOrder":21},
  {"id":"s_work_nvlt_3_22","chapterId":"ch_work_nvlt_3","text":"又曰：孟春之月，東宮御女青色，衣青采，鼓琴瑟。","sortOrder":22},
  {"id":"s_work_nvlt_3_23","chapterId":"ch_work_nvlt_3","text":"《說苑》曰：管仲曰：吾窮必矣，吾不能以春風風人，不能以夏雨雨人，吾窮必矣。","sortOrder":23},
  {"id":"s_work_nvlt_3_24","chapterId":"ch_work_nvlt_3","text":"《京房占》曰：春當退貪殘，進柔良，恤幼孤，赈不足，求隱士，則萬物應節而生，隨氣而長，所謂春令也。","sortOrder":24},
  {"id":"s_work_nvlt_3_25","chapterId":"ch_work_nvlt_3","text":"又曰：正月建寅，律為太蔟，雞雉孳尾，招搖生聚，少陽解冻，其氣溫柔，逆之則寒。","sortOrder":25},
  {"id":"s_work_nvlt_3_26","chapterId":"ch_work_nvlt_3","text":"《白虎通》曰：嫁娶以春何也，春天地交通，物始生，陰陽交接之時也。","sortOrder":26},
  {"id":"s_work_nvlt_3_27","chapterId":"ch_work_nvlt_3","text":"《臨海異物志》曰：鶗窸，一名田鵑，春三月鳴，晝夜不止，音聲自呼，俗言取梅子，涂其口兩邊皆赤，上天自言乞思，［《太平御覽》十九作恩。］至當麥［御覽作陆。］子熟，鳴乃止耳。","sortOrder":27},
  {"id":"s_work_nvlt_3_28","chapterId":"ch_work_nvlt_3","text":"《漢書》曰：孟春之月，群居者將散，行人振木铎徇於路，以采詩，獻之太師，比其音律，以聞於天子。","sortOrder":28},
  {"id":"s_work_nvlt_3_29","chapterId":"ch_work_nvlt_3","text":"《東觀漢記》曰：梁鸿將之會稽，作詩曰：維季春兮華色，麥含金兮方秀。","sortOrder":29},
  {"id":"s_work_nvlt_3_30","chapterId":"ch_work_nvlt_3","text":"《續漢禮儀志》曰：立春之日，京都百官，皆衣青衣，立青幡，施土牛耕人於門外。","sortOrder":30},
  {"id":"s_work_nvlt_3_31","chapterId":"ch_work_nvlt_3","text":"又曰：立春之日，下宽大書曰：方春東作，敬始慎微，罪殊死，且勿案验，皆須麥秋，退貪殘，進柔良。","sortOrder":31},
  {"id":"s_work_nvlt_3_32","chapterId":"ch_work_nvlt_3","text":"《博物志》曰：宋國有田夫，常衣黂缊以過冬，暨春東作，自暴於日，不知天下之有廣厦隩室，綿纊狐貉，顧其妻曰：負日之暄，人莫知者，以獻吾君，將有賞。","sortOrder":32},
  {"id":"s_work_nvlt_3_33","chapterId":"ch_work_nvlt_3","text":"《楚辭》曰：獻歲發春兮，汨吾南征，菉蘋齊葉兮白芷生，湛湛江水兮上有楓，目極千里兮傷春心。","sortOrder":33},
  {"id":"s_work_nvlt_3_34","chapterId":"ch_work_nvlt_3","text":"又曰：开春發［楚辭九章發下有歲字。］兮，白日出之悠悠，吾且荡志而愉樂兮，遵江夏以娱忧。","sortOrder":34},
  {"id":"s_work_nvlt_3_35","chapterId":"ch_work_nvlt_3","text":"又曰：王孫遊兮不歸，春草生兮萋萋。","sortOrder":35},
  {"id":"s_work_nvlt_3_36","chapterId":"ch_work_nvlt_3","text":"又曰：青春受謝白日昭，春氣奋發萬物遽。","sortOrder":36},
  {"id":"s_work_nvlt_3_37","chapterId":"ch_work_nvlt_3","text":"【詩】晉陆機詩曰：節運同可悲，莫若春氣甚，和風未及燠，遺涼清且凛。","sortOrder":37},
  {"id":"s_work_nvlt_3_38","chapterId":"ch_work_nvlt_3","text":"晉張协雜詩曰：大昊啟東節，春郊禮青祗，鷹化日夜分，雷動寒暑離，飛泽洗冬條，浮飆解春澌，采虹纓高雲，文虬鳴陰池，冲氣扇九垠，蒼生衍四垂，時至萬實成，化周天地移。","sortOrder":38},
  {"id":"s_work_nvlt_3_39","chapterId":"ch_work_nvlt_3","text":"晉郭璞詩曰：青陽畅和氣，穀風穆以溫，英茝晔林薈，崑虫鹹啟門，高台臨迅流，四坐列王孫，羽蓋停雲陰，翠鬱映玉樽。","sortOrder":39},
  {"id":"s_work_nvlt_3_40","chapterId":"ch_work_nvlt_3","text":"晉顧凯之神情詩曰：春水滿四泽，夏雲多奇峰，秋月扬明辉，冬嶺秀寒松。［摘句。］","sortOrder":40},
  {"id":"s_work_nvlt_3_41","chapterId":"ch_work_nvlt_3","text":"梁簡文帝春日想上林詩曰：春風本自奇，楊柳最相宜，柳葉恒著地，楊花好上吹，處處春心動，常惜光陰移，西京董賢馆，南宛習都［按據襄陽記，當作鬱。］池，行間魚共樂，桃上鳥相窥，香車雲母幰，駃馬黃金羁。","sortOrder":41},
  {"id":"s_work_nvlt_3_42","chapterId":"ch_work_nvlt_3","text":"又晚春時詩曰：紫蘭葉初滿，娇鶯弄不稀，石蹲還似獸，萝長更勝衣，水冻文鰩聚，山瞑雅鳥飛，渚蒲变新節，巖桐長舊围，風花落未已，山斋开夜扉。","sortOrder":42},
  {"id":"s_work_nvlt_3_43","chapterId":"ch_work_nvlt_3","text":"又春日看梅詩曰：昨日看梅树，新花已自生，今旦聞春鳥，何啻兩三聲，冻解池开渌，雲穿天半晴，遊心不應動，為此欲逢迎。","sortOrder":43},
  {"id":"s_work_nvlt_3_44","chapterId":"ch_work_nvlt_3","text":"又晚日後堂詩曰：幔陰通碧砌，日影度城隅，岸柳垂長葉，窗桃落細跗，花留蛱蝶粉，竹翳蜻蜓珠，賞心無與共，染翰獨踟蹰。","sortOrder":44},
  {"id":"s_work_nvlt_3_45","chapterId":"ch_work_nvlt_3","text":"又春日詩曰：花开幾千葉，水覆數重衣，蝶颺萦空舞，燕作同心飛，歌妖弄曲罢，鄭女挟琴歸。","sortOrder":45},
  {"id":"s_work_nvlt_3_46","chapterId":"ch_work_nvlt_3","text":"又春日詩曰：年還樂應滿，春歸思复生，桃含可怜紫，柳發斷腸情，落花隨燕入，遊絲帶蝶驚，邯鄲歌管地，見許欲留情。","sortOrder":46},
  {"id":"s_work_nvlt_3_47","chapterId":"ch_work_nvlt_3","text":"梁元帝春日詩曰：春還春節美，春日春風過，春心日日異，春情處處多，處處春芳動，日日春禽变，春意春已繁，春人春不見，不見懷春人，徒望春光新，春愁春自結，春結詎能申，欲道春園趣，复憶春時人，春人竟何在，空爽上春期，獨念春花落，還似昔春時。","sortOrder":47},
  {"id":"s_work_nvlt_3_48","chapterId":"ch_work_nvlt_3","text":"梁沈約詠春初詩曰：扶道觅陽春，相將共携手，草色猶自腓，林中都未有，無事逐梅花，空交信楊柳，且复歸去來，含情寄杯酒。","sortOrder":48},
  {"id":"s_work_nvlt_3_49","chapterId":"ch_work_nvlt_3","text":"又春詠曰：楊柳亂如絲，綺羅不自持，春草复黃绿，客心傷此時，青苔已結洧，碧水复盈淇，日華照趙瑟，風心動燕姬，襟中萬行淚，故是一相思。","sortOrder":49},
  {"id":"s_work_nvlt_3_50","chapterId":"ch_work_nvlt_3","text":"梁吳筠［按當作均，後同。］春詩曰：春從何處來，拂水复驚梅，雲彰青琐闼，風吹承露台，美人隔千里，羅帷閉不开，無由得共語，空對相思杯。","sortOrder":50},
  {"id":"s_work_nvlt_3_51","chapterId":"ch_work_nvlt_3","text":"梁王僧孺寄乡友詩曰：旅心已多恨，春至尚離群，翠枝結斜影，绿水散圓文，戲魚兩相顧，遊鳥半藏雲，何時不悯默，是日最思君。","sortOrder":51},
  {"id":"s_work_nvlt_3_52","chapterId":"ch_work_nvlt_3","text":"又春思絕句詩曰：雪罢枝即青，冰开水便绿，复聞黃鳥聲，全作相思曲。","sortOrder":52},
  {"id":"s_work_nvlt_3_53","chapterId":"ch_work_nvlt_3","text":"梁萧子范春望古意詩曰：光景斜漢宮，橫梁照采虹，春情寄柳色，鳥語出梅中，氛氲閨里思，逶迤水上風，落花徒入戶，何解妾床空。","sortOrder":53},
  {"id":"s_work_nvlt_3_54","chapterId":"ch_work_nvlt_3","text":"梁王筠春日詩曰：金堤草非舊，玉池泉已新，風生似羊［原訛牛，據冯校本改。］角，雲上若魚鱗，幽閨多怨思，停織坐娇春，芳華既零落，方作向隅人。","sortOrder":54},
  {"id":"s_work_nvlt_3_55","chapterId":"ch_work_nvlt_3","text":"梁萧瑱春日貽劉孝綽詩曰：涧水初流碧，山櫻早發紅，新禽爭弄响，落蕊亂從風，拂筵多软幹，映戶悉花丛，誰雲相去遠，垂柳對高桐。","sortOrder":55},
  {"id":"s_work_nvlt_3_56","chapterId":"ch_work_nvlt_3","text":"梁庾肩吾詩曰：桃紅柳絮白，照日复隨風，影出朱城外，香歸青殿中，水映寄生竹，山橫半死桐，頒文知渥重，搦札愧才空。","sortOrder":56},
  {"id":"s_work_nvlt_3_57","chapterId":"ch_work_nvlt_3","text":"梁鮑泉奉和湘東王春日詩曰：新燕始新歸，新蝶复新飛，新花滿新树，新月麗新辉，新光新氣早，新望新盈抱，新水新绿浮，新禽新聽好，新景自新還，新葉复新攀，新枝雖可結，新愁詎解顏，新思獨氛氲，新知不可聞，新扇如新月，新蓋學新雲，新落連珠淚，新點石榴裙。","sortOrder":57},
  {"id":"s_work_nvlt_3_58","chapterId":"ch_work_nvlt_3","text":"梁聞人蒨春日詩曰：高台動春色，清池映日華，绿葵向光轉，翠柳逐風斜，林有鳴心鳥，園多奪目花，相與鹹知節，叹子獨離家。","sortOrder":58},
  {"id":"s_work_nvlt_3_59","chapterId":"ch_work_nvlt_3","text":"周庾信詠春詩曰：昨夜鳥聲春，驚鳴動四鄰，今朝梅树下，定有詠花人，流星浮酒泛，粟瑱繞杯唇，何勞一片雨，唤作陽台神。","sortOrder":59},
  {"id":"s_work_nvlt_3_60","chapterId":"ch_work_nvlt_3","text":"又曰：逍遙遊桂苑，寂絕想桃源，狹石分花迳，長桥映水門，管聲驚百鳥，人衣香一園，定知歡未足，橫琴坐树根。","sortOrder":60},
  {"id":"s_work_nvlt_3_61","chapterId":"ch_work_nvlt_3","text":"陳徐陵詩曰：岸煙起暮色，岸水帶斜暉，迳狹橫枝度，帘搖驚燕飛，落花承步履，流涧寫行衣，何殊九芝蓋，薄暮洞庭歸。","sortOrder":61},
  {"id":"s_work_nvlt_3_62","chapterId":"ch_work_nvlt_3","text":"隋江總山庭春詩曰：洗沐唯五日，栖遲在一丘，古楂橫近涧，危石耸前洲，峰绿开河柳，池紅照海榴，野花寧待晦，山虫詎識秋，人生复能幾，夜燭非長遊。","sortOrder":62},
  {"id":"s_work_nvlt_3_63","chapterId":"ch_work_nvlt_3","text":"【賦】晉傅玄陽春賦曰：虛心定乎昏中，龍星正乎春辰，嘉勾芒之統時，宣太皞之威神，素冰解而泰液洽，玄獭祭而雁北征，幽蟄蠢動，萬物樂生，依依楊柳，翩翩浮萍，桃之夭夭，灼灼其榮，繁華燁而燿野，煒芬葩而扬英，鵲營巢於高树，燕衔泥於廣庭，睹戴勝之止桑，聆布穀之晨鳴，習習穀風，洋洋绿泉，丹霞橫景，文虹竟天。","sortOrder":63},
  {"id":"s_work_nvlt_3_64","chapterId":"ch_work_nvlt_3","text":"晉湛方生懷春賦曰：夫榮彫之感人，猶色象之在鏡，事隨化而遷回，心無主而虛映，眄秋林而情悲，遊春泽而心恧，雖四時之平分，何陽節之清淑，日婉娈以舒和，氣有仁而無肅，雷發乡於南山，雨漸泽於四溟，啟潛蟄於九泉，收靈蛇於天庭，修虹煥绿以東冏，幽涧泮冰而流清，鸿飄翮於歸風，燕衔泥而來征，鷙鳥感仁而革性，鶗窸乘化而变聲，麥芃芃而含秀，桑藹藹而敷榮。","sortOrder":64},
  {"id":"s_work_nvlt_3_65","chapterId":"ch_work_nvlt_3","text":"周庾信春賦曰：宜春苑中春已歸，披香殿里作春衣，新年鳥聲千种啭，二月楊花滿路飛，河陽一縣併是花，金穀從來滿園树，一丛香草足礙人，數尺遊絲即橫路，苔始绿而藏魚，麥才青而覆雉，吹箫弄玉之台，鳴珮陵波之水，移戚里之家富，入新丰而酒美，石榴聊泛，蒲桃酦醅，芙蓉玉碗，莲子金杯，新芽竹筍，細核楊梅，绿珠捧琴至，文君送酒來，玉管初調，鳴絃暫撫，陽春绿水之曲，對鳳回鸞之舞，更炙笙簧，還移筝柱，月入歌扇，花承節鼓，协律都尉，射雉中郎，停車小苑，連騎長楊，金鞍始被，柘月新張，拂尘看馬埒，分朋入射堂，馬是天池之龍种，帶乃荆山之玉梁，艳錦安天鹿，新綾織鳳皇，三日曲水向河津，日晚河邊多解神，树下流杯客，沙頭度水人，鏤薄窄衫袖，穿珠帖領巾，百丈山頭日欲斜，三晡未醉莫還家，池中水影懸勝鏡，屋里衣香不如花。","sortOrder":65},
  {"id":"s_work_nvlt_3_66","chapterId":"ch_work_nvlt_3","text":"晉夏侯湛春可樂曰：春可樂兮，樂東作之良時，嘉新田之啟萊，悅中畴之發菑，桑冉冉以奋條，麥遂遂以扬秀，泽苗翳渚，原卉耀阜，春可樂兮，樂崇陆之可娱，登夷岡以回眺，超矯駕乎山嵎，缀雜華以為蓋，集繁蕤以飾裳，散風衣之馥氣，納戢懷之潛芳，鸚交交以弄音，翠翾翾以輕翔，招君子以偕樂，携淑人以微行。","sortOrder":66},
  {"id":"s_work_nvlt_3_67","chapterId":"ch_work_nvlt_3","text":"晉王廙春可樂曰：春可樂兮，樂孟月之初陽，冰泮涣以微流，土冒橛而解刚。野暄卉以揮绿，山葱蒨以發蒼。","sortOrder":67},
  {"id":"s_work_nvlt_3_68","chapterId":"ch_work_nvlt_3","text":"晉李顒悲四時曰：悲春日兮，悲陽泽之方宣，建靈威以延蟄，叩東震而响天。布和氣之煙煴，舒朗景之淑鮮，雲興滋於秀石，飆鳴柯於崇山，平皋眇莽，中林葱青，野馬飛涧，晨虹垂旌，陽燕南徂，陰雁北征，素華浩浩，丹秀熒熒。","sortOrder":68},
  {"id":"s_work_nvlt_3_70","chapterId":"ch_work_nvlt_3","text":"《爾雅》曰：夏為朱明，一曰長嬴。","sortOrder":70},
  {"id":"s_work_nvlt_3_71","chapterId":"ch_work_nvlt_3","text":"《尸子》曰：夏為樂，南方為夏，夏，興也，南，任也，是故萬物莫不任興，蕃殖充盈，樂之至也。","sortOrder":71},
  {"id":"s_work_nvlt_3_72","chapterId":"ch_work_nvlt_3","text":"《尚書》曰：申命羲叔，宅南交，日永星火，以正仲夏，鳥獸希革。","sortOrder":72},
  {"id":"s_work_nvlt_3_73","chapterId":"ch_work_nvlt_3","text":"《周書·時訓》曰：夏至之日，鹿角解，蜩始鳴，大暑之日，腐草化為螢。","sortOrder":73},
  {"id":"s_work_nvlt_3_74","chapterId":"ch_work_nvlt_3","text":"《禮記》曰：孟夏月，盛德在火，天子迎夏於南郊，還反，行賞，封諸侯，慶賜遂行，靡草死，麥秋至，斷薄刑，决小罪，仲夏之月，天子羞以含桃，先荐寢廟，日長至，陰陽爭，君子處必掩身，無躁，蝉始鳴，木槿榮，可以居高明，可以遠眺望，可以升山陵，可以處台榭，季夏之月，溫風始至，蟋蟀居壁，鷹乃學習，腐草化為螢。","sortOrder":74},
  {"id":"s_work_nvlt_3_75","chapterId":"ch_work_nvlt_3","text":"又曰：南方者夏，夏之為言假也，養之長之，假之仁也。","sortOrder":75},
  {"id":"s_work_nvlt_3_76","chapterId":"ch_work_nvlt_3","text":"尚書考靈耀曰：火星為夏期，专陽相［御覽二十一相下有助字。］同精感符。","sortOrder":76},
  {"id":"s_work_nvlt_3_77","chapterId":"ch_work_nvlt_3","text":"《易通卦验》曰：離，南方也，主夏，日中赤氣出，直離，此正氣，出右，萬物半死，氣出左，赤地千里。","sortOrder":77},
  {"id":"s_work_nvlt_3_78","chapterId":"ch_work_nvlt_3","text":"《詩含神霧》曰：曹，地處季夏之位，土地劲急，音中徵，其聲清以急。","sortOrder":78},
  {"id":"s_work_nvlt_3_79","chapterId":"ch_work_nvlt_3","text":"太公《金匮》曰：紂嘗以六月獵於西土，發民逐禽，民諫曰：今六月，天務覆施，地務長養，今盛夏發民逐禽，而元元懸於野，君踐一日之苗，而民百日不食，天子失道，後必無福，紂以為妖言而誅之，後數月，天暴風雨，發屋折树。","sortOrder":79},
  {"id":"s_work_nvlt_3_80","chapterId":"ch_work_nvlt_3","text":"皇覽《逸禮》曰：夏則衣赤衣，佩赤玉，乘赤辂，駕赤龍，載赤旗，以迎夏於南郊，其祭。］先黍與雞，居明堂正廟，啟南戶。","sortOrder":80},
  {"id":"s_work_nvlt_3_81","chapterId":"ch_work_nvlt_3","text":"孝經緯，周天七衡六間，曰穀雨，後十五日，斗指戊，東南維，為立夏，後十五日，斗指己，以為小滿。","sortOrder":81},
  {"id":"s_work_nvlt_3_82","chapterId":"ch_work_nvlt_3","text":"《管子》曰：夏至而麥熟，天子祀太宗，其盛以麥，穀之始也。","sortOrder":82},
  {"id":"s_work_nvlt_3_83","chapterId":"ch_work_nvlt_3","text":"《淮南子》曰：孟夏之月，南宮御女，赤色赤衣，吹竽笙。","sortOrder":83},
  {"id":"s_work_nvlt_3_84","chapterId":"ch_work_nvlt_3","text":"又曰：邹衍事燕惠王盡忠，左右谮之，王系之，仰天而哭，夏五月，為之下霜。","sortOrder":84},
  {"id":"s_work_nvlt_3_85","chapterId":"ch_work_nvlt_3","text":"又陽氣為火，陰氣為水，水勝故夏至溫，火勝故冬至燥，八尺之表，景修尺五寸，景修則陰氣勝，短則陽氣勝，陰氣勝則為水，陽氣勝則為旱。","sortOrder":85},
  {"id":"s_work_nvlt_3_86","chapterId":"ch_work_nvlt_3","text":"《文子》曰：政失於夏，熒惑逆行，夏政不失，降雨時。","sortOrder":86},
  {"id":"s_work_nvlt_3_87","chapterId":"ch_work_nvlt_3","text":"續漢書律歷志曰：日行南陆謂之夏。","sortOrder":87},
  {"id":"s_work_nvlt_3_88","chapterId":"ch_work_nvlt_3","text":"蔡邕《獨斷》曰：夏至陰氣始起，麋鹿解角，故寢兵鼓，身欲寧，志欲靜，故不聽事。","sortOrder":88},
  {"id":"s_work_nvlt_3_89","chapterId":"ch_work_nvlt_3","text":"《續漢禮儀志》曰：夏至日，浚井改水，冬至日，鑽燧改火。","sortOrder":89},
  {"id":"s_work_nvlt_3_90","chapterId":"ch_work_nvlt_3","text":"《五經通義》曰：夏至陰始動，未達，故寢兵鼓，不設政事，所以助養陰氣也，易曰：先王以至日閉關，後不省方，以此助之。","sortOrder":90},
  {"id":"s_work_nvlt_3_91","chapterId":"ch_work_nvlt_3","text":"《楚辭》曰：滔滔孟夏，草木莽莽。","sortOrder":91},
  {"id":"s_work_nvlt_3_92","chapterId":"ch_work_nvlt_3","text":"又曰：收恢台之盛夏。","sortOrder":92},
  {"id":"s_work_nvlt_3_93","chapterId":"ch_work_nvlt_3","text":"【詩】晉郭璞詩曰：羲和聘丹衢，朱明赫其猛，融風拂晨霄，陽精一何冏，閒宇靜無娱，端坐愁日永。","sortOrder":93},
  {"id":"s_work_nvlt_3_94","chapterId":"ch_work_nvlt_3","text":"晉李顒詩曰：炎光燦南溟，溽暑融三夏，黮｛雨對｝重雲荫，砰稜震雷吒。","sortOrder":94},
  {"id":"s_work_nvlt_3_95","chapterId":"ch_work_nvlt_3","text":"宋顏延之夏夜呈從兄散騎詩曰：炎天方埃鬱，暑晏阕尘紛，獨靜闕隅座，臨堂對星分，侧聽風薄木，遙睇月开雲，夜蝉當夏急，陰虫先秋聞，歲候初過半，荃蕙豈久芬。","sortOrder":95},
  {"id":"s_work_nvlt_3_96","chapterId":"ch_work_nvlt_3","text":"齊謝朓出下馆詩曰：麥候始清和，涼雨銷炎燠，紅莲搖弱荇，丹藤繞新竹，物色盈懷抱，方駕娱耳目。","sortOrder":96},
  {"id":"s_work_nvlt_3_97","chapterId":"ch_work_nvlt_3","text":"梁萧子范夏夜獨坐詩曰：節序值徂炎，茲宵在三伏，冯軒佇涼氣，中筵倦煩燠，寂漠對空窗，清疏臨夜竹，虫音亂階草，螢光繞庭木，帘月渡斜辉，風花起餘馥，一傷年志罢，長嗟逝波速。","sortOrder":97},
  {"id":"s_work_nvlt_3_98","chapterId":"ch_work_nvlt_3","text":"【賦】晉傅玄述夏賦曰：四月惟夏，運臻正陽，和氣穆而扇物，麥含露而飛芒，清徵泛於琴瑟，朱鳥感於炎荒，鹿解角於中野，草木蔚其條長。","sortOrder":98},
  {"id":"s_work_nvlt_3_99","chapterId":"ch_work_nvlt_3","text":"梁江淹四時賦曰：至如［如字據冯校本補。］炎雲峰起，芳树未移，皋蘭生坂，朱荷出池，憶上國之綺树，想金陵之蕙枝。","sortOrder":99},
  {"id":"s_work_nvlt_3_100","chapterId":"ch_work_nvlt_3","text":"晉李顒悲四時賦曰：悲炎節之赫羲，覽祝融之御辔，遊井耀兮南離，睎辰凯之長吹，荫绿柳之楊枝，雲鬱律以泉涌，雨淋澡而方簁，奋駭霆之奔磕，舒驚電之橫摛。","sortOrder":100},
  {"id":"s_work_nvlt_3_102","chapterId":"ch_work_nvlt_3","text":"《爾雅》曰：秋為白藏，一曰收成。","sortOrder":102},
  {"id":"s_work_nvlt_3_103","chapterId":"ch_work_nvlt_3","text":"《禮記》曰：孟秋之月，涼風至，白露降，寒蝉鳴，鷹乃祭鳥，仲秋之月，鸿雁來，玄鳥歸，群鳥養羞，季秋之月，鸿雁來賓，雀入大水為蛤，菊有黃花，豺乃祭獸。","sortOrder":103},
  {"id":"s_work_nvlt_3_104","chapterId":"ch_work_nvlt_3","text":"《尸子》曰：秋為禮，西方為秋，秋，肅也，萬物莫不禮肅，敬之至也。","sortOrder":104},
  {"id":"s_work_nvlt_3_105","chapterId":"ch_work_nvlt_3","text":"《毛詩》曰：秋日凄凄，百草具腓。","sortOrder":105},
  {"id":"s_work_nvlt_3_106","chapterId":"ch_work_nvlt_3","text":"又曰：一日不見，如三秋兮。","sortOrder":106},
  {"id":"s_work_nvlt_3_107","chapterId":"ch_work_nvlt_3","text":"《春秋考異郵》曰：立秋趣織鳴。","sortOrder":107},
  {"id":"s_work_nvlt_3_108","chapterId":"ch_work_nvlt_3","text":"《尚書》曰：分命和仲，宅西，曰昧穀，寅餞納日，平秩西成，宵中星虛，以殷仲秋。","sortOrder":108},
  {"id":"s_work_nvlt_3_109","chapterId":"ch_work_nvlt_3","text":"《周書·時訓》曰：立秋之日，涼風至，後五日，白露降，後五日，寒蜩鳴，涼風不至，國無嚴政，白露不降，民多欬病，寒蜩不鳴，人臣力爭，白露之日，鸿雁來，後五日，玄鳥歸，後五日，群鳥養羞，鸿雁不來，遠人背叛，玄鳥不歸，室家離散，群鳥不羞，臣下驕慢，秋分之日，雷乃始收，後五日，蟄虫坯戶，後五日，水始涸，雷乃不收，諸侯淫汰，蟄虫不坯，民靡有賴，水不始涸，介虫為害。","sortOrder":109},
  {"id":"s_work_nvlt_3_110","chapterId":"ch_work_nvlt_3","text":"《周官》曰：司裘，掌為大裘，以供王祀天之服，仲秋獻良裘，季秋獻功裘。","sortOrder":110},
  {"id":"s_work_nvlt_3_111","chapterId":"ch_work_nvlt_3","text":"又曰：籥章，掌仲秋击土鼓，籥豳詩，以迎寒。","sortOrder":111},
  {"id":"s_work_nvlt_3_112","chapterId":"ch_work_nvlt_3","text":"皇覽《逸禮》曰：秋則衣白衣，佩白玉，乘白辂，駕白骆，載白旗，以迎秋於西郊。","sortOrder":112},
  {"id":"s_work_nvlt_3_113","chapterId":"ch_work_nvlt_3","text":"《詩含神霧》曰：秦，地處仲秋之位，男懦弱，女高膫，白色秀身，音中商，其言舌舉而仰，聲清以扬。","sortOrder":113},
  {"id":"s_work_nvlt_3_114","chapterId":"ch_work_nvlt_3","text":"《文子》曰：日月欲明，浮雲蓋之，丛蘭欲修，秋風败之。","sortOrder":114},
  {"id":"s_work_nvlt_3_115","chapterId":"ch_work_nvlt_3","text":"《淮南子》曰：孟秋之月，西宮御女白色，衣白采，撞白鍾，其兵鉞，其畜狗，八月官尉，其树柘，九月官候，其树槐。","sortOrder":115},
  {"id":"s_work_nvlt_3_116","chapterId":"ch_work_nvlt_3","text":"《漢書》曰：孫寶［原訛實，據本書九十一卷鷹篇引改。］為京兆尹，以立秋日，署侯文為東部督郵，入見，敕曰：今鷹隼始击，當從天氣，取奸惡，以成嚴霜之誅，掾部其有人乎。","sortOrder":116},
  {"id":"s_work_nvlt_3_117","chapterId":"ch_work_nvlt_3","text":"《尚書考靈耀》曰：虛星為秋候，昴為冬期，陰氣相佐，德乃不邪，子助母收，母合子符，［虛星，北方宿也，昴星，西方宿也，陰稱母也。］","sortOrder":117},
  {"id":"s_work_nvlt_3_118","chapterId":"ch_work_nvlt_3","text":"續漢禮儀志曰：立秋之日，白郊畢，始扬武，斬牲於郊東門，以荐陵廟，其儀。］乘舆御戎辂，白馬朱鬛，騁，執弩射牲，牡［續漢志作牲。］以鹿麛，太宰令謁者各一人，載獲車，馳驷送陵廟，還宮，遣使者赍束帛，以賜武官，肆兵，習戰陣之儀，斬牲之禮，名曰貙劉。","sortOrder":118},
  {"id":"s_work_nvlt_3_119","chapterId":"ch_work_nvlt_3","text":"《世說》曰：張季鷹辟齊王東曹掾，在洛，見秋風起，因思吳莼菜羹鱸魚鱠，曰：人生貴適志耳，何能從宦數千里，以要名爵，遂命駕便歸，俄而齊王败，時人皆謂之為見機而作。","sortOrder":119},
  {"id":"s_work_nvlt_3_120","chapterId":"ch_work_nvlt_3","text":"《楚辭·九懷》曰：秋風兮萧萧，舒芳兮振條。","sortOrder":120},
  {"id":"s_work_nvlt_3_121","chapterId":"ch_work_nvlt_3","text":"又曰：悲哉，秋之為氣也，萧瑟兮草木搖落而变衰，憭栗兮若在遠行，登山臨水兮送將歸，穴寥兮天高而氣清，寂惨兮收潦而水清。","sortOrder":121},
  {"id":"s_work_nvlt_3_122","chapterId":"ch_work_nvlt_3","text":"又曰：裊裊兮秋風，洞庭波兮木葉下。","sortOrder":122},
  {"id":"s_work_nvlt_3_123","chapterId":"ch_work_nvlt_3","text":"又曰：皇天平分四時兮，竊獨悲此凛秋，白露既下降百草兮，淹離被此梧楸。","sortOrder":123},
  {"id":"s_work_nvlt_3_124","chapterId":"ch_work_nvlt_3","text":"又曰：秋既先戒以白露兮，冬又申之以嚴霜。","sortOrder":124},
  {"id":"s_work_nvlt_3_125","chapterId":"ch_work_nvlt_3","text":"《淮南子》曰：春女悲，秋士哀，知物化矣。","sortOrder":125},
  {"id":"s_work_nvlt_3_126","chapterId":"ch_work_nvlt_3","text":"《風土記》曰：鳴鶴戒露，白鶴也，此鳥性儆，至八月，白露降，即高鳴相儆。","sortOrder":126},
  {"id":"s_work_nvlt_3_127","chapterId":"ch_work_nvlt_3","text":"【詩】晉左思雜詩曰：秋風何烈烈，白露為朝霜，柔條旦夕劲，绿葉日夜黃，明月出雲崖，皎皎流素光，披軒臨前庭，嗷嗷晨雁翔。","sortOrder":127},
  {"id":"s_work_nvlt_3_128","chapterId":"ch_work_nvlt_3","text":"晉孫綽詩曰：萧瑟仲秋月，飆唳風雲高，山居感時变，遠客興長謠，疏林積涼風，虛岫結凝霄，湛露洒庭林，密葉辭榮條，撫葉悲先落，攀松羨後凋。","sortOrder":128},
  {"id":"s_work_nvlt_3_129","chapterId":"ch_work_nvlt_3","text":"晉江逌詩曰：祝融解炎辔，蓐收起涼駕，高風催節变，凝露督物化，長林悲素秋，茂草思朱夏，鳴雁薄雲嶺，蟋蟀吟深榭，寒蝉向夕號，驚飆激中夜。","sortOrder":129},
  {"id":"s_work_nvlt_3_130","chapterId":"ch_work_nvlt_3","text":"宋孝武初秋詩曰：夏盡炎氣微，火息涼風生，绿草未傾色，白露已盈庭，遠视秋雲發，近聽寒蝉鳴，運移矜物化，川上感餘情。","sortOrder":130},
  {"id":"s_work_nvlt_3_131","chapterId":"ch_work_nvlt_3","text":"又秋夜詩曰：局景薄西隅，升月照東垂，肅肅風盈幕，泫泫露傾枝，侧聞飛壶急，坐見河宿移，睹辰念節变，感物矜乖離。","sortOrder":131},
  {"id":"s_work_nvlt_3_132","chapterId":"ch_work_nvlt_3","text":"宋謝惠連懷秋詩曰：平生無志意，少小婴忧患，如何乘［冯校本作辛。］苦心，矧复值秋晏，皎皎天月明，弈弈河宿烂，萧瑟含風蝉，寥唳度雲雁，寒商動清閨，孤燈暧幽幔，耿介繁慮積，展轉長宵半，夷陰難豫謀，倚伏昧前筭，未知古人心，且從性所玩，賓至可命觴，朋來當染翰，頹魄不再圓，傾羲無兩旦，金石終銷毀，丹青蹔彫煥，各勉玄發歡，無貽白首叹。","sortOrder":132},
  {"id":"s_work_nvlt_3_133","chapterId":"ch_work_nvlt_3","text":"宋南平王劉鑠歌詩曰：昊天清且高，秋氣發初涼，白露下微津，明月流素光，凝煙泛城闕，凄風入軒房，朱華先零落，绿草就芸黃，纖羅還笥箧，輕紈改衣裳。","sortOrder":133},
  {"id":"s_work_nvlt_3_134","chapterId":"ch_work_nvlt_3","text":"宋鮑照秋日詩曰：枯枝葉易零，疲客心易驚，今茲亦何早，已聞絡緯鳴，回風滅且起，卷蓬息复征，凄凄簟上寒，栗栗帳里清，物色延暮思，霜露逼朝榮，白楊方萧瑟，長叹從此生。","sortOrder":134},
  {"id":"s_work_nvlt_3_135","chapterId":"ch_work_nvlt_3","text":"宋湯惠休歌詩曰：秋風裊裊入曲房，羅帳含月思心傷，蟋蟀夜鳴斷人腸，長夜思君心飛扬，他人相思君相忘，錦衾瑤席為誰芳。","sortOrder":135},
  {"id":"s_work_nvlt_3_136","chapterId":"ch_work_nvlt_3","text":"又歌思引曰：秋寒依依風過河，白露萧萧洞庭波，思君末光光已滅，眇眇悲望如思何。","sortOrder":136},
  {"id":"s_work_nvlt_3_137","chapterId":"ch_work_nvlt_3","text":"梁簡文帝秋詩曰：羽翣晨猶動，珠汗晝恒揮，秋風忽裊裊，向夕引涼歸，浮陰即染浪，清氣始乘衣，卷幌通河色，开窗引月暉，晚花欄下照，疏螢簟上飛，直置猶如此，何况送將歸。","sortOrder":137},
  {"id":"s_work_nvlt_3_138","chapterId":"ch_work_nvlt_3","text":"又秋夜詩曰：高秋渡函穀，墜露下芳枝，绿潭倒雲氣，青山衔月規，花心風上轉，葉影树中危，外遊獨千里，夕叹誰共知。","sortOrder":138},
  {"id":"s_work_nvlt_3_139","chapterId":"ch_work_nvlt_3","text":"又秋夜詩曰：螢飛夜的的，虫思夕喓々，輕露沾懸井，浮煙入綺寮，簷重月没早，树密風聲饒，池莲翻罢葉，霜筱生寒條，端坐弥茲漏，離忧積此宵。","sortOrder":139},
  {"id":"s_work_nvlt_3_140","chapterId":"ch_work_nvlt_3","text":"又秋晚詩曰：浮雲出西嶺，落日下西江，促陰橫隱壁，長暉斜度窗，亂霞圓绿水，細葉影飛棋。","sortOrder":140},
  {"id":"s_work_nvlt_3_141","chapterId":"ch_work_nvlt_3","text":"梁萧晔奉和詩曰：副君乘暇景，臨秋坐北宮，杏梁照初月，莲池引夕風，清暉洞澡井，流香入綺籠，鵲聲時徙树，螢光乍滅空，涼氛散簟席，露色变林丛。","sortOrder":141},
  {"id":"s_work_nvlt_3_142","chapterId":"ch_work_nvlt_3","text":"梁范雲赠俊公道人詩曰：秋蓬飄秋甸，寒藻泛寒池，風條振風乡，霜葉斷霜枝，幸及清江滿，無使明月虧，月虧君不來，相期竟悠哉。","sortOrder":142},
  {"id":"s_work_nvlt_3_143","chapterId":"ch_work_nvlt_3","text":"梁沈約秋夜詩曰：月落宵向分，紫煙鬱氛氲，曀曀螢入霧，離離雁出雲，巴童闇理瑟，漢女夜縫裙，新知樂如是，久要詎相聞。","sortOrder":143},
  {"id":"s_work_nvlt_3_144","chapterId":"ch_work_nvlt_3","text":"梁庾肩吾奉和便省餘秋詩曰：前對金精坡，傍臨圓水池，照影礙浮葉，看山通回枝，雁行連霧盡，雨足帶雲移。","sortOrder":144},
  {"id":"s_work_nvlt_3_145","chapterId":"ch_work_nvlt_3","text":"梁吳筠秋念詩曰：团团珠暉轉，炤炤漢陰移，箕風入桂露，璧月滿瑤池，树青草未落，蝉涼葉已危，還深長夜想，顧憶臨邛卮，芳杜果芜没，纓帶欲何為。","sortOrder":145},
  {"id":"s_work_nvlt_3_146","chapterId":"ch_work_nvlt_3","text":"梁鮑泉秋日詩曰：露色已成霜，梧楸欲半黃，燕去朓恒靜，莲寒池不香，夕乌飛向月，餘蚊聚逐光，旅情恒自苦，秋夜漸應長。","sortOrder":146},
  {"id":"s_work_nvlt_3_147","chapterId":"ch_work_nvlt_3","text":"【賦】晉潘嶽秋興賦序曰：晉十有四年，餘春秋三十有二，始見二毛，以太尉掾寓直於散騎之省，高閣連雲，陽景罕曜，珥蝉冕而袭紈綺之士，此焉遊處，仆野人也，偃息不過茆屋茂林之下，談話不過農夫田父之客，攝官承乏，猥廁朝列，夙興晏寢，匪遑底寧，譬猶池魚籠鳥，而有江湖山藪之思，於是染翰操紙，慨然而賦，於時秋也，以秋興命篇，四運忽其代序，萬物紛以回薄，覽華蒔之時育，察盛衰之所讬，［原訛記，據冯校本改。］感冬索以春敷，嗟夏茂而秋落，雖末事之榮悴，伊人情之美惡，嗟秋日之可哀，良無愁而不盡，野有歸燕，隰有翔隼，遊氛朝興，槁葉夕殒，於是乃屏輕箑，釋纖絺，藉莞蒻，御袷衣，庭树槭以洒落，劲風戾而吹帷，蝉嘒嘒，以寒吟，雁飄飄而南飛，天晃朗而弥高，日悠陽而浸微，何微陽之短晷，覺涼夜之方永，月朣胧以含光，露凄清以凝冷，熠燿粲於階闼，蟋蟀鳴於軒屏，聽離鸿之晨吟，望流火之餘景，宵耿介而不寐，獨展轉於華省，悟歲時之遒盡兮，慨府首而自省，班鬢彪以承弁兮，素發飒以垂領，且斂衽以歸來兮，忽投绂以高厲，耕東皋之沃壤，输黍稷之餘稅，逍遙乎山川之阿，放曠乎人間之世，優哉遊哉，聊以卒歲。","sortOrder":147},
  {"id":"s_work_nvlt_3_148","chapterId":"ch_work_nvlt_3","text":"晉盧諶感運賦曰：朱明送夏，白藏迎秋，微涼漸屆，溽暑日收，氣掆々而浸冷。霜微微而日華，翠葉紛以朝落，朱華惨以夕捐。","sortOrder":148},
  {"id":"s_work_nvlt_3_149","chapterId":"ch_work_nvlt_3","text":"晉江逌述歸賦曰：時運逝其何速，素秋奄以告季，虛柳中於昏日，羲和宿於房位，微寒凄其薄人，凝霜粲兮朝墜，林飄飄以洒葉，隰芒芒而摧穟，菊發華於高丘，雁辭北以南莅。","sortOrder":149},
  {"id":"s_work_nvlt_3_150","chapterId":"ch_work_nvlt_3","text":"宋袁淑秋晴賦曰：是月也，聲晷合，朝夜分，霆收耀，虹戢文，炎都褰埃，旻寓涤氛，［原訛氣，據冯校本改。］曳悲泉之凝霧，轉絕垠之嚴雲。","sortOrder":150},
  {"id":"s_work_nvlt_3_151","chapterId":"ch_work_nvlt_3","text":"宋沈勃秋羁賦曰：於時朱雲弛辰，金祗御歲，菊圖縟於園沼，橘倒飾於池例，草改濬而傾蕡，林伐状而搖蒂，潭掆氣而威荷，露危光而嚴蕙。","sortOrder":151},
  {"id":"s_work_nvlt_3_152","chapterId":"ch_work_nvlt_3","text":"梁簡文帝秋興賦曰：秋何興而不盡，興何秋而不傷，傷二情之本背，更同來而匪方，复有登山望別，臨水送歸，洞庭之葉初下，塞外之草前衰，攸征人與行子，必承脸而霑衣，紛吾閒居有怡，優遊多暇，乃息書幌之勞，以命北園之駕，爾乃從玩池曲，遷坐林間，淹留而荫丹岫，徘徊而搴木蘭，為興未已，升彼懸崖，臨風長想，冯高俯窥，察遊魚之息涧，怜驚禽之換枝，聽夜签之响殿，聞懸魚之扣扉，將據梧於芳杜，欲留連而不歸。","sortOrder":152},
  {"id":"s_work_nvlt_3_153","chapterId":"ch_work_nvlt_3","text":"又臨秋賦曰：火歇兮秋氣生，風起兮秋潦清，覽時興而自得，聊飛辔而娱情。遵二條之廣路，背九仞之高城，爾乃登長坂，息餘骥，攬筆舒情，沉吟屬思，草色雜而香同，树影齊而花異，遙峰迢遰，萦沙斷絕，雲出山而相似，水含天而難別。","sortOrder":153},
  {"id":"s_work_nvlt_3_154","chapterId":"ch_work_nvlt_3","text":"梁江淹四時賦曰：及夫秋風一至，白露团团，明月生波，營［本集作螢。］光迎寒，眷庭中之梧楸，念機上之羅紈。","sortOrder":154},
  {"id":"s_work_nvlt_3_155","chapterId":"ch_work_nvlt_3","text":"晉夏侯湛秋可哀曰：秋可哀兮，哀秋日之萧條，火回景以西流，天既清而氣高，壤含素霜，山結玄霄，月延路以增夜，日遷行以收暉，屏絺綌於笥匣，納纶縞以授衣，秋可哀兮，哀新物之陳芜，綢筱朔以斂稀，密葉摵以陨疏，雁擢翼於太清，燕蟠形乎榛墟，秋可哀兮，哀良夜之遙長，月翳翳以隱雲，時籠籠以投光，映前軒之疏幌，炤後帷之閒房，拊輕衾而不寐，臨虛槛而褰裳，感時邁以興思，情怆怆以含傷。","sortOrder":155},
  {"id":"s_work_nvlt_3_156","chapterId":"ch_work_nvlt_3","text":"又秋夕哀曰：秋夕兮遙長，哀心兮永傷，結帷兮中宇，屣履兮閒房，聽蟋蟀之潛鳴，睹遊雁之雲翔，尋修庑之飛簷，覽明月之流光，木萧萧以被風，階縞縞以受霜，玉機兮環轉，四運兮骤遷，衔恤兮迄今，忽將兮涉年，日往兮哀深，歲暮兮思繁。","sortOrder":156},
  {"id":"s_work_nvlt_3_157","chapterId":"ch_work_nvlt_3","text":"晉湛方生秋夜詩［冯校本作清。］曰：悲九秋之為節，物凋悴而無榮，嶺頹鮮而殒绿，木傾柯而落英，履代謝以惆怅，睹搖落而興情，信皋壤而感人，樂未畢而哀生，秋夜清兮，何秋夕之轉長，夜悠悠而難極，月皦皦而停光，播商氣以清溫，扇高風以革涼，水激波以成涟，露凝結而為霜，凡有生而必凋，情何感而不傷，苟靈符之未虛，孰茲恋之可忘，何天懸之難釋，思假畅之冥方，拂尘衿於玄風，散近滯於老莊，攬逍遙之宏維，總齊物之大綱，同天地於一指，等大山於毫芒，萬慮一時頓渫，情累豁焉都忘，物我泯然而同體，豈复寿夭於彭殇。","sortOrder":157},
  {"id":"s_work_nvlt_3_158","chapterId":"ch_work_nvlt_3","text":"宋謝琨秋夜長曰：秋夜長兮，雖欣長而悼速，送晨暉於西嶺，迎夕景於東穀，夜既分而氣高，風入林而傷绿，燕翩翩以辭宇，雁邕邕而南屬。","sortOrder":158},
  {"id":"s_work_nvlt_3_159","chapterId":"ch_work_nvlt_3","text":"宋蘇彦秋夜長曰：晨暉電流以西逝，閒宵漫漫其未央，牛女隔河以延佇，列宿双景以相望，輕雲飄霏以籠朗，素月披曜而舒光，時禽鳴於庭柳，節虫吟於戶堂，零葉紛其交萃，落英飒以散芳，睹遷化之遒邁，悲榮枯之靡常，貞松隆冬以擢秀，金菊吐翘以凌霜。","sortOrder":159},
  {"id":"s_work_nvlt_3_160","chapterId":"ch_work_nvlt_3","text":"宋何瑾悲秋夜曰：欣莫欣兮春日，悲莫悲兮秋夜，伊之秋夜可悲，增沉懷於遠情，叹授衣於豳詩，感萧瑟於宋生，天廖廓兮高褰，氣凄肅兮厲清，燕溯陰兮歸飛，雁懷陽兮寒鳴，霜凝條兮漼漼，露霤葉兮泠泠。","sortOrder":160},
  {"id":"s_work_nvlt_3_161","chapterId":"ch_work_nvlt_3","text":"宋伏系之秋懷曰：於是景宇肅澄，風高木斂，凄氣夕衰，零露晨湛，泽收润而草枯，葉骤墜而庭掩，雁偕來以希陽，燕遊逝而投险，豈微物之足懷，傷頹齡之告漸。","sortOrder":161},
  {"id":"s_work_nvlt_3_163","chapterId":"ch_work_nvlt_3","text":"《爾雅》曰：冬為玄英，一曰安寧。","sortOrder":163},
  {"id":"s_work_nvlt_3_164","chapterId":"ch_work_nvlt_3","text":"《禮記》曰：孟冬之月，水始冰，地始冻，雉入大水為蜃，虹藏不見，仲冬之月，冰益壮，地始坼，鶡鳥不鳴，虎始交，荔挺出，丘蚓結，麋角解，水泉動，日短至，季冬之月，雁北向，鵲始巢，雉雊雞乳，日窮於次，月窮於紀，星回於天。","sortOrder":164},
  {"id":"s_work_nvlt_3_165","chapterId":"ch_work_nvlt_3","text":"《尚書大傳》曰：北方者，物之伏方也，何以謂之冬，冬，中也，物方藏於中也，故曰北方冬也。","sortOrder":165},
  {"id":"s_work_nvlt_3_166","chapterId":"ch_work_nvlt_3","text":"《尚書》曰：申命和叔，宅朔方，曰幽都，平在朔易，日短星昴，以正仲冬。","sortOrder":166},
  {"id":"s_work_nvlt_3_167","chapterId":"ch_work_nvlt_3","text":"《周書·時訓》曰：小寒之日，雁北乡。又五日，鵲始巢。又五日，雉始雊，雁不北乡，民不懷生，鵲不始巢，國不安寧，雉不始雊，國乃大水，大寒之日，雞始乳。又五日，鷙鳥厲疾。又五日，水泽腹堅，雞不乳，淫女亂男，鷙鳥不厲，國不除兵，水泽不腹堅，言乃不從。","sortOrder":167},
  {"id":"s_work_nvlt_3_168","chapterId":"ch_work_nvlt_3","text":"《逸禮》曰：冬則衣黑衣，佩玄玉，乘玄辂，駕鐵驪，載玄旂，以迎冬於北郊，其祭先豕，居明堂後廟，啟北戶。","sortOrder":168},
  {"id":"s_work_nvlt_3_169","chapterId":"ch_work_nvlt_3","text":"《毛詩》曰：冬日烈烈，飄風發發。","sortOrder":169},
  {"id":"s_work_nvlt_3_170","chapterId":"ch_work_nvlt_3","text":"《易緯通卦验》曰：冬至之日，見雲送迎，從下乡來，歲美，民人和，不疾疫，無雲送迎，德薄，歲惡，故其雲赤者旱，黑者水，白者為兵，黃者有土功，諸從日氣送迎，此其傚也。","sortOrder":170},
  {"id":"s_work_nvlt_3_171","chapterId":"ch_work_nvlt_3","text":"又曰：立冬不周風至，水始冰，荠麥生，燕雀入水為蛤。","sortOrder":171},
  {"id":"s_work_nvlt_3_172","chapterId":"ch_work_nvlt_3","text":"太公《金匮》曰：夏桀之時，以十月發民，凿山穿陵，通於河，民諫曰：孟冬凿山穿陵，是泄天氣，發地之藏，天子失道，後必有败，桀殺之，期年，岑山崩為大泽，湯率諸侯伐之。","sortOrder":172},
  {"id":"s_work_nvlt_3_173","chapterId":"ch_work_nvlt_3","text":"《京房占》曰：春冬乾王，不周風用事，人君當興邊兵，治城郭，行刑，斷獄訟，繕宮殿。","sortOrder":173},
  {"id":"s_work_nvlt_3_174","chapterId":"ch_work_nvlt_3","text":"《漢書》曰：冬，民既入，婦人同巷相從夜績，一月得四十五日，必相從者，所以省費燎火，同巧拙而合習俗也。","sortOrder":174},
  {"id":"s_work_nvlt_3_175","chapterId":"ch_work_nvlt_3","text":"《魏略》曰：董遇好學，人從學者，遇不肯教，雲，當先讀書百遍，而義自見，從學者雲，苦渴無日，遇曰：當以三餘，冬者歲之餘，雨者晴之餘，夜者日之餘。","sortOrder":175},
  {"id":"s_work_nvlt_3_176","chapterId":"ch_work_nvlt_3","text":"《五經通義》曰：冬至陽氣萌，陰陽交精，始成萬物，氣微在下，不可動泄。","sortOrder":176},
  {"id":"s_work_nvlt_3_177","chapterId":"ch_work_nvlt_3","text":"桓谭《新論》曰：太原郡民，以隆冬不火食五日，雖有病缓急，猶不敢犯，為介之推故也。","sortOrder":177},
  {"id":"s_work_nvlt_3_178","chapterId":"ch_work_nvlt_3","text":"《續漢禮儀志》曰：立冬之日，夜漏未盡五刻，京都百官，皆衣皂，迎氣黑郊。","sortOrder":178},
  {"id":"s_work_nvlt_3_179","chapterId":"ch_work_nvlt_3","text":"【詩】晉張華冬初歲小會詩曰：日月不留，四氣回周，節慶代序，萬國同休，庶尹群後，奉寿升朝，我有嘉禮，式宴百寮。","sortOrder":179},
  {"id":"s_work_nvlt_3_180","chapterId":"ch_work_nvlt_3","text":"又雜詩曰：晷度隨天運，四時互相承，東壁正昏中，涸陰寒節升，繁霜隆當夕，悲風中夜興，朱火青無光，蘭膏坐未凝，重衾無暖氣，挟纊如懷冰。","sortOrder":180},
  {"id":"s_work_nvlt_3_181","chapterId":"ch_work_nvlt_3","text":"晉陳新涂妻李氏冬至詩曰：靈象尋數回，四氣平運散，陰律鼓微陽，大明啟修旦，感與時來興，心隨逝化叹，式宴集中堂，賓客盈朝馆。","sortOrder":181},
  {"id":"s_work_nvlt_3_182","chapterId":"ch_work_nvlt_3","text":"晉曹毗詠冬詩曰：綿邈冬夕永，凛厲寒氣升，離葉向晨落，長風振條興，夜靜輕乡起，天清月暉澄，寒水盈渠結，素霜竟朓凝，今載忽已暮，來紀奄复仍。","sortOrder":182},
  {"id":"s_work_nvlt_3_183","chapterId":"ch_work_nvlt_3","text":"宋謝靈運歲暮詩曰：殷忧不能寐，苦此夜難穨，明月照積雪，朔風劲且哀，運往無淹物，逝年覺易催。","sortOrder":183},
  {"id":"s_work_nvlt_3_184","chapterId":"ch_work_nvlt_3","text":"又彭城宮中直感歲暮詩曰：草草眷徂物，契契矜歲蝉，楚艳起行戚，吳趨絕歸懽，修帶缓舊裳，素鬢改朱顏，晚暮非獨已，鳴鶗歇春蘭。","sortOrder":184},
  {"id":"s_work_nvlt_3_185","chapterId":"ch_work_nvlt_3","text":"宋鮑照冬至詩曰：景移風度改，日至晷回換，眇眇負霜鶴，皎皎帶雲雁，長河結皪玕，層水如玉岸。","sortOrder":185},
  {"id":"s_work_nvlt_3_186","chapterId":"ch_work_nvlt_3","text":"又冬日詩曰：嚴風亂山起，白日欲還次，重霧蔽窮天，夕陰晦寒地，瀚海有歸潮，衰容不還稚，令君且安歌，無念老將至。","sortOrder":186},
  {"id":"s_work_nvlt_3_187","chapterId":"ch_work_nvlt_3","text":"謝靈運［冯校本作謝惠連。］詠冬詩曰：七宿乘運曜，三星與時滅，履霜冰弥堅，積寒風愈切，繁雲起重陰，回飆流輕雪，園林粲斐皓，庭除秀皎絜，墀琐有凝汗，達衢無通轍。","sortOrder":187},
  {"id":"s_work_nvlt_3_188","chapterId":"ch_work_nvlt_3","text":"梁簡文帝大同十年十月戊寅詩曰：喧尘是時息，靜坐對重峦，冬深柳條落，雪後桂枝殘，星明霧色盡，天白雁行单，雲飛乍想閣，冰結遠疑紈，晚橘隱重屏，枯藤帶回竿，荻陰連水氣，山峰染月寒。","sortOrder":188},
  {"id":"s_work_nvlt_3_189","chapterId":"ch_work_nvlt_3","text":"又玄圃寒夕詩曰：洞門扉未掩，金壶漏已催，曛煙生涧曲，暗色起林隈，雪花無有蒂，冰鏡不安台，階楊始倒插，浦桂半新栽，陳根委落蕙，細蕊發香梅，雁去衔芦上，猿戲繞枝來。","sortOrder":189},
  {"id":"s_work_nvlt_3_190","chapterId":"ch_work_nvlt_3","text":"又大同十一月庚戌詩曰：茲園植藝積，山穀久紆威，直興轉多緒，真事亦因依，是節嚴冬暮，寒雲掩落暉，遠聞風瑟瑟，亂视雪霏霏，浪起川難渡，林深人至稀，山禽背迳走，野鳥歷塘飛。","sortOrder":190},
  {"id":"s_work_nvlt_3_191","chapterId":"ch_work_nvlt_3","text":"梁庾肩吾歲盡詩曰：歲序已雲殫，春心不自安，聊开柏葉酒，试奠五辛盤，金薄圖神燕，朱泥印鬼丸，梅花應可折，倩為雪中看。","sortOrder":191},
  {"id":"s_work_nvlt_3_192","chapterId":"ch_work_nvlt_3","text":"北齊邢子才冬日傷志詩曰：昔時墮遊士，任性少矜裁，朝馳馬腦勒，夕衔熊耳杯，折花赠淇水，撫瑟望丛台，繁華夙昔改，衰病一時來，重以三冬月，愁雲聚复开，天高日色淺，林劲鳥鳴哀，終風激簷宇，餘雪滿條枚，遨遊昔宛洛，踟蹰今草萊，時事方去矣，撫己獨懷哉。","sortOrder":192},
  {"id":"s_work_nvlt_3_193","chapterId":"ch_work_nvlt_3","text":"周王襃和殷廷尉歲暮詩曰：歲晚悲窮律，他乡念索居，寂寞灰心盡，摧殘生意餘，產空交道絕，财殫密親疏，空悲趙壹賦，還著虞卿書。","sortOrder":193},
  {"id":"s_work_nvlt_3_194","chapterId":"ch_work_nvlt_3","text":"【賦】晉陆機感時賦曰：悲夫，冬之為氣，亦何憯懍以萧索，天悠悠其弥高，霧鬱鬱而四幕，夜綿邈其難終，日晼晚而易落，伊夫時之方惨，曷萬物之能歡，猿長嘯於林杪，鳥高鳴於雲端，矧餘情之含瘁，恒睹物而增酸，歷四時以迭感，悲此歲之已寒，撫傷懷以呜咽，望永路而汍澜。","sortOrder":194},
  {"id":"s_work_nvlt_3_195","chapterId":"ch_work_nvlt_3","text":"梁江淹四時賦曰：至於冬陰北邊，永夜不晓，平芜际海，千里飛鳥，何嘗不夢帝城之阡陌，故乡之台沼。","sortOrder":195},
  {"id":"s_work_nvlt_3_196","chapterId":"ch_work_nvlt_3","text":"晉陆雲歲暮賦曰：颛頊御時，玄冥統官，淪重陽於潛戶兮，嚴積陰於司寒，堅冰涸於川底兮，白雪陨於雲端，時凛戾其可悲兮，氣萧索以傷心，凄風怆其鳴條，落葉翻而洒林，獸藏丘而絕跡兮，鳥攀木而栖音，山振枯於層嶺兮，人懷惨於重襟。","sortOrder":196},
  {"id":"s_work_nvlt_3_197","chapterId":"ch_work_nvlt_3","text":"梁萧子雲歲暮直庐賦曰：日躔女度，歲華雲暮，衡輕炭燥，權重泉涸，藏玄武於大陰，蟄螣蛇於高霧，日臨圭而易落，晷中杙而南傃，凝寒氣於廣庭，洞層陰於端库，風餮切而晚作，雲沧浪而晦景，霰的皪於彤庭，霙葳蕤於丹屏，韜罘罳之飛棟，没屠蘇之高影，始飄舞於圓池，終停華於方井。","sortOrder":197},
  {"id":"s_work_nvlt_3_198","chapterId":"ch_work_nvlt_3","text":"晉傅玄大寒賦曰：五行倏而竟骛兮，四節紛而電逝，谅暑往寒來，十二月而成歲，日月會於析木兮，重陰凄而增肅，彩虹藏於虛廓兮，鱗介潛而長伏，若乃天地凛冽，庶極氣否，嚴霜夜結，悲風晝起，飛雪山積，萧條萬里，百川明而不流兮，冰冻合於四海，扶木憔悴於湯穀，若華零落於濛汜。","sortOrder":198},
  {"id":"s_work_nvlt_3_199","chapterId":"ch_work_nvlt_3","text":"《藝文類聚》　唐·欧陽詢","sortOrder":199},
  {"id":"s_work_nvlt_4_1","chapterId":"ch_work_nvlt_4","text":"卷四歲時中據明本補","sortOrder":1},
  {"id":"s_work_nvlt_4_2","chapterId":"ch_work_nvlt_4","text":"○元正人日正月十五日月晦寒食三月三五月五七月七七月十五九月九","sortOrder":2},
  {"id":"s_work_nvlt_4_3","chapterId":"ch_work_nvlt_4","text":"◇元正","sortOrder":3},
  {"id":"s_work_nvlt_4_4","chapterId":"ch_work_nvlt_4","text":"《尚書》曰：月正元日，舜格於文祖。","sortOrder":4},
  {"id":"s_work_nvlt_4_5","chapterId":"ch_work_nvlt_4","text":"《列子》曰：邯鄲之民，以正月之旦，獻鳩於簡子，簡子大悅，厚賞之，客問其故，簡子曰：正旦放生，示有恩也。","sortOrder":5},
  {"id":"s_work_nvlt_4_6","chapterId":"ch_work_nvlt_4","text":"《孔丛子》曰：邯鄲民以正月旦獻爵於趙王，而缀以五采，王大悅，東觀漢記曰：戴凭為侍中，正旦朝贺，帝令群臣說經義，不通者奪其席，凭遂重五十餘席，［事具講論篇。］《漢書》曰：鮑宣字子都，哀帝時，正旦日蚀，宣上書諫曰：陛下父事天，母事地，子養黎民，父虧明，母震動，子訛言，今日蚀三陽始，小民正月朔旦，尚惡败器物，况日虧缺乎。","sortOrder":6},
  {"id":"s_work_nvlt_4_7","chapterId":"ch_work_nvlt_4","text":"漢雜事曰：正月朝贺，三公奉璧上殿，乡御坐北面，太常使贊曰：皇帝為君興，三公伏，皇帝坐，乃前進璧。","sortOrder":7},
  {"id":"s_work_nvlt_4_8","chapterId":"ch_work_nvlt_4","text":"《典略》曰：明帝使博士馬均，作司南車，水轉百戲，正月朝，造巨獸魚龍蔓延，弄馬倒騎，備如漢西京故事。","sortOrder":8},
  {"id":"s_work_nvlt_4_9","chapterId":"ch_work_nvlt_4","text":"《魏略》曰：正始元年，商風大起數十日，發屋折树，動太極殿東閣，正旦大會。又甚，傾床案，曹休將誅之徵也。","sortOrder":9},
  {"id":"s_work_nvlt_4_10","chapterId":"ch_work_nvlt_4","text":"王浑集曰：詔問明正旦會，四方計吏入見，臨朝當何所宜，浑奏，舊正會計吏軒下，中書令宣詔，問方土所宜，士人賢才，隱伏未達，風俗好尚，禮教之宜，勤農務本，以盡墾殖之利，刑獄清理，無枉濫之失，郡守長吏，勤心治政，為民興利除害，訓化之績，授以紙筆，意陳聞見，以明聖旨垂心四遠。","sortOrder":10},
  {"id":"s_work_nvlt_4_11","chapterId":"ch_work_nvlt_4","text":"晉鹹康起居註曰：十二月庚子，詔曰：正會日，百寮增祿，賜醽酒，人二升。","sortOrder":11},
  {"id":"s_work_nvlt_4_12","chapterId":"ch_work_nvlt_4","text":"《世說》曰：元帝正會，引丞相王导登御床，王公固辭，中宗引之弥苦，文獻曰：使太陽與萬物同暉，臣下何以仰瞻，帝乃止。","sortOrder":12},
  {"id":"s_work_nvlt_4_13","chapterId":"ch_work_nvlt_4","text":"邓德明《南康記》曰：昔有盧耽，仕州為治中，少學仙術，善解飛騰，每夕，辄凌虛歸家，晓則還州，嘗元會至晚，不及朝列，化為白鵠，至閣前，徊翔欲下，威儀以帚掷之，得一只履，耽驚還就列，內外左右，莫不駭異，時步骘為廣州刺史，意甚惡之，便以状列聞，遂至誅滅。","sortOrder":13},
  {"id":"s_work_nvlt_4_14","chapterId":"ch_work_nvlt_4","text":"裴玄《新語》曰：正朝，縣官殺羊，懸其頭於門。又磔雞以副之，俗說以厭癘氣。玄以問河南伏君，伏君曰：是土氣上升，草木萌動，羊齧百草，雞啄五穀，故殺之以助生氣。","sortOrder":14},
  {"id":"s_work_nvlt_4_15","chapterId":"ch_work_nvlt_4","text":"【詩】魏陳思王曹植元會詩曰：初歲元祚，吉日惟良，乃為嘉會，宴此高堂。衣裳鮮絜，黼黻玄黃，珍膳雜遝，充溢圓方，俯视文軒，仰瞻華梁，原保茲善。千載為常，歡笑盡娱，樂哉未央，皇室榮貴，寿考無疆。","sortOrder":15},
  {"id":"s_work_nvlt_4_16","chapterId":"ch_work_nvlt_4","text":"晉荀勖正大會行禮歌詩曰：於皇元首，群生資始，履端大享，敬御福祉，肆觐群後，爰及卿士，钦順時财，允也天子。","sortOrder":16},
  {"id":"s_work_nvlt_4_17","chapterId":"ch_work_nvlt_4","text":"又曰：明明天子，臨下有赫，四表宅心，惠浃荒貊，柔遠能邇，孔淑不逆。來格祁祁，邦家是若。","sortOrder":17},
  {"id":"s_work_nvlt_4_18","chapterId":"ch_work_nvlt_4","text":"又曰：光光邦家，天篤其祜，丕顯喆命，顧予三祖，世德作求，奄有九土，思我皇度，彝倫攸序。","sortOrder":18},
  {"id":"s_work_nvlt_4_19","chapterId":"ch_work_nvlt_4","text":"晉曹毗正朝詩曰：靈春散初泽，棼煴青陽舒，佳袍忽已故，今載奄复初，软節畅宇宙，和風被八區。","sortOrder":19},
  {"id":"s_work_nvlt_4_20","chapterId":"ch_work_nvlt_4","text":"晉劉和妻王氏正朝詩曰：稔冉冥機運，迅矣四節經，太簇應玄律，青陽兆初正。","sortOrder":20},
  {"id":"s_work_nvlt_4_21","chapterId":"ch_work_nvlt_4","text":"晉傅克妻辛氏元正詩曰：元正啟令節，嘉慶肇自茲，鹹奏萬年觴，小大同悅熙。","sortOrder":21},
  {"id":"s_work_nvlt_4_22","chapterId":"ch_work_nvlt_4","text":"晉荀勖正會公王上寿酒歌曰：踐元辰，延顯融，獻羽觴，祈令終，我皇寿而隆，我皇茂而嵩，本枝奋百世，休祚鍾聖躬。","sortOrder":22},
  {"id":"s_work_nvlt_4_23","chapterId":"ch_work_nvlt_4","text":"【賦】晉傅玄朝會賦曰：考夏後之遺訓，綜殷周之典製，采秦漢之舊儀，肇元正之嘉會，於是先期戒事，眾發允敕，萬國鹹享，各以其職，翼翼京邑，巍巍紫極，前三朝之夜中，庭燎晃以舒光，華燈若乎火树，炽百枝之煌煌，俯而察之，如亢燭龍而炤玄方，仰而觀焉，若披丹霞而鑒九陽。","sortOrder":23},
  {"id":"s_work_nvlt_4_24","chapterId":"ch_work_nvlt_4","text":"【頌】晉劉臻妻正旦獻椒花頌曰：遊穹周回，三朝肇建，青陽散暉，澄景載煥，美哉靈葩，爰采爰獻，聖容映之，永寿於萬。","sortOrder":24},
  {"id":"s_work_nvlt_4_25","chapterId":"ch_work_nvlt_4","text":"◇人日","sortOrder":25},
  {"id":"s_work_nvlt_4_26","chapterId":"ch_work_nvlt_4","text":"《荆楚歲時記》曰：正月七日為人日，以七种菜為羹，翦采為人，或鏤金薄帖屏風上，忽［《太平御覽》三十作亦。］戴之，像人入新年，形容改新。","sortOrder":26},
  {"id":"s_work_nvlt_4_27","chapterId":"ch_work_nvlt_4","text":"董勋《問禮俗》曰：一日為雞，二日為狗，三日為猪，四日為羊，五日為牛，六日為馬，七日為人。","sortOrder":27},
  {"id":"s_work_nvlt_4_28","chapterId":"ch_work_nvlt_4","text":"贾充《典戒》曰：人日造華勝相遺，像瑞圖金勝之形，又像西王母戴勝也。","sortOrder":28},
  {"id":"s_work_nvlt_4_29","chapterId":"ch_work_nvlt_4","text":"劉臻妻陳氏進見儀曰：正月七日，上人勝於人。","sortOrder":29},
  {"id":"s_work_nvlt_4_30","chapterId":"ch_work_nvlt_4","text":"【詩】隋陽休之人日登高侍宴詩曰：廣殿麗年辉，上林起春色，風生拂雕輦，雲回浮綺翼。","sortOrder":30},
  {"id":"s_work_nvlt_4_31","chapterId":"ch_work_nvlt_4","text":"薛道衡人日思歸詩曰：入春才七日，離家已二年，人歸落雁後，思發在花前。","sortOrder":31},
  {"id":"s_work_nvlt_4_32","chapterId":"ch_work_nvlt_4","text":"【銘】李充登安仁峰銘曰：正月七日，厥日惟人，策我良驷，陟彼安仁。","sortOrder":32},
  {"id":"s_work_nvlt_4_33","chapterId":"ch_work_nvlt_4","text":"◇正月十五日","sortOrder":33},
  {"id":"s_work_nvlt_4_34","chapterId":"ch_work_nvlt_4","text":"玉燭寶典曰：正月十五日，作膏，［《太平御覽》三十膏下有粥字。］以祠門戶。","sortOrder":34},
  {"id":"s_work_nvlt_4_35","chapterId":"ch_work_nvlt_4","text":"《荆楚歲時記》曰：風俗望日，以楊枝插門，隨楊枝所指而祭，其夕。］迎紫姑神以卜。","sortOrder":35},
  {"id":"s_work_nvlt_4_36","chapterId":"ch_work_nvlt_4","text":"《史記》曰：漢家以望日祀太一，從昏時到明，今夜遊觀燈是其遺跡，［今夜遊以下九字，《初學記》四，《太平御覽》三十作註文。］","sortOrder":36},
  {"id":"s_work_nvlt_4_37","chapterId":"ch_work_nvlt_4","text":"《西域記》曰：摩竭紘國，正月十五日，僧俗雲集，觀佛舍利，放光雨花。","sortOrder":37},
  {"id":"s_work_nvlt_4_38","chapterId":"ch_work_nvlt_4","text":"《涅槃經》曰：如來阇維訖，收舍利罌，置金床上，天人散花奏樂，繞城步步燃燈十二里。","sortOrder":38},
  {"id":"s_work_nvlt_4_39","chapterId":"ch_work_nvlt_4","text":"【詩】蘇味道望日夜遊詩曰：火树銀花合，星桥鐵鎖开，暗尘隨馬去，明月逐人來，遊騎皆秾李，行歌盡落梅，金吾不惜夜，玉漏莫相催。","sortOrder":39},
  {"id":"s_work_nvlt_4_40","chapterId":"ch_work_nvlt_4","text":"崔液夜遊詩曰：玉漏銅壶且莫催，鐵關金鎖彻明开，誰家見月能間坐，何處聞燈不看來。","sortOrder":40},
  {"id":"s_work_nvlt_4_41","chapterId":"ch_work_nvlt_4","text":"又曰：神燈佛火百輪張，刻像圖形七寶裝，影里如聞金口說，空中似散玉毫光。","sortOrder":41},
  {"id":"s_work_nvlt_4_42","chapterId":"ch_work_nvlt_4","text":"又曰：金勒銀鞍控紫骝，玉輪朱幰駕青牛，驂驔始散東城曲，倏忽還逢南陌頭。","sortOrder":42},
  {"id":"s_work_nvlt_4_43","chapterId":"ch_work_nvlt_4","text":"◇月晦","sortOrder":43},
  {"id":"s_work_nvlt_4_44","chapterId":"ch_work_nvlt_4","text":"《荆楚歲時記》曰：元日至月晦，併為酺聚飲食，每月皆有晦朔，正月初年，時俗重以為節。","sortOrder":44},
  {"id":"s_work_nvlt_4_45","chapterId":"ch_work_nvlt_4","text":"玉燭寶典曰：元日至月晦，人併為酺食，士女悉湔裳斟酒於水湄，以為度厄。","sortOrder":45},
  {"id":"s_work_nvlt_4_46","chapterId":"ch_work_nvlt_4","text":"《帝王世紀》曰：尧有草夹階而生，每月朔生一荚，月半則生十五荚，自十六日一荚落，至月晦而盡，月小則餘一荚，厭而不落，以為瑞草，名為蓂荚，一名歷荚。","sortOrder":46},
  {"id":"s_work_nvlt_4_47","chapterId":"ch_work_nvlt_4","text":"【詩】太宗皇帝月晦詩曰：晦魄移中律，凝暄起麗城，罩雲朝蓋上，穿露晓珠呈，笑树花分色，啼枝鳥合聲，披襟歡眺望，極目畅春晴。","sortOrder":47},
  {"id":"s_work_nvlt_4_48","chapterId":"ch_work_nvlt_4","text":"北齊魏收晦日汎舟應詔詩曰：裊裊春枝弱，關關新鳥呼，棹唱忽逶迤，菱歌時顧慕，睿賞芳日色，宴言忘日暮，遊豫慰人心，照臨康國步。","sortOrder":48},
  {"id":"s_work_nvlt_4_49","chapterId":"ch_work_nvlt_4","text":"後魏盧元明晦日汎舟應詔詩曰：輕灰吹上管，落蓂飄下蒂，遲遲春色華，晼晼年光麗。","sortOrder":49},
  {"id":"s_work_nvlt_4_50","chapterId":"ch_work_nvlt_4","text":"◇寒食","sortOrder":50},
  {"id":"s_work_nvlt_4_51","chapterId":"ch_work_nvlt_4","text":"《周禮》曰：司烜氏，仲春以木铎脩火禁於國中，為季春將出火也。","sortOrder":51},
  {"id":"s_work_nvlt_4_52","chapterId":"ch_work_nvlt_4","text":"《荆楚歲時記》曰：去冬至一百五日，即有疾風甚雨，謂之寒食。","sortOrder":52},
  {"id":"s_work_nvlt_4_53","chapterId":"ch_work_nvlt_4","text":"周斐先賢傳曰：太原舊俗，雲介子推焚骸，一月寒食，莫敢煙爨。","sortOrder":53},
  {"id":"s_work_nvlt_4_54","chapterId":"ch_work_nvlt_4","text":"陆翙《鄴中記》曰：併州俗，冬至後百五日，為介子推斷火，冷食三日，作乾粥，今之糗是也。","sortOrder":54},
  {"id":"s_work_nvlt_4_55","chapterId":"ch_work_nvlt_4","text":"又曰：寒食三日，作醴酪，煮粳米及麥為酪，捣杏仁，煮作粥。","sortOrder":55},
  {"id":"s_work_nvlt_4_56","chapterId":"ch_work_nvlt_4","text":"范晔《後漢書》曰：周舉遷併州刺史，太原一郡，舊俗以介子推焚骸，有龍忌之禁，至其月，鹹言神靈不樂舉火，舉移書於子推廟雲，春中寒食一月，老小不堪，今則三日而已。","sortOrder":56},
  {"id":"s_work_nvlt_4_57","chapterId":"ch_work_nvlt_4","text":"古今藝術圖曰：北方山戎，寒食日用鞦韆為戲，以習輕趫者。","sortOrder":57},
  {"id":"s_work_nvlt_4_58","chapterId":"ch_work_nvlt_4","text":"【詩】李崇嗣寒食詩曰：普天皆滅焰，匝地盡藏煙，不知何處火，來就客心燃。","sortOrder":58},
  {"id":"s_work_nvlt_4_59","chapterId":"ch_work_nvlt_4","text":"宋之問途中寒食詩曰：馬上逢寒食，途中屬暮春，可怜江浦望，不見洛桥人。","sortOrder":59},
  {"id":"s_work_nvlt_4_60","chapterId":"ch_work_nvlt_4","text":"沈佺期嶺表寒食詩曰：嶺外逢寒食，春來不見餳，洛中新甲子，明日是清明。","sortOrder":60},
  {"id":"s_work_nvlt_4_61","chapterId":"ch_work_nvlt_4","text":"【令】魏武帝明罰令曰：聞太原上党西河雁門，冬至後百五日，皆絕火寒食，雲為介子推，且北方沍寒之地，老少羸弱，將有不堪之患，令到，人不得寒食，若犯者，家長半歲刑，主吏百日刑，令長奪一月俸。","sortOrder":61},
  {"id":"s_work_nvlt_4_62","chapterId":"ch_work_nvlt_4","text":"◇三月三日","sortOrder":62},
  {"id":"s_work_nvlt_4_63","chapterId":"ch_work_nvlt_4","text":"應劭《風俗通》曰：按周禮，女巫掌歲時以祓除疾病，禊者絜也，故於水上盥絜之也，巳者祉也，邪疾已去，祈介祉也。","sortOrder":63},
  {"id":"s_work_nvlt_4_64","chapterId":"ch_work_nvlt_4","text":"韓詩曰：三月桃花水之時，鄭國之俗，三月上巳，於溱洧兩水之上，執蘭招魂續魄，拂除不祥。","sortOrder":64},
  {"id":"s_work_nvlt_4_65","chapterId":"ch_work_nvlt_4","text":"《漢書》曰：太後春幸蠶馆，率皇後列侯夫人桑，遵灞水而祓除。","sortOrder":65},
  {"id":"s_work_nvlt_4_66","chapterId":"ch_work_nvlt_4","text":"續漢書禮儀志曰：三月上巳，官民皆絜於東流水上，自洗濯，祓除宿垢，為太絜。","sortOrder":66},
  {"id":"s_work_nvlt_4_67","chapterId":"ch_work_nvlt_4","text":"《魏志》曰：袁紹三月上巳，大會賓徒於薄落津，聞魏郡兵及黑山賊於毒等數萬人，共覆鄴城，殺守，坐中客家在鄴者，皆忧怖失色，或起而立，紹容貌自若，不改常度。","sortOrder":67},
  {"id":"s_work_nvlt_4_68","chapterId":"ch_work_nvlt_4","text":"《竹林七賢論》曰：王濟嘗解禊洛水，明日，或問王曰：昨遊有何語議，濟曰：張華善說史漢，裴逸民叙前言往行，袞袞可聽，［事具談論部。］","sortOrder":68},
  {"id":"s_work_nvlt_4_69","chapterId":"ch_work_nvlt_4","text":"夏仲御別傳曰：仲御詣洛，到三月三日，洛中公王以下，莫不方軌連軫，併至南浮桥邊禊，男則朱服耀路，女則錦綺粲烂，仲御時在船中，曝所市藥，雖見此辈，穩坐不搖，贾公望見之，深奇其節，原相與語，此人有心胆，有似冀缺，走問船中安坐者為誰，仲御不應，重問，徐乃答曰：會稽北海間民夏仲御。","sortOrder":69},
  {"id":"s_work_nvlt_4_70","chapterId":"ch_work_nvlt_4","text":"《晉中興書》曰：玉导謂從兄敦曰：王仁德未著，而名位猶輕，兄威名日已振，宜有以共相匡舉，會三月三日，中宗出禊，乘肩輦，敦导併騎從，紀瞻使人觇之，既聞敦导騎從，乃大驚，自出拜於道左，中宗從容謂导曰：卿吾之萧何也。","sortOrder":70},
  {"id":"s_work_nvlt_4_71","chapterId":"ch_work_nvlt_4","text":"《續搜神記》曰：盧充獵，見獐，便射中之，隨逐不覺遠，忽見一里門，如府舍，問鈴下，鈴下對曰：崔少府也，進見少府，少府語充曰：尊府君為索小女婚，故相迎耳，三日畢，車送充至家，母問，具状以對，與崔別後四年，充三月三日臨水戲，遙見水傍有犢車，充往开車戶，見崔女與三歲男共載，情意如初，抱男兒還充。又與金鋺別。","sortOrder":71},
  {"id":"s_work_nvlt_4_72","chapterId":"ch_work_nvlt_4","text":"《雜五行書》曰：欲知蠶善惡，常以三月三日，天陰而無日，不見雨，蠶大善。","sortOrder":72},
  {"id":"s_work_nvlt_4_73","chapterId":"ch_work_nvlt_4","text":"續齊諧記曰：晉武帝問尚書郎挚虞曰：三日曲水，其義何指，答曰：漢章帝時，平原徐肇，以三月初生三女，至三日俱亡，一村以為怪，乃相携之水濱盥洗，遂因水以汎觴，曲水之義起於此，帝曰：若如所談，便非好事，尚書郎束晳曰：仲治小生，不足以知此，臣請說其始，昔周公城洛邑，因流水以汎酒，故逸詩雲，羽觴隨波。又秦昭王三日置酒河曲，見有金人出，奉水心劍曰：令君製有西夏，及秦霸諸侯，乃因此處立為曲水祠，二漢相緣，皆為盛集，帝曰：善，賜金五十斤，左遷仲治為陽城令。","sortOrder":73},
  {"id":"s_work_nvlt_4_74","chapterId":"ch_work_nvlt_4","text":"【詩】晉張華三月三日後園會詩曰：暮春元日，陽氣清明，祁祁甘雨，膏泽流盈，習習祥風，啟滯导生，禽鳥逸豫，桑麻滋榮，纖條被绿，翠華含英，於皇我後，钦若昊乾，順時省物，言觀中園，宴及群辟，乃命乃延，合樂華池，祓濯清川，汎彼龍舟，溯遊渚源。","sortOrder":74},
  {"id":"s_work_nvlt_4_75","chapterId":"ch_work_nvlt_4","text":"又上巳篇曰：仁風导和氣，勾芒御昊春，姑洗應時月，元巳啟良辰，密雲荫朝日，零雨洒微尘，飛軒遊九野，置酒會眾賓。","sortOrder":75},
  {"id":"s_work_nvlt_4_76","chapterId":"ch_work_nvlt_4","text":"晉潘尼三日洛水作詩曰：晷運無窮已，時逝焉可追，斗酒足為歡，臨川胡獨悲，暮春春服成，百草敷英蕤，聊為三日遊，方駕結龍旂，廊廟多豪俊，都邑有艳姿，朱軒荫蘭皋，翠幕映洛湄，臨岸濯素手，涉水搴輕衣，沉鉤出比目，舉弋落双飛，羽觴乘波進，素卯隨流歸。","sortOrder":76},
  {"id":"s_work_nvlt_4_77","chapterId":"ch_work_nvlt_4","text":"晉王濟平吳後三月三日華林園詩曰：蠢爾長蛇，荐食江汜，我皇神武，汎舟萬里，迅雷電邁，弗及掩耳，思樂華林，薄采其蘭，皇居伟則，芳園巨觀，仁以山悅，水為智歡，清池流爵，秘樂通玄，物以時序，情以化宣。","sortOrder":77},
  {"id":"s_work_nvlt_4_78","chapterId":"ch_work_nvlt_4","text":"晉闾丘冲三月三日應詔詩曰：暮春之月，春服既成，升陽土润，冰涣川盈，餘萌達壤，嘉木敷榮，後皇宣遊，既宴且寧，光光華輦，诜诜從臣，微風扇秽，朝露翳尘，上荫丹幄，下藉文茵，臨川浥盥，濯故絜新，俯鏡清流，仰睇天津，藹藹華林，嚴嚴景陽，業業峻宇，奕奕飛梁，垂荫倒景，若沉若翔，浩浩白水，汎汎龍舟，皇在靈沼，百辟同遊，击棹清歌，鼓枻行酬，聞樂鹹和，具醉斯柔，在昔帝虞，德被遐荒，幹戚在庭，苗民來王，今我哲後，古聖齊芳，惠此中國，以綏四方，元首既明，股肱惟良，樂酒今日，君子惟康。","sortOrder":78},
  {"id":"s_work_nvlt_4_79","chapterId":"ch_work_nvlt_4","text":"晉王贊三月三日詩曰：招搖啟運，寒暑代新，亹亹不舍，如彼行雲，猗猗季月，穆穆和春，皇储降止，宴及嘉賓，嘉賓伊何，具惟姻族，如彼葛藟，衍於樛木，鬱鬱近侍，巖巖台嶽，庶寮鱗次，以崇天祿，如彼崑山，列此琚玉，巍巍天階，亦降列宿，右載元首，左光储副，大祚無窮，天地為寿，晉陆機詩曰：遲遲暮春日，天氣柔且嘉，元吉隆初巳，濯秽遊黃河。","sortOrder":79},
  {"id":"s_work_nvlt_4_80","chapterId":"ch_work_nvlt_4","text":"晉阮脩上巳會詩曰：三春之季，歲惟嘉時，靈雨既零，風以散之，英華扇耀，翔鳥群嬉，澄澄绿水，澹澹其波，脩岸逶迤，長川相過，聊且逍遙，其樂如何，坐此脩筵，臨彼素流，嘉肴既設，舉爵獻酬，彈筝弄琴，新聲上浮，水有七德。智者所娱，清瀨瀺灂，菱葭芬敷，沉此芳鉤，引彼潛魚，委〈饣甘〉芳美，君子戒諸。","sortOrder":80},
  {"id":"s_work_nvlt_4_81","chapterId":"ch_work_nvlt_4","text":"晉孫綽三月三日詩曰：姑洗斡運，首陽穆闡，嘉卉萋萋，溫風暖暖，言涤長瀨，聊以遊眼，縹{艹沂}渶流，绿柳荫坂，羽從風飄，鱗隨浪轉。","sortOrder":81},
  {"id":"s_work_nvlt_4_82","chapterId":"ch_work_nvlt_4","text":"晉庾闡三月三日詩曰：心結湘川渚，目散冲霄外，清泉吐翠流，绿醽漂素瀨。悠想眄長川，輕澜眇如帶。","sortOrder":82},
  {"id":"s_work_nvlt_4_83","chapterId":"ch_work_nvlt_4","text":"又三月三日臨曲水詩曰：暮春濯清巳，遊鱗泳一壑，高泉吐東岑，洄澜自净泶，臨川叠曲流，丰林映绿薄，輕舟沉飛觴，鼓枻觀魚躍。","sortOrder":83},
  {"id":"s_work_nvlt_4_84","chapterId":"ch_work_nvlt_4","text":"宋顏延之三日侍遊曲阿後湖詩曰：虞風載帝狩，夏諺頌王遊，春方動宸駕，望幸傾五州，山祗跸峤路，水若驚沧流，神御出瑤軫，天儀降藻舟，萬軸胤行衛，千翼泛飛浮，雕雲麗璇蓋，祥飆被采斿，江南進荆艳，河徼獻趙謳。","sortOrder":84},
  {"id":"s_work_nvlt_4_85","chapterId":"ch_work_nvlt_4","text":"又詔宴曲水詩曰：道隱未形，治彰既亂，帝跡懸衡，皇流共貫，惟王創物，永錫洪筭，仁固开周，義高登漢，祚融世哲，葉光列聖，太上正位，天臨海鏡，帝體麗明，儀辰作貳，居彼東朝，金昭玉粹，德有润身，體不愆器，开榮洒泽，舒虹烁電，伊思鎬飲，每懷洛宴，郊餞有疆，君舉有禮，幕帳蘭甸畫流高陛，分庭荐樂，析波浮醴，豫同夏諺，事兼出濟。","sortOrder":85},
  {"id":"s_work_nvlt_4_86","chapterId":"ch_work_nvlt_4","text":"又三月三日詔宴西池詩曰：河嶽曜圖，聖時利見，於赫有皇，升中納禪，載貞其恒，載通其变，大哉人文，至矣天睠，昭哉储德，靈慶攸繁，明兩紫宸，景物乾元，帝宗菴藹，惟城惟蕃，袞衣善職，彤弓受言，飾馆春宮，稅鑣青辂，長筵逶迤，浮觴沿溯，宋謝靈運三月三日侍宴西池詩曰：詳觀記牒，鸿荒莫傳，降及雲鳥，曰聖則天，虞承唐命，周袭商艱，江之永矣，皇心惟眷，矧乃暮春，時物芳衍，濫觴逶迤，周流蘭殿，禮備朝容，樂阕夕宴。","sortOrder":86},
  {"id":"s_work_nvlt_4_87","chapterId":"ch_work_nvlt_4","text":"宋謝惠連三月三日曲水集詩曰：四時著平分，三春禀融烁，遲遲和景婉，夭夭園桃灼，携朋斯郊野，昧旦辭廛郭，斐雲興翠嶺，芳飆起華薄，解辔偃崇丘，藉草繞回壑，际渚羅時蔌，讬波汎輕爵。","sortOrder":87},
  {"id":"s_work_nvlt_4_88","chapterId":"ch_work_nvlt_4","text":"齊謝朓為皇太子侍華光殿曲水宴詩曰：傍求遂古，逖聽鸿名，大寶曰位，得一為貞，朱綈葉祉，绿字摛英，升配同貫，進讓殊聲，大橫將屬，會昌已命，國步中阻，震居膺慶，玺劍克傳，龟玉增映，玄塞北靡，丹徼南極，浮毳駕風，非泳非陟，西京藹藹，東都濟濟，秋祓濯流，春禊浮醴，初吉雲獻，上除方啟，昔駕陽穎，今歡雲陛，嘉樂舊矣，芳宴在斯，載留神矚，有睟天儀，龍精已映，威仰未移，葉依黃鳥，花落春池，高宴弘敞，禁林稠密，青隥崛起，丹樓間出，翠葆隨風，金戈動日，惆怅清管，徘徊輕佾，灞浐入筵，河淇流阼，媧［本集作海。］若來往，觴肴沿溯，歡飫有終，清光欲暮，輕轺回首，華組徐步。","sortOrder":88},
  {"id":"s_work_nvlt_4_89","chapterId":"ch_work_nvlt_4","text":"又為人作三日侍華光殿曲水宴詩曰：神理內寂，機象外融，遺情汾水，垂冕鸿宮，树以司牧，匪我求蒙，徒勤日用，誰器玄功，當寧日昃，求衣未明，抵璧焚翠，銷劍隳城，九畴式序，三辟載清，麗景則春，儀方在震，重聖積厚，金式琼润，祓秽河浦，張樂春畴，既停龍駕，亦汎凫舟，初湋命晓，朝華开夜，飾陛导源，回伊流灞，間馆巖敞，長廊水架，金觴搖荡，玉俎推移，筵浮水豹，席扰雲螭，歡茲廣宴，穆是天儀。","sortOrder":89},
  {"id":"s_work_nvlt_4_90","chapterId":"ch_work_nvlt_4","text":"梁簡文帝三日侍宴林光殿曲水詩曰：芳年留帝賞，應物動天襟，挟苑連金陣。分衢度羽林，帷宮對廣掖，層殿邇高岑，風旗爭曳影，亭皋共生陰，林花初墮蒂。池荷欲吐心。","sortOrder":90},
  {"id":"s_work_nvlt_4_91","chapterId":"ch_work_nvlt_4","text":"又三日率爾成詩曰：芳年多美色，麗景复妍遙，握蘭唯是旦，采艾亦今朝，回沙溜碧水，曲岫散桃夭，綺花非一种，風絲亂百條，雲起相思觀，日照飛虹桥，繁華炫姝色，燕趙艳妍妖，金鞍汗血馬，寶髻珊瑚翘，蘭聲起縠袖，莲錦束琼腰，相看隱绿榭，見人還自娇，玉桂鳴羅荐，渠碗泛回潮，洛濱非拾羽，滿握詎貽椒。","sortOrder":91},
  {"id":"s_work_nvlt_4_92","chapterId":"ch_work_nvlt_4","text":"又三日侍皇太子曲水宴詩曰：震德协靈，年芳節淑，濯伊臨灞，荡心愉目。驤騎晨野，摐金晓陆，蕙氣卷旌，神飆擎轂，曾岑偃蹇，耸觀岧峣，煙生翠幕，日照綺寮，銀華晨散，金芝暮搖，绿水動葉，丹距映條，顧惟菲薄，徒承恩裕，藝學未優，聲績不树，豈辨河書，寧摛淮賦，徒偶群龍，終慚併馭。","sortOrder":92},
  {"id":"s_work_nvlt_4_93","chapterId":"ch_work_nvlt_4","text":"又曲水聯句詩曰：春色明上巳，桃花落繞溝，波回卮不進，纶下鉤時留，［臣导。］絳水時回岸，花觴轉更周，陳肴渡玉俎，垂餌下銀鉤，王卿，回川入帳殿，列俎間芳洲，漢艾凌波出，江楓拂岸遊，［庾肩吾。］王生回水碓，蔡嫗荡輕舟，岸燭斜臨水，波光上映樓，［殿下。］","sortOrder":93},
  {"id":"s_work_nvlt_4_94","chapterId":"ch_work_nvlt_4","text":"梁沈約三日侍鳳光殿曲水宴詩曰：光遲蕙敏，氣婉椒台，皇心愛矣，帝曰遊哉，玉鸞徐骛，翠鳳輕回，別殿廣臨，離宮洞啟，川祗奉寿，河宗相禮，清洛漸筵，長伊流陛，洄荡嘉羞，搖漾芳醴，輕歌易繞，弱舞難持，素雲留管，玄穀停絲，引思為歲，歲亦陽止，叨服贲身，身亦昌止，徒勤丹漆，終愧文梓。","sortOrder":94},
  {"id":"s_work_nvlt_4_95","chapterId":"ch_work_nvlt_4","text":"又上巳華光殿詩曰：於維盛世即軒妫，朝酆宴鎬复在斯，朝光灼烁映蘭池。春風婉轉入細枝，時湋顧暮聲合離，輕波微動漾羽卮，河宗海若生蛟螭，浮梁径度跨回漪，朱顏始洽景將移，安得壮士駐奔曦。","sortOrder":95},
  {"id":"s_work_nvlt_4_96","chapterId":"ch_work_nvlt_4","text":"又侍林光殿曲水宴詩曰：宴鎬锵玉鑾，遊汾舉仙軷，榮光泛采旄，脩風動芝蓋，淑氣婉登辰，天行耸雲旆，帳殿臨春篽，帷宮繞芳薈，漸席周羽觴，分墀引回瀨，穆穆寶化昇，濟濟皇陛泰，將御遺風軫，遠侍瑤台會。","sortOrder":96},
  {"id":"s_work_nvlt_4_97","chapterId":"ch_work_nvlt_4","text":"又三日率爾成篇詩曰：麗日屬元巳，年芳具在斯，开花已匝树，流湋复滿枝，洛陽繁華子，長安輕薄兒，東出千金堰，西臨雁鶩陂，遊絲映空轉，高楊拂地垂，绿帻文照曜，紫燕光陆離，清辰戲伊水，薄暮宿蘭池，象筵鳴寶瑟，金瓶汎羽卮，寧憶春蠶起，日暮桑欲萎。","sortOrder":97},
  {"id":"s_work_nvlt_4_98","chapterId":"ch_work_nvlt_4","text":"梁劉孝綽三日侍華光殿曲水宴詩曰：薰祓三陽暮，濯禊元巳初，皇心腃樂飲，帳殿臨春渠，豫遊高夏諺，凯樂盛周居，复以禁林日，丰茸花树舒，羽觴環階轉，清澜傍席疏，妍歌已嘹亮，妙舞复紆餘，九成变絲竹，百戲起龍魚。","sortOrder":98},
  {"id":"s_work_nvlt_4_99","chapterId":"ch_work_nvlt_4","text":"又三日侍安成王曲水宴詩曰：匯泽良孔殷，分區屏中縣，躡跨兼流采，矜唯邇封甸，吾王奄酆畢，折圭承羽傳，不資魯俗移，何待齊風变，東山富遊士，北土無遺彦，一言白璧輕，片善黃金賤，餘辰屬上巳，清祓追前諺，持此陽瀨遊，复展城隅宴，芳洲亘千里，遠近風光扇，方歡厚德重，誰言薄遊倦。","sortOrder":99},
  {"id":"s_work_nvlt_4_100","chapterId":"ch_work_nvlt_4","text":"梁劉孝威侍宴樂遊林光殿曲水詩曰：蒸哉軒頊，赫矣尧心，女媧補石，重華弃金，湯羅禹扇，羲瑟農琴，皇乎備矣，受命君臨，试舟五反，和樂九成，鉤楯秘戲，协律新聲，丹杯水激，絳采坯榮，天吳還往，海若逢迎。又三日侍皇太子宴詩曰：二龍巡夏代，八駿馭周朝，豫遊光帝則，樂飲盛民謠，皇储遵洛禊，濫觴追灞桥，掌祓开神篽，司馬動鑾鑣，周旗交彩毦，晉鼓雜清箫，旌宮臨廣隰，藻衛烁巖椒，蘭樽沿曲折，靈若溯回潮。","sortOrder":100},
  {"id":"s_work_nvlt_4_101","chapterId":"ch_work_nvlt_4","text":"梁庾肩吾三日侍蘭亭曲水宴詩曰：榮星依夜動，鑾駕忽朝遊，旌門臨苑树，相風生鳳樓，春生露泥泥，天覆雲油油，桃花舒玉涧，柳葉暗金溝，禊川分曲洛，帳殿掩芳洲，涌躍赪魚出，參差絳棗浮，百戲俱臨水，千鍾共逐流。","sortOrder":101},
  {"id":"s_work_nvlt_4_102","chapterId":"ch_work_nvlt_4","text":"北齊邢子才三日華林園公宴詩曰：回鑾自樂野，弭蓋屬瑤池，五丞接光景，七友树風儀，芳春時欲遽，覽物惜將移，新萍已冒沼，餘花尚滿枝，草滋径芜没，林長山蔽虧，方筵羅玉俎，激水漾金卮，歌聲斷且續，舞袖合還離。","sortOrder":102},
  {"id":"s_work_nvlt_4_103","chapterId":"ch_work_nvlt_4","text":"隋盧思道上巳禊飲詩曰：山泉好風景，城市厭嚣尘，聊持一樽酒，共尋千里春，餘光下幽桂，夕吹舞青蘋，何言出關後，重有入林人。","sortOrder":103},
  {"id":"s_work_nvlt_4_104","chapterId":"ch_work_nvlt_4","text":"【賦】後漢杜篤祓禊賦曰：王侯公主，暨乎富商，用事伊雒，帷幔玄黃，於是旨酒嘉肴，方丈盈前，浮棗絳水，酹酒醲川，若乃窈窕淑女，美媵艳姝，戴翡翠，珥明珠，曳離袿，立水涯，微風掩壒，纖穀［全後漢文二十八作縠。］低徊，蘭蘇盻蚃，感動情魂，若乃隱逸未用，鸿生俊儒，冠高冕，曳長裾，坐沙渚，談詩書，詠伊呂，歌唐虞。","sortOrder":104},
  {"id":"s_work_nvlt_4_105","chapterId":"ch_work_nvlt_4","text":"晉成公綏洛禊賦曰：考吉日，簡良辰，祓除解禊，同會洛濱，妖童媛女，嬉遊河曲，或振纖手，或濯素足，臨清流，坐沙場，列罍樽，飛羽觴。","sortOrder":105},
  {"id":"s_work_nvlt_4_106","chapterId":"ch_work_nvlt_4","text":"晉張协洛禊賦曰：夫何三春之令月，嘉天氣之氤氲，和風穆以布畅，百卉晔而敷芬，川流清泠以汪濊，原隰葱翠以龍鱗，遊魚瀺灂於渌波，玄鳥鼓翼於高雲，美節慶之動物，悅群生之樂欣，故新服之既成，將禊除於水濱，於是縉紳先生，嘯儔命友，携朋接党，冠童八九，主希孔墨，賓慕顏柳，臨涯詠吟，濯足揮手，乃至都人士女，弈弈祁祁，車駕岬嵑，充溢中逵，粉葩翕習，緣阿被湄，振袖坐風，接衽成帏，若夫權戚之家，豪侈之族，采騎齊鑣，華輪方轂，青蓋雲浮，參差相屬，集乎長洲之浦，曜乎洛川之曲，遂乃停舆蕙渚，稅駕蘭田，朱幔虹舒，翠幕蜺連，羅樽列爵，周以長筵，於是布椒醑，荐柔嘉，祈休吉，蠲百痾，漱清源以涤秽兮，攬绿藻之纖柯，浮素卯［《太平御覽》八十五作卵。］以蔽水，洒玄醪於中河。","sortOrder":106},
  {"id":"s_work_nvlt_4_107","chapterId":"ch_work_nvlt_4","text":"晉褚爽禊賦曰：伊暮春之令月，將解禊於通川，凌元巳之清晨，溯微風之泠然，川回澜以澄映，嶺插崿以霏煙，輕霞舒於翠崖，白雲映乎青天。","sortOrder":107},
  {"id":"s_work_nvlt_4_108","chapterId":"ch_work_nvlt_4","text":"晉夏侯湛禊賦曰：羨暮春之嘉辰，美靈氣之和柔，結方軌之奏路，敷令節而宣遊，爾乃鈴鳴擢翠，旗垂繁纓，微雲乘軒，清風卷旌，飛輪焱起，良馬電驚，車駕鱗萃，男女霧會，服煥羅縠，翠翳連蓋，榮香丸於素襟，結九齡乎時外，粲烂虺韡。混晔發越，若乎朝春挺葩，夕霞抱月，爾乃臨清流，背绿柯，雲幕高接，丹組四羅。","sortOrder":108},
  {"id":"s_work_nvlt_4_109","chapterId":"ch_work_nvlt_4","text":"晉阮瞻上巳會賦曰：臨清川而嘉宴，聊假日以遊娱，荫朝雲而為蓋，讬茂树以為庐，好脩林之蓊鬱，樂草莽之扶疏，列四筵而設席，祈吉祥於斯涂，酌羽觴而交酬，獻遐寿之無疆，同歡情而悅豫，欣斯樂之恺慷，發中懷而絃歌，讬情志於宮商。","sortOrder":109},
  {"id":"s_work_nvlt_4_110","chapterId":"ch_work_nvlt_4","text":"梁萧子范家園三日賦曰：春亦暮止，田家上巳，時將磔於九門，節方郊於七里，扇習習之和風，照遲遲之華晷，飛玄翮之土燕，奪丹焜之山雉，聊結新而濯故，式東流之前軌，居免上漏，树非榛栗，既無擇於爽垲，曾不訪於凶吉，右瞻則青溪千仞，北睹則龍盤秀出，與歲月而荒茫，同林藪之芜密，懽茲嘉月，悅此時良，庭散花蕊，傍插筠篁，洒玄醪於沼沚，浮絳棗於泱泱，觀翠輪之出没，戲青舸之低昂。","sortOrder":110},
  {"id":"s_work_nvlt_4_111","chapterId":"ch_work_nvlt_4","text":"周庾信三月三日華林園馬射賦曰：於時玄鳥司歷，蒼龍馭行，羔獻冰开，桐華萍合，皇帝幸於華林之園，千乘雷動，萬騎雲屯，落花與芝蓋同飛，楊柳與春旗一色，乃命群臣，陳大射之禮，騶虞九節，狸首七章，於是選朱汗之馬，校黃金之埒，紅陽飛鵲，紫燕陆沈，唐成公之驌骦，海西侯之千里，莫不飲羽衔竿，吟猿落雁，鍾鼓振地，埃尘涨天，采則錦市俱移，錢則銅山合徙，實天下之至樂，景福之歡欣者也，歲次昭陽，月在大梁，其日上巳，其時少陽，春吏司職，青祗效祥，徵萬騎於平樂，开千門於建章，皇帝翊四校於仙園，回六龍於天苑，華蓋平飛，風乌細轉，帷宮宿設，帳殿开筵，傍臨細柳，斜界宜年，河漘薙草，渭口浇泉，塴雲五色，的晕重圓，陽管既調，春絃實撫，玉律調鍾，金錞節鼓，於是咀衔拉鐵，逐日追風，併试長秋之埒，俱下蘭池之宮，鳴鞭則汙赭，入埒則尘紅，变三驅而畫鹿，登百尺而懸熊，禮正六耦，詩歌九節，弓如明月對堋，馬似浮雲向埒，雁失群而行斷，猿求林而路絕，乃有六郡雄才，五陵高選，新回馬邑之兵，始罢龍城之戰，尚帶流星，猶乘奔電，始聽鼓而唱筹，即移竿而摽箭，熊耳刻杯，浮雲畫罍，水衡之錢山積，織室之錦霞开，司筵賞至，酒正杯來，既而日下泽宮，筵阑相圃，怅從跸之留歡，眷回鑾之餘武。","sortOrder":111},
  {"id":"s_work_nvlt_4_112","chapterId":"ch_work_nvlt_4","text":"【序】晉王羲之三日蘭亭詩序曰：永和九年，歲在癸丑，暮春之初，會於會稽山陰之蘭亭，脩禊事也，群賢畢至，少長鹹集，此地有崇山峻嶺，茂林脩竹。又有清流激湍，映帶左右，引以為流，流觴曲水，列坐其次，雖無絲竹管絃之盛，一觴一詠，亦足以畅叙幽情，是日也，天朗氣清，惠風和畅，仰觀宇宙之大，俯察品類之盛，所以遊目騁懷，足以極视聽之娱，信足樂也。","sortOrder":112},
  {"id":"s_work_nvlt_4_113","chapterId":"ch_work_nvlt_4","text":"晉孫綽三日蘭亭詩序曰：古人以水喻性，有旨哉斯談，非以停之則清，混之則濁耶，情因所習而遷移，物觸所遇而興感，故振辔於朝市，則充屈之心生，閒步於林野，則遼落之志興，仰瞻羲唐，邈已遠矣，近詠台尚，顧深增懷，為复於暧昧之中，思萦拂之道，屢借山水，以化其鬱結，永一日之足，當百年之溢，以暮春之始，禊於南涧之濱，高嶺千尋，長湖萬頃，隆屈澄汪之势，可為壮矣，乃席芳草，鏡清流，覽卉木，觀魚鳥，具物同榮，資生鹹畅，於是和以醇醪，齊以達觀，泱然兀矣，焉复覺鵬鷃之二物哉。","sortOrder":113},
  {"id":"s_work_nvlt_4_114","chapterId":"ch_work_nvlt_4","text":"宋顏延之三日曲水詩序曰：夫方策既載，皇王之跡已殊，鐘石畢陳，舞詠之情不一，雖淵流遂往，詳略異聞，然其宅天衷，立民極，莫不崇尚其道，神明其位，拓世貽統，固萬葉而為量者也，有宋函夏，帝圖弘遠，高祖以聖武定鼎，規同造物，皇上以叡文承歷，景屬宸居，隆周之卜既永，宗漢之兆在焉，正體毓德於少陽，上宰宣哲於元辅，晷緯昭應，山渎效靈，五方雜遝，四隩來暨，赪茎素毳併柯共穗之瑞，史不絕書，栈山航海逾沙軼漠之貢，府無虛月，日躔胃維，月軌青陆，皇祗發生之始，後王布和之辰，思對上靈之心，以惠庶萌之原，加以二王於邁，出餞戒吉，有詔掌故，爰命司歷，獻陳洛飲之禮，具上巳之儀，南除輦道，北清禁林，左關巖隥，右梁潮源，略亭皋，跨芝廛，苑大液，懷曾山，松石峻峗，葱翠陰煙，遊泳之所攒萃，翔骤之所往還，閱水環階，引池分席，春官聯事，蒼靈奉涂，然後升秘駕，胤緹騎，撫玉鑾，發流吹，以降於行所，禮也，龍文飾辔，青翰侍御，華裔殷至，觀聽骛集，扬袂風山，舉袖陰泽，靓妆藻野，袨服縟川，故以隱赈外區，煥衍都內者矣，上膺萬寿，下禔百福，布筵禀和，阖堂依德，情盤景遽，歡洽日斜，怅釣台之未臨，慨酆宮之不懸，方且排鳳闕以高遊，开爵園而廣宴，併命在位，展詩發志，則夫誦美有章，陳信無愧者欤。","sortOrder":114},
  {"id":"s_work_nvlt_4_115","chapterId":"ch_work_nvlt_4","text":"齊王融三日曲水詩序曰：臣聞出豫為象，鈞天之樂張焉，時乘既位，御氣之駕翔焉，是以得一奉宸，逍遙襄城之域，體元則大，怅望姑射之阿，然窅眇寂寥，其獨適者也，至如夏後兩龍，載驅璿台之上，穆王八駿，如舞瑤水之陰，亦有饗雲，固不與萬民共也，我大齊之握機創歷，誕命建家，接禮貳宮，考庸太室，昭華之珍既徙，延喜之玉攸歸，革宋受天，保生萬國，度邑靜鹿丘之叹，遷鼎息大坰之慚，駿發开其遠祥，定爾固其洪業，皇帝體膺上聖，運鍾下武，冠五行之秀氣，邁三代之英風，昭章雲漢，暉麗日月，猶且具明废寢，昃晷忘餐，懼負重於春冰，懷御奔於秋駕，储後睿哲在躬，妙善居质，內積和順，外發英華，斧藻至德，琢磨令范，若夫族茂麟趾，宗固磐石，跨蹍昌姬，韜軼炎漢，元宰比肩於尚父，中铉繼踵乎周南，分陝流勿剪之歡，來仕允克施之譽，本枝之盛如此，稽古之政如彼，故免群生於湯火，納百姓於休和，引鏡皆明目，臨池無洗耳，沉冥之怨既缺，薖軸之疾已消，讒莠蔑聞，攘爭揜息，稀鳴桴於砥路，鞠茂草於圓扉，侮食來王，左言入侍，一尉候於西東，合車書於南北，偃革辭軒，銷金罢刃，天瑞降，地符升，泽馬來，器車出，江海呈象，龟龍載文，功既成矣，世既貞矣，信可以優遊暇豫，作樂崇德者欤，於時青鳥司开，條風發歲，粵斯上巳，惟暮之春，禊飲之日在茲，風舞之情鹹荡，載懷平圃，乃睠芳林，芳林園者，福地奧區之凑，丹陵若水之舊，殷殷均乎姚泽，膴々尚於周原，飛觀神行，虛簷雲構，離房乍設，層樓間起，負朝陽而抗殿，跨靈沼而浮榮，鏡文虹於綺疏，浸蘭泉於玉砌，幽幽丛薄，秩秩斯幹，新萍泛沚，華桐發岫，雜夭采於柔荑，亂嘤聲於錦羽，禁軒承幸，清宮俟宴，緹帷宿置，帟幕宵懸，既而滅宿登［《文選》四十六作澄。］霞，登光辨色，徐鑾警節，鳴鐘畅音，七萃連鑣，九斿齊軌，爾乃回舆駐早，［《文選》作罕。］嶽镇川渟，睟容有穆，賓儀式序，授幾肆筵，因流波而成次，蕙肴芳醴，任激水而推移，葆佾陳階。金匏在席，戚奏翘舞，籥動邠詩，召鳴鳥於〈山弇〉山，追伶倫於嶰穀，清歌有阕，羽觴無筭，上陳景福之賜，下獻南山之寿，信凯宴於在藻，知和樂於食苹。","sortOrder":115},
  {"id":"s_work_nvlt_4_116","chapterId":"ch_work_nvlt_4","text":"梁簡文帝三日曲水詩序曰：竊以周城洛邑，自流水以禊除，晉集華林，同文軌而高宴，莫不禮具義舉，沓矩重規，昭動神明，雍熙鍾石者也，皇太子生知上德，英明在躬，智湛靈珠，辯均河註，騰茂實於三善，振嘉聲於八區，是節也，上巳屬辰，餘萌達壤，仓庚應律，女夷司候，爾乃分階树羽，疏泉泛爵，蘭觴沿溯，蕙肴來往，賓儀式序，盛德有容，吹發孫枝，聲流嶰穀，舞艳七盤，歌新六变，遊雲駐采，仙鶴來儀，都人野老，雲集霧會，結軫方衢，飛軒照日。","sortOrder":116},
  {"id":"s_work_nvlt_4_117","chapterId":"ch_work_nvlt_4","text":"◇五月五日","sortOrder":117},
  {"id":"s_work_nvlt_4_118","chapterId":"ch_work_nvlt_4","text":"《琴操》曰：介子綏割其腓股，以啖重耳，重耳复國，子綏獨無所得，綏甚怨恨，乃作龍蛇之歌以感之，終不肯出，文公令燔山求之，子綏遂抱木而燒死，文公令民五月五日不得發火，［國語雲介子推。］","sortOrder":118},
  {"id":"s_work_nvlt_4_119","chapterId":"ch_work_nvlt_4","text":"《續漢禮儀志》曰：五月五日，朱索五色柳桃印為門戶飾，以止惡氣。","sortOrder":119},
  {"id":"s_work_nvlt_4_120","chapterId":"ch_work_nvlt_4","text":"《風土記》曰：仲夏端五，烹鶩［原訛骛，據冯校本改。］角黍，端，始也，謂五月初五日也。又以菰葉裹黏米煮熟，謂之角黍。","sortOrder":120},
  {"id":"s_work_nvlt_4_121","chapterId":"ch_work_nvlt_4","text":"續齊諧記曰：屈原五月五日投汨羅而死，楚人哀之，每至此日，竹筒貯米，投水祭之，漢建武中，長沙欧回，白日忽見一人，自稱三闾大夫，謂曰：君當見祭甚善，但常所遺，苦蛟龍所竊，今若有惠，可以楝树葉塞其上，以五采絲縛之，此二物蛟龍所憚也，固依其言，世人作粽，併帶五色絲及楝葉，皆汨羅之遺風也。","sortOrder":121},
  {"id":"s_work_nvlt_4_122","chapterId":"ch_work_nvlt_4","text":"崔寔《四民月令》曰：五月五日，取蟾蜍，可合惡疽瘡，取東行蝼蛄，治婦難產。","sortOrder":122},
  {"id":"s_work_nvlt_4_123","chapterId":"ch_work_nvlt_4","text":"《會稽典錄》曰：女子曹娥者，會稽上虞人，父能絃歌為巫，漢安帝二年五月五日，於縣江溯涛迎波神，溺死，不得尸骸，娥年十四，乃緣江號哭，晝夜不絕聲，七日，遂投江而死。","sortOrder":123},
  {"id":"s_work_nvlt_4_124","chapterId":"ch_work_nvlt_4","text":"抱朴子，蟾蜍萬歲者，頭上有角，頷下有丹書八字再重，五月五日午時取之。陰乾百日，以其足畫地，即為流水。","sortOrder":124},
  {"id":"s_work_nvlt_4_125","chapterId":"ch_work_nvlt_4","text":"又曰：或問辟五兵之道，答曰：以五月五日，作赤靈符，著心前。","sortOrder":125},
  {"id":"s_work_nvlt_4_126","chapterId":"ch_work_nvlt_4","text":"《風俗通》曰：五月五日，以五采絲系臂者，辟兵及鬼，令人不病溫，亦因屈原。","sortOrder":126},
  {"id":"s_work_nvlt_4_127","chapterId":"ch_work_nvlt_4","text":"又曰：五月五日續命縷，俗說以益人命。","sortOrder":127},
  {"id":"s_work_nvlt_4_128","chapterId":"ch_work_nvlt_4","text":"夏小正曰：此日蓄采眾藥，以蠲除毒氣。","sortOrder":128},
  {"id":"s_work_nvlt_4_129","chapterId":"ch_work_nvlt_4","text":"荆楚記曰：荆楚人，以五月五日併蹋百草，采艾以為人，懸門戶上，以禳毒氣。","sortOrder":129},
  {"id":"s_work_nvlt_4_130","chapterId":"ch_work_nvlt_4","text":"又曰：屈原以是日死於汨羅，人傷其死，所以併將舟楫以拯之，今之競渡，是其遺跡。","sortOrder":130},
  {"id":"s_work_nvlt_4_131","chapterId":"ch_work_nvlt_4","text":"《大戴禮》曰：五月五日蓄蘭為沐浴。","sortOrder":131},
  {"id":"s_work_nvlt_4_132","chapterId":"ch_work_nvlt_4","text":"《楚辭》曰：浴蘭湯兮沐芳華。","sortOrder":132},
  {"id":"s_work_nvlt_4_133","chapterId":"ch_work_nvlt_4","text":"【詩】梁王筠五日望采拾詩曰：長絲表良節，金縷應嘉辰，結芦同楚客，采艾異詩人，折花競鮮彩，拭露染芳津，含娇起斜眄，斂笑動微嚬，獻璫依洛浦，懷珮似江濱。","sortOrder":133},
  {"id":"s_work_nvlt_4_134","chapterId":"ch_work_nvlt_4","text":"◇七月七日","sortOrder":134},
  {"id":"s_work_nvlt_4_135","chapterId":"ch_work_nvlt_4","text":"《列仙傳》曰：陶安公者，六安鑄冶師行火者，朱雀止冶上，曰：安公，冶與天通，七月七日，迎汝以赤龍，［事具仙部。］","sortOrder":135},
  {"id":"s_work_nvlt_4_136","chapterId":"ch_work_nvlt_4","text":"又曰：王子乔見柏長［初學記四，《太平御覽》三十一作桓良。］曰：告我家，七月七日，待我於缑氏山頭，至時，乘白鶴在山頭，望之不得到，舉手謝時人，數日而去。","sortOrder":136},
  {"id":"s_work_nvlt_4_137","chapterId":"ch_work_nvlt_4","text":"《漢書》曰：武帝七月七日，生於漪蘭殿。","sortOrder":137},
  {"id":"s_work_nvlt_4_138","chapterId":"ch_work_nvlt_4","text":"《漢武故事》曰：七月七日，上於承華殿斋，正中，忽有一青鳥從西方來，集殿前，上問東方朔，朔曰：此西王母欲來也，有頃王母至，［事具鳥部。］","sortOrder":138},
  {"id":"s_work_nvlt_4_139","chapterId":"ch_work_nvlt_4","text":"崔寔《四民月令》：七月七日，曝經書，設酒脯時果，散香粉於筵上，祈請於河鼓織女，言此二星神當會，守夜者鹹懷私原，或雲，見天漢中，有奕奕正白氣，如地河之波，辉辉有光曜五色，以此為徵應，見者便拜乞原，三年乃得。","sortOrder":139},
  {"id":"s_work_nvlt_4_140","chapterId":"ch_work_nvlt_4","text":"《竹林七賢論》曰：阮鹹，字仲容，籍兄子也，諸阮前世皆儒學，內足於财，唯籍一生，尚道弃事，好酒而貧，舊俗，七月七日，法當曬衣，諸阮庭中烂然，莫非綈錦，鹹時總角，乃竖長竿，摽大布犢鼻於庭中，曰：未能免俗，聊复爾爾，［原訛耳，據冯校本改。］","sortOrder":140},
  {"id":"s_work_nvlt_4_141","chapterId":"ch_work_nvlt_4","text":"《世說》曰：郝隆，七月七日，見鄰人皆曝曬衣物，隆乃仰臥出腹，雲曬書。","sortOrder":141},
  {"id":"s_work_nvlt_4_142","chapterId":"ch_work_nvlt_4","text":"續齊諧記曰：桂陽城武丁，有仙道，謂其弟曰：七月七日，織女當渡河，諸仙悉還宮，弟問曰：織女何事渡河，答曰：織女暫詣牵牛，世人至今雲織女嫁牵牛也。","sortOrder":142},
  {"id":"s_work_nvlt_4_143","chapterId":"ch_work_nvlt_4","text":"【詩】古詩曰：迢迢牵牛星，皎皎河漢女，纖纖擢素手，紥紥弄機杼，終日不成章，涕泣零如雨，河漢清且淺，相去詎幾許，盈盈一水間，脈脈不得語。","sortOrder":143},
  {"id":"s_work_nvlt_4_144","chapterId":"ch_work_nvlt_4","text":"晉潘尼七月七日侍皇太子宴玄圃園詩曰：商風初授，辰火微流，朱明送夏，少昊迎秋，嘉木茂園，芳草被畴，於時我後，以豫以遊。","sortOrder":144},
  {"id":"s_work_nvlt_4_145","chapterId":"ch_work_nvlt_4","text":"晉李充七月七日詩曰：朗月垂玄景，洪漢截皓蒼，牵牛難牵牧，織女守空襄，河廣尚可越，怨此漢無梁。","sortOrder":145},
  {"id":"s_work_nvlt_4_146","chapterId":"ch_work_nvlt_4","text":"晉蘇彦七月七日詠織女詩曰：織女思北沚，牵牛叹南陽，時來嘉慶集，整駕巾玉箱，琼珮垂藻蕤，霧裾結雲裳，釋辔紫微庭，解礻令碧琳堂，歡宴未及究，晨暉照扶桑，怅怅一宵促，遲遲別日長。","sortOrder":146},
  {"id":"s_work_nvlt_4_147","chapterId":"ch_work_nvlt_4","text":"宋孝武七夕詩曰：白日傾晚照，絃月升［原訛外，據冯校本改。］初光，炫炫葉露滿，肅肅庭風扬，瞻言媚天漢，幽期濟河梁，服箱從奔轺，紈綺闕成章，解帶遽回軫，誰雲秋夜長，愛聚双情款，念離兩心傷。","sortOrder":147},
  {"id":"s_work_nvlt_4_148","chapterId":"ch_work_nvlt_4","text":"宋南平王劉鑠七夕詠牛女詩曰：秋動清風扇，火移炎氣歇，廣簷含夜陰，高軒通夕月，安步巡芳林，傾望極雲闕，組幕萦漢陳，龍駕凌霄發，沉情未申寫，飛光已飄忽，來對眇難期，今歡自茲没。","sortOrder":148},
  {"id":"s_work_nvlt_4_149","chapterId":"ch_work_nvlt_4","text":"宋謝惠連七夕詠牛女詩曰：落日隱簷楹，升月照帘栊，团团滿葉露，淅淅振條風，蹀足循廣除，瞬目矖曾穹，雲漢有靈匹，弥年闕相從，遐川阻昵愛，脩渚曠清容，弄杼不成藻，耸辔骛前蹤，昔離秋已兩，今聚夕無双，傾河易回斡，款顏難久悰，沃若靈駕旋，寂寥雲幄空，留情顧華寢，遙心逐奔龍。","sortOrder":149},
  {"id":"s_work_nvlt_4_150","chapterId":"ch_work_nvlt_4","text":"宋王僧達七夕月下詩曰：遠山斂氛祲，廣庭扬月波，氣往風集隙，秋還露泫柯，節氣既已孱，中宵振綺羅，來歡詎終夕，收淚泣分河。","sortOrder":150},
  {"id":"s_work_nvlt_4_151","chapterId":"ch_work_nvlt_4","text":"宋顏延之為織女赠牵牛詩曰：婺女俪經星，姮娥栖飛月，慚無二媛靈，讬身侍天闕，閶阖殊未暉，鹹池豈沐發，漢陰不夕張，長河為誰越，雖有促宴期，方須涼風發。","sortOrder":151},
  {"id":"s_work_nvlt_4_152","chapterId":"ch_work_nvlt_4","text":"宋謝靈運七夕詠牛女詩曰：火逝首秋節，明經絃月夕，月絃光照戶，秋首風入隙，陵風步曾岑，凭雲肆遙脈，徙倚西北庭，竦踴東南觌，紈綺無報章，河漢有駿軛。","sortOrder":152},
  {"id":"s_work_nvlt_4_153","chapterId":"ch_work_nvlt_4","text":"宋謝莊七夕夜詠牛女應製詩曰：輟機起春暮，停箱動秋衿，璇居照漢右，芝駕肅河陰，容裔泛星道，逶迤濟煙潯，陆離迎宵佩，倏烁望昏簪，俱傾環氣怨，共歇浃年心，珠殿棋未沫，瑤庭露已深，夕清豈淹拂，絃辉無人臨。","sortOrder":153},
  {"id":"s_work_nvlt_4_154","chapterId":"ch_work_nvlt_4","text":"梁武帝七夕詩曰：白露月下圓，秋風枝上鮮，瑤台含碧霧，羅幕生紫煙，妙會非綺節，佳期乃涼年，玉壶承夜急，蘭膏依晓煎，昔悲漢難越，今傷河易旋，怨咽双念斷，凄悼兩情懸。","sortOrder":154},
  {"id":"s_work_nvlt_4_155","chapterId":"ch_work_nvlt_4","text":"梁簡文帝七夕穿針詩曰：怜從帳里出，相見夜窗开，針欹疑月暗，縷散恨風來。","sortOrder":155},
  {"id":"s_work_nvlt_4_156","chapterId":"ch_work_nvlt_4","text":"梁柳惲七夕穿針詩曰：代馬秋不歸，緇紈無复緒，迎寒理夜縫，映月抽纖縷，清露下羅衣，秋風吹玉柱，流景對秋夕，餘光欲難駐。","sortOrder":156},
  {"id":"s_work_nvlt_4_157","chapterId":"ch_work_nvlt_4","text":"梁劉遵七夕穿針詩曰：步月如有意，情來不自禁，向光抽一縷，舉袖弄双針。","sortOrder":157},
  {"id":"s_work_nvlt_4_158","chapterId":"ch_work_nvlt_4","text":"梁劉孝威七夕穿針詩曰：縷亂恐風來，衫輕羞指現，故穿双眼針，時縫合歡扇。","sortOrder":158},
  {"id":"s_work_nvlt_4_159","chapterId":"ch_work_nvlt_4","text":"梁沈約織女赠牵牛詩曰：紅妆與明鏡，二物本相親，用持施點畫，不照離居人，往秋雖一照，一照還复尘，尘生不复拂，蓬首對河津，冬夜寒如是，寧遽道陽春，初商怱［《初學記》四作忽。］雲至，暫得奉衣巾，施〈礻令〉［《初學記》作衿。］誠已故，每聚忽如新。","sortOrder":159},
  {"id":"s_work_nvlt_4_160","chapterId":"ch_work_nvlt_4","text":"梁王筠代牵牛答織女詩曰：新知與生別，由來傥相值，如何寸心中，一霄懷兩事，歡娱未繾綣，倏忽成離異，終日遙相望，秪益生愁思，猶憶今春悲，尚有故年淚，忽遇長河轉，獨喜涼飆至，奔情翊鳳軫，精阿警龍辔。","sortOrder":160},
  {"id":"s_work_nvlt_4_161","chapterId":"ch_work_nvlt_4","text":"梁范雲望織女詩曰：盈盈一水邊，夜夜空自怜，不辭精衛苦，河流未可填，寸情百重結，一心萬處懸，原作双青鳥，共舒明鏡前。","sortOrder":161},
  {"id":"s_work_nvlt_4_162","chapterId":"ch_work_nvlt_4","text":"梁劉孝威詠織女詩曰：金钿已照耀，白日未蹉跎，欲待黃昏至，含娇渡淺河。","sortOrder":162},
  {"id":"s_work_nvlt_4_163","chapterId":"ch_work_nvlt_4","text":"梁何遜七夕詩曰：仙車駐七驤，鳳駕出天潢，月映九微火，風吹百和香，來歡蹔巧笑，還淚已啼妆，別離不得語，河漢漸湯湯。","sortOrder":163},
  {"id":"s_work_nvlt_4_164","chapterId":"ch_work_nvlt_4","text":"梁庾肩吾七夕詩曰：玉匣卷懸衣，高樓开夜扉，姮娥隨月落，織女逐星移。離前忿促夜，別後對空機，倩語雕陵鵲，填河未可飛。","sortOrder":164},
  {"id":"s_work_nvlt_4_165","chapterId":"ch_work_nvlt_4","text":"又奉使江州船中七夕詩曰：九江逢七夕，初絃值早秋，天河來映水，織女欲攀舟，漢使俱為客，星槎共逐流，莫言相送浦，不及穿針樓。","sortOrder":165},
  {"id":"s_work_nvlt_4_166","chapterId":"ch_work_nvlt_4","text":"北齊邢子才七夕詩曰：盈盈河水侧，朝朝長叹息，不吝漸衰苦，波流詎可测，秋期忽雲至，停梭理容色，束衿未解帶，回鑾已霑軾，不見眼中人，誰堪機上織，原逐青鳥去，蹔因希羽翼。","sortOrder":166},
  {"id":"s_work_nvlt_4_167","chapterId":"ch_work_nvlt_4","text":"隋江總七夕詩曰：漢曲天榆冷，河邊月桂秋，婉娈期今夜，飄飖渡淺流，輪隨月宿轉，路逐采雲浮，橫波翻泻淚，束素反緘愁，此時機杼息，獨向紅妆羞。","sortOrder":167},
  {"id":"s_work_nvlt_4_168","chapterId":"ch_work_nvlt_4","text":"杜審言七夕詩曰：白露含明月，青雲斷絳河，天街七襄轉，關道二神過，襦服锵環珮，香筵拂綺羅，年年今夜盡，機杼別情多。","sortOrder":168},
  {"id":"s_work_nvlt_4_169","chapterId":"ch_work_nvlt_4","text":"隋王蜰七夕詩曰：天河橫欲晓，鳳駕俨應飛，落月移妆鏡，浮雲動別衣，懽逐今宵盡，愁隨還路歸，猶將宿昔淚，更上去年機。","sortOrder":169},
  {"id":"s_work_nvlt_4_170","chapterId":"ch_work_nvlt_4","text":"隋張文恭七夕詩曰：鳳律驚秋氣，龍梭靜夜機，星桥百枝動，雲路七香飛，映月回雕扇，凌霞曳綺衣，含情向華幄，流態入重闈，懽餘夕漏盡，怨結晓驂歸，誰念分河漢，還憶兩心违。","sortOrder":170},
  {"id":"s_work_nvlt_4_171","chapterId":"ch_work_nvlt_4","text":"【賦】隋庾信七夕賦曰：兔月先上，羊燈次安，睹牛星之曜景，视織女之阑幹，於是秦娥麗妾，趙艳佳人，窈窕名燕，逶迤姓秦，嫌朝妆之半故，怜晚拭之全新，此時併舍房栊，共往庭中，縷條紧而貫矩，針鼻細而穿矩，［《初學記》四作空。］","sortOrder":171},
  {"id":"s_work_nvlt_4_172","chapterId":"ch_work_nvlt_4","text":"南齊謝朓七夕賦曰：金祗司姖，火曜方流，素鍾當御，夷則鳴秋，朱光既夕，涼雲始浮，盈多靈［《初學記》四作夕露。］之藹藹，升夜月之悠悠，步廣庭而延膝，［《初學記》作睞。］屬天媛而淹留，嗟斯靈之淑景，招好仇於服箱，厭［《初學記》作靨。］白玉而為飾，霏丹霞而為裳，回龍駕之容裔，亂鳳管之凄锵，軾帝車而捐玦，凌天津而上翔，怅漢渚之夕涨，欣河廣之既梁，臨瑤席而宴語，綿含睇而蛾扬，嗟蘭夜［《初學記》作阑夜，而難永，泣會促而怨長，撫鳴琴而脩浩，浣安歌而自傷，歌曰：月殿清兮桂醑酬，雲幄靜兮香風浮，龍鑣蹀兮玉鑾整，睠星河兮不可留。］","sortOrder":172},
  {"id":"s_work_nvlt_4_173","chapterId":"ch_work_nvlt_4","text":"◇七月十五","sortOrder":173},
  {"id":"s_work_nvlt_4_174","chapterId":"ch_work_nvlt_4","text":"《荆楚歲時記》曰：七月十五日，僧尼道俗，悉營盆供諸寺院。","sortOrder":174},
  {"id":"s_work_nvlt_4_175","chapterId":"ch_work_nvlt_4","text":"《盂蘭盆經》雲，有七葉功德，併幡花歌鼓果食送之，蓋由此。","sortOrder":175},
  {"id":"s_work_nvlt_4_176","chapterId":"ch_work_nvlt_4","text":"又曰：目連比丘，見其亡母生饿鬼中，即以鉢盛飯，往餉其母，食未入口，化成火炭，遂不得食，目連大叫，馳還白佛，佛言，汝母罪重，非汝一人力所奈何，當須十方眾僧威神之力，至七月十五日，當為七代父母現在父母厄難中者，具百味五果，以著盆中，供養十方大德，佛敕眾僧，皆為施主咒原，七代父母，行禪定意，然後受食，是時，目連母得脱一劫饿鬼之苦，目連白佛，未來世佛弟子行孝順者，亦應奉盂蘭盆為爾可否，佛言大善，故後代人因此廣為華飾，乃至刻木割竹，飴〈虫葛〉剪采，模花果之形，極工妙之巧。","sortOrder":176},
  {"id":"s_work_nvlt_4_177","chapterId":"ch_work_nvlt_4","text":"道經曰：七月十五，中元之日，地官校勾，搜選人間，分別善惡，諸天聖眾，普詣宮中，簡定劫數，人鬼傳錄，饿鬼囚徒，一時皆集，以其日作玄都大獻於玉京山，采諸花果，珍奇異物，幢幡寶蓋，清膳飲食，獻諸聖眾，道士於其日夜講誦是經，十方大聖，齊詠靈篇，囚徒饿鬼俱飽滿，免於眾苦，得還人中。","sortOrder":177},
  {"id":"s_work_nvlt_4_178","chapterId":"ch_work_nvlt_4","text":"【賦】楊蜅盂蘭盆賦曰：浑元告秋，羲和奏晓，太陰望兮圓魄皎，閶阖开兮涼風裊，四海澄兮百川皛，陰陽肅兮天地窅，扫離宮，清重閣，設皇邸，張翠幕。鸞飛鳳翔，晱陽倏烁，雲舒霞布，翕赫冥［《初學記》四作{勿目}。］霍，陳法供，飾盂蘭，壮神功之妙物，何造化之多端，青莲吐而非夏，赪果搖而不寒，銅鐵鉛錫，璆琳琅玕，映以甘泉之玉树，冠以承露之金盤，憲章三極，儀形萬類，上廖廓兮法天。下安貞兮象地，殫怪力，窮神異，少君王子，掣曳兮若束，［《初學記》四作來。］玉女瑤姬，翩仙兮不至，鳴鷫鹴與鸑鷟，舞鶤雞與翡翠，毒龍怒兮赫然，狂象奔兮沉醉，怖魍魉，潛魑魅，離娄明目，不足見其精微，匠石洗心，不足徵其奧秘，夫其遠也，天台璨起，繞之以赤霞，夫其近也，削成孤峙，覆之以莲花，晃兮瑤台之帝室，赩兮金闕之仙家，其高也上諸天於大梵，其廣也遍諸法於恒沙，上可以荐元府［《初學記》四。］《太平御覽》三十二作符，於七廟，下可以納群動於三車，［原訛軍，據冯校本改。］","sortOrder":178},
  {"id":"s_work_nvlt_4_179","chapterId":"ch_work_nvlt_4","text":"◇九月九日","sortOrder":179},
  {"id":"s_work_nvlt_4_180","chapterId":"ch_work_nvlt_4","text":"《風土記》曰：九月九日，律中無射而數九，俗尚此月，折茱萸房以插頭，言辟除惡氣而御初寒。","sortOrder":180},
  {"id":"s_work_nvlt_4_181","chapterId":"ch_work_nvlt_4","text":"《續晉陽秋》曰：陶潛嘗九月九日無酒，宅邊菊丛中，摘菊盈把，坐其侧久，望見白衣至，乃王弘送酒也，即便就酌，醉而後歸。","sortOrder":181},
  {"id":"s_work_nvlt_4_182","chapterId":"ch_work_nvlt_4","text":"續齊諧記曰：汝南桓景，隨費長房遊學累年，長房謂之曰：九月九日，汝家當有灾厄，急宜去，令家人各作絳囊，盛茱萸以系臂，登高飲菊酒，此禍可消，景如言，舉家登山，夕還家，見雞狗牛羊，一時暴死，長房聞之曰：代之矣，今世人每至九日，登山飲菊酒，婦人帶茱萸囊是也。","sortOrder":182},
  {"id":"s_work_nvlt_4_183","chapterId":"ch_work_nvlt_4","text":"孟嘉傳曰：嘉為桓溫參軍，既和而正，溫甚重之，九月九日，溫遊龍山，參僚畢集，時佐吏併著戎服，有風至，吹嘉帽墮落，溫謂左右及賓客勿言，以觀其舉止。","sortOrder":183},
  {"id":"s_work_nvlt_4_184","chapterId":"ch_work_nvlt_4","text":"《臨海記》曰：郡北四十步，有湖山，山甚平正，可容數百人坐，民俗極重，每九日菊酒之辰，宴會於此山者，常至三四百人。","sortOrder":184},
  {"id":"s_work_nvlt_4_185","chapterId":"ch_work_nvlt_4","text":"【詩】宋謝瞻九日從宋公戲馬台詩曰：風至授寒服，霜降休百工，巢幕無留燕，遵渚有來鸿，輕霞冠秋日，迅商薄清穹，聖心眷嘉節，鳴鑾戾行宮，四筵霑芳醴，中堂起絲桐，扶光迫西汜，歡餘宴有窮。","sortOrder":185},
  {"id":"s_work_nvlt_4_186","chapterId":"ch_work_nvlt_4","text":"宋［原訛來，據冯校本改。］謝靈運九日從宋公戲馬台送孔令詩曰：季秋朔邊苦，旅雁违霜雪，凄凄陽卉腓，皎皎寒潭絜，良辰感聖心，雲旗興暮節，鳴葭戾朱宮，蘭卮獻時哲，歸客逐海隅，脱冠謝朝列，河流有急澜，浮驂無缓轍。","sortOrder":186},
  {"id":"s_work_nvlt_4_187","chapterId":"ch_work_nvlt_4","text":"齊竟陵王萧子良九日侍宴詩曰：月殿風轉，層台氣寒，高雲斂色，遙露已团，式詔司警，言戾秋峦，輕觴時荐，落英可餐。","sortOrder":187},
  {"id":"s_work_nvlt_4_188","chapterId":"ch_work_nvlt_4","text":"齊王俭侍皇太子九日玄圃宴詩曰：明明储後，冲默其量，徘徊禮樂，優遊風尚，微言外融，幾神內王，就日齊暉，儀雲等望，本茂條榮，源澄流絜，漢稱間平，周雲魯衛，咨我藩華，方軌前軼，秋日在房，鸿雁來翔，寥寥清景，霭霭微霜，草木搖落，幽蘭獨芳，眷言淄苑，尚想濠梁，既畅旨酒，亦飽徽猷，有來斯悅，無遠不柔。","sortOrder":188},
  {"id":"s_work_nvlt_4_189","chapterId":"ch_work_nvlt_4","text":"梁簡文帝九日侍皇太子樂遊苑詩曰：離光麗景，神英春裕，副極儀天，金锵玉度，監撫昭明，善物宣布，惠润崑琼，泽熙垂露，秋晨精曜，駕動宮闈，露點金節，霜沉玉璣，玄戈侧影，［原脱，據冯校本補。］翠羽翻暉，庭回鶴蓋，水照犀衣，蘭羞荐俎，竹酒澄芬，千音寫鳳，百戲承雲，紫燕躍武，赤兔越空，橫飛鳥箭，半轉蛇弓。","sortOrder":189},
  {"id":"s_work_nvlt_4_190","chapterId":"ch_work_nvlt_4","text":"又九日賦韻詩曰：是節协陽數，高秋氣已精，簷芝逐月啟，帷風依夜清，遠燭承歌黛，斜桥聞履聲，梁尘下未息，共愛賞心併。","sortOrder":190},
  {"id":"s_work_nvlt_4_191","chapterId":"ch_work_nvlt_4","text":"梁沈約為臨川王九日侍太子宴詩曰：涼風比起，高雁南翻，葉浮楚水，草折梁園，凄清霜野，惆怅晨鵾，雲輕寒树，日麗秋原，三金廣設，六羽高陳，寒英始獻，涼酎初醇，靡靡神襟，锵锵群彦，思媚储猷，洽和奉宴，恩畅蘭席，歡同桂殿，景遽樂推，臨風以眷，麗景天枝，位非德舉，任伍辰階，祚均河楚，負嶽未勝，瞻雲難侣，望古興惕，心焉載佇。","sortOrder":191},
  {"id":"s_work_nvlt_4_192","chapterId":"ch_work_nvlt_4","text":"又九日侍宴樂遊苑詩曰：凭玉宅海，端扆御天，上流飛壑，靜震騰川，凝神貫極，摛道漏泉，西裘委衽，南風在絃，暮芝始绿，年桂初丹，上林葉下，沧池水寒，霜霑玉树，雁動輕澜，停跸玉陛，徙衛璇墀，琱箱鳳采，羽蓋鸞姿，虹旌迢遰，翠華葳蕤，禮弘灞汭，義高洛湄。","sortOrder":192},
  {"id":"s_work_nvlt_4_193","chapterId":"ch_work_nvlt_4","text":"梁丘遲九日侍宴樂遊苑詩曰：朱明已謝，蓐收司禮，爰理秋祓，備扬旌棨，奉璋瓘瓘，金貂濟濟，上林弘敞，離宮非一，采殿回風，丹樓映日，隨珠甲帳，屯衛周悉，睟容徐動，天儀澄謐，雲物遊颺，光景高麗，枯葉未落，寒花委砌，絲桐激舞，楚雅閒慧，參差繁响，殷勤流詣。","sortOrder":193},
  {"id":"s_work_nvlt_4_194","chapterId":"ch_work_nvlt_4","text":"梁任昉九日侍宴樂遊苑詩曰：帝德峻韶夏，王功書頌平，共貫沿五勝，獨道邁三英，我皇撫歸運，時乘信告成，一唱革鍾石，再撫被絲笙，黃草歸雒木，梯山廌玉榮，時來濁河变，瑞起溫洛清，物色動宸眷，民豫降皇情。","sortOrder":194},
  {"id":"s_work_nvlt_4_195","chapterId":"ch_work_nvlt_4","text":"梁劉苞九日侍宴樂遊苑正陽堂詩曰：六郡良家子，幽併遊俠兒，立乘爭飲羽，倒騎競紛馳，鳴珂飾華毦，金鞍映玉羁，膳羞殫海陆，和齊眠秋宜，雲飛雅琴奏，風起洞箫吹，曲終高宴罢，景落树陰移，微薄承嘉惠，飲德良不赀，取效績無紀，感恩心自知。","sortOrder":195},
  {"id":"s_work_nvlt_4_196","chapterId":"ch_work_nvlt_4","text":"梁王脩己九日詩曰：霜威始落翠，寒氣初入堂，隨珠烂似燭，懸黎疑夜光，舞步因絃折，歌聲隨袂扬，夜深聞漏缓，簷虛覺唱長。","sortOrder":196},
  {"id":"s_work_nvlt_4_197","chapterId":"ch_work_nvlt_4","text":"梁劉孝威九日酌菊花酒詩曰：露花疑始摘，羅衣似適熏，餘杯度不取，欲持娇使君。","sortOrder":197},
  {"id":"s_work_nvlt_4_198","chapterId":"ch_work_nvlt_4","text":"梁何遜為西丰侯九日侍宴樂，遊苑詩曰：皇德無與讓，重規袭帝勋，垂衣化比屋，卷領慎為君，翾飛悅有道，卉木荷平分，宸襟動時豫，歲序屬涼氛，城霞旦晃朗，槐霧晓氤氲，鸞和馳八袭，鳳駕啟千群，羽觴歌湛露，佾舞奏承雲，禁林終宴晚，華池物色曛，疏树翻高葉，寒流聚細文，梁庾肩吾侍宴九日詩曰：轍跡光周頌，巡遊减夏功，鉤陳萬騎轉，閶阖九門通，秋暉逐行漏，朔氣繞相風，獻寿重陽節，回鸞上苑中，疏山开輦道，間树出離宮，玉醴吹花菊，銀床落井桐，飲羽山西射，浮雲冀［《初學記》四作冀。］","sortOrder":198},
  {"id":"s_work_nvlt_4_199","chapterId":"ch_work_nvlt_4","text":"北驄，尘飛金埒滿，葉破柳條空。","sortOrder":199},
  {"id":"s_work_nvlt_4_200","chapterId":"ch_work_nvlt_4","text":"周王襃九日從駕詩曰：黃山獵地廣，青門官路長，律改三秋節，氣應九鍾霜，曙影初分地，暗色始成光，交旆長秋坂，緹幕杏間堂，射馬垂双帶，丰貂佩兩璜，苑寒梨树紫，山秋菊葉黃，終慚屬車對，空假侍中郎。","sortOrder":200},
  {"id":"s_work_nvlt_4_201","chapterId":"ch_work_nvlt_4","text":"【賦】宋傅亮九月九日登陵，嚣馆賦曰：歲九旻之暮月，肅晨駕而北逝，度回壑以停轅，凌孤馆而遠憩，何物惨而節哀。又雲悠而風厲，悴绿蘩於寒渚，陨丰灌於荒澨，玩中原之芬菊，惜蘭圃之彫蕙，旌竹柏之劲心，謝梧楸之零脆，爾乃流眄平隰，落日還皋，於感具盈，在物周骚，聆離鵾之凄响，沂鳴林之瀏飆，彼遊子之苦傷，每寤叹於我勞，矧集悲而鍾苦，疚寸心其如忉，眇天末以遙瞪，怨故乡之阻遼。","sortOrder":201},
  {"id":"s_work_nvlt_4_202","chapterId":"ch_work_nvlt_4","text":"【書】魏文帝與鍾繇書曰：歲往月來，忽复九月九日，九為陽數，而日月併應，俗嘉其名，以為宜於長久，故以享宴高會，是月律中無射，言群木庶草，無有射而生，至於芳菊，紛然獨榮，非夫含乾坤之純和，體芬芳之淑氣，孰能如此，故屈平悲冉冉之將老，思食秋菊之落英，辅體延年，莫斯之貴，謹奉一束，以助彭祖之術。","sortOrder":202},
  {"id":"s_work_nvlt_4_203","chapterId":"ch_work_nvlt_4","text":"《藝文類聚》　唐·欧陽詢","sortOrder":203},
  {"id":"s_work_nvlt_5_1","chapterId":"ch_work_nvlt_5","text":"卷五歲時下","sortOrder":1},
  {"id":"s_work_nvlt_5_2","chapterId":"ch_work_nvlt_5","text":"○社［按當作祖，說詳下。］伏熱寒腊律歷","sortOrder":2},
  {"id":"s_work_nvlt_5_3","chapterId":"ch_work_nvlt_5","text":"◇社［按本篇據北堂書鈔一百五十五祖篇，當作祖，今篇目作社，及條內各社字，疑均後人臆改(詳各條下。)正月祖祭，禮始漢代，見續漢書禮儀志註，通典四十四。］","sortOrder":3},
  {"id":"s_work_nvlt_5_4","chapterId":"ch_work_nvlt_5","text":"《風俗通》曰：謹按禮傳，共工之子曰脩，好遠遊，舟車所至，足跡所達，靡不窮覽，故祀以為社［風俗通八，北堂書鈔一百五十五作祖，神。］","sortOrder":4},
  {"id":"s_work_nvlt_5_5","chapterId":"ch_work_nvlt_5","text":"《毛詩》曰：韓侯出祖，出宿於屠，顯甫餞之，清酒百壶，其肴惟何，炰鱉鮮魚。其蔌惟何，惟筍及蒲，其赠惟何，乘馬路車。","sortOrder":5},
  {"id":"s_work_nvlt_5_6","chapterId":"ch_work_nvlt_5","text":"左傳昭上曰：楚靈王成章華之台，原與諸侯樂［左傳昭七年作落。］之，蒍啟疆來召公，公將往，夢襄公社，［左傳昭七年作祖，下同。］梓慎曰：君不果行，襄公之適楚也，夢周公社而行，今襄公實社，君不行，子服惠伯曰：行，先君未嘗適楚，故周公祖道之，襄公適楚矣，而社以道，君不行何之，三月，公如楚。","sortOrder":6},
  {"id":"s_work_nvlt_5_7","chapterId":"ch_work_nvlt_5","text":"《魏志》曰：王脩年七歲，丧母，母以社［北堂書鈔一百五十五作祖，下同。］日亡，來歲鄰里社，脩感念母悲哀，其鄰里聞之，為之罢社。","sortOrder":7},
  {"id":"s_work_nvlt_5_8","chapterId":"ch_work_nvlt_5","text":"武陵先賢傳，潘京為州辟，進謁，值社會，因得見，次及，探得不孝，刺史問曰：辟士為不孝耶，京舉板答曰：今為忠臣，不得复為孝子，其機辯如此。","sortOrder":8},
  {"id":"s_work_nvlt_5_9","chapterId":"ch_work_nvlt_5","text":"魏台訪議曰：帝問何用未社［北堂書鈔一百五十五作祖，下同。］丑腊，王肅對曰：魏，土也，土畏木，丑之明日便寅，寅，木也，故以丑腊，土成於未，故於歲始未社也。","sortOrder":9},
  {"id":"s_work_nvlt_5_10","chapterId":"ch_work_nvlt_5","text":"【詩】晉潘尼皇太子社［北堂書鈔一百五十五作祖，下准此。］詩曰：太簇协青陽，履端發歲首，孟月涉初旬，吉日惟上酉，我後邇天休，設社祈遐耇。","sortOrder":10},
  {"id":"s_work_nvlt_5_11","chapterId":"ch_work_nvlt_5","text":"【序】晉嵇含社［北堂書鈔一百五十五，《初學記》十三作祖，下同。］賦序曰：社之在於世尚矣，自天子至於庶人，莫不鹹用，有漢卜日丙午，魏氏釋［《初學記》十三作擇］用丁未，至於大晉，則社孟月之酉日，各因其行運，三代固有不同，雖共奉社，而莫議社之所由興也，說文雲，祈請道神為［北堂書鈔一百五十五，《初學記》十三作謂。］之社，有事於道者，吉凶偕名。","sortOrder":11},
  {"id":"s_work_nvlt_5_12","chapterId":"ch_work_nvlt_5","text":"【祭文】後漢蔡邕祝社［北堂書鈔一百五十五作祖。］文曰：元正令午，時惟嘉良，乾坤交泰，太蔟運陽，乃祀社靈，以祈福祥。","sortOrder":12},
  {"id":"s_work_nvlt_5_13","chapterId":"ch_work_nvlt_5","text":"晉應硕祝社［按文雲吉酉辰良，據嵇含賦，晉祖日用酉，是亦當作祖，下准此。］文曰：元首肇建，吉酉辰良，五政敷惠，四教初扬，萬類資新，英穎擢章，穀風涤秽，日和時光，命於嘉賓，宴茲社箱，敬响社君，休祚是將，嘉肴綺错，白茅荐恭，有肉如墀，有酒如江，社君既眷，祇肅威容。","sortOrder":13},
  {"id":"s_work_nvlt_5_15","chapterId":"ch_work_nvlt_5","text":"歷忌釋曰：伏者何也，金氣伏藏之日也，四時代謝，皆以相生，立春木代水，水生木，立夏火代木，木生火，立冬水代金，金生水，至於立秋，以金代火，金畏於火，故至庚日必伏，庚者金故也。","sortOrder":15},
  {"id":"s_work_nvlt_5_16","chapterId":"ch_work_nvlt_5","text":"《漢書》曰：東方朔，伏日詔賜諸侍郎肉，朔獨不待詔，拔劍割肉，懷之而去，［事具肉部。］","sortOrder":16},
  {"id":"s_work_nvlt_5_17","chapterId":"ch_work_nvlt_5","text":"《典略》曰：光祿劉松北镇，而袁紹夜酣酒，以盛夏三伏之际，晝夜與松飲酒，至於無知，雲以避一時之暑，故河北［明本作朔。］避暑飲。","sortOrder":17},
  {"id":"s_work_nvlt_5_18","chapterId":"ch_work_nvlt_5","text":"《世說》曰：郄嘉賓三伏之日詣謝公，炎暑熏赫，雖复當風交扇，猶沾汗流離，謝著故絹衣，食熱白粥，晏然無異。","sortOrder":18},
  {"id":"s_work_nvlt_5_19","chapterId":"ch_work_nvlt_5","text":"《風俗通》曰：戶律，漢中巴蜀廣漢，自擇伏日，俗說，漢中巴蜀廣漢，正［《太平御覽》三十八作土。］地溫暑，草木蚤生晚枯，氣異中國，夷狄畜之，故令自擇伏日也。","sortOrder":19},
  {"id":"s_work_nvlt_5_20","chapterId":"ch_work_nvlt_5","text":"【詩】晉程晓詩曰：平生三伏時，道路無行車，閉門避暑臥，出入不相過。今世愔襶子，觸熱到人家，主人聞客來，嚬噈奈此何，搖扇胛中疼，流汗正滂沱，傳誡語高明，熱行宜見诃。","sortOrder":20},
  {"id":"s_work_nvlt_5_21","chapterId":"ch_work_nvlt_5","text":"晉潘嶽懷縣詩，南陆迎脩景，朱明，送未垂，初伏啟新節，隆暑方赫羲，朝想慶雲興，夕遲白日移，揮汗辭中宇，登城臨清池，涼風自遠集，輕衿隨風吹，靈圃曜華果，通衢列高椅。","sortOrder":21},
  {"id":"s_work_nvlt_5_23","chapterId":"ch_work_nvlt_5","text":"《說文》：溽，濕暑也。","sortOrder":23},
  {"id":"s_work_nvlt_5_24","chapterId":"ch_work_nvlt_5","text":"《山海經》曰：寿麻之國，爰有大暑，不可以往。","sortOrder":24},
  {"id":"s_work_nvlt_5_25","chapterId":"ch_work_nvlt_5","text":"《禮記月令》曰：季夏之月，土润溽暑。","sortOrder":25},
  {"id":"s_work_nvlt_5_26","chapterId":"ch_work_nvlt_5","text":"《毛詩》曰：旱既太甚，蘊隆虫虫，赫赫炎炎，雲我無所。","sortOrder":26},
  {"id":"s_work_nvlt_5_27","chapterId":"ch_work_nvlt_5","text":"《管子》曰：善為國者，使農寒耕而熱耘。","sortOrder":27},
  {"id":"s_work_nvlt_5_28","chapterId":"ch_work_nvlt_5","text":"《楚辭》雲，魂兮歸來，東方不可以讬，十日代出，流金鑠石。","sortOrder":28},
  {"id":"s_work_nvlt_5_29","chapterId":"ch_work_nvlt_5","text":"《淮南子》曰：南方之極，自北戶之界，至炎風之野，赤帝祝融之所司。","sortOrder":29},
  {"id":"s_work_nvlt_5_30","chapterId":"ch_work_nvlt_5","text":"《神異經》曰：北方曾冰萬里，厚百丈，有蛇奚鼠在冰下土中，其形如鼠，食冰草木根，肉重萬斤，可以作脯，食之已熱，［事見肉部。］","sortOrder":30},
  {"id":"s_work_nvlt_5_31","chapterId":"ch_work_nvlt_5","text":"京房《易飛候》曰：有雲大如車蓋十餘，此陽水之氣，必暑，有暍者。","sortOrder":31},
  {"id":"s_work_nvlt_5_32","chapterId":"ch_work_nvlt_5","text":"《漢書·西域傳》曰：罽賓國，道歷大小頭痛之山，赤土身熱之坂，令人熱無色，頭痛欧吐。","sortOrder":32},
  {"id":"s_work_nvlt_5_33","chapterId":"ch_work_nvlt_5","text":"《桓子新論》曰：元帝被病，廣求方士，漢中逸人王仲都者，詔問所能為，對曰：但能忍寒暑耳，因為待詔，至夏大暑日，使暴坐。又環以十爐火，不言熱而身汗不出。","sortOrder":33},
  {"id":"s_work_nvlt_5_34","chapterId":"ch_work_nvlt_5","text":"《五經通義》曰：冬至陽動於下，推陰而上之，故寒於上，夏至陰動於下，推陽而之上，故大熱於上。","sortOrder":34},
  {"id":"s_work_nvlt_5_35","chapterId":"ch_work_nvlt_5","text":"《易》［《太平御覽》三十四易上有故字，與上連，作一條。］曰：日月運行，一寒一暑，日在牵牛則寒，在東井則暑，牵牛水［御覽作外。］宿，遠人，故寒，東井內宿，近人，故溫也。","sortOrder":35},
  {"id":"s_work_nvlt_5_36","chapterId":"ch_work_nvlt_5","text":"《括地圖》曰：天毒國最大暑熱，夏草木皆乾死，民善没水，以避日入時暑，常入寒泉之下。","sortOrder":36},
  {"id":"s_work_nvlt_5_37","chapterId":"ch_work_nvlt_5","text":"《抱朴子》：洪從祖仙公，每大醉及夏天盛熱，辄入深水底，入日乃出者，正以能閉氣胎息故耳。","sortOrder":37},
  {"id":"s_work_nvlt_5_38","chapterId":"ch_work_nvlt_5","text":"又曰：或問不熱之道，或服玄冰丸飛雪散，王仲都等用此方也。","sortOrder":38},
  {"id":"s_work_nvlt_5_39","chapterId":"ch_work_nvlt_5","text":"《語林》曰：劉真長見王公，王公了不與語，時大熱，以腹熨石局。","sortOrder":39},
  {"id":"s_work_nvlt_5_40","chapterId":"ch_work_nvlt_5","text":"【詩】晉傅玄詩曰：朱明運將極，溽暑晝夜興，裁動四支废，舉身若山陵，珠汗洽玉體，呼吸氣鬱蒸，尘垢自成泥，素粉隨手凝。","sortOrder":40},
  {"id":"s_work_nvlt_5_41","chapterId":"ch_work_nvlt_5","text":"梁簡文帝苦熱詩曰：六龍骛不息，三伏啟炎陽，寢興煩幾案，俯仰倦帏床，滂沱汗似鑠，微靡風如湯，洄池愧生浪，蘭殿非含霜，細帘時半卷，輕幌乍橫張，雲斜花影没，日落荷心香，原見洪崖井，詎怜河朔觴。","sortOrder":41},
  {"id":"s_work_nvlt_5_42","chapterId":"ch_work_nvlt_5","text":"梁任昉苦熱詩曰：旭旦煙雲卷，烈景入東軒，傾光望轉蕙，斜日照西垣，既卷蕉梧葉，复傾葵藿根，重簟無冷氣，挟石似懷溫，霡霂類珠缀，喘哧状雷奔。","sortOrder":42},
  {"id":"s_work_nvlt_5_43","chapterId":"ch_work_nvlt_5","text":"梁何遜苦熱詩曰：昔聞草木燋，今睹沙石烂，曀曀風逾靜，曈曈日漸旰，習靜悶衣襟，讀書煩幾案，臥思清露浥，坐待高星燦，蝙蝠戶中飛，蠛蠓窗間亂，實無河朔飲，空有臨淄汗。","sortOrder":43},
  {"id":"s_work_nvlt_5_44","chapterId":"ch_work_nvlt_5","text":"梁王筠苦暑詩曰：日坂散朱雰，天隅斂青霭，飛焰煥南陆，炎津通北瀨，繁星聚若珠，密雲屯似蓋，月至每开衿，風過時解帶。","sortOrder":44},
  {"id":"s_work_nvlt_5_45","chapterId":"ch_work_nvlt_5","text":"梁劉孝威苦暑詩曰：暮日苦炎溽，遷坐接階廊，月麗姮娥影，星含織女光，栖禽動夜竹，流螢出闇牆，香盤糅鮮粉，雕壶承玉漿，白羽徒棰握，渌水自周堂，弱紈猶覺重，纖絺尚少涼，弄風思漢朔，戲雨憶吳王，玄水術難验，赤道漏猶長，誰能更吹律，還令黍穀涼。","sortOrder":45},
  {"id":"s_work_nvlt_5_46","chapterId":"ch_work_nvlt_5","text":"梁簡文帝納涼詩曰：斜日晚骎骎，池塘生半陰，避暑高梧侧，輕風時入襟，落花還就影，驚蝉乍失林，遊魚吹水沫，神蔡上荷心，翠竹垂秋采，丹棗映疏砧，無勞夜遊曲，寄此讬微吟。","sortOrder":46},
  {"id":"s_work_nvlt_5_47","chapterId":"ch_work_nvlt_5","text":"又晚景納涼詩曰：日移涼氣散，懷抱信悠哉，珠帘影空卷，桂戶向池开，鳥栖星欲見，河净月應來，橫階入細筍，蔽地濕輕苔，草化飛為火，蚊聲合似雷，於茲靜聞見，自此歇氛埃。","sortOrder":47},
  {"id":"s_work_nvlt_5_48","chapterId":"ch_work_nvlt_5","text":"又玄圃納涼詩曰：登山想劍閣，逗浦憶辰陽，飛流如冻雨，夜月似秋霜，螢翻競晚熱，虫思引秋涼，鳴波如礙石，闇草別蘭香。","sortOrder":48},
  {"id":"s_work_nvlt_5_49","chapterId":"ch_work_nvlt_5","text":"梁孝元帝納涼詩曰：高舂斜日下，佳氣滿欄楹，池紅早花落，水渌晚苔生，星稀月稍上，雲开河尚橫，白鳥翻帷暗，丹螢入帳明，珠綦趨北閤，玳席徙南榮，金鋪掩夕扇，玉壶傳夜聲。","sortOrder":49},
  {"id":"s_work_nvlt_5_50","chapterId":"ch_work_nvlt_5","text":"梁劉孝威奉和逐涼詩曰：鍾鳴夜未央，避暑起徬徨，長河似曳素，明星若散璫，倚巖欣石冷，臨池愛水涼，月纖張敞畫，荷妖韓寿香，對此遊清夜，何勞娱洞房。","sortOrder":50},
  {"id":"s_work_nvlt_5_51","chapterId":"ch_work_nvlt_5","text":"又奉和晚日詩曰：虬簷掛珠箔，虹梁卷霧绡，迷迭涵香長，芙蓉逐浪搖，飛輪搏羽扇，翻車引落潮，甘泉推激水，迎風慚遠飆，寄言王待詔，因聲張子侨，吾君安已樂，無勞誦洞箫。","sortOrder":51},
  {"id":"s_work_nvlt_5_52","chapterId":"ch_work_nvlt_5","text":"梁劉缓奉和納涼詩曰：清氣流暄濁，非關狹室中，當由小堂上，自有大王風，蟭螟動蘭室，神飆起桂丛，披襟深睿賞，曲巷何由同。","sortOrder":52},
  {"id":"s_work_nvlt_5_53","chapterId":"ch_work_nvlt_5","text":"梁庾肩吾奉和山子納涼詩曰：北園涼風早，步輦暫逍遙，避日交長扇，迎風列短箫，山帶彈琴曲，桐橫栖鳳條，懸門开溜水，錦石镇浮桥，黑米生菰葑，青花出稻苗，無因學仙藻，雲氣徒飄飖。","sortOrder":53},
  {"id":"s_work_nvlt_5_54","chapterId":"ch_work_nvlt_5","text":"陳徐陵內園逐涼詩曰：昔有北山北，今餘東海東，納涼高树下，直坐落花中，狹径長無跡，茅斋本自空，提琴就竹筱，酌酒勸梧桐。","sortOrder":54},
  {"id":"s_work_nvlt_5_55","chapterId":"ch_work_nvlt_5","text":"【賦】魏繁钦暑賦曰：暑景方徂，時惟六月，大火飄光，炎氣酷烈，翕翕盛熱，蒸我層軒，溫風淟涊，動靜增煩，雖讬陰宮，罔所避旃，粉扇靡救，宴戲鮮歡，庶望秋節，慰我愁叹，魏陳王曹植大暑賦曰：炎帝掌節，祝融司方，羲和按辔，南崔［本集作雀。］舞衡，蛇折鱗於靈窟，龍解角於皓蒼，遂乃溫風赫戲，草木垂幹，山坼海沸，沙融砾烂，飛魚躍渚，潛黿浮岸，鳥張翼而近栖，獸交遊而雲散，於時黎庶徙倚，綦布葉分，機女絕綜，農夫釋耘，背暑者不群而齊跡，向陰者不會而成群，於是大人遷居宅幽，缓神育靈，雲屋重構，閒房肅清，寒泉涌流，玄木奋榮，積素冰於幽馆，氣飛結而為霜，奏白雪於琴瑟，朔風感而增涼。","sortOrder":55},
  {"id":"s_work_nvlt_5_56","chapterId":"ch_work_nvlt_5","text":"魏劉楨大暑賦曰：其為暑也，羲和總駕發扶木，太陽為舆達炎燭，靈威參垂步朱轂，赫赫炎炎，烈烈暉暉，若炽燎之附體。又溫泉而沉肌，獸喘氣於玄景，鳥戢翼於高危，農畯捉鐏而去畴，織女釋杼而下機，溫風至而增熱，歊悒慴而無依，披襟領而長嘯，冀微風之來思。","sortOrder":56},
  {"id":"s_work_nvlt_5_57","chapterId":"ch_work_nvlt_5","text":"魏王粲大暑賦曰：惟林鍾之季月，重陽積而上昇，喜润土之溽暑，扇溫風而至興，獸狼望以倚喘，鳥垂翼而弗翔，遠崑吾之中景，天地翕其同光，征夫瘼於原野，處者困於門堂，患衽席之焚灼，譬烘燎之在床，起屏營而東西，欲避之而無方，仰庭槐而嘯風，風既至而如湯，於是帝後順時，幸九峻之陰岡，讬甘泉之清野，御華殿於林光，潛廣室之邃宇，激寒流於下堂，重屋百層，垂陰千庑，九闼洞开，周帷高舉，堅冰常奠，寒饌代叙。","sortOrder":57},
  {"id":"s_work_nvlt_5_58","chapterId":"ch_work_nvlt_5","text":"晉夏侯湛大暑賦曰：若乃三伏相仍，徂暑肜肜，上無纖雲，下無微風，扶桑赩其增憤，天氣晔其南升，爾乃土墳地坼，穀枯川竭，寒泉潛沸，冰井騰沫，洪液蒸於单簟兮，珠汗霑乎絺葛，溫風翕其至兮，若洒湯於玉质，沃新水以達夕，振輕箑以終日。","sortOrder":58},
  {"id":"s_work_nvlt_5_59","chapterId":"ch_work_nvlt_5","text":"晉卞伯玉大暑賦曰：惟祝融之司運，赫溽暑之方隆，日貞躍於鶉首，律遷度於林鍾，溫風翕以辰至，星火烂以昏中，氣滔滔而方盛，晷永路而難終，流風兮莫繼，朱煙兮四纏，鬱邑兮中房，展轉兮長筵，體沸灼兮如燎，汗流烂兮珠連。","sortOrder":59},
  {"id":"s_work_nvlt_5_60","chapterId":"ch_work_nvlt_5","text":"晉傅鹹感涼賦曰：踐朱明之中月，暑鬱隆以肇興，赫融融以弥炽，乃沸海而焦陵，獸竄伏於幽林兮，鳥垂翼而弗升，汗珠陨於玉體兮，粉附身而沾凝，於是景雲晨敷，曜靈潛光，陰氣聿升，凯風載扬，忽輕箑於坐隅兮，思暖服於蘭房。","sortOrder":60},
  {"id":"s_work_nvlt_5_62","chapterId":"ch_work_nvlt_5","text":"《左傳》曰：楚莊王围萧，申公巫臣曰：師人多寒，王巡三軍，撫而勉之，三軍之士，皆如挟纊。","sortOrder":62},
  {"id":"s_work_nvlt_5_63","chapterId":"ch_work_nvlt_5","text":"《穆天子傳》曰：庚寅北風雪，天子寒，日中大寒，有冻人，天子作黃竹詩，［事具雪部。］","sortOrder":63},
  {"id":"s_work_nvlt_5_64","chapterId":"ch_work_nvlt_5","text":"《晏子》曰：景公起大台，歲寒，役之冻餒者乡有焉，公延晏子坐，飲酒樂，晏子歌曰：庶民之冻，我若之何，奉上靡弊，我若之何，歌終，喟然流涕，公止之曰：子殆為大台之役夫，寡人將罢。","sortOrder":64},
  {"id":"s_work_nvlt_5_65","chapterId":"ch_work_nvlt_5","text":"《尸子》曰：雨雪，楚莊王披裘當戶曰：我猶寒，彼百姓賓客甚矣，乃使巡國中，求百姓賓客之無居宿絕糧者赈之，國人大悅。","sortOrder":65},
  {"id":"s_work_nvlt_5_66","chapterId":"ch_work_nvlt_5","text":"《戰國策》曰：田单為齊相，過淄水，有老人，涉淄而寒，不能，坐沙中，乃解裘衣之，襄王曰：单之厚施，欲取我國乎，有貫珠者聞之，曰：不如因以為己善，乃下令曰：寡人忧民之寒，而单解裘衣人，稱寡人之意，於是闾里相與語曰：田单之愛人，乃王之教也。","sortOrder":66},
  {"id":"s_work_nvlt_5_67","chapterId":"ch_work_nvlt_5","text":"《呂氏春秋》曰：衛靈公天寒凿池，苑春曰：天寒，恐傷民，公曰：寒哉，春曰：君衣狐裘，坐熊席，四陬有火，是以不寒，民衣弊不補，履决不苴，君則不寒，民則寒矣，公曰善，命罢役。","sortOrder":67},
  {"id":"s_work_nvlt_5_68","chapterId":"ch_work_nvlt_5","text":"又曰：戎夷违齊如魯，天大寒，而後與門弟子宿於郭外，寒逾甚，謂弟子曰：子與我衣，我活，我與子衣，子活，我國士也，為天下惜死，子不肖人，［按本條見呂氏春秋長利篇，此有脱文。］惡能與國士衣哉，戎夷笑曰：道不濟夫，解衣與弟子，夜坐而死。","sortOrder":68},
  {"id":"s_work_nvlt_5_69","chapterId":"ch_work_nvlt_5","text":"《漢書》曰：上聞韓王信降匈奴，上自將击之，連戰乘勝逐北，至樓煩，會天寒，卒士墮指者十二三，鍾離意別傳曰：嚴遵昔與光武俱為諸生，暮夜宿息，二人寒，不得寢臥，更相謂曰：後日豪貴，憶此勿相忘，別後數年，光武有天下，徵遵不至。","sortOrder":69},
  {"id":"s_work_nvlt_5_70","chapterId":"ch_work_nvlt_5","text":"《東觀漢記》曰：王朗起兵，上自蓟東南馳，夜至芜蒌亭，時天寒烈，眾皆飢疲，冯異上豆粥，明旦，上謂諸將曰：昨日得公孫豆粥，飢寒俱解。","sortOrder":70},
  {"id":"s_work_nvlt_5_71","chapterId":"ch_work_nvlt_5","text":"葛仙公別傳曰：公與客談語，時天大寒，仙公謂客曰：居貧，不能人人得爐火，請作一大火，共致暖者，仙公因吐氣，火赫然從口中出，須臾大滿屋，客皆熱脱衣矣。","sortOrder":71},
  {"id":"s_work_nvlt_5_72","chapterId":"ch_work_nvlt_5","text":"【賦】梁裴子野寒夜賦曰：何四序之平分，處脩冬而多慮，眷搖落兮遒盡，悲荏苒其雲除，日晼晚而易潛，夜悠長而難曙，既而庭流皓月，階被凝霜，風吹衣而懍懍，氣空積而蒼蒼，袭重裘兮弗燠，炽朱火兮無光，門萧條兮晝阒，巷寂寞兮無人，疏三迳以負汲，結二耦而為賓，晉夏侯湛寒苦謠曰：惟玄冬之初夜，天惨懍以降寒，霜皚皚以被庭，冰溏瀩於井幹，草槭槭以疏葉，木萧萧以零殘，松陨葉於翠條，竹摧柯於绿竿。","sortOrder":72},
  {"id":"s_work_nvlt_5_73","chapterId":"ch_work_nvlt_5","text":"【表】陳王曹植表曰：臣聞寒者不貪尺玉而思短褐，飢者不原千金而美一餐，夫千金尺玉至貴，而不若一餐短褐者，物有所急也。","sortOrder":73},
  {"id":"s_work_nvlt_5_75","chapterId":"ch_work_nvlt_5","text":"《風俗通》曰：禮傳曰：夏曰嘉平，殷曰清祀，周曰大蠟，漢改曰臈，臈者腊也，因腊取獸，祭先祖也，漢火行，衰於戌，故此日腊也。","sortOrder":75},
  {"id":"s_work_nvlt_5_76","chapterId":"ch_work_nvlt_5","text":"《漢舊儀》曰：腊者報諸鬼神，古聖賢有功於民者也。","sortOrder":76},
  {"id":"s_work_nvlt_5_77","chapterId":"ch_work_nvlt_5","text":"蔡邕《獨斷》曰：腊者歲終大祭，縱吏民宴飲，非但迎氣，故但送不迎。","sortOrder":77},
  {"id":"s_work_nvlt_5_78","chapterId":"ch_work_nvlt_5","text":"《禮記》曰：天子大蠟八，伊耆氏始為蠟，蠟者索也，歲十二月，合聚萬物而索饗之。","sortOrder":78},
  {"id":"s_work_nvlt_5_79","chapterId":"ch_work_nvlt_5","text":"又曰：子貢觀於蠟，孔子曰：賜也樂乎，對曰：一國之人皆若狂，賜未知其樂也，子曰：百日之蠟，一日之泽，非爾所知也，［蠟之祭，勞農以休息之，言民勤稼啬，有百日之勞，今日飲酒燕樂，君之恩泽也，非爾所知，其義大也。］","sortOrder":79},
  {"id":"s_work_nvlt_5_80","chapterId":"ch_work_nvlt_5","text":"《周禮》曰：國祭蠟則歙豳頌，击土鼓，以息老物。","sortOrder":80},
  {"id":"s_work_nvlt_5_81","chapterId":"ch_work_nvlt_5","text":"《左傳》曰：晉侯假道於虞，以伐虢，宮之奇諫，弗聽，以其族行，曰：虞不腊也。","sortOrder":81},
  {"id":"s_work_nvlt_5_82","chapterId":"ch_work_nvlt_5","text":"《列女傳》曰：魯之母師者，魯九子之寡母也，腊日，休家作者，歲祀禮事畢，悉召諸子，謂曰：婦人之義，非有大故，不出夫家，然吾父母家多幼稚，歲時禮不理，吾從汝謁，往監之，諸子皆稽首唯诺。又召諸婦，曰：婦人有三從之義，無专製之行，少系於父母，長系於夫，老系於子，今諸子許我歸私家，雖逾婦禮，原與少子俱，以備婦人出入之製，諸婦其慎房戶之守，吾夕而反，於是使少子仆而歸。","sortOrder":82},
  {"id":"s_work_nvlt_5_83","chapterId":"ch_work_nvlt_5","text":"謝承《後漢書》曰：沛國陳鹹，為廷尉監，王莽篡位，還家，杜門不出，莽改易漢法令及腊日，鹹常言，我先祖何知王氏腊乎。","sortOrder":83},
  {"id":"s_work_nvlt_5_84","chapterId":"ch_work_nvlt_5","text":"《風俗通》曰：莬髕，俗說，腊正祖食，得莬髕者，名之曰幸。賞以寒酒，幸善祥，令人吉利也。","sortOrder":84},
  {"id":"s_work_nvlt_5_85","chapterId":"ch_work_nvlt_5","text":"鄭玄別傳曰：玄年十二，隨母還家，正腊宴會，同列十數人，皆美服盛飾，語言閒通，玄獨漠然如不及，父母私督數，乃曰：此非我志，不在所原。","sortOrder":85},
  {"id":"s_work_nvlt_5_86","chapterId":"ch_work_nvlt_5","text":"《陳留志》曰：范乔，邑人腊，多盜斫其树，人有告，乔佯弗聞，邑人愧而歸之，乔曰：乡腊日取此，欲與父母相歡娱耳。","sortOrder":86},
  {"id":"s_work_nvlt_5_87","chapterId":"ch_work_nvlt_5","text":"《會稽典錄》曰：陳脩，乌傷人，家貧為吏，常步簷上下，恒食乾糒，每至正腊，僵仆不起，同僚飲食，請不肯往，其志操如此。","sortOrder":87},
  {"id":"s_work_nvlt_5_88","chapterId":"ch_work_nvlt_5","text":"《世說》曰：王朗中年，以識度推華歆，歆蠟日嘗集子侄宴飲，王朗亦學之，有人向張茂先稱此事，茂先曰：王之學華，皆是形骸之外，去之所以更玄遠。","sortOrder":88},
  {"id":"s_work_nvlt_5_89","chapterId":"ch_work_nvlt_5","text":"晉博士張亮議曰：腊，接也，祭宜在新，故交接也，俗謂之腊之明日為初歲，秦漢以來有贺，此皆古之遺語也。","sortOrder":89},
  {"id":"s_work_nvlt_5_90","chapterId":"ch_work_nvlt_5","text":"《史記》曰：秦惠文公十二年，初腊，始皇三十一年，更名腊曰嘉平。","sortOrder":90},
  {"id":"s_work_nvlt_5_91","chapterId":"ch_work_nvlt_5","text":"《東觀漢記》曰：甄宇，北海人，建武中，青州從事徵拜博士，每腊，詔賜博士羊，人一頭，羊有大小肥瘦，時博士祭酒議，欲殺羊，稱分其肉，宇曰：不可。又欲投鉤，宇复恥之，宇因先自取其最瘦者。","sortOrder":91},
  {"id":"s_work_nvlt_5_92","chapterId":"ch_work_nvlt_5","text":"袁山松《後漢書》曰：韓卓，字子助，陳留人，腊日，奴竊食祭其先人，卓義其心，即曰免之。","sortOrder":92},
  {"id":"s_work_nvlt_5_93","chapterId":"ch_work_nvlt_5","text":"《華陽國志》曰：王長文，元康初，试守江源令，縣收得盜馬賊及發冢賊，長文引前誘慰，時遇腊晦，皆遣歸家，獄先有系囚，亦遣之，謂曰：教化不厚，使汝等如此，長文過也，蠟節慶祚，歸就汝上下，善相歡樂，過節來還，當為汝思他理，群吏惶懅爭請，不許，尋有赦令，無不感思，所宥人誓不為惡，曰：不敢負王君也。","sortOrder":93},
  {"id":"s_work_nvlt_5_94","chapterId":"ch_work_nvlt_5","text":"《搜神記》曰：宣帝時，陰子方者，當腊日晨炊，而竈君神形見，子方再拜受慶，家有黃羊，因以祀之，自是以後，暴至巨富，故後常以腊日祠竈，［事具竈部。］養生要曰：十二月腊夜，令人持椒臥井旁，無與人言，內椒井中，除溫病。","sortOrder":94},
  {"id":"s_work_nvlt_5_95","chapterId":"ch_work_nvlt_5","text":"【詩】晉裴秀大蠟詩曰：日躔星紀，大呂司晨，玄象改次，庶眾更新，歲事告成，八蠟報勤，告成伊何，年丰物阜，丰禋孝祀，介茲萬祜，報勤伊何，農功是歸，穆穆我後，務茲蒸黎，宣力菑畝，沾體暴肌，飲饗清祀，四方來綏，充仞郊甸，鱗集京師，交错貿遷，紛葩相追，反袂成帷，有肉如丘，有酒如泉，有肴如林，有货如山，率土同歡，和氣來臻，祥風协順，降祉自天，方隅清謐，嘉祚日延，與民優遊，享寿萬年。","sortOrder":95},
  {"id":"s_work_nvlt_5_96","chapterId":"ch_work_nvlt_5","text":"晉江伟答贺蠟詩曰：正元二年冬腊，家君在陳郡，餘別在國舍，不得集會，弟廣平作詩以貽餘，餘因答之曰：蠟節之會，廓焉獨處，晨風朝興，思我慈父，我心懷恋，運首延佇。","sortOrder":96},
  {"id":"s_work_nvlt_5_97","chapterId":"ch_work_nvlt_5","text":"宋張望蠟除詩曰：玄靈告稔謝，青龍駕拂軫，鮮冰迎流結，凝霤垂簷霣，人欣八蠟畅，詎知歲聿盡。","sortOrder":97},
  {"id":"s_work_nvlt_5_98","chapterId":"ch_work_nvlt_5","text":"【序】晉嵇含娱蠟賦序曰：玄象運而寒暑交，節會至而萬物遷，天地之化，固以不停，况於人道之不变乎，是以百年忧喜相參，能達要終之數，悟生生之宜者，百世不過［明本作周。］其人，大蠟之夕，雖天下同有，携金蘭以齊馨利，貴得意以遣榮势，孰我尚哉。","sortOrder":98},
  {"id":"s_work_nvlt_5_100","chapterId":"ch_work_nvlt_5","text":"《爾雅》曰：律謂之分。","sortOrder":100},
  {"id":"s_work_nvlt_5_101","chapterId":"ch_work_nvlt_5","text":"《尚書》曰：予欲聞六律五聲八音，在治忽，以出內五言，汝聽。","sortOrder":101},
  {"id":"s_work_nvlt_5_102","chapterId":"ch_work_nvlt_5","text":"又曰：聲依永，律和聲，八音克諧，無相奪倫，神人以和。","sortOrder":102},
  {"id":"s_work_nvlt_5_103","chapterId":"ch_work_nvlt_5","text":"《周官》曰：太師，掌六律六呂，文以五聲，播以八音，教六詩，以六德為之本，以六律為之音。","sortOrder":103},
  {"id":"s_work_nvlt_5_104","chapterId":"ch_work_nvlt_5","text":"《禮記》曰：正月律中太蔟，二月律中夹鍾，三月律中沽洗，四月律中仲呂，五月律中蕤賓，六月律中林鍾，七月律中夷則，八月律中南呂，九月律中無射，十月律中應鍾，十一月律中黃鍾，十二月律中大呂。","sortOrder":104},
  {"id":"s_work_nvlt_5_105","chapterId":"ch_work_nvlt_5","text":"《周禮註》曰：律呂相生者，三分益一，下生者三分减一，黃鍾律長九寸，下生林鍾，六月律也。","sortOrder":105},
  {"id":"s_work_nvlt_5_106","chapterId":"ch_work_nvlt_5","text":"《左氏傳》曰：六律七音，八風九歌，以相成也，清濁小大，短長疾徐，哀樂遲速，高下出入，周流以相濟也，君子聽之，以平其心。","sortOrder":106},
  {"id":"s_work_nvlt_5_107","chapterId":"ch_work_nvlt_5","text":"《孟子》曰：師曠之聰，不以六律，不能正五音。","sortOrder":107},
  {"id":"s_work_nvlt_5_108","chapterId":"ch_work_nvlt_5","text":"《呂氏春秋》曰：昔黃帝命伶倫作為律，伶倫自大夏之西，乃之阮隃之陰，取竹之谿穀以生空竅厚均者，斷兩節間長三寸九分而吹之，以為十二筒，聽鳳鳴以別十二律，其雄鳴為六，雌鳴亦六，故曰黃鍾之宮，律之本也。","sortOrder":108},
  {"id":"s_work_nvlt_5_109","chapterId":"ch_work_nvlt_5","text":"《淮南子》曰：夔合六律，調五音，通八風。","sortOrder":109},
  {"id":"s_work_nvlt_5_110","chapterId":"ch_work_nvlt_5","text":"《漢書》曰：至治之世，天地之氣，合以生風，天地之風氣，定十二律。","sortOrder":110},
  {"id":"s_work_nvlt_5_111","chapterId":"ch_work_nvlt_5","text":"又曰：漢家言律歷者，本張蒼，蒼好書，無所不觀，無所不通，而尤究律歷。","sortOrder":111},
  {"id":"s_work_nvlt_5_112","chapterId":"ch_work_nvlt_5","text":"又曰：京房本姓李，推律，自定為京氏。","sortOrder":112},
  {"id":"s_work_nvlt_5_113","chapterId":"ch_work_nvlt_5","text":"劉向別錄曰：邹子在燕，燕有穀，地美而寒，不生五穀，邹子居之，吹律而溫氣至，今名黍穀，［事具地部穀篇。］","sortOrder":113},
  {"id":"s_work_nvlt_5_114","chapterId":"ch_work_nvlt_5","text":"《論衡》曰：孔子吹律，自知殷苗裔。","sortOrder":114},
  {"id":"s_work_nvlt_5_115","chapterId":"ch_work_nvlt_5","text":"楊泉《物理論》曰：聽清濁五聲之和，然後製為鍾律，取弘農宜陽縣金門山竹為管。","sortOrder":115},
  {"id":"s_work_nvlt_5_116","chapterId":"ch_work_nvlt_5","text":"晉諸公贊曰：世祖時，以荀勖所造律，得周時玉律，以校正同，荀勖奏曰：中所出御府銅管律二十五具，其三具與杜夔左延年法同。","sortOrder":116},
  {"id":"s_work_nvlt_5_117","chapterId":"ch_work_nvlt_5","text":"【表】周王襃上新定鍾表曰：萬物生象，始乎筭數，天道運行，基乎步術，量有輕重，平以權衡，音有清濁，协乎律呂，是以周發聽聲，候春冬之生殺，師曠吹律，知晉楚之衰亡，數始黃鍾，琯終仲呂，還宮变徵，參天兩地，三分損益，累黍相乘，四時發斂，忽微斯测，皇帝治歷明時，推元受命，八音七始之奏，五聲六律之和，斟酌繁簡，分析節度，推之以升斛，正之以權衡，稽之以古今，覈之以經傳。","sortOrder":117},
  {"id":"s_work_nvlt_5_118","chapterId":"ch_work_nvlt_5","text":"周庾信為晉陽公上玉律表曰：臣聞三才既立，君臣之道已陳，六位時成，禮樂之功斯正，故以葉和日月，测度陰陽，悅豫兆民，儀形萬國者也，伏見敕旨，刊正音律，平章歷象，奏黃鍾而歌大呂，变孤竹而舞雲門，莫不器取疏通，聲從安樂，四分既明，三微是定，是以聞鍾於洛浦，即辨聲乖，聽铎於邯鄲，先知响韻，二分二至，行於司歷之官，九变九成，被於和樂之職，足以動天地，感鬼神，化被風俗，平分寒暑，豈直吟嘯谿穀，回翔鸞鳳而已哉，是知零陵廟前徒尋舜管，始平城下空論周天，臣聞上製其禮，下習其儀，君定其法，臣行其事，謹造玉律一具，併玉秤尺斗合等，始得成功，至於分粟累黍，量茲數籥，實以仰禀聖規，參詳神思，所冀節移陰管，無勞河內之灰，氣動陽鍾，不待金門之竹，而琬琰事輕，般倕慮淺，不足展采成均，增辉度量。","sortOrder":118},
  {"id":"s_work_nvlt_5_120","chapterId":"ch_work_nvlt_5","text":"《世本》曰：容成作歷。","sortOrder":120},
  {"id":"s_work_nvlt_5_121","chapterId":"ch_work_nvlt_5","text":"《尚書》曰：乃命羲和，钦若昊天，歷象日月星辰，敬授民時。","sortOrder":121},
  {"id":"s_work_nvlt_5_122","chapterId":"ch_work_nvlt_5","text":"又曰：葉用五紀，其五曰歷數。","sortOrder":122},
  {"id":"s_work_nvlt_5_123","chapterId":"ch_work_nvlt_5","text":"《尸子》曰：造歷數者，羲和子也。","sortOrder":123},
  {"id":"s_work_nvlt_5_124","chapterId":"ch_work_nvlt_5","text":"《漢書》曰：歷數之起尚矣，傳述颛頊命南正重司天，火正黎司地，其後三苗亂德，二官鹹废，而閏餘乖次，孟陬殄滅，攝提失方。","sortOrder":124},
  {"id":"s_work_nvlt_5_125","chapterId":"ch_work_nvlt_5","text":"又曰：使校歷淳於陵渠，复覆太初歷，晦朔絃望最密，日月如合璧，五星若連珠。","sortOrder":125},
  {"id":"s_work_nvlt_5_126","chapterId":"ch_work_nvlt_5","text":"又曰：歷譜者，序四時之位，正分至之節，會日月五星之辰，以考寒暑殺生之實，故聖王必正歷，以探知五星日月之會，凶阨之患，其術皆出焉，此聖人知命之術也。","sortOrder":126},
  {"id":"s_work_nvlt_5_127","chapterId":"ch_work_nvlt_5","text":"《續漢書》曰：昔者聖人之作歷也，觀璿璣之運，三光之作，道之發斂，景之長短，斗綱所建，青龍所躔，參伍以变，错綜其數，而製術焉。","sortOrder":127},
  {"id":"s_work_nvlt_5_128","chapterId":"ch_work_nvlt_5","text":"《益部耆舊傳》曰：巴郡落下閎，漢武帝時，改颛頊歷，更作太初歷，曰：後八百歲，此歷差一日，當有聖人定之。","sortOrder":128},
  {"id":"s_work_nvlt_5_129","chapterId":"ch_work_nvlt_5","text":"楊泉《物理論》曰：畴昔神農始治農功，正節氣，審寒溫，以為早晚之期，故立歷日。","sortOrder":129},
  {"id":"s_work_nvlt_5_130","chapterId":"ch_work_nvlt_5","text":"《風土記》曰：自黃帝颛頊，下達三王，治歷十有一家，考課損益，各有变衰，非天運之错，考察意異故也。","sortOrder":130},
  {"id":"s_work_nvlt_5_131","chapterId":"ch_work_nvlt_5","text":"王隱《晉書》曰：張載弟前乌程令名冗，［《太平御覽》十六作亢。又亢下有依字。］蔡邕註明堂令中台要解。又缀諸說歷數而為歷贊，荀崧見贊，異之，雲信該羅歷表義矣。","sortOrder":131},
  {"id":"s_work_nvlt_5_132","chapterId":"ch_work_nvlt_5","text":"【表】梁簡文帝謝賜新歷表曰：五司告肇，萬寿載光，琯葉璧輪，慶休寶歷，班和布政，懸闕徇道，或弘敬授之典，載闡浃辰之教。又謝賜新歷表曰：璿籥環璣，鳳司肇律，觀斗辯氣，玉琯移春，萬福惟新，剋固天保。","sortOrder":132},
  {"id":"s_work_nvlt_5_133","chapterId":"ch_work_nvlt_5","text":"梁沈約謝賜新歷表曰：竊惟觀斗辯日，馭生為本，審時分地，稼政莫先，何則，勝殺無舛，拘忌之理難忽，珠璧有徵，禮節之原攸序。","sortOrder":133},
  {"id":"s_work_nvlt_5_134","chapterId":"ch_work_nvlt_5","text":"梁王僧孺謝賜歷表曰：竊以龍馭不爽，靡見侵薄，鳳職是司，曾無昃眺，璧聯珠粲，輪映階平，義實明時，事惟均政，固以先天候其餘始，執杓验其平分，九瀛仰化，萬宇依朔。","sortOrder":134},
  {"id":"s_work_nvlt_5_135","chapterId":"ch_work_nvlt_5","text":"【啟】梁庾肩吾謝歷日啟曰：凌渠所奏，絃望既符，邓平之言，锱銖皆合，登台视朔，睹雲物之必書，拂管移灰，識權衡之有度，初开卷始，暫謂春留，未覽篇終，便傷冬及，徘徊厚渥，比日為年。","sortOrder":135},
  {"id":"s_work_nvlt_5_136","chapterId":"ch_work_nvlt_5","text":"《藝文類聚》　唐·欧陽詢","sortOrder":136},
  {"id":"s_work_nvlt_6_1","chapterId":"ch_work_nvlt_6","text":"卷六地部、州部、郡部","sortOrder":1},
  {"id":"s_work_nvlt_6_2","chapterId":"ch_work_nvlt_6","text":"○地野關岡巖峡石尘","sortOrder":2},
  {"id":"s_work_nvlt_6_3","chapterId":"ch_work_nvlt_6","text":"○冀州楊州荆州青州徐州兖州豫州雍州益州幽州併州交州","sortOrder":3},
  {"id":"s_work_nvlt_6_4","chapterId":"ch_work_nvlt_6","text":"○河南郡京兆郡宣城郡會稽郡","sortOrder":4},
  {"id":"s_work_nvlt_6_6","chapterId":"ch_work_nvlt_6","text":"《神農書》曰：湛濁為地。","sortOrder":6},
  {"id":"s_work_nvlt_6_7","chapterId":"ch_work_nvlt_6","text":"《黃帝素問》曰：積陰為地，故地者濁陰也。","sortOrder":7},
  {"id":"s_work_nvlt_6_8","chapterId":"ch_work_nvlt_6","text":"蔡邕《月令章句》曰：總丘陵原隰阪险曰地。","sortOrder":8},
  {"id":"s_work_nvlt_6_9","chapterId":"ch_work_nvlt_6","text":"《春秋元命苞》曰：地者易也，言養物懷任，交易变化，含吐應節，故其立字，土力於乙者為地。","sortOrder":9},
  {"id":"s_work_nvlt_6_10","chapterId":"ch_work_nvlt_6","text":"《河圖括地象》曰：地廣東西二萬八千，南北二萬六千，有君長之州，州有九，阻中土之文德，及而不治。","sortOrder":10},
  {"id":"s_work_nvlt_6_11","chapterId":"ch_work_nvlt_6","text":"《山海經》曰：帝令竖亥，步自東極，至於西極，五亿十萬九千八百八步，竖亥左手把筭，右手指青丘北。","sortOrder":11},
  {"id":"s_work_nvlt_6_12","chapterId":"ch_work_nvlt_6","text":"《孝經援神契》曰：計九州之別壤，山陵之大，川泽所註，萊沮所生，鳥獸所聚，九百一十一萬八千二十四頃，蛇尧埆不墾者千五百萬二千頃。","sortOrder":12},
  {"id":"s_work_nvlt_6_13","chapterId":"ch_work_nvlt_6","text":"《易》曰：立地之道，曰柔與刚。","sortOrder":13},
  {"id":"s_work_nvlt_6_14","chapterId":"ch_work_nvlt_6","text":"又曰：在地成形。","sortOrder":14},
  {"id":"s_work_nvlt_6_15","chapterId":"ch_work_nvlt_6","text":"又曰：坤，地也。","sortOrder":15},
  {"id":"s_work_nvlt_6_16","chapterId":"ch_work_nvlt_6","text":"《禮記》曰：孟冬之月，地始冻，仲春之月，地始坼。","sortOrder":16},
  {"id":"s_work_nvlt_6_17","chapterId":"ch_work_nvlt_6","text":"又曰：今夫地，一撮土之少，及其廣厚，載華嶽而不重，振河海而不泄，而萬物載焉。","sortOrder":17},
  {"id":"s_work_nvlt_6_18","chapterId":"ch_work_nvlt_6","text":"《周官》曰：大司徒，掌天下土地之圖，知九州之地域，廣輪之數，辯五地之物。","sortOrder":18},
  {"id":"s_work_nvlt_6_19","chapterId":"ch_work_nvlt_6","text":"《樂聲儀》曰：下元者，地氣也，為始萬物，生育長養，蓋藏之主也。","sortOrder":19},
  {"id":"s_work_nvlt_6_20","chapterId":"ch_work_nvlt_6","text":"《春秋元命苞》曰：地所以右轉者，氣濁精少，含陰而起遲，故轉右迎天，佐其道。","sortOrder":20},
  {"id":"s_work_nvlt_6_21","chapterId":"ch_work_nvlt_6","text":"《爾雅》曰：東至泰遠，西至邠國，南至濮鉛，北至祝栗，謂之四極，孤竹北戶西王母日下，謂之四荒，九夷八狄，七戎六蠻，謂之四海。","sortOrder":21},
  {"id":"s_work_nvlt_6_22","chapterId":"ch_work_nvlt_6","text":"《老子》曰：地得一以寧，地無以寧將恐發。","sortOrder":22},
  {"id":"s_work_nvlt_6_23","chapterId":"ch_work_nvlt_6","text":"《墨子》曰：禽子問天與地孰仁，《墨子》曰：翟以地為仁，太山之上，則封禪焉，培塿之侧，則生松柏，下生黍苗莞蒲，水生黿鼍龟魚，民衣焉食焉，家焉死焉，地終不责德焉，故翟以地為仁。","sortOrder":23},
  {"id":"s_work_nvlt_6_24","chapterId":"ch_work_nvlt_6","text":"《孔子家語》曰：子夏曰：商聞山書曰：地東西為緯，南北為經，山為積德，川為積形，高者為生，下者為死，丘陵為牝，谿穀為牡。","sortOrder":24},
  {"id":"s_work_nvlt_6_25","chapterId":"ch_work_nvlt_6","text":"【啟】梁昭明太子謝敕赉地圖啟曰：漢氏舆地，形茲未擬，晉世方丈，比此非妙，疋之長樂，唯畫古賢，儔之未央，止圖將帥，未有洞該八藪，混觀六合，域中天外，指掌可求，地角河源，戶庭不出，豈問千秋，自識乌桓之地，脱逢莊武，方著博物之書。","sortOrder":25},
  {"id":"s_work_nvlt_6_26","chapterId":"ch_work_nvlt_6","text":"【論】晉裴秀禹貢九州地域圖論曰：圖書之設，由來尚矣，自古垂象立製而賴其用，三代置其官，使掌其職，暨漢祖屠鹹陽，丞相萧何盡收秦之圖籍，今秘書既無古今之地圖。又無萧何所得秦圖書，唯有漢氏所畫舆地及諸雜圖，各不設分率。又不考正准望，亦不備載名山大川，其所載列，雖有粗形，皆不精審，不可依據，或稱外荒迂誕之言，不合事實，於義無取，今製地圖之體有六，一曰分率，所以辯廣輪之度也，二曰准望，所以正彼此之體也，三曰道里，所以定所由之數也，四曰高下，五曰方邪，六曰迂直，此六者各因地而製形，所以校夷险之故也，有圖象而無分率，則無以審遠近之差，有分率而無准望，雖得之於一隅，必失之於他方，雖有准望，而無道里，則施於山海絕隔之地，不能以相通，有道里而無高下方邪迂直之校，則径路之數，必與遠近之實相违，失准望之正，故必以此六者參而考之，然後遠近之實，定於分率，彼此之實，定於准望，径路之實，定於道里，度數之實，定於高下方邪迂直之筭，故雖有峻山巨海之隔，絕域殊方之迥，登降诡曲之因，皆可得舉而定者，准望之法既正，則曲直遠近，無所隱其形也。","sortOrder":26},
  {"id":"s_work_nvlt_6_28","chapterId":"ch_work_nvlt_6","text":"《爾雅》曰：邑外謂之郊，郊外謂之牧，牧外謂之野。","sortOrder":28},
  {"id":"s_work_nvlt_6_29","chapterId":"ch_work_nvlt_6","text":"《說文》曰：野，郊外也。","sortOrder":29},
  {"id":"s_work_nvlt_6_30","chapterId":"ch_work_nvlt_6","text":"《山海經》曰：大樂之野，夏後啟於此舞九代馬，［事具獸部馬篇。］","sortOrder":30},
  {"id":"s_work_nvlt_6_31","chapterId":"ch_work_nvlt_6","text":"又曰：都廣之野，後稷葬焉，爰有黍稷，百穀自生，鸞自歌，鳳自舞，靈寿寶華，草木所聚。","sortOrder":31},
  {"id":"s_work_nvlt_6_32","chapterId":"ch_work_nvlt_6","text":"《尚書》曰：大野既猪，東原底平。","sortOrder":32},
  {"id":"s_work_nvlt_6_33","chapterId":"ch_work_nvlt_6","text":"《毛詩》曰：我行其野，蔽芾其樗，婚姻之故，言就爾居。","sortOrder":33},
  {"id":"s_work_nvlt_6_34","chapterId":"ch_work_nvlt_6","text":"《左傳》曰：辛有適伊川，見被發祭於野者，曰：不及百年，此其戎乎，其禮先亡矣。","sortOrder":34},
  {"id":"s_work_nvlt_6_35","chapterId":"ch_work_nvlt_6","text":"又曰：晉文公過衛，出於五鹿，乞食於野人，野人與之塊，公子欲鞭之，子犯曰：天賜也，稽首受而載之。","sortOrder":35},
  {"id":"s_work_nvlt_6_36","chapterId":"ch_work_nvlt_6","text":"又曰：裨諶能謀於野，於野則獲，謀於國則否，鄭國有難，子產載以如野，謀四國之事。","sortOrder":36},
  {"id":"s_work_nvlt_6_37","chapterId":"ch_work_nvlt_6","text":"《穆天子傳》曰：曠原之野，飛鳥之所解羽。","sortOrder":37},
  {"id":"s_work_nvlt_6_38","chapterId":"ch_work_nvlt_6","text":"《莊子》曰：黃帝將見大隗於具茨之山，方明為御，昌宇參乘，至於襄城之野，七聖皆迷，無所問涂，適遇牧馬童子，乃問涂焉，［事具帝王部。］","sortOrder":38},
  {"id":"s_work_nvlt_6_39","chapterId":"ch_work_nvlt_6","text":"又曰：北門成問黃帝曰：帝張鹹池之樂於洞庭之野，吾始聞之而懼，後聞之而怠，卒聞之而惑，荡荡默默，乃不自得。","sortOrder":39},
  {"id":"s_work_nvlt_6_40","chapterId":"ch_work_nvlt_6","text":"《楚辭》曰：獨不見鸞鳳之高翔於大皇之野，循四極而回周，見盛德而下。","sortOrder":40},
  {"id":"s_work_nvlt_6_41","chapterId":"ch_work_nvlt_6","text":"《韓詩外傳》曰：孔子出遊少原之野，有婦人哭甚哀，問之，婦人曰：向刈蓍薪，亡吾簪，是以哀也，非傷亡簪，不忘故也，［事具草部。］","sortOrder":41},
  {"id":"s_work_nvlt_6_42","chapterId":"ch_work_nvlt_6","text":"《帝王世紀》曰：炎帝［史記五帝本紀索隱引作黃帝。］戮蚩尤於中冀，［索隱作冀。］","sortOrder":42},
  {"id":"s_work_nvlt_6_43","chapterId":"ch_work_nvlt_6","text":"名其地曰絕辔之野。","sortOrder":43},
  {"id":"s_work_nvlt_6_44","chapterId":"ch_work_nvlt_6","text":"《幽明錄》曰：桓溫北征姚襄，在伊水上，許遜曰：不見得襄，而有大功，見襄走入太玄中，問曰：太玄是何等也，答曰：南為丹野，北為太玄，必西北走也，果如言。","sortOrder":44},
  {"id":"s_work_nvlt_6_45","chapterId":"ch_work_nvlt_6","text":"【贊】晉郭璞都廣之野贊曰：都廣之野，珍怪所聚，爰有羔穀，鸞歌鳳舞，後稷讬終，樂哉斯土。","sortOrder":45},
  {"id":"s_work_nvlt_6_47","chapterId":"ch_work_nvlt_6","text":"《周官》曰：司關掌國货之節，以聯門市，凡货不出於關，舉其货，罰其人，國凶札則無關門之征。","sortOrder":47},
  {"id":"s_work_nvlt_6_48","chapterId":"ch_work_nvlt_6","text":"《禮記》曰：仲夏之月，關市無索。","sortOrder":48},
  {"id":"s_work_nvlt_6_49","chapterId":"ch_work_nvlt_6","text":"又曰：古者關譏而不征。","sortOrder":49},
  {"id":"s_work_nvlt_6_50","chapterId":"ch_work_nvlt_6","text":"蔡邕《月令章句》曰：關在境，所以察出御入。","sortOrder":50},
  {"id":"s_work_nvlt_6_51","chapterId":"ch_work_nvlt_6","text":"《左傳》曰：臧文仲不仁者三，废六關。","sortOrder":51},
  {"id":"s_work_nvlt_6_52","chapterId":"ch_work_nvlt_6","text":"《孟子》曰：古之為關也，將以御暴也，今之為關也，將以為暴也。","sortOrder":52},
  {"id":"s_work_nvlt_6_53","chapterId":"ch_work_nvlt_6","text":"《燕丹子》曰：燕丹去秦，夜到關，關門未开，丹為雞鳴，眾雞皆鳴，遂得逃歸。","sortOrder":53},
  {"id":"s_work_nvlt_6_54","chapterId":"ch_work_nvlt_6","text":"《史記》曰：秦昭王囚孟嘗君，孟嘗君变姓名，夜半至函穀關，關法，雞鳴出客，孟嘗君恐追至，客居下坐者，能為雞鳴，於是眾雞皆鳴，遂出關。","sortOrder":54},
  {"id":"s_work_nvlt_6_55","chapterId":"ch_work_nvlt_6","text":"《戰國策》曰：中山與燕趙為王，齊閉關不通中山之使，其言曰：我萬乘之國也，中山千乘國也，何侔名於我乎。","sortOrder":55},
  {"id":"s_work_nvlt_6_56","chapterId":"ch_work_nvlt_6","text":"《楚漢春秋》曰：沛公西入武關，居於灞上，遣將軍閉函穀關，無內項王，項王大將亚父至關，不得入，怒曰：沛公欲反耶，即令家發薪一束，欲燒關門，關門乃开。","sortOrder":56},
  {"id":"s_work_nvlt_6_57","chapterId":"ch_work_nvlt_6","text":"《列仙傳》曰：關令尹喜，周大夫也，善內學，老子西遊，先見其氣，知真人當過，物色而遮之，果得老子，與俱之流沙，［事具仙部。］","sortOrder":57},
  {"id":"s_work_nvlt_6_58","chapterId":"ch_work_nvlt_6","text":"《漢書》曰：秦王子婴，誅滅趙高，遣將將兵距峣關，沛公欲击之，張良曰：秦尚強，未可輕，原先遣人益張旗幟於山上，為疑兵，使郦食其陆贾往說秦將，啗以利，秦將果欲連和，因而攻之。","sortOrder":58},
  {"id":"s_work_nvlt_6_59","chapterId":"ch_work_nvlt_6","text":"又曰：景帝四年春，复置諸關，用傳出入。","sortOrder":59},
  {"id":"s_work_nvlt_6_60","chapterId":"ch_work_nvlt_6","text":"又曰：武帝三年冬，徙函穀於新安。","sortOrder":60},
  {"id":"s_work_nvlt_6_61","chapterId":"ch_work_nvlt_6","text":"又曰：終軍初從濟南嘗詣博士，入關，關吏與軍繻，軍問以此何為，吏曰。為复傳還，當以合符，軍曰：大丈夫西遊，終不复傳還，弃繻去，後軍為謁者，使行郡國，建節東出關，關吏識之，曰：此使者乃前弃繻生也。","sortOrder":61},
  {"id":"s_work_nvlt_6_62","chapterId":"ch_work_nvlt_6","text":"《東觀漢記》曰：隗嚣將王元謂嚣曰：請以一丸泥，為大王東封函穀關，此萬世一時也。","sortOrder":62},
  {"id":"s_work_nvlt_6_63","chapterId":"ch_work_nvlt_6","text":"又曰：郭丹初之長安，從宛人陳洮買入關符，以入函穀關，既入，封符乞人。曰：不乘使者車不出關，丹自從入關後，不歸家十二年，後奉使乃出關，竟如本心。","sortOrder":63},
  {"id":"s_work_nvlt_6_64","chapterId":"ch_work_nvlt_6","text":"又曰：李恂餉遺無所受，處新安關下，拾橡實為食。","sortOrder":64},
  {"id":"s_work_nvlt_6_65","chapterId":"ch_work_nvlt_6","text":"《吳越春秋》曰：伍子胥與太子建子勝俱奔吳，夜行晝伏，出到昭關，關吏欲執之，胥因诈曰：上之所以索我者，以我有美珠也，今我已亡之矣，我將告子欲取之，關吏因舍焉。","sortOrder":65},
  {"id":"s_work_nvlt_6_66","chapterId":"ch_work_nvlt_6","text":"吳書，陆凯奏曰：臣愚以西陵國之關首，宜重其備，備重則敵不敢輕，輕備則為敵所侮。","sortOrder":66},
  {"id":"s_work_nvlt_6_67","chapterId":"ch_work_nvlt_6","text":"何禎集曰：以正始六年，為弘農太守，表省崤關曰：易稱王公設险以守其國，孟軻雲，古者關譏而不征，關险之設，所由尚矣。","sortOrder":67},
  {"id":"s_work_nvlt_6_68","chapterId":"ch_work_nvlt_6","text":"段國沙州記曰：龍涸北四十里，有白馬關，關甚崄峻，使十人固险，雖萬夫亦不能前。","sortOrder":68},
  {"id":"s_work_nvlt_6_69","chapterId":"ch_work_nvlt_6","text":"【詩】陳周弘正入武關詩曰：武關設地险，遊客好邅回，將軍天上落，童子弃繻來，揮汗成雲雨，車馬漾尘埃，雞鳴不可信，未晓莫先开。","sortOrder":69},
  {"id":"s_work_nvlt_6_70","chapterId":"ch_work_nvlt_6","text":"【賦】後漢李尤函穀關賦曰：爾乃周覽以汎觀，歷眾關以遊目，惟迂闊之顯麗，羌莫盛乎函穀，施雕砻以作好，建峻敞之堅重，殊中外以隔別，翼巍巍之高崇，命尉臣以執鑰，統群類之所從，嚴固守之猛厲，操戈鉞而普聰，蕃镇造而惕息，侯伯過而震惶，惟函穀之初設险，前有姬之苗流，睢背魏而西逝，讬衾衣以免搜，大漢承獘以建德，革厥舊而運脩，准令宜以就製，因茲势，以立基，蓋可以诈非司邪，栝執喉咽，季末荒戍，墮闕有年，天闵群黎，命我聖君，稽符皇乾，孔適河文，中興再受，二祖同勋，永平承緒，钦明奉循，上羅三關，下列九門。","sortOrder":70},
  {"id":"s_work_nvlt_6_71","chapterId":"ch_work_nvlt_6","text":"【銘】後漢李尤函穀關銘曰：函穀险要，襟帶喉咽，尹從李老，留作二篇。孟嘗離秦，奔骛東征，夜造稽疑，譎以雞鳴，范睢將入，自盛以囊，元鼎革移。错之新安，舍彼西阻，東即高原，長墉重閣，閒固不逾，簡易易從，與乾合符。","sortOrder":71},
  {"id":"s_work_nvlt_6_73","chapterId":"ch_work_nvlt_6","text":"《爾雅》曰：山脊曰岡。","sortOrder":73},
  {"id":"s_work_nvlt_6_74","chapterId":"ch_work_nvlt_6","text":"《毛詩》曰：陟彼高岡，我馬玄黃。","sortOrder":74},
  {"id":"s_work_nvlt_6_75","chapterId":"ch_work_nvlt_6","text":"《地理志》曰：秦望氣者雲，東南有天子氣，使赭衣徒凿雲陽縣北岡，改名曲阿。","sortOrder":75},
  {"id":"s_work_nvlt_6_76","chapterId":"ch_work_nvlt_6","text":"又曰：天門零陽縣有半石岗，岗上有石，名仙人樓。","sortOrder":76},
  {"id":"s_work_nvlt_6_77","chapterId":"ch_work_nvlt_6","text":"山謙之《丹陽記》曰：句容縣東三十里，有龍岗，岗顶有龍沸潭，周十三丈，聞人聲，水便沸動，常日則不動。","sortOrder":77},
  {"id":"s_work_nvlt_6_78","chapterId":"ch_work_nvlt_6","text":"劉楨京口記曰：城北四十餘里，有小岗，高二丈許，有人鼻形，著岗西頭，有口在上，而鼻在下，方圓數尺，状如燋土，古老相傳，因名下鼻，今無复鼻，厥口猶在。","sortOrder":78},
  {"id":"s_work_nvlt_6_79","chapterId":"ch_work_nvlt_6","text":"王韶之始興記曰：郡西南有芙蓉岗，高若玉山，鄰枕郊郭，可四十餘里。","sortOrder":79},
  {"id":"s_work_nvlt_6_80","chapterId":"ch_work_nvlt_6","text":"又曰：含洭縣白鹿城南，有白鹿岗，晉鹹和中，縣令張鲂，有德惠，白鹿群遊岗上，因以為名。","sortOrder":80},
  {"id":"s_work_nvlt_6_81","chapterId":"ch_work_nvlt_6","text":"雷次宗豫章記曰：洪井西有鸞岗，舊說，洪崖先生乘鸞所憩之處也。","sortOrder":81},
  {"id":"s_work_nvlt_6_82","chapterId":"ch_work_nvlt_6","text":"顧徵《廣州記》曰：四會縣有金岗，行人往往見金於岗侧。","sortOrder":82},
  {"id":"s_work_nvlt_6_83","chapterId":"ch_work_nvlt_6","text":"裴氏《廣州記》曰：城北有馬鞍岗，秦時，瞻氣者言南方有天子氣，始皇發民凿破北岗，地中出血，凿處猶在，增城縣有雲母岡，日出，照之晃曜。","sortOrder":83},
  {"id":"s_work_nvlt_6_84","chapterId":"ch_work_nvlt_6","text":"武昌記曰：城北有岡，高數丈，名為鳳闕，其處顯敞勝闕，以望川泽，多所遠瞻，吳黃龍元年，有鳳皇集此岡，故謂之鳳闕，鳳闕南十里，有金牛岡，古老相傳雲，有金牛出此岡，岡今半崩，坑深數丈，牛踐堈邊，遺跡尚存。","sortOrder":84},
  {"id":"s_work_nvlt_6_85","chapterId":"ch_work_nvlt_6","text":"王孚安城［《太平御覽》十作成。］記曰：萍乡西津里南五里山，名玉女岡，天氣當雨，水辄先涌出，石开而有五色玄黃，百姓謂之玉女披衣。","sortOrder":85},
  {"id":"s_work_nvlt_6_86","chapterId":"ch_work_nvlt_6","text":"邓德明《南康記》曰：陳蕃墓有青龍岡，土人傳雲，昔見一物，龍形而通身純青，數出此岡顶，故因以為名青龍也。","sortOrder":86},
  {"id":"s_work_nvlt_6_87","chapterId":"ch_work_nvlt_6","text":"又曰：贛縣有馬脊岡，其形如馬脊，故以為名也。","sortOrder":87},
  {"id":"s_work_nvlt_6_88","chapterId":"ch_work_nvlt_6","text":"《衡山記》曰：衡山有曾青岡，出曾青，可合仙藥，有靈寿岡，多靈寿木。","sortOrder":88},
  {"id":"s_work_nvlt_6_89","chapterId":"ch_work_nvlt_6","text":"《圖墓書》曰：冢前左右有小岡如投筭，相連數里，名為导引岡，葬之出富貴。","sortOrder":89},
  {"id":"s_work_nvlt_6_90","chapterId":"ch_work_nvlt_6","text":"又曰：經言糟遇沉岡，遠至二十年，皆絕世無後，葬遇浮岡，隨世沉浮，著土必安，終無灾厄，葬遇飛岡，弈世富貴，亦出神仙。","sortOrder":90},
  {"id":"s_work_nvlt_6_91","chapterId":"ch_work_nvlt_6","text":"【詩】宋謝靈運入華子岡麻原第三穀詩曰：南州實炎德，桂树凌寒山，銅陵映碧涧，石磴寫紅泉，既枉隱淪客，亦栖肥遁賢，遂登群峰首，邈若勝雲煙，羽人絕仿佛，丹丘徒空荃，圖牒复磨滅，碑板誰聞傳，莫辨百代後，安知千載前，且申獨往意，乘月弄潺湲。","sortOrder":91},
  {"id":"s_work_nvlt_6_92","chapterId":"ch_work_nvlt_6","text":"【賦】宋傅亮登龍岡賦曰：靜潛處以永念，聊駕言以寫忧，蒙旭露而夙軫，稅餘辔於龍丘，南臨平隰，西际荒畴，比宇連甍，幽榛四周，眺江都之廣澨，究川陆之回脩，羨翔羽之嬉林，樂绿蘋之在流，乘清漪以汎濫，翳稠枚而命仇，信遂生之有所，何怵迫於人尤。","sortOrder":92},
  {"id":"s_work_nvlt_6_94","chapterId":"ch_work_nvlt_6","text":"晉中興書徵祥［原訛拜，據冯校本改，按何法盛晉中興書有徵祥說，下傅字衍。］傅說曰：鹹和四年，庐山西大巖崩，俄而郭默害江州刺史，伏誅。","sortOrder":94},
  {"id":"s_work_nvlt_6_95","chapterId":"ch_work_nvlt_6","text":"《尋陽記》曰：赤山崖峻壁上多靈巖，生仙菜，村人恒采之也。","sortOrder":95},
  {"id":"s_work_nvlt_6_96","chapterId":"ch_work_nvlt_6","text":"《嵩高山記》曰：少室山大巖中，有一石室，雲有自然經書，自然飲食，室前有一石柱，象承露盤，上有石脂，滴滴流下，服之一合，寿與天地同畢。","sortOrder":96},
  {"id":"s_work_nvlt_6_97","chapterId":"ch_work_nvlt_6","text":"盛弘之《荆州記》曰：平樂縣有山，臨水，巖間有兩目，如人眼，極大，瞳子白黑分明，名為目巖。","sortOrder":97},
  {"id":"s_work_nvlt_6_98","chapterId":"ch_work_nvlt_6","text":"又曰：始興機山東，有兩巖相向，如鴟尾，石室數十所，經過皆聞有金石絲竹之聲。","sortOrder":98},
  {"id":"s_work_nvlt_6_99","chapterId":"ch_work_nvlt_6","text":"鄭緝之《東陽記》曰：北山有春草巖根竹巖仙姥巖間不生蔓草，盡出龍須，尤多藥物。","sortOrder":99},
  {"id":"s_work_nvlt_6_100","chapterId":"ch_work_nvlt_6","text":"【詩】梁丘遲夜發密巖口詩曰：弭棹才假寐，击汰已爭先，敞朗朝霞澈，驚明晓魄懸，方尋仰危石，百丈窥重泉，丛枝上點點，崩溜下填填。","sortOrder":100},
  {"id":"s_work_nvlt_6_102","chapterId":"ch_work_nvlt_6","text":"《續漢書》曰：虞詡為武都太守，下辯東三十里，有峡，中有大石，鄣塞水流。春夏辄濆溢，败坏城郭，詡使人燒石，以水灌之，石皆罅裂，因鑴去，遂無沉溺之害。","sortOrder":102},
  {"id":"s_work_nvlt_6_103","chapterId":"ch_work_nvlt_6","text":"庾仲雍《荆州記》曰：巴楚有明月峡廣德峡東突峡，今謂之巫峡秭歸峡歸乡峡。","sortOrder":103},
  {"id":"s_work_nvlt_6_104","chapterId":"ch_work_nvlt_6","text":"袁山松宜都記曰：自西陵溯江西北行三十里，入峡口，其山行周回隱映，如絕复通，高山重嶂，非日中夜半，不見日月也。","sortOrder":104},
  {"id":"s_work_nvlt_6_105","chapterId":"ch_work_nvlt_6","text":"邓德明《南康記》曰：雩都峡去縣百里，兩邊傍江，江廣三十餘丈，高嶺稠叠，連巖石峙，其水常自激涌，奔轉如輪，春夏洪潦，經過阻絕。","sortOrder":105},
  {"id":"s_work_nvlt_6_106","chapterId":"ch_work_nvlt_6","text":"王韶之始興記曰：梁鮮二水口下流，有滇陽峡，長二十餘里，山嶺紆鬱，丛流曲勃，中宿縣有貞女峡，峡西岸水际，有石，如人形，状似女子，是曰貞女，父老相傳，秦世有女數人，取螺於此，遇風雨晝昏，而一女化為此石。","sortOrder":106},
  {"id":"s_work_nvlt_6_107","chapterId":"ch_work_nvlt_6","text":"【賦】梁萧子范建安城門峡賦曰：原夫城門之所都，乃設险於閩區，艱難過於身势，襟要甚於飛狐，長湍一流而沸涌，曾山兩判而盤紆，對巘双分，幹宵帶雲，怪石隨波而隱見，枯槎橫出而不群，顧瞻左右，重峦接阜，其間如砺，其絕如斗，千乘馳輪，匹夫可守，巃崧呀呷，蹙浪楊華，雁門飲羽，西施浣沙，朅诡丰隆，质状不同，班黃糅采，玄紫潛通，水奔湍其如電，聲疾烈其如風，树低柯而翠鬱，潭隱日而青空。","sortOrder":107},
  {"id":"s_work_nvlt_6_108","chapterId":"ch_work_nvlt_6","text":"隋江總貞女峡賦曰：倦辛苦於嶺表，遂沉淪於海外，跡飄飖於轉蓬，情缭繞於懸旆，駭茲峡之珍怪，佇奇峰而矖矚，或逦迤而四成，乍嶵{山隗}而五曲，含照曜之燭銀，渧潺湲之膏玉，山蒼蒼以墜葉，树索索而搖枝，澄碧源之見底，耸翠壁以臨危。","sortOrder":108},
  {"id":"s_work_nvlt_6_110","chapterId":"ch_work_nvlt_6","text":"《物理論》曰：土精為石。","sortOrder":110},
  {"id":"s_work_nvlt_6_111","chapterId":"ch_work_nvlt_6","text":"《尚書》曰：青州，厥貢鉛松怪石。","sortOrder":111},
  {"id":"s_work_nvlt_6_112","chapterId":"ch_work_nvlt_6","text":"《周官》曰：大司寇，以嘉石平罢民，有罪者坐諸嘉石，以肺石達窮民，凡茕獨老幼，欲复於上而未達者，立於肺石，［註曰：嘉石，文石也，肺石，赤石也。］","sortOrder":112},
  {"id":"s_work_nvlt_6_113","chapterId":"ch_work_nvlt_6","text":"《毛詩》曰：漸漸之石，維其高矣。","sortOrder":113},
  {"id":"s_work_nvlt_6_114","chapterId":"ch_work_nvlt_6","text":"《穆天子傳》曰：天子升於采石之山，於是取采石焉，鑄以成器，於黑水之上。","sortOrder":114},
  {"id":"s_work_nvlt_6_115","chapterId":"ch_work_nvlt_6","text":"《尸子》曰：昔者武王崩，成王少，周公旦踐東宮，履乘石，祀明堂，假為天子七年，［乘石，王所登上車之石也。］","sortOrder":115},
  {"id":"s_work_nvlt_6_116","chapterId":"ch_work_nvlt_6","text":"《列子》曰：天亦物也，物有不足，故昔者女媧氏煉五色之石，以補其闕。","sortOrder":116},
  {"id":"s_work_nvlt_6_117","chapterId":"ch_work_nvlt_6","text":"《隋巢子》曰：禹產於崑石，啟生於石，［王韶之雲，啟生而母化為石。］","sortOrder":117},
  {"id":"s_work_nvlt_6_118","chapterId":"ch_work_nvlt_6","text":"呂氏春秋曰：石可破也，不可奪其堅。","sortOrder":118},
  {"id":"s_work_nvlt_6_119","chapterId":"ch_work_nvlt_6","text":"《史記》曰：王翦［原訛剪，據冯校本改，下同。］代李信击荆，荆兵數挑戰。終不出，久之，翦使人問軍中戲乎，對曰：方投石超距，翦曰：士卒可用矣。","sortOrder":119},
  {"id":"s_work_nvlt_6_120","chapterId":"ch_work_nvlt_6","text":"又曰：張良見老人出一編書，曰：讀是則為王者師，後十二年，見我濟北穀城山下，黃石即我也，良後果得黃石，寶而祠之，及死，併葬黃石，伏腊祠之。","sortOrder":120},
  {"id":"s_work_nvlt_6_121","chapterId":"ch_work_nvlt_6","text":"《韓詩外傳》曰：楚熊渠子夜行，見寢石，以為伏虎，弯弓而射之，没金飲羽，下视，知其石也，因复射之，矢摧無跡，［漢書載李廣，亦如之。］","sortOrder":121},
  {"id":"s_work_nvlt_6_122","chapterId":"ch_work_nvlt_6","text":"十洲記曰：流洲，在西海中，上多積石，名為崑吾石，冶其成鐵，作劍，光明照洞，如水精状，割玉物，如切泥土焉。","sortOrder":122},
  {"id":"s_work_nvlt_6_123","chapterId":"ch_work_nvlt_6","text":"《阚子》曰：宋之愚人，得燕石於梧台之東，歸而藏之以為寶，周客聞而觀焉。主人斋七日，端冕玄服以發寶，革匮十重，緹巾十袭，客見之，掩口而笑曰：此特燕石也，其與瓦甓不殊。","sortOrder":123},
  {"id":"s_work_nvlt_6_124","chapterId":"ch_work_nvlt_6","text":"應劭《漢官儀》曰：馬伯弟登太山，見石二枚，其一是武帝時石，用五車載不能上，因置山下為屋，號曰五車石，其一是紀號石，刻文字，紀功德，立壇上。","sortOrder":124},
  {"id":"s_work_nvlt_6_125","chapterId":"ch_work_nvlt_6","text":"《博物志》曰：桃林，在弘農湖城縣休牛之山，有石焉，曰帝台之椹也，五色而文，状如鶉卵。","sortOrder":125},
  {"id":"s_work_nvlt_6_126","chapterId":"ch_work_nvlt_6","text":"《神仙傳》曰：白石生者，恒煮白石為糧，就白石山居，故號白石先生。","sortOrder":126},
  {"id":"s_work_nvlt_6_127","chapterId":"ch_work_nvlt_6","text":"遊名山志曰：芙蓉渚有耸石，頭如初生芙蓉，色皆青白。","sortOrder":127},
  {"id":"s_work_nvlt_6_128","chapterId":"ch_work_nvlt_6","text":"三齊略記曰：始皇作石塘，欲過海看日出處，時有神人，能驅石下海，石去不速，神辄鞭之，皆流血，至今悉赤，陽城山石盡起立，嶷嶷東傾，状如相隨行，［事具神篇。］","sortOrder":128},
  {"id":"s_work_nvlt_6_129","chapterId":"ch_work_nvlt_6","text":"王韶之《南康記》曰：湘源有長瀨，其傍石，或像人形，或似牛羊，其土人名人形者為令史。","sortOrder":129},
  {"id":"s_work_nvlt_6_130","chapterId":"ch_work_nvlt_6","text":"邓德明《南康記》曰：雩都縣有金雞石。","sortOrder":130},
  {"id":"s_work_nvlt_6_131","chapterId":"ch_work_nvlt_6","text":"武昌記曰：盤龍石，舊傳雲，有龍盤於此石，積日方去。","sortOrder":131},
  {"id":"s_work_nvlt_6_132","chapterId":"ch_work_nvlt_6","text":"庾仲雍《荆州記》曰：歸乡縣有屈原宅，女須廟，捣衣石，猶存。","sortOrder":132},
  {"id":"s_work_nvlt_6_133","chapterId":"ch_work_nvlt_6","text":"荆州圖副曰：宜都有石穴，穴有二石，相去一丈，俗雲，其一為陽石，其一為陰石，水旱為灾，鞭陽石則雨，鞭陰石則晴。","sortOrder":133},
  {"id":"s_work_nvlt_6_134","chapterId":"ch_work_nvlt_6","text":"《異苑》曰：永康王曠井上有一洗石，時見赤氣，後有二胡人寄宿，忽求買之。曠怪所以，未及度錢，子婦孫氏，睹二黃鳥斗於石上，疾往掩取，变成黃金，胡人不知，索市愈急，既得撞破，石內空段，有二鳥處。","sortOrder":134},
  {"id":"s_work_nvlt_6_135","chapterId":"ch_work_nvlt_6","text":"《幽明錄》曰：宜都建平二郡之界，有倚石，如二人像，攘袂相對，俗謂二郡督郵爭界於此。","sortOrder":135},
  {"id":"s_work_nvlt_6_136","chapterId":"ch_work_nvlt_6","text":"又曰：宮亭湖邊傍山間，有石數枚，形圓若鏡，明可以鑒人，謂之石鏡。","sortOrder":136},
  {"id":"s_work_nvlt_6_137","chapterId":"ch_work_nvlt_6","text":"【詩】陳陰铿詠石詩曰：天漢支機罢，仙嶺博棋餘，零陵舊是燕，崑池本學魚，雲移莲势出，苔駮錦文疏，還當穀城下，別自解兵書。","sortOrder":137},
  {"id":"s_work_nvlt_6_138","chapterId":"ch_work_nvlt_6","text":"陳周弘正詠石鯨應詔詩曰：石鯨何壮麗，獨在天池陰，騫鰭類橫海，半出似浮深，吞航本無日，吐浪亦難尋，聖帝遊靈沼，能懷躍藻心。","sortOrder":138},
  {"id":"s_work_nvlt_6_139","chapterId":"ch_work_nvlt_6","text":"【賦】陳張正見石賦曰：連山蔽虧，巨石嵚崎，上興雲而蔚薈，下激水而推移，舒丹霞於九折，混白露於三危，镇方城於濮水，固天闕於湯池，开五嶽之靈圖，集九老之仙都，韜神弓於射的，產利劍於崑吾，魚躍湘乡之水，雁浮平固之湖，嶞山鵲之金印，碎驪龍之寶珠，奄藹披衣，氤氲翠微，精衛取而填海，天孫用以支機，隨西王而不落，傍東武而俱飛。","sortOrder":139},
  {"id":"s_work_nvlt_6_140","chapterId":"ch_work_nvlt_6","text":"【贊】晉郭璞磁石贊曰：磁石吸鐵，琥珀取芥，氣有潛通，數亦冥會，物之相感，出乎意外。","sortOrder":140},
  {"id":"s_work_nvlt_6_142","chapterId":"ch_work_nvlt_6","text":"《山海經》曰：黑水之南，有玄蛇，食尘，大人之國，有大青蛇，頭方，食尘。","sortOrder":142},
  {"id":"s_work_nvlt_6_143","chapterId":"ch_work_nvlt_6","text":"又曰：前有尘埃，則載鳴鳶。","sortOrder":143},
  {"id":"s_work_nvlt_6_144","chapterId":"ch_work_nvlt_6","text":"《毛詩》曰：無將大車，維尘冥冥。","sortOrder":144},
  {"id":"s_work_nvlt_6_145","chapterId":"ch_work_nvlt_6","text":"《左傳》曰：晉楚戰於城濮，狐毛設二旆而退之，栾枝使舆曳柴而伪遁，［曳柴起尘，作却走。］","sortOrder":145},
  {"id":"s_work_nvlt_6_146","chapterId":"ch_work_nvlt_6","text":"《老子》曰：和其光，同其尘。","sortOrder":146},
  {"id":"s_work_nvlt_6_147","chapterId":"ch_work_nvlt_6","text":"《莊子》曰：野馬也，尘埃也，生物之以息相吹者也。","sortOrder":147},
  {"id":"s_work_nvlt_6_148","chapterId":"ch_work_nvlt_6","text":"《楚辭》曰：安能以皓皓之白，蒙世俗之尘埃哉，《淮南子》曰：地不滿東南，故水潦尘埃歸焉。","sortOrder":148},
  {"id":"s_work_nvlt_6_149","chapterId":"ch_work_nvlt_6","text":"謝承《後漢書》曰：范丹，字史雲，所居单陋，有時絕糧，闾里歌之曰：甑中生尘范史雲也。","sortOrder":149},
  {"id":"s_work_nvlt_6_150","chapterId":"ch_work_nvlt_6","text":"應璩與曹公箋曰：昔漢光武與戴子高，有撫尘之好。","sortOrder":150},
  {"id":"s_work_nvlt_6_151","chapterId":"ch_work_nvlt_6","text":"蔡邕勸學曰：蚓無爪牙，软弱不便，穿穴洞地，食尘飲泉。","sortOrder":151},
  {"id":"s_work_nvlt_6_152","chapterId":"ch_work_nvlt_6","text":"《博物志》曰：徐州人謂尘土為蓬塊，吳人謂尘土為埃坱。","sortOrder":152},
  {"id":"s_work_nvlt_6_153","chapterId":"ch_work_nvlt_6","text":"李康遊山序曰：蓋人生天地之間也，若流電之過戶牖，輕尘之遷弱草。","sortOrder":153},
  {"id":"s_work_nvlt_6_154","chapterId":"ch_work_nvlt_6","text":"《郭子》曰：庾公名位漸重，足傾王公，時庾亮在石頭，王公在城，忽風起扬尘，王公以扇拂之曰：元規尘污人，［元規，庾亮字，王公，王导也。］","sortOrder":154},
  {"id":"s_work_nvlt_6_155","chapterId":"ch_work_nvlt_6","text":"【詩】晉傅玄飛尘篇曰：飛尘秽清流，朝雲蔽日光，秋蘭豈不芬，鮑肆亂其芳，河决潰金堤，一手不能障。","sortOrder":155},
  {"id":"s_work_nvlt_6_156","chapterId":"ch_work_nvlt_6","text":"梁簡文帝詠梁尘詩曰：依帷翠濛重，帶日聚輕紅，定為歌聲起，非關团扇風。","sortOrder":156},
  {"id":"s_work_nvlt_6_157","chapterId":"ch_work_nvlt_6","text":"梁徐摛賦得帘尘詩曰：朝逐珠胎卷，夜傍玉鉤垂，恒交羅袖拂，不分秋風吹。","sortOrder":157},
  {"id":"s_work_nvlt_6_158","chapterId":"ch_work_nvlt_6","text":"◇州部","sortOrder":158},
  {"id":"s_work_nvlt_6_159","chapterId":"ch_work_nvlt_6","text":"《春秋說題辭》曰：州之言殊也，合同類，異其界也。","sortOrder":159},
  {"id":"s_work_nvlt_6_160","chapterId":"ch_work_nvlt_6","text":"《說文》曰：尧遭洪水，民居水中高土，故名曰州，一曰：州，畴也，畴其土而生之也。","sortOrder":160},
  {"id":"s_work_nvlt_6_161","chapterId":"ch_work_nvlt_6","text":"《物理論》曰：九州变易交错不同，禹貢有梁州，無併州，周官有併州，無梁州，爾雅有營州，無青州，漢興，武帝开拓三方，立十三州，通併梁之數，而增交益焉。","sortOrder":161},
  {"id":"s_work_nvlt_6_162","chapterId":"ch_work_nvlt_6","text":"《風俗通》曰：周禮，五党為州，州，畴也，州有長，使之相周足也。","sortOrder":162},
  {"id":"s_work_nvlt_6_163","chapterId":"ch_work_nvlt_6","text":"《河圖括地象》曰：天有九部八紀，地有九州八柱。","sortOrder":163},
  {"id":"s_work_nvlt_6_164","chapterId":"ch_work_nvlt_6","text":"《尚書大傳》曰：古之處師，八家［《太平御覽》一百五十七家下有而為鄰三字。］三鄰而為明，［御覽作朋，下同。］三明而為里，五里而為邑，十邑而為都，十都而為師，州十有二師焉。","sortOrder":164},
  {"id":"s_work_nvlt_6_165","chapterId":"ch_work_nvlt_6","text":"張衡靈憲圖曰：崑崙東南，有赤縣之州，風雨有時，寒暑有節，苟非此土，南則多暑，北則多寒，東則多陰，故聖王不處焉。","sortOrder":165},
  {"id":"s_work_nvlt_6_166","chapterId":"ch_work_nvlt_6","text":"《史記》曰：邹衍著書雲，中國於天下，八十一分居其一分耳，中國名赤縣，赤縣內自有九州，禹之叙九州是也，不得為州數，中國外，如赤縣州者有九，乃謂九州也，有神［《初學記》八，《太平御覽》一百五十七作裨。］海環之，如一區中者，乃為一州，如是者九，乃有大瀛海環其外，天地之际焉。","sortOrder":166},
  {"id":"s_work_nvlt_6_167","chapterId":"ch_work_nvlt_6","text":"※冀州","sortOrder":167},
  {"id":"s_work_nvlt_6_168","chapterId":"ch_work_nvlt_6","text":"《爾雅》曰：兩河間曰冀州。","sortOrder":168},
  {"id":"s_work_nvlt_6_169","chapterId":"ch_work_nvlt_6","text":"《周官》曰：河內曰冀州，其山镇曰霍山，其泽藪曰楊紆，其川漳，其浸汾潞，其利松柏。","sortOrder":169},
  {"id":"s_work_nvlt_6_170","chapterId":"ch_work_nvlt_6","text":"《春秋元命苞》曰：昴畢間為天街，散為冀州，分為趙國，立為常山。","sortOrder":170},
  {"id":"s_work_nvlt_6_171","chapterId":"ch_work_nvlt_6","text":"《淮南子》曰：往古之時，四極废，九州裂，於是女媧殺黑龍，以祭冀州，［事具帝王部。］","sortOrder":171},
  {"id":"s_work_nvlt_6_172","chapterId":"ch_work_nvlt_6","text":"《釋名》曰：冀州，取地以為名也，其地有险有易，帝王所都，亂則冀治，弱則冀強，荒則冀丰也。","sortOrder":172},
  {"id":"s_work_nvlt_6_173","chapterId":"ch_work_nvlt_6","text":"【賦】漢班彪冀州賦曰：夫何事於冀州，聊讬公以遊居，歷九州而觀風，亦哲人之所娱，望常山之峨峨，登北嶽而高遊，建封壇於岱宗，瘞玄玉於此丘，遍五嶽與四渎，觀沧海以周流。","sortOrder":173},
  {"id":"s_work_nvlt_6_174","chapterId":"ch_work_nvlt_6","text":"【箴】漢楊雄冀州箴曰：洋洋冀州，鸿原大陆，嶽陽是都，島夷皮服，潺湲河流，表以碣石，三後攸降，列為侯伯，隆周之末，趙魏是宅，冀土麋沸，炫沄如湯，更盛更衰，載從載橫，漢興定製，改列藩王，故治不忘亂，安不忘危，牧臣司冀，敢告在階。","sortOrder":174},
  {"id":"s_work_nvlt_6_175","chapterId":"ch_work_nvlt_6","text":"※楊州","sortOrder":175},
  {"id":"s_work_nvlt_6_176","chapterId":"ch_work_nvlt_6","text":"《尚書·禹貢》：淮海惟楊州，厥貢瑤琨筱簜，厥苞橘柚。","sortOrder":176},
  {"id":"s_work_nvlt_6_177","chapterId":"ch_work_nvlt_6","text":"《周官》曰：東南曰楊州，其山镇曰會稽，其泽藪曰具區，其川三江，其浸五湖，其利金錫竹箭。","sortOrder":177},
  {"id":"s_work_nvlt_6_178","chapterId":"ch_work_nvlt_6","text":"《春秋元命苞》曰：牵牛流為楊州，分為越國，立為楊山。","sortOrder":178},
  {"id":"s_work_nvlt_6_179","chapterId":"ch_work_nvlt_6","text":"《續漢書》曰：張禹拜楊州刺史，當濟江行部，土人皆以江有子胥之神，難於濟涉，禹厲聲雲，子胥若其有靈，知吾志在理察枉訟，豈危我哉，令鼓楫而過，歷行部邑吏民希見者，人懷喜悅。","sortOrder":179},
  {"id":"s_work_nvlt_6_180","chapterId":"ch_work_nvlt_6","text":"益部耆舊傳雲，嚴遵為楊州刺史，行部，聞道傍女子哭聲不哀，問所哭者誰。對雲，夫遭燒死，遵敕吏舁尸到，與語訖，語吏雲，死人自道不燒死，攝女，令人守尸，雲當有［《太平御覽》二百五十八作有物，此脱。］往，吏白有蠅聚頭所，遵令披视，得鐵錐貫顶，考問，淫殺夫。","sortOrder":180},
  {"id":"s_work_nvlt_6_181","chapterId":"ch_work_nvlt_6","text":"【箴】漢楊雄楊州箴曰：天矯楊州，江漢之滸，彭蠡既潴，陽鳥攸處，橘柚羽貝，瑤琨筱簜，閩越北垠，沅湘攸往，翩彼昭王，南征不旋，人鹹踬於垤，莫踬於山，太伯遜位，其吳紹類，夫差一誤，太伯無祚，周室不匡，勾踐入霸，當周之隆，越裳重譯，春秋之末，侯甸叛逆，元首不可不思，股肱不可不慈，尧崇屢省，舜盛钦謀，牧臣司楊，敢告執筹。","sortOrder":181},
  {"id":"s_work_nvlt_6_182","chapterId":"ch_work_nvlt_6","text":"※荆州","sortOrder":182},
  {"id":"s_work_nvlt_6_183","chapterId":"ch_work_nvlt_6","text":"《尚書·禹貢》曰：荆及衡陽惟荆州，厥貢羽毛齒革，惟金三品，杶幹栝柏。砺砥砮丹，惟箘簬楛，苞匦菁茅，厥篚玄纁璣組，九江納錫大龟。","sortOrder":183},
  {"id":"s_work_nvlt_6_184","chapterId":"ch_work_nvlt_6","text":"《釋名》曰：荆州，取名於荆山也，荆，警也，警南蠻數為寇逆，其民有道後服，無道先強，常警備之也。","sortOrder":184},
  {"id":"s_work_nvlt_6_185","chapterId":"ch_work_nvlt_6","text":"《春秋元命苞》曰：軫星散為荆州，分為楚國，荆之為言強也，陽盛物堅，其氣急悍也。","sortOrder":185},
  {"id":"s_work_nvlt_6_186","chapterId":"ch_work_nvlt_6","text":"元康地記曰：荆州於古，蠻服之地也，秦滅楚，置郡縣，漢武分為交州，至魏晉而荆州所部郡國二十。","sortOrder":186},
  {"id":"s_work_nvlt_6_187","chapterId":"ch_work_nvlt_6","text":"《周官》曰：正南曰荆州，其山镇曰衡山，其泽藪曰雲夢，其川江漢，其浸潁湛，其利丹銀齒角。","sortOrder":187},
  {"id":"s_work_nvlt_6_188","chapterId":"ch_work_nvlt_6","text":"沈約《宋書》曰：朱脩之為荆州刺史，百城士民赠貺，一毫無所受，去镇之日，秋毫無犯，計在州以來，內外燃油，及私牛馬食費，以私錢六十萬裨之。","sortOrder":188},
  {"id":"s_work_nvlt_6_189","chapterId":"ch_work_nvlt_6","text":"【箴】漢楊雄荆州箴曰：杳杳巫山，在荆之陽，江漢朝宗，其流湯湯，雲夢涂泥，包匦菁茅，金玉砥砺，象齒元龟，貢篚百物，世世以饒，戰戰栗栗，至桀荒溢，我在帝位，若天有日，不順庶國，孰敢餘奪，亦有成湯，果秉其鉞，放之南巢，號之以桀，南巢茫茫，多楚與荆，風飄以悍，氣銳以刚，有道後服，無道先強，世雖安平，無敢逸豫，牧臣司荆，敢告執御。","sortOrder":189},
  {"id":"s_work_nvlt_6_190","chapterId":"ch_work_nvlt_6","text":"※青州","sortOrder":190},
  {"id":"s_work_nvlt_6_191","chapterId":"ch_work_nvlt_6","text":"《尚書·禹貢》曰：海岱惟青州，厥貢鹽絺，海物惟错，岱畎絲枲，鉛松怪石。","sortOrder":191},
  {"id":"s_work_nvlt_6_192","chapterId":"ch_work_nvlt_6","text":"《春秋元命苞》曰：虛危之精，流為青州，分為齊國，立為萊山。","sortOrder":192},
  {"id":"s_work_nvlt_6_193","chapterId":"ch_work_nvlt_6","text":"《太康地記》曰：青州，東方少陽，其色青，其氣清，歲之首，事之始也，故以為名，周之建國，表齊東海，居於青州，故吳季札觀樂於魯，聞齊之詩，雲泱泱乎大國之風也，其表東海者乎。","sortOrder":193},
  {"id":"s_work_nvlt_6_194","chapterId":"ch_work_nvlt_6","text":"《周官》曰：正東曰青州，其山镇曰沂山，其泽藪曰望諸，其川淮泗，其浸沂沐，［周禮職方氏作沭。］其利蒲魚。","sortOrder":194},
  {"id":"s_work_nvlt_6_195","chapterId":"ch_work_nvlt_6","text":"王隱晉書雲，苟晞為青州刺史，役煩賦重，民不堪命，日斬十人，流血成川，號雲屠伯。","sortOrder":195},
  {"id":"s_work_nvlt_6_196","chapterId":"ch_work_nvlt_6","text":"【箴】漢楊雄青州箴曰：茫茫青州，海岱是極，鹽鐵之地，鉛松怪石，群水攸歸，萊夷作牧，貢篚以時，莫怠莫违，昔在文武，封呂於齊，厥土涂泥，在丘之營，五侯九伯，是讨是征，馬殆其衔，御失其度，周室荒亂，小白以霸，諸侯雖服，复尊京師，小白既没，周卒陵遲，嗟茲天王，附命下土，失其法度，丧其文武，牧臣司青，敢告執矩。","sortOrder":196},
  {"id":"s_work_nvlt_6_197","chapterId":"ch_work_nvlt_6","text":"※徐州","sortOrder":197},
  {"id":"s_work_nvlt_6_198","chapterId":"ch_work_nvlt_6","text":"《尚書·禹貢》曰：海岱及淮惟徐州，厥貢惟土五色，嶧陽孤桐，泗濱浮磬，淮夷蠙珠暨魚，厥篚玄纖縞。","sortOrder":198},
  {"id":"s_work_nvlt_6_199","chapterId":"ch_work_nvlt_6","text":"《春秋元命苞》曰：天弓星，主司弓弩，流為徐州，別為魯國，徐之為言舒也，言陰牧內安詳也","sortOrder":199},
  {"id":"s_work_nvlt_6_200","chapterId":"ch_work_nvlt_6","text":"【箴】漢楊雄徐州箴曰：海岱伊淮，東海是渚，豫州之土，邑於蕃宇，大野既猪，有羽有蒙，孤桐蠙珠，泗沂攸同，降周任薑，镇於琅琊，薑氏絕苗，田氏攸都，事猶細微，不慮不圖，禍如丘山，本在萌牙，牧臣司徐，敢告仆夫。","sortOrder":200},
  {"id":"s_work_nvlt_6_201","chapterId":"ch_work_nvlt_6","text":"※兖州","sortOrder":201},
  {"id":"s_work_nvlt_6_202","chapterId":"ch_work_nvlt_6","text":"《尚書·禹貢》曰：濟河惟兖州，厥貢漆絲，厥篚織文，浮於濟漯，達於河。","sortOrder":202},
  {"id":"s_work_nvlt_6_203","chapterId":"ch_work_nvlt_6","text":"《春秋元命苞》曰：五星流為兖州，兖之言端也，言隄精端，故其氣纖殺，分為鄭國。","sortOrder":203},
  {"id":"s_work_nvlt_6_204","chapterId":"ch_work_nvlt_6","text":"《周官》曰：河東曰兖州，其山镇曰岱山，其泽藪曰大野，其川河沛，其浸盧維，其利蒲魚。","sortOrder":204},
  {"id":"s_work_nvlt_6_205","chapterId":"ch_work_nvlt_6","text":"【箴】漢楊雄兖州箴曰：悠悠濟河，兖州之宇，九河既导，雷夏攸處，草繇木條，漆絲絺纻，濟漯既通，降丘宅土，成湯五徙，卒都於亳，盤庚北度，牧野是宅，箕子歔欷，厥居為墟，牧臣司兖，敢告執書。","sortOrder":205},
  {"id":"s_work_nvlt_6_206","chapterId":"ch_work_nvlt_6","text":"※豫州","sortOrder":206},
  {"id":"s_work_nvlt_6_207","chapterId":"ch_work_nvlt_6","text":"《尚書·禹貢》曰：荆河惟豫州，厥貢漆枲絺纻，厥篚纖纊，錫貢磬错，浮於洛。達於河。","sortOrder":207},
  {"id":"s_work_nvlt_6_208","chapterId":"ch_work_nvlt_6","text":"《春秋元命苞》曰：鉤鈐星，別為豫州，豫之為言序也，言陰陽分布，各得處也。","sortOrder":208},
  {"id":"s_work_nvlt_6_209","chapterId":"ch_work_nvlt_6","text":"《周官》曰：河南曰豫州，其山镇曰華山，其泽藪曰圃田，其川滎洛，其浸波溠，其利林漆絲枲。","sortOrder":209},
  {"id":"s_work_nvlt_6_210","chapterId":"ch_work_nvlt_6","text":"【箴】漢楊雄豫州箴曰：鬱鬱荆河，伊洛是經，滎嶓枲漆，惟用攸成，田田相拏，庐庐相距，夏殷不都，成周攸處，豫野所居，爰在鶉墟，四隩鹹宅，宇內莫如，毋曰我大，莫或餘败，毋曰我強，靡克餘亡，王赧為極，實絕周祀，牧臣司豫，敢告柱史。","sortOrder":210},
  {"id":"s_work_nvlt_6_211","chapterId":"ch_work_nvlt_6","text":"※雍州","sortOrder":211},
  {"id":"s_work_nvlt_6_212","chapterId":"ch_work_nvlt_6","text":"《尚書·禹貢》曰：黑水西河惟雍州，厥貢惟球琳琅玕，浮於積石，至於龍門西河。","sortOrder":212},
  {"id":"s_work_nvlt_6_213","chapterId":"ch_work_nvlt_6","text":"《春秋元命苞》曰：東井鬼星，散為雍州，分為秦國，東距殽阪，西有漢中，南含高山，北阻居庸，得東井動深之萌，其氣险也。","sortOrder":213},
  {"id":"s_work_nvlt_6_214","chapterId":"ch_work_nvlt_6","text":"《春秋文燿鉤》曰：華岐以北，龍門積石，南至三危之野，雍州，屬魁星。","sortOrder":214},
  {"id":"s_work_nvlt_6_215","chapterId":"ch_work_nvlt_6","text":"《太康地記》曰：雍州兼得梁州之地，西北之位，陽所不及，陰氣雍閼，故取名焉。","sortOrder":215},
  {"id":"s_work_nvlt_6_216","chapterId":"ch_work_nvlt_6","text":"《周官》曰：正西曰雍州，其山镇曰曰［曰字衍。］嶽山，其泽藪曰絃蒲，其川涇汭，其浸洛，其利玉石。","sortOrder":216},
  {"id":"s_work_nvlt_6_217","chapterId":"ch_work_nvlt_6","text":"【箴】漢楊雄雍州箴曰：黑水西河，橫截崑崙，邪指閶阖，盡為雍垠，上侵積石，下礙龍門，蓋安不忘危，盛不讳衰，牧臣司雍，敢告赘衣。","sortOrder":217},
  {"id":"s_work_nvlt_6_218","chapterId":"ch_work_nvlt_6","text":"※益州","sortOrder":218},
  {"id":"s_work_nvlt_6_219","chapterId":"ch_work_nvlt_6","text":"《春秋元命苞》曰：觜參流為益州，益之言隘也，謂物類併决，其氣急切决列也。","sortOrder":219},
  {"id":"s_work_nvlt_6_220","chapterId":"ch_work_nvlt_6","text":"楊雄《蜀本紀》曰：蜀始王曰蠶丛，次曰伯雍，次曰魚凫。","sortOrder":220},
  {"id":"s_work_nvlt_6_221","chapterId":"ch_work_nvlt_6","text":"又曰：武都人有女，蜀王納以為妃，疾卒，葬於成都，作石鏡一枚，以表其墓。","sortOrder":221},
  {"id":"s_work_nvlt_6_222","chapterId":"ch_work_nvlt_6","text":"《十三州志》曰：蜀王杜宇，自號望帝。","sortOrder":222},
  {"id":"s_work_nvlt_6_223","chapterId":"ch_work_nvlt_6","text":"左思蜀都賦曰：外負銅梁宕渠，內函要害膏腴。","sortOrder":223},
  {"id":"s_work_nvlt_6_224","chapterId":"ch_work_nvlt_6","text":"【箴】漢楊雄益州箴曰：巖巖岷山，古曰梁州，華陽西極，黑水南流，秦作無道，三方潰叛，義兵征暴，遂國於漢，拓开疆宇，恢梁之野，列為十二，光羨虞夏，牧臣司梁，是職是圖，經營盛衰，敢告士夫。","sortOrder":224},
  {"id":"s_work_nvlt_6_225","chapterId":"ch_work_nvlt_6","text":"※幽州","sortOrder":225},
  {"id":"s_work_nvlt_6_226","chapterId":"ch_work_nvlt_6","text":"《周官》曰：東北曰幽州，其山镇曰医無闾，其泽藪曰貕養，其川河沛，［周禮職方氏作泲。］其浸菑時，其利魚鹽。","sortOrder":226},
  {"id":"s_work_nvlt_6_227","chapterId":"ch_work_nvlt_6","text":"《春秋元命苞》曰：箕星散為幽州，分為燕國，幽之為言窈也，言風出入窈冥，敏劲易晓，故其氣躁急。","sortOrder":227},
  {"id":"s_work_nvlt_6_228","chapterId":"ch_work_nvlt_6","text":"《釋名》曰：幽州在北，幽昧之地也。","sortOrder":228},
  {"id":"s_work_nvlt_6_229","chapterId":"ch_work_nvlt_6","text":"【箴】漢楊雄幽州箴曰：荡荡平川，惟冀之別，伊昔唐虞，實為平陆，周末荐臻，迫於獯鬻，六國擅權，燕趙本都，東限秽犭百，羨及東湖，［《初學記》八作胡。］彊秦北排，蒙公城疆，大漢初定，分狄之荒，元戎屢征，如風之騰，義兵涉漠，偃我邊萌，既定且康，复古虞唐，盛不可不圖，衰不可不忘，隄潰蚁穴，器漏藏亡，牧臣司幽，敢告侍旁。","sortOrder":229},
  {"id":"s_work_nvlt_6_230","chapterId":"ch_work_nvlt_6","text":"※併州","sortOrder":230},
  {"id":"s_work_nvlt_6_231","chapterId":"ch_work_nvlt_6","text":"《春秋元命苞》曰：營室流為併州，分為衛國之镇，立為明山，併之為言誠也。精舍交併，其氣勇抗誠信也。","sortOrder":231},
  {"id":"s_work_nvlt_6_232","chapterId":"ch_work_nvlt_6","text":"《太康地記》曰：併州不以衛水為號，又不以恒山為名，而雲併者，蓋以其在兩穀之間乎，韓魏趙謂之三晉，即併冀二州，是其地也。","sortOrder":232},
  {"id":"s_work_nvlt_6_233","chapterId":"ch_work_nvlt_6","text":"《周官》曰：正北曰併州，其山镇曰恒山，其泽藪曰昭餘祁，其川虖池呕夷，其浸漆［周禮職方氏作淶。］易，其利布帛。","sortOrder":233},
  {"id":"s_work_nvlt_6_234","chapterId":"ch_work_nvlt_6","text":"【箴】漢楊雄併州箴曰：雍別朔方，河水悠悠，北辟獯鬻，南界涇流，盡茲朔土，正真［《初學記》八作直。］幽方，自昔何為，莫敢不來貢，莫敢不來王，周穆遐征，犬戎不享，爰藐伊意，侵玩上國，宣王命將，攘之涇北，宗幽罔識，日用爽蹉，既不俎豆，又不幹戈，犬戎作難，毙於驪阿，太上曜德，其次曜兵，德兵俱顛，靡不悴荒，牧臣司併，敢告執綱。","sortOrder":234},
  {"id":"s_work_nvlt_6_235","chapterId":"ch_work_nvlt_6","text":"※交州","sortOrder":235},
  {"id":"s_work_nvlt_6_236","chapterId":"ch_work_nvlt_6","text":"《苗恭交廣記》曰：漢武帝元鼎中，开拓土境，北开朔方，南置交阯刺史，建安二年，南陽張津為刺史，交阯太守土燮表言，伏見十二州皆稱曰州，而交獨為交阯刺史，何天恩不平乎，若普天之下，可為十二州者，獨不可為十三州，詔報聽許，拜津交州牧，加以九錫，彤弓彤矢，禮樂征伐，威震南夏，與中州方伯齊同，自津始也。","sortOrder":236},
  {"id":"s_work_nvlt_6_237","chapterId":"ch_work_nvlt_6","text":"《太康地記》曰：交州本屬楊州，取交阯以為名，虞之南極也，周有天下，越裳氏慕聖人之德，重九譯，貢白雉，秦滅六國，南开百越，置桂林象郡，以趙他為龍川令，因秦之末，自擅南裔，漢高革命，加以王爵，始变椎髻，袭冠冕焉。","sortOrder":237},
  {"id":"s_work_nvlt_6_238","chapterId":"ch_work_nvlt_6","text":"【箴】漢楊雄交州箴曰：交州荒裔，水與天际，越裳是南，荒國之外，爰自开辟，不羁不绊，周公攝祚，白雉是獻，昭王陵遲，周室是亂，越裳絕貢，荆楚逆叛，大漢受命，中國兼該，南海之宇，聖武是恢，稍稍受羁，遂臻黃支，抗海三萬，來牵其犀，盛不可不忧，隆不可不懼，泉竭中虛，池竭瀨乾，牧臣司交，敢告執憲。","sortOrder":238},
  {"id":"s_work_nvlt_6_239","chapterId":"ch_work_nvlt_6","text":"◇郡部","sortOrder":239},
  {"id":"s_work_nvlt_6_240","chapterId":"ch_work_nvlt_6","text":"《風俗通》曰：周製，天子方千里，分為縣，縣有四郡，故《左氏傳》曰：上大夫受縣，下大夫受郡，至秦始皇，初置三十六郡，以監縣。","sortOrder":240},
  {"id":"s_work_nvlt_6_241","chapterId":"ch_work_nvlt_6","text":"應劭《漢官》曰：秦用李斯議，分天下為三十六郡，凡郡，或以列國，陳魯齊吳是也，或以舊名，長沙丹陽是也，或以山陵，太山山陽是也，或以川源，西河河東也，或以所出，金城城下有金，酒泉泉味如酒，豫章樟树生庭中，雁門雁之所育是也。","sortOrder":241},
  {"id":"s_work_nvlt_6_242","chapterId":"ch_work_nvlt_6","text":"苗恭十四州記曰：秦兼天下，始皇二十六年，废五等之爵，立郡縣之官，以公國為大郡，侯伯為小郡，大郡曰守，小郡曰尉，郡之言君也，今之郡字，君在其左，邑在其右，君為元首，邑以載民，故取名於君，而謂之郡也。","sortOrder":242},
  {"id":"s_work_nvlt_6_243","chapterId":"ch_work_nvlt_6","text":"【箴】後漢劉騊駼郡太守箴曰：有嬴駈除，焚典紀舊，荡滅蕃畿，罢侯置守，秦發闾左，陳涉奋威，楚筑乾谿，靈王不歸，征遐由近，可不肅祗，守臣司境，敢告執機。","sortOrder":243},
  {"id":"s_work_nvlt_6_244","chapterId":"ch_work_nvlt_6","text":"※河南郡","sortOrder":244},
  {"id":"s_work_nvlt_6_245","chapterId":"ch_work_nvlt_6","text":"應劭《漢官》雲，河南尹，所治周地，秦兼天下，置三川守，河雒伊也，漢更名河南，孝武皇帝，增雲太守，世祖中興，徙都雒陽，改號為尹，尹，正也。","sortOrder":245},
  {"id":"s_work_nvlt_6_246","chapterId":"ch_work_nvlt_6","text":"謝承《後漢書》曰：華山松，為河南尹，優賢養民，興教崇化，至其剪治強宗。威烈不虧，遂見谮毀。","sortOrder":246},
  {"id":"s_work_nvlt_6_247","chapterId":"ch_work_nvlt_6","text":"又曰：羊陟，遷河南尹，下車，計日受俸，嘗食乾飯茹菜，禁斷豪右嘱讬。書疏不與交通，斷理冤徒，進用善士，節操者旌表異行。","sortOrder":247},
  {"id":"s_work_nvlt_6_248","chapterId":"ch_work_nvlt_6","text":"《魏志》雲：司馬芝為河南尹，抑強撫弱，私請不行，芝為教與群下曰：蓋君能設教，不能使吏必不犯也，吏能犯教，而不能使君必不聞也，夫設教而犯，君之劣也，犯教而聞，吏之禍也，君劣於上，吏禍於下，此政事所以不理也，可不各勉之哉。","sortOrder":248},
  {"id":"s_work_nvlt_6_249","chapterId":"ch_work_nvlt_6","text":"《傅子》曰：傅嘏為河南尹，治以德教為本，然持法有恒，簡而不可犯，見理識情，獄訟不任槚楚而得其實，不為小惠，有所荐達，及有大益於民，皆隱其端跡，若不由己。","sortOrder":249},
  {"id":"s_work_nvlt_6_250","chapterId":"ch_work_nvlt_6","text":"又曰：樂廣為河南尹，郡中前廳，多怪病，後人皆於廊下督郵傳中治事，無敢在廳事者，唯廣處之，白日戶自閉，二子凯橫等慑怖，廣使掘牆孔，得狸乃絕。","sortOrder":250},
  {"id":"s_work_nvlt_6_251","chapterId":"ch_work_nvlt_6","text":"【箴】後漢崔骃河南尹箴曰：茫茫天區，畫冀為京，商邑翼翼，四方是營，唐虞商周，河洛是居，成王郏鄏，以處鶉墟，諸夏劲強，是從是橫，彻我牆屋，而師尹不匡，霸奪其權，宗器以分，圖籍遷齊，九鼎入秦。","sortOrder":251},
  {"id":"s_work_nvlt_6_252","chapterId":"ch_work_nvlt_6","text":"※京兆郡","sortOrder":252},
  {"id":"s_work_nvlt_6_253","chapterId":"ch_work_nvlt_6","text":"《漢書》曰：趙廣漢為京兆尹，以和顏接士，事善，推功歸之下，曰：某掾屬所為，非二千石所及，吏皆输寫心腹，無所隱匿。","sortOrder":253},
  {"id":"s_work_nvlt_6_254","chapterId":"ch_work_nvlt_6","text":"又曰：張敞守京兆尹，尹自趙廣漢誅後，皆不稱職，京師寢废，長安市偷盜尤多，百贾苦之，敞既视事，求問長安偷盜首長數人，居皆溫厚，出從僮仆，闾里以為長者，敞皆召，既見责問，因貸其罪，乃署吏，令致諸偷以自贖，為置酒。小偷皆來贺之，飲醉，偷長陰以赭汙其衣裾，吏坐門閱，赭汙者辄收之，一日捕得數百人，由是枹鼓希鳴，市無偷盜。","sortOrder":254},
  {"id":"s_work_nvlt_6_255","chapterId":"ch_work_nvlt_6","text":"又曰：王駿為京兆尹，成帝欲大用之，故试以政事，先是京兆有趙廣漢張敞王遵王章王駿，皆有名，京師稱曰：前有趙張，後有三王。","sortOrder":255},
  {"id":"s_work_nvlt_6_256","chapterId":"ch_work_nvlt_6","text":"【碑】後漢蔡邕京兆尹樊陵碑曰：於顯哲尹，誕德孔彰，膺帝休命，謂篤不忘，爰納忠式，規悟聖皇，钦崇園邑，大孝允光，九命車服，昭示采章，軒轺四牡，承祀蒸嘗，多士時貢，繇役永息，進路孔夷，民清险棘，同體諸舊，兆萌蒙福，惠垂無疆，守以罔極。","sortOrder":256},
  {"id":"s_work_nvlt_6_257","chapterId":"ch_work_nvlt_6","text":"※宣城郡","sortOrder":257},
  {"id":"s_work_nvlt_6_258","chapterId":"ch_work_nvlt_6","text":"陶氏家傳雲，陶汪，晉鹹康中為宣城內史，君從父猷，先為之，君到郡，乃招隱逸，廣开學舍，以此教民，民有向方者，則辟為掾吏，百姓歌之曰：人當勤學得主簿，誰使為之陶明府。","sortOrder":258},
  {"id":"s_work_nvlt_6_259","chapterId":"ch_work_nvlt_6","text":"《晉中興書》曰：桓彝少孤，家貧，而性度高豁，不以箪瓢屑意，年在弱冠，便有知人之鑒，為宣城太守，百姓懷之。","sortOrder":259},
  {"id":"s_work_nvlt_6_260","chapterId":"ch_work_nvlt_6","text":"沈約《宋書》曰：羊玄保為黃門郎，善弈棋，棋品第三，太祖亦好弈，數蒙引見。嘉其溫謹，與太祖赌郡，戲勝，以補宣城太守。","sortOrder":260},
  {"id":"s_work_nvlt_6_261","chapterId":"ch_work_nvlt_6","text":"【詩】齊謝朓始之宣城郡詩曰：簪發逢嘉惠，教義承君子，心跡苦未併，忧歡將十祀，幸霑雲雨慶，方辔參多士，振鷺徒追飛，群龍難隸齒，烹鮮止貪競，共理屬廉恥，伊餘昧損益，何用祗千里，解劍北宮朝，息駕南川涘，寧希廣平詠，聊慕華陰市。","sortOrder":261},
  {"id":"s_work_nvlt_6_262","chapterId":"ch_work_nvlt_6","text":"又宣城郡內登望詩曰：借問下車日，匪直望舒圓，寒城一以眺，平楚正蒼然，山積稜［《文選》三十作陵。］陽阻，溪流春穀泉，威紆距遙甸，巉嵒帶遠天，切切陰風暮，桑柘起寒煙，怅望心已極，敞怳魂屢遷，結發倦為侣，平生早事邊，誰規鼎食盛，寧要狐白鮮，方弃汝南詔，［《文選》作诺。］言稅遼東田。","sortOrder":262},
  {"id":"s_work_nvlt_6_263","chapterId":"ch_work_nvlt_6","text":"※會稽郡","sortOrder":263},
  {"id":"s_work_nvlt_6_264","chapterId":"ch_work_nvlt_6","text":"司馬彪《續漢書》曰：任延拜會稽南部都尉，時年十九，迎吏見其少，皆驚，會稽多名士，延到官，皆聘請高行俊乂，警［後漢書六十六作敬。］待師友之禮。及掾吏貧乏，辄分俸祿，以赈給之。","sortOrder":264},
  {"id":"s_work_nvlt_6_265","chapterId":"ch_work_nvlt_6","text":"《晉中興書》曰：諸葛恢為會稽太守，臨行，上為置酒，謂之曰：會稽，晉之關中，足食足兵，在於太守，以君有涖任之方，是以相屈，四方分崩，當匡振否運，治之所先，君為言之，恢陳謝，因對曰：今天下丧亂之餘，風俗凌遲，宜尊五美，屏四惡，進忠實之士，退浮華之党，中宗深納之。","sortOrder":265},
  {"id":"s_work_nvlt_6_266","chapterId":"ch_work_nvlt_6","text":"又曰：王彪之為镇軍將軍會稽內史，加散騎常侍，居郡八年，豪強斂跡，亡戶出者三萬餘口。","sortOrder":266},
  {"id":"s_work_nvlt_6_267","chapterId":"ch_work_nvlt_6","text":"又曰：王述作會稽太守，外白請讳，答曰：惟祖惟考，四海所知，過此無所复讳。","sortOrder":267},
  {"id":"s_work_nvlt_6_268","chapterId":"ch_work_nvlt_6","text":"【啟】齊謝朓為王敬則謝會稽太守啟曰：臣本布衣，不謀遠大，折冲之勤不舉，燮理之義何階，常恐覆餗是貽，咎徵斯應，陛下繼歷勝統，日月重光，得以桓珪袞服，拜奉歲時，视濯獻牲，鞠躬郊廟，而鸿恩妄假，复授龟符，玉節邁於双璜，表東侔於四履，臨邊三事，既謝張溫，潁川再撫，亦慚黃霸。","sortOrder":268},
  {"id":"s_work_nvlt_6_269","chapterId":"ch_work_nvlt_6","text":"《藝文類聚》　唐·欧陽詢","sortOrder":269},
  {"id":"s_work_nvlt_7_1","chapterId":"ch_work_nvlt_7","text":"卷七山部上","sortOrder":1},
  {"id":"s_work_nvlt_7_2","chapterId":"ch_work_nvlt_7","text":"○總載山崑崙山嵩高山華山衡山庐山太行山荆山鍾山北芒山天台山首陽山燕然山羅浮山九疑山","sortOrder":2},
  {"id":"s_work_nvlt_7_3","chapterId":"ch_work_nvlt_7","text":"◇總載山","sortOrder":3},
  {"id":"s_work_nvlt_7_4","chapterId":"ch_work_nvlt_7","text":"《春秋說題辭》曰：山之為言宣也，含泽布氣，調五神也。","sortOrder":4},
  {"id":"s_work_nvlt_7_5","chapterId":"ch_work_nvlt_7","text":"《國語》曰：禹封九山，山者土之聚也。","sortOrder":5},
  {"id":"s_work_nvlt_7_6","chapterId":"ch_work_nvlt_7","text":"《論語》曰：仁者樂山。","sortOrder":6},
  {"id":"s_work_nvlt_7_7","chapterId":"ch_work_nvlt_7","text":"《春秋元命苞》曰：山者氣之包含，所［《太平御覽》三十八所下有以字。］含精藏雲，故觸石布山。","sortOrder":7},
  {"id":"s_work_nvlt_7_8","chapterId":"ch_work_nvlt_7","text":"《爾雅》曰：山西曰夕陽，山東曰朝陽。","sortOrder":8},
  {"id":"s_work_nvlt_7_9","chapterId":"ch_work_nvlt_7","text":"又曰：山大而高曰崧，山小而高曰岑，多草木曰屺，無草木曰岵，石戴土謂之崔嵬，土戴石為蛇且。","sortOrder":9},
  {"id":"s_work_nvlt_7_10","chapterId":"ch_work_nvlt_7","text":"《禮記》曰：夫山，一拳石之多，及其廣大，草木生之，禽獸居之，寶藏興焉。","sortOrder":10},
  {"id":"s_work_nvlt_7_11","chapterId":"ch_work_nvlt_7","text":"《史記》曰：黃帝東至於海，登丸山，西至於崆峒，登雞頭，南至熊湘，北逐獯鬻，合符金［明本作崟，當作釜，金系釜之坏體。］山。","sortOrder":11},
  {"id":"s_work_nvlt_7_12","chapterId":"ch_work_nvlt_7","text":"《蜀王本紀》曰：天為蜀王生五丁力士，能獻［《太平御覽》八百八十八作徙。］山，秦王獻美女與蜀王，蜀王遣五丁迎女，見一大蛇入山穴中，五丁併引蛇，山崩，秦五女皆上山，化為石。","sortOrder":12},
  {"id":"s_work_nvlt_7_13","chapterId":"ch_work_nvlt_7","text":"《河圖》曰：武關山為地門，上為天高星，主囹圄，岐山在崑崙東南，為地乳，上為天糜星，汶山之地為井絡，帝以會昌，神以建福，上為天井。","sortOrder":13},
  {"id":"s_work_nvlt_7_14","chapterId":"ch_work_nvlt_7","text":"《呂氏春秋》曰：何謂九山，會稽太山王屋首陽山太華歧山太行羊腸孟門。","sortOrder":14},
  {"id":"s_work_nvlt_7_15","chapterId":"ch_work_nvlt_7","text":"《漢名臣奏》曰：漢得陰山，匈奴長老過之，未嘗不哭。","sortOrder":15},
  {"id":"s_work_nvlt_7_16","chapterId":"ch_work_nvlt_7","text":"地鏡曰：入名山，必先斋五十日，牵白犬，抱白雞，以鹽一勝，［太平御覽三十八作升。］山神大喜，芝草異藥寶玉為出，未到山百步，呼曰林林央央，此山王名，知之却百邪。","sortOrder":16},
  {"id":"s_work_nvlt_7_17","chapterId":"ch_work_nvlt_7","text":"袁山松宜都記曰：郡西北陆行四十里，有丹山，山間時有赤氣，籠蓋林嶺如丹色，因以名山。","sortOrder":17},
  {"id":"s_work_nvlt_7_18","chapterId":"ch_work_nvlt_7","text":"又曰：自西陵東北陆行百二十里，有方山，其嶺四方，素崖如壁，天清朗時，有黃影似人像，山上有神祠場，特生一竹，茂好，其摽垂場中，場中有尘埃，則風起動此竹，拂去如洒扫者。","sortOrder":18},
  {"id":"s_work_nvlt_7_19","chapterId":"ch_work_nvlt_7","text":"盛弘之《荆州記》曰：宜都西陵峡中，有黃牛山，江湍紆回，途經信宿，猶望見之，行者語曰：朝發黃牛，暮宿黃牛，三日三暮，黃牛如故。","sortOrder":19},
  {"id":"s_work_nvlt_7_20","chapterId":"ch_work_nvlt_7","text":"又曰：桂陽郡西南五十里，有萬歲山，有石室鍾乳，山上悉生靈寿木。","sortOrder":20},
  {"id":"s_work_nvlt_7_21","chapterId":"ch_work_nvlt_7","text":"又曰：武陵舞陽縣，有淳於白雉二山，在寧州武陵二界畔，絕壑之半，有一石雉，遠望首尾，可長二丈，申足翔翼，若虛中翻飛，頸缀著石。","sortOrder":21},
  {"id":"s_work_nvlt_7_22","chapterId":"ch_work_nvlt_7","text":"又曰：衡山有三峰極秀，一峰名紫蓋。","sortOrder":22},
  {"id":"s_work_nvlt_7_23","chapterId":"ch_work_nvlt_7","text":"又曰：宜都夷道縣西南九十里，有望州山，四面壁立，登此見一州內，東有涌泉，欲雨，辄有赤氣，故名丹水。","sortOrder":23},
  {"id":"s_work_nvlt_7_24","chapterId":"ch_work_nvlt_7","text":"又曰：宜都宜昌縣三峡七百里，兩岸連山，略無絕處，漁者歌曰：巴東三峡巫峡長。","sortOrder":24},
  {"id":"s_work_nvlt_7_25","chapterId":"ch_work_nvlt_7","text":"荆南圖製［當作副，本卷石篇引書有荆州圖副。］曰：宜都夷陵縣東六十里，南岸有荆門山，北有虎牙，二山相對，虎牙有石壁，其文黃赤。又似虎牙形，荆門山上合下空，有若門象。","sortOrder":25},
  {"id":"s_work_nvlt_7_26","chapterId":"ch_work_nvlt_7","text":"又曰：邓城西七里，有作樂山，諸葛亮常登此山，為梁甫吟。","sortOrder":26},
  {"id":"s_work_nvlt_7_27","chapterId":"ch_work_nvlt_7","text":"又曰：襄陽郡中庐縣西百三十里，有馬穴山，傍有一地道，雲漢時有馬出其中，［事具馬部。］","sortOrder":27},
  {"id":"s_work_nvlt_7_28","chapterId":"ch_work_nvlt_7","text":"又曰：宜都夷陵縣西八十里，有高筐山，古老相傳，尧時大水，此山不没，如筐篚，因以為名。","sortOrder":28},
  {"id":"s_work_nvlt_7_29","chapterId":"ch_work_nvlt_7","text":"又曰：巴東崑陽縣東南十里，有柏枝山，有石泉，口方數丈，中有魚。","sortOrder":29},
  {"id":"s_work_nvlt_7_30","chapterId":"ch_work_nvlt_7","text":"又曰：宜都夷道縣北，有女觀山，昔有思婦，登山絕望，懷思而死，葬之山顶，山遂枯悴，因以名山。","sortOrder":30},
  {"id":"s_work_nvlt_7_31","chapterId":"ch_work_nvlt_7","text":"庾仲雍湘中記曰：桂陽郴縣東北五里，有馬嶺山，高六百餘丈，蘇躭所栖遊處，因而得仙，後有見躭乘白馬，還此山中，世因名為馬嶺。","sortOrder":31},
  {"id":"s_work_nvlt_7_32","chapterId":"ch_work_nvlt_7","text":"《晏子春秋》曰：齊景公召群臣問曰：天不雨久矣，民有飢色，吾卜祟在高山廣泽，寡人欲祠靈山，可乎，《晏子》曰：夫靈山，因以石為身，以草木為毛發，天久不雨，發將焦，身將熱，獨不欲雨乎，祠之何益。","sortOrder":32},
  {"id":"s_work_nvlt_7_33","chapterId":"ch_work_nvlt_7","text":"《淮南子》曰：牛蹄之涔，無尺之鯉，頹府之山，無丈之材，所以然者何也，皆其營守狹小，而不能容巨大。","sortOrder":33},
  {"id":"s_work_nvlt_7_34","chapterId":"ch_work_nvlt_7","text":"《韓詩外傳》曰：仁者何以樂山，山者萬物之所瞻仰也，草木生焉，萬物殖焉，飛鳥集焉，走獸休焉，吐生萬物而不私焉，出雲导風，天地以成，國家以寧，此仁者所以樂山。","sortOrder":34},
  {"id":"s_work_nvlt_7_35","chapterId":"ch_work_nvlt_7","text":"張璠《漢記》曰：梁冀聚土筑山，十里九坂，以象二崤，窮極工巧，積金玉明珠，充牣其中。","sortOrder":35},
  {"id":"s_work_nvlt_7_36","chapterId":"ch_work_nvlt_7","text":"《相冢書》曰：青乌子稱，山望之如却月形，或如覆舟，葬之出富貴，山望之如雞栖，葬之滅門，山有重叠，望之如鼓吹樓，葬之連州二千石。","sortOrder":36},
  {"id":"s_work_nvlt_7_37","chapterId":"ch_work_nvlt_7","text":"《遊名山志》曰：玉溜山，一名地肺山，一名浮山。","sortOrder":37},
  {"id":"s_work_nvlt_7_38","chapterId":"ch_work_nvlt_7","text":"《魏志》曰：明帝鏨太行山之石英，采穀城之文石，起景陽山於芳林園。","sortOrder":38},
  {"id":"s_work_nvlt_7_39","chapterId":"ch_work_nvlt_7","text":"王韶之《始興記》曰：郡東有玉山，草木滋茂，泉石澄润。","sortOrder":39},
  {"id":"s_work_nvlt_7_40","chapterId":"ch_work_nvlt_7","text":"邓德明《南康記》曰：平固縣覆笥山，上有笥，貯玉牒記，故山因笥為名焉。","sortOrder":40},
  {"id":"s_work_nvlt_7_41","chapterId":"ch_work_nvlt_7","text":"【詩】晉庾闡登楚山詩曰：拂駕升西嶺，寓目臨浚波，想望七德耀，詠此九功歌，龍驷釋陽林，朝服集三河，回首盼宇宙，一無濟邦家。","sortOrder":41},
  {"id":"s_work_nvlt_7_42","chapterId":"ch_work_nvlt_7","text":"晉王凝之妻謝氏詩曰：瓘瓘東嶽高，秀極冲清天，巖中間虛宇，寂漠幽以玄，非工复非匠，雲構發自然，器象爾何物，遂令我屢遷，逝將宅斯宇，可以盡天年。","sortOrder":42},
  {"id":"s_work_nvlt_7_43","chapterId":"ch_work_nvlt_7","text":"宋孝武遊覆舟山詩曰：束發好怡衍，弱冠頗流薄，素想終勿傾，聿來果丘壑。曾峰亘天維，曠渚綿地絡，逢皋列神苑，遭壇树仙閣，松墱含青暉，荷源煜彤烁，川界泳遊鱗，巖庭响鳴鶴。","sortOrder":43},
  {"id":"s_work_nvlt_7_44","chapterId":"ch_work_nvlt_7","text":"又登作樂山詩曰：脩路軫孤辔，竦石頓飛轅，遂登千尋首，表里望丘原，屯煙扰風穴，積水漏雲根，漢潦吐新波，楚山帶舊苑，壤草凌故國，拱木秀頹垣，目極情無屆，客思空已繁。","sortOrder":44},
  {"id":"s_work_nvlt_7_45","chapterId":"ch_work_nvlt_7","text":"又登魯山詩曰：解帆憩通渚，息徒凭椒丘，粵值風景和，升高從遠眸，紀巠阝窮西路，湘夢極南流，杳哉漢陰水，浩焉江界脩，宋謝靈運往北山經湖中詩曰：石橫水分流，林密蹊絕蹤，初篁笣绿箨，新蒲合紫茸，海鷗戲春岸，天雞弄和風。","sortOrder":45},
  {"id":"s_work_nvlt_7_46","chapterId":"ch_work_nvlt_7","text":"宋宗炳登白鳥山詩曰：我徂白鳥山，因名感昔擬，仰升數百仞，俯覽眇千里，杲杲群木分，岌岌眾峦起。","sortOrder":46},
  {"id":"s_work_nvlt_7_47","chapterId":"ch_work_nvlt_7","text":"又登半石山詩曰：清晨陟阻崖，氣志洞萧洒，嶰穀崩地幽，窮石凌天委，長松列竦肅，萬树巉巖诡，上施神農萝，下凝尧時髓。","sortOrder":47},
  {"id":"s_work_nvlt_7_48","chapterId":"ch_work_nvlt_7","text":"齊謝朓和王著作登八公山詩曰：東限琅琊台，西距孟諸陆，阡眠起雜树，檀栾陰脩竹，日隱澜疑空，雲聚岫如複，出没眺樓雉，遠近送春目。","sortOrder":48},
  {"id":"s_work_nvlt_7_49","chapterId":"ch_work_nvlt_7","text":"又遊敬亭山詩曰：茲山亘百里，合沓與雲齊，上幹蔽白日，下屬帶回溪，交藤荒且蔓，樛枝耸复低，獨鶴方朝唳，飢鼯此夜啼，泄雲已漫漫，多雨亦凄凄。","sortOrder":49},
  {"id":"s_work_nvlt_7_50","chapterId":"ch_work_nvlt_7","text":"梁沈約遊金華山詩曰：遠策追夙心，靈山协久要，天倪臨紫闕，地道通丹竅。未乘琴高鯉，且縱嚴陵釣，若蒙羽駕迎，得奉金書召，高馳入閶阖，方睹靈妃笑。","sortOrder":50},
  {"id":"s_work_nvlt_7_51","chapterId":"ch_work_nvlt_7","text":"又留真人東山還詩曰：連峰竟無已，積翠遠微微，寥戾野風急，芸黃秋草肥，我來歲雲暮，於此怅懷歸，霜雪方共下，寧止露霑衣，待餘兩歧秀，去去掩柴扉。","sortOrder":51},
  {"id":"s_work_nvlt_7_52","chapterId":"ch_work_nvlt_7","text":"梁范雲登三山詩曰：仄迳崩且危，丛巖竦复垂，石藤多卷節，水树饒蟠枝，海中昔自重，江上今如斯。","sortOrder":52},
  {"id":"s_work_nvlt_7_53","chapterId":"ch_work_nvlt_7","text":"梁江淹歷山詩曰：愁生白露日，思起秋風年，竊悲杜蘅暮，攬涕即空山，落葉下楚水，別鶴噪吳田，嶂氣陰不極，日色半虧天，酒至情萧瑟，凭樽還悯然。","sortOrder":53},
  {"id":"s_work_nvlt_7_54","chapterId":"ch_work_nvlt_7","text":"又遊黃檗山詩曰：長望竟何極，閩雲連越邊，南州饒奇怪，赤縣多靈仙，金峰各虧日，銅石共臨天，陽岫沼鸞來，陰谿喷龍泉，雞鳴丹壁上，猿嘯青崖間。","sortOrder":54},
  {"id":"s_work_nvlt_7_55","chapterId":"ch_work_nvlt_7","text":"梁任昉奉和登影陽山詩曰：物色感神遊，升高怅有閱，南望銅扆街，北走長楸埒，別涧苑沧溟，疏山駕瀛碣，奔鯨吐華浪，司南動輕枻，日下重門照，雲關九華澈，觀閣隆舊恩，奉圖愧前哲。","sortOrder":55},
  {"id":"s_work_nvlt_7_56","chapterId":"ch_work_nvlt_7","text":"梁庾肩吾遊甑山詩曰：去子平已久，餘風今复追，未必遊春草，王孫自不歸，寒雲間石起，秋葉下山飛。","sortOrder":56},
  {"id":"s_work_nvlt_7_57","chapterId":"ch_work_nvlt_7","text":"周王襃明慶寺石壁詩曰：夏水懸台际，秋泉帶雨餘，石生銘字長，山久穀神虛。","sortOrder":57},
  {"id":"s_work_nvlt_7_58","chapterId":"ch_work_nvlt_7","text":"又雲居寺高顶詩曰：中峰雲已合，絕顶日猶晴，邑居隨望近，風煙對眼生。","sortOrder":58},
  {"id":"s_work_nvlt_7_59","chapterId":"ch_work_nvlt_7","text":"周庾信陪駕幸終南山詩曰：玉山乘四載，瑤池宴八龍，黿桥浮少海，鵠蓋上中峰，飛狐橫塞路，白馬當河冲，水奠三川後，山封五树松，長虹双瀑布，圓闕兩芙蓉，戍樓鳴夕鼓，山寺响晨鍾，新蒲節轉促，短筍箨猶重，树宿含櫻鳥，花留酿蜜蜂，迎風下列缺，酾酒召昌容，且欣陪北上，方欲待東封。","sortOrder":59},
  {"id":"s_work_nvlt_7_60","chapterId":"ch_work_nvlt_7","text":"陳張正見賦得山卦名詩曰：蓬萊遁羽客，巖穴轉蒙籠，雲歸仙井暗，霧解石桥通，影帶臨峰鶴，形隨雜雨風，尋師不失路，鹹欲馭飛鸿。","sortOrder":60},
  {"id":"s_work_nvlt_7_61","chapterId":"ch_work_nvlt_7","text":"【賦】魏劉楨黎陽山賦曰：自魏都而南邁，迄洪川以朅休，想王旅之旌旄，望南路之遐脩，御輕駕而西徂，過舊坞之高區，爾乃逾峻嶺，超連罡，一登九息，遂臻其陽，南荫黃河，左覆金城，青壇承祀，高碑頌靈，珍木骈羅，奋華扬榮，雲興風起，萧瑟清泠，延首南望，顧瞻舊乡，桑梓增敬，惨切懷傷，河源汩其東遊，陽鳥飄而南翔，睹眾物之集華，退欣欣而樂康。","sortOrder":61},
  {"id":"s_work_nvlt_7_62","chapterId":"ch_work_nvlt_7","text":"晉潘嶽登虎牢山賦曰：辭京輦兮遙邁，將遠遊兮東夏，朝發轫兮帝墉，夕結軌兮中野，凭脩坂兮停車，臨寒泉兮飲馬，眷故乡之遼隔，思紆軫以鬱陶，步玉趾以升降，凌汜水而登虎牢，覽河洛之二川，眺成平之双皋，崇嶺骉以崔崒，幽穀豁以窙寥，路逶迤以迫隘，林廓落以萧條，爾乃仰荫嘉木，俯藉芳卉，青煙鬱其相望，棟宇懍以鱗萃，彼登山而臨水，因先喆之所哀，矧去乡而離家，邈長辭而遠乖，望歸雲以叹息，腸一日而九回，良勞者之詠事，爰寄言以表懷。","sortOrder":62},
  {"id":"s_work_nvlt_7_63","chapterId":"ch_work_nvlt_7","text":"晉郭璞巫鹹山賦曰：蓋巫鹹者，實以鸿術，為帝尧医，生為上公，死為貴神。豈封斯山，而因以名之乎，伊巫鹹之名山，嚬孤停而嵥峙，體岑峭以隆頹，冠崇嶺以峻起，配華霍以助镇，致靈润乎百里，爾乃寒泉懸涌，浚湍流帶，林薄丛茏，幽蔚隱藹，八風之所歸起，遊鳥之所喧會，潛瑕石，楊蘭茝，回翔鵷集，凌鷮鹪翳，禽鳥遷陽以晨鳴，熊虎窟陰而夕〈口〉。","sortOrder":63},
  {"id":"s_work_nvlt_7_64","chapterId":"ch_work_nvlt_7","text":"梁江淹江上之山賦曰：桂青萝兮萬仞，竖丹石兮百重，百重兮嵒崿，如斫兮如削，波潮兮吐納，〈山其〉岸兮積沓，見紅草之交生，眺碧树之四合，草自然而千華，树無情而百色，嗟世道之異茲，牵忧患而來逼。","sortOrder":64},
  {"id":"s_work_nvlt_7_65","chapterId":"ch_work_nvlt_7","text":"梁吳均八公山賦曰：峻極之山，蓄聖表仙，南參差而望越，北逦迤而懷燕，爾其盤桓基固，含陽藏霧，絕壁崄巇，層巖回互，桂皎月而常团，雲望空而自布，袖以華阆，帶以潛淮，文星亂石，藻日流階，若夫神基巨镇，卓荦荆河，箕風畢雨，育嶺生瓘，高岑直兮蔽景，脩坂出兮架天，似迎雲而就日，若從漢而回山，露泫葉而原净，花照磯而岫鮮，促嶂萬尋，平崖亿絕，上被紫而煙生，傍帶花而來雪，維英王兮好仙，會八公兮小山，駕飛龍兮翩翩，高馳翔兮冲天。","sortOrder":65},
  {"id":"s_work_nvlt_7_66","chapterId":"ch_work_nvlt_7","text":"陳張正見山賦曰：何神山之峻美，谅苞結之所成，東垂曰泰，南服稱衡，西戎所擅，北狄摽名，於是尧值洪流，滔天襄陵，禹敷水土，奠高槎木，眾川既导，群嶽自脩，潛通四渎，镇壓九川，森羅辰象，吐吸雲霧，深不可测，遠不可步，於廓靈山，長為作固，爾其為状也，則武當太和，武功太白，崑崙五門，扶寧三石，峰高一萬，峭峙三百，登而眺之，則千里無極，俯而臨之，則萬仞難测，映白鶴而同高，混青天而共色。","sortOrder":66},
  {"id":"s_work_nvlt_7_67","chapterId":"ch_work_nvlt_7","text":"晉潘尼西［北堂書鈔一百四十一，一百五十七，《初學記》二十四作惡。］道賦曰：異山河之岨阨，倦關穀之盤紆，車低佪於潛軌，馬侘傺於险涂，狗肘還勾，羊角互戾，葂窟連投，十數亿計，石子之涧，坎埳之穴，支體為之危竦，形骸為之疲曳，此亦行者之艱難，羁旅之困毙，若其名坂，則羊羹八特，成皋黃馬，回波激浪，飛沙飄瓦，馬則頓踬狼傍，虺頹玄黃，牛則體疲力竭，損食丧膚，尳蹄穿領，摩髖脱軀。","sortOrder":67},
  {"id":"s_work_nvlt_7_68","chapterId":"ch_work_nvlt_7","text":"【吟】晉夏侯湛山路吟曰：夙駕兮待明，陟山路兮遐征，冒晨朝兮入大穀，道逶迤兮岚氣清，攬辔兮抑馬，踟蹰兮曠野，曠野〈骨區〉兮遼落，崇嶽兮嵬崿，丘陵兮連離，卉木兮交错，渌水兮長流，驚涛兮拂石。","sortOrder":68},
  {"id":"s_work_nvlt_7_69","chapterId":"ch_work_nvlt_7","text":"宋謝莊山夜忧曰：庭光盡，山明歸，流風乘軒卷，明月緣河飛，涧鳥鳴兮夜蝉清，橘露靡兮蕙煙輕，凌別浦兮值泉躍，經乔林兮遇猿驚，南皋別鶴佇行漢，東鄰孤管入青天，沉痾白發共急日，朝露過隙詎賒年，年去兮發不還，金膏玉液豈留顏，回舲拓繩戶，收棹掩荆關。","sortOrder":69},
  {"id":"s_work_nvlt_7_70","chapterId":"ch_work_nvlt_7","text":"【贊】晉庾肅之山贊曰：懸巖杳翳，神明攸居，官府風雲，懷吐川渠，崑阆天竦，五嶽雲停，飛峰紫蔚，辰秀太清。","sortOrder":70},
  {"id":"s_work_nvlt_7_71","chapterId":"ch_work_nvlt_7","text":"晉戴逵山贊曰：蔚矣名山，亭亭洪秀，併基二儀，峣嶕雲構，嵯峨積岨，寥籠虛岫，輕霞仰拂，神泉旁漱，曰仁奚樂，希靜此寿。","sortOrder":71},
  {"id":"s_work_nvlt_7_72","chapterId":"ch_work_nvlt_7","text":"晉郭璞《炎山贊》曰：木含陽氣，精構則燃，焚之無盡，是生火山，理見乎微，其妙在傳。","sortOrder":72},
  {"id":"s_work_nvlt_7_73","chapterId":"ch_work_nvlt_7","text":"【銘】晉張載劍閣銘曰：巖巖梁山，積石瓘瓘，遠屬荆衡，近缀岷嶓，南通邛僰，北達襃斜，狹過彭碣，高逾嵩華，惟蜀之門，作固作镇，是曰劍閣，壁立千仞，窮地之险，極路之峻，世濁則逆，道清斯順，閉由往漢，开自有晉，秦得百二，併吞諸侯，齊得十二，田生獻筹，矧茲狹隘，土之外區，一人荷戟，萬夫趑趄，形勝之地，非親勿居，昔在武侯，中流而喜，山河之固，見屈吳起，興實在德，险亦難恃，洞庭孟門，二國不祀，自古迄今，天命匪易，凭阻作昏，鮮不败績，公孫既滅，劉氏衔璧，覆車遺軌，岡或重跡，勒銘山阿，敢告梁益。","sortOrder":73},
  {"id":"s_work_nvlt_7_74","chapterId":"ch_work_nvlt_7","text":"晉湛方生靈秀山銘曰：巖巖靈秀，積岨幽重，傍嶺關岫，乘標挺峰，桂柏參幹。芝菊亂丛，翠雲夕映，爽氣晨蒙，籠籠疏林，穆穆閒房，幽室冬暄，清荫夏涼，神木奇生，靈草貞香，雲鮮其色，風飄其芳，可以養性，可以遷翔，長生久视，何必仙乡。","sortOrder":74},
  {"id":"s_work_nvlt_7_75","chapterId":"ch_work_nvlt_7","text":"梁簡文帝行雨山銘曰：巖畔途遠，阿曲路深，猶雲息馭，尚且抽琴，茲峰獨擅。嵚崎千变，却繞畫房，前臨寶殿，玉岫开華，紫水回斜，谿間聚葉，涧里萦沙，月映成水，人來當花，藤結如帷，碛起成基，芸香馥迳，石鏡臨墀。","sortOrder":75},
  {"id":"s_work_nvlt_7_76","chapterId":"ch_work_nvlt_7","text":"又明月山銘曰：迢遞峰長，威紆嶽聚，既正書門，兼同天柱，非競小山，寧論大庾，豈學土龍，詎須石鼓，緅色斜臨，霞文橫竖。","sortOrder":76},
  {"id":"s_work_nvlt_7_77","chapterId":"ch_work_nvlt_7","text":"梁孝元帝東宮後堂仙室山銘曰：太華削成，本擅奇聲，峰如雪委，嶺若莲生，雲除紫蓋，霞通赤城，金壇是箓，玉記題名，鳳依桐树，鶴聽琴聲，殿接南箕，桥連北斗，秋河徙帶，春禽衔綬，朱鳥安窗，青龍作牖。","sortOrder":77},
  {"id":"s_work_nvlt_7_78","chapterId":"ch_work_nvlt_7","text":"梁庾肩吾東宮玉帳山銘曰：玉帳寥廓，崑山抵鵲，總葉成帳，連枝起幕，玉蕊難徙，金花不落，隱士彈琴，仙人看博，巖留故鼎，竈聚新荆，煮石初烂，燒丹欲成，桑田屢盡，海水頻傾，長聞鳳曲，永聽箫聲。","sortOrder":78},
  {"id":"s_work_nvlt_7_79","chapterId":"ch_work_nvlt_7","text":"周庾信梁東宮行雨山銘曰：山名行雨，地異陽台，春人無數，神女羞來，翠幔朝开，新妆旦起，树入床前，山來鏡里，草色衫同，花紅面似，开年寒盡，正月春遊，天絲剧藕，蝶粉多尘，橫藤礙路，垂柳低人，誰論洛水，一个河神。","sortOrder":79},
  {"id":"s_work_nvlt_7_80","chapterId":"ch_work_nvlt_7","text":"陳徐陵後堂望美人山銘曰：高堂礙雨，洛浦無洲，何處相望，山邊一樓，峰因五婦，石是三侯，险逾地肺，危鄰天柱，禁苑斜通，春人恒聚，树里聞歌，枝中見舞，恰對妆台，諸窗併开，遙看已識，试唤便回，豈如織女，非秋不來。","sortOrder":80},
  {"id":"s_work_nvlt_7_81","chapterId":"ch_work_nvlt_7","text":"【碑】梁簡文帝神山碑銘曰：關號天井，山稱地雌，碧雞金馬，越渎梁池，懷靈缊德，孕寶含奇，此亦神岫，英名遠摛，昔有鷲窟，不燒净土，邁彼高蹤，構茲法宇，引葉成帷，即树為柱，石砌危橫，崖階斜竖。","sortOrder":81},
  {"id":"s_work_nvlt_7_82","chapterId":"ch_work_nvlt_7","text":"梁元帝玄圃牛渚磯碑曰：竊以增城九重，仙林八树，未有船如鳴鶴，時度宓妃，桥似牵牛，能分織女，丹鳳為群，紫柱成迾，清風韻响，即代歌仙，桂影浮池，仍為月浦，璧月朝暉，金樓啟扉，畫船向浦，錦纜牵磯，花飛拂袖，荷香入衣，山林朝市，併覺忘歸。","sortOrder":82},
  {"id":"s_work_nvlt_7_83","chapterId":"ch_work_nvlt_7","text":"【序】宋謝靈運名山序曰：夫衣食人生之所資，山水性分之所適，世識多雲，歡足本在華堂，枕巖嗽流者，之［《初學記》五作乏。］於大志，故保其枯槁，餘謂不然，君子有愛物之情，有救物之能，橫流之獘，非才不理，故時有屈己以濟彼，豈以名利之場，賢於清曠之域邪，語萬乘則鼎湖有縱辔，論储貳則嵩山有絕控。又陶朱高揖越相，留侯原辭漢傅，推此而言，可以明矣。","sortOrder":83},
  {"id":"s_work_nvlt_7_84","chapterId":"ch_work_nvlt_7","text":"【書】梁吳均與施從事書曰：故鄣縣東三十五里，有青山，絕壁幹天，孤峰入漢，緣［全梁文六十作绿。］嶂百重，青川萬轉，歸飛之鳥，千翼競來，企水之猿，百臂相接，秋露為霜，春萝被迳，風雨如晦，雞鳴不已，信足荡累颐物，悟衷散賞。","sortOrder":84},
  {"id":"s_work_nvlt_7_85","chapterId":"ch_work_nvlt_7","text":"又與朱元思書曰：風煙俱净，天山共色，從流飄荡，任意東西，自富陽至桐庐，一百許里，奇山異水，天下獨絕，水皆漂碧，千丈見底，遊魚細石，直视無礙，急湍甚箭，猛浪若奔，夹峰高山，皆生寒树，負势競上，互相軒邈，爭高直指，千百成峰，泉水激石，泠泠作响，好鳥相鳴，湋湋成韻，蝉則千轉不窮，猿則百叫無絕，烝飛戾天者，望峰息心，經纶世務者，窥穀忘反，橫柯上蔽，在晝猶昬，疏條交映，有時見日。","sortOrder":85},
  {"id":"s_work_nvlt_7_86","chapterId":"ch_work_nvlt_7","text":"◇崑崙山","sortOrder":86},
  {"id":"s_work_nvlt_7_87","chapterId":"ch_work_nvlt_7","text":"《河圖》曰：崑崙之墟，五城十二樓，河水出焉。","sortOrder":87},
  {"id":"s_work_nvlt_7_88","chapterId":"ch_work_nvlt_7","text":"《龍魚河圖》曰：崑崙山，天中柱也。","sortOrder":88},
  {"id":"s_work_nvlt_7_89","chapterId":"ch_work_nvlt_7","text":"大荒西經曰：赤水之後，黑水之前，有大山，名曰崑崙之丘，有神，人面虎身，有尾。","sortOrder":89},
  {"id":"s_work_nvlt_7_90","chapterId":"ch_work_nvlt_7","text":"《爾雅》曰：西北之美者，有崑崙之墟，璆琳琅玕焉。","sortOrder":90},
  {"id":"s_work_nvlt_7_91","chapterId":"ch_work_nvlt_7","text":"《穆天子傳》曰：天子遂宿於崑崙之阿，赤水之陽，吉日辛酉，天子升於崑崙之丘，以觀黃帝之宮，紀年曰：周穆王十七年，西征至崑崙丘，見西王母，王母止之。","sortOrder":91},
  {"id":"s_work_nvlt_7_92","chapterId":"ch_work_nvlt_7","text":"《神異經》曰：崑崙有銅柱焉，其高入天，所謂天柱也，围三千里，圓周如削，銅柱下有回屋焉，辟方百丈，［事具仙部。］","sortOrder":92},
  {"id":"s_work_nvlt_7_93","chapterId":"ch_work_nvlt_7","text":"《史記》曰：禹本紀，言河出崑崙，崑崙甚高，三千五百餘里，日月所相避隱為光明也，其上醴泉華池，自張騫使大夏之後，窮河源，惡睹本紀所謂崑崙者乎。","sortOrder":93},
  {"id":"s_work_nvlt_7_94","chapterId":"ch_work_nvlt_7","text":"水經曰：崑崙墟在西北，去嵩高五萬里，地之中也，其高萬一千里，河水出其東北陬。","sortOrder":94},
  {"id":"s_work_nvlt_7_95","chapterId":"ch_work_nvlt_7","text":"《博物志》曰：崑崙從廣萬一千里，神物之所生，聖人神仙之所集，五色雲氣，五色之流水，其泉東南流入中國，名為河也。","sortOrder":95},
  {"id":"s_work_nvlt_7_96","chapterId":"ch_work_nvlt_7","text":"葛仙公傳曰：崑崙，一曰玄圃，一曰積石瑤房，一曰阆風台，一曰華蓋，一曰天柱，皆仙人所居也。","sortOrder":96},
  {"id":"s_work_nvlt_7_97","chapterId":"ch_work_nvlt_7","text":"《搜神記》曰：崑崙之山，地首也，是惟帝之下都，故其外絕以弱水之深。又環以炎火之山，山上有鳥獸草木，皆生育滋茂於炎火之中，故有火澣布，非此山之皮枲，則其鳥獸之毛也。","sortOrder":97},
  {"id":"s_work_nvlt_7_98","chapterId":"ch_work_nvlt_7","text":"【贊】晉郭璞崑崙丘贊曰：崑崙月精，水之靈府，惟帝下都，西羌之宇，嵥然中峙，號曰天柱。","sortOrder":98},
  {"id":"s_work_nvlt_7_99","chapterId":"ch_work_nvlt_7","text":"◇嵩高山","sortOrder":99},
  {"id":"s_work_nvlt_7_100","chapterId":"ch_work_nvlt_7","text":"《山海經》曰：太室之中山，其上有木焉，葉状如梨而赤理，而名曰指，服者不垢。","sortOrder":100},
  {"id":"s_work_nvlt_7_101","chapterId":"ch_work_nvlt_7","text":"《毛詩》曰：崧高惟嶽，峻極於天，維嶽降神，生甫及申。","sortOrder":101},
  {"id":"s_work_nvlt_7_102","chapterId":"ch_work_nvlt_7","text":"《列仙傳》曰：王子乔，周靈王太子晉也，好吹笙作鳳鳴，遊伊雒間，道士浮丘公接上嵩高山。","sortOrder":102},
  {"id":"s_work_nvlt_7_103","chapterId":"ch_work_nvlt_7","text":"《漢武帝內傳》曰：武帝夜夢與李少君俱上嵩高山，上半道，有繡衣使者，乘龍持節，從雲中下，言太一君召，覺，即告近臣曰：如朕夢，少君將舍朕去矣。","sortOrder":103},
  {"id":"s_work_nvlt_7_104","chapterId":"ch_work_nvlt_7","text":"《劉根別傳》曰：根弃世學道，入中嶽嵩山石室中，峥嵘上，東南下五十丈，北人冬夏不衣，身毛皆長一二尺，顏状如年十五時。","sortOrder":104},
  {"id":"s_work_nvlt_7_105","chapterId":"ch_work_nvlt_7","text":"《仙經》雲，嵩高山東南大巖下石孔，方圓一丈，西方北入五六里，有大室，高三十餘丈，周圓三百步，自然明燭，相見如日月無異，中有十六仙人，雲月光童子，常在天台，時亦往來此中，人非有道，不得望見。","sortOrder":105},
  {"id":"s_work_nvlt_7_106","chapterId":"ch_work_nvlt_7","text":"戴延之《西征記》曰：嵩高山，巖中也，東謂太室，西謂少室，相去七十里，嵩高，總名也。","sortOrder":106},
  {"id":"s_work_nvlt_7_107","chapterId":"ch_work_nvlt_7","text":"《世記》［《初學記》五，《太平御覽》三九作劉義慶《世說》：按亦見幽明錄，(古小說鉤沉謂唐宋類書引幽明錄，時亦題《世說》：是也。)］曰：嵩高山北有大穴，莫测其深，百姓歲時每遊觀其上。晉初，嘗有一人誤墮穴中，同辈冀其傥不死，乃投食於穴中，墜者得之，為尋穴而行，計可十許日，忽曠然見明。又有草屋，中有二人，對坐围棋。局下有一杯白飲，墜者告以飢渴，棋者曰：可飲此。墜者飲之，氣力十倍。半年許，乃出於蜀中，歸洛下，問張華，華曰：此仙馆大夫，所飲者玉漿也。","sortOrder":107},
  {"id":"s_work_nvlt_7_108","chapterId":"ch_work_nvlt_7","text":"《俗說》曰：傅亮北征，在黃河中，垂至洛，遙見嵩高山，於時同從客在坐，問傅曰：潘安仁懷舊賦雲，前瞻太室，傍眺嵩丘，嵩丘太室，故是一山，何以言傍眺，傅曰：有嵩丘山，去太室七十里，此是書寫誤耳。","sortOrder":108},
  {"id":"s_work_nvlt_7_109","chapterId":"ch_work_nvlt_7","text":"【贊】晉郭璞太室山贊曰：嵩惟嶽宗，華岱恒衡，氣通元漠，神洞幽明，嵬然中立，眾山之英。","sortOrder":109},
  {"id":"s_work_nvlt_7_110","chapterId":"ch_work_nvlt_7","text":"◇華山","sortOrder":110},
  {"id":"s_work_nvlt_7_111","chapterId":"ch_work_nvlt_7","text":"《爾雅》曰：華山為西嶽。","sortOrder":111},
  {"id":"s_work_nvlt_7_112","chapterId":"ch_work_nvlt_7","text":"《西山經》曰：太華之山，削成而四方，其高五千仞，其廣十里。","sortOrder":112},
  {"id":"s_work_nvlt_7_113","chapterId":"ch_work_nvlt_7","text":"《晏子》曰：君子若華山然，松柏既多矣，望之盡日不知厭。","sortOrder":113},
  {"id":"s_work_nvlt_7_114","chapterId":"ch_work_nvlt_7","text":"《列仙傳》曰：脩羊公者，魏人，止華陰山石室中，中有石榻，常臥其上，石盡陷穿。","sortOrder":114},
  {"id":"s_work_nvlt_7_115","chapterId":"ch_work_nvlt_7","text":"又曰：呼子先者，漢中關下卜師，寿百餘歲，臨去，呼酒家嫗，令急裝，便有仙人，持二茅狗來至，子先持一與酒嫗，因各騎之，乃龍也，上華陰山，常於山大呼，言子先酒母在此。","sortOrder":115},
  {"id":"s_work_nvlt_7_116","chapterId":"ch_work_nvlt_7","text":"《華山記》曰：華山高巖四合，重嶺秀起，上有石池，北有石鼓，父老相傳雲，嘗有聞其鳴者。","sortOrder":116},
  {"id":"s_work_nvlt_7_117","chapterId":"ch_work_nvlt_7","text":"《述征記》曰：華山對河東首陽山，黃河流於二山之間，雲本一山，巨靈所开，今睹手跡於華嶽，而腳跡在首陽山下。","sortOrder":117},
  {"id":"s_work_nvlt_7_118","chapterId":"ch_work_nvlt_7","text":"【贊】晉郭璞華山贊曰：華嶽靈峻，削成四方，爰有神女，是挹玉漿，其誰遊之，龍駕雲裳。","sortOrder":118},
  {"id":"s_work_nvlt_7_119","chapterId":"ch_work_nvlt_7","text":"【銘】晉傅玄華嶽銘序曰：易稱法象莫大乎天地，天以高明崇顯，而嶽配焉，地以廣厚為基，而嶽體焉，若夫太華之為镇也，五嶽列位而存其首，三條分方而處其中，故能參兩儀以比德，协和氣之絪缊，故雲行與雨施，興雷風以動物，是以古先歷代聖帝明王，莫不燔柴加牲，尊而祀焉，於虞書，則西巡狩至於西嶽，而親祭焉，於禮，則大司馬掌其分域，而大宗伯典其禮祀也。","sortOrder":119},
  {"id":"s_work_nvlt_7_120","chapterId":"ch_work_nvlt_7","text":"【碑】後漢張昶西嶽華山堂闕碑序曰：易曰：天地定位，山泽通氣，然山莫尊於嶽，泽莫盛於渎，嶽有五而華處其一，渎有四而河在其數，其靈也至矣，人主废興，必有其應，故岱山石立，中宗繼統，太華授璧，秦胡絕緒，白魚入舟，姬武建業，寶珪出水，子朝丧位，布五方則處其西，列三條則居其中，世宗又經集靈之宮於其下，想松乔之儔，是遊是憩，郡國方士，自遠而至者，充巖塞崖，乡邑巫覡，宗祝乎其中者，亦盈穀溢蛇奚，鹹有浮飄之志，愉悅之色，必雲霄之路可升而越，果繁昌之福可降而致也，故殖财之寶，黃玉自出，令德之珍，卿相是毓，匪惟嵩高，降生申甫，斯亦有焉。","sortOrder":120},
  {"id":"s_work_nvlt_7_121","chapterId":"ch_work_nvlt_7","text":"◇衡山","sortOrder":121},
  {"id":"s_work_nvlt_7_122","chapterId":"ch_work_nvlt_7","text":"《周官》曰：荆州之镇山曰衡山。","sortOrder":122},
  {"id":"s_work_nvlt_7_123","chapterId":"ch_work_nvlt_7","text":"《湘中記》曰：衡山九疑，皆有舜廟，遙望衡山，如陣雲，沿湘千里，九向九背，乃不复見。","sortOrder":123},
  {"id":"s_work_nvlt_7_124","chapterId":"ch_work_nvlt_7","text":"又曰：南陽劉道人，嘗遊衡山，行數十里，有絕穀，不得前，遙望見三石囷，二囷閉，一囷开，盛弘之《荆州記》曰：衡山有三峰極秀，一峰名芙蓉峰，最為竦桀，自非清霁素朝，不可望見，峰上有泉飛派，如一幅絹，分映青林，直註山下。","sortOrder":124},
  {"id":"s_work_nvlt_7_125","chapterId":"ch_work_nvlt_7","text":"《異苑》曰：湘東姚祖，太元末為郡吏，經衡山，望巖下有數年少，併執筆作書，祖謂是行侣休息，乃枉道過之，未至百許步，少年相與翻然飛颺。","sortOrder":125},
  {"id":"s_work_nvlt_7_126","chapterId":"ch_work_nvlt_7","text":"【詩】晉庾闡詩曰：北眺衡山首，南睨五嶺末，寂坐挹虛恬，運目情四豁，翔亂凌九宵，陆鱗困濡沫，既體江湖悠，安識南溟闊。","sortOrder":126},
  {"id":"s_work_nvlt_7_127","chapterId":"ch_work_nvlt_7","text":"◇庐山","sortOrder":127},
  {"id":"s_work_nvlt_7_128","chapterId":"ch_work_nvlt_7","text":"《山海經》曰：庐山名有二，一曰天子都，二曰天子鄣。","sortOrder":128},
  {"id":"s_work_nvlt_7_129","chapterId":"ch_work_nvlt_7","text":"伏滔《遊庐山序》曰：庐山者，江陽之名嶽，其大形也，背岷流，面彭蠡，蟠根所據，亘數百里，重嶺桀嶂，仰插雲日，俯瞰川湖之流焉。","sortOrder":129},
  {"id":"s_work_nvlt_7_130","chapterId":"ch_work_nvlt_7","text":"遠法師庐山記曰：東南有香爐山，孤峰秀起，遊氣籠其上，則棼氲若煙。","sortOrder":130},
  {"id":"s_work_nvlt_7_131","chapterId":"ch_work_nvlt_7","text":"《神仙傳》曰：董奉還豫章，庐山下居，在山間，了不佃作，為人治病，亦不取錢物，使病愈者，种杏五株。","sortOrder":131},
  {"id":"s_work_nvlt_7_132","chapterId":"ch_work_nvlt_7","text":"張野庐山記曰：庐山，天將雨，則有白雲，或冠峰巖，或亘中嶺，俗謂之山帶，不出三日必雨。","sortOrder":132},
  {"id":"s_work_nvlt_7_133","chapterId":"ch_work_nvlt_7","text":"周景式庐山記曰：匡俗，周威［《太平御覽》四十一引張僧鑒尋陽記作武。］王時，生而神靈，庐於此山，世稱庐君，故山取號焉。","sortOrder":133},
  {"id":"s_work_nvlt_7_134","chapterId":"ch_work_nvlt_7","text":"又曰：登庐山，望九江，以觀禹之跡，其茲峰乎，東南隱諸嶺，不得骈矚，自庐山人跡所暨，迥望處無复出此者。又甚高峻，每雨，其下成潦，而上猶皎日，峰頭有大盤石，可坐數百人。","sortOrder":134},
  {"id":"s_work_nvlt_7_135","chapterId":"ch_work_nvlt_7","text":"【詩】宋謝靈運登庐山絕顶望諸峤詩曰：積峡忽复啟，平涂俄已閉，峦隴有合沓，往來無蹤轍，晝夜蔽日月，冬夏共霜雪。","sortOrder":135},
  {"id":"s_work_nvlt_7_136","chapterId":"ch_work_nvlt_7","text":"宋鮑昭［按當作照，後同。］登庐山詩曰：懸裝亂水區，旅薄次山楹，千巖状岨積，萬壑势回萦，巃鹢高昔貌，紛亂袭前名，洞涧窥地脈，竦树隱天經，松磴上迷密，雲窦下縱橫，陰冰實夏結，炎树信冬榮。","sortOrder":136},
  {"id":"s_work_nvlt_7_137","chapterId":"ch_work_nvlt_7","text":"又登庐山望石門詩曰：明發振雲冠，升峤遠栖趾，高峰隔半天，長崖斷千里，雞鳴青涧中，猿嘯白雲里，瑤波逐穴开，霞石觸峰起，回互非一形，參差悉相似。","sortOrder":137},
  {"id":"s_work_nvlt_7_138","chapterId":"ch_work_nvlt_7","text":"梁江淹登庐山香爐峰詩曰：絳氣下萦薄，白雲上杳冥，中坐瞰蜿虹，俯伏视流星，日落長沙渚，曾陰萬里生，藉蘭素多意，臨風默含情。","sortOrder":138},
  {"id":"s_work_nvlt_7_139","chapterId":"ch_work_nvlt_7","text":"【賦】宋支曇諦庐山賦曰：昔哉壮麗，峻極氤氲，包靈奇以藏器，蘊絕峰乎青雲，景澄則巖岫开鏡，風生則芳林流芬，嶺奇故神明鱗萃，路絕故人跡自分，嚴清升山於玄崖，世高垂化於共阝亭，應真陵雲以踞峰，眇忽翳景而入冥，鹹豫聞其清尘，妙無得之稱名也，若其南面巍崛，北背〈辶苕〉蒂，懸霤分流以飛湍，七嶺重氵急而叠势，映以竹柏，蔚以柽松，萦以三湖，帶以九江，嗟四物之萧森，爽獨秀於玄冬，美二流之潺湲，津百川之所冲，峭門百尋，峻闕千仞，香爐吐雲以像煙，甘泉涌霤而先润。","sortOrder":139},
  {"id":"s_work_nvlt_7_140","chapterId":"ch_work_nvlt_7","text":"【碑】梁元帝庐山碑序曰：夫日月麗天，皇穹所以貞觀，川嶽帶地，後土所以惟寧，庐山者，亦南國之德镇，雖林石異势，而雲霞共色，長風夜作，則萬流俱响，晨鼯晓吟，則百嶺齊應，東瞻洪井，識曳帛之在茲，西望石梁，見指寶之可拾，誠复慕類易悲，山中難久，攀萝結桂，多見淹留。","sortOrder":140},
  {"id":"s_work_nvlt_7_141","chapterId":"ch_work_nvlt_7","text":"◇太行山","sortOrder":141},
  {"id":"s_work_nvlt_7_142","chapterId":"ch_work_nvlt_7","text":"《山海經》曰：太行山，其首曰歸山，其上有金玉，下有碧玉。","sortOrder":142},
  {"id":"s_work_nvlt_7_143","chapterId":"ch_work_nvlt_7","text":"《穆天子傳》曰：天子命駕八駿之乘，赤骥之驷，南征翔行，迳絕翟道，升於太行，南濟於河。","sortOrder":143},
  {"id":"s_work_nvlt_7_144","chapterId":"ch_work_nvlt_7","text":"《墨子》曰：墨子請耕桂嶺子［墨子耕柱篇作墨子怒耕柱子，嶺字衍，(疑類聚據本怒作請，請嶺音近，故致衍，若作怒，則音相距遠矣，請問也，見國語吳語註，呂氏春秋首時註。)］曰：將上太行，駕骥與牛，子將誰驅，曰：將驅骥，以骥足貴［耕柱篇及《太平御覽》四十作责。］也。","sortOrder":144},
  {"id":"s_work_nvlt_7_145","chapterId":"ch_work_nvlt_7","text":"《尸子》曰：龍門，魚之難也，太行，牛之難也，以德報怨，人之難也。","sortOrder":145},
  {"id":"s_work_nvlt_7_146","chapterId":"ch_work_nvlt_7","text":"《戰國策》曰：范睢說秦王曰：舉兵攻滎陽，則成皋之路不通，北巉太行之道，則上党之兵不下，王舉兵而攻滎陽，則其國斷為三。","sortOrder":146},
  {"id":"s_work_nvlt_7_147","chapterId":"ch_work_nvlt_7","text":"《神仙傳》曰：王烈入太行山，忽聞山東北雷聲，往视，見山上破數百丈，石中有一孔，径尺，中有青泥流出，烈取摶之，隨手堅凝，氣味如粳米飲。","sortOrder":147},
  {"id":"s_work_nvlt_7_148","chapterId":"ch_work_nvlt_7","text":"【詩】晉袁宏從征行方山頭詩曰：峨瓘太行，凌虛抗势，天嶺交氣，窈然無际，澄流入神，玄穀應契，四象悟心，幽人來憩。","sortOrder":148},
  {"id":"s_work_nvlt_7_149","chapterId":"ch_work_nvlt_7","text":"◇荆山","sortOrder":149},
  {"id":"s_work_nvlt_7_150","chapterId":"ch_work_nvlt_7","text":"《山海經》曰：荆山，其陰多鐵，其陽多赤金。","sortOrder":150},
  {"id":"s_work_nvlt_7_151","chapterId":"ch_work_nvlt_7","text":"《河圖括地象》曰：荆山為地雌，上為軒轅星。","sortOrder":151},
  {"id":"s_work_nvlt_7_152","chapterId":"ch_work_nvlt_7","text":"《韓子》曰：卞和得玉於楚山中，獻厲王，王使玉人相之，曰：石也，刖其左足，和抱其璞，哭於荆山之下，三日，泣盡繼之以血，［事具玉門。］","sortOrder":152},
  {"id":"s_work_nvlt_7_153","chapterId":"ch_work_nvlt_7","text":"《水經》曰：荆山在南郡臨沮縣東北。","sortOrder":153},
  {"id":"s_work_nvlt_7_154","chapterId":"ch_work_nvlt_7","text":"【詩】晉桓玄登荆山詩曰：理不孤湛，影比有津，曾是名嶽，明秀超鄰，器遷荒外，命契响神，我之懷矣，巾駕飛輪。","sortOrder":154},
  {"id":"s_work_nvlt_7_155","chapterId":"ch_work_nvlt_7","text":"梁江淹望荆山詩曰：奉詔至江漢，始知楚塞長，南關繞桐柏，西嶽出魯陽，寒郊無留影，秋日懸清光，悲風繞重林，雲霞肅川涨，歲晏君如何，零淚染衣裳。","sortOrder":155},
  {"id":"s_work_nvlt_7_156","chapterId":"ch_work_nvlt_7","text":"◇鍾山","sortOrder":156},
  {"id":"s_work_nvlt_7_157","chapterId":"ch_work_nvlt_7","text":"徐爰釋門［《太平御覽》四十一作問。］略曰：建康北十餘里，有鍾山，舊名金山，漢末，金陵尉蒋子文，讨賊戰亡，靈發於山，因立蒋侯祠，故世號曰蒋山。","sortOrder":157},
  {"id":"s_work_nvlt_7_158","chapterId":"ch_work_nvlt_7","text":"庾闡楊都賦註曰：建康宮北十里，有蒋山，舆地圖謂之鍾山，元皇帝未渡江之年，望氣者雲，蒋山上有紫雲，時時晨見。","sortOrder":158},
  {"id":"s_work_nvlt_7_159","chapterId":"ch_work_nvlt_7","text":"山謙之《丹陽記》曰：京師南北，併有連嶺，而蒋山獨隆嚬峻異，其形象龍，實楊都之镇也，孫權葬山南，因山為名，號曰蒋陵。","sortOrder":159},
  {"id":"s_work_nvlt_7_160","chapterId":"ch_work_nvlt_7","text":"沈約《宋書》曰：萧思話領左衛，嘗從太祖登鍾山北嶺，石上彈琴，因賜以銀鍾酒，［事具琴部。］","sortOrder":160},
  {"id":"s_work_nvlt_7_161","chapterId":"ch_work_nvlt_7","text":"【詩】梁沈約遊鍾山詩曰：靈山紀地德，地险資嶽靈，終南表秦馆，少室邇王城，北阜何其峻，林薄杳葱青，發地多奇嶺，幹雲非一状，合沓共隱天，參差分相望，鬱律構丹巘，崚嶒起青嶂，即事既多美，臨眺殊复奇，南矚储胥觀，西望崑明池，山中鹹可悅，賞逐四時移，春光發隴首，秋風生桂枝，多值息心侣，結架山之足，八解鳴涧流，四禪隱巖曲。","sortOrder":161},
  {"id":"s_work_nvlt_7_162","chapterId":"ch_work_nvlt_7","text":"梁虞騫登鍾山下峰望詩曰：冠者五六人，携手巖之际，散意百仞端，極目千里睇，叠岫乍昏明，浮雲時卷閉，遙看野树短，遠望樵人細。","sortOrder":162},
  {"id":"s_work_nvlt_7_163","chapterId":"ch_work_nvlt_7","text":"◇北邙山","sortOrder":163},
  {"id":"s_work_nvlt_7_164","chapterId":"ch_work_nvlt_7","text":"《魏志》曰：明帝即位，欲平北芒，令登台觀見孟津，廷尉辛毗諫曰：天地之性，高高下下，今而反之，既非其理，加以損費人功，民不堪役，且若九河盛溢，洪水為害，而丘陵皆夷，何以御之，帝乃止。","sortOrder":164},
  {"id":"s_work_nvlt_7_165","chapterId":"ch_work_nvlt_7","text":"朱超石與兄書曰：登北芒遠眺，眾美都盡，光武墳邊杏甚美，今奉送核。","sortOrder":165},
  {"id":"s_work_nvlt_7_166","chapterId":"ch_work_nvlt_7","text":"【詩】魏劉伶北芒客舍詩曰：泱漭望舒隱，黮黤玄夜陰，寒雞思天曙，擁翅吹長音，蚊蚋歸丰草，枯葉散萧林，陳醴發悴顏，巴歈畅真心，缊被終不晓，斯叹信難任，何以除斯叹，付之與瑟琴，長笛响中夕，聞此消焜衿。","sortOrder":166},
  {"id":"s_work_nvlt_7_167","chapterId":"ch_work_nvlt_7","text":"【賦】晉張协登北芒賦曰：陟峦丘之〈山麗〉岮，升逶迤之脩岅，回餘車於峻嶺。聊送目於四遠，靈嶽鬱以造天，連岗巖以蹇產，伊洛混而東流，帝居赫以崇顯，山川汨其常弓，萬物化而代轉，何天地之難窮，悼人生之危淺，叹白日之西頹兮，哀世路之多蹇，於是徘徊絕嶺，踟蹰步趾，前瞻狼山，却闚大岯，東眺虎牢，西睨熊耳，邪亘天际，旁極萬里，莽眩眼以芒昧，谅群形之難紀，臨千仞而俯看，似遊身於雲霓，撫長風以延佇，想凌天而舉翮，瞻冠蓋之悠悠，睹商旅之接枙，爾乃地势窊隆，丘墟陂紘，墳隴嵔叠，基布星羅，松林摻映以攒列，玄木搜寥而振柯，壮漢氏之所營，望五陵之嵬瓘，丧亂起而啟壤，僮竖登而作歌。","sortOrder":167},
  {"id":"s_work_nvlt_7_168","chapterId":"ch_work_nvlt_7","text":"◇天台山","sortOrder":168},
  {"id":"s_work_nvlt_7_169","chapterId":"ch_work_nvlt_7","text":"名山略記曰：天台山在剡縣，即是眾聖所降，葛仙公山也。","sortOrder":169},
  {"id":"s_work_nvlt_7_170","chapterId":"ch_work_nvlt_7","text":"《異苑》曰：會稽天台山，雖非遐遠，自非忘生忘形，不能跻也。","sortOrder":170},
  {"id":"s_work_nvlt_7_171","chapterId":"ch_work_nvlt_7","text":"《幽明錄》曰：漢帝永平五年，剡縣劉晨阮肇，共入天台山，度山，出一大溪，溪邊有二女子，姿质妙絕，遂留半年，懷土思求歸，既出，親舊零落，邑屋改異，無复相識，訊問得七世孫。","sortOrder":171},
  {"id":"s_work_nvlt_7_172","chapterId":"ch_work_nvlt_7","text":"孔靈符會稽記曰：赤城山內，則有天台靈嶽，玉室璿台。","sortOrder":172},
  {"id":"s_work_nvlt_7_173","chapterId":"ch_work_nvlt_7","text":"【賦】晉孫綽遊天台山賦序曰：天台山者，蓋山嶽之神秀者也，涉海則有方丈蓬萊，登陆則有四明天台，皆玄聖之所遊化，靈仙之所窟宅，夫其峻極之状，嘉祥之美，窮山海之朅富，盡人神之壮麗矣，所以不列於五嶽，闕載於常典者，豈不以其所立冥奧，其路幽迥，或倒景於重溟，或匿峰於千嶺，始經魑魅之涂，卒踐無人之境，舉世罕能登陟，王者莫由禋祀，理無隱而不彰，啟二奇以示兆，赤城霞起而建標，瀑布飛流以界道。","sortOrder":173},
  {"id":"s_work_nvlt_7_174","chapterId":"ch_work_nvlt_7","text":"◇首陽山","sortOrder":174},
  {"id":"s_work_nvlt_7_175","chapterId":"ch_work_nvlt_7","text":"《毛詩》曰：采苓采苓，首陽之巔。","sortOrder":175},
  {"id":"s_work_nvlt_7_176","chapterId":"ch_work_nvlt_7","text":"《論語》曰：伯夷叔齊，饿於首陽之下。","sortOrder":176},
  {"id":"s_work_nvlt_7_177","chapterId":"ch_work_nvlt_7","text":"《史記》：伯夷叔齊，孤竹君之二子，讓國逃去，隱於首陽山，采薇而食之，遂饿死首陽山，［事具讓部。］","sortOrder":177},
  {"id":"s_work_nvlt_7_178","chapterId":"ch_work_nvlt_7","text":"【詩】魏阮籍詩曰：步出上東門，遙望首陽岑，下有采薇士，上有嘉树林。","sortOrder":178},
  {"id":"s_work_nvlt_7_179","chapterId":"ch_work_nvlt_7","text":"【賦】漢杜篤首陽山賦曰：嗟首陽之孤嶺，形势窟其槃曲，面河源而抗巖隴。堆隈而相屬，長松落落，卉木蒙蒙，青羅落漠而上覆，穴溜滴瀝而下通，高岫帶乎巖侧，洞房隱於雲中，忽吾睹兮二老，時采薇以從容，於是乎，乃訊其所求，問其所脩，州域乡党，親戚疋儔，何務何樂，而併茲遊矣，其二老乃答餘曰：吾殷之遺民也，厥胤孤竹，作蕃北湄，少名叔齊，長曰伯夷，聞西伯昌之善〈求殳〉，［明本作教。］育年艾於胡耇，遂相携而隨之，冀寄命乎餘寿，而天命之不常，伊事变而無方，昌伏事而畢命，子忽遘其不祥，乃興師於牧野，遂幹戈以伐商，乃弃之而來遊，擔［明本作誓。］不步於其乡，餘閉口而不食，併卒命於山傍。","sortOrder":179},
  {"id":"s_work_nvlt_7_180","chapterId":"ch_work_nvlt_7","text":"◇燕然山","sortOrder":180},
  {"id":"s_work_nvlt_7_181","chapterId":"ch_work_nvlt_7","text":"漢書匈奴傳曰：貳師引兵還，至燕然山，单於知漢軍勞倦，自將五萬騎遮击，貳師軍大亂败，貳師降单於。","sortOrder":181},
  {"id":"s_work_nvlt_7_182","chapterId":"ch_work_nvlt_7","text":"【銘】後漢班固燕然山銘曰：勒以八陣，莅以威神，玄甲耀日，朱旗絳天，遂陵高闕，下雞鹿，經碛滷，絕大漠，斬溫禺以亹鼓，血尸逐以染鍔，然後四校橫徂，星流彗扫，萧條萬里，野無遺寇，於是城滅區殫，反旆而旋，鑠王師兮征荒裔，剿凶虐兮截海外，敻其邈兮亘地界，封神丘兮建隆嵑，熙帝載兮振萬世。","sortOrder":182},
  {"id":"s_work_nvlt_7_183","chapterId":"ch_work_nvlt_7","text":"◇羅浮山","sortOrder":183},
  {"id":"s_work_nvlt_7_184","chapterId":"ch_work_nvlt_7","text":"茅君內傳曰：大天之內，有地中之洞天三十六所，羅浮山之洞，周回五百里。名曰朱明曜真之天。","sortOrder":184},
  {"id":"s_work_nvlt_7_185","chapterId":"ch_work_nvlt_7","text":"袁彦伯羅浮山疏曰：遙望石樓直上，當十餘里許，石樓之於山顶，十分之一耳，去縣三十里，便見山基，至所登處，當百里許，山皆平敞極目。","sortOrder":185},
  {"id":"s_work_nvlt_7_186","chapterId":"ch_work_nvlt_7","text":"《羅浮山記》曰：羅浮者，蓋總稱焉，羅，羅山也，浮，浮山也，二山合體，謂之羅浮，在增城博羅二縣之境，舊說，羅浮高三千丈，有七十石室，七十二長溪，神明神禽，玉树朱草。","sortOrder":186},
  {"id":"s_work_nvlt_7_187","chapterId":"ch_work_nvlt_7","text":"【詩】宋王叔之遊羅浮山詩曰：菴藹靈嶽，开景神封，綿界盤趾，中天舉峰，孤樓侧挺，增岫回重，風雲秀體，卉木媚容。","sortOrder":187},
  {"id":"s_work_nvlt_7_188","chapterId":"ch_work_nvlt_7","text":"【賦】宋謝靈運羅浮山賦曰：客夜夢見延陵茅山，在京之東南，明旦得洞經，所載羅浮山事雲，茅山是洞庭口，南通羅浮，正與夢中意相會，遂感而作羅浮山賦曰：若乃茅公之說，神化是悉，數非亿度，道单悒憰，［古冗切，○冗當作穴，見廣韻屑韻。］洞四有九，此惟其七，潛夜引辉，幽境朗日，故曰朱明之陽宮，耀真之陰室，洞穴之寶衢，海靈之雲術，伊離情之易結，谅沉念之羅浮，發潛夢於永夜，若愬波而乘桴，越扶屿之緬涨，上增龍之合流，鼓蘭枻以水宿，杖桂策以山遊。","sortOrder":188},
  {"id":"s_work_nvlt_7_189","chapterId":"ch_work_nvlt_7","text":"◇九疑山","sortOrder":189},
  {"id":"s_work_nvlt_7_190","chapterId":"ch_work_nvlt_7","text":"《山海經》曰：南方蒼梧之丘，蒼梧之川，其中有九疑山焉，舜之所葬，在長沙零陵界。","sortOrder":190},
  {"id":"s_work_nvlt_7_191","chapterId":"ch_work_nvlt_7","text":"楚辭九歌曰：九疑紛兮併近，［九歌作迎。］","sortOrder":191},
  {"id":"s_work_nvlt_7_192","chapterId":"ch_work_nvlt_7","text":"《淮南子》曰：九疑之南，陆事寡而水事多。","sortOrder":192},
  {"id":"s_work_nvlt_7_193","chapterId":"ch_work_nvlt_7","text":"《漢書》曰：武帝南巡狩，至於盛唐，望祀虞舜於九疑，［事具巡狩部。］","sortOrder":193},
  {"id":"s_work_nvlt_7_194","chapterId":"ch_work_nvlt_7","text":"《湘中記》曰：九疑山，在營道縣，九山相似，行者疑惑，故名九疑。","sortOrder":194},
  {"id":"s_work_nvlt_7_195","chapterId":"ch_work_nvlt_7","text":"《名山略記》曰：九疑山，漢末有張禮正，魏時有治明期，南遊九疑，禮正服黃精，明期服泽寫柏實，後俱適西城君，受虹景方，兼以守一，內外洞澈，東華迎而乘雲升天。","sortOrder":195},
  {"id":"s_work_nvlt_7_196","chapterId":"ch_work_nvlt_7","text":"【詩】庾闡采藥詩曰：采藥靈山氵急，結駕登九疑，懸巖漏石髓，芳穀挺丹芝，泠泠雲珠落，漼漼玉蜜滋，鮮景染冰顏，妙氣翼冥期。","sortOrder":196},
  {"id":"s_work_nvlt_7_197","chapterId":"ch_work_nvlt_7","text":"【碑】漢蔡邕九疑山碑曰：巖巖九疑，峻極於天，觸石膚合，興播建雲，時風嘉雨，浸润下民，芒芒南土，實賴厥勋，逮於虞舜，聖德光明，克諧顽傲，以孝蒸蒸，師錫帝世，尧而授徵，受終文祖，璇璣是承，太階以平，人以有終，遂葬九疑，解體而升，登此崔嵬，讬靈神仙。","sortOrder":197},
  {"id":"s_work_nvlt_7_198","chapterId":"ch_work_nvlt_7","text":"《藝文類聚》　唐·欧陽詢","sortOrder":198},
  {"id":"s_work_nvlt_8_1","chapterId":"ch_work_nvlt_8","text":"卷八山部下、水部上","sortOrder":1},
  {"id":"s_work_nvlt_8_2","chapterId":"ch_work_nvlt_8","text":"○虎丘山蒜山石帆山石鼓山石門山太平山岷山會稽諸山交廣諸山","sortOrder":2},
  {"id":"s_work_nvlt_8_3","chapterId":"ch_work_nvlt_8","text":"○總載水海水河水江水淮水漢水洛水","sortOrder":3},
  {"id":"s_work_nvlt_8_4","chapterId":"ch_work_nvlt_8","text":"◇虎丘山","sortOrder":4},
  {"id":"s_work_nvlt_8_5","chapterId":"ch_work_nvlt_8","text":"《虎丘山銘》曰：晉司徒東亭獻公王珣撰，雲武丘山先名海涌山。","sortOrder":5},
  {"id":"s_work_nvlt_8_6","chapterId":"ch_work_nvlt_8","text":"《吳越春秋》曰：阖庐死，葬於國西北，名虎丘，穿土為川，積壤為丘，發五都之士十萬人，共治千里，使象摙土，冢池四周，水深丈餘，椁三重，傾水銀為池，池廣六十步，黃金珠玉為凫雁，扁諸之劍魚腸三千在焉，葬之已三日，金精上楊，為白虎據墳，故曰虎丘。","sortOrder":6},
  {"id":"s_work_nvlt_8_7","chapterId":"ch_work_nvlt_8","text":"王珣虎丘記曰：山大势四面周嶺，南則是山迳，兩面壁立，交林上合，蹊路下通，升降窈窕，亦不卒至。","sortOrder":7},
  {"id":"s_work_nvlt_8_8","chapterId":"ch_work_nvlt_8","text":"【詩】張正見從永陽王遊虎丘山詩曰：沧波壮鬱島，洛邑镇崇芒，未若茲山麗，岧峣擅水乡，地靈侔少室，涂艱像太行，重巖摽虎據，九曲峻羊腸，溜深涧無底，風幽穀自涼，寶沉餘玉氣，劍隱絕星光，白雲多異影，丹桂有藂香，遠看銀台竦，洞塔耀山莊，瑞草生金地，天花照石梁。","sortOrder":8},
  {"id":"s_work_nvlt_8_9","chapterId":"ch_work_nvlt_8","text":"【序】晉顧恺之虎丘山序曰：吳城西北，有虎丘山者，含真藏古，體虛窮玄，隱嶙陵堆之中，望形不出常阜，至乃嵒崿，絕於華峰。","sortOrder":9},
  {"id":"s_work_nvlt_8_10","chapterId":"ch_work_nvlt_8","text":"陳顧野王虎丘山序曰：夫少室作镇，以峻極而摽奇，太華神掌，以削成而稱貴，若茲山者，高不摡雲，深無藏影，卑非培塿，淺異棘林，秀壁數尋，被杜蘭與苔藓，椿枝十仞，掛藤葛與懸萝，曲涧潺湲，脩篁荫暎，路若絕而复通，石將頹而更缀，抑巨麗之名山，信大吳之勝壤，若乃九功六義之興，依永和聲之製，志由興作，情以詞宣，形言諧於韶夏，成文畅於鐘律，由來尚矣，未有登高能賦，而韜斐麗之章，入穀忘歸，而忽铿锵之節，故總辔齊鑣，競雕虫於山水，雲合霧集，爭歌頌於林泉，於時風清邃穀，景麗脩峦，蘭佩堪纫，胡繩可索，林花翻洒，乍飄颺於蘭皋，山禽啭响，時弄聲於乔木，班草班荆，坐磻石之上，濯纓濯足，就沧浪之水，傾縹瓷而酌旨酒，剪绿葉而賦新詩，肅爾若與三迳齊蹤，鎗然似共九成偕韻，盛矣哉，聊述時事，寄之翰墨。","sortOrder":10},
  {"id":"s_work_nvlt_8_11","chapterId":"ch_work_nvlt_8","text":"【書】陳張种與沈蜅書曰：虎丘山者，吳嶽之神秀者也，雖复峻極異於九天。隱磷殊於太一，衿帶城傍，獨超眾嶺，控繞川泽，顧絕峰岑，若其峰崖刻削，窮造化之瑰诡，絕涧杳冥，若鬼神之仿佛，珍木靈草，茂琼枝與碧葉，飛禽走獸，必負義而膺仁，是以歷代高賢，輕舉栖讬，梵台雲起，寶刹星懸，自非玉牒开祥，金精蘊耀，豈其神怪，若此者乎。","sortOrder":11},
  {"id":"s_work_nvlt_8_12","chapterId":"ch_work_nvlt_8","text":"陳沈蜅答書曰：若乃三江五湖，洞庭巨麗，寫長洲之茂苑，登九曲之層台，山高水深，雲蒸霧吐，其中之秀異者，實虎丘之靈阜焉，冬桂夏柏，長萝脩竹，靈源秘洞，轉侧超絕，遠涧深崖，交羅戶穴。","sortOrder":12},
  {"id":"s_work_nvlt_8_13","chapterId":"ch_work_nvlt_8","text":"◇蒜山","sortOrder":13},
  {"id":"s_work_nvlt_8_14","chapterId":"ch_work_nvlt_8","text":"劉楨京口記曰：蒜山無峰嶺，北懸臨江中，魏文帝南望而致歌，［太平御覽四十六作叹。］","sortOrder":14},
  {"id":"s_work_nvlt_8_15","chapterId":"ch_work_nvlt_8","text":"山謙之南徐州記曰：蒜山北江中，有伏牛山。","sortOrder":15},
  {"id":"s_work_nvlt_8_16","chapterId":"ch_work_nvlt_8","text":"【詩】宋顏延之侍遊蒜山詩曰：睿思纏故里，巡駕匝舊坰，陟峰騰輦路，尋雲抗瑤薨，［《文選》二十二作甍。］春江壮風涛，蘭野茂荑英，宣遊弘下濟，窮遠凝聖情。","sortOrder":16},
  {"id":"s_work_nvlt_8_17","chapterId":"ch_work_nvlt_8","text":"宋謝莊侍宴蒜山詩曰：龍旌拂紆景，鳳蓋起流雲，轉蕙方因委，層華正氛氲，煙竟山郊遠，霧罢江天分，調石飛延露，裁金起承雲。","sortOrder":17},
  {"id":"s_work_nvlt_8_18","chapterId":"ch_work_nvlt_8","text":"◇石帆山","sortOrder":18},
  {"id":"s_work_nvlt_8_19","chapterId":"ch_work_nvlt_8","text":"盛弘之《荆州記》曰：武陵舞陽縣，有石帆山，若數百幅帆。","sortOrder":19},
  {"id":"s_work_nvlt_8_20","chapterId":"ch_work_nvlt_8","text":"謝靈運遊名山志曰：破石溪南二百餘里。又有石帆，脩廣與破石等度，质色亦同，傳雲，古有人以破石之半為石帆，故名彼為石帆，此名破石。","sortOrder":20},
  {"id":"s_work_nvlt_8_21","chapterId":"ch_work_nvlt_8","text":"【銘】宋鮑昭石帆銘曰：應龍剖流，息石橫波，下潀地軸，上獦星羅，牵湘引漢，欱蠡吞沱，西歷岷冢，北寫淮河，渺淼泓藹，積廣連深，淪天测际，亘海窮陰，雲旌未起，風柯不吟，崩涛山逐，鬱浪雷沉，穆戎遂留，昭御不還，徒悲猿鶴，空駕沧煙。","sortOrder":21},
  {"id":"s_work_nvlt_8_22","chapterId":"ch_work_nvlt_8","text":"◇石鼓山","sortOrder":22},
  {"id":"s_work_nvlt_8_23","chapterId":"ch_work_nvlt_8","text":"《臨海記》曰：郡西白鶴山，有石鼓石搥，世雲石鼓鳴則土地寇亂，隆安初，此鼓屢鳴，果有孫恩之賊。","sortOrder":23},
  {"id":"s_work_nvlt_8_24","chapterId":"ch_work_nvlt_8","text":"舊說，鄴西北有石鼓，懸著山旁，鳴則有軍兵動，零陵永正乡，有鳴石二所，其一状如鼓，俗名石鼓，泉陵縣有石鼓，舊聞數十里，今無聲。","sortOrder":24},
  {"id":"s_work_nvlt_8_25","chapterId":"ch_work_nvlt_8","text":"王韶之《南康記》曰：寧都溪之西，有一山，状如鼓，相傳謂之石鼓，去縣三里，壁立百餘丈，赫然似朝霞初暉，異於凡石。","sortOrder":25},
  {"id":"s_work_nvlt_8_26","chapterId":"ch_work_nvlt_8","text":"盛弘之《荆州記》曰：建平郡南陵縣有石鼓，南有五龍山，山峰嶕峣，凌雲濟竦，状若龍形，故因為名。","sortOrder":26},
  {"id":"s_work_nvlt_8_27","chapterId":"ch_work_nvlt_8","text":"【詩】晉庾闡觀石鼓詩曰：命駕觀奇逸，径鶩造靈山，朝濟清溪岸，夕憩五龍泉，鳴石含潛响，雷駭震九天，妙化非不有，莫知神自然，翔霄拂翠嶺，緣涧漱巖間，手藻春泉絜，目玩陽葩鮮。","sortOrder":27},
  {"id":"s_work_nvlt_8_28","chapterId":"ch_work_nvlt_8","text":"◇石門山","sortOrder":28},
  {"id":"s_work_nvlt_8_29","chapterId":"ch_work_nvlt_8","text":"遠法師庐山記曰：西南有石門山，其形似双闕，壁立千餘仞，而瀑布流焉。","sortOrder":29},
  {"id":"s_work_nvlt_8_30","chapterId":"ch_work_nvlt_8","text":"周景式庐山記曰：石門山在康皇東北八十餘里，是一山之大穀，有涧水，亦名石門涧，吐源浚遠，為眾泉之宗，每夏霖秋潦，轉石發树，聲動數十里。","sortOrder":30},
  {"id":"s_work_nvlt_8_31","chapterId":"ch_work_nvlt_8","text":"劉楨京口記曰：石門，二山頭相對，高二十餘丈，廣六十餘步，謂為石門，行道所經。","sortOrder":31},
  {"id":"s_work_nvlt_8_32","chapterId":"ch_work_nvlt_8","text":"謝靈運名山志曰：石門山，兩巖間微有門形，故以為稱，瀑布飛泻，丹翠交曜。","sortOrder":32},
  {"id":"s_work_nvlt_8_33","chapterId":"ch_work_nvlt_8","text":"【詩】宋謝靈運登石門最高顶詩曰：晨策尋絕壁，夕宿在山栖，疏峰抗高馆，對嶺臨回溪，長林羅戶穴，積石擁基階，連巖覺路塞，密竹使迳迷，來人忘新術，去子惑故蹊，聒聒夕流駛，噭々夜猿啼，沉冥豈別理，守道自不携，心契九秋幹，目玩三春荑，惜無同懷客，共登青雲梯。","sortOrder":33},
  {"id":"s_work_nvlt_8_34","chapterId":"ch_work_nvlt_8","text":"又石門巖上宿詩曰：朝搴苑中蘭，畏彼霜下歇，暝還雲际宿，弄此石上月。鳥鳴識夜栖，木落知風發，異音同致聽，殊响俱清越，美人竟不來，陽阿徒晞發。","sortOrder":34},
  {"id":"s_work_nvlt_8_35","chapterId":"ch_work_nvlt_8","text":"【書】梁吳筠［按當作均，後同。］與顧章書曰：仆去月謝病，還賝薜萝，梅溪之西，有石門山者，森壁爭霞，孤峰限日，幽岫含雲，深溪蓄翠，蝉吟鶴唳，水响猿啼，英英相雜，綿綿成韻，既素重幽居，遂葺宇其上，幸富菊花，偏饒竹實，山穀所資，於斯已辦，仁智所樂，豈徒語哉。","sortOrder":35},
  {"id":"s_work_nvlt_8_36","chapterId":"ch_work_nvlt_8","text":"◇太平山","sortOrder":36},
  {"id":"s_work_nvlt_8_37","chapterId":"ch_work_nvlt_8","text":"孔皋［延祐四明志七作晔。又《太平御覽》四十七引孔書皆作晔，後同。］會稽記曰：餘姚縣南百里，有太平山，山形似繖，四角各生一种木，木不雜糅，三陽之辰，華卉代發。","sortOrder":37},
  {"id":"s_work_nvlt_8_38","chapterId":"ch_work_nvlt_8","text":"孔靈符會稽記曰：餘姚江源出太平山，東至浃江口入海。","sortOrder":38},
  {"id":"s_work_nvlt_8_39","chapterId":"ch_work_nvlt_8","text":"【詩】齊孔稚珪遊太平山詩曰：石险天濬分，林交日容缺，陰涧落春榮，寒巖留夏雪。","sortOrder":39},
  {"id":"s_work_nvlt_8_40","chapterId":"ch_work_nvlt_8","text":"【銘】晉孫綽太平山銘曰：隗瓘太平，峻逾華霍，秀嶺樊缊，奇峰挺崿，上幹翠霞，下籠丹壑，有士冥遊，默往奇讬，肅形枯林，映心幽漠，亦既覯止，涣焉融滯，懸棟翠微，飛宇雲际，重峦蹇產，回溪萦帶，被以青松，洒以素瀨，流風佇芳，翔雲停藹。","sortOrder":40},
  {"id":"s_work_nvlt_8_41","chapterId":"ch_work_nvlt_8","text":"◇岷山","sortOrder":41},
  {"id":"s_work_nvlt_8_42","chapterId":"ch_work_nvlt_8","text":"《尚書·禹貢》：岷山导江，東別為沱。","sortOrder":42},
  {"id":"s_work_nvlt_8_43","chapterId":"ch_work_nvlt_8","text":"《河圖》曰：岷山之地為井絡，帝以會昌，神以建福，上為天井。","sortOrder":43},
  {"id":"s_work_nvlt_8_44","chapterId":"ch_work_nvlt_8","text":"【贊】晉郭璞岷山贊曰：岷山之精，上絡東井，始出一勺，終致淼溟，作紀南夏，天清地靜。","sortOrder":44},
  {"id":"s_work_nvlt_8_45","chapterId":"ch_work_nvlt_8","text":"◇會稽諸山","sortOrder":45},
  {"id":"s_work_nvlt_8_46","chapterId":"ch_work_nvlt_8","text":"《吳越春秋》曰：范蠡作城訖，怪山自至，怪山者，琅耶東武海中山也，一夕自來，百姓怪之，故曰怪山。","sortOrder":46},
  {"id":"s_work_nvlt_8_47","chapterId":"ch_work_nvlt_8","text":"《孔子家語》曰：禹會諸侯於涂山，防風氏後至，禹戮之，其骨专車。","sortOrder":47},
  {"id":"s_work_nvlt_8_48","chapterId":"ch_work_nvlt_8","text":"《越絕書》曰：雞山豕山者，勾踐以畜雞豕，將伐吳，以食死士。","sortOrder":48},
  {"id":"s_work_nvlt_8_49","chapterId":"ch_work_nvlt_8","text":"孔皋會稽記，永興縣東北九十里，有餘山，傳曰：是涂山，案越書，禹娶於涂山，涂山去山陰五十里，捡其里數，似其處也。","sortOrder":49},
  {"id":"s_work_nvlt_8_50","chapterId":"ch_work_nvlt_8","text":"又縣東南十八里，有射的山，遠望的的如射侯，謂之射的。射的之西，有石室，壁方二丈，謂之射堂。傳雲，羽客之所遊憩，土人常以此占穀食貴賤，射的明則米賤，闇則貴。喭曰：射的白，貐一百，射的玄，貐一千。","sortOrder":50},
  {"id":"s_work_nvlt_8_51","chapterId":"ch_work_nvlt_8","text":"又曰：縣東北六十里，有土城山，勾踐索美女以獻吳王，得諸暨羅山賣薪女西施鄭旦，先教習於土城山，山邊有石，雲是西施瀚［《太平御覽》四十七作澣，沙石。］","sortOrder":51},
  {"id":"s_work_nvlt_8_52","chapterId":"ch_work_nvlt_8","text":"又曰：東有秦望山，昔秦始皇登此，使李斯勒石，其碑見在。","sortOrder":52},
  {"id":"s_work_nvlt_8_53","chapterId":"ch_work_nvlt_8","text":"孔靈符會稽山記曰：會稽山南，有宛委山，其上有石，俗呼石匮，壁立幹雲，有懸度之险，升者累梯，然後至焉，昔禹治洪水，厥功未就，乃跻於此山，發石匮，得金簡玉字，以知山河體势，於是疏导百川，各盡其宜。","sortOrder":53},
  {"id":"s_work_nvlt_8_54","chapterId":"ch_work_nvlt_8","text":"又曰：射的山西南水中，有白鶴，常為仙人取箭，曾刮壤尋索，遂成此山也。","sortOrder":54},
  {"id":"s_work_nvlt_8_55","chapterId":"ch_work_nvlt_8","text":"【詩】晉王彪之登會稽刻石山詩曰：隆山珪瓘，崇峦嶕峣，傍觌沧洲，仰拂玄霄，文命遠會，風淳道遼，秦皇遐巡，邁茲英豪，宅靈基阿，銘跡峻峤，青陽曜景，時和氣淳，脩嶺增鮮，長松挺新，飛鸿振羽，騰龍躍鱗。","sortOrder":55},
  {"id":"s_work_nvlt_8_56","chapterId":"ch_work_nvlt_8","text":"【贊】晉郭璞會稽山贊曰：禹徂會稽，爰朝群臣，不虔是讨，乃戮長人，玉匮表夏，玄石勒秦。","sortOrder":56},
  {"id":"s_work_nvlt_8_57","chapterId":"ch_work_nvlt_8","text":"◇交廣諸山","sortOrder":57},
  {"id":"s_work_nvlt_8_58","chapterId":"ch_work_nvlt_8","text":"顧微《廣州記》曰：南海增城縣，有白水山，有瀑布，懸註百許丈。","sortOrder":58},
  {"id":"s_work_nvlt_8_59","chapterId":"ch_work_nvlt_8","text":"又曰：南海始昌縣，有一石，望之似牛向江，名曰牛鼻山，縣西有夫盧山，高入雲霄，世傳雲，上有湖水，至甲戌日，辄聞山上有鼓角笳箫鳴响。","sortOrder":59},
  {"id":"s_work_nvlt_8_60","chapterId":"ch_work_nvlt_8","text":"又曰：南海四會縣，有金岗山，行人往往見金人見形岗侧。","sortOrder":60},
  {"id":"s_work_nvlt_8_61","chapterId":"ch_work_nvlt_8","text":"又曰：東莞寶安縣，有參里山，傳雲，曾參純孝，其所居山林，後以為名。","sortOrder":61},
  {"id":"s_work_nvlt_8_62","chapterId":"ch_work_nvlt_8","text":"又曰：鬱林郡北，有大山，其高隱天，上有池，有石牛在池下，民常祀之，歲旱，百姓殺牛祈雨，以牛血和泥，厚泥石牛背，祠畢，天雨洪註，洗石牛背泥盡而後晴。","sortOrder":62},
  {"id":"s_work_nvlt_8_63","chapterId":"ch_work_nvlt_8","text":"劉欣期交州記曰：浮石山，海中而峙，高數十丈，浮在水上。","sortOrder":63},
  {"id":"s_work_nvlt_8_64","chapterId":"ch_work_nvlt_8","text":"又曰：有一山，神功刻鏤，若射堋，去石堂口百步，夜常聞射聲。","sortOrder":64},
  {"id":"s_work_nvlt_8_65","chapterId":"ch_work_nvlt_8","text":"裴氏《廣州記》曰：蒼梧彰平縣，有石膏山，望之皎若霜雪。","sortOrder":65},
  {"id":"s_work_nvlt_8_66","chapterId":"ch_work_nvlt_8","text":"【賦】宋謝靈運嶺表賦曰：若乃長山钦跨，外內乖隔，下無伏流，上無夷跡，麕兔望岗而旋歸，鸿雁睹峰而反翮，既陟麓而踐坂，遂升降於山畔，顧後路之傾巘，眺前磴之絕岸，看朝雲之抱岫，聽夕流之註涧，羅石棋布，怪譎橫越，非山非阜，如樓如闕，斑采類繡，明白若月，萝蔓絕攀，苔衣流滑。","sortOrder":66},
  {"id":"s_work_nvlt_8_67","chapterId":"ch_work_nvlt_8","text":"◇總載水","sortOrder":67},
  {"id":"s_work_nvlt_8_68","chapterId":"ch_work_nvlt_8","text":"《易說卦》曰：坎為水，润萬物者，莫润於水。","sortOrder":68},
  {"id":"s_work_nvlt_8_69","chapterId":"ch_work_nvlt_8","text":"《尚書》曰：湯湯洪水方割，荡荡懷山襄陵，浩浩滔天。","sortOrder":69},
  {"id":"s_work_nvlt_8_70","chapterId":"ch_work_nvlt_8","text":"《穀梁傳》曰：水北為陽，水南為陰。","sortOrder":70},
  {"id":"s_work_nvlt_8_71","chapterId":"ch_work_nvlt_8","text":"《左傳》：汙潦之水，可荐於鬼神，可羞於王公。","sortOrder":71},
  {"id":"s_work_nvlt_8_72","chapterId":"ch_work_nvlt_8","text":"《左傳》曰：共工氏以水紀官，故為水師而水名。","sortOrder":72},
  {"id":"s_work_nvlt_8_73","chapterId":"ch_work_nvlt_8","text":"說文，浦，水濱也。","sortOrder":73},
  {"id":"s_work_nvlt_8_74","chapterId":"ch_work_nvlt_8","text":"《禮記》曰：水曰清涤。","sortOrder":74},
  {"id":"s_work_nvlt_8_75","chapterId":"ch_work_nvlt_8","text":"又曰：今夫水一勺之多，及其不测，黿鼍鲛龍魚鱉生焉，货财殖焉。","sortOrder":75},
  {"id":"s_work_nvlt_8_76","chapterId":"ch_work_nvlt_8","text":"《毛詩》曰：楊之水，不流束薪。","sortOrder":76},
  {"id":"s_work_nvlt_8_77","chapterId":"ch_work_nvlt_8","text":"《穆天子傳》曰：天子飲於溽水之上。","sortOrder":77},
  {"id":"s_work_nvlt_8_78","chapterId":"ch_work_nvlt_8","text":"《尚書大傳》曰：非水無以准萬里之平，非水無以通道任重也。","sortOrder":78},
  {"id":"s_work_nvlt_8_79","chapterId":"ch_work_nvlt_8","text":"《韓詩外傳》曰：夫水者緣理而行，不遺小，似有智者，重而下，似有禮者，蹈深不疑，似有勇者，鄣防而清，似知命者，歷险致遠，似有德者，天地以成，群物以生，國家以寧，萬事以平，此智者所以樂於水也。","sortOrder":79},
  {"id":"s_work_nvlt_8_80","chapterId":"ch_work_nvlt_8","text":"又曰：夏不數浴，非愛水也，冬不數煬，非愛火也。","sortOrder":80},
  {"id":"s_work_nvlt_8_81","chapterId":"ch_work_nvlt_8","text":"《論語》曰：智者樂水。","sortOrder":81},
  {"id":"s_work_nvlt_8_82","chapterId":"ch_work_nvlt_8","text":"又曰：子在川上，曰：逝者如斯夫，不舍晝夜。","sortOrder":82},
  {"id":"s_work_nvlt_8_83","chapterId":"ch_work_nvlt_8","text":"《老子》曰：上善若水，水善利萬物而不爭，處眾人之所惡，故幾於道。","sortOrder":83},
  {"id":"s_work_nvlt_8_84","chapterId":"ch_work_nvlt_8","text":"《文子》曰：混混之水濁，可以濯吾足，青青之水清，可以濯吾纓，［事具離骚，雲沧浪之水。］又曰：水之性欲清，沙石秽之，人之性欲平，嗜欲害之。","sortOrder":84},
  {"id":"s_work_nvlt_8_85","chapterId":"ch_work_nvlt_8","text":"《晏子》曰：景公問廉政何如，對曰：其行。］水也，美哉水乎，其濁無不涂，其清無不洒。","sortOrder":85},
  {"id":"s_work_nvlt_8_86","chapterId":"ch_work_nvlt_8","text":"《墨子》曰：古語曰：君子不鏡於水而鏡於人，鏡於水見面之容，鏡於人則知吉凶。","sortOrder":86},
  {"id":"s_work_nvlt_8_87","chapterId":"ch_work_nvlt_8","text":"《尸子》曰：凡水，其方折者有玉，其圓折者有珠，清水有黃金，［淮南子亦雲，事具珠玉部。］","sortOrder":87},
  {"id":"s_work_nvlt_8_88","chapterId":"ch_work_nvlt_8","text":"《孟子》曰：觀於海者難為水，遊於聖人之門者難為言。","sortOrder":88},
  {"id":"s_work_nvlt_8_89","chapterId":"ch_work_nvlt_8","text":"又曰：性猶湍水也，决諸東方則東流，决諸西方則西流，人性之無分於善惡也，猶水之無分於東西也。","sortOrder":89},
  {"id":"s_work_nvlt_8_90","chapterId":"ch_work_nvlt_8","text":"《莊子》曰：水靜則明，濁則混，水靜猶明，而况精神聖人之心靜乎。","sortOrder":90},
  {"id":"s_work_nvlt_8_91","chapterId":"ch_work_nvlt_8","text":"又曰：秋水時至，百川灌河，涘涯之間，不辨牛馬，於是河伯欣然自喜，以天下之美為在己。","sortOrder":91},
  {"id":"s_work_nvlt_8_92","chapterId":"ch_work_nvlt_8","text":"又曰：夫水，積也不厚，則負其大舟也無力。","sortOrder":92},
  {"id":"s_work_nvlt_8_93","chapterId":"ch_work_nvlt_8","text":"《淮南子》曰：往古之時，九州裂，水浩漾而不息，於是女媧積芦灰以止淫水，［事具帝王部。］","sortOrder":93},
  {"id":"s_work_nvlt_8_94","chapterId":"ch_work_nvlt_8","text":"又曰：土地各以類生人，是故清水音小，濁水音大，湍水人輕，遲水人重。","sortOrder":94},
  {"id":"s_work_nvlt_8_95","chapterId":"ch_work_nvlt_8","text":"《山海經》曰：剡山有獸焉，名曰合窳，見則天下大水，其上有水焉，甚寒而清，帝台之漿水也。","sortOrder":95},
  {"id":"s_work_nvlt_8_96","chapterId":"ch_work_nvlt_8","text":"《玄中記》曰：天下之多者水焉，浮天載地，高下無不至，萬物無不润。","sortOrder":96},
  {"id":"s_work_nvlt_8_97","chapterId":"ch_work_nvlt_8","text":"《博物志》曰：有八流水出名山，渭出鳥鼠，漾出嶓冢，洛出熊耳，潁出少室，汝出燕泉，泗出陪尾，淄出月台，沂出太山。","sortOrder":97},
  {"id":"s_work_nvlt_8_98","chapterId":"ch_work_nvlt_8","text":"永嘉郡記曰：有柘林水，［出建安吳興縣。］有梧桐水，［有兩源，一出松陽。］有桃支水，［出東陽長山縣。］","sortOrder":98},
  {"id":"s_work_nvlt_8_99","chapterId":"ch_work_nvlt_8","text":"《湘中記》曰：湘水至清，雖深五六丈，見底了了，石子如樗蒲矢，五色鮮明，白沙如霜雪，赤岸如朝霞。","sortOrder":99},
  {"id":"s_work_nvlt_8_100","chapterId":"ch_work_nvlt_8","text":"《抱朴子》曰：左慈以氣禁水，水為逆流一二丈，禁水著中庭露之，大寒不冰。","sortOrder":100},
  {"id":"s_work_nvlt_8_101","chapterId":"ch_work_nvlt_8","text":"《華陽國志》曰：朱仓，少受學於蜀郡，豆屑飲水以諷誦，同業等怜其貧，給米肉，終不受。","sortOrder":101},
  {"id":"s_work_nvlt_8_102","chapterId":"ch_work_nvlt_8","text":"《搜神記》曰：漢末，零陵太守有女，悅門下書佐，使婢取盥手水飲之而有娠，既而生子，至能行，太守抱兒，使求其父，兒直上書佐膝，書佐推之，兒仆地為水。","sortOrder":102},
  {"id":"s_work_nvlt_8_103","chapterId":"ch_work_nvlt_8","text":"車潁秦書曰：王猛攻鄴，慕容評距猛，而恒賣水與軍人，眾思為亂，猛因得破之。","sortOrder":103},
  {"id":"s_work_nvlt_8_104","chapterId":"ch_work_nvlt_8","text":"《續述征記》曰：梁邹城西，有籠水，雲齊孝婦誠感神明，涌泉發於室內，潛以績籠覆之，由是無負汲之勞，及家人疑之，時其出而搜其室，试發此籠，而泉遂濆涌，流漂居宇，故名曰籠水。","sortOrder":104},
  {"id":"s_work_nvlt_8_105","chapterId":"ch_work_nvlt_8","text":"【詩】陳祖孫登詠水詩曰：龍川紫闕映，珠浦碧沙沉，岸闊莲香遠，流清雲影深，風潭如拂鏡，山溜似調琴，請君看皎絜，知有淡然心。","sortOrder":105},
  {"id":"s_work_nvlt_8_106","chapterId":"ch_work_nvlt_8","text":"【賦】魏文帝濟川賦曰：臨濟川之層淮，覽洪波之容裔，濞騰楊以相薄，激長風而亟逝，漫浩汗而難测，眇不睹其垠际，於是龟龍神嬉，鸿鸞群翔，鱗介霍驿，載止載行，俯唼菁藻，仰餐若芳，永號長吟，延首相望，美玉昭晰以曜煇，明珠灼灼而流光，於是遊覽既厭，日亦西傾，朱旗電曜，击鼓雷鳴，長驅風厲，悠爾北征，思魏都以偃息，讬華屋而遨遊，酌玄清於金罍，騰羽觴以獻酬。","sortOrder":106},
  {"id":"s_work_nvlt_8_107","chapterId":"ch_work_nvlt_8","text":"又臨渦賦曰：建安［《初學記》九。又二十二，《太平御覽》三百五十九下有十字，此脱。］八年，經東國，遵渦水，相佯乎树下，駐馬書鞭，作臨渦之賦曰：荫高树兮臨曲渦，微風起兮水增波，魚頡颃兮鳥逶迤，雌雄鳴兮聲相和，蓱藻生兮散茎柯，春木繁兮發丹華。","sortOrder":107},
  {"id":"s_work_nvlt_8_108","chapterId":"ch_work_nvlt_8","text":"晉應貞臨丹賦曰：陟綿岡之迢邈，臨窈穀之濬遐，覽丹源之冽泉，眷懸流之清波，漱玄瀨而漾沚，順黃崖而荡博，激重巖之絕根，拂崇丘之飛崿，然後陰渠洞出，陽澮旁开，倏熠高鶩，皓暚長懷，盤溢鬱没，雲轉飆回，屏侧為之飛陨，壁岸為之陂隤，列以青林，荫以绿枝，柽松蓊茸於其侧，楊柳婀娜乎其下，則［○則上有脱文。］高溜承崖，懸泉屬嶺，別流分註，冰瑩玉靜，清波引鏡，形無遁影。","sortOrder":108},
  {"id":"s_work_nvlt_8_109","chapterId":"ch_work_nvlt_8","text":"晉左九嫔涪漚賦曰：覽庶類之肇化，何涪漚之獨靈，禀陰精以運景，因落雨而結形，不系根於獨立，故假物以資生，體珠光之皎皎，若凝霜之初成，色鮮熠以熒熒，似融露之將渟，亡不長消，存不久寄，其成不欲難，其败亦以易也。","sortOrder":109},
  {"id":"s_work_nvlt_8_110","chapterId":"ch_work_nvlt_8","text":"【贊】晉顧凯之水贊曰：湛湛若凝，开神以质，乘風檀澜，妙齊得一。","sortOrder":110},
  {"id":"s_work_nvlt_8_111","chapterId":"ch_work_nvlt_8","text":"晉庾肅之水贊曰：湛湛涵渌，清澜澄濬，妙质柔明，雲深夜润。","sortOrder":111},
  {"id":"s_work_nvlt_8_112","chapterId":"ch_work_nvlt_8","text":"晉殷仲堪水贊曰：大象無形，氣以分粗，淡淡冲津，质有雖虛，清澜可瀨，明激弗渝，孰能懷之，汎然靡拘。","sortOrder":112},
  {"id":"s_work_nvlt_8_113","chapterId":"ch_work_nvlt_8","text":"晉孔甯子水贊曰：澄鑒無虛，積之成川，湍飛瑩穀，激石泠然。","sortOrder":113},
  {"id":"s_work_nvlt_8_114","chapterId":"ch_work_nvlt_8","text":"晉郭璞釋水贊曰：川渎綺错，涣澜流帶，潛润旁通，經營華外，殊出同歸，混之東會。","sortOrder":114},
  {"id":"s_work_nvlt_8_115","chapterId":"ch_work_nvlt_8","text":"又弱水贊曰：弱出崑山，鸿毛是沉，北淪流沙，南暎火林，惟水之奇，莫测其深。","sortOrder":115},
  {"id":"s_work_nvlt_8_116","chapterId":"ch_work_nvlt_8","text":"◇海水","sortOrder":116},
  {"id":"s_work_nvlt_8_117","chapterId":"ch_work_nvlt_8","text":"《尚書》曰：江漢朝宗於海。","sortOrder":117},
  {"id":"s_work_nvlt_8_118","chapterId":"ch_work_nvlt_8","text":"《山海經》曰：無皋之山，南望幼海，［郭璞註曰：即少海水。］","sortOrder":118},
  {"id":"s_work_nvlt_8_119","chapterId":"ch_work_nvlt_8","text":"又曰：發鳩之山，有鳥名曰精衛，是炎帝之女，往遊於東海，溺而不反，是故精衛常取西山之木石，以填東海。","sortOrder":119},
  {"id":"s_work_nvlt_8_120","chapterId":"ch_work_nvlt_8","text":"又曰：大荒中有山，名曰天台，海水之入焉。","sortOrder":120},
  {"id":"s_work_nvlt_8_121","chapterId":"ch_work_nvlt_8","text":"《老子》曰：江海所以能為百穀王者，以其善下，故能為百穀王。","sortOrder":121},
  {"id":"s_work_nvlt_8_122","chapterId":"ch_work_nvlt_8","text":"《淮南子》曰：海不讓水，積以成其大。","sortOrder":122},
  {"id":"s_work_nvlt_8_123","chapterId":"ch_work_nvlt_8","text":"謝承《後漢書》曰：汝南陳茂，嘗為交阯別駕，刺史周敞，涉海遇風，舡欲覆没，茂拔劍呵骂水神，風即止息。","sortOrder":123},
  {"id":"s_work_nvlt_8_124","chapterId":"ch_work_nvlt_8","text":"《博物志》曰：舊說，天河與海通，近世有居海渚者，年年八月，有浮楂來過，甚大，往反不失期，此人乃多齎糧，乘楂去，忽忽不覺晝夜，奄至一處，有城郭屋舍，望室中，多見織婦，見一丈夫，牵牛渚次飲之，此人問此為何處，答曰：問嚴君平，此人還，問君平，君平曰：某年某月，有客星犯牛斗，即此人乎。","sortOrder":124},
  {"id":"s_work_nvlt_8_125","chapterId":"ch_work_nvlt_8","text":"王隱《晉書》曰：慕容晃上言曰：臣躬征平郭，遠假陛下之威，將士竭命，精誠感靈，海為結冰，凌行海中三百餘里，臣自立國，及問諸故老，初無海水冰冻之歲。","sortOrder":125},
  {"id":"s_work_nvlt_8_126","chapterId":"ch_work_nvlt_8","text":"《神仙傳》曰：麻姑謂王方平曰：自接侍以來，見東海三為桑田，向到蓬萊，水乃淺於往者略半也，豈复為陵乎。","sortOrder":126},
  {"id":"s_work_nvlt_8_127","chapterId":"ch_work_nvlt_8","text":"《論語》曰：道不行，乘桴浮於海，從我者其由也與。","sortOrder":127},
  {"id":"s_work_nvlt_8_128","chapterId":"ch_work_nvlt_8","text":"《莊子》曰：南海之帝為倏，北海之帝為忽，中央之帝為浑沌，儵與忽時相與遇於浑沌之地，浑沌待之甚厚，倏與忽謀報浑沌之德，曰：人皆有七竅，以视聽食息，此獨無有，常试凿一竅，七日而浑沌死。","sortOrder":128},
  {"id":"s_work_nvlt_8_129","chapterId":"ch_work_nvlt_8","text":"又曰：窮發之北，有溟海者，天池也，有魚名曰鯤，化而為鳥，名曰鵬，［事具鳥部。］","sortOrder":129},
  {"id":"s_work_nvlt_8_130","chapterId":"ch_work_nvlt_8","text":"又曰：東海之鱉，謂埳井之蛙曰：夫海，千里之遠，不足以舉其大，千仞之高，不足以極其深，禹之時，十年九潦而水弗加益，湯之時，八年七旱而涯不减損，夫不為頃久推移，不以多少進退者，此亦東海之大樂也。","sortOrder":130},
  {"id":"s_work_nvlt_8_131","chapterId":"ch_work_nvlt_8","text":"又曰：海水三歲一周，流波相薄，故地動。","sortOrder":131},
  {"id":"s_work_nvlt_8_132","chapterId":"ch_work_nvlt_8","text":"《韓詩外傳》曰：成王時，有越裳氏，重三譯而朝，曰：吾受命國之黃發曰：久矣，天之不迅風雨，海之不波溢也，三年於茲矣，意者中國有聖人乎，盍往朝之。","sortOrder":132},
  {"id":"s_work_nvlt_8_133","chapterId":"ch_work_nvlt_8","text":"《十洲記》曰：扶桑在碧海之中，地一面萬里，太帝之宮，太真東王君所治處。","sortOrder":133},
  {"id":"s_work_nvlt_8_134","chapterId":"ch_work_nvlt_8","text":"《玄中記》曰：天下之強者，東海之惡燋焉，水灌而不已，惡燋者，山名也，在東海南方三萬里，海水灌水而即消。","sortOrder":134},
  {"id":"s_work_nvlt_8_135","chapterId":"ch_work_nvlt_8","text":"《博物志》曰：漢使驃騎將軍霍去病，北伐单於，至瀚海而還。","sortOrder":135},
  {"id":"s_work_nvlt_8_136","chapterId":"ch_work_nvlt_8","text":"周景式《孝子傳》曰：管寧避地遼東，經海遇風，船人危懼，皆叩頭悔過，寧思愆，念向曾如廁不冠，即便稽首，風亦尋靜。","sortOrder":136},
  {"id":"s_work_nvlt_8_137","chapterId":"ch_work_nvlt_8","text":"西域傳曰：蒲昌海一名鹽泽。","sortOrder":137},
  {"id":"s_work_nvlt_8_138","chapterId":"ch_work_nvlt_8","text":"【詩】宋謝靈運遊赤石進帆海詩曰：首夏猶清和，芳草亦未歇，水宿淹晨暮，陰霞屢興没，周覽倦瀛壖，况乃凌窮發，川後時安流，天吳靜不發，扬帆采石華，掛席拾海月。","sortOrder":138},
  {"id":"s_work_nvlt_8_139","chapterId":"ch_work_nvlt_8","text":"齊謝朓望海詩曰：沧波不可望，望極與天平，往往孤山映，處處春雲生，差池遠雁没，飒沓群凫驚。","sortOrder":139},
  {"id":"s_work_nvlt_8_140","chapterId":"ch_work_nvlt_8","text":"梁劉孝標登鬱洲山望海詩曰：沧潦聯霄岫，曾嶺鬱巑崱，下盤鹽海底，上轉靈乌翼，滇氵眄非可辯，鸿溶信難测，輕尘久弭飛，驚浪終不息，雲錦曜石屿，羅綾文水色。","sortOrder":140},
  {"id":"s_work_nvlt_8_141","chapterId":"ch_work_nvlt_8","text":"北齊祖孝徵望海詩曰：登高臨巨壑，不知千萬里，雲島相接連，風潮無極已，時看遠鸿度，乍見驚鷗起，無待送將歸，自然傷客子。","sortOrder":141},
  {"id":"s_work_nvlt_8_142","chapterId":"ch_work_nvlt_8","text":"【賦】後漢班叔皮覽海賦曰：餘有事於淮浦，覽沧海之茫茫，悟仲尼之乘桴，聊從容而遂行，馳鸿瀨以縹鶩，翼飛風而回翔，顧百川之分流，煥烂漫以成章，風波薄其裔裔，邈浩浩以湯湯，指日月以為表，索方瀛與壶梁，曜金璆以為闕，次玉石而為堂，蓂芝列於階路，涌醴漸於中唐，朱紫彩烂，明珠夜光，松乔坐於東序，王母處於西箱，命韓眾與歧伯，講神篇而校靈章，原結旅而自讬，因離世而高遊，騁飛龍之驂駕，歷八極而回周，遂竦節而响應，忽輕舉以神浮，遵霓霧之掩荡，登雲涂以凌厲，乘虛風而體景，超太清以增逝，麾天閽以啟路，辟閶阖而望餘，通王謁於紫宮，拜太一而受符。","sortOrder":142},
  {"id":"s_work_nvlt_8_143","chapterId":"ch_work_nvlt_8","text":"魏王粲遊海賦曰：乘菌桂之方舟，浮大江而遙逝，翼驚風而長驅，集會稽而一睨，登陰隅以東望，覽沧海之體势，吐星出日，天與水际，其深不测，其廣無臬，章亥所不極，盧敖所不屆，懷珍藏寶，神隱怪匿，或無氣而能行，或含血而不食，或有葉而無根，或能飛而無翼，鳥則爰居孔鵠，翡翠鷫鹴，繽紛往來，沉浮翱翔，魚則橫尾曲頭，方目偃嵒，大者若山陵，小者重鈞石，乃有贲蛟大貝，明月夜光，蠵{辟龟}玳瑁，金质黑章，若夫長洲別島，旗布星峙，高或萬尋，近或千里，桂林藂乎其上，珊瑚周乎其趾，群犀代角，巨象解齒，黃金碧玉，名不可紀。","sortOrder":143},
  {"id":"s_work_nvlt_8_144","chapterId":"ch_work_nvlt_8","text":"魏文帝沧海賦曰：美百川之獨宗，壮沧海之威神，經扶桑而遐逝，跨天崖而讬身，驚涛暴駭，騰踴澎湃，铿訇隱鄰，涌沸凌邁，於是黿鼍漸離，泛濫淫遊，鸿鸞孔鵠，哀鳴相求，楊鱗濯翼，載沉載浮，仰唼芳芝，俯漱清流，巨魚橫奔，厥势吞舟，爾乃釣大貝，采明珠，搴懸黎，收武夫，窥大麓之潛林，睹搖木之羅生，上蹇產以交错，下來風之泠泠，振绿葉以葳蕤，吐分葩而扬榮。","sortOrder":144},
  {"id":"s_work_nvlt_8_145","chapterId":"ch_work_nvlt_8","text":"晉木玄虛海賦曰：昔在帝妫臣唐之世，洪涛澜汗，萬里無际，江河既导，萬穴俱流，掎拔五嶽，竭涸九州，於廓靈海，長為委输，［去聲。］其為怪，則乃浟湙［音亦。］潋滟，浮天［原訛大，據文選十二改。］無岸，波如連山，乍合乍散，噓吸百川，洗涤淮漢，若乃霾翳潛消，莫振莫竦，輕尘不飛，纖羅不動，猶尚呀呷，餘波獨涌，若乃邊荒速告，王命急宣，飛迅鼓楫，泛海凌山，於是候劲風，揭百尺，維長梢，掛帆席，望涛遠决，冏然鳥逝，一越三千，不終朝而濟所屆，若乃負秽臨深，虛誓愆祈，則有海童邀路，馬衔當蹊，天吳乍見而仿佛，岡象暫晓而閃尸，爾其大量也，則南澰朱崖，北洗天墟，東演析木，西薄青徐，經纶瀴溟，萬萬有餘，吐雲霓，含龍魚，隱鯤鱗，潛雲居，其垠則有天琛水怪，鲛人之室，瑕石诡暉，鱗甲異质，繁采扬華，萬色隱鮮，陽冰不治，［○《文選》十二作冶。］陰火潛燃，其魚則橫海之鯨，突杌孤遊，茹鱗甲，吞龍舟，若其毛翼產鷇，剖卵成禽，凫雏離衤從，鶴子淋渗，群飛侣浴，戲廣浮深，且其為器也，苞乾之奧，括坤之區，唯神是宅，亦祇是庐，何奇不有，何怪不储，茫茫積流，含形內虛，曠哉坎德，卑以自居。","sortOrder":145},
  {"id":"s_work_nvlt_8_146","chapterId":"ch_work_nvlt_8","text":"晉潘嶽沧海賦曰：徒觀其状也，則湯湯荡荡，澜漫形沉，流沫千里，懸水萬丈。测之莫量其深，望之不見其廣，無遠不集，靡幽不通，群谿俱息，萬流來同，含三河而納四渎，朝五湖而夕九江，陰霖則興雲降雨，陽霁則吐霞曜日，煮水而鹽成，剖蚌而珠出，其中有蓬萊名嶽，青丘奇山，阜陵別島，嵔環其間，其山則〈山累〉崔嵬崒，嵯峨隆屈，披沧流以特起，擢崇基而秀出，其魚則有吞舟鯨鲵，乌賊龍須，蜂目銶口，狸班雉軀，怪體異名，不可勝圖，其虫獸則素蛟丹虬，元龟靈鼍，脩黿巨鱉，紫貝螣蛇，玄螭蚴虬，赤龍焚蘊，遷體改角，推舊納新，舉扶搖以抗翼，泛陽侯以濯鱗，其禽鳥則鶠鸿鷫鹴，駕［當作鴐。］鹅鵁鶄，朱背煒燁，縹翠葱青，詳察浪波之來往，遍聽奔激之音响，力势之所回薄，润泽之所弥廣，普天之極大，橫率土而莫兩。","sortOrder":146},
  {"id":"s_work_nvlt_8_147","chapterId":"ch_work_nvlt_8","text":"晉庾闡海賦曰：昔禹啟龍門，群山既凿，高明澄氣而清浮，厚載势廣而盤礴。灌註百川，控清引濁，始乎濫觴，委输大壑，若夫長風鼓怒，涌浪碎潏，颺波於萬里之間，漂沫於扶桑之外，於是百川輻凑，四渎橫通，回〈風日〉泱漭，耸散穹隆，映晓雲而色暗，照落景而俱紅，驚浪峣瓘，眇漫瀄汩，灙漭潺湲，浮天沃日，鯨鲵蘊而乍見，伏螭涌而競遊，靈鼍朱鱉，出没爭浮，螣龍掣水，巨鱗吞舟。","sortOrder":147},
  {"id":"s_work_nvlt_8_148","chapterId":"ch_work_nvlt_8","text":"晉孫綽望海賦曰：五湖同浸，九江丛溉，抱河含濟，吞淮納泗，南控沅湘，西引涇渭，洲渚迢遞以疏屬，島屿綿邈以牢羅，殖嵬崔之碣石，構穹隆之〈牜羊〉柯，玄奧之府，重刃之房，鱗匯萬殊，甲產無方，包隨珠，衔夜光，玳瑁熠烁以泳遊。蟕蠵煥烂以映涨，靈貝含素而表紫，蠳螺絡舟而帶緗，青甲芬飆以微扇，玄木杳眇以舒芳，其卉木則绿苔石發，蔓以流綿，紫茎菎綜，解以被渚，華組依波而錦披，翠纶扇風而繡舉，長鯨嶽立以截浪，虭〈魚昔〉扬鬐以排流，巨鼇贔屃以冠山，乌鳠呼吸以吞舟，鵬為羽桀，鯤稱介豪，翼遮半天，背負重霄，舉翰則宇宙生風，抗鱗則四渎起涛，考萬川以周覽，亮天池之綜緯，弥纶八荒，亘帶九地，昏明註之而不溢，尾闾泄之而不匮。","sortOrder":148},
  {"id":"s_work_nvlt_8_149","chapterId":"ch_work_nvlt_8","text":"齊張融海賦曰：爾其海之状也，則窮區没渚，萬里藏岸，控會河濟，朝總江漢，湍轉則日月似驚，浪動則星河如覆，展轉從橫，扬珠起玉，峰势崇高，岫形參错，或如前而未進，乍非遷而已却，却瞻無後，向望何前，長尋高眺，唯水與天，若乃山橫蹙浪，風倒摧波，磊若驚山碣嶺以竦石，鬱若飛煙奔雲以振柯，連瑤光而交彩，接玉繩以通華，爾其奇名出錄，诡物無書，高岸乳鳥，橫閞產魚，蟕蠵玳瑁，綺貝繡螺，玄珠互采，［原訛牙米，據冯校本及明本改。］绿紫相華。","sortOrder":149},
  {"id":"s_work_nvlt_8_150","chapterId":"ch_work_nvlt_8","text":"◇河水","sortOrder":150},
  {"id":"s_work_nvlt_8_151","chapterId":"ch_work_nvlt_8","text":"《山海經》曰：崑崙山，河水出焉。","sortOrder":151},
  {"id":"s_work_nvlt_8_152","chapterId":"ch_work_nvlt_8","text":"又曰：陽紆之山，河出其中，陵門之山，河出其中。","sortOrder":152},
  {"id":"s_work_nvlt_8_153","chapterId":"ch_work_nvlt_8","text":"《毛詩》曰：新台，刺衛宣公也，納伋之妻，作新台於河上而要之，國人惡之，而作是詩也，新台有泚，河水沴沴。","sortOrder":153},
  {"id":"s_work_nvlt_8_154","chapterId":"ch_work_nvlt_8","text":"又曰：誰謂河廣，一苇杭之，誰謂宋遠，跂予望之。","sortOrder":154},
  {"id":"s_work_nvlt_8_155","chapterId":"ch_work_nvlt_8","text":"《左傳》曰：周詩有之曰：俟河之清，人寿幾何。","sortOrder":155},
  {"id":"s_work_nvlt_8_156","chapterId":"ch_work_nvlt_8","text":"又曰：楚昭王有疾，卜河為祟，大夫請祭，王曰：江漢沮漳，楚之望也，河非所獲罪，遂弗祭。","sortOrder":156},
  {"id":"s_work_nvlt_8_157","chapterId":"ch_work_nvlt_8","text":"《穀梁傳》曰：梁山崩，壅遏河三日不流，晉君召伯尊，伯尊過，遇輦者問焉，輦者曰：君親素縞師，群臣哭之，既而祠焉，伯尊至，君問之，伯尊如其言，而河流矣，［左傳雲伯宗。］","sortOrder":157},
  {"id":"s_work_nvlt_8_158","chapterId":"ch_work_nvlt_8","text":"《孝經援神契》曰：河者水之伯，上應天漢。","sortOrder":158},
  {"id":"s_work_nvlt_8_159","chapterId":"ch_work_nvlt_8","text":"《呂氏春秋》曰：古龍門未开，呂梁未發，河出孟門，大溢逆流，名曰洪水，禹乃决流疏河，為彭澧之漳，［呂氏春秋愛類篇作障。］所活者千八百國，此禹之功也。","sortOrder":159},
  {"id":"s_work_nvlt_8_160","chapterId":"ch_work_nvlt_8","text":"《史記》曰：元光中，河决於瓠子，於是天子已用事萬里沙，則還臨决河，沉白馬玉璧於河，令群臣從官，自將軍以下，皆負薪填决河，而取淇園之竹以為揵，天子既臨河决，悼功之不成，乃作瓠子之歌。","sortOrder":160},
  {"id":"s_work_nvlt_8_161","chapterId":"ch_work_nvlt_8","text":"又曰：秦滅六國，自以獲水德之瑞，更名河曰德水。","sortOrder":161},
  {"id":"s_work_nvlt_8_162","chapterId":"ch_work_nvlt_8","text":"《韓詩外傳》曰：申徒狄非其世，將自投於河，崔嘉聞而止之曰：聖仁之人，民之父母也，今為濡足，不救溺人，可乎，申徒曰：昔桀殺龍逢，紂殺比幹，而亡天下，吳殺子胥，陳殺泄冶，而滅其國，非無聖智，不用故也，遂負石而沉於河。","sortOrder":162},
  {"id":"s_work_nvlt_8_163","chapterId":"ch_work_nvlt_8","text":"《淮南子》：河以逶蛇故能遠。","sortOrder":163},
  {"id":"s_work_nvlt_8_164","chapterId":"ch_work_nvlt_8","text":"又曰：河水九折註海而流不絕者，有崑崙之输也。","sortOrder":164},
  {"id":"s_work_nvlt_8_165","chapterId":"ch_work_nvlt_8","text":"《物理論》曰：河色黃赤，眾川之流，蓋濁之也，百里一小曲，千里一大曲一直。","sortOrder":165},
  {"id":"s_work_nvlt_8_166","chapterId":"ch_work_nvlt_8","text":"《爾雅》曰：水自河出為雍。","sortOrder":166},
  {"id":"s_work_nvlt_8_167","chapterId":"ch_work_nvlt_8","text":"河出崑崙墟，色白。","sortOrder":167},
  {"id":"s_work_nvlt_8_168","chapterId":"ch_work_nvlt_8","text":"《山海經》曰：積石之山，其下有石門，河水冒以西南流。","sortOrder":168},
  {"id":"s_work_nvlt_8_169","chapterId":"ch_work_nvlt_8","text":"《莊子》曰：河润九里，泽及三族。","sortOrder":169},
  {"id":"s_work_nvlt_8_170","chapterId":"ch_work_nvlt_8","text":"《楚辭》曰：與汝遊兮九河，冲風起兮水扬波。","sortOrder":170},
  {"id":"s_work_nvlt_8_171","chapterId":"ch_work_nvlt_8","text":"【詩】梁范雲度黃河詩曰：河流迅且濁，湯湯不可陵，桧楫難為榜，松舟才自勝，空亭偃舊木，荒畴餘故塍，不睹行人跡，但見狐兔興，寄言河上老，此水何當澄。","sortOrder":171},
  {"id":"s_work_nvlt_8_172","chapterId":"ch_work_nvlt_8","text":"【賦】晉成公綏大河賦曰：覽百川之弘壮，莫尚美於黃河，發崑崙之峻極，出積石之嵯峨。","sortOrder":172},
  {"id":"s_work_nvlt_8_173","chapterId":"ch_work_nvlt_8","text":"魏應玚靈河賦曰：咨靈川之遐原，於崑崙之神丘，冲積石之重险，披山麓而溢浮，涉津路之峻泉，播九道乎中州，汾鸿踴而騰鶩，恒亹亹而徂征，肇乘高而迅逝，陽侯沛而振驚，有漢中葉，金隄隤而瓠子傾，興萬乘而親務，董群後而來營。下淇園之丰筱，投玉璧而沉星，若夫長杉峻槚，茂栝芬橿，扶流灌列，暎水荫防，隆條動而畅清風，白日顯而曜殊光。","sortOrder":173},
  {"id":"s_work_nvlt_8_174","chapterId":"ch_work_nvlt_8","text":"【頌】宋鮑昭河清頌，夫四皇六帝，树聲長世，大寶也，泽浸群生，國富刑清，鸿德也，製禮裁樂，淳風遷俗，文教也，誅箠羯黠，束顙象闕，武功也，鳴鳥躍魚，涤秽河渠，至祥也，大寶鸿德，文教武功，其崇如此，幽明同贊，神祇與能，厥應如彼，唯天為大，尧實則之，抑又聞之，势之所覃者淺，則美之所傳者近，道之所感者深，則慶之所流者遠，聖命難諶，皇歷攸歸，謀從筮协，神與民推，黃旗西暎，紫蓋東暉，納瑞璃玉，升政衡璣，污彼四渎，媚此双川，伏靈遙紀，閟貺遐年，澄波崑丘，鏡流葱山。","sortOrder":174},
  {"id":"s_work_nvlt_8_175","chapterId":"ch_work_nvlt_8","text":"【銘】後漢李尤河銘曰：洋洋河水，赴宗於海，經自中州，龍圖所在，昔周武諸侯，會於孟津，魚入王舟，乃往剋殷，大漢承緒，懷附遐鄰，邦事來濟，各貢厥珍。","sortOrder":175},
  {"id":"s_work_nvlt_8_176","chapterId":"ch_work_nvlt_8","text":"◇江水","sortOrder":176},
  {"id":"s_work_nvlt_8_177","chapterId":"ch_work_nvlt_8","text":"《尚書·禹貢》：岷山导江，東別為沱。","sortOrder":177},
  {"id":"s_work_nvlt_8_178","chapterId":"ch_work_nvlt_8","text":"又曰：三江既入，震泽底定。","sortOrder":178},
  {"id":"s_work_nvlt_8_179","chapterId":"ch_work_nvlt_8","text":"《春秋元命苞》曰：牛女為江潮，江潮者，所以开神润化，故其氣湍急。","sortOrder":179},
  {"id":"s_work_nvlt_8_180","chapterId":"ch_work_nvlt_8","text":"《孫卿子》曰：子路盛服見孔子，孔子曰：由，是襜襜者何也，在昔江出於汶山，其始出，源可以濫觴，及其至江之津也，不方舟，不避風，不可涉也，非唯下流水耶，今汝衣服既盛，顏色充盈，天下且孰肯諫汝乎。","sortOrder":180},
  {"id":"s_work_nvlt_8_181","chapterId":"ch_work_nvlt_8","text":"《列女傳》曰：楚昭王貞薑，齊女也，昭王出遊，留夫人漸台，江水大至，使使者迎夫人，忘持符，夫人不肯出，使者還取符，未及，台已坏，流水而死，［事具人部賢婦人篇。］","sortOrder":181},
  {"id":"s_work_nvlt_8_182","chapterId":"ch_work_nvlt_8","text":"又曰：廣漢薑詩妻，事姑至孝，姑好飲江水，水去家七里，妻常雞鳴溯流而汲，而風雪，不時得水，詩责遣之，妻寄鄰家，紡績給與，詩聞追還，舍侧立有涌泉出，味如江水。","sortOrder":182},
  {"id":"s_work_nvlt_8_183","chapterId":"ch_work_nvlt_8","text":"謝承《後漢書》曰：吳郡王閎，渡錢塘江，遭風，船欲覆，閎拔劍斫水，骂五［《太平御覽》六十作伍。］子胥，水息得濟。","sortOrder":183},
  {"id":"s_work_nvlt_8_184","chapterId":"ch_work_nvlt_8","text":"《吳志》曰：魏文帝出廣陵，望大江曰：彼有人焉，未可圖也，乃還。","sortOrder":184},
  {"id":"s_work_nvlt_8_185","chapterId":"ch_work_nvlt_8","text":"《吳錄》曰：書雲，三江既入，震泽底定，震泽，吳西南太湖也。","sortOrder":185},
  {"id":"s_work_nvlt_8_186","chapterId":"ch_work_nvlt_8","text":"又曰：步骘表言，此降人說，北多作布囊，欲以盛沙塞大江，吳主見呂岱，說，骘言北欲以沙囊塞江，每讀其表，辄獨失笑，此江自开辟以來，寧可以囊塞之乎。","sortOrder":186},
  {"id":"s_work_nvlt_8_187","chapterId":"ch_work_nvlt_8","text":"【詩】梁沈約泛永康江詩曰：長枝萌紫葉，清源泛绿苔，山光浮水至，春色犯寒來，臨睨信永矣，望美暧悠哉，寄言幽閨妾，羅袖勿空裁。","sortOrder":187},
  {"id":"s_work_nvlt_8_188","chapterId":"ch_work_nvlt_8","text":"又渡新安江貽京邑遊好詩曰：眷言訪舟客，茲川信可珍，洞澈隨深淺，皎鏡無冬春，千仞寫高树，百丈見遊鱗，紛吾隔嚣滓，寧可濯衣巾，原以潺湲末，霑君衣上尘。","sortOrder":188},
  {"id":"s_work_nvlt_8_189","chapterId":"ch_work_nvlt_8","text":"梁任昉濟浙江詩曰：昧旦乘輕風，江湖忽來往，或與歸波送，乍逐翻流上，近岸無暇目，遠峰更興想，绿树懸宿根，丹崖頹久壤。","sortOrder":189},
  {"id":"s_work_nvlt_8_190","chapterId":"ch_work_nvlt_8","text":"又嚴陵瀨詩曰：群峰此峻極，參差百重嶂，清淺既涟漪，激石复奔壮，神物徒有造，終然莫能仗。","sortOrder":190},
  {"id":"s_work_nvlt_8_191","chapterId":"ch_work_nvlt_8","text":"梁劉孝綽和太子落日望水詩曰：川平落日迥，落照滿川涨，复此淪坡池，泒引別沮漳，耿耿流長脈，熠熠動輕光，臨泛自多美，况乃還故乡，榜人夜理楫，棹女闇成妆，欲待春江曙，爭涂向洛陽。","sortOrder":191},
  {"id":"s_work_nvlt_8_192","chapterId":"ch_work_nvlt_8","text":"梁王台卿臨沧波詩曰：高軒臨不测，清江窮廣深，天邊生岸影，水上結雲陰，風來白華起，潮滿黃沙沉。","sortOrder":192},
  {"id":"s_work_nvlt_8_193","chapterId":"ch_work_nvlt_8","text":"又泛江詩曰：春江下白帝，畫舸向黃牛，錦纜回沙碛，蘭桡避荻洲，濕花隨水泛，空巢逐树流，岸社多乔木，山城足迥樓。","sortOrder":193},
  {"id":"s_work_nvlt_8_194","chapterId":"ch_work_nvlt_8","text":"陳陰铿晚出新亭詩曰：大江一浩荡，離悲足幾重，潮落猶如蓋，雲昏不作峰，遠戍唯聞鼓，寒山但見松，九十方稱半，歸途詎有蹤。","sortOrder":194},
  {"id":"s_work_nvlt_8_195","chapterId":"ch_work_nvlt_8","text":"【賦】東晉郭璞江賦曰：咨五才之併用，寔水德之靈長，惟岷山之导江，初發源於濫觴，總括漢泗，兼包淮湘，併吞沅澧，汲引沮漳，源二分於崌崍，流九泒乎潯陽，鼓洪涛於赤岸，淪餘波於柴桑，註五湖以漫漭，灌三江而漰沛，滈汗六州之域，經營炎景之外，呼吸萬里，吐納靈潮，自然往复，或夕或朝，若乃巴東之峡。夏後疏凿，絕岸萬丈，璧立霞駮，碧沙潰沱而往來，巨石硉蛇兀以前却，魚則江豚海豨，叔鲔王鳣，〈魚骨〉鰊〈魚桊〉鲉，鲛鰩鯩鰱，爾其水物怪错，則有王珧海月。土肉石華，琐蛣腹蟹，水母目虾，紫蚖如渠，洪蚶专車，琼〈王半〉晞曜以瑩珠，石〈虫去〉應節而扬葩，若乃龍鯉一角，奇鸧九頭，有鱉三足，有龟六眸，赪蟞肺躍而吐璣，文魮磬鳴以孕璆，〈馬孛〉馬騰波以噓蹀，水兕雷咆乎陽侯，雹布餘糧，星離沙鏡，青纶競糾，縟組爭映，石帆蒙籠以蓋屿，蓱實時出而漂泳，其下則金矿丹砾，雲精燭銀，鳴石列乎陽渚，浮磬肆乎陰濱，其羽族則有晨鵠天雞，鴢鷔鷗鹱，千類萬聲，自相喧聒，繁蔚芳蓠，隱藹水松，涯灌芊萰，潛薈葱茏，爰有包山洞庭，巴陵地道，潛達傍通，幽岫窈窕，金精玉英瑱其里，瑤珠怪石綷其表，海童之所巡遊，琴高之所靈矯，冰夷倚浪以傲睨，江妃含嚬而矊眇，若乃宙宇澄寂，八風不翔，舟子於是搦棹，涉人於是檥榜，漂飛雲，運艅艎，舳舻相屬，萬里連樯，溯回沿流，或漁或商，長風颹以增扇，廣莫〈風劦〉［音麗。］而氣整，徐而不〈風委〉，疾而不猛，鼓帆迅越，〈走白〉涨截浻，倏忽數百，千里俄頃，於是芦人漁人，擯落江山，衣則羽褐，食惟蔬鮮，或揮輪於懸蛇奇，或中瀨而橫旋，忽忘夕而宵歸，詠采菱以叩舷，及其譎变儵怳，符祥非一，動應無方，感事而出，經紀天地，错綜人術，妙不可盡之於言，事不可窮之於筆。","sortOrder":195},
  {"id":"s_work_nvlt_8_196","chapterId":"ch_work_nvlt_8","text":"晉庾闡涉江賦曰：發中州之曲泫，背石頭之巖岨，溯晨風而遙邁，乘涛波而容與，於是時也，夕日將昏，天吳駭奔，陽侯漂海，若泛江豚，爾乃雲霧勃起，風流溷淆，排巖拒瀨，觸石興涛，澎湃洗渒，鬱怒咆哮，回連波以嶽墜，壑後土而川窅，總百川之殊势，集朝宗乎沧浪，註天波於析木，潋東極乎扶桑，體含弘而弥泰，道謙尊而逾光，齊山海以比量，冠百穀而稱王，此則水之势也，且夫山川朅怪，水物含靈，鱗千其族，羽萬其名，毛群诡觀，倮類殊形，明月晞光以夕耀，金沙逐波而吐瑛，撫楫中流，汨徂西土，過乎歷陽之津，迄乎橫江之浦，若乃越三江之下口，眇濡須以迳渡，邈天险之遐势，歷習坎之重固，川渎泓澄以含景，山水氵甲氵鼠而鱗布。","sortOrder":196},
  {"id":"s_work_nvlt_8_197","chapterId":"ch_work_nvlt_8","text":"晉曹毗涉江賦曰：迄趙屯，歷彭川，脩岸靡靡，莞苇芊芊，紫莲被翠波而抗英，碧椹乘天岸而星懸，百籁夕奏，山精夜燃，狂梠萧瑟以洞駭，洪涛突兀而橫峙，爾乃江豨彭濞，夜火煇煥，凌错吐梠，駭鯨喷澜，采蜂於是汎波，文魚於是登岸。","sortOrder":197},
  {"id":"s_work_nvlt_8_198","chapterId":"ch_work_nvlt_8","text":"【歌】晉夏侯湛江上泛歌曰：悠悠兮遠征，倏倏兮暨南荆，南荆兮臨長江。臨江河兮讨不庭，江水兮浩浩，長流兮萬里，洪浪兮雲轉，陽侯兮奔起，驚翼兮垂天，鯨魚兮嶽跱，蘪芜紛兮被皋陆，脩竹鬱兮翳崖趾，望江之南兮遨目桂林，桂林蓊鬱兮鵾雞扬音，凌波兮原濟，舟楫不具兮江水深沈，嗟回盻於北夏，何歸軫之難尋。","sortOrder":198},
  {"id":"s_work_nvlt_8_199","chapterId":"ch_work_nvlt_8","text":"◇淮水","sortOrder":199},
  {"id":"s_work_nvlt_8_200","chapterId":"ch_work_nvlt_8","text":"《尚書·禹貢》曰：道淮自桐柏。","sortOrder":200},
  {"id":"s_work_nvlt_8_201","chapterId":"ch_work_nvlt_8","text":"《毛詩》曰：率彼淮浦，省此徐土。","sortOrder":201},
  {"id":"s_work_nvlt_8_202","chapterId":"ch_work_nvlt_8","text":"水經曰：淮水出南陽平氏縣昭稽山，東北過桐柏山。","sortOrder":202},
  {"id":"s_work_nvlt_8_203","chapterId":"ch_work_nvlt_8","text":"《山海經》曰：淮水出餘山，山在朝陽義乡西，入海。","sortOrder":203},
  {"id":"s_work_nvlt_8_204","chapterId":"ch_work_nvlt_8","text":"【賦】魏文帝浮淮賦曰：建安十四年，師自谯東征，大興水軍，泛舟萬艘，雖孝武舳舻千里，殆不過也，溯淮水而南邁，泛洪潭之皇波，仰巖岗之隆阻，經東山之曲阿，於是驚風泛，涌波駭，眾帆張，群棹起，爭先逐進，莫過［疑涉下適字衍。］適相待。","sortOrder":204},
  {"id":"s_work_nvlt_8_205","chapterId":"ch_work_nvlt_8","text":"魏王粲浮淮賦曰：從王師以南征，浮淮水而遐逝，背渦浦之曲流，望馬丘之高澨，於是迅風興，涛波動，長瀨潭渨，滂沛汹溶。","sortOrder":205},
  {"id":"s_work_nvlt_8_206","chapterId":"ch_work_nvlt_8","text":"◇漢水","sortOrder":206},
  {"id":"s_work_nvlt_8_207","chapterId":"ch_work_nvlt_8","text":"《山海經》曰：嶓冢之山，漢水出焉，東南流，註於江。","sortOrder":207},
  {"id":"s_work_nvlt_8_208","chapterId":"ch_work_nvlt_8","text":"《尚書·禹貢》曰：嶓冢道漾，東流為漢。","sortOrder":208},
  {"id":"s_work_nvlt_8_209","chapterId":"ch_work_nvlt_8","text":"《毛詩》曰：漢廣，德廣所及也，文王之化，被乎南國，美化行於江漢之域，漢有遊女，不可求思。","sortOrder":209},
  {"id":"s_work_nvlt_8_210","chapterId":"ch_work_nvlt_8","text":"《左氏傳》曰：屈完謂齊桓公曰：楚國方城以為城，漢水以為池。","sortOrder":210},
  {"id":"s_work_nvlt_8_211","chapterId":"ch_work_nvlt_8","text":"【詩】梁簡文帝玩漢水詩曰：雜色崑崙水，泓澄龍首渠，豈若茲川麗，清流疾且徐，離離細碛净，藹藹树陰疏，石衣隨溜卷，水芝扶浪舒，連翩寫去楫，鏡澈倒遙墟，聊持點纓上，於是察川魚。","sortOrder":211},
  {"id":"s_work_nvlt_8_212","chapterId":"ch_work_nvlt_8","text":"【賦】後漢蔡邕漢津賦曰：夫何大川之浩浩，披厚土以載形，納陽穀之所吐，兼漢沔之殊名，總畎澮之群液，演西土之陰精，過曼山以左回，遊襄陽而南萦，於是遊目騁觀，南援三州，北集京都，上控隴坻，下接江湖，导财運货，懋遷有無，既乃風焱萧瑟，勃焉併興，陽侯沛以奔骛，洪涛涌以沸騰，原乘流以上下，窮沧浪乎三澨，觀固宗之形兆，看洞庭之交會。","sortOrder":212},
  {"id":"s_work_nvlt_8_213","chapterId":"ch_work_nvlt_8","text":"◇洛水","sortOrder":213},
  {"id":"s_work_nvlt_8_214","chapterId":"ch_work_nvlt_8","text":"《山海經》曰：洛水出洛西山，東北註河，入成皋之西。","sortOrder":214},
  {"id":"s_work_nvlt_8_215","chapterId":"ch_work_nvlt_8","text":"《易》曰：河出圖，雒出書，聖人則之。","sortOrder":215},
  {"id":"s_work_nvlt_8_216","chapterId":"ch_work_nvlt_8","text":"《尚書》曰：道洛自熊耳，東北會於涧瀍。","sortOrder":216},
  {"id":"s_work_nvlt_8_217","chapterId":"ch_work_nvlt_8","text":"《國語》曰：靈王二十二年，穀洛龍斗，將毀宮室，王欲壅之，太子晉曰：夫山，土之聚也，藪，物之歸也，川，氣之导也，泽，水之鍾也，夫水聚於高，歸於下，今吾執政，無乃實所僻，而禍夫二川之神，王卒壅之，王室大亂。","sortOrder":217},
  {"id":"s_work_nvlt_8_218","chapterId":"ch_work_nvlt_8","text":"《淮南子》曰：雒水輕利宜禾。","sortOrder":218},
  {"id":"s_work_nvlt_8_219","chapterId":"ch_work_nvlt_8","text":"謝承《後漢書》曰：沛國陳宣，建武十年，雒水出，造天津城門，或欲筑塞之，宣諫曰：昔王尊正身，金堤水退，况聖人耶，言未絕而水去。","sortOrder":219},
  {"id":"s_work_nvlt_8_220","chapterId":"ch_work_nvlt_8","text":"漢官典職曰：德陽殿，周遊容萬人，自偃師去宮四十五里，激洛水於殿下。","sortOrder":220},
  {"id":"s_work_nvlt_8_221","chapterId":"ch_work_nvlt_8","text":"【詩】太宗皇帝臨洛水詩曰：春蒐馳駿骨，總辔俯長河，霞處流萦錦，風前瀁卷羅，水花翻照树，隄蘭倒插波，豈必汾陰曲，秋雲發棹歌。","sortOrder":221},
  {"id":"s_work_nvlt_8_222","chapterId":"ch_work_nvlt_8","text":"蘇味道和受圖溫洛詩曰：绿綺膺河檢，青壇俯洛濱，天旋俄製跸，孝享屬嚴禋，陟配光三祖，懷柔洎百神，霧开中道日，雪斂屬車尘，預奉鹹英奏，長歌亿萬春。","sortOrder":222},
  {"id":"s_work_nvlt_8_223","chapterId":"ch_work_nvlt_8","text":"李峤和拜洛詩曰：七萃鑾舆動，千年瑞檢开，文如龟貝出，圖似鳳衔來，殷荐三神享，明祠萬國陪，周旗黃鳥集，漢幄紫雲回，日暮鉤陳轉，清歌上帝台。","sortOrder":223},
  {"id":"s_work_nvlt_8_224","chapterId":"ch_work_nvlt_8","text":"牛鳳及和受圖溫洛詩曰：八神承玉輦，六羽驚瑤溪，戒道伊川北，通旌涧水西，御圖开洛匮，刻石與天齊，瑞日波中上，仙禽霧里低，微臣矯弱翮，抃舞接鸞鹥。","sortOrder":224},
  {"id":"s_work_nvlt_8_225","chapterId":"ch_work_nvlt_8","text":"【賦】魏曹子建《洛神賦》曰：餘從京域，言歸東藩，背伊闕，越轘轅，經通穀，凌景山，容與乎陽林，流眄乎洛川，睹一麗人，於巖之畔，乃援御者而告之曰：彼何人斯，若斯之艳也，御者對曰：臣聞河洛之神，名曰虙妃，君王所見，無乃是乎，餘告曰：其形也，翩若驚鸿，婉若遊龍，仿佛兮若輕雲之蔽月，飄飖兮若流風之回雪，於是忽焉縱體，以遊以嬉，左倚采旄，右荫桂旗，攘皓腕於神滸，采湍瀨之玄芝，收和顏而靜志兮，申禮防以自持，爾乃眾靈雜遝，命儔嘯侣，或戲清流，或翔神渚，或采明珠，或拾翠羽，從南湘之二妃，携漢濱之遊女，體迅飛凫，飄忽若神，凌波微步，羅襪生尘，於是屏翳收風，川後靜波，冯夷鳴鼓，女媧清歌，騰文魚以警乘，鳴玉鑾以偕逝，六龍俨其齊首，載雲車之容裔。","sortOrder":225},
  {"id":"s_work_nvlt_8_226","chapterId":"ch_work_nvlt_8","text":"《藝文類聚》　唐·欧陽詢","sortOrder":226},
  {"id":"s_work_nvlt_9_1","chapterId":"ch_work_nvlt_9","text":"卷九水部下","sortOrder":1},
  {"id":"s_work_nvlt_9_2","chapterId":"ch_work_nvlt_9","text":"○壑四渎涛泉湖陂池谿穀涧浦渠井冰津桥","sortOrder":2},
  {"id":"s_work_nvlt_9_4","chapterId":"ch_work_nvlt_9","text":"《山海經》曰：東海之外有大壑。","sortOrder":4},
  {"id":"s_work_nvlt_9_5","chapterId":"ch_work_nvlt_9","text":"《列子》曰：渤海之東，不知幾亿萬里，有大壑，實惟無底之穀。","sortOrder":5},
  {"id":"s_work_nvlt_9_6","chapterId":"ch_work_nvlt_9","text":"《莊子》曰：諄芒東之大壑，遇苑風於東海濱，苑風曰：子將之大壑奚為，夫壑之為物，註焉而不滿，取焉而不竭。","sortOrder":6},
  {"id":"s_work_nvlt_9_7","chapterId":"ch_work_nvlt_9","text":"又曰：藏舟於壑，藏山於泽，謂之固矣，然而夜半有力者負之而走，昧者不知也。","sortOrder":7},
  {"id":"s_work_nvlt_9_8","chapterId":"ch_work_nvlt_9","text":"《離骚》曰：降望大壑。","sortOrder":8},
  {"id":"s_work_nvlt_9_9","chapterId":"ch_work_nvlt_9","text":"【賦】梁簡文帝大壑賦曰：渤海之東，不知幾亿，大壑在焉，其深無極，悠悠既凑，滔滔不息，觀其浸受，壮其吞匿，歷詳眾水，異导殊名，江出濯錦，漢吐珠瑛，海逢時而不涌，河遇聖而知清，嗟乎，使夫懷山之水積，天漢之流駛，彭潛與渭濕俱臻，四渎與九河同至，餘乃知巨壑之難滿，尾闾之為異","sortOrder":9},
  {"id":"s_work_nvlt_9_10","chapterId":"ch_work_nvlt_9","text":"◇四渎","sortOrder":10},
  {"id":"s_work_nvlt_9_11","chapterId":"ch_work_nvlt_9","text":"《爾雅》曰：江河淮濟為四渎，四渎者，發源註海者也。","sortOrder":11},
  {"id":"s_work_nvlt_9_12","chapterId":"ch_work_nvlt_9","text":"桓谭《新論》曰：四渎之源，最高而長，從高註下，其流激浚，故為平地灾害。","sortOrder":12},
  {"id":"s_work_nvlt_9_13","chapterId":"ch_work_nvlt_9","text":"《博物志》曰：四渎，濟出王屋山，其江河淮所出，已具別卷。","sortOrder":13},
  {"id":"s_work_nvlt_9_14","chapterId":"ch_work_nvlt_9","text":"【碑】周王襃四渎祠碑銘曰：靈祠嶽立，貝關雲浮，寂寥诡怪，仿仿神遊，姬嬴分國，河渭合流，桃花春水，靈草孤洲，潼乡河曲，汾陰睺壤，亂流不度，龍門難上，河魚送迎，江妃來往，水开通跡，山臨高掌，智以藏往，神以知來，榮光離合，雲氣徘徊，水仙遺操，津吏餘杯，波息川後，浪靖澹台。","sortOrder":14},
  {"id":"s_work_nvlt_9_16","chapterId":"ch_work_nvlt_9","text":"《廣雅》曰：陽侯涛，大波也。","sortOrder":16},
  {"id":"s_work_nvlt_9_17","chapterId":"ch_work_nvlt_9","text":"《吳越春秋》曰：吳王賜子胥劍，遂伏劍而死，吳王乃取子胥之尸，盛以鴟夷之器，投之江海，子胥因隨流扬波，成涛激岸，隨潮來往。","sortOrder":17},
  {"id":"s_work_nvlt_9_18","chapterId":"ch_work_nvlt_9","text":"《論衡》曰：儒書言，吳王夫差殺伍子胥，煮之於镬，盛以囊，投之於江，子胥恚恨，臨水為涛，溺殺人，夫言吳王殺伍子胥投之於江，實也，言其恨恚，臨水為涛者，虛也，衛菹子路而漢烹彭越，子胥勇猛，不過子路彭越，然二士不能發怒於鼎镬之中，子胥亦然，自先入鼎镬，後乃入江，在镬之時，其神豈怯，而勇於江水哉，何其怒氣前後不相副也。","sortOrder":18},
  {"id":"s_work_nvlt_9_19","chapterId":"ch_work_nvlt_9","text":"《博物志》曰：東海中有牛魚，其形如牛，剝其皮懸之，潮水至則毛起，潮去則伏。","sortOrder":19},
  {"id":"s_work_nvlt_9_20","chapterId":"ch_work_nvlt_9","text":"【詩】晉蘇彦於西陵觀涛詩曰：洪涛奔逸势，駭浪駕丘山，訇隱振宇宙，漰潏津雲連。","sortOrder":20},
  {"id":"s_work_nvlt_9_21","chapterId":"ch_work_nvlt_9","text":"梁徐昉賦得觀涛詩曰：雲容雜浪起，楚水漫吳流，漸看遙树没，稍見遠天浮，漁人迷舊浦，海鳥失前洲，不测沧溟曠，輕鱗幸自遊。","sortOrder":21},
  {"id":"s_work_nvlt_9_22","chapterId":"ch_work_nvlt_9","text":"【賦】晉顧恺之觀涛賦曰：臨浙江以北眷，壮沧海之宏流，水無涯而合岸，山孤映而若浮，既藏珍而納景，且激波而扬涛，其中則有珊瑚明月，石帆瑤瑛，彫鱗采介，特种奇名，崩峦填壑，傾堆漸隅，岑有積螺，嶺有懸魚，謨茲涛之為體，亦崇廣而宏浚，形無常而參神，斯必來以知信，势刚凌以周威，质柔弱以协順。","sortOrder":22},
  {"id":"s_work_nvlt_9_23","chapterId":"ch_work_nvlt_9","text":"晉曹毗觀涛賦曰：伊山水之遼迥，何秋月之凄清，瞻沧津之騰起，觀雲涛之來征，爾其势也，發源溟池，回冲天井，洒拂仓漢，遙櫟星景，伍子結誓於陰府，洪湍應期而來騁，汩如八風俱臻，隗若崑崙抗嶺。","sortOrder":23},
  {"id":"s_work_nvlt_9_24","chapterId":"ch_work_nvlt_9","text":"晉伏滔望涛賦曰：若夫金祇理辔，素月告望，宏涛於是鬱起，重流於是電驤。起沙渟而迅邁，觸橫門而剋壮，灌江津而砰潏，鼓赤岸而激扬，鬱律煙騰，隗兀連岗，重叠巘而天竦，洄湍澼而起涨。","sortOrder":24},
  {"id":"s_work_nvlt_9_26","chapterId":"ch_work_nvlt_9","text":"《爾雅》曰：泉一見一否為瀸，濫泉正出，正出，涌出也，沃泉懸出，懸，下出也，汎泉仄出，仄出，旁出也。","sortOrder":26},
  {"id":"s_work_nvlt_9_27","chapterId":"ch_work_nvlt_9","text":"論語撰考讖曰：水名盜泉，舟尼不嗽。","sortOrder":27},
  {"id":"s_work_nvlt_9_28","chapterId":"ch_work_nvlt_9","text":"《呂氏春秋》曰：太公釣於滋泉，◇《淮南子》曰：崑崙四水者，帝之神泉，以和百藥，以润萬物。","sortOrder":28},
  {"id":"s_work_nvlt_9_29","chapterId":"ch_work_nvlt_9","text":"《東觀漢記》曰：耿恭為校尉，居疏勒，匈奴來攻，城中穿井十五丈無水，恭曰：聞二師將軍，拔佩刀刺山，而飛泉出，今漢德神靈，豈有窮乎，乃正衣服，向井拜，為吏請祷，有頃，井泉濆出。","sortOrder":29},
  {"id":"s_work_nvlt_9_30","chapterId":"ch_work_nvlt_9","text":"應劭《漢官儀》曰：酒泉城下有金泉，泉味如酒，故曰酒泉。","sortOrder":30},
  {"id":"s_work_nvlt_9_31","chapterId":"ch_work_nvlt_9","text":"吳郡錄曰：始興有始興山，山出溫泉。","sortOrder":31},
  {"id":"s_work_nvlt_9_32","chapterId":"ch_work_nvlt_9","text":"天門零縣有溫泉，丹陽江乘縣有湯山，出溫泉，二所可以治［太平御覽七十一作瀹。］雞。","sortOrder":32},
  {"id":"s_work_nvlt_9_33","chapterId":"ch_work_nvlt_9","text":"《廣志》曰：溫泉，西者在新丰，北者在廣平，有美泉出，溉种，出穀香美，在汲郡，新成縣有泠泉，水冷如冰，在湖縣有鹽泉，煮則為鹽，有醴泉，用之愈疾。","sortOrder":33},
  {"id":"s_work_nvlt_9_34","chapterId":"ch_work_nvlt_9","text":"晉安帝紀曰：吳隱之性廉操，為廣州刺史，界有一水，謂之貪泉，古老雲，飲此水者，廉士皆貪，隱之始踐境，先至水所，酌而飲之，因賦詩以言志，若使夷齊飲，終當不易心，清操逾厲。","sortOrder":34},
  {"id":"s_work_nvlt_9_35","chapterId":"ch_work_nvlt_9","text":"宣城記曰：臨城縣南四十里，有蓋山，百許步有姑舒［《文選》註四十三，初學記八，《太平御覽》七十作舒姑，此倒。］泉，昔有舒女，與其父析薪於此泉，女因坐，牵挽不動，乃還告家，比還，唯見清泉湛然，女母曰：吾女好音樂，乃作絃歌，泉涌洄流，有朱鯉一双，令［《文選》註作今，御覽同。］人作樂嬉戲，泉故涌出。","sortOrder":35},
  {"id":"s_work_nvlt_9_36","chapterId":"ch_work_nvlt_9","text":"漢水記曰：漢水有溫泉，方圓數十步，冬夏常沸涌，望見白氣冲天，能差百病。","sortOrder":36},
  {"id":"s_work_nvlt_9_37","chapterId":"ch_work_nvlt_9","text":"江乘地記曰：東南三十五里，有半湯泉，半冷半溫，共同一壑。","sortOrder":37},
  {"id":"s_work_nvlt_9_38","chapterId":"ch_work_nvlt_9","text":"盛弘之《荆州記》曰：新陽縣惠泽中，有溫泉，冬月，未至數里，遙望白氣，浮蒸如煙，上下采映，状若綺疏。又有車輪双轅形，世傳昔有玉女乘車，自投此泉，今人時見女子，姿儀光麗，往來倏忽。","sortOrder":38},
  {"id":"s_work_nvlt_9_39","chapterId":"ch_work_nvlt_9","text":"又曰：夷道縣句將山下，有三泉，傳雲，本無此泉，居者皆苦遠汲，人人多賣水與之，有一女子，孤貧褴縷，無以貿易，有一乞人，衣粗貌丑，瘡痍竟體，村人見之，無不秽惡，唯女子獨加哀矜，割飯飴之，乞人食畢曰：我感嫗行善，欲思相報，為何所須，女答曰：何恩可報，且今所須之物，非君能得，因問所須，女子曰：正原此山下有水可汲，乞人乃取腰中書刀，刺山下三處，即飛泉涌出，因便辭去，忽然不見。","sortOrder":39},
  {"id":"s_work_nvlt_9_40","chapterId":"ch_work_nvlt_9","text":"括地圖曰：負丘之山，上有赤泉，飲之不老，神宮有英泉，飲之，眠三百歲乃覺，不知死。","sortOrder":40},
  {"id":"s_work_nvlt_9_41","chapterId":"ch_work_nvlt_9","text":"《十洲記》曰：瀛洲有玉膏，山出泉如酒味，名為玉酒。","sortOrder":41},
  {"id":"s_work_nvlt_9_42","chapterId":"ch_work_nvlt_9","text":"【詩】北齊劉逖浴湯泉詩曰：驪岫猶懷玉，新丰尚有家，神井堪銷疹，溫泉足荡邪，紫苔生石岸，黃沫擁金沙，振衣殊未已，翻然停使車。","sortOrder":42},
  {"id":"s_work_nvlt_9_43","chapterId":"ch_work_nvlt_9","text":"【賦】後漢張衡溫泉賦曰：陽春之月，百草萋萋，餘在遠行，原望有懷，遂適驪山，觀溫泉，浴神井，風中峦，壮厥類之獨美，思在化之所原，覽中域之珍，［《初學記》七珍下有怪字，此脱。］無斯水之神靈，控湯穀於瀛洲，濯日月乎中營，荫高山之北延，處幽屏以間清，於是殊方交涉，駿奔來臻，士女晔其鱗萃，紛雜遝其如絪。","sortOrder":43},
  {"id":"s_work_nvlt_9_44","chapterId":"ch_work_nvlt_9","text":"晉傅鹹神泉賦序曰：餘所居庭前，有涌泉，在夏則冷，涉冬而溫，溫則水物冬生，冷則冰可以過，每夏遊之，不知歲之有暑耳，惟茲神泉，厥理難原，在冬則溫，既夏而寒，混混洋洋，載清載澜，遂乃坘以文石，树之柳杞，密葉雲覆，重荫蔽沚，氣泠泠以含涼，風肅肅而恒起，於時朱明紀運，旭日馳光，鬱鬱隆暑，赫赫太陽，盥［全晉文五十一作盥。］玉體於素波，身凄焉而自清，不知天時之有暑，忽謂繁霜之陨庭，逮至旻秋既逝，司寒騁節，六合萧條，嚴風凛冽，河洛輟流，太陰凝結，彼溰々而含冻，此灼灼而含熱，绿竹猗猗，荇藻青青，是讬斯茂，是殖斯榮。","sortOrder":44},
  {"id":"s_work_nvlt_9_45","chapterId":"ch_work_nvlt_9","text":"【碑】周王襃溫湯碑曰：原夫二儀开辟，雷風以之通响，五材運行，水火因而併用，炎上作苦，既麗純陽之德，润下作鹹，且协凝陰之度，至於遷陵熱溪，沉魚涌浪，炎洲燒地，穴鼠含煙，火井飛泉，垂天遠扇，焦源沸水，冲流迸集，甘川浴日，跳波邁椒丘之野，湯穀扬涛，激水疾龍門之箭，故以地伏流黃，神泉愈疾雲雲。其銘曰：挺此溫穀，驪嶽之陰，白礬上彻，丹沙下沉，華清駐老，飛流瑩心，穀神不死，川德愈深。","sortOrder":45},
  {"id":"s_work_nvlt_9_46","chapterId":"ch_work_nvlt_9","text":"周庾信溫湯碑曰：鹹池浴日，先應绿甲之圖，砥柱浮天，始受玄夷之命，仁則涤荡埃氛，義則激扬清濁，勇則負山餘力，弱則鸿毛不勝，仲春則榆荚同流，三月則桃花共下，其色变者，流為五雲之漿，其味美者，結為三危之露，煙青於銅浦，色白於鉛溪，非神鼎而長沸，異龍池而獨涌，洒胃湔腸，興羸起瘠，秦皇餘石，仍為雁齒之階，漢武舊陶，即用魚鱗之瓦，山間涌水，實表忠誠，室內江流，弥彰純孝，豈若醴泉消疾，聞乎建武之朝，神水蠲痾，在乎鹹康之世，嵩嶽三仙之馆，不孤擅於天池，華陰百丈之泉，豈獨高於莲井。","sortOrder":46},
  {"id":"s_work_nvlt_9_48","chapterId":"ch_work_nvlt_9","text":"《說文》曰：湖，大陂也，楊州浸有五湖，水泽所仰以溉灌也。","sortOrder":48},
  {"id":"s_work_nvlt_9_49","chapterId":"ch_work_nvlt_9","text":"《越絕書》曰：大湖周三萬六千頃。","sortOrder":49},
  {"id":"s_work_nvlt_9_50","chapterId":"ch_work_nvlt_9","text":"《神異經》曰：北方荒外有石湖，其水冰。","sortOrder":50},
  {"id":"s_work_nvlt_9_51","chapterId":"ch_work_nvlt_9","text":"《淮南子》曰：夫歷陽之都，一夕反而為湖，歷陽，淮南國名，昔有老嫗，常行仁義，有兩書生過之，謂曰：此國當没為湖，视東城門阃有血，便走上山，勿反顧也，自爾，此嫗數往视門阃，吏問之，姥對如其言，暮，門吏殺雞，以血涂門，明日，嫗早往视，門血，便走上山，國没為湖。","sortOrder":51},
  {"id":"s_work_nvlt_9_52","chapterId":"ch_work_nvlt_9","text":"《風俗通》曰：越滅吳，范蠡乘舟於五湖。","sortOrder":52},
  {"id":"s_work_nvlt_9_53","chapterId":"ch_work_nvlt_9","text":"《語林》曰：褚公與孫綽遊曲阿後湖，狂風忽起，舫欲傾，諸公已醉，乃曰：此舫人皆無可以招天譴者，唯有興公多尘滓，正當以厭天欲耳，便欲捉掷水中，孫遽無計，唯大啼曰：季野，卿念我。","sortOrder":53},
  {"id":"s_work_nvlt_9_54","chapterId":"ch_work_nvlt_9","text":"《述異記》曰：桓冲為江州刺史，乃遣人周行庐山，冀睹靈異，既陟崇巘，有一湖，匝生桑树，有大群白鹅，湖中有败艑赤鱗魚。","sortOrder":54},
  {"id":"s_work_nvlt_9_55","chapterId":"ch_work_nvlt_9","text":"劉道真錢塘記曰：明聖湖在縣南，去縣三里，父老相傳，湖有金牛。","sortOrder":55},
  {"id":"s_work_nvlt_9_56","chapterId":"ch_work_nvlt_9","text":"鄭緝之東陽記曰：北山有湖，故老相傳雲，其下有居民曰徐公者，常登嶺至此處，見湖水湛然，有二人共博於湖間，自稱赤松子安期先生，有一壶酒，因酌以飲徐公，徐公醉而寐其侧，比醒，不复見二人，而宿草攒蔓其上，家人以為死也，丧服三年，服竟，徐公方反，今其處猶為徐公湖。","sortOrder":56},
  {"id":"s_work_nvlt_9_57","chapterId":"ch_work_nvlt_9","text":"裴氏《廣州記》曰：庐山顶有湖，廣數頃，有楊梅山桃，止得於上飽啖，不得持去。","sortOrder":57},
  {"id":"s_work_nvlt_9_58","chapterId":"ch_work_nvlt_9","text":"《秦州記》曰：武都山前有湖，冬夏無增减，義熙初，有白龍於此湖升天。","sortOrder":58},
  {"id":"s_work_nvlt_9_59","chapterId":"ch_work_nvlt_9","text":"邓德明《南康記》曰：平固縣覆笥山上，有太湖，周數十里，靈果異物，皆不可識。又有石雁，浮在湖中，每至秋天，石雁飛鳴，如候時也。","sortOrder":59},
  {"id":"s_work_nvlt_9_60","chapterId":"ch_work_nvlt_9","text":"《風土記》曰：陽羨縣東，有太湖，中有包山，山下有洞穴，潛行地中，雲無所不通，謂之洞庭地脈也。","sortOrder":60},
  {"id":"s_work_nvlt_9_61","chapterId":"ch_work_nvlt_9","text":"荆山記曰：巴陵南有青草湖，周回百里，日月出没其中，湖南有青草山，故因為名。","sortOrder":61},
  {"id":"s_work_nvlt_9_62","chapterId":"ch_work_nvlt_9","text":"【詩】晉李顒涉湖詩曰：旋經義興境，弭棹石蘭渚，震泽為何在，今唯大湖浦，圓径萦五百，眇目緬無睹，高天淼若岸，長津雜如縷。","sortOrder":62},
  {"id":"s_work_nvlt_9_63","chapterId":"ch_work_nvlt_9","text":"宋孝武濟曲阿後湖詩曰：宵登毗陵路，旦過雲陽郛，平湖曠津濟，菰渚迭明芜，和風翼歸采，夕氛晦山嵎，驚澜翻魚藻，赪霞照桑榆。","sortOrder":63},
  {"id":"s_work_nvlt_9_64","chapterId":"ch_work_nvlt_9","text":"宋謝靈運石壁還湖中作詩曰：昏旦变氣候，山水含清暉，清暉能娱人，遊子憺忘歸，出穀日尚早，入舟陽已微，林壑斂暝色，雲霞收夕霏，芰荷迭映暧，蒲稗相因依，披拂趍南迳，愉悅偃東扉。","sortOrder":64},
  {"id":"s_work_nvlt_9_65","chapterId":"ch_work_nvlt_9","text":"宋謝惠連汎南湖至石帆詩曰：軌息陆涂初，枻鼓川路始，涟漪繁波漾，參差層峰跱，萧疏野趣生，逶迤白雲起，登陟苦跋涉，〈目辟〉盼樂心耳，即玩玩有竭，在興興無已。","sortOrder":65},
  {"id":"s_work_nvlt_9_66","chapterId":"ch_work_nvlt_9","text":"梁元帝泛芜湖詩曰：桂潭連菊岸，桃李夹成蹊，石文如濯錦，雲飛似散珪，桡度菱根反，船去荇枝低，颿隨迎雨燕，鼓逐伺潮雞。","sortOrder":66},
  {"id":"s_work_nvlt_9_67","chapterId":"ch_work_nvlt_9","text":"梁范雲治西湖詩曰：史氏导漳水，西門溉河潮，圖始未能悅，克終良可要，擁锸勸年首，提爵勞春朝，平皋草色嫩，通林鳥聲娇，已集故池鶩，行蒔新田苗，何吁畚筑苦，方驩魚稻饒。","sortOrder":67},
  {"id":"s_work_nvlt_9_68","chapterId":"ch_work_nvlt_9","text":"陳陰铿渡青草湖詩曰：洞庭春溜滿，平湖錦帆張，源水桃花色，湘流杜若香，穴去茅山近，江連巫峡長，帶天澄迥碧，映日動浮光，行舟逗遠树，渡鳥息危樯，滔滔不可测，一苇詎能航。","sortOrder":68},
  {"id":"s_work_nvlt_9_69","chapterId":"ch_work_nvlt_9","text":"陳劉删汎宮亭湖詩曰：回舻乘泒水，舉帆逐分風，滉瀁疑無际，飄扬似度空，樯乌排鳥路，船影没河宮，孤石沧波里，匡山苦霧中，寄言千金子，安知萬里蓬。","sortOrder":69},
  {"id":"s_work_nvlt_9_70","chapterId":"ch_work_nvlt_9","text":"【賦】吳楊泉五湖賦曰：乃天地之玄源，陰陽之所徂，上值箕斗之精，與雲漢乎同模，受三方之灌溉，為百川之巨都，居楊州之大泽，苞吳越之具區，南與長江分體，東與巨海合流，太陰之所毖，玄靈之所遊，追湖水而往還，通蓬萊與瀛洲，爾乃詳觀其廣深之所極，延袤之規方，邈乎浩浩，漫乎洋洋，西合乎濛汜，東苞乎扶桑，日月於是出入，與天漢乎相望，左有苞山，連以醴渎，岝嵒崔嵬，穹窮紆曲，右有平原廣泽，蔓延旁薄，原隰陂阪，各有條格，茹芦菼薍，隱軫肴错，冲風之所去，零雨之所薄。","sortOrder":70},
  {"id":"s_work_nvlt_9_72","chapterId":"ch_work_nvlt_9","text":"《毛詩》曰：彼泽之陂，有蒲與荷。","sortOrder":72},
  {"id":"s_work_nvlt_9_73","chapterId":"ch_work_nvlt_9","text":"《史記》曰：高祖母曰劉媪，常息大泽之陂，夢與神遇。［事具帝王部中。］","sortOrder":73},
  {"id":"s_work_nvlt_9_74","chapterId":"ch_work_nvlt_9","text":"《淮南子》曰：譬若同陂而溉田，其愛水均也。","sortOrder":74},
  {"id":"s_work_nvlt_9_75","chapterId":"ch_work_nvlt_9","text":"《續漢書》曰：郭泰入汝南，交黃叔度，至南州，先過袁奉高，不宿而去，從叔度，累日，或以問泰，泰曰：袁奉高之器，譬諸軌濫，雖清而易挹也，叔度之器，汪汪若萬頃之陂，澄之而不清，混之而不濁，不可量也。","sortOrder":75},
  {"id":"s_work_nvlt_9_76","chapterId":"ch_work_nvlt_9","text":"《魏略》曰：明帝出次摩陂，有龍見於井中，帝出觀，因改摩陂為龍陂。","sortOrder":76},
  {"id":"s_work_nvlt_9_77","chapterId":"ch_work_nvlt_9","text":"漢宮殿疏曰：雁鶩陂，蓋地六頃，承崑明池下流。","sortOrder":77},
  {"id":"s_work_nvlt_9_78","chapterId":"ch_work_nvlt_9","text":"《抱朴子》曰：葛仙公每飲酒醉，常入家門前陂水中臥，竟日乃出。","sortOrder":78},
  {"id":"s_work_nvlt_9_79","chapterId":"ch_work_nvlt_9","text":"《汝南先賢傳》曰：鄭敬去吏，隱居於蚁陂之陽，以漁釣自娱，彈琴詠詩，常方坐於陂侧。","sortOrder":79},
  {"id":"s_work_nvlt_9_80","chapterId":"ch_work_nvlt_9","text":"《襄陽耆舊記》曰：宜城縣東北角，有熨斗陂。","sortOrder":80},
  {"id":"s_work_nvlt_9_81","chapterId":"ch_work_nvlt_9","text":"【詩】魏文帝於玄武陂作詩曰：兄弟共行遊，驅車出西城，野田廣开辟，川渠互相經，黍稷何鬱鬱，流波激悲聲，菱芡覆绿水，芙蓉發丹榮，柳垂重荫绿，向我池邊生，乘渚望長洲，群鳥讙譁鳴，萍藻泛濫浮，澹澹隨風傾。","sortOrder":81},
  {"id":"s_work_nvlt_9_82","chapterId":"ch_work_nvlt_9","text":"【銘】晉張載洪池陂銘曰：开源東註，出自城池，魚鱉炽殖，水鳥盈涯，菱藕狎獦，粳稻連畦，漸台中起，列馆參差，惟水泱泱，厥大難訾。","sortOrder":82},
  {"id":"s_work_nvlt_9_84","chapterId":"ch_work_nvlt_9","text":"《毛詩》曰：東門之池，可以漚麻。","sortOrder":84},
  {"id":"s_work_nvlt_9_85","chapterId":"ch_work_nvlt_9","text":"又曰：王在靈沼，於牣魚躍，［沼，池也。］《六韜》曰：殷君喜為酒池，回船糟丘，《穆天子傳》曰：天子西征，至於玄池，天子三日休於玄池之上，乃奏廣樂而歸，是曰樂池。","sortOrder":85},
  {"id":"s_work_nvlt_9_86","chapterId":"ch_work_nvlt_9","text":"又曰：天子觴西王母於瑤池之上，西王母為天子謠，［事具樂部。］","sortOrder":86},
  {"id":"s_work_nvlt_9_87","chapterId":"ch_work_nvlt_9","text":"韓詩外傳曰：齊景公出弋昭華之池也。","sortOrder":87},
  {"id":"s_work_nvlt_9_88","chapterId":"ch_work_nvlt_9","text":"《漢書》曰：贾山奏事吳王曰：吳有諸侯之位，而實富於天子，遊曲台，臨上路，不如朝夕之池，深壁高壘，副以闕城，不如長江之固，江淮之险。","sortOrder":88},
  {"id":"s_work_nvlt_9_89","chapterId":"ch_work_nvlt_9","text":"又曰：太液池中有蓬萊方丈瀛洲，象神山也。","sortOrder":89},
  {"id":"s_work_nvlt_9_90","chapterId":"ch_work_nvlt_9","text":"《魏志》曰：黃初三年，穿靈芝池。","sortOrder":90},
  {"id":"s_work_nvlt_9_91","chapterId":"ch_work_nvlt_9","text":"逸士傳曰：尧讓天子於許由，許由逃，巢父聞之，而洗耳於池。","sortOrder":91},
  {"id":"s_work_nvlt_9_92","chapterId":"ch_work_nvlt_9","text":"顧子曰：與子華遊東池，子華曰：水有四德，池為一焉，沐浴群生，泽流萬世，仁也，扬清激濁，涤荡尘秽，義也，弱而難勝，勇也，导江疏河，变盈流謙，智也，顧子曰：我得女於池上矣。","sortOrder":92},
  {"id":"s_work_nvlt_9_93","chapterId":"ch_work_nvlt_9","text":"《華陽國志》曰：滇池縣有泽水，周回二百里，所出深廣，下流淺狹，似如倒流，故俗曰滇池，長老傳言，池中有神馬，與家馬交，則生駿駒，世稱滇池駒，日行五百里。","sortOrder":93},
  {"id":"s_work_nvlt_9_94","chapterId":"ch_work_nvlt_9","text":"《襄陽記》曰：峴山南，習鬱大魚池，依范蠡養魚法，种楸芙蓉菱芡，山季倫每臨此池，辄大醉而歸，恒曰：比我高陽池也，城中小兒歌之曰：山公何所往，來至高陽池，日夕倒載歸，酩酊無所知。","sortOrder":94},
  {"id":"s_work_nvlt_9_95","chapterId":"ch_work_nvlt_9","text":"王羲之書雲，張芝臨池學書，池水盡黑，寡人躭之若是，未必後之，［事具藝部書篇。］","sortOrder":95},
  {"id":"s_work_nvlt_9_96","chapterId":"ch_work_nvlt_9","text":"《續述征記》曰：大梁西南七十里尉氏縣，有蓬池。","sortOrder":96},
  {"id":"s_work_nvlt_9_97","chapterId":"ch_work_nvlt_9","text":"《梁州記》曰：明月池南二里，有七女池。","sortOrder":97},
  {"id":"s_work_nvlt_9_98","chapterId":"ch_work_nvlt_9","text":"【詩】魏文帝芙蓉池詩曰：乘輦夜行遨，逍遙步西園，双渠相灌溉，嘉木繞通川，卑枝拂羽蓋，脩條摩蒼天，丹霞夹明月，華星出雲間，遨遊快心意，保己終百年。","sortOrder":98},
  {"id":"s_work_nvlt_9_99","chapterId":"ch_work_nvlt_9","text":"魏陳王曹植詩曰：逍遙芙蓉池，翩翩戲輕舟，南陽栖双鵠，北柳有鳴鳩。","sortOrder":99},
  {"id":"s_work_nvlt_9_100","chapterId":"ch_work_nvlt_9","text":"梁武帝首夏泛天池詩曰：薄遊朱明節，泛漾天淵池，舟楫互容與，藻蘋相推移，碧沚紅菡萏，白沙青涟漪，新枝拂舊石，殘花落故池，葉软風易出，草密路難披。","sortOrder":100},
  {"id":"s_work_nvlt_9_101","chapterId":"ch_work_nvlt_9","text":"梁簡文帝山池詩曰：日暮芙蓉水，聊登鳴鶴舟，飛舻飾羽毦，長幔覆緹紬，停舆依柳息，住蓋影空留，古树橫臨沼，新藤上掛樓，魚遊向闇集，戲鳥逗楂流。","sortOrder":101},
  {"id":"s_work_nvlt_9_102","chapterId":"ch_work_nvlt_9","text":"梁庾肩吾山池應令詩曰：阆苑秋光暮，金塘牧潦清，荷低芝蓋出，浪涌燕舟輕，逆湍留棹唱，帶穀聚笳聲，岸竹交臨浦，山桐迥出城，水逐雲峰闇，寒隨殿影生。","sortOrder":102},
  {"id":"s_work_nvlt_9_103","chapterId":"ch_work_nvlt_9","text":"梁王台卿山池詩曰：歷覽周仁智，登臨歡豫多，穿渠引金穀，辟道出銅駝，長桥時跨水，曲閣乍臨波，巖風生竹树，池香出芰荷，石幽衔細草，林末度橫柯。","sortOrder":103},
  {"id":"s_work_nvlt_9_104","chapterId":"ch_work_nvlt_9","text":"梁鮑至山池詩曰：望園光景暮，林觀歇雰埃，荷疏不礙楫，石淺好萦苔，風花逐榜轉，山路向桥开，树交樓影没，岸暗水光來。","sortOrder":104},
  {"id":"s_work_nvlt_9_105","chapterId":"ch_work_nvlt_9","text":"後魏溫子升春日臨池詩曰：光風動春树，丹霞起暮陰，嵯峨暎連璧，飄飖下散金，徒自臨濠渚，空复撫鳴琴，莫知流水曲，誰辯遊魚心。","sortOrder":105},
  {"id":"s_work_nvlt_9_106","chapterId":"ch_work_nvlt_9","text":"周庾信奉和山池詩曰：樂官多暇豫，望苑蹔回舆，鳴笳陵絕限，飛蓋歷通渠，桂亭花未落，桐門葉半疏，荷風驚浴鳥，桥影聚行魚，日落含山氣，雲歸帶雨餘。","sortOrder":106},
  {"id":"s_work_nvlt_9_107","chapterId":"ch_work_nvlt_9","text":"又晚宴崑明池詩曰：春餘足光景，趙李舊經過，上林棗腰細，新丰酒泛多，小船行釣里，新盤待摘荷，蘭皋徒稅駕，何處有凌波。","sortOrder":107},
  {"id":"s_work_nvlt_9_108","chapterId":"ch_work_nvlt_9","text":"又奉和初濬池成清晨臨泛詩曰：千金高堰合，百頃浚源开，翻逢積草浪，更識崑明灰，虎嘯風還急，雞鳴潮即來，時看青雀舫，遙逐貴舟回。","sortOrder":108},
  {"id":"s_work_nvlt_9_109","chapterId":"ch_work_nvlt_9","text":"周王襃玄圃濬池詩曰：長洲春水滿，臨汎廣川中，石壁如明鏡，飛桥類飲虹，垂楊夹浦绿，新桃緣迳紅，對樓還泊岸，迎波蹔守風，漁舟釣欲滿，莲房采半空，於茲臨北闕，非复坐牆東。","sortOrder":109},
  {"id":"s_work_nvlt_9_110","chapterId":"ch_work_nvlt_9","text":"又山池落日詩曰：竹馆掩荆扉，池光晦晚暉，孤舟隱荷出，輕棹染苔歸，浴禽時侣竄，驚羽忽单飛。","sortOrder":110},
  {"id":"s_work_nvlt_9_111","chapterId":"ch_work_nvlt_9","text":"陳徐陵山池應令詩曰：畫舸圖仙獸，飛艎掛采斿，榜人事金槳，釣女飾銀鉤，細萍時帶楫，低荷乍入舟，猿啼知穀晚，蝉噎覺山秋。","sortOrder":111},
  {"id":"s_work_nvlt_9_112","chapterId":"ch_work_nvlt_9","text":"又奉和山池詩曰：羅浮無定所，鬱島屢遷移，不覺因風雨，何時入後池，樓台非一势，臨玩自多奇，雲生對戶石，猿掛入朓枝。","sortOrder":112},
  {"id":"s_work_nvlt_9_113","chapterId":"ch_work_nvlt_9","text":"陳陰铿經丰城劍池詩曰：清池自湛淡，神劍久遷移，無复連星氣，空餘似月池，夹筱澄深渌，含風結細漪，唯有莲華萼，還想匣中雌。","sortOrder":113},
  {"id":"s_work_nvlt_9_114","chapterId":"ch_work_nvlt_9","text":"隋江總秋日崑明池詩曰：玄沼萧條望，遊人意緒多，終南雲影落，渭北雨聲過，蝉噪金堤柳，鷺飲石鯨波，珠來照似月，織處寫成河，詎知臨水叹，非复采莲歌。","sortOrder":114},
  {"id":"s_work_nvlt_9_115","chapterId":"ch_work_nvlt_9","text":"隋薛道衡遊崑明池詩曰：霸陵因靜退，靈沼暫徘徊，新船木蘭楫，舊宇豫樟材，荷心宜露泣，竹径重風來，魚潛疑刻石，沙闇似沉灰。","sortOrder":115},
  {"id":"s_work_nvlt_9_116","chapterId":"ch_work_nvlt_9","text":"【賦】晉張載濛汜池賦曰：麗華池之湛淡，开重壤以停源，激通渠於千金，承瀍洛之長川，挹洪流之汪濊，包素瀨之寒泉，既乃北通醴泉，東入紫宮，左面九市，右帶阆風，周墉建乎其表，洋波回乎其中，幽渎傍集，潛流獨註，仰承河漢，吐納雲霧，緣以采石，殖以嘉树，水禽育而萬品，珍魚產而無數，蒼苔汎濫。脩條垂幹，绿葉覆水，玄荫珍岸，紅莲煒而秀出，繁葩赩以煥烂，遊龍躍翼而上征，翔鳳因儀而下觀，想白日之納光，睹洪暉之皓旰，於是天子乘玉輦，時遨遊，排金門，出千秋，造绿池，鏡清流，翳華蓋以逍遙，攬魚釣之所收，纖緒掛而鳣鲔來，芳餌沉而鰋鯉浮，丰夥逾於巨壑，信可樂以忘忧。","sortOrder":116},
  {"id":"s_work_nvlt_9_117","chapterId":"ch_work_nvlt_9","text":"晉郭璞鹽池賦曰：水润下以作鹹，莫斯鹽之最靈，傍峻嶽以發源，池茫爾而海渟，嗟玄液之潛洞，羌莫知其所生，状委蛇其若漢，流漫漫以漭漭，吁凿凿以粲粲，色暠然而雪朗，扬赤波之煥烂，光旰旰以晃晃，隆陽映而不燋，洪涔沃而不長，磊崔〈山錄〉碓，鍔剡棋方，玉润膏津，雪白凌岡，粲如散玺，煥若布璋，烂然漢明，晃爾霞赤，望之絳承，即之雪積，翠涂內映，赪液外幂，動而愈生，損而茲益，若乃煎海鑠泉，或冻或漉，所贍不過一乡，所營不過鍾斛，飴戎見珍於西鄰，火井擅奇乎巴濮，豈若茲池之所產，帶神邑之名嶽，吸靈润於河汾，總膏液乎澮涑。","sortOrder":117},
  {"id":"s_work_nvlt_9_118","chapterId":"ch_work_nvlt_9","text":"宋謝莊悅曲池賦曰：北山兮黛柏，南江兮赪石，赪岸兮若虹，黛树兮如畫，暮雲兮十重，朝霞兮千尺，步東池兮夜未久，臥西窗兮月向山，引一息於魂內，扰百緒於眼前。","sortOrder":118},
  {"id":"s_work_nvlt_9_119","chapterId":"ch_work_nvlt_9","text":"【銘】隋江總芳林園天淵池銘曰：歲次執徐，月維大呂，爰命梓匠，廣脩畚锸，摽置舊趾，开浚昔基，東西弥望，雲霧之所澄荡，南北紆萦，虹霓之所引曜，晓川漾璧，似日御之在河宿，夜浪浮金，疑月輪之馳水府，前瞰萬雉，列榭參差，却拒三袭，危峦耸峭，朅鳥異禽，自學歌舞，神木靈卉，不知搖落，但叔皮覽海，序螭蛟之泛濫，吉甫臨舟，美柽松之蓊茸，尚复著在吟詠，緘彼緹緗，况我君門，盛事未紀，谬頒待詔，謹製銘雲，石溝溜密，蘭渚潮平，九華閣道，百丈層盈，液搖殿色，殿寫波明。","sortOrder":119},
  {"id":"s_work_nvlt_9_120","chapterId":"ch_work_nvlt_9","text":"【表】晉江逌諫凿北池表曰：伏承當凿北池及立閣道，雖湫阨陋小，用功甚微。又役不扰民，賦不及外，至簡至約，誠不可加，然於愚懷，實有眷眷。","sortOrder":120},
  {"id":"s_work_nvlt_9_122","chapterId":"ch_work_nvlt_9","text":"《爾雅》曰：水註川曰谿，山渎無所通曰谿。","sortOrder":122},
  {"id":"s_work_nvlt_9_123","chapterId":"ch_work_nvlt_9","text":"《管子》曰：桓公北征孤竹，至卑耳之谿，［事具武部。］","sortOrder":123},
  {"id":"s_work_nvlt_9_124","chapterId":"ch_work_nvlt_9","text":"《俗說》曰：郗僧施青溪中汎，到一曲之處，辄作詩一篇，謝益寿見詩笑曰：青谿之曲，复何窮盡。","sortOrder":124},
  {"id":"s_work_nvlt_9_125","chapterId":"ch_work_nvlt_9","text":"武昌記曰：樊山東有小谿，夏時懷袖恒有寒氣，故謂之寒谿。","sortOrder":125},
  {"id":"s_work_nvlt_9_126","chapterId":"ch_work_nvlt_9","text":"裴氏《廣州記》曰：管谿周圓丈餘，水極沸涌，如猛火煎油聲，《荆州記》曰：郦縣北五十里，有菊谿，源出縣西北五十里石涧山，東南流，會专水，兩岸多甘菊。","sortOrder":126},
  {"id":"s_work_nvlt_9_127","chapterId":"ch_work_nvlt_9","text":"盛弘之《荆州記》曰：桂陽郡西南宿山，水出註大谿，號曰橫谿，水甚深，冬夏不乾，俗謂之貪泉，飲者辄冒於财賄。","sortOrder":127},
  {"id":"s_work_nvlt_9_128","chapterId":"ch_work_nvlt_9","text":"【詩】梁任昉泛長谿詩曰：徇祿聚歸糧，依隱謝羁勒，絕物甘離群，長懷忽去國，長谿水東舍，震區窮水域，道遇垂纶叟，聊訪問津惑，弭楫申九言，無為累牵纆，長泛沧浪水，平明至曛黑。","sortOrder":128},
  {"id":"s_work_nvlt_9_129","chapterId":"ch_work_nvlt_9","text":"又落日汎舟東谿詩曰：黝黝桑柘繁，芃芃麻麥盛，交柯谿易陰，反景澄餘映，吾生雖有待，樂天庶知命，不學梁甫吟，唯識沧浪詠，田荒我有役，秩滿餘謝病。","sortOrder":129},
  {"id":"s_work_nvlt_9_130","chapterId":"ch_work_nvlt_9","text":"【賦】宋謝靈運長谿賦曰：潭結绿而澄清，瀨扬白而戴華，飛急聲之瑟汩，散輕文之涟羅，始鏡底以如玉，終積岸而成沙。","sortOrder":130},
  {"id":"s_work_nvlt_9_132","chapterId":"ch_work_nvlt_9","text":"《爾雅》曰：水註谿曰穀。","sortOrder":132},
  {"id":"s_work_nvlt_9_133","chapterId":"ch_work_nvlt_9","text":"《毛詩》曰：葛之覃兮，施於中穀，維葉萋萋。","sortOrder":133},
  {"id":"s_work_nvlt_9_134","chapterId":"ch_work_nvlt_9","text":"又曰：伐木丁丁，鳥鳴嘤嘤，出自幽穀，遷於乔木，［事具鳥部。］","sortOrder":134},
  {"id":"s_work_nvlt_9_135","chapterId":"ch_work_nvlt_9","text":"又曰：皎皎白駒，在彼空穀。","sortOrder":135},
  {"id":"s_work_nvlt_9_136","chapterId":"ch_work_nvlt_9","text":"《老子》曰：穀得一以盈，穀無以盈，將恐竭。","sortOrder":136},
  {"id":"s_work_nvlt_9_137","chapterId":"ch_work_nvlt_9","text":"《韓子》曰：昔齊桓公入山，問父老，此為何穀，答曰：臣舊畜牛生犢，以子買駒，少年謂牛不生駒，遂持而去，傍鄰謂臣愚，遂名為愚公穀，［說苑又載，事具人部諷篇。］","sortOrder":137},
  {"id":"s_work_nvlt_9_138","chapterId":"ch_work_nvlt_9","text":"《韓詩外傳》曰：孔子南遊適楚，至於阿穀之隧，有處子佩璜而浣者，孔子抽觴以授子貢曰：以觀其辭。","sortOrder":138},
  {"id":"s_work_nvlt_9_139","chapterId":"ch_work_nvlt_9","text":"劉向別錄曰：方士傳言，邹衍在燕，燕有穀，地美而寒，不生五穀，邹子居之，吹律而溫氣至，而穀生，今名黍穀。","sortOrder":139},
  {"id":"s_work_nvlt_9_140","chapterId":"ch_work_nvlt_9","text":"《漢武故事》曰：上微時行至柏穀，舍於逆旅，逆旅翁骂之，因從乞漿，翁曰：正有溺，無漿也。","sortOrder":140},
  {"id":"s_work_nvlt_9_141","chapterId":"ch_work_nvlt_9","text":"《博物志》曰：夏桀之時，為長夜宮於深穀之中，男女雜處，三旬不出聽政，其後大風扬沙，一夕填此穀。","sortOrder":141},
  {"id":"s_work_nvlt_9_142","chapterId":"ch_work_nvlt_9","text":"周景式庐山記曰：石門是一大穀，穀中有脩林萬頃，伟木千尋，日月之光罕照焉。","sortOrder":142},
  {"id":"s_work_nvlt_9_143","chapterId":"ch_work_nvlt_9","text":"戴延之《西征記》曰：梓泽，去洛城六十里，梓泽，金穀也，中朝賢達所集，賦詩猶存，是石崇居處。","sortOrder":143},
  {"id":"s_work_nvlt_9_144","chapterId":"ch_work_nvlt_9","text":"【賦】晉胡濟湹穀賦曰：嘉高岗之崇峻兮，臨玄穀以遠覽，仰高丘之崔嵬兮，望清川之澹澹，爾乃陟重险，涉榛薄，倚春木，臨幽壑，深穀豁以窈藹，高峰鬱而岝崿。","sortOrder":144},
  {"id":"s_work_nvlt_9_146","chapterId":"ch_work_nvlt_9","text":"《釋名》曰：涧，間也，言在兩山間也。","sortOrder":146},
  {"id":"s_work_nvlt_9_147","chapterId":"ch_work_nvlt_9","text":"《說文》曰：涧，山夹水也，從水間聲也。","sortOrder":147},
  {"id":"s_work_nvlt_9_148","chapterId":"ch_work_nvlt_9","text":"《爾雅》曰：山夹水曰涧。","sortOrder":148},
  {"id":"s_work_nvlt_9_149","chapterId":"ch_work_nvlt_9","text":"韓宣［字衍。］","sortOrder":149},
  {"id":"s_work_nvlt_9_150","chapterId":"ch_work_nvlt_9","text":"子曰：董安於為趙上地守，行右阜山，見深涧峭如牆，深百仞，問其乡左右曰：人嘗有入此乎，曰：無有，有婴兒狂聋人入此乎，曰：無有，有牛馬犬入此乎，曰：無有，安於叹曰：吾能治矣，使吾法之無改，猶入涧之必死，則民莫之犯也。","sortOrder":150},
  {"id":"s_work_nvlt_9_151","chapterId":"ch_work_nvlt_9","text":"《漢書》曰：沛公與項籍臨廣武涧而語，數籍以十罪。","sortOrder":151},
  {"id":"s_work_nvlt_9_152","chapterId":"ch_work_nvlt_9","text":"石崇金穀序曰：餘有別庐，在河南界金穀涧中，或高或下，有清泉茂树眾果竹木草藥之屬。","sortOrder":152},
  {"id":"s_work_nvlt_9_153","chapterId":"ch_work_nvlt_9","text":"《異苑》曰：苻堅為慕容冲所袭，堅馳騧馬，墯而落涧，追兵幾及，計無由出，馬即踟蹰臨涧，垂控與堅，堅不能及，馬又跪而授焉，堅授［《太平御覽》六十九作攀。］之，得登岸而走。","sortOrder":153},
  {"id":"s_work_nvlt_9_154","chapterId":"ch_work_nvlt_9","text":"【詩】梁劉孝威賦得曲涧詩曰：涧流急易轉，溪竹闇難开，近樓俄已失，前州忽复回，石岸生寒癬，沉根渍水苔，菱舟失道去，歸凫迷迳來。","sortOrder":154},
  {"id":"s_work_nvlt_9_155","chapterId":"ch_work_nvlt_9","text":"宋徐谖華林北涧詩曰：總長潭兮括遠源，下沉溜兮起輕泉，回溪浚兮曲沼阻，冲波激兮瀨淺淺，貫九穀兮積靈芝，飛清涛兮絜澄連。","sortOrder":155},
  {"id":"s_work_nvlt_9_157","chapterId":"ch_work_nvlt_9","text":"《說文》曰：浦，水濱也。","sortOrder":157},
  {"id":"s_work_nvlt_9_158","chapterId":"ch_work_nvlt_9","text":"《風土記》曰：大水小口別通為浦。","sortOrder":158},
  {"id":"s_work_nvlt_9_159","chapterId":"ch_work_nvlt_9","text":"《楚詞》曰：出溆浦而邅回。","sortOrder":159},
  {"id":"s_work_nvlt_9_160","chapterId":"ch_work_nvlt_9","text":"又曰：望美人兮南浦。","sortOrder":160},
  {"id":"s_work_nvlt_9_161","chapterId":"ch_work_nvlt_9","text":"《述征記》曰：興浦，舊魏步道，吳揭水灌之，今絕道為浦。","sortOrder":161},
  {"id":"s_work_nvlt_9_162","chapterId":"ch_work_nvlt_9","text":"顧微《廣州記》曰：溪浦口，有蒲母，養龍，裂斷其尾，因呼龍掘，人時見之，則土境大丰而利涉也。","sortOrder":162},
  {"id":"s_work_nvlt_9_163","chapterId":"ch_work_nvlt_9","text":"劉楨京口記曰：縣城東南大路，過長堽五里，得屠兒浦者，昔諸屠兒居此小浦，因以為名也。","sortOrder":163},
  {"id":"s_work_nvlt_9_164","chapterId":"ch_work_nvlt_9","text":"伏滔北征記曰：廣陵西一里水名公路浦，袁術自九江東奔袁谭於下邳，由此浦渡，因名也。","sortOrder":164},
  {"id":"s_work_nvlt_9_165","chapterId":"ch_work_nvlt_9","text":"【詩】梁簡文帝入溆浦詩曰：泛水入回塘，空枝度日光，竹垂懸扫浪，凫疑遠避樯。","sortOrder":165},
  {"id":"s_work_nvlt_9_166","chapterId":"ch_work_nvlt_9","text":"梁丘遲旦發漁浦潭詩曰：魚潭霧已开，赤亭風未颺，棹歌發中流，鳴鞞响沓嶂，村童忽相聚，野老時一望，诡怪石異象，危絕峰殊状，森森荒树齊，淅淅寒沙涨，藤垂島異陟，崖傾屿難傍。","sortOrder":166},
  {"id":"s_work_nvlt_9_167","chapterId":"ch_work_nvlt_9","text":"【表】宋王弘廣陵前浦开表曰：伏聞廣陵前浦，榛芜歷久，近复开除，清源虛邃，含明內鑒，瑞以數致，象以類應，夫如是者，鸞响鳳儀，可停屬而須矣。","sortOrder":167},
  {"id":"s_work_nvlt_9_169","chapterId":"ch_work_nvlt_9","text":"《史記》曰：韓聞秦之好興事，欲罢之，無令東伐，乃使水工鄭國間，說秦，令凿涇水，自中山，西抵瓠口，為渠，併北山，東註洛三百里，欲以溉田，中作而覺，欲殺鄭國，鄭國曰：始臣為間，然渠成，亦秦之利也，卒使就渠，渠就而用註四萬餘頃，收皆畝一鍾，於是關中為沃野，秦以富強，因命曰鄭國渠。","sortOrder":169},
  {"id":"s_work_nvlt_9_170","chapterId":"ch_work_nvlt_9","text":"《漢書》曰：張掖郡有千金渠。","sortOrder":170},
  {"id":"s_work_nvlt_9_171","chapterId":"ch_work_nvlt_9","text":"《地理書》曰：滎陽有浪荡渠。","sortOrder":171},
  {"id":"s_work_nvlt_9_172","chapterId":"ch_work_nvlt_9","text":"【頌】後漢蔡邕京兆樊惠渠頌曰：洪范八政，一曰食，周禮十職，一曰農，生民之本，於是乎出，丰殖财用，於是乎在，陽陵縣東，厥地汙泥，嘉穀不殖，光和五年，京兆尹樊君，勤恤民隱，乃命立新渠，曩之毒田，化為甘壤，相與謳談，斐然成章，謂之樊惠渠，其歌曰：我有長流，莫或閼之，我有溝澮，莫有達之，田畴斥滷，莫脩莫治，飢饉困瘁，莫恤莫思。","sortOrder":172},
  {"id":"s_work_nvlt_9_174","chapterId":"ch_work_nvlt_9","text":"盛弘之《荆州記》曰：隨郡北界，有九井，相傳神農既育，九井自穿。又雲，浚一井，則眾井水皆動。","sortOrder":174},
  {"id":"s_work_nvlt_9_175","chapterId":"ch_work_nvlt_9","text":"又曰：江陵縣東北十里天井台，東臨天井，井周回二里許，中有潛室，人時見之，辄有兵寇。","sortOrder":175},
  {"id":"s_work_nvlt_9_176","chapterId":"ch_work_nvlt_9","text":"戴延之《西征記》曰：太極殿上有金井金博山，鹿盧交龍，負山於井上，有金師子，在龍下。","sortOrder":176},
  {"id":"s_work_nvlt_9_177","chapterId":"ch_work_nvlt_9","text":"潯陽記曰：盆城，灌婴所筑，孫權經此城，自摽井地，令人掘之，正得故井，銘雲潁陰侯所开，雲三百年當塞，塞後不滿百年，當為應運者所开，權欣悅，以為己瑞，井甚深大，江中風浪，此井辄動，常當之。","sortOrder":177},
  {"id":"s_work_nvlt_9_178","chapterId":"ch_work_nvlt_9","text":"嵩高山記曰：少室山有雲母井。","sortOrder":178},
  {"id":"s_work_nvlt_9_179","chapterId":"ch_work_nvlt_9","text":"《異物志》曰：庐陵城中有一井，中有二色水，半青半黃，黃者灰汁，取作糜粥，皆作金色，土人名灰汁為金，因名為金井。","sortOrder":179},
  {"id":"s_work_nvlt_9_180","chapterId":"ch_work_nvlt_9","text":"《異苑》曰：句容縣有延陵季子廟，廟前井及渎，恒自涌沸，故曰沸井，於今猶然。","sortOrder":180},
  {"id":"s_work_nvlt_9_181","chapterId":"ch_work_nvlt_9","text":"又曰：臨邛有火井，漢室之隆，則炎赫弥炽，暨桓靈之际，火势漸微，諸葛亮一瞰而更盛。","sortOrder":181},
  {"id":"s_work_nvlt_9_182","chapterId":"ch_work_nvlt_9","text":"【詩】梁范雲詠井詩曰：乃鑒長林曲，有浚廣庭前，即源以為浪，因方自成圓，兼冬積溫水，叠暑必寒泉，不甘未應竭，既涸斷來翾。","sortOrder":182},
  {"id":"s_work_nvlt_9_183","chapterId":"ch_work_nvlt_9","text":"又悲故井詩曰：因舊未嘗改，緣甘故先竭，歷稔久無禽，一朝見开渫，泌泉既斯涌，短绠將安設。","sortOrder":183},
  {"id":"s_work_nvlt_9_184","chapterId":"ch_work_nvlt_9","text":"【賦】晉郭璞井賦曰：益作井，龍登天，凿後土，洞黃泉，潛源存溱，潏潏涓涓，爾乃冠玉槛，甃鱗错，鼓鹿盧，揮劲索，飛輕袪之繽紛，手爭鶩而互弱，長缧委蛇以曾萦，瑤瓮龍騰而洒激，乃回澄以靜映，状冏然而鏡灼，挹之不損，停之不溢，莫察其源，動而愈出，信润下而德施，壮邑移以不改，獨星陳於丘墟兮，越百代而猶在，守虛靜以玄澹兮，不東流而註海。","sortOrder":184},
  {"id":"s_work_nvlt_9_185","chapterId":"ch_work_nvlt_9","text":"晉孫楚井賦曰：苦行潦之滓濁，靡清流以自娱，乃喟爾而有感，率鄰左之數夫，脈厥土以興作，登甘醴於玄虛，渴人來翔，行旅是賴，輟耕息肩，不期而會，沉黃李，浮朱柰，雜狸首之班如，飛清尘以洮汰，枕玄石以盥嗽，喜遨怡以缓帶。","sortOrder":185},
  {"id":"s_work_nvlt_9_186","chapterId":"ch_work_nvlt_9","text":"晉江逌井賦曰：穿重壤之十仞兮，構玉甃之百節，營之不日，既汲既渫，潛流炤炤，寒泉冽冽，挹之不損，滀之不充，納而不處其有，興而不匮其丰，先王借象以辯義，君子擬淡以自綏，神龍來蟠以育鱗，列仙一嗽而雲飛。","sortOrder":186},
  {"id":"s_work_nvlt_9_187","chapterId":"ch_work_nvlt_9","text":"【贊】晉卞敬宗溝井贊曰：爰有邃井，冽彼下泉，引流重壤，合耀青天，蘊甘澄絜，湛爾終年，圖象懷惻，寄旨嘉荃。","sortOrder":187},
  {"id":"s_work_nvlt_9_188","chapterId":"ch_work_nvlt_9","text":"【銘】後漢李尤井銘曰：井之所尚，寒泉冽清，法律取象，不槩自平，多取不損，少汲不盈，執憲若斯，何有邪傾。","sortOrder":188},
  {"id":"s_work_nvlt_9_190","chapterId":"ch_work_nvlt_9","text":"《易坤卦》曰：初六，履霜堅冰至，象曰：履霜堅冰至，陰始凝也。","sortOrder":190},
  {"id":"s_work_nvlt_9_191","chapterId":"ch_work_nvlt_9","text":"《毛詩》曰：誕寘之寒冰，鳥覆翼之。","sortOrder":191},
  {"id":"s_work_nvlt_9_192","chapterId":"ch_work_nvlt_9","text":"又曰：二之日，凿冰冲冲，三之日，納於凌陰，二日，夏之十二月，三日，夏之正月，凿，取冰，冲冲，聲濬，凌陰，冰室也。《漢書》曰：晁错上書曰：夫胡鲗之地，積陰之處也，木皮三寸，冰厚六尺。","sortOrder":192},
  {"id":"s_work_nvlt_9_193","chapterId":"ch_work_nvlt_9","text":"孫盛《雜語》曰：王祥字休徵，性至孝，後母苛虐，欲危害祥，祥色養無怠，盛寒之月，後母曰：吾思生魚，祥脱衣，將剖冰求之，有少處冰解，下有魚出，因以奉養。","sortOrder":193},
  {"id":"s_work_nvlt_9_194","chapterId":"ch_work_nvlt_9","text":"《楚詞》曰：魂兮歸來，北方不可以止，增冰峨峨，飛雪千里。","sortOrder":194},
  {"id":"s_work_nvlt_9_195","chapterId":"ch_work_nvlt_9","text":"《邓析書》曰：明君之御民，若乘奔而無辔，履冰而負重也。","sortOrder":195},
  {"id":"s_work_nvlt_9_196","chapterId":"ch_work_nvlt_9","text":"《孫卿子》曰：冰生於水而寒於水。","sortOrder":196},
  {"id":"s_work_nvlt_9_197","chapterId":"ch_work_nvlt_9","text":"《淮南子》曰：見一葉之落，知歲之將暮，睹瓶中之冰，而知天下之寒，以近諭遠也。","sortOrder":197},
  {"id":"s_work_nvlt_9_198","chapterId":"ch_work_nvlt_9","text":"《左傳》曰：古者日在北陆而藏冰，西陆朝觌而出之，其藏冰也，深山窮穀，固陰冱寒，於是乎取之。","sortOrder":198},
  {"id":"s_work_nvlt_9_199","chapterId":"ch_work_nvlt_9","text":"《老子》曰：涣若冰將釋。","sortOrder":199},
  {"id":"s_work_nvlt_9_200","chapterId":"ch_work_nvlt_9","text":"《史記》曰：周紀曰：薑嫄為帝喾元妃，出里，見巨人跡而履之，身動如孕，暮而生子，以為不祥，弃於冰之上，鳥以翼覆荐之。","sortOrder":200},
  {"id":"s_work_nvlt_9_201","chapterId":"ch_work_nvlt_9","text":"《論衡》曰：夫然一炬火，爨一镬水，終日不熱也，倚一尺冰，置庖厨中，終夜不寒也，何則，微小之感，不能動大也，今邹衍之叹，不過如一炬尺冰，而皇天巨大，不徒镬水庖厨也，一夫仰叹，天為降霜，何天之易感，霜之易降也。","sortOrder":201},
  {"id":"s_work_nvlt_9_202","chapterId":"ch_work_nvlt_9","text":"《吳越春秋》曰：越王念吳，欲复怨，非一旦也，苦思勞心，夜以接日，冬寒則抱冰，夏熱則握火，愁心苦志，懸胆於戶，出入嘗之，不絕於口。","sortOrder":202},
  {"id":"s_work_nvlt_9_203","chapterId":"ch_work_nvlt_9","text":"魏子曰：危殆之國，治不益之民，是猶薄冰當白日，聚毛過猛火也。","sortOrder":203},
  {"id":"s_work_nvlt_9_204","chapterId":"ch_work_nvlt_9","text":"《博物志》曰：削冰令圓，舉以向日，以艾承其影，則有火出。","sortOrder":204},
  {"id":"s_work_nvlt_9_205","chapterId":"ch_work_nvlt_9","text":"束晳集曰：君聞薄冰凝池，非登廟之寶，零露垂林，非缀冕之飾，必將采素璧於層山，探圓珠於重泉也。","sortOrder":205},
  {"id":"s_work_nvlt_9_206","chapterId":"ch_work_nvlt_9","text":"【賦】晉顧凯之冰賦曰：激厲風而貞质，仰和景而融暉，清流離之光彻，邈雲英之巍巍，爾乃連綿絡幕，乍結乍無，義刚有折，照壶則虛，讬形超象，比朗玄珠，若乃上結薄暎，下鏡長泉，靈葩隨流，含馨楊鮮。","sortOrder":206},
  {"id":"s_work_nvlt_9_207","chapterId":"ch_work_nvlt_9","text":"晉庾倏［按當作儵。］冰井賦曰：嘉陰陽之博施，美天地之廣宣，萬物雜而無越，不易類以相幹，或专陽負暑，或固陰冱寒，涂雖殊而同歸，信协德而俱延。於是孟冬之月，群陰畢升，霜雪紛其交淪，流波結而成凌，啟南墉之重隩，將却熱以藏冰，納遠宮之邃宇，靜幽淡以清徵，抱堅精之玄素，發川靈而長凝，於是寒往暑來，四時代序，帝將攘患，炎灾是御，爾乃携我同類，援我蒸徒，將涉寒藪，害氣是除，攀靈艦而增舉，爰自讬於城隅，仰瞻重構，俯臨陰穴，凄清驚冷，觱發栗烈，餘寒嚴悴，凄若霜雪。","sortOrder":207},
  {"id":"s_work_nvlt_9_208","chapterId":"ch_work_nvlt_9","text":"【啟】梁沈約謝敕賜冰啟曰：竊惟司寒輟响，眇自前代，凌室曠官，歷茲永久，聖功闡物，逸典備甄，窮深既采，園池靡用，有籍羔秬，無灾霜雹。","sortOrder":208},
  {"id":"s_work_nvlt_9_210","chapterId":"ch_work_nvlt_9","text":"《說文》曰：津，水渡也，濮，小津也。","sortOrder":210},
  {"id":"s_work_nvlt_9_211","chapterId":"ch_work_nvlt_9","text":"《論語》曰：長沮桀溺，耦而耕，孔子過之，使子路問津焉，長沮曰：夫執舆者為誰，子路曰：孔丘，曰：是知津矣。","sortOrder":211},
  {"id":"s_work_nvlt_9_212","chapterId":"ch_work_nvlt_9","text":"《列女傳》曰：趙簡子南击楚，津吏醉臥，不能渡，簡子召，欲殺之，津吏女子，持楫而前曰：妾父聞君東渡不测之水，恐風波之起，故祷九江三淮之神，不勝巫祝杯酌餘瀝，醉至於此，妾原以鄙軀易父之死，簡子將渡，少一人，乃備員持楫，遂與渡，中流，發激棹之歌，簡子悅，以為夫人。","sortOrder":212},
  {"id":"s_work_nvlt_9_213","chapterId":"ch_work_nvlt_9","text":"續漢志曰：河東大陽縣，有茅津，北屈縣，有采桑津。","sortOrder":213},
  {"id":"s_work_nvlt_9_214","chapterId":"ch_work_nvlt_9","text":"【銘】後漢李尤孟津銘曰：洋洋河水，赴宗於海，經自中州，龍圖所在，黃函白神，赤符以信，昔有周武，集會孟津，魚入王舟，乃往克殷。","sortOrder":214},
  {"id":"s_work_nvlt_9_216","chapterId":"ch_work_nvlt_9","text":"《說文》曰：桥，水梁也，東楚謂桥為圯。","sortOrder":216},
  {"id":"s_work_nvlt_9_217","chapterId":"ch_work_nvlt_9","text":"紀年曰：周穆王三十七年，伐楚，大起九師，至於九江，比黿鼍為梁。","sortOrder":217},
  {"id":"s_work_nvlt_9_218","chapterId":"ch_work_nvlt_9","text":"《燕丹子》曰：燕太子丹质於秦，秦王遇之無禮，乃求歸，秦王為機發之桥，欲以陷丹，丹過之無虞，《戰國策》曰：豫讓欲為智伯報讎，趙襄子當出，伏於桥下，至桥馬驚，曰：必是豫讓也，求之果是。","sortOrder":218},
  {"id":"s_work_nvlt_9_219","chapterId":"ch_work_nvlt_9","text":"《史記》曰：秦昭王四十九年，初作河桥。","sortOrder":219},
  {"id":"s_work_nvlt_9_220","chapterId":"ch_work_nvlt_9","text":"又曰：文帝行出中渭，有一人從桥下走出，乘轝馬驚，使騎捕之，屬廷尉，廷尉張釋之治問，曰：縣人來，聞跸，匿桥下，見車騎即走耳，張廷尉奏，一人犯跸，當罰金，［漢書亦雲，事具官職部。］","sortOrder":220},
  {"id":"s_work_nvlt_9_221","chapterId":"ch_work_nvlt_9","text":"黃圖曰：秦始皇兼天下，都鹹陽，端門四達，以則紫宮，渭水貫都，以象天漢，橫桥南渡，以法牵牛，《論衡》曰：高麗國有侍婢，自雲有氣如雞子，來下我，故有身，後生子，曰東明，東明善射，王恐害其國，欲殺之，東明走至掩水，以弓击水，魚鱉浮而為桥梁，［事載魏略，亦具鱗介部。］","sortOrder":221},
  {"id":"s_work_nvlt_9_222","chapterId":"ch_work_nvlt_9","text":"蘇子曰：微生與婦人期，不來，水至，抱梁柱而死，［或作尾生。］王隱《晉書》曰：杜豫啟建河桥於富平津，眾論以為周所都，經聖賢而不作者，必不可作故也，豫曰：昔造舟為梁，則河桥之謂也，遂作桥成，上從百官臨會，舉杯勸豫曰：非君桥不立也，豫答詔曰：非陛下之明，臣亦不獲奉成聖製也，眾鹹稱善。","sortOrder":222},
  {"id":"s_work_nvlt_9_223","chapterId":"ch_work_nvlt_9","text":"【詩】梁簡文帝賦得桥詩曰：浮梁既冲崄，通波信可陵，乘空寫渭石，跨岸擬河冰，斜阑隱濁霧，布影入清渑，方知歌渌水，無待榜蒼鷹。","sortOrder":223},
  {"id":"s_work_nvlt_9_224","chapterId":"ch_work_nvlt_9","text":"又詠坏桥詩曰：虹飛亘林际，星度斷山隅，斜梁懸水跡，畫柱脱輕朱。","sortOrder":224},
  {"id":"s_work_nvlt_9_225","chapterId":"ch_work_nvlt_9","text":"又石桥詩曰：惠子臨濠上，秦王見海神，寫虹便欲飲，圖星逼似真。","sortOrder":225},
  {"id":"s_work_nvlt_9_226","chapterId":"ch_work_nvlt_9","text":"梁萧若靜石桥詩曰：連延過絕涧，迢遞跨長津，已數逢仙客，兼曾度獦人。","sortOrder":226},
  {"id":"s_work_nvlt_9_227","chapterId":"ch_work_nvlt_9","text":"梁徐摛坏桥詩曰：匝拦生闇藓，覆板没魚衣，岸曲斜梁岨，何時香步歸。","sortOrder":227},
  {"id":"s_work_nvlt_9_228","chapterId":"ch_work_nvlt_9","text":"周庾信看治渭桥詩曰：大夫參下位，司職渭之陽，富平移鐵钅巢，甘泉運石梁，跨虹連絕岸，浮黿續斷航，春洲湋鵡色，流水桃花香。","sortOrder":228},
  {"id":"s_work_nvlt_9_229","chapterId":"ch_work_nvlt_9","text":"周王襃和治渭桥詩曰：東流仰天漢，南度似牵牛，長堤通角道，飛梁跨造舟，使者开金堰，太守擁河流，廣陵候涛水，荆峡望陽侯，波生從故舶，沙涨涌新洲，天星識辯對，捡玉應沉鉤。","sortOrder":229},
  {"id":"s_work_nvlt_9_230","chapterId":"ch_work_nvlt_9","text":"陳陰铿賦得度岸桥詩曰：畫桥長且曲，傍崄复凭流，寫虹晴尚飲，圖星晝不收，跨波連斷岸，接路上危樓，欄高荷不及，池清影自浮，何必橫南渡，方复似牵牛。","sortOrder":230},
  {"id":"s_work_nvlt_9_231","chapterId":"ch_work_nvlt_9","text":"太宗文皇帝賦得浮桥詩曰：曲岸非千里，桥斜異七星，蹔低逢輦度，還高值浪驚，水搖文鹢動，纜轉錦花萦，遠近隨輪影，輕重應人行。","sortOrder":231},
  {"id":"s_work_nvlt_9_232","chapterId":"ch_work_nvlt_9","text":"梁庾肩吾石桥詩曰：秦王金作柱，漢帝玉為欄，仙人飛往易，道士出歸難。","sortOrder":232},
  {"id":"s_work_nvlt_9_233","chapterId":"ch_work_nvlt_9","text":"張文琮賦桥詩曰：造舟浮渭日，鞭石表秦初，星文遙泻漢，虹势尚凌虛，已授文成履，空題武騎書，別有臨濠上，栖偃獨觀魚。","sortOrder":233},
  {"id":"s_work_nvlt_9_234","chapterId":"ch_work_nvlt_9","text":"後周宗羁登渭桥詩曰：仲山朝飲馬，還坐渭桥中，南瞻臨別馆，北望盡離宮，四面衣裾合，三條冠蓋通，蘭香想和季，雲起憶成公，圯上相知早，雞鳴幸共同。","sortOrder":234},
  {"id":"s_work_nvlt_9_235","chapterId":"ch_work_nvlt_9","text":"《藝文類聚》　唐·欧陽詢","sortOrder":235},
  {"id":"s_work_nvlt_10_1","chapterId":"ch_work_nvlt_10","text":"卷十符命部","sortOrder":1},
  {"id":"s_work_nvlt_10_2","chapterId":"ch_work_nvlt_10","text":"○符命","sortOrder":2},
  {"id":"s_work_nvlt_10_3","chapterId":"ch_work_nvlt_10","text":"◇符命","sortOrder":3},
  {"id":"s_work_nvlt_10_4","chapterId":"ch_work_nvlt_10","text":"《春秋潛潭巴》曰：里社鳴，此里有聖人，其呴則百姓歸之，［社，里之君也，鳴則教令行，唯聖人能之，呴，鳴之怒也。］","sortOrder":4},
  {"id":"s_work_nvlt_10_5","chapterId":"ch_work_nvlt_10","text":"春秋合誠圖曰：尧母慶都，出觀三河，奄然陰風，赤龍與慶都合，生尧。","sortOrder":5},
  {"id":"s_work_nvlt_10_6","chapterId":"ch_work_nvlt_10","text":"《河圖》曰：湯母扶都，見白氣貫月，意感而生湯。","sortOrder":6},
  {"id":"s_work_nvlt_10_7","chapterId":"ch_work_nvlt_10","text":"《春秋元命苞》曰：殷紂之時，五星聚於房，房者蒼神之精，周據而興，［周起於房，而五星聚之，得天下之祥。］","sortOrder":7},
  {"id":"s_work_nvlt_10_8","chapterId":"ch_work_nvlt_10","text":"《尚書·中候》曰：季秋，赤雀衔丹書，入酆，止於昌戶，昌拜稽首，受最［最，要者也。］曰：姬昌蒼帝子。","sortOrder":8},
  {"id":"s_work_nvlt_10_9","chapterId":"ch_work_nvlt_10","text":"又曰：呂尚釣磻谿，得玉璜，刻曰：姬受命，呂佐旌，［旌，理也。］","sortOrder":9},
  {"id":"s_work_nvlt_10_10","chapterId":"ch_work_nvlt_10","text":"呂氏春秋曰：周文王時，見大赤鳥衔書，集於周社，文王曰：火氣勝，故其色上赤。","sortOrder":10},
  {"id":"s_work_nvlt_10_11","chapterId":"ch_work_nvlt_10","text":"《尚書·中候》曰：武王發渡於孟津，中流，白魚躍入王船，王俯取魚，長三尺，有文王字。","sortOrder":11},
  {"id":"s_work_nvlt_10_12","chapterId":"ch_work_nvlt_10","text":"《史記》曰：帝喾少妃有娀氏女簡狄，以春分玄鳥至之日，祀於高禖，有玄鳥遺其卵，簡狄吞之，孕，生契，為殷始祖。","sortOrder":12},
  {"id":"s_work_nvlt_10_13","chapterId":"ch_work_nvlt_10","text":"又曰：帝高陽氏元妃薑嫄，見大人之跡，履之，歆然若感，而生後稷，弃之寒冰之上，鳥翼覆之。又弃之隘巷，羊牛乳之。又弃之平林之上，人收養之，為周始祖。","sortOrder":13},
  {"id":"s_work_nvlt_10_14","chapterId":"ch_work_nvlt_10","text":"又曰：高祖母媪，嘗息大泽之陂，夢與神遇，時雷電晦冥，父太公往视，見蛟龍於上，已而有娠，遂生高祖。","sortOrder":14},
  {"id":"s_work_nvlt_10_15","chapterId":"ch_work_nvlt_10","text":"又曰：高祖被酒，夜經酆西泽中，令一人行前，行前者還報曰：前有大蛇當径，高祖乃前，拔劍斬蛇，蛇分為兩，道开，後人來至蛇所，有一老嫗夜哭，問之，嫗曰：吾子白帝子，化為蛇當道，今為赤帝子斬之，因忽不見。","sortOrder":15},
  {"id":"s_work_nvlt_10_16","chapterId":"ch_work_nvlt_10","text":"《漢書》曰：高祖元年，冬十月，五星聚於東井，從歲星也，［東井，秦分野，漢以義取天下之應也。］","sortOrder":16},
  {"id":"s_work_nvlt_10_17","chapterId":"ch_work_nvlt_10","text":"又曰：孝昭帝時，太山萊芜山南，汹汹有數千人聲，民视之，有大石自立，高丈五尺，大三十八围，入地深八尺，三石為足，石立後，有白乌數千集其旁，宣帝中興之瑞也。","sortOrder":17},
  {"id":"s_work_nvlt_10_18","chapterId":"ch_work_nvlt_10","text":"又曰：昭帝時，上林柳树斷，臥地，一朝起立，生枝葉，有虫食其葉，成文字，曰：公孫病已立。","sortOrder":18},
  {"id":"s_work_nvlt_10_19","chapterId":"ch_work_nvlt_10","text":"又曰：昌邑王問社，有枯树复生枝葉，眭孟以為木下民象，當有废改之象，公孫氏從民間受命為天子者，後宣帝立，帝本名病已。","sortOrder":19},
  {"id":"s_work_nvlt_10_20","chapterId":"ch_work_nvlt_10","text":"《隋巢子》曰：昔三苗大亂，天命夏禹於玄宮，有大神，人面鳥身，降而福之，司祿益富而國家實，司命益年而民不犮，四方歸之，禹乃克三苗，而神民不违。","sortOrder":20},
  {"id":"s_work_nvlt_10_21","chapterId":"ch_work_nvlt_10","text":"《墨子》曰：夏桀時，天乃命湯於驪宮，有神來告曰：夏德大亂，往攻之，予必使汝大戡之。","sortOrder":21},
  {"id":"s_work_nvlt_10_22","chapterId":"ch_work_nvlt_10","text":"又商王紂時，周武王見三神曰：予既沉渍殷紂於酒德矣，汝往攻之，予必使汝大戡之。","sortOrder":22},
  {"id":"s_work_nvlt_10_23","chapterId":"ch_work_nvlt_10","text":"《東觀漢記》曰：光武帝夜生時，有赤光，室中盡明，皇考異之，使卜者王長卜之，長曰：此善事，不可言，是歲有嘉禾生，一茎九穗，長大於凡禾，縣界大丰熟，因名上曰秀。","sortOrder":23},
  {"id":"s_work_nvlt_10_24","chapterId":"ch_work_nvlt_10","text":"又曰：光武從邯鄲避王郎兵，至呼沱河，导吏還言，河水流澌，無船，不可濟，左右皆惶，畏為王郎所及，上命王霸前往视之，實然，霸念還言驚眾，雖不可渡，且臨水止，尚可為阻，即白曰：冰堅可渡，士眾大喜，上大笑曰：果妄言也，叱至河，流澌冰合可履，彊以囊盛沙，布冰上，乃渡，渡未畢，而數車冰陷也。","sortOrder":24},
  {"id":"s_work_nvlt_10_25","chapterId":"ch_work_nvlt_10","text":"《琴操》曰：魯哀公十四年，西狩，薪者獲麟，击之，傷其左足。將以示孔子，孔子道與相逢見，俯而泣。抱麟曰：爾孰為來哉，孰為來哉，反袂拭面，仰视其人，龍顏日角。夫子奉麟之口，須臾吐三卷圖，一為赤伏，劉季興為王，二為周滅，夫子將終，三為漢製造，作《孝經》。夫子還謂子夏曰：新主將起，其人如得麟者。","sortOrder":25},
  {"id":"s_work_nvlt_10_26","chapterId":"ch_work_nvlt_10","text":"《帝王世紀》曰：燧人之世，有大跡出雷泽，華胥履之，生庖犧氏於成紀也。","sortOrder":26},
  {"id":"s_work_nvlt_10_27","chapterId":"ch_work_nvlt_10","text":"又曰：神龍感女登於常羊，生炎帝。","sortOrder":27},
  {"id":"s_work_nvlt_10_28","chapterId":"ch_work_nvlt_10","text":"又曰：電光繞北斗枢星，照郊野，感附寶，孕二十月，生黃帝於寿丘。","sortOrder":28},
  {"id":"s_work_nvlt_10_29","chapterId":"ch_work_nvlt_10","text":"又曰：黃帝時，有大星如虹，下流華渚，女節夢接之，意感，生少昊。","sortOrder":29},
  {"id":"s_work_nvlt_10_30","chapterId":"ch_work_nvlt_10","text":"又曰：陶唐之世，握登見大虹，意感，生舜於姚墟。","sortOrder":30},
  {"id":"s_work_nvlt_10_31","chapterId":"ch_work_nvlt_10","text":"又曰：脩巳山行，見流星貫昴，意感栗然。又吞神珠薏苡，焜坼而生禹。","sortOrder":31},
  {"id":"s_work_nvlt_10_32","chapterId":"ch_work_nvlt_10","text":"又曰：漢昭靈後名含始，遊浴池，有玉雞衔赤珠出，刻曰玉英，吞此者王，含始吞之，生高祖。","sortOrder":32},
  {"id":"s_work_nvlt_10_33","chapterId":"ch_work_nvlt_10","text":"魏氏春秋曰：明帝青龍三年，張掖郡删丹縣金山玄川溢，涌寶石負圖，状象靈龟，立於川西，有石馬七，其一仙人騎之，其一羁绊之，其五有形而不善成，有玉匣，开蓋於前，上有玉字，玉玦二，玉璜一。又有騏驎在東，鳳皇在南，白虎在西，犧牛在北，馬自中布列南方，有字曰：大讨曹，金但取之，此司馬氏革運之徵。","sortOrder":33},
  {"id":"s_work_nvlt_10_34","chapterId":"ch_work_nvlt_10","text":"《魏志》曰：桓帝時，有黃星見於楚宋之分，遼東殷馗，善天文，言後五十歲，當有真人起於梁沛之間，其鋒不可當，至是凡五十年，而太祖破袁紹，天下莫敵矣。","sortOrder":34},
  {"id":"s_work_nvlt_10_35","chapterId":"ch_work_nvlt_10","text":"《吳錄》曰：孫堅墓上數有光，如雲氣五色，上屬天，下蔓延數里，父老相謂曰：此非凡氣，孫氏其興乎。","sortOrder":35},
  {"id":"s_work_nvlt_10_36","chapterId":"ch_work_nvlt_10","text":"《吳書》曰：孫堅母懷妊，夢腸繞吳昌門，孫策母懷策，夢月入懷，懷孫權，夢日入懷，晉中興書，中宗元皇帝初誕，有神光之異，一室盡明，所藉藁如始刈。","sortOrder":36},
  {"id":"s_work_nvlt_10_37","chapterId":"ch_work_nvlt_10","text":"豫章記曰：松陽門內有大梓树，大四十五围，舉树盡枯死，永嘉中，一旦忽更榮茂，太興中，元皇帝果繼大業，庾仲初楊都賦所雲，瘣木薈於豫章，郭璞南郊賦雲，弊梓擢秀於祖邑也，宣帝祖為豫章太守，故雲祖邑也。","sortOrder":37},
  {"id":"s_work_nvlt_10_38","chapterId":"ch_work_nvlt_10","text":"臧榮緒《晉書》曰：王廙為鄱陽太守，有枯樟树更生，王敦表勸進中宗曰：皓獸應瑞而來臻，樟树久枯而更榮。","sortOrder":38},
  {"id":"s_work_nvlt_10_39","chapterId":"ch_work_nvlt_10","text":"孫盛《晉陽秋》曰：秦始皇時，望氣者言，五百年後，金陵之地，有天子氣，於是改金陵曰秣陵，巉北山，以絕其势，秦政東遊以厭之，後五百二十六年，而中宗即位於江南。","sortOrder":39},
  {"id":"s_work_nvlt_10_40","chapterId":"ch_work_nvlt_10","text":"又曰：太安中，歲镇辰太白四星，聚於牛女之間，後中宗即位於楊州也。","sortOrder":40},
  {"id":"s_work_nvlt_10_41","chapterId":"ch_work_nvlt_10","text":"武昌記曰：孫權獦於樊山，見一姥，問獦何得，答曰：止得一豹，姥曰：何不堅［《太平御覽》六百八十作竖。］其尾，忽然不見，因為立樊姥廟。","sortOrder":41},
  {"id":"s_work_nvlt_10_42","chapterId":"ch_work_nvlt_10","text":"徐爰《宋書》曰：武帝夜生，有神光之異，室內盡明，是夕，甘露降於墓树。","sortOrder":42},
  {"id":"s_work_nvlt_10_43","chapterId":"ch_work_nvlt_10","text":"又，高祖舉目瞻睞，常見二龍在焉，始尚微小，及貴，龍形漸長，光色轉明，左右侍者，亦數見徵異。","sortOrder":43},
  {"id":"s_work_nvlt_10_44","chapterId":"ch_work_nvlt_10","text":"《宋書》曰：高祖既登祚，謂群臣曰：朕始望不至此，眾人鹹撰辭，欲盛稱功德，王弘率爾對曰：所謂天命，求之不可得，推之不可去，眾皆以為知言。","sortOrder":44},
  {"id":"s_work_nvlt_10_45","chapterId":"ch_work_nvlt_10","text":"【文】漢司馬相如封禪文曰：伊上古之初肇，自昊穹之生民，歷選列辟，以迄於秦，率邇者踵武，逖聽者風聲，紛纶葳蕤，湮滅而不稱者，不可勝數也，繼昭夏，崇號謚，略可道者，七十有二君，書曰：元首明哉，股肱良哉，因斯以談，君莫盛於唐尧，臣莫賢於後稷，後稷創業於唐尧，公劉發跡於西戎，文王改製，大行厥成，故軌跡夷易，易遵也，湛恩厖鸿，易丰也，憲度著明，易則也，垂統理順，易繼也，是以業隆於襁褓，而崇冠於二後，未有殊尤絕跡，可考於今者也，然猶躡梁父，登泰山，建顯號，施尊名，大漢之德，烽［音蜂。］涌源泉，沕潏曼羨，旁魄四塞，雲布霧散，上畅九垓，下溯八埏，崑虫凯泽，回首面內，然後囿騶虞之珍群。儌麕鹿之怪獸，导一茎六穗於庖，犧双觡共牴之獸，招翠黃乘龍於沼，钦哉符瑞臻茲，猶以為德薄，不敢道封禪，蓋周躍魚陨航，休之以燎，此之為符也，以登介丘，不亦恧乎，進讓之道，何其爽與，於是大司馬進曰：陛下仁育群生，義征不譓，德侔往初，功無與二，意者泰山梁父，設壇場望幸，蓋上帝垂恩储祉，將以慶成，陛下謙讓而弗發也，契三神之歡，缺王道之儀，群臣恧焉，夫脩德以錫符，奉符以行事，不為進越也，故聖王不替，而脩禮地祗，謁款天神，勒功中嶽，以章至尊，皇皇哉斯事，天下之壮觀，王者之丕業，不可貶也，原陛下全之，俾萬世得激清流，扬微波，飛英聲，騰茂實，前聖之所以永保鸿名，而常為稱首者用此，宜命掌故，悉奏其儀而覽焉，於是天子沛然改容曰：俞乎，朕其誠哉，乃遷思回慮，總公卿之儀，詢封禪之事，詩大泽之博，演符瑞之富，遂作頌曰：自我天覆，雲之油油，甘露時雨，厥壤可遊，滋液渗漉，何生不育，嘉穀六穗，我穡曷蓄，匪唯雨之。又润泽之，匪唯遍之，我汜布護之，名山顯位，望君之來，君乎君乎，侯不邁哉，般般之獸，樂我君囿，白质黑章，其儀可嘉，旼旼穆穆，君子之態，蓋聞其聲，今親其來，厥途靡從，天瑞之徵，茲爾於舜，虞氏以興，濯濯之麟，遊彼靈畤，孟冬十月，君徂郊祀，馳我君舆，帝以享祉，宛宛黃龍，興德而升，正陽顯見，覺悟黎蒸，於傳載之，雲受命所乘，依類讬宇，喻以封峦，披藝觀之，天人之际已交，上下相發，允答聖王之德，兢兢翼翼，故曰：於興必慮衰，安必思危，是以湯武至尊嚴，不失肅祗，舜在假典，顧省闕遺，此之謂也。","sortOrder":45},
  {"id":"s_work_nvlt_10_46","chapterId":"ch_work_nvlt_10","text":"【頌】魏傅遐皇初頌雲，尋盛德以降應，著顯符於方臻，積嘉祚以待期，储鸿施於真人，昔九代之革命，鹹受天之休祥，匪至德其焉昭，匪至仁其焉章，懿大魏之聖後，固上天之所興，應靈運以承統，排閶阖以龍升，摅皇象以闡化，順帝則以播音，遵陽春以行施，揆四時以立信，運聰明以舉善，宣柔惠以養人，於赫我後，邁德如神，化不期月，令不浃辰，於是天地休豫，靈祗歡欣，嘉瑞雲集，四靈允臻，甘露霄零於宮庭，醴泉冬涌於中原，白雉素乌，丹芝朱魚，鱗集群萃，不可勝書，信應天之美瑞，受命之靈符也，然後覽公卿之谠議，詢百僚之典謨，天子乃登彫輦，戴羽蓋，佩玉锵锵，鑾聲哕哕，拜上皇，告受位，兆休祚，导神氣，於是建皇初之上元，發曠荡之明詔，眚灾肆赦，荡涤瑕秽，崇設九賓，溥延公卿，嘉羞千品，俎豆充庭，金石具懸，鍾鼓畢作，歌九功，舞八佾，鸿泽普，皇恩洽，民欲得，神望塞。","sortOrder":46},
  {"id":"s_work_nvlt_10_47","chapterId":"ch_work_nvlt_10","text":"【叙】後漢傅幹王命叙曰：昔在唐虞之禪，列於帝典，殷周之代，叙於詩書，天之歷數，昭焉著明，周篤後稷公劉，積德行仁，至乎文武，遂成王業，雖五德殊運，或禪或征，其变化應天，與時消息，其道一也，故雖有威力，非天命不授，雖有運命，非功烈不章，自我高祖，袭唐之統，受命龍興，讨秦滅項，光有萬國，世祖攘亂，奄复帝宇，人鬼协謀，徵祥煥然，皆順乎天而應乎人也，然則帝王之起，必有天命瑞應自然之符，明統顯祚丰懿之業，加以茂德成功，賢智之助，而後君臨兆民，為神明所保祐，永世所尊崇，未見運叙無紀次，勋泽不加於民，而可力爭觊觎神器者也，豪桀見二祖無尺地之階，為专智力，乘衅而起，不知天祚聖哲，帝王自有真也，哀哉，非徒闇於將來。又不考之於既往矣，自开辟已來，奸雄妄動，不識天命，勇如蚩尤，強如共工，威如夷羿，然皆從分橫裂，為天下戒。又况淺智小才，勇不足畏，強不足憚，未有成資，而敢失順，视不軌之事也哉，夫行潦之流，不致江海之深，丘垤之資，不成太山之高，魚鱉之類，不希雲龍之軌，一官之守，不經天人之变，當王莽之末，英雄四起，而邓禹耿弇，識世祖之福祚，贏糧間行，進其策謀，遂荷胥附之任，享佐命之寵，張玄慕蘇秦蒯通之業，周旋嚣述，西說窦融，言未及終，而梁統已誅之矣，禹弇見命祚之兆，其福如彼，張玄蔽逆順之理，其禍如此，審斯二事，趣舍之分明矣，且世祖之興有四，一曰帝皇之正統，二曰形相多異表，三曰體文而知武，四曰履信而好士，加之以聰明獨斷，達於事機，發策如神應，视遠如見近，偏旅首進，摧莽軍百萬之眾，单師獨征，平河北萬里之功，識邓隆之將败，知劉興之必死，然猶乾乾日昃，博采訓咨，拔吳漢於小尹，擢馬武於行伍，寵功臣以兼國之爵，顯卓茂以非次之位，言語政事文學之士，鹹盡其材，致之宰相，權勇畢力於征伐，搢紳悉心於左右，此其所以成大業也，高祖方娠，有雲龍之表，其始入秦，五星同軌，以旅於東井，在天之符也，世祖之徵符，其詳可聞也，其初育則靈光鑒於室隩，嘉禾滋於邑壤，其望舊庐，有火光之異，其渡呼沱，有河合之應，西門君惠，先識其讳，強華獻符，千里同验，劉歆改名而陨其身，王長错卦而見吉兆，故王遵謂之天授，非人力也，覽废興之運會，觀徵瑞之攸祚，審天應之萌兆，察人物之所附，念功成而道退，無非次而妄據，後之人，誠能昭然遠覽，曠然深悟，收莽述之闇惑，忠邓耿之弘慮，好謀而要成，臨事而知懼，距張玄之邪說，思在三之明數，則福祿衍於無窮，亦世不失其通路矣。","sortOrder":47},
  {"id":"s_work_nvlt_10_48","chapterId":"ch_work_nvlt_10","text":"【文】漢楊雄剧秦美新曰：上罔顯於羲皇，中莫盛於唐虞，邇靡著於成周，仲尼不遭用，春秋因斯發言，神明所祚，兆民所讬，罔不雲道德仁義禮智，獨秦崛起西戎，因襄文宣靈之僣跡，基孝公，茂惠文，奋昭莊，至政，破從擅衡，併吞六國，遂稱乎皇帝，盛從鞅儀韦斯之邪政，馳鶩起翦恬贲之用兵，刬滅古文，刮語燒書，弛禮崩樂，涂民耳目，遂流唐漂虞，涤殷荡周，然除仲尼之篇籍，自勒功業，改製度軌量，鹹稽之於秦紀，是以耆儒硕老，抱其書而永遯，禮官博士，卷其舌而不談，二世而亡，何其剧欤，帝王之道，兢兢乎不可離已，夫能貞而明之者窮祥瑞，困而昧之者極妭愆，故若古者稱尧舜，威侮者陷桀紂，况盡訊扫前聖數千載功業，专用己之私，而能享祜者哉，會漢祖龍騰酆沛，奋迅宛葉，自武關，與項戮力鹹陽，創業蜀漢，發跡三秦，克項山東，而帝天下，擿秦政惨酷尤煩者，應時蠲始，儒林刑辟歷紀圖典之用稍增焉，秦餘製度，項氏爵號，雖违古而猶袭之，是以帝典闕而不補，王綱弛而未張，逮至大新受命，上帝還資，後土顧懷，玄符靈契，雲動風偃，震聲日景，炎光飛响，盈塞天泉之間，乃奉若天命，窮寵極崇，與天剖神符，地合靈契，創亿兆，規萬世，卓哉煌煌，真天子之表也，若夫白鳩丹乌，素魚斷蛇，方斯蔑矣，是以發秘府，覽書林，遙集乎文雅之囿，翱翔乎禮樂之場，胤殷周之失業，紹唐虞之絕風，懿律嘉量，金科玉條，煥烂照耀，靡不宣臻，振鷺之聲充庭，鸿鸞之党漸階，俾前聖之緒，布濩流衍而不韞韣，鬱鬱乎煥哉，天人之事盛矣，鬼神之望充塞，紹少典之苗，著黃虞之裔，帝典闕者已補，王綱弛者既張，炳炳煒煒，豈不懿哉，而述前典，巡四民，迄四嶽，增封太山，廣禪梁甫，斯受命者之典業也，崇嶽渟海通渎之神，鹹設壇場，望受命之臻焉，海外遐方，信延頸企踵，回回內乡，喁喁如也，帝者雖勤讓，惡可以已乎，宜命賢哲，作典引一篇，以示來人，摛之罔極，令萬世常戴巍巍，履栗栗，嗅馨香，含甘實，鏡純粹之至精，聆清和之正聲，則百工伊凝，庶績越熙，荷天衢，提地釐，斯天下之上則已，庶可试哉。","sortOrder":48},
  {"id":"s_work_nvlt_10_49","chapterId":"ch_work_nvlt_10","text":"【論】後漢班彪王命論曰：昔在帝尧之禪曰：咨爾舜，天之歷數在爾躬，舜亦以命禹，既於稷契，鹹佐唐虞，光濟四海，弈世載德，至於湯武，而有天下，雖其遭遇異時，禪代不同，至於應天順民，其揆一焉，是故劉氏承尧之祚，氏族之世，著於春秋，唐據火德而紹之，始起沛泽，則神母夜號，以彰赤帝之符，由是言之，帝王之祚，必有明聖顯懿之德，丰功厚利積累之業，然後精誠通於神明，流泽加於生民，故能為鬼神所福乡，天下所歸往，未見運世無本，功德不紀，而得倔起在此位者也，世俗見高祖興於布衣，不達其故，以為適遭暴亂，得奋其劍，遊說之士，至比天下於逐鹿，幸捷而得之，不知神器有命，不可以智力求，悲夫，此世之所以多亂臣賊子者也，若然者，豈徒闇於天道哉。又不睹之於人事矣，夫饿饉流隸，飢寒道路，思有短褐之袭，擔石之蓄，所原不過一金，終於轉死溝壑，何則，貧窮亦有命也，况乎天子之貴，四海之富，神明之祚，可得而妄處哉，故雖遭罹厄會，竊其權柄，勇如信布，強如梁藉，成如王莽，然卒润镬伏锧，烹醢分裂。又况么么不及數子，而欲闇於天位者乎，是故駑蹇之乘，不騁千里之涂，燕雀之儔，不奋六翮之用，楶棁之材，不荷棟梁之任，斗筲之子，不執帝王之重，易曰：鼎折足，覆公餗，不勝其任也，當秦之末，豪杰併起，共推陳婴而王之，婴母止之曰：自吾為子家婦，而世貧賤，今卒富貴，不祥，不如以兵屬人，事成少受其利，不成禍有所歸，婴從其言，而陳氏以寧，王陵為漢將，而母獲於楚，有漢使來，陵母見之，謂曰：原告吾子，漢王長者，必得天下，子謹事之，無有二心，遂對漢使，伏劍而死，以固勉之，夫以疋婦之明，猶能推事理之致，探禍福之幾，而况大丈夫之事乎，是故窮達有命，吉凶由人，婴母知废，陵母知興，此二者帝王之分决矣，蓋在高祖，其興也有五，一曰帝尧之苗裔，二曰體濬多奇異，三曰神武有徵應，四曰宽明而仁恕，五曰知人善任使，加之以信誠，好謀達於聽受，見善如不及，用人如用己，從諫如順流，趍時如乡起，當食吐哺，納子房之策，拔足揮洗，揖郦生之說，寤戍卒之言，斷懷土之情，高四皓之名，割肌膚之愛，舉韓信於行陣，收陳平於亡命，英雄陳力，群策畢舉，此高祖之大略，所以成帝業也，若乃靈瑞符應。又可略聞矣，是以王武感物而折契，呂公睹形而進女，秦皇東遊以厭其氣，呂後望雲而知所處，始受命則白蛇分，西入關則五星聚，故淮陰留侯，謂之天授，非人力也，歷古今之得失，验行事之成败，取舍不厭斯位，符瑞不周斯度，而苟昧權利，越次妄據，外不量力，內不知命，則必丧保家之主，殀天年之寿，遇折足之凶，伏斧鉞之誅，英雄誠知覺寤，收陵婴之明分，絕信布之觊觎，拒逐鹿之瞽說，審神器之有授，貪不可冀，無為二母之所笑，則福祚流於子孫，天祿其永終矣。","sortOrder":49},
  {"id":"s_work_nvlt_10_50","chapterId":"ch_work_nvlt_10","text":"【典引】後漢班固典引曰：陶唐舍胤而禪有虞，［《文選》四十八重有虞二字。］亦命夏後，稷契熙載，越成湯武，股肱既周，天乃歸功元首，將授漢劉，俾其承三季之荒末，值亢龍之灾孽，懸象闇而恒文乖，彝倫斁而舊章缺，高光二聖，辰居其域，赫赫聖漢，巍巍唐基，溯测其源，乃先孕虞育夏，甄殷陶周，然後宣二祖之重光，袭四宗之緝熙，神靈日照，光被六幽，仁風翔於海表，威靈行乎鬼區，盛哉皇家帝世，德臣列辟，功君百王，榮鏡宇宙，涣楊宇內，是以來儀集羽族於觀魏，肉角馴毛宗於外囿，扰緇文皓质於郊，升黃辉采鱗於沼，甘露宵零於丰草，三足騫翥於茂树，若乃嘉穀靈草，奇獸神禽，應圖合謀，窮祥極瑞者，朝夕坰牧，日月邦畿，卓荦方州，羨溢乎要荒，昔周姬有素雉朱乌玄秬黃麰［莫侯。］之事耳，君臣動色，左右相趍，濟濟翼翼，峨峨如也，啟恭馆之金縢，御東序之秘寶，是時聖上固已垂精遊神，苞舉藝文，屢訪群儒，俞咨故老，與之斟酌道德之淵源，餚覈仁義之林藪，以望元符之臻焉，將伻萬嗣，扬洪暉，奋景炎，扇遺風，播芳烈，久而逾新，用而不竭，汪汪乎丕天之大律，其畴能亘之哉，唐哉皇哉，皇哉唐哉。","sortOrder":50},
  {"id":"s_work_nvlt_10_51","chapterId":"ch_work_nvlt_10","text":"【論】魏陳王曹植魏德論曰：元氣否塞，玄黃憤薄，星辰亂逆，陰陽舛错，四海鼎沸，萧條沙漠，武皇之興也，以道凌殘，義氣風發，神戈退指，則妭雰順製，靈弧雲舉，則朝扬播越，唯我聖後，神武蓋天，威光佐扫，辰彗北［韻補二作比。］弯，首尾爭击，氣齊率然，乃電北，［曹集詮評雲句有脱文。］席卷千里，隱乎若崩嶽，旰乎若潰海，慍彼蠻夏，蠢爾弗恭，脂我萧斧，簡武煉鋒，星陳而天運，振耀乎南封，荆人風靡，交益影從，軍蘊餘势，袭利乘權，荡鬼區於白水，摛矯製乎遐川，仰屬目於條支，晞弱水之潺湲，薄張騫於大夏，笑驃騎於祁連，其化之也如神，其養之也如春，柔遠能邇，誰敢不賓，憲度增飾，日耀月光，跡存乎建安，道隆乎延康，於是漢氏歸義，顧音孔昭，顯禪天位，布唐放尧，上猶謙謙弗納也，發不世之明詔，薄皇居而弗泰，蹈北人之清節，美石戶之高介，義貫金石，神明以興，神祗致祥，乾靈效祐，於是群公卿士，功臣列辟，率爾而進曰：昔文王三分居二，以服事殷，非能之而弗欲，蓋欲之而弗能，况天網不禁，皇綱圮紐，侯民非复漢萌，尺土非复漢有，故武皇創跡於前，陛下光美於後，蓋所謂勋成於彼，位定於此者也，將使斯民，播秬鬯，殖靈芝，鋤六穟，挹醴滋，遂乃凯風回回，甘露匝時，農夫詠於田垅，織婦吟而綜絲，黃吻之龀，含哺而怡，鲐背之老，击壤而嬉，古雖稱乎赫胥，曷若斯之大治乎，於時上富於春秋，聖德汪濊，奇志妙思，神鑒靈察，方將審御陰陽，增耀日月，極禎祥於遐奧，飛仁風以树惠，既遊精萬機，探幽洞深，逍遙六藝，兼覽儒林，抗思乎文藻之場囿，容與乎道術之彊畔，超天路而高峙，階清雲以妙觀，將參跡於三皇，豈徒論功於大漢，天地位矣，九域清矣，皇化四達，帝猷成矣，明哉元首，股肱貞矣，禮樂既作，興頌聲矣，固將封泰山，禪梁甫，歷名川以祈福，周五方之靈宇，越八九於往素，踵帝皇之靈矩，流餘祚於黎蒸，鍾元吉乎聖主。","sortOrder":51},
  {"id":"s_work_nvlt_10_52","chapterId":"ch_work_nvlt_10","text":"【述】魏邯鄲淳上受命述曰：伊上天闡載，自民主肇建，歷聽風聲，陶唐為盛，虞夏受終，殷周革命，有禪而帝，有代而王，禪代雖殊，大小繇同，於是以漢歷在魏，赤運歸黃也，是故大魏之業，皇耀震霆，肅清宇內，萬邦有截，師義翼漢，奉禮不越，飭躬戮力，茂亮弘烈，树深根以厚基，播醇泽以酿味，含光而弗耀，戢翼而弗發，將俟聖嗣，是遂是達，聖嗣承統，爰宣重光，陳錫裕下，民悅無彊，三神宜釐，四靈順方，元龟介玉，應龍粹黃，若雲魏德，據茲以昌，爾乃鳴玉陟壇，三搢以俟，既受休命，龍旋鳳峙，煌煌厥暉，穆穆容止，臨下有赫，允也天子，既踐帝位，納玺要绂，太常司燎，升炮告類，珪璋峨峨，髦士棣棣，蹌蹌聖躬，御策以莅，巍巍乎崇功，顯顯乎德容，信帝者之壮業，天休之所鍾也，於時天地交和，日月光精，氛祲不作，風尘弭清，凡在壇場之位，舉目乎廣庭，莫不君臣和德，鹹玉色而金聲，屢省萬機，訪謀老成，治詠儒墨，納策公卿，昧旦孜孜，夕惕乾乾，務在諧萬國，叙彝倫，而折不若，懷遠人，混六合之風，納於仁寿之門，刑错靡试，偃伯靡軍，然後乃勒功岱嶽，升中上玄，斯固我皇之大摹，思心之所存也。","sortOrder":52},
  {"id":"s_work_nvlt_10_53","chapterId":"ch_work_nvlt_10","text":"隋李德林天命論曰：有娀玄鳥，商以興焉，薑嫄巨跡，周以興焉，邑薑夢帝，隋以興焉，古今三代，靈命如一，天下之重，不可妄據，軒初四帝，周餘六王，藉势因基，自取而不得也，孟軻稱仲尼之德，過於尧舜，著述成帝者之事，弟子備王佐之才，墨不代蒼，泣麟叹鳳，恓恓汲汲，雖聖達而莫許也，蚩尤則黃神抗衡，共工則黑帝勍敵，項羽誅秦摧漢，宰神州，角逐爭驅，盡威力而無就也，其餘欻起妖妄，何足數乎，若使四凶執八元之誡，三監懷九臣之志，韓信彭越，深明帝子之符，孫述隗嚣，妙識真人之出，尉迥同謳歌之類，王謙比獄訟之民，福祿蝉聯，胡可窮也，而违天逆物，獲罪人神，呜呼，此前事之大戒矣，誅夷烹醢，歷代共尤，僣逆凶邪，時煩獄吏，其不戒慎何哉，蓋積惡既成，心自絕於善道，物類相感，理必至於誅戮，天奪其魄，鬼惡其盈，故也，大帝聰明，群臣正直，耳目監於率土，賞罰參於國朝，辅助一人，覆育兆庶，豈有食人之祿，受人之榮，苞藏禍心，不殲盡者也，必當執法未處其罪，司命已除其藉，自古明哲，慮遠防微，位尊而心愈下，祿厚而志弥約，納寵思之以懼，道高守之以恭，克念於此，則奸回不至，謙光滿覆，義在知幾，吉凶由人，妖不自作，夙沙則主雖愚蔽，民盡知歸，有苗則始為跋扈，終而大服，漢南諸國，見一面以從殷，河西將軍，率五郡而臣漢，故能招信順之助，保太山之安也","sortOrder":53},
  {"id":"s_work_nvlt_10_54","chapterId":"ch_work_nvlt_10","text":"【表】魏邯鄲淳上受命述表曰：臣聞雅頌作於盛德，典謨興於茂功，德盛功茂，傳序弗忘，是故竹帛以載之，金石以聲之，垂諸來世，萬載弥光，陛下以聖德應期，龍飛在位，其有天下也，恭己以受天子之籍，無為而四海順風，若乃天地顯應，休徵祥瑞，以表聖德者，不可勝載，鑠乎煥顯，真神明之所以祚，命世之令主也，凡自能言之類，莫不謳叹於野，執筆之徒，鹹竭文思，獻詩上頌，臣抱疾伏蓐，作書一篇，欲謂之頌，則不能雍容盛懿，列伸玄妙，欲謂之賦。又不能敷演洪烈，光扬緝熙，故思竭愚，稱受命述。","sortOrder":54},
  {"id":"s_work_nvlt_10_55","chapterId":"ch_work_nvlt_10","text":"《藝文類聚》　唐·欧陽詢","sortOrder":55},
  {"id":"s_work_nvlt_11_1","chapterId":"ch_work_nvlt_11","text":"卷十一帝王部一","sortOrder":1},
  {"id":"s_work_nvlt_11_2","chapterId":"ch_work_nvlt_11","text":"○總載帝王天皇氏地皇氏人皇氏有巢氏燧人氏太昊庖犧氏帝女媧氏炎帝神農氏黃帝軒轅氏少昊金天氏颛頊高陽氏帝喾高辛氏帝尧陶唐氏帝舜有虞氏禹夏後氏","sortOrder":2},
  {"id":"s_work_nvlt_11_3","chapterId":"ch_work_nvlt_11","text":"◇總載帝王","sortOrder":3},
  {"id":"s_work_nvlt_11_4","chapterId":"ch_work_nvlt_11","text":"尚書刑德放曰：帝者，天號也，王者，人稱也，天有五帝以立名，人有三王以正度，天子，爵稱也，皇者，煌煌也。","sortOrder":4},
  {"id":"s_work_nvlt_11_5","chapterId":"ch_work_nvlt_11","text":"《春秋演孔圖》曰：正氣為帝，間氣為臣，秀氣為人。","sortOrder":5},
  {"id":"s_work_nvlt_11_6","chapterId":"ch_work_nvlt_11","text":"《禮斗威儀》曰：帝者得其根核，王者得其英華，霸者得其附枝，故帝道不行，不能王，王道不行，不能霸，霸道不行，不能守其身。","sortOrder":6},
  {"id":"s_work_nvlt_11_7","chapterId":"ch_work_nvlt_11","text":"《管子》曰：明一者皇，察道者帝，通德者王，謀得兵勝者霸。","sortOrder":7},
  {"id":"s_work_nvlt_11_8","chapterId":"ch_work_nvlt_11","text":"《呂氏春秋》曰：始生之者天也，養成之者人也，能養天之所生而為天子。","sortOrder":8},
  {"id":"s_work_nvlt_11_9","chapterId":"ch_work_nvlt_11","text":"春秋考耀文曰：王者往也，神所输向，人所樂歸。","sortOrder":9},
  {"id":"s_work_nvlt_11_10","chapterId":"ch_work_nvlt_11","text":"《春秋繁露》曰：德俟天地者稱皇帝，天祐而子之，號稱天子。","sortOrder":10},
  {"id":"s_work_nvlt_11_11","chapterId":"ch_work_nvlt_11","text":"董子曰：古之人造文字者，三畫而連其中謂之王，三畫者，天地與人也，連中者，通其道也，取天地與人之才而參之，非王者其孰能當是，故王者必法天，以大仁覆育萬物，既化而生之。又養而成之。","sortOrder":11},
  {"id":"s_work_nvlt_11_12","chapterId":"ch_work_nvlt_11","text":"《韓詩外傳》曰：君者何，曰群也，敢群天下萬物而除其害者謂之君。","sortOrder":12},
  {"id":"s_work_nvlt_11_13","chapterId":"ch_work_nvlt_11","text":"《白虎通》曰：帝王者，號也，號者，功之表也，所以表功明德，號令臣下者也，德合天地者稱帝，仁義合者稱王，別優劣也。","sortOrder":13},
  {"id":"s_work_nvlt_11_14","chapterId":"ch_work_nvlt_11","text":"又曰：接上稱天子者，明以爵事天也，接下稱帝王者，明位號天下至尊之稱。","sortOrder":14},
  {"id":"s_work_nvlt_11_15","chapterId":"ch_work_nvlt_11","text":"漢雜事曰：古者天子稱皇，其次稱王，秦承百王之末，為漢驅除，自以德兼三皇五帝，故併為號。","sortOrder":15},
  {"id":"s_work_nvlt_11_16","chapterId":"ch_work_nvlt_11","text":"《帝王世紀》曰：孔子稱天子之德，感天地，洞八方，是以化合神者稱皇，德合天地者稱帝，仁義合者稱王。","sortOrder":16},
  {"id":"s_work_nvlt_11_17","chapterId":"ch_work_nvlt_11","text":"蔡邕《獨斷》曰：上者尊位所在也，太史令司馬遷記事，當言帝，則依违之，但言上，不敢泄［獨斷作渫，下同。］渎者尊號，言尊尊之義也，乘舆出於律文，曰敢盜乘舆服御物，謂天子所服食者也，天子至尊，不敢泄渎言之，故讬於乘舆也，天子以天下為家，不以京師宮室為常處，當乘舆以天下，故謂之車駕，天子自謂行在所，今雖在京師，言在行所也，巡狩天下，所奏事處皆為宮，在長安則曰長安宮，在泰山則曰泰山宮，唯當時所在。","sortOrder":17},
  {"id":"s_work_nvlt_11_18","chapterId":"ch_work_nvlt_11","text":"《禮記》曰：天子者，與天地參，德配天地，兼利萬物，與日月併明，明照四海，而不遺微小，其在朝廷，則道仁聖禮義之序，燕處則聽雅頌之音，行步則有環珮之聲，升車則有鸞和之音，居處有禮，進退有度，百官得其宜，萬事得其序。","sortOrder":18},
  {"id":"s_work_nvlt_11_19","chapterId":"ch_work_nvlt_11","text":"《六韜》曰：王者之道，如龍之首，高居遠望，深视而審聽，神其形而散其精，若天高而不可極，若川深而不可测，故可怒而不怒，臣乃為虎，可殺而不殺，大賊乃發，兵势不行，敵國乃強。","sortOrder":19},
  {"id":"s_work_nvlt_11_20","chapterId":"ch_work_nvlt_11","text":"《管子》曰：黃帝立明堂之議，上觀於賢也，尧有衢室之問，下聽於民也，舜有告善之旌，而主不蔽也，禹立諫鼓於朝，而備訊也，湯有總街之廷，觀民非也，武王有靈台之宮，賢者進也，此古聖帝明王，所以有而勿失，得而勿止也。","sortOrder":20},
  {"id":"s_work_nvlt_11_21","chapterId":"ch_work_nvlt_11","text":"《尸子》曰：孔子曰：商汝知君之為君乎，子夏曰：魚失水則死，水失魚猶為水也，孔子曰：商知之矣，《莊子》曰：赫胥氏之時，民居不知所為，行不知所之，含哺而熙，鼓腹而遊。","sortOrder":21},
  {"id":"s_work_nvlt_11_22","chapterId":"ch_work_nvlt_11","text":"又曰：昔容成氏大庭氏柏皇氏軒轅氏尊盧氏伏羲氏，當是時也，結繩而用之，甘其食，美其服，樂其俗，安其居，鄰國相望，雞狗之音相聞，民至老死，不相往來，若此時則至治也。","sortOrder":22},
  {"id":"s_work_nvlt_11_23","chapterId":"ch_work_nvlt_11","text":"《孫卿子》曰：人主者，守至約而詳，事至狹［荀子王霸篇作佚］而切，［王霸篇作功。］垂衣裳，不下簟席之上，而海內之民，莫不原得以為帝王。","sortOrder":23},
  {"id":"s_work_nvlt_11_24","chapterId":"ch_work_nvlt_11","text":"《呂氏春秋》曰：五帝先道而後德，故德莫盛焉，三王先德而後事，故事莫功焉，五伯先事而後兵，故兵莫強焉。","sortOrder":24},
  {"id":"s_work_nvlt_11_25","chapterId":"ch_work_nvlt_11","text":"《韓子》曰：明王製其臣下者，二柄而已矣，二者，刑，德也，殺戮之謂刑，慶賞之謂德。","sortOrder":25},
  {"id":"s_work_nvlt_11_26","chapterId":"ch_work_nvlt_11","text":"《淮南子》曰：帝者體太一，王者法陰陽，霸者則四時，君者用六律，體太一者，牢籠天地，彈壓山川，含吐陰陽，申洩四時，紀綱八極，經緯六合，覆露照导，普汜而無私，翾飛蠕動，莫不仰德而生，法陰陽，承天地之和，形萬類之體，含氣化物，以成形類，則四時者，春生，夏長，秋收，冬藏，取與有節，出入有時，开阖張斂，不失其序，喜怒刚柔，不雜其理，用六律者，生之與殺也，賞之與罰也，予之與奪也，非此無道。","sortOrder":26},
  {"id":"s_work_nvlt_11_27","chapterId":"ch_work_nvlt_11","text":"又曰：人主者，以天下之目视，以天下之耳聽，以天下之智慮，以天下之力動，是故號令能下究，而臣情得上聞，百官脩通，群臣輻凑，喜不以賞賜，怒不以罪誅。","sortOrder":27},
  {"id":"s_work_nvlt_11_28","chapterId":"ch_work_nvlt_11","text":"潛夫論曰：太古之時，兆黎初載，未有上下，而自順序，天未事焉，君未設焉，末後矯處，或相凌虐，為萌巨害，於是天命聖人，使司牧之，勿令失性，四海蒙利，草木被德，恭俭奉戴，謂之天子。","sortOrder":28},
  {"id":"s_work_nvlt_11_29","chapterId":"ch_work_nvlt_11","text":"【箴】晉潘尼乘舆箴曰：皇極肇建，兩儀既分，彝倫未序，萬邦糾紛，國事明主，家奉嚴君，各有攸尊，德用不勤，煌煌四海，藹藹萬乘，匪賢焉倚，匪哲焉凭，左辅右弼，前疑後承，一日萬機，業業兢兢，夫出其言善，則千里是應，而莫餘违，亦丧邦有徵，辛作璇室，而夏興瑤台，糟丘酒池，象箸玉杯，叔世道衰，末俗化淺，躭樂逸遊，荒淫沉湎，不式古訓，而好是佞辯，不遵正路，而覆車是踐，滅败之效，載在前典，匪唯凌夷，厥世用殄，故曰：树君如之何，將民是司牧，视之猶傷，知其寒燠，故能撫之斯柔，而敦之斯睦，無遠不懷，靡思不服，夫豈厭縱一人，而玩其耳目，內迷聲色，外荒馳逐，不修政事，而終於顛覆。","sortOrder":29},
  {"id":"s_work_nvlt_11_30","chapterId":"ch_work_nvlt_11","text":"【論】漢贾誼過秦論曰：秦孝公據崤函之固，擁雍州之地，君臣固守，以窥周室，有卷席天下，包舉宇內，囊括四海之意，併吞八荒之心，當是時也，商君佐之，內立法度，務耕織，脩守戰之具，外連衡而斗諸侯，諸侯恐懼，會盟而謀弱秦，不愛珍器重寶，肥饒之地，以致天下之士，合從締交，相與為一，當此之時，齊有孟嘗，趙有平原，楚有春申，魏有信陵，此四賢者，皆明智而忠信，宽厚而愛人，尊賢重士，約從連橫，兼韓魏燕楚宋衛中山之眾，嘗以什倍之地，百萬之師，仰關而攻秦，秦人开關延敵，九國之師，遁逃而不敢進，秦無亡矢遺鏃之費，天下諸侯已困矣，及至秦始皇，奋六世之餘烈，振長策而御宇內，吞二周而亡諸侯，履至尊而製六合，執敲扑以鞭笞天下，威振四海，南取百越之地，以為桂林象郡，百越之君，俯首系頸，委命下吏，乃使蒙恬，北筑長城而守藩篱，却匈奴七百餘里，胡人不敢南下而牧馬，士不敢弯弓而報怨，然後踐華為城，因河為池，據亿丈之城，臨不测之谿以為固，良將劲弩，守要害之處，信臣精卒，陳利兵而誰何，天下已定，始皇自以為關中之固，金城千里，子孫帝王萬世之業也，始皇既没，餘威振於殊俗，然而陳涉瓮牖繩枢之子，甿隸之人，而遷徙之徒也，材能不及中人，率罢散之卒，將數百之眾，轉而攻秦，山東豪俊，蜂起而亡秦族矣，且夫天下非小弱也，雍州之地，崤函之固，自若也，陳涉之位，非尊於齊楚燕趙魏宋衛中山之君也，鋤耰棘矜，非銛於鉤戟長鎩也，謫戍之眾，非抗於九國之師也，深謀遠慮，行軍用兵之道，非及曩時之士也，然而成败異变，功業相反，试使山東之國，與陳涉度長契大，比權量力，則不可同年而語矣，然秦以區區之地，致萬乘之權，招八州而朝同列，百有餘年矣，然後以六合為家，崤函為宮，一夫作難而七廟隳，身死人手，為天下之笑者，何也，仁義不施，而攻守之势異也。","sortOrder":30},
  {"id":"s_work_nvlt_11_31","chapterId":"ch_work_nvlt_11","text":"魏王粲難鍾荀太平論曰：聖莫盛於尧，而洪水方割，丹朱淫虐，四族凶佞矣，帝舜因之，而三苗畔戾矣，禹又因而防風為戮矣，此三聖古之所大稱也，繼踵相承，且二百年，而刑罰未嘗一世而乏也，然則此三聖能平，［明本作乎，三聖○聖下疑脱不字。］能平，則何世能致之乎，孔子稱曰：唯上智與下愚不移，不移者丹朱四凶三苗之謂也，當紂之世，殷岡不小大好草竊奸宄，周公遷殷顽民於洛邑，其下愚之人，必有之矣，周公之於三聖，不能逾也，三聖有所不化矣，有所不移矣，周公之不能化殷之顽民，所可知也，苟不可移，必或犯罪，罪而弗刑，是失所也，犯而刑之，刑不可错矣，孟軻有言，盡信書，不如無書，有大而言之者，刑错之屬也，豈亿兆之民，歷數十年，而無一人犯罪，一物失所哉，謂之無者，盡信書之謂也。","sortOrder":31},
  {"id":"s_work_nvlt_11_32","chapterId":"ch_work_nvlt_11","text":"魏曹冏六代論曰：昔者夏殷周，歷世數十，而秦二世而亡，何則，三代之君，與天下共其民，故天下同其忧，秦王獨製其民，故傾危而莫救，先王獨知［《文選》五十二作知獨。］治之不能久也，故與人共治之，知獨守之不能固也，故與人共守之，兼親疏而兩用，參同異而併立，是以輕重足以相镇，親疏足以相衛，兼併路塞，逆節不生，及其衰也，桓文率禮，包茅不貢，齊師伐楚，宋不城周，晉戮其宰，王綱弛而复張，諸侯傲而复肅，二霸之後，浸以陵遲，吳楚凭江，負固方城，雖心希九鼎，而畏迫宗姬，奸情散於胸懷，逆謀消於唇吻，斯豈非信重親戚，任用賢能，枝葉硕茂，本根賴之，至於王赧，降為庶人，猶枝幹相持，得居虛位，海內無主，四十餘年，秦據势勝之地，騁譎诈之術，征伐關東，蠶食九國，至於始皇，乃定天位，曠日若彼，用力若此，非深根固蒂，不拔之道乎，漢祖奋三尺之劍，騁乌合之眾，五年之中，而成帝業，自开辟已來，其興功立勋，未有若漢之易者也，夫伐深根者難為功，摧枯朽者易為力，理势然也，漢鑒秦之失，封植子弟，及諸呂擅權，圖危劉氏，而天下所以不傾動，百姓所以不易心者，徒以東牟朱虛，受命於內，齊代吳，楚，作衛於外，向使高祖踵亡秦之法，忽先王之製，則天下以傳，非劉氏有也，大魏之興，觀五代之存亡，而不用其長策，睹前車之傾覆，而不改其轍跡，子弟王空虛之地，君臣使民之失，［《文選》五十二作君有不使之民，魏志二十註引同，本句當有脱訛，明本臣作亡，亦未盡恰。］宗室竄於闾阎，不聞邦國之政，權均疋夫，势齊凡庶，內無深根不拔之固，外無盤石宗盟之助，非所以安社稷，為萬世之業也。","sortOrder":32},
  {"id":"s_work_nvlt_11_33","chapterId":"ch_work_nvlt_11","text":"晉陆機辨亡論曰：昔漢氏失御，奸臣竊命，禍基京畿，毒遍宇內，皇綱弛紊。王室遂卑，於是群雄蜂駭，義兵四合，吳武烈皇帝，慷慨下國，電發荆南，權略紛紜，忠勇伯世，威稜則夷羿震荡，兵交則丑虜授馘，遂扫清宗祊，蒸禋皇祖，於時雲興之將帶州，飆起之師跨邑，雖兵以義合，同盟戮力，然皆包藏禍心，阻兵怙亂，或師無謀律，丧威稔寇，忠規武節，未有如此其著者也，武烈既没，長沙桓王，逸才命世，弱冠秀發，招扰［冯校本同，明本及文選五十三作攬。］遺老，與之述業，神兵東驅，奋寡犯眾，攻無堅城之將，戰無交鋒之虜，誅叛柔服，而江外底定，飭法脩師，則威德翕赫，將北伐諸華，誅鉏幹紀，旋皇舆於夷庚，反帝座於紫闼，挟天子以令諸侯，清天步而歸舊物，戎車既次，群凶侧目，大業未就，中世而殒，用集我大皇帝，以奇蹤袭於逸軌，叡心因乎令圖，從政咨於故實，播憲稽乎遺風，而加之以篤固，申之以節俭，畴咨俊茂，好謀善斷，束帛旅於丘園，旌命交乎涂巷，故豪彦尋聲而响凑，志士希光而景鶩，異人輻凑，猛士如林，謀無遺谞，舉不失策，故遂割據山川，跨製荆吳，而與天下爭衡矣，故魏人請好，漢氏乞盟，遂跻天號，鼎峙而立，於是講八代之禮，蒐三王之樂，告類上帝，拱揖群後，虎臣毅卒，循江而守，長棘劲鎩，望飆而奋，庶尹盡規於上，四民展業於下，化协殊裔，風衍遐圻，乃俾一介行人，撫巡外域，巨象逸駿，扰於外閒，明珠玮寶，曜於內府，珍瑰重跡而至，奇玩應响而赴，輶軒騁於南荒，冲輣息於朔野，齊民免幹戈之患，戎馬無晨服之虞，而帝業固矣，爰及末葉，群公既丧，然後黔首有瓦解之志，皇家有土崩之衅，歷命應化而微，王師躡運而發，卒散於陣，民奔於邑，城池無蕃篱之固，山川無溝阜之势，軍未浃辰，而社稷夷矣，雖忠臣發憤，烈士死節，將奚救哉，夫曹劉之將，非一世所選，向時人［人字文選無。］之師，無曩日之眾，戰守之道，抑有前符，险阻之利，俄然未改，而成败貿理，古今诡趣，何哉，彼此之化殊，授任之才異也。","sortOrder":33},
  {"id":"s_work_nvlt_11_34","chapterId":"ch_work_nvlt_11","text":"又辨亡論下曰：昔三方之王，魏人據中夏，漢氏有岷益，吳製荆楊而掩交廣，曹氏雖功濟諸華，虐亦深矣，其民怨，劉翁因险飾智，功已薄矣，其俗陋，夫吳桓王基之以武，太祖成之以德，聰明睿達，懿度深遠矣，其求賢如弗及，恤民如稚子，接士盡盛德之容，親仁罄丹府之愛，拔呂蒙於戎行，擢潘濬於系虜，推誠信士，不恤人之我欺，量能授器，不患權之我逼，地方幾萬里，帶甲將百萬，其野沃，其民練，其器利，其财丰，東負沧海，西阻险塞，長江製其區宇，峻山帶其封域，國家之利，未巨有弘於茲者矣，借使中才守之以道，善人御之有術，敦率遺典，勤民謹政，脩定策，守常险，則可以長世永年，未有危亡之患，易曰：湯武革命順乎天，玄曰：亂不極則治不形，言帝王之因天時也，古人有言曰：天時不如地利，易曰：王侯設险，以守其國，言為國之恃险也。","sortOrder":34},
  {"id":"s_work_nvlt_11_35","chapterId":"ch_work_nvlt_11","text":"又曰：地利不如人和，在德不在险，言守险之由人也，吳之興也，參而由焉，孫卿所謂合其參者也，及其亡也，恃险而已。又孫卿所謂舍其參者也，夫四州之萌，非無眾也，大江之南，非乏俊也，山川之险，易守也，劲利之器，易用也，先政之策，易循也，功不興而禍遘，何哉，所以用之者失也，故先王達經國之長規，審存亡之至數，謙己以安百姓，敦惠以致人和，宽冲以誘俊人之謀，慈和以結士民之愛，是以其安也，則黎元與之同慶，及其危也，則兆庶與之同患，安與眾同慶，則危不可得也，危與下共患，則其難不足恤也，夫然故能保其社稷，而固其土宇，麥秀無悲殷之思，黍離無愍周之感矣。","sortOrder":35},
  {"id":"s_work_nvlt_11_36","chapterId":"ch_work_nvlt_11","text":"晉幹寶晉紀總論曰：昔高祖宣皇帝，以雄才硕量，應運而仕，至於百姓與能，大象始構矣，世宗承基，太祖繼業，始當非常之禮，終受備物之錫，至於世祖，遂享皇極，正位居體，聿脩祖宗之志，思辑戰國之苦，腹心不同，公卿異議，而獨納羊祜之策，至於鹹寧之末，遂排群議而杖王杜之决，汎舟三峡，介馬桂陽，役不二時，江湖來同，掩唐虞之舊域，班正朔於八荒，太康之中，天下書同文，車同軌，牛馬被野，餘糧栖畝，行旅草舍，外闾不閉，雖大平未洽，亦百代一時矣，二十餘年，而河洛為墟，戎羯稱製，二帝失尊，山陵無所，何哉，树立失權，讬付非才，四維不張，而苟且之政多也，夫天下之大器也，器大者不可以小道理，势重者不可以爭競扰，古先哲王，知其然也，是以扞其大患，而不有其功，御其大灾，而不尸其利，是以感而應之，悅而歸之，如晨風之鬱北林，魚龍之趨淵泽也，然後設禮文以理之，斷刑罰以威之，故眾悅其教，而安其俗，君子勤禮，小人盡力，廉恥篤於家闾，邪僻消於胸懷。又况可奋臂大呼，聚之以幹紀作亂之事乎，加之朝寡醇德之士，乡乏不二之老，風俗淫僻，趣向失所，學者以莊老為宗，而黜六經，談者以虛薄為辨，而賤名檢，當官者以望空為高，而笑勤恪，劉頌屢言治道，傅鹹每糾邪正，皆謂之俗吏，若夫文王日昃不暇食，仲山甫夙夜匪懈者，蓋共嗤黜，以為灰尘，而相詬病矣，由是毀譽亂於善惡之實，情慝奔於货欲之涂，選者為人擇官，官者為身擇利，其婦女莊櫛織纴，皆取成於婢仆，未嘗知女功絲枲之業，中饋酒食之事也，故皆不恥淫佚之過，不拘妒忌之惡，有殺戮妾媵，有黷亂上下，父兄不之罪，天下莫之非。又况责之闡四教於古，脩貞順於今，以辅佐君子者哉，禮法刑政，於此大坏，如室之斯構，而去其凿契，如水斯積，而决其隄防，如火斯畜，而離其薪燎也，國將亡，本必先顛，其此之謂乎。","sortOrder":36},
  {"id":"s_work_nvlt_11_37","chapterId":"ch_work_nvlt_11","text":"◇天皇氏","sortOrder":37},
  {"id":"s_work_nvlt_11_38","chapterId":"ch_work_nvlt_11","text":"項峻《始學篇》曰：天地立，有天皇十三頭，號曰天靈，治萬八千歲。","sortOrder":38},
  {"id":"s_work_nvlt_11_39","chapterId":"ch_work_nvlt_11","text":"《洞冥記》曰：一姓十三人也。","sortOrder":39},
  {"id":"s_work_nvlt_11_40","chapterId":"ch_work_nvlt_11","text":"徐整《三五歷紀》雲，歲起攝提，元氣肇，有神靈一人，有十三頭，號天皇。","sortOrder":40},
  {"id":"s_work_nvlt_11_41","chapterId":"ch_work_nvlt_11","text":"《春秋緯》曰：天皇地皇人皇，兄弟九人，分九州，長天下也。","sortOrder":41},
  {"id":"s_work_nvlt_11_42","chapterId":"ch_work_nvlt_11","text":"《遁甲开山圖》曰：天皇被跡，在柱州崑崙山下。","sortOrder":42},
  {"id":"s_work_nvlt_11_43","chapterId":"ch_work_nvlt_11","text":"◇地皇氏","sortOrder":43},
  {"id":"s_work_nvlt_11_44","chapterId":"ch_work_nvlt_11","text":"項峻《始學篇》曰：地皇十一頭，治八千歲。","sortOrder":44},
  {"id":"s_work_nvlt_11_45","chapterId":"ch_work_nvlt_11","text":"《帝系譜》曰：地皇治一萬八千歲，以火德王。","sortOrder":45},
  {"id":"s_work_nvlt_11_46","chapterId":"ch_work_nvlt_11","text":"《遁甲开山圖》曰：地皇興於熊耳龍門山。","sortOrder":46},
  {"id":"s_work_nvlt_11_47","chapterId":"ch_work_nvlt_11","text":"◇人皇氏","sortOrder":47},
  {"id":"s_work_nvlt_11_48","chapterId":"ch_work_nvlt_11","text":"項峻《始學篇》曰：人皇九頭，兄弟各三百歲，依山川土地之势财，度為九州，各居其一方，因是而區別，榮氏曰：人皇兄弟九人，生於刑馬山，身九色。","sortOrder":48},
  {"id":"s_work_nvlt_11_49","chapterId":"ch_work_nvlt_11","text":"◇有巢氏","sortOrder":49},
  {"id":"s_work_nvlt_11_50","chapterId":"ch_work_nvlt_11","text":"項峻《始學篇》曰：上古皆穴處，有聖人教之巢居，號大巢氏，皇甫謐以為有巢在女媧之後。","sortOrder":50},
  {"id":"s_work_nvlt_11_51","chapterId":"ch_work_nvlt_11","text":"《遁甲开山圖》曰：石樓山在琅琊，昔有巢氏治此山南。","sortOrder":51},
  {"id":"s_work_nvlt_11_52","chapterId":"ch_work_nvlt_11","text":"◇燧人氏","sortOrder":52},
  {"id":"s_work_nvlt_11_53","chapterId":"ch_work_nvlt_11","text":"《尚書大傳》曰：燧人為燧皇，以火紀官。","sortOrder":53},
  {"id":"s_work_nvlt_11_54","chapterId":"ch_work_nvlt_11","text":"《禮含文嘉》曰：燧人始鑽木取火，炮生為熟，令人無腹疾，遂天之意，故為燧人。","sortOrder":54},
  {"id":"s_work_nvlt_11_55","chapterId":"ch_work_nvlt_11","text":"◇太昊庖犧氏","sortOrder":55},
  {"id":"s_work_nvlt_11_56","chapterId":"ch_work_nvlt_11","text":"《易》曰：古者庖犧氏之王天下也，仰則觀象於天，俯則觀法於地，觀鳥獸之文，與地之宜，近取諸身，遠取諸物，於是始作八卦，以通神明之德，以類萬物之情，結繩而為網罟，以畋以漁，蓋取諸離。","sortOrder":56},
  {"id":"s_work_nvlt_11_57","chapterId":"ch_work_nvlt_11","text":"《禮含文嘉》曰：伏羲德洽上下，天應以鳥獸文章，地應以龟書，伏羲乃則象作易。","sortOrder":57},
  {"id":"s_work_nvlt_11_58","chapterId":"ch_work_nvlt_11","text":"《帝王世紀》曰：太昊帝庖羲氏，風姓也，蛇身人首，有聖德，都陳，作瑟三十六絃。","sortOrder":58},
  {"id":"s_work_nvlt_11_59","chapterId":"ch_work_nvlt_11","text":"【贊】魏陳王曹植庖羲贊曰：木德風姓，八卦創焉，龍瑞名官，法地象天，庖厨祭祀，罟網魚畋，瑟以像時，神德通玄。","sortOrder":59},
  {"id":"s_work_nvlt_11_60","chapterId":"ch_work_nvlt_11","text":"◇帝女媧氏","sortOrder":60},
  {"id":"s_work_nvlt_11_61","chapterId":"ch_work_nvlt_11","text":"《淮南子》曰：往古之時，四極废，九州裂，天不兼覆，地不周載，猛獸食精民。［精，善也。］鷙鳥攫老弱，於是女媧煉五色石，以補蒼天，斷鼇足，以立四方極，鼇，［大龟也。］蒼天神，四極正，淫水涸，冀州平，狡虫死，精民生，背方州，抱圓天。","sortOrder":61},
  {"id":"s_work_nvlt_11_62","chapterId":"ch_work_nvlt_11","text":"《帝王世紀》曰：帝女媧氏，亦風姓也，作笙簧，亦蛇身人首，一曰女希，是為女皇，其末諸侯共工氏，任知刑以強，伯而不王。","sortOrder":62},
  {"id":"s_work_nvlt_11_63","chapterId":"ch_work_nvlt_11","text":"【贊】魏陳王曹植女媧贊曰：古之國君，造簧作笙，禮物未就，軒轅纂成，或雲二皇，人首蛇形，神化七十，何德之靈。","sortOrder":63},
  {"id":"s_work_nvlt_11_64","chapterId":"ch_work_nvlt_11","text":"◇神農氏","sortOrder":64},
  {"id":"s_work_nvlt_11_65","chapterId":"ch_work_nvlt_11","text":"《易》曰：神農氏作，斫木為耜，楺木為耒，耒耨之利，以教天下，蓋取諸益，日中為市，致天下之货，交易而退，各得其所，蓋取諸噬嗑。","sortOrder":65},
  {"id":"s_work_nvlt_11_66","chapterId":"ch_work_nvlt_11","text":"《周書》曰：神農之時，天雨粟，神農耕而种之，作陶冶斤斧，為耜鉏耨，以墾草莽，然後五穀興，以助果蓏實。","sortOrder":66},
  {"id":"s_work_nvlt_11_67","chapterId":"ch_work_nvlt_11","text":"春秋《命歷序》曰：有神人，名石年，蒼色大眉，戴玉理，［玉理，猶玉英，神農也。］","sortOrder":67},
  {"id":"s_work_nvlt_11_68","chapterId":"ch_work_nvlt_11","text":"《呂氏春秋》曰：神農教曰：士有當年不耕者，則天下或受其飢矣，女有當年不績者，則天下或受其寒矣，故夫親耕，妻親績。","sortOrder":68},
  {"id":"s_work_nvlt_11_69","chapterId":"ch_work_nvlt_11","text":"《贾誼書》曰：神農以為走禽難以久養民，乃求可食之物，嘗百草，察實醎苦之味，教民食穀。","sortOrder":69},
  {"id":"s_work_nvlt_11_70","chapterId":"ch_work_nvlt_11","text":"《帝王世紀》曰：炎帝神農氏，薑姓也，人身牛首，長於薑水，有聖德，都陳，作五絃之琴，始教天下种穀，故號神農氏，諸侯夙沙氏，叛不用命，箕文諫而殺之，炎帝退而脩德，夙沙之民，自攻其君，而歸炎帝。","sortOrder":70},
  {"id":"s_work_nvlt_11_71","chapterId":"ch_work_nvlt_11","text":"【贊】魏陳王曹植神農贊曰：少典之胤，火德承木，造為耒耜，导民播穀，正為雅琴，以畅風俗。","sortOrder":71},
  {"id":"s_work_nvlt_11_72","chapterId":"ch_work_nvlt_11","text":"◇黃帝軒轅氏","sortOrder":72},
  {"id":"s_work_nvlt_11_73","chapterId":"ch_work_nvlt_11","text":"《易》曰：黃帝垂衣裳而天下治，蓋取乾坤也。","sortOrder":73},
  {"id":"s_work_nvlt_11_74","chapterId":"ch_work_nvlt_11","text":"《左傳》曰：剡子曰：黃帝以雲紀官，故為雲師而雲名。","sortOrder":74},
  {"id":"s_work_nvlt_11_75","chapterId":"ch_work_nvlt_11","text":"河圖挺佐辅曰：黃帝脩德立義，天下大治，乃召天老而問焉，餘夢見兩龍，挺白圖，以授餘於河之都，天老曰：河出龍圖，雒出龟書，紀帝錄，列聖人之姓號，興謀治太平，然後鳳皇處之，今鳳凰以下三百六十日矣，天其受帝圖乎，黃帝乃祓斋七日，至於翠妫之川，大鱸魚折溜而至，乃與天老迎之，五色畢具，魚汎白圖，蘭葉朱文，以授黃帝，名曰錄圖。","sortOrder":75},
  {"id":"s_work_nvlt_11_76","chapterId":"ch_work_nvlt_11","text":"《龍魚河圖》曰：黃帝時，有蚩尤，兄弟八十一人，併獸身人語，銅頭鐵額，食沙石子，造立兵杖，刀戟大弩，威振天下，誅殺無道，不仁慈，萬民欲令黃帝行天下事，黃帝仁義，不能禁蚩尤，黃帝仰天而叹，天遣玄女下，授黃帝兵信神符，製伏蚩尤，帝因使之主兵，以製八方，蚩尤没後，天下复扰亂，黃帝遂畫蚩尤形像，以威天下，天下鹹謂蚩尤不死，八方萬邦，皆為弭伏。","sortOrder":76},
  {"id":"s_work_nvlt_11_77","chapterId":"ch_work_nvlt_11","text":"《春秋內事》曰：軒轅氏以土德王天下，始有堂庑，高棟深宇，以避風雨。","sortOrder":77},
  {"id":"s_work_nvlt_11_78","chapterId":"ch_work_nvlt_11","text":"《列子》曰：黃帝喜天下之戴己也，養正命，娱耳目，乃喟然叹曰：養一己，治萬物，其患如此，於是放萬機，舍宮寢，退而間居大庭之馆，斋心服形，三月不親政事，晝寢而夢遊於華胥，華胥氏國，不知距齊國幾千里，［齊，中國。］蓋非舟車足力之所及，神遊而已，其國入水不溺，入火不熱，乘空如履實，寢虛若處床，黃帝既{宀悟}，怡然自得。又二十八年，天下大治，幾若華胥國矣。","sortOrder":78},
  {"id":"s_work_nvlt_11_79","chapterId":"ch_work_nvlt_11","text":"《淮南子》曰：黃帝治天下，而力牧太山稽辅之，使強不得掩弱，眾不得暴寡，人民保命而不夭，歲時熟而不凶，百官正而無私，辅弼公而不阿，道不拾遺，市不預贾，城郭不閉，邑無盜賊，人相讓以财，狗彘吐菽粟於道路，而無忿爭之心，於是日月精明，星辰不失其行，風雨時節，五穀登熟，虎豹不妄噬，鷙鳥不妄搏，鳳皇翔於庭，麒麟遊於郊，青龍進駕，飛煌伏皂，［飛黃出西方，其状如狐，背上有角，乘之寿千歲，皂，歷也。］諸北儋耳之國，莫不獻其貢職，［皆北極之夷國。］","sortOrder":79},
  {"id":"s_work_nvlt_11_80","chapterId":"ch_work_nvlt_11","text":"《史記·封禪書》曰：黃帝得仙上天，群臣葬其衣冠，《帝王世紀》曰：黃帝有熊氏，少典之子，姬姓也，生寿丘，長於姬水，龍顏，有聖德，受國於有熊，居軒轅之丘，故因以為號，治五氣，設五量，及神農氏衰，黃帝脩德撫民，諸侯鹹去神農而歸之，黃帝於是乃扰馴猛獸，與神農氏戰於版泉之野，三戰而克之。又徵諸侯，使力牧神皇直讨蚩尤氏，擒之於涿鹿之野，使應龍殺之於凶黎之丘，凡五十二戰，而天下大服，有妃，［《太平御覽》七十九妃上有四字。］生二十五子，黃帝在位百年而崩，年百一十歲矣，或傳以為仙，或言寿三百歲，葬於上郡陽周之桥山。","sortOrder":80},
  {"id":"s_work_nvlt_11_81","chapterId":"ch_work_nvlt_11","text":"《抱朴子》曰：黃帝生而能言，役使百靈，可謂天授自然體之者，猶复不敢端坐而得道，故陟王屋而受丹經，到鼎湖而飛流珠，登崆峒而問廣成，之具茨而事大隗，適東岱而奉中黃，入金穀而谘子心，論导養而质玄素二女，精推步則訪山稽力牧，講占候則詢風後，著體诊則受雷岐，審攻戰則納五音之策，窮神奸則記［抱朴子極言篇記下有白字。］泽之辭，相地理則書青乌之說，救傷殘則缀金冶之術，故能畢記秘要，窮盡道真，遂勒升龍以高濟，與天地乎岡極。","sortOrder":81},
  {"id":"s_work_nvlt_11_82","chapterId":"ch_work_nvlt_11","text":"【頌】晉牵秀黃帝頌曰：邈矣黃軒，應天載靈，通幽遠覽，觀象設形，誕敷厥訓，彝倫攸經，德從風流，化與雲征，皇猷允塞，地平天成，爰登方嶽，封禪勒成，紛然鳳舉，龍騰大清，违茲九土，陟彼高冥，民斯攸慕，涕泗沾纓，遐而不墜，式頌德聲。","sortOrder":82},
  {"id":"s_work_nvlt_11_83","chapterId":"ch_work_nvlt_11","text":"【贊】魏陳王曹植黃帝贊曰：少典之孫，神明聖哲，土德承火，赤帝是滅，服牛乘馬，衣裳是製，氏雲名官，功冠五列。","sortOrder":83},
  {"id":"s_work_nvlt_11_84","chapterId":"ch_work_nvlt_11","text":"又黃帝三鼎贊曰：鼎质文精，古之神器，黃帝是鑄，以像太一，能輕能重，知凶識吉，世衰則隱，世和則出。","sortOrder":84},
  {"id":"s_work_nvlt_11_85","chapterId":"ch_work_nvlt_11","text":"晉曹毗黃帝贊曰：軒轅應玄期，幼能總百神，體煉五靈妙，氣含雲露津，摻石曾城岫，鑄鼎荆山濱，豁焉天扉辟，飄然跨騰鱗，儀辔洒長風，褰裳躡紫宸。","sortOrder":85},
  {"id":"s_work_nvlt_11_86","chapterId":"ch_work_nvlt_11","text":"周庾信黃帝見廣成畫贊曰：治身紫府，問政青丘，龍湖鼎没，丹竈珠流，疏雲即雨，落木先秋，至道須極，長生可求。","sortOrder":86},
  {"id":"s_work_nvlt_11_87","chapterId":"ch_work_nvlt_11","text":"◇少昊金天氏","sortOrder":87},
  {"id":"s_work_nvlt_11_88","chapterId":"ch_work_nvlt_11","text":"《左傳》曰：郯子曰：我高祖少昊挚之立也，鳳鳥適至，故紀於鳥，為鳥師而鳥名焉。","sortOrder":88},
  {"id":"s_work_nvlt_11_89","chapterId":"ch_work_nvlt_11","text":"《帝王世紀》曰：少昊帝名挚，字青陽，姬姓也，降居江水，有聖德，邑於窮桑，以登帝位，都曲阜，故或謂之窮桑，即圖讖所謂白帝朱宣者也，故稱少昊，號金天氏，在位百年而崩。","sortOrder":89},
  {"id":"s_work_nvlt_11_90","chapterId":"ch_work_nvlt_11","text":"【贊】陳思王曹植少昊贊曰：祖自軒轅，青陽之裔，金德承土，儀鳳帝世，官鳥號名，殊職別系，農正扈氏，各有品製。","sortOrder":90},
  {"id":"s_work_nvlt_11_91","chapterId":"ch_work_nvlt_11","text":"◇颛頊高陽氏","sortOrder":91},
  {"id":"s_work_nvlt_11_92","chapterId":"ch_work_nvlt_11","text":"《史記》曰：帝颛頊高陽者，靜深有謀，疏通知事，北至幽陵，南至交趾，西濟流沙，東至蟠木，動靜之物，大小之神，日月所照，莫不砥屬。","sortOrder":92},
  {"id":"s_work_nvlt_11_93","chapterId":"ch_work_nvlt_11","text":"《帝王世紀》曰：帝颛頊，高陽氏，黃帝之孫，昌意之子，姬姓也，母曰景仆，蜀山氏女，為昌意正妃，謂之女枢，金天氏之末，女枢生颛頊於若水，首戴幹戈，有聖德，父昌意雖黃帝之嫡，以德劣，降居若水，為諸侯，及颛頊，生十年而佐少昊，二十而登帝位，平九黎之亂，以水事紀官，南正重司天，以屬神，火［明本作北，正黎司地，以屬民，於是民神不雜，萬物有序，始都窮桑，徙商丘，命飛龍效八風之音，作樂五英，以祭上帝，世有材子八人，號八凯，颛頊在位七十八年，年九十一歲，歲在鶉火而崩，葬東郡頓丘廣陽里。］","sortOrder":93},
  {"id":"s_work_nvlt_11_94","chapterId":"ch_work_nvlt_11","text":"【贊】魏曹植帝颛頊贊曰：昌意之子，祖自軒轅，始誅九黎，水德統天，以國為號，風化神宣，威畅八極，靡不祗虔。","sortOrder":94},
  {"id":"s_work_nvlt_11_95","chapterId":"ch_work_nvlt_11","text":"◇帝喾高辛氏","sortOrder":95},
  {"id":"s_work_nvlt_11_96","chapterId":"ch_work_nvlt_11","text":"《史記》曰：帝喾高辛氏者，黃帝之曾孫也，父曰蟜極，蟜極父曰玄嚣，玄嚣父曰黃帝，自玄嚣與蟜極，不得在位，帝喾生而神靈，自言其名，日月所照，風雨所至，莫不從助。","sortOrder":96},
  {"id":"s_work_nvlt_11_97","chapterId":"ch_work_nvlt_11","text":"《帝王世紀》曰：帝喾高辛氏，姬姓也，有聖德，年十五而佐颛頊，四十登位，都亳，以人事紀官，故以勾芒為木正，祝融為火正，蓐收為金正，玄冥為水正，後土為土正，是五行之官，分職而治諸侯，於是化被天下，遂作樂六茎，以康帝位，世有材子八人，號曰八元，亦納四妃，卜其子，皆有天下，元妃有台氏女，曰薑嫄，生後稷，次有娀氏女，曰簡翟，生，次陳丰氏女，曰慶都，生放勋，次娵訾氏女，曰常儀，生帝挚，喾在位七十年，年百五歲而崩，葬東郡頓丘廣陽里。","sortOrder":97},
  {"id":"s_work_nvlt_11_98","chapterId":"ch_work_nvlt_11","text":"【贊】魏陳王曹植帝喾贊曰：祖自軒轅，玄嚣之裔，生言其名，木德帝世，無寧天地，神聖靈察，教弭四海，明併日月。","sortOrder":98},
  {"id":"s_work_nvlt_11_99","chapterId":"ch_work_nvlt_11","text":"◇帝尧陶唐氏","sortOrder":99},
  {"id":"s_work_nvlt_11_100","chapterId":"ch_work_nvlt_11","text":"尚書尧典曰：若稽古帝尧，曰放勋，钦明文思安安，允恭克讓，光被四表，格於上下，克明俊德，以親九族，九族既睦，平章百姓，百姓昭明，协和萬邦，黎民於变時邕。","sortOrder":100},
  {"id":"s_work_nvlt_11_101","chapterId":"ch_work_nvlt_11","text":"《論語》曰：大哉尧之為君也，巍巍乎，唯天為大，唯尧則之，荡荡乎民無能名焉，巍巍乎其有成功也，煥乎其有文章。","sortOrder":101},
  {"id":"s_work_nvlt_11_102","chapterId":"ch_work_nvlt_11","text":"《春秋元命苞》曰：尧眉八采，是謂通明，歷象日月璇璣玉衡。","sortOrder":102},
  {"id":"s_work_nvlt_11_103","chapterId":"ch_work_nvlt_11","text":"《尚書·中候》曰：帝尧即政，榮光出河，休氣四塞，龍馬衔甲，赤文绿色，［龍形像馬，甲所以藏圖也，其文赤而绿，］甲似龟背，五色，有列星之分，斗政之度，帝王錄紀，興亡之數。","sortOrder":103},
  {"id":"s_work_nvlt_11_104","chapterId":"ch_work_nvlt_11","text":"《大戴禮》曰：宰我曰：請問帝尧，孔子曰：其仁如天，其智如神，就之如日，望之如雲，富而不驕，貴而不豫。","sortOrder":104},
  {"id":"s_work_nvlt_11_105","chapterId":"ch_work_nvlt_11","text":"《淮南子》曰：人之所以樂為天子者，以其窮耳目之欲，而適躬體之便也，今高台曾榭，人之所麗也，而尧采椓不斫，斥題不枅，［言梁柱相斥距，不著枅栌。］珍怪奇味，人之所美也，而尧糲梁之飯，藜藿之羹，文錦狐白，人之所好也，而尧布衣掩形，鹿裘御寒，養生之具厚不加，［《太平御覽》八十作不加厚。］以［御覽作而。］增之以大任，重之［御覽之下有以字。］忧，故舉天下而傳之舜，若釋負然。","sortOrder":105},
  {"id":"s_work_nvlt_11_106","chapterId":"ch_work_nvlt_11","text":"《帝王世紀》曰：帝尧陶唐氏，祁姓也，母慶都，孕十四月而生尧於丹陵，名曰放勋，鳥庭河勝，或從母姓伊氏，年十五而佐帝挚，受封於唐，為諸侯，身長十尺，嘗夢天而上之，故二十而登帝位，都平陽，置敢諫之鼓，命羲和四子，羲仲羲叔和仲和叔，分掌四時方嶽之職，故名曰四嶽也，諸侯有苗氏，處南蠻而不服，尧征而克之於丹水之浦，乃以尹寿許由為師，夔放山川谿穀之音，作樂大章，天下大和，百姓無事，有五十老人，击壤於道，觀者叹曰：大哉，帝之德也，老人曰：吾日出而作，日入而息，凿井而飲，耕田而食，帝何力於我哉，於是景星曜於天，甘露降於地，朱草生於郊，鳳皇止於庭，嘉禾孳於畝，澧泉涌於山，焦僥民來貢没羽，厨中自生肉脯，其薄如翣形，搖鼓自生風，使食物寒而不篯，名曰翣脯。又有草夹階而生，隨月生死，王者以是占日月之數，惟盛德之君，應和而生，故尧有之，名曰蓂荚，始封稷契咎繇，襃進伯禹，納舜於大麓，後年二月。又率群臣，刻璧為書，東沉洛水，言天命當傳舜之意，今中候運衡之篇是也，凡尧即位九十八年，年百一十八歲乃殂，百姓如丧考妣，三載，四海遏密八音，葬於濟陰之成陽西北，是為穀林，尧取富宜氏女，曰女皇，生丹朱。又有庶子九人，皆不肖，故以天下命舜，曰：咨爾舜，天之歷數在爾躬，允執其中，四海困窮，天祿永終，及尧三年丧畢，舜踐天子位。","sortOrder":106},
  {"id":"s_work_nvlt_11_107","chapterId":"ch_work_nvlt_11","text":"《符子》曰：尧曰：餘坐華殿之上，森然而松生於棟，餘立櫺扉之內，霏焉而雲生於牖，雖面双闕，無異乎崔巍之冠蓬萊，雖背墉椁，無異乎回峦之萦崑崙，餘安知其所以安。","sortOrder":107},
  {"id":"s_work_nvlt_11_108","chapterId":"ch_work_nvlt_11","text":"【贊】魏陳王曹植帝尧畫贊曰：火德統位，父則高辛，克平共工，萬國同尘，調適陰陽，其惠如春，巍巍成功，配天則神。","sortOrder":108},
  {"id":"s_work_nvlt_11_109","chapterId":"ch_work_nvlt_11","text":"◇帝舜有虞氏","sortOrder":109},
  {"id":"s_work_nvlt_11_110","chapterId":"ch_work_nvlt_11","text":"尚書舜典曰：慎徽五典，五典克從，納於百揆，百揆時叙，賓於四門，四門穆穆，納於大麓，烈風雷雨弗迷，帝曰：咨爾舜，詢事考言，乃言底可績，三載，汝陟帝位。","sortOrder":110},
  {"id":"s_work_nvlt_11_111","chapterId":"ch_work_nvlt_11","text":"《禮記》曰：子曰：舜其大智也與，好察邇言，隱惡而扬善，執其兩端，用其中於民，其斯以為舜乎。","sortOrder":111},
  {"id":"s_work_nvlt_11_112","chapterId":"ch_work_nvlt_11","text":"又曰：昔舜作五絃之琴，以歌南風，［事具樂部。］","sortOrder":112},
  {"id":"s_work_nvlt_11_113","chapterId":"ch_work_nvlt_11","text":"《論語》曰：無為而治者，其舜也與，夫何為哉，恭己正南面而已矣。","sortOrder":113},
  {"id":"s_work_nvlt_11_114","chapterId":"ch_work_nvlt_11","text":"《孝經援神契》曰：舜龍顏重瞳大口，［手握襃，重童，象電多精光也，大口，象斗星口也，握襃，手中有襃字，喻從勞苦起，受襃飾，致大位也。］","sortOrder":114},
  {"id":"s_work_nvlt_11_115","chapterId":"ch_work_nvlt_11","text":"雒書靈准聽曰：有人方面，日衡重華，［日衡，衡有骨表如日者也。］握石推，懷神珠，［推讀曰錘，錘，平輕重者也，握石錘，謂知璇璣玉衡之道也，懷神珠，喻有聖智也。］舜受終，鳳皇儀，黃龍感，朱草生，蓂荚孳，西王母授益地圖，［西王母得益地之圖來獻。］","sortOrder":115},
  {"id":"s_work_nvlt_11_116","chapterId":"ch_work_nvlt_11","text":"《孟子》曰：雞初鳴而起，孳孳為善者，舜之徒也，雞初鳴而起，孳孳為利者，蹠之徒也，［蹠，盜蹠。］","sortOrder":116},
  {"id":"s_work_nvlt_11_117","chapterId":"ch_work_nvlt_11","text":"又曰：尧之於舜，使其子九男事之，妻以二女焉，百年［孟子萬章作官。］牛羊仓廪備，以養舜於畎畝之中，而後舉加諸上位。","sortOrder":117},
  {"id":"s_work_nvlt_11_118","chapterId":"ch_work_nvlt_11","text":"又曰：舜聞一善言，見一善行，若决江河，霈然莫之能御也。","sortOrder":118},
  {"id":"s_work_nvlt_11_119","chapterId":"ch_work_nvlt_11","text":"《尸子》曰：舜一徙成邑，再徙成都，三徙成國，尧聞其賢，徵之草茅之中，與之語禮樂而不逆，與之語政至簡而行，與之語道廣大而不窮，於是妻之以媓，媵之以娥，九子事之，而讬天下焉。","sortOrder":119},
  {"id":"s_work_nvlt_11_120","chapterId":"ch_work_nvlt_11","text":"《韓子》曰：歷山農者侵畔，舜往耕，期年而耕者讓畔，河濱漁者爭坘，舜往漁，期年而漁者讓長，東夷之陶者苦窳，舜往陶，期年而器以牢。","sortOrder":120},
  {"id":"s_work_nvlt_11_121","chapterId":"ch_work_nvlt_11","text":"《呂氏春秋》曰：舜有子九人，不予其子而授禹，至公也。","sortOrder":121},
  {"id":"s_work_nvlt_11_122","chapterId":"ch_work_nvlt_11","text":"《帝王世紀》曰：帝有虞氏，姚姓也，目重瞳，故名重華，字都君，有聖德，始遷於負夏，販於頓丘，债於傳虛，家本冀州，每徙則百姓歸之，尧於是見舜於貳宮，設饗禮，迭為賓主，南面而問政，尧乃试以五典，遂舉八凯，使佐後土，以揆百事，舉八元，使布五教於四方，舜於是有大功二十，故夢眉長與發等，尧乃賜舜以昭華之玉，老而命舜代己攝政，舜東巡狩，登南山，觀河渚，受圖書，襃賜群臣，尊任伯禹稷契皋繇，皆益地，有苗氏負固不服，禹請征之，舜曰：我德不厚而行武，非道也，吾前教由未也，乃脩教三年，執幹戚而舞之，有苗請服，立誹謗之木，申命九官十二牧，三載一考績，三載黜陟幽明，禹為司空，功被天下，弃為後稷，播時百穀，契為司徒，敬敷五教，皋繇為士，典刑惟明，倕為共工，莫不致力，益為朕虞，庶物繁植，伯夷為祑宗，三禮不闕，夔為樂正，神人以和，龍為納言，出內惟允，於是俊乂在官，群後德讓，百僚師師，以五采章施於五色為服，以六律五聲八音协治，治用之和，蒸民乃粒，萬邦作乂，庶績鹹熙，乃作大韶之樂，箫韶九成，鳳皇來儀，击石拊石，百獸率舞，故孔子稱韶盡美矣。又盡善也，景星曜於房，群瑞畢致，地出乘黃，舜於是德被天下，荐於天，使禹攝政，有苗氏叛，南征，崩於鳴條，殯以瓦棺，葬於蒼梧九疑山之陽，是為零陵，謂之紀市，在今營道，下有群象為之耕。","sortOrder":122},
  {"id":"s_work_nvlt_11_123","chapterId":"ch_work_nvlt_11","text":"【贊】魏陳王曹植帝舜贊曰：颛頊氏族，重瞳神聖，克协顽瞽，應唐涖政，除凶舉俊，以齊七政，應歷受禪，顯天之命。","sortOrder":123},
  {"id":"s_work_nvlt_11_124","chapterId":"ch_work_nvlt_11","text":"晉夏侯湛虞舜贊曰：有虞愔愔，揖讓鼓琴，垂拱臨民，詠彼南音，世澄道玄，天下混心，思我王度，如玉如金。","sortOrder":124},
  {"id":"s_work_nvlt_11_125","chapterId":"ch_work_nvlt_11","text":"晉庾闡虞舜像贊併序曰：夫至道玄妙，非器象所載，靈化潛融，非軌跡所傳，故道資冲朴，則謂之三皇，德被群生，則號稱舜禹，是以先王因其會通，製為准極，功格於天，則配於上帝，法施於民，則載在祀典，然後名教彰於至治，王道煥乎無窮，故茲堂之構也，有自來矣，然树寢所以栖神，而寢非神之所期，立像所以表德，而像非德之所存，若乃废其軌景，洞其玄真，雖冥照之鑒獨朗，天下惡乎註其耳目哉，遂乃顯圖靈像，廓其廟壇，俾天光焜於宇宙，南風散乎五絃，豈謂神道之妙，可寄之於有涯哉，蓋亦畅悠悠者之心也，其辭曰：玄像焜燿，萬物含靈，飛龍在天，陽德文明，神道雖寂，務由機生，擁琴高詠，寄和五聲，玄風既畅，妙盡無名，民鑒其朗，孰测窈冥。","sortOrder":125},
  {"id":"s_work_nvlt_11_126","chapterId":"ch_work_nvlt_11","text":"周庾信舜幹戚畫贊曰：平風变律，击石來儀，先齊七政，更服三危，朱幹獨舞，玉戚空麾，南風一曲，恭己無為。","sortOrder":126},
  {"id":"s_work_nvlt_11_127","chapterId":"ch_work_nvlt_11","text":"【碑】後魏溫子昇舜廟碑曰：懷山不已，龍門未辟，大道御世，天下為公，感夢長人，明易攵仄陋，釐降二女，結友九男，執耜歷山，耕夫所以謝畔，施罟雷泽，漁父於是讓川，亦既登庸，以之納錄，九官鹹事，百揆時叙，有大功於當世，集歷數而在躬，受文祖之命，致昭華之玉，班五瑞於群後，禋六宗於上玄，舞幹戚而遠夷賓，弃金璧而幽靈應，青雲浮洛，榮光塞河，符瑞必臻，休祥鹹萃，以君人之大德，為帝王之稱首，陟方之駕遂往，蒼梧之窆不歸，爰自先民，實存舊廟，既緝藥房，遂镇瑤席，龍駕帝服，蓋依俙於慕舜，交鼓亘瑟，實仿佛於聞韶，其辭曰：虹氣降靈，姚墟誕聖，树陰未徙，帝圖已定，乃賓四門，以齊七政，天眷功高，民歸德盛，治既荡荡，化亦巍巍，南風在詠，西環有歸，疑山永逝，湘水長违，靈宮肅肅，神馆微微。","sortOrder":127},
  {"id":"s_work_nvlt_11_128","chapterId":"ch_work_nvlt_11","text":"【文】宋顏延之為張湘州祭虞帝文曰：惟哲化神，繼天作聖，藏器漁陶，致身愛敬，是以二妃嫔德，九子觀命，在麓不迷，御衡以正，唐歷既終，虞道乃光，咨尧授禹，素俎采堂，百齡厭世，萬里陟方，敬詢故老，钦咨聖君，職奉西湘，虔屬南雲，神之聽之，匪酒伊葷。","sortOrder":128},
  {"id":"s_work_nvlt_11_129","chapterId":"ch_work_nvlt_11","text":"《尚書·大禹謨》曰：受命於神宗，率百官，若帝之初，［從舜初授帝政事奉行之。］","sortOrder":129},
  {"id":"s_work_nvlt_11_130","chapterId":"ch_work_nvlt_11","text":"《論語》曰：子曰：禹吾無間然矣，［孔子推禹功德之大，言不能复間廁其間。］菲飲食而致孝乎鬼神，惡衣服而致美乎黻冕。","sortOrder":130},
  {"id":"s_work_nvlt_11_131","chapterId":"ch_work_nvlt_11","text":"《禮含文嘉》曰：禹卑宮室，垂意於溝洫，百穀用成，神龍至，靈龟服，玉女敬養天賜。","sortOrder":131},
  {"id":"s_work_nvlt_11_132","chapterId":"ch_work_nvlt_11","text":"《春秋元命苞》曰：禹之時，民大樂，其骈三聖相繼，故夏者大也。","sortOrder":132},
  {"id":"s_work_nvlt_11_133","chapterId":"ch_work_nvlt_11","text":"《左傳》曰：禹會諸侯於涂山，執玉帛者萬國。","sortOrder":133},
  {"id":"s_work_nvlt_11_134","chapterId":"ch_work_nvlt_11","text":"《尚書·中候》曰：伯禹曰：臣觀河伯，面長人首魚身，出水曰：吾河精也，授臣河圖。","sortOrder":134},
  {"id":"s_work_nvlt_11_135","chapterId":"ch_work_nvlt_11","text":"《尚書璇璣鈐》曰：禹开龍門，导積石，玄圭出，刻曰延喜玉，受德天賜佩，［禹功既成，天出玄圭以賜之，古者以德佩，禹有治水功，故天佩以玄圭。］","sortOrder":135},
  {"id":"s_work_nvlt_11_136","chapterId":"ch_work_nvlt_11","text":"呂氏春秋曰：禹南濟乎江，黃龍負舟，［事具祥瑞部。］","sortOrder":136},
  {"id":"s_work_nvlt_11_137","chapterId":"ch_work_nvlt_11","text":"《淮南子》曰：禹沐淫雨，櫛疾風，决江疏河，凿龍門，辟伊闕，乘四載，隨山刊木，平治水土，定七百國。","sortOrder":137},
  {"id":"s_work_nvlt_11_138","chapterId":"ch_work_nvlt_11","text":"又曰：禹為水，以身解於陽旰［淮南脩務篇作盱，註同。］之河，［解，祷也，陽旰河在秦。］","sortOrder":138},
  {"id":"s_work_nvlt_11_139","chapterId":"ch_work_nvlt_11","text":"《吳越春秋》曰：禹案黃帝中經，見聖人所記曰：在九疑山東南天柱，號曰宛委，承以文玉，覆以盤石，其書金簡，青玉為字，編以白銀，皆瑑其文，禹乃東巡，登衡山求之，赤繡文衣男子，自稱玄夷仓水使者，來候禹，令斋三月，更求之，禹乃三日斋，登宛委山，取得書，得通水之理，遂周行天下，使益疏記之，名山海經也。","sortOrder":139},
  {"id":"s_work_nvlt_11_140","chapterId":"ch_work_nvlt_11","text":"鬻子曰：禹投［《太平御覽》八十二作據。］一饋而七起，曰：吾不恐四海之士留於道路也，恐其留吾門也，是以四海之士皆至，禹當朝廷，門可以羅雀。","sortOrder":140},
  {"id":"s_work_nvlt_11_141","chapterId":"ch_work_nvlt_11","text":"《帝王世紀》曰：伯禹夏後氏，姒姓也，生於石坳，虎鼻大口，兩耳參漏，首戴鉤鈐，胸有玉斗，足文履巳，故名文命，字高密，身長九尺二寸，長於西羌，西羌夷人也，其父既放，降在疋庶，有聖德，夢目［《太平御覽》八十二作自。］洗於河西，四嶽師舉之，舜進之尧，尧命以為司空，繼篰治水，乃勞身涉勤，不重径尺之璧，而愛日之寸陰，手足胼胝，故世傳禹病偏枯，足不相過，至今巫稱禹步是也。又納禮賢人，一沐三握發，一食三起，尧美其績，乃賜姓姒氏，封為夏伯，故謂之伯禹，天下宗之，謂之大禹，年百歲，崩於會稽，因葬會稽山陰縣之南，今山上有禹冢併祠，下有群鳥芸田。","sortOrder":141},
  {"id":"s_work_nvlt_11_142","chapterId":"ch_work_nvlt_11","text":"又曰：禹葬，衣衾三領，桐棺三寸，葛以繃之，下不及泉，上不通篯，既葬，收餘壤為垅，若參耕之畝。","sortOrder":142},
  {"id":"s_work_nvlt_11_143","chapterId":"ch_work_nvlt_11","text":"《符子》曰：禹讓天下於奇子，奇子曰：君言佐舜勞矣，凿山川，通河漢，首無發，股無毛，故舜也以勞報子，我生而逸，不能為君之勞矣。","sortOrder":143},
  {"id":"s_work_nvlt_11_144","chapterId":"ch_work_nvlt_11","text":"【贊】魏陳王曹植夏禹贊曰：於嗟夫子，拯世濟民，克卑宮室，致孝鬼神，蔬食薄服，紼冕乃新，厥德不回，其誠可親，亹亹其德，溫溫其仁，尼稱無間，何德之純。","sortOrder":144},
  {"id":"s_work_nvlt_11_145","chapterId":"ch_work_nvlt_11","text":"又曰：禹治水贊曰：嗟夫夏禹，寔勞水功，西凿龍門，疏河道江，梁歧既辟，九州以同，天賜玄圭，奄有萬邦。","sortOrder":145},
  {"id":"s_work_nvlt_11_146","chapterId":"ch_work_nvlt_11","text":"又禹渡河贊曰：禹濟於河，黃龍負船，舟人併懼，禹叹仰天，予受大運，勤功恤民，死亡命也，龍乃弭身。","sortOrder":146},
  {"id":"s_work_nvlt_11_147","chapterId":"ch_work_nvlt_11","text":"周庾信渡江贊曰：三江初凿，九穀新成，風飛鹢涌，水起龍驚，樂天知命，無待忧生，危舟遂靜，亂楫還平。","sortOrder":147},
  {"id":"s_work_nvlt_11_148","chapterId":"ch_work_nvlt_11","text":"《藝文類聚》　唐·欧陽詢","sortOrder":148},
  {"id":"s_work_nvlt_12_1","chapterId":"ch_work_nvlt_12","text":"卷十二帝王部二","sortOrder":1},
  {"id":"s_work_nvlt_12_2","chapterId":"ch_work_nvlt_12","text":"○殷成湯周文王周武王周成王漢高帝漢文帝漢景帝漢武帝漢昭帝漢宣帝漢光武帝漢明帝漢和帝","sortOrder":2},
  {"id":"s_work_nvlt_12_3","chapterId":"ch_work_nvlt_12","text":"◇殷成湯","sortOrder":3},
  {"id":"s_work_nvlt_12_4","chapterId":"ch_work_nvlt_12","text":"《春秋元命苞》曰：湯臂四肘，是謂神肘。","sortOrder":4},
  {"id":"s_work_nvlt_12_5","chapterId":"ch_work_nvlt_12","text":"《尚書璇璣鈐》曰：湯受金符帝箓，白狼衔鉤入殷朝。","sortOrder":5},
  {"id":"s_work_nvlt_12_6","chapterId":"ch_work_nvlt_12","text":"《尚書·中候》曰：天乙在亳，諸鄰國襁負歸德，東觀乎雒，降三分璧，黃魚双躍，出濟於壇，化為黑玉，赤勒曰：玄精天乙，受神福，伐桀克。","sortOrder":6},
  {"id":"s_work_nvlt_12_7","chapterId":"ch_work_nvlt_12","text":"尚書湯誓曰：伊尹相湯伐桀，升自陑，遂與桀戰於鳴條之野。","sortOrder":7},
  {"id":"s_work_nvlt_12_8","chapterId":"ch_work_nvlt_12","text":"《春秋元命苞》曰：湯之時，其民大樂，其救之於患害，故樂名大護，護者救也，一雲，扶都感白氣而生湯。","sortOrder":8},
  {"id":"s_work_nvlt_12_9","chapterId":"ch_work_nvlt_12","text":"《周書》曰：湯放桀而歸於亳，三千諸侯大會，湯取天子之玺，置之於天子之座左，复而再拜，從諸侯之位，湯曰：此天子之位，有道者可以處之矣，夫天下非一家之有也，有道者之有也，故天下者，唯有道者理之，唯有道者宜處之，湯以此三讓，三千諸侯，莫敢即位，然後湯即天子之位。","sortOrder":9},
  {"id":"s_work_nvlt_12_10","chapterId":"ch_work_nvlt_12","text":"《孟子》曰：湯居亳，與葛伯為鄰，葛伯不祀，湯使人問，何為不祀，曰：無以供犧牲，湯遺之牛羊，葛伯得而食之。又不祀，湯又問之，曰：無以供粢盛，湯使亳民為之耕，老弱饋食，葛伯率眾要其酒肉黍稷者，遮而奪之，不以饔授者則殺之，有一童子，以黍肉餉，殺而奪焉，湯乃興師伐葛伯，天下聞之，皆曰：非富天下也，為疋夫疋婦報讎也。","sortOrder":10},
  {"id":"s_work_nvlt_12_11","chapterId":"ch_work_nvlt_12","text":"《呂氏春秋》曰：成湯之時，有穀生於庭，昏生，至旦而大合拱，史請卜其故，湯退卜者曰：吾聞祥者福之先也，見祥而為不善，則福不至，妖者禍之先也，見妖而為善，則禍不至，於是早朝晏退，問疾弔丧，務镇撫百姓，三日而穀亡，尚書大傳曰：夏人飲酒，醉者持不醉者，不醉者持醉者，相和而歌曰：盍歸於亳，盍歸於亳上，亳亦大矣，故伊尹退而閒居，深聽樂聲，［思其故也，是時伊尹仕桀。］更曰：覺兮较兮，吾大命格兮，［覺兮謂先知者，较兮謂直道者也，格，至也，吾，語桀也。］去不善而就善，何樂兮，伊尹入告於桀曰：大命之亡有日矣，桀哑笑曰：天之有日，猶吾之有民也，日亡，吾亦亡矣，是以伊尹遂去夏適湯。","sortOrder":11},
  {"id":"s_work_nvlt_12_12","chapterId":"ch_work_nvlt_12","text":"《說苑》曰：湯欲伐桀，伊尹請且乏貢職，以觀夏動，桀怒，起九夷之師，伊尹曰：未可，彼尚能起九夷之師，是罪在我也，湯乃謝請服，入貢職，明年。又乏貢職，桀起九夷之師，九夷之師不起，伊尹曰：可矣，湯乃興師伐桀，殘之，遷於南巢。","sortOrder":12},
  {"id":"s_work_nvlt_12_13","chapterId":"ch_work_nvlt_12","text":"《帝王世紀》曰：成湯一名帝乙，丰下銳上，倨身而扬聲，長九尺，有聖德，諸侯有不義者，湯從而征之，誅其君，弔其民，天下鹹悅，故東征則西夷怨，南征則北狄怨，曰：奚為而後我，凡二十七征而德施於諸侯，出見羅者，方祝曰：從天下者，從地出者，四方來者，皆入吾羅，湯曰：嘻，盡之矣，非桀其孰能為此哉，乃命解其三面，而置其一面，更教之祝曰：欲左者左，欲右者右，欲高者高，欲下者下，吾取其犯命者，漢南諸侯聞之，鹹曰：湯之德至矣，泽及禽獸，况於人乎，一時歸者三十六國，及夏桀無道，罪諫者，湯使人哭之，桀囚湯使於夏台，而後釋之，諸侯由是鹹叛桀附湯，同日貢職者五百國，三年而天下鹹服，湯自伐桀後，大旱七年，殷史卜曰：當以人祷，湯曰：吾所為請雨者民也，若必以人祷，吾請自當，遂斋戒，剪發斷爪，以己為牲，祷於桑林之社，言未已而大雨，方數千里，湯踐天子位十三年，年百歲而崩。","sortOrder":13},
  {"id":"s_work_nvlt_12_14","chapterId":"ch_work_nvlt_12","text":"【贊】魏陳王曹植殷湯贊曰：殷湯伐夏，諸侯振仰，放桀鳴條，南面以王，桑林之祷，炎灾克偿，伊尹佐治，可謂賢相。","sortOrder":14},
  {"id":"s_work_nvlt_12_15","chapterId":"ch_work_nvlt_12","text":"又湯祷桑林贊曰：惟殷之世，炎旱七年，湯祷桑林，祈福於天，剪發離爪，自以為牲，皇靈感應，時雨以零。","sortOrder":15},
  {"id":"s_work_nvlt_12_16","chapterId":"ch_work_nvlt_12","text":"周庾信湯解網贊曰：連珠兩起，合玉双沉，穀為祥树，桑成樂林，三方落網，一面驅禽，德以行政，仁乎用心。","sortOrder":16},
  {"id":"s_work_nvlt_12_17","chapterId":"ch_work_nvlt_12","text":"◇周文王","sortOrder":17},
  {"id":"s_work_nvlt_12_18","chapterId":"ch_work_nvlt_12","text":"《春秋元命苞》曰：文王四乳，是謂含良，蓋法酒旗，布恩舒明，［酒者乳也，能乳天下，布恩之謂也。］","sortOrder":18},
  {"id":"s_work_nvlt_12_19","chapterId":"ch_work_nvlt_12","text":"《周書》曰：文王在鎬，召太子發曰：我身老矣，吾語汝，我所保與我所守，傳之子孫，吾厚德而廣惠，不為驕侈，不為泰靡，童牛不服，童馬不馳，土不失其宜，萬物不失其性，天下不失時，以成萬材，萬材已成，牧以為人，天下利之而勿德，是謂大仁。","sortOrder":19},
  {"id":"s_work_nvlt_12_20","chapterId":"ch_work_nvlt_12","text":"《墨子》曰：赤鳥衔珪，降周之歧社，曰：命周文王伐殷。","sortOrder":20},
  {"id":"s_work_nvlt_12_21","chapterId":"ch_work_nvlt_12","text":"《韓子》曰：昔文王請入雒西地赤壤之國方千里，以解炮烙之刑，天下皆說，仲尼曰：大哉文王，輕千乘之國，而請解炮烙之刑。","sortOrder":21},
  {"id":"s_work_nvlt_12_22","chapterId":"ch_work_nvlt_12","text":"《韓詩外傳》曰：昔周文王寢疾五日而地動，東西南北，不出四郊，有司請曰：臣聞地之動為人主也，今者君王寢疾五日而地動，四面不出國郊，群臣皆恐，曰：請移之，文王曰：奈何其移之也，對曰：興事動眾，以增國城，其可移之，文王曰：夫天之見妖，以伐有罪，我必有罪，故天以罰我也，今又专興事動眾，以增國城，是重吾罪也，不可，請改行重善移之，其可以免乎，於是遂謹其禮祑皮革，以交諸侯，飾其辭令幣帛，以出禮俊士，頒其爵列等級田畴，以賞群臣，行無幾何而疾止。","sortOrder":22},
  {"id":"s_work_nvlt_12_23","chapterId":"ch_work_nvlt_12","text":"《琴操》曰：受命者，謂文王受天命而王，文王以紂時為歧侯，躬脩道德，執行仁義，百姓附親，是時，紂為無道，刳胎斮涉，废坏仁人，天統易運，諸侯瓦解，皆歸文王，其後有鳳皇衔書於文王之郊，文王曰：殷帝無道，虐亂天下，皇命已移，不得复久，乃作鳳皇之歌，其章曰：翼翼翔翔，彼鸞皇兮，衔書來遊，以命昌兮，瞻天案圖，殷將亡兮，蒼蒼昊天，始有萌兮，神連精合，謀於房兮。","sortOrder":23},
  {"id":"s_work_nvlt_12_24","chapterId":"ch_work_nvlt_12","text":"又曰：文王備修道德，百姓親附，文王有二子，周公武王，皆聖，是時，崇侯虎與文王列為諸侯，德不及文王，常嫉妒之，乃谮文王於紂曰：西伯昌聖人也，長子發中子旦皆聖人也，三聖合謀，君其慮之，乃囚文王於羑里，將欲殺之，於是文王四臣散宜生等，周流海內，經歷丰土，得美女二人，水中大貝，白馬朱鬛，以獻於紂，陳於中庭，紂立出西伯，文王在羑里時，演易八卦以六十四，作鬱厄之辭，困於石，據於蒺藜，乃申憤以作歌曰：殷道溷溷，浸濁煩兮，朱紫相合，不別分兮，迷亂聲色，信讒言兮，炎炎之虐，使我愆兮，幽閉牢阱，由其言兮，遘我四人，忧勤勤兮。","sortOrder":24},
  {"id":"s_work_nvlt_12_25","chapterId":"ch_work_nvlt_12","text":"《論衡》曰：文王飲酒千鍾，孔子百觚，言聖人能以德持酒也，如一坐千鍾百觚，此酒徒，非聖人也。","sortOrder":25},
  {"id":"s_work_nvlt_12_26","chapterId":"ch_work_nvlt_12","text":"《帝王世紀》曰：文王昌，龍顏虎肩，身長十尺，焜有四乳，敬老慈幼，晏朝不食，以延四方之士，是以大〈真真〉閎夭散宜生南宮適之屬鹹至，是為四臣，文王雖在諸侯之位，袭父為西伯，紂既囚文王，文王之長子曰伯邑考，质於殷，為紂御，紂烹以為羹，賜文王，曰：聖人當不食其子羹，文王得而食之，紂曰：誰謂西伯聖者，食其子羹，尚不知也。","sortOrder":26},
  {"id":"s_work_nvlt_12_27","chapterId":"ch_work_nvlt_12","text":"【贊】魏陳王曹植文王贊曰：於赫聖德，寔惟文王，三分有二，猶复事商，化加虞芮，傍暨四方，王業克昭，武嗣遂光。","sortOrder":27},
  {"id":"s_work_nvlt_12_28","chapterId":"ch_work_nvlt_12","text":"又文王赤雀贊曰：西伯積德，天命攸顧，赤雀衔書，爰集昌戶，瑞為天使，和氣所致，嗟爾後王，昌期而至，周庾信文王見呂尚贊曰：言歸養老，垂釣西川，岸止盤石，溪唯小船，風雨未感，意氣怡然，有此相望，於今幾年。","sortOrder":28},
  {"id":"s_work_nvlt_12_29","chapterId":"ch_work_nvlt_12","text":"◇周武王","sortOrder":29},
  {"id":"s_work_nvlt_12_30","chapterId":"ch_work_nvlt_12","text":"《尚書·中候》曰：太子發，以紂存三仁，雖即位，不稱王，［三仁，箕子比幹微子。］","sortOrder":30},
  {"id":"s_work_nvlt_12_31","chapterId":"ch_work_nvlt_12","text":"樂稽耀嘉曰：武王承命興師，誅於商，萬國鹹喜，軍渡孟津，前歌後舞，克殷之後，民乃大安，家給人足，酌酒鬱搖，［鬱搖，喜濬。］","sortOrder":31},
  {"id":"s_work_nvlt_12_32","chapterId":"ch_work_nvlt_12","text":"《史記》曰：武王脩文王業，東觀兵孟津，為文王木主，載以居中軍，自稱太子發，言奉文王以伐，不敢自专，遂興師，渡於河，時諸侯不期而會孟津者八百，諸侯皆曰：紂可伐，武王曰：未可也，乃還師，居二年，聞紂昏亂滋甚，殺比幹，囚箕子，太師疵少師彊微子，抱其祭器而饹周，於是武王乃渡孟津，伐紂，紂師皆倒幹戈以戰，紂軍潰畔，紂死。","sortOrder":32},
  {"id":"s_work_nvlt_12_33","chapterId":"ch_work_nvlt_12","text":"《帝王世紀》曰：武王見暍人，王自左擁而右扇之，紂政弥亂，殷太史向挚，載其圖書而歸周，王以告於諸侯，四年，起師而東，至商郊牧野，乃作木簷，［○帝王世紀作牧誓。］王襪系解，五人御於前，莫肯為王系襪，皆曰：臣所以事君王，非為系襪也，王乃釋旄鉞而系之，與紂戰，紂師败績，禽費仲惡來，紂赴於京，自燔於宣室而死，二嬖妾與妲己亦自殺，乃以大白髦麾諸侯入殷商都，百姓鹹待於郊，王使告曰：上天降休，商人皆拜，王亦答拜，以兵入，造紂及妲己尸，王親射之，三發，然後下車，以劍击之，周公為司徒，使以黃鉞斬紂頭，懸於大白之旗，召公為司空。又使以玄鉞斬妲己頸，縣之小白旗，置旌於商容之庐，命召公釋箕子之囚，賜貝千朋，命原公釋百姓之囚，歸璇台之珠玉，命南宮括散鹿台之财，發巨桥之粟，以赈貧民，命南宮伯達史逸，遷九鼎於洛邑，命閎夭封比幹之墓，命宗祝饗祀於軍，微子膠鬲，皆委质為臣，殷人鹹喜曰：王之於人也，死猶封其墓，况其生者乎，王之於賢仁也，亡者猶表其庐，况其存者乎，王之於财也，聚者猶散之，况其复藉者乎，王之於色也，在者猶歸其父母，况复徵之乎。","sortOrder":33},
  {"id":"s_work_nvlt_12_34","chapterId":"ch_work_nvlt_12","text":"【贊】魏陳王曹植周武王贊曰：桓桓武王，繼世滅殷，鹹任尚父，且作商臣，功加四海，救世濟民，天下宗周，萬國是賓。","sortOrder":34},
  {"id":"s_work_nvlt_12_35","chapterId":"ch_work_nvlt_12","text":"◇周成王","sortOrder":35},
  {"id":"s_work_nvlt_12_36","chapterId":"ch_work_nvlt_12","text":"《春秋元命苞》曰：文王造之而未遂，武王遂之而未成，周公旦抱少主而成之，故曰成王。","sortOrder":36},
  {"id":"s_work_nvlt_12_37","chapterId":"ch_work_nvlt_12","text":"《贾誼書》曰：周成王問鬻子曰：寡人聞聖人在上位，使民富且寿，若夫富則可為也，若夫寿則在天乎，鬻子對曰：夫聖王在上位，天下無軍兵之事，故諸侯不私相攻，而民不私相斗也，則民得盡一生矣，聖王在上，則君積於德化，而積於用力，故婦人為其所衣，丈夫為其所食，則民無冻饿，已得二生矣，聖人在上，則君積於仁，吏積於愛，民積於順，則刑罰废而無夭遏之誅，民則得三生矣，聖王在上，則使人有時，而用之有節，則民無厲疾，民得四生矣。","sortOrder":37},
  {"id":"s_work_nvlt_12_38","chapterId":"ch_work_nvlt_12","text":"《史記》曰：成王少，周公攝行政，管叔蔡叔群弟疑周公，與武庚作亂，周公奉成王命，誅武庚，殺管叔，放蔡叔，以微子啟代殷後，國於宋，周公行政七年，成王長，周公反政成王，北面就群臣之位，成王在丰，使召公复營洛邑，如武王之意，卒營筑，居九鼎焉，曰：此天下之中，四方入貢，道理均。","sortOrder":38},
  {"id":"s_work_nvlt_12_39","chapterId":"ch_work_nvlt_12","text":"《帝王世紀》曰：成王元年，周公為冢宰，攝政，王年少，未能治事，故號曰孺子，八年，春正月朔，王始躬政事，以周公為太師，封伯禽於魯，父子併命，周公拜於前，魯公拜於後，王以周公有勋勞於天下，故加魯以四等之上，兼二十四附庸，地方七百里，既營都洛邑，复居酆鎬，淮夷徐戎及奄阝叛，王乃大搜於岐陽，東伐淮夷。","sortOrder":39},
  {"id":"s_work_nvlt_12_40","chapterId":"ch_work_nvlt_12","text":"【贊】魏陳王曹植周成王贊曰：成王繼武，賢聖保傅，年雖幼稚，岐嶷有素，初疑周公，終焉克寤，旦奭佐治，遂至刑错。","sortOrder":40},
  {"id":"s_work_nvlt_12_41","chapterId":"ch_work_nvlt_12","text":"又周公贊曰：成王即位，年尚幼稚，周公居攝，四海慕利，罰叛柔服，祥應仍至，誦長反政，達天忠義。","sortOrder":41},
  {"id":"s_work_nvlt_12_42","chapterId":"ch_work_nvlt_12","text":"周庾信成王刻桐葉封虞叔贊曰：虞叔百里，居河之汾，帝刻桐葉，天書掌文，禮以成德，樂以歌勋，天子無戲，唐其有君。","sortOrder":42},
  {"id":"s_work_nvlt_12_43","chapterId":"ch_work_nvlt_12","text":"◇漢高帝","sortOrder":43},
  {"id":"s_work_nvlt_12_44","chapterId":"ch_work_nvlt_12","text":"河圖提劉曰：帝季，日角戴勝，斗焜龟背龍股，長七尺八寸，明聖宽仁，好任主軫。","sortOrder":44},
  {"id":"s_work_nvlt_12_45","chapterId":"ch_work_nvlt_12","text":"《春秋孔演圖》曰：其人日角龍顏，姓卯金，含仁義。","sortOrder":45},
  {"id":"s_work_nvlt_12_46","chapterId":"ch_work_nvlt_12","text":"《史記》曰：高祖讳邦，字季，沛丰邑中陽里人，為人隆准而龍顏，美須髯，左股有七十二黑子，宽仁愛人，意豁如也，為泗上亭長，常從王媪武負贳酒飲，醉臥，武負王媪見其上常有龍，怪之，高祖每留飲，酒讎數倍，呂公者，好相人，見高祖状貌，因敬重之，呂公曰：臣少好相人，相人多矣，無如季相，原季自愛，臣有息女，原為箕帚妾，女即呂後也，生孝惠帝魯元公主，有一老父過，請飲，老父相呂後曰：夫人天下貴人也，令相兩子，見孝惠帝，曰：夫人所以貴者，乃此男，魯元公主亦皆貴，老父已去，高祖從旁舍來，呂後具言，高祖乃追及老父，老父曰：向見者夫人兒子，皆似君相，君相貴不可言，及高祖貴，遂不知老父去處，高祖以亭長為縣送徒於驪山，到丰西泽中亭，止飲，夜皆解縱所送徒，高祖夜經泽中，前有大白蛇當径，高祖拔劍斬之，［事具符命部。］秦始皇帝常曰：東南有天子氣，於是東遊，高祖隱於芒碭山泽間，呂後與人俱求，常得之，高祖怪問呂後，呂後曰：季所在山居，上常有雲氣，故往常得季，高祖興諸侯兵，共击項羽，項羽败而走，使騎將灌婴追殺羽東城，正月，諸侯尊漢王為皇帝。","sortOrder":46},
  {"id":"s_work_nvlt_12_47","chapterId":"ch_work_nvlt_12","text":"又曰：范增說項羽曰：沛公居東，貪於财货，好美姬，今入關，财物無所取，婦女無所幸，此其志不在小，吾令人望氣，皆為龍虎，成五采，此天子氣也。","sortOrder":47},
  {"id":"s_work_nvlt_12_48","chapterId":"ch_work_nvlt_12","text":"《漢書》曰：漢承尧運，德祚已盛，斷蛇著符，旗幟尚赤，协於火德，自然之應，得天統矣。","sortOrder":48},
  {"id":"s_work_nvlt_12_49","chapterId":"ch_work_nvlt_12","text":"《論衡》曰：項羽與高祖俱起，威力輕重，未有所定，高祖誅羽，難於斬鐵也，武王伐紂，易於摧木也，然則漢力勝周多矣，湯武伐桀紂，一敵也，高祖誅秦殺項羽，兼勝二家，力倍湯武，五代之起，皆有因緣，力易為也，高祖從亭長，提三尺劍，取天下，光武由白水，奋威武，帝海內，無尺土所因，一位所乘，直奉天命，推勋自然，此則起高於川汙，為深於丘山也。","sortOrder":49},
  {"id":"s_work_nvlt_12_50","chapterId":"ch_work_nvlt_12","text":"荀悅漢紀論曰：高祖开建大業，統畢元功，度量規矩，不可尚矣，天下初定，庶事草創，故韶夏之音，天下未聞焉。","sortOrder":50},
  {"id":"s_work_nvlt_12_51","chapterId":"ch_work_nvlt_12","text":"《帝王世紀》曰：禮稱至道以王，義道以霸，觀高祖之取天下也，遭秦暴亂，不階尺土之資，不摧將相之柄，發跡泗亭，奋其智謀，衔勒英雄，鞭驅天下，或以德致，或以義成，事以權斷，順逆不常，霸王之道雜焉，是以居帝王之位，而無一定之製，三代之美，固難及矣。","sortOrder":51},
  {"id":"s_work_nvlt_12_52","chapterId":"ch_work_nvlt_12","text":"【述】後漢班固高祖紀述曰：皇矣漢祖，纂尧之緒，實天生德，聰明神武，秦人不綱，網漏於楚，爰茲發跡，斷蛇奋旅，神母告符，朱旗乃舉，粵蹈秦郊，婴來稽首，革命創製，三章是紀，應天順民，五星同晷，項氏叛換，黜我巴漢，西土宅心，戰士憤怨，乘衅而運，席卷三秦，割據河山，保此懷民，股肱萧曹，社稷是經，爪牙信布，腹心良平，恭行天罰，赫赫明明。","sortOrder":52},
  {"id":"s_work_nvlt_12_53","chapterId":"ch_work_nvlt_12","text":"【贊】魏陳王曹植漢高皇帝贊曰：屯雲斬蛇，靈母告祥，朱旗既抗，九野披攘，禽婴克羽，扫滅英雄，承機帝世，功著武湯。","sortOrder":53},
  {"id":"s_work_nvlt_12_54","chapterId":"ch_work_nvlt_12","text":"晉傅玄漢高祖畫贊曰：赫赫漢祖，受命龍興，五星协象，神母告徵，讨秦滅項，如日之升，超從侧陋，光據萬乘。","sortOrder":54},
  {"id":"s_work_nvlt_12_55","chapterId":"ch_work_nvlt_12","text":"周庾信漢高祖置酒沛宮畫贊曰：遊子思舊，來歸沛宮，還迎故老，更召歌童，雖欣入沛，方念移丰，酒酣自舞，先歌大風。","sortOrder":55},
  {"id":"s_work_nvlt_12_56","chapterId":"ch_work_nvlt_12","text":"【碑】後漢班固高祖泗水亭碑曰：皇皇炎漢，兆自沛丰，乾降著符，精感赤龍，承魁流裔，袭唐末風，寸木尺土，無Ａ斯亭，建號宣基，維以沛公，楊威斬蛇，金精摧傷，涉關凌灞，受爵漢中，勒兵陳東，剟禽三秦，陳張畫策，萧勃翼終，出爵襃賢，列土封功，炎火之德，弥光以明，源清流絜，本盛末弘，序將八十，贊述股肱，休勋顯祚，永永無彊，於皇舊亭，留嗣是承，天之福祐，萬年是興。","sortOrder":56},
  {"id":"s_work_nvlt_12_57","chapterId":"ch_work_nvlt_12","text":"【論】後漢孔融周武王漢高祖論曰：武王從後稷以來，至其身，相承積五十世，俱有魚鳥之瑞，至高祖一身修德，瑞有四，呂公望形而荐女，呂後見雲知其處，白蛇分，神武哭，西入關，五星聚。又武王伐紂，斬而刺之，高祖入秦，赦子婴而遺之，是宽裕又不如高祖也。","sortOrder":57},
  {"id":"s_work_nvlt_12_58","chapterId":"ch_work_nvlt_12","text":"魏高貴乡公少康漢高祖論曰：上問荀顗等曰：有夏既衰，後相殄滅，少康收辑夏眾，复禹之績，高祖拔起垄畝，芟夷秦項，考其功德，誰宜為先，顗等曰：造之與因，難易不同，少康功德雖美，猶為中興，與漢世祖同流可也，至如高祖，臣等以為優，上曰：少康生於滅亡之後，降為諸侯之隸，能布其德而兆有其謀，卒滅過戈，复禹之績，祀夏配天，不失舊物，非至德弘仁，豈濟斯勋，漢祖因土崩之势，收一時之權，為人子則數危其親，為人君則因賢相，為人父則不能衛子，身殁之後，社稷幾傾，若與少康易地而處，或未能复大禹之績也，推此言之，宜高夏康而下漢祖矣。","sortOrder":58},
  {"id":"s_work_nvlt_12_59","chapterId":"ch_work_nvlt_12","text":"◇漢文帝","sortOrder":59},
  {"id":"s_work_nvlt_12_60","chapterId":"ch_work_nvlt_12","text":"《史記》曰：孝文皇帝，初立為代王，都中都，高後崩，呂產等欲為亂，以危劉氏，大臣共誅之，使人迎代王，代王問左右郎中令張武，張武等議，原大王稱疾以無往，觀其变，中尉宋昌進曰：群臣議皆非也，今高帝子，獨淮南王與大王，大王又長，賢聖仁孝，聞於天下，故大臣因天下之心而欲迎立大王，大王勿疑也，乃命宋昌參乘，張武等六人乘傳，詣長安，馳入代邸，代王西乡讓者再，遂即天子位。","sortOrder":60},
  {"id":"s_work_nvlt_12_61","chapterId":"ch_work_nvlt_12","text":"又曰：孝文帝即位二十三年，宮室苑囿，狗馬服御，無所增益，有不便，辄弛以利民，常欲作露台，召匠計之，直百金，帝曰：百金中民十家之產，吾奉先帝宮室，常恐羞之，何以台為，所幸慎夫人，衣不曳地，帏帳不得文繡，以示敦朴，先與匈奴和親，匈奴背約入盜，然令邊備守，不得發兵深入，惡煩苦百姓，群臣如袁盎等，稱說雖切，常假借用之，群臣如張武受賂遺金錢，覺，上常發御府金錢賜之，以愧其心，专務以德化民，是以海內殷富，興於禮義。","sortOrder":61},
  {"id":"s_work_nvlt_12_62","chapterId":"ch_work_nvlt_12","text":"又曰：孔子言必世而後仁，善人為邦百年，亦可以勝殘去殺矣，誠哉是言，漢興至孝文，四十有餘載，德至盛也。","sortOrder":62},
  {"id":"s_work_nvlt_12_63","chapterId":"ch_work_nvlt_12","text":"《漢書》曰：孝文皇帝讳恒，高帝中子也，母曰薄皇後。","sortOrder":63},
  {"id":"s_work_nvlt_12_64","chapterId":"ch_work_nvlt_12","text":"又曰：文帝斷獄四百，幾致刑措。","sortOrder":64},
  {"id":"s_work_nvlt_12_65","chapterId":"ch_work_nvlt_12","text":"又曰：武帝問東方朔曰：吾欲化民，豈有道乎，朔對曰：原近述孝文皇帝之時，當世耆老，皆聞見之，貴為天子，富有四海，身衣弋綈，足履革舄，以韦帶劍，莞蒲為席，集上書囊為殿帷。","sortOrder":65},
  {"id":"s_work_nvlt_12_66","chapterId":"ch_work_nvlt_12","text":"【述】後漢班固文帝述曰：太宗穆穆，允恭玄默，化民以躬，師下以德，農不共貢，罪不收帑，宮不新馆，陵不崇墓，我德如風，民應如草，國富刑清，登我漢道。","sortOrder":66},
  {"id":"s_work_nvlt_12_67","chapterId":"ch_work_nvlt_12","text":"【贊】魏陳王曹植漢文帝贊曰：孝文即位，愛物檢身，驕吳撫越，匈奴和親，納諫赦罪，以德讓民，殆至刑错，萬國化淳。","sortOrder":67},
  {"id":"s_work_nvlt_12_68","chapterId":"ch_work_nvlt_12","text":"◇漢景帝","sortOrder":68},
  {"id":"s_work_nvlt_12_69","chapterId":"ch_work_nvlt_12","text":"《史記》曰：漢興，孝文施德，天下懷安，至孝景，不复忧異姓，而晁错刻削諸侯，遂使七國俱起，合從而西乡，以諸侯大盛，而错為之不以漸也，及主父偃言之，而諸侯以弱，卒以安漢，安危之幾，豈不以謀哉。","sortOrder":69},
  {"id":"s_work_nvlt_12_70","chapterId":"ch_work_nvlt_12","text":"《漢書》曰：孝景帝讳啟，文帝大子也，母曰窦皇後。","sortOrder":70},
  {"id":"s_work_nvlt_12_71","chapterId":"ch_work_nvlt_12","text":"又曰：孔子稱斯民三代之所以直道而行也，信哉，周秦之獘，網密文峻，而奸宄不勝，漢興，拂除煩苛，與民休息，至孝文，加之以恭俭，孝景遵業，五六十載之間，至於移風易俗，黎民醇厚，周雲成康，漢言文景，美矣。","sortOrder":71},
  {"id":"s_work_nvlt_12_72","chapterId":"ch_work_nvlt_12","text":"【述】後漢班固景帝述曰：孝景莅政，諸侯方命，剋伐七國，王室以定，非怠非荒，務在農桑，著於甲令，民用寧康。","sortOrder":72},
  {"id":"s_work_nvlt_12_73","chapterId":"ch_work_nvlt_12","text":"【贊】魏陳王曹植漢景帝贊曰：景帝明德，繼文之則，肅清王室，克滅七國，省役薄賦，百姓殷昌，風移俗易，齊美成康。","sortOrder":73},
  {"id":"s_work_nvlt_12_74","chapterId":"ch_work_nvlt_12","text":"◇漢武帝","sortOrder":74},
  {"id":"s_work_nvlt_12_75","chapterId":"ch_work_nvlt_12","text":"《漢書》曰：孝武皇帝讳彻，景帝中子也，元封元年，行自雲陽，北歷上郡西河五原，出長城，登单於台，臨北河，勒兵十八萬騎，旌旗千餘里，威震匈奴，還，登封泰山。又自潯陽浮江，親射蛟江中，獲之，舳舻千里。又登之罦，東來(漢書武紀註作萊。)有之罦山祠，浮大海，山稱萬歲。","sortOrder":75},
  {"id":"s_work_nvlt_12_76","chapterId":"ch_work_nvlt_12","text":"又曰：漢承百王之弊，高祖拨亂反正，文景務在養民，至於稽古禮文之事，猶多闕焉，孝武初立，卓然罢黜百家，表章六經，遂畴咨海內，舉其俊民，與之立功，興太學，修郊祀，改正朔，定歷數，协音律，作詩樂，建封禪，祀百神，號令文章，煥焉可述，後嗣得遵洪業，而有三代之風，如武帝之雄材大略，不改文景之恭俭，以濟斯民，雖詩書所稱，何有加焉。","sortOrder":76},
  {"id":"s_work_nvlt_12_77","chapterId":"ch_work_nvlt_12","text":"荀悅《漢紀》曰：武皇帝恢萬世業，內脩文學，外曜武威，延天下之士，濟濟盈朝，興事創製，無所不施，先王之風，粲然存矣，然猶好其文，未盡其實，發其始，不克其終，奢侈無限，窮兵極武，百姓空竭，萬民罢弊，當此之時，天下骚然，海內無聊，而孝文之業衰矣。","sortOrder":77},
  {"id":"s_work_nvlt_12_78","chapterId":"ch_work_nvlt_12","text":"劉歆《七略》曰：孝武皇帝，敕丞相公孫弘，廣开獻書之路，百年之間，書積如丘山，故外則有太常太史博士之藏，內則有延閣廣內秘室之府。","sortOrder":78},
  {"id":"s_work_nvlt_12_79","chapterId":"ch_work_nvlt_12","text":"《桓子新論》曰：漢武帝材质高妙，有崇先廣統之規，故即位而开發大志，考合古今，模獲前聖故事，建正朔，定製度，招選俊杰，奋扬威怒，武義四加，所征者服，興起六藝，廣進儒術，自开辟以來，唯漢家最為盛焉，故顯為世宗，可謂卓爾絕世之主矣，然上多過差，既欲斥境廣土。又乃貪利爭物之無益者，聞西夷大宛國有名馬，即大發軍兵，攻取歷年，士眾多死，但得數十疋耳。又歌兒衛子夫，因幸愛重，乃陰求陳皇後過惡而废退之，即立子夫，更其男為太子，後聽邪臣之谮，衛後以忧死，太子出走滅亡，不知其處，信其巫蠱，多徵會邪僻，求不急之方，大起宮室，內竭府軍，［《太平御覽》八十八作库。］外罢天下，百姓之死亡，不可勝數，此可謂通而蔽者也。","sortOrder":79},
  {"id":"s_work_nvlt_12_80","chapterId":"ch_work_nvlt_12","text":"《典論》曰：孝武承四世之遺業，遇中國之殷阜，府库餘金錢，仓廪畜腐粟，因此有意乎滅匈奴，而得清邊境矣，故即位之初，從王恢之畫，設馬邑之謀，自元光以迄征和，四五十載之間，征匈奴四十餘舉，盛餘［二字御覽八十八引無，此有訛脱。］逾廣漢，絕梓嶺，封狼居，禪姑幕，梁北河，觀兵潮［御覽八十八作瀚。］海，刈单於之旗，剿閼氏之首，探符離之窟，扫五王之庭，納休屠崑耶之附，獲祭天金人之寶，斬名王以千數，馘酋虜以萬計，既窮追其散亡。又摧破其積聚，虜不暇於救死扶傷，疲困於孕重墮殒，元封初，躬執武節，告以天子自將，懼以兩越之誅，彼時號為威震匈奴矣。","sortOrder":80},
  {"id":"s_work_nvlt_12_81","chapterId":"ch_work_nvlt_12","text":"【述】後漢班固武帝述曰：世宗晔晔，思弘祖業，畴咨熙載，髦俊併作，厥作伊何，百蠻是攘，恢我疆宇，薄於四荒，武功既抗，亦迪斯文，憲章六學，統一聖真，封禪郊祀，祭旅百神，协律改王，饗茲永年。","sortOrder":81},
  {"id":"s_work_nvlt_12_82","chapterId":"ch_work_nvlt_12","text":"【贊】魏陳王曹植漢武帝贊曰：世宗光光，文武是攘，威震百蠻，恢拓土疆，簡定律歷，辨脩舊章，封天禪土，功越百王。","sortOrder":82},
  {"id":"s_work_nvlt_12_83","chapterId":"ch_work_nvlt_12","text":"周庾信漢武帝聚書贊曰：獻書路廣，藏書府开，秦儒出穀，漢簡吹灰，芝泥印上，玉匣封來，坐觀風俗，不出蘭台。","sortOrder":83},
  {"id":"s_work_nvlt_12_84","chapterId":"ch_work_nvlt_12","text":"◇漢昭帝","sortOrder":84},
  {"id":"s_work_nvlt_12_85","chapterId":"ch_work_nvlt_12","text":"《漢書》曰：昭皇帝讳弗，武帝子也，母曰趙婕妤，本以有奇異得幸，［婕妤有奇，謂手指不申，及有奇氣。］及生帝，亦奇異，［十四月乃生。］","sortOrder":85},
  {"id":"s_work_nvlt_12_86","chapterId":"ch_work_nvlt_12","text":"又曰：昔周成以孺子繼統，而有管蔡四國流言之变，孝昭幼年即位，亦有燕蓋上官逆謀之亂。成王不疑周公，孝昭委任霍光，各因其時以成名，大矣哉，承孝武奢侈餘獘，師旅之後，海內虛耗，戶口减半，知時務之要，輕徭薄賦，與民休息，至始元元鳳之間，匈奴和親，百姓充實，舉賢良文學，問民所疾苦，議鹽鐵而罢榷酤，尊號曰昭，不亦宜乎。","sortOrder":86},
  {"id":"s_work_nvlt_12_87","chapterId":"ch_work_nvlt_12","text":"【述】後漢班固昭帝述曰：孝昭幼冲，冢宰推忠，燕蓋诪張，實叡實聰，罪人斯得，邦家和同。","sortOrder":87},
  {"id":"s_work_nvlt_12_88","chapterId":"ch_work_nvlt_12","text":"【論】魏文帝周成漢昭論曰：或方周成王於漢昭帝，佥高成而下昭，餘以為周成王體上聖之休氣，禀賢妣之貽誨，周召為保傅，呂尚為太師，口能言則行人稱辭，足能履則相者导儀，目厭威容之美，耳飽仁義之聲，所謂沉渍玄流，而沐浴清風者矣，猶有咎悔，聆二叔之謗，使周公東遷，皇天赫怒，顯明厥咎，猶啟諸金縢，稽諸國史，然後乃悟，不亮周公之聖德，而信金縢之教言，豈不暗哉，夫孝昭父非武王，母非邑薑，養惟蓋主，相則桀光，體不承聖，化不胎育，保無仁孝之质，佐無隆平之治，所謂生於深宮之中，長於婦人之手，然而德與性成，行與體併，年在二七，早智夙達，發燕書之诈，亮霍光之誠，豈將有啟金縢，信國史，而後乃寤哉，使夫昭成均年而立，易世而化，貿臣而治，換樂而歌，則漢不獨少，周不獨多也。","sortOrder":88},
  {"id":"s_work_nvlt_12_89","chapterId":"ch_work_nvlt_12","text":"魏丁儀周成漢昭論曰：成王昭帝，俱以襁褓之幼，讬於冢宰，流言讒興，此其艱险相似者也，夫以發金縢然後垂泣，與計日力便覺诈書，明之遲速，既有差矣，且叔父兄子，非相嫌之處，異姓君臣，非相信之地，霍光罹人謗而不出，周公賴天变而得入，推此數者，齊本而論末，計重而况輕，漢昭之優周成甚明者也，成王秀而獲實，其美在終，昭帝苗而未秀，其得在始，必不得已而論二主，餘與夫始者。","sortOrder":89},
  {"id":"s_work_nvlt_12_90","chapterId":"ch_work_nvlt_12","text":"◇漢宣帝","sortOrder":90},
  {"id":"s_work_nvlt_12_91","chapterId":"ch_work_nvlt_12","text":"《漢書》曰：孝宣皇帝讳詢，字次卿，武帝曾孫，戾太子孫也，太子納史良娣，生皇孫，皇孫納王夫人，生皇帝，號曰皇曾孫，生數月，遭巫蠱事，太子良娣皇孫王夫人皆遇害，曾孫坐系郡邸獄，邴吉為廷尉監，治巫蠱，怜曾孫之無辜，使女徒乳養，私給衣食，至後，望氣者言長安獄有天子氣，上遣使皆殺之，內者令郭欀，［漢書宣紀，《太平御覽》八十九作穰。］夜至郡邸獄，吉拒閉不得入，曾孫賴吉得全，因遭赦，高才好學，然亦喜遊俠，斗雞走馬，具知闾里奸邪，吏治得失，時會朝請，舍長安尚冠里，身足下有毛，臥居數有光耀，昭帝崩，無嗣，霍光徵昌邑王贺，贺淫亂废，光奏遣宗正德至尚冠里舍洗沐，賜御府，［○《太平御覽》八十九府下有衣字。］太仆以軨轕車奉迎曾孫，就齊宗正府，封為陽武侯，群臣上玺綬，即皇帝位。","sortOrder":91},
  {"id":"s_work_nvlt_12_92","chapterId":"ch_work_nvlt_12","text":"又曰：宣帝始立，謁見高廟，大將軍光參乘，上內嚴憚之，若芒刺在背，後張安世代光參乘，天子從容肆意，甚安。","sortOrder":92},
  {"id":"s_work_nvlt_12_93","chapterId":"ch_work_nvlt_12","text":"又曰：孝宣之治，信賞必罰，綜覈名實，政事文學法理之士，鹹精其能，至於技巧工匠器械，自元成間，鮮能及之者，亦足以知吏稱其職，民安其業也，遭值匈奴乖亂，推亡固存，信威北夷，单於慕義，稽首稱蕃，功光宗祖，業垂後嗣，可謂中興，侔德殷宗周宣矣。","sortOrder":93},
  {"id":"s_work_nvlt_12_94","chapterId":"ch_work_nvlt_12","text":"荀悅漢紀曰：孝宣任法審刑，綜覈名實，聽斷精明，事業修理，下無隱情，是以功光前世，號為中宗，然不甚用儒術，是以德化不能純備。","sortOrder":94},
  {"id":"s_work_nvlt_12_95","chapterId":"ch_work_nvlt_12","text":"【述】後漢班固宣帝述曰：中宗明明，寅用刑名，時舉博納，聽斷惟精，柔遠能邇，煇燿威靈，龍荒漠朔，莫不來庭，丕顯祖烈，尚於有成。","sortOrder":95},
  {"id":"s_work_nvlt_12_96","chapterId":"ch_work_nvlt_12","text":"◇後漢光武帝","sortOrder":96},
  {"id":"s_work_nvlt_12_97","chapterId":"ch_work_nvlt_12","text":"《東觀漢記》曰：世祖光武皇帝，高祖九世孫，出自長沙定王，定王生舂陵節侯，舂陵本在零陵郡，節侯孫孝侯，以土地下濕，元帝時，求封南陽蔡陽白水乡，因故國名曰舂陵，上隆准日角，大口，美須眉，身長七尺三寸，仁智明達，多權略，樂施愛人，在家重慎畏事，勤於稼穡，兄伯升，好俠，笑上事田作，比之高祖兄仲，上歸舊庐，望見庐南有火光，以為人持火，呼之，光遂赫然屬天，有頃不見，上異之，初伯升之起也，諸家子弟皆亡逃自匿，曰：伯升殺我，及聞上至，絳衣大冠，乃驚，以為獨伯升如此，謹厚者亦為之。","sortOrder":97},
  {"id":"s_work_nvlt_12_98","chapterId":"ch_work_nvlt_12","text":"又曰：王莽遣大司徒王尋大司空王邑，將兵來征，莽欲盛威武，王齊則［三字有訛脱，《太平御覽》九十作以振山東，至驅六字。］虎豹犀象，奇伟猛獸，以長人巨無霸為壘校尉，秦漢以來師出，未嘗有也，時漢兵八九千人，二公兵以五六十萬，到，遂環崑陽城作營，且围之數百重，有流星墜尋營，營中正晝有雲氣，如坏山直下營而不及地尺而散，吏士皆厭伏，上選精兵三千人與戰，大破之，殺司徒王尋，赴水溺死者以萬數，滍水為之不流，更始以上為大司馬，遣之河北，安集百姓，破邯鄲，誅王郎，入宮收文書，尋得吏民謗毀上言可击者數千章，上會諸將燒之，曰：令反侧子自安也，更始遣使者立上為萧王。又击破銅馬，受降適畢，賊亦兩心，上敕降賊各歸勒兵待，上輕騎入，按行賊營，賊曰：萧王推赤心置人腹中，安得不投死，由是皆自安。","sortOrder":98},
  {"id":"s_work_nvlt_12_99","chapterId":"ch_work_nvlt_12","text":"又曰：諸將請上尊號，初王莽時，上與伯叔及姊婿邓晨攘人蔡少公坐語，少公道讖言劉秀當為天子，或曰是國師劉子駿也，上戲曰：何用知仆非也，坐者皆大笑，時傳聞赤伏符，不見文章軍中所，上未信，到鄗，上所與長安同舍諸生強華，自長安奉赤伏符詣鄗，與上會，群臣复伏固，［御覽固下有請字。］乃命有司設壇鄗之千秋亭，六月，即皇帝位。","sortOrder":99},
  {"id":"s_work_nvlt_12_100","chapterId":"ch_work_nvlt_12","text":"袁宏漢紀曰：南頓令钦，生光武皇帝，讳秀，字文叔。","sortOrder":100},
  {"id":"s_work_nvlt_12_101","chapterId":"ch_work_nvlt_12","text":"《帝王世紀》曰：春秋興［《太平御覽》九十作稱。］夏少康之起，有田一成，有眾一旅，若漢之策命世祖，不階成旅之資，平暴反正，遂建中興，夏少康同美矣。","sortOrder":101},
  {"id":"s_work_nvlt_12_102","chapterId":"ch_work_nvlt_12","text":"《續漢書》曰：昔羿寒浞篡夏數十年，少康生為牧人，能修德复夏，厥勋大矣，然尚有虞思及靡有鬲內外之助，至於光武，承王莽之篡，起自疋庶，一民尺土，靡有凭焉，發跡於崑陽，以數千屠百萬，非胆智之至，孰能堪之，讨賊平亂，克复漢業，號稱中興，雖初興者無以加之矣，中國既定，柔遠以德，愛慎人命，下及至賤，武功既抗，文德術修，［武功以下，《太平御覽》九十作武功既備，抗文德，脩經術，此有訛倒。］勋績弘矣。","sortOrder":102},
  {"id":"s_work_nvlt_12_103","chapterId":"ch_work_nvlt_12","text":"薛瑩漢紀曰：王莽之际，天下雲亂，英雄併發，其跨州據郡，僣製者多矣，人皆有冀於非望，然考其聰明仁勇，自無光武儔也，加以宽博容納，計慮如神，是以任光窦融，望風景附，馬援一見，睹顏識奇，故能以十數年間，扫除群凶，清复海內，豈非天人之所辅贊哉，古者師不內御，而光武命將，皆授以方略，使奉圖而進，其有违失，無不折傷，意豈文史之過乎，不然，雖聖人其猶病諸。","sortOrder":103},
  {"id":"s_work_nvlt_12_104","chapterId":"ch_work_nvlt_12","text":"袁山松《後漢書》曰：前漢自成哀已下，天地縱橫，巨猾竊命，劉氏舊泽猶存，而瞻乌之望殆絕，世祖以眇眇之胤，起白水之濱，身屈無妄之力，位舉群賢併列，［御覽九十作位與群竖併列，此有訛文。］於時懷玺者十餘，建旗者數百，高才者居南面，疾足者為王公，茫茫九州，瓜分脔切，湣湣蒼生，尘消鼎沸，我扇之以仁風，驅之以大威，雪霜被而茨棘枯，橫網振而逆鱗扫，群材畢凑，人鬼與能，數年之間，廓清四海，雖曰中興，與夫始創業者，庸有異乎，誠哉馬生之言，固已寥廓大度，同符高祖。又等太宗之仁，兼孝宣之明，一人之體，其殆於周，故能享有神器，據乎萬乘之上矣。","sortOrder":104},
  {"id":"s_work_nvlt_12_105","chapterId":"ch_work_nvlt_12","text":"【碑】後漢蔡邑光武濟陽宮碑曰：王室中微，哀平短祚，奸臣王莽，偷有神器，十有八年，罪盈惡熟，天人致誅，帝乃龍見白水，淵躍崑滍，破前队之眾，殄二公之師，收兵略地，經營河朔，於是群公諸將，據河洛之文，协符瑞之徵，佥曰歷數在帝，踐祚允宜，乃以建武元年六月，即位於鄗縣之陽，五成之陌，祀漢配天，罔失舊物，享國三十有三年，方內乂安，蠻夷率服，巡狩太山，禪梁父，皇代之遐跡，帝者之上儀，罔不畢舉，道德餘慶，延於無窮，先民有言曰：樂樂其所自生，而禮不忘其本，是以虞稱妫汭，姬美周原，皇天乃眷，神宮實始於此，厥路藐哉，所謂神麗顯融，越不可尚，小臣河尹玮，來在濟陽，顧見神宮，追惟桑梓褒述之義，用敢作頌，其辭曰：赫赫炎天，爰曜其暉，篤生聖皇，貳漢之微，稽度虔則，誕育靈姿，黃孽作慝，篡握天機，帝赫斯怒，爰整其師，應期潛見，扶陽而飛，禍亂克定，群凶殄夷，匡复帝載，萬國以綏，巡於四嶽，展義省方，登封降禪，升於中皇，爰茲初基，天命孔彰，子子孫孫，保之無疆。","sortOrder":105},
  {"id":"s_work_nvlt_12_106","chapterId":"ch_work_nvlt_12","text":"【論】魏陳王曹植漢二祖優劣論曰：客有問餘曰：夫漢二帝，高祖光武，俱為受命拨亂之君，此時事之難易，論其人之優劣，孰者為先，餘應之曰：昔漢之初興，高祖因暴秦而起，遂誅強楚，先［《太平御覽》四百四十七作光。］有天下，功齊湯武，業流後嗣，誠帝王之元勋，人君之盛事也，然而名不繼德，行不純道，身没之後，崩亡之际，果令凶婦肆酖酷之心，嬖妾被人豕之刑，亡趙幽囚，禍殃骨肉，諸呂专權，社稷幾移，凡此諸事，豈非高祖寡計淺慮以致，然彼之雄才大略，俶傥之節，信當世至豪健壮杰士也。又其枭將畫臣，皆古今之鮮有，歷世之希睹，彼能任其才而用之，聽其言而察之，故兼天下，有帝位，流巨勋而遺元功也，世祖體乾靈之休德，禀貞和之純精，通黃中之妙理，韜亚聖之懿才，其為德也，聰達而多識，仁智而明恕，重慎而周密，樂施而愛人，值陽九無妄之世，遭炎光厄會之運，殷爾雷發，赫然神舉，用武略以攘暴，興義兵以扫殘，神光前驅，威風先逝，軍未出於南京，莽已毙於西都，夫其荡涤凶秽，剿除丑類，若順迅風而縱烈火，曬白日而扫朝雲也，爾乃廟勝而後動眾，計定而後行師，故攻無不陷之壘，戰無奔北之卒，是以群下欣欣，歸心聖德，宣仁以和眾，邁德以來遠，故窦融聞聲而影附，馬援一見而叹息，股肱有濟濟之美，元首有穆穆之容，敦睦九族，有唐虞之稱，高尚純朴有羲皇之素，謙虛納下，有吐握之勞，留心庶事，有日昃之勤，乃規弘跡而造皇極，創帝道而立德基，是以計功則業殊，比隆則事異，旌德則靡愆，言行則無秽，量力則势微，論辅則力劣，卒能握乾圖之休徵，應五百之顯期，立不刊之遐跡，建不朽之元功，金石播其休烈，詩書載其勋懿，故曰光武其優也。","sortOrder":106},
  {"id":"s_work_nvlt_12_107","chapterId":"ch_work_nvlt_12","text":"◇漢明帝","sortOrder":107},
  {"id":"s_work_nvlt_12_108","chapterId":"ch_work_nvlt_12","text":"《東觀漢記》曰：孝明皇帝，世祖中子也，母光烈皇後，初讓尊位為貴人，故帝年十二，以皇子立為東海公，三歲，進爵為王，幼而聰明叡智，容濬壮麗，世祖異焉，數問以政議，應對敏達，謨慮甚深，溫恭好學，敬愛師傅，所以承事兄弟，親密九族，內外周洽，世祖愈珍上德，以為宜承先序，詔废郭皇後，立陰貴人以為皇後，上以東海王立為皇太子，治尚書，備師法，兼通四經，略舉大義，博觀群書，以助術學。","sortOrder":108},
  {"id":"s_work_nvlt_12_109","chapterId":"ch_work_nvlt_12","text":"又曰：建武四年，皇子陽生，丰下銳上，顏赤色，有似尧，上以赤色，名之曰陽，年十三，通春秋，上循其頸曰：吳季子，袁山松《後漢書》曰：皇帝讳陽，一名莊，字子麗。","sortOrder":109},
  {"id":"s_work_nvlt_12_110","chapterId":"ch_work_nvlt_12","text":"華峤《後漢書》曰：世祖既以吏事自婴，明帝尤任文法，總攬威柄，權不借下，值天下初定，四民樂業，戶口滋殖，中興以來，追蹤宣帝，以鍾離意之廉淳，諫爭恳恳，常以宽和為首，以此推之，難得而言也。","sortOrder":110},
  {"id":"s_work_nvlt_12_111","chapterId":"ch_work_nvlt_12","text":"薛瑩漢紀曰：明帝自在储宮，而聰允之德著矣，及臨萬機，以身率禮，恭奉遺業，一以貫之，雖夏啟周成，繼體持統，無以加焉，是以海內乂安，四夷賓服，斷獄希少，有治平之風，號曰顯宗，不亦宜乎。","sortOrder":111},
  {"id":"s_work_nvlt_12_112","chapterId":"ch_work_nvlt_12","text":"范晔《後漢書》曰：帝善刑理，法令分明，日晏坐朝，幽枉必達，外內無倖曲之私，在上無矜大之色，斷獄得情，號居前世十二，故後之言事者，莫不先建武永平之政，然而鍾離意宋均之徒，常以察惠為言，夫豈弘仁之度未優乎。","sortOrder":112},
  {"id":"s_work_nvlt_12_113","chapterId":"ch_work_nvlt_12","text":"【贊】晉傅玄漢明帝贊曰：肅矣孝明，杖法任刑，勤綜萬機，察下以情，未弘道治，用致太平，专信俗儒，非禮之經。","sortOrder":113},
  {"id":"s_work_nvlt_12_114","chapterId":"ch_work_nvlt_12","text":"【诔】漢傅毅明帝诔曰：惟此永平，其德不回，恢廓鸿績，遐方是懷，明明肅肅，四國順威，赫赫盛漢，功德巍巍，躬履聖德，以臨萬國，仁風弘惠，雲布雨集，武伏蚩尤，文騰孔墨，下製九州，上系皇極，丰美中世，垂華亿載，冠尧佩舜，踐履五代，三雍既洽，帝道繼備，七經宣畅，孔業淑著，明德慎罰，尊上師傅，薄刑厚賞，惠慈仁恕，明併日月，無有偏照，譬如北辰，與天同曜，發號施令，萬國震懼，庠序設陳，禮樂宣布，璇璣所建，靡不奄有，貢篚納賦，如歸父母，正朔永昌，冠帶儋耳，四方共貫，八極同軌。","sortOrder":114},
  {"id":"s_work_nvlt_12_115","chapterId":"ch_work_nvlt_12","text":"◇漢和帝","sortOrder":115},
  {"id":"s_work_nvlt_12_116","chapterId":"ch_work_nvlt_12","text":"《東觀漢記》曰：孝和皇帝，章帝中子也，上自歧嶷，至於總角，孝順聰明，宽和仁孝，帝由是深珍之，以為宜承天位，年四歲，立為太子，初治尚書，遂兼覽書傳，好古樂道，無所不照，上以五經義異，書傳意殊，親幸東觀，覽書林，閱篇藉，朝無寵族，惠泽沾濡，外忧庶績，內勤經藝，自左右近臣，皆誦詩書，德教在宽，仁恕併洽，是以黎元寧康，萬國协和，符瑞八十餘品，帝讓而不宣，故靡得而紀。","sortOrder":116},
  {"id":"s_work_nvlt_12_117","chapterId":"ch_work_nvlt_12","text":"《帝王世紀》曰：孝和之嗣世，正身履道，以奉大業，賓禮耆艾，動式舊典，宮無嫔嫱鄭衛之燕，囿無般樂遊畋之豫，躬履至德，虛靜自損，是以屢獲丰年，遠近承風。","sortOrder":117},
  {"id":"s_work_nvlt_12_118","chapterId":"ch_work_nvlt_12","text":"范晔《後漢書》曰：自中興以後，逮於永元，雖頗有施張，而俱存不扰，是以齊民歲增，辟土世廣，偏師出塞，則漢［後漢書和紀作漠。］北地空，都護西指，則通驿四萬，豈其道遠三代，術長前世，將服叛懷來，自有數也。","sortOrder":118},
  {"id":"s_work_nvlt_12_119","chapterId":"ch_work_nvlt_12","text":"【诔】後漢蘇順和帝诔曰：天王徂登，率土奄傷，如何昊穹，奪我聖皇，恩德累代，乃作銘章，其辭曰：恭惟大行，配天建德，陶元二化，風流萬國，立我蒸民，宜此儀則，厥初生民，三五作刚，載藉之盛，著於虞唐，恭惟大行，爰同其光，自昔何為，钦明允塞，恭惟大行，天覆地載，無為而治，冠斯往代，往代崎嶇，諸夏擅命，爰茲發號，民樂其政，奄有萬國，民臣鹹祑，大孝備矣，閟宮有侐，由昔薑嫄，祖妣之室，本枝百世，神契惟一，弥留不豫，道扬末命，勞謙有終，實惟其性，衣不製新，犀玉遠屏，履和而行，威稜上古，洪泽滂流，茂化沾溥，不玦少留，民斯何怙，歔欷成雲，泣涕成雨，昊天不弔，丧我慈父。","sortOrder":119},
  {"id":"s_work_nvlt_12_120","chapterId":"ch_work_nvlt_12","text":"後漢崔瑗和帝诔曰：玄景寢曜，雲物見徵，冯相考妖，遂當帝躬，三載四海，遏密八音，如丧考妣，擗踴號吟，大遂既啟，乃徂玄宮，永背神器，升遐皇穹，長夜冥冥，曷雲其窮。","sortOrder":120},
  {"id":"s_work_nvlt_12_121","chapterId":"ch_work_nvlt_12","text":"《藝文類聚》　唐·欧陽詢","sortOrder":121},
  {"id":"s_work_nvlt_13_1","chapterId":"ch_work_nvlt_13","text":"卷十三帝王部三","sortOrder":1},
  {"id":"s_work_nvlt_13_2","chapterId":"ch_work_nvlt_13","text":"○魏武帝魏文帝吳大帝晉武帝晉元帝晉成帝晉康帝晉穆帝晉簡文帝晉孝武帝宋武帝宋孝武帝","sortOrder":2},
  {"id":"s_work_nvlt_13_3","chapterId":"ch_work_nvlt_13","text":"◇魏武帝","sortOrder":3},
  {"id":"s_work_nvlt_13_4","chapterId":"ch_work_nvlt_13","text":"《魏志》曰：太祖武皇帝，沛國谯人，讳操，字孟德，漢相曹參之後也，時曹騰為中常侍大長秋，養子嵩，嗣父，嵩官至太尉，太祖少機警，有權數，而任俠放荡，不治行業，故世人未之奇也，唯梁國乔玄南陽何顒，謂太祖曰：天下將亂，非命世之才，不能濟也，能安之者，其在君乎，初，桓帝時，有黃星見於楚宋之分，遼東殷馗善天文，言後五十歲，當有真人起於梁沛之間，其鋒不可當也，至是凡五十年，而公破袁紹，天下莫敵矣。","sortOrder":4},
  {"id":"s_work_nvlt_13_5","chapterId":"ch_work_nvlt_13","text":"【诔】魏陳王曹植武帝诔曰：於惟我王，承運之衰，神武震發，群雄殄夷，拯民於下，登帝太微，德美旦奭，功越彭韦，九德光備，萬國作師，寢疾不興，聖體長歸，華夏飲淚，黎庶含悲，神翳功顯，身沉名飛，敢扬聖德，表之素旗，乃作诔曰：於穆我王，胄稷胤周，賢聖是紹，元懿允休，先侯佐漢，實惟平陽，功成績著，德昭二皇，民以寧一，興詠有章，我王承統，天姿時生，年在志學，謀過老成，奋臂舊邦，翻身上京，表與我王，兵交若神，張陳背誓，傲帝虐民，擁徒百萬，虎视朔濱，我王赫怒，戎車列陳，武卒虓阚，如雷如震，攙搶北扫，舉不浃辰，紹遂奔北，河朔是賓，振旅京室，帝嘉厥庸，乃位承相，總攝三公，光受上爵，臨君魏邦，九錫昭備，大路火龍，玄監靈蔡，探幽洞微，下無伪情，奸不容非，敦俭尚古，不玩珠玉，以身先下，民以純朴，聖性嚴毅，平修清一，唯善是嘉，靡疏靡昵，怒過雷霆，喜逾春日，萬國肅虔，望風震栗，既總庶政，兼覽儒林，躬著雅頌，被之瑟琴，茫茫四海，我王康之，微微漢嗣，我王匡之，群桀扇動，我王服之，喁喁黎庶，我王育之，光有天下，萬國作君，虔奉本朝，德美周文，以宽克眾，每征必舉，四夷賓服，功逾聖武，翼帝王世，神武鷹扬，左鉞右旄，威凌伊呂，年逾耳順，體愉志肅，乾乾庶事，氣過方叔，宜併南嶽，君國無窮，如何不弔，禍鍾聖躬，弃離臣子，背世長終，兆民號咷，仰愬上穹，既以約終，令節不衰，既即梓宮，躬御缀衣，玺不存身，唯紼是荷，明器無飾，陶素是嘉，既次西陵，幽閨啟路，群臣奉迎，我王安厝，窈窈玄宇，三光不入，潛闼一扃，尊靈永蟄，聖上臨穴，哀號靡及，群臣陪臨，佇立以泣，去此昭昭，於彼冥冥，永弃兆民，下君百靈，千代萬葉，曷時复形。","sortOrder":5},
  {"id":"s_work_nvlt_13_6","chapterId":"ch_work_nvlt_13","text":"【策文】魏文帝為武帝策文曰：痛神曜之幽潛，哀鼎俎之虛置，舒皇德而詠思，遂腷臆以莅事，矧乃小子，夙遭不造，豭豭在疚，呜呼皇考，產我曷晚，弃我曷早，群臣子辅，奪我哀原，猥抑奔墓，俯就權变，卜葬既從，大隧既通，漫漫長夜，窈窈玄宮，有晦無明，曷有所窮，滷簿既整，三官骈羅，前驅建旗，方相執戈，弃此宮庭，陟彼山阿。","sortOrder":6},
  {"id":"s_work_nvlt_13_7","chapterId":"ch_work_nvlt_13","text":"◇魏文帝","sortOrder":7},
  {"id":"s_work_nvlt_13_8","chapterId":"ch_work_nvlt_13","text":"《魏志》曰：文皇帝讳丕，字子桓，武帝太子也，為五官中郎將，嗣丞相為魏太子，太祖崩，繼位為丞相魏王，延康元年，受禪於漢為帝，初，帝自許昌南征，諸軍兵併進，孫權臨江拒守，帝幸廣陵收［《太平御覽》九十三作故。］城臨江觀兵，戎卒十餘萬，旌旗數百里。","sortOrder":8},
  {"id":"s_work_nvlt_13_9","chapterId":"ch_work_nvlt_13","text":"《江表傳》曰：魏文帝出廣陵，欲伐吳，臨大江叹曰：吳據洪流，且多糧穀，魏雖武騎千队，無所用之，乃還。","sortOrder":9},
  {"id":"s_work_nvlt_13_10","chapterId":"ch_work_nvlt_13","text":"《吳錄》曰：魏文帝至廣陵，臨江觀兵，見波涛汹涌，叹曰：此固天之所以隔北也，遂歸。","sortOrder":10},
  {"id":"s_work_nvlt_13_11","chapterId":"ch_work_nvlt_13","text":"【诔】魏陳王曹植文帝诔曰：天震地駭，崩山陨霜，陽精薄景，五緯错行，哀殊丧考，思慕過唐，擗踴郊野，仰愬穹蒼，考諸先紀，尋之哲言，生若浮寄，德貴長傳，朝聞夕逝，死志所存，皇雖殪没，天祿永延，何以述德，表之素旃，何以詠功，宣之管絃，乃作诔曰：元光幽昧，道究運遷，乾回歷數，簡聖授賢，乃眷大行，屬以黎元，龍飛踐祚，合契上玄，五行定紀，改號革年，明明赫赫，授命自天，風偃物化，德以禮宣，詳惟聖质，岐嶷幼齡，研機六典，學不過庭，潛心無內，抗志高明，才秀藻朗，如玉如瑩，聽察無响，视睹未形，其刚如金，其劲如琼，如冰之絜，如砥之平，爵功無重，戮违無輕，心鏡萬機，鑒照下情，宅土之中，率民以漸，道義是圖，弗營厥险，六合通同，齊契共檢，导下以純，民由朴俭，紼冕崇麗，衡紞惟新，尊肅禮容，瞻之若神，方牧妙舉，钦於恤民，虎將荷節，镇彼四鄰，朱旗所剿，九壤披震，畴克不若，孰敢不臣，懸旌海表，萬里無尘，回回凯風，祁祁甘雨，稼惟歲丰，登我稷黍，家佩惠君，戶蒙慈父，在位七載，九功仍舉，將承太和，絕跡三五，宜作物師，長為神主，寿終金石，等筭東父，如何奄忽，摧身後土，俾我豭豭，靡瞻靡顧，嗟嗟皇穹，胡寧忍予，明鑒吉凶，體達存亡，深垂典製，申之嗣皇，聖上虔奉，是順是將，乃啟玄宇，基於首陽，擬跡穀林，追尧纂唐，合山同阪，不树不疆，涂車萏靈，珠玉靡藏，百神警侍，賓於幽堂，於是侯大隧之致功，陳元辰之叔禎，潛華體於梓宮，凭正殿以居靈，悼晏駕之既俟，感容車之速征，浮飛魂於輕霄，就黃墟以藏形，背三光之昭晢，歸窀穸之冥冥，嗟一往之不返，痛閟闼之長扃。","sortOrder":11},
  {"id":"s_work_nvlt_13_12","chapterId":"ch_work_nvlt_13","text":"【章】魏陳王曹植慶文帝受禪章曰：陛下以聖德龍飛，順天革命，允答神符，誕作民主，乃祖先後，積德累仁，世濟其美，以暨於先王，王勤恤民隱，劬勞戮力，以除其害，經營四方，不遑啟處，是用隆茲福慶，光啟於魏，陛下承統，缵戎前緒，克廣德音，綏靜內外，紹先周之舊跡，袭文武之懿德，保大定功，海內為一，豈不休哉。又慶文帝受禪上禮章曰：陛下以明聖之德，受天顯命，良辰即祚，以臨天下，洪化宣流，洋溢宇內，是以溥天率土，莫不承風欣慶，執贽奔走，奉贺闕下，况臣親體至戚，懷歡踴躍。","sortOrder":12},
  {"id":"s_work_nvlt_13_13","chapterId":"ch_work_nvlt_13","text":"【表】魏文帝讓授禪表曰：臣聞尧禪重華，舉其克諧之德，舜授文命，采其齊聖之美，猶下咨四嶽，上觀璇璣，今臣德非虞夏，行非二後，而承歷數之詔，應選授之命，內自揆撫，無德以稱，且許由疋夫，猶拒帝位，善卷布衣，而逆虞詔，臣雖鄙蔽，敢忘守節。","sortOrder":13},
  {"id":"s_work_nvlt_13_14","chapterId":"ch_work_nvlt_13","text":"魏辛毗等勸進表曰：古先聖王，所以受天命而不辭者，誠急於答皇天之意，副四海之望，不得已也。","sortOrder":14},
  {"id":"s_work_nvlt_13_15","chapterId":"ch_work_nvlt_13","text":"魏桓階等勸進表曰：臣等以為天命不可稽，神器不可黷，昔周武中流有白魚之應，不待濟而大號以建，舜受禪大麓，桑陰未移，而已陟帝位，所以祗承天命者，若此之速也，故無固讓之義，不以守節為貴，必信於神靈，而符合於天地也。","sortOrder":15},
  {"id":"s_work_nvlt_13_16","chapterId":"ch_work_nvlt_13","text":"◇吳大帝","sortOrder":16},
  {"id":"s_work_nvlt_13_17","chapterId":"ch_work_nvlt_13","text":"《吳志》曰：孫權，字仲謀，漢以孫策遠修貢職，遣使者劉琬加錫命，琬語人曰：吾觀孫氏兄弟，雖各才秀明達，然皆祿祚不終，唯中弟孝廉，形濬奇伟，骨體不恒，有大貴之表。又最寿，策薨，以事授權。","sortOrder":17},
  {"id":"s_work_nvlt_13_18","chapterId":"ch_work_nvlt_13","text":"《江表傳》曰：堅為下邳丞時，權生，方颐大口，目有精光，堅異之，以為貴象，及堅亡，策起事江東，權常隨從，性度弘朗，仁而多斷，好俠養士。","sortOrder":18},
  {"id":"s_work_nvlt_13_19","chapterId":"ch_work_nvlt_13","text":"《吳歷》曰：曹公出濡須，權數挑戰，乃自乘舡，從濡口而入，公見舟舡器仗，徒伍整肅，喟然叹曰：生子當如孫權為，劉景升子，若纟屯犬耳。","sortOrder":19},
  {"id":"s_work_nvlt_13_20","chapterId":"ch_work_nvlt_13","text":"吳志，孫權屈伸忍辱，任才尚計，有勾踐之英奇，人之杰矣，故能自擅江表鼎峙之業，性嫌忌，果於殺戮，既於末年，弥以滋甚，至於讒說殄行，胤嗣废毙，豈所以貽厥孫謀，以燕翼子者哉，其後葉凌遲，遂致覆國，未必不由此也。","sortOrder":20},
  {"id":"s_work_nvlt_13_21","chapterId":"ch_work_nvlt_13","text":"【诔】晉陆機吳大帝诔曰：我皇明明，固天寔生，體和二合，以察三精，濯暉育慶，懷詳載榮，率性而和，因心則靈，厥靈伊何，克聖克仁，茂對四象，克配乾坤，齊明日月，考祥鬼神，誕自幼冲，叡哲宿照，甄化無形，探景絕曜，巍巍聖姿，文武既俊，有覺德徽，兆民欣順，將熙景命，經營九围，登跡岱宗，班瑞舊圻，上玄匪惠，早零聖暉，神庐既考，史臣獻貞，龍輴啟殯，宵載紫庭，辰旒飛藻，凶旗舉銘，崇華熠烁，翠蓋繁纓，千乘結驷，萬騎重營，箫鼓振响，和鑾流聲，動軫閶阖，永背承明，顯步萬官，幽驅百靈，隨化太素，即宮杳冥，亿兆同慕，泣血如零。","sortOrder":21},
  {"id":"s_work_nvlt_13_22","chapterId":"ch_work_nvlt_13","text":"◇晉武帝","sortOrder":22},
  {"id":"s_work_nvlt_13_23","chapterId":"ch_work_nvlt_13","text":"王隱《晉書》曰：世祖武皇帝，文帝太子也，文帝初开晉國，立為世子，拜撫軍大將軍，嗣相國文帝崩，魏帝命上為相國晉王，十一月，受禪於魏，有獻雉頭裘者，上曰：異服奇伎，典製所禁也，宜於殿前燒裘，上與羊祜張華謀伐吳，朝士莫知也，潛乃筹量虛實，為戰備，孫皓面縛舆榇降，有司奏，晉德隆茂，光被四表，吳會既平，六合為一，宜勒封嶽，以彰聖德，詔曰：此盛德之事，所宜未議。","sortOrder":23},
  {"id":"s_work_nvlt_13_24","chapterId":"ch_work_nvlt_13","text":"帝譜曰：世祖武皇帝，讳炎，字安世。","sortOrder":24},
  {"id":"s_work_nvlt_13_25","chapterId":"ch_work_nvlt_13","text":"【诔】晉潘嶽世祖武皇帝诔曰：粵若稽古帝皇，誕受休命，作我晉室，赫赫文皇，配天併日，大行龍飛，創製改物，沉恩汪濊，流泽洋溢，上齊七政，下綏萬邦，四門穆穆，五典克從，惟清緝熙，於变時雍，愛盡事親，教加百姓，於丧過哀，在祭餘敬，後蠶冕服，躬籍粢盛，六代畢奏，九功鹹詠，行敦醇朴，思貫玄妙，莅政端位，臨朝光曜，胄子入學，辟雍宗禮，國老恂恂，貴遊濟濟，莫孝匪子，莫悌匪弟，化自外明，訓法以禮，獷彼吳楚，稱亂三代，世歷五伪，年幾百載，邊垂虔劉，王化阻閡，羽檄星馳，鉦鼓日戒，帝御群師，奉辭奋旅，腹心庭爭，爪牙疑沮，天監獨照，聖策乃舉，朝服濟江，止戈曜武，野無交兵，役不淹月，僣號歸命，稽顙晉闕，邪界蠻流，傍納百越，表闾旌善，德音爰發，虞人獻箴，周書垂誥，酒懼其彝，獸戒其冒，於我大行，縱心所好，動不逾矩，性與道奧，厭厭酣飲，樂不辨顏，桓桓振旅，田無遊盤，我德如風，民應如蘭，靡不夙夜，無敢宴安，務農望歲，時或不稔，小心翼翼，恤民以甚，御坐不怡，撤膳振廪，西流垂精，南金仰施，詠言孝思，天經地義，問誰贊事，英彦髦士，問誰翼侍，博物君子，潛明神鑒，從眾屈己，道濟群生，為而不恃，先天弗违，後天降時，萬物熙熙，懷而慕思，顒顒搢紳，不謀同辭，巖巖岱宗，想望翠旗，恭惟大行，功成不居，議寢封禪，心栖冲虛，策告不足，太平有餘，七十二君，方之蔑如，思樂天德，等寿嵩華，如何寢疾，背世登遐，遷幸梓宮，孤我邦家，龟筮既袭，吉日惟良。永指太極，寧神峻陽，群後擗踴，長訣辒辌，聖靈斯顧，豈伊不傷，家無遠邇，邦靡小大，四海供職，同軌畢會，茫茫原野，亭亭素蓋，縞辂解駕，白虎弭旆，龍輴即定，玄闼載扃，如天斯崩，如地斯傾，哀哀庶寮，豭豭自愍，彼蒼者天，胡寧斯忍，聖君不返，我獨旋軫。","sortOrder":25},
  {"id":"s_work_nvlt_13_26","chapterId":"ch_work_nvlt_13","text":"【哀策文】晉張華武帝哀策文曰：感大饗之無虧，哀樽俎之虛設，叩龍輴以長叫，痛靈暉之潛逝，其辭曰：钦惟皇考，體道之真，德侔乾坤，齊曜三辰，應期登禪，协於天人，上虔郊祀，下惠兆民，憲章唐虞，允得其津，搜扬仄陋，故老是賓，百揆時序，盛業日新，恩從雲翔，威猶霆震，江海靜波，岷嶽無尘，四夷率服，莫不來臣，肅慎奉貢，越裳效珍，化此弊俗，歸之至淳，昔在上聖，鹹享百年，哀哀皇考，用不是臻，遘厲弥侵，景命殒顛，舍此昭晢，即彼幽玄，仰瞻靡怙，廓若無天，終製尚俭，率由典度，華幕弗陳，器必陶素，不封不树，所在惟固，貽法來世，是則是慕，大隧既啟，吉日將征，鍾鼓雷震，白虎抗旌，龍螭驤首，良驷悲鳴，倡者振铎，挽夫齊聲，背此崇殿，將適下庭，玄宮窈窕，修夜冥冥，光燈永戢，幽闼長扃，仰訴皇穹，零淚屏營，雲誰能忍，寄之我情，結心墳隴，永凭聖靈。","sortOrder":26},
  {"id":"s_work_nvlt_13_27","chapterId":"ch_work_nvlt_13","text":"【論】晉幹寶晉武革命論曰：帝王之興，必俟天命，苟或代謝，非人事也，文质異時，興建不同，故古之有天下者，柏皇栗陆以前，為而不有，應而不求，執大象也，羲黃世及，以一民也，尧舜內禪，體文德也，漢魏外禪，順大名也，湯武革命，應天人也，高光爭伐，定功業也，各因其運，而天下隨時，隨時之義大矣哉，古者敬其事，則命以始，今帝王受命，而用其終，豈人事乎，其天意乎。","sortOrder":27},
  {"id":"s_work_nvlt_13_28","chapterId":"ch_work_nvlt_13","text":"◇晉元帝","sortOrder":28},
  {"id":"s_work_nvlt_13_29","chapterId":"ch_work_nvlt_13","text":"《晉中興書》曰：中宗元皇帝，讳睿，字景文，世祖鹹寧二年，生於洛陽，初誕有神光之異，一室盡明，所藉藁，如始刈，及長，白豪生日角之左，眼有精曜，唯侍中谯國嵇紹，少而異之，謂其友曰：琅琊王毛骨非常，殆非人臣之相，惠帝幸臨漳，中宗從駕，是時中宗叔父東安王繇，為成都王穎所害，懼禍及，謀出奔，其夜月明，禁衛甚嚴，不能得去，有頃，天暴風雨晦暝，徼者四散，中宗間得脱，及遷镇建鄴，以顧榮為軍司馬，禮接名豪，設官分職，隱恤士庶，百姓歸心焉，初性好酒，王导深以為誡，乃命左右進觴，躬引覆之，自是不复飲也，愍帝為胡賊劉粲所没，中宗素服出次，舉哀三日，於是百僚稱上尊號，帝固讓，百僚又固請，中宗慨然流涕曰：吾本琅琊王，諸賢見逼不已，乃呼私奴命駕，將反國，群臣不敢复逼，乃求依魏晉故事，為晉王，許之，愍帝崩於平陽，百僚更上尊號，是日即皇帝位。","sortOrder":29},
  {"id":"s_work_nvlt_13_30","chapterId":"ch_work_nvlt_13","text":"《晉陽秋》曰：太安中，童謠曰：五馬浮渡江，一馬化為龍，永嘉大亂，王室淪覆，唯琅琊西陽汝南南頓彭城五王獲濟，至是中宗登祚，先是五铎見於晉陵，靈數玄感，若合符契。","sortOrder":30},
  {"id":"s_work_nvlt_13_31","chapterId":"ch_work_nvlt_13","text":"【策文】晉郭璞元皇帝哀策文曰：永惟殿宇之廓寂，悲彝奠之莫歆，感鸞辂之晏駕，哀袞裘之委衿，痛聖躬之遐往，長淪景於太陰，乃作策曰：王之不極，百六作艱，鴞集琼林，鯨躍神淵，懷愍失據，海覆嶽巔，蠢蠢六合，岡不倒懸，靈慶有底，見龍在田，誰其極哉，我後先天，大人承運，重明繼作，撫征淮海，駿命再廓，仁風旁靡，神化潛鑠，處冲思挹，居簡行約，聖敬日邁，玄心逾漠，用物與能，總攬群略，林無滯才，山無遺错，恩靡不懷，化靡不被，茫茫海域，款塞慕義，萬里同尘，岡匪王隸，熙熙遺黎，莫知其寄，括終宇宙，混同天地，曰功永年，曰德慶隆，奈何氛厲，奄集聖躬，大業未恢，皇齡未中，天憯其景，崑頹其崇，豭豭小子，藐藐孤冲，靡天何戴，靡地何凭，恍惚極慕，若存若終，蔑焉無聞，廓焉長寂，聆音靡晞，瞻顏失觌，窮號曷訴，叩心誰告，何悲之哀，何痛之酷，呜呼我皇，逢天之戚，呜呼哀哉，眇然升遐，即安玄室，煌煌火龍，赫赫朱韠，終焉永潛，曷其有出，明訓長絕，小子何述，望阜增欷，臨崩恸栗，哀兼陟方，痛過遏密，靈爽安之，反真复质，永合元漠，終始得一。","sortOrder":31},
  {"id":"s_work_nvlt_13_32","chapterId":"ch_work_nvlt_13","text":"【令】晉元帝答劉琨等令曰：今方嶽牧伯之任，股肱腹心之臣，萬邦之內，九服之外，鹹見翼戴，以隆天威，是用辭不獲已，而居王位，尋覽所陳，弘旨優遠，孤方當匡复帝祚，豈可猥居極位，昔有夏克复，賴靡艾之勋，周宣中興，由申邵之佐，二公镇御幽朔，忠以衛上，建功極難，實凭遠略，夷難雪恥，於是乎在。","sortOrder":32},
  {"id":"s_work_nvlt_13_33","chapterId":"ch_work_nvlt_13","text":"【表】晉劉琨勸進元帝表曰：否泰之運，古今迭有，宗子有明德，曷常不由多難以隆中興，故獫玁殘周，以啟宣王，巨猾竊漢，乃發光武，陛下天授至德，聰明神武，勞謙恭己，卑以自牧，體伯禽經營之誠，行公旦吐握之事，上崇勤王之義，下垂庇民之量，收羅俊乂，任賢以能，綏爰陝東，化流無外，戎狄荒服，請事率職，重譯納貢，不遠萬里，功高德邵，遐邇歸心，况陛下道邁大宗，勋莫與二，且以親以賢，義實兼之，是以琨敢緣天文人事徵祥之應，昧死上事，以奉尊號，原陛下無常心，以群心為心，忘其身，以萬物為公，則宗廟蒸嘗，不替於今，逆虜逋寇，一讨而滅，無負於天下，無愧於七後矣。","sortOrder":33},
  {"id":"s_work_nvlt_13_34","chapterId":"ch_work_nvlt_13","text":"又表曰：臣聞台宿在天，實承辰極，股肱雖卑，同體元首，臣負乘前朝，過充三吏，國之崇替，有與忧喜，臣聞德合兩儀者，固以四海為公，智周萬物者，不以一身為私，舜禹揖讓，以陟帝位，湯武征伐，以濟時難，彼四王者，遘會不同，登受有異，至夫外己存物，忧世遺躬，其致一也，期於愛民治國，應变合道，以為天下利而已矣，况宗廟是陛下之宗廟，百姓是大晉之百姓耶，陛下若忽七廟之重，距天人之心，絕而不繼，困而不拯，則宗廟不歆其禋祀，群生無所措其手足矣，况臣班具臣之列，荷累世之恩，上懷國家之統，俯絕乌鳥之情者哉，昔伍員發怒，手撻平王之墓，灌夫慷慨，身搴吳濞之旗，皆能宣其臣節，摅其私忿，戮尸斬將，存亡岡恨，臣誠無若人之才，實有此人之憤，苟得上凭天威，展其微效，雖陨九泉，猶以明白。","sortOrder":34},
  {"id":"s_work_nvlt_13_35","chapterId":"ch_work_nvlt_13","text":"又表曰：陛下之躬執謙光，允恭克讓，俯從吏議，示總萬機，布曠荡之詔，开自新之路，海隅漸惠，朔南暨聲，有生之倫，鹹被嘉慶，陛下量包宇宙，明侔三辰，靈祇稽應，華戎同戴，加以王室中微，邦基將絕，遺民元元，屬命陛下，陛下以德則無所與讓，言事固所負荷，誠宜遺小禮，存大務，援據圖錄，居正宸極，上副祖宗之心，下一兆庶之望，臣聞必也正名，前聖大之，春秋傳曰：名以出信，名苟不正，則事有不從，信苟不立，則禮義或愆，乃載籍之明誡，开塞之所由也。","sortOrder":35},
  {"id":"s_work_nvlt_13_36","chapterId":"ch_work_nvlt_13","text":"又表曰：臣聞天生蒸民，树之以君，所以對越天地，司牧黎元，聖帝明王，鑒其若此，知天地不可以無饗，故屈其身以奉之，知黎元不可以無主，故不得已而臨之，社稷時難，則戚蕃定其傾，郊廟或替，則宗哲纂其祀，所以弘振遐風，式固萬世，自元康已來，艱禍繁興，永嘉之际，氛厲弥昏，宸極失御，登遐丑裔，國家之危，有若缀旒，天不悔禍，大灾荐臻，國未亡難，寇害尋興，逆胡劉曜，縱逸西都，主上幽劫，复沉虜庭，神器流離，再辱荒逆，臣每覽史籍，觀之前載，厄運之極，古今未有，在食土之毛，含氣之類，莫不叩心絕氣，行號巷哭，况臣荷寵二世，位廁鼎司，承問震惶，精爽飛越，臣聞昏明迭用，否泰相濟，天命無改，歷數有歸，或多難以固邦國，或隱忧以啟聖明，是以齊有無知之禍，而小白為五伯之長，晉有驪姬之難，而重耳以主諸侯，陛下玄德通於神明，聖姿合於兩儀，應命世之期，紹千載之運，符瑞之表，天人有徵，中興之肇，圖讖垂典，自京畿殒丧，九服崩離，陛下撫寧江左，奄有舊吳，柔服以德，伐叛以刑，抗明威以慑不類，杖大順以肅宇內，純化既敷，則率土宅心，義風既畅，則遐方企踵，昔少康之隆，夏訓以為美談，宣王之興，周詩以為休詠，况茂勋格於皇天，清暉光於四海，蒼生顒顒，莫不欣戴，聲教所加，原為臣妾者哉，且宣皇之胤，唯有陛下，亿兆攸歸，曾無與二，天祚大晉，必將有主，主晉祀者，非陛下而誰，是以邇無異言，遠無異望，謳歌者無不吟詠徽猷，獄訟者無不思於聖德，天地之际既交，華裔之情允合，一角之獸，連理之木，以為休徵者，蓋有百數，冠帶之倫，要荒之眾，不謀而同辭者，動以萬計，是以臣等敢考天地之心，因函夏之趣，昧死上尊號，原陛下存舜禹至公之情，狹巢由矯抗之節，以社稷為務，不以小行為先，以黔首為忧，不以克讓為事，上以慰宗廟乃顧之懷，下以釋普天頓首之望，臣聞尊位不可久虛，萬機不可久曠，虛之一日，則尊位以殆，曠之浃辰，則萬機以亂，陛下雖欲逡巡，其若宗廟何，其若百姓何。","sortOrder":36},
  {"id":"s_work_nvlt_13_37","chapterId":"ch_work_nvlt_13","text":"◇晉成帝","sortOrder":37},
  {"id":"s_work_nvlt_13_38","chapterId":"ch_work_nvlt_13","text":"《晉中興書》曰：顯宗成皇帝，讳衍，字世根，肅祖長子也，即位後，蘇峻及祖約，阻兵作逆，詔庾亮卞壸距之，戰於青谿，壸等败績，壸死之，亮奔江州，共陶偘溫峤，率眾下讨峻，臨陣斬之。","sortOrder":38},
  {"id":"s_work_nvlt_13_39","chapterId":"ch_work_nvlt_13","text":"【策文】晉成帝哀策文［闕撰人姓名。］曰：宸極寥廓，聖靈遐之，哀備物之虛在，痛永往之無期，乃命史官，述德寄辭，其辭曰：五德代興，素靈啟曜，離光叠暉，三辰重照，明明我皇，含貞挺妙，玄秀夙達，履德岡违，鳳栖遐邈，神宇凝夷，文明外润，仁簡內綏，舉無遺中，鑒無幽微，韻隆汾陽，道侔垂拱，靜恭清穆，冥功日用，亹亹神軌，固天攸縱，爰在陽九，皇綱中替，奸竖肆逆，牢羅失衛，升降艱難，协應神契，靈祚既保，顯扬天命，雰霧朝晞，兩儀开鏡，訓谘阿衡，虛己納正，九功潛流，七德將表，方振宏羅，稜威電扫，芟荡神衢，一我王道，昊天不弔，降茲大悔，天傾其儀，地覆其載，大業未究，神爽遷背，哀貫三靈，痛流萬代，爰初不豫，大漸在躬，啟手歸全，神氣夷冲，凝哉達識，體正履終，袞龍既袭，玉容斯幽，澄醪虛設，觴爵靡酬，墳牍莫啟，聖跡誰修，冥冥我皇，神焉何遊，撫膺遐叫，迸涕交流，三筮告期，將歸陵墟，陛殒羽翼，庭納龍舆，玉輪動運，錫鸞鳴衢，銘旆徘徊，六骥踟蹰，輕雲荫軌，流風翼車，哀哀同軌，嗺々輓夫，長號永慕，泣涕涟洳，大塊獨運，終歸其始，我後永往，寧神千祀，悠悠上天，豭豭惟己，眇然靡凭，廓焉無恃，目范令儀，徽音在耳。","sortOrder":39},
  {"id":"s_work_nvlt_13_40","chapterId":"ch_work_nvlt_13","text":"◇晉康帝","sortOrder":40},
  {"id":"s_work_nvlt_13_41","chapterId":"ch_work_nvlt_13","text":"《晉中興書》曰：康皇帝，讳嶽，字世同，成皇帝崩，上即位，忧哀不忍言政，一委中書監庾冰。","sortOrder":41},
  {"id":"s_work_nvlt_13_42","chapterId":"ch_work_nvlt_13","text":"【策文】晉康帝哀策文［闕撰人姓名。］曰：感廣厦之空寂，悲俎奠之虛陳，痛皇神之邈遠，哀靈景之長泯，仰瞻宸極，俯凭鸞軒，五情摧裂，號恸煩冤，遂命國史，述德銘勋，事以言顯，功以名存，其辭曰：招拒降靈，篤生我皇，歧嶷妙哲，幼有珪璋，含真發曜，蘭風載芳，厥初肇建，宗國是胤，祗承師友，執心淑慎，徽猷恺悌，金质玉润，固天所啟，應茲靈運，入繼皇祚，龍騰鳳迅，因假任物，惟精委順，穆穆我皇，風流凝廣，聰鑒遐照，思心內朗，應变無方，從善如响，矩儀可慮，法物可象，覆焘群生，靡物不養，如何一旦，神遊靈爽，仰攀擗踴，觸物鹹想，卜吉有期，將即玄冥，太常既建，千乘列庭，皓皓舆服，翩翩素旌，笳箫寥咧，輓夫齊聲，六骥踌躇，萧萧悲鳴，是用增哀，雨泣霑纓，痛貫五內，哀切三情，道隆名貴，德享弥光，灼灼皇猷，終然允臧，垂美兆祀，芳風休扬。","sortOrder":42},
  {"id":"s_work_nvlt_13_43","chapterId":"ch_work_nvlt_13","text":"◇晉穆帝","sortOrder":43},
  {"id":"s_work_nvlt_13_44","chapterId":"ch_work_nvlt_13","text":"《晉中興書》曰：孝宗穆皇帝，讳聃，字彭子，康帝子也，崩時年十九。","sortOrder":44},
  {"id":"s_work_nvlt_13_45","chapterId":"ch_work_nvlt_13","text":"【策文】晉穆帝哀策文［闕撰人姓名。］曰：钦明文思，允恭克讓，忽若布衣，忘其矜尚，體有示無，德充神王，冕旒兩楹，委政元辅，內倚公旦，外仗尚父，鬱哉惟文，赫斯惟武，西廓岷河，北清伊渚，園陵聿修，舊京式叙，方振長慧，風扫天宇，休牛歸馬，卷旗臥鼓，俾我蒸民，击壤容與，昊天不弔，奄背率土，哀同遏密，痛方創鉅，日月不居，神道之幽，三辰吉良，五謀同休，祖載華庭，晏駕崇丘，俯執饋奠，仰攀龍辀，岌岌黼翣，飄飄素斿，感想平昔，人懷崩抽，號聲如震，洒涕成流。","sortOrder":45},
  {"id":"s_work_nvlt_13_46","chapterId":"ch_work_nvlt_13","text":"◇晉簡文帝","sortOrder":46},
  {"id":"s_work_nvlt_13_47","chapterId":"ch_work_nvlt_13","text":"《晉中興書》曰：太宗簡文帝，讳昱，字道方，中宗少子也。","sortOrder":47},
  {"id":"s_work_nvlt_13_48","chapterId":"ch_work_nvlt_13","text":"《晉陽秋》曰：桓溫始以雄盛入辅，系以废立，帝雖登祚，內不自安，初，熒惑入太微，尋废海西公，至是熒惑猶在太微，帝惡之，謂郄超曰：命之修短，大所不計，故無复往日事耶，超雲，大司馬溫，方內固社稷，外布經略，非常之事，臣以百口保之，超假還東，帝謂之曰：致意尊公，家國之事，遂至於此，由吾不能以道匡树，思患豫防，媿叹之深，言何能喻。又誦庾闡詩雲，士痛朝危，臣哀主辱，泣下沾衣，涟如相續。","sortOrder":48},
  {"id":"s_work_nvlt_13_49","chapterId":"ch_work_nvlt_13","text":"《續晉陽秋》曰：帝弱而惠異，中宗深器焉，及長，美風姿，好清言，舉心端詳，器服簡素，與劉惔王蒙等為布衣之遊。","sortOrder":49},
  {"id":"s_work_nvlt_13_50","chapterId":"ch_work_nvlt_13","text":"【策文】晉簡文帝哀策文［闕撰人姓名。］曰：同軌畢至，內外成列，素旗宿懸，辒辌首轍，執祖行於前殿，奉靈舆而遷逝，悲神宇之長违，痛聖儀之幽翳，攀龍輴以孺慕，撫素膺以泣血，爰命史臣，叙述聖德，扬徽音於飛旌，寫哀心於翰墨，乃作策曰：淳曜發暉，皇歷攸應，聖祖啟運，哲王遐承，蒸哉元後，光我中興，天基徙構，朝陽再升，皇矣聖考，合一履中，道心玄玄，文明內融，湛湛神儀，穆穆靈風，望之凝秀，即之深冲，爰在初齡，至性自然，水鏡一世，堂室重玄，愔愔素庭，翳若丘園，遂阿王室，婉跡經纶，時有汙隆，道無屈伸，如彼平流，泯矣其津，大過之時，皇德不競，天人革心，謳歌徒詠，時惟伊霍，辅運以政，钦若昊天，祗此明命，龍飛九五，饗茲萬國，居宗舉契，允恭玄默，綢缪哲辅，虛己仗德，天明方曜，離暉翳朗，玄化誰陶，蒼生曷仰，四運忽其遙邁，日月飄以飛沉，將寧神於玄宇，遷玉辂於中林，背華殿之昭晢，即幽隧之重深，奉神榇以永訣，邈終天而莫尋，神恍惚其若寄，泣橫墜以流襟。","sortOrder":50},
  {"id":"s_work_nvlt_13_51","chapterId":"ch_work_nvlt_13","text":"◇晉孝武帝","sortOrder":51},
  {"id":"s_work_nvlt_13_52","chapterId":"ch_work_nvlt_13","text":"《晉中興書》曰：烈宗孝武皇帝，讳昌明，中宗第三子也。","sortOrder":52},
  {"id":"s_work_nvlt_13_53","chapterId":"ch_work_nvlt_13","text":"【策文】晉王珣孝武帝哀策曰：同軌畢至，百司胥亚，法物夕陳，辒辌夙駕，親執饋奠，長號永夜，懼鼓刻之遄盡，哀良辰之莫借，悲宮宇之寥廓，痛聖儀之幽化，夫至德無名，固理絕稱喟，然祝史陳辭，亦臣子所貴，寄窮情於翰墨，庶遺尘之仿佛，其辭曰：惟皇作極，五德迭胤，康實复夏，武亦隆晉，亹亹太宗，希夷其韻，鏡之者玄，撫之者順，於穆皇考，嗣徽絕軌，前聖後哲，契合一揆，心去其伐，行遺其美，废華任誠，舍筌存旨，惟深通志，群方鹹秩，惟幾成務，能事斯畢，未若我皇，至則不疾，恢恢天網，疏而莫失，居有以虛，宰多以少，簡則可從，易則不扰，信及豚魚，泽被亿兆，湛然司契，坐一八表，園陵既衛，威靈赫赫，子來既構，寢廟弈弈，武曰止戈，戎不極役，文教聿脩，有恥且格，跡有遠邇，感無高深，道之所被，改色革音，皓獸馴苑，素羽栖林，殊柯通理，異蒂同根，方融玄液，陶鑄斯民，雲韶候奏，比屋思淳，積祐莫應，天罰奄臻，太山頹構，洪渎竭津，何殃之甚，何酷之殷，自罹旻凶，二氣代变，霜繁廣除，風回高殿，帷幕空張，肴俎虛荐，極聽無聞，詳视岡見，人神道殊，吉凶有禮，龟筮參謀，埏隧告啟，史臣考吉，警者在陛，攀援忪忪，惟兄及弟，龍舆肅以引邁，前騼紛以抗旒，城闕俨以整列，馳道亘以通脩，感平昔之所幸，豈斯路之复由，輓哀唱以翼衡，驷悲鳴而顧辀，违華宇之晰晰，即永夜之悠悠，奉靈榇而長訣，緬終天而莫收，訴穹蒼以叫踴，洞五內其若抽，傥性命之可贖，甘人百於山丘，茫茫大運，靡始不終，哲王遺世，貴在道融，昭哉我皇，萬代流風，良史式述，德音永隆。","sortOrder":53},
  {"id":"s_work_nvlt_13_54","chapterId":"ch_work_nvlt_13","text":"◇宋武帝","sortOrder":54},
  {"id":"s_work_nvlt_13_55","chapterId":"ch_work_nvlt_13","text":"徐爰《宋書》曰：武皇帝，彭城縣綏興里人，夜生有神光之異，室內盡明，是夕，甘露降於墓树，少嘗遊下邳，遇一沙門於逆旅舍，沙門言及中原多故，因雲江表尋复丧亂，能拯之者，其唯君乎，其意甚切至，初高祖患手創，積年未瘳，沙門因出懷中黃散一裹留之，沙門既去，高祖追而望之，倏忽不見，以散治創，一傅而愈，餘散寶錄之，每被金創，辄用有验，高祖舉目瞻睞，常見二龍在焉，始尚微小，及貴，龍形漸長，光色轉明，左右侍者，亦數見徵異，晉陵人韦藪，少以占相為事，其言多验，嘗相高祖曰：君當位至方伯，久之又曰：君相轉進，貴不可言，唯原富貴無相忘，高祖北征，至洛陽，常有紫雲見於軍上。","sortOrder":55},
  {"id":"s_work_nvlt_13_56","chapterId":"ch_work_nvlt_13","text":"沈約《宋書》曰：帝讳裕，字德舆，小字寄奴，初為冠軍孫［宋書武帝紀孫下有無終二字。］司馬，桓玄篡帝位，遷天子於潯陽，桓修入朝，高祖從至京邑，玄見高祖，語司徒王謐曰：昨見劉裕，風骨不恒，蓋人杰也，上清簡寡欲，嚴整有法度，未嘗视珠玉舆馬之飾，後庭無絲竹之音，寧州嘗獻琥珀枕，光色甚麗，將北征，以琥珀治金創，上大悅，命捣碎，分賦諸將，平關中，得姚興從女，有盛寵，以之废事，謝晦諫，即時遣出，宋台建，有司奏東西堂施局腳床，銀涂釘，上不許，使用直腳，釘用鐵，孝武帝大明中，坏上所居陰室，其處起玉燭殿，與群臣觀之，床頭有土障壁，上掛葛燈籠麻蠅拂，侍中袁顗，盛稱上俭素之德，故能光有天下，克成大業者焉。","sortOrder":56},
  {"id":"s_work_nvlt_13_57","chapterId":"ch_work_nvlt_13","text":"【诔】宋謝靈運武帝诔曰：九有同悲，四海等哀，矧伊下臣，思恋徘徊，敢遵前典，式述聖徽，乃作诔曰：舜潛歷巖，高晦泗渚，龍德而隱，風積乃舉，皇之遁世，屯難方阻，眷此區寰，闵爾淪胥，太元之季，權戚携薄，隆安之初，主相蒙弱，嶽牧糾虔，朝庭紛错，妖橫乘隙，蛟喷鯨躍，既扰奧區，遂斥帝廛，亂離斯瘼，不後不先，寔賴明哲，授手康旃，紀度回薄，餘分成閏，舊晉中微，伪楚籍衅，躡彼潛機，整此英陣，推亡必朽，固存斯振，盧循負险，肆慝遐嶺，殄我江豫，迫我台省，民既搖荡，國將遷鼎，乘騶歸轅，式固皇境，弘危濟险，弭難釋殆，虎騎鶩隰，舟師涨海，傾穴尋窠，窮幽测昧，昔去洛汭，息肩江沚，世更十君，年逾百祀，國絕興复，家成桑梓，荒默莫恤，頹國誰恥，夏典載禹，九道是行，商誥述湯，兼攻是併，勤彼周流，协此經營，杖鉞伐鼓，赫赫明明，乃敕眾師，竟執戎昭，誨以三略，惠以六弢，雲撤周京，席卷秦郊，复禮前塋，雪愧舊朝，既清西關，將旋東道，中憩徐豫，兼應燕趙，業盛曩代，惠侔大造，泽及四海，功格八表，悠悠聲教，綿綿川陆，北獻氈裘，南貢金竹，髽首冠弁，穿匈斂服，寒穴欣日，巢栖玩屋，匪惟遐谭，靈物偕就，孰是人事，自天所祐，甘露芝草，祥雲瑞宿，嘉禾連木，素鳥皓獸，昔之所感，謳頌同音，今之所應，幽顯一心，宋充虞德，晉猶唐钦，曰總八紘，於茲三齡四維开張，九流昭明，敦俭務素，钦賢愛萌，製規作訓，闡校修經，禮樂已甄，雲雨未弘，將陟井陉，薄扫白登，北朔渴望，飛旌衡輣，東岱靈遲，玉牒金縢，天地不仁，蒼生寡福，已荷一遇，弃我何速，梁顛太頹，甘殒以贖，同軌畢至，率土鹹哀，殊方均服，栾栾素縗，洒淚成雨，响叫如雷，史臣考卜，高山开基，貞龟無遠，遷靈有期，嗣皇擗摽，群後崩悲，孰雲不戚，痛百在茲，惟祖之夕，流火始变，秋月未永，飛漏急箭，鳴箫哀噭，金觴虛奠，列駕長隧，發輦華殿，華殿既謝，長隧是幸，双蓋踌蹰，六閒引領，攀援容貌，眷恋俄頃，哀哀百僚，長辭含鯁，奉教百朝，執鞭王始，從履五牧，年歷十祀，天光下濟，谬蒙眷齒，愧微刀筆，頗預遊止，垂幕侍講，接筵餐理，脩曙朗夕，登台泛沼，匪月匪日，無晏無早，如何一旦，緬邈穹昊，徽容未遠，聖靈超然，收淚即路，含戚何言，風霜萧瑟，山海蒼茫，地苦情矜，節速心傷，孰是幽哀，實恋我皇，情思如環，萱蘇豈忘。","sortOrder":57},
  {"id":"s_work_nvlt_13_58","chapterId":"ch_work_nvlt_13","text":"【議】宋顏延之武帝謚議曰：以為聖哲同風，功美殊稱，蓋出乎道者無方，故刑於物者不一，伏惟道塞人神，信通期運，愛敬所禀，因心則遠，英粹之照，正性自天，體苞潛躍，慮周卷舒，龍德在陰，雖艱貞而不悶，因時而惕，故有來其必亨，在晉之季，皇涂荐阻，攙搶幹紀，璇璣失馭，天鑒靈武，民屬聖明，不假十室之資，不籍百乘之賦，首義馳風，一鼓靜亂，涤除太階，消殒薄蚀，斯亮登庸之基，經纶之始者也，內難雖弭，外圖未辑，河華海岱，負固相望，荆濮燕亳，侯服交侵，眷言帝畿，思康王路，戎不稱駕，遺珉即序，斥候之所末羁，亭徼之所不譯，莫不飾誠請罪，款塞來賓，故能洒扫中嶽，致廟九山，神道會昌，寶命既集，損之而益，後身愈先，既而儀形帝載，揖讓天歷，改玉乎文祖，班瑞於神宗，貫革寢機，文武搢笏，故辰居兩楹，坐一八表，國訓成均之學，家沾撫辜之仁，大美配天，必終之以俭德，道固萬葉，猶申之以話言，允所謂教思無窮，树之長世，取高上代，顧邈前王矣。","sortOrder":58},
  {"id":"s_work_nvlt_13_59","chapterId":"ch_work_nvlt_13","text":"◇宋孝武帝","sortOrder":59},
  {"id":"s_work_nvlt_13_60","chapterId":"ch_work_nvlt_13","text":"沈約《宋書》曰：帝讳駿，字休龍，小字道民，文帝第三子也，元凶殺逆，舉義兵，克定京邑，乃踐帝位，年三十五，崩，在位八年。","sortOrder":60},
  {"id":"s_work_nvlt_13_61","chapterId":"ch_work_nvlt_13","text":"【策文】宋謝莊孝武帝哀策文曰：應門洞望，馳道南除，菆涂已撤，鬱鬯將虛，哀子嗣皇帝，擗摽池綍，周遑旌軫，攀七緯之崩淪，恸三靈之徂盡，百神慕而行雲沉，萬國哀而素霜霣，衣冠緬邈，弓劍不追，敢緝謳頌，仿佛希夷，其辭曰：枢電皇根，月瑤國緒，胤裔丹陵，蝉聯華渚，二後在天，大行纂武，克睿克聖，重規袭矩，昭昭金式，明明玉溫，望雲其遠，就日其尊，雨零露湛，冬暖春暄，聲芳納麓，道昭賓門，上德無稱，至功不器，怊怅四始，優遊六位，缀响蘭深，緝言琼秘，悠哉梁踐，眇焉汾肆，敬業开宇，離經作翰，鸿起荆河，鸞遊楚漢，泗濱霑明，江區承奐，陝左清郊，棠陰虛馆，地維不紐，乾綱弛機，羲庭薄蚀，紫路流飛，泣血泒涘，顧瞻川沂，孝貫枢極，義震寰围，誓鉞皇郊，詔師牧甸，七景締華，五雲卷煽，雪怨園邑，扫恥瀛縣，啟聖宸居，集寶龍見，王室多故，國步方蹇，淮濟裂冠，江荆毀冕，東楚亂常，西華汨典，動筭揮圖，爰戡爰剪，浃宙斯澄，綿區鹹鏡，修風晓逸，德星夕映，溽露飛甘，舒雲結慶，禎被動植，信泊［疑當作洎。］翔泳，缺禮克宣，墜章必構，方堂饗極，圓流肆胄，南耸郊宮，北清靈囿，瑤軒春藉，翠華冬狩，經緯窮文，克定盡武，鄗上呈祥，介丘載佇，在盈念冗，成功弗處，榮鏡中世，舄弈前古，睿業初遠，鸿化方亭，丹雲承日，素景媵星，玉幾去袭，缀衣在庭，辭重陽之昭昭，降大夜之冥冥，氣貿炎涼，史詔龟筮，文物空嚴，鑾和虛衛，動蜃辂之逶遲，顧壁羽之容裔，出國門，分天地，向幽途，異身世，龍旌鬱而青槐遠，驚葭亂而白楊翳，觀初霜之变條，聽秋風之下蒂，桥山縆雲，穀林虧日，輦道結寒，松庭盡密，芝蓋迫軨，上驤眷辔，萬宇肅其北〈車炎〉，靈阿阒其深隘，南維有時傾，離光不常鏡，騰英聲與茂實，方流華於舞詠。","sortOrder":61},
  {"id":"s_work_nvlt_13_62","chapterId":"ch_work_nvlt_13","text":"《藝文類聚》　唐·欧陽詢","sortOrder":62},
  {"id":"s_work_nvlt_14_1","chapterId":"ch_work_nvlt_14","text":"卷十四帝王部四","sortOrder":1},
  {"id":"s_work_nvlt_14_2","chapterId":"ch_work_nvlt_14","text":"○齊高帝齊武帝齊明帝梁武帝梁元帝北齊文宣帝陳武帝陳文帝陳宣帝","sortOrder":2},
  {"id":"s_work_nvlt_14_3","chapterId":"ch_work_nvlt_14","text":"◇齊高帝","sortOrder":3},
  {"id":"s_work_nvlt_14_4","chapterId":"ch_work_nvlt_14","text":"《齊書》曰：高帝讳道成，字紹伯，蘭陵人，受禪於宋，在位四年。","sortOrder":4},
  {"id":"s_work_nvlt_14_5","chapterId":"ch_work_nvlt_14","text":"【哀策文】齊王俭高帝哀策文曰：降階執禮，泣血纏心，感客台之罢御，哀恭馆之不臨，仰神儀而邈絕，视區物而凄陰，俾茲良史，敬修舊則，敢圖鸿規，式扬至德，其辭曰：靈源遙裔，肇惟商丘，聖功寧夏，賢識歸周，我皇踵武，超冠前猷，英風允迪，德音孔修，月准敷仁，日精表孝，則地均和，體天合照，外弘三至，內隆七教，水祚將傾，乾維晦象，韦弁長袭，鼓磬屬响，聲化已淪，政刑遂往，國圖靡緝，民規載爽，康世以德，拨亂資武，威以雷霆，润以風雨，六術允昭，四義克舉，自東徂北，遐方即序，功被河濟，化隆江漢，帝謩仰式，王維佇幹，改步藩屏，來登翼贊，綢缪總章，因循陽馆，昔在保衡，君违斯正，爰茲博陆，亦鑒靈命，放昏以忠，登明資敬，義煥金石，功昭舞詠，蠢爾荆漢，悖亂人經，謀連枢禁，兵接神坰，御宄以德，御宄以刑，獻捷宗寢，飲至王庭，政教雲行，徽猷天造，山鑒紫璇，苑茂朱草，玉檢騰暉，金繩荐寶，天鏡既穆，地維既肅，遐邇一體，表里禔福，乃眷斯民，昧旦杼軸，興文偃武，缵禹舊服，所尚惟簡，所保惟賢，居尊弥約，無善不延，膠庠載緝，風軌克宣，上洞清儀，下達玄泉，聽覽閒日，應物餘景，怡慮以文，栖心以靜，鸿章晨暎，徽言夕永，跡庇區服，情深箕穎，萬宇餐和，百神受職，梁甫欣儀，雲亭望式，辅德伊何，奄捐民極，嵩嶽長傾，宸暉斯昃，機照惟寂，達鑒靡傷，慎終敬始，知微知章，立言垂范，玉润金相，瞻仰遺式，哀結流霜，旋玉轪之曒鏡，動雲旗之逶迤，振哀笳於八極，响清跸於鹹池，顧應掖而稍遠，视機衡而長離，風遲遲而懷暮，日憯憯其若垂，感衣冠於乔嶽，追弓劍之在斯，悼丁年之薄祐，訴窮心於兩儀。","sortOrder":5},
  {"id":"s_work_nvlt_14_6","chapterId":"ch_work_nvlt_14","text":"【表】梁江淹齊高帝讓禪表曰：陛下遠视唐虞永揖之典，近摹漢魏高謝之禮，既鑒金水昏明之數。又协雲雷興替之徵，若乃與能之交，禪錫之會，豈伊虛薄，所可遵擬，昔傅巖佐商，祑終上公，磻溪翼周，名極列伯，臣才非半古，功愧逮聖，獄訟不往，謳歌寧歸，河乏馬圖之寶，天無乘龍之錫，伏原陛下遺舜禹之心，俾臣守巢由之節，則道曜日月，泽浸飛泳。","sortOrder":6},
  {"id":"s_work_nvlt_14_7","chapterId":"ch_work_nvlt_14","text":"◇齊武帝","sortOrder":7},
  {"id":"s_work_nvlt_14_8","chapterId":"ch_work_nvlt_14","text":"《齊書》曰：武帝讳績，字宣遠，在位十一年。","sortOrder":8},
  {"id":"s_work_nvlt_14_9","chapterId":"ch_work_nvlt_14","text":"【議】梁沈約齊武帝謚議曰：臣聞天德平分，而四時之名或異，聖功一揆，而皇王之稱不同，蓋跡因隨事，名由義立，尧臣禹佐，鹹率茲典，伏惟盡寂窮微，含神獨照，德茂始裳之主，道冠初耜之君，含精靈於五緯，駕貞明於三象，初九勿用，英氣凌雲，負揭日月，抑扬霄漢，龍姿鳳采，煥若麗天，登庸在试，盛績雲舉，雖屈景潢汙，降情尺木，而拯世濟民，浚發懷抱，昔成湯百家，仁被比屋，文王十里，化先寡妻，前聖後賢，重規沓矩，震雄圖於九江，播靈威於夏汭，旌旆未麾，鯨鲵自殒，弗勞羌僰之長，無待六事之人，義等伐謀，功高善陣，建有國之符，成定鼎之業，會朝清明，事資於牧野，受命作周，非止於西伯，视瞻寢門，孝德光備，守器宗祧，元良載遠，嗣大寶以君百辟，敷景化以致隆平，守在四夷，威行海內，囹圄寂寞，禮讓交興，八柄馭下，九官鹹事，臨朝凝默，尊嚴若神，風行日烜，無思不畅，至仁與造化爭流，靈威與雷霆齊軌，上貫蒼昊，下洞深泉，春無凄風，夏無苦雨，時若岡愆，多稔如積，三革不累，五刃不砥，庠塾大啟，儒雅雲集，訓閱得宜，蒐狩有序，丹徼青丘之野，跂踵反戶之民，浮深駕阻，回首革面，北夷畏力，獻琛內款，不藉終軍之使，無假絕漠之威，嘉祥霧合，秘瑞泉涌，史不輟文，簡無虛日，方當垂七曜之旗，駕八龍之乘，望禮中嶽，肆觐群後，造化不仁，穆卜愆應，慕切遺弓，哀同遏密，晦朔不居，殯宮將啟，勤茲大名，宜盡徽極。","sortOrder":9},
  {"id":"s_work_nvlt_14_10","chapterId":"ch_work_nvlt_14","text":"◇齊明帝","sortOrder":10},
  {"id":"s_work_nvlt_14_11","chapterId":"ch_work_nvlt_14","text":"《齊書》曰：明帝讳鸞，字景栖，在位五年。","sortOrder":11},
  {"id":"s_work_nvlt_14_12","chapterId":"ch_work_nvlt_14","text":"【哀策】梁沈約齊明帝哀策文曰：龍菆既撤，備物已陳，殯宮無夜，夕燎終晨，號環辌幄，攀摽應路，容衛弗改，軒槛如故，望東川而不追，仰昊天而自訴，列聖同軌，謚法树聲，爰詔掌牍，式播遺英，其辭曰：五曜在天，遞作民主，赫矣帝高，蒸哉嗣武，多難固業，隱忧啟聖，時惟我皇，功符受命，爰始濡足，坐運機深，鵬逝風舉，龍動雲陰，之郢南溯，即豫西臨，體茲大德，懷此小心，賓於四門，四門穆穆，納於百揆，百揆肅肅，德浸堇荼，仁被比屋，何遠何邇，無思不服，嗣君丧道，不式典謨，神器業業，事等瞻乌，民懷奧主，後來其蘇，皇天眷命，授以箓圖，臨朝凝睟，昧旦丕顯，斟酌前王，擇其令典，不言斯應，不行斯踐，路台靡營，離宮弗宴，眷言膠塾，弘啟上庠，軌儀四代，祖述三王，德暉內動，英華外扬，禮行樽俎，義及幽荒，仰庶天德，降年永久，北極齊光，南山獻寿，沧溟奄竭，嵩岱皆朽，沴非昊穹，惟餘之咎，攀龍詎幾，大隧方玄，厭世崇陛，即宮下泉，殯階已遽，素幕高褰，端闈洞啟，蜃紼徐前，背朱闕以南轉，乘翠龍而東度，經原野之荒涼，屬西成之雲暮，伐金鼓以清道，扬悲笳而啟路，極厚地而不追，終蒼天而永慕，蒼梧晦遠，蜰徽不泯，紀事寂寞，龟書可循，哲王违世，克播遺尘，猗欤萬古，暉光日新。","sortOrder":12},
  {"id":"s_work_nvlt_14_13","chapterId":"ch_work_nvlt_14","text":"【謚策】齊謝朓明皇帝謚策文曰：仰惟早弃萬邦，聖列方遠，式遵帝世，俾鬯鸿猷，鹹以為無名以化，則言系莫宣其道，有來斯應，則影响庶圖其功，所以永言配命，寄心宗極，光昭令德，允树風聲，伏惟合信四時，齊光日月，創保大於登庸，通機神於受命，因時以惕，藉九萬而輕舉，天保既定，運四海而高臨，及开物成務，重維國紐，風行草偃，化往如神，左賢右戚，內樂外禮，辑五材以教民，申三驅而在宥，用能盛德殷荐，美善斯畢，皇矣之業既孚，蒸哉之道鹹備，景化方遠，厭世在天，龟筮告期，遠日無改，仰則前王，俯詢百辟，累德稱睿，允極鸿名。","sortOrder":13},
  {"id":"s_work_nvlt_14_14","chapterId":"ch_work_nvlt_14","text":"【議】梁沈約齊明帝謚議曰：臣聞君德靡二，辟王之名不一，聖功無爽，尧禹之稱或殊，兼以拯世寧亂，致平未必同道，崇墠增祧，嘉號不可相袭，伏惟自天誕睿，英聖在躬，皇矣之符夙著，蒸哉之謠早集，賓門納揆，天平地成，自南自北，無思不韙，任屬負圖，导扬末命，值嗣主狂凶，人倫道盡，宗社阽危，瞻乌靡讬，國難立長，亂極治刑，四海樂推，三靈以眷，東向而讓天下，功高代入，流涕而膺寶位，如就重負，日昃劬勞，躬親庶事，撫辜納隍之念，義同於罪己，振民厚下之情無废於終食，聰明神武，逖聽邇聞，萬目備張，紘綱靡漏，御辔不迷，寧藉聽於襄野，大川可濟，不待備於舟楫，峥嵘之下，泽靡不懷，寥廓之上，明無不燭，包以宇宙，润以風雨，霜露所交，人跡所至，百姓仰之而不知其始，萬物用之而岡識其終，上庠废業，忽焉已久，三載弗為，淪弛將及，臨朝引領，思隆雅訓，貴遊胥萃，俊造成群，方將驅世反本，既仁且寿，告成東嶽，高宴汾陽，造化不仁，厭世雲及，放勋之慕不追，負乡之思空遠，殯宮將撤，輴軫難留，英聲茂實，於是乎在。","sortOrder":14},
  {"id":"s_work_nvlt_14_15","chapterId":"ch_work_nvlt_14","text":"梁任昉齊明帝謚議曰：以為窮神之跡，無繼於成名，教思所宗，言歸於有稱，是以則天為大，義盡於翼善，武功受命，理貫於斯文，伏惟功高五讓，道冠三極，愛敬始於扬名，孝饗終乎嚴配，寥廓大度，誕君人之符，閨庭小節，應軌物之訓，歷试允諧，納揆時序，貽厥之寄，義均負圖，榱棟惟新，壓焉將及，於是承製宣德，定策公卿，登嗣後於西鍾，反獨夫於侯服，既而主幼時艱，仍離屯蹇，應當璧之祥，註息肩之原，立德以長，紹开中興，擬度天行，取則乾健，日昃罢朝，幽枉必達，官曹寂寞，圄犴空虛，虎門肆義，大足协律，巖廊有搢紳之談，乡塾無橫議之士，既富而教，弘此孝治，遂使家無荡子，野有栖畝，寘天下於掌握，覽八荒於戶牖，寵微金穴之家，恩絕椒風之馆，天應民和，祥符總暨，故能上变雲物，下漏深泉，若乃青丘丹陵之國，黃銀紫玉之瑞，幽符遠萃，詢德報功，方將馳道日觀，清宮鳴泽，為而不恃，高揖成功，百川所以朝宗，參辰於焉取正，豈所謂中衢均奠，懸衡共軌者欤。","sortOrder":15},
  {"id":"s_work_nvlt_14_16","chapterId":"ch_work_nvlt_14","text":"【表】齊謝朓為百官勸進齊明帝表曰：臣聞時乘在御，必待先天之業，神化為皇，乃葉應期之運。况复湯孫有緒，纂尧惟德。舊邦佇新，复禹歸祉。大齊之權舆寶歷，孕育前古，昭假四海，克酬三靈。而嗣命疾威，蕃鄙叛換，委裘御宇，彝鼎如忽。陛下文思體道，徇齊作聖。剪應龍於冀州，戮長蛇於沮水。榮光之瑞昭回，延喜之寶润色。天睠爰發，人謀鹹贊。伏原陛下，仰答靈祇，弘宣景命，誕受多方，奄宅萬國。","sortOrder":16},
  {"id":"s_work_nvlt_14_17","chapterId":"ch_work_nvlt_14","text":"【啟】梁沈約贺齊明帝登祚啟曰：竊惟皇源浚遠，帝寶連暉，基深慶厚，道貫萬葉，而鬱林凶德早树，行悖人經，逖聽之所未書，宗廟之殆如缀，百靈耸動，九服回遑，結後來之望，思庇民之主，日月以冀，遐邇翘心，伏惟陛下，大聖在躬，君德夙表，龍章日采，煥若麗天，納麓賓門，道風遐被，睿化神行，無思不洽，獄訟允歸，天人戴仰，屈飛龍之眇辔，紆汾陽之遠情，運尧心以臨亿兆，敷舜烈以膺寶命，雖中宗之興殷道，宣後之隆漢德，異世同符，千載一揆，刑措之業方遠，隆平之基在焉，率土含欣，懷生戴賴，况臣早蒙覆润，夙荷恩靈，踴躍外畿，心不勝慶，謹緝民和，式流星泽，涂歌里抃，戴懷凫藻。","sortOrder":17},
  {"id":"s_work_nvlt_14_18","chapterId":"ch_work_nvlt_14","text":"◇梁武帝","sortOrder":18},
  {"id":"s_work_nvlt_14_19","chapterId":"ch_work_nvlt_14","text":"《梁書》曰：武帝讳衍，字叔達，蘭陵人，受禪於齊，在位四十九年。","sortOrder":19},
  {"id":"s_work_nvlt_14_20","chapterId":"ch_work_nvlt_14","text":"【議】梁元帝高祖武皇帝謚議曰：臣聞翼善傳聖曰尧，仁聖盛明曰舜，受禪成功曰禹，除虐去殘曰湯，謚者行之跡，號者功之表，雖賤不诔貴，卑不诔尊，而彰乎名者，盛德之嘉號也，被於物者，治定之實錄也，斯所以聲明煥乎鍾石，昭晰備於絃管者焉，伏惟天縱钦明，惟睿作聖，功超三五，聲逾七十，仰之弥高，就之弥遠，載潛載躍，乃武乃文，先是木運告終，群後改屬，乾維岡構，地紐如崩，祧祀阽危，公卿旰食，九牧有淪胥之悲，八表興橫流之叹，乃凝威黑水，表瑞丹陵，雲合景從，表里禔福，受終文祖，允恭克讓，知黔首不可以無歸，蒼生不可以無主，降汾陽之遠志，不得已而臨之，於是類帝禋宗，革命創製，禘郊式展，殷荐斯絜，臨茲大寶，化與和氣俱宣，扇此王風，政與秋霜併肅，言懸日月，功格區宇，不以紫宸為貴，不以黃屋為尊，政謐刑措，民殷國阜，虹旌式卷，堡燧載清，胥象相因，環楛無曠，天衢亭泰，王道升平，南海候風，東溟奉赆，膏露凝枝，慶雲觸石，山开蒼璧，地出玄珪，驃騎把鉞，則休屠款塞，太尉抗旌，則名王蹶角，聲教所漸，浃靈蛇之都，威令所行，通燭龍之外，开庠建序，布濩於成均，正俗移風，氛氲於司樂，虛納十亂，引谅直之規，廣辟四門，弘招賢之德，青衿知击壤之性，黃發恣鼓腹之歡，加以鑽味微言，研精至道，文終所牧之典，史倚所讀之書，無輟萬機，日且千遍，馳鬱鬱之聲，表乾乾之德，允所謂皇哉君哉，日用而不知者矣，方旦告成岱嶽，鏤升中之玉簡，昭事梁甫，秘社首之金繩，而文王明夷，事侔往册，黃帝桥山，痛深前典，萬有淪傷，三辰掩曜，人祇軫慕，山海含悲，恸切陟方，哀深遏密，煩冤荼毒，貫切心髓，風树不靜，陟岵何期，思所以钦若九功，仰稽七德。","sortOrder":20},
  {"id":"s_work_nvlt_14_21","chapterId":"ch_work_nvlt_14","text":"【敕】梁沈約武帝踐祚後與諸州郡敕曰：钦惟遂古，爰及近代，雖禪代異時，而成功一揆，豈惟靜民寧亂，實由符運總集，故能啟業垂統，光宅區夏，齊氏遘茲昏诐，斯亡奄及，民命蠢蠢，倒懸非喻，朕大懼四海舟覆，二象雲傾，亿兆與崑岗併燎，搢紳與蘊崇共日，永言凄悼，發憤經營，推鋒投袂，電击風扫，藉上天之靈，因熊羆之用，德未半古，功侔前烈，齊氏既钦若虞夏，高揖萬邦，兼以冥符先著，樂推攸在，幽顯宅心，辭不獲命，猥以虛寡，君臨萬國，川壑之懷，寤寐盈慮，方欲昧旦丕顯，日昃忘勞，思與賢能，康濟世道，卿擁旄萬里，共治是寄，當求民瘼，留念獄市，威斷以御強猾，仁惠以撫貧孤，使遠近幽深，鹹得其所，方虛位钦能，懸爵佇效，勿令漢代玺書，獨行於自古，晉世班條，靡用於茲日，想加克勉，副其侧席。","sortOrder":21},
  {"id":"s_work_nvlt_14_22","chapterId":"ch_work_nvlt_14","text":"【令】梁任昉齊宣德皇後臨朝答梁王令曰：承固茲謙揖，未膺大典，敬复雅旨，良有怃然，夫至寂難原，言象所絕，教思有律，感通斯在，所以異人者神明，同人者用舍，王誕茲上睿，對越天行，德冠二儀，化周群動，生民以來，一人而已，但達節弘道，每濡跡於中庸，神照惟幾，不抑心於鑽仰，范宣既讓，其下取則，况聖圖睿范，歌思是歸，廉約雖弘，慶賞遂替，誠賢者悅義，長難進之風，不肖者矜功，沮竭力之效，勸沮之間，所差已遠，王何得不暫紆雅尚，允答天人，使朕夜艾以安，早朝有預，今遣率茲百辟，申荐誠款，萬致一涂，煩言可略。","sortOrder":22},
  {"id":"s_work_nvlt_14_23","chapterId":"ch_work_nvlt_14","text":"又敦勸梁王令曰：夫功在不賞，故庸勋之典蓋闕，施侔造物，則謝德之涂已冥，要不得不強為之名，使铨宰有寄，王實天生德，齊聖廣淵，重構參辰，而九星仰止，不易日月，而二儀貞觀，在昔晦明，隱鱗戢翼，博通群籍，而讓齒乎一卷之師，劍氣凌雲，而屈跡於萬夫之下，辯析天口，而似不能言，文擅彫龍，而成辄削藁，爰在弱冠，首膺弓旌，客遊梁朝，聲華藉甚，隆昌季年，勤王始著，建武惟新，締構斯在，功隆賞薄，嘉庸莫畴，一馬之田，介山之志愈厲，六百之祑，大树之號斯存，及擁旄司部，代馬不敢南牧，推轂樊邓，胡尘罕嘗夕起，惟彼狡童，窮凶極虐，衣冠泯絕，禮樂崩丧，既而鞠旅誓眾，言謀王室，白羽一麾，黃馬底定，甲既鱗下，車亦瓦裂，致天之屆，拱揖群後，丰功厚利，無得而稱，是以祥光總至，休氣四塞，五老遊河，飛星入昴，元功茂勋，若斯之盛，而地狹乎四履，势卑乎九伯，帝有惡焉，輶軒萃止，今遣率茲百辟，人致其誠，庶匪席之旨，不遠而复。","sortOrder":23},
  {"id":"s_work_nvlt_14_24","chapterId":"ch_work_nvlt_14","text":"重敦勸梁王令曰：朕聞疋夫好仁，義在磨踵，君子行道，達斯兼濟，未有盡器窮神，蘊徽章乎天植，高奠中樽，睹傾罍而弗拯，惟王德冠往初，功無與二，四時等契，兩曜齊明，擬度天行，取則乾健，而運距艱季，道極百王，援義而起，一戎大定，羅山革草，岡不率從，用使商庭產{艹悉}，周闕树梓，傾宮既散，鹿台靡蓄，盛德大業，巍巍若此，日者亭歧之號，爰發帝言，殊物備禮，率由寡昧，雖复雲竿載路，清跸啟行，昭德報功，未臻其極，而高揖天休，遠存克讓，俾予未亡，興慚日昃，今遣率茲百辟，人致誠請，庶有感睿心，霈然降志。","sortOrder":24},
  {"id":"s_work_nvlt_14_25","chapterId":"ch_work_nvlt_14","text":"【箋】梁任昉為百辟勸進，梁王箋曰：伏承嘉命佇策，明公逡巡盛禮，斯實謙尊之旨，未窮遠大之致，何者，嗣君弃常，自絕宗社，國命民生，剪為仇讎，折棟崩榱，壓焉自及，卿士懷脯斮之痛，黔首懼比屋之誅，明公亮格天之功，拯水火之切，稱踵日月，重缀參辰，反龟玉於涂泥，濟斯民於坑岸，使夫疋婦童兒，羞言伊呂，乡校里塾，恥談五霸，位卑乎阿衡，地狹於曲阜，明公宜祗奉天人，允膺大禮，無使後予之歌，同彼胥怨，兼濟之仁，翻為獨善。又箋曰：近以朝命蘊崇，冒奏丹誠，奉披還令，未蒙虛受，搢紳顒顒，深所未達，蓋聞受金於府，通人之弘致，高蹈海隅，疋夫之小節，是以履乘石而周公不以為疑，增玉璜而太公不以為讓，况世哲繼軌，先德在民，經纶草昧，叹深微管，加以朱方之役，荆河是依，班師振旅，大造王室，雖复累跡救宋，重眡存楚，居今觀古，曾何足雲，而惑甚盜鍾，功疑不賞，皇天後土，不勝其酷，是以玉馬駿奔，表微子之去，金版出地，告龍逢之怨，明公據鞍辄哭，厲三軍之志，獨居掩涕，激義士之心，故能使海若登祇，磬圖效祉，山戎孤竹，束馬景從，伐罪弔民，一匡靖亂，匪叨天功，實勤濡足，且明公本自諸生，取樂名教，道風素論，坐镇雅俗，不習孫吳，構茲神武，驅盡誅之氓，濟必封之俗，龟玉不毀，誰之功欤，獨為君子，將使伊周何地，某等不達通变，實有愚誠，不任悾款，棘心重謁，伏原特膺典策，式副民望。","sortOrder":25},
  {"id":"s_work_nvlt_14_26","chapterId":"ch_work_nvlt_14","text":"【序】梁沈約武帝集序曰：文思安安，钦明所以光宅，日月光華，南風所以興詠，日角之主，出自諸生，銳顶之君，少明古學，漢高宋武，雖闕章句，歌大風以還沛，好清談於暮年，夫成天地之大功，膺樂推之寶運，未或不文武兼資，能事斯畢者也，我皇誕縱自天，生知在御，清明內發，疏通外舉，爰始貴遊，篤志經術，究淹中之雅旨，盡曲台之奧義，莫不因流極源，披條振藻，若前疑往滯，舊學罕通，而超然直詣，妙拔終古，善發談端，精於持論，置壘難逾，推鋒莫擬，有同成誦，無假含毫，興絕節於高唱，振清辭於蘭畹，至於春風秋月，送別望歸，皇王高宴，心期促賞，莫不超挺睿興，濬發神衷，及登庸歷试，辭翰繁蔚，箋記風動，表議雲飛，彫虫小藝，無累大道，懷君人之大德，有事君之小心，為下奉上，刑於辭旨，雖密奏忠規，遺必削，而國謨藩政，存者猶多，逮乎俯應歸運，仰修乾錄，載筆握簡，各有司存，如纶之旨，時或染翰，暨於設虡靈囿，恺樂在鎬，鹿鳴四牡，皇華棠棣之歌，伐木采薇，出車杕杜之宴，皆詠志摛藻，廣命群臣，上與日月爭光，下與鍾石比韻，事同觀海，義等窥天，睹之而不测，遊之而不知者矣，竊唯左史記言，右史記事，君舉必書，無論大小，况乎感而後思，思而後積，積而後滿，滿而後言，若斯而已哉，謹因事立名，隨源編次。","sortOrder":26},
  {"id":"s_work_nvlt_14_27","chapterId":"ch_work_nvlt_14","text":"◇梁元帝","sortOrder":27},
  {"id":"s_work_nvlt_14_28","chapterId":"ch_work_nvlt_14","text":"《梁書》曰：元帝讳繹，字世誠，武帝第七子也，嗣位三年。","sortOrder":28},
  {"id":"s_work_nvlt_14_29","chapterId":"ch_work_nvlt_14","text":"【表】陳沈蜅為群臣勸進梁元帝初表曰：蠢爾羯胡，遂凭天邑，閶阖受白登之辱，象魏致尧城之疑，臣聞丧君有君，春秋之茂典，以德以長，先王之通訓，少康則牧眾撫職，祀夏所以配天，平王則居正東遷，宗周所以卜世，漢光以能補不道，故景歷重昌，中宗以不违群議，故江東可立，天其祚梁，必將有主，軒轅得姓，存者二人，高祖五王，代實居長，功高九有，道濟生民，非奉聖明，誰嗣下武，日月貞明，太陽不可以闕照，天地貞觀，乾道不可以久愓，寶器存乎至重，介石慎於易差，黔首豈可以少選無君，宗祏豈可以一日無主。","sortOrder":29},
  {"id":"s_work_nvlt_14_30","chapterId":"ch_work_nvlt_14","text":"又第二表曰：紫宸曠位，赤縣無主，百靈耸動，萬國回遑，雖醒醉相扶，同歸景亳，或謳且誦，總赴唐郊，陛下沈首讠勞然，讓德不嗣，臣聞星回日薄，击雷鞭電者之謂天，嶽立川流，吐霧蒸雲者之謂地，包天地之混成，洞陰陽之不测，而以财成萬物者，其在聖人乎，故雲，天地之大德曰生，聖人之大寶曰位，黃屋廟堂之下，大非獲己所安，明鏡四衢之樽，蓋由應物取訓，陛下稽古文思，英雄特達，比以周旦，則文王之子，方之放勋，則帝挚之季，千年旦暮，可不在斯，庭闕湮亡，鍾鼎淪覆，嗣膺景業，非陛下而誰，豈可使赤眉更立盆子，隗嚣讬置高廟，陛下方复從容高讓，用執謙尊，展其矯行伪書，誣罔正朔，見機而作，斷可識矣，不疑何卜，無待蓍龟，日者公卿失馭，禍纏霄極，獯羯凭凌，奸臣互起，師戎伐穎，無處不然，勸乎誅晉，侧足皆爾，宗社不墜，繄在聖明，今也何時，而申帝啟之避，凶危若此，方陳太伯之辭，國有具臣，誰敢奉詔。","sortOrder":30},
  {"id":"s_work_nvlt_14_31","chapterId":"ch_work_nvlt_14","text":"又第三表曰：日者百司嶽牧，仰祈宸鑒，以錫珪之功，既歸有道，當璧之禮，允屬聖明，而優詔謙冲，窅然凝邈，謳歌載馳，是用翘首，楚人固執，燻丹穴以求君，周民樂歸，越歧山而事主，漢王不即位，無以貴功臣，光武止萧王，豈謂紹宗廟，陛下英威茂略，雄圖武筭，指捴則丹浦不戰，顧眄則阪泉自荡，地維絕而重紐，天柱傾而更植，縱陛下拂衣而遊廣成，登弇山而去東土，群臣安得仰訴，萬物何所歸仁，况郊祀配天，罍篚禮曠，斋宮清廟，匏竹不陳，豈可久稽眾議，有曠彝典。","sortOrder":31},
  {"id":"s_work_nvlt_14_32","chapterId":"ch_work_nvlt_14","text":"陳徐陵勸進梁元帝表曰：臣聞封唐有聖，還承帝喾之家，居代維賢，終纂高皇之祚，至如金行重作，源出東莞，炎運猶昌，枝分南頓，莫不因時多難，俱繼神宗者也，陛下握符執鉞，將在御天，玉勝珠衡，先章元後，神祇所命，非惟太室之祥，圖書斯歸，何止尧門之瑞，星躔東井，時破崤潼，雷震南陽，初平尋邑，宗王啟霸，非勞武德之侯，清跸無虞，何事長安之邸，正應扬龍旂以饗帝，御鳳扆以承天，歷數在躬，畴與為讓，豈可逡巡固讓，方求石戶之農，高謝君臨，徒引箕山之客，未知上德之不德，唯見聖人之不仁。","sortOrder":32},
  {"id":"s_work_nvlt_14_33","chapterId":"ch_work_nvlt_14","text":"◇北齊文宣帝","sortOrder":33},
  {"id":"s_work_nvlt_14_34","chapterId":"ch_work_nvlt_14","text":"《北齊書》曰：文宣帝讳洋，字子進，受禪於後魏，在位五年。","sortOrder":34},
  {"id":"s_work_nvlt_14_35","chapterId":"ch_work_nvlt_14","text":"【哀策】北齊邢子才文宣帝哀策文曰：皋路啟扉，輴菆弛殯，八校案部，六卿且引，攀蜃辂而雨泣，仰穹蒼而撫心，悲風發而地駭，愁雲興而景沉，哲王垂范，有訓有則，式奉話言，光敷令德，其辭曰：四象更運，九天代名，通三以王，得一為貞，是應玄德，實啟蒼精，風後之陣，師尚之兵，三奇六合，七变五成，授柯推轂，禀律龚行，野無完陣，邑少堅城，經營四海，劬勞百姓，芝蓋夕臨，羽旄晨暎，地不掩瑞，天無愛寶，既丹其雀。又朱其草，莫黑已素，莫赤自皓，百獸斯蹈，五靈載扰，甘露瀼瀼，青龍矯矯，武功已畅，文教未窮，方偃烽候，銷戟藏弓，齊光日月，比祚華嵩，而氛祲日下，星闇虛中，奄捐朝市，長弃華戎，道宣末命，義闡餘風，六繂已散，九旗方卷，見容衛之虛歸，知平生之日遠，同乘雲而永逝，異騎龍之更反，清笳奏兮野風急，金鼓震兮日光晚，千官悲而雨註，萬國哀而露泫，萬事同盡，百慮俱收，劍舄永去，衣冠自遊，音儀已謝，神教空留，知英聲與至德，當無絕兮千秋。","sortOrder":35},
  {"id":"s_work_nvlt_14_36","chapterId":"ch_work_nvlt_14","text":"【議】北齊邢子才文宣帝謚議曰：伏惟聖德光遠，神猷弘大，初自登庸，民譽所集，把尺持刀，成務斯在，百揆載清，四門唯穆，及天眷既屬，人謀所歸，鳥獸遷情，士女革面，敬順天人，拱揖群後，處無上之尊，居域中之大，禮盛樂修，時和歲稔，海內有截，天下泰然，猶忧勞亿兆，經營四國，同虞舜之巡省，若軒轅之靡寧，威武紛紜，神功四畅，怨西以東，化南自北，臨瀚海以浴兵，登天山而绁馬，左萦右拂，夷歌成章，方朝百神於太華，受萬國於稽嶺，升中增封，高拱垂衣，而天丧黎庶，奄捐四海，考妣之慕，實被含生，稱天作诔，抑唯恒數，故以名追實，盡物未臻其美，屈道從製，一日可以成名。","sortOrder":36},
  {"id":"s_work_nvlt_14_37","chapterId":"ch_work_nvlt_14","text":"◇陳武帝","sortOrder":37},
  {"id":"s_work_nvlt_14_38","chapterId":"ch_work_nvlt_14","text":"《陳書》曰：武帝讳霸先，字興國，吳興長城人，受禪於梁，在位三年。","sortOrder":38},
  {"id":"s_work_nvlt_14_39","chapterId":"ch_work_nvlt_14","text":"【哀策】陳沈蜅武帝哀策文曰：望三靈而摽目，蹐九地而崩心，哭仍幾之將撤，恸祖鬯之虛斟，黃屋祲而白日掩，紫極沴而浮雲陰，其辭曰：悠悠妫水，鬱鬱姚墟，惟帝之系，在唐作虞，正卿之後，握此靈符，雕雲布族，祥星結枢，負茲天鏡，來拾遺珠，爰初發跡，斬蛇鞠旅，大定番禺，載戡海渚，承衅而運，席卷中流，王室如毀，乃合諸侯，負鈇誓眾，釋位同謀，俱登涿鹿，實斷蚩尤，道濟一匡，功歸四履，爰總百官，訓於天子，傥來有運，事非獲已，翠龟負字，赤雀衔書，謳歌適夏，禮樂遷虞，負扆正位，升壇受圖，二儀协序，五緯同符，門歌麟趾，室詠騶虞，奉常定日，太卜蠲時，升中備物，方告雍熙，天甘玉露，地秀金芝，休禎未答，靈貺徒欺，吏求穆卜，詔絕良医，羲躔失御，天街褫跸，夏采升榮，宮車晏出，洞閨移凶，充庭罢吉，閉窅窅之窮燈，去昭昭之遊日，歸大暮之不暘，降幽宮而長畢，巫鹹筮吉，容成戒期，文衛如在，葆铎相悲，去畢陌而東顧，望桥山而路遲，臣攀龍而尚在，魂過沛而何之，侍低昂之靈纛，奉寂寂之空帷，銅爵没於脩松，平陵隱於深柏，節{世鼓}鼓之哀音，燎爟火於通夕，薤露落而暮田寒，玄霜凝而垄草白，銘功德於旗常，被徽音於鍾石，回天儀於清廟，祔祖考而來格，播茂實與英聲，鬱氛氲於宗祏。","sortOrder":39},
  {"id":"s_work_nvlt_14_40","chapterId":"ch_work_nvlt_14","text":"【表】陳沈蜅為百官勸進陳武帝表曰：臣聞春榮秋落，四時所以迭代，金行水流，五德所以互序，昔陶唐告終，有虞氏作，漢魏禪讓，晉宋以之登庸，天有非常之功，有非常之賞，能利天下者，受天下之利，陛下造化之功，日用之德，褰裳去之，物誰仰訴，頃五星夜聚，八風通吹，丰露呈甘，卿雲舒族，白狼遠至，素雉朝飛，天意顯然，靈貺可睹。","sortOrder":40},
  {"id":"s_work_nvlt_14_41","chapterId":"ch_work_nvlt_14","text":"◇陳文帝","sortOrder":41},
  {"id":"s_work_nvlt_14_42","chapterId":"ch_work_nvlt_14","text":"《陳書》曰：文帝讳蒨，字子華，嗣位七年。","sortOrder":42},
  {"id":"s_work_nvlt_14_43","chapterId":"ch_work_nvlt_14","text":"【哀策】陳徐陵文帝哀策文曰：容車晓駕，幄殿晨張，旌帷具列，綍翿成行，擗蜃辂於丹陛，攀龍帷於紫庭，趨過窮於屏闈，拜恸感於明靈，東京飛其瑞露，北陆霣其祥星，乃詔雲台之史，稽采鹹池之曲，葉大雅於鳴金，同藏書於群玉，其辭曰：若水傳帝，薰風御民，重光所集，世載於陳，赫矣高祖，悠哉上旻，蝉聯寶胄，暉煥郊禋，我皇誕聖，膺此家慶，道王衢樽，神凝懸鏡，洛書天表，河紀靈命，納揆馳芳，賓門流詠，稽陰克伐，震野勤王，亳道增構，豳風會昌，言瞻少昊，實杖高陽，駕彼軨轕，清宮未央，歡覃兆庶，德洎遐荒，穆齊高寢，上膳長樂，肅肅承顏，哀哀廌酌，悼園恭俭，章陵謙約，大寶崇名，無聞改作，纂武升歷，遺愛寔繁，三湘九泒，弥氣雲昬，力折天柱，才傾地門，甘泉夜照，細柳朝屯。穀魅山鬼，橫流塞源，赫赫英謩，赳赳雄斷，遍行天讨，無遺神算，鬱扫江淮，長驅巴漢，九夷百越，雷隨風涣，北頓崑耶，西戡伊靬，荷負皇極，劬勞庶機，勤民聽政，昃食宵衣，服貴綈皂，風移阃闈，唐山罢奏，濮水韜徽，訪采狂狷，搜易攵仄微，世感中孚，民維大畜，外戶無閉，高垣奚筑，降情儒雅，凝懷庠塾，御庑為歡，臨雍弥肅，禮兼三代，樂備九成，天資武德，地照文明，墨履斯在，懞巾自清，連珠合璧，曜爽流精，獸舞時豫，禽歌頌平，帝載維遠，王靈維大，候雨占風，荒中海外，憬彼鞮譯，鹹承冠帶，是曰君臨，斯為交泰，白環已赆，玄珪克禎，東河佇揖，北狄思征，鉞斧將或，璁珩未鳴，星淫去楚，日沴悲荆，亿兆何亹，穹旻遽傾，大禹胼胝，重華腒腊，仰惟勞務，同斯违怿，發夢無徵，昭祈奚益，聽茂陵之鍾鼓，抱乔陽之劍舄，詎仿佛於宸儀，終纏綿於號擗，三占以吉，四海同奔，列赗天宇，崩號帝閽，千門啟於閶阖，萬乘警於靈辒，槐風悲於輦道，松雨思於郊原，鑾旂動而虛跸，宿衛靜而空尊，畢陌平夷，流山蟠固，紀無遷市，唐有通树，經白社之脩涂，回青門之廣路，思沛邑以東臨，懷周京以西顧，機神不测，性道難稱，充窮靡寄，孺慕奚冯，惟封雲之與禪肅，玉牒之與金繩，扬英聲而永久，共日月而俱升。","sortOrder":43},
  {"id":"s_work_nvlt_14_44","chapterId":"ch_work_nvlt_14","text":"◇陳宣帝","sortOrder":44},
  {"id":"s_work_nvlt_14_45","chapterId":"ch_work_nvlt_14","text":"《陳書》曰：宣帝讳頊，字紹世，在位十四年。","sortOrder":45},
  {"id":"s_work_nvlt_14_46","chapterId":"ch_work_nvlt_14","text":"【哀策】隨江總陳宣帝哀策文曰：望蜃綍而攀摽，拜龍菆而恸絕，变五統而凄涼，回三辰而惨切，感川嶽而地維傾，號穹蒼而天柱折，千秋茂德，萬世鸿名，爰詔掌禮，式序英聲，其辭曰：妫水枢宿，姚墟大虹，謳歌承歷，揖讓受終，重規帝緒，踵武王風，名山紀变，清廟傳功，我後丕承，思弘祖業，莅政恭己，臨朝凝默，煥烂九功，葳蕤七德，憲章昭著，威靈允塞，爰茲發跡，天步艱難，連華滕衛，比譽應韓，羽儀戚右，軒冕朝端，祈膺當璧，繇顯大橫，延喜授玉，告善飛旌，神器有奉，性道無名，詩頌唐年，樂舞姬日，仁聲汪濊，武義洋溢，理訟總街，凝情衢室，巡望如禮，幽祇鹹祑，疆垂叛換，關徼虔劉，治兵丹浦，獲丑青丘，屠釣且拔，管库方搜，如龍駕鼓，獻雉焚裘，天必呈祥，地寧愛寶，神禽奇獸，嘉穀靈草，屈軼抽階，飛黃伏皂，綺雲舒慶，珠星照老，廣敷丘素，弘啟膠庠，書林吐馥，文囿含锵，南洽侯衛，北畅遐荒，殷羅自解，周圄無傷，金英掩色，玉床弗豫，天驷摧鑣，王良失御，鑄鼎奚益，缀衣何處，漫漫幽夜，冥冥上仙，長违拜日，天意祈年，寧神卜兆，晏駕回天，銅驎感泣，銀海埋田，出德陽之廣殿，動繁笳之哀啭，渡洛水之浮桥，望偃師之近縣，背紫陌而未遠，隱黃山而不見，铎啟挽而依依，馬嘶風而恋恋，平原欲晦，落照將垂，鳳蓋飄而水暗，鸞跸耸而山危，曳蛇旗之舒卷，間翠野之參差，鳥哀哀而驚曙，松瑟瑟而吟枝，異故乡之絲竹，非舊宅之埙篪，扫秋葉而無盡，荐春櫻而原知，北邙已謝，西陵何有，遠宿蒼梧，便乖仁寿，聲合韶濩，道宣戶牖，共瀛海而恒流，併嵩華而莫朽。","sortOrder":46},
  {"id":"s_work_nvlt_14_47","chapterId":"ch_work_nvlt_14","text":"《藝文類聚》　唐·欧陽詢","sortOrder":47},
  {"id":"s_work_nvlt_15_1","chapterId":"ch_work_nvlt_15","text":"卷十五後妃部","sortOrder":1},
  {"id":"s_work_nvlt_15_2","chapterId":"ch_work_nvlt_15","text":"○後妃","sortOrder":2},
  {"id":"s_work_nvlt_15_3","chapterId":"ch_work_nvlt_15","text":"◇後妃","sortOrder":3},
  {"id":"s_work_nvlt_15_4","chapterId":"ch_work_nvlt_15","text":"《白虎通》曰：天子之配謂之後，後者何也，明海內之小君也。","sortOrder":4},
  {"id":"s_work_nvlt_15_5","chapterId":"ch_work_nvlt_15","text":"《禮記》曰：古者天子立後，六宮三夫人九嫔二十七世婦八十一御妻，以聽天下之內治，以明章婦道，故天下內和而家理，婦順不脩，陰事不得，謫見於天，月為之食，月食，則後素服而修六宮之職，荡天下之陰事。","sortOrder":5},
  {"id":"s_work_nvlt_15_6","chapterId":"ch_work_nvlt_15","text":"又曰：舜葬蒼梧，蓋三妃未之從也，［舜納三妃，生九子，娥皇無子，女英生商均，益(禮記檀弓疏作癸。)比生二女，宵明，燭光，舜不告而娶，不立正妃，故唯納三妃焉。］","sortOrder":6},
  {"id":"s_work_nvlt_15_7","chapterId":"ch_work_nvlt_15","text":"《周官》曰：仲春，詔後師［周禮內宰作帥，下同。］內外命婦，始蠶於北郊，以為祭服，上春，詔王後帥六宮之人，生种而獻之於王。","sortOrder":7},
  {"id":"s_work_nvlt_15_8","chapterId":"ch_work_nvlt_15","text":"《毛詩》曰：關雎，後妃之德也，風之始也，所以風天下而正夫婦也。","sortOrder":8},
  {"id":"s_work_nvlt_15_9","chapterId":"ch_work_nvlt_15","text":"又曰：葛覃，後妃之本也，後妃在父母家，則志在於女功之事，躬俭節用，服澣濯之衣，尊敬師傅，則可以歸安父母，化天下以婦道也。","sortOrder":9},
  {"id":"s_work_nvlt_15_10","chapterId":"ch_work_nvlt_15","text":"又，卷耳，後妃之志也。又當辅佐君子，求賢審官，知臣下之勤勞，內有進賢之志，而無险诐私謁之心，朝夕思念，至於忧勤者也。","sortOrder":10},
  {"id":"s_work_nvlt_15_11","chapterId":"ch_work_nvlt_15","text":"又，樛木，後妃逮下也，言能逮下而無疾妒之心焉，［木下曲曰樛，木枝下垂。故葛藟得而蔓之，諭後，妃能下逮眾妾，使得其序，眾妾上附事之也。］","sortOrder":11},
  {"id":"s_work_nvlt_15_12","chapterId":"ch_work_nvlt_15","text":"又，螽斯，後妃子孫眾多也，言若螽斯不妒忌，則子孫眾多也，［凡物有陰陽欲者，無不妒忌，唯螽斯不妒，各得大(明本作天，詩鄭箋作受。)氣而生子。］","sortOrder":12},
  {"id":"s_work_nvlt_15_13","chapterId":"ch_work_nvlt_15","text":"又曰：兔罝，後妃之化也，關雎之化行，則莫不好德，賢人眾多也。","sortOrder":13},
  {"id":"s_work_nvlt_15_14","chapterId":"ch_work_nvlt_15","text":"又曰：芣苡，後妃之美也，天下和平，則婦人樂有子矣，《尚書》曰：釐降二女於妫汭，嫔於虞，［嫔，嫁也。］","sortOrder":14},
  {"id":"s_work_nvlt_15_15","chapterId":"ch_work_nvlt_15","text":"尚書大傳，古者後夫人將侍，君前，息燭，至於房中，釋朝服，袭燕服，然後入御於君，雞鳴，太師奏雞鳴於陛，夫人鳴佩玉於房中，告去也，然後應門击柝，告辟也。","sortOrder":15},
  {"id":"s_work_nvlt_15_16","chapterId":"ch_work_nvlt_15","text":"《史記》曰：自古受命帝王，及繼體守文之君，非獨內德茂也，蓋亦有外戚助焉。故易基乾坤，詩首關雎，書叙釐降，春秋譏不親迎，夫妻之际，人道之大倫。","sortOrder":16},
  {"id":"s_work_nvlt_15_17","chapterId":"ch_work_nvlt_15","text":"《漢書》曰：漢興，因秦之稱號帝母皇太後，祖母稱太皇太後，正適稱皇後，妾稱夫人。又有美人良人八子七子之號，至武帝，製婕妤娙娥容華充容各有爵位，而元帝加昭儀之號，凡十四等。","sortOrder":17},
  {"id":"s_work_nvlt_15_18","chapterId":"ch_work_nvlt_15","text":"又曰：黃帝妃方雷氏，生玄嚣，為青陽，妃累祖，生昌意，妃彤魚氏，生夷鼓，妃嫫母，生蒼林。","sortOrder":18},
  {"id":"s_work_nvlt_15_19","chapterId":"ch_work_nvlt_15","text":"應劭《漢官儀》曰：皇後稱椒房，取其實蔓延盈升，以椒涂室，取溫暖，除惡氣也，猶天子朱泥殿上曰丹墀。","sortOrder":19},
  {"id":"s_work_nvlt_15_20","chapterId":"ch_work_nvlt_15","text":"《漢舊儀》曰：皇後婕妤乘輦，餘皆以茵，四人舆以行，皇後玉玺，文與帝同，皇後春桑，皆衣青，手采桑，以繅三盆茧，示群臣妾從，春桑生而皇後親桑，於苑中蠶室，養蠶千箔以上，群臣妾從桑還，獻茧於馆。","sortOrder":20},
  {"id":"s_work_nvlt_15_21","chapterId":"ch_work_nvlt_15","text":"又曰：皇帝賜後黃金萬斤。","sortOrder":21},
  {"id":"s_work_nvlt_15_22","chapterId":"ch_work_nvlt_15","text":"又曰：皇後食三十縣，曰湯沐邑。","sortOrder":22},
  {"id":"s_work_nvlt_15_23","chapterId":"ch_work_nvlt_15","text":"五經要義曰：古者後夫人，必有女史彤管之法，後妃群妾，以禮御於君所，女史書其環以進退之，生子月辰，則以金環退之，當御者，著於左手，既御，著於右手，左手陽也，以當就男，故著左手，右手陰也，御而复故。","sortOrder":23},
  {"id":"s_work_nvlt_15_24","chapterId":"ch_work_nvlt_15","text":"《世本》曰：帝喾卜其四妃之子，皆有天下，元妃有邰氏之女，曰薑嫄，生後稷，次妃有娀氏之女，曰簡狄，生契，次妃陳酆氏慶都，生帝尧，次妃娵訾氏，生帝挚。","sortOrder":24},
  {"id":"s_work_nvlt_15_25","chapterId":"ch_work_nvlt_15","text":"《論語》：武王曰：予有亂臣十人，孔子曰：才難，不其然乎，有婦人焉，九人而已，婦人文母也，［五字當是註文。］","sortOrder":25},
  {"id":"s_work_nvlt_15_26","chapterId":"ch_work_nvlt_15","text":"《列女傳》曰：黃帝妃嫫母，於四妃之班居下，貌甚丑而最賢，心每自退。","sortOrder":26},
  {"id":"s_work_nvlt_15_27","chapterId":"ch_work_nvlt_15","text":"又曰：啟母涂山之女者，夏禹之妃，涂山女也，曰女娇，禹取四日而去治水，啟既生，呱呱而泣，禹三過其門，不入子之，涂山獨明教訓，啟化其德，卒致令名，禹為天子，啟嗣而立，能繼禹之道。","sortOrder":27},
  {"id":"s_work_nvlt_15_28","chapterId":"ch_work_nvlt_15","text":"又曰：湯妃有莘之女也，德高而名，［後漢書一百一十崔琦傳註引作明。］訓正後宮，嫔御有序，伊尹為之媵臣，佐湯致王。","sortOrder":28},
  {"id":"s_work_nvlt_15_29","chapterId":"ch_work_nvlt_15","text":"又曰：太薑者，太王之妃，有台氏之女也，賢而有色，生太伯仲雍季歷，化导三子，皆成賢德，太王有事，必谘謀焉，詩曰：爰及薑女，聿來胥宇，此之謂也。","sortOrder":29},
  {"id":"s_work_nvlt_15_30","chapterId":"ch_work_nvlt_15","text":"又曰：太任者，王季之妃，挚任之女也，端一誠莊，唯德之行，及其有身也，目不视惡色，耳不聽惡聲，口不出放言，溲於豕牢，而生文王，文王生而明聖，太任教以一，而知其百，卒為周宗，君子謂太任為能胎教。","sortOrder":30},
  {"id":"s_work_nvlt_15_31","chapterId":"ch_work_nvlt_15","text":"又曰：太姒者，文王之妃，莘姒之女也，號曰文母，亦思媚太薑，太任旦夕勤勞，以進婦道，文王治外，文母治內，生十子，太姒教誨十子，自少及長，常以正道押持之，卒成武王周公之德。","sortOrder":31},
  {"id":"s_work_nvlt_15_32","chapterId":"ch_work_nvlt_15","text":"《帝王世紀》曰：武王妃太公之女，曰邑薑，修教於內，生太子誦。","sortOrder":32},
  {"id":"s_work_nvlt_15_33","chapterId":"ch_work_nvlt_15","text":"琐語曰：周宣王夜臥而晏起，後夫人不出於房，薑後既出，乃脱簪珥，待罪於永巷，使其傅母通言於宣王曰：妾之淫心見矣，至使君王失禮而晏起，以見君王之樂色而忘德也，亂之興，從婢子起，敢請罪，王曰：寡人不德，寔自生過，非夫人之罪也，遂复薑後而勤於政事，早朝晏退，卒成中興之名。","sortOrder":33},
  {"id":"s_work_nvlt_15_34","chapterId":"ch_work_nvlt_15","text":"《續漢書》曰：明德皇後馬氏，伏波將軍馬援之女也，後年七歲，幹治家事，敕製僮御，出入計校，一以貫之，年十三，以選入太子宮，接侍同列而承至尊，先人後己，發於至誠，由是見寵，是時後宮未有任育者，常言繼嗣當以時立，荐達左右，惟恐不及，身衣大帛，御者禿裙不緣，諸王親家朝請望，見後裙極粗疏，以為綺，就视乃笑，後曰：此繒染色好，故用之耳，老人知者，無不叹息，性不喜出入遊觀。又不好音樂，上時幸苑囿離宮，以故希從，誦易經，習詩論春秋，略記大義，後志在克己辅上，不以私家幹朝庭，兄為虎贲中郎將，兩弟黃門郎，訖永平世不遷。","sortOrder":34},
  {"id":"s_work_nvlt_15_35","chapterId":"ch_work_nvlt_15","text":"【詩】晉成公綏詩曰：天地不獨立，造化由陰陽，乾坤垂覆載，日月耀重光，治國先家道，立教起閨房，二妃濟有虞，三母隆周王，涂山興大禹，有莘佐成湯，齊晉霸諸侯，皆賴姬與薑，關雎思賢妃，此言安可忘。","sortOrder":35},
  {"id":"s_work_nvlt_15_36","chapterId":"ch_work_nvlt_15","text":"又曰：殷湯令妃，有莘之女，仁教內修，度義以處，清謐後宮，九嫔有序，伊尹為媵臣，遂作元辅。","sortOrder":36},
  {"id":"s_work_nvlt_15_37","chapterId":"ch_work_nvlt_15","text":"【頌】賢明頌曰：於鑠薑後，光配周宣，非義不動，非禮不言，晏起早朝，永巷告愆，王用勤政，萬國以虔。","sortOrder":37},
  {"id":"s_work_nvlt_15_38","chapterId":"ch_work_nvlt_15","text":"又晉劉柔妻王氏薑嫄頌曰：英英薑嫄，寔德之純，肇承靈瑞，武敏是遵，誕育歧嶷，毗贊皇纶，播殖之訓，萬葉攸循。","sortOrder":38},
  {"id":"s_work_nvlt_15_39","chapterId":"ch_work_nvlt_15","text":"又啟母涂山頌曰：涂山靜居，玄朗悟機，大禹至公，過門不歸，明此道訓，孩胤是綏，仁哲以成，永系天暉。","sortOrder":39},
  {"id":"s_work_nvlt_15_40","chapterId":"ch_work_nvlt_15","text":"魏韦誕皇後親蠶頌曰：於時明庶扇物，鳥帑昏正，躬耕帝藉，邁德班令，嘉柔桑之肇敷，思郊廟之至敬，命皇後以親蠶，俾躬桑於外坰，考時日於巫鹹，詔太卜以獻禎，御坤德之大辂，翳翠葆以扬旌，爾乃皇英參乘，涂山奉舆，總薑任於後陳，載樊衛於貳車，千乘隱其雷動，萬騎粲以星敷，啟前路於三官，命蚩尤而清衢，遊青虬於左角，步素螭於右隅，登崇壇而正位，觌休氣於朝陽，步雕輦而下降。手柔條於公桑，嫔妾肅以莅事，職蠶植而承筐，供副袆之六服，昭孝敬於蒸嘗，盛華禮於中宇，神化馳於八方，乃延群妾，宴賜於前，降至貴以逮下，布恺悌之渥恩，禮儀備序，巾車回轅，班中黃之禁财，散束帛之戋戋，神泽霈以雨施，洪惠播於無原，同硕慶於生民，發三靈之永歡，苞繁祜於萬國，卷福釐以言旋，美休祚於亿載，豈百世之曾玄。","sortOrder":40},
  {"id":"s_work_nvlt_15_41","chapterId":"ch_work_nvlt_15","text":"晉左九嫔武帝納皇後頌曰：峨峨華山，峻極太清，巨靈导流，河渎是經，惟渎之神，惟嶽之靈，鍾於扬族，載育盛明，我後穆穆，應期挺生，含聰體喆，歧嶷夙成，如蘭之茂，如玉之瑩，越在幼冲，休有令名，飛聲八極，翕習紫庭，超任邈姒，比德皇英，京室是嘉，備禮致聘，令月吉辰，百僚奉迎，登位太微，明德日盛，群黎欣戴，函夏同慶，翼翼聖皇，睿哲孔純，愍茲狂戾，闡惠播仁，蠲衅涤秽，與時惟新，霈然洪赦，恩詔遐震，後之踐祚，囹圄虛陳，萬國齊歡，六合同欣，坤神抃舞，天人載悅，興瑞降祥，表精日月，和氣煙煴，三光朗烈，既獲嘉時，尋播甘雪，玄雲掩霭，靈液霏霏，既储既積，待陽而晞，長享丰年，福祿永綏。","sortOrder":41},
  {"id":"s_work_nvlt_15_42","chapterId":"ch_work_nvlt_15","text":"【贊】曹植薑嫄簡狄贊曰：喾卜四妃，子皆為王，帝挚早崩，尧承天綱，玄鳥大跡，殷周美祥，稷契既生，功顯虞唐。","sortOrder":42},
  {"id":"s_work_nvlt_15_43","chapterId":"ch_work_nvlt_15","text":"又禹妻贊曰：禹娶涂山，土功是急，聞啟之生，過門不入，女娇達義，明勋是執，成長聖嗣，天祿以袭。","sortOrder":43},
  {"id":"s_work_nvlt_15_44","chapterId":"ch_work_nvlt_15","text":"晉傅玄班婕妤畫贊曰：斌斌婕妤，履正修文，進辭同輦，以禮匡君，納侍顯德，谠對解紛，退身避害，志邈浮雲。","sortOrder":44},
  {"id":"s_work_nvlt_15_45","chapterId":"ch_work_nvlt_15","text":"又明德馬皇後贊曰：明德馬後，執貞履素，光崇六行，動遵禮度，作後作母，帝谘厥謀，國賴內訓，家應顯祚。","sortOrder":45},
  {"id":"s_work_nvlt_15_46","chapterId":"ch_work_nvlt_15","text":"晉左九嫔虞舜二妃贊曰：妙矣二妃，體靈應符，奉嫔於妫，光有此虞，沅湘示教，靈德永敷。","sortOrder":46},
  {"id":"s_work_nvlt_15_47","chapterId":"ch_work_nvlt_15","text":"又周宣王薑後贊曰：昭昭宣王，克复前製，亹亹薑後，乃激乃厲，執心至公，以恢明世。","sortOrder":47},
  {"id":"s_work_nvlt_15_48","chapterId":"ch_work_nvlt_15","text":"又納楊後贊曰：清和协極，二儀降靈，啟茲楊族，仁哲誕生，徽音內發，有馥其聲，玄符表運，作合聖明，文定厥祥，考卜惟貞，良辰納幣，三光朗清，元公執挚，嘉禮告成，卿士庶僚，烂其充庭，赫赫華宗，弈世載榮，謙光其尊，在滿戒盈，受茲介福，垂祚亿齡。","sortOrder":48},
  {"id":"s_work_nvlt_15_49","chapterId":"ch_work_nvlt_15","text":"晉庾闡二妃像贊曰：二妃玄達，含靈體妙，协德坤元，配虞齊耀，明兩既麗，重光作照，有邈其微，神風遐劭。","sortOrder":49},
  {"id":"s_work_nvlt_15_50","chapterId":"ch_work_nvlt_15","text":"【箴】後漢皇甫規女師箴曰：觀象製教，肇經乾坤，家有王義，室有嚴君，各有定位，陰陽是分，昔在軒轅，陶化正刑，刑於壸闈，以臨百官，煌煌後妃，玄紞是閒，穆穆夫人，爰采絜蘩，師禮莫违，而神岡時怨，關雎首化，萬國承流，實有淑女，允作好逑，唐媛興妫，文武盛周，德音不回，弘濟大繇，咨爾庶妃，鑾路斯邁，戰戰兢兢，厲省鞶帶，漸進不形，变起無外，行難著而易丧，事易失而難退，動若順流，應如發機，奉上惟敬，撫下唯慈，怨豈在明，患生不思。","sortOrder":50},
  {"id":"s_work_nvlt_15_51","chapterId":"ch_work_nvlt_15","text":"後漢傅幹皇後箴曰：煌煌四星，著天垂曜，赫赫後妃，是則是效，舜納二女，對扬茂教，正位於內，顽嚣輟恭，辛亂妲己，共則情悅，牝雞亂晨，殷祀用絕，孝成宽柔，縱弛紀綱，王擅朝權，趙专椒房，巨猾是緣，竊弄神器，故禍不出所憎，常出所愛，是以在昔明後，日新其化，匪唯訓外，亦訓於內，晉張華女史箴曰：茫茫造化，兩儀始分，散氣流形，既陶既甄，在帝庖羲，肇經天人，爰始夫婦，以及君臣，家道以正，而王猷有倫，婦德尚柔，含章貞一，婉娩淑慎，正位居室，樊姬感莊，不食鮮禽，衛女矯桓，耳忌和音，志厲義高，而二主易心，玄熊攀槛，冯媛趍進，夫豈無畏，知死不吝，班女有辭，割歡同輦，夫豈無懷，防微慮遠，人鹹知飾其容，莫知飾其性，性之不飾，或愆禮正，出其言善，千里應之，苟违斯義，同衾以疑，懽不可以渎，寵不可以专，专實生慢，愛極則遷，致盈必損，理有固然。","sortOrder":51},
  {"id":"s_work_nvlt_15_52","chapterId":"ch_work_nvlt_15","text":"晉裴頠女史箴曰：膏不厭鮮，水不厭清，玉不厭絜，蘭不厭馨，爾形信直，影亦不曲，爾聲信清，响亦不濁，绿衣雖多，無貴於色，邪径雖利，無尚於直，春華雖美，期於秋實，冰璧雖泽，期於見日，浴者振衣，沐者彈冠，人知正服，莫知行端，服美動目，行美動神，天道祐順，常與吉人。","sortOrder":52},
  {"id":"s_work_nvlt_15_53","chapterId":"ch_work_nvlt_15","text":"【诔】漢楊雄皇後诔曰：沙麓之靈，太陰之精，天生聖姿，豫有祥禎，作合於漢，配元生成，孝順皇姑，聖敬齊莊，內則純備，後烈丕光，肇初配元，天命是將，志在黎元，是勞是勤，寅賓出日，東祑陽穀，鳴鳩拂羽，勝降桑木，蠶於茧馆，躬執筐曲，帥道群妾，鹹修蠶族，分茧理絲，女工是敕，遐邇蒙祉，中外提福，自京逮海，靡不仰德，去此昭昭，就彼冥冥，忽兮不見，超兮西征，既作下宮，不复故庭。","sortOrder":53},
  {"id":"s_work_nvlt_15_54","chapterId":"ch_work_nvlt_15","text":"後漢崔瑗窦貴人诔曰：若夫貴人，天地之所留神，造化之所殷{勤心}，華光曜乎日月，才志出乎浮雲，然猶退讓，未嘗专寵，樂慶雲之普覆，悼時雨之不廣，忧國念主，不敢怠遑，呜呼哀哉，惟以永傷，重曰：積善之家福慶長，修身以寿道之常，聖人之言義不虛，修身獲報效莫疏，令問不忘身猶存，貴人雖没遺德尊，著於金石垂後崑。","sortOrder":54},
  {"id":"s_work_nvlt_15_55","chapterId":"ch_work_nvlt_15","text":"曹植卞太後诔曰：率土喷薄，三光改度，陵頹穀踴，五行互错，皇室萧條，羽檄四布，百姓歔欷，婴兒號慕，若丧考妣，天下縞素，聖者知命，殉道寶名，義之攸在，亦弃厥生，敢扬後德，表之旐旌，光垂岡極，以慰我情，乃作诔曰：我皇之生，坤靈是辅，作合於魏，亦光聖武，篤生帝文，紹虞之緒，龍飛紫宸，奄有九土，詳惟聖善，歧嶷秀出，德配薑嫄，不忝先哲，玄覽萬機，兼才備藝，汎納容眾，含垢藏疾，仰奉諸姑，降接儔列，陰處陽觀，潛明內察，及踐大位，母養萬國，溫溫其仁，不替明德，悼彼邊氓，末遑宴息，恒勞庶事，兢兢翼翼，親桑蠶馆，為天下式，樊姬霸楚，書載其庸，武王有亂，孔叹其功，我後齊聖克畅丹聰，不出房闼，心照萬邦，年逾耳順，乾乾匪倦，珠玉不玩，躬御綈練，日昃忘飢，臨樂勿宴去奢即俭，曠世作顯，慎終如始，蹈和履貞，恭事神祇，昭奉百靈，跼天蹐地，祇畏神明，敬微慎獨，執禮幽冥，虔肅宗廟，蠲荐三牲，降福無疆，祝雲其誠，宜享斯祐，蒙祉自天，何圖凶咎，不勉斯年，嘗祷盡禮，有篤無痊，豈命有終，神食其言，遺孤在疚，承讳東藩，擗踴郊畛，洒淚中原，追號皇妣，弃我何遷，昔垂顧复，今何不然，空宮寥廓，棟宇無煙，巡省階涂，仿佛櫺軒，仰瞻帷幄，俯察幾筵，物不毀故，而人不存，痛莫酷斯，彼蒼者天，遂臻魏都，遊魂舊邑，大隧开涂，靈將斯戢，叹息霧興，揮淚雨集，徘徊輀柩，號咷弗及，神光既幽，佇立以泣。","sortOrder":55},
  {"id":"s_work_nvlt_15_56","chapterId":"ch_work_nvlt_15","text":"晉張華章懷皇後诔曰：自天陶靈，必有徵祥，誕在初載，亦曜神光，顯應天祿，聿嫔聖皇，受氣自然，寔聽清和，內含茂质，外發英華，身處宸極，敬恭惟夙，窈窕淑媚，柔順婉穆，宣慈內政，流化太微，六宮变雅，清我壸闈，經纶庶屬，積思萬機，既臻緝熙，玄泽流衍，將翼我後，登封降禪，氛祲告妖，沉結弥留，奄忽升遐，弃世高遊，聖上哀懷，感切悼心，率土縞素，遏密八音，眇眇遊靈，將焉所之，容光幽邁，豈有反期，杳杳新宮，下絕三泉，茫茫陵域，合體中原，委弃暉章，即安太清。","sortOrder":56},
  {"id":"s_work_nvlt_15_57","chapterId":"ch_work_nvlt_15","text":"晉左九嫔元皇後楊氏诔曰：昔有莘適殷，薑姒歸周，宣德中閨，徽音永流，樊衛二姬，匡齊翼楚，馬邓兩妃，亦毗漢主，峨峨元後，光嫔晉宇，伉俪聖皇，比蹤往古，遭命不永，北［明本作背。］陽即陰，六宮號咷，四海動心，嗟餘鄙妾，衔恩特深，追慕三良，甘心自沉，何用存思，不忘德音，何用紀述，記辭翰林，乃作诔曰：惟嶽降神，顯茲禎祥，篤生英媛，休有烈光，和畅春日，操厲秋霜，率由四教，容德匪荒，行周六親，徽音顯扬，皇英佐舜，涂山翼禹，明明我後，與世同矩，雲胡不造，丁茲禍殃，寢疾弥留，寤寐不康，祈祷無應，嘗藥無良，有始有終，天地之經，自非三光，誰能不零，存播令德，没圖丹青，溫溫元後，寔宣慈焉，撫育群生，恩惠滋焉，懸名日月，垂萬春焉。","sortOrder":57},
  {"id":"s_work_nvlt_15_58","chapterId":"ch_work_nvlt_15","text":"宋謝莊孝武帝宣貴妃诔曰：律穀罢煊，龍乡輟晓，照車去魏，聯城辭趙，皇帝痛掖殿之既阒，悼泉涂之已空，巡步簷而臨蕙路，集重陽而望椒風，國軫丧淑之傷，家凝霣妣之怨，敢撰德於旂旒，庶圖芳於鍾萬，其辭曰：玄丘煙煴，瑤台降芬，高唐泄雨，巫山鬱雲，誕發蘭儀，光啟玉度，望月方娥，瞻星比婺，敏德素里，栖景震軒，處麗絺绤，出懋蘋蘩，脩詩贲道，稱圖昭言，翼訓姚幄，贊軌尧門，展如之華，寔邦之缓，敬勤顯陽，肅恭崇憲，奉榮惟約，承茲以遜，逮下延和，臨朝违怨，祚靈集祉，慶藹迎祥，皇胤璲式，帝女金相，聯附齊穎，接萼均芳，以蕃以牧，燭代暉梁，视朔書氣，觀台告祲，璁衡藏容，翚翟毀衽，掩采瑤光，收華紫禁，移氣朔兮变羅紈，白霜凝兮歲將阑，庭树驚兮中睢［《文選》五十七作帷。］响，金棋暧兮玉座寒，仰昊天之莫報，怨凯風之徒攀，經建春而右轉，循閶阖而径度，旌委鬱於飛飛，龍逶遲於步步，锵楚挽於槐風，唱邊箫於松霧，涉姑射而環回，望樂池而顧慕，晨辒解鳳，晓蓋俄今，［《文選》作金。］山庭寢白，隧露抽陰，重扃閉兮燈以黯，中泉寂兮此夜深，銷神躬於壤末，散靈魄於天浸。","sortOrder":58},
  {"id":"s_work_nvlt_15_59","chapterId":"ch_work_nvlt_15","text":"【哀策】晉潘嶽景獻皇後哀策文曰：於穆先後，俪皇协運，世宗之胤，德博化先，用俭禮峻，任姒隆周，後亦母晉，終溫且惠，其儀淑慎，既慎其儀，克明禮教，撫翼齊蕃，訓成弘操，其慈有威，不舒不暴，乃家乃邦，是則是效，嗟餘艱屯，仍遭不造，靡恃惟妣，景命弗保，心之雲痛，痛貫穹昊，袭龟筮之良辰，啟幽房之潛邃，整武駕之隆牡，結龍辀之縞驷，望旂常而崩摧，披辒辌以增欷，口呜咽以失聲，目橫迸以洒淚，邈雨絕於宮闈，長無觌於仿佛。","sortOrder":59},
  {"id":"s_work_nvlt_15_60","chapterId":"ch_work_nvlt_15","text":"晉張華元皇後哀策文曰：天地配享，化成兩儀，王假有道，義在伉俪，薑嫄佐喾，二妃興妫，仰觀古籍，觊亦同規，今胡不然，景命夙虧，我膺歷運，臨統萬方，正位於內，寔在嫔嫱，天作之合，駿發其祥，河嶽降靈，啟祚華陽，弈世丰衍，朱绂斯皇，來翼家邦，憲度是常，緝熙陰教，德聲顯扬，如何不弔，背世陨丧，瑤齊無住，長去蒸嘗，追懷永悼，率土摧傷，陵兆既宅，將遷幽都，宵陳夙駕，元妃其徂，宮闈遏密，階庭永虛，設祖屬紼，告駕啟途，法服翚褕，寄象容車，金辂晻藹，帷裳不舒，千乘動軫，六骥踟蹰，銘旌树表，翣柳雲敷，祁祁同軌，岌岌蒸徒，孰雲不懷，哀感萬夫，寧神虞旃，安體玄庐。","sortOrder":60},
  {"id":"s_work_nvlt_15_61","chapterId":"ch_work_nvlt_15","text":"宋顏延之元皇後哀策文曰：龍轜纚綍，容翟結驂，皇涂昭曠，神路幽嚴，皇帝親臨祖饋，躬瞻宵載，飾遺儀於組旒，纶徂音乎珩佩，悲黼翣之移御，痛翚褕之重晦，降轝客位，彻奠殯階，乃命史臣，累德述懷，其辭曰：倫昭俪昇，有總有凭，圓精初鑠，方祇始凝，昭哉世族，祥發慶膺，秘儀景胄，圓光玉繩，昌暉在陰，柔明將進，率禮蹈和，稱詩納順，爰自待年，金聲夙振，亦既有行，素章增絢，象服是加，言觀維則，俾我王風，始基嫔德，蕙問川流，芳猷允塞，方江泳漢，再謠南國，伊昔不造，鸿化中微，用集寶命，仰陟天機，釋位公宮，登曜紫闈，钦若皇姑，允迪前徽，孝達寧親，敬行宗祀，進思才淑，傍宗圖史，降音在詠，動容成紀，坤則順成，皇軒润飭，下節震騰，上清眺侧，有來斯雍，無思不極，象物方臻，视祲告沴，太和既融，攸華委世，蘭殿長陰，椒涂弛衛，戒涼在律，杪秋即穸，霜夜流唱，晓月升魄，八神警引，五辂遷跡，噭々储嗣，哀哀列辟，洒零玉墀，雨泗丹液，［《文選》五十八作掖。］撫存悼亡，感今懷昔，南背國門，北首山園，遙酸紫蓋，眇泣素軒，滅采清都，夷體寿原，邑野淪藹，戎夏悲歡，［《文選》作讙。］來方可述，往駕弗援。","sortOrder":61},
  {"id":"s_work_nvlt_15_62","chapterId":"ch_work_nvlt_15","text":"齊謝朓敬皇後哀策文曰：翚帟舒阜，玄堂啟扉，俎彻三獻，筵卷六衣，懷蜃衛而延首，想鹥辂而撫心，痛椒涂之先廓，哀長信之莫臨，身隔兩起，時無三辰，旋詔左言，光敷聖善，其辭曰：帝唐遠胄，御龍遙緒，在秦作劉，在漢开楚，肇惟淑聖，克柔克令，清漢表靈，曾沙膺慶，爰定厥祥，徽音允穆，光華沼沚，榮曜中穀，敬始絺绤，教先穜稑，睿問川流，神襟蘭鬱，先德韜光，君道方披，辅佐求賢，在謁無陂，顧史弘式，陳詩展義，厚下曰仁，藏往伊智，十亂斯俟，四教岡式，思媚諸姑，貽我嫔則，化自公宮，遠被南國，軒曜懷光，素舒佇德，闵予不祐，慈訓早违，方年冲藐，懷袖靡依，家臻寶業，身嗣昌暉，寿宮寂遠，清廟虛歸，帝遷明命，民神胥悅，乾景外臨，陰儀內缺，空悲故劍，徒嗟金穴，冯相告祲，宸駕長往，貽厥遠圖，末命是奖，懷丰沛之綢缪，背神京之弘敞，陋蒼梧之不從，遵鲋隅以同坏，陳象設於園寢，映舆鍰於松楸，望承明而不入，度清洛而南遊，繼池綍於通軌，接龍帷於造舟，回塘寂其已慕，東川澹而不流，藉閟宮之遠烈，聞缵女之遐慶，始协德於蘋蘩，終配祇而表命，慕方纏於賜衣，悲日隆於撫鏡，思寒泉之岡極，讬彤管於遺詠。","sortOrder":62},
  {"id":"s_work_nvlt_15_63","chapterId":"ch_work_nvlt_15","text":"梁任昉王貴嫔哀策文曰：遊衣戒節，轜車命服，永去椒華，長辭嘉福，笥緘遺組，筵委尘鞠，將命啟期，寔惟嘉數，珮空响其何節，姆下當［疑當作堂。］其誰傅，殯宮既毀，祖饋斯撤，爰命史臣，宣美來裔，坤載既厚，內德雲助，軒五有弘，姬十斯豫，誕咨邦淑，選自良家，爰登六列，象服委蛇，青絇丹繶，辰衣素紗，肅雍婦職，佥曰俞往，贊景望舒，方娠明兩，心前軌慶，軒中增朗，與栝不愆，朏魄無爽，式陪茧觀，有事蠶宮，降舆訪道，基我王風，宣禮撤豆，緝樂房中居貴能降，在盈思冲，仁者必寿，彼蒼者穹，如何不淑，萬化齊終，荐車告途，殯穸既辨，黼翣璀以陆離，帷〈巾光〉紛其舒卷，出桂宮而北徂，經未央以西轉，池紼顧而徐前，服馬嘶而不踐，霜霏微而初被，野空籠而始彫，促虞泉於薤露，撫悲翁於短箫，母以子貴，義弘前哲，申前［明本作襄，疑當作衰。］齊削以從疑，革麻縓之輕殺，達副君之天至，賦白華之無缺，庶清廟之微微，非寿原之永翳。","sortOrder":63},
  {"id":"s_work_nvlt_15_64","chapterId":"ch_work_nvlt_15","text":"【謚策】宋謝莊殷貴妃謚策文曰：維年月日，皇帝曰咨故淑儀殷氏，惟爾合徽挺懋，爰光素里，友琴流荇，實華紫掖，奉軒景以柔明發跡，處椒風以婉娈升［原作外，據冯校本改。］名，幽閒之范，日藹層闈，繁祉之慶，方隆蕃世，而當春掩藻，中波滅源，朕用震悼，傷於厥心，松區已剪，泉冥將遂，宜旌德第行，式衍聲芳，魂而有靈，尚茲寵渥，呜呼哀哉。","sortOrder":64},
  {"id":"s_work_nvlt_15_65","chapterId":"ch_work_nvlt_15","text":"【詔】梁沈約梁武帝立內職詔曰：刑於垂訓，周文所以表德，壸闈失序，漢氏所以丧邦，併被諸方策，式昭戒勸，魏晉以來，雖雲簡薄，而內職名號，參差不同，在宋太始，位置繁縟，遂設九品，且擬外朝，填委椒掖，徵費無已，自此相仍，踵以成舊，昭陽九華，千門萬戶，朕受命自天，始基七百，思所以立房自邇，貽厥方來，前代職品，所宜因革，外可詳議，務令該允。","sortOrder":65},
  {"id":"s_work_nvlt_15_66","chapterId":"ch_work_nvlt_15","text":"陳徐陵陳文帝登祚尊皇太後詔曰：朕以虛薄，才非弘濟，竊守蕃維，常懼盈滿，豈圖蒼昊不弔，國步艱難，皇嗣元良，藐在崤渭，二臣奉迎，川途靡從，六傳還朝，淹留未日，令國圖無主，家業事隆，上奉父母之嚴規，下逼群公之庭諍，遂以庸质，升纂帝基，對扬大化，弥增號懼，今宜式遵舊則，奉上皇後尊號為皇太後，御慈訓宮，一依前典，若中流靜晏，皇嗣歸來，辄當解绂於箕山之陽，歸老於琅琊之國，复子明辟，還承寶圖，若問與夷，無媿園寢。","sortOrder":66},
  {"id":"s_work_nvlt_15_67","chapterId":"ch_work_nvlt_15","text":"【章】梁江淹為建平皇［本集作王。］慶王後正位章曰：伏承以嘉月惠時，膺曜宸正，翚珩昭品，褕組在飾，休遍函夏，譽殷靈昧，伏惟嶽曜靜德，式懷謙順，升降圖傳，左右詩史，夙鏡茂資，早摛芳訓，衍教紫庭，麗軌華屋，聲激綺組，風偃家邦。","sortOrder":67},
  {"id":"s_work_nvlt_15_68","chapterId":"ch_work_nvlt_15","text":"梁沈約為六宮拜章曰：蓬闈菲质，嘉淑無筭，越自幽衡，登軀宸漢，奉日月之華，侍巾屣之末，何以廁鴛鸞之盛序，奉屬車之清尘，隨江總為陳六宮謝章曰：恭膺禮命，愧集丹縷之顏，拜奉曲私，愁萦翚羽之色，曾宮夜火，伯媛匪驚，楚謝奔涛，貞薑何懼，豈期日月騰影，風雲寫润，遂复位崇九御，聲高六列，象服增華，丹軿耀采，何以弼佐王風，克柔陰化，兢惶併集，追想流荇之詩，荷據相併，遂失鳴環之節。","sortOrder":68},
  {"id":"s_work_nvlt_15_69","chapterId":"ch_work_nvlt_15","text":"【表】魏傅嘏請立貴嫔為皇後表曰：有虞始德，觀化妫汭，夏後創業，啟祚涂山，鹹以淑哲，垂文曲頌，伏惟貴嫔，誕秀令族，禀真高胄，應昭明之量，兼聖善之行，金玺未授，而玉瑞先顯，表贊天休，昭隆後祚，貞侔先典，告逾往訓，而猶潛光，未即皇統，進违二儀煙煴之德，退阚懸象兼曜之儀，群僚百辟，所以竦佇陛下钦若天秩，祗贊帝祉，夙崇盛禮，俾君萬國，則六合承風，天下幸甚。","sortOrder":69},
  {"id":"s_work_nvlt_15_70","chapterId":"ch_work_nvlt_15","text":"魏陳王曹植上卞太後诔表曰：大行皇太後，資坤元之性，體載物之仁，齊美薑嫄，等德任姒，佐政內朝，惠加四海，草木荷恩，含氣受润，庶鍾元吉，永膺萬祚，何圖一旦，早弃明朝，背絕臣庶，悲痛靡告，臣聞銘以述德，诔尚及哀，是以冒越谅闇之禮，作诔一篇，知不足贊楊明貴，以展臣蓼莪之思，忧荒情散，不足觀采。","sortOrder":70},
  {"id":"s_work_nvlt_15_71","chapterId":"ch_work_nvlt_15","text":"晉左九嫔上元皇後诔表曰：伏惟聖善宣慈，仁洽六宮，含弘光大，德润四海，妾聞之前志，卑不诔尊，少不诔長，楊雄臣也，而诔漢後，班固子也，而诔其父，皆以述楊景行，顯之竹帛，豈所謂三代不同禮，隨時而作者乎。","sortOrder":71},
  {"id":"s_work_nvlt_15_72","chapterId":"ch_work_nvlt_15","text":"後魏溫子昇魏帝納皇後群臣上禮文曰：臣聞軒轅乃神，西陵以之作合，夏後至聖，涂山於是來嫔，伏惟陛下，龍飛缵歷，大明理運，長秋既建，陰教有主，景命無窮，靈基長世，普天之下，莫不欣躍。","sortOrder":72},
  {"id":"s_work_nvlt_15_73","chapterId":"ch_work_nvlt_15","text":"隨江總為陳六宮謝表曰：鶴籥晨啟，雀釵晓暎，恭承盛典，肅荷徽章，步動雲桂，香飄霧縠，媿纏艳粉，無情拂鏡，愁萦巧黛，息意臨窗，妾聞漢水赠珠，人聞絕世，洛川拾翠，仙處無双，或有風流行雨，窈窕初日，聲高一笑，价起兩環，乃可桂殿迎春，蘭房侍寵，借班姬之扇，未掩驚羞，假蔡琰之文，寧披悚戴。","sortOrder":73},
  {"id":"s_work_nvlt_15_74","chapterId":"ch_work_nvlt_15","text":"【論】宋范晔皇後紀論曰：周禮，後正位宮闈，同體天王，夫人坐論婦禮，九嫔掌教四德，世婦知丧祭賓客，女御序於王之燕寢，順宮分務，［原訛霧，據冯校本改。］各有典司，女史彤管，記功書過，居有保阿之訓，動有環珮之响，進賢才以辅佐君子，哀窈窕而不淫其色，所以能宣述陰化，脩成內則，秦併天下，多自驕大，官備七國，爵列八品，漢興因循，而婦製莫釐，高祖帷箔不修，孝文衽席無辨，而選納尚簡，飾玩少華，自武元之後，世增淫費，至乃掖庭三千，增級十四，及光武中興，斫彫為朴，六宮稱號，唯後貴人，貴人金印紫綬。又置美人宮人采女三等，明帝事遵先旨，宮教頗修，登建嫔後，必先令德，內無出阃之言，權無私溺之授，可謂矯其弊矣，孝章以下，漸用色授，恩隆好合，遂忘灾蠹，自古雖主幼時艱，王家多衅，委成冢宰，未有专任婦人，斷割重器，唯秦芊太後，始攝政事，故穰侯權重於昭王，家富於嬴國，漢仍其谬，知患莫改，東京皇統屢絕，權歸女主，外立者四帝，臨朝者六後，莫不定策帷帟，委事父兄，貪孩童以久其政，抑明賢以专其威，任重道愆，利深禍速，身犯霧露於雲台之上，家婴缧絏於圄犴之下，堙滅連踵，傾辀繼路，而赴蹈不息，焦烂為期，終乃凌夷大運，淪亡神寶，詩書所叹，略同一揆。","sortOrder":74},
  {"id":"s_work_nvlt_15_75","chapterId":"ch_work_nvlt_15","text":"【行状】梁江淹宋建平王太妃周氏行状曰：竊聞侯服之譽，非黃冠所敷，玉食之門，寧皂衣所述，谅畏裒虛美於君後，披空名於鼎貴，然昔有漢臣诔行，晉史書德者，亦雲實而已焉，太妃誕巽離之正和，函雲露之中氣，凝采髻歲，贲章笄年，若乃彤管女圖之學，纂組綺縞之工，升降虔謙之儀，柔靜嘉順之節，莫不中道若性，不嚴而成，故譽滿帷阃，聲播軒殿。","sortOrder":75},
  {"id":"s_work_nvlt_15_76","chapterId":"ch_work_nvlt_15","text":"《藝文類聚》　唐·欧陽詢","sortOrder":76},
  {"id":"s_work_nvlt_16_1","chapterId":"ch_work_nvlt_16","text":"卷十六储宮部","sortOrder":1},
  {"id":"s_work_nvlt_16_2","chapterId":"ch_work_nvlt_16","text":"○储宮太子妃［附］公主","sortOrder":2},
  {"id":"s_work_nvlt_16_3","chapterId":"ch_work_nvlt_16","text":"◇储宮","sortOrder":3},
  {"id":"s_work_nvlt_16_4","chapterId":"ch_work_nvlt_16","text":"《周易》曰：黃離元吉，象曰：明兩作離，大人以繼明照於四方。","sortOrder":4},
  {"id":"s_work_nvlt_16_5","chapterId":"ch_work_nvlt_16","text":"尚書［《太平御覽》一百四十六作尚書大傳，下同。］曰：惟四月，太子發上祭於畢，下至於盟津之上，乃告司馬司徒司空。","sortOrder":5},
  {"id":"s_work_nvlt_16_6","chapterId":"ch_work_nvlt_16","text":"又曰：太子發升於舟，中流，白魚入於舟，王跪取出，俟以燎，群公鹹曰：休哉。","sortOrder":6},
  {"id":"s_work_nvlt_16_7","chapterId":"ch_work_nvlt_16","text":"《尚書大傳》曰：天子太子年十八，曰孟侯，孟侯者，於四方諸侯來朝迎於郊者，問其所不知也。","sortOrder":7},
  {"id":"s_work_nvlt_16_8","chapterId":"ch_work_nvlt_16","text":"尚書《洪范五行傳》曰：心之大星，天皇也，其前星，太子也，後星，庶子也。","sortOrder":8},
  {"id":"s_work_nvlt_16_9","chapterId":"ch_work_nvlt_16","text":"《禮記》曰：王太子王子群後之太子卿大夫元士之適子，凡入學以齒。","sortOrder":9},
  {"id":"s_work_nvlt_16_10","chapterId":"ch_work_nvlt_16","text":"又曰：文王之為世子，朝於王季，日三，雞初鳴而衣服，至於寢門外，問內竖之御者曰：今日安否何如，內竖曰安，文王乃喜，及日中又至，亦如之，及暮又至，亦如之，其有不安，則內竖以告文王，文王色忧，行不能正履，王季复膳，然後亦复初，食上必在视寒暖之節。","sortOrder":10},
  {"id":"s_work_nvlt_16_11","chapterId":"ch_work_nvlt_16","text":"又曰：國君世子生，告於君，接以大牢，宰掌具。","sortOrder":11},
  {"id":"s_work_nvlt_16_12","chapterId":"ch_work_nvlt_16","text":"又曰：行一物而三善皆得者，唯世子而已，其齒於學之謂，其一知父子之禮，其二知君臣之義，其三知長幼之節，故學之父子焉君臣焉長幼焉，一人元良，萬國以貞，世子之謂也。","sortOrder":12},
  {"id":"s_work_nvlt_16_13","chapterId":"ch_work_nvlt_16","text":"《左傳》曰：九月丁卯，子同生，以太子之禮舉之，接以太牢，士負之，士妻食之，公與文薑宗婦命之。","sortOrder":13},
  {"id":"s_work_nvlt_16_14","chapterId":"ch_work_nvlt_16","text":"《白虎通》曰：天子之太子諸侯之世子皆就於外者，尊師重先王之道也，故曲禮曰：禮聞來學，不聞往教也。","sortOrder":14},
  {"id":"s_work_nvlt_16_15","chapterId":"ch_work_nvlt_16","text":"《贾誼書》曰：文王使太公望傅太子發，嗜鮑魚，公不與，曰：鮑魚不登俎，豈有非禮而可養太子哉。","sortOrder":15},
  {"id":"s_work_nvlt_16_16","chapterId":"ch_work_nvlt_16","text":"《春秋外傳》曰：靈王二十二年，穀洛龍斗，將毀王宮，王欲壅之，太子晉諫曰：晉聞古之長民者，不隳山，不崇藪，不防川，不竭泽，靈王不從。","sortOrder":16},
  {"id":"s_work_nvlt_16_17","chapterId":"ch_work_nvlt_16","text":"又曰：師曠見太子晉曰：吾聞太子之語，高於太山，原聞一言，太子曰：吾聞太師之來，喜而又懼，汝知人年長短吉凶也，師曠曰：君色赤，君聲清，火色不寿，太子曰：然，却後三年，吾上賓於帝，汝慎無言，殃將及汝，太子時年十五，後三年而卒。","sortOrder":17},
  {"id":"s_work_nvlt_16_18","chapterId":"ch_work_nvlt_16","text":"《史記》曰：厲王出奔彘，太子靜匿召公之家，國人聞，乃围之，召公以其子以代太子，太子得脱，召公周公二相行政，號曰共和，十四年，厲王死，太子靜長於召公家，二相乃共立之，是為宣王也。","sortOrder":18},
  {"id":"s_work_nvlt_16_19","chapterId":"ch_work_nvlt_16","text":"又曰：上欲废太子，立趙王如意，大臣諫爭，未得堅决，張良為畫計曰：顧上不能致者，商山四人，今能無愛金玉，使太子卑辭厚禮，迎此四人，則一助也，於是四人至，侍太子入宴，年皆八十餘，眉鬢皓白，衣冠甚伟，上怪問之，四人各以名對，帝大驚曰：吾求公數歲，常避逃我，今何從吾兒遊，四人去，上目送之，指示戚夫人曰：彼四人辅之，羽翼已成，難可動矣。","sortOrder":19},
  {"id":"s_work_nvlt_16_20","chapterId":"ch_work_nvlt_16","text":"《漢書》曰：孝景王皇後，武帝母也，內太子宮，太子幸愛之，生三女一男，男方在身時，王夫人夢日入其懷，以告，太子曰：此貴徵也，未生而文帝崩，景帝即位，王夫人生男，是為武帝。","sortOrder":20},
  {"id":"s_work_nvlt_16_21","chapterId":"ch_work_nvlt_16","text":"又曰：孝元皇帝，宣帝太子也，母曰許皇後，宣帝微時，生民間，年二歲，宣帝即位，八歲立為太子，壮大柔仁好儒。","sortOrder":21},
  {"id":"s_work_nvlt_16_22","chapterId":"ch_work_nvlt_16","text":"又曰：孝成皇帝，元帝太子，母曰王皇後，元帝在太子宮，生甲觀畫堂，為世嫡皇孫，宣帝愛之，字曰太孫，常置左右，年三歲而宣帝崩，元帝即位，帝為太子，壮好經書，宽博謹慎，初居桂宮，上嘗急召，太子出龍樓門，不敢絕馳道，西至真城門，得絕乃度，還入作室門，上遲之，問其故，以状對，上大悅，乃著令太子得絕馳道。","sortOrder":22},
  {"id":"s_work_nvlt_16_23","chapterId":"ch_work_nvlt_16","text":"《東觀漢記》曰：建武時，天下墾田不實，詔下州郡檢其事，帝見陳留牍上有書曰：潁川弘農可問，河南南陽不可問，帝詰吏由趣，吏不服，抵言於長安街得之，帝怒，時明帝年十二，在幄後曰：吏受郡敕，當欲以墾田相方耳，帝曰：即如此，河南南陽不可問，對曰：河南帝城，多近臣，南陽帝乡，多近親，田宅逾製，不可為准，帝令詰問，乃首服，如顯宗言。","sortOrder":23},
  {"id":"s_work_nvlt_16_24","chapterId":"ch_work_nvlt_16","text":"《魏略》曰：太祖不時立太子，太子自疑，是時高元呂者，善相人，乃呼問之，對曰：其貴不可言，因問寿幾何，元呂曰：甚寿，至四十，當有小苦，過是無忧，後無幾而立為太子。","sortOrder":24},
  {"id":"s_work_nvlt_16_25","chapterId":"ch_work_nvlt_16","text":"《魏志》曰：明帝，文帝太子，生而愛之，常令在左右，數歲而有歧嶷之姿，武帝異之曰：我基於爾三世矣，每朝宴會同，與近臣併列帷幄，好學多識，特留意法理。","sortOrder":25},
  {"id":"s_work_nvlt_16_26","chapterId":"ch_work_nvlt_16","text":"《吳志》曰：孫登，權長子也，立為太子，選置師傅，詮簡秀士，以為賓友，諸葛恪為左辅，張休為右弼，顧谭為辅正，陳表為翼正，為四友於東宮，號為多士，登镇武昌，或時獵，當由径道，常避遠良田，不踐苗稼，至所憩止。又擇空閒之地，不欲煩民。","sortOrder":26},
  {"id":"s_work_nvlt_16_27","chapterId":"ch_work_nvlt_16","text":"王隱《晉書》曰：初，武帝未為世子，文帝問裴秀，人有相否，秀曰：中撫軍立，發至地，手過於膝，人望既茂，天表如此，非人臣之相。","sortOrder":27},
  {"id":"s_work_nvlt_16_28","chapterId":"ch_work_nvlt_16","text":"又曰：愍懷太子名遹，少聰惠，帝愛之，六七歲時，帝夜望火，太子牵上衣裾，使入闇中，上問其故，太子對曰：暮夜仓卒，宜備非常，不當親近火光，令人照見。","sortOrder":28},
  {"id":"s_work_nvlt_16_29","chapterId":"ch_work_nvlt_16","text":"《世說》曰：晉明帝數歲，在元帝處坐，時有人從長安來，帝謂曰：爾言長安日遠，明帝曰：只聞人從長安來，不聞從日邊來，日固宜遠，帝大嗟賞，明日，群僚併集，帝更問，乃答雲，日近，帝失色，乃謂曰：何以昨語異，答曰：出門見日，不見長安，眾莫不嗟叹。","sortOrder":29},
  {"id":"s_work_nvlt_16_30","chapterId":"ch_work_nvlt_16","text":"【詩】梁劉孝威重光詩曰：重光，储後宣製義也，赫赫重光，明明二聖，帝作储述，禮和樂正，中衢置樽，高堂懸鏡，其酌不窮，其明逾盛，德音孔昭，民胥攸詠，明明二聖，赫赫重光，風神洒落，容止汪洋，瞻彼談扇，載抑載扬，何斯天辯，如珪如璋，顏闵函席，遊夏升堂，以卿以士，惟公惟王，思媚储後，顧哉樂康，芃芃黍苗，陰雨膏之，诜诜纓冕，储王道之，道之以禮，齊之以仁，理則探聖，言則窮神，訓於四國，覃於萬民。","sortOrder":30},
  {"id":"s_work_nvlt_16_31","chapterId":"ch_work_nvlt_16","text":"又奉和簡文帝太子詩曰：太子天下本，元良萬國貞，周朝推上嗣，漢世慚重明，前星涵瑞采，洊雷扬遠聲，三善傳樂正，百行紀司飛，九流遍已辯，七經鹹所精，博聞強子政，高才凌長卿，禮尊逾屈己，德盛益卑情，仙氣貽鍾相，儒道推桓榮，延賢博望苑，视膳長安城，園綺隨金辂，浮丘侍玉笙，智囊前殿笏，端士後垂纓，九仙良所重，四海更東傾，班输同舉乘，甲觀齊蓬行，［《初學記》十作瀛。］","sortOrder":31},
  {"id":"s_work_nvlt_16_32","chapterId":"ch_work_nvlt_16","text":"【賦】魏卞蘭贊述太子賦曰：超古人之遐跡，崇先聖之弘基，躭八素之秘奧，遵二儀於大猷，正往昔之常弊，定當世之舊儀，禀休和之上性，應五百之運期。著典憲之高論，作叙懽之麗詩，越文章之常檢，扬不學之妙辭，蹈布衣之所難，闡善道而廣之，道無深而不测，術無細而不敷，論古賢以叹息，睹懿德以歡娱，歷精思於訓籍，忽日移而忘劬，雖明略而無上，猶博納以自扶，賓故老以勸俗，諷六經以榮儒，嘉通人之達節，笑俗士之守株，匿天盛之嚴厲，扬恺悌之和舒，惟凡百之詠德，感恩惠之有餘，信清風之休著，非臣下之敢虛，乃作頌曰：明明太子，既叡且聰，博B聞W強Q記，聖思無双，猗之左右，如虎如龍，八俊在侧，旁無諛凶，富不忘施，尊而益恭，研精書籍，留思異同，建計立議，廓然發蒙，天下延頸，歌頌德音，聞之於古，見之於今，深不可测，高不可尋，創法萬載，垂此休風。","sortOrder":32},
  {"id":"s_work_nvlt_16_33","chapterId":"ch_work_nvlt_16","text":"【箴】晉溫峤侍臣箴曰：勿謂其微，覆簣成高，勿謂其細，巨由纖毫，故曰善不積，不足以成名，話言如絲，而萬里來享，無以處極，而利在永貞，是以太子之在東宮，均士抗禮，以卑厥情，入學齊齒，言稱先生，不以賢自臧，不以貴為榮，思有虞之蒸蒸，尊周文之翼翼，晨昏靡违，夙興晏息，師傅是瞻，正人在侧，屏彼佞諛，納此亮直，故傅敬德義，臣思盡忠，或稽古訓导，惟道之不融，或造膝诡辭，懼咎之蘊崇，惴惴兢兢，思二雅之遺風，鑒乎九三，天祿永終，近臣司規，敢告常從。","sortOrder":33},
  {"id":"s_work_nvlt_16_34","chapterId":"ch_work_nvlt_16","text":"周王褒皇太子箴曰：臣聞教化爰始，詠歌不足，政俗既移，風雅斯变，伏惟皇明御宇，功均造物，改文為质，斫雕成素，皇太子洊雷居震，明兩作離，春夏幹戈，秋冬羽籥，叔譽慚五稱之對，師曠降四馬之恩，竊以太史官箴，虞書所誡，永树芳烈，丞相所以垂文，深睹安危，太傅以之陳訓，敢自斯義，獻箴雲爾，天生蒸民，司牧斯树，鹹熙庶績，式昭王度，惠民垂統，元良繼體，麗止離暉，惟機天啟，令問令望，聞詩聞禮，從曰撫軍，守曰監國，秋坊通夢，春宮養德，桓榮獻書，荀攸觀則，元子為士，齒卿命秩，朝服寢門，回車作室，正陽君位，乔枝父道，臣子所崇，忠孝為寶，勿謂居尊，禍福無門，勿謂親賢，王道無偏，無為慮始，無為事先，損之又損，而全之亦全，無往不复，無平不陂，美疹甘言，鮮不為累，則哲惟難，知人未易，居室為善，分陰無弃，亡保其存，危安其位，神聽不惑，天妖斯忌，文昌著於前星，秬鬯由於守器，庶僚司箴，敢告閽寺。","sortOrder":34},
  {"id":"s_work_nvlt_16_35","chapterId":"ch_work_nvlt_16","text":"隋戴逵皇太子箴曰：無謂父子無間，江充掘蠱，無謂兄弟無携，倡優起舞。","sortOrder":35},
  {"id":"s_work_nvlt_16_36","chapterId":"ch_work_nvlt_16","text":"【诔】晉陆機愍懷太子诔曰：明明皇子，成命既駿，保乂皇家，載生淑胤，茂德克廣，仁姿朗俊，當克無疆，光紹有晉，如何不弔，暴離咎艱，曾是遘愍，匪降自天，肇傾運祚，遂丧華年，呜呼哀哉，沉雲既祛，日月增暉，靈寵可赠，冤魂難追，舊物東反，靈柩西歸，傷我惠後，寂焉翳滅，衔哀駿奔，凶服就列，追慕徽尘，興言斷絕，敢诔遺風，庶存芳烈，其辭曰：巍巍皇基，弈弈紫微，有命既集，天祿永綏，篤生太子，纂德承茂，平紹大烈，時惟洪胄，奇穎發翘，清藻在秀，誕自幼蒙，逮事武皇，展矣太子，播此琼芳，允矣聖祖，無言不臧，婉娈乘舆，名裕德昌，龍集庚戌，日月改度，赫赫明明，我皇登祚，厥登伊何，皇統是荷，華绂重采，翠蓋垂葩，鸞旗阿那，玉衡吐和，聿來在宮，體亮而誠，肅雍皇極，思媚紫庭，亦既涉學，遵師盛道，何年之妙，而察之早，谠言必复，乖義則考，惟天有命，太子膺之，惟皇有慶，太子承之，當究遐年，登茲胡耇，緝熙有晉，克構帝宇，如何晨牝，秽我朝聽，仰索皇家，惟尘明聖，惴惴太子，終溫且敬，衔辭即罪，掩淚祗命，顯加放流，潛肆鸩毒，痛矣太子，乃離斯酷，謂天蓋高，訴哀靡告，鞠躬引分，顧景摧剝，呜呼哀哉，凡民之丧，有戚有姻，太子之殁，傍無昵親，跼蹐嚴宮，絕命禁闈，幽柩偏寄，孤魂曷歸，呜呼太子，生冤殁悲，疋夫有怨，尚或殒霜，矧乃太子，萬邦攸望，普天扼腕，率土懷傷，精感六沴，咎徵紫房，爰茲元辅，啟我令圖，王赫斯怒，天誅靡逋，攙搶叱扫，元凶服辜，仁詔引咎，哀策東徂，光复寵祚，紹建藐孤，於時暉服，粲焉畢陳，庭旅舊物，堂有故臣，孰雲太子，不見其人，呜呼哀哉，既濟洛川，靈旆左回，三軍凄裂，都邑如隤，慨矣寤叹，念我愍懷。","sortOrder":36},
  {"id":"s_work_nvlt_16_37","chapterId":"ch_work_nvlt_16","text":"【哀策】齊王融皇太子哀策文曰：繡幕啟涂，銅池從殯，葆铎既行，枚綍且引，皇帝痛粢，盛之闕奉，哀匕鬯之有亡，悯含嗟乎崇正，顧掩欷於承光，式睠元良，永懷人寶，俾茲史策，載餘風道，其辭曰：居辰北極，在日重離，誕惟妙善，克自生知，資神為契，合聖如規，地維缺位，月紀褰期，哀纏晦朔，燧改歲時，〈米亶〉粥不溢，薑桂無滋，俯終心禮，昌我帝基，思皇下武，缵戎上德，將葉人神，永貽家國，用稽嗣典，實弘储則，庸器改物，徽號崇名，往辭绿蓋，來馭朱纓，旂旗旖旎，鸞纛聲明，守器宣華，訪安永福，上漏驂軒，初晨戒服，慶色伊滿，夤儀載肅，至誠莫感，遐福空辭，氛程月志，祲動年司，素妭犯列，青雲失滋，中楹軫夢，當戶陳詩，楚藥毀方，秦医反轍，高議虛演，奇文徒說，遠賓上靈，長违昭世，痛結宸慈，哀震華棣，呜呼哀哉，軒惟高寂，庭帳深陰，鶴關晝掩，凫燈夜沉，仍袭未改，容饌如臨，暧徽儀而可慕，摽嗣子之純心，呜呼哀哉，韦弁告期，麻衣請日，辯域展圖，楊龟獻吉，文物充階，具僚在位，總葭挽之哀凄，视風煙之骚瑟，呜呼哀哉，飾麾辂而南指，轉旌羽而北徂，車結軫於雕轂，馬缓節於金蘇，寄靈心於萬象，增恋恋於國都，呜呼哀哉，光徙靡而欲沉，山荒涼而遂晚，城闕緬而何期，平原忽而超遠，情有望而弗追，顧如疑於將反，呜呼哀哉。","sortOrder":37},
  {"id":"s_work_nvlt_16_38","chapterId":"ch_work_nvlt_16","text":"梁王筠昭明太子哀策文曰：蜃辂峨峨，龍驂跼步，羽翿前驅，雲旗北傃，皇帝哀繼明之寢曜，痛嗣德之徂芳，御武帳而凄恸，臨甲觀而增傷，式稽令典，載扬鸿烈，詔撰德於旌旂，求傅徽於舞缀，其辭曰：式載明兩，實惟少陽，儀天比峻，俪景騰光，睿哲膺期，旦暮斯在，識洞機深，量苞瀛海，立德不器，至功弗宰，宽綽居心，溫恭成性，脩襟孝友，率由嚴敬，鹹有种德，惠和齊聖，括囊流略，包舉藝文，遍該緗素，殫極丘墳，騰褰充積，儒墨區分，瞻河闡訓，望魯楊芬，雲物告徵，祲沴褰象，星霾恒曜，山頹朽壤，威儀上賓，德音長往，具僚無荫，谘丞安仰，呜呼哀哉，首夏司开，麥秋紀節，容衛徒警，菁華萎絕，書幌空張，談筵罢設，虛饋饛饛，孤燈翳翳，呜呼哀哉，簡辰請日，筮合龟貞，幽埏夙啟，玄宮獻成，武校齊列，文物增明，昔遊漳水，賓從無聲，今歸郊郭，徒御相驚，呜呼哀哉，背絳闕以遠徂，轥青門而徐轉，顧馳道而詎前，望國都而不踐，凌脩坂之威夷，溯平原之悠緬，骥蹀足以酸嘶，挽凄锵而流泫，呜呼哀哉，混哀音於萧籁，变愁容於天日，雖夏木之森陰，反寒林之萧瑟，既將反而复疑，如有求而遂失，謂天地其無心，遽永潛於容质，呜呼哀哉。","sortOrder":38},
  {"id":"s_work_nvlt_16_39","chapterId":"ch_work_nvlt_16","text":"【詔】梁武帝立皇太子詔曰：非至公無以王天下，非博愛無以臨四海，所以尧禪舜讓，惟德是與，文王舍伯邑考而立武王，格於上下，光被四表，今岱宗牢落，天步艱難，淳風猶鬱，黎民未乂，自非克明克哲，允文允武，豈能荷神器之重，嗣龍圖之尊，晉安王綱，德行內敏，威惠外宣，群後歸美，率土宅心，可立綱為皇太子，庶百年勝殘，方流餘慶，畢世後仁，永固洪業。","sortOrder":39},
  {"id":"s_work_nvlt_16_40","chapterId":"ch_work_nvlt_16","text":"梁沈約立太子詔曰：朕屬當期運，系跡前王，思所以長世流祚，垂之萬葉，百辟鹹以元良之寄，有國莫先，自昔哲後，降及近代，莫不立储树〈女頃〉，［《初學記》十作嫡。］守器承祧，乃旁挹群議，遠惟七百，建茲蒙稚，仰副宗祊，承華肇开，崇基克永，無疆之慶，非獨在餘，思霑渥泽，被之遐邇，可賜天下為父後者爵一級，王侯以下，量錫幣帛。","sortOrder":40},
  {"id":"s_work_nvlt_16_41","chapterId":"ch_work_nvlt_16","text":"後魏溫子昇魏莊帝生皇太子赦詔曰：有國三善，事屬元良，本枝百世，義鍾繼體，朕應天纂命，握圖受箓，景祚唯新，十年以永，今月吉辰，皇子誕育，彩雲映日，神光照殿，方开博望，將起龍樓，遠近同歡，人神共悅，便可大赦天下。","sortOrder":41},
  {"id":"s_work_nvlt_16_42","chapterId":"ch_work_nvlt_16","text":"【教】魏文帝答卞蘭教曰：賦者言事類之所附也，頌者美盛德之形容，故作者不虛其辭，受者必當其實，蘭此豈吾實哉，昔吾丘寿王，一陳寶鼎，何武等徒以歌頌，猶受金帛之賜，蘭事雖不谅，義足寿也，今賜牛一頭。","sortOrder":42},
  {"id":"s_work_nvlt_16_43","chapterId":"ch_work_nvlt_16","text":"【表】吳張俨請立太子師傅表曰：昔贾誼為漢文帝陳周成王為太子，以周公為傅，召公為太保，呂望為太師。又立三少，皆上大夫，使與太子居處，左右前後，皆正人也，明禮義以导習之，故能光熙文武，興隆周室，伏惟陛下，命世應期，順乾作主，皇太子以天然之姿，為國上嗣，朝廷以四海未定，國家多事，師傅之官，闕而未備，臣愚以為高祖初基，天下造創，引張良叔孫通，出為師保，入與朝政，宜博采周漢，依舊儀，用將相名官，辅弼太子，於是以熙贊洪業，增暉日月，實為光大也。","sortOrder":43},
  {"id":"s_work_nvlt_16_44","chapterId":"ch_work_nvlt_16","text":"魏卞蘭贊述太子表曰：伏惟太子，研精典籍，留思篇章，覽照幽微，才不世出，禀聰叡之絕性，體明達之殊風，慈孝發於自然，仁恕洽於無外，是以武夫懷息，文士歸德，竊見所作典論，及諸賦頌，逸句烂然，沈思泉涌，華藻雲浮，聽之忘味，正使聖人复存，猶稱善不暇，所不能間也，昔舜以蒸蒸顯其德，周旦不驕成其名，豈因南面之尊以發假，稱鼎足之盛以取譽哉，夫至尊至貴，能令人畏，不能令人譽，故桀不能变龍逢之心，紂不能易三仁之意，懷近服遠，非德無施，今太子博納多容，海渟嶽峙，學無常師，唯德所在，思無所思，唯德所親，觀士察人，毫毛無失，望色則知其情，覽始則達其終，遏伪辯於未言，絕讒巧於未形，其所以包羅殊類，鑒觀成败，德生於性，明出自然，太子所行，晏然休著，皆群下所常吟詠，誠不复須臣贊扬懿美，褒稱盛行，然後令夜光之璧，顯於金匮，隋侯之珠，彰於韞櫝者也，今相鍾繇，大理王朗，海內英儒，國家柱臣，博物多識，通洽君子，年耆德茂，所更多矣，若遊海者難與論水，睹前世者不可為言，然鹹歸太子巍巍之美，叙述清風，言之有味，聽者欣欣，忘日之夕，流景燿於無窮，布芳陰於四遠，譬若麟龍發足，群獸追蹤，鸞鳳舉翼，眾鳥隨風，小臣區區，嘉樂無已，竊怡綿綿之屬，忘愚戆之言，謹觸冒上賦一篇，以摅狂狷之思。","sortOrder":44},
  {"id":"s_work_nvlt_16_45","chapterId":"ch_work_nvlt_16","text":"宋謝莊慶皇太子元服上至尊表曰：伏惟皇太子殿下，明兩承乾，元良作貳，抗法迂身，英華自遠，樂以脩中，禮以治外，三善克懋，德成教尊，今日昭辰，顯加元服，對靈祇之望，儔上庠之歡，率天罄世，莫不載躍。","sortOrder":45},
  {"id":"s_work_nvlt_16_46","chapterId":"ch_work_nvlt_16","text":"又皇太子元服上皇太後表曰：離景承宸，枢光陪極，毓問東華，飛英上序，樂正歌風，司成頌德，清明神鏡，溫文在躬，練日簡辰，顯備元服，懋三王之教，爥少陽之重。","sortOrder":46},
  {"id":"s_work_nvlt_16_47","chapterId":"ch_work_nvlt_16","text":"梁簡文帝謝為皇太子表曰：伏見詔書，以臣為皇太子，有命自天，實驚物聽，鸿名盛典，爰萃庸薄，势舉千鈞，方茲未重，高摶九萬，比此非遙，臣本凡蔽，賓實無取，特以毓慶雲霄，凭暉璿極，鳴玉內侍，指麾外蕃，猶懼不任，尚疑废職，况复監撫守從，道著前經，恭敬溫文，義彰昔記，震維禮絕，離景事尊，養德北宮，贊業東序，魏平非擬，漢莊靡繼，臣牧拙樊漢，始獲言歸，遂以下才，屬當上嗣，事異定陶之舉，有類膠東之册，將何以著三善之德，延四皓之遊，屈叔譽之辭，卞［卞上明本空一字，有脱文。］蘭之頌。","sortOrder":47},
  {"id":"s_work_nvlt_16_48","chapterId":"ch_work_nvlt_16","text":"又拜皇太子臨軒竟謝表曰：臣聞团暉麗天，洊雷居震，必資令德，寔建賢明，臣本空薄，器業無取，已慚好儒之志，且乏丰下之姿，叨逢慈奖，事出希世，方將問安寢門，视膳天幄，察陳奏之，［之下明本空一字，有脱文。］示嚴警之書，出龍樓而祗召，息車馳道，侍鑾舆而巡幸，說經孔庭，足踐閶阖，風雲之势斯近，飛陵倒景，神仙之舉超然，何以允副元良，和茲守器，逢師曠之褒，值史丹之述。","sortOrder":48},
  {"id":"s_work_nvlt_16_49","chapterId":"ch_work_nvlt_16","text":"又上昭明太子集別傳等表曰：若夫正少陽之位，主承祧之則，口實為美，唯稱啟誦，自茲厥後，罕或聞焉，昭明太子，禀仁聖之姿，縱生知之量，孝敬兼極，溫恭在躬，明月西流，幼有文章之敏，羽籥東序，長備元良之德，非假二疏，寧勞四皓，虎贲恧其經學，智囊慚其調護，豈止博望延賓，寿春能賦，問疑棗據，書戒凭陵而已哉，玉折何追，星頹靡續，地尊虢嗣，外陽之術無徵，位比周储，缑山之駕不反，臣以不肖，妄作明離，出入銅龍，瞻仰故實，思所以揄扬盛軌，宣記德音，謹撰昭明太子別傳文集，請備之延閣，藏諸廣內，未彰茂實，式表洪徽。","sortOrder":49},
  {"id":"s_work_nvlt_16_50","chapterId":"ch_work_nvlt_16","text":"梁任昉為皇太子求一日一入朝表曰：臣聞內竖告安，姬昌怡色，鳴雞戒旦，周發冠履，或以涼燠之候，晨昏異宜，膳羞之和，鼎飪殊節，一辰三朝，稱情猶簡，終日承顏，在理斯愜，且長寿之對，撫循無已，馳道未窮，顧懷不輟，豈直下動天至，固亦上結慈衷，自頃半旬乃朝，遂為通製，事逾信次，義乖晨省，一日萬機，不敢三尘御省，每旦改宿，特乞一至寢門。","sortOrder":50},
  {"id":"s_work_nvlt_16_51","chapterId":"ch_work_nvlt_16","text":"梁沈約為皇太子謝初表曰：臣實蒙稚，溫文以闕，不閒三善之訓，未習四學之議，唯問安內竖，因心自發，而親膳寢門，未任再至，乃降皇慈，夙膺盛典，貳體宸極，守器宗祧，顧循幼志，如臨冰壑。","sortOrder":51},
  {"id":"s_work_nvlt_16_52","chapterId":"ch_work_nvlt_16","text":"梁萧子范求撰昭明太子集表曰：臣聞姬旦雲亡，播禮樂於百代，宣尼既殁，傳雅頌於千祀，夏啟之風，載傳樂野，周晉之跡，止在洛濱，入侍四公，西京見美，長寿一察，東漢流名，魏击之悟箧衣，事關戰國，孫登之愛田苗，義屬偏霸，各稱小善，靡擅雕虫，子桓雖詩賦可嘉，規范頓闕，貽譏良史，取誚前載，備而為論，佥奧允歸，自少陽潛位，震方滅采，神儀長往，銅龍毀構，音顏緬邈，舟壑遷移，若乃緣情體物，繁絃縟錦，縱橫艳思，籠蓋辭林，積練累素，盈車滿笈，金石有銷，斯文方遠，既異陳王之躬撰。又非當陽之自集，臣蝉翼輕身，未從尘露，而班输嚴駕，永輟騑驂，恋主懷茲，伏深涕慕，冒乞铨次遺藻，勒成卷軸。","sortOrder":52},
  {"id":"s_work_nvlt_16_53","chapterId":"ch_work_nvlt_16","text":"梁陆倕為豫章王慶太子出宮表曰：臣聞周固本枝，寔資明兩，漢啟盤石，必系元良，所以闡弘祚鼎，光崇守器，伏惟皇太子，道契生知，照均天縱，不藉審諭之功，無待溫文之辅，而冬書秋記，夙表睿資，春誦夏絃，幼彰神度，雖复直門守令，長寿察微，魏贊多容，漢稱宽博，不足以連辉茂則，疋景令圖，甲觀惟新，桂宮告始，朱班徙次，翠蓋移陰，華裔式瞻，人祇蹈舞。","sortOrder":53},
  {"id":"s_work_nvlt_16_54","chapterId":"ch_work_nvlt_16","text":"周王褒為百僚請立皇太子表曰：臣聞洊雷居震，春方應守器之禮，明兩作離，少陽纂重暉之業，是以三善昭德，載祀之祚克隆，一人元良，貞國之基永固，至於軒轅得姓，高陽才子，上嗣佇賢，前星虛位，魯國公臣贇，親居元子，屬當储貳，具僚仰則，列辟式瞻，臣等參議，請立為皇太子，事隆監撫，教資審諭，問安寢門，视膳天幄。","sortOrder":54},
  {"id":"s_work_nvlt_16_55","chapterId":"ch_work_nvlt_16","text":"周庾信慶傳位於皇太子表曰：昔者降居若水，登庸有優劣之殊，來朝櫟陽，繼體有君臣之異，不得與夫天之兩日，一日之再中，併曜聯辉，重明之双照，同年而語矣，欲令百工相和，先聞揖讓之風，天下無為，早識吾君之子，皇帝藐然姑射，正當乘雲馭龍，問道崆峒，豈复先秋木落。","sortOrder":55},
  {"id":"s_work_nvlt_16_56","chapterId":"ch_work_nvlt_16","text":"◇太子妃","sortOrder":56},
  {"id":"s_work_nvlt_16_57","chapterId":"ch_work_nvlt_16","text":"《漢書》曰：漢景薄皇後，孝文薄太後家女也，景帝為太子時，太後為太子取以為妃。","sortOrder":57},
  {"id":"s_work_nvlt_16_58","chapterId":"ch_work_nvlt_16","text":"又曰：武帝陳皇後，長公主嫖女也，初武帝得立為太子，公主有力焉，故欲以女納太子。","sortOrder":58},
  {"id":"s_work_nvlt_16_59","chapterId":"ch_work_nvlt_16","text":"又曰：武［《太平御覽》一百四十九作孝。］成許皇後，平恩侯嘉女也，元帝選配太子，上令中常侍黃門親近者侍送，還白帝，稱太子欣悅，元帝喜，謂左右曰：酌酒贺我，左右皆稱萬歲。","sortOrder":59},
  {"id":"s_work_nvlt_16_60","chapterId":"ch_work_nvlt_16","text":"《漢武故事》曰：初，武帝為太子時，長公主欲以女配帝，時帝尚小，長公主指女問帝曰：得阿娇好不，帝曰：若得阿娇，以金屋貯之，主大喜，乃以配帝，是曰陳皇後，阿娇，後字也。","sortOrder":60},
  {"id":"s_work_nvlt_16_61","chapterId":"ch_work_nvlt_16","text":"王隱《晉書》曰：武帝欲為太子取妃，久而不决，上欲娶衛瓘女，楊後欲娶贾充女，上曰：衛公女有五可，贾公女有五不可，衛家种賢而多子，端正而長白，贾家种妒而少子，丑而短黑，楊後既納寶物，固欲娶贾氏，因乃納之。","sortOrder":61},
  {"id":"s_work_nvlt_16_62","chapterId":"ch_work_nvlt_16","text":"又曰：愍懷太子妃，王衍女也，劉曜等入洛，盡將諸後妃去，妃獨拔刀向賊曰：我司徒公女，皇太子妃，死則已，終不為賊婦，賊害之。","sortOrder":62},
  {"id":"s_work_nvlt_16_63","chapterId":"ch_work_nvlt_16","text":"晉孝武起居註曰：上臨軒，設懸而不樂，遣兼司空謝琰，納太子妃王氏，賜文武布絹，百官詣上東門上禮。","sortOrder":63},
  {"id":"s_work_nvlt_16_64","chapterId":"ch_work_nvlt_16","text":"甲辰儀曰：皇太子妃公主夫人，逢持節使者高車使者，住車相揖。","sortOrder":64},
  {"id":"s_work_nvlt_16_65","chapterId":"ch_work_nvlt_16","text":"《東宮舊事》曰：皇太子妃，給織成袞帶，白玉佩，四望車，羽葆，前後部鼓吹各一部。","sortOrder":65},
  {"id":"s_work_nvlt_16_66","chapterId":"ch_work_nvlt_16","text":"又曰：太子納妃，有七采杯文綺被，長命杯，文綺袴。","sortOrder":66},
  {"id":"s_work_nvlt_16_67","chapterId":"ch_work_nvlt_16","text":"【哀策】宋謝莊皇太子妃哀策文曰：楹凝桂酒，庭肅龍辒，風吹國路，雲起郊門，皇帝傷總繸之掩采，悼副袆之滅華，行光既晏，長河又斜，顧而言曰：璇瑤有毀，鬱烈無湮，翦素裁簡，授之史臣，其辭曰：霍岫〈虛號〉天，灊流凝漢，祥發桐珪，慶昭金筭，毓景帝出，飛芳戚闬，秘儀施穀，升音集灌，月晷幾望，娣袂維良，釋帏春宮，承篚少陽，五葉衍藻，四訓抽光，葳蕤蕙振，婉娈琼相，清徽就遠，祲沴方搏，臨華罢翠，當晔收蘭，複殿生响，長庑結寒，節移虛饋，氣变容衣，中庭草薆，階上螢飛，傷榮里第，痛溢朝闈，霜侵燭昧，風密帷凄，驚葭夕轉，龍驂夜嘶，筵既訣兮奠既撤，背青闕兮去神閨，旌掩鬱而還泛，蓋逶遲而顧低。素紼〈佥殳〉維，華軿解馭，山〈土遂〉恒陰，松阿不曙，離天渥兮就銷沉，委白日兮即冥暮，菊有秀兮蘅有芬，德方遠兮聲弥树。","sortOrder":67},
  {"id":"s_work_nvlt_16_68","chapterId":"ch_work_nvlt_16","text":"齊王俭皇太子妃哀策文曰：肇惟初識，芳猷夙就，翩翻禮園，徘徊樂囿，视秋齊明，方春等茂，伊宋之季，天衢荐阻，咨我储貳，締緝江滸，衛女事齊，樊姬贊楚，美著嫔嗣，徽音踵武，數盈則反，否極斯昌，肅膺靈命，經緯三光，往儀衡馆，來式椒堂，紃組鹹事，象服有章，八演仰則，六幽望景，悠悠草昧，如何不永，方中委曜，先秋落穎，世有遺尘，庭無餘影，呜呼哀哉，遵三兆之嘉日，迨九筮之靈期，澄金波而映鑾旆，命飛廉而拂琼辎，扬清笳於漢表，動嘶挽於雲基。","sortOrder":68},
  {"id":"s_work_nvlt_16_69","chapterId":"ch_work_nvlt_16","text":"◇公主","sortOrder":69},
  {"id":"s_work_nvlt_16_70","chapterId":"ch_work_nvlt_16","text":"公羊傳曰：天子嫁女於諸侯，必使諸侯同姓者主之。","sortOrder":70},
  {"id":"s_work_nvlt_16_71","chapterId":"ch_work_nvlt_16","text":"《史記》曰：李斯長男由，為三川守，諸男皆尚秦公主，女悉嫁諸公子，由告歸鹹陽，斯置酒於家，百官長皆前為寿，門庭車騎以千數。","sortOrder":71},
  {"id":"s_work_nvlt_16_72","chapterId":"ch_work_nvlt_16","text":"《漢書》曰：周勃下廷尉，吏侵辱之，勃以千金與獄吏，乃書牍背示之曰：以公主為證，公主，孝文女也，勃子勝尚之，故獄吏教引為證。","sortOrder":72},
  {"id":"s_work_nvlt_16_73","chapterId":"ch_work_nvlt_16","text":"又曰：宣平侯張敖，尚惠帝姊魯元公主，有女，惠帝既立，呂太後欲為重親，以公主女配帝。","sortOrder":73},
  {"id":"s_work_nvlt_16_74","chapterId":"ch_work_nvlt_16","text":"又曰：孝武衛皇後，字子夫，為平陽主謳者，武帝即位數年，無子，過平陽主，既飲，謳者進，帝獨說子夫，帝起更衣，子夫侍尚衣軒中，得幸，還坐甚忻，賜平陽主金千斤，子夫上車，主拊其背曰：行矣，強飯勉之，即貴，原無相忘也。","sortOrder":74},
  {"id":"s_work_nvlt_16_75","chapterId":"ch_work_nvlt_16","text":"又曰：乌孫以馬千疋娉漢女，元封中，遣江都王建女細君為公主，以妻焉，賜乘舆服御物，為備官屬，侍御數百人，赠送甚盛，乌孫崑莫以為右夫人，公主至其國，自治宮室，歲時再過，崑莫年老，言語不通，公主悲愁，自為作歌，天子聞而怜之。","sortOrder":75},
  {"id":"s_work_nvlt_16_76","chapterId":"ch_work_nvlt_16","text":"范晔《後漢書》曰：製，皇女皆封縣公主，儀服同列侯，其尊崇者，加號長公主，儀服同蕃王，諸王皆封乡亭侯，公主儀服同乡亭侯。","sortOrder":76},
  {"id":"s_work_nvlt_16_77","chapterId":"ch_work_nvlt_16","text":"又曰：光武姊湖陽公主，新寡，帝與共論朝臣，微觀其意，公主曰：宋公威容德器，群臣莫及，帝曰：方且圖之，後宋弘被引見，帝令公主坐屏風後，因謂弘曰：喭言貴易交，富易妻，人情乎，弘曰：臣聞貧賤之知不可忘，糟糠之妻不下堂，帝顧謂主曰：事不諧矣。","sortOrder":77},
  {"id":"s_work_nvlt_16_78","chapterId":"ch_work_nvlt_16","text":"又曰：董宣為洛陽令，湖陽公主蒼頭，白日殺人，因匿主家，吏不能得，及主出行，而以奴驂乘，宣於夏門亭候之，乃駐車叩馬，以刀畫地大言數主之失，叱奴下車，因格煞之，主即還宮訴帝，帝大怒，召宣，欲箠煞，宣叩頭曰：原乞一言而死，帝曰：欲何言，宣曰：陛下聖德中興，而縱奴煞良民，將何以治天下乎，臣不須箠，請得自殺，即以頭击楹，流血被面，帝令小黃門持之，使宣叩頭謝主，宣不從，帝強使頓之，宣兩手據地，終不肯俯，主曰：文叔為白衣時，藏亡匿死，吏不敢至門，今為天子，威不能行一令乎，帝大笑曰：天子不與白衣同。","sortOrder":78},
  {"id":"s_work_nvlt_16_79","chapterId":"ch_work_nvlt_16","text":"又曰：窦融長子穆，尚內黃公主，子勋，尚東海王強女比［後漢書五十三窦融傳作泚，王氏集解雲，當作沘。］陽公主。又子固，亦尚世祖女沮陽公主，窦氏一公兩侯三公主，親戚功臣中莫與為比。","sortOrder":79},
  {"id":"s_work_nvlt_16_80","chapterId":"ch_work_nvlt_16","text":"又曰：馆陶公主為子求郎，明帝不許，而賜錢千萬，謂群臣曰：郎官上應列宿，出宰百里，苟非其人，則民受其殃，是以難之矣。","sortOrder":80},
  {"id":"s_work_nvlt_16_81","chapterId":"ch_work_nvlt_16","text":"魏末傳曰：何晏婦金乡公主，即晏同母妹，公主賢明，謂其母沛王太妃曰：晏為惡日甚，將不保身，母笑曰：汝得無妒晏耶，俄而晏死，有一男，年五六歲，宣王遣人錄之，晏婦藏其子王宮中，向使者搏頰，乞所活之，使者具以白宣王，宣王亦聞晏婦有先見之言，心常嘉之，且為沛王故，特原不煞。","sortOrder":81},
  {"id":"s_work_nvlt_16_82","chapterId":"ch_work_nvlt_16","text":"《晉中興書》曰：臨海公主，惠帝弟四女，羊皇後所生，初封清河公主，未出適，值永嘉亂，□［《太平御覽》一百五十二作傳。］賣長城民錢溫，溫以送女，女遇主甚酷，主自告吳興太守周禮［按晉書三十一贾後傳，此事在建興中，據晉書五十八周札傳，札時正為吳興內史，禮當是札字之訛。］以聞，於是殺溫及女，適谯國曹統。","sortOrder":82},
  {"id":"s_work_nvlt_16_83","chapterId":"ch_work_nvlt_16","text":"臧榮緒《晉書》曰：贾後二女，宣華女彦，封宣華弘農郡公主，女彦年八歲，聰明歧嶷，便能書學，諷誦詩論，病困，贾後欲議封女以長公主，彦語後曰：我尚小，未及成人，禮不用公主，及薨，謚哀獻皇女，以長公主禮葬送。","sortOrder":83},
  {"id":"s_work_nvlt_16_84","chapterId":"ch_work_nvlt_16","text":"《列仙傳》曰：朱仲，會稽販珠人也，高後時，獻三寸珠，魯元公主私以七百金，從仲求珠，仲獻珠四寸，［事具寶部。］","sortOrder":84},
  {"id":"s_work_nvlt_16_85","chapterId":"ch_work_nvlt_16","text":"【碑】魏溫子昇常山公主碑曰：啟泰微之層構，辟閶阖之重扉，據天下以為家，苞率土而光宅，然則崑山西跱，爰有夜光，漢水東流，是生明月，公主禀靈宸極，資和天地，芬芳有性，溫润成质，自然秘遠，若上元之隔絳河，直置清高，類姮娥之依桂树，令淑之至，比光明於宵燭，幽間之盛，匹秾華於桃李，讬體宮闈，而執心捴順，婉然左辟，率禮如賓，舉華燭以宵征，動鳴佩而晨去，致肅雍於車乘，成好合於琴瑟，立行絜於清冰，抗志高於黃鵠，停輪表信，阖門示禮，終能成其子姓，貽厥孫謀，而鍾漏相催，日夜不息，川有急流，風無靜树，奄辭身世，從宓妃於伊洛，遽捐馆舍，追帝子於瀟湘，銘曰：龍辔莫援，日車遂往，奄離形神，忽歸丘壤，祖歌薤露，出奏巫山，永厝中野，終掩窮泉，萧瑟神道，荒涼墓田，松槚徒列，琬琰空傳。","sortOrder":85},
  {"id":"s_work_nvlt_16_86","chapterId":"ch_work_nvlt_16","text":"【墓志】宋謝莊豫章長公主墓志銘曰：禀中枢之照，體星軒之華，肅恭在國，掖庭钦其風，恪勤衡馆，庶族仰其德，神葉靈條，爰自帝尧，文信啟魯，肇京於楚，宵燭載照，娥英是從，婉娩絺绤，優柔肅雍，蘅蕙有寶，金碧不居，泉庭一夜，里馆長芜。","sortOrder":86},
  {"id":"s_work_nvlt_16_87","chapterId":"ch_work_nvlt_16","text":"齊王融永嘉長公主墓志銘曰：作儀阿媛，取俪漢妃，相金漏质，秾李慚暉，肅穆婦容，靜恭女德，顧史求箴，披圖問則，慶善鬱夷，與仁冥默，宵燧亡明，晓挽已聲，松門嚴闊，泉帳寒清，悠哉白日，鬱彼佳城。","sortOrder":87},
  {"id":"s_work_nvlt_16_88","chapterId":"ch_work_nvlt_16","text":"齊謝朓臨海公主墓志銘曰：長發有祥，瑤台乃構，玄鳥歸飛，北音斯奏，聿來徐土，禎符爰授，帝體靈柯，秾華以秀，飾馆東魯，言歸景族，有教公宮，無系車服，既肅簪珥，亦崇湯沐，率禮衡門，降情雲屋，彼月斯望，在釣維缗，瞻須配景，望燭齊神，霾華崑岫，滅采上春，慈纏雲陛，悲動外姻，鬱彼崇芒，睠然城輦，辎翟按辔，龍旒徐轉。","sortOrder":88},
  {"id":"s_work_nvlt_16_89","chapterId":"ch_work_nvlt_16","text":"又新安長公主墓志銘曰：氛氲長發，時惟睿文，誕茲明淑，玉振蘭芬，譽宣女師，德侔高行，肅穆嫔風，優遊阃正，撫事成箴，臨圖作鏡，如何冥默，方春委盛。","sortOrder":89},
  {"id":"s_work_nvlt_16_90","chapterId":"ch_work_nvlt_16","text":"【诔】魏陳王曹植平原懿公主诔曰：俯振地紀，仰错天文，悲風激興，霜飆雪雰，凋蘭犮蕙，良幹以泯，於惟懿主，瑛瑤其质，协策應期，含英秀出，岐嶷之姿，寔朗貴，［《初學記》十作寔朗寔一，此有脱訛。］生在十旬，察人識物，儀同聖表，聲协音律，驤眉識往，俯瞳知來，求顏必笑，和音則孩，阿保接手，侍御充傍，常在襁抱，不停笫床，专愛一宮，取玩聖皇，何圖奄忽，罹天之殃，魂神遷移，精爽翾翔，號之不應，聽之莫聆，帝用於嗟，呜呼［《初學記》十作咽。］失聲，呜呼哀哉，怜爾早殁，不逮陰光，改封大郡，惟帝舊疆，建土开家，邑移蕃王，绲珮惟鮮，朱绂斯煌，國號既崇，哀爾孤獨，配爾名子，華宗貴族，爵以列侯，銀艾優渥，成禮於宮，靈轜交轂，生雖異室，殁同山嶽，爰構玄宮，玉石交連。朱房晧壁，暠曜電鮮，飾終備衛，法生象存，長埏繕脩，神閨掩扉，二柩併降，双魂孰依，人誰不殁，怜爾尚微，阿保激摧，聖上傷悲，城闕之詩，以日喻歲，况我愛子，神光長滅，扃關一阖，曷其复晢。","sortOrder":90},
  {"id":"s_work_nvlt_16_91","chapterId":"ch_work_nvlt_16","text":"晉潘嶽南陽長公主诔曰：昔唐女嫔妫，書叙釐降之美，周姬適齊，詩詠肅雍之歌，漢之新野，以節義垂號千載，伊晉之獻主，以聰明叡智，考終定謚，茲可謂母儀純備，邁蹤古烈者已，惜乎不永，背世湮沉，爰讬素旂，式章徽音，主之誕育，既慕洪胄，德之休明，亦固天授，思心婉娈，淑质純茂，母儀不忒，內則靡疚，肇自弱笄，有馥其芬，言告言歸，作合於荀，在貴思降，處逸能勤，上虔諸姑，傍接支嫔，內諧閨閾，外和族姻，終溫且惠，淑慎其身，積善餘慶，啟茲名胤，厲以惠肅，誨以柔順，主實體化，不言而信，二子遵式，匪嚴而峻，於穆獻後，奕代熙盛，重作大司，黎牧火正，國之仁姑，家之慈母，天道辅賢，宜享遐寿，如何短命，曾不華首，寢疾弗興，繁榮摧朽，呜呼哀哉，容車戒路，祖奠在庭，騑驂踌躇，服馬悲鳴，皇舆親臨，望旗失聲，列辟鹹起，洒淚霑纓，呜呼哀哉，既次墓門，降柩升輴，靈衣從風，素幕生尘，明燎守夜，竦紼俟晨，噭々遺嗣，豭豭孤臣，號無废音，涕不輟中。又皇女诔曰：厥初在鞠，玉质華繁，玄發儵曜，蛾眉連娟，清顱橫流，明眸朗鮮，迎時夙智，望歲能言，亦既免懷，提携紫庭，聰惠機警，授色應聲，亹亹其進，好曰之經，辭合容止，閒於幼齡，猗猗春蘭，柔條含芳，落英彫矣，從風飄颺，妙妙弱媛，窈窕淑良，孰是人斯，而離斯殃，靈殯既祖，次此暴庐，披覽遺物，徘徊舊居，手泽未改，領腻如初，孤魂遐逝，存亡永殊，呜呼哀哉。","sortOrder":91},
  {"id":"s_work_nvlt_16_92","chapterId":"ch_work_nvlt_16","text":"晉左九嫔萬年公主诔曰：昔滿［疑當作蒲。］衣早智，周晉夙成，鹹以岐嶷，名存典經，猗欤公主，在幼克哲，方德比齒，有邈先烈，何德之盛，而年或闕，何華之繁，而實不結，雨墜風逝，形影長滅，赫赫京室，河洛所經，陰精發曜，降茲淑靈，篤生公主，誕膺休禎，秀生紫微，日暉月明，既睇艳姿，徽音孔昭，盼蒨其媚，婉曼其娇，寵玩軒陛，如琼如瑤，雖則弱齒，双德兼苞，五福所集，聞之先民，積善鍾慶，祜德辅仁，宜終淑美，光暉日新，雲何降戾，景命不振，晔晔榮曜，英蕤始芳，何辜於天，猥遇降霜，豭豭稚魂，飄飖遐翔，於戲何辜，痛茲不福，生而何晚，殁而何速，酷矣皇靈，谬哉司祿，呜呼哀哉，日月載馳，白露凝結，自主薨徂，奄離時節，吉凶乖邈，存亡異製，將遷幽都，潛神永翳，呜呼公主，魂豈是綏，岌岌靈轜，駿驷騑騑，挽僮齊唱，悲音激摧，士女歔欷，高風增哀，一日不見，采萧作歌，况我公主，形滅體訛，精靈遷逝，幽此中阿，言思言念，涕淚滂沱，呜呼哀哉。","sortOrder":92},
  {"id":"s_work_nvlt_16_93","chapterId":"ch_work_nvlt_16","text":"【表】宋江斅當尚世祖女表讓婚［據宋書四十一，孝武王皇後傳，乃劉駿使人為斅作。］曰：伏承詔旨，當以臨海公主降嫔，榮出望表，恩加典外，顧審輶蔽，跪處忧遑，臣寒門悴族，人凡质陋，闾阎有對，本隔天姻，年近將冠，皆已有室，荆釵布裙，足得成禮，自晉氏以來，配尚王姬者，雖累經美胄，亟有名才，至如王敦慑氣，桓溫斂跡，王偃無仲都之质，而祼雪於北階，何瑀闕龍工之姿，而見投於深井，謝莊殆自同於矇瞍，殷仲幾不免於強鋤，製勒甚於仆隸，防閒過於婢妾，行來出入，人理之常，當待賓客，朋從之義，而令扫轍息駕，無窥門之期，废筵抽席，絕接對之理，非惟交友離異，仍乃兄弟疏闊，姆妳爭媚，相勸以急，尼媪競說，相諂以嚴，其間又有應答問訊，止［宋書作卜。］巫師母，乃至殘餘飲食，詰辨與誰，衣被故弊，必责顯［宋書作頭。］領，或進不獲前，或入不聽出，不入則嫌於欲疏，求出則疑於有別意，召必以三更為期，遣必以日出為限，夕不見晚魄，朝不識曙星，至於夜步月而弄琴，晝拱袂而被［宋書作披。］卷，一生之內，與此乖矣。又聲影表聞，則少婢奔迸，裾袂向席，而丑老藂來，左右整刷，以疑寵見嫌，賓客未冠，以小［宋書作少］，容致斥，如臣門介，［宋書作分。］代荷殊榮，足定家聲，便預提拂，青宮美官，或由才升，一切婚戚，鹹成恩侵，是以仰冒非宜，披露丹款，非唯上陳一己，規全身原，寔乃廣申諸門，受患之切，若恩詔難降，扱請不申，便當刑膚翦發，投山竄海。","sortOrder":93},
  {"id":"s_work_nvlt_16_94","chapterId":"ch_work_nvlt_16","text":"《藝文類聚》　唐·欧陽詢","sortOrder":94},
  {"id":"s_work_nvlt_17_1","chapterId":"ch_work_nvlt_17","text":"卷十七人部一","sortOrder":1},
  {"id":"s_work_nvlt_17_2","chapterId":"ch_work_nvlt_17","text":"○頭目耳口舌發髑髏胆","sortOrder":2},
  {"id":"s_work_nvlt_17_4","chapterId":"ch_work_nvlt_17","text":"《說文》曰：首，頭也。","sortOrder":4},
  {"id":"s_work_nvlt_17_5","chapterId":"ch_work_nvlt_17","text":"《釋名》曰：頭，獨也，體高而獨也，首，始也。","sortOrder":5},
  {"id":"s_work_nvlt_17_6","chapterId":"ch_work_nvlt_17","text":"《黃帝素問》曰：頭者精明之主也。","sortOrder":6},
  {"id":"s_work_nvlt_17_7","chapterId":"ch_work_nvlt_17","text":"《易說卦》曰：乾為首。","sortOrder":7},
  {"id":"s_work_nvlt_17_8","chapterId":"ch_work_nvlt_17","text":"《毛詩》曰：螓首蛾眉。","sortOrder":8},
  {"id":"s_work_nvlt_17_9","chapterId":"ch_work_nvlt_17","text":"《禮斗威儀》曰：君乘火而王，其民銳頭，君乘水而王，其民大頭。","sortOrder":9},
  {"id":"s_work_nvlt_17_10","chapterId":"ch_work_nvlt_17","text":"《春秋元命苞》曰：頭者，神所居，上圓象天。","sortOrder":10},
  {"id":"s_work_nvlt_17_11","chapterId":"ch_work_nvlt_17","text":"《晏子》曰：湯長頭而髯鬢。","sortOrder":11},
  {"id":"s_work_nvlt_17_12","chapterId":"ch_work_nvlt_17","text":"《史記》曰：蔺相如為趙使秦，持璧却立倚柱，謂秦王曰：趙王斋戒五日，使臣奉璧，今大王見臣，禮節甚倨，得璧傳之美人以戲弄，故臣复取璧，大王必欲急臣，臣頭今與璧俱碎於柱矣。","sortOrder":12},
  {"id":"s_work_nvlt_17_13","chapterId":"ch_work_nvlt_17","text":"《漢書》曰：陳遵長八尺餘，長頭大鼻，容貌甚伟。","sortOrder":13},
  {"id":"s_work_nvlt_17_14","chapterId":"ch_work_nvlt_17","text":"帝系譜曰：神農牛首，結繩而治，伏羲人頭蛇身。","sortOrder":14},
  {"id":"s_work_nvlt_17_15","chapterId":"ch_work_nvlt_17","text":"嚴尤三將叙曰：趙孝成王曰：誰能當武安君，平原君曰：渑池之會，臣察武安君，小頭而銳，瞳子白黑分明，视瞻不轉，小頭而銳，斷敢行也，目黑白分，見事明也，视瞻不轉，執志強也，可與持久，難與爭鋒，廉頗足以當之。","sortOrder":15},
  {"id":"s_work_nvlt_17_16","chapterId":"ch_work_nvlt_17","text":"《東觀漢記》曰：彭寵與吳漢围隗嚣於西城，敕彭書曰：西城若下，便可將兵南击蜀虜，人苦不知足，既平隴，重望蜀，每一發兵，頭鬢為白。","sortOrder":16},
  {"id":"s_work_nvlt_17_17","chapterId":"ch_work_nvlt_17","text":"《魏志》曰：辰韓國兒生，以石押其頭，欲其扁扁，今辰韓人皆扁頭。","sortOrder":17},
  {"id":"s_work_nvlt_17_18","chapterId":"ch_work_nvlt_17","text":"《搜神記》曰：南方有落［《太平御覽》三百六十四落下有頭字。］民，吳時，將軍朱桓一婢，每夜臥後，頭辄飛去，或從狗窦，或從天窗中出入，以耳為翼，將晓复還，數數如此，傍人怪之，夜照视，唯有身無頭，其體微冷，乃蒙之以被，至晓頭還，礙被不得安，再三墮地，而其體氣急疾，若將死者，乃去被，頭复起附，得安，复瞑如常人。","sortOrder":18},
  {"id":"s_work_nvlt_17_19","chapterId":"ch_work_nvlt_17","text":"《神仙傳》曰：曹公捕左慈，數日得之，便斷頭，以白曹公，公大喜曰：果慈頭，定视，是一束茅爾。","sortOrder":19},
  {"id":"s_work_nvlt_17_20","chapterId":"ch_work_nvlt_17","text":"洞林曰：郭璞為左尉周恭卜雲，君且墮馬傷頭，尉後乘馬行，黃昏，坂下犢車觸馬，馬驚，頭打石上，流血殆死。","sortOrder":20},
  {"id":"s_work_nvlt_17_21","chapterId":"ch_work_nvlt_17","text":"《秦記》曰：符堅祖洪，見堅状濬，欲令頭堅腹软，字之曰堅頭。","sortOrder":21},
  {"id":"s_work_nvlt_17_22","chapterId":"ch_work_nvlt_17","text":"《幽明錄》曰：河東贾弼之，義熙中，為琅琊府參軍，夜夢有一人，面查靤［防老反。］甚，多鬢大鼻〈目閒〉目，請之曰：愛君之濬，欲易頭，可乎，乃於夢中許易，明朝起，自不覺，而人悉驚走藏，雲那漢何處來，弼取鏡自看，方知怪異，因還家，家人悉驚，入內，婦女走藏，雲那得男子，弼坐自陳說，後能半面笑，兩足手口各捉一筆，俱書，辭意皆美，此為異也，餘併如先。","sortOrder":22},
  {"id":"s_work_nvlt_17_23","chapterId":"ch_work_nvlt_17","text":"【文】晉張敏頭责子羽文曰：太原溫長仁，潁川荀景伯，范陽張茂先，上郡劉文生，南陽邹润甫，河南鄭冽，［據下及世說排調篇，當是鄭詡，詡字思淵，淵字坏作冽。又脱思字。］餘友有秦生者，雖有姊夫之尊，少而狎之，同時昵好張荀之徒，繼踵登朝，而此賢身處陋巷，屢沽而無善价，為之慨然。又怪諸賢身己既在位，曾無伐木嘤鳴之聲。又违王貢彈冠之義，故因秦生容貌之盛，為頭责之文以戲之，併嘲六子，頭责子羽曰：吾讬為子頭，萬有餘日矣，大塊禀我以精，造我以形，我為子蒔發膚，置鼻耳，安眉須，捶牙齒，眸子摛光，双權隆起，每至出入人間，遨遊市里，行者僻易，坐者竦跽，如此者故我形之足伟也，子冠冕弗戴，金銀弗佩，旨味弗嘗，食粟茹菜，子遇我如讎，我视子如仇，居常不樂，兩者俱忧，何其鄙哉，子欲為仁賢耶，當如皋陶後稷巫鹹伊陟，保乂王家，永見封殖，子欲為名高耶，則當如許由子臧卞隨務光，洗耳逃祿，千載流芳，子欲為遊說耶，則當如陳軫蒯通陆生邓公，轉禍為福，含辭從容，子欲為恬淡耶，則當如老聃之守一，莊周之自逸，廓然離俗，志凌雲日，子欲為隱遯耶，則當如榮期之帶索，漁父之儳灂，栖遲神丘，垂餌巨壑，今子上不希道德，中不效儒墨，塊然窮賤，守此愚惑，察子之情，觀子之志，退不能為處士，進無望乎三事，而徒玩日勞形，習為常人之所喜，對曰：吾以天幸，為子所寄，今子欲使吾為忠耶，則當如子胥屈平，欲使吾為信耶，則當殺身而成名，欲使吾為介節耶，赴水火以全貞，此四者，子之所忌，故吾不敢造意，頭曰：吾欲告苶菀匝慓裕曶澶］以優遊，而與虮蝨同性，不聽我謀，悲哉，俱御人體，而獨為子頭，且擬人其倫，諭子儕偶，子曾不如太原溫顒，潁川荀禹，［世說作宇。］范陽張華，上郡劉許，南陽邹湛，河南鄭詡，此數子或謇吃無宮，［宮下有商字，此脱。］或尫陋希言語，或淹伊多姿態，或驒騱［上阤，下奚。］少智谞，或口如含膠飴，或頭如巾齏杵，而猶以文采可觀，意思詳序，攀龍附鳳，併登天府，豈若夫子，徒令唇口腐烂，手足霑濡哉，居有事之世，而恥為權謀，譬猶凿地抱瓮，難以求富，嗟乎子羽，何異牢槛之熊，深阱之虎，石間饿蟹，竈中之鼠，事力雖多，而見功甚少，宜其蹉跼煎蹙，至老無所希也。","sortOrder":23},
  {"id":"s_work_nvlt_17_25","chapterId":"ch_work_nvlt_17","text":"《易說卦》曰：離為目。","sortOrder":25},
  {"id":"s_work_nvlt_17_26","chapterId":"ch_work_nvlt_17","text":"《山海經》曰：一臂國，為人一目，中其面而居。","sortOrder":26},
  {"id":"s_work_nvlt_17_27","chapterId":"ch_work_nvlt_17","text":"《毛詩》曰：美目盼兮。","sortOrder":27},
  {"id":"s_work_nvlt_17_28","chapterId":"ch_work_nvlt_17","text":"《左傳》曰：宋華父督，見孔父之妻，目逆而送之。","sortOrder":28},
  {"id":"s_work_nvlt_17_29","chapterId":"ch_work_nvlt_17","text":"又曰：睅其目，皤其腹，［事具謳謠篇。］","sortOrder":29},
  {"id":"s_work_nvlt_17_30","chapterId":"ch_work_nvlt_17","text":"《春秋孔演圖》曰：蒼頡四目，是謂併明。","sortOrder":30},
  {"id":"s_work_nvlt_17_31","chapterId":"ch_work_nvlt_17","text":"又舜重瞳子，是謂重明。","sortOrder":31},
  {"id":"s_work_nvlt_17_32","chapterId":"ch_work_nvlt_17","text":"《孫卿子》曰：尧舜三眸子。","sortOrder":32},
  {"id":"s_work_nvlt_17_33","chapterId":"ch_work_nvlt_17","text":"《孝經援神契》曰：伏犧大目。","sortOrder":33},
  {"id":"s_work_nvlt_17_34","chapterId":"ch_work_nvlt_17","text":"《老子》曰：五色令人目盲。","sortOrder":34},
  {"id":"s_work_nvlt_17_35","chapterId":"ch_work_nvlt_17","text":"胡非子曰：目見百步之外，而不能見其眦。","sortOrder":35},
  {"id":"s_work_nvlt_17_36","chapterId":"ch_work_nvlt_17","text":"《莊子》曰：溫伯雪適齊，舍於魯，仲尼見之而不言，子路問焉，仲尼曰：若夫人者，目击而道存矣。","sortOrder":36},
  {"id":"s_work_nvlt_17_37","chapterId":"ch_work_nvlt_17","text":"又曰：孔子見老聃而語仁義，老聃曰：夫播糠眯目，則天地四方易位矣，夫仁義翻然，乃愦吾心，亂莫大焉。","sortOrder":37},
  {"id":"s_work_nvlt_17_38","chapterId":"ch_work_nvlt_17","text":"《孟子》曰：伯夷目不视惡色。","sortOrder":38},
  {"id":"s_work_nvlt_17_39","chapterId":"ch_work_nvlt_17","text":"《慎子》曰：離朱之明，察毫末於百步之外，下水尺，不能見淺深，非目不明，其势難睹也。","sortOrder":39},
  {"id":"s_work_nvlt_17_40","chapterId":"ch_work_nvlt_17","text":"《尸子》曰：使目在足下，則不可以视，《楚辭》曰：娱光眇视目增波。","sortOrder":40},
  {"id":"s_work_nvlt_17_41","chapterId":"ch_work_nvlt_17","text":"又曰：蛾眉曼睩目騰光。","sortOrder":41},
  {"id":"s_work_nvlt_17_42","chapterId":"ch_work_nvlt_17","text":"又曰：帝子降兮北渚，目眇眇兮愁予。","sortOrder":42},
  {"id":"s_work_nvlt_17_43","chapterId":"ch_work_nvlt_17","text":"又曰：滿堂兮美人，忽獨與餘兮目成。","sortOrder":43},
  {"id":"s_work_nvlt_17_44","chapterId":"ch_work_nvlt_17","text":"《孫卿子》曰：厭目而视者，视一以為兩也。","sortOrder":44},
  {"id":"s_work_nvlt_17_45","chapterId":"ch_work_nvlt_17","text":"《韓子》曰：田驷欺邹君，邹君將殺之，田驷恐，告惠子，惠子見邹君曰：有人見君，則镴其一目，奚如，君曰：我必殺之，惠子曰：瞽镴兩目，君奚弗殺，驷東欺齊侯，南欺荆王，驷之於欺人瞽也，君奚怨，乃弗殺。","sortOrder":45},
  {"id":"s_work_nvlt_17_46","chapterId":"ch_work_nvlt_17","text":"《淮南子》曰：夫目察秋毫之末，而耳不聞雷霆之音，耳調玉石之聲，而目不見太山之高，何則，小有所志，而大有所忘也。","sortOrder":46},
  {"id":"s_work_nvlt_17_47","chapterId":"ch_work_nvlt_17","text":"《孔丛子》曰：夫子適周，見萇弘，言終退，萇弘語劉文公曰：吾觀仲尼，有聖人之表，其状河目而隆顙，是黃帝之形濬也，史記曰：吳王賜子胥屬鏤之劍以死，子胥仰天叹曰：抉吾眼，著吳東門上，以觀越寇之入滅吳也，乃自刭。","sortOrder":47},
  {"id":"s_work_nvlt_17_48","chapterId":"ch_work_nvlt_17","text":"《漢書》曰：東方朔上書，臣朔目若懸珠，齒如編貝。","sortOrder":48},
  {"id":"s_work_nvlt_17_49","chapterId":"ch_work_nvlt_17","text":"《東觀漢記》曰：馬援眉目如畫。","sortOrder":49},
  {"id":"s_work_nvlt_17_50","chapterId":"ch_work_nvlt_17","text":"鄭玄《別傳》曰：玄秀眉明目。","sortOrder":50},
  {"id":"s_work_nvlt_17_51","chapterId":"ch_work_nvlt_17","text":"《竹林七賢》論曰：王戎眸子洞彻，视日而眼明不虧。","sortOrder":51},
  {"id":"s_work_nvlt_17_52","chapterId":"ch_work_nvlt_17","text":"《瀨乡記》曰：老子大目。","sortOrder":52},
  {"id":"s_work_nvlt_17_53","chapterId":"ch_work_nvlt_17","text":"【詩】梁劉孝綽詠眼詩曰：含娇〈目曼〉已合，離怨動還开，欲知密中意，浮光逐笑回。","sortOrder":53},
  {"id":"s_work_nvlt_17_54","chapterId":"ch_work_nvlt_17","text":"【箴】宋謝惠連目箴曰：氣之清明，双眸善識，唯道是视，瞻彼正直。","sortOrder":54},
  {"id":"s_work_nvlt_17_55","chapterId":"ch_work_nvlt_17","text":"【銘】齊竟陵王萧子良眼銘曰：惟正是视，玄黃匪惑，非禮不觀，儀形是則，慎爾所觌，無愆斯德。","sortOrder":55},
  {"id":"s_work_nvlt_17_57","chapterId":"ch_work_nvlt_17","text":"《樊氏相法》曰：耳門不容麥，百歲。","sortOrder":57},
  {"id":"s_work_nvlt_17_58","chapterId":"ch_work_nvlt_17","text":"《相書》曰：耳門小，富而吝。","sortOrder":58},
  {"id":"s_work_nvlt_17_59","chapterId":"ch_work_nvlt_17","text":"《淮南子》曰：禹耳三漏，是謂大通，興利除害，决江疏河。","sortOrder":59},
  {"id":"s_work_nvlt_17_60","chapterId":"ch_work_nvlt_17","text":"《老子》曰：五音令人耳聋。","sortOrder":60},
  {"id":"s_work_nvlt_17_61","chapterId":"ch_work_nvlt_17","text":"《孟子》曰：伯夷耳不聽惡聲。","sortOrder":61},
  {"id":"s_work_nvlt_17_62","chapterId":"ch_work_nvlt_17","text":"《史記》曰：韓信使人言於漢王，齊反覆之國，不為假王镇之，其势不定，漢王大怒，張良陳平，躡漢王之足，附耳語曰：漢方不利，寧能禁信王乎，因立之。","sortOrder":62},
  {"id":"s_work_nvlt_17_63","chapterId":"ch_work_nvlt_17","text":"范晔《後漢書》曰：珠崖儋耳，其渠帥耳垂肩三寸。","sortOrder":63},
  {"id":"s_work_nvlt_17_64","chapterId":"ch_work_nvlt_17","text":"《列仙傳》曰：務光，夏時人，耳長七寸，陽都女，耳細而長，眾皆言此天人也。","sortOrder":64},
  {"id":"s_work_nvlt_17_65","chapterId":"ch_work_nvlt_17","text":"《列士傳》曰：燕丹使田光往候荆軻，值其醉，唾其耳中，軻覺曰：此出口入耳之言，必大事也，則往見光。","sortOrder":65},
  {"id":"s_work_nvlt_17_66","chapterId":"ch_work_nvlt_17","text":"《蜀志》曰：先主長七尺五寸，垂臂下膝，顧，自見其耳。","sortOrder":66},
  {"id":"s_work_nvlt_17_67","chapterId":"ch_work_nvlt_17","text":"《英雄記》曰：曹公擒呂布，布顧劉備曰：玄德，卿為上坐客，我為降虜，繩縛我急，獨不可一言耶，操曰：縛虎不得不急，曹公欲缓之，備曰：不可，公不見布事丁建陽董太師乎，操憾［明本作頷，《太平御覽》三百六十六作領。］之，布目備曰：大耳兒最叵信。","sortOrder":67},
  {"id":"s_work_nvlt_17_68","chapterId":"ch_work_nvlt_17","text":"魏書，荀攸年七八歲，父衢曾醉，誤傷攸耳，而攸出入遊戲，常避護，不欲令衢見也，衢後聞之，乃驚，其夙智如此。","sortOrder":68},
  {"id":"s_work_nvlt_17_69","chapterId":"ch_work_nvlt_17","text":"《抱朴子》曰：老君耳長七寸。","sortOrder":69},
  {"id":"s_work_nvlt_17_70","chapterId":"ch_work_nvlt_17","text":"《瀨乡記》曰：老子耳有三門。","sortOrder":70},
  {"id":"s_work_nvlt_17_71","chapterId":"ch_work_nvlt_17","text":"《楚辭》曰：曾頰倚耳曲眉規。","sortOrder":71},
  {"id":"s_work_nvlt_17_72","chapterId":"ch_work_nvlt_17","text":"樊氏相法曰：人耳囷長寸三分，寿百二十歲，一寸，寿百歲，如豆，生即死耳，門前有仙人杖，四理一百歲，三理八十，二理六十。","sortOrder":72},
  {"id":"s_work_nvlt_17_73","chapterId":"ch_work_nvlt_17","text":"【賦】晉祖台之荀子耳賦曰：夫惡勞而希逸，寔萬物之至誠，何斯耳之不辰，讬荀子而宅形，在瘠土而長勤，無須臾之閒寧，預清談而閉塞，开鄙秽而聰明，竭微聽於門閣，采群下之風聲。","sortOrder":73},
  {"id":"s_work_nvlt_17_74","chapterId":"ch_work_nvlt_17","text":"【銘】齊竟陵王萧子良耳銘曰：惟耳是聽，仁愛是聞，詳察巧言，離辯異群，無迷邪諂，炫惑莫分。","sortOrder":74},
  {"id":"s_work_nvlt_17_76","chapterId":"ch_work_nvlt_17","text":"《易·說卦》曰：兑為口。","sortOrder":76},
  {"id":"s_work_nvlt_17_77","chapterId":"ch_work_nvlt_17","text":"《禮記》曰：數誚無為口容。","sortOrder":77},
  {"id":"s_work_nvlt_17_78","chapterId":"ch_work_nvlt_17","text":"又曰：口容止。","sortOrder":78},
  {"id":"s_work_nvlt_17_79","chapterId":"ch_work_nvlt_17","text":"又曰：負劍辟咡，詔之則掩口而對。","sortOrder":79},
  {"id":"s_work_nvlt_17_80","chapterId":"ch_work_nvlt_17","text":"又曰：趙文子，其言呐呐然，如不出諸其口。","sortOrder":80},
  {"id":"s_work_nvlt_17_81","chapterId":"ch_work_nvlt_17","text":"《孝經》曰：口無擇言。","sortOrder":81},
  {"id":"s_work_nvlt_17_82","chapterId":"ch_work_nvlt_17","text":"《孝經援神契》曰：舜大口。","sortOrder":82},
  {"id":"s_work_nvlt_17_83","chapterId":"ch_work_nvlt_17","text":"又曰：孔子海口含海，［《太平御覽》三百六十七作泽。］","sortOrder":83},
  {"id":"s_work_nvlt_17_84","chapterId":"ch_work_nvlt_17","text":"《老子》曰：五味令人口爽。","sortOrder":84},
  {"id":"s_work_nvlt_17_85","chapterId":"ch_work_nvlt_17","text":"《莊子》曰：公孫龍問於魏牟曰：吾聞莊子之言，芒焉異之，牟曰：子獨不聞坎井之蛙謂東海之鱉曰：坎井之樂，亦至矣，子奚不來入觀乎，鱉左足未入，而右膝已縶矣，公孫龍口呿而不合，舌舉而不下。","sortOrder":85},
  {"id":"s_work_nvlt_17_86","chapterId":"ch_work_nvlt_17","text":"《史記》曰：秦始皇遊於會稽，渡浙江，項梁與籍俱觀，籍曰：彼可取而代也，梁掩其口曰：無妄言，誅族矣。","sortOrder":86},
  {"id":"s_work_nvlt_17_87","chapterId":"ch_work_nvlt_17","text":"又曰：邓公見景帝曰：吳王為反數十年矣，發怒削地，以誅错為名，其意非在错也，且臣恐天下之士，噤口不敢复言。","sortOrder":87},
  {"id":"s_work_nvlt_17_88","chapterId":"ch_work_nvlt_17","text":"《鬼穀子》曰：口者機關也，所以开閉情意也。","sortOrder":88},
  {"id":"s_work_nvlt_17_89","chapterId":"ch_work_nvlt_17","text":"又曰：口可以食，不可以言。","sortOrder":89},
  {"id":"s_work_nvlt_17_90","chapterId":"ch_work_nvlt_17","text":"《說苑》曰：常枞有疾，《老子》曰：先生疾甚，無遺教語弟子乎，常枞乃張其口示《老子》曰：舌存乎，曰：存，豈非以软耶，齒亡乎，曰：亡，豈非以刚耶，常枞曰：天下事盡矣。","sortOrder":90},
  {"id":"s_work_nvlt_17_91","chapterId":"ch_work_nvlt_17","text":"又曰：惡言不過口，苛言不留耳，口者，關也，舌者，機也，出言不審，驷馬不能追也。","sortOrder":91},
  {"id":"s_work_nvlt_17_92","chapterId":"ch_work_nvlt_17","text":"《漢書》曰：漢王击魏豹，問郦食其曰：魏大將誰也，曰：柏直，漢王曰：是口尚乳臭。","sortOrder":92},
  {"id":"s_work_nvlt_17_93","chapterId":"ch_work_nvlt_17","text":"又曰：周昌曰：臣口不能言，心知其不可。","sortOrder":93},
  {"id":"s_work_nvlt_17_94","chapterId":"ch_work_nvlt_17","text":"又曰：楊雄口吃，不能戲談。","sortOrder":94},
  {"id":"s_work_nvlt_17_95","chapterId":"ch_work_nvlt_17","text":"應劭《漢官》曰：侍中刁存，年老口臭，帝賜雞舌香，令含之。","sortOrder":95},
  {"id":"s_work_nvlt_17_96","chapterId":"ch_work_nvlt_17","text":"杜恕《體論》曰：束脩之業，其上在於不言，其次莫如寡知也，故諺曰：使口如鼻，至老不失。","sortOrder":96},
  {"id":"s_work_nvlt_17_97","chapterId":"ch_work_nvlt_17","text":"《養生經》曰：軍營之中有甘泉，［軍營，口也，甘泉，唾也。］","sortOrder":97},
  {"id":"s_work_nvlt_17_98","chapterId":"ch_work_nvlt_17","text":"養生要尹氏內解曰：口為華池。","sortOrder":98},
  {"id":"s_work_nvlt_17_99","chapterId":"ch_work_nvlt_17","text":"《相書》曰：欲知人多口舌，當视其口如鳥喙，言語皆聚此多舌人也。","sortOrder":99},
  {"id":"s_work_nvlt_17_100","chapterId":"ch_work_nvlt_17","text":"《相書雜要》曰：口大容手，赤如朱丹，貴且寿。","sortOrder":100},
  {"id":"s_work_nvlt_17_101","chapterId":"ch_work_nvlt_17","text":"《瀨乡記》曰：老子方口。","sortOrder":101},
  {"id":"s_work_nvlt_17_102","chapterId":"ch_work_nvlt_17","text":"《吳錄》曰：孫權方颐大口，目有精光。","sortOrder":102},
  {"id":"s_work_nvlt_17_103","chapterId":"ch_work_nvlt_17","text":"【箴】宋謝惠連口箴曰：宣納之由，沄伊枢機，唯舌是出，馳驷安追，差氂千里，君子慎微，何用口爽，信在际肺¨","sortOrder":103},
  {"id":"s_work_nvlt_17_104","chapterId":"ch_work_nvlt_17","text":"【誡】晉傅玄口誡曰：勿謂何有炁積怨致咎，勿曰不傳，伏流成川，蚁孔潰河，流穴傾山。","sortOrder":104},
  {"id":"s_work_nvlt_17_105","chapterId":"ch_work_nvlt_17","text":"【銘】齊竟陵王萧子良口銘曰：惟口是慎，慎乎語笑，三緘是戒，事重周廟，戒之戒之，無貽厥誚。","sortOrder":105},
  {"id":"s_work_nvlt_17_107","chapterId":"ch_work_nvlt_17","text":"《山海經》曰：反舌國，其人反舌。","sortOrder":107},
  {"id":"s_work_nvlt_17_108","chapterId":"ch_work_nvlt_17","text":"《呂氏春秋》曰：善為君者，蠻夷反舌，殊俗異習，皆服德厚也。","sortOrder":108},
  {"id":"s_work_nvlt_17_109","chapterId":"ch_work_nvlt_17","text":"《莊子》曰：公孫龍口呿而不合，舌舉而不下。","sortOrder":109},
  {"id":"s_work_nvlt_17_110","chapterId":"ch_work_nvlt_17","text":"《燕丹子》曰：荆軻之燕，太子曰：田先生今無恙乎，軻曰：光臨送軻之時，言太子戒以國事，恥以丈夫而不見信，向軻吞舌而死矣。","sortOrder":110},
  {"id":"s_work_nvlt_17_111","chapterId":"ch_work_nvlt_17","text":"《史記》曰：平原君已定從而歸，至於趙，曰：毛先生以三寸之舌，強於百萬之師。","sortOrder":111},
  {"id":"s_work_nvlt_17_112","chapterId":"ch_work_nvlt_17","text":"又曰：留侯曰：家世相韓，韓滅，不愛萬金之資，為韓報讎強秦，天下振動，今以三寸舌，為帝者之師，封萬戶，位列侯，此布衣之極，於良足矣。","sortOrder":112},
  {"id":"s_work_nvlt_17_113","chapterId":"ch_work_nvlt_17","text":"又曰：張儀嘗從楚相飲，已而楚相亡璧，門下意儀盜璧，共執儀，掠笞數百，不服，釋之，其妻曰：子無讀書遊說，安得此辱乎，儀張口曰：视吾舌尚在否，妻曰：在也，儀曰：足矣。","sortOrder":113},
  {"id":"s_work_nvlt_17_114","chapterId":"ch_work_nvlt_17","text":"《說苑》曰：韓平子問叔向曰：刚與软孰堅，對曰：臣年八十矣，齒再墮而舌尚在。","sortOrder":114},
  {"id":"s_work_nvlt_17_115","chapterId":"ch_work_nvlt_17","text":"《神異經》曰：東荒山中，有大石室，東王公居之，長一丈，頭發皓白，鳥面人形而虎尾，恒與一玉女更投壶。","sortOrder":115},
  {"id":"s_work_nvlt_17_116","chapterId":"ch_work_nvlt_17","text":"《漢書》：蒯通謂韓信曰：郦生一士，伏軾掉三寸舌，下齊七十城。","sortOrder":116},
  {"id":"s_work_nvlt_17_117","chapterId":"ch_work_nvlt_17","text":"《英雄記》曰：曹操與劉備密言，備泄之於袁紹，紹知操有圖己之意，操自咋其舌流血，以失言戒後世。","sortOrder":117},
  {"id":"s_work_nvlt_17_118","chapterId":"ch_work_nvlt_17","text":"《搜神記》曰：永嘉中有天竺胡人，能斷舌，先吐舌示賓客，然後刀截，血流覆地，乃取置器中，傳示人，取舌還含，有頃如故。","sortOrder":118},
  {"id":"s_work_nvlt_17_119","chapterId":"ch_work_nvlt_17","text":"《郭子》曰：殷仲堪雲，三日不讀道德經，覺舌本間強。","sortOrder":119},
  {"id":"s_work_nvlt_17_120","chapterId":"ch_work_nvlt_17","text":"沈約《宋書》曰：南郭［宋書作郡。］王義宣，生而舌短涩言。","sortOrder":120},
  {"id":"s_work_nvlt_17_121","chapterId":"ch_work_nvlt_17","text":"《相書》曰：舌如絳赤者，賢人也。","sortOrder":121},
  {"id":"s_work_nvlt_17_122","chapterId":"ch_work_nvlt_17","text":"《相書雜要》曰：吐舌及鼻三公。","sortOrder":122},
  {"id":"s_work_nvlt_17_123","chapterId":"ch_work_nvlt_17","text":"【賦】梁簡文帝舌賦曰：奚茲先生問於何斯逸士曰：夫三端所貴，三寸著名，故微言傳乎往記，妙說表乎丹青，魯談笑而軍却，王言詠而瑞隆，陆有千金之富，周為一說之功，复有構扇之端，讒諛之跡，艳紫凌朱，飛黃妒白，吾將欲废便辟之交，遠巧佞之友，殄張儀之餘，殲蘇秦之後，粉虞卿之白璧，碎漢王之玉斗，然後浮伪可息，淳風不朽。","sortOrder":123},
  {"id":"s_work_nvlt_17_124","chapterId":"ch_work_nvlt_17","text":"【論】晉張韓不用舌論曰：論者以為心氣相驅，因舌而言，卷舌翕氣，安得畅理，餘以留意於言，不如留意於不言，徒知無舌之通心，未盡有舌之必通心也，仲尼雲，天何言哉，四時行焉，夫子之文章，可得而聞也，夫子之言性與天道，不可得而聞，是謂至精，愈不可聞，枢機之發，主乎榮辱，禍言相尋，召福甚希，丧元滅族，没有餘哀，三緘告慎，銘在金人，留侯不得已而掉三寸，亦反初服而效神仙，靈龟啟兆於有識，前却可通於千年，鸚鵡猩猩，鼓弄於籠羅，财無一介之存，普天地之與人物，亦何屑於有言哉。","sortOrder":124},
  {"id":"s_work_nvlt_17_126","chapterId":"ch_work_nvlt_17","text":"《歸藏啟筮》曰：共工人面蛇身，朱發。","sortOrder":126},
  {"id":"s_work_nvlt_17_127","chapterId":"ch_work_nvlt_17","text":"《左傳》曰：齊侯田於莒，盧蒲嫳見，泣且請曰：餘之發如此种种，餘奚能為，［种种，短也。］公曰：吾告二子，子尾欲复之，子雅不可，曰：彼其發短而心甚長，其或寢處我矣，子雅放盧蒲嫳於北燕。","sortOrder":127},
  {"id":"s_work_nvlt_17_128","chapterId":"ch_work_nvlt_17","text":"又曰：昔有仍氏女生，鬒黑［美發為鬒。］而甚美，光可以鑒，名曰玄妻，樂正後夔取之。","sortOrder":128},
  {"id":"s_work_nvlt_17_129","chapterId":"ch_work_nvlt_17","text":"《禮斗威儀》曰：君乘木而王，為人美發。","sortOrder":129},
  {"id":"s_work_nvlt_17_130","chapterId":"ch_work_nvlt_17","text":"《呂氏春秋》曰：昔者殷旱五年，湯乃以身祷，剪發自以為犧，用祈福於上帝。","sortOrder":130},
  {"id":"s_work_nvlt_17_131","chapterId":"ch_work_nvlt_17","text":"《韓子》曰：文公之時，宰人上炙而發繞之，文公召宰人而誚之，宰人曰：臣有死罪三，援砺砥刀，利猶幹將，切肉斷而發不絕，臣之罪一也，援錐貫脔，而不見發，臣之罪二也，奉炙爐炭，肉盡赤紅，炙熟而發不焦，臣之罪三也，堂下得微有嫉臣者乎，公乃召其下而誚之，果然，乃誅之。","sortOrder":131},
  {"id":"s_work_nvlt_17_132","chapterId":"ch_work_nvlt_17","text":"又曰：燕李季好遠出，其妻有士，季至，士在內，妻患之，妾曰：令公子倮而解發，直出門，吾屬詳不見也，公子從其計，疾走出門，季曰：是何人也，家室皆曰無有，季曰吾見鬼，為之奈何，婦曰：取五姓之水浴之，季曰：诺，乃浴。","sortOrder":132},
  {"id":"s_work_nvlt_17_133","chapterId":"ch_work_nvlt_17","text":"《家語》曰：顏回二十發白。","sortOrder":133},
  {"id":"s_work_nvlt_17_134","chapterId":"ch_work_nvlt_17","text":"《史記》曰：蔺相如持璧，却立倚柱，怒發上冲冠。","sortOrder":134},
  {"id":"s_work_nvlt_17_135","chapterId":"ch_work_nvlt_17","text":"《漢書》曰：蘇武留匈奴十九年，始以強壮出，及還，鬢發盡白。","sortOrder":135},
  {"id":"s_work_nvlt_17_136","chapterId":"ch_work_nvlt_17","text":"淮南《萬畢術》曰：理發竈前，婦安夫家。","sortOrder":136},
  {"id":"s_work_nvlt_17_137","chapterId":"ch_work_nvlt_17","text":"又曰：用麻子中人，桐葉米汁煮之，沐二十日，發長。","sortOrder":137},
  {"id":"s_work_nvlt_17_138","chapterId":"ch_work_nvlt_17","text":"《東觀漢記》曰：明德後美發，為四起大髻，但以發成尚有餘，繞髻三匝。","sortOrder":138},
  {"id":"s_work_nvlt_17_139","chapterId":"ch_work_nvlt_17","text":"又曰：和喜皇後，六歲，諸兄持後發，後曰：身體發膚，受之父母，不敢毀傷，孝之始也，奈何弄人發乎。","sortOrder":139},
  {"id":"s_work_nvlt_17_140","chapterId":"ch_work_nvlt_17","text":"《曹瞞傳》曰：太祖嘗行經麥中，令卒士無败麥，犯者死，騎士皆下馬持麥以相付，時太祖馬騰入麥中，太祖曰：製法而自犯之，何以帥下，然孤為軍帥，不可殺，請自刑，因援劍割發以置地。","sortOrder":140},
  {"id":"s_work_nvlt_17_141","chapterId":"ch_work_nvlt_17","text":"王隱《晉書》曰：陶侃為吏，鄱陽孝廉與親友過侃宿，母截發以供賓，諸客叹曰：非此母，不生此子也。","sortOrder":141},
  {"id":"s_work_nvlt_17_142","chapterId":"ch_work_nvlt_17","text":"【詩】梁何遜白發詩曰：絲白不難染，蓬生本易扶，唯此星星發，獨與眾中殊。","sortOrder":142},
  {"id":"s_work_nvlt_17_143","chapterId":"ch_work_nvlt_17","text":"【賦】晉左思白發賦曰：星星白發，生於鬢垂，雖非青蠅，秽我光儀，策名觀國，以此見疵，將拔將鑷，好爵是縻，白發將拔，惄然自訴，禀命不幸，值君年暮，逼迫秋霜，生而皓素，始覽明鏡，惕然見惡，朝生晝拔，何罪之故，予觀橘柚，一〈目高〉一瞱，貴其素華，匪尚绿葉，原戢子之手，攝子之鑷，咨爾白發，觀世之途，靡不追榮，貴華賤枯，赫赫閶阖，藹藹紫庐，弱冠來仕，童髫獻謨，甘羅乘軫，子奇剖符，英英終贾，高論雲衢，拔白就黑，此自在吾，白發臨欲拔，瞋目號呼，何我之冤，何子之誤，甘羅自以辯惠見稱，不以發黑而名著，贾生自以良才見異，不以乌鬢而後舉，聞之先民，國用老成，二老歸周，周道肅清，四皓佐漢，漢德光明，何必去我，然後要榮，咨爾白發，事故有以，爾之所言，非不有理，曩貴耆耋，今薄舊齒，皤皤榮期，皓首田里，雖有二毛，河清難俟，隨時之变，見叹孔子，發乃辭盡，誓以固窮，昔臨玉顏，今從飛蓬，發膚至昵，尚不克終，聊用擬辭，比之國風。","sortOrder":143},
  {"id":"s_work_nvlt_17_144","chapterId":"ch_work_nvlt_17","text":"【序】晉稽含白首賦序曰：餘年二十七，始有白發生於左鬢，斯乃衰悴之標證，弃捐之大漸也，蒲衣幼齒，作弼夏後，漢之贾邓，弱冠從政，獨以垂立之年，白首無聞，壮志衄於芜涂，忠貞抗於棘路，睹將衰而有川上之感，觀趣舍而抱慷慨之叹。","sortOrder":144},
  {"id":"s_work_nvlt_17_145","chapterId":"ch_work_nvlt_17","text":"◇髑髏","sortOrder":145},
  {"id":"s_work_nvlt_17_146","chapterId":"ch_work_nvlt_17","text":"《說文》曰：髑髏，顶也。","sortOrder":146},
  {"id":"s_work_nvlt_17_147","chapterId":"ch_work_nvlt_17","text":"《廣雅》曰：顙顱謂之髑髏。","sortOrder":147},
  {"id":"s_work_nvlt_17_148","chapterId":"ch_work_nvlt_17","text":"《莊子》曰：莊子使楚，見空髑髏，击以馬捶而問曰：夫子貪生失理而為此乎，將有冻餒之患而為此乎，語卒，援髑髏，枕而臥，髑髏見夢曰：夫死無君於上，無臣於下，亦無四時之事，與天地為春秋，雖南面帝王，樂不能過也。","sortOrder":148},
  {"id":"s_work_nvlt_17_149","chapterId":"ch_work_nvlt_17","text":"《魏略》曰：王忠先因飢啖人，五官將與共從駕出行，過冢［原訛家，據冯校本改。］間，無何，令取道邊死人髑髏系著忠馬鞍上，以為戲笑。","sortOrder":149},
  {"id":"s_work_nvlt_17_150","chapterId":"ch_work_nvlt_17","text":"盛弘之《荆州記》曰：長沙蒲圻縣，有呂蒙冢，冢中有一髑髏，極大，蒙形既長伟，疑即蒙髑髏也。","sortOrder":150},
  {"id":"s_work_nvlt_17_151","chapterId":"ch_work_nvlt_17","text":"《廣州記》曰：盧循袭廣州，風火夜發，奔免者數千而已，循除諸燒骨，數得髑髏三萬餘，於江南洲上作大坑葬之，今名共冢。","sortOrder":151},
  {"id":"s_work_nvlt_17_152","chapterId":"ch_work_nvlt_17","text":"《南州異物志》曰：乌滸人，髑髏破之，以飲酒。","sortOrder":152},
  {"id":"s_work_nvlt_17_153","chapterId":"ch_work_nvlt_17","text":"《續搜神記》曰：永嘉五年，張榮為高平戍邏主，時遭曹嶷賊寇亂，人民［○原民字坏，據《太平御覽》三百七十四補。］皆坞壘自保固，見山中火起，飛埃絕烂［御覽作爓。］十餘丈，树顛大焱，响動山穀，久聞人馬鎧甲聲，謂嶷賊上，人皆惶恐，併嚴出，將欲击之，引騎到山下，無有人，但見碎火來曬人，袍鎧馬毛{髟葛}皆燒，於是軍人走還，明日往视山中，無燃火處，唯見髑髏百頭，布散在山中。","sortOrder":153},
  {"id":"s_work_nvlt_17_154","chapterId":"ch_work_nvlt_17","text":"【賦】後漢張衡髑髏賦曰：張平子將遊目於九野，觀化於八方，顧見髑髏，委於路旁，平子怅然而問之，子將併糧推命，以夭逝乎，本丧此土，流遷來乎，為是上知，為是下愚，答曰：吾宋人也，姓莊名周，遊心方外，不能自修，公子何以問之，對曰：我欲告之於五嶽，祷之於神祇，起子素骨，反子四支，髑髏曰：死為休息，生為役勞，冬之冰凝，何如春冰之消，况我已化，與道逍遙，與陰陽同其流，元氣合其朴，雲漢為川池，星宿為珠玉，雷電為鼓扇，日月為燈燭，合體自然，無情無欲，不行而至，不疾而速。","sortOrder":154},
  {"id":"s_work_nvlt_17_155","chapterId":"ch_work_nvlt_17","text":"晉呂安髑髏賦曰：踌躇增愁，言遊舊乡，惟遇髑髏，在彼路傍，餘乃俯仰咤叹，告於昊蒼，此獨何人，命不永長，身銷原野，骨曝大荒，餘將殯子時服，與子嚴裝，殓以棺椁，遷彼幽堂，於是髑髏蠢如，精靈感應，若在若無，斐然見形，溫色素膚，昔以無良，行违皇乾，來遊此土，天奪我年，令我全膚消滅，白骨連翩，四支摧藏於草莽，孤魂悲悼乎黃泉，餘乃感其苦酸，哂其所說，念爾荼毒，形神斷絕，今宅子後土，以為永列，相與異路，於是便別。","sortOrder":155},
  {"id":"s_work_nvlt_17_156","chapterId":"ch_work_nvlt_17","text":"【說】魏陳王曹植髑髏說曰：曹子遊乎陂塘之濱，步乎蓁秽之藪，萧條潛虛，經幽踐阻，顧見髑髏，塊然獨居，於是伏軾而問之曰：子將結纓首劍，殉國君乎，將被堅執銳，毙三軍乎，將婴茲固疾，命殒傾乎，將寿終數極，歸幽冥乎，叩遺骸而叹息，哀白骨之無靈，慕嚴周之適楚，傥讬夢以通情，於是伻若有來，怳若有存，影見容隱，厲响而言曰：子何國之君子乎，既枉舆駕，愍其枯朽，不惜咳唾之音，慰以苦言，子則辯於辭矣，然未達幽冥之情，識死生之說也，夫死之為言歸也，歸也者，歸於道也，道也者，身以無形為主，故能與化推移，陰陽不能更，四節不能虧，是故洞於纖微之域，通於恍惚之庭，望之不見其象，聽之不聞其聲，挹之不冲，滿之不盈，吹之不凋，噓之不榮，激之不流，凝之不停，寥落冥漠，與道相拘，偃然長寢，樂莫是逾，曹子曰：予將請之上帝，求諸神靈，使司命輟籍，反子骸形，於是髑髏長呻廓眦曰：甚矣，何子之難語也，昔太素氏不仁，無故勞我以形，苦我以生，今也幸变而之死，是反吾真也，何子之好勞，而我之好逸，子則行矣，餘將歸於太虛，於是言卒响絕，神光霧除，顧將旋軫，乃命仆夫，拂以玄尘，覆以縞巾，爰將藏彼路濱，壅以丹土，翳以绿榛，夫存亡之異势，乃宣尼之所陳，何神凭之虛對，雲死生之必均。","sortOrder":156},
  {"id":"s_work_nvlt_17_158","chapterId":"ch_work_nvlt_17","text":"《黃帝素問》曰：胆者，中正之官，斷决出焉。","sortOrder":158},
  {"id":"s_work_nvlt_17_159","chapterId":"ch_work_nvlt_17","text":"《吳越春秋》曰：越王欲報怨，懸胆於戶，出入嘗之，［事具水部水篇。］","sortOrder":159},
  {"id":"s_work_nvlt_17_160","chapterId":"ch_work_nvlt_17","text":"魏志曰：樂進，字文謙，容貌短小，以胆烈從太祖。","sortOrder":160},
  {"id":"s_work_nvlt_17_161","chapterId":"ch_work_nvlt_17","text":"又曰：袁紹在黎陽，將南度，程昱守甄城，太祖欲益其兵，昱不肯，曰：袁紹擁十萬眾，見昱兵少，必輕易不攻，若益昱兵，過則不可，攻之必克，徒兩損其势，原公無疑，太祖從之，紹聞昱兵少，果不往，太祖曰：程昱之胆，過於贲育。","sortOrder":161},
  {"id":"s_work_nvlt_17_162","chapterId":"ch_work_nvlt_17","text":"《吳志》曰：呂蒙病篤，孫權問曰：卿如不起，誰可代者，對曰：朱然，胆守有餘，愚以為可任。","sortOrder":162},
  {"id":"s_work_nvlt_17_163","chapterId":"ch_work_nvlt_17","text":"《管辂別傳》曰：辂年十五，琅琊太守单子春，雅有才度，欲見辂，辂造之，客百餘人，有能言之士，辂謂子春曰：府君名士，加有雄貴之資，辂既年少，胆未堅刚，若欲相觀，懼失精神，請先飲酒三斗，然後而言，子春大喜，酌三斗，獨使飲之，於是辂人人答對，言皆有餘。","sortOrder":163},
  {"id":"s_work_nvlt_17_164","chapterId":"ch_work_nvlt_17","text":"劉琨書曰：胆識堅定，臨難無苟免之意。","sortOrder":164},
  {"id":"s_work_nvlt_17_165","chapterId":"ch_work_nvlt_17","text":"《世說》曰：薑維死時見剖，胆大如斗。","sortOrder":165},
  {"id":"s_work_nvlt_17_166","chapterId":"ch_work_nvlt_17","text":"【論】魏嵇康明胆論曰：有呂子春者，精義味道，研覈是非，以為人有胆可無明，有明便有胆矣，嵇先生以為明胆殊用，不能相生，論曰：夫元氣陶鑠，眾生禀焉，賦受有多少，故才性有昏明，唯至人，特鍾純美，兼周外內，無不畢備，降此已往，蓋闕如也，或明於見物，或勇於决斷，人情貪廉，各有所止，譬諸草木，區以別矣，兼之者博於物，偏受者守其分，故吾謂明胆異氣，不能相生，明以見事，胆以决斷，专明無胆，雖見不斷，专胆無明，則违理失機。","sortOrder":166},
  {"id":"s_work_nvlt_17_167","chapterId":"ch_work_nvlt_17","text":"《藝文類聚》　唐·欧陽詢","sortOrder":167},
  {"id":"s_work_nvlt_18_1","chapterId":"ch_work_nvlt_18","text":"卷十八人部二","sortOrder":1},
  {"id":"s_work_nvlt_18_2","chapterId":"ch_work_nvlt_18","text":"○美婦人賢婦人老","sortOrder":2},
  {"id":"s_work_nvlt_18_3","chapterId":"ch_work_nvlt_18","text":"◇美婦人","sortOrder":3},
  {"id":"s_work_nvlt_18_4","chapterId":"ch_work_nvlt_18","text":"《方言》曰：秦晉之間，美貌謂之娥，美状為窕，美色為艳，美心為窈。","sortOrder":4},
  {"id":"s_work_nvlt_18_5","chapterId":"ch_work_nvlt_18","text":"《毛詩》曰：窈窕淑女，君子好逑。","sortOrder":5},
  {"id":"s_work_nvlt_18_6","chapterId":"ch_work_nvlt_18","text":"又曰：硕人其頎，衣錦褧衣，手如柔荑，膚如凝脂，領如蝤蛴，齒如瓠犀，螓首娥眉。","sortOrder":6},
  {"id":"s_work_nvlt_18_7","chapterId":"ch_work_nvlt_18","text":"又曰：有美一人，婉如清陽。","sortOrder":7},
  {"id":"s_work_nvlt_18_8","chapterId":"ch_work_nvlt_18","text":"《左傳》曰：宋華父督見孔父之妻於路，曰：美而艳。","sortOrder":8},
  {"id":"s_work_nvlt_18_9","chapterId":"ch_work_nvlt_18","text":"又曰：昔有仍氏生女，黰黑而甚美，光可鑒，名曰玄妻。","sortOrder":9},
  {"id":"s_work_nvlt_18_10","chapterId":"ch_work_nvlt_18","text":"《禮含文嘉》曰：禹卑宮室，垂意溝洫，則玉女敬養。","sortOrder":10},
  {"id":"s_work_nvlt_18_11","chapterId":"ch_work_nvlt_18","text":"《穆天子傳》曰：赤乌之人甚好，獻二女於天子，以為嬖人，赤乌，美人之地。","sortOrder":11},
  {"id":"s_work_nvlt_18_12","chapterId":"ch_work_nvlt_18","text":"《韓子》曰：魏王遺楚王美女，王甚悅之。","sortOrder":12},
  {"id":"s_work_nvlt_18_13","chapterId":"ch_work_nvlt_18","text":"《莊子》曰：毛嫱驪姬，人之所美也，魚見之深潛，鳥見之高飛。","sortOrder":13},
  {"id":"s_work_nvlt_18_14","chapterId":"ch_work_nvlt_18","text":"尹《文子》曰：齊有黃公者，二女皆國色，以其美也，常謙辭毀之為丑惡，丑惡之名遠布，而一國之人無敢娉者。","sortOrder":14},
  {"id":"s_work_nvlt_18_15","chapterId":"ch_work_nvlt_18","text":"《慎子》曰：毛嫱西施，天下之至姣［胡茅反。］也，衣以皮褐倛，［欺既反。］則見者走，易以玄裼，則行者皆止。","sortOrder":15},
  {"id":"s_work_nvlt_18_16","chapterId":"ch_work_nvlt_18","text":"《楚辭》曰：姱容脩態艑洞房，娥眉曼绿目騰光。","sortOrder":16},
  {"id":"s_work_nvlt_18_17","chapterId":"ch_work_nvlt_18","text":"又曰：粉白黛黑施芳泽，長袂拂面善留客。","sortOrder":17},
  {"id":"s_work_nvlt_18_18","chapterId":"ch_work_nvlt_18","text":"又曰：美人既醉朱顏酡。","sortOrder":18},
  {"id":"s_work_nvlt_18_19","chapterId":"ch_work_nvlt_18","text":"《淮南子》曰：曼容皓齒，形姱骨佳，不待傅粉芳泽而美者，西施陽文也。","sortOrder":19},
  {"id":"s_work_nvlt_18_20","chapterId":"ch_work_nvlt_18","text":"《戰國策》曰：張儀曰：鄭周之女，粉白黛黑，非知而見之者以為神。","sortOrder":20},
  {"id":"s_work_nvlt_18_21","chapterId":"ch_work_nvlt_18","text":"又曰：司馬喜謂趙王曰：趙，佳麗之所出也。","sortOrder":21},
  {"id":"s_work_nvlt_18_22","chapterId":"ch_work_nvlt_18","text":"《史記》曰：紂囚西伯，而閎夭之徒，以有莘氏美女獻紂，紂大悅，乃放西伯。","sortOrder":22},
  {"id":"s_work_nvlt_18_23","chapterId":"ch_work_nvlt_18","text":"又曰：尹夫人邢夫人，同時併幸，武帝有詔，不得相見，尹夫人自請武帝，原見邢夫人，帝令他夫人飾，從者數十人來前，尹夫人見之曰：非邢夫人，帝曰：何以言之，對曰：视其體，形状不足以當人主，有詔邢夫人，衣故衣，獨身來，尹夫人望見之曰：真是矣，於是乃低頭俯而泣，自痛其不如也。喭曰：美女入室，惡女之仇也。","sortOrder":23},
  {"id":"s_work_nvlt_18_24","chapterId":"ch_work_nvlt_18","text":"《漢書》曰：李延年善歌，侍武帝，歌曰：北方有佳人，絕世而獨立，一顧傾人城，再顧傾人國，寧不知傾城國，佳人不可再得，上叹曰：善，豈有此人乎，平陽主因言延年有女弟，上乃召見之，實妙麗善舞，以為夫人。［事具樂部舞篇。］","sortOrder":24},
  {"id":"s_work_nvlt_18_25","chapterId":"ch_work_nvlt_18","text":"《漢武故事》曰：起明光宮，發燕趙美女二千人充之，率取十五以上，二十以下，凡諸宮美人，可有七八十，與上同輦者十六人，員數恒使滿，皆自然美麗，不使粉白黛黑。","sortOrder":25},
  {"id":"s_work_nvlt_18_26","chapterId":"ch_work_nvlt_18","text":"《東觀漢記》曰：初，光武聞陰麗華美，心悅之，叹曰：娶妻當得陰麗華，後為皇後，［事具叙志篇。］","sortOrder":26},
  {"id":"s_work_nvlt_18_27","chapterId":"ch_work_nvlt_18","text":"華峤《漢書》曰：梁冀妻孫寿，色美，能作愁眉啼妆，墮馬髻，折腰步，龋齒笑，以為媚惑也。","sortOrder":27},
  {"id":"s_work_nvlt_18_28","chapterId":"ch_work_nvlt_18","text":"妒記曰：桓大司馬以李势女為妾，桓妻南郡主，拔刀率數十婢往李所，因欲斫之，見李在窗前梳頭，發垂委地，姿貌絕麗，乃徐下地結髻，斂手向主曰：國破家亡，無心以至今日，若能見殺，實猶生之年，神色閒正，辭氣凄婉，主乃掷刀前抱之曰：阿子，見汝不能不怜，何况老奴，遂善遇之。","sortOrder":28},
  {"id":"s_work_nvlt_18_29","chapterId":"ch_work_nvlt_18","text":"幹寶《晉紀》曰：石崇有妓人曰绿珠，美而工舞，孫秀乃使人求焉，崇方登涼觀，臨清水，婦人侍侧使者以告崇，崇出妓妾數十人，皆蘊蘭麝而被羅縠，曰：在所擇，使者曰：君侯服御，麗則麗矣，然本受旨索绿珠，崇勃然曰：绿珠吾所愛重，不可得也，使者還，以告，故秀勸趙王倫殺之。","sortOrder":29},
  {"id":"s_work_nvlt_18_30","chapterId":"ch_work_nvlt_18","text":"桓谭《新論》曰：陳平說单於閼氏，言漢有好麗美女，其容貌天下無双，急以進单於，单於見此，必大愛之，則閼氏疏矣。","sortOrder":30},
  {"id":"s_work_nvlt_18_31","chapterId":"ch_work_nvlt_18","text":"《典論》曰：司隸冯方女，國色也，袁術登城見，悅之，遂納焉，甚愛幸，諸姬害其寵，殺之。","sortOrder":31},
  {"id":"s_work_nvlt_18_32","chapterId":"ch_work_nvlt_18","text":"《魏略》曰：初袁紹子熙，納甄後，熙出幽州，後留侍姑，及鄴破，紹妻及後，坐堂皇上，紹妻自縛，文帝曰：袁夫人令新婦舉頭，姑乃奉後令仰，帝審视，見其顏色非凡，稱叹之，太祖為迎取焉。","sortOrder":32},
  {"id":"s_work_nvlt_18_33","chapterId":"ch_work_nvlt_18","text":"《吳志》曰：孫權步夫人，以美麗得幸，寵冠後庭。","sortOrder":33},
  {"id":"s_work_nvlt_18_34","chapterId":"ch_work_nvlt_18","text":"又曰：周瑜從孫策皖城，得桥公兩女，國色也，策自納大桥，瑜納小桥，俗說曰：宋禕是石崇妓绿珠弟子，有國色，善吹笛，後入晉明帝宮，［事具樂部笛篇。］","sortOrder":34},
  {"id":"s_work_nvlt_18_35","chapterId":"ch_work_nvlt_18","text":"《鄴中記》曰：陳逵妹，才色甚美，發長七尺，石季龍以為夫人。","sortOrder":35},
  {"id":"s_work_nvlt_18_36","chapterId":"ch_work_nvlt_18","text":"【詩】古詩曰：燕趙多佳人，美者顏如玉，被服羅裳衣，當戶理清曲，音响一何悲，絃急知柱促，原為双飛燕，衔泥巢君屋。","sortOrder":36},
  {"id":"s_work_nvlt_18_37","chapterId":"ch_work_nvlt_18","text":"魏陳王曹植詩曰：有美一人，被服纖羅，妖姿艳麗，蓊若春花，紅顏韡晔，雲髻峨峨，彈琴撫節，為我絃歌，清濁齊均，既亮且和，取樂今日，遑恤其他。又雜詩曰：南國有佳人，容華若桃李，朝遊江海岸，夕宿瀟湘沚，時俗薄朱顏，誰為發皓齒，俯仰歲將暮，榮曜寧久恃。","sortOrder":37},
  {"id":"s_work_nvlt_18_38","chapterId":"ch_work_nvlt_18","text":"又美女篇曰：美女妖且閒，采桑岐路間，攘袖見素手，皓腕約金環，頭上三爵釵，腰佩翠琅玕，明珠交玉體，珊瑚間木難，羅衣何飄飖，輕裾隨風還，顧盻遺光采，長笑氣若蘭，行徒用息駕，休首以忘餐，借問女何居，乃在城南端，青樓臨大路，高門結重關，容華暉朝日，誰不希令顏。","sortOrder":38},
  {"id":"s_work_nvlt_18_39","chapterId":"ch_work_nvlt_18","text":"魏阮籍詩曰：西方有佳人，皎若白日光，被服纖羅衣，左右佩双璫。","sortOrder":39},
  {"id":"s_work_nvlt_18_40","chapterId":"ch_work_nvlt_18","text":"又詩曰：周鄭天下郊，衛衢當三河，妖冶閒都子，英曜何芬葩，玄發發朱顏，睇眄有光華，傾城思一顧，遺视來相過，原為三春遊，朝陽忽蹉跎。","sortOrder":40},
  {"id":"s_work_nvlt_18_41","chapterId":"ch_work_nvlt_18","text":"又詩曰：二妃遊江濱，逍遙從風翔，交甫懷環珮，婉娩有芬芳，綺靡情歡愛，千歲不相忘，傾城迷下蔡，容華結中腸，感激生忧思，萱草树蘭房。","sortOrder":41},
  {"id":"s_work_nvlt_18_42","chapterId":"ch_work_nvlt_18","text":"晉傅玄詩曰：有女懷芬芳，媞媞步東厢，蛾眉若双翠，明眸發清陽，丹唇翳皓齒，秀顏若珪璋，令儀希世出，無乃古毛嫱，首戴金步搖，耳系明月璫，珠環約素腕，翠羽垂鮮光，容華既已艳，志節擬秋霜。","sortOrder":42},
  {"id":"s_work_nvlt_18_43","chapterId":"ch_work_nvlt_18","text":"梁簡文帝晚景出行詩曰：細树含殘影，春閨散晚香，輕花鬢畔墮，微汗粉中光，飛凫初罢曲，啼鳥忽度行，羞令白日暮，車馬鬱相望。","sortOrder":43},
  {"id":"s_work_nvlt_18_44","chapterId":"ch_work_nvlt_18","text":"又詩曰：麗旦與妖嫱，共拂可怜妆，同安鬟里拨，異作額間黃，羅裾宜細簡，畫屟重高牆，含羞未上砌，微笑出長廊，取花爭寶鑷，攀枝念蕊香，但歌聊一曲，鳴絃未肯張，自矜心所愛，三十侍中郎。","sortOrder":44},
  {"id":"s_work_nvlt_18_45","chapterId":"ch_work_nvlt_18","text":"又詠內人晝眠詩曰：北窗聊就枕，南簷日未斜，攀鉤落倚障，插捩舉琵琶，夢笑开娇靨，眠鬟壓落花，簟文生玉腕，香汗浸紅紗，夫婿恒相伴，莫誤是倡家。","sortOrder":45},
  {"id":"s_work_nvlt_18_46","chapterId":"ch_work_nvlt_18","text":"又詠美人看畫詩曰：殿上圖神女，殿里出佳人，可怜俱是畫，誰能辯寫真，分明净眉眼，一种細腰身，所可持為異，長有好精神。","sortOrder":46},
  {"id":"s_work_nvlt_18_47","chapterId":"ch_work_nvlt_18","text":"梁元帝古意詩曰：妾在成都縣，原作高唐雲，樽中石榴酒，機上蒲萄紋，停梭還斂色，何時勸使君。","sortOrder":47},
  {"id":"s_work_nvlt_18_48","chapterId":"ch_work_nvlt_18","text":"梁昭明太子詠照流看落釵詩曰：相隨照渌水，意是重涼風，流搖妆影坏，釵落鬢花空，佳期在何許，徒傷心不同。","sortOrder":48},
  {"id":"s_work_nvlt_18_49","chapterId":"ch_work_nvlt_18","text":"又名士悅傾城詩曰：美人稱絕世，麗色譬花丛，經居李城北，來往宋家東，教歌公主第，學舞漢城宮，多遊淇水曲，好在鳳樓中，履高疑上砌，裾开特畏風，袖輕見跳脱，珠摡雜青虫，垂絲繞帷幔，落日度房栊，妆窗隔柳色，井水照桃紅，非怜交甫珮，羞使春閨空。","sortOrder":49},
  {"id":"s_work_nvlt_18_50","chapterId":"ch_work_nvlt_18","text":"又美人晨妆詩曰：北窗朝向鏡，錦障复斜萦，娇羞不肯出，猶言妆未成，散黛隨眉廣，煙支逐脸生，试將持出眾，定得向怜名。","sortOrder":50},
  {"id":"s_work_nvlt_18_51","chapterId":"ch_work_nvlt_18","text":"梁邵陵王萧纶見姬人詩曰：春來不复賒，入苑駐行車，比來妆點異，今世拨鬟斜，却扇承枝影，舒衫受落花，狂夫不妒妾，隨意晚還家。","sortOrder":51},
  {"id":"s_work_nvlt_18_52","chapterId":"ch_work_nvlt_18","text":"梁萧子顯美女篇曰：章丹暫輟舞，巴姬請罢絃，佳人淇洧出，艳趙复傾燕，繁秾既為李，照水亦成莲，朝酤成都酒，暝數河間錢，餘光幸未惜，蘭膏空自煎。","sortOrder":52},
  {"id":"s_work_nvlt_18_53","chapterId":"ch_work_nvlt_18","text":"梁庾肩吾詠美人看畫詩曰：欲知畫能巧，唤取真來映，併出似分身，相看如照鏡，安釵等疏密，著領俱周正，不解平城围，誰與丹青競。","sortOrder":53},
  {"id":"s_work_nvlt_18_54","chapterId":"ch_work_nvlt_18","text":"又詩曰：絳树及西施，俱是好容儀，非關能結束，本自細腰枝，鏡前難併照，相將映渌池，看妆畏水動，斂袖避風吹，轉手齊裾亂，橫簪歷鬢垂，曲中人未取，誰堪白日移，不分他相識，唯聽使君知。","sortOrder":54},
  {"id":"s_work_nvlt_18_55","chapterId":"ch_work_nvlt_18","text":"又南苑看人還詩曰：春花競玉顏，俱折复俱攀，細腰宜窄衣，長釵巧扶鬟，洛桥初度燭，青門欲上關，中人應有望，上客莫前還。","sortOrder":55},
  {"id":"s_work_nvlt_18_56","chapterId":"ch_work_nvlt_18","text":"梁徐君蒨初春携內人行戲詩曰：梳飾多今世，衣著一時新，草短猶通屟，梅香未［原訛末，據冯校本改。］著人，树斜牵錦帔，風橫入紅纶，滿酌蘭英酒，對此得娱神，梁劉孝綽愛姬赠主人詩曰：臥久疑妆脱，鏡中私自看，薄黛銷將盡，凝朱半有殘，垂釵繞落鬢，微汗染輕紈，同羞不相難，對笑更成懽，妾心君自解，掛玉且留冠。","sortOrder":56},
  {"id":"s_work_nvlt_18_57","chapterId":"ch_work_nvlt_18","text":"又為人赠美人詩曰：巫山荐枕日，洛浦獻珠時，一遇便如此，寧關先有期，幸非使君問，莫作羅敷辭，夜長眠复坐，誰知闇斂眉，欲寄同花燭，為照遙相思。","sortOrder":57},
  {"id":"s_work_nvlt_18_58","chapterId":"ch_work_nvlt_18","text":"又詠姬人未肯出詩曰：帷开見釵影，帘動聞钏聲，徘徊定不出，常羞華燭明。","sortOrder":58},
  {"id":"s_work_nvlt_18_59","chapterId":"ch_work_nvlt_18","text":"又見鄰舟人投一物眾姬爭之詩曰：河流既浼浼，河鳥复關關，落花浮浦出，飛雉度洲還，是日倡家女，競娇桃李顏，良人惜美珥，欲以代芳菅，新缣疑故素，盛趙蔑衰班，曳绡爭掩縠，搖珮奋鳴環，客心空振荡，乔枝不可攀。","sortOrder":59},
  {"id":"s_work_nvlt_18_60","chapterId":"ch_work_nvlt_18","text":"又淇上戲荡子婦詩曰：桑中始弈弈，淇上未湯湯，美人要雜佩，上客誘明璫，日暗人聲靜，微步上蘭房，露葵不待勸，鳴琴無暇張，翠釵掛已落，羅衣拂更香，如何嫁荡子，春夜守空床，未見青絲騎，徒勞紅粉妆。","sortOrder":60},
  {"id":"s_work_nvlt_18_61","chapterId":"ch_work_nvlt_18","text":"梁吳筠［按當作均，後同。］擬古詩曰：艳裔陽之春，携手清洛濱，雞鳴上林苑，薄暮小平津，長裾藻白日，廣袖帶芳尘，故交一如此，新知詎憶人。","sortOrder":61},
  {"id":"s_work_nvlt_18_62","chapterId":"ch_work_nvlt_18","text":"又古意詩曰：妾家橫塘北，發艳小長安，花釵玉宛轉，珠繩金絡紈，幂棡懸青鳳，逶迤搖白团，誰能分見此，含恨不相看。","sortOrder":62},
  {"id":"s_work_nvlt_18_63","chapterId":"ch_work_nvlt_18","text":"梁王僧孺陳南康新納詩曰：二八人如花，三五月如鏡，开帘一种色，還將兩相映。","sortOrder":63},
  {"id":"s_work_nvlt_18_64","chapterId":"ch_work_nvlt_18","text":"梁何思澄南苑逢美人詩曰：洛浦疑回雪，巫山似旦雲，傾城今始見，傾國昔曾聞，媚眼隨羞合，丹唇逐笑分，風卷蒲萄帶，日照石榴裙，自有狂夫在，空持勞使君。","sortOrder":64},
  {"id":"s_work_nvlt_18_65","chapterId":"ch_work_nvlt_18","text":"梁費昶春郊望美人詩曰：芳郊拾翠人，回袖探芳春，金辉起步搖，紅采發吹纶，陽陽蓋傾日，飄飄馬足尘，薄暮高樓下，當知妾姓秦。","sortOrder":65},
  {"id":"s_work_nvlt_18_66","chapterId":"ch_work_nvlt_18","text":"梁劉缓詠傾城人詩曰：不信巫山女，不信洛川神，何關別有物，還是傾城人，經共陳王戲，曾與宋家鄰，未嫁先名玉，來時本姓秦，粉光猶假面，朱色不勝唇，遙望疑花發，聞香知異春，夜夜言娇盡，日日態還新，已傾荀奉蒨，能迷石季倫，上客徒留目，不見正橫陳。","sortOrder":66},
  {"id":"s_work_nvlt_18_67","chapterId":"ch_work_nvlt_18","text":"梁鮑泉落日看還詩曰：妖姬競早春，上苑逐名臣，苔輕变水色，霞浓掩日輪，雕甍斜落景，畫扇拂遊尘，衣香遙已度，衫紅遠更新，誰家荡舟妾，何處織缣人。","sortOrder":67},
  {"id":"s_work_nvlt_18_68","chapterId":"ch_work_nvlt_18","text":"梁徐悱妻劉氏詩曰：花庭麗景斜，蘭牖輕風度，落日更新妆，开帘對芳树。","sortOrder":68},
  {"id":"s_work_nvlt_18_69","chapterId":"ch_work_nvlt_18","text":"又詩曰：東家挺奇麗，南國擅容辉，夜月方神女，朝霞喻洛妃。","sortOrder":69},
  {"id":"s_work_nvlt_18_70","chapterId":"ch_work_nvlt_18","text":"梁范靜妻沈戲萧娘詩曰：明珠翠羽帳，金薄绿绡帷，因風時暫舉，想像見芳姿，清晨插步搖，薄晚解羅衣，讬意風流子，佳情肯自私。","sortOrder":70},
  {"id":"s_work_nvlt_18_71","chapterId":"ch_work_nvlt_18","text":"陳伏知道詠人娉妾仍逐琴心詩曰：春色轉相催，佳人心自回，長卿琴已弄，秦嘉書未來，掛冠易分綬，荐枕缺因媒，染香風即度，登垣花正开，貞樓若高下，何如上陽台。","sortOrder":71},
  {"id":"s_work_nvlt_18_72","chapterId":"ch_work_nvlt_18","text":"陳徐陵春情詩曰：風光今旦動，雪色故年殘，薄衣迎新節，當爐却晚寒，故香分細煙，石炭捣輕紈，竹葉裁衣帶，梅花奠酒盤，年芳袖里出，春色黛中安，欲知迷下蔡，先將過上蘭。","sortOrder":72},
  {"id":"s_work_nvlt_18_73","chapterId":"ch_work_nvlt_18","text":"隋江總秋日新寵美人應令詩曰：後宮唯聞莫琼树，絕世後有宋容華，皆自爭名進女弟，定覺双飛勝荡家，原併迎春比翼燕，長作照日同心花，聞道艳歌時易調，忖許新恩那久要，翠眉未畫自生愁，玉脸含啼還似笑，角枕千娇荐芬香，若使琴心一曲奏，幽蘭度曲不可終，陽台夢里自應通，秋树相思一枝绿，為插賤妾兩鬟中。","sortOrder":73},
  {"id":"s_work_nvlt_18_74","chapterId":"ch_work_nvlt_18","text":"又新入姬人應令詩曰：洛浦流風漾淇水，秦樓初日度陽台，玉軼輕輪五香散，金燈夜火百光开，非是妖姬渡江日，定言神女隔河來，來時向月別姮娥，別時清吹悲萧史，數錢拾翠爭佳麗，拂紅點黛何相似，本持纖腰惑楚宮，暫回舞袖驚吳市，新人羽帳掛流蘇，故人網戶織蜘蛛，梅花柳色春難遍，情來春去在須臾，不用庭中賦绿草，但原思著弄明珠。","sortOrder":74},
  {"id":"s_work_nvlt_18_75","chapterId":"ch_work_nvlt_18","text":"【賦】楚宋玉登徒子好色賦曰：登徒子侍於楚王，短宋玉曰：玉為人體貌閒麗，口多微辭。又性好色，原王勿與出入後宮，王以登徒子之言問宋玉，玉曰：天下之佳人，莫若臣東家子，增之一分則太長，减之一分則太短，著粉太白，施朱太赤，眉如翠羽，肌如白雪，腰如束素，齒如含貝，嫣然一笑，惑陽城，迷下蔡，然此女登牆闚臣三年，至今未許也，登徒子則不然，其妻蓬頭挛耳，齞唇歷齒，旁行踽僂。又疥且痔，登徒子悅之，使有五子，王熟察之，誰為好色者矣，秦章華大夫在侧，因進而稱曰：臣周覽九土，足歷五都，從容鄭衛溱洧之間，是時向春之末，迎夏之陽，鸧鹒喈喈，群女出桑，此郊之姝，華色含光，體美容冶，不待飾妆，於是處子怳若有望而不來，忽若有來而不見，意密體疏，俯仰異觀，含喜微笑，竊视流盻，因遷延而辭避，目欲其顏，心顧其義，扬詩守禮，終不過差，故不足稱也。","sortOrder":75},
  {"id":"s_work_nvlt_18_76","chapterId":"ch_work_nvlt_18","text":"漢司馬相如美人賦曰：司馬相如，美麗閒都，遊於梁王，梁王悅之，邹陽谮之於王曰：相如美則美矣，然服色容冶，妖麗不忠，將欲媚辭取悅，遊王後宮，相如曰：古之避色，孔墨之徒，聞齊饋女而遐逝，望朝歌而回車，譬猶防火水中，避溺山隅，此乃未見其可欲，何以明不好色乎，若臣者，少長西土，鳏處獨居，室宇遼廓，莫與為娱，臣之東鄰，有一女子，玄發丰艳，蛾眉皓齒，登垣而望臣，三年於茲矣，臣弃而不許，聞大王之高義，命駕來東，途出鄭衛，道由桑中，朝發溱洧，暮宿上宮，上宮閒馆，寂寞重虛，門閤盡掩，暧若神居，芳香芬烈，黼帳高張，有女獨處，婉若在床，臣遂撫絃，為幽蘭之曲，女乃歌曰：獨處室兮廓無依，有美人兮來何遲，玉釵掛臣冠，羅袖拂臣衣，茵褥重陳，角枕橫施，女乃弛其上服，表其中衣，皓體呈露，弱骨丰肌，時來親臣，柔滑如脂，臣脈定於內，心正於懷，翻然高舉，與彼長辭。","sortOrder":76},
  {"id":"s_work_nvlt_18_77","chapterId":"ch_work_nvlt_18","text":"後漢張衡定情賦曰：夫何妖女之淑麗，光華艳而秀容，斷當時而呈美，冠朋匹而無双，叹曰：大火流兮草虫鳴，繁霜降兮草木零，秋為期兮時已征，思美人兮愁屏營。","sortOrder":77},
  {"id":"s_work_nvlt_18_78","chapterId":"ch_work_nvlt_18","text":"後漢蔡邕协初賦曰：其在近也，若神龍采鱗翼將舉，其既遠也，若披雲緣漢見織女，立若碧山亭亭竖，動若翡翠奋其羽，眾色燎照，视之無主，面若明月，辉似朝日，色若莲葩，肌如凝蜜。","sortOrder":78},
  {"id":"s_work_nvlt_18_79","chapterId":"ch_work_nvlt_18","text":"又檢逸賦曰：夫何姝妖之媛女，顏煒燁而含榮，普天壤其無俪，曠千載而特生，餘心悅於淑麗，愛獨結而未併，情罔象而無主，意徙倚而左傾，晝騁情以舒愛，夜讬夢以交靈。","sortOrder":79},
  {"id":"s_work_nvlt_18_80","chapterId":"ch_work_nvlt_18","text":"魏陳琳止欲賦曰：媛哉逸女，在餘東濱，色曜春華，艳過硕人，乃遂古其寡儔，固當世之無鄰，允宜國而寧家，實君子之攸嫔，伊餘情之是悅，志荒溢而傾移，宵蜅蜅以不寐，晝舍食而忘飢，叹北風之好我，美携手之同歸，忽日月之徐邁，庶枯楊之生稊，道攸長而路阻，河廣瀁而無梁，雖企予而欲往，非一苇之可航，展餘辔以言歸，含憯瘁而就床，忽假暝其若寐，夢所懽之來征，魂翩翩以遙懷，若交好而通靈。","sortOrder":80},
  {"id":"s_work_nvlt_18_81","chapterId":"ch_work_nvlt_18","text":"魏阮瑀止欲賦曰：夫何淑女之佳麗，顏〈火旬〉〈火旬〉以流光，歷千代其無匹，超古今而特章，執妙年之方盛，性聰惠以和良，禀純絜之明節，後申禮以自防，重行義以輕身，志高尚乎貞薑，予情悅其美麗，無須臾而有忘，思桃夭之所宜，原無衣之同裳，懷紆結而不畅兮，魂一夕而九翔，出房戶以踯躅，睹天漢之無津，傷匏瓜之無偶，悲織女之獨勤，還伏枕以求寐，庶通夢而交神，神惚怳而難遇，思交错以繽紛，遂終夜而靡見，東方旭以既晨，知所思之不得，乃抑情以自信。","sortOrder":81},
  {"id":"s_work_nvlt_18_82","chapterId":"ch_work_nvlt_18","text":"魏王粲閒邪賦曰：夫何英媛之麗女，貌洵美而艳逸，橫四海而無仇，超遐世而秀出，發唐棣之春華，當盛年而處室，恨年歲之方暮，哀獨立而無依，情紛挐以交橫，意惨凄而增悲，何性命之奇薄，愛兩絕而俱违，排空房而就衽，將取夢以通靈，目蜅蜅而不寐，心忉怛而惕驚。","sortOrder":82},
  {"id":"s_work_nvlt_18_83","chapterId":"ch_work_nvlt_18","text":"魏應玚正情賦曰：夫何媛女之殊麗兮，姿溫惠而明哲，應靈和以挺质，體蘭茂而琼絜，方往載其鮮双，曜來今而無列，發朝陽之鸿暉，流精睇而傾泄，既榮麗而冠時，援申女而比節，餘心嘉夫淑美，原結歡而靡因，承窈窕之芳美，情踴躍乎若人，魂翩翩而夕遊，甘同夢而交神，晝彷徨於路侧，宵耿耿而達晨，清風厲於玄序，因飆逝於中唐，聽雲雁之翰鳴，察列宿之華煇，南星晃而電陨，偏雄肅而特飛，冀騰言以俯音，嗟激迅而難追，傷住禽之無隅，悼流光之不歸，愍伏辰之方逝，哀吾原之多违，步便旋以永思，情憀栗而傷悲，還幽室以假寐，固展轉而不安，神妙妙以潛翔，恒存遊乎所觀，仰崇夏而長息，動哀响而餘叹，氣浮踴而雲馆，腸一夕而九煩。","sortOrder":83},
  {"id":"s_work_nvlt_18_84","chapterId":"ch_work_nvlt_18","text":"魏陳思王曹植靜思賦曰：夫何美女之娴妖，紅顏晔而流光，卓特出而無匹。呈才好其莫當，性通畅以聰惠，行孊密而妍詳，荫高岑以翳日，臨渌水之清流，秋風起於中林，離鳥鳴而相求，愁惨惨以增傷，悲予安能乎淹流。","sortOrder":84},
  {"id":"s_work_nvlt_18_85","chapterId":"ch_work_nvlt_18","text":"晉張華永懷賦曰：美淑人之妖艳，因盻睞而傾城，扬綽約之麗姿，懷婉娩之柔情，超六列於往古，邁來今之清英，既惠餘以至懽。又結我以同心，交恩好之款固，接情愛之分深，誓中誠於曒日，要執契以斷金，嗟夫，天道幽昧，差错谬於參差，怨祿運之不遭，雖義結而絕離，執纏綿之篤趣，守德音以終始，邀幸會於有期，冀容華之我俟，傥皇靈之垂仁，長收懽於永已。","sortOrder":85},
  {"id":"s_work_nvlt_18_86","chapterId":"ch_work_nvlt_18","text":"梁江淹麗色賦曰：夫絕世獨立者，信東鄰之佳人，既翠眉而瑤质，亦顱瞳而赪唇，洒金花及珠履，飒綺袂與錦紳，色練練而欲奪，光炎炎而若神，非氣象之可譬，焉影响而能陳，故仙藻靈葩，冰華玉儀，其始見也，若紅莲鏡池，其少進也，如采雲出崖，五光徘徊，十色陆離，寶過珊瑚同树，价直琼草共枝，於是雕台繡戺，當衢橫術，椒庭承月，碧戶延日，架虬柱之嚴麗，亘虹梁之峻密，錦幔垂而香寂，桂煙起而清謐，女乃曜邯鄲之鵕步，媚北里之鳴瑟，若夫紅華舒春，黃鳥飛時，绀蕙初软，赪蘭始滋，不掔蘅帶，無倚桂旗，摘芳拾蕊，涵詠吐辭，笑月出於陳歌，感蔓草於衛詩，氣炎日永，離明火中，堇榮任露，莲華勝風，後欄丹柰，前軒碧桐，笙歌畹右，琴舞池東，至乃西陆始秋，白道月絃，金波照戶，玉露暧天，氣以濕兮晓未半，星雖流兮夜何央，憶雜佩兮且一念，怜錦衾兮以九傷，於是帳必藍田之寶，席必蒲萄之文，馆圖明月，室畫浮雲，言必入媚，動必應規，有光有艳，如合如離，氣柔色靡，神凝骨奇，經秦歷趙，既無其双，尋楚訪蔡，不觌其容，非天下之至麗，孰能與於此哉。","sortOrder":86},
  {"id":"s_work_nvlt_18_87","chapterId":"ch_work_nvlt_18","text":"梁沈約麗人賦曰：有客弱冠未仕，締交戚里，馳骛王室，遨遊許史，歸而稱曰：狹斜才女，銅街麗人，亭亭似月，嬿婉如春，凝情待价，思尚衣巾，芳逾散麝，色茂开莲，陆離羽珮，雜错花钿，响羅衣而不進，隱明燈而未前，中步襜而一息，順長廊而回歸，池翻荷而納影，風動竹而吹衣，薄暮延佇，宵分乃至，出闇入光，含羞隱媚，垂羅曳錦，鳴瑤動翠，來脱薄妆，去留餘腻，霑妆委露，理鬢清渠，落花入領，微風動裾。","sortOrder":87},
  {"id":"s_work_nvlt_18_88","chapterId":"ch_work_nvlt_18","text":"◇賢婦人","sortOrder":88},
  {"id":"s_work_nvlt_18_89","chapterId":"ch_work_nvlt_18","text":"《毛詩》曰：柏舟，共薑自誓也，衛世子共伯蚤死，其妻守義，父母欲奪而嫁之，誓而弗許，故作是詩，以絕之也。","sortOrder":89},
  {"id":"s_work_nvlt_18_90","chapterId":"ch_work_nvlt_18","text":"《列女傳》曰：楚昭貞薑，齊侯之女，楚昭王之夫人也，昭王出遊，留夫人漸台之上而去，王聞江水大至，使使者迎夫人，忘持符，使者至，請夫人出，夫人曰：大王與宮人約，命曰：召宮［列女傳四，《太平御覽》四百四十一，宮下有人字。］必以符，今使者不持符，妾不敢從使者而行，妾聞之，貞女之義不犯約，勇者不畏死，守節而已，妾知從使者必生，留必死也，然妾不敢弃約，越義而求生，大水至而死，乃號曰貞薑。","sortOrder":90},
  {"id":"s_work_nvlt_18_91","chapterId":"ch_work_nvlt_18","text":"又曰：楚白貞姬者，楚白勝之妻也，白公早死，其妻紡績不嫁，吳王聞其美，使大夫操金百镒，白璧一双，以聘焉，因以辎軿三十乘迎之，將以為夫人，夫人辭曰：白公無恙時，妾幸得充後宮，執箕帚，今白公不幸而死，妾原守其墳墓，以終天年，今王賜金璧之聘，夫人之位，非愚妾之所聞也，吳王賢其守節而有義，號曰楚貞姬。","sortOrder":91},
  {"id":"s_work_nvlt_18_92","chapterId":"ch_work_nvlt_18","text":"又曰：魯秋胡絜婦者，魯秋胡之妻也，秋胡子既納之，五日而去，宦於陳，五年乃歸，未至家，見路傍有一美婦人，方采桑，秋胡子下車罻日，［列女傳五，《太平御覽》四百四十一作謂曰。］若曝獨采桑，吾行道遠，原讬桑陰下一食，婦人采桑不輟，秋胡子謂曰：力田不如逢少年，力桑不如見公卿，今吾有金，原與夫人，婦人曰：采桑力作，紡織經織，以供衣食，奉二親，養夫子而已矣，吾不原人之金也，秋胡子還家，奉金遺母，母使人呼其婦，婦乃向采桑婦，婦乃自投於河而死。","sortOrder":92},
  {"id":"s_work_nvlt_18_93","chapterId":"ch_work_nvlt_18","text":"又曰：梁寡高行者，梁之寡婦，早寡不嫁，梁貴人爭欲取之，不能得，梁王聞之，使相聘之，高行曰：妾之夫，不幸先犬馬填溝壑，妾宜以身荐棺椁，守養幼孤，不得专意，妾聞婦人之義，一往不改，以全貞信之節，弃義而從利，無以為人，乃援鏡操刀，以割其鼻，曰：妾已刑餘之人，殆可釋矣，王高其節，號曰高行。","sortOrder":93},
  {"id":"s_work_nvlt_18_94","chapterId":"ch_work_nvlt_18","text":"又曰：［《太平御覽》四百四十引作皇甫謐列女傳，下羅靜，景奇妻，相登妻，劉長卿妻，同。］漢中趙高［御覽作嵩。］妻者，同郡張氏之女也，字禮脩，姑嚴酷無道，小怒則骂，大怒則罰，禮脩恭承，初無慍色，引過自咎，姑後知之，乃变意，厚加愛敬，後姑疾病，其女來视，臨困，却女曰：我困矣，絕命當在賢婦之手，婦前抱持乃絕，後郡內遭賊，高死君難，禮脩以碧涂面，亂頭稱痛，懷刀在身，意氣烈决，賊不迫也，叔父矜其年壮，欲更嫁之，禮脩慷慨，至死為誓。","sortOrder":94},
  {"id":"s_work_nvlt_18_95","chapterId":"ch_work_nvlt_18","text":"又曰：丹陽羅靜者，廣德羅勤之女也，為同縣朱曠所聘，昏禮未成，勤遇病丧没，鄰比斷絕，曠觸冒經營，尋复病亡，靜感其義，遂誓不嫁，有楊祚者，多將人眾，自往納幣，靜乃逃竄，祚劫其弟妹，靜懼為祚所害，乃出見之曰：實感朱曠為妾父而死，是以讬身亡者，自誓不貳，辛苦之人，原君哀而舍之，如其不然，請守之以死，乃舍之。","sortOrder":95},
  {"id":"s_work_nvlt_18_96","chapterId":"ch_work_nvlt_18","text":"又曰：蜀景奇妻者，羅氏之女，字貢羅，奇亡無嗣，貢羅专心供養，父青以許同郡宰詩，貢羅與父書，陳其情志，歷年不歸，後青受遠使，詩白州，告縣，發遣貢羅，貢羅乃由径道，詣州白訴，言意慷慨，請死不從，州嘉而許焉。","sortOrder":96},
  {"id":"s_work_nvlt_18_97","chapterId":"ch_work_nvlt_18","text":"又曰：犍為相登妻者，名度，適登一年而寡，守令吳厚，因入問度，度引刀截發，縣長吏复遣媒介，度曰：前已斷發，謂之表心，何誤复有斯言哉，欲取刀割鼻，左右救止。","sortOrder":97},
  {"id":"s_work_nvlt_18_98","chapterId":"ch_work_nvlt_18","text":"又曰：沛郡劉長卿妻者，生一男，字玉，玉五歲而長卿卒，懼見謗［《太平御覽》四百四十作誘。］嫁，既不歸寧，兄弟時往，防漸遠疑，言不及外，玉年十五死，乃援刀割耳，明己不二，在丧侧者，無不感傷。","sortOrder":98},
  {"id":"s_work_nvlt_18_99","chapterId":"ch_work_nvlt_18","text":"又曰：［本條《太平御覽》三百六十七引，作列女後傳。又與下許昇妻條，同見御覽四百四十引，只作列女傳，當均出皇甫謐書。］吳孫奇妻者，廣陵范慎女，名姬，年十八，配奇一年而奇亡，慎以姬少寡無子，迎還其家，姬不肯歸，迎者以父母命迫之，姬遂操刀，割耳及鼻曰：父迎我者，不過以我年少而色美，今已殘矣，行將焉如，於是迎者空反。","sortOrder":99},
  {"id":"s_work_nvlt_18_100","chapterId":"ch_work_nvlt_18","text":"又曰：廣漢廖伯妻者，同郡段氏之女，名紀配，性聰敏，達於詩書，進退閒暇，父母將有所許，紀配曰：梁高行割鼻告誠，以全其節，求生害仁，仁者不為，紀配生見禮義，豈獨使古人擅名哉，作詩三章，以諷父母，乃援刀斷指。","sortOrder":100},
  {"id":"s_work_nvlt_18_101","chapterId":"ch_work_nvlt_18","text":"又曰：吳許升妻者，呂氏之女，名榮，升遊誕博戲，不治操行，榮躬勤家業，以養其姑，勸升學問，未嘗不垂淚而言，榮父疾升，呼榮，欲改嫁之，榮曰：命之所遭，義無離貳，終不肯歸，升後感悔，尋師遠學，四年乃歸，遂致名譽，為州所辟，遇劫被害，榮手刃殺升者，以首還祭。","sortOrder":101},
  {"id":"s_work_nvlt_18_102","chapterId":"ch_work_nvlt_18","text":"又曰：［按本條亦見後漢書列女傳，當亦出皇甫謐書。］河南貞義者，樂羊子之妻，羊子出學，貞義截發賣，以供其費，後羊子得遺金一餅，以與貞義，貞義曰：妾聞君子不以利洿行，羊子慚而弃之，鄰人欲犯貞義而劫其姑，貞義操刀而出，鄰人曰：從者可，不從者殺汝姑，貞義仰天而叹，以刀刎頸而死，太守以大夫禮葬之，號曰貞義。","sortOrder":102},
  {"id":"s_work_nvlt_18_103","chapterId":"ch_work_nvlt_18","text":"又曰：［《太平御覽》四百四十一引作皇甫謐列女傳。］留子直妻者，漢末扰攘，隨夫之從父，客居豫章，從父與賊交通，郡收族之，妻年少有色，太守客請以為妻，守死不從，以還太守，付吏殺之，臨死顏色不变，口無怨言，郡吏及客怜，更還救請免，既得活，乃自割耳，久之，太守聞其夫在，遂還其妻。","sortOrder":103},
  {"id":"s_work_nvlt_18_104","chapterId":"ch_work_nvlt_18","text":"又曰：［《太平御覽》五百引作列女後傳。］會稽翟素者，翟氏之女也，受聘，未及配適，遭亂，賊欲犯之，臨之以刃，曰：不從者，今即死矣，素曰：我可得而殺，不可得而辱，賊遂殺素。","sortOrder":104},
  {"id":"s_work_nvlt_18_105","chapterId":"ch_work_nvlt_18","text":"【詩】晉傅玄秋胡詩曰：秋胡納令室，三日宦他乡，皎皎絜婦姿，泠泠守空房，嬿娩不終夕，別如參與商，精誠馳萬里，既至兩相忘，行人悅令顏，借息此树傍，言以逢卿喻，遂下黃金裝。","sortOrder":105},
  {"id":"s_work_nvlt_18_106","chapterId":"ch_work_nvlt_18","text":"宋顏延之秋胡詩曰：燕居未及好，良人顧有违，脱巾千里外，結綬登王畿，戒徒在昧旦，左右來相依，蠶月觀時暇，桑野多經過，佳人從所務，窈窕援高柯，傾城誰不顧，弭節停中阿，南金豈不重，聊自意所輕，義心多苦調，密此金玉聲，如何久為別，百行愆諸己，愧彼行露詩，甘之長川涘。","sortOrder":106},
  {"id":"s_work_nvlt_18_107","chapterId":"ch_work_nvlt_18","text":"【贊】晉左九嫔班婕妤贊曰：恂恂班女，恭讓謙虛，辭輦進賢，辯祝理誣，形圖丹青，名侔樊虞。","sortOrder":107},
  {"id":"s_work_nvlt_18_108","chapterId":"ch_work_nvlt_18","text":"又孟軻母贊曰：邹母善导，三徙成教，鄰止庠序，俎豆是效，斷織激子，廣以墳奧，聰達知禮，敷述聖道。","sortOrder":108},
  {"id":"s_work_nvlt_18_109","chapterId":"ch_work_nvlt_18","text":"又狂接舆妻贊曰：接舆高絜，懷道行謠，妻亦冰清，同味玄昭，遺俗榮津，志遠神遼。","sortOrder":109},
  {"id":"s_work_nvlt_18_110","chapterId":"ch_work_nvlt_18","text":"又荆武王夫人邓曼贊曰：天道惡盈，極數則微，邈哉邓曼，心暎禍幾，睹兆叹亡，考德知衰，賢智卓殊，邈哉難追。","sortOrder":110},
  {"id":"s_work_nvlt_18_111","chapterId":"ch_work_nvlt_18","text":"又齊杞梁妻贊曰：遭命不改，逢時险屯，夫卒莒場，郊弔不賓，哀崩高城，訴情穹旻，遂赴淄川，讬軀清津。","sortOrder":111},
  {"id":"s_work_nvlt_18_112","chapterId":"ch_work_nvlt_18","text":"又齊義繼母贊曰：聖教玄化，禮貴信誠，至哉繼母，行合典經，不遺宿诺，義割私情，表德來裔，垂則後生。","sortOrder":112},
  {"id":"s_work_nvlt_18_113","chapterId":"ch_work_nvlt_18","text":"又魯敬薑贊曰：邈矣敬薑，含德之英，於行則高，於理斯明，垂訓於宗，厲發奇聲，宣尼三叹，萬代遺馨。","sortOrder":113},
  {"id":"s_work_nvlt_18_114","chapterId":"ch_work_nvlt_18","text":"晉滔鈕［按當作鈕滔，詳下荐環夫人書。］母孫氏公孫夫人序贊曰：夫人姓公孫氏，會稽剡人也，夫人資三靈之淳懿，誕華宗之澄粹，奇朗照於龆龀，四教成於弱笄，慈恩溫恭，行有秋霜之絜，祗心製節，性同青春之和，敦悅憲章，動遵禮規，居室則道齊師氏，有行則德配女儀，禮服有盈，笾豆無闕，猗欤夫人，天姿特挺，行高冰絜，操與霜整，性扬蘭芳，德振玉穎，猗彼琼林，奇翰有集，展彼硕媛，含德來緝，動與禮遊，靜以義立。","sortOrder":114},
  {"id":"s_work_nvlt_18_115","chapterId":"ch_work_nvlt_18","text":"【碑】晉張林陳夫人碑曰：夫人姓徐，吳郡嘉興人也，夫人少膺靈粹，誕茲淑貞，聰哲明敏，溫恭柔順，體仁足以長人，嘉德足以合禮，恭順不隋其心，明烈寔備其體，若夫柔惠清順，中和聖善，婦德既備，母道亦踐，志厲冰玉，厥德靡顯，靡靡其操，翼翼其仁，明景內暎，朗節外新，芳徽風邁，淑慎其身。","sortOrder":115},
  {"id":"s_work_nvlt_18_116","chapterId":"ch_work_nvlt_18","text":"【書】晉鈕［原訛鈞，據明本改，按晉書九十六虞潭母孫氏傳，卒謚定夫人，此當是與虞潭母書，鈕滔晉松陽令，見隋書經籍志集部。］滔母與虞定夫人荐環夫人書曰：琼聞興賢崇德，聖主令典，旌善表操，有邦盛務，伏見族祖吳國亡民富春孫彦妻環，少厲令節，服膺道教，逮適孫氏，恪居婦職，宗姻有聲，奉禮未周，彦母丧殒，丧殒半年，彦奄亡没，環率禮奉終，抗義明節，傾竭私產，以供葬送，禮服既終，前無立子，家欲改醮，誓而不許。","sortOrder":116},
  {"id":"s_work_nvlt_18_117","chapterId":"ch_work_nvlt_18","text":"【解】晉湛方生上貞女解曰：伏見西道縣治下里龍怜，年始弱笄，出適皮氏，未逾半年，婿京殒没，京兄弟三人，相尋凋落，外靡期功之親，內絕胤嗣之繼，怜货其父母之資，躬親機杼之勤，數年之間，三丧俱舉，四節蒸嘗，於今不輟，志存匪石之固，行無片言之玷，賢良屢聘，誓而弗許，守節窮居，於今五十餘年矣，詳觀之遺烈，［句有脱文。］書於記傳者，或毀發膚之體，以絕求者之望，或自經溝中，苟全不奪之志，雖操存而身亡，行立而形虧，寡能兼全其道，始終若斯者也，怜蓋草萊之婦人耳，生於幽穀之中，長於荒榛之下，目不見尺素之文，耳不聞今古之說，師心率己，蹈茲四德，抑可謂禀靈山嶽，自然天知者矣，而彤管未揮，令問不彰，非所以表賢崇善，激扬貞風也。","sortOrder":117},
  {"id":"s_work_nvlt_18_119","chapterId":"ch_work_nvlt_18","text":"《說文》曰：老，考也，七十曰耆，八十曰耋，九十曰耄。","sortOrder":119},
  {"id":"s_work_nvlt_18_120","chapterId":"ch_work_nvlt_18","text":"《釋名》曰：九十曰鲐背，或曰黃耇，或曰冻梨，或曰鲵齒，或曰眉寿。","sortOrder":120},
  {"id":"s_work_nvlt_18_121","chapterId":"ch_work_nvlt_18","text":"《易》曰：枯楊生荑，老夫得其女妻。","sortOrder":121},
  {"id":"s_work_nvlt_18_122","chapterId":"ch_work_nvlt_18","text":"《尚書》曰：五福，一曰寿。","sortOrder":122},
  {"id":"s_work_nvlt_18_123","chapterId":"ch_work_nvlt_18","text":"《禮記》曰：百年曰期颐。","sortOrder":123},
  {"id":"s_work_nvlt_18_124","chapterId":"ch_work_nvlt_18","text":"又曰：凡養老，有虞氏以燕禮，夏後氏以饗禮，殷人以食禮，周人脩而兼用之。","sortOrder":124},
  {"id":"s_work_nvlt_18_125","chapterId":"ch_work_nvlt_18","text":"又曰：六十養於國，七十養於學，八十拜君命，一坐再至。","sortOrder":125},
  {"id":"s_work_nvlt_18_126","chapterId":"ch_work_nvlt_18","text":"又曰：五十始衰，六十非肉不飽，七十非帛不暖。","sortOrder":126},
  {"id":"s_work_nvlt_18_127","chapterId":"ch_work_nvlt_18","text":"又曰：五十杖於家，六十杖於乡，七十杖於國，八十杖於朝。","sortOrder":127},
  {"id":"s_work_nvlt_18_128","chapterId":"ch_work_nvlt_18","text":"《毛詩》曰：執子之手，與子偕老。","sortOrder":128},
  {"id":"s_work_nvlt_18_129","chapterId":"ch_work_nvlt_18","text":"又曰：酌以大斗，以祈黃耇，黃耇鲐背，以引以翼。","sortOrder":129},
  {"id":"s_work_nvlt_18_130","chapterId":"ch_work_nvlt_18","text":"《左傳》曰：燭之武對鄭伯曰：臣之壮也，猶不如人，今老矣，無能為，［事具遊說篇。］","sortOrder":130},
  {"id":"s_work_nvlt_18_131","chapterId":"ch_work_nvlt_18","text":"又曰：晉悼大夫［《太平御覽》三百八十三作夫人。］食舆人，絳縣人或年長矣，使問之年，曰：臣小人也，不知紀年，臣生之歲，正月甲子朔，四百有四十五甲子矣，其年［御覽作季。］於今三之一也，使問諸師曠，曰：七十三矣。","sortOrder":131},
  {"id":"s_work_nvlt_18_132","chapterId":"ch_work_nvlt_18","text":"《論語讖》曰：尧舜遊首山，觀河渚，乃有五老遊河渚，曰：河圖將浮，五老飛為流星，上入昴。","sortOrder":132},
  {"id":"s_work_nvlt_18_133","chapterId":"ch_work_nvlt_18","text":"《國語》曰：昔衛武公年九十有五，警於國曰：苟在朝者，無謂我老耄而舍我也，必恭恪於朝，朝夕以警戒我，聞一二之言，必誦志而納之，以訓导我。","sortOrder":133},
  {"id":"s_work_nvlt_18_134","chapterId":"ch_work_nvlt_18","text":"《周書》曰：文王召太子發曰：呜呼，我身老矣，吾語汝，我所保與守，守之哉，傳之子孫，［事具帝王部。］","sortOrder":134},
  {"id":"s_work_nvlt_18_135","chapterId":"ch_work_nvlt_18","text":"《尚書·中候》曰：齊桓公封禪，謂管仲曰：寡人日暮，仲父年艾。","sortOrder":135},
  {"id":"s_work_nvlt_18_136","chapterId":"ch_work_nvlt_18","text":"《尸子》曰：湯問伊尹曰：寿可為耶，伊尹曰：王欲之則可為，弗欲則不可為也。","sortOrder":136},
  {"id":"s_work_nvlt_18_137","chapterId":"ch_work_nvlt_18","text":"《孟子》曰：伯夷避紂，居北海之濱，聞文王作，興曰：盍歸乎來，吾聞西伯善養老者，太公避紂，居東海之濱，聞文王作，興曰：盍歸乎來，吾聞西伯善養老者，二老者，天下之大老也。","sortOrder":137},
  {"id":"s_work_nvlt_18_138","chapterId":"ch_work_nvlt_18","text":"《戰國策》曰：昔者秦魏為與國，齊楚約攻魏，魏使人求救於秦，冠蓋相望，秦救不出，魏人有唐且者，年九十餘，謂魏王曰：老臣請西說秦，令兵出，可乎，曰：敬诺，遂約車遣之，且說秦王，秦王遂發兵救之。","sortOrder":138},
  {"id":"s_work_nvlt_18_139","chapterId":"ch_work_nvlt_18","text":"《史記》曰：秦始王謂王翦曰：將軍老矣，何怯也。","sortOrder":139},
  {"id":"s_work_nvlt_18_140","chapterId":"ch_work_nvlt_18","text":"又曰：武帝使使，束帛加璧，安車驷馬，迎申公，至見天子，天子問治亂事，申公時已年八十餘矣。","sortOrder":140},
  {"id":"s_work_nvlt_18_141","chapterId":"ch_work_nvlt_18","text":"又曰：伏生，秦博士，孝文欲求治尚書，天下無有，聞伏生能治，欲召之，是時伏生老不能行，詔晁错往受之。","sortOrder":141},
  {"id":"s_work_nvlt_18_142","chapterId":"ch_work_nvlt_18","text":"《韓詩外傳》曰：齊桓公見畝丘人曰：叟年幾何，對曰：臣年八十三矣，公曰：美哉寿也。","sortOrder":142},
  {"id":"s_work_nvlt_18_143","chapterId":"ch_work_nvlt_18","text":"又曰：楚丘先生，被蓑帶索，見孟嘗君，孟嘗君曰：先生老矣，春秋高矣，多遺忘矣，何以教文，先生曰：惡將我使而老哉，使我投石拔距乎，追車赴馬乎，吾則將死，何暇老哉，將使我深計而遠謀乎，設精神而决嫌疑，吾乃始壮矣，何老之有。","sortOrder":143},
  {"id":"s_work_nvlt_18_144","chapterId":"ch_work_nvlt_18","text":"《說苑》曰：楚文王伐鄭，使王子革子露車，二子出遊，老人載畚從乞焉，不與，搏而奪之畚。","sortOrder":144},
  {"id":"s_work_nvlt_18_145","chapterId":"ch_work_nvlt_18","text":"《漢書》曰：冯唐以老為郎，文帝輦過，問曰：父老何自為郎。","sortOrder":145},
  {"id":"s_work_nvlt_18_146","chapterId":"ch_work_nvlt_18","text":"又曰：張蒼口中無齒，飲乳，妻妾以百數，曾孕者不复幸，年百餘歲乃卒。","sortOrder":146},
  {"id":"s_work_nvlt_18_147","chapterId":"ch_work_nvlt_18","text":"又曰：張安世荐蘇武明習故事，奉使不辱，宣帝以武著節老臣，令朝朔望，號稱祭酒。","sortOrder":147},
  {"id":"s_work_nvlt_18_148","chapterId":"ch_work_nvlt_18","text":"《東觀漢記》曰：馬援年六十二，請击五溪蠻，帝愍其老，未許，援曰：臣尚能被甲上馬，帝令试之，援據鞍顧盻，以示可用，帝笑曰：矍鑠哉是翁，遂遣援，［事具武部將帥篇。］","sortOrder":148},
  {"id":"s_work_nvlt_18_149","chapterId":"ch_work_nvlt_18","text":"《續漢書》曰：民年七十者，授之以玉杖，餔之以糜粥，玉杖長九尺，端鳩飾，鳩，不噎之鳥也，欲老人不噎也。","sortOrder":149},
  {"id":"s_work_nvlt_18_150","chapterId":"ch_work_nvlt_18","text":"又曰：仲秋祠老人星於國南郊。","sortOrder":150},
  {"id":"s_work_nvlt_18_151","chapterId":"ch_work_nvlt_18","text":"《神仙傳》曰：淮南王安好道術，八公詣門，門者見垂白，不進，八公皆化成童子，色如桃花，門吏白王，王迎之，登思仙之台，八公還成老人，授之要道。","sortOrder":151},
  {"id":"s_work_nvlt_18_152","chapterId":"ch_work_nvlt_18","text":"《世說》曰：顧悅與簡文同年而早白，簡文問曰：卿何以先老，答曰：蒲柳之姿，望秋而落，松柏之姿，隆冬轉茂。","sortOrder":152},
  {"id":"s_work_nvlt_18_153","chapterId":"ch_work_nvlt_18","text":"《瀨乡記》曰：老聃計其年紀，時已一百餘，聃無老耄之貌也。","sortOrder":153},
  {"id":"s_work_nvlt_18_154","chapterId":"ch_work_nvlt_18","text":"《述異記》曰：尹雄年九十，左鬢生角，長寸半。","sortOrder":154},
  {"id":"s_work_nvlt_18_155","chapterId":"ch_work_nvlt_18","text":"【詩】魏應璩詩曰：古有行道人，陌上見三叟，年各百餘歲，相與鋤禾莠，住車問三叟，何以得此寿。","sortOrder":155},
  {"id":"s_work_nvlt_18_156","chapterId":"ch_work_nvlt_18","text":"又新詩曰：少壮面目泽，長老顏色粗，粗丑人所惡，拔白自洗蘇。","sortOrder":156},
  {"id":"s_work_nvlt_18_157","chapterId":"ch_work_nvlt_18","text":"魏阮瑀詩曰：白發隨櫛墜，未寒思厚衣，四支易懈倦，行步益疏遲，常恐時歲盡，魂魄忽高飛，自知百年後，堂上生旅葵，晉張載詩曰：氣力漸衰損，鬢發終以皓，昔為春月華，今為秋日草。","sortOrder":157},
  {"id":"s_work_nvlt_18_158","chapterId":"ch_work_nvlt_18","text":"晉陆機詩曰：软顏收紅蕊，玄鬢吐素華，冉冉逝將老，咄咄奈老何。","sortOrder":158},
  {"id":"s_work_nvlt_18_159","chapterId":"ch_work_nvlt_18","text":"梁范泰詩曰：在生竟何豫，未雲倏已老，華發飄悴容，苦慮栖懷抱，畴昔少年時，皆以歸大造。","sortOrder":159},
  {"id":"s_work_nvlt_18_160","chapterId":"ch_work_nvlt_18","text":"梁簡文帝詩曰：昔類紅莲草，自玩［原訛阮，據冯校本改。］渌池邊，今如白華树，還悲明鏡前。","sortOrder":160},
  {"id":"s_work_nvlt_18_161","chapterId":"ch_work_nvlt_18","text":"梁孔焘老詩曰：盛年歌吹日，顧步惜容儀，一朝衰朽至，星星白發垂。","sortOrder":161},
  {"id":"s_work_nvlt_18_162","chapterId":"ch_work_nvlt_18","text":"【表】梁沈約致仕表曰：徒以桑榆無幾，時製行及，不朝之禮，忽在今辰，使反身敝庐，待終窮巷，臣又聞之，懸車散發，其來舊矣，昔廣德請骸，義在量力，二疏知止，懼貽後悔，數年以來，稍就盡竭，氣力衰耗，不自支持，若蒙天地大恩，造物洪施，拯其隆滿之切，救其害盈之灾，譬彼日昃，假榮終朝，踟蹰夕景，少觀盛化，宅壤歸泉，自無雲幾，祈仁仰泽，事止寸陰。","sortOrder":162},
  {"id":"s_work_nvlt_18_163","chapterId":"ch_work_nvlt_18","text":"梁王僧孺為韦雍州致仕表曰：一旦攀附，遂無涯限，排雲矯漢，飛□待翼，陆離蝉組，照灼潘旗，受脤推轂，執珪奉酎，变狹室於高門，改小冠於侯服，况复還周紐其六印，歸齊列其五鼎，常懼輪輕載積，基薄墉高，器覆危傾，人指鬼瞰，老與年併，疾隨衰及，涂遙齒截，漏迫鍾鳴，高舂之景一斜，不周之風忽至，菌蟪夕陰，倏駛無幾，堇蕣朝采，飄零已及，仰朱闕而掩涕，向濛穀而自悲，豈复式瞻拱默，仰接鍾鼓，傥帷蓋未親，東嶽稍駐，击壤鼓腹，其賜猶多。","sortOrder":163},
  {"id":"s_work_nvlt_18_164","chapterId":"ch_work_nvlt_18","text":"周王裒為库狄峙致仕表曰：俯音赴曲，操終則外，傾身舉重，力殫斯毙，何者，日暮途遠，前哲所以告歸，漏盡載馳，昔賢以之知退，陳徐陵為王儀同致仕表曰：尺波歸海，恒叹不居，爝火為薪，猶悲假續，况复星回日薄，通人有乞老之言，鍾鳴漏盡，前史有夜行之誡，五陵鼎族，家傳軒冕，四姓乡侯，榮由恩泽，雖虛名靡實，世官非才，年力方彊，雖不能辭退，今三元肇慶，六呂司春，得奉萬寿之杯，豫參百辟之禮，便釋朝衣，謹遵初服，方同孔光之杖，載遊戶庭，廣德之車，方懸私馆。","sortOrder":164},
  {"id":"s_work_nvlt_18_165","chapterId":"ch_work_nvlt_18","text":"【疏】後漢班超上疏曰：蠻夷之俗，畏壮侮老，臣超犬馬齒耄，常恐年衰，奄忽僵仆，孤魂弃捐，自以寿終屯部，誠無所恨，但原生入玉門關，不敢望封酒泉郡。","sortOrder":165},
  {"id":"s_work_nvlt_18_166","chapterId":"ch_work_nvlt_18","text":"又曰：［又曰以下，明本無，冯校本雲，此一段宋本有之，然辭義實不屬，語亦不可解，今按其文義，蓋賦名實，疑自他篇竄入者，俟考。］其誠無徵名實，賦以言行，具可扬倫，上方委我朝杰，搜材儒門，若取火於燧，求玉於崑，且知人則哲，永矢不谖，詢乎譽則汝察乎德，摭其實則明试以言，夫名，實之賓，實者名立，正先修名以责實，亦徵言而考行，假使賢愚紛糾，是非交競，用舍不雜於薰莸，妍蚩豈逃乎龟鑒，若畴離祉，馴致其令，則傅說感於殷聰，驩兜迷於尧聖，原夫未分陶璧，尚混齊竽，議沓人口，聲喧路隅，乍好丹以非素，罕惡紫之奪朱，爭笐容於磻木，指彻瑕於瑾瑜，及夫舉直措枉，削繁省芜，轉衡用心，既不畏於狂絜，取賢□厦，求智又侔於炙輠，信垂拱而仰成，亦奚為而不可，懿其恭树桃李，假翼鵷鸞，仰春夏而延陰，面挟而遂轉，然後實無所蔽其跡，名無所匿其端，是二物也，坦然可觀。","sortOrder":166},
  {"id":"s_work_nvlt_18_167","chapterId":"ch_work_nvlt_18","text":"《藝文類聚》　唐·欧陽詢","sortOrder":167},
  {"id":"s_work_nvlt_19_1","chapterId":"ch_work_nvlt_19","text":"卷十九人部三","sortOrder":1},
  {"id":"s_work_nvlt_19_2","chapterId":"ch_work_nvlt_19","text":"○言語謳謠吟嘯笑","sortOrder":2},
  {"id":"s_work_nvlt_19_3","chapterId":"ch_work_nvlt_19","text":"◇言語","sortOrder":3},
  {"id":"s_work_nvlt_19_4","chapterId":"ch_work_nvlt_19","text":"《釋名》曰：言，宣也，宣彼此之意也，語，叙也，叙己所欲說述也。","sortOrder":4},
  {"id":"s_work_nvlt_19_5","chapterId":"ch_work_nvlt_19","text":"《說文》曰：直言曰言，論議曰語。","sortOrder":5},
  {"id":"s_work_nvlt_19_6","chapterId":"ch_work_nvlt_19","text":"《易》曰：君子出其言善，則千里之外應之，出其言不善，則千里之外违之。","sortOrder":6},
  {"id":"s_work_nvlt_19_7","chapterId":"ch_work_nvlt_19","text":"又曰：言行君子之枢機。","sortOrder":7},
  {"id":"s_work_nvlt_19_8","chapterId":"ch_work_nvlt_19","text":"《毛詩》曰：哿矣能言，巧言如流。","sortOrder":8},
  {"id":"s_work_nvlt_19_9","chapterId":"ch_work_nvlt_19","text":"又曰：無易由言。","sortOrder":9},
  {"id":"s_work_nvlt_19_10","chapterId":"ch_work_nvlt_19","text":"又曰：斯言之玷，不可為也。","sortOrder":10},
  {"id":"s_work_nvlt_19_11","chapterId":"ch_work_nvlt_19","text":"又曰：於時言言，於時語語。","sortOrder":11},
  {"id":"s_work_nvlt_19_12","chapterId":"ch_work_nvlt_19","text":"《左傳》曰：晉叔向適鄭，鬷篾惡，從收器者立於堂下，一言而善，叔向聞之曰：必鬷明也。","sortOrder":12},
  {"id":"s_work_nvlt_19_13","chapterId":"ch_work_nvlt_19","text":"又曰：鄭子大叔卒，趙簡子為之臨，甚哀，曰：黃父之會，夫子語我九言，曰：無始亂，無怙富，無恃寵，無违同，無傲禮，無驕能，無复怒，無謀非德，無犯非義。","sortOrder":13},
  {"id":"s_work_nvlt_19_14","chapterId":"ch_work_nvlt_19","text":"《禮記》曰：事君，大言入則望大利，小言入則望小利，故君子不以小言受大祿，不以大言受小祿。","sortOrder":14},
  {"id":"s_work_nvlt_19_15","chapterId":"ch_work_nvlt_19","text":"又曰：王言如絲，其出如纶，王言如纶，其出如綍。","sortOrder":15},
  {"id":"s_work_nvlt_19_16","chapterId":"ch_work_nvlt_19","text":"又曰：言不危行，行不危言。","sortOrder":16},
  {"id":"s_work_nvlt_19_17","chapterId":"ch_work_nvlt_19","text":"又曰：五方之人，言語不通。","sortOrder":17},
  {"id":"s_work_nvlt_19_18","chapterId":"ch_work_nvlt_19","text":"《大戴禮》曰：黃帝弱而能言，［事具帝王部。］","sortOrder":18},
  {"id":"s_work_nvlt_19_19","chapterId":"ch_work_nvlt_19","text":"《孝經》曰：言滿天下無口過，行滿天下無怨惡。","sortOrder":19},
  {"id":"s_work_nvlt_19_20","chapterId":"ch_work_nvlt_19","text":"《論語》曰：定公問，一言可以興邦，有諸，子曰：言不可以若是其幾也，一言可以丧邦，有諸，子曰：言不可以若是其幾也。","sortOrder":20},
  {"id":"s_work_nvlt_19_21","chapterId":"ch_work_nvlt_19","text":"又曰：君子欲讷於言而敏於行。","sortOrder":21},
  {"id":"s_work_nvlt_19_22","chapterId":"ch_work_nvlt_19","text":"又曰：法語之言，能無從乎，繹之為貴。","sortOrder":22},
  {"id":"s_work_nvlt_19_23","chapterId":"ch_work_nvlt_19","text":"《邓析書》曰：一言而非，驷馬不能追，一言不急，驷馬不能及，故惡言不出口，苛聲不入耳。","sortOrder":23},
  {"id":"s_work_nvlt_19_24","chapterId":"ch_work_nvlt_19","text":"《尸子》曰：言美則响美，言惡則响惡。","sortOrder":24},
  {"id":"s_work_nvlt_19_25","chapterId":"ch_work_nvlt_19","text":"《申子》曰：一言正，天下定，一言倚，天下靡。","sortOrder":25},
  {"id":"s_work_nvlt_19_26","chapterId":"ch_work_nvlt_19","text":"《莊子》曰：言者所以在意，得意而忘言，吾安得忘言之人，與之言哉。","sortOrder":26},
  {"id":"s_work_nvlt_19_27","chapterId":"ch_work_nvlt_19","text":"又曰：凡交近則必相靡以信，遠則必忠之以言。","sortOrder":27},
  {"id":"s_work_nvlt_19_28","chapterId":"ch_work_nvlt_19","text":"《鶡冠子》曰：趙武靈王問庞暖曰：寡人聞飛語流傳曰：戰百勝，非善之善者也。","sortOrder":28},
  {"id":"s_work_nvlt_19_29","chapterId":"ch_work_nvlt_19","text":"《淮南子》曰：得萬人之兵，不若聞一言之當。","sortOrder":29},
  {"id":"s_work_nvlt_19_30","chapterId":"ch_work_nvlt_19","text":"《漢書》曰：漢王與項羽臨廣武間而語。","sortOrder":30},
  {"id":"s_work_nvlt_19_31","chapterId":"ch_work_nvlt_19","text":"又曰：太尉周勃迎代王，請間，宋昌曰：所言公，公之，所言私，王者無私。","sortOrder":31},
  {"id":"s_work_nvlt_19_32","chapterId":"ch_work_nvlt_19","text":"又曰：韓信當斬，视滕公曰：不欲就天下乎，而斬壮士，滕公奇其言，壮其貌，弗斬，與語大悅之。","sortOrder":32},
  {"id":"s_work_nvlt_19_33","chapterId":"ch_work_nvlt_19","text":"《孫卿子》曰：赠人以言，重於珠玉，傷人以言，甚於劍戟。","sortOrder":33},
  {"id":"s_work_nvlt_19_34","chapterId":"ch_work_nvlt_19","text":"《吳志》曰：張尚，孫皓時為侍郎，以言語辯捷見知，括地圖曰：太極山采華之草，服之通萬里之語。","sortOrder":34},
  {"id":"s_work_nvlt_19_35","chapterId":"ch_work_nvlt_19","text":"衛玠別傳曰：太尉王君，見阮千里而問曰：老莊與聖教異，［《太平御覽》三百九十異上有同字。］阮曰：將無同，太尉善其言，辟之為掾，世號阮瞻三語掾，王君見而嘲之曰：一言可以辟，何假於三，阮曰：苟是天下民望，亦可無言而辟，复何假於一。","sortOrder":35},
  {"id":"s_work_nvlt_19_36","chapterId":"ch_work_nvlt_19","text":"《神仙傳》曰：老子生而能言。","sortOrder":36},
  {"id":"s_work_nvlt_19_37","chapterId":"ch_work_nvlt_19","text":"【詩】梁昭明太子大言詩曰：觀修鯤其若轍鲋，视沧海之如濫觴，經二儀而跼蹐，跨六合以翱翔。","sortOrder":37},
  {"id":"s_work_nvlt_19_38","chapterId":"ch_work_nvlt_19","text":"又細言詩曰：坐臥鄰空尘，凭附蟭螟翼，越咫尺而三秋，度毫釐而九息。","sortOrder":38},
  {"id":"s_work_nvlt_19_39","chapterId":"ch_work_nvlt_19","text":"梁殷鈞大言應令詩曰：噫氣為風，揮汗成雨，聊灼戴山龟，欲持探遂古。","sortOrder":39},
  {"id":"s_work_nvlt_19_40","chapterId":"ch_work_nvlt_19","text":"又細言應令詩曰：汎舟毛滴海，為政蜗牛國，逍遙輕尘上，指辰問南北。","sortOrder":40},
  {"id":"s_work_nvlt_19_41","chapterId":"ch_work_nvlt_19","text":"梁王規大言應令詩曰：俯身望日入，下视見星羅，噓八風而為氣，吹四海而扬波。","sortOrder":41},
  {"id":"s_work_nvlt_19_42","chapterId":"ch_work_nvlt_19","text":"又細言應令詩曰：針鋒於焉止息，發杪可以翱翔，蚊眉深而易阻，蚁目曠而難航。","sortOrder":42},
  {"id":"s_work_nvlt_19_43","chapterId":"ch_work_nvlt_19","text":"梁王錫大言應令詩曰：欲遊五嶽，迫不得申，杖千里之木，鱠橫海之鱗。","sortOrder":43},
  {"id":"s_work_nvlt_19_44","chapterId":"ch_work_nvlt_19","text":"又細言應令詩曰：冥冥藹藹，離朱不辯其實，步蜗角而三伏，經針孔而千日。","sortOrder":44},
  {"id":"s_work_nvlt_19_45","chapterId":"ch_work_nvlt_19","text":"梁張缵大言應令詩曰：河流既渴，日月俱騰，罝羅微物，動落雲鵬。","sortOrder":45},
  {"id":"s_work_nvlt_19_46","chapterId":"ch_work_nvlt_19","text":"又細言應令詩曰：遨遊蚁目辯輕尘，蚊睫成宇蝨如輪。","sortOrder":46},
  {"id":"s_work_nvlt_19_47","chapterId":"ch_work_nvlt_19","text":"梁沈約大言應令詩曰：隘此大汎庭，方知九陔局，窮天豈弥指，盡地不容足。","sortOrder":47},
  {"id":"s_work_nvlt_19_48","chapterId":"ch_work_nvlt_19","text":"又細言應令詩曰：开馆尺捶餘，筑榭微尘裹，蜗角列州縣，毫端建朝市。","sortOrder":48},
  {"id":"s_work_nvlt_19_49","chapterId":"ch_work_nvlt_19","text":"【賦】楚宋玉大言賦曰：楚襄王與唐勒景差宋玉，遊於陽雲之台，王曰：能為寡人大言者上座，王因稱曰：操是太阿戮一世，流血冲天，車不可以厲，至唐勒曰：壮士難兮絕天維，北斗戾兮太山夷，至宋玉曰：方地為車，圓天為蓋，長劍耿介倚天外，王曰：未可也，玉曰：併吞四夷，飲枯河海，跂越九州，無所容止。又小言賦曰：楚襄王既登陽雲之觀，命諸大夫景差唐勒宋玉等，併進大言賦，賦卒而宋玉受賞。","sortOrder":49},
  {"id":"s_work_nvlt_19_50","chapterId":"ch_work_nvlt_19","text":"又曰：有能為小言賦者，賜之雲夢之田，景差曰：戴氛埃兮垂漂尘，體輕蚊翼，形微蚤鱗，經由針孔，出入羅巾，唐勒曰：折飛糠以為舆，剖秕糟以為舟，凭〈虫兩〉眦以顧盼，附蠛蠓而遐遊。","sortOrder":50},
  {"id":"s_work_nvlt_19_51","chapterId":"ch_work_nvlt_19","text":"又曰：馆於蠅須，宴於毫端，亨蝨腦，切虮肝，會九族而同哜，猶委餘而不殫，宋玉曰：無內之中，微物潛生，比之無象，言之無名，蒙蒙景滅，昧昧遺形，纖於毳末之微篾，陋於茸毛之方生，视之則眇眇，望之則冥冥，離朱為之叹悶，神明不能察其情，二子之言，磊磊皆不小，何如此之為精，王曰善，賜雲夢之田。","sortOrder":51},
  {"id":"s_work_nvlt_19_52","chapterId":"ch_work_nvlt_19","text":"晉傅鹹小語賦曰：楚襄王登陽雲之台，景差唐勒宋玉侍，王曰：能為小語者處上位，景差曰：么蔑之子，形難為象，晨登蚁埃，薄暮不上，朝炊半粒，晝复得酿，亨一小蝨，飽於乡党，唐勒曰：攀蚊髯，附蚋翼，我自謂重彼不極，邂逅有急相切逼，竄於針孔以自匿，宋玉曰：折薜足以為擢，舫粒糠而為舟，將遠遊以遐覽，越蝉溺以橫浮，若涉海之無涯，懼湮没於洪流，弥數旬而汔濟，陟虮蚁之崇丘，未升半而九息，何時達乎杪頭。","sortOrder":52},
  {"id":"s_work_nvlt_19_53","chapterId":"ch_work_nvlt_19","text":"魏陳暄應詔語賦曰：覈生民之要技，實言語以為前，枢機誠為急務，筆札乃是次焉，擬金人於右階，稱石人於左邊，鄭侨戎服而無媿，張儀舌存而理痊，唯诺唯辯，何者是與，故知於時言言，於時語語，若乃遼城崄峻，齊陣交加，燕將恐懼，漢帝咄嗟，魯連才吐數句，郦子直御单車，息十重之萦帶，賢百萬之喧哗，至於蘭台靜秘，華燭高明，徐斟桂醑，缓奏秦聲，二三朋好，數四才英，既說前言之往行，重睹生死之交情，扼腕抵掌，攘袂盱衡，當斯時也，何者為榮，欲同吃如邓士載，欲作辯似娄君卿，為守為相併如此，少意少事不成名。","sortOrder":53},
  {"id":"s_work_nvlt_19_54","chapterId":"ch_work_nvlt_19","text":"【贊】魏王粲反金人贊曰：君子亮直，不柔辟，友賤不恥，誨焉是益，我能發蹤，彼用遠跡，一言之賜，過乎玙璧，末世不敦，義與茲易，而言匪忠，退有其謫。","sortOrder":54},
  {"id":"s_work_nvlt_19_55","chapterId":"ch_work_nvlt_19","text":"【箴】晉蘇彦語箴曰：孔子曰：餘欲無言。","sortOrder":55},
  {"id":"s_work_nvlt_19_56","chapterId":"ch_work_nvlt_19","text":"又曰：天何言哉，赫胥之世，大庭之治，玄風陶鼓，率直放志，熙熙群動，無欲無事，逮於三季，奔競茲彰，雷動風駭，飛辯雲翔，戰國紛扰，爭霸稱彊，爾乃遊說縱橫，騁技時王，衔刃懷毒，吐膏示芳，利動春露，害重冬霜，四紀若馳，七都翦亡，爰茲末俗，扇風簸颺，先意承旨，原情察乡，擯爾笾豆，和樂且康。","sortOrder":56},
  {"id":"s_work_nvlt_19_57","chapterId":"ch_work_nvlt_19","text":"【銘】周太廟金人銘曰：孔子觀周，入後稷廟，廟堂右階之前，有金人焉，三緘其口，而銘其背曰：我古之慎言人也，戒之哉，戒之哉，無多言，無多事，多言多败，多事多患，安樂必戒，無行所悔，勿謂何傷，其禍將長，勿謂何害，其禍將大，勿謂不聞，神將伺人，焰焰弗滅，炎炎若何，涓涓不壅，終為江河，綿綿不絕，或成網羅，毫末不札，將尋斧柯。","sortOrder":57},
  {"id":"s_work_nvlt_19_58","chapterId":"ch_work_nvlt_19","text":"晉孫楚反金人銘曰：晉太廟有石人焉，大張其口，而書其胸曰：我古之多言人也，無少言，無少事，少言少事，則後生何述焉，夫唯立言，名乃長久，胡為塊然，生鉗其口，凡夫貪财，烈士殉名，盜跖為濁，夷柳為清，鮑肆為臭，蘭圃為馨，莫貴澄清，莫賤滓秽，二者言異，歸於一會，尧懸諫鼓，舜立謗木，聽采風謠，惟日不足，道润群生，化隆比屋，末葉陵遲，禮教弥衰，承旨則順，忤意則违，時好細腰，宮中皆飢，時悅廣額，下作細眉，逆龍之鱗，必陷斯機，括囊無咎，乃免誅夷，顛覆厥德，可為傷悲，斯可用戒，無妄之時，假說周廟，於言為蚩，是以君子，追而正之。","sortOrder":58},
  {"id":"s_work_nvlt_19_59","chapterId":"ch_work_nvlt_19","text":"【論】晉欧陽建言盡意論曰：有雷同君子，問於违眾先生曰：世之論者，以為言不盡意，由來尚矣，至乎通才達識，鹹以為然，若夫蒋公之論眸子，鍾傅之言才性，莫不引此為談證，而先生以為不然，何哉，先生曰：夫天不言，而四時行焉，聖人不言，而鑒識存焉，形不待名，而方圓已著，色不俟稱，而黑白以彰，然則名之於物無施者也，言之於理無為者也，而古今務於正名，聖賢不能去言，其故何也，誠以理得於心，非言不畅，物定於彼，非言不辯，言不畅志，則無以相接，名不辯物，則鑒識不顯，鑒識顯而名品殊，言稱接而情志畅，原其所以，本其所由，非物有自然之名，理有必定之稱也，欲辯其實，則殊其名，欲宣其志，則立其稱，名逐物而遷，言因理而变，此猶聲發响應，形存影附，不得相與為二，苟其不二，則無不盡，吾故以為盡矣。","sortOrder":59},
  {"id":"s_work_nvlt_19_60","chapterId":"ch_work_nvlt_19","text":"◇謳謠","sortOrder":60},
  {"id":"s_work_nvlt_19_61","chapterId":"ch_work_nvlt_19","text":"《爾雅》曰：徒歌謂之謠。","sortOrder":61},
  {"id":"s_work_nvlt_19_62","chapterId":"ch_work_nvlt_19","text":"《毛詩》曰：心之忧矣，我歌且謠。","sortOrder":62},
  {"id":"s_work_nvlt_19_63","chapterId":"ch_work_nvlt_19","text":"《左傳》曰：宋城，華元為植，巡功，城者謳曰：睅其目，皤其腹，弃甲而复，於思於思，弃甲复來。","sortOrder":63},
  {"id":"s_work_nvlt_19_64","chapterId":"ch_work_nvlt_19","text":"《家語》曰：孔子相魯，齊人歸女樂，魯君淫荒，孔子遂行，師乙［太平御覽四百六十五作已。］送孔子曰：吾欲歌，可乎，歌曰：彼婦人之口，可以出走，彼婦人之謁可以死败，優哉遊哉，聊以卒歲。","sortOrder":64},
  {"id":"s_work_nvlt_19_65","chapterId":"ch_work_nvlt_19","text":"《列子》曰：尧微服遊康衢，童兒謠曰：立我蒸民，莫匪爾極，不識不知，順帝之則，［事具雜文部詩篇。］","sortOrder":65},
  {"id":"s_work_nvlt_19_66","chapterId":"ch_work_nvlt_19","text":"《韓子》曰：齊桓公飲酒醉，遺其冠，恥之，管仲曰：公不雪之以政，公曰：善，因發仓，賜貧窮，三日而民歌之曰：公胡不复遺其冠乎。","sortOrder":66},
  {"id":"s_work_nvlt_19_67","chapterId":"ch_work_nvlt_19","text":"《呂氏春秋》曰：魏襄王使史起為鄴令，引漳水灌田，民大得利，相與歌曰：鄴有聖令為史公，决漳水，灌鄴旁，終古斥滷生稻粱。","sortOrder":67},
  {"id":"s_work_nvlt_19_68","chapterId":"ch_work_nvlt_19","text":"《史記》曰：曹參為漢相國，百姓歌之曰：萧何為法，講若畫一，曹參代之，守而勿失，載其清靜，民以寧一。","sortOrder":68},
  {"id":"s_work_nvlt_19_69","chapterId":"ch_work_nvlt_19","text":"又曰：衛子夫為皇後，弟青貴震天下，天下歌之曰：生男無喜，生女無怒，獨不見衛子夫霸天下。","sortOrder":69},
  {"id":"s_work_nvlt_19_70","chapterId":"ch_work_nvlt_19","text":"《漢書》曰：趙中大夫白公奏川渠引涇水，民得其饒，歌之曰：田於何所，池陽穀口，鄭國在前，白渠起後，舉锸為雲，决渠為雨，涇水一石，其泥數斗，［事具產業部田篇。］","sortOrder":70},
  {"id":"s_work_nvlt_19_71","chapterId":"ch_work_nvlt_19","text":"又曰：冯立為西河上郡，在職公廉，與野王相代，治行相似而多恩，吏民乃歌曰：大冯君，小冯君，兄弟繼踵相因循，聰明聖智惠吏民，政如魯衛德化均，周公康叔猶二君。","sortOrder":71},
  {"id":"s_work_nvlt_19_72","chapterId":"ch_work_nvlt_19","text":"《東觀漢記》曰：張湛為漁陽太守，开田八千餘頃，勸民耕种，以致殷富，百姓歌曰：桑無附枝，麥秀兩歧，張君為政，樂不可欺，［事具職官部刺史篇。］","sortOrder":72},
  {"id":"s_work_nvlt_19_73","chapterId":"ch_work_nvlt_19","text":"又曰：廉范，字叔度，為蜀郡太守，舊製禁民夜作，以防火，范乃毀削先令，但嚴储水而已，百姓歌之曰：廉叔度，來何暮，不禁火，民安堵，昔無一襦，今有五袴，［事具職官部刺史篇。］","sortOrder":73},
  {"id":"s_work_nvlt_19_74","chapterId":"ch_work_nvlt_19","text":"《新序》曰：延陵季子，以劍帶徐君墓树，徐人歌之曰：延陵季子兮，不忘舊故，脱千金之劍，以帶丘墓，［事具懷舊篇。］","sortOrder":74},
  {"id":"s_work_nvlt_19_75","chapterId":"ch_work_nvlt_19","text":"謝承後漢書曰：岑胵遷魏郡大守，人歌之曰：我有枳棘，岑君伐之，我有蟊賊，岑君遏之，狗犬不驚，足下生氂，含哺鼓腹，焉知凶灾，我嘉我生，獨丁斯時，美哉岑君，於戲在茲。","sortOrder":75},
  {"id":"s_work_nvlt_19_76","chapterId":"ch_work_nvlt_19","text":"又曰：皇甫嵩，請冀州一年田租，以贍飢民，百姓歌曰：天下亂兮市為墟，母不保子妻失夫，賴得皇甫复汝居，［事具職官部刺史篇。］","sortOrder":76},
  {"id":"s_work_nvlt_19_77","chapterId":"ch_work_nvlt_19","text":"又曰：劉騊駼除摐陽長，以病免，吏民思而歌之曰：悒然不樂，思我劉君，何時复來，安此下民，［事具職官部縣令篇。］","sortOrder":77},
  {"id":"s_work_nvlt_19_78","chapterId":"ch_work_nvlt_19","text":"又曰：郭贺，字乔卿，為荆州刺史，到官有殊政，百姓歌曰：厥德仁明郭乔卿，忠正朝廷上下平，［事具職官部刺史篇。］","sortOrder":78},
  {"id":"s_work_nvlt_19_79","chapterId":"ch_work_nvlt_19","text":"續《漢書》曰：張霸為會稽郡，越賊歸附，童謠曰：弃我戟，捐我矛，盜賊盡，吏皆休。","sortOrder":79},
  {"id":"s_work_nvlt_19_80","chapterId":"ch_work_nvlt_19","text":"又曰：李燮拜京兆，詔發西園錢，君上封事，遂上［《太平御覽》四百六十五作止。］不發，吏民愛敬，乃謠曰：我府君，道教舉，恩如春，威如虎，刚不吐，弱不茹，愛如母，訓如父。","sortOrder":80},
  {"id":"s_work_nvlt_19_81","chapterId":"ch_work_nvlt_19","text":"《吳志》曰：周瑜少精意於音樂，三爵之後，其有闕誤，瑜必知之，知之必顧，時人謠曰：曲复誤，周郎顧。","sortOrder":81},
  {"id":"s_work_nvlt_19_82","chapterId":"ch_work_nvlt_19","text":"《吳錄》曰：王谭，字世容，為成武令，民服德化，宿惡奔迸，父老歌曰：王世容，治無双，省徭役，盜賊空。","sortOrder":82},
  {"id":"s_work_nvlt_19_83","chapterId":"ch_work_nvlt_19","text":"王隱《晉書》曰：王祥為本州別駕，時人歌曰：海沂之康，實賴王祥，邦國不空，別駕之功。","sortOrder":83},
  {"id":"s_work_nvlt_19_84","chapterId":"ch_work_nvlt_19","text":"又曰：裴秀年十歲餘，時人謠曰：後進領袖有裴秀。","sortOrder":84},
  {"id":"s_work_nvlt_19_85","chapterId":"ch_work_nvlt_19","text":"又曰：諸葛恢，字道明，荀闿，字道明，蔡謨，字道明，有名譽，號曰中興三明，時人歌之曰：京師三明各有名，蔡氏儒雅荀葛清。","sortOrder":85},
  {"id":"s_work_nvlt_19_86","chapterId":"ch_work_nvlt_19","text":"續安帝紀曰：司馬休之兄尚，為桓玄所败，休之奔淮泗，頗得彼之人心，從者為之歌曰：可怜司馬公，作性甚溫良，憶昔水邊戲，使我不能忘。","sortOrder":86},
  {"id":"s_work_nvlt_19_87","chapterId":"ch_work_nvlt_19","text":"《會稽典錄》曰：徐弘，字聖通，為汝陰令，誅鋤奸桀，道不拾遺，民歌之曰：徐聖通，政無双，平刑罰，奸宄空。","sortOrder":87},
  {"id":"s_work_nvlt_19_88","chapterId":"ch_work_nvlt_19","text":"《文士傳》曰：束晢，太康中大旱，晢乃令邑人躬共請雨，三日水三尺，百姓為之歌曰：束先生，通神明，請天三日甘雨零，我黍以育，我稷以生，何以酬之，報束長生。","sortOrder":88},
  {"id":"s_work_nvlt_19_89","chapterId":"ch_work_nvlt_19","text":"殷氏《世傳》曰：殷褒為滎陽令，廣筑學馆，會集朋徒，民知禮讓，乃歌曰：滎陽令，有異政，脩立學校人易性，令我子弟恥訟爭。","sortOrder":89},
  {"id":"s_work_nvlt_19_90","chapterId":"ch_work_nvlt_19","text":"車頻秦書曰：符堅時，關隴百姓丰樂，民歌之曰：長安大街，兩邊种槐，下走朱輪，上有鸞栖。","sortOrder":90},
  {"id":"s_work_nvlt_19_91","chapterId":"ch_work_nvlt_19","text":"趙書曰：劉曜讨陳安於隴域，安死，乃謠曰：隴城健兒曰陳安，體幹雖小腹中宽，愛養將士同心肝，［事具軍器∥篇。］","sortOrder":91},
  {"id":"s_work_nvlt_19_92","chapterId":"ch_work_nvlt_19","text":"趙書曰：汲桑，六月盛暑，重裘累茵，使人扇，患不清涼，斬扇者，時軍中為之謠曰：士為將軍何可羞，六月重茵被豹裘，不識寒暑斬他頭。","sortOrder":92},
  {"id":"s_work_nvlt_19_93","chapterId":"ch_work_nvlt_19","text":"《襄陽耆舊記》曰：山季倫每臨習池，未曾不大醉而還，恒曰：我高陽池中也，襄陽城中小兒歌之曰：山公何所去，往至高陽池，日夕倒載歸，酩酊無所知，時時能騎馬，倒著白接離，舉鞭向葛強，何如併州兒。","sortOrder":93},
  {"id":"s_work_nvlt_19_94","chapterId":"ch_work_nvlt_19","text":"《世說》曰：郤超王珣，併以俊才，為桓大司馬所眷，珣為主簿，超為記室參軍，超為人多須，珣形状短小，時人為之歌曰：髯參軍，短主簿，能令公喜，能令公怒。","sortOrder":94},
  {"id":"s_work_nvlt_19_95","chapterId":"ch_work_nvlt_19","text":"晉夏侯湛長夜謠曰：日暮兮初晴，天灼灼兮遐清，披雲兮歸山，垂景兮照庭，列宿兮皎皎，星稀兮月明，亭簷隅以逍遙兮，盻大虛以仰觀，望閶阖之昭晢兮，麗紫微之暉煥。","sortOrder":95},
  {"id":"s_work_nvlt_19_96","chapterId":"ch_work_nvlt_19","text":"晉湛方生懷歸謠曰：辭衡門兮至歡，懷生離兮苦辛，豈羁旅兮一慨，亦代謝兮感人，四運兮道盡，化新兮歲故，氣惨惨兮凝晨，風凄凄兮薄暮，雨雪兮交紛，重雲兮四布，天地兮一色，六合兮同素，山木兮摧披，津壑兮凝冱，感羁旅兮苦心，懷桑梓兮增慕，胡馬兮恋北，越鳥兮依陽，彼禽獸兮尚然，况君子兮去故乡，望歸涂兮漫漫，盻江流兮洋洋，思涉路兮莫由，欲越津兮無梁。","sortOrder":96},
  {"id":"s_work_nvlt_19_97","chapterId":"ch_work_nvlt_19","text":"陳沈蜅獨酌謠曰：獨酌謠，獨酌獨長謠，智者不我顧，愚夫餘未要，不愚复不智，誰當餘見招，所以成獨酌，一酌傾一瓢，生涯本漫漫，神理暫超超，一酌矜許史，再酌傲松乔，頻煩四五酌，不覺凌丹霄，倏忽厭五鼎，俄然賤九韶，彭殇無異葬，夷跖可同朝，龍蠖非不屈，鵬鷃但逍遙，寄語號呶侣，無乃大尘嚣。","sortOrder":97},
  {"id":"s_work_nvlt_19_99","chapterId":"ch_work_nvlt_19","text":"《說文》曰：吟，叹也。","sortOrder":99},
  {"id":"s_work_nvlt_19_100","chapterId":"ch_work_nvlt_19","text":"《釋名》曰：吟，嚴也，其聲本出於忧愁，故聲嚴肅，使聽之凄叹也。","sortOrder":100},
  {"id":"s_work_nvlt_19_101","chapterId":"ch_work_nvlt_19","text":"《毛詩序》曰：吟詠情性，以風其上。","sortOrder":101},
  {"id":"s_work_nvlt_19_102","chapterId":"ch_work_nvlt_19","text":"《鹽鐵論》曰：曾子傍山而吟，山鳥下翔。","sortOrder":102},
  {"id":"s_work_nvlt_19_103","chapterId":"ch_work_nvlt_19","text":"《東觀漢記》曰：梁鸿常閉戶吟詠書記。","sortOrder":103},
  {"id":"s_work_nvlt_19_104","chapterId":"ch_work_nvlt_19","text":"《魏志》曰：管辂隨軍西行，過毌丘俭墓下，倚松树哀吟，精神不樂，人問其故，辂曰：林木雖茂，無形可久，碑诔雖美，無後可守。","sortOrder":104},
  {"id":"s_work_nvlt_19_105","chapterId":"ch_work_nvlt_19","text":"陳武別傳曰：陳武，字國本，休屠胡人，常騎驢牧羊，諸家牧竖十數人，或有知歌謠者，武遂學太山梁父吟，幽州馬客吟及行路難之屬。","sortOrder":105},
  {"id":"s_work_nvlt_19_106","chapterId":"ch_work_nvlt_19","text":"《文士傳》曰：李康，清廉有志節，不能和俗，為乡里豪右所共害，故宦涂不進，作遊山九吟。","sortOrder":106},
  {"id":"s_work_nvlt_19_107","chapterId":"ch_work_nvlt_19","text":"蜀志諸葛亮梁父吟曰：步出齊城門，遙望荡陰里，里中有三墳，累累正相似，問是誰家冢，田強古冶子，力能排南山，文能絕地理，一朝被讒言，二桃殺三士，誰能為此謀，國相齊晏子。","sortOrder":107},
  {"id":"s_work_nvlt_19_108","chapterId":"ch_work_nvlt_19","text":"晉潘尼逸民吟曰：我顧傲，世自遺，舒志六合，由巢是追，沐浴池洪迅羽衣，陟彼名山，采此芝薇，朝雲叆叇，行露未晞，遊魚群戲，翔鳥双飛，逍遙博觀，日晏忘歸，嗟哉世士，從我者誰。","sortOrder":108},
  {"id":"s_work_nvlt_19_110","chapterId":"ch_work_nvlt_19","text":"雜字解詁曰：嘯，吹聲。","sortOrder":110},
  {"id":"s_work_nvlt_19_111","chapterId":"ch_work_nvlt_19","text":"《毛詩》曰：有女仳離，條其嘯矣遇人之不淑矣。","sortOrder":111},
  {"id":"s_work_nvlt_19_112","chapterId":"ch_work_nvlt_19","text":"《列女傳》曰：魯漆室邑之女，過時未適人，倚柱而嘯，傍人聞之，心莫不為之惨者，鄰婦從之遊曰：何嘯之悲也，子欲嫁乎，吾為子求偶，漆室女曰：吾豈為不嫁之故而悲哉，忧吾君老太子少也。","sortOrder":112},
  {"id":"s_work_nvlt_19_113","chapterId":"ch_work_nvlt_19","text":"《莊子》曰：童子夜嘯，鬼數若齒。","sortOrder":113},
  {"id":"s_work_nvlt_19_114","chapterId":"ch_work_nvlt_19","text":"《吳越春秋》曰：吳王阖闾，將欲伐楚，登台向南風而嘯，有頃而叹，群臣莫有晓王意者，伍子胥深知王忧，乃荐孫武，善為兵法，人莫知其能。","sortOrder":114},
  {"id":"s_work_nvlt_19_115","chapterId":"ch_work_nvlt_19","text":"《魏略》曰：諸葛亮在荆州遊學，每晨夜，常抱膝長嘯。","sortOrder":115},
  {"id":"s_work_nvlt_19_116","chapterId":"ch_work_nvlt_19","text":"《竹林七賢論》曰：阮籍，性樂酒，善嘯，聲聞數百步。","sortOrder":116},
  {"id":"s_work_nvlt_19_117","chapterId":"ch_work_nvlt_19","text":"又曰：籍常箕踞嘯歌，酣放自若，時蘇門山中，忽有真人在焉，籍親往尋，其人擁膝巖巔，遂登嶺從之，箕坐相對，籍乃商略終古以問之，仡然不應，籍因對之長嘯，有間，彼乃龂然笑曰：可更作，籍乃為嘯，意盡，退還半嶺，嶺巔〈口酋〉然有聲，若數部鼓吹，顧瞻乃向人之嘯也。","sortOrder":117},
  {"id":"s_work_nvlt_19_118","chapterId":"ch_work_nvlt_19","text":"孫登別傳曰：孫登，魏末處邛北山中，以石室為宇，編草自覆，阮嗣宗聞登而往造焉，適見苫蓋被發，端坐巖下鼓琴，嗣宗自下趍之，既坐，莫得與言，嗣宗乃嘲嘈長嘯，與鼓琴音諧會雍雍然，登乃逌爾而笑，因嘯和之，妙响動林壑，［事具樂府部琴篇。］","sortOrder":118},
  {"id":"s_work_nvlt_19_119","chapterId":"ch_work_nvlt_19","text":"《晉陽秋》曰：嵇康見孫登，登對之嘯，時不言。","sortOrder":119},
  {"id":"s_work_nvlt_19_120","chapterId":"ch_work_nvlt_19","text":"《郭子》曰：劉道真少時，善歌嘯，有一老姥，識其非常之人，甚樂其歌嘯，乃殺豚進之，道真食〈犭屯〉不謝。","sortOrder":120},
  {"id":"s_work_nvlt_19_121","chapterId":"ch_work_nvlt_19","text":"潯陽記曰：桓宣穆使人尋庐山，見一人謂之曰：君過前嶺，必逢二年少，相隨長嘯，试要問之，若不與言者，可速去，此人過嶺，果見二年少，以袂掩鼻長嘯，状如惡鼻，呼不與言。","sortOrder":121},
  {"id":"s_work_nvlt_19_122","chapterId":"ch_work_nvlt_19","text":"《世說》曰：晉文王德盛功大，坐席嚴敬，擬於王者，唯阮籍箕踞嘯歌，酣放自若。","sortOrder":122},
  {"id":"s_work_nvlt_19_123","chapterId":"ch_work_nvlt_19","text":"又曰：劉越石為胡騎所围，城中窘迫，劉乘月登樓清嘯，胡賊聞之，皆凄然長叹。","sortOrder":123},
  {"id":"s_work_nvlt_19_124","chapterId":"ch_work_nvlt_19","text":"《搜神記》曰：趙炳嘗臨水，從船人乞渡，船人不許，炳乃張蓋坐其中，長嘯呼風，亂流而濟。","sortOrder":124},
  {"id":"s_work_nvlt_19_125","chapterId":"ch_work_nvlt_19","text":"漢晉春秋曰：桓帝幸樊城，百姓莫不觀之，有一老父，獨耕不輟，議郎張溫使問焉，父嘯而不答。","sortOrder":125},
  {"id":"s_work_nvlt_19_126","chapterId":"ch_work_nvlt_19","text":"王廙別傳曰：王导與庾亮遊於石頭，會遇廙至，爾日迅風飛帆，廙倚樓而長嘯，神氣甚逸。","sortOrder":126},
  {"id":"s_work_nvlt_19_127","chapterId":"ch_work_nvlt_19","text":"神境記曰：滎［按水經註三十八湘水篇營水迳營陽郡治，孫皓分零陵置。又晉亦有營陽郡，見晉書地理志江州下，是滎當作營。］陽郡西有靈源山，有石髓紫芝，昔者有采藥此山，聞林穀間有長嘯者，今樵人往往猶聞焉。","sortOrder":127},
  {"id":"s_work_nvlt_19_128","chapterId":"ch_work_nvlt_19","text":"《異苑》曰：尋陽姑石，在江之坻，初桓玄至西下，令人登之，中嶺便聞長嘯，聲甚清澈，至峰，見一人箕踞石上。","sortOrder":128},
  {"id":"s_work_nvlt_19_129","chapterId":"ch_work_nvlt_19","text":"夢書曰：夢吹嘯者，欲有求。","sortOrder":129},
  {"id":"s_work_nvlt_19_130","chapterId":"ch_work_nvlt_19","text":"【詩】晉陆雲詩曰：逍遙近南畔，長嘯作悲叹。","sortOrder":130},
  {"id":"s_work_nvlt_19_131","chapterId":"ch_work_nvlt_19","text":"晉郭璞詩曰：绿羅結高林，蒙籠蓋一山，中有冥寂士，靜嘯撫清絃。","sortOrder":131},
  {"id":"s_work_nvlt_19_132","chapterId":"ch_work_nvlt_19","text":"【賦】晉成公綏嘯賦曰：逸群公子，體奇好異，傲世忘榮，絕弃人事，於是延友生，集同好，精性命之至機，研道德之玄奧，邈跨俗而遺身，乃慷慨而長嘯，發妙聲於丹唇，激哀音於皓齒，响抑扬而潛轉，氣冲鬱而熛起，协黃宮於清角，雜商羽於流徵，飄遊雲於泰清，集長風乎萬里，谅自然之至音，非絲竹之所擬，是故聲不假器，用不借物，近取諸身，役心御氣，動唇有曲，發口成音，觸類感物，因歌隨吟，清激切於竽笙，優润和於瑟琴，列列飆扬，啾啾响作，奏胡馬之長思，向寒風乎北朔。又似鸿雁之扬雏，群鳴號乎沙漠，故能因形創聲，隨事造曲，應物無窮，機發响速，乃吟詠而發散，聲繹繹而响連，心涤荡而無累，志離俗而飄然。","sortOrder":132},
  {"id":"s_work_nvlt_19_133","chapterId":"ch_work_nvlt_19","text":"晉殷仲堪將離詠曰：爾乃理辔杖策，或乘或步，行悲歌以諧歡，朗長嘯以啟路。","sortOrder":133},
  {"id":"s_work_nvlt_19_134","chapterId":"ch_work_nvlt_19","text":"【書】晉桓玄與袁宜都書論嘯曰：讀卿歌賦，序詠音聲，皆有清味，然以嘯為仿佛有限，不足以致幽旨，將未至耶，夫契神之音，既不俟多贍，而通其致，苟一音足以究清和之極，阮公之言，不動蘇門之聽，而微嘯一鼓，玄默為之解顏，若人之興逸响，惟深也哉。","sortOrder":134},
  {"id":"s_work_nvlt_19_135","chapterId":"ch_work_nvlt_19","text":"袁山松答桓南郡書曰：嘯有清浮之美，而無控引之深，歌窮测根之致，用之弥覺其遠，至乎吐辭送意，曲究其奧，豈唇吻之切發，一往之清泠而已哉，若夫阮公之嘯，蘇門之和，蓋感其一奇，何為徵此一至，大疑嘯歌所拘耶。","sortOrder":135},
  {"id":"s_work_nvlt_19_137","chapterId":"ch_work_nvlt_19","text":"《說文》曰：欣，笑喜也。","sortOrder":137},
  {"id":"s_work_nvlt_19_138","chapterId":"ch_work_nvlt_19","text":"《易》曰：同人，先號咷而後笑。","sortOrder":138},
  {"id":"s_work_nvlt_19_139","chapterId":"ch_work_nvlt_19","text":"又曰：旅人，先笑而後號咷。","sortOrder":139},
  {"id":"s_work_nvlt_19_140","chapterId":"ch_work_nvlt_19","text":"又曰：笑言哑哑。","sortOrder":140},
  {"id":"s_work_nvlt_19_141","chapterId":"ch_work_nvlt_19","text":"《毛詩》曰：終風且暴，顧我則笑，謔浪笑傲，中心是悼。","sortOrder":141},
  {"id":"s_work_nvlt_19_142","chapterId":"ch_work_nvlt_19","text":"又曰：兄弟不知，咥其笑矣。","sortOrder":142},
  {"id":"s_work_nvlt_19_143","chapterId":"ch_work_nvlt_19","text":"又曰：載笑載言。","sortOrder":143},
  {"id":"s_work_nvlt_19_144","chapterId":"ch_work_nvlt_19","text":"又曰：宴笑語兮。","sortOrder":144},
  {"id":"s_work_nvlt_19_145","chapterId":"ch_work_nvlt_19","text":"《左傳》曰：晉侯使郄克徵會於齊，齊頃公帷婦人，使觀之，郄子登，婦人笑於房。","sortOrder":145},
  {"id":"s_work_nvlt_19_146","chapterId":"ch_work_nvlt_19","text":"又曰：晉士弥牟送［《太平御覽》三百九十一作逆。］叔孫於箕，叔孫使梁其跮［御覽作踁。］待於門內，曰：餘左顧而欬，乃殺之，右顧而笑，乃止。","sortOrder":146},
  {"id":"s_work_nvlt_19_147","chapterId":"ch_work_nvlt_19","text":"《穀梁傳》曰：季孫行父禿，晉郄克跛，衛孫良夫眇，曹公子首僂，同聘於齊，齊使禿者御禿者，跛者御跛者，僂者御僂者，萧同叔子處台而笑之，客不悅，［事具治政部。］","sortOrder":147},
  {"id":"s_work_nvlt_19_148","chapterId":"ch_work_nvlt_19","text":"《論語》曰：子問公叔文子於公明贾曰：信乎夫子不言不笑不取乎，公明贾對曰：夫子時然後言，人不厭其言，樂然後笑，人不厭其笑，義然後取，人不厭其取。","sortOrder":148},
  {"id":"s_work_nvlt_19_149","chapterId":"ch_work_nvlt_19","text":"又曰：子遊為武城宰，子之武城，聞絃歌之聲，夫子莞爾而笑曰：割雞焉用牛刀。","sortOrder":149},
  {"id":"s_work_nvlt_19_150","chapterId":"ch_work_nvlt_19","text":"《禮斗威儀》曰：君桑土而王，其民人好大笑。","sortOrder":150},
  {"id":"s_work_nvlt_19_151","chapterId":"ch_work_nvlt_19","text":"《樂聲儀》曰：人情喜則笑矣。","sortOrder":151},
  {"id":"s_work_nvlt_19_152","chapterId":"ch_work_nvlt_19","text":"《老子》曰：下士聞道，大笑之，不笑，不足以為道。","sortOrder":152},
  {"id":"s_work_nvlt_19_153","chapterId":"ch_work_nvlt_19","text":"《晏子》曰：齊景公置酒泰山，公四望喟然叹，泣數行，曰：寡人將去此堂國者而死耶，左右泣者三人，晏子搏髀仰天大笑曰：樂哉今之飲也，公怒曰：子笑何也，對曰：臣見怯君一，諛臣三，是以大笑，公慚。","sortOrder":153},
  {"id":"s_work_nvlt_19_154","chapterId":"ch_work_nvlt_19","text":"琐語曰：師曠御晉平公鼓瑟，輟而笑曰：齊君與其嬖人戲，墜於床而傷其臂，平公命人書之曰：某月某日，齊君戲而傷，問之於齊侯，笑曰：然，有之。","sortOrder":154},
  {"id":"s_work_nvlt_19_155","chapterId":"ch_work_nvlt_19","text":"《楚辭》曰：若有人兮山之阿，被薜荔兮帶女萝，既含睇兮又宜笑，子慕予兮善窈窕。","sortOrder":155},
  {"id":"s_work_nvlt_19_156","chapterId":"ch_work_nvlt_19","text":"又曰：行不群以顛越兮。又眾兆之所咍。","sortOrder":156},
  {"id":"s_work_nvlt_19_157","chapterId":"ch_work_nvlt_19","text":"《呂氏春秋》曰：戎常寇周，幽王击鼓，諸侯皆至，襃姒大悅而笑，王欲襃姒之笑，數击鼓而諸侯至，無寇，及真寇至，击鼓而諸侯不來，遂為戎所滅。","sortOrder":157},
  {"id":"s_work_nvlt_19_158","chapterId":"ch_work_nvlt_19","text":"《史記》曰：孫子试兵，以王寵姬二人，以為軍队長，三鼓，宮女皆掩口而笑。","sortOrder":158},
  {"id":"s_work_nvlt_19_159","chapterId":"ch_work_nvlt_19","text":"又曰：孟嘗君過趙平原君客之，趙人聞孟嘗君賢，出觀之，皆大笑曰：始以薛公為魁梧也，然今视之，乃眇小丈夫耳。","sortOrder":159},
  {"id":"s_work_nvlt_19_160","chapterId":"ch_work_nvlt_19","text":"又曰：高祖奉玉卮為太上皇寿，曰：始大人常以臣無賴，不能治產業，不如仲力，今某之業所就，孰與仲多，殿上群臣皆呼萬歲，大笑為樂。","sortOrder":160},
  {"id":"s_work_nvlt_19_161","chapterId":"ch_work_nvlt_19","text":"《漢書》曰：匡衡能解詩，諸儒為之語曰：無說詩，匡鼎來，匡說詩，解人颐，［事具雜部詩篇。］","sortOrder":161},
  {"id":"s_work_nvlt_19_162","chapterId":"ch_work_nvlt_19","text":"《蜀志》曰：馬忠為人宽濟，有度量，但大笑而已，忿怒不形於色。","sortOrder":162},
  {"id":"s_work_nvlt_19_163","chapterId":"ch_work_nvlt_19","text":"《晉中興書》曰：石勒與李陽相近，陽性刚愎，每爭漚麻池，共相扑打，互有勝負，勒既貴，召陽至，引入，言及平生，酒酣，宣陽肘曰：卿年老，臂中故有力不，頗复與人斗耶，孤往數得卿拳，卿亦快得孤毒手，因大笑。","sortOrder":163},
  {"id":"s_work_nvlt_19_164","chapterId":"ch_work_nvlt_19","text":"又曰：勒治門閤至峻，有醉胡乘馬，径入府門，勒問門吏冯翥，向走馬入門，為是何人，翥惶遽，誤對忘讳，向有醉胡，乘馬馳來，即已诃問，胡人難與語，非小吏所製，勒笑曰：胡正自難可與言。","sortOrder":164},
  {"id":"s_work_nvlt_19_165","chapterId":"ch_work_nvlt_19","text":"蜀記曰：谯周，字允南，體濬素朴，無造次辯論之才，諸葛亮領益州牧，州［《太平御覽》三百九十一作周。］為勸學從事，初見，左右皆笑，既出，有司請推笑者，亮曰：孤欲不能忍，况左右乎。","sortOrder":165},
  {"id":"s_work_nvlt_19_166","chapterId":"ch_work_nvlt_19","text":"《世說》曰：張華問陆機曰：雲何以不來，機曰：雲有笑疾，恐公未悉，故未敢，俄而雲詣華，華為人多姿製。又好帛纏須，雲見而大笑，不能自已。","sortOrder":166},
  {"id":"s_work_nvlt_19_167","chapterId":"ch_work_nvlt_19","text":"又曰：陆雲好笑，嘗著縗帻上舡，水中自見其影，便大笑不已，幾落水。","sortOrder":167},
  {"id":"s_work_nvlt_19_168","chapterId":"ch_work_nvlt_19","text":"又曰：桓南郡與道曜講老子，王侍中為主簿，在坐，桓公曰：王主簿可顧名思義，王未有答，且大笑，桓公曰：王思道故能作大家兒笑。","sortOrder":168},
  {"id":"s_work_nvlt_19_169","chapterId":"ch_work_nvlt_19","text":"【賦】晉孫楚笑賦曰：有度俗之公子，總萬物之細故，心仿佛乎巢由，以得意為至樂，不拘恋乎凡流，會親戚於高宇，結宗盟於綢缪，所以交頸偃仰，推匈指掌，冗洪聲於通穀，順長風以流响，氣參谭以相屬，若將頹而复往，或嚬蹙俛首，状似悲愁，怫鬱唯轉，呻S吟Y鬱伊，或携手悲嘯，噓天長叫，遲重則如陆沉，輕疾則如水漂，徐疾任其口頰，員合得乎機要，或中路背叛，更相毀賤，傾倚叵我，彫聲迄乎日晏，信天下之笑林，調謔之巨觀也。","sortOrder":169},
  {"id":"s_work_nvlt_19_170","chapterId":"ch_work_nvlt_19","text":"《藝文類聚》　唐·欧陽詢","sortOrder":170},
  {"id":"s_work_nvlt_20_1","chapterId":"ch_work_nvlt_20","text":"卷二十人部四","sortOrder":1},
  {"id":"s_work_nvlt_20_2","chapterId":"ch_work_nvlt_20","text":"○聖賢忠孝","sortOrder":2},
  {"id":"s_work_nvlt_20_4","chapterId":"ch_work_nvlt_20","text":"《尚書》曰：睿作聖。","sortOrder":4},
  {"id":"s_work_nvlt_20_5","chapterId":"ch_work_nvlt_20","text":"又曰：聖作則。","sortOrder":5},
  {"id":"s_work_nvlt_20_6","chapterId":"ch_work_nvlt_20","text":"《莊子》曰：以德分人謂之聖。","sortOrder":6},
  {"id":"s_work_nvlt_20_7","chapterId":"ch_work_nvlt_20","text":"《白虎通》曰：才稱萬人曰杰，倍杰曰聖，《風俗通》曰：聖者，聲也，通也，言其聞聲知情，通於天地，條畅萬物也。","sortOrder":7},
  {"id":"s_work_nvlt_20_8","chapterId":"ch_work_nvlt_20","text":"《家語》曰：聖者，德合天地，变通無方也。","sortOrder":8},
  {"id":"s_work_nvlt_20_9","chapterId":"ch_work_nvlt_20","text":"《易》曰：備物致用，立成器以為天下利，莫大乎聖人，知進退存亡而不失其正者，其唯聖人乎。","sortOrder":9},
  {"id":"s_work_nvlt_20_10","chapterId":"ch_work_nvlt_20","text":"《禮記》曰：大哉聖人之道，洋洋乎發育萬物，峻極於天，譬如天地之無不持載，無不覆焘，譬如四時之错行，如日月之代明。","sortOrder":10},
  {"id":"s_work_nvlt_20_11","chapterId":"ch_work_nvlt_20","text":"又曰：唯天下至聖，為能聰明叡智，足以有臨也，發強刚毅，足以有執也，斋莊中正，足以有敬也，文理密察，足以有別也。","sortOrder":11},
  {"id":"s_work_nvlt_20_12","chapterId":"ch_work_nvlt_20","text":"《毛詩》曰：周公攝政，遠則四國流言，近則王不知，周大夫美不失其聖也。","sortOrder":12},
  {"id":"s_work_nvlt_20_13","chapterId":"ch_work_nvlt_20","text":"又曰：思齊，文王所以聖也。","sortOrder":13},
  {"id":"s_work_nvlt_20_14","chapterId":"ch_work_nvlt_20","text":"《大戴禮》曰：聖人有國，則日月不食，星辰不孛。","sortOrder":14},
  {"id":"s_work_nvlt_20_15","chapterId":"ch_work_nvlt_20","text":"又曰：哀公問曰：何謂聖人，孔子對曰：所謂聖人者，智通乎大道，應变而不窮，测物之情性者也。","sortOrder":15},
  {"id":"s_work_nvlt_20_16","chapterId":"ch_work_nvlt_20","text":"《論語》曰：太宰問於子貢曰：夫子聖者與，何其多能也，子貢曰：固天縱之將聖。又多能也。","sortOrder":16},
  {"id":"s_work_nvlt_20_17","chapterId":"ch_work_nvlt_20","text":"《禮記》曰：聖人能以天下為一家，中國為一人者，非意之也，必知其利，達於其患，然後能為之。","sortOrder":17},
  {"id":"s_work_nvlt_20_18","chapterId":"ch_work_nvlt_20","text":"《家語》：國有聖人而不能用，欲以求治，是猶却步而求及前人也。","sortOrder":18},
  {"id":"s_work_nvlt_20_19","chapterId":"ch_work_nvlt_20","text":"《六韜》曰：聖人與天下之人皆安樂。","sortOrder":19},
  {"id":"s_work_nvlt_20_20","chapterId":"ch_work_nvlt_20","text":"又曰：聖人守無窮之府，用無窮之才，天下仰之而治。","sortOrder":20},
  {"id":"s_work_nvlt_20_21","chapterId":"ch_work_nvlt_20","text":"《管子》曰：聖人若天然，無私覆，若地然，無私載也，私者亂天下也。","sortOrder":21},
  {"id":"s_work_nvlt_20_22","chapterId":"ch_work_nvlt_20","text":"《老子》曰：聖人無常心，以百姓心為心，善者吾善之，不善者吾亦善之。","sortOrder":22},
  {"id":"s_work_nvlt_20_23","chapterId":"ch_work_nvlt_20","text":"《文子》曰：聖人同死生，愚人亦同死生，聖人之同死生，明於分理也，愚人之同死生，不知利害所在也。","sortOrder":23},
  {"id":"s_work_nvlt_20_24","chapterId":"ch_work_nvlt_20","text":"又曰：聖人以仁義為准繩，中繩之謂君子，不中繩之謂小人。","sortOrder":24},
  {"id":"s_work_nvlt_20_25","chapterId":"ch_work_nvlt_20","text":"《列子》曰：龍叔謂文挚曰：吾有疾，子能已乎，文挚即命龍叔背明而立，文挚從後向明而望之，既而曰：嘻，吾見子之心矣，方寸之地虛矣，幾聖人也，子心六孔流通，一孔不達，今聖智為病者，或由此乎。","sortOrder":25},
  {"id":"s_work_nvlt_20_26","chapterId":"ch_work_nvlt_20","text":"又曰：商太宰見孔子曰：丘聖者與，答曰：聖則丘何敢，曰：三王聖者與，答曰：三王善任智勇者，聖則丘弗知，曰：五帝聖者與，答曰：五帝善任仁義者，聖則丘弗知，曰：三皇聖者與，答曰：三皇善因時者，聖則丘弗知，商曰：然則孰者為聖，孔子曰：西方聖者，不治而不亂，不言而自信，不化而自行，荡荡乎民無能名焉。","sortOrder":26},
  {"id":"s_work_nvlt_20_27","chapterId":"ch_work_nvlt_20","text":"又曰：庖犧女媧神農夏後，蛇身人面牛首，此非人之状，而有大聖之德，［事具帝王部女媧篇。］","sortOrder":27},
  {"id":"s_work_nvlt_20_28","chapterId":"ch_work_nvlt_20","text":"《孟子》曰：觀於海者難為水，遊於聖人之門者難為言。","sortOrder":28},
  {"id":"s_work_nvlt_20_29","chapterId":"ch_work_nvlt_20","text":"《莊子》曰：夫卜梁倚有聖人之才者，而無聖人之道，我有聖人之道，而無聖人之才，吾教之其果為聖人也。","sortOrder":29},
  {"id":"s_work_nvlt_20_30","chapterId":"ch_work_nvlt_20","text":"又曰：尧辭封人曰：我以汝為聖人，曰：夫聖人鶉居而鷇食，鳥行而無跡，天下有道，則與物皆昌，天下無道，則修德就間，千歲厭世，去而上仙，乘彼白雲，至於帝乡，三患莫至，身常無殃，則何辱之有。","sortOrder":30},
  {"id":"s_work_nvlt_20_31","chapterId":"ch_work_nvlt_20","text":"《孫卿子》曰：神固謂之聖人，聖人者道之管也，天下之道管此矣。","sortOrder":31},
  {"id":"s_work_nvlt_20_32","chapterId":"ch_work_nvlt_20","text":"又曰：天下無二道，聖人無兩心，神人無功，聖人無名，聖人者天下利器。","sortOrder":32},
  {"id":"s_work_nvlt_20_33","chapterId":"ch_work_nvlt_20","text":"《淮南子》曰：聖人不貴尺璧而重寸陰，故禹之趍時也，履遺而弗取，冠掛而弗顧。","sortOrder":33},
  {"id":"s_work_nvlt_20_34","chapterId":"ch_work_nvlt_20","text":"又曰：唯聖人為能知權，言而必信，期而必當，天下之高行也。","sortOrder":34},
  {"id":"s_work_nvlt_20_35","chapterId":"ch_work_nvlt_20","text":"又曰：孔子不黔突，墨子不暖席，是故聖人蒙恥辱以幹世主者，非以貪祿慕位，欲事天下之利，除萬民之害也，神農憔悴，尧瘦臞，舜微黑，禹胼胝，由此觀之，則聖人之忧勞百姓亦甚矣。","sortOrder":35},
  {"id":"s_work_nvlt_20_36","chapterId":"ch_work_nvlt_20","text":"又曰：古者聖人，勞形盡慮，為民興利除害，羸天下之忧，而任海內之事，聖人之忧民，如此其明也。","sortOrder":36},
  {"id":"s_work_nvlt_20_37","chapterId":"ch_work_nvlt_20","text":"楊子《法言》曰：或問孔子之時，諸侯有知孔子聖者與，曰：知之，若知之則曷為不用，曰：不能，曰：知聖而不能用，可得聞乎，曰：用之則弃其所習，逆其所從，彊其所劣，捐其所能，非天下之至，孰能用之。","sortOrder":37},
  {"id":"s_work_nvlt_20_38","chapterId":"ch_work_nvlt_20","text":"《韓詩外傳》曰：辟土殖穀者，後稷也，决江疏河者，禹也，聽獄執中者，皋陶也，然而有聖名者，尧也。","sortOrder":38},
  {"id":"s_work_nvlt_20_39","chapterId":"ch_work_nvlt_20","text":"《神異經》曰：西南大荒中，人身長十丈，其腹围九丈，踐龟蛇，戴朱鳥，左手凭青龍，右手凭白虎，知河海斗斛，識山石多少，知天下鳥獸言語，識土上人所道，知百穀可食，識草木鹹苦，名曰聖，一曰哲，一名通，一名無不達。","sortOrder":39},
  {"id":"s_work_nvlt_20_40","chapterId":"ch_work_nvlt_20","text":"《尚書大傳》曰：天無別風淮雨，中國有聖人。","sortOrder":40},
  {"id":"s_work_nvlt_20_41","chapterId":"ch_work_nvlt_20","text":"姚信士緯曰：聖人高不可極，深不可测，窮神知化，獨見先識，仁若春陽，信若影响，此所禀於天也。","sortOrder":41},
  {"id":"s_work_nvlt_20_42","chapterId":"ch_work_nvlt_20","text":"《說苑》曰：聖人之於百姓也，其猶赤子乎，飢者食之，寒者衣之，將之養之，育之長之，唯恐其不至於大也。","sortOrder":42},
  {"id":"s_work_nvlt_20_43","chapterId":"ch_work_nvlt_20","text":"【頌】後漢張超尼父頌曰：巖巖孔聖，異世稱杰，量合乾坤，明參日月，德被八荒，名充遐外，終於獲麟，遺歌魯衛。","sortOrder":43},
  {"id":"s_work_nvlt_20_44","chapterId":"ch_work_nvlt_20","text":"晉孫楚尼父頌曰：皇矣尼父，聖哲之杰，德比天地，明齊日月，周室陵遲，大道芜秽，禮樂崩阻，奸雄罔世，乃養門徒，廣延俊乂，垂訓列國，頌聲魯衛，威震夹穀，義厭陳蔡，德之休明，幽而弥泰，超美三代，風馳雲邁。","sortOrder":44},
  {"id":"s_work_nvlt_20_45","chapterId":"ch_work_nvlt_20","text":"【贊】晉陆機孔子贊曰：孔子叡聖，配天弘道，風扇玄流，思探神寶，明發懷周，興言謨老，靈魄有行，言觀蒼昊，清歌先誡，丹書有造。","sortOrder":45},
  {"id":"s_work_nvlt_20_46","chapterId":"ch_work_nvlt_20","text":"晉湛方生孔公贊曰：文王既没，微言將墜，邈哉孔公，龍見九二，闡化系象，素王洙泗，發揮中葉，道映周季。","sortOrder":46},
  {"id":"s_work_nvlt_20_47","chapterId":"ch_work_nvlt_20","text":"【碑】後漢祢衡魯夫子碑曰：受天至精，純粹睿哲，崇高足以長世，宽容足以廣包，幽明足以测神，文藻足以辯物，然而敏學以求之，下問以诹之，虛心以受之，深思以詠之，愍周道之回遹，悼九畴之乖悖，故發憤忘食，應聘四方，魯以大夫之位，任以國政之權，譬若飛鸿鸞於中庭，騁騏骥於闾巷也，是以期月之頃，五教克諧，移風易俗，邦國肅焉，無思不服，懿文德以紆餘，缀三五之紀綱，流洪耀之休赫，曠萬世而扬光，夫大明以動，天則也，廣大無疆，地德也，六經混成，洪式也，備此三者，聖極也，合吉凶於鬼神，遂殂落於夢寐，是以風烈流行，無所不通，故立石銘勋，以示昭明，辭曰：煌煌上天，篤降若人，邈矣悠哉，千祀一鄰，明德弘監，情性存存，弈弈純嘏，稽憲乾坤，曜彼靈祇，以訓黎元，終日乾乾，配天之行，在险而正，在困而亨，窮達之運，委諸穹蒼，日月則陰，天地不光，聖叡殂崩，大猷不綱。","sortOrder":47},
  {"id":"s_work_nvlt_20_48","chapterId":"ch_work_nvlt_20","text":"【論】後漢孔融聖人優劣論曰：荀愔等以為聖人俱受乾坤之醇靈，禀造化之和氣，該百行之高善，備九德之淑懿，極鸿源之深闾，窮品物之情類，曠荡出於無外，沉微淪於無內，器不是周，不充聖極，荀以為孔子稱大哉尧之為君也，唯天為大，唯尧則之，是為覆蓋眾聖，最優之明文也，孔以尧作天子九十餘年，政化洽於民心，雅頌流於眾聽，是以聲德發聞，遂為稱首，則易所謂聖人久於其道，而天下化成，百年然後勝殘去殺，必世而後仁者也，故曰：大哉尧之為君也，尧之為聖也，明其聖與諸聖同，但以人見稱為君爾。","sortOrder":48},
  {"id":"s_work_nvlt_20_49","chapterId":"ch_work_nvlt_20","text":"梁沈約辯聖論曰：聖人蓋人中之含明德，盡照精粹凝玄者，或三聖併時，或千載寂蔑，聖人遺情忘己，常以兼濟為念，若不登九五之位，則其道不行，非以黃屋玉玺為尊貴也，文王造周而未集，武王集之而未成，周公雖無王錄，而父兄二聖之烈，不可以終，若夫表以聖功，製禮作樂，則太平之基不著，二聖之美不彰，孔子當無錄之運，值自晦之時，而雲河不出圖，洛不出書，吾已矣夫，欲以聖德示天下，垂來世，當仲尼在世之時，世人不言為聖人也，伐树削跡，幹七十君而不一值，或以東家丘，或以為丧家犬，若不高叹鳳鳥，稱夢周公，樂正雅頌，各得其所，則當世安知其聖人乎。","sortOrder":49},
  {"id":"s_work_nvlt_20_51","chapterId":"ch_work_nvlt_20","text":"《毛詩》曰：丘中有麻，思賢也。","sortOrder":51},
  {"id":"s_work_nvlt_20_52","chapterId":"ch_work_nvlt_20","text":"又曰：南山有台，樂得賢也，得賢則能為邦家立太平之基矣。","sortOrder":52},
  {"id":"s_work_nvlt_20_53","chapterId":"ch_work_nvlt_20","text":"《春秋繁露》曰：氣之清者為精，人之清者為賢，治身者以積精為寶，治國者以積賢為道。","sortOrder":53},
  {"id":"s_work_nvlt_20_54","chapterId":"ch_work_nvlt_20","text":"《尚書》曰：所寶惟賢，則邇人安。","sortOrder":54},
  {"id":"s_work_nvlt_20_55","chapterId":"ch_work_nvlt_20","text":"又曰：野無遺賢。","sortOrder":55},
  {"id":"s_work_nvlt_20_56","chapterId":"ch_work_nvlt_20","text":"《論語》曰：賢者避世，其次避地，其次避色，其次避言。","sortOrder":56},
  {"id":"s_work_nvlt_20_57","chapterId":"ch_work_nvlt_20","text":"又曰：見賢思齊焉，見不賢而內自省者也。","sortOrder":57},
  {"id":"s_work_nvlt_20_58","chapterId":"ch_work_nvlt_20","text":"又曰：賢哉回也，一箪食，一瓢飲，回也不改其樂。","sortOrder":58},
  {"id":"s_work_nvlt_20_59","chapterId":"ch_work_nvlt_20","text":"又曰：臧文仲其［《太平御覽》四百零二其下有竊位者欤四字，此脱。］知柳下惠之賢而不與立也。","sortOrder":59},
  {"id":"s_work_nvlt_20_60","chapterId":"ch_work_nvlt_20","text":"又曰：賢賢易色。","sortOrder":60},
  {"id":"s_work_nvlt_20_61","chapterId":"ch_work_nvlt_20","text":"京房《易飛候》曰：视四方常有大雲，五色具而不雨，其下有聖賢人隱。","sortOrder":61},
  {"id":"s_work_nvlt_20_62","chapterId":"ch_work_nvlt_20","text":"《家語》曰：孔子讀史，至楚复陳，喟然曰：賢哉楚莊王，輕千乘之國，而重一言之信，非申叔時之忠，弗能見其義，非莊王賢，弗能受其訓。","sortOrder":62},
  {"id":"s_work_nvlt_20_63","chapterId":"ch_work_nvlt_20","text":"又曰：哀公問孔子曰：當今之君，孰者最賢，孔子曰：有衛靈公乎，公曰：吾聞其閨門無別，而子賢之何也，對曰：靈公之弟曰公子渠牟，其智足以治千乘，靈公任之，有大夫史鰌，以道去衛，而靈公却舍，琴瑟不御，臣以此賢之，不亦可乎，國語曰：臼季使於冀野，見冀缺耨，其妻馌之敬，相待如賓，歸而進之曰：得賢人，敢以告，文公曰：子何，以知其賢也，對曰：臣見其不忘敬也，使為下軍大夫。","sortOrder":63},
  {"id":"s_work_nvlt_20_64","chapterId":"ch_work_nvlt_20","text":"《列子》曰：治國之難，在於知賢，而不在自賢。","sortOrder":64},
  {"id":"s_work_nvlt_20_65","chapterId":"ch_work_nvlt_20","text":"尹《文子》曰：尹文子見齊宣王，宣王叹國寡賢，尹《文子》曰：使國悉賢，孰處王下，王曰：國悉不肖，［《太平御覽》四百二肖下有可乎尹文子曰國悉不肖十字，此脱。］孰理王朝，王曰：賢與不肖，皆無可乎，《文子》曰：不然，有賢，有不肖，故王尊於上，臣卑於下，賢賢退不肖，所以有上下也。","sortOrder":65},
  {"id":"s_work_nvlt_20_66","chapterId":"ch_work_nvlt_20","text":"《申子》曰：千里有賢者，是比肩而立也。","sortOrder":66},
  {"id":"s_work_nvlt_20_67","chapterId":"ch_work_nvlt_20","text":"《孫卿子》曰：古之賢人，食則餰鬻不足，衣則短褐不完，然而非禮不進，非義不受。","sortOrder":67},
  {"id":"s_work_nvlt_20_68","chapterId":"ch_work_nvlt_20","text":"《呂氏春秋》曰：公孫枝獻百里奚於缪公，三月，請屬事焉，公曰：買之五羊之皮而屬事，無乃為天下笑乎，枝曰：信賢而任之，君之明也，議賢而下之，臣之忠也，夫誰笑哉。","sortOrder":68},
  {"id":"s_work_nvlt_20_69","chapterId":"ch_work_nvlt_20","text":"又曰：賢者遺人以仁。","sortOrder":69},
  {"id":"s_work_nvlt_20_70","chapterId":"ch_work_nvlt_20","text":"又曰：得地千里，不如得一賢也。","sortOrder":70},
  {"id":"s_work_nvlt_20_71","chapterId":"ch_work_nvlt_20","text":"又曰：魏文侯過段幹木之闾而式，其仆曰：君胡式，曰：幹木賢者也，吾安敢不式。","sortOrder":71},
  {"id":"s_work_nvlt_20_72","chapterId":"ch_work_nvlt_20","text":"《韓子》曰：晉平公問叔向曰：吾群臣孰賢，對曰：趙武賢，武立如不勝衣，言如不出口，然其所舉者數十人，皆令德也。","sortOrder":72},
  {"id":"s_work_nvlt_20_73","chapterId":"ch_work_nvlt_20","text":"黃石公三略曰：傷賢者殃及三世，蔽賢者身當其害，達賢者福流子孫，嫉賢者名不存。","sortOrder":73},
  {"id":"s_work_nvlt_20_74","chapterId":"ch_work_nvlt_20","text":"《韓詩外傳》曰：聖人求賢者以自辅。","sortOrder":74},
  {"id":"s_work_nvlt_20_75","chapterId":"ch_work_nvlt_20","text":"又曰：魏文侯問孤卷子曰：父子兄弟臣賢，足恃乎，對曰：父賢不過尧，而丹朱放，子賢不過舜，而瞽瞍拘，兄賢不過舜，而象傲，弟賢不過周公，而管叔誅，臣賢不過湯武，而桀紂伐，君欲治，亦從身始，人何可恃。","sortOrder":75},
  {"id":"s_work_nvlt_20_76","chapterId":"ch_work_nvlt_20","text":"《物理論》曰：賢人為德，體自然也，故語曰：黃金累千，不如一賢。","sortOrder":76},
  {"id":"s_work_nvlt_20_77","chapterId":"ch_work_nvlt_20","text":"【頌】漢王褒聖主得賢臣頌曰：夫賢者國家之器用也，所任賢，則趍舍省而功施普，器用利，則用力少而就效眾，故工人之用钝器也，勞筋苦骨，終日矻矻，及巧冶鑄幹將之朴，清水淬其鋒，越砥斂其鍔，水斷蛟龍，陆剸犀革，使離娄督繩，公输削墨，雖崇台五層，延袤百丈而不溷者，工用相得也，故服絺绤之涼者，不苦盛暑之鬱燠，袭狐貉之暖者，不忧至寒之凄沧，何則，有其具者易其備，有賢人君子，亦聖王之所以易海內也，君人者，勤於求賢，而逸於得人，人臣亦然，昔賢者之未遭遇也，圖事揆策，則君不用其謀，陳見悃誠，則上不然其信，進仕不得施效，斥逐又非其愆，是故伊尹勤於鼎俎，太公困於鼓刀，百里自鬻，甯子飯牛，及其遇明君，遭聖主也，運筹合上意，諫爭則見聽，進退得關其忠，任職得行其術，剖符錫壤而光祖考，傳之子孫，以資說士，故世必有聖智之君，而後有賢明之臣，詩曰：思皇多士，生此王國，故世平王聖，俊乂將自至，若尧舜禹湯文武之君，獲稷契皋陶伊尹呂望之臣，明明在朝，穆穆列布，故聖主必待賢臣而弘功業，俊士亦俟明主以顯其德，上下俱欲，歡然交欣，千載一會，論說無疑，翼乎如鸿毛遇順風，沛乎若巨魚縱大壑，其得意如此，則胡禁不止，曷令不行，化溢四表，橫被無窮，遐夷貢獻，萬祥必臻，是以聖王不遍窥望，而视已明，不殫傾耳，而聽已聰。","sortOrder":77},
  {"id":"s_work_nvlt_20_78","chapterId":"ch_work_nvlt_20","text":"【贊】晉夏侯湛顏子贊曰：知彰知微，體深研機，明象介石，量同聖師，探赜罔滯，在言靡遺，仰諸惟高，瞻之攸希。","sortOrder":78},
  {"id":"s_work_nvlt_20_79","chapterId":"ch_work_nvlt_20","text":"又左丘明贊曰：世亂讒勝，君子道忧，丘明達聖，致志春秋，微言逃難，旁行不流，庶幾斯文，希志訓猷。","sortOrder":79},
  {"id":"s_work_nvlt_20_80","chapterId":"ch_work_nvlt_20","text":"晉戴逵顏回贊曰：神道天絕，理非語象，不有伊人，誰怜誰仰，际盡一時，照無二朗，契彼玄跡，冥若影响。","sortOrder":80},
  {"id":"s_work_nvlt_20_81","chapterId":"ch_work_nvlt_20","text":"晉孫楚顏回贊曰：束身励行，宗事聖道，鑽仰孜孜，视予猶考。","sortOrder":81},
  {"id":"s_work_nvlt_20_82","chapterId":"ch_work_nvlt_20","text":"【碑】後漢祢衡顏子碑曰：禀天地之純和，鍾嶽渎之休靈，睿哲之姿，誕自初育，英絕之才，顯乎婴孩，在束脩之齒，入宣尼之室，德行邁於三千，仁風橫於萬國，知微知章，聞一覺十，用行舍藏，與聖合契，名為四友之冠，寔盡疏附之益，爾乃安陋巷，挹清流，甘箪瓢以充飢，雖屢空而不忧，於時河不出圖，周祚未訖，仲尼無舜禹之功，先生包元凯之烈，其辭曰：亚聖德，蹈高蹤，遊洙泗，肅禮容，備懿體，心弥冲，秀不實，振芳風，配聖饋，圖辟雍，紀德行，昭罔窮。","sortOrder":82},
  {"id":"s_work_nvlt_20_83","chapterId":"ch_work_nvlt_20","text":"【論】魏高貴乡公顏子論曰：心不违仁，行無二過，用行舍藏，與同進退，聽承聖言，罔有不喻，叙之於易，以章殊異，死則悲恸，謂天丧己，所以殷勤至於此者，聖人嘉美良才之效也，設使天假之年，後孔子没，焉知其不光明聖道，闡扬師業，有卓爾之美乎，百慮之所得，愚者有焉，原後之君子，詳覽之焉爾。","sortOrder":83},
  {"id":"s_work_nvlt_20_85","chapterId":"ch_work_nvlt_20","text":"《說苑》曰：逆命利君謂之忠。","sortOrder":85},
  {"id":"s_work_nvlt_20_86","chapterId":"ch_work_nvlt_20","text":"《孝經》曰：進思盡忠，退思補過，將順其美，匡救其惡。","sortOrder":86},
  {"id":"s_work_nvlt_20_87","chapterId":"ch_work_nvlt_20","text":"《左傳》曰：晉獻公使荀息傅奚齊，對曰：臣竭其股肱之力，加之以忠貞，其濟君之靈也，不濟則以死繼之，公曰：何謂忠貞，對曰：公家之利，知無不為，忠也，送往事居，耦俱無猜，貞也。","sortOrder":87},
  {"id":"s_work_nvlt_20_88","chapterId":"ch_work_nvlt_20","text":"又曰：晉懷公命無從亡人，狐突之子毛及偃，從重耳在秦，弗召，懷公執突曰：子來則免，對曰：子之能仕，父教之忠，策名委质，貳乃辟也，父教子貳，何以事君，乃殺之。","sortOrder":88},
  {"id":"s_work_nvlt_20_89","chapterId":"ch_work_nvlt_20","text":"又曰：楚子滅若敖氏，其孫葴尹克黃使於齊，聞亂，其人曰：不可以入矣，葴尹曰：君，天也，天可逃乎，遂歸复命，自拘司败。","sortOrder":89},
  {"id":"s_work_nvlt_20_90","chapterId":"ch_work_nvlt_20","text":"又曰：季文子卒，無衣帛之妾，無食粟之馬，無藏金玉，無重器備，君子是以知季文子之忠於公室也，相三君矣，而無積，可不謂忠乎。","sortOrder":90},
  {"id":"s_work_nvlt_20_91","chapterId":"ch_work_nvlt_20","text":"又曰：楚子囊將死，遺言謂子庚曰：必城郢，君子謂子囊忠，將死不忘衛社稷，可不謂忠乎，忠，民之望也。","sortOrder":91},
  {"id":"s_work_nvlt_20_92","chapterId":"ch_work_nvlt_20","text":"《家語》曰：孔子曰：晏子於君為忠臣，於行為恭敏。","sortOrder":92},
  {"id":"s_work_nvlt_20_93","chapterId":"ch_work_nvlt_20","text":"《晏子》曰：梁丘據問《晏子》曰：子事三君，君不同心，而子俱從焉，仁人固多心乎，對曰：一心可以事百君，百心不可以事一君。","sortOrder":93},
  {"id":"s_work_nvlt_20_94","chapterId":"ch_work_nvlt_20","text":"《韓詩外傳》曰：有大忠，有次忠，有下忠，若周公於成王，可謂大忠，管仲於桓公，可謂次忠，子胥於夫差，可謂下忠矣。","sortOrder":94},
  {"id":"s_work_nvlt_20_95","chapterId":"ch_work_nvlt_20","text":"又曰：狄人殺衛懿公，盡食其肉，獨舍其肝，弘演使還，哭畢呼天，因自出其肝，內懿公之肝，齊桓公聞之曰：弘演可謂忠矣。","sortOrder":95},
  {"id":"s_work_nvlt_20_96","chapterId":"ch_work_nvlt_20","text":"《史記》曰：項籍围漢王於滎陽，漢將紀信曰：事已急，請為王，王可間出，紀信乘黃屋左纛，曰：城中食盡，漢王降，楚軍皆呼萬歲，漢王與數十騎出，項王燒殺紀信。","sortOrder":96},
  {"id":"s_work_nvlt_20_97","chapterId":"ch_work_nvlt_20","text":"《說苑》曰：楚莊王立，三年不聽朝，令於國曰：諫者死，蘇從曰：處君之高爵，食君之厚祿，愛死不諫，非忠也，乃諫，［事具諫篇。］","sortOrder":97},
  {"id":"s_work_nvlt_20_98","chapterId":"ch_work_nvlt_20","text":"又曰：卑身賤體，進賢不解，數稱往古之行事，以厲王意，庶幾有益，以安國家，如此者忠臣也。","sortOrder":98},
  {"id":"s_work_nvlt_20_99","chapterId":"ch_work_nvlt_20","text":"《漢書》曰：非劉氏不王，高祖製詔御史，長沙王吳芮忠，其定著令。","sortOrder":99},
  {"id":"s_work_nvlt_20_100","chapterId":"ch_work_nvlt_20","text":"又曰：王莽遣使者，即拜龚勝，以印綬就加勝身，勝輟推不受，曰：吾受漢家厚恩，無以報，豈以一身事二姓哉，語畢，遂不复飲食，積十四日死。","sortOrder":100},
  {"id":"s_work_nvlt_20_101","chapterId":"ch_work_nvlt_20","text":"《東觀漢記》曰：光武指王常謂群臣曰：此家率下江諸將，辅翼漢室，心如金石，真忠臣也，是日遷常為漢忠將軍。","sortOrder":101},
  {"id":"s_work_nvlt_20_102","chapterId":"ch_work_nvlt_20","text":"《續漢記》曰：陰識拜特進，極言正議，至與賓客語，不及國事，常慕仲山甫夙夜匪解。","sortOrder":102},
  {"id":"s_work_nvlt_20_103","chapterId":"ch_work_nvlt_20","text":"又曰：溫序為護軍校尉，行部至隴西，為隗嚣將荀宇等所劫，欲生降序，序大怒。以節挝殺人，賊趍欲殺序，宇止之曰：義士欲死節，賜劍令自裁，序受劍，衔須著口中，叹曰：無令須汙土，遂伏劍。","sortOrder":103},
  {"id":"s_work_nvlt_20_104","chapterId":"ch_work_nvlt_20","text":"謝承《後漢書》曰：漢安元年，選遣八使，巡行風俗，餘人受命之部，而張綱獨埋輪於洛陽都亭，曰：銶狼當路，安問狐狸，遂奏大將軍梁冀無君之心十五事，皆臣子所切齒者也。","sortOrder":104},
  {"id":"s_work_nvlt_20_105","chapterId":"ch_work_nvlt_20","text":"《魏志》曰：王脩為大農郎中令，時嚴才反攻掖門，脩聞变，將官屬出至宮門，太祖在銅雀台，望見之曰：彼來者，必王叔治也，相國鍾繇謂脩曰：舊京城有变，九卿各居其府，脩曰：居府雖舊，非赴難之義也。","sortOrder":105},
  {"id":"s_work_nvlt_20_106","chapterId":"ch_work_nvlt_20","text":"又曰：典韦拜都尉，太祖引置左右，將親兵數百人，常繞帳，韦性忠至謹重，常晝夜立侍，終日夜宿帳左右，稀歸私寢，《蜀志》曰：初諸葛亮自表後主，成都有桑八百，薄田十五頃，子孫衣食自有餘，至於臣在外任，隨身衣食，悉仰於官，若臣死之日，不使內有餘帛，外有嬴财，及卒，如其所言。","sortOrder":106},
  {"id":"s_work_nvlt_20_107","chapterId":"ch_work_nvlt_20","text":"周處別傳曰：互［《初學記》十七作氐。］賊為亂，以處為建威將軍，以兵五千，受夏侯俊節度，處遂進軍大戰，仰天叹曰：古者良將受命，凿凶門以出，蓋有進無退，我為大臣，以身殉國，不亦可乎，遂戰死。","sortOrder":107},
  {"id":"s_work_nvlt_20_108","chapterId":"ch_work_nvlt_20","text":"【贊】梁元帝忠臣傳記［《初學記》十七作受。］讬篇贊曰：太真英挺，投袂勤王，伯猷蹈節，身殒名扬，嶷嶷景倩，主亡與亡，嗟乎尚矣，惟國之良。","sortOrder":108},
  {"id":"s_work_nvlt_20_109","chapterId":"ch_work_nvlt_20","text":"又忠臣傳諫［原作陳，據本書二十四諫篇引序改。］爭篇贊曰：子政铿铿，誠存社稷，朱遊折槛，遂其婞直。","sortOrder":109},
  {"id":"s_work_nvlt_20_110","chapterId":"ch_work_nvlt_20","text":"又忠臣傳執法篇贊曰：設官分職，鹹曰師師，彼己之子，邦之直司，銶狼當路，安問狐狸，昏明有世，直道無時。","sortOrder":110},
  {"id":"s_work_nvlt_20_111","chapterId":"ch_work_nvlt_20","text":"【表】梁元帝上忠臣傳表曰：資父事君，寔曰嚴敬，求忠出孝，義兼臣子，是以冬溫夏凊，盡事君之節，進思將美，懷出奉之義，羲軒改物，殷周受命，三能十亂，九棘五臣，靡不夙夜在公，忠為令德，若使縉雲得姓之子，姬昌魯衛之臣，是知理合君親，孝忠一體，性與率由，因心致極，臣連華霄漢，凭暉日月，三握再吐，夙奉紫庭之慈，春詩秋禮，早蒙丹扆之訓，宣帝褒德，麟閣畫充國之形，顯宗念功，雲台圖仲華之象。","sortOrder":111},
  {"id":"s_work_nvlt_20_112","chapterId":"ch_work_nvlt_20","text":"【箋】梁王筠答湘東王示忠臣傳箋曰：竊以孝實天經，忠為令德，百行攸先，一心靡或，昔淮南鸿烈，事無的准，沛王通論，義止儒術，東平獲譽為片言，臨淄見稱文辭小道，孰若理冠君親，義兼臣子，謹當宣示遐邇，光扬德音。","sortOrder":112},
  {"id":"s_work_nvlt_20_113","chapterId":"ch_work_nvlt_20","text":"【序】梁元帝忠臣傳序曰：夫天地之大德曰生，聖人之大寶曰位，因生所以盡孝，因位所以立忠，事君事父，資敬之理寧異，為臣為子，率由之道斯一，忠為令德，竊所景行，且孝子烈女逸民，鹹有別傳，至於忠臣，曾無述製，今將發箧陳書，備加論讨。","sortOrder":113},
  {"id":"s_work_nvlt_20_114","chapterId":"ch_work_nvlt_20","text":"又忠臣傳死節篇序曰：自非識君臣之大體，鑒生死之弘分，何以能滅七尺之軀，殉一顧之感，然平路康衢，從容之道進，危涂险径，忠貞之節興，登平路者易為功，涉险涂者難為力，從容之用，世不乏人，忠貞之槩，時難屢有。","sortOrder":114},
  {"id":"s_work_nvlt_20_116","chapterId":"ch_work_nvlt_20","text":"《爾雅》曰：善事父母曰孝。","sortOrder":116},
  {"id":"s_work_nvlt_20_117","chapterId":"ch_work_nvlt_20","text":"《孝經》曰：夫孝天之經也，地之義也，民之行也。","sortOrder":117},
  {"id":"s_work_nvlt_20_118","chapterId":"ch_work_nvlt_20","text":"又曰：夫孝始於事親，中於事君，終於立身。","sortOrder":118},
  {"id":"s_work_nvlt_20_119","chapterId":"ch_work_nvlt_20","text":"又曰：愛親者，不敢惡於人，敬親者，不敢慢於人，愛敬盡於事親，而德教加於百姓，刑於四海，蓋天子之孝也。","sortOrder":119},
  {"id":"s_work_nvlt_20_120","chapterId":"ch_work_nvlt_20","text":"《禮記》曰：《曾子》曰：孝有三，大孝尊親，其次弗辱，其下能養。","sortOrder":120},
  {"id":"s_work_nvlt_20_121","chapterId":"ch_work_nvlt_20","text":"又曰：公明儀問於《曾子》曰：夫子可以為孝乎，《曾子》曰：孝者先意承志，諭父母於道，參直養者也，安能為孝乎。","sortOrder":121},
  {"id":"s_work_nvlt_20_122","chapterId":"ch_work_nvlt_20","text":"又曰：先王之孝也，色不忘乎目，聲不絕乎耳，心志嗜欲，不忘乎心。","sortOrder":122},
  {"id":"s_work_nvlt_20_123","chapterId":"ch_work_nvlt_20","text":"又曰：生則敬養，死則敬享。","sortOrder":123},
  {"id":"s_work_nvlt_20_124","chapterId":"ch_work_nvlt_20","text":"《毛詩》曰：哀哀父母，生我劬勞，無父何怙，無母何恃，出則衔恤，入則靡至，父兮生我，母兮鞠我，撫我育我，長我畜我，顧我复我，出入腹我，欲報之德，昊天罔極。","sortOrder":124},
  {"id":"s_work_nvlt_20_125","chapterId":"ch_work_nvlt_20","text":"《論語》曰：三年無改於父之道，可謂孝矣。","sortOrder":125},
  {"id":"s_work_nvlt_20_126","chapterId":"ch_work_nvlt_20","text":"又曰：孟懿子問孝，子曰：無违，樊遲曰：何謂也，子曰：生事之以禮，死葬之以禮，祭之以禮。","sortOrder":126},
  {"id":"s_work_nvlt_20_127","chapterId":"ch_work_nvlt_20","text":"子遊問孝，子曰：父母唯其疾之忧，《尸子》曰：曾子每讀丧禮，泣下霑襟，常以一夕五起，视衣之厚薄，枕之高卑。","sortOrder":127},
  {"id":"s_work_nvlt_20_128","chapterId":"ch_work_nvlt_20","text":"《韓詩外傳》曰：《曾子》曰：往而不可還者，親也故孝欲養而親不待，是故椎牛而葬，不如雞豚之逮親存也，初吾為吏，祿不及釜，尚欣欣而喜者，非以為多也，樂其逮親也，既没之後，吾嘗南遊於楚，得尊官焉，堂高九尺，轉嘗［○初學記十七，《太平御覽》四百十四作轂。］百乘，然猶北乡而泣涕者，非為賤也，悲不逮吾親也，故家貧親老，不擇官而仕。","sortOrder":128},
  {"id":"s_work_nvlt_20_129","chapterId":"ch_work_nvlt_20","text":"《說苑》曰：曾子常有為不中，曾晳怒，援木击之，曾子有頃乃蘇，退鼓瑟而歌。孔子聞之，告門人曰：參來勿內也，昔舜事瞽瞍，索而使之，未嘗不在侧，索而殺之。未嘗可得，而小箠則受，大箠則走，今曾子委身待暴怒，以陷父不義，不孝孰大乎。","sortOrder":129},
  {"id":"s_work_nvlt_20_130","chapterId":"ch_work_nvlt_20","text":"又曰：韓伯瑜有過，其母笞之，泣，母曰：他日未嘗泣，今何泣，對曰：他日得笞，嘗痛，今母之力不能痛，是以泣也。","sortOrder":130},
  {"id":"s_work_nvlt_20_131","chapterId":"ch_work_nvlt_20","text":"又曰：闵子騫兄弟二人，母死，其父更娶，复有二子，子騫為其父御車，失辔，父持其手，衣甚单，父則歸，呼其後母兒，持其手，衣甚厚溫，即謂其婦曰：吾所以娶汝，乃為吾子，今汝欺我，去無留，子騫前曰：母在一子单，母去四子寒，其父默然，故曰：孝哉闵子騫，一言其母還，再言三子溫。","sortOrder":131},
  {"id":"s_work_nvlt_20_132","chapterId":"ch_work_nvlt_20","text":"《列女傳》曰：老萊子孝養二親，行年七十，婴兒自娱，著五色采衣，嘗取漿上堂，跌仆，因臥地為小兒啼，或弄乌鳥於親侧。","sortOrder":132},
  {"id":"s_work_nvlt_20_133","chapterId":"ch_work_nvlt_20","text":"《漢書》曰：淳於緹萦，齊人淳於意，五女無男，坐事當刑，緹萦最小，涕泣隨父到長安，上書曰：妾父為監，齊中皆稱廉平，今坐事當刑，妾乞没為官婢，以贖父罪，文帝詔免意罪，併除肉刑。","sortOrder":133},
  {"id":"s_work_nvlt_20_134","chapterId":"ch_work_nvlt_20","text":"又曰：文帝母薄太後疾，文帝侍養數年，衣不解帶，親供粢盛，坐罪不及父母，下哀矜之詔。","sortOrder":134},
  {"id":"s_work_nvlt_20_135","chapterId":"ch_work_nvlt_20","text":"又曰：金日磾母，教誨兩子，甚有法度，上聞而嘉之，母病死，詔圖畫於甘泉宮，署曰休屠王閼氏，日磾每見畫，常拜之涕泣。","sortOrder":135},
  {"id":"s_work_nvlt_20_136","chapterId":"ch_work_nvlt_20","text":"《東觀漢記》曰：長沙義士古初，父丧未葬，鄰人火起，及初舍下，棺不可移，初冒火伏棺上，俄而火滅。","sortOrder":136},
  {"id":"s_work_nvlt_20_137","chapterId":"ch_work_nvlt_20","text":"又曰：趙咨至孝，躬率子孫，耕農為養，盜嘗夜往劫之，咨恐母驚懼，乃先至門迎盜，因請為設食，謝曰：老母八十，疾病須養，居貧，乞置衣糧，妻子餘物無所惜，諸盜皆慚叹，跪曰：所犯無状，幹暴賢者，言畢奔走。","sortOrder":137},
  {"id":"s_work_nvlt_20_138","chapterId":"ch_work_nvlt_20","text":"又曰：黃香父為郡五官，貧無奴仆，香躬執勤苦，盡心供養，冬無被袴，而親極滋味，暑即扇床枕，寒即以身溫席。","sortOrder":138},
  {"id":"s_work_nvlt_20_139","chapterId":"ch_work_nvlt_20","text":"《續漢書》曰：申徒蟠九歲丧父，孝毀過禮，服除，不進肉十餘年，每忌日，辄三日不食。","sortOrder":139},
  {"id":"s_work_nvlt_20_140","chapterId":"ch_work_nvlt_20","text":"郭林宗別傳曰：茅容耕於野，避雨树下，眾皆夷踞相對，獨容危坐愈恭，林宗行，見而奇之，與言，因請寓宿，既而日夕，容殺雞為饌，林宗謂為己設，既而以供其母，自以菜蔬供客同飯，林宗起拜曰：卿賢乎我哉。","sortOrder":140},
  {"id":"s_work_nvlt_20_141","chapterId":"ch_work_nvlt_20","text":"《汝南先賢傳》曰：薛苞好學篤行，丧母，以至孝聞，父娶後妻而憎苞，分之令出，苞日夜號泣不能去，至被驅杖，不得已，庐於舍外，旦入而扫，父怒。又逐之，乃庐於里門，昏晨不废，積歲餘，父母慚而還之。","sortOrder":141},
  {"id":"s_work_nvlt_20_142","chapterId":"ch_work_nvlt_20","text":"《蜀志》曰：先主在樊，率其眾南行，諸葛亮與徐庶併從，為曹公所追破，獲庶母，庶辭先主而指其心曰：本欲與將軍共圖王霸之業，以此方寸心，今已失母，方寸亂矣，無益於事，請於此別，遂詣曹公。","sortOrder":142},
  {"id":"s_work_nvlt_20_143","chapterId":"ch_work_nvlt_20","text":"《吳書》曰：顧悌，以孝悌廉正，聞於乡党，每得父母書，洒埽整衣服，設幾案，舒書其上，拜跪讀之，每句應诺畢，复再拜，父有疾耗之問，臨書垂泣哽噎，父終，水漿不入口五日，孫權為作布衣一袭，強令悌釋服，悌雖以公義自割，猶以為不見父丧，常畫壁作棺象，設神坐於下，每對之哭泣，服未阕而卒，晉中興書曰：吳隱之少有孝行，遭母忧，哀毀過禮，太常韓康伯鄰居，隱之每哭，康伯母辄輟事流淚，悲不自勝。","sortOrder":143},
  {"id":"s_work_nvlt_20_144","chapterId":"ch_work_nvlt_20","text":"萧廣濟《孝子傳》曰：妫皓父崑，被劾入重，皓年十六，髡頭詣闕，通章不省，皓不飲食，懷石腰中，詣公卿，辄出石置地，叩頭流血覆面，莫不傷懷，遂奏理崑罪。","sortOrder":144},
  {"id":"s_work_nvlt_20_145","chapterId":"ch_work_nvlt_20","text":"師覺授《孝子傳》曰：程曾年七歲，丧母，哀號哭泣，不異成人，祖母怜之，嚼肉食之，覺有味，便吐去。","sortOrder":145},
  {"id":"s_work_nvlt_20_146","chapterId":"ch_work_nvlt_20","text":"宗躬《孝子傳》曰：吳坦之，隱之兄也，母葬夕，設九飯祭，坦之每臨一祭，辄號恸斷絕，至七祭，吐血而死。","sortOrder":146},
  {"id":"s_work_nvlt_20_147","chapterId":"ch_work_nvlt_20","text":"又曰：張景胤六歲丧母，母遺物悉散施，唯留一畫扇，每感思，辄开匣流涕，父邵為吳興太守，暴疾報至，天雪水涸，便徒跣上岸，左右捉履靺逐，發都，夜晝三日半至郡，入郭奉讳，氣絕吐血，久乃蘇。","sortOrder":147},
  {"id":"s_work_nvlt_20_148","chapterId":"ch_work_nvlt_20","text":"又曰：華寶八歲，義熙中，父從軍，語寶曰：吾還，當營婚冠，值鹹陽丧亂，吉凶兩絕，寶年六十，遂不冠娶，舉言流涕。","sortOrder":148},
  {"id":"s_work_nvlt_20_149","chapterId":"ch_work_nvlt_20","text":"又曰：何子平事母至孝，為楊州從事，月俸得白米，辄货市粟麥，人或問之，答曰：尊老在東，不辦常得米，何容獨食白粲，母丧，年將六十，有孺，子之慕，晝夜號叫，暑避清涼，冬不衣絮。","sortOrder":149},
  {"id":"s_work_nvlt_20_150","chapterId":"ch_work_nvlt_20","text":"又曰：桑虞丧父，年十四，毀瘠過禮，日食百粒，以糝藜藿。","sortOrder":150},
  {"id":"s_work_nvlt_20_151","chapterId":"ch_work_nvlt_20","text":"《續搜神記》曰：吳猛性至孝，小兒時，在父母邊臥，時夏月，多蚊虻，而終不搖扇，雲懼蚊虻去我及父母，父母終，行服墓次，蜀賊縱暴，焚燒邑屋，發掘丘隴，民人迸竄，猛在墓侧，號恸不去，賊為之感怆，遂不犯。","sortOrder":151},
  {"id":"s_work_nvlt_20_152","chapterId":"ch_work_nvlt_20","text":"荀氏家傳曰：荀顗年逾耳順，而母年九十，色養烝烝，以孝聞，在丧憔悴，貌不可識，若婴孺之號，哀恸傍人。","sortOrder":152},
  {"id":"s_work_nvlt_20_153","chapterId":"ch_work_nvlt_20","text":"【詩】魏王粲思親詩曰：穆穆顯妣，德音徽止，思齊先姑，志侔薑姒，躬此勞瘁，鞠予小子，小子之生，遭世罔寧，烈考勤時，從之於征，奄遘不造，隱忧是婴，咨予靡及，退守祧祊。","sortOrder":153},
  {"id":"s_work_nvlt_20_154","chapterId":"ch_work_nvlt_20","text":"晉孫綽表哀詩曰：天地之德曰生，生之所恃者親，親存則歡泰情盡，親亡則哀悴理極，故老萊婆娑於膝下，曾闵泣血於終年，哀悼之思至矣，自然之性篤矣，餘以薄祜，夙遭闵凶，越在九齡，嚴考即世，未及志學，過庭無聞，天覆既淪，俯凭坤厚，殖根外氏，賴以成訓，然以不才，不能負荷仁妣，弘母儀之德，邁榮寒之操，雕琢固顽，勉以道義，庶幾砥砺犬馬之報，豈悟一朝，复見孤弃，上天極禍，怨痛莫訴，皆由惡積咎深，不能通感，自丁荼毒，載離寒暑，茵帷尘寂，棟宇寥怳，仰悲軌跡，長自矜悼，不勝哀號，作詩一首，敢冒谅闇之譏，以申罔極之痛，詩曰：茫茫太極，賦授理殊，咨生不辰，仁考夙徂，微微冲弱，眇眇偏孤，叩心昊蒼，痛貫黃墟，肅我以義，鞠我以仁，嚴邁商風，恩洽陽春，昔聞邹母，勤教善分，懿矣慈妣，曠世齊運，嗟予小子，譬彼土粪，俯愧陋质，仰忝高訓，悠悠玄運，四氣错序，自我酷痛，載離寒暑，寥寥空堂，寂寂响戶，尘蒙幾筵，風生棟宇，感昔有恃，望晨遲顏，婉娈懷袖，極原盡歡，奈何茲妣，歸體幽埏，酷矣痛深，剖髓摧肝。","sortOrder":154},
  {"id":"s_work_nvlt_20_155","chapterId":"ch_work_nvlt_20","text":"晉夏侯湛離親詠曰：剖符兮南荆，辭親［親下明本有了字，當作兮，此脱。］遐征，發轫兮皇京，夕臻兮泉亭，撫首兮內顧，按辔兮安步，仰恋兮後涂，俯叹兮前路，既感物以永思兮，且歸身乎懷抱，苟违親以從利兮，匪曾闵之攸寶，视微榮之琐琐兮，知吾志之愈小，獨申愧於一心兮，慚報德之弥少。","sortOrder":155},
  {"id":"s_work_nvlt_20_156","chapterId":"ch_work_nvlt_20","text":"【賦】魏陳思王曹植懷親賦曰：濟陽南泽，有先帝故營，遂停馬住駕，造斯賦焉，獦平原而南骛，睹先帝之舊營，步壁壘之常製，識旌麾之所停，在官曹之典列，心仿佛於平生，回骥首而永逝，赴脩涂以尋遠，情眷眷而顧懷，魂須臾而九反。","sortOrder":156},
  {"id":"s_work_nvlt_20_157","chapterId":"ch_work_nvlt_20","text":"晉陆機祖德賦曰：咨時文之懿祖，膺降神之靈曜，栖九德以弘道，振風烈以增劭，彼劉公之矯矯，固雲網之逸禽，既凭形以傲物，谅傅翼而栖林，伊我公之秀武，思無幽而弗昶，形鮮烈於懷霜，泽溫惠乎挟纊，牧希世之洪捷，固山穀而為量，西夏坦其無尘，帝命赫而大壮，登具瞻於太階，濯長纓乎天漢，解戎衣以高揖，正端冕而大觀，戢靈武於既曜，恢時文於未煥，騰絕風以逸骛，庶遐蹤於公旦。","sortOrder":157},
  {"id":"s_work_nvlt_20_158","chapterId":"ch_work_nvlt_20","text":"又述先賦曰：仰先後之顯烈，懿暉祚之允辑，應遠期於已曠，昭前光於未戢，抱朗節以遐慕，振奇跡而峻立，在虐臣之貪禍，據西山而作违，招長轂於河畔，飲冀馬乎江湄，頓雲網而潛泳，揮神戈而外臨，敵罔隆而弗夷，逆無微而不禽，茂德韡其既休，元勋晔而荐舉，袭袞服於太階，配三台乎其所是，故其生也榮，雖萬物鹹被其仁，其亡也哀，雖天網猶失其綱，婴國命以逝止，亮身没而吳亡。","sortOrder":158},
  {"id":"s_work_nvlt_20_159","chapterId":"ch_work_nvlt_20","text":"又思親賦曰：悲桑梓之悠曠，愧蒸嘗之弗營，指南雲以寄款，望歸風而效誠。年歲俄其聿暮，明星烂而將清，回飆肅以長赴，零雪紛其下頹，羨纖枝之在榦，悼落葉之去枚，在顧复之遺忘，感明發之所懷，居辭安而厭苦，養引約而摧丰，忘天命之晚慕，原鞠子之速融，兄琼芳而蕙茂，弟蘭發而玉暉，感瑰姿之晚就，痛慈景之先违，天步悠長，人道短矣，異途同歸，無早晚矣。","sortOrder":159},
  {"id":"s_work_nvlt_20_160","chapterId":"ch_work_nvlt_20","text":"晉劉柔妻王氏懷思賦曰：超離親而獨寄，與忧憤而長俱，雖亮分以自勉，曾無聞乎須臾，思遙遙而忡惙，疾結滯乎肌膚，憶昔日之懽侍，奉膝下而怡裕，集同生而從容，常欣泰以逸豫，何運遇之偏否，獨遼隔於脩路，何恒鳥之將分，猶哀鳴以告離，况遊子之眷慕，孰殷思之可靡，於是仲秋萧索，蓐收西御，寒露宵零，落葉晨布，羨歸鸿之提提，振輕翼而高舉，志眇眇而遠馳，悲離思而呜咽，彼邁物而推移，何予思之難泄，聊攬翰以寄懷，怅辭鄙而增結。","sortOrder":160},
  {"id":"s_work_nvlt_20_161","chapterId":"ch_work_nvlt_20","text":"宋謝靈運孝感賦曰：舉高牆於楊潭，眇投跡於炎州，貫庐江之長路，出彭蠡而南浮，於時月孟節季，歲亦告暨，離乡眷壤，改時懷氣，恋丘墳而萦心，憶桑梓而零淚，孟積雪而抽筍，王斫冰以鱠鮮，荑葇葉於枯木，起春波於寒川，顧微心之庸褊，謝精靈於昭晢，擁永慕而莫從，曾遐感而靡彻。","sortOrder":161},
  {"id":"s_work_nvlt_20_162","chapterId":"ch_work_nvlt_20","text":"梁武帝孝思賦曰：念過隙之倏忽，悲逝川之不停，踐霜露而凄怆，懷燧穀而涕零，仲由念枯魚而永慕，吾丘感風树而長悲，雖一志而舍生，奉二親而何期，至如獻歲發揮，春日載陽，木散百華，草列眾芳，對樂時而無歡，乃觸目而感傷，朱明啟節，白日朝臨，木低甘果，树接清陰，不娱悅於懷抱，唯罔極而纏心，寒冰已結，寒條已折，旅雁鳴而哀哀，朔風鼓而烈烈，無一息而缓念，與四時而長切，蒹葭蒼蒼，白露為霜，涼氣入衣，凄風動裳，心無迫而自切，情不觸而獨傷，靈蛇衔珠以酬志，慈乌反哺以報親，在虫鳥其猶爾，况三才之令人。","sortOrder":162},
  {"id":"s_work_nvlt_20_163","chapterId":"ch_work_nvlt_20","text":"【頌】後漢蔡邕祖德頌曰：昔文王始受命，武王定禍亂，至於成王，太平乃洽，祥瑞必降，夫豈後德隆漸，浸之所通也，是以易嘉積善有餘慶，詩稱子孫其保之，非特王道然也，賢人君子，脩仁履德者，亦其有焉，昔我烈祖，暨於予考，世載孝友，重以明德，率禮莫违，是以靈祇降之休瑞，兔扰馴以昭其仁，木連理以象其義，斯乃祖祢之遺靈，盛德之所貺也，豈是童蒙孤稚所克任哉，穆穆我祖，世篤其仁，其德克明，惟懿惟醇，宣慈惠和，無競伊人，巖巖我考，莅之以莊，增崇丕顯，克構其堂，是用祚之，休徵惟光，厥徵伊何，於昭於今，園有甘棠，別榦同心，墳有扰兔，宅我柏林，神不可誣，伪不可加，析薪之業，畏不克荷，矧貪靈貺，以為己華，惟予小子，豈不是欲，於有先功，匪榮伊辱。","sortOrder":163},
  {"id":"s_work_nvlt_20_164","chapterId":"ch_work_nvlt_20","text":"晉庾峻祖德頌曰：思文我祖，降茲嶽靈，綿綿之跡，時惟初生，天難忱斯，駿命靡常，世祚中衰，官族消亡，念昔厎績，惟乃舊章，烈祖勤止，其德允荒，漢後不辟，公族剝亂，難起萧牆，政由竖官，監彼天眚，我不幹時，縱德遺寵，顯志遁思，均樂公侯，逸豫無期，烈祖厎戒，營茲垣墉，曾孫篤之，永世攸同。","sortOrder":164},
  {"id":"s_work_nvlt_20_165","chapterId":"ch_work_nvlt_20","text":"【贊】晉夏侯湛闵子騫贊曰：聖既擬天，賢亦希聖，蒸蒸子騫，立體忠正，幹祿辭親，事親盡敬，勉心景跡，擢辭流詠。","sortOrder":165},
  {"id":"s_work_nvlt_20_166","chapterId":"ch_work_nvlt_20","text":"梁元帝孝德傳皇王篇贊曰：天子之孝，曰聖與仁，重瞳表德，參漏通神，皇矣高祖，連鑣舜禹，天經地義，重規沓矩，道逾七十，聲超三五。","sortOrder":166},
  {"id":"s_work_nvlt_20_167","chapterId":"ch_work_nvlt_20","text":"又孝德傳天性篇贊曰：生之育之，長之畜之，顧我复我，答施何時，欲報之德，不可方思，涓尘之孝，河海之慈，废書叹息，泣下涟洏。","sortOrder":167},
  {"id":"s_work_nvlt_20_168","chapterId":"ch_work_nvlt_20","text":"【序】梁元帝孝德傳序曰：夫天經地義，聖人不加，原始要終，莫逾孝道，能使甘泉自涌，鄰火不焚，地出黃金，天降神女，感通之至，良有可稱。","sortOrder":168},
  {"id":"s_work_nvlt_20_169","chapterId":"ch_work_nvlt_20","text":"《藝文類聚》　唐·欧陽詢","sortOrder":169},
  {"id":"s_work_nvlt_21_1","chapterId":"ch_work_nvlt_21","text":"卷二十一人部五","sortOrder":1},
  {"id":"s_work_nvlt_21_2","chapterId":"ch_work_nvlt_21","text":"○德讓智性命友悌交友絕交","sortOrder":2},
  {"id":"s_work_nvlt_21_4","chapterId":"ch_work_nvlt_21","text":"《易》曰：君子進德脩業。","sortOrder":4},
  {"id":"s_work_nvlt_21_5","chapterId":"ch_work_nvlt_21","text":"又曰：見龍在田，德施普也。","sortOrder":5},
  {"id":"s_work_nvlt_21_6","chapterId":"ch_work_nvlt_21","text":"《尚書》曰：惟德動天，無遠不屆。","sortOrder":6},
  {"id":"s_work_nvlt_21_7","chapterId":"ch_work_nvlt_21","text":"又曰：皋陶邁种德，德乃降。","sortOrder":7},
  {"id":"s_work_nvlt_21_8","chapterId":"ch_work_nvlt_21","text":"《左傳》曰：君人者，將昭德塞违，以臨照百官。","sortOrder":8},
  {"id":"s_work_nvlt_21_9","chapterId":"ch_work_nvlt_21","text":"又曰：故昭令德，以示子孫。","sortOrder":9},
  {"id":"s_work_nvlt_21_10","chapterId":"ch_work_nvlt_21","text":"又曰：官之失德，寵賂彰也。","sortOrder":10},
  {"id":"s_work_nvlt_21_11","chapterId":"ch_work_nvlt_21","text":"又曰：夫德，俭而有度。","sortOrder":11},
  {"id":"s_work_nvlt_21_12","chapterId":"ch_work_nvlt_21","text":"又曰：楚子問鼎大小輕重焉，王孫滿對曰：德之休明，雖小重也。","sortOrder":12},
  {"id":"s_work_nvlt_21_13","chapterId":"ch_work_nvlt_21","text":"又曰：德以柔中國。","sortOrder":13},
  {"id":"s_work_nvlt_21_14","chapterId":"ch_work_nvlt_21","text":"《毛詩》曰：德輶如毛，民鮮克舉之。","sortOrder":14},
  {"id":"s_work_nvlt_21_15","chapterId":"ch_work_nvlt_21","text":"《孝經》曰：先王有至德要道。","sortOrder":15},
  {"id":"s_work_nvlt_21_16","chapterId":"ch_work_nvlt_21","text":"又曰：聖人之德，無以加於孝乎。","sortOrder":16},
  {"id":"s_work_nvlt_21_17","chapterId":"ch_work_nvlt_21","text":"《論語》曰：為政以德，譬如北辰。","sortOrder":17},
  {"id":"s_work_nvlt_21_18","chapterId":"ch_work_nvlt_21","text":"又曰：德行顏淵闵子騫。","sortOrder":18},
  {"id":"s_work_nvlt_21_19","chapterId":"ch_work_nvlt_21","text":"又曰：有德者不必有言，有言者不必有德。","sortOrder":19},
  {"id":"s_work_nvlt_21_20","chapterId":"ch_work_nvlt_21","text":"又曰：君子之德風，小人之德草。","sortOrder":20},
  {"id":"s_work_nvlt_21_21","chapterId":"ch_work_nvlt_21","text":"又曰：骥不稱其力，稱其德也。","sortOrder":21},
  {"id":"s_work_nvlt_21_22","chapterId":"ch_work_nvlt_21","text":"《老子》曰：上德不德，是以有德，下德不失德，是以無德。","sortOrder":22},
  {"id":"s_work_nvlt_21_23","chapterId":"ch_work_nvlt_21","text":"《文子》曰：川廣者魚大，地廣者德厚。","sortOrder":23},
  {"id":"s_work_nvlt_21_24","chapterId":"ch_work_nvlt_21","text":"《鹽鐵論》曰：以道德為城，以仁義為郭。","sortOrder":24},
  {"id":"s_work_nvlt_21_25","chapterId":"ch_work_nvlt_21","text":"又曰：以道德為胄，以仁義為劍。","sortOrder":25},
  {"id":"s_work_nvlt_21_26","chapterId":"ch_work_nvlt_21","text":"《呂氏春秋》曰：宋景公時，熒惑在心，公問子韦，對曰：禍在君，可移宰相，公曰：宰相所與治國也，曰：移於民，公曰：民死，誰與為君，曰：移於歲，曰：歲飢，民必死，子韦曰：天處高而聽卑，君有至德之言三，天必賞君，熒惑果徙三舍［已具天部星篇。］","sortOrder":26},
  {"id":"s_work_nvlt_21_27","chapterId":"ch_work_nvlt_21","text":"《漢書》曰：有陰德者，天報以福。","sortOrder":27},
  {"id":"s_work_nvlt_21_28","chapterId":"ch_work_nvlt_21","text":"漢雜事曰：太史言，有德星見，當有英才賢德同遊者，詔下諸郡縣問，潁川郡上事曰：有陳太丘父子三人，俱共會社。","sortOrder":28},
  {"id":"s_work_nvlt_21_29","chapterId":"ch_work_nvlt_21","text":"《東觀漢記》曰：張堪為冯翊，見府寺門即下，主簿進曰：位尊德重，不宜自輕，堪曰：禮下公門，何謂輕哉。","sortOrder":29},
  {"id":"s_work_nvlt_21_30","chapterId":"ch_work_nvlt_21","text":"荀氏家傳曰：荀彧德行周備，其所規謩，以聖人為度。","sortOrder":30},
  {"id":"s_work_nvlt_21_31","chapterId":"ch_work_nvlt_21","text":"海內先賢傳曰：黃憲動則蹈規矩，言則發德音。","sortOrder":31},
  {"id":"s_work_nvlt_21_32","chapterId":"ch_work_nvlt_21","text":"【頌】晉左九嫔德柔頌曰：邈邈德柔，越天之刚，神以知來，智以藏往，含純溥生，允矣君子，展也大成，執德純粹，嶽峻川渟，履行高厲，荡乎其平，敦興聖道，率正不傾，令問不已，載路厥聲。","sortOrder":32},
  {"id":"s_work_nvlt_21_33","chapterId":"ch_work_nvlt_21","text":"【贊】又德刚贊曰：溫溫德刚，寔秉道純，履此聖義，體此敦仁，篤物博好，靡疏靡親，九族懷附，邦邑望尘，貴實賤華，尚素安貧，雖在崇高，必若平民，匪道之榮，譬之生民，褒飾之譽，謂之謗身，惟義是存，惟道是遵。","sortOrder":33},
  {"id":"s_work_nvlt_21_34","chapterId":"ch_work_nvlt_21","text":"【序】梁元帝全德志序曰：老子言全德歸厚，莊周雲全德不刑，呂覽稱全德之人，故以全德創其名也，此志隆［按隆當作陆，所雲寶劍，鼓瑟，公侯踞掌，要荒厥角，皆陆贾事，見史記贾傳。］大夫為首，伊人有學有辯，不天［按贾傳雲陆生竟以寿終，是天當作夭。］不貧，寶劍在前，鼓瑟從後，連環炙輠，雍容卒歲，驷馬高車，優遊宴喜，既令公侯踞掌，复使要荒蹶角，入室生光，豈非盛矣，若乃河宗九策，事等神鉤，陽雍双璧，理歸玄感，南陽樊重，高閣連雲，北海公沙，門人成市，咨此八龍，各傳一藝，夹河兩郡，家有萬石，人生行樂，上［疑當作止。］足為先，但使樽酒不空，坐客恒滿，寧與孟嘗問琴，承睫淚下，中山聽息，悲不自禁，同年而語也。","sortOrder":34},
  {"id":"s_work_nvlt_21_35","chapterId":"ch_work_nvlt_21","text":"【論】梁元帝全德志論曰：物我俱忘，無貶廊廟之器，動寂同遣，何累經纶之才，雖坐三槐，不妨家有三径，接五侯，不妨門垂五柳，但使良園廣宅，面水帶山，饒甘果而足花卉，葆筠篁而玩魚鳥，九月肅霜，時饗田畯，三春捧茧，乍酬蠶妾，酌升酒而歌南山，烹羔豚而击西缶，或出或處，併以全身為貴，優之遊之，鹹以忘懷自逸，若此眾君子，可謂得之矣。","sortOrder":35},
  {"id":"s_work_nvlt_21_37","chapterId":"ch_work_nvlt_21","text":"《尚書》曰：舜帝曰：俞，咨禹，汝平水土，惟時懋哉，禹拜稽首，讓於稷暨皋陶。","sortOrder":37},
  {"id":"s_work_nvlt_21_38","chapterId":"ch_work_nvlt_21","text":"周官大司徒職曰：以陽禮教讓，則民不爭。","sortOrder":38},
  {"id":"s_work_nvlt_21_39","chapterId":"ch_work_nvlt_21","text":"《禮記》曰：君子恭敬樽節退讓以明禮。","sortOrder":39},
  {"id":"s_work_nvlt_21_40","chapterId":"ch_work_nvlt_21","text":"又曰：子雲，觴酒豆肉，讓而受惡，民猶犯齒，衽席之上，讓而坐下，民猶犯貴，朝庭之位，讓而就賤，民猶犯忠。","sortOrder":40},
  {"id":"s_work_nvlt_21_41","chapterId":"ch_work_nvlt_21","text":"又曰：君子貴人而賤己，先人而後己，則民作讓。","sortOrder":41},
  {"id":"s_work_nvlt_21_42","chapterId":"ch_work_nvlt_21","text":"又曰：天子有善，讓德於天，諸侯有善，歸諸天子。","sortOrder":42},
  {"id":"s_work_nvlt_21_43","chapterId":"ch_work_nvlt_21","text":"《左傳》曰：宋穆公疾，召大司馬孔父而屬殇公焉，曰：先君舍與夷而立寡人，若弃德不讓，是废先君之舉也，豈曰能賢。","sortOrder":43},
  {"id":"s_work_nvlt_21_44","chapterId":"ch_work_nvlt_21","text":"又曰：齊侯使管夷吾平戎於晉，王使隰朋平戎於晉，王以上卿之禮饗管仲，辭曰：臣賤有司也，有天子之守國高在，若節春秋，來承王命，何以禮焉，陪臣敢辭，王曰：舅氏，餘嘉乃勋，應乃懿德，謂督不忘，往踐乃職，管仲受下卿之禮而還，君子曰：管氏之世祀也，宜哉，讓不忘其上。","sortOrder":44},
  {"id":"s_work_nvlt_21_45","chapterId":"ch_work_nvlt_21","text":"又曰：讓禮之主也，范宣子讓，其下皆讓。","sortOrder":45},
  {"id":"s_work_nvlt_21_46","chapterId":"ch_work_nvlt_21","text":"《論語》曰：子曰：太伯三以天下讓，民無得而稱焉。","sortOrder":46},
  {"id":"s_work_nvlt_21_47","chapterId":"ch_work_nvlt_21","text":"《孝經》曰：先之以敬讓，而民不爭。","sortOrder":47},
  {"id":"s_work_nvlt_21_48","chapterId":"ch_work_nvlt_21","text":"《家語》曰：虞芮二國爭田而訟，連年不决，相謂曰：西伯仁人也，盍往质焉，入其境，則耕者讓畔，行者讓路，入其朝，則士讓為大夫，大夫讓為卿，虞芮之君曰：吾儕小人，不可以入君子之朝，［事具產業部田篇。］","sortOrder":48},
  {"id":"s_work_nvlt_21_49","chapterId":"ch_work_nvlt_21","text":"《周書》曰：湯放桀於亳，三千諸侯大會，湯取天子之玺，置之天子之坐，再拜，從諸侯之位，湯曰：此天子之位，有道者可以處之，三讓三千諸侯，諸侯莫敢即位，然後湯即天子之位。","sortOrder":49},
  {"id":"s_work_nvlt_21_50","chapterId":"ch_work_nvlt_21","text":"《慎子》曰：尧讓許由，舜讓善卷，皆辭為天子，而退為疋夫。","sortOrder":50},
  {"id":"s_work_nvlt_21_51","chapterId":"ch_work_nvlt_21","text":"《列子》曰：昔尧舜伪以天下讓許由善卷，而不失天下，伯夷叔齊，實以孤竹讓，而終忘其國。","sortOrder":51},
  {"id":"s_work_nvlt_21_52","chapterId":"ch_work_nvlt_21","text":"《莊子》曰：尧以天下讓許由，曰：日月出矣，而爝火不息，其於光也，不亦難乎，時雨降矣，而猶浸灌，其於泽也，不亦勞乎。","sortOrder":52},
  {"id":"s_work_nvlt_21_53","chapterId":"ch_work_nvlt_21","text":"《山海經》曰：君子國民，衣冠帶劍，土方千里，多薰華之草，好讓，故為君子國。","sortOrder":53},
  {"id":"s_work_nvlt_21_54","chapterId":"ch_work_nvlt_21","text":"《史記》曰：太伯虞仲，知古公欲立季歷以傳昌，乃亡如荆蠻，文身斷發，以讓季歷。","sortOrder":54},
  {"id":"s_work_nvlt_21_55","chapterId":"ch_work_nvlt_21","text":"又曰：太尉周勃立代王，代王曰：奉高帝宗廟事重，寡人不佞，不足以稱，寡人不敢當，群臣皆伏，固請，代王西向讓者三，南向讓者再，［事具帝王部。］又曰：魯連既說秦軍，秦軍為却，平原君欲封魯連，魯連辭謝者三，終不肯受，平原乃置酒，酒酣起前，以千金為魯連寿，連叹曰：所貴天下之士者，為人排患釋難解紛而無所取也，即有取者，是商贾之事，連不忍為也，遂辭而去，終身不复見，［事具隱逸部。］","sortOrder":55},
  {"id":"s_work_nvlt_21_56","chapterId":"ch_work_nvlt_21","text":"又曰：董偃與馆陶主家兒博戲殿下，主伏槛觀之，偃負财［《太平御覽》四百二十三作則。］饒人，勝則有讓，主益奇之。","sortOrder":56},
  {"id":"s_work_nvlt_21_57","chapterId":"ch_work_nvlt_21","text":"又曰：伯夷叔齊，孤竹君之子也，父欲立叔齊，及卒，齊乃讓伯夷，伯夷曰：父命也，遂逃去。","sortOrder":57},
  {"id":"s_work_nvlt_21_58","chapterId":"ch_work_nvlt_21","text":"又曰：吳王諸樊元年，已除丧，讓位季札，季札弃室而耕，乃舍之，［事具隱逸篇。］","sortOrder":58},
  {"id":"s_work_nvlt_21_59","chapterId":"ch_work_nvlt_21","text":"《漢書》曰：金日磾在武帝左右，屬霍光以辅少主，光讓日磾，日磾曰：臣外國人，且使匈奴輕漢，於是遂為光副。","sortOrder":59},
  {"id":"s_work_nvlt_21_60","chapterId":"ch_work_nvlt_21","text":"又曰：文帝初立，以陳平為相，太尉周勃，親以兵誅呂氏，功多，平欲讓勃位，乃謝病，文帝怪，平曰：高帝時，勃功不如臣，及誅諸呂，臣功亦不如勃，原以相讓勃。","sortOrder":60},
  {"id":"s_work_nvlt_21_61","chapterId":"ch_work_nvlt_21","text":"又曰：韦賢薨，子玄成當為嗣，玄成心知其［《太平御覽》四百二十三其下有兄字。］非賢，即陽為病狂，臥便利，妄哭語，既葬，當袭爵，以病狂不應，大鸿臚奏状，章下丞相御史案验，玄成素有名聲，士大夫多疑其欲讓爵於兄，丞相御史遂以玄成實不病劾奏之，有詔勿劾，引拜，玄成不得已，受侯爵，［事具封爵部。］","sortOrder":61},
  {"id":"s_work_nvlt_21_62","chapterId":"ch_work_nvlt_21","text":"又曰：龚遂為渤海太守，數年，上遣使者徵遂，議曹王生原從太守會，遂引入宮，王生醉，從呼曰：原有所白，遂問其故，王生曰：天子即問君何以治渤海，君不可有所陳，宜曰：皆聖主之德，非小臣之力也，上果問以治状，遂對如王生言，天子悅其有讓，叹曰：君安得長者之言而稱之，遂因前曰：臣非有知，此乃臣議曹教戒臣也。","sortOrder":62},
  {"id":"s_work_nvlt_21_63","chapterId":"ch_work_nvlt_21","text":"《東觀漢記》曰：承宮遭王莽篡位，天下扰攘，盜賊併起，宮遂避世漢中，建武四年，將妻子之華陰山穀，耕种禾黍，臨熟，人就認之，宮悉推與而去，由是顯名。","sortOrder":63},
  {"id":"s_work_nvlt_21_64","chapterId":"ch_work_nvlt_21","text":"又曰：上封朱祐，祐自陳功薄而國大，原受南陽五百戶足矣，上不許。","sortOrder":64},
  {"id":"s_work_nvlt_21_65","chapterId":"ch_work_nvlt_21","text":"又曰：窦融，光武時數辭爵位，因上疏曰：臣融年五十三，有一子，年十五，质性顽钝，臣融朝夕教导以經藝，不得令觀天文，見讖記，誠欲令恭肅畏事，恂恂脩道，不顯其有才能，何况乃當傳以連城廣土，享侯國哉。","sortOrder":65},
  {"id":"s_work_nvlt_21_66","chapterId":"ch_work_nvlt_21","text":"又曰：邓骘，永初元年，封骘等，以定策增三千戶，讓不獲，遂逃避使者，閉關上疏自陳。","sortOrder":66},
  {"id":"s_work_nvlt_21_67","chapterId":"ch_work_nvlt_21","text":"又曰：欧陽尚書博士缺，上欲用桓榮，榮叩頭讓曰：臣經術淺薄，不如同門生郎中彭宏楊州從事皋弘，帝曰：俞，往汝諧，因拜榮為博士。","sortOrder":67},
  {"id":"s_work_nvlt_21_68","chapterId":"ch_work_nvlt_21","text":"又曰：淳於恭以謙俭推讓為節，家有山田橡树，人有盜取之者，恭助為收拾，載之歸，乃知是恭，其盜還橡，恭不受，人又有盜刈恭禾者，恭見之，念其愧，因伏草中，至去乃起。","sortOrder":68},
  {"id":"s_work_nvlt_21_69","chapterId":"ch_work_nvlt_21","text":"《續漢書》曰：張堪讓先人餘财數百萬與兄子。","sortOrder":69},
  {"id":"s_work_nvlt_21_70","chapterId":"ch_work_nvlt_21","text":"謝承《後漢書》曰：雷義舉茂才，讓於陳重，刺史不聽，義遂佯狂，不應命，乡里為之語曰：膠漆自謂堅，不如雷與陳。","sortOrder":70},
  {"id":"s_work_nvlt_21_71","chapterId":"ch_work_nvlt_21","text":"魏武令曰：讓禮一寸，得禮一尺。","sortOrder":71},
  {"id":"s_work_nvlt_21_72","chapterId":"ch_work_nvlt_21","text":"魏武帝雜事曰：辭爵逃祿，不以利累名，不以位虧德之謂讓。","sortOrder":72},
  {"id":"s_work_nvlt_21_73","chapterId":"ch_work_nvlt_21","text":"《魏志》曰：太祖署邴原為丞相徵事，崔琰為東曹掾記，讓曰：徵事邴原，議郎張范，皆秉德純壹，志行忠方，清净足以厲俗，貞固足以幹事，所謂龍翰鳳翼，國之重寶，舉而用之，不仁者遠。","sortOrder":73},
  {"id":"s_work_nvlt_21_74","chapterId":"ch_work_nvlt_21","text":"《吳志》曰：魯肅卒，孫權以嚴畯代肅，畯前後固辭曰：仆素書生，不閒軍事，非才而據，咎悔必至，發言慷慨，至於流涕，權乃聽焉，世嘉其能以實讓。","sortOrder":74},
  {"id":"s_work_nvlt_21_75","chapterId":"ch_work_nvlt_21","text":"又曰：薛綜為選曹尚書，固讓顧谭，曰：谭心精體密，貫道達微，才照人物，德服眾望，誠非愚誠所可越先。","sortOrder":75},
  {"id":"s_work_nvlt_21_76","chapterId":"ch_work_nvlt_21","text":"又曰：［《太平御覽》四百二十四作晉中興書，非吳志，或前有佚條。］郄愔，字方回，拜給事黃門侍郎，愔苦求外出，時吳郡缺，朝讓［御覽作議。］用愔，愔以資輕而年少，不宜超登大郡，辭讓切至，朝廷嘉之。","sortOrder":76},
  {"id":"s_work_nvlt_21_77","chapterId":"ch_work_nvlt_21","text":"《江表傳》曰：程普頗以年長陵侮周瑜，瑜折節下之，不與計，普後自敬而親重之，乃告人曰：吾與周公瑾交，若飲淳醪，不覺醉時也。","sortOrder":77},
  {"id":"s_work_nvlt_21_78","chapterId":"ch_work_nvlt_21","text":"許遜別傳曰：遜年七歲，無父，躬耕負薪以養母，盡孝敬之道，與寡嫂共田桑，推讓好者，自取其荒，不營榮利，母常譴之，如此，當乞食無處居，笑應母曰：但原老母寿耳。","sortOrder":78},
  {"id":"s_work_nvlt_21_79","chapterId":"ch_work_nvlt_21","text":"郭翻別傳曰：翻經水，墜刀於水，路人有為取者，翻因與之，路人不取，至於三四，路人固辭，翻曰：爾向不取，我豈能得乎，路人曰：吾若取此物，為天地鬼神所责矣，翻知其終不受，乃沉刀於向所失處，路人怅然，乃复没為取之，翻於是不逆其意，十倍刀价與之。","sortOrder":79},
  {"id":"s_work_nvlt_21_80","chapterId":"ch_work_nvlt_21","text":"《符子》曰：太伯將讓其國於季歷，謂其傅曰：太王欲以一國之事而以嗣我，我其羞之，吾聞至人也，不君一世，而萬世以之君，不貴一代，而萬代以之貴，吾焉能貴乎一國，而賤乎萬代哉。","sortOrder":80},
  {"id":"s_work_nvlt_21_81","chapterId":"ch_work_nvlt_21","text":"【碑】梁陆雲［全梁文五十三作陆雲公。］太伯碑曰：夫至仁至德，垂風垂化，內脩訓范，外陶氓俗，百年之教，淳道載凝，而百年既終，遺愛斯軫，莫不肅虔寢廟，著名金石，貽其後崑，聿遵前典，是以禹堂既毀，增飾丹青，尧碑載焚，重睹刊勒，太伯膺慶二儀，协靈七曜，志輕天下，慈深萬物，脱屣歧周，克讓之風斯舉，端委楊越，衣冠之俗載成，重以仲雍扬波，延陵蹈節，民習敦厚，俗懷忠信，忧深思遠，千載遺風，美哉洋洋，致足觀也，昔蒼洲遁跡，箕山辭位，志守幽優，不越鐏俎，猶以稱首高節，摽名往代，豈若吾君之子，義結民心，獄訟載歸，謳歌屢請，能舍玉舆之貴，永袭皮冠之跡，悠然獨往，信無德而稱焉，吾［疑當作吳。］啟金車，晉遷紫蓋，寔號帝乡，爰是天邑，若乃忠人入國，凄怆生悲，殉義希風，懦夫立志。","sortOrder":81},
  {"id":"s_work_nvlt_21_82","chapterId":"ch_work_nvlt_21","text":"【論】晉劉寔崇讓論曰：古之聖王之治天下所以貴讓者，欲以出賢才而息爭也，夫人情莫不皆欲己之賢也，故勸令讓賢，以自明賢，豈假讓不［太平御覽四百二十四作而。］賢哉，故讓道興，賢能之人，不求而自出矣，至公之舉而自立矣，一官缺，擇眾官所讓最多者而用之，審才之道也，在朝之人，相讓於上，草庐之人，鹹皆化之，推能讓賢之風，從此生矣，為一國所讓，一國士也，天下所共，則天下才也，推讓之風行，賢與不肖，灼然殊矣，此道之行，在上者無所用其心，故曰：荡荡乎尧之為君，莫之能名，言天下自治，不見尧所以治之，故不能名也。又曰舜禹之有天下，而不與焉，無為而治者，其舜也欤，賢人相讓於朝，大才之人，恒在大官，小人不爭於野，則天下無事矣，以賢才治無事，至治興矣，已抑［晉書四十一寔傳作仰。］其成，复何所與，故可歌南風之詩，彈五絃之琴也。","sortOrder":82},
  {"id":"s_work_nvlt_21_83","chapterId":"ch_work_nvlt_21","text":"晉孫盛周泰伯三讓論曰：孔子曰：太伯其可謂至德也已矣，三以天下讓，民無得而稱焉，鄭玄以為讬采藥而行，一讓也，不奔丧，二讓也，斷發文身，三讓也，三者之美，皆蔽隱不著，王肅曰：其讓隱，故民無得而稱焉，盛謂玄既失之，而肅亦未為得也，玄之所雲，三跡顯然，天下所共見也，何得雲隱而未著乎，三跡苟著，則高讓可知，亦复不得雲其讓隱也，蓋太伯之出，讓跡已露，不奔丧，故一事耳，斷發之言，與左傳明文相背。又不經也，然則稱三讓者，其在古公至文王乎，周之王業，顯於亶父，受命於昌，太伯玄覽，弃周太子之位，一讓也，假讬遜遁，受不赴丧之譏，潛推大美，二讓也，無胤嗣而不養仲雍之子以為己後，是其深思遠防，令周嫡在昌，天人葉從，四海悠悠，無复纖芥疑惑，三讓也，凡此三者，帝王之業，故孔子曰：三以天下讓，言非其常讓，若臧札之倫者也。","sortOrder":83},
  {"id":"s_work_nvlt_21_85","chapterId":"ch_work_nvlt_21","text":"《爾雅》曰：距齊州以南，戴日為丹穴，丹穴之人智。","sortOrder":85},
  {"id":"s_work_nvlt_21_86","chapterId":"ch_work_nvlt_21","text":"《易》曰：智周萬物，道濟天下。","sortOrder":86},
  {"id":"s_work_nvlt_21_87","chapterId":"ch_work_nvlt_21","text":"《論語》曰：智者樂水。","sortOrder":87},
  {"id":"s_work_nvlt_21_88","chapterId":"ch_work_nvlt_21","text":"又曰：智者動。","sortOrder":88},
  {"id":"s_work_nvlt_21_89","chapterId":"ch_work_nvlt_21","text":"又曰：甯武子，邦有道則知。","sortOrder":89},
  {"id":"s_work_nvlt_21_90","chapterId":"ch_work_nvlt_21","text":"又曰：若臧武仲之智。","sortOrder":90},
  {"id":"s_work_nvlt_21_91","chapterId":"ch_work_nvlt_21","text":"又曰：智者不惑。","sortOrder":91},
  {"id":"s_work_nvlt_21_92","chapterId":"ch_work_nvlt_21","text":"《禮記》曰：舜其大智欤，［事具帝王部。］","sortOrder":92},
  {"id":"s_work_nvlt_21_93","chapterId":"ch_work_nvlt_21","text":"《周書》曰：智與眾同者，非人師也，且成事必在大智。","sortOrder":93},
  {"id":"s_work_nvlt_21_94","chapterId":"ch_work_nvlt_21","text":"《家語》曰：孔子曰：好學則智。","sortOrder":94},
  {"id":"s_work_nvlt_21_95","chapterId":"ch_work_nvlt_21","text":"《商君書》曰：愚者闇於成事，而智者見於未萌。","sortOrder":95},
  {"id":"s_work_nvlt_21_96","chapterId":"ch_work_nvlt_21","text":"《莊子》曰：巧者勞而智者優。","sortOrder":96},
  {"id":"s_work_nvlt_21_97","chapterId":"ch_work_nvlt_21","text":"又曰：大智閒閒，小智間間。","sortOrder":97},
  {"id":"s_work_nvlt_21_98","chapterId":"ch_work_nvlt_21","text":"《孫卿子》曰：言而當，智也，嘿而當，亦智也。","sortOrder":98},
  {"id":"s_work_nvlt_21_99","chapterId":"ch_work_nvlt_21","text":"又曰：是是非非謂之智。","sortOrder":99},
  {"id":"s_work_nvlt_21_100","chapterId":"ch_work_nvlt_21","text":"《戰國策》曰：今六國相伐，適足以強秦，天下為秦相烹，秦曾不出薪，何秦之智，而山東之愚耶。","sortOrder":100},
  {"id":"s_work_nvlt_21_101","chapterId":"ch_work_nvlt_21","text":"《淮南子》曰：夫聖人之智，固已多矣，愚人之智，固已少矣。","sortOrder":101},
  {"id":"s_work_nvlt_21_102","chapterId":"ch_work_nvlt_21","text":"又曰：裨諶出郊而智。","sortOrder":102},
  {"id":"s_work_nvlt_21_103","chapterId":"ch_work_nvlt_21","text":"又曰：文公种米，曾子枷羊，猶為智也。","sortOrder":103},
  {"id":"s_work_nvlt_21_104","chapterId":"ch_work_nvlt_21","text":"唐子曰：命相在天，才智由人，由人可學致，在天無可冀。","sortOrder":104},
  {"id":"s_work_nvlt_21_105","chapterId":"ch_work_nvlt_21","text":"《符子》曰：尧舜之智，桀紂以為不智，尧舜以為智，惡知尧舜之非桀紂，桀紂之非尧舜乎。","sortOrder":105},
  {"id":"s_work_nvlt_21_106","chapterId":"ch_work_nvlt_21","text":"《史記》曰：樗里子名疾，滑稽多智，秦人號曰智囊。","sortOrder":106},
  {"id":"s_work_nvlt_21_107","chapterId":"ch_work_nvlt_21","text":"又曰：陳平智有餘而難獨任。","sortOrder":107},
  {"id":"s_work_nvlt_21_108","chapterId":"ch_work_nvlt_21","text":"《漢書》曰：劉德少脩黃老術，有智略，武帝謂之千里駒。","sortOrder":108},
  {"id":"s_work_nvlt_21_109","chapterId":"ch_work_nvlt_21","text":"諸葛亮集曰：曹操智計，殊絕於人。","sortOrder":109},
  {"id":"s_work_nvlt_21_110","chapterId":"ch_work_nvlt_21","text":"《魏志》曰：贾詡自以非太祖舊臣，懼見猜嫌，阖門自守，退無私交，婚嫁不結高門，天下之論智計者歸之。","sortOrder":110},
  {"id":"s_work_nvlt_21_111","chapterId":"ch_work_nvlt_21","text":"《魏略》曰：司馬宣王聞諸葛恪死，曰：張敬仲懸論恪，以為必見殺，今果然，張仲之智，為勝恪也。","sortOrder":111},
  {"id":"s_work_nvlt_21_112","chapterId":"ch_work_nvlt_21","text":"王隱《晉書》曰：石季倫少多意智，敏捷有計略。","sortOrder":112},
  {"id":"s_work_nvlt_21_113","chapterId":"ch_work_nvlt_21","text":"《華陽國志》曰：任文公聞武簷石折，曰：噫，方［《太平御覽》四百三十二方上有西字。］智者死，吾其應之，遂卒，益部為之謠曰：任文公，智無双。","sortOrder":113},
  {"id":"s_work_nvlt_21_114","chapterId":"ch_work_nvlt_21","text":"【賦】楚荀况智賦曰：皇天隆物，以施下民，或厚或薄，常弗齊均，桀紂以亂，湯武以賢，臣愚弗識，原聞其名，曰外勝敵者邪，法禹舜而能弇跡者邪，行為動靜，待之而後適者邪，血氣之精也，志意之榮也，百姓待之而後寧也，天下待之而後平也，明遠純粹而無疵，夫是謂君子之智。","sortOrder":114},
  {"id":"s_work_nvlt_21_115","chapterId":"ch_work_nvlt_21","text":"◇性命","sortOrder":115},
  {"id":"s_work_nvlt_21_116","chapterId":"ch_work_nvlt_21","text":"《易》曰：乾道变化，各正性命。","sortOrder":116},
  {"id":"s_work_nvlt_21_117","chapterId":"ch_work_nvlt_21","text":"又曰：樂天知命而不忧。","sortOrder":117},
  {"id":"s_work_nvlt_21_118","chapterId":"ch_work_nvlt_21","text":"《毛詩》曰：文王受命，有此武功。","sortOrder":118},
  {"id":"s_work_nvlt_21_119","chapterId":"ch_work_nvlt_21","text":"又曰：文王受命以作周。","sortOrder":119},
  {"id":"s_work_nvlt_21_120","chapterId":"ch_work_nvlt_21","text":"《尚書》曰：無墜天之降寶命。","sortOrder":120},
  {"id":"s_work_nvlt_21_121","chapterId":"ch_work_nvlt_21","text":"又曰：用集大命於厥躬。","sortOrder":121},
  {"id":"s_work_nvlt_21_122","chapterId":"ch_work_nvlt_21","text":"又雲，天其永我命於茲新邑。","sortOrder":122},
  {"id":"s_work_nvlt_21_123","chapterId":"ch_work_nvlt_21","text":"春秋曰：劉子曰：人受天地之中以生，所謂命也。","sortOrder":123},
  {"id":"s_work_nvlt_21_124","chapterId":"ch_work_nvlt_21","text":"《禮記》曰：天命之謂性，率性之謂道，修道之謂教。","sortOrder":124},
  {"id":"s_work_nvlt_21_125","chapterId":"ch_work_nvlt_21","text":"《論語》：子夏曰：死生有命，富貴在天。","sortOrder":125},
  {"id":"s_work_nvlt_21_126","chapterId":"ch_work_nvlt_21","text":"又曰：子罕言利與命與仁。","sortOrder":126},
  {"id":"s_work_nvlt_21_127","chapterId":"ch_work_nvlt_21","text":"又曰：五十而知天命。","sortOrder":127},
  {"id":"s_work_nvlt_21_128","chapterId":"ch_work_nvlt_21","text":"又曰：道之將行也欤，命也，道之將废也欤，命也。","sortOrder":128},
  {"id":"s_work_nvlt_21_129","chapterId":"ch_work_nvlt_21","text":"《楚辭》曰：哀時命者，屈原之所作也。","sortOrder":129},
  {"id":"s_work_nvlt_21_130","chapterId":"ch_work_nvlt_21","text":"《家語》曰：魯哀公問於孔子曰：人之命與性何謂，孔子對曰：分於道謂之命，形於一謂之性。","sortOrder":130},
  {"id":"s_work_nvlt_21_131","chapterId":"ch_work_nvlt_21","text":"《史記》曰：孟嘗君五月五日生，其父靜郭君曰：五月子，長至戶則害父，孟嘗君曰：人受命於天，豈受命於戶。","sortOrder":131},
  {"id":"s_work_nvlt_21_132","chapterId":"ch_work_nvlt_21","text":"《漢書》曰：高祖曰：吾起自布衣，提三尺劍，以取天下，豈非命也，［事具軍器部劍篇。］","sortOrder":132},
  {"id":"s_work_nvlt_21_133","chapterId":"ch_work_nvlt_21","text":"范晔《後漢書》曰：藝可學而行，天爵高懸，得之者命也。","sortOrder":133},
  {"id":"s_work_nvlt_21_134","chapterId":"ch_work_nvlt_21","text":"【賦】晉仲長敖覈性賦曰：趙荀卿著書，言人性之惡，弟子李斯韓非，顧而相謂曰：夫子之言性惡當矣，未詳才之善否何如，原聞其說，荀卿曰：天地之間，兆族羅列，同禀氣质，無有區別，裸虫三百，人最為劣，爪牙皮毛，不足自衛，唯賴诈伪，迭相嚼齧，總而言之，少尧多桀，但見商鞅，不聞稷契，父子兄弟，殊情異計，君臣朋友，志乖怨結，怜國乡党，務相吞噬，台隸僮竖，唯盜唯竊，面從背违，意與口戾，言如飴蜜，心如蠻厲，未知勝負，便相凌蔑，正路莫踐，競赴邪轍，利害交爭，豈顧憲製，懷仁抱義，祇受其毙，周孔徒勞，名教虛設，蠢爾一槩，智不相絕，推此而談，孰癡孰黠，法術之士，能不噤齘，仰則扼腕，俯則攘袂，荀卿之言未終，韓非越席起舞，李斯击節長歌，其辭曰：形生有極，嗜欲莫限，達鼻耳，开口眼，納眾惡，距群善，方寸地，九折坂，為人作崄易，俄頃成此蹇，多謝悠悠子，悟之不亦晚。","sortOrder":134},
  {"id":"s_work_nvlt_21_135","chapterId":"ch_work_nvlt_21","text":"【論】晉李康運命論曰：夫治亂，運也，窮達，命也，貴賤，時也，故運之所降，必生聖明之君，聖明之君，必有忠賢之臣，其所以相遇也，不求而自合，其所以相親也，不介而自親，唱之而必和，謀之而必從，得失不能疑其志，讒構不能離其交，然後得成功也，其所以得然者，豈徒人事哉，授之者天也，告之神也，成之者運也，張良誦三略之說，以遊於群雄，其言也，如以水投石，莫之受也，及其遭漢祖，其言也，如以石投水，莫之逆也，非張良之拙說於陳項，而巧言於沛公也，然則聖人所以為聖者，蓋在乎樂天知命，故遇之而不怨，居之而不疑，是以聖人處窮達如一也，子夏曰：死生有命，富貴在天，故道之將行也，命之將貴也，則伊尹呂尚，興於殷周，百里子房，用於秦漢矣，道之將废也，豈獨君子恥之而弗為乎，蓋亦知為之而弗得矣。","sortOrder":135},
  {"id":"s_work_nvlt_21_136","chapterId":"ch_work_nvlt_21","text":"晉袁准才性論曰：凡萬物生於天地之間，有美有惡，物何故美，清氣之所生也，物何故惡，濁氣之所施也，夫金石絲竹，中天地之氣，黼黻玄黃，應五方之色，有五君子以此得，［文有脱訛。］曲直者木之性也，曲者中鉤，者繩［有脱。］輪桷之材也，賢不肖者人之性也，賢者為師，不肖者為資，師資之材也，然則性言其质，才名其用，明矣。","sortOrder":136},
  {"id":"s_work_nvlt_21_137","chapterId":"ch_work_nvlt_21","text":"宋何承天達性論曰：夫兩儀既位，帝王參之，宇中莫尊焉，天以陰陽分，地以刚柔用，人以仁義立，人非天地不生，天地非人不靈，三材同體，相須而成者也，故能禀氣清和，神明特達，情綜古今，智周萬物，妙思窮幽赜，製作侔造化，歸仁與能，是為君長，撫養黎元，助天宣德，日月淑清，四靈來格，祥風协律，玉燭扬暉，酸鹹百品，備其膳羞，絲纻玄黃，供其器服，文以禮度，娱以八音，夫物用俭則易足，易足則力有餘，有餘則情志泰，樂治之心，於是生焉，事簡則不扰。不扰則神明靈，神明靈則謀慮審，濟治之務，於是成焉，故天地以俭素訓民，乾坤以易簡示物，殷勤若此之篤也，安得與夫飛沉喘蠕，併為眾生者，取之有時，用之有道，行火俟風暴，田漁候銶獭祭，所以順天時也，大夫不麛卵，庶人不數罟，行苇作歌，宵魚垂化，所以愛人用也，庖厨不邇，五豝是翼，殷後改祝，孔釣不綱，［按當作網。］所以明仁道也。","sortOrder":137},
  {"id":"s_work_nvlt_21_138","chapterId":"ch_work_nvlt_21","text":"梁劉孝標辨命論曰：臣觀管辂，天才英伟，珪璋特秀，實海內之名杰，而官止少府丞，年終四十八，天之報施，何其寡欤，然則高才而無貴仕，饕餮而居大位，自古所叹焉，獨公明而已哉，故性命之道，窮通之數，夭閼紛纶，莫知其辨，仲任蔽其源，子長闡其惑，至於褐冠瓮牖，必以玄天有期，鼎貴高門，則曰唯人所召，萧遠論其本，而不畅其流，子玄語其流，而未詳其本，嘗言之曰：夫道生萬物，則謂之道，生而無主，謂之自然，自然者，物見其然，不知所以然，同焉皆得，不知所以得，鼓動陶鑄，而不為功，庶類混成，而非其力，荡乎大乎，萬寶以之化，確乎純乎，一化而不易，化而不易，則謂之命，命也者，自天之命也，定於冥兆，終然不变，鬼神莫可預，聖哲不能謀，觸山之力無以抗，倒日之誠弗能感，短則不可缓之於寸陰，長則不可急之於箭漏，至乃伍員浮尸於江流，三闾沉骸於湘渚，贾大夫沮志於長沙，冯都尉皓發於郎署，君山鸿漸，鎩羽儀於高雲，敬通鳳起，摧迅翮於風穴，此豈才不足而行有遺哉，近世有沛國劉瓛，瓛弟璡，併一時之秀士也，瓛則關西孔子，通涉六經，循循善誘，服膺儒行，璡則志烈秋霜，心貞琨玉，亭亭高耸，不雜風尘，皆毓德於衡門，併馳聲於天地，而官有微於侍郎，位不登於執戟，相次殂落，宗祀無饗，因斯兩賢以言古，則昔之玉质金相，英髦秀達，擯斥於當年，韞奇才而莫用，候草木以共凋，與麋鹿而同死，膏涂平原，骨填川穀，煙滅而無聞者，豈可勝道哉，故曰：死生有命，富貴在天，其斯之謂矣，或者睹湯武之龍躍，謂戡亂在神功，聞孔墨之挺生，謂英睿擅奇响，视韓彭之豹变，謂鷙猛致人爵，見張桓之朱绂，謂明經拾青紫，豈知有力者運之而趍乎，然則君子居正體道，樂天知命，其無可奈何，識其不由智力，逝而不召，來而不拒，生而不喜，死而不戚，不充诎於富貴，不遑遑於所欲，豈有史公董相不遇之文乎。","sortOrder":138},
  {"id":"s_work_nvlt_21_139","chapterId":"ch_work_nvlt_21","text":"◇友悌","sortOrder":139},
  {"id":"s_work_nvlt_21_140","chapterId":"ch_work_nvlt_21","text":"《爾雅》曰：善兄弟為友。","sortOrder":140},
  {"id":"s_work_nvlt_21_141","chapterId":"ch_work_nvlt_21","text":"《尚書》曰：惟孝友於兄弟。","sortOrder":141},
  {"id":"s_work_nvlt_21_142","chapterId":"ch_work_nvlt_21","text":"《毛詩》曰：陟彼岡兮，瞻望兄兮。","sortOrder":142},
  {"id":"s_work_nvlt_21_143","chapterId":"ch_work_nvlt_21","text":"又曰：棠棣之華，萼不韡韡，凡今之人，莫如兄弟，死丧之威，兄弟孔懷，原隰裒矣，兄弟求矣，鹡鸰在原，兄弟急難。","sortOrder":143},
  {"id":"s_work_nvlt_21_144","chapterId":"ch_work_nvlt_21","text":"又曰：兄弟既翕，和樂且湛。","sortOrder":144},
  {"id":"s_work_nvlt_21_145","chapterId":"ch_work_nvlt_21","text":"又曰：衛宣公之二子，爭相為死。","sortOrder":145},
  {"id":"s_work_nvlt_21_146","chapterId":"ch_work_nvlt_21","text":"《孝經》曰：孝悌之至，通於神明。","sortOrder":146},
  {"id":"s_work_nvlt_21_147","chapterId":"ch_work_nvlt_21","text":"《禮記》曰：兄弟親戚，稱其慈也，寮友稱其悌也。","sortOrder":147},
  {"id":"s_work_nvlt_21_148","chapterId":"ch_work_nvlt_21","text":"又曰：兄良弟悌，夫義婦聽，家之肥也。","sortOrder":148},
  {"id":"s_work_nvlt_21_149","chapterId":"ch_work_nvlt_21","text":"《論語》曰：兄弟怡怡如也。","sortOrder":149},
  {"id":"s_work_nvlt_21_150","chapterId":"ch_work_nvlt_21","text":"《列女傳》曰：［御覽四百十六作宋躬孝子傳。］任延寿之妻，字季兒，有三子，季兒兄季宗，□［宗下原空一字，《太平御覽》四百十六作與延寿爭事五字。］延寿與其友殺季宗，後會赦，乃以告季兒，季兒曰：嘻，乃今語我乎，季兒曰：殺夫不義，事兄之讎亦不義，何面目以生，而戴天履地乎，延寿慚，自經，［按御覽，乃季兒遂自經死，事見列女傳五，此有脱字。］又曰：古師安妻呂君，少寡無子，其兄犯法，君乃泣曰：少遭家不造，兄弟单鮮，門宗唯兄存，而复此禍，我有一計，猶足免難，為辭乞代兄命，自經縣門，縣官嘉其義，乃舍之。","sortOrder":150},
  {"id":"s_work_nvlt_21_151","chapterId":"ch_work_nvlt_21","text":"又曰：齊宣王時，有人斗死道者，被一創，齊義二子立其傍，吏問之，兄曰：我煞之，弟曰：非兄，乃我煞之，期年相推不决，召其母，問所欲殺活，母泣對曰：煞少者，相曰：少子人之所愛，欲煞之何也，對曰：少者妾之子，長者前妻之子，子雖痛，謂義何，宣王美其義，皆赦之。","sortOrder":151},
  {"id":"s_work_nvlt_21_152","chapterId":"ch_work_nvlt_21","text":"《漢書》曰：卜式以田蓄為事，有少弟，弟壮，式脱身出，獨取畜羊百餘，田宅财物盡與弟，式牧十餘年，羊致千餘頭，買田宅，而弟盡破其產。又分财與弟者數矣。","sortOrder":152},
  {"id":"s_work_nvlt_21_153","chapterId":"ch_work_nvlt_21","text":"又曰：王商父薨，商嗣，推财以分異母諸弟，商無所受。","sortOrder":153},
  {"id":"s_work_nvlt_21_154","chapterId":"ch_work_nvlt_21","text":"《東觀漢記》曰：魏霸為長史，妻子不到官舍，念兄嫂在家勤苦，而獨尊樂，故常服粗，不食魚肉，其子躬耕，與兄弟子同苦樂，乡里皆慕其化。","sortOrder":154},
  {"id":"s_work_nvlt_21_155","chapterId":"ch_work_nvlt_21","text":"又曰：王琳年十餘，丧父母，遭大亂，百姓奔逃，唯琳兄弟獨守家庐，弟季出，遇赤眉賊，將為餔，琳自縛，請先季死，賊矜而放之。","sortOrder":155},
  {"id":"s_work_nvlt_21_156","chapterId":"ch_work_nvlt_21","text":"又曰：趙孝，兄弟怡怡，乡党歸德，天下亂，人相食，弟禮為賊所得，孝詣賊曰：禮羸瘦，不如孝肥，賊併放之。","sortOrder":156},
  {"id":"s_work_nvlt_21_157","chapterId":"ch_work_nvlt_21","text":"《續漢書》曰：薑肱兄弟二人，皆以孝行著，與弟仲同被臥，慈親相友，及長相愛，不能相離。","sortOrder":157},
  {"id":"s_work_nvlt_21_158","chapterId":"ch_work_nvlt_21","text":"《吳書》曰：劉繇與群弟居，常夜臥早起，妻妾希見其面。","sortOrder":158},
  {"id":"s_work_nvlt_21_159","chapterId":"ch_work_nvlt_21","text":"【詩】魏陳王曹植赠弟白馬王彪詩曰：謁帝承明庐，逝將歸舊疆，清晨發皇邑，日夕過首陽，伊洛曠且深，欲濟川無梁，汎舟越洪涛，怨彼東路長，脩阪造雲日，我馬玄以黃，鴟枭鳴衡軛，銶狼當路衢，蒼蠅間白黑，讒巧合親疏，欲還絕無迳，攬辔止踟蹰，秋風發微涼，寒蝉鳴我侧，原野何萧條，白日忽西匿，感物傷我懷，撫心長太息，丈夫志四海，萬里猶比鄰，何必同衾帱，然後展殷勤。仓卒骨肉情，能不懷苦辛。","sortOrder":159},
  {"id":"s_work_nvlt_21_160","chapterId":"ch_work_nvlt_21","text":"晉陆機與弟雲詩曰：有命自天，崇替靡常，王師乘運，席卷江湘，俯慚堂構，仰惟先靈，孰雲忍愧，寄之我情，昔我斯逝，族有餘榮，今我來思，堂有哀聲，我行其道，鞠為茂草，我履其房，物存人亡，撫膺泣血，洒淚彷徨。","sortOrder":160},
  {"id":"s_work_nvlt_21_161","chapterId":"ch_work_nvlt_21","text":"晉陆雲答兄詩曰：昔我崑弟，如鸞如龍，今我友生，凋俊墜雄，華堂傾榱，廣宅頹墉，高門降衡，循庭树蓬。","sortOrder":161},
  {"id":"s_work_nvlt_21_162","chapterId":"ch_work_nvlt_21","text":"宋謝瞻答靈運詩曰：華萼相光飾，嘤鳴悅同饗，親親子敦餘，賢賢吾爾賞，此景後鮮暉，雲當一日長，萎葉受榮條，涸流好河廣。","sortOrder":162},
  {"id":"s_work_nvlt_21_163","chapterId":"ch_work_nvlt_21","text":"梁簡文帝應令詩曰：微軀多幸，接萼嘉運，紫幄承慈，青襟禀訓，傍玉流溫，依蘭染薰，百氏既洽，六義乃摛，辭河泻润，高論忘疲，翠幕晨宇，朱花夜池，窗斜八綺，燈懸百支。","sortOrder":163},
  {"id":"s_work_nvlt_21_164","chapterId":"ch_work_nvlt_21","text":"梁昭明太子示徐州弟詩曰：宴君晝室，靖眺銅池，三墳既覽，四始兼摛，高宇既清，虛堂复靜，義府載陳，玄言斯逞。","sortOrder":164},
  {"id":"s_work_nvlt_21_165","chapterId":"ch_work_nvlt_21","text":"梁劉孝綽與虞弟詩曰：下邑非上郡，徒然想二冯，餘慚野王德，爾勖聖乡風，望望餘涂盡，凄凄良宴終，朝蔬一不共，夜被何由同。","sortOrder":165},
  {"id":"s_work_nvlt_21_166","chapterId":"ch_work_nvlt_21","text":"梁劉孝勝冬日家園別陽羨始興詩曰：四鳥怨離群，三荆悅同處，如今腰艾綬，東南各殊舉，且欣棠棣集，弥惜光陰遽，黠吏本須裁，豪民亦難御，原勖千金水，思聞五湖譽。","sortOrder":166},
  {"id":"s_work_nvlt_21_167","chapterId":"ch_work_nvlt_21","text":"【賦】魏陳王曹植，建安十六年，大軍西讨馬超，太子留監國，植時從焉，意有懷恋，遂作離思之賦，在肇秋之嘉月，將曜師而西旗，餘抱疾以賓從，扶衡軫而不怡，慮征期之方至，傷無階以告辭，念慈君之光惠，庶没命而不疑，欲畢力於旌麾，將何心而遠之，原我君之自愛，為皇朝而寶己，水重深而魚悅，林循茂而鳥喜。","sortOrder":167},
  {"id":"s_work_nvlt_21_168","chapterId":"ch_work_nvlt_21","text":"又釋思賦曰：家弟出養族父郎中伊，餘以兄弟之愛，心有恋然，作此賦以赠之，彼朋友之離別，猶求思乎白駒，况同生之義絕，重背親而為疏，樂鴛鴦之同池，羨比翼之共林，亮根異其何戚，痛別幹之傷心。","sortOrder":168},
  {"id":"s_work_nvlt_21_169","chapterId":"ch_work_nvlt_21","text":"晉陆機述思賦曰：情易感於已攬，思難戢於未忘，嗟伊思之且爾，夫何往而弗臧，駭中心於同氣，分戚濬於異方，寒鳥悲而饒音，衰林愁而寡色，嗟餘情之屢傷，負大悲之無力，苟彼涂之信险，恐此日之行昃，亮相見之幾何。又離居而別域，觀尺景以傷悲，撫寸心而凄惻。","sortOrder":169},
  {"id":"s_work_nvlt_21_170","chapterId":"ch_work_nvlt_21","text":"【文】晉潘嶽哭弟文曰：视不見兮聽不聞，逝日遠兮忧弥殷，終皓首兮何時忘，情楚侧兮常苦辛。","sortOrder":170},
  {"id":"s_work_nvlt_21_171","chapterId":"ch_work_nvlt_21","text":"【祭文】宋陶潛祭從弟文曰：曰仁者寿，竊獨信之，如何斯言，獨能見斯，年甫過立，奄與世辭，長歸蒿里，邈無還期，庭树如故，齊宇廓然，孰雲敬遠，何時复旋。","sortOrder":171},
  {"id":"s_work_nvlt_21_172","chapterId":"ch_work_nvlt_21","text":"宋顏延之祖祭弟文曰：阖棺窮野，啟殯中荒，靈影夙滅，筵寢虛張，人往運來，自秋徂陽，蕃蘭落色，宿草滋長，孰雲不痛，辭家去乡，爾之於役，爰適茲邑，上秋告來，方春佇立，如何不弔，吉违凶集，六親憧心，姻朋浩泣，我雖載奔，伊何雲及，求懷在昔，追亡悼存，惟兄及弟，瞻母望崑，生無榮嬿，没望歸魂，令龟吉兆，祖榇東旋，靈轅次路，嚴舟在川，廓然何及，痛矣終天。","sortOrder":172},
  {"id":"s_work_nvlt_21_173","chapterId":"ch_work_nvlt_21","text":"【啟】梁簡文帝叙南康簡王薨上東宮啟曰：方當逸足長衢，克固蕃屏，而峰摧璧毀，一朝雲及，綱兄弟各從王役，東守西撫，常原陪承甲馆，同奉畫堂，預得西苑賦文，北場旋食，豈謂不幸，獨隔昭世，異林有悲，飛鳴斯切，伏惟殿下，愛睦思深，常棣天篤，北海雲亡，騎傳餘藁，東平告盡，驿問留書，呜呼此恨，复在茲日。","sortOrder":173},
  {"id":"s_work_nvlt_21_174","chapterId":"ch_work_nvlt_21","text":"梁劉孝儀從弟丧上東宮啟曰：亡從弟遵，百行無點，千里立志，同氣三荆之友，假寢十起之慈，皆體之於自然，行之如俯拾，自碣宮陪宴，釣台從幸，攀附鱗翼，三十餘載，茫昧與善，一旦長辭，劍匿光芒，璧碎符采，躬搖神筆，親動妙思，雖每想南皮，書憶阮瑀，行經北馆，歌悼子侯，不足辈此深仁，齊茲舊愛。","sortOrder":174},
  {"id":"s_work_nvlt_21_175","chapterId":"ch_work_nvlt_21","text":"【書】吳陆景與兄書曰：向訣不知所言，追惟衔恨，恨結胸懷，懷此恋恨，何時可言，望路則尚近，別已千里，其為思結，纏在心膂，於是離折，路人悲之，况處此戚，兼之懿好，情之感咽，何時可勝，念兄始出，既當勞思，嚴寒向隆，經涂轗軻，既宜保德，為世作資，厚自珍愛。","sortOrder":175},
  {"id":"s_work_nvlt_21_176","chapterId":"ch_work_nvlt_21","text":"又與兄書曰：自尋外役，出入三年，緣兄之篤睦，必時存之，寶錄兄書，積之盈笥，不得新命，無以自慰，時辄溫故，以釋其思，有信勿忘數字，每見手跡。如复蹔會。","sortOrder":176},
  {"id":"s_work_nvlt_21_177","chapterId":"ch_work_nvlt_21","text":"又答從兄安成王書［嚴可均全梁文二十二雲，類聚載此文於陆景後，案吳時諸陆無封安成王者，當是萧昺之文(唐讳昺為景。)安成王者萧秀也，於昺為從兄。］曰：奉告清言溢目，眷逮周委，炎光已盛，原比勝宜，仰承發止，已次新林，引邁務殷，無妨怡賞，三湘奧區，九疑形勝，浮洲動浪，聞眠鷗之舊說，安流洞浦，憶采若之遺風，昔景伯出蕃，高風振古，叔英之部，清約見稱，兄政譽平宣，威和兼濟，加以夏石奇雲，秋江迥月，翰飛紙落，理丰辭賦，賞末興餘，時希逮憶，睽離方遠，川途脩曠，炎涼方改，原加珍勖，绿字可傳，自雲終間，心傷淚洒，投筆無宣。","sortOrder":177},
  {"id":"s_work_nvlt_21_178","chapterId":"ch_work_nvlt_21","text":"梁元帝答晉安王叙南康簡王薨書曰：南康兄器宇冲貴，風神英挺，魏之中山，徒聞退讓，晉之扶風，雖號師范，用今方昔，若吞夢雲，及尋陽私疾，孝感神明，殆不勝丧，扶而後起，猶冀天道可期，豈謂福善虛說，且分违易久，嘉會難逢，綢缪宮阃，不過紈綺之歲，離群作镇，動回星紀之歷，志冀双鸞之集，遽切四鳥之悲，松茂柏悅，夙昔歡抃，芝焚蕙叹，今用呜咽。","sortOrder":178},
  {"id":"s_work_nvlt_21_179","chapterId":"ch_work_nvlt_21","text":"◇交友","sortOrder":179},
  {"id":"s_work_nvlt_21_180","chapterId":"ch_work_nvlt_21","text":"《周易》曰：二人同心，其義斷金，同心之言，其臭如蘭。","sortOrder":180},
  {"id":"s_work_nvlt_21_181","chapterId":"ch_work_nvlt_21","text":"又曰：上交不諂，下交不渎。","sortOrder":181},
  {"id":"s_work_nvlt_21_182","chapterId":"ch_work_nvlt_21","text":"《毛詩》曰：伐木，燕朋友故舊也，自天子至於庶人，未有不須友以成者也。","sortOrder":182},
  {"id":"s_work_nvlt_21_183","chapterId":"ch_work_nvlt_21","text":"又曰：雖有兄弟，不如友生。","sortOrder":183},
  {"id":"s_work_nvlt_21_184","chapterId":"ch_work_nvlt_21","text":"又曰：伐木丁丁，鳥鳴嘤嘤，出自幽穀，移於乔木。","sortOrder":184},
  {"id":"s_work_nvlt_21_185","chapterId":"ch_work_nvlt_21","text":"又曰：嘤其鳴矣，求其友聲。","sortOrder":185},
  {"id":"s_work_nvlt_21_186","chapterId":"ch_work_nvlt_21","text":"又曰：朋友攸攝，攝以威儀。","sortOrder":186},
  {"id":"s_work_nvlt_21_187","chapterId":"ch_work_nvlt_21","text":"《禮記》曰：君子之交淡如水，小人之交甘如醴，君子淡以成，小人甘以坏。","sortOrder":187},
  {"id":"s_work_nvlt_21_188","chapterId":"ch_work_nvlt_21","text":"又曰：寡婦之子，非有見焉，弗與為友。","sortOrder":188},
  {"id":"s_work_nvlt_21_189","chapterId":"ch_work_nvlt_21","text":"又曰：君子不盡人之歡，以全交也。","sortOrder":189},
  {"id":"s_work_nvlt_21_190","chapterId":"ch_work_nvlt_21","text":"又曰：儒有合志同方，營道同術，久不相見，聞流言不信，義同而進，不同退，其交友有如此者。","sortOrder":190},
  {"id":"s_work_nvlt_21_191","chapterId":"ch_work_nvlt_21","text":"《大戴禮》曰：與君子遊，苾乎如入蘭芷之室，久而不聞其香，則與之化矣。","sortOrder":191},
  {"id":"s_work_nvlt_21_192","chapterId":"ch_work_nvlt_21","text":"《孝經》曰：士有爭友，則身不離於令名。","sortOrder":192},
  {"id":"s_work_nvlt_21_193","chapterId":"ch_work_nvlt_21","text":"《論語》曰：與朋友交，言而有信，雖曰未學，吾必謂之學矣。","sortOrder":193},
  {"id":"s_work_nvlt_21_194","chapterId":"ch_work_nvlt_21","text":"又曰：朋友數，斯疏矣。","sortOrder":194},
  {"id":"s_work_nvlt_21_195","chapterId":"ch_work_nvlt_21","text":"又曰：朋友切切偲偲，兄弟怡怡。","sortOrder":195},
  {"id":"s_work_nvlt_21_196","chapterId":"ch_work_nvlt_21","text":"又曰：原車馬，衣輕裘，與朋友共，敝之而無憾，［事具叙志篇。］","sortOrder":196},
  {"id":"s_work_nvlt_21_197","chapterId":"ch_work_nvlt_21","text":"又曰：益者三友，損者三友，友直，友谅，友多聞，益矣，友便僻，友善柔，友便佞，損矣。","sortOrder":197},
  {"id":"s_work_nvlt_21_198","chapterId":"ch_work_nvlt_21","text":"又曰：君子以文會友，以友辅仁。","sortOrder":198},
  {"id":"s_work_nvlt_21_199","chapterId":"ch_work_nvlt_21","text":"《家語》曰：行循而名不彰，友之罪也，故君子入則篤行，出則友賢。","sortOrder":199},
  {"id":"s_work_nvlt_21_200","chapterId":"ch_work_nvlt_21","text":"《莊子》曰：魚相造乎水，人相造乎道，故魚相忘於江湖，人相忘於道術。","sortOrder":200},
  {"id":"s_work_nvlt_21_201","chapterId":"ch_work_nvlt_21","text":"又曰：凡交近則必相靡以信。","sortOrder":201},
  {"id":"s_work_nvlt_21_202","chapterId":"ch_work_nvlt_21","text":"《孟子》曰：舜見帝，帝馆於貳室，迭為賓主，是天子友疋夫也。","sortOrder":202},
  {"id":"s_work_nvlt_21_203","chapterId":"ch_work_nvlt_21","text":"《列子》曰：管夷吾鮑叔牙，二人相友，管仲曰：吾與鮑叔贾，分财多自與，鮑叔不以我為貪，知吾有親也，吾嘗為鮑叔謀事，大窮困，鮑叔不以我為愚，知時有不利也，吾嘗三仕三見逐，鮑叔不以我為不肖，知不遭時也，知我者鮑叔，生我者父母。","sortOrder":203},
  {"id":"s_work_nvlt_21_204","chapterId":"ch_work_nvlt_21","text":"孔藂子曰：昔虢叔閎夭太顛散宜生南宮適五臣同寮比德，贊文武，及虢叔死，四人為服朋友之服。","sortOrder":204},
  {"id":"s_work_nvlt_21_205","chapterId":"ch_work_nvlt_21","text":"劉歆新議曰：夫交接者，人道之本始，紀綱之大要，名由之成，事由之立。","sortOrder":205},
  {"id":"s_work_nvlt_21_206","chapterId":"ch_work_nvlt_21","text":"又曰：交之於人也，猶唇齒之相濟。","sortOrder":206},
  {"id":"s_work_nvlt_21_207","chapterId":"ch_work_nvlt_21","text":"又曰：才非交不用，名非交不發，義非交不立。","sortOrder":207},
  {"id":"s_work_nvlt_21_208","chapterId":"ch_work_nvlt_21","text":"谯子曰：夫交之道，猶素之白也，染之以朱則赤，染之以藍則青。","sortOrder":208},
  {"id":"s_work_nvlt_21_209","chapterId":"ch_work_nvlt_21","text":"又曰：交得其人，千里同好，固於膠漆，堅於金石，貢公之於王吉，可謂推賢矣。","sortOrder":209},
  {"id":"s_work_nvlt_21_210","chapterId":"ch_work_nvlt_21","text":"《漢書》曰：翟公署門，一貴一賤，交情乃見，一死一生，乃知交情，一貧一富，乃知交態，［事具職官部廷尉篇。］","sortOrder":210},
  {"id":"s_work_nvlt_21_211","chapterId":"ch_work_nvlt_21","text":"贾［《太平御覽》四百零六作要。］覽曰：势利之交，難以經遠，士之相知，溫不增華，寒不改葉，貫四時而不衰，歷夷险而益固。","sortOrder":211},
  {"id":"s_work_nvlt_21_212","chapterId":"ch_work_nvlt_21","text":"謝承《後漢書》曰：張元伯范巨卿二人友，元伯卒，巨卿夢見元伯死，當葬，曰：卿，子未我忘，當奔葬，巨卿往赴之，［事具夢部。］《晉中興書》曰：郄超所交，皆一時秀美，雖寒門後進，亦拔而友之。","sortOrder":212},
  {"id":"s_work_nvlt_21_213","chapterId":"ch_work_nvlt_21","text":"竹林七賢傳曰：山涛與阮籍嵇康，皆一面契若金蘭，涛語妻曰：吾當年可為交者，唯此二人耳。","sortOrder":213},
  {"id":"s_work_nvlt_21_214","chapterId":"ch_work_nvlt_21","text":"世記［《太平御覽》四百零九作說。］曰：荀巨伯遠看友人疾，值胡賊攻郡，巨伯不忍去，賊既至，謂巨伯曰：大軍至，一郡併空，汝何男子，敢獨止此，巨伯曰：有友人疾，不忍委之，寧以我身代友人之命，賊知其賢，疾旋軍而還。","sortOrder":214},
  {"id":"s_work_nvlt_21_215","chapterId":"ch_work_nvlt_21","text":"【詩】魏陳王曹植離友詩曰：乡人有夏侯威者，少有成人之風，餘尚其為人，與之昵好，王師振旅，送餘於魏邦，心有眷然，為之陨涕，乃作離友之詩，其辭曰：王旅遊兮背故乡，彼君子兮篤人綱，媵予行兮歸朔方，馳原隰兮尋舊疆，車載奔兮馬繁驤，涉浮濟兮汎輕航，迄魏都兮息蘭房，展宴好兮惟樂康。","sortOrder":215},
  {"id":"s_work_nvlt_21_216","chapterId":"ch_work_nvlt_21","text":"晉郭璞赠溫峤詩曰：人亦有言，松竹有林，及爾臭味，異苔同岑，言以忘得，交以淡成，同匪伊和，惟我與生，爾神餘契，我懷子情，携手一豁，安知尘冥。","sortOrder":216},
  {"id":"s_work_nvlt_21_217","chapterId":"ch_work_nvlt_21","text":"齊謝朓赠友人詩曰：芳洲有杜若，可以赠佳期，望望忽超遠，何由見所思，我行未千里，山川以間之，離居方歲月，故人不在茲，清風動帘夜，孤月照窗時，安得同携手，酌酒賦新詩。","sortOrder":217},
  {"id":"s_work_nvlt_21_218","chapterId":"ch_work_nvlt_21","text":"梁陆倕赠京邑僚友詩曰：餘本水乡士，閉門江海隅，時逢道世泰，蹇足出高衢，江中寒事早，夜露傷秋草，心屬姑蘇台，目送邯鄲道，追惟畴昔時，朝府多歡暇，薄暮埃尘靜，飛蓋相追迓，李郭或同舟，潘夏時方駕，娱歡追美景，敷文永清夜，促膝豈異人，戚戚皆姻娅。","sortOrder":218},
  {"id":"s_work_nvlt_21_219","chapterId":"ch_work_nvlt_21","text":"【賦】梁丘遲思賢賦曰：豈顧問哉，相然信死，斯則結深念於撫翼，跂雄飛而俱起，知我於财利之間，何足多於鮑子，目击而道存，至味其如水，未見其人，吾聞其理矣，夫子長之讬意，甘執鞭於異世，在慈明之慕義，聊慚馭而追悅，况至德之可師，無兼裘以共弊，有樂安之任子，伟群才而稱杰，備百行之高致，該九流之洪藝，谅可雜而非染，跡每同而常別，牆易入而難窥，關無鍵而有閉，思若神而泉涌，翰如雲而積袂，沉潛於懷抱之間，萧散於天人之际，日下愧其未双，關西慚於上哲，紛吾既有此固陋，荷君子之渥惠，尘非府而分深，葉未移而好結，尋宿草之宴處，歷三紀於茲日，性有同於杞梓，心獲变於丹漆，文何屬而不辯，理何疑而匪质，問不休而鍾扣，答無窮而座謐。","sortOrder":219},
  {"id":"s_work_nvlt_21_220","chapterId":"ch_work_nvlt_21","text":"【贊】晉夏侯湛管仲像贊曰：堂堂管生，忘存興仁，仁道在己，唯患無身，苞辱遠害，思濟彝倫，心寄鮑子，動成生民。","sortOrder":220},
  {"id":"s_work_nvlt_21_221","chapterId":"ch_work_nvlt_21","text":"又鮑叔像贊曰：鮑子愔愔，式昭德音，綢缪敬叔，二人同心，厥芳猶蘭，其堅如金，遙遙景跡，君子攸钦。","sortOrder":221},
  {"id":"s_work_nvlt_21_222","chapterId":"ch_work_nvlt_21","text":"【箴】宋周秖執友箴曰：四辅扬辉，伐木幽林，撫乔鸞飛，爰逮姬衰，俗遂凋成，交緣利昵，用因伪情，穀風興哀，繁霜夏零，道之未盡，弘焉由人，自室有回，過門則親，微言綿邈，清談輟响，金雖能照，尘積翳朗，西河感離，口悟投杖，慊慊文侯，友賢好學，英英燕昭，禮郭致樂，推誠歲寒，功摽松竹，落落高札，遼遼莊惠，解帶一愚，道映萬世，人亦有言，貴則易交，利重太山，道輕鸿毛，久而致敬，見之晏平，霜雪既至，劲柏冬青。","sortOrder":222},
  {"id":"s_work_nvlt_21_223","chapterId":"ch_work_nvlt_21","text":"◇絕交","sortOrder":223},
  {"id":"s_work_nvlt_21_224","chapterId":"ch_work_nvlt_21","text":"《毛詩》曰：天下俗薄，朋友道絕焉，習習穀風，維風及雨，將恐將懼，惟予與汝，將安將樂，汝轉弃予。","sortOrder":224},
  {"id":"s_work_nvlt_21_225","chapterId":"ch_work_nvlt_21","text":"又曰：伐木废，則朋友缺矣。","sortOrder":225},
  {"id":"s_work_nvlt_21_226","chapterId":"ch_work_nvlt_21","text":"《漢書》曰：張耳陳餘，始居約時，相然信死，豈顧問哉，及據國爭權，卒相滅亡，势利之交，古人羞之。","sortOrder":226},
  {"id":"s_work_nvlt_21_227","chapterId":"ch_work_nvlt_21","text":"又曰：萧育少與朱博為友，著聞當世，故長安語曰：萧朱結綬，王貢彈冠，始育公卿子顯，博尚為杜陵亭長，為育進舉，遂至丞相，與博有隙。","sortOrder":227},
  {"id":"s_work_nvlt_21_228","chapterId":"ch_work_nvlt_21","text":"世記曰：王恭王都［本條見世說識鑒篇，雲王恭隨父在會稽，王大(忱)自都來拜墓雲雲，此有脱訛。］二人素相友善，恭父曰：恐非子之，［世說之下有友字。］後遂不終。","sortOrder":228},
  {"id":"s_work_nvlt_21_229","chapterId":"ch_work_nvlt_21","text":"【書】魏應玚報庞惠恭書曰：夫萧艾之歌，發於信宿，子衿之思，起不嗣音，况實三載，能不有懷，雖萱草树背，皋蘇在侧，悒憤不逞，秖以增毒，朝隱之官，賓不往來，乔木之下，曠無休息，抱勞而已，足下剖符南面，振威千里，行人子羽，朝夕相繼，曾不枉咫尺之路，問蓬室之舊，過意賜書，辭不半紙，慰藉輕於繒縞，譏望重於丘山，是角弓之詩，所以為刺也，植鷺羽於宛丘，騁駿足於株林，發明月之辉光，照妖人之窈窕，斯亦所以眩耳目之视聽，亡聲命於知友者也。","sortOrder":229},
  {"id":"s_work_nvlt_21_230","chapterId":"ch_work_nvlt_21","text":"晉嵇康與山涛絕交書曰：柳下惠東方朔，達人也，安乎卑位，吾豈敢短之哉，仲尼兼愛，不羞執鞭，子文無欲卿相，而三登令尹，且延陵高子臧之風，長卿慕相如之節，志氣所讬，亦不可奪也，吾每讀尚子平台孝威傳，慨然慕之，想其為人。又縱逸來久，情意傲散，簡與禮相背，嬾與慢相成，而為儕類見宽，不攻其過，故使榮進之心日頹，任實之情轉篤，此由禽鹿，少見馴育，則服從教製，長而見羁，則狂顧頓纓，赴蹈湯火，雖飾以金鑣，饗以嘉肴，愈思長林，而志在丰草也。又人倫有禮，朝廷有法，自惟至熟，有必不堪者七，甚不可者二，臥喜晚起，而當關呼之不置，一不堪也，抱琴行吟，弋釣草野，而吏卒守之，不得妄動，二不堪也，危坐一時，痺不得搖，性复多蝨，把搔無已，而當裹以章服，揖拜上官，三不堪也，素不便書，不喜作書，而人間多事，堆案盈幾，不相酬答，則犯教傷義，欲自勉強，則不能及，四不堪也，不喜弔丧，而人道以此為重，己為未見恕者所怨，至欲見中傷者，雖懼然自责，然不可化，終不能獲無咎無譽如此，五不堪也，不喜俗人，而當與之共事，或賓客盈坐，鳴聲聒耳，嚣尘臭處，千变百技，在人目前，六不堪也，心不耐煩，而官事鞅掌，機務纏其心，世故繁其慮，七不堪也。又每非湯武而薄周孔，人間不止此事，會顯世教所不容，此甚不可一也，刚腸疾惡，輕肆直言，遇事便發，此甚不可二也，以促中心［《文選》四十三心上有小字。］之性，統此九患，不有外難，當有內病，寧可久處人間邪。又聞道士遺言，餌術黃精，令人益寿，意甚信之，遊山泽，觀魚鳥，心甚樂之，一行作吏，此事便废，足下見直木必不可以為輪，曲者必不可以為桷，蓋不欲以枉其天才，令得其所也，不可自見好章甫，強越人以文冕也，今但原守陋巷，教子孫，時時與親舊叙闊，陳說平生，濁酒一柸，彈琴一曲，志原畢矣。","sortOrder":230},
  {"id":"s_work_nvlt_21_231","chapterId":"ch_work_nvlt_21","text":"【論】後漢朱穆絕交論曰：世之務交遊也，甚矣，不敦於業，不忌於君，犯祀以追之，背公以從之，事替義退，公輕私重。","sortOrder":231},
  {"id":"s_work_nvlt_21_232","chapterId":"ch_work_nvlt_21","text":"魏徐幹中論曰：大夫州郡牧守，王事不恤，賓客為務，冠蓋闐門，服膺盈道，殷殷沄沄，俾夜作晝，星言夙駕，送往迎來，停傳常滿，吏卒侍門，炬火夜行，閽寺不關，文書委於官曹，系囚積於囹圄，為師無以教訓，弟子亦不受業，或身没他邦而不歸，父母懷豭獨之思，室人抱東山之哀，嗟乎，王教之败，乃至於此，林宗之時所謂交遊者也，輕位不仕者，則有巢許之高，废職待客者，則有仲尼之稱，委親遠學者，則有優遊之美，是以各眩其名，而忘天下之亂也。","sortOrder":232},
  {"id":"s_work_nvlt_21_233","chapterId":"ch_work_nvlt_21","text":"梁劉孝標廣絕交論曰：若夫組織仁義，琢磨道德，驩其愉樂，恤其凌夷，寄通靈台之下，遺跡江湖之上，風雨急而不輟其音，霜雪零而不渝其色，斯則賢達之素交，歷萬古而一遇，逮叔世民訛，徂诈飆起，溪穀不能逾其险，鬼神無以究其变，競羽毛之輕，趍錐刀之末，於是素交盡，利交興，天下蚩蚩，鳥驚雷駭，然利交同源，派流則異，较言其略，有五術焉，若其寵均董石，權壓梁窦，彫刻百工，爐錘萬物，九域耸其風尘，四海叠其燻灼，靡不望影星奔，藉响川骛，約同要離焚妻子，誓殉荆卿湛七［原作亡，據文選五十五改。］族，是［原脱，據冯校本補。］曰势交，其流一也，富均陶白，赀巨程羅，山擅銅陵，家藏金穴，則有窮巷之賓，繩枢之士，冀宵燭之末光，邀润屋之微泽，衔恩遇，進款誠，援青松以示心，指白水而旌信，是曰賄交，其流二也，陆大夫宴喜西都，郭有道人倫東國，公卿貴其藉甚，搢紳羨其登仙，加以顩颐蹙頞，涕唾流沫，騁黃馬之剧談，縱碧雞之雄辨，於是有弱冠王孫，綺紈公子，道不掛於通人，聲未遒於雲閣，攀其鱗翼，丐其餘論，附駔骥之髦端，軼歸鸿於碣石，是曰談交，其流三也，陽舒陰惨，生民大情，忧合歡離，品物恒性，故魚以泉涸而煦沫，鳥因將死而鳴哀，同病相怜，缀河上之悲曲，恐懼寘懷，昭穀風之盛典，斯則斷金由於湫隘，刎頸起於苫蓋，是以伍員濯溉於宰嚭，張王撫翼於陳相，是曰窮交，其流四也，馳骛之俗，浇薄之倫，無不操權衡，秉纖纊，衡所以量其輕重，纊所以屬其鼻息，若衡不能舉，纊不能飛，雖顏冉龍翰鳳雏，曾史蘭薰雪白，视若遊尘，遇如斷梗，莫肯費其半菽，罕有落其一毛，若衡重锱銖，纊微彯撇，雖共工之蒐慝，驩兜之掩義，南荆之跋扈，東陵之巨猾，皆為匍匐委蛇，折支舐痔，金膏翠羽將其意，脂韦便辟导其誠，謀而後動，芒毫寡忒，是曰量交，其流五也，凡斯五交，義均贾鬻，故桓談譬之於闤阓，林回喻之於甘醴，近世有樂安任昉，海內髦杰，早綰銀黃，夙昭民譽，遒文麗藻，方駕曹王，英特俊邁，聯橫許郭，類田文之愛士，同鄭莊之好賢，見一善則盱衡扼腕，遇一才則扬眉抵掌，至顧眄增其倍价，剪拂使其長鳴。彯組雲台者肩磨，趍走丹墀者叠跡，莫不締恩狎，結綢缪，想莊惠之清尘，庶羊左之徽烈，及瞑目東越，歸骸洛浦，繐帳猶懸，門罕渍酒之彦，墳未宿草，野絕動輪之賓，藐爾諸孤，朝不謀夕，流離大海之南，寄命瘴癘之地，自昔把臂之英，金蘭之友，曾無羊舌下泣之仁，寧慕郈成分宅之德，呜呼，世路崄巇，一至於此，太行孟門，豈雲嶄絕，是以耿介之士，疾其若斯，裂裳裹足，弃之長骛，獨立高山之顶，驩與麋鹿同群，曒々然絕其雰濁，誠恥之也，誠畏之也。","sortOrder":233},
  {"id":"s_work_nvlt_21_234","chapterId":"ch_work_nvlt_21","text":"《藝文類聚》　唐·欧陽詢","sortOrder":234},
  {"id":"s_work_nvlt_22_1","chapterId":"ch_work_nvlt_22","text":"卷二十二人部六","sortOrder":1},
  {"id":"s_work_nvlt_22_2","chapterId":"ch_work_nvlt_22","text":"○公平品藻质文","sortOrder":2},
  {"id":"s_work_nvlt_22_3","chapterId":"ch_work_nvlt_22","text":"◇公平","sortOrder":3},
  {"id":"s_work_nvlt_22_4","chapterId":"ch_work_nvlt_22","text":"《尚書》曰：無偏無党，王道荡荡，無党無偏，王道平平。","sortOrder":4},
  {"id":"s_work_nvlt_22_5","chapterId":"ch_work_nvlt_22","text":"《左傳》曰：贾季奔狄，宣子使臾骈送其帑，夷之蒐，贾季戮臾骈，臾骈之人欲盡殺贾氏以報焉，臾骈曰：不可，吾聞前志有之曰：敵惠敵怨，不在後嗣，忠之道也，夫子禮於贾季，我以其寵報私怨，無乃不可乎。","sortOrder":5},
  {"id":"s_work_nvlt_22_6","chapterId":"ch_work_nvlt_22","text":"又曰：祁奚請老，晉侯問嗣焉，稱解狐，其讎也，將立之而卒。又問焉，對曰：午也可，於是羊舌職死矣，晉侯曰：孰可以代之，對曰：赤也可，於是使祁午為中軍尉，羊舌赤佐之，君子謂祁奚能舉善矣，稱其讎，不為諂，立其子，不為比，舉其偏，不為党。","sortOrder":6},
  {"id":"s_work_nvlt_22_7","chapterId":"ch_work_nvlt_22","text":"《禮記》曰：昔衛獻公出奔，反國，及郊，將頒邑於從者而後入，柳莊曰：如皆守社稷，則孰執羁靮而從，如皆從，則孰守社稷，君反國而有私也，無乃不可乎，於是弗果頒。","sortOrder":7},
  {"id":"s_work_nvlt_22_8","chapterId":"ch_work_nvlt_22","text":"又曰：天無私覆，地無私載，日月無私照，奉三無私，以勞天下。","sortOrder":8},
  {"id":"s_work_nvlt_22_9","chapterId":"ch_work_nvlt_22","text":"《韓子》曰：解狐荐其讎以為相，其讎往拜謝，解狐引弓，迎而射之。","sortOrder":9},
  {"id":"s_work_nvlt_22_10","chapterId":"ch_work_nvlt_22","text":"又曰：解狐與荆伯柳為怨，趙簡王問於解狐曰：孰可以為上党守，對曰：荆伯柳可，趙簡王曰：非子之讎乎，對曰：臣聞忠臣舉賢，不避仇讎。","sortOrder":10},
  {"id":"s_work_nvlt_22_11","chapterId":"ch_work_nvlt_22","text":"《說苑》曰：晉文公問於舅犯，誰可使為西河守者，對曰：虛子羔，曰：子羔非汝之仇欤，曰：君問為守者，非問臣之仇也，子羔見舅犯謝之曰：君幸赦臣之過，荐之於君，得為西河守，舅犯曰：荐子者公也，吾不以私事害公義，子其去矣，顧，吾射子矣。","sortOrder":11},
  {"id":"s_work_nvlt_22_12","chapterId":"ch_work_nvlt_22","text":"《家語》曰：澹台滅明，為人公正無私。","sortOrder":12},
  {"id":"s_work_nvlt_22_13","chapterId":"ch_work_nvlt_22","text":"《慎子》曰：夫投鉤分财，投策分馬，非以鉤策為均，使得美者不知所以德，得惡者不知所以怨，此所以塞怨望也，故蓍龟所以立公言也，權衡所以立公正也，書契所以立公信也，法製禮籍，所以立公義也，凡立公所以弃私也。","sortOrder":13},
  {"id":"s_work_nvlt_22_14","chapterId":"ch_work_nvlt_22","text":"《呂氏春秋》曰：荆人有遺弓者，弗肯索，曰：荆人遺之，荆人得之。又何求焉，孔子聞之曰：去其荆而可矣，老聃聞之曰：去其人而可矣，故老聃則至公得矣。","sortOrder":14},
  {"id":"s_work_nvlt_22_15","chapterId":"ch_work_nvlt_22","text":"又曰：昔先聖王之治天下，必先公，公則天下平矣，有得天下者眾矣，其得之必以公，其失之必以偏。","sortOrder":15},
  {"id":"s_work_nvlt_22_16","chapterId":"ch_work_nvlt_22","text":"《史記》曰：邑中人民俱出獵，任安常分麋鹿雉兔，眾人皆喜，曰：任少卿分則平。","sortOrder":16},
  {"id":"s_work_nvlt_22_17","chapterId":"ch_work_nvlt_22","text":"又曰：陳平為社宰，分肉甚均，里父老曰：善陳孺子之為宰，平曰：嗟乎，使平得宰天下，亦如肉矣。","sortOrder":17},
  {"id":"s_work_nvlt_22_18","chapterId":"ch_work_nvlt_22","text":"《韓詩外傳》曰：楚白公之難，有社之善者，辭其母，將死君難，其母曰：弃母死君，可乎，社之善曰：聞事君者，內其祿而外其身，今之所養母者，君之祿也，請往死之，比至朝，三废車中，其仆曰：子懼，何不反也，社之善曰：懼，吾私也，死君，吾公也，吾聞君子不以私害公，遂死之。","sortOrder":18},
  {"id":"s_work_nvlt_22_19","chapterId":"ch_work_nvlt_22","text":"《漢書》曰：萧何不與曹參相能，及何病，惠帝自臨视，因問曰：君即百歲後，誰可代君，對曰：知臣莫如主，帝曰：曹參何如，何頓首曰：帝得之矣，臣死不恨矣。","sortOrder":19},
  {"id":"s_work_nvlt_22_20","chapterId":"ch_work_nvlt_22","text":"又曰：義縱少時，與張次翁俱攻剽為群盜，縱姊以医幸王太後，太後問，子有兄弟欲為官者乎，姊曰：有弟無行，不可，太後乃告上，拜縱為中郎。","sortOrder":20},
  {"id":"s_work_nvlt_22_21","chapterId":"ch_work_nvlt_22","text":"又曰：朱邑惇篤於故舊，然性公正，不可交以私，天子器之。","sortOrder":21},
  {"id":"s_work_nvlt_22_22","chapterId":"ch_work_nvlt_22","text":"《東觀漢記》曰：耿嵩履清高之節，龀童介然特立，不隨於俗，乡党士大夫莫不敬異之，王莽败，賊盜起，宗族在草中，穀食貴，人民相食，宗家數百，升合分糧，時嵩年十二三，宗人長少，鹹共推令主廪給，莫不稱平。","sortOrder":22},
  {"id":"s_work_nvlt_22_23","chapterId":"ch_work_nvlt_22","text":"魏武令曰：今寿春漢中長安，先欲使一兒各往詣領之，欲擇慈孝不违，吾今兒亦未知用誰也，雖兒小時見愛，而長大能善，必用之，吾非有二言也，不但不私臣吏，兒子亦不欲有所私。","sortOrder":23},
  {"id":"s_work_nvlt_22_24","chapterId":"ch_work_nvlt_22","text":"周生烈曰：天下所以平者，政平也，政所以平者，人平也，人所以平者，心平也，《燕書》曰：梁琛使秦，琛從兄弈，先在秦為尚書郎，會罢，秦主欲令琛止弈舍，琛語有司曰：昔諸葛亮兄弟各處三國，及其聘集，公朝相見，退無私面，君子之志，餘敢忘乎，竟不止，弈數就邸舍，因問東國起居，琛曰：今二方鼎據，兄弟併蒙附寵，論心各有所在，今欲以東國事語君，恐非西國之所欲聞，何以見問。","sortOrder":24},
  {"id":"s_work_nvlt_22_25","chapterId":"ch_work_nvlt_22","text":"【論】魏曹羲至公論曰：夫世人所謂掩惡扬善者，君子之大義，保明同好，朋友之至交，斯言之作，蓋闾阎之日談，所以救愛憎之相謗，崇居厚之大分耳，非篤正文至理，折中之公議也，世士不斷其數，而系其言，故善惡不分，以覆過為弘，朋友忽義，以雷同為美，善惡不分，亂實由之，朋友雷同，败必從焉，談論以當實為清，不以過難為貴，相知者以等分為交，不以雷同為固，是以達者，存其義，不察於交，識其心，不求於言，且在私論，猶行之有節，明處公議，則無所固之矣，凡智者之處世，鹹欲興化致治者也，興化致治，不崇公抑割，情以順理，厲清議以督俗，明是非以宣教者，吾未見其功也，清議非臧否不顯，是非非賞罰不明，故臧否不可以遠實，賞罰不可以失中，若乃背清議，违是非，雖尧不能一日以治，審臧否，詳賞罰，故中主可以萬世安，是以君子知私情之難統，至公之易行，故季友鸩兄而不疑，叔向戮弟而不悔，斯二士者，皆前世之通士，晉魯之忠臣也，亦豈無慈愛骨肉之心，愍恤同生之仁哉，夫至公者，天之經也，地之義也，理之要也，人之用也，昔鯀者，親禹之父也，舜則殛鯀而興禹，禹知舜之殛其父無私，故受命而不辭，舜明禹知己之至公，故用之而無疑，無私者，雖父黜而子不言，况用之於他哉。","sortOrder":25},
  {"id":"s_work_nvlt_22_26","chapterId":"ch_work_nvlt_22","text":"晉嵇康釋私論曰：不知冒陰之可以無景，而患景之不匿，不知無惜［晉書四十九嵇康傳作措，下同。］之可以無患，而恨惜之不巧，豈不哀哉，未有抱伪懷奸，而身立清世，匿非藏情，而信著明君者也，是以君子既有其质。又睹其鑒，貴夫亮達，希而存之，惡夫務吝，弃而遠之，言無苟讳，而行無苟德，不以愛之而苟善，不以惡之而苟非，心無所矜，而情無所系，體清神正，而是非允當，忠感明於天子，而信篤乎萬民，寄胸懷於八荒，垂坦荡以永日，斯非賢人君子高行之美異者乎。","sortOrder":26},
  {"id":"s_work_nvlt_22_27","chapterId":"ch_work_nvlt_22","text":"◇品藻","sortOrder":27},
  {"id":"s_work_nvlt_22_28","chapterId":"ch_work_nvlt_22","text":"《家語》曰：子貢曰：陳靈公君臣宣淫於朝，泄冶諫而煞之，是與比幹同也，可謂仁乎，子曰：比幹於紂，親則叔父，官則少師，忠款之心，在於宗廟而已，固以必死爭之，冀身死之後，紂當悔悟，本其情志，在乎仁者也，泄冶位下大夫，無骨肉之親，懷寵不去，以區區之身，欲止一國之淫昏，死而益亡，［《太平御覽》四百四十五作無益。］可謂懷矣，詩曰：民之多僻，無自立辟，其泄冶之謂也。","sortOrder":28},
  {"id":"s_work_nvlt_22_29","chapterId":"ch_work_nvlt_22","text":"又曰：子路曰：澹台子羽，有君子之容，而行不勝其貌，宰我有文雅之辭，而智不充其辯，孔子曰：相馬以舆，相士以居，弗可废已，以容取人，則失之子羽，以言取人，則失之宰予。","sortOrder":29},
  {"id":"s_work_nvlt_22_30","chapterId":"ch_work_nvlt_22","text":"又曰：子夏三年丧畢，見於孔子，與之琴，使之絃，侃侃而樂，作而曰：先王製禮，不敢不及，子曰：君子也，闵子三年丧畢，見於孔子，與之琴，使之絃，切切而悲，作而曰：先王製禮，不敢過焉，子曰：君子也，子貢曰：二者殊情，而俱曰君子，賜也惑之，敢問，孔子曰：闵子哀未盡，能斷之以禮，子夏哀已盡，能引之及禮，雖鈞謂之君子，不亦可乎。","sortOrder":30},
  {"id":"s_work_nvlt_22_31","chapterId":"ch_work_nvlt_22","text":"孔藂子曰：魏安釐王問子從［《太平御覽》四百四十七作順，此避梁讳而未回改，後同。］曰：馬回梗梗亮直，有大丈夫之節，吾欲以為相，可乎，答曰：亮直之節，臣未明也，王曰：何故，答曰：長目而豕视者，必體方而心圓，每以其法相人，千百不失一，臣見回，非不伟其體幹也，然甚疑其目，王卒用之，三月，果以諂言得罪。","sortOrder":31},
  {"id":"s_work_nvlt_22_32","chapterId":"ch_work_nvlt_22","text":"《漢書》曰：高帝置酒洛陽南宮，上曰：吾所以有天下者何，項氏之所以失天下者何，王陵對曰：陛下慢而侮人，項羽仁而敬人，然陛下使人攻城略地，所降者因以與之，與天下同其利也，項羽妒賢嫉能，有功者害之，賢者疑之，戰勝而不與人功，得地而不與人利，此其所以失天下也，上曰：公知其一，未知其二，夫運筹帷幄之中，决勝千里之外，吾不如子房，镇國家，撫百姓，給餉饋，不絕糧道，吾不如萧何，連百萬之眾，戰必勝，攻必取，吾不如韓信，此三者皆人杰也，吾能用之，此吾所以有天下也，項羽唯有一范增，不能用，此其所以為我擒也，群臣悅服。","sortOrder":32},
  {"id":"s_work_nvlt_22_33","chapterId":"ch_work_nvlt_22","text":"袁山松《漢書》曰：王允，字子師，世仕州郡，為冠蓋，同郡郭林宗，見而奇之曰：王生一日千里，王佐才也，遂與之友善，允仕至司徒。","sortOrder":33},
  {"id":"s_work_nvlt_22_34","chapterId":"ch_work_nvlt_22","text":"青州先賢傳曰：京師號曰：陳仲舉，昂昂如千里骥，周孟玉，瀏瀏如松下風。","sortOrder":34},
  {"id":"s_work_nvlt_22_35","chapterId":"ch_work_nvlt_22","text":"范晔《後漢書》曰：許劭嘗到潁川，多長者之遊，唯不詣陳寔。又陳蕃丧妻還葬，乡人畢至，而劭獨不往，或問其故，劭曰：太丘道廣，廣則難周，仲舉性峻，峻則少通，故不造也，其多所裁量若此，曹操微時，嘗卑辭厚禮，求為已助，劭鄙其人，而不肯對，操乃伺隙胁劭，劭不得已曰：君清平之奸賊，亂世之英雄，操大悅而去，初劭與從兄靖，俱有高名，好共覈論乡党人物，每月辄更其品題，故汝南俗有月旦評焉。","sortOrder":35},
  {"id":"s_work_nvlt_22_36","chapterId":"ch_work_nvlt_22","text":"郭泰別傳曰：泰字林宗，少遊汝南，先過袁阆，不宿而退，遂往從黃憲，累日方還，或問林宗，林宗曰：奉高之器，譬諸汎濫，雖清而易挹，叔度汪汪君子，若千萬頃陂，澄之不清，混之不濁，不可量也。","sortOrder":36},
  {"id":"s_work_nvlt_22_37","chapterId":"ch_work_nvlt_22","text":"《三辅决錄》曰：弭生字仲叔，其父賊，故張伯英與李幼才書曰：弭仲叔高德美名，命世之才也，非弭氏小族所當有，新丰瘠土所當出也。","sortOrder":37},
  {"id":"s_work_nvlt_22_38","chapterId":"ch_work_nvlt_22","text":"《魏志》曰：盧钦著書，稱徐邈曰：或問钦，徐公當武帝之時，人以為通人，自在涼州，及還京都，人以為介，何也，钦答曰：往者毛孝先崔季珪用事，貴清素之志，徐公不改其常，故人以為通，比來天下奢靡，轉相放效，而徐公雅尚自若，不與俗同，故前日之通，乃今日之介也。","sortOrder":38},
  {"id":"s_work_nvlt_22_39","chapterId":"ch_work_nvlt_22","text":"《典略》曰：祢衡，建安初，自荆州北遊許都，書一刺懷之，漫滅而無所遇，或問之曰：何不從陳長文司馬伯達乎，衡曰：卿欲使我從屠沽兒辈耶。又問曰：當今复誰可者，衡曰：大兒孔文舉，小兒楊德祖。又問荀令君趙荡寇，皆足蓋世乎，衡見荀有容儀，趙有腹，乃答曰：文若可借面弔丧，稚長可使監厨請客，其意以為荀但有濬，趙健啖肉也。","sortOrder":39},
  {"id":"s_work_nvlt_22_40","chapterId":"ch_work_nvlt_22","text":"又曰：趙戩遭三辅亂，客於荆州，荆州牧劉表，以為賓客，是時祢衡來遊京師，詆訾朝士，謂無直事，及南見戩，叹之曰：所謂劍則幹將莫耶，木則椅桐梓漆，人則顏冉仲弓也。","sortOrder":40},
  {"id":"s_work_nvlt_22_41","chapterId":"ch_work_nvlt_22","text":"姚信士緯曰：周勃之勋，不如霍光，此前史所載，较然可見，而以勃功大於光，意竊不安，何者，勃本高帝大臣，官尊势顯，眾所歸向，居太尉位，擁兵百萬，既有陳平王陵之力。又有朱虛諸王之援，郦其遊說，以譎諸呂，因眾之心，易以濟事，若霍光者，以仓卒之际，受寄讬之任，辅弼幼主，天下晏然，遇燕王上官之亂，誅除凶逆，以靖王室，废昌邑，立宣帝，任漢家之重，隆中興之祚，參贊伊周，為漢賢相，推验事效，優劣明矣。","sortOrder":41},
  {"id":"s_work_nvlt_22_42","chapterId":"ch_work_nvlt_22","text":"袁子曰：或雲，故少府楊阜，豈非忠臣哉，答曰：然可謂直士，忠則吾不知也，夫為人臣，見人主失道，指斥其非，而播扬其惡，可謂直士，未為忠臣，故司馬陳群則不然，其談論終日，未嘗言人主之非，書數十上，而外人不知，君子謂陳群於是乎長者。","sortOrder":42},
  {"id":"s_work_nvlt_22_43","chapterId":"ch_work_nvlt_22","text":"《郭子》曰：庾道季雲，蔺相如雖千載死人，懍懍恒如有生氣，曹蜍李志雖見在，厭厭如在九泉下。","sortOrder":43},
  {"id":"s_work_nvlt_22_44","chapterId":"ch_work_nvlt_22","text":"《世說》曰：王濬冲裴叔則二人，總角詣鍾士季，須臾去，後客問二童何如，鍾曰：裴楷清通，王戎簡要，後二十年，此二賢當為吏部尚書，冀爾時天下無复滯才，［事具職官部吏部尚書篇。］","sortOrder":44},
  {"id":"s_work_nvlt_22_45","chapterId":"ch_work_nvlt_22","text":"又曰：嵇中散語趙景真，卿瞳子白黑分明，有白起風，恨量小狹，趙答曰：尺表能審璇衡之度，寸管能测往复之晷，何必在大，但問識何如耳。","sortOrder":45},
  {"id":"s_work_nvlt_22_46","chapterId":"ch_work_nvlt_22","text":"又曰：諸葛瑾，其弟亮，及從弟誕，併有盛名，各在一國，於時以為蜀得其龍，吳得其虎，魏得其狗。","sortOrder":46},
  {"id":"s_work_nvlt_22_47","chapterId":"ch_work_nvlt_22","text":"又曰：王大將軍稱王夷甫，處眾人之中，如珠玉在瓦石間。","sortOrder":47},
  {"id":"s_work_nvlt_22_48","chapterId":"ch_work_nvlt_22","text":"又曰：世中稱庾文康為丰年玉，庾稚恭為荒年穀。","sortOrder":48},
  {"id":"s_work_nvlt_22_49","chapterId":"ch_work_nvlt_22","text":"又曰：魏明帝世，使後弟毛曾，與夏侯太初共坐，時人謂蒹葭倚玉树，時目夏侯太初，朗如日月入懷。","sortOrder":49},
  {"id":"s_work_nvlt_22_50","chapterId":"ch_work_nvlt_22","text":"【書】晉徐藻妻陳氏與妹劉氏書，伏見伟方所作先君诔，其述詠勋德，則仁風靡墜，其言情訴哀，則孝心以叙，自非挺生之才，孰能克隆聿脩若斯者乎，執詠反覆，觸言流淚，感賴交集，悲慰併至，元方伟方，併年少而有盛才，文辭富艳，冠於此世，竊不自量，有疑一言，略陳所懷，庶備起予，先君既體弘仁義。又動則聖檢，奉视極孝，事君盡忠，行己也恭，養民也惠，可謂立德立功，示民軌儀者也，但道長祚短，時乏識真，榮位未登，高志不遂，本不標方外跡也，老莊者，絕聖弃智，浑齊萬物，等貴賤，忘哀樂，非經典所貴，非名教所取，何必辄引以為喻耶，可共詳之。","sortOrder":50},
  {"id":"s_work_nvlt_22_51","chapterId":"ch_work_nvlt_22","text":"【論】後漢孔融汝潁優劣論曰：融以為汝南士勝潁川士，陳長文難，融答之曰：汝南戴子高，親止千乘萬騎，與光武皇帝共於道中，潁川士雖抗節，未有頡颃天子者也，汝南許子伯，與其友人，共說世俗將坏，因夜舉聲號哭，潁川雖忧時，未有能哭世者也，汝南府許掾，教太守邓晨，圖开稻陂數萬頃，累世獲其功，夜有火光之瑞，韓元長雖好地理，未有成功見效，如許掾者也，汝南張元伯，身死之後，見夢范巨卿，潁川士雖有奇異，未有能神而靈者也，汝南應世叔，讀書五行俱下，潁川士雖多聰明，未有能離娄併照者也，汝南李洪，為太尉掾，弟煞人當死，洪自劾詣閤，乞代弟命，便飲酖而死，弟用得全，潁川雖尚節義，未有能煞身成仁如洪者也，汝南翟子威，為東郡太守，始舉義兵，以讨王莽，潁川士雖疾惡，未有能破家為國者也，汝南袁公著，為甲科郎，上書欲治梁冀，潁川士雖慕忠谠，未有能投命直言者也。","sortOrder":51},
  {"id":"s_work_nvlt_22_52","chapterId":"ch_work_nvlt_22","text":"魏夏侯玄樂毅論曰：夫求古賢之意，宜以大者遠者先之，必迂回而難通，然後已焉可也，觀樂生報燕惠王之書，其殆庶乎知機，合道以終始者與，其喻昭王曰：伊尹放太甲而不疑，太甲受放而不怨，是以天下為心者也，夫欲極道德之至量，務以天下為心者，必致其主於盛隆，合其趣於先王，樂生之志，豈其局跡當時，止於兼併而已哉，舉齊之事，所以運其機而動四海也，围城而害不加於百姓，此仁心著於遐邇矣，舉國不謀其功，除暴不以威力，此至德令於天下也，邁至德以率列國，則幾於湯武之事矣，樂生方恢大綱，以縱二城，收民明信，以待其弊，將使即墨莒人，顧仇其上，原釋幹戈，賴我猶親，善守之智，無所施之，然求仁得仁，即墨大夫之義也，任窮則從，微子適周之道也，开弥廣之路，以待田单之徒，長容善之風，以申齊之志，我泽如春，下應如草，道光宇宙，智者宅心，然則鄰國傾慕，四海延頸，思戴燕主，仰望風聲，二城必從，則王業隆矣，雖淹留於兩邑，乃所以致速於天下也，不幸之变，势所不圖，败於垂成，時運固然，樂生豈不知拔二城之速了哉，顧城拔而業乖也，豈不慮不速之致变哉，顧業乖與变同也，由是觀之，樂生之不屠二城，其亦未可量也。","sortOrder":52},
  {"id":"s_work_nvlt_22_53","chapterId":"ch_work_nvlt_22","text":"晉張辅名士優劣論曰：世人見魏武皇帝處有中土，莫不謂勝劉玄德也，餘以玄德為勝，夫拨亂之主，先以能收相獲將為本，一身善戰，不足恃也，世人以玄德為呂布所袭，為武帝所走，舉軍東下，而為陆遜所覆，雖曰為呂布所袭，未若武帝為徐榮所败，失馬被創之危也，玄德還據徐州，形势未合，在荆州，景叔父子不能用其計，舉州降魏，手下步騎，不滿數千，為武帝大眾所走，未若武帝為呂布北騎所禽，突火之急也，為陆遜所覆，未若武帝為張繡所困，挺身逃遁，以丧二子也，然其忌克，安忍無親，董公仁贾文和，恒以佯愚自免，荀文若楊德祖之徒，多見賊害，行兵三十餘年，無不親征，功臣謀士，曾無列土之封，仁愛不加親戚，惠泽不流百姓，豈若玄德威而有思，勇而有義，宽弘而大略乎，諸葛孔明，達治知变，殆王佐之才，玄德無強盛之势，而令委质，張飛關羽，皆人杰也，服而使之，夫明闇不相為用，能否不相為使，武帝雖處安強，不為之用也，况在危急之間，势弱之地乎，若令玄德據有中州，將與周室比隆，豈徒三杰而已哉。","sortOrder":53},
  {"id":"s_work_nvlt_22_54","chapterId":"ch_work_nvlt_22","text":"又曰：世人論司馬遷班固，多以固為勝，餘以為失，遷叙三千年事，五十萬言，固叙二百年事，八十萬言，固煩省不敵，不如一也，良史述事，善足以奖勸，惡足以鑒誡，人道之常，中流小事，無取皆書，不如二也，毀败晁错，傷忠臣之道，不如三也，遷既造創，固又因循，難易益不同矣。又遷為蘇秦張儀范睢蔡泽作傳，逞詞流離，亦足以明其大才，此真所以為良史也。","sortOrder":54},
  {"id":"s_work_nvlt_22_55","chapterId":"ch_work_nvlt_22","text":"又曰：樂毅諸葛孔明之優劣，互以毅相弱燕，合五國之兵，以破強齊，雪君王之恥，围城而不急攻，將令道窮而義服，此則仁者之師，莫不謂毅為優，餘以五國之兵，共伐一齊，不足為強，大戰濟西，伏尸流血，不足為仁，夫孔明包文武之德，劉玄德以知人之明，屢造其庐，咨以濟世，奇策泉涌，智謀從橫，遂東說孫權，北抗大魏，以乘勝之師，翼佐取蜀，及玄德臨終，禪其大位，在扰攘之际，立童蒙之主，設官分職，班叙眾才，文以寧內，武以折冲，然後布其恩泽於中國之民，其行軍也，路不拾遺，毫毛不犯，勋業垂濟而陨，觀其遺文，謀謨弘遠，雅規恢廓，己有功則讓於下，下有闕則躬自咎，見善則遷，納諫則改，故聲烈震於遐邇也，《孟子》曰：聞伯夷之風，貪夫廉，餘以為睹孔明之忠，奸臣立節矣，殆將與伊呂爭儔，豈徒樂毅為伍哉。","sortOrder":55},
  {"id":"s_work_nvlt_22_56","chapterId":"ch_work_nvlt_22","text":"◇质文","sortOrder":56},
  {"id":"s_work_nvlt_22_57","chapterId":"ch_work_nvlt_22","text":"《禮記》曰：虞夏之质，殷周之文，至矣，虞夏之文，不勝其质，殷周之质，不勝其文。","sortOrder":57},
  {"id":"s_work_nvlt_22_58","chapterId":"ch_work_nvlt_22","text":"又曰：禮有以文為貴者，天子龍卷，諸侯黼，大夫黻，士玄衣纁裳，天子之冕，朱绿璪十有二旒，諸侯九，上大夫七，下大夫五，士三，此以文為貴也，禮有以素為貴者，至敬無文，父党無容，大珪不瑑，大羹不和，大路素而越席，犧尊疏布幂，此以素為貴也。","sortOrder":58},
  {"id":"s_work_nvlt_22_59","chapterId":"ch_work_nvlt_22","text":"又曰：壹獻质，三獻文。","sortOrder":59},
  {"id":"s_work_nvlt_22_60","chapterId":"ch_work_nvlt_22","text":"《左傳》曰：言以足志，文以足言，不言誰知其志，言之無文，行而不遠。","sortOrder":60},
  {"id":"s_work_nvlt_22_61","chapterId":"ch_work_nvlt_22","text":"又曰：昭公如楚，鄭伯勞於師之梁，孟僖子為介，不能相儀，及楚，不能答郊勞，公至自楚，僖子病不能禮，乃講學之。","sortOrder":61},
  {"id":"s_work_nvlt_22_62","chapterId":"ch_work_nvlt_22","text":"又曰：齊慶封來聘，叔孫與慶封食，不敬，為賦相鼠，亦不知也。","sortOrder":62},
  {"id":"s_work_nvlt_22_63","chapterId":"ch_work_nvlt_22","text":"《論語》曰：周監於二代，鬱鬱乎文哉，吾從周。","sortOrder":63},
  {"id":"s_work_nvlt_22_64","chapterId":"ch_work_nvlt_22","text":"又曰：子貢問曰：孔文子何以謂之文也，子曰：敏而好學，不恥下問，是以謂之文也。","sortOrder":64},
  {"id":"s_work_nvlt_22_65","chapterId":"ch_work_nvlt_22","text":"又曰：质勝文則野，文勝质則史，文质彬彬，然後君子。","sortOrder":65},
  {"id":"s_work_nvlt_22_66","chapterId":"ch_work_nvlt_22","text":"又曰：棘子成曰：君子质而已矣，何以文為，子貢曰：惜乎，夫子之說君子也，驷不及舌，文猶质也，质猶文也，虎豹之鞟，猶犬羊之鞟。","sortOrder":66},
  {"id":"s_work_nvlt_22_67","chapterId":"ch_work_nvlt_22","text":"《春秋元命包》曰：正朔三而改，文质再而复。","sortOrder":67},
  {"id":"s_work_nvlt_22_68","chapterId":"ch_work_nvlt_22","text":"《莊子》曰：夫澹泊寂寞，虛無無為，此天地之本，道德之质。","sortOrder":68},
  {"id":"s_work_nvlt_22_69","chapterId":"ch_work_nvlt_22","text":"《漢書》曰：周昌敢直言，高帝欲废太子，而立戚姬子如意，昌廷爭之，上問其說，昌為人吃。又盛怒，曰：臣口不能言，然知其不可，陛下欲废太子，臣期期不奉詔，上欣然而笑，即罢。","sortOrder":69},
  {"id":"s_work_nvlt_22_70","chapterId":"ch_work_nvlt_22","text":"又曰：陆贾少有口辯，高帝為贾曰：试為我著秦所以失天下，吾所以得之者，贾每奏一篇，帝未嘗不稱善，左右呼萬歲，稱其書曰新語。","sortOrder":70},
  {"id":"s_work_nvlt_22_71","chapterId":"ch_work_nvlt_22","text":"又曰：曹參代萧何為相國，無所变更，壹遵何之約束，日夜飲酒，不事朝政，參子密諫參，參笞之二百，惠帝讓參，參免冠謝曰：高帝與萧何定天下，法令既明具，陛下垂拱，參等守職，遵而勿失，不亦可乎，帝曰：善，百姓歌之曰：萧何為法，講若畫一，曹參代之，守而勿失，載其清靜，民以寧一。","sortOrder":71},
  {"id":"s_work_nvlt_22_72","chapterId":"ch_work_nvlt_22","text":"又曰：張釋之為謁者仆射，文帝登虎圈，問上林尉禽獸簿，盡不能對，虎圈啬夫從傍代尉對，悉响應無窮，帝詔釋之，拜啬夫為上林令，釋之前曰：陛下以絳侯周勃何人也，上曰：長者。又問東陽侯張相如何人也，上复曰：長者，釋之曰：此兩人言事，曾不出口，豈效此啬夫喋喋利口捷急哉，且秦以任刀筆之吏，以亟疾苛察相高，無惻隱之實，是故不聞其過，天下土崩，今陛下以啬夫口辯而超遷之，臣恐天下隨而風靡，爭口辯，其［漢書五十釋之傳其上有亡字。］實，不可不察也，帝乃止。","sortOrder":72},
  {"id":"s_work_nvlt_22_73","chapterId":"ch_work_nvlt_22","text":"《晉書》曰：殷慶元质略有明規，文武可施用也。","sortOrder":73},
  {"id":"s_work_nvlt_22_74","chapterId":"ch_work_nvlt_22","text":"【論】魏阮瑀文质論曰：蓋聞日月麗天，可瞻而難附，群物著地，可見而易製，夫遠不可識，文之觀也，近而得察，质之用也，文虛质實，遠疏近密，援之斯至，動之應疾，兩儀通數，固無攸失，若乃陽春敷華，遇冲風而陨落，素葉变秋，既究物而定體，麗物苦伪，丑器多牢，華璧易碎，金鐵難陶，故言多方者，中難處也，術饒津者，要難求也，意弘博者，情難足也，性明察者，下難事也，通士以四奇高人，必有四難之忌，且少言辭者，政不煩也，寡知見者，物不扰也，专一道者，思不散也，混濛蔑者，民不備也，质士以四短违人，必有四安之報，故曹參相齊，寄讬獄市，欲令奸人有所容立，及為宰相，飲酒而已，故夫安劉氏者周勃，正嫡位者周勃，大臣木強，不至華言，孝文上林苑欲拜啬夫，釋之前諫，意崇敦朴，自是以降，其為宰相，皆取堅強一學之士，安用奇才，使变典法。","sortOrder":74},
  {"id":"s_work_nvlt_22_75","chapterId":"ch_work_nvlt_22","text":"魏應玚文质論曰：蓋皇穹肇載，陰陽初分，日月運其光，列宿曜其文，百穀麗於土，芳華茂於春，是以聖人合德天地，禀氣淳靈，仰觀象於玄表，俯察式於群形，窮神知化，萬國是經，故否泰易趍，道無攸一，二政代序，有文有质，若乃陶唐建國，成周革命，九官鹹乂，濟濟休令，火龍黼黻，暐鞾於廊廟，袞冕旂旒。舄弈乎朝廷，冠德百王，莫參其政，是以仲尼叹煥乎之文，從鬱鬱之盛也，夫质者端一玄靜，俭啬潛化利用，承清泰，御平業，循軌量，守成法，至乎應天順民，拨亂夷世，摛藻奋權，赫弈丕烈，紀禪协律，禮儀煥別，覽墳丘於皇代，建不刊之洪製，顯宣尼之典教，探微言之所弊，若夫和氏之明璧，輕縠之袿裳，必將遊玩於左右，振飾於宮房，豈爭牢伪之势，金布之刚乎，且少言辭者，孟僖所以不能答郊勞也，寡智見者，慶氏所以困相鼠也，今子弃五典之文，闇禮智之大，信管望之小，尋老氏之蔽，所謂循軌常趍，未能釋連環之結也，且高帝龍飛丰沛，虎據秦楚，唯德是建，唯賢是與，陆郦摛其文辯，良平奋其權谞，萧何創其章律，叔孫定其庠序，周樊展其忠毅，韓彭列其威武，明建天下者，非一士之術，營宮廟者非一匠之矩也，逮至高後亂德，損我宗劉，朱虛軫其慮，辟強釋其忧，曲逆規其模，郦友诈其遊，袭據北軍，實賴其畴，冢嗣之不替，誠四老之由也，夫諫則無義以陳，問則服汗沾濡，豈若陳平敏對，叔孫據書，言辨國典，辭定皇居，然後知质者之不足，文者之有餘。","sortOrder":75},
  {"id":"s_work_nvlt_22_76","chapterId":"ch_work_nvlt_22","text":"《藝文類聚》　唐·欧陽詢","sortOrder":76},
  {"id":"s_work_nvlt_23_1","chapterId":"ch_work_nvlt_23","text":"卷二十三人部七","sortOrder":1},
  {"id":"s_work_nvlt_23_2","chapterId":"ch_work_nvlt_23","text":"○鑒誡","sortOrder":2},
  {"id":"s_work_nvlt_23_3","chapterId":"ch_work_nvlt_23","text":"◇鑒誡","sortOrder":3},
  {"id":"s_work_nvlt_23_4","chapterId":"ch_work_nvlt_23","text":"《書》曰：兢兢業業，一日二日萬機。","sortOrder":4},
  {"id":"s_work_nvlt_23_5","chapterId":"ch_work_nvlt_23","text":"《易》曰：君子乾乾，夕惕若厲。","sortOrder":5},
  {"id":"s_work_nvlt_23_6","chapterId":"ch_work_nvlt_23","text":"又曰：天道惡盈而福謙。","sortOrder":6},
  {"id":"s_work_nvlt_23_7","chapterId":"ch_work_nvlt_23","text":"《尚書》曰：帝曰：來，禹，降水儆予，成允成功，克勤於邦，克俭於家，不自滿假，惟汝賢，汝惟不矜，天下莫與汝爭能，汝惟不伐，天下莫與汝爭功。","sortOrder":7},
  {"id":"s_work_nvlt_23_8","chapterId":"ch_work_nvlt_23","text":"又曰：無稽之言勿聽，弗詢之謀勿庸。","sortOrder":8},
  {"id":"s_work_nvlt_23_9","chapterId":"ch_work_nvlt_23","text":"又曰：玩人丧德，玩物丧志，不作無益害有益，功乃成，不貴異物賤用物，民乃足，犬馬非其土性不畜，珍禽奇獸不育於國，不寶遠物，則遠人格，所寶惟賢，則邇人安，不矜細行，終累大德，為山九仞，功虧一簣。","sortOrder":9},
  {"id":"s_work_nvlt_23_10","chapterId":"ch_work_nvlt_23","text":"又曰：功崇惟志，業廣惟勤，位不期驕，祿不期侈。","sortOrder":10},
  {"id":"s_work_nvlt_23_11","chapterId":"ch_work_nvlt_23","text":"又曰：作德心逸日休，作伪心勞日拙，居寵思危。","sortOrder":11},
  {"id":"s_work_nvlt_23_12","chapterId":"ch_work_nvlt_23","text":"又曰：戒慎無虞，岡失法度。","sortOrder":12},
  {"id":"s_work_nvlt_23_13","chapterId":"ch_work_nvlt_23","text":"又曰：戒之用休，董之用威。","sortOrder":13},
  {"id":"s_work_nvlt_23_14","chapterId":"ch_work_nvlt_23","text":"《毛詩》曰：惴惴小心，如臨於穀。","sortOrder":14},
  {"id":"s_work_nvlt_23_15","chapterId":"ch_work_nvlt_23","text":"又曰：殷鑒不遠，在夏後之世。","sortOrder":15},
  {"id":"s_work_nvlt_23_16","chapterId":"ch_work_nvlt_23","text":"《左傳》曰：晉既勝楚，范宣子立於戎馬之前曰：君幼，諸臣不佞，何以及此，天命不於常，有德之謂也。","sortOrder":16},
  {"id":"s_work_nvlt_23_17","chapterId":"ch_work_nvlt_23","text":"又曰：禍福無門，唯人所召。","sortOrder":17},
  {"id":"s_work_nvlt_23_18","chapterId":"ch_work_nvlt_23","text":"又曰：臧孫雲，季孫之愛我，疾疹也，孟孫之惡我，藥石也，美疹不如惡石，孟孫死，吾亡無日矣。","sortOrder":18},
  {"id":"s_work_nvlt_23_19","chapterId":"ch_work_nvlt_23","text":"《禮記》曰：好田好女者，亡其國。","sortOrder":19},
  {"id":"s_work_nvlt_23_20","chapterId":"ch_work_nvlt_23","text":"《孝經》曰：在上不驕，高而不危，所以長守貴也。","sortOrder":20},
  {"id":"s_work_nvlt_23_21","chapterId":"ch_work_nvlt_23","text":"《論語》曰：君子有三戒，少之時，戒之在色，及其壮也，戒之在斗，及其老也，戒之在得。","sortOrder":21},
  {"id":"s_work_nvlt_23_22","chapterId":"ch_work_nvlt_23","text":"又曰：如有周公之才之美，使驕且吝，其餘不足觀也。","sortOrder":22},
  {"id":"s_work_nvlt_23_23","chapterId":"ch_work_nvlt_23","text":"太公《金匮》曰：武王問師尚父曰：五帝之戒，可得聞乎，師尚父曰：舜之居民上，矜矜如履薄冰，禹之居民上，栗栗如恐不滿，湯之居民上，翼翼乎懼不敢息。","sortOrder":23},
  {"id":"s_work_nvlt_23_24","chapterId":"ch_work_nvlt_23","text":"又曰：吾聞道自微而生，禍自微而成，《家語》曰：孔子去周，而老子送之曰：凡當世之士，聰明深察而死者，好議人者也，博辯宏大而危者，好發人之惡者也，孔子曰：敬奉教。","sortOrder":24},
  {"id":"s_work_nvlt_23_25","chapterId":"ch_work_nvlt_23","text":"又曰：舟非水不行，水入舟没，民非君不治，民犯上則君危，故君子不可不嚴也。","sortOrder":25},
  {"id":"s_work_nvlt_23_26","chapterId":"ch_work_nvlt_23","text":"又曰：顏回謂子路曰：力猛於德而得其死者，鮮矣，子慎諸。","sortOrder":26},
  {"id":"s_work_nvlt_23_27","chapterId":"ch_work_nvlt_23","text":"又曰：以富貴而下人，何人不與，富貴而敬愛，何人不親，發言不逆，可謂知言矣。","sortOrder":27},
  {"id":"s_work_nvlt_23_28","chapterId":"ch_work_nvlt_23","text":"又曰：《曾子》曰：狎甚則簡，莊甚則不親，是故君子之狎足以交其勸，莊足以成禮而已矣。","sortOrder":28},
  {"id":"s_work_nvlt_23_29","chapterId":"ch_work_nvlt_23","text":"《韓詩外傳》曰：昔者禹以夏王，桀以夏亡，湯以殷王，紂以殷亡，故無常安之國，宜治之民，得賢則昌，不肖則亡，夫明鏡所以照形也，往古所以知今也，鄙語曰：不知為吏，视已成事，前車覆，後車誡。","sortOrder":29},
  {"id":"s_work_nvlt_23_30","chapterId":"ch_work_nvlt_23","text":"又曰：《曾子》曰：君子有三言，可實［韓詩外傳二作貫。］而佩也，一曰無內疏而外親，二曰身不善而怨他人，三曰患已至而後呼天。","sortOrder":30},
  {"id":"s_work_nvlt_23_31","chapterId":"ch_work_nvlt_23","text":"《戰國策》曰：昔儀狄作酒而美，進之於禹，禹飲而甘之，遂疏儀狄絕旨酒，曰：後世必有以酒亡其國者。","sortOrder":31},
  {"id":"s_work_nvlt_23_32","chapterId":"ch_work_nvlt_23","text":"《管子》曰：齊桓公與管仲鮑叔牙甯戚四人飲，公曰：何不為寡人寿，鮑叔牙奉杯而起曰：使公無忘在莒，管仲無忘其束縛在魯，甯戚無忘飯牛車下，公避席再拜。","sortOrder":32},
  {"id":"s_work_nvlt_23_33","chapterId":"ch_work_nvlt_23","text":"鬻子曰：昔周公使康叔守殷，戒之曰：無煞不辜，寧失有罪，亦有無罪而見誅，無有有功而不賞，慎之。","sortOrder":33},
  {"id":"s_work_nvlt_23_34","chapterId":"ch_work_nvlt_23","text":"《晏子》曰：君子居必擇鄰，遊必就士，可以避患也。","sortOrder":34},
  {"id":"s_work_nvlt_23_35","chapterId":"ch_work_nvlt_23","text":"又曰：其文好者身必剝，其角美者身見煞，甘泉必竭，直木必伐。","sortOrder":35},
  {"id":"s_work_nvlt_23_36","chapterId":"ch_work_nvlt_23","text":"又曰：夫爵益高者意益下，官益大者心益小，祿益厚者施益博。","sortOrder":36},
  {"id":"s_work_nvlt_23_37","chapterId":"ch_work_nvlt_23","text":"又曰：人之將疾，必先不甘粱肉之味，國之將亡，必先惡忠臣之語。","sortOrder":37},
  {"id":"s_work_nvlt_23_38","chapterId":"ch_work_nvlt_23","text":"《孫卿子》曰：孔子對魯哀公曰：君者，舟也，庶人者，水也，水則載舟，水則覆舟，君以此思危，則不危焉。","sortOrder":38},
  {"id":"s_work_nvlt_23_39","chapterId":"ch_work_nvlt_23","text":"又曰：得師者王，得疑者霸，自為謀莫己若者亡。","sortOrder":39},
  {"id":"s_work_nvlt_23_40","chapterId":"ch_work_nvlt_23","text":"又曰：伯禽將歸於魯，周公謂伯禽曰：君子力如牛，不與牛爭力，走如馬，不與馬爭走，智如士，不與士爭智，我文王之子，武王之弟，成王之叔父，吾於天下，亦不賤也，常握發吐餐，以接天下之士矣。","sortOrder":40},
  {"id":"s_work_nvlt_23_41","chapterId":"ch_work_nvlt_23","text":"《韓子》曰：西門豹性急，佩韦以自缓，董安於心缓，佩帶以自急，故能以有餘補不足，以長續短之謂明主。","sortOrder":41},
  {"id":"s_work_nvlt_23_42","chapterId":"ch_work_nvlt_23","text":"《淮南子》曰：天下有至貴，而非势位也，有至富，而非金玉也，有至寿，而非千歲，願恕反性，則貴矣，適情知足，則富矣，明死生之分，則寿矣。","sortOrder":42},
  {"id":"s_work_nvlt_23_43","chapterId":"ch_work_nvlt_23","text":"《說苑》曰：魏武侯浮西河，中流，謂吳起曰：美哉河山之固，此魏國之寶也，對曰：在德不在险，昔夏桀之君，左河濟，右太華，伊闕在其南，羊腸在其北，不循仁政，湯放之，武侯曰：善。","sortOrder":43},
  {"id":"s_work_nvlt_23_44","chapterId":"ch_work_nvlt_23","text":"又曰：有身貴而驕人者，民去之，位高而擅權者，君惡之，祿厚而不知足者，患處之。","sortOrder":44},
  {"id":"s_work_nvlt_23_45","chapterId":"ch_work_nvlt_23","text":"《新序》曰：齊王聘田巴先生而將問政焉，對曰：政在正身，正身之本，在於群臣，王召臣，臣改製鬋飾，問於妾，奚若，妾愛臣，諛臣曰佼，臣臨淄水而觀，然後自知丑惡也，今齊之臣諛王者眾，王能臨淄水見己之惡，過而自改，斯齊國治矣。","sortOrder":45},
  {"id":"s_work_nvlt_23_46","chapterId":"ch_work_nvlt_23","text":"《漢書》曰：扬惲失官居家，治產業，起室宅，孫會宗戒之曰：為大臣废退，當阖門惶恐，為可怜之意，不當通賓客，有稱譽也。","sortOrder":46},
  {"id":"s_work_nvlt_23_47","chapterId":"ch_work_nvlt_23","text":"《東觀漢記》曰：冯勤遷司徒，是時三公多見罪退，上欲見令以善自矜，乃因宴見，從容戒之曰：朱浮上不忠於君，下凌轹同列，竟以中傷人臣，放逐受誅，雖追加賞賜，不足以偿不訾之身，忠臣孝子之覽照前世以為鏡誡，能盡忠於國，事君無二，則爵賞光乎當世，功名列於不朽，可不勉哉。","sortOrder":47},
  {"id":"s_work_nvlt_23_48","chapterId":"ch_work_nvlt_23","text":"又曰：樊宏為人謙慎，常戒其子曰：富貴盈溢，未有能終者，天道惡滿而好謙，前世貴戚，皆明戒也，保身全己，豈不樂哉。","sortOrder":48},
  {"id":"s_work_nvlt_23_49","chapterId":"ch_work_nvlt_23","text":"又曰：班超為都護，以任尚代超，尚謂超曰：君在外國三十餘年，而小人猥承君後，宜有以誨之，超曰：塞外吏士，本非孝子順孫，皆以過罪徙補邊，而蠻夷懷鳥獸之心，難禁易败，今君性嚴急，水清無大魚，察政不及得下和，宜陽為簡易，宽小過，總大綱而已。","sortOrder":49},
  {"id":"s_work_nvlt_23_50","chapterId":"ch_work_nvlt_23","text":"【詩】後漢傅毅迪志詩曰：咨爾庶士，迨時斯勖，日月逾邁，豈雲旋复，於赫我祖，顯於殷國，二跡阿衡，克光其則，咨予小子，秽陋靡逮，懼我世烈，於茲以墜，於戲君子，無恒自逸，徂年如流，鮮茲暇日。","sortOrder":50},
  {"id":"s_work_nvlt_23_51","chapterId":"ch_work_nvlt_23","text":"魏陳王曹植矯志詩曰：芝桂雖芳，難以餌魚，尸位素餐，難以成居，磁石引鐵，於金不連，大朝舉士，愚不聞焉。","sortOrder":51},
  {"id":"s_work_nvlt_23_52","chapterId":"ch_work_nvlt_23","text":"又矯志詩曰：抱璧涂乞，無為貴寶，履仁遘福，無為貴道，鴛雏遠害，不羞卑栖，靈虬避難，不恥汙泥，都蔗雖甘，杖之必折，巧言雖美，用之必滅，濟濟唐朝，萬邦作孚，逢蒙雖巧，必得良弓，賢主雖智，亦待英雄，螳螂見叹，齊士輕戰，越王軾蛙，國以死獻，道遠知骥，世伪知賢，覆之焘之，順天之矩，泽如凯風，惠如時雨，口為禁闼，舌為發機，門機之闕，［冯校本作關。］楛矢不追。","sortOrder":52},
  {"id":"s_work_nvlt_23_53","chapterId":"ch_work_nvlt_23","text":"魏繁钦遠戍勸戒詩曰：肅將王事，集此扬土，凡我同盟，既文既武，鬱鬱桓桓，有規有矩，務在和光，同尘共垢，各競其心，為國蕃辅，訚訚衎衎，非法不語，可否相濟，闕則雲補。","sortOrder":53},
  {"id":"s_work_nvlt_23_54","chapterId":"ch_work_nvlt_23","text":"又雜詩曰：世俗有险易，時運有盛衰，老氏和其光，蘧瑗貴可懷。","sortOrder":54},
  {"id":"s_work_nvlt_23_55","chapterId":"ch_work_nvlt_23","text":"魏應璩雜詩曰：細微可不慎，隄潰自蚁隙，腠理早從事，安复勞針石，哲人睹未形，愚夫闇明白，曲突不見賓，燋烂為上客，思原獻良規，江海傥不逆，狂言雖寡善，猶有如雞跖，雞跖食不已，齊王為肥泽。","sortOrder":55},
  {"id":"s_work_nvlt_23_56","chapterId":"ch_work_nvlt_23","text":"晉張華励志詩曰：仁道不遐，德輶如羽，求焉斯至，眾鮮克舉，复禮終朝，天下歸仁，若金受砺，若泥在鈞，進德修業，暉光日新。","sortOrder":56},
  {"id":"s_work_nvlt_23_57","chapterId":"ch_work_nvlt_23","text":"晉潘安仁家風詩曰：綰發綰發，發亦鬢止，日祗日祗，敬亦慎止，靡专靡有。受之父母，鳴鶴匪和，析薪弗荷，隱忧孔疚，我堂靡構，義方既訓，家道穎穎。豈敢荒寧，一日三省。","sortOrder":57},
  {"id":"s_work_nvlt_23_58","chapterId":"ch_work_nvlt_23","text":"晉嵇紹赠石季倫詩曰：人生禀五常，中和為至德，嗜欲雖不同，成生所不識，仁者安其身，不為外物惑，事故誠多端，未若酒之賊，內以損性命，煩辭傷軌則屢飲致疲怠，清和自否塞，陽堅［按此用子反事，當作竖。］败楚軍，長夜傾宗國，詩書著明戒，量體節飲食，遠希彭聃寿，虛心處冲默，茹芝味醴泉，何為昏酒色。","sortOrder":58},
  {"id":"s_work_nvlt_23_59","chapterId":"ch_work_nvlt_23","text":"【賦】魏文帝戒盈賦序曰：避暑東閤，延賓高會，酒酣樂作，怅然懷盈滿之戒，乃作斯賦，惟應龍之將舉，飛雲降而下征，資物類之相感，信貫微之通靈，何今日之延賓，君子紛其集庭，信臨高而增懼，獨處滿而懷愁，原群士之箴規，博納我以良謀，吳楊泉贊善賦曰：伊善惡之所施，乃禍福之為階，行德安而保身，忘為害而自危，故先民之有作，執溫恭而不虧，雲顏冉之遭命，怪禍福之參差，夫二賢之履道，歷千載而見知，身既没而名存，厥复戚乎何為，夫死生之有命，非神明之所規，故積善之家，厥福惟昌，積惡之門，必有餘殃，是以趙武好善，厥胤以長，三郄好勝，厥身以亡，古人從善如不及，去惡如探湯，恐福德而難值，而禍惡之易當。","sortOrder":59},
  {"id":"s_work_nvlt_23_60","chapterId":"ch_work_nvlt_23","text":"【贊】晉戴逵申三复贊曰：嗜好深則天機淺，名利集則純白離，如此故識鑒逾昏，驕淫弥汰，心與慎乖，則理與险會，然後役智以御险，履险以逃害，故陰陽寇其內，人力攻其外，陰陽結則金石為之消，人事至則雖智不足賴，若然者，雖翠幄華堂，焉得而康之，列鼎重味，焉得而嘗之。","sortOrder":60},
  {"id":"s_work_nvlt_23_61","chapterId":"ch_work_nvlt_23","text":"周庾信周公伯禽贊曰：伯禽居魯，鳴玉來朝，周公問政，治國風謠，北山有梓，南山有桥，禮容雖備，俯仰無驕。","sortOrder":61},
  {"id":"s_work_nvlt_23_62","chapterId":"ch_work_nvlt_23","text":"【箴】梁武帝凡百箴曰：凡百眾庶，爾其聽之，事無大小，先當熟思，思之不熟，致成反覆，其心不定，不可施令，是曰亂常，是曰败政，弗止辱身，亦丧厥命，勿恃爾尊，驕慢淫昏，勿謂爾貴，長夜荒醉，日不恒中，月盈則虧，履邪念正，居安思危，莫言爾賤，而不受命，君子小人，本無定性，莫言人微，而以自輕，水清照净，表直影端，近取諸身，無假遠觀，猗欤哲人，勿謂斯難。","sortOrder":62},
  {"id":"s_work_nvlt_23_63","chapterId":"ch_work_nvlt_23","text":"【訓】晉潘嶽兩階銅人訓曰：言之有臧，讬乎多士，言之不臧，絕之由己，無曰莫傳，宣於四海，無曰莫聞，响振萬里，枢機之發，榮辱之徵，怨豈在大，纖介是興。","sortOrder":63},
  {"id":"s_work_nvlt_23_64","chapterId":"ch_work_nvlt_23","text":"【誡】漢東方朔誡子曰：明者處世，莫尚於中，優哉遊哉，與道相從，首陽為拙，柳惠為工，飽食安步，以仕代農，依隱玩世，诡時不逢，是故才盡者身危，好名者得華，有群者累生，孤貴者失和，遺餘者不匮，自盡者無多，聖人之道，一龍一蛇，形見神藏，與物变化，隨時之宜，無有常家。","sortOrder":64},
  {"id":"s_work_nvlt_23_65","chapterId":"ch_work_nvlt_23","text":"後漢鄭玄戒子曰：宿業衰落，仍有失誤，年入此歲，而七十矣，於禮可傳家事，今我告爾以老，將閒居以安性，覃思以終業，非拜國君之命，問族親忧患，展敬墳墓，春秋觀省野物，胡常扶杖出門乎，家事大小，汝一承之，求為君子之道，鑽研勿替，敬順威儀，以近有德，顯譽成於僚友，德行立於己志，可不深念耶。","sortOrder":65},
  {"id":"s_work_nvlt_23_66","chapterId":"ch_work_nvlt_23","text":"後漢高義方清誡曰：天長而地久，人生則不然。又不養以福，保全其寿年，飲酒病我性，思慮害我神，美色伐我命，利欲亂我真，神明無聊賴，愁毒於眾煩，中年弃我逝，忽若風過山，形氣各分離，一往不复還，上士愍其痛，抗志凌雲煙，涤荡弃秽累，飄邈任自然，退修清以净，存吾玄中玄，澄心剪思慮，泰清不受尘，恍惚中有物，希微無形端，智慮赫赫盡，穀神綿綿存。","sortOrder":66},
  {"id":"s_work_nvlt_23_67","chapterId":"ch_work_nvlt_23","text":"魏王肅家誡曰：夫酒所以行禮養性命歡樂也，過則為患，不可不慎，是故賓主百拜，終日飲酒，而不得醉，先王所以備酒禍也，凡為主人飲客，使有酒色而已，無使至醉，若為人所強，必退席長跪，稱父誡以辭之，敬仲辭君，而况於人乎，為客又不得唱造酒史也，若為人所屬，下坐行酒，隨其多少，犯令行罰，示有酒而已，無使多也，禍变之興，常於此作，所宜深慎。","sortOrder":67},
  {"id":"s_work_nvlt_23_68","chapterId":"ch_work_nvlt_23","text":"魏王昶家誡曰：夫立功者有二難，功就而身不退，一難也，退而不靜，務伐其功，二難也，且懷祿之士，躭寵之臣，苟患失之，何所不至，若樂毅帥弱燕之眾，東破強齊，收七十餘城，其功盛矣，知難而退，保身全名，張良杖劍建策，光濟大漢，辭三萬戶封，學養性之道，弃人間之事，卒無咎悔，何二賢綽綽有餘裕哉，治家亦有患焉，積而不能散，則有鄙吝之累，積而好奢，則離驕上之罪，大者破家，小者辱身，此二患也。","sortOrder":68},
  {"id":"s_work_nvlt_23_69","chapterId":"ch_work_nvlt_23","text":"魏荀爽女誡曰：詩雲，泉源在左，淇水在右，女子有行，遠父母兄弟，明當許嫁，配適君子，竭節從理，昏定晨省，夜臥早起，和顏悅色，事如依恃，正身絜行，稱為順婦，以崇螽斯百葉之祉，婚姻九族，雲胡不喜，聖人製禮，以隔陰陽，七歲之男，王母不抱，七歲之女，王父不持，親非父母，不與同車，親非兄弟，不與同筵，非禮不動，非義不行，是故宋伯姬遭火不下堂，知必為灾，傅母不來，遂成於灰，春秋書之，以為高也。","sortOrder":69},
  {"id":"s_work_nvlt_23_70","chapterId":"ch_work_nvlt_23","text":"魏程晓女典篇曰：丈夫百行，以功補過，婦人四教，以備為成，婦德闕，則仁義废矣，婦言虧，則辭令慢矣，婦工簡，則織纴荒矣，是以禮有功宮家室之教，詩有牖下蘋藻之奠，然後家道諧允，儀表則見於內，若夫麗色妖容，高才美辭，貌足傾城，言以亂國，此乃蘭形棘心，玉曜瓦质，在邦必危，在家必亡。","sortOrder":70},
  {"id":"s_work_nvlt_23_71","chapterId":"ch_work_nvlt_23","text":"晉嵇康家誡曰：人無志，非人也，但君子用心，有所准行，當量其善者，擬議而後動，若心之所之，則口與心誓，守死無貳，恥躬不逮，期於必濟，若心疲體懈，或牵於外物，或累於內欲，不堪近患，不忍小情，則議於去就，議於去就，則二心交爭，二心交爭，則向所以見役之情勝矣，或有中道而废，或有未成而败，以之守則不固，以之攻則怯弱，與之誓則多违，與之謀則善泄，臨樂則肆情，處逸則極意，故雖榮華熠熠，無結秀之勤，終年之勤，無一日之功，斯君子所以叹息也，若夫申胥之長吟，夷叔之全絜，展季之執信，蘇武之守節，可謂固矣，故以無心守之，安而體之，若自然也，乃是守志盛者也。","sortOrder":71},
  {"id":"s_work_nvlt_23_72","chapterId":"ch_work_nvlt_23","text":"吳姚信誡子曰：古人行善者，非名之務，非人之為，心自甘之，以為己度，崄易不虧，終始如一，進合神契，退同人道，故神明祐之，眾人尊之，而聲名自顯，榮祿自至，其势然也。又有內析外同，吐實懷诈，見賢則暫自新，獨居則縱所欲，聞譽則驚自飾，見尤則弃善端，凡失名位，恒多怨人而害善，怨一人則眾人疾之，害一善則眾人怨之，雖欲陷人而進己，不可得也，祗所以自毀耳，顧真伪不可掩，褒貶不可妄，舍伪從實，遺己察人，可以通矣，舍己就人，去否適泰，可以弘矣，貴賤無常，唯人所速，苟善，則疋夫之子，可至王公，苟不善，則王公之子，反為凡庶，可不勉哉。","sortOrder":72},
  {"id":"s_work_nvlt_23_73","chapterId":"ch_work_nvlt_23","text":"吳陆景誡盈曰：富貴天下之至榮，位势人情之所趍，然古之智士，或山藏林竄，忽而不慕，或功成身退，逝若脱屣者，何哉，蓋居高畏其危，處滿懼其盈，富貴榮势，本非禍始，而多以凶終者，持之失德，守之背道，道德丧而身隨之矣，是以留侯范蠡，弃貴如遺，叔敖萧何，不宅美地，此皆知盛衰之分，識倚伏之機，故身全名著，與福始卒，自此以來，重臣貴戚，隆盛之族，莫不離患構禍，鮮以善終，大者破家，小者滅身，唯金張子弟，世履忠篤，故保貴持寵，祚鍾崑嗣。","sortOrder":73},
  {"id":"s_work_nvlt_23_74","chapterId":"ch_work_nvlt_23","text":"蜀諸葛亮誡子曰：夫君子之行，靜以修身，俭以養德，非澹泊無以明志，非寧靜無以致遠，夫學須靜也，才須學也，非學無以廣才，非志無以成學，慆慢則不能励精，险躁則不能治性，年與時馳，意與歲去，遂成枯落，悲叹窮慮，將复何及。","sortOrder":74},
  {"id":"s_work_nvlt_23_75","chapterId":"ch_work_nvlt_23","text":"晉李充起居誡曰：溫良恭俭，仲尼所以為貴，小心翼翼，文王所以稱美，聖德周達無名，斯亦聖中之目也，中人而有斯行，則亦聖人之一隅矣，而末俗謂守慎為拘吝，退慎為怯弱，不遜以為勇，無禮以為達，異乎吾所聞也。","sortOrder":75},
  {"id":"s_work_nvlt_23_76","chapterId":"ch_work_nvlt_23","text":"【誥】宋顏延之庭誥曰：若能服溫厚而知穿弊之苦，周明之德也，厭滋旨而識空嗛之急，仁恕之功也，豈與夫比發膚於草石，方手足於飛走者，同其意哉，罰慎其濫，惠誡其偏，罰濫則無以為罰，惠偏則不如無惠，嫌或疑心，誠亦難分，動容竊斧，束裝盜金。又何足論也，是以前王作典，明慎議獄，而僭濫易意，火含煙而煙妨火，桂懷蠹而蠹殘桂，然火勝則煙滅，蠹壮則桂折，故性明者欲簡，嗜繁者氣昏，與善人居，如入芝蘭之室，久而不知其芳，與之化矣，與不善人居，如入鮑魚之肆，久而不知其臭，與之变矣，唯夫金貞玉粹者，乃能處而不汙其身耳，故曰：丹可滅而不能使無赤，石可毀而不能使無堅，苟丹石之性，必慎浸染之由。","sortOrder":76},
  {"id":"s_work_nvlt_23_77","chapterId":"ch_work_nvlt_23","text":"【銘】後漢崔瑗座右銘曰：無道人之短，無說己之長，施人慎勿念，受施慎勿忘，俗譽不足慕，唯仁為紀綱，隱身而後動，謗議庸何傷，無使名過實，守愚聖所臧，柔弱生之徒，老氏誡刚強，在涅貴不緇，暧暧內含光，蛇巠蛇巠鄙夫介，悠悠故難量，慎言節飲食，知足勝不祥，行之苟有恒，久久自芬芳。","sortOrder":77},
  {"id":"s_work_nvlt_23_78","chapterId":"ch_work_nvlt_23","text":"魏卞蘭座右銘曰：重階連棟，必濁汝真，金寶滿室，將亂汝神，厚味來殃，艳色危身，求高反墜，務厚更貧，閉情塞欲，老氏所珍，周廟之銘，仲尼是遵，審慎汝口，戒無失人，從容順時，和光同尘，無謂冥漠，人不汝聞，無謂幽冥，處獨若群，不為福先，不與禍鄰，守玄執素，無亂大倫，常若臨深，終始惟純。","sortOrder":78},
  {"id":"s_work_nvlt_23_79","chapterId":"ch_work_nvlt_23","text":"【書】漢劉向誡子書曰：汝有厚德，蒙恩甚厚，將何以報，董生有雲，弔者在門，贺者在闾，言有忧則恐懼敬事，敬事則必有善功而福至也。","sortOrder":79},
  {"id":"s_work_nvlt_23_80","chapterId":"ch_work_nvlt_23","text":"又曰：贺者在門，弔者在闾，言受福則驕奢，驕奢則禍至，故弔隨而來，齊頃公之始，藉霸者之餘威，輕侮諸侯，虧跂蹇之容，故被鞍之禍，遁服而亡，所謂贺者在門，弔者在闾也，兵败師破，人皆弔之，恐懼自新，百姓愛之，諸侯皆歸其所奪邑，所謂弔者在門，贺者在闾。","sortOrder":80},
  {"id":"s_work_nvlt_23_81","chapterId":"ch_work_nvlt_23","text":"後漢張奐誡兄子書曰：汝曹薄祐，早失賢父，财单藝盡，今適喘息，聞仲祉輕傲耆老，侮狎同年，極口恣意，當崇長幼，以禮自持，間敦煌有人來，同聲相道，皆稱叔時宽仁，聞之喜而且悲，喜叔時得美稱，悲汝得惡論，經言孔於乡党，恂恂如也，恂恂者，恭謙之貌也，經難知，且自以汝資父為師，汝父寧輕乡里耶，年少多失，改之為貴，蘧伯玉年五十，見四十九年非，但能改之，不可不思吾言，不自克责，反雲張甲謗我，李乙悉我，我無是過，爾亦已矣。","sortOrder":81},
  {"id":"s_work_nvlt_23_82","chapterId":"ch_work_nvlt_23","text":"後漢司馬徽誡子書曰：聞汝充役，室如懸磬，何以自辨，論德則吾薄，說居則吾貧，勿以薄而志不壮，貧而行不高也。","sortOrder":82},
  {"id":"s_work_nvlt_23_83","chapterId":"ch_work_nvlt_23","text":"後漢馬援誡兄子書曰：吾欲汝曹聞人過失，如聞父母之名，耳可得聞，而口不可得言也，好論議人長短，妄是非正法，此吾所大惡也，寧死不原聞子孫有此行也，汝曹知吾惡之甚矣，所以复言者，施衿結褵，申父母之誡，欲使汝曹不忘之耳，龍伯高敦厚周慎，口無擇言，謙約節俭，公正有威，吾愛之重之，原汝曹效之，杜季良豪俠好義，忧人之忧，樂人之樂，清濁無所失，父丧致客，數郡畢至，吾愛之重之，不原汝曹效之也，效伯高不得，猶為謹敕之士，所謂刻鵠不成，尚類鶩者也，效季良不得，陷為天下輕薄子，所謂畫虎不成，反類狗也。","sortOrder":83},
  {"id":"s_work_nvlt_23_84","chapterId":"ch_work_nvlt_23","text":"後漢崔骃與窦憲書曰：骃聞交淺而言深者，愚也，在賤而望貴者，惑也，未信而納忠者，謗也，皆所不宜，而或蹈之者，思效其區區憤盈而不能已也，竊見足下，體淳淑之姿，躬高明之量，意美志厲，有尚賢之風，骃幸得充下馆，序後陳，是以竭其拳拳，敢進一言，傳曰：生而富者驕，生而貴者傲，生富貴而能不驕傲者，未之有也。","sortOrder":84},
  {"id":"s_work_nvlt_23_85","chapterId":"ch_work_nvlt_23","text":"魏王脩誡子書曰：自汝行之後，恨恨不樂，何者，我實老矣，所恃汝等也，皆不在目前，意遑遑也，人之居世，忽去便過，日月可愛也，故禹不愛尺璧，而愛寸陰，時過不可還，若年大，不可少也，欲汝早之，未必讀書，併學作人，欲令見舉動之宜，觀高人遠節，志在善人，左右不可不慎，善否之要，在此际也，行止與人，務在饒之，言思乃出，行詳乃動，皆用情實，道理违，斯败矣，父欲令子善，唯不能煞身，其餘無惜也。","sortOrder":85},
  {"id":"s_work_nvlt_23_86","chapterId":"ch_work_nvlt_23","text":"晉羊祜誡子書曰：吾少受先君之教，能言之年，便召以典文，年九歲，便誨以詩書，然尚猶無乡人之稱，無清異之名，今之職位，谬恩之加耳，非吾力所能致也，吾不如先君遠矣，汝等复不如吾，谘度弘伟，恐汝兄弟未之能也，奇異獨達，察汝等將無分也，恭為德首，慎為行基，原汝等言則忠信，行則篤敬，無口許人以财，無傳不經之談，無聽毀譽之語，聞人之過，耳可得受，口不得宣，思而後動，若言行無信，身受大謗，自入刑論，豈复惜汝，恥及祖考，思乃父言，纂乃父教，各諷誦之。","sortOrder":86},
  {"id":"s_work_nvlt_23_87","chapterId":"ch_work_nvlt_23","text":"晉殷裒書曰：大道也者，易尋而難窮，易知而難行也，故京房之徒，考步吉凶之变，而不能自見其禍，更為姚平所誡，此道之難知也，省爾之才，不及於房，而吾之言過於平矣，昔弗父何三命滋恭，晏平仲久而敬之，曾顏之徒，有若無，實若虛也，况爾析薪之智，欲彈射世俗，身為謗先，怨禍併集，使吾懷朝父之忧，為范武子所叹，亦非汝之美也，若朝益暮習，先人後己，恂恂如也，則吾聞音而識其曲，食旨而知其甘，永終吾餘年矣，复何恨哉，古人有言，思不出其位，爾其念之，爾其念之。","sortOrder":87},
  {"id":"s_work_nvlt_23_88","chapterId":"ch_work_nvlt_23","text":"宋陶潛誡子書曰：少來好書，偶愛閒靜，开卷有得，便欣然忘食，見树木交荫，時鳥变聲，亦复歡爾有喜，嘗言五六月中，北窗下臥，遇涼風暫至，自謂是犧皇上人，汝等雖不同生，當思四海皆兄弟之義，鮑叔敬仲，分财無吝情，歸生伍舉，班荆道舊，遂能以败為成，因丧立功，他人尚爾，况共父之人哉。","sortOrder":88},
  {"id":"s_work_nvlt_23_89","chapterId":"ch_work_nvlt_23","text":"梁簡文帝誡當陽公書曰：汝年時尚幼，所闕者學，可久可大，其唯學欤，所以孔丘言，吾嘗終日不食，終夜不寢，以思無益，不如學也，若使牆面而立，沐猴而冠，吾所不取，立身之道，與文章異，立身先須謹重，文章且須放荡。","sortOrder":89},
  {"id":"s_work_nvlt_23_90","chapterId":"ch_work_nvlt_23","text":"梁孝元帝與學生書曰：吾聞斫玉為器，諭乎知道，惟山出泉，譬乎從學，是以執射執御，雖聖猶然，為弓為箕，不無以矣，抑又聞曰：漢人流麥，晉人聚螢，安有挟册讀書，不覺風雨以至，朗月章奏，不知爝火為微，所以然者，良有以夫，可久可大，莫過乎學，求之於己，道在則尊。","sortOrder":90},
  {"id":"s_work_nvlt_23_91","chapterId":"ch_work_nvlt_23","text":"梁徐勉與大息山松書曰：家世清廉，故常居貧素，至於產業之事，所未嘗言，中年聊於東田，欲穿池种树，少寄情賞。又以郊际閒曠，終可為宅，傥獲懸車致仕，實欲歌笑於斯，經營歷年，粗已成立，桃李茂密，桐竹成陰，塍陌交通。渠畎相屬，茅樓迥榭，頗有臨眺之美，孤岑藂薄，不無糾紛之興，雖雲人外，城闕密邇，凡為人長，殊复不易，當使中外諧緝，人無間言，先物後己，然後可貴，老生雲，後其身而身先，若能爾者，更招巨利，汝當勉勖，見賢思齊，不宜忽略以弃日也，非徒弃日，乃是弃身，身名美惡，豈不大哉。","sortOrder":91},
  {"id":"s_work_nvlt_23_92","chapterId":"ch_work_nvlt_23","text":"梁范縝與王仆射書曰：君侯匡辅聖朝，中夏無虞，既盡美矣。又盡善矣，唐尧非不隆也，門有謗木，虞舜非不盛也，庭懸諫鼓，周公之才也，樂聞譏諫，故明君賢宰，不憚諤諤之言，布衣窮賤之人，鹹得獻其狂瞽，先王所以有而勿亡，得而勿失，功傳不朽，名至今者，用此道也。","sortOrder":92},
  {"id":"s_work_nvlt_23_93","chapterId":"ch_work_nvlt_23","text":"【論】魏王粲安身論曰：蓋崇德莫盛乎安身，安身莫大乎存政，存政莫重乎無私，無私莫深乎寡欲，是以君子安其身而後動，易其心而後語，定其交而後行，然則動者，吉凶之端也，語者，榮辱之主也，求者，利病之幾也，行者，安危之决也，故君子不妄動也，必適於道，不徒語也，必經於理，不苟求也，必造於義，不虛行也，必由於正，夫然用能免或击之凶，厚自天之祐，故身不安則殆，言不順則悖，交不審則惑，行不篤則危，四者存乎中，則患忧接乎外矣，忧患之接，必生於自私，而興於有欲，自私者，不能成其私，有欲者，不能濟其欲，理之至也。","sortOrder":93},
  {"id":"s_work_nvlt_23_94","chapterId":"ch_work_nvlt_23","text":"晉袁宏去伐論曰：夫君者，必量才任以授官，參善惡以毀譽，課功過以賞罰者也，苟伐其善，必忘其惡，於是怨责之情，必存乎心，希望之氣，必形乎色，此矜伐之士，自賢之人，所以為薄，而先王甚惡之者也，君子則不然，勞而不伐，施而不德，致恭以存其位，下人不隱其功，處不避汙，官不辭卑，唯懼不任，唯患弗能，故力有餘而智不屈，遠咎悔而行成名立也。","sortOrder":94},
  {"id":"s_work_nvlt_23_95","chapterId":"ch_work_nvlt_23","text":"《藝文類聚》　唐·欧陽詢","sortOrder":95},
  {"id":"s_work_nvlt_24_1","chapterId":"ch_work_nvlt_24","text":"卷二十四人部八","sortOrder":1},
  {"id":"s_work_nvlt_24_2","chapterId":"ch_work_nvlt_24","text":"○諷諫","sortOrder":2},
  {"id":"s_work_nvlt_24_4","chapterId":"ch_work_nvlt_24","text":"《毛詩》曰：上以風化下，下以風刺上，主文而譎諫，言之者無罪，聞之者足以戒，故曰風。","sortOrder":4},
  {"id":"s_work_nvlt_24_5","chapterId":"ch_work_nvlt_24","text":"《禮記》曰：吳侵陳，斬祀殺厲，夫差使行人儀問太宰嚭曰：師必有名，人之稱斯師也，則謂之何，太宰嚭曰：古之侵伐者，不斬祀，不殺厲，不獲二毛，今斯師也殺厲與，其不謂之殺厲之師與。","sortOrder":5},
  {"id":"s_work_nvlt_24_6","chapterId":"ch_work_nvlt_24","text":"《左傳》曰：魏獻子受梗楊人賄，阎没，汝宽欲諫，待於庭，饋入，召之食，比置三叹，既食，使坐，魏子曰：吾聞唯食忘忧，今置食之間三叹，何也，同辭而對曰：饋之始至，恐其不足，是以叹，中置自咎曰：豈將軍食之而有不足，是以再叹，及饋之畢，原以小人之腹，為君子之心，屬厭而已，獻子辭梗楊人。","sortOrder":6},
  {"id":"s_work_nvlt_24_7","chapterId":"ch_work_nvlt_24","text":"《國語》曰：晉平公射鷃，使竖搏之，不得，公怒，將殺之，叔向曰：君必殺之，吾先君唐叔，射兕於徒林，以為大甲，所以封於晉，今君嗣唐叔，射鷃不得，是扬吾君之恥，速殺之，無令遠聞，君忸怩，乃赦之。","sortOrder":7},
  {"id":"s_work_nvlt_24_8","chapterId":"ch_work_nvlt_24","text":"《晏子》曰：齊景公树竹，令吏守之，公出過之，有斬竹者，拘之，將加罪焉，《晏子》曰：君聞吾先君丁公乎，曰：何如，對曰：丁公伐曲城，勝之，止其财，出其民，有舆死人以出者，公怪之，令视之，則其中有金玉焉，吏請殺其人，丁公曰：以兵攻城，以眾围财，不仁，且君人者，宽惠慈眾，身不妄誅，令吏舍之，公曰：善，令出斬竹之囚，舍之。","sortOrder":8},
  {"id":"s_work_nvlt_24_9","chapterId":"ch_work_nvlt_24","text":"又曰：齊景公所愛馬暴死，景公怒，令刀解養馬者，晏子請數之曰：爾有罪三，公使汝養馬，汝殺之，當死罪一。又殺公之所愛馬，當死罪二，使公以一馬之故殺人，百姓怨吾君，諸侯輕吾國，汝當死罪三，景公喟然曰：舍之，［事具馬部。］","sortOrder":9},
  {"id":"s_work_nvlt_24_10","chapterId":"ch_work_nvlt_24","text":"《列子》曰：晉文公出會，欲伐衛，公子鉏仰而笑之，公問何故笑，對曰：笑臣之鄰人也，臣之鄰人，有送其妻適私家者，道見桑婦，悅而與之言，顧视其妻，亦有招之者，臣竊叹之也，公乃止，［事具木部桑篇。］","sortOrder":10},
  {"id":"s_work_nvlt_24_11","chapterId":"ch_work_nvlt_24","text":"《呂氏春秋》曰：楚莊王立三年，不聽朝，成公贾入諫曰：有鳥止於南方之阜，三年不動，不飛不鳴，是何也，王曰：是鳥雖無飛，飛將冲天，雖無鳴，鳴將駭人，贾出矣，不穀知之矣，明日朝，所進者五十人，所退者五十人，群臣大悅。","sortOrder":11},
  {"id":"s_work_nvlt_24_12","chapterId":"ch_work_nvlt_24","text":"《史記》曰：秦二世欲漆其城，優旃曰：善，主上雖無言，臣固將請之，漆城荡荡，寇來不可上，易為漆耳，難為荫室，二世笑而止。","sortOrder":12},
  {"id":"s_work_nvlt_24_13","chapterId":"ch_work_nvlt_24","text":"又曰：孫叔敖病將死，屬其子曰：貧困，往見優孟，後其子窮困負薪，逢優孟，與言，孟曰：無遠行，時楚莊王欲以優孟為相，對曰：請與婦人計之，三日後，優孟來，王曰：何如，曰：婦言無為楚相，孫叔敖盡忠以治楚，楚以得霸，今死，其子無立錐之地，必如孫叔敖，不如自殺，王乃召孫叔敖子，以四百戶奉其祀。","sortOrder":13},
  {"id":"s_work_nvlt_24_14","chapterId":"ch_work_nvlt_24","text":"又曰：東武侯母當養漢武帝，號太乳母，乳母家子孫橫暴，徙邊，乳母嘗辭見郭舍人，為下泣，舍人曰：即入辭去，疾步數還顧，乳母入辭，如其言，疾步數還顧，郭舍人疾言骂之曰：咄，老女子，何不疾行，陛下已壮，寧尚須汝乳而活耶，尚何還顧，於是上怜悲之，乃下詔，無徙乳母。","sortOrder":14},
  {"id":"s_work_nvlt_24_15","chapterId":"ch_work_nvlt_24","text":"又曰：田叔相魯，初到，民訟王取其财物百餘人，田叔取渠率二十人，笞各五十，怒之曰：王非若主耶，何敢言若主，魯王聞之，大慚。","sortOrder":15},
  {"id":"s_work_nvlt_24_16","chapterId":"ch_work_nvlt_24","text":"《韓詩外傳》曰：齊景公之時，民有得罪者，公怒，縛置殿下，召左右，支解之，晏子左手持頭，右手磨刀而問曰：古明王聖主，支解人從何支始，景公離席曰：縱之，罪在寡人。","sortOrder":16},
  {"id":"s_work_nvlt_24_17","chapterId":"ch_work_nvlt_24","text":"《東方朔傳》曰：人有煞上林鹿者，武帝下有司煞之，東方朔曰：是人固當死者三，使陛下以鹿之故煞人，一當死也，使天下聞之，皆以陛下為重鹿賤人，二當死也，匈奴即有急，推鹿觸之，三當死也，武帝嘿然，遂赦之。","sortOrder":17},
  {"id":"s_work_nvlt_24_18","chapterId":"ch_work_nvlt_24","text":"孔藂子曰：陳惠侯大城，因起陵陽之台，未終而坐法死者數十人。又執二監吏，將煞之，孔子適陳，聞之，見陳侯，與俱登台而觀焉，孔子曰：美哉斯台，自古聖王為城台，未有不戮一人而致功若此者也，陳侯默，赦所執吏。","sortOrder":18},
  {"id":"s_work_nvlt_24_19","chapterId":"ch_work_nvlt_24","text":"《新序》曰：趙簡子上羊關阪，群臣皆偏裼推車，而唐會擔戟行歌，簡子曰：寡人上阪，群臣推車，會獨行歌，不推車，是會為臣而侮其主，其罪何若，對曰：臣侮主之罪當死，死者身死妻子為戮也，君雖聞為臣侮主之罪，君亦聞為人君而侮其臣者乎，簡子曰：何若為侮其臣者乎，對曰：智者不為謀，辯者不為使，勇者不為斗，夫智者不為謀，則社稷危，辯者不為使，則指事不通，勇者不為斗，則邊境侵，三者不使，則君難保，簡子乃罢推車。","sortOrder":19},
  {"id":"s_work_nvlt_24_20","chapterId":"ch_work_nvlt_24","text":"又曰：魏文侯與大夫坐，問曰：寡人何如君也，群臣皆曰：君仁君也，次問翟黃，曰：君非仁君也，曰：子何以言之，對曰：君伐中山，不以封君之弟，而以封君之長子，曰以是知君之非仁君也，文侯怒而逐翟黃，翟黃趍而出，次任坐，坐對曰：君仁君也，曰：子何以言之，對曰：臣聞之，其君仁者其臣直，向翟黃之言直，臣是以知君仁君也，文侯曰：善，复召翟黃。","sortOrder":20},
  {"id":"s_work_nvlt_24_21","chapterId":"ch_work_nvlt_24","text":"《說苑》曰：趙簡子舉兵伐齊，有被甲士申護笑，簡子曰：子何笑，對曰：臣乃有宿笑，當桑之時，臣鄰家父與妻俱之田，見桑中女，因追之，不能得，還反，其妻怒而去之，臣笑其曠也，簡子曰：今吾伐國失國，是吾曠也，還師而歸。","sortOrder":21},
  {"id":"s_work_nvlt_24_22","chapterId":"ch_work_nvlt_24","text":"又曰：齊桓公逐鹿入穀，見一老公，問是為何穀，對曰：為愚公穀，以臣名之，桓公曰：视公儀状非愚人，何為以公名之，對曰：臣故畜牸牛生子，大賣之而買駒，少年曰：牛不能生馬，遂持駒去，傍鄰以臣為愚，故名愚公，管仲再拜曰：此夷吾之過也，使尧在上，咎繇為理，安有取駒者乎。","sortOrder":22},
  {"id":"s_work_nvlt_24_23","chapterId":"ch_work_nvlt_24","text":"又曰：吳王欲伐荆，舍人少孺子欲諫，不敢，則懷丸操彈，遊於後園，露沾其衣，王曰：何沾衣如此，對曰：榆上有蝉，高居悲鳴，不知螗螂在後，螗螂委身欲取蝉，不知黃雀在其傍，黃雀延頸欲啄螗螂，而不知彈丸在其下，此三者皆務欲得其利，而不顧其後患也，王曰：善哉，乃罢兵。","sortOrder":23},
  {"id":"s_work_nvlt_24_24","chapterId":"ch_work_nvlt_24","text":"《蜀志》曰：天旱，禁酒酿者，刑吏於人家索得酿具，欲令與作酒者同罰，簡雍從先主遊，見一男子行道，謂先主，彼人欲淫，何以不縛，先主曰：卿何以知之，雍曰：彼有淫具，與欲酿者同，先主大笑，而原欲酿者。","sortOrder":24},
  {"id":"s_work_nvlt_24_25","chapterId":"ch_work_nvlt_24","text":"世記［《太平御覽》八百三十二作說。］曰：桓玄好獵，纴兔騰逸，參佐無不被系，桓道恭常自帶綿絳繩，著腰中，玄問用此何為，答，玄獵好縛人士，會被縛，手不能堪痛也，玄自此小差。","sortOrder":25},
  {"id":"s_work_nvlt_24_26","chapterId":"ch_work_nvlt_24","text":"【詩】漢韦孟諷諫詩序曰：孟為元王傅。又傅子夷王，及孫王戊，荒淫不遵道，孟作詩諷諫曰：肅肅我祖，國自豕韦，黼衣朱绂，四牡龍旂，彤弓斯征，撫寧遐荒，總齊群邦，以翼大商，迭彼大彭，勋績惟光，至於有周，歷世會同，王赧聽谮，寔絕我邦，悠悠嫚秦，上天不寧，乃睠南顧，授漢於京，乃命厥弟，建侯於楚，俾我小臣，惟傅是辅，兢兢元王，恭俭靜壹，惠此黎民，納彼辅弼，爰及夷王，克奉厥緒，咨命不永，惟王統祀，如何我王，不思守保，不惟履冰，以繼祖考，邦事是废，逸遊是娱，人馬悠悠，是放是驅，所弘匪德，所親匪俊，唯囿是恢，唯諛是信，嗟嗟我王，漢之睦親，曾不夙夜，以休令聞。","sortOrder":26},
  {"id":"s_work_nvlt_24_27","chapterId":"ch_work_nvlt_24","text":"魏應璩百一詩曰：年命在桑榆，東嶽與我期，長短有常會，遲速不得辭，斗酒當為樂，無為待來茲，室廣致凝陰，台高來積陽，奈何季世人，侈靡在宮牆，飾巧無窮極，土木被朱光，徵求傾四海，雅意猶未康。","sortOrder":27},
  {"id":"s_work_nvlt_24_28","chapterId":"ch_work_nvlt_24","text":"【賦】楚荀况賦曰：天下不治，請陳佹詩，天地易位，四時易乡，列星陨墜，旦暮晦冥，幽暗登照，日月下藏，公正無私，見謂縱橫，志愛公私，重樓疏堂，道德純備，讒口將將，仁人诎約，敖暴擅強，天下幽险，怨失世殃，龟龍為蝘蜓，鴟枭為鳳皇，比幹見剖，孔子拘匡，昭昭乎其智之明也，鬱鬱乎其遇時不祥也，拂乎其欲禮義之大行也，暗乎天下之晦盲也，璇玉瑤琳，不知佩也，雜布與綿，不知異也，闾娵子奢，莫之媒也，嫫母力父，莫［荀子賦篇作是。］之喜也，以盲為明，以聋為聰，以危為安，以吉為凶，呜呼上天，曷惟其同。","sortOrder":28},
  {"id":"s_work_nvlt_24_29","chapterId":"ch_work_nvlt_24","text":"楚宋玉諷賦曰：楚襄王時，宋玉休歸，唐勒讒之於王曰：玉為人，身體容冶，內多微辭，出愛主人之女，入事大王，原王疏之，玉休還，王謂玉曰：出愛主人之女，入事寡人，不亦薄乎，玉曰：臣嘗出行，仆飢馬疲，主人之女，翳承日之華，披翠雲之裘，更被白縠之单衫，垂珠步搖，來排臣戶，為臣炊彫胡之飯，烹露葵之羹，以其翡翠之釵，掛臣冠纓，為臣歌曰：歲將暮兮日已寒，中心亂兮勿多言，臣复援琴為秋竹積雪之曲，主人女又為臣歌曰：怵惕心兮徂玉床，橫自陳兮君之傍，君不御兮妾誰怨，日將至兮下黃泉。","sortOrder":29},
  {"id":"s_work_nvlt_24_30","chapterId":"ch_work_nvlt_24","text":"又釣賦曰：宋玉與登徒子偕受釣於玄泉，止而併見於楚襄王，登徒子曰：夫玄泉天下之善釣者也，以三尋之竿，八絲之線，以出三尺之魚於數仞之中，可謂無術乎，襄王曰：善，宋玉進曰：今玄泉釣。又焉足為大王言乎，王曰：子所謂善釣者何，玉曰：善釣者，其竿非竹，其纶非絲，其鉤非針，其餌非螾也，王曰：原遂聞之，宋玉曰：昔尧舜禹湯之釣也，以聖賢為竿，道德為纶，仁義為鉤，利人為餌，四海為池，萬民為魚，其釣道微也，非聖孰能察之，王曰：釣未可見也，宋玉曰：其釣易見，昔殷湯以七十里，興利除害，天下歸之，其餌可謂芳矣，南面以掌天下，歷載數百，到今不废，其纶可謂多幼［古文苑二作纫。］矣，群生浸其泽，民氓畏其罰，其釣可謂善矣，功成而不墜，名立而不改，其竿可謂強矣，夫竿折纶絕，餌墮釣决，魚失，則夏桀，殷紂不通夫釣術也。","sortOrder":30},
  {"id":"s_work_nvlt_24_31","chapterId":"ch_work_nvlt_24","text":"晉陆機豪士賦曰：夫立德之基有常，而建功之路不一，何則，修心以為量者在乎我，因物以成務者系乎彼，存夫我者，隆殺止乎其域，系乎物者，丰約唯所遭遇，落葉候微飆以陨，而風之力蓋寡，孟嘗遭雍門以泣，而琴之感以末，何哉，欲陨之葉，無所假烈風，將墜之泣，不足繁哀响也，苟時啟於天，理盡於民，庸夫可以濟聖賢之功，斗筲可以定烈士之業，故曰：才未半古，功已倍之，蓋得之於時势也，歷觀古今，徼一時之功，而居伊周之位者，有矣，夫我之自我，智士猶婴其累，物之相物，崑虫皆有此情，豈識乎功在身外，任出才表者哉，眾心日侈，危機將發，而方偃仰瞪盻，謂足以夸世，笑古人之未工，忘己事之已拙，然後河海之跡，堙為窮流，一匮之衅，積成山嶽，豈不谬哉，故聊賦焉，世有豪士兮，遭國顛沛，攝窮運之歸期，當眾通之所會，苟時至而理盡，譬摧枯與振败，因天地以運動，恒才璅而功大，於是禮極上典，服盡暉崇，儀北辰以葺宇，實蘭室而桂宮，撫玉衡於枢極，運萬物乎掌中，伊天道之刚健，猶時至而必愆，日罔中而弗昃，月何盈而不闕，袭覆車之危軌，笑前乘之未完，若知险而退止，趍歸蕃而自戢，推璇璣以長謝，顧萬邦而高揖，讬浮雲以邁志，豈咎吝之能集，挤為山以自陨，叹禍至於何及。","sortOrder":31},
  {"id":"s_work_nvlt_24_32","chapterId":"ch_work_nvlt_24","text":"【論】魏陳王曹植令禽惡鳥［《太平御覽》九百二十三作貪惡鳥論。］曰：國人有以伯勞生獻者，王召見之，侍臣曰：世同惡伯勞之鳴，敢問何謂也，王曰：昔尹吉甫用後妻之讒，煞孝子伯奇，吉甫後悟，追傷伯奇，出遊於田，見鳥鳴於桑，其聲噭然，吉甫動心曰：伯奇乎，鳥乃撫翼，其音尤切，吉甫乃顧曰：伯勞乎，是吾子，栖吾舆，吾［《太平御覽》吾上有非字，此脱。］子，飛勿居，鳥尋聲而栖於蓋，吉甫遂射煞後妻以謝之，故俗惡伯勞之鳴，言所鳴之家，必有尸也，此好事者附名為之說，而今普傳惡之，其實否也，伯勞以五月而鳴，應陰氣之動，陰為賊害，蓋賊害之鳥也，其聲鵙鵙然，故俗憎之，若其為人灾害，愚民之所信，通人之所略也，鳥鳴之惡自取憎，人言之惡自取滅，不能有累於當世也，而凶人之行弗可易，枭鵙之鳴弗可更者，天性然也，昔荆之枭，將巢於吳，鳩遇之曰：何去荆而巢吳乎，枭曰：荆人惡予之聲，鳩曰：子如不能革子之音，則吳楚之民，不易情也，為子計者，莫若宛頸戢翼，終身勿复鳴也，昔會朝議者，有人問曰：寧有聞枭食其母乎，有答之者曰：嘗聞乌反哺，未聞枭食其母也，問者慚唱不善也，得蟢者莫不馴而放之，為利人也，得蚤者莫不糜之齒牙，為害身也，鳥獸崑虫，猶以名聲見異，况夫吉士之與凶人乎。","sortOrder":32},
  {"id":"s_work_nvlt_24_34","chapterId":"ch_work_nvlt_24","text":"《周官》曰：保氏掌諫王惡。","sortOrder":34},
  {"id":"s_work_nvlt_24_35","chapterId":"ch_work_nvlt_24","text":"《禮記》曰：為人臣禮不顯諫，三諫而不聽，則逃之，子之事親也，三諫而不從，則號泣而隨之。","sortOrder":35},
  {"id":"s_work_nvlt_24_36","chapterId":"ch_work_nvlt_24","text":"《左傳》曰：公將如棠觀魚者，臧僖伯諫曰：凡物不足以講大事，其材不足以備器用，則君不舉焉，故春蒐夏苗，狄狝冬狩，皆於農隙以講事也，若夫山林川泽之實，器用之資，皂隸之事，官司之守，非君所及也，公曰：吾將略地焉，遂往陳魚而觀之，僖伯稱疾不從。","sortOrder":36},
  {"id":"s_work_nvlt_24_37","chapterId":"ch_work_nvlt_24","text":"又曰：宋華父督以郜大鼎賂公，納於太廟，非禮也，臧哀伯諫曰：君人者，將昭德塞违，以臨照百官，猶懼或失之，故昭令德以示子孫，百官於是乎戒懼，而不敢易紀律，今滅德立违，而寘其賂器於太廟，以明示百官，百官象之，其又何誅焉，國家之败，由官邪也，官之失德，寵賂彰也，郜鼎在廟，彰孰甚焉。","sortOrder":37},
  {"id":"s_work_nvlt_24_38","chapterId":"ch_work_nvlt_24","text":"又曰：晉侯假道於虞以伐虢，宮之奇諫曰：虢，虞之表也，虢亡，虞必從之，晉不可啟，寇不可玩，一之謂甚，其可再乎，諺所謂辅車相依，唇亡齒寒者，虞虢之謂也，［事具武部戰伐篇。］","sortOrder":38},
  {"id":"s_work_nvlt_24_39","chapterId":"ch_work_nvlt_24","text":"又曰：晉師為楚所败，既歸，荀桓子請死，晉侯欲許之，士貞子諫曰：不可，林父之事君也，進思盡忠，退思補過，社稷之衛也，若之何煞之，夫其败也，如日月之食焉，何損於明，晉侯使复其位。","sortOrder":39},
  {"id":"s_work_nvlt_24_40","chapterId":"ch_work_nvlt_24","text":"《論語》曰：事父母幾諫。","sortOrder":40},
  {"id":"s_work_nvlt_24_41","chapterId":"ch_work_nvlt_24","text":"《逸禮》曰：衛史鰌病且死，謂其子曰：我死，治丧於北堂，吾生不能進蘧伯玉而退弥子瑕，是不能正君也，生不能正君者，死不當成禮，死而置尸於北堂，於我足矣，靈公往弔，問其故，其子以父言聞於靈公，公失容曰：吾失矣，立召蘧伯玉而貴之，召弥子瑕而退之，徙丧於堂，成禮而後去。","sortOrder":41},
  {"id":"s_work_nvlt_24_42","chapterId":"ch_work_nvlt_24","text":"《晏子》曰：景公有所愛槐，令吏守之，令犯槐者死，有過而犯之者，君令吏收而拘之，將加罪焉，晏子明日早朝，諫曰：君窮民财力，繁鍾鼓之樂，極宮室之觀，犯槐者死，刑煞不稱，賊民之深者也，君饗國，德行未見於眾，而刑辟著於國，婴恐其不可以莅國子民也，公曰：善，罢守槐之役，出犯槐之囚。","sortOrder":42},
  {"id":"s_work_nvlt_24_43","chapterId":"ch_work_nvlt_24","text":"又曰：景公為台，台成。又欲為鍾，晏子諫曰：君今既已筑台矣。又斂於民而為鍾，則民必哀矣，斂民哀以為樂，不祥，非所以君民也，公乃止。","sortOrder":43},
  {"id":"s_work_nvlt_24_44","chapterId":"ch_work_nvlt_24","text":"又曰：景公畋，十有八日而不反，晏子往見公，比至，衣冠盡不正，望遊而馳，公見，逆勞曰：夫子何為遽，國家得無有故乎，晏子對曰：無恙也，雖然，婴原有复也，國人皆以君安野而不安國，好獸而惡人，無乃不可乎，公於是罢田，即日歸。","sortOrder":44},
  {"id":"s_work_nvlt_24_45","chapterId":"ch_work_nvlt_24","text":"《呂氏春秋傳》曰：越飢，請食於吳，子胥諫曰：不可與也，夫吳之與越，接土鄰境，道易人通，仇讎敵戰之國，非吳丧越，越必丧吳，今將输之粟，是長吾仇讎，财匮民怨，悔無及也，吳王不從，後吳飢，請食於越，越弗與，及攻之，夫差為禽。","sortOrder":45},
  {"id":"s_work_nvlt_24_46","chapterId":"ch_work_nvlt_24","text":"又曰：衛靈公天寒凿池，苑春諫曰：天寒起役，恐傷民，公曰：天寒乎哉，苑春曰：公衣狐裘，坐熊席，是以不寒，今民衣弊不補，民則寒矣，公曰：善，令罢役。","sortOrder":46},
  {"id":"s_work_nvlt_24_47","chapterId":"ch_work_nvlt_24","text":"王孫子《新書》曰：楚莊王攻宋，厨有臭肉，樽有败酒，將軍子重諫曰：今君厨肉臭而不可食，樽酒败而不可飲，而三軍之士，皆有飢色，欲以勝敵，不亦難乎，莊王曰：善。","sortOrder":47},
  {"id":"s_work_nvlt_24_48","chapterId":"ch_work_nvlt_24","text":"又曰：衛靈公坐重華之台，侍御數百，隨珠照日，羅衣從風，仲叔敖入諫曰：昔桀紂行此而亡，今四境內侵，諸侯加兵，土地日削，百姓乖離，今君內寵，無乃太盛欤，靈公再拜曰：寡人過矣，微子之言，社稷幾傾，於是出宮女之不進者數百人，百姓大悅。","sortOrder":48},
  {"id":"s_work_nvlt_24_49","chapterId":"ch_work_nvlt_24","text":"《史記》曰：趙肅侯遊大陆，出於鹿門，大戊午扣馬曰：耕事方急，一日不作，百日不食，肅侯下車而謝之。","sortOrder":49},
  {"id":"s_work_nvlt_24_50","chapterId":"ch_work_nvlt_24","text":"又曰：始皇長子扶蘇諫曰：天下初定，遠方黔首未集，今皆重法繩之，臣恐天下不安，唯上察之，始皇怒，使扶蘇北監蒙恬於上郡。","sortOrder":50},
  {"id":"s_work_nvlt_24_51","chapterId":"ch_work_nvlt_24","text":"又曰：沛公入秦宮，宮室帏帳重室，狗馬婦女以千數，意欲留居之，張良諫曰：夫秦為無道，故沛公得至此，夫為天下除殘賊，宜縞素為資，今始入秦，即安其樂，此所□□□［史記留侯世家作謂助桀三字。］為虐也，且忠言逆耳利於行，良藥苦口利於病，沛公乃還軍灞上。","sortOrder":51},
  {"id":"s_work_nvlt_24_52","chapterId":"ch_work_nvlt_24","text":"又曰：高帝欲以趙王如意易太子，叔孫通諫曰：太子仁孝，天下皆聞之，呂後與陛下攻苦食淡，其可背哉，必欲废適而立少，臣原先伏誅，以頸血汙地，帝曰：公罢矣，吾特戲耳，叔孫通曰：太子者，天下根本，本壹搖，天下振動，奈何以天下戲。","sortOrder":52},
  {"id":"s_work_nvlt_24_53","chapterId":"ch_work_nvlt_24","text":"《漢書》曰：郅都，景帝時為中郎，敢言直諫，面折大臣於朝，嘗從上入上林，贾姬在廁，野彘入廁，上目都，都不行，上欲自持兵救贾姬，都伏上前曰：一姬死，复一姬進，天下所少，寧贾姬等乎，陛下縱自輕，奈宗廟太後何，上還，彘亦不傷贾姬，太後聞之嘉，賜都金百斤，上亦賜金百斤。","sortOrder":53},
  {"id":"s_work_nvlt_24_54","chapterId":"ch_work_nvlt_24","text":"又曰：薛廣德敢直言諫爭，上幸甘泉，因留射獵，廣德上書曰：竊見關東困極，民人流離，陛下日撞亡秦之鍾，聽鄭衛之樂，臣誠悼之，今士卒暴露，從官勞倦，原陛下亟反宮，思與百姓同忧樂，天下幸甚，上即日還。","sortOrder":54},
  {"id":"s_work_nvlt_24_55","chapterId":"ch_work_nvlt_24","text":"又曰：梅福上書諫成帝曰：天下之士民，有上書求見者，辄使詣尚書，問其所言諫，可采取者，秩以斗升之祿，賜以一束之帛，若此，則天下之士，發憤懣，吐忠言，嘉謀日聞於上，天下之條貫，國家之表里，烂然可睹矣。","sortOrder":55},
  {"id":"s_work_nvlt_24_56","chapterId":"ch_work_nvlt_24","text":"又曰：哀帝時，杜钦諫曰：臣聞曰：非仁無以廣施，非義無以正身，今漢承周秦之弊，宜抑文尚质，表實去伪，臣竊有所忧，言之拂心逆耳，不言則漸日長禍不細。","sortOrder":56},
  {"id":"s_work_nvlt_24_57","chapterId":"ch_work_nvlt_24","text":"《說苑》曰：楚莊王筑層台，延石千重，延壤百里，諫者七十二人皆死矣，有諸御已入諫莊王曰：昔虞不用宮之奇，而晉併之，曹不用僖負羁，而宋併之，吳不用子胥，而越併之，桀煞關龍逢，而湯得之，紂煞比幹，而武王得之，遂趍出，王遽追之曰：吾用子之諫，先日說寡人者，不足動寡人之心，故皆至死，明日出令，有能入諫者，吾與為兄弟，废層台，罢民。","sortOrder":57},
  {"id":"s_work_nvlt_24_58","chapterId":"ch_work_nvlt_24","text":"又曰：晏子复於景公曰：朝居嚴乎，公曰：朝居嚴則曷害於治國家哉，晏子對曰：朝居嚴則下無言，下無言則上無聞矣，下無言則謂之喑，上無聞則謂之聋，聋喑則非害治國家如何，且合升斗之穀，以滿仓廪，泰山之高，非一石也，累卑然後高也，夫治天下者，非用一士之言也。","sortOrder":58},
  {"id":"s_work_nvlt_24_59","chapterId":"ch_work_nvlt_24","text":"又曰：楚莊王立，三年不聽朝，令於國曰：寡人惡為人臣諫其君者，今寡人有國家，立社稷，有諫即死無赦，蘇縱曰：處君之高爵，食君之厚祿，愛死而不諫，則非忠臣也，乃諫莊王，立鍾鼓之間，王左伏楊姬，右擁成姬曰：吾鍾鼓不暇，何諫之聽，縱曰：臣聞之，好樂者迷，荆國亡無日矣，王曰：善，左執縱手，右抽佩刀，刎鍾鼓之懸，明日授縱為相。","sortOrder":59},
  {"id":"s_work_nvlt_24_60","chapterId":"ch_work_nvlt_24","text":"又曰：晉靈公造九層台，費用千亿，謂左右曰：敢有諫者斬，孫息乃諫曰：臣能累十三博棋，加九雞子其上，公曰：吾少學，未嘗見也，子為寡人作之，孫息即以棋子置其下，加九雞子其上，左右慴懼，靈公扶伏，氣息不續，公曰：危哉危哉，孫息曰：臣謂是不危也，复有危此者，公曰：原見之，孫息曰：九層之台，三年不成，男不得耕，女不得織，國用空虛，戶口减少，吏民叛亡，鄰國謀議將興兵，社稷一滅，君何所望，靈公曰：寡人之過，乃至於此，即坏九層之台。","sortOrder":60},
  {"id":"s_work_nvlt_24_61","chapterId":"ch_work_nvlt_24","text":"《漢武帝故事》，汲黯諫上曰：陛下愛才樂士，求之無倦，比得一人，勞心苦神，未盡其用，辄已煞之，以有限之士，資無已之誅，陛下欲誰與為治乎。","sortOrder":61},
  {"id":"s_work_nvlt_24_62","chapterId":"ch_work_nvlt_24","text":"《東觀漢記》曰：張堪為光祿大夫，數諫，堪常乘白馬，上每有異政，辄言白馬生且复諫矣，［事具職部光祿篇。］","sortOrder":62},
  {"id":"s_work_nvlt_24_63","chapterId":"ch_work_nvlt_24","text":"謝承《後漢書》曰：陳蕃諫桓帝曰：當今之世，有三空，田野空，朝廷空，仓库空，是謂三空，加之兵戎未戢，四方離散，是陛下焦心毀顏，坐而待旦之時也，豈宜扬旗曜武，騁心舆馬之觀乎。","sortOrder":63},
  {"id":"s_work_nvlt_24_64","chapterId":"ch_work_nvlt_24","text":"《汝南先賢傳》曰：建武八年，車駕西征隗嚣，郭憲諫曰：天下初定，車駕未可以動，憲乃當車，拔佩刀以斷車靷，帝不從，遂上隴，其後潁川兵起，乃回駕而還，帝叹曰：恨不用郭憲之言。","sortOrder":64},
  {"id":"s_work_nvlt_24_65","chapterId":"ch_work_nvlt_24","text":"《魏略》曰：太祖欲征吳而雨霖，三軍多不原行，太祖知其然，恐外有諫者，教曰：今雖戒嚴，未知所之，有諫者死，贾逵乃諫，太祖怒，收逵送獄。","sortOrder":65},
  {"id":"s_work_nvlt_24_66","chapterId":"ch_work_nvlt_24","text":"《魏志》：辛毗能直諫，文帝踐祚，為侍中，帝欲徙冀州十萬戶實河南，時連蝗民飢，毗與朝臣俱求見，帝知其欲諫，作色以見之，皆莫敢言，毗曰：陛下欲徙家，其計安出，帝曰：卿謂我徙之非耶，毗曰：誠以為非也，帝曰：吾不與卿共議也，帝起入內，毗隨而引其裾，帝遂奋衣不還，良久乃出曰：卿持我何太急耶。","sortOrder":66},
  {"id":"s_work_nvlt_24_67","chapterId":"ch_work_nvlt_24","text":"《吳志》曰：孫權既為吳王，歡宴之末，自起行酒，虞翻伏地佯醉，不待權去，翻起坐，權於是大怒，手劍欲击之，侍坐者莫不惶遽，唯大司農劉基起抱權諫曰：大王以三爵後煞善士，雖翻有罪，天下孰知之，且大王以能容賢，故海內望風，今一朝弃之，可乎，翻由是得免。","sortOrder":67},
  {"id":"s_work_nvlt_24_68","chapterId":"ch_work_nvlt_24","text":"【表】魏陳王曹植諫伐遼東表曰：臣伏以遼東負岨之國，势便形固，帶以遼海，今輕軍遠攻，師疲力屈，彼有其備，所謂以逸待勞，以飽製飢者也，以臣觀之，誠未易攻也，若國家攻而必剋，屠襄平之城，懸公孫之首，得其地，不足以偿中國之費，虜其民，不足以補三軍之失，是我所獲，不如所丧也，若其不拔，曠日持久，暴師於野，然天時難测，水濕無常，彼我之兵，連於城下，進則有高城深池，無所施其功，退則有歸涂不通，道路瀸洳，東有待衅之吳，西有伺隙之蜀，吳起東南，則荆楊骚動，蜀應西境，則雍涼參分，兵不解於外，民罢困於內，促耕不解其飢，疾蠶不救其寒，夫渴而後穿井，飢而後殖种，可以圖遠，難以應卒也，臣以為當今之務，在於省徭役，薄賦斂，勸農桑，三者既備，然後令伊管之臣，得施其術，孫吳之將，得奋其力，若此則泰平之基，可立而待，康哉之歌，可坐而聞，曾何忧於二敵，何懼於公孫乎，今不恤邦畿之內，而勞神於蠻貊之域，竊為陛下不取也。","sortOrder":68},
  {"id":"s_work_nvlt_24_69","chapterId":"ch_work_nvlt_24","text":"齊竟王陵上谠言表曰：臣聞明台既辟，承雲之歌闡，衢室爰啟，南風之頌流，莫非降道爝煇，紆靈浸泽，陛下凝慶协圖，席昌屬歷，乾臨冬暧，海鏡春亭，選議釣俗，觀風調紀，垂聽革之典，降聆金之訓，用能詩史無輟，工頌有聞，是故置四辅，立七諫，正國度，箴王闕，臣謂當今，宜崇諫司，专事昭塞，職蹈謇諤，績宣王文，則優其寵秩，厚其節禮，庶獻鮮之美，方高聖代，至乃靡衣媮食，曾宇雕墉，商貿浮侈，田萊芜替，棫朴爽流，摽梅失序，勉民觀俗之宜，設官立事之要，隨闕興規，袞废能補，如此則壤詠無遠，轅樂可追。","sortOrder":69},
  {"id":"s_work_nvlt_24_70","chapterId":"ch_work_nvlt_24","text":"【書】秦李斯上書諫始皇曰：臣聞吏議逐客，竊以為過矣，昔者穆公求士，西取由餘於戎，東得百里奚於宛，迎蹇叔於宋，來丕豹公孫支於晉，此五子者，不產於秦，穆公用之，併國二十，遂霸西戎，惠王用張儀之計，拔三川之地，西併巴蜀，北收上郡，南取漢中，苞九夷，製鄢郢，東據成皋之险，割膏腴之壤，散六國之從，使之西面事秦，功施到今，昭王得范睢，废穰侯，逐華陽，強公室，杜私門，蠶食諸侯，使秦成帝業，皆以客之功，由此觀之，客何負於秦哉，今陛下致崑山之玉，有隨和之寶，垂明月之珠，服太阿之劍，乘纖離之馬，建翠鳳之旗，树靈鼍之鼓，此數寶者，秦不產一焉，而陛下悅之，必秦國之所生然後可，則是夜光之璧，不飾朝廷，犀象之器，不為玩好，而駿馬駃騠，不實外廄，所以飾後宮，充下陳，娱心意，悅耳目者，必出於秦然後可，則是宛珠之簪，錦繡之飭，不進於前，而趙女不立於侧也，所重者在乎色樂，而所輕者在乎人民，此非所以夸海內也。","sortOrder":70},
  {"id":"s_work_nvlt_24_71","chapterId":"ch_work_nvlt_24","text":"漢邹陽上書諫吳王曰：臣聞蛟龍驤首奋翼，則浮雲出流，霧雨成集，聖王砥節脩德，則遊談之士，歸義思名，今臣盡智畢議，易精極慮，則無國而不可幹，飾固陋之心，則何王之門，不可曳裾乎，然臣歷數王之朝，背淮千里而自致者，非惡臣國而樂吳民也，竊高下風之行，尤悅大王之義，故原大王無忽，察聽其至，夫全趙之時，武力鼎士，袨服藂台之下者，一旦成市，不能止幽王之沆患，淮南連山東之俠，死士盈朝，不能還厲王之西也，然則計議不得，雖諸贲不能安其位，亦明矣，今漢據全秦之地，兼六國之眾，大王之所明知也，今夫諂諛之臣，為大王計者，不論骨肉之義，民之輕重，國之大小，以為吳禍，此臣所以為大王患也，夫舉吳兵以訾於漢，譬猶蠅蚋之附群牛，腐肉之齒利劍，鋒接必無矣。","sortOrder":71},
  {"id":"s_work_nvlt_24_72","chapterId":"ch_work_nvlt_24","text":"漢枚乘上書諫吳王曰：得全者昌，失全者亡，舜無立錐之地，以有天下，禹無十戶之聚，以王諸侯，湯武之土，不過百里，上不絕三光之明，下不傷百姓之心者，有王術也，忠臣不避重誅以直諫，則事無遺策，功流萬世，夫以一縷之任，系千鈞之重，上懸之無極之高，下垂之不测之深，雖甚愚之人，猶知哀其將絕也，人性有畏其影而惡其跡者，却背而走，足跡愈多，影愈疾，不知就陰而止，影滅而跡絕，欲人勿聞，莫若勿言，欲人勿知，莫若勿為，福生有基，禍生有胎，納其基，絕其胎，禍何自來，夫銖銖而稱之，至石必差，寸寸而度之，至丈必過，磨砻砥砺，不見其損，有時而盡，种树畜養，不見其益，有時而大，積德累行，不知其善，有時而用，弃義背理，不知其惡，有時而亡，楚有子玉得臣，晉文為之侧席而坐，趙有廉頗馬服，強秦不敢窥兵，昔白起為秦將，南伐郢都，北坑趙括，以纖介之過，賜死杜郵，秦民怜之，莫不陨涕。","sortOrder":72},
  {"id":"s_work_nvlt_24_73","chapterId":"ch_work_nvlt_24","text":"漢司馬相如上書諫武帝曰：物有同類而殊能者，故力稱乌獲，捷言慶忌，勇期贲育，臣之愚暗，竊以為人誠有之，獸亦宜然，今陛下好凌阻险，射猛獸，卒然遇軼材之獸，駭不存之地，犯屬車之清尘，舆不及還轅，人不暇施巧，雖有乌獲逢蒙之伎力，不得施用，枯木朽株，盡為難矣，夫輕萬乘之重，不以為安，而樂出萬有一危之涂以為娱，臣竊為陛下不取也，蓋明者遠見於未萌，而智者避危於無形，禍固多藏於隱微，而發於人所忽也，鄙諺曰：家累千金，坐不垂堂，此言雖小，可以喻大。","sortOrder":73},
  {"id":"s_work_nvlt_24_74","chapterId":"ch_work_nvlt_24","text":"【序】梁元帝忠臣傳諫爭篇序曰：富貴寵榮，人所不能忘也，刑戮流放，人所不能甘也，而士有冒雷霆，犯顏色，吐一言終，知自投鼎镬，取離刀鋸，而曾不避者，其故何也，蓋傷茫茫禹跡，毀於一朝，赫赫宗周，滅成禾黍，何者，百世之後，王化漸頹，钦若之信既盡，解網之仁已泯，徒以繼體所及，守器攸歸，出則清警傳路，處則凭玉負扆，事無蹔舛，意有必從，所謂生於深宮之中，長於婦人之手，未嘗知忧，未嘗知懼，况惑裒人之巧笑，迷陽阿之妙舞，重之以刳斮，囚之以逋逃，亦有傾天滅地，汙宮潴社之罪，拔本塞源，裂冠毀冕之衅，於是策名委质，守死不二之臣，以刚腸疾惡之心，確乎貞一之性，不忍見霜露麋鹿，栖於宮寢，麥穗黍離，被於宗廟，故瀝血抽誠，披胸見款，赴燋烂於危年，甘滅亡於昔日，冀桐宮有返道之明，望夷無不言之恨，而九重懸遠，百雉嚴絕，丹心莫亮，白刃先指，見之者掩目，聞之者傷心，然後鳴條有不收之魂，商郊致白旗之戮。","sortOrder":74},
  {"id":"s_work_nvlt_24_75","chapterId":"ch_work_nvlt_24","text":"【論】漢東方朔非有先生論曰：非有先生仕於吳，進不能稱往古以廣主意，退不能扬君美以顯其功，吳王怪而問之，先生曰：談何容易，夫談者，有悖於目而拂於耳，谬於心而便於身，或有悅於目，順於耳，快於心，而毀於行者，非有明王聖主，孰能聽之，吳王曰：何為其然也，先生對曰：昔關龍逢深諫於桀，而王子比幹直言於紂，此二臣者，直言其失，切諫其邪，將以為君之榮，除主之禍也，今則不然，反以為誹謗君之行，無人臣之禮，戮及先人，為天下笑，故曰：談何容易，故養寿命之士，莫肯進也，遂居深山之間，積土為室，編蓬為戶，彈琴其中，以詠先王之風，亦可以樂而忘死矣。","sortOrder":75},
  {"id":"s_work_nvlt_24_76","chapterId":"ch_work_nvlt_24","text":"漢穀永與王音書曰：夫上德厚則下愛深，下愛深則其謀忠，其言至，昔善將國者不忘危，善養生者不讳死，以忠臣直友，明史良医，靈蓍信龟，鹹得盡忠正言，不蔽兆占，故能遷咎延譽，轉禍為福。","sortOrder":76},
  {"id":"s_work_nvlt_24_77","chapterId":"ch_work_nvlt_24","text":"《藝文類聚》　唐·欧陽詢","sortOrder":77},
  {"id":"s_work_nvlt_25_1","chapterId":"ch_work_nvlt_25","text":"卷二十五人部九","sortOrder":1},
  {"id":"s_work_nvlt_25_2","chapterId":"ch_work_nvlt_25","text":"○說嘲戲","sortOrder":2},
  {"id":"s_work_nvlt_25_4","chapterId":"ch_work_nvlt_25","text":"《左傳》曰：晉侯秦伯围鄭，佚之狐言於鄭伯曰：國危矣，若使燭之武見秦君，師必退，燭之武夜縋而出，見秦伯曰：秦晉围鄭，鄭既知亡矣，若亡鄭而有益於君，敢以煩執事，越國以鄙遠，君知其難也，焉用亡鄭以陪鄰，夫晉何厭之有，既東封鄭。又欲肆其西封，不闕秦，焉取之，闕秦以利晉，唯君圖之，秦伯悅。","sortOrder":4},
  {"id":"s_work_nvlt_25_5","chapterId":"ch_work_nvlt_25","text":"又曰：晉郄缺言於趙宣子曰：日衛不睦，故取其地，今已睦矣，可以歸之，叛而不讨，何以示威，服而弗柔，何以示懷，非威非懷，何以示德，無德何以主盟，子為正卿，以主諸侯，而不務德，將若之何，宣子悅之。","sortOrder":5},
  {"id":"s_work_nvlt_25_6","chapterId":"ch_work_nvlt_25","text":"又曰：吳伐楚，入郢，申包胥如秦乞師，曰：吳為封豕長蛇，荐食上國，虐始於楚，寡君失守社稷，越在草莽，使下臣告急曰：夷德無厭，若鄰於君，疆埸之患也，逮吳之未定也，君其取分焉，若以君靈撫之，世以事秦，立依於庭牆而哭，日夜不絕聲，勺飲不入口，七日，秦師乃出。","sortOrder":6},
  {"id":"s_work_nvlt_25_7","chapterId":"ch_work_nvlt_25","text":"又曰：楚子饗魯昭公於新台，好以大屈，既而悔之，薳啟強聞之，見公，公語之，拜贺，公曰：何贺，對曰：齊與晉越，欲此久矣，寡君無適與也，敢不贺乎，公懼，乃反之。","sortOrder":7},
  {"id":"s_work_nvlt_25_8","chapterId":"ch_work_nvlt_25","text":"《戰國策》曰：范睢謂秦王曰：大王之國，北有甘泉穀口，南涇渭，右隴蜀，左關阪，戰車千乘，奋卒數百萬，以秦卒之勇，車騎之多，以當諸侯，譬若放韓盧而逐狡兔也，霸王之業可致，今反閉關，不敢窥兵於山東者，是穰侯為秦謀不忠，大王之計有失也。","sortOrder":8},
  {"id":"s_work_nvlt_25_9","chapterId":"ch_work_nvlt_25","text":"又曰：秦惠王以女為燕太子婦，燕文公卒，齊王因燕丧，攻取十城，蘇秦說齊王，再拜而贺，迎［《太平御覽》四百六十作仰。］而弔，齊王曰：何慶弔相隨之速也，對曰：人之飢所以不食乌喙者，以為雖充腸而與死同患，夫燕雖弱小，強秦之婿也，王利其十城，而與秦為仇，以招天下精兵，此食乌喙之類也，王曰：然則奈何，對曰：王能聽臣，莫如歸燕城，卑辭以謝之，秦知王以己之故歸燕地，必德王，燕無故得十城，燕亦德王，是王弃強仇而立身厚交也，齊王大悅，乃歸燕城。","sortOrder":9},
  {"id":"s_work_nvlt_25_10","chapterId":"ch_work_nvlt_25","text":"又曰：秦王謂趙使者谅貇［戰國策趙策作毅，下同。］曰趙豹平原君，數欺弄寡人，趙能煞此兩人則可，若不能煞，請率諸侯受命邯鄲城下，谅{啓下\"口改月\"}曰：趙豹平原君，親寡君之母弟也，猶大王之有葉［原訛筑，據下文改。］陽君涇陽君，大王以孝悌聞於天下，衣服之便於體，膳啗之兼於口，未嘗不分，舆馬衣裘，無非大王之服，今受大王之嚴令，以報弊邑之君，不敢弗行，無乃傷葉陽君之心乎。","sortOrder":10},
  {"id":"s_work_nvlt_25_11","chapterId":"ch_work_nvlt_25","text":"又曰：齊欲伐魏，魏使人謂淳於髡曰：齊欲伐魏，能解魏患，唯先生也，弊邑有寶璧二双，文馬二驷，請致之先生，淳於髡诺，入說齊王曰：楚，齊之仇敵也，魏，齊之與國也，夫伐與國，使仇敵製其餘弊，名丑而實危，為王不取也，齊王曰：善，乃不伐魏。","sortOrder":11},
  {"id":"s_work_nvlt_25_12","chapterId":"ch_work_nvlt_25","text":"又曰：趙且伐燕，蘇代謂惠王曰：今者來過川，蚌方出曝，而鷸喙曰［《太平御覽》四百六十作而鷸啄其肉，蚌掩鷸啄，鷸曰：(又九百四十一引文略同)此有脱文。］今日不雨，明日不雨，蚌將為脯，蚌亦謂鷸曰：今日不出，明日不出，必見死鷸，兩者不肯相舍，漁者得而併禽之，今趙且伐燕，燕趙久相交兵，恐強秦之為漁父也，故原王孰計之，惠王曰：善，乃止。","sortOrder":12},
  {"id":"s_work_nvlt_25_13","chapterId":"ch_work_nvlt_25","text":"又曰：昭陽為楚伐魏，移兵而攻齊，陳軫為齊王使，見昭陽曰：今子貴矣，王非置兩令尹也，臣竊為公譬之，可乎，楚有祠者，錫其舍人酒一卮，舍人相謂曰：數人飲之不足，一人飲之有餘，請畫蛇，先成者飲酒，一人蛇先成，乃左手持卮，右手畫蛇曰：吾能為足，為足未成，一人之蛇成，奪其卮曰：蛇故無足，子安能為之足，遂飲其酒，畫蛇足者終亡其酒，今公攻魏煞將，得八城。又移師欲攻齊，齊畏公甚，公以是名足矣，冠之上非可重也，戰無不勝而不知止者，身且死，爵且偃，猶為蛇足也，昭陽以為然，解軍而歸。","sortOrder":13},
  {"id":"s_work_nvlt_25_14","chapterId":"ch_work_nvlt_25","text":"又曰：衛客事魏王，三年不得見，乃見梧丘先生，許之以百金，先生曰：诺，乃見魏王曰：吾聞秦出兵，未知所之，原王专事秦，無他計，王曰：诺，客趍出，至郭門而反，曰：臣恐王事秦之晚也，夫人於事己者過急，於事人者過缓，今王於事己者缓，安能急於事人，衛客事王，三年不得見，臣以是知王缓也，魏王趍見衛客。","sortOrder":14},
  {"id":"s_work_nvlt_25_15","chapterId":"ch_work_nvlt_25","text":"又曰：蘇秦為楚合從，說韓王曰：夫以韓卒之勇，被堅甲，帶利劍，一人當百，不足雲也，夫以韓卒之劲，與王之賢，乃欲事秦，為天下笑，無過此者，大王事秦，秦必求宜陽成皋，今茲效之，明年又求之，予之則無地以給，不予則弃前功而受後禍，大王之地有盡，而秦之求無厭，以有盡之地，而應無已之求，鄙語曰：寧為雞口，不為牛後，今西面交臂而事秦，何異牛後乎。","sortOrder":15},
  {"id":"s_work_nvlt_25_16","chapterId":"ch_work_nvlt_25","text":"又曰：秦王與中期爭論而不勝，秦王大怒，中期徐行去，人為中期說秦王曰：此悍人也，中期適遇明君故也，遇桀紂，必殺之矣，王因弗罪。","sortOrder":16},
  {"id":"s_work_nvlt_25_17","chapterId":"ch_work_nvlt_25","text":"《史記》曰：李斯說秦王曰：自孝公以來，周室卑微，諸侯相兼，關東為六國，秦之乘勝役諸侯，蓋六世矣，今諸侯服秦，譬若郡縣，夫以秦之強大，王之賢，由竈上扫除，足以滅諸侯，成帝業矣，今怠而弗急就，諸侯复強，相聚約從，雖有黃帝之賢，弗能併也，秦王聽其計。","sortOrder":17},
  {"id":"s_work_nvlt_25_18","chapterId":"ch_work_nvlt_25","text":"又曰：李左車說成安君陳餘曰：臣聞韓信涉西河，虜魏王，禽夏說，新喋血閼與，今乃辅以張耳，議欲以下趙，此乘勝而遠斗，其鋒不可當，臣聞千里餽糧，士有飢色，今井陉之道，車不得方軌，騎不得成列，其势糧食必在其後，原足下假臣奇兵三萬人，從間道絕其辎重，彼前不得斗，退不得還，吾奇兵絕其後，野無所掠，不至十日，兩將之頭，可致麾下。","sortOrder":18},
  {"id":"s_work_nvlt_25_19","chapterId":"ch_work_nvlt_25","text":"又曰：郦食其說齊王曰：王知天下所歸乎，齊王曰：天下何歸，曰：歸漢，何以言之，曰：漢王與項王戮力西面击秦，約先入鹹陽者王之，項王負約不與，而王之漢中。又遷煞義帝，漢王聞之，起蜀漢之兵，责煞義帝之罪，降城即以侯其將，得賂即以分其士，蜀漢之粟，萬船而下，項羽有背約之名，煞義帝之負，於人之功無所記，於人之罪無所忘，天下之士，歸於漢王，可坐而策，今以據敖仓之粟，塞成皋之险，守白馬之津，杜太行之版，距飛狐之口，天下後服者先亡，王疾下漢王，齊國社稷可得而保，不下漢王，危亡可立而待，乃聽郦生。","sortOrder":19},
  {"id":"s_work_nvlt_25_20","chapterId":"ch_work_nvlt_25","text":"又曰：高祖使陆生賜尉他印，為南越王，陆生進說他曰：足下中國人，親戚崑弟墳墓在真定，今反天性，弃冠帶，欲以區區之越，與天子抗衡，禍且及身也，乃欲以新造未集之越，屈強於此，漢使一偏將，將十萬眾臨越，則越煞王降漢，如反覆手耳，［事具治政部奉使篇。］","sortOrder":20},
  {"id":"s_work_nvlt_25_21","chapterId":"ch_work_nvlt_25","text":"《漢書》曰：項羽击陳留外黃，外黃不下，數月乃降，羽悉令男子年十五以上詣城東，欲坑之，外黃令舍人兒年十三，往說羽曰：彭越強劫外黃，外黃恐，故降待大王，大王至。又皆坑之，百姓豈有所歸心哉，從此以東，梁地十餘城皆恐，莫肯下矣，羽然其言。","sortOrder":21},
  {"id":"s_work_nvlt_25_22","chapterId":"ch_work_nvlt_25","text":"又曰：趙王乃與張耳陳餘，北略地燕界，趙王為燕軍所獲，燕因留之，欲與分地，趙有厮養卒，乃走燕壁問曰：何知臣欲，燕將曰：若欲得王耳，曰：君知張耳陳餘何人也，燕將曰：賢人也，曰：其志何欲，燕將曰：欲得其王耳，趙卒笑曰：君未知兩人所欲也，夫武臣張耳陳餘，杖馬箠下趙數十城，亦各欲南面而王，夫臣之與主，豈可同日道哉，兩人亦欲分趙而王，時未可耳，今兩人名為求王，實欲燕煞之，此兩人分趙而王，夫以一趙尚易燕，况以兩王，右提左挈，而责直義煞王，滅燕易矣，燕以為然，乃歸趙王。","sortOrder":22},
  {"id":"s_work_nvlt_25_23","chapterId":"ch_work_nvlt_25","text":"《東觀漢記》曰：隗嚣既立，使聘平陵方望為軍師，望至，說嚣曰：足下欲承天順民，辅漢而起，今立者乃在南陽，王莽尚據長安，雖欲以漢為名，其實無所受命，將何以見信於眾，宜急立高廟，稱臣奉祠，所謂神道設教，求助民神者也，嚣從其言。","sortOrder":23},
  {"id":"s_work_nvlt_25_24","chapterId":"ch_work_nvlt_25","text":"又曰：隗嚣將王元說嚣曰：昔更始西都，四方响應，天下喁喁，謂之太平，一旦坏败，今南有子陽，北有文伯，江湖海岱，王公十數，而欲牵儒生之說，弃千乘之基，計之不可者也，今天水見富，士馬最強，北取西河，東收三辅，案秦舊跡，表里山河，元請以一丸泥，為大王東封函穀關，此萬世一時也，若計不及此，且畜養士馬，據隘自守，曠日持久，以待四方之变，圖王不成，其弊猶足以霸，嚣然其計。","sortOrder":24},
  {"id":"s_work_nvlt_25_25","chapterId":"ch_work_nvlt_25","text":"又曰：功曹李熊，說公孫述曰：蜀地沃野千里，土壤膏腴，果實所生，無穀而飽，戰士不下百萬，見利則出兵而略地，無利則堅守而力農，東下漢水，以窥秦地，南順江流，以震荆楊，所謂用天因地，成功之資，今名號未定，志士狐疑，宜即大位，使遠人有所依歸，述遂自立為天子。","sortOrder":25},
  {"id":"s_work_nvlt_25_26","chapterId":"ch_work_nvlt_25","text":"又曰：邓禹聞上安集河北，即杖策北渡，追及於鄴，禹進曰：三辅假號，往往群聚，皆庸人崛起，志在财幣，非有忠良明智，深慮遠圖，尊主安民者也，明公雖建蕃辅之功，猶恐無所成立，於今之計，莫如攬延英雄，務悅民心，立高祖之業，救萬民之命，以公慮天下，不足定也，上大悅。","sortOrder":26},
  {"id":"s_work_nvlt_25_27","chapterId":"ch_work_nvlt_25","text":"范晔《後漢書》曰：袁紹奔冀州，董卓購募紹，伍琼說卓曰：袁紹不達大體，恐懼出奔，非有他志，今急購之，势必為变，袁氏树恩四世，門生故吏，遍於天下，若收豪杰以聚徒眾，英雄因之而起，則山東非公之有也，不如赦之，必無患矣，卓以為然。","sortOrder":27},
  {"id":"s_work_nvlt_25_28","chapterId":"ch_work_nvlt_25","text":"又曰：曹公軍至新野，傅巽說劉琮曰：逆順有大體，強弱有定势，以人臣而拒人主，逆道也，以新造之楚，而御中國，必危也，以劉備而敵曹公，不當也，三者皆短，欲以抗王師之鋒，必凶之道也，原將軍勿疑。","sortOrder":28},
  {"id":"s_work_nvlt_25_29","chapterId":"ch_work_nvlt_25","text":"漢晉春秋曰：鍾會陰懷異圖，薑維見而知其心，乃說之曰：聞君自淮南以來，算無遺策，今复定蜀，威德震世，民高其功，而主畏其謀，欲以此安歸乎，夫韓信不背於漢，扰攘而見疑於既平，大夫种不從范蠡於五湖，卒伏劍而妄死，彼豈闇主愚臣哉，利害使之然也，今公何不法陶朱，汎舟絕跡，全功保身，登瓘眉之嶺，而從赤松遊乎，會曰：為全之道，或未盡於此也，維曰：其他則君智力所能盡，無煩老夫矣。","sortOrder":29},
  {"id":"s_work_nvlt_25_30","chapterId":"ch_work_nvlt_25","text":"【書】齊魯仲連與燕將書曰：吾聞之，智者不背時而弃利，勇士不怯死而滅名，忠臣不先身而後君，忠废名滅，後世無稱，非智也，且吾聞效小節者不能行大威，惡小恥者不能立榮名，昔管仲射桓公，中其鉤，篡也，傅公子糾而不死，怯也，束縛桎梏，辱也，三行者，乡里不通，世主弗臣，使管仲終窘抑而不見，窮年没寿，不免為辱人，然而管仲併三行之過，據齊國之政，一匡天下，九合諸侯，使為五伯首，名高天下，光昭鄰國，曹沫為魯君將，三戰而丧地千里，使曹沫計不顧後，即不免為败軍禽將，非勇也，功废名滅，後世無稱，非智也，去三北之恥，以一劍之任，劫桓公於壇上，顏色不变，而辭氣不悖，三戰之所丧，一朝反之，天下振動，名傳後世，若此二公者，非不能行小節，死小恥也，以為煞身絕世，功名不立，非智也，故業與三王爭流，名與天壤相弊也，公其圖之。","sortOrder":30},
  {"id":"s_work_nvlt_25_31","chapterId":"ch_work_nvlt_25","text":"漢司馬相如諭難蜀父老書曰：漢興七十有八載，德茂存乎六世，威武紛紜，湛恩汪濊，群生沾濡，洋溢乎方外，於是乃命使西征，隨流而攘，風之所被，岡不披靡，結軌還轅，東乡將報，至於蜀都，耆老大夫搢紳先生之徒二十有七人，俨然造焉，辭畢進曰：蓋聞天子之牧夷狄也，其義羁縻勿絕而已，今罢三郡之士，通夜郎之涂，三年於茲，而功不竟，今又接之以西夷，百姓力屈，恐不能卒業，此亦使者之累也，使者曰：世必有非常之人，然後有非常之事，有非常之事，然後有非常之功，非常者，固常人之所異也，且夫賢君之踐位也，必將崇論宏議，創業垂統，為萬世規，是以六合之內，八方之外，懷生之倫，靡有不浸润於泽者，賢君恥之，而夷狄殊俗之國，遼絕異党之域，舟車不通，人跡罕至，君臣易位，尊卑失序，號泣內乡而怨曰：蓋聞中國有至仁焉，舉踵思慕，若枯旱之望雨，故乃關沫若，徼〈牜羊〉柯，鏤靈山，梁孫原，創道德之涂，垂仁義之統，以偃甲兵於此，而息讨伐於彼，遐邇一體，中外禔福，不亦康乎，方將增太山之封，鳴和鸞，扬樂頌，上减五，下登三，觀者未睹旨，聽者未聞音，猶鹪鵬已翔乎寥廓之宇，而羅者猶视乎藪泽，於是諸大夫喟然稱曰：允哉漢德，此固鄙人之所原聞也。","sortOrder":31},
  {"id":"s_work_nvlt_25_32","chapterId":"ch_work_nvlt_25","text":"後漢朱浮與彭寵書曰：朝廷之於伯通，恩亦厚矣，委以大郡，任以威武，事有柱石之寄，情同子孫之親，匹夫媵母，尚能致命一餐，豈有身帶三綬，職典大邦，而不顧恩義，生心外叛者乎，伯通與吏民語，何以為顏，行步拜起，何以為容，坐臥念之，何以為心，引鏡闚影，何施眉目，惜乎弃休令之嘉名，造鴟枭之逆謀，捐傳世之慶祚，招破败之重灾，生為世笑，死為愚鬼，不亦哀乎，伯通自伐，以為功高天下，往時遼東有豕，生子白頭，異而獻之，行至河東，見群豕皆白，懷慚而還，若以子之功，論於朝廷，則為遼東豕也。","sortOrder":32},
  {"id":"s_work_nvlt_25_33","chapterId":"ch_work_nvlt_25","text":"後漢冯衍說曰：皇帝聖德靈威，龍興鳳舉，率宛葉之效，摧九虎之軍，雷震四海，席卷天下，攘除禍亂，繼高祖之休烈，修文武之絕業，社稷复存，炎精更辉，德冠往初，功無與二，天下因以去亡新，就聖漢，故易以树恩布德，易於周洽，其猶順驚風而蜚鸿毛，然而諸將滷掠，至乎逆倫絕理，殺人父子，妻人婦女，燔其室屋，殄盡其财產，冤結失望，無所歸命，今大將軍以明淑之德，秉大使之權，統三軍之政，存撫併州之民，惠愛之誠，加乎百姓，高世之聲，聞乎群士，故其延頸舉踵而望者，非特二［後漢書五十八冯衍傳作一。］人也，且大將軍之事，豈得在於珪璧束脩而已哉，將定國家之大業，成天地之元功也，昔周宣中興之主，齊桓霸強之君耳，猶有申伯邵虎，夷吾申［衍傳作吉。］甫，安其疆宇，况乎萬里之漢，明帝复興，而大將軍為之梁棟，此誠不可以忽也，且衍聞之，兵久即力屈，民愁即变生，今邯鄲之賊未滅，真定之际复扰，兵革雲朔，［衍傳作翔。］百姓震駭，奈何自怠，不為深忧乎。","sortOrder":33},
  {"id":"s_work_nvlt_25_34","chapterId":"ch_work_nvlt_25","text":"魏阮瑀為魏武與孫權書曰：每覽古今所由改趣，因緣侵辱，用成大变，若韓信傷心於失楚，彭寵積望於無異，盧綰嫌畏於已隙，英布忧迫於情漏，此事之緣也，孤與將軍，恩如骨肉，而忍絕王命，明弃硕交，不能遠度孤心，近慮事势，遂赍見薄之决計，秉翻然之成議，常思除弃小事，更申前好，二族俱榮，祚流後嗣，高帝設爵以延田橫，世祖指河而誓朱鲔，君之負累，豈如二子，是以至情，原聞德音，智者之慮，慮於未形，達者所規，規於未兆，是故子胥知姑蘇之有麋鹿，辅果識智伯之為趙禽，穆生謝病以免楚難，邹陽北遊，不同吳禍，此四士者，豈聖人哉，徒通变思深，以微知著耳，若能內取子布，外击劉備，以效赤心，用复前好者，則江表之任，長以相付，高位重爵，坦然可觀。","sortOrder":34},
  {"id":"s_work_nvlt_25_35","chapterId":"ch_work_nvlt_25","text":"晉孫楚為石苞與孫晧書曰：吳之先主，起自荆州，遭時扰攘，播潛江表，劉備震懼，逃跡巴岷，遂依丘陵積石之固，三江五湖，浩汗無涯，假氣遊魂，迄於四紀，二邦合從，東西唱和，卒相扇動，拒捍中國，自謂三分鼎足之势，可與泰山共相終始，晉王辅相帝室，文武桓桓，獨見之鑒，與眾絕慮，主上钦明，委以萬機，長辔遠御，妙略潛授，偏師同心，上下用力，威稜奋伐，深入其阻，併敵一向，奋其胆氣，小戰江界，成都自潰，曜兵劍閣，而薑維面縛，开地五千，裂郡三十，師不逾時，梁益肅清，使竊號之雄，稽顙絳闕，球琳重錦，充於府库，夫虢滅虞亡，韓併魏徙，此皆前鑒之验，後事之師也，方今百寮濟濟，俊乂盈朝，虎臣武將，折冲萬里，國富兵強，六軍精練，思复翰飛，飲馬南海，自頃國家整治器械，修造舟楫，簡習水戰，伐树北山，則太行木盡，濬决河洛，則百川流通，樓船萬艘，千里相望，自刳木以來，舟車之用，未有如今日之盛者也，驍勇百萬，畜力待時，役不再舉，今日之謂也。","sortOrder":35},
  {"id":"s_work_nvlt_25_36","chapterId":"ch_work_nvlt_25","text":"晉劉琨與石勒書曰：將軍誕禀雄姿，勇略自然，大呼於紛扰之中，奋臂於駭亂之际，發跡河朔，席卷兖豫，飲馬江沔，折冲淮漢，自古名將，未足為喻，所以攻城而不有其民，略地而不有其士，聚徒百萬，而莫為己用，翕爾雲合，忽复星散，周流天下，而無容足之地，百戰百勝，而無尺寸之功，將軍豈知然乎，存亡决在得主，成败要在所附，得主則為義兵，附逆則為賊眾，義兵雖败，而功業必成，賊眾雖剋，而終殄滅者也，赤眉盛於東海，黃巾連帶三州，張昌李辰，僣逆荆豫，或擁眾百萬，橫逸宇內，所以一旦败亡，正以兵出無名，聚而為亂，劉聰父子，戎狄凡才，乘衅肆毒，寇虐人神，煞父害弟，偷竊位號，自古及今，豈有聰比而可以王天下者乎，見將軍明鑒灼然，所宜懸了者也，况附聰之弊，漸以彰著，資财不為己用，名位不可得守，有若晨霜秋露，雰霧之氣，雖朝凝而夕消，蹔見而尋没也，今將軍附賊，而望為民主，不亦難乎。","sortOrder":36},
  {"id":"s_work_nvlt_25_37","chapterId":"ch_work_nvlt_25","text":"晉桓玄與劉牢之書曰：今君戰败則傾宗，戰勝則覆族，以是安歸乎，孰若翻然改圖，唯理是宅，保其富貴，全其勋業，則身與金石等固，名與天壤俱窮，孰與頭足異處，身名俱滅，為天下笑哉，夫明者見於無形，愚夫安於所躭，二者成败，惟君圖之。","sortOrder":37},
  {"id":"s_work_nvlt_25_38","chapterId":"ch_work_nvlt_25","text":"宋謝莊為朝臣與雍州刺史袁顗書曰：夫夷险相因，興革逮數，或殷忧而啟聖明，此既著於聞見，天道辅順，謳歌有奉，高祖之孫，文皇之子，德洞九幽，功貫二曜，匡拯家國，提敏蒼生，若不南面子民，將使神器何主，當誓眾奋戈，剪此朝食，若自延過聽，迷涂未遠，聖上臨物以仁，接下以愛，豈直雍齒先封，乃當射鉤見相矣。","sortOrder":38},
  {"id":"s_work_nvlt_25_39","chapterId":"ch_work_nvlt_25","text":"梁簡文帝與魏東荆州刺史李志書曰：卿門世英葉，中州舊族，自金天失馭，帝鼎南遷，衣冠播越，不及俱邁，豈可屈志膻戎，久淪胡壤，今皇師外埽，天鉞四臨，海荡電飛，雲蒸雨合，所摧所剋，是卿之具聞也，且伪國沸騰，四方幅裂，主虐臣奸，牝雞亂政，若能早識事機，翻歸有道，豈直圖形長樂，刻像鍾鼎，時事易差，相思勉励，但明月闇投，昔人為誡，鄰蕃赠藥，有可虛懷，密驿輕郵，侧望歸簡。","sortOrder":39},
  {"id":"s_work_nvlt_25_40","chapterId":"ch_work_nvlt_25","text":"梁邵陵王萧纶與元帝書曰：先朝聖德治天下，九親維睦，四表無怨，誠為國政，實亦家風，弟弘識遠鑒，無俟傍說，事重情切，不能默已，勞兵損義，虧失多矣，可謂吞冰療寒，扬湯止沸，侯景所以未敢窥兵江外，正為蕃屏盤固，宗镇強密，若自相魚肉，是謂代景行師，昔廉蔺二虎，且猶不斗，况弟與湘雍，方須葉力，惟親惟急，萬倍於斯，同怨同恥，尤甚昔事，豈得各恣目前，不思久遠，安臥積薪，日待焚炽，狂夫尚猶阻之，智者反致其惑，所冀聽識，一聞斯悟。","sortOrder":40},
  {"id":"s_work_nvlt_25_41","chapterId":"ch_work_nvlt_25","text":"梁丘遲與陳伯之書曰：將軍勇冠三軍，才為世出，弃燕雀之小志，慕鸿鶴以高翔，昔因機变化，遭遇明主，立功展事，开國稱孤，朱輪華轂，擁旄萬里，何其壮也，如何一旦為奔亡之虜，聞鳴鏑而股栗，對穹庐以屈膝。又何劣耶，暮春三月，江南草長，雜花生树，群湋亂飛，見故國之旗鼓，感平生於畴昔，撫絃登陴，豈不怆恨，所以廉公之思趙將，吳子之泣西河，人之情也，將軍獨無情哉。","sortOrder":41},
  {"id":"s_work_nvlt_25_42","chapterId":"ch_work_nvlt_25","text":"◇嘲戲","sortOrder":42},
  {"id":"s_work_nvlt_25_43","chapterId":"ch_work_nvlt_25","text":"《毛詩》曰：善戲謔兮，不為虐兮。","sortOrder":43},
  {"id":"s_work_nvlt_25_44","chapterId":"ch_work_nvlt_25","text":"《左傳》曰：晉人或以廣队，不能進，楚人惎之，脱扃，少進馬還。又惎之，拔旆投衡乃出，顧曰：吾不如大國之數奔也。","sortOrder":44},
  {"id":"s_work_nvlt_25_45","chapterId":"ch_work_nvlt_25","text":"《晏子春秋》曰：晏子短小，使楚，楚人為小門於大門侧，而延晏子，晏子不入，曰：使狗國者，從狗門入，今臣使楚，不當從狗門入，王曰：齊無人耶，對曰：齊之臨淄，張袂成帷，揮汗成雨，何為無人，齊使賢者使賢王，不肖者使不肖王，婴不肖，故使王爾。","sortOrder":45},
  {"id":"s_work_nvlt_25_46","chapterId":"ch_work_nvlt_25","text":"又曰：晏子使楚，楚王謂左右曰：晏婴習辭者也，吾欲傷之，若坐定，縛一人來，及婴坐，左右縛人，王問何謂者，曰：齊人，坐盜，王视《晏子》曰：齊人善盜乎，晏子對曰：婴聞橘生江北則為枳，葉徒相似，其實味不同，水土異也，今此人生於齊不為盜，入楚則盜，得無楚之水土使為盜耶，王笑曰：寡人反取病焉。","sortOrder":46},
  {"id":"s_work_nvlt_25_47","chapterId":"ch_work_nvlt_25","text":"孔藂子曰：平原君與子高飲，強子高酒，曰：昔有遺諺，尧舜千鍾，孔子百觚，子路溘溘，尚飲百榼，古之賢聖，無不能飲也，吾子何辭焉，子高曰：以穿所聞，賢聖以道德燕人，未聞以飲也，平原君曰：即如先生言，則此言何出，子高曰：出於嗜酒者，蓋其勸励探戲之辭，非實然也，平原君忻然曰：吾弗戲子，無所聞此雅言也。","sortOrder":47},
  {"id":"s_work_nvlt_25_48","chapterId":"ch_work_nvlt_25","text":"《漢書》曰：東方朔自公卿在坐，朔皆傲弄，無所為屈，上以朔口諧辭給，嘗問朔曰：先生视朕何如主也，朔對曰：自唐虞之隆，成康之际，未足以諭當世，臣伏觀陛下功德，陳五帝之上，在三王之右，非若此而已，誠得天下賢士，公卿在位，鹹得其人矣，譬若以邵公為丞相，孔丘為御史大夫，太公為將軍，畢公高拾遺於後，卞莊子為衛尉，皋陶為大理，後稷為司農，伊尹為少府，子貢使外國，顏闵為博士，子夏為太常，孫叔敖為諸侯相，子產為郡守，王子慶忌為期門，上乃大笑。","sortOrder":48},
  {"id":"s_work_nvlt_25_49","chapterId":"ch_work_nvlt_25","text":"續《漢書》：邊韶，字孝先，以文學知名，教授數百人，韶口辯，曾晝假臥，弟子嘲之曰：邊孝先，腹便便，嬾讀書，但欲眠，韶潛聞之，應時對曰：邊為姓，先為字，腹便便，五經笥，但欲眠，思經事，寐與周公通夢，坐與孔子同意，師而可嘲，出何典記。","sortOrder":49},
  {"id":"s_work_nvlt_25_50","chapterId":"ch_work_nvlt_25","text":"《魏略》曰：丁謐父斐，初隨太祖，太祖以斐乡里，特饒愛之，太祖征吳，斐隨行，以家牛羸困，私易官牛，坐免官，後太祖啁斐曰：文侯印綬所在，斐知見戲，對曰：以易餅，太祖大笑，謂左右曰：東曹毛掾，數白此家，欲我重治，我非不知清良也，譬如人家有盜狗，而善捕鼠，盜雖有小損，而完我囊貯，遂复斐官如初。","sortOrder":50},
  {"id":"s_work_nvlt_25_51","chapterId":"ch_work_nvlt_25","text":"《魏略》曰：太祖請會，啁王朗曰：飲太祖［按飲太祖三字，魏志王朗傳註引無，疑本作太祖請會飲，太祖啁王朗曰：此有訛倒。］不能效君，昔在會稽折粳米飯也，朗仰而叹曰：宜適難值，如朗昔者，未可折而折，如明公今日，可折而不折。","sortOrder":51},
  {"id":"s_work_nvlt_25_52","chapterId":"ch_work_nvlt_25","text":"《蜀志》曰：張裕饒鬢，［《太平御覽》四百六十六作須，下同。］先主嘲之曰：涿縣特多毛姓，東西南北皆諸毛也，涿令稱曰：諸毛饒涿居乎，裕即答曰：昔有作上党潞長，遷為涿令者，去官還家，時人與書，欲署潞則失涿，署涿則失潞，乃署曰潞涿君，先主無鬢，故裕雲此也。","sortOrder":52},
  {"id":"s_work_nvlt_25_53","chapterId":"ch_work_nvlt_25","text":"又曰：蜀遣邓芝使吳，孫權謂芝曰：若天下太平，二主分理，不亦樂乎，芝對曰：夫天無二日，土無二王，如併魏之後，大王未深識天命，則戰爭方始耳，權大笑曰：君之誠款，乃當爾耶。","sortOrder":53},
  {"id":"s_work_nvlt_25_54","chapterId":"ch_work_nvlt_25","text":"《吳志》曰：蜀使張奉使，於孫權前，以姓名啁阚泽，泽不能答，薛綜下行酒，用勸雲，蜀者何也，有犬為獨，無犬為蜀，橫目句身，虫入其腹，奉曰：不當复說君吳耶，綜應聲曰：無口為天，有口為吳，君臨萬邦，天子之都，於是眾坐喜笑，而奉無對。","sortOrder":54},
  {"id":"s_work_nvlt_25_55","chapterId":"ch_work_nvlt_25","text":"《江表傳》曰：孫權以鄭泉為郎中，嘗為之言，卿好於眾中面諫，或失禮敬，寧不畏龍鱗乎，對曰：臣聞君明臣直，朝廷上下無讳，實恃洪恩，不畏龍鱗，後侍宴，權乃怖之，命提出有司治罪，泉臨出，屢顧，權呼還，笑曰：卿言不畏龍鱗，何以臨出而顧乎，對曰：實恃恩覆，無忧至死，當出閤，感惟威靈，不能不顧耳。","sortOrder":55},
  {"id":"s_work_nvlt_25_56","chapterId":"ch_work_nvlt_25","text":"《典略》曰：魏文帝嘗賜劉楨郭落帶，其後師死，欲借取以為像，因書啁楨雲，夫物因人為貴，故在賤者之手，不御至尊之侧，今雖取之，勿嫌其不反也，楨答曰：聞荆山之璞，曜元後之寶，隨侯之珠，燭眾女之好，南垠之金，登窈窕之首，丰貂之尾，缀侍臣之帻，此四寶者，伏朽石之下，潛汙泥之中，而扬光千載之上，皆亦未能初接於至尊也，貴者所御，賤者所先也，故夏屋初成，而大匠先立其下，嘉禾始熟，而農夫先嘗其粒，恨楨所帶，無他妙飾，若實殊異，尚可納也。","sortOrder":56},
  {"id":"s_work_nvlt_25_57","chapterId":"ch_work_nvlt_25","text":"諸葛恪別傳曰：孫權嘗宴見蜀使費禕，逆敕群臣，使至伏食勿起，至，權為輟食，而群下不起，禕啁之曰：鳳皇來翔，騏驎吐哺，驢騾無知，伏食如故，恪答曰：爰植梧桐，以待鳳皇，有何燕雀，自稱來翔，何不彈射，使還故乡，王隱《晉書》曰：武帝問郄诜，卿自以為何如，诜對曰：臣舉賢良對策，為天下第一，猶桂林之一枝，若崑山之片玉，帝笑，侍中奏免诜，詔曰：吾與戲耳。","sortOrder":57},
  {"id":"s_work_nvlt_25_58","chapterId":"ch_work_nvlt_25","text":"《晉中興書》曰：刁彝於桓溫坐，嘲韓博曰：君是韓盧後，博誤曰：卿是韓盧後，溫笑曰：刁以君姓韓，故相問耳，他自刁，那得是韓盧後，博曰：明公未之思耳，短尾者則為刁也，一坐推叹焉。","sortOrder":58},
  {"id":"s_work_nvlt_25_59","chapterId":"ch_work_nvlt_25","text":"《文士傳》曰：棗據嘲沙門幹法龍曰：今大晉弘廣，天下為家，何不全發膚，去袈裟，舍故服，被綺羅，入沧浪，濯清波，隨太陽，耀春華，而獨上违父母之恩，下失夫婦之疋，雖受布施之名，而有乞丐之實乎。","sortOrder":59},
  {"id":"s_work_nvlt_25_60","chapterId":"ch_work_nvlt_25","text":"顧恺之家傳曰：恺之見謝萬，因論神仙，謂曰：仙者之乘，或羊或鹿，使君當乘何物耶，使君曰：居家者，遇物斯乘，卿辈即轅中客也。","sortOrder":60},
  {"id":"s_work_nvlt_25_61","chapterId":"ch_work_nvlt_25","text":"《語林》曰：劉道真於河侧自牵舡，見一老嫗采旅，［《太平御覽》四百六十六作穞。］劉啁之曰：女子何不調機利杼而采旅，［御覽作穞。］女答曰：丈夫何不跨馬揮鞭而牵舡。","sortOrder":61},
  {"id":"s_work_nvlt_25_62","chapterId":"ch_work_nvlt_25","text":"又曰：道真嘗與一人共索袢草中食，見一嫗將二兒過，併青衣，啁之曰：青羊將兩羔，嫗答曰：兩猪共一槽。","sortOrder":62},
  {"id":"s_work_nvlt_25_63","chapterId":"ch_work_nvlt_25","text":"又曰：許玄度將弟出都婚，諸人钦遲之，既見，乃甚癡，便欲嘲弃之，玄度為之作賓主相對，真長叹曰：玄度為弟婚，施十重鐵步障。","sortOrder":63},
  {"id":"s_work_nvlt_25_64","chapterId":"ch_work_nvlt_25","text":"又曰：鍾雅語祖士言，我汝穎之士利如錐，卿燕代之士钝如槌，祖曰：以我钝槌，打爾利錐，鍾曰：自有神錐，不可得打，祖曰：既有神錐，亦有神槌。","sortOrder":64},
  {"id":"s_work_nvlt_25_65","chapterId":"ch_work_nvlt_25","text":"又曰：辛恭靜見司馬太傅，問卿何處人，答曰：西人，太傅應聲戲之曰：在西頗見西王母不，恭靜答曰：在西乃不見西王母，過東已見東王公，太傅大愧。","sortOrder":65},
  {"id":"s_work_nvlt_25_66","chapterId":"ch_work_nvlt_25","text":"又曰：晉孝武好與虞嘯父飲酒，醉拜不能起，帝呼人扶，虞嘯父答曰：臣位未及扶，醉未及亂，非分之賜，所不敢當，帝美之，敕疏取語，於是為風俗，人相嘲調，辄雲好語疏取。","sortOrder":66},
  {"id":"s_work_nvlt_25_67","chapterId":"ch_work_nvlt_25","text":"《世說》曰：庾元規語周伯仁曰：諸人皆以君方樂，周曰：樂毅耶，庾曰：方樂令耳，周曰：何乃刻畫無鹽，以搪突西施耶。","sortOrder":67},
  {"id":"s_work_nvlt_25_68","chapterId":"ch_work_nvlt_25","text":"又曰：諸葛瑾為豫州，別駕雲，［按世說排調篇作遣別駕到台，語雲，此有脱文。］小兒知談，卿可與語，別駕唤恪咄咄郎君，恪因嘲之，豫州亂矣，何咄咄之有，答曰：君明臣賢，未聞其亂，恪复雲，昔唐尧在上，四凶在下，答曰：豈惟四凶，亦有丹朱。","sortOrder":68},
  {"id":"s_work_nvlt_25_69","chapterId":"ch_work_nvlt_25","text":"又曰：邓艾口吃，語稱艾艾，晉文王戲之曰：卿雲艾艾，為是幾艾，邓答曰：鳳兮鳳兮，故是一鳳。","sortOrder":69},
  {"id":"s_work_nvlt_25_70","chapterId":"ch_work_nvlt_25","text":"又曰：桓南郡出射，有劉參軍與周參軍同用［世說排調篇作朋。］赌，垂成，唯少一破，劉謂周曰：卿此起不破，我當相撻，周曰：何至受卿撻，劉曰：伯禽之貴，尚不免撻，而况於卿。","sortOrder":70},
  {"id":"s_work_nvlt_25_71","chapterId":"ch_work_nvlt_25","text":"又曰：謝太傅始有東山之志，桓公見藥中有遠志，公問謝，此藥又名小草，何以一物二稱，謝未即答，郝參軍答曰：處則為遠志，出則為小草，謝公殊有愧色。","sortOrder":71},
  {"id":"s_work_nvlt_25_72","chapterId":"ch_work_nvlt_25","text":"又曰：司馬太傅斋中坐，天月明净，叹以為佳，謝景重答曰：意謂不如有微雲點缀，太傅因戲謝曰：卿居心不净，乃复欲滓秽太清耶。","sortOrder":72},
  {"id":"s_work_nvlt_25_73","chapterId":"ch_work_nvlt_25","text":"又曰：荀鳴鶴陆士龍二人，俱會張茂先坐，共語，陆曰：雲間陆士龍，荀曰：日下荀鳴鶴，陆曰：既开青雲，睹白雉，何不張爾弓，彀爾矢，荀答曰：本謂是雲龍骙骙，乃是山鹿野麋，獸微弩強，是以發遲。","sortOrder":73},
  {"id":"s_work_nvlt_25_74","chapterId":"ch_work_nvlt_25","text":"沈約宋書，何承天除著作郎，年時已老，諸佐郎併名家年少，荀伯子嘲之，常呼為妳母，承天曰：卿當雲鳳皇將九子，妳母何言耶。","sortOrder":74},
  {"id":"s_work_nvlt_25_75","chapterId":"ch_work_nvlt_25","text":"又曰：劉義基封營道侯，凡鄙無識，始興王濬謂義基曰：陆士衡詩曰：營道無烈心，其意若何文義，答曰：下官初不識士衡，何忽見苦。","sortOrder":75},
  {"id":"s_work_nvlt_25_76","chapterId":"ch_work_nvlt_25","text":"【詩】晉李充嘲友人詩曰：同好齊歡愛，纏綿一何深，子既識我情，我亦知子心，燕婉歷年歲，和樂如瑟琴，良辰不我俱，中闊似商參，爾隔北山陽，我分南川陰，嘉會罔克從，積思安可任，目想妍麗姿，耳存清媚音，修晝興永念，遙夜獨悲吟，逝將尋行役，言別涕沾襟，原示降玉趾，一顧重千金。","sortOrder":76},
  {"id":"s_work_nvlt_25_77","chapterId":"ch_work_nvlt_25","text":"【答客難】東方朔答客難曰：蘇秦張儀，一當萬乘之主，而身都卿相之位，泽及後世，今子大夫修先王之術，慕聖主之義，自以為智能海內無双，則可謂博聞辯智矣，然悉力盡忠，以事聖帝，曠日持久，官不過侍郎，位不登執戟，意者尚有遺行耶，東方先生仰而應曰：蘇秦張儀之時，周室大坏，諸侯不朝，力政爭權，相禽以兵，得士者強，失士者亡，故談說得行焉，身處尊位，今則不然，聖帝流德，天下震慴，諸侯賓服，安於覆盂，動猶運掌，賢不肖何以異哉，尊天之道，順地之理，物無不得其所，故綏之則安，動之則苦，尊之則為將，卑之則為虜，抗之則在青雲之上，抑之則在黃泉之下，雖欲盡節效情，安知前後，使蘇秦張儀與仆併生於今之世，曾不得掌故，安敢望侍郎乎。","sortOrder":77},
  {"id":"s_work_nvlt_25_78","chapterId":"ch_work_nvlt_25","text":"又漢楊雄解嘲曰：客嘲楊子曰：吾聞上世之士，人綱人紀，析人之圭，儋人之爵，紆青拖紫，朱丹其轂，今吾子幸得遭盛明之世，處不讳之朝，歷金門，上玉堂，有日矣，曾不能畫一奇，出一策，上說人主，下談公卿，顧黜而作太玄五千文，深者入黃泉，高者出蒼天，大者含元氣，纖者入無間，然位不過侍郎，擢才給事黃門，楊子笑而應之曰：客徒欲朱丹吾轂，不知一跌將赤吾之族也，往者周網解結，群鹿爭佚，土亡常君，國亡定臣，得士者富，失士者貧，今大漢，左東海，右渠搜，前番禺，後椒涂，散以禮樂，風以詩書，天下之士，雷動而雲合，魚鱗雜袭，鹹營於八區，家家自以為稷契，人人自以為皋陶，戴纚垂纓而談者，皆擬於阿衡，五尺童子，羞比晏婴與夷吾，旦握權則為卿相，夕失势則為疋夫，譬若江湖之涯，渤澥之島，乘雁集不為之多，双凫飛不為之少，向使上世之士，處乎今也，策非甲科，行非孝廉，舉非方正。又安得金紫，且吾聞之也，攫拏者亡，默默者存，位極者宗危，自守者身全，是以知玄知默，守道之極，爰靜爰清，遊神之廷，惟寂惟寞，守德之宅，世異事变，人道不殊，彼我易時，未知何如，故有造萧何律於唐虞之世，則谬矣，有作叔孫通儀於夏殷之時，則惑矣，有建娄敬之策於成周之世，則悖矣，有談范蔡之說於金張許史之間，則狂矣，夫萧規而曹隨，留侯畫策，陳平出奇，功若泰山，响若埙篪，雖其人贍智哉，亦會其時之可為也，故為可為於可為之時則從，為不可為於不可為之時則凶。","sortOrder":78},
  {"id":"s_work_nvlt_25_79","chapterId":"ch_work_nvlt_25","text":"後漢班固賓戲曰：太上有立德，其次有立功，是以聖哲治之，栖栖遑遑，孔席不暖，墨突不黔，由此言之，取舍者昔人之上務，著作者前烈之餘事耳，今吾子幸遊帝王之世，躬帶绂冕之服，卒不能摅首尾，奋翼鱗，使見之者景駭，聞之者响震，徒枕經籍，紆體衡門，潛神默記，亘以年歲，然而器不贾於當己，用不效於一世，雖馳辯如涛波，摛藻如春華，猶無益於殿最也，主人曰：若賓之言，斯所謂見势利之華，闇道德之實，守突奧之熒燭，未仰天庭而睹白日也，曩者王涂芜秽，周失其馭，侯伯方軌，戰國橫骛，當此之時，搦杇磨钝，鉛刀皆能一斷，商鞅挟三術以贊［《文選》四十五作鑽。］孝公，李斯奋，時務而要始皇，彼皆躡風尘之會，履顛沛之势，朝為榮華，夕而憔悴，福不盈眦，禍溢於世，且功不可以虛成，名不可以伪立，韓設辯而徼君，呂行诈以贾國，說難既酋，［《文選》作遒。］其身乃囚，秦货既貴，厥宗亦墜，方今大漢，洒扫群秽，夷险芟荒，廓帝紘，恢皇綱，基隆於羲農，規廣於黃唐，其君天下也，炎之如日，威之如神，涵之如海，養之如春，譬猶草木之殖山林，鳥魚之毓川泽，參天地而施化，豈雲人事之厚薄哉，賓曰：若夫鞅斯之倫，既聞命矣，敢問上古之士，處身行道，辅世成名，可述於後者，默而已乎，主人曰：何為其然也，昔者咎繇謨虞，箕子訪周，言通帝王，謀合聖神，殷說夢發於傅巖，周望兆動於渭濱，皆侯命而神交，匪詞言之所信，故能建必然之册，展無窮之勋也，若乃牙曠清耳於管絃，離娄眇目於豪末，逢蒙絕伎於弧矢，班输攉巧於斧斤，仆亦不任廁伎於彼列，故密邇自娱於斯文。","sortOrder":79},
  {"id":"s_work_nvlt_25_80","chapterId":"ch_work_nvlt_25","text":"後漢崔骃達旨曰：往者楊雄設言，客有難玄之尚白，應以戰國之士，若范蔡邹衍，垂衅相傾，誑曜諸侯，以幹濁世之寵，或人亦有睹我之澹泊，故比方昔問以難餘，餘略依前訓以報焉，或說己曰：今子韞韣六經，服膺道術，歷世而遊，高談有日，然下不步卿相之庭，上不登王公之門，進不党於贊己，退不渎於庸人，獨師友道德，合符曩真，蓋树乔靡休，獨木不林，隨時之宜，道貴從己，答曰：有是乎，苟欲免吾以世路，不知其跌而失吾之度也，昔尧含威而皋陶謨，高祖叹而子房慮，禍不散而曹絳奋，結不解而陳平權，及策合道從，克亂弭冲，乃將銘崑吾之冶，勒景襄之鍾，今聖上之育斯民也，朴以皇质，彫以唐文，六合怡怡，比屋為仁，夫君子非不欲仕也，恥夸毗以求舉，非不欲室也，惡登牆而樓處，叫呼衒鬻，懸旌皇表，非隨和之寶也，曝智曜世，固以幹祿，非仲尼之道也。","sortOrder":80},
  {"id":"s_work_nvlt_25_81","chapterId":"ch_work_nvlt_25","text":"後漢崔寔答譏曰：客有譏夫人之享天爵而應睿哲也，必將振民毓德，弭難濟時，故或階媵以納說，或桎梏而不辭，或击角以自衒，或養老以待期，及其規合策從，勋績克章，拨亂夷险，九合一匡，聖人大寶，唯斯為光，今子遊精太清，潛思九玄，厲節縹霄，抗志浮雲，口原甘而嘗苦，身樂逸而長勤，志求貴而永卑，情好富而困貧，慕容名而失厚，思慮勞乎形神，答曰：子徒休彼繡衣，不知嘉遁之獨肥也，且麟隱於遐荒，不紆機阱之路，鳳皇翔於寥廓，故節高而可慕，李斯奋激，果失其度，胥种遂功，身乃無處，觀夫人之進趍也，不揣己而幹祿，不揆時而要會，或遭否而不遇，或智小而謀大，纖芒豪末，禍亟無外，榮速激電，辱必弥世，故曰：愛餌衔鉤，悔在鸞刀，被文食豢，乃啟其毛，若夫守恬履靜，澹爾無求，沉缗濬壑，栖息高丘，雖無炎炎之樂，亦無灼灼之忧，餘竊嘉茲，庶遵厥猷。","sortOrder":81},
  {"id":"s_work_nvlt_25_82","chapterId":"ch_work_nvlt_25","text":"後漢蔡邕釋誨曰：務世公子，誨於華顛，胡老曰：今夫子生清穆之世，禀醇和之器，覃思典籍，韞韣六經，安貧樂賤，與世無營，曾不能登天庭，序彝倫，扫六合之秽慝，清宇宙之埃尘，小子惑焉，胡老曰：若公子，所謂睹暧昧之利，而忘昭晢之害，专必成之功，而忽跌蹉之败者已，於是智者騁诈，辯者馳說，武夫奋略，戰士講說，電駭風馳，霧散雲披，連衡者六印磊落，合從者骈組流離，據巧蹈機，以忘其危，夫花離蒂而萎，條去幹而枯，女冶容而淫，士背道而辜，人毀其滿，神疾其邪，利端始萌，害漸亦牙，貪夫殉财，夸者死權，瞻仰世事，體躁心煩，暝謙盈之效，迷損益之數，騁駑骀於修路，慕麒麟而增驅，卑俯乎外戚之門，乞助乎近貴之譽，原榮未副，從而顛踣，大河盈溢，非一屆所防，帶甲百萬，非一勇所抗，今子责疋夫以清宇宙，庸可以水旱而累尧湯乎，是以君子推微達著，尋端究緒，履霜知冰，踐露知暑，魏陳琳應譏曰：客有譏餘者雲，聞君子動作周旋，無所苟而已矣，今主君鍾陰陽之美，總賢聖之風，固非世人所能及，遭銶狼肆虐，社稷陨傾，既不能抗節服義，與主存亡，而背枉违難，耀茲武功，徒獨震扑山東，剝落元元，結疑本朝，假拒群奸，使己蒙噂沓之謗，而他人受讨賊之勋，捐功弃力，以德取怨，今賤文德而貴武勇，任權譎而背舊章，無乃非至德之純美，而有闕於後人哉，主人曰：是何言也，夫兵之設亦久矣，所以威不軌而懲淫慝也，夫申鳴违父，樂羊食子，季友鸩兄，周公戮弟，猶忍而行之，王事所不得已也，而况將避讒慝之嫌，弃社稷之難，愛暫勞之民，忘永康之樂，此庸夫猶所不為，何有冠世之士哉，昔洪水滔天，汎濫中國，伯禹躬之，過門而不入，率萬方之民，致力乎溝洫，及至箫韶九成，百獸率舞，垂拱無為，而天下晏如，夫豈前好勤而後媮樂乎，蓋以彼勞求斯逸也，夫世治责人以禮，世亂則考人以功，斯各一時之宜，故有論戰陣之權於清廟之堂者，狂矣，陳俎豆之器於城濮之墟者，則悖矣，是以達人君子，必相時以立功，必揆宜以處事，孝靈既丧，妖官放禍，棟臣殘酷，宮室焚火，主君乃芟凶族，夷惡丑，荡涤朝奸，清澄守職也，既乃卓為封蛇，幽鸩帝後，強以暴國，非力所讨，违而去之宜也，是故天贊人和，無思不至，用能合師百萬，若運諸掌者，義也，今主君以宽弘為宇，仁惠為庐，若地之載，如天之焘，故當其聞管籥之聲，則恐己之病也，見羽旄之美，則懼士之勞也，察稼穡之不時，惟民之匮也，臨台觀之崇高，則恤役之病也，是以虛心恭己，取人之謨，辟四門，廣諫路，貴谠言，賤巧伪，慮不专行，功不擅美，咨事若不及，求愆恐不聞，用能使賢智者盡其策，勇敢者竭其身，故舉無遺闕，而風烈宿宣也。","sortOrder":82},
  {"id":"s_work_nvlt_25_83","chapterId":"ch_work_nvlt_25","text":"《藝文類聚》　唐·欧陽詢","sortOrder":83},
  {"id":"s_work_nvlt_26_1","chapterId":"ch_work_nvlt_26","text":"卷二十六人部十","sortOrder":1},
  {"id":"s_work_nvlt_26_2","chapterId":"ch_work_nvlt_26","text":"○言志","sortOrder":2},
  {"id":"s_work_nvlt_26_3","chapterId":"ch_work_nvlt_26","text":"◇言志","sortOrder":3},
  {"id":"s_work_nvlt_26_4","chapterId":"ch_work_nvlt_26","text":"《尚書》曰：詩言志。","sortOrder":4},
  {"id":"s_work_nvlt_26_5","chapterId":"ch_work_nvlt_26","text":"《禮記》：志之所至，詩亦至焉，詩之所至，樂亦至焉。","sortOrder":5},
  {"id":"s_work_nvlt_26_6","chapterId":"ch_work_nvlt_26","text":"《毛詩序》曰：詩者，志之所之也，在心為志，發言為詩。","sortOrder":6},
  {"id":"s_work_nvlt_26_7","chapterId":"ch_work_nvlt_26","text":"《論語》曰：顏回季路侍，子曰：盍各言爾志，子路曰：原車馬，衣輕裘，與朋友共，弊之而無憾，顏回曰：原無伐善，無施勞，子路曰：原聞子之志，子曰：老者安之，朋友信之，少者懷之。","sortOrder":7},
  {"id":"s_work_nvlt_26_8","chapterId":"ch_work_nvlt_26","text":"又，子曰：飯蔬食飲水，曲肱而枕之，樂亦在其中矣，不義而富且貴，於我如浮雲。","sortOrder":8},
  {"id":"s_work_nvlt_26_9","chapterId":"ch_work_nvlt_26","text":"又曰：葉公問孔子於子路，子路不對，子曰：汝奚不曰：其為人也，發憤忘食，樂以忘忧，不知老之將至雲爾。","sortOrder":9},
  {"id":"s_work_nvlt_26_10","chapterId":"ch_work_nvlt_26","text":"又，子路曾晢冉有公西華侍坐，子曰：居則曰不吾知也如或知爾，則何以哉？子路率爾而對曰：千乘之國，攝乎大國之間，加之以師旅，因之以飢饉，由也為之，比及三年，可使有勇，且知方也。夫子哂之，求爾何如？對曰：方六七十，如五六十，求也為之，比及三年，可使足民，如其禮樂，以俟君子。赤爾何如？對曰：非曰能之，原學焉，宗廟之事，如會同，端章甫，原為小相焉。點爾何如？鼓瑟希，铿爾，舍瑟而作。對曰：異乎三子者之撰。子曰：何傷乎，亦各言其志也。曰：暮春者，春服既成，冠者五六人，童子六七人，浴乎沂，風乎舞雩，詠而歸。夫子喟然叹曰：吾與點也。","sortOrder":10},
  {"id":"s_work_nvlt_26_11","chapterId":"ch_work_nvlt_26","text":"《家語》，孔子北遊，登於農山之上，子路子貢顏回侍侧，孔子四望，喟然而叹曰：於斯致思，無所不至矣，二三子各言其志，吾將擇焉，子路進曰：原得白羽若月，赤羽若日，鍾鼓之音，上振於天，旌旗繽紛，下蟠於地，由當一队而敵之，搴旗執馘，唯由能之，使夫二子從我焉，夫子曰：勇哉，子貢曰：賜原使齊楚合戰，兩壘相當，旗鼓相望，埃尘連接，捉刃交兵，賜著縞衣白冠，陳說其間，推論利害，二國釋患，唯賜能之，使夫二子從我焉，夫子曰：辯哉，顏回曰：回聞薰莸不同器而藏，尧桀不共國而治，以類異也，回原得明王聖主而相之，敷其五教，遵之禮樂，使城郭不脩，溝洫不越，鑄兵刃為農器，放牛馬於原藪，室家無怨曠之思，千載無戰斗之患，則由無所施其勇，而賜無所用其辯矣，夫子懍然曰：美哉德也，不傷财，不害民，不繁辭，則顏氏之子有焉。","sortOrder":11},
  {"id":"s_work_nvlt_26_12","chapterId":"ch_work_nvlt_26","text":"孝經鉤命决曰：孔子曰：吾志在春秋，行在孝經，以春秋屬商，以孝經屬參。","sortOrder":12},
  {"id":"s_work_nvlt_26_13","chapterId":"ch_work_nvlt_26","text":"《史記》：陳涉嘗與人佣耕，輟耕於垄上，怅恨久之，曰：苟富貴，無相忘，佣者笑而應之曰：若為佣耕，何富貴乎，涉太息曰：嗟乎，燕雀焉知鸿鵠之志哉。","sortOrder":13},
  {"id":"s_work_nvlt_26_14","chapterId":"ch_work_nvlt_26","text":"漢楊雄自叙曰：雄為人簡易佚宕，默而好深湛之思，清净無為，少嗜欲，不汲汲於富貴，不戚戚於貧賤，不修廉隅，以儌名當世，無擔石之储，晏如也，自有大度，非聖哲之書不好也，非其意，雖富貴不事也。","sortOrder":14},
  {"id":"s_work_nvlt_26_15","chapterId":"ch_work_nvlt_26","text":"東觀漢記，初光武適新野，聞陰後美，心悅之，後至長安，見執金吾甚盛，因叹曰：仕宦當作執金吾，娶妻當得陰麗華。","sortOrder":15},
  {"id":"s_work_nvlt_26_16","chapterId":"ch_work_nvlt_26","text":"後《漢書》：馬少遊謂其從兄援曰：士生一世，但取衣食裁足，乘下泽車，御款段馬，守墳墓，乡里稱善人，斯可矣。","sortOrder":16},
  {"id":"s_work_nvlt_26_17","chapterId":"ch_work_nvlt_26","text":"又，冯衍有大志，不戚戚於貧賤，常慷慨叹曰：衍少事名賢，經歷顯位，懷金垂紫，竭節奉使，不求苟得，常有凌雲之志，三公之貴，千金之富，不得其原，不槩於懷，貧而不衰，賤而不恨，年雖疲曳，猶庶幾名賢之風，修道德於幽冥之路，以終身名，為後世法。","sortOrder":17},
  {"id":"s_work_nvlt_26_18","chapterId":"ch_work_nvlt_26","text":"又，班超，字仲叔，家貧，佣書以供養，久乃投筆而叹曰：大丈夫無他志略，猶當效傅介子張騫，立功異域，以取封侯，安能久事筆砚間乎。","sortOrder":18},
  {"id":"s_work_nvlt_26_19","chapterId":"ch_work_nvlt_26","text":"又，梁竦，字敬叔，自負其才，鬱鬱不得其意，登山遠望，叹息曰：大丈夫生當封侯，死當廟食，如不然，閒居足以養志，詩書足以自娱，州郡之職，但勞人耳。","sortOrder":19},
  {"id":"s_work_nvlt_26_20","chapterId":"ch_work_nvlt_26","text":"又，仲長統，字公理，常欲卜居清曠，以樂其志，曰：濯清水，追涼風，釣遊鯉，弋高鸿，不受當世之责，永保性命之期，則可以凌雲霄，出宇宙之外矣。","sortOrder":20},
  {"id":"s_work_nvlt_26_21","chapterId":"ch_work_nvlt_26","text":"張璠漢紀，孔融拜太中大夫，雖居家失势，賓客日滿其門，愛才樂士，常若不足，每叹曰：坐上賓常滿，樽中酒不空，吾無忧矣。","sortOrder":21},
  {"id":"s_work_nvlt_26_22","chapterId":"ch_work_nvlt_26","text":"吳書，鄭泉，博學有奇姿，而性嗜酒，閒居，每日原得美酒滿五百斛舡，以四時甘肥置兩頭，反覆没飲之，憊即住而啖肴膳，酒有升斗减，隨即益之，不亦快乎。","sortOrder":22},
  {"id":"s_work_nvlt_26_23","chapterId":"ch_work_nvlt_26","text":"晉中興書，畢卓為吏部郎中，常謂人曰：右手持酒杯，左手持蟹螯，柏浮酒池中，便足了一生。","sortOrder":23},
  {"id":"s_work_nvlt_26_24","chapterId":"ch_work_nvlt_26","text":"【詩】魏陳思王曹植詩曰：慶雲未時興，雲龍潛作魚，神鸞失其儔，還從燕雀居。","sortOrder":24},
  {"id":"s_work_nvlt_26_25","chapterId":"ch_work_nvlt_26","text":"晉阮籍詠懷詩曰：天地煙煴，元精代序，清陽曜靈，和氣容與，於赫帝朝，伊衡作辅，才非允文，器非經武，適彼沅湘，讬介漁父，優哉遊哉，爰居爰處。","sortOrder":25},
  {"id":"s_work_nvlt_26_26","chapterId":"ch_work_nvlt_26","text":"又曰：月明星稀，天高地寒，嘯歌傷懷，獨寤寐言，臨觴拊膺，對食忘餐，世無萱草，令我哀叹。","sortOrder":26},
  {"id":"s_work_nvlt_26_27","chapterId":"ch_work_nvlt_26","text":"又曰：河上有丈人，緯萧弃明珠，甘彼藜藿食，樂是蓬蒿庐，豈效繽紛子，良馬騁輕舆，朝生衢路傍，夕瘞橫街隅，歌笑不終宴，俯仰复欷歔，鑒茲二三者，憤懣從此舒。","sortOrder":27},
  {"id":"s_work_nvlt_26_28","chapterId":"ch_work_nvlt_26","text":"又，幽蘭不可佩，朱草為誰榮，脩竹隱山陰，射幹臨增城。","sortOrder":28},
  {"id":"s_work_nvlt_26_29","chapterId":"ch_work_nvlt_26","text":"又曰：駕言發魏都，南向望吹台，箫管有遺音，梁王安在哉，戰士食糟糠，賢者處蒿萊，歌舞曲未終，秦兵复已來。","sortOrder":29},
  {"id":"s_work_nvlt_26_30","chapterId":"ch_work_nvlt_26","text":"又曰：木槿榮丘墓，煌煌有光色，白日頹林中，翩翩零路侧，蟋蟀吟戶牖，蟪蛄鳴荆棘，蜉蝣原三朝，采采循羽翼。","sortOrder":30},
  {"id":"s_work_nvlt_26_31","chapterId":"ch_work_nvlt_26","text":"又，一日复一日，一夕复一晨，容色改平常，精魂自飄淪，臨觴多哀楚，思我故情人，對酒不能言，凄怆懷酸辛。","sortOrder":31},
  {"id":"s_work_nvlt_26_32","chapterId":"ch_work_nvlt_26","text":"又曰：鸿鵠相隨飛，隨飛適荒裔，双翮凌長風，須臾萬里逝，朝餐琅玕實，夕宿丹山际，讬身青雲中，網羅不能製，豈與乡曲士，携手共言誓。","sortOrder":32},
  {"id":"s_work_nvlt_26_33","chapterId":"ch_work_nvlt_26","text":"又曰：鸒鳩飛桑榆，海鳥運天池，豈不識宏大，羽翼不相宜，招搖安可翔，不若栖树枝，下集蓬蒿間，上遊園囿篱，但爾亦自足，用子為追隨。","sortOrder":33},
  {"id":"s_work_nvlt_26_34","chapterId":"ch_work_nvlt_26","text":"又曰：嘉树下成蹊，東園桃與李，秋風吹飛藿，零落從此始，繁華有憔悴，堂上生荆杞。","sortOrder":34},
  {"id":"s_work_nvlt_26_35","chapterId":"ch_work_nvlt_26","text":"又曰：天馬出西北，由來從東道，春秋非有讬，富貴焉常保，清露被皋蘭，凝霜霑野草。","sortOrder":35},
  {"id":"s_work_nvlt_26_36","chapterId":"ch_work_nvlt_26","text":"又曰：平生少年時，輕薄好絃歌，西遊鹹陽中，趙李相經過，娱樂未終極，白日忽蹉跎，驅馬复來歸，反顧望三河，黃金百镒盡，資用常苦多，北臨太行道，失路將如何。","sortOrder":36},
  {"id":"s_work_nvlt_26_37","chapterId":"ch_work_nvlt_26","text":"又曰：步出上東門，北望首陽岑，下有采薇士，上有嘉树林，良辰在何許，凝霜霑衣襟，寒風振山岡，玄雲起重陰，鳴雁飛南征，鶗窸發哀音，素质遊商聲，凄怆傷我心。","sortOrder":37},
  {"id":"s_work_nvlt_26_38","chapterId":"ch_work_nvlt_26","text":"又曰：昔年十四五，志尚好書詩，被褐懷珠玉，顏闵相與期，开軒臨四野，登高望所思，丘墓蔽山岡，萬世同一時，千秋百歲後，榮名安所之。","sortOrder":38},
  {"id":"s_work_nvlt_26_39","chapterId":"ch_work_nvlt_26","text":"又曰：徘徊蓬池上，還顧望大梁，渌水扬洪波，曠野渀茫茫。","sortOrder":39},
  {"id":"s_work_nvlt_26_40","chapterId":"ch_work_nvlt_26","text":"又曰：寧與燕雀翔，不隨黃鵠飛，黃鵠遊四海，中路將安歸。","sortOrder":40},
  {"id":"s_work_nvlt_26_41","chapterId":"ch_work_nvlt_26","text":"又曰：北里多奇舞，濮上有微音，輕薄閒遊子，俯仰乍浮沉，焉見王子乔，乘雲翔邓林，獨有延年術，可用慰我心。","sortOrder":41},
  {"id":"s_work_nvlt_26_42","chapterId":"ch_work_nvlt_26","text":"又曰：南國有佳人，容華若桃李，朝遊江北岸，夕宿瀟湘沚，時俗薄朱顏，誰為發皓齒。","sortOrder":42},
  {"id":"s_work_nvlt_26_43","chapterId":"ch_work_nvlt_26","text":"又曰：夜中不能寐，起坐彈鳴琴，薄帷鑒明月，清風吹我衿，孤鸿號外野，翔鳥歸北林，徘徊將何見，忧思獨傷心，晉傅玄雜詩曰：閒夜微風起，明月照高台，清响呼不應，玄景招不來，厨人進藿茹，有酒不盈杯，安貧福所與，富貴為禍媒，金玉雖高堂，於我賤蒿萊。","sortOrder":43},
  {"id":"s_work_nvlt_26_44","chapterId":"ch_work_nvlt_26","text":"晉張翰詩曰：暮春和氣應，白日照園林，青條若總翠，黃花如散金，榮與壮俱去，賤與老相尋。","sortOrder":44},
  {"id":"s_work_nvlt_26_45","chapterId":"ch_work_nvlt_26","text":"又，東鄰有一树，三紀裁可拱，無花复無實，亭亭雲中竦，隙禽不為巢，短翮莫肯任。","sortOrder":45},
  {"id":"s_work_nvlt_26_46","chapterId":"ch_work_nvlt_26","text":"又，忽有一飛鳥，五色雜英華，一鳴眾鳥至，再鳴眾鳥羅，長鳴搖羽翼，百鳥互相和。","sortOrder":46},
  {"id":"s_work_nvlt_26_47","chapterId":"ch_work_nvlt_26","text":"晉張协詩，瓴甋夸玙璠，魚目笑明月，不見郢中歌，能否居然別，陽春無和者，巴人皆下節。","sortOrder":47},
  {"id":"s_work_nvlt_26_48","chapterId":"ch_work_nvlt_26","text":"又曰：此乡非吾地，此郭非吾城，折冲樽俎間，製勝在兩楹，巧遲不足稱，拙速乃垂名。","sortOrder":48},
  {"id":"s_work_nvlt_26_49","chapterId":"ch_work_nvlt_26","text":"宋謝靈運憶山中詩曰：采菱調易急，江南歌不缓，楚人心昔絕，越客腸今斷，斷絕雖殊念，俱為歸慮款。","sortOrder":49},
  {"id":"s_work_nvlt_26_50","chapterId":"ch_work_nvlt_26","text":"又詩，韓亡子房奋，秦帝魯連恥，本自江海人，忠義感君子。","sortOrder":50},
  {"id":"s_work_nvlt_26_51","chapterId":"ch_work_nvlt_26","text":"宋謝惠連詩，夕坐苦多慮，行歌踐閨中，房栊引傾月，步簷結春風。","sortOrder":51},
  {"id":"s_work_nvlt_26_52","chapterId":"ch_work_nvlt_26","text":"宋鮑昭雜詩，十五諷詩書，篇翰靡不通，弱冠參多士，飛步遊春宮，侧睹君子論，預見古人風，兩說窮舌端，五車摧筆鋒，羞當白璧貺，恥受聊城功，晚節從世務，乘鄣遠和戎，解珮袭犀渠，卷帙奉盧弓，始原力不及，安知命不終。","sortOrder":52},
  {"id":"s_work_nvlt_26_53","chapterId":"ch_work_nvlt_26","text":"齊謝朓冬緒羁懷詩曰：去國懷丘園，入遠滯城闕，寒燈耿宵夢，清鏡悲晓發，風草不留霜，冰池共如月。","sortOrder":53},
  {"id":"s_work_nvlt_26_54","chapterId":"ch_work_nvlt_26","text":"梁江淹效阮公詩曰：歲暮多懷傷，中夕弄清琴，戾戾曙風急，团团明月陰，愁雲出北山，宿鳥驚東林，誰謂人道曠，忧慨自相尋，寧知霜雪後，獨見竹柏心。","sortOrder":54},
  {"id":"s_work_nvlt_26_55","chapterId":"ch_work_nvlt_26","text":"又曰：十五學詩書，顏華常美好，不逐世間人，斗雞東郊道，富貴如浮雲，金玉不為寶，一旦鶗窸鳴，嚴霜被劲草，志氣多感失，泣下霑懷抱。","sortOrder":55},
  {"id":"s_work_nvlt_26_56","chapterId":"ch_work_nvlt_26","text":"又曰：夕雲映西山，蟋蟀吟桑梓，零落被百草，秋風吹桃李，君子懷苦心，感慨不能止，駕言遠行遊，驅馬清河涘，寒暑更進退，金石有終始，光色俯仰間，英艳難久恃。","sortOrder":56},
  {"id":"s_work_nvlt_26_57","chapterId":"ch_work_nvlt_26","text":"梁吳均詠懷詩曰：仆本報恩人，走馬救東秦，黃龍暗迢遞，青泥寒苦辛，野戰劍鋒盡，攻城才智貧，唯餘一死在，留持赠主人。","sortOrder":57},
  {"id":"s_work_nvlt_26_58","chapterId":"ch_work_nvlt_26","text":"又曰：元淑势位卑，長卿宦情寡，二頃且營田，三錢聊飲馬，懸風白雲上，掛月青山下，心中欲有言，未得忘言者。","sortOrder":58},
  {"id":"s_work_nvlt_26_59","chapterId":"ch_work_nvlt_26","text":"周庾信詠懷詩曰：步兵未飲酒，中散未彈琴，萧索無真氣，昏昏有欲心，涸鲋常思水，驚飛每失林，風雲能变色，松竹且悲喑，由來不得意，何必往長岑。","sortOrder":59},
  {"id":"s_work_nvlt_26_60","chapterId":"ch_work_nvlt_26","text":"又曰：無悶無不悶，有待何可待，昏昏如坐霧，漫漫疑行海，千年水未清，一代人先改，昔說東陵侯，唯見瓜園在。","sortOrder":60},
  {"id":"s_work_nvlt_26_61","chapterId":"ch_work_nvlt_26","text":"又曰：畴昔國士遇，生平知己恩，直言殊可吐，寧知炭欲吞，一顧重尺璧，千金輕一言，悲傷劉孺子，凄怆史皇孫，無因同武騎，歸守灞陵園。","sortOrder":61},
  {"id":"s_work_nvlt_26_62","chapterId":"ch_work_nvlt_26","text":"又曰：周王逢鄭忿，楚後值秦冤，梯冲已鶴列，冀馬忽雲屯，武安簷瓦振，崑陽猛獸奔，流星夕照境，烽火夜燒原，古獄饒冤氣，空亭多枉魂，天道或可問，微子不忍言。","sortOrder":62},
  {"id":"s_work_nvlt_26_63","chapterId":"ch_work_nvlt_26","text":"又曰：萧條亭鄣遠，凄怆風尘多，關門臨白狄，城影入黃河，秋風別蘇武，寒水送荆軻，誰言氣蓋世，晨起帳中歌。","sortOrder":63},
  {"id":"s_work_nvlt_26_64","chapterId":"ch_work_nvlt_26","text":"隋顏之推古意詩曰：十五好詩書，二十彈冠仕，楚王賜顏色，出入章華里，作賦凌屈原，讀書夸左史，數從明月宴，或侍朝雲祀，登山摘紫芝，泛江采绿芷，歌舞未終曲，風尘闇天起，吳師破九龍，秦兵割千里，狐兔穴宗廟，霜露霑朝市，璧入邯鄲宮，劍去襄城水，不獲殉陵墓，獨生良足恥，悯悯思舊都，惻惻懷君子，白發闚明鏡，忧傷没餘齒。","sortOrder":64},
  {"id":"s_work_nvlt_26_65","chapterId":"ch_work_nvlt_26","text":"又曰：寶珠出東國，美玉產南荆，隨侯曜我色，卞氏飛吾聲，已加明稱物，复飾夜光名，驪龍旦夕駭，白虹朝暮生，華彩燭兼乘，价直距連城，常悲黃雀起，每畏靈蛟迎，千刃安可舍，一毀難复營，昔為時所重，今為時所輕，原與濁泥會，思將垢石併，歸真川嶽下，抱润潛其榮。","sortOrder":65},
  {"id":"s_work_nvlt_26_66","chapterId":"ch_work_nvlt_26","text":"【賦】後漢冯衍顯志賦曰：冯子以大人之德，不碌碌如玉，硌硌如石，風興雲蒸，一龍一蛇，合道翱翔，與時变化，夫豈守一節哉，上隴阪，騰高岡，遊精宇宙，流目八紘，眇然有思凌雲之意，乃作賦自廣，命篇曰顯志雲，开歲發春，百卉含英，甲子之朝兮，汨吾西征，發軫新丰兮，徘徊鎬京，凌飛廉而太息，登平陽而懷傷，悲世俗之险阨，哀好惡之無常，弃衡石而意量兮，隨風波而飛扬，陟九嵕而臨〈山截〉嶭，聽涇渭之波聲，歲忽忽而日邁兮，寿冉冉而不與，恥功業之無成兮，赴原野而窮處，陟隴山以逾望，眇然覽於八荒，風波飄其併興兮，情惆怅而增傷。覽天地之幽奧兮，統萬物之維綱，究陰陽之变化兮，昭五德之精光，高吾冠之岌岌兮，長吾珮之洋洋，飲六醴之清液，食五芝之茂英，嘉孔丘之知命兮，大老聃之貴榮玄，德與道其孰能寶，名與身其孰親。","sortOrder":66},
  {"id":"s_work_nvlt_26_67","chapterId":"ch_work_nvlt_26","text":"後漢班固幽通賦曰：系高頊之玄胄兮，氏中葉之炳靈，飄凯風而蝉蜕兮，雄朔野以颺聲，皇十紀而鸿漸兮，有羽儀於上京，魂豭豭與神交兮，精誠發於宵寐，夢登山而回眺兮，觌幽人之仿佛，惟天地之無窮兮，鮮民生之晦在，紛屯邅與蹇連兮，何艱多而智寡，昔衛叔之御崑兮，崑為寇而丧予，管弯弧欲毙讎兮，讎作後而成已，变化故而相诡兮，孰雲豫其終始，雍造怨而先賞兮，丁由惠而被戮，栗取弔於由吉兮，王膺慶於所蹙，叛回穴其若茲兮，北叟頗識其倚伏，宣曹興败於下夢兮，魯衛名謚於銘謠，妣聆呱而刻石兮，許相理而鞠條，道混成而自然兮，術同源而分流，所貴聖人之至論兮，順天性而斷誼，物有欲而不居兮，亦有惡而不避，三仁殊而一致兮，夷惠異而齊聲，木偃息以藩魏兮，申重茧而存荆，紀焚躬以衛上兮，皓颐志而弗傾，侯草木之區別兮，苟能實其必榮，要没世而不朽，乃先民之所程，觀天網之紘覆兮，實匪諶而相訓，謨先聖之大猷兮，亦鄰德而助信，虞韶美而儀鳳兮，孔忘味於千載，素文信而底麟兮，漢賓祚於異代。","sortOrder":67},
  {"id":"s_work_nvlt_26_68","chapterId":"ch_work_nvlt_26","text":"魏陳王曹植玄畅賦曰：夫富者非财也，貴者非寶也，或有輕爵祿而重榮聲者，或有受性命以殉功名者，是以孔老異旨，楊墨殊義，聊作斯賦，名曰玄畅，夫何希世之大人，罄天壤而作皇，該仁聖之上義，據神位以統方，補五帝之漏目，缀三代之維綱，僥餘生之幸祿，遘九二之嘉祥，上同契於稷禼，降合穎於伊望，思荐寶以繼佩，怨和璞之始镌，思黃鍾以协律，怨伶夔之不存，考所圖之莫合，怅蘊結而延佇，志鵬舉以補天，蹶青雲而奋羽，舍餘驷而改駕，任中才之法御，望前軌而致策，顧後乘而安驅，匪逞邁之短修，取全真而保素，弘道德而為宇，筑無怨以作蕃，播慈惠以為圃，耕柔順以為田，不媿景而慚魄，信樂天之何欲，逸千載而流聲，超貴黎而度俗。","sortOrder":68},
  {"id":"s_work_nvlt_26_69","chapterId":"ch_work_nvlt_26","text":"又幽思賦曰：倚高台之曲嵎，處幽僻之閒深，望翔雲之悠悠，差朝濟而夕陰，顧秋華之零落，感歲暮而傷心，觀躍魚於南沼，聆鳴鶴乎北林，搦素筆而慷慨，扬大雅之哀吟，仰清風以叹息，寄予思於悲絃，信有心而在遠，重登高以臨川，何餘心之煩错，寧翰墨之能傳。","sortOrder":69},
  {"id":"s_work_nvlt_26_70","chapterId":"ch_work_nvlt_26","text":"魏劉楨遂志賦曰：幸遇明後，因志東傾，披此丰草，乃命小生，生之小矣。何茲雲當，牧馬於路，役車低昂，怆恨惻切，我獨西行，去峻溪之鸿洞，觀日日於朝陽，釋藂棘之餘刺，踐槚林之柔芳，皦玉粲以曜目，榮日華以舒光，信此山之多靈，何神分之煌煌，聊且遊觀，周歷高岑，仰攀高枝，侧身遺陰，磷磷〈石阑〉々，以廣其心，伊天皇之树葉，必結根於仁方，梢吳夷於東隅，掣畔臣乎南荆，戢幹戈於內库，我馬縶而不行，扬洪恩於無涯，聽頌聲之洋洋，四宇莫以無為，玄道穆以普將，翼俊乂於上列，退仄陋於下場，袭初服之芜薉，讬蓬芦以遊翔，豈放言而雲爾，乃旦夕之可忘。","sortOrder":70},
  {"id":"s_work_nvlt_26_71","chapterId":"ch_work_nvlt_26","text":"魏丁儀厲志賦曰：覽前志而博觀，求餘心之所安，雖疲駑而才弱，敢舍力而不攀，懿躬稼之克任，賤善射而陨殘，羨首陽之遺譽，憎千驷之餘訕，宗舍藏之伟節，薄鼎角之自幹，嘉法言之令扬，悼說難之丧韓，鑒登险之败績，顧清道以自閒，瞻亢龍而懼進，退廣志於伐檀，雖德厚而祚卑，猶不忘於盤桓，薰以芬香而自燒，兔亦取毙於豪翰，援大雅以為戒，眺龚勝而自叹，嗟世俗之參差，將未審乎好惡，鹹隨情而與議，固真伪以紛错，秽杯盂之周用，令瑚璉以抗閣，恨騾驢之進庭，屏騏骥於溝壑，疾青蠅之染白，悲小弁之靡讬，惡晨婦之蒙厚，痛三代之見薄，惟受性之朴拙，亮未達乎测度，顧鍾子之既没，牙輟絃而不作，敦三思之弥憤，勤循牆之茲恪，勉夕改以補朝，履日新而悔昨。","sortOrder":71},
  {"id":"s_work_nvlt_26_72","chapterId":"ch_work_nvlt_26","text":"魏韦鋋［按當作誕。］叙志賦曰：胤鸿烈之末流，蒙祖考之餘德，奉過庭之明訓，納微躬於軌則，勉四民之耕耘，遂能辯乎菽麥，自弱冠而立朝，無匡時之異才，每寤寐以叹息，思損己而降階，遭大魏之革命，罔群士於行職，雖固陋之無用，猶收錄而序飾，歷文武於機衡，擁大璫於帝侧，隨倫儕以按牒，乃剖符而封殖，顧儀服而增憤，心夕惕以愧恧，蒙聖皇之宏恩，過待罪於卿士，奏朝請於朔望，恭禋享於郊祀，念餘年之冉冉，忽一過其如馳，微奇功以佐時，徒曠官其何為，匪遜讓之足殉，信神氣之稍衰，將訴誠於明後，乞骸骨而告歸，晉夏侯惇懷思賦曰：何天地之悠長，悼人生之短淺，思縱欲以求歡，苟抑沉以避免，嗟聖王之製作，所以貴夫善善，信循道以從法，何世路之迍蹇，始絜操以迄今，每適道而靡违，思典言以攝事，弗履過而循非，恒戰戰以矜栗，杜秽衅而防微，斂規節以踐跡，冀天鑒之祐誠，勤恭肅以端厲，常苦心而勞形，桑榆掩其薄没，既白首而無成，世務多故，吾固甘夫無為，名不足以為尚，空勞秽以自卑，永無事以安神，故幸殁之無知。","sortOrder":72},
  {"id":"s_work_nvlt_26_73","chapterId":"ch_work_nvlt_26","text":"晉棗據表志賦曰：據忝職門下，在帷幄之末，與群士斜齊，［句有訛，全晉文六十七斜作叙。］登玉陛，待日月，久矣，出為冀州刺史，犬馬恋主，既有微情，且志之所存，不能無言，因而賦之曰：過承嘉惠，擢身泰晨，俯躡丹墀，仰承三辰，當樂夏之颽南，蒙朱陽之和仁，接鳴鸞之垂翼，因神虬之光鱗，浮眇末之纖质，濟吾身於天津，邈盧敖之所涉，階多士之遺尘，登九垓之虛軌，觌汗漫之威神，情飄飄而凌雲，意仿佛於真人，扶搖薄於懸圃，增城鬱以嵯峨，被羽衣之飛飛，握若蕙之芳華，蹈糾紛之絕軌，攀大椿之疏柯，意翘翘而慕遠，思濯發於天波，悲落葉之思條，情恋恋於昊仓，懷聖德之弘施，情惨切而內傷，感有莘之媵臣，原致主於陶唐。","sortOrder":73},
  {"id":"s_work_nvlt_26_74","chapterId":"ch_work_nvlt_26","text":"晉潘尼懷退賦曰：伊畴昔之懷憤，思天飛以遠跡，望循涂而投軌，溯翔風以理翮，冀雲霧之可凭，希天路之开辟，何時原之多违，奄就羁以服役，困吳坂之峻岨，畏鹽車之嚴筴，嗟遊處之弗遇，奚鬱悒之難任，背宇宙之寥廓，羅網罟之重深，常屏氣以斂跡，焉遊豫以娱心，傅釋板以亮殷，望投竿而相姬，窮獨善以全质，達兼利以濟時，聃安志於柱史，由抗跡於嵩箕，理殊涂而同歸，雖百慮其何思，敢因虛以讬談，遂逡巡而造辭。","sortOrder":74},
  {"id":"s_work_nvlt_26_75","chapterId":"ch_work_nvlt_26","text":"晉傅鹹申懷賦曰：何天施之弘普，廁瓦砾於琼瑛，備東宮之妙選，奉储君之聖明，穆穆清禁，濟濟群英，鸞翔鳳集，羽儀上京，芬芳併發，我秽其馨，德音光宣，我累厥聲，豈伊不媿，顧影慚形，雖自百於殒越，懼恩隆而命輕，命既輕而才下，谅無補於明時，塞賢哲之顯路，而尘損之日滋，匪躭榮而忘替，實結恋之有违，忍厚顏於寮類，甘獲戾而受譏，不悟皇恩之弥崇，授大縣乎近畿，畿雲近而防遠，情眷眷而含悲，悲則兼懷，忧慮寔深，雍可南面，千載晞心，微微小子，斯之莫任，莫斯之任，求仁在我，將反初服，畢志訓雅，盡乌鳥之至情，竭歡敬於膝下，進抗疏以歸誠，退抽簪而脂車，庶所乞之克從，永收跡於蓬庐。","sortOrder":75},
  {"id":"s_work_nvlt_26_76","chapterId":"ch_work_nvlt_26","text":"晉曹摅述志賦曰：慕浮雲以抗操，躭箪食之自娱，羨首陽之皎節，叹南山之高疏，哀夫差之溷惑，詠楚懷之失圖，悲伍員之沉悴，痛屈平之無辜，嘉沮溺之隱約，羨接舆之狂歌，顧大雅之先智，緯明哲之所經，微見機而遂逝，比舍生而親名，道殊涂而同歸，要逾世而併榮，舜拘忤於焚廪，孔怵惕於陳匡，紛迍蹇之若斯，何遭命之可常，情怳惚以回迷，夢乘雲而飛颺，駕麟鳳之靡靡，截龍旂之洋洋，周九州而騁目，登四嶽而永望，承聖喆而砥砺，奋羽儀而翱翔，被蘭戺之芳華，帶鍾山之玉英，飾吾冠之岌岌，美吾珮之玲玲，悲盛衰之遞處，情悠悠以紆結，攬萱草以掩淚，曾一叹而九咽。","sortOrder":76},
  {"id":"s_work_nvlt_26_77","chapterId":"ch_work_nvlt_26","text":"晉陆機遂志賦曰：昔崔篆作詩，以明道述志，而冯衍又作顯志賦，班固作幽通賦，皆相依仿焉，張衡思玄，蔡邕玄表，張叔哀系，此前世之可得言者也，崔氏簡而有情，顯志壮而泛濫，哀系俗而時靡，玄表雅而微素，思玄精練而何［集作和。］惠，欲麗前人，而優遊清典，漏［疑當作陋。］幽通矣，班生彬彬，切而不絞，哀而不怨矣，崔蔡冲虛溫敏，雅人之屬也，衍抑扬頓挫，怨之徒也，豈亦窮達異事，而聲為情变乎，餘備讬作者之末，聊复用心焉，武定鼎於洛汭，胡受瑞於汝墳，繇鳴鳳於百祀，啟敬仲乎方震，苟天光之所炤，豈舜族其必陳，厭禋祀於故墟，饗禴祭於東鄰，祢八葉而松茂，舞九韶乎降神，系薑叟於海曲，表沧流以遠震，仰前蹤之綿邈，豈孤人之能胄，匪世祿之敢懷，傷茲堂之不構，理或睽而後合，道有夷而弗順，傅栖巖而神交，伊荷鼎以自進，萧綢缪於丰沛，故攀龍而先躍，陳傾覆於楚魏，亦陵霄以自濯，伍被刑而伏劍，魏和戎而擁樂，彼殊涂而併致，此同川而偏溺，禍無景而易逢，福有時而難學，惟萬物之運動，雖紛糾而相袭，隨性類以曲成，故圓行而方立，要信心而委命，援前脩以自呈，擬遺跡於成軌，詠新曲於故聲，任窮達以逝止，亦進仕而退耕，庶斯言之不渝，抱耿介以成名。又懷土賦曰：餘去家漸久，懷土弥篤，方思之殷，何物不感，曲街委巷，罔不興詠，水泉草木，鹹足悲焉，故述斯賦，背故都之沃衍，適新邑之丘墟，遵黃川以葺宇，被蒼林而卜居，悼孤生之已晏，恨親没之何速，排虛房而永念，想遺尘其如玉，眇綿邈而莫覯，徒佇立其焉屬，感亡景於存物，惋隤年於拱木，悲顧眄而有餘，思俯仰而自足，留茲情於江介，寄瘁貌於海曲，玩通川以悠想，撫歸涂而踯躅，伊踯躅之徒勤，惨歸途之良難，愍栖鳥於南枝，弔離禽於別山，念庭树以悟懷，憶路草而解顏，甘堇荼於飴茈，緯萧艾其如蘭，神何寢而不夢，形何興而不言。","sortOrder":77},
  {"id":"s_work_nvlt_26_78","chapterId":"ch_work_nvlt_26","text":"梁元帝玄覽賦曰：歲次旃蒙，月建司空，变蕤賓之呂，扇廣莫之風，萧子褰帷九水，作牧三宮，乃盱衡而言曰：唯天為大，唯尧則之，唯地為厚，唯王國之，粵羲皇之握鏡，實乃神而乃聖，陳六聯於八則，弘九職於三令，惟天縱於副後，逾啟誦而為首，既論儒而肅成，复斷獄於長寿，爾其湘水之東，即我龟蒙，魏正元而分邑，吳太平而定中，镇鱗山之崔嵬，傍龍跡而穹隆，將遊目於五湖，夕結覽於姑蘇，臨閶門之跨水，耸重闕而开都，觀泉亭之涌波，窟巍巍而瓘瓘，張素蓋而萦洲屿，馳白馬而赴江沱，登舜桥而延首，暇禹井而淹留，御史之床猶在，督護之門不脩，詳夫皇王爰處，本無定所，尧都平陽，舜在冀方，商王居亳，成周卜洛，故知黃旗紫蓋，域中為大，天地之所合，風雲之所會，爰八命而建旟，誠非親而勿居，應鳴鞞於龍角，覆緹幕於熊車，經釣台而高邁，過鄂渚而西浮，变青門之三袭，為黃尘之一丘，臨章華而留眄，見舊楚之凄涼，试極目乎千里，何春心之可傷，其渚宮也，夹江帶阡，布濩井田，通逵交迸，高門接連，人腰水心之劍，家給火耕之田，爾乃树之榛栗，椅桐梓漆，三巴黃甘，千戶朱橘，矧高宴於城隅，駐五馬而踟蹰，乃有青琴碧玉，絳树绿珠，西河王豹，東野綿駒，蘭缸夕燃，合璧斜天，照流風之回雪，映出水之初莲，奉信珪而入朝，驅駿驷而乘轺，既總司於戍旅，亦兼飾於丰貂，幼墳籍以自娱，迄方今而不渝，雲氣芝英之簡，懸針倒薤之書，擬河獻之留真，希淳於之席珍，臨秋水之至樂，登春台而目欣，凿戶牖而長望，混木雁而兼陳，嗟今來而古往，聊絕筆於獲麟。","sortOrder":78},
  {"id":"s_work_nvlt_26_79","chapterId":"ch_work_nvlt_26","text":"又言志賦曰：天文既表，人文可觀，知負扆之來易，信握鏡之雲難，差立極而補天，验璧合而珠連，有庖羲之八索，稱朱襄之五絃，聞夏王之鑄鼎，重農皇之播田，雖車軌之未同，亶弥媿於棟隆，戮封豕於海內，斬長狄於區中，懷宿昔之玙璠，併來遊於菟園，悲元瑜之已逝，叹靈光之獨存，想延賓於北閣，因置酒於南軒，聞湋鳴而懷友，聽長笛其何言，夙有尚於清靜，叨再□［原坏，疑是駐字。］於鄢郢，東窥文命之穴，南望鸿崖之井，遂撫運而登庸，谬垂旒而卷領，雖有愧於前英，每求衣於未明，召司烜而照夜，觀執珪而滿庭，誠雖休以勿休，寔旨酒之忘忧，絕何楊之妙舞，废綿駒之善謳，彼知止與知足，复何營而何欲，柱何用於黃金，案寧勞於青玉，爾乃高步北園，用荡嚣煩，桂偃蹇而臨棟，石穹隆而架門，對灌木之脩耸，觀激水之飛奔，涧不風而自响，天無雲而晝昏，聞賓鸿之夜飛，想過沛而霑衣，况登樓而作賦，望懷海而思歸。","sortOrder":79},
  {"id":"s_work_nvlt_26_80","chapterId":"ch_work_nvlt_26","text":"【書】漢司馬遷報任安書曰：仆亦嘗廁下大夫之列，陪奉外廷末議，不以此時，引維綱，盡思慮，今已虧形為埽除之隸，在阘茸之中，乃欲仰首伸眉，論列是非，不亦輕朝廷羞當世之士邪，仆與李陵，俱居門下，素非相善也，趨舍異路，未嘗衔杯酒，接殷勤之餘歡，今舉事一不當，而全軀保妻子之臣，隨而媒蘖其短，仆誠私心痛之，且李陵提步卒，不滿五千，深踐戎馬之地，矢盡道窮，救兵不至，士卒死傷如積，然李陵一呼勞軍，士卒無不起，張空拳，冒白刃，北乡爭死敵者，愚以為李陵素與士大夫絕甘分少，能得人之死力，雖古名將不過也，身雖陷败，亦足以曝於天下也，適會召問，即以此指，推言陵之功，欲以廣主上之意，塞睚眦之辭，未能盡明，明主不晓，以為仆沮貳師，而為李陵遊說，遂下於理，奉拳拳之忠，終不自明，交遊莫救视，左右親近不為一言，身非木石，獨與法吏為伍，深幽囹圄之中，誰可告愬者，此真少卿所親見，仆行事豈不然乎，且夫臧獲婢妾，猶能引决，况仆之不得已乎，所以隱忍苟活，身函粪土之中而不辭者，鄙没世而文采不表於後世也，古者富貴而名磨滅，不可勝記，唯倜傥非常之人稱焉，蓋西伯拘而演周易，仲尼厄而作春秋，屈原放逐，乃賦離骚，左丘失明，厥有《國語》：孫子臏腳，兵法修列，不韦遷蜀，世傳呂覽，韓非囚秦，說難孤憤，詩三百篇，大抵賢聖發憤之所為作也，仆竊不遜，近自讬於無能之辭，網羅天下放失舊聞，略考其行事，綜其終始，稽其成败興坏之紀，欲以究天地之际，通古今之变，成一家之言，惜其不成，是以就極刑而無慍色，仆誠已著此書，藏之名山，傳之其人，通邑大都，則仆偿前辱之责，雖萬被戮，豈有悔哉，然此可為智者道，難為俗人言也。","sortOrder":80},
  {"id":"s_work_nvlt_26_81","chapterId":"ch_work_nvlt_26","text":"漢楊惲報孫會宗書曰：惲家方隆盛時，乘朱輪者五十人，位在列卿，爵為通侯，總領從官，與聞政事，曾不能以此時有所建明，以宣德化，已負竊位素餐之责久矣，懷祿貪势，不能自退，遂遭变故，橫被口語，身幽北闕，妻子滿獄，當此之時，自以夷滅不足以塞责，豈意得全首領，复奉先人之丘墓乎，伏惟聖主之恩，不可勝量，君子遊道，樂以忘忧，小人全軀，悅以忘罪，竊自思念，過已久矣，行已虧矣，長為農夫，以没世矣，是故身奉［《文選》四十一作率。］妻子，戮力耕桑，灌田治產，以給公上，不意當复用此為譏議也，田家作苦，歲時伏腊，烹羊炮羔，斗酒自勞，家本秦地，能為秦聲，婦趙女也，雅善鼓瑟，奴婢歌者數人，酒後耳熱，仰天撫缶而呼呜呜，其詩曰：田彼南山，芜秽不治，种豆一頃，落而為萁，人生行樂耳，須富貴何時，是日也，拂衣而喜，奋袖低昂，頓足起舞，誠淫荒無度，不知其不可也，惲幸有餘祿，方籴賤販貴，逐什一之利，下流之人，眾毀所歸，不寒而栗，雖雅知憚者，猶隨風而靡，尚何稱譽之有，道不同，不相為謀，今子尚安得以卿大夫之製而责仆哉。","sortOrder":81},
  {"id":"s_work_nvlt_26_82","chapterId":"ch_work_nvlt_26","text":"魏文帝與吳质書曰：季重無恙，涂路雖局，官守有限，原言之懷，良不可任，足下所治僻左，書問致簡，益用增勞，每念昔日南皮之遊，誠不可忘，既妙思六經，逍遙百氏，彈琴間設，終以博弈，高談娱心，哀筝順耳，馳騁北場，旅食南馆，浮甘瓜於清泉，沉朱李於寒水，白日既匿，繼以朗月，同乘共載，以遊後園，舆輪徐動，賓從無聲，清風夜起，悲笳微吟，樂往哀來，怆然傷懷，餘顧而言，斯樂難常，足下之徒，鹹以為然，今果分別，各在一方，元瑜長逝，化為異物，每一念至，何時可言，方今蕤賓紀時，景風扇物，天意和暖，眾果具繁，時駕而遨，北遵河曲，從者鳴笳以啟路，文學讬於後車，節同時異，物是人非，我勞如何。","sortOrder":82},
  {"id":"s_work_nvlt_26_83","chapterId":"ch_work_nvlt_26","text":"又曰：昔日遊處，行則連舆，立則接席，何曾須臾相失，每至觴酌流行，絲竹併奏，酒酣耳熱，仰而賦詩，當此之時，忽然不自知樂也，何圖數年之間，零落略盡，言之傷心，頃撰其遺文，都為一集，觀其姓名，已為鬼錄，追思昔遊，猶在心目，而此諸子，化為粪壤，可复道哉，歷覽諸子之文，對之收淚，既痛逝者，行自念也，年行已長大，所懷萬端，時有所慮，至乃通夕不暝，志意何時复類往昔邪，已成老翁，但未白頭爾。","sortOrder":83},
  {"id":"s_work_nvlt_26_84","chapterId":"ch_work_nvlt_26","text":"魏陳王曹植與吳质書曰：前日雖因常調，得為密坐，雖宴飲弥日，其於別遠會稀，不盡其勞積也，若夫觴酌凌波於前，笳箫發音於後，足下鷹扬其體，鳳翔虎视，謂萧曹不足儔，衛霍不足侔也，左顧右盻，謂若無人，豈若吾子之壮志哉，過屠門而大嚼，雖不得肉，貴且快意，當斯之時，原舉太山以為肉，齊東海以為酒，伐雲夢之竹以為笛，斬泗濱之梓以為筝，食若填巨壑，飲若灌漏卮，其樂固難量，豈非大丈夫之樂哉，然日歲不我與，曜靈急節，面有逸景之速，別有參商之闊，思抑六龍之首，頓羲和之辔，折若木之華，閉濛汜之穀，天路高邈，良無由緣。","sortOrder":84},
  {"id":"s_work_nvlt_26_85","chapterId":"ch_work_nvlt_26","text":"魏吳质答太子書曰：奉讀手命，追亡慮存，恩哀之隆，形於文墨，日月冉冉，歲不我與，昔侍左右，廁坐眾賢，出有微行之遊，入有管絃之歡，置酒樂飲，賦詩稱寿，自謂可終始相保，併聘材力，效節明主，何意數年之間，死丧略盡，臣獨何德，以堪久長，徐陳劉應，才學所著，誠如來命，惜其不遂，可謂痛切，凡此數子，於雍容侍從，實其人也，若乃邊境有虞，群下鼎沸，軍書輳至，羽檄交馳，於彼諸賢，非其任矣，往者孝武之世，文章為盛，若東方朔枚皋之徒，不能持論，即阮陳之流也，其唯嚴助寿王，與聞政事，然皆不損其身，善謀於國，卒以败亡，臣竊恥之，至於司馬長卿，稱疾避事，以著撰為務，則徐生庶幾焉，而今各逝，已為異物。","sortOrder":85},
  {"id":"s_work_nvlt_26_86","chapterId":"ch_work_nvlt_26","text":"又答陳思王曹植書曰：信到，奉所惠貺，發函伸紙，是何文采之巨麗，而慰喻之綢缪乎，夫登東嶽者，然後知眾山之迤逦也，奉至尊，然後知百里之卑微也，身賤犬馬，德輕鸿毛，至乃歷玄關，排金門，升玉堂，伏櫺槛於前殿，臨曲池而行觴，既威儀虧替，言辭漏泄，雖恃平原養士之懿，愧無毛遂耀穎之才，深蒙薛公折節之禮，而無冯谖三窟之效，屢獲信陵虛左之德。又無侯生可述之美，凡此數者，乃质之所以憤積於胸襟，懷眷而於邑者也，若追前宴，謂之未究，欲傾海為酒，併山為肴，伐竹雲夢，斬梓泗濱，然後極雅意，盡歡情，信公子之壮觀，非鄙人之所庶幾也，若质之志，實在所天，思投印釋黻，朝夕侍坐，鑽仲父之遺訓，覽老氏之要言，對清酤而不酌，抑嘉肴而不享，使西施出帷，嫫母侍侧，斯盛德之所蹈，明哲之所保也，若乃近者之觀，實荡鄙心，秦筝發徽，二八迭奏，埙箫激於華屋，靈鼓動於坐左，耳嘈嘈而無聞，情踴躍於鞍馬，謂可北慑肅慎，使貢其楛矢，南震百越，使獻其白雉。又况權備，夫何足视乎，還治諷集所著，觀省英玮，實賦頌之宗，作者之師表也。","sortOrder":86},
  {"id":"s_work_nvlt_26_87","chapterId":"ch_work_nvlt_26","text":"晉羊祜與從弟書曰：吾以布衣，忝荷重任，每以尸素為愧，大命既隆，唯江南未夷，此人臣之责，是以不量所能，畢力吳會，當凭朝廷之威，賴士大夫之謀，以全克之舉，除萬世之患，年已朽老，既定邊事，當有角巾東路，還歸乡里，於墳墓侧，為容棺之墟，假日视息，思與後生味道，此吾之至原也，以凡才而居重位，何能不懼盈滿以责邪，疏廣吾師也，聖主明恕，當不奪微志爾。","sortOrder":87},
  {"id":"s_work_nvlt_26_88","chapterId":"ch_work_nvlt_26","text":"晉劉琨答盧諶書曰：書及詩，備辛酸之苦言，畅經通之遠旨，執玩反覆，不能釋手，慨然以悲，歡然以喜，昔在少壮，未當檢括，遠詠老莊之齊物，近嘉阮生之放曠，怪厚薄何由而生，哀樂何由而至，自頃诪張，困於逆亂，國破家亡，親友凋殘，塊然獨處，愧憤雲集，負杖行吟，則百忧俱至，時复相與，舉觴對膝，破涕為笑，排終身之積惨，求數刻之蹔歡，譬由疾疹弥年，而欲以一丸銷之爾，夫才生於世，而世實須才，和氏之璧，焉得獨曜於郢握，夜光之珠，無緣得玩於隨掌，天下之寶，固當與天下共之，但離索之日，不能不以怅恨爾。","sortOrder":88},
  {"id":"s_work_nvlt_26_89","chapterId":"ch_work_nvlt_26","text":"齊謝朏與王俭書曰：夫所貴天下之士者何，其上則閟景山壑，凌氣風霞，次則投缗舍筑，鬱為上佐，次則服秦楚而辭其功，振燕魏而逃其賞，凡此數辈，皆英懿之士也，自茲已降，參差萬緒，或跡著明晦，或才兼默語，若桓谭之褰俗，冯衍之忤時，北海之凝峭，中散之峻絕，率以方寸之情，丧不訾之德，蓋無取焉，若相如之愛奇，任伟長之淹粹弘遠，樂廣融通，裴楷夷淡，彼四賢者，併純神絕景，徇物傷意，其慕之而未可以言，但心之所暗，咫尺千里，志之所符，沧洲暧然，揣而論之，寔山河之不肖者也。","sortOrder":89},
  {"id":"s_work_nvlt_26_90","chapterId":"ch_work_nvlt_26","text":"梁簡文帝答徐摛書曰：山涛有雲，東宮養德而已，但今與古殊，時有監撫之務，竟不能黜邪進善，少助國章，獻可替不，仰裨聖政，以此慚遑，無忘夕惕，驅馳五嶺，在戎十年，险阻艱難，備更之矣，觀夫全軀具臣，刀筆小吏，未嘗識山川之形势，介胄之勤勞，細民之疾苦，風俗之嗜好，高閣之間可來，高門之地徒重，玉饌羅前，黃金在握，足訾粟斯，容與自憙，亦复言軒羲以來，一人而已，使人見此，良足長叹。","sortOrder":90},
  {"id":"s_work_nvlt_26_91","chapterId":"ch_work_nvlt_26","text":"梁王僧孺與何遜書［梁書王僧孺傳作何蜅。］曰：昔李叟入秦，梁生適越，猶懷恨怅，且或吟謠，况歧路之日，將離嚴網，辭無可怜，罪有不测，所以握手恋恋，離別珍重，弟愛同郭李，淫淫承睫，吾猶抗手分背，羞學婦人，顧實不肖，文质無所抵，蓋困在衣食，迫於飢寒，非有奇才，絕略高談，吐一言可以匡俗振民，動一議可以固邦興國，全璧歸趙，飛矢投燕，偃息藩魏，甘臥安郢，腦日逐，髓月支，擁十萬而橫行，提五千而深入，將能執珪裂壤，功勒景鍾，錦繡為衣，朱丹被轂，斯蓋大丈夫之志，非吾曹之所能及，除舊布新，清晷方旦，抱樂衔圖，訟謳有主，一旦陪武帳，仰文枇，備聃佚之柱下，充嚴朱之席上，入班九棘，出专千里，未有躡景追風，奔骤之若此者也，蓋基薄牆高，涂遙力踬，司隸懍懍，思得應絃，譬懸厨之獸，如離繳之鳥，將充庖鼎，以餌鷹鹯，雖事異鑽皮，文非次骨，猶复因茲舌杪，成此筆端，上可以投畀北方，次可以論諭左校，幸聖主留善貸之德，紆好生之施，解網祝禽，下車泣罪，所謂還魄斗極，追風奉高，蓋士無賢不肖，在朝見嫉，女無美惡，入宮見妒，外無奔走之友，內乏彊近之视，是以媾市之徒，隨相媒蘖，一朝捐弃，以快怨者之心，吁可悲矣，蓋先貴後賤，古富今貧，李流所以發此哀音，雍門所以扣其悲曲。又迫以嚴秋殺氣，萬物多悲，長夜展轉，百忧俱至，况复露鋪草色，風搖树影，寒虫夕叫，含輕重而同悲，秋葉晚傷，雜黃紫而俱墜，悲夫，豈复得與二三士友，抗首接膝，履足差肩，摛綺縠之清文，談希夷之至道，唯吳凭之遇夏馥，范式之值孔嵩，愍其留賃，怜此行乞爾。","sortOrder":91},
  {"id":"s_work_nvlt_26_92","chapterId":"ch_work_nvlt_26","text":"又答江琰書曰：猥惠嘉音，用蠲疾首，發函伸紙，朗若披雲，等嶰穀之清音，比洞庭之高曲，辭則美矣，而擬其非倫，譬享海鳥以醇醪嘉膳，栖林狖以崇楹曾栱，苟非其實，立有驚怖，况复以一離訴弃，賓實漼然，豈复能使一笥可輕，八厨斯引，且登清漢，乍弃黃汙，望影析支，爭涂再楫，其或蹲林臥石，籍卉班荆，不過田畯野老，漁父樵客，酌醴焚枯，呜呜相勞，羹藜含糗，果然滿腹，寧有幡旗貴客，車馬大賓，獻書盡先賢之德，作頌罄前皇之美，豈不俯拾青紫，坐享大夫，况复詠高梧而賦脩竹，背清淮而遊長范，留東閤以從容，登石室而高视，豈與夫身没名陨，同年而共毀譽哉。","sortOrder":92},
  {"id":"s_work_nvlt_26_93","chapterId":"ch_work_nvlt_26","text":"《藝文類聚》　唐·欧陽詢","sortOrder":93},
  {"id":"s_work_nvlt_27_1","chapterId":"ch_work_nvlt_27","text":"卷二十七人部十一","sortOrder":1},
  {"id":"s_work_nvlt_27_2","chapterId":"ch_work_nvlt_27","text":"○行旅","sortOrder":2},
  {"id":"s_work_nvlt_27_3","chapterId":"ch_work_nvlt_27","text":"◇行旅","sortOrder":3},
  {"id":"s_work_nvlt_27_4","chapterId":"ch_work_nvlt_27","text":"《爾雅》曰：征，邁，行也。","sortOrder":4},
  {"id":"s_work_nvlt_27_5","chapterId":"ch_work_nvlt_27","text":"《易》曰：天行健。","sortOrder":5},
  {"id":"s_work_nvlt_27_6","chapterId":"ch_work_nvlt_27","text":"又曰：牝馬地類，行地無疆。","sortOrder":6},
  {"id":"s_work_nvlt_27_7","chapterId":"ch_work_nvlt_27","text":"又曰：利有攸往。","sortOrder":7},
  {"id":"s_work_nvlt_27_8","chapterId":"ch_work_nvlt_27","text":"《毛詩》曰：周大夫行役，過故宗廟宮室，盡為禾黍，彷徨而不忍去。","sortOrder":8},
  {"id":"s_work_nvlt_27_9","chapterId":"ch_work_nvlt_27","text":"又曰：行邁靡靡，中心搖搖。","sortOrder":9},
  {"id":"s_work_nvlt_27_10","chapterId":"ch_work_nvlt_27","text":"又曰：周公東征，三年而歸。","sortOrder":10},
  {"id":"s_work_nvlt_27_11","chapterId":"ch_work_nvlt_27","text":"又曰：我徂東山，慆慆不歸，我來自東，零雨其濛。","sortOrder":11},
  {"id":"s_work_nvlt_27_12","chapterId":"ch_work_nvlt_27","text":"又曰：我行其野，芃芃其麥。","sortOrder":12},
  {"id":"s_work_nvlt_27_13","chapterId":"ch_work_nvlt_27","text":"又曰：惠而好我，携手同行。","sortOrder":13},
  {"id":"s_work_nvlt_27_14","chapterId":"ch_work_nvlt_27","text":"又曰：行道遲遲，中心有违。","sortOrder":14},
  {"id":"s_work_nvlt_27_15","chapterId":"ch_work_nvlt_27","text":"《尚書》曰：歲二月，東巡狩，至於岱宗，五月，南巡狩，至於南嶽，八月，西巡狩，至於西嶽，十有一月，北巡狩，至於北嶽。","sortOrder":15},
  {"id":"s_work_nvlt_27_16","chapterId":"ch_work_nvlt_27","text":"《左氏傳》曰：不有居者，誰守社稷，不有行者，許扞牧圉。","sortOrder":16},
  {"id":"s_work_nvlt_27_17","chapterId":"ch_work_nvlt_27","text":"又曰：先王卜征五年，歲袭其祥，祥習乃行。","sortOrder":17},
  {"id":"s_work_nvlt_27_18","chapterId":"ch_work_nvlt_27","text":"又曰：行李之往來，共其資糧屝屦，其可也。","sortOrder":18},
  {"id":"s_work_nvlt_27_19","chapterId":"ch_work_nvlt_27","text":"又曰：凡公行，告於宗廟，反行飲至，舍爵策勋焉，禮也。","sortOrder":19},
  {"id":"s_work_nvlt_27_20","chapterId":"ch_work_nvlt_27","text":"又曰：君行師從，卿行旅從。","sortOrder":20},
  {"id":"s_work_nvlt_27_21","chapterId":"ch_work_nvlt_27","text":"又曰：昔周穆王欲肆其心，周行天下，將皆必有車轍馬跡焉。","sortOrder":21},
  {"id":"s_work_nvlt_27_22","chapterId":"ch_work_nvlt_27","text":"《禮記》曰：行則有隨，立則有序，行而無隨，則亂於行。","sortOrder":22},
  {"id":"s_work_nvlt_27_23","chapterId":"ch_work_nvlt_27","text":"《莊子》曰：黃帝將見大隗於具茨之山，方明為馭，昌宇參乘，於襄城之野，七聖皆迷，適遇牧馬童子，問涂焉。","sortOrder":23},
  {"id":"s_work_nvlt_27_24","chapterId":"ch_work_nvlt_27","text":"又曰：黃帝遊乎赤水之池，登於崑崙之丘。","sortOrder":24},
  {"id":"s_work_nvlt_27_25","chapterId":"ch_work_nvlt_27","text":"又曰：適百里者宿糧，適千里者，三月聚糧。","sortOrder":25},
  {"id":"s_work_nvlt_27_26","chapterId":"ch_work_nvlt_27","text":"《家語》曰：齊人歸女樂，魯君觀之，三日不朝，孔子遂行。","sortOrder":26},
  {"id":"s_work_nvlt_27_27","chapterId":"ch_work_nvlt_27","text":"《穆天子傳》曰：天子北征，絕漳水，西征，賓於王母，天子觴西王母瑤池之上。","sortOrder":27},
  {"id":"s_work_nvlt_27_28","chapterId":"ch_work_nvlt_27","text":"《史記》曰：禹乘四載，隨山刊木，山行乘轝，［史記夏本紀作〈木輦〉。］泥行乘橇，陆行乘車，水行乘舟。","sortOrder":28},
  {"id":"s_work_nvlt_27_29","chapterId":"ch_work_nvlt_27","text":"又曰：老子居周，久之，見周之衰，乃遂去關，關令尹喜曰：子將隱矣，喜與老子俱之流沙之西。","sortOrder":29},
  {"id":"s_work_nvlt_27_30","chapterId":"ch_work_nvlt_27","text":"又曰：秦始皇至雲夢，望祀虞舜於九疑，浮江，下觀丹陽，至錢唐，臨浙江，上會稽，祭大禹，望於南海，傍海，北至琅邪，《漢書》曰：武帝行幸雍，遂北出萧關，歷獨鹿鳴泽，自代而還。","sortOrder":30},
  {"id":"s_work_nvlt_27_31","chapterId":"ch_work_nvlt_27","text":"又曰：行幸至甘泉宮，賓禮外國客。","sortOrder":31},
  {"id":"s_work_nvlt_27_32","chapterId":"ch_work_nvlt_27","text":"又，行幸東海，獲赤雁。","sortOrder":32},
  {"id":"s_work_nvlt_27_33","chapterId":"ch_work_nvlt_27","text":"又，武帝南巡，至盛唐，祀虞帝於九疑，祭天柱山，自尋陽浮江，斬蛟江中，遂北至琅邪，傍海而還，所過名山大川。","sortOrder":33},
  {"id":"s_work_nvlt_27_34","chapterId":"ch_work_nvlt_27","text":"又曰：張騫為郎，募使月支，匈奴留之十餘年，騫持漢節不失，西走大宛，抵康居，傳至大月支王，從月支，至大夏，窮河源，廣地萬里，九譯致殊俗，威德遍於四海。","sortOrder":34},
  {"id":"s_work_nvlt_27_35","chapterId":"ch_work_nvlt_27","text":"【詩】古詩曰：驅車遠行役，悠悠涉長道，四顧何茫茫，東風搖百草，所遇無故物，焉得不速老。","sortOrder":35},
  {"id":"s_work_nvlt_27_36","chapterId":"ch_work_nvlt_27","text":"魏文帝詩曰：漫漫秋夜長，烈烈北風涼，展轉不能寐，披衣起彷佯，俯视清水波，仰看明月光，鬱鬱多愁思，綿綿思故乡，原飛安得翼，欲濟河無梁。","sortOrder":36},
  {"id":"s_work_nvlt_27_37","chapterId":"ch_work_nvlt_27","text":"又於明津作詩曰：遙遙山上亭，皎皎雲間星，遠望使心懷，遊子恋所生，驅車出北門，遙望河陽城。","sortOrder":37},
  {"id":"s_work_nvlt_27_38","chapterId":"ch_work_nvlt_27","text":"魏陳王曹植雜詩曰：悠悠遠行客，去家千餘里，出亦無所之，入亦無所止，浮雲翳日光，悲風動地起。","sortOrder":38},
  {"id":"s_work_nvlt_27_39","chapterId":"ch_work_nvlt_27","text":"又曰：遊魚潛渌水，翔鸞薄天飛，始出嚴霜結，今來白露稀。","sortOrder":39},
  {"id":"s_work_nvlt_27_40","chapterId":"ch_work_nvlt_27","text":"魏阮瑀詩曰：臨川多悲風，秋日苦清涼，客子易為戚，感此用哀傷，攬衣起踯躅，上觀心與房，三星守故次，明月未收光，雞鳴當何時，朝晨尚未央，還坐長叹息，忧忧安可忘。","sortOrder":40},
  {"id":"s_work_nvlt_27_41","chapterId":"ch_work_nvlt_27","text":"又曰：我行自凛秋，季冬乃來歸，置酒高堂上，友朋集光辉，念當复離別，涉路险且夷，思慮益惆怅，淚下霑裳衣。","sortOrder":41},
  {"id":"s_work_nvlt_27_42","chapterId":"ch_work_nvlt_27","text":"晉王贊詩曰：朔風動秋草，邊馬有歸心，昔往仓庚鳴，今來蟋蟀吟，人情懷舊乡，客鳥思故林。","sortOrder":42},
  {"id":"s_work_nvlt_27_43","chapterId":"ch_work_nvlt_27","text":"晉張协詩曰：述職投邊城，羁束戎旅間，下車如昨日，望舒三五圓，流波恋舊浦，行雲思故山。","sortOrder":43},
  {"id":"s_work_nvlt_27_44","chapterId":"ch_work_nvlt_27","text":"晉陆機赴洛詩曰：總辔登長路，呜咽辭密親，借問子何為，世網婴我身，永叹遵北渚，遺思結南津。","sortOrder":44},
  {"id":"s_work_nvlt_27_45","chapterId":"ch_work_nvlt_27","text":"又曰：遠遊越山川，山川脩且廣，振策陟崇丘，按辔遵平莽，夕息抱景寐，朝徂衔思往。","sortOrder":45},
  {"id":"s_work_nvlt_27_46","chapterId":"ch_work_nvlt_27","text":"又尸乡亭詩曰：東遊觀巩洛，逍遙丘墓間，秋草蔓長柯，寒木入雲煙，發軫有夙晏，息駕無愚賢。","sortOrder":46},
  {"id":"s_work_nvlt_27_47","chapterId":"ch_work_nvlt_27","text":"晉湛方生帆入南湖詩曰：彭蠡紀三江，庐嶽主眾阜，白沙净川路，青松蔚巖首，此水何時流，此山何時有，人運互推遷，茲器獨長久，悠悠宇宙中，古今迭先後。","sortOrder":47},
  {"id":"s_work_nvlt_27_48","chapterId":"ch_work_nvlt_27","text":"又還都帆詩曰：高嶽萬丈峻，長湖千里清，白沙窮年絜，林松冬夏青，水無暫停流，木有千載貞，寤言賦新詩，忽忘羁客情。","sortOrder":48},
  {"id":"s_work_nvlt_27_49","chapterId":"ch_work_nvlt_27","text":"晉成公綏詩曰：洋洋熊耳流，巍巍伊闕山，高岡碣崔嵬，双阜夹長川，素石何磷磷，水禽浮翩翩，遠涉許穎路，顧思邈綿綿，鬱陶懷所親，引領情緬然。","sortOrder":49},
  {"id":"s_work_nvlt_27_50","chapterId":"ch_work_nvlt_27","text":"宋陶潛赴假還江陵夜行涂口作詩曰：閒居三十載，遂與尘事冥，詩書敦宿好，園林無俗情，叩枻新秋月，臨流別友生，涼風起將夕，夜景湛虛明。","sortOrder":50},
  {"id":"s_work_nvlt_27_51","chapterId":"ch_work_nvlt_27","text":"宋謝靈運入東道路詩曰：整駕辭金門，命旅惟詰朝，懷居顧歸雲，指涂溯行飆，屬值清明節，榮華感和韶，陵隰繁绿杞，墟囿粲紅桃，鷕鷕翚方雊，纖纖麥垂苗，隱軫邑里密，緬邈江海遼，滿目皆古事，心賞貴所高，魯連謝千金，延州權去朝，行路既經見，原言寄吟謠。","sortOrder":51},
  {"id":"s_work_nvlt_27_52","chapterId":"ch_work_nvlt_27","text":"又之郡發都詩曰：述職期蘭署，理棹变金素，秋岸沉夕陰，火昊团朝露，辛苦誰為情，遊子值頹暮，生幸休明時，親蒙英達顧，空班趙氏聖，［《文選》二十六作璧。］徒乖魏王瓠，從來漸二紀，始得傍歸路，將窮山海跡，永絕賞心悟。","sortOrder":52},
  {"id":"s_work_nvlt_27_53","chapterId":"ch_work_nvlt_27","text":"又發石首城詩曰：白珪尚可磨，斯言以為緇，雖抱中孚爻，猶勞貝錦詩，寸心若不亮，微命察如絲，日月垂光景，成貸遂兼茲，出宿薄京畿，晨裝摶曾飔，重經平生別，再與朋知辭，故山日已遠，風波豈還時，遙遙萬里帆，茫茫終何之，钦聖若旦暮，懷賢亦凄其，皎皎明發心，不為歲寒欺。","sortOrder":53},
  {"id":"s_work_nvlt_27_54","chapterId":"ch_work_nvlt_27","text":"又七里瀨詩曰：孤客傷逝湍，徒旅苦奔峭，石淺水潺湲，日落山照曜。","sortOrder":54},
  {"id":"s_work_nvlt_27_55","chapterId":"ch_work_nvlt_27","text":"又初往新安桐庐口詩曰：感節良已深，懷古亦雲思，不有千里棹，孰申百代意，既及冷風善。又即秋水泱，江山共开曠，雲日相照媚，景夕群物清，對玩鹹可憙。","sortOrder":55},
  {"id":"s_work_nvlt_27_56","chapterId":"ch_work_nvlt_27","text":"又夜發石關亭詩曰：隨山逾千里，浮溪將十夕，鳥歸息舟楫，星阑命行役，亭亭晓月映，泠泠朝露滴。","sortOrder":56},
  {"id":"s_work_nvlt_27_57","chapterId":"ch_work_nvlt_27","text":"又彭蠡口詩曰：春晚绿野秀，巖高白雲屯，千念集日夜，萬感盈朝昏，攀崖照石鏡，牵葉入松門。","sortOrder":57},
  {"id":"s_work_nvlt_27_58","chapterId":"ch_work_nvlt_27","text":"又初發入南城詩曰：弄波不輟手，玩景豈停目，雖未登雲峰，且以歡水宿。","sortOrder":58},
  {"id":"s_work_nvlt_27_59","chapterId":"ch_work_nvlt_27","text":"又往臨川郡發石頭城詩曰：越海陵三山，遊湘歷九疑，钦聖若旦暮，懷賢亦凄其。","sortOrder":59},
  {"id":"s_work_nvlt_27_60","chapterId":"ch_work_nvlt_27","text":"宋顏延之北使至洛詩曰：振楫發吳州，秣馬陵楚山，涂出梁宋郊，道由周鄭間，前登陽城路，旦夕望三川，伊洛絕津濟，台馆無尺椽，宮階多巢穴，城闕生雲煙。","sortOrder":60},
  {"id":"s_work_nvlt_27_61","chapterId":"ch_work_nvlt_27","text":"宋鮑昭還都道中詩曰：昨夜宿南陵，今旦入芦洲，客行惜日月，崩波不可留，侵星赴早路，畢景逐前儔，發舻眺淮甸，掩泣望荆州，絕目盡平原，時見遠煙浮。","sortOrder":61},
  {"id":"s_work_nvlt_27_62","chapterId":"ch_work_nvlt_27","text":"又從臨海王西镇發新亭詩曰：客行有苦樂，但問客何行，攀龍不待翼，附骥絕尘冥，梁珪分楚牧，羽鹢指全荆，狐兔懷窟志，犬馬恋主情。","sortOrder":62},
  {"id":"s_work_nvlt_27_63","chapterId":"ch_work_nvlt_27","text":"又登黃鵠圻詩曰：適郢無東轅，過夏有西浮，三崖隱丹隥，九派引蒼流，淚竹感湘別，荆珠懷漢遊。","sortOrder":63},
  {"id":"s_work_nvlt_27_64","chapterId":"ch_work_nvlt_27","text":"又還都在路詩曰：夕聽江上波，遠極千里目，寒煙警窮蹊，爽氣起乔木。","sortOrder":64},
  {"id":"s_work_nvlt_27_65","chapterId":"ch_work_nvlt_27","text":"又至竹里詩曰：複涧隱松聲，重崖伏雲色，君子树令名，細人效命力，不見長波水，清濁俱不息。","sortOrder":65},
  {"id":"s_work_nvlt_27_66","chapterId":"ch_work_nvlt_27","text":"又齊劉繪入琵琶峡望積布磯詩曰：江山信多美，此地最為神，以茲峰石麗，重在芳树春，照烂虹蜺雜，交错錦繡陳，却瞻了非向，前觀已复新，翠微上虧景，青莎下拂津。","sortOrder":66},
  {"id":"s_work_nvlt_27_67","chapterId":"ch_work_nvlt_27","text":"齊謝朓和劉繪琵琶峡望積布磯詩曰：昔餘侍君子，歷此遊荆漢，山川隔舊賞，朋僚多雨散，惆怅懷昔踐，仿像得殊觀，赪紫共彬駮，雲錦相凌亂。","sortOrder":67},
  {"id":"s_work_nvlt_27_68","chapterId":"ch_work_nvlt_27","text":"晚登三山望京邑詩曰：灞涘望長安，河陽视京縣，白日麗飛甍，參差皆可見，餘霞散成綺，澄江靜如練，喧鳥覆春洲，雜英滿芳甸。","sortOrder":68},
  {"id":"s_work_nvlt_27_69","chapterId":"ch_work_nvlt_27","text":"又休沐重還道中詩曰：還邛歌賦似，休汝車騎非，霸池不可別，伊川難重违，汀葭稍靡靡，江葉复依依，田鵠遠相叫，沙鴇［《文選》二十七作鴇。］忽爭飛，雲端楚山見，林表吳岫微，歲華春有酒，初服偃郊扉。","sortOrder":69},
  {"id":"s_work_nvlt_27_70","chapterId":"ch_work_nvlt_27","text":"齊孔稚珪旦發青林曰：孤征越清江，遊子悲路長，二旬倏已滿，三千眇未央，草雜今古色，巖留冬夏霜，寄懷中山舊，舉酒莫相忘。","sortOrder":70},
  {"id":"s_work_nvlt_27_71","chapterId":"ch_work_nvlt_27","text":"齊劉瑱上湘度琵琶磯詩曰：茲山挺異萼，孤起秀雲中，陂池激楚浪，紛糾絕宛風，煙峰晦如晝，寒水清若空，頡颃鷗舞白，流亂葉飛紅。","sortOrder":71},
  {"id":"s_work_nvlt_27_72","chapterId":"ch_work_nvlt_27","text":"梁簡文帝經琵琶峡詩曰：百嶺相迂蔽，千崖共隱天，橫峰時礙水，斜岸或通川。","sortOrder":72},
  {"id":"s_work_nvlt_27_73","chapterId":"ch_work_nvlt_27","text":"梁孝元帝經巴陵行部伍詩曰：涉江望行旅，金鉦間采遊，水际含天色，虹光入浪浮，柳條恒拂岸，花氣盡燻舟，丛林多故社，单戍有危樓。","sortOrder":73},
  {"id":"s_work_nvlt_27_74","chapterId":"ch_work_nvlt_27","text":"梁范雲述行詩曰：振策出燕代，驅車背朔併，翩翩朱蓋轉，萧萧良馬鳴。","sortOrder":74},
  {"id":"s_work_nvlt_27_75","chapterId":"ch_work_nvlt_27","text":"梁劉孝綽還渡浙江詩曰：季秋絃望後，輕寒朝夕殊，商人泣紈扇，客子夢羅襦，忧方自難遣，况复阻川隅，日暮愁陰合，繞树噪寒乌，濛漠江煙上，蒼茫沙屿芜，解纜辭東越，接舳鶩西徂，懸帆似馳骥，飛棹若驚凫，言歸遊俠窟，方從冠蓋衢。","sortOrder":75},
  {"id":"s_work_nvlt_27_76","chapterId":"ch_work_nvlt_27","text":"又夕逗繁昌浦詩曰：日入江風靜，安波似天流，暮煙生遠路，夕鳥赴前洲。","sortOrder":76},
  {"id":"s_work_nvlt_27_77","chapterId":"ch_work_nvlt_27","text":"又月半夜泊鵲尾詩曰：客行三五夜，息棹隱中洲，月光隨浪動，山影逐波流。","sortOrder":77},
  {"id":"s_work_nvlt_27_78","chapterId":"ch_work_nvlt_27","text":"梁劉孝儀帆渡吉陽洲詩曰：扬帆乘浪華，噪鼓扬風力，近树倏而遐，遙山俄已逼，欲比驚龍掣，將頓陽乌翼，客行悲道遠，唯須前路極。","sortOrder":78},
  {"id":"s_work_nvlt_27_79","chapterId":"ch_work_nvlt_27","text":"梁劉孝威帆渡吉陽洲詩曰：江潮凌晚急，鉦鼓候晨催，幸息榜人唱，聊望高帆开，聯村倏忽盡，循汀俄頃回，疑是傍洲退，似覺前山來，將與圖南競，誰雲勞溯洄。","sortOrder":79},
  {"id":"s_work_nvlt_27_80","chapterId":"ch_work_nvlt_27","text":"梁江洪詩曰：日没風光靜，遠山深無雲，潮落晚洲出，浪罢沙成文，挟琴上高岸，望月彈明君，去家未千里，斷絕怨離群。","sortOrder":80},
  {"id":"s_work_nvlt_27_81","chapterId":"ch_work_nvlt_27","text":"梁吳筠酬鮑畿詩曰：振棹出江湄，依依望九疑，欲謁蒼梧帝，過問沅湘姬。折荷縫作蓋，落羽紡成絲，吾行別有意，不為君道之。","sortOrder":81},
  {"id":"s_work_nvlt_27_82","chapterId":"ch_work_nvlt_27","text":"又憶費昶詩曰：皎皎日將上，獵獵起微風，山没清波內，帆在浮雲中，直趣珠星北，斜开碧海東，故人若思我，當念離根蓬。","sortOrder":82},
  {"id":"s_work_nvlt_27_83","chapterId":"ch_work_nvlt_27","text":"又使庐陵詩曰：怅然不自悟，端忧坐漠漠，風急雁毛斷，水堅馬跡落，客子飢寒多，江上衣裝薄，何當報恩罢，驅車還北郭。","sortOrder":83},
  {"id":"s_work_nvlt_27_84","chapterId":"ch_work_nvlt_27","text":"梁王僧孺中川長望詩曰：長川杳難即，四望四無極，安流寧可值，憤風方未息，危帆渡中懸，孤光巖下仄，岸际树難辨，雲中鳥易識，莫恨東复西，誰知迂且直，故乡相思者，當春受顏色，獨寫千行淚，誰同萬里憶。","sortOrder":84},
  {"id":"s_work_nvlt_27_85","chapterId":"ch_work_nvlt_27","text":"梁何遜度連圻詩曰：客子行行倦，年光處處華，石蒲生促節，巖树落高花。","sortOrder":85},
  {"id":"s_work_nvlt_27_86","chapterId":"ch_work_nvlt_27","text":"又還度五洲詩曰：睠言還九派，回舻出五洲，萧散煙霞晚，清凄江漢秋，沙汀暮寂寂，芦岸夕脩脩。","sortOrder":86},
  {"id":"s_work_nvlt_27_87","chapterId":"ch_work_nvlt_27","text":"又富陽浦口和朗上人詩曰：客心愁日暮，徙倚空望歸，山煙斂树色，江水映霞辉，獨鶴凌風逝，双凫出浪飛，故乡千餘里，茲夕寒無衣。","sortOrder":87},
  {"id":"s_work_nvlt_27_88","chapterId":"ch_work_nvlt_27","text":"梁虞騫尋沈剡夕至嵊亭詩曰：命楫尋嘉會，信次歷山原，扪天上雲糾，礜石下雷奔，澄潭寫度鳥，空嶺應鳴猿，榜歌唱將夕，商子處方昬。","sortOrder":88},
  {"id":"s_work_nvlt_27_89","chapterId":"ch_work_nvlt_27","text":"梁王筠遊望詩曰：晨登黃馬坡，遙望白龍堆，風威盡撩折，路险車輪摧。","sortOrder":89},
  {"id":"s_work_nvlt_27_90","chapterId":"ch_work_nvlt_27","text":"梁朱超泊巴陵詩曰：月夜三江靜，雲霧四邊收，淤泥不通挽，寒浦劣客舟，回風折長草，輕冰斷細流，古村空烈树，荒戍久無樓。","sortOrder":90},
  {"id":"s_work_nvlt_27_91","chapterId":"ch_work_nvlt_27","text":"梁庾肩吾舟中寒望詩曰：日暮敝凫舟，曾冰合駚流，雪照齊君履，寒入楚王裘。","sortOrder":91},
  {"id":"s_work_nvlt_27_92","chapterId":"ch_work_nvlt_27","text":"周王褒始發宿亭詩曰：送人亭上別，被馬櫪中嘶，漠漠村煙起，離離嶺树齊，落星侵晓没，殘月半山低。","sortOrder":92},
  {"id":"s_work_nvlt_27_93","chapterId":"ch_work_nvlt_27","text":"又和趙王途中詩曰：飄飄映軍幕，出没望連旗，度雲還翊陣，回風即送師，峡路沙如月，山峰石似眉，村桃拂紅粉，岸柳被青絲，錦城遙可望，回鞍念此詩。","sortOrder":93},
  {"id":"s_work_nvlt_27_94","chapterId":"ch_work_nvlt_27","text":"周庾信將命使北始渡瓜步江詩曰：校尉始辭國，樓舩欲渡河，輴軒臨碛岸，旌節映江沱，觀涛想帷蓋，爭長憶幹戈，雖同燕市泣，猶聽趙津歌。","sortOrder":94},
  {"id":"s_work_nvlt_27_95","chapterId":"ch_work_nvlt_27","text":"又入彭城馆詩曰：襄君前建國，項氏昔威稜，鶂飛傷楚戰，雞鳴悲漢围，年代殊氓俗，風雲更盛衰，水流浮磬動，山深喧狄［本集作翟。］飛，夏餘花欲盡，秋近燕將稀，槐庭垂绿穗，莲浦落紅衣。","sortOrder":95},
  {"id":"s_work_nvlt_27_96","chapterId":"ch_work_nvlt_27","text":"又反命河朔始入武州詩曰：輕車飛逐李，定遠未隨班，受詔祁連反，申威疏勒還，飛蓬損腰帶，秋鬢落容顏，寄言舊相識，知餘生入關。","sortOrder":96},
  {"id":"s_work_nvlt_27_97","chapterId":"ch_work_nvlt_27","text":"陳陰铿和傅郎歲暮還湘州詩曰：蒼茫歲欲晚，辛苦客方行，大江靜猶浪，扁舟獨且征，棠枯絳葉盡，芦冻白花輕，戍人寒不望，沙禽回未驚，湘波各深淺，空軫念歸情。","sortOrder":97},
  {"id":"s_work_nvlt_27_98","chapterId":"ch_work_nvlt_27","text":"又晚泊五洲詩曰：客行逢日暮，結纜晚洲中，戍樓因碪险，村路入江窮，水隨雲渡黑，山帶日歸紅，遙然一柱觀，欲輕千里風。","sortOrder":98},
  {"id":"s_work_nvlt_27_99","chapterId":"ch_work_nvlt_27","text":"又夜發詩曰：夜江霧里闊，新月迥中明，溜舡阝唯識火，驚凫但聽聲，勞者時歌榜，愁人數問更。","sortOrder":99},
  {"id":"s_work_nvlt_27_100","chapterId":"ch_work_nvlt_27","text":"【賦】漢劉歆遂初賦曰：歆好左氏春秋，欲立於學官，時諸儒不聽，歆乃移書太常，责讓深切，為朝廷大臣所非，求出補吏，後徙五原太守，志意不得，經歷故晉之城，感今思古，遂作斯賦，得玄武之嘉兆，守五原之烽燧，馳太行之巖防，入天井之乔關，望亭燧之皦皦，飛旗幟之翩翩，迥百里之無家，路脩遠之綿綿，勒漳塞而固守，奋武靈之精誠，摅趙奢之策慮，威謀完乎金城。","sortOrder":100},
  {"id":"s_work_nvlt_27_101","chapterId":"ch_work_nvlt_27","text":"後漢班彪北征賦曰：紛吾去此舊都兮，騑遲遲以歷茲，遂舒節以遠逝兮，指安定以為期，飛雲霧之杳杳，涉積雪之皚皚，遊子悲其故乡兮，心怆恨以傷懷，攬餘涕於邑兮，哀生民之多故，谅時運之所為兮，永伊鬱其誰訴。","sortOrder":101},
  {"id":"s_work_nvlt_27_102","chapterId":"ch_work_nvlt_27","text":"後漢曹世叔妻班氏東征賦曰：惟永初之有七兮，餘隨子乎東征，時孟春之吉日兮，撰良辰而將行，遂去故而就新兮，志怆悢而懷悲，明發曙而不寐兮，心遲遲而有违，亂曰：君子之思，必成文兮，盍各言志，慕古人兮。","sortOrder":102},
  {"id":"s_work_nvlt_27_103","chapterId":"ch_work_nvlt_27","text":"後漢蔡邕述行賦曰：餘有行於京洛，遘淫雨之經時，涂迍邅其蹇連，潦汙滯而為灾，聊弘慮以存古，宣幽情而屬詞，行遊目以南望，覽太室之威靈，顧大河於北垠，睹洛汭之始併，率陵阿以登降，赴偃師而精勤，壮田橫之奉首，義二士之夹墳。","sortOrder":103},
  {"id":"s_work_nvlt_27_104","chapterId":"ch_work_nvlt_27","text":"魏崔琰述初賦曰：琰性顽口讷，至二十九，粗關書傳，聞北海有鄭徵君者，當世名儒，遂往造焉，道由齊都，而作述初賦曰：有鄭氏之高訓，吾將往乎發矇，洒餘發於蘭池，振餘珮於清風，望高密以函征，戾衡門而造止，觌遊夏之瓘瓘，聽大猷之篇記，高洪崖之耿介，羨安期之長生，登川山以永望，臨洞浦之廣溟，左扬波於湯穀，右濯岸於濛汜，運混元以升降，與三光而終始，蓬萊蔚其潛興，瀛壶崛以骈羅，列金台之蹇產，方玉闕之珪瓘。","sortOrder":104},
  {"id":"s_work_nvlt_27_105","chapterId":"ch_work_nvlt_27","text":"晉陆機行思賦曰：背洛浦之遙遙，浮黃川之裔裔，遵河曲以悠遠，觀通流之所會，啟石門而東萦，沿汴渠其如帶，讬飄風之習習，冒沉雲之藹藹，商秋肅其發節，玄雲霈而垂陰，涼氣凄其薄體，零雨鬱而下淫，睹川禽之遵渚，看山鳥之歸林，揮清波以濯羽，翳绿葉而弄音，行弥久而情勞，涂愈近而思深，羨品物以獨感，悲綢缪而在心，嗟逝宦之永久，年荏苒而歷茲，越河山而讬景，眇四載而遠期，孰歸寧之弗樂，獨抱感而弗怡。","sortOrder":105},
  {"id":"s_work_nvlt_27_106","chapterId":"ch_work_nvlt_27","text":"又思歸賦曰：餘以元康六年冬，取急歸，而王師外征，職典中兵，與聞軍政，懼兵革未息，宿原有违，懷歸之思，憤而成篇，節運代序，四氣相推，寒風肅殺，白露霑衣，嗟行邁之弥留，感時逝而懷悲，彼離思之在人，恒戚戚而無歡，悲緣情以自誘，忧觸物而生端，晝輟食而發憤，宵假寐而興言，羨歸鸿以矯首，挹穀風而如蘭，歲靡靡而薄暮，心悠悠而增楚，風霏霏而入室，响泠泠而愁序，既遨遊於川沚，亦改駕乎山林，伊我思之沈鬱，怆感物而增深，叹隨風而上逝，涕承纓而下尋，冀王事之暇豫，庶歸寧之有時，候涼風而警策，指孟冬而為期，原靈暉之促景，恒立表以望之。","sortOrder":106},
  {"id":"s_work_nvlt_27_107","chapterId":"ch_work_nvlt_27","text":"晉潘嶽西征賦曰：歲次玄枵，月旅蕤賓，潘子冯軾西征，自京徂秦，皇鑒揆餘之忠誠，俄命餘以未［《文選》十作末。］班，杖疲［原字坏，據冯校本補。］人於西夏，携老幼而入關，餘乃越平樂，過街郵，秣馬皋門，稅駕西周，澡孝水而濯纓，嘉善名而在茲，登崤坂之威夷，仰崇領之嵯峨，皋讬墳於南陵，文违風於北阿，躡函穀之重阻，看天险之衿帶，跡諸侯之勇怯，算嬴氏之利害，或开關以延敵，競遁逃而奔竄，發阌乡而警策，溯黃卷［《文選》作巷。］而濟潼，眺華嶽之陰崖，觌高掌之遺蹤，倦狹路之迫隘，軌崎嶇以低仰，蹈秦郊而始辟，豁爽垲以宏壮，黃壤千里，沃野弥望，華實芬敷，桑麻涤畅，邪界褒斜，右濱汧隴，寶雞前鳴，甘泉後涌，面終南而背雲陽，跨平原而連嶓冢，九嵕〈山截〉嶭，太［《文選》太下有一字，此脱。］巃嵸，吐清風之飂戾，納歸雲之鬱蓊，南有玄灞素浐，湯井溫穀，北有清渭濁涇，蘭池周曲，浸决鄭白之渠，漕引淮海之粟，林茂有鄠之竹，山挺藍田之玉，履犬戎之侵地，疾幽後之诡惑，舉伪烽以沮眾，淫嬖褒以縱慝，軍败戲水之上，身死驪山之北，異哉秦始皇之為君也，傾天下以厚葬，自开辟而未聞，匠人勞而弗圖，俾生埋以報勤，外罹西楚之禍，內受牧竖之焚，語曰：行無禮必自及，此非效欤，乾坤以有親可久，君子以厚德載物，觀夫漢高之興也，非徒聰明神武，豁達大度而已，乃實慎終追遠，篤誠款愛，泽靡不漸，恩無不逮，率土且猶不遺，而况於鄰里乎，而况於卿士乎，於斯時也，乃摹寫舊丰，製造新邑，故社易置，枌榆遷立，街衢如一，庭宇相袭，浑雞犬而亂放，各識家而競入，籍含怒於鸿門，沛跼蹐而來王，范謀害而弗許，陰授劍以約莊，挺白刃以萬舞，危冬葉之待霜，爾乃階長樂，登未央，汎太液，凌建章，萦馺娑而款骀荡，轥枍詣而轹承光，徘徊桂宮，惆怅柏梁，驚雉雊於台陂，狐兔窟於殿傍，何黍苗之離離，而予思之茫茫。","sortOrder":107},
  {"id":"s_work_nvlt_27_108","chapterId":"ch_work_nvlt_27","text":"晉郭璞流寓賦曰：戒雞晨而星發，至猗氏而方晓，觀屋落之隳殘，顧但見乎丘棗，嗟城池之不固，何人物之希少，越南山之高嶺，修焦丘之微路，駭斯径之峻絕，感王陽而增懼，詰朝發於解池，辰中暨乎河北，思此縣之舊名，蓋曩日之魏國，詠詩人之流歌，信風土之俭刻，背茲邑之迥逝，何险難之多歷，望陝城於南涯，存虢氏之疆埸，實我姓之攸出，邈有懷乎乃跡，陟函穀之高關，壮斯势之险固，過王城之丘墉，想穀洛之合斗，惡王靈之壅流，奇子乔之輕舉，遊華輦而永懷，乃凭軾以寓目，思文公之所營，蓋成周之墟域。","sortOrder":108},
  {"id":"s_work_nvlt_27_109","chapterId":"ch_work_nvlt_27","text":"晉張載叙行賦曰：歲大荒之孟夏，餘將往乎蜀都，脂輕車而秣馬，循路軌以西徂，朝發轫於京宇兮，夕予宿於穀洛，踐有周之舊墟，槐丘荒以寥廓，贊王孫於北門，問九鼎於東郭，寔公旦［原坏，據冯校本補。］之所卜，曷斯水之濆薄，入函穀而長驅，歷新安之滷阜，行逶迤以登降，陟二崤之重阻，經嵚岑之险巇，想姬文之避雨，出潼關以回逝，仰華嶽之崔嵬，勤大禹之疏导，豁龍門之洞开，舍予車以步趾，玩卉木之璀错，翳青青之長松，荫肅肅之高柞，緣阻岑之絕崖，蹈偏梁之懸閣，石壁立以切天，岌崄隗其欲落，超陽平而越白水，稍幽薆以回深，秉重峦之百層，轉木末於九岑，浮雲起於轂下，零雨集於麓林，上昭晢以清陽，下杳冥而晝陰，聞山鳥之晨鳴，聽玄猿之夜吟，雖處者之所樂，嗟寂寞而愁予心，造劍閣之崇關，路盤曲以晻藹，山峥嵘以峻狹，仰青天其如帶，兼習坎之重固，形東隘以要害，豈乾坤之分域，將隔絕乎內外。","sortOrder":109},
  {"id":"s_work_nvlt_27_110","chapterId":"ch_work_nvlt_27","text":"晉袁宏東征賦曰：惟吾生於末運，讬一葉於邓林，顧微軀之眇眇，若絕响之遺音，壮公瑾之明達，吐不世之奇策，挫百勝於崇朝，靡雲旗於赤壁，三光一舉而參分，四海指麾而中隔，過武昌以逍遙，登樊山以流盻，訪遺老以證往，乃西鄂之舊縣，曩有吳之初基，升員丘而豹变，爾乃出桑洛，會通川，背彭泽，面長泉，洲渚迢遰，〈山幾〉岫虛懸，即雲似嶺，望水若天，日月出乎波中，雲霓生於浪間，嗟我行之弥留，跨晦朔之倏忽，風褰林而萧瑟，雲出山而逢渤，向孫氏之南面，鑽靈龟以相土，模酆鎬之製度，寫河洛之規矩，經始郛郭，筑室葺宇，金城萬雉，崇墉百堵，君臣有章，上下獲叙，所以能三分天下，而有其文武，到吳都以停舟，覽阖闾之餘尘，建脩城以營郭，引通流而發津，遠矣吳德，舊邦惟新，太伯被發，仲雍文身，言偃以文學遺風，季札以讓國稱仁，高節顯於華夏，端委行乎海濱。","sortOrder":110},
  {"id":"s_work_nvlt_27_111","chapterId":"ch_work_nvlt_27","text":"宋謝靈運歸涂賦曰：昔文章之士，多作行旅賦，或欣在觀國，或怵在斥徙，或述職邦邑，或羁役戎陣，事由於外，興不自己，雖高才可推，求懷未愜，今量分告退，反身草泽，經涂履運，用感其心，賦曰：承百世之慶靈，遇千載之優渥，匪康衢之難踐，谅跬步之易局，踐寒暑以推換，眷桑梓以緬邈，褫簪帶於窮城，反巾褐於空穀，果歸期於原言，獲素念於思樂，於是舟人告辦，佇楫在川，觀鳥候風，望景测圓，背海向溪，乘潮傍山，凄凄送歸，愍愍告旋，時旻秋之杪節，天既高而物衰，雲上騰而雁翔，霜下淪而草腓，舍陰漠之舊浦，去湯［冯校本作陽。］景之芳蕤，林承風而飄落，水鑒月而含辉，發青田之枉渚，逗白岸之空亭，路威夷而诡状，山侧背而易形，停餘舟而淹留，搜縉雲之遺跡，漾百里之清潭，見千仞之孤石，歷古今而長在，經盛衰而不易。","sortOrder":111},
  {"id":"s_work_nvlt_27_112","chapterId":"ch_work_nvlt_27","text":"宋鮑昭遊思賦曰：雲遙兮海冲，上潮兮送風，秋水兮架浦，涼煙兮冒虹，暮氣起兮遠岸黑，陽精滅兮天际紅，波汒々兮無底，山嵾々兮萬重，舍堂宇之密親，坐江潭而為客，對蒹葭之遂黃，视零露之方白，鸿晨驚以响湍，泉夜下而鳴石，瞻荆吳之遠山，望邯鄲之長陌，塞風馳兮邊草飛，胡沙起兮雁扬翮，雖燕越之異心，在禽鳥之同戚。","sortOrder":112},
  {"id":"s_work_nvlt_27_113","chapterId":"ch_work_nvlt_27","text":"齊謝朓思歸賦曰：餘菲薄以固陋，受恩靈而不訾，拖銀黃之沃若，剖金符之陆離，舟未濟而河廣，途方遙而馬疲，紛吾生之遊薄，弥一紀而歷茲，自下車於江海，涉青春而於是時，〈目眷〉崇芒而引領，望大夏而長思，離曲街之委陋，猶寤寐而見之，餘乃眷言興慕，南眺猶然，將整歸辔，原受一廛，考幸城之直陌，相洛浦之回阡，於是楥搖芳槿，門拂長楊，簷桃春發，窗竹夏涼，晨露晞而草馥，微風起而树香，恒離居而歲月，痛銷落而徒傷。","sortOrder":113},
  {"id":"s_work_nvlt_27_114","chapterId":"ch_work_nvlt_27","text":"梁簡文帝述羁賦曰：奉明後之霑渥，將遠述於衡楚，叹雲霞之窅漫，對江山之遙阻，是時孟夏首節，雄風吹甸，晚解纜乎乡津，涕淫淫其若霰，舟飄飄而轉遠，顧帝都而裁見，遠山碧，暮水紅，日既晏，誰與同，雲珪瓘而出岫，江搖漾而生風，奉玺言而遄邁，改餘玉於江隈，遵陽涂而中正，軫悲心其若頹，引領京邑，瞻望弗遠，恋逐雲飛，思隨蓬卷，觀江水之寂寥，原從流而東反。","sortOrder":114},
  {"id":"s_work_nvlt_27_115","chapterId":"ch_work_nvlt_27","text":"又阻歸賦曰：觀建國之皇王，選能官於前古，元帝慈而布教，豈齊聖而作辅，伊吾人之固陋，宅璇漢而自通，躡九枝而耀景，總六翮而摶風，屬玄玦之啟異，逢玉弩之相驚，頓天羅於八表，騰雲驅於四溟，發伏鱉之雄氣，耀策馬之高星，地邇朔埸，疆鄰北極，垅树饒風，胡天少色，上月斜臨，寒松遙直，雲向山而欲斂，雁疲飛而不息，何愁緒之交加，豈树萱與折麻，聞繁鉦之韻冰，聽流風之入笳，終知客遊之阻，無解乡路之賒。","sortOrder":115},
  {"id":"s_work_nvlt_27_116","chapterId":"ch_work_nvlt_27","text":"梁江淹待罪江南思北歸賦曰：惟江南兮丘墟，經萬里兮長芜，帶封狐兮比景，連雄虺兮蒼梧，當青春而離散，方仲秋而遂徂，雲清冷而多緒，風萧條而無端，猿之吟兮日光迥，狖之啼兮月色寒，况北州之賤士，為炎土之流人，共魍魉而相偶，與〈虫萧〉蛸而為鄰，秋露下兮點劍舄，春苔生兮缀衣巾。","sortOrder":116},
  {"id":"s_work_nvlt_27_117","chapterId":"ch_work_nvlt_27","text":"梁丘遲還林賦曰：爰自京師，言歸舊嶺，今風古轍，每動寸衷，因事而書。不覺成卷，非謂為文，聊記行途所經雲爾，太皞弭節，祝融耸駕，炎鍾汎响，青籥靜吹，丘子稅轅畿路，總舳川湄，裭魂故嶺，結夢舊墀，揆身世而載懷，鏡古今而興辭，验難停於楊轍，昭易改於墨絲，匪追舉而辯命，豈適尹而問蓍，簷簦無白璧之想，負書靡黑豹之悲，纜解山潮，首顧京澨，仰絳堞之紛回，與素津之容裔，荃桡往來，芰蓋經過，依俙子陵之釣，仿佛沧浪之歌，出入風霞，遊息雲露，階容伺禽飛，窗高月渡，踟蹰七教，徘徊五禮，永翦帶於關上，長緝巾乎林底。","sortOrder":117},
  {"id":"s_work_nvlt_27_118","chapterId":"ch_work_nvlt_27","text":"梁沈約愍涂賦曰：結榜窮渚，思臨長屿，情依舊越，身經故楚，彼長路之多端，伊客心之無緒，懽因情而易失，悲由心而難拒，此江海之信遼，知餘思之方阻，日晻長浦，風扫聯葭，叠雲疑憤，廣水騰華，聽奔沸於洲屿，望掩暧乎煙沙，依雲邊以知國，極鳥道以瞻家，免凄怆於羁離，亦殷勤於行路，叹餘涂之屢蹇，奚前芳之可慕。","sortOrder":118},
  {"id":"s_work_nvlt_27_119","chapterId":"ch_work_nvlt_27","text":"梁張缵南征賦曰：歲次娵訾，月惟中呂，餘謁帝於承明，將述職於南楚，忽中川而反顧，懷舊乡而延佇，溯金牛之迅渚，睹靈涛之雄壮，標素嶺乎青壁，葺赪文於翠障，跳巨石以驚湍，批冲巖而駭浪，铲千尋之峭峰，潀萬流之大壑，隱日月以蔽虧，摶風煙而回薄，崖映川而晃朗，水騰光以倏烁，下流湍而洊险，上岑崟而將落，於是近睇赭峰，遙瞻鵲岸，島屿蒼茫，風霜萧散，值時雨之新晴，觀百川之浩汗，水泓澄以闇夕，山參差而辨旦，忽臨睨於故乡，眇江天其無畔，獨向風而舒情，搴芳洲而誰玩，於是千流共歸，萬嶺分状，清江洗潮，平湖夷畅，翻光轉彩，出没搖漾，岷山嶓冢，悠遠寂寥，青湓赤岸，控汐引潮，界飛流於翠薄，耿長虹於青霄，若夫灌漭川涯，曾潭水府，遊泳之所往還，喧鳴之所攒聚，聆寡鶴之偏叫，問孤鸿之慕侣，在客行而多思，獨傷魂而凄楚。","sortOrder":119},
  {"id":"s_work_nvlt_27_120","chapterId":"ch_work_nvlt_27","text":"陳沈蜅魂歸賦曰：值天地之輻裂，遭日月之雰虹，去父母之邦國，埋形影於胡戎，絕君臣而辭骨肉，蹐厚地而跼蒼穹，抱北思之胡馬，望南飛之夕鸿，泣霑衿而雜露，悲微吟而帶風，履瓘瓘之層冰，面飗飗之嚴霜，去莫敖之所縊，過臨川之折軸，矧今古之悲涼，併攒心而霑袂，渡狹石之欹危，跨清津之幽咽，雁虛弓而自殒，猿叫子而腸裂，歷江漢之逶迤，及樊郡之參差，望隆中之大宅，映峴首之沉碑，乃尋析而歷裔，遂經秦而至洛，覺高蹈之清遠，見風雲之倏烁，何武關之狹隘，而漢祖之英雄，山萬重而仰雲霧，水百仞而寫蜿虹，去青泥而逾白鹿，越浐水而至青門，長卿之賦可想，邵平之跡不存，咄嗟驪山之阜，惆怅灞陵之園，訪轵道之長組，拾藍田之玙璠，登未央之北闕，望長樂之基趾，伊太後之所居，筑旗亭而成市，槐路鬱以三條，方涂阻而九軌，觀阡陌之遺蹤，實不乖於前史，傍直城而北轉，臨橫門而左起，泊涇泥之混濁，盥渭渚之清波，指鹹陽而長望，何李趙之經過，息甘泉而避暑，猶爽垲而清和，至誠可以感鬼，秉信可以祈天，何精殒而魄散，忽魂歸而氣旋，解龍驂而見送，走却驲於停傳，出向來之大道，及初入之山川，爰繞朝之赠策，報李陵之別篇，淚未悲而自墮，語有噎而無宣。","sortOrder":120},
  {"id":"s_work_nvlt_27_121","chapterId":"ch_work_nvlt_27","text":"【書】宋鮑昭與妹書曰：吾自發寒雨，而全行日少，栈石星飯，結荷水宿，以今食時，仅及大雷，涂登千里，日逾一辰，去親為客，如何如何，向因步頓，凭觀川陆，遨神清渚，流睇方曛，東顧三洲之隔，西眺九派之分，闚地門之絕景，望天际之孤雲，南則積山萬状，爭氣負高，含霞飲景，參差代雄，陵跨長隴，前後相屬，帶天有匝，橫地無窮，東則砥原遠隰，亡端靡际，寒蓬夕卷，古树雲平，旋風四起，思鳥群歸，靜聽無聞，極视不見，北則陂池潛演，湖泽脈通，栖風之鳥，水化之虫，以智吞愚，因彊捕小，號噪驚聒，紛牣其中，西則回江永指。長波吞合，滔滔何窮，漫漫安竭，左右青藹，表里紫霄，從嶺而西，氣盡金光，半山以下，純為黛色，信可以神居帝郊，镇控湘漢者也，夕景欲沉，晓露將合，孤雏寒嘯，遊鸿遠吟，樵蘇一叹，舟子再泫，誠足忧悲，不可說也。","sortOrder":121},
  {"id":"s_work_nvlt_27_122","chapterId":"ch_work_nvlt_27","text":"《藝文類聚》　唐·欧陽詢","sortOrder":122},
  {"id":"s_work_nvlt_28_1","chapterId":"ch_work_nvlt_28","text":"卷二十八人部十二","sortOrder":1},
  {"id":"s_work_nvlt_28_2","chapterId":"ch_work_nvlt_28","text":"○遊覽","sortOrder":2},
  {"id":"s_work_nvlt_28_3","chapterId":"ch_work_nvlt_28","text":"◇遊覽","sortOrder":3},
  {"id":"s_work_nvlt_28_4","chapterId":"ch_work_nvlt_28","text":"《家語》曰：孔子北遊，登農山，子路子貢顏回侍，孔子四望，喟然叹曰：二三子各言爾志。","sortOrder":4},
  {"id":"s_work_nvlt_28_5","chapterId":"ch_work_nvlt_28","text":"《穆天子傳》曰：天子遂袭崑崙之丘，遊軒轅之宮，眺望鍾山之嶺，玩帝者之寶。勒石王母之山，紀跡玄圃之上，乃取其嘉木艳草，奇鳥怪獸，玉石珍瑰之器，重膏銀燭之寶。","sortOrder":5},
  {"id":"s_work_nvlt_28_6","chapterId":"ch_work_nvlt_28","text":"又曰：天子北昇於舂山之上，以望四野，舂山是惟天下之高山也，天子五日觀於舂山之上。","sortOrder":6},
  {"id":"s_work_nvlt_28_7","chapterId":"ch_work_nvlt_28","text":"《史記》曰：始皇三十七年，上會稽山，望於南海，立石刻，頌秦德，還過吳，從江乘渡，傍海上，北至琅邪。","sortOrder":7},
  {"id":"s_work_nvlt_28_8","chapterId":"ch_work_nvlt_28","text":"又曰：太史公登會稽山，探禹穴，登姑蘇，望五湖。","sortOrder":8},
  {"id":"s_work_nvlt_28_9","chapterId":"ch_work_nvlt_28","text":"《莊子》曰：莊子與惠子遊濠梁之上，《莊子》曰：儵魚出遊從容，是魚樂也，惠子曰：子非魚，焉知魚之樂也，《莊子》曰：子非我，焉知吾不知魚之樂也。","sortOrder":9},
  {"id":"s_work_nvlt_28_10","chapterId":"ch_work_nvlt_28","text":"《楚辭》曰：覽冀州兮有餘，橫四海兮焉發。","sortOrder":10},
  {"id":"s_work_nvlt_28_11","chapterId":"ch_work_nvlt_28","text":"又曰：登崑崙兮四望，心飛楊兮浩荡，日將暮兮怅忘歸，遺極浦兮悟懷。","sortOrder":11},
  {"id":"s_work_nvlt_28_12","chapterId":"ch_work_nvlt_28","text":"《韓詩外傳》曰：齊景公遊於牛山，而北望齊曰：美哉國乎，鬱鬱蓁蓁。","sortOrder":12},
  {"id":"s_work_nvlt_28_13","chapterId":"ch_work_nvlt_28","text":"《淮南子》曰：所謂樂者，遊雲夢，陟高丘，耳聽九韻六茎，口味煎熬芬芳，馳騁夷道，釣射鷫鹴，之謂樂乎。","sortOrder":13},
  {"id":"s_work_nvlt_28_14","chapterId":"ch_work_nvlt_28","text":"《戰國策》曰：昔楚王登彊台而望崇山，左江右湖，以臨方湟，［冯校本作淮。］其樂忘死。","sortOrder":14},
  {"id":"s_work_nvlt_28_15","chapterId":"ch_work_nvlt_28","text":"《說苑》曰：齊景公遊海上，樂之，六月不歸。","sortOrder":15},
  {"id":"s_work_nvlt_28_16","chapterId":"ch_work_nvlt_28","text":"又曰：楚昭王欲之荆台遊，司馬子綦進諫曰：荆台之遊，左洞庭之波，右彭蠡之水，南望獵山，下臨方淮，其樂使人遺老而忘死。","sortOrder":16},
  {"id":"s_work_nvlt_28_17","chapterId":"ch_work_nvlt_28","text":"《新序》曰：晉平公遊西河，中流而叹曰：嗟乎，安得賢士，與共此樂乎。","sortOrder":17},
  {"id":"s_work_nvlt_28_18","chapterId":"ch_work_nvlt_28","text":"《列女傳》曰：楚昭王燕遊，蔡姬在左，越姬參乘，王親乘驷以逐，登附莊之台，以望雲夢之囿，乃顧謂二女曰：樂乎，吾原與子生若此。","sortOrder":18},
  {"id":"s_work_nvlt_28_19","chapterId":"ch_work_nvlt_28","text":"《世說》曰：過江諸人，每暇日，辄相要出新亭，藉卉飲宴，周侯中坐而叹曰：風景不殊，舉目有江河之異。","sortOrder":19},
  {"id":"s_work_nvlt_28_20","chapterId":"ch_work_nvlt_28","text":"【詩】古詩曰：青青陵上柏，磊磊涧中石，人生天地間，忽如遠行客，驅車策駑馬，遊戲宛與洛，長衢羅夹巷，王侯多第宅，兩宮遙相望，双闕百餘尺，極宴娱心意，戚戚何所迫。","sortOrder":20},
  {"id":"s_work_nvlt_28_21","chapterId":"ch_work_nvlt_28","text":"魏文帝在孟津詩曰：良辰啟初節，高會構歡娱，清歌發妙曲，樂正奏笙竽，曜靈忽西邁，炎燭繼望舒，翊日浮黃河，長驅旋鄴都。","sortOrder":21},
  {"id":"s_work_nvlt_28_22","chapterId":"ch_work_nvlt_28","text":"又銅雀園詩曰：朝遊高台觀，夕宴華池陰，大酋奉甘醪，獸人獻嘉禽，齊倡發東舞，秦筝奏西音，飛鳥翻翔舞，悲鳴集北林，樂極哀情來，憀恨摧肝心。","sortOrder":22},
  {"id":"s_work_nvlt_28_23","chapterId":"ch_work_nvlt_28","text":"又於清河作詩曰：方舟戲長水，澹澹自浮沉，絃歌發中流，悲風漂餘音。","sortOrder":23},
  {"id":"s_work_nvlt_28_24","chapterId":"ch_work_nvlt_28","text":"魏王粲詩曰：悠悠涉荒路，靡靡我心愁，四望無煙火，但見林與丘，城郭生榛棘，蹊径無所由，萑蒲竟廣泽，葭苇夹長流，遊客多悲傷，淚下不可收，朝入谯郡界，曠然消人忧，詩人美樂土，雖客猶原留。","sortOrder":24},
  {"id":"s_work_nvlt_28_25","chapterId":"ch_work_nvlt_28","text":"又詩曰：日暮遊西園，冀寫忧思情，曲池扬素波，列树敷丹榮，上有特栖鳥，懷春向我鳴。","sortOrder":25},
  {"id":"s_work_nvlt_28_26","chapterId":"ch_work_nvlt_28","text":"又詩曰：吉日簡清時，從君出西園，方軌策良馬，併驅厲中原，北臨清漳渚，西看柏楊山，回翔遊廣囿，逍遙波水間。","sortOrder":26},
  {"id":"s_work_nvlt_28_27","chapterId":"ch_work_nvlt_28","text":"又詩曰：列車息眾駕，相伴绿水湄，幽蘭吐芳烈，芙蓉發紅暉，百鳥何繽翻，振翼群相追，投網引潛鯉，強弩下高飛，白日已西邁，歡樂忽忘歸。","sortOrder":27},
  {"id":"s_work_nvlt_28_28","chapterId":"ch_work_nvlt_28","text":"魏陳琳詩曰：高會時不娱，羁客難為心，{殷心}懷從中發，悲感激清音，投觴罢歡坐，逍遙步長林，萧萧山穀風，黯黯天路陰，惆怅忘旋反，歔欷涕霑襟。","sortOrder":28},
  {"id":"s_work_nvlt_28_29","chapterId":"ch_work_nvlt_28","text":"又詩曰：節運時氣舒，秋風涼且清，閒居心不娱，駕言從友生，翱翔戲長流，逍遙登高城，東望看畴野，回顧覽園庭，嘉木凋绿葉，芳草纖紅榮，騁哉日月逝，年命將西傾，建功不及時，鍾鼎何所銘，收念還房寢，慷［原作恍，據冯校本改。］慨詠墳經，庶幾及君在，立德垂功名，晉陆機遨遊出西城詩曰：遨遊出西城，按辔循都邑，逝物隨節改，時風肅且熠，遷化有常然，盛衰自相袭，靡靡年時改，苒苒老已及，行矣勉良圖，使爾脩名立。","sortOrder":29},
  {"id":"s_work_nvlt_28_30","chapterId":"ch_work_nvlt_28","text":"晉棗據詩曰：矯足登雲閣，相伴步九華，徙倚凭高山，仰攀桂树柯，延首觀神州，回精眄曲阿，芳林挺脩幹，一歲再三花，何以濟不朽，噓吸漱朝霞，重巖吐神氵霤，傾觴挹涌波，恢恢大道間，人事足為多。","sortOrder":30},
  {"id":"s_work_nvlt_28_31","chapterId":"ch_work_nvlt_28","text":"晉張載登成都白菟樓詩曰：重城結曲阿，飛宇起層樓，累棟出雲表，峣蘖臨太虛，高軒啟朱扉，回望畅八隅，西瞻岷山嶺，珪瓘似荆巫，蹲鴟蔽地生，原隰殖嘉蔬，雖遇尧湯世，民食恒有餘，鬱鬱小城中，岌岌百族居，街術紛綺错，高甍夹長衢，借問楊子舍，想見長卿庐。","sortOrder":31},
  {"id":"s_work_nvlt_28_32","chapterId":"ch_work_nvlt_28","text":"晉陆冲詩曰：命駕遵長涂，綿邈涂難尋，我行一何艱，山川阻且深，洿泽無夷軌，重峦有曾陰，零雨淹中路，玄雲蔽高岑，俯悼孤行獸，仰叹偏翔禽，空穀回悲响，流風漂哀音。","sortOrder":32},
  {"id":"s_work_nvlt_28_33","chapterId":"ch_work_nvlt_28","text":"又詩曰：肆觀野原外，放心希大和，景嶽造天漢，丰林冒重阿，清芬乘風散，艳藻映渌波。","sortOrder":33},
  {"id":"s_work_nvlt_28_34","chapterId":"ch_work_nvlt_28","text":"宋江夏王義恭登景陽樓詩曰：丹墀設金屏，瑤榭陳玉床，溫宮冬开燠，清殿夏含霜，弱蕊布遐馥，輕葉振遠芳，弥望少無际，肆睇周華疆，象闕對馳道，飛廉矚方塘，邸寺送暉曜，槐柳自成行，通川溢輕舻，長術盈方箱，顧此爝火微，胡顏廁天光。","sortOrder":34},
  {"id":"s_work_nvlt_28_35","chapterId":"ch_work_nvlt_28","text":"又彭城戲馬台集詩曰：騁骛辭南京，弭節憩東楚，懿蕃重遐望，興言集僚侣，於役未雲淹，時遷变淳暑，眷恋江水流，回首獨延佇。","sortOrder":35},
  {"id":"s_work_nvlt_28_36","chapterId":"ch_work_nvlt_28","text":"宋袁淑登宣城郡詩曰：怅焉訊舊老，茲前乃楚居，十代闕州記，百祀絕方書。","sortOrder":36},
  {"id":"s_work_nvlt_28_37","chapterId":"ch_work_nvlt_28","text":"宋顏延之罢郡還與張湘川登巴陵城樓詩曰：江漢分楚望，衡巫奠南服，三湘淪洞庭，七泽藹荆牧，凄矣自遠風，傷哉千里目，萬古陳往還，百代勞起伏。","sortOrder":37},
  {"id":"s_work_nvlt_28_38","chapterId":"ch_work_nvlt_28","text":"又登景陽樓詩曰：風觀要春景，月榭迎秋光，沿波被華若，隨山茂貞芳。","sortOrder":38},
  {"id":"s_work_nvlt_28_39","chapterId":"ch_work_nvlt_28","text":"宋鮑昭行樂［本集作藥。］至城東桥詩曰：迅風首旦發，平路寒飛尘，扰扰遊官子，營營市井民，懷金近從利，撫劍遠辭親，爭知萬里途，各事百年身。","sortOrder":39},
  {"id":"s_work_nvlt_28_40","chapterId":"ch_work_nvlt_28","text":"宋謝瞻遊西池詩曰：逍遙越郊肆，原言屢經過，回阡被陵闕，高台眺飛霞，惠風荡繁囿，白雲屯曾阿，褰裳順蘭沚，徙倚引芳柯，美人愆歲月，遲暮獨如何。","sortOrder":40},
  {"id":"s_work_nvlt_28_41","chapterId":"ch_work_nvlt_28","text":"宋謝靈運晚出西射堂詩曰：步出西掖門，遙望城西岑，連障叠巘崿，青翠杳深沉，晓霜楓葉丹，夕曛岚氣陰，節往慼不淺，感來恨已深，羁雌恋舊侣，迷鳥懷故林，含情尚勞愛，如何離賞心，撫鏡華緇賓，［《文選》二十二作鬢。］攬帶缓促衿，安排徒空言，幽獨賴鳴琴。","sortOrder":41},
  {"id":"s_work_nvlt_28_42","chapterId":"ch_work_nvlt_28","text":"又登池上樓詩曰：殉祿反窮海，臥痾對空林，傾耳聆波澜，舉目眺嶇嵚，初景革緒風，新陽改故陰，池塘生春草，園柳变鳴禽，索居易永久，離群難處心，持操豈獨古，無悶徵於今。","sortOrder":42},
  {"id":"s_work_nvlt_28_43","chapterId":"ch_work_nvlt_28","text":"又登江中孤屿詩曰：江南倦歷覽，江北曠周旋，懷新道轉回，尋異景不延，亂流趨孤屿，孤屿媚中川，雲日相暉映，空水共澄鮮，表靈物莫賞，蘊真誰為傳。","sortOrder":43},
  {"id":"s_work_nvlt_28_44","chapterId":"ch_work_nvlt_28","text":"又東山望海詩曰：开春獻初歲，白日出悠悠，荡志將愉樂，瞰海庶忘忧，策馬步蘭皋，緤控息椒丘，采蕙遵大薄，搴若履長洲，白華縞陽林，紫虈晔春流，非徒不弭忘，覽物情弥遒，萱蘇始無慰，寂寞終可求。","sortOrder":44},
  {"id":"s_work_nvlt_28_45","chapterId":"ch_work_nvlt_28","text":"又初往新安至桐庐口詩曰：絺绤雖凄其，授衣尚未至，感節良已深，懷古徒役思，不有千里棹，孰申百代意，遠协尚子心，遙得許生忌，既及冷風善。又即秋水駚，江山共开曠，雲日相照媚，景夕群物清，對玩鹹可喜。","sortOrder":45},
  {"id":"s_work_nvlt_28_46","chapterId":"ch_work_nvlt_28","text":"宋謝莊遊豫章西山觀洪崖井詩曰：幽原平生積，野好歲月弥，舍簪神區外，整褐靈乡垂，林遠炎天隔，山深白日虧，遊陰騰鵠嶺，飛清起鳳池，隱暧松霞被，容與涧煙移，將遂丘中性，結駕終在斯。","sortOrder":46},
  {"id":"s_work_nvlt_28_47","chapterId":"ch_work_nvlt_28","text":"齊謝朓和徐勉出新林渚詩曰：宛洛佳遨遊，春色滿皇州，結軫青郊路，回瞰沧江流，日華川上動，風光草际浮，桃李成蹊径，桑榆荫道周。","sortOrder":47},
  {"id":"s_work_nvlt_28_48","chapterId":"ch_work_nvlt_28","text":"又遊東田詩曰：戚戚苦無悰，携手共行樂，尋雲陟累榭，隨山望菌閣，遠树暧芊芊，山煙紛漠漠，魚戲新荷動，鳥散餘花落，不對芳春酒，還望青山郭。","sortOrder":48},
  {"id":"s_work_nvlt_28_49","chapterId":"ch_work_nvlt_28","text":"梁簡文帝仰和衛尉新渝侯巡城口號詩曰：帝景風雨中，層闕煙霞浮，玉署清餘熱，金城含暮秋，水光凌却敵，槐影帶重樓。","sortOrder":49},
  {"id":"s_work_nvlt_28_50","chapterId":"ch_work_nvlt_28","text":"又薄晚逐涼北樓回望詩曰：平衢望如掌，曾雉暧相連，斷雲留去日，長山减半天，戲凫乘洑下，漁舟冒浪前。","sortOrder":50},
  {"id":"s_work_nvlt_28_51","chapterId":"ch_work_nvlt_28","text":"又大同八年秋九月詩曰：大君重九節，下輦上林中，酒阕嘉宴罢，車騎各西東，時餘守西掖，脂車歸北宮，車分獨坐道，扇拂冶城風，落照巉中滿，浮煙槐外通，長樂含初紫，安榴坼晚紅。","sortOrder":51},
  {"id":"s_work_nvlt_28_52","chapterId":"ch_work_nvlt_28","text":"又大同九年秋七月詩曰：高樓辟左扇，回望依蘭桡，晚風飖颺來，落照參差好。","sortOrder":52},
  {"id":"s_work_nvlt_28_53","chapterId":"ch_work_nvlt_28","text":"又登錦壁詩曰：孫生酸棗寺，王子枝江樓，何如登石鏡，因閒猶豫遊。","sortOrder":53},
  {"id":"s_work_nvlt_28_54","chapterId":"ch_work_nvlt_28","text":"又應令詩曰：蠡浦急兮川路長，白雲重兮出帝乡，平原忽兮遠極目，江甸阻兮羁心傷，树庐嶽兮高且峻，瞻泒水兮去泱泱，遠煙生兮含山势，風散花兮傳馨香，臨清波兮望石鏡，瞻鶴嶺兮睇仙裝，望邦畿兮千里曠，悲遙夜兮九回腸，顧龍樓兮不可見，徒送目兮淚霑裳。","sortOrder":54},
  {"id":"s_work_nvlt_28_55","chapterId":"ch_work_nvlt_28","text":"梁元帝出江陵縣還詩曰：遊魚迎浪上，雊雉向林飛，遠村雲里出，遙舡天际歸。又詩曰：朝出屠羊縣，夕反仲宣樓，水滿還侵岸，沙盡稍开流。","sortOrder":55},
  {"id":"s_work_nvlt_28_56","chapterId":"ch_work_nvlt_28","text":"又登江州百花亭懷荆楚詩曰：目極才千里，何由望楚津，落花洒行路，垂楊拂砌尘，柳絮飄春雪，荷珠漾水銀，试酌新清酒，遙勸陽台人。","sortOrder":56},
  {"id":"s_work_nvlt_28_57","chapterId":"ch_work_nvlt_28","text":"梁昭明太子示雲麾弟詩曰：白雲飛兮江上阻，北流分兮山風舉，山萬仞兮多高峰，流九派兮饒汪渚，上岧峣兮乃逼天，下微濛兮後興雨，實覽歷兮此名地，故遨遊兮茲勝所，爾登涉兮一長望，理化顧兮忽憶予，想玉顏兮在目中，徒踟蹰兮增延佇。","sortOrder":57},
  {"id":"s_work_nvlt_28_58","chapterId":"ch_work_nvlt_28","text":"梁沈約登高望春詩曰：登高眺京洛，街巷何紛紛，回首望長安，城闕鬱盤桓，齊童躡珠履，趙女楊翠翰，春風搖雜树，葳蕤绿且丹，寶瑟玫瑰柱，金羁玳瑁鞍，淹留宿下蔡，置酒過上蘭，日出照钿黛，風過動羅紈。","sortOrder":58},
  {"id":"s_work_nvlt_28_59","chapterId":"ch_work_nvlt_28","text":"又秋晨羁怨望海思歸詩曰：分空臨澥霧，披遠望沧流，八桂暧如畫，三桑眇若浮，煙極希丹水，月表望青丘。","sortOrder":59},
  {"id":"s_work_nvlt_28_60","chapterId":"ch_work_nvlt_28","text":"梁劉孝威登覆舟山望湖北詩曰：紫川通太液，丹岑聯少華，堂皇更隱映，松灌雜交加，荇浦浮新葉，漁舟繞落花，浴童爭淺岸，漂女擇平沙，極望傷春目，回車歸狹邪。","sortOrder":60},
  {"id":"s_work_nvlt_28_61","chapterId":"ch_work_nvlt_28","text":"又出新林詩曰：芒山眡洛邑，函穀望秦京，遙分承露掌，遠見長安城，故乡已可識，遊子必勞情，霧罢前村見，風息涌川平，坐觀暮潮落，漸見夕煙生，無由一羽化，徒想風御輕。","sortOrder":61},
  {"id":"s_work_nvlt_28_62","chapterId":"ch_work_nvlt_28","text":"梁劉孝標江州還入石頭詩曰：鼓枻浮大川，延睇洛城觀，洛城何鬱鬱，杳與雲霄半，前望蒼龍門，斜瞻白鶴馆，槐垂御溝道，柳缀金隄岸，迅馬晨風趨，輕舆流水散，高歌梁尘下，瑟荆禽亂，我思江海遊，曾無朝市玩，忽寄靈台宿，空軫及關叹，仲子入南楚，伯鸞出東漢，何能栖树枝，取毙王孫彈。","sortOrder":62},
  {"id":"s_work_nvlt_28_63","chapterId":"ch_work_nvlt_28","text":"梁萧子范東亭極望詩曰：晚流稍東急，暝景促西暉，水鳥衔魚望，莲舟拂芰歸，郊原共超遠，林野雜依菲，從君采萝葛，寧复想輕肥。","sortOrder":63},
  {"id":"s_work_nvlt_28_64","chapterId":"ch_work_nvlt_28","text":"梁萧子暉應教使客春遊詩曰：上林看草色，河桥望日暉，洛陽城閉晚，金鞍橫路歸。","sortOrder":64},
  {"id":"s_work_nvlt_28_65","chapterId":"ch_work_nvlt_28","text":"梁萧子雲落日郡西斋望海山詩曰：漁舟暮出浦，漢女采莲歸，夕雲向山合，水鳥望田飛，蝉鳴早秋至，蕙草無芳菲，故隱天山北，夢想日依依。","sortOrder":65},
  {"id":"s_work_nvlt_28_66","chapterId":"ch_work_nvlt_28","text":"梁吳筠登鍾山宴集望西靜壇詩曰：客思何以缓，春郊滿初律，高車陆離至，駿騎差池出，寶碗汎莲花，珍杯食竹實，才勝商山四，文高竹林七，复望子乔壇，金繩蘊绿帙，風雲生屋宇，芝英被仙室，方隨鳳皇去，悠然駕白日。","sortOrder":66},
  {"id":"s_work_nvlt_28_67","chapterId":"ch_work_nvlt_28","text":"又迎柳吳興道中詩曰：团团日西靡，客念已蹉跎，長風倒危葉，輕練網寒波，白雲光采麗，青松意氣多，所言飽恩德，忘我北山萝。","sortOrder":67},
  {"id":"s_work_nvlt_28_68","chapterId":"ch_work_nvlt_28","text":"梁庾肩吾登城北望詩曰：誓師屠六郡，登城望九顒，山沉黃霧里，地盡黑雲中，霜戈曜垅日，哀笳斷寒風。","sortOrder":68},
  {"id":"s_work_nvlt_28_69","chapterId":"ch_work_nvlt_28","text":"又和衛尉新渝侯巡城口號詩曰：維城寄右戚，巡警屬勤王，南瞻通灞岸，北眺指橫芒，入漢飛延閣，臨雲出建章，步逐天津遠，城隨秋夜長，露槐落金氣，風寮上巉涼。","sortOrder":69},
  {"id":"s_work_nvlt_28_70","chapterId":"ch_work_nvlt_28","text":"又暮遊山水賦韻得碛應令詩曰：餘春屬清夜，西園恣遊歷，入径轉金舆，开桥通畫鹢，細藤初上楥，新流漸涵碛，雲峰没城柳，電影开巖壁。","sortOrder":70},
  {"id":"s_work_nvlt_28_71","chapterId":"ch_work_nvlt_28","text":"又和晉安王薄晚逐涼北樓回望詩曰：向夕紛喧屏，追涼飛觀中，树隱臨城日，窗含度水風，遙天如接岸，遠帆似凌空，陪文慚宋玉，徒等侍蘭宮。","sortOrder":71},
  {"id":"s_work_nvlt_28_72","chapterId":"ch_work_nvlt_28","text":"梁王僧孺落日登高詩曰：凭高且一望，目極不能舍，東北指青門，西南見白社，軫軫河梁上，紛紛渭桥下，爭利亦爭名，驅車复驅馬，寧訪蓬蒿人，誰怜寂寞者。","sortOrder":72},
  {"id":"s_work_nvlt_28_73","chapterId":"ch_work_nvlt_28","text":"又至牛渚憶魏少英詩曰：楓林暧似畫，沙岸靜如扫，空籠望玄石，回斜見危島，绿草間遊蜂，青葭集輕鴇，徘徊洞初月，侵淫潰春涝，非原歲物華，徒用風光好。","sortOrder":73},
  {"id":"s_work_nvlt_28_74","chapterId":"ch_work_nvlt_28","text":"梁王筠和衛新渝侯巡城詩曰：閶阖暧已昏，鉤陳杳將暮，栖鳥城上反，晚雀林中度，閣道趨文昌，禁兵連武库，銅乌迎早風，金掌承朝露，罘罳分晓色，睥睨生秋霧。","sortOrder":74},
  {"id":"s_work_nvlt_28_75","chapterId":"ch_work_nvlt_28","text":"梁劉綏和晚日登樓詩曰：所以登台榭，正重接煙霞，長虹觸欄斷，歸鳥避空斜，俯巢窥瞑宿，臨树摘高花，百雉時方晚，九層光尚賒。","sortOrder":75},
  {"id":"s_work_nvlt_28_76","chapterId":"ch_work_nvlt_28","text":"梁宗懍和歲道寒望詩曰：旅騎出平原，鉦鐃遍野喧，接里开都邑，連車駐小門，稻車回故坞，獵馬轉新村，古碑空戴石，山龛未上幡，所言春不至，未有桃花源。","sortOrder":76},
  {"id":"s_work_nvlt_28_77","chapterId":"ch_work_nvlt_28","text":"北齊劉逖秋朝野望詩曰：駐車凭险岸，飛蓋歷平湖，菊寒花稍發，莲秋葉漸枯，向浦低行雁，排空轉噪乌，若將君共賞，何處减城隅。","sortOrder":77},
  {"id":"s_work_nvlt_28_78","chapterId":"ch_work_nvlt_28","text":"陳陰铿和登百花亭懷荆楚詩曰：江陵一柱觀，尋陽千里潮，風煙望似接，川路恨成遙，落花輕未下，飛絲斷易飄，藤長還依格，荷生不避桥，陽台可憶處，唯有暮將朝。","sortOrder":78},
  {"id":"s_work_nvlt_28_79","chapterId":"ch_work_nvlt_28","text":"又登武昌岸望詩曰：遊人试歷覽，舊跡但丘墟，巴水萦非字，楚山斷類書，荒城高仞落，古柳細條疏，湮芜遂若此，當不為能居。","sortOrder":79},
  {"id":"s_work_nvlt_28_80","chapterId":"ch_work_nvlt_28","text":"又和侯司空登樓望乡詩曰：懷土臨霞觀，思歸想石門，瞻雲望鳥道，對柳憶家園，寒田獲里靜，野日燒中昏，信美今何益，傷心自有源。","sortOrder":80},
  {"id":"s_work_nvlt_28_81","chapterId":"ch_work_nvlt_28","text":"陳張正見遊龍首城詩曰：關外山川闊，城隅尘霧浮，白雲凝絕嶺，沧波間斷洲，四面觀長薄，千里眺平丘，河津無桂树，樽酒自淹留。","sortOrder":81},
  {"id":"s_work_nvlt_28_82","chapterId":"ch_work_nvlt_28","text":"又隨江總秋日登廣州城南樓詩曰：秋城韻晚笛，危榭引清風，遠氣疑埋劍，驚禽似避弓，海树一邊出，山雲四面通，野火初煙細，新月半輪空，塞外離群鳥，顏鬢早如蓬，徒懷建鄴水，复想洛陽宮，不及孤飛雁，獨在上林中。","sortOrder":82},
  {"id":"s_work_nvlt_28_83","chapterId":"ch_work_nvlt_28","text":"【賦】後漢班彪遊居賦曰：夫何事於冀州，聊讬公以遊居，歷九土而觀風，亦慚人之所虞，遂發軫於京洛，臨孟津而北厲，想尚甫之威虞，號蒼兕而明誓，既中流而叹息，美周武之知性，謀人神以動作，享乌魚之瑞命，瞻淇澳之園林，美绿竹之猗猗，望常山之瓘瓘，登北嶽而高遊，嘉孝武之乾乾，親飾躬於伯姬，建封禪於岱宗，瘞玄玉於此丘，遍五嶽與四渎，觀沧海以周流，鄙臣恨不及事，陪後乘之下僚，今匹馬之獨征，豈斯樂之足娱，且休精於敝邑，聊卒歲以須臾。","sortOrder":83},
  {"id":"s_work_nvlt_28_84","chapterId":"ch_work_nvlt_28","text":"魏陳王曹植節遊賦曰：覽宮宇之顯麗，實大人之攸居，建三台於前處，飄飛陛以凌虛，連雲閣以遠径，營觀榭於城隅，亢高軒以迥眺，緣雲霓而結疏，仰西嶽之崧岑，臨漳滏之清渠，觀靡靡而無終，何眇眇而難殊，亮靈後之所處，非吾人之所庐，於是仲春之月，百卉丛生，萋萋藹藹，翠葉朱茎，竹林青葱，珍果含榮，凯風發而時鳥讙，微波動而水虫鳴，感氣運之和润，樂時泽之有成，遂乃浮素蓋，御驊骝，命友生，携同儔，誦風人之所叹，遂駕言而出遊，步北園而馳骛，庶翱翔以寫忧，望洪池之滉漾，遂降集乎輕舟，沉浮蚁於金罍，行觴爵於好仇，絲竹發而响厲，悲風激於中流，且容與以盡觀，聊永日而忘愁，嗟羲和之奋策，怨曜靈之無光，念人生之不永，若春日之微霜，谅遺名之可紀，信天命之無常，愈志荡以淫遊，非經國之大綱，罢曲宴而旋服，遂言歸乎舊房。","sortOrder":84},
  {"id":"s_work_nvlt_28_85","chapterId":"ch_work_nvlt_28","text":"又感節賦曰：携友生而遊觀，盡賓主之所求，登高墉以永望，冀銷日以忘忧，欣陽春之潛润，樂時泽之惠休，望候雁之翔集，想玄鳥之來遊，嗟征夫之長勤，雖處逸而懷愁，懼天河之一回，没我身乎長流，豈吾乡之足顧，恋祖宗之靈丘，惟人生之忽過，若凿石之未曜，慕牛山之哀泣，懼平仲之我笑，折若華之翳日，庶朱光之長炤，原寄軀於飛蓬，乘陽風而遠飄，亮吾志之不從，乃拊心以叹息，青雲鬱其西翔，飛鳥翩而上匿，欲縱體而從之，哀予身之無翼，大風隱其四起，扬黃尘之冥冥，野獸驚以求群，草木紛其扬英，見遊魚之涔灂，感流波之悲聲，內紆曲而潛結，心怛惕以中驚，匪榮德之累身，恐年命之早零，慕歸全之明義，庶不忝乎所生。","sortOrder":85},
  {"id":"s_work_nvlt_28_86","chapterId":"ch_work_nvlt_28","text":"魏楊脩節遊賦曰：爾乃息偃暇豫，携手同征，遊乎北園，以娱以逞，钦太皞之統氣，樂乾坤之布靈，誕煙煴之純和，百卉挺而滋生，穀風習以順時，桡百物而有成，行中林以彷徨，玩奇树之抽英，或素華而雪朗，或紅彩而發赪，绿葉幽蒂，紫柯朱茎，楊柳依依，鍾龍蔚青，紛灼灼以舒葩，芳馥馥以播馨，嗟珍果之丛生，每異類而絕形，禀冲和以固植，信能實而先榮，於是回旋詳觀，目周意倦，御於方舟，載笑載言，仰溯涼風，俯濯纖腕，極歡欣以從容，乃升車而來反。","sortOrder":86},
  {"id":"s_work_nvlt_28_87","chapterId":"ch_work_nvlt_28","text":"【叹】晉石崇思歸叹曰：登城隅兮臨長江，極望無涯兮思填胸，魚瀺灂兮鳥繽翻，泽雉遊枭兮戲中園，秋風厲兮鸿雁征，蟋蟀嘈嘈兮晨夜鳴，落葉飄兮枯枝竦，百草零兮覆畦垅，時光逝兮年易盡，感彼歲暮兮怅自愍，廓羁旅兮滯野都，原御北風兮忽歸徂，惟金石兮幽且清，林鬱茂兮芳卉盈，玄泉流兮萦丘阜，閣馆萧寥兮荫丛柳，吹長笛兮彈五絃，高歌凌雲兮樂餘年，舒篇卷兮與聖談，釋冕投绂兮希彭聃，超逍遙兮絕尘埃，福亦不至兮禍不來。","sortOrder":87},
  {"id":"s_work_nvlt_28_88","chapterId":"ch_work_nvlt_28","text":"【書】魏應璩與滿公琰書，徒恨宴樂始酣，白日傾夕，驪駒就駕，意不宣展，追惟耿介，迄於明發，適欲遣書，會承來命，知諸君子，复有漳渠之會，西有伯陽之觀，北有曠野之望，高榭翳朝雲，文禽蔽绿水，沙場夷敞，清風肅穆，是泉台之樂也，得無流而不反乎，適有事務，須自經營，不獲侍坐，良增悒悒。","sortOrder":88},
  {"id":"s_work_nvlt_28_89","chapterId":"ch_work_nvlt_28","text":"又與從弟君胄書曰：間者北遊，喜歡無量，登芒濟河，曠若發蒙，風伯扫除，雨師洒道，按辔清路，周望山野，亦既至止，酌彼春酒，接武茅茨，棟過大厦，獻寸肴脩，味逾方丈，逍遙陂塘之上，吟詠花柳之下，結春芳以崇珮，折若華以翳日，弋下高雲之鳥，餌出深川之魚，蒲菹贊善，便螺稱妙，何其樂哉，雖仲尼忘味於虞韶，楚人流遯於荆台，無以過也，班嗣之書，信不虛矣，未還京都，塊然獨處，營宅濱洛，困於嚣尘，思樂汶上，發於寤寐，昔伊尹輟耕，郅惲放羊，思致君於有虞，濟蒸民於涂炭，而吾方欲執耒於山陽，沉缗於丹水，知其不如古人遠矣，然山甫不貪天地之樂，曾參不慕晉楚之富，亦其志也。","sortOrder":89},
  {"id":"s_work_nvlt_28_90","chapterId":"ch_work_nvlt_28","text":"《藝文類聚》　唐·欧陽詢","sortOrder":90},
  {"id":"s_work_nvlt_29_1","chapterId":"ch_work_nvlt_29","text":"卷二十九人部十三","sortOrder":1},
  {"id":"s_work_nvlt_29_2","chapterId":"ch_work_nvlt_29","text":"○別上","sortOrder":2},
  {"id":"s_work_nvlt_29_3","chapterId":"ch_work_nvlt_29","text":"◇別上","sortOrder":3},
  {"id":"s_work_nvlt_29_4","chapterId":"ch_work_nvlt_29","text":"《毛詩》曰：出宿於泲，飲餞於祢。","sortOrder":4},
  {"id":"s_work_nvlt_29_5","chapterId":"ch_work_nvlt_29","text":"又曰：顯父餞之，清酒百壶。","sortOrder":5},
  {"id":"s_work_nvlt_29_6","chapterId":"ch_work_nvlt_29","text":"又曰：燕燕，衛莊薑送歸妾也。","sortOrder":6},
  {"id":"s_work_nvlt_29_7","chapterId":"ch_work_nvlt_29","text":"又曰：之子於歸，遠送於野。","sortOrder":7},
  {"id":"s_work_nvlt_29_8","chapterId":"ch_work_nvlt_29","text":"又曰：有女仳離，慨其叹矣。","sortOrder":8},
  {"id":"s_work_nvlt_29_9","chapterId":"ch_work_nvlt_29","text":"《禮記》曰：嫁女之家，三夜不息燭，思相離也，［事具禮部。］","sortOrder":9},
  {"id":"s_work_nvlt_29_10","chapterId":"ch_work_nvlt_29","text":"《家語》曰：孔子去周，而老子送之曰：吾聞富貴者送之以财，仁者送之以言，吾雖不能富貴，而竊仁者之號，請送子以言乎，凡當世之聰明深察而近於死者，好議人者也，博辯閎大而危其身者，好發人之惡者也，孔子曰：敬授［《初學記》十八，《太平御覽》四百八十九作奉。］教。","sortOrder":10},
  {"id":"s_work_nvlt_29_11","chapterId":"ch_work_nvlt_29","text":"《楚辭》曰：離，別也，骚，愁也，言己放逐離別，中心愁思。","sortOrder":11},
  {"id":"s_work_nvlt_29_12","chapterId":"ch_work_nvlt_29","text":"又曰：悲莫悲兮生離別，樂莫樂兮新相知。","sortOrder":12},
  {"id":"s_work_nvlt_29_13","chapterId":"ch_work_nvlt_29","text":"又曰：憭栗兮若在遠行，登山臨水送將歸。","sortOrder":13},
  {"id":"s_work_nvlt_29_14","chapterId":"ch_work_nvlt_29","text":"又曰：超北梁兮永辭，送美人兮南浦。","sortOrder":14},
  {"id":"s_work_nvlt_29_15","chapterId":"ch_work_nvlt_29","text":"《呂氏春秋》曰：吳起，魏武侯送之曰：何以治西河，對曰：以忠信。","sortOrder":15},
  {"id":"s_work_nvlt_29_16","chapterId":"ch_work_nvlt_29","text":"《吳越春秋》曰：勾踐伐吳，乃命國中與之訣，而國人悲哀，皆作離別之聲。","sortOrder":16},
  {"id":"s_work_nvlt_29_17","chapterId":"ch_work_nvlt_29","text":"又曰：群臣送勾踐，至於江上，臨水祖道，大夫种為祝，勾踐舉杯垂涕。","sortOrder":17},
  {"id":"s_work_nvlt_29_18","chapterId":"ch_work_nvlt_29","text":"孔丛曰：子高遊趙，平原君客有邹文李節者，與相友善，及將還魯，諸故人訣既畢，文節送行，三宿，臨別，文節流涕交颐，子高徒抗手而已，分背就路，其徒問曰：先生與彼二子善，彼有恋恋之心，未知後會何期，凄怆流涕，而先生厲聲高揖，無乃非親親之謂乎，子高曰：始吾謂二子丈夫爾，乃今知其婦人也，人豈鹿豕也哉，而常群聚乎。","sortOrder":18},
  {"id":"s_work_nvlt_29_19","chapterId":"ch_work_nvlt_29","text":"《漢書》曰：武帝平陽公主家衛子夫，得幸，主因奏子夫送入宮，子夫上車，主拊其背曰：去矣，即貴原無相忘，［事具储官部公主篇。］","sortOrder":19},
  {"id":"s_work_nvlt_29_20","chapterId":"ch_work_nvlt_29","text":"又曰：疏廣與兄子受，併為皇太子師傅，廣謂受曰：吾聞知足不辱，知止不殆，功遂身退，天之道也，遂上疏乞骸骨，上許之，公卿大夫，故人邑子，遂為設祖道，供帳東都門外，送者車數百兩，辭訣去，及道路觀者，皆曰：賢哉二大夫，或叹息，為之下泣。","sortOrder":20},
  {"id":"s_work_nvlt_29_21","chapterId":"ch_work_nvlt_29","text":"又曰：李廣利將兵击匈奴，丞相為祖道，至渭桥。","sortOrder":21},
  {"id":"s_work_nvlt_29_22","chapterId":"ch_work_nvlt_29","text":"又曰：窦皇後弟廣國曰：姊去我西時，與我訣於傳舍中，沐我。","sortOrder":22},
  {"id":"s_work_nvlt_29_23","chapterId":"ch_work_nvlt_29","text":"又曰：成帝遣定陶王之國，王辭去，上與相對泣而訣。","sortOrder":23},
  {"id":"s_work_nvlt_29_24","chapterId":"ch_work_nvlt_29","text":"《東觀漢記》曰：陳遵使匈奴，過辭於王丹，丹謂遵曰：俱遭世反覆，唯我二人為天地所遺，今子當之絕域，無以相赠，赠子以不拜，遂揖而別，遵甚喜。","sortOrder":24},
  {"id":"s_work_nvlt_29_25","chapterId":"ch_work_nvlt_29","text":"又曰：東平王蒼，與諸王朝京師，月餘還，帝臨送，歸宮凄然懷思，乃遣使手詔諸國曰：辭別之後，獨坐不樂，因就車歸，伏軾而吟，瞻望永懷，實勞我心，誦及采菽，以增叹息。","sortOrder":25},
  {"id":"s_work_nvlt_29_26","chapterId":"ch_work_nvlt_29","text":"又曰：肅宗遣諸王歸國，帝特留東平王蒼，賜以秘書列圖，道術秘方，至八月飲酎畢，有司复奏遣蒼，乃許之，手詔賜蒼曰：骨肉與天性，誠不以遠近親疏，然數見顏色，情重昔時，中心恋恋，惻然不能言，於是車駕祖送，流涕而訣，复賜乘舆服御珍寶，鞍馬錢布，以亿萬計。","sortOrder":26},
  {"id":"s_work_nvlt_29_27","chapterId":"ch_work_nvlt_29","text":"又曰：光武遣冯異讨赤眉，車駕送至河南，賜以乘舆七尺具劍，敕異曰：念自修整，無為郡縣所笑，異頓首受命。","sortOrder":27},
  {"id":"s_work_nvlt_29_28","chapterId":"ch_work_nvlt_29","text":"謝承《後漢書》曰：范丹與王奐親善，奐後為漢陽太守，丹於道候別之，奐曰：行路仓卒，非陳闊之所，可共到前亭宿息，以叙分隔，丹曰：今子遠適千里，會面無期，如其相追，將有慕貴之譏矣，便起告违，拂衣而去，奐瞻望弗及，丹長逝不顧。","sortOrder":28},
  {"id":"s_work_nvlt_29_29","chapterId":"ch_work_nvlt_29","text":"《吳志》曰：魯肅代周瑜，過呂蒙，酒酣，蒙問肅曰：君受重任，與關羽為鄰，將何計略，以備不虞，肅應曰：臨時施宜，蒙因為畫五策，肅於是越席就之，拊其背曰：呂子明，吾不知卿才略所及，至於此也，遂拜蒙母，結友而別。","sortOrder":29},
  {"id":"s_work_nvlt_29_30","chapterId":"ch_work_nvlt_29","text":"又曰：劉繇亡於豫章，孫策命太史慈往安撫之，左右皆曰：慈必北去不還，策曰：子義舍我，當复與誰，餞送昌門，把腕別曰：何時能還，答曰：不過六十日，果如期而反。","sortOrder":30},
  {"id":"s_work_nvlt_29_31","chapterId":"ch_work_nvlt_29","text":"《吳錄》曰：孫權祖朱桓，桓奉觴曰：臣當遠去，原一持陛下須，無所恨，權凭機前席，桓進捋須。","sortOrder":31},
  {"id":"s_work_nvlt_29_32","chapterId":"ch_work_nvlt_29","text":"《魏志》曰：曹休為镇南將軍，假節都督軍事，車馬臨送，下舆執手而別。","sortOrder":32},
  {"id":"s_work_nvlt_29_33","chapterId":"ch_work_nvlt_29","text":"《蜀志》曰：宗豫聘吳，孫權捉豫手，涕泣而別曰：君每衔命，結二國之好，今君年長，孤亦老矣，恐不复相見。","sortOrder":33},
  {"id":"s_work_nvlt_29_34","chapterId":"ch_work_nvlt_29","text":"《管辂別傳》曰：諸葛樂［魏志二十九管辂傳作原。］與辂別，戒以二言，卿性樂酒，雖溫克，然不可保，寧當節之，卿有水鏡之才，所見者妙，禍如膏火，不可不慎。","sortOrder":34},
  {"id":"s_work_nvlt_29_35","chapterId":"ch_work_nvlt_29","text":"許邁別傳曰：邁好養生，遣妻歸家，東遊，采藥於桐庐山，欲斷穀，以山近人，不得专一，移入臨安，自以無复反，乃改名遠遊，書與婦別。","sortOrder":35},
  {"id":"s_work_nvlt_29_36","chapterId":"ch_work_nvlt_29","text":"《語林》曰：有人詣謝公別，謝公流涕，此人了不悲，既去，左右曰：向客殊自密雲，謝公曰：非徒密雲，乃自旱雷爾。","sortOrder":36},
  {"id":"s_work_nvlt_29_37","chapterId":"ch_work_nvlt_29","text":"《俗說》曰：張敷從彭城還，傅亮下舡與別，張不起，授手著舫戶外，傅遂不執手，熟视張面雲，查故是梨中不臧者，便去。","sortOrder":37},
  {"id":"s_work_nvlt_29_38","chapterId":"ch_work_nvlt_29","text":"《世說》曰：阮籍嫂嘗歸家，籍相見與別，人或譏之，籍曰：禮豈為我辈設耶。","sortOrder":38},
  {"id":"s_work_nvlt_29_39","chapterId":"ch_work_nvlt_29","text":"《廣州記》曰：尉他筑台，以朝朔望，構起華馆，以送陆贾，［事具居處部。］沈約《宋書》曰：張敷音儀詳缓，與人別，執手曰：念相聞，餘响久之不絕。","sortOrder":39},
  {"id":"s_work_nvlt_29_40","chapterId":"ch_work_nvlt_29","text":"又曰：殷仲文還姑熟，祖送傾朝，桓謙要參軍王弘同行，答曰：餞離送別，必在有情，下官與殷風馬不接，無緣扈從，謙貴其言。","sortOrder":40},
  {"id":"s_work_nvlt_29_41","chapterId":"ch_work_nvlt_29","text":"【詩】古詩曰：行行重行行，與君生別離，相去萬餘里，各在一天［文選二十九，《初學記》十八作天一。］涯，道路阻且長，會面安可知，胡馬依北風，越鳥巢南枝，相去日已遠，衣帶日已缓，浮雲蔽白日，遊子不顧反，思君令人老，歲月忽已晚，弃捐勿复道，努力加餐飯。","sortOrder":41},
  {"id":"s_work_nvlt_29_42","chapterId":"ch_work_nvlt_29","text":"又古詩曰：明月何皎皎，照我羅床帷，忧愁不能寐，攬衣起徘徊，行客雖雲樂，不如早旋歸。","sortOrder":42},
  {"id":"s_work_nvlt_29_43","chapterId":"ch_work_nvlt_29","text":"古詩曰：涉江采芙蓉，蘭泽多芳草，采之欲遺誰，所思在遠道，還顧望舊乡，長路漫浩浩，同心而離居，忧傷已終老。","sortOrder":43},
  {"id":"s_work_nvlt_29_44","chapterId":"ch_work_nvlt_29","text":"古詩曰：庭中有奇树，绿葉發華滋，攀條折其榮，將以遺所思，馨香盈懷袖，路遠莫致之，此物何足貴，但感別經時。","sortOrder":44},
  {"id":"s_work_nvlt_29_45","chapterId":"ch_work_nvlt_29","text":"漢李陵赠蘇武別詩曰：晨風鳴北林，熠燿東南飛，原言所相思，日暮不垂帷，明月照高樓，想見餘光辉，玄鳥夜過庭，仿佛能复飛，褰裳路踟蹰，彷徨不能歸，浮雲日千里，安知我心悲，思得琼树枝，以解長渴飢。","sortOrder":45},
  {"id":"s_work_nvlt_29_46","chapterId":"ch_work_nvlt_29","text":"又赠蘇武別詩曰：良時不再至，離別在須臾，屏營衢路侧，執手野踟蹰，仰视浮雲馳，奄忽交相逾，風波一失路，各在一天［《文選》二十九作天一。］隅，長當從此別，且复去斯須，欲因晨風發，送子以賤軀。","sortOrder":46},
  {"id":"s_work_nvlt_29_47","chapterId":"ch_work_nvlt_29","text":"蘇武詩曰：骨肉緣枝葉，結交亦相因，四海皆兄弟，誰為行路人，况我連枝树，與子同一身，昔為鴛與鴦，今為參與辰，昔在常相近，邈若胡與秦，惟念當離別，思情日已新，鹿鳴思野草，可以喻嘉賓，我有一樽酒，欲以赠遠人，原子留斟酌，慰我平生親。","sortOrder":47},
  {"id":"s_work_nvlt_29_48","chapterId":"ch_work_nvlt_29","text":"又赠蘇武別詩曰：嘉會難再遇，三載為千秋，臨河濯長纓，念別怅悠悠，望望悲風至，對酒不能酬，行人懷往路，何以慰我愁，獨有盈觴酒，與子結綢缪。","sortOrder":48},
  {"id":"s_work_nvlt_29_49","chapterId":"ch_work_nvlt_29","text":"又蘇武詩曰：黃鵠一遠別，千里顧徘徊，胡馬失其群，思心常依依，何况双飛龍，羽翼臨當乖，幸有絃歌曲，可以喻中懷，請為遊子吟，泠泠一何悲，絲竹厲清聲，慷慨有餘哀，長歌正激烈，中心怆以摧，欲展清商曲，念子不能歸，俛仰內傷心，淚下不可揮，原為双黃鵠，送子俱遠飛。","sortOrder":49},
  {"id":"s_work_nvlt_29_50","chapterId":"ch_work_nvlt_29","text":"又赠蘇武詩曰：携手上河梁，遊子暮何之，徘徊溪路侧，恨恨不能離，行人難久留，各言長相思，安知非日月，絃望自有時，努力崇明德，皓首以為期。","sortOrder":50},
  {"id":"s_work_nvlt_29_51","chapterId":"ch_work_nvlt_29","text":"又赠蘇武別詩曰：陟彼南山隅，送子淇水陽，爾行西南遊，我獨東北翔，轅馬顧悲鳴，五步一彷徨，双凫相背飛，相遠日已長，遠望雲中路，想見來珪璋，萬里遙相思，何益心獨傷，隨時愛景曜，原言莫相忘。","sortOrder":51},
  {"id":"s_work_nvlt_29_52","chapterId":"ch_work_nvlt_29","text":"又赠蘇武詩曰：烁烁三星列，拳拳月初生，寒涼應節至，蟋蟀夜悲鳴，晨風動乔木，枝葉日夜零，遊子暮歸思，塞耳不能聽，遠望正萧條，百里無人聲，遠處天一隅，苦困獨伶丁，親人隨風散，瀝滴如流星，原得萱草枝，以解飢渴情。","sortOrder":52},
  {"id":"s_work_nvlt_29_53","chapterId":"ch_work_nvlt_29","text":"又赠蘇武別詩曰：鍾子歌南音，仲尼叹歸與，戎馬悲邊鳴，遊子恋故庐，陽鳥歸飛雲，蛟龍樂潛居，人生一世間，貴與原同俱，身無四凶罪，何為天一隅，與其苦筋力，必欲榮薄軀，不如及清時，策名於天衢。","sortOrder":53},
  {"id":"s_work_nvlt_29_54","chapterId":"ch_work_nvlt_29","text":"漢蘇武別李陵詩曰：双凫俱北飛，一凫獨南翔，子當留斯馆，我當歸故乡，一別如秦胡，會見何詎央，怆恨切中懷，不覺淚霑裳，原子長努力，言笑莫相忘。","sortOrder":54},
  {"id":"s_work_nvlt_29_55","chapterId":"ch_work_nvlt_29","text":"又別李陵詩曰：征夫懷往路，起视夜何其，參辰皆已没，去去從此辭，行役在戰場，相見未有期，握手一長叹，淚為生別滋，努力愛春華，莫忘歡樂時，生當复來歸，死當長相思。","sortOrder":55},
  {"id":"s_work_nvlt_29_56","chapterId":"ch_work_nvlt_29","text":"魏文帝代劉勋出妻王氏詩曰：翩翩床前帳，可以蔽光辉，昔將爾同去，今將爾共歸，緘藏箧笥里，當复何時披。","sortOrder":56},
  {"id":"s_work_nvlt_29_57","chapterId":"ch_work_nvlt_29","text":"魏陳王曹植詩曰：門有萬里客，問君何乡人，褰裳起從之，果得心所親，挽裳對我泣，太息前自陳，本是朔方士，今為吳越民，行行將复行，去去適西秦。","sortOrder":57},
  {"id":"s_work_nvlt_29_58","chapterId":"ch_work_nvlt_29","text":"又詩曰：微陰翳陽景，清風飄我衣，遊魚潛渌水，翔鳥薄天飛，眇眇客行士，徭役不得歸，始出嚴霜結，今來白露晞，遊子叹黍離，處者歌式微，慷慨對嘉賓，凄怆內傷悲。","sortOrder":58},
  {"id":"s_work_nvlt_29_59","chapterId":"ch_work_nvlt_29","text":"又送應氏詩曰：原得展嬿婉，我友之朔方，親昵併集送，置酒此河陽，山川迥且遠，別促會日長。","sortOrder":59},
  {"id":"s_work_nvlt_29_60","chapterId":"ch_work_nvlt_29","text":"又離友詩曰：涼風肅兮白露滋，木感氣兮條葉辭，臨渌水兮登重基，折秋華兮采靈芝，尋永歸兮赠所思，感離隔兮會無期，伊鬱悒兮情不怡。","sortOrder":60},
  {"id":"s_work_nvlt_29_61","chapterId":"ch_work_nvlt_29","text":"魏應玚別詩曰：朝雲浮四海，日暮歸故山，行役懷舊土，悲思不能言，悠悠涉千里，未知何時旋。","sortOrder":61},
  {"id":"s_work_nvlt_29_62","chapterId":"ch_work_nvlt_29","text":"又別詩曰：浩浩長河水，九折東北流，晨夜赴沧海，海流亦何抽，遠適萬里道，歸來未有由，臨河累太息，五內懷傷忧。","sortOrder":62},
  {"id":"s_work_nvlt_29_63","chapterId":"ch_work_nvlt_29","text":"魏徐幹為挽舡士與新娶妻別詩曰：與君結新婚，宿昔當別離，涼風動秋草，蟋蟀鳴相隨，蚓蚓寒蝉吟，蝉吟抱枯枝，枯枝時飛扬，身體忽遷移，不悲身體移，當惜歲月馳，月馳無窮極，會合安可知，原為双黃鵠，悲鳴戲清池。","sortOrder":63},
  {"id":"s_work_nvlt_29_64","chapterId":"ch_work_nvlt_29","text":"晉孫楚答弘農故吏民詩曰：昔我先侯，邁德垂化，康哉之詠，寔由良佐，惟餘忝辱，弗克負荷，每歷貴邦，仰瞻泰華，追慕先軌，感想哀嗟，诜诜臣故，爰及群士，皓首老成，率彼邑里，闡崇高義，長幼以齒。","sortOrder":64},
  {"id":"s_work_nvlt_29_65","chapterId":"ch_work_nvlt_29","text":"又征西官屬送別詩曰：晨風飄岐路，零雨被芳草，傾城遠相送，餞我千里道，乖離即長衢，惆怅盈懷抱。","sortOrder":65},
  {"id":"s_work_nvlt_29_66","chapterId":"ch_work_nvlt_29","text":"晉潘嶽北芒送別王世胄詩曰：朱鑣既扬，四辔既整，駕言餞行，告離芒嶺，情有遷延，日無餘影，回轅南翔，心焉北騁。","sortOrder":66},
  {"id":"s_work_nvlt_29_67","chapterId":"ch_work_nvlt_29","text":"又金穀集詩曰：王生和鼎實，石子镇海沂，親友各言邁，中心怅有违，何以叙離思，携手遊郊畿，朝發晉京陽，夕次金穀湄，回谿萦曲阻，峻坂路威夷，渌池泛淡淡，青柳何依依，玄醴染朱顏，但訴杯行遲，投分寄石友，白首同所歸。","sortOrder":67},
  {"id":"s_work_nvlt_29_68","chapterId":"ch_work_nvlt_29","text":"晉潘尼送盧弋陽景宣詩曰：楊朱焉所哭，岐路重別離，屈原何傷悲，生離情獨哀，知命雖無忧，仓卒意低回，叹氣從中發，洒淚隨襟頹，九重不常鍵，閶阖有時开，愧無纻衣獻，貽言取諸懷。","sortOrder":68},
  {"id":"s_work_nvlt_29_69","chapterId":"ch_work_nvlt_29","text":"又皇太子集應令詩曰：聖朝命方嶽，爪牙思北鄰，皇储延篤愛，設餞送遠賓，誰應今日宴，具惟廊廟臣，置酒宴猷庭，击鼓靈沼濱，羽觴飛酃醁，芳饌備奇珍，巴渝二八奏，妙舞鼓铎振，長袂生回飄，曲裾扬輕尘，晉王浚從幸洛水餞王公歸國詩曰：聖主應期運，至德敷彝倫，神道垂大教，玄化被無垠，钦若崇古製，建侯屏四鄰，皇舆回羽蓋，高會洛水濱，臨川講妙藝，縱酒釣潛鱗，八音以迭奏，蘭羞備時珍，古人亦有言，為國不患貧，與蒙廟庭施，幸得廁太鈞，群僚荷恩泽，朱顏感獻春，賦詩盡下情，至感畅人神，長流無舍逝，白日入西津，奉辭慕華輦，侍衛路無因，馳情系帷幄，乃心恋軌尘。","sortOrder":69},
  {"id":"s_work_nvlt_29_70","chapterId":"ch_work_nvlt_29","text":"晉陆機祖道畢雍孫劉邊仲潘正叔詩曰：皇储延髦俊，多士出幽遐，適遂時來運，與子遊承華，執笏崇賢內，振纓曾城阿，畢劉贊文武，潘生莅邦家，感別懷遠人，原言叹以嗟。","sortOrder":70},
  {"id":"s_work_nvlt_29_71","chapterId":"ch_work_nvlt_29","text":"又於承明作與弟士龍詩曰：牵世纓時網，駕言遠徂征，飲餞豈異族，親戚弟與兄，分涂長林侧，揮袂萬始亭，南歸憩永安，北邁頓承明。","sortOrder":71},
  {"id":"s_work_nvlt_29_72","chapterId":"ch_work_nvlt_29","text":"又送顧公直詩曰：伐鼓五嶺表，扬聲萬里外，高山向足陵，巨海猶萦帶。","sortOrder":72},
  {"id":"s_work_nvlt_29_73","chapterId":"ch_work_nvlt_29","text":"又擬庭中有奇树詩曰：芳草忽已茂，佳人竟不歸，感物恋所歡，采此當遺誰。","sortOrder":73},
  {"id":"s_work_nvlt_29_74","chapterId":"ch_work_nvlt_29","text":"晉王濬祖道應令詩曰：侯誰在矣，東宮诜诜，曰保曰傅，弘道惟新，前疑协衡，顧問翼輪，豈伊張仲，专美前津，煥乎唐德，钦在四鄰，齊軌上葉，永垂清尘。","sortOrder":74},
  {"id":"s_work_nvlt_29_75","chapterId":"ch_work_nvlt_29","text":"晉左思赠妹九嫔悼離詩曰：鬱鬱岱清，海渎所經，陰精以靈，為祥為禎，瓘瓘令妹，應期誕生，如蘭之秀，如芝之榮，總角岐嶷，龀龆夙成，比德古烈，異世同聲，惟我惟妹，寔惟同生，早丧先妣，恩百常情，女子有行，實遠父兄，骨肉之恩，固有歸寧，何悟離析，隔以天庭，自我不見，於今二齡，穆穆令妹，有德有言，才麗漢班，明朗楚樊，默識若記，下筆成篇，行顯中閨，名播外藩，何以為赠，勉以烈圖，何以為言，申以詩書，相去在近，上下欷歔，含辭滿胸，鬱煩不舒。","sortOrder":75},
  {"id":"s_work_nvlt_29_76","chapterId":"ch_work_nvlt_29","text":"晉張華祖道征西應詔詩曰：赫赫大晉，奄有萬方，陶以仁化，曜以天光，二跡陝西，實在我王，內飪玉铉，外惟鷹扬，四牡扬鑣，玄辂振綏，庶寮群後，餞飲洛湄，感離叹凄，慕德遲遲。","sortOrder":76},
  {"id":"s_work_nvlt_29_77","chapterId":"ch_work_nvlt_29","text":"又祖道趙王應詔詩曰：崇選穆穆，利建明德，於顯穆親，時惟我王，禀姿自然，金质玉相，光宅舊趙，作镇異方，休寵曲錫，備物煥彰，發轫上京，出自天邑，百寮餞行，搢紳具集，軒冕瓘瓘，冠蓋習習，恋德惟懷，永叹弗及，晉陆雲餞太尉王公還京邑詩曰：聖泽既渥，嘉會愔愔，庭旅鍾鼓，堂有瑟琴，飛辔清暉，扶桑移陰，视景祗慕，揮袂霑襟，恋彼同栖，悲爾異林，我有旨酒，以歌以吟。","sortOrder":77},
  {"id":"s_work_nvlt_29_78","chapterId":"ch_work_nvlt_29","text":"又赠兄詩曰：行矣怨路長，惄焉傷別促，指途悲有餘，臨觴歡不足，我若西流水，子如東峙嶽，慷慨逝言感，徘徊居情育，安得携手俱，契闊成騑服，悠遠涂可極，別促怨會長，衔思恋行邁，興言在臨觴，南津有絕濟，北渚河無梁，神往同逝感，形留悲參商。","sortOrder":78},
  {"id":"s_work_nvlt_29_79","chapterId":"ch_work_nvlt_29","text":"又左九嫔感離詩曰：自我去膝下，倏忽逾再期，邈邈浸弥遠，拜奉將何時，披省所賜告，尋玩悼離詞，仿佛想容儀，歔欷不自持，何時當奉面，娱目於書詩，何以訴辛苦，告情於文辭。","sortOrder":79},
  {"id":"s_work_nvlt_29_80","chapterId":"ch_work_nvlt_29","text":"晉殷仲文送東陽太守詩曰：昔人深誠叹，臨水送將離，如何祖良遊，心事孱在斯，虛亭無留賓，東川緬逶迤。","sortOrder":80},
  {"id":"s_work_nvlt_29_81","chapterId":"ch_work_nvlt_29","text":"晉何敬祖洛水祖王公應詔詩曰：穆穆聖皇，體此慈仁，友於之至，通於明神，遊宴綢缪，情恋所親，薄言餞之，於洛之濱，嵩崖巖巖，洪流湯湯，春風動衿，歸雁和鳴，我後饗客，鼓瑟吹笙，舉爵惟別，聞樂傷情，嘉宴既終，白日西歸，群司告旋，鸞舆整綏，我皇重離，頓辔驂騑，臨川永叹，酸涕霑颐，崇恩感物，左右同悲。","sortOrder":81},
  {"id":"s_work_nvlt_29_82","chapterId":"ch_work_nvlt_29","text":"宋孝武與庐陵王紹別詩曰：連歲矜離心，今茲幸良集，信宿窮晨暮，开顏披所戢，未盡歡晤懷，已傷岐路及，舳舻引江介，飛旌背爾邑，悄扰徒旅戒，团栾流景入，遲遲分手念，泫泫登路泣。","sortOrder":82},
  {"id":"s_work_nvlt_29_83","chapterId":"ch_work_nvlt_29","text":"宋南［原脱，據冯校本補。］平王代收淚［原脱，據冯校本補。］就長路詩曰：耸辔高陵曲，揮袂廣川濆，黃尘昏白日，悲風起浮雲，萧條萬里別，契闊三秋分，時往從朝露，年來驚夕氲，徘徊去芳節，依遲從遠軍。","sortOrder":83},
  {"id":"s_work_nvlt_29_84","chapterId":"ch_work_nvlt_29","text":"宋謝靈運相送方山詩曰：祗役出皇邑，指期憩甌越，解纜及流潮，懷舊不能發，折折就衰林，皎皎明秋月，含情易為盈，遇物難可歇。又答謝惠連詩曰：懷人行千里，我勞盈十旬，別時花灼灼，別後葉蓁蓁。","sortOrder":84},
  {"id":"s_work_nvlt_29_85","chapterId":"ch_work_nvlt_29","text":"宋謝惠連西陵獻康樂詩曰：哲兄感仳別，相送越埛林，飲餞野亭馆，分袂澄湖陰，凄凄留子言，眷眷浮客心，回塘隱舻枻，遠望絕形音。","sortOrder":85},
  {"id":"s_work_nvlt_29_86","chapterId":"ch_work_nvlt_29","text":"又與孔曲阿別詩曰：凄凄乘蘭秋，言餞千里舟，涂屆雲陽邑，邑宰有昔遊，行人雖念路，為爾暫淹留。","sortOrder":86},
  {"id":"s_work_nvlt_29_87","chapterId":"ch_work_nvlt_29","text":"又夜集叹乖詩曰：詩人詠踟蹰，骚者歌離別，誠哉曩日歡，展矣今夕切，吾生赴遙命，质明即行轍，在貧故宜言，赠子保溫惠，曷用書諸紳，久要亮有誓。","sortOrder":87},
  {"id":"s_work_nvlt_29_88","chapterId":"ch_work_nvlt_29","text":"宋顏延之為皇太子侍宴餞衡陽南平二王應詔詩曰：大儀在御，皇聖居貞，旁緝民紀，仰緯天經，物資感变，神以瑞形，川無遁寶，山不閟靈，亦既戒裝，皇心載遠，夕帳亭皋，晨儀禁苑，神行景骛，發自靈阃，對宴感分，瞻秋悼晚。","sortOrder":88},
  {"id":"s_work_nvlt_29_89","chapterId":"ch_work_nvlt_29","text":"宋鮑昭詩曰：輕鸿戲江潭，孤雁集洲沚，邂逅兩相親，同念共無已，風雨好東西，一隅頓千里，追憶栖宿時，聲客滿心耳，扬翮不能翔，徘徊煙霧里。","sortOrder":89},
  {"id":"s_work_nvlt_29_90","chapterId":"ch_work_nvlt_29","text":"又送盛侍郎詩曰：北臨出塞道，南望入乡津，高墉宿寒霧，平野起秋尘。","sortOrder":90},
  {"id":"s_work_nvlt_29_91","chapterId":"ch_work_nvlt_29","text":"齊王俭後園餞從兄豫章詩曰：茲夕竟何夕，念別开曾軒，光風轉蘭蕙，流月汎虛園。","sortOrder":91},
  {"id":"s_work_nvlt_29_92","chapterId":"ch_work_nvlt_29","text":"齊王融奉辭镇西應教詩曰：未學謝能筭，高義幸知遊，霤庭參辯奭，梁苑豫才邹，徘徊歲光晚，搖落江树秋，風旗萦別浦，霜琯迾遙州。","sortOrder":92},
  {"id":"s_work_nvlt_29_93","chapterId":"ch_work_nvlt_29","text":"又萧谘議西上夜集詩曰：徘徊將所忧，惜別在河梁，衿袖三春隔，江山千里長，寸心無遠近，邊地有風霜，勉哉勤歲暮，敬矣慎容光，山中殊未怿，杜若空自芳。","sortOrder":93},
  {"id":"s_work_nvlt_29_94","chapterId":"ch_work_nvlt_29","text":"齊謝朓別王僧孺詩曰：花树雜為錦，月池皎如練，如何當此時，別離言與宴，非君不見思，所悲思不見。","sortOrder":94},
  {"id":"s_work_nvlt_29_95","chapterId":"ch_work_nvlt_29","text":"又與江水曹詩曰：山中上芳月，故人清樽賞，遠山翠百重，回流映千丈，花枝聚如雪，垂藤散猶網，別後能相思，何差異風壤。","sortOrder":95},
  {"id":"s_work_nvlt_29_96","chapterId":"ch_work_nvlt_29","text":"又懷故人詩曰：芳洲有杜若，可以赠佳期，望望忽超遠，何由見所思，我行未千里，山川已間之，離居方歲月，故人不在茲，清風動帘夜，孤月照窗時，安得同携手，酌酒賦新詩。","sortOrder":96},
  {"id":"s_work_nvlt_29_97","chapterId":"ch_work_nvlt_29","text":"又離夜詩曰：玉繩隱高树，斜漢映曾台，離堂華燭盡，別幌清琴哀，翻潮尚知限，客思眇難裁，山川不可夢，况乃故人杯。","sortOrder":97},
  {"id":"s_work_nvlt_29_98","chapterId":"ch_work_nvlt_29","text":"又將發石頭上烽火樓詩曰：徘徊恋皇邑，踯躅曬曾阿，陵高墀闕近，眺迥風雲多，荆吳阻山岫，江海合澜波，歸飛無羽翼，其如別離何。","sortOrder":98},
  {"id":"s_work_nvlt_29_99","chapterId":"ch_work_nvlt_29","text":"又新亭渚別范雲詩曰：洞庭張樂地，萧［《文選》二十作瀟。］湘帝子遊，雲去蒼梧野，水還江漢流，停驂我怅望，輟棹子夷猶，廣平聽方籍，茂陵方見求，心事俱已矣，江上徒離忧。","sortOrder":99},
  {"id":"s_work_nvlt_29_100","chapterId":"ch_work_nvlt_29","text":"齊虞義［按當作羲。］送友人上湘詩曰：濡足送征人，褰裳臨水路，共盈一樽酒，對之愁日暮，漢廣雖容舠，風悲未可渡，佳期難再得，原但論心故，沅水日生波，芳洲行墜露，共知丘壑改，同無金石固。","sortOrder":100},
  {"id":"s_work_nvlt_29_101","chapterId":"ch_work_nvlt_29","text":"齊劉繪送別詩曰：春滿方解箨，弱柳向低風，相思將安寄，怅望南飛鸿。","sortOrder":101},
  {"id":"s_work_nvlt_29_102","chapterId":"ch_work_nvlt_29","text":"齊張融別詩曰：白雲山上盡，清風松下歇，欲識離人悲，孤台見明月。","sortOrder":102},
  {"id":"s_work_nvlt_29_103","chapterId":"ch_work_nvlt_29","text":"梁簡文帝示晉陵弟詩曰：零雨岐路悲，送歸臨水節，時事雖為舛，離忧等閒別。","sortOrder":103},
  {"id":"s_work_nvlt_29_104","chapterId":"ch_work_nvlt_29","text":"又餞臨海太守劉孝儀蜀郡太守劉孝勝詩曰：碣石臨東海，峨眉距西候，兩杜昔夹河，二龍今出守，方無夜犬驚，向息神牛斗，涼風繞輕幕，麥雨交新溜，念此一衔觴，懷離在惟舊。","sortOrder":104},
  {"id":"s_work_nvlt_29_105","chapterId":"ch_work_nvlt_29","text":"又餞庐陵內史王脩應令詩曰：餞行臨上節，开筵命羽觴，回池泻飛棟，浓雲垂畫堂，疏槐未合影，反日暫流光，園梅斂新衰，階蕙結初芳。","sortOrder":105},
  {"id":"s_work_nvlt_29_106","chapterId":"ch_work_nvlt_29","text":"又餞別詩曰：行樂南北皮，宴餞臨華池，箨解篁开節，花闇鳥迷枝，窗陰隨影度，水色帶風移，徒命衔杯酒，終成悯別離。","sortOrder":106},
  {"id":"s_work_nvlt_29_107","chapterId":"ch_work_nvlt_29","text":"又送別詩曰：行行異溯海，依依別路岐，水苔隨纜聚，岸柳拂舟垂，石菌生懸葉，江槎流臥枝，燭盡悲宵去，酒滿惜將離。","sortOrder":107},
  {"id":"s_work_nvlt_29_108","chapterId":"ch_work_nvlt_29","text":"又傷離新體詩曰：傷離复傷離，別後情鬱紆，凄凄隱去棹，悯悯怆還途，慼慼意不申，轉顧獨霑襟，前驅經御宿，後騎歷河漘，胡香翼還幰，清笳送後尘，落日斜飛蓋，餘暉承畫輪，柳影長橫路，槐枝深隱人，桂宮夕掩銅龍扉，甲馆宵垂雲母帏，胧胧月色上，的的夜螢飛，草香袭餘袂，露洒霑人衣，帶堞凌城雲亂聚，排枝度葉鳥爭歸，碗中浮蚁不能酌，琴間玉徽調別鶴，別鶴千里別離聲，絃調軫急心自驚，试起登南樓，還向華池遊，前時筱生今欲合，近日裁荷尚不抽，猶是衔杯共賞處，今茲對此獨生愁，樓高望暧暧，山川自分態，偃師雖北連，轘轅已南背，遠聽寂無聞，遙瞻目有閡，含毫意不迷，長叹情無賴。","sortOrder":108},
  {"id":"s_work_nvlt_29_109","chapterId":"ch_work_nvlt_29","text":"梁昭明春日宴晉熙王詩曰：百六鍾期數，三七厄時中，國難悲如毀，親離叹數窮，藩哲遊沮夢，楊化撫邊戎，幸茲同宴醑，引滿愛樽空。","sortOrder":109},
  {"id":"s_work_nvlt_29_110","chapterId":"ch_work_nvlt_29","text":"梁范雲之零陵郡次新亭詩曰：江幹遠树浮，天末孤煙起，江天自如合，煙树還相似，沧流未可源，高飄去何已。","sortOrder":110},
  {"id":"s_work_nvlt_29_111","chapterId":"ch_work_nvlt_29","text":"又別詩曰：洛陽城東西，長作經時別，昔去雪如花，今來花似雪。","sortOrder":111},
  {"id":"s_work_nvlt_29_112","chapterId":"ch_work_nvlt_29","text":"又送沈記室夜別詩曰：桂水澄夜分，桂山清晓雲，秋風兩乡怨，秋月千里分，寒芝寧共采，霜猿行獨聞，扪萝意遺我，折桂方思君。","sortOrder":112},
  {"id":"s_work_nvlt_29_113","chapterId":"ch_work_nvlt_29","text":"又別詩曰：孤煙起新丰，候雁出雲中，草低金城霧，木下玉門風，別君河初滿，思君月屢空，折桂衡山北，摘蘭沅水東，蘭摘心焉寄，桂折意誰通。","sortOrder":113},
  {"id":"s_work_nvlt_29_114","chapterId":"ch_work_nvlt_29","text":"梁江淹貽袁常侍詩曰：昔我別楚水，秋月麗秋天，今君客吳坂，春日媚春泉，幽冀生碧草，沅湘含翠煙，鑠鑠霞上景，懵懵雲外山，涉江竟何望，留滯空采莲。","sortOrder":114},
  {"id":"s_work_nvlt_29_115","chapterId":"ch_work_nvlt_29","text":"又臨秋怨別詩曰：四時煎日夜，玉露催紫榮，始懷未及叹，春意秋方驚，涼草散螢色，衰树斂蝉聲，承君客江潭，先愁鸿雁鳴，吳山饒離袂，楚水多別情，金碧堅不滅，桂華蘭有英，但見一葉落，衰恨方未平。","sortOrder":115},
  {"id":"s_work_nvlt_29_116","chapterId":"ch_work_nvlt_29","text":"又擬古雜體詩曰：遠與君別者，乃至雁門關，黃雲蔽千里，遊子何時還，送君如昨日，簷前露已团，不惜蕙草晚，所悲道里寒，君行在天涯，妾身長別離，原一見顏色，不異琼树枝，菟絲及水萍，所寄終不移。","sortOrder":116},
  {"id":"s_work_nvlt_29_117","chapterId":"ch_work_nvlt_29","text":"梁宗史［當作夬。］詩曰：別酒正參差，乖情將陆離，怅焉臨桂苑，愍默瞻華池，輕雲流惠采，時雨亂清漪，眇眇追蘭径，悠悠結芳枝，眷言終何讬，心寄方在斯。","sortOrder":117},
  {"id":"s_work_nvlt_29_118","chapterId":"ch_work_nvlt_29","text":"梁萧琛別詩曰：落日總行辔，薄別在江幹，遊客無淹期，長川有急澜，分手信雲易，相思誠獨難，之子兩特達，伊子日盤桓，俟我式微歲，共賞階前蘭。","sortOrder":118},
  {"id":"s_work_nvlt_29_119","chapterId":"ch_work_nvlt_29","text":"梁任昉詩曰：離燭有窮辉，別念無終緒，歧言未及申，離白已先舉，揆景衡無阿，臨風長楸渚，浮雲難嗣音，徘徊怅誰與，傥有關外驿，聊訪狎鷗鷺。","sortOrder":119},
  {"id":"s_work_nvlt_29_120","chapterId":"ch_work_nvlt_29","text":"梁丘遲侍宴樂遊苑餞徐州刺史應詔詩曰：詰旦阖闾开，馳道聞鳳吹，輕荑承玉輦，細草藉龍騎，風遲山尚响，雨息雲猶渍，巢空初鳥飛，荇亂新魚戲，寔惟北門重，匪親孰為寄，參差別念舉，肅穆恩波被，小臣信多幸，投生豈酬義。","sortOrder":120},
  {"id":"s_work_nvlt_29_121","chapterId":"ch_work_nvlt_29","text":"梁沈約侍宴謝朏宅餞東歸應詔詩曰：皇情怅東〈舟世〉，羽飾拂南躔，夏雲清朝景，秋風扬早蝉，飲和陪下席，論道光上筵。","sortOrder":121},
  {"id":"s_work_nvlt_29_122","chapterId":"ch_work_nvlt_29","text":"又侍宴樂遊苑餞徐州刺史應詔詩曰：沃若動龍驂，參差凝鳳管，金塘草未合，玉池泉將滿。","sortOrder":122},
  {"id":"s_work_nvlt_29_123","chapterId":"ch_work_nvlt_29","text":"又侍宴樂遊苑餞呂僧珍應詔詩曰：丹浦非樂戰，負重切君臨，我皇蘊至德，忘己用尧心，愍茲區宇內，魚鳥失飛沉，推轂二崤道，扬旆九河陰，超乘盡三屬，選士皆百金，戎主出細柳，餞席樽上林，命師誅後服，授律缓前禽，函轅方解帶，峣武稍披衿，伐罪芒山曲，弔民伊水潯，將陪告成禮，待此未抽簪。","sortOrder":123},
  {"id":"s_work_nvlt_29_124","chapterId":"ch_work_nvlt_29","text":"又別范安［《文選》二十安下有成字，此脱。］詩曰：平生少年日，分手易前期，及爾同衰暮，非复別離時，勿言一樽酒，明日難共持，夢中不識路，何以慰相思。","sortOrder":124},
  {"id":"s_work_nvlt_29_125","chapterId":"ch_work_nvlt_29","text":"又送友人別詩曰：君東我亦西，衔悲涕如霰，浮雲一南北，何由展言宴，方作異乡人，赠子同心扇，遙裔發海鸿，連翩出簷燕，春秋更去來，參差不相見。","sortOrder":125},
  {"id":"s_work_nvlt_29_126","chapterId":"ch_work_nvlt_29","text":"又別謝文學詩曰：漢池水如帶，巫山雲似蓋，一望沮漳水，寧思江海會，以我經寸心，從君千里外。","sortOrder":126},
  {"id":"s_work_nvlt_29_127","chapterId":"ch_work_nvlt_29","text":"梁王筠侍宴餞臨川王北伐應詔詩曰：金版韜英，玉牒蘊精，帝德乃武，王威有征，軒習弧矢，夏陳幹戚，周骛戎車，漢馳羽檄，我皇俊聖，千年鍾武，德洞十門，威加八柱，金正圮德，水行失道，胡馬南牧，戎徒西保，荐食伊瀍，整居沣鎬，金闕楊尘，銅台茂草，命彼膳［原訛胆，據冯校本改。］夫，爰詔协律，樂武出車，絃操別日，玉饌骈羅，琼漿泛溢，聖德溫溫，賓儀秩秩。","sortOrder":127},
  {"id":"s_work_nvlt_29_128","chapterId":"ch_work_nvlt_29","text":"梁萧子顯侍宴餞陆倕應令詩曰：储皇餞離送，廣命傳羽觴，侍遊追西水，閒宴等清漳，新泉已激浪，初卉始含芳，雨罢葉增绿，日斜树影長。","sortOrder":128},
  {"id":"s_work_nvlt_29_129","chapterId":"ch_work_nvlt_29","text":"梁劉孝綽侍宴餞庾於陵應詔詩曰：皇心眷將遠，怅餞靈芝侧，是日青春獻，林塘多秀色，芳卉疑纶組，嘉树以雕飾，遊絲缀湋領，光風送綺翼，下輦朝既盈，留宴景將昃，高辯競談瑞，奇文爭筆力，伊臣獨無伎，何由奉吹息。","sortOrder":129},
  {"id":"s_work_nvlt_29_130","chapterId":"ch_work_nvlt_29","text":"又侍宴餞張惠紹應詔詩曰：沧池誠自廣，蓬山一何峻，麗景花上鮮，油雲葉里润，風度餘芳滿，鳥集新條振，餞言班俊造，光私奖輶吝，徒然谬反隅，何以窥重仞。","sortOrder":130},
  {"id":"s_work_nvlt_29_131","chapterId":"ch_work_nvlt_29","text":"又應令詩曰：鮮雲積上月，冻雨晦初陽，回風飄淑氣，落景換新光，竹萌始防露，桂挺已含芳，瑤庭变杜若，玉沼發攒蒋，聖衿惜歧路，曲宴辟蘭堂。","sortOrder":131},
  {"id":"s_work_nvlt_29_132","chapterId":"ch_work_nvlt_29","text":"又江津寄劉之遴詩曰：與子如黃鵠，將別复徘徊，經過一柱觀，出入三休台，共摛雲氣藻，同舉霞文杯，流人每晓遊，禁門恒晚开，欲寄一言別，高駕何由來。","sortOrder":132},
  {"id":"s_work_nvlt_29_133","chapterId":"ch_work_nvlt_29","text":"又發建興渚示劉陆二黃門詩曰：扁舟去平樂，還顧極川梁，猶聞棗下吹，尚識杏間堂，洛桥分曲渚，官寺隱回塘，客行裁跬步，即事已多傷，况复千餘里，悲心未遽央。","sortOrder":133},
  {"id":"s_work_nvlt_29_134","chapterId":"ch_work_nvlt_29","text":"又侍離宴詩曰：軒轅東北望，江漢西南永，羽旗映日移，鐃吹臨風警，令王愍追送，纜舟餞俄頃，掩袂望征雲，衔杯惜餘景，首燕徒有心，局步何由騁，梁吳筠送呂外兵詩曰：白雲浮海际，明月落河濱，送君長叹息，徒使淚霑巾。","sortOrder":134},
  {"id":"s_work_nvlt_29_135","chapterId":"ch_work_nvlt_29","text":"又別夏侯故章詩曰：白馬黃金羁，青驪紫絲控，新知關山別，故人河梁送，置此一函書，為餘達雲夢。","sortOrder":135},
  {"id":"s_work_nvlt_29_136","chapterId":"ch_work_nvlt_29","text":"又酬別詩曰：故人杯酒別，天清明月亮，露下寒葭中，風起秋江上，衣染潺湲泣，棹犯參差浪，匕首直千金，七寶雕華状，生離何用表，賴此持相餉。","sortOrder":136},
  {"id":"s_work_nvlt_29_137","chapterId":"ch_work_nvlt_29","text":"又別王謙詩曰：嚴光不遂世，流轉任飛蓬，欲還天台嶺，不狎甘泉宮，離歌玉絃絕，別酒金卮空，傥遺故人念，仆在東山東。","sortOrder":137},
  {"id":"s_work_nvlt_29_138","chapterId":"ch_work_nvlt_29","text":"又赠搖郎詩曰：星漢正參差，佳人不在斯，宿昔暫乖阻，何異遠分離，露染蘼芜葉，月照芄蘭枝，風光已飄薄，雲采复逶迤，勞夢無人覺，默默心自知。","sortOrder":138},
  {"id":"s_work_nvlt_29_139","chapterId":"ch_work_nvlt_29","text":"又赠別詩曰：客子惨無歡，送別江之幹，白雲方眇眇，黃鳥尚關關，糾紛巫山石，合沓洞庭澜，行衣侵晓露，征舠犯夜湍，無因停合浦，見此去珠還。","sortOrder":139},
  {"id":"s_work_nvlt_29_140","chapterId":"ch_work_nvlt_29","text":"又赠別詩曰：树响浃山來，猿聲繞岫急，旅帆風飄扬，行巾露霑濕，深浪闇蒹葭，浓雲没城邑，不見別離人，獨有相思泣。","sortOrder":140},
  {"id":"s_work_nvlt_29_141","chapterId":"ch_work_nvlt_29","text":"又赠別詩曰：君留朱門里，我至廣江濆，城高望猶見，風多聽不聞，流蘋方繞繞，落葉尚紛紛，無由得共賞，山川間白雲。","sortOrder":141},
  {"id":"s_work_nvlt_29_142","chapterId":"ch_work_nvlt_29","text":"梁何遜與胡興安夜別詩曰：居人行轉軾，客子暫維舟，念此一筵笑，分為兩地愁，露濕寒塘草，月映清淮流，芳抱新離恨，獨守故園秋。又從镇江州與遊故別詩曰：歷稔共追遊，一旦辭群匹，复如東流水，未有西歸日，夜雨滴空階，晓燈暗雕室，相悲各罢酒，何時更促膝。","sortOrder":142},
  {"id":"s_work_nvlt_29_143","chapterId":"ch_work_nvlt_29","text":"梁庾肩吾侍宴餞湘東王詩曰：陳主從遊士，高宴入承華，併載同連璧，雕文類簡沙，落猿時動树，墜雪暫搖花，念此離筵促，方愁別路賒。","sortOrder":143},
  {"id":"s_work_nvlt_29_144","chapterId":"ch_work_nvlt_29","text":"又侍宴餞湘州刺史張續詩曰：洞庭資善政，層城送遠離，九歌扬妙曲，八桂動芳枝，雨足飛春殿，雲峰入夏池，郢路方遼遠，湘山轉蔽虧，何當好風日，極望長沙垂。","sortOrder":144},
  {"id":"s_work_nvlt_29_145","chapterId":"ch_work_nvlt_29","text":"又餞張孝總應令詩曰：層台臨回涨，耿耿青煙上，欲送分符人，翻似河隄望，寒雲暗積水，秋雨蒙重嶂，別念動神衿，華文切離貺，慚無寡和曲，空陪郢中唱。","sortOrder":145},
  {"id":"s_work_nvlt_29_146","chapterId":"ch_work_nvlt_29","text":"又應令詩曰：江上早寒生，萧條鐃管清，別筵开帳殿，離舟卷幔城，前山黃葉起，對岸白沙驚，臨渦同極望，竊吹愧才輕。","sortOrder":146},
  {"id":"s_work_nvlt_29_147","chapterId":"ch_work_nvlt_29","text":"又侍宴餞東陽太守范子雲詩曰：東部資良守，北宮敦獻酬，新枝漸接树，故冻欲含流，早花少餘雪，春寒極晚秋，徒嗟白岸遠，空想赤松遊。","sortOrder":147},
  {"id":"s_work_nvlt_29_148","chapterId":"ch_work_nvlt_29","text":"又新林送劉之遴詩曰：旆轉黃山路，舟纜白馬津，送輪時合幰，分驂各背尘，常山喜臨代，隴頭悲望秦，欲持漢中策，還以赠征人。","sortOrder":148},
  {"id":"s_work_nvlt_29_149","chapterId":"ch_work_nvlt_29","text":"梁朱超道別席中兵詩曰：數年共遊息，一旦各聯翩，莫論行近遠，終是隔山川，長波漫不極，高岫鬱相連，急風亂還鳥，輕寒靜暮蝉，扁舟已入浪，孤帆漸逼天，停車對空渚，長望轉依然。","sortOrder":149},
  {"id":"s_work_nvlt_29_150","chapterId":"ch_work_nvlt_29","text":"梁劉顯發新林浦赠同省詩曰：回首望歸途，山川邈離異，落日懸秋浦，歸鳥飛相次，感物傷我情，惆怅懷親懿。","sortOrder":150},
  {"id":"s_work_nvlt_29_151","chapterId":"ch_work_nvlt_29","text":"梁劉孺侍宴餞新安太守萧幾應令詩曰：芝殿近薄景，畫室寫油雲，玄覽多該洽，聖思究前聞，微密探精義，優遊妙典墳，飲餞參多士，言赠賦新文。","sortOrder":151},
  {"id":"s_work_nvlt_29_152","chapterId":"ch_work_nvlt_29","text":"梁王僧孺送殷何兩記室詩曰：掩袖出南浦，驅車送上征，飄飄晓雲駚，瀁々旦潮平，不肖餘何惜，無赀是勿輕，傥有還書便，一言訪死生。","sortOrder":152},
  {"id":"s_work_nvlt_29_153","chapterId":"ch_work_nvlt_29","text":"梁張缵侍宴餞東陽太守萧子雲詩曰：仲月發初陽，輕寒帶春序，渌池解餘冻，丹霞霁新雨，良守謁承明，徂舟戒蘭渚，皇储惜將邁，金樽留宴醑。","sortOrder":153},
  {"id":"s_work_nvlt_29_154","chapterId":"ch_work_nvlt_29","text":"周王裒入關故人送別詩曰：百年餘古树，千里闇黃尘，關山行就近，相看成遠人。","sortOrder":154},
  {"id":"s_work_nvlt_29_155","chapterId":"ch_work_nvlt_29","text":"又別裴儀同詩曰：河桥望行旅，長亭送故人，沙飛似軍幕，蓬卷若車輪，邊衣苦霜雪，愁貌損風尘，行路皆兄弟，千里念相親。","sortOrder":155},
  {"id":"s_work_nvlt_29_156","chapterId":"ch_work_nvlt_29","text":"又別陆才子詩曰：解纜出南浦，征棹且凌晨，還看分手處，唯餘送別人，中流搖蓋影，邊江落騎尘，平湖开曙日，細柳發新春，沧波不可望，行雲聊共因。","sortOrder":156},
  {"id":"s_work_nvlt_29_157","chapterId":"ch_work_nvlt_29","text":"又別王都官詩曰：連翩悯流水，凄怆惜離群，東西御溝水，南北會稽雲，河桥兩隄絕，橫歧數路分，山川遙不見，懷袖遠相聞。","sortOrder":157},
  {"id":"s_work_nvlt_29_158","chapterId":"ch_work_nvlt_29","text":"周庾信應令詩曰：望別非新馆，开舟即舊湾，浦喧征棹發，亭空送客還，路尘猶向水，征帆獨背關。","sortOrder":158},
  {"id":"s_work_nvlt_29_159","chapterId":"ch_work_nvlt_29","text":"又和保法師詩曰：秦關望楚路，灞岸想江潭，幾人應落淚，看君馬向南。","sortOrder":159},
  {"id":"s_work_nvlt_29_160","chapterId":"ch_work_nvlt_29","text":"又和侃法師詩曰：客遊經歲月，羁旅故情多，近待衡陽雁，秋分俱度河。","sortOrder":160},
  {"id":"s_work_nvlt_29_161","chapterId":"ch_work_nvlt_29","text":"又和侃法師詩曰：回首河隄望，眷眷嗟離絕，誰言舊國人，到在他乡別。","sortOrder":161},
  {"id":"s_work_nvlt_29_162","chapterId":"ch_work_nvlt_29","text":"又寄王琳詩曰玉關道路遠，金陵信使疏，獨下千行淚，开君萬里書。","sortOrder":162},
  {"id":"s_work_nvlt_29_163","chapterId":"ch_work_nvlt_29","text":"又別周弘正［原訛王，據本集改正，此訛。］詩曰：扶風石桥北，函穀故關前，此中一分手，相逢知幾年，黃鵠一反顧，徘徊恋怆然，自知悲不已，徒勞减瑟絃。","sortOrder":163},
  {"id":"s_work_nvlt_29_164","chapterId":"ch_work_nvlt_29","text":"陳周弘正隴頭送征客詩曰：朝霜侵漠草，流沙度隴飛，一聞流水曲，行住兩霑衣。","sortOrder":164},
  {"id":"s_work_nvlt_29_165","chapterId":"ch_work_nvlt_29","text":"又答林法師詩曰：客行七十歲，歲暮遠徂征，寒雲結不解，隴水冻無聲，君看日近遠，為忖長安城。","sortOrder":165},
  {"id":"s_work_nvlt_29_166","chapterId":"ch_work_nvlt_29","text":"陳徐陵新亭送別應令詩曰：鳳吹臨伊水，時駕出河梁，野燎村田黑，江秋岸荻黃，隔城聞上鼓，回洲隱去樯，神襟愛遠別，流睇極清漳。","sortOrder":166},
  {"id":"s_work_nvlt_29_167","chapterId":"ch_work_nvlt_29","text":"又別毛永嘉詩曰：原子厲清規，歸來振羽儀，嗟餘今老病，此別恐長離，白馬君來哭，黃泉我詎知，徒勞脱寶劍，空掛隴頭枝。","sortOrder":167},
  {"id":"s_work_nvlt_29_168","chapterId":"ch_work_nvlt_29","text":"陳張正見征虜亭送新安王應令詩曰：鳳吹臨南浦，神駕餞東平，亭回漳水乘，旆轉洛濱笙，地冻班輪响，風嚴羽蓋輕，燒田雲色暗，古树雪花明，歧路一回首，流襟動眷情。","sortOrder":168},
  {"id":"s_work_nvlt_29_169","chapterId":"ch_work_nvlt_29","text":"又秋日別庾正員詩曰：征途愁轉旆，連騎惨停鑣，朔氣凌疏木，江風送上潮。青雀離帆遠，朱鳶別路遙，唯有當秋月，夜夜上河桥。","sortOrder":169},
  {"id":"s_work_nvlt_29_170","chapterId":"ch_work_nvlt_29","text":"陳陰铿送始興王詩曰：良守別承明，枉道暫逢迎，去帆收錦纟乍，歸騎指蘭城，紛糾連山暗，潺湲泒水清，桂晚花方白，莲秋葉始輕，背飛傷客念，臨岐悯聖情，分風不得遠，何由送上征。","sortOrder":170},
  {"id":"s_work_nvlt_29_171","chapterId":"ch_work_nvlt_29","text":"又江津送劉光祿不及詩曰：依然臨送渚，長望倚河津，鼓聲隨聽絕，帆势與雲鄰，泊處空餘鳥，離亭已散人，林寒正下葉，鉤晚欲收纶，如何相背遠，江漢與城闉。","sortOrder":171},
  {"id":"s_work_nvlt_29_172","chapterId":"ch_work_nvlt_29","text":"又廣陵岸送北使詩曰：行人引去節，送客舣歸舻，即是觀涛處，仍為郊赠衢，汀洲浪已息，邦江路不紆，亭嘶背櫪馬，樯轉向風乌，海上春雲雜，天际晚帆孤，離舟對零雨，別渚望飛凫，定知能下淚，非但一楊朱。","sortOrder":172},
  {"id":"s_work_nvlt_29_173","chapterId":"ch_work_nvlt_29","text":"隋江總赠洗馬袁朗別詩曰：贾誼登朝日，終軍對奏年，校文升廣內，撫劍入崇賢，奇才殊艳逸，將別愛留聯，驅車命鐃管，拱坐面林泉，池寒稍下雁，木落久無蝉，霧侵山上月，霜开石路煙，高談無與慰，遲爾報華篇。","sortOrder":173},
  {"id":"s_work_nvlt_29_174","chapterId":"ch_work_nvlt_29","text":"又別袁昌州詩曰：河梁望隴頭，分手路悠悠，徂年驚若電，別日欲成秋，黃鵠飛飛遠，青山去去愁，不言雲雨散，更似東西流。","sortOrder":174},
  {"id":"s_work_nvlt_29_175","chapterId":"ch_work_nvlt_29","text":"又賦得携手上河梁應詔詩曰：早秋天氣涼，分手關山長，雲愁數處黑，木落幾枝黃，鳥歸猶識路，流去不知乡，秦川心斷絕，何悟是河梁。","sortOrder":175},
  {"id":"s_work_nvlt_29_176","chapterId":"ch_work_nvlt_29","text":"又別袁昌州詩曰：客子叹途窮，此別異西東，關山嗟墜葉，岐路悯征蓬，別鶴聲聲遠，愁雲處處同。","sortOrder":176},
  {"id":"s_work_nvlt_29_177","chapterId":"ch_work_nvlt_29","text":"又別賓化侯詩曰：分歧泣世道，念別傷邊秋，斷山時結霧，平海若無流，驚鷺一群起，哀猿數處愁，是日送歸客，為情自可求。","sortOrder":177},
  {"id":"s_work_nvlt_29_178","chapterId":"ch_work_nvlt_29","text":"又別永新侯詩曰：送君張掖郡，分悲函穀關，欲知腸斷絕，浮雲去不還。","sortOrder":178},
  {"id":"s_work_nvlt_29_179","chapterId":"ch_work_nvlt_29","text":"《藝文類聚》　唐·欧陽詢","sortOrder":179},
  {"id":"s_work_nvlt_30_1","chapterId":"ch_work_nvlt_30","text":"卷三十人部十四","sortOrder":1},
  {"id":"s_work_nvlt_30_2","chapterId":"ch_work_nvlt_30","text":"○別下怨","sortOrder":2},
  {"id":"s_work_nvlt_30_3","chapterId":"ch_work_nvlt_30","text":"◇別下","sortOrder":3},
  {"id":"s_work_nvlt_30_4","chapterId":"ch_work_nvlt_30","text":"【賦】魏文帝離居賦曰：惟離居之可悲，敦獨處於空床，愁耿耿而不寐，歷冬夜之悠長，驚風厲於閨闼，忽增激於中房，動帷裳之晻暧，彼明燭之無光。","sortOrder":4},
  {"id":"s_work_nvlt_30_5","chapterId":"ch_work_nvlt_30","text":"又感離賦曰：建安十六年，上西征，餘居守，老母諸弟皆從，不勝思慕，乃作賦曰：秋風動兮天氣涼，居常不快兮中心傷，出北園兮彷徨，望眾慕兮成行，柯條憯兮無色，绿草变兮萎黃，感微霜兮零落，隨風雨兮飛扬，日薄暮兮無悰，思不衰兮愈多，招延佇兮良久，忽踟蹰兮忘家。","sortOrder":5},
  {"id":"s_work_nvlt_30_6","chapterId":"ch_work_nvlt_30","text":"又永思賦曰：仰北辰而永思，溯悲風以增傷，哀遐路之漫漫，痛長河之無梁，原讬乘於浮雲，嗟逝速之難當。","sortOrder":6},
  {"id":"s_work_nvlt_30_7","chapterId":"ch_work_nvlt_30","text":"又出婦賦曰：思在昔之恩好，似比翼之相親，惟方今之疏絕，若驚風之吹尘，夫色衰而愛絕，信古今其有之，傷茕獨之無恃，恨胤嗣之不滋，甘没身而同穴，終百年之長期，信無子而應出，自典禮之常度，悲穀風之不答，怨昔人之忽故，被入門之初服，出登車而就路，遵長涂而南邁，馬踌躇而回顧，野鳥翩而高飛，怆哀鳴而相慕，撫騑服而展節，即臨沂之舊城，踐麋鹿之曲蹊，聽百鳥之群鳴，情怅恨而顧望，心鬱結其不平。","sortOrder":7},
  {"id":"s_work_nvlt_30_8","chapterId":"ch_work_nvlt_30","text":"魏陳王曹植出婦賦曰：以才薄之质陋，奉君子之清尘，承顏色以接意，恐疏賤而不親，悅新昏而忘妾，哀愛惠之中零，遂摧頹而失望，退幽屏於下庭，痛一旦而見弃，心忉怛以悲驚，衣入門之初服，背床室而出征，攀仆御而登車，左右悲而失聲，嗟冤結而無訴，乃愁苦以長窮，恨無愆而見弃，悼君施之不終。","sortOrder":8},
  {"id":"s_work_nvlt_30_9","chapterId":"ch_work_nvlt_30","text":"又愍志賦曰：或人有好鄰人之女者，時無良媒，禮不成焉，彼女遂行適人，有言之於餘者，餘心感焉，乃作賦曰：竊讬音於往昔，迄來春之不從，思同遊而無路，情壅隔而靡通，哀莫哀於永絕，悲莫悲於生離，豈良時之難俟，痛餘质之日虧，登高樓以臨下，望所歡之攸居，去君子之清宇，歸小人之蓬庐，欲輕飛而從之，迫禮防之我拘。","sortOrder":9},
  {"id":"s_work_nvlt_30_10","chapterId":"ch_work_nvlt_30","text":"又歸思賦曰：背故乡而遷徂，將遙憩乎北濱，經平常之舊居，感荒坏而莫振，城邑寂以空虛，草木秽而荆榛，嗟乔木之無陰，處原野其何為，信樂土之足慕，忽併日而載馳。","sortOrder":10},
  {"id":"s_work_nvlt_30_11","chapterId":"ch_work_nvlt_30","text":"魏王粲出婦賦曰：既僥倖兮非望，逢君子兮弘仁，當隆暑兮翕赫，猶蒙眷兮見親，更盛衰兮成败，思弥固兮日新，竦餘身兮敬事，理中饋兮恪勤，君不篤兮終始，樂枯荑兮一時，心搖荡兮变易，忘舊姻兮弃之，馬已駕兮在門，身當去兮不疑，攬衣帶兮出戶，顧堂室兮長辭。","sortOrder":11},
  {"id":"s_work_nvlt_30_12","chapterId":"ch_work_nvlt_30","text":"晉陆機別賦曰：伊公子之可懷，悲永別之局期，悼同居之無樂，曾不逾乎一期，經春秋之寒暑，常戚戚而不怡，登九層而脩觀，超臨遠以相思。","sortOrder":12},
  {"id":"s_work_nvlt_30_13","chapterId":"ch_work_nvlt_30","text":"晉傅鹹感別賦曰：嘉天地之交泰，美萬物之會通，悅朋友之攸攝，慕管鮑之遐蹤，退以文而會友，钦公子之清尘，信同聲之相應，意未寫而情親，誓雅好之龆龀，分綢缪而日新，蘭蕙含芬，有時而馨，龍骥踠足，有時而征，乾道变化，時惟大明，瓘瓘睦友，載扬厥聲，降聖宰之旌招，曜羽儀之上京，贊唐虞之嘉運，超飛躍乎太清，佩銀璜於帝侧，拖紫艾於天庭，瞻宸極之眇眇，喜吾子之寵榮，無荆玉之夜觀，猥齊景於夜光，敢有觀於斯舉，欣與子而併翔，天啟其原，自忝蘋蘩，幼則同遊，長則同班，同心厥職，其臭如蘭，庶績未凝，聖朝畴咨，顯佐納言，光綜萬機，出順景而為偶，入阒然而無依，步空宇以低徊，想宴笑之餘暉，意躔綿而弥結，淚雨面而霑衣。","sortOrder":13},
  {"id":"s_work_nvlt_30_14","chapterId":"ch_work_nvlt_30","text":"梁江淹別賦曰：黯然銷魂者，唯別而已矣，况秦吳兮絕國，复燕宋兮千里，或春苔兮始生，乍秋風兮暫起，是以行子腸斷，百感凄惻，風萧萧而異响，雲漫漫兮奇色，舟凝滯於水濱，車逶遲於山侧，棹容與而記［《文選》十六作詎，此訛。］前，馬寒鳴而不息，掩金觴而誰御，橫玉柱而霑軾，居人愁臥，恍若有亡，日下壁而沉彩，月上軒而飛光，知離夢之踯躅，意離魂之飛扬，爾乃別雖一緒，事乃萬族，至若龍馬銀鞍，朱軒繡軸，帳飲東都，送客金穀，琴羽張兮箫鼓陳，燕趙歌兮傷美人，珠與玉兮艳暮秋，羅與綺兮娇上春，造分手而衔涕，感寂寞而傷神，乃有劍客慚恩，少年報士，韓國趙廁，吳宮燕市，驅征馬而不顧，見行尘之時起。又若君居淄右，妾家河陽，同琼珮之晨照，共金爐之夕香，君結綬兮千里，惜瑤草之徒芳，慚幽宮之琴瑟，悔台上之流黃，春闈閟此青苔色，秋帳涵茲明月光，夏簟清兮晝不暮，冬棋凝兮夜何長，織錦曲兮泣已盡，回紋詩兮影獨傷，是以別方不定，別理千名，有別必怨，有怨必盈，使人意奪神駭，心摧骨驚。","sortOrder":14},
  {"id":"s_work_nvlt_30_15","chapterId":"ch_work_nvlt_30","text":"又去故乡賦曰：日已暮兮，隱吳山之丘墟，北風折兮絳花落，流水嚴兮翠茎流，發桂枝而不是，怅浮雲之離居，乃陵大壑，越蒼川，茫茫積水，崚崚斷山，窮陰匝海，平芜帶天，於是泣故關之已虛，傷故國之無际，出汀洲而解冠，入溆浦而捐袂，芳洲之草行欲暮，桂水之波不可渡，絕世獨立兮，報君子之一顧，是時霜翦蕙兮風摧芷，平原晚兮黃霧起，重曰：江南之杜衡兮色已陳，原使黃鵠兮報佳人，橫羽觴而掩望，撫玉琴兮何親。","sortOrder":15},
  {"id":"s_work_nvlt_30_16","chapterId":"ch_work_nvlt_30","text":"梁劉孝儀叹別賦曰：在羁旅兮為思，每居常而不樂，意難偕於骀荡，情易邀於陨獲，愁非和而自來，忧试排而不却，退求己以自省，慨撫衿而太息，位不俟於一進，發徒彰於二色，名有似於務耕，學無均於譬織，在初歸之為慶，庶因拙而自收，保私庭之宴喜，共崑弟而嬉遊，校小文於搖筆，比揩式於臨流，止每歡於接膝，行如喜於同辀，忽一去而數千，遂離居而別域，阻同被於當寐，乖共餐於終食，唯凭遠望以代歸，負相思其無力。","sortOrder":16},
  {"id":"s_work_nvlt_30_17","chapterId":"ch_work_nvlt_30","text":"梁張缵離別賦曰：太常劉侯，前辈宿達，餘在紈綺之歲，固已钦其風矣，及理棹江幹，攬涕還望，采萧之詠，不覺成篇，彼劉侯之矯矯，承世德之清辉，挺荆衡之箘簵，辉江漢之珠璣，昔相知於一定，逾盛衰乎二紀，豈因媒以成親，非彈冠而來仕，分自諧於金石，情冥符乎蘭芷，忘時辈之後先，略相知之年齒，及胥遇於雲閣。又方駕而聯曹，宵擁衾而暗語，晝稅鞅以遊遨，案方前而等食，衣共體而同袍，猶合歡之蠲忿，如來蘇之釋勞，唯吾人之與子兮，谅不言其已召，在百代而奚殊，雖千年而同調，寧風波之所移，豈流俗之能要，非高唱而雲擬，逢下士而或笑，隔原言於信次，尚眷眷而興懷，矧雲崖之遠訣，抱離袖而長乖，顧龍門而掩涕，瞻郢路而何偕，在驚禽之屢感，迫徂年之長暮，眺湘沅之分流，遵洞庭之永路，山峻高而易隱，浦邅回而難溯，猿啾啾而夜吟，鵑骚骚而晓度，撫客子兮其何心，能辭乡兮別故，共抱荃蕙之遺芳，共［《初學記》十八作不。］離披於霜露。","sortOrder":17},
  {"id":"s_work_nvlt_30_18","chapterId":"ch_work_nvlt_30","text":"【書】漢李陵與蘇武書曰：子卿名聲冠於圖籍，分義光於二國，形影表於丹青，爵祿傳於王室，家獲無窮之寵，永明白於千載，夫行志志立，求仁得仁，雖遭困厄，死而後已，將何恨哉，陵前提步卒五千，深入匈奴右地三千餘里，雖身降名辱，下計其功，豈不足以免老母之命耶，嗟乎子卿，世事谬矣，功者福主，今為禍先，忠者義本，今為重患，是以彭蠡赴流，屈原沉身，子欲居九夷，此不由感怨之志耶，行矣子卿，恩若一體，分為二朝，悠悠永絕，何可為思，人殊俗異，死生斷絕，何由复達。","sortOrder":18},
  {"id":"s_work_nvlt_30_19","chapterId":"ch_work_nvlt_30","text":"漢蘇武報李陵書曰：曩以人乏，奉使方外，至使遐夷作逆，封豕造悖，銶狼出爪，摧辱王命，身幽於無人之處，跡戢於胡塞之地，歃朝露以為飲，茹田鼠以為糧，窮目極望，不見所識，侧耳遠聽，不聞人聲，當此之時，生不足甘，死不足惡，所以忍困強存，徒念忠義，雖誘仆以隆爵厚寵，萬金之利，不以滑其慮也，迫以白刃在頸，鈇锧在喉，不以動其心也，何則，志定於不回，期誓於没命，幸賴聖明，遠垂拯贖，得使入湯之禽，复假羽毛，刖斷之足，复蒙連續，每念足下，才為世英，器為時出，語曰：夜行被繡，不足為榮，况於家室孤滅，弃在絕域，衣則異製，食味不均，弃損功名，雖尚视息，與亡無異，向使君服節死難，書功竹帛，傳名千代，茅土之封，永在不朽，不亦休哉，嗟乎季卿，事已去矣，失之毫釐，差之千里，將复何言，所貺重遺，義當順承，本為一體，今為異俗，餘歸漢室，子留彼國，臣無境外之交，故不當受，乖離邈矣，相見未期，國別俗殊，死生隔絕，岱馬越鳥，能不依依，謹奉答報，併還所赠。","sortOrder":19},
  {"id":"s_work_nvlt_30_20","chapterId":"ch_work_nvlt_30","text":"李陵重報書曰：子卿足下，勤宣令德，策名清時，榮問休畅，幸甚幸甚，遠讬異國，昔人所悲，望風懷想，能不依依，自從初降，以至今日，身之困窮，獨坐愁苦，終日無睹，但見異類，韦韝毳幕，以御風雨，膻肉酪漿，以充飢渴，舉目言笑，誰與為歡，涼秋九月，塞外草衰，夜不能寐，侧耳遠聽，胡笳互動，牧馬悲鳴，吟嘯成群，聽之不覺淚下，與子別後，邊聲四起，晨坐益复無聊，身負國恩，為世所悲，子歸受榮，我留受辱，命也何如，身出禮義之乡，入無知之俗，每一念至，忽然忘生，陵不難刺心以自明，刎頸以見志，顧國家於我已矣，殺身無益，適足增羞，左右之人，見陵如此，為不入耳之歡，來相勸勉，異方之樂，秖令人悲，增忉怛爾，子卿视陵，豈偷生之士，而惜死之人哉，誠以虛死不如立節，滅名不如報德也，昔范蠡不殉會稽之恥，曹沫不死三败之辱，卒复句踐之讎，報魯國之羞，區區之心，竊慕此爾，足下又雲，漢於功臣不薄，子為漢臣，安得不雲爾乎，足下昔以单車之使，適萬乘之虜，丁年奉使，皓首而歸，老母終堂，生妻去室，此天下所希聞，古今所未有，聞子之歸，賜不過二百萬，位不過典屬國，子尚如此，陵复何望哉，且漢厚誅陵以不死，薄賞子以守節，欲使遠聽之臣，望風馳命，此實難矣，男兒生以不成名，死則葬蠻夷中，誰复能屈身稽顙，回向北闕，使刀筆之吏，弄其文墨耶，嗟乎子卿，夫复何言，相去萬里，人絕路殊，生為別世之人，死為異域之鬼，長與足下生死辭矣。","sortOrder":20},
  {"id":"s_work_nvlt_30_21","chapterId":"ch_work_nvlt_30","text":"後漢張奐與延篤書曰：唯別三年，無一日之忘，京師禁急，不敢相聞，豈不懷歸，畏此簡書，年老氣衰，智盡謀索，每有所處，违宜失便，北為兒車所讎，［按後漢書九十五張奐傳論雲，見欺竖子疑本句北當作比，車當作辈。］中為馬循所困，直欲入三泉之下，复镇之以大石，厄乎此時也，且太陰之地，冰厚三尺，木皮三寸，風寒惨冽，剝脱傷骨，但此自非老憊者所堪，而复加之以師旅，因之以飢饉，眾難聚集，不可一二言也，聋盲日甚，氣力寢衰，神耶當复相見者，［句有訛。］從此辭矣。","sortOrder":21},
  {"id":"s_work_nvlt_30_22","chapterId":"ch_work_nvlt_30","text":"後漢窦玄，形貌絕異，天子以公主妻之，舊妻與玄書別曰：弃妻斥女敬白窦生，卑賤鄙陋，不如貴人，妾日已遠，彼日已親，何所告訴，仰呼蒼天，悲哉窦生，衣不厭新，人不厭故，悲不可忍，怨不自去，彼獨何人，而居我處。","sortOrder":22},
  {"id":"s_work_nvlt_30_23","chapterId":"ch_work_nvlt_30","text":"晉趙景真與嵇茂《齊書》曰：昔李叟入秦，及關而叹，梁生適越，登嶽長謠，夫以嘉遯之舉，猶懷恋恨，况乎不得已者哉，惟別之後，離群獨逝，背榮宴，辭倫好，經迥路，造沙漠，鳴雞戒旦，則飄爾晨征，日薄西山，則馬首靡讬，或乃回飆狂厲，白日寢光，徙倚交错，陵隰相望，涉泽求蹊，披榛觅路，嘯詠溝渠，良不可度，斯亦行路之艱難，然非吾心之所懼也。又北土之性，難以讬根，投人夜光，鮮不案劍，今將植橘柚於玄朔，蒂華藕於脩陵，表龍章於裸壤，奏韶武於聋俗，固難以取貴矣，朝霞啟暉，則身疲於遄征，太陽戢曜，則情劬於夕惕，思躡雲梯，橫奋八極，披艱埽秽，荡海夷嶽，蹴崑崙使西倒，踏泰山令東覆，平涤九區，恢廓宇宙，斯亦吾心之鄙原也，時不我與，垂翼遠逝，鋒铓靡加，六翮摧屈，自非樂天知命，誰能不憤悒者哉，吾子植根芳苑，擢秀清流，榮曜眩其前，艳色餌其後，良儔交其左，聲名馳其右，翱翔倫党之間，弄姿房帷之里，從容顧眄，綽有餘裕，俯仰吟嘯，自以為得志矣，豈能與吾同大丈夫之忧樂哉，去矣嵇生，永離隔矣，茕茕飄寄，臨沙漠矣，悠悠三千，路難涉矣，執手之期，邈無日矣，思心弥結，誰雲釋矣，無金玉爾音，而有遐心，身雖胡越，意存斷金。","sortOrder":23},
  {"id":"s_work_nvlt_30_24","chapterId":"ch_work_nvlt_30","text":"晉嵇茂齊答趙景真書曰：登山遠望，睹〈山孝〉〈山郭〉以成憤，策杖廣泽，瞻長波以增悲，遊眄春圃，情有秋林之悴，濯足夏流，心懷冬冰之惨，對榮宴而不樂，臨清觴而無歡，今足下琬琰之朴未剖，而求光時之价，騏骥之足未摅，而希絕景之功，心銳而動淺，望速而應遲，故有企佇之懷爾，夫處靜不悶，古人所貴，窮而不濫，君子之美，故顏生居陋，不改其樂，孔父困陳，絃歌不废，幸吾子思弘遠理，舍道自榮，將與足下交伯成於窮野，結箕山乎蓬屋，侣范生於海濱，儔黃綺於商嶽，凭輕雲以絕馳，遊曠荡以自足，雖不齊足下之所樂，亦吾心之所原也。","sortOrder":24},
  {"id":"s_work_nvlt_30_25","chapterId":"ch_work_nvlt_30","text":"梁簡文帝與劉孝綽書曰：執別灞泄，嗣音阻闊，合璧不停，旋灰屢徙，玉霜夜下，旅雁晨飛，想涼燠得宜，時候無爽，既官寺務煩，簿領殷凑，等張釋之條理，同於公之明察，雕龍之才本傳，靈蛇之譽自高，頗得暇逸於篇章，從容於文諷，頃擁旄西邁，載離寒暑，晓河未落，拂桂棹而先征，夕鳥歸林，懸孤帆而未息，足使邊心憤薄，乡思邅回，但離闊已久，載勞寤寐，佇聞還驿，以慰相思。","sortOrder":25},
  {"id":"s_work_nvlt_30_26","chapterId":"ch_work_nvlt_30","text":"又與萧臨川書曰：零雨送秋，輕寒迎節，江楓晓落，林葉初黃，登舟已積，殊足勞止，解維金關，定在何日，八區內侍，厭直御史之庐，九棘外府，且息官曹之務，應分竹南川，剖符千里，但黑水初旋，未申十千之飲，桂宮既啟，复乖双闕之宴，文雅縱橫，即事分阻，清夜西園，眇然未剋，想征舻而結叹，望桂席而霑衿，若使弘農書疏，脱還鄴下，河南口占，傥歸乡里，必遲青泥之封，且覯朱明之詩，白雲在天，蒼波無極，瞻之岐路，眷慨良深，愛護波潮，敬勖光彩。","sortOrder":26},
  {"id":"s_work_nvlt_30_27","chapterId":"ch_work_nvlt_30","text":"梁元帝與萧挹書曰：闊別清顏，忽焉已久，未复音息，勞望情深，暑氣方隆，恒保清善，握蘭雲閣，解绂龍樓，允膺妙選，良為幸甚，想同僚多士，方駕連曹，雅步南宮，容與自玩，士衡已後，唯在茲日，惟崑與季，文藻相暉，二陆三張，豈獨擅美，比暇日無事，時复含毫，頗有賦詩，別當相簡，但衡巫峻極，漢水悠長，何時把袂，共披心腹。","sortOrder":27},
  {"id":"s_work_nvlt_30_28","chapterId":"ch_work_nvlt_30","text":"梁劉孝標答郭峙書曰：聞君子舊矣，但人非豕鹿，轉加蓬逝，波駭雨散，動間山川，故無由交羽觴，荐雜佩，睨浮雲以搔首，臨清風而浩歌，变燧回星，亦雲勞止。","sortOrder":28},
  {"id":"s_work_nvlt_30_29","chapterId":"ch_work_nvlt_30","text":"周王裒與周弘讓書曰：嗣宗窮途，楊朱岐路，征蓬長逝，流水不歸，南北殊方，炎涼異節，木皮春厚，桂树冬榮，攝衛惟宜，動靜多豫，賢兄入關，敬承闊曲，猶依杜陵之水，尚保東陂之田，铲跡幽蹊，銷聲穹穀，何其愉樂，幸甚幸甚，弟昔因多疾，亟覽九仙之方，晚涉世途，猶懷五嶽之舉，頃年事遒盡，容發衰謝，芸其黃矣，零落無時，還念生涯，繁忧總集，親［周書四十一王裒傳作视。］陰愒日，類趙孟之徂年，負杖行吟，同劉琨之積惨，河陽北遊，空思巩洛，灞陵南望，唯見長安，所貴書生之魂，還依舊里，射聲之鬼，無恨他乡，浮雲在天，邈無由矣，會見之期，長無日矣，援筆攬紙，龍鍾橫集。","sortOrder":29},
  {"id":"s_work_nvlt_30_30","chapterId":"ch_work_nvlt_30","text":"陳周弘讓答王裒書曰：甚矣悲哉，此之為別也，雲飛泥沉，金鑠蘭滅，玉音不嗣，瑤華莫因，家兄至自鎬京，致來書於穹穀，故人之跡，有如對面，开題申紙，流脸霑膝，與弟分袂西陝，言反東區，雖保周陂，還依蒋径，三荆離坼，二仲不歸，麋鹿為曹，更多悲緒，丹經在握，貧病莫諧，芝術可求，聊因采掇，昔吾壮日，及弟富年，俱值邕熙，併歡衡泌，南風雅操，清觴妙曲，絃琴促坐，無乏夕晨，玉瀝金華，冀獲難老，不虞一旦，翻覆波澜，吾已愒陰，弟非茂齒，禽尚之契，各在天涯，永念生平，難為胸臆，正當视陰數箭，排愁破涕，人生樂爾，忧戚何為，原愛玉體，珍金相，保期颐，享考黃發，猶冀蒼雁赪鯉，時傳尺素，清風朗月，但寄相思，搦管操觚，聲淚俱咽。","sortOrder":30},
  {"id":"s_work_nvlt_30_31","chapterId":"ch_work_nvlt_30","text":"陳徐陵答尹義《尚書》曰：別離二國，雲雨十年，心想河陽，言銅爵而無遠，神遊漳水，與金鳳而俱飛，弟留連河北，義等周南，懷此殊才，實可傷叹，吾崦嵫既暮，容鬢凋然，風氣弥留，砭藥無損，追惟畴昔，共備行人，家國安危，賓禮升降，懸壶代哭，俱歷春冬，移管於箕，同茲辛苦，鳴蜩抱树，亟見藏冰，歸雁衔芦，多歷寒食，靖言念此，如何可忘，夫以擁肿之木，得免困［文苑英華六百八十五作因。］於不才，觳觫之牛，自保由於無用，嗟餘鄙陋，未有龚生，唯叹吾賢，不同蘧瑗爾，夫推溝拯溺，無切皇衷，逸翮飄鱗，見優機覽，所以降尺一之書，馳輶軒之使，心期與國，必遂還途，寧謂親鄰，更成難請，伊昔梁朝，共奉嘉聘，張茲大帛，處彼高閎，庭奏歌鍾，座延娇眄，賓客之叙，方於階阼，田獵之禽，同於君膳，正以乡關阻亂，致爾拘留，家國隆平，義應旋反，韓宣屢至，宰孔頻還，翻爾遲回，豈雲鄰睦。","sortOrder":31},
  {"id":"s_work_nvlt_30_33","chapterId":"ch_work_nvlt_30","text":"《春秋潛潭巴》曰：河水逆流，怨氣盛也。","sortOrder":33},
  {"id":"s_work_nvlt_30_34","chapterId":"ch_work_nvlt_30","text":"《毛詩序》曰：亂世之音怨以怒，其政乖。","sortOrder":34},
  {"id":"s_work_nvlt_30_35","chapterId":"ch_work_nvlt_30","text":"又曰：角弓，父兄刺幽王也，不親九族而好讒佞，骨肉相怨，故作是詩也，骍骍角弓，翩其反矣，兄弟婚姻，無胥遠矣。","sortOrder":35},
  {"id":"s_work_nvlt_30_36","chapterId":"ch_work_nvlt_30","text":"《左傳》曰：晉侯賞從亡者，介之推不言祿，祿亦弗及，其母曰：盍亦求之，以死誰{封心}，對曰：尤而效之，罪又甚焉，且出怨言，不食其食。","sortOrder":36},
  {"id":"s_work_nvlt_30_37","chapterId":"ch_work_nvlt_30","text":"又曰：晉郄至獻楚捷於周，與单襄公語，骤稱其伐，单子語諸大夫曰：溫季其亡乎，位於七人之下，而求掩其上，怨之聚，亂之本也，多怨而階亂，何以在位，夏書曰：怨豈在明，不見是圖，將慎其細也，今而明之，其可乎。","sortOrder":37},
  {"id":"s_work_nvlt_30_38","chapterId":"ch_work_nvlt_30","text":"又曰：吳公子札來聘，請觀於周樂，為之歌周南召南，曰：美哉，始基之矣，猶未也，然勤而不怨矣，為之歌小雅，曰：美哉，思而不貳，怨而不言，其周德之盛乎。","sortOrder":38},
  {"id":"s_work_nvlt_30_39","chapterId":"ch_work_nvlt_30","text":"又曰：子產雲，我聞忠善以損怨，不聞作威以防怨。","sortOrder":39},
  {"id":"s_work_nvlt_30_40","chapterId":"ch_work_nvlt_30","text":"又曰：君子之言，信而有徵，故怨遠於身，小人之言，僣而無徵，故怨咎及之。","sortOrder":40},
  {"id":"s_work_nvlt_30_41","chapterId":"ch_work_nvlt_30","text":"《論語》曰：放於利而行多怨。","sortOrder":41},
  {"id":"s_work_nvlt_30_42","chapterId":"ch_work_nvlt_30","text":"又曰：貧而無怨難，富而無驕易。","sortOrder":42},
  {"id":"s_work_nvlt_30_43","chapterId":"ch_work_nvlt_30","text":"《管子》曰：凡禍亂之所生，生於怨咎，怨咎之所生，在於非理，故曰閒禍在除怨。","sortOrder":43},
  {"id":"s_work_nvlt_30_44","chapterId":"ch_work_nvlt_30","text":"《楚辭》曰：怨靈修［原作循，據冯校本改。］之浩荡，終不察夫民心。","sortOrder":44},
  {"id":"s_work_nvlt_30_45","chapterId":"ch_work_nvlt_30","text":"《淮南子》曰：和氏之璧，夏後之璜，揖讓而進之以合歡，夜以投人則為怨，時與不時也。","sortOrder":45},
  {"id":"s_work_nvlt_30_46","chapterId":"ch_work_nvlt_30","text":"《琴操》曰：王昭君者，齊國人也，顏色皎絜，聞於國中，獻於孝元帝，訖不幸納，積五六年，昭君心有怨曠，伪不飾其形容，元帝每歷後宮，疏略不過其處，後单於遣使者朝贺，元帝陳設倡樂，乃令後宮妆出，昭君怨恚日久，乃便循飾，善妆盛服，光暉而出，俱列坐，元帝謂使者曰：单於何所原樂，對曰：珍奇怪物，皆悉自備，唯婦人丑陋，不如中國，乃令後宮欲至单於者起，昭君喟然越席而前曰：妾幸得備在後宮，粗丑卑陋，不合陛下之心，誠原得行，帝大驚悔之，良久太息曰：朕已誤矣，遂以與之，昭君至单於，心思不樂，乃作怨曠思惟歌曰：秋木萋萋，其葉萎黃，有鳥處山，集於苞桑，養育毛羽，形容生光，既得升雲，遊倚曲房，離宮絕曠，身體摧藏，志念抑冗，不得頡颃，雖得餧食，心有徊徨，我獨伊何，改往变常，翩翩之燕，遠集西羌，高山瓘瓘，河水泱泱，父兮母兮，道里悠長，呜呼哀哉，忧心惻傷。","sortOrder":46},
  {"id":"s_work_nvlt_30_47","chapterId":"ch_work_nvlt_30","text":"《續漢書》曰：建武三十年三月，群臣上言，即位三十年，宜封禪泰山，詔書曰：百姓怨氣滿腹，吾誰欺，欺天乎，曾謂泰山不如林放乎。","sortOrder":47},
  {"id":"s_work_nvlt_30_48","chapterId":"ch_work_nvlt_30","text":"【詩】魏阮瑀詩曰：民生受天命，漂若河中尘，雖稱百齡寿，孰能應此身，猶獲婴凶禍，流離恒苦辛。","sortOrder":48},
  {"id":"s_work_nvlt_30_49","chapterId":"ch_work_nvlt_30","text":"宋鮑昭行路難曰：君不見河邊草，冬時枯死春滿道，君不見城上日，今暝没西山，明朝复更出，今我何時得自然，一滅永罢歸黃泉，人生苦多歡樂少，意氣敷腴在盛年，且原得志數相就，床頭恒有沽酒錢，功名竹帛非我事，存亡貴賤委皇天。","sortOrder":49},
  {"id":"s_work_nvlt_30_50","chapterId":"ch_work_nvlt_30","text":"又曰：寫水置平地，各自東西南北流，民生亦有命，安能行叹复坐愁，酌酒小自宽，舉杯斷絕歌行路難，心非木石豈無感，吞聲踯躅不敢言。","sortOrder":50},
  {"id":"s_work_nvlt_30_51","chapterId":"ch_work_nvlt_30","text":"齊謝朓玉階怨詩曰：夕殿下珠帘，流螢飛复息，長夜縫羅衣，思君此何極。","sortOrder":51},
  {"id":"s_work_nvlt_30_52","chapterId":"ch_work_nvlt_30","text":"梁元帝送西歸內人詩曰：秋氣蒼茫結孟津，复送巫山荐枕神，昔時慊慊愁應去，今日勞勞長別人。","sortOrder":52},
  {"id":"s_work_nvlt_30_53","chapterId":"ch_work_nvlt_30","text":"梁豫章王萧綜聽鐘鳴詩曰：歷歷聽鐘鳴，當知在帝城，西树隱落月，東窗見晓星，霧露朏朏未分明，鳥啼哑哑已流聲，驚客思，動客情，客思鬱從橫，翩翩孤雁何所栖，依依別鶴半夜鳴，今歲行已暮，雨雪向凄凄，飛蓬旦夕起，楊柳尚翻低，氣鬱結，涕滂沱，愁思無所讬，強作聽鍾歌。","sortOrder":53},
  {"id":"s_work_nvlt_30_54","chapterId":"ch_work_nvlt_30","text":"梁范雲登城怨詩曰：楚妃歌脩竹，漢女奏幽蘭，獨以閨中笑，豈知城上寒。","sortOrder":54},
  {"id":"s_work_nvlt_30_55","chapterId":"ch_work_nvlt_30","text":"梁劉孝綽班婕妤怨詩曰：應門寂已閉，非复後庭時，况在青春日，萋萋绿草滋，妾身似秋扇，君恩絕履綦，詎憶遊輕輦，從今賤妾辭。","sortOrder":55},
  {"id":"s_work_nvlt_30_56","chapterId":"ch_work_nvlt_30","text":"梁吳筠行路難曰：洞庭水上一株桐，經霜觸浪困嚴風，昔時抽心曜白日，今旦怨死黃沙中，洛陽名工見咨嗟，一嗟一剋作琵琶，白璧規心學明月，珊瑚暎面作風花，帝王見賞不見忘，提携把握登建章，掩抑摧藏張女彈，殷勤促柱楚明光，年年月月對君子，遙遙夜夜宿未央，未央婇女弃鳴篪，爭見拂拭生光儀，茱萸錦衣玉作匣，安念昔日枯树枝，不學衡山南嶺桂，至今千載猶未知。","sortOrder":56},
  {"id":"s_work_nvlt_30_57","chapterId":"ch_work_nvlt_30","text":"又曰：青璅門外安石榴，連枝接葉夹御溝，金墉城西合歡树，垂條照采拂鳳樓，遊俠少年遊上路，傾心顛倒想恋慕，摩顶至足買片言，开胸瀝胆取一顧，自言家在趙邯鄲，翩翩舌杪复劍端，青驪白駮的盧馬，金羁绿控紫絲鞶，躞蹀橫行不肯進，夜夜汗血至長安，長安城中諸貴臣，爭貴儒者席上珍，复聞梁王好學問，輕弃劍客如埃尘，吾丘寿王始得意，司馬相如適被申，大才大辯尚如此，何况我辈輕薄人。","sortOrder":57},
  {"id":"s_work_nvlt_30_58","chapterId":"ch_work_nvlt_30","text":"又曰：君不見西陵田，從橫十字成陌阡，君不見東郊道，荒涼芜没起寒煙，盡是昔日帝王處，歌姬舞女達天曙，今日翩妍少年子，不知華盛落前去，吐心吐意許他人，今旦回惑生猶豫，山中桂树自有枝，心中方寸自相知，何言歲月忽若馳，君之情意與我離，還君玳瑁金雀釵，不忍見此便心危。","sortOrder":58},
  {"id":"s_work_nvlt_30_59","chapterId":"ch_work_nvlt_30","text":"又曰：君不見長安客舍門，娼家少女名桃根，貧窮夜紡無燈燭，何言一朝奉至尊，至尊離宮百餘處，千門萬戶不知曙，唯聞哑哑城上乌，玉蘭金井牵轆轳，丹梁翠柱飛流蘇，香薪桂火炊彫菰，當年翻覆無常定，薄命為女必已粗。","sortOrder":59},
  {"id":"s_work_nvlt_30_60","chapterId":"ch_work_nvlt_30","text":"梁孔翁歸班婕妤怨詩曰：長門與長信，日暮九重空，雷聲聽隱隱，車响絕籠籠，恩光隨妙舞，团扇逐秋風，鉛華誰不見，人意自難同。","sortOrder":60},
  {"id":"s_work_nvlt_30_61","chapterId":"ch_work_nvlt_30","text":"梁何思澄班婕妤詩曰：寂寂長信晚，雀聲愁洞房，蜘蛛網高閣，駮藓被長廊，虛殿帘帷靜，閒階花蕊香，愁愁视日暮，還复守空床。","sortOrder":61},
  {"id":"s_work_nvlt_30_62","chapterId":"ch_work_nvlt_30","text":"梁施榮泰王昭君詩曰：垂羅下椒閣，舉袖拂胡尘，即即撫心叹，蛾眉誤殺人。","sortOrder":62},
  {"id":"s_work_nvlt_30_63","chapterId":"ch_work_nvlt_30","text":"梁徐悱妻劉氏班婕妤怨詩曰：日没應門閉，愁思百端生，况复昭陽近，風傳歌吹聲，寵移真不恨，讒枉太無情，祗言爭分理，非妒舞腰輕。","sortOrder":63},
  {"id":"s_work_nvlt_30_64","chapterId":"ch_work_nvlt_30","text":"梁王叔英妻劉氏王昭君怨詩曰：一生竟何定，萬事良難保，丹青失應圖，匣玉成秋草，相接辭關淚，至今猶未燥，漢使汝南還，殷勤為人道。","sortOrder":64},
  {"id":"s_work_nvlt_30_65","chapterId":"ch_work_nvlt_30","text":"梁范靖妻沈氏昭君叹詩曰：早信丹青巧，重賂洛陽師，千金畫雲鬢，百萬寫娥眉。","sortOrder":65},
  {"id":"s_work_nvlt_30_66","chapterId":"ch_work_nvlt_30","text":"陳陰铿班婕妤詩曰：柏梁新寵盛，長信昔恩傾，誰謂詩書巧，翻為歌舞輕，花月分窗進，苔草共階生，憶淚衫前滿，单眠夢里驚，可惜逢秋扇，何用合歡名。","sortOrder":66},
  {"id":"s_work_nvlt_30_67","chapterId":"ch_work_nvlt_30","text":"陳明昭［樂府詩集二十九作陳昭，按晉讳昭作明，當是陳昭沿舊稱作明君辭，後人誤倒。］君辭曰：跨鞍今永訣，垂涕別親賓，漢地隨行盡，胡關逐望新，郊河壅塞霧，隴日闇沙尘，唯有孤明月，猶能遠送人。","sortOrder":67},
  {"id":"s_work_nvlt_30_68","chapterId":"ch_work_nvlt_30","text":"【賦】漢董仲舒士不遇賦曰：呜呼嗟乎，遐哉邈矣，時來曷遲，去之速矣，屈意從人，悲吾族矣，正身俟時，將就木矣，心之忧兮，不期祿矣，遑遑匪寧，祗增辱矣，努力觸藩，徒摧角矣，不出戶庭，庶無過矣，重曰：生不丁三代之盛隆兮，而丁三季之末俗，末俗以辯诈而期通，貞士以耿介而自束，雖日三省於吾身，繇懷進退之唯穀，彼寔繁之有徒，指貞白以為墨，目信嫮而言眇，口信辯而言讷，鬼神不能正人事之变戾，聖賢亦不能开愚夫之违惑，出門則不可與偕同，藏器又蚩其不容，退洗心而內訟，固亦未知其所從，觀上世之清暉，廉士茕茕而靡歸，殷湯有卞隨與務光，周武有伯夷與叔齊，孰若反身於素業，莫隨世俗而輪轉，雖矯情而獲百利，不如复心而歸一善。","sortOrder":68},
  {"id":"s_work_nvlt_30_69","chapterId":"ch_work_nvlt_30","text":"漢司馬遷悲士不遇賦曰：悲夫士生之不辰，愧顧影而獨存，恒克己而复禮，懼志行而無聞，谅才韙而世戾，將逮死而長勤，雖有行而不彰，徒有能而不陳，何窮達之易惑，信美惡之難分，時悠悠而荡荡，將遂屈而不伸，使公於公者，彼我同兮，私於私者，自相悲兮，天道微哉，吁嗟闊兮，人理顯然，相傾奪兮，好生惡死，才之鄙也，好貴夷賤，哲之亂也，炤炤洞達，胸中豁也，昏昏罔覺，內生毒也，我之心矣，哲已能忖，我之言矣，哲已能選，没世無聞，古人惟恥，朝聞夕死，孰雲其否，逆順還周，乍没乍起，無造福先，無觸禍始，委之自然，終歸一矣。","sortOrder":69},
  {"id":"s_work_nvlt_30_70","chapterId":"ch_work_nvlt_30","text":"漢司馬相如陳皇後長門賦曰：原賜問而同進兮，得尚君之玉音，奉虛言而望誠兮，期城南之離宮，循薄具而自設兮，君不肯而幸臨，浮雲鬱而四塞兮，天窈窈而晝陰，雷隱隱而响起兮，聲象君之車音，刻木蘭以為榱兮，飾文杏以為梁，日黃昬而望絕兮，怅獨讬於空堂，懸明月以自照兮，徂清夜於洞房，援雅琴以变調兮，奏愁思之不可長，案流徵以却轉兮，聲窈妙而复扬，摶芬若以為枕兮，席荃蘭而茝香，忽寢寐而夢想兮，魂若君之在傍。","sortOrder":70},
  {"id":"s_work_nvlt_30_71","chapterId":"ch_work_nvlt_30","text":"班婕妤自傷賦曰：承祖考之遺德，荷性命之淑靈，登薄軀於宮闈，充下陳於後庭，蒙聖皇之渥惠，當日月之盛明，扬光烈之翕赫，奉隆寵於增城，既遇幸於非位，竊庶幾乎嘉時，陳女圖而鏡鑒，顧女史而問詩，歷年歲而悼懼，闵蕃華之不滋，白日忽以移光，遂暗漠以昧幽，猶被覆載之厚德，不废捐於罪尤，奉供養於東宮，讬長信之末流，重曰：潛玄宮兮幽以清，應門閉兮禁闈扃，華殿尘兮玉階苔，中庭萋兮绿草生，神眇眇兮密靜處，君不御兮誰為榮，俯视兮丹墀，思君兮履綦，仰视兮雲屋，双涕兮橫流，顧左右兮和顏，酌羽觴兮銷忧，惟人生兮一世，忽一過兮若浮。","sortOrder":71},
  {"id":"s_work_nvlt_30_72","chapterId":"ch_work_nvlt_30","text":"魏丁廙蔡伯喈女賦曰：伊太宗之令女，禀神惠之自然，在華年之二八，披邓林之曜鮮，明六列之尚致，服女史之話言，參過庭之明訓，才朗悟而通玄，當三春之嘉月，時將歸於所天，曳丹羅之輕裳，戴金翠之華钿，美榮曜之所茂，哀寒霜之已繁，豈偕老之可期，庶盡歡於餘年，何大原之不遂，飄微軀於逆邊，行悠悠於日遠，入穹穀之寒山，慚柏舟於千祀，負冤魂於黃泉，我羁虜其如昨，經春秋之十二，忍胡顏之重恥，恐終風之我萃，詠芳草於萬里，想音尘之仿佛，祈精爽於交夢，終寂寞而不至，哀我生之何辜，為神靈之所弃，仰蕣華其已落，臨桑榆之歔欷，入穹庐之秘馆，亟逾時而經節，叹殊類之非匹，傷我躬之無悅，脩膚體以深，［句有脱文。］念蘭泽之空設，佇美目於胡忌，向凯風而泣血。","sortOrder":72},
  {"id":"s_work_nvlt_30_73","chapterId":"ch_work_nvlt_30","text":"梁江淹恨賦曰：试望平原，蔓草萦骨，拱木斂魂，人生到此，天道寧論，於是仆本恨人，心驚不已，直念古者，伏恨而死，若乃趙王既虜，遷於房陵，薄心動念，昧旦晨興，別艳姬與美女，丧金舆及玉乘，置酒欲飲，悲來填膺，千秋萬歲，為怨難勝，至如李君降北，名辱身冤，拔劍击柱，弔影慚魂，若夫明妃去時，仰天太息，紫台稍遠，關山無極，搖風忽起，白日西匿，隴雁少飛，岱雲寡色，望君皇兮何期，終芜絕兮異域，至如敬通見抵，罢歸田里，閉關却扫，塞門不仕，左對孺人，右顧稚子，脱略公卿，跌宕文史，赍志没地，長懷無已，若夫中散下獄，神氣激扬，濁醪夕引，素琴晨張，秋日萧索，浮雲無光，鬱青霞之奇志，入脩夜之不暘，或有孤臣危涕，孽子墜心，遷客海上，流戍隴陰，此人但聞悲風汩起，泣下霑衿，亦复含酸茹怨，銷落湮沉，若乃騎叠跡，車屯軌，黃尘匝地，歌吹四起，無不煙斷火絕，閉骨泉里，已矣哉，春草暮兮秋風驚，秋風罢兮春草生，綺羅畢兮池管盡，琴瑟滅兮丘隴平，自古皆有死，莫不飲恨而吞聲。","sortOrder":73},
  {"id":"s_work_nvlt_30_74","chapterId":"ch_work_nvlt_30","text":"《藝文類聚》　唐·欧陽詢","sortOrder":74},
  {"id":"s_work_nvlt_31_1","chapterId":"ch_work_nvlt_31","text":"卷三十一人部十五","sortOrder":1},
  {"id":"s_work_nvlt_31_2","chapterId":"ch_work_nvlt_31","text":"○赠答","sortOrder":2},
  {"id":"s_work_nvlt_31_3","chapterId":"ch_work_nvlt_31","text":"◇赠答","sortOrder":3},
  {"id":"s_work_nvlt_31_4","chapterId":"ch_work_nvlt_31","text":"《毛詩》曰：無言不詶。","sortOrder":4},
  {"id":"s_work_nvlt_31_5","chapterId":"ch_work_nvlt_31","text":"又，周公乃為詩以貽王，名之曰鴟鴞焉。","sortOrder":5},
  {"id":"s_work_nvlt_31_6","chapterId":"ch_work_nvlt_31","text":"又，吉甫作頌，其詩孔硕，其風肆好，以赠申伯。","sortOrder":6},
  {"id":"s_work_nvlt_31_7","chapterId":"ch_work_nvlt_31","text":"《晏子》曰：曾子將行，晏子送之曰：君子赠人以軒，不如赠人以言。","sortOrder":7},
  {"id":"s_work_nvlt_31_8","chapterId":"ch_work_nvlt_31","text":"《史記》曰：孔子適周，見老子，辭去，老子送之曰：吾聞富貴者送人以财，仁者送人以言，吾竊仁者之號，請送子以言。","sortOrder":8},
  {"id":"s_work_nvlt_31_9","chapterId":"ch_work_nvlt_31","text":"《孫卿子》曰：赠人以言，重於金石珠玉，勸人以言，美於黼黻文章，聽人以言，樂於鍾鼓琴瑟。","sortOrder":9},
  {"id":"s_work_nvlt_31_10","chapterId":"ch_work_nvlt_31","text":"《莊子》曰：凡交近則必相靡以信，遠則必忠之以言。","sortOrder":10},
  {"id":"s_work_nvlt_31_11","chapterId":"ch_work_nvlt_31","text":"《韓子》曰：鄭人有遺燕相書者，夜書，火不明，因謂持燭者曰：舉燭，而過書舉燭，非書意也，燕相國受書而悅之曰：舉燭者，高明也，舉賢任之，司［○《太平御覽》八百七十作國。］以治。","sortOrder":11},
  {"id":"s_work_nvlt_31_12","chapterId":"ch_work_nvlt_31","text":"《穆天子傳》曰：穆王饗西王母於瑤池之上，上賦詩往來，辭義可觀。","sortOrder":12},
  {"id":"s_work_nvlt_31_13","chapterId":"ch_work_nvlt_31","text":"《漢書》曰：古者諸侯卿大夫，交接鄰國，以微言相感，常揖讓之時，必稱詩以喻其志。","sortOrder":13},
  {"id":"s_work_nvlt_31_14","chapterId":"ch_work_nvlt_31","text":"又曰：陳遵為河南太守，既至官，常遣從使西，召善書吏十人於前，治私書，謝京師親故，遵凭幾，占書數百封，親疏各有意。","sortOrder":14},
  {"id":"s_work_nvlt_31_15","chapterId":"ch_work_nvlt_31","text":"《文士傳》曰：桓驎伯父乌［《太平御覽》三百八十五作焉，此訛。］官至太尉，驎年十二，在座，焉告客曰：吾此弟子，知有異才，殊能作詩賦，各［○據御覽。當作客。］乃為詩曰：甘羅十二，楊乌九齡，昔有二子，今則桓生，驎即應聲答曰：邈矣甘羅，超等絕倫，伊彼楊乌，命世稱賢，嗟予憃弱，殊才伟年，仰慚二子，俯媿過言。","sortOrder":15},
  {"id":"s_work_nvlt_31_16","chapterId":"ch_work_nvlt_31","text":"漢雜事曰：高彪謁馬融，辭疾不見，彪覆刺與書曰：聞高風為日久矣，故不待介者，造君子之門，冀一見龍光，叙腹心之原，不圖辭之以疾，昔者周公兄父文武，九命作伯，以君華夏，猶握沐吐餐，以接白屋之士，天下歸德，歷載邈矣，今君不能相見，宜哉，融省書大慚，遣人辭謝追請，径去不還。","sortOrder":16},
  {"id":"s_work_nvlt_31_17","chapterId":"ch_work_nvlt_31","text":"先賢行状曰：杜安入太學，時號曰神童，時貴戚慕安高行，多有與書者，不辄發，以慮後患，常凿壁藏書，當時皆嘉其慮遠。","sortOrder":17},
  {"id":"s_work_nvlt_31_18","chapterId":"ch_work_nvlt_31","text":"《會稽典錄》曰：陳業少特操，沛國桓俨，當世英俊，避地會稽，聞業高節，欲與相見，終不獲，後俨浮海南入交州，臨去，遺書與業曰：不因行李，以系陰山白樓，曰：從容養高，動靜履直，季世多艱，爰適樂土，聞高風飢渴語言，知乃深隱邈然，終時求仁，斯得勤而無憾，齊蹤古賢，何其優哉。","sortOrder":18},
  {"id":"s_work_nvlt_31_19","chapterId":"ch_work_nvlt_31","text":"《蜀志》曰：馬良使吳，良謂諸葛亮曰：今衔國命，协睦二家，幸為良介於孫將軍，亮曰：君试自為文，良即為草曰：寡君遣掾馬良，通聘繼好，以紹崑吾豕韦之勋，其人吉士，荆楚之令，鮮於造次之華，而有克終之美，原降心有納，以慰將命，權大悅之。","sortOrder":19},
  {"id":"s_work_nvlt_31_20","chapterId":"ch_work_nvlt_31","text":"文章叙錄曰：杜挚與毌丘俭乡里相親，故為詩與俭，求仙人藥一丸，欲以感切俭，求助也。","sortOrder":20},
  {"id":"s_work_nvlt_31_21","chapterId":"ch_work_nvlt_31","text":"荀氏家傳曰：荀勖，蜀平之後，遣使通吳，司馬文王，用公所作書與孫皓，皓報命和親，王謂公曰：君前作書，使吳思順，勝十萬之眾也。","sortOrder":21},
  {"id":"s_work_nvlt_31_22","chapterId":"ch_work_nvlt_31","text":"《楚辭》曰：結微情以陳詞兮，矯以遺夫美人。","sortOrder":22},
  {"id":"s_work_nvlt_31_23","chapterId":"ch_work_nvlt_31","text":"【詩】後漢蔡邕答對元式詩曰：伊餘有行，爰戾茲邦，先進博學，同類率從，濟濟群彦，如雲如龍，君子博文，貽我德音，辭之集矣，穆如清風。","sortOrder":23},
  {"id":"s_work_nvlt_31_24","chapterId":"ch_work_nvlt_31","text":"又答卜元嗣詩曰：斌斌硕人，貽我以文，辱此休辭，非餘所希，敢不酬答，賦誦以歸。","sortOrder":24},
  {"id":"s_work_nvlt_31_25","chapterId":"ch_work_nvlt_31","text":"魏王粲赠蔡子篤詩曰：悠悠世路，亂離多阻，濟岱江衡，邈焉異處，風流雲散，一別如雨。","sortOrder":25},
  {"id":"s_work_nvlt_31_26","chapterId":"ch_work_nvlt_31","text":"魏徐幹答劉楨詩曰：與子別無幾，所經未一旬，我思一何篤，其愁如三春，雖路在咫尺，難涉如九關，陶陶朱夏別，草木昌且繁。","sortOrder":26},
  {"id":"s_work_nvlt_31_27","chapterId":"ch_work_nvlt_31","text":"魏應玚報趙淑麗詩曰：朝雲不歸，久結成陰，離群猶宿，永思長吟，有鳥孤栖，哀鳴北林，嗟我懷矣，感物傷心。","sortOrder":27},
  {"id":"s_work_nvlt_31_28","chapterId":"ch_work_nvlt_31","text":"魏繁钦赠梅公明詩曰：瞻我北園，有條者桑，遘此春景，既茂且長，氤氲吐葉，柔润有光，黃條蔓衍，青鳥來翔，日月其邁，時不可忘，公子瞻旃，勋名乃彰。","sortOrder":28},
  {"id":"s_work_nvlt_31_29","chapterId":"ch_work_nvlt_31","text":"魏程晓赠傅休弈詩曰：茕茕獨夫，寂寂靜處，酒不盈觴，肴不掩俎，厥客伊何，許由巢父，厥醴伊何，玄酒瓠脯。","sortOrder":29},
  {"id":"s_work_nvlt_31_30","chapterId":"ch_work_nvlt_31","text":"又赠傅休弈詩曰：三光飛景，玉衡代邁，龍集甲子，四時成歲，權舆授代，徐陳荡秽，元服初嘉，萬福鹹會，赫赫應門，嚴嚴朱闕，群後傷傷，［明本作堂扬扬。］庭燎晳晳。","sortOrder":30},
  {"id":"s_work_nvlt_31_31","chapterId":"ch_work_nvlt_31","text":"魏邯鄲淳答赠詩曰：我受上命，來隨臨菑，與君子處，曾未盈期，見召本朝，駕言趣期，群子重離，首命於時，餞我路隅，赠我嘉辭，既受德音，敢不答之，餘惟薄德，既局且鄙，見養賢侯，於今四祀，既庇西伯，永誓没齒，今也被命，我在不俟，瞻恋我侯。又慕君子，行道遲遲，體逝情止，豈無好爵，懼不我與，聖主受命，千載一遇，攀龍附鳳，必在初舉，行矣去矣，別易會難，自強不息，人誰獲安，原子大夫，勉匮成山，天休方至，萬福爾臻。","sortOrder":31},
  {"id":"s_work_nvlt_31_32","chapterId":"ch_work_nvlt_31","text":"晉張華答何劭詩曰：良朋貽新詩，示我以遊娱，穆如洒清風，煥若春華敷，自昔同寮寀，於今比園墟，衰夕近辱殆，庶幾併懸舆，散發重陰下，把杖臨清渠，屬耳聽鳴禽，流目玩儵魚，從容養餘日，取樂於桑榆。","sortOrder":32},
  {"id":"s_work_nvlt_31_33","chapterId":"ch_work_nvlt_31","text":"又詩曰：駕言歸外庭，放志永栖遲，相伴步園畴，春草鬱鬱滋，榮觀雖盈目，親友莫與偕，悟物增隆思，結恋慕同儕，援翰屬新詩，永叹有餘懷。","sortOrder":33},
  {"id":"s_work_nvlt_31_34","chapterId":"ch_work_nvlt_31","text":"又赠挚仲治詩曰：君子有逸志，栖遲於一丘，仰荫高林茂，俯臨渌水流，恬淡養玄虛，况精研聖猷。","sortOrder":34},
  {"id":"s_work_nvlt_31_35","chapterId":"ch_work_nvlt_31","text":"何劭赠張華詩曰：四時更代謝，萬物迭卷舒，暮春忽复來，和風與節俱，俯臨清泉涌，仰觀嘉木敷，在昔同班司，今者併園墟，私原階黃發，逍遙樂琴書，舉爵茂陰下，携手共踌躇，奚用遺形骸，忘筌在得魚。","sortOrder":35},
  {"id":"s_work_nvlt_31_36","chapterId":"ch_work_nvlt_31","text":"晉潘嶽為贾謐赠陆機詩曰：神農更生，軒轅承紀，畫野離彊，爰封眾子，夏殷既袭，宗周系祀，綿綿瓜瓞，六國互峙，彊秦兼併，吞滅四隅，子婴面榇，漢祖應符，靈獻微弱，在涅則渝，三雄鼎足，孫啟南吳，南吳伊何，僣號稱王，大晉統天，仁風遐扬，伪孫衔璧，奉土歸疆，婉婉長離，陵江而翔，長離雲誰，咨餘陆生，鶴鳴九皋，猶載厥聲，况乃海隅，播名上京，爰應旌招，撫翼紫庭，蕃嶽作镇，辅我京室，旋及桑梓，帝弟作弼，式雲國官，清涂攸失，吾子洗然，恬淡自逸，廊廟惟清，俊乂是延，擢應嘉舉，自國而遷，齊辔群龍，光贊納言，優遊省闼，珥筆華軒，昔餘與子，繾綣同朝，脩日朗月，携手逍遙，自我離群，二周於今，雖簡其面，分著情深，子其超矣，實慰我心，發言為詩，望俟好音，欲崇其高，必重其曾，在南稱甘，度北則橙，崇子鋒穎，不騫不崩。","sortOrder":36},
  {"id":"s_work_nvlt_31_37","chapterId":"ch_work_nvlt_31","text":"晉陆機答贾謐詩曰：先天創物，景命是膺，降及群後，迭毀迭興，邈矣終古，崇替有徵，在漢之季，皇綱幅裂，雄臣騰骛，義夫赴節，釋位揮戈，言謀王室，王室之亂，靡邦不泯，如彼墜景，曾不可振，乃眷三哲，俾乂斯民，啟土綏難，改物承天，天厭霸德，皇祚告衅，獄訟违魏，謳歌逼晉，陳留歸蕃，我皇登禪，庸崏稽顙，三江改獻，惟公太宰，光翼二祖，誕育洪胄，纂戎於魯，昔我逮茲，時惟下僚，及子栖遲，同林異條，年殊志密，服舛義禂，遊跨三春，情固二秋，祗承皇命，出納無违，往踐蕃朝，來步紫微，升降秘閣，我服載暉，孰雲匪懼，仰肅明威，分索則易，携手實難，念昔良遊，茲焉永叹，公之雲感，貽此音翰，蔚彼高藻，如玉如蘭，民之胥好，指狂厲聖，儀形在昔，爭聞子命。","sortOrder":37},
  {"id":"s_work_nvlt_31_38","chapterId":"ch_work_nvlt_31","text":"又答潘尼詩曰：於穆同心，如琼如琳，我東日徂，來餞其琛，彼美潘生，實綜我心，探子玉懷，畴爾惠音。","sortOrder":38},
  {"id":"s_work_nvlt_31_39","chapterId":"ch_work_nvlt_31","text":"又赠冯文羆詩曰：嗟我人斯，戢翼江潭，有命集上，翻飛自南，出彼幽穀，及爾同林，双情交映，遺物識心。","sortOrder":39},
  {"id":"s_work_nvlt_31_40","chapterId":"ch_work_nvlt_31","text":"又赠潘尼詩曰：水會於海，雲翔於天，道之所混，孰後孰先，及子雖殊，同升太玄，舍彼玄冕，袭此雲冠，遺情市朝，永志丘園，靜猶幽穀，動若揮蘭。","sortOrder":40},
  {"id":"s_work_nvlt_31_41","chapterId":"ch_work_nvlt_31","text":"又赠從兄車騎詩曰：孤獸思故藪，離鳥悲舊林，翩翩遊宦子，辛苦難為心，仿佛穀水陽，婉娈崑山陰，營魄懷茲土，精爽若飛沉。","sortOrder":41},
  {"id":"s_work_nvlt_31_42","chapterId":"ch_work_nvlt_31","text":"又赠波丘令冯文羆詩曰：夙駕出東城，送子臨江曲，密席接同志，羽觴飛酃渌，登樓望峻陂，時逝一何速。","sortOrder":42},
  {"id":"s_work_nvlt_31_43","chapterId":"ch_work_nvlt_31","text":"又赠紀士詩曰：琼朅俟丰价，窈窕不自鬻，有美蛾眉子，惠音清且淑，修嫮协姝麗，華顏婉如玉。","sortOrder":43},
  {"id":"s_work_nvlt_31_44","chapterId":"ch_work_nvlt_31","text":"又赠顧彦先詩曰：清夜不能寐，悲風入我軒，立影對孤軀，哀聲應苦言。","sortOrder":44},
  {"id":"s_work_nvlt_31_45","chapterId":"ch_work_nvlt_31","text":"晉傅玄答程晓詩曰：弈弈兩儀，昭昭太陽，四氣代升，三朝受祥，濟濟群後，瓘瓘聖皇，元服肇御，配天垂光，伊周作弼，王室惟康，顒顒兆民，蠢蠢戎膻，率土充庭，萬國奉蕃，皇泽雲行，神化風宣，六合鹹熙，遐邇同歡，赫赫明明，天人合和，下罔遺滯，焦朽斯華，矧我良朋，如玉之嘉，穆穆雝雝，興頌作歌。","sortOrder":45},
  {"id":"s_work_nvlt_31_46","chapterId":"ch_work_nvlt_31","text":"又答程晓詩曰：羲和運玉衡，招搖賦朔旬，嘉慶形三朝，美德扬初春，聖主加元服，萬國望威神，伊周敷玄化，併世霑天人，洪涯歌山岫，許由嗟水濱。","sortOrder":46},
  {"id":"s_work_nvlt_31_47","chapterId":"ch_work_nvlt_31","text":"又傅鹹赠褚武良詩曰：爰暨於褚，惟晉之禎，肇振鳳翼，羽儀上京，聿作喉舌，納言紫庭，光贊帝道，敷皇之明，方任之重，實在江扬，乃授旄鉞，宣曜威靈，悠悠遐邁，東夏於征。","sortOrder":47},
  {"id":"s_work_nvlt_31_48","chapterId":"ch_work_nvlt_31","text":"又赠建平太守李叔龍詩曰：弘道興化，實在良守，悠悠建平，皇泽未流，朝選於眾，乃子之授，南荆註望，心乎克副。","sortOrder":48},
  {"id":"s_work_nvlt_31_49","chapterId":"ch_work_nvlt_31","text":"又赠太尉司馬虞顯機詩曰：帝崇元淑，妙選其屬，命子是佐，增袞之縟。","sortOrder":49},
  {"id":"s_work_nvlt_31_50","chapterId":"ch_work_nvlt_31","text":"又赠崔伏二郎詩曰：英妙之選，二生之授，顒顒兩城，歡德之茂，君子所居，九夷非陋，無狹百里，而不垂覆，人之好我，赠我清詩，示我周行，心與道期，誠發自忠，義形於辭，古人辭谠，豈不爾思。","sortOrder":50},
  {"id":"s_work_nvlt_31_51","chapterId":"ch_work_nvlt_31","text":"又與尚書同僚詩曰：非望之寵，谬加於己，猥授非據，奄司萬里，煌煌朱軒，服骥參騄，晔晔初延，肅肅臣仆，暉光顯赫，眾目所屬，斯之弗稱，匪榮伊辱，质弱尚甫，受任鷹扬，德非樊仲，王命是將，百城或违，無能有匡，一州之矜，將弛其綱，得意忘言，言在意後，夫惟神交，可以長久，我心之孚，有盈於缶，與子階［疑當作偕。］老，豈曰執手，出司萬里，牧彼朔濱，服冕乘軒，六辔既均，威風先邁，百城肅震。","sortOrder":51},
  {"id":"s_work_nvlt_31_52","chapterId":"ch_work_nvlt_31","text":"又答潘尼詩併序曰：司州秀才潘正叔，識通才高，以文學溫雅為博士，餘性直而處清論襃貶之任，作詩以見規，雖襃飾之舉，非所敢聞，而斐粲之辭，良可樂也，答之雖不足以相詶報，所盍各言志也，詩曰：貽我妙文，繁春之榮，匪榮斯尚，乃新其聲，吉甫作頌，有馥其馨，寔由樊仲，其德克明，授此瓦砾，廁彼瑤琼，貺非其喻，聞寵若驚。","sortOrder":52},
  {"id":"s_work_nvlt_31_53","chapterId":"ch_work_nvlt_31","text":"又答栾弘詩併序曰：安樂令栾弘，太傅鉅平侯羊公辟，未就而公薨，後應司州之命，舉秀才，博文通濟之士，餘失和於府，當換為護軍司馬，賦詩見赠，答之雲爾，鉅平作宰，是貴是钦，弓旌仍招，嘉命胥尋，鸞鳳養儀，戢翼幽林，未附雅調，以和韶音，鉅平遐逝，厲志弥深，肅肅京司，清風裁邁，乃延群彦，龍集鳳會，亦既斯降，萬里有賴，聲發响應，好結傾蓋。","sortOrder":53},
  {"id":"s_work_nvlt_31_54","chapterId":"ch_work_nvlt_31","text":"晉潘尼答傅鹹詩序曰：司徒左長史傅長虞，會定九品，左長史宜得其才，屈為此職，此職執天下清議，宰割百國，而長虞性直而行，或有不堪，餘與之親，作詩以規焉，悠悠群吏，非子不整，嗷嗷眾議，非子不靖，忽荷略紐，握綱提領，矯矯貞臣，惟國之屏。","sortOrder":54},
  {"id":"s_work_nvlt_31_55","chapterId":"ch_work_nvlt_31","text":"又赠吳王郎中令陆士衡詩曰：東南之美，曩惟延州，顯允陆生，於今斯畴，振鱗南海，濯翼洪流，婆娑翰林，容與墳丘，玉以瑜润，隨以光融，乃漸上京，乃儀储宮，玩爾清藻，味爾芳風，泳之弥廣，揖之弥冲，崑山何有，有瑤有珉，及爾同僚，具惟近臣，予涉素秋，子登青春，媿無老成，廁彼日新，祁祁大邦，惟桑與梓，穆穆伊人，南國之紀，帝曰爾諧，惟王卿士，俯僂從命，奚恤奚喜。","sortOrder":55},
  {"id":"s_work_nvlt_31_56","chapterId":"ch_work_nvlt_31","text":"又答陆士衡詩曰：顧茲蓬蔚，廁根蘭陂，膏泽雖均，華不足披，逮春不茂，未秋先萎，子濯鱗翼，我挫羽儀，原言難常，載今載離，昔遊禁闼，祗畏夕惕，今放丘園，縱心夷易，口詠新詩，目玩文跡，予志耕圃，爾勤王役，慚無琬琰，以詶尺璧。","sortOrder":56},
  {"id":"s_work_nvlt_31_57","chapterId":"ch_work_nvlt_31","text":"又赠隴西太守張仲治詩曰：二八由唐顯，周以多士隆，群靈感韶運，理翮應翔風，張生拔幽華，蘋蘩登二宮，未幾振朱錦，剖符撫西戎，及子仍同僚，赠言貽爾躬，威刑有時用，唯德可念終。","sortOrder":57},
  {"id":"s_work_nvlt_31_58","chapterId":"ch_work_nvlt_31","text":"又赠劉佐詩曰：要言將誰苦，聊以貽友生，念我二三賢，規我無隱情。","sortOrder":58},
  {"id":"s_work_nvlt_31_59","chapterId":"ch_work_nvlt_31","text":"又送大將軍掾盧晏詩曰：赠物雖陋薄，識意在忘言，琼琚尚交好，桃李貴往還，萧艾苟見納，貽我以芳蘭。","sortOrder":59},
  {"id":"s_work_nvlt_31_60","chapterId":"ch_work_nvlt_31","text":"又赠汲郡太守李茂彦詩曰：離索何惆怅，後會未可希，河朔貴相忘，歧路安足悲。","sortOrder":60},
  {"id":"s_work_nvlt_31_61","chapterId":"ch_work_nvlt_31","text":"又赠長安令劉正伯詩曰：遊鸞凭太虛，騰鱗讬浮霄，過蒙嘉時會，假翼陵扶搖，疲憊充時乏，及餘再同寮，併跡侍储宮，携手登皇朝，劉侯撫西都，邁績參豹乔，德厚化必深，政明奸自消，萬尋由積匮，千里一步超，爾其騁逸軌，遠涂固可要。","sortOrder":61},
  {"id":"s_work_nvlt_31_62","chapterId":"ch_work_nvlt_31","text":"又答楊士安詩曰：逝將辭储宮，栖遲集南畿，不誤百里賤，徒惜年志衰，踌躇顧城闕，怨恋慕端闈，俊德貽妙詩，敷藻發清徽，媿彼襃崇過，感此歧路悲。","sortOrder":62},
  {"id":"s_work_nvlt_31_63","chapterId":"ch_work_nvlt_31","text":"又赠榮陽太守吳子仲詩曰：大晉盛得人，储宮畜髦士，吳侯降高质，剖符授千里，垂覆豈他乡，回光臨桑梓，寮類感歧路，黎庶思知恥，老氏喻小鱗，曹參寄獄市，無謂弊邑陋，覆簣由茲起。","sortOrder":63},
  {"id":"s_work_nvlt_31_64","chapterId":"ch_work_nvlt_31","text":"晉張載赠虞顯度詩曰：畴昔协蘭房，繾綣在華年，嘉好結平素，分著寮友前，謂得終遐日，綢缪永周旋，吾子遭不造，遘闵丁忧艱，俾我失良朋，誰與吐話言，一日為三秋，歲况乃三年，離居一何闊，結思如回川。","sortOrder":64},
  {"id":"s_work_nvlt_31_65","chapterId":"ch_work_nvlt_31","text":"晉石崇赠棗腆詩曰：久官無成績，栖遲於徐方，寂寂守空城，悠悠思故乡，恂恂二三賢，身遠屈龍光，携手沂泗間，遂登舞雩堂，文藻譬春華，談話由蘭芳，消忧以觴醴，娱耳以名娼，博弈逞妙思，弓矢威邊疆。","sortOrder":65},
  {"id":"s_work_nvlt_31_66","chapterId":"ch_work_nvlt_31","text":"晉司馬彪赠山涛詩曰：苕苕椅梧树，寄生於南嶽，上陵青雲霓，下臨千仞穀，處身自孤危，於何讬餘足，晉曹摅赠石崇詩曰：涓涓穀中泉，鬱鬱巖下林，泄泄群翟飛，咬咬春鳥吟，野次何索漠，薄暮愁人心，三軍望衡蓋，叹息有餘音，臨肴忘肉味，對酒不能斟，人言重別離，斯情效於今。","sortOrder":66},
  {"id":"s_work_nvlt_31_67","chapterId":"ch_work_nvlt_31","text":"晉劉琨赠盧諶詩曰：時光不我與，去乎若雲浮，朱實陨劲風，繁英落素秋，狹路傾華蓋，駭驷摧双辀，何意百煉刚，化為繞指柔。","sortOrder":67},
  {"id":"s_work_nvlt_31_68","chapterId":"ch_work_nvlt_31","text":"又重赠劉琨詩［按本詩系劉琨下，則題不當雲重赠劉琨，疑當作重赠盧諶，此有訛誤，冯惟讷晉詩紀迳改作盧諶詩，然按詩義，乃劉答盧詩，疑非。］曰：璧由識真顯，龍因慶雲翔，茨棘非所憩，翰飛遊高岡，餘音非九韶，何以儀鳳皇，新城非芝圃，曷由殖蘭芳。","sortOrder":68},
  {"id":"s_work_nvlt_31_69","chapterId":"ch_work_nvlt_31","text":"晉盧諶答劉琨詩曰：隨寶產漢濱，摛此夜光真，不待卞和顯，自為命世珍。","sortOrder":69},
  {"id":"s_work_nvlt_31_70","chapterId":"ch_work_nvlt_31","text":"晉棗腆赠石季倫詩曰：深蒙君子眷，雅顧出群俗，受寶取諸懷，所赠非珠玉，凡我二三子，執手携玉腕，嘉言從所好，企予結雲漢，望風整輕翮，因虛舉双翰，朝遊清渠侧，日夕登高馆。","sortOrder":70},
  {"id":"s_work_nvlt_31_71","chapterId":"ch_work_nvlt_31","text":"又答石崇詩曰：昔我不造，備嘗顛沛，後土傾基，皇天陨蓋，少懷蒙昧，長無耿介，遺訓莫聞，出入靡賴，我舅敷命，於彼徐方，載詠陟岵，言念渭陽，乃溯洪流，汎身餘艎，宵寢晨逝，曷路之長，亦既至止，原言以寫，爰有石侯，作镇東夏，宽以撫戎，從容柔雅，我聞有言，居安思危，位極則遷，势至必移，上德無欲，貴道不為，妙識先覺，通夢皇羲，竊睹堂奧，钦蹈明規。","sortOrder":71},
  {"id":"s_work_nvlt_31_72","chapterId":"ch_work_nvlt_31","text":"晉挚虞答杜育詩曰：越有杜生，既文且哲，龍躍穎豫，有聲彰澈，賴茲三益，如琼如切，好以義結，友以文會，豈伊在高，分定傾蓋，其人如玉，美彼生刍，鍾鼓匪樂，安用百壶，老夫灌灌，離群索居，懷恋結好，心焉恨如。","sortOrder":72},
  {"id":"s_work_nvlt_31_73","chapterId":"ch_work_nvlt_31","text":"晉欧陽建答棗腆詩曰：於鑠我舅，明德塞违，俾扞東藩，在徐之邳，載播其惠，載扬其威，濟宽以猛，方夏以綏，光啟先業，增曜重暉，咨餘冲人，艱苦攸離，過庭無聞，顽固匪移，寔賴茲誨，导之軌儀，仰遵嘉訓，俯蹈明規，如葛斯蔓，如樛斯垂，我遘君子，仰之弥高，巖巖其高，即之惟溫，居盈思冲，在貴忘尊，縱酒嘉宴，自明及昏，無幽不妍，靡奧不論，人樂其量，士感其敦。","sortOrder":73},
  {"id":"s_work_nvlt_31_74","chapterId":"ch_work_nvlt_31","text":"晉石崇答棗腆詩曰：言念將別，睹物傷情，赠爾話言，要在遺名，唯此遺名，可以全生。","sortOrder":74},
  {"id":"s_work_nvlt_31_75","chapterId":"ch_work_nvlt_31","text":"晉杜育赠挚仲治詩曰：之子於歸，言秣其駒，矧乃斯人，乃邁乃徂，雖非顯甫，餞彼百壶，雖非張仲，將脍河魚，人亦有言，貴在同音，雖曰翻飛，曾未異林，顧恋同枝，增其慨心，望爾不遐，無金玉音。","sortOrder":75},
  {"id":"s_work_nvlt_31_76","chapterId":"ch_work_nvlt_31","text":"晉棗據答阮德猷詩曰：有朋顧之，貽我良箴，玩之無斁，終詠斯音，燕鼎在舟，雖重不沉，庶凭嘉謨，高跡可尋。","sortOrder":76},
  {"id":"s_work_nvlt_31_77","chapterId":"ch_work_nvlt_31","text":"宋顏延之赠王太常僧達詩曰：玉水記方流，璇源載圓折，蓄寶每希聲，雖秘猶彰澈，聆龍〈目祭〉九州，聞鳳窥丹穴，歷聽豈多士，唯然覯時哲，舒文廣國華，敷言遠朝烈，德煇灼邦茂，芳風被乡耋，侧同幽人居，郊扉常晝閉，林闾時晏开，亟回長者轍，庭昏見野陰，山明望松雪，靜惟浃群化，徂生入窮節，豫往誠歡聚，悲來非樂阕，屬美謝繁翰，遙懷具短札。","sortOrder":77},
  {"id":"s_work_nvlt_31_78","chapterId":"ch_work_nvlt_31","text":"又直東宮答鄭尚書道子詩曰：皇居體寰極，設险协天功，兩闈阻通軌，對禁阻［《文選》二十六作限。］清風。","sortOrder":78},
  {"id":"s_work_nvlt_31_79","chapterId":"ch_work_nvlt_31","text":"宋鮑昭赠顧墨曹詩曰：昏明易遠，離會難揆，雲撤泉分，西舻東軌。","sortOrder":79},
  {"id":"s_work_nvlt_31_80","chapterId":"ch_work_nvlt_31","text":"宋鮑令暉題書寄行人詩曰：自君之出矣，臨軒不解顏，砧杵夜不發，高門晝恒關，帳中流熠燿，庭前華紫蘭，物枯識節異，鸿來知客寒。","sortOrder":80},
  {"id":"s_work_nvlt_31_81","chapterId":"ch_work_nvlt_31","text":"又寄行人詩曰：桂吐兩三枝，蘭开四五葉，是時君不歸，春風徒笑妾。","sortOrder":81},
  {"id":"s_work_nvlt_31_82","chapterId":"ch_work_nvlt_31","text":"齊王俭赠徐孝嗣詩曰：婉婉遊龍，載遊載東，靡靡行雲，併躍齊蹤，無類不感，有來斯雍，之子雲邁，嗟我莫從，歲雲暮止，述職戒行，崇蘭罢秀，孤松獨貞，悲風宵遠，乘雁晨征，撫物遐想，念別書情。","sortOrder":82},
  {"id":"s_work_nvlt_31_83","chapterId":"ch_work_nvlt_31","text":"齊徐孝嗣答王俭詩曰：書帷停月，琴袖承飆，結芳幽穀，解珮明椒，去德滋永，懷德滋深，行雲傳想，歸鸿寄音。","sortOrder":83},
  {"id":"s_work_nvlt_31_84","chapterId":"ch_work_nvlt_31","text":"又齊王融赠族叔衛軍詩曰：台曜澄華，铉嶽裁峻，經天為象，麗地作镇，不器其德，有匪斯文，质起瑚璉，才逸卿雲，搖筆泉泻，動詠霙紛，德馨伊何，如蘭之宣，貞筠抽箭，润璧懷山，六樂畢該，五禮備貫，七訓是敷，三英有粲，惟旦惟公，惟公惟旦。","sortOrder":84},
  {"id":"s_work_nvlt_31_85","chapterId":"ch_work_nvlt_31","text":"齊謝朓夜發新林至京邑詩，赠西府同僚，大江流日夜，客心悲未央，徒望關山近，終知返路長，秋河曙耿耿，寒渚夜蒼蒼，引領望京邑，宮雉正相望，金波麗鳷鵲，玉繩低建章，驅車鼎門外，思見昭丘陽，池暉不可接，何况隔兩乡，風煙有鳥路，江漢限無梁，常恐鷹隼击，時菊委嚴霜，寄言罻羅者，寥廓已高翔。","sortOrder":85},
  {"id":"s_work_nvlt_31_86","chapterId":"ch_work_nvlt_31","text":"又在郡呈沈尚書詩曰：淮陽股肱守，高臥猶在茲，况复南山曲，何異幽栖時，高閤常晝掩，荒階少諍詞，珍簟清夏室，輕扇動涼飔，夏李沉朱實，秋藕折輕絲，良辰竟何許，夙昔夢佳期，坐嘯徒可積，為邦歲已期。","sortOrder":86},
  {"id":"s_work_nvlt_31_87","chapterId":"ch_work_nvlt_31","text":"齊陆厥奉答內兄顧希叔詩曰：平原十日飲，中散千里遊，渤海方流滯，宜城誰獻詶，屏居南山下，臨此歲方秋，惜哉時不與，日暮無輕舟。","sortOrder":87},
  {"id":"s_work_nvlt_31_88","chapterId":"ch_work_nvlt_31","text":"梁簡文帝赠張缵詩曰：儀表鹹推挹，牆仞難窥踐，既富垂帷學，复折波涛辯，綺思暧霞飛，清文煥飆轉，宋旗赫容與，彫棨紛曜煜，波搖白鱧舟，風動蒼鷹舳，九嶷势參差，江天相蔽虧，三春澧浦葉，九月洞庭枝，洞庭枝褭娜，澧浦葉參差，芬芳與搖落，俱應傷別離。","sortOrder":88},
  {"id":"s_work_nvlt_31_89","chapterId":"ch_work_nvlt_31","text":"梁沈約詶謝宣城朓詩曰：王乔飛凫舄，東方金馬門，從宦非宦侣，避世非避喧，揆予發皇鑒，短羽屢飛翻，晨趨朝建禮，晚沐臥郊園，賓至下尘榻，忧來命绿樽，昔賢侔時雨，今守馥蘭荪，神交疲夢寐，路遠隔思存。","sortOrder":89},
  {"id":"s_work_nvlt_31_90","chapterId":"ch_work_nvlt_31","text":"又詶孔逷通直懷蓬居詩曰：閶阖既洞啟，龍樓亦高辟，兩宮集鸞步，二闼引通籍，伊邇事清涂，紛吾供賤役。","sortOrder":90},
  {"id":"s_work_nvlt_31_91","chapterId":"ch_work_nvlt_31","text":"梁任昉答劉孝綽詩曰：閱水既成澜，藏舟遂移壑，彼美洛陽子，投我懷秋作，久敬類誠言，吹噓似嘲謔，兼稱夏雲盡，复陳秋树索，詎慰耋嗟人，徒深老夫讬。","sortOrder":91},
  {"id":"s_work_nvlt_31_92","chapterId":"ch_work_nvlt_31","text":"梁范雲赠沈左衛詩曰：伊昔霑嘉惠，出入承明宮，遊息萬年下，經過九龍中，越鳥憎北树，胡馬畏南風，原言反漁蓚，津梁肯見通。","sortOrder":92},
  {"id":"s_work_nvlt_31_93","chapterId":"ch_work_nvlt_31","text":"梁劉孝綽答張左西詩曰：相思如三月，相望非兩宮，持此連枝树，暫作背飛鸿，若人惠思我，摛藻蔚彫虫，仙掌方晞露，靈乌正轉風，方假排虛翮，相與北山藂。","sortOrder":93},
  {"id":"s_work_nvlt_31_94","chapterId":"ch_work_nvlt_31","text":"又赠任中丞詩曰：步出金華省，遙望承明庐，壮哉宛洛地，佳麗實皇居，虹蜺拖飛閣，蘭芷覆清渠，白雲夏峰盡，青槐秋葉疏，但原長閒暇，酌醴焚枯魚。","sortOrder":94},
  {"id":"s_work_nvlt_31_95","chapterId":"ch_work_nvlt_31","text":"梁王僧孺赠顧仓曹詩，洛陽十二門，樓闕似西崑，暧暧罘罳下，想望隔畫垣，畫垣向阿閣，栖鳳复栖鴛，五曹均趍奏，六尚等便煩，朝爐何馥馥，夜錦有餘溫，日中驅上驷，驤首遍京宛，晨趍魏公子，夕宿韓王孫，夙昔今何在，生平充不論，譬如卷葹草，心謝葉空存，誰复三承〈目妻〉，獨念九飛魂。又秋日愁居答孔主簿詩曰：首夏雲物善，盡暑旦猶清，日華隨水汎，树影逐風輕，依帘野馬合，當戶昔耶生，物我一無际，人鳥不相驚，傥遇北山北，聊訪法乔卿。","sortOrder":95},
  {"id":"s_work_nvlt_31_96","chapterId":"ch_work_nvlt_31","text":"又寄何記室詩曰：思君不得見，望望獨長嗟，夜風入寒水，晓露拂秋花，何由假日御，暫得寄風車。","sortOrder":96},
  {"id":"s_work_nvlt_31_97","chapterId":"ch_work_nvlt_31","text":"梁王筠寓直中庶坊赠萧洗馬詩曰：龍樓實九重，薄寒起殊早，玉階泣清露，銅池結秋潦，霜被守宮槐，風驚護門草，之子擅文華，縱橫富辭藻，舒錦慚光麗，握珠謝奇寶，媿予非工文，何用披懷抱。","sortOrder":97},
  {"id":"s_work_nvlt_31_98","chapterId":"ch_work_nvlt_31","text":"又東陽還經嚴陵瀨赠萧大夫詩曰：子陵徇高尚，超然獨長往，釣石宛如新，故態依可想。","sortOrder":98},
  {"id":"s_work_nvlt_31_99","chapterId":"ch_work_nvlt_31","text":"梁裴子野答張貞成皋詩曰：匈奴時未滅，連年被甲兵，明君思將帥，方聽鼓鞞聲，吾生姿逸翮，撫劍起徂征，非徒慕辛李，聊欲逞良平，出車既方軌，絕幕且橫行，豈伊長纓系，行見黃河清，雖令懦夫勇，念別猶有情，感子盈編赠，握玩以為榮，改予振旅凯，含毫備勒銘，梁萧子雲赠海法師還甑山詩曰：直心好丘壑，偏悅幽栖人，忽聞甑山旅，萬里自相親，泬寥晚霖霁，重叠晴雲新，秋至蝉鳴柳，風高露起尘，動予憶山思，惆怅惜荷巾。","sortOrder":99},
  {"id":"s_work_nvlt_31_100","chapterId":"ch_work_nvlt_31","text":"又寒夜直坊憶袁三公詩曰：滴滴雨鳴階，愔愔茲夜靜，風落宣猷树，寒凋承光屏，高帷獨晓垂，華燭夜空冷，所思不相見，方知寒漏永。","sortOrder":100},
  {"id":"s_work_nvlt_31_101","chapterId":"ch_work_nvlt_31","text":"又東郊望春詶王建安俊晚遊詩曰：金塘绿泉滿，上園梨蕊落，蛱蝶恋殘花，黃湋對妖萼，芳菲滿郊甸，惠氣生蘭薄，子家冠蓋里，我馆幽栖郭，绿楊垂長溪，便桥限清洛，相去能幾許，一水終疏索。","sortOrder":101},
  {"id":"s_work_nvlt_31_102","chapterId":"ch_work_nvlt_31","text":"梁柳惲赠吳筠詩曰：寒雲晦沧洲，奔潮溢南浦，相思白露亭，永望秋風渚，心知別路長，誰謂若燕楚，關候日遼絕，如何附行旅，原作野飛鳥，飄然自輕舉。","sortOrder":102},
  {"id":"s_work_nvlt_31_103","chapterId":"ch_work_nvlt_31","text":"又赠吳筠詩曰：山桃落晚紅，野蕨开初紫，雲日自清明，蘋芷齊靃靡，離念已鬱陶，物華复如此。","sortOrder":103},
  {"id":"s_work_nvlt_31_104","chapterId":"ch_work_nvlt_31","text":"又赠吳筠詩曰：遠遊濟伊洛，秣馬度清漳，邯鄲饒美女，艳色含春芳，鼓瑟未成曲，跕屣复翱翔，我本遊客子，情愛在淮陽，知誰新不樂，念舊苦人傷。","sortOrder":104},
  {"id":"s_work_nvlt_31_105","chapterId":"ch_work_nvlt_31","text":"又赠吳筠詩曰：秋風度關隴，楚客奏歸音，飒飒避霜葉，離離出塞禽。","sortOrder":105},
  {"id":"s_work_nvlt_31_106","chapterId":"ch_work_nvlt_31","text":"梁何遜落日赠范岫詩曰：緣溝绿草蔓，扶援雜花舒，輕煙澹柳色，重霞掩日餘，遙遙長路晚，寂寂行人疏。","sortOrder":106},
  {"id":"s_work_nvlt_31_107","chapterId":"ch_work_nvlt_31","text":"又日夕望江赠魚司馬詩曰：湓城帶湓水，湓水萦如帶，日夕望高樓，耿耿青雲外，城中多宴賞，絲竹常繁會，管聲已流悅，絃聲复凄切，歌黛惨如愁，舞腰疑欲絕，仲秋黃葉下，長風正骚屑，早雁出雲歸，故燕辭簷別，晝悲在異縣，夜夢還洛汭，洛汭何悠悠，起望登西樓，的的帆向浦，团团日隱洲，誰能一羽化，輕舉逐飛浮。","sortOrder":107},
  {"id":"s_work_nvlt_31_108","chapterId":"ch_work_nvlt_31","text":"梁吳筠赠周興嗣詩曰：昔賢當路者，聲名振華夏，朱輪玳瑁牛，紫鞚連錢馬，朝花舞風中，夜月窥窗下，想君貴易朋，居然應見舍。","sortOrder":108},
  {"id":"s_work_nvlt_31_109","chapterId":"ch_work_nvlt_31","text":"又入蘭台赠王治書僧孺詩曰：故人楊子雲，校書麟閣下，寂寞少交遊，紛纶富文雅，予本隴西使，寓居洛陽社，相思非不深，行行避驄馬。","sortOrder":109},
  {"id":"s_work_nvlt_31_110","chapterId":"ch_work_nvlt_31","text":"又答柳惲詩曰：閒房肅已靜，落月有餘暉，寒虫隱壁思，秋蛾繞燭飛，絕雲斷更合，離禽去复歸，佳人今何在，迢遞江之沂，一為別鶴弄，千里淚沾衣。","sortOrder":110},
  {"id":"s_work_nvlt_31_111","chapterId":"ch_work_nvlt_31","text":"又赠任黃門詩曰：相如體英彦，左右生容暉，已紆漢帝組，复解梁王衣，經過雲母扇，出入千門扉，連洲茂芳社，長山鬱翠微，欲言終未敢，徒然獨依依。","sortOrder":111},
  {"id":"s_work_nvlt_31_112","chapterId":"ch_work_nvlt_31","text":"又詶郭臨丞詩曰：聞君立名義，我亦倦晨征，馬在城上蹀，［原作堞，據冯校本改。］劍自腰中鳴，白日遼川暗，黃尘垅坻驚，原君但衔酒，深知有素誠。","sortOrder":112},
  {"id":"s_work_nvlt_31_113","chapterId":"ch_work_nvlt_31","text":"又詶聞人侍郎詩曰：怅然心不樂，萬里向悠悠，陵潮憩枉渚，泊暮遵江州，君住青門上，我發霸陵頭，相思自有處，春風明月樓。","sortOrder":113},
  {"id":"s_work_nvlt_31_114","chapterId":"ch_work_nvlt_31","text":"又詣周承不值因赠此詩曰：竹枝任風轉，蘭心逐風卷，青雲葉上团，白露花中泫，聞君入綺疏，聊寄錦中書，一隨平原客，寧憶豫章徐。","sortOrder":114},
  {"id":"s_work_nvlt_31_115","chapterId":"ch_work_nvlt_31","text":"又遙赠周承詩曰：巨石亂天崖，雜树鬱參差，伯魚留蜀郡，長房還葛陂，練練波中月，亭亭雲上枝，高岑蔽人者，無處得相知。","sortOrder":115},
  {"id":"s_work_nvlt_31_116","chapterId":"ch_work_nvlt_31","text":"又周承未還重赠詩曰：石渠阒無人，子雲今何在，顧望獨凝忧，衔杯竟誰待，散雪逐吹寒，蓬姿霜雪采，甘泉無竹花，鵷雏欲還海。","sortOrder":116},
  {"id":"s_work_nvlt_31_117","chapterId":"ch_work_nvlt_31","text":"隋江總遇長安使寄裴尚書詩曰：傳聞令［文苑英華二百四十七作合，此訛。］浦葉，遠向洛陽飛，北風尚嘶馬，南冠獨不歸，去雲目徒送，離琴手自揮，征蓬失處所，春草屢芳菲，太息關山月，風尘客子衣。","sortOrder":117},
  {"id":"s_work_nvlt_31_118","chapterId":"ch_work_nvlt_31","text":"【賦】梁劭陵王赠言賦曰：張雲麾問望之美，作牧南蕃，維舟江漢，留連飲餞，發邁有期，會面無日，依依別袂，恨恨江幹，古人赠別以言，聊為赠言賦曰：昔人有感於知己，深情投分，如斯已矣，相知势利之間，實君子之所鄙，靜言神交之际，亦難得而具美，豈直鮮其令終，曾自聞其善始，日逾久而益敬，蓋惟一人者爾，語同志而好合，谅今古之皆然，荀讬御而自說，徐因刍而請前，况英聲與茂實，乃絕後而光先，似臨潭而鏡對，若披霧而睹天，钦愛顧之罔己，良佩服之在旃，資淑美之上才，超群雄而獨峻，德既深於萬頃，牆有高乎數仞，思若神而泉涌，文如華而玉振，伊薄軀之固陋，谬攝官於夏汭，知美錦之難裁，處棼絲而易結，幸中途而遘止，仰旌旆之踟蹰，似德星之東邁，類祥雲之西徂，亟留連於河渚，或終宴於城隅，賞既延於賓友，懽亦洽於仆夫，嗟灰琯之易逝，慨離袂之雲促，惜日車之不駐，恨流影之難續，觀善誘而不倦，餐好音而未足，佇浮雲之可寄，原無比乎金玉。","sortOrder":118},
  {"id":"s_work_nvlt_31_119","chapterId":"ch_work_nvlt_31","text":"梁張缵懷音賦併序曰：西平劭陵王，以親賢作蕃夏首，下走叨竊時命，驅傳湘羅，久讬下風，素蒙淑顧，及涂經鄢郢，淹泊累旬，君王彈隨珠於千仞，乃貽之以麗則，詩雲懷我好音，敢為懷音賦雲爾，伊宗周之令望，巡召南而述職，襟帶郧夏之乡，宣條江漢之域，服詩書於懷袖，抱仁義於焜臆，總九德以栖身，橫四溟而撫翼，循微躬之末跡，谬馳傳於衡嶷，由洞庭而左轉，指酃醴而為期，仰芳尘於夏汭，路將近而弥滋，棹陵波以遄務，舟望浦而倦遲，自清光之末覯，逾一紀以歷茲，敢凭情於往昔，逢君恩之未遺，陪桂苑之良遊，接蘭台之高會，既醉酒以飽德，亦傾羞而缓帶，感平原之愛客，傷歧路之難留，恋西園之餘賞，泣南浦之徂舟，結煩言於將赠，情有重乎琳球，顧龍門其不見，過夏首而西浮，申服義之未沫，長寄言於還郵。","sortOrder":119},
  {"id":"s_work_nvlt_31_120","chapterId":"ch_work_nvlt_31","text":"梁陆倕感知己賦赠任昉曰：夜申旦而不寐，獨匡坐而怨咨，命仆夫而夙駕，指南馆而為期，學窮書府，文究辭林，既耳聞而存口。又目見而登心，似臨淄之借書，類東武之飛翰，軫工遲於長卿，逾巧速於王粲，固乃度平子而越孟堅，何論孔璋而與公幹，或欲涉其涯涘，求其界畔，則浩浩淃々，彪彪涆々，譬長鋏於削中，若龍淵與蜀漢，濟濟冠蓋，祁祁俊逸，有竊風以味道，鹹交臂而屈膝，或望路以窥門，罕升堂而入室，彼春蘭及秋菊，尚無絕於眾芳，矧重仁與袭義，信遼遼兮未央，言追意而不逮，辭欲書而复忘，竊仰高而希骥，忽脂車而秣馬，既一顧之我隆，亦東壁之餘假，似延州之如舊，同伯喈之倒屣，附蒼蠅於骥尾，讬明鏡於朝光，謂虛無而為有，布籍甚於遊扬，於是柔條飒其成劲，白露变而為霜，歲忽忽而遒盡，忧與愛兮未忘，聚落茎於虛室，聽羁雀於枯楊，忳鬱悒其誰語，獨撫抱而增傷，讬異人以蠲忧，類其文而愈疾，索黃琼之寄居，造安仁之狹室，車出門其已歡，無論衔杯與促膝，譬邹子之吟松，故未寒而能栗，徒納壤以作高，陋吞舟而為罔，值墨子之愛兼，逢太丘之道廣，陪九萬以齊征，激三千而同上，識公沙於杵臼，拔孝相於無名，非夫人之為惑，孰雲感於餘情，指北芒以作誓，期鬱鬱於佳城。","sortOrder":120},
  {"id":"s_work_nvlt_31_121","chapterId":"ch_work_nvlt_31","text":"梁任昉答陆倕感知己賦曰：原知己之時義，故相知之信然，乃貪廉之異貫，奈勇怯之相懸，貪在物而成累，怯在我而可甄，既自得於為御。又甘心於執鞭，矧相知其如此，獨攬涕而潺湲，雖有望於己知，更非謂其知己，信伟人之世篤，本侯服於陆卿，緬風流與道素，袭袞衣與繡裳，逮伊人而世載，併三駿而龍光，過龍津而一息，望鳳條而載翔，彼白玉之雖絜，此幽蘭之信芳，思在物之取譬，非升斛而能量，匹方峙於東嶽，比凝厲於秋霜，不一飯以忘過，每三錢以投渭，匪蒙袂之敢嗟，豈溝壑之能衣，既蘊籍其有餘。又淡然而無味，得意同乎卷懷，违方似乎仗氣，類平叔而靡雕，似子台而不朴，冠眾善而胎操，綜群言而名學。折高戴於後台，異邹顏乎董幄，探三詩於河間，訪九師於淮曲，術兼口傳之書，藝廣铿锵之樂，時坐睡而懸梁，裁據梧而錐幄，唯忘年之陆子，定一遇於班荆，餘獲田蘇之价，爾得海上之名，信落魄而無產，終長勤於短生，飢虛表於徐步，逃责顯於疾行，子比我於叔則。又方餘於耀卿，心照情交，流言靡惑，萬類闇求，千里懸渴，言象可废，筌蹄自默，居非連棟，行待舟車，冬夜不長，夏日靡餘，肴核非餌，絲竹豈娱，我未舍駕，子已回舆，中飲相顧，怅然動色，邦壤雖殊，離會難测，存異山陽之居，没非要離之侧，以膠投漆中，離娄豈能識。","sortOrder":121},
  {"id":"s_work_nvlt_31_122","chapterId":"ch_work_nvlt_31","text":"【書】後漢崔瑗與葛元甫書曰：今遣奉書，錢千為贽，併送許子十卷，貧不及素，但以紙耳。","sortOrder":122},
  {"id":"s_work_nvlt_31_123","chapterId":"ch_work_nvlt_31","text":"後漢馬融與窦伯向書曰：孟陵奴來，賜書，見手跡，歡喜何量，次於面也，書雖兩紙，紙八行，行七字，七八五十六字，百一十二言耳，後漢延篤答張奐書曰：惟別三年，夢想言念，何日有违，伯英來，惠書盈四紙，讀之三复，喜不可言。","sortOrder":123},
  {"id":"s_work_nvlt_31_124","chapterId":"ch_work_nvlt_31","text":"後漢張奐與陰氏書曰：篤念既密，文章燦烂，名實相副，奉讀周旋，紙弊墨渝，不離於手。","sortOrder":124},
  {"id":"s_work_nvlt_31_125","chapterId":"ch_work_nvlt_31","text":"晉庾冰與王羲之書曰：得示，連紙一丈，致辭一千，祗增其叹耳，了無解於往懷。","sortOrder":125},
  {"id":"s_work_nvlt_31_126","chapterId":"ch_work_nvlt_31","text":"《藝文類聚》　唐·欧陽詢","sortOrder":126},
  {"id":"s_work_nvlt_32_1","chapterId":"ch_work_nvlt_32","text":"卷三十二人部十六","sortOrder":1},
  {"id":"s_work_nvlt_32_2","chapterId":"ch_work_nvlt_32","text":"○閨情","sortOrder":2},
  {"id":"s_work_nvlt_32_3","chapterId":"ch_work_nvlt_32","text":"◇閨情","sortOrder":3},
  {"id":"s_work_nvlt_32_4","chapterId":"ch_work_nvlt_32","text":"《毛詩》曰：自伯之東，首如飛蓬，豈無膏沐，誰適為容。","sortOrder":4},
  {"id":"s_work_nvlt_32_5","chapterId":"ch_work_nvlt_32","text":"又，角枕粲兮，錦衾烂兮，予美忘此，誰與獨旦。","sortOrder":5},
  {"id":"s_work_nvlt_32_6","chapterId":"ch_work_nvlt_32","text":"又，我徂東山，滔滔不歸，我來自東，零雨其濛，鸛鳴於垤，婦叹於室。","sortOrder":6},
  {"id":"s_work_nvlt_32_7","chapterId":"ch_work_nvlt_32","text":"又，采绿，刺怨曠也，幽王之時，多怨曠者，終朝采绿，不盈一匊，予發曲局，薄言歸沐，終朝采藍，不盈一襜，五日為期，六日不詹。","sortOrder":7},
  {"id":"s_work_nvlt_32_8","chapterId":"ch_work_nvlt_32","text":"又，靜女其姝，俟我於城隅，愛而不見，搔首踟蹰","sortOrder":8},
  {"id":"s_work_nvlt_32_9","chapterId":"ch_work_nvlt_32","text":"又，燕爾新婚，如兄如弟。","sortOrder":9},
  {"id":"s_work_nvlt_32_10","chapterId":"ch_work_nvlt_32","text":"又曰：未見君子，忧心忡忡，亦既見止，亦既覯止，我心則降。","sortOrder":10},
  {"id":"s_work_nvlt_32_11","chapterId":"ch_work_nvlt_32","text":"又，未見君子，忧心惙惙，亦既見止，亦既覯止，我心則悅。","sortOrder":11},
  {"id":"s_work_nvlt_32_12","chapterId":"ch_work_nvlt_32","text":"《左傳》：晉叔向曰：昔贾大夫惡，娶妻而美，三年不言不笑，御以如皋，射雉獲之，其妻始笑而言。","sortOrder":12},
  {"id":"s_work_nvlt_32_13","chapterId":"ch_work_nvlt_32","text":"又，晉文公謂季隗曰：待我二十五年不來而後嫁，季隗曰：我二十五年矣。又如是而嫁，則就木焉。","sortOrder":13},
  {"id":"s_work_nvlt_32_14","chapterId":"ch_work_nvlt_32","text":"《說苑》曰：齊王起九重之台，募國中能畫者，賜之錢，有敬君，居常飢寒，其妻妙色，敬君工畫台，貪賜畫台去家日久，思憶其妻，像向之而笑，傍人見以白王，王召問之，對曰：有妻如此，去家日久，心常念之，竊畫其像，以慰離心，不悟上聞。","sortOrder":14},
  {"id":"s_work_nvlt_32_15","chapterId":"ch_work_nvlt_32","text":"漢［漢下脱書字。］張敞為婦畫眉，帝知問之，敞曰：閨房之內，夫婦之私，有過此者。","sortOrder":15},
  {"id":"s_work_nvlt_32_16","chapterId":"ch_work_nvlt_32","text":"又，李夫人得幸武帝而卒，上怜悯焉，圖畫其像於甘泉宮，初李夫人病篤，上自臨候之，夫人蒙被謝曰：妾久寢病，形貌毀坏，不可以見帝，上曰：夫人病亦甚，殆將不起，一見我，屬讬王及兄弟，豈不快哉，夫人曰：尊官在帝，不在一見，上复言，欲必見之，夫人遂轉面向壁歔欷，上不悅而起，夫人姊妹讓之曰：獨不可一見上，屬讬兄弟耶，夫人曰：不見帝者，乃欲深讬兄弟也，夫以色事人者，色衰則愛弛，上所恋恋念我，以平生容貌也，今見我毀坏，顏色非昔，必且畏惡我，尚肯思复錄其兄弟哉。","sortOrder":16},
  {"id":"s_work_nvlt_32_17","chapterId":"ch_work_nvlt_32","text":"《風俗通》曰：有張伯偕仲偕兄弟，形貌絕相類，仲偕妻新妆竟，忽見伯偕，乃戲問曰：今日妆飾好不，伯偕應之曰：我伯偕也，妻乃趍避之，須臾。又見伯偕，猶以為仲偕，告雲，向大错誤，伯偕曰：我故伯偕也。","sortOrder":17},
  {"id":"s_work_nvlt_32_18","chapterId":"ch_work_nvlt_32","text":"《世說》曰：王浑妻鍾夫人，每嘗卿浑，浑曰：詎可爾，妻曰：怜愛卿，是以卿卿，我不卿卿，誰當卿卿。","sortOrder":18},
  {"id":"s_work_nvlt_32_19","chapterId":"ch_work_nvlt_32","text":"又曰：荀奉蒨妻曹氏，有艳色，妻常病熱，奉蒨乃出中庭取冷，還，以家［○世說惑溺篇作身。］熨之，妻亡人弔，不哭而神傷，無幾，奉蒨亦卒。","sortOrder":19},
  {"id":"s_work_nvlt_32_20","chapterId":"ch_work_nvlt_32","text":"又曰：孫楚妻亡，至祥，仍為詩以悼之，王武子見其文曰：未知文生於情，情生於文，見此使人增伉俪之重。","sortOrder":20},
  {"id":"s_work_nvlt_32_21","chapterId":"ch_work_nvlt_32","text":"湘川記曰：舜巡狩蒼梧而崩，三妃不從，思憶舜，以淚染竹，竹盡為班。","sortOrder":21},
  {"id":"s_work_nvlt_32_22","chapterId":"ch_work_nvlt_32","text":"【詩】古詩曰：青青河畔草，鬱鬱園中柳，盈盈樓上女，皎皎當窗牖，瓘瓘紅粉妆，纖纖出素手，昔為娼家女，今為荡子婦，荡子行不歸，空床難獨守。","sortOrder":22},
  {"id":"s_work_nvlt_32_23","chapterId":"ch_work_nvlt_32","text":"又曰：上山采蘪芜，下山逢故夫，長跪問故夫，新人复何如，新人雖雲好，未若故人姝，其色似相類，手爪不相如，新人從門入，故人從閤去，新人工織缣，故人工織素，織缣日一匹，織素五丈餘，持缣將比素，新人不如故。","sortOrder":23},
  {"id":"s_work_nvlt_32_24","chapterId":"ch_work_nvlt_32","text":"又曰：蘭若生春陽，涉冬猶盛滋，原言追昔愛，情款感四時，美人在雲端，天路隔無期。","sortOrder":24},
  {"id":"s_work_nvlt_32_25","chapterId":"ch_work_nvlt_32","text":"後漢焦仲卿妻劉氏，為姑所遣，時人傷之，作詩曰：孔雀東南飛，五里一徘徊，十三能織綺，十四學裁衣，十五彈箜篌，十六誦書詩，十七嫁為婦，心中常苦悲，君既為府史，守節情不移，雞鳴入機織，夜夜不得息，三日斷五疋，大人故言遲，非為織作遲，君家婦難為，妾有繡腰襦，葳蕤金縷光，紅羅複斗帳，四角垂香囊，交文象牙簟，宛轉素絲繩，鄙賤雖可薄，猶中迎後人。","sortOrder":25},
  {"id":"s_work_nvlt_32_26","chapterId":"ch_work_nvlt_32","text":"魏陳王曹植詩曰：攬衣出中閨，逍遙步兩楹，閒房何寂寥，绿草被階庭，空穴自生風，百鳥翩南征，春思安可忘，忧戚與君併，佳人在遠道，妾身单且茕，歡會難再遇，蘭芝不重榮，人皆弃舊愛，君豈若平生，寄松為女萝，依水如浮萍，赍身奉衿帶，朝夕不墮傾，傥終顧眄恩，永副我中情。","sortOrder":26},
  {"id":"s_work_nvlt_32_27","chapterId":"ch_work_nvlt_32","text":"又曰：明月照高樓，流光正徘徊，上有愁思婦，悲叹有餘哀，借問叹者誰，雲是客子妻，君行逾十年，孤妾常獨栖，君若清路尘，妾若濁水泥，浮沉各異势，會合何時諧，原為西南風，長遊［《文選》二十三作逝。］入君懷，君懷時不开，妾心將何依。","sortOrder":27},
  {"id":"s_work_nvlt_32_28","chapterId":"ch_work_nvlt_32","text":"又曰：西北有織婦，綺縞何繽紛，明晨秉機杼，日晏不成文，太息終長夜，悲嘯入青雲，妾身守空房，良人從行軍，自期三年歸，今已歷九春，孤鳥繞树翔，噭々鳴索群，原為南流景，馳光見我君。","sortOrder":28},
  {"id":"s_work_nvlt_32_29","chapterId":"ch_work_nvlt_32","text":"魏徐幹室思詩曰：浮雲何洋洋，原因通我辭，一逝不可歸，嘯歌久踟蹰，人離皆复會，我獨無反期，自君之出矣，明鏡开［玉台新詠一，作暗，疑當作閉。］不治，思君如流水，何有窮已時。","sortOrder":29},
  {"id":"s_work_nvlt_32_30","chapterId":"ch_work_nvlt_32","text":"晉潘嶽內顧詩曰：靜居懷所歡，登城望四泽，春草鬱青青，桑者何弈弈，芳林振丹榮，渌水激素石，初征冰未泮，忽焉振絺绤，漫漫三千里，迢迢遠行客，馳情恋朱顏，寸陰過盈尺，夜愁極清晨，朝悲終日夕，山川自悠永，原言良不獲，別嶺訴歸期，雲沉不可釋。","sortOrder":30},
  {"id":"s_work_nvlt_32_31","chapterId":"ch_work_nvlt_32","text":"晉陆機為陆思遠婦作詩曰：二合兆嘉偶，女子禮有行，絜己入德門，終遠母與兄，如何躭時寵，遊宦忘歸寧，雖為三載婦，顧景媿虛名，歲暮饒悲風，洞房涼且清，拊枕循薄质，非君誰見榮，離君多悲心，寤寐勞人情，敢忘桃李陋，侧想瑤與琼。又擬青青河畔草詩曰：靡靡江離草，熠烁生河侧，皎皎彼姝女，婀娜當軒織，粲粲娇容姿，灼灼美顏色，良人遊不歸，偏栖獨只翼，空房來悲風，中夜起叹息。","sortOrder":31},
  {"id":"s_work_nvlt_32_32","chapterId":"ch_work_nvlt_32","text":"又擬蘭若生春陽詩曰：嘉树生朝陽，凝想封其條，執心守時信，歲寒終不凋，美人何其曠，的的在雲霄。","sortOrder":32},
  {"id":"s_work_nvlt_32_33","chapterId":"ch_work_nvlt_32","text":"晉張華情詩曰：北方有佳人，端坐鼓鳴琴，終晨撫管絃，日夕不成音，忧來結不解，我思存所钦。","sortOrder":33},
  {"id":"s_work_nvlt_32_34","chapterId":"ch_work_nvlt_32","text":"又情詩曰：君居北海陽，妾在江南陰，懸貌極脩途，山川阻且深，承懽註隆愛，結分投所钦，衔恩守篤義，萬里讬微心。","sortOrder":34},
  {"id":"s_work_nvlt_32_35","chapterId":"ch_work_nvlt_32","text":"又詩曰：遊目四野外，逍遙獨延佇，蘭蕙緣清渠，繁華陰渌渚，佳人不在茲，取之欲誰與，巢居知寒風，穴處知陰雨，不曾遠別離，安知慕儔侣。","sortOrder":35},
  {"id":"s_work_nvlt_32_36","chapterId":"ch_work_nvlt_32","text":"宋孝武帝擬室［原訛空，據冯校本改。］思詩曰：自君之出矣，金翠闇無精，思君如日月，回還晝夜生，宋江夏劉義恭擬詩曰：自君之出矣，笥錦废不开，思君如清風，晓夜嘗徘徊。","sortOrder":36},
  {"id":"s_work_nvlt_32_37","chapterId":"ch_work_nvlt_32","text":"宋顏師伯擬詩曰：自君之出矣，芳帷低不舉，思君如回雪，流亂無端緒。","sortOrder":37},
  {"id":"s_work_nvlt_32_38","chapterId":"ch_work_nvlt_32","text":"齊王融秋胡詩曰：日月共為照，松筠俱以貞，佩紛甘自遠，結鏡待君明，且协金蘭好，方愉琴瑟情，佳人忽千里，空閨積思生。","sortOrder":38},
  {"id":"s_work_nvlt_32_39","chapterId":"ch_work_nvlt_32","text":"梁簡文帝詠人弃妾詩曰：昔時娇玉步，含羞花燭邊，豈言心愛斷，衔啼私自怜，但覺歡成愁，非關丑易妍，獨鵠罢中路，孤鸞死鏡前。","sortOrder":39},
  {"id":"s_work_nvlt_32_40","chapterId":"ch_work_nvlt_32","text":"又春宵詩曰：花树含春藂，羅帳夜長空，風聲隨筱韻，月色與池同，采箋徒自襞，無信往雲中。","sortOrder":40},
  {"id":"s_work_nvlt_32_41","chapterId":"ch_work_nvlt_32","text":"又晓思詩曰：晨禽爭學啭，朝花亂欲开，爐煙入斗帳，屏風隱鏡台，紅妆幾盡淚，荡子何當來。","sortOrder":41},
  {"id":"s_work_nvlt_32_42","chapterId":"ch_work_nvlt_32","text":"又冬晓詩曰：冬朝日照梁，含愁下前床，帷褰竹葉帶，鏡轉菱花光，會是無人覺，何用早紅妆。","sortOrder":42},
  {"id":"s_work_nvlt_32_43","chapterId":"ch_work_nvlt_32","text":"又秋閨夜思詩曰：非關長信別，詎是良人征，九重忽不見，萬恨滿心生，夕門掩魚鑰，宵床悲畫屏，回月臨階度，吟虫繞砌鳴，初霜實細葉，秋風吹亂螢，故妆猶累日，新衣裂［玉台新詠七作襞。］未成，欲知妾不寐，城外捣砧聲。","sortOrder":43},
  {"id":"s_work_nvlt_32_44","chapterId":"ch_work_nvlt_32","text":"又倡樓怨節詩曰：朝日斜來照戶，春鳥爭飛出林，片光片影皆麗，一聲一啭煎心，上林紛紛花落，淇水漠漠苔浮，年馳節流易盡，何為忍意含羞。","sortOrder":44},
  {"id":"s_work_nvlt_32_45","chapterId":"ch_work_nvlt_32","text":"又春別詩曰：別觀蒲萄帶實垂，江南豆蔻生連枝，無情無意又如此，有心有恨徒別離。","sortOrder":45},
  {"id":"s_work_nvlt_32_46","chapterId":"ch_work_nvlt_32","text":"又詩曰：可怜淮水去來潮，春隄楊柳覆河桥，淚痕未燥詎終朝，行聞玉佩已相要。","sortOrder":46},
  {"id":"s_work_nvlt_32_47","chapterId":"ch_work_nvlt_32","text":"又詩曰：桃紅李白若朝妆，羞持憔悴比新芳，不惜暫住君前死，愁無西國更生香。","sortOrder":47},
  {"id":"s_work_nvlt_32_48","chapterId":"ch_work_nvlt_32","text":"梁元帝寒閨詩曰：乌鵲夜南飛，良人行未歸，池水浮明月，寒風送捣衣，原織回文錦，因君寄武威。","sortOrder":48},
  {"id":"s_work_nvlt_32_49","chapterId":"ch_work_nvlt_32","text":"又閨怨詩曰：荡子從遊宦，思妾守房栊，尘鏡朝朝掩，寒床夜夜空，若非有懽悅，何事久西東，知人相望否，淚盡夢啼中。","sortOrder":49},
  {"id":"s_work_nvlt_32_50","chapterId":"ch_work_nvlt_32","text":"又代舊姬有怨詩曰：寧為萬里隔，乍作死生離，那堪眼前見，故愛逐新移，未展春花落，遽被涼風吹，怨黛舒還斂，啼紅拭复垂，誰能巧為賦，黃金妾不赀。","sortOrder":50},
  {"id":"s_work_nvlt_32_51","chapterId":"ch_work_nvlt_32","text":"又別詩曰：崑明夜月光如練，上林朝花色如霰，花朝月夜動春心，誰忍相思今不見。","sortOrder":51},
  {"id":"s_work_nvlt_32_52","chapterId":"ch_work_nvlt_32","text":"又詩曰：试看機上蛟龍錦，還瞻庭里合歡枝，映日通風影珠幔，飄花拂葉度金池，不聞離人當重合，唯悲合罢會成離。","sortOrder":52},
  {"id":"s_work_nvlt_32_53","chapterId":"ch_work_nvlt_32","text":"又詩曰：門前楊柳亂如絲，直置佳人不自持，適言新作裂紈詩，誰悟今成織素辭。","sortOrder":53},
  {"id":"s_work_nvlt_32_54","chapterId":"ch_work_nvlt_32","text":"又詩曰：日暮徙倚渭桥西，正見流月與雲齊，若使月光無近遠，應照離人今暝啼。","sortOrder":54},
  {"id":"s_work_nvlt_32_55","chapterId":"ch_work_nvlt_32","text":"又詩曰：別罢花枝不共攀，別後書信不相關，欲賝行人寄消息，衣常潮水暝應還。","sortOrder":55},
  {"id":"s_work_nvlt_32_56","chapterId":"ch_work_nvlt_32","text":"又詩曰：三月桃花合面脂，五月新油好煎泽，莫复臨時不寄人，漫道江中無估客。","sortOrder":56},
  {"id":"s_work_nvlt_32_57","chapterId":"ch_work_nvlt_32","text":"梁武陵王萧妃夜夢詩曰：昨夜夢君歸，賤妾下鳴機，極知意氣薄，不著去時衣，故言如夢里，賴得雁書飛。","sortOrder":57},
  {"id":"s_work_nvlt_32_58","chapterId":"ch_work_nvlt_32","text":"梁范雲擬古詩曰：自君之出矣，羅帳咽秋風，思君如蔓草，連延不可窮。","sortOrder":58},
  {"id":"s_work_nvlt_32_59","chapterId":"ch_work_nvlt_32","text":"梁王僧孺為何遜舊姬擬上山采蘼芜詩曰：出戶望蘭薰，褰帘正逢君，斂容裁一訪，新人詎可聞，新人含笑近，故人含笑隱，妾意在寒松，君心逐朝槿。","sortOrder":59},
  {"id":"s_work_nvlt_32_60","chapterId":"ch_work_nvlt_32","text":"又為姬人怨詩曰：自知心里恨，還向影中羞，回持昔慊慊，变作今悠悠，還君與妾扇，歸妾與君裘，絃斷猶可續，心去最難留。","sortOrder":60},
  {"id":"s_work_nvlt_32_61","chapterId":"ch_work_nvlt_32","text":"又為人傷近而不見詩曰：嬴女鳳皇樓，漢姬柏梁殿，詎過仙將死，音容不可見，獨我一心人，同乡不異縣，異縣不成隔，同乡更脈脈，脈脈如牛女，□由［○冯校本上字缺同，下作由，按玉台新詠六，本句作無妨年一語，疑此當作無由寄一語。］寄一語。","sortOrder":61},
  {"id":"s_work_nvlt_32_62","chapterId":"ch_work_nvlt_32","text":"又作寵姬詩曰：及君高堂還，值妾妍妆罢，曲房褰錦帳，回廊步珠屣，玉釵時可掛，羅襦詎難解，再顧連城易，一眄千金買。","sortOrder":62},
  {"id":"s_work_nvlt_32_63","chapterId":"ch_work_nvlt_32","text":"又詠姬人詩曰：窈窕守容華，但歌有情曲，轉眄非無以，斜眉幸相屬，不减許飛琼，多勝劉璧玉，何因送款款，半飲杯中醁。","sortOrder":63},
  {"id":"s_work_nvlt_32_64","chapterId":"ch_work_nvlt_32","text":"梁萧子顯春別詩曰：翻湋度燕双比翼，楊柳千條共一色，但看陌上携手歸，誰能對此空中憶。又詩曰：幽宮積草自芳菲，黃鳥芳树情相依，爭風競日常聞响，重花叠葉不通飛，當知此時動妾思，蹔使罢袂拂臣衣。","sortOrder":64},
  {"id":"s_work_nvlt_32_65","chapterId":"ch_work_nvlt_32","text":"又詩曰：衔悲攬涕別心知，桃花李色任風吹，本如人心不似树，何意人別似花離，梁劉缓閨怨詩曰：別後春池異，荷盡欲生冰，箱中翦刀冷，台上面脂凝，纖腰轉無力，寒衣怨不勝。","sortOrder":65},
  {"id":"s_work_nvlt_32_66","chapterId":"ch_work_nvlt_32","text":"又秋閨詩曰：樓上起秋風，絕望秋閨中，燭溜花行滿，香然奁欲空，徒交兩行淚，俱浮妆上紅¨","sortOrder":66},
  {"id":"s_work_nvlt_32_67","chapterId":"ch_work_nvlt_32","text":"梁吳筠閨怨詩曰：胡笳屢凄斷，征蓬未肯唤，娈坐江之介，君戍小長安，相去三千里，參差書信難，四時無人見，誰复重羅紈。","sortOrder":67},
  {"id":"s_work_nvlt_32_68","chapterId":"ch_work_nvlt_32","text":"又閨怨詩曰：春草可攬結，妾心正斷絕，绿鬢愁中改，紅顏啼里滅，非獨淚如珠，亦見珠成血，原為飛鵲鏡，翩翩照離別。","sortOrder":68},
  {"id":"s_work_nvlt_32_69","chapterId":"ch_work_nvlt_32","text":"又古意詩曰：賤妾思不堪，采桑渭城南，帶减連枝繡，發亂鳳皇簪，花舞依長薄，鹅飛愛渌潭，無由報君此，流涕向春蠶。","sortOrder":69},
  {"id":"s_work_nvlt_32_70","chapterId":"ch_work_nvlt_32","text":"梁庾肩吾春宵詩曰：征人別來久，年芳复臨牖，燭下夜縫衣，春寒偏著手，原及歸飛雁，因書向高柳。","sortOrder":70},
  {"id":"s_work_nvlt_32_71","chapterId":"ch_work_nvlt_32","text":"又冬晓詩曰：鄰雞聲已傳，愁人競不眠，月光侵曙後，霜明落晓前，萦鬟起照鏡，誰忍椠花钿。","sortOrder":71},
  {"id":"s_work_nvlt_32_72","chapterId":"ch_work_nvlt_32","text":"梁劉孝綽春宵詩曰：春宵猶自長，春心非一傷，月帶園樓影，風飄花树香，誰能對双燕，暝暝守空床。","sortOrder":72},
  {"id":"s_work_nvlt_32_73","chapterId":"ch_work_nvlt_32","text":"又冬晓詩曰：冬晓風正寒，偏念客衣单，臨妆罢鉛黛，含淚翦綾紈，寄語龍城下，詎知書信難。","sortOrder":73},
  {"id":"s_work_nvlt_32_74","chapterId":"ch_work_nvlt_32","text":"又古意詩曰：燕趙多佳麗，白日照紅妆，荡子十年別，羅衣双帶長，春樓怨難守，玉階悲自傷，對此歸飛燕，衔泥繞曲房，差池入綺幕，上下傍雕梁，故居猶尚爾，故人安可忘，徒然枕枕席，誰與同衣裳，空使蘭膏夜，蜅蜅對繁霜。","sortOrder":74},
  {"id":"s_work_nvlt_32_75","chapterId":"ch_work_nvlt_32","text":"梁何遜閨怨詩曰：晓河没高棟，斜月半空庭，窗中度落葉，帘外隔飛螢，含情下翠帳，掩涕閉金屏，旨［玉台新詠五作昔。］期今未反，春草寒复青，思君無轉易，何異北辰星。","sortOrder":75},
  {"id":"s_work_nvlt_32_76","chapterId":"ch_work_nvlt_32","text":"又詠倡婦詩曰：暧暧高樓暮，華燭帳前明，羅帷雀釵影，寶瑟鳳雏聲，夜花枝上發，新月霧中生，誰念當窗牖，相望獨盈盈。","sortOrder":76},
  {"id":"s_work_nvlt_32_77","chapterId":"ch_work_nvlt_32","text":"梁費昶長門怨詩曰：向夕千悲起，百恨何嗟及，愁思且歸床，羅襦方掩泣，絳树搖風软，黃鳥弄聲急，金屋貯娇時，不言君不入。","sortOrder":77},
  {"id":"s_work_nvlt_32_78","chapterId":"ch_work_nvlt_32","text":"梁劉孝儀閨怨詩曰：本無金屋寵，長作玉階悲，一乖西北麗，寧复城南期，永巷愁無歇，應門閉有時，空勞織素巧，徒為团扇詞，匡床終不共，何由橫自私。","sortOrder":78},
  {"id":"s_work_nvlt_32_79","chapterId":"ch_work_nvlt_32","text":"梁劉孝威春宵詩曰：花开人不歸，節暖衣須变，回釵掛反镮，拭淚繩春線，今夜月輪圓，胡兵必應戰。","sortOrder":79},
  {"id":"s_work_nvlt_32_80","chapterId":"ch_work_nvlt_32","text":"又冬晓詩曰：妾家邊洛城，慣識晓鍾聲，鍾聲猶未盡，漢使報應行，天寒砚水冻，心悲書不成。","sortOrder":80},
  {"id":"s_work_nvlt_32_81","chapterId":"ch_work_nvlt_32","text":"梁劉孝先春宵詩曰：夜樓明月絃，露下百花鮮，情多意不設，啼罢未歸眠，敦煌定若遠，一信動經年。","sortOrder":81},
  {"id":"s_work_nvlt_32_82","chapterId":"ch_work_nvlt_32","text":"又冬晓詩曰：晨霞影翠帷，思婦織霜絲，經寒牵杼涩，钏冷調梭遲，乍废倡樓粉，貪赴遠人期，梁王筠閨情詩曰：月出宵將半，星流晓未央，空閨易成响，虛室自生光，娇羞悅人夢，猶言君在傍。","sortOrder":82},
  {"id":"s_work_nvlt_32_83","chapterId":"ch_work_nvlt_32","text":"又向晓閨情詩曰：北斗行欲没，東方稍已晞，晨雞初下栖，晓露上霑衣，衾裯徒有設，信誓果相违，詎忍开朝鏡，羞恨掩空扉。","sortOrder":83},
  {"id":"s_work_nvlt_32_84","chapterId":"ch_work_nvlt_32","text":"又春遊詩曰：藂蘭已飛蝶，楊柳半藏鴉，物色相煎荡，微步出東家，既同翡翠翼，复如桃李花，欲以千金笑，回君流水車。","sortOrder":84},
  {"id":"s_work_nvlt_32_85","chapterId":"ch_work_nvlt_32","text":"梁陆罩詩曰：自怜斷帶日，偏恨分釵時，留步惜餘影，含意結愁眉，徒知今異昔，空使怨成思，欲以別離意，獨向蘼芜悲。","sortOrder":85},
  {"id":"s_work_nvlt_32_86","chapterId":"ch_work_nvlt_32","text":"梁鮑泉寒閨詩曰：行人消息斷，空閨靜复寒，風急朝機燥，鏡暗晚妆難，從來腰自小，衣帶就中宽。","sortOrder":86},
  {"id":"s_work_nvlt_32_87","chapterId":"ch_work_nvlt_32","text":"梁邓铿閨怨詩曰：暫別猶添恨，何忍別經時，藂桂頻銷葉，庭树幾攀枝，君言妾貌改，妾畏君心移，終須一相見，併得兩心知。","sortOrder":87},
  {"id":"s_work_nvlt_32_88","chapterId":"ch_work_nvlt_32","text":"又月夜閨中詩曰：閨中日已暮，樓上月初華，树陰緣砌上，窗影向床斜，开屏寫密書，卷帳照垂花，誰能當此夕，獨處類倡家，梁萧子暉春宵詩曰：夜夜妾偏栖，百花含露低，虫聲繞春岸，月色思空閨，倩語長安驿，辛苦寄遼西。又冬晓詩曰：步欄光欲通，曙鳥向西東，燭滅傳餘氣，帷香开晓風，繁花無處盡，還銷寒鏡中。","sortOrder":88},
  {"id":"s_work_nvlt_32_89","chapterId":"ch_work_nvlt_32","text":"梁劉邈秋閨詩曰：螢飛綺窗外，妾思霍將軍，燈前量獸錦，簷下織花紋，墜露如輕雨，長河似薄雲，秋還百种事，衣成不暇熏。","sortOrder":89},
  {"id":"s_work_nvlt_32_90","chapterId":"ch_work_nvlt_32","text":"梁萧子雲春思詩曰：春風荡羅帳，餘花落鏡奁，池荷正卷葉，庭柳复垂簷，竹柏君自改，团扇妾方嫌，詎能怜故素，終為泣新缣。","sortOrder":90},
  {"id":"s_work_nvlt_32_91","chapterId":"ch_work_nvlt_32","text":"梁何思澄古意詩曰：故交不可忘，猶如蘭桂芳，新知雖可悅，不異茱萸香，妾有鳳皇曲，非無陌上桑，荐君君不御，抱瑟自悲涼。","sortOrder":91},
  {"id":"s_work_nvlt_32_92","chapterId":"ch_work_nvlt_32","text":"梁朱越賦得荡子行未歸詩曰：坐樓愁出望，息意不思春，無奈園中柳，寒時已報人，捉梳羞理鬢，挑朱懶向唇，何當上路晚，風吹還騎尘。","sortOrder":92},
  {"id":"s_work_nvlt_32_93","chapterId":"ch_work_nvlt_32","text":"陳陰铿南征閨怨詩曰：湘水舊言深，征客理難尋，獨愁無處道，長啼不自禁，作人憎解佩，從來懶聽音，唯當有夜鵲，南飛似妾心。","sortOrder":93},
  {"id":"s_work_nvlt_32_94","chapterId":"ch_work_nvlt_32","text":"又秋閨怨詩曰：獨眠雖已慣，秋來只自愁，火籠恒暖腳，行障镇床頭，眉含黛俱斂，啼將粉共流，誰能無限別，唯守一空樓。","sortOrder":94},
  {"id":"s_work_nvlt_32_95","chapterId":"ch_work_nvlt_32","text":"陳李爽山家閨怨詩曰：山中多早梅，荆扉達曙开，竹巾君自折，荷衣誰為裁，行雲無處所，人住在陽台。","sortOrder":95},
  {"id":"s_work_nvlt_32_96","chapterId":"ch_work_nvlt_32","text":"陳張正見山家閨怨詩曰：王孫春好遊，雲鬢不勝愁，離鸿暫罢曲，別路已經秋，山中桂花晚，勿為俗人留。","sortOrder":96},
  {"id":"s_work_nvlt_32_97","chapterId":"ch_work_nvlt_32","text":"又賦得佳期競不歸詩曰：良人萬里向河源，倡婦三秋思柳園，路遠寄詩空織錦，宵長夢反欲驚魂，飛蛾屢繞帷前燭，衰草還侵階上玉，衔啼拂鏡不成妆，促柱繁絃還亂曲，時忿年移競不歸，偏憎信急夜縫衣，流螢映月明空帳，疏葉從風入斷機，自對孤鸞向影絕，終無一雁帶書飛。","sortOrder":97},
  {"id":"s_work_nvlt_32_98","chapterId":"ch_work_nvlt_32","text":"陳徐湛賦得班去趙姬升詩曰：班姬與飛燕，俱侍漢王宮，不意恩情歇，偏將衰草同，香飛金輦外，苔上玉階中，今日悲团扇，非是為秋風。","sortOrder":98},
  {"id":"s_work_nvlt_32_99","chapterId":"ch_work_nvlt_32","text":"隋江總賦得空閨怨詩曰：荡妻怨獨守，盧姬傷獨居，瑟上調絃落，機中織素餘，自羞淚無燥，翻覺夢成虛，复嗟長信閤，寂寂往來疏。","sortOrder":99},
  {"id":"s_work_nvlt_32_100","chapterId":"ch_work_nvlt_32","text":"又為姬人怨服散詩曰：天寒海水慣相知，空床明月不相宜，庭中芳桂憔悴葉，井上疏桐零落枝，寒燈作花羞夜短，霜雁多情恒結伴，非為隴水望秦川，直置思君腸自斷，薄命夫婿好神仙，逆愁高飛向紫煙，金丹欲成猶百煉，玉酒新熟幾千年，妾家邯鄲好輕薄，特忿仙童一丸藥，自悲行處绿苔生，何悟啼多紅粉落，莫輕小婦狎春風，羅襪也得步河宮，雲車欲駕應相待，羽衣未去幸須同，不學萧史還樓上，會逐恒娥戲月中。","sortOrder":100},
  {"id":"s_work_nvlt_32_101","chapterId":"ch_work_nvlt_32","text":"又閨怨詩曰：寂寂青樓大道邊，紛紛白雪綺窗前，池上鴛鴦不獨自，帳中蘇合還空然，屏風有意障明月，鐙火無情照獨眠，遼西水冻春應少，蓟北鸿來路幾千，原君關山及早度，念妾桃李片時妍。","sortOrder":101},
  {"id":"s_work_nvlt_32_102","chapterId":"ch_work_nvlt_32","text":"又詩曰：蜘蛛作絲滿帳中，芳草結葉當行路，紅脸脈脈一生啼，黃鳥飛飛有時度，故人雖故昔經新，新人雖新复應故。","sortOrder":102},
  {"id":"s_work_nvlt_32_103","chapterId":"ch_work_nvlt_32","text":"【賦】梁元帝荡婦秋思賦曰：荡子之別十年，倡婦之居自怜，登樓一望，唯見遠树含煙，平原如此，不知道路幾千，天與水兮相逼，山與雲兮共色，山則蒼蒼入漢，水則涓涓不测，誰复堪見鳥飛，悲鳴只翼，秋何月而不清，月何秋而不明，况乃倡樓荡婦，對此傷情，於時露萎庭蕙，霜封階砌，坐视帶長，轉看腰細，重以秋水文波，秋雲似羅，日黯黯而將暮，風骚骚而渡河，妾怨回文之錦，君思出塞之歌，相思相望，路遠如何，鬢飄蓬而漸亂，心懷愁而轉叹，愁萦翠眉斂，啼多紅粉漫，已矣哉，秋風起兮秋葉飛，春花落兮春日暉，春日遲遲猶可至，客子行行終不歸。","sortOrder":103},
  {"id":"s_work_nvlt_32_104","chapterId":"ch_work_nvlt_32","text":"梁江淹倡婦自悲賦曰：日自趙東，來舞漢宮，瑤席金陳，桂枝娇春，素壁翠樓，明月使秋，歌聲忽散，倡人复愁，君王更衣，露色未晞，侍青鑾以雲徙，夹丹輦以霞飛，原南山之無隙，指寿陵以同歸，俄而绿衣坐奋，白華臥進，屑骨不怜，抵金誰吝，九重以閉，高門自芜，青苔積兮銀閤涩，網羅生兮玉梯虛，度九冬而廓處，經十秋而分居，傷營魄之已盡，畏松柏之無餘，去柏梁以掩袂，出桂柱而斂眉，视朱殿以再暮，撫嫔華而一疑。","sortOrder":104},
  {"id":"s_work_nvlt_32_105","chapterId":"ch_work_nvlt_32","text":"周庾信荡子賦曰：荡子辛苦逐征行，直守長城千里城，隴水恒冰合，關山唯明月，况复空床起怨，倡婦生離，紗窗獨掩，羅帳長垂，新筝不弄，長笛羞吹，常年桂苑，昔日蘭閨，羅敷總發，弄玉初笄，新歌子夜，舊舞前溪，別後關情無复情，離前明鏡不須明，合歡無信寄，回紋織未成，遊尘滿床不用拂，細草橫階隨意生，前日漢使著章台，聞道夫婿定應回，手巾還欲燥，愁眉即剩开，逆想行人至，迎前含笑來。","sortOrder":105},
  {"id":"s_work_nvlt_32_106","chapterId":"ch_work_nvlt_32","text":"【書】後漢秦嘉與妻書曰：不能養志，當給郡使，隨俗順時，黾勉當去，知所苦故爾，未有瘳損，想念悒悒，勞心無已，當涉遠路，趨走風尘，非志所慕，惨惨少樂。又計往還，將弥時節，念發同怨，意有遲遲，欲暫相見，有所屬讬，今遣車往，想必自力。","sortOrder":106},
  {"id":"s_work_nvlt_32_107","chapterId":"ch_work_nvlt_32","text":"秦嘉妻徐淑答書曰：知屈珪璋，應奉歲使，策名王府，觀國之光，雖失高素皓然之業，亦是仲尼執鞭之操也，自初承問，心原東還，迫疾惟宜抱叹而已，日月已盡，行有伴例，想嚴莊已辦，發邁在近，誰謂宋遠，企予望之，室邇人遐，我勞如何，深穀逶迤，而君是涉，高山巖巖，而君是越，斯亦難矣，長路悠悠，而君是踐，冰霜惨烈，而君是履，身非形影，何得動而辄俱，體非比目，何得同而不離，於是詠萱草之喻，以消兩家之恩，割今者之恨，以待將來之歡，今適樂土，優遊京邑，觀王都之壮麗，察天下之珍妙，得無目玩意移，往而不能出耶。","sortOrder":107},
  {"id":"s_work_nvlt_32_108","chapterId":"ch_work_nvlt_32","text":"嘉重報妻書曰：車還空反，甚失所望，兼叙遠別，恨恨之情，顧有恨然，間得此鏡，既明且好，形觀文彩，世所希有，意甚愛之，故以相與，併寶釵一双，好香四种，素琴一張，常所自彈也，明鏡可以鑒形，寶釵可以耀首，芳香可以馥身，素琴可以娱耳。","sortOrder":108},
  {"id":"s_work_nvlt_32_109","chapterId":"ch_work_nvlt_32","text":"妻又報嘉書曰：既惠音令，兼賜諸物，厚顧殷勤，出於非望，鏡有文彩之麗，釵有殊異之觀，芳香既珍，素琴益好，惠異物於鄙陋，割所珍以相賜，非丰恩之厚，孰肯若斯，覽鏡執釵，情想仿佛，操琴詠詩，思心成結，敕以芳香馥身，喻以明鏡鑒形，此言過矣，未獲我心也，昔詩人有飛蓬之感，班婕妤有誰榮之叹，素琴之作，當須君歸，明鏡之鑒，當待君還，未奉光儀，則寶釵不列也，未侍帷帳，則芳香不發也。","sortOrder":109},
  {"id":"s_work_nvlt_32_110","chapterId":"ch_work_nvlt_32","text":"梁何遜為衡山侯與婦書曰：昔人遨遊洛汭，會遇陽台，神仙仿佛，有如今別離，［離字疑衍。］帳前微笑，涉想猶存，而幄里餘香，從風且歇，掩屏為疾，引領成勞，鏡想分鸞，琴悲別鶴，心如膏火，獨夜自煎，思等流波，終朝不息，始知萋萋萱草，忘忧之言不實，团团輕扇，合歡之用為虛，路邇人遐，音尘寂絕，一日三秋，不足為喻，聊陳往翰，寧寫款懷，遲枉琼瑤，慰其杼軸。","sortOrder":110},
  {"id":"s_work_nvlt_32_111","chapterId":"ch_work_nvlt_32","text":"周庾信為上黃侯世子與婦書曰：昔仙人道引，尚刻三秋，神女將梳，猶期九日，未有龍飛劍匣，鶴別琴台，莫不衔怨而心悲，聞猿而下淚，人非新市，何處尋家，別異邯鄲，那應知路，想鏡中看影，當不含啼，欄外將花，居然俱笑，分杯帳里，却扇床前，故是不思，何時能憶，當學海神，逐潮風而來往，勿如織女，待填河而相見。","sortOrder":111},
  {"id":"s_work_nvlt_32_112","chapterId":"ch_work_nvlt_32","text":"陳伏知道為王宽與婦義安主書曰：昔魚嶺逢車，芝田息駕，雖見妖淫，終成揮忽，遂使家勝陽台，為歡非夢，人慚萧史，相偶成仙，輕扇初开，欣看笑靨，長眉始畫，愁對離妆，猶聞徙佩，顧長廊之未盡，尚分行幰，冀迥陌之難回，廣攝金屏，莫令愁擁，恒开錦幔，速望人歸，鏡台新去，應餘落粉，燻爐未徙，定有餘煙，淚滴芳衾，錦花長濕，愁隨玉軫，琴鶴恒驚，已覺錦水丹鱗，素書稀遠，玉山青鳥，仙使難通，采筆试操，香箋遂滿，行雲可讬，夢想還勞，九重千日，詎想倡家，单枕一宵，便如荡子，當令照影双來，一鸞羞鏡，勿使窥窗獨坐，恒娥笑人。","sortOrder":112},
  {"id":"s_work_nvlt_32_113","chapterId":"ch_work_nvlt_32","text":"《藝文類聚》　唐·欧陽詢","sortOrder":113},
  {"id":"s_work_nvlt_33_1","chapterId":"ch_work_nvlt_33","text":"卷三十三人部十七","sortOrder":1},
  {"id":"s_work_nvlt_33_2","chapterId":"ch_work_nvlt_33","text":"○寵幸遊俠報恩報讎盟","sortOrder":2},
  {"id":"s_work_nvlt_33_3","chapterId":"ch_work_nvlt_33","text":"◇寵幸","sortOrder":3},
  {"id":"s_work_nvlt_33_4","chapterId":"ch_work_nvlt_33","text":"《左傳》曰：申侯有寵於楚文王，文王將死，與之璧，使行，曰：唯我知汝，汝专利而不厭，我死，汝必速行，無適小國，將不容汝焉，既葬，出奔鄭。又寵於厲公。","sortOrder":4},
  {"id":"s_work_nvlt_33_5","chapterId":"ch_work_nvlt_33","text":"又曰：公子他有白馬四，宋公嬖向魋，魋欲之，公取而朱其尾鬛，以與之，他怒，使其從奪之，魋懼，將走，公閉門而泣之，目盡肿。","sortOrder":5},
  {"id":"s_work_nvlt_33_6","chapterId":"ch_work_nvlt_33","text":"《韓子》曰：弥子瑕有寵於衛國，衛國法，竊駕君車罪刖，子瑕之母病，其人有夜告弥子，弥子矯駕君車以出，君聞而賢之曰：孝哉，為母之故，犯刖罪，異日與君遊於果園，食桃而甘，以其餘獻君，君曰：愛我，忘其口，啖寡人。","sortOrder":6},
  {"id":"s_work_nvlt_33_7","chapterId":"ch_work_nvlt_33","text":"《戰國策》曰：楚王遊雲夢，結驷千乘，旌旗蔽日，野火之起若雲蜺，兕虎之〈口睪〉若雷霆，有狂兕依輪，而王親扞弓而射之，一發而殪，王仰天而笑曰：樂矣，今日之遊也，寡人萬歲千秋之後，誰與同樂此矣，安陵君纏泣數行而進曰：臣入則侍席，出則陪乘，大王萬歲千秋之後，臣原以身拭黃泉，驅蝼蚁。又何得此樂而樂之，大王悅，而封纏為安陵君。","sortOrder":7},
  {"id":"s_work_nvlt_33_8","chapterId":"ch_work_nvlt_33","text":"又曰：魏王與龍陽君共船而釣，龍陽君涕下，王曰：何為泣，曰：為臣之所得魚也，王曰：何謂也，對曰：臣之所得魚也，臣甚喜，後得又益大，臣欲弃前所得魚矣，今以臣之凶惡，而得為王拂枕席，今四海之內，美人亦甚多矣，聞臣之得幸於王也，必褰裳趍王，臣亦曩之所得魚也，亦將弃矣，臣安能無涕出乎，魏王於是布令於四境之內曰：敢言美人者滅族。","sortOrder":8},
  {"id":"s_work_nvlt_33_9","chapterId":"ch_work_nvlt_33","text":"《漢書》曰：漢興，佞幸寵臣，高祖時，則有藉孺，孝惠時閎孺，此兩人非有材能，但以婉媚貴幸，與上臥起，公卿皆因門說，故孝惠時，郎侍中皆冠鵕鸃，具帶，傅脂粉，皆閎藉之屬也。","sortOrder":9},
  {"id":"s_work_nvlt_33_10","chapterId":"ch_work_nvlt_33","text":"又曰：邓通為黃頭郎，文帝夢上天，不能，有一黃頭郎推助之，及顧其衣裳，後穿，寐覺而之漸台，以夢中陰自求推者，見邓通其衣後穿，夢中所見也，召問甚悅，尊異之，通亦願謹，不好外交，雖賜洗沐，不欲出，於是文帝賞賜通鉅萬以十數，賜通蜀嚴道銅山，得自鑄錢。","sortOrder":10},
  {"id":"s_work_nvlt_33_11","chapterId":"ch_work_nvlt_33","text":"又曰：韓嫣，武帝為膠東王時，與上學相愛，及上為太子，愈益親，嫣善騎射，聰惠，上即位，欲事伐胡，而嫣先習兵，以故益尊貴，賞賜擬邓通，常與上共臥起。","sortOrder":11},
  {"id":"s_work_nvlt_33_12","chapterId":"ch_work_nvlt_33","text":"又曰：李延年歌為变聲，是時欲造樂，令司馬相如等作詩，延年辄承意，絃歌所造詩，為之聲曲，由是為协律都尉，佩二千石印綬，而上與之臥起，其愛幸將韓嫣同。","sortOrder":12},
  {"id":"s_work_nvlt_33_13","chapterId":"ch_work_nvlt_33","text":"又曰：金日磾子賞建二人，皆愛幸，為武帝弄兒，常在旁，昭帝時，日磾兩子俱侍中，與昭帝略同年，共臥起，賞為奉車都尉，建為駙馬都尉。","sortOrder":13},
  {"id":"s_work_nvlt_33_14","chapterId":"ch_work_nvlt_33","text":"又曰：張放，鸿嘉中，宣［當作成。］帝欲遵武帝故事，與近臣遊宴，放以公主子，日數得幸，取皇後弟平恩侯許嘉女，上為放供帳，賜甲第，充以乘舆服飾，號為天子取婦，皇後嫁女，兩宮使者，冠蓋不絕，賞賜以千萬，故與上臥起，寵愛殊絕。","sortOrder":14},
  {"id":"s_work_nvlt_33_15","chapterId":"ch_work_nvlt_33","text":"又曰：董賢為郎，傳漏正殿下，賢為人美麗，哀帝望見，悅其儀貌，識而問之曰：是舍人董賢耶，因引上與語，拜為黃門郎，由是始幸，賢寵愛日甚，為駙馬都尉，侍中，出則參乘，入御左右，旬月間，賞賜累鉅萬，常與上臥起，常晝寢，偏藉上衣袖，上欲起，賢未覺，不欲動賢，乃斷袖而起，其受恩至此。","sortOrder":15},
  {"id":"s_work_nvlt_33_16","chapterId":"ch_work_nvlt_33","text":"《魏志》曰：孔掛［魏志三註作桂，下同。］性便妍，晓博弈蹋鞠，太祖愛之，每在左右，出入隨從，掛察太祖意歡樂，因言吹，［魏志註作次。］曲有所陳，事多見從，數得賞賜。又多饋遺，掛由此侯服玉食，太祖既愛掛，五官將及諸侯亦皆親之。","sortOrder":16},
  {"id":"s_work_nvlt_33_17","chapterId":"ch_work_nvlt_33","text":"又曹毗曹肇傳曰：肇纂［按本條不見魏志註，肇纂間疑有脱文。］明帝寵愛之，寢止恒同，常與帝戲，睹衣物，有不獲，辄入御帳，服之径出，其見親寵，類此比也。","sortOrder":17},
  {"id":"s_work_nvlt_33_18","chapterId":"ch_work_nvlt_33","text":"《俗說》曰：桓玄寵丁期，朝賢論事，賓客聚集，恒在背後坐，食畢，便回盤與之，期雖被寵，而謹約不敢為非，玄臨死之日，期乃以身捍刃。","sortOrder":18},
  {"id":"s_work_nvlt_33_19","chapterId":"ch_work_nvlt_33","text":"【詩】魏阮籍詩曰：昔日繁華子，安陵與龍陽，夭夭桃李華，灼灼有辉光，悅泽若九春，罄折似秋霜，流眄發姿媚，言笑吐芬芳，携手等歡愛，宿昔同衾裳。","sortOrder":19},
  {"id":"s_work_nvlt_33_20","chapterId":"ch_work_nvlt_33","text":"晉張翰周小史詩曰：翩翩周生，婉娈幼童，年十有五，如日在東，香膚柔泽，素质參紅，团辅圓跡，菡萏芙蓉，爾形既淑，爾服亦鮮，輕車隨風，飛霧流煙，轉侧綺靡，顧眄便妍，和顏善笑，美口善言。","sortOrder":20},
  {"id":"s_work_nvlt_33_21","chapterId":"ch_work_nvlt_33","text":"梁吳筠詠少年詩曰：董生唯巧笑，子都信美目，百萬市一言，千金買相逐，不道參差菜，誰論窈窕淑，原君捧繡被，來就越人宿。","sortOrder":21},
  {"id":"s_work_nvlt_33_22","chapterId":"ch_work_nvlt_33","text":"梁劉遵繁華詩曰：可怜周小童，微笑摘蘭藂，鮮膚勝粉白，〈月曼〉脸若桃紅，挟彈雕陵下，垂鉤莲葉東，腕動飄香麝，衣輕任好風，幸承拂枕選，得奉畫堂中，本知傷輕薄，含辭羞自通，翦袖恩雖重，殘桃愛不終，蛾眉詎誰嫉，新姬近入宮。","sortOrder":22},
  {"id":"s_work_nvlt_33_23","chapterId":"ch_work_nvlt_33","text":"【論】梁沈約宋書恩幸傳序論曰：夫人君南面，九重奧絕，陪奉朝夕，義隔卿士，階闼之任，宜有司存，既而恩以狎生，信由恩得，無可憚之姿，有易親之色，孝建泰始，主威獨運，空置百司，權不外假，而刑政糾雜，理難遍通，耳目所寄，事歸近習，賞罰之要，是謂國權，出內王命，由其掌握，於是方涂結軌，輻輳同奔，人主謂其身卑位薄，以為權不得重，曾不見鼠凭社貴，狐藉虎威，外無逼主之嫌，內有专用之功，势傾天下，未之或悟，挟朋树党，政以賄成，鈇质創痏，構於床笫，服冕乘軒，出乎言笑之下，西京許史，蓋不足雲，晉朝王石，［宋書九十四恩倖傳作庾。］未或能及，太宗晚運，屢經盛衰，權倖之徒，慴憚宗戚，欲使幼主孤立，永竊國權，構造異同，興树禍隙，帝弟宗王，相繼屠剿，民忘宋德，雖非一涂，寶祚夙傾，實由於此，呜呼哀哉。","sortOrder":23},
  {"id":"s_work_nvlt_33_24","chapterId":"ch_work_nvlt_33","text":"◇遊俠","sortOrder":24},
  {"id":"s_work_nvlt_33_25","chapterId":"ch_work_nvlt_33","text":"《列子》曰：虞氏者，梁之富民也，家既充盛，錢金無量，财货無赀，登高樓，臨大路，設樂陳酒，击博樓上，俠客相隨而行，樓上博者大笑，鳶飛，適墜其腐鼠而中之，俠客曰：虞氏福樂之日久矣，常有輕易人之志，乃辱我以腐鼠，率徒屬而滅其家。","sortOrder":25},
  {"id":"s_work_nvlt_33_26","chapterId":"ch_work_nvlt_33","text":"《史記》曰：甯成抵罪得脱，乃诈［原訛許，據冯校本改。］刻傳，出關歸家，稱曰：仕不至二千石，贾不至千萬，安可比人乎，乃贳貸，買陂田千餘頃，役使數千家，數年，產至千金，為任俠，其役民重於郡守。","sortOrder":26},
  {"id":"s_work_nvlt_33_27","chapterId":"ch_work_nvlt_33","text":"《淮南子》曰：北楚有任俠者，其子孫數止之，不聽，縣有賊，大搜其庐，事果發覺，夜驚而走，追及之，其所施德者，皆為之戰，得免，反謂其子曰：汝數止吾俠，今有難，皆賴而身免，汝諫不可用也。","sortOrder":27},
  {"id":"s_work_nvlt_33_28","chapterId":"ch_work_nvlt_33","text":"《戰國策》曰：韓劚嚴遂事於君，二人相害，嚴遂正議直指，舉韓劚之過，拔劍趨之，嚴遂懼誅，亡去，求人可以報韓劚者，至齊，陰交聂政，以意厚之，政母死，既葬除服曰：嗟乎，政乃市井之人，鼓刀之屬，而嚴仲子不遠千里，枉車騎而交臣，舉金為親寿，是深知政也，至濮陽，見嚴仲子曰：前所以不許子者，徒以親在，今親已亡，仲子所欲報者為誰，嚴仲子具告曰：臣之仇韓劚，政遂獨行，仗劍至韓，直入刺劚，劚走而抱哀侯，政刺之，兼中哀侯，左右大亂。","sortOrder":28},
  {"id":"s_work_nvlt_33_29","chapterId":"ch_work_nvlt_33","text":"《漢書》曰：戰國合縱連衡，力政爭彊，繇是列國公子，魏有信陵，趙有平原，齊有孟嘗，楚有春申，皆藉王公之势，競為遊俠，雞鳴狗吠，無不賓禮，而談者以四豪而稱首。","sortOrder":29},
  {"id":"s_work_nvlt_33_30","chapterId":"ch_work_nvlt_33","text":"又曰：季布為任俠，有名，項籍使將兵，數窘漢王，項籍滅，高祖購求布千金，敢匿罪三族，布匿濮陽周氏，乃髡鉗布衣褐，置廣柳車中，併與其家僮數十人，之魯朱家所賣之，朱家心知其季布也，買置田舍，乃之洛陽，見汝陰侯滕公說曰：季布何罪，臣各為其主用職耳，項氏臣豈可盡誅也，今上始得天下，而以私怨求一人，何示不廣也，且以季布之賢，漢求之急，如此，此不北走胡，南走越耳，大忌壮士以資敵國，此伍子胥所以鞭荆王之墓也，君何不從容為上言之，滕公心知朱家大俠，意布匿其所，乃許诺，侍間，果言如朱家指，上乃赦布。","sortOrder":30},
  {"id":"s_work_nvlt_33_31","chapterId":"ch_work_nvlt_33","text":"又曰：季布弟季心，氣蓋關中遇人謹恭，為任俠，方數千里，士爭為死，嘗殺人亡吳，從爰絲匿，長事爰絲，弟畜灌夫籍福之屬，少年多待之，籍其名以行，當是時，季布以信聞關中。","sortOrder":31},
  {"id":"s_work_nvlt_33_32","chapterId":"ch_work_nvlt_33","text":"又，鄭當時為任俠自喜，孝景時，為太子舍人，每五日洗沐，常置驿馬長安諸郊，請謝賓客，夜以繼日，至明旦，常恐不遍，其知友皆天下有名之士也。","sortOrder":32},
  {"id":"s_work_nvlt_33_33","chapterId":"ch_work_nvlt_33","text":"又曰：丞相公孫贺子敬聲，以皇後姊子驕奢，擅用北軍錢千九百萬，發覺下獄，是時詔捕陽陵朱安世，不能得，上求之急，贺自請逐捕安世，以贖敬聲罪，上許之，後果獲安世，安世者，京師大俠也，聞贺欲以贖子，笑曰：丞相禍及宗矣，南山之竹，不足受我辭，斜穀之木，不足為我械，安世從獄中告敬聲與陽石公主私通，及使巫祭祠，當道埋偶人，祝詛有惡言，下有司案验，贺父子死獄中。","sortOrder":33},
  {"id":"s_work_nvlt_33_34","chapterId":"ch_work_nvlt_33","text":"又曰：灌夫，為人刚直使酒，不好面諛權貴，势在己右者，必陵之，在左者，愈貧賤，尤益禮敬，稠人廣眾，荐寵下辈，士以此多歸之。","sortOrder":34},
  {"id":"s_work_nvlt_33_35","chapterId":"ch_work_nvlt_33","text":"又曰：剧孟，以俠顯，吳楚反時，條侯為太尉，乘傳東，將至河南，得剧孟，喜曰：吳楚舉大事，而不求剧孟，吾知其無能為已，天下骚動，大將得之，若一敵國，剧孟行大類朱家，及孟母死，自遠方送丧，蓋千乘，及孟死，家無十金之财。","sortOrder":35},
  {"id":"s_work_nvlt_33_36","chapterId":"ch_work_nvlt_33","text":"又曰：郭解，河內轵人，任［《太平御覽》四百七十三任上有解父以三字，此脱。］俠，孝文時誅死，解為人靜悍，不飲酒，所殺甚眾，以軀借友報仇，自喜為俠，解姊子見殺，解使人微知賊處，賊窘自歸，具以實告，解曰：公殺之當，吾兒不直，遂放其賊，諸公聞之，皆多解之義，益附焉，解出入，人皆避，有一人獨箕踞视之，解問其姓名，客欲殺之，解曰：居邑屋不見敬，是吾德不脩也，彼何罪。","sortOrder":36},
  {"id":"s_work_nvlt_33_37","chapterId":"ch_work_nvlt_33","text":"又曰：萬章與中書令石顯相善，顯坐专權擅势，免官故［漢書九十二遊俠傳故上有徙歸二字，此脱。］郡，留其床席器物，直數百萬，欲以與章，章不受，賓客或問其故，章叹曰：章以布衣見哀於石君，石君家破，不能有以安也，受其财物，此為石氏之禍，萬氏反福耶，諸公以是稱之。","sortOrder":37},
  {"id":"s_work_nvlt_33_38","chapterId":"ch_work_nvlt_33","text":"又曰：娄護，字君卿，是時王氏方盛，賓客盈門，五侯兄弟，爭名其客，各有所厚，唯護盡入其門，鹹得其懽心，結士大夫，無所不傾，其交長者，尤見親敬，眾以是服之，與穀永俱為五侯上客，長安號曰：穀子雲之筆札，娄君卿之唇舌，母死，送葬者致車二三千兩，闾里歌之曰：五侯治丧娄君卿，時成都侯商為大司馬衛將軍，欲候護，其主簿諫曰：將軍至尊，不宜入闾巷，商不聽，遂往至護家，久住移時。","sortOrder":38},
  {"id":"s_work_nvlt_33_39","chapterId":"ch_work_nvlt_33","text":"《魏志》曰：楊阿若，後名丰，字伯陽，少遊俠，常以報仇解怨為事，故時人為之號曰：東市相斫楊阿若，西市相斫楊阿若。","sortOrder":39},
  {"id":"s_work_nvlt_33_40","chapterId":"ch_work_nvlt_33","text":"【詩】晉張華俠曲曰：俠客樂险幽，筑室窮山陰，栖遲熊羆穴，容與虎豹林，雄兒任氣候，聲蓋少年場，偕友行報怨，殺人駔市傍，吳刀鳴手中，利劍嚴秋霜，騰起如電激，回旋如流光，生從命子遊，死聞俠骨香，没身心不懲，勇氣如四方。","sortOrder":40},
  {"id":"s_work_nvlt_33_41","chapterId":"ch_work_nvlt_33","text":"又遊俠篇曰：翩翩四公子，濁世稱賢明，食客三千餘，門下稱豪英，遊說朝夕至，辯士自縱橫，孟嘗東出關，濟身由雞鳴，信陵西反魏，秦人开濟彊，趙勝南盟楚，乃與毛遂行，黃歇北適秦，太子還入荆。","sortOrder":41},
  {"id":"s_work_nvlt_33_42","chapterId":"ch_work_nvlt_33","text":"宋王僧達依古詩曰：少年好馳俠，旅宦遊關源，既踐經古跡，聊平興亡言，顯軌莫殊轍，幽涂豈異魂。","sortOrder":42},
  {"id":"s_work_nvlt_33_43","chapterId":"ch_work_nvlt_33","text":"宋鮑昭擬古詩曰：幽併重騎射，少年好馳逐，氈帶佩双鞬，象弧插雕服，獸肥春草短，飛鞚越平陆，朝遊雁門上，暮還樓煩宿，石梁有餘劲，驚雀無全目。","sortOrder":43},
  {"id":"s_work_nvlt_33_44","chapterId":"ch_work_nvlt_33","text":"又擬古詩曰：日晏罢朝歸，舆馬塞衢路，宗党生光華，賓仆遠傾慕，富貴人所欲，道德亦何懼。","sortOrder":44},
  {"id":"s_work_nvlt_33_45","chapterId":"ch_work_nvlt_33","text":"梁元帝劉生詩曰：任俠有劉生，然诺重西京，扶風好驚坐，長安恒借名，榴花聊夜飲，竹葉解朝醒，結交李都尉，遨遊佳麗城。","sortOrder":45},
  {"id":"s_work_nvlt_33_46","chapterId":"ch_work_nvlt_33","text":"梁吳筠詩曰：結客少年歸，翩翩駿馬肥，報恩殺人竟，賢君賜錦衣，握蘭登建禮，拖玉入含暉，顧看草玄者，功名終自微。","sortOrder":46},
  {"id":"s_work_nvlt_33_47","chapterId":"ch_work_nvlt_33","text":"又古意詩曰：西都盛冠蓋，九逵尘霧塞，中有惡少年，伎能专自得，玉鞭莲花紐，［原作細，據冯校本改。］金苣流星勒，聊為路傍人，寫鞚長楸北。","sortOrder":47},
  {"id":"s_work_nvlt_33_48","chapterId":"ch_work_nvlt_33","text":"梁王僧孺詩曰：青絲控燕馬，紫艾飾吳刀，朝風吹錦帶，落日映珠袍，陆離關右客，照曜出西豪，雖非學诡遇，終是任逢遭，人生會有死，得處如鸿毛，寧能偶雞鶩，寂寂隱蓬蒿。","sortOrder":48},
  {"id":"s_work_nvlt_33_49","chapterId":"ch_work_nvlt_33","text":"梁何遜擬輕薄篇曰：城東美少年，重身輕萬亿，拓彈隨珠丸，白馬黃金飾，長安九逵上，青槐陰道植，轂击晨已喧，肩摩暗不息，走狗通西望，牵牛亘南直，相期百戲傍，去來三市侧，象床沓繡被，玉盤傳綺食。","sortOrder":49},
  {"id":"s_work_nvlt_33_50","chapterId":"ch_work_nvlt_33","text":"周王襃遊俠篇曰：京洛出名謳，豪俠競交遊，河南朝四姓，關西謁五侯，斗雞橫大道，走馬出長楸，桑陰徙將夕，槐路轉淹留。","sortOrder":50},
  {"id":"s_work_nvlt_33_51","chapterId":"ch_work_nvlt_33","text":"周庾信詩曰：俠客重連鑣，金鞍被桂條，細尘障路起，驚花亂眼飄，酒醺人半醉，汗濕馬全驕，歸鞍畏日晚，爭路上河桥。","sortOrder":51},
  {"id":"s_work_nvlt_33_52","chapterId":"ch_work_nvlt_33","text":"陳沈蜅長安少年詩曰：長安好少年，驄馬鐵連錢，陳王裝腦勒，晉後鑄金鞭，步搖如飛燕，寶劍似舒莲，去來新市侧，遨遊大道邊。","sortOrder":52},
  {"id":"s_work_nvlt_33_53","chapterId":"ch_work_nvlt_33","text":"陳陰铿西遊鹹陽中詩曰：上林春色滿，鹹陽遊俠多，城斗疑連漢，桥星像跨河，影里看飛轂，尘前聽遠珂，還家何意晚，無處不經過。","sortOrder":53},
  {"id":"s_work_nvlt_33_54","chapterId":"ch_work_nvlt_33","text":"陳楊縉俠客控絕影詩曰：青門小苑物華新，花开鳥弄會芳春，仙掌層台浮麗日，長楸廣路起紅尘，園中追尋桃李径，陌上逢迎遊俠人，遊俠英名馳上國，人馬意氣俱相得，白玉鹿盧秋水劍，青絲宛轉黃金勒，复有魚目併龍文，躡影追風本絕群，影入吳門疑曳練，形來西北似浮雲，寄語幽併馳射客，未肯推名持借君。","sortOrder":54},
  {"id":"s_work_nvlt_33_55","chapterId":"ch_work_nvlt_33","text":"◇報恩","sortOrder":55},
  {"id":"s_work_nvlt_33_56","chapterId":"ch_work_nvlt_33","text":"《毛詩》曰：投我以木瓜，報之以琼琚，匪報也，永以為好也。","sortOrder":56},
  {"id":"s_work_nvlt_33_57","chapterId":"ch_work_nvlt_33","text":"又曰：無言不詶，無德不報。","sortOrder":57},
  {"id":"s_work_nvlt_33_58","chapterId":"ch_work_nvlt_33","text":"《左傳》曰：晉魏顆败秦師於辅氏，獲杜回，秦之力人也，初魏武子有嬖妾，無子，武子疾，命顆曰：必嫁是妾，疾病，曰：必以為殉，及卒，顆嫁之，曰：疾病則亂，從其治也，及辅氏之役，顆見老人結草以亢杜回，踬而顛，故獲之，夜夢老人曰：所嫁婦人之父也，爾用先人之治命，予是以報。","sortOrder":58},
  {"id":"s_work_nvlt_33_59","chapterId":"ch_work_nvlt_33","text":"《晏子》曰：晏子以粟金遺北郭骚，骚辭金受粟，有聞，［晏子春秋五，太平御覽四百七十九作間。］晏子見疑於景公，出奔，北《郭子》曰：養及親者，身更其難，遂造公廷曰：晏子天下之賢，去齊，齊國必侵，不若先死，乃自殺，公自追晏子，及郊而反之。","sortOrder":59},
  {"id":"s_work_nvlt_33_60","chapterId":"ch_work_nvlt_33","text":"《呂氏春秋》曰：秦穆公失右服馬，公自往求焉，見野人方食之於歧山之陽，穆公笑曰：食駿馬肉，不飲酒，予恐傷汝也，遂遍飲而去，及一年，為韓原之戰，晉人已環穆公之車，晉梁由靡已扣穆公左驂，嘗食馬肉三百餘人，疾斗車下，遂大剋晉，反獲晉惠公以歸。","sortOrder":60},
  {"id":"s_work_nvlt_33_61","chapterId":"ch_work_nvlt_33","text":"又曰：簡子有兩白〈馬嬴〉，甚愛之，陽城胥渠處，［陽城姓，胥渠名，處猶病也。］廣門之官夜款門而謁曰：主君之臣胥渠有疾，医教之曰：得白〈馬嬴〉之肝則止，不得則死，請入通，董安於［原訛虧，據冯校本改。］御於侧，簡子殺白〈馬嬴〉取其肝以予陽城胥渠，無何，趙興兵而攻翟，廣門之官七百人皆先登。","sortOrder":61},
  {"id":"s_work_nvlt_33_62","chapterId":"ch_work_nvlt_33","text":"《戰國策》曰：中山君饗都大夫，司馬子期在焉，羊羹不遍，子期怒而走於楚，以伐中山君，中山君亡走，有人挈戈隨其後者，顧謂二人，子奚為，對曰：臣父嘗饿且死，君下壶餐餔臣父，臣父且死曰：中山有事，汝必死之，故來死君也，中山君慨然曰：吾以一杯羊羹亡國，以一壶餐得二人。","sortOrder":62},
  {"id":"s_work_nvlt_33_63","chapterId":"ch_work_nvlt_33","text":"《史記》曰：爰盎為吳相，時有從吏，嘗盜爰盎侍兒，盎知之不泄，遇之如初，人有告從吏，言君知爾與侍者通，乃亡歸，盎驅自追，遂以侍者賜之，复為從吏，及爰盎使吳見守，從吏適為校司馬，守盎，夜引爰盎起曰：君可以去矣，吳王期旦日斬君，盎謝之而去。","sortOrder":63},
  {"id":"s_work_nvlt_33_64","chapterId":"ch_work_nvlt_33","text":"又曰：項王使說韓信，韓信謝曰：臣事項王，官不過郎中，位不過執戟，故背楚而歸漢，漢王授我上將軍印，解衣衣我，推食食我，言聽計用，夫人深親信我，我倍之不祥，雖死不易。","sortOrder":64},
  {"id":"s_work_nvlt_33_65","chapterId":"ch_work_nvlt_33","text":"《說苑》曰：楚莊王賜群臣酒，日暮燈燭滅，有人引美人衣，美人援絕其冠纓，告王曰：有引妾衣者，妾絕其纓，取持火來，视絕纓者，王曰：今日飲不絕纓者不懽，君臣百官皆絕冠纓，乃出火，居二年，晉與楚戰，有一人常在前，五合五獲首，怪而問之，對曰：臣乃夜絕纓者也，王隱忍不曝而誅，常原肝腦涂地，用頸血湔敵久矣，遂平晉君，［《太平御覽》四百七十九作軍。］","sortOrder":65},
  {"id":"s_work_nvlt_33_66","chapterId":"ch_work_nvlt_33","text":"《漢書》曰：張蒼，秦時為御史，有罪亡歸，及沛公略地過陽武，蒼以客從攻南陽，蒼當斬，解衣伏质，身大肥白如瓠，王陵乃言沛公，赦勿斬，以為常山相，蒼德王陵，及貴，父事陵，陵死，蒼為丞相，洗沐，常先朝陵夫人，上食，然後敢歸家。","sortOrder":66},
  {"id":"s_work_nvlt_33_67","chapterId":"ch_work_nvlt_33","text":"又曰：蓋宽饒為衛司馬，躬案行士卒庐室，视其飲食居處，有疾病者，身自撫循臨問，加致医藥，遇之甚恩，及歲終交代，衛卒數千人，皆叩頭自請，原复更留一年，以報宽饒厚德，宣帝嘉之，以宽饒為太中大夫。","sortOrder":67},
  {"id":"s_work_nvlt_33_68","chapterId":"ch_work_nvlt_33","text":"《吳越春秋》曰：伍子胥伐楚還，過溧陽瀨水之上，長叹息曰：吾常飢，於此乞食，而殺一婦人，將欲報之百金，不知其家，遂投金瀨水之中而去。","sortOrder":68},
  {"id":"s_work_nvlt_33_69","chapterId":"ch_work_nvlt_33","text":"《三辅决錄》曰：高陵庞勃，為郡小吏，東平衡農為書生，窮乏，容［太平御覽四百七十九作客。］鍜於勃家，勃知其賢，禮待酬直過常，農曰：為冯翊，乃相報，別七八年，累［御覽作果。］為冯翊，勃為門下書佐，忘之矣，農召問，乃悟，遂舉勃。","sortOrder":69},
  {"id":"s_work_nvlt_33_70","chapterId":"ch_work_nvlt_33","text":"《魏略》曰：楊沛為新鄭長，課民蓄桑椹幪［原訛營，據冯校本作幪。］豆，積浸得千餘斛，太祖西迎天子，軍無糧，沛乃進乾椹，後為鄴令，賜其生口十六人，絹五百疋，以報乾椹也。","sortOrder":70},
  {"id":"s_work_nvlt_33_71","chapterId":"ch_work_nvlt_33","text":"《魏志》曰：太祖平幽州，召孫禮司空軍謀掾，初荒亂時，禮與母相失，同郡馬台，求得禮母，禮推家财，盡以與台。","sortOrder":71},
  {"id":"s_work_nvlt_33_72","chapterId":"ch_work_nvlt_33","text":"《華陽國志》曰：曹公察關羽不安，張遼以情問之，羽叹曰：吾極知曹公待我厚，然吾受劉將軍恩，誓以共死，不可背之，要當立效報公，公聞而義之，顏良攻東郡太守劉延於白馬，公使遼羽為先鋒，羽望見良麾，策馬刺於萬眾中，斬其首，盡封其物，稱書告辭，而歸先主。","sortOrder":72},
  {"id":"s_work_nvlt_33_73","chapterId":"ch_work_nvlt_33","text":"【賦】齊謝朓酬德賦曰：右衛沈侯，眷予以國士，四年，忝役朱方，見赠以詩，詩不雲乎，無言不酬，無德不報，故稱之酬德賦雲，悲夫四遊之代序，六龍骛而不息，輕蓋靡於駿奔，玉衡勞於撫翼，嗟歲晏之鮮歡，曾陰默以凄惻，嗟民生之知用，知莫深於在己，彼知己之為深，信懷之其何已，君奉筆於帝储，我曳裾於皇穆，籍風雲之光景，申遊好於蘭菊，結德言而為佩，帶芳猷而為服，予窘跡以多悔，媿離厄而獨處，君紆組於名邦，貽話言於川渚，爾要戟於戎禁，我拂劍於郎闈，原同車以日夜，誠望昏而掩扉，時遊般以未極，眷落景之徂暉，苦清顏之倏忽，吝歡賞之多违。","sortOrder":73},
  {"id":"s_work_nvlt_33_74","chapterId":"ch_work_nvlt_33","text":"【書】漢穀永謝王鳳書曰：永斗筲之材，质薄學朽，將軍悅其狂言，擢之皂衣之吏，廁之賓朋之末，不聽浸润之谮，不食膚受之愬，雖齊桓晉文，用士篤密，察父哲兄，覆育子弟，誠無以加，昔豫子吞炭坏形，以奉見異，齊容［漢書八十五，穀永傳作客。］陨首公門，以報恩於［漢書作施。］智氏孟嘗，猶有死士，何况將軍之門。","sortOrder":74},
  {"id":"s_work_nvlt_33_75","chapterId":"ch_work_nvlt_33","text":"◇報讎","sortOrder":75},
  {"id":"s_work_nvlt_33_76","chapterId":"ch_work_nvlt_33","text":"《禮記》曰：父母之讎，不與共戴天，兄弟之讎，不反兵，交遊之讎，不同國。","sortOrder":76},
  {"id":"s_work_nvlt_33_77","chapterId":"ch_work_nvlt_33","text":"又曰：居父母之讎，寢苫枕塊，不仕，不與共國，遇諸市，不反兵而斗。","sortOrder":77},
  {"id":"s_work_nvlt_33_78","chapterId":"ch_work_nvlt_33","text":"《左傳》曰：齊高發伐莒，莒子奔紀鄣，初莒有婦人，莒子殺其夫，己為釐婦，讬於紀鄣，紡焉，以度而去之，及師至，則投諸外，齊師夜縋而登，莒共公懼，啟西門而齊師入紀。","sortOrder":78},
  {"id":"s_work_nvlt_33_79","chapterId":"ch_work_nvlt_33","text":"又曰：吳伐越，越王句踐御之，陳於槜李，阖庐傷將指，還卒於陉，夫差使人立於庭，出入必謂曰：夫差，而忘越王之殺而父乎，則曰：唯，不敢忘，三年乃報越。","sortOrder":79},
  {"id":"s_work_nvlt_33_80","chapterId":"ch_work_nvlt_33","text":"《越絕書》曰：子胥入吳，阖庐將為之報讎，其後荆將軍伐蔡，使子胥伐荆，十五戰十五勝，子胥操捶，笞平王之墓而數之曰：吾先人無罪，而子殺之，今以此報子。","sortOrder":80},
  {"id":"s_work_nvlt_33_81","chapterId":"ch_work_nvlt_33","text":"《戰國策》曰：豫讓欲為智伯報讎，趙襄子當出，豫讓伏劍桥下，襄子至桥，馬驚，曰：必是讓也，求之，果是，數之曰：子不事范中行氏乎，智伯盡滅之，子不為報讎，反臣於智伯，智伯亦已死，何報讎深也，答曰：范中行眾人遇我，我以眾人報之，智伯國士遇我，我以國士報之，襄子曰：為智伯，名既成，寡人赦子，亦已，答曰：君前赦臣，天下莫不稱君之賢，臣固伏誅，然原請君之衣而击之，以致報讎之意，乃使使持衣與讓，讓拔劍三躍而击之，曰：吾可以下報智伯矣，遂伏劍死。","sortOrder":81},
  {"id":"s_work_nvlt_33_82","chapterId":"ch_work_nvlt_33","text":"《史記》曰：秦昭王聞魏齊在平原君所，欲為睢報仇，乃為書遺平原君曰：原與君為布衣之交，十日之飲，平原君見昭王，昭王與平原君飲，數日，謂曰：范君之仇在君家，原使入歸取頭來，平原君曰：不在臣所，昭王乃令趙王發卒围平原君家，魏齊夜亡。","sortOrder":82},
  {"id":"s_work_nvlt_33_83","chapterId":"ch_work_nvlt_33","text":"《東觀漢記》曰：海曲有呂母，其子為縣吏，犯小罪，縣宰殺之，呂母家素丰赀產，乃益酿醇酒，少年來沽者，贳之，视其乏者，辄假衣裝，少年欲相與偿之，呂母垂泣曰：縣宰枉殺吾子，欲報怨爾，諸君寧肯哀之乎，少年許诺，遂相聚得數百人，因與呂母入海，自稱將軍，遂破海曲，執縣宰斬之，以其首祭子冢。","sortOrder":83},
  {"id":"s_work_nvlt_33_84","chapterId":"ch_work_nvlt_33","text":"又曰：郅惲與董子張友，子張父為乡人所害，及子張病將終，惲候子張，视惲歔欷不能言，惲曰：吾知子不悲天命，而痛讎不复也，惲即將客遮仇人，取其頭以示子張，子張見而氣絕。","sortOrder":84},
  {"id":"s_work_nvlt_33_85","chapterId":"ch_work_nvlt_33","text":"又曰：趙喜少有節操，從兄為人所殺，無子，喜常思欲報之，遂往复仇，而仇家皆疾病，喜以因疾報殺，非仁者心，且釋之而去，顧謂仇曰：爾曹若健，遠相避，後病愈，悉自縛詣喜，喜不與相見，後竟殺之。","sortOrder":85},
  {"id":"s_work_nvlt_33_86","chapterId":"ch_work_nvlt_33","text":"《吳書》曰：甘寧殺陵統父，孫權命不得讎之，嘗於呂蒙舍酒酣，統乃以刀舞，寧起曰：寧能双戟舞，蒙曰：未若蒙之巧也，因操刀楯，以身分之。","sortOrder":86},
  {"id":"s_work_nvlt_33_87","chapterId":"ch_work_nvlt_33","text":"《列女傳》曰：缑氏女玉，為父報讎，吏執玉，以告外黃令梁配，欲論殺玉，申徒蟠時年十五，進諫曰：玉之節義，足以感無恥之孫，激忍辱之子，不遭明時，尚當表旌庐墓，况在清聽，而不加哀矜，配善其言，乃為减死論。","sortOrder":87},
  {"id":"s_work_nvlt_33_88","chapterId":"ch_work_nvlt_33","text":"又曰：庞涓母者，趙氏女，字娥，父為同縣人所殺，而娥兄弟三人，俱時病物故，讎乃喜，以為莫己報，娥乃潛備刀兵，以候讎家十餘年後，遇於都亭，刺殺之，因詣縣自首曰：父仇已報，請就刑。","sortOrder":88},
  {"id":"s_work_nvlt_33_89","chapterId":"ch_work_nvlt_33","text":"又曰：衛義姬者，其夫有先人之讎，讎家來報，婿避之，仇家得義姬，問婿所在，乃積薪，燎之，遂不言而燒死。","sortOrder":89},
  {"id":"s_work_nvlt_33_90","chapterId":"ch_work_nvlt_33","text":"又曰：潁川公孫氏女河，年十三，怨家報其父，父走得免，河與母俱亡，母先見得，仇人事欲甘心，河馳出，叩頭涕泣曰：老母常有篤疾，安足殘戮以塞忿哉，我是其兒，父母所怜，不如殺我，仇遂殺之，而舍其母。","sortOrder":90},
  {"id":"s_work_nvlt_33_91","chapterId":"ch_work_nvlt_33","text":"又京師節女者，本夫有仇，仇家欲報其夫，乃劫其妻父，使要其女中間，父呼其女而告之計，女念不聽之則殺父，不孝，聽之則殺夫，不義，欲以身當之，曰：诺，因曰：夜在樓上新沐頭東首臥，則是矣，仇家果至，斷其頭持去，明而视之，乃其妻之頭也，仇以為義，遂釋其夫。","sortOrder":91},
  {"id":"s_work_nvlt_33_92","chapterId":"ch_work_nvlt_33","text":"會稽典錄，董黯家貧，采薪供養，母甚肥悅，鄰人家富，有子不孝，母甚瘦小，不孝子疾黯母肥，常苦之，黯不報，及母終，負土成墳竟，殺不孝子，置冢前以祭。","sortOrder":92},
  {"id":"s_work_nvlt_33_93","chapterId":"ch_work_nvlt_33","text":"《晉中興書》曰：桓溫父被害時，溫年十五，枕戈泣血經年，乃提刀直進，手刃仇人。","sortOrder":93},
  {"id":"s_work_nvlt_33_94","chapterId":"ch_work_nvlt_33","text":"【詔】魏文帝詔曰：丧亂以來，兵革縱橫，天下之人，多相殘害者，昔田橫殺郦商之兄，張步害伏湛之子，漢氏二祖，下詔使不得相讎，今兵戎始息，宇內初定，民之存者，非流亡之孤，則鋒刃之餘，當相親愛，養老長幼，自今以後，宿有仇怨者，皆不得相讎。","sortOrder":94},
  {"id":"s_work_nvlt_33_95","chapterId":"ch_work_nvlt_33","text":"【教】梁簡文帝甄異張景原复讎教曰：夫理感禽魚，道均荆棘，亦有乡因行改，江以孝移，張景原自縛到郡，稱其父為韦法所殺，今於公田渚斬法級祭墓訖，束身歸家，昔沂泽撫劍，河南執戟，遠符古義，實足可嘉，防廣刃讎，赦其桎梏之罪，丁蘭雪恥，擢以大夫之位。","sortOrder":95},
  {"id":"s_work_nvlt_33_97","chapterId":"ch_work_nvlt_33","text":"《周官》曰：凡邦國有疑，會同則掌其盟約之載，盟萬民之犯命者，詛其不信者，有獄者則使之盟詛，凡盟詛各以其地域之眾庶，供其牲而致焉。","sortOrder":97},
  {"id":"s_work_nvlt_33_98","chapterId":"ch_work_nvlt_33","text":"《尚書》曰：惟十三年，大會於孟津，王曰：嗟我友邦冢君，越我御事庶士，明聽誓，今商王受，弗敬上天，降灾下民，沈湎冒色，敢行暴虐，罪人以族，官人以世，惟宮室台榭陂池侈服，以殘害於爾萬方百姓，皇天震怒，命我文考，肅將天威，大勋未集，肆予小子發，以爾友邦冢君，觀政於商，同力度德，同德度義，受有臣亿萬，惟亿萬心，予有臣三千，惟一心，商罪貫盈，天命誅之，予弗順天，厥罪惟鈞，爾尚弼予一人，永清四海。","sortOrder":98},
  {"id":"s_work_nvlt_33_99","chapterId":"ch_work_nvlt_33","text":"又曰：時厥明，王乃大巡六師，明誓眾士，王曰：呜呼我西土君子，商王受，狎侮五常，荒怠不敬，自絕於天，結怨於民，斮朝涉之胫，剖賢人之心，作威殺戮，毒痡四海，崇信奸回，放黜師保，屏弃典刑，囚奴正士，郊社不修，宗廟不享，作奇技淫巧，以悅婦人，爾其孜孜奉予一人，恭行天罰。","sortOrder":99},
  {"id":"s_work_nvlt_33_100","chapterId":"ch_work_nvlt_33","text":"《左傳》曰：晉侯獻楚俘於王，王子虎盟諸侯於王庭，要言曰：皆奖王室，無相害也，有渝此盟，明神殛之，俾墜其師，無克祚國，及而玄孫，無有老幼，君子謂是盟也信。","sortOrder":100},
  {"id":"s_work_nvlt_33_101","chapterId":"ch_work_nvlt_33","text":"又曰：甯武子與衛人盟於宛濮，曰：天禍衛國，君臣不协，今天誘其衷，使皆降心以相從也，不有居者，誰守社稷，不有行者，誰扞牧圉，不协之故，用昭乞盟於爾大神，自今日以往，行者無保其力，居者無懼其罪，有渝此盟，明神先君，是糾是殛，國人聞此盟而後不貳。","sortOrder":101},
  {"id":"s_work_nvlt_33_102","chapterId":"ch_work_nvlt_33","text":"又曰：楚子围鄭，鄭伯肉袒牵羊以逆，楚王曰：其君能下人，必能信用其民矣，退三十里而許鄭人平，潘尫入盟，子良出质。","sortOrder":102},
  {"id":"s_work_nvlt_33_103","chapterId":"ch_work_nvlt_33","text":"又曰：楚師围宋，宋人懼，使華元夜入楚師，登子反之床，起之曰：寡君使元以病告曰：弊邑易子而食，析骸而爨，雖然，城下之盟，有以國毙，不能從也，去我三十里，唯命是聽，子反懼，與之盟，而告王，退三十里。","sortOrder":103},
  {"id":"s_work_nvlt_33_104","chapterId":"ch_work_nvlt_33","text":"又曰：諸侯伐鄭，同盟於亳，載書曰：凡我同盟，無蘊年，無壅利，無保奸，無留慝，救灾患，恤禍亂，同好惡，奖王室，或簡茲命，司慎司盟，名山名川，群神群祀，先王先公，七姓十二國之祖，明神殛之，俾失其民，墜命亡氏，踣其國家。","sortOrder":104},
  {"id":"s_work_nvlt_33_105","chapterId":"ch_work_nvlt_33","text":"《史記》曰：吳起東遊，出衛郭門，與其母別，齧指而盟曰：起不為卿相，不复入衛。","sortOrder":105},
  {"id":"s_work_nvlt_33_106","chapterId":"ch_work_nvlt_33","text":"《漢書》曰：高後立諸呂為王，王陵曰：高皇帝刑白馬而盟，非劉氏而王者，天下共击之，今王呂氏，非約也。","sortOrder":106},
  {"id":"s_work_nvlt_33_107","chapterId":"ch_work_nvlt_33","text":"《淮南子》曰：胡人彈骨，［胡人之盟約，置酒人頭骨中，飲以相詛也。］越人割臂，中國喢盟，所由各異，其於信一也。","sortOrder":107},
  {"id":"s_work_nvlt_33_108","chapterId":"ch_work_nvlt_33","text":"《晉中興書》曰：中宗以祖逖為前鋒都督，径北渡江，中流誓曰：祖逖不清中原而复濟者，有如此江。","sortOrder":108},
  {"id":"s_work_nvlt_33_109","chapterId":"ch_work_nvlt_33","text":"又曰：吳主孫權，與蜀盟文曰：天降丧亂，皇綱失叙，逆臣承衅，劫奪國柄，始於董卓，終於曹操，九州輻裂，普天無繼，及操子丕，偷取天位，而叡么么，尋亦凶逆，昔共工亂蒙，而高辛行師，三苗千度，而虞舜征焉，今日滅叡，擒其徒党，非漢與吳，將复誰在，建大事，必先盟誓，漢之與吳，雖信由中，然分土列境，宜立盟約，使東西士民，鹹共聞知，既盟之後，戮力一心，同讨魏賊，救危恤患，分灾共慶，各守分土，無相侵犯，傳之後葉，克終若始，有渝此盟，創禍先亂，俾墜其師，無克祚國。","sortOrder":109},
  {"id":"s_work_nvlt_33_110","chapterId":"ch_work_nvlt_33","text":"【文】晉劉琨與段匹磾盟文曰：天不靜晉，難集上邦，四方豪杰，是焉扇動，乃凭陵於諸夏，俾天子播越震荡，罔有攸底，二虜交侵，區夏將泯，神人乏主，蒼生無歸，百罹備臻，死丧相枕，肌膚润於鋒鏑，骸骨曝於草莽，千里無煙火之庐，列城有丘曠之邑，茲所以痛心疾首，仰訴皇穹者也，臣琨蒙國寵靈，叨切台嶽，臣磾世效忠節，忝荷公辅，大懼丑類，猾夏王旅，殒首丧元，盡其臣禮，古先哲王，貽厥後訓，所以翼戴天子，敦序同好者，莫不臨之以神明，結之盟誓，故齊桓會於邵陵，而群後加恭，晉文盟於踐土，而諸侯茲順，加臣等，介在遐鄙，而與主相去迥遼，是以敢幹先典，刑牲歃血，自今日既盟之後，皆盡忠竭節，以翦夷二寇，有加難於琨，磾必救，加難於磾，琨亦如之，繾綣齊契，披布焜懷，書功金石，藏於王府，有渝此盟，亡其宗族，俾墜軍旅，無其遺育。","sortOrder":110},
  {"id":"s_work_nvlt_33_111","chapterId":"ch_work_nvlt_33","text":"晉庾闡為郄車騎讨蘇峻盟文曰：賊臣祖約蘇峻，不恭天命，不畏王誅，凶戾肆逆，幹國之紀，稱兵攻宮，焚掠宗廟，遂乃製胁幼主，有無君之心，大行皇太後，以忧厄崩殂，殘害忠良，禍虐烝民，窮凶極暴，毒流四海，是以率土怨酷，兆庶泣血，鹹原奉辭罰罪，以除元惡，今主上幽危，百姓倒懸，忠臣烈士，志在死國，既盟之後，戮力一心，共翦丑類，殒首丧元，以救社稷，若二寇不枭，無望偷安，當令生者不食今誓，死者無媿黃泉。","sortOrder":111},
  {"id":"s_work_nvlt_33_112","chapterId":"ch_work_nvlt_33","text":"晉王羲之為會稽內史，稱疾去郡，於父墓前自誓文曰：羲之不天，夙遭闵凶，遂因人乏，蒙國寵榮，每仰詠老氏周任之誡，常恐斯亡無日，是用寤寐永叹，若墜深穀，止足之分，定於今日，稽顙歸誠，自今之後，敢渝变此心，貪冒苟進，是有無尊之心，而不子也，子而不子，天地所不覆載也，名教所不得容也，信誓之誠，有如皎日。","sortOrder":112},
  {"id":"s_work_nvlt_33_113","chapterId":"ch_work_nvlt_33","text":"陳沈蜅為陳武帝與王僧辯盟文曰：侯景戎羯小丑，逆天無状，背我恩義，破我國家，毒我生民，改移我廟社，誅鋤我郡縣，割裂我宗姻，我高祖靈聖聰明，光宅天下，劬勞兆庶，亭育萬民，哀景以窮見歸，全景將戮之首，授景要害之地，崇景非次之榮，於景何怨，而景長戟彊弩，陵慼朝庭，刳肝斮趾，不厭其快，高祖菜食卑宮，春秋九十，屈意凝威，憤終寇手，大行皇帝，溫嚴恭默，不守鸿名，於景何有，复加忍毒，豈有率土之濱，忍聞此痛，僧辨等，荷相國湘東王泣血衔冤之寄，摩顶至踵之恩，能不瀝胆抽腸，共誅奸逆，葉和將帥，同心共契，必誅凶竖，尊奉湘東王，嗣膺鸿業，以主郊祭，若一相欺負，一相违戾，天地宗廟，是譴是詰。","sortOrder":113},
  {"id":"s_work_nvlt_33_114","chapterId":"ch_work_nvlt_33","text":"《藝文類聚》　唐·欧陽詢","sortOrder":114},
  {"id":"s_work_nvlt_34_1","chapterId":"ch_work_nvlt_34","text":"卷三十四人部十八","sortOrder":1},
  {"id":"s_work_nvlt_34_2","chapterId":"ch_work_nvlt_34","text":"○懷舊哀傷","sortOrder":2},
  {"id":"s_work_nvlt_34_3","chapterId":"ch_work_nvlt_34","text":"◇懷舊","sortOrder":3},
  {"id":"s_work_nvlt_34_4","chapterId":"ch_work_nvlt_34","text":"《尚書》：人惟求舊，器非求舊，惟新。","sortOrder":4},
  {"id":"s_work_nvlt_34_5","chapterId":"ch_work_nvlt_34","text":"《毛詩》曰：友賢不弃，不遺故舊，則民德歸厚。","sortOrder":5},
  {"id":"s_work_nvlt_34_6","chapterId":"ch_work_nvlt_34","text":"《左傳》曰：鄭子太叔卒，趙簡子為之臨，甚哀，曰：黃父之會，夫子語我九言，［事具言語篇。］","sortOrder":6},
  {"id":"s_work_nvlt_34_7","chapterId":"ch_work_nvlt_34","text":"《論語》曰：故舊不遺，則民不偷。","sortOrder":7},
  {"id":"s_work_nvlt_34_8","chapterId":"ch_work_nvlt_34","text":"《漢書》曰：高祖過沛，置酒沛宮，悉召故人父老，酒酣，自击筑起舞，慷慨傷懷，泣數行下，謂沛父兄曰：遊子悲故乡，吾雖都關中，萬歲之後，吾魂魄猶思樂沛，與父老諸母故乡人，樂飲極歡，道舊故為笑樂。","sortOrder":8},
  {"id":"s_work_nvlt_34_9","chapterId":"ch_work_nvlt_34","text":"又曰：朱邑惇篤於故舊，性公平，不可交私。","sortOrder":9},
  {"id":"s_work_nvlt_34_10","chapterId":"ch_work_nvlt_34","text":"《新序》曰：延陵季子使過徐，徐君心欲得其寶劍，弗忍言，季子心許之而未及與，及還而徐君已薨，乃脱寶劍，懸於墓树，徐人奇之曰：延陵季子，不忘舊故，脱千金之劍掛丘树。","sortOrder":10},
  {"id":"s_work_nvlt_34_11","chapterId":"ch_work_nvlt_34","text":"《東觀漢記》曰：章帝幸東平，祭東平王墓，雲，思其人，到其乡，其處在，其人亡。","sortOrder":11},
  {"id":"s_work_nvlt_34_12","chapterId":"ch_work_nvlt_34","text":"皇甫謐《高士傳》曰：徐稚仁讓聞於天下，黃琼辟公府，不詣，及琼薨，稚負笈徒步三千餘里，到琼墓致酹。","sortOrder":12},
  {"id":"s_work_nvlt_34_13","chapterId":"ch_work_nvlt_34","text":"嵇康《高士傳》曰：商容有疾，老子問之，容曰：子過故乡而下車，知之乎，老子曰：非謂不忘故耶。","sortOrder":13},
  {"id":"s_work_nvlt_34_14","chapterId":"ch_work_nvlt_34","text":"【詩】梁沈約懷舊詩曰：元長秉奇調，弱冠慕前蹤，眷言懷祖武，一簣望成峰，涂難行易跌，命舛志難逢，折風落迅羽，流恨滿青松，［傷王融。］","sortOrder":14},
  {"id":"s_work_nvlt_34_15","chapterId":"ch_work_nvlt_34","text":"又詩曰：吏部信才杰，文鋒振音响，調與金石諧，思逐風雲上，豈言陵霜质，忽隨人事往，尺璧爾何冤，一旦同丘壤，［傷謝朓。］","sortOrder":15},
  {"id":"s_work_nvlt_34_16","chapterId":"ch_work_nvlt_34","text":"又詩曰：右率馥時譽，秀出冠朋僚，耸茲千仞氣，依此百尋條，蘊藉含文雅，散朗溢風飆，楸槚今已合，容范尚昭昭，［傷庾杲之。］","sortOrder":16},
  {"id":"s_work_nvlt_34_17","chapterId":"ch_work_nvlt_34","text":"又詩曰：長史體閒任，坦荡無外求，持身非诡遇，應物有虛舟，心從朋好盡，形為歡宴留，歡宴未終畢，零落委山丘，［傷王諶。］","sortOrder":17},
  {"id":"s_work_nvlt_34_18","chapterId":"ch_work_nvlt_34","text":"又詩曰：東南既擅美，洛陽复稱才，携手同歡宴，比跡共追陪，事隨短秀落，言歸長夜台，［傷虞炎。］","sortOrder":18},
  {"id":"s_work_nvlt_34_19","chapterId":"ch_work_nvlt_34","text":"又詩曰：少府懷貞節，忘軀濟所奉，吏道勤不息，繁文長自擁，既闕優孟歌，身没誰為寵，［傷李珪之。］","sortOrder":19},
  {"id":"s_work_nvlt_34_20","chapterId":"ch_work_nvlt_34","text":"又詩曰：韦敻識前載，博物備戎華，稅驂止營校，淪跡委泥沙，如知庸聽局，方悟大音賒，［傷韦景猷。］又詩曰：處和無近累，天然有勝质，萧索負高情，耿介懷私實，義貴良為重，蘭摧非所恤，一罢平生言，寧知携手日，［傷劉佩。］","sortOrder":20},
  {"id":"s_work_nvlt_34_21","chapterId":"ch_work_nvlt_34","text":"又詩曰：豫州懷風范，綽然摽雅度，處約志不渝，接廣情無忤，頡颃事刀筆，紛纶遞朱素，美志同山河，浮年迫朝露，［傷胡諧之。］","sortOrder":21},
  {"id":"s_work_nvlt_34_22","chapterId":"ch_work_nvlt_34","text":"【賦】西晉向秀思舊賦曰：予與嵇康呂安，居止接近，其人併有不羁之才，嵇康意遠而疏，呂安心曠而放，其後各以事犯法，嵇博綜技藝，於絲竹特妙，臨當就命，顧视日影，索琴而彈之，曰［《文選》十六作餘。］逝將西邁，經其舊庐，鄰人有吹笛者，發聲寥亮，追想曩昔遊宴之好，感音而叹，故作賦雲，將命適於遠京，遂旋返而北徂，濟黃河以汎舟，經山陽之舊居，踐二子之遺跡，歷窮巷之空庐，惟古昔以懷念，心徘徊以踌躇，棟宇存而弗毀，形神逝其焉如，昔李斯之受罪，叹黃犬之長吟，悼嵇生之永辭，顧日影而彈琴，讬運遇於际會，寄餘命於寸陰，聽鳴笛之慷慨，妙聲絕而复尋，停駕言而將邁，遂援翰而寫心。","sortOrder":22},
  {"id":"s_work_nvlt_34_23","chapterId":"ch_work_nvlt_34","text":"晉潘嶽懷舊賦曰：予十二而獲見於父友東武戴侯楊君，遂申之以婚姻，而道元公嗣，亦隆世親之愛，不幸短命，父子凋殒，予尋役於外，不歷嵩丘之山者，九年於茲矣，今而經焉，慨然懷舊，乃作賦曰：仰睎歸雲，俯鏡泉流，前瞻太室，旁眺嵩丘，東武讬焉，建塋啟畴，巖巖双表，列列行楸，予總角而獲見，承戴侯之清尘，名予以國士，眷予以嘉姻，自祖考而隆好，逮二子而世親，歡携手以偕老，庶報德之有鄰，今九載而一來，空馆阒其無人，陳荄被於堂除，舊圃化而為薪，步庭庑以徘徊，流涕泣而霑巾。","sortOrder":23},
  {"id":"s_work_nvlt_34_24","chapterId":"ch_work_nvlt_34","text":"【銘】周庾信思舊銘曰：歲次攝提，星居鶉首，梁故觀寧侯萧永卒，呜呼哀哉，人之戚也，既非金石所移，士之悲也，寧有春秋之異，高台已傾，稷下有聞琴之泣，壮士一去，燕南有击筑之悲，項羽之晨起帳中，李陵之徘徊歧路，無假窮秋，於時悲矣，况复魚飛武库，豫有弃甲之徵，鳥伏狄泉，先見橫流之兆，星紀吳亡，庚辰楚滅，原隰載馳，轘轅長往，甲裳失矣，餘皇弃焉，河流酸棗，杞梓與樗櫟俱沉，海淺蓬萊，魚鱉共蛟龍併盡，燃香複道，詎斂冤魂，載酒屬車，寧消愁氣，芝蘭萧艾之秋，形殊而併悴，羽毛鱗介之怨，聲異而俱哀，幕府昔开，俊賢翘首，為羁終歲，門人謝焉，及乎東首告辭，西陵長往，山陽車馬，永別郊門，潁川賓客，遙悲松路，嵇叔夜之山庐，尚多楊柳，王子猷之舊径，唯餘竹林，王孫葬地，方為長樂之宮，列士埋魂，即是將軍之墓，昔嘗歡宴，風月留連，追憶平生，宛然心目，美酒酌焉，猶思建業之水，鳴琴在操，終念華亭之鶴，重為此別，呜呼甚哉，麟亡星落，月死珠傷，瓶罄罍恥，芝焚蕙叹，所冀鍾沉德水，望出風雲，劍没丰城，氣連牛斗，潸然思舊，乃作銘雲，風雲上惨，舟壑潛移，骎骎霜露，君子先危，紀侯大去，懷王不反，玉树長埋，風流遂遠，荀卿故縣，慶封餘邑，萬里傷魂，脩門詎入，城連武库，山枕盧龍，思歸道遠，反葬無從，徒留送雁，空靡長松，畴昔隆貴，惨舒語嘿，讬情嵇琴，風雲相得，有酒如渑，終溫且克，朝陽落鳳，大野傷麟，佳城鬱鬱，流寓於秦，山陽相送，惟餘故人，孀機嫠緯，獨鶴孤鸞，閨深夜靜，風月俱寒，生平已矣，懷故何期，匣中絃斷，鄰人笛悲，昔為幕府，今成德帷。","sortOrder":24},
  {"id":"s_work_nvlt_34_25","chapterId":"ch_work_nvlt_34","text":"【序】梁元帝懷舊志序曰：吾自北守琅台，東探禹穴，觀涛廣陵，面金湯之設险，方舟宛委，眺玉笥之幹霄，臨水登山，命儔嘯侣，中年承乏，攝牧神州，戚里英賢，尚冠髦俊，荫真長之弱柳，觀茂弘之舞鶴，清酒繼進，甘果徐行，長安郡公，為其延譽，扶風長者，刷其羽毛，於是駐伏熊，回驷，［全梁文十七驷上有結字。］命邹湛，召王祥，餘顧而言曰：斯樂難常，誠有之矣，日月不居，零露相半，素車白馬，往矣不追，春華秋寶，懷哉何已，獨軫魂交，情深宿草，故備書爵里，陳懷舊焉。","sortOrder":25},
  {"id":"s_work_nvlt_34_26","chapterId":"ch_work_nvlt_34","text":"◇哀傷","sortOrder":26},
  {"id":"s_work_nvlt_34_27","chapterId":"ch_work_nvlt_34","text":"《毛詩》曰：終風，衛莊薑傷己也，遭州吁之難，傷己不見答於先君，以至困窮。","sortOrder":27},
  {"id":"s_work_nvlt_34_28","chapterId":"ch_work_nvlt_34","text":"又曰：我心忧傷，惄焉如捣。","sortOrder":28},
  {"id":"s_work_nvlt_34_29","chapterId":"ch_work_nvlt_34","text":"《左傳》曰：魯襄仲殺公子惡及视，而立宣公，夫人薑氏歸於齊，哭而過市曰：天乎，仲為不道，殺適立庶，市人皆哭，魯人謂之哀薑。","sortOrder":29},
  {"id":"s_work_nvlt_34_30","chapterId":"ch_work_nvlt_34","text":"又，晉不哀吾丧，而滅吾同姓。","sortOrder":30},
  {"id":"s_work_nvlt_34_31","chapterId":"ch_work_nvlt_34","text":"《禮記》曰：墟墓之間，未施哀於民而民哀。","sortOrder":31},
  {"id":"s_work_nvlt_34_32","chapterId":"ch_work_nvlt_34","text":"又曰：陽門之介夫死，而司城子罕哭之哀，而民說。","sortOrder":32},
  {"id":"s_work_nvlt_34_33","chapterId":"ch_work_nvlt_34","text":"又曰：孔子過泰山侧，有婦人哭於墓者而哀，夫子使子貢問之，對曰：昔吾舅死於虎，吾夫又死焉，今吾子又死焉。","sortOrder":33},
  {"id":"s_work_nvlt_34_34","chapterId":"ch_work_nvlt_34","text":"又曰：知生者弔，知死者傷。","sortOrder":34},
  {"id":"s_work_nvlt_34_35","chapterId":"ch_work_nvlt_34","text":"又曰：傷哉貧也，生無以養，死無以為禮。","sortOrder":35},
  {"id":"s_work_nvlt_34_36","chapterId":"ch_work_nvlt_34","text":"又曰：孔子過衛，遇舊馆人之丧，夫子入哭之，出，使子貢脱驂而赙之，曰：予向者入而哭之，過於一哀而出涕。","sortOrder":36},
  {"id":"s_work_nvlt_34_37","chapterId":"ch_work_nvlt_34","text":"《論語》曰：關雎樂而不淫，哀而不傷。","sortOrder":37},
  {"id":"s_work_nvlt_34_38","chapterId":"ch_work_nvlt_34","text":"又曰：臨丧不哀，吾何以觀之哉。","sortOrder":38},
  {"id":"s_work_nvlt_34_39","chapterId":"ch_work_nvlt_34","text":"《家語》曰：闵子騫三年丧畢，見於孔子，與之琴，使之絃，切切而悲，孔子曰：君子也，哀未盡，能斷之以禮，［事具品藝篇。］焦贛《易林》曰：秋風生哀，華落悲心。","sortOrder":39},
  {"id":"s_work_nvlt_34_40","chapterId":"ch_work_nvlt_34","text":"《說苑》曰：鮑叔死，管仲舉上衽而哭之，泣下如雨，從者曰：非君臣父子也，管仲曰：生我者父母知我者鮑子也，士為知己者死，而况為之哀乎，《列子》曰：燕人生長於楚，及老而還本國，過晉國，同行者誑之，指城曰：此燕國之城，其人愀然变容，指社曰：此君里之社，乃喟然而叹，指舍曰：此君先人之庐，乃潸然而泣，指垅曰：此君先人之冢，其人哭不自禁。","sortOrder":40},
  {"id":"s_work_nvlt_34_41","chapterId":"ch_work_nvlt_34","text":"《文子》曰：九夷八狄之哭，異聲而皆哀。","sortOrder":41},
  {"id":"s_work_nvlt_34_42","chapterId":"ch_work_nvlt_34","text":"《吳志》曰：呂岱親愛徐源，源性忠壮，好直言，及源死，哭之甚哀，曰：益友不幸，岱复何聞乎。","sortOrder":42},
  {"id":"s_work_nvlt_34_43","chapterId":"ch_work_nvlt_34","text":"王隱《晉書》曰：庾袞兄子孤卒，袞既哀其孤。又痛其成人而未娶，撫柩而號，每哭，聽者皆泣，人不哀其丧，感其哀也。","sortOrder":43},
  {"id":"s_work_nvlt_34_44","chapterId":"ch_work_nvlt_34","text":"又曰：阮籍鄰家女，未嫁而死，籍往哭之，甚哀。","sortOrder":44},
  {"id":"s_work_nvlt_34_45","chapterId":"ch_work_nvlt_34","text":"《俗說》曰：阮光祿大兒丧，哀過，遂得失心病。","sortOrder":45},
  {"id":"s_work_nvlt_34_46","chapterId":"ch_work_nvlt_34","text":"《琴操》曰：孔子遊於泰山，見薪者哭甚哀，孔子問之，薪者曰：吾自傷，故哀爾。","sortOrder":46},
  {"id":"s_work_nvlt_34_47","chapterId":"ch_work_nvlt_34","text":"沈約《宋書》曰：世祖與群臣至寵姬殷貴妃墓，謂劉德原曰：卿等哭貴妃若悲者，當加厚賞，德原應聲便號恸，涕泗交橫，上甚悅，以為豫州刺史，上又令羊志哭，志亦呜咽甚哀，他日有問志者，卿那得此副急淚，志答曰：我爾日自哭亡妾耳。","sortOrder":47},
  {"id":"s_work_nvlt_34_48","chapterId":"ch_work_nvlt_34","text":"秦川記曰：隴西郡有隴山，山東人升此而顧瞻者，莫不悲思哀傷。","sortOrder":48},
  {"id":"s_work_nvlt_34_49","chapterId":"ch_work_nvlt_34","text":"【詩】魏文帝寡婦詩曰：友人阮元瑜早亡，傷其妻子孤寡，為作此詩，霜露紛兮交下，木葉落兮萋萋，候雁叫兮雲中，歸燕翩兮徘徊，妾心感兮惆怅，白日急兮西頹，守長夜兮思君，魂一夕兮九乖，怅延佇兮仰视，星月隨兮天回，徒引領兮入房，竊自怜兮孤栖，原從君兮終没，愁何可兮久懷。","sortOrder":49},
  {"id":"s_work_nvlt_34_50","chapterId":"ch_work_nvlt_34","text":"魏阮瑀七哀詩曰：丁年難再遇，富貴不重來，良時忽一過，身體為土灰，冥冥九泉室，漫漫長夜台，身盡氣力索，精魂靡所能，嘉肴設不御，旨酒盈觴杯，出壙望故乡，但見蒿與萊。","sortOrder":50},
  {"id":"s_work_nvlt_34_51","chapterId":"ch_work_nvlt_34","text":"又詩曰：臨川多悲風，秋日苦清涼，客子易為戚，感此用哀傷，攬衣久踯躅，上觀心與房，三星守故次，明月未收光，雞鳴當何時，朝晨尚未央，還坐長叹息，忧忧難可忘。","sortOrder":51},
  {"id":"s_work_nvlt_34_52","chapterId":"ch_work_nvlt_34","text":"魏王粲七哀詩曰：西京亂無象，銶虎方遘患，复弃中國去，遠身適荆蠻，親戚對我悲，朋友追相攀，出門無所見，白骨蔽平原，南登灞陵岸，回首望長安，悟彼下泉人，喟然傷心肝。","sortOrder":52},
  {"id":"s_work_nvlt_34_53","chapterId":"ch_work_nvlt_34","text":"又詩曰：荆蠻非我乡，何為久滯淫，方舟溯大江，日暮愁我心，山岡有餘映，巖阿增重陰，流波激清响，猴猿臨岸吟，獨夜不能寐，攝衣起撫琴，絲桐感人情，為我發悲音。","sortOrder":53},
  {"id":"s_work_nvlt_34_54","chapterId":"ch_work_nvlt_34","text":"晉張載七哀詩曰：秋風吐商氣，萧瑟扫前林，陽鳥收和响，寒蝉無餘音，朱光馳北陆，浮景想西沈，顧望無所見，唯睹松柏陰，肅肅高桐枝，翩翩孤栖禽，仰聽離鸿鳴，俯聞蜻蛚吟，哀人易感傷，覽物增悲心。","sortOrder":54},
  {"id":"s_work_nvlt_34_55","chapterId":"ch_work_nvlt_34","text":"晉潘嶽關中詩曰：哀此黎元，無罪無辜，肝腦涂地，白骨交衢，夫行妻寡，父出子孤，俾我晉民，化為狄俘。","sortOrder":55},
  {"id":"s_work_nvlt_34_56","chapterId":"ch_work_nvlt_34","text":"又哀詩曰：漼如葉落树，邈若雨絕天，雨絕有歸雲，葉落何連山，時氣冒岗嶺，長風鼓松柏，堂虛聞鳥聲，室暗如日夕，晝愁奄逮昏，夜思忽終昔，展轉獨悲窮，泣下霑枕席，人居天地間，飄若遠行客，先後詎能幾，誰能獘金石。","sortOrder":56},
  {"id":"s_work_nvlt_34_57","chapterId":"ch_work_nvlt_34","text":"又悼亡詩曰：皎皎窗中月，照我室南端，清商應秋至，溽暑隨節阑，凛凛涼風升，始覺夏衾单，豈曰無重纊，誰與同歲寒，歲寒無與同，朗月何胧胧，展轉眄枕席，長簟竟床空，床空委清尘，室虛來悲風，霑胸安能已，悲懷從中起，寢興目存形，遺音猶在耳。","sortOrder":57},
  {"id":"s_work_nvlt_34_58","chapterId":"ch_work_nvlt_34","text":"又悼亡詩曰：荏苒冬春謝，寒暑忽流易，之子歸窮泉，重壤永幽隔，望庐思其人，入室想所歷，帷屏無仿佛，翰墨有餘跡，流芳未及歇，遺桂猶在壁，怅脱如或存，回遑忡驚惕，如彼翰林鳥，双栖一朝只，如彼遊川魚，比目中路隔。","sortOrder":58},
  {"id":"s_work_nvlt_34_59","chapterId":"ch_work_nvlt_34","text":"又思子詩曰：造化甄品物，天命代虛盈，奈何念稚子，懷奇陨幼齡，追想存仿佛，感道傷中情，一往何時還，千載不复生。","sortOrder":59},
  {"id":"s_work_nvlt_34_60","chapterId":"ch_work_nvlt_34","text":"宋顏延之除弟服詩曰：徂没離二秋，淹泣備三冬，往辰緬難紀，來筭忽易窮，升没奄期晦，洒扫易禮容，縞衣变餘體，長逝歸爾躬。","sortOrder":60},
  {"id":"s_work_nvlt_34_61","chapterId":"ch_work_nvlt_34","text":"又辭難潮溝詩曰：徘徊眷郊甸，俯仰引单襟，一涂苟不豫，百慮畢來侵，永懷交在昔，有原愆瑟琴，寫言勞者事，將用慰亡簪。","sortOrder":61},
  {"id":"s_work_nvlt_34_62","chapterId":"ch_work_nvlt_34","text":"齊謝朓銅爵台妓詩曰：繐帷飄井幹，尊酒若平生，鬱鬱西陵树，詎聞歌吹聲，芳襟染淚跡，嬋媛空复情，玉坐猶寂寞，况乃妾身輕。","sortOrder":62},
  {"id":"s_work_nvlt_34_63","chapterId":"ch_work_nvlt_34","text":"梁簡文帝傷美人詩曰：昔聞倡女別，荡子無歸期，今似陳王叹，流風難重思，翠帶留餘結，苔階没故基，圖形更非是，夢見反成疑，燻爐含好氣，庭树吐華滋，香燒日有歇，花落無還時。","sortOrder":63},
  {"id":"s_work_nvlt_34_64","chapterId":"ch_work_nvlt_34","text":"梁任昉哭范仆射詩曰：平生禮數絕，式瞻在國禎，一朝萬化盡，猶我故人情，已矣平生事，詠歌盈箧笥，兼复相嘲謔，常與虛舟值，何時見范侯，還叙平生意。","sortOrder":64},
  {"id":"s_work_nvlt_34_65","chapterId":"ch_work_nvlt_34","text":"梁沈約萧丞相弟詣世子車中作詩曰：廉公失權势，門馆有虛盈，貴賤猶如此，况乃曲池平，高車尘未滅，珠履故餘聲，賓階绿錢滿，客位紫苔生，唯當九原上，鬱鬱望佳城。","sortOrder":65},
  {"id":"s_work_nvlt_34_66","chapterId":"ch_work_nvlt_34","text":"梁萧子范入元襄王第詩曰：伏軾窥東苑，收淚下玉桥，昔時方轂處，於今共寂寥，夹池猶裊裊，仙榭尚迢迢，一同西靡柏，徒思芳树萧。","sortOrder":66},
  {"id":"s_work_nvlt_34_67","chapterId":"ch_work_nvlt_34","text":"梁王筠和萧子范入元襄王第詩曰：昔入睢陽苑，連步披風雲，今遊故台處，向望阒無人，皓壁留餘篆，蕙圃有餘芬，行人皆陨涕，何獨孟嘗君。","sortOrder":67},
  {"id":"s_work_nvlt_34_68","chapterId":"ch_work_nvlt_34","text":"梁吳筠傷友詩曰：可怜桂树枝，懷芳君不知，摧折寒山里，遂死無人窥。","sortOrder":68},
  {"id":"s_work_nvlt_34_69","chapterId":"ch_work_nvlt_34","text":"梁何遜行經范仆射故宅詩曰：旅葵應蔓井，荒藤已上扉，寂寂空郊暮，無复車馬歸，潋滟故池水，蒼茫落日暉，阒寂今如此，行客盡霑衣。","sortOrder":69},
  {"id":"s_work_nvlt_34_70","chapterId":"ch_work_nvlt_34","text":"又銅爵台妓詩曰：秋風木葉落，萧瑟絃管清，望陵歌對酒，向帳舞空城，寂寂簷宇曠，飄飄帷幔輕，曲終相顧起，日暮松柏聲。","sortOrder":70},
  {"id":"s_work_nvlt_34_71","chapterId":"ch_work_nvlt_34","text":"梁劉孝綽銅爵台妓詩曰：爵台三五日，歌吹似佳期，定對西陵晚，松風飄素帷，危絃斷更接，心傷於此時，何言留客袂，翻掩望陵悲。","sortOrder":71},
  {"id":"s_work_nvlt_34_72","chapterId":"ch_work_nvlt_34","text":"梁庾肩吾亂後經吳郵亭詩曰：郵亭一回望，風尘千里昏，青袍異春草，白馬即吳門，獯戎鞭伊洛，雜种亂轘轅，輦道同關塞，王城似太原，休明鼎尚重，秉禮國猶存，殷牖爻雖跡，尧城吏轉尊，泣血悲東走，橫戈念北奔，方凭七廟略，誓雪五陵冤，人事今如此，天道共誰論。","sortOrder":72},
  {"id":"s_work_nvlt_34_73","chapterId":"ch_work_nvlt_34","text":"周庾信傷周處士詩曰：冥漠爾遊岱，凄涼予向秦，雖言異生死，同是不歸人，怅然張仲蔚，悲哉鄭子真，三山猶有鶴，五柳更應春，遂令從渭水，投釣往江濱。","sortOrder":73},
  {"id":"s_work_nvlt_34_74","chapterId":"ch_work_nvlt_34","text":"周王褒送觀寧侯葬詩曰：丹旐書空位，素帳設虛樽，楚琴南操絕，韓書舊說存，西靡傷新树，東陵惜故園，自怜悲穀影，弥念玉關門，餘暉天盡末，夕霧起山根，平原看獨树，皋亭望列村，寂寥還蓋靖，荒茫歸路昏，挽铎已流唱，童歌行自喧，眷言千載後，誰將遊九原。","sortOrder":74},
  {"id":"s_work_nvlt_34_75","chapterId":"ch_work_nvlt_34","text":"又送劉中書葬詩曰：昔別傷南浦，今悲去北邙，書生空讬夢，久客每思乡，塞近邊雲黑，尘昏野日黃，陵穀俄遷变，松柏易荒涼，題銘無复跡，何處验龟長。","sortOrder":75},
  {"id":"s_work_nvlt_34_76","chapterId":"ch_work_nvlt_34","text":"陳沈蜅望郢州城詩曰：魂兮何處反，非死复非仙，坐柯如昨日，石合未淹年，歷陽頓成浦，東海果為田，空憶扶風詠，誰見峴山傳，世变才良改，時移民物遷，悲哉孫驃騎，悠悠哭彼天。","sortOrder":76},
  {"id":"s_work_nvlt_34_77","chapterId":"ch_work_nvlt_34","text":"又長安還至方山怆然自傷詩曰：秦軍坑趙卒，遂有一人生，雖還舊乡里，危心曾未平，淮源比桐柏，方山似削成，猶疑屯虜騎，尚畏值胡兵，空村餘拱木，废邑有頹城，舊識莫不盡，新知皆異名，百年三萬日，處處此傷情。","sortOrder":77},
  {"id":"s_work_nvlt_34_78","chapterId":"ch_work_nvlt_34","text":"陳陰铿和樊晉陵傷妾詩曰：畫梁朝日盡，芳树落花辭，忽以千金笑，長作九泉悲，鏡前尘剧粉，機上網多絲，戶餘双入燕，床有一空帷，名香不可得，何見反魂時。","sortOrder":78},
  {"id":"s_work_nvlt_34_79","chapterId":"ch_work_nvlt_34","text":"陳張正見銅爵台詩曰：荒涼銅爵晚，搖落墓田通，雲惨當歌日，松吟欲舞風，人疏瑤席冷，曲罢繐帷空，可惜年將淚，俱盡望陵中。","sortOrder":79},
  {"id":"s_work_nvlt_34_80","chapterId":"ch_work_nvlt_34","text":"隋江總奉和東宮經故妃舊殿詩曰：故殿看看冷，空階步步悲，猶憶窥窗處，還如解珮時，苔生無意早，燕入有言遲，若令歸就月，照見不須疑。","sortOrder":80},
  {"id":"s_work_nvlt_34_81","chapterId":"ch_work_nvlt_34","text":"又傷顧野王詩曰：獨酌一樽酒，高詠七哀詩，何言蒿里別，非复竹林期，階荒鄭公草，戶阒董生帷，人隨暮槿落，客共晚湋悲，年發兩如此，傷心獨幾時。","sortOrder":81},
  {"id":"s_work_nvlt_34_82","chapterId":"ch_work_nvlt_34","text":"又和張源傷往詩曰：小婦當爐夜，夫婿凯師年，正歌千里曲，翻入九重泉，機中未斷素，瑟上本留絃，空帳臨窗掩，孤燈向壁燃，還悲塞垄曙，松短未生煙。","sortOrder":82},
  {"id":"s_work_nvlt_34_83","chapterId":"ch_work_nvlt_34","text":"【賦】漢武帝李夫人賦曰：飾新宮以延佇，泯不歸乎故乡，惨鬱鬱其芜秽，處隱隱而懷傷，釋舆馬於山椒，奄修夜之不陽，秋氣憯以凄戾，桂枝落而消亡，神茕茕以遙思，精浮遊而出彊，讬沉陰以曠久，惜繁華之未央，念窮極之不逮，惟要妙而相佯。","sortOrder":83},
  {"id":"s_work_nvlt_34_84","chapterId":"ch_work_nvlt_34","text":"後漢蘇順叹懷賦曰：悲終風之陨{⺮釋}，條枝梢以摧傷，桂敷榮而方盛，遭暮冬之隆霜，華菲菲之將實，中夭零而消亡，童乌濬其明哲，悲何寿之不將，嗟劉生之若茲，奄弥留而永丧。","sortOrder":84},
  {"id":"s_work_nvlt_34_85","chapterId":"ch_work_nvlt_34","text":"魏文帝悼夭賦曰：族弟文仲，亡時年十一，母氏傷其夭逝，追悼無已，予以宗族之愛，乃作斯賦，氣紆結以填胸，不知涕之縱橫，時徘徊於舊處，睹靈衣之在床。感遺物之如故，痛爾身之獨亡，愁端坐而無聊，心慼慼而不寧，步廣厦而踟蹰，覽萱草於中庭，悲風萧其夜起，秋氣憯以厲情，仰瞻天而太息，聞別鳥之哀鳴。","sortOrder":85},
  {"id":"s_work_nvlt_34_86","chapterId":"ch_work_nvlt_34","text":"又寡婦賦曰：陳留阮元瑜早亡，每感存其遺孤，未嘗不怆然傷心，故作斯賦，惟生民兮艱危，在孤寡兮常悲，人皆處兮歡樂，我獨怨兮無依，撫遺孤兮太息，俯哀傷兮告誰，三辰周兮遞照，寒暑運兮代臻，歷夏日兮苦長，涉秋夜兮漫漫，微霜陨兮集庭，燕雀飛兮我前，去秋兮就冬，改節兮時寒，水凝兮成冰，雪落兮翻翻，傷薄命兮寡獨，內惆怅兮自怜。","sortOrder":86},
  {"id":"s_work_nvlt_34_87","chapterId":"ch_work_nvlt_34","text":"又感物賦曰：丧亂以來，天下城郭丘墟，惟從太仆君宅尚在，南征荆州，還過乡里，舍焉，乃种諸蔗於中庭，涉夏歷秋，先盛後衰，悟興废之無常，慨然永叹，乃作斯賦，伊陽春之散節，悟乾坤之交靈，瞻玄雲之蓊鬱，仰沉陰之杳冥，降甘雨之丰霈，垂長溜之泠泠，掘中堂而為圃，植諸蔗於前庭，涉炎夏而既盛，迄凛秋而將衰，豈在斯之獨然，信人物其有之。","sortOrder":87},
  {"id":"s_work_nvlt_34_88","chapterId":"ch_work_nvlt_34","text":"魏陳王曹植慰子賦曰：彼凡人之相親，小離別而懷恋，况中殇之愛子，乃千秋而不見，入空室而獨倚，對床帷而切叹，痛人亡而物在，心何忍而复觀，日晼晚而既没，月代照而舒光，仰列星以至晨，衣霑露而含霜，惟逝者之日遠，怆傷心而絕腸。","sortOrder":88},
  {"id":"s_work_nvlt_34_89","chapterId":"ch_work_nvlt_34","text":"魏高貴乡公傷魂賦曰：王師東征，宗正曹併，以宗室材能，兼侍中從行，到頃得疾，數日亡，意甚傷之，為作此賦，宗臣充於常伯，體材藝而中良，何旻天之不怙，遘暴疾而陨亡，惟厥疾之初發，若常疾之輕微，未經日而况篤，氣惙々而耗衰，歧鵲騁技而弗救，豈藥石之能追，精魂忽已消散，神眇眇而長违。","sortOrder":89},
  {"id":"s_work_nvlt_34_90","chapterId":"ch_work_nvlt_34","text":"魏王粲傷夭賦曰：惟皇天之賦命，實浩荡而不均，或老終以長世，或昏夭而夙泯，物雖存而人亡，心惆怅而長慕，哀皇天之不惠，抱此哀而何愬，求魂神之形影，羌幽冥而弗迕，淹低徊以想像，心弥結而紆萦，晝忽忽其若昏，夜蜅蜅而至明。","sortOrder":90},
  {"id":"s_work_nvlt_34_91","chapterId":"ch_work_nvlt_34","text":"又思友賦曰：登城隅之高觀，忽臨下以翱翔，行遊目於林中，睹舊人之故場，身既没而不見，餘跡存而未丧，沧浪浩兮回流波，水石激兮扬素精，夏木兮結茎，春鳥兮愁鳴，平原兮泱莽，绿草兮羅生，超長路兮逶迤，實舊人兮所經，身既逝兮幽翳，魂眇眇兮藏形。又寡婦賦曰：阖門兮却扫，幽處兮高堂，提孤孩兮出戶，與之步兮東厢，顧左右兮相怜，意凄怆兮摧傷，觀草木兮敷榮，感傾葉兮落時，人皆懷兮歡豫，我獨感兮不怡，日掩暧兮不昏，朗月皎兮扬暉，坐幽室兮無為，登空床兮下帏，涕流連兮交頸，心憯結兮增悲。","sortOrder":91},
  {"id":"s_work_nvlt_34_92","chapterId":"ch_work_nvlt_34","text":"魏丁廙妻寡婦賦曰：惟女子之有行，固歷代之彝倫，辭父母而言歸，奉君子之情尘，如懸萝之附松，似浮萍之讬津，何性命之不造，遭世路之险迍，榮華晔其始茂，所恃奄其徂泯，靜閉門以却扫，魂孤茕以窮居，刷朱扉以白堊，易玄帳以素帱，含惨悴以何訴，抱弱子以自慰，時翳翳以東陰，日亹亹以西墜，雞斂翼以登栖，雀分散以赴肆，還空床以下帷，拂衾褥以安寐，想逝者之有凭，因宵夜之仿佛，痛存没之異路，終窈漠而不至，時荏苒而不留，將遷靈以大行，駕龍轜於門侧，設祖祭於前廊，彼生離其猶難，矧永絕而不傷，自衔恤而在疚，履冰冬之四節，風萧萧而增劲，寒凛凛而弥切，霜凄凄而夜降，水溓々而晨結，瞻靈宇之空虛，悲屏幌之徒設，仰皇天而叹息，腸一日而九結，惟人生於世上，若馳骥之過櫺，計先後其何幾，亦同歸乎幽冥。","sortOrder":92},
  {"id":"s_work_nvlt_34_93","chapterId":"ch_work_nvlt_34","text":"晉陆機叹逝賦曰：昔每聞長老，追計平生同時親故，或曾共遊一途，同宴一室，十年之外，索然已盡，以是思哀，哀可知矣，賦曰：悲夫，川閱水以成川，水滔滔而日度，世閱人而為世，人冉冉而行暮，人何世而弗新，世何人之能故，亮造化之若茲，吾安取夫久長，痛靈根之夙陨，怨具爾之多丧，悼堂構之隤瘁，愍城闕之丘荒，親弥懿其已逝，交何戚而不亡，弥年時之詎幾，夫何往而不殘，或冥邈而既盡，或寥廓而仅半，信松茂而柏悅，嗟芝焚而蕙叹，苟性命之弗殊，豈同波而異澜，年弥往而念廣，涂薄暮而迫迮，顧舊要於遺存，得十一於千百。","sortOrder":93},
  {"id":"s_work_nvlt_34_94","chapterId":"ch_work_nvlt_34","text":"又愍思賦曰：予屢抱孔懷之痛，而奄复丧同生姊，衔恤哀傷，一載之間，而丧製便過，故作此賦，以纾惨惻之感，時方至其儵忽，歲既去其晼晚，樂來日之有繼，傷頹年之莫纂，覽萬物以澄念，怨伯姊之已遠，尋遺尘之思長，瞻日月之何短，升降乎階际，顧眄兮屏營，雲承宇兮藹藹，風入室兮泠泠，仆從為我悲，孤鳥為我鳴。","sortOrder":94},
  {"id":"s_work_nvlt_34_95","chapterId":"ch_work_nvlt_34","text":"又大暮賦曰：夫死生是失得之大者，故樂莫甚焉，哀莫深焉，使死而有知乎，安知其不如生，如遂無知耶。又何生之足恋，故極言其哀，而終之以達，庶以开夫近俗雲，夫何天地之遼闊，而人生之不可久長，日引月而併陨，時惟歲而俱丧，徒假原於須臾，指夕景而為誓，忽呼吸而不振，奄神徂而形獘，於是六親雲起，姻族如林，爭涂掩淚，望門舉音，敷幄席以悠想，陳備物而虞靈，仰寥廓而無見，俯寂寞而無聲，肴饛饛其不毀，酒湛湛而每盈，屯送客於山足，伏埏道而哭之，扃幽戶以大畢，溯玄闕而長辭，歸無涂兮往不反，年弥去兮逝弥遠，弥遠兮日隔，無涂兮曷因，庭树兮葉落，暮草兮根陳。","sortOrder":95},
  {"id":"s_work_nvlt_34_96","chapterId":"ch_work_nvlt_34","text":"晉潘嶽悼亡賦曰：伊良嫔之初降，幾二紀以迄茲，遭兩門之不造，備荼毒而嘗之，婴生艱之至極。又薄命而早終，含芬華之芳列，翩零落而從風，神飄忽而不反，形焉得而久安，袭時服於遺质，表鉛華於餘顏，問筮嫔之何期，宵過分而參阑，詎幾時而見之，目眷恋以相屬，聽诹人之唱筹，來聲叫以連續，聞冬夜之恒長，何此夕之一促，且伉俪之片合，垂明哲乎嘉禮，苟此義之不谬，乃全身之半體，吾聞丧禮之在妻，謂製重而哀輕，既履冰而知寒，吾今信其緣情，夕既昏兮朝既清，延爾族兮臨後庭，入空室兮望靈座，帷飄飄兮燈熒熒，燈熒熒兮如故，帷飄飄兮若存，物未改兮人已化，饋生尘兮酒停樽，春風兮泮冰，初陽兮戒溫，逝搖搖兮浸遠，嗟茕茕兮孤魂。","sortOrder":96},
  {"id":"s_work_nvlt_34_97","chapterId":"ch_work_nvlt_34","text":"又寡婦賦曰：樂安任子鹹者，予少而歡焉，不幸弱冠而終，其妻又吾姨也，故作斯賦，伊女子之有行，爰奉嫔於高族，承慶雲之光覆，荷君子之恩渥，奉蒸嘗之效順，供洒埽以弥載，榮華晔其始茂，良人忽以損背，愁煩冤其誰告，提孤孩於坐侧，時暧暧而向昏，日杳杳而西匿，雀群飛而赴楹，雞登栖而斂翼，歸空馆而自怜，撫衾帱以叹息，耳傾想於畴昔，目仿佛乎平素，雖冥冥而罔觌，猶依依以凭附，自仲夏而在疾，逾履霜以踐冰，雪霏霏而骤落，風瀏瀏而夙興，意惚恍以遷越，神一夕而九升，庶浸遠而哀降，情惻惻而弥甚，原假夢以通靈，目蜅蜅而不寢，夜漫漫以悠悠，寒凄凄以凛凛，氣憤薄以乘焜，涕交橫而流枕，重曰：仰皇天兮叹息，私自怜兮何極，省微躬兮孤弱，顧稚子兮未識，如涉川兮無津，若陵虛兮失翼。","sortOrder":97},
  {"id":"s_work_nvlt_34_98","chapterId":"ch_work_nvlt_34","text":"晉王浑妻鍾遐思賦曰：惟仲秋之惨凄，百草萎悴而变衰，燕翔逝而歸海，蟋蟀鳴而相追，坐虛堂而無寥，嗟我心之多懷，怅遐思而內結，嗟爾薑任，邈不我留，謀民生之未幾，吾何為其多愁，涼風萧條，露霑我衣，忧來多方，慨然永懷，感飛鳥之反乡，詠衛女之思歸，於是周遊容與，逍遙彷徨，悲民生之局促，原輕舉之遐翔。","sortOrder":98},
  {"id":"s_work_nvlt_34_99","chapterId":"ch_work_nvlt_34","text":"晉劉［按當作紐。］滔母孫氏悼艱賦曰：伊禀命之不辰，遭天難之靡忱，夙無父之何怙，哀壅瘁以抽心，覽蓼莪之遺詠，詠肥泉之餘音，經四位之代謝，雖積祀而思深，伊三從而有歸，爰奉嫔於他族，仰慈姑之惠和，荷仁泽之陶渥，釋褧服以斬衣，代羅帷以縞布，仰慈尊以飲泣，撫孤景以协慕，遇飛廉之暴骸，觸驚風之所會，扶搖奋而上跻，頹雲下而無际，頓餘邑之當春，望峻陵而鬱青，瞻空宇之寥廓，愍宿草之發生，顧南枝以永哀，向北風以飲泣，情無觸而不悲，思無慼而不集。","sortOrder":99},
  {"id":"s_work_nvlt_34_100","chapterId":"ch_work_nvlt_34","text":"宋孝武帝擬漢武帝李夫人賦曰：觀周氏之逸篇，覽漢室之遺篆，弔新宮之掩映，嗟璧台之芜踐，雖媛德之有載，竟滯悲其何遣，念桂枝之秋霣，惜瑤華之春翦，彤殿閉兮素尘積，翠戺芜兮紫苔生，寶羅暍兮春幌重，珍簟空兮夏帱局，秋台惻兮碧煙凝，冬宮冽兮朱火青，流津有終，深心無歇，徙倚雲日，徘徊風月，思玉步於鳳墀，想金聲於鸞闕。","sortOrder":100},
  {"id":"s_work_nvlt_34_101","chapterId":"ch_work_nvlt_34","text":"宋謝靈運感時賦曰：夫逝物之感，有生所同，頹年致悲，時懼其速，豈能忘懷，乃作斯賦，相物類以迨已，闵交臂之匪賒，揆大耋之或遄，指崦嵫於西河，鑒三命於予躬，怛行年之蹉跎，於鶗窸之先號，挹芬芳而夙過，微靈芝之頻秀，迫朝露其如何，雖發叹之早晏，谅大暮之同科。","sortOrder":101},
  {"id":"s_work_nvlt_34_102","chapterId":"ch_work_nvlt_34","text":"又傷己賦曰：嗟夫，卞賞珍於連城，孫別駿於千里，彼珍駿以貽愛，此陋容其敢擬，丁曠代之渥惠，遭谬眷於君子，眺徂歲之骤經，睹芳春之每始，始春芳而羨物，終歲徂而感己，貌憔悴以衰形，意幽翳而苦心，出衾裯而載坐，辟襜幌以迥臨，望步襜而周流，眺幽閨之清陰，想輕綦之往跡，餐和聲之餘音，播芬煙而不燻，張明鏡而不照，歌白華而絕曲，奏蒲生之促調。","sortOrder":102},
  {"id":"s_work_nvlt_34_103","chapterId":"ch_work_nvlt_34","text":"宋顏延之行殣賦曰：嗟我來之雲遠，睹行殣於水隅，崩朽棺以掩曠，仰枯顙而枕衢，資沙砾以含實，藉水草之襚储，撫躬中涂，太息蘭渚，行徘徊於永路，時悄怆於川侣。","sortOrder":103},
  {"id":"s_work_nvlt_34_104","chapterId":"ch_work_nvlt_34","text":"宋鮑昭傷逝賦曰：晨登南山，望美中河，露团秋槿，風卷寒萝，凄怆傷心，悲如之何，盡若窮煙，離若箭絃，如影滅地，猶星殒天，弃華宇於明世，閒金扃於下泉，修堂庑而下降，歷帏戶而升基，志存業而遺緒，身先物而長辭，日月飄而不留，命鯈忽而誰保，發迎忧而送華，貌先悴而收藻。","sortOrder":104},
  {"id":"s_work_nvlt_34_105","chapterId":"ch_work_nvlt_34","text":"梁沈約傷美人賦曰：信美顏其如玉，咀清畦而度曲，思佳人而未來，望餘光而踯躅，拂螭雲之高帳，陳九枝之華燭，虛翡翠之珠被，空合歡之芳褥，言歡愛之可永，庶羅袂之空裁，曾未申其巧笑，忽淪軀於夜台，伊芳春之仲節，夜猶長而未遽，怅徙倚而不眠，住徘徊於故處。","sortOrder":105},
  {"id":"s_work_nvlt_34_106","chapterId":"ch_work_nvlt_34","text":"梁江淹傷友人賦曰：靜然霑衣兮，悲袁友之英秀，系神緒而作氏，胤靈枝而作胄，轹四代而式昌，洎十葉而克茂，友人之生，川岫降明，譬如冬雪，既華既絜，將似秋月，至麗至彻，乃上代而少双，故叔世而曠絕，弔蕙若之暫芳，恸琬琰之永缺，餘幼好於斯人，乃神交於一顧，邈畴年之繾綣，窈生平之遊遇，懷愛重於素璧，結分珍於黃金，舍一世而笑淺，訪古人而求深，固齊術而共径，豈異袖而同襟，爾凝情於霜柏，我發志於冬桂，帶瑤玉而爭光，握隨珠而比麗，予結誼兮梁門，复從宦兮朱蕃，何人径之亟阻，而天道之匪存，凋碧玉之神树，銷紫芝之靈根，承遠書於江澨，結深痛於爾魂。","sortOrder":106},
  {"id":"s_work_nvlt_34_107","chapterId":"ch_work_nvlt_34","text":"梁萧子范傷往賦曰：彼蘭菊之芳茂，及蕖槿之榮色，終於邑乎繁霜，俱飄飖於路侧，引輕華之微珍，猶見嗟於有識，况獨立之妍媛，信盈盈而挺植，去倡家而來儀，承君子之宴息，摧麗容而思進，豈蛾眉之肯抑，詠美媵而自箴，歌忠妾而為式，痛妖姿之不留，惜華年之中夭，冀羆祥之永慶，忽從飆而先摽，魂一逝而莫追，夕有長而無晓，惟君侯之惆怅，覽遺物而霑巾，惟半垂而將下，尚仿像而疑真，懷方士之良術，顯有凭而致神。","sortOrder":107},
  {"id":"s_work_nvlt_34_108","chapterId":"ch_work_nvlt_34","text":"周庾信哀江南賦曰：粵以戊辰之年，建亥之月，大盜移國，金陵瓦解，信年始二毛，即逢丧亂，狼狽流離，至於暮齒，燕河遠別，悲不自勝，楚老相逢，泣將何及，鍾儀君子，入就南冠之囚，季孫行人，留守西河之馆，申包胥之頓地，碎之以首，蔡威公之淚盡，加之以血，孫策以天下為三分，眾裁一旅，項羽用江東之子弟，人唯八千，遂乃分裂山河，宰割天下，豈有百萬義師，一朝卷甲，芟夷斬伐，如草木焉，江淮無涯岸之阻，亭壁無蕃篱之固，將非江表王氣，應終三百年乎，呜呼，山嶽崩頹，既有危亡之運，春秋迭代，必有去故之悲，天意人事，可以凄怆傷心者矣，賦曰：始則王子召戎，奸臣介胄，既官政而離逷，遂師言而泄漏，爾乃杰黠構扇，凭陵畿甸，青袍如草，白馬如練，天子履端废朝，单於長围高宴，竟遭夏台之禍，遂睹尧城之变，遂乃韓分趙裂，鼓臥旗折，失群班馬，迷输亂轍，猛士婴城，謀臣卷舌，崑陽之戰象走林，常山之陣蛇奔穴，五郡則兄弟相悲，三州則父子離別，於是桂林顛覆，長洲麋鹿，潰潰沸騰，茫茫惨黷，競動天關，爭回乾軸，探雀鷇而未飽，待熊蹯而詎熟，乃有車侧郭門，筋懸廟屋，鬼同曹社之謀，人有秦庭之哭，西瞻博望，地臨玄圃，月榭風台，池平树古，仁寿之鏡徒懸，茂陵之書空聚，中宗之夷凶靜亂，大雪冤恥，去代邸而承基，遷唐郊而纂祀，反舊章於司隸，歸餘風於正始，沉猜則方逞其欲，藏疾則自矜於己，天下之事没焉，諸侯之心搖矣，既而齊交北絕，秦患西起，况背關而坏楚，異端委而开吳，驅绿林之散卒，拒驪山之叛徒，問諸淫昏之鬼，求諸厭劾之巫，荆門遭廪延之戮，夏口濫逵泉之誅，况以沴氣宵浮，妖精夜殒，赤鳥則終朝夹日，蒼雲則七重围軫，亡吳之歲既窮，入郢之年斯盡，周含鄭怒，楚結秦怨，有南風之不競，值西鄰之责言，俄而梯冲亂舞，冀馬雲屯，栈秦車於畅轂，沓漢鼓於雷門，雖复楚有七泽，人稱三戶，辭洞庭兮落木，去涔陽兮極浦，炽火兮焚旗，貞風兮害蠱，乃使玉軸扬灰，龍文析柱，下江餘城，長林故營，徒思□［本集作拑。］馬之秣，未見燒牛之兵，章曼友以轂走，宮之奇以族行，河無小而馬渡，關未晓而雞鳴，忠臣解骨，君子吞聲，章華望祭之所，雲夢伪遊之地，荒穀縊於莫敖，冶甫囚乎群師，［本集作帥。］硎阱摺拉，鷹鹯扌此扌費，於時瓦解冰泮風飛雹散，浑然千里，淄沔一亂，雪暗如沙，冰橫如岸，逢赴洛之陆機，見離家之王粲，莫不聞隴水而掩泣，向關山而長叹。","sortOrder":108},
  {"id":"s_work_nvlt_34_109","chapterId":"ch_work_nvlt_34","text":"又傷心賦曰：予五福無徵，三靈用譴，至於繼體，多從夭折，二男二女，併得勝衣，金陵丧亂，相守亡没，苗而不秀，頻有所悲，唯覺傷心，遂以傷心為賦，悲哉秋氣，搖落变衰，魂兮遠矣，何去何依，望思無望，歸來不歸，未達東門之意，空懼西河之譏，在昔金陵，天下丧亂，王室版荡，生人涂炭，兄弟則五郡分張，父子則三州離散，地鼎沸於袁曹，人銶狼於楚漢，或有擁树離灾，藏衣遭難，未設桑弧，先空柘馆，人惟一丘，亭遂千秋，邊韶永恨，孫楚長愁，張壮武之心亡，羊南城之淚流，痛斯傳體，尋茲世載，天道斯慈，人倫此愛，膝下龍摧，掌中珠碎，芝在室而先枯，蘭生庭而早刈，况乃流寓秦川，飄飖播遷，從宦非宦，歸田不田，對玉關而羁旅，坐長河而暮年，以觸目之萬恨，更傷心於九泉。","sortOrder":109},
  {"id":"s_work_nvlt_34_110","chapterId":"ch_work_nvlt_34","text":"【哀辭】魏陳王曹植金瓠哀辭，予之首女，雖未能言，固以授色知心矣，生十九旬而夭折，乃作此辭曰：在襁褓而撫育，向孩笑而未言，不終年而夭絕，何負罰於皇天，信吾罪之所招，悲弱子之無愆，去父母之懷抱，滅微骸於粪土，天地長久，人生幾時，先後無覺，從爾有期。","sortOrder":110},
  {"id":"s_work_nvlt_34_111","chapterId":"ch_work_nvlt_34","text":"又行女哀辭曰：行女生於季秋，而終於首夏，三年之中，二子頻丧，伊上靈之降命，何短修之難裁，或華發以終年，或懷妊而逢灾，感前哀之未阕，复新殃之重來，方朝華而晚敷，比晨露而先晞，感逝者之不追，情忽忽而失度，天蓋高而無階，懷此恨其誰訴。","sortOrder":111},
  {"id":"s_work_nvlt_34_112","chapterId":"ch_work_nvlt_34","text":"又仲雍哀辭曰：曹喈，字仲雍，魏太子之中子也，三月生而五月亡，昔後稷之在寒冰，斗穀之在楚泽，鹹依鳥凭虎，而無風尘之灾，今之玄第文茵，無寒冰之惨，羅帱綺帳，暖於翔禽之翼，幽房閒宇，密於雲夢之野，慈母良保，仁乎乌菟之情，卒不能延期於期載，離六旬而夭没，彼孤蘭之眇眇，亮成幹其畢榮，哀綿綿之弱子，早背世而潛形，且四孟之未周，將何原乎一齡，陰雲回於素蓋，悲風動其扶輪，臨埏闼以歔欷，淚流射而霑巾。","sortOrder":112},
  {"id":"s_work_nvlt_34_113","chapterId":"ch_work_nvlt_34","text":"晉陆機吳大司馬六公少女哀辭曰：冉冉晞陽，不遂其茂，晔晔芳華，凋芳落秀，遵堂涉室，仿佛興想，人皆有聲，爾獨無响。","sortOrder":113},
  {"id":"s_work_nvlt_34_114","chapterId":"ch_work_nvlt_34","text":"晉潘嶽哀永逝辭曰：逝日長兮生年淺，忧患眾兮歡樂鮮，怅怅兮遲遲，遵古路兮凶歸，思其人兮已滅，覽餘跡兮未夷，昔同涂兮今異世，憶舊歡兮增新悲，謂原隰兮無畔，謂川流兮無岸，视天日兮蒼茫，面邑里兮萧散，匪外物兮或改，固歡哀兮情換，歸反哭兮殯宮，聲有止兮哀無終，既顧瞻兮家道，長寄心兮爾躬。","sortOrder":114},
  {"id":"s_work_nvlt_34_115","chapterId":"ch_work_nvlt_34","text":"又傷弱子辭曰：予之長安，次於新安千秋亭，而弱子夭，感嬴博之哀，乃傷之曰：奈何兮弱子，邈弃爾兮丘林，還眺兮墳瘞，草莽莽兮木森森，伊遂古之遐胄，逮祖考之永延，咨吾家之不嗣，羌一適之未甄，仰崇堂之遺構，若無津而涉川，葉落永離，覆水不收，赤子何辜，罪我之由。","sortOrder":115},
  {"id":"s_work_nvlt_34_116","chapterId":"ch_work_nvlt_34","text":"又金鹿哀辭曰：嗟我金鹿，天資特挺，鬒發凝膚，蛾眉蛴領，柔情和泰，朗心聰警，呜呼上天，胡忍我門，良嫔短世，令子夭昏，既披我幹。又翦我根，槐如瘣木，枯荄獨存，捐子中野，遵我歸路，將反如疑，回首長顧。","sortOrder":116},
  {"id":"s_work_nvlt_34_117","chapterId":"ch_work_nvlt_34","text":"又陽城劉氏妹哀辭曰：鳥鳴於桓，乌號於荆，徘徊踯躅，立聞其聲，相彼羽族，矧伊人情，叩心長叫，痛我同生，誕育聖王，發奇稚齒，如彼名駒，昴昴千里，劉氏□［冯校本雲，氏下缺文。］懷寶，未曜隨和，伊予輕弱，弗克負荷，祿微於朝，财匮於家，俾我令妹，勤俭備加，珍羞罕御，器服靡華，撫膺恨毒，逝矣奈何，哀哀母氏，蒸蒸聖慈，震恸擗摽，何痛如之，魂而有靈，豈不慕思，嗟哉往矣，當复何時。","sortOrder":117},
  {"id":"s_work_nvlt_34_118","chapterId":"ch_work_nvlt_34","text":"又悲邢生曰：周文公之苗裔，予元舅之洪胄，厲操確其不拔，乡譽著而日就，妙邦畿而高察，雄州闾以擢秀，茂實畅矣，而休名未衍，其财至貧，其位至賤，而死之日，奔者盈庭，停餘車而在郊，撫靈榇以增悲，瞻轜容而想像，曾無觌乎餘辉，送子兮境垂，永訣兮路歧，一別兮長絕，盡哀兮告離。","sortOrder":118},
  {"id":"s_work_nvlt_34_119","chapterId":"ch_work_nvlt_34","text":"又京陵女公子王氏哀辭曰：猗欤公子，季女惟王，生自洪胄，禀茲義方，盼倩粲麗，窈窕淑良，如彼春蘭，吐葩含芳，葩以霜陨，芳以歇盡，彼蒼者天，胡寧斯忍，曾未弱笄，無疾而陨，宮朝震驚，靡人不愍，嗟爾母氏，劬勞撫鞠，恩斯勤斯，是長是育，帷屏媚子，奄離顧复，哀無废心，涕不輟目，於以祖之，於掖閨庭，於以送之，陵岗崔嵬，仆馬回眷，旗旐旋飛，夕陽失映，晴鳥忘歸，皎皎宵月，載盈載微，冥冥公子，一往不追，長夜無旦，孤魂曷依。","sortOrder":119},
  {"id":"s_work_nvlt_34_120","chapterId":"ch_work_nvlt_34","text":"又為任子鹹妻作孤女泽蘭哀辭曰：茫茫造化，爰啟英淑，猗猗泽蘭，應靈誕育，須發蛾眉，巧笑美目，顏耀榮苕，華茂時菊，如金之精，如蘭之馥，淑质弥畅，聰惠日新，朝夕顧复，夙夜盡勤，彼蒼者天，哀此矜人，胡寧不惠，忍予眇身，俾爾婴孺，微命弗振，俯覽衾襚，仰訴穹旻，弱子在懷，既生不遂，存靡讬躬，没無遺類，耳存遺响，目想餘顏，寢席伏枕，摧心剖肝，相彼鳥矣，和鳴嘤嘤，矧伊蘭子，音影冥冥，彷徨丘垄，徙倚墳塋。","sortOrder":120},
  {"id":"s_work_nvlt_34_121","chapterId":"ch_work_nvlt_34","text":"【文】又為楊長文作弟仲武哀祝文曰：悠悠上天，我獨何辜，祖考早世，兄弟幼孤，備嘗艱毒，同集蓼荼，父兮生我，過庭靡聞，母兮鞠我，寧一苦辛，日顧日复，我弟我身，併自垂發，越於成人，濬哲聰朗，純粹溫良，烈烈清風，邦族之望，母氏劬勞，庶爾之報，彼蒼者天，子何不弔，殲我令弟，窮泉是造，無父何怙，無弟何友，茕茕此身，哀哀慈母，煩冤痛毒，撫心思咎，哀爾薄祐，逢家多阻，弱冠未室，盛年絕緒，丧庭寥廓，庐位無主，冥冥長夜，窈窈玄宇，當复何時，見我仲武，於以祔之，於其王父，魂而有靈，神其寧處。","sortOrder":121},
  {"id":"s_work_nvlt_34_122","chapterId":"ch_work_nvlt_34","text":"晉孫楚和氏外孫道生哀文曰：嗟爾道生，和氏之寶，玉顏丰下，曜於懷抱，暮春而育，孟冬而夭，二十三旬，奇於五日，方之期颐，百分之一，命之脩短，始則有終，誰能長久，與天無窮，籛翁近千，殇子幼冲，俱反無形，冥昧之中，造化多少，豈獨爾躬。","sortOrder":122},
  {"id":"s_work_nvlt_34_123","chapterId":"ch_work_nvlt_34","text":"又和氏外孫小同哀文曰：晔晔蕣華，朝生夕落，爾命方之，猶為淺薄，暫有冥质，尋友冥漠，譬彼蜉蝣，不識晦朔，死尚未知，生亦焉知，爾雖旬月，我未之视，萬物混焉，天地一指，杪末婴孩，安足稱诔，大人達觀，同之一揆。","sortOrder":123},
  {"id":"s_work_nvlt_34_124","chapterId":"ch_work_nvlt_34","text":"又胡母夫人哀辭曰：滔滔汶川，浩浩雲漢，乃眷洪族，裁育英媛，幼挺芳烈，暉光日新，有美其猗，有彪其文，華茂春芳，志厲秋霜，邂逅之遇，遘茲良會，豈惟中饋，義形於外，恒凭賢明，以自休賴，冀享永年，偕老一世，景命伊何，忽然長逝。","sortOrder":124},
  {"id":"s_work_nvlt_34_125","chapterId":"ch_work_nvlt_34","text":"梁簡文帝大同哀辭曰：大同予第十子也，生於仲秋，殒於冬末，悲夫夕坐，於是申旦，當以食［文苑英華九百九十九作食以。］之不甘，客謂予曰：死生常也，夭寿命也，陳蕃所憩之家，久記玄錄之歲，華歆［原訛欹，據冯校本改。］所間［英華作聞。］之語，已定北陵之期，上聖所以忘情，賢者所以達節，將何戚焉，予對之曰：觀其明眸丰下，玉色和聲，豈不登髫歲而擬觸藩，反［英華作及。］紈袴而仰折李，靈心摧於毫末，慧識挫於跬步，豈不傷哉，乃為辭曰：彼神蔡之靈長，獲萬春之悠緬，有蕣華之灼灼，寄一朝之浮淺，信歡慰之未幾，悼夭零之雲及，乃变樂而為悲，遂改笑而成泣。","sortOrder":125},
  {"id":"s_work_nvlt_34_126","chapterId":"ch_work_nvlt_34","text":"【書】晉劉臻妻陳氏答舅母書曰：元方春秋始富，德業亦隆，弘道博文，才质兼備，冀志與時畅，榮耀當年，豈意一朝，冥然長往，元方冲幼，過庭莫聞，聖善明訓，業成三徙，亦既冠婚，双譽允集，庶幾偕老，色養膝下，而殃厲橫流，艱禍仍遘，媛姊傾逝，宗模永絕，姊方玄華，併夭戚年，豈慮豈圖，禍降弥酷，良才夭於始立，崇基殒於一匮，仰痛殄滅，俯悼二弟，斯人斯命，當可奈何，母年逾耳順，備經百罹，一紀之中，四遘至痛，目前廓然，三從靡讬，窮悼中發，情馳難處。","sortOrder":126},
  {"id":"s_work_nvlt_34_127","chapterId":"ch_work_nvlt_34","text":"梁任昉與沈約書曰：范仆射遂不救疾，范侯淳孝睦友，在家必聞，直道正色，立朝斯著，一金之俸，必遍親倫，鍾庾之秩，散之故舊，佐命興王，心力俱盡，謀猷忠允，谅誠匪躬，破產而字死友之孤，开門而延故人之殯，則惟其常，無得而稱矣，器用車馬，無改平生之凭，素論款對，不易布素之交，若斯人者，豈雲易遇，昉將莅此邦，務在遄速，雖解駕流連，再貽款顧，將乖之际，不忍告別，無益離悲，祗增今恨，永念平生，忽焉畴曩，追尋笑緒，皆成悲端。","sortOrder":127},
  {"id":"s_work_nvlt_34_128","chapterId":"ch_work_nvlt_34","text":"又弔樂永世書曰：永世孝友之至，發自天真，皎絜之操，曾非矯飾，意有所固，白刃不移，理有所讬，淄渑自辨，餘息惟存，视陰無幾，終始之讬，方寄祁侯，豈謂樂生，反先朝露，以理遣滯，鄙識未晓，以事尋悲，哀楚交至，宿草易滋，傷恨不滅，松槚可拱，悲緒無窮。","sortOrder":128},
  {"id":"s_work_nvlt_34_129","chapterId":"ch_work_nvlt_34","text":"梁劉孝標追答劉沼書曰：劉侯既有斯難，值予有天倫之職，［《文選》四十三作戚。］竟未之致也，尋而此君長逝，化為異物，緒言餘論，蘊而莫傳，或有自其家得而示予者，予悲其音徽未沫，而其人已亡，青簡尚新，而宿草將列，泫然不知涕之無從也，雖隙驷不留，尺波電謝，而秋菊春蘭，英華靡絕，故存其梗槩，更詶其旨，若使墨翟之言無爽，宣室之談有徵，冀東平之树，望鹹陽而西靡，蓋山之泉，聞絃歌而赴節，但懸劍空垅，有恨如何。","sortOrder":129},
  {"id":"s_work_nvlt_34_130","chapterId":"ch_work_nvlt_34","text":"《藝文類聚》　唐·欧陽詢","sortOrder":130},
  {"id":"s_work_nvlt_35_1","chapterId":"ch_work_nvlt_35","text":"卷三十五人部十九","sortOrder":1},
  {"id":"s_work_nvlt_35_2","chapterId":"ch_work_nvlt_35","text":"○妒淫愁泣貧奴婢佣保","sortOrder":2},
  {"id":"s_work_nvlt_35_4","chapterId":"ch_work_nvlt_35","text":"《左傳》曰：叔向之母妒，叔虎之母美而不使見，叔向諫，其母曰：深山大泽。實生龍蛇，彼美，餘懼而生龍蛇以禍汝，我何愛焉，使往侍寢，生叔虎。","sortOrder":4},
  {"id":"s_work_nvlt_35_5","chapterId":"ch_work_nvlt_35","text":"《毛詩序》曰：夫人無妒忌之行，惠及賤妾，進御於君，知其命有貴賤，能盡其心矣。","sortOrder":5},
  {"id":"s_work_nvlt_35_6","chapterId":"ch_work_nvlt_35","text":"又曰：不妒忌則子孫眾多矣。","sortOrder":6},
  {"id":"s_work_nvlt_35_7","chapterId":"ch_work_nvlt_35","text":"《山海經》曰：秦室山有木，葉如梨而赤理，其名曰指木，服之不妒。","sortOrder":7},
  {"id":"s_work_nvlt_35_8","chapterId":"ch_work_nvlt_35","text":"《文子》曰：爵高者人妒之，官大者王惡之，祿厚者怨處之。","sortOrder":8},
  {"id":"s_work_nvlt_35_9","chapterId":"ch_work_nvlt_35","text":"《漢書》曰：武帝陳皇後為妒，別在長門宮，司馬相如作賦，皇後复親幸。","sortOrder":9},
  {"id":"s_work_nvlt_35_10","chapterId":"ch_work_nvlt_35","text":"又曰：陳後寵衰，妒甚，令巫祭祀，以回上意。","sortOrder":10},
  {"id":"s_work_nvlt_35_11","chapterId":"ch_work_nvlt_35","text":"又曰：呂氏妒戚夫人，髡鉗赭衣使舂。又斷手足，去目重身，飲瘖藥，名曰人豕。","sortOrder":11},
  {"id":"s_work_nvlt_35_12","chapterId":"ch_work_nvlt_35","text":"又曰：廣川王去，嘗有疾，陽城昭信侍疾甚謹，去愛之，立為後。又有幸姬望卿，［原作乡，據冯校本改，下同。］為脩孊夫人，主繒帛，昭信谮望卿曰：與我無禮，衣服常鮮我。又傅粉，數南戶窥郎吏，疑有奸，去曰：伺之，益不愛望卿，昭信知去怒，誣言望卿，歷指郎吏臥處，具知其名，去即與昭信從諸姬至望卿室，裸形系之，令諸姬各持鐵共灼之，望卿自投井而死，昭信出之，椓陰中，割其鼻唇，斷舌，遂解置大镬中，取桃灰毒藥併煮之，令諸姬觀糜盡，乃止。","sortOrder":12},
  {"id":"s_work_nvlt_35_13","chapterId":"ch_work_nvlt_35","text":"冯敬通集曰：敬通有一婢，妻任酷妒之，击婢無所不至，敬通乃弃遣之，因與婦弟任武達書曰：不去此婦，則家不寧，不去此婦，則家不清，不去此婦，則福不生，不去此婦，則身不榮，不去此婦，則事不成，吾數奇命薄，端相逢遭。","sortOrder":13},
  {"id":"s_work_nvlt_35_14","chapterId":"ch_work_nvlt_35","text":"《典論》曰：上洛都尉王琰，以功封，其妻哭於家，為琰富貴更取妾故也。","sortOrder":14},
  {"id":"s_work_nvlt_35_15","chapterId":"ch_work_nvlt_35","text":"《魏志》曰：冯方女美，袁術納焉，甚寵幸，諸妾害其寵，因共殺而懸之，言其自縊。","sortOrder":15},
  {"id":"s_work_nvlt_35_16","chapterId":"ch_work_nvlt_35","text":"又曰：袁紹婦劉氏，甚妒，紹死未殯，寵妾五人，劉盡殺之。又毀其形，其少子尚。又盡滅死妾家焉。","sortOrder":16},
  {"id":"s_work_nvlt_35_17","chapterId":"ch_work_nvlt_35","text":"王隱《晉書》曰：贾充妻郭，產子黎民，三歲，乳母抱向閤，充入，黎民喜勇，［《太平御覽》五百二十一作踴。］充惡［御覽作呜。］之，郭遙望見，疑充，即鞭乳母殺之，兒思乳母而死，郭又生一男，乳母抱在中庭，充過拈頰，郭又疑，复殺乳母，男又死。","sortOrder":17},
  {"id":"s_work_nvlt_35_18","chapterId":"ch_work_nvlt_35","text":"《郭子》曰：孫秀妻蒯，嘗妒骂秀為貉，秀大不平，遂出不复入，蒯氏請救於武帝，時大赦，帝曰：天下曠荡，蒯夫人可得從其例否，秀免冠謝，為夫婦如初。","sortOrder":18},
  {"id":"s_work_nvlt_35_19","chapterId":"ch_work_nvlt_35","text":"妒記曰：王丞相曹夫人，性甚忌，禁製丞相，不得有侍御，時有妍少，必加誚责，王公不能久堪，乃密營別馆，眾妾羅列，男女成行，後元會日，夫人於青疏中觀望，忽見兩三小兒騎羊，皆端正，夫人語婢雲，汝出問，此是誰家兒，奇可念，給使不達旨，乃雲，此是第四五等諸郎，曹氏驚恚，不能自忍，乃命駕車，將黃門及婢二十人，持食刀，欲自出尋讨，王公亦飛辔出門，猶患遲，乃以左手攀車拦，右手提麈尾，以柄打牛，狼狽奔馳，方得先至，蔡司徒聞之，乃謂王曰：朝廷欲加九錫，公知否，王為信，自叙謙志，蔡曰：不聞加餘物，惟聞短轅犢車，長柄麈尾爾，王大羞愧。","sortOrder":19},
  {"id":"s_work_nvlt_35_20","chapterId":"ch_work_nvlt_35","text":"又曰：謝太傅劉夫人，不令公有別房，公既深好聲樂，复遂頗欲立妓妾，兄子外生等，微達此旨，共問訊劉夫人，因方便，稱關雎螽斯，有不忌之德，夫人知以諷己，乃問誰撰此詩，答雲周公，夫人曰：周公是男子，相為爾，若使周姥撰詩，當無此也。","sortOrder":20},
  {"id":"s_work_nvlt_35_21","chapterId":"ch_work_nvlt_35","text":"又曰：京邑有士人婦，大妒忌，於夫小則骂詈，大必捶打，常以長繩系夫腳，且唤便牵繩，士人密與巫嫗為計，因婦眠，士人入廁，以繩系羊，士人緣牆走避，婦覺，牵繩而羊至，大驚怪，召問巫，巫曰：娘積惡，先人怪责，故郎君变成羊，若能改悔，乃可祈請，婦因悲號，抱羊恸哭，自咎悔誓，師嫗乃令七日斋，舉家大小悉避於室中，祭鬼神，師祝羊還复本形，婿徐徐還，婦見婿，啼問曰：多日作羊，不乃辛苦耶，婿曰：猶憶啖草不美，腹中痛爾，婦愈悲哀，後复妒忌，婿因伏地作羊鳴，婦驚起徒跣，呼先人為誓，不复敢爾，於此不复妒忌。","sortOrder":21},
  {"id":"s_work_nvlt_35_22","chapterId":"ch_work_nvlt_35","text":"又曰：泰元中，有人姓荀，婦庾氏，大妒忌，荀嘗宿行，遂殺二兒，為屋不立斋室，唯有廳事，不作後壁，令在堂上，泠然望見外事，凡無須人不得入門，送書之人，若以手近荀手，無不痛打，客若共床坐，亦賓主俱败，鄰近有年少，径突前詣荀，接膝共坐，便聞大骂，推求刀杖，荀謂客曰：仆狂婦行，君之所聞，君不去，必誤君事，客曰：仆不畏此，乃前捉荀手，婦便持杖，直前向客，客既大健。又有短杖在衣里，便與手，老嫗無力，即倒地，客打垂死，荀走叛不敢還，婦密令賝荀，雲近遭狂人，非君之過，君便可還，荀然後敢出，婦兄來，就荀共方床臥，而婦不知，便來捉兄頭，拽著地欲殺，方知是兄，慚懼入內，兄稱父命，與杖數百，亦無改悔。","sortOrder":22},
  {"id":"s_work_nvlt_35_23","chapterId":"ch_work_nvlt_35","text":"又曰：諸葛元直妻劉氏，大妒忌，恒與元直杖，與杖之法，大罪十，小罪五，然得手摩，不得一一受也，常行杖小重，元直不勝痛，才得一兩，仍以手摸，婦不［不下疑有脱文。］誤打指節肿，從此作製，每與杖，辄令兩手各捉纟忌跗，元直□□□遇見婦捉纟忌跗欲成衣，謂當與己杖，失色怖，婦曰：不也，捉此自欲成衣耳，乃欣然。","sortOrder":23},
  {"id":"s_work_nvlt_35_24","chapterId":"ch_work_nvlt_35","text":"《異苑》曰：吳興桑乞妻，臨終執乞手雲，我死，為當婚否，乞言不忍也，服竟更娶，白日見其死婦，語之雲，君先結誓，雲何負言，因以刀割其陽道，雖不致死，人性永废。","sortOrder":24},
  {"id":"s_work_nvlt_35_25","chapterId":"ch_work_nvlt_35","text":"俗說，桓溫平蜀後，以李势女為妾，南郡主甚妒，［已具美婦人也。］","sortOrder":25},
  {"id":"s_work_nvlt_35_26","chapterId":"ch_work_nvlt_35","text":"【詩】魏陳王曹植詩曰：嗟爾同衾，曾弗是志，寧彼冶容，安此妒忌。","sortOrder":26},
  {"id":"s_work_nvlt_35_27","chapterId":"ch_work_nvlt_35","text":"【賦】梁張缵妒婦賦曰：惟婦怨之無極，羌於何而弗有，或造端構末，皆莠言之在口，常因情以起恨，每傳聲而妄受，乍隔帳而窥屏，或觇窗而瞰牖，若夫室怒小憾，反目私言，不忍細忿，皆成大冤，閨房之所隱私，床笫之所讨論，鹹一朝之發洩，滿四海之嚣喧，忽有逆其妒鱗，犯其忌製，赴湯蹈火，瞋目攘袂，或弃產而焚家，或投兒而害婿。","sortOrder":27},
  {"id":"s_work_nvlt_35_29","chapterId":"ch_work_nvlt_35","text":"《周易上·系》曰：冶容誨淫，［誨，教也。］","sortOrder":29},
  {"id":"s_work_nvlt_35_30","chapterId":"ch_work_nvlt_35","text":"《洪范五行傳》曰：蜮射人者，生於南方，謂之短狐，故南越多蜮，蜮者，淫女惑亂之所生也。","sortOrder":30},
  {"id":"s_work_nvlt_35_31","chapterId":"ch_work_nvlt_35","text":"《毛詩》曰：鄘柏舟桑中，刺奔也，衛公室亂，男女相奔，至於世族在位，相竊妻妾，期於幽遠，期我乎桑中，要我乎上宮，送我乎淇之上矣，桑中上宮，所期之地，淇，水名也。","sortOrder":31},
  {"id":"s_work_nvlt_35_32","chapterId":"ch_work_nvlt_35","text":"又曰：齊雞鳴南山，刺襄公也，鳥獸之行，淫乎其妹。","sortOrder":32},
  {"id":"s_work_nvlt_35_33","chapterId":"ch_work_nvlt_35","text":"《左傳》曰：僖中［疑當作左傳僖中曰：按本書所引《左傳》：分卷或與今本不同如僖公昭公，有分卷為上中下者，本條見僖十七年，正值中卷，故雲僖中，前卷五社篇引左傳昭上曰：同此。］齊侯好內，多淫，內嬖如夫人者六人。","sortOrder":33},
  {"id":"s_work_nvlt_35_34","chapterId":"ch_work_nvlt_35","text":"《戰國策》曰：秦宣太後愛魏丑，後病，且令曰：我死，必以魏子為殉，庸芮為諫曰：以死為無知，何空以生所愛，葬無知之死，人若有知，先王積怒久，太後救過不暇，何得更殉魏丑，後乃止。","sortOrder":34},
  {"id":"s_work_nvlt_35_35","chapterId":"ch_work_nvlt_35","text":"《列子》曰：鄭公孫穆好色，後庭數十，皆擇稚齒，屏親昵，絕交遊，於後庭以晝足夜，三月一出，意從未愜。","sortOrder":35},
  {"id":"s_work_nvlt_35_36","chapterId":"ch_work_nvlt_35","text":"《博物志》曰：三身國，一頭三身三手，昔容成氏有季子，好淫，白日淫於市，帝放之西南，季子妻馬生子，人身有尾蹄。","sortOrder":36},
  {"id":"s_work_nvlt_35_37","chapterId":"ch_work_nvlt_35","text":"《漢書》曰：五鳳中，濟北王終吉，所愛奴，與八子及諸御妾為奸，終吉與共被席，或晝日使裸伏，犬馬交接，終吉親觀，產子，辄曰：亂不可知，丞相御史奏，終吉位諸侯王，以置八子，秩比六百石，所廣嗣重祖，而終吉禽獸行亂，勃逆人倫，請削四縣。","sortOrder":37},
  {"id":"s_work_nvlt_35_38","chapterId":"ch_work_nvlt_35","text":"又曰：許皇後坐執左道，废處長信［漢書九十七下作定。］宮，姊孊為龍嵒思侯夫人，寡居，淳於長與孊私通，因娶為小妻，許後因孊賂遺，欲求复為婕妤，長受後金錢乘舆服物千餘萬計，為白上，立為左皇後，孊每入長信宮。長與孊書，戲許後。","sortOrder":38},
  {"id":"s_work_nvlt_35_39","chapterId":"ch_work_nvlt_35","text":"華峤《後漢書》曰：梁冀愛監奴秦宮，官至太仓令，得入妻寿所，寿見宮，屏御者以言事，因通焉，宮威權大震，二千石皆拜謁之。","sortOrder":39},
  {"id":"s_work_nvlt_35_40","chapterId":"ch_work_nvlt_35","text":"范晔《後漢書》曰：赤眉發掘諸陵，取寶货，汙辱呂後，凡有玉匣者，皆如生，故赤眉多行淫秽。","sortOrder":40},
  {"id":"s_work_nvlt_35_41","chapterId":"ch_work_nvlt_35","text":"臧榮緒《晉書》曰：贾充後妻郭氏。又生二女，少有淫行，年十四五，通於韓寿，充未覺，時外國獻奇香，世祖分與充，充以賜女，充與寿坐，聞其衣香，心疑之，充家嚴峻，牆高丈五，荐以枳棘，周行東北角，有如狸鼠行跡，充潛殺知婢，遂以女妻之。","sortOrder":41},
  {"id":"s_work_nvlt_35_42","chapterId":"ch_work_nvlt_35","text":"沈約《宋書》曰：楚王山陰公主，废帝姊也，肆情淫縱，以吏部褚淵貌美，請自侍十日，帝許之，淵雖遂旨，以死自固。","sortOrder":42},
  {"id":"s_work_nvlt_35_43","chapterId":"ch_work_nvlt_35","text":"《列女傳》曰：夏姬者，陳大夫徵舒母也，状美好，老而复壮者三，三為王後，諸侯爭之，莫不迷惑，陳靈公與孔甯儀父皆通焉，或衣其衣，或裝其幡，［幡，蔽膝衣。］以戲於朝。","sortOrder":43},
  {"id":"s_work_nvlt_35_44","chapterId":"ch_work_nvlt_35","text":"《列異傳》曰：漢桓帝冯夫人病亡，靈帝時，有賊盜發冢，七十餘年，顏色如故，但小冷，共奸通之，至斗爭相殺，窦太後家被誅，欲以冯夫人配食，下邳陳公達議，以貴人雖是先所幸，尸體秽汙，不宜配至尊，乃以窦太後配食。","sortOrder":44},
  {"id":"s_work_nvlt_35_45","chapterId":"ch_work_nvlt_35","text":"《論衡》曰：書雲，齊桓公負婦人以朝諸侯，管仲曰：吾君背疽瘡，不得婦人不愈，此虛也。","sortOrder":45},
  {"id":"s_work_nvlt_35_46","chapterId":"ch_work_nvlt_35","text":"《風俗通》曰：平原君谳韽谭娶周碧為妻，谭陰陽不屬，令碧與李方張少奸通，冀得其子。","sortOrder":46},
  {"id":"s_work_nvlt_35_47","chapterId":"ch_work_nvlt_35","text":"《語林》曰：劉道真子婦始入門，遣婢［原作婦，據冯校本作婢。］虔，劉聊之甚苦，婢固不從，劉乃下地叩頭，婢懼而從之，明日語人曰：手推故是神物，一下而婢服淫。","sortOrder":47},
  {"id":"s_work_nvlt_35_48","chapterId":"ch_work_nvlt_35","text":"傳曰：衛宣公烝於夷薑，生急子，［薑，公之母，淫上曰蒸。］","sortOrder":48},
  {"id":"s_work_nvlt_35_49","chapterId":"ch_work_nvlt_35","text":"晉祁勝與邬臧，通室易妻。","sortOrder":49},
  {"id":"s_work_nvlt_35_51","chapterId":"ch_work_nvlt_35","text":"《左傳》曰：晉人謀去故絳，諸大夫曰：必居郇瑕氏之地，沃饒而近盬，魏獻子曰：不如新田，土厚水深，居之不疾，郇瑕氏土薄水淺，其惡易覯，覯則民愁，愁則墊隘，於是乎有沉溺重膇之疾。","sortOrder":51},
  {"id":"s_work_nvlt_35_52","chapterId":"ch_work_nvlt_35","text":"又曰：吳公子札來聘，請觀於周樂，為之歌頌，曰：至矣哉，哀而不愁，［知命也。］樂而不荒，［節之以禮。］《莊子》曰：不知乎人，謂朱愚，知乎則反愁我軀，不仁則害人，仁則反傷吾身，不義則傷彼，義則反愁我己。","sortOrder":52},
  {"id":"s_work_nvlt_35_53","chapterId":"ch_work_nvlt_35","text":"《吳越春秋》曰：越王念吳，欲复讎，愁心苦志，中夜抱柱而哭，承之以嘯，群臣聞之曰：君王何愁心之甚也，夫复讎謀敵，非君王之忧，自臣下之急務也。","sortOrder":53},
  {"id":"s_work_nvlt_35_54","chapterId":"ch_work_nvlt_35","text":"《史記》曰：虞卿著書八篇，號曰虞氏春秋，太史公曰：虞卿非窮愁，不能著書，自見於後世。","sortOrder":54},
  {"id":"s_work_nvlt_35_55","chapterId":"ch_work_nvlt_35","text":"《後漢書》曰：梁冀妻色美，善為妖態，作愁眉，［具美婦人。］","sortOrder":55},
  {"id":"s_work_nvlt_35_56","chapterId":"ch_work_nvlt_35","text":"《楚辭》曰：天問者，屈原所作也，屈原放逐，忧心愁悴，彷徨山泽，經歷陵陆，嗟號日聞，仰天叹息，楚有先王之廟，及公卿祠堂，圖畫天地山川，神靈奇伟，及古賢聖怪物行事，周流罢倦，休息其下，仰見圖畫，因書其壁，呵而問之，以洩憤懣，舒寫愁思。","sortOrder":56},
  {"id":"s_work_nvlt_35_57","chapterId":"ch_work_nvlt_35","text":"又曰：漁父者，屈原所作也，屈原馳逐江湘之間，忧愁吟叹，而漁父避世隱身，釣魚江濱，欣然自樂，時遇屈原川泽之域，怪而問之，遂相應答。","sortOrder":57},
  {"id":"s_work_nvlt_35_58","chapterId":"ch_work_nvlt_35","text":"《晉書》曰：王丞［按當作承，下同，參下郭子條。］去官東渡，是時道路寇盜，人懷危懼，丞每過艱险，處之若夷然，雖家人，不見其愁喜之色。","sortOrder":58},
  {"id":"s_work_nvlt_35_59","chapterId":"ch_work_nvlt_35","text":"《郭子》曰：王東海初過江，［王丞(《太平御覽》四百六十九作承。)字安期。］登琅邪山，叹曰：我由來不愁，今日直欲愁。","sortOrder":59},
  {"id":"s_work_nvlt_35_60","chapterId":"ch_work_nvlt_35","text":"【詩】後漢張衡四愁詩曰：我所思兮在泰山，欲往從之梁甫艱，侧身東望涕霑翰，美人赠我金错刀，何以報之英琼瑤，路遠莫致倚逍遙，何以懷愁心煩勞。","sortOrder":60},
  {"id":"s_work_nvlt_35_61","chapterId":"ch_work_nvlt_35","text":"又曰：我所望兮在桂林，欲往從之湘水深，侧身南望涕霑襟，美人赠我翠琅玕，何以報之双玉盤。","sortOrder":61},
  {"id":"s_work_nvlt_35_62","chapterId":"ch_work_nvlt_35","text":"又曰：我所思兮在漢陽，欲往從之隴坂長，侧身西望涕霑裳，美人赠我貂襜褕，何以報之明月珠。","sortOrder":62},
  {"id":"s_work_nvlt_35_63","chapterId":"ch_work_nvlt_35","text":"又曰：我所思兮在雁門，欲往從之雪紛紛，侧身北望涕霑巾，美人赠我錦繡段，何以報之青玉案。","sortOrder":63},
  {"id":"s_work_nvlt_35_64","chapterId":"ch_work_nvlt_35","text":"晉張載擬四愁詩曰：我所思兮在南巢，欲往從之巫山高，佳人遺我筒中布，何以報之流黃素。","sortOrder":64},
  {"id":"s_work_nvlt_35_65","chapterId":"ch_work_nvlt_35","text":"又曰：我所思兮在朔湄，欲往從之白雪霏，佳人遺我雲中翮，何以赠之連城璧。","sortOrder":65},
  {"id":"s_work_nvlt_35_66","chapterId":"ch_work_nvlt_35","text":"又曰：我所思兮在隴原，欲往從之隔秦山，佳人遺我双角端，何以赠之雕玉環。","sortOrder":66},
  {"id":"s_work_nvlt_35_67","chapterId":"ch_work_nvlt_35","text":"又曰：我所思兮在營州，欲往從之路阻脩，佳人遺我绿綺琴，何以赠之双南金。","sortOrder":67},
  {"id":"s_work_nvlt_35_68","chapterId":"ch_work_nvlt_35","text":"宋王徽詠愁詩曰：自予抱羁思，眇與日月長，載離非宋遠，誰謂河難航，忧隨積霖密，慨因朗旭彰，負之苦不勝，即之竟無方，如彼引鯤魚，待盡守空梁，天地豈私貧，運至豈固當，既悟非形兆，茲數詎可攘。","sortOrder":68},
  {"id":"s_work_nvlt_35_69","chapterId":"ch_work_nvlt_35","text":"梁王僧孺夜愁示諸賓詩曰：簷露滴為珠，池水合如璧，萬行朝淚泻，千里夜愁積，孤帳閉不开，寒膏盡复益，誰知心眼亂，看朱忽成碧。","sortOrder":69},
  {"id":"s_work_nvlt_35_70","chapterId":"ch_work_nvlt_35","text":"又忽不任愁聊示固遠詩曰：去秋客舊吳，今春投故越，淚逐東歸水，心掛西斜月，未應歲貶顏，直以忧殘發。","sortOrder":70},
  {"id":"s_work_nvlt_35_71","chapterId":"ch_work_nvlt_35","text":"梁劉孝綽夜不得眠詩曰：夜長愁反覆，懷抱不能裁，披衣坐惆怅，當戶立徘徊，風音觸树起，月色度雲來，夏葉依窗落，秋花當戶开，光陰已如此，复持忧自催。","sortOrder":71},
  {"id":"s_work_nvlt_35_72","chapterId":"ch_work_nvlt_35","text":"梁劉孝先和兄孝綽夜不得眠詩曰：夜愁眠不安，起望台南端，葉惨風聲異，樓空月色寒，笙冷調簧數，絃脆上琴難，百年行詎幾，萬慮坐相攒，誰家有明鏡，蹔借照心看。","sortOrder":72},
  {"id":"s_work_nvlt_35_73","chapterId":"ch_work_nvlt_35","text":"【賦】魏陳王曹植叙愁賦曰：時家二女弟，故漢皇帝聘以為貴人，家母見二弟愁思，故令予作賦曰：嗟妾身之微薄，信未達乎義方，遭母氏之聖善，奉恩化之弥長，迄盛年而始立，脩女職於衣裳，承師保之明訓，誦六列之篇章，觀圖像之遺形，竊庶幾乎皇英，委微軀於帝室，充末列於椒房，荷印绂之令服，非陋才之所望，對床帳而太息，慕二親以增傷，扬羅袖而掩涕，起出戶而彷徨，顧堂宇之舊處，悲一別之異乡。","sortOrder":73},
  {"id":"s_work_nvlt_35_74","chapterId":"ch_work_nvlt_35","text":"又愁思賦曰：四節更王兮秋氣悲，遙思惝怳兮若有遺，原野萧條兮煙無依，雲高氣靜兮露凝衣，野草变色兮茎葉希，鳴蜩抱木兮雁南飛，歸室解裳兮步庭前，月光照懷兮星依天，居一世兮芳景遷，松乔難慕兮誰能仙，長短命也兮獨何怨。","sortOrder":74},
  {"id":"s_work_nvlt_35_75","chapterId":"ch_work_nvlt_35","text":"又九愁賦曰：嗟離思之難忘，心惨毒而含哀，踐有畿之末境，超引領之徘徊，眷浮雲以太息，原攀登而無階，匪徇榮而愉樂，信舊都之可懷，恨時王之谬聽，受奸枉之虛辭，扬天威以臨下，忽放臣而不疑，登高陵而反顧，心懷愁而荒悴，念先寵之既隆，哀後施之不遂，雖危亡之不豫，亮無遠君之心，刈桂蘭而秣馬，舍予車於西林，原接翼於歸鸿，羌高飛而莫攀，因流景而寄言，乡一絕而不還，傷時俗之趍险，獨惆怅而長愁，感龍鸞而匿跡，如吾身之不留，竄江介之曠野，獨眇眇而汎舟，思孤客之可悲，愍予身之翩翔，豈天監之孔明，將時運之無常，謂內思而自策，筭乃昔之愆殃，以忠言而見黜，信無負於時王，俗參差而不齊，豈毀譽之可同，競昏瞀以營私，害予身之奉公，共朋党而妒賢，俾予濟乎長江，嗟大化之移易，悲性命之悠遭，愁慊慊而繼懷，恒惨惨而情挽，曠年載而不回，長去君乎悠遠，御飛龍之蜿蜿，扬翠霓之華旌，絕氣霄而高骛，飄弭節於天庭，披輕雲而下觀，覽九土之殊形，顧南郢之邦壤，鹹芜秽而倚傾，驂盤桓讓路以悲服，仰御驤以悲鳴，紆予袂而收涕，仆夫感以失聲，履先王之正路，豈淫径之可遵，知犯君之招咎，恥幹媚而求親，顧旋复之無軌，長自弃於遐濱，與麋鹿而為群，宿林藪之葳蓁，野萧條而極望，曠千里而無人，民生期於必死，何自苦以終身，寧作清水之决泥，不為濁路之飛尘，踐蹊径之危阻，登岧峣之高岑，見失群之離獸，觌偏栖之孤禽，懷憤激以切痛，若回刃之在心，愁戚戚其無為，遊绿林而逍遙，臨白水以悲嘯，猿驚聽而失條，亮無怨而弃逐，乃全行之所招。","sortOrder":75},
  {"id":"s_work_nvlt_35_76","chapterId":"ch_work_nvlt_35","text":"魏繁钦愁思賦曰：何旻秋之惨凄，處閒夜而懷愁，潛白日於玄陰，翳朗月於重幽，零雨濛其迅集，潢淹汩以橫流，聽峻階之回霤，心沉切以增忧，嗟王事之靡盬，士感時而情悲，原出身以徇役，式簡書以忘歸，時陟岵以旋顧，涕漸纓而鮮晞，聽鳴鶴之哀音，知我行之多违，怅俯仰而自怜，志荒悃而摧威，聊絃歌以厲志，勉奉職於閨闈。","sortOrder":76},
  {"id":"s_work_nvlt_35_77","chapterId":"ch_work_nvlt_35","text":"又弭愁賦曰：傷有閒之淑女，采薜荔於朝陽，露素质之皎皎，綰玄發以流光，結翠葉於珠簪，擢丹華於绿房，點圜的之熒熒，暎双辅而相望，袭遊閒之妓服，褥阿縠之桂裳，纫畹蘭於纓佩，動晻暧以遺芳，既容冶而多好，且妍惠之纖微，顧見予之獨立，知我情之思歸，鳴環瑱以回眄，若欲進而行遲，眷紅顏之晔晔，何的皪之少群，整桂冠而自飾，敷綦藻之華文，從景炎而猗靡，粲綿邈以繽紛，時了眇以含笑，收婉媚以愁人。","sortOrder":77},
  {"id":"s_work_nvlt_35_78","chapterId":"ch_work_nvlt_35","text":"梁簡文帝序愁賦曰：情無所治，志無所求，不懷傷而忽恨，無驚猜而自愁，玩飛花之入戶，看斜暉之度寮，雖复玉觴浮碗，趙瑟含娇，未足以袪斯耿，［句有脱文。］息此長謠。","sortOrder":78},
  {"id":"s_work_nvlt_35_79","chapterId":"ch_work_nvlt_35","text":"【文】魏陳王曹植釋愁文曰：予以愁惨，行吟路邊，形容枯悴，忧心如焚，有玄虛先生見而問之曰：子將何疾，以至於斯，答曰：吾所病者愁也，先生曰：愁是何物，而能病子乎，答曰：愁之為物，惟惚惟怳，不召自來，推之弗往，尋之不知其际，握之不盈一掌，寂寂長夜，或群或党，去來無方，亂我精爽，其來也難進，其去也易追，臨餐困於哽咽，煩冤毒於酸嘶，加之以粉飾不泽，飲之以兼肴不肥，溫之以火石不消，摩之以神膏不稀，受之以巧笑不悅，樂之以絲竹增悲，医和絕思而無措，先生豈能為我蓍龟乎，先生作色而言曰：予徒辯子之愁形，未知子愁所由生，吾獨為子言其發矣，今大道既隱，子生末季，沉溺流俗，眩惑名位，濯纓彈冠，谘诹榮貴，坐不安席，食不終味，遑遑汲汲，或惨或悴，所鬻者名，所拘者利，良由華薄，凋損正氣，吾將赠子以無為之藥，給子以澹泊之湯，刺子以玄虛之針，灸子以淳朴之方，安子以恢廓之宇，坐子以寂寞之床，使王乔與之［本集作子。］携手而遊，黃公與子詠歌而行，莊生為子具養神之饌，老聃為子致愛性之方，趣遐路以栖跡，乘輕雲以高翔，於是精駭意散，改心回趣，原納至言，仰崇玄度，眾愁忽然，不辭而去。","sortOrder":79},
  {"id":"s_work_nvlt_35_81","chapterId":"ch_work_nvlt_35","text":"《說文》曰：泣，無聲出涕也。","sortOrder":81},
  {"id":"s_work_nvlt_35_82","chapterId":"ch_work_nvlt_35","text":"《禮記》曰：高子皋執親之丧，泣血三年，未嘗見齒，君子以為難矣。","sortOrder":82},
  {"id":"s_work_nvlt_35_83","chapterId":"ch_work_nvlt_35","text":"又曰：弁人有其母死而孺子泣者，孔子曰：哀則哀矣，而難為繼矣。","sortOrder":83},
  {"id":"s_work_nvlt_35_84","chapterId":"ch_work_nvlt_35","text":"《左傳》曰：楚令尹子元，欲蠱文夫人，為馆於其宮侧，振萬焉，夫人聞之，泣曰：先君以是舞也，習戎備也，今令尹不尋諸仇讎，而於未亡人之侧，不亦異乎。","sortOrder":84},
  {"id":"s_work_nvlt_35_85","chapterId":"ch_work_nvlt_35","text":"又曰：叔孫婼聘於宋，宋公與宴，子［按子上當脱昭字。］飲酒樂，宋公使昭子右坐，語相泣，樂祁左，退而告人曰：今茲君與叔孫，其皆死乎，吾聞之，哀而樂，樂而哀，皆丧心也，何以能久。","sortOrder":85},
  {"id":"s_work_nvlt_35_86","chapterId":"ch_work_nvlt_35","text":"《國語》曰：叔向見司馬侯之子，撫而泣之曰：自其父死也，吾蔑與比而事君也，昔者其父始之，我終之，我始之，夫子終之。","sortOrder":86},
  {"id":"s_work_nvlt_35_87","chapterId":"ch_work_nvlt_35","text":"《尸子》曰：曾子每讀丧禮，泣霑襟，［已具孝篇。］","sortOrder":87},
  {"id":"s_work_nvlt_35_88","chapterId":"ch_work_nvlt_35","text":"又曰：費子陽謂子思曰：吾念周室將滅，涕泣不可禁也，子思曰：然，今以一人之身，忧世之不治，而涕泣不禁，是忧河水濁，而以泣清之也。","sortOrder":88},
  {"id":"s_work_nvlt_35_89","chapterId":"ch_work_nvlt_35","text":"《呂氏春秋》曰：吳起治西門之外，王错谮之魏武侯，武侯使人召之，吳起至於岸門，止車而望西河，泣數行而下。","sortOrder":89},
  {"id":"s_work_nvlt_35_90","chapterId":"ch_work_nvlt_35","text":"《楚漢春秋》曰：呂後欲為惠帝高墳，使從未央宮坐而見之，東陽侯垂泣曰：陛下日夜見惠帝冢，悲哀流涕無已，是傷生也，臣竊哀之，太後乃止。","sortOrder":90},
  {"id":"s_work_nvlt_35_91","chapterId":"ch_work_nvlt_35","text":"《史記》曰：箕子過故殷墟，鹹生禾黍，箕子傷之，欲哭則不可，欲泣為近婦人，乃作麥秀之詩，以歌詠之，殷民皆流涕，［具麥篇。］","sortOrder":91},
  {"id":"s_work_nvlt_35_92","chapterId":"ch_work_nvlt_35","text":"又曰：荆軻與高漸離，飲於燕市，酒酣，漸離共荆軻相和而歌於市中，相樂，已而相泣，傍若無人。","sortOrder":92},
  {"id":"s_work_nvlt_35_93","chapterId":"ch_work_nvlt_35","text":"又曰：漢高欲自击陳豨，蒯成侯周緤泣曰：始秦攻破天下，未嘗自行，今上自行，是為無人可使者乎。","sortOrder":93},
  {"id":"s_work_nvlt_35_94","chapterId":"ch_work_nvlt_35","text":"又曰：戚姬愛幸，生趙王如意，常從之關東，日夜啼泣，欲立如意為太子。","sortOrder":94},
  {"id":"s_work_nvlt_35_95","chapterId":"ch_work_nvlt_35","text":"又曰：窦皇後兄長君，弟曰廣國，年五歲時，家貧，為人所略，賣之長安，聞窦後新立，廣國上書自陳，後召見，具言其故，後持之而泣，侍御左右，皆伏地泣。","sortOrder":95},
  {"id":"s_work_nvlt_35_96","chapterId":"ch_work_nvlt_35","text":"《說苑》曰：雍門周以琴見孟嘗君，君曰：先生鼓琴，亦能令人悲乎，周曰：夫千秋萬歲之後，高台既已坏，曲池即以堑，墳墓既已下，婴兒竖子樵采者，踯躅其足，而歌其上曰：夫以孟嘗君貴尊，乃若是乎，於是孟嘗君泫然涕泣曰：令文立若破國亡邑之人，［具琴篇。］","sortOrder":96},
  {"id":"s_work_nvlt_35_97","chapterId":"ch_work_nvlt_35","text":"又曰：聖人於天下也，譬猶一堂之上，令滿堂飲酒，有一人向隅而泣，則一堂之人，皆不樂矣。","sortOrder":97},
  {"id":"s_work_nvlt_35_98","chapterId":"ch_work_nvlt_35","text":"又曰：禹出見辜人，問而泣之，左右問其故，禹曰：尧舜之民，皆以尧舜之心為心，今吾為君，百姓皆以其心為心，是以痛之。","sortOrder":98},
  {"id":"s_work_nvlt_35_99","chapterId":"ch_work_nvlt_35","text":"《新序》曰：周舍事趙簡子，居無幾何，周舍死，後與諸大夫飲酒酣，簡子泣曰：百羊之皮，不如一狐之腋，眾人之唯唯，不如周舍之愕愕，自周舍死，吾未嘗聞吾罪也，吾國幾亡乎，是以垂泣。","sortOrder":99},
  {"id":"s_work_nvlt_35_100","chapterId":"ch_work_nvlt_35","text":"《漢書》曰：高祖破黥布軍還，過沛，置酒沛宮，上慷慨傷懷，泣數行下，［具懷舊篇。］","sortOrder":100},
  {"id":"s_work_nvlt_35_101","chapterId":"ch_work_nvlt_35","text":"《東觀漢記》曰：更始害齊武王，光武飲食語笑如平常，獨居，辄不御酒肉，枕席有涕泣處。","sortOrder":101},
  {"id":"s_work_nvlt_35_102","chapterId":"ch_work_nvlt_35","text":"又曰：來歙蓋延攻公孫述，蜀人大懼，使刺客刺歙，歙未死，馳告蓋延，延見歙，悲哀不能仰视，歙叱曰：欲屬以軍事，而反效兒女子涕泣乎。","sortOrder":102},
  {"id":"s_work_nvlt_35_103","chapterId":"ch_work_nvlt_35","text":"《論衡》曰：昔周人有仕不遇，年老白首，泣涕於途者，或問何為泣乎，對曰：吾仕數不遇，自傷年老失時，是以泣。","sortOrder":103},
  {"id":"s_work_nvlt_35_104","chapterId":"ch_work_nvlt_35","text":"又曰：蘇秦張儀，學縱橫之術於鬼穀先生，先生曰：能說我泣出，則能分天皇之地，秦說鬼穀先生，先生泣霑襟。","sortOrder":104},
  {"id":"s_work_nvlt_35_105","chapterId":"ch_work_nvlt_35","text":"《汝南先賢傳》曰：蔡順母畏雷，後母卒，每有震，順辄圜冢泣曰：順在此。","sortOrder":105},
  {"id":"s_work_nvlt_35_106","chapterId":"ch_work_nvlt_35","text":"邴原傳曰：原年五六歲，過書舍而泣，師曰：何泣，原曰：孤者易傷感，夫書者皆有父母也，心原其得書，故惻然涕零也，師哀原而為之泣曰：欲之可書，須費也，［《太平御覽》六百十一作不之求費也，此有脱文。］","sortOrder":106},
  {"id":"s_work_nvlt_35_107","chapterId":"ch_work_nvlt_35","text":"《後漢書》曰：張奐與張公超書曰：下筆怆恨，泣先言泯。","sortOrder":107},
  {"id":"s_work_nvlt_35_108","chapterId":"ch_work_nvlt_35","text":"《吳錄》曰：孟宗為驃騎朱據軍吏，將母在營，既不得志。又夜雨屋漏，因起涕泣以謝母，母曰：但當勉之，何足泣也。","sortOrder":108},
  {"id":"s_work_nvlt_35_109","chapterId":"ch_work_nvlt_35","text":"《襄陽耆舊記》曰：羊公與邹閏甫登峴山，垂泣曰：有宇宙便有此山，由來賢達，登此遠望者多矣，皆湮滅無聞，不可得知，念此令人悲傷。","sortOrder":109},
  {"id":"s_work_nvlt_35_110","chapterId":"ch_work_nvlt_35","text":"《晉陽秋》曰：司馬文王問劉禪曰：頗思蜀否，禪曰：此間樂，不思蜀也，郄正見禪曰：若王後問，宜泣以對，會王复問，禪曰：先人墳墓，遠在隴蜀，乃心西悲，無日不思，因閉眼，王曰：何以似郄正語耶，禪驚视曰：如尊命。","sortOrder":110},
  {"id":"s_work_nvlt_35_112","chapterId":"ch_work_nvlt_35","text":"《尚書·洪范》曰：六極，四曰貧。","sortOrder":112},
  {"id":"s_work_nvlt_35_113","chapterId":"ch_work_nvlt_35","text":"《禮記》：子路曰：傷哉貧，生無以為養，死無以為禮，子曰：啜菽飲水，盡其歡，斯之謂孝，斂手足形，還葬而無椁，稱其财，之謂禮。","sortOrder":113},
  {"id":"s_work_nvlt_35_114","chapterId":"ch_work_nvlt_35","text":"又曰：儒有一畝之宮，環堵之室，篳門圭窦。","sortOrder":114},
  {"id":"s_work_nvlt_35_115","chapterId":"ch_work_nvlt_35","text":"《論語》曰：子曰：邦有道，貧且賤焉恥也。","sortOrder":115},
  {"id":"s_work_nvlt_35_116","chapterId":"ch_work_nvlt_35","text":"又曰：衣敝缊袍與衣狐貉者立，而不恥者，其由也與，鄭玄曰：缊，絮也，《毛詩》曰：出自北門，終窭且貧，莫知我艱。","sortOrder":116},
  {"id":"s_work_nvlt_35_117","chapterId":"ch_work_nvlt_35","text":"又曰：小東大東，杼柚其空，註曰：謂無货，唯絲麻，今盡不作也。","sortOrder":117},
  {"id":"s_work_nvlt_35_118","chapterId":"ch_work_nvlt_35","text":"《家語》曰：端木賜結驷連騎，以從原憲，憲居蓬蒿中，併日而食，子貢曰：甚矣子之病也，憲曰：予貧也，非病也。","sortOrder":118},
  {"id":"s_work_nvlt_35_119","chapterId":"ch_work_nvlt_35","text":"《國語》曰：叔向見韓宣子，宣子忧貧，叔向贺之，宣子曰：吾有卿名，而無其實，無以從二三子，吾是以忧，子贺我何故，對曰：昔栾武子無一卒之田，諸侯親之，戎翟懷之，以正晉國，今吾子有栾武子之貧，吾以為能脩其德也，是以贺，若不忧德之不脩，而患货之不足，將弔不暇，何贺之有。","sortOrder":119},
  {"id":"s_work_nvlt_35_120","chapterId":"ch_work_nvlt_35","text":"呂悅［按當作忱。］《字林》曰：窭，貧空也。","sortOrder":120},
  {"id":"s_work_nvlt_35_121","chapterId":"ch_work_nvlt_35","text":"《方言》曰：南楚人貧，衣被丑敝，謂之須捷，［捷謂俾遲。］或謂之褛裂，［褛，衣坏，具音。］或謂之藍縷，［《左傳》曰：荜辂藍縷為貧也。］","sortOrder":121},
  {"id":"s_work_nvlt_35_122","chapterId":"ch_work_nvlt_35","text":"《晏子》曰：晏子方食，景公使使者至，分食食之，使不飽，晏子亦不飽，使者反之，公曰：晏子如此貧乎，使致千金，以奉賓客。","sortOrder":122},
  {"id":"s_work_nvlt_35_123","chapterId":"ch_work_nvlt_35","text":"《列子》曰：凡為名者必廉，廉斯貧，為名者必讓，讓斯賤，《莊子》曰：原憲處魯，居環堵之室，茨以生草，蓬戶不完，桑木為枢而瓮牖，上漏下濕，匡坐而絃歌，子貢乘大馬，中绀而表素，軒車不容巷，往見原憲，憲杖藜應門，子貢曰：先生病也，憲應之曰：憲聞無财之謂貧，學而不能行之謂病，今憲貧也，非病也，子貢逡巡而退，有愧色。","sortOrder":123},
  {"id":"s_work_nvlt_35_124","chapterId":"ch_work_nvlt_35","text":"又曰：孔子謂顏回曰：家貧居卑，胡不仕乎，對曰：不原仕，回有郭外之田五十畝，足以給餰鬻，郭內十畝，足以為絲麻，鼓琴可以自娱，所學夫子者，足以自樂也，回不原仕，夫子愀然变色曰：美哉。","sortOrder":124},
  {"id":"s_work_nvlt_35_125","chapterId":"ch_work_nvlt_35","text":"又曰：莊周家貧，故往貸粟於監河侯，河侯曰：我將得邑金，貸子三百金，周忿然作色曰：周昨來，有中道而呼者，顧视車轍，有鲋魚焉，問之曰：子何為者耶，對曰：我東海波臣也，君豈有斗升之水而活我哉，周曰：诺，我將南遊吳越之王，激西江之水而迎子，可乎，鲋魚忿焉作色曰：吾得升斗之水為活爾，君乃言此，曾不如早索我枯魚之肆。","sortOrder":125},
  {"id":"s_work_nvlt_35_126","chapterId":"ch_work_nvlt_35","text":"又曰：子舆與子桑友，而霖雨十日，子舆曰：子桑殆病矣，裹飯而往食之，子桑若歌若哭，鼓琴曰：父母豈欲吾貧哉，天地豈私貧吾哉，求其為之者不得也。","sortOrder":126},
  {"id":"s_work_nvlt_35_127","chapterId":"ch_work_nvlt_35","text":"《孫卿子》曰：子夏貧若懸鶉，人曰：子何不仕，曰：諸侯之驕我者，吾不為臣，大夫之驕我者，吾不复見。","sortOrder":127},
  {"id":"s_work_nvlt_35_128","chapterId":"ch_work_nvlt_35","text":"又曰：仁義之於人也，譬之若货财粟米之於家也，多有之者富，少有之者貧，至無有者窮。","sortOrder":128},
  {"id":"s_work_nvlt_35_129","chapterId":"ch_work_nvlt_35","text":"《呂氏春秋》曰：世皆以珠玉為寶，寶愈多而民愈貧，失其所寶也。","sortOrder":129},
  {"id":"s_work_nvlt_35_130","chapterId":"ch_work_nvlt_35","text":"《戰國策》曰：齊人有冯暖者，貧乏不能自存，使人屬孟嘗君，原寄食門下。","sortOrder":130},
  {"id":"s_work_nvlt_35_131","chapterId":"ch_work_nvlt_35","text":"《史記》曰：魏勃少時，欲求見齊相曹參，家貧，無以自通，乃常獨早夜扫齊相門外，相舍人怪而以為物，而伺之，得勃，勃曰：原見相君無因，故為子扫門，欲求見，於是舍人見勃，曹參因以為舍人。","sortOrder":131},
  {"id":"s_work_nvlt_35_132","chapterId":"ch_work_nvlt_35","text":"又曰：東郭先生久待詔公車，貧困飢乏寒，衣敝履不完，行雪中，履有上無下，足盡以踐地，道中人笑之。","sortOrder":132},
  {"id":"s_work_nvlt_35_133","chapterId":"ch_work_nvlt_35","text":"又曰：甘茂亡秦奔齊，逢蘇代，代為齊使於秦，茂曰：臣得罪於秦，懼而逃，無所容跡，臣聞貧人女曰：我無以買燭，而子之燭光有餘，子可分我餘光，無損子之明，今臣困，原以餘光振之。","sortOrder":133},
  {"id":"s_work_nvlt_35_134","chapterId":"ch_work_nvlt_35","text":"又曰：楚相孫叔敖死，謂其子曰：我死，汝必貧困，可見優孟，［已具諷篇。］","sortOrder":134},
  {"id":"s_work_nvlt_35_135","chapterId":"ch_work_nvlt_35","text":"《漢書》曰：朱買臣，家貧好書，不治產業，妻求去，買臣笑曰：我五十當貴，今已四十餘，妻曰：如公子等，終當饿死，買臣不能留，即聽之。","sortOrder":135},
  {"id":"s_work_nvlt_35_136","chapterId":"ch_work_nvlt_35","text":"又曰：郦食其，好讀書，家貧落魄，無衣食產業，為里監門，然縣中賢豪不敢役，皆為之狂生。","sortOrder":136},
  {"id":"s_work_nvlt_35_137","chapterId":"ch_work_nvlt_35","text":"又曰：王章，字仲卿，為諸生，學長安，獨與妻居，病疾無被，臥牛衣中，與妻訣，涕泣，其妻呵怒之曰：仲卿，京師尊貴在朝廷人，誰逾仲卿者，今病疾困厄，不自激昂，乃反涕泣，何鄙也。","sortOrder":137},
  {"id":"s_work_nvlt_35_138","chapterId":"ch_work_nvlt_35","text":"謝承《後漢書》曰：王充，字仲任，少孤，家貧無書，常遊洛陽市肆，閱所賣書，［具雜文部讀書。］","sortOrder":138},
  {"id":"s_work_nvlt_35_139","chapterId":"ch_work_nvlt_35","text":"《續漢書》曰：王苑，字孫仲，安貧，茅屋蓬戶，藜藿不餍。","sortOrder":139},
  {"id":"s_work_nvlt_35_140","chapterId":"ch_work_nvlt_35","text":"又曰：范丹，桓帝時，以丹為萊芜長，不到官，遭党人禁錮，結草室居，歌之曰：甑中生尘范史雲，釜中生魚范萊芜。","sortOrder":140},
  {"id":"s_work_nvlt_35_141","chapterId":"ch_work_nvlt_35","text":"范晔《漢書》曰：李元，［《太平御覽》四百八十四作充。］字大遜，陳留人，事母至孝，家貧，兄弟六人，同衣出入。","sortOrder":141},
  {"id":"s_work_nvlt_35_142","chapterId":"ch_work_nvlt_35","text":"《三辅决錄》曰：弟［《太平御覽》四百八十五作第。］五頡，字子陵，倫小子，洛陽無主人，乡里無田宅，寄上［御覽作止。］靈台中，或十日不炊。","sortOrder":142},
  {"id":"s_work_nvlt_35_143","chapterId":"ch_work_nvlt_35","text":"又曰：孫晨，字元公，家貧不仕，生居城中，織箕為業，明詩書，為郡功曹，冬月無被，有藁一束，暮臥中，旦收之。","sortOrder":143},
  {"id":"s_work_nvlt_35_144","chapterId":"ch_work_nvlt_35","text":"先賢行状曰：胡定，字元安，至行絕人，在丧，雉兔遊其庭，時雪霜滿其室，縣令遣戶曹掾，排雪問定，定已絕穀，妻子皆臥在床，令即遣掾，以乾糧就遺之，定乃受半。","sortOrder":144},
  {"id":"s_work_nvlt_35_145","chapterId":"ch_work_nvlt_35","text":"魚豢魏書［《太平御覽》四百八十四作略。］曰：楊師，［御覽作沛。］前後宰城守，不以私計介意，故身退之後，家無餘财，蜗牛庐居其中，妻子冻饿。","sortOrder":145},
  {"id":"s_work_nvlt_35_146","chapterId":"ch_work_nvlt_35","text":"《魏略》曰：裴潛每之官，不將妻子，妻子貧乏，織荆芘以自供，群弟之田庐，常步行，家人小大，或併日而食。","sortOrder":146},
  {"id":"s_work_nvlt_35_147","chapterId":"ch_work_nvlt_35","text":"《楚辭》曰：坎壈兮貧士失耳［楚辭九辯作職。］而志不平，《六韜》曰：成王問太公，貧富豈有命乎，將理不得其意，太公曰：盜在其室，計之不熟，一盜收种不時，二盜取得無能，三盜養女太多，四盜其［《太平御覽》四百八十五作弃。］事就酒，五盜衣服過度。","sortOrder":147},
  {"id":"s_work_nvlt_35_148","chapterId":"ch_work_nvlt_35","text":"顏延之庭誥曰：富則盛，貧則病，甚矣，不唯形色粗黡，或亦神心沮丧，非但交友疏弃，必有家人訟誤，非廣絜深識者，何能不交移其植，故欲蠲忧患，莫若懷古之意，當自同古，見深則忧淺，識遠則患浮，昔有琴歌於編蓬之中，用此道也。","sortOrder":148},
  {"id":"s_work_nvlt_35_149","chapterId":"ch_work_nvlt_35","text":"【詩】晉張望詩曰：荒墟人跡希，隱僻闾鄰闊，苇篱自朽損，毀屋正寥豁，炎夏無完絺，玄冬無暖褐，四體困寒暑，六時疲飢渴，營生生愈瘁，愁來不可割。","sortOrder":149},
  {"id":"s_work_nvlt_35_150","chapterId":"ch_work_nvlt_35","text":"晉江逌詩曰：荜門不啟扇，環堵蒙蒿榛，空瓢覆壁下，箄上自生尘，出問誰氏子，憊哉一何貧。","sortOrder":150},
  {"id":"s_work_nvlt_35_151","chapterId":"ch_work_nvlt_35","text":"宋陶潛貧士詩曰：萬族各有讬，孤雲獨無依，暧暧虛中滅，何時見餘暉。","sortOrder":151},
  {"id":"s_work_nvlt_35_152","chapterId":"ch_work_nvlt_35","text":"又詩曰：安貧守賤者，自古有黔娄，好爵吾弗營，厚饋吾不酬，一旦寿命盡，蔽覆乃不周，豈不知其極，非道固無忧。","sortOrder":152},
  {"id":"s_work_nvlt_35_153","chapterId":"ch_work_nvlt_35","text":"梁朱超詠貧詩曰：觸涂皆可试，惟貧獨未安，窗开兩片月，霜足一重寒，藁濕鋪床冷，荷脆補衣難，若言為客易，推劍與君彈。","sortOrder":153},
  {"id":"s_work_nvlt_35_154","chapterId":"ch_work_nvlt_35","text":"【賦】漢楊雄逐貧賦曰：楊子遁世，離俗隱處，左鄰崇山，右接曠野，鄰垣乞兒，終貧且窭，禮薄義敝，相與群聚，惆怅失志，呼貧與語，汝在六極，投弃荒遐，好為庸卒，刑戮是加，匪惟幼稚，嬉戲土沙，亦非近鄰，接屋連家，恩輕毛羽，義薄輕羅，進不由德，退不受呵，久為滯客，其意若何，人皆文繡，餘褐不完，人皆稻糧，我獨藜餐，貧無寶玩，何以接歡，宗室之宴，為樂不期，徒行負賃，出處易衣，身服百役，手足胼胝，或耘或耔，霑體露肌，朋友道絕，進官凌遲，厥咎安在，職汝為之，舍汝遠竄，崑崙之巔，爾复我隨，翰飛戾天，舍爾登山，嵒穴隱藏，爾复隨我，陟彼高岡，舍爾入海，汎彼柏舟，爾复我隨，載沉載浮，我行爾動，我靜汝休，豈無他人，從我何求，今汝去矣，勿复久留，貧曰唯唯，主人見逐，多言益蚩，心有所懷，原得盡辭，昔我乃祖，宣其明德，克佐帝尧，誓為典則，土階茅茨，匪彫匪飾，爰及季世，縱其昏惑，饕餮之群，貪富苟得，鄙我先人，乃傲乃驕，瑤台琼室，華屋崇高，流酒為池，積肉為肴，是用鵠逝，不踐其朝，三省吾身，謂予無愆，處君之所，福祿如山，忘我大德，思我小怨，堪寒能暑，少而習焉，寒暑不忒，等寿神仙，桀跖不顧，貪類不幹，人皆重閉，子獨露居，人皆怵惕，子獨無虞，言辭既罄，色厲目張，攝斋而興，降階下堂，逝將去汝，適彼首陽，孤竹之子，與我連行，予乃避席，辭謝不直，請不貳過，聞義則服，長與爾居，終無厭極，貧遂不去，與我遊息。","sortOrder":154},
  {"id":"s_work_nvlt_35_155","chapterId":"ch_work_nvlt_35","text":"又晉束晳貧家賦曰：餘遭家之轗軻，婴六極之困屯，恒{勤心}身以勞思，丁飢寒之苦辛，無原憲之厚德，有民斯之下貧，有漏狹之草屋，無蔽覆之受尘，唯曲壁之常在，時弛落而壓镇，食草葉而不飽，常嗛嗛於膳珍，涉孟春之季月，迄仲冬之堅冰，稍煎蹙而窮迫，無衣褐以蔽身，還趨床而無被，手狂攘而妄牵，何夜長之難晓，心咨嗟以怨天，责家至而相敦，乃取東而偿西，行乞貸而無處，退顧影以自怜，衒賣葉而難售，遂前至於飢年，煮黃當之草菜，作汪洋之羹饘，釜遲钝而難沸，薪鬱絀而不然，至日中而不熟，心苦苦而飢懸，丈夫慨於堂上，妻妾叹於竈間，悲風噭於左侧，小兒啼於右邊。","sortOrder":155},
  {"id":"s_work_nvlt_35_156","chapterId":"ch_work_nvlt_35","text":"【箋】宋晃道元與天公箋曰：道居在城，南接水墟，草木幽鬱，蚊虻所藏，茅茨陋宇，才容數床，積汙累燻，體濬萎黃，冬則兩幅之薄被，心有牵黎與敝絮，撤以三股之絲綖，袷以四升之粗布，狹領不掩其巨形，促緣不覆其長度，申腳則足出，挛卷則脊露。","sortOrder":156},
  {"id":"s_work_nvlt_35_157","chapterId":"ch_work_nvlt_35","text":"【書】魏應璩與韦仲將書曰：夫以原憲懸罄之居，而值皇天無已之雨，薪刍既盡，舊穀亦傾匮，屠蘇發撤，機榻見謀，進無顏子不改之志，退無楊雄晏然之情，是以懷蹙，良不可堪，人非神仙，須仰衣食，方今體寒心飢，忧在旦夕，而欲東希誅［疑當作許。］昌治生之物，西望陝縣厨食之祿，誠恐將為牛蹄中魚，卒鮑氏之肆矣。","sortOrder":157},
  {"id":"s_work_nvlt_35_158","chapterId":"ch_work_nvlt_35","text":"又與董仲連書曰：穀籴驚踴，告求周鄰，日獲數升，猶复無薪可以熟之，雖孟軻困於梁宋，宣尼飢於陳蔡，無以過此，夫挟管晏之智者，不有厮役之勞，懷陶朱之慮者，不居貧賤之地，出蒙譏於恤護，入見謫於嫔息，忽便邑憤，不知處世之為樂。","sortOrder":158},
  {"id":"s_work_nvlt_35_159","chapterId":"ch_work_nvlt_35","text":"又與尚書諸郎書曰：夫秋節涼和，霖雨清閒，正高會之盛時，飲宴之良日也，而陋巷之居，無高密之宇，壁立之室，無旬朔之資，流潦浸於北堂，隙漏霑於衣服，藁蒸单竭，擔石傾罄，中饋告乏，役者莫興，飯玉炊桂，猶尚優泰，雖欣皇天之降润，亮水軍之思雨，私懷蹙頞，良不可言，想諸夫子，亦斯困也，夫否泰潛升，蓋由昏明，二三執事，以龍虎之姿，遭風雲之會，方將飛騰閶阖，振翼紫微，運筹帷幄，顯扬丰績，豈久沉滯於下職，契闊於貧悴哉。","sortOrder":159},
  {"id":"s_work_nvlt_35_160","chapterId":"ch_work_nvlt_35","text":"【文】後漢蔡邕九惟曰：八惟困乏，忧心殷殷，天之生我，星宿值貧，六極之厄，獨遭斯勤，居處浮漂，無以自在，冬日栗栗，上下同雲，無衣無褐，何以自溫，六月徂暑，炎赫來臻，無絺無绤，何以蔽身，無食不飽，永離懽欣。","sortOrder":160},
  {"id":"s_work_nvlt_35_162","chapterId":"ch_work_nvlt_35","text":"《周禮註》：男奴女婢，鄭司農註雲，奴，罪隸也，男女同名。","sortOrder":162},
  {"id":"s_work_nvlt_35_163","chapterId":"ch_work_nvlt_35","text":"又曰：其奴，男子入於罪隸，女子入於春［《太平御覽》五百作舂。］藁。","sortOrder":163},
  {"id":"s_work_nvlt_35_164","chapterId":"ch_work_nvlt_35","text":"又曰：奚三百人。註雲，今時侍史官奴婢也。","sortOrder":164},
  {"id":"s_work_nvlt_35_165","chapterId":"ch_work_nvlt_35","text":"《論語》曰：箕子為之奴。","sortOrder":165},
  {"id":"s_work_nvlt_35_166","chapterId":"ch_work_nvlt_35","text":"《左傳》曰：斐豹隸也，註曰：犯罪没為奴。","sortOrder":166},
  {"id":"s_work_nvlt_35_167","chapterId":"ch_work_nvlt_35","text":"《方言》曰：臧甬［音勇。］海［方言，《初學記》十九作侮。］獲奴婢賤稱也，荆淮海岱之間，骂奴曰臧，骂婢曰獲，齊之北鄙，燕之南郊，凡民男而婿婢，謂之臧，女而婦奴，謂之獲，亡奴謂之臧，亡婢謂之獲，亡［疑衍。］皆異方骂奴婢之丑稱也。","sortOrder":167},
  {"id":"s_work_nvlt_35_168","chapterId":"ch_work_nvlt_35","text":"《風俗通》曰：古製本無奴婢，犯事者原之，臧者被罪，没入為官奴，獲者逃亡，复得為婢。","sortOrder":168},
  {"id":"s_work_nvlt_35_169","chapterId":"ch_work_nvlt_35","text":"又曰：南陽庞俭，少失其父。後居庐里，凿井，得錢千餘萬，行求老蒼頭，使主牛馬耕种，直錢二萬。有賓婚大會，奴在竈下，竊言堂上母，我婦也。婢即具白母，母使俭問，曰：是我翁也。因下堂，抱其頸啼泣，遂為夫婦。俭及子歷二千石刺史七八人，時為之語曰：庐里諸庞，凿井得銅，買奴得翁。","sortOrder":169},
  {"id":"s_work_nvlt_35_170","chapterId":"ch_work_nvlt_35","text":"又曰：將作大匠陳國公孫志節，有蒼頭地餘，年十七，攻書疏，志節為戶曹吏，令地餘歸取物，餘馳車馬亡去，至丹陽，改姓王名斌，字文高，遂留為諸曹吏，志節拜楊州刺史，郡衣冠子弟皆出斌下，乃用之，斌乞屏左右，叩頭涕洟曰：斌即使君地餘也，斌後為蒼梧太守。","sortOrder":170},
  {"id":"s_work_nvlt_35_171","chapterId":"ch_work_nvlt_35","text":"《史記》曰：衛青為侯家人，少時歸，其父使牧羊，先母之子，皆奴畜之，不以為兄弟，青常至甘泉居室，有鉗徒相青曰：貴人也，官至封侯，青叹曰：人奴之生，得無笞骂足矣，安望封侯。","sortOrder":171},
  {"id":"s_work_nvlt_35_172","chapterId":"ch_work_nvlt_35","text":"又曰：栾布嘗為人所略，賣為奴，賣與燕將臧荼，後為都尉。","sortOrder":172},
  {"id":"s_work_nvlt_35_173","chapterId":"ch_work_nvlt_35","text":"又曰：齊俗賤奴虜，而刁聞［《太平御覽》五百作間，下同。］獨愛貴之，桀黠奴人之所患，唯刁聞收使之，終得其力。","sortOrder":173},
  {"id":"s_work_nvlt_35_174","chapterId":"ch_work_nvlt_35","text":"又曰：季布為朱家鉗奴。","sortOrder":174},
  {"id":"s_work_nvlt_35_175","chapterId":"ch_work_nvlt_35","text":"又曰：諸呂擅權，陆贾曰：天下安危，註意將相，將相和則士豫附，陳遂結懽太尉，以奴百人遺贾。","sortOrder":175},
  {"id":"s_work_nvlt_35_176","chapterId":"ch_work_nvlt_35","text":"又曰：衛將軍舍人，過平陽主家，主令騎奴同席而食，持刀斷席而坐。","sortOrder":176},
  {"id":"s_work_nvlt_35_177","chapterId":"ch_work_nvlt_35","text":"《漢書》曰：武帝時，募民能入奴婢，得以終身复，為郎，增秩。","sortOrder":177},
  {"id":"s_work_nvlt_35_178","chapterId":"ch_work_nvlt_35","text":"又曰：王鳳群弟爭為驕侈，奴僮以千數。","sortOrder":178},
  {"id":"s_work_nvlt_35_179","chapterId":"ch_work_nvlt_35","text":"又曰：張安世家僮七百人，皆有手技。","sortOrder":179},
  {"id":"s_work_nvlt_35_180","chapterId":"ch_work_nvlt_35","text":"又曰：王莽時，匈奴侵寇，乃大虜［漢書食货志，《初學記》十九作募。］囚徒人奴，名者［志，記作曰。］猪突倅［志，記作豨。］勇。","sortOrder":180},
  {"id":"s_work_nvlt_35_181","chapterId":"ch_work_nvlt_35","text":"又曰：宣帝詔，大司馬光，宿衛忠正，宣德明恩，前後賜奴婢百七十人。","sortOrder":181},
  {"id":"s_work_nvlt_35_182","chapterId":"ch_work_nvlt_35","text":"《新序》曰：昌邑王以侧註冠賜師及儒者，後以冠冠奴，龚遂免冠歸之，曰：今以冠冠奴，是奴虜畜惡也。","sortOrder":182},
  {"id":"s_work_nvlt_35_183","chapterId":"ch_work_nvlt_35","text":"《東觀漢記》曰：劉宽簡略，嗜酒，嘗坐客，使蒼頭市酒，大醉而還，對客骂曰畜生，宽遣人视奴，疑必自殺。","sortOrder":183},
  {"id":"s_work_nvlt_35_184","chapterId":"ch_work_nvlt_35","text":"又曰：韓卓，腊日奴竊食祭其母，卓義其心，即日免之。","sortOrder":184},
  {"id":"s_work_nvlt_35_185","chapterId":"ch_work_nvlt_35","text":"又曰：彭寵奴子密三人等，寵晝臥，密等遂縛寵著床，召其妻入縫纏囊，夜斷寵及妻頭，盛囊中，投世祖，世祖封子密為不義侯。","sortOrder":185},
  {"id":"s_work_nvlt_35_186","chapterId":"ch_work_nvlt_35","text":"又曰：邓弘奴醉，击長寿亭長，弘見亭長，賞錢五千，異日，奴得复［《東觀漢記》八复下有與字。］宮中衛士怒爭，衛士箠奴，弘聞。又與五千。","sortOrder":186},
  {"id":"s_work_nvlt_35_187","chapterId":"ch_work_nvlt_35","text":"前秦錄曰：慕容冲進通［《太平御覽》五百作逼，此訛。］長安，金城［○御覽作堅登城，此有訛脱。］觀之，大言责冲曰：爾辈群奴，正可牧羊牛，何為送死，冲曰：奴則奴矣，既厄奴苦，欲取爾相代。","sortOrder":187},
  {"id":"s_work_nvlt_35_188","chapterId":"ch_work_nvlt_35","text":"《蜀志》曰：劉琰侈靡，侍婢奴能為聲樂。又教誦靈光殿賦。","sortOrder":188},
  {"id":"s_work_nvlt_35_189","chapterId":"ch_work_nvlt_35","text":"《三辅决錄》曰：平陵孟佗，盡以家财賂張讓監奴，眾奴斬［《太平御覽》五百作慚。］焉，時賓客求見讓者，常數百乘，累日不得通焉，他後至，諸奴拜迎，径將他車獨往入，眾謂他與讓善，爭以珍物賂佗，佗得以賂讓。","sortOrder":189},
  {"id":"s_work_nvlt_35_190","chapterId":"ch_work_nvlt_35","text":"語［按本條事見宋書七十七沈慶之傳，語上當有脱文，《初學記》十九引作宋書。］曰：虜據滑，太祖欲北伐，沈慶之固陳不可，丹陽尹徐湛之吏部尚書江湛在座，湛之等難慶之，慶之曰：理國譬如理家，耕當使奴，織當問婢，陛下欲伐國，而與白面書生辈謀之，何由濟，上笑，曰傳［按此左傳桓二年文，有脱文，誤連上，當另作條。］士有隸子弟，［以其子弟為仆隸。］","sortOrder":190},
  {"id":"s_work_nvlt_35_191","chapterId":"ch_work_nvlt_35","text":"林邑記曰：范文，夷師奴也，以刀斫石障軒盧，［《初學記》十九作如斬芦苇，《太平御覽》九百三十七作如斬盧，此有脱訛，疑當作以刀斫石障，如斬芦苇。］後遂為國王。","sortOrder":191},
  {"id":"s_work_nvlt_35_192","chapterId":"ch_work_nvlt_35","text":"《江表傳》曰：穀利，孫權奴。","sortOrder":192},
  {"id":"s_work_nvlt_35_193","chapterId":"ch_work_nvlt_35","text":"【書】梁簡文帝答安吉公主餉胡子書曰：方言異俗，極有可觀，山高水遠，宛在其邈，不使去來執辔，媲彼青衣，正當出入燒香，還依丹轂，豈直王濟女奴，獨有羅袴，方使樂府行胡，羞論歌舞，垂膝新奇，伏增荷抃。","sortOrder":193},
  {"id":"s_work_nvlt_35_194","chapterId":"ch_work_nvlt_35","text":"漢王襃僮約曰：蜀郡王襃，以事止冤歸［《初學記》十九，《太平御覽》五百作寡婦。］楊惠舍，有一奴名便了，倩行酤酒，便捍大杖，上冢巔曰：大夫買便了時，但約守家，不約為他家男子酤酒也，襃大怒曰：奴寧欲賣邪，奴复曰：欲使便了，皆當上券，不上券，便了不能為也，襃乃為券曰：百役不得有二言，晨起早扫，飲食洗涤，居當穿臼縛帚，裁盂凿斗，出入不得騎馬載車，踑坐大怒，下床振頭，垂鉤刈刍，織履作粗，黏雀張鳥，結網捕魚，繳雁彈凫，登山射鹿，入水捕龟，後園縱魚，雁鶩百餘，驅逐鴟乌，持梢牧猪，种薑養羊，長育豚駒，粪除堂庑，食［初學記食上有餧字。］馬牛，鼓四起坐，夜半益刍，舍中有客，提壶行酤，汲水作餔，奴但當飯豆飲水，不得嗜酒，欲美飲［《初學記》作飲美。］酒，唯得染唇渍口，不得傾盂覆斗，不得晨出夜入，交關侔［《初學記》，御覽作伴。］偶，多取蒲茅，益作繩索，雨墮無所為，當編蒋織薄，植种桃李，梨柿柘桑，三丈一树，八行［御覽作尺。］為行，果類相從，蹤橫相當，果熟收斂，不得吮嘗，犬吠當起，驚告鄰里，搶門拄戶，上樓击柝，持盾曳矛，環落三周，勤心疾作，不得遨遊，奴老力索，种苋織席，事訖欲休，當舂一石，夜半無事，浣衣當白，若有私錢，主急賓客，奴不得有奸私，事事當开［○《初學記》作關。］白，奴不聽教，當笞一百，讀券文訖，辭窮诈索，仡仡叩頭，兩手自摶，目淚下落，鼻涕長一尺，審如王大夫言，不如早歸黃土陌，丘蚓鑽嵒，早知當爾，為王大夫酤酒，真不敢作惡。","sortOrder":194},
  {"id":"s_work_nvlt_35_196","chapterId":"ch_work_nvlt_35","text":"《管子》曰：齊桓公使管仲求甯戚，戚應之浩浩乎，仲不能，婢子問之，仲曰：非婢子所知也，婢子曰：詩有之，浩浩之水，育育之魚，未有家室，我將安居，甯子其欲室乎，仲以其言告桓公。","sortOrder":196},
  {"id":"s_work_nvlt_35_197","chapterId":"ch_work_nvlt_35","text":"《列女傳》曰：周室大夫仕於周，妻淫於鄰，主父還，恐覺之，為毒藥，使婢進上，婢恐殺主父，因僵覆酒，主父怒而笞之，妻因他過，欲殺婢，婢就杖將死而不言，主父弟聞之，复以言告主父，主父乃厚幣嫁之。","sortOrder":197},
  {"id":"s_work_nvlt_35_198","chapterId":"ch_work_nvlt_35","text":"《漢書》曰：傅太後使謁者買諸官婢，賤取之，复取執金吾官婢八人。","sortOrder":198},
  {"id":"s_work_nvlt_35_199","chapterId":"ch_work_nvlt_35","text":"《東觀漢記》曰：劉宽向朝會，裝已訖，婢奉肉羹翻，汙衣，宽神色不異，乃徐語曰：羹烂爾手。","sortOrder":199},
  {"id":"s_work_nvlt_35_200","chapterId":"ch_work_nvlt_35","text":"又曰：朱暉為郡督郵，太守阮况當嫁女，欲買暉婢，暉不與，及况卒，暉送金三斤，問其故，暉曰：前不與婢者，以财汙府君，金重送，欲明使君。","sortOrder":200},
  {"id":"s_work_nvlt_35_201","chapterId":"ch_work_nvlt_35","text":"謝承《後漢書》［《太平御覽》五百，本條作東觀漢記。］曰：長沙视［○御覽作祝。］良為洛陽令，常侍樊丰妻殺侍婢，置井中，良收其妻殺之。","sortOrder":201},
  {"id":"s_work_nvlt_35_202","chapterId":"ch_work_nvlt_35","text":"《晉書》曰：烈宗之母，本織坊中婢也，形長色黑，宮人謂之崑崙，太宗以大［原脱，據冯校本補。］計幸之，有身。","sortOrder":202},
  {"id":"s_work_nvlt_35_203","chapterId":"ch_work_nvlt_35","text":"《語林》曰：裴秀母是婢，秀年十八，有令望，而嫡母妒，猶令秀母親下食與眾賓，賓見，併起拜之，答曰：微賤豈宜如此，當為小兒故耳，於是父母乃不敢复役之。","sortOrder":203},
  {"id":"s_work_nvlt_35_204","chapterId":"ch_work_nvlt_35","text":"皇甫謐列女後傳曰：會稽翟素，受娉，未及配適，遭賊，欲犯之，臨之以白刃，素曰：我可得而殺，不可得而辱，素婢名青，乞代素，賊遂殺素，复欲犯青，青曰：向欲代素者，恐被恥獲害耳，今素已死，我何以生為，賊复殺之。","sortOrder":204},
  {"id":"s_work_nvlt_35_205","chapterId":"ch_work_nvlt_35","text":"《搜神記》曰：晉杜嘏家葬，而婢誤不得出，十餘年开墓，婢尚生，雲其始如眠，有頃漸覺，自謂一再宿，初婢之埋，年十五六，及开冢時，猶十五六，嫁之有子。","sortOrder":205},
  {"id":"s_work_nvlt_35_206","chapterId":"ch_work_nvlt_35","text":"又曰：諸葛恪已被誅，其［《太平御覽》五百其下有妻字，此脱。］在室，問婢，爾何故血臭，婢忽然起躍，頭至棟，攘臂切齒。","sortOrder":206},
  {"id":"s_work_nvlt_35_207","chapterId":"ch_work_nvlt_35","text":"《晉中興書》曰：祖約為丞相從事中郎，於府內為婢所傷，司直劉隗奏約，患生婢仆，身被傷刑，解職還家。","sortOrder":207},
  {"id":"s_work_nvlt_35_208","chapterId":"ch_work_nvlt_35","text":"《世說》曰：鄭玄家奴婢讀書，玄嘗使一婢，不稱旨，將撻之，方自陳說，玄怒，使人曳著泥中，須臾，复一婢來，問曰：胡為乎泥中，答曰：薄言往訴，逢彼之怒。","sortOrder":208},
  {"id":"s_work_nvlt_35_209","chapterId":"ch_work_nvlt_35","text":"又曰：石崇富侈，廁常令婢數十，曳羅縠直之。","sortOrder":209},
  {"id":"s_work_nvlt_35_210","chapterId":"ch_work_nvlt_35","text":"又曰：崇婢绿珠，天下美色，孫秀求之不與，因誅崇。","sortOrder":210},
  {"id":"s_work_nvlt_35_211","chapterId":"ch_work_nvlt_35","text":"又曰：光祖［世說德行篇作祖光祿，此有脱倒。］少孤貧，至孝，常自炊爨，王北平［世說作平北。］聞而佳之，乃以二婢餉焉，因取為吏人，人戲之曰：奴贾倍於婢，祖答曰：百里奚亦何必不輕於五羖之皮也。","sortOrder":211},
  {"id":"s_work_nvlt_35_212","chapterId":"ch_work_nvlt_35","text":"《三辅决錄》曰：金禕為郡上計，留在許都，時魏武使長史王必，將兵衛天子於許，禕與必善，見禕有胡婢善射，必常從請之。","sortOrder":212},
  {"id":"s_work_nvlt_35_213","chapterId":"ch_work_nvlt_35","text":"【賦】後漢蔡邕青衣賦曰：金生沙砾，珠出蚌泥，叹茲窈窕，生於卑微，玄發光润，領如螬蛴，脩長冉冉，硕人其頎，綺繡丹裳，躡蹈絲韦，都冶妩媚，卓砾多姿，精慧小心，趣事若飛，寒雪翩翻，充庭盈階，停停溝侧，噭々青衣，我思遠逝，爾思來追，明月昭昭，當我戶扉，條風狎獵，吹予床帷，河上逍遙，徙倚庭階，南瞻井柳，仰察斗機，非彼牛女，隔於河維，思爾念爾，惄焉且飢。","sortOrder":213},
  {"id":"s_work_nvlt_35_214","chapterId":"ch_work_nvlt_35","text":"後漢張安超譏青衣賦曰：彼何人斯，悅此艳姿，麗辭美譽，雅詞斐斐，文則可嘉，志鄙意微，鳳兮鳳兮，何德之衰，醴泉可飲，何必洿泥，隋珠彈雀，堂溪刈葵，鴛雏啄鼠，何異於鴟，歷觀古今，禍福之階，晏婴絜志，不顧景女，及俊不疑，奉霍不受，見尊不迷，况此隸竖，生女為妾，生男為虜，歲時醊祀，詣其先祖，或於馬廄，厨門竈下，東向長跪，接神觴酒，悉請諸靈，辟邪富主，多乞步少，銅丸鐵柱，績繒累嘉，皆來集聚，臧獲之類，蓋不足數，古之赘婿，尚為尘垢，况明智者，欲作奴父，勤節君子，無當自逸，宜如防水，守之以一，秦缪思襃，故獲終吉。","sortOrder":214},
  {"id":"s_work_nvlt_35_215","chapterId":"ch_work_nvlt_35","text":"◇佣保","sortOrder":215},
  {"id":"s_work_nvlt_35_216","chapterId":"ch_work_nvlt_35","text":"《史記》曰：荆軻死，高漸離变姓名，為人佣保，作於宋子，［縣名。］久之作苦，聞其家堂上客击筑，不能去，徬徨，從者告其主，便击筑，一坐稱善。","sortOrder":216},
  {"id":"s_work_nvlt_35_217","chapterId":"ch_work_nvlt_35","text":"又曰：栾布與彭越為家人。","sortOrder":217},
  {"id":"s_work_nvlt_35_218","chapterId":"ch_work_nvlt_35","text":"《鶡冠子》曰：伊尹酒保，立為世師。","sortOrder":218},
  {"id":"s_work_nvlt_35_219","chapterId":"ch_work_nvlt_35","text":"《藝文類聚》　唐·欧陽詢","sortOrder":219},
  {"id":"s_work_nvlt_36_1","chapterId":"ch_work_nvlt_36","text":"卷三十六人部二十","sortOrder":1},
  {"id":"s_work_nvlt_36_2","chapterId":"ch_work_nvlt_36","text":"○隱逸上","sortOrder":2},
  {"id":"s_work_nvlt_36_3","chapterId":"ch_work_nvlt_36","text":"◇隱逸上","sortOrder":3},
  {"id":"s_work_nvlt_36_4","chapterId":"ch_work_nvlt_36","text":"《周易》曰：遯世無悶。","sortOrder":4},
  {"id":"s_work_nvlt_36_5","chapterId":"ch_work_nvlt_36","text":"又曰：天地閉，賢人隱。","sortOrder":5},
  {"id":"s_work_nvlt_36_6","chapterId":"ch_work_nvlt_36","text":"又曰：不事王侯，高尚其事。","sortOrder":6},
  {"id":"s_work_nvlt_36_7","chapterId":"ch_work_nvlt_36","text":"又曰：贲於丘園，束帛戋戋，《禮記》曰：儒有上不臣天子，下不事諸侯。","sortOrder":7},
  {"id":"s_work_nvlt_36_8","chapterId":"ch_work_nvlt_36","text":"又曰：季春之月，聘名士，禮賢者。","sortOrder":8},
  {"id":"s_work_nvlt_36_9","chapterId":"ch_work_nvlt_36","text":"《論語》曰：逸民，伯夷叔齊虞仲夷逸朱張柳下惠少連。","sortOrder":9},
  {"id":"s_work_nvlt_36_10","chapterId":"ch_work_nvlt_36","text":"《莊子》曰：古之所謂隱士者，非伏其身而不見也，非閉其言而不出也，非藏其知而不發也，時命大谬也。","sortOrder":10},
  {"id":"s_work_nvlt_36_11","chapterId":"ch_work_nvlt_36","text":"又曰：刻意尚行，離世異俗，此山穀之士，避世之人也，就藪泽，處間曠，釣魚閒處，無為而已矣，此江海之士，避世之人也，閒暇之所好也。","sortOrder":11},
  {"id":"s_work_nvlt_36_12","chapterId":"ch_work_nvlt_36","text":"嵇康《高士傳》曰：廣成子在崆峒之上，黃帝問曰：吾欲取天地之精，以養萬物，為之奈何，廣成子蹶然而起曰：至道之精，窈窈冥冥，無视無聽，抱神以靜，我守其一，以處其和，故千二百歲而形未嘗衰，得吾道者，上為皇，下為王，失吾道者，上見光，而下為土，吾將去汝，入無窮之門，遊無極之野，與日月參光，與天地為常。","sortOrder":12},
  {"id":"s_work_nvlt_36_13","chapterId":"ch_work_nvlt_36","text":"又曰：黃帝將見大隗於具茨之山，方明為御，昌宇參乘，黃帝曰：［本句上有脱文。］異哉，請問天下，小童曰：予少遊六合之外，適有瞀病，有長者教予，乘日之車，遊於襄城之野，今病少損，將复六合之外，為天下者，予奚事焉，夫為天下，亦奚異牧馬哉，去其害馬而已，黃帝再拜，稱天師而還。","sortOrder":13},
  {"id":"s_work_nvlt_36_14","chapterId":"ch_work_nvlt_36","text":"又曰：善卷者，舜以天下讓之，卷曰：予立宇宙之中，冬衣皮毛，夏衣絺葛，日出而作，日入而息，逍遙天地之間，何以為天下哉，遂入深山，莫知其所終。","sortOrder":14},
  {"id":"s_work_nvlt_36_15","chapterId":"ch_work_nvlt_36","text":"又曰：石戶之農，不知何許人，與舜為友，舜以天下讓之，石戶夫負妻携子以入海，終身不返。","sortOrder":15},
  {"id":"s_work_nvlt_36_16","chapterId":"ch_work_nvlt_36","text":"又曰：伯成子高者，唐虞之時為諸侯，至禹，去而耕，禹往趨而問之，子高曰：昔尧治天下，至公無私，不賞而民勸，不罰而民畏，今子賞而不勸，罰而不威，德自此衰，刑自此作，夫子盍行乎，無落吾事，俋俋乎耕而不顧。","sortOrder":16},
  {"id":"s_work_nvlt_36_17","chapterId":"ch_work_nvlt_36","text":"又曰：魯連好奇伟倜傥，嘗遊趙，難新垣衍以秦為帝，秦軍為却，平原君欲封連，連三辭，平原君乃以千金為連寿，連笑曰：所貴於天下之士者，為人排患釋難也，即有取之，是商贾之事爾，及燕將守遼［史記八十三魯仲連傳作聊。］城，田单攻之不能下，連乃為書射城中，遺燕將，燕將見書，泣三日，乃自殺，城降，田单欲爵連，連曰：吾與於富貴而诎於人，寧貧賤輕世而肆意。","sortOrder":17},
  {"id":"s_work_nvlt_36_18","chapterId":"ch_work_nvlt_36","text":"又曰：闾丘先生，齊宣王獵於社山，社山父老十三人，相與勞王，王賜父老不租，先生獨不謝，曰：原得寿得富得貴，夫選良吏，平法度，則臣得寿矣，振之以時，則臣得富矣，令少敬長，則臣得貴矣。","sortOrder":18},
  {"id":"s_work_nvlt_36_19","chapterId":"ch_work_nvlt_36","text":"又曰：田生菅床茅屋，不肯仕宦，惠帝親自往，不出屋。","sortOrder":19},
  {"id":"s_work_nvlt_36_20","chapterId":"ch_work_nvlt_36","text":"又曰：鄭仲虞不仕漢朝，章帝自往，終不肯起，曰：陛下何惜不為上世君，令臣得為偃息之民，天子以尚書祿終其身，世號白衣尚書。","sortOrder":20},
  {"id":"s_work_nvlt_36_21","chapterId":"ch_work_nvlt_36","text":"又曰：韓福者，以行義脩絜，漢昭帝時，以德行徵，病不進，元鳳元年，詔賜帛五十匹，遣長吏時以存問，常以八月賜羊酒，不幸死者，賜複衾一，祠以中牢，自是至今為徵士之故事，福終身不仕，卒於家。","sortOrder":21},
  {"id":"s_work_nvlt_36_22","chapterId":"ch_work_nvlt_36","text":"又曰：班嗣世在京師，家有賜書，內足於财，父党楊子雲以下，莫不造門，桓君山從借莊子，嗣報曰：今吾子聞仁義之羁绊，系聲名之韁鎖，伏孔氏之軌躅，馳顏闵之極藝，何以大道為自眩也，昔有學步邯鄲者，匍匐而歸耳，其行己持論如此，遂終於家。","sortOrder":22},
  {"id":"s_work_nvlt_36_23","chapterId":"ch_work_nvlt_36","text":"又曰：尚長，字子平，禽慶，字子夏，二人相善，慶隱避不仕王莽，長通易老子，安貧樂道，好事者更饋遺，辄受之，自足還餘，如有不取也，舉措必於中和，司空王邑，辟之連年，乃欲荐之於莽，固辭乃止，遂求退，讀易至損益卦，喟然叹曰：吾知富貴不如貧賤，未知存何如亡爾，為子嫁娶畢，敕家事斷之，勿复相關，當如我死矣，是後肆意，與同好遊五嶽名山，遂不知所在。","sortOrder":23},
  {"id":"s_work_nvlt_36_24","chapterId":"ch_work_nvlt_36","text":"又曰：巢父，尧時隱人，年老，以树為巢，而寢其上，故人號為巢父，尧之讓許由也，由以告巢父，巢父曰：汝何不隱汝形，藏汝光，非吾友也，乃击其膺而下之，許由怅然不自得，乃遇清泠之水，洗其耳，拭其目，曰：乡者聞言，負吾友，遂去，終身不相見。","sortOrder":24},
  {"id":"s_work_nvlt_36_25","chapterId":"ch_work_nvlt_36","text":"又曰：許由，字武仲，尧舜皆師之，與齧缺論尧而去，隱乎沛泽之中，尧舜乃致天下而讓焉，曰：十日併出，而爝火不息，其光也不亦難乎，夫子為天子，則天下治，我由尸之，吾自视缺然，許由曰：吾將為名乎，名者實之賓，吾將為賓乎，乃去，宿於逆旅之家，旦而遺其皮冠，巢父聞由為尧所讓，以為汙，乃臨池水而洗其耳，池主怒曰：何以汙我水，由乃退而遯耕於中嶽，潁水之陽，箕山之下。","sortOrder":25},
  {"id":"s_work_nvlt_36_26","chapterId":"ch_work_nvlt_36","text":"又曰：壤父者，尧時人，年五十而击壤於道中，觀者曰：大哉帝之德也，壤父曰：吾日出而作，日入而息，凿井而飲，耕地而食，帝何德於我哉。","sortOrder":26},
  {"id":"s_work_nvlt_36_27","chapterId":"ch_work_nvlt_36","text":"又曰：子支伯者，舜以天下讓支伯，支伯曰：予適有幽忧之病，方且治之，未暇治天下也，遂不知所之。","sortOrder":27},
  {"id":"s_work_nvlt_36_28","chapterId":"ch_work_nvlt_36","text":"又曰：被裘公者，吳人也，延陵季子出遊，見道中遺金，顧而睹之，謂公曰：取彼金，公投鑣瞋目，拂手而言曰：何子居之高，视之卑，吾被裘而負薪，豈取遺金者哉，季子大驚，既謝而問其姓名，曰：吾子皮相之士，何足語姓名哉。","sortOrder":28},
  {"id":"s_work_nvlt_36_29","chapterId":"ch_work_nvlt_36","text":"又曰：段幹木者，治清節，遊西河，守道不仕，魏文侯就造其門，幹木逾牆而避之，文侯以客禮，出過其庐則式，其仆問之，文侯曰：幹木不趣势，隱處窮巷，聲馳千里，敢勿式乎，文侯所以名過齊桓公者，能尊段幹木，敬卜子夏，友田子方也。","sortOrder":29},
  {"id":"s_work_nvlt_36_30","chapterId":"ch_work_nvlt_36","text":"又曰：莊周少學老子，梁惠王時，為蒙縣漆園吏，以卑賤，不肯仕，楚威王以百金聘周，周方釣於濮水之上，曰：楚有龟，死三千歲矣，今巾笥而藏之於廟堂之上，此龟寧生而掉尾涂中耳，子往矣，吾方掉尾於涂中，後齊宣王又以千金之幣，迎周為相，周曰：子不見郊祭之犧牛乎，衣以文繡，食以刍菽，及其牵入太廟，欲為孤豚，其可得乎，遂終身不仕。","sortOrder":30},
  {"id":"s_work_nvlt_36_31","chapterId":"ch_work_nvlt_36","text":"《續晉陽秋》曰：謝敷隱居會稽山，初月犯少微星，一名處士星，時戴逵名重於敷，時人忧之，俄而敷死，故會稽士人嘲吳人雲，吳中高士，求死不得。","sortOrder":31},
  {"id":"s_work_nvlt_36_32","chapterId":"ch_work_nvlt_36","text":"《世說》曰：郄超每聞欲高尚隱退者，辄為辦百萬資，併為造立居宇，在剡，為戴公起宅甚精，戴始往居，與所親書曰：近在剡，如入官舍。又為傅約亦辦百萬，傅隱事差互，故不果述。","sortOrder":32},
  {"id":"s_work_nvlt_36_33","chapterId":"ch_work_nvlt_36","text":"又曰：支道林因人就深公買印山，深公曰：未聞巢由買山而隱。","sortOrder":33},
  {"id":"s_work_nvlt_36_34","chapterId":"ch_work_nvlt_36","text":"袁淑真隱傳曰：鬼穀先生，不知何許人也，隱居韜智，居鬼穀山，因以為稱，蘇秦張儀師之，遂立功名，先生遺書责之曰：若二君豈不見河邊之树乎，仆御折其枝，波浪荡其根，上無径尺之陰，身被數千之痕，此木豈與天地有仇怨，所居然也，子不見嵩岱之松柏，華霍之檀桐乎，上枝幹於青雲，下根通於三泉，千秋萬歲，不受斧斤之患，此木豈與天地有骨肉哉，蓋所居然也。","sortOrder":34},
  {"id":"s_work_nvlt_36_35","chapterId":"ch_work_nvlt_36","text":"又曰：鶡冠子，或曰楚人，隱居幽山，衣敝履空，以鶡為冠，莫测其名，因服成號，著書言道家，冯谖常師事之，後顯於趙，鶡冠子懼其荐己也，乃與谖絕。","sortOrder":35},
  {"id":"s_work_nvlt_36_36","chapterId":"ch_work_nvlt_36","text":"【詩】魏阮瑀詩曰：四晧潛南嶽，老萊竄河濱，顏回樂陋巷，許由安賤貧，伯夷饿首陽，天下歸其仁，何患處貧苦，但當守明真。","sortOrder":36},
  {"id":"s_work_nvlt_36_37","chapterId":"ch_work_nvlt_36","text":"晉張華招隱詩曰：隱士讬山林，遁世以保真，連惠亮未遇，雄才屈不申。","sortOrder":37},
  {"id":"s_work_nvlt_36_38","chapterId":"ch_work_nvlt_36","text":"又詩曰：栖遲四野外，陆沉背當時，循名奄不著，藏器待無期，羲和策六龍，弭節越崦嵫，盛年俯仰過，忽若振輕絲。","sortOrder":38},
  {"id":"s_work_nvlt_36_39","chapterId":"ch_work_nvlt_36","text":"晉張載招隱詩曰：出處雖殊涂，居然有輕易，山林有悔吝，人間實多累，鵷雏翔穹冥，蒲且不能视，鸛鷺遵皋渚，數為矰所系，隱顯雖在心，彼我共一地，不見巫山火，芝艾豈相離，去來捐時俗，超然辭世伪，得意在丘中，安事愚與智。","sortOrder":39},
  {"id":"s_work_nvlt_36_40","chapterId":"ch_work_nvlt_36","text":"晉張协詩曰：結宇窮岚曲，耦耕幽藪陰，荒庭寂以閒，山岫峭且深，凄風起東穀，有弇興南岑，雖無箕畢期，膚寸自成霖，泽雉登垄雊，寒猿擁條吟，溪壑無人跡，荒楚鬱萧森，投禾脩岸垂，時聞樵采音，重棋可擬志，回淵可比心，養真尚無為，道勝貴陆沉，遊思竹素園，寄辭翰墨林。","sortOrder":40},
  {"id":"s_work_nvlt_36_41","chapterId":"ch_work_nvlt_36","text":"晉左思招隱詩曰：杖策招隱士，荒涂橫古今，巖穴無結構，丘中有鳴琴，白雪傍陰岗，丹葩耀陽林，非必絲與竹，山水有清音，何事待嘯歌，灌木自悲吟。","sortOrder":41},
  {"id":"s_work_nvlt_36_42","chapterId":"ch_work_nvlt_36","text":"又招隱詩曰：經始東山庐，果下自成榛，前有寒泉井，聊可瑩心神。","sortOrder":42},
  {"id":"s_work_nvlt_36_43","chapterId":"ch_work_nvlt_36","text":"晉陆機招隱詩曰：駕言尋飛遁，山路鬱盤桓，芳蘭振蕙葉，玉泉涌微澜，嘉卉獻時服，靈術進朝餐，朝采南涧т，夕息西山足，輕條象雲構，密葉成翠屋，結風佇蘭林，回芳薄秀木。","sortOrder":43},
  {"id":"s_work_nvlt_36_44","chapterId":"ch_work_nvlt_36","text":"又詩曰：尋山求逸民，穹穀幽且遐，清泉荡玉渚，文魚躍中波。","sortOrder":44},
  {"id":"s_work_nvlt_36_45","chapterId":"ch_work_nvlt_36","text":"晉闾丘冲招隱詩曰：大道曠且夷，蹊路安足尋，經世有险易，隱顯自存心，嗟哉巖岫士，歸來從所钦。","sortOrder":45},
  {"id":"s_work_nvlt_36_46","chapterId":"ch_work_nvlt_36","text":"晉王康琚招隱詩曰：登山招隱士，褰裳躡遺蹤，華條當圜室，翠葉代綺窗。","sortOrder":46},
  {"id":"s_work_nvlt_36_47","chapterId":"ch_work_nvlt_36","text":"晉辛曠赠皇甫謐詩曰：顒顒朝士，亦孔其依，莫不遲想，載渴載飢，我弓我旄，禮亦無违，企望高岡，來儀來歸，其暉伊何，與帝同心，明明天子，如日之臨，臨照四方，探赜幽深，山無逸民，水無潛龍，爰彼九皋，克量德音，茂哉先生，皇實是钦。","sortOrder":47},
  {"id":"s_work_nvlt_36_48","chapterId":"ch_work_nvlt_36","text":"宋謝靈運越嶺行溪詩曰：猿鳴誠知曙，幽穀光未顯，巖下雲方合，花上露猶泫，逶迤傍嵔〈山奧〉，迢遰陟陉峴，蘋萍泛深沉，蒲菰冒清淺，企石挹飛泉，攀林摘葉卷，想見山阿人，萝薜若在眼。","sortOrder":48},
  {"id":"s_work_nvlt_36_49","chapterId":"ch_work_nvlt_36","text":"梁武帝逸民詩曰：如垅生木，木有異心，如林鳴鳥，鳥有殊音，如江遊魚，魚有浮沉，巖巖山高，湛湛水深，事跡易見，理相難尋。","sortOrder":49},
  {"id":"s_work_nvlt_36_50","chapterId":"ch_work_nvlt_36","text":"梁劉孝標始居山營室詩曰：自昔厭喧嚣，執志好栖息，嘯歌弃城市，歸來事耕織，凿戶闚嶕峣，开軒望嶄崱，激水簷前溜，脩竹堂陰植，香風鳴紫湋，高梧巢绿翼，泉脈洞沓沓，流波下不極，仿佛玉山隈，响像瑤池侧，夜誦神仙記，旦吸雲霞色，將馭六龍舆，行從三鳥食，誰與金門士，撫心論焜臆。","sortOrder":50},
  {"id":"s_work_nvlt_36_51","chapterId":"ch_work_nvlt_36","text":"梁范雲答句曲先生詩曰：終朝吐祥霧，薄晚孕奇煙，洞涧生芝草，重崖出醴泉，中有懷真士，被褐守冲玄，石戶栖十秘，金壇謁九仙，乘鵷方履漢，辔鶴上騰天。","sortOrder":51},
  {"id":"s_work_nvlt_36_52","chapterId":"ch_work_nvlt_36","text":"梁吳筠詩曰：山际見來煙，竹中窥落日，鳥向簷上飛，雲從窗里出。","sortOrder":52},
  {"id":"s_work_nvlt_36_53","chapterId":"ch_work_nvlt_36","text":"又詩曰：绿竹可充食，女萝可代裙，山中自有宅，桂树籠青雲。","sortOrder":53},
  {"id":"s_work_nvlt_36_54","chapterId":"ch_work_nvlt_36","text":"又詩曰：具區窮地险，稽山萬里餘，奈何梁隱士，一去無還書。","sortOrder":54},
  {"id":"s_work_nvlt_36_55","chapterId":"ch_work_nvlt_36","text":"梁任昉答劉居士詩曰：君子之道，亦有其四，高行絕俗，盛德出類，才同文錦，學非書肆，望之可階，即之難至，輟精天理，躔象少微，人與俗異，道與人违，庭飛熠燿，室滿伊威，行無轍跡，理絕心機。","sortOrder":55},
  {"id":"s_work_nvlt_36_56","chapterId":"ch_work_nvlt_36","text":"又答何徵君詩曰：散誕羁鞿外，拘束名教里，得性千乘同，山林無朝市，勿以耕蠶貴，空笑易農仕，宿昔仰高山，超然絕尘軌，傾［原脱，據冯校本補。］壶已等藥，命管亦齊□，無為叹獨遊，若終方同止。","sortOrder":56},
  {"id":"s_work_nvlt_36_57","chapterId":"ch_work_nvlt_36","text":"又赠徐徵君詩曰：促生悲永路，早交傷晚別，自我隔容徽，於焉徂歲月，情非山河阻，意似河湖悅，東皋有儒素，杳與榮名絕，曾是违賞心，曷用箴餘缺，眇焉追平生，尘書废不閱，信此伊能已，懷抱豈暫輟，何以表相思，貞松擅嚴節。","sortOrder":57},
  {"id":"s_work_nvlt_36_58","chapterId":"ch_work_nvlt_36","text":"梁庾肩吾赠周處士詩曰：九丹开石室，三径没荒林，仙人翻可見，隱士更難尋，篱下黃花菊，丘中白雪琴，方欣松葉酒，自和遊山吟。","sortOrder":58},
  {"id":"s_work_nvlt_36_59","chapterId":"ch_work_nvlt_36","text":"又尋周處士弘讓詩曰：试遂赤松遊，披林對一丘，梨紅大穀晚，桂白小山秋，石鏡菱花發，桐門琴曲愁，泉飛疑度雨，雲積似重樓，王孫若不去，山中定可留。","sortOrder":59},
  {"id":"s_work_nvlt_36_60","chapterId":"ch_work_nvlt_36","text":"又賦得嵇叔夜詩曰：山林重明滅，風月臨嚣尘，著書惟隱士，談玄止穀神，雁重翻傷性，蠶寒更養身，廣陵餘故曲，山陽有舊鄰，俗俭寧妨患，才多反累身，寄言山吏部，無以助庖人。","sortOrder":60},
  {"id":"s_work_nvlt_36_61","chapterId":"ch_work_nvlt_36","text":"周明帝赠韦居士詩曰：六爻貞遁世，三辰少光微，潁陽去猶遠，沧洲遂不歸，風動秋蘭佩，香飄莲葉衣，坐石窥仙洞，乘槎下釣磯，嶺松千仞直，巖泉百丈飛，傥能同四隱，來參餘萬機。","sortOrder":61},
  {"id":"s_work_nvlt_36_62","chapterId":"ch_work_nvlt_36","text":"周王襃赠周處士詩曰：我行無歲月，征馬屢盤桓，崤曲三危阻，關重九折難，猶持漢節使，尚服楚臣冠，巢禽疑上幕，驚羽畏虛彈，飛蓬去不已，客思漸無端，壮志與時歇，生年隨事阑，百齡悲促命，數刻念餘歡，雲生隴坻黑，桑疏蓟北寒，鳥道無蹊径，清溪有波澜，思君化羽翮，要我鑄金丹。","sortOrder":62},
  {"id":"s_work_nvlt_36_63","chapterId":"ch_work_nvlt_36","text":"又和趙王隱士詩曰：凫鵠均長短，雕鷃共逍遙，清襟蘊秀氣，虛席滿風飆，斷絃唯續葛，獨酌止傾瓢，菖蒲九重節，桑薪七過燒。","sortOrder":63},
  {"id":"s_work_nvlt_36_64","chapterId":"ch_work_nvlt_36","text":"周庾信奉和趙王隱士詩曰：洛陽徵五隱，東都別二賢，雲氣浮函穀，星光集潁川，灞陵采樵路，成都賣卜錢，鹿裘披稍裂，藜床坐欲穿，阮籍唯長嘯，嵇康訝一絃，涧险無平石，山深足細泉，低松猶百丈，少鶴已千年，野鳥繁絃啭，山花焰火然，雖無亭長識，終見野人船。","sortOrder":64},
  {"id":"s_work_nvlt_36_65","chapterId":"ch_work_nvlt_36","text":"又窮秋寄隱士詩曰：王倪逢齧缺，桀溺遇長沮，藜床負日臥，麥隴帶經鋤，自然曲木幾，無名科斗書，聚花聊飼雀，穿池试養魚，小村治涩路，低田補坏渠，秋水牵沙落，寒藤抱树疏，空枉平原騎，來過仲蔚庐。","sortOrder":65},
  {"id":"s_work_nvlt_36_66","chapterId":"ch_work_nvlt_36","text":"陳周弘正還草堂尋處士弟詩曰：四時易荏苒，百齡倏將半，故老多零落，山僧盡凋散，宿树倒為查，舊水侵成岸，幽尋屬令弟，依然歸舊馆，感物自多傷，况乃春湋亂。","sortOrder":66},
  {"id":"s_work_nvlt_36_67","chapterId":"ch_work_nvlt_36","text":"陳周弘讓無名詩曰：行行訪名嶽，處處必留連，遂至一巖里，灌木上參天，忽見茅茨屋，暧暧有人煙，一士开門出，一士呼我前，相看不道姓，焉知隱與仙。","sortOrder":67},
  {"id":"s_work_nvlt_36_68","chapterId":"ch_work_nvlt_36","text":"陳伏知道賦得招隱詩曰：招隱訪仙楹，丘中琴正鳴，桂丛侵石路，桃花隔世情，薄暮安車近，林喧山鳥驚。","sortOrder":68},
  {"id":"s_work_nvlt_36_69","chapterId":"ch_work_nvlt_36","text":"陳正見賦得落落窮巷士詩曰：楊雲不邀名，原憲本遺榮，草長三径合，花發四鄰明，尘隨幽巷靜，嘯逐遠風清，門外無車轍，自可絕公卿。","sortOrder":69},
  {"id":"s_work_nvlt_36_70","chapterId":"ch_work_nvlt_36","text":"隋江總夏日還山庭詩曰：獨於幽栖地，山庭暗女萝，涧渍長低筱，池开半卷荷，野花朝暝落，盤根歲月多，停樽無賞慰，狎鳥自經過。","sortOrder":70},
  {"id":"s_work_nvlt_36_71","chapterId":"ch_work_nvlt_36","text":"又春夜山庭詩曰：春夜芳時晚，幽庭野氣深，山疑刻削意，树接縱橫陰，戶對忘忧草，池驚旅浴禽，樽中良得性，物外知餘心。","sortOrder":71},
  {"id":"s_work_nvlt_36_72","chapterId":"ch_work_nvlt_36","text":"隋王由禮賦得巖穴無結搆詩曰：巖間無結構，穀處極幽尋，葉落秋巢迫，雲生石路深，早梅香野径，清涧响丘琴，獨有栖遲客，留連芳杜心。","sortOrder":72},
  {"id":"s_work_nvlt_36_73","chapterId":"ch_work_nvlt_36","text":"【賦】後漢張衡歸田賦曰：遊都邑以永久，無明略以佐時，徒臨川以羨魚，俟河清乎未期，感蔡子之慷慨，從唐生以决疑，谅天道之微昧，追漁父以同嬉，於是仲春令月，時和氣清，原隰鬱茂，百草滋榮，王睢鼓翼，仓庚哀鳴，交頸頡〈亢鳥〉，關關嘤嘤，於焉逍遙，聊以娱情，於時曜靈俄景，繼以望舒，極盤遊之至樂，雖日夕以忘劬，感老氏之遺誡，且回駕乎蓬庐，彈五絃之妙指，詠周孔之圖書，揮翰墨以奋藻，陳三皇之軌模，苟縱心於域外，焉知榮辱之所拘。","sortOrder":73},
  {"id":"s_work_nvlt_36_74","chapterId":"ch_work_nvlt_36","text":"魏陳王曹植潛志賦曰：潛大道以遊志，希往昔之遐烈，矯貞亮以作矢，當苑囿乎藝窟，驅仁義以為禽，必信中而後發，退隱身以滅跡，進出世而取容，且摧刚而和謀，接處肅以靜恭，亮知榮而守辱，匪天路以焉通。","sortOrder":74},
  {"id":"s_work_nvlt_36_75","chapterId":"ch_work_nvlt_36","text":"晉張華歸田賦曰：隨陰陽之开阖，從時宜以卷舒，冬奧處以城邑，春遊放於外庐，歸郏鄏之舊里，讬言靜以閒居，育草木之藹蔚，因地势之丘墟，丰蔬果之林错，茂桑麻之紛敷，用天道以取資，行藥物以為娱，時逍遙於洛濱，聊相佯以縱意，目白沙與積砾，玩眾卉之同異，扬素波以濯足，溯清澜以荡思，低徊住留，栖遲菴藹，存神忽微，遊精域外，藉纖草以為茵，援垂陰以為蓋，瞻高鳥之陵風，臨鯈魚於清瀨，眇萬物而遠觀，脩自然之通會，以退足於一壑，故處否而忘泰。","sortOrder":75},
  {"id":"s_work_nvlt_36_76","chapterId":"ch_work_nvlt_36","text":"晉陆機幽人賦曰：世有幽人，漁釣乎玄渚，彈雲冕以辭世，披宵褐而延佇，是以物外莫得窥其奧，舉世不足扬其波，劲秋不能凋其葉，芳春不能發其華，超尘冥以絕緒，豈世網之能加。","sortOrder":76},
  {"id":"s_work_nvlt_36_77","chapterId":"ch_work_nvlt_36","text":"又應嘉賦曰：友人有作嘉遁賦與餘者，作賦應之，號曰應嘉雲，傲世公子，體逸懷遐，意邈澄宵，神夷靜波，仰群軌以遙企，頓駿翮以婆娑，寄冲氣於大象，解心累於世羅，袭三闾之奇服，詠南榮之清歌，濯下泉於浚涧，溯凯風於卷阿，指千秋以厲响，俟寂寞之來和，懷前脩之彷彿，觌幽人乎所過，抱玄景以獨寐，含芳風而寤語，發蘭音以清唱，摻玉懷而喻予，於是葺宇中陵，筑室河曲，軌絕千途，而門瞻百族，假妙道以達觀，考贲龟而貞卜，苟形骸之可忘，豈投簪其必穀，方介丘於尺阜，讬雲林乎一木，佇鳴條以招風，聆哀音其如玉，窮覽物以盡齒，將弭跡於餘足。","sortOrder":77},
  {"id":"s_work_nvlt_36_78","chapterId":"ch_work_nvlt_36","text":"晉陆雲逸民賦曰：富貴者，是人之所欲，而古之逸民，輕天下，細萬物，而欲专一丘之懽，擅一壑之美，豈不以身重於宇宙，而恬貴於芬華哉，天地不易其樂，萬物不幹其志，然後可以妙有生之極，固無疆之休，乃為賦曰：世有逸人，栖遲乎一丘，委天形以外心，淡浩然其何求，杖短策而遂往，乃枕石而漱流，靜芬响於詠言，滅絕景於质，［本集质上有無字。］相荒土以卜居，度山河而考室，曾丘翳薈，穹穀重深，巖木振穎，葛藟垂陰，潛魚泳沚，嘤鳥來吟，仍疏圃於茲薄，即蘭堂於芳林，靡飛飄以赴節，揮天籁以興音，假樂之於神造，詠幽人於鳴琴。","sortOrder":78},
  {"id":"s_work_nvlt_36_79","chapterId":"ch_work_nvlt_36","text":"晉孫承嘉遁賦曰：有嘉遁之玄人，含貞光之凯邁，靡薜荔於苑柳，荫翠葉之雲蓋，揮脩纶於洄澜，臨峥嵘而式墜，溯清風以長嘯，詠九韶而忘味，若乃御有撫生，應物宅心，曜應春圃，凋葉秋林，振藻陽波，清景玄陰，形猶與以徙靡，神曠寂而難尋，浑無名於域外，和丘中以草音，於是混心齊物，遨翔容與，薄言采薇，收萝中野，朝觀夷陆，夕步蘭渚，仰弋鳴雁，俯釣鲂鱮，遊無方之內，居無形之域，詠休遁之貞亨，察天心而觀复，委性命於玄芒，任吉凶而靡錄。","sortOrder":79},
  {"id":"s_work_nvlt_36_80","chapterId":"ch_work_nvlt_36","text":"宋謝靈運逸民賦曰：於止唯舍唯用，其見也則如遊龍，其潛也則如隱鳳，來無所從，去無所至，有酒則舞，無酒則醒，不明不晦，不昧不類，萧條秋首，兀我春中，弄琴明月，酌酒和風，御清風以遠路，拂白雲而峻舉，指寰中以為期，望系外而延佇。","sortOrder":80},
  {"id":"s_work_nvlt_36_81","chapterId":"ch_work_nvlt_36","text":"又入道至人賦曰：爰有名外之至人，乃入道而馆真，荒聰明以削智，遁支體以逃身，於是卜居千仞，左右窮懸，幽庭虛絕，荒帳成煙，水縱橫以觸石，日參差於雲中，飛英明於對溜，積氤氲而為峰，推天地於一物，橫四海於寸心，超埃尘以貞觀，何落落此焜襟。","sortOrder":81},
  {"id":"s_work_nvlt_36_82","chapterId":"ch_work_nvlt_36","text":"又辭祿賦曰：荷賞延之渥恩，在弱齡而覃惠，蒙聖達之眷顧，得乘閒以沉泄，雖鑣羁之有名，恒遊奖而匪滯，解龟紐於城邑，反褐衣於丘窟，判人事於一朝，與世物乎長絕，自牵缀於朱絲，奄二九於斯年，服纓佩於兩宮，執鞭笏於宰蕃。","sortOrder":82},
  {"id":"s_work_nvlt_36_83","chapterId":"ch_work_nvlt_36","text":"梁簡文帝玄虛公子賦曰：有玄虛之公子，輕滅喧俗，保此大愚，居榮利而不染，豈聲色而能拘，回還四始，出入三墳，心溶溶於玄境，意飄飄於白雲，追寂圃而逍遙，任文林而佚宕，忘情於物我之表，縱志於有無之上，不為山而自高，不為海而弥廣。","sortOrder":83},
  {"id":"s_work_nvlt_36_84","chapterId":"ch_work_nvlt_36","text":"梁陆倕思田賦曰：歲聿忽其雲暮，庭草飒以萎黃，風飗飗以吹隙，燈黯黯而無光，獨展轉而不寐，何增叹而自傷，於是踟蹰徙倚，顧景興懷，魂茕茕以至曙，缀予想於田萊，彼五畝其焉在，乃爰洎乎江隈，出郭門而東鶩，入溆浦而南回，爾乃觀其水陆物產，原隰形便，林藪挺直，丘陵帶面，臨九曲之回江，對千里之平甸，風去蘋其已开，日登桑而先見，聽啁哳之寒雞，弄差池之春燕，臨場圃以筑馆，對櫺軒而凿池，集遊泳於階下，引朝派於堂垂，瞻巨石之前却，玩激水之推移，雜青莎之靃靡，拂細柳之長枝，感風燭與石火，嗟民生其如寄，苟有焜而無心，必行難而言易，幸少私而寡欲，兼絕仁以弃智，忽學步而學趾。又追飛而厲翅，瞻鹿囿而竊高，仰疆台而慕義，歷四時於遊水，馳三稔於申臂，望歸流而載懷，情鬱悒其何寘。","sortOrder":84},
  {"id":"s_work_nvlt_36_85","chapterId":"ch_work_nvlt_36","text":"宋陶潛歸去來曰：歸去來兮，田園將芜胡不歸，既自以心為形役，奚惆怅而獨悲，悟已往之不諫，知來者之可追，寔迷途其未遠，覺今是而昨非，舟遙遙而輕颺，風飄飄而吹衣，乃瞻衡宇，載欣載奔，僮仆歡迎，稚子候門，三径就荒。松菊猶存，携幼入室，有酒盈樽引壶觴以自酌，眄庭柯以怡顏，倚南窗以寄傲，審容膝之易安，策扶老以流憩，時矯首以遐觀，雲無心而出岫，鳥倦飛而知還，農人告餘以春將及，有事乎西畴，或命巾車，或棹孤舟，既窈窕而尋壑，亦崎嶇而經丘，木欣欣以向榮，泉涓涓而始流，善萬物之得所，感吾年之行休，已矣乎，寓形宇內，复得幾時，曷不委心任去留，胡為乎遑遑欲何之，富貴非吾原，帝乡不可期，懷良辰以孤往，或植杖而耘耔，登東皋以舒嘯，臨清流而賦詩，聊乘化以歸盡，樂夫天命复奚疑。","sortOrder":85},
  {"id":"s_work_nvlt_36_86","chapterId":"ch_work_nvlt_36","text":"梁沈約八詠守山東曰：守山東，山東萬嶺鬱青葱，兩谿共一泻，水絜望如空，岸侧青莎被，巖間丹桂丛，上瞻既隱軫，下睇亦冥蒙，遠林响咆獸，近树聒鳴虫，路出若溪［原訛然，據冯校本改。］右，涧吐金華東，萬仞倒危石，百丈註懸潀，掣曳寫流電，奔飛似白虹，洞井含清氣，漏穴吐飛風，玉窦膏滴瀝，石室乳空籠，餘平生之所愛，欻暮年而此逢，欲一去而不還，恨邦君之未禘，秩滿撫白雲，淹留事芝髓。","sortOrder":86},
  {"id":"s_work_nvlt_36_87","chapterId":"ch_work_nvlt_36","text":"【頌】晉潘嶽許由頌曰：邈哉許公，執真履貞，辭尧天下，抱朴隱形，川停嶽峙，澹泊無營，栖遲高山，與世靡爭，虛薄忝任，來宰斯城，愧無惠化，豹產之政，峨峨治所，樂慕景名，登基逍遙，來過暮庭，通於時憲，頃匡不盈，恨無旨酒，奠公之靈，死而不朽，公有其榮，聊述雅美，扬公馨聲。","sortOrder":87},
  {"id":"s_work_nvlt_36_88","chapterId":"ch_work_nvlt_36","text":"晉孫綽聘士徐君墓頌曰：晉南昌相太原縣君，白漢故聘士徐君之靈，惟君風軌英邃，德音徽遠，播餐仰芳，流宗播揖，在昔古人有言，聞伯夷之風者，懦夫有立志，仰先生之道，豈無青雲之懷哉，餘以不才，忝宰茲邑，遐宗有道，思揖遠風，乃與友人殷浩等，束帶靈墳，奉瞻祠宇，雖玉质幽潛，而目想令儀，雅音永寂，而心存高范，徘徊墟垅，仰眄松林，哀有形之短，［全晉文六十一短下有化字。］悼令德之長泯，怃然有感，凄焉增傷，夫諷謠生於情讬，雅頌興乎所钦，匪於詠述，孰寄斯懷，頌曰：巖巖先生，邁此英風，含真獨畅，心夷體冲，高蹈域表，淑問顯融，昂昂五賢，赫赫八俊，雖曰休明，或婴险吝，豈若先生，保茲玉润，超世作范，流光遐振，墳塋壘落，松竹萧森，薈丛蔚蔚，虛宇愔愔，遊獸戲阿，嘤鳥鳴林，嗟乎徐君，不聞其音，徘徊丘侧，凄焉流襟，何以舒蘊，援翰讬心。","sortOrder":88},
  {"id":"s_work_nvlt_36_89","chapterId":"ch_work_nvlt_36","text":"隋江總莊周畫頌曰：玉絜蒙縣，蘭薰漆園，丹青可久，雅道斯存，夢中化蝶，水外翔鯤，出俗靈府，師心妙門，垂竿自若，重聘忘言，悠哉天地，共是籠樊。","sortOrder":89},
  {"id":"s_work_nvlt_36_90","chapterId":"ch_work_nvlt_36","text":"【贊】後漢蔡邕焦君贊曰：猗欤焦君，常此玄墨，衡門之下，栖遲偃息，泌之洋洋，樂以忘食，鶴鳴九皋，音亮帝侧，乃徵乃用，將受袞職，昊天不弔，賢人遘慝，不惟一志，併此四國，如何穹蒼，不詔斯或，惜哉朝廷，丧茲舊德，恨以學士，將何法則。","sortOrder":90},
  {"id":"s_work_nvlt_36_91","chapterId":"ch_work_nvlt_36","text":"魏陳王曹植許由巢父池主贊曰：尧禪許由，巢父是恥，秽其圂聽，臨河洗耳，池主是讓，以水為濁，嗟此三士，清足厲俗。","sortOrder":91},
  {"id":"s_work_nvlt_36_92","chapterId":"ch_work_nvlt_36","text":"又卞隨贊曰：湯將伐桀，謀於卞子，既克讓位，隨以為恥，薄於殷世，著自汙己，自投潁水，清風邈矣。","sortOrder":92},
  {"id":"s_work_nvlt_36_93","chapterId":"ch_work_nvlt_36","text":"又南山四皓贊曰：嗟爾四皓，避秦隱形，劉項之爭，養志弗營，不應朝聘，保節全貞，應命太子，漢嗣以寧。","sortOrder":93},
  {"id":"s_work_nvlt_36_94","chapterId":"ch_work_nvlt_36","text":"晉夏侯湛范蠡贊曰：悠悠范子，求仁在己，進報危國，退弘妙理，身與勋偕，名與身否，逸群遠遊，永齊終始。","sortOrder":94},
  {"id":"s_work_nvlt_36_95","chapterId":"ch_work_nvlt_36","text":"又魯仲連贊曰：峨峨先生，有邈其節，流仁忧亂，抗道自絜，隨事抑扬，與時开閉，在幽能泰，處悶惟悅。","sortOrder":95},
  {"id":"s_work_nvlt_36_96","chapterId":"ch_work_nvlt_36","text":"又莊周贊曰：邁邁莊周，騰世獨遊，遁時放言，齊物絕尤，垂釣一壑，取戒犧牛，望風寄心，讬志清流。","sortOrder":96},
  {"id":"s_work_nvlt_36_97","chapterId":"ch_work_nvlt_36","text":"晉孫楚莊周贊曰：莊周曠荡，高才英俊，本道根貞，歸於大順，妻之不哭，亦何所懽，慢弔鼓缶，放此誕言，殆矯其情，近失自然。","sortOrder":97},
  {"id":"s_work_nvlt_36_98","chapterId":"ch_work_nvlt_36","text":"又榮啟期贊曰：榮公溫雅，既怡既怿，濁以徐清，寂然澹泊，援琴自娱，詠此三樂，眉寿無疆，惟德之宅。","sortOrder":98},
  {"id":"s_work_nvlt_36_99","chapterId":"ch_work_nvlt_36","text":"又原壤贊曰：壤之辀張，絕滅禮教，實交仲尼，同機合奧，聖以之臧，俗以之笑，獨协區外，孰知其妙。","sortOrder":99},
  {"id":"s_work_nvlt_36_100","chapterId":"ch_work_nvlt_36","text":"晉左九嫔巢父惠施贊曰：泱泱長流，沔沔清波，思文巢惠，載詠載歌，垂纶一壑，萬象匪多，神乎畅矣，緬同基阿。","sortOrder":100},
  {"id":"s_work_nvlt_36_101","chapterId":"ch_work_nvlt_36","text":"晉庾闡孫登贊曰：靈巖霞蔚，石室鱗構，青松標空，蘭泉吐漏，籠薈可遊，芳津可漱，玄穀萧寥，鳴琴獨奏，先生體之，寂坐幽岸，凝冰結朴，熙陽靡煥，潛真內全，飛榮外散，凌崖高嘯，希風朗彈，道有冥废，運有昏消，達隱不巖，玄跡不標，或曰先生，晦德逍遙，嵇子秀達，英風朗烈，道俊薰芳，鮮不玉折，兆動初萌，妙鑒奇絕，翘首丘冥，仰想玄哲。","sortOrder":101},
  {"id":"s_work_nvlt_36_102","chapterId":"ch_work_nvlt_36","text":"晉戴逵閒遊贊曰：昔神人在上，辅其天理，知溟海之禽，不以籠樊服養，櫟散之质，不以斧斤致用，故能树之於廣漢，栖之於江湖，載之以大猷，覆之以玄風，使夫淳朴之心，靜一之性，鹹得就山泽，樂閒曠，自此而箕嶺之下，始有閒遊之人焉，降及黃綺，逮於台尚，莫不有以保其太和，肆其天真者也，且夫巖嶺高則雲霞之氣鮮，林藪深則萧瑟之音清，其可以藻玄瑩素，疪其皓然者，舍是焉，故雖援世之彦，翼教之杰，放舞雩以發詠，聞乘桴而懍厲，况乎道乖方內，體絕風尘，理揖長謝，歌鳳逡巡，荡八疵於玄流，澄雲崖而颐神者哉，然如山林之客，非徒逃人患，避爭門，谅所以翼順資和，涤除機心，容養淳淑，而自適者爾，凡物莫不以適為得，以足為至，彼閒遊者，奚往而不適，奚待而不足，故荫映巖流之际，偃息琴書之侧，寄心松竹，取樂魚鳥，則澹泊之原，於是畢矣，然奇趣難均，玄契罕遇，終古皆孤栖於一巖，獨玩於一流，苟有情而未忘，有感而無對，則缀斤寢絃之叹，固已幽結於林中，骤感於遐心，為日久矣，我故遂求方外之美，略舉養和之具，為雜贊八首，畅其所讬，始欣閒遊之遐逸，終感嘉契之難會，以廣一往之詠，以抒幽人之心雲爾，茫茫草昧，綿邈玄世，三極未鼓，天人無际，萬器既判，靈朴乃翳，寔有神宰，忘懷司契，冥外傍通，潛感莫滯，總順巢，兼應夷惠，緬矣遐心，超哉絕步，顧揖百王，仰怡泰素，矜其天真，外其嚣務，詳觀群品，馳神萬慮，誰能高佚，悠然一悟。","sortOrder":102},
  {"id":"s_work_nvlt_36_103","chapterId":"ch_work_nvlt_36","text":"又尚長贊曰：尚叟冲順，庸行昏世，和龍婉約，玄識罔滯，瞻彼崇高，俄為尘翳，亦有同好，潛莊宿契，超超增翥，眇眇偕逝，跡絕青崖，影滅雲际。","sortOrder":103},
  {"id":"s_work_nvlt_36_104","chapterId":"ch_work_nvlt_36","text":"晉庾亮翟徵君贊曰：夫所謂至人者，體包杰量，神凝域表，該落萬動，玄心獨融，故能虬驤慶霄，而不绁豢龍之辔，鳳鳴瑤林，而不屈伶倫之籠，豈必欣太清而樂琼藹哉，顧蹄涔不足以濯神須，翳薈不足以翔雲翮，是故藐姑有綽約之庐，箕阜有高嘯之宇，唐勋表於玄庭，夏功忘於虛室，晉徵士南陽翟君，禀逸韻於天陶，含冲氣於特秀，體虛任而委順，恢昭曠而高蹈，先生載營抱一，泊然獨處，神栖飆藹之表，形逸巖泽之隅，雖束帛仍降，轺冕屢招，而弓旌屈於匪石，帝命慚於虛复矣，是以高風振宇宙遠詠冠當時，方將表大庭於絕代，恢玄解以釋紛，仰朝霞而晞翼，陵扶搖以獨翔，景命不延，卒於尋陽之南山，哲人其萎，高軌孰仿，餘钦若人之風，常問道於無何之庐，賓想玄珠，主以瞻授，沐道霑淳，固以實而歸矣，自昔之违，於茲七稔，何悟先生，忽焉升遐，感至德之長泯，悼仁風之永翳，標爾其傷，潸然增欷，乃援翰詠跡，以宣來葉，其辭曰：卓哉先生，逸韻遐超，虬盤玉津，鳳戢琼條，涤耳夏鼎，高揖唐朝，洪崖邈矣，玄跡載劭，淳風沐世，飛芳九霄。","sortOrder":104},
  {"id":"s_work_nvlt_36_105","chapterId":"ch_work_nvlt_36","text":"晉方湛［全晉文一百四十作湛方生。此有訛倒。］北叟贊曰：樂為忧根，禍為福始，數極則旋，往复迭起，世人迷之，橫生欣恥，滔滔北叟，獨亮真理，丧馬弗希，折肱愈喜，淡哉一生，無泰無否。","sortOrder":105},
  {"id":"s_work_nvlt_36_106","chapterId":"ch_work_nvlt_36","text":"宋陶潛張長公贊曰：達哉長公，萧然何事，世路皆同，而我獨異，斂辔朅來，閒養其志，寢跡窮年，誰知斯意。","sortOrder":106},
  {"id":"s_work_nvlt_36_107","chapterId":"ch_work_nvlt_36","text":"又周妙珪贊曰：美哉周子，稱疾閒居，寄心清商，恬然自娱，翳翳衡門，洋洋泌流，日玩群書，顧眄寡畴，飲河既足，自外皆休，緬懷千載，讬契孤遊。","sortOrder":107},
  {"id":"s_work_nvlt_36_108","chapterId":"ch_work_nvlt_36","text":"又魯二儒贊曰：易大隨時，迷变則愚，芬芬若人，特為貞夫，德不百年，汙我詩書，逝焉不顧，被褐幽居。","sortOrder":108},
  {"id":"s_work_nvlt_36_109","chapterId":"ch_work_nvlt_36","text":"又夷齊贊曰：二子讓國，相隨海隅，天人革命，絕景窮居，采薇高歌，慨想黃虞，貞風凌俗，爰感懦夫。","sortOrder":109},
  {"id":"s_work_nvlt_36_110","chapterId":"ch_work_nvlt_36","text":"又尚長禽慶贊曰：尚子昔薄宦，妻孥共早晚，貧賤與富貴，讀易悟益損，禽生善周遊，周遊日已遠，去矣尋名山，上山豈知反。","sortOrder":110},
  {"id":"s_work_nvlt_36_111","chapterId":"ch_work_nvlt_36","text":"宋范泰張長公贊曰：長公秉心，獨逸世表，量物難同，審己弥了，情雖高邃，跡無抗矯，靡當夷惠，孰識多少。","sortOrder":111},
  {"id":"s_work_nvlt_36_112","chapterId":"ch_work_nvlt_36","text":"又高鳳贊曰：遐哉玄古，邈矣皇羲，自茲已降，顯默參差，智為世駭，才為物奇，跡出無泯，潛躍俱馳，暧暧若人，孰测其為，戢曜幽壑，采真重崖，冲情莫亮，汙跡示疵，輕俗無际，肆志莫羁。","sortOrder":112},
  {"id":"s_work_nvlt_36_113","chapterId":"ch_work_nvlt_36","text":"又吳季子札贊曰：延州高遠，弃國帥誠，優遊大邑，觀風上京，仁懷邦壤，道畅聖明，鑒彻昔代，樂察未形，嬴博遠死，解劍在生，夫子戾止，爰詔作名。","sortOrder":113},
  {"id":"s_work_nvlt_36_114","chapterId":"ch_work_nvlt_36","text":"齊王俭竟陵王山居贊曰：升堂踐室，金暉玉朗，亹亹大韶，遙遙閒賞，道以德弘，聲由業廣，義重實歸，情深虛往，濠梁在茲，安事遐想。","sortOrder":114},
  {"id":"s_work_nvlt_36_115","chapterId":"ch_work_nvlt_36","text":"梁沈約高士贊曰：餘之所謂高士者，悠悠皆是，請试言之，聖人莅天下，則賢人贊務，益皋陶是也，自中智以下，莫有不學以從政佐國安民者也，易曰：聖人之大寶曰位，非學則不得也，學所以行其志，孝悌慈仁信義是也，雖誦先王之典謨，而不行其志，聖人之大寶，亦不可得也，要須學行兼有，然後取之，悠悠之徒，莫不攘袂而議進取，怒目而爭權利，悅愚謟闇，苟得忘廉，若斯人者，豈入國士之涂，動衣冠之眄，藉此而登高位，未或有也，贊曰：亦有哲人，獨執高志，避世避言，不友不事，恥從汙祿，靡惑守餌，心安藜藿，口絕炮胾，取足落毛，寧懷組織，如金在沙，顯然自異，猶玉在泥，涅而不緇，身標遠跡，名重前記，有美高尚，處知若無，劣哉群品，事靜心驅，苟能立志，爭此疋夫，進忘陨獲，退守恬愉，曰仁與義，其径不迂，為之則至，非物所拘，宦成名立，陟彼高衢。","sortOrder":115},
  {"id":"s_work_nvlt_36_116","chapterId":"ch_work_nvlt_36","text":"又銷聲贊曰：寂矣栖魂，非海非樊，若人焉往，斯理空存，天標已暧，絕羽孤騫，尧逢豈讓，札值奚言。","sortOrder":116},
  {"id":"s_work_nvlt_36_117","chapterId":"ch_work_nvlt_36","text":"周庾信五月披裘負薪畫贊曰：披裘當夏，俗外為心，雖逢季子，不拾遺金，禽巢欲遠，魚穴惟深，消聲滅跡，何必山林。","sortOrder":117},
  {"id":"s_work_nvlt_36_118","chapterId":"ch_work_nvlt_36","text":"又張良遇黃石公畫贊，張良取履，跪授無辭，兵書一卷，長者之期，昔稱韓相，今為漢師，穀城餘石，還歸舊祠。","sortOrder":118},
  {"id":"s_work_nvlt_36_119","chapterId":"ch_work_nvlt_36","text":"又榮啟期三樂畫贊曰：榮期三樂，惟人與年，夫子相遇，即以為賢，性靈造化，風雲自然，雅音雖古，獨有鳴絃。","sortOrder":119},
  {"id":"s_work_nvlt_36_120","chapterId":"ch_work_nvlt_36","text":"【箴】晉庾凯幽人箴曰：有物混成，先天地生，乃剖乃判，二儀既分，高卑以陳，貴賤攸位，榮辱相換，乾道尚謙，人神同符，危由忽安，溢緣釋虛，苟識妙膏，厥美有腴，韓信耽齊，殒首鍾室，子房辭留，高跡卓逸，貴不足榮，利不足希，華繁則零，樂極則悲，歸數明白，势豈容违，人徒知所以進，而忘所以退，穰侯安寵，襄公失愛，始乘夷道，終婴其類，羲和升而就翳，望舒滿而就虧，盈挹之分，自然之規，悠悠庶人，如何弗疑，幽人守虛，仰鑽玄遠，敢草斯箴，敬咨黻冕。","sortOrder":120},
  {"id":"s_work_nvlt_36_121","chapterId":"ch_work_nvlt_36","text":"晉江逌逸民箴曰：至人應務，是統是營，乃製上下，以牧群生，君位孰在，匪聖伊明，賢愚相奉，臣主以成，如彼百節，各役天形，率分委质，仰應一情，心膂有位，股肱有經，豈以處下，為戚為榮，各安其所，舉體用平，夫設爵列土，懸弓垂旌，卑尊之級，貴賤之名，匪以恣物之欲，寔大猷而是經，處遁之士，奚眷於時，行矣先覺，捐俗長辭，明乎忧患，故超爾不疑，解發靈崖，被褐絃絲，飄飄台上，輕舉高之，穆穆二仲，携策相期，盤幽隱寂，與物無治，凡厥後來，順乃所往，鑒茲俗累，戒於顛荡，無殉外物，心煩披養，無弃恬曠，忧勤是掌，林人司箴，敢進善党。","sortOrder":121},
  {"id":"s_work_nvlt_36_122","chapterId":"ch_work_nvlt_36","text":"【志】梁陶隱居尋山志曰：倦世情之易繞，乃杖策而尋山，既沿幽以達峻，窮實阻而備艱，眇來心其未已，方际夕乎雲根，欣夫得志者忘形，遺形者神存，於是散發解帶，盤旋巖上，心容曠朗，氣宇條畅，玄雖遠其必存，累無大而必忘，害馬之弊既去，解牛之刀乃王，荆門晝掩，蓬戶夜开，室迷夏草，径惑春苔，庭虛月映，琴响風哀，夕鳥依簷，暮獸爭來，時复歷近垄，尋遠峦，坐盤石，望平原，日負障以共隱，月披雲而出山，風下松而含曲，泉萦石而生文，草靃靃以拂露，尘飒飒而來群，扪虛萝以入穀，傍洪潭而比清，照石壁以端色，攀桂枝而齊貞，函扈蘭而佩蕙，及春窸之未鳴，且含懷以屏氣，待惠風而舒情，遂乃陵巖峭，至松門，背通林，面長源，右聯山而無际，左凭海而齊天，草泫泫以垂露，柳依依而近蝉，鳥双双以赴水，鷺軒軒而歸田。","sortOrder":122},
  {"id":"s_work_nvlt_36_123","chapterId":"ch_work_nvlt_36","text":"梁劉孝標山栖志曰：夫鳥居山上，曾巢木末，魚潛川下，窟穴沙泥，豈好異哉，蓋性然也，故有忽白璧而樂垂纶，負玉鼎而要卿相，行藏紛糾，顯晦踳駮，無異火炎水流，圓動方息，斯則廟堂之與江海，蓬戶之與金阖，併然其所然，悅其所悅，餘每思濯清瀨，息椒丘，寤寐永懷，其來尚矣，所居東陽郡金華山，山川秀麗，皋泽坱鬱，若其群峰叠起，接漢連霞，乔林布濩，春青冬绿，回溪映流，則千仞洞底，膚［原訛庸，據冯校本改。］寸雲合，必千里雨散，所住三面，山皆周繞，有象郛郭，南則平野萧條，極目通望，東西帶二涧，則四時飛流泉，澜清微澍，滴瀝生响，白波跳沫，汹涌成音，楓楮椅櫪之树，梓柏桂樟之木，分形異色，千族萬种，結朱實，苞绿里，搖白蒂，抽紫茎，橚矗苯矗，梢風鳴籁，垂柯簷戶，布葉房栊，中穀涧濱，華葩攒列，至於青春受謝，萍生泉動，則都梁含馥，懷香送芬，長樂負霜，宜男泫露，芙蕖紅菙，照水皋蘇，縹葉從風，凭軒永眺，蠲忧忘疾，歲始年季，農隙時閒，濁醪初濟，縹清新［據廣弘明集二十四新字下有熟字。］則有田家野老，提壶共至，班荆林下，陳樽置爵，酒酣耳熱，屢舞嚾呶，盛論箱庾，高談穀稼，不求於世，不迕萬物，莫辨榮辱，匪知毀譽，浩荡天地之間，心無怵惕之警。","sortOrder":123},
  {"id":"s_work_nvlt_36_124","chapterId":"ch_work_nvlt_36","text":"【訓】魏繁钦祿里先生訓曰：處則抗區外之志，出則規非常之功，寔哲士之高趣，雅人之遠圖，故呂尚垂翼北海，以待鷹扬之任，黃綺削跡南山，以集神器之贊。","sortOrder":124},
  {"id":"s_work_nvlt_36_125","chapterId":"ch_work_nvlt_36","text":"【譏】魏麋元譏許由曰：潛居默靜，隱於箕山，身在布衣，而輕天下，世人歸其高行，學者以為美談，夫际會之間，矯時所譽，至乃抽簪散發，背時逆命，隱於山林之中，以此自高，非以勸智能之士，入通遠之教，故譏而责之曰：太上貴德，其次立功，世殊時異，不得而同，故伯禹過門而不入，稷契刻節而奋庸，股肱帝室，作民王公，今子生聖明之世，得觀雍熙之法，則當摅不朽之功，畅不羁之志，龍飛鳳起，修攝君司，佐天理物，幹成王事，若子以尧為闇主，則歷代載其功，以民為貪亂，則比屋可封，若夫世濁時昏，上無賢君，忠臣不出，小人聚群，即當拨煩理亂，跨騰風雲，光顯時主，拔濟生民，何得偃蹇，藏影蔽身，夫道不虛行，士不徒生，生則幹時，為國之楨，故伊尹幹湯，周公相成，興治濟世，以致太平，生有顯功，没有美名，人生於世，貴能立功，何得逃位，矯世絕蹤，丹朱不肖，朝有四凶，尧放求賢，遜位於子，度才處分，不能則已，何所感激，臨河洗耳，山居巢處，執心不傾，辭君之祿，忘君之榮，居君之地，避君之庭，立身若此，非子之貞，欲言子智，則不仕聖君，欲言子高，則鳥獸同群，無功可紀，無事可論。","sortOrder":125},
  {"id":"s_work_nvlt_36_126","chapterId":"ch_work_nvlt_36","text":"【銘】晉慮［按當作盧。］播阮籍銘曰：峨峨先生，天挺無欲，玄虛恬澹，混齊榮辱，荡涤秽累，婆娑止足，胎胞造化，韜光缊韣，鼓棹沧浪，彈冠峤嶽，颐神太素，簡曠世局，澄之不清，溷之不濁，翱翔區外，遺物度俗，隱處臣室，友真歸朴，汪汪川原，邁跡圖箓。","sortOrder":126},
  {"id":"s_work_nvlt_36_127","chapterId":"ch_work_nvlt_36","text":"《藝文類聚》　唐·欧陽詢","sortOrder":127},
  {"id":"s_work_nvlt_37_1","chapterId":"ch_work_nvlt_37","text":"卷三十七人部二十一","sortOrder":1},
  {"id":"s_work_nvlt_37_2","chapterId":"ch_work_nvlt_37","text":"○隱逸下","sortOrder":2},
  {"id":"s_work_nvlt_37_3","chapterId":"ch_work_nvlt_37","text":"◇隱逸下","sortOrder":3},
  {"id":"s_work_nvlt_37_4","chapterId":"ch_work_nvlt_37","text":"【碑】後漢胡廣徵士法高卿碑曰：言滿天下，發成篇章，行充宇宙，動為儀表，四海英儒，履義君子，企望來臻者，不可勝紀也，翻然鳳舉，匿燿遠遯，名不可得而聞，身難可得而睹，為尧舜所知，不飲洗耳之水，超越青雲之上，德逾巢許之右，所謂逃名而名我隨，避聲而聲我追者已，揆君分量，輕寵傲俗，乃百世之師也，其辭曰：邈玄德，膺懿資，弘聖典，研道機，彪童蒙，作世師，辭皇命，確不移，亚鸿崖，超由夷，垂英聲，扬景暉。","sortOrder":4},
  {"id":"s_work_nvlt_37_5","chapterId":"ch_work_nvlt_37","text":"後漢蔡邕伯夷叔齊碑曰：惟君之质，體清良兮，昔佐殷姬，忠孝彰兮，委國損爵，諫國匡兮，譏武伐紂，欲喻匡兮，時不可救，歷運蒼兮，追念先侯，受命皇兮，忧懷感兮，雖没不朽，名兮芳兮。","sortOrder":5},
  {"id":"s_work_nvlt_37_6","chapterId":"ch_work_nvlt_37","text":"又郭泰碑曰：先生誕膺天衷，聰睿明哲，孝友溫恭，仁慈惠敏，夫其器量弘深，姿度廣大，浩浩焉，汪汪焉，奧乎不可测已，於時纓緌之徒，紳佩之士，望形表而景附，聆嘉聲而响臻者，猶百川之歸巨海，鱗介之宗龟龍也，方將蹈鸿崖之遐跡，紹巢許之絕軌，翔區外以舒翼，超天衢以高峙，銘曰：懿乎其純，確乎其操，洋洋縉紳，言觀其高，栖遲秘丘，善誘能教，恭恭［本集作赫赫。］三事，幾何其招，委辭名員，［本集作召貢。］保此清妙。","sortOrder":6},
  {"id":"s_work_nvlt_37_7","chapterId":"ch_work_nvlt_37","text":"又玄文先生李休碑曰：休少以好學，遊心典謨，既綜七經。又精群緯，絇深極奧，窮覽聖旨，居則玩其辭，動則玩其变，雲物不顯，必考其占，故能獨見前識，以先神意，若古今常難，疑議错谬，前人所希論，後學所不覺，休盡剖判，處約不戚，聞寵不欣，榮不能華，威不能震，有惠雲載，惟邦之珍，按典考論，號曰玄文。","sortOrder":7},
  {"id":"s_work_nvlt_37_8","chapterId":"ch_work_nvlt_37","text":"又處士圈典碑曰：天真淑性，精微周密，包括道要，致思無形，臨殁顧命曰：知我者蔡邕，乃為銘曰：載書休美，俾來崑裔，永有諷誦，以知先生之德，混其若濁，徐然後清，綽其若煥，終其益貞。","sortOrder":8},
  {"id":"s_work_nvlt_37_9","chapterId":"ch_work_nvlt_37","text":"又翟先生碑曰：世以仁義為质，學問為業，爰暨先生，固天縱德，應運立言，繼期五百，實行形於州里，明哲與聖合契，該通五經，洗洞墳籍，為萬里之場圃，九隩之林泽，挹之若江湖，仰之若華光，玄玄焉测之則無源，汪汪焉酌之則不竭，可謂生民之英者已，國失元傅，學失表式，凡百搢紳，哀矣泣血，人百其身，匪雲來复，於是乡党乃相與登山伐石而勒銘曰：邈矣先生，厥德孔真，腹心弘道，深高入神，王錫三命，觀國之賓，其树富貴，忽若浮雲，既不降志，亦不辱身。","sortOrder":9},
  {"id":"s_work_nvlt_37_10","chapterId":"ch_work_nvlt_37","text":"魏劉楨處士國文甫碑曰：先生執乾靈之貞資，禀神祇之正性，咳笑則孝悌之端著，匍匐則清節之兆見，龆龀以及成人，體無懈容，口無愆辭，兢兢業業，小心思忌，勤讓同儔，敬事長老，雖周之樂正子春，漢之江都董相，其飭躬力行，無以尚之，是以長安師其仁，朋友钦其義，閨門推其慈，宗屬懷其惠，既乃潛身窮巖，遊心載籍，薄世名也，初海內之亂，不视膳羞，十有餘年，忧思泣血，不勝其哀，形銷氣竭，以建安十七年四月卒，於時龍德逸民，黃發實叟，缀文通儒，有方彦士，莫不拊心長號，如丧同生，鹹以為诔所以昭行也，銘所以旌德也，古之君子，既没而令問不亡者，由斯二者也，銘曰：懿矣先生，天授德度，外清內白，如玉之素，逍遙九皋，方回是慕，不計治萃，名與殊路，知我者希，韞櫝未酤，丧過乎哀，遘疾不悟，早世永頹，违此榮祚，咨爾末徒，聿修叹故。","sortOrder":10},
  {"id":"s_work_nvlt_37_11","chapterId":"ch_work_nvlt_37","text":"齊孔稚珪褚先生百玉碑曰：夫河洛摛寶，神道之功傳，華［華下有脱字。］吐秘，仙靈之跡可睹，蓋事詳於玉牒，理煥於金符，雖冥默難源，顯晦異軌，测心觀古，可得而言焉，是以子晉笙歌，馭鳳於天海，王乔雲舉，控鶴於玄都，亦有羽化蜕蝉，觸影遁形，神翥帝宮，跡留劍杖，遊瑤池而不返，宴玄圃以忘歸，永嘉惡道者，窮地之险也，欹窦遏日，折石橫波，飛浪突雲，奔湍急箭，先生攀途跻阻，宿枻涉圻，而衡飆夜鼓，山洪暴激，忽乃崩舟墜壑，一倒千仞，飄地淪篙，翻透無底，徒侣判其冰碎，舟子悲其雹散，危魂中夜，赴阻相尋，方見先生，恬然安席，銘曰：關西升妙，洛右飛英，鳳吹金闕，箫歌玉京，絕封萬古，乃既先生，先生浩浩，唯神其道，泉石依情，煙霞入抱，秘影窮岫，孤栖幽草，心圖上玄，志通大造。","sortOrder":11},
  {"id":"s_work_nvlt_37_12","chapterId":"ch_work_nvlt_37","text":"梁元帝隱居先生陶弘景碑曰：昔大和中，有許遠遊者，乃雲霄之勝賓，大虛之選客，先生規同矩合，實踵高步，曩基先構，即駕胥宇，千尋危耸，凭牖以望奔星，百拱高懸，倚櫺而觀朝日，飛流界道，似天漢之橫波，觸石起雲，若奇峰之出岫，銘曰：肇彼冥默，翻成协贊，身讬外臣，心同有亂，重道遵德，爰積叡衷，顧懷汾射，玺問遙通，朱楊鬱起，華構方崇，靜台冠月，經榭迎風，嶕峣高棟，育霭脩栊，極望山川，周觀京陆，碧嶂千嶺，清流萬穀，景落重崖，煙生岫複。","sortOrder":12},
  {"id":"s_work_nvlt_37_13","chapterId":"ch_work_nvlt_37","text":"梁劭陵王萧纶貞白先生陶弘景碑曰：夫夜光結绿，非胠箧之恒珍，逸羽翔鱗，豈園池之近玩，寧期心於遠大，蓋不知其所以然也，道風與星漢同高，勝氣與煙霞共遠，深壑危峭，組織煙霞，枕石漱流，山禽無桡，采藥耦耕，野獸不亂，朗猶懸鏡，鬱似貞筠。","sortOrder":13},
  {"id":"s_work_nvlt_37_14","chapterId":"ch_work_nvlt_37","text":"梁裴子野劉虬碑曰：受川嶽之英靈，有清明之淑性，淡乎若深泉之靜，皜乎若寒霜之絜，千仞不足議其高，萬頃不足畴其量，在其幼也，孝敬淳深，貫乎幽顯，庐乎墓所，而暴獸去之，墟里賴焉，樵蘇無犯，及其長也，捧檄動容，薄遊下邑，甘露零於丰草，蒲密致於時雍，有以見賢人之行，動天地，感鬼神，明疾乎影响，如斯之者美矣，夫聲名籍甚，群公侧席，凿室林皋，面流傍隴，咫尺荆衡，表里巫夢，树蕙滋蘭，芜没庭戶，平畴翠潋，千里極目，信物外之神區，幽居之勝境，昔許子將謂太丘道廣，廣則不周，仲舉性峻，峻則少納，峻而納，廣而周，君於二陳，折其中矣，其所修孔氏之學，則儒者師之，所明釋氏之教，則净行傳之，所著文集，則辭人錄之，銘曰：滔滔江漢，實紀南國，篤生居士，高明柔克，瓘瓘其道，巍巍其德，曰仁曰義，惟民惟則，筑室皋壤，考槃郛郭，坐臥山樊，嘯歌林薄，親致甘旨，躬餐上藥，優哉遊哉，且以行樂，九丘八索，百家群史，西河疑聖，華陰成市，悠哉荆夢，逖矣江濆，辎軿結轍，羔雁成群，監觀令范，式如金玉，君子徽猷，誰其與屬，畴咨故老，遵扬實錄。","sortOrder":14},
  {"id":"s_work_nvlt_37_15","chapterId":"ch_work_nvlt_37","text":"【墓志】梁簡文帝徵君何先生墓志曰：先生履玉燭之禎氣，應大賢之一期，實生而知機，撫尘斯庶，敬非習起，孝乃因心，聚徒教習，學侣成群，與沛國劉瓛汝南周顒為友，陆璉贺玚之徒，更道北面，永明中，王文憲俭，受詔撰禮，未竟而卒，屬在司徒文宣王，王以讓先生，因廣加刊緝，故以含文燕居，說六典五恩之義，或齊侯所不镇，孟嘉所未知，皆折茲大物，成此良教，小人道長，每諷考槃之詩，君子道消，便執天山之筮，乃毀車掛冠，拂衣東嶺，始居若耶，來從秦望，今上經纶天地，權舆鼎業，始徵為軍謀祭酒，實允文若之舉，且光彦先之選。又徵特進右光祿大夫，高尚其事，確乎不拔，玄纁徒往，束帛虛歸，而給白衣尚書祿，固辭不受，卒窆乎其山，正衾在殯，嗤鏤器與玉衣，尧典入棺，恥密章及書綬，知與不知，併懷惋怆，鹹以人亡素楷，禮墜文章，洙泗頹經，扶風罢學，關西疑聖之德，自此長淪，高松引風之氣，於茲永息，餘昔在殊方，亟枉翰跡，钦風味道，迄淹歲時，既而位阻桂宮，涂乖咫尺，不獲擁經步至，問春卿之痾，徐輪三反，入杜夷之舍，痛祥雲之滅采，悲列曜之晞暉，追勒高乡，乃為銘曰：文范高世，玄晏絕倫，复有令德，遠之與均，誰與均此，呜呼哲人，第五肥遁，餘軌尚遵，司空开學，其風不泯，傳茲孝敬，曰悌且仁，氣高琼嶽，心虛穀神，括羽儒囿，舟舆席珍，既遊慧水，兼引法輪，談扇猶在，鳴琴尚陳，如何不慭，德素長淪，寂寥巖穴，荒涼渭濱，桥曰只雞，徐稱酹素，餘钦夫子，風期夙著，蓄思含毫，傳芳寫譽，沉楚雖貞，玄泉無曙。","sortOrder":15},
  {"id":"s_work_nvlt_37_16","chapterId":"ch_work_nvlt_37","text":"又華陽陶先生墓志曰：若夫真以歸空為美，送以無形為貴，不知悅生，大德所以為生，不知惡死，穀神所以不死，妙矣哉，隱顯变化，則物莫之测，既而岫开折石，天墜玉棺，銀書息簡，流珠罢竈，九節麗於空中，千和焚於地下，仙宮有得朋之憙，受學震臨穀之悲，餘昔在粉壤，早逢汜上之術，今簉元良，屢禀浮丘之教，握留符而惻怆，思化杖而酸情，乃為銘曰：無名曰道，不死為仙，以有元則，兼稱稚川，猗欤夫子，受錄歸玄，梨傳苑吏，書因贾舡，鬱鬱方崖，悠悠洞天，三山白鶴，何時复旋。","sortOrder":16},
  {"id":"s_work_nvlt_37_17","chapterId":"ch_work_nvlt_37","text":"梁元帝庾先生承先墓志曰：悠哉掌庾，興自陶唐，伯舅居晉，連鑣渭陽，爰斯厥後，世挺珪璋，乃登靈嶽，言遵洞府，乃陟石山，將從輕舉，實惟貞吉，實惟退讓，皎皎不群，超超高尚，本同寿夭，寧論得丧，諸方未遊，佳城已望，蓬生蒋径，釣罢磻谿，槚悲新隴，桃餘故蹊，風翻嶺背，月下松西，扬名不朽，高蹈夷齊。","sortOrder":17},
  {"id":"s_work_nvlt_37_18","chapterId":"ch_work_nvlt_37","text":"【诔】魯柳下惠妻柳下惠诔曰：夫子之不伐兮，夫子之不竭兮，三黜終不弊兮，恺悌君子，永能厲兮，嗟兮惜哉，乃下世兮，晉張華烈文先生鮑玄泰诔曰。於鑠烈文，續蕤皇祚，夏後基命，靈根已固，杞鄫既微，枝離葉布，爰暨叔牙，世贊齊風，翼桓濟管，遂登霸功，越在漢隆，三司併縱，烈考中丞，妙世顯名，瓘瓘先生，誕資英俊，淑质清醇，蘭芳玉润，抗行崇邈，遊心大順，允文文明，聰昭秀哲，啟冥演幽，守文命世，抱道冲虛，執義貞厲，栖遲無悶，不營不拔，［全晉文五十八作忮。］擬志雲霄，致命窮達，行為范軌，言成隱括，宜登遐年，弘此徽猷，濟濟搢紳，永挹清流，取識遺音，目想表儀，孰雲玄泰，曾不我知，感傷慷慨，揮涕渗澌，已矣鮑子，寧爾玄陰，振聲竹帛，永播徽音。","sortOrder":18},
  {"id":"s_work_nvlt_37_19","chapterId":"ch_work_nvlt_37","text":"晉陆機吳貞獻處士陆君诔曰：我聞有命，天祿有秩，如斯吉人，而有斯疾，兄弟之恩，離形合氣，矧我與君，年相亚逮，綢缪之遊，自矇及朗，孩不貳音，抱或同襁，撫髫併育，携手相長，行焉比跡，誦必共响，庶君偕老，靈根克固，拊翼雲霄，双飛天路，人皆年長，君獨短祚，穀則同朝，遊矣先暮。","sortOrder":19},
  {"id":"s_work_nvlt_37_20","chapterId":"ch_work_nvlt_37","text":"晉處士劉參妻王氏夫诔曰：猗猗嘉穎，朝陽方翘，烈風嚴霜，殒此秀條，璇璣倏忽，四序競征，清商激宇，蟋蟀吟櫺。","sortOrder":20},
  {"id":"s_work_nvlt_37_21","chapterId":"ch_work_nvlt_37","text":"宋顏延之陶徵士诔曰：夫璇玉致美，不為池湟之寶，桂椒信芳，而非園林之實。","sortOrder":21},
  {"id":"s_work_nvlt_37_22","chapterId":"ch_work_nvlt_37","text":"【弔】後漢胡廣弔夷齊曰：遭亡辛之昏虐，時繽紛以芜秽，恥降志於汙君，溷雷同於榮势，抗浮雲之妙志，遂蝉蜕以偕逝，徼六軍於河渚，叩王馬而慮計，雖忠情而指尤，匪天命之所謂，賴尚父之戒慎，镇左右而不害。","sortOrder":22},
  {"id":"s_work_nvlt_37_23","chapterId":"ch_work_nvlt_37","text":"魏王粲弔夷齊文曰：歲旻秋之仲月，從王師以南征，濟河津而長驅，逾芒阜之峥嵘，覽首陽於東隅，見孤竹之遺靈，心於悒而感懷，意惆怅而不平，望壇宇而遙弔，抑悲古之幽情，知養老之可歸，忘除暴之為世，絜己躬以騁志，愆聖哲之大倫，忘舊惡而希古，退采薇以窮居，守聖人之清槩，要既死而不渝，厲清風於貪士，立果志於懦夫，到於今而見稱，為作者之表符，雖不同於大道，今尼父之所譽。","sortOrder":23},
  {"id":"s_work_nvlt_37_24","chapterId":"ch_work_nvlt_37","text":"魏阮瑀弔伯夷曰：餘以王事，適彼洛師，瞻望首陽，敬弔伯夷，東海讓國，西山食薇，重德輕身，隱景潛暉，求仁得仁，報之仲尼，没而不朽，身沈名飛。","sortOrder":24},
  {"id":"s_work_nvlt_37_25","chapterId":"ch_work_nvlt_37","text":"魏靡［《太平御覽》五百九十六作糜。］元弔夷齊曰：少承洪烈，從戎於王，侧聞先生，處於首陽，敢不敬弔，寄之山岡，夫五德更運，天祚靡常，如見絕代之主，必有受命之王，故尧德終於虞舜，禹祚滅於成湯，且夏後之末禮，亦殷氏之所亡，若周武而為失，則帝乙亦有傷，子不弃殷而饿死，何獨背周而深藏，是識春香之為馥，而不知秋蘭之亦芳也，首陽誰山，而子匿之，彼薇誰菜，而子食之，行周之林，讀周之書，彈周之琴，飲周之水，食周之芩，而謗周之主，謂周之淫，是誦周之文，聽聖之音，居聖之世，而異聖之心，嗟乎二子，何痛之深。","sortOrder":25},
  {"id":"s_work_nvlt_37_26","chapterId":"ch_work_nvlt_37","text":"【祭文】宋謝惠連為學生祭周居士文曰：維君陶造化之純元，侔先哲之遐蹤，體無事於高尚，蹈虛素乎中庸，不臣天子，不事諸侯，公辟弗盻，王命匪酬，窮歡極樂，帶索被裘。","sortOrder":26},
  {"id":"s_work_nvlt_37_27","chapterId":"ch_work_nvlt_37","text":"【詔】梁沈約為武帝搜訪隱逸詔曰：高尚其志，義煥通爻，山林不出，訓光惇史，朕聽朝晏罢，尚想幽人，蒲玉之禮，佇聞峻節，可班下州郡，博訊巡遠，若有道映丘園，事孚高尚，可以弭競遷浇，還風拯俗，皆以名聞，靡或遺漏，朕將辟衢室而寘幾杖，开東序而授袞職，庶令江海無遺，異人必至。","sortOrder":27},
  {"id":"s_work_nvlt_37_28","chapterId":"ch_work_nvlt_37","text":"又資給何點詔曰：遠趣高情，前王所貴，義兼昔款，倍用興懷，徵士何點，居貞物表，縱心尘外，夷任之風，率由自遠，往因素志，頗申宴言，眷彼子陵，情兼惟舊，昔仲虞邁俗，受俸漢朝，安道逸志，不辭晉祿，此蓋前代盛軌，往賢所同，可詳加資給，併出所，［景宋本梁書何點傳，所上有在字，此脱。］曰［景宋本梁書作日，此訛。］契資須，太官別給，人高曜卿，故事同垣下。","sortOrder":28},
  {"id":"s_work_nvlt_37_29","chapterId":"ch_work_nvlt_37","text":"【敕】梁沈約為武帝與謝朏敕曰：吾以菲德，屬當期運，鑒與吾言，思隆治道，而明不遠燭，所蔽者多，實寄賢能，正其寡闇，常謂山林之志，上所宜弘，激貪厲薄，義等為政，自居元首，臨對百司，雖复執文經武，各修厥職，群才競爽，以致和美，而镇風靜俗，变教論道，自非箕穎高人，莫膺茲寄，是用虛心侧席，屬想清尘，不得不屈茲獨往，同此濡足，便望釋萝袭袞，出野登朝，必不以濩有慚德，武未盡善，不降其身，不屈其志，使璧帛虛往，蒲輪空歸，傾首東路，望兼立表，羲軒邈矣，古今殊事，不獲總駕崆峒，依風問道，今方复引領雲台，虛己宣室，紆賢之愧，載結寢興。","sortOrder":29},
  {"id":"s_work_nvlt_37_30","chapterId":"ch_work_nvlt_37","text":"又與何胤敕曰：吾猥當期運，膺此樂推，而顧己多蔽，昧於治道，雖复劬勞日昃，思致隆平，而先生遺范，尚蘊方策，息舉之用，存乎其人，兼以世道浇暮，諍诈繁起，改俗遷風，良有未易，自非以儒雅弘朝，高尚軌物，則泊流所至，莫知其限，治人之與治身，獨善之與兼濟，得失去取，為用孰多，吾雖不學，頗好博古，尚想高尘，每懷击節，今世務紛糾，忧责是當，不得不屈道巖阿，共成世美，必望深達往懷，不吝濡足。","sortOrder":30},
  {"id":"s_work_nvlt_37_31","chapterId":"ch_work_nvlt_37","text":"【教】江淹為宋建平王聘逸士教曰：府州國綱紀，雖周德之富，猶有漁潭之士，漢教之隆，亦見西山之夫，跡絕雲氣，意負青天，皆待絳螭驤首，翠虬來儀，是以清風扇百代，餘烈激後生，斯乃王教之助，古人之意焉。","sortOrder":31},
  {"id":"s_work_nvlt_37_32","chapterId":"ch_work_nvlt_37","text":"【表】魏桓范荐管寧表曰：臣聞殷湯聘伊尹於畎畝之中，周文進呂尚於渭水之濱，竊見東莞管寧，束脩著行，少有令稱，州闾之名，亚故太尉華歆，遭亂浮海，遠客遼東，於混濁之中，履絜清之節，篤行足以厲俗，清風足以矯世，以箪食瓢飲，過於顏子，漏屋蔽衣，逾於原憲，臣聞唐尧寵許由，虞舜禮支父，夏禹優伯成，文王養夷齊，及漢祖高四皓之名，屈命於商洛之野，史籍叹述，以為美談，陛下紹五帝之鸿烈，併三王之逸軌，膺期受命，光昭百代，仍有優崇之禮，於大夫管寧，寵以上卿之位，榮以安車之稱，斯之為美，當在魏典，流之無窮，明世之高士也，臣以為既加其大，不受其細，可重之以玄纁，聘之殊禮矣。","sortOrder":32},
  {"id":"s_work_nvlt_37_33","chapterId":"ch_work_nvlt_37","text":"晉皇甫謐讓徵聘表曰：臣因病抽簪，散發林阜，人綱否閉，鳥獸為群，伏自惟忖，瓶鮓琐器，實非瑚璉之求，稊稗之賤，不中粢盛之用，小人致灾，久婴篤疾，仰迫天威，不能淹留，所苦加篤，不任進路，委身待罪，伏枕叹息，仰惟陛下，留神恕恩，垂怜微命，索隱於傅巖，收釣於渭濱，無令泥滓，久濁清流，臣聞邹子一叹，霜為之降，杞妻一感，城為大崩，以臣况之，乃知精誠不可以賤致，古人言為虛也。","sortOrder":33},
  {"id":"s_work_nvlt_37_34","chapterId":"ch_work_nvlt_37","text":"【啟】梁何胤答皇太子啟曰：胤性愛山泉，情篤魚鳥，而從鷗未狎，入獸相驚，兼年齒衰暮，荒径榛梗，既無語稼之客，寧有論書之賓，緘嘿畎畝，栖息丘壑，秀木清潭，於茲永已，伏惟明察之德，誕縱自天，忠孝之規，不待因習，猶复留神六經，降意百代，同仁博古，等物簉聞，辟承華而延儒雅，埽黃闼而列文學，嘉美聿宣，無思不勸，胤無解歸之談，屢蒙奖飾之重，匪南皮之舊，每荷存問之恩，衔茲污朽，罔知攸寘。","sortOrder":34},
  {"id":"s_work_nvlt_37_35","chapterId":"ch_work_nvlt_37","text":"又梁沈約謝齊竟陵王教撰高士傳啟曰：竊聞高尚其事，義光爻象，賢者避世，聲煥典墳，豈徒激貪勉競，澡身浴德而已，爾乃大弘義訓，百代通風，是以梁鸿蘇伯，記遠跡於前，叔夜士安，書高麈於後，雖去取異情，群略殊軫，而獨行必彰，斥言罔極，貞操與日月俱懸，孤芳隨山壑共遠，明公得一含道，體二居宗，跡屈巖廊之下，神遊江海之上，愛奇商洛，訪美東都，蓋欲隱顯高功，出處同致，巢由與伊旦併流，三辟與四門共軌，肅奉明規，思自罄勖。","sortOrder":35},
  {"id":"s_work_nvlt_37_36","chapterId":"ch_work_nvlt_37","text":"【書】後漢張奐與宋季文書曰：攬手跡，知遂遵南山之志，繼四賢之蹤，時止則止，時行則行，其道光明，奐以鄙固，少复道訓，於今五十載矣。","sortOrder":36},
  {"id":"s_work_nvlt_37_37","chapterId":"ch_work_nvlt_37","text":"魏桓范與管寧書曰：凿坏而處，養德顯仁，尧舜在上，許由在下，箕山之志，於是复顯，嚴平鄭真，未足論比，清聲遠播，顽鄙慕仰，思請見於蓬庐之侧，承訓誨於道德之門，厥涂無由，讬思晨風。","sortOrder":37},
  {"id":"s_work_nvlt_37_38","chapterId":"ch_work_nvlt_37","text":"魏管寧答桓范書曰：乾道辅誠，誕膺嘉祚，膺受多福，為國蕃維，雖分陝之任，未足比盛，遠近□望，何慶如之，昔值险阻，越竄海表，於裔歷載，風綱不紀，暨蒙國恩，還踐舊土，簿佐多難，恒婴篤疾，愧使區區，展之無偕，泛愛遇隆，遠辱纶墨，降尊誘卑，訓喻過泰，見得思義，抱以踧踖，不勝來顧，裁因答辱。","sortOrder":38},
  {"id":"s_work_nvlt_37_39","chapterId":"ch_work_nvlt_37","text":"晉辛曠與皇甫謐書曰：夫三光懸象，式扬天德，嶽渎山泽，廣开地道，賢人顯進，實興聖治，故力牧佐黃，而涿鹿之征捷，舜禹翼唐，而滔天之灾殄，阿衡在商，而成湯之功著，薑望入周，而文武之業建，聖人光濟四海，欲垂大化者，莫不收才取良，而致股肱，忠賢大才之人，原立名跡，思在利見大人，而主聖時治，此所以應天順民之神龟，利涉大川之元吉，大晉合天地之中和，經日月之重光，四目视其明，四聰達其聽，巖穴出其隱，四門啟其矇，登高陽之八子，御高辛之群龍，俊才在官，時亮天工，鳥獸非君子之儔，九皋無長鳴之鶴，萬國黎獻，鹹仰南風之仁，而抱聖化之隆，此其至治也，而先生固執冲虛，塞淵其心，殉文人之耿介，忘宣尼之所沽，步幽山之窮径，背漢津之明衢，日月遂往，時不我須，此惜寸陰者之所以為懼，而臨川者之所懷慨也，竊謂先生降匪石於高岡，回羽儀於皇京，順震驚而翔撫，奋六翮於天庭，邈禹稷之遐蹤，騁大往之夷涂，招不世之洪勋，同先哲之丕模，使瞻仰者所以藉之美也，希藉人六義之一，獻斯一篇，惟蒙采覽。","sortOrder":39},
  {"id":"s_work_nvlt_37_40","chapterId":"ch_work_nvlt_37","text":"又與皇甫謐書曰：伏惟先生，黃中通理，經纶稽古，既好斯文，述而不作，將邁卜商於洙泗之上，超董生於儒林之首，含光烈於千載之前，吐英聲於萬世之後，亦以盛矣，曠以不敏，感佩厚惠，原附骥尾，撫尘而遊，谘睹未因，而西望延企。","sortOrder":40},
  {"id":"s_work_nvlt_37_41","chapterId":"ch_work_nvlt_37","text":"晉皇甫謐答辛曠書曰：聞服有素，委心無量，加昔州壤，通門舊儀，虛想之積，過於陵阜，汎愛不遺，猥降德音，清喻烂煥，情義款篤，執誨欣然，若饗太牢，抱佩至眷，銘乎心膂，且箕山之叟，超跡於尧帝之世，首陽之老，抗操於有周之隆，故能名奋百代，使聞之厲節，皆經聖明之論，所以邈世卓時者也，至於鄙薄，才顽行秽，疾奪其志，神迷其心，因讬虛靜，遂竊美選，聖上仁聰，亮其辛苦，每自陳訴，辄見宽放，雖大君有命，實小人勿用也，匪敢盤桓，疾與榮競，巾車順命，非劣憊所堪也，密雲雖興，知枯木難植，昔人有言，欲之必為之辭，豈來惠之謂矣，猥承告示，欲備七十，木非梧桐，豈敢栖鳳，聞命悚灼，如蹈春冰，非苟崇謙，實懼陷墜，幸恕不假，明亮志心。","sortOrder":41},
  {"id":"s_work_nvlt_37_42","chapterId":"ch_work_nvlt_37","text":"梁昭明太子與何胤書曰：園公道勝，漢盈屈節，春卿明經，漢莊北面，况乃義兼乎此，而顧揆不肖哉，但經途千里，眇焉莫因，何嘗不夢姑胥而鬱陶，想具區而杼軸，心往形留，於茲有年載矣，方今朱明在謝，清風戒寒，想攝養得宜，與時休適，耽精義，味玄理，息嚣尘，玩泉石，激扬硕學，誘接後進，志與秋天競高，理與春泉爭溢，樂可言乎，樂可言乎，豈與口厭刍豢，耳聆絲竹者之娱，同年語哉，方今泰階端平，天下無事，修日養夕，差得從容，每鑽閱六經，汎濫百氏，研尋物理，顧略清言，既以自慰，且以自警，而才性有限，思力匪長，熱疾愦其神，風眩弊其體，多慚過目，釋卷便忘，是以蒙求之懷，於茲弥軫。","sortOrder":42},
  {"id":"s_work_nvlt_37_43","chapterId":"ch_work_nvlt_37","text":"梁任昉為昭明太子答何胤書曰：得書，知便遠追疏董，超然高蹈，雖朝旨殷勤，而輕棹已遠，供踐莫申，瞻言增慨，善保嘉猷，比致音息，懷人望古，潸怅久之。又為庾杲之與劉居士虬書曰：自別荆南，迄將二紀，杲之牵滯形有，推遷物保，丈人没志外身，超然獨善，雖心路咫尺，而事阻山河，悠悠白雲，依然有道，金涼佇運，想恒納宜，冲明在襟，履候無爽，體道為用，蹈理則和，杲之牵缀疲朽，愧心已多，訪德則山林窅然，觀道則風雲自遠，歲暮之期，指涂衡嶽，神虛氣懋，無待怡和，江湖相望，安事行李，司徒竟陵王，懋於神者，言象所絕，接乎士者，遐邇所宗，鍾石非禮樂之本，纓褐豈朝野之謂，想闇投之懷，不以形體為阻，一日通籍梁邸，親奉話言，夢想清尘，為歲已積，以大人非羔雁所榮，故息蒲幣之典，勝寄冥運，谅有風期之遲，君王卜居郊郭，榮［全梁文四十三作萦。］帶川阜，顯不絢功，晦不摽跡，從容乎人野之間，以窮二者之致，且弘護為心，廣孚真俗，思聞系表，共剖眾心，妙域筵山河，虛馆帶川涘，實望贲然，少詶侧遲，昔東平樂善，旌君大於東閤，今王愛素，致吾子於西山，豈不盛欤，百齡飄骤，凝滯自物，千載一朝，為仁由己，且凌雪戒涂，非滅跡之郊，鸿鍾在御，豈銷聲之道，已摽異人之跡，故有同物之勞，夫山水無情，應之以會，愛閒在我，觸目萧條，衡嶽何親，鍾嶺何薄，想弘思有在，不俟繁言。","sortOrder":43},
  {"id":"s_work_nvlt_37_44","chapterId":"ch_work_nvlt_37","text":"梁劉孝標與宋玉山元思書曰：驅馬金張之馆，飛蓋許史之庐，習匡鼎之說詩，騁穀雲之雕篆，賓徒波涌，舆輪靡息，當是時也，樂可言哉，然靜思夫君，愀焉軫叹，何則，方凿圓枘，鉏铻難從，翔鳥遊魚，蹉跎不狎，是以贾生懷琬琰而挫翮，冯子握玙璠而鍛羽，夫［全梁文五十七作天。］誕英逸，獨擅民秀，心貞筠箭，德润珪璋，信人［全梁文人下空二字，有脱文。］水鏡，一性之鎔范，而荆南雅曲，高音鮮和，河西名骥，滅没誰賞，故若先生者，進有三難，退有三樂，竊觀先生，未能鸿翔鸞起，騰霞跻漢，將由囿空桑麻，田無負郭，俯眉翕肩，以斯故爾，今賢弟賓從，抗鱗奋翼，或衣繡江塘，或鳴騶洛渚，連騎方驅，击鍾乃食，萼跗若是，吾子复何忧哉，唯當纂兩仲之微跡，袭二疏之風流，生與漁父同僖，死葬要離墓侧，金石可碎，聲華無寂，斯道坦坦，先生幸其勖與。","sortOrder":44},
  {"id":"s_work_nvlt_37_45","chapterId":"ch_work_nvlt_37","text":"又陶弘景答謝中書曰：山川之美，古來共談，高峰入雲，清流見底，兩岸石壁，五色交暉，青林翠竹，四時俱備，晓霧將歇，猿鳥亂鳴，夕日欲頹，沉鱗競躍，實是欲界之仙都，自康樂以來，未复有能與其奇者。","sortOrder":45},
  {"id":"s_work_nvlt_37_46","chapterId":"ch_work_nvlt_37","text":"又答虞仲書曰：栖六翮於荆枝，望綺雲於青漢者，有日於茲矣，而春華來被，草石开鮮，辭動情端，志交衿曲，信知鄰德之談，無虛往牍，夫子雖跡躔朱閤，而心期岱嶺，豈但散發乎高岫，以將飛霜於絕穀，良為钦哉，野人幸得讬形崇阜，息影長林，每對月流叹，臨風軫慨，徒事累可豁，而發容難待，自非齊生死於一致者，孰不心熱者乎，舉世悠悠，孰雲同此，傥遇知己，相與共忧，朅來虞公，茲焉可邁，何為栖栖，空勞鼓缶，迨及暇日，有事還童，不亦皎絜當年，而無忸前修也。","sortOrder":46},
  {"id":"s_work_nvlt_37_47","chapterId":"ch_work_nvlt_37","text":"又答趙英才書曰：子架學區中，飛才甸外，不肯埽門觅仕，复懶彈鋏求通，故偃蹇園巷，從容郊邑，昔所謂泬賓者，此其是乎，巖下鄙人，守一介之志，非敢蔑榮嗤俗，自致雲霞，蓋任性靈而直往，保無用以得閒，垅薪井汲，樂有餘歡，切松煮術，此外何務，然亦以天地棟宇，萬物同於一化，死生善惡之能聞。","sortOrder":47},
  {"id":"s_work_nvlt_37_48","chapterId":"ch_work_nvlt_37","text":"梁沈約答沈麟士書曰：獨往之業，雖聞前載，高尘逸軌，罕或共時，未嘗不拊袠興懷，望古遐矚，尊賢拔俗，遙然沉冥，自遠幽貞之操，義高篆策，雖蒋詡不窥城市，鄭真名動京師，何遠之有，名山既乡內所丰，清川又坐臥可對，不出戶庭，而與禽尚齊美哉，約少不自涯，早愛虫鳥，逐食推遷，未諧夙原，冀幽期可讬，克全素履，與尊弋釣泉皋，以慰閒暮，則生平之心，於此遂矣。","sortOrder":48},
  {"id":"s_work_nvlt_37_49","chapterId":"ch_work_nvlt_37","text":"梁王僧孺與陳居士書曰：雲波遙敻，燕越數千，行雲鬱術，征禽難使，用隔巾車，未能搦札，引領南望，怅矣心飛，幸因劣薄，懷章貴壤，依然穀口，覺子真之咫尺，靜睇巖滩，信子陵之非遠，林鹿以入虛白之室，用披蓬蒿之径，禀紛纶之高論，承希微之妙旨，虛往實歸，用袪尘惑。","sortOrder":49},
  {"id":"s_work_nvlt_37_50","chapterId":"ch_work_nvlt_37","text":"孔德璘［按當作璋，北山移文曰：鍾山之英，草堂之靈。］","sortOrder":50},
  {"id":"s_work_nvlt_37_51","chapterId":"ch_work_nvlt_37","text":"【論】魏阮籍達莊論曰：天道貴順，地道貴貞，聖人修之，以建其名，吉凶有分，是非有經，務利高势，惡死重生，故天下安而大功成也，今莊子周，乃齊禍福而一死生，以天地為一物，以萬類為一指，無乃徼惑以失真，而自以為誠者也。於是先生乃撫琴容與，慨然而叹，俯而微笑，仰而流盻，噓吸精神，言其所見，天地名焉，天地者有內，故萬物生焉，當其無外，誰謂異乎，當其有內，誰謂殊乎，地沉其燥，天抗其濕，月東出，日西入，故曰：自其異者视之，則肝胆楚越矣，自其同者视之，則萬物一體也，以生言之，則物無不寿，推之以死，則物無不夭，自小视之，則萬物莫不小，由大觀之，則萬物莫不大，殇子為寿，彭祖為夭，秋毫為大，泰山為小，故以死生為一貫，是非為一條也，夫至人者，恬於生而靜於死，恬生則不惑，死靜則神不離生，故能與陰陽化而不易，從天地变而不移，生究其寿，死終其宜，心氣平治，消息不虧，故求得者丧，爭明者失，無欲者自足，空虛者受實，是以作智造巧者害於物，明是考非者危其身，脩飾以顯絜者惑於生，畏死而崇生者失其貞。","sortOrder":51},
  {"id":"s_work_nvlt_37_52","chapterId":"ch_work_nvlt_37","text":"晉石崇許巢論曰：客有問於餘曰：昔許由巢父，距尧之讓，逍遙颐神，寶己貴世，司馬遷以假讬之言，必無此實，竊以為然，餘答之曰：是何言欤，蓋聞聖人在位，則群材必舉，官才任能，輕重允宜，大任已備，則不抑大材使居小位，小材已極其分，則不以積久而合處過材之位，然則稷播嘉穀，契敷五教，皋陶夔龍，各已授職，其聯屬之官，必得其材，則必不重載兼置，斯可知也，巢許則元恺之儔，大位已充，則宜敦廉讓以励俗，崇無為以化世，然後動靜之教備，隱顯之功著，故能成巍巍之化，民莫能名，將何疑焉。","sortOrder":52},
  {"id":"s_work_nvlt_37_53","chapterId":"ch_work_nvlt_37","text":"晉庾闡郭先生神論曰：夫天地者，陰陽之形魄，变化者，萬物之遊魂，神籁與無窮併吹，大冶與造運齊根，生資聚氣之跡，死寄玄牝之門，视榮辱其猶尘埃，邈高尚而不顧，故能外安恬逸，內體平和，鳴鳥可拊翼而遊，猛獸可頓羁而羅，矧乎樵巖之樂，呂梁之波，疾雷破嶽，而忧在山河者乎，觀夫郭先生之為體也，可謂含真履信，純朴自然。","sortOrder":53},
  {"id":"s_work_nvlt_37_54","chapterId":"ch_work_nvlt_37","text":"晉王叔之遂隱論曰：崇退儒生，問於抱朴丈人曰：請問隱何為者也而生，上古徇之，至今繼踵，何哉，丈人曰：夫全朴之道，萬物一氣，三極湛然，天人無际，豈有朝野之別，隱顯之端哉，則夫隱者，於己失者也，平原既开，風流散漫，故隱者所以全其真素，養其浩然之氣也。","sortOrder":54},
  {"id":"s_work_nvlt_37_55","chapterId":"ch_work_nvlt_37","text":"宋范晔逸民傳論曰：尧稱則天，而不屈穎陽之高。","sortOrder":55},
  {"id":"s_work_nvlt_37_56","chapterId":"ch_work_nvlt_37","text":"梁沈約七賢論曰：嵇生是上智之人，值無妄之日，神才高杰，故為世道所莫容，風邈挺特，荫映於天下，言理吐論，一時所莫能參，屬馬氏執國，欲以智計傾皇祚，誅鉏勝己，靡或有遺，玄伯太初之徒，併出嵇生之流，鹹已就戮，嵇審於此時，非自免之運，若登朝進仕，映邁當時，則受禍之速，過於旋踵，自非霓裳羽帶，無用自全，故始以餌術黃精，終於假涂讬化，阮公才器宏廣，亦非衰世所容，但容貌風神，不及叔夜，求免世難，如為有涂，若率其恒儀，同物俯仰，邁群獨秀，亦不為二馬所安，故毀行废禮，以秽其德，崎嶇人世，仅然後全，仲容年齒，不齒不懸，風力粗可，慕李文［疑當作季父。］風尚，景而行之，彼嵇阮二生，志存保己，既讬其跡，宜慢其形，慢形之具，非酒莫可，故引滿終日，陶兀盡年，酒之為用，非可獨酌，宜須用侣，然後成歡，劉伶酒性既深，子期又是飲客，山王二公，悅風而至，相與莫逆，把臂高林，徒得其遊，故於野泽，衔杯舉樽之致，寰中妙趣，固冥然不睹矣，自嵇阮之外，山向五人，止是風流器度，不為世匠所駭，且人本含情，情性宜有所讬慰，悅當年隱，［句有訛。］萧散懷抱，非五人之與，其誰與哉。","sortOrder":56},
  {"id":"s_work_nvlt_37_57","chapterId":"ch_work_nvlt_37","text":"《藝文類聚》　唐·欧陽詢","sortOrder":57},
  {"id":"s_work_nvlt_38_1","chapterId":"ch_work_nvlt_38","text":"卷三十八禮部上","sortOrder":1},
  {"id":"s_work_nvlt_38_2","chapterId":"ch_work_nvlt_38","text":"○禮祭祀郊丘宗廟明堂辟雍學校釋奠","sortOrder":2},
  {"id":"s_work_nvlt_38_4","chapterId":"ch_work_nvlt_38","text":"《管子》曰：禮者，因人之情，緣義之理，而為之節文者也。","sortOrder":4},
  {"id":"s_work_nvlt_38_5","chapterId":"ch_work_nvlt_38","text":"《物理論》曰：禮者，履也，律也，義同而名異，五禮者，吉凶賓軍嘉也。","sortOrder":5},
  {"id":"s_work_nvlt_38_6","chapterId":"ch_work_nvlt_38","text":"周禮，大宗伯之職，以吉禮事邦國之鬼神祇，事謂祀之祭之享之，以凶禮哀邦國之忧，哀謂救患分灾也，以賓禮親邦國，以軍禮同邦國，同謂威其不葉偕老［周禮註作僣差，此訛。］也，以嘉禮親萬民，嘉，善也，所以因人心所善而為製，吉禮之別十有二，一曰禋祀，二曰實柴，三曰槱燎，四曰血祭，五曰埋沉，六曰副辜，七曰肆獻，八曰饋食，九曰祠，十曰禴，十一［一下脱曰字。］嘗，十二曰蒸，凶禮之別有五，一曰丧禮，哀死亡，二曰荒禮，哀凶札荒，人物有害之也，三曰弔禮，哀禍灾，遭水火也，四曰禬禮，哀围败，同盟合會财货，以更其所丧也，五曰恤禮，哀寇亂，鄰國相忧，賓禮之別有八，一曰朝，二曰宗，三曰觐，四曰遇，五曰會，六曰同，七曰問，八曰视，軍禮之別有五，一曰大師之禮以用眾，二曰大均之禮以恤眾，［均其地政，所以忧民。］三曰大田之禮以簡眾，因田習閱車徒之數也，四曰大役之禮以任眾，筑宮邑，所以事民力彊［周禮註彊下有弱字。］也，五曰大封之禮以合眾，正封疆以合眾人也，嘉禮之別有六，一曰飲食，二曰婚冠，三曰賓射，四曰饗燕，五曰脤膰，六曰慶贺。","sortOrder":6},
  {"id":"s_work_nvlt_38_7","chapterId":"ch_work_nvlt_38","text":"又曰：太宰掌三曰禮典，以和邦國，以統百官，以諧萬民。","sortOrder":7},
  {"id":"s_work_nvlt_38_8","chapterId":"ch_work_nvlt_38","text":"大司徒以五禮防民之伪，而教之中。","sortOrder":8},
  {"id":"s_work_nvlt_38_9","chapterId":"ch_work_nvlt_38","text":"《禮記》曰：禮也者，體也，禮不備，謂之不成人。","sortOrder":9},
  {"id":"s_work_nvlt_38_10","chapterId":"ch_work_nvlt_38","text":"又曰：夫禮者，所以定親疏，决嫌疑，別同異，明是非也，道德仁義，非禮不成，教訓正俗，非禮不備，分爭辯訟，非禮不决，君臣上下，父子兄弟，非禮不定。","sortOrder":10},
  {"id":"s_work_nvlt_38_11","chapterId":"ch_work_nvlt_38","text":"又曰：夫禮，先王以承天之道，以治人之情，故失之者死，得之者生，詩雲，相鼠有體，人而無禮，人而無禮，胡不遄死，言偃复問曰：夫子之極言禮也，可得而聞與，孔子曰：我欲觀夏道，是故之杞而不足徵也，吾得夏時焉，我欲觀殷道，是故之宋而不足徵也，吾得坤乾焉。","sortOrder":11},
  {"id":"s_work_nvlt_38_12","chapterId":"ch_work_nvlt_38","text":"又曰：故人情者，聖王之田也，修禮以耕之，陳義以种之，講學以耨之，本仁以聚之，播樂以安之。","sortOrder":12},
  {"id":"s_work_nvlt_38_13","chapterId":"ch_work_nvlt_38","text":"又曰：禮其在人也，如竹箭之有筠也，如松柏之有心也，二者居天下之大端也，貫四時，不改柯易葉。","sortOrder":13},
  {"id":"s_work_nvlt_38_14","chapterId":"ch_work_nvlt_38","text":"又曰：夫禮本於太一，分而為天地，轉而為陰陽，变而為四時，列而為鬼神。","sortOrder":14},
  {"id":"s_work_nvlt_38_15","chapterId":"ch_work_nvlt_38","text":"《大戴禮》曰：禮象五行也，其義四時也，故以四時［大戴禮本命篇無時字。］舉，有思，［大戴禮作恩，此訛。］有義，有節，有權。","sortOrder":15},
  {"id":"s_work_nvlt_38_16","chapterId":"ch_work_nvlt_38","text":"《左傳》曰：子太叔見趙簡子，簡子問揖讓周旋之禮，對曰：是儀也，非禮也，簡子曰：敢問何謂禮，對曰：聞諸先大夫子產曰：夫禮，天地之經也，地之義也，民之行也。","sortOrder":16},
  {"id":"s_work_nvlt_38_17","chapterId":"ch_work_nvlt_38","text":"又曰：邾隱公來朝，子貢觀焉，邾子執玉高，其容仰，公受玉卑，其容俯，子貢曰：以禮觀之，二公皆有亡焉，今朝贺而不度，高仰驕也，卑俯替也，驕近亂，替近疾，君為主，其先亡乎。","sortOrder":17},
  {"id":"s_work_nvlt_38_18","chapterId":"ch_work_nvlt_38","text":"《論語》曰：道之以政，齊之以刑，民免而無恥，道之以德，齊之以禮，有恥且格。","sortOrder":18},
  {"id":"s_work_nvlt_38_19","chapterId":"ch_work_nvlt_38","text":"又曰：顏回問仁，子曰：克己复禮為仁，一日克己复禮，天下歸仁焉，為仁由己，而由人乎哉，顏回曰：請問其目，子曰：非禮勿视，非禮勿聽，非禮勿言，非禮勿動，顏回曰：回雖不敏，請事斯語矣。","sortOrder":19},
  {"id":"s_work_nvlt_38_20","chapterId":"ch_work_nvlt_38","text":"《莊子》曰：三皇五帝之禮義法度，不矜於同，而矜於治，故譬三皇五帝之禮義法度，其猶楂梨橘柚耶，其味相反，而皆可於口，故禮義法度，應時而变也。","sortOrder":20},
  {"id":"s_work_nvlt_38_21","chapterId":"ch_work_nvlt_38","text":"《孫卿子》曰：人生有欲，欲則求，求則爭，爭則亂，亂則窮，先王惡其亂也，故製禮義以養之，《慎子》曰：禮從俗，政從上，使從君，國有貴賤之禮，無賢不肖之禮也。","sortOrder":21},
  {"id":"s_work_nvlt_38_22","chapterId":"ch_work_nvlt_38","text":"《白虎通》曰：所以作禮樂者，樂以象天，禮以法地。","sortOrder":22},
  {"id":"s_work_nvlt_38_23","chapterId":"ch_work_nvlt_38","text":"《家語》曰：孔子言於魯哀公曰：人之所以生，禮為大，非禮無以辨君臣之位。","sortOrder":23},
  {"id":"s_work_nvlt_38_24","chapterId":"ch_work_nvlt_38","text":"董生書曰：理者天所為也，文者人所為也，人所為謂之禮，禮者，因人情而為節文也，以救其亂，夫隄者水之防也，禮者人之防也，刑防其末，禮防其本。","sortOrder":24},
  {"id":"s_work_nvlt_38_25","chapterId":"ch_work_nvlt_38","text":"《禮稽命徵》曰：禮之動搖也，與天地同氣，四時合信，陰陽為符，日月為明。","sortOrder":25},
  {"id":"s_work_nvlt_38_26","chapterId":"ch_work_nvlt_38","text":"《漢書》曰：叔孫通為高祖製漢儀十二篇。","sortOrder":26},
  {"id":"s_work_nvlt_38_27","chapterId":"ch_work_nvlt_38","text":"范晔《後漢書》曰：詔召玄武司馬班固，問定禮製之宜，固曰：京師諸儒，多能說禮，宜廣招集，共議失得，帝曰：作舍道邊，三年不成，會禮之家，名為聚訟，互生疑異，筆不得下，昔者尧作大章，一夔足矣，章和元年，乃召曹褒，詣嘉德門，持班固所上叔孫通漢儀十二篇，敕褒曰：此製散略，多不合經，令宜依製條，使可施行，褒於南宮東觀，考正舊禮，上自天子，至於庶人，冠昏吉凶，終始製度，以為一百五十篇。","sortOrder":27},
  {"id":"s_work_nvlt_38_28","chapterId":"ch_work_nvlt_38","text":"《典略》曰：孔子適宋，與弟子習於树下，宋司馬桓魋使人拔其树，去適於野。","sortOrder":28},
  {"id":"s_work_nvlt_38_29","chapterId":"ch_work_nvlt_38","text":"【賦】楚荀况禮賦曰：爰有大物，非絲非帛，文理成章，非日非月，為天下明，生者以寿，死者以葬，城郭以固，三軍以彊，粹而王，駮而霸，無一焉而亡，臣愚弗識，敢請之王，王曰：此夫文而不采者欤，簡而易知，而致有理者欤，君子所敬，小人所不敬者欤，匹夫隆之，則為聖人，諸侯隆之，則一四海者欤，致明而約，甚順而體，請歸之禮。","sortOrder":29},
  {"id":"s_work_nvlt_38_30","chapterId":"ch_work_nvlt_38","text":"◇祭祀","sortOrder":30},
  {"id":"s_work_nvlt_38_31","chapterId":"ch_work_nvlt_38","text":"《尚書大傳》曰：祭之為言察也，荐，至也，言人事至於神也。","sortOrder":31},
  {"id":"s_work_nvlt_38_32","chapterId":"ch_work_nvlt_38","text":"《爾雅》曰：春祭曰祠，祠之言食，夏祭曰礿，新菜可汋，秋祭曰嘗，嘗新穀也，冬祭曰蒸，蒸，進也，進品物祭天曰燔柴，既祭，積薪焚之，祭地曰瘞薶，既祭，埋藏之，祭山曰庪懸，或庪或懸，置之於山，［庪音軌。］祭水曰沉浮，或沉或浮，置之於水，祭星曰布，布散於地，祭風曰磔，今俗當大道中磔狗，雲以止風，此其遺象也，是類是禡，師祭也，類於上帝，禡於所征之地，［禡，莫架反，出詩雅也。］既伯既祷，馬祭也，伯，馬祖也，將用馬力，必先祭其祖也。","sortOrder":32},
  {"id":"s_work_nvlt_38_33","chapterId":"ch_work_nvlt_38","text":"《廣雅》曰：圓丘大壇，祭天也，方泽大折，祭地也。","sortOrder":33},
  {"id":"s_work_nvlt_38_34","chapterId":"ch_work_nvlt_38","text":"《周書》曰：設丘兆於南郊，以祀上帝，配以後稷農星，先王皆與食。","sortOrder":34},
  {"id":"s_work_nvlt_38_35","chapterId":"ch_work_nvlt_38","text":"《說文》曰：除惡之祭曰禬，告事示福曰祷，道上之祭曰犭軍，絜意以享曰禋，以事類祭神曰禷，祭司命曰礻比，［俾利反。］祭豕先曰礻曹，［似勞反。］月祭曰祽。［子內反。］","sortOrder":35},
  {"id":"s_work_nvlt_38_36","chapterId":"ch_work_nvlt_38","text":"《周官》曰：凡庶人不畜者，祭無牲，不耕者，祭無盛。","sortOrder":36},
  {"id":"s_work_nvlt_38_37","chapterId":"ch_work_nvlt_38","text":"又曰：血祭祭社稷五祀五嶽，埋沉祭山林川泽，以副［副音孚逼(經典釋文，下有反字。)膝(周禮註作焜。)也。］辜祭四方百物，以肆獻祼享先王，以饋食享先王。","sortOrder":37},
  {"id":"s_work_nvlt_38_38","chapterId":"ch_work_nvlt_38","text":"又曰：凡陽祀，用骍牲毛之，陰祀，用黝牲毛之，陰是北郊。","sortOrder":38},
  {"id":"s_work_nvlt_38_39","chapterId":"ch_work_nvlt_38","text":"又鄭註曰：《周禮》曰：鬱為蘭也，煮之和鬯酒也。","sortOrder":39},
  {"id":"s_work_nvlt_38_40","chapterId":"ch_work_nvlt_38","text":"《禮記》曰：祭，丰年不奢，凶年不俭。","sortOrder":40},
  {"id":"s_work_nvlt_38_41","chapterId":"ch_work_nvlt_38","text":"又曰：祭不欲數，數則不敬，祭不欲疏，疏則怠，是故君子合諸天道，春禘秋嘗，霜露既降，君子履之，必有凄怆之心，非寒之謂也，春雨露既濡，君子履之，必有怵惕之心，如將見之，樂以迎來，哀以送往。","sortOrder":41},
  {"id":"s_work_nvlt_38_42","chapterId":"ch_work_nvlt_38","text":"又曰：孟春之月，其祀戶，祭先脾，孟夏之月，其祀竈，祭先肺，中央土，其祀中霤，祭先心，孟秋之月，其祀門，祭先肝，孟冬之月，其祀行，祭先腎，天子祭天地四方山川五祀，歲遍，大夫祭五祀，歲遍，士祭其先，祭日於壇，祭月於坎，日於東序，月於西序，以別幽明內外，王立七祀，曰司命，曰中霤，曰國行，曰國門，曰泰厲，曰戶，曰竈，諸侯五祀，曰司命中霤國門國行公厲，大夫三祀，曰族厲，曰門，曰行，士二祀，曰門，曰行，庶人一祀，曰或亡戶，或立竈，聖人之製祀也，法施於人則祀之，以死勤事則祀之，以勞定國則祀之，能御大灾則祀之，日月星辰，人所瞻仰也，山林川穀丘陵，人所取材用也，非此族也，不在祀典。","sortOrder":42},
  {"id":"s_work_nvlt_38_43","chapterId":"ch_work_nvlt_38","text":"《尚書》曰：肆類於上帝，禋於六宗，望於山川，遍於群神，王肅註雲，六宗者，所宗者皆絜祀之，埋少牢於泰昭，祭時也，相近於坎壇，祭寒暑也，王宮祭日也，夜明祭月也，幽禜祭星也，雲禜祭水旱也。","sortOrder":43},
  {"id":"s_work_nvlt_38_44","chapterId":"ch_work_nvlt_38","text":"《詩》曰：以享以祀，以介景福。","sortOrder":44},
  {"id":"s_work_nvlt_38_45","chapterId":"ch_work_nvlt_38","text":"《穀梁傳》曰：宮室不設，不可以祭者，荐其義也，非享味也。","sortOrder":45},
  {"id":"s_work_nvlt_38_46","chapterId":"ch_work_nvlt_38","text":"《物理論》曰：古者尊祭重神，祭宗廟，追養也，祭天地，報往也。","sortOrder":46},
  {"id":"s_work_nvlt_38_47","chapterId":"ch_work_nvlt_38","text":"《論衡》曰：凡祭祀之義有二，一曰報功，二曰修先，報功以勉力，脩先以崇恩也。","sortOrder":47},
  {"id":"s_work_nvlt_38_48","chapterId":"ch_work_nvlt_38","text":"《幽明錄》曰：廟方四丈，不作墉道，廣□［原缺，明本作五，《初學記》十三作四。］尺，夹树蘭香，斋者煮以沐浴後祭，所謂蘭湯。","sortOrder":48},
  {"id":"s_work_nvlt_38_49","chapterId":"ch_work_nvlt_38","text":"《尸子》曰：齊有貧者，命其狗為富，命其子為樂，方將祭，入於室，叱之曰：富出，祝曰：不祥，家果有禍，長子死，哭之曰：樂乎，而不自悲也。","sortOrder":49},
  {"id":"s_work_nvlt_38_50","chapterId":"ch_work_nvlt_38","text":"《孔丛子》曰：元和二年春，帝東巡狩，還過魯，幸闕里，以太牢祀孔子及七十弟子，作六代之樂，大會孔氏男子二十以上者六十人。","sortOrder":50},
  {"id":"s_work_nvlt_38_51","chapterId":"ch_work_nvlt_38","text":"《越絕書》曰：越王既往平吳，春祭三江，秋祭五湖，因以其時為之立祠，垂之末世，傳之萬載。","sortOrder":51},
  {"id":"s_work_nvlt_38_52","chapterId":"ch_work_nvlt_38","text":"《漢書》曰：高祖微時，聞魏公子賢，及即位，每過大梁，常祀公子，高祖十二年，從击黥布還，為公子置守冢五家，世世以歲四時奉祠。","sortOrder":52},
  {"id":"s_work_nvlt_38_53","chapterId":"ch_work_nvlt_38","text":"又曰：元始四年，詔書祀百辟卿士有益於民者，蜀郡以文翁，九江以召父應，詔書歲時郡二千石率官屬行禮奉祠，信臣家在南陽，亦為立祠。","sortOrder":53},
  {"id":"s_work_nvlt_38_54","chapterId":"ch_work_nvlt_38","text":"又曰：初朱邑且死，嘱其子曰：我故為桐乡啬夫，其民吏愛我，必葬桐乡，後世子孫奉我，不如桐乡民，及死，其子葬之桐乡西郭外，民果共為邑起冢，立祠祭，至今不絕。","sortOrder":54},
  {"id":"s_work_nvlt_38_55","chapterId":"ch_work_nvlt_38","text":"《東觀漢記》曰：桓谭，字君山，沛人，章帝元和中，行巡狩至沛，令使者祠谭家，乡里甚榮之。","sortOrder":55},
  {"id":"s_work_nvlt_38_56","chapterId":"ch_work_nvlt_38","text":"又曰：永平二年十一月，詔京兆右扶風，以中牢祀萧何霍光，出郡錢穀，給萧何子孫，在三里內者，悉令侍祠。","sortOrder":56},
  {"id":"s_work_nvlt_38_57","chapterId":"ch_work_nvlt_38","text":"又曰：皇帝立黃老祠躍［《太平御覽》五百二十六作濯。］龍中，為壇，采色眩曜。","sortOrder":57},
  {"id":"s_work_nvlt_38_58","chapterId":"ch_work_nvlt_38","text":"《漢舊儀》曰：皇帝祭天，紫壇帷幄，高皇帝配天，後［《初學記》十三，太平御覽五百二十六作居。］堂下西乡，绀席也。","sortOrder":58},
  {"id":"s_work_nvlt_38_59","chapterId":"ch_work_nvlt_38","text":"《左傳》曰：龍見而雩，［旱祭也，祈雨為雩。］雪霜風雨之灾則禜之。","sortOrder":59},
  {"id":"s_work_nvlt_38_60","chapterId":"ch_work_nvlt_38","text":"【文】魏武帝祠太尉乔玄墓文曰：昔以幼年，逮升堂室，增榮益觀，皆由奖助，士死知己，懷此無忘。又承從容要誓，徂逝之後，路有經由，不以斗酒只雞，過相沃酹，車過三步，腸［魏志一註作腹。］痛勿怪，雖臨時戲笑之言，非至親之篤好，夫何肯為此辭哉。","sortOrder":60},
  {"id":"s_work_nvlt_38_61","chapterId":"ch_work_nvlt_38","text":"晉潘嶽為諸婦祭庾新婦文曰：潛形幽榇，寧神舊宇，室虛風生，床尘帷舉，自我不見，載離寒暑，雖則乖隔，哀亦時叙，啟殯今夕，祖行明朝，雨絕華庭，埃滅大宵，俪執箕帚，偕奉夕朝，仿佛未行，顧瞻弗獲，伏膺飲淚，感今懷昔，懷昔伊何，祁祁娣姒，感今伊何，冥冥吾子，形未废目，音猶在耳。","sortOrder":61},
  {"id":"s_work_nvlt_38_62","chapterId":"ch_work_nvlt_38","text":"晉殷闡祭王東亭文曰：以少牢之奠，敬荐東亭王侯之靈，蓋聞朗鑒不尘，精金能照，君以珪璋，資以明要，少長風流，舉契理調，事扰皇家，道在君子，亮誠外內，寄心萬里，契同風雲，義貫終始，自昔索居，荏苒於茲，五載不觌，何日不思，呜呼若人，奄隨化遷，古之遺愛，猶或興言，承凶怆痛，慨然留連。","sortOrder":62},
  {"id":"s_work_nvlt_38_63","chapterId":"ch_work_nvlt_38","text":"晉殷允祭徐孺子文曰：惟豫章太守殷君，謹奠漢故聘士豫章徐先生，惟君資純玄粹，含真太和，卓爾高尚，道映南嶽，逍遙環堵，萬物不幹其志，負褐行吟，軒冕不易其樂，時携虛榻，佇金蘭之眷，千里命契，寄生刍之詠，非夫超悟身名，遁世無悶者，孰若是乎，夫誠素自中，微物為重，蘋藻是歆，實過牲牢。","sortOrder":63},
  {"id":"s_work_nvlt_38_64","chapterId":"ch_work_nvlt_38","text":"晉王珣祭徐聘士文曰：豫章徐先生，陶精太和，誕膺一德，藏器高栖，確爾特立，貞一足以製群動，純本足以息浮末，宣尼有言，不事王侯，高尚其事，若先生者，抑亦當之矣，限茲遐路，無由造敬，系佇靈宇，乃情依依，故貢薄祠，昭述宿心，神而有靈，傥垂尚饗。","sortOrder":64},
  {"id":"s_work_nvlt_38_65","chapterId":"ch_work_nvlt_38","text":"晉周穎文祭梁鸿文曰：晉隆安四年，陳郡周穎文，以蕰藻行潦，祠於梁先生之墓，夫子邁志箕穎，尘垢雕俗，骨秀風霜，性淳寡欲，娶待偕隱之俪，文絕陪臣之錄，遂負策周魯之郊，逆旅吳會之阿，可謂高奇絕倫，孤生莫和者也，後學撫牍，得人在文，忽以知命，而展其墳，芒芒積草，有馥餘芬，昔先生過延陵而想季，經海隅而感連，苟踐跡而趣合，亦斷金於當年。","sortOrder":65},
  {"id":"s_work_nvlt_38_66","chapterId":"ch_work_nvlt_38","text":"宋王僧遠祭顏延之文曰：氣高叔夜，方嚴仲舉，逸翮獨征，孤風絕侣。","sortOrder":66},
  {"id":"s_work_nvlt_38_67","chapterId":"ch_work_nvlt_38","text":"宋陶潛自祭文曰：歲惟丁未，律中無射，天寒夜長，風氣萧索，鸿雁於征，草木黃落，陶子將辭逆旅之馆，永歸本宅，故人凄其相悲，同祖行於今夕，自餘為人，逢運之貧，箪飄屢罄，絺绤冬陳，已達運命，畴能罔眷，餘今斯化，可以無恨，寿涉百齡，身慕肥遁，從老得終，奚所复恋，葬之中野，以安其魂，寂寂我行，萧萧墓門，奢恥宋臣，俭笑王孫，匪貴前譽，孰重後歌，人生實難，死如之何。","sortOrder":67},
  {"id":"s_work_nvlt_38_68","chapterId":"ch_work_nvlt_38","text":"宋謝延之祭屈原文曰：蘭薰而摧，玉貞則折，物忌堅芳，人讳明絜，曰若先生，逢辰之缺。","sortOrder":68},
  {"id":"s_work_nvlt_38_69","chapterId":"ch_work_nvlt_38","text":"齊卞伯玉祭孫叔敖文曰：謹以醴羞，祭楚令尹孫君之靈，眇眇千載，悠悠舒荆，理無不通，事隔者形，尚想清尘，承風效誠，超超夫子，淡矣道情，自心伊貴，人爵靡婴，芳風如箫，清响如埙，景矣行役，言戾豫方，侧聞夫子，讬憤睢陽，靈封頹墓，丘塋榛荒，幽幽神道，為有為亡，徘徊永念，怆矣其傷。","sortOrder":69},
  {"id":"s_work_nvlt_38_70","chapterId":"ch_work_nvlt_38","text":"齊謝朓為諸娣祭阮夫人文曰：婉娩嫔德，幽閒婦性，眄史弘箴，陳詩成詠，嘉言足題，清暉可映，契闊未幾，音尘如昨，中景遽傾，芳荍先落，畴日交觴，享也虛荐，帶上先結，握中遺扇，迸淚失聲，潺湲如霰。","sortOrder":70},
  {"id":"s_work_nvlt_38_71","chapterId":"ch_work_nvlt_38","text":"齊孔稚珪祭外兄張長史文曰：惟君之德，高明秀挺，浩汗深度，昂藏風領，學不師古，因心則睿，筌蹄象繇，糠秕莊惠，吾與夫子，分协芳金，凭風共酒，藉月同琴。","sortOrder":71},
  {"id":"s_work_nvlt_38_72","chapterId":"ch_work_nvlt_38","text":"梁簡文帝祭戰亡者文曰：降夫既旋，功臣又賞，班荷元勋，蘇逢漏網，校尉霑榮，屬國蒙奖，獨念斷魂，長畢灰壤，膏原染刃，委骨埋泉，徒聞身没，詎辯名傳。","sortOrder":72},
  {"id":"s_work_nvlt_38_73","chapterId":"ch_work_nvlt_38","text":"梁徐悱妻劉氏祭夫文曰：維梁大同五年，新婦謹荐少牢於徐府君之靈曰：惟君德爰禮智，才兼文雅，學比山成，辯同河泻，明經擢秀，光朝振野，調逸許中，聲高洛下，含潘度陆，超終邁贾，二儀既肇，判合始分，簡賢依德，乃隸夫君，外治徒奉，內佐無聞，幸移蓬性，頗習蘭薰，式傳琴瑟，相酬典墳，辅仁難验，神情易促，雹碎春紅，霜雕夏绿，躬奉正衾，親觀啟足，一見無期，百身何贖，呜呼哀哉，生死雖殊，情親猶一，敢遵先好，手調薑橘，素俎空乾，奠觴徒溢，昔奉齊眉，異於今日，從軍暫別，且思樓中，伯遊未反，尚比飛蓬，如當此訣，永痛無窮，百年何幾，泉穴方同。","sortOrder":73},
  {"id":"s_work_nvlt_38_74","chapterId":"ch_work_nvlt_38","text":"陳沈炯祭梁吳郡袁府君文曰：夫宮鳴徵應，响韻相趨，桂馥蘭芬，期臭在斯，道合一朝，豈忘千載，日者明德世彦，振纓王室，坐嘯大邦，顯治巨麗，竊以不敏，出宰句吳，上郡下邑，都城接雉，雖王事靡盬，無失豫遊，窥洞庭於五湖，登姑蘇於九曲，身後之事，一至於斯，今者長樂未央，已夹樗里之墓，公宮魯库，非复少昊之墟，成土一棺，未知何讬，解劍絮漿，轉增歔欷。","sortOrder":74},
  {"id":"s_work_nvlt_38_75","chapterId":"ch_work_nvlt_38","text":"◇郊丘","sortOrder":75},
  {"id":"s_work_nvlt_38_76","chapterId":"ch_work_nvlt_38","text":"《爾雅》曰：祭天曰燔柴，祭地曰瘞埋。","sortOrder":76},
  {"id":"s_work_nvlt_38_77","chapterId":"ch_work_nvlt_38","text":"《廣雅》曰：圓丘太壇祭天，方泽太折祭地。","sortOrder":77},
  {"id":"s_work_nvlt_38_78","chapterId":"ch_work_nvlt_38","text":"《周書》曰：乃兆乎南郊，以祀上帝，配後稷農皇［按前祭祀篇引作星。］先王與食。","sortOrder":78},
  {"id":"s_work_nvlt_38_79","chapterId":"ch_work_nvlt_38","text":"《周官》曰：大宗伯掌天神之禮，以禋祀祀昊天上帝，以實柴祀日月星辰，以槱燎祀司中司命風師雨師。","sortOrder":79},
  {"id":"s_work_nvlt_38_80","chapterId":"ch_work_nvlt_38","text":"又曰：蒼璧禮天，黃琮禮地。","sortOrder":80},
  {"id":"s_work_nvlt_38_81","chapterId":"ch_work_nvlt_38","text":"又曰：四圭有邸，以祀天，旅上帝，兩圭有邸，以祀地，旅四望，大司樂奏黃鍾，歌大呂，舞雲門，以祀天神，［謂五帝及天(周禮註天字無。)日月星辰之，(周禮註作也。)王者各以夏正月祀其受命之帝於南郊也。］奏太蔟，歌應鍾，舞鹹池，以祭地祇於北郊，謂地神及社稷也，［按本句亦周禮註文，當作夹註。］又曰：凡樂，圜鍾為宮，黃鍾為角，太蔟為徵，姑洗為羽，雷鼓雷鼗，孤竹之管，雲和之琴瑟，雲門之舞，冬日至，於地上之圓丘奏之，若樂六变，天神皆降，可得而禮矣，凡樂函鍾為宮，太蔟為角，姑洗為徵，南呂為羽，靈鼓靈鼗，孫竹之管，空桑之琴瑟，鹹池之舞，夏日至，於泽中之方丘奏之，若樂八变，則地祇皆出，可得而禮矣。","sortOrder":81},
  {"id":"s_work_nvlt_38_82","chapterId":"ch_work_nvlt_38","text":"《禮記》曰：郊之祭，迎長日之至，大報天而主日也，兆於南郊，就陽位也，扫地而祭，於其质也，器用陶匏，以象天地之性也，於郊故謂之郊。","sortOrder":82},
  {"id":"s_work_nvlt_38_83","chapterId":"ch_work_nvlt_38","text":"又曰：祭帝於郊，所以定天位也。","sortOrder":83},
  {"id":"s_work_nvlt_38_84","chapterId":"ch_work_nvlt_38","text":"又曰：成王封周公於魯，命魯公祀周公以天子之禮樂，是以魯君孟春乘大辂，戴弧韣，旂十有二旒，日月之章，祀帝於郊，配以後稷，天子之禮也。","sortOrder":84},
  {"id":"s_work_nvlt_38_85","chapterId":"ch_work_nvlt_38","text":"《毛詩》曰：昊天有成命，郊祀天地也。","sortOrder":85},
  {"id":"s_work_nvlt_38_86","chapterId":"ch_work_nvlt_38","text":"公羊傳曰：祭者，荐其時也，荐其義也，非享味也。","sortOrder":86},
  {"id":"s_work_nvlt_38_87","chapterId":"ch_work_nvlt_38","text":"又曰：山川有能润乎百里者，天子秩而祭之，《漢書》曰：成帝初即位，丞相御史大夫桓谭奏言，帝王之事，莫大於承天之序，承天之序，莫重於郊祀，故聖王盡心極慮，以建其製，祭天於南郊，就陽之義，瘞地於北郊，則陰之象也。","sortOrder":87},
  {"id":"s_work_nvlt_38_88","chapterId":"ch_work_nvlt_38","text":"又曰：高帝入關，問秦祀何帝，曰白青黃赤四帝，上曰：天有五帝而四何，莫知其說，上曰：五待我，為立黑帝，祀曰黑畤。","sortOrder":88},
  {"id":"s_work_nvlt_38_89","chapterId":"ch_work_nvlt_38","text":"《漢舊儀》曰：漢法，三歲一祭於雲陽宮甘泉壇，以冬至日祭天，天神下，三歲一祭地於河東汾陰後土宮，以夏至日祭地，地神出，祭五帝於雍畤。","sortOrder":89},
  {"id":"s_work_nvlt_38_90","chapterId":"ch_work_nvlt_38","text":"又曰：祭天用六采綺席，六重，上一丈，中一幅四周緣之，玉幾玉飾器。","sortOrder":90},
  {"id":"s_work_nvlt_38_91","chapterId":"ch_work_nvlt_38","text":"又曰：桓［《太平御覽》五百二十七作皇，下同。］帝祭天，居玄雲［御覽作雲陽。］宮，斋百日，上甘泉通天台，高三十丈，以候天神之下，見如流火，舞女童三百人，皆年八歲，天神下壇所，舉烽火，桓帝就竹宮中，不至壇所，甘泉台去長安三百里，望見長安成，［御覽作城。］帝［御覽帝上有黃字。］已來所祭天之圓丘也。","sortOrder":91},
  {"id":"s_work_nvlt_38_92","chapterId":"ch_work_nvlt_38","text":"又曰：祭地河東汾陰後土宮，宮曲入河，古之祭地泽中方丘也，禮儀如祭天。","sortOrder":92},
  {"id":"s_work_nvlt_38_93","chapterId":"ch_work_nvlt_38","text":"《五經通義》曰：王者所祭天地何，王者父事天，母事地，故以子道也，祭日以丁與辛何，丁者，反覆自丁寧也，辛者，自克辛也。","sortOrder":93},
  {"id":"s_work_nvlt_38_94","chapterId":"ch_work_nvlt_38","text":"《後漢書》曰：靈帝建寧二年，迎氣黃郊，遂於洛水西桥，逢暴風雨，导從滷部車或發蓋，百官霑濡，還不至郊。","sortOrder":94},
  {"id":"s_work_nvlt_38_95","chapterId":"ch_work_nvlt_38","text":"贺循上郊壇製度曰：漢舊儀，南郊圓壇八陛，於宮南七里，北郊方壇四陛，於城北四里，依漢故事，柴於壇二十步，高二丈，大二丈。","sortOrder":95},
  {"id":"s_work_nvlt_38_96","chapterId":"ch_work_nvlt_38","text":"【賦】晉郭璞南郊賦曰：於是時惟青陽，日在方旭，我後將受命靈壇，乃改步而鳴玉，升金軒，撫太仆，扬六鸞，齊八騄，列五幡於一元兮，靡日月乎黃屋，矯陵乌以侦候兮，整豹尾於後屬，爾乃造曠場，戾壇庭，百寮山立，萬乘雲萦，延祝史，肆玉牲，登圓丘，揖太清，禮群望，告皇靈，天澄其氣，日朗其精，飛廉鼓舞於八維兮，丰隆击節於九冥，祝融穆清而肅侍兮，陽侯澹以中停，郊寰之內，區域之外，雕題卉服，被發左帶，駿奔在壇，不期而會，瓘瓘群辟，蚩蚩黎庶，翘懷聖猷，思我王度，事崇其簡，服尚其素，化無不融，萬物自鼓，振西北之絕維，隆東南之桡柱，廓清紫衢，電扫神宇，風馬桂林，抗旌林圃，五嶽不足以題其勋，九韶不足以贊其舞。","sortOrder":96},
  {"id":"s_work_nvlt_38_97","chapterId":"ch_work_nvlt_38","text":"【頌】梁簡文帝南郊頌曰：臣聞唯天為大，聖人敬其德，知幾其神，至人契其道，故龍宮弱言之後，合揆於蒼旻，鳥紀垂衣之君，昭格於上帝，皇帝之御天下也，緯天維，理地軸，移浇風於末俗，反淳正於區中，化不言而先顯，教不言而已肅，九垓同軌，四海無波，尘清世晏，蒼兕無所用其武功，運謐時雍，鴛鷺鹹併脩其文德，玉門罢候，紫塞沉烽，畫一之政，萬代表於時和，三章之律，百姓沐於仁寿，於是隆光之地，日浴之乡，紫舌黃支，頭飛鼻飲，自西自南，無思不服，由是嘉祥被，眾瑞發，金人泽馬，丹甑玉雞，三角九尾，四肩六足，參差於郊藪，布濩於宮闈，乃以恭肅神祇，理通孝敬，江左以來，爽垲未辟，爰命將作，揆日載營，三靈葉响，百工鹹事，宛如神造，俨類仙居，五達四通，廓郊弥泽，南瞻重嶽，北眺芒嶺，東臨灞浐，西望舊丰，紆餘委蛇，丘陵起伏，澎湃峣屼，山川異態，飛梁邃宇，洞燭空懸，紫殿仙宮，霞褰鳥翥。","sortOrder":97},
  {"id":"s_work_nvlt_38_98","chapterId":"ch_work_nvlt_38","text":"【表】梁簡文帝上南郊頌表曰：雖周郊南甸，宗伯之官徒設，漢興北畤，夤恪之道未隆，而體元含極，先後弗违，典盛望禋，理通孝敬，絜靜之禮載光，禘郊之風斯洽，昔東平琅邪，著藻炎德，臨淄中山，摛文魏美。","sortOrder":98},
  {"id":"s_work_nvlt_38_99","chapterId":"ch_work_nvlt_38","text":"【啟】梁元帝慶南郊啟曰：大裘而冕，陶匏以质，黃鍾既奏，雲門斯舞，樂諧六变，歌陳九德，感天動神，式展誠敬。","sortOrder":99},
  {"id":"s_work_nvlt_38_100","chapterId":"ch_work_nvlt_38","text":"◇宗廟","sortOrder":100},
  {"id":"s_work_nvlt_38_101","chapterId":"ch_work_nvlt_38","text":"《尚書大傳》曰：廟者，貌也，其以貌言之也。","sortOrder":101},
  {"id":"s_work_nvlt_38_102","chapterId":"ch_work_nvlt_38","text":"《釋名》曰：宗，尊也，廟，貌也，先祖形貌所在也。","sortOrder":102},
  {"id":"s_work_nvlt_38_103","chapterId":"ch_work_nvlt_38","text":"《禮記》曰：天子七廟，三昭三穆，與太祖之廟而七，諸侯五廟，二昭二穆，與太祖之廟而五，大夫三廟，一昭一穆，與太祖之廟而三，士一廟，庶人祭於寢，遠廟為祧，去祧為壇，去壇為墠，去墠為鬼，自祧以下皆廟。","sortOrder":103},
  {"id":"s_work_nvlt_38_104","chapterId":"ch_work_nvlt_38","text":"又曰：凡祭宗廟之禮，牛曰一元大武，豕曰刚鬛，豚曰腯肥，羊曰柔毛，雞曰翰音，犬曰羹獻，雉曰疏趾，兔曰明视，｛巩言｝脯曰尹祭，魚曰商祭，鮮魚曰脡祭，水曰清涤，酒曰清酌，黍曰芗合，稷曰明粢，稻曰嘉疏，韭曰丰本，鹽曰鹹鹾，玉曰嘉玉，幣曰量幣。","sortOrder":104},
  {"id":"s_work_nvlt_38_105","chapterId":"ch_work_nvlt_38","text":"又曰：當七廟五廟之無虛主，唯祫祭於祖，為無主爾。","sortOrder":105},
  {"id":"s_work_nvlt_38_106","chapterId":"ch_work_nvlt_38","text":"又曰：夏六月，以禘禮祀周公於太廟，尊用玉豆雕篹，爵用玉盏。","sortOrder":106},
  {"id":"s_work_nvlt_38_107","chapterId":"ch_work_nvlt_38","text":"《周禮註》：五歲一禘，三歲一祫。","sortOrder":107},
  {"id":"s_work_nvlt_38_108","chapterId":"ch_work_nvlt_38","text":"又曰：凡賓客獻瑤爵，皆贊。","sortOrder":108},
  {"id":"s_work_nvlt_38_109","chapterId":"ch_work_nvlt_38","text":"又曰：凡灌玉，濯之陳之，以贊祼事，註雲，灌玉，圭瓒也。","sortOrder":109},
  {"id":"s_work_nvlt_38_110","chapterId":"ch_work_nvlt_38","text":"《儀禮》曰：始虞用柔日，哀某敢用玉［儀禮士虞禮玉字無。］絜桂［儀禮作牲。］刚鬛香合嘉荐。","sortOrder":110},
  {"id":"s_work_nvlt_38_111","chapterId":"ch_work_nvlt_38","text":"《說文》曰：宗廟之木主，名曰祏。","sortOrder":111},
  {"id":"s_work_nvlt_38_112","chapterId":"ch_work_nvlt_38","text":"《白虎通》曰：言神無所依據，孝子以主繼心。","sortOrder":112},
  {"id":"s_work_nvlt_38_113","chapterId":"ch_work_nvlt_38","text":"又曰：位尊盛德，所及弥遠，謂之禘祫何，禘之為言讓［白虎通宗廟篇作諦。］也，序昭穆，禘父子也，祫合也。","sortOrder":113},
  {"id":"s_work_nvlt_38_114","chapterId":"ch_work_nvlt_38","text":"五經要義曰：木主之状，四方，穿中央，以達四方，天子長尺二寸，諸侯長尺，皆刻謚於其背。","sortOrder":114},
  {"id":"s_work_nvlt_38_115","chapterId":"ch_work_nvlt_38","text":"挚虞要訣註曰：凡廟之主，藏於戶外北牖下，有石函，故名宗祏。","sortOrder":115},
  {"id":"s_work_nvlt_38_116","chapterId":"ch_work_nvlt_38","text":"《五經異義》曰：謹按叔孫通宗廟有日祭之禮，古而然也，三歲一祫，周禮也，一禘，疑先王禮也。","sortOrder":116},
  {"id":"s_work_nvlt_38_117","chapterId":"ch_work_nvlt_38","text":"《論語》曰：夏後氏以松，殷人以柏，周人以栗，栗，敬也，使人謹敬也。","sortOrder":117},
  {"id":"s_work_nvlt_38_118","chapterId":"ch_work_nvlt_38","text":"《詩》曰：閟宮有侐，註雲，閟禘，禘陽之盛也，薑嫄神所依，故曰神宮。","sortOrder":118},
  {"id":"s_work_nvlt_38_119","chapterId":"ch_work_nvlt_38","text":"又曰：清廟，祀文王也，周公既成洛邑，率以祀文王焉，清者言有清明之德。","sortOrder":119},
  {"id":"s_work_nvlt_38_120","chapterId":"ch_work_nvlt_38","text":"又曰：有壬有林，錫爾純嘏，純，大也，嘏謂尸與主人以福也。","sortOrder":120},
  {"id":"s_work_nvlt_38_121","chapterId":"ch_work_nvlt_38","text":"《漢書》曰：廟所以藏主，則列昭穆。","sortOrder":121},
  {"id":"s_work_nvlt_38_122","chapterId":"ch_work_nvlt_38","text":"《續漢書》曰：祫，合也，毀廟之主，合食於太祖也，禘以四月，祫以十月，四月陽氣在上，陰氣在下，正尊卑之義，十月五穀登，故骨肉合聚飲食。","sortOrder":122},
  {"id":"s_work_nvlt_38_123","chapterId":"ch_work_nvlt_38","text":"《漢書［《初學記》十三作舊。］儀》曰：子為昭，孫為穆，昭西面，穆東面，三年大祫，諸帝以昭穆坐於高廟。","sortOrder":123},
  {"id":"s_work_nvlt_38_124","chapterId":"ch_work_nvlt_38","text":"又曰：皇帝會諸侯，酎金以上計儀，設九賓陪位也。","sortOrder":124},
  {"id":"s_work_nvlt_38_125","chapterId":"ch_work_nvlt_38","text":"《國語》曰：甸服者祀，日祭月祀，先王之訓者也。","sortOrder":125},
  {"id":"s_work_nvlt_38_126","chapterId":"ch_work_nvlt_38","text":"張方《楚國先賢傳》曰：古者先王日祭月享，時類歲祀，諸侯舍日，卿大夫舍月，士庶人舍時。","sortOrder":126},
  {"id":"s_work_nvlt_38_127","chapterId":"ch_work_nvlt_38","text":"鍾離意別傳曰：意為魯相，修孔子廟，孔子堂道有瓮，意召守廟孔訢問曰：此何等瓮，訢曰：夫子瓮背皆有書，故自夫子亡後，無敢發者，意乃發，得素書焉。","sortOrder":127},
  {"id":"s_work_nvlt_38_128","chapterId":"ch_work_nvlt_38","text":"吳錄《地理志》曰：會稽有禹廟，始皇配食，王朗為太守，黜之。","sortOrder":128},
  {"id":"s_work_nvlt_38_129","chapterId":"ch_work_nvlt_38","text":"晉諸公贊曰：王浚，字彭祖，為幽州刺史，尋洛陽破，浚承製建行台，以宗廟焚毀，設墠，望祀七室及功臣配食者。","sortOrder":129},
  {"id":"s_work_nvlt_38_130","chapterId":"ch_work_nvlt_38","text":"《楚辭·天問序》曰：屈原放逐，忧心愁悴，彷徨山泽，經歷陵陆，仰天叹息，楚有先王之廟，及公卿祠堂，圖畫天地山川神靈，及古賢怪物所行事，周流罢倦，休息其下，仰見圖畫，因書其壁，呵而問之，以泄憤，寫愁思。","sortOrder":130},
  {"id":"s_work_nvlt_38_131","chapterId":"ch_work_nvlt_38","text":"【詩】梁簡文帝赛漢高廟詩［按此及下庾信，張正見三詩皆見後，此重出，冯校本無。］曰：日正山無影，威斜漢屢回，瞻流如地望，崑崙匹天台。","sortOrder":131},
  {"id":"s_work_nvlt_38_132","chapterId":"ch_work_nvlt_38","text":"庾信至老子廟詩曰：三門臨苦縣，九井對靈溪，盛丹須竹節，量藥用刀圭。","sortOrder":132},
  {"id":"s_work_nvlt_38_133","chapterId":"ch_work_nvlt_38","text":"張正見經季子廟詩曰：延州高讓遠，傳芳世祀移，地絕貴金路，松悲懸劍枝，野藤侵沸井，山雨濕苔碑。","sortOrder":133},
  {"id":"s_work_nvlt_38_134","chapterId":"ch_work_nvlt_38","text":"宋謝瞻經張子房廟詩曰：伊人鹹代工，聿來扶興王，婉婉幕中畫，暉暉天業昌，鸿門消薄蚀，垓下陨欃槍，爵仇建萧宰，定都護储皇，肇允契幽叟，翻飛指帝乡，惠心奋千祀，清埃播無疆。","sortOrder":134},
  {"id":"s_work_nvlt_38_135","chapterId":"ch_work_nvlt_38","text":"宋鄭鮮之行經張子房廟詩曰：七雄裂周紐，道盡鼎亦淪，長風晦崑溟，潛龍動泗濱，紫煙翼丹虬，靈媪悲素鱗，宋范泰經漢高廟詩曰：嘯吒英豪萃，指捴五嶽分，乘彼道消势，遂廓宇宙氛，重瞳豈不伟，奋臂騰群雄，壮力拔高山，猛氣烈迅風，恃勇終必撓，道勝業自隆。","sortOrder":135},
  {"id":"s_work_nvlt_38_136","chapterId":"ch_work_nvlt_38","text":"齊謝朓赛敬亭廟喜雨詩曰：執玉朝群帝，樽桂迎東皇，排雲接孔［本集作虬。］蓋，蔽日下霓裳，會舞紛瑤席，安歌繞鳳梁，百味芬綺帳，四望霑羽觴。","sortOrder":136},
  {"id":"s_work_nvlt_38_137","chapterId":"ch_work_nvlt_38","text":"梁簡文帝和萧東陽祀七里廟詩曰：萬里實幽宗，三神亦天構，豈謂木石精，斯乃山川守，遠來太白旗，遙徵青鳥候，以茲弗敬怠，方知教應否。","sortOrder":137},
  {"id":"s_work_nvlt_38_138","chapterId":"ch_work_nvlt_38","text":"又漢高廟赛神詩曰：玉轪朝行動，閶阖旦應开，白雲蒼梧上，丹霞鹹陽來，日正山無影，城斜漢屢回，瞻流如地脈，望嶺匹天台，欲袪九秋恨，聊舉十千杯。","sortOrder":138},
  {"id":"s_work_nvlt_38_139","chapterId":"ch_work_nvlt_38","text":"梁元帝祀伍［原作五，據冯校本改。］相廟詩曰：石城寧足拒，金陣詎能追，楚關开六塞，吳兵入九围，山水猶萦帶，城池失是非，空餘寿宮在，日暮舞靈衣。","sortOrder":139},
  {"id":"s_work_nvlt_38_140","chapterId":"ch_work_nvlt_38","text":"梁庾肩吾漢高廟詩曰：昔作唐山曲，今承紫貝壇，寧知臨楚岸，非复望長安，尘飛遠騎没，日徙半峰寒。","sortOrder":140},
  {"id":"s_work_nvlt_38_141","chapterId":"ch_work_nvlt_38","text":"又亂後經夏禹廟詩曰：金簡泥初發，龍門凿始通，配天不失舊，為魚微此功，林堂上偃蹇，山殿下穹隆，侵雲似天闕，照水類河宮，神來导赤豹，仙去擁飛鸿，松龛撤暮俎，棗径落寒丛，仙舟還入鏡，玉軸更乘空，去國嗟行邁，離居泣轉蓬，月起吳山北，星臨天漢中，申胥猶有志，荀息本懷忠，待見欃槍滅，歸來松柏桐。","sortOrder":141},
  {"id":"s_work_nvlt_38_142","chapterId":"ch_work_nvlt_38","text":"周庾信至老子廟詩曰：三門臨苦縣，九井對靈溪，盛丹須竹節，量藥用刀圭，行當別關吏，直向流沙西。","sortOrder":142},
  {"id":"s_work_nvlt_38_143","chapterId":"ch_work_nvlt_38","text":"又西門豹廟詩曰：君子為利博，達人树德深，蘋藻由斯荐，樵蘇幸未侵，恭聞正直祀，良識佩韦心，容范雖年代，徽猷若可尋，菊花隨酒馥，槐影向窗臨，鶴飛疑逐舞，魚驚似聽琴，漳流鳴磴石，銅爵影秋林。","sortOrder":143},
  {"id":"s_work_nvlt_38_144","chapterId":"ch_work_nvlt_38","text":"陳陽慎從駕祀麓山廟詩曰：聖德忧民暇，麾旆謁山靈，畫航泛北渚，文馬侍東平，春浦戊誕照，寒林鐃吹鳴，依俙長安驿，萧條都尉城，井泉能共動，江帆得分行，窗幽細網合，階靜落花明，簷巢始入燕，軒树已遷湋，菲菲蘭俎馥，淡淡桂樽清，銀堂日影盡，玉座舞衣輕。","sortOrder":144},
  {"id":"s_work_nvlt_38_145","chapterId":"ch_work_nvlt_38","text":"陳張正見行經季子廟詩曰：延州高讓遠，傳芳世祀移，地絕遺金路，松悲懸劍枝，野藤侵沸井，山雨濕苔碑，別有觀風處，樂奏無人知。","sortOrder":145},
  {"id":"s_work_nvlt_38_146","chapterId":"ch_work_nvlt_38","text":"隋江總卞山楚廟詩曰：蘋藻祈明德，倚棹息巖阿，忽聽鳥鳴曙，非复楚宮歌，閒階薙宿荠，古木斷懸萝，帷堂寂易晚，桴鼓自相和，威祀流百世，英威言幾何。","sortOrder":146},
  {"id":"s_work_nvlt_38_147","chapterId":"ch_work_nvlt_38","text":"又攝官梁小廟詩曰：畴昔遊衣所，今日荐櫻時，憲章誠有革，歲月遂難思，故人獨之子，官聯更在茲，虛簷靜暮雀，洞戶映光絲，平生复能幾，語事必傷悲。","sortOrder":147},
  {"id":"s_work_nvlt_38_148","chapterId":"ch_work_nvlt_38","text":"【頌】魏陳王曹植孔子廟頌曰：修复舊廟，丰其甍宇，莘莘學徒，爰居爰處，王教既備，群小遄沮，魯道以興，永作憲矩，洪聲登遐，神祇來祜，休徵雜沓，瑞我邦家，內光區域，外被荒遐。","sortOrder":148},
  {"id":"s_work_nvlt_38_149","chapterId":"ch_work_nvlt_38","text":"【文】宋謝惠連祭禹廟文曰：謹遣左曹掾，奉水土之羞，敬荐夏帝之靈，咨聖繼天，載誕英徽，克明克哲，知章知微，運此宏謨，恤彼民忧，身勞五嶽，形疲九州，呱呱弗顧，虔虔是钦，物貴尺璧，我重寸陰，乃錫玄圭，以告成功，虞數既改，夏德乃隆，臨朝總政，巡國觀風，淹留稽嶺，乃徂行宮，恭司皇役，敬屬暉融，神且略荐，乃昭其忠。","sortOrder":149},
  {"id":"s_work_nvlt_38_150","chapterId":"ch_work_nvlt_38","text":"梁王僧孺武帝祭禹廟文曰：惟帝禀圖上昊，貽則下民，五聲窮聽，四乘兼往，輕璧惜景，既舍冠履，愛人忘我，不顧胼胝，下車以泣，事深罪己，凭舟靡懼，義存拯物，盛業方來，遺神如在，愛被崑虫，理有好生之德，事安菲素，固無厚味之求，是用黍稷非馨，蘋蘩以荐，克誠斯饗，凭心可答。","sortOrder":150},
  {"id":"s_work_nvlt_38_151","chapterId":"ch_work_nvlt_38","text":"◇明堂","sortOrder":151},
  {"id":"s_work_nvlt_38_152","chapterId":"ch_work_nvlt_38","text":"《釋名》曰：明堂，明［《釋名》五，《初學記》十三，《太平御覽》五百三十三作堂。］堂高顯貌也。","sortOrder":152},
  {"id":"s_work_nvlt_38_153","chapterId":"ch_work_nvlt_38","text":"《大戴禮》曰：明堂者，凡九室，一室而有四戶八牖，以茅蓋屋，上圓下方，所以明諸侯尊卑也，外水名曰辟雍，總三十六戶，七十二牖。","sortOrder":153},
  {"id":"s_work_nvlt_38_154","chapterId":"ch_work_nvlt_38","text":"《周禮》曰：夏後氏大室，殷人重屋，周人明堂，度有九尺之筵。","sortOrder":154},
  {"id":"s_work_nvlt_38_155","chapterId":"ch_work_nvlt_38","text":"《周書》曰：明堂方一百一十二尺，室中方六十尺，牖高三尺，門方十六尺，東方曰青陽，南方曰明堂，西方曰總章，北方曰玄堂，中央曰太廟，左為左个，右為右个，五經要義，以大室經為太室，［《初學記》十三作以太廟為太室，此有訛衍。］《孝經援神契》曰：明堂者，天子布政之宮，上圓下方，八窗四達，在國之陽。","sortOrder":155},
  {"id":"s_work_nvlt_38_156","chapterId":"ch_work_nvlt_38","text":"桓谭《新論》曰：王者造明堂，上圓下方，以象天地，為四方堂，各從其色，以郊四方，天稱明，故命曰明堂。","sortOrder":156},
  {"id":"s_work_nvlt_38_157","chapterId":"ch_work_nvlt_38","text":"黃圖曰：明堂者，明天地之堂也，所以順四時，行月令，宗祀先王，祭五帝，故謂之明堂，辟雍圓如璧，雍所以異水名同事，［《初學記》十三作雍以水，異名同事，此有衍倒。］其實一也。","sortOrder":157},
  {"id":"s_work_nvlt_38_158","chapterId":"ch_work_nvlt_38","text":"《禮記》曰：昔者周公朝諸侯於明堂之位，天子負斧扆，南向而立。","sortOrder":158},
  {"id":"s_work_nvlt_38_159","chapterId":"ch_work_nvlt_38","text":"《三禮圖》曰：明堂者，周製五室，東為木室，南火，西金，北水，土在其中，秦為九室，十二室［《太平御覽》五百三十三室字無。］階，各有所居。","sortOrder":159},
  {"id":"s_work_nvlt_38_160","chapterId":"ch_work_nvlt_38","text":"《尸子》曰：黃帝曰合宮，有虞曰總章，殷人曰陽馆，周人曰明堂。","sortOrder":160},
  {"id":"s_work_nvlt_38_161","chapterId":"ch_work_nvlt_38","text":"《管子》曰：黃帝立明堂之議，舜有告善之旌，湯有總街之匡，武王有靈台之候。","sortOrder":161},
  {"id":"s_work_nvlt_38_162","chapterId":"ch_work_nvlt_38","text":"蔡邕《月令論》曰：明堂者，天子太廟也，所以宗祀而配上帝，明天氣，統萬物也。","sortOrder":162},
  {"id":"s_work_nvlt_38_163","chapterId":"ch_work_nvlt_38","text":"徐虔《明堂議》曰：明堂在國之陽，國門外，一堂五室，四門八階。","sortOrder":163},
  {"id":"s_work_nvlt_38_164","chapterId":"ch_work_nvlt_38","text":"許慎《五經異義》曰：明堂在國之陽，七里之內，八窗四闼，以［《太平御覽》五百三十三作已。］地，就陽位也。","sortOrder":164},
  {"id":"s_work_nvlt_38_165","chapterId":"ch_work_nvlt_38","text":"《五經釋例》曰：告朔行正，謂之明堂，蔡邕禮樂志曰：孝武封岱宗，立明堂於太山汶上。","sortOrder":165},
  {"id":"s_work_nvlt_38_166","chapterId":"ch_work_nvlt_38","text":"《禮論》曰：或以明堂者文王廟，周時往合和，［三字《初學記》十三，太平御覽五百三十三作德泽和洽，此有訛脱。］蒿茂大，以為宮社，［《初學記》，御覽作柱，此訛。］名為蒿宮。","sortOrder":166},
  {"id":"s_work_nvlt_38_167","chapterId":"ch_work_nvlt_38","text":"《禮含文嘉》曰：明堂所以通神靈，感天地，正四時，出教化，崇有德，章有道也。","sortOrder":167},
  {"id":"s_work_nvlt_38_168","chapterId":"ch_work_nvlt_38","text":"《白虎通》曰：禮三老於明堂，所以教諸侯孝，禮五更於太學，所以教諸侯悌。","sortOrder":168},
  {"id":"s_work_nvlt_38_169","chapterId":"ch_work_nvlt_38","text":"《淮南子》曰：古者明堂之製，下之润濕，不能及也，上之霧露，不能入也，所以饗上帝，禮鬼神，示人知節也。","sortOrder":169},
  {"id":"s_work_nvlt_38_170","chapterId":"ch_work_nvlt_38","text":"《家語》曰：孔子觀乎明堂，睹四門之牖，有尧舜桀紂之像，而各有善惡之状，興废之戒焉。","sortOrder":170},
  {"id":"s_work_nvlt_38_171","chapterId":"ch_work_nvlt_38","text":"又曰：周公相成王，抱之而負斧扆，南面以朝諸侯之國焉。","sortOrder":171},
  {"id":"s_work_nvlt_38_172","chapterId":"ch_work_nvlt_38","text":"《吳越春秋》曰：越王召范蠡而問，孤竊自欲以今日一登上明堂，布恩致令，以撫百姓也。","sortOrder":172},
  {"id":"s_work_nvlt_38_173","chapterId":"ch_work_nvlt_38","text":"《漢書》曰：上欲治明堂，未晓其製度，濟南人公玉帶上黃帝時明堂圖，圖中有一殿，四面無壁，以茅蓋屋，屋通水，水圜宮恒，［《太平御覽》五百三十三作垣。］為複道，上有樓，從西面入，名曰崑崙，天子從之。","sortOrder":173},
  {"id":"s_work_nvlt_38_174","chapterId":"ch_work_nvlt_38","text":"又曰：元始五年正月，祫祭明堂，諸侯王列侯宗室子九百餘人助祭，畢，皆益戶賜爵及金帛。","sortOrder":174},
  {"id":"s_work_nvlt_38_175","chapterId":"ch_work_nvlt_38","text":"《東觀漢記》曰：元年營造明堂辟雍靈台，以即明三事不同也，前黃圖雲，同一物也。","sortOrder":175},
  {"id":"s_work_nvlt_38_176","chapterId":"ch_work_nvlt_38","text":"【詩】梁元帝和劉尚書兼明堂斋宮詩曰：质明攝上宰，詰旦乘轺軒，四圭邸蒼玉，六变舞雲門，香浮鬱金酒，煙繞鳳皇樽，新花臨御陌，春色起天園，河間獻樂語，斯道媿能論。","sortOrder":176},
  {"id":"s_work_nvlt_38_177","chapterId":"ch_work_nvlt_38","text":"【銘】後漢李尤明堂銘曰：布政之室，上圓下方，體則天地，在國正陽，窗闼四設流水洋洋，順節行化，各居其房，春恤幼孤，夏進賢良，秋厲武人，冬謹關梁。","sortOrder":177},
  {"id":"s_work_nvlt_38_178","chapterId":"ch_work_nvlt_38","text":"◇辟雍","sortOrder":178},
  {"id":"s_work_nvlt_38_179","chapterId":"ch_work_nvlt_38","text":"《說文》曰：辟雍，天子饗飲處也。","sortOrder":179},
  {"id":"s_work_nvlt_38_180","chapterId":"ch_work_nvlt_38","text":"《五經通義》曰：天子立辟雍者何，所以行禮樂，宣德化，教导天下之人，使為士君子，養三老，事五更，與諸侯行禮之處也。","sortOrder":180},
  {"id":"s_work_nvlt_38_181","chapterId":"ch_work_nvlt_38","text":"又曰：諸侯不得觀四方，故缺東以南，半天子之學，故曰泮宮。","sortOrder":181},
  {"id":"s_work_nvlt_38_182","chapterId":"ch_work_nvlt_38","text":"《禮記》曰：天子辟雍，諸侯曰泮宮。","sortOrder":182},
  {"id":"s_work_nvlt_38_183","chapterId":"ch_work_nvlt_38","text":"《白虎通》曰：天子立辟雍，行禮樂，宣德化，辟者象璧，圓法天，雍之以水，象教化流行。","sortOrder":183},
  {"id":"s_work_nvlt_38_184","chapterId":"ch_work_nvlt_38","text":"桓谭《新論》曰：王者作圓池，如璧形，實水其中，以圜壅之，名曰辟雍，言其上承天地，以班教令，流轉王道，周而复始。","sortOrder":184},
  {"id":"s_work_nvlt_38_185","chapterId":"ch_work_nvlt_38","text":"《續漢書》曰：明帝永平二年，上始率群臣，躬養三老五更於辟雍，行大射之禮。","sortOrder":185},
  {"id":"s_work_nvlt_38_186","chapterId":"ch_work_nvlt_38","text":"《魏志》曰：明帝甘露二年，幸辟雍，命群臣令賦詩。","sortOrder":186},
  {"id":"s_work_nvlt_38_187","chapterId":"ch_work_nvlt_38","text":"【賦】後漢李尤辟雍賦曰：辟雍巖巖，規矩圓方，階序牖闼，双觀四張，流水湯湯，造舟為梁，神聖班德，由斯以匡，王公群後，卿士具集，攒羅鱗次，差池雜遝，延忠信之純一兮，列左右之貂璫，三後八蕃，師尹群卿，加休慶德，稱寿上觴，戴甫垂畢，其儀蹌蹌，是以乾坤所周，八極所要，夷戎蠻羌，儋耳哀牢，重譯响應，抱珍來朝，南金大路，玉象犀龟。","sortOrder":187},
  {"id":"s_work_nvlt_38_188","chapterId":"ch_work_nvlt_38","text":"晉傅玄辟雍乡飲酒賦曰：時皇帝親枉萬乘之尊號，以幸乎辟雍，滷簿齊列，官正其容，乃延卿士，乃命王公，定小會之常儀兮，饗殊俗而見遠邦，揖讓而升，有主有賓，禮雖舊製，其教惟新，若其俎豆有數，威儀翼翼，賓主百拜，貴賤修敕。酒清而不飲，肴乾而不食，及至嘒嘒笙磬，喤喤鍾鼓，琴瑟安歌，德音有叙，樂而不淫，好朴尚古，四坐先迷而後悟，然後知禮教之弘普也。","sortOrder":188},
  {"id":"s_work_nvlt_38_189","chapterId":"ch_work_nvlt_38","text":"【頌】陳徐陵皇太子臨辟雍頌曰：臣聞天大王大，詳於道德之言，天文人文，顯於爻象之說，是以大君革命，黔首所以庇焉，聖人創物，文籍所以生焉，鹹由此道，製為民極，莫不對越上靈，裁成庶類，濟世育德，昭被崑虫，皇帝世膺下武，體資上德，握天鏡而授河圖，執玉衡而運乾象，皇太子耀彼重離，光茲匕鬯，儀天以行三善，俪極以照四方，惟忠惟孝，自家刑國，乃武乃文，化成天下，侍中國子祭酒新安王，宗室羽儀，衣冠准的，惟善為樂，造次必儒，粵以十一年三月二十一日，受詔弘宣，發論語題，攝齊升堂，抠衣即席，對扬天人，开辟大訓，清言既吐，精義入神，副德爰動，音［本集音下有辭字。］鋒起，問難泉涌，辯論纶之異，定倫理之疑，玉振锵锵，雲浮雨布，介王奉系聖蹤，馳辯秀出，信令張禹慚其師法，何晏忸其訓詁，穆穆焉，洋洋焉，此實虞朝之盛德，生民之壮觀者也，臣抑又聞之，魯頌聿興，史克宣其懿，晉雍大啟，王廙逞其詞，所以述休平之風，扬君上之德，輕以下才，敢為頌曰：皇運勃啟，膺圖受命，紫蓋東臨，黃旌南映，積仁累德，重明叠聖，四海無浪，三階已平，储駕戾止，和鸞有聲，弘風講肆，崇儒肅成，丹書貴道，黃金賤籝，洙泗興業，闕里增榮。","sortOrder":189},
  {"id":"s_work_nvlt_38_190","chapterId":"ch_work_nvlt_38","text":"◇學校","sortOrder":190},
  {"id":"s_work_nvlt_38_191","chapterId":"ch_work_nvlt_38","text":"《物理論》曰：學者植也。","sortOrder":191},
  {"id":"s_work_nvlt_38_192","chapterId":"ch_work_nvlt_38","text":"《五經通義》曰：三王教化之宮，總名為學。","sortOrder":192},
  {"id":"s_work_nvlt_38_193","chapterId":"ch_work_nvlt_38","text":"《禮記》曰：古之教者，家有塾，党有庠，術有序，國有學。","sortOrder":193},
  {"id":"s_work_nvlt_38_194","chapterId":"ch_work_nvlt_38","text":"《周官》曰：師氏以三德教國子，一曰至德，以為道本，二曰敏德，以為行本，三曰孝德，以知［原缺，據冯校本補。］惡逆。","sortOrder":194},
  {"id":"s_work_nvlt_38_195","chapterId":"ch_work_nvlt_38","text":"《尚書大傳》曰：稷［《太平御覽》五百三十四作耰。］鉏已藏，歲事欲畢，餘子皆學，十［御覽十下有五字。］始入小學，見小節，踐小義，十八始入大學，見大節，踐大義。","sortOrder":195},
  {"id":"s_work_nvlt_38_196","chapterId":"ch_work_nvlt_38","text":"《漢書》曰：三代之道，乡里有教，夏曰校，殷曰庠，周曰序。","sortOrder":196},
  {"id":"s_work_nvlt_38_197","chapterId":"ch_work_nvlt_38","text":"《三辅舊事》曰：漢太子［《太平御覽》五百三十四作學。］在長安門東書杜［御覽作社。］門，五經博士員弟子萬餘人。","sortOrder":197},
  {"id":"s_work_nvlt_38_198","chapterId":"ch_work_nvlt_38","text":"黃圖曰：禮，小學在公宮之南，太學在東，就陽位也，去城七里，東為常滿仓，食之北為槐市，列槐树數百行，為隧，無牆屋，諸生朔望會此市，各持其群［御覽五百三十四作郡。］所出货物，及經傳書記，笙磬樂器，相與買賣，雍雍揖讓，論義槐下。","sortOrder":198},
  {"id":"s_work_nvlt_38_199","chapterId":"ch_work_nvlt_38","text":"《東觀漢記》曰：光武五年，初起太學，諸生吏子弟及民，以義助作，上自齊歸，幸太學，賜博士弟子。","sortOrder":199},
  {"id":"s_work_nvlt_38_200","chapterId":"ch_work_nvlt_38","text":"《續漢書》曰：明帝永平二年，上始帥群臣，養三老於辟雍，郡國縣道，行飲酒禮於學校。","sortOrder":200},
  {"id":"s_work_nvlt_38_201","chapterId":"ch_work_nvlt_38","text":"魏名臣奏曰：蒋濟奏，學者不恭肅，慢師酗酒好訟，罰飲水三升。","sortOrder":201},
  {"id":"s_work_nvlt_38_202","chapterId":"ch_work_nvlt_38","text":"晉諸公贊曰：惠帝時，裴頠為國子祭酒，奏立國子太學，起講堂，筑門闕，刻石寫經。","sortOrder":202},
  {"id":"s_work_nvlt_38_203","chapterId":"ch_work_nvlt_38","text":"任豫《益州記》曰：文翁學堂，在大城南，經火灾，蜀郡太守高眹，修复繕立，圖畫聖賢古人像，及禮器瑞物。","sortOrder":203},
  {"id":"s_work_nvlt_38_204","chapterId":"ch_work_nvlt_38","text":"【頌】後漢崔瑗南陽文學頌曰：昔聖人製禮樂也，將以統天理物，經國序民，立均出度，因其利而利之，俾不失其性也，故觀禮則體敬，聽樂則心和，然後知反其性，而正其身焉，取律於天以和聲，采言於聖以成謀，以和邦國，以諧萬民，以序賓旅，以悅遠人，其觀威儀，省禍福也，出言视聽，於是乎取之，民生如何，导以禮樂，乃修禮官，奋其羽籥，我國既淳，我俗既敦，神樂民則，嘉生乃繁，無言不酬，其德宜光，先民既没，賴茲舊章，我禮既經，我樂既馨，三事不叙，莫識其形。","sortOrder":204},
  {"id":"s_work_nvlt_38_205","chapterId":"ch_work_nvlt_38","text":"魏陳王曹植學宮頌曰：自五帝典絕，三王禮废，應期命世，齊賢等聖者，莫高於孔子也，故有若曰：出乎其類，拔乎其萃，誠所謂性與天道，不可得而聞矣，由也務學，名在前志，宰予晝寢，粪土作誡，過庭之言，子弟明記，歌以詠言，文以騁志，予今不述，後賢曷識，於鑠尼父，生民之杰，性與天成，該聖備藝，德倫三五，配皇作烈，玄鏡獨鑒，神明昭晢，仁塞宇宙，志陵雲霓，學者三千，莫不俊乂，唯仁可凭，唯道足恃，鑽仰弥高，請益不已。","sortOrder":205},
  {"id":"s_work_nvlt_38_206","chapterId":"ch_work_nvlt_38","text":"【志】魏王粲荆州文學記官志曰：有漢荆州牧曰劉君，稱曰：於先王為世也，則象天地，軌儀憲極，設教导化，叙經志業，用建雍泮焉，立師保焉，作為禮樂，以節其性，表陳載籍，以特其德，上知所以臨下，下知所以事上，官不失守，民德無悖，然後太階平焉，夫文學也者，人倫之首，大教之本也，乃命五業從事宋哀，［當作衷。］新作文學，延朋徒焉，宣德音以贊之，降嘉禮以勸之，五載之間，道化大行，耆德故老綦母阖等，負書荷器，自遠而至者，三百有餘人，於是童幼猛進，武人革面，總角佩觿，委介免胄，比肩繼踵，川逝泉涌，亹亹如也，兢兢如也，遂訓六經，講禮物，諧八音，协律呂，修紀歷，理刑法，六略鹹秩，百氏備矣，天降純嘏，有所底授，臻於我君，受命既茂，南牧是建，荆衡作守，時邁淳德，宣其丕繇，厥繇伊何，四國交阻，乃赫斯威，爰整其旅，虔夷不若，屢戡寇侮，誕啟洪軌，敦崇聖緒，典墳既章，禮樂鹹舉，濟濟搢紳，盛茲階宇，祁祁髦俊，亦集爰處，和化普畅，休徵時叙，品物宣育，百穀繁芜，勋格皇穹，聲被四宇。","sortOrder":206},
  {"id":"s_work_nvlt_38_207","chapterId":"ch_work_nvlt_38","text":"【銘】後漢李尤太學銘曰：漢遵禮典，崇興六藝，修周之理，埽秦之弊，褒建儒宮，廣置異記，开延學者，勸以爵位。","sortOrder":207},
  {"id":"s_work_nvlt_38_208","chapterId":"ch_work_nvlt_38","text":"【詔】宋傅亮立學詔曰：古之建國，教學為先，弘風訓世，莫尚於此，發蒙啟滯，鹹必由之，故爰自盛王，迄於近代，莫不敦崇學藝，修建庠序，自昔多故，戎馬在郊，旌旗卷舒，日不暇給，遂令學校荒芜，講誦蔑聞，軍旅日陳，俎豆藏器，訓誘之風，將墜於地，今王略遠覃，華域清晏，仰風之士，日月以冀，便宜博延胄子，陶奖童蒙，選被儒宮，弘振國學。","sortOrder":208},
  {"id":"s_work_nvlt_38_209","chapterId":"ch_work_nvlt_38","text":"【表】宋鄭鮮之請立學表曰：至於洙泗之教，洋洋盈耳，所以柔漸性情，日用成器，國废胄子之教，家弛勸學之訓，宜振起頹業，以回视聽，接光太陽，燭之幽夜，令欣流者濟津，懷寶者剖和。","sortOrder":209},
  {"id":"s_work_nvlt_38_210","chapterId":"ch_work_nvlt_38","text":"梁簡文帝求寧國臨城二公入學表曰：臣聞瞻彼緝孤，既次良冶，相諸筍玉，猶符他山，故沮涣之水可居，邹魯之乡為貴，下帷投斧，昔人以為精力，弃竿委麥，先哲以為美談，伏惟陛下，弘至德之微言，闡無為之妙說，語郊講道，不勞贾生之議，就陽啟位，無待公玉之圖，原得齒年國胄，隨肩選造。","sortOrder":210},
  {"id":"s_work_nvlt_38_211","chapterId":"ch_work_nvlt_38","text":"梁元帝請於州立學校表曰：臣聞公宮之南，四術四教，司樂成均，六詩六律，韶濩既舞，羽籥之道行焉，党塾茲備，離經之志辯焉，故不升嵩霍，豈識乾行之峻，不臨溟渤，安知地載之厚，洎乎秦焚金篆，周亡玉鏡，群言爭亂，諸子相騰，書則夏侯欧陽，易則神输道訓，詩乃齊魯毛韓，傳稱邹左張夹，禮有曲台王史之異，樂有龍德趙定之殊，伏惟陛下，撫五辰而建五長，播九德而导九州，容成為歷，興景雲之瑞，伶倫吹律，應黃鍾之琯，拨亂反正，經武也，製禮作樂，緯文也，若非六經庖厨，百家異饌，三墳為瑚璉，五典為笙簧，豈能暴以秋陽，紆就望之景，濯以江漢，播垂天之泽。","sortOrder":211},
  {"id":"s_work_nvlt_38_212","chapterId":"ch_work_nvlt_38","text":"【啟】梁王僧孺為萧監利求入學啟曰：竊以矯首伺飛，不如修弋，宛足念遠。莫若驅〈馬麃〉，故朴斫成於丹雘，筱簜資於栝羽，敢因莩末，有志庠均，為山資於一簣，學海漸其微流。","sortOrder":212},
  {"id":"s_work_nvlt_38_213","chapterId":"ch_work_nvlt_38","text":"梁任昉求為劉瓛立馆啟曰：昔在魏中，爰及晉始，書貴虛玄，人悅陶縱，瑚璉废泗上之容，樽俎恣林下之適，春幹秋羽，委曠而弗陳，西序東膠，寂寥而誰仰，所以金雞忘晓，玉羊失馭，神器毀於獯戎，寶歷遷於幹越，豈不悲欤，劉瓛澡身浴德，修行明經，賤珪璧於光陰，竟松筠於歲晚，貧不陨獲其心，窮不二三其操，而困無居止，浮寓親遊，垣棟傾鑽，窐衢墊侧，有朋自遠，無用栖凭，皆負笈擔簦，櫛風沐露，瓛之器學，無謝前修，辄欲與之周旋，开馆招屈，臣第西遍，官有閒地，北拒晉山，南望通邑，雖曰人境，實少浮喧，廣輪裁盈數畝，布以施立黉塾，薄藝桑麻，粗創茨宇。","sortOrder":213},
  {"id":"s_work_nvlt_38_214","chapterId":"ch_work_nvlt_38","text":"【教】晉湛方生修學校教曰：貴郡之境，山秀水清，嶺舉雲霞之摽，泽流清曠之氣，荆藍之璞，豈不在茲。","sortOrder":214},
  {"id":"s_work_nvlt_38_215","chapterId":"ch_work_nvlt_38","text":"梁元帝召學生教曰：閤下，昔楚王好詩，沛王傳易，猶且傳之不朽，以為盛事，况吾親承天旨，聞禮聞詩，方欲化行南國，被於西楚。","sortOrder":215},
  {"id":"s_work_nvlt_38_216","chapterId":"ch_work_nvlt_38","text":"◇釋奠","sortOrder":216},
  {"id":"s_work_nvlt_38_217","chapterId":"ch_work_nvlt_38","text":"《禮記》曰：凡欲立學，必先釋奠於先聖先師，及行事，必以幣，天子親學，大昕鼓徵，所以警眾也，眾至，然後天子至，乃命有司行事，適東序，釋奠於先老。","sortOrder":217},
  {"id":"s_work_nvlt_38_218","chapterId":"ch_work_nvlt_38","text":"又曰：凡學，春官釋奠於先師，秋冬亦如之，釋奠即舍菜，舍菜即祭菜，然則國子入學，以蘋蘩告誠，祀其師，以示敬道也，菜芹之屬。","sortOrder":218},
  {"id":"s_work_nvlt_38_219","chapterId":"ch_work_nvlt_38","text":"又曰：天子乃獻羔开冰，先荐寢廟，上丁，命樂正習舞，天子乃率公卿，親往视之，註雲，樂官之長也，命舞者，順萬物始出地鼓舞也，將舞，必釋奠於先師。","sortOrder":219},
  {"id":"s_work_nvlt_38_220","chapterId":"ch_work_nvlt_38","text":"夏小正月，［按當作曰。］二月丁亥，方，［大戴記夏小正作萬，此當作萬。］用日，［夏小正作用入學，此有訛脱。］丁亥者，吉日也，萬者，幹戚舞也，學者，大學也。","sortOrder":220},
  {"id":"s_work_nvlt_38_221","chapterId":"ch_work_nvlt_38","text":"晉博士戴邈議曰：周禮大胥之職，掌國子之版，以待致諸子，春入學，舍采合舞，秋頒學，合聲。","sortOrder":221},
  {"id":"s_work_nvlt_38_222","chapterId":"ch_work_nvlt_38","text":"晉范堅書問冯懷曰：漢代以來，釋奠先師，唯饗仲尼，不及公旦，何也，冯答曰：若如來之談，亦當憲章尧舜文武，豈唯周公乎。","sortOrder":222},
  {"id":"s_work_nvlt_38_223","chapterId":"ch_work_nvlt_38","text":"【詩】宋顏延之侍皇太子釋奠宴詩曰：伊昔周储，聿光往記，思皇世哲，體元作嗣，資此夙知，降從輕志，正殿張筵，司分簡日，尚度函丈，承疑奉帙，獻終袭吉，即宮廣宴，堂設象筵，庭宿金懸，台保兼徽，皇戚比音，肴乾酒澄，端服整弁。","sortOrder":223},
  {"id":"s_work_nvlt_38_224","chapterId":"ch_work_nvlt_38","text":"齊竟陵王萧子良侍皇太子釋奠宴詩曰：霜輕流日，風送夕雲，雕簷結采，綺井生文，四璉合旨，八簋舒芬。","sortOrder":224},
  {"id":"s_work_nvlt_38_225","chapterId":"ch_work_nvlt_38","text":"齊王俭侍皇太子釋奠宴詩曰：禮惟國幹，義實民端，身由業澡，世以教安，金鎔乃器，水術伊澜，漸芳則馥，履冰固寒，瞽宗務時，泮宮善誘，咨此含生，跻彼仁寿，淳移雅缺，歷茲永久，遊藝莫師，獨學誰友，三兆戒辰，八鸞警旦，禮邁仁周，樂超英漢，神保爰格，祝史斯贊。","sortOrder":225},
  {"id":"s_work_nvlt_38_226","chapterId":"ch_work_nvlt_38","text":"梁任昉侍皇太子釋奠宴詩曰：在昔歸運，阻亂弘多，夷山製宇，荡海為家，風雲改族，日月增華，惟神知化，在物立言，樂正雅頌，鹹被後崑，告奠明祀，觀道聖門，日月不息，師表常尊。","sortOrder":226},
  {"id":"s_work_nvlt_38_227","chapterId":"ch_work_nvlt_38","text":"梁沈約侍皇太子釋奠宴詩曰：复禮曲台，反樂宣榭，闕文內舉，輶軒外駕，結朋千里，從師百舍，队典必從，闕祀鹹荐，回鑾獻爵，摐金委奠，肆士辯儀，胥人掌縣，仿佛神蹤，徘徊靈睠。","sortOrder":227},
  {"id":"s_work_nvlt_38_228","chapterId":"ch_work_nvlt_38","text":"又為南郡王侍太子釋奠宴詩曰：陵季相沿，訓隨世殆，政缺雅乖，風離化改，禮亡衽席，樂沉河海，三雍靡構，四教誰采，瞻震併峻，義屬重麗，橫書清道，晦彼生知。","sortOrder":228},
  {"id":"s_work_nvlt_38_229","chapterId":"ch_work_nvlt_38","text":"【頌】晉傅鹹皇太子釋奠頌曰：生而知之，上於皇储，以能而問，處實若虛，爰雕聖章，玉采是敷，乃備嘉荐，於國之雍，敬享先師，以畴聖功。","sortOrder":229},
  {"id":"s_work_nvlt_38_230","chapterId":"ch_work_nvlt_38","text":"晉潘尼釋奠頌曰：三光迭運，五德代微，黃精既冗，素靈乃暉，有皇承天，造我晉畿，祚以大寶，登以龍飛，聖容穆穆，侍講訚訚，抽演微言，啟發道真，采幽窮赜，溫故知新，曰皇储後，體神含幾，兆吉先見，知來動微。","sortOrder":230},
  {"id":"s_work_nvlt_38_231","chapterId":"ch_work_nvlt_38","text":"【文】晉庾亮釋奠祭孔子文曰：維鹹康三年，荆豫州刺史都亭侯庾亮，敬告孔聖明靈，詩書煥於唐虞，憲章盛於文武，然後黎民時雍，彝倫攸叙，幽厲頹構，玉繩絕紀，高岸為穀，六合错否，上凌夷而失教，下苟免而無恥，公以玄聖之靈，應感圓通，萬物我賴，匪我求蒙，夫子既没，洪范乖流，秦雖慢道，漢聿孔修，洎我皇晉，仰钦大猷，宗聖既建，遐胄俾侯，令月吉辰，祗陳大禮，磬管锵锵，威儀濟濟，嘉奠既設，钦若靈規，心存鳳德，尚想來儀，神其歆之，降鑒在斯。","sortOrder":231},
  {"id":"s_work_nvlt_38_232","chapterId":"ch_work_nvlt_38","text":"梁元帝釋奠祭孔子文曰：粵若宗師，猗欤乃聖，惟嶽降神，惟天所命，上善如水，至人若鏡。","sortOrder":232},
  {"id":"s_work_nvlt_38_233","chapterId":"ch_work_nvlt_38","text":"又祭顏子文曰：钦哉體一，惡彼至人，乍分介石，時知落鱗，不先稱寶，席上為珍，致虛守靜，曲巷安貧，钦風味道，其德有鄰。","sortOrder":233},
  {"id":"s_work_nvlt_38_234","chapterId":"ch_work_nvlt_38","text":"梁陆倕釋奠祭孔子文曰：於惟上德，是曰聖真，克明克俊，知化窮神，研幾善誘，藏用顯仁，利同道濟，成俗教民，道尊功倍，德博化光，離經辨志，濟濟洋洋。","sortOrder":234},
  {"id":"s_work_nvlt_38_235","chapterId":"ch_work_nvlt_38","text":"《藝文類聚》　唐·欧陽詢","sortOrder":235},
  {"id":"s_work_nvlt_39_1","chapterId":"ch_work_nvlt_39","text":"卷三十九禮部中","sortOrder":1},
  {"id":"s_work_nvlt_39_2","chapterId":"ch_work_nvlt_39","text":"○巡守籍田社稷朝會燕會封禪親蠶","sortOrder":2},
  {"id":"s_work_nvlt_39_3","chapterId":"ch_work_nvlt_39","text":"◇巡守","sortOrder":3},
  {"id":"s_work_nvlt_39_4","chapterId":"ch_work_nvlt_39","text":"《禮》註［《太平御覽》五百三十七作禮記逸禮。］曰：王者必製巡守之禮何，尊天重民也，所以五年一巡守何，五歲再閏，天道大備，王者恩亦當竟也，所以至四嶽者，盛得之，［御覽作盛德之山，此有訛脱。］四方之中，能興雲致雨也。","sortOrder":4},
  {"id":"s_work_nvlt_39_5","chapterId":"ch_work_nvlt_39","text":"又曰：［按此禮記王製文。］天子五年一巡守，二月東巡守，至於岱宗，柴而望祀山川，觐諸侯，問百年者，就見之，命太師陳詩，以觀民風，命市納贾，以觀民之好惡。","sortOrder":5},
  {"id":"s_work_nvlt_39_6","chapterId":"ch_work_nvlt_39","text":"《易》曰：先王以省方，觀民設教。","sortOrder":6},
  {"id":"s_work_nvlt_39_7","chapterId":"ch_work_nvlt_39","text":"《尚書》曰：歲二月，東巡守，至於岱宗，柴。","sortOrder":7},
  {"id":"s_work_nvlt_39_8","chapterId":"ch_work_nvlt_39","text":"《傳》曰：天子非展義不巡守，註雲，巡守所以布德展義。","sortOrder":8},
  {"id":"s_work_nvlt_39_9","chapterId":"ch_work_nvlt_39","text":"《周禮》曰：職方氏，掌天下之圖，王巡守，則戒於四方，考職事，無不敬戒。","sortOrder":9},
  {"id":"s_work_nvlt_39_10","chapterId":"ch_work_nvlt_39","text":"《風俗通》曰：巡者，循也，守者，守也，道德太平，恐遠近不同化，幽隱有不得所者，故自躬親行之。","sortOrder":10},
  {"id":"s_work_nvlt_39_11","chapterId":"ch_work_nvlt_39","text":"《白虎通》曰：巡守所以時出何，當承宗廟，故不逾也，以夏之中月，同律度，得其中也。","sortOrder":11},
  {"id":"s_work_nvlt_39_12","chapterId":"ch_work_nvlt_39","text":"《越絕書》曰：禹巡守大越，見耆老，納詩書，審铨衡，平斗斛。","sortOrder":12},
  {"id":"s_work_nvlt_39_13","chapterId":"ch_work_nvlt_39","text":"《漢書》曰：元封五年冬，行南巡，至於盛唐，望祠虞舜於九疑，登天柱山，自尋陽浮江，親射蛟江中，獲之，舳舻千里，薄枞陽而出，作盛唐枞陽之歌。","sortOrder":13},
  {"id":"s_work_nvlt_39_14","chapterId":"ch_work_nvlt_39","text":"《東觀漢記》曰：章帝東巡，至岱宗，祀五帝於汶上。","sortOrder":14},
  {"id":"s_work_nvlt_39_15","chapterId":"ch_work_nvlt_39","text":"黃帝太一察［《初學記》十三，《太平御覽》五百三十七作密。］推曰：欲先知巡之年，當视太一與白［《初學記》，御覽作天目。］在四維之歲，為狩。","sortOrder":15},
  {"id":"s_work_nvlt_39_16","chapterId":"ch_work_nvlt_39","text":"蔡邕《獨斷》曰：巡守校獵還，公卿以下陳雒陽亭前街，上乘舆到，公卿以下拜，天子下車，公卿親識顏色，然後還宮，古語曰：在宮惟下，唯此時施行。","sortOrder":16},
  {"id":"s_work_nvlt_39_17","chapterId":"ch_work_nvlt_39","text":"挚虞新禮儀曰：魏元氏巡守故事新禮，守方嶽，柴望告至，設〈土匮〉，［明本作壝，下同。］諸侯之觐者乃挚，皆如儀，而不建旗，臣虞謹按，觐禮天子各建其旗，旗章所以殊爵命，视等威也，詩稱君子至止，言觀其旂，宜定新禮，建旗如舊。","sortOrder":17},
  {"id":"s_work_nvlt_39_18","chapterId":"ch_work_nvlt_39","text":"三齊略記曰：尧山在廣固城西七里，尧巡守所登，遂以為名，山顶立祠，祠邊有柏树，枯而复生，不知幾代树也。","sortOrder":18},
  {"id":"s_work_nvlt_39_19","chapterId":"ch_work_nvlt_39","text":"【詩】隋虞世基和幸江都尉［文苑英華作虞世南和幸江都尉詩。］詩曰：南國行周化，稽山秘夏圖，百王豈殊軌，千載协前謀，肆觐遵時豫，順動悅來蘇，安流進玉舳，戒道翼金吾，龍旂煥辰象，鳳吹溢川途，封唐昔敷錫，分陝被荆吳，沐道鹹知讓，慕義久成都，冬律初飛管，陽乌正衔芦，嚴飆肅林薄，暖景澹江湖，鸿私浃幽遠，厚泽润凋枯，虞琴起歌詠，漢筑動巴歈，多幸霑行苇，無庸類散樗。","sortOrder":19},
  {"id":"s_work_nvlt_39_20","chapterId":"ch_work_nvlt_39","text":"又曰：［《初學記》十三作虞茂奉和幸江都應詔詩。］巡遊光帝典，征吉乃文先，泽國翔宸駕，水府汎樓船，七華萦長薄，三翼亘通川，夙興大昕始，求衣昧旦前，澄澜浮晓色，遙林卷宿煙，晨霞稍含景，落月漸虧絃，回塘响歌吹，極浦望旌旃，方陪觐東後，登封禪肅然。","sortOrder":20},
  {"id":"s_work_nvlt_39_21","chapterId":"ch_work_nvlt_39","text":"【賦】漢楊雄甘泉賦曰：孝成帝時，客有荐雄文似相如者，上方祀甘泉泰畤，雄從上甘泉，故述斯賦，惟漢十世，將郊上玄，乃命群僚，星陳而天行，詔招搖與太陰兮，伏鉤陳使當兵，八神奔而警跸兮，飛蒙茸而走陆梁，猋駭雲迅，奋以方攘，半散照烂，粲以成章，於是帥爾陰閉，霅然陽开，流星旄以電燭兮，鹹翠蓋而鸞旗，臨高衍之嵱嵸，超紆譎之清澄，據軨軒而周流，忽軮軋而無垠，翠玉树之青葱，璧馬犀之璘〈王扁〉，歷倒景而絕飛梁，浮蠛蠓而撇天，曳虹彩之流離，颺翠氣之宛延，排玉戶而颺金鋪，發蘭蕙與芎藭，靡薜荔而為席，折琼枝以為芳，吸青雲之流霞，飲若木之露英，集乎禮神之囿，登乎頌祇之堂，攀璇璣而下视，行遊目乎三危，玉女亡所眺其清矑，宓妃曾不得施其蛾眉，於是钦柴宗祈，燎薰皇天，樵蒸焜上，配藜四施，選巫鹹兮叫帝閽，开天庭兮延群神，由是事畢功弘，回車而歸，登長平兮雷鼓磕，度三蠻兮偈棠梨，雲飛扬兮雨雱霈，於胥德兮麗萬世，亂曰：崇崇圜丘，隆隱天兮，增宮參差，骈嵯峨兮，上天之縡，杳旭卉兮，聖皇穆穆，信厥對兮，來祗郊禋，神所依兮，辉光炫燿，降厥福兮，子子孫孫，長無極兮。","sortOrder":21},
  {"id":"s_work_nvlt_39_22","chapterId":"ch_work_nvlt_39","text":"又幸河東賦曰：其三月，將祭後土，上乃帥群臣，橫大河，凑汾陰，既祭畢，登歷觀，陟西嶽，以望八荒，跡殷周之墟，眇然以思唐虞之風，雄以為臨川羨魚，不如歸而結網，還，上河東賦以勸，其辭曰：伊年暮春，將瘞後土，禮靈祇，謁汾陰於東郊，乃撫翠鳳之駕，馳光影之乘，棹奔星之流旃，攫天狼之威弧，奋電鞭，驂雷辎，鳴洪鍾，建逐旂，羲和司日，顏倫奉舆，樂往昔之遺風，喜虞舜之所耕，瞰帝唐之嵩高兮，盻隆周之大寧，叱風伯於南北，呵雨師於西東，參天地而獨立，廓荡荡其無双。","sortOrder":22},
  {"id":"s_work_nvlt_39_23","chapterId":"ch_work_nvlt_39","text":"【頌】後漢班固東巡頌曰：竊見巡狩岱宗，上稽帝尧，中述世宗，遵奉世祖，禮儀備具，動自聖心，是以明神屢應，休徵仍降，不勝狂簡之情，謹上岱宗頌一篇曰：若稽古在漢迪哲，聿修厥德，憲章丕烈，翿六龍，较五辂，齊百僚，陶质素，命南重以司歷，厥中月之六辰，備天官之列衛，盛舆服而東巡。","sortOrder":23},
  {"id":"s_work_nvlt_39_24","chapterId":"ch_work_nvlt_39","text":"又南巡頌曰：惟漢再命，系葉十一，帝典协景，和則天經，郊高宗，光六幽，通神明，既禘祖於西都。又將祫於南庭，是時聖上運天官之法駕，凭列宿而贊元。","sortOrder":24},
  {"id":"s_work_nvlt_39_25","chapterId":"ch_work_nvlt_39","text":"後漢崔骃東巡頌曰：伊漢中興三葉，於皇惟烈，允迪厥倫，矩坤度以范物，規乾則以陶鈞，於是考上帝以质中，總列宿於北辰，开太微，敞禁庭，延儒林以谘詢岱嶽之事，於時典司耆耇，載華抱實，逌爾而造曰：盛乎大漢，世增其德，此神人之所庶［《初學記》十三作慶。］幸，海內之所想思，頌有乔山之征，典有徂嶽之巡，時邁其邦，民斯攸勤，不亦宜哉，乃命太仆，訓六騶，閒路馬，戒師徒，於是乘舆登天靈之威路，駕太一之象車，升九龍之華旗，建扫霓之旌旄，裒胡耇之元老，賞孝行之畯農。","sortOrder":25},
  {"id":"s_work_nvlt_39_26","chapterId":"ch_work_nvlt_39","text":"後漢馬融東巡頌曰：允迪在昔，紹烈陶唐，殷天衷，充搖光，若時則，運琼衡，敷六典，經八成，肆類乎上帝，實柴乎三辰，禋祀乎六宗，祗燎乎群神，遂發號群司，申戒百工，卜筮稱吉，蓍龟袭從，南征□□，冯相告祥，清夷道而後行，曜四國而扬光，展聖義於巡狩，喜圻畤而詠八荒，指宗嶽以為期，固岱神之所望，散斋既畢，越翼良辰，棫槱增構，烈火燔燃，暉光四煬，焱烂薄天，萧香肆升，青煙冒雲，珪璋瓘瓘，犧牲絜純，鬱鬯宗彝，明水玄樽，空桑孤竹，鹹池雲門，六八匝变，神祇併存。","sortOrder":26},
  {"id":"s_work_nvlt_39_27","chapterId":"ch_work_nvlt_39","text":"【誥】後漢張衡東巡誥曰：惟二月初吉，帝將狩於岱嶽，展義省方，觀民設教，率群賓，備法駕，以祖於東門，屆於靈宮，是日也，有鳳双集於台，壬辰，祀上帝於明堂，帝曰：咨予不材，為天地主，栗栗翘翘，百僚萬機，心之謂矣，孰朕之勞，上帝有靈，不替朕命，誕敢不祗承，凡庶與祭於壇墠之位者曰：懷爾邦君，寔原先帝，載厥太宗，以左右朕躬，群臣曰：帝道橫被，旁行海表，一人有韙，萬民賴之，從巡助祭者，茲惟嘉瑞，乃歌曰：皇皇者鳳，通玄知時，萃於山趾，與帝邀期，吉事有祥，惟漢之祺，帝曰：朕不敢當，亦不敢蔽天之吉命。","sortOrder":27},
  {"id":"s_work_nvlt_39_28","chapterId":"ch_work_nvlt_39","text":"◇籍田","sortOrder":28},
  {"id":"s_work_nvlt_39_29","chapterId":"ch_work_nvlt_39","text":"《說文》曰：帝籍千畝者，使民如借，故謂之籍。","sortOrder":29},
  {"id":"s_work_nvlt_39_30","chapterId":"ch_work_nvlt_39","text":"《毛詩》曰：載芟，春籍田而祈社稷也。","sortOrder":30},
  {"id":"s_work_nvlt_39_31","chapterId":"ch_work_nvlt_39","text":"《周官》曰：上春，詔王後帥六宮之人，而生穜稑之种，而獻之於王。","sortOrder":31},
  {"id":"s_work_nvlt_39_32","chapterId":"ch_work_nvlt_39","text":"又曰：甸師，率其屬而耕耨王籍，以時入之，以供粢盛。","sortOrder":32},
  {"id":"s_work_nvlt_39_33","chapterId":"ch_work_nvlt_39","text":"《禮記》曰：孟春之月，天子乃以元日，祈穀於上帝，天子親載耒耜，帥三公九卿，諸侯大夫，躬耕帝籍，天子三推，三公五推，卿諸侯九推，庶人終畝，反，乃執爵於太寢，命曰勞酒。","sortOrder":33},
  {"id":"s_work_nvlt_39_34","chapterId":"ch_work_nvlt_39","text":"又曰：天子耕於南郊，諸侯於東郊。","sortOrder":34},
  {"id":"s_work_nvlt_39_35","chapterId":"ch_work_nvlt_39","text":"又曰：天子為籍千畝，冕而朱紘，躬執耒，以事天地山川，以為醴酪粢盛，於是乎取之，敬之至也，諸侯百畝，冕而青紘。","sortOrder":35},
  {"id":"s_work_nvlt_39_36","chapterId":"ch_work_nvlt_39","text":"梁五禮籍田儀註曰：其田東去宮八里，遠十六里，為千畝，天子耒耜一具，九卿耒耜九具，立方壇，以祠先農。","sortOrder":36},
  {"id":"s_work_nvlt_39_37","chapterId":"ch_work_nvlt_39","text":"應劭《漢官儀》曰：天子升壇，公卿耕訖，啬夫下种，籍田千畝，亦曰帝籍，亦曰親耕，亦曰王籍。","sortOrder":37},
  {"id":"s_work_nvlt_39_38","chapterId":"ch_work_nvlt_39","text":"又曰：東耕之日，親率公卿，戴青帻，載青車，駕蒼馬，公卿以下，車駕如常法。","sortOrder":38},
  {"id":"s_work_nvlt_39_39","chapterId":"ch_work_nvlt_39","text":"五經要義曰：天子籍田千畝，孟冬啟蟄，既郊之後，率公卿大夫而親耕焉，所以先百姓而致孝敬。","sortOrder":39},
  {"id":"s_work_nvlt_39_40","chapterId":"ch_work_nvlt_39","text":"《國語》曰：宣王即位，不籍千畝，虢文公諫曰：夫民之大事在農，上帝之粢盛，於是乎出，民之蕃庶，於是乎生，先時九日，太史告稷曰：陽氣俱蒸，土膏其動，稷［原作即，據冯校本改。］以告王，王即御事，王耕一拨，班三之，庶人終乎千畝，王不聽，師败於薑戎也。","sortOrder":40},
  {"id":"s_work_nvlt_39_41","chapterId":"ch_work_nvlt_39","text":"《論衡》曰：立春東耕，為土象人，男女各二，執耒鉏錢，或立土牛，象人土牛未畢而耕也，從氣應時，示帥下也。","sortOrder":41},
  {"id":"s_work_nvlt_39_42","chapterId":"ch_work_nvlt_39","text":"漢書文帝詔曰：夫農天下之本，其籍田，朕親率耕，以給宗廟粢盛。","sortOrder":42},
  {"id":"s_work_nvlt_39_43","chapterId":"ch_work_nvlt_39","text":"《東觀漢記》曰：永平十三年二月，耕籍田畢，賜觀者食，有一諸生前言，善哉文王之遇太公也，上書版曰：生非太公，予亦非文王。","sortOrder":43},
  {"id":"s_work_nvlt_39_44","chapterId":"ch_work_nvlt_39","text":"【詩】宋顏延之侍東耕詩曰：題封經地域，辰角麗天部，浮藹起青壇，沉腴發绀耦，草服荐同穗，黃冠獻嘉寿。","sortOrder":44},
  {"id":"s_work_nvlt_39_45","chapterId":"ch_work_nvlt_39","text":"宋謝莊侍東耕詩曰：肅鑣奉晨發，恭帶廁朝聞，仙乡降朱藹，神郊起青雲，陰台承寒采，陽树迎初薰，觀德欣臨籍，瞻道樂遊汾。","sortOrder":45},
  {"id":"s_work_nvlt_39_46","chapterId":"ch_work_nvlt_39","text":"梁武帝籍田詩曰：寅賓始出日，律中方星鳥，仁化洽孩虫，德令禁胎夭，耕籍乘月映，遺滯指秋杪，年丰廉讓多，歲薄禮節少。","sortOrder":46},
  {"id":"s_work_nvlt_39_47","chapterId":"ch_work_nvlt_39","text":"梁簡文帝和詩曰：禮經聞往說，觀寶著遐篇，豈如春路動，祈穀重民天，三春润榆荚，七月待鳴蝉，鰩魚顯嘉瑞，銅雀應丰年，不勞鄭國雨，無榮鄴令田。","sortOrder":47},
  {"id":"s_work_nvlt_39_48","chapterId":"ch_work_nvlt_39","text":"陳張正見從籍田應衡陽王教作詩曰：帝京惟赤縣，神居應紫微，涂山萬國仰，沧海百川歸，東郊事平秩，仲月祀靈威，含光开早扇，閶阖啟朝扉，［其一。］","sortOrder":48},
  {"id":"s_work_nvlt_39_49","chapterId":"ch_work_nvlt_39","text":"洛城鍾漏息，靈台雲霧卷，森森虎戟前，藹藹鑾旂轉，屬車遊絳闕，風乌度丹巘，帳殿幸金舆，旌門擁玉輦，［其二。］","sortOrder":49},
  {"id":"s_work_nvlt_39_50","chapterId":"ch_work_nvlt_39","text":"玉輦帶非煙，金舆映绿川，雨師清遠路，風伯靜遙天，分渠通沃野，激水入公田，草發青壇外，花飛蒼玉前，［其三。］","sortOrder":50},
  {"id":"s_work_nvlt_39_51","chapterId":"ch_work_nvlt_39","text":"蒼玉臨珪璧，青壇躬帝籍，冒橛乃三推，齊衡均百辟，蘭場俨芝駕，桂圃芳瑤席，山禽韻管絃，野獸和鍾石，［其四。］","sortOrder":51},
  {"id":"s_work_nvlt_39_52","chapterId":"ch_work_nvlt_39","text":"鍾石既相和，江海复無波，梁客簪裾盛，陳王文雅多，修涂參弱骀，乔木間輕萝，幸承溫吹末，击壤自為歌，［其五。］","sortOrder":52},
  {"id":"s_work_nvlt_39_53","chapterId":"ch_work_nvlt_39","text":"【賦】晉潘嶽籍田賦曰：伊晉之四年正月，皇帝親率群後籍於千畝之甸，禮也，於是乃使甸師清畿，野庐扫路，封人〈土匮〉宮，掌舍設枑，青壇蔚其嶽立，翠幕點以雲布，沃野墳腴，膏壤平砥，清洛濁渠，引流激水，葱犗服於縹軛，绀轅缀於黛耜，俨储駕於廛左，俟萬乘之躬履，袭春服之萋萋，接遊車之辚辚，森奉璋以階列，望皇軒而肅震，若湛露之晞朝陽，似眾星之拱北辰，於是前驅魚麗，屬車辚萃，閶阖洞啟，參涂方驷，常伯陪乘，太仆秉辔，後妃獻穜稑之种，司農撰播植之器，天子乃御玉輦，荫華蓋，冲牙錚鎗，绡紈綷纟蔡，表朱玄於離坎，飛青鎬於震兑。中黃晔以發暉，方采紡其繁會，震震填填，以幸乎藉田，蝉冕颎以灼灼，碧色肅其芊芊，似夜光之剖荆璞，若茂松之依山巔，於是我皇，乃降靈壇，撫御耦，三推而舍，庶人終畝，貴賤以班，或五或九，躡踵侧肩，椅裳連袂，黃尘為之四合，陽光為之潛翳，動容發音，而觀者莫不抃舞乎康衢，謳吟乎聖世，有邑老田父，進而稱曰：蓋損益隨時，理有常然，高以下為基，民以食為天，九土之宜弗任，四人之務不一，展三時之弘務，致仓廪之盈溢，固尧湯之用心，而存救之要術，若乃廟祧有事，祝宗诹日，黍稷馨香，旨酒嘉栗，古人有言曰：昔者明王以孝治天下，其或繼之者希矣，逮我皇晉，實光斯道，儀形孚於萬國，愛敬盡於祖考。","sortOrder":53},
  {"id":"s_work_nvlt_39_54","chapterId":"ch_work_nvlt_39","text":"宋任豫籍田賦曰：瞻望圭景，咫尺三川，緬彼帝籍，百有餘年，映至德於盛位，俪列晷於微辰，紆汾陽以昧旦，信尧心而禹勤，史奉載耜之禮，民奏舉趾之歌，膏壤千畝，與式既同，區势平易，畎陌脩通，提携丘泽，眺嶺面松。","sortOrder":54},
  {"id":"s_work_nvlt_39_55","chapterId":"ch_work_nvlt_39","text":"隋江總勞酒賦曰：在陽春之仲序，覽具物之芳菲，帥公卿而播百穀，親耒耜而命三推，开青壇於回甸，列翠幕於清沂，乃遵執爵之典，爰降食苹之宴，豁朱鳥之高窗，啟黃龍之抗殿，奏帝鸿之萬舞，動鈞天之九变，顧曲私之亭育，遞寒暑而徂遷，谬陳力而策骀，豈酬恩於暮年。","sortOrder":55},
  {"id":"s_work_nvlt_39_56","chapterId":"ch_work_nvlt_39","text":"【文】齊謝朓為隨王粲東耕文曰：穀躔星景，穡表踖先，八政奚首，六府茲宣，獘嗟非國，登頌有年，一夫惑怠，望歲誰天。","sortOrder":56},
  {"id":"s_work_nvlt_39_57","chapterId":"ch_work_nvlt_39","text":"梁元帝祭東耕文曰：三農九穀，為政所先，萬箱亿庾，是曰民天，系稱斫耜，書美厥田，花开杏树，冻解新泉，當使黍稷莫莫，民翳胥樂，甘雨祁祁，遂及我私，我私之熟，表里禔福，禔福中田，歲取十千，是藨是袞，登頌有年。","sortOrder":57},
  {"id":"s_work_nvlt_39_58","chapterId":"ch_work_nvlt_39","text":"【啟】梁元帝慶東耕啟曰：伏惟陛下，敬授民時，造幄籍圃，漢之元鳳，未足捧羁，晉之太始，非堪扶轂，但承明侍從，即事未由，周南留滯，伏深恋仰。","sortOrder":58},
  {"id":"s_work_nvlt_39_59","chapterId":"ch_work_nvlt_39","text":"【論】魏陳王曹植籍田論曰：春耕於籍田，郎中令侍寡人焉，顧而謂之曰：昔者神農氏始嘗萬草，教民种植，今寡人之興此田，將欲以擬乎治國，非徒娱耳目而已也，夫營畴萬畝，厥田上上，經以大陌，帶以橫阡，此亦寡人之封疆也，日殄没而歸馆，晨未昕而即野，此亦寡人之先下也，菽雚特畴，禾黍異田，此亦寡人之政理也，及其息沸涌，庇重陰，懷有虞，撫素琴，此寡人之所習樂也，蘭蕙荃蘅，植之近畴，此亦寡人之所親賢也，藜蓬臭蔚，弃之乎遠疆，此亦寡人之所遠佞也，若年丰歲登，果茂菜滋，則臣仆小大，鹹取验焉。","sortOrder":59},
  {"id":"s_work_nvlt_39_60","chapterId":"ch_work_nvlt_39","text":"又曰：封人有能以輕凿脩鉤，去树之蝎者，树得以繁茂，中舍人曰：不識天下者亦有蝎乎，寡人告人曰：昔三苗共工鯀驩兜，非尧之蝎與，問曰：諸侯之國，亦有蝎乎，寡人告之曰：齊之諸田，晉之六卿，魯之三桓，非諸侯之蝎與，然三國無輕凿脩鉤之任，終於齊篡魯弱，晉國以分，不亦痛乎，曰：不識為君子者亦有蝎乎，寡人告之曰：固有之也，富而慢，貴而驕，殘仁賊義，甘财悅色，亦君子之蝎乎，天子勤耘以收一國，大夫勤耘以收世祿，君子勤耘以顯令德，夫農者始於种，終於獲，泽既時矣，苗既美矣，弃而不耘，則故為荒畴，蓋丰年者期於必收，譬修道亦期於没身也。","sortOrder":60},
  {"id":"s_work_nvlt_39_61","chapterId":"ch_work_nvlt_39","text":"◇社稷","sortOrder":61},
  {"id":"s_work_nvlt_39_62","chapterId":"ch_work_nvlt_39","text":"《孝經緯》曰：社，土地之主也，土地闊不可盡敬，故封土為社，以報功也，稷，五穀之長也，穀眾不可遍祭，故立稷神以祭之。","sortOrder":62},
  {"id":"s_work_nvlt_39_63","chapterId":"ch_work_nvlt_39","text":"《禮記》曰：夫聖王之製禮也，法施於民則祀之，以勞定國則祀之，能御大灾則祀之，能扞大患則祀之，是故厲山氏之有天下也，其子曰柱，能殖百穀，夏之衰也，周弃繼之，故祀以為稷，共工氏之霸九州也，其子曰後土，能平九州，故祀以為社。","sortOrder":63},
  {"id":"s_work_nvlt_39_64","chapterId":"ch_work_nvlt_39","text":"又曰：社祭土而主陰氣也，君南向，於北墉下，答陰之義也，［牆謂之墉，北墉，社內地也。］日用甲，用日之始也，［國中之神，莫貴於社。］天子大社，必受霜露風雨，以達天地之氣也，是故丧國之社屋之，不受天陽也，薄社北墉，使陰明也，社所以神，地之道也，地載物，天垂象，取财於地，取法於天，是以尊天而親地也。","sortOrder":64},
  {"id":"s_work_nvlt_39_65","chapterId":"ch_work_nvlt_39","text":"又曰：王為神群姓立社，曰太社，自立社，曰王社，諸侯為百姓立社，曰國社，自為立曰侯社，大夫以下置社。","sortOrder":65},
  {"id":"s_work_nvlt_39_66","chapterId":"ch_work_nvlt_39","text":"《左傳》曰：魏獻子問於蔡墨曰：社稷五祀，誰氏之五官也，對曰：少皞有四叔，曰重，曰該，曰脩，曰熙，實能金木及水，使重為句芒，該為蓐收，脩及熙為玄冥，此其三祀也，颛頊氏有四［左傳昭二十九年四字無。］子，曰黎，為祝融，共工氏有子，曰句龍，為後土，此其二祀也，後土為社稷，田正也，有烈山氏之子，曰柱，為稷，自夏以上祀之，周弃亦為稷，自商以來祀之。","sortOrder":66},
  {"id":"s_work_nvlt_39_67","chapterId":"ch_work_nvlt_39","text":"又曰：宋使邾文公用鄫子於次睢之社，欲以屬東夷，司馬子魚曰：古者六畜不相為用，小事不用大牲，况敢用人乎，祭祀以為人，民，神之主，用人，其誰饗之。","sortOrder":67},
  {"id":"s_work_nvlt_39_68","chapterId":"ch_work_nvlt_39","text":"《尚書》曰：海岱及淮，惟徐州，厥貢惟土五色，王者封五色土以為社，建諸侯，則割方色土立社，焘以黃土，苴以白茅，茅取其絜，黃取王者覆四方也。","sortOrder":68},
  {"id":"s_work_nvlt_39_69","chapterId":"ch_work_nvlt_39","text":"又曰：湯既勝夏，欲遷其社，不可，湯承尧舜禪之後，順天應人，逆取順守，而有慚德，故革命創製，改正易服，委宜［《初學記》十三作变置。］社稷，以稷代無及句龍者，故不可而止。","sortOrder":69},
  {"id":"s_work_nvlt_39_70","chapterId":"ch_work_nvlt_39","text":"又曰：越翼日戊午，乃社於新邑，牛羊豕各一，註雲，告社稷用太牢也。","sortOrder":70},
  {"id":"s_work_nvlt_39_71","chapterId":"ch_work_nvlt_39","text":"《周書》曰：諸侯受命於周，乃建立太社於國中，其〈土匮〉，東青土，南赤土，西白土，北驪土，中央焘以黃土，將建諸侯，凿取方一面之土，苴以白茅，以土封之，故曰列土於周也。","sortOrder":71},
  {"id":"s_work_nvlt_39_72","chapterId":"ch_work_nvlt_39","text":"《周官》曰：小宗伯，掌建國之神位，右社稷，大宗伯，掌以血祭祭社稷。","sortOrder":72},
  {"id":"s_work_nvlt_39_73","chapterId":"ch_work_nvlt_39","text":"又曰：封人設王之社壝，為畿，封而树之，註雲，壝，壇也。","sortOrder":73},
  {"id":"s_work_nvlt_39_74","chapterId":"ch_work_nvlt_39","text":"公羊傳曰：日有食之，鼓用牲於社，求乎陰道也，以朱絲營社，或曰胁之，或曰暗恐犯之，故營也。","sortOrder":74},
  {"id":"s_work_nvlt_39_75","chapterId":"ch_work_nvlt_39","text":"尚書逸篇曰：北社惟松惟柏，南社為梓，西社為槐。","sortOrder":75},
  {"id":"s_work_nvlt_39_76","chapterId":"ch_work_nvlt_39","text":"《白虎通》曰：王者所以有社稷何，為天地報功也，社稷所以有树何，所以表功也。","sortOrder":76},
  {"id":"s_work_nvlt_39_77","chapterId":"ch_work_nvlt_39","text":"《淮南子》曰：禹勞天下，故死而為社，周弃作稼穡，死而為稷。","sortOrder":77},
  {"id":"s_work_nvlt_39_78","chapterId":"ch_work_nvlt_39","text":"又曰：夫窮乡之社，叩瓮拊缺，相和而歌曰：以為樂也，常试為之，击建鼓，撞巨鍾，乃始知夫瓮缺之足羞也，夫至道之論，亦學者之建鼓也，芜乡之社，易為黍肉，芜國之稷，易為求福。","sortOrder":78},
  {"id":"s_work_nvlt_39_79","chapterId":"ch_work_nvlt_39","text":"《莊子》曰：匠石之齊，至於曲轅，見櫟社树，其大蔽牛，其高臨山，十仞而後有枝，其可以為舟者旁十數，觀者如市。","sortOrder":79},
  {"id":"s_work_nvlt_39_80","chapterId":"ch_work_nvlt_39","text":"《論語》曰：哀公問社於宰我，宰我對曰：夏後氏以松，殷人以柏，周人以栗。","sortOrder":80},
  {"id":"s_work_nvlt_39_81","chapterId":"ch_work_nvlt_39","text":"《論衡》曰：亡國之社，屋其上，栈其下，絕於天地，夫春秋藩社，周以為戒。","sortOrder":81},
  {"id":"s_work_nvlt_39_82","chapterId":"ch_work_nvlt_39","text":"《漢書》曰：高祖時，天下已定，詔御史，宜於丰治枌榆社，嘗以春羊彘祀之。","sortOrder":82},
  {"id":"s_work_nvlt_39_83","chapterId":"ch_work_nvlt_39","text":"又曰：社者土地，宗廟王者所居，稷者百穀之王，所以奉宗廟，共粢盛，人所食以生活也，王者莫不尊重，親祭者為之主禮。","sortOrder":83},
  {"id":"s_work_nvlt_39_84","chapterId":"ch_work_nvlt_39","text":"《毛詩》曰：乃立冢土。","sortOrder":84},
  {"id":"s_work_nvlt_39_85","chapterId":"ch_work_nvlt_39","text":"又曰：以御田祖，以祈甘雨。","sortOrder":85},
  {"id":"s_work_nvlt_39_86","chapterId":"ch_work_nvlt_39","text":"《漢書》曰：漢興，禮儀稍定，已有官社，未立官稷，遂於官社後立官稷，以夏禹配饗官社，後稷配食官稷，徐州牧歲貢五色土各一斗。","sortOrder":86},
  {"id":"s_work_nvlt_39_87","chapterId":"ch_work_nvlt_39","text":"又曰：陳平既娶張氏女，資用益饒，遊道日廣，里中社，平為之宰，分肉食甚均，里父老曰：善陳孺子之為宰，平曰：嗟乎，使平得宰天下，亦如此肉矣。","sortOrder":87},
  {"id":"s_work_nvlt_39_88","chapterId":"ch_work_nvlt_39","text":"又曰：栾布，吳軍時，以功封為俞侯，燕齊之間，皆為立社，號曰栾公社。","sortOrder":88},
  {"id":"s_work_nvlt_39_89","chapterId":"ch_work_nvlt_39","text":"又曰：［本條《太平御覽》五百三十二作博物志。］周之正月受社牲之首，以出种於帝籍，蠶人受社雍祭，以沐蠶种，上辛，乃射里社［御覽作黑牲。］於帝郊，以祈來年之丰。","sortOrder":89},
  {"id":"s_work_nvlt_39_90","chapterId":"ch_work_nvlt_39","text":"漢舊事曰：天子太社，以五土為壇，封諸侯者，取其土，苴以白茅，授之，各以其所封方色，立社於其國，故曰受茅土。","sortOrder":90},
  {"id":"s_work_nvlt_39_91","chapterId":"ch_work_nvlt_39","text":"《搜神記》曰：中興初，有應嫗者，生四子，而盡［《初學記》十三作晝。］見神光照社，初探试之，乃得黃金，自是諸子官學，併有芳名，至玚七世顯，雲雲。","sortOrder":91},
  {"id":"s_work_nvlt_39_92","chapterId":"ch_work_nvlt_39","text":"戴延之《西征記》曰：洛陽建春門外迎道北，有白社，董威輦所住也，去門二里，白社有牛馬市，即嵇公臨刑處也。","sortOrder":92},
  {"id":"s_work_nvlt_39_93","chapterId":"ch_work_nvlt_39","text":"伍辑之《從征記》曰：臨沂厚丘間，有次雎里社，常以人祭，襄公使邾子用鄫子處，相承雇貧人，命斋絜，祭時縛著社前，如見牲犧，魏初乃止。","sortOrder":93},
  {"id":"s_work_nvlt_39_94","chapterId":"ch_work_nvlt_39","text":"荆州圖記曰：鄭［字有訛。］縣東百步，有縣故城，縣南里名伍伯村，有白榆連理树，異根合條，高四丈餘，土民奉為社。","sortOrder":94},
  {"id":"s_work_nvlt_39_95","chapterId":"ch_work_nvlt_39","text":"湛方生盟文曰：仰推先王建社之義，俯從詩人匍伏之儀，遂藝树立壇，結誓明神。","sortOrder":95},
  {"id":"s_work_nvlt_39_96","chapterId":"ch_work_nvlt_39","text":"【賦】晉張華朽社賦曰：高柏桥南大道傍，有古槐树，蓋數百年木也，餘少居近之，後去，行路遇之，則已朽，意有緬然，辄為之賦，因以言衰盛之理雲爾，伊茲，槐之挺植，於京路之東隅，得讬尊於田主，據爽垲以高居，垂重陰於道周，臨大路之通衢，饗春秋之所報，應丰胙於無射，歷漢京之康樂，逾丧亂之橫逆，朱夏當陽，蓊藹萧森，征夫雲會，行旅歸心，輶軒停蓋，輕舆讬陰，吉人向風而袪袂，王孫清嘯而啟襟，晞甘棠之廣覆，褊乔木之無陰。","sortOrder":96},
  {"id":"s_work_nvlt_39_97","chapterId":"ch_work_nvlt_39","text":"【頌】魏陳王曹植社頌曰：於惟太社，官名後土，是曰句龍，功著仁古，德配帝皇，實為靈主，克明播植，農正曰柱，尊以作稷，丰年是興，義與社同，方神北宇，建國承家，莫不脩叙。","sortOrder":97},
  {"id":"s_work_nvlt_39_98","chapterId":"ch_work_nvlt_39","text":"宋何承天社頌曰：餘以永初三年八月大社，聊為此文，實惟陰祇，稷為穀元，率育萬類，协靈昊乾，霸德方將，世號共工，厥有才子，寔曰句龍，稱物平賦，百姓喜雍，唐尧救灾，决河流江，弃亦播植，作乂萬邦，克配二祀，以報勤庸，勤庸伊何，厚載生民，仓廪既實，神節斯因，人亦有言，物用思人，矧乃大德，功被陶鈞，豈伊百世，萬代不泯，蒸哉帝王，肇建皇極，體國經野，設官分職，瓘瓘二社，列幹比殖，歲雲其秋，晷漏均程，牲牢既絜，嘉荐惟馨。","sortOrder":98},
  {"id":"s_work_nvlt_39_99","chapterId":"ch_work_nvlt_39","text":"◇朝會","sortOrder":99},
  {"id":"s_work_nvlt_39_100","chapterId":"ch_work_nvlt_39","text":"《禮記》曰：天子無事與諸侯相見，曰朝，［事具征伐篇。］","sortOrder":100},
  {"id":"s_work_nvlt_39_101","chapterId":"ch_work_nvlt_39","text":"《周禮》曰：春見曰朝，夏見曰宗，秋見曰觐，冬見曰遇，時見曰會，殷見曰同。","sortOrder":101},
  {"id":"s_work_nvlt_39_102","chapterId":"ch_work_nvlt_39","text":"又曰：王執镇圭，［以四镇山為飾。］公執桓圭，侯執信圭，信即身也，謂圭上作人身，伯執躬圭，亦身，子執穀璧，［穀以養人，璧上作穀。］男執蒲璧，［蒲者所以為席，以安人，為璧上作蒲草文。］孤執皮帛，卿執羔，大夫執雁，士執雉，庶人執鶩，工商執雞。","sortOrder":102},
  {"id":"s_work_nvlt_39_103","chapterId":"ch_work_nvlt_39","text":"又曰：春朝諸侯而圖天下之事，註雲，圖，考績也。","sortOrder":103},
  {"id":"s_work_nvlt_39_104","chapterId":"ch_work_nvlt_39","text":"傳曰：凡朝以正班爵之義，會以訓上下之則。","sortOrder":104},
  {"id":"s_work_nvlt_39_105","chapterId":"ch_work_nvlt_39","text":"又曰：宣十四年，孟獻子言於公曰：臣聞小國之免於大國也，聘而獻物，於是庭實旅百，朝而獻功，註雲，獻其國，若征伐之功於牧伯也。","sortOrder":105},
  {"id":"s_work_nvlt_39_106","chapterId":"ch_work_nvlt_39","text":"又曰：子產相鄭伯如楚，侨聞大適小，有五美，宥其罪戾，赦其過失，救其灾患，賞其德刑，教其不及。","sortOrder":106},
  {"id":"s_work_nvlt_39_107","chapterId":"ch_work_nvlt_39","text":"又曰：薳啟彊對楚子曰：朝聘有圭，享頫有璋，小有述職，大有巡功。","sortOrder":107},
  {"id":"s_work_nvlt_39_108","chapterId":"ch_work_nvlt_39","text":"又曰：叔向曰：明王之製，使諸侯歲聘以志業，間朝以講禮，再朝而會以示威，再會而盟，以著昭明，志業於好，講禮於等，示威於眾，昭明於神。","sortOrder":108},
  {"id":"s_work_nvlt_39_109","chapterId":"ch_work_nvlt_39","text":"又曰：莊公二十三年，夏，公如齊觀社，非禮也，曹刿諫曰：夫禮所以整民也，故會以訓上下之則，製财用之節，朝以正班爵之義，帥長幼之序。","sortOrder":109},
  {"id":"s_work_nvlt_39_110","chapterId":"ch_work_nvlt_39","text":"《孟子》曰：諸侯朝天子曰述職，一不朝則貶其爵，二不朝則削其地，三不朝則六師移之。","sortOrder":110},
  {"id":"s_work_nvlt_39_111","chapterId":"ch_work_nvlt_39","text":"挚虞决疑要註曰：漢製，會於建始殿，晉製，大會於太極殿，小會於東堂，會則五時服，庭設金石，武贲旄頭，文衣繡［《太平御覽》五百三十九作鶡。］尾。","sortOrder":111},
  {"id":"s_work_nvlt_39_112","chapterId":"ch_work_nvlt_39","text":"又曰：宴之與會，威儀不同也，會隨五時朝服，庭設金石，旄頭之［御覽作文。］衣鶡尾以列陛，宴則服常服，設絲竹之樂，宿衛列仗，會［御覽會上有大字。］於太極殿，小會於東堂。","sortOrder":112},
  {"id":"s_work_nvlt_39_113","chapterId":"ch_work_nvlt_39","text":"《白虎通》曰：凡臣見君，必有贽，贽者，质也，致己质誠也，公侯以玉為贽者，取其燥不輕，濕不重也，大夫以雁為贽者，取其飛成行，立成列也，士以野雞，使其不可誘之以食，胁之以威，畢死不可畜也。又諸侯相聘，為相尊敬也，朝聘天子，更以所尊，考禮正刑一德，以尊天子也。","sortOrder":113},
  {"id":"s_work_nvlt_39_114","chapterId":"ch_work_nvlt_39","text":"又曰：聘者，緣臣子欲知其君父無恙。又當奉土地所生珍物以助祭，是以皆行聘禮。","sortOrder":114},
  {"id":"s_work_nvlt_39_115","chapterId":"ch_work_nvlt_39","text":"又曰：朝，備文德而明禮義也。","sortOrder":115},
  {"id":"s_work_nvlt_39_116","chapterId":"ch_work_nvlt_39","text":"《春秋說題辭》曰：諸侯執政各來朝，講文德禮讓，製法四方。","sortOrder":116},
  {"id":"s_work_nvlt_39_117","chapterId":"ch_work_nvlt_39","text":"《尚書》曰：既月，乃日觐四嶽群牧，註雲，既，盡也，觐，見也，言舜日盡正月，乃見群牧。","sortOrder":117},
  {"id":"s_work_nvlt_39_118","chapterId":"ch_work_nvlt_39","text":"《穀梁傳》曰：滕侯薛侯來朝，天子無事，諸侯朝正也，考禮修德，所以尊天子也。","sortOrder":118},
  {"id":"s_work_nvlt_39_119","chapterId":"ch_work_nvlt_39","text":"又曰：六年，五服一朝。又六年，王乃時巡，考製度於四嶽，諸侯各朝於方嶽，大明黜陟，註雲，觐四方諸侯，各於其方嶽之下，大明考績。","sortOrder":119},
  {"id":"s_work_nvlt_39_120","chapterId":"ch_work_nvlt_39","text":"《漢書》曰：漢王已併天下，諸侯共尊為皇帝，於是叔孫通就其儀，漢七年，長樂宮成，諸侯群臣朝十月，皇帝輦出房，百官執戟傳警，引諸侯王以次奉贺，觴九行，謁者言罢酒，御史舉不如儀者，引去，竟朝置酒，無敢喧哗失禮，上曰：吾乃今日知為皇帝之貴也，拜通為太常。","sortOrder":120},
  {"id":"s_work_nvlt_39_121","chapterId":"ch_work_nvlt_39","text":"《漢官儀》曰：正月旦，天子幸德陽殿，臨軒，公卿大夫百官，各陪位朝贺，蠻貊胡羌朝貢畢，見屬郡計吏，皆陪觐，宗室諸劉雜會，皆冠兩梁冠，皂单衣，既定上寿，計吏中庭北向坐，太官上食，賜群臣酒食，作九賓，撤樂。","sortOrder":121},
  {"id":"s_work_nvlt_39_122","chapterId":"ch_work_nvlt_39","text":"又曰：大將軍三公朝會，天子為起，住入，太常住車曰：皇帝為群公起，天子坐，方前進。","sortOrder":122},
  {"id":"s_work_nvlt_39_123","chapterId":"ch_work_nvlt_39","text":"又曰：尚書令御史中丞司隸，朝會各獨席，故京師曰三獨坐。","sortOrder":123},
  {"id":"s_work_nvlt_39_124","chapterId":"ch_work_nvlt_39","text":"《魏志》曰：黃初元年，郭淮奉使贺文帝踐阼，而道路疾故，計遠近為稽留，及群臣懽會，帝责之曰：昔禹會諸侯於涂山，防風後至，便行大戮，今溥天同慶，而最留遲，何也，對曰：臣聞五帝先教，导民以德，夏後氏衰，始用刑辟，今臣遭虞舜之世，是以自知免於防風之戮也，帝悅。","sortOrder":124},
  {"id":"s_work_nvlt_39_125","chapterId":"ch_work_nvlt_39","text":"晉《起居註》曰：武帝太康元年詔曰：江表初平，天下同其歡豫，王公卿士，各奉禮稱慶，其於東堂小會，設樂，使加於常，五月庚寅，御臨軒，大會於太極殿前，四方贺使國子太學生司徒吏副將以上，及吳降將吏，皆與會，詔引歸命侯孫皓上殿，稽顙陳恩謝罪，稱萬歲。","sortOrder":125},
  {"id":"s_work_nvlt_39_126","chapterId":"ch_work_nvlt_39","text":"又曰：太常張華止，［《太平御覽》五百三十九作上書。］按舊事，拜公建始殿，因以小會，今拜公於太極殿，亦宜因以小會，蓋所以崇宰辅也。","sortOrder":126},
  {"id":"s_work_nvlt_39_127","chapterId":"ch_work_nvlt_39","text":"又曰：穆帝升平二年正月朔朝會，是日賜眾客醁醽酒。","sortOrder":127},
  {"id":"s_work_nvlt_39_128","chapterId":"ch_work_nvlt_39","text":"《東宮舊事》曰：正會儀，太子著遠遊冠，絳紗襮，登舆，至承華門，設位，拜二傅，二傅交禮畢，不复登車，太傅訓道在前，少傅訓從在後，太子入崇賢門，樂作，太子登殿，西向坐。","sortOrder":128},
  {"id":"s_work_nvlt_39_129","chapterId":"ch_work_nvlt_39","text":"【詩】魏陳王曹植應詔詩曰：命彼掌徒，肅我征旅，朝發鸞台，夕宿蘭渚，經彼公田，樂我稷黍，西濟關穀，或降忽升，騑驂倦路，載寢載興，將朝聖皇，匪敢燕寧，前驅舉燧，後乘抗旌，長懷永慕，忧心如酲。","sortOrder":129},
  {"id":"s_work_nvlt_39_130","chapterId":"ch_work_nvlt_39","text":"梁簡文帝守東平中華門开詩曰：脂車向馳道，總辔息中華，落關猶待漏，文戟未通車，薄雲初啟雨，曙色始成霞，巉流鋪紫若，城風泛橘花，絃誦終無取，顧己自懷嗟。","sortOrder":130},
  {"id":"s_work_nvlt_39_131","chapterId":"ch_work_nvlt_39","text":"梁何遜早朝詩曰：詰旦鍾聲罢，隱隱禁門通，蘧車响北闕，鄭履入南宮，宿霧开馳道，初日照相通，風胥徒紛驿，騶御或西東。","sortOrder":131},
  {"id":"s_work_nvlt_39_132","chapterId":"ch_work_nvlt_39","text":"周王褒入朝守門开詩曰：鳳池通複道，嚴駕早凌晨，鐵符行警曙，銀棨未开闉，巉暗城無影，晴新路不尘，屯兵引畫劍，騎吹動班輪，徒知御睿藻，抽辭殊未申。","sortOrder":132},
  {"id":"s_work_nvlt_39_133","chapterId":"ch_work_nvlt_39","text":"隋江總答王均早朝守建陽門开詩曰：金兔猶懸魄，銅龍欲啟扉，三條息行火，百雉照初暉，御溝槐影出，仙掌露光晞。","sortOrder":133},
  {"id":"s_work_nvlt_39_134","chapterId":"ch_work_nvlt_39","text":"【表】陳王曹植請赴元正表曰：欣豫百官之美，想見朝觐之禮，耳存九成，目想率舞。","sortOrder":134},
  {"id":"s_work_nvlt_39_135","chapterId":"ch_work_nvlt_39","text":"又謝得入表曰：不世之命，非所致思，有若披浮雲而曬白日，出幽穀而登乔木，目希庭燎，心存泰極。","sortOrder":135},
  {"id":"s_work_nvlt_39_136","chapterId":"ch_work_nvlt_39","text":"◇燕會","sortOrder":136},
  {"id":"s_work_nvlt_39_137","chapterId":"ch_work_nvlt_39","text":"《周官》曰：以饗燕之禮，親四方之賓客，言四方之賓客來聘，王為設饗燕之禮。","sortOrder":137},
  {"id":"s_work_nvlt_39_138","chapterId":"ch_work_nvlt_39","text":"《毛詩》曰：鹿鳴，燕群臣嘉賓也，常棣，燕兄弟，湛露，天子燕諸侯也。","sortOrder":138},
  {"id":"s_work_nvlt_39_139","chapterId":"ch_work_nvlt_39","text":"又曰：伐木，燕朋友故舊也，自天子至於庶人，未有不須友以成也，親親以睦，友賢不弃，故舊不遺，則民德歸厚矣。","sortOrder":139},
  {"id":"s_work_nvlt_39_140","chapterId":"ch_work_nvlt_39","text":"《左傳》曰：魯文公即位，衛侯使大夫甯武子聘於魯，魯文公與武子燕，為賦湛露及彤弓之詩。","sortOrder":140},
  {"id":"s_work_nvlt_39_141","chapterId":"ch_work_nvlt_39","text":"又曰：衛侯燕莒成叔，甯惠子相，莒成叔傲，甯子曰：莒成叔家其亡乎，古之為饗食也，以觀威儀，省禍福，今子傲，取禍之道也。","sortOrder":141},
  {"id":"s_work_nvlt_39_142","chapterId":"ch_work_nvlt_39","text":"韓詩曰：不脱履而即度，［《初學記》十四作席。］謂之禮，下跣而止，［《初學記》十四作上。］謂之燕，能飲者飲，不能飲者，謂之醧，閉門不出客，謂之湎，禮記曰：奠酬而升歌，發德也，註雲，以詩之義，明賓主之禮。","sortOrder":142},
  {"id":"s_work_nvlt_39_143","chapterId":"ch_work_nvlt_39","text":"又曰：諸侯宴禮，俎豆牲醴荐，皆有等差，所以明貴賤也。","sortOrder":143},
  {"id":"s_work_nvlt_39_144","chapterId":"ch_work_nvlt_39","text":"《漢書》曰：高祖十二年，击黥布，還，過沛，留置酒，悉召故人父老諸母樂飲，道舊故為笑樂，上留帳飲三日，召沛中兒百二十人，上击筑，歌大風。","sortOrder":144},
  {"id":"s_work_nvlt_39_145","chapterId":"ch_work_nvlt_39","text":"《東觀漢記》曰：建武三年，幸舂陵，祠園廟，大置酒，與父老故人相樂，十九年，幸汝南頓正令舍，大置酒，賜吏民，复南頓田租一年。","sortOrder":145},
  {"id":"s_work_nvlt_39_146","chapterId":"ch_work_nvlt_39","text":"魏書曰：文帝為魏王，南征次谯，大饗六軍及父老，設樂伎百戲。","sortOrder":146},
  {"id":"s_work_nvlt_39_147","chapterId":"ch_work_nvlt_39","text":"《世說》曰：過江諸人，每至暇日，辄相要出新亭，藉卉飲宴，周侯中坐而叹曰：風景不殊，舉目有江河之異，皆相视流淚，唯丞相愀然作色曰：當共戮力王室，剋复神州，何至作楚囚相對泣耶。","sortOrder":147},
  {"id":"s_work_nvlt_39_148","chapterId":"ch_work_nvlt_39","text":"沈約《宋書》曰：鄭鮮之為人通率，在高祖坐，言無所隱，時人甚憚焉，尤為高祖所狎，上嘗於內殿宴飲，朝貴畢集，唯不召鮮之，坐定，謂群臣曰：鄭鮮之必當自來，俄而外雲尚書郎鄭鮮之詣門，求啟事，高祖大笑，引入。","sortOrder":148},
  {"id":"s_work_nvlt_39_149","chapterId":"ch_work_nvlt_39","text":"【詩】古詩曰：今日良宴會，歡樂難具陳，彈筝奋逸响，新詩妙入神，齊心同所原，含意俱未申，人生寄一世，奄忽如飄尘，何不策高足，先據要路津，無為守窮賤，轗〈車禀〉長苦辛。","sortOrder":149},
  {"id":"s_work_nvlt_39_150","chapterId":"ch_work_nvlt_39","text":"魏陳王曹植公宴詩曰：公子敬愛客，終宴不知疲，清夜遊西園，飛蓋相追隨，明月澄清景，列宿正參差，秋蘭被長坂，朱華冒绿池，潛魚躍清波，好鳥鳴高枝，神飆接丹轂，輕輦隨風移。","sortOrder":150},
  {"id":"s_work_nvlt_39_151","chapterId":"ch_work_nvlt_39","text":"又侍太子坐詩曰：白日曜青春，時雨靜飛尘，寒冰辟炎景，涼風飄我身，清醴盈金觴，肴饌縱橫陳，齊人進奇樂，歌者出西秦，翩翩我公子，機巧忽若神。","sortOrder":151},
  {"id":"s_work_nvlt_39_152","chapterId":"ch_work_nvlt_39","text":"又與丁廙詩曰：嘉賓填城闕，丰膳出中厨，吾與二三子，曲宴此城隅，秦筝發西氣，齊瑟扬東呕，肴來不虛滿，觴至反無餘。","sortOrder":152},
  {"id":"s_work_nvlt_39_153","chapterId":"ch_work_nvlt_39","text":"魏應玚公宴詩曰：开馆延群士，置酒於斯堂，辨論釋常結，援筆興文章，穆穆眾君子，好合同歡康，促坐褰重帷，傳滿騰羽觴。","sortOrder":153},
  {"id":"s_work_nvlt_39_154","chapterId":"ch_work_nvlt_39","text":"魏劉楨公宴詩曰：永日行遊戲，歡樂猶未央，遺思在玄夜，相與复翱翔，輦車飛素蓋，從者盈路傍，月出照園中，珍树鬱蒼蒼，清川過石渠，流波為魚防，芙蓉散其花，菡萏溢金塘，珍鳥宿水裔，仁獸遊飛梁，投翰長叹息，綺麗不可忘。","sortOrder":154},
  {"id":"s_work_nvlt_39_155","chapterId":"ch_work_nvlt_39","text":"魏王粲公宴會詩曰：昊天降丰泽，百卉挺葳蕤，涼風彻蒸暑，青雲却炎暉，高會君子堂，併坐荫華榱，嘉肴充圓方，旨酒盈金罍，常聞詩人語，不醉且無歸，原我賢主人，與天享巍巍，克符周公業，弈世不可追。","sortOrder":155},
  {"id":"s_work_nvlt_39_156","chapterId":"ch_work_nvlt_39","text":"魏陳琳宴會詩曰：凯風飄陰雲，白日扬素暉，良友招我遊，高會宴中闈，玄鶴浮清泉，綺树煥青蕤。","sortOrder":156},
  {"id":"s_work_nvlt_39_157","chapterId":"ch_work_nvlt_39","text":"晉武帝華林園詩曰：習習春陽，帝出乎震，天施地生，以應仲春，思文聖皇，順時秉仁，钦若靈則，飲御嘉賓，洪恩普畅，慶乃眾臣，［其一。］","sortOrder":157},
  {"id":"s_work_nvlt_39_158","chapterId":"ch_work_nvlt_39","text":"其慶惟何，錫以帝祉，肆觐群後，有客戾止，外納要荒，內延卿士，箫管詠德，八音鹹理，凯樂飲酒，莫不宴喜，［其二。］","sortOrder":158},
  {"id":"s_work_nvlt_39_159","chapterId":"ch_work_nvlt_39","text":"晉陆機擬今日良宴會詩曰：閒夜命歡友，置酒迎風馆，齊童梁甫吟，秦娥張女彈，哀音繞棟宇，遺响入雲漢，人生無幾何，為樂常苦晏，譬彼司晨鳥，扬聲當及旦。","sortOrder":159},
  {"id":"s_work_nvlt_39_160","chapterId":"ch_work_nvlt_39","text":"又皇太子賜宴詩曰：明明隆晉，茂德有赫，思媚上帝，配天光宅，誕育皇储。儀形在昔，徽言時宣，福祿來格，勞謙降貴，肆敬下臣，肇彼先驅，翻成嘉賓。","sortOrder":160},
  {"id":"s_work_nvlt_39_161","chapterId":"ch_work_nvlt_39","text":"又侍皇太子宣猷堂詩曰：篤生我後，克明克秀，體暉重光，承規景數，茂德冲深，天姿玉裕，三正迭紹，洪聖啟運，自昔哲王，先天而順，群辟崇替，降及近古，黃暉既渝，素靈承祜，三後始基，世武丕丞，协風傍駭，天晷仰澄，自彼河汾，奄齊七政，時文惟晉，世篤其聖，明明隆晉，茂德有赫。","sortOrder":161},
  {"id":"s_work_nvlt_39_162","chapterId":"ch_work_nvlt_39","text":"晉王贊侍皇太子宴始平王詩曰：亹亹聖胤，繼明重體，樂此常棣，其甘如荠。我有嘉宴，以洽百禮，煌煌同族，藹藹王僚，惟中惟外，如琼如瑤，湛湛朝雲。德靡不覆，玄黃所缀，文成采繡，政以神和，樂以安奏，一人有慶，萬邦是祐。","sortOrder":162},
  {"id":"s_work_nvlt_39_163","chapterId":"ch_work_nvlt_39","text":"又侍皇太子祖道楚淮南二王詩曰：於明聖晉，仰統天緒，易以明险，簡以知阻，研彼群慮，俾侯授土，鬱鬱二王，祗承皇命，睹離鑒親，觀禮知盛，皇储降會，延於公姓，瞻彼行役，併憩同林，分涂殊軌，靡不回心。","sortOrder":163},
  {"id":"s_work_nvlt_39_164","chapterId":"ch_work_nvlt_39","text":"晉陆雲侍大將軍宴詩曰：茫茫宇宙，天地交泰，王在華堂，式宴嘉會，玄暉峻朗，翠雲崇霭，冕卉振纓，藻服垂帶，祁祁臣僚，有來雍雍，薄言載考，承顏下風，俯觌前客，仰瞻玉容，天錫難老，如嶽之崇。","sortOrder":164},
  {"id":"s_work_nvlt_39_165","chapterId":"ch_work_nvlt_39","text":"宋鮑昭侍宴覆舟山應詔詩曰：繁霜飛玉闼，愛景麗皇州，清跸式馳路，羽蓋佇宣遊，神居既崇盛，巖险信周流，禮俗陶德聲，昌會溢民謳。","sortOrder":165},
  {"id":"s_work_nvlt_39_166","chapterId":"ch_work_nvlt_39","text":"梁王僧孺侍宴景陽樓詩曰：金鋪烁可鏡，桂棟俨臨雲，霑觴均飲德，服道验朝聞，詎論禹無間，非恥尧為君，小臣亦何者，短翮屢追群。","sortOrder":166},
  {"id":"s_work_nvlt_39_167","chapterId":"ch_work_nvlt_39","text":"又侍宴詩曰：麗景屬春餘，清陰澄夏首，交枝隱脩径，回流影遙阜，徒為轹輕筠，移鑾拂高柳，去矣勞茂績，勉哉報嘉誘，小臣良不才，涓尘愧所守，何用勝彫斫，譬木良如朽。","sortOrder":167},
  {"id":"s_work_nvlt_39_168","chapterId":"ch_work_nvlt_39","text":"又侍宴詩曰：回舆避暑宮，下輦迎風馆，散漫輕煙轉，霏微商雲散，蔓草亘巖垂，高枝起天半，回風稍驚水，落光漸斜岸，妙舞駐行雲，清歌入曾漢，睟顏畅有怿，德音良已粲。","sortOrder":168},
  {"id":"s_work_nvlt_39_169","chapterId":"ch_work_nvlt_39","text":"梁庾肩吾侍宴詩曰：沐道逢將聖，飛觴屬上賢，仁風开美景，瑞氣動非煙，秋树翻黃葉，寒池墮黑莲，承恩謝命淺，念報在身前。","sortOrder":169},
  {"id":"s_work_nvlt_39_170","chapterId":"ch_work_nvlt_39","text":"又侍宴詩曰：副君時暇豫，曾城聊近遊，清池寫飛閣，疏树出龍樓，北陆冰方壮，西園春欲周，梅心芳屢動，蒲節促難抽，徒然頒併命，無以廁應劉。","sortOrder":170},
  {"id":"s_work_nvlt_39_171","chapterId":"ch_work_nvlt_39","text":"又侍宣猷堂宴湘東王詩曰：陳王驂駕反，副後西園遊，併命登飛閣，列坐對芳洲，桂巖逢暮序，菊水值窮秋，竹径箫聲發，相門琴曲愁，徒奉文成誦，空知思若抽。","sortOrder":171},
  {"id":"s_work_nvlt_39_172","chapterId":"ch_work_nvlt_39","text":"梁劉孝綽侍宴詩曰：清宴延多士，鸿漸濫微薄，臨猋出蕙樓，望辰跻菌閣，上征切雲漢，晚眺周京洛，城寺鬱參差，街衢紛漠漠，禁林寒氣晚，方秋未搖落，皇心重發志，賦詩追併作，自昔承天寵，於茲被人爵，選言非綺绡，何以俨金雘。","sortOrder":172},
  {"id":"s_work_nvlt_39_173","chapterId":"ch_work_nvlt_39","text":"又侍宴詩曰：茲堂乃峭峤，伏槛臨曲池，树中望流水，竹里見攒枝，欄高景難蔽，岫隱雲易垂，邂逅逢休幸，朱跸曳青規，丘山不可答，葵藿空自知。","sortOrder":173},
  {"id":"s_work_nvlt_39_174","chapterId":"ch_work_nvlt_39","text":"又侍宴集賢堂應令詩曰：北閤時見啟，西園又已辟，官屬引鸿鷺，朝行命金碧，伊臣獨何取，隆恩徒自昔，布武登玉墀，委坐陪瑤席，綢缪參宴笑，淹留奉觴醳，壶人告漏晚，煙霞起將夕，反景入池林，餘光映泉石。","sortOrder":174},
  {"id":"s_work_nvlt_39_175","chapterId":"ch_work_nvlt_39","text":"又陪徐仆射晚宴於兒宅詩曰：天君追宴憙，十日遞來過，筑室華池上，开軒臨芰荷，方塘交密筍，對霤接繁柯，景移林改色，風去水餘波，洛城雖半日，愛客待驪歌。","sortOrder":175},
  {"id":"s_work_nvlt_39_176","chapterId":"ch_work_nvlt_39","text":"梁江淹擬魏帝遊宴詩曰：置酒坐飛閣，逍遙臨華池，神飄自遠至，左右芙蓉披，绿竹夹清水，秋蘭被幽崖，月出照園中，冠佩相追隨，肅肅廣殿陰，雀聲愁北林，眾賓還城邑，何用慰我心，陳徐陵侍宴詩曰：園林才有熱，夏淺更勝春，嫩竹猶含粉，初荷未聚尘，承恩豫下席，應阮獨何人。","sortOrder":176},
  {"id":"s_work_nvlt_39_177","chapterId":"ch_work_nvlt_39","text":"隋江總賦得置酒殿上詩曰：三清傳旨酒，柏梁奉歡宴，霜雲動玉葉，冻水疏金箭，羽籥响鍾石，流泉灌金殿，盛時不再得，光景馳如電。","sortOrder":177},
  {"id":"s_work_nvlt_39_178","chapterId":"ch_work_nvlt_39","text":"◇封禪","sortOrder":178},
  {"id":"s_work_nvlt_39_179","chapterId":"ch_work_nvlt_39","text":"《禮記》曰：昔先王因天事天，因地事地，因名山升中於天，［中，成也，祭天告以成功也。］","sortOrder":179},
  {"id":"s_work_nvlt_39_180","chapterId":"ch_work_nvlt_39","text":"河圖真紀曰：王者封太山，禪梁甫，易姓奉度，繼崇功也。","sortOrder":180},
  {"id":"s_work_nvlt_39_181","chapterId":"ch_work_nvlt_39","text":"河圖會昌符雲，漢太興之道，在九代之王，封於太山，刻石著紀，禪於梁甫，退考功。","sortOrder":181},
  {"id":"s_work_nvlt_39_182","chapterId":"ch_work_nvlt_39","text":"春秋含孳曰：天子所以昭察，以從斗枢，禁令天下，系體守文，宿思以合神，保長久，天子受符，以辛日立號。","sortOrder":182},
  {"id":"s_work_nvlt_39_183","chapterId":"ch_work_nvlt_39","text":"《史記》曰：齊桓公欲封禪，管仲曰：古封太山，禪梁甫，七十二家，夷吾所記，十有二焉，無懷氏封泰山，禪雲雲，颛頊封泰山，禪雲雲，神農封泰山，禪雲雲，炎帝封泰山，禪雲雲，黃帝封泰山，禪亭亭，帝喾封泰山，禪雲雲，尧封泰山，禪雲雲，舜封泰山，禪雲雲，禹封泰山，禪會稽，湯封泰山，禪雲雲，周成王封泰山，禪社首，皆受命，然後得封禪，古之封禪，鄗上之黍，北里之禾，所以為盛，江淮之間，一茅三脊，所以為籍，東海致比目之魚，西海致比翼之鳥，然後有不召而自至者，十有五焉。","sortOrder":183},
  {"id":"s_work_nvlt_39_184","chapterId":"ch_work_nvlt_39","text":"又曰：秦始皇既併天下，即帝位，徵齊魯儒士，博士七十人，至泰山下，議曰：古者封禪為蒲車，惡傷山之土石草木，始皇上泰山立石，頌始皇德，明其得封也，封藏皆秘，代不得而記也，始皇上泰山，中坂遇風雨，休於树下，因封其树為五大夫。","sortOrder":184},
  {"id":"s_work_nvlt_39_185","chapterId":"ch_work_nvlt_39","text":"又曰：封禪則不死，黃帝是也，儒者皮弁荐紳，射牛，封太山，如郊太一之禮。","sortOrder":185},
  {"id":"s_work_nvlt_39_186","chapterId":"ch_work_nvlt_39","text":"又曰：李少君上言雲，縱遠方奇獸飛禽及白雉以加祀，皆至太山，其夜若有光。晝有白雲起封中。","sortOrder":186},
  {"id":"s_work_nvlt_39_187","chapterId":"ch_work_nvlt_39","text":"《白虎通》曰：天以高為尊，地以厚為德，故增太山之高以報天，附梁父之厚以報地也。","sortOrder":187},
  {"id":"s_work_nvlt_39_188","chapterId":"ch_work_nvlt_39","text":"又曰：易姓而王，必升封太山，報告成。","sortOrder":188},
  {"id":"s_work_nvlt_39_189","chapterId":"ch_work_nvlt_39","text":"又曰：或封禪，金泥銀繩，或曰石泥金繩，封之金印，或曰：封禪封之以金印。","sortOrder":189},
  {"id":"s_work_nvlt_39_190","chapterId":"ch_work_nvlt_39","text":"孝經序金［《太平御覽》五百三十六作鉤命。］决曰：封乎太山，考績燔燎，禪乎梁父，刻石紀功。","sortOrder":190},
  {"id":"s_work_nvlt_39_191","chapterId":"ch_work_nvlt_39","text":"《尚書·中候》曰：昔古聖王，功成道洽，符瑞出，乃封太山，今比目之魚不至，鳳皇不臻，未可以封，鄭玄註雲，比目東方異氣所生，名〈魚枼〉。","sortOrder":191},
  {"id":"s_work_nvlt_39_192","chapterId":"ch_work_nvlt_39","text":"司馬相如封禪書曰：然猶躡梁父，登太山，建昭號，施尊名，俾萬代得激清流，扬微波，飛英聲，騰茂實。","sortOrder":192},
  {"id":"s_work_nvlt_39_193","chapterId":"ch_work_nvlt_39","text":"封禪儀註曰：持禮三十人，上發壇上十石函蓋，尚書令北向跪，藏玉牒畢，持禮覆石函，尚書令封上石捡，亦治以金繩，泥雜用四方土，各依其色。","sortOrder":193},
  {"id":"s_work_nvlt_39_194","chapterId":"ch_work_nvlt_39","text":"張華議曰：海內符瑞之應，備物之盛，未有若今之盛，宜禮中嶽，封泰山，發德號。","sortOrder":194},
  {"id":"s_work_nvlt_39_195","chapterId":"ch_work_nvlt_39","text":"《漢官儀》曰：封禪太山，既［漢官儀作即。］武帝封處，累其石，登壇，置玉牒書封石此中，复封石捡。","sortOrder":195},
  {"id":"s_work_nvlt_39_196","chapterId":"ch_work_nvlt_39","text":"又曰：元封封禪，書［按當作晝。］有白氣，夜有光，下天關石門。","sortOrder":196},
  {"id":"s_work_nvlt_39_197","chapterId":"ch_work_nvlt_39","text":"又曰：有玉龟。","sortOrder":197},
  {"id":"s_work_nvlt_39_198","chapterId":"ch_work_nvlt_39","text":"又曰：建武二十二年，東巡狩，二月九日，到魯，十九日，國家居亭，百官布野，此日上山，雲氣成宮闕，百姓皆見。","sortOrder":198},
  {"id":"s_work_nvlt_39_199","chapterId":"ch_work_nvlt_39","text":"《漢書》曰：元封元年四月癸卯，上遷，［漢書武帝紀作還。］登封太山，應劭雲，成功治定，告成於天，有金策石函，金泥玉捡之封。","sortOrder":199},
  {"id":"s_work_nvlt_39_200","chapterId":"ch_work_nvlt_39","text":"又曰：倪宽對策雲，其封太山，禪梁父，昭姓考功，此帝王之盛節。","sortOrder":200},
  {"id":"s_work_nvlt_39_201","chapterId":"ch_work_nvlt_39","text":"《續漢書》曰：上以用石功難。又欲及二月封，故詔梁松，因故封石空捡，更加封而已，松上疏爭之，以為承天之敬，尤宜章明，今因舊封，竄寄玉牒故石下，恐非重命之義。","sortOrder":201},
  {"id":"s_work_nvlt_39_202","chapterId":"ch_work_nvlt_39","text":"又曰：建武二十二年，上許梁松等奏，方求元封時故事，議封禪所施用，有司奏當刻玉玺一枚，方寸三分，玉版方五寸。","sortOrder":202},
  {"id":"s_work_nvlt_39_203","chapterId":"ch_work_nvlt_39","text":"又曰：上御輦升山，日中後到山上，即位於壇南北，［《太平御覽》五百三十六北下有面字。］帝升壇，尚書令奉玉牒捡，皇帝以寸二分玺親封之。","sortOrder":203},
  {"id":"s_work_nvlt_39_204","chapterId":"ch_work_nvlt_39","text":"《吳志》曰：孫皓天玺元年，陽羨山有石室，所石［吳志三作在所。］表為天瑞，乃遣司空董朝周處等，封禪國山。","sortOrder":204},
  {"id":"s_work_nvlt_39_205","chapterId":"ch_work_nvlt_39","text":"《宋書》曰：江夏王義恭表雲，氣於宮树珍露味於林，［句有訛脱。］宜修封太山，瘞玉岱趾。","sortOrder":205},
  {"id":"s_work_nvlt_39_206","chapterId":"ch_work_nvlt_39","text":"《太康地記》曰：奉高者，以事東嶽，帝王禪代之處也，故明堂在縣南四里，漢武立太壇於東山，以登［《太平御覽》五百三十六作祭。］天下，［御覽下字無。］示增高。","sortOrder":206},
  {"id":"s_work_nvlt_39_207","chapterId":"ch_work_nvlt_39","text":"◇親蠶","sortOrder":207},
  {"id":"s_work_nvlt_39_208","chapterId":"ch_work_nvlt_39","text":"《禮記·祭義》曰：古者天子諸侯，必有公桑蠶室，近川而為之，筑宮仞有三尺，棘牆而外閉之。","sortOrder":208},
  {"id":"s_work_nvlt_39_209","chapterId":"ch_work_nvlt_39","text":"《祭統》曰：王後蠶於北郊，以供純服，夫人蠶於北郊，以供冕服，［純音緇也。］","sortOrder":209},
  {"id":"s_work_nvlt_39_210","chapterId":"ch_work_nvlt_39","text":"《五禮先蠶儀註》曰：親蠶前二日，太祝令，质明，以太牢祀先蠶。","sortOrder":210},
  {"id":"s_work_nvlt_39_211","chapterId":"ch_work_nvlt_39","text":"《皇後親蠶儀註》曰：皇後躬桑，始將一條，執筐受桑。","sortOrder":211},
  {"id":"s_work_nvlt_39_212","chapterId":"ch_work_nvlt_39","text":"周遷《古今舆服雜事》曰：蠶始生，後食之，三洒而止。","sortOrder":212},
  {"id":"s_work_nvlt_39_213","chapterId":"ch_work_nvlt_39","text":"晉元康義曰：皇後采桑壇，蠶宮西南。","sortOrder":213},
  {"id":"s_work_nvlt_39_214","chapterId":"ch_work_nvlt_39","text":"董巴《舆服志》曰：漢皇後桑於東郊苑中者。","sortOrder":214},
  {"id":"s_work_nvlt_39_215","chapterId":"ch_work_nvlt_39","text":"又曰：太皇太後入廟服，绀上皂下，蠶，青上縹下，簪以玳瑁，長一尺，端為華勝，上為鳳皇。","sortOrder":215},
  {"id":"s_work_nvlt_39_216","chapterId":"ch_work_nvlt_39","text":"《禮記》曰：季春之月，後妃斋戒躬桑，以勸蠶事，孟夏之月，蠶事既畢，後妃獻茧。","sortOrder":216},
  {"id":"s_work_nvlt_39_217","chapterId":"ch_work_nvlt_39","text":"又曰：蠶事既登，分茧稱絲，以供郊廟之服。","sortOrder":217},
  {"id":"s_work_nvlt_39_218","chapterId":"ch_work_nvlt_39","text":"又曰：後妃獻茧，乃收茧稅，以桑為均，貴賤長幼如一。","sortOrder":218},
  {"id":"s_work_nvlt_39_219","chapterId":"ch_work_nvlt_39","text":"《東觀漢記》曰：明德馬皇後，置織室蠶於濯龍中，數往來觀视。","sortOrder":219},
  {"id":"s_work_nvlt_39_220","chapterId":"ch_work_nvlt_39","text":"《漢書》曰：孝元王皇後為太後，幸蠶馆，率皇後及列侯夫人桑北郊。","sortOrder":220},
  {"id":"s_work_nvlt_39_221","chapterId":"ch_work_nvlt_39","text":"《藝文類聚》　唐·欧陽詢","sortOrder":221},
  {"id":"s_work_nvlt_40_1","chapterId":"ch_work_nvlt_40","text":"卷四十禮部下","sortOrder":1},
  {"id":"s_work_nvlt_40_2","chapterId":"ch_work_nvlt_40","text":"○冠婚謚弔冢墓","sortOrder":2},
  {"id":"s_work_nvlt_40_4","chapterId":"ch_work_nvlt_40","text":"《儀禮》曰：士冠禮，筮於廟門，主人玄冠朝服，緇帶素韠，即位於門東，門［儀禮士冠禮作西面。］有司如主人，即位於西方，筮賓，如求日之儀，祝曰：令月吉日，始加元服，弃爾幼志，從爾成德，寿考唯祺，介爾景福。又再加曰：吉月令辰，乃申爾服，敬爾威儀，淑慎有德，眉寿萬年，永受厥福。又三加曰：以歲之正，以月之令，鹹加爾服，兄弟具在，以成厥德，黃耇無疆，受天之慶。","sortOrder":4},
  {"id":"s_work_nvlt_40_5","chapterId":"ch_work_nvlt_40","text":"又醴辭曰：甘醴惟享，嘉荐令芳，拜受祭之，以定爾祥，承天之休，寿考不忘。","sortOrder":5},
  {"id":"s_work_nvlt_40_6","chapterId":"ch_work_nvlt_40","text":"又醮辭曰：旨酒既清，嘉荐以時，乃加元服，兄弟具來，孝友時格，永乃保之。又再醮曰：旨酒既清，嘉荐伊脯，乃伸爾服，禮儀有序，祭此嘉爵，承天之祜。","sortOrder":6},
  {"id":"s_work_nvlt_40_7","chapterId":"ch_work_nvlt_40","text":"又三醮曰：旨酒令芳，笾豆有楚，鹹加爾服，肴升嘉［《儀禮》作折。］俎，承天之慶，受福無疆。","sortOrder":7},
  {"id":"s_work_nvlt_40_8","chapterId":"ch_work_nvlt_40","text":"又字辭曰：禮儀既備，令月吉日，昭告爾字，愛［《儀禮》作爰。］字孔嘉，髦士攸宜，宜之於嘏，永受保之。","sortOrder":8},
  {"id":"s_work_nvlt_40_9","chapterId":"ch_work_nvlt_40","text":"《禮記》曰：始冠，緇布之冠也，太古冠布，齊則緇之，適子冠於阼，以著代也，醮於客位，加有成也，三加弥尊，喻其志也，冠而字之，敬其名也。","sortOrder":9},
  {"id":"s_work_nvlt_40_10","chapterId":"ch_work_nvlt_40","text":"又曰：成王冠，祝雍曰：使王近於民，遠於年，啬於時，惠於财，任賢使能。","sortOrder":10},
  {"id":"s_work_nvlt_40_11","chapterId":"ch_work_nvlt_40","text":"《大戴禮》曰：太子既冠，成人，免於傅保，則有司過之史，有虧膳之宰，太子有過，史必書之。","sortOrder":11},
  {"id":"s_work_nvlt_40_12","chapterId":"ch_work_nvlt_40","text":"《漢記》曰：馬防子鉅，為常從小侯，上欲冠鉅，夜拜為黃門郎，御章台，下殿陳鼎俎，自臨冠之禮。","sortOrder":12},
  {"id":"s_work_nvlt_40_13","chapterId":"ch_work_nvlt_40","text":"《漢書》曰：安帝桓帝獻帝加元服，併大赦，賜公卿金帛。","sortOrder":13},
  {"id":"s_work_nvlt_40_14","chapterId":"ch_work_nvlt_40","text":"【箴】萧子范子冠子箴曰：是月惟令，敬擇良辰，式遵士典，讠咅筮於賓，嘉字爰錫，醮酒方陳，禮莊爾质，德成爾身，永变童心，長移悼齒，朱錦辭發，青約在履，丹石為操，冰泉厲己，務簡朋匹，由蘇遊止，在我尚謙，推物盡美，面諂退言，弗納於耳，直絃矢辭，斯為良士。","sortOrder":14},
  {"id":"s_work_nvlt_40_16","chapterId":"ch_work_nvlt_40","text":"《釋名》曰：婚，昏時成禮也，姻，女因媒也。","sortOrder":16},
  {"id":"s_work_nvlt_40_17","chapterId":"ch_work_nvlt_40","text":"《爾雅》曰：女之夫曰婿，婿父母為姻，婦父母為婚。","sortOrder":17},
  {"id":"s_work_nvlt_40_18","chapterId":"ch_work_nvlt_40","text":"《禮記》曰：仲春之月，玄鳥至，至之日，以太牢祀高禖，［玄鳥，燕也，燕以來巢，室於嫁娶之家，媒氏以為候也。］","sortOrder":18},
  {"id":"s_work_nvlt_40_19","chapterId":"ch_work_nvlt_40","text":"又曰：婚禮者，將合二姓之好，上以事宗廟，而下繼後世矣，故君重之。","sortOrder":19},
  {"id":"s_work_nvlt_40_20","chapterId":"ch_work_nvlt_40","text":"又曰：嫁女之家，三夜不息燭，思相離也，娶婦之家，三日不舉樂，思嗣親也，三月而廟見，稱來婦也，擇日而祭於祢，成婦之義也。","sortOrder":20},
  {"id":"s_work_nvlt_40_21","chapterId":"ch_work_nvlt_40","text":"又曰：夫婚禮萬世之始也，壹與之齊，終身不改，故夫死不嫁，男女別，然後父子親，父子親，然後義生，義生然後禮作，禮作然後萬物安，婿親御授，親之也，出乎大門，男帥女，女從男，夫婦之義由此始，婦人從人者也，幼從父兄，嫁從夫，夫死從子。","sortOrder":21},
  {"id":"s_work_nvlt_40_22","chapterId":"ch_work_nvlt_40","text":"又曰：納女於天子，曰備百姓，於國君，曰備酒漿，於大夫，曰備扫洒。","sortOrder":22},
  {"id":"s_work_nvlt_40_23","chapterId":"ch_work_nvlt_40","text":"又曰：哀公問孔子曰：冕而親迎，不已重乎，孔子對曰：合二姓之好，以繼先聖之後，以為天地宗廟社稷之主，君何謂已重乎，崔骃婚禮結言曰：乾坤其德，恒久不已，爰定天綱，夫婦作始，乃降英媛，有淑其儀，姬薑是侔，比則姚妫，載納嘉贽，申結鞶褵。","sortOrder":23},
  {"id":"s_work_nvlt_40_24","chapterId":"ch_work_nvlt_40","text":"《毛詩》曰：何彼秾矣，美王姬也，雖則王姬，亦下嫁於諸侯，車服不系其夫，下王後一等，猶執婦道，以成肅雍之德。","sortOrder":24},
  {"id":"s_work_nvlt_40_25","chapterId":"ch_work_nvlt_40","text":"又曰：豈其食魚，必河之鲂，豈其娶妻，必齊之薑，豈其食魚，必河之鯉，豈其娶妻，必宋之子。","sortOrder":25},
  {"id":"s_work_nvlt_40_26","chapterId":"ch_work_nvlt_40","text":"又曰：伐柯如之何，匪斧不克，娶妻如之何，匪媒不得。","sortOrder":26},
  {"id":"s_work_nvlt_40_27","chapterId":"ch_work_nvlt_40","text":"《左傳》曰：齊侯與蔡姬乘舟於囿，荡公，公变色，禁之不可，公怒，歸之，未之絕也，蔡人嫁之，齊侯以諸侯之師侵蔡，蔡潰，伐楚。","sortOrder":27},
  {"id":"s_work_nvlt_40_28","chapterId":"ch_work_nvlt_40","text":"又曰：楚昭王败，鍾建負季芊以從，將嫁季芊，芊辭曰：所以為女子，遠丈夫也，昔者鍾建負我矣，以妻鍾建。","sortOrder":28},
  {"id":"s_work_nvlt_40_29","chapterId":"ch_work_nvlt_40","text":"《白虎通》曰：天子諸侯，一娶［《太平御覽》五百四十一娶下有九女二字，此脱。］者何，重國廣繼也，法地有九州，承天之施，無所不生，一聚九女，亦足承君之施，九而無子，百無益也。","sortOrder":29},
  {"id":"s_work_nvlt_40_30","chapterId":"ch_work_nvlt_40","text":"鄭氏婚禮謁文曰：納采，始相與言語，采擇可否之時，問名，謂問女名，將歸上［《初學記》十四作卜。］之也，納吉，謂歸卜吉，往告之也，納徵，用束帛，徵成也，請期，謂吉日將親迎，謂成禮也。","sortOrder":30},
  {"id":"s_work_nvlt_40_31","chapterId":"ch_work_nvlt_40","text":"劉恢與范註［按當作汪。］論婚事曰：禮無拜時，拜時出於末世耳，將以世族多虛，吉事宜速，故以好歲拜時，新年便可婚也。","sortOrder":31},
  {"id":"s_work_nvlt_40_32","chapterId":"ch_work_nvlt_40","text":"《列女傳》曰：邵南申女者，申人之女也，既許嫁於丰，夫家不備而欲迎之，女也遂不肯往，夫家訟之於理，致之於獄，女終以一物不具，一禮不備，守節持義，必死不往。","sortOrder":32},
  {"id":"s_work_nvlt_40_33","chapterId":"ch_work_nvlt_40","text":"《漢書》曰：陳平，邑富人張負，有女孫，五嫁夫辄死，平欲得之，邑中有大丧，平家貧，侍丧，以先往後罢為助，既見之丧所，隨平至其家，家乃負郭窮巷，然門外多長者車轍，負以女孫妻平，曰：固有美如陳平，而長貧賤者乎。","sortOrder":33},
  {"id":"s_work_nvlt_40_34","chapterId":"ch_work_nvlt_40","text":"又曰：張耳，大梁人也，常亡命遊外黃，外黃富人女甚美，庸奴其夫，亡抵父客，父客謂曰：必欲求賢夫，從耳，女聽為請，决嫁之，女家厚奉給耳，耳以故致千里客。","sortOrder":34},
  {"id":"s_work_nvlt_40_35","chapterId":"ch_work_nvlt_40","text":"又曰：張放取［原脱，據三十三卷寵幸篇引補。］皇後弟平恩侯許嘉女，上為放供帳，賜甲第，充乘舆服飾，時號為天子取婦，皇後嫁女，［事具人部寵幸篇。］","sortOrder":35},
  {"id":"s_work_nvlt_40_36","chapterId":"ch_work_nvlt_40","text":"《風俗通》曰：兩袒，俗說齊人有女，二人求之，東家子丑而富，西家子好而貧，父母疑不能决，問其女定所欲適，難指斥言者，偏袒令我知之，女便兩袒，怪問其故，雲欲東家食，西家宿，此為兩袒者也。","sortOrder":36},
  {"id":"s_work_nvlt_40_37","chapterId":"ch_work_nvlt_40","text":"《楚國先賢傳》曰：孫俊，字文英，與李元禮俱娶太尉桓焉女，時人謂桓叔元兩女俱乘龍，言得婿如龍也。","sortOrder":37},
  {"id":"s_work_nvlt_40_38","chapterId":"ch_work_nvlt_40","text":"《世說》曰：王戎俭吝，其從子婚，與一单衣裁，後更责之，戎女適裴氏，貸錢數萬，女歸，戎色不說，女還錢，乃怿。","sortOrder":38},
  {"id":"s_work_nvlt_40_39","chapterId":"ch_work_nvlt_40","text":"又曰：溫峤從［《太平御覽》五百四十一下有姑字。］劉氏家，值亂離，唯有一女，甚有慧，姑以屬峤索婚，峤密自有婚意，答雲，佳婿難得，但如峤比雲何，姑答曰：丧破之餘，乞得粗相存活，便足慰吾餘年，敢希汝比，却數日，峤報姑雲，已得婚處，門地粗可，婿身不减峤，因下玉鏡台一枚，姑大喜，既婚交禮，女以手披紗扇大笑，固嫌是此老奴，果如所疑，玉鏡台是峤為劉越石長史北征劉聰所得也。","sortOrder":39},
  {"id":"s_work_nvlt_40_40","chapterId":"ch_work_nvlt_40","text":"【詩】晉嵇含伉俪詩曰：餘執百兩辔，之子詩采蘩，我被双絲絹，著以同功綿，夏搖比翼扇，冬臥蛩蛩氈，飢餐併糧粒，渴飲一流泉，臨軒树萱草，中庭植合歡。","sortOrder":40},
  {"id":"s_work_nvlt_40_41","chapterId":"ch_work_nvlt_40","text":"梁何遜看新婚詩曰：霧夕莲出水，霞朝日照梁，何如花燭夜，輕扇掩紅妆，良人已灼灼，席上自生光，所悲高駕動，環佩出長廊。","sortOrder":41},
  {"id":"s_work_nvlt_40_42","chapterId":"ch_work_nvlt_40","text":"梁劉瑗詠左右新婚詩曰：小使如初日，得婦類行雲，琴聲妾曾聽，桃子婿經分，娥眉參意畫，繡被共籠薰，偏增使君度，無趣遣相聞。","sortOrder":42},
  {"id":"s_work_nvlt_40_43","chapterId":"ch_work_nvlt_40","text":"陳周弘正看新婚詩曰：莫愁年十五，來聘子都家，婿顏如美玉，婦色勝桃花，帶啼疑暮雨，含笑似朝霞，暫却輕紈扇，傾城判不賒。","sortOrder":43},
  {"id":"s_work_nvlt_40_44","chapterId":"ch_work_nvlt_40","text":"【賦】魏陳王曹植感婚賦曰：陽氣動兮淑清，百卉鬱兮含英，春風起兮萧條，蟄虫出兮悲鳴，顧有懷兮妖人，用搔首兮屏營，澄清台以荡志，状高軒而遊情，悲良媒之不顧，懼歡媾之不成，慨仰首而叹息，風飄飖以動纓。","sortOrder":44},
  {"id":"s_work_nvlt_40_45","chapterId":"ch_work_nvlt_40","text":"晉張華感婚賦曰：婚姻者，競赴良時，雖葩英肯顧，乃作感婚賦曰：窈窕初茂，玉质始盛，容華外丰，心神內正，接軫連騎，隱隱習習，充街塞里，暉曜城邑，相麗姿之綽約兮，遙仿佛以感心，怨佳人之幽翳兮，恨檢防之高深。","sortOrder":45},
  {"id":"s_work_nvlt_40_46","chapterId":"ch_work_nvlt_40","text":"【箴】晉挚虞新婚箴曰：今在哲文，遭家不造，結發之麗，不同偕老，既納新配，內芬外藻，厚味腊毒，大命將夭，色不可耽，命不可輕，君子是憚，敢告後生。","sortOrder":46},
  {"id":"s_work_nvlt_40_47","chapterId":"ch_work_nvlt_40","text":"晉潘嶽答新婚箴曰：女實存色，男實好德，德在正色，色在不惑，故新舊兼弘，義申理得，君子過慮，愛己明箴，防微测顯，文麗旨深，敬納嘉誨，敢酬德音。","sortOrder":47},
  {"id":"s_work_nvlt_40_48","chapterId":"ch_work_nvlt_40","text":"晉王廙婦德箴曰：团团明月，魄滿則缺，亭亭陽暉，曜過則逝，天地猶有盈虧，况華艳之浮孽，是以淑女鑒之，戰戰乾乾，相彼七出，順此話言，懼茲屋漏，畏斯新垣，在昧無愧，幽不改虔。","sortOrder":48},
  {"id":"s_work_nvlt_40_49","chapterId":"ch_work_nvlt_40","text":"【啟】梁劉孝儀為王儀［全梁文六十一儀下有同字。］謝國姻啟曰：即日，主書王靜民宣敕，安告［全梁文作吉。］主降嫔臣第三息實，臣素里庸族，蓬衡賤品，事隔伊缗之禮，望絕下嫁之姬，而聖慈猥洽，皇姻曲建，荆布陋飾，已膺凡奖，負薪微胤，复降肅邕，頻煩叨荷，內外榮抃。","sortOrder":49},
  {"id":"s_work_nvlt_40_50","chapterId":"ch_work_nvlt_40","text":"【教】梁簡文帝資遣孔焘二女教曰：夫思人生至卿，［句有訛。］事惟悼往，表闾式墓，義匪字孤，至如遊殷之息，見撫張既，桥玄之子，受讬魏王，斯故美在令終，受兼身後，故無錫令孔焘，經術弘長，志履貞槩，遊處積年，一朝長往，聞其在室二女，併未有行，可廣訪姻家，務求偶對。","sortOrder":50},
  {"id":"s_work_nvlt_40_51","chapterId":"ch_work_nvlt_40","text":"◇謚《說文》曰：謚者，說行之跡也。","sortOrder":51},
  {"id":"s_work_nvlt_40_52","chapterId":"ch_work_nvlt_40","text":"韦昭辯《釋名》曰：古者諸侯薨，則天子論行以賜謚，唯王者無上，故於南郊稱天以謚之，當春秋時，周室卑微，臣謚其父，故諸侯之謚，多不以實。","sortOrder":52},
  {"id":"s_work_nvlt_40_53","chapterId":"ch_work_nvlt_40","text":"古史考曰：謚禮，待葬而謚，所以尊名也，其行善惡惡為謚，所以勉為善也。","sortOrder":53},
  {"id":"s_work_nvlt_40_54","chapterId":"ch_work_nvlt_40","text":"《禮記》曰：已孤暴貴，不為父作謚。","sortOrder":54},
  {"id":"s_work_nvlt_40_55","chapterId":"ch_work_nvlt_40","text":"又曰：公叔文子卒，其子請謚於君曰：日月有時，將葬矣，請所以易其名，君曰：昔者衛國凶飢，夫子為粥與國之饿者，是不亦惠乎，昔衛國有難，夫子以其死衛寡人，不亦貞乎，夫子聽衛國之政，修其班製，社稷不辱，不亦文乎，謚夫子貞惠文子。","sortOrder":55},
  {"id":"s_work_nvlt_40_56","chapterId":"ch_work_nvlt_40","text":"《大戴禮》曰：武王踐阼曰：謚者行之跡也，是以大行受大名，小行受小名，行出乎己，名出乎人。","sortOrder":56},
  {"id":"s_work_nvlt_40_57","chapterId":"ch_work_nvlt_40","text":"《左傳》曰：無駭卒，羽父請謚與族，公問於眾仲，眾仲對曰：天子建德，因生以賜姓，胙之土而命之氏，諸侯以字，官有世功則有官族，邑亦如之，公命以字，為展氏。","sortOrder":57},
  {"id":"s_work_nvlt_40_58","chapterId":"ch_work_nvlt_40","text":"《論語》曰：子夏問曰：孔文子何以謂之文也，子曰：敏而好學，不恥下問，是以謂之文也，［事具文部文质篇目。］","sortOrder":58},
  {"id":"s_work_nvlt_40_59","chapterId":"ch_work_nvlt_40","text":"《春秋說題辭》曰：號者功之表，謚者行之跡，所以追勸成德，使尚務節。","sortOrder":59},
  {"id":"s_work_nvlt_40_60","chapterId":"ch_work_nvlt_40","text":"《穆天子傳》曰：為盛姬謚曰哀淑人。","sortOrder":60},
  {"id":"s_work_nvlt_40_61","chapterId":"ch_work_nvlt_40","text":"《列女傳》曰：魯黔娄先生死，曾子與門人往弔焉，曰：何以為謚，其妻曰：以康為謚，昔者先生，君嘗賜之粟二十鍾，先生辭而不受，是其有餘富也，君嘗欲授之國相，先生辭而弗為，是有餘貴也，求仁而得仁，求義而得義，其謚為康，不亦宜乎。","sortOrder":61},
  {"id":"s_work_nvlt_40_62","chapterId":"ch_work_nvlt_40","text":"《漢書》曰：霍去病，元狩六年薨，上悼之，發屬國玄甲軍，陳自長安至茂陵，為冢象祁連山，謚之景桓侯，［謚法，仁義行刚曰景，辟土行遠曰桓。］","sortOrder":62},
  {"id":"s_work_nvlt_40_63","chapterId":"ch_work_nvlt_40","text":"又曰：贾山奏事曰：古者聖王作謚，三四十世爾，雖尧舜禹湯文武，累世廣德，以為子孫基業，無過二三十世也，秦始皇帝曰：死而以謚法，是父子名號，有時相袭也，以一至萬，則世世不相复也，故死而號曰始皇帝。","sortOrder":63},
  {"id":"s_work_nvlt_40_64","chapterId":"ch_work_nvlt_40","text":"《五經通義》曰：謚者死後之稱，累生時之行而謚之，生有善行，死有善謚，所以勸善戒惡也，謚之言列其所行，身雖死，名常存，故謂謚也。","sortOrder":64},
  {"id":"s_work_nvlt_40_65","chapterId":"ch_work_nvlt_40","text":"《東觀漢記》曰：吳漢爵位奉賜最尊重，然但治宅，不起巷第，恭俭如此，病薨，奏謚曰：有司議宜以為武昭，特賜謚曰忠侯。","sortOrder":65},
  {"id":"s_work_nvlt_40_66","chapterId":"ch_work_nvlt_40","text":"張璠《漢記》曰：范丹，中平二年卒，三府各遣令史奔弔，累行論謚，佥曰宜為貞節先生，會葬二千餘人。","sortOrder":66},
  {"id":"s_work_nvlt_40_67","chapterId":"ch_work_nvlt_40","text":"荀氏家傳曰：荀爽對策曰：臣聞火生於木，故其德孝，漢之謚帝稱孝者，其義取此也，故漢製，使天下皆誦孝經，選吏則舉孝廉，以孝為務也。","sortOrder":67},
  {"id":"s_work_nvlt_40_68","chapterId":"ch_work_nvlt_40","text":"《中興書》曰：中宗即尊號也，時賜謚多由封爵，不考德行，王导曰：近代以來，唯爵得謚，武官牙門，有爵必謚，卿校常伯，無爵悉不賜謚，甚失製謚之本，今中興肇建，勋德兼備，宜深體前訓，使行以謚彰，中宗納焉，自後公卿無爵而謚，自导始也。","sortOrder":68},
  {"id":"s_work_nvlt_40_69","chapterId":"ch_work_nvlt_40","text":"【表】梁陆倕為張缵謝兄尚書謚靖子表曰：亡兄夙遘皇慈，早邀靈慶，立言著績，未酬天寵，門衰祚寡，遽辭昌運，拊心摧恨，私懷罔極，日月告時，幽埏浸遠，王人猥集，佳册光臨，榮溢里庭，恩沉松槚。","sortOrder":69},
  {"id":"s_work_nvlt_40_70","chapterId":"ch_work_nvlt_40","text":"【議】晉張華晉文王謚議曰：殊位盛禮，實隆明德，班爵崇寵，亦光茂勋，至於表名赠號，世考洪烈，冠聲無窮者，莫尚於號謚也，論功高於禹稷，比德邁於伊周。","sortOrder":70},
  {"id":"s_work_nvlt_40_71","chapterId":"ch_work_nvlt_40","text":"【書】齊虞義［按當作羲。］與萧令王仆射書，為袁彖求謚曰：袁侍中體高亮之宏姿，挺孤奇之逸操，孝友結於衡闾，忠正表於邦域，懷抱七經，該綜百氏，清文麗目，幾義窮神，言非義而不發，容导禮而後動，居貧無悶，事等安期，處顯不驚，道均無叹，兄弟親從，同居共财，怡怡雍穆，人所不間，顧與善無徵，報施徒語，岱山委岫，崑嶽摧峰，四海搢紳，誰不掩泣，明公德冠時宗，道高物表，若得橫議聖時，斟酌今古，采茂實於當年，褾芳流於千載，馳徽謚於山道，润貞氣於泉門，豈非體國之至公，典謨之盛軌者哉。","sortOrder":71},
  {"id":"s_work_nvlt_40_73","chapterId":"ch_work_nvlt_40","text":"《左傳》曰：齊侯遇杞梁之妻於郊，使弔之，辭曰：殖之有罪，何辱命焉，若免於罪，猶有先人之弊庐在，下妾不得與於郊弔，齊侯弔諸其室。","sortOrder":73},
  {"id":"s_work_nvlt_40_74","chapterId":"ch_work_nvlt_40","text":"又曰：莊公十一年，宋大水，公使弔焉，曰：天作淫雨，害於粢盛，若之何不弔，對曰：孤實不敬，天降之灾，以為君忧，拜命之辱。","sortOrder":74},
  {"id":"s_work_nvlt_40_75","chapterId":"ch_work_nvlt_40","text":"《禮記》曰：知生者弔，知死者傷，知生而不知死，弔而不傷，知死而不知生，傷而不弔，弔丧弗能赙，弗問其所欲。","sortOrder":75},
  {"id":"s_work_nvlt_40_76","chapterId":"ch_work_nvlt_40","text":"又曰：五十無車者，不越疆而弔人，弔於人，是日不樂，婦人不越疆而弔人，行弔之日，不飲酒食肉焉，弔於葬者，必執引，若從及壙，皆執紼。","sortOrder":76},
  {"id":"s_work_nvlt_40_77","chapterId":"ch_work_nvlt_40","text":"又曰：子夏丧其子而丧其明，曾子弔之曰：吾聞之曰：朋友丧明，則哭之。","sortOrder":77},
  {"id":"s_work_nvlt_40_78","chapterId":"ch_work_nvlt_40","text":"《家語》曰：史魚將卒，命其子曰：吾在朝，不能進蘧伯玉，退弥子瑕，是不能正君，不可以成禮，我死，汝其置尸牖下，靈公弔焉，怪而問之，其子以父言告，公曰：寡人過也，令殯於客位，進蘧伯玉，退弥子瑕，孔子曰：史魚死而尸諫，可謂直乎，［事具人部諷篇。］","sortOrder":78},
  {"id":"s_work_nvlt_40_79","chapterId":"ch_work_nvlt_40","text":"《莊子》曰：孔子围於陳蔡之間，七日不火食，太公任弔之曰：幾死乎，曰：然，子惡死乎，曰：然，任曰：直木先伐，甘井先竭，子其意者，飾智以驚愚，修身以明行，昭昭乎如揭日月而行，故不免。","sortOrder":79},
  {"id":"s_work_nvlt_40_80","chapterId":"ch_work_nvlt_40","text":"又曰：莊子妻死，惠子弔之，則方箕踞鼓盆而歌。","sortOrder":80},
  {"id":"s_work_nvlt_40_81","chapterId":"ch_work_nvlt_40","text":"《淮南子》曰：北塞上之有憙道者，其馬無故亡入胡中，人皆弔之，其父曰：此何詎不乃為福，居數月，其馬將胡駿馬而歸，人皆贺之，其父曰：此何詎不乃為禍，家富馬良，其子騎馬，墮而拆髀，人皆弔之，其父曰：此何詎不乃為福，居一年，胡夷大出，丁壮者皆控絃而戰，塞上之人死者十九，此獨跂足，故子父相保，［事具戰部馬篇。］","sortOrder":81},
  {"id":"s_work_nvlt_40_82","chapterId":"ch_work_nvlt_40","text":"《說苑》曰：孫叔敖為楚令尹，吏民皆贺，有一老父，衣粗衣冠，後弔曰：身貴而驕人者，民去之，位高擅權者，民惡之，祿厚而不知止者，患處之，孫叔敖再拜曰：敬受命，原聞餘教，父曰：位已高而身益卑，意益大而心益小，祿已厚而慎不敢取，言［《太平御覽》五百六十一言字無。］君謹守此三者，足以治楚。","sortOrder":82},
  {"id":"s_work_nvlt_40_83","chapterId":"ch_work_nvlt_40","text":"《漢書》曰：龚勝死，有老父來弔，其哭甚哀，既而曰：嗟乎，薰以香自燒，膏以明自銷，龚生竟夭天年，非吾徒也，遂趍而出，莫知其誰。","sortOrder":83},
  {"id":"s_work_nvlt_40_84","chapterId":"ch_work_nvlt_40","text":"虞翻別傳曰：翻放弃南方，自恨疏斥，當長没海隅，生無可與語，死以青蠅為弔客，天下一人知己者，足以不恨，以典籍自慰。","sortOrder":84},
  {"id":"s_work_nvlt_40_85","chapterId":"ch_work_nvlt_40","text":"挚虞决疑要註曰：禮，臣丧其父母，則赴於君，君弔之，漢太傅胡廣丧母，天子使謁者，以中牢弔祭，具送葬，魏司空陳群丧母，使者弔祭如故事。又使黃門侍郎杜恕，奉詔慰問。","sortOrder":85},
  {"id":"s_work_nvlt_40_86","chapterId":"ch_work_nvlt_40","text":"又曰：國家同姓王公妃主，發哀於東堂，凡使者監哀弔祭同姓者，素冠帻，白練深衣，器用皆素，弔祭異姓者，服色器用不变也。","sortOrder":86},
  {"id":"s_work_nvlt_40_87","chapterId":"ch_work_nvlt_40","text":"又曰：古素冠錫衰為弔服，今以白袷深衣為服，深衣即单衣也，錫細麻疏也。","sortOrder":87},
  {"id":"s_work_nvlt_40_88","chapterId":"ch_work_nvlt_40","text":"【賦】漢司馬相如弔秦二世賦曰：登陂紘之長坂，入曾宮之嵯峨，臨曲江之溰州，望南山之參差，巖巖深山，涳々通穀，豁乎娀〈穀阑〉，泊乎溝〈革反〉以永逝，註平皋之廣衍，觀眾树之蓊薆，覽竹林之榛榛，東馳土山，北偈石瀨，弭節容與，歷弔二世，持身不謹，亡國失势，信讒不寤，宗廟滅絕，呜呼摻行之不得，墳墓芜秽而不修，魂魄亡歸而不食。","sortOrder":88},
  {"id":"s_work_nvlt_40_89","chapterId":"ch_work_nvlt_40","text":"晉傅鹹弔秦始皇賦曰：餘治獄至長安，觀乎阿房，而弔始皇曰：傷秦政之為暴，弃仁義以自亡，搦紙申辭，以弔始皇，有姬失統，命不於常，六國既平，奄有萬方，政虐刑酷，如火之扬，致周章之百萬，取發掘於項王，疲斯民乎宮墓，甚癸辛於夏商，未旋踵而為墟，屯獐麋乎廟堂，國既顛而莫扶，孰阻兵之為強。","sortOrder":89},
  {"id":"s_work_nvlt_40_90","chapterId":"ch_work_nvlt_40","text":"【文】漢贾誼弔屈原文曰：鸞鳥伏竄，鴟枭翱翔，謂隨夷溷兮，跖蹻為廉，莫耶為钝兮，鉛刀為銛，騰駕罢牛驂蹇驢，骥垂兩耳服鹽車，所貴聖人之神德，遠濁世而自藏，使騏麟可系而羁，豈雲異夫犬羊。","sortOrder":90},
  {"id":"s_work_nvlt_40_91","chapterId":"ch_work_nvlt_40","text":"後漢蔡邕弔屈原文曰：鸋窸軒翥，鸞鳳挫翮，啄碎琬琰，寶其瓴甋，皇車奔而失轄，執辔忽而不顧，卒坏覆而不振，顧抱石其何補。","sortOrder":91},
  {"id":"s_work_nvlt_40_92","chapterId":"ch_work_nvlt_40","text":"晉潘嶽弔孟嘗君文曰：人罔貴賤，士無真伪，延入如歸，望賓若企，出掘秦機，入专齊政，右眄而嬴強，左顧而田競，且以造化為水，天地為舟，樂則齊喜，哀則同忧，豈區區之國，而大邦是謀，琐琐之身，而名利是求，畏首畏尾，東奔而囚，志撓於木偶，命懸於狐裘。","sortOrder":92},
  {"id":"s_work_nvlt_40_93","chapterId":"ch_work_nvlt_40","text":"晉陆機弔魏武帝文曰：夫以回天倒日之力，而不能振形骸之內，濟世夷難之智，而受困魏闕之下，格乎上下者，藏於區區之木，光於四表者，翳乎蕞爾之土，雄心權於弱憤，壮圖終於哀志，長筭屈於短日，遠跡頓於促路，持姬女而指季豹以示四子曰：以累汝，因泣下，傷哉，曩以天下自任，今以愛子讬人。","sortOrder":93},
  {"id":"s_work_nvlt_40_94","chapterId":"ch_work_nvlt_40","text":"又曰：吾婕妤伎人，皆著銅爵台上，施六尺床，下繐帳，朝脯設脯糒之屬，月朝十五日，辄向帳作伎，汝等時時登銅雀台，望吾西陵墓田。又雲，餘香可與諸夫人，諸舍中無為，學作履組賣也，吾歷官所得絹，皆著藏中，吾餘衣裘，可別為一藏，不能者，兄弟可共分之，威先天而蓋世，力荡海而拔山，厄奚险而弗濟，敵何強而不殘，违率土以靖寐，戢弥天之一棺，惜內顧之纏綿，恨未命之微詳，紆家人於履組，尘清慮於餘香，結遺情之婉娈，何命促而意長，宣備物於虛器，發哀音於舊倡，矯戚容以赴節，掩零淚而荐觴，徵清絲而獨奏，進脯糒而誰嘗，悼繐帳之冥漠，怨西陵之茫茫，登雀台而群悲，眝美目其何望，覽遺籍以慷恺，獻茲文而凄傷。","sortOrder":94},
  {"id":"s_work_nvlt_40_95","chapterId":"ch_work_nvlt_40","text":"又弔蔡邕文曰：彼洪川之方割，豈一等［本集作簣。］之所堙，故尼父之惠訓，智必愚而後賢，谅知道之已妙，曷信道之未堅，忽甯子之保己，效萇叔之违天，冀澄河之遠日，忘朝露之短年。","sortOrder":95},
  {"id":"s_work_nvlt_40_96","chapterId":"ch_work_nvlt_40","text":"晉庾闡弔贾生文曰：飛榮洛汭，濯穎山東，质清浮磬，聲若孤桐，琅琅其璞，巖巖其峰，信道居正，天下為公，方駕逸步，不以曲路期通，是以張高絃悲，聲激柱落，清唱未和，而桑濮代作，昔皋陶謩虞，呂尚歸昌，德协允符，乃應帝王，夷吾相桓，漢登萧張，草庐三顧，臭若蘭芳，奈何摧景飆風，獨丧厥明，悠悠大素，存亡一指，道來斯通，世往斯否，吾哀其生，未見其死，敢不敬弔，寄之渌水。","sortOrder":96},
  {"id":"s_work_nvlt_40_97","chapterId":"ch_work_nvlt_40","text":"宋袁淑弔古文曰：贾誼發憤於湘江，長卿愁悉於園邑，彦真因文以悲出，伯喈衒史而求入，文舉疏誕以殃速，德祖精密而禍及，夫然，不患思之貧，無若識之淺，士以伐能見斥，女以驕色貽遣，以往古為鏡鑒，以未來為針艾，書餘言於子紳，亦何勞乎蓍蔡。","sortOrder":97},
  {"id":"s_work_nvlt_40_98","chapterId":"ch_work_nvlt_40","text":"◇冢墓","sortOrder":98},
  {"id":"s_work_nvlt_40_99","chapterId":"ch_work_nvlt_40","text":"《禮記》曰：《曾子》曰：朋友之墓，有宿草而不哭焉。","sortOrder":99},
  {"id":"s_work_nvlt_40_100","chapterId":"ch_work_nvlt_40","text":"又曰：趙文子與叔譽觀九原，《文子》曰：死如可作，吾誰與歸，叔譽曰：其陽處父乎，《文子》曰：其智不足稱也，其臼犯乎，《文子》曰：其仁不足稱也，我則隨武子乎，利君不忘其身，謀身不遺其友。","sortOrder":100},
  {"id":"s_work_nvlt_40_101","chapterId":"ch_work_nvlt_40","text":"《越絕書》曰：阖庐冢在昌門外，銅椁三重，洪池六尺，玉凫之流，扁諸之劍三千，幹將魚腸之劍在焉，十萬人筑治之，［吳越春秋又載，事具山部。］","sortOrder":101},
  {"id":"s_work_nvlt_40_102","chapterId":"ch_work_nvlt_40","text":"史記曰：樗里子卒，葬渭南章台之東，曰：後一百歲，當有天子之宮夹我墓，至漢興，長樂宮在其東，未央在其西，武库正當其墓。","sortOrder":102},
  {"id":"s_work_nvlt_40_103","chapterId":"ch_work_nvlt_40","text":"《漢書》曰：原涉自以先人墳墓俭約，非孝也，乃大治冢舍，周閣重門，初武帝時，京兆曹氏葬茂陵，民謂其道為京兆阡，涉墓［漢書九十二原涉傳作慕。］之，乃買地开道，立署曰南陽阡，人不肯從，謂之原氏阡。","sortOrder":103},
  {"id":"s_work_nvlt_40_104","chapterId":"ch_work_nvlt_40","text":"楊雄家諜曰：子雲以天鳳五年卒，葬安陵阪上，所厚沛郡桓君山，平陵如子禮，弟子鉅鹿侯芭，共為治丧，諸公遣世子朝臣郎吏行事者會送，桓君山為斂赙，起祠塋，侯芭負土作墳，號曰玄冢。","sortOrder":104},
  {"id":"s_work_nvlt_40_105","chapterId":"ch_work_nvlt_40","text":"《博物志》曰：漢滕公夏侯婴死，公卿送葬至東都門外，馬不行，殕地悲鳴，得石椁，有銘曰：佳城鬱鬱，三千年見白日，吁嗟滕公居此室，乃葬之。","sortOrder":105},
  {"id":"s_work_nvlt_40_106","chapterId":"ch_work_nvlt_40","text":"范晔《後漢書》曰：楊震為樊丰等所谮，飲酖卒，先葬十餘日，有大鳥，高丈餘，集震丧前，俯仰悲鳴，淚下霑地，葬畢乃飛去，於是立石鳥象於墓所。","sortOrder":106},
  {"id":"s_work_nvlt_40_107","chapterId":"ch_work_nvlt_40","text":"《梁州記》曰：武侯壘東南，有定軍山，入山十餘里，有諸葛武侯墓，鍾會征蜀，至漢川，祭亮之廟，令軍士不得於墓刍牧樵采，今松柏碑銘俨然。","sortOrder":107},
  {"id":"s_work_nvlt_40_108","chapterId":"ch_work_nvlt_40","text":"盛弘之《荆州記》曰：冠軍縣東，有魏征南軍司張詹墓，刻其碑背曰：白楸之棺，易朽之裳，銅鐵不入，瓦器不藏，嗟矣後人，幸勿我傷，至元嘉六年，民飢，始被發，金銀朱漆之器，雕刻烂然。","sortOrder":108},
  {"id":"s_work_nvlt_40_109","chapterId":"ch_work_nvlt_40","text":"《荆州記》曰：郦縣北三十里，有一墓，甚崇伟，前有石樓，高一丈五尺，上作石鳳，將九子，相傳雲是姚家墓，不詳其人。","sortOrder":109},
  {"id":"s_work_nvlt_40_110","chapterId":"ch_work_nvlt_40","text":"《異苑》曰：魏武北征喻［《太平御覽》五百五十九作蹹。］頓，升嶺眺望，見一岗，不生百草，王粲曰：必是古冢，此人在世服生礜石，死而石生，势蒸出外，致卉草燋滅，即令凿看，果得墓，有礜石滿塋。","sortOrder":110},
  {"id":"s_work_nvlt_40_111","chapterId":"ch_work_nvlt_40","text":"皇覽曰：蒼頡冢在冯翊縣衙［《太平御覽》五百五十九作衙縣。］此倒，利陽亭南，道旁墳高六尺，學書者皆祭之不絕。","sortOrder":111},
  {"id":"s_work_nvlt_40_112","chapterId":"ch_work_nvlt_40","text":"蚩尤冢在東郡寿張縣阚［《太平御覽》五百五十九作阌。］乡城中，高七丈，民常十月祀之，有赤氣出，如一匹絳，民為蚩尤旗。","sortOrder":112},
  {"id":"s_work_nvlt_40_113","chapterId":"ch_work_nvlt_40","text":"伍辑之《從征記》曰：孔丛雲，夫子墓方二里，諸弟子各以四方木來植之，今盤根猶存。","sortOrder":113},
  {"id":"s_work_nvlt_40_114","chapterId":"ch_work_nvlt_40","text":"魏武令曰：故北中郎將盧植，名著海內，學為儒宗，士之楷模，國之植幹也，今亟遣丞相掾，除其墳墓，存其子孫，併致薄醊，以彰厥德。","sortOrder":114},
  {"id":"s_work_nvlt_40_115","chapterId":"ch_work_nvlt_40","text":"《魏志》曰：陳思王薨，遣葬，初植登魚山，臨東河，喟然有叹焉之心，遂營為墓。","sortOrder":115},
  {"id":"s_work_nvlt_40_116","chapterId":"ch_work_nvlt_40","text":"《吳志》曰：顧邵起家為豫章太守，下車祀先賢徐孺子墓，優待其後。","sortOrder":116},
  {"id":"s_work_nvlt_40_117","chapterId":"ch_work_nvlt_40","text":"又曰：漢末，關中亂，有發前漢時宮人冢者，猶活，既出复如舊，郭後愛念之，常置左右，問當時宮內事，了了有次第。","sortOrder":117},
  {"id":"s_work_nvlt_40_118","chapterId":"ch_work_nvlt_40","text":"王隱《晉書》曰：太康元年，汲縣民盜發魏安釐王冢，得竹書漆字古書，有易卦，似連山歸藏文，有春秋，似左傳。","sortOrder":118},
  {"id":"s_work_nvlt_40_119","chapterId":"ch_work_nvlt_40","text":"《搜神記》曰：宋大夫韓冯，取妻而美，康王奪之，俄而冯自殺，妻乃陰腐其衣，王與登台，遂自投台下，左右攬之，衣不中手，遺書於帶曰：王利其生，不［法苑珠林三十六作妾。］利其死，原以尸骨賜冯而合葬乎，王怒弗聽，使里人埋之，冢相望也，宿昔有交梓木生於二冢之端，旬日而大合抱，屈體相就，根交於下。又有鴛鴦鳥，雌雄各一，恒栖树上，交頸悲鳴，宋人哀之，遂號其木曰相思树。","sortOrder":119},
  {"id":"s_work_nvlt_40_120","chapterId":"ch_work_nvlt_40","text":"《從征記》曰：劉表冢在高平郡，表之子琮，捣四方珍香數十斛，著棺中，蘇合消疾之香，莫不畢備，永嘉中，郡人發其墓，表白如生，香聞數十里。","sortOrder":120},
  {"id":"s_work_nvlt_40_121","chapterId":"ch_work_nvlt_40","text":"《世說》曰：戴公見林法師墓曰：德音未遠，而拱木已積，冀神理綿綿，不與氣運俱盡耳。","sortOrder":121},
  {"id":"s_work_nvlt_40_122","chapterId":"ch_work_nvlt_40","text":"戴延之《西征記》曰：金乡焦氏山北數里，有漢司隸校尉曾峻冢，前有石祠，堂中四壁，皆青石隱起，自書契以來，忠臣孝子，孔子七十二人形象，皆刻石記之。","sortOrder":122},
  {"id":"s_work_nvlt_40_123","chapterId":"ch_work_nvlt_40","text":"【詩】古墟墓詩曰：去者日已疏，生者日已親，出郭門直视，但見丘與墳，古墓犁為田，松柏摧為薪，白楊多悲風，萧萧愁殺人，思還故里闾，欲歸道無因。","sortOrder":123},
  {"id":"s_work_nvlt_40_124","chapterId":"ch_work_nvlt_40","text":"宋孝武拜衡陽文王義季墓詩曰：昧旦凭行軾，濡露及山庭，投步矜履蹈，舉目增凄清，轺路滅歸軫，淪闼負重扃，深松朝已霧，幽燧晏未明，長楊敷晚素，宿草披初青，哀往起沉泉，追愛恸中情，竹帛凭年遠，世范隨伏傾。","sortOrder":124},
  {"id":"s_work_nvlt_40_125","chapterId":"ch_work_nvlt_40","text":"宋謝靈運經庐陵王墓詩曰：晚日發雲陽，落日次朱方，含凄汎廣川，洒淚眺連岗，眷言懷君子，沉痛切衷腸，道消結憤懣，運开申悲涼，神期恒若存，德音初不忘，徂謝易永久，松柏森已行，一隨往化滅，安用空名扬，舉聲泣已歷，長叹不成章。","sortOrder":125},
  {"id":"s_work_nvlt_40_126","chapterId":"ch_work_nvlt_40","text":"齊隨郡王萧子隆經劉瓛墓下詩曰：升堂子不谬，問道餘未窮，如何辭白日，千載隔音通，山門已一絕，長夜緬難終，初松切暮鳥，新楊摧晚風。","sortOrder":126},
  {"id":"s_work_nvlt_40_127","chapterId":"ch_work_nvlt_40","text":"齊竟陵王萧子良同隨王經劉先生墓詩曰：漢陵掩馆芜，晉殄洙風缺，五都聲論空，三阿文義絕，興禮邁前英，談玄逾往哲，桓井忽以平，煙雲從容裔，爾叹牛山悲，我悼驚川逝。","sortOrder":127},
  {"id":"s_work_nvlt_40_128","chapterId":"ch_work_nvlt_40","text":"梁沈約經劉瓛墓詩曰：表闾钦逸軌，式墓禮貞魂，化涂終眇默，神理暧猶存，尘經未輟愰，高衡已委門，華陰無遺布，楚席有靈樽。","sortOrder":128},
  {"id":"s_work_nvlt_40_129","chapterId":"ch_work_nvlt_40","text":"梁何遜行經孫氏陵詩曰：水龍忽東鶩，青蓋乃西歸，朅來易永久，年代暧微微，苔石疑文字，荆墳失是非，山湋空曙响，垄月自秋暉，銀海終無浪，金凫會不飛，阒寂今如此，望望霑人衣。","sortOrder":129},
  {"id":"s_work_nvlt_40_130","chapterId":"ch_work_nvlt_40","text":"陳陰铿行經古墓詩曰：偃松將古墓，年代理當深，表柱應堪燭，碑書欲有金。回墳由路毀，荒隧受田侵，霏霏野霧合，昏昏垄日沉，懸劍今何在，風扬空自吟。","sortOrder":130},
  {"id":"s_work_nvlt_40_131","chapterId":"ch_work_nvlt_40","text":"【賦】後漢張衡冢賦曰：系以循隧，洽以溝渎，曲折相連，迤靡相屬，弈弈將將，崇棟廣宇，在冬不涼，在夏不暑，祭祝是居，神明是處。","sortOrder":131},
  {"id":"s_work_nvlt_40_132","chapterId":"ch_work_nvlt_40","text":"晉陆機感丘賦曰：泛輕舟於西川，背京室而電飛，遵伊洛之抵渚，沿黃河之曲湄，睹墟墓於山梁，讬崇丘以自綏，見兆域之藹藹，羅魁封之壘壘，於是徘徊洛涯，弭節河幹，佇眄留心，慨爾遺叹，仰終古以遠念，窮萬緒乎其端，伊人生之寄世，猶水草乎山河，應甄陶以歲改，順通川而日過，爾乃申舟人以遂往，橫大川而有惡，傷年命之倏忽，怨天步之不幾，雖履信而思順，曾何足以保茲，普天壤其弗免，寧吾人之所辭，原靈根之晚墜，指歲暮而為期。","sortOrder":132},
  {"id":"s_work_nvlt_40_133","chapterId":"ch_work_nvlt_40","text":"晉傅鹹遂登芒賦曰：左光祿大夫濟北侯荀公，前丧元妃，及失令子，葬於西芒，有以感懷，而作斯賦，何天道之難忱，信厥命之靡常，匪彼生之不辰，亦夫人之多殃，惟濟北之初載，夙遘旻而逢罹，興瓜瓞之綿綿，飛英聲以風馳，庶家道之克昌，永保祚於螽斯，慍無妄之為灾，怨上皇之有违，在德門之方隆，乃降厲於元妃，蘭房阒其無主，眾孤茕而莫依，孔臨川以永叹，趙有感於九原，覽登芒之哀賦，谅聖賢之同情。","sortOrder":133},
  {"id":"s_work_nvlt_40_134","chapterId":"ch_work_nvlt_40","text":"【表】晉張士然請湯武諸孫置守冢人表［按文選三十八作為吳令謝詢求為諸孫置守冢人表，此有訛脱。］曰：成湯革夏而封杞，武王入殷而建宋，西戎有即叙之民，京邑开吳蜀之馆，興滅加乎萬國，繼絕接於百世，春雨润木，自葉落根，鴟鴞恤功，愛子及室，家有義勇之暮，［《文選》作基。］世傳扶危之業，進為徇漢之臣，退為开吳之主，而蒸嘗絕於三葉，園陵殘於薪采。","sortOrder":134},
  {"id":"s_work_nvlt_40_135","chapterId":"ch_work_nvlt_40","text":"【教】宋傅亮修复前漢諸陵教曰：夫信陵之墳，守衛無曠，展季之垄，樵蘇有刑，彼匹夫懷道，列國陪隸，猶見禮異世，取貴鄰邦，漢高拨亂反正，大造區宇，道拯橫流，功高百代，盛德之烈，義在不泯。","sortOrder":135},
  {"id":"s_work_nvlt_40_136","chapterId":"ch_work_nvlt_40","text":"又修楚元王墓教曰：夫褒賢崇德，千祀弥光，尊本敬始，義高自遠，楚元王積仁基德，啟蕃斯境，本枝胤祚，隆彼四方，遺芳餘烈，奋乎百世，而丘封翳然，墳塋莫翦，感遠在彼，慨焉永懷，况瓜瓞攸興，开元自本，可謂［《文選》三十六謂字無。］蠲复近墓五家，長給洒扫。","sortOrder":136},
  {"id":"s_work_nvlt_40_137","chapterId":"ch_work_nvlt_40","text":"【文】宋謝惠連祭古冢文曰：東府掘巉一丈，得古冢，上無封域，明器之屬，材瓦銅漆，有數十种，異形不可盡識，刻木為人，長三尺許，初开見，悉為人形，以物枨拨之，應手灰滅，水中有甘蔗節及李核瓜蒂，皆浮出，不甚烂坏，世代不可知也，既不知其名字，故假號曰冥漠君雲爾，刍靈已毀，涂車既摧，蔗傳餘節，瓜表遺犀，十仞斯建，百堵斯齊，墉不可轉，巉不可回，黃腸既毀，便房已頹，修題興念，撫榇增哀。","sortOrder":137},
  {"id":"s_work_nvlt_40_138","chapterId":"ch_work_nvlt_40","text":"梁任孝恭祭雜墳文曰：惟爾冥然往代，求圓石而無名，邈矣遐年，讨方砖而不記，封树漂殄，誰別羽商之家，墳垄傾回，終迷庚癸之向，近創此伽藍，寔須泥丸，命彼硕人，置茲屯邑，不謂纶繩所用，遂毀牛亭之基，鍬锸所侵，爰傷馬鬛之势，重使翠幕臨風，佳城見日，昔靈沼枯骨，周王改以衣冠，廣武橫尸，漢主加其轊櫝，辄勒彼山虞，覆頹隍於舊趾，命茲匠者，修反壤於故林，還蚁結之文。依似坊之势，幸得宜陽大道，無变無移，京兆長阡，勿回勿徙，庶幽魂遊止，踐昔径而不疑，涂車往還，瞻舊轍而猶在。","sortOrder":138},
  {"id":"s_work_nvlt_40_139","chapterId":"ch_work_nvlt_40","text":"《藝文類聚》　唐·欧陽詢","sortOrder":139},
  {"id":"s_work_nvlt_41_1","chapterId":"ch_work_nvlt_41","text":"卷四十一樂部一","sortOrder":1},
  {"id":"s_work_nvlt_41_2","chapterId":"ch_work_nvlt_41","text":"○論樂","sortOrder":2},
  {"id":"s_work_nvlt_41_3","chapterId":"ch_work_nvlt_41","text":"◇論樂","sortOrder":3},
  {"id":"s_work_nvlt_41_4","chapterId":"ch_work_nvlt_41","text":"《說文》曰：樂，五聲八音總□［說文作名。］也。","sortOrder":4},
  {"id":"s_work_nvlt_41_5","chapterId":"ch_work_nvlt_41","text":"《易》曰：雷出地奋豫，先王以作樂崇德，殷荐上帝。","sortOrder":5},
  {"id":"s_work_nvlt_41_6","chapterId":"ch_work_nvlt_41","text":"《禮記》曰：夔始作樂，以賞諸侯。","sortOrder":6},
  {"id":"s_work_nvlt_41_7","chapterId":"ch_work_nvlt_41","text":"又曰：凡音之起，由人心生也，人心之動，物使之然，感於物而動，故形於聲，聲相應，故生变，变成方，謂之音，比音而樂之，及幹戚羽旄，謂之樂。","sortOrder":7},
  {"id":"s_work_nvlt_41_8","chapterId":"ch_work_nvlt_41","text":"又曰：審聲以知音，審音以知樂，審樂以知政，而治道備矣。","sortOrder":8},
  {"id":"s_work_nvlt_41_9","chapterId":"ch_work_nvlt_41","text":"又曰：大樂必易，大禮必簡，鍾鼓管磬，羽籥幹戚，樂之器也，屈伸俯仰，缀兆疾舒，樂之文也，故知禮樂之情者能作，識禮樂之文者能述，作者之謂聖，述者之謂明，明聖者，述作之謂也，五帝殊時，不相沿樂，三王異世，不相袭禮。","sortOrder":9},
  {"id":"s_work_nvlt_41_10","chapterId":"ch_work_nvlt_41","text":"《孝經》曰：移風易俗，莫善於樂。","sortOrder":10},
  {"id":"s_work_nvlt_41_11","chapterId":"ch_work_nvlt_41","text":"樂緯曰：黃帝樂曰鹹池，帝喾曰六英，颛頊曰五茎，尧曰大章，舜曰箫韶，殷曰濩，周曰酌，是以清和上升，天下樂其風俗，鳳皇來儀，百獸率舞，神龍升降，靈龟晏寧。","sortOrder":11},
  {"id":"s_work_nvlt_41_12","chapterId":"ch_work_nvlt_41","text":"《尚書》曰：帝曰：夔，命汝典樂，教胄子，詩言志，歌永言，聲依永，律和聲，八音克諧，無相奪倫，神人以和，夔曰：於，予击石拊石，百獸率舞。","sortOrder":12},
  {"id":"s_work_nvlt_41_13","chapterId":"ch_work_nvlt_41","text":"《周官》曰：凡六樂者，一变而致羽物及川泽之祇，再变而致臝物及山林之祇，三变而致鱗物及丘陵之祇，四变而致毛物及墳衍之祇，五变而致介物及土示，六变而致象物及天神，九德之歌，九磬之舞，於宗廟之中奏之，若樂九变，則人鬼可得而禮矣。","sortOrder":13},
  {"id":"s_work_nvlt_41_14","chapterId":"ch_work_nvlt_41","text":"又曰：鍾師，掌金奏，凡樂事，以鍾鼓奏九夏。","sortOrder":14},
  {"id":"s_work_nvlt_41_15","chapterId":"ch_work_nvlt_41","text":"《穆天子傳》曰：天子西征，至於玄池之上，乃奏廣樂，三日而終，是曰樂池。","sortOrder":15},
  {"id":"s_work_nvlt_41_16","chapterId":"ch_work_nvlt_41","text":"《論語》曰：子在齊，聞韶，三月不知肉味，曰：不圖為樂之至於斯。","sortOrder":16},
  {"id":"s_work_nvlt_41_17","chapterId":"ch_work_nvlt_41","text":"《楚辭》曰：陳鍾案鼓造新歌，涉江采菱發陽阿，二八齊容起鄭舞，衽若交竿撫案下，竽瑟狂會填鳴鼓，宮庭震驚發激楚。又，代奏［楚辭大招作秦。］鄭衛鳴竽張，伏戲駕辨楚勞商。","sortOrder":17},
  {"id":"s_work_nvlt_41_18","chapterId":"ch_work_nvlt_41","text":"《韓子》曰：昔衛靈公之晉，於濮水之上宿，夜聞有新聲者，召師涓撫瑟寫之，公遂之晉，晉平公觴之，靈公乃召師涓，坐師曠之傍，援琴鼓之，未終，師曠曰：不如清徵，平公曰：原试聽之，師曠援琴一奏，有玄鶴二八來集，再奏而列，三奏而延頸鳴，舒翼而舞，音中宮商，師曠曰：不如清角，師曠一奏之，有雲從西北方來，再奏之，大風至，大雨隨之，裂帷幕，破俎豆，墮廊瓦。","sortOrder":18},
  {"id":"s_work_nvlt_41_19","chapterId":"ch_work_nvlt_41","text":"《史記》曰：趙簡子疾，五日不知人，居二日半，簡子寤，語大夫曰：我之帝所，甚樂，與百神遊於鈞天，廣樂九奏萬舞。","sortOrder":19},
  {"id":"s_work_nvlt_41_20","chapterId":"ch_work_nvlt_41","text":"《鹽鐵論》曰：貴人之家，中山索女，撫流徵於堂，與鳴鼓巴渝交作堂下。","sortOrder":20},
  {"id":"s_work_nvlt_41_21","chapterId":"ch_work_nvlt_41","text":"《漢武故事》曰：未央庭中，設角抵戲，享外國，三百里內觀，角抵者，使角力相觸也，其雲雨雷電，無異於真，畫地為川，聚石成山，倏忽变化，無所不為。","sortOrder":21},
  {"id":"s_work_nvlt_41_22","chapterId":"ch_work_nvlt_41","text":"漢官典職曰：正旦，天子行陽德殿，作九賓樂，舍利從東來，戲於庭，入殿前，激水化成比目魚，跳躍漱水作霧，化成黃龍，高八十丈，出水戲於庭，以兩大絲纏系兩頭，中間相去數丈，兩倡女對舞，行於繩上，道逢功［續漢書禮儀志引漢儀改切。］肩不傾。又踏跼屈身，藏形於斗中，鍾磬普唱，樂畢，作魚龍曼延，黃門吹三匝。","sortOrder":22},
  {"id":"s_work_nvlt_41_23","chapterId":"ch_work_nvlt_41","text":"《淮南子》曰：奏雅樂者，始於陽阿采菱。","sortOrder":23},
  {"id":"s_work_nvlt_41_24","chapterId":"ch_work_nvlt_41","text":"《五經通義》曰：舞四夷之樂，明德泽廣被四表也，東夷之樂曰抹［太平御覽五百六十七作侏。］離，南夷之樂曰任，西夷之樂曰禁，北夷之樂曰昧。","sortOrder":24},
  {"id":"s_work_nvlt_41_25","chapterId":"ch_work_nvlt_41","text":"又曰：受命而王者六樂焉，以太一樂天，以鹹池樂地，以肆夏樂人，以大夏樂四時，以大濩樂五行神明，以大武樂六律，各象其性分，而為之製，以樂其先祖。","sortOrder":25},
  {"id":"s_work_nvlt_41_26","chapterId":"ch_work_nvlt_41","text":"又曰：王者之樂有先後者，各尚其德也，以文得之，先文樂，天繡［北堂書鈔一百零七作衣繡衣，此有訛脱。］持羽而舞，以武得之，先武樂，持朱幹玉戚而舞。","sortOrder":26},
  {"id":"s_work_nvlt_41_27","chapterId":"ch_work_nvlt_41","text":"五經要義曰：周禮鍾磬皆編懸之，二八十六而在一虡，謂之堵磬，一堵謂之肆，春秋傳曰：歌鍾二肆，此之謂也。","sortOrder":27},
  {"id":"s_work_nvlt_41_28","chapterId":"ch_work_nvlt_41","text":"又曰：凡樂音有八，鼓謂之革，鍾謂之金，磬謂之石，琴瑟謂之絲，箫鼓謂之竹，埙謂之土，柷敔謂之木，笙謂之匏，是謂八音。","sortOrder":28},
  {"id":"s_work_nvlt_41_29","chapterId":"ch_work_nvlt_41","text":"袁淮招公子曰：燕倡趙舞齊商歌，五色紛華曳纖羅。","sortOrder":29},
  {"id":"s_work_nvlt_41_30","chapterId":"ch_work_nvlt_41","text":"挚虞决疑曰：漢末丧亂，絕無金石之樂，魏武帝至漢中，得杜夔，識舊法，始复設軒懸鍾磬，至於今用之。","sortOrder":30},
  {"id":"s_work_nvlt_41_31","chapterId":"ch_work_nvlt_41","text":"【樂府古詩】飲馬長城窟行曰：青青河畔草，綿綿思遠道，遠道不可思，宿昔夢見之，夢見在我旁，忽覺在他乡，他乡各異縣，展轉不相見，枯桑知天風，海水知天寒，入門各自媚，誰肯相與言，客從遠方來，遺我双鯉魚，呼兒烹鯉魚，中有尺素書，長跪讀素書，書中竟何如，上有加餐飯，下有長相思。","sortOrder":31},
  {"id":"s_work_nvlt_41_32","chapterId":"ch_work_nvlt_41","text":"魏文帝飲馬長城窟行曰：浮舟橫大江，讨彼犯荆虜，武將齊貫錍，征人伐金鼓，長戟十萬队，幽冀百石弩，發機若雷電，一發連四五。","sortOrder":32},
  {"id":"s_work_nvlt_41_33","chapterId":"ch_work_nvlt_41","text":"晉傅玄飲馬長城窟行曰：青青河邊草，悠悠萬里道，草生在春時，還道還有期，春至草不生，期盡漠無聲，感物懷思心，夢想發中情，夢君如鴛鴦，比翼雲間翔，既覺寂無見，曠若參與商。","sortOrder":33},
  {"id":"s_work_nvlt_41_34","chapterId":"ch_work_nvlt_41","text":"晉陆機飲馬長城窟行曰：驅馬陟陰山，山高馬不前，往問陰山候，劲虜在燕然，末德爭先鳴，凶德無兩全，師克薄賞行，軍没微軀捐，將軍甘陳跡，收功单於旃。","sortOrder":34},
  {"id":"s_work_nvlt_41_35","chapterId":"ch_work_nvlt_41","text":"梁沈約飲馬長城窟行，介馬渡龍堆，涂萦馬屢回，前訪昌海驿，雜种寇輪台，旌幕倦煙雨，徒御犯冰埃。","sortOrder":35},
  {"id":"s_work_nvlt_41_36","chapterId":"ch_work_nvlt_41","text":"晉陆機董桃行六言曰：和風習習薄林，柔條布繁垂陰，鳴鳩拂羽相尋，仓鹒喈喈弄音，感時悼逝傷心。","sortOrder":36},
  {"id":"s_work_nvlt_41_37","chapterId":"ch_work_nvlt_41","text":"又長安有狎斜行曰：伊洛有岐路，岐路交朱輪，輕蓋承華景，騰步躡飛尘，鳴玉豈朴儒，凭軾皆俊民，烈心厲劲秋，麗服鮮芳春，餘本倦遊客，豪彦多舊親，傾蓋承芳訊，欲鳴賞及晨。","sortOrder":37},
  {"id":"s_work_nvlt_41_38","chapterId":"ch_work_nvlt_41","text":"宋謝惠連長安有狹斜行曰：紀郢有通逵，通逵併軒車，弈弈彫輪馳，軒軒翠蓋舒，撰策之五尹，振辔從三闾，推劍凭前軾，鳴佩专後舆。","sortOrder":38},
  {"id":"s_work_nvlt_41_39","chapterId":"ch_work_nvlt_41","text":"梁沈約長安有狹斜行曰：青槐金陵陌，丹轂貴遊士，方驂萬乘臣，炫服千金子，鹹陽不足稱，臨淄孰能擬。","sortOrder":39},
  {"id":"s_work_nvlt_41_40","chapterId":"ch_work_nvlt_41","text":"梁庾肩吾長安有狹斜詩曰：長安有曲陌，曲陌不容幰，路逢双綺襦，問君居近遠，我居臨御溝，可識不難求，長子登麟閣，次子待龍樓，少子無高位，聊從嚴駕遊，大婦襞雲裘，中婦卷羅帱，少婦多妖艳，當钿椠石榴，夫君且安坐，歡娱方未周。","sortOrder":40},
  {"id":"s_work_nvlt_41_41","chapterId":"ch_work_nvlt_41","text":"宋鮑昭結客少年場行曰：驄馬金絡頭，錦帶佩吳鉤，失意杯酒間，白刃起相讎，追兵一旦至，負劍遠行遊，去乡三十載，复得還舊丘，升高臨四野，表里望皇州，九衢平若水，双闕似雲浮，扶宮羅將相，夹道列王侯，日中市朝滿，車馬如川流，击鍾陳鼎食，方駕自相求，今我獨何為，埳壈懷百忧。","sortOrder":41},
  {"id":"s_work_nvlt_41_42","chapterId":"ch_work_nvlt_41","text":"梁劉孝威結客少年場行曰：少年本六郡，遨遊遍五都，插腰銅匕首，障日錦涂蘇，鷲羽裝銀鏑，犀膠飾象弧，近發連双兔，高弯落九乌，邊城多驚急，節使滿郊衢，居延箭服盡，疏勒井泉枯，千金募惡少，一麾擒骨都，勇餘聊蹙鞠，戰罢戲投壶，昔為北邊將，今成南面孤，邦君行負弩，縣令且前驅。","sortOrder":42},
  {"id":"s_work_nvlt_41_43","chapterId":"ch_work_nvlt_41","text":"宋鮑昭出自蓟北門行曰：羽檄起邊亭，烽火入鹹陽，徵騎屯廣武，分兵救朔方，嚴秋筋竿劲，虜陣精且彊，天子案劍怒，使者遙相望，雁行緣石径，魚貫度飛梁，箫鼓流漢思，旌甲被胡霜，疾風冲塞起，沙砾自飄扬，馬毛縮如猬，角弓不可張，時危見臣節，世亂識忠良，投軀報明主，身死為國殇。","sortOrder":43},
  {"id":"s_work_nvlt_41_44","chapterId":"ch_work_nvlt_41","text":"周庾信出自蓟北門行曰：蓟門還北望，徭役盡傷情，笳寒芦葉脆，弓冻纻絃鳴，梅林能止渴，複姓可防兵，燕山猶有石，須勒幾人名。","sortOrder":44},
  {"id":"s_work_nvlt_41_45","chapterId":"ch_work_nvlt_41","text":"陳徐陵出自蓟北門行曰：蓟北聊長望，黃昏心獨愁，燕山對古刹，代郡倚城樓，屢戰桥恒斷，長冰巉不流，天雲如地陣，漢月帶胡秋，請土泥函穀，桉繩縛涼州，生平燕頷相，會自得封侯。","sortOrder":45},
  {"id":"s_work_nvlt_41_46","chapterId":"ch_work_nvlt_41","text":"宋鮑昭苦熱行曰：赤阪橫西阻，火山赫南威，身熱頭且痛，鳥墮魂來歸，湯泉發雲泽，焦煙起石圻，丹蛇逾百尺，玄蜂盈十围，含沙射流影，吹蠱病行暉，戈船榮既薄，伏波賞亦微，君輕君尚惜，士重安可希。","sortOrder":46},
  {"id":"s_work_nvlt_41_47","chapterId":"ch_work_nvlt_41","text":"又白頭行吟曰：直如朱絲繩，清如玉壶冰，何慚宿昔意，猜恨坐相仍，人情賤恩舊，世議逐衰興，毫發一為瑕，丘山不可勝，凫鶴遠成美，薪刍前見陵，申黜褒女進，班去趙姬升，古來共如此，非君獨撫膺。","sortOrder":47},
  {"id":"s_work_nvlt_41_48","chapterId":"ch_work_nvlt_41","text":"魏文帝釣竿行曰：東越河濟水，遙望大海崖，釣竿何珊珊，魚尾何簁簁，行路之好者，芳餌欲何為。","sortOrder":48},
  {"id":"s_work_nvlt_41_49","chapterId":"ch_work_nvlt_41","text":"梁沈約釣竿行曰：桂舟既容與，绿浦复回紆，輕絲動弱芰，微楫起单凫，扣舷志日暮，卒歲以為娱。","sortOrder":49},
  {"id":"s_work_nvlt_41_50","chapterId":"ch_work_nvlt_41","text":"梁戴嵩釣竿篇曰：试持玄渚釣，蹔罢池陽獵，翠羽飾長纶，蕖花裝小緤，鉅利斷莼絲，汎舉牵菱葉，聊載前魚童，過看後舟妾。","sortOrder":50},
  {"id":"s_work_nvlt_41_51","chapterId":"ch_work_nvlt_41","text":"梁劉孝威釣竿篇曰：釣舟畫采鹢，魚子服冰紈，金轄茱萸網，銀鉤翡翠竿，斂桡隨水脈，急槳度沙湍，湍長自不辭，前浦有佳期，莲交棹影合，浦深魚出遲。","sortOrder":51},
  {"id":"s_work_nvlt_41_52","chapterId":"ch_work_nvlt_41","text":"魏陳王曹植太山梁甫行曰：八方各異氣，千里殊風雨，剧哉邊海民，寄身於草墅，妻子象禽獸，行止依林阻，柴門何萧條，狐兔翔我宇。","sortOrder":52},
  {"id":"s_work_nvlt_41_53","chapterId":"ch_work_nvlt_41","text":"梁沈約梁甫吟行曰：龍駕有馳策，日御無停陰，寒光稍眇眇，秋海日沉沉，哀歌涉梁甫，叹絕有遺吟。","sortOrder":53},
  {"id":"s_work_nvlt_41_54","chapterId":"ch_work_nvlt_41","text":"魏陳王曹植豫章行曰：窮達難豫圖，禍福信亦然，虞舜不逢尧，耕耘處中田，太公未遭文，漁釣經渭川，不見魯孔丘，窮困陳蔡間，周公下白屋，天下稱其賢。","sortOrder":54},
  {"id":"s_work_nvlt_41_55","chapterId":"ch_work_nvlt_41","text":"又曰：鴛鴦自用親，不若比翼連，他人雖同盟，骨肉天性然，周公穆康叔，管蔡則流言，子臧讓千乘，季札慕其賢。","sortOrder":55},
  {"id":"s_work_nvlt_41_56","chapterId":"ch_work_nvlt_41","text":"晉傅玄豫章行曰：苦相身為女，早［冯校本作平，按樂府詩集三十四作卑，當作卑。］陋難再陳，男兒當門戶，墮地自生神，雄心志四海，萬里望風尘，女育無欣慶，不為家所珍，玉顏隨年变，丈夫多好新，昔為形與影，今為胡與秦。","sortOrder":56},
  {"id":"s_work_nvlt_41_57","chapterId":"ch_work_nvlt_41","text":"晉陆機豫章行曰：汎舟清川渚，遙望南山陰，川陆殊涂軌，懿親將遠尋，三荆歡同株，四鳥悲異林，樂會良自古，悼別豈獨今。","sortOrder":57},
  {"id":"s_work_nvlt_41_58","chapterId":"ch_work_nvlt_41","text":"宋謝靈運豫章行曰：短生旅長世，恒覺白日欹，覽鏡睨頹容，華顏豈久期，苟無回戈術，坐觀落崦嵫。","sortOrder":58},
  {"id":"s_work_nvlt_41_59","chapterId":"ch_work_nvlt_41","text":"梁沈約豫章行曰：燕陆平而遠，易河清且駛，一見尘波阻，臨涂引征思，双劍愛匣同，孤鸞悲影異，往歡墜壮心，來戚滿衰志。","sortOrder":59},
  {"id":"s_work_nvlt_41_60","chapterId":"ch_work_nvlt_41","text":"魏陳王曹植薤露行曰：天地無窮極，陰陽轉相因，人居一世間，忽若風吹尘，原得展功勤，输力於明君，懷此王佐才，慷恺獨不群，鱗介尊神龍，走獸宗騏麟，虫獸豈知德，何况於士人，孔氏删詩書，王業粲已分，騁我径寸翰，流藻垂華芬。","sortOrder":60},
  {"id":"s_work_nvlt_41_61","chapterId":"ch_work_nvlt_41","text":"魏文帝秋胡行曰：尧任舜禹，當复何為，百獸率舞，鳳皇來儀，得人則安，失人則危，唯賢知賢，人不易知，歌以詠言，誠不易移，鳴條之役，萬舉必全，明德通靈，福降自天。","sortOrder":61},
  {"id":"s_work_nvlt_41_62","chapterId":"ch_work_nvlt_41","text":"又曰：朝與佳人期，日夕殊不來，嘉肴不嘗，旨酒停杯，寄言飛鳥，告餘不能，俯折蘭黃，仰結桂枝，佳人不在，結之何為，從爾何所之，乃至大海隅，靈若道言，貽爾明珠，企予望之，步立躇蹰，佳人不來，何得何須。","sortOrder":62},
  {"id":"s_work_nvlt_41_63","chapterId":"ch_work_nvlt_41","text":"又曰：汎汎渌池，中有浮萍，寄身流波，隨風靡傾，芙蓉含芳，菡萏垂榮，朝采其實，夕佩其英，采之誰遺，所思在庭，双魚比目，鴛鴦交頸，有美一人，婉如青陽，知音識曲，善為樂方。","sortOrder":63},
  {"id":"s_work_nvlt_41_64","chapterId":"ch_work_nvlt_41","text":"又丹霞蔽日行曰：丹霞蔽日，采虹垂天，穀水潺潺，木落翩翩，孤禽失群，悲鳴雲間，月盈則冲，華不再繁，古來有之，嗟我何言。","sortOrder":64},
  {"id":"s_work_nvlt_41_65","chapterId":"ch_work_nvlt_41","text":"魏陳王曹植曰：紂為昏亂，殘忠虐正，周室何隆，一門三聖，牧野致功，天亦革命，漢祖之興，階秦之衰，雖有南面，王道陵夷，炎光再幽，忽滅無遺。","sortOrder":65},
  {"id":"s_work_nvlt_41_66","chapterId":"ch_work_nvlt_41","text":"晉傅玄秋胡行曰：秋胡子，娶婦三日，會行仕宦，既享顯爵，保茲德音，以祿颐親，韞此黃金，睹一好婦，采桑路傍，遂下黃金，誘以逢卿，玉磨逾絜，蘭動弥馨，源流絜清，水無濁波，奈何秋胡，中道懷邪，美此節婦，高行瓘瓘，哀哉可愍，自投長河。","sortOrder":66},
  {"id":"s_work_nvlt_41_67","chapterId":"ch_work_nvlt_41","text":"晉陆機秋胡行曰：道雖一致，涂有萬端，吉凶紛藹，休咎之源，人鮮知命，命未易觀，生亦何惜，功名所勤。","sortOrder":67},
  {"id":"s_work_nvlt_41_68","chapterId":"ch_work_nvlt_41","text":"宋謝惠連秋胡行曰：春日遲遲，桑何萋萋，紅桃含妖，绿柳舒荑，邂逅粲者，遊渚戲蹊，華顏易改，良原難諧。","sortOrder":68},
  {"id":"s_work_nvlt_41_69","chapterId":"ch_work_nvlt_41","text":"又曰：系風捕景，誠知不得，念彼奔波，意慮回惑，漢女倏忽，洛神飄扬，空勤交甫，徒勞陳王。","sortOrder":69},
  {"id":"s_work_nvlt_41_70","chapterId":"ch_work_nvlt_41","text":"魏陳王曹植蒲生行曰：浮萍寄绿水，隨風東西流，結發辭嚴親，來為君子仇，恪勤在朝夕，中年獲愆尤，茱萸自內芳，不若桂與蘭，佳人雖成列，不若故所歡，行雲有返期，君恩傥中還。","sortOrder":70},
  {"id":"s_work_nvlt_41_71","chapterId":"ch_work_nvlt_41","text":"又妾薄命行曰：携玉手，喜同車，比上雲閤飛除，釣台蹇產清虛，池塘靈沼可娱，仰汎龍舟渌波，俯棹神草枝柯，想彼宓妃洛河，退詠漢女湘娥，日既逝矣西藏，更會蘭室洞房，華燈先置舒光，皎若日出扶桑，促酒合座行觴，屢舞仙仙體輕，解裳履遺絕纓，齊舉金爵翠槃，腕弱不勝珠環。","sortOrder":71},
  {"id":"s_work_nvlt_41_72","chapterId":"ch_work_nvlt_41","text":"梁簡文帝妾薄命行曰：名都多雅质，本自恃容姿，荡子行不至，秋胡無定期，玉貌歇紅縷，長嚬串翠眉，毛嫱貌本絕，踉蹌入氈帷，盧姬嫁日晚，非复少年時。","sortOrder":72},
  {"id":"s_work_nvlt_41_73","chapterId":"ch_work_nvlt_41","text":"梁劉孝威妾薄命行曰：去年從越漳，今歲没朝［樂府詩集六十二作胡。］廷，嚴霜封碣石，驚沙暗井陉，玉簪久落鬢，羅衣長掛屏，勿言戎夏隔，但令心契冥，不見酆城劍，千祀复同形。","sortOrder":73},
  {"id":"s_work_nvlt_41_74","chapterId":"ch_work_nvlt_41","text":"又古陌上桑羅敷行曰：日出東海隅，照我秦氏樓，秦氏有好女，自名為羅敷，羅敷喜蠶桑，采桑城南隅，青絲為籠繩，桂枝為籠鉤，頭上緌墮髻，耳中明月珠，緗綺為下裾，紫綺為上襦，使君從南來，五馬立踟蹰，使君遣使往，問是誰家姝，二十尚未然，十五頗有餘，使君謝羅敷，寧可共載不，羅敷前致詞，使君一何愚，使君自有婦，羅敷自有夫，東方千餘騎，夫婿居上頭，何用識夫婿，白馬從驪駒，青絲系馬尾，黃金絡馬頭，腰中鹿盧劍，可直千萬餘，十五府小吏，二十朝大夫，三十侍中郎，四十专城居，為人絜白晳，鬢鬢頗有須，盈盈公府步，冉冉府中趨。","sortOrder":74},
  {"id":"s_work_nvlt_41_75","chapterId":"ch_work_nvlt_41","text":"晉陆機日出東南隅行曰：扶桑升朝暉，照此高台端，涉貌曜皎日，蕙心清且閒，美目扬玉泽，娥眉象翠翰，暮春春服成，霞粲綺與紈，金雀垂藻翘，琼珮結瑤璠，方駕扬清尘，濯足洛水澜，悲歌吐清响，雅韻播幽蘭，赴曲迅驚鸿，蹈節如集鸞，俯仰紛阿那，顧步鹹可歡。","sortOrder":75},
  {"id":"s_work_nvlt_41_76","chapterId":"ch_work_nvlt_41","text":"宋謝靈運日出東南隅行曰：柏梁冠南山，桂宮燿北泉，晨風拂幨幌，朝日照閨軒，美人臥屏席，懷蘭秀瑤璠，皎絜秋松氣，淑德春景暄。","sortOrder":76},
  {"id":"s_work_nvlt_41_77","chapterId":"ch_work_nvlt_41","text":"梁沈約日出東南隅行曰：朝日出邯鄲，照我丛台端，中有傾國艳，顧影織羅紈，幸有同匡好，西仕服秦官，寶劍垂玉貝，汗馬飾金鞍，萦場類轉雪，逸控寫騰鸞，羅衣夕解帶，玉釵暮垂冠。","sortOrder":77},
  {"id":"s_work_nvlt_41_78","chapterId":"ch_work_nvlt_41","text":"梁萧子顯日出東南隅行曰：大明上迢迢，陽城射凌霄，光照窗中婦，絕世同阿娇，逶迤梁家髻，冉弱楚宮腰，蠶籠拾芳翠，桑陌采柔條，路逢車馬客，飛蓋動襜轺，单衣鼠毛織，寶劍羊頭銷，大夫疲應對，御者輟衔鑣，女本西家宿，君自上宮要，漢馬三萬疋，夫婿仕嫖姚，十五張內侍，十八贾登朝。","sortOrder":78},
  {"id":"s_work_nvlt_41_79","chapterId":"ch_work_nvlt_41","text":"晉陆機君子有所思行曰：命駕登北山，延佇望城郭，鄽里一何盛，街巷紛漠漠，甲第崇高闼，洞房結阿閣，曲池何湛湛，清川帶花薄，人生誠行邁，容華隨年落，善哉膏粱士，榮生奧且博，無以酒肉資，取笑葵與藿。","sortOrder":79},
  {"id":"s_work_nvlt_41_80","chapterId":"ch_work_nvlt_41","text":"宋鮑昭代君子有所思行曰：西山登舊台，東下望雲闕，屑閣肅天君，馳道直如發，繡甍結飛霞，璇題納行月，陳鍾陪夕宴，歌笙待明發，年貌不可留，身意會盈歇。","sortOrder":80},
  {"id":"s_work_nvlt_41_81","chapterId":"ch_work_nvlt_41","text":"齊王融有所思曰：如何有所思，而無相見期，宿昔夢顏色，階庭尋履綦，高張更何已，引滿終自欹，欲知忧里老，為视鏡中絲。","sortOrder":81},
  {"id":"s_work_nvlt_41_82","chapterId":"ch_work_nvlt_41","text":"齊劉繪有所思行曰：別離安可再，而我更重之，佳人不相見，明月空在帷，共衔滿堂酌，獨斂向隅眉，心中亂如雪，寧知有所思。","sortOrder":82},
  {"id":"s_work_nvlt_41_83","chapterId":"ch_work_nvlt_41","text":"梁庾肩吾賦得有所思行曰：佳期竟不歸，春物坐芳菲，拂匣看離扇，开箱見別衣，井桐生未合，宮槐卷复稀，不及衔泥燕，從來相逐飛。","sortOrder":83},
  {"id":"s_work_nvlt_41_84","chapterId":"ch_work_nvlt_41","text":"梁沈約君子有所思行曰：晨策終南首，顧望鹹陽川，戚里溯曾闕，甲馆負崇軒，複涂希紫閣，重台擬望仙，巴姬幽蘭奏，鄭女陽春絃，共矜紅顏日，俱忘白發年，寂寥茂陵宅，照曜未央蝉，無以五鼎盛，顧嗤三經玄。","sortOrder":84},
  {"id":"s_work_nvlt_41_85","chapterId":"ch_work_nvlt_41","text":"梁王僧孺有所思行曰：夜風吹熠燿，朝光照昔邪，幾銷蘼芜葉，空落蒲桃花，不堪長織素，誰嗟獨澣紗，光陰复何極，望促反成賒，知君自荡子，奈妾亦倡家。","sortOrder":85},
  {"id":"s_work_nvlt_41_86","chapterId":"ch_work_nvlt_41","text":"晉陆機東武吟行曰：投跡短世間，高步長生闈，濯發冒雲冠，洗身被羽衣，飢從寒眾餐，寒就佚女栖。","sortOrder":86},
  {"id":"s_work_nvlt_41_87","chapterId":"ch_work_nvlt_41","text":"宋鮑昭東武吟行曰：主人且勿喧，賤子歌一言，仆本寒乡士，出身蒙漢恩，始隨張校尉，召募到河源，後逐李輊車，追虜窮塞垣，密涂亘萬里，寧歲猶七奔，將軍既即世，部曲亦罕存，時事一朝異，孤績誰复論，少壮辭家去，窮老還入門，昔如韝上鷹，今似槛中猿，徒結千載恨，空負百年怨，弃席思君幄，疲馬恋君軒，原垂晉主惠，不媿田子魂。","sortOrder":87},
  {"id":"s_work_nvlt_41_88","chapterId":"ch_work_nvlt_41","text":"梁沈約東武吟行曰：天德深且曠，人世賤而浮，東枝裁拂景，西壑已停辀，遊辭金門寵，去飲玉池流，宵辔絕永矣，俗累從此休。","sortOrder":88},
  {"id":"s_work_nvlt_41_89","chapterId":"ch_work_nvlt_41","text":"晉陆機順東西門行曰：日出西門望天庭，陽穀既虛崦嵫盈，逝者若斯安得停，迨未年暮及世平，置酒高堂宴友生，取樂今日盡歡情。","sortOrder":89},
  {"id":"s_work_nvlt_41_90","chapterId":"ch_work_nvlt_41","text":"宋謝惠連順東西門行曰：哀朝囷，愍頹力，遷化常然焉肯息，及壮齒，遇世直，酌酩華堂集親識，舒情盡歡遣凄惻。","sortOrder":90},
  {"id":"s_work_nvlt_41_91","chapterId":"ch_work_nvlt_41","text":"又都東西門行曰：慷恺發想思，惆怅恋音徽，四節競阑候，六龍引頹機，人生隨時变，遷化焉可祈，百年難必保，千慮盈懷之。","sortOrder":91},
  {"id":"s_work_nvlt_41_92","chapterId":"ch_work_nvlt_41","text":"梁沈約都東西門行曰：驅馬西城阿，回眺想京闕，望極煙原盡，地遠山河没，歲華委徂邈，年霜移暮發。","sortOrder":92},
  {"id":"s_work_nvlt_41_93","chapterId":"ch_work_nvlt_41","text":"魏文帝上留田行曰：居世一何不同，上留田，富人食稻與粱，上留田，貧子食糟與糠，貧賤亦何傷，上留田，祿命懸在蒼天，上留田，命爾叹息將欲誰怨，上留田。","sortOrder":93},
  {"id":"s_work_nvlt_41_94","chapterId":"ch_work_nvlt_41","text":"晉陆機上留田行曰：［平徵調。］嗟行人之藹藹，駿馬陟原風馳，輕舟汎川雷邁，寒往暑來相尋，零雪霏霏集宇，悲風徘徊入襟，歲華冉冉方除，我思纏綿未纾，感時悼逝凄如。","sortOrder":94},
  {"id":"s_work_nvlt_41_95","chapterId":"ch_work_nvlt_41","text":"又齊謳行曰：營丘負海曲，沃野爽且平，洪川控河濟，崇山入高冥，東被姑尤侧，南界聊攝城，孟諸吞楚夢，百二侔秦京，惟師恢東表，桓後定周傾，天道有迭代，人道無久盈，行行將复去，長存非所營。","sortOrder":95},
  {"id":"s_work_nvlt_41_96","chapterId":"ch_work_nvlt_41","text":"梁沈約齊謳行曰：東秦稱右地，川隰固夷昶，層峰駕蒼雲，濁河流素壤，青丘良杳鬱，淄宮信疏敞，王佐改殷命，霸功缪周網。","sortOrder":96},
  {"id":"s_work_nvlt_41_97","chapterId":"ch_work_nvlt_41","text":"晉陆機隴西行曰：我靜如鏡，民動如煙，事以形兆，應以象懸，豈曰無才，世鮮興賢。","sortOrder":97},
  {"id":"s_work_nvlt_41_98","chapterId":"ch_work_nvlt_41","text":"宋謝惠連隴西行曰：運有榮枯，道有舒屈，潛保黃裳，顯服朱黻，誰能守靜，弃華辭榮，窮穀是處，考槃是營，千金不回，百代傳名，厥包者柚，忘忧者萱，何為有用，自乖中原，實摘柯摧，葉殒條煩。","sortOrder":98},
  {"id":"s_work_nvlt_41_99","chapterId":"ch_work_nvlt_41","text":"梁簡文帝隴西行曰：邊秋胡馬肥，雪中驚寇入，勇氣時無侣，輕兵救邊急，沙平不見虜，嶂崄還相及，出塞豈成歌，經川未遑汲，乌孫涂更阻，康居路猶涩，月晕抱龍城，星眉照馬邑，長安路遠書不還，寧知征人獨佇立。","sortOrder":99},
  {"id":"s_work_nvlt_41_100","chapterId":"ch_work_nvlt_41","text":"晉陆機吳趍行曰：楚妃且勿叹，齊娥且莫謳，四坐併清聽，聽我歌吳趍。吳趍自有紀，請從昌門起，昌門何瓘瓘，飛閣跨通波，重栾承璇極，回軒啟曲阿，大伯导仁風，仲雍扬其波，穆穆延陵子，灼灼光其華，大皇自富春，矯手頓世羅。邦彦應運興，粲若春林葩，屬城鹹有士，吳邑最為多。","sortOrder":100},
  {"id":"s_work_nvlt_41_101","chapterId":"ch_work_nvlt_41","text":"漢班婕妤怨歌行曰：新裂齊紈素，皎絜如霜雪，裁為合歡扇，团团似明月，出入君懷袖，動搖微風發，常恐秋節至，涼風奪炎熱，弃捐箧笥中，恩情中道絕。","sortOrder":101},
  {"id":"s_work_nvlt_41_102","chapterId":"ch_work_nvlt_41","text":"梁江淹擬班婕妤詠扇曰：紈扇如团月，出自機中素，畫作秦王女，乘鸞向煙霧，竊愁秋涼至，吹我玉階树，君子恩未畢，零落委中路。","sortOrder":102},
  {"id":"s_work_nvlt_41_103","chapterId":"ch_work_nvlt_41","text":"魏陳王曹植怨歌行曰：為君既不易，為臣良獨難，忠信事不顯，乃有見疑患，周旦佐文武，金縢功不刊，推心辅王政，二叔反流言，待罪居東國，泣涕當留連，皇靈天動变，震雷風且寒，拔树偃秋稼，天威不可幹，素服开金縢，感悟求其端，公旦事既顯，成王乃哀叹，吾欲竟此曲，此曲悲且長，今日樂相樂，別後莫相忘，晉傅玄怨詩曰：昔為春蠶緒，今為秋女衣，丹唇形素齒，翠采發娥眉，玉顏虧有時，秀色隨年衰，常恐新間舊，变故興細微，浮萍本無根，非水將何依。","sortOrder":103},
  {"id":"s_work_nvlt_41_104","chapterId":"ch_work_nvlt_41","text":"梁沈約怨歌行曰：時屯寧易犯，俗险信難群，坎壈元淑賦，頓挫敬通文，遽論班姬寵，夙窆贾生墳，短俗同如此，長叹欲何雲。","sortOrder":104},
  {"id":"s_work_nvlt_41_105","chapterId":"ch_work_nvlt_41","text":"魏文帝苦寒行曰：北上太行山，艱哉何巍巍，羊腸坂詰屈，車輪為之摧，垅树何萧瑟，北風聲正悲，溪穀少人民，雪落何霏霏，簷囊行取薪，斧冰待作麋，哀彼東山詩，悠悠使我悲。","sortOrder":105},
  {"id":"s_work_nvlt_41_106","chapterId":"ch_work_nvlt_41","text":"晉陆機苦寒行曰：北遊幽朔城，涼野多险艱，凝冰結重涧，積雪被長峦，陰雲興巖侧，悲風鳴树端，渴飲堅冰漿，飢食零露餐，剧哉人行役，慊慊恒苦寒。","sortOrder":106},
  {"id":"s_work_nvlt_41_107","chapterId":"ch_work_nvlt_41","text":"宋謝靈運苦寒行曰：歲歲曾冰合，紛紛霰雪落，浮陽滅清暉，寒禽叫悲壑，飢爨煙不興，渴汲水枯涸。","sortOrder":107},
  {"id":"s_work_nvlt_41_108","chapterId":"ch_work_nvlt_41","text":"魏文帝善哉行曰：有美一人，婉如青陽，知音識曲，善為樂方，流鄭激楚，度宮中商，感心動耳，綺麗難忘。","sortOrder":108},
  {"id":"s_work_nvlt_41_109","chapterId":"ch_work_nvlt_41","text":"魏陳思王曹植善哉行曰：來日大難，口燥唇乾，今日相樂，皆當喜歡，径歷名山，芝草翩翩，仙人王乔，奉藥一丸，自惜袖短，內手知寒，慚無靈辄，以救趙宣，月没參橫，北斗阑幹，親友在門，飢不及餐。","sortOrder":109},
  {"id":"s_work_nvlt_41_110","chapterId":"ch_work_nvlt_41","text":"宋謝惠連善哉行曰：涼來溫謝，寒往暑却，陰灌陽藂，彫華墜萼，击節當歌，對酒親酌，鄙哉愚人，戚戚懷瘼，善哉達士，滔滔處樂。","sortOrder":110},
  {"id":"s_work_nvlt_41_111","chapterId":"ch_work_nvlt_41","text":"魏文帝苦哉行曰：上山采薇，薄暮苦飢，溪穀多風，霜露霑衣，高山有林，崖木有枝，忧來無方，人莫知之，今我不樂，歲月若馳，湯湯川流，中有行舟，隨波轉泊，有似客遊。","sortOrder":111},
  {"id":"s_work_nvlt_41_112","chapterId":"ch_work_nvlt_41","text":"魏陳思王曹植君子行曰：君子防未然，不處嫌疑間，瓜田不納履，李下不正冠，周公下白屋，吐哺不及餐，一沐三握發，後人稱聖賢。","sortOrder":112},
  {"id":"s_work_nvlt_41_113","chapterId":"ch_work_nvlt_41","text":"晉陆機君子行曰：天道夷且簡，人道险而艱，休咎相乘躡，翻覆各波澜，去疾苦不遠，疑似實生患。","sortOrder":113},
  {"id":"s_work_nvlt_41_114","chapterId":"ch_work_nvlt_41","text":"梁簡文帝君子行曰：君子懷琬琰，不使涅尘淄，從容子雲閣，寂寞仲舒帷，多謝悠悠子，管窥良可悲。","sortOrder":114},
  {"id":"s_work_nvlt_41_115","chapterId":"ch_work_nvlt_41","text":"梁沈約君子行曰：良御或燕楚，妙察亂渑淄，隄傾由漏坏，垣隙自危基，嚣途或妄踐，谠義勿輕持。","sortOrder":115},
  {"id":"s_work_nvlt_41_116","chapterId":"ch_work_nvlt_41","text":"梁戴暠君子行曰：畫野依德星，开鄽對廉水，接越稱交讓，連树名君子，數非唯二失，升階無三止，探甑不凝尘，正冠還避李，寄言蘧伯玉，無為嗟獨恥。","sortOrder":116},
  {"id":"s_work_nvlt_41_117","chapterId":"ch_work_nvlt_41","text":"魏文帝猛虎行曰：與君媾新歡，讬配於二儀，充列於紫微，升降焉可知，何梧攀鳳翼，雲雨散洪池。","sortOrder":117},
  {"id":"s_work_nvlt_41_118","chapterId":"ch_work_nvlt_41","text":"晉陆機猛虎行曰：渴不飲盜泉水，熱不息惡木陰，惡木豈無枝，志士苦用心，整駕肅時命，振策將遠尋，飢食猛虎窟，寒栖野雀林。","sortOrder":118},
  {"id":"s_work_nvlt_41_119","chapterId":"ch_work_nvlt_41","text":"宋謝惠連猛虎行曰：貧不攻九疑玉，倦不憩三危峰，九疑有或號，三危無安容，美物摽貴用，志士厲奇蹤，如何抵遠役，王命宜肅恭，伐鼓功未著，振旅何時從。","sortOrder":119},
  {"id":"s_work_nvlt_41_120","chapterId":"ch_work_nvlt_41","text":"魏陳王曹植平陆東行曰：閶阖开，天衢通，被我羽衣乘飛龍，飛龍與仙期，東上蓬萊采靈芝，靈芝采之可服食，年若王父無終極。","sortOrder":120},
  {"id":"s_work_nvlt_41_121","chapterId":"ch_work_nvlt_41","text":"又苦思行曰：绿萝緣玉树，光曜粲相暉，下有兩真人，舉翅翻高飛，我心何踴躍，思欲攀雲追，鬱鬱西嶽顛，石室青怱與天連，中有耆年隱士須發皆皓然，策杖從吾遊，教我要忘言。","sortOrder":121},
  {"id":"s_work_nvlt_41_122","chapterId":"ch_work_nvlt_41","text":"魏文帝甄皇後塘上行曰：蒲生我池中，蒲葉何離離，傍能行仁義，莫若妾自知，眾口烁黃金，使君生別離，莫以毫發故，弃捐素所愛，莫以魚肉賤，弃捐葱與薤，莫以麻枲賤，弃捐菅與蒯。","sortOrder":122},
  {"id":"s_work_nvlt_41_123","chapterId":"ch_work_nvlt_41","text":"晉陆機塘上行曰：江蓠生幽渚，微芳不足宣，被蒙風雲會，移居華池邊，天道有遷易，人理無常全，男稚智傾愚，女愛衰避妍，不惜微驅［《文選》二十八作軀。］退，但懼蒼蠅前，原君廣末光，照妾薄暮年。","sortOrder":123},
  {"id":"s_work_nvlt_41_124","chapterId":"ch_work_nvlt_41","text":"宋謝惠連塘上行曰：芳萱秀凌阿，菲质不足營，幸有忘忧用，移根讬君庭，垂穎臨清池，擢彩仰華甍，霑渥雲雨润，葳蕤吐芳馨，原君春傾葉，留景惠餘明。","sortOrder":124},
  {"id":"s_work_nvlt_41_125","chapterId":"ch_work_nvlt_41","text":"梁沈約塘上行曰：泽蘭被荒径，孤芳豈自通，幸逢瑤池曠，得與金芝丛，既美脩嫮女，复怳繁華童，夙昔玉霜滿，旦暮翠條空，财殫交易絕，華落色難終，所原昭陽景，時照長門宮。","sortOrder":125},
  {"id":"s_work_nvlt_41_126","chapterId":"ch_work_nvlt_41","text":"梁劉孝威塘上行苦辛篇曰：蒲生伊何陳，曲中多苦辛，黃金坐銷鑠，白玉遂淄磷，裂衣工毀嫡，掩袖切讒新，嫌成跡易已，愛去理難申，秦雲猶变色，魯日尚回輪，妾歌已唱斷，君心終未親。","sortOrder":126},
  {"id":"s_work_nvlt_41_127","chapterId":"ch_work_nvlt_41","text":"古相逢行曰：相逢狹路間，道隘不容車，不知何年少，夹轂問君家，君家誠易知，易知复難忘，黃金為君門，璧玉為君堂，中庭生桂树，華燈何煌煌，兄弟兩三人，中子為侍郎，五日因來歸，道上自生光，黃金絡馬頭，觀者盈道傍，入門一左顧，但見双鴛鴦，大婦織綺羅，中婦織流黃，小婦無所為，挟瑟上高堂，丈人且安坐，調絃未遽央。","sortOrder":127},
  {"id":"s_work_nvlt_41_128","chapterId":"ch_work_nvlt_41","text":"宋謝靈運相逢行曰：行行即長道，長道息班草，邂逅賞心人，與我傾懷抱，夷世信難值，浮生不可保。","sortOrder":128},
  {"id":"s_work_nvlt_41_129","chapterId":"ch_work_nvlt_41","text":"梁張率相逢行曰：相逢夕陰街，獨趨尚冠里，高門既如一，甲第复相似，凭軾日欲昏，何處訪公子，公子之所在，所在良易知，青樓出上路，漸台臨曲池，兄弟兩三人，冠佩紛陆離，朝從禁中出，車騎併驅馳，金鞍馬腦勒，聚觀路傍兒，大婦刺方領，中婦抱婴兒，小婦尚娇稚，端坐吹參差，丈人幸無遽，神鳳且來儀。","sortOrder":129},
  {"id":"s_work_nvlt_41_130","chapterId":"ch_work_nvlt_41","text":"古驅車上東門行曰：驅車上東門，遙望北郭墓，白楊何萧萧，松柏夹廣路，下有陳死人，杳杳即長暮，潛寐黃泉下，千載不覺寤，浩浩陰陽移，年命如朝露，服食求神仙，多為藥所誤，不如飲美酒，被服紈與素。","sortOrder":130},
  {"id":"s_work_nvlt_41_131","chapterId":"ch_work_nvlt_41","text":"晉陆機駕言出北闕行曰：驅馬上東門，［冯校本雲，意是題下註，今混寫耳。］駕言出北闕，踯躅遵山陵，長松何鬱鬱，丘墓互相承，念昔徂殁子，悠悠不可勝，人生何所促，忽如朝露凝，求仙鮮克仙，太虛不可凌。","sortOrder":131},
  {"id":"s_work_nvlt_41_132","chapterId":"ch_work_nvlt_41","text":"宋鮑昭驅馬上東門行曰：傷禽見絃驚，倦客惡離聲，離聲斷客情，賓御皆涕零，涕零心斷絕，將去复還訣，一息不相知，何况異乡別，遙遙征駕遠，杳杳落日晚，居人掩閨臥，行子野中飯，食梅常苦酸，衣葛常苦寒，絲竹徒滿座，忧人不解顏，長歌欲自慰，弥起長恨端。","sortOrder":132},
  {"id":"s_work_nvlt_41_133","chapterId":"ch_work_nvlt_41","text":"晉陆機從軍行曰：苦哉遠征人，飄飖窮西河，南涉五嶺顛，北戍長城阿，胡馬如雲屯，越旂亦星羅，朝食不免胄，夕息常負戈，苦哉遠征人，拊心悲如何。","sortOrder":133},
  {"id":"s_work_nvlt_41_134","chapterId":"ch_work_nvlt_41","text":"宋顏延之從軍行曰：苦哉遠征人，畢力输時艱，秦初略陽越，漢世爭陰山，羽檄旦暮急，旌旗晝夜懸，臥伺金柝响，起候亭燧燃，悲矣遠征人，苦哉私自怜。","sortOrder":134},
  {"id":"s_work_nvlt_41_135","chapterId":"ch_work_nvlt_41","text":"梁簡文帝從軍行曰：貳師惜善馬，樓蘭貪漢财，前年出右地，今歲謝輪台，魚雲望旗聚，龍沙隨陣开，冰城朝浴鐵，地道夜衔枚，將軍號令密，天子玺書催，何時反舊里，遙見下機來。","sortOrder":135},
  {"id":"s_work_nvlt_41_136","chapterId":"ch_work_nvlt_41","text":"又曰：雲中亭障羽檄驚，甘泉烽火通夜明，貳師將軍新筑營，嫖姚校尉初出征，复有山西將，絕世愛雄名，三門應遯甲，五壘學神兵，白雲隨旆色，蒼山答鼓聲，先平小月陣，却滅大宛城，善馬還長道，黃金付水衡，小婦趙人能鼓瑟，侍婢初笄解鄭聲，庭前柳絮飛欲合，必應紅妆來起迎。","sortOrder":136},
  {"id":"s_work_nvlt_41_137","chapterId":"ch_work_nvlt_41","text":"梁萧子顯從軍行曰：左角名王侵漢邊，輕薄良家惡少年，縱橫向沮泽，凌厲取山田，黃尘不見景，飛蓬恒滿天，邊功封浞野，竊寵劫祁連，春風春月將進酒，夭姬舞女亂君前。","sortOrder":137},
  {"id":"s_work_nvlt_41_138","chapterId":"ch_work_nvlt_41","text":"梁戴暠從軍詩曰：長安夜刺閨，胡騎白銅鞮，詔書發隴右，召募取關西，劍懸三尺鞘，鎧累七重犀，侵星出柳塞，际晚入榆溪，陰山日不著，長城風自凄，弓寒折錦鞬，馬冻滑斜蹄，登山试下趙，凭軾且平齊，當今函穀上，唯見一丸泥。","sortOrder":138},
  {"id":"s_work_nvlt_41_139","chapterId":"ch_work_nvlt_41","text":"晉陆機悲哉行曰：遊客芳春林，春芳傷客心，和風飛清响，鮮雲垂薄陰，蕙草饒淑氣，時鳥多好音，傷哉遊客士，忧思一何深，原讬歸風响，寄言遺所钦。","sortOrder":139},
  {"id":"s_work_nvlt_41_140","chapterId":"ch_work_nvlt_41","text":"宋謝靈運悲哉行曰：萋萋春草生，王孫遊有情，差池燕始飛，夭裊柳初榮。","sortOrder":140},
  {"id":"s_work_nvlt_41_141","chapterId":"ch_work_nvlt_41","text":"梁沈約悲哉行曰：旅遊媚年春，年春媚遊人，徐光旦垂彩，和露晓凝津，時嘤起稚葉，蕙氣動初蘋，一朝阻舊國，萬里隔良辰。","sortOrder":141},
  {"id":"s_work_nvlt_41_142","chapterId":"ch_work_nvlt_41","text":"晉張華門有車馬客行曰：門有車馬客，問君何乡士，捷步往相訊，果是舊鄰里，語昔有故悲，論今無新喜，清晨相訪慰，日暮不能已，詞端競未究，忽唱分途始，前悲尚未弭，後忧方复起。","sortOrder":142},
  {"id":"s_work_nvlt_41_143","chapterId":"ch_work_nvlt_41","text":"晉陆機門有車馬客行曰：門有車馬客，駕言發故乡，念君久不歸，濡跡涉江湘，投袂起門途，攬衣不及裝，借問邦族間，惻怆論存亡，天道信崇替，人生安得長。","sortOrder":143},
  {"id":"s_work_nvlt_41_144","chapterId":"ch_work_nvlt_41","text":"《藝文類聚》　唐·欧陽詢","sortOrder":144},
  {"id":"s_work_nvlt_42_1","chapterId":"ch_work_nvlt_42","text":"卷四十二樂部二","sortOrder":1},
  {"id":"s_work_nvlt_42_2","chapterId":"ch_work_nvlt_42","text":"○樂府","sortOrder":2},
  {"id":"s_work_nvlt_42_3","chapterId":"ch_work_nvlt_42","text":"◇樂府","sortOrder":3},
  {"id":"s_work_nvlt_42_4","chapterId":"ch_work_nvlt_42","text":"魏武帝短歌行曰：對酒當歌，人生幾何，譬如朝露，去日苦多，明明如月，何時可掇，忧從中來，不可斷絕，月明星稀，乌鵲南飛，繞树三匝，何枝可依，山不厭高，海不厭深，周公吐哺，天下歸心。","sortOrder":4},
  {"id":"s_work_nvlt_42_5","chapterId":"ch_work_nvlt_42","text":"陆機短歌行曰：置酒高堂，悲歌臨觴，人寿幾何，逝如朝霜，時無重至，華不再陽，蘋以春暉，蘭以秋芳，來日苦短，去日苦長，今我不樂，蟋蟀在房。","sortOrder":5},
  {"id":"s_work_nvlt_42_6","chapterId":"ch_work_nvlt_42","text":"古長歌行曰：青青園中葵，朝露待日晞，陽春布德泽，萬物生光辉，常恐秋節至，焜黃華葉衰，百川東到海，何時复西歸，少壮不努力，老大徒傷悲。","sortOrder":6},
  {"id":"s_work_nvlt_42_7","chapterId":"ch_work_nvlt_42","text":"又曰：昭昭清明月，辉光燭我床，忧人不能寐，耿耿夜何長，微風冲閨闼，羅帷自飄颺，攬衣曳長帶，屣履下高堂。","sortOrder":7},
  {"id":"s_work_nvlt_42_8","chapterId":"ch_work_nvlt_42","text":"魏明帝長歌行曰：靜夜不能寐，耳聆眾禽鳴，入城育狐兔，高墉多鳥聲，中心感時物，攬劍下閒庭，翔佯於階际，景星一何明。","sortOrder":8},
  {"id":"s_work_nvlt_42_9","chapterId":"ch_work_nvlt_42","text":"晉陆機長歌行曰：逝矣經天日，悲哉帶地川，寸陰無停晷，尺波徒自旋，遠期鮮克及，盈數固希全。","sortOrder":9},
  {"id":"s_work_nvlt_42_10","chapterId":"ch_work_nvlt_42","text":"梁沈約長歌行曰：連連舟壑改，微微市朝变，局涂頓遠策，留歡限奔箭，春貌既移紅，秋林豈停蒨，一倍茂陵道，寧思柏梁宴，長戢兔園情，永別金華殿。","sortOrder":10},
  {"id":"s_work_nvlt_42_11","chapterId":"ch_work_nvlt_42","text":"魏文帝煌煌京洛行曰：嗟彼樂生，古之雅人，智矣燕昭，可謂得臣，瓘瓘仲連，齊之高士，北辭千金，東蹈沧海。","sortOrder":11},
  {"id":"s_work_nvlt_42_12","chapterId":"ch_work_nvlt_42","text":"宋鮑昭代京洛篇曰：鳳台十二重，四戶八綺窗，繡桷金莲花，桂柱玉盤龍，珠帘無隔露，羅幌不勝風，春吹回白日，霜歌落塞鸿，但懼秋尘起，盛愛逐衰蓬，坐视青苔滿，臥對錦筵空，琴筑縱橫散，舞衣不复縫。","sortOrder":12},
  {"id":"s_work_nvlt_42_13","chapterId":"ch_work_nvlt_42","text":"梁簡文帝京洛篇曰：南遊偃師縣，斜上灞陵東，回瞻龍首堞，遙望德陽宮，重門遠照耀，天闕复穹隆，夜輪懸素魄，朝光荡碧空，秋霜晓驅雁，春雨暮成虹，曲陽造甲第，高安還禁中，劉蒼歸作相，窦憲出臨戎，惟此兩京盛，歡宴遂無窮。","sortOrder":13},
  {"id":"s_work_nvlt_42_14","chapterId":"ch_work_nvlt_42","text":"梁戴暠煌煌京洛篇曰：欲知佳麗地，為君陳帝京，由來稱俠窟，爭利复爭名，鑄銅門外馬，刻石水中鯨，黑龍過飲渭，丹鳳俯臨城，群公惡郭解，天子問黃琼，詔幸平陽第，騎指伏波營，五侯同拜爵，七貴各垂纓，揮金留客坐，饌玉待鍾聲，獨有文園令，偏嗟武騎輕。","sortOrder":14},
  {"id":"s_work_nvlt_42_15","chapterId":"ch_work_nvlt_42","text":"魏陳王曹植名都篇曰：名都多妖麗，京洛出少年，寶劍直千金，被服麗且鮮，斗雞長安道，走馬長楸間，驅馳未能半，双兔過我前，左挽因右發，一縱兩禽連，餘功未及展，仰手接飛鳶，歸來宴平樂，美酒斗十千。","sortOrder":15},
  {"id":"s_work_nvlt_42_16","chapterId":"ch_work_nvlt_42","text":"又白馬篇曰：白馬飾金羁，連翩西北馳，借問誰家子，幽併遊俠兒，少小去乡邑，扬名沙漠垂，控絃破左的，右發摧月支，仰手接飛猱，俯身散馬蹄，邊城多警急，胡虜數遷移，羽檄從北來，厲馬登高堤，寄身鋒刃端，性命安可懷，高名在壮籍，不得中顧私，捐軀赴國難，视死忽若歸。","sortOrder":16},
  {"id":"s_work_nvlt_42_17","chapterId":"ch_work_nvlt_42","text":"宋袁淑效曹子建白馬篇曰：劍騎何翩翩，長安五陵間，秦地天下枢，八方凑才賢，荆魏多壮士，宛洛富少年，義分明於霜，信行直如絃，俠烈良有聞，古來共知然。","sortOrder":17},
  {"id":"s_work_nvlt_42_18","chapterId":"ch_work_nvlt_42","text":"宋鮑昭代陳王白馬篇曰：白馬骍角弓，鳴鞭垂北風，要途問邊急，雜虜入雲中，薄暮雪雲起，飛沙被遠松，弃別中國愛，要冀胡馬功，但令塞上兒，知我獨為雄。","sortOrder":18},
  {"id":"s_work_nvlt_42_19","chapterId":"ch_work_nvlt_42","text":"梁沈約白馬篇曰：白馬紫金鞍，停鑣過上蘭，赤坂涂三折，龍堆路九蟠，水生肌里冻，風起骨中寒，唯見恩義重，豈覺衣裳单，本持驅命苦，幸遇身得完。","sortOrder":19},
  {"id":"s_work_nvlt_42_20","chapterId":"ch_work_nvlt_42","text":"梁徐悱擬白馬篇曰：要功非汗馬，報效有鋒端，日没塞雲起，風悲起胡地寒，歸報明天子，燕然今复刊。","sortOrder":20},
  {"id":"s_work_nvlt_42_21","chapterId":"ch_work_nvlt_42","text":"魏文帝燕歌行曰：秋風萧瑟天氣涼，草木搖落露為霜，群燕爭歸雁南翔，念君遠遊多思腸，慊慊思歸恋故乡，何為淹留寄他方，賤妾茕茕守空房，忧來思君不敢忘。","sortOrder":21},
  {"id":"s_work_nvlt_42_22","chapterId":"ch_work_nvlt_42","text":"魏明帝燕歌行曰：白日晼晼忽西傾，霜露惨凄涂階庭，秋草卷葉摧枝茎，翩翩飛蓬常獨征，有似遊子不安寧。","sortOrder":22},
  {"id":"s_work_nvlt_42_23","chapterId":"ch_work_nvlt_42","text":"晉陆機燕歌行曰：四時代序逝不追，寒風習習落葉飛，蟋蟀在堂露盈階，念君遠遊苦恒悲，君何緬然久不歸。","sortOrder":23},
  {"id":"s_work_nvlt_42_24","chapterId":"ch_work_nvlt_42","text":"宋謝惠連燕歌行曰：四時推遷迅不停，三秋萧瑟葉辭茎，霏霜被野雁南征，念君客遊羁思盈，何為淹留無歸聲，愛而不見傷心情。","sortOrder":24},
  {"id":"s_work_nvlt_42_25","chapterId":"ch_work_nvlt_42","text":"梁元帝燕歌行曰：燕趙佳人本自多，遼東少婦學春歌，黃龍戍北花如錦，玄兔城前月似蛾，如何此時別夫婿，金羁翠毦往交河，還聞入漢去燕營，怨妾愁心百恨生，漫漫悠悠天未晓，遙遙夜夜聽寒更，自從異縣同心別，偏恨同時成異節，橫波滿脸萬行啼，翠眉暫斂千重結，併海連天合不开，那堪春日上春台，唯見遠舟如落葉，复看遙舸似行杯，沙汀夜鶴嘯羁雌，妾心無趣坐傷離，翻嗟漢使音尘斷，空傷賤妾燕南垂。","sortOrder":25},
  {"id":"s_work_nvlt_42_26","chapterId":"ch_work_nvlt_42","text":"周王襃燕歌行曰：初春麗日湋欲娇，桃花流水没河桥，薔薇花开百重葉，楊柳覆地數千條，自從昔別春燕分，經年一去不相聞，無复漢地關山月，唯有漠北蓟城雲，屬國小婦猶年少，羽林輕騎數征行，遙聞陌頭采桑曲，猶勝胡笳邊地聲，胡笳向暮使人泣，長望閨中空佇立，桃抽覆地春花舒，桐生井底寒葉疏，试為來看上林雁，應有遙寄隴頭書。","sortOrder":26},
  {"id":"s_work_nvlt_42_27","chapterId":"ch_work_nvlt_42","text":"周庾信燕歌行曰：岱北雲氣晝昏昏，千里飛蓬無复根，寒雁一一度遼水，桑葉紛紛落蓟門，晉陽山頭無箭竹，疏勒城中乏水源，屬國征戍久離居，陽關音信絕能疏，原得魯連飛一箭，持寄思歸燕將書，度遼本自有將軍，寒風萧萧生水濱，妾驚甘泉旦烽火，君訝漁陽多陣雲，自從將軍出細柳，荡子空床定難守，盤龍明鏡餉秦嘉，辟惡生香寄韓寿，洛陽遊絲百丈連，黃河春冰千片穿，桃花顏色如好馬，榆荚新开似細錢，蒲桃一杯千日醉，無事九轉學神仙，定取金丹作幾服，能令華表得千年。","sortOrder":27},
  {"id":"s_work_nvlt_42_28","chapterId":"ch_work_nvlt_42","text":"魏文帝月重輪行曰：三辰垂光，照臨四海，煥哉何煌煌，悠悠與天地久長，愚見目前，聖睹萬年，明闇相絕，何可勝言。","sortOrder":28},
  {"id":"s_work_nvlt_42_29","chapterId":"ch_work_nvlt_42","text":"魏明帝月重輪行曰：天地無窮，人命有終，立功扬名，行之在躬，聖賢度量，得為道中。","sortOrder":29},
  {"id":"s_work_nvlt_42_30","chapterId":"ch_work_nvlt_42","text":"梁戴暠月重輪篇曰：皇基屬明朗，副德表重輪，輪重非是晕，桂滿自恒春，海珠全更减，階蓂翳且新，婕妤譬团扇，曹王比洛神，北堂豈盈手，西園偏照人。","sortOrder":30},
  {"id":"s_work_nvlt_42_31","chapterId":"ch_work_nvlt_42","text":"魏陳王曹植飛龍篇曰：晨遊太山，雲霧窈窕，忽逢二童，顏色鮮好，乘彼白鹿，手翳芝草，西登玉堂，金樓複道，投我此藥，神皇可造，寿同金石，永世難老。","sortOrder":31},
  {"id":"s_work_nvlt_42_32","chapterId":"ch_work_nvlt_42","text":"又吁嗟篇曰：吁嗟此轉蓬，居世何獨然，長去本根逝，宿昔無休閒，原為中林草，秋隨野火燔。","sortOrder":32},
  {"id":"s_work_nvlt_42_33","chapterId":"ch_work_nvlt_42","text":"又虾〈魚旦〉篇曰：虾〈魚旦〉遊潢潦，不知江海流，燕雀戲蕃柴，安識鸿鶴遊，世士比誠明，大德故無畴。","sortOrder":33},
  {"id":"s_work_nvlt_42_34","chapterId":"ch_work_nvlt_42","text":"又种葛篇曰：种葛南山下，葛蔓自成陰，與君初定婚，結發恩義深，行年將晚暮，佳人懷異心，恩紀曠不接，我情遂抑沉。","sortOrder":34},
  {"id":"s_work_nvlt_42_35","chapterId":"ch_work_nvlt_42","text":"又驅車篇曰：神哉彼太山，五嶽顯其名，隆高貫雲霓，珪瓘出太清，周流二六候，間置十二亭，上有涌醴泉，玉石楊華英，車北望吳野，西眺觀日精，王者以歸天，效厥元功成。","sortOrder":35},
  {"id":"s_work_nvlt_42_36","chapterId":"ch_work_nvlt_42","text":"又當欲遊南山篇曰：東海廣且深，由卑下百川，五嶽雖高大，不逆垢與尘，嘉善而矜愚，大聖亦同然，仁者必寿考，八坐鹹萬年。","sortOrder":36},
  {"id":"s_work_nvlt_42_37","chapterId":"ch_work_nvlt_42","text":"又仙人篇曰：仙人攬六箸，對博太山隅，湘娥拊琴瑟，素女吹笙竽，玉樽盈桂酒，河伯獻神魚，回駕過紫微，與帝合靈符，閶阖正珪瓘，双闕萬丈餘。","sortOrder":37},
  {"id":"s_work_nvlt_42_38","chapterId":"ch_work_nvlt_42","text":"又升天行曰：乘蹻追術士，遠之蓬萊山，靈液飛素波，蘭桂上參天，玄豹遊其下，翔鵾戲其巔，乘風忽登舉，彷彿見眾仙。","sortOrder":38},
  {"id":"s_work_nvlt_42_39","chapterId":"ch_work_nvlt_42","text":"又，扶桑之所出，乃在朝陽谿，中心陵蒼吳，［本集作昊。］布葉蓋天崖，日出登東幹，既夕没西枝，原得紆陽辔，回日使東馳。","sortOrder":39},
  {"id":"s_work_nvlt_42_40","chapterId":"ch_work_nvlt_42","text":"宋鮑昭升天行曰：倦見物興衰，骤睹俗屯平，窮途悔短計，晚志重長生，從師入遠嶽，結友事仙靈，風餐委松宿，雲臥恣天行，暫遊越萬里，近別數千齡。","sortOrder":40},
  {"id":"s_work_nvlt_42_41","chapterId":"ch_work_nvlt_42","text":"晉傅玄歷九秋篇曰：歷九秋兮三春，遣貴客兮一賓，顧名君心所親，乃命妙妓才人，窮八音兮異倫，微披素齒丹唇，逸响飛薄梁尘，精爽眇眇入神，荠與麥兮夏零，蘭桂踐霜逾馨，妾心結意丹青，何忧君心中傾。","sortOrder":41},
  {"id":"s_work_nvlt_42_42","chapterId":"ch_work_nvlt_42","text":"又車遙篇曰：車遙遙兮馬洋洋，追思君兮不可忘，君安遊兮西入秦，原為影兮隨君身。","sortOrder":42},
  {"id":"s_work_nvlt_42_43","chapterId":"ch_work_nvlt_42","text":"梁簡文帝渡關山行曰：關山遠可度，遠度复難思，直指遮歸道，都護總前期，力農爭地利，轉戰逐天時，材官蹶張皆命中，弘農越騎盡褰旗，褰旗遠不息，驅虜何窮極，狼居一封難再睹，閼氏永去無容色，銳氣且橫行，朱旗亂日精，先屠光祿寨，却破夫人城，凯還歸舊里，非是衒功名。","sortOrder":43},
  {"id":"s_work_nvlt_42_44","chapterId":"ch_work_nvlt_42","text":"梁戴暠度關山篇曰：昔聽隴頭吟，平居已流涕，今上關山望，長安树如荠，千里非乡邑，百姓為兄弟，武帝初承平，東伐复西征，催令四校出，倚望三邊平，丈夫意氣本自然，來時辭第已聞天，但令此心與命在，不持烽火照甘泉。","sortOrder":44},
  {"id":"s_work_nvlt_42_45","chapterId":"ch_work_nvlt_42","text":"周王襃關山篇曰：從軍出隴阪，驅馬度關山，關山恒掩藹，高峰白雲外，遙望秦川水，千里長如帶，好勇自秦中，意氣多豪雄，少年便習戰，十四已從戎，遼水深難渡，榆關斷未通。","sortOrder":45},
  {"id":"s_work_nvlt_42_46","chapterId":"ch_work_nvlt_42","text":"晉陆機太山吟曰：太山一何高，迢迢造天庭，峻極周已遠，曾雲鬱冥冥，梁甫亦有馆，蒿里亦有亭，幽涂延萬鬼，神房集百靈，長吟太山侧，慷慨激楚聲。","sortOrder":46},
  {"id":"s_work_nvlt_42_47","chapterId":"ch_work_nvlt_42","text":"宋謝靈運吳會行曰：六引缓清唱，三調佇繁音，列筵皆寂寂，鹹共聆會吟，會吟自有初，請從文命敷，敷績壶冀始，刊木至江汜，句踐善废興，越王識行止，范蠡出江湖，梅福入城市。","sortOrder":47},
  {"id":"s_work_nvlt_42_48","chapterId":"ch_work_nvlt_42","text":"晉傅玄艳歌行曰：娥眉分翠羽，明月發清陽，丹唇翳皓齒，秀色若珪璋，容華既以艳，志節擬秋霜。","sortOrder":48},
  {"id":"s_work_nvlt_42_49","chapterId":"ch_work_nvlt_42","text":"梁簡文帝艳歌行曰：雲楣桂成戶，飛棟杏為梁，斜窗通藥氣，細隙引尘光，裁衣魏後尺，汲水淮南床，青驪暮已及，豫使羅裙香。","sortOrder":49},
  {"id":"s_work_nvlt_42_50","chapterId":"ch_work_nvlt_42","text":"晉陆機前缓聲歌行曰：遊仙聚靈族，高宴層城阿，長風萬里急，慶雲鬱珪瓘，北徵瑤台女，南要湘川娥，肅肅宵駕動，翩翩翠蓋羅，大客揮高絃，洪涯發清歌，獻酬既已終，輕舉乘紫霞。","sortOrder":50},
  {"id":"s_work_nvlt_42_51","chapterId":"ch_work_nvlt_42","text":"宋謝靈運缓歌行曰：飛客結靈友，凌空萃丹丘，習習和風起，采采彤雲浮，娥皇發湘浦，宵明出河洲，宛宛連螭辔，裔裔振龍旒。","sortOrder":51},
  {"id":"s_work_nvlt_42_52","chapterId":"ch_work_nvlt_42","text":"晉陆機棹歌行曰：遲遲暮春日，天氣柔且嘉，元吉隆初已，濯秽遊黃河，龍舟浮鹢首，羽旗垂藻葩，乘風宣飛景，逍遙戲中波，名謳激清唱，榜人縱棹歌，投纶沉洪川，飛繳入紫霞。","sortOrder":52},
  {"id":"s_work_nvlt_42_53","chapterId":"ch_work_nvlt_42","text":"梁簡文帝棹歌行曰：妾家住湘川，菱歌本自便，風生解榜浪，水深能捉船。葉亂由牵荇，絲飄為折莲，溅妆疑薄汗，霑衣似故{湔灬}，浣紗流暫濁，汰錦色還鮮，參同趙飛燕，借問李延年，從來入絃管，誰在棹歌前。","sortOrder":53},
  {"id":"s_work_nvlt_42_54","chapterId":"ch_work_nvlt_42","text":"宋鮑昭放歌行曰：蓼虫避葵堇，習苦良可哀，小人自齷齪，安知曠士懷，雞鳴洛城里，禁門平旦开，冠蓋縱橫至，車騎四方來，夷世不可逢，賢君信愛才，一言分珪爵，片善辭蒿萊，豈伊白璧賜，將起黃金台，今君有何疾，臨路獨遲回。","sortOrder":54},
  {"id":"s_work_nvlt_42_55","chapterId":"ch_work_nvlt_42","text":"梁何遜輕薄篇曰：長安美年少，重身輕萬亿，柘彈隨珠丸，白馬黃金飾，相期百戲傍，去來三市侧，象床沓繡被，玉盤傳綺食，倡女掩扇歌，小婦开帘織，相看獨隱笑，見人還斂色。","sortOrder":55},
  {"id":"s_work_nvlt_42_56","chapterId":"ch_work_nvlt_42","text":"梁張率遠期篇，遠期終不歸，節華坐將变，誰將久離別，他乡且異縣，浮雲蔽重山，相望不可見。","sortOrder":56},
  {"id":"s_work_nvlt_42_57","chapterId":"ch_work_nvlt_42","text":"梁庾成師遠期篇曰：憶別春花飛，已見秋葉稀，淚粉羞明鏡，愁帶减宽衣，得書言未及，夢見道應歸，坐使紅顏歇，獨掩青樓扉。","sortOrder":57},
  {"id":"s_work_nvlt_42_58","chapterId":"ch_work_nvlt_42","text":"梁簡文帝蜀道難曲曰：巫山七百里，巴水三回曲，笛聲下复高，猿啼斷還續。","sortOrder":58},
  {"id":"s_work_nvlt_42_59","chapterId":"ch_work_nvlt_42","text":"梁劉孝威蜀道難篇曰：玉壘高無極，銅梁不可攀，双流迸巇道，九坂涩陽關，邓侯束馬去，王生斂辔還，嵎山金碧有光辉，遷亭車馬正輕肥，弥思王襃擁節去，复憶相如乘傳歸，君平子雲寂不嗣，江漢英靈已信稀。","sortOrder":59},
  {"id":"s_work_nvlt_42_60","chapterId":"ch_work_nvlt_42","text":"又行行遊獵篇曰：之罘講射所，上林娱獵場，傾飛具罾繳，材官命蹶張，高罝掩月兔，劲矢射天狼，蹶地不遑逸，排虛豈及翔。","sortOrder":60},
  {"id":"s_work_nvlt_42_61","chapterId":"ch_work_nvlt_42","text":"又思歸篇曰：胡地凭良馬，懷驕負漢恩，甘泉烽火入，回中宮室燔，錦車勞遠駕，繡衣疲屢奔，櫪下嚴双駿，腰邊垂兩鞬，乘嶂無期限，歸思安可言。","sortOrder":61},
  {"id":"s_work_nvlt_42_62","chapterId":"ch_work_nvlt_42","text":"又公莫渡河篇曰：請公莫渡河，河廣風威厲，牆偃落金乌，舟傾没犀枻，劍飛猶共水，魂沉理俱逝，君為川後臣，妾作江妃娣。","sortOrder":62},
  {"id":"s_work_nvlt_42_63","chapterId":"ch_work_nvlt_42","text":"梁簡文帝雁門太守歌曰：輕霜中夜下，黃葉晚辭枝，寒苦春難覺，邊城秋易知，風急鈴旗斷，涂長鎧馬疲，少解孫吳法，家本幽併兒，非關買雁肉，徒勞皇甫規。","sortOrder":63},
  {"id":"s_work_nvlt_42_64","chapterId":"ch_work_nvlt_42","text":"又曰：三月楊花合，四月麥秋初，幽州寒食罢，鄭國采桑疏，便聞雁門戍，結束事戎車，寄語金閨妾，勿怨寒床虛。","sortOrder":64},
  {"id":"s_work_nvlt_42_65","chapterId":"ch_work_nvlt_42","text":"齊謝朓鼓吹曲十首，元會曲曰：二儀啟昌歷，三朝應慶期，分階赩組練，充庭羅翠旗，觴流白日下，吹謐景雲滋，天儀穆藻殿，萬宇慶皇基。","sortOrder":65},
  {"id":"s_work_nvlt_42_66","chapterId":"ch_work_nvlt_42","text":"鈞天曲曰：高宴皓天台，置酒迎風觀，笙镛禮百神，鍾石動雲漢，瑤台寶瑟驚，綺席舞衣散，已慶明庭樂，誰想南風彈，入朝曲曰：江南佳麗地，金陵帝王州，飛甍夹馳道，垂楊荫御溝，凝笳翼高蓋，叠鼓送行辀，獻納雲台表，功名良可收。","sortOrder":66},
  {"id":"s_work_nvlt_42_67","chapterId":"ch_work_nvlt_42","text":"從戎曲曰：選旅辭轘轅，弭節趨河源，日起霜戈照，風回連旗翻，寥唳清笳轉，萧條邊馬煩，自勉輟耕原，征役去何言。","sortOrder":67},
  {"id":"s_work_nvlt_42_68","chapterId":"ch_work_nvlt_42","text":"送遠曲曰：北梁辭歡宴，南浦送佳人，方衢控龍馬，平路騁朱輪，琼筵妙舞絕，桂席羽觴陳，一為清吹激，潺湲傷別神。","sortOrder":68},
  {"id":"s_work_nvlt_42_69","chapterId":"ch_work_nvlt_42","text":"登山曲曰：天明开秀草，澜光媚碧隄，風荡翻湋亂，雲行芳树低，暮春春服美，遊駕躡石梯。","sortOrder":69},
  {"id":"s_work_nvlt_42_70","chapterId":"ch_work_nvlt_42","text":"汎水曲曰：玉霜霑翠草，金風鳴素枝，罢遊平樂菀，汎鹢崑明池，羽旗散容裔，箫鼓吹參差，百年如流水，寸心寧共知。","sortOrder":70},
  {"id":"s_work_nvlt_42_71","chapterId":"ch_work_nvlt_42","text":"梁沈約鼓吹曲十二首，漢第一曲朱辂，今第一曲木紀謝，齊［隋書音樂志齊下有謝字，此脱。］梁升也，木紀謝，炎運昌，民去癸，鼎歸梁，轥五帝，軼三王，橫四海，被八荒。","sortOrder":71},
  {"id":"s_work_nvlt_42_72","chapterId":"ch_work_nvlt_42","text":"漢第二曲思悲翁，今第二曲賢首山，言聖主大破匈奴於刀［隋志作司。］部，肇王跡也，賢首山，险而峻，乘阻凭，臨胡陣，騁奇謀，奋卒徒，斷白馬，塞飛孤，［樂府詩集二十作狐。］","sortOrder":72},
  {"id":"s_work_nvlt_42_73","chapterId":"ch_work_nvlt_42","text":"漢第三曲艾如張，今第三曲桐柏山，言聖主收［隋志作牧。］司，王業弥彰也。桐柏山，淮之首，肇基帝跡，遂光區有，震邊關，殪獯丑，農既歡，民惟阜。","sortOrder":73},
  {"id":"s_work_nvlt_42_74","chapterId":"ch_work_nvlt_42","text":"漢第四曲上之回，今第四曲道亡，言東民［隋志作昏。］丧道，義師起樊邓也，道亡數極歸永元，悠悠兆庶盡含冤，矯龍翰，自樊漢，率茲八百驅十亂，登我聖明由多難。","sortOrder":74},
  {"id":"s_work_nvlt_42_75","chapterId":"ch_work_nvlt_42","text":"漢第五曲翁離，今第五曲抗［隋志作忱。］威，言破加湖，元勋建也，抗威授律命蒼光，［疑當作兕。］言薄加湖灌秋水，資此威烈齊文軌。","sortOrder":75},
  {"id":"s_work_nvlt_42_76","chapterId":"ch_work_nvlt_42","text":"漢第六曲戰城南，今第六曲漢東流，言義師剋魯山城也，漢東流，江之汭，逆徒蜂聚，旌旗紛仰蔽，震威靈，乘高騁銳，至仁解網，窮鳥入懷，因此龍躍，言登泰階。","sortOrder":76},
  {"id":"s_work_nvlt_42_77","chapterId":"ch_work_nvlt_42","text":"漢第七曲巫山高，今第七曲鶴樓峻，言平郢城，兵威無敵也，鶴樓峻，連翠微，薄言震，曜靈威，凶眾稽顙，天不能违。","sortOrder":77},
  {"id":"s_work_nvlt_42_78","chapterId":"ch_work_nvlt_42","text":"漢第八曲上陵，今第八曲昏主，言東昏致亂，聖主起義，平九江姑熟，大破朱崖，伐罪弔民也，昏主恣淫慝，皆曰自言盛，上仁矜亿兆，誓師為請命，既齊丹浦戰。又符甲子辰，悠悠萬姓民，於此睹陽春。","sortOrder":78},
  {"id":"s_work_nvlt_42_79","chapterId":"ch_work_nvlt_42","text":"漢第九曲將進酒，今第九曲石首扃，言義師先平京邑四城，仍废昏主，定大事也，石首扃，北墉墐，新堞嚴，東壘峻，夫［樂府詩集作矢。］未飛，鼓方振，競衔璧，併舆榇，翦廉惡，靡餘胤。","sortOrder":79},
  {"id":"s_work_nvlt_42_80","chapterId":"ch_work_nvlt_42","text":"漢第十曲有所思，今第十曲期運集，言聖主膺箓受圖，德盛化遠也，期運集，惟皇膺寶符，龍躍清漢渚，鳳起方城隅，謳歌共適夏，獄訟兩违朱，二儀啟佳祚，千載猶旦暮，無［樂府詩集作舞。］蹈流帝功，金石昭王度。","sortOrder":80},
  {"id":"s_work_nvlt_42_81","chapterId":"ch_work_nvlt_42","text":"漢第十一曲芳树，今第十一曲於穆，言大梁闡運，君臣和樂，休祚方遠也，於穆君臣，君臣和以肅，關王道，定天保，樂均靈囿，宴同在鎬，前庭懸鼓鍾，左右列笙镛，纓佩俯仰有則，備禮容。","sortOrder":81},
  {"id":"s_work_nvlt_42_82","chapterId":"ch_work_nvlt_42","text":"漢第十二曲上雅，今第十二曲大梁，言梁德廣運，仁化溥洽也，惟大梁开運，受箓膺圖，天冠八極，帶被五都。","sortOrder":82},
  {"id":"s_work_nvlt_42_83","chapterId":"ch_work_nvlt_42","text":"齊王融巫山高曰：仿象巫山高，薄暮陽台曲，煙華乍卷舒，行芳時斷續，無忘坐相望，秋風下庭绿。","sortOrder":83},
  {"id":"s_work_nvlt_42_84","chapterId":"ch_work_nvlt_42","text":"梁元帝巫山高曰：巫山高不窮，回出荆門中，滩聲下溅石，猿鳥上逐風，树雜山如畫，林暗涧疑空，無因謝神女，一為出房籠。","sortOrder":84},
  {"id":"s_work_nvlt_42_85","chapterId":"ch_work_nvlt_42","text":"梁范雲巫山高曰：巫山高不極，白日隱光暉，藹藹朝雲去，冥冥暮雨歸，巖懸獸無跡，林暗鳥疑飛，枕席竟誰荐，相望徒依依。","sortOrder":85},
  {"id":"s_work_nvlt_42_86","chapterId":"ch_work_nvlt_42","text":"梁沈約芳树曰：發萼九華隈，开跗露寒侧，氤氲非一香，參差多異色，夙昔寒飆舉，摧殘不可識，霜雪交橫至，對之長叹息。","sortOrder":86},
  {"id":"s_work_nvlt_42_87","chapterId":"ch_work_nvlt_42","text":"梁丘遲芳树曰：芳葉已漠漠，嘉實复離離，發景傍雲屋，凝暉覆華池，輕蜂掇浮穎，弱鳥隱深枝，一朝容色茂，千春長不移。","sortOrder":87},
  {"id":"s_work_nvlt_42_88","chapterId":"ch_work_nvlt_42","text":"魏文帝臨高台行曰：臨台行高高以軒，下有水清且寒，中有黃鵠往且翻，行為臣當盡忠，原令皇帝陛下三千歲，宜居此宮，鵠欲南遊，雌不能隨，我欲躬衔汝，口噤不能开，我欲負之，毛衣摧頹，五里一顧，六里徘徊。","sortOrder":88},
  {"id":"s_work_nvlt_42_89","chapterId":"ch_work_nvlt_42","text":"齊謝朓臨高台行曰：千里常思歸，登台臨綺翼，才見孤鳥還，未辨連山極，四面動清風，朝夜起寒色，誰知倦遊者，嗟此故乡憶。","sortOrder":89},
  {"id":"s_work_nvlt_42_90","chapterId":"ch_work_nvlt_42","text":"梁沈約臨高台行曰：高台不望遠，望遠使人愁，連山無斷續，河水复悠悠，所思愛何在，洛陽南陌頭，可望不可至，何用解人忧。","sortOrder":90},
  {"id":"s_work_nvlt_42_91","chapterId":"ch_work_nvlt_42","text":"梁王僧孺登高台曰：试出金華殿，聊登銅雀台，九路平如砥，千門洞已开，軒車映日過，箫管逐風來，若非邯鄲美，便是洛陽才。","sortOrder":91},
  {"id":"s_work_nvlt_42_92","chapterId":"ch_work_nvlt_42","text":"梁范雲當對酒曰：對酒心自足，故人來共持，方悅羅襟解，誰念發成絲，迨餘聽歌日，及我傾樽時。","sortOrder":92},
  {"id":"s_work_nvlt_42_93","chapterId":"ch_work_nvlt_42","text":"梁張率當對酒曰：對酒誠可樂，此酒复能醇，如華良可貴，似乳更非珍，誰能共遲暮，對酒惜芳辰，君歌尚未罢，却坐避梁尘。","sortOrder":93},
  {"id":"s_work_nvlt_42_94","chapterId":"ch_work_nvlt_42","text":"梁柳惲獨不見曰：芳草生未積，春花落如霰，出從張公子，還過趙飛燕，奉帚長信宮，誰知獨不見。","sortOrder":94},
  {"id":"s_work_nvlt_42_95","chapterId":"ch_work_nvlt_42","text":"梁元帝關山月曰：朝望清波道，夜上白登台，月中含桂树，流影自徘徊，寒沙逐風起，春花犯雪开，夜長無與晤，衣单誰為裁。","sortOrder":95},
  {"id":"s_work_nvlt_42_96","chapterId":"ch_work_nvlt_42","text":"又隴頭水歌曰：衔悲別隴頭，關路漫悠悠，故乡迷遠近，征人分去留，沙飛晓成幕，海氣旦如樓，欲識秦川處，隴水向東流。","sortOrder":96},
  {"id":"s_work_nvlt_42_97","chapterId":"ch_work_nvlt_42","text":"梁劉孝威橫吹曲隴頭流水詩曰：從軍戍隴頭，隴水帶沙流，時觀胡騎飲，常為漢國羞，衅妻成兩劍，殺子祠双鉤，頓取樓蘭頸，就解郅支裘，勿令如李廣，功遂不封侯。","sortOrder":97},
  {"id":"s_work_nvlt_42_98","chapterId":"ch_work_nvlt_42","text":"梁簡文帝洛陽道詩曰：洛陽佳麗所，大道滿春光，遊童時挟彈，蠶妾始提筐，金鞍照龍馬，羅袖拂春桑，王車爭晓入，潘［原訛滿，據冯校本改。］果溢高箱。","sortOrder":98},
  {"id":"s_work_nvlt_42_99","chapterId":"ch_work_nvlt_42","text":"梁元帝洛陽道詩曰：洛陽开大道，城北達城西，青槐隨幔拂，绿柳逐風低，玉珂鳴戰馬，金爪斗場雞，桑萎日行暮，多逢秦氏妻。","sortOrder":99},
  {"id":"s_work_nvlt_42_100","chapterId":"ch_work_nvlt_42","text":"梁元帝長安路曰：前登灞陵岸，還瞻渭水流，城形類南斗，桥势似牵牛，飛軒與良驷，寶劍雜輕裘，經過狹邪里，日暮且淹留。","sortOrder":100},
  {"id":"s_work_nvlt_42_101","chapterId":"ch_work_nvlt_42","text":"梁庾肩吾長安路詩曰：桂宮延複道，黃山开廣路，遠聽平陵鍾，遙識新丰树，日落唱歌還，尘飛車馬度。","sortOrder":101},
  {"id":"s_work_nvlt_42_102","chapterId":"ch_work_nvlt_42","text":"宋鮑昭代淮南王曰：淮南王，好長生，服藥煉氣讀仙經，琉璃藥碗牙作盤，金鼎玉匕合神丹，合神丹，賜紫房，紫房采女弄明璫，朱城九围外，［玉台新詠九作朱城九門門九开，此有脱文。］原逐明月入君懷，入君懷，結君珮，怨君恨君恃君愛。","sortOrder":102},
  {"id":"s_work_nvlt_42_103","chapterId":"ch_work_nvlt_42","text":"宋吳邁遠陽春曲詩曰：绿树搖雲光，春城起風色，佳人愛華景，流靡園塘侧，宋玉歌陽春，巴人長叹息，生重愛惠輕，私自怜何極。","sortOrder":103},
  {"id":"s_work_nvlt_42_104","chapterId":"ch_work_nvlt_42","text":"又長離別詩曰：生離不可聞，况复長相思，如何與君別，當我盛年時，蕙華每搖荡，妾心空自持。","sortOrder":104},
  {"id":"s_work_nvlt_42_105","chapterId":"ch_work_nvlt_42","text":"又長相思詩曰：晨有遠道客，依依造門端，人馬風尘色，知從關塞還，煩君尺錦書，寸心從此殫，道妾長憔悴，無复歌笑顏，欄隱千霜树，庭枯十年蘭，經春不舉袖，秋落寧复看。","sortOrder":105},
  {"id":"s_work_nvlt_42_106","chapterId":"ch_work_nvlt_42","text":"梁張率長相思詩曰：長相思，久離別，美人之遠如雨絕，獨延佇，心中結，望雲去去遠，望鳥飛飛滅，長相思，久別離，所思所在若天垂，鬱鬱相望不得知，玉階月夕映，羅帷風夜吹，長思不能寢，坐望天河移。","sortOrder":106},
  {"id":"s_work_nvlt_42_107","chapterId":"ch_work_nvlt_42","text":"梁簡文帝乌栖曲曰：芙蓉作船絲作纟乍，北斗橫天月將落，采桑渡頭礙黃河，郎今欲度畏風波。","sortOrder":107},
  {"id":"s_work_nvlt_42_108","chapterId":"ch_work_nvlt_42","text":"又曰：浮雲似帳月如鉤，那能夜夜南陌遊，宜城投酒今行熟，停鞍系馬暫栖宿。","sortOrder":108},
  {"id":"s_work_nvlt_42_109","chapterId":"ch_work_nvlt_42","text":"又曰：青牛丹轂七香車，可怜今夜宿娼家，娼家高树乌欲栖，羅帷翠帳向君低。","sortOrder":109},
  {"id":"s_work_nvlt_42_110","chapterId":"ch_work_nvlt_42","text":"又曰：織成屏風銀屈膝，朱唇玉面燈前出，相看氣息望君怜，誰能含羞不自前。","sortOrder":110},
  {"id":"s_work_nvlt_42_111","chapterId":"ch_work_nvlt_42","text":"梁元帝乌栖曲曰：沙棠作船桂為楫，夜渡江南采莲葉，复值西施新浣紗，共汎江幹瞻月華。","sortOrder":111},
  {"id":"s_work_nvlt_42_112","chapterId":"ch_work_nvlt_42","text":"又曰：月華似璧星如珮，流影澄明玉堂內，邯鄲九投朝始成，金卮銀碗共君傾。","sortOrder":112},
  {"id":"s_work_nvlt_42_113","chapterId":"ch_work_nvlt_42","text":"又曰：交龍成錦斗鳳紋，芙蓉為帶石榴裙，日下城南兩相望，月没參橫掩羅帳。","sortOrder":113},
  {"id":"s_work_nvlt_42_114","chapterId":"ch_work_nvlt_42","text":"又曰：七彩隨珠九華玉，蛱蝶為歌明星曲，蘭房椒閤夜方开，那知步步香風逐。","sortOrder":114},
  {"id":"s_work_nvlt_42_115","chapterId":"ch_work_nvlt_42","text":"梁萧子顯乌栖曲曰：浓黛輕紅點花色，還欲令人不相識，金壶夜永誰能過，莫持奢用比懸河。","sortOrder":115},
  {"id":"s_work_nvlt_42_116","chapterId":"ch_work_nvlt_42","text":"又曰：芳树歸飛聚儔匹，猶有殘光半山日，莫憚褰裳不相求，漢皋遊女習風流。","sortOrder":116},
  {"id":"s_work_nvlt_42_117","chapterId":"ch_work_nvlt_42","text":"梁簡文帝龍笛曲曰：江真弄真態，翔鳳陽春台，同去复同來。","sortOrder":117},
  {"id":"s_work_nvlt_42_118","chapterId":"ch_work_nvlt_42","text":"梁柳惲江南曲曰：汀洲采白蘋，日落江南春，洞庭有歸客，瀟湘逢故人，故人久不返，春華复應晚，不道新知樂，空言行路遠。","sortOrder":118},
  {"id":"s_work_nvlt_42_119","chapterId":"ch_work_nvlt_42","text":"梁吳筠携手曲曰：艳裔陽之春，携手清洛濱，雞鳴上林苑，薄暮小平津，長裾扫白日，廣袖帶芳尘，故友一如此，新知詎憶人。","sortOrder":119},
  {"id":"s_work_nvlt_42_120","chapterId":"ch_work_nvlt_42","text":"梁沈約夜夜曲曰：河漢縱复橫，北斗橫复直，星漢空如此，寧知心所憶，孤燈暧不明，寒機猶更織，零涕向誰道，雞鳴徒叹息。","sortOrder":120},
  {"id":"s_work_nvlt_42_121","chapterId":"ch_work_nvlt_42","text":"梁江洪渌［原作绿，據冯校本改。］水曲曰：潺湲复皎絜，輕鮮尚可悅，橫使有情禽，照影遂孤絕。","sortOrder":121},
  {"id":"s_work_nvlt_42_122","chapterId":"ch_work_nvlt_42","text":"又曰：尘客不忍飾，臨池思客歸，誰知取渌水，無趣浣羅衣。","sortOrder":122},
  {"id":"s_work_nvlt_42_123","chapterId":"ch_work_nvlt_42","text":"又秋風曲曰：光拂連雲台，罢入迎鑾殿，已折池中荷，复馳簷里燕。","sortOrder":123},
  {"id":"s_work_nvlt_42_124","chapterId":"ch_work_nvlt_42","text":"又胡笳曲曰：藏器欲邀時，年來不相讓，紅顏征戍兒，白首邊城將。","sortOrder":124},
  {"id":"s_work_nvlt_42_125","chapterId":"ch_work_nvlt_42","text":"又曰：落日惨無光，臨河獨飲馬，瑟飒夕風高，聯翩雁飛下。","sortOrder":125},
  {"id":"s_work_nvlt_42_126","chapterId":"ch_work_nvlt_42","text":"宋吳邁遠秋風曲曰：寒乡無異服，衣氈代文練，月月望君歸，年年不解線，荆楊早春和，幽冀猶霜霰，地寒妾已知，南心君不見。","sortOrder":126},
  {"id":"s_work_nvlt_42_127","chapterId":"ch_work_nvlt_42","text":"又胡笳曲曰：輕命重意氣，古來豈但今，缓頰獻一說，扬眉受千金，邊風落寒草，鳴笳墜飛禽，越情結楚思，漢耳聽胡音，既懷離俗傷，复悲朝光侵，日當故乡没，遙見浮雲陰。","sortOrder":127},
  {"id":"s_work_nvlt_42_128","chapterId":"ch_work_nvlt_42","text":"梁吳筠秦王卷衣曲曰：鹹陽春草芳，秦帝卷衣裳，玉檢茱萸匣，金泥蘇合香。須臾朝宴罢，持此赠華陽。","sortOrder":128},
  {"id":"s_work_nvlt_42_129","chapterId":"ch_work_nvlt_42","text":"梁劉孝綽賦得乌夜啼詩曰：鵾絃且輟弄，鶴操暫停揮，別有啼乌曲，東西各自飛，倡人怨獨守，荡子猶未歸，忽聞生離唱，中夜泣羅衣，周庾信乌夜啼曲曰：促柱繁絃非子夜，歌聲舞態異前溪，御史府中何處宿，洛陽城頭那得栖，彈琴蜀郡卓家女，織錦秦川窦氏妻，詎不自驚長淚落，到道啼乌恒夜啼。","sortOrder":129},
  {"id":"s_work_nvlt_42_130","chapterId":"ch_work_nvlt_42","text":"又曰：桂树懸知遠，風竿詎肯低，獨來明月夜，孤情猶未栖，虎贲誰見惜，御史詎相携，雖言入絃管，終是曲中啼。","sortOrder":130},
  {"id":"s_work_nvlt_42_131","chapterId":"ch_work_nvlt_42","text":"晉石崇明君辭曰：王明君者，本為王昭君，以觸文帝讳改之，匈奴盛，請婚於漢，元帝以明君配焉，昔公主嫁乌孫，令琵琶馬上作樂，以慰其道路之思，其送明君，亦必爾也，詩曰：我本漢家子，將適单於庭，辭訣未及終，前驅已抗旌，仆御涕流離，轅馬悲且鳴，行行日已遠，遂造匈奴城，延我於穹庐，加我閼氏名，殺身良不易，默默以苟生，原假飛鸿翼，弃［《文選》二十七作乘。］之以遐征，昔為匣中琴，今為粪上英，朝華不足歡，甘與秋草併，傳語後世人，遠嫁難為情。","sortOrder":131},
  {"id":"s_work_nvlt_42_132","chapterId":"ch_work_nvlt_42","text":"梁沈約昭君辭曰：朝發披香殿，夕濟汾陰河，於茲懷九折，自此斂双蛾，霑妆如湛露，繞脸状流波，日見奔沙起，稍覺轉蓬多，唯有三五夜，明月暫經過。","sortOrder":132},
  {"id":"s_work_nvlt_42_133","chapterId":"ch_work_nvlt_42","text":"魏陳王曹植箜篌引曰：置酒高殿上，親友從我遊，中厨辨丰膳，烹羊宰肥牛，秦筝何慷恺，齊瑟和且柔，陽阿奏妙舞，京洛出名謳，樂飲過三爵，缓帶傾庶羞，主稱千金寿，賓奉萬年酬，驚風飄白日，光景馳西流，盛時不再來，百年忽我忧，生存華屋處，零落歸山丘。","sortOrder":133},
  {"id":"s_work_nvlt_42_134","chapterId":"ch_work_nvlt_42","text":"晉石崇思歸引曰：思歸引，歸河陽，假餘翼，鸿鶴高飛翔，經芸阜，濟河梁，望我舊馆心悅康，清渠繳，魚彷徨，雁驚溯波群相將，終日周覽樂無方，登雲閣，列姬薑，拊絲竹，叩宮商，宴華池，酌玉觴。","sortOrder":134},
  {"id":"s_work_nvlt_42_135","chapterId":"ch_work_nvlt_42","text":"梁簡文帝江南曲曰：陽春路，時使佳人度，枝中水上春併歸，長楊扫地桃花飛，清風吹人光照衣，光照衣，景將夕，掷黃金，留上客。","sortOrder":135},
  {"id":"s_work_nvlt_42_136","chapterId":"ch_work_nvlt_42","text":"梁沈約江南行陽春曲曰：楊柳至地燕差池，緘情忍思落容儀，絃傷曲怨心自知，心自知，人不見，動羅裙，拂珠殿。","sortOrder":136},
  {"id":"s_work_nvlt_42_137","chapterId":"ch_work_nvlt_42","text":"朝雲曲曰：陽台氛氲多異色，巫山高高上無極，雲來雨去長不息，長不息，夢來遊，經萬世，度千秋。","sortOrder":137},
  {"id":"s_work_nvlt_42_138","chapterId":"ch_work_nvlt_42","text":"梁簡文帝悲楚妃叹曰：閨閒漏永永，漏長宵寂寂，草螢飛夜戶，絲虫繞秋壁，薄笑未為欣，微叹還成戚，金簪鬢下垂，玉箸衣前滴。","sortOrder":138},
  {"id":"s_work_nvlt_42_139","chapterId":"ch_work_nvlt_42","text":"宋孝武帝夜聽妓詩曰：寒夜起聲管，促席引靈寄，深心屬悲絃，遠情逐流吹，勞衿凭苦辰，誰謂懷忘易。","sortOrder":139},
  {"id":"s_work_nvlt_42_140","chapterId":"ch_work_nvlt_42","text":"梁簡文帝聽夜妓詩曰：合歡蠲忿葉，萱草忘忧條，何如明月夜，流風拂舞腰，朱唇隨吹盡，玉钏逐絃搖，留賓惜殘弄，負態動餘娇。","sortOrder":140},
  {"id":"s_work_nvlt_42_141","chapterId":"ch_work_nvlt_42","text":"梁元帝春夜看妓詩曰：蛾眉漸成光，燕姬戲小堂，胡舞开春閤，鈴盤出步廊，起龍調節奏，却鳳點笙篁，树交臨舞席，荷生夹妓行，竹密無分影，花疏有異香，舉杯聊轉笑，叹茲樂未央。","sortOrder":141},
  {"id":"s_work_nvlt_42_142","chapterId":"ch_work_nvlt_42","text":"梁何遜詠妓詩曰：管隨羅荐合，絲驚雪袖遲，逐唱回纖手，聽曲動蛾眉，凝情顧眄墮，微睇讬含辭，日暮留佳客，相看愛此時。","sortOrder":142},
  {"id":"s_work_nvlt_42_143","chapterId":"ch_work_nvlt_42","text":"周庾信看妓詩曰：绿珠歌扇薄，飛燕舞袖長，琴曲隨流水，箫聲逐鳳皇，細茝纏鍾板，圓花釘鼓床，懸知曲不誤，無事顧周郎。","sortOrder":143},
  {"id":"s_work_nvlt_42_144","chapterId":"ch_work_nvlt_42","text":"陳劉删侯司空第山園詠妓詩曰：石家金穀妓，妆罢出蘭閨，看花爭欲笑，聞瑟似能啼，山邊歌落日，池上舞前溪，持人當桃李，無處不成蹊。","sortOrder":144},
  {"id":"s_work_nvlt_42_145","chapterId":"ch_work_nvlt_42","text":"陳陰铿侯司空第山園詠妓詩曰：佳人遍綺席，妙曲動鵾絃，樓似陽台上，池如洛水邊，鶯啼歌扇後，花落舞衫前，翠柳將斜日，俱照晚妆鮮。","sortOrder":145},
  {"id":"s_work_nvlt_42_146","chapterId":"ch_work_nvlt_42","text":"陳萧琳隔壁聽妓詩曰：徒聞絃管切，不見舞腰回，唯有歌梁共，尘飛一半來。","sortOrder":146},
  {"id":"s_work_nvlt_42_147","chapterId":"ch_work_nvlt_42","text":"隋盧思道夜聞鄰妓詩曰：娼樓對三道，吹台臨九重，笙隨山上鶴，笛奏水中龍，誰能暫眉各，［句有訛。］解珮一相從。","sortOrder":147},
  {"id":"s_work_nvlt_42_148","chapterId":"ch_work_nvlt_42","text":"【論】晉阮籍樂論曰：昔者聖人之作樂也，將以順天地之性，體萬物之生也，故定天地八方之音，以迎陰陽八風之聲，故律呂协則陰陽和，音聲適而萬物類，奏之圓丘，而天神下降，肆之方嶽，而地祇上應，天地合其德，則萬物合其生，刑賞不用而民自安，車服旌旗，宮室飲食，禮之具也，鍾磬鞞鼓琴瑟，樂之器也，禮逾其製則尊卑乖，樂失其序則親疏亂，禮定其眾，樂平其心，禮治其外，樂化其內，故清廟之歌，詠成功之績，賓饗之詩，稱禮讓之則，百姓化其善，異俗服其德也。","sortOrder":148},
  {"id":"s_work_nvlt_42_149","chapterId":"ch_work_nvlt_42","text":"《藝文類聚》　唐·欧陽詢","sortOrder":149},
  {"id":"s_work_nvlt_43_1","chapterId":"ch_work_nvlt_43","text":"卷四十三樂部三","sortOrder":1},
  {"id":"s_work_nvlt_43_2","chapterId":"ch_work_nvlt_43","text":"○舞歌","sortOrder":2},
  {"id":"s_work_nvlt_43_4","chapterId":"ch_work_nvlt_43","text":"《爾雅》曰：婆娑，舞也，［舞者之容也。］","sortOrder":4},
  {"id":"s_work_nvlt_43_5","chapterId":"ch_work_nvlt_43","text":"《尚書》曰：苗民逆命，帝乃誕敷文德，舞幹羽於兩階，七旬有苗格。","sortOrder":5},
  {"id":"s_work_nvlt_43_6","chapterId":"ch_work_nvlt_43","text":"樂緯曰：武王承命興師，渡盟津，前歌後舞。","sortOrder":6},
  {"id":"s_work_nvlt_43_7","chapterId":"ch_work_nvlt_43","text":"《周官》曰：樂師掌教國子六舞，凡舞有帗舞，有羽舞，有旄舞，有幹舞。","sortOrder":7},
  {"id":"s_work_nvlt_43_8","chapterId":"ch_work_nvlt_43","text":"《禮記》曰：治民勞者，舞行缀遠，治民逸者，舞行缀短，故觀其舞，知其德，［民德薄，故舞勞人少。］","sortOrder":8},
  {"id":"s_work_nvlt_43_9","chapterId":"ch_work_nvlt_43","text":"又曰：以禘禮祀周公於太廟，朱幹玉戚，冕而舞大武。","sortOrder":9},
  {"id":"s_work_nvlt_43_10","chapterId":"ch_work_nvlt_43","text":"《毛詩》曰：舍其坐遷，屢舞仙仙，侧弁之俄，屢舞傞傞。","sortOrder":10},
  {"id":"s_work_nvlt_43_11","chapterId":"ch_work_nvlt_43","text":"《左傳》曰：考仲子之宮，將萬焉，公問羽數於眾仲，對曰：天子用八，諸侯用六，大夫四，士二，夫舞，所以節八音而行八風也。","sortOrder":11},
  {"id":"s_work_nvlt_43_12","chapterId":"ch_work_nvlt_43","text":"《楚辭》曰：二八齊容起鄭舞，衽若交竽撫案下。","sortOrder":12},
  {"id":"s_work_nvlt_43_13","chapterId":"ch_work_nvlt_43","text":"又曰：翾飛兮翠曾，［曾，舞也，言舞工巧似翠鳥之舉。］展詩兮會舞。","sortOrder":13},
  {"id":"s_work_nvlt_43_14","chapterId":"ch_work_nvlt_43","text":"《韓子》曰：長袖善舞，多錢善贾。","sortOrder":14},
  {"id":"s_work_nvlt_43_15","chapterId":"ch_work_nvlt_43","text":"《淮南子》曰：今鼓舞者，身若秋藥被風，［藥，白芷也，被風言其弱也。］《漢書》曰：孝武李夫人，本以倡進，兄延年，知音善歌舞，延年侍上起舞，歌曰：北方有佳人，絕世而獨立，一顧傾人城，再顧傾人國，寧不知傾國與［原坏，據冯校本改。］傾城，佳人難再得，平陽公主因言延年女弟，上召見，實妙麗善舞，由是幸，生昌邑哀王。","sortOrder":15},
  {"id":"s_work_nvlt_43_16","chapterId":"ch_work_nvlt_43","text":"又曰：高祖廟奏武德文始五行之舞，武德者，象天下樂己行武以除亂也，文始者，本舜韶舞也，高祖更名曰文始，示不相袭。","sortOrder":16},
  {"id":"s_work_nvlt_43_17","chapterId":"ch_work_nvlt_43","text":"范晔《後漢書》曰：蔡邕坐上章事徙，及歸，將就還路，五原太守王智餞之，酒酣，智起舞，屬邕，邕不為報，智者中常侍王甫之弟，智衔之，密告邕，怨於囚放，謗訕朝廷，邕慮卒不免禍，乃亡命江海，遠跡吳會。","sortOrder":17},
  {"id":"s_work_nvlt_43_18","chapterId":"ch_work_nvlt_43","text":"《呂氏春秋》曰：陶唐氏之始，陰多滯伏，民氣壅閼，故為作舞，以宣导之。","sortOrder":18},
  {"id":"s_work_nvlt_43_19","chapterId":"ch_work_nvlt_43","text":"《家語》曰：子路戎服見孔子，拔劍而舞曰：古之君子，固以劍自衛乎，孔子曰：古之君子，忠以為质，仁以為衛。","sortOrder":19},
  {"id":"s_work_nvlt_43_20","chapterId":"ch_work_nvlt_43","text":"蔡邕《月令章句》曰：樂容曰舞，有俯仰張翕，行缀長短之製。","sortOrder":20},
  {"id":"s_work_nvlt_43_21","chapterId":"ch_work_nvlt_43","text":"三巴記曰：阆中有渝水，賨民銳氣喜舞，高祖樂其猛銳，數觀其舞，使樂人習之，故名巴渝舞。","sortOrder":21},
  {"id":"s_work_nvlt_43_22","chapterId":"ch_work_nvlt_43","text":"魏名臣奏，王朗表曰：凡音樂以舞為主，自黃帝雲門，至周大武，皆大廟舞樂名也，樂所以樂君之德，舞所以象君之功。","sortOrder":22},
  {"id":"s_work_nvlt_43_23","chapterId":"ch_work_nvlt_43","text":"《吳書》曰：陶謙為舒令，郡守張磐，恥為之下，磐舞，屬謙，謙不為起，強之乃舞，舞不轉，磐曰：不當轉耶，曰：轉則勝人。","sortOrder":23},
  {"id":"s_work_nvlt_43_24","chapterId":"ch_work_nvlt_43","text":"又曰：陆遜破曹休，上與群僚大會，酒酣，命遜舞，解所著白鼯子裘賜之。","sortOrder":24},
  {"id":"s_work_nvlt_43_25","chapterId":"ch_work_nvlt_43","text":"【詩】宋南平王白纻舞曲曰：仙仙徐動何盈盈，玉腕俱凝若雲行，佳人舉袖曜青蛾，摻摻擢手映鮮羅，状似明月汎雲河，體如輕風動流波。","sortOrder":25},
  {"id":"s_work_nvlt_43_26","chapterId":"ch_work_nvlt_43","text":"梁簡文帝詠舞詩曰：娇情因曲動，弱步逐風吹，懸釵隨舞落，飛袖低鬟垂。","sortOrder":26},
  {"id":"s_work_nvlt_43_27","chapterId":"ch_work_nvlt_43","text":"又詠舞詩曰：戚里多妖麗，重娉蔑燕餘，逐節工新舞，娇態似凌虛，納［內音。］花承俵概，垂翠逐璫舒，扇开衫影亂，巾度履行疏，徒勞交甫憶，自有专城居。","sortOrder":27},
  {"id":"s_work_nvlt_43_28","chapterId":"ch_work_nvlt_43","text":"又詠舞詩曰：可怜稱二八，逐節似飛鸿，懸勝河陽伎，闇與淮南同，入行看履進，轉面望鬟空，腕動苕華玉，衫隨如意風，上客何須起，啼乌未肯終。","sortOrder":28},
  {"id":"s_work_nvlt_43_29","chapterId":"ch_work_nvlt_43","text":"梁劉遵應令詠舞詩曰：倡女多艳色，入選盡華年，舉腕嫌衫重，回腰覺態妍，情繞陽春吹，影逐相思絃，履度开裙俵，鬢轉匝花钿，所愁餘曲罢，為欲在君前。","sortOrder":29},
  {"id":"s_work_nvlt_43_30","chapterId":"ch_work_nvlt_43","text":"梁王訓應令詠舞詩曰：新妆本絕世，妙舞亦如仙，傾腰逐韻管，斂色聽張絃，袖輕風易入，釵重步難前，笑態千金動，衣香十里傳，將持比飛燕，定當誰可怜。","sortOrder":30},
  {"id":"s_work_nvlt_43_31","chapterId":"ch_work_nvlt_43","text":"梁楊曒詠舞詩曰：紅顏自燕趙，妙妓邁陽阿，就行齊逐唱，赴節闇相和，折腰送餘曲，斂袖待新歌，嚬容生翠羽，曼睇出橫波，雖稱趙飛燕，比此詎成多。","sortOrder":31},
  {"id":"s_work_nvlt_43_32","chapterId":"ch_work_nvlt_43","text":"梁庾肩吾詠舞詩曰：飛鳥袖始拂，啼乌曲未終，聊因斷續唱，试讬往還風。","sortOrder":32},
  {"id":"s_work_nvlt_43_33","chapterId":"ch_work_nvlt_43","text":"梁劉孝儀和舞詩曰：回履裾香散，飄衫钏响傳，低釵依促管，曼睇入繁絃。","sortOrder":33},
  {"id":"s_work_nvlt_43_34","chapterId":"ch_work_nvlt_43","text":"又和詩曰：轉袖隨歌發，頓履赴絃餘，度行過接手，回身乍斂裾。","sortOrder":34},
  {"id":"s_work_nvlt_43_35","chapterId":"ch_work_nvlt_43","text":"又舞就行詩曰：依歌移弱步，傍燭艳新妆，徐來翻應節，亂去反成行。","sortOrder":35},
  {"id":"s_work_nvlt_43_36","chapterId":"ch_work_nvlt_43","text":"周庾信詠舞詩曰：洞房花燭明，燕餘双舞輕，頓履疏隨節，低鬟逐上聲，步轉行初進，衫飄曲未成，鸞回鏡欲滿，鶴顧市應傾，已曾天上學，詎是世中生。","sortOrder":36},
  {"id":"s_work_nvlt_43_37","chapterId":"ch_work_nvlt_43","text":"陳徐陵詠舞詩曰：十五屬平陽，因來入建章，主家能教舞，城中巧旦［原作且，據冯校本改。］妆，低鬟向綺席，舉袖拂花黃，燭送空回影，衫傳箧里香，當由好留客，故作舞衣長。","sortOrder":37},
  {"id":"s_work_nvlt_43_38","chapterId":"ch_work_nvlt_43","text":"【賦】後漢傅毅舞賦曰：楚襄王既遊雲夢，將置酒宴飲，謂宋玉曰：寡人欲觴群臣，何以娱之，玉曰：臣聞激楚結風陽阿之舞，材人之窮觀，天下之至妙，噫可進乎，王曰：试為寡人賦之，玉曰：唯唯，鄭女出進，二八徐侍，姣服極麗，姁媮致態，貌嫽妙以妖冶，紅顏燁其楊華，眉〈女連〉娟以增繞，目流睇而橫波，珠翠的皪而照曜，華袿飛髾而雜纖羅，顧形影，自整裝，順微風，揮若芳，動朱唇，紆清陽，亢音高歌，為樂之方，其始興也，若俯若仰，若來若往，雍容惆怅，不可為象，羅衣從風，長袖交橫，骆驿飛散，飒遝合併，綽約閒靡，機迅體輕，於是合場遞進，安步而俟，埒材角妙，夸容乃理，軼態橫出，瑰姿譎起，回身還入，迫於急節，紆形赴遠，漼以摧折，纖縠俄飛，繽焱若絕，體如遊龍，袖如素蜺，遷延微笑，退复次列，觀者稱麗，莫不怡悅。","sortOrder":38},
  {"id":"s_work_nvlt_43_39","chapterId":"ch_work_nvlt_43","text":"後漢張衡舞賦曰：昔客有觀舞於淮南者，美而賦之曰：音樂陳兮旨酒施，击靈鼓兮吹參差，叛淫衍兮漫陆離，於是飲者皆醉，日亦既昃，美人興而將舞，乃脩容而改袭，服羅縠之雜错，申綢缪以自飾，拊者啾其齊列，盤鼓煥以骈羅，抗脩袖以翳面兮，展清聲而長歌，歌曰：驚雄逝兮孤雌翔，臨歸風兮思故乡，搦纖腰而互折，嬛傾倚兮低昂，增芙蓉之紅花兮，光的皪以發扬，騰〈目雩〉目以顧眄，盼烂烂以流光，連翩骆驿，乍續乍絕，裾似飛燕，袖如回雪，於是粉黛施兮玉质粲，珠簪挺兮緇發亂，然後整笄攬發，被纖垂萦，同服骈奏，合體齊聲，進退無差，若影追形。","sortOrder":39},
  {"id":"s_work_nvlt_43_40","chapterId":"ch_work_nvlt_43","text":"梁簡文帝舞賦曰：酌蒲桃，坐柘觀，命妙舞，徵清彈，丱發初笄，參差俱集，信身輕而釵重，亦腰羸而帶急，响玉砌而遲前，度金扉而斜入，似斷霞之照彩，若飛鸞之相及，既相看而綿视，亦含姿而俱立，於是徐鳴娇節，薄動輕金，奏巴渝之麗曲，唱碣石之清音，扇才移而動步，鞞輕宣而逐吟，爾乃優遊容豫，顧眄徘徊，強紆顏而失笑，乍雜怨而成猜，或低昂而失侣，乃歸飛而相附，或前異而始同，乍初離而後赴，不遲不疾，若輕若重，盻鼓微吟，回巾自擁，發亂難持，簪低易捧，牵恃其思，懷娇知寵。","sortOrder":40},
  {"id":"s_work_nvlt_43_42","chapterId":"ch_work_nvlt_43","text":"《說文》曰：詠，歌，曰［曰上疑脱又字。］獨歌謂之謠，謳，齊歌也。","sortOrder":42},
  {"id":"s_work_nvlt_43_43","chapterId":"ch_work_nvlt_43","text":"蔡邕《月令章句》曰：樂聲曰歌。","sortOrder":43},
  {"id":"s_work_nvlt_43_44","chapterId":"ch_work_nvlt_43","text":"《山海經》曰：帝俊八子，是始為歌，［帝俊，帝舜也。］","sortOrder":44},
  {"id":"s_work_nvlt_43_45","chapterId":"ch_work_nvlt_43","text":"又曰：夏後氏开，上三嫔於天，得九辯與九［《太平御覽》五百七十二，九下有歌字。］以下。","sortOrder":45},
  {"id":"s_work_nvlt_43_46","chapterId":"ch_work_nvlt_43","text":"《毛詩序》曰：情動於中而形於言，言之不足，故嗟叹之，嗟叹之不足，故詠歌之。","sortOrder":46},
  {"id":"s_work_nvlt_43_47","chapterId":"ch_work_nvlt_43","text":"《穆天子傳》曰：天子東遊於黃泽，宿於曲洛，洛水之曲也，使宮樂謠［宮樂，典樂者。］曰：黃之紘，其馬歕沙，［音普問反。］黃之泽，其馬歕玉。","sortOrder":47},
  {"id":"s_work_nvlt_43_48","chapterId":"ch_work_nvlt_43","text":"《列子》曰：薛談學謳於秦青，未窮青之伎，自謂盡之，遂辭歸，秦青弗止，餞於交衢拊節悲歌，聲震林木，响遏行雲，薛談乃謝求反，終身不敢言歸，秦青顧其友曰：昔韓娥東之齊，匮糧，過雍門，鬻歌假食，既去，餘响繞梁，三日不絕。","sortOrder":48},
  {"id":"s_work_nvlt_43_49","chapterId":"ch_work_nvlt_43","text":"《孟子》曰：昔王豹處於淇，而河西善謳，綿駒處於高唐，而齊右善歌。","sortOrder":49},
  {"id":"s_work_nvlt_43_50","chapterId":"ch_work_nvlt_43","text":"襄陽耆舊傳曰：宋玉識音而善文，襄王好樂而愛賦，既美其才，而憎其似屈原也，乃謂之曰：子盍從楚之俗，使楚人貴子之德乎，對曰：昔楚有善歌者，王其聞與，始而曰下里巴人，國中唱而和之者數萬人，中而曰陽阿采菱，國中唱而和之者數百人，既而曰陽菱［《初學記》十五作阿。］白露，朝日魚麗，含商吐角，絕節赴曲，國中唱而和之者，不過數人，蓋其曲弥高，其和弥寡。","sortOrder":50},
  {"id":"s_work_nvlt_43_51","chapterId":"ch_work_nvlt_43","text":"《呂氏春秋》曰：昔葛天氏之樂，三人操牛尾，捉足以歌八阕。","sortOrder":51},
  {"id":"s_work_nvlt_43_52","chapterId":"ch_work_nvlt_43","text":"又曰：帝喾氏命鹹黑作為唐歌，尧命质效山穀之音以作歌，湯命伊尹作為大濩，歌晨露。","sortOrder":52},
  {"id":"s_work_nvlt_43_53","chapterId":"ch_work_nvlt_43","text":"《淮南子》曰：易道良馬，使人欲馳，飲酒而樂，使人欲歌。","sortOrder":53},
  {"id":"s_work_nvlt_43_54","chapterId":"ch_work_nvlt_43","text":"又曰：［瓠梁之歌，可隨也。］其所歌者不可為，瓠梁，古善歌之人也。","sortOrder":54},
  {"id":"s_work_nvlt_43_55","chapterId":"ch_work_nvlt_43","text":"劉向別錄曰：有麗人歌賦，漢興以來，善雅歌者，魯人虞公，發聲清哀，蓋動梁尘。","sortOrder":55},
  {"id":"s_work_nvlt_43_56","chapterId":"ch_work_nvlt_43","text":"《漢書》曰：孝武南巡狩，至於盛唐，自潯陽浮江，親射蛟江中，獲之，舳舻千里，薄摐陽而出，作盛唐摐陽之歌。","sortOrder":56},
  {"id":"s_work_nvlt_43_57","chapterId":"ch_work_nvlt_43","text":"又曰：武帝思念李夫人不已，方士齊人少翁，言能致其神，乃夜設燈燭帏幄，而令帝居他帳，遙見望好女，如夫人之貌，而不得就视，愈益悲感，為作詩，令樂府諸音家絃歌之，曰：是耶非耶，立而望之，偏，娜娜何冉冉其來遲。","sortOrder":57},
  {"id":"s_work_nvlt_43_58","chapterId":"ch_work_nvlt_43","text":"又曰：張釋之為中郎將，從行至灞陵，是時慎夫人從，上指视慎夫人新丰道曰：此是邯鄲道也，使慎夫人鼓瑟，上倚瑟而歌。","sortOrder":58},
  {"id":"s_work_nvlt_43_59","chapterId":"ch_work_nvlt_43","text":"《漢武內傳》曰：西王母命侍女安法婴，歌玄雲曲，上元夫人自彈雲林之瑟，乃歌步玄之曲曰：渌景清飆起，雲蓋映朱葩，蘭房辟琳闕，碧室啟琼沙。","sortOrder":59},
  {"id":"s_work_nvlt_43_60","chapterId":"ch_work_nvlt_43","text":"鄭緝之東陽記曰：歌山在吳寧縣，故老相傳雲，昔有人乘船從下過，見一女子穀汲，乃登此山，負水行歌，姿態甚妍，而莫知所由，故名歌山。","sortOrder":60},
  {"id":"s_work_nvlt_43_61","chapterId":"ch_work_nvlt_43","text":"虞舜作歌曰：元首明哉，股肱良哉，庶事康哉。","sortOrder":61},
  {"id":"s_work_nvlt_43_62","chapterId":"ch_work_nvlt_43","text":"又歌曰：元首丛脞哉，股肱惰哉，萬事墮哉。","sortOrder":62},
  {"id":"s_work_nvlt_43_63","chapterId":"ch_work_nvlt_43","text":"又歌曰：南風之薰兮，可以解吾民之慍兮，南風之時兮，可阜吾民之财兮。","sortOrder":63},
  {"id":"s_work_nvlt_43_64","chapterId":"ch_work_nvlt_43","text":"又卿雲歌曰：卿雲烂兮，禮缦缦兮，日月光華，旦或旦兮，八伯鹹進，稽首曰：明明上天，烂然星辰，日月［《太平御覽》五百七十一月下有光字。］華，弘兮［御覽作予。］一人，帝乃再歌曰：日月有常，星辰有行，四時從經，萬姓允誠，於予論樂，配天之靈。","sortOrder":64},
  {"id":"s_work_nvlt_43_65","chapterId":"ch_work_nvlt_43","text":"周穆天子觴西王母於瑤池之上，西王母為天子謠曰：白雲在天，山陵自出，道里悠遠，山川間之，將子無死，尚能复來，天子答曰：予歸東土，和治諸夏，萬民平均，吾顧見汝，比及三年，將复而野。","sortOrder":65},
  {"id":"s_work_nvlt_43_66","chapterId":"ch_work_nvlt_43","text":"齊甯戚扣牛角歌曰：沧浪之水白石粲，中有鯉魚長尺半，轂布单衣裁至骭，清朝飯牛至夜半，黃犢上坂且休息，吾將舍汝相齊國。","sortOrder":66},
  {"id":"s_work_nvlt_43_67","chapterId":"ch_work_nvlt_43","text":"又燕荆軻萧萧歌曰：燕太子丹使荆軻刺秦王，丹祖送於易水之上，高漸離击筑，荆軻歌，宋意和之曰：風萧萧兮易水寒，壮士一去不复還。","sortOrder":67},
  {"id":"s_work_nvlt_43_68","chapterId":"ch_work_nvlt_43","text":"漢高祖大風歌曰：高祖還過沛，留置酒沛宮，悉召故人父老子弟佐相酒，發沛中兒，得百二十人，教之歌，酒酣，上击筑自歌曰：大風起兮雲飛扬，威加海內兮歸故乡，安得猛士兮守四方。","sortOrder":68},
  {"id":"s_work_nvlt_43_69","chapterId":"ch_work_nvlt_43","text":"漢武臨河决，悼功之不成，乃歌曰：瓠子决兮將奈何，浩浩洋洋，慮殫為河，殫為河兮，地不得寧，功無已□［漢書溝洫志作時。］兮吾山平，吾山平兮鉅鹿［漢書作野。］溢，魚弗鬱兮迫冬日。","sortOrder":69},
  {"id":"s_work_nvlt_43_70","chapterId":"ch_work_nvlt_43","text":"漢司馬相如琴歌曰：相如遊臨邛，富人卓王孫家，有女文君，新寡，竊於壁見之，相如因以琴歌挑之曰：鳳兮鳳兮歸故乡，遊遨四海求其皇，有艳淑女在此房，何緣交接為鴛鴦，鳳兮鳳兮從我栖，得讬字尾永為妃，交情通體心和諧，中夜相從知者誰。","sortOrder":70},
  {"id":"s_work_nvlt_43_71","chapterId":"ch_work_nvlt_43","text":"漢乌孫公主歌曰：吾家嫁我兮天一方，遠讬異國乌孫王，穹庐為室兮氈為牆，肉為食兮酪為漿，居常思土心內傷，原為黃鶴兮還故乡。","sortOrder":71},
  {"id":"s_work_nvlt_43_72","chapterId":"ch_work_nvlt_43","text":"後漢章帝時童謠曰：城中好高髻，四方高一尺，城中好大眉，四方且半額，城中好廣袖，四方用疋帛。","sortOrder":72},
  {"id":"s_work_nvlt_43_73","chapterId":"ch_work_nvlt_43","text":"後漢桓帝時童謠曰：城上乌，尾畢逋，公為吏，兒為徒，一徒死，百乘車，車班蘭，至河間，姹女能數錢，銀為室，金為堂，戶上膴々舂黃粱，下有鼓，我欲击之丞相怒。","sortOrder":73},
  {"id":"s_work_nvlt_43_74","chapterId":"ch_work_nvlt_43","text":"晉劉琨扶風歌曰：系馬長松下，废鞍高嶽頭，烈烈悲風起，泠泠涧水流，鹿遊我前，猴戲我侧，資糧既以乏，薇蕨安足食，惟昔李愆期，寄在匈奴庭，忠信反獲罪，漢武不見明。","sortOrder":74},
  {"id":"s_work_nvlt_43_75","chapterId":"ch_work_nvlt_43","text":"晉陆機百年歌曰：一十時，顏如蕣華晔有暉，體如飄風行如飛，終朝出遊薄暮歸，六情逸豫心無违，清酒將炙奈樂何，清酒將炙奈樂何。","sortOrder":75},
  {"id":"s_work_nvlt_43_76","chapterId":"ch_work_nvlt_43","text":"二十時，膚彩津泽人理成，美目淑貌灼有榮，光車駿馬遊都城，高談雅步何盈盈，清酒將炙奈樂何，清酒將炙奈樂何。","sortOrder":76},
  {"id":"s_work_nvlt_43_77","chapterId":"ch_work_nvlt_43","text":"三十時，行成名立有令聞，力可扛鼎志幹雲，食如漏卮氣如熏，辭家觀國綜典文，清酒將炙奈樂何，清酒將炙奈樂何。","sortOrder":77},
  {"id":"s_work_nvlt_43_78","chapterId":"ch_work_nvlt_43","text":"四十時，體力克壮志方刚，跨州越郡還帝乡，出入承明擁大璫，清酒將炙奈樂何，清酒將炙奈樂何。","sortOrder":78},
  {"id":"s_work_nvlt_43_79","chapterId":"ch_work_nvlt_43","text":"五十時，荷旄杖節镇邦家，鼓鍾嘈囋趙女歌，羅衣綷粲金翠華，言笑雅舞相經過，清酒將炙奈樂何，清酒將炙奈樂何。","sortOrder":79},
  {"id":"s_work_nvlt_43_80","chapterId":"ch_work_nvlt_43","text":"六十時，年亦耆艾業亦隆，驂駕四牡入紫宮，軒冕納那翠雲中，子孫昌盛家道丰，清酒將炙奈樂何，清酒將炙奈樂何。","sortOrder":80},
  {"id":"s_work_nvlt_43_81","chapterId":"ch_work_nvlt_43","text":"七十時，精爽頗損膂力愆，清水明鏡不欲觀，臨樂對酒轉無歡，攬形脩發獨長叹。","sortOrder":81},
  {"id":"s_work_nvlt_43_82","chapterId":"ch_work_nvlt_43","text":"八十時，明已損，聰去耳，前言往行不复紀，辭官致祿歸桑梓，安車驷馬入舊里，樂事告終忧事始。","sortOrder":82},
  {"id":"s_work_nvlt_43_83","chapterId":"ch_work_nvlt_43","text":"九十時，日告耽瘁月告衰，形體雖是志意非，言多谬誤心多悲，子孫朝拜或問誰，指景玩日慮安危，感念平生淚交揮。","sortOrder":83},
  {"id":"s_work_nvlt_43_84","chapterId":"ch_work_nvlt_43","text":"百歲時，盈數已登肌肉单，四支百節還相患，目若濁鏡口垂涎，呼吸嚬蹙反侧難，茵褥滋味不复安。","sortOrder":84},
  {"id":"s_work_nvlt_43_85","chapterId":"ch_work_nvlt_43","text":"晉傅玄燕人美兮歌曰：燕人美兮趙女佳，其室則邇兮限增崖，雲為車兮風為馬，玉在泥兮蘭在野，雲無期兮風有止，思多端兮誰能理。","sortOrder":85},
  {"id":"s_work_nvlt_43_86","chapterId":"ch_work_nvlt_43","text":"晉王獻之情人桃葉歌曰：桃葉复桃葉，桃葉連桃根，相怜兩樂事，獨使我纏綿。","sortOrder":86},
  {"id":"s_work_nvlt_43_87","chapterId":"ch_work_nvlt_43","text":"桃葉复桃葉，渡江不用楫，但渡無所苦，我自楫迎汝。","sortOrder":87},
  {"id":"s_work_nvlt_43_88","chapterId":"ch_work_nvlt_43","text":"桃葉答王团扇歌曰：七寶畫团扇，粲烂明月光，與郎却暄暑，相憶莫相忘，青青林中竹，可作白团扇，動搖郎玉手，因風讬方便，团扇复向誰，侍許自障面，憔悴無复理，羞與郎相見。","sortOrder":88},
  {"id":"s_work_nvlt_43_89","chapterId":"ch_work_nvlt_43","text":"齊陆□［明本作垂，按玉台新詠九作厥，當作厥。］李夫人及貴人歌曰：別車桂席尘，豹尾香煙滅，彤殿向蘼芜，青蒲复萎絕，坐萎絕，對蘼芜，臨玉階，泣長涂，寡鶴羁雌飛且止，彫梁翠壁網蜘蛛，洞房明月夜，對此淚如珠。","sortOrder":89},
  {"id":"s_work_nvlt_43_90","chapterId":"ch_work_nvlt_43","text":"晉孫綽情人詩曰：碧玉破瓜時，相為情顛倒，感郎不羞難，回身就郎抱。","sortOrder":90},
  {"id":"s_work_nvlt_43_91","chapterId":"ch_work_nvlt_43","text":"宋鮑昭白纻辭歌曰：朱唇動，素袖舉，洛陽少童邯鄲女，古稱渌水今白纻，催絃急管為君舞，窮秋九月荷葉黃，北風驅鷹天雨霜，夜長酒多樂未央，春風澹荡使思多，天色净渌氣妍和，含桃紅萼蘭紫芽，朝日灼烁發園花，卷幌結帷羅玉筵，齊謳秦吹盧女絃，千金雇笑買芳年，桂宮柏寢擬天居，朱爵文窗韜碧疏，彫屏匼匝組帳舒，秦筝趙瑟挟笙竽，垂璫散緌盈玉除，停觴不語欲誰須。","sortOrder":91},
  {"id":"s_work_nvlt_43_92","chapterId":"ch_work_nvlt_43","text":"又中興歌曰：中興太平運，化清四海樂，星星照玉台，紫煙遊鳳閣，碧樓含夜月，紫殿爭朝光，采墀散蘭麝，風起自生芳，三五容色滿，四五妙容歇，已输春日觀，分隨秋光没。","sortOrder":92},
  {"id":"s_work_nvlt_43_93","chapterId":"ch_work_nvlt_43","text":"宋謝莊明堂歌辭曰：履艮宅中宇，司繩總四方，裁化偏寒燭，布政周炎涼，景麗條可結，霜明冰可折，凯風扇朱辰，白雲流素節，右歌明堂黃帝辭，［五言，依土數。］","sortOrder":93},
  {"id":"s_work_nvlt_43_94","chapterId":"ch_work_nvlt_43","text":"參映夕，驷昭晨，雲乘震，司青春，萌動達，萬品新。","sortOrder":94},
  {"id":"s_work_nvlt_43_95","chapterId":"ch_work_nvlt_43","text":"润無际，泽無垠，右歌青帝辭，［三言，依木數。］","sortOrder":95},
  {"id":"s_work_nvlt_43_96","chapterId":"ch_work_nvlt_43","text":"龍精初見大火中，朱光北至圭景同，庶物盛長鹹殷阜，恩覃四溟被九有，右歌赤帝辭，［七言，依火數。］","sortOrder":96},
  {"id":"s_work_nvlt_43_97","chapterId":"ch_work_nvlt_43","text":"百川如鏡天地爽且明，雲冲氣舉盛德在素精，右歌白帝辭。［九言，依金數。］","sortOrder":97},
  {"id":"s_work_nvlt_43_98","chapterId":"ch_work_nvlt_43","text":"歲既暮，日既馳，靈乘坎德司規，玄雲合晦鳥歸，白雪繁亘天涯，右歌黑帝辭，［六言，依水數。］","sortOrder":98},
  {"id":"s_work_nvlt_43_99","chapterId":"ch_work_nvlt_43","text":"齊謝朓郊廟歌辭，歌青帝，［木生數三。］營翼日，鳥殷霄，凝冰泮，玄蟄昭，景湯湯，風習習，夷女歌，東皇集。","sortOrder":99},
  {"id":"s_work_nvlt_43_100","chapterId":"ch_work_nvlt_43","text":"歌赤帝，［火成數七。］惟此夏德德恢恢，兩龍在御炎精來，族雲蓊鬱溫風煽，興雨祁祁委苗遍。","sortOrder":100},
  {"id":"s_work_nvlt_43_101","chapterId":"ch_work_nvlt_43","text":"歌黃帝，土數五，禀火自明敏，資金挺刚克，涼燠資成化，群方載厚德。","sortOrder":101},
  {"id":"s_work_nvlt_43_102","chapterId":"ch_work_nvlt_43","text":"歌白帝，金數九，帝悅於兑執矩固司藏，百川牧［樂府詩集三作收。］潦精景應徂商，嘉树離披榆關命賓鳥，夜光如霜秋風方裊裊。","sortOrder":102},
  {"id":"s_work_nvlt_43_103","chapterId":"ch_work_nvlt_43","text":"歌黑帝，［水數六。］霜鍾鳴冥陵起，星回天月窮紀，聽嚴風來不息，望玄雲黝無色。","sortOrder":103},
  {"id":"s_work_nvlt_43_104","chapterId":"ch_work_nvlt_43","text":"齊王融明王歌辭曰：明王日月照，至樂天地和，幸息雲門吹，复歇鹹池歌，桂序金匏轉，瑤軒絲石羅，露凝嘉草秀，煙度醴泉波。","sortOrder":104},
  {"id":"s_work_nvlt_43_105","chapterId":"ch_work_nvlt_43","text":"又曰：聖君應昌歷，景祚啟休期，海荡萬川集，山崖百草滋，大哉君為後，何羨唐虞時。","sortOrder":105},
  {"id":"s_work_nvlt_43_106","chapterId":"ch_work_nvlt_43","text":"又曰：湛露改寒司，交湋变陽旭，琼袖藻晨紅，瑤塘，汙初渌，日霁沙溆明，風泉暗華燭，遵渚汎蘭觴，乘漪舞清曲。","sortOrder":106},
  {"id":"s_work_nvlt_43_107","chapterId":"ch_work_nvlt_43","text":"又曰：炎光銷玉殿，涼風吹鳳樓，金華妆翠羽，鹢首畫龍舟，荆姬采菱曲，越女江南謳，良時時一遇，佳人難再求。","sortOrder":107},
  {"id":"s_work_nvlt_43_108","chapterId":"ch_work_nvlt_43","text":"梁武帝春歌曰：階上香入懷，庭中花照眼，春心一如此，情來不自限。","sortOrder":108},
  {"id":"s_work_nvlt_43_109","chapterId":"ch_work_nvlt_43","text":"夏歌曰：江南莲花水，紅光复碧色，同絲有同藕，異心無異意。","sortOrder":109},
  {"id":"s_work_nvlt_43_110","chapterId":"ch_work_nvlt_43","text":"秋歌曰：繡帶合歡給，錦衣連理文，懷情入夜月，含笑出朝雲。","sortOrder":110},
  {"id":"s_work_nvlt_43_111","chapterId":"ch_work_nvlt_43","text":"团扇歌曰：手中白团扇，净如秋圓月，清風任動生，娇香乘意發。","sortOrder":111},
  {"id":"s_work_nvlt_43_112","chapterId":"ch_work_nvlt_43","text":"襄陽白銅隄歌曰：龍馬紫金鞍，翠毦白玉羁，照曜双闕下，知是襄陽兒。","sortOrder":112},
  {"id":"s_work_nvlt_43_113","chapterId":"ch_work_nvlt_43","text":"梁沈約郊廟歌黃帝辭曰：鬱彼中壇，含靈闡化，回環氣象，輪無輟駕。","sortOrder":113},
  {"id":"s_work_nvlt_43_114","chapterId":"ch_work_nvlt_43","text":"歌青帝辭曰：帝位在震，龍德司春，开元布泽，含和上人。","sortOrder":114},
  {"id":"s_work_nvlt_43_115","chapterId":"ch_work_nvlt_43","text":"歌赤帝辭曰：炎光在離，火為盛德，執禮昭訓，持衡授則。","sortOrder":115},
  {"id":"s_work_nvlt_43_116","chapterId":"ch_work_nvlt_43","text":"歌白帝辭曰：神在秋方，帝居西顥，允茲金德，裁成萬寶。","sortOrder":116},
  {"id":"s_work_nvlt_43_117","chapterId":"ch_work_nvlt_43","text":"歌黑帝辭曰：德盛浮水，玄冥紀節，陰降陽騰，氣凝象閉。","sortOrder":117},
  {"id":"s_work_nvlt_43_118","chapterId":"ch_work_nvlt_43","text":"元會歌辭，皇帝出入奏皇雅，歌詩三曲，五言，［二郊太廟明堂同用。］帝德實廣運，車書靡不賓，執瑁朝群後，垂旒御百神。","sortOrder":118},
  {"id":"s_work_nvlt_43_119","chapterId":"ch_work_nvlt_43","text":"華蓋拂紫微，鉤陳繞太一，容裔被緹組，參差羅罘罼。","sortOrder":119},
  {"id":"s_work_nvlt_43_120","chapterId":"ch_work_nvlt_43","text":"清跸朝萬宇，端冕臨正陽，春句［隋書音樂志作青絇。］黃金繶，袞衣文繡裳。","sortOrder":120},
  {"id":"s_work_nvlt_43_121","chapterId":"ch_work_nvlt_43","text":"皇太子出入奏胤雅，歌詩一曲，四言，自昔殷代，哲王世有，降及周成，惟器是守，上天乃眷，大梁既受，灼灼重明，仰承元首，上寿酒奏分［隋書音樂志作介。］雅，詩一曲，五言，百福四象初，萬寿三元始，拜獻惟袞職，同心协卿士，北極永無窮，南山安足擬。","sortOrder":121},
  {"id":"s_work_nvlt_43_122","chapterId":"ch_work_nvlt_43","text":"又襄陽白銅鞮歌曰：分手桃林崖，望別峴山頭，若欲寄音信，漢水向東流。","sortOrder":122},
  {"id":"s_work_nvlt_43_123","chapterId":"ch_work_nvlt_43","text":"又春白纻歌曰：蘭葉參差桃半紅，飛芳舞縠戲春風，如娇如怨状不同，含笑流盻滿堂中，翡翠群飛飛不息，原在雲間長比翼，佩服堇［樂府詩集五十六作瑤。］草駐容色，舜日尧年歡無極。","sortOrder":123},
  {"id":"s_work_nvlt_43_124","chapterId":"ch_work_nvlt_43","text":"夏白纻歌曰：朱火灼烁照佳人，含情送意遙相親，嫣然一轉亂心神，非子之故欲誰因。","sortOrder":124},
  {"id":"s_work_nvlt_43_125","chapterId":"ch_work_nvlt_43","text":"秋白纻歌曰：白露欲凝草已黃，金琯玉柱响洞房，双心一影俱回翔，吐情寄君君莫忘。","sortOrder":125},
  {"id":"s_work_nvlt_43_126","chapterId":"ch_work_nvlt_43","text":"冬白纻歌曰：寒閨晝密羅幌垂，娇容麗色心相知，双去双還誓不移，長袖拂面為君施。","sortOrder":126},
  {"id":"s_work_nvlt_43_127","chapterId":"ch_work_nvlt_43","text":"梁劉孝威行幸甘泉歌曰：漢家迎夏畢，避暑甘泉宮，栈車鳴里鼓，驷馬駕相風，校尉乌丸騎，待詔娄煩弓，後旌猶五柞，前笳度九顒，才人豹尾內，御酒屬車中，輦回百子閣，扇動七輪風，鳴鍾休衛士，披圖占後宮，材官但校獵，涼風戲射熊。","sortOrder":127},
  {"id":"s_work_nvlt_43_128","chapterId":"ch_work_nvlt_43","text":"古東飛伯勞等歌曰：東飛伯勞西飛燕，黃姑織女時相見，誰家女兒對門居，开華發色照里闾，南窗北牖掛明光，羅帷綺帳脂粉香，女兒年幾十五六，窈窕無双顏如玉，三春已暮花隨風，空留可怜與誰同。","sortOrder":128},
  {"id":"s_work_nvlt_43_129","chapterId":"ch_work_nvlt_43","text":"古，［古下疑有脱文。］河中之水向東流，洛陽女兒名莫愁，莫愁十三能織綺，十四采桑東陌頭，十五嫁為盧家婦，十六生兒字阿侯，盧家蘭室桂為梁，中有鬱金蘇合香，頭上金釵十二行，足下絲履五文章，珊瑚掛鏡烂生光，平頭奴子提履箱，人生富貴何所望，恨不嫁與東家王。","sortOrder":129},
  {"id":"s_work_nvlt_43_130","chapterId":"ch_work_nvlt_43","text":"【賦】袁山松歌賦曰：朱唇不啟，皓齒不離，清氣獨轉，妍弄潛移，或似停而不留，或如疾而不馳。","sortOrder":130},
  {"id":"s_work_nvlt_43_131","chapterId":"ch_work_nvlt_43","text":"【箋】魏繁钦與太子箋曰：都尉薛訪車子，年始十四，能啭喉引聲，與葭同音，乃知天壤之所生，誠有自然之妙物，潛氣內轉，哀音外激，大不抗越，細不幽散，聲悲奋笳，曲美常均，及與黃門鼓吹溫胡，迭唱迭和，喉所發音，無不响應，遺聲抑扬，不可勝窮，暨其清激悲吟，雜以怨慕，詠北狄之遐征，奏胡馬之長思，是時涼風拂衽，背山臨谿，莫不泫泣陨涕，悲懷慷慨，竊惟聖體，兼愛好奇，是以先白。","sortOrder":131},
  {"id":"s_work_nvlt_43_132","chapterId":"ch_work_nvlt_43","text":"魏文帝答曰：披書歡笑，不能自勝，奇才妙伎，何其善也，頃守土［《太平御覽》五百七十三作守宮王，按當作守宮士。］孫世，有女曰琐，年始九歲，夢與神通，寤而悲吟，哀聲激切，涉歷六載，於今十五，近者督將具以状聞，是日博延眾賢，遂奏名倡，曲極數彈，歡情未逞，乃令從官，引內世女，須臾而至，厥状甚美，素顏玄發，皓齒丹唇，詳而問之，雲善歌舞，於是提袂徐進，扬蛾微眺，芳聲清激，逸足橫集，然後循容飾妆，改曲变度，斯可謂聲协鍾石，氣應風律，今之妙舞，莫巧於絳树，清歌莫善［《太平御覽》三百八十一，《初學記》十九作激。］於宋臈，豈能亂［全三國文七亂上有上字。］靈祇，下变庶物，漂悠風雲，橫厲無方，若斯也哉，固非車子喉啭長吟所能逮也，吾練色知聲，雅應此選，謹卜良日，納之閒房。","sortOrder":132},
  {"id":"s_work_nvlt_43_133","chapterId":"ch_work_nvlt_43","text":"【啟】梁沈約謝齊竟陵王宋永明樂歌曰：鳳采鸞章，霞鮮錦縟，觌寶河宗，未必比麗，觀樂帝所，遠有慚德，雖日月在天，理絕稱詠，而徘徊光景，不能自息。","sortOrder":133},
  {"id":"s_work_nvlt_43_134","chapterId":"ch_work_nvlt_43","text":"《藝文類聚》　唐·欧陽詢","sortOrder":134},
  {"id":"s_work_nvlt_44_1","chapterId":"ch_work_nvlt_44","text":"卷四十四樂部四","sortOrder":1},
  {"id":"s_work_nvlt_44_2","chapterId":"ch_work_nvlt_44","text":"○琴筝箜篌琵琶筍虡箫笙笛笳","sortOrder":2},
  {"id":"s_work_nvlt_44_4","chapterId":"ch_work_nvlt_44","text":"周官，孤竹之管，雲和之琴瑟，冬日至，於地上圓丘奏之，孤竹之管，空桑之琴瑟，夏日至，於泽中方丘奏之，陰竹之管，龍門之琴瑟，於宗廟奏之。","sortOrder":4},
  {"id":"s_work_nvlt_44_5","chapterId":"ch_work_nvlt_44","text":"《毛詩》曰：窈窕淑女，琴瑟友之。","sortOrder":5},
  {"id":"s_work_nvlt_44_6","chapterId":"ch_work_nvlt_44","text":"《禮記》曰：舜作五絃之琴，以歌南風之詩，而天下治。","sortOrder":6},
  {"id":"s_work_nvlt_44_7","chapterId":"ch_work_nvlt_44","text":"又曰：絲聲哀，哀以廉，廉以立志，君子聽琴瑟之聲，則思志義之臣。","sortOrder":7},
  {"id":"s_work_nvlt_44_8","chapterId":"ch_work_nvlt_44","text":"《左傳》曰：晉侯觀於軍府，見鍾儀，問其族，曰：伶人也，與之琴，操南音，公曰：君子也，言稱先職，不背本也，樂操土風，不忘舊也。","sortOrder":8},
  {"id":"s_work_nvlt_44_9","chapterId":"ch_work_nvlt_44","text":"又曰：初衛侯有嬖妾，使師曹誨之琴，師曹鞭之，公怒，鞭師曹三百。","sortOrder":9},
  {"id":"s_work_nvlt_44_10","chapterId":"ch_work_nvlt_44","text":"《列子》曰：瓠巴鼓琴，而鳥舞魚躍。","sortOrder":10},
  {"id":"s_work_nvlt_44_11","chapterId":"ch_work_nvlt_44","text":"又曰：孔子遊太山，見榮啟期，鹿裘帶索鼓琴瑟，孔子問曰：先生為樂何也，對曰：天生萬物，唯人為貴，吾既為人，一樂也，男貴女賤，今既為男，二樂也，今有不見日月，不免襁褓，吾行年九十有五矣，三樂也，貧者士之常，死者生之終，居常以待終，何忧哉。","sortOrder":11},
  {"id":"s_work_nvlt_44_12","chapterId":"ch_work_nvlt_44","text":"《呂氏春秋》曰：宓子賤治单父，彈琴，身不下堂而治。","sortOrder":12},
  {"id":"s_work_nvlt_44_13","chapterId":"ch_work_nvlt_44","text":"又曰：伯牙鼓琴，鍾子期善聽之，方鼓琴，志在太山，鍾子期曰：善哉乎鼓琴，巍巍乎如太山，志在流水，鍾子期曰：善哉乎鼓琴，洋洋乎若流水，鍾子期死，伯牙擗琴絕絃，終身不复鼓琴，以為世無足鼓琴以也。","sortOrder":13},
  {"id":"s_work_nvlt_44_14","chapterId":"ch_work_nvlt_44","text":"《莊子》曰：孔子遊乎緇帷之林，坐杏壇之上，弟子讀書，孔子絃歌鼓琴，奏曲未半，有漁父者，下舡而來，孔子推琴而起曰：其聖人欤，［事具居處部壇篇。］《孫卿子》曰：伯牙鼓琴，六馬仰秣。","sortOrder":14},
  {"id":"s_work_nvlt_44_15","chapterId":"ch_work_nvlt_44","text":"《史記》曰：萬石君奋，年十五，為小吏，侍高祖，高祖與語，愛其恭敬，問曰：若何有，對曰：獨有母，不幸失明，有姊，能鼓琴，高祖乃召其姊為美人，以奋為中涓，徙其家長安中戚里。","sortOrder":15},
  {"id":"s_work_nvlt_44_16","chapterId":"ch_work_nvlt_44","text":"又曰：騶忌以鼓琴見齊威王，威王舍之右室。","sortOrder":16},
  {"id":"s_work_nvlt_44_17","chapterId":"ch_work_nvlt_44","text":"又曰：司馬相如素與臨邛令王吉相善，臨邛富人卓王孫，有女文君，新寡，好音，故相如缪與令相重，而以琴心挑之，文君竊從戶窥之，心悅，既罢，相如乃使人重賜文君侍者，通殷勤，文君夜亡奔相如。","sortOrder":17},
  {"id":"s_work_nvlt_44_18","chapterId":"ch_work_nvlt_44","text":"桓谭《新論》曰：神農氏繼而王天下，於是始削桐為琴，繩絲為絃，以通神明之德，合天人之和焉，《廣雅》曰：神農氏琴，長三尺六寸六分，上有五絃，曰宮商角徵羽，文王增二絃，曰少宮少商。","sortOrder":18},
  {"id":"s_work_nvlt_44_19","chapterId":"ch_work_nvlt_44","text":"《風俗通》曰：琴者樂之統，與八音併行，君臣以相御也，和樂作者，其曲曰畅，言其道畅美也，忧愁作者，其曲曰操，言心失其操也。","sortOrder":19},
  {"id":"s_work_nvlt_44_20","chapterId":"ch_work_nvlt_44","text":"《說苑》曰：雍門周以琴見孟嘗君，孟嘗君曰：先生鼓琴，亦能令文悲乎，周曰：臣獨焉能令足下悲哉，所能令悲者，先貴而後賤，先富而後貧，不若身才高妙，適遭暴亂，不若處势隱絕，不及四鄰，诎折擯厭，舞［《太平御覽》五百七十九舞字無。］無所告愬，臣一為之徵操援琴，則涕零矣，今若足下，千乘之君，廣夏邃房，下羅帷，來清風，斗象旗，［說苑善說篇作棋。］舞鄭妾，麗色淫目，流聲娱耳，水遊則連方舟，戴羽旗，野遊則馳弋獵乎平原廣囿，入則撞鍾击鼓乎深宮之中，雖有善鼓琴者，固未能使足下悲也，然臣所為足下悲者一也，千秋萬世之後，宗廟必不血食，高台既已坏，曲池既已漸，墳墓既已下，婴兒竖子樵采者，踯躅其足而歌其上曰：夫以孟嘗君尊貴，乃若是乎，於是孟嘗泫焉承脸，周引琴而鼓之，徐動宮徵，拂羽角，孟嘗涕泣增哀，下而就之曰：先生之鼓琴，令文若破國亡邑之人。","sortOrder":20},
  {"id":"s_work_nvlt_44_21","chapterId":"ch_work_nvlt_44","text":"《韓詩外傳》曰：孔子南遊適楚，至於阿穀之隧，有處女佩瑱而浣，孔子曰：彼婦人可與言矣，抽琴去其軫，以授子貢曰：善為之辭，子貢曰：於此有琴而無軫，借子以調其音，婦人對曰：吾野鄙之人，五音不知，安能調琴。","sortOrder":21},
  {"id":"s_work_nvlt_44_22","chapterId":"ch_work_nvlt_44","text":"《江表傳》曰：顧雍從蔡邕學琴，雍異之，曰：卿必成，故以名與卿。","sortOrder":22},
  {"id":"s_work_nvlt_44_23","chapterId":"ch_work_nvlt_44","text":"華峤《漢書》曰：初蔡邕在陳留，鄰人有以酒食召雍［按雍邕通。］者，比往而酒以酣，客有彈琴於屏，邕至門，潛聽之，曰：以樂召我，而有殺心，何也，遂反，將命者告主人，以蔡君至門而去，邕素為邦乡所宗，主人遂自追問其故，邕且以告，莫不怃然，彈琴者曰：我向見螳螂方向鳴蝉，蝉將去而未飛，螳螂為之一前一却，吾心耸然，唯恐螳螂之失蝉也，此豈為殺心而形於聲者乎，邕笑曰：此足以當之矣，［事具鳥部蝉篇。］","sortOrder":23},
  {"id":"s_work_nvlt_44_24","chapterId":"ch_work_nvlt_44","text":"《列仙傳》曰：稷丘公，華山道士，漢武封禪，公乃冠章甫，擁琴來迎。","sortOrder":24},
  {"id":"s_work_nvlt_44_25","chapterId":"ch_work_nvlt_44","text":"劉向別錄曰：雅琴之意事，皆出龍德諸琴雜事中，趙氏者，渤海人趙定也，宣帝時，元康神爵間，丞相奏能鼓琴者渤海趙定梁國龍德，皆召，入見溫室，使鼓琴待詔，定為人尚清靜，少言語，善鼓琴，時間燕為散操，多為之涕泣者。","sortOrder":25},
  {"id":"s_work_nvlt_44_26","chapterId":"ch_work_nvlt_44","text":"《東觀漢記》曰：上嘗問宋弘通儒之士，弘荐桓谭，谭善鼓琴，憙鄭聲，上數聽悅之，聞，坐府上，遣吏召谭，责問之，谭叩頭良久乃遣，後上令谭鼓琴，谭為之失次，上問之，弘言其故，其後不复令谭給事中。","sortOrder":26},
  {"id":"s_work_nvlt_44_27","chapterId":"ch_work_nvlt_44","text":"孫登別傳曰：孫登，字公和，汲郡人，清靜無為，好讀易彈琴，頹然自得，觀其風神，若遊六合之外者，當魏末，居北山中，以石窟為宇，編草自覆，阮嗣宗見登，被發端坐巖下，遙見鼓琴，嗣宗自下趍進，莫得與言，嗣宗乃長嘯，與琴音諧和，登因嘯和之，妙响動林壑。","sortOrder":27},
  {"id":"s_work_nvlt_44_28","chapterId":"ch_work_nvlt_44","text":"《語林》曰：嵇中散夜燈火下彈琴，有一人，面甚小，斯須轉大，遂長丈餘，黑单衣草［《太平御覽》五百七十七，八百七十作革。］帶，嵇视之既熟，乃吹火滅，曰：恥與魑魅爭光。","sortOrder":28},
  {"id":"s_work_nvlt_44_29","chapterId":"ch_work_nvlt_44","text":"阮籍樂論曰：漢桓帝聞楚琴扆而悲，慷慨長息曰：善哉，為聲如此而足矣，昔季流子向風而鼓琴，聽之者淚下。","sortOrder":29},
  {"id":"s_work_nvlt_44_30","chapterId":"ch_work_nvlt_44","text":"蔡琰別傳曰：琰，字文姬，蔡邕之女，年六歲，夜鼓琴，絃斷，琰曰：第二絃，邕故斷一絃，而問之，琰曰：第四絃，邕曰：偶得之矣，琰曰：吳札觀化，知興亡之國，師曠吹律，識南風之不競，由此觀之，何足不知。","sortOrder":30},
  {"id":"s_work_nvlt_44_31","chapterId":"ch_work_nvlt_44","text":"馬明生別傳曰：明生隨神女入石室，金床玉幾，彈琴有一絃，五音併奏。","sortOrder":31},
  {"id":"s_work_nvlt_44_32","chapterId":"ch_work_nvlt_44","text":"《搜神記》曰：吳人有燒桐以爨者，蔡邕聞其爆聲曰：此良桐也，因請之，削以為琴，而燒不盡，因名燋尾琴，有殊聲焉。","sortOrder":32},
  {"id":"s_work_nvlt_44_33","chapterId":"ch_work_nvlt_44","text":"《晉中興書》曰：戴逵，字安道，少有文藝，善鼓琴，太宰武陵王晞，聞其能琴，使人召焉，逵對使者前，打破琴曰：戴安道不能為王侯伶人。","sortOrder":33},
  {"id":"s_work_nvlt_44_34","chapterId":"ch_work_nvlt_44","text":"《世說》曰：會稽有防風鬼，屢見城邑，常跂雷門上，腳乘至地，晉橫陽令贺韜善鼓琴，防風聞琴聲，在贺中庭舞。","sortOrder":34},
  {"id":"s_work_nvlt_44_35","chapterId":"ch_work_nvlt_44","text":"沈約《宋書》曰：萧思話領左衛將軍，嘗從太祖登鍾山北嶺，中道有盤石清泉，上使於石上彈琴，因賜以銀鍾酒，謂曰：相賞有松石間之高意也。","sortOrder":35},
  {"id":"s_work_nvlt_44_36","chapterId":"ch_work_nvlt_44","text":"【詩】梁丘遲題琴朴奉柳吳興詩曰：邊山此嘉树，搖影出雲垂，清心有素體，直幹無曲枝，凡耳非所別，君子特見知，不辭去根本，造膝仰光儀。","sortOrder":36},
  {"id":"s_work_nvlt_44_37","chapterId":"ch_work_nvlt_44","text":"陳沈蜅為我彈鳴琴詩曰：為我彈鳴琴，琴鳴傷我衿，半死無人覺，入竈始知音，空為貞女引，誰達楚妃心，雍門何假說，落淚自淫淫。","sortOrder":37},
  {"id":"s_work_nvlt_44_38","chapterId":"ch_work_nvlt_44","text":"陳贺澈為我彈鳴琴詩曰：薄暮高堂上，調琴召美人，伯喈聲未盡，相如曲复新，點徽還轉弄，亂爪更留賓，聊持一絃响，雜起艳歌尘。","sortOrder":38},
  {"id":"s_work_nvlt_44_39","chapterId":"ch_work_nvlt_44","text":"隋江總賦詠待琴詩曰：可怜嶧陽木，雕為绿綺琴，田文承睫淚，卓女弄絃心，戲鶴來應舞，遊魚聽不沉，楚妃幸勿叹，此異丘中音。","sortOrder":39},
  {"id":"s_work_nvlt_44_40","chapterId":"ch_work_nvlt_44","text":"【賦】後漢傅毅琴賦曰：歷嵩岑而將降，睹鸿梧於幽阻，高百仞而不枉，對脩條以持處，蹈通涯而將圖，遊茲梧之所宜，蓋雅琴之麗朴，乃升伐其孫枝，命離娄使布繩，施公输之剞劂，遂彫琢而成器，揆神農之初製，盡聲变之奧妙，抒心志之鬱滯。","sortOrder":40},
  {"id":"s_work_nvlt_44_41","chapterId":"ch_work_nvlt_44","text":"後漢馬融琴賦曰：惟梧桐之所生，在衡山之峻陂，於是遨間公子，中道失志，孤茕特行，懷闵抱思，昔師曠三奏，而神物下降，玄鶴二八，軒舞於庭，何琴德之深哉。","sortOrder":41},
  {"id":"s_work_nvlt_44_42","chapterId":"ch_work_nvlt_44","text":"後漢蔡邕琴賦曰：爾乃言求茂木，周流四垂，觀彼椅桐，層山之陂，丹華煒燁，绿葉參差，甘露润其末，涼風扇其枝，鸞鳳翔其巔，玄鶴巢其岐，考之詩人，琴瑟是宜，爾乃清聲發兮五音舉，發宮商兮動角羽，曲引興兮繁絃撫，然後哀聲既發，秘弄乃开，左手抑扬，右手徘徊，指掌反覆，抑案藏摧，於是繁絃既抑，雅韻乃扬，仲尼思歸，鹿鳴三章，梁甫悲吟，周公越裳，青雀西飛，別鶴東翔，飲馬長城，楚曲明光，楚姬遺叹，雞鳴高桑，走獸率舞，飛鳥下翔，感激茲歌，一低一昂。","sortOrder":42},
  {"id":"s_work_nvlt_44_43","chapterId":"ch_work_nvlt_44","text":"晉嵇康琴賦曰：椅桐之所生，讬峻嶽之崇岡，含天地之醇和，吸日月之休光，鬱紛紜以獨茂，飛英蕤於旻蒼，其山川形势，則盤紆隱嶙，蛇崔嵬岑嵒，丹崖崄巇，青壁萬尋，若乃春蘭被其東，沙棠植其西，涓子宅其陽，玉醴涌其前，玄雲荫其上，翔鸞集其巔，乃斫孫枝，准量所任，至人摅思，製為雅琴，错以犀象，藉以翠绿，絃以園客之絲，徽以鍾山之玉，爰有龍鳳之象，古人之形，伯牙揮手，鍾期聽聲，華容灼烁，發采扬明，伶倫比律，田連操張，進御君子，新聲嘹亮，及其初調，則角羽俱起，宮徵相證，參發併趣，上下累應，若乃高軒飛觀，廣厦閒房，冬夜肅清，朗月垂光，新衣翠粲，纓徽流芳，於是器洽絃調，心閒手敏，觸〈媲\"女改扌\"〉如志，唯意所擬，初涉渌水，中奏清徵，拊絃安歌，新聲代起，曲引向阑，眾音將歇，改韻易調，奇弄乃發，或徘徊顧慕，擁鬱抑按，盤桓毓養，從容秘玩，牢落凌厲，布濩半散，英聲發越，采采粲粲，穆溫柔以怡怿，婉順叙而委蛇，或乘险投會，邀隙趍危，嘤若離鵾鳴清池，翼若遊鸿翔增崖，或樓〈媲\"女改木\"〉櫟捋，漂缭潎洌。遠而聽之，若鸞鳳和鳴戲雲中，迫而察之，若眾葩敷榮曜春風，若次其曲引所宜，則廣陵止息，東武太山，飛龍鹿鳴，鵾雞遊絃，更唱迭奏，聲若自然，下逮謠俗，蔡氏五曲，王昭楚妃，千里別鶴，論其體势，詳其風聲，器和故响逸，張急故聲清，間遼故音埤，絃長故徽鳴，性絜靜以端理，含至德之和平，誠可以感荡心志，而發泄幽情矣。","sortOrder":43},
  {"id":"s_work_nvlt_44_44","chapterId":"ch_work_nvlt_44","text":"晉成公綏琴賦曰：伯牙彈而驷馬仰秣，子野揮而玄鶴鳴，清角發而陽氣亢，白雲奏而風雨零。","sortOrder":44},
  {"id":"s_work_nvlt_44_45","chapterId":"ch_work_nvlt_44","text":"【贊】晉殷仲堪琴贊曰：五聲不彰，孰表太音，至人善寄，畅之雅琴，聲由動發，趣以虛深。","sortOrder":45},
  {"id":"s_work_nvlt_44_46","chapterId":"ch_work_nvlt_44","text":"晉王珣琴贊曰：穆穆和琴，至至愔愔，如彼清風，泠焉經林。","sortOrder":46},
  {"id":"s_work_nvlt_44_47","chapterId":"ch_work_nvlt_44","text":"宋謝惠連琴贊曰：嶧陽孤桐，裁為鳴琴，體兼九絲，聲備五音，重華載揮，以養民心，孫登是玩，取樂山林。","sortOrder":47},
  {"id":"s_work_nvlt_44_48","chapterId":"ch_work_nvlt_44","text":"【銘】後漢李尤琴銘曰：琴之在音，荡涤邪心，雖有正性，其感亦深，存雅却鄭，浮侈是禁，條畅和正，樂而不淫。","sortOrder":48},
  {"id":"s_work_nvlt_44_50","chapterId":"ch_work_nvlt_44","text":"《釋名》曰：筝，施絃高，筝筝然。","sortOrder":50},
  {"id":"s_work_nvlt_44_51","chapterId":"ch_work_nvlt_44","text":"《史記》曰：秦逐客李斯上書曰：夫击瓮［《太平御覽》五百七十六，瓮下有缶字。］叩瓶，彈琴［御覽作筝。］搏髀，而歌呼呜鳴快耳者，真秦之聲。","sortOrder":51},
  {"id":"s_work_nvlt_44_52","chapterId":"ch_work_nvlt_44","text":"《風俗通》曰：謹案禮樂記，筝五絃筑身也，今併涼二州筝，形如瑟，不知誰改也。","sortOrder":52},
  {"id":"s_work_nvlt_44_53","chapterId":"ch_work_nvlt_44","text":"《英雄記》曰：呂布詣袁紹，紹患布，欲殺之，遣三十六兵被鎧迎布，使著帳邊臥，布知之，使於帳中鼓筝，諸兵臥，布出帳去，兵不覺也。","sortOrder":53},
  {"id":"s_work_nvlt_44_54","chapterId":"ch_work_nvlt_44","text":"傅子曰：郝素善彈筝，雖伯牙妙手，吳姬奇聲，何以加之。","sortOrder":54},
  {"id":"s_work_nvlt_44_55","chapterId":"ch_work_nvlt_44","text":"又曰：筝者，上圓象天，下平象地，中空准六合，絃柱十二，擬十二月，乃仁智之器也。","sortOrder":55},
  {"id":"s_work_nvlt_44_56","chapterId":"ch_work_nvlt_44","text":"《語林》曰：桓野王善解音，晉孝武祖宴西堂，樂阕酒阑，將詔桓野王筝歌，野王辭以須笛，於是詔其常吹奴硕，賜姓曰張，加四品將軍，引使上殿，張硕意氣激扬，吹破三笛，末取暏腳［按世說輕詆篇，蔡伯喈睹睞笛條，註引伏滔長笛賦序(亦見本卷笛篇)桓子野有故長笛，雲蔡邕之所作雲雲，疑當作睹睞笛。］笛，然後乃理調成曲。","sortOrder":56},
  {"id":"s_work_nvlt_44_57","chapterId":"ch_work_nvlt_44","text":"《俗說》曰：謝仁祖為豫州主簿，在桓溫閤下，桓聞其善彈筝，便呼之，既至，取筝令彈，謝即理絃撫筝，因歌秋風，意氣殊遒，桓大以此知之。","sortOrder":57},
  {"id":"s_work_nvlt_44_58","chapterId":"ch_work_nvlt_44","text":"【詩】梁王台卿詠筝曰：依歌時轉韻，按曲動花钿，促調移輕柱，亂手度繁絃，唯有高秋月，秦聲獨可怜。","sortOrder":58},
  {"id":"s_work_nvlt_44_59","chapterId":"ch_work_nvlt_44","text":"梁孝元帝和彈筝人詩曰：琼柱動金絲，奏聲發趙曲，流徵含陽春，美手過如玉。","sortOrder":59},
  {"id":"s_work_nvlt_44_60","chapterId":"ch_work_nvlt_44","text":"梁沈約詠筝詩曰：秦筝吐絕調，玉柱扬清曲，絃依高張斷，聲隨妙指續，徒聞音繞梁，寧知顏如玉。","sortOrder":60},
  {"id":"s_work_nvlt_44_61","chapterId":"ch_work_nvlt_44","text":"【賦】後漢侯瑾筝賦曰：於是急絃促柱，变調改曲，卑殺纖妙，微聲繁縟，散清商而流轉兮，若將絕而复續，紛曠荡以繁奏，邈遺世而越俗，若乃察其風采，練其聲音，美武荡乎，樂而不淫，雖懷思而不怨，似豳風之遺音，於是雅曲既阕，鄭衛仍脩，新聲順变，妙弄優遊，微風漂裔，冷氣輕浮，感悲音而增叹，怆嚬悴而懷愁，若乃上感天地，下動鬼神，享祀祖宗，酬酢嘉賓，移風易俗，混同人倫，莫有尚於筝者矣，魏阮瑀筝賦曰：惟夫筝之奇妙，極五音之幽微，苞群聲以作主，冠眾樂而為師，禀清和於律呂，籠絲木以成資，身長六尺，應律數也，故能清者感天，濁者合地，五聲併用，動靜簡易，大興小附，重發輕隨，折而复扶，循覆逆开，浮沉抑扬，升降綺靡，殊聲妙巧，不識其為，平調足均，不疾不徐，遲速合度，君子之衢也，慷慨磊落，卓砾盤紆，壮士之節也，曲高和寡，妙妓難工，伯牙能琴，於茲為朦，皦怿翕純，庶配其蹤，延年新聲，豈此能同，陳惠李文，曷能是逢。","sortOrder":61},
  {"id":"s_work_nvlt_44_62","chapterId":"ch_work_nvlt_44","text":"晉陶融妻陳氏筝賦曰：伊夫筝之為體，惟高亮而殊特，應六律之修和，與七始乎消息，括八音之精要，超眾器之表式，後夔創製，子野考成，列柱成陳，既和且平，牙氏攘袂而奋手，鍾期傾耳以靜聽，奏清角之要妙，詠騶虞以鹿鳴，獸連軒而率舞，鳳踉蹌而集庭，汎濫浮沉，逸响發揮，翕然若絕，皎如复回，爾乃秘艳曲，卓砾殊異，周旋去留，千变萬態。","sortOrder":62},
  {"id":"s_work_nvlt_44_63","chapterId":"ch_work_nvlt_44","text":"晉贾彬筝賦曰：溫顏既授，和志向悅，賓主交歡，聲铎品列，鍾子授筝，伯牙同節，唱葛天之高韻，贊幽蘭與白雪，其始奏也，蹇澄疏雅，若將畅而未越，其漸成也，抑按铿锵，猶沉鬱之舒彻，何以盡美，請徵其喻，剖状同形，兩象著也，設絃十二，太蔟數也，列柱參差，招搖布也，分位允諧，六龍御也。","sortOrder":63},
  {"id":"s_work_nvlt_44_64","chapterId":"ch_work_nvlt_44","text":"晉顧恺之筝賦曰：其器也，則端方修直，天隆地平，華文素质，烂蔚波成，君子嘉其斌麗，知音伟其含清，罄虛中以扬德，正律度而儀形，良工加妙，輕縟璘彬，玄漆緘响，慶雲被身。","sortOrder":64},
  {"id":"s_work_nvlt_44_65","chapterId":"ch_work_nvlt_44","text":"梁簡文帝筝賦曰：聽鳴筝之弄响，聞茲絃之一彈，足使客遊恋國，壮士冲冠，若夫楚王怡荡，楊生娱志，小國寡民，督郵無事，乃有燕餘麗妾，方桃譬李，本住南城，經居東里，度玲瓏之曲閤，出翡翠之香帷，腕凝紗薄，珮重行遲，爾乃促筵命友，衔觴置酒，耳熱眼花之娱，千金萬年之寿，白日蹉跎，時淹樂久，玩飛花之度窗，看春風之入柳，命麗人於玉席，陳寶器於紈羅，撫鳴筝而動曲，譬輕薄之經過，若夫鈞竿复發，蛱蝶初揮，動玉匣之餘怨，鳴陽乌之始飛，逐東趍於鄭女，和西舞於荆妃，使長廊之瓦虛墜，梁上之尘染衣。","sortOrder":65},
  {"id":"s_work_nvlt_44_66","chapterId":"ch_work_nvlt_44","text":"◇箜篌","sortOrder":66},
  {"id":"s_work_nvlt_44_67","chapterId":"ch_work_nvlt_44","text":"《釋名》曰：箜篌，師延所作，靡靡之樂，後出桑間濮上之地，師涓為晉平公鼓焉，鄭衛分其地而有之，遂號鄭衛之音為淫樂。","sortOrder":67},
  {"id":"s_work_nvlt_44_68","chapterId":"ch_work_nvlt_44","text":"桓谭《新論》曰：鄙人謂狐為狸，以瑟為箜篌，此非徒不知狐與瑟，乃不知狸與箜篌也。","sortOrder":68},
  {"id":"s_work_nvlt_44_69","chapterId":"ch_work_nvlt_44","text":"司馬相如凡將篇曰：鍾磬竽笙筑坎侯。","sortOrder":69},
  {"id":"s_work_nvlt_44_70","chapterId":"ch_work_nvlt_44","text":"《續漢書》曰：靈帝好胡服，作胡箜篌。","sortOrder":70},
  {"id":"s_work_nvlt_44_71","chapterId":"ch_work_nvlt_44","text":"甄異傳曰：永和中，吳郡陳緒家，平旦，忽有叩門自通，雲陳都尉寄住，緒有妾姓奚，能彈箜篌，神意歡悅，既令妾絃歌，歌聲焦細，歷三年乃別去。","sortOrder":71},
  {"id":"s_work_nvlt_44_72","chapterId":"ch_work_nvlt_44","text":"班彪上事曰：漢宣帝賜呼韓耶单於竽瑟箜篌。","sortOrder":72},
  {"id":"s_work_nvlt_44_73","chapterId":"ch_work_nvlt_44","text":"《琴操》曰：箜篌引者，朝鮮津卒霍子高所作也，子高晨刺舡而濯，有一狂夫，被發提壶而渡，其妻追止之，不及，墮河而死，乃號天噓唏，鼓箜篌而歌，曲終投河而死，子高援琴，作其歌聲，故曰箜篌引。","sortOrder":73},
  {"id":"s_work_nvlt_44_74","chapterId":"ch_work_nvlt_44","text":"《搜神記》曰：晉永嘉中，有神見兖州，自號樊道基，有嫗號成夫人，夫人好音樂，能彈箜篌，聞人歌絃，辄起舞。","sortOrder":74},
  {"id":"s_work_nvlt_44_75","chapterId":"ch_work_nvlt_44","text":"《風俗通》曰：箜篌一名坎侯，謹按，武帝祀太山太一後土，令樂人侯調，依琴作坎侯，言其坎坎應節也，侯以姓冠章也。","sortOrder":75},
  {"id":"s_work_nvlt_44_76","chapterId":"ch_work_nvlt_44","text":"【詩】梁簡文帝賦得箜篌詩曰：捩遲初挑吹，弄急時催舞，钏响逐絃鳴，衫回半鄣柱，欲知心不平，君看黛眉聚。","sortOrder":76},
  {"id":"s_work_nvlt_44_77","chapterId":"ch_work_nvlt_44","text":"【賦】晉鈕滔母孫氏箜篌賦曰：考茲器之所起，實侯氏之所營，遠不假於琴瑟，顧無取乎竽笙，爾乃陟九峻之增巖，晞承溫之朝日，剖嶧陽之孤桐，代楚宮之椅漆，徵班输之造器，命伶倫而調律，浮音穆以遐畅，沉响幽而若絕，樂操則寒條反榮，哀曼則晨華朝滅，邈漸離之清角，超子野之白雪，然思超梁甫，原登華嶽，路崄悲秦，道難怨蜀，遺逸悼行邁之離，秋風哀年時之速，陵危柱以頡颃，凭哀絃以踯躅，於是數轉難测，聲变無方，或冉弱以飄沉，或頓壮以抑扬，或散角以放羽，或摅徵以騁商。","sortOrder":77},
  {"id":"s_work_nvlt_44_78","chapterId":"ch_work_nvlt_44","text":"晉曹毗箜篌賦曰：嶧陽之桐，殖穎巖摽，清泉润根，女萝被條，爾乃楚班製器，窮妙極巧，龍身鳳形，連翩窈窕，纓以金采，絡以翠藻，其絃則乌號之絲，用應所任，體劲质朗，虛置自吟，於是召倡人，命妙姿，御新肴，酌金罍，發愁吟，引吳妃，湖上飒沓以平雅，前溪藏摧而懷歸。","sortOrder":78},
  {"id":"s_work_nvlt_44_79","chapterId":"ch_work_nvlt_44","text":"宋臨川王劉義慶箜篌賦曰：侯牵化而始造，魯幸奇而後珍，名啟端於雅引，器荷重於吳君，等齊歌以無譬，似秦筝而非群。","sortOrder":79},
  {"id":"s_work_nvlt_44_80","chapterId":"ch_work_nvlt_44","text":"◇琵琶","sortOrder":80},
  {"id":"s_work_nvlt_44_81","chapterId":"ch_work_nvlt_44","text":"《釋名》曰：琵琶本於胡中，馬上所鼓也，推手前曰琵，引却曰琶，因以為名。","sortOrder":81},
  {"id":"s_work_nvlt_44_82","chapterId":"ch_work_nvlt_44","text":"《風俗通》曰：謹按，琵琶近世樂家所作，不知誰作也，長三尺五寸，法天地人與五行也。又四絃象四時也。","sortOrder":82},
  {"id":"s_work_nvlt_44_83","chapterId":"ch_work_nvlt_44","text":"《三辅决錄》曰：遊楚表乞宿衛，拜駙馬都尉，楚不學問，性好遊遨音樂及畜歌者，琵琶筝笛，每行來，將以自隨。","sortOrder":83},
  {"id":"s_work_nvlt_44_84","chapterId":"ch_work_nvlt_44","text":"傅子曰：朱生善彈琵琶，雖伯牙之妙，舞［《太平御覽》五百八十三無舞字。］無以加之。","sortOrder":84},
  {"id":"s_work_nvlt_44_85","chapterId":"ch_work_nvlt_44","text":"《語林》曰：謝镇西著紫羅襦，據胡床，在大市佛圖門樓上，彈琵琶，作大道曲。","sortOrder":85},
  {"id":"s_work_nvlt_44_86","chapterId":"ch_work_nvlt_44","text":"《竹林七賢論》曰：阮鹹善彈琵琶。","sortOrder":86},
  {"id":"s_work_nvlt_44_87","chapterId":"ch_work_nvlt_44","text":"《異苑》曰：南平國嶽，［《太平御覽》五百八十三作兵。］在姑孰，有鬼附之，每占吉凶，辄先索琵琶，隨彈而言事有验，或雲是老鼠所作，名曰靈侯。","sortOrder":87},
  {"id":"s_work_nvlt_44_88","chapterId":"ch_work_nvlt_44","text":"《幽明錄》曰：晉司空桓豁，在荆州，有參軍剪五月五日鸲鹆舌，教令學語，遂無所不名，與人相阌顧，參軍善彈琵琶，鸲鹆每聽移時。","sortOrder":88},
  {"id":"s_work_nvlt_44_89","chapterId":"ch_work_nvlt_44","text":"《世說》曰：桓大司馬曰：謝仁祖，企腳在北牖下彈琵琶，故自有天际意。","sortOrder":89},
  {"id":"s_work_nvlt_44_90","chapterId":"ch_work_nvlt_44","text":"【詩】齊王融詠琵琶詩曰：抱月［原作目，據冯校本改。］如可明，懷風殊复清，絲中傳意緒，花里寄春情，掩抑有奇態，凄锵多好聲，芳袖幸時拂，龍門空自生。","sortOrder":90},
  {"id":"s_work_nvlt_44_91","chapterId":"ch_work_nvlt_44","text":"【賦】晉孫諺［《初學記》十六作該，此訛。］琵琶賦曰：惟嘉桐之奇生，於丹泽之北垠，下脩條而迥回，上糾紛而幹雲，开鍾黃以挺幹，表素质於仓春，然後讬乎公班，妙意橫施，四分六合，廣袤應規，回風臨樂，刻飾流離，絃則岱穀檿絲，篚貢天府，伯奇執軛，杞妻抽緒，大不過宮，細不過羽，清朗紧劲，絕而不茹，伶人鼓焉，景响丰蛇良，操畅骆驿，遊乎風扬，抑按捻［北堂書鈔一百一十作擫，擫下有攝字，此脱。］拰搦摧藏，爾乃叩少宮，騁明光，發下柱，展上按，儀蔡氏之繁絃，放莊公之倍簧，於是酒酣日晚，改為秦聲，壮谅抗愾，土風所生，延年度曲，六彈俱成，絀耶在正，疏密有程，離而不散，滿而不盈，沉而不重，浮而不輕，綿駒遺呕，岱宗梁父，淮南廣陵，郢都激楚，每至曲終歌阕，亂以眾契，王［明本及《初學記》十六王字無。］上下奔鶩，鹿奋猛厲，波騰雨註，飄飛電逝。","sortOrder":91},
  {"id":"s_work_nvlt_44_92","chapterId":"ch_work_nvlt_44","text":"晉成公綏琵琶賦曰：八音之用，誦於典藝，箫韶九奏，物有容製，惟此琵琶，興自末世，爾乃讬巧班爾，妙意橫施，因形造美，洪殺得宜，柄如翠虬之仰首，盤似靈龟之觜{唯角}，臨樂則齊州之丹木，柱則梁山之象犀，〈媲\"女改扌\"〉以玳瑁，格以瑤枝，若夫盤圖合靈，太極形也，三材片合，兩儀生也，分柱列位，歲數成也，回窗華表，日月星也。","sortOrder":92},
  {"id":"s_work_nvlt_44_93","chapterId":"ch_work_nvlt_44","text":"◇筍虡","sortOrder":93},
  {"id":"s_work_nvlt_44_94","chapterId":"ch_work_nvlt_44","text":"《釋名》曰：所以懸鍾者，橫曰筍，筍，峻也，在上高峻也，縱［原作蹤，據冯校本改。］曰虡，虡，舉也，在傍舉筍也。","sortOrder":94},
  {"id":"s_work_nvlt_44_95","chapterId":"ch_work_nvlt_44","text":"《毛詩》曰：設業設虡，崇牙树羽。","sortOrder":95},
  {"id":"s_work_nvlt_44_96","chapterId":"ch_work_nvlt_44","text":"《禮記》曰：夏後氏之龍筍虡，殷之崇牙，周之壁翣。","sortOrder":96},
  {"id":"s_work_nvlt_44_97","chapterId":"ch_work_nvlt_44","text":"鬻子曰：大禹為銘於筍虡，銘言曰：教寡人以道者击鼓，教以義者击鍾，教以事者振铎，語以忧者击磬，語以訟獄者揮鞀。","sortOrder":97},
  {"id":"s_work_nvlt_44_98","chapterId":"ch_work_nvlt_44","text":"《說苑》曰：秦博士對始皇，階下撞千石之鍾，萬石之虡。","sortOrder":98},
  {"id":"s_work_nvlt_44_99","chapterId":"ch_work_nvlt_44","text":"《淮南子》曰：阖闾伐楚，破九龍之鍾虡。","sortOrder":99},
  {"id":"s_work_nvlt_44_100","chapterId":"ch_work_nvlt_44","text":"《東觀漢記》曰：東海王彊，殿［東觀漢記七殿下有設字。］鍾虡之懸。","sortOrder":100},
  {"id":"s_work_nvlt_44_101","chapterId":"ch_work_nvlt_44","text":"《莊子》曰：梓慶削木為鐻，見者驚猶鬼神，魯侯問其術，對曰：臣將為鐻，未嘗敢以耗氣，斋七日，忘吾四支，然後入山林，觀天性區別，見成鐻，然後加手，［鐻似夹鍾也。］","sortOrder":101},
  {"id":"s_work_nvlt_44_102","chapterId":"ch_work_nvlt_44","text":"《離骚》曰：箫鍾兮瑤虡。","sortOrder":102},
  {"id":"s_work_nvlt_44_103","chapterId":"ch_work_nvlt_44","text":"【賦】漢贾誼虡賦曰：牧太平以深志，象巨獸之屈奇，妙彫文以刻鏤，舒循尾之采垂，舉其鋸牙，以左右相指，負大鍾而欲飛。","sortOrder":103},
  {"id":"s_work_nvlt_44_104","chapterId":"ch_work_nvlt_44","text":"【銘】後漢李尤鍾虡銘曰：周因殷禮，損益可知，漢因於周，猶若重規，人因秦器，事有可施，鸿鍾怒虡，物得其宜，聲扬遠聞，文耀委迤。","sortOrder":104},
  {"id":"s_work_nvlt_44_106","chapterId":"ch_work_nvlt_44","text":"《釋名》曰：箫，肅也，其聲肅肅而清也。","sortOrder":106},
  {"id":"s_work_nvlt_44_107","chapterId":"ch_work_nvlt_44","text":"《風俗通》曰：按舜作，其形參差，象鳳翼，十管，長三尺。","sortOrder":107},
  {"id":"s_work_nvlt_44_108","chapterId":"ch_work_nvlt_44","text":"《爾雅》曰：大箫謂之言，小者謂之筊。","sortOrder":108},
  {"id":"s_work_nvlt_44_109","chapterId":"ch_work_nvlt_44","text":"《三禮圖》曰：雅箫長尺四寸，二十四彄，頌箫尺二寸，十六彄。","sortOrder":109},
  {"id":"s_work_nvlt_44_110","chapterId":"ch_work_nvlt_44","text":"《尚書》曰：箫韶九成，鳳皇來儀。","sortOrder":110},
  {"id":"s_work_nvlt_44_111","chapterId":"ch_work_nvlt_44","text":"又曰：既備乃奏，箫管備舉，喤々厥聲，肅雍和鳴。","sortOrder":111},
  {"id":"s_work_nvlt_44_112","chapterId":"ch_work_nvlt_44","text":"《禮記》曰：仲夏之月，命樂師，均管箫。","sortOrder":112},
  {"id":"s_work_nvlt_44_113","chapterId":"ch_work_nvlt_44","text":"《莊子》曰：南郭子綦謂顏成子遊曰：汝聞人籁而未聞地籁，汝聞地籁而未聞天籁，［郭象曰：籁，箫也。］","sortOrder":113},
  {"id":"s_work_nvlt_44_114","chapterId":"ch_work_nvlt_44","text":"《呂氏春秋》曰：客有以吹籁見越王者，上下宮商和，而越王不喜也，或為之野音，而王反悅之，亦有如此者，要在聽之而已。","sortOrder":114},
  {"id":"s_work_nvlt_44_115","chapterId":"ch_work_nvlt_44","text":"《列仙傳》曰：箫史者，秦穆公時人，善吹箫，能致孔雀白鶴，穆公女弄玉好之，公妻焉，一旦隨鳳飛去，故秦樓作鳳女祠，雍宮世有箫聲雲，［事具神仙部。］","sortOrder":115},
  {"id":"s_work_nvlt_44_116","chapterId":"ch_work_nvlt_44","text":"《漢書》曰：元帝多材藝，吹洞箫，自度曲，被歌聲。","sortOrder":116},
  {"id":"s_work_nvlt_44_117","chapterId":"ch_work_nvlt_44","text":"又曰：元帝為太子，體不安，善忘不樂，詔使王褒等之太子宮，讀誦奇文，太子善褒洞箫頌，令後宮讀誦之。","sortOrder":117},
  {"id":"s_work_nvlt_44_118","chapterId":"ch_work_nvlt_44","text":"《史記》曰：周勃常為人吹箫，給丧事。","sortOrder":118},
  {"id":"s_work_nvlt_44_119","chapterId":"ch_work_nvlt_44","text":"蔡邕《月令章句》曰：箫長則濁，短則清，以臈密實其底，而增减之，則和管而成音，定無所复調，當與琴瑟相參。","sortOrder":119},
  {"id":"s_work_nvlt_44_120","chapterId":"ch_work_nvlt_44","text":"傅子曰：馬先生能使木人吹箫，比妙般输墨翟，曰不劣古矣。","sortOrder":120},
  {"id":"s_work_nvlt_44_121","chapterId":"ch_work_nvlt_44","text":"段龟龍《涼州記》曰：呂纂鹹寧三年，胡人發張駿冢，得玉箫。","sortOrder":121},
  {"id":"s_work_nvlt_44_122","chapterId":"ch_work_nvlt_44","text":"《丹陽記》曰：江寧縣南四十里，慈母山，積石臨江，生箫管竹，王褒洞箫賦所稱，即此也，其竹圓緻，異於眾處，自伶倫采竹嶰穀，其後唯此簳見珍，故歷代常給樂府，而俗呼曰鼓吹山。","sortOrder":122},
  {"id":"s_work_nvlt_44_123","chapterId":"ch_work_nvlt_44","text":"潯陽記曰：庐山西南有康王穀。又北嶺城，天欲雨，辄聞鼓角箫笳之聲。","sortOrder":123},
  {"id":"s_work_nvlt_44_124","chapterId":"ch_work_nvlt_44","text":"【詩】梁劉孝儀詠箫詩曰：危聲合鼓吹，絕弄混笙篪，管饒知氣促，叙動覺唇移，仙史安為貴，能令秦女隨。","sortOrder":124},
  {"id":"s_work_nvlt_44_125","chapterId":"ch_work_nvlt_44","text":"【賦】漢王褒洞箫賦曰：原夫箫榦之所生，出於江南之丘墟，洞條畅以罕節。摽敷紛以扶疏，徒觀其傍山仄，則嶇嵚〈山虛〉崎，戲阨綺靡，誠可悲乎其不安也，弥望傥莽，連延曠荡。又足樂乎其敞閒也，讬身軀於厚土，經萬世而不遷，翔鳳萧萧經其末，回江流水溉其山，朝露清泠而陨其侧，玉液浸润而承其根，孤雌寡鵠，娱優乎其下，春禽群嬉，翱翔乎其巔，秋蜩不食，抱朴而長吟，玄猿悲嘯，搜索乎其間，於是般匠施巧，夔襄准法，帶以象牙，掍其會合，其妙聲則清靜厭翳，［音翳。］順叙卑迖，［他戾。］若孝子之事父也，科條譬類，誠應義理，澎濞沆瀣，一何壮士，優柔溫润。又似君子，或留而不行，或行而不留，愺恅烂漫，亡耦失儔，故知音者悲而樂之，不知音者怪而伟之，故其為悲聲，則莫不怆然累欷，撇涕抆淚，其奏懽娱，則莫不憚漫衎凯，阿那｛疒畏}痿者已，以是蟋蟀尺蠖，跂行喘息，魚瞰雞睨，垂喙宛轉，瞪瞢忘食，况乎感陰陽之和，而見風俗之倫哉。","sortOrder":125},
  {"id":"s_work_nvlt_44_127","chapterId":"ch_work_nvlt_44","text":"《釋名》曰：笙，生也，象物貫地而生，以匏為之，故曰匏竽，亦是也，其中空以受簧也。","sortOrder":127},
  {"id":"s_work_nvlt_44_128","chapterId":"ch_work_nvlt_44","text":"《世本》曰：隋作笙也，《爾雅》曰：大笙謂之巢，小者謂之和。","sortOrder":128},
  {"id":"s_work_nvlt_44_129","chapterId":"ch_work_nvlt_44","text":"《說文》曰：舜祠之下，得笙白玉管，笙十三簧，象鳳之身。","sortOrder":129},
  {"id":"s_work_nvlt_44_130","chapterId":"ch_work_nvlt_44","text":"《尚書》曰：笙镛以間，鳥獸蹌蹌。","sortOrder":130},
  {"id":"s_work_nvlt_44_131","chapterId":"ch_work_nvlt_44","text":"《毛詩》曰：笙磬同音。","sortOrder":131},
  {"id":"s_work_nvlt_44_132","chapterId":"ch_work_nvlt_44","text":"《周官》曰：笙師掌教吹笙。","sortOrder":132},
  {"id":"s_work_nvlt_44_133","chapterId":"ch_work_nvlt_44","text":"《禮記》曰：女媧之笙簧。","sortOrder":133},
  {"id":"s_work_nvlt_44_134","chapterId":"ch_work_nvlt_44","text":"《穆天子傳》曰：西王母吟曰：吹笙鼓簧，中心翔翔。","sortOrder":134},
  {"id":"s_work_nvlt_44_135","chapterId":"ch_work_nvlt_44","text":"《尸子》曰：商容觀舞，墨子吹笙，墨子非樂，而於樂有是也。","sortOrder":135},
  {"id":"s_work_nvlt_44_136","chapterId":"ch_work_nvlt_44","text":"《漢武內傳》曰：西王母命侍女董双成，吹雲和之笙。","sortOrder":136},
  {"id":"s_work_nvlt_44_137","chapterId":"ch_work_nvlt_44","text":"《列仙傳》曰：王子乔者，周靈王太子晉也，好吹笙作鳳鳴，遊伊雒間，道士浮丘公接以上嵩山，［事具神仙部。］","sortOrder":137},
  {"id":"s_work_nvlt_44_138","chapterId":"ch_work_nvlt_44","text":"《魏志》曰：文帝令杜夔，於賓客中吹笙鼓琴，夔有難色，遂黜免。","sortOrder":138},
  {"id":"s_work_nvlt_44_139","chapterId":"ch_work_nvlt_44","text":"【詩】梁陆罩詠笙詩曰：管清羅袖拂，响合絳唇吹，含情應節轉，逸態逐聲移，所美周王子，弄羽一參差。","sortOrder":139},
  {"id":"s_work_nvlt_44_140","chapterId":"ch_work_nvlt_44","text":"【賦】晉潘嶽笙賦曰：河汾之寶，有曲沃之懸匏焉，邹魯之珍，有汶陽之孤筱焉，若乃綿蔓紛敷之麗，浸润靈液之滋，固眾作者之所詳，餘可得而略之，徒觀其製器也，則審洪纖，面短長，戾刂生簳，裁熟簧，設宮分羽，經徵列商，基黃鍾以舉韻，望儀鳳以擢形，寫皇翼以插羽，摹鸞音以厲聲，於是乃有始泰終約，前榮後瘁，激憤於今賤，永懷乎故貴，眾滿堂而飲酒，獨向隅而掩淚，援鳴笙而將吹，先嗢哕以理氣，或案衍夷靡，或竦踴剽急，或既往而不返，或已出而复入，徘徊布護，涣衍葺袭，舞既蹈而中輟，節將撫而弗及，輟張女之哀彈，流廣陵之名散，詠園桃之夭夭，歌棗下之纂纂，歌曰：棗下纂纂，朱實離離，宛其落矣，化為枯枝，人生不能行樂，何以虛謚為，爾乃引飛龍，鳴鵾雞，双鸿翔，白鵠飛，子乔輕舉，明君懷歸，荆王喟其長吟，楚妃叹而增悲，新聲变曲，奇韻橫逸，萦纏歌鼓，網羅鍾律，烂熠燿以放艳，鬱蓬勃以氣出，秋風詠於燕路，天光重乎朝日，大不逾宮，細不過羽，唱發章夏，导扬韶武，协和陳宋，混一齊楚，延不逼而遠無携，聲成文而節有叙。","sortOrder":140},
  {"id":"s_work_nvlt_44_141","chapterId":"ch_work_nvlt_44","text":"晉王廙笙賦曰：其製器也，則取不周之竹，曾城之匏，生懸崖之絕嶺，邈隆峰以崇高，延脩頸以亢首，厭瑤口之陆離，舞靈蛟之素鱗，衔明珠於帶垂，弱舌紙薄，鉛錘內藏，合松臈以密际，糅彤丹以發光。","sortOrder":141},
  {"id":"s_work_nvlt_44_142","chapterId":"ch_work_nvlt_44","text":"晉夏侯淳［《初學記》作湛。］笙賦曰：嗟萬物之殊觀，莫比美乎音聲，總眾異以合體，匪求一以取成，雖琴瑟之既麗，猶靡尚於清笙，爾乃采桐竹，翦朱密，摘長松之流肥，鹹崑崙之所出，抑扬噓吸，或〈口劦〉或吹，厭枯［《初學記》作拈。］挹按，同覆互移，初進飛龍，重繼鵾雞，振引合和，如潰如離，若夫纏綿約殺，足使放達者循察，通豫平曠，足使廉規者弃節，冲靈冷澹，足使貪榮者退世，开明爽亮，足使慢惰者進竭，豈眾樂之能倫，邈奇特而殊絕。","sortOrder":142},
  {"id":"s_work_nvlt_44_144","chapterId":"ch_work_nvlt_44","text":"《風俗通》曰：笛，武帝時丘仲所作也，笛，涤也，所以涤邪秽，納之雅正也，長尺四寸，七孔，後有羌笛，見馬融賦。","sortOrder":144},
  {"id":"s_work_nvlt_44_145","chapterId":"ch_work_nvlt_44","text":"傅子曰：列和善吹笛，吳姬之聲，無以加也。","sortOrder":145},
  {"id":"s_work_nvlt_44_146","chapterId":"ch_work_nvlt_44","text":"伏滔蔡邕長笛賦序曰：餘同僚桓子野，有故長笛賦，［世說輕詆篇註，北堂書鈔一百十一賦字無。］傳之耆艾，雲蔡邕之所作也，初邕避難江南，宿於柯亭，柯亭之馆，以竹為椽，仰而眄之曰：良竹也，取以為笛，奇聲獨絕，歷代傳之。","sortOrder":146},
  {"id":"s_work_nvlt_44_147","chapterId":"ch_work_nvlt_44","text":"《廣雅》曰：籥謂之笛，有七孔。","sortOrder":147},
  {"id":"s_work_nvlt_44_148","chapterId":"ch_work_nvlt_44","text":"《魏略》曰：遊楚好音樂，畜笛者，每待［前琵琶篇引三辅决錄作將。］以自隨。","sortOrder":148},
  {"id":"s_work_nvlt_44_149","chapterId":"ch_work_nvlt_44","text":"《世說》曰：王子猷聞桓子野善笛而不識，遇桓於岸上過，舡中客有識之者，雲此是桓野王，使令人與相問，聞君善吹，试為我一奏，桓爾時已貴顯，素聞王名，即便回，下車，踞胡床，為作三調，弄畢便去，客主竟不交言。","sortOrder":149},
  {"id":"s_work_nvlt_44_150","chapterId":"ch_work_nvlt_44","text":"《俗說》曰：宋禕是石崇妓绿珠弟子，有國色，善吹笛，後在晉明帝宮，帝疾患危篤，群臣進諫，請出宋禕，時朝賢悉見，帝曰：卿諸人誰欲得者，眾人無言，阮遙集時為吏部尚書，對曰：原以賜臣，即與之。","sortOrder":150},
  {"id":"s_work_nvlt_44_151","chapterId":"ch_work_nvlt_44","text":"又曰：謝仁祖妾阿妃，有國色，甚善吹笛，謝死，阿妃誓不嫁，郗曇時為北中郎，設權計，遂得阿妃為妾，阿妃終身不與曇言。","sortOrder":151},
  {"id":"s_work_nvlt_44_152","chapterId":"ch_work_nvlt_44","text":"段龟龍《涼州記》曰：呂纂時，胡人發張駿冢，得玉笛。","sortOrder":152},
  {"id":"s_work_nvlt_44_153","chapterId":"ch_work_nvlt_44","text":"《續搜神記》曰：合肥口有一大白舡，覆在水中，雲是曹公白舡，嘗有漁人夜宿，以舡系之，聞筝笛絃節之音，漁人夢人驅遣，雲勿近官妓，此人驚，即移去，相傳雲，曹公載妓舡覆於此，猶存焉。","sortOrder":153},
  {"id":"s_work_nvlt_44_154","chapterId":"ch_work_nvlt_44","text":"《幽明錄》曰：永嘉中，太山民巢氏，先為相縣令，居在晉陵，家婢采薪，忽有一人追隨婢還家，不使人見，與婢宴飲，辄吹笛而歌，歌雲，閒夜寂已清，長笛亮且鳴，若欲知我者，姓郭字長生。","sortOrder":154},
  {"id":"s_work_nvlt_44_155","chapterId":"ch_work_nvlt_44","text":"【賦】楚宋玉笛賦曰：餘嘗觀於衡山之陽，見奇筱異幹，罕節簡枝之丛生也，其處旁塘千仞，絕谿陵阜，隆崛萬丈，磐石双起，丹水涌其左，醴泉流其右，師曠將為陽春北鄭白雪之曲，取其雄焉，宋意將送荆卿於易水之上，得其雌焉，於是天旋少陰，白日西靡，命嚴春，使午子，延長鵄，奋玉手，摛朱唇，曜皓齒，赪顏臻，玉貌起，吟清商，起流徵。","sortOrder":155},
  {"id":"s_work_nvlt_44_156","chapterId":"ch_work_nvlt_44","text":"後漢馬融長笛賦曰：融既博覽典雅，精該術數。又性好音律，能鼓琴吹笛，為督郵，無留事，獨臥郿縣平陽邬中，有雒客舍逆旅，吹笛，融去京師逾年，暫聞甚悲樂之，作長笛賦，其辭曰：惟籦籠之奇生兮，於終南之陰崖，讬九成之孤岑，臨萬仞之石溪，是以間介無蹊，人跡罕到，猿蜼晝吟，鼯鼠夜叫，於是放臣逐子，弃妾離友，攒乎下風，收精註耳，夔襄比律，子野协呂，十二畢具，黃鍾為主，詳觀夫曲胤之繁會丛雜，何其富也，紛葩烂熳，誠可喜也，波散廣衍，實可異也，律呂既和，哀聲五降，曲終阕盡，餘絃更興，繁手累發，密擳叠董，［文選十八作重。］上擬法於韶箾南籥，中取度於白雪渌水，下采製於延露巴人，於時也，綿駒吞聲，伯牙毀絃，瓠巴聑［下挟反。］柱，磬襄弛懸，近世双笛從羌起，羌人伐竹未及已，龍鳴水中不見已，截竹吹之聲相似，易京君明識音律，故本四孔加以一，君明所加孔後出，是謂商聲五音畢。","sortOrder":156},
  {"id":"s_work_nvlt_44_158","chapterId":"ch_work_nvlt_44","text":"蔡琰別傳曰：琰，字文姬，先適河東衛仲道，夫亡無子，歸寧於家，漢末大亂，為胡騎所獲，在左賢王部伍中，春月登胡殿，感笳之音，作詩言志曰：胡笳動兮邊馬鳴，孤雁歸兮聲嘤嘤。","sortOrder":158},
  {"id":"s_work_nvlt_44_159","chapterId":"ch_work_nvlt_44","text":"曹嘉之《晉書》曰：劉畴曾避亂坞壁，贾胡百數，欲害之，畴無懼色，援笳而吹之，為出塞之聲，動其遊客之思，於是群胡皆倚泣而去。","sortOrder":159},
  {"id":"s_work_nvlt_44_160","chapterId":"ch_work_nvlt_44","text":"《世說》曰：劉越石為胡騎所围數重，城中窘迫無計，劉始夕乘月，登樓清嘯，胡賊聞之，皆凄然長叹，中夜次奏胡笳，賊皆流涕，人有懷土之切，向晓又吹，賊併起围奔走，或雲是劉道真。","sortOrder":160},
  {"id":"s_work_nvlt_44_161","chapterId":"ch_work_nvlt_44","text":"【賦】魏杜挚笳賦曰：唯葭芦之為物，谅絜劲之自然，讬妙體於阿泽，歷百代而不遷，於是秋節既至，百物具成，嚴霜告殺，草木殒零，賓鳥鼓翼，蟋蟀悲鳴，羁旅之士，感時用情，乃命狄人，操笳扬清，吹東角，動南徵，清羽發，濁商起，刚柔待用，五音迭進，倏爾却轉，忽焉前引，或缊缊以和怿，或凄凄以燋殺，或漂淫以輕浮，或遲重以沉滯。","sortOrder":161},
  {"id":"s_work_nvlt_44_162","chapterId":"ch_work_nvlt_44","text":"西晉孫楚笳賦曰：衔長葭以汎吹，噭啾啾之哀聲，奏胡馬之悲思，詠北狄之遐征，順穀風以撫節，飄响乎天庭，徐疾從宜，音引代起，叩角動商，鳴羽發徵，若夫廣陵散吟，三節白纻，太山長曲，哀及梁父，似鸿雁之將雏，乃群翔於河渚。","sortOrder":162},
  {"id":"s_work_nvlt_44_163","chapterId":"ch_work_nvlt_44","text":"晉夏侯湛夜聽笳賦曰：越鳥恋乎南枝，胡馬懷夫朔風，惟人情之有思，乃否滯而發中，南闾兮拊掌，北阎兮鳴笳，鳴笳兮协節，分唱兮相和，相和兮哀諧，惨激畅兮清哀，奏烽燧之初驚，展從繇之叹乖，伸弃兮更纏，遷調兮故韻，披涼州之妙參，扌製飛龍之奇引，垂幽蘭之遊响，來楚妃之絕叹，放鵾雞之弄音，散白雪之清变。","sortOrder":163},
  {"id":"s_work_nvlt_44_164","chapterId":"ch_work_nvlt_44","text":"《藝文類聚》　唐·欧陽詢","sortOrder":164},
  {"id":"s_work_nvlt_45_1","chapterId":"ch_work_nvlt_45","text":"卷四十五職官部一","sortOrder":1},
  {"id":"s_work_nvlt_45_2","chapterId":"ch_work_nvlt_45","text":"○總載職官諸王相國丞相冢宰","sortOrder":2},
  {"id":"s_work_nvlt_45_3","chapterId":"ch_work_nvlt_45","text":"◇總載職官","sortOrder":3},
  {"id":"s_work_nvlt_45_4","chapterId":"ch_work_nvlt_45","text":"《尚書》曰：成王既黜殷命，滅淮夷，歸於宗周，董正治官，曰唐虞稽古，建官惟百，內有百揆四嶽，外有州牧侯伯。","sortOrder":4},
  {"id":"s_work_nvlt_45_5","chapterId":"ch_work_nvlt_45","text":"《禮記》曰：有虞氏官五十，夏後氏官百，殷二百，周三百，天子立六官，三公九卿，二十七大夫，八十一元士，以聽天下之外治，以明章天下之男教。","sortOrder":5},
  {"id":"s_work_nvlt_45_6","chapterId":"ch_work_nvlt_45","text":"《大戴禮》曰：古之卿政以治天下者，冢宰之官以成道，司徒之官以成德，宗伯之官以成仁，司馬之官以成禮，司寇之官以成義，司空之官以成智。","sortOrder":6},
  {"id":"s_work_nvlt_45_7","chapterId":"ch_work_nvlt_45","text":"《尚書大傳》曰：古者天子三公，每一公三卿佐之，每一卿三大夫佐之，每一大夫三元士佐之。","sortOrder":7},
  {"id":"s_work_nvlt_45_8","chapterId":"ch_work_nvlt_45","text":"贾誼《新書》曰：王者官人六等，一曰師，二曰友，三曰大臣，四曰左右，五曰侍御，六曰厮役，智足以為源泉，行足以為表儀，謂之師，智足以為砻砺，行足以為辅助，謂之友，智足以謀國事，行足以為民率，謂之三［《太平御覽》二百零三無三字。］大臣也，修身正行，不〈僣中\"日改心\"〉於乡曲，左右也，事君不敢有二心，侍御者也，唯言之聽，以事君者，厮役也。","sortOrder":8},
  {"id":"s_work_nvlt_45_9","chapterId":"ch_work_nvlt_45","text":"《說苑》曰：應侯與贾子坐，聞有鼓琴之聲，應侯曰：今之琴一何悲也，贾子曰：夫張急調下，故使之悲爾，張急者，良材也，調下者，官卑也，取夫良材而卑官之，安能無悲乎，應侯曰：善。","sortOrder":9},
  {"id":"s_work_nvlt_45_10","chapterId":"ch_work_nvlt_45","text":"《漢書》曰：永元三年，上微行，始出，北至池陽，西至黃山，南獵長扬，東遊宜春，微行常用飲酎八九月中，與侍中常侍武騎及待詔隴西北地良家子能騎射者，期諸殿門，故有期門之號，自此始也。","sortOrder":10},
  {"id":"s_work_nvlt_45_11","chapterId":"ch_work_nvlt_45","text":"《東觀漢記》曰：更始所置官，多群小，長安謂之語曰：竈下養，中郎將，烂羊胃，騎都尉，烂羊頭，關內侯。","sortOrder":11},
  {"id":"s_work_nvlt_45_12","chapterId":"ch_work_nvlt_45","text":"《漢舊儀》曰：古法，聖猶试，故令丞相設四科之辟，以博異德，第一科曰：德行高妙，志節清白，二科曰：學道修行，經中博士，三科曰：明晓法令，足以决疑，能案章覆問，文中御史，四科曰：刚毅多略，遭事不惑，明足以照奸，勇足以决斷，才任三辅剧令，皆试以其能，然後官之，第一科補西曹南閤祭酒，二科補議曹，三科補四辭八奏，四科補［漢舊儀補下有賊字，此脱。］决。","sortOrder":12},
  {"id":"s_work_nvlt_45_13","chapterId":"ch_work_nvlt_45","text":"李重雜奏議曰：古之聖王，建官垂製，所以體國經治，而功在簡易，自帝王而下，世有增損，舜命九官，周分六職，秦采古製，漢仍秦舊，倚丞相，任九卿，雖置五曹尚書，始於封奏，以宣外內，事任尚輕，而郡守牧民之官重，故漢宣稱所與為治，唯良二千石，其有殊勋者，辄玺書勉励，或賜爵進秩，禮遇丰厚，得治大體，所以追蹤三代也，乃至東京，雖漸優顯，然令仆射出為郡守，鍾離意黃香胡廣是也，郡守入為三公，虞延第五倫桓虞鮑昱是也。","sortOrder":13},
  {"id":"s_work_nvlt_45_14","chapterId":"ch_work_nvlt_45","text":"楊泉《物理論》曰：吏者理也，所以理萬機，平百揆也，武士宰民，猶使狼牧羊，鷹養雏也，是以人主務在審官擇人。","sortOrder":14},
  {"id":"s_work_nvlt_45_15","chapterId":"ch_work_nvlt_45","text":"【詩】魏應璩雜詩，散騎常師友，朋夕進規獻，侍中主喉舌，萬機無不亂，尚書統庶事，官人乘法憲，彤管弭納言，貂璫表武弁，出入承明庐，車服一何煥，三寺齊榮秩，百僚所瞻原。","sortOrder":15},
  {"id":"s_work_nvlt_45_16","chapterId":"ch_work_nvlt_45","text":"【頌】晉陆機漢高祖功臣頌曰：茫茫宇宙，上惨［《文選》四十七作墋。］下黷，波振四海，尘飛五嶽，九服徘徊，三靈改卜，赫矣高祖，肇載天祿，彤雲晝聚，素靈夜哭，萬邦宅心，駿民效足，堂堂萧公，主跡是因，綢缪睿後，無實惟人，外濟六師，內撫三秦，拔奇夷難，邁德振民，名蓋群後，是謂宗臣，平陽樂道，在变則通，爰深爰默，有此武功，長驅河朔，電击襄東，协策淮陰，亚跡萧公，文成作師，通幽洞冥，永言配命，因心則靈，窮神觀化，望景扬清，鬼無隱謨，物無遁形，運筹固陵，定策東袭，三王從風，五侯允集，霸楚雲丧，皇漢凯入，曲逆宏達，好謀能深，遊情杳莫，神跡是尋，奇謀六奋，嘉慮百回，規主於足，離項於懷，韓王窘執，胡馬洞开，灼灼淮陰，靈武冠世，策出無方，思入神契，有险必夷，摧刚則脆，肇謨漢湄，還定渭表，濟河夷魏，登山滅趙，威掠火烈，势逾風扫，拾代如遺，偃齊猶草，彭越觀世，韜跡隱光，威凌楚城，质委漢王，靖難河濟，即宮舊梁，烈烈黥布，睆睆其眄，名冠強楚，鋒猶駭電，肇彼枭風，翩為我扇，天命方集，王於東夏，矯矯三雄，至於垓下，元凶既夷，寵祿來假，張耳之賢，有聲梁魏，俯思舊恩，仰察五緯，脱跡违禮，披榛來媚，改策西秦，執辱北冀，王信韓孽，拓土开疆，我圖爾戎，越遷晉陽，盧綰自微，婉恋我皇，跨功逾德，祚爾暉章，吳芮之王，祚由梅鋗，功微势弱，世載忠賢，肅肅荆王，董我三軍，圖掌四方，殷荐其勋，庸親祚勞，舊楚是分，安國违親，悠悠我思，依依哲母，既明且仁，引身伏劍，永言固之，主雲興亡，末命是期，絳侯质木，多略寡言，曾是忠勇，惟帝攸叹，雲驚靈丘，景逸上蘭，平代擒豨，奄有燕韓，寧亂以武，毙呂以權，實惟太尉，劉宗以安，舞陽道迎，延帝幽藪，宣力王室，匪惟厥武，總幹鸿門，披闼帝宇，耸顏誚項，掩淚寤主，百王之極，舊事靡存，稷嗣製禮，下肅上尊，穆穆帝典，乃其盈門，風希三代，憲流後崑，紀信誑項，轺軒是乘，身與煙銷，名與風興，形可以暴，志不可凌。","sortOrder":16},
  {"id":"s_work_nvlt_45_17","chapterId":"ch_work_nvlt_45","text":"【贊】後漢班固公孫弘贊曰：公孫弘卜式倪宽，皆以鸿漸之翼，困於燕爵，遠跡羊豕之間，非遇其時，焉能致此位乎，是時漢興六十餘載，上方欲用文武，求之如弗及，始以蒲輪迎枚生，見主父而叹息，群士慕向，異人併出，卜式拔於刍牧，弘羊擢於贾竖，衛青奋於奴仆，日磾出於降虜，斯亦曩時版筑飯牛之朋也，漢之得人，於茲為盛，儒雅則公孫弘董仲舒倪宽，篤行則石建石慶，质直則汲黯卜式，推賢則韓安國鄭當時，定令則趙禹張湯，文章則司馬遷相如，滑稽則東方朔枚皋，應對則嚴助朱買臣，歷數則唐都洛下閎，协律則李延年，運筹則桑弘羊，奉使則張騫蘇武，將帥則衛青霍去病，受遺則霍光金日磾，其餘不可勝紀，是以興造功業，製度遺文，後世莫及，孝宣承統，纂修洪業，亦講論六藝，招選茂異，而萧望之梁丘贺夏侯勝韦玄成嚴彭祖尹更始，以儒術進，劉向王褒，以文章顯，將相則張安世趙充國魏相邴吉於定國杜延年，治民則黃霸王成龚遂鄭弘邵信臣韓延寿尹翁歸趙廣漢嚴延年張敞之屬，皆有功績，見述後世，參其名臣，亦其次也。","sortOrder":17},
  {"id":"s_work_nvlt_45_18","chapterId":"ch_work_nvlt_45","text":"晉袁宏三國名臣贊曰：赫赫三雄，併回乾軸，競收杞梓，爭采松竹，鳳不及栖，龍不暇伏，英英文若，靈鑒洞照，應变知微，探赜索要，日月在躬，隱之弥曜，公達潛朗，思同蓍蔡，運用無功，勋攝群會，邈哉崔生，體正心直，天骨疏朗，牆岸高嶷，忠存軌跡，義形風色，思树芳蘭，翦除荆棘，景山恢誕，韻與道合，形器不存，方寸海納，和而不同，通而不雜，過醉亡辭，在醒貽答，長文通雅，義格終始，思戴元首，擬伊同齒，嘉謨肆庭，谠言盈耳，深哉泰初，宇量高雅，器范自然，標准無假，全由身冥，跡汙必伪，處死匪難，理存則易，六合徒廣，容身靡寄，堂堂孔明，基宇宏邈，器同生人，獨禀先覺，標榜風流，遠朋管樂，士元弘長，雅性自融，崇善愛物，觀始知終，丧亂備矣，勝涂未隆，先生標之，振起清風，公琰植根，不忘忠敬，豈曰模擬，實在雅性，推賢恭己，久而可敬，公瑾英達，朗心獨見，披草求君，定交一面，桓桓魏武，外讬霸跡，志掩衡霍，恃戰忘敵，卓卓若人，曜奇赤壁，三光參分，宇宙暫隔，子布擅名，遭世方扰，撫翼桑梓，息肩江表，王略威夷，吳魏同寶，遂贊宏謨，匡比霸道，昂昂子敬，拔跡草萊，荷簷吐奇，乃構雲台，子瑜長者，體性純懿，諫而不犯，正而不毀，將命闕庭，退忘私位，伯言謇謇，以道佐世，出能勤功，入亦獻替，謀翊社稷，解紛挫銳，元叹穆遠，神和形捡，如彼白珪，质無尘點，清不增絜，濁不加染，仲翔高亮，性不和物，好是不群，折而不屈，屢摧逆鱗，直道受黜，叹過孫陽，放同贾屈。","sortOrder":18},
  {"id":"s_work_nvlt_45_19","chapterId":"ch_work_nvlt_45","text":"【頌】晉張子併楊四公頌［明本在陆機漢高祖功臣頌後。］曰：瓘瓘西嶽，峻極太清，降神挺賢，實有景靈，靈何為四，四楊是丁，佐我大侯，俾作韓貞，明明在上，不顯其身，帝時畴咨，本道求真，佥曰於公，溫故知新，宜保宜傳，克贊典墳，昔在阿衡，左右商王，有周文武，股肱旦望，我漢楊氏，代作棟梁，蹇蹇匪躬，惟國之綱，綱弛复整，政無亂荒，功假皇穹，率土以康，心盡於朝，終然允臧，伊德之辅，是乃毛羽，匪哲匪賢，孰雲敢舉，楊氏蹈之，為軌為武，軌武伊何，盡啟基緒，穆穆天子，以為心膂，於萬斯年，克昌厥後。","sortOrder":19},
  {"id":"s_work_nvlt_45_20","chapterId":"ch_work_nvlt_45","text":"◇諸王","sortOrder":20},
  {"id":"s_work_nvlt_45_21","chapterId":"ch_work_nvlt_45","text":"漢書百官表曰：諸侯王高帝初置，金玺組綬。","sortOrder":21},
  {"id":"s_work_nvlt_45_22","chapterId":"ch_work_nvlt_45","text":"蔡邕獨斷，漢製，皇子封為王，其實諸侯也，周末諸侯或稱王，而漢天子自以皇帝為稱，故以王號加之，總名諸侯王，法律家皆曰列侯，天子太社，以五色土為壇，皇子封為王者，受天子太社之土，以所封之方色，東方受青，南方受赤，他如其方色，藉以白茅，歸國以立社，故謂之茅土。","sortOrder":22},
  {"id":"s_work_nvlt_45_23","chapterId":"ch_work_nvlt_45","text":"《贾誼書》曰：高帝瓜分天下，以王有功之臣，反者如猬毛而起，高皇帝以為不可製，故削去不義諸侯，空其國，擇良日，立諸子洛陽上東門外，諸子畢王，而天下乃安。","sortOrder":23},
  {"id":"s_work_nvlt_45_24","chapterId":"ch_work_nvlt_45","text":"《漢書》曰：楚元王交，高帝弟，自帝即位，交與盧綰，常侍上，出入臥內，傳語言諸內事隱謀，文帝尊寵元王子，爵比皇子。","sortOrder":24},
  {"id":"s_work_nvlt_45_25","chapterId":"ch_work_nvlt_45","text":"又曰：初楚元王敬禮申公等，穆生不嗜酒，元王每置酒，嘗為穆生設醴。","sortOrder":25},
  {"id":"s_work_nvlt_45_26","chapterId":"ch_work_nvlt_45","text":"又，齊悼惠王肥，高帝子，食七十餘城，諸民能齊言者，皆與齊。","sortOrder":26},
  {"id":"s_work_nvlt_45_27","chapterId":"ch_work_nvlt_45","text":"又，梁孝王，文帝窦皇後少子，愛之，孝王筑東苑，方三百里，得賜天子旌旗，從千乘萬騎，出稱警，入言跸，擬於天子，招延四方豪杰，自山東遊士，莫敢不至。","sortOrder":27},
  {"id":"s_work_nvlt_45_28","chapterId":"ch_work_nvlt_45","text":"又，河間獻王德，景帝子，修學好古，從民得善書，必為好寫與之，留其真，如金帛賜以招之，由是四方道術之人，不遠千里，或有先祖舊書，多奉以奏獻王者，故得書與漢等，被服儒術，造次必於儒者，武帝時，獻王來朝，獻雅樂，對三雍宮及詔策所問三十餘事，其對推道術而言，得事之中。","sortOrder":28},
  {"id":"s_work_nvlt_45_29","chapterId":"ch_work_nvlt_45","text":"又，魯共王，景帝子，好治宮室苑囿狗馬，王初坏孔子舊宅，以廣其居，聞鍾磬琴瑟之聲，遂不敢坏，於其壁中，得古文經傳。","sortOrder":29},
  {"id":"s_work_nvlt_45_30","chapterId":"ch_work_nvlt_45","text":"又，淮南王安，為人好書鼓瑟，不喜弋獵狗馬馳騁，亦欲以行陰德，拊循百姓，招致賓客方術之士數千人，作為內書三十一篇，外書甚眾。又有中篇八卷，言神仙黃白之術。","sortOrder":30},
  {"id":"s_work_nvlt_45_31","chapterId":"ch_work_nvlt_45","text":"又，淮陽憲王钦，宣帝子，好經書法律，聰達有才，帝甚愛之，數嗟叹憲王曰：真我子也。","sortOrder":31},
  {"id":"s_work_nvlt_45_32","chapterId":"ch_work_nvlt_45","text":"《東觀漢記》曰：東平王蒼，少有孝友之质，宽仁弘雅，帝即位，詔以為驃騎將軍，位在三公上，四年，蒼上疏原朝，上以王觸寒涉道，使中謁者賜乘舆豹裘，蒼到洛陽，使鸿臚持節郊迎，引入，不在贊拜之位，升殿乃拜，上親答拜，諸王歸國，上特留蒼，八月飲酎畢，大鸿臚奏遣蒼發，上親臨送流涕，賞賜以亿萬數。","sortOrder":32},
  {"id":"s_work_nvlt_45_33","chapterId":"ch_work_nvlt_45","text":"又，明帝詔書示諸國曰：詔問東平王蒼，處家何等最樂，王對曰：為善最樂，帝曰：其言甚大，副其腰腹，蒼美鬢髯，腰帶八赤二寸。","sortOrder":33},
  {"id":"s_work_nvlt_45_34","chapterId":"ch_work_nvlt_45","text":"又，北海靖王興，每朝廷有異政，京師雨泽，秋稼好丑，辄驿馬下興，其見親重如此。","sortOrder":34},
  {"id":"s_work_nvlt_45_35","chapterId":"ch_work_nvlt_45","text":"又，廣平鉅鹿樂成王在邸，入問起居，車馬鞍勒皆純黑，無金銀采飾，馬不逾六尺，於是以白太後，即賜錢各五百萬。","sortOrder":35},
  {"id":"s_work_nvlt_45_36","chapterId":"ch_work_nvlt_45","text":"《魏志》曰：邓哀王冲，字蒼舒，少聰察岐嶷，生五六歲，智意所及，有若成人，孫權曾致巨象，太祖欲知其斤重，訪之群下，鹹莫能出其理，冲曰：置象大舡之上，而刻其所至，稱物所以載之，則斤可知矣，太祖大悅，即施行焉，時軍國多事，用刑嚴重，太祖馬鞍在库，而為鼠所齧，库吏懼必死，冲謂曰：待三日中，然後自歸，冲於是以刀穿单衣，如鼠齧者，谬為失意，貌有愁色，太祖問之，冲對曰：世俗以為鼠齧衣者，其生［《太平御覽》九百十一作主。］不吉，今单衣見齧，是以忧戚，太祖曰：此妄言爾，無所苦也，俄而库吏以齧鞍聞，太祖大笑曰：兒衣在侧尚齧，况鞍懸柱乎，一無所問。","sortOrder":36},
  {"id":"s_work_nvlt_45_37","chapterId":"ch_work_nvlt_45","text":"又曰：中山恭王袞，少好學，生十餘歲，能屬文，每讀書，文學左右，常恐以精力為患，數諫止之，然性所樂，不能废也，文學防辅相與言曰：受詔察公，舉错有過，當奏，及善，亦宜以聞，遂共表稱，陳袞美，袞聞之大驚，责讓文學曰：修身自守，常人之行耳，而諸君乃以上聞，是適所以增其負累也。","sortOrder":37},
  {"id":"s_work_nvlt_45_38","chapterId":"ch_work_nvlt_45","text":"又，任成［《太平御覽》一百五十一作城。］威王彰，字子文，少善射，御力過人，手格猛獸，不避险阻，數從征伐，志意慷慨，太祖常折之曰：汝不念讀書，慕聖道，而好乘馬击劍，此一夫之用，何足貴也，彰謂左右曰：大丈夫一為衛霍，將十萬騎，馳沙漠，驅戎狄，立功建號爾，何能作博士耶。","sortOrder":38},
  {"id":"s_work_nvlt_45_39","chapterId":"ch_work_nvlt_45","text":"又，陳思王植，字子建，年十餘歲，誦讀詩論及辭賦數十萬言，能屬文，太祖常视其文，謂植曰：汝倩人爾，植跪曰：言出為論，下筆成章，頗［太平御覽一百五十一作顧。］當面试，奈何倩人，時鄴銅爵台新成，太祖悉將諸子登台，使各為賦，植援筆立成，可觀，太祖甚異之。","sortOrder":39},
  {"id":"s_work_nvlt_45_40","chapterId":"ch_work_nvlt_45","text":"王隱《晉書》曰：齊王攸，學不倦，借人書，皆為治護時還，有水旱，則出租秩加賦，以赈國人，須丰年，乃收入本直，太康三年，詔攸當出方嶽，遂撫其國，加都督青州，增封濟南郡，德［《太平御覽》一百五十一晉書作備。］物典策，軒懸之樂，六佾之舞，賜金鉞朝車乘舆之副。","sortOrder":40},
  {"id":"s_work_nvlt_45_41","chapterId":"ch_work_nvlt_45","text":"又，安平獻王孚，世祖受禪為太宰，四年正會，上見太宰，身執子孫之禮，舆車上殿，上於阼階下迎拜，王既坐，上又親奉上寿，孚雖見尊寵，而常有戚容，獻王一門三世，同時十人封王，二人世子父，位極人臣，子孫鹹居大官，出則旌旗節鉞，入則貂蝉袞冕，自公族之寵，未始有也。","sortOrder":41},
  {"id":"s_work_nvlt_45_42","chapterId":"ch_work_nvlt_45","text":"晉百官表曰：王古號也，夏殷周稱王，金玺龟紐，細纁朱綬，五時朝服，遠遊冠，佩山玄玉。","sortOrder":42},
  {"id":"s_work_nvlt_45_43","chapterId":"ch_work_nvlt_45","text":"沈約《宋書》曰：衡陽王義季，為荆州刺史，先是臨川王義慶在任，巴蜀亂扰，師旅應接，府库空虛，義季躬行節俭，蓄财省用，數年間，還复充實，队主續丰，母老家貧，無以充養，遂斷不食肉，義季哀其志，給丰每月白米二斛，錢一千，併製丰啖肉，義季素拙書，上聽使餘人書啟事，唯自署名而已，素嗜酒，自彭城王義康废，遂為長夜之飲，略無少醒日，太祖累加詰责，義季引愆陳謝，上詔報誡語，終不改，以至於終，二十一年。","sortOrder":43},
  {"id":"s_work_nvlt_45_44","chapterId":"ch_work_nvlt_45","text":"又，始平孝敬王子鸞，字季羽，孝武帝第八子也，母殷淑儀，寵傾後宮，子鸞冠愛諸子，凡為上所聘遇者，莫不入子鸞府國，及為南徐州。又割吳郡以屬之。","sortOrder":44},
  {"id":"s_work_nvlt_45_45","chapterId":"ch_work_nvlt_45","text":"又，建平宣簡王宏，字休度，文帝第七子也，少而閒素，篤好文籍，太祖寵愛殊常，為立第於雞籠山，盡山水之美，建平國高他國一階。","sortOrder":45},
  {"id":"s_work_nvlt_45_46","chapterId":"ch_work_nvlt_45","text":"【賦】魏夏侯玄皇胤賦曰：覽二儀之上禮，本人倫之大紀，道莫隆於後辟，統莫泰於宗祀，伊皇衢之光赫，享乾祗之元祉，在太和之五載，肇皇胤之盛始，時惟孟秋，和氣淑清，良辰既啟，皇子誕生，爾乃發恺悌之明詔，振隆恩之丰沛，殊惠洽乎黎民，崇施畅於無外，爵群兆以布德，赦殊死以崇仁，黔首詠而齊樂，原皇祚之日新。","sortOrder":46},
  {"id":"s_work_nvlt_45_47","chapterId":"ch_work_nvlt_45","text":"【頌】陳王曹植皇太子頌曰：於我皇後，懿章前志，克慕二皇，三靈昭事，祗肅郊廟，明德敬惠，陽和積吉，鍾天之釐，嘉月令辰，篤生聖嗣，慶由一人，萬國作喜，喁喁萬國，岌岌群生，禀命我後，綏之則榮，長為臣妾，終天之經，仁聖弈世，永載明明，同年上帝，休祥淑貞，藩臣作頌，光流德聲，吁嗟卿士，祗承予聽。","sortOrder":47},
  {"id":"s_work_nvlt_45_48","chapterId":"ch_work_nvlt_45","text":"【碑】梁沈約齊司徒安陆昭王碑曰：稷契身佐唐虞，功大於天地，商武姬文，所以膺圖受箓，萧曹扶翼漢祖，滅秦項以寧亂，魏氏時乘於前，皇齊握符於後，靈源與積石爭流，神基與極天比峻，公含辰象之秀德，體河嶽之靈，［文選五十九靈上有上字。］氣蘊風雲，身負日月，姑蘇奧［《文選》五十九奧下有壤字。］，服［《文選》服上有全趙之袨四字。］丛台，方此為劣，臨淄之地，揮汗成雨，曾何足稱，乃鸿騫奋［《文選》作舊。］吳，作守東楚，夏首荡［《文選》作藩。］要，任重推轂，襟帶中流，地殷江漢，南接衡巫，風雲之俗千里，西通郾邓，水陆之涂三千，是惟形勝，阃外莫先，建麾作牧，明德攸存，以戎羯窥窬，伺我邊隙，北風未起，馬首便則南向，塞草未衰，嚴城於焉早閉，惠至以奉上，明謙以接下，撫僚庶盡盛德之容，交士林忘公侯之貴，虛懷博納，幽闡洞开，宴語談笑，情澜不竭，凡我僚屬，均哀共戚，怨天德之無厚，痛崇陰之不留，所以克卜思播遺尘，［《文選》作思所以克播遺尘，此有倒衍。］敞［○《文選》作蔽。］之穹壤，天命玄鳥，降而生商，是开金運，祚始玉筐，三仁雲［《文選》作去。］殷，五曜入房，亦白其馬，服襄周王，惠露霑吳，仁風扇越，涉夏逾漢，政成期月。","sortOrder":48},
  {"id":"s_work_nvlt_45_49","chapterId":"ch_work_nvlt_45","text":"北齊邢子才廣平王碑文曰：公分氣氤氲，禀靈昭晉，基構輪奐，源流濬遠，積石莫之方，委水不能喻，山渎效神，辰昴降德，自天攸縱，鬱為時宗，牆宇淹曠，標格秀遠，道亚生知，德均殆庶，日月在躬，水鏡被物，望青松而比秀，幹白雲而上征，侍講金華，參遊銅雀，出陪芝蓋，入奉桂室，充會友之選，當拾遺之舉，發言為論，受詔成文，碧雞自口，靈蛇在握，方見建安之體，复聞正始之音，公年方弱冠，而位居寮右，道被生民，惠漸萬物，鬱為雅俗之表，瓘成社稷之镇，公孫聲動天下，已非其倫，管子光照鄰國，孰雲能擬，方謂膺茲多福，降此永年，奪摶風之逸羽，窮送日之遠路，同歧山之嘉會，陪岱宗之盛禮，而群飛在辰，橫流具及，山崩川斗，星霣日銷，崑嶽既毀，玉石俱燼，蘭挺則芬，玉生則润，泱泱萬源，落落千仞，我有徽猷，金聲玉振，志猶學海，業比登山，踟蹰緹袞，絳帳韦編，尋微啟奧，敷理入玄，天地或終，山河匪寿，昔曰先民，誰堪長久，立言立事，貴之身後，式銘景行，是為不朽。","sortOrder":49},
  {"id":"s_work_nvlt_45_50","chapterId":"ch_work_nvlt_45","text":"【墓志】齊王融豫章文獻王墓志銘曰：領袖傾淪，人綱弛没，半嶽摧峰，中河墜月，眷然晓隧，如何夜台，鯨驂惋慕，葆吹徘徊，千秋萬祀，顧有餘哀。","sortOrder":50},
  {"id":"s_work_nvlt_45_51","chapterId":"ch_work_nvlt_45","text":"又齊謝朓鬱林王墓銘曰：绿車旖旎，翠蕤奄映，癸貳戲良，臨祧弛盛，毀德歸桐，弃尊君鄭。","sortOrder":51},
  {"id":"s_work_nvlt_45_52","chapterId":"ch_work_nvlt_45","text":"又齊海陵王墓志銘曰：景祚雲及，多難攸啟，載驅軨轄，高辟代邸，西光已謝，東龟又良，龍纛夕俨，葆挽晨锵，風搖草色，月照松光，春秋非我，晓夜何長。","sortOrder":52},
  {"id":"s_work_nvlt_45_53","chapterId":"ch_work_nvlt_45","text":"梁簡文安成蕃王墓銘曰：許氏猶龍，荀家鳴鶴，豈如宗子，分聯華萼，對策雲台，觀書麟閣，官美登朝，文高入洛，得意琴書，忘言丘壑。","sortOrder":53},
  {"id":"s_work_nvlt_45_54","chapterId":"ch_work_nvlt_45","text":"梁任昉撫軍桂陽王墓志銘曰：於昭帝緒，擅美前王，绿圖丹紀，金簡玉筐，世載台鼎，地居魯衛，沛易且傳，楚詩將說，桐圭誰戲，甘棠何憩。","sortOrder":54},
  {"id":"s_work_nvlt_45_55","chapterId":"ch_work_nvlt_45","text":"梁沈約丞相長沙宣武王墓志銘曰：山嶽镇地，日月麗天，鄰幾者庶，亚極稱賢，瓘瓘哲人，寔惟天縱，德基內美，功成日用，亦既東轅，實拯朝難，迅鋒雷駭，霜戈電斷，震主必危，功高不賞，哀動上霄，痛銘玄壤，聖武爰發，後恥申冤，大禮空備，幽駕莫援。","sortOrder":55},
  {"id":"s_work_nvlt_45_56","chapterId":"ch_work_nvlt_45","text":"陳徐陵司空河東康簡王墓志曰：夫聖人至德，天道福謙，大哉尧舜，貽慶長遠，明兩之盛，中陽纂於豢龍，百世之祀，皇家兆於鳴鳳，违有丘於海北，應紫蓋於江南，帝系王基，重光累葉，高祖之建天柱，聖［本集聖上有列字。］之補地維，荡荡乎民無得而名焉者也，王資神昴緯，讬曜房靈，體斯孝烈，不由師保，月生之對，曾何用於擬議，日近之言，無階於等級，封河東王，加侍中，淑貌與金燧相宜，清顏與玉壶同照，授使持節南徐州刺史，武羌旅拒，亭障遷移，漠草非長廣之東，湖萊近荆門之北，王常譏庾翼，使白面之非才，深慕曹彰，叹黃鬢之為可，火精不退，奚應善言，冰蛭難消，徒持陰德，薨於沙镇，時年十有七，追赠司空，加鼓吹班劍，謚曰康簡王，洛北占墳，河南除道，葭悲煙殿之聲，劍動丰城之氣，豈惟晉皇寵悼，重琅邪之赠官，魏後高文，製蒼舒之哀诔。","sortOrder":56},
  {"id":"s_work_nvlt_45_57","chapterId":"ch_work_nvlt_45","text":"【诔】後漢傅龍［按當作毅。］北海王诔曰：永平六年，北海靜王薨，於是境內，市不交易，涂無征旅，農不修畝，室無女工，感傷惨怛，若丧厥親，俯哭後土，仰愬皇旻，於是群英列俊，靜思勒銘，惟王勋德，是昭是明，存隆其實，光曜其聲，終始之际，於斯為榮，乃作诔曰：覽视昔初，若論往代，有國有家，篇籍攸載，貴鮮不驕，滿罔不溢，莫能履道，聲色以卒，惟王建國，作此蕃弼，撫綏方域，承翼京室，對楊休嘉，光昭其則，溫恭朝夕，敦循伊德。","sortOrder":57},
  {"id":"s_work_nvlt_45_58","chapterId":"ch_work_nvlt_45","text":"又魏文帝蒼舒诔曰：建安十二年，五月甲戌，童子曹蒼舒卒，乃作诔曰：於惟淑弟，懿矣純良，誕丰令质，荷天之光，既哲且仁，爰柔克刚，彼德之容，慈我聿行，宜逢分祚，以永無疆，如何昊天，凋斯俊英，呜呼哀哉，惟人之生，忽若朝露，促促百年，亹亹行暮，矧爾既夭，十三而卒，何辜於天，景命不遂。","sortOrder":58},
  {"id":"s_work_nvlt_45_59","chapterId":"ch_work_nvlt_45","text":"魏陳王曹植任城王诔曰：昔二虢佐文，旦奭翼武，於休我王，魏之元辅，將崇懿跡，等號齊魯，如何奄忽，命不是與，仁者悼没，兼彼殊類，矧我同生，能不憯悴，目想宮墀，心存平素，仿佛魂神，馳情陵墓，凡夫愛命，達者彻名，王雖薨殂，功著丹青，人誰不没，貴有遺聲，乃作诔曰：幼有令质，光耀珪璋，孝殊闵氏，義達參商，溫溫其恭，爰柔克刚，心存建業，王室是匡，矯矯元戎，雷動雨徂，橫行燕代，威慴北胡，奔虜無竄，還戰高柳，王率壮士，常為軍首，宜究長年，永保皇家，如何奄忽，景命不遐，同盟飲淚，百僚咨嗟。","sortOrder":59},
  {"id":"s_work_nvlt_45_60","chapterId":"ch_work_nvlt_45","text":"宋謝靈運庐陵王诔曰：事非淮南，而痛深於中霧，跡非任城，而暴甚於仰毒，讬體皇極，衔怨至盡，豈惟有識傷慨，故亦率土凄心，蓋出罔己之悲，以陳酸切之事雲爾，哀哀君王，終仁且德，在枉無言，即罪有默，曾是忍虐，古來一酷，身微咎累，痛逾酖毒，何斯禍斯，乃怨乃辱，命如可延，人百其贖，矜急景之難留，悼驚波之易淪，自君王之冥漠，歷弥稔於此春，聆鳴禽之响穀，视乔木之陵雲，鹹感節而興悅，獨懷悲而莫申，侯射隼於高墉，赫王典以正刑，服二辜於北犴，致九伐於南荆，發酸痛於仁詔，令寵赠於哀心，布凄楚於帝言，摅綢缪於皇音。","sortOrder":60},
  {"id":"s_work_nvlt_45_61","chapterId":"ch_work_nvlt_45","text":"【行状】梁任昉齊竟陵文宣王萧子良行状曰：公道亚生知，照鄰幾庶，孝始人倫，忠為令德，公實體之，非毀譽所至，天材博贍，學綜兼明，至曲台之禮，九師之易，樂分龍趙，詩析齊韓，有一於此，不［《文選》六十不上有罔字。］兼綜，昔沛獻訪對於雲台，東平齊聲於楊史，淮南取貴於食時，陳思見稱於七步，方斯蔑如也，夫家國之道，互為公私，君親之義，遞為隱犯，公一極一致，愛敬同歸，亮誠盡規，謀猷弘遠矣，他人之善，若己有之，民之不臧，公實貽恥，誘接恂恂，降以顏色，人有不及，內恕諸己，非意相幹，每為理屈，任天下之重，體生民之俊，華袞與缊褚同歸，山藻與蓬池俱逸，良田廣宅，符仲長之言，芒山洛水，协應叟之志，丘園東國，緇銖軒冕，乃依林構宇，傍巖拓架，清猿與壶人爭旦，緹幕與素瀨交暉，置之虛室，入野何辨，高人何黠，［《文選》作點，躡屦於鍾阿，徵士劉虬，獻書於衡嶽，赠以真人之服，弘以度外之禮。］","sortOrder":61},
  {"id":"s_work_nvlt_45_62","chapterId":"ch_work_nvlt_45","text":"梁沈約齊臨川王行状曰：公遵玄源於陵壑，禀黃中之正氣，其性逸，其神凝，端華表於弱齒，弘貴著乎將立，雲虛景暧，嶽秀川渟，蘭桂不逾其质，珪璋未究其美，幼而悅學，業茂從師，洽貫書場，該緯文圃，清暉秘譽，燭野光朝。","sortOrder":62},
  {"id":"s_work_nvlt_45_63","chapterId":"ch_work_nvlt_45","text":"梁裴子野司空安城康王行状，公降七緯之禎靈，五行之正性，珪璋博達，清明在躬，學無常師，希風乎孔甫，幾神殆庶，谅亚跡乎顏生，悅禮敦詩，方昔人而有裕，既明且哲，體大雅而弗渝，若乃慈明外朗，淑德內润，夏侯玉树之談，衛玠璧人之目。又授使持節郢州刺史，公四居方嶽，政刑克舉，仁恕以懷君子，刑憲以肅小人，莅煩以簡，居難則易，霈如時雨，芬若蘭荪，所去見思，所居稱治，遘疾薨竟陵之石梵，時年四十四，皇上震天倫之悼，庶僚懷人百之感，詔赠司空常侍，王如故，禮也，自巴濮以東，郾邓以北，方舟連騎，赴者如雲，昔王薨及葬，仁禽有踐境之識，羊祜雲亡，市人有罢歸之恸，若公恩結三楚，亦異世一時之，［疑當作亦異世之一時。］公幼無擇言，長無擇行，立功以庇物，執德以居宗，重以道性虛閒，居處冲約，終日清靜，如布素焉。","sortOrder":63},
  {"id":"s_work_nvlt_45_64","chapterId":"ch_work_nvlt_45","text":"◇相國","sortOrder":64},
  {"id":"s_work_nvlt_45_65","chapterId":"ch_work_nvlt_45","text":"漢書百官表曰：相國，秦官，金印紫綬，掌丞天子，助理萬機。","sortOrder":65},
  {"id":"s_work_nvlt_45_66","chapterId":"ch_work_nvlt_45","text":"《漢書》曰：萧何，沛人，陳豨反，上自將，聞呂後用何計誅韓信，拜何相國，益封五千戶，卒五百人為衛，眾人皆贺，召平獨弔，召平者，故秦東陵侯，秦破，為布衣，种瓜長安城東，平謂何曰：禍自此始也，何乃讓封，悉以家财佐軍，上喜。","sortOrder":66},
  {"id":"s_work_nvlt_45_67","chapterId":"ch_work_nvlt_45","text":"又曰：曹參聞萧何薨，告舍人，趣治裝，吾將入相，使者果召參，參為相，日夜飲酒，賓客見參不事，皆欲有言，至者參辄飲以酒，醉而後去，終莫得說，相舍後園近吏舍，吏舍日飲歌呼，從吏患之，請參遊後園，幸相國召案，乃反張坐飲，歌呼與相和，參見人細過，专掩匿之，百官偕叹。","sortOrder":67},
  {"id":"s_work_nvlt_45_68","chapterId":"ch_work_nvlt_45","text":"《獨斷》曰：相國自萧何以後，殆非复人臣之位。","sortOrder":68},
  {"id":"s_work_nvlt_45_69","chapterId":"ch_work_nvlt_45","text":"齊職儀曰：相國，绿綬，袞冕服，湯以伊尹為左相，仲虺為右相，高宗得說，因立為相，魏襄王以公孫衍為相國，趙孝成王以廉頗為相國。","sortOrder":69},
  {"id":"s_work_nvlt_45_70","chapterId":"ch_work_nvlt_45","text":"【诔】晉成公綏魏相國舞陽宣文侯司馬公诔曰：應期降命，篤生我公，九德聿修，百行兼通，文皇踐位，龍飛天衢，协贊大命，啟迪靈符，光我聖主，齊德有虞，受茲介祉，封國建畿，入總納言，敷化衡機，出登上將，奋武明威，皇舆省方，作镇於許，旌旗既反，撫戎荆楚，巴蜀作寇，侵我邊疆，乃眷西顧，董統雍涼，丹麾所指，莫之敢抗，仁濟宇內，威慑外荒，流惠陝西，齊美甘棠，加命九錫，尊位相國，比王齊魯，以崇厥德。","sortOrder":70},
  {"id":"s_work_nvlt_45_71","chapterId":"ch_work_nvlt_45","text":"◇丞相","sortOrder":71},
  {"id":"s_work_nvlt_45_72","chapterId":"ch_work_nvlt_45","text":"應劭《風俗通》曰：丞者，承也，相者，助也。","sortOrder":72},
  {"id":"s_work_nvlt_45_73","chapterId":"ch_work_nvlt_45","text":"《史記》曰：秦武王置二丞相，甘茂為左丞相，樗里疾為右丞相。又，韦丞相賢者，魯人，以讀書術為吏，至大鸿臚，有相工相之，當至丞相，有男四人，使相之，至第二子，名玄成，相工曰：此子貴，當封侯，丞相曰：我今為丞相，有長子，是安從得之，後竟為丞相。","sortOrder":73},
  {"id":"s_work_nvlt_45_74","chapterId":"ch_work_nvlt_45","text":"又，匡衡為御史大夫，歲餘，韦丞相死，代為丞相，封樂安侯，十年之間，不出長安城門，而至丞相。","sortOrder":74},
  {"id":"s_work_nvlt_45_75","chapterId":"ch_work_nvlt_45","text":"《漢書》：百官表曰：丞相秦官，金印紫綬，掌丞天子，助治萬機，秦有左右，高帝即位，置丞相。","sortOrder":75},
  {"id":"s_work_nvlt_45_76","chapterId":"ch_work_nvlt_45","text":"又，陳平，武陽人，周勃，沛人，帝即位，以平為丞相，平曰：臣功不如勃，於是以勃為右丞相，以平為左丞相，帝問勃曰：歲决獄錢穀出入幾何，勃不知，汗出洽背，上問平，平曰：有主者，上曰：主者誰，平曰：决獄责廷尉，錢穀责治粟內史，上曰：君所主何事，平曰：臣主上佐天子，理陰陽，調四時，下遂萬物之宜，镇撫四夷，上曰：善。","sortOrder":76},
  {"id":"s_work_nvlt_45_77","chapterId":"ch_work_nvlt_45","text":"又曰：公孫弘，淄川人，武帝以弘為丞相，丞相常以列侯為之，唯弘無爵，詔封平津乡侯，六百五十戶，丞相封自弘始也，弘食一肉脱粟飯，故人賓客仰衣食，家無餘财。","sortOrder":77},
  {"id":"s_work_nvlt_45_78","chapterId":"ch_work_nvlt_45","text":"又曰：蔡義，河內人，詔求能為韓詩者，徵義，上疏，臣行能無比，容貌不及眾，而不弃人倫者，以聞道於先師，自讬於經術，原賜清間之燕，以詩授昭帝，為丞相，短小無須眉，貌似老嫗，行步俯僂，常兩吏扶夹，乃能行。","sortOrder":78},
  {"id":"s_work_nvlt_45_79","chapterId":"ch_work_nvlt_45","text":"又曰：王商為丞相，有威重，長八尺餘，单於來朝，引見，商坐未央庭中，单於前拜謁商，商起，離席與言，单於仰视商貌，大畏之，遷延却退，天子聞之，叹曰：此真漢相也。","sortOrder":79},
  {"id":"s_work_nvlt_45_80","chapterId":"ch_work_nvlt_45","text":"漢雜事曰：田蚡為丞相，中二千石拜謁，蚡不為禮，汲黯為主爵都尉，見蚡，未嘗拜，揖之而已。","sortOrder":80},
  {"id":"s_work_nvlt_45_81","chapterId":"ch_work_nvlt_45","text":"《漢舊儀》曰：丞相車兩黑轓，騎者戈絳，掾吏見禮如師弟子，白錄不拜朝，示不臣也，聽事閤曰黃閤。","sortOrder":81},
  {"id":"s_work_nvlt_45_82","chapterId":"ch_work_nvlt_45","text":"又曰：有天地大变，天下大過，皇帝使侍中持節，乘四白馬，賜上尊酒十斛，牛一頭，策告殃咎，使者去，半道，丞相病，上追使者還，未白事，尚書以丞相不［《太平御覽》二百零四不下有起病聞，若丞相不七字，此脱。］勝任，使者策書，駕骆馬，即時布衣，步出府，免為庶人，丞相有他過，使者奉策書，駕騅騩馬，即時步出府，乘栈車壮［御覽作牝。］馬，賜歸田里思過。","sortOrder":82},
  {"id":"s_work_nvlt_45_83","chapterId":"ch_work_nvlt_45","text":"應劭《漢官儀》曰：丞相有疾，御史大夫三日一問起居，百僚亦然，朝廷遣中使太医高手，膳羞骆驿，及瘳视事，尚書令若光祿大夫賜以養牛，上尊酒。","sortOrder":83},
  {"id":"s_work_nvlt_45_84","chapterId":"ch_work_nvlt_45","text":"《物理論》曰：高祖定天下，置丞相，以統文德，立大司馬，以整武事，為二府焉。","sortOrder":84},
  {"id":"s_work_nvlt_45_85","chapterId":"ch_work_nvlt_45","text":"【箴】晉陆機丞相箴曰：夫导民在簡，為政以仁，仁實生愛，簡亦易遵，罔疏下睦，禁密巧繁，深文碎教，伊何能存，故人不可以不審，任不可以不忠，舍賢昵讒，則丧爾邦，且偏見則昧，专聽悔疑，耳目之用，亦各有期，夫豈不察，而惟牆隔之，矜已任智，是蔽是欺，德無遠而不复，惡何適而不追，存亡日鑒，成败代陳，人鹹知鏡其貌，而莫能照其身。","sortOrder":85},
  {"id":"s_work_nvlt_45_86","chapterId":"ch_work_nvlt_45","text":"【碑】晉袁宏丞相桓溫碑銘曰：文武开業，尚父定王佐之契，宗周不競，桓公弘九伐之勋，脱履於必濟之功，忘懷於屈伸之會，高氏出乎生民，公亮坦於萬物，遂复改謀回慮，策馬武關，總辔丹扸之涂，扬鞭終南之嶺，兵交則戰無全敵，勸義則襁負雲集，徒以懸軍輕進，因蓄靡储，而銶狼懼殪，保固窟穴，乃方軌回轅，反師凯入，雖奇功大勋，未捷於一朝，而宏謨神略，義高於天下，公惟秀杰英特，奇姿表於弱冠，俊神朗鑒，明統備於成德，巾褐衡門，風流推其高致，忘己應務，天下謝其勋業，辅相兩儀，而通運之功必周，虛中容長，而方圓之才鹹得，道濟而不有，處泰而逾約，可謂固天特縱，生民之杰者也，銘曰：美盡黃裳，道畅伊呂，哲人應運，命世作辅，卓卓英風，略略宏宇，亮心高列，俊神間舉，忘己濟物，撫化翼世，河洛澄流，華梁卷翳，俾我仁公，弘道作鏡，如何不弔，雲峦落映。","sortOrder":86},
  {"id":"s_work_nvlt_45_87","chapterId":"ch_work_nvlt_45","text":"又晉孫綽丞相王导碑文，公胄興姬文，氏由王乔，玄聖陶化以啟源，靈仙延祉以分流，賢俊相承，世冠海岱，二儀交泰，妙氣發暉，醇曜所鍾，公寔應之，玄性合平，道旨冲一，體之自然，柔畅协乎春風，溫而侔於冬日，信人倫之水鏡，道德之標准也，惠懷之际，運在大過，皇德不建，神辔再絕，獫玁孔炽，凶類猋起，公見機而作，超然玄悟，遂扶翼蕃王，室协東嶽，弘大順以一群後之望，仗王道以應天人之會，於時乾維肇振，創製理物，中宗拱己，雅仗賢相，尚父之任，具瞻在公，存烹鮮之義，殉易簡之政，大略宏規，卓然可述，公雅好談詠，恂然善誘，雖管綜時務，一日萬機，夷心以延白屋之士，虛己以招巖穴之俊，逍遙放意，不峻儀軌，公執國之鈞，三十餘載，時難世故，備經之矣，夷险理亂，常保元吉，匪躬而身全，遺功而勋舉，非夫領鑒玄達，百煉不渝，孰能莫忤於世，而動與理會者哉。","sortOrder":87},
  {"id":"s_work_nvlt_45_88","chapterId":"ch_work_nvlt_45","text":"梁簡文帝長沙宣武王北涼州廟碑文曰：黃曲仁［按黃疑當作神，曲仁二字當作農，神農九井，見荆州記。］之祀，九井尚慚，沫水之堂，七壁猶在，豈非德含體氣，神降空桑，烝民仰其立功，太上懷其貴德，公讳，蘭陵人，皇帝之長兄也，命世降靈，峻極开著，宗百川而成海，倍萬俊而為英，為南梁北秦二州刺史，華陽陵黑水，［句有訛誤。］改號難堪，加以嶽牧遷回，軍民徙散，同高闕以為塞，象玉門而置關，三尉寢謀，六屯罢業，功同疏勒之守備，甚即墨之堅围，公臨危製变，殷如敵國，是以六角摧鋒，兩賢衅鼓，指捴則破勍敵，叱咤而靜邊尘，公德應大賢，照惟殆庶，如鍾資叩，似铎發聲，含朝陽於千仞，散風行於萬頃，神武所向，士卒忘水火之難，单醪所驅，小大一死生之志，微管之風，餘芳無絕，人畏其神，德音不泯，梁秦二州刺史宜封侯條，刺舉漢陽，親睹遺愛，有表請立碑置廟，天子許焉，反宇飛風，伏槛含日，參差丹桂，周流紫房，躨跜刻獸，下臨網戶，菡萏荷華，傍連屈屋，庶使邊韶所立之名，豈稱高於陳郡，袁逢所勒之字，非獨擅於華陽，乃為贊曰：帝圖开道，皇源配天，功書绿字，事燭青編，天漢之陽，黑水惟梁，如仁永播，流詠寧忘，扶風高碣，召伯甘棠，餘芳無泯，望古可方，構斯象室，循茲洞房，琉璃照戶，璧玉开堂，秋條下葉，春卉含芳，九微夜火，百味朝漿。","sortOrder":88},
  {"id":"s_work_nvlt_45_89","chapterId":"ch_work_nvlt_45","text":"又丞相長沙宣武王碑曰：金表龍符，绿地龟圖，且稱瑞漢，寔曰开虞，於昭帝緒，蝉聯厥初，有微玄冰，亦作司徒，重簷偃蹇，曲註逶迤，重栌鳳翥，桂棟莲披，文檀晚麗，采節晨辉，春藤絡戶，寒菊臨池，惟馨惟德，無絕於斯。","sortOrder":89},
  {"id":"s_work_nvlt_45_90","chapterId":"ch_work_nvlt_45","text":"梁沈約齊丞相豫章文憲王碑曰：世載冠冕之暉，家开配天之業，洪源邁於委水，雲峰冠於削成，公自天攸縱，非待河嶽，道亚生知，德備藏往，摩赤霄而理翰，望閶阖以上馳，回風飆於襟袖，宅山川於懷抱，爰初弱冠，藏器俟時，康莊廣辟，飾禮賢之馆，杞梓備收，罄滋蘭之畹，既駕朱驂。又敷袞職，升降軒陛，率由孝敬，謙以備物，貴以在身，再握励己，三吐忘倦，公德惟民望，位冠朝首，儀表瑰雄，風神秀杰，每至三元首旦，華裔在庭，執玉端闈，冠冕百辟，外夷震耸，猶单於之懼王商，群後瞻慕，若眾星之俯日月，雖复以周公之親，居周公之任，道格皇天，光被四海，而小善靡失，輶德必從，譬由畎澮匪讓，所以淼致江河，土壤同歸，故能鬱成嵩岱，保翼三善，弘正九伐，銘彼太常，懸諸日月，銘曰：大德風邁，其美雲從，事貴愈貶，禮峻弥恭，且有厚命，車服以庸，羽儀列辟，冠冕群龍，周實多祐，漢有餘慶，弈弈皇族，於斯為盛，公之綏之，終和且敬，是惟宗國，庶邦作詠。","sortOrder":90},
  {"id":"s_work_nvlt_45_91","chapterId":"ch_work_nvlt_45","text":"梁任昉丞相長沙宣武王碑曰：玉映藍田，金铉之望已集，木秀邓林，輪轅之用先表，值戎寇貪惏，羁縻失道，凭凌雉堞，逼迫濠湟，都護之威既弛，副尉之策已謝，斧松晨析，易子朝餐，乞師援絕，飛書路阻，公內定不戰之奇，外騁必勝之略，神功倏忽，有同拾遺，南下牧馬，既寢折膠之術，北遯燕然，將空漠南之地，加以廣平簡惠，信賞必罰，增赀就賦，夷歌成章。","sortOrder":91},
  {"id":"s_work_nvlt_45_92","chapterId":"ch_work_nvlt_45","text":"【诔】晉陆機吳丞相江陵侯陆公诔曰：根條伊何，苗黃裔舜，長發有祥，貽我作胤，劉王負险，寇我西鄰，公侯赫怒，幹戈啟陳，金鉞鏡日，雲旗降文，元玉陨難，鯨鲵墜鱗，戎漢時殪，方城清尘。","sortOrder":92},
  {"id":"s_work_nvlt_45_93","chapterId":"ch_work_nvlt_45","text":"◇冢宰","sortOrder":93},
  {"id":"s_work_nvlt_45_94","chapterId":"ch_work_nvlt_45","text":"仲長統《昌言》曰：冢宰，尧官也。","sortOrder":94},
  {"id":"s_work_nvlt_45_95","chapterId":"ch_work_nvlt_45","text":"《尚書》曰：冢宰掌邦治，統百官，均四海。","sortOrder":95},
  {"id":"s_work_nvlt_45_96","chapterId":"ch_work_nvlt_45","text":"《周官》曰：太宰之職，掌建邦之六典，以佐王治邦國，一曰治典，以經邦國，以治官府，以紀萬民，二曰教典，以安邦國，以教官府，以扰萬民，三曰禮典，以和邦國，以統百官，以諧萬民，四曰政典，以平邦國，以正百官，以均萬民，五曰刑典，以詰邦國，以刑百官，以糾萬民，六曰事典，以富邦國，以任百官，以生萬民。","sortOrder":96},
  {"id":"s_work_nvlt_45_97","chapterId":"ch_work_nvlt_45","text":"王隱《晉書》曰：武帝時，太傅領司徒何曾，屢上書遜位，詔以司徒所掌煩務，不可以久勞耆艾，其進位太宰，朝會乘舆，劍履上殿，如漢萧何魏鍾繇故事。","sortOrder":97},
  {"id":"s_work_nvlt_45_98","chapterId":"ch_work_nvlt_45","text":"晉公卿禮族［《太平御覽》二百零六作秩。］曰：安平王孚朗陵公何曾汝南王亮，皆為太宰，齊職儀曰：太宰品第一，金章紫綬，佩山玄玉，尧命羲和，使主其陰陽之職，羲伯司天官也，後稷伏事虞夏，敬事民時，尊稷為天官，夏衰，稷後不窋失官，由是废官，殷以其官為冢宰，周公在丰，為太宰，召公又居之，秦漢魏無此職，晉武以從祖安平王孚為太宰，始置其官，安平薨省，鹹寧四年又置，或謂本太師之職，避景帝讳，改為太宰，太宰周之卿位，晉武依周置職，以尊安平，非避讳也，後元興中，恭帝為太宰，桓玄都督中外，博士徐豁議，太宰非武官，不應敬都督，從豁議。","sortOrder":98},
  {"id":"s_work_nvlt_45_99","chapterId":"ch_work_nvlt_45","text":"【碑】晉孫綽太宰郄鑒碑文曰：公蓋黃帝之苗裔，氏族所由，皆紀於祖御史大夫之碑矣，靈和誕授，載育公侯，至德硕量，天實挺之，琅邪王應天啟之運，闡中興之道，思延英賢，以匡王業，乃假兖州刺史金章，仍割玄鉞載飾，於時羯寇凶炽，群逆猋起，公奋其忠勇，精貫白日，信順為甲胄，大節為城池，故能摧却凶寇，全身濟功，惟公德器純固，體識深弘，敦尚衡門，則服膺曾闵，毗亮皇極，則憲章元凯，篤誠簡於帝心，明允著於莅政，信鍾山之珪璧，歲寒之靈木者也，摛藻風雲，策名帝錄，肇皆方尺，遂隆台嶽，王室未休，吾何以豫，興言再慨，思康天步，將俾皇化，歸之大素，彼蒼者天，曾不遐祚，哲人其萎，民斯攸慕，嗟爾後崑，式瞻宏度。","sortOrder":99},
  {"id":"s_work_nvlt_45_100","chapterId":"ch_work_nvlt_45","text":"齊王俭太宰褚彦回碑文曰：夫太上立德，其次立功，此謂之不朽，所以子產雲亡，宣尼泣其遺愛，隋武既没，趙文懷其餘風，乃祖太傅，德合當時，行庇州壤，深識臧否，不以毀譽形言，亮采王室，每懷冲虛之道，可謂婉而成章，志而晦者矣，公禀川嶽之靈暉，含珪璋而挺曜，和順內凝，英華外發，神茂初學，業隆弱冠，是以仁經義緯，敦穆於閨庭，金聲玉振，寥亮於區宇，孝敬淳深，率由斯至，盡歡朝夕，人無間言，逍遙乎文雅之囿，翱翔乎禮樂之圃，風儀與秋月齊明，音徽與春雲等润，既而齊德龍興，順皇高禪，深達先天之運，匡贊奉時之業，亦猶稷契之臣虞夏，荀裴之奉魏晉，今之尚書，古之冢宰，雖秩輕於袞司，而任隆於百辟，暫遂冲旨，改授朝端，邇無異言，遠無異望，執五禮以正民，簡八刑而罕用，故能聘績康衢，延慈哲後，仰南風之高詠，餐東野之秘實，雅議於聽政之晨，披文於宴私之夕，參以酒德，間以琴心，暧有餘暉，遙然流想，君垂冬日之溫，臣盡秋霜之戒，肅肅焉，穆穆焉，於是見君親之同致，在三之如一，銘曰：永言必孝，用心則友，仁洽兼濟，愛深善誘，睹海齊星，登嶽均厚，五臣茲六，八元斯九，率禮蹈謙，谅實身幹，跡屈朱軒，志隆衡馆，眇眇玄宗，萋萋辭翰，義既水流，文亦霧散。","sortOrder":100},
  {"id":"s_work_nvlt_45_101","chapterId":"ch_work_nvlt_45","text":"【诔】晉潘嶽太宰魯武公诔曰：昂昂公侯，實天誕育，八元斯九，五臣茲六，揜讨逆節，折冲［原訛衡，據冯校本改。］江湖，走钦擒俭，枭誕弊吳，公於出征，爰整其旅，壘未越郊，麾不及舉，秦涼獲乂，西戎即叙，他人之賢，譬彼丘陵，邈矣公侯，如日之昇，泰山其頹，寢疾不興，遐邇曷仰，社稷焉凭，生則榮易，終哀實難，靡不春華，鮮克歲寒，於呼公陨，率土含酸，趙丧望諸，列國同傷，秦亡蹇叔，舂者不相，桃李不言，下自成行，德之休明，没能弥彰。","sortOrder":101},
  {"id":"s_work_nvlt_45_102","chapterId":"ch_work_nvlt_45","text":"【表】後魏溫子昇上党王穆讓太宰表曰：臣聞策蹇長途，終慚一日之致，懸縷層台，詎任千鈞之重，固知才弱不可自彊，力微難以企及，智小謀大，恐貽折足之忧，才輕任重，懼有絕臏之悔，既慮鑠金，固陳匪石。","sortOrder":102},
  {"id":"s_work_nvlt_45_103","chapterId":"ch_work_nvlt_45","text":"《藝文類聚》　唐·欧陽詢","sortOrder":103},
  {"id":"s_work_nvlt_46_1","chapterId":"ch_work_nvlt_46","text":"卷四十六職官部二","sortOrder":1},
  {"id":"s_work_nvlt_46_2","chapterId":"ch_work_nvlt_46","text":"○太尉太傅太保祭酒博士","sortOrder":2},
  {"id":"s_work_nvlt_46_3","chapterId":"ch_work_nvlt_46","text":"◇太尉","sortOrder":3},
  {"id":"s_work_nvlt_46_4","chapterId":"ch_work_nvlt_46","text":"《春秋合成圖》曰：尧坐舟中，與太尉舜臨觀，鳳皇授圖。","sortOrder":4},
  {"id":"s_work_nvlt_46_5","chapterId":"ch_work_nvlt_46","text":"《史記》曰：孝惠帝六年，置太尉官。","sortOrder":5},
  {"id":"s_work_nvlt_46_6","chapterId":"ch_work_nvlt_46","text":"百官表註曰：太尉，古官也，自上安下曰尉，故武官以為號。","sortOrder":6},
  {"id":"s_work_nvlt_46_7","chapterId":"ch_work_nvlt_46","text":"月令曰：孟夏，太尉贊俊杰，遂賢良。","sortOrder":7},
  {"id":"s_work_nvlt_46_8","chapterId":"ch_work_nvlt_46","text":"漢書百官表曰：太尉，秦官，金印紫綬，掌武事，周勃灌婴周亚夫等為之。","sortOrder":8},
  {"id":"s_work_nvlt_46_9","chapterId":"ch_work_nvlt_46","text":"《漢書》曰：呂後問高祖曰：陛下百歲之後，萧相國既死，令誰代之，上曰：曹參可，其次，曰：王陵可，然少戆，陳平可以助之，陳平智有餘，然難獨任，周勃重厚少文，然安劉氏者，必勃也，可令為太尉。","sortOrder":9},
  {"id":"s_work_nvlt_46_10","chapterId":"ch_work_nvlt_46","text":"又曰：王龚為太尉，在位，自非公事，不通州郡書記，其所辟命，皆海內長者。","sortOrder":10},
  {"id":"s_work_nvlt_46_11","chapterId":"ch_work_nvlt_46","text":"《東觀漢記》曰：張辅，字益侯，為太尉，父尚在，辅每遷轉，乃一到洛，父來，適會正臈，公卿罢朝，俱贺歲，奉酒上辅父寿，極歡，莫不嘉其榮。","sortOrder":11},
  {"id":"s_work_nvlt_46_12","chapterId":"ch_work_nvlt_46","text":"又曰：邓彪，字智伯，為太尉，在位清白公廉。","sortOrder":12},
  {"id":"s_work_nvlt_46_13","chapterId":"ch_work_nvlt_46","text":"謝承《後漢書》曰：京兆朱寵，字仲威，為太尉，家貧，食脱粟飯，臥布被，朝廷賜錦被粱肉，皆不敢當。","sortOrder":13},
  {"id":"s_work_nvlt_46_14","chapterId":"ch_work_nvlt_46","text":"又曰：鄭弘為臨江太守，行春，有兩白鹿，隨車夹轂而行，弘怪問主簿黃國，鹿為吉凶，國拜贺曰：聞三公車圖畫作鹿，明府當為宰相，後弘果為太尉，舉［○《太平御覽》二百零七舉下有將字，此脱。］六十九卷屏風篇引亦脱，弟五倫為司空，班次在下，每正朔朝見，弘曲躬自卑，上後置雲母屏風分隔，由此為故事。","sortOrder":14},
  {"id":"s_work_nvlt_46_15","chapterId":"ch_work_nvlt_46","text":"《續漢書》曰：太尉公一人，掌四方兵事功勤，歲盡則奏其殿最，而行賞罰，凡郊祀之事，掌亚獻。","sortOrder":15},
  {"id":"s_work_nvlt_46_16","chapterId":"ch_work_nvlt_46","text":"袁崧《後漢書》曰：太尉劉虞，讓位於羊續，靈帝時，為三公者，皆输禮錢千萬，續舉褞袍以示之曰：臣之有，唯此而已，遂不代虞。","sortOrder":16},
  {"id":"s_work_nvlt_46_17","chapterId":"ch_work_nvlt_46","text":"華峤《後漢書》曰：安帝即位，太尉徐防，以灾異寇賊，策免就國，凡三公以灾免，始自防也。","sortOrder":17},
  {"id":"s_work_nvlt_46_18","chapterId":"ch_work_nvlt_46","text":"范晔《後漢書》曰：曹嵩，靈帝時，货賂中官，及输西園錢一亿萬，故位至太尉。","sortOrder":18},
  {"id":"s_work_nvlt_46_19","chapterId":"ch_work_nvlt_46","text":"應劭《漢官儀》曰：章帝詔曰：司空牟融，典職六年，勤勞不怠，其以融為太尉，錄尚書事。","sortOrder":19},
  {"id":"s_work_nvlt_46_20","chapterId":"ch_work_nvlt_46","text":"又曰：冲帝丁酉策書，太尉趙峻，二世掌典機衡，有匪石不貳之心，大司農李同，公族之苗，忠直不回，有史魚之風，今以峻為太傅，同為太尉，與大將軍冀，參錄尚書事。","sortOrder":20},
  {"id":"s_work_nvlt_46_21","chapterId":"ch_work_nvlt_46","text":"《幽明錄》曰：常山張顥，為梁相，天新雨後，有鳥如鵲，飛翔稍下，墜地，民爭取，即化為一圓石，顥椎破之，得金印，文曰忠孝侯印，顥表上聞，藏之秘府，顥漢靈帝時至太尉。","sortOrder":21},
  {"id":"s_work_nvlt_46_22","chapterId":"ch_work_nvlt_46","text":"齊職儀曰：魏文帝黃初二年，日食，奏免太尉贾詡，詔曰：天地之灾害，罪在朕躬，勿貶三公，遂為永製，而太尉華歆，以疾，依田千秋故事，乘舆上殿，大會，遣散騎常侍缪龚請歆，百官總己，聽歆至。","sortOrder":22},
  {"id":"s_work_nvlt_46_23","chapterId":"ch_work_nvlt_46","text":"【贊】後漢蔡邕太尉陳公贊曰：公在百里，有西產之惠，賜命方伯，分陝餘慶，餘慶伊何，兆民其觀，少者是懷，老者是安，綱紀文王，文王用平，東督京輦，京輦用清，乃登三事，三事攸寧，契稷之佐，具於尧庭，今則由古，於穆誕成。","sortOrder":23},
  {"id":"s_work_nvlt_46_24","chapterId":"ch_work_nvlt_46","text":"【箴】後漢崔骃太尉箴曰：天官冢宰，庶僚之師，師錫有帝，命虞作尉，苟非其人，斁我帝載，昔周人思文公，而召南詠甘棠，崑吾隆夏，伊挚盛商，季世頗僻，禮用不匡。","sortOrder":24},
  {"id":"s_work_nvlt_46_25","chapterId":"ch_work_nvlt_46","text":"【碑】後漢蔡邕楊太尉碑銘曰：於戲公，惟嶽靈，天挺德，翼赤精，神氤氲。仁哲生，應台任，作邦禎，帝钦亮，訪典刑，道不忒，迄有成，光遐邇，穆其清。","sortOrder":25},
  {"id":"s_work_nvlt_46_26","chapterId":"ch_work_nvlt_46","text":"又楊太尉碑銘曰：天鑒有漢，挺生元辅，世作三事，勋在王府，乃及伊公，克光前矩，悉心畢力，胤其祖武，化洽群生，泽霑區宇。","sortOrder":26},
  {"id":"s_work_nvlt_46_27","chapterId":"ch_work_nvlt_46","text":"又太尉李鹹碑銘曰：天垂三台，地應五嶽，降生我公，應鼎之足，弈世載德，名昭圖錄，既文且武，桓桓紹續，外則折冲，內則大麓。","sortOrder":27},
  {"id":"s_work_nvlt_46_28","chapterId":"ch_work_nvlt_46","text":"又太尉桥玄碑曰：岐嶷而超等，總角而逸群，至矣乎［本集作至於］初紳，高明卓異，為眾杰之雄，其性莊，疾尚華［本集作華尚。］朴，有折而不桡，拔賢如逝流，讨惡如霆击，至德在己，扬之由人，苟不矯跡，夫何舍焉。","sortOrder":28},
  {"id":"s_work_nvlt_46_29","chapterId":"ch_work_nvlt_46","text":"後漢桓麟［按當作驎。］太尉劉宽碑曰：公誕受純和之氣，體有樂道寧俭之性，疾雕飾，尚朴素，輕榮利，重謙讓，劣與同好，鑴墳典於茅庐，是以根經緯，綜精微，誨童冠而不倦，遷南陽太守，推貞谅以示下，顯眾善以厲否，惻隱之誠，通於神人，故去鞭朴，如獲其情，弗用刑，如弭其奸，晉孫綽太尉庾亮碑曰：咨黃中以啟曹，鍾遐武於軒轅，爰及晉代，世號多士，公吸峻極之秀氣，誕命世之深量，微言散於秋毫，玄風畅乎德音，闚門者貴其凝峙，入室者議其通玄，摽形者得之廊廟，悟旨者期諸濠川，提挈南翔，息肩靈越，會大君有命，納妃德門，自求多福，辭不獲已，鳳羽籠於華樊，麟趾縶於椒房，王敦阻兵玩權，志闚神器，乃轉公左衛將軍，要雄戟以扶華轂，勒武旅以翼豹尾，死難之心，義形於色，親受中詔，奔告方伯，於是群後契盟，同禀高謀，巖栖懷德，以乡赴義，拯神器於獸吻，扶帝座於已傾，王室之不坏，翳伯舅是賴，公以為戰伐之謀，仁所恥聞，况立德弘道，年幾不惑，阖門沈舟，將遠跡山海，詔累遣侍中黃門，逼以嚴製，知不獲免，乃固求外任，江外無烽燧之警，宇內歸穆然之美，銘曰：金德時昏，乾綱絕紀，素靈南映，中宗蔚起，誰其贊之，數鍾伊公，達人忘懷，形隨運通，再潛再躍，婉若遊龍，梁沈約齊太尉王俭碑銘曰：瞻旦奭而齊軫，軼夔龍而長骛，百辟翘首，譬列宿之仰望舒，千里結轍，若派流之宗江漢，及宋道盛運，鼎命將改，而瞻乌所集，未知適歸，公高臥閒宇，獨咤虛室，眷龍顏以讬夢，詠日角以興言，佇傅巖之下，懷滋水之上，慨深版荡，念在濡足，霸君亦慮屬一匡，情隆三顧，卜匪熊羆，唯人是與，公深睹興废，妙識人英，察榮光於河渚，攀龍翼於雲漢，傾方寸以奉國，忘七尺以事君，殊文共會，異軫同歸，堆案盈幾，充庭滿室，隨方引應，斷决如流，辭不輟响，紙無停筆，精明外朗，神彩傍映，曬曯接其光景，風飆溢乎帷席，嚣喧總至，大薄相填，齊鑣共軫，併而不雜，銘曰：怅公赫矣，世載經纶，四彼三杰，六茲五臣，德參世命，道亚如仁，屣步金門，濯纓蘭畴，激水上征，倍帆鬱起。","sortOrder":29},
  {"id":"s_work_nvlt_46_30","chapterId":"ch_work_nvlt_46","text":"陳沈蜅太尉始興昭烈王碑銘曰：古者帝王之興，莫不崇建親屏，泰伯讓而退封，武哀終而受號，則有之矣，至若勒功鼎鼐，銘德太常，清廟尊乎國家，扬名顯乎子弟，在昭烈王見之焉，若夫妫水遙源，石砮遐集，五絲作而詠南風，八世興而和鳴鳳，籍帝王之基，居正卿之族，有由來矣，孔融汝穎之論，許其少多，傅畅諸公之書，頗有賢哲，自漢至魏，涉江而東，綿邈蝉聯，言之者舊，皇上革命應運，大啟邦國，麟趾盤石之宗固宜，金楨玉榦之戚畢封，文叔掩被之悲無泯，仲謀援鞍之恸逾切，乃封始興郡王，永定元年下詔曰：天倫所感，義本因心，名器追崇，則惟恒典，己兄梁故南兖州刺史長城縣公，德范沈邃，風度宽厚，性與天道，深乎靡测，昔彈冠入仕，譽重城華，宣力艱難，遂顧洪業，雖時非季漢，势異桓王，海內挹其風流，生民懷其大德者矣，朕受天明命，爰膺寶歷，言尋永往，興慕增懷，可奉赠太尉，公昔之密戚，近親，宗英令德，若河間之不群，沛獻之受象，東平之樂善，陳思之藻麗，實聞之也，未有身死忠貞，名存前代，若王之義烈者，銘曰：稽古帝舜，重瞳有裔，曰陳祚土，纂虞之系，騰波汝穎，承流妫汭，四嶽有後，六奇獻計，惟寔惟忠，卿長群公，浮舟震泽，佳氣葱葱，岐周七十，商亳百里，婉婉中陽，帝出攸止，太常景皇，季孫讓子，天下不賤，聞之惇史，入孝出忠，清辉何已，苞指周藏，風流懿德，言為世范，行成士則，名山可镌，丰碑易勒，惜哉往矣，殒身凶慝，鼎命既遷，山河是始，光啟代郡，德表永祀，周以別功，魯侯戾止，禮茂廟堂，恩加松杞。","sortOrder":30},
  {"id":"s_work_nvlt_46_31","chapterId":"ch_work_nvlt_46","text":"【墓志】梁沈約齊太尉文憲王公墓志銘曰：德被九官，功苞十亂，帝圖必舉，皇猷諧煥，斯謂國楨，是惟民幹，翱翔禮園，優遊文馆，秘義煙涌，朅辭雨散，揆路扬辉，台庭改觀，方翊隆平，变茲天網，福履每愆，降年多爽，微言永謝，庶僚誰長，鐃吹罢音，松風代响。","sortOrder":31},
  {"id":"s_work_nvlt_46_32","chapterId":"ch_work_nvlt_46","text":"梁沈約齊太尉徐公墓志曰：公美風儀，善言笑，愛重琴棋，流連情賞，拓宇東郊，暧然閒素，榮貴之來，無概懷抱，任居端揆，萬務同歸，簿領盈前，嚣尘滿席，直舉枉错，虛來實及，天道不仁，與善褰應。","sortOrder":32},
  {"id":"s_work_nvlt_46_33","chapterId":"ch_work_nvlt_46","text":"北齊邢子才太尉韓公墓志銘曰：立事立言，是為勿替，且公世德，實兮不朽，雖將相無种，而公卿有門，是以萬种四牡，曷弈於往代，長組高冠，陆離於前祀，及負笈追侣，結友從師，先難後易，身佚功倍，皆神遊隅隩，理合精微，非存甯越，废寢食以存道，久殊高鳳，忘冠履以成業，皎皎獨照，旁絕嚣滓，亭亭孤出，入自雲霞，忘情譽毀，同嗣宗之於善惡，齊心得丧，若叔夜之於慍喜，［原訛善，據冯校本改。］方將受在三九，追蹤二八，弘大道以事一人，敷至理以安百姓，而天德不厚，神聽多愆，仁勇一亡，辯智同盡。","sortOrder":33},
  {"id":"s_work_nvlt_46_34","chapterId":"ch_work_nvlt_46","text":"晉盧諶［原訛謀，據冯校本改。］太尉劉公诔曰：公侯之生，固天攸擢，高智萧條，英風卓荦，励操宏壮，抗意崇邈，雅用深奧，明鑒朗出，摛藻雲浮，飛辯盆溢，驅其豺狼，斬其藜藿，建立市朝，營置亭徼，劉恥南比，猗盧北接，或以恩燮，微我公侯，方事焉捷，委重於外，弛御於中，製比邓禹，禮優窦融。","sortOrder":34},
  {"id":"s_work_nvlt_46_35","chapterId":"ch_work_nvlt_46","text":"【表】梁王僧孺為臨川王讓太尉表曰：臣聞一□以長，望千里而成累，空输易騁，觸三尺而不登，苟曰违方，難用適遠，安車驷馬，望高闕而朝至，繡服緹麾，〈車間〉康衢而暮返，行瞻盡瘣，居對蒼龍，陛下海涵春育，日鏡雲伸，追大道之無私，惜微臣之宜極。","sortOrder":35},
  {"id":"s_work_nvlt_46_36","chapterId":"ch_work_nvlt_46","text":"後魏溫子昇西河王謝太尉表曰：臣聞拂羽决起，力謝摩天，策蹇載馳，功微送日，將短翮難以陵高，駑乘無由致遠，雖复建旟出郡，未追楚趙之風，捧壶入侍，徒踵金張之跡，及天祚明德，運啟興王，六遂始遷，九鼎初定，於焉承之，有用當官，草靡從風，未遑克讓，常恐執辔輕輪，操刀傷錦。","sortOrder":36},
  {"id":"s_work_nvlt_46_37","chapterId":"ch_work_nvlt_46","text":"◇太傅","sortOrder":37},
  {"id":"s_work_nvlt_46_38","chapterId":"ch_work_nvlt_46","text":"《大戴禮》曰：傅傅德義。","sortOrder":38},
  {"id":"s_work_nvlt_46_39","chapterId":"ch_work_nvlt_46","text":"又曰：天子不惠於庶民，不信於諸侯，不戒於戎事，不誠於賞罰，凡是之屬，太傅之任也。","sortOrder":39},
  {"id":"s_work_nvlt_46_40","chapterId":"ch_work_nvlt_46","text":"《尚書》曰：成王黜殷命，滅淮夷，歸丰，作周官，立太師太傅太保，茲惟三公，論道經邦，燮理陰陽，官不必備，惟其人。","sortOrder":40},
  {"id":"s_work_nvlt_46_41","chapterId":"ch_work_nvlt_46","text":"《贾誼書》曰：昔文王使太公望傅太子發，嗜鮑魚而公不與，文王曰：發嗜鮑魚，何為不與，太公曰：禮，鮑魚不登乎俎，豈有非禮而可以養太子哉，［事具储君部。］","sortOrder":41},
  {"id":"s_work_nvlt_46_42","chapterId":"ch_work_nvlt_46","text":"《東觀漢記》，章帝詔曰：行太尉事衛尉趙喜，三世在位，為國元老，其以喜為太傅。","sortOrder":42},
  {"id":"s_work_nvlt_46_43","chapterId":"ch_work_nvlt_46","text":"《續漢書》曰：每帝初即位，置太傅，錄尚書事，薨辄省。","sortOrder":43},
  {"id":"s_work_nvlt_46_44","chapterId":"ch_work_nvlt_46","text":"應劭《漢官》曰：太傅，古官也，周成王，康叔為之，高後元年，初用王陵，金印紫綬，八年省，哀帝元寿二年复置，位在三公上，世祖中興，特遣使者備禮，徵故密令南陽卓茂，策曰：夫士誠能為人所不能為，名冠天下，當受天下重賞，故武王誅紂，封比幹之墓，表商容之闾，今以茂為太傅，封宣德侯。","sortOrder":44},
  {"id":"s_work_nvlt_46_45","chapterId":"ch_work_nvlt_46","text":"曹植辅臣論曰：蓋精微聽察，理析毫分，規矩可則，阿保不傾，群言系於口，而研摭是非，典誥總乎心，而唯所用之者，鍾太傅也。","sortOrder":45},
  {"id":"s_work_nvlt_46_46","chapterId":"ch_work_nvlt_46","text":"齊職儀曰：太傅，品秩冠服同太宰，成王即位，周公為太傅，遷太師，秦無其職，漢惠帝崩，呂後以右丞相王陵為少帝太傅，位在三公上。","sortOrder":46},
  {"id":"s_work_nvlt_46_47","chapterId":"ch_work_nvlt_46","text":"魏黃初七年，詔太尉鍾繇為太傅，華歆為太尉，併以疾，依田千秋乘舆上殿，後三公有疾，多以為准。","sortOrder":47},
  {"id":"s_work_nvlt_46_48","chapterId":"ch_work_nvlt_46","text":"沈約《宋書》曰：晉宣帝為魏太傅，誅曹爽後，置左右長史，掾屬舍人各十人，事既非常，加又領兵，非准例也。","sortOrder":48},
  {"id":"s_work_nvlt_46_49","chapterId":"ch_work_nvlt_46","text":"【箴】晉齊王攸太傅箴曰：伊昔上皇，建國立君，仰觀天文，俯察地理，創業恢道，以惠於民，承祀祚，延統重，故援立太子，尊以弘道，固以貳己，储德既立，邦有所恃，固親以道，勿固以恩，修身以敬，勿讬以尊，自損者有餘，自益者弥昏。","sortOrder":49},
  {"id":"s_work_nvlt_46_50","chapterId":"ch_work_nvlt_46","text":"【碑】後漢蔡邕太傅胡廣碑銘曰：用能七登九命，篤受分祉，亮皇聖於六世，嘉庶績於九有，窮生民之光寵，享黃耇之遐紀，蹈明哲以保身，與福祿於終始，五蹈九列，七統三事，和神人於宗伯，治水土於下台，光弼六世，歷載三十，自漢興以來，鼎臣元辅，未有若公者焉，睹皋陶之闈壸，究孔氏之房奧，通水泉於润下，繁後土於稼穡，訓五品於群黎，理人倫於區域，曜三辰於混元，协太和乎皇極，傅聖德於幼冲，率旦奭之奋職。","sortOrder":50},
  {"id":"s_work_nvlt_46_51","chapterId":"ch_work_nvlt_46","text":"晉孫綽太傅褚褒碑曰：公資清刚之正氣，挺純粹之茂质，深量體於自然，冲識足乎弱冠，含章內映，而不運皦察之明，玄識沈通，而不以浮藻曜物，穆然忘容，尘務不幹其度，默爾獨得，膚受莫测其奧，加以溫恭孝友，少思寡欲，都督兖州刺史，將以藩屏畿甸，綏授分內，會康皇晏駕，太後臨朝，總己之重，民無異望，乃徵將軍中書令，錄尚書事，公要終之識，定於介石，雖事己未來，而情以本應，顧以主少國危，方難未夷，思清函夏，以一天宇，且帝命所存，以社稷為寄，謀身雖重，方此為輕，深為意疾，俯首撫順，公志在芟夷凶類，拯拔晉民，繕甲煉卒，日不暇給者久矣，遂見機而作，遺其劍履，將龍馬河洛，電扫司豫，廟筭以逆徒尚繁，困獸難逼，命公逐旆，以俟齊舉，雖元勋未捷，義聲亦足以振暴於華夷矣，銘曰：邈邈遠遊，亹亹令圖，將激淮海，洒涤中區，雅業未究，哲人其徂，敢勒玄石，敬刊高謨。","sortOrder":51},
  {"id":"s_work_nvlt_46_52","chapterId":"ch_work_nvlt_46","text":"晉孫楚故太傅羊祜碑曰：禀二儀之純靈，膺造化之冲氣，文為辭宗，行作世表，遷黃門侍郎，受秘書監，公筭滅吳之略，以為孟獻營虎牢而鄭人懼，晏弱城東陽而萊子服，乃進據险處，开建五城，收膏腴之地，奪敵人之資，於是江浦馳義，襁負而至，雖研精軍政，用思滅敵，然兼立學校，闡扬典訓，是以搢紳之士，鱗集仰化，雲翔衡門，雖泮宮之詠魯侯，菁莪之美育才，無以過也，銘曰：金德發曜，惟公作辅，肇建嘉謨，建我民主，不慚遺公，俾屏聖皇，哲人其徂，孰不增傷。","sortOrder":52},
  {"id":"s_work_nvlt_46_53","chapterId":"ch_work_nvlt_46","text":"周王褒太傅燕文公於謹碑銘曰：古者六等官人，師傅崇其匡辅，一命作牧，侯伯總其专征，南仲成薄伐之功，吉甫作來歸之頌，若乃仰葉宸曜，上屬台階，錫之以彝器，明之以車服，除名盛業，太傅燕國公其有焉，西晔开其命緒，東海傳其世祿，父曾致平法之科，廷尉稱無冤之頌，驷馬方駕，高門繼軌，公禀山嶽之上靈，含風雲之秀氣，雕良玉於廉刿，煉貞金於鎏鋈，於時王業締構，國步權舆，太祖地雖二分，功猶再駕，忠誠簡帝，有志興王，公運策帷帳，參謀幕府，封齊定文成之計，間楚資曲逆之奇，仲華訪舆地之圖，林叔參兵車之右，魏恭帝元年，為大司寇，正刑糾慝，國無害馬之倫，翦暴詰奸，民亡飲羊之俗，三刺荐無簡之文，兩造陳禁邪之憲，大周受命，寶歷攸歸，表高惠之功臣，紀山河之著命，封燕公，邑萬戶，姬氏建國，君奭始封，昭王禮賢，郭隗开馆。又授太傅，本官如先，保定五年，賜金石樂一部，公世為邊將，少習兵書，當敵製機，臨戎應变，增壘减竈之圖，題树系桑之略，軍中罢戰，無废雅歌，壮士志驕，時觀投石，及乎名高衛霍，爵重韓彭，錫邑增於鄭侨，賜乘同於魏絳，丹節比司隸之貴，緹綺將金吾之寵，座闕倡歌之娱，堂無鍾鼓之奏，辭功坐树，不伐征西之勋，還第角巾，無競龍驤之賞，銘曰：惟嶽降神，膺期命世，量苞川藪，道弘兼濟，昴宿协符，佐旌冥契，匪躬谅直，武節橫厲，函崤重险，鍾鼎淪覆，潛龍勿用，瞻乌在室，道贊上台，功匡下渎，條教斯理，彝倫載睦，懋官惟德，明试以功，既移上將，實董元戎，傳呼甚寵，徽章載隆，居高能降，處貴思冲，寶命惟新，王猷允塞，爵班異姓，禮均同德，林胡以南，易川之北，帝曰爾諧，俾侯燕國，骎骎過隙，滔滔逝川，明哲詎寶，馆舍長捐，立言不没，遺愛在旃，三河斥土，驷馬开泉，丹旒毀宗，玄堂啟殯，寵赠虛加，鸞和空引，晏子悼齊，隋武懷晉，謂天蓋高，如何不慭。","sortOrder":53},
  {"id":"s_work_nvlt_46_54","chapterId":"ch_work_nvlt_46","text":"【表】陳沈蜅為陳太傅讓表曰：奏六代之舞，不能祚天，具百神之歌，無以動聖，延首當閽，轉增危栗，百川沸騰，百室如毀，釋位同謀，諸侯總至，盟書會府，餘臣一人，若使幅巾衡巷，口絕平吳，朝遊赤松，暮過濟北，出就侯服，入禠龍章，則四郊有壘，誰守社稷，如其雄戟在前，強弩自衛，負孺子之圖，飾緣鹡［《初學記》十一陳大科本作鶴。］之鼎，軍威重於護將，國禮貴於寒門，則臣道尚卑，孰雲非逼，臣所以出謝公卿，入訓妻子，拜長陵之園，謁太祖之廟，不以九族违恩義，不以百姓負國家，所期陛下與北極同寿，朝廷與南山同固。","sortOrder":54},
  {"id":"s_work_nvlt_46_55","chapterId":"ch_work_nvlt_46","text":"◇太保","sortOrder":55},
  {"id":"s_work_nvlt_46_56","chapterId":"ch_work_nvlt_46","text":"應劭《漢官》曰：太保，古官，保，養也。","sortOrder":56},
  {"id":"s_work_nvlt_46_57","chapterId":"ch_work_nvlt_46","text":"《呂氏春秋》曰：荆文王得茄［《太平御覽》二百零六作如，下同。］黃之狗，宛路之矰，以田於雲夢，三月不返，得丹陽之姬，暮［御覽作期，下同。］年不聽朝，保申曰：先王以臣為保，今王暮年不聽朝，王之罪當笞，王伏，臣將笞王，王曰：敬诺，保申束細箭五十，跪而加之於背，如此者再，謂王曰：起矣，王曰：有笞之名一也，遂致之，保申曰：君子恥之，小人痛之，恥之不变，痛之何益，保申趨出，請死罪，文王曰：此不穀之過也，保申何罪，王乃殺茄黃之狗，折宛路之矰，放丹陽之姬，兼國三十九，保申之力也。","sortOrder":57},
  {"id":"s_work_nvlt_46_58","chapterId":"ch_work_nvlt_46","text":"《贾誼書》曰：天子處位不端，受業不敬，教誨諷誦書禮不經不法，言語不序，凡此其屬太保之任也。","sortOrder":58},
  {"id":"s_work_nvlt_46_59","chapterId":"ch_work_nvlt_46","text":"王隱《晉書》曰：王祥，字休徵，琅邪人，泰始元年，拜太保，三年春，御史中丞侯史光上言曰：祥久以疾病闕废朝會，應免官，詔曰：太保，朕所毗倚以隆道弘治者也，前後遜讓，不從所執，此非有司所得議也。","sortOrder":59},
  {"id":"s_work_nvlt_46_60","chapterId":"ch_work_nvlt_46","text":"齊職官儀曰：太保，品秩冠服同太宰，成王即位，召公為太保，召誥雲，越三日戊申，太保朝於洛，《逸禮》曰：太公為太師，周公為太傅，召公為太保。","sortOrder":60},
  {"id":"s_work_nvlt_46_61","chapterId":"ch_work_nvlt_46","text":"沈約《宋書》曰：太師太傅太保為三公，訓護天子，导以德義，天子加拜，待以不臣之禮，非人則闕矣，漢製，保傅在三公上，號曰上公，自後常然。","sortOrder":61},
  {"id":"s_work_nvlt_46_62","chapterId":"ch_work_nvlt_46","text":"【碑】周王褒太保吳武公尉遲綱碑銘曰：昔者王室藩屏，周德謂之宗親，列國諸侯，異姓稱為伯舅，元勋懿德，姬崇齊楚之霸，疏爵畴庸，漢重韓吳之秩，司勋載其洪烈，典册備其徽章，山甫式列辟之功，絕跡庸器，莊叔匡成獻之難，昭德彝鼎，鸿名盛業，公實兼焉，公命世挺生，應期間出，嵩華峻極，降惟嶽之上靈，霜露所均，體中和之秀氣，危松擢本，且觀後彫之质，貞桂挺生，便體冬華之秀，是故以辰昴膺慶，風雲玄感者焉，公柔順內凝，英華外發，斧藻仁義，珪璋令范，危劲之節，貫四序而逾秀，堅貞之操，經百煉而不銷，加以逵門射法，遠中戟支，養由箭神，遙穿懸葉，巧極將軍之伎，精窮校尉之官，及年逾艾服，任隆台袞，甲第當衢，傳呼啟路，不以寵貴驕人，每以卑恭自牧，易箦之言，無忘寢瘵，城郢之志，終於瞑目，銘曰：珠角應期，山庭表德，出忠入孝，自家形國，人物冠冕，彝章表則，任屬屯警，官聯極侍，行部六條，議班三吏，逝水詎停，光陰不借，遽辭逆旅，俄悲怛化，旌舒夏練，棺陳衛幕，北郭人希，西山景落，三千不見，九原誰作，銘茲鼎鼐，永傳嵩霍。","sortOrder":62},
  {"id":"s_work_nvlt_46_63","chapterId":"ch_work_nvlt_46","text":"又太子太保中都公陆逞碑銘曰：公本居三吳郡三吳縣，丞相遜後也，宋武匡定鍾鼎，底平涵洛，公曾祖載，實贊軍謀，及反旆南轅，以司武留守，赫連作亂，見拘夏州，以江右名家，為中山太守，地既鮮虞，途通靈寿，呼沱易水，仗武乘邊，趙北燕南，申威河外，祖營州使君，長於戎馬，稱雄朔漢，南中都督，猶缵弈世之基，西校國門，無墜承家之業，公識度深詳，摽尚閒遠，處眾捴謙，居簡行敬，風鑒外明，潛機內敏，建章門戶，張華成立，［按當作立成。］原陵松柏，虞延盡記，昔處文房。又居內職，或傳冰華，時遊甲邸，魏祖軍謀，還豫南陂之宴，梁王師傅，猶對宣室之談，出內優隆，通籍榮寵，升降榮步，便煩官禁，銘曰：淮海惟楊，具區之藪，水朝江漢，星纏牛斗，盛德遺風，神明厥後，龍章八命，鸞旂四牡，賓階昔遇，風月相思，卿門今別，宿草何悲，輪環不已，零落無時，永矣元伯，長從此辭。","sortOrder":63},
  {"id":"s_work_nvlt_46_64","chapterId":"ch_work_nvlt_46","text":"周庾信太保雁門公紇幹弘碑曰：公本姓田氏，虞賓在位，基於揖讓之風，鳳皇於飛，紹於親賢之國，論其繼世之功，則狄城有廟，序其移家之始，則長陵有碑，况复高廟上書，小車而對漢祖，聊城祭鳥，長兵而驅燕將，公以胎教之月，歲德在宮，誕載之辰，星精出昴，既而受書黃石，意在王者之師，揮劍白猿，心存霸國之用，常原執金鼓而問吳王，橫琱戈而反齊地，有志不就，忠貞死焉，銘曰：移苗返葬，提柩山行，靈墟隴水，哀挽長城，山如北望，树似東平，松門石起，碑字金生，眇眇山河，茕茕胤子，泣血徒步，奔波千里，孝水先枯，悲雲即起，世數存没，哀榮終始。","sortOrder":64},
  {"id":"s_work_nvlt_46_65","chapterId":"ch_work_nvlt_46","text":"◇祭酒","sortOrder":65},
  {"id":"s_work_nvlt_46_66","chapterId":"ch_work_nvlt_46","text":"韦昭辯《釋名》曰：祭酒者，謂祭六神，以酒醊之也，辯雲，凡會同饗宴，必尊長先用，先用必以酒祭先，故曰祭酒，漢時，吳王年長，以為劉氏祭酒是也。","sortOrder":66},
  {"id":"s_work_nvlt_46_67","chapterId":"ch_work_nvlt_46","text":"《漢書》曰：張安世荐蘇武明習故事，奉使不辱命，先帝以為遺言，宣帝即位時，召武侍官［漢書五十四。］蘇武傳作宦，者署，數進見，复為右曹典屬國，以武苦節老臣，令朝朔望，號稱祭酒，甚優寵之。","sortOrder":67},
  {"id":"s_work_nvlt_46_68","chapterId":"ch_work_nvlt_46","text":"《風俗通》曰：詩禮春秋，至齊襄王時，而孫卿最為老師，齊尚循列大夫之缺，而孫卿三為祭酒也。","sortOrder":68},
  {"id":"s_work_nvlt_46_69","chapterId":"ch_work_nvlt_46","text":"《蜀志》曰：先主既定益州，廣漢太守夏纂，請秦宓［原訛奏密，據冯校本改。］為師友祭酒。","sortOrder":69},
  {"id":"s_work_nvlt_46_70","chapterId":"ch_work_nvlt_46","text":"百官表註曰：博士祭酒一人，掌國子學，早朝服進賢兩梁冠，佩水蒼玉，秦燔書籍，而置博士之官，博者，博通於藝事也。","sortOrder":70},
  {"id":"s_work_nvlt_46_71","chapterId":"ch_work_nvlt_46","text":"齊職儀曰：晉令，博士祭酒，掌［《太平御覽》二百三十六掌下有國子學三字。］國子生師事祭酒，執經，葛巾单衣，終身致敬。","sortOrder":71},
  {"id":"s_work_nvlt_46_72","chapterId":"ch_work_nvlt_46","text":"沈約《宋書》曰：博士，秦官也，常通古今，員多至數十人，有仆射，光武增為十五人，蓋一經有數家之學故也，皆教弟子，光武改仆射曰祭酒，祭酒者，一位之元長也。","sortOrder":72},
  {"id":"s_work_nvlt_46_73","chapterId":"ch_work_nvlt_46","text":"【表】齊王融為王俭讓國子祭酒表曰：竊以庠均義重，振古所崇，資師道尊，有來攸尚，匪曰蘭芷，畴变入室之情，不自朱藍，何遷素絲之质。","sortOrder":73},
  {"id":"s_work_nvlt_46_74","chapterId":"ch_work_nvlt_46","text":"又表曰：况臣仁慚富侣，德謝润身，識漏令經，器非匣重，何以昇墜道於殊身，反斯文於遙日，將使良璣脩竹，無增瑩羽，敬遜務時，遂騫星歲。","sortOrder":74},
  {"id":"s_work_nvlt_46_75","chapterId":"ch_work_nvlt_46","text":"又表曰：臣聞脩危［疑當作卮。］方湛，弱露霑而取覆，懸衡紀正，輕尘委而必移，况臣才非應俗，用乖知治，取其集木飲冰，旌懸輪骛，方臣之念，未足言矣。","sortOrder":75},
  {"id":"s_work_nvlt_46_76","chapterId":"ch_work_nvlt_46","text":"後魏溫子昇為安丰王延明讓國子祭酒表曰：臣聞寶劍未砥，猶乏切玉之功，美箭闕羽，尚無冲石之势，况才非會稽之竹，质謝崑吾之金，至於敷教東序，流訓上庠，置樽候酌，懸鍾待叩，必須蘊朱藍以成彩，立規矩以為式，垂三行於貴遊，扬六藝於胄子，而臣學媿聚沙，問慚攻木，雖歷文史，不治章句，於茲曠官，青衿何仰。","sortOrder":76},
  {"id":"s_work_nvlt_46_77","chapterId":"ch_work_nvlt_46","text":"◇博士","sortOrder":77},
  {"id":"s_work_nvlt_46_78","chapterId":"ch_work_nvlt_46","text":"應劭《漢官儀》曰：博士，秦官也，博者，通博古今，士者，辯於然否，孝武帝建元五年，初置五經博士，太常差次有聰明威重者一人為祭酒，總領綱紀。","sortOrder":78},
  {"id":"s_work_nvlt_46_79","chapterId":"ch_work_nvlt_46","text":"《漢書》曰：贾誼，洛陽人，年十八，以能誦詩屬書，稱於郡中，文帝召以為博士，是時年二十餘，最為少，每詔令議下，諸老先生未能言，誼盡能為之對，人人各如其意所出。","sortOrder":79},
  {"id":"s_work_nvlt_46_80","chapterId":"ch_work_nvlt_46","text":"又曰：公孫弘對策時百餘人，太常奏弘第居下，天子擢之，弘對為第一，召入見，容貌甚麗，拜為博士，待詔金馬門。","sortOrder":80},
  {"id":"s_work_nvlt_46_81","chapterId":"ch_work_nvlt_46","text":"《東觀漢記》曰：桓榮授皇太子經，每朝，令榮於公卿前說經，上曰：得卿幾晚，因除博士。","sortOrder":81},
  {"id":"s_work_nvlt_46_82","chapterId":"ch_work_nvlt_46","text":"范晔《後漢書》曰：董均，永平初為博士，時草創五郊祭祀，及宗廟禮樂，威儀章服，辄令鈞參議，多見從用，為當世通儒。","sortOrder":82},
  {"id":"s_work_nvlt_46_83","chapterId":"ch_work_nvlt_46","text":"李郃別傳曰：郃上書太後，數陳忠言，其辭不能盡施用，辄有策詔褒贊焉，博士著兩梁冠，朝會隨將大夫例，時賤經學，博士乃在市長下，公奏以為非所以敬儒，明國體也，上善公言，正月大朝，引博士公府長史前。","sortOrder":83},
  {"id":"s_work_nvlt_46_84","chapterId":"ch_work_nvlt_46","text":"《漢舊儀》曰：武帝初置博士，取學通行脩，博識多藝，晓古文《爾雅》能屬文章，為高第，朝贺位次中都官史，［《太平御覽》二百三十六作吏。］稱先生，不得言君，其真弟子稱門人。","sortOrder":84},
  {"id":"s_work_nvlt_46_85","chapterId":"ch_work_nvlt_46","text":"又曰：孝文皇帝時，博士七十餘人，朝服玄端，章甫冠。","sortOrder":85},
  {"id":"s_work_nvlt_46_86","chapterId":"ch_work_nvlt_46","text":"《晉令》曰：博士皆取履行清通，淳明典義，若散騎中書侍郎太子中庶子以上，乃得召试，諸生有法度者，及白衣，试在高第，拜郎中。","sortOrder":86},
  {"id":"s_work_nvlt_46_87","chapterId":"ch_work_nvlt_46","text":"魯國先賢傳曰：漢文帝時，聞申公為詩最精，以為博士，申公為詩傳，號曰魯詩。","sortOrder":87},
  {"id":"s_work_nvlt_46_88","chapterId":"ch_work_nvlt_46","text":"《典略》曰：公儀休者，魯博士也，為魯相，無所变更，百官自正，使食祿者，不得與下爭利。","sortOrder":88},
  {"id":"s_work_nvlt_46_89","chapterId":"ch_work_nvlt_46","text":"殷氏《世傳》曰：殷亮，建武中，徵拜博士，遷講學大夫，諸儒講論，勝者賜席，亮重席至八九，帝嘉之曰：學不當如是耶。","sortOrder":89},
  {"id":"s_work_nvlt_46_90","chapterId":"ch_work_nvlt_46","text":"《郭子》曰：張凭舉孝廉，請劉真長還舡，須臾，真長至，遣觅張孝廉舡，同旅愕然，既同載，俱詣撫軍，劉前進，謂撫軍曰：為公得一士，太常博士之妙選，既前，撫軍與之言，咨嗟稱善，乃曰：張凭勃窣為理窟，即用為太常博士。","sortOrder":90},
  {"id":"s_work_nvlt_46_91","chapterId":"ch_work_nvlt_46","text":"【箴】漢楊雄博士箴曰：典禮是脩，盡為辟雍，國有學校，侯有泮宮，名有伋教，德用不陵，昔在文王，經營其軌，勖於德音，而思皇多士，多士作楨，惟周以寧，國人興讓，虞芮质成，公劉挹行潦，洒濁亂斯清，官摻其業，士執其經，昔聖人之綏俗，莫美於施化，故孔子觀夫人之學，而知為王之易大舜南面無為，而衽席平，還師階間，三苗以懷，秦作無道，斬决天紀，漫彼王跡，而坑術士。","sortOrder":91},
  {"id":"s_work_nvlt_46_92","chapterId":"ch_work_nvlt_46","text":"【表】梁丘遲為王博士讓表曰：臣聞撫臆可以言心，量能則知所止，是故矯親魯門，簡業事亡，雜吹齊稚，分聲遽逝，臣才行過污，文质無廉，疏達謝於穀杜，浃洽乖夫劉楊，非除部養之勤，豈通掌固之業。","sortOrder":92},
  {"id":"s_work_nvlt_46_93","chapterId":"ch_work_nvlt_46","text":"《藝文類聚》　唐·欧陽詢","sortOrder":93},
  {"id":"s_work_nvlt_47_1","chapterId":"ch_work_nvlt_47","text":"卷四十七職官部三","sortOrder":1},
  {"id":"s_work_nvlt_47_2","chapterId":"ch_work_nvlt_47","text":"○大司馬司徒司空儀同特進","sortOrder":2},
  {"id":"s_work_nvlt_47_3","chapterId":"ch_work_nvlt_47","text":"◇大司馬","sortOrder":3},
  {"id":"s_work_nvlt_47_4","chapterId":"ch_work_nvlt_47","text":"韦昭辯《釋名》曰：大司馬，司馬，武也，大，總武事也，大司馬掌軍，古者兵車一車四馬，故以馬名官。","sortOrder":4},
  {"id":"s_work_nvlt_47_5","chapterId":"ch_work_nvlt_47","text":"《春秋運斗枢》曰：黃帝與大司馬容光，觀鳳衔圖，置黃帝前。","sortOrder":5},
  {"id":"s_work_nvlt_47_6","chapterId":"ch_work_nvlt_47","text":"《尚書》曰：司馬掌邦政，統六師，平邦國。","sortOrder":6},
  {"id":"s_work_nvlt_47_7","chapterId":"ch_work_nvlt_47","text":"《周官》曰：大司馬之職，掌以九伐之法，正邦國。","sortOrder":7},
  {"id":"s_work_nvlt_47_8","chapterId":"ch_work_nvlt_47","text":"《毛詩》曰：祈父，予王之爪牙。","sortOrder":8},
  {"id":"s_work_nvlt_47_9","chapterId":"ch_work_nvlt_47","text":"《管子》曰：涼風至，白露下，天子命左右司馬，全組甲，励士眾。","sortOrder":9},
  {"id":"s_work_nvlt_47_10","chapterId":"ch_work_nvlt_47","text":"《漢書》：百官表曰：武帝元狩四年，初置大司馬，以冠軍印綬置官屬，成帝綏和元年，賜大司馬金印綬，置官屬，祿比丞相。","sortOrder":10},
  {"id":"s_work_nvlt_47_11","chapterId":"ch_work_nvlt_47","text":"《東觀漢記》曰：今以平狄將軍孫鹹，行大司馬事，以名應讖。","sortOrder":11},
  {"id":"s_work_nvlt_47_12","chapterId":"ch_work_nvlt_47","text":"王隱《晉書》曰：石苞，泰始之初，拜大司馬，舊參軍於都督無敬，故孫楚抗衡於苞，苞以楚傲，更相表理，參軍有敬，自楚始也。","sortOrder":12},
  {"id":"s_work_nvlt_47_13","chapterId":"ch_work_nvlt_47","text":"《晉中興書》曰：王猛少貧賤，鬻畚為事，嘗至洛陽货畚，有人於市貴買其畚，雲家近在此，可隨我取直，隨去，忽至深山，此人曰：且住，當先啟道君，須臾猛進，見一公踞胡床，頭白，將從十許人，有一人引猛，雲大司馬公可進，猛因拜老公，公曰：王公何緣拜，即十倍售畚直，發人送猛出山，既出顧视，乃嵩高山也。","sortOrder":13},
  {"id":"s_work_nvlt_47_14","chapterId":"ch_work_nvlt_47","text":"《博物志》曰：太公望為灌壇令，文王夢見婦人當道哭，問其故，曰：吾泰山之神也，嫁為西海婦，灌壇今當吾道，不得作風雨，夢覺，召太公，是日果疾風暴雨，文王乃拜太公為大司馬。","sortOrder":14},
  {"id":"s_work_nvlt_47_15","chapterId":"ch_work_nvlt_47","text":"晉公卿禮秩曰：司馬，大台兵官也，魏氏大司馬大將軍各自為官，在三司上，晉以石苞為大司馬，次三司下。","sortOrder":15},
  {"id":"s_work_nvlt_47_16","chapterId":"ch_work_nvlt_47","text":"齊職官儀曰：大司馬品第一，秩二千石，金章紫綬，武冠，絳佩［太平御覽二百零九佩字無］朝服，佩山玄玉，其在少昊，則雎鳩氏之任，颛頊以司馬主火，尧命羲叔為司馬，夏官也，虞夏二代，以司馬夏官，弃居其職，周成王以畢公高為司馬，楚漢之际，曹無咎周殷，始居其職。","sortOrder":16},
  {"id":"s_work_nvlt_47_17","chapterId":"ch_work_nvlt_47","text":"【诔】後漢杜篤大司馬吳漢诔曰：篤以為尧隆稷契，舜嘉皋陶，伊尹佐殷，呂尚翼周，若此五臣，功無與畴，今漢吳公，追而六之，乃作诔曰：朝失鯁臣，國丧牙爪，天子愍悼，中宮咨嗟，四方殘暴，公不征茲，征茲海內，公其攸平，泯泯群黎，賴公以寧，勋業既崇，持盈守虛，功成即退，挹而損諸，死而不朽，名勒丹書，功著金石，與日月俱。","sortOrder":17},
  {"id":"s_work_nvlt_47_18","chapterId":"ch_work_nvlt_47","text":"魏陳王曹植大司馬曹休诔曰：於穆公侯，魏之宗室，明德繼踵，弈世純粹，闡弘汎愛，仁以接物，藝以為華，體茲亮實，年没弱冠，志在雄英，高揖名師，發言有章，東夏翕然，稱曰龍光，貧而無怨，孔以為難，嗟我公侯，屢空是安，不耽世祿，親悅為懽，好彼蓬枢，甘此瓢箪，味道忘忧，逾憲超顏，矯矯公侯，不桡其厄，呵叱三軍，躬奋雄戟，足蹴白刃，手接飛鏑，終弭淮南，保我疆埸。","sortOrder":18},
  {"id":"s_work_nvlt_47_19","chapterId":"ch_work_nvlt_47","text":"晉陆機吳大司馬陆抗诔曰：我公承軌，高風肅邁，明德繼體，徽旨弈世，昭德伊何，克俊克仁，德周能事，體合機神，禮交徒候，敬睦白屋，踧踖曲躬，吐食揮沐，爰及鳏寡，赈此惸獨，孚厥惠心，脱驂分祿，乃命我公，誕作元辅，位表百辟，名茂群後，因是荆人，造我寧宇，備物典策，玉冠及斧，龍旂飛藻，靈鼓树羽，质文殊涂，百異行彻，人玩其華，鮮識其實，於穆我公，因心則哲，經纶至道，終始自結，德與行滿，英與言溢。","sortOrder":19},
  {"id":"s_work_nvlt_47_20","chapterId":"ch_work_nvlt_47","text":"【章】梁簡文帝為南平王拜大司馬章曰：臣度連宸萼，地寔璿跗，王業權舆，夙奉締構，爰頒盧綰，同贊密謀，豫均邓禹，俱奉明詔，故摶飛九萬，實假扶搖之力，冲天百尺，無俟剞劂之勞。","sortOrder":20},
  {"id":"s_work_nvlt_47_21","chapterId":"ch_work_nvlt_47","text":"◇司徒","sortOrder":21},
  {"id":"s_work_nvlt_47_22","chapterId":"ch_work_nvlt_47","text":"《尚書》曰：百姓不親，五品不遜，汝作司徒，敬敷五教，在宽。","sortOrder":22},
  {"id":"s_work_nvlt_47_23","chapterId":"ch_work_nvlt_47","text":"又曰：司徒掌邦教，敷五典，扰兆民。","sortOrder":23},
  {"id":"s_work_nvlt_47_24","chapterId":"ch_work_nvlt_47","text":"《周官》曰：大司徒，以土圭之法测土深，日至之景，尺有五寸，謂之地中，天地之所合，四時之所交也，風雨之所會，陰陽之所和也，然則百物阜安，乃建王國焉。","sortOrder":24},
  {"id":"s_work_nvlt_47_25","chapterId":"ch_work_nvlt_47","text":"《禮記》曰：司徒修六禮，以節民性，明七教，以興民德，齊八政以防淫，一道德以同俗，養老以致孝。","sortOrder":25},
  {"id":"s_work_nvlt_47_26","chapterId":"ch_work_nvlt_47","text":"《毛詩》曰：緇衣，美武功［詩鄭風作公。］也，以明有國善善之功，管子曰：昔者黃帝得祝融，辨南方，故使為司徒。","sortOrder":26},
  {"id":"s_work_nvlt_47_27","chapterId":"ch_work_nvlt_47","text":"《東觀漢記》曰：袁安為司徒，每朝會，忧念王室，未嘗不流涕。","sortOrder":27},
  {"id":"s_work_nvlt_47_28","chapterId":"ch_work_nvlt_47","text":"又曰：郭丹為司徒，在朝名清廉公正。","sortOrder":28},
  {"id":"s_work_nvlt_47_29","chapterId":"ch_work_nvlt_47","text":"《續漢書》曰：司徒公一人，掌人民事，凡教民孝悌遜順謹俭，養生送死，事則議其製，建其度，凡四方民事功課，歲盡，則奏其殿最而行賞罰，凡郊祀之事，嘗省牲视濯。","sortOrder":29},
  {"id":"s_work_nvlt_47_30","chapterId":"ch_work_nvlt_47","text":"謝承《後漢書》曰：劉寵為司徒，臥粗布被。","sortOrder":30},
  {"id":"s_work_nvlt_47_31","chapterId":"ch_work_nvlt_47","text":"蔡邕鍾鼎銘序曰：惟建寧四年三月，進公登於玉堂前庭，乃製詔曰：其以司空乔玄為司徒，公拜稽首，三讓，然後受命。","sortOrder":31},
  {"id":"s_work_nvlt_47_32","chapterId":"ch_work_nvlt_47","text":"《典略》曰：契為司徒，百姓和親，夔主賓客，遠人畢至。","sortOrder":32},
  {"id":"s_work_nvlt_47_33","chapterId":"ch_work_nvlt_47","text":"《九州春秋》曰：靈帝賣官，崔烈入錢五百萬，以買司徒，烈子均，亦有世名，烈問曰：吾作三公，天下論何如，均曰：大人少有高名，不謂不當為公，但海內嫌銅臭爾。","sortOrder":33},
  {"id":"s_work_nvlt_47_34","chapterId":"ch_work_nvlt_47","text":"《吳錄》曰：丁固為司徒，初為尚書，夢松出其腹，謂人曰：松字十八公，後十八年，吾其公乎，遂如夢。","sortOrder":34},
  {"id":"s_work_nvlt_47_35","chapterId":"ch_work_nvlt_47","text":"王隱《晉書》曰：魏舒為司徒，年過致仕，有謙謙意，而無居宅，乃漸以俸秩餘為第一所，九年正月，朝會罢，送還家，奉送章綬。","sortOrder":35},
  {"id":"s_work_nvlt_47_36","chapterId":"ch_work_nvlt_47","text":"又曰：武帝以山涛為司徒，頻讓不許，涛出，径歸家，左丞白襃，奏涛违詔，詔杖襃五十。","sortOrder":36},
  {"id":"s_work_nvlt_47_37","chapterId":"ch_work_nvlt_47","text":"又曰：王戎代王浑為司徒，高選長史西曹掾，委任责成，形状短陋，而目明澈。威儀不足，常乘馬轝，無日不出，以象牙筭晝夜筭計家财，遠及田牧，性又俭，不能善自奉養，飲食通财不外出，天下之人謂之膏肓之病。","sortOrder":37},
  {"id":"s_work_nvlt_47_38","chapterId":"ch_work_nvlt_47","text":"《晉中興書》曰：劉隗從兄畴，字王乔，有重名，司空蔡謨每叹曰：若使劉王乔得南渡，司徒公之美選也。","sortOrder":38},
  {"id":"s_work_nvlt_47_39","chapterId":"ch_work_nvlt_47","text":"又曰：蔡謨讓司徒，孝帝臨軒，自平旦至日中，使者十餘反，而謨不至，孝帝時年八歲，甚怒之極，問左右曰：所召何以不至，今來臨軒，何時當竟，皇太後詔曰：必不來者，宜罢朝，中軍殷浩奏曰：免吏部尚書江彪官，於是公卿奏送謨廷尉，以正刑書，謨懼，率子弟，素服詣闕，到廷尉待罪，詔可依舊製，免為庶人。","sortOrder":39},
  {"id":"s_work_nvlt_47_40","chapterId":"ch_work_nvlt_47","text":"齊職儀曰：司徒，品秩冠服同丞相，郊廟服冕同太尉，漢哀帝從朱博議，始置三司，改丞相為大司徒，以孔光為之，魏以華歆為司徒。","sortOrder":40},
  {"id":"s_work_nvlt_47_41","chapterId":"ch_work_nvlt_47","text":"江氏家傳曰：江統，字應元，時太傅從事中郎庾子嵩，以風韻見重，亦併雅敬君德，庾中郎每雲，當今可以居司徒，充民望者，江生其人也。","sortOrder":41},
  {"id":"s_work_nvlt_47_42","chapterId":"ch_work_nvlt_47","text":"【箴】漢崔骃司徒箴曰：天監在下，仁德是哀，乃立司徒，亂茲蒸黎，茫茫庶域，率土祁祁，民具爾瞻，四方是維，乾乾夕惕，靡怠靡违，恪恭爾職，以勤王機，敬敷五教，九德鹹事，啬民用章，黔萌是富。","sortOrder":42},
  {"id":"s_work_nvlt_47_43","chapterId":"ch_work_nvlt_47","text":"【碑】宋傅亮司徒劉穆之碑曰：公讳穆之，字道和，彭城人也，公膺陶鈞之秀范，該生民之上操，三变肇於弱容，九德充於初迪，文明在中，柔順畅於事業，敬以直內，義讓洽於州党，時元凶竄遁，擁據荆沔，乘舆播幸，越蹈九江，公率先群後，電發川湄，奖懷本之眾，励思奋之士，桓謙籍累葉之資，徐覆忸骤勝之鋒，習亂之徒，若猬毛而起，內懷根本之虞，外通首尾之势，公靈武獨運，奇謨內湛，鞠旅陳眾，视险若夷，飛雲西溯，則水截鯨鲵，乘轅東指，則陆殪長蛇，回累棋之危，成維山之固，丰功茂勋，大造於王室，淳風懿化，永結於荆南，銘曰：二儀發揮，川嶽协靈，外恢溫雅，內鏡文明，懷仁履順，蘊義居貞，煌煌袞衣，禮亦隆止，翼翼素心，亮終如始，夷情升降，一色慍喜，訓俭於物，复禮於己。","sortOrder":43},
  {"id":"s_work_nvlt_47_44","chapterId":"ch_work_nvlt_47","text":"【墓志】後魏溫子昇司徒元树墓志銘曰：昔枢電降祥，姬水成業，握八符以馭世，膺五命以會昌，钦明格於上下，光宅被於宇宙，卜年永久，歷世遐長，有文王之孫子，啟周公之苗裔，積善所及，踵武稱賢，每以辛李為言，恒持韓白自許，殫百慮之一致，盡能事於生民，而蒼蒼在上，義歸無厚，徒有東平避世之意，空懷北海自晦之情，疾非逢霧，終異啟手，銘曰：明允篤誠，發於岐嶷，未鏤已雕，不扶而直，脩禮以耕，強學為殖，孔既叹魯，莊亦吟越，况以度思，有懷明發，翻然高舉，歸於魏闕，長路未窮，朝光已没。","sortOrder":44},
  {"id":"s_work_nvlt_47_45","chapterId":"ch_work_nvlt_47","text":"又司徒祖瑩墓志曰：自天命生商，王居徙亳，源流毖遠，枝葉繁華，祖德润於身，聲高邦國，父行成於己，名重京師，公鍾美多福，資神積善，器局閒靈，志識开悟，口含碧雞之辯，手握雕龍之聲，門有善業，家傳慶靈，砺金成器，相遺滿籝，琢玉為寶，待价聯城，匪直也人，實惟有道，言折秋毫，辭連春藻。","sortOrder":45},
  {"id":"s_work_nvlt_47_46","chapterId":"ch_work_nvlt_47","text":"梁沈約為司徒謝朏墓志銘曰：嶽神昔降，和氣今鍾，以彼天爵，鬱為人龍，崇墓往峻，世德今重，漢車作傳，靈位攸待，我君應符，非公莫宰，華袞既袭，輕萝自改，形雖廟堂，心猶江海，經邦已備，皇情回屬，素騑輟柳，玄雲罢曲。","sortOrder":46},
  {"id":"s_work_nvlt_47_47","chapterId":"ch_work_nvlt_47","text":"【诔】後漢張衡司徒呂公诔曰：昔呂皇祖，帝交之緒，伯夷秩唐，唐宗允叙。四嶽在虞，傅土佐禹，克厭帝心，姓薑氏呂，登是南邦，以家以處，降及於周，穆侯作辅，寡於九族，九族用寧，登受八命，袞職靡傾，黃耳金铉，公餗以盈，綽兮其冤，曒兮其清，既明且哲，式保令名，斿旍從風，驷牡超驤，去此寧宇，歸於幽堂，玄室冥冥，脩夜弥長。","sortOrder":47},
  {"id":"s_work_nvlt_47_48","chapterId":"ch_work_nvlt_47","text":"梁簡文帝司徒始興忠武王诔曰：皇源地闡，帝業天維，於穆忠武，光國之基，爰自弱齡，英明播越，玉润冰鮮，山靜雲發，帝曰爾諧，佥議彼屬，推轂兩江，建旗三蜀，將旋上國，恋結四民，三鳣表服，二鹿隨輪，方变正袞，永范時規，天弗報善，哲人其萎，响哀挽於北邙，去承明而不入，望參差之旒影，聽潺湲之雨泣。","sortOrder":48},
  {"id":"s_work_nvlt_47_49","chapterId":"ch_work_nvlt_47","text":"【章】宋謝莊北中郎新安王拜司徒章曰：不惟震施罔匮，鸿慶方稠，燮調之重，遂臻非據，智小謀大，周家興規，少陽微暄，有鑒前史，辨其動植，布其安扰，以倡九牧，阜成王教，豈臣眇末，所能克荷。","sortOrder":49},
  {"id":"s_work_nvlt_47_50","chapterId":"ch_work_nvlt_47","text":"又為北中郎將謝兼司徒章曰：臣聞燮理陰陽，寅亮天地，弗惟其官，無人則闕，司徒掌敷五典，職扰兆民，豈悟乾靈罔匮，光渥方闡，不次之任，殊絕藩嶽，豈可權尸三事，假備六符，慚震周回，顧步交悸。","sortOrder":50},
  {"id":"s_work_nvlt_47_51","chapterId":"ch_work_nvlt_47","text":"【表】吳筠楊州建安王讓知司徒表曰：臣聞玄黃之馬，事絕於衔鑣，蟠朽之材，飾乖於丹漆，何則，千里之志已窮，萬乘之器無取，遠物遂身，於焉在譬。","sortOrder":51},
  {"id":"s_work_nvlt_47_52","chapterId":"ch_work_nvlt_47","text":"後魏溫子昇為司徒高敖曹謝表曰：委水橫流，群龍交戰，徒悲道丧，空懷主辱，雖复見義援戈，臨危奋劍，顧慚後衄，終謝先鞭，事等泣河，無救三川之竭，有類忧天，豈支四極之坏。","sortOrder":52},
  {"id":"s_work_nvlt_47_53","chapterId":"ch_work_nvlt_47","text":"北齊邢子才為潘司徒樂讓表曰：武皇帝運屬繼元，事深微禹，摧蚩尤之陣，破尋邑之師，義开金石，理勖庸骀，遂日奉羁勒，有事風尘，徒備鳥背之毛，曾無馬箠之力。","sortOrder":53},
  {"id":"s_work_nvlt_47_54","chapterId":"ch_work_nvlt_47","text":"◇司空","sortOrder":54},
  {"id":"s_work_nvlt_47_55","chapterId":"ch_work_nvlt_47","text":"《春秋元命包》曰：危東六星，兩兩而比，曰司空，主水。","sortOrder":55},
  {"id":"s_work_nvlt_47_56","chapterId":"ch_work_nvlt_47","text":"《尚書》曰：佥曰：伯禹作司空，帝曰：俞，咨禹，汝平水土，惟時懋哉。","sortOrder":56},
  {"id":"s_work_nvlt_47_57","chapterId":"ch_work_nvlt_47","text":"又曰：司空掌邦土，居四民，時地利。","sortOrder":57},
  {"id":"s_work_nvlt_47_58","chapterId":"ch_work_nvlt_47","text":"《禮記》曰：司空執度，度地以居民，量地遠近，興事任力。","sortOrder":58},
  {"id":"s_work_nvlt_47_59","chapterId":"ch_work_nvlt_47","text":"尚書刑德放曰：禹長於地理，水泉九州，得括象圖，故尧以為司空。","sortOrder":59},
  {"id":"s_work_nvlt_47_60","chapterId":"ch_work_nvlt_47","text":"《家語》曰：孔子初仕為中都宰，二年，定公以為司空，乃別五土之性，而物其所生之宜，鹹得厥所。","sortOrder":60},
  {"id":"s_work_nvlt_47_61","chapterId":"ch_work_nvlt_47","text":"《漢書》曰：御史大夫，秦官，副丞相，成帝綏和九年，更名大司空，祿比丞相。","sortOrder":61},
  {"id":"s_work_nvlt_47_62","chapterId":"ch_work_nvlt_47","text":"《東觀漢記》曰：杜林代張純為大司空，務於無為，弟五倫為司空，奉公不撓，言事無所依违。","sortOrder":62},
  {"id":"s_work_nvlt_47_63","chapterId":"ch_work_nvlt_47","text":"《續漢書》曰：張奋為司空，時歲灾旱，祈雨不應，乃上表，即時引見，复口陳時政之宜，帝召太尉司徒，幸洛陽獄，錄囚徒，大雨三日。","sortOrder":63},
  {"id":"s_work_nvlt_47_64","chapterId":"ch_work_nvlt_47","text":"又曰：王梁，字君嚴，赤伏符曰：王梁作玄武，玄武水神，大司空水土之官也，於是拜梁為大司空。","sortOrder":64},
  {"id":"s_work_nvlt_47_65","chapterId":"ch_work_nvlt_47","text":"袁宏漢紀曰：弟五倫為司空，有人與倫千里馬者，倫雖不取，每三公有所選舉，倫心不忘也，然亦終不用。","sortOrder":65},
  {"id":"s_work_nvlt_47_66","chapterId":"ch_work_nvlt_47","text":"華峤《後漢書》曰：伏恭為太仆，帝臨辟雍，於行禮中，拜恭為司空，儒者以為榮。","sortOrder":66},
  {"id":"s_work_nvlt_47_67","chapterId":"ch_work_nvlt_47","text":"《魏志》曰：徐邈拜司空，叹曰：三公論道之官，無其人則闕，豈可以老病忝之哉，固辭不受。","sortOrder":67},
  {"id":"s_work_nvlt_47_68","chapterId":"ch_work_nvlt_47","text":"《典略》曰：禹為司空，披九山，通九泽，决九川，定九州，使各以其職來貢。","sortOrder":68},
  {"id":"s_work_nvlt_47_69","chapterId":"ch_work_nvlt_47","text":"《華陽國志》曰：趙瑤，字元珪，自扶風太守來之郡，司空張溫謂曰：弟五倫［《太平御覽》二百零八作伯，此訛。］魚從蜀郡為司空，今扫吾第，以待足下。","sortOrder":69},
  {"id":"s_work_nvlt_47_70","chapterId":"ch_work_nvlt_47","text":"荀氏家傳曰：荀爽，字德明，董卓徵公，公到府三日，策拜司空，起巖穴九十五日，而為台司，世人號曰白衣登三公。","sortOrder":70},
  {"id":"s_work_nvlt_47_71","chapterId":"ch_work_nvlt_47","text":"《晉中興書》曰：陆玩，字士瑤，王导郄鑒庾亮相繼殂，朝野忧懼，鹹以為三良既没，國基墜矣，於是遷玩侍中司空，給羽林四十人，玩比陳讓，不聽，既拜，叹息謂賓客曰：以我為三公，是天下無人也，談者以為知言。","sortOrder":71},
  {"id":"s_work_nvlt_47_72","chapterId":"ch_work_nvlt_47","text":"齊職儀曰：司空，品秩冠服同太宰，舜以禹為司空，成王以毛公為司空，宋以武公之讳，改司空為司城，楚改司空為莫敖，秦置御史大夫，省司空。","sortOrder":72},
  {"id":"s_work_nvlt_47_73","chapterId":"ch_work_nvlt_47","text":"【贊】魏楊脩司空荀爽述贊曰：生應正性，體含中和，篤誠宣於初言，明允朗於始察，是以在童龀而顯奇，漸一紀則布名，頃幼［疑當作項他。］之可師，甘羅之少者，何以逾公之性量乎，砥心六經，探索道奧，瞻乾坤而知陰陽之極，載而集之，獨說十萬餘言，士林景附，群英式慕，由毛羽之宗鵬鸞，眾山之仰五嶽也，昔楚思叔敖而作歌，鄭謳子產而興叹，瞻望弗及，作詞告思，詞曰：爰在大漢，挺荀作貞，其德允明，誕發幼齡，行蠲體絜，如玉之瑩，確乎其志，乃励乃清，遂陟司空，天子是毗，惟君之德，朋僚所咨，清水平土，茂哉是力，將混六合，繩以正直，散以禮樂，夙以道德。","sortOrder":73},
  {"id":"s_work_nvlt_47_74","chapterId":"ch_work_nvlt_47","text":"晉孫綽贺司空脩［《初學記》十一作循。］像贊曰：公應天縱之德，系命世之期，质與荆玉參貞，鑒與南金等照，若其好學之性，不勸而成，弱不珍玩，雅好博古，慨洙泗之邈遠，悼禮樂之不舉，於是覃思深講，銳精幽贊，雖齊孝之歸孟軻，漢王之宗仲舒，無以加焉，贊曰：思文公侯，誕保休祥，素质玉絜，華藻金章，總角韞德，被褐韜光，自昔丧亂，征鼓日震，禮樂藏器，詩書蒙尘，哲人遐慨，垂幕澄神，仰觀洙泗，扬波絕津，方曜金铉，协贊衡機，旻天不弔，曾不慭遺，搢紳頹范，皇德莫毗，公之雲徂，華裔同悲。","sortOrder":74},
  {"id":"s_work_nvlt_47_75","chapterId":"ch_work_nvlt_47","text":"【箴】漢楊雄司空箴曰：昔彼坤靈，併天作合，分製五服，盡為萬國，乃立地官，空惟是職，烈烈俊乂，翼翼王臣，臣當其官，官當其人，九一之政，七賦以均。","sortOrder":75},
  {"id":"s_work_nvlt_47_76","chapterId":"ch_work_nvlt_47","text":"【銘】後漢蔡邕東海銘曰：桥玄為司空公，越在先民，毗佐天子，罔不著其股肱，畢其思心，式率天行，式昭德音。","sortOrder":76},
  {"id":"s_work_nvlt_47_77","chapterId":"ch_work_nvlt_47","text":"【表】宋謝莊東海王讓司空表曰：臣侧觀前載，與窥洪典，三事之授，惟帝其難，臣乘少籍長久，分逾涯量，出滿入泰，每究榮光，不悟乾燭方遠，義路同遺，下參弘化，上尸燮理，自非德仞具瞻，聲湛民詠，未有妄臻此泽，空集茲靈，齊孔稚珪為王敬則讓司空表曰：故李通豪贍，以親寵登司，王基才勇，與聲華入選，先帝擢臣以榮華，陛下伸臣以富貴，遂得北帶五州，東跨六郡，內亚三鼎，外齊四嶽，蝉佩之映，則左右交暉，龟組之華，則縱橫吐耀，輕輪徐動，則劍騎如雲，飛蓋暫停，則歌鍾成列，摐金龍吹鬱其前，鳴笳鳳管叠其後，邓禹若不遭漢光，則南陽之掾吏，微臣若不逢明聖，則孤城之式客，豈可加以正台之席，登以論道之寄，啟黃扉而燮五緯，躡青帷而調四序。","sortOrder":77},
  {"id":"s_work_nvlt_47_78","chapterId":"ch_work_nvlt_47","text":"梁劉孝儀為臨川王解司空表曰：臣以庸薄，谬竊隆重，職班三事，任總六條，衣袞坐槐，既闕論道，馳傳憩棠，尤慚為政，而俯司土地，仰燮陰陽，棟桡之譏已彰，愆伏之咎爰著，今水沴乃作，旱魃為灾，山無薈蔚，雲成煙火，陛下曲私，未垂策免，臣職是當，逃责，［《太平御覽》二百零八作於何逃责。］乞降茲台步，协此天人。","sortOrder":78},
  {"id":"s_work_nvlt_47_79","chapterId":"ch_work_nvlt_47","text":"梁江淹為齊高帝讓司空表曰：臣聞日發星回，昊天無以爽其節，山盈川冲，厚地不能虧其度，陛下停若鏡之明，流如雲之暧，方求士於版巖，宜思賢於蜀肆。","sortOrder":79},
  {"id":"s_work_nvlt_47_80","chapterId":"ch_work_nvlt_47","text":"又北齊邢子才為司空景讓表曰：屬平分廣施，造物多品，長短入用，小大見收，連采台階，堪均鼎足，昨見謫見垂象，灾起潛伏，此之為累，非直微躬。","sortOrder":80},
  {"id":"s_work_nvlt_47_81","chapterId":"ch_work_nvlt_47","text":"【碑】後漢蔡邕司空袁逢碑曰：凡所臨君，明而先覺，故能教不肅而化成，政不嚴而事治，其惠和也晏晏然，其博大也洋洋焉，信可謂兼三才而該刚柔，無射於人斯矣，銘曰：天鑒有漢，賜茲世辅，顯允厥德，昭胤休序，峨峨雍宮，禮樂備舉，穆穆天子，孝敬允叙，降拜屏著，奉饋西序，威儀聿脩，化溢區宇，乃尹京邑，總齊禁旅。","sortOrder":81},
  {"id":"s_work_nvlt_47_82","chapterId":"ch_work_nvlt_47","text":"又為司空房楨碑銘曰：公言非法度，不出於口，行非至公，不萌於心，治身則伯夷之絜也，俭啬則季文之約也，盡忠則史魚之直也，刚平則山甫之励也，總茲四德，式是百辟，夙夜匪懈，以事一人，枉絲發，树私恩，不為也，讨無禮，當彊御，弗避也，是以功隆名顯，在世孤特，不獲恺悌宽厚之譽，享年垂老，至於積世，門無立車，堂無宴客，衣不变裁，食不兼味，雖易之貞厲，詩之羔羊，無以加也，明明在公，寔惟房後，誕應正德，式作漢辅，邪慝是仇，直亮是與，刚則不吐，柔則不茹，媚茲天子，以靖［原訛請，據冯校本改。］土宇。","sortOrder":82},
  {"id":"s_work_nvlt_47_83","chapterId":"ch_work_nvlt_47","text":"晉潘嶽司空鄭袞碑曰：陳謨台階，翼和鼎實，顯績成於台省，清風畅於所莅，故能老安少懷，遠至邇親，凡厥搢紳之士，所以挹酌洪流，含咀英芳者，猶旱苗之仰膏雨，湛露之晞朝陽也，銘曰：於鑠元侯，則天垂象，弘操嶽峻，宇量深廣，允恭克讓，宣哲清朗，有始有卒，可大可久，言由忠信，行履孝友，光光金貂，再冠其首，赫赫皇符，仍拆其部，義格皇穹，德冠群後，清風顯烈，没而不朽。","sortOrder":83},
  {"id":"s_work_nvlt_47_84","chapterId":"ch_work_nvlt_47","text":"晉孫綽庾司空冰碑曰：君喻嵩巖之玄精，挹清瀨之絜流，貞质謀於白珪，明操励於南金，雖名器未極，而任盡臣道，正身提衡，鈐括百揆，知無不為，謀必鮮過，端委待旦，則有心宣孟，以約訓俭，則擬議季文，君平恒無私，己謙寡欲，當世之所難，於君易之矣，於是慨然遠覽，量己而退，高挹帷幕，投跡藩屏，夫良玉以經焚不渝，故其貞可貴，竹柏以蒙霜保榮，故見殊列树，治而不亂者有矣，未有亂而弥治者也，考終以證始，即事以徵心，少長能一其度，貴賤不二其道，文康之雅量，於是乎弘著矣，銘曰：洋洋俊潁，巖巖神嵩，流涤淳氣，頗扇祥風，篤生公侯，情靈德充，臨川擬絜，仰華思崇，履险思夷，處滿思冲，方恢遠猷，皇極是贊，繁霜夏被，脩梧摧幹，人之雲徂，朝野鹹叹，儀形永戢，光風長煥，梁劉孝綽司空安成康王碑銘曰：昔者重華文命，併胄高陽之苗，丰邑舂陵，俱纂帝尧之緒，而虞夏革運，姚姒之姓已分，高光再興，大漢之名無改，如我皇家，梁齊代建，異文叔之紹开，起自王族，非伯禹之更姓，公則本枝別幹，誕自河嶽，五百之期，實膺命世，卜商有問，是謂色難，承志望顏，在公斯易，至如文琰之對食餘，幼權之言爵里，衛子之朗月映山，杜生之凝脂點漆，惟公具美，歷駕前修，峨峨焉非嶽陵之所至，浩浩焉總江漢而為長，故能击水三千，摶風九萬，排天關而俯眡，掩浮雲而上征，皇帝甄名挺聖，河洛有徵，握衡含枢，奄一時夏，利建藩屏，固葉深根，郕霍酆郇，方周啟祚，封公為安成王，食邑二千戶，允同衛叔，賜寶器於商郊，殊異應侯，戲桐珪於汾水，乃公為平西將軍荆州刺史，楚之對齊，屈完引城池之固，荆之比宋，墨翟陳輦路之殊，品金作貢，不異淮海，珠璣犀象。又無求於晉國，况以雲夢九百之宏侈，章華三休之巨麗，公御煩以寡，居高而降，執冲虛之道，無矜滿之情，其為政也，莊敬足以范物，慈惠足以庇民，刚毅足以威暴，清貞足以励俗，天鑒十七年薨，春秋四十有五，凡我庶民，竊親高義，况复祗承帝命，來仕王家，兔園晚春，叨從者之賜，高唐暮天，而奉作賦之私，常懼慶雲之惠不酬，而搖落奄至，豈謂經尘之效莫展，而峻極先頹，思所以立言貞石，貽厥長世，銘曰：昔在文韶，五賢二聖，漢藩魏屏，微風不競，於赫我梁，德符姬姓，康王康叔，異時同盛，爰自妙年，令問不已，一孝一悌，寔光行始，義府文場，詞人髦士，波澜莫际，牆仞難窥，用茲先覺，导此後知，德大心小，居高志卑，再握不倦，三吐忘疲，飛龍在天，肇基宛渎，地猶小胏，民同世复，皇情睠正，屬難推轂，允矣宗英，移藩改牧，誰謂路永，江漢已浮，彼蒼不惠，遽反成周，川回溯舳，涂引歸旒。","sortOrder":84},
  {"id":"s_work_nvlt_47_85","chapterId":"ch_work_nvlt_47","text":"【墓志】宋謝莊司空何尚之墓志曰：遠源長澜，自晉徂韓，潛川韜玉，霍岫騰鸞，處華民瞻，出光帝難，寂寞寿仁，茫昧報施，調於飪歸，經難褰寄，晻暎留芳，煙煴作義。","sortOrder":85},
  {"id":"s_work_nvlt_47_86","chapterId":"ch_work_nvlt_47","text":"陳徐陵司空章昭達墓志銘曰：周原膴々，佳氣葱葱，王業攸興，帝圖斯盛，在昔光武佐命，鄰縣者邓侯，高祖元臣，同郡者萧相，公台辅之量，便著綺紈，瑚璉之姿，無待雕琢，起家為東宮直前，所奉之君，則梁簡文皇帝，既而黑山巨盜，凭陵上國，白水彊胡，虔劉中夏，公傾其產業，慕是驍雄，思報皇储，累殲鯨寇，屬幽［本集作豳。］風有象，代邸方降，搜荆楚之英才，資班输之妙略，百樓忽起，登雲霄而俯臨，萬弩俱張，隨雷霆而併震，扬兵於九天之上，决勝於千里之中，殪彼群凶，皆無旋踵，陳寶應至懷反叛，客引周迪，資其食力，更事窥窬，公奉詔崇朝，飲冰將力，前茅後劲，步骤奔馳，仍向甌閩，殄其巢窟，若夫鳴蛇之洞，深穀隱於蒼天，飛猿之嶺，乔树參於雲日，宜越艇而登峤，蒙燕犀而涉江，威武紛紜，震山風海，於是鹹俘伪帥，悉據高墉，爰洎沧溟，莫不懲乂，既而齊人無信，將謀郢藩，斗艦戈舡，窥江淹漢，公才聞羽檄，遽禀師期，馳袭荆郧，應時燒荡，方欲宣威隴汧，大讨梁華，屬上將之韜光，逢中台之掩曜，大建三年，薨於軍幕，爾乃青乌相墓，白鹡標墳，林有逃車，树同華蓋，前旍熊軾，後乘龍轜，介士發三河之民，哀鐃同驷馬之曲，長安傳坐，恩禮盛於西京，襄陽墮淚，悲恸喧於南峴。","sortOrder":86},
  {"id":"s_work_nvlt_47_87","chapterId":"ch_work_nvlt_47","text":"【诔】後漢張衡司空陳公诔曰：敬仲初育，發繇卜筮，鳳飛觀國，流光末裔，天祚明德，德茂於公，入孝出友，爰肅爰邕，兼學多識，窮理知機，德音孔昭，翻爾灰飛，賦政二城，還集皇闈，公寔省之，亹亹庶績，公寔靜之，藹藹百僚，公寔愍之，乃陟司空，纂禹之跡，导楊徽庸，致訓京畿，协和萬邦，萬邦既协，殊服來同，眇論前績，莫與比蹤。","sortOrder":87},
  {"id":"s_work_nvlt_47_88","chapterId":"ch_work_nvlt_47","text":"【行状】梁任昉齊司空曲江公行状曰：公禀靈景宿，擅氣中和，一匮初登，東嶽之功可監，埏埴在器，瑚璉之姿先表，豈惟荆南有聖童之目，襄城著孔甫之稱而已哉，故以羽儀宗家，冠蓋後進，路叔之一日千里，北海之稱美共治，方斯蔑如也，志學之年，偏治經記，登隆千載，網羅百氏，藻斯贍逸，蔚為詞宗，延贾誼而升堂，携相如而入室，加以翰牍精辯，發言有章，持論從容，辭無矜尚，自河洛丘墟，歷載二百，俾我逢掖，遂淪左衽，晉宋所以遺恨，祖宗是用顧懷，公自荷方任，志在剋复，將欲使功遂之日，身退有所，爰乃卜宇金陵，萦帶林壑，用辭聊城之賞，以為疏韓之馆，人謝運往，遂輟遠圖。","sortOrder":88},
  {"id":"s_work_nvlt_47_89","chapterId":"ch_work_nvlt_47","text":"梁沈約齊司空柳世隆行状曰：公禀靈華嶽，幼挺珪璋，清襟素履，發乎龆丱，及長風质洞遠，儀止祥華，動容合矩，吐言被律，時沈攸之狼據陝西，氣陵物上，而太祖登庸作宰，天歷在躬，攸之播封豕之情，總令荆之力，兕甲十萬，鐵馬千群，水陆長骛，志窥皇邑，公抗威川涘，勇略紛紜，顯晦有方，出没無緒，攸之乃反旆亘围，親受矢石，增橹乘埤，嚴冲駕雉，雲輣俯阚，地穴斜通，半藏晚餐，負戶晨汲，公乃綏眾以武，應敵以奇，靈鋒電曜，威策雲舉，事切三版之危，氣損九天之就，殘寇外老，逆党內離，焚舟委甲，掬指宵遯，公風標秀彻，器范弘润，茂乎辭彩，雅善鼓琴，摛純蔡之高芬，纂鍾稽之妙曲，雖婴拂世務，而素業無改，臨姑蘇而想八桂，登衡山而望九嶷，七紆邦組，三臨荡甸，五職瑞扇，一司百揆，固可以齊衡八凯，方駕五臣。","sortOrder":89},
  {"id":"s_work_nvlt_47_90","chapterId":"ch_work_nvlt_47","text":"◇儀同","sortOrder":90},
  {"id":"s_work_nvlt_47_91","chapterId":"ch_work_nvlt_47","text":"《東觀漢記》曰：邓骘，字昭明，［《太平御覽》二百四十三作伯。］延平元年，拜為車騎將軍，儀同三司，儀同三司始自骘也。","sortOrder":91},
  {"id":"s_work_nvlt_47_92","chapterId":"ch_work_nvlt_47","text":"王隱《晉書》曰：太始七年，以鄭襄［《太平御覽》二百四十三作袤，下同。］為司空，天子臨軒，遣使就第拜授襄，襄推讓，上送印綬，至於十數，久之見許，以侯就第，儀同三司，置舍人官騎，賜床帳簟縟。","sortOrder":92},
  {"id":"s_work_nvlt_47_93","chapterId":"ch_work_nvlt_47","text":"齊職儀曰：开府儀同三司，秦漢無聞，始建初三年，馬防為車騎將軍，儀同三司事，魏以黃權為車騎开府，此後甚眾，將軍开府，依大司馬，朱服，光祿大夫开府，依司徒，皂服。","sortOrder":93},
  {"id":"s_work_nvlt_47_94","chapterId":"ch_work_nvlt_47","text":"【墓志】簡文帝儀同徐勉墓志銘曰：朱弓表瑞，寶劍攸歸，長澜斯註，瓜瓞含辉，舉直斥伪，校名责實，朝有進賢，野無遺逸，违天即地，歸幽去明，空穀傳古，哀風送旍。","sortOrder":94},
  {"id":"s_work_nvlt_47_95","chapterId":"ch_work_nvlt_47","text":"【章】齊王俭拜儀同三司章曰：臣聞日中則昃，盈虛之定分，器滿必傾，往复之恒理，遂乃班同袞章，燮和台曜，外參論道，內總百司，切議惟尘，自識非據。","sortOrder":95},
  {"id":"s_work_nvlt_47_96","chapterId":"ch_work_nvlt_47","text":"梁庾肩吾為武陵王拜儀同章曰：臣宅慶紫霄，聯休皇極，地均指日，既無跡而成高，仕若乘風，故不行而自遠，今者四郊無壘，天下同文，都尉春田，猶居塞外，单於冬獵，不入漁陽，臣坐牧三邊，非勞七戰，豈能屯兵大夏，封萬里之侯，飛箭遼城，受千金之寿，論其才望，有懼茂弘，光佩印校，常羞叔度。","sortOrder":96},
  {"id":"s_work_nvlt_47_97","chapterId":"ch_work_nvlt_47","text":"【表】梁王筠為王儀同瑩初讓表曰：執玉獻金，卒先五等，親冕迎轺，光导百辟，坐階遠大，遂致隆滿，自位昇朝首，職冠禮闡，辭滿之原將际，致仕之請方奏，而思渥恩眦，昭奖必被，寵章爰降，朝野驚矚，是以安石歸禾固請，元規終以致讓，况臣才质空疏，器量庸淺，而可以妄參铉席，靦貌槐庭。","sortOrder":97},
  {"id":"s_work_nvlt_47_98","chapterId":"ch_work_nvlt_47","text":"梁沈約為始興王讓儀同表曰：徒尘翠渥，方降紫泥，以茲上令，用隔下情，况高擬萬石，爰均八命，室等天黃，服加黼黻，出則高陪千乘，入則仰司百揆，陛下道苞九舜，明出十尧，萬徽必理，一物興念，有紆玄鏡，蹔垂止水。","sortOrder":98},
  {"id":"s_work_nvlt_47_99","chapterId":"ch_work_nvlt_47","text":"梁王僧孺為南平王讓儀同表曰：臣聞石瓠難剖，用謝瓶罍，瘣木雲庇，事乖丹雘，逢聖徼天，一朝賞至，非能聲均河楚，譽埒梁陳，故以神夢紫霄，心飛丹掖，品同儀比，媿铉莫殊。","sortOrder":99},
  {"id":"s_work_nvlt_47_100","chapterId":"ch_work_nvlt_47","text":"陳沈蜅為周儀同失律後复官讓表曰：日者驂驚鄭馬，害在晉軍，獄囚悲其夜數，缧人切其晓奏，危光似燭，察命如絲，雲誰之尤，自貽其咎，假令誅以妻子，戮及墳墓，漢非負德，陵實孤恩，况伏锧俯眉，遂受淮陰之問，吞聲飲恨，不與臧洪共死，陛下怜而宥之，伊臣豈不獨愧，丧其子弟，六謝父兄，百萬之師，千夫有長，問臣安在，誰曰董司，魂遊奉高，不知何對。","sortOrder":100},
  {"id":"s_work_nvlt_47_101","chapterId":"ch_work_nvlt_47","text":"隋江總太保萧公謝儀同表曰：陂泉野戰，曾無汗馬之勞，代邸運筹。又闕前歌之勇，薄伐专征，早遊邊外，執玉奉酎，文虧朝則，王人降止，朝册遠臨，奉述敕書，曲停表奏，沧波阻敻，既杜敬仲之辭，關路攸長，致絕趙襄之讓，心馳紫路，登文石而莫由，目送白雲，拜承明而未日。","sortOrder":101},
  {"id":"s_work_nvlt_47_102","chapterId":"ch_work_nvlt_47","text":"◇特進","sortOrder":102},
  {"id":"s_work_nvlt_47_103","chapterId":"ch_work_nvlt_47","text":"漢雜事曰：諸侯功德優盛，朝廷所敬異者，賜位特進，在三公下。","sortOrder":103},
  {"id":"s_work_nvlt_47_104","chapterId":"ch_work_nvlt_47","text":"百官表註曰：特進，官品第二，漢製，皇後之父，率為此官。","sortOrder":104},
  {"id":"s_work_nvlt_47_105","chapterId":"ch_work_nvlt_47","text":"傅鹹集曰：特進，執皮帛，坐侍臣之下，門下屬，漢武特進執璧，已有舊製，今特進宜執璧。","sortOrder":105},
  {"id":"s_work_nvlt_47_106","chapterId":"ch_work_nvlt_47","text":"齊職儀曰：特進，以功德特進見也。","sortOrder":106},
  {"id":"s_work_nvlt_47_107","chapterId":"ch_work_nvlt_47","text":"沈約《宋書》曰：特進，魏世驃騎將軍劉放衛將軍孫資等遜位，以侯就第，蓋位特進，其諸官加特進者，從本官供給，特進但為班位而已，不別有吏卒車服也。","sortOrder":107},
  {"id":"s_work_nvlt_47_108","chapterId":"ch_work_nvlt_47","text":"【墓志】梁孝元帝特進萧琛墓志銘曰：山東流水，關西城市，義府辭鋒，風飛雲起，遊楚宦梁，桂馥蘭芳，莲花可賦，迷迭成章，學類五行，書倅三箧，已研金匮，兼探玉牒，石詞既擬，栾社茲同，桃李成径，松柏為藂，天地長久，永扇高風。","sortOrder":108},
  {"id":"s_work_nvlt_47_109","chapterId":"ch_work_nvlt_47","text":"隋江總特進光祿大夫徐陵墓志銘曰：耕耘書囿，弋獵文場，藻思綺合，尺牍繡扬，辭奔太史，筆利幹將，心緘武库，口定雌黃，奉使巡采，絕域遐深，市朝遷貿，陵穀相侵，形寄王績，多宣攀附，高排閶阖，鬱轉雲路，年逾致仕，齒及懸車，夜漏方盡，馳光复斜，平原出宿，庠序為家，隴愁宿霧，松悲閒鳥，地迥雲低，山重树小，九原孤月，三泉送旐，畴曩行役，共上河梁，餘因病免，君事遠將，痛心期之徂謝，悯時代之銷亡，冀镌石於玄冢，留清風於故乡。","sortOrder":109},
  {"id":"s_work_nvlt_47_110","chapterId":"ch_work_nvlt_47","text":"《藝文類聚》　唐·欧陽詢","sortOrder":110},
  {"id":"s_work_nvlt_48_1","chapterId":"ch_work_nvlt_48","text":"卷四十八職官部四","sortOrder":1},
  {"id":"s_work_nvlt_48_2","chapterId":"ch_work_nvlt_48","text":"○錄尚書尚書令仆射吏部尚書尚書吏部郎侍中黃門侍郎散騎常侍給事中中書令中書侍郎驃騎","sortOrder":2},
  {"id":"s_work_nvlt_48_3","chapterId":"ch_work_nvlt_48","text":"◇錄尚書","sortOrder":3},
  {"id":"s_work_nvlt_48_4","chapterId":"ch_work_nvlt_48","text":"應劭《漢官儀》曰：章帝詔曰：司空牟融，典職六年，勤勞不怠，其以融為太尉，錄尚書。","sortOrder":4},
  {"id":"s_work_nvlt_48_5","chapterId":"ch_work_nvlt_48","text":"又曰：和帝策書曰：故太尉邓彪，元公之族，三讓弥高，海內歸仁，為群賢首，其以彪為太尉，錄尚書事，百官總己以聽。","sortOrder":5},
  {"id":"s_work_nvlt_48_6","chapterId":"ch_work_nvlt_48","text":"又曰：殇帝策書曰：司徒徐防，以台閣機密，施政牧守，其以防為太尉，錄尚書事，百官總己以聽。","sortOrder":6},
  {"id":"s_work_nvlt_48_7","chapterId":"ch_work_nvlt_48","text":"又曰：冲帝策書曰：太尉趙峻，二世常典機衡，有匪石不貳其心，大司農李固，公族之苗，忠貞不回，今以峻為太傅，固太尉，參錄尚書事。","sortOrder":7},
  {"id":"s_work_nvlt_48_8","chapterId":"ch_work_nvlt_48","text":"又曰：靈帝策書曰：故太尉陳蕃，忠亮謇諤，有不吐茹之節，司徒胡廣，敦德允元，五世從政，今以蕃為太傅，與廣參錄尚書事。","sortOrder":8},
  {"id":"s_work_nvlt_48_9","chapterId":"ch_work_nvlt_48","text":"王隱《晉書》曰：贾充為太尉，錄尚書，五年伐吳，為大都督，吳平，上遣侍中程鹹犒勞，增邑八千戶。","sortOrder":9},
  {"id":"s_work_nvlt_48_10","chapterId":"ch_work_nvlt_48","text":"《晉中興書》曰：明帝後庾氏，為皇太後，九月癸卯，皇太後臨朝，製司徒王导，錄尚書事。","sortOrder":10},
  {"id":"s_work_nvlt_48_11","chapterId":"ch_work_nvlt_48","text":"沈約《宋書》曰：高祖永初三年，尚書令扬州刺史徐羨之為司空，錄尚書事。","sortOrder":11},
  {"id":"s_work_nvlt_48_12","chapterId":"ch_work_nvlt_48","text":"又曰：孝武帝即位，以大將軍江夏王義恭為太尉，錄尚書事。","sortOrder":12},
  {"id":"s_work_nvlt_48_13","chapterId":"ch_work_nvlt_48","text":"又曰：諸公錄尚書事，古製也，王肅解尚書納於大麓曰：尧納舜於尊顯之官，使大錄萬機之政，案漢氏諸吏，平尚書奏事，後霍光以大司馬大將軍平尚書事。","sortOrder":13},
  {"id":"s_work_nvlt_48_14","chapterId":"ch_work_nvlt_48","text":"傅畅故事曰：何劭王戎張華裴楷楊濟和峤，為愍懷太傅，通省尚書事，張華為光祿大夫，尚書七條事，皆谘而後行，惠帝之世，太保衛瓘，太宰河間王顒，太傅東海王越，皆錄三省尚書秘書事。","sortOrder":14},
  {"id":"s_work_nvlt_48_15","chapterId":"ch_work_nvlt_48","text":"【表】齊謝朓為明帝拜錄尚書表曰：升降玉階，對扬休命，六辔在手，千里何偕，司會天官之統，尚書百僚之本，弘之即庶績惟凝，替之則彝倫斯斁，修身踐言，本慚五美，果行育德，未階六正，妄屬負圖之寄，多謝五仁之績，操桧楫於龍津，荷梓梁於雲構，無以辅位明堂，遺象麟閣。","sortOrder":15},
  {"id":"s_work_nvlt_48_16","chapterId":"ch_work_nvlt_48","text":"【啟】陳徐陵安成王讓錄尚書表後啟曰：臣聞間平就國，乃盛漢之常儀，郕霍無官，實宗周之明典，何則，皇季之重，非待歷階，王爵之隆，自高群辟，况臣戢翼要荒，亟離寒暑，進慚趙勝，能定楚從，退匪齊文，馳免秦厄，固以內切皇心，外貽家恥，甘输重餌，降禮单於，迾城十五，如諸和璧，市乡三十，聊同寶劍，武夫力而獲諸原，微臣還而反諸敵，瞻言馬駿，著隴右之功，追念曹彰，克乌丸之虜，前王子弟，若此勋庸，偏其反而，豈可勝愧。","sortOrder":16},
  {"id":"s_work_nvlt_48_17","chapterId":"ch_work_nvlt_48","text":"◇尚書令","sortOrder":17},
  {"id":"s_work_nvlt_48_18","chapterId":"ch_work_nvlt_48","text":"《漢書》曰：張安世，字子孺，少以父任為郎，因善書，令給事尚書，精力於職，休沐未嘗出，行幸河東，亡書三箧，詔問莫能知，唯安世識之，具作其事，後購求得書，以相校，無所遺失，上奇其才，擢尚書令。","sortOrder":18},
  {"id":"s_work_nvlt_48_19","chapterId":"ch_work_nvlt_48","text":"漢雜事曰：尚書黃香，為東郡太守，乞留宿衛，拜為尚書令，秩二千石。","sortOrder":19},
  {"id":"s_work_nvlt_48_20","chapterId":"ch_work_nvlt_48","text":"漢官儀職曰：尚書令，主贊奏，總典綱紀，無所統，秩二千石。","sortOrder":20},
  {"id":"s_work_nvlt_48_21","chapterId":"ch_work_nvlt_48","text":"《東觀漢記》曰：侯霸為尚書令，深見任用，樊准為尚書令，明習漢家舊事，周密畏慎，申屠刚為尚書令，謇謇多直言，無所屈桡。","sortOrder":21},
  {"id":"s_work_nvlt_48_22","chapterId":"ch_work_nvlt_48","text":"又曰：永平七年，宋均徵為尚書令，忠正直言，數納策謀，每駮議，未嘗不合上意。","sortOrder":22},
  {"id":"s_work_nvlt_48_23","chapterId":"ch_work_nvlt_48","text":"張璠《漢書》曰：左雄為尚書令，限年四十，先试經，然後舉孝廉。","sortOrder":23},
  {"id":"s_work_nvlt_48_24","chapterId":"ch_work_nvlt_48","text":"《續漢書》曰：陳蕃出為豫章太守，性方峻，不接賓客，徵為尚書令，送者不出郭門。","sortOrder":24},
  {"id":"s_work_nvlt_48_25","chapterId":"ch_work_nvlt_48","text":"百官表曰：尚書令，是謂文章［《初學記》十一作昌。］天府，銅印墨綬，五時朝服，納言帻，進賢兩梁冠，佩水蒼玉，總攝諸曹，出納王命，敷奏萬機，書曰：龍，命汝納言，夙夜出納朕命，惟允，詩雲，惟仲山甫，王之喉舌，蓋此謂也。","sortOrder":25},
  {"id":"s_work_nvlt_48_26","chapterId":"ch_work_nvlt_48","text":"《魏志》曰：明帝即位，進陳峤為尚書令，車駕常幸，至尚書門，峤跪問帝曰：陛下何之，帝曰：欲案行文書耳，峤曰：此自臣職分，非陛下所宜臨也，若臣不稱其職，則請就黜退，陛下宜還，帝慚，回車而返。","sortOrder":26},
  {"id":"s_work_nvlt_48_27","chapterId":"ch_work_nvlt_48","text":"又曰：太祖進荀彧為漢侍中，守尚書令。","sortOrder":27},
  {"id":"s_work_nvlt_48_28","chapterId":"ch_work_nvlt_48","text":"又曰：裴潛為尚書令，奏正分職，簡名實，出事使斷官府者，百五十餘條。","sortOrder":28},
  {"id":"s_work_nvlt_48_29","chapterId":"ch_work_nvlt_48","text":"費禕別傳曰：禕代蒋琬為尚書令，以朝脯聽事，其間接納賓客，加之博弈不废，後董允代之，旬日之間，事多愆積，允曰：人之才力，相懸若此。","sortOrder":29},
  {"id":"s_work_nvlt_48_30","chapterId":"ch_work_nvlt_48","text":"曹羲九品議曰：尚書，尊官也，親作納言，易曰：枢機之發，榮辱之主，漢和帝，南陽左雄為尚書令，天下皆慎選舉，選舉所知，自其職也。","sortOrder":30},
  {"id":"s_work_nvlt_48_31","chapterId":"ch_work_nvlt_48","text":"山涛啟事曰：尚書令李胤，遷處，缺宜得其人，征南將軍羊祜，體義玉立，可以肅整朝廷。","sortOrder":31},
  {"id":"s_work_nvlt_48_32","chapterId":"ch_work_nvlt_48","text":"王隱《晉書》曰：樂廣為尚書令，所在無當時之功譽，然為後人所思。","sortOrder":32},
  {"id":"s_work_nvlt_48_33","chapterId":"ch_work_nvlt_48","text":"又曰：鹹寧二年，李胤為尚書令，雖歷職內外，而在公退食，家室至貧俭，兒病，無以市藥，上賜錢十萬，齊職儀曰：秦漢之世，委政公卿，尚書之職，掌於封奏，令贊文書，仆射主开閉，令不在，則仆射奏下其事，魏氏重內職，八座尚書，任同六卿，舜舉八元八凯，以隆唐朝，令［《太平御覽》二百十作今。］號八座為元凯，謂以賢能用事，義如昔也。","sortOrder":33},
  {"id":"s_work_nvlt_48_34","chapterId":"ch_work_nvlt_48","text":"【箴】晉挚虞尚書令箴曰：舜納大麓，七政以齊，內成外平，風雨不迷，補我袞闕，闡我王繇，王繇允塞，四海鹹休，雖聖雖明，必賴良才，無曰我智，官不能任，發言如絲，其出成纶，千里之應，枢機在身。","sortOrder":34},
  {"id":"s_work_nvlt_48_35","chapterId":"ch_work_nvlt_48","text":"【碑】後漢潘勖尚書令荀彧碑曰：夫其為德也，則主忠履信，孝友溫惠，高亮以固其中，柔嘉以宣其外，廉慎以為己任，仁恕以察人物，踐行則無轍跡，出言則無辭費，納規無敬辱之心，機情有密靜之性，若乃奉身蹈道，勤禮貴德，動咨事間，匪雲予克，然後教以黃中之叡，守以貞固之直，註焉若洪河之源，不可竭也，確焉若華嶽之停，不可拔也，故能言之斯立，行之斯成，身匪隆污，直哉惟情，紊綱用亂，废禮复經，於是百揆時序，王猷允塞，告厥成功，用俟萬歲。","sortOrder":35},
  {"id":"s_work_nvlt_48_36","chapterId":"ch_work_nvlt_48","text":"【表】後魏溫子升臨淮王或［魏書十八作彧］謝封开府尚書令表曰：臣道愧山東，氣慚隴右，激水弗堪，摶風無力，但以平源帶地，資緒極天，發趾自高，理融以遠，出臨侯服，既乏刺舉之能，入踐帝閽。又無應對之美，空复受戈清廟，推轂朱門，效闕淚河，功慚汗海，大寶遂隆，橫草未树，顧以有涯，原言知止。","sortOrder":36},
  {"id":"s_work_nvlt_48_37","chapterId":"ch_work_nvlt_48","text":"又為魏南陽王允寶炬［原訛拒，據冯校本改。］讓尚書令表曰：臣聞立而讬乘，乃成致遠之功，坐以運舟，遂有利涉之用，若以輕任重課，凭虛责實，雖欲自勤，終焉靡效。","sortOrder":37},
  {"id":"s_work_nvlt_48_38","chapterId":"ch_work_nvlt_48","text":"梁范雲為柳司空讓尚書令初表曰：陛下繼明南面，复垂顯錄，增榮益觀，豈侧身限，而露不廣海，尘不增山，微物知止，敢忘自退，誠以懷音感遇，久妨彝序，尸祿昧寵，取蹈風歌，中寐軫心，方餐凝慮，寧可冒釐綜之重，負學製之談，將玷朝徽，匪伊身議。","sortOrder":38},
  {"id":"s_work_nvlt_48_39","chapterId":"ch_work_nvlt_48","text":"第二表曰：臣聞聖人在上，愚智無以息隱，天下有道，方圓歸其能是，如以駑蹇之才，不致問於千里，瓦砾之质，佇待价於十城，伏原陛下，矜臣負乘之尤，照臣匪飾之情，跡言觀用，允授上才，斂會流恩，曲蠲下第，則雲序斯平，彝章載穆。","sortOrder":39},
  {"id":"s_work_nvlt_48_40","chapterId":"ch_work_nvlt_48","text":"梁沈約拜尚書令到都坐表曰：竊位之譏，允當斯责，王命私請，有事相傾，油雲湛露，從降旻昊之德，弱縞輕蝉，不載丘嶽之重，登階望席，怳焉失步。","sortOrder":40},
  {"id":"s_work_nvlt_48_41","chapterId":"ch_work_nvlt_48","text":"北齊邢子才為文襄皇帝讓尚書令表曰：扬職萬機，總任百揆，想衔庶物，准納群寮，何以助日月之光華，增天地之高厚，反鑒取照，匹此何難，倒裳求領，方之為易。","sortOrder":41},
  {"id":"s_work_nvlt_48_42","chapterId":"ch_work_nvlt_48","text":"又表曰：正以晝覽太山，不假秋毫之察，夜仰列宿，豈藉燭龍之明，爵人以世，既非盛德之舉，公門有私，故足陵夷之運。","sortOrder":42},
  {"id":"s_work_nvlt_48_43","chapterId":"ch_work_nvlt_48","text":"隋江總讓尚書令表曰：臣弱歲立朝，本無奇志，每謂任登常伯，足承基緒，值梁季不造，牧拙人間，東竄三江，南徂百越，不知秦漢，十有七年，心跡退黜，平生畢矣，但野性疏懶，不屑死增，俯仰乖時，人物多忤，天飛踐阼，任寄隆布，谬以商丘之木，遂比舟栰之材，燕岱之石，混同瑚璉之器，當由崇賢傳舉，早守名節，竊以天府文昌，萬方之藪，天官冢宰，無所不統，禮革三獨，事昭百揆，曠職雲久，三十餘載，一旦开置，必資望實，豈期廷典私偏，濫庸菲薄，陛下聽覽餘辰，曲垂昭納，遂斯反汗，高選具瞻，則敝蓋敝帷，使臣暮齒，歲製月製，賒臣皓發。","sortOrder":43},
  {"id":"s_work_nvlt_48_44","chapterId":"ch_work_nvlt_48","text":"隋江總除尚書令謝台啟曰：竊以昔之冢司，今日端揆，頃同台袞，無人則闕，臣之朽薄，安可叨贲，謹當奏承夜月，冀奉三思之旨，聲寄浮雲，方祈九天之路。","sortOrder":44},
  {"id":"s_work_nvlt_48_45","chapterId":"ch_work_nvlt_48","text":"又除尚書令斷表後啟曰：司會治本，冢宰朝端，搢紳所屬，儀形攸在，皇代以來，無人則闕，陛下將備厥職，用穆巨僚，不容始自庸菲，以讙物議，當今藩翰至戚，不無其才，廊廟重臣，亦有其器，伏原檢俞往之則，闡平章之道，臣沿心布款，有理存焉。","sortOrder":45},
  {"id":"s_work_nvlt_48_46","chapterId":"ch_work_nvlt_48","text":"◇仆射","sortOrder":46},
  {"id":"s_work_nvlt_48_47","chapterId":"ch_work_nvlt_48","text":"《漢書》曰：仆射，秦官也，古者重武，官有主射，以督課之，自侍中尚書博士及騶宰永巷官人皆有，取其領事之號。","sortOrder":47},
  {"id":"s_work_nvlt_48_48","chapterId":"ch_work_nvlt_48","text":"又曰：鄭崇，哀帝擢為尚書仆射，數求見諫爭，上初納用之，每聞曳革履，上叹曰：我識鄭尚書履聲。","sortOrder":48},
  {"id":"s_work_nvlt_48_49","chapterId":"ch_work_nvlt_48","text":"《續漢書》曰：尚書仆射一人，六百石，令不在，則奏下眾事。","sortOrder":49},
  {"id":"s_work_nvlt_48_50","chapterId":"ch_work_nvlt_48","text":"百官表註曰：仆射一人，銅印墨綬，五時朝，［《初學記》十一，《太平御覽》二百十一朝下有服字，此脱。］納言帻，進賢兩梁冠，佩水蒼玉，建安以來，執金吾榮劭，為尚書左仆射，仆射之有左右，自此始也。","sortOrder":50},
  {"id":"s_work_nvlt_48_51","chapterId":"ch_work_nvlt_48","text":"鍾離意別傳曰：意為尚書仆射，其年匈奴羌胡歸義，詔賜缣三百匹，尚書侍郎廣陵暨酆，誤以為三千匹，詔大怒，鞭酆欲死，意入諫曰：海內遐邇，謂陛下貴徵［《太平御覽》六百四十九引會稽典錄作微。］财而賤人命，愚臣所不安，明帝以意諫，且酆错合大義，贳酆，敕大官賜酒藥，詔謂意曰：非鍾離尚書，朕幾降威於此郎。","sortOrder":51},
  {"id":"s_work_nvlt_48_52","chapterId":"ch_work_nvlt_48","text":"《魏志》曰：桓范荐徐宣為仆射，車駕幸許昌，總留事，帝還，主者奏呈文書，詔曰：吾省與仆射何異，竟不视。","sortOrder":52},
  {"id":"s_work_nvlt_48_53","chapterId":"ch_work_nvlt_48","text":"又曰：陳泰為尚書左仆射，典選舉。","sortOrder":53},
  {"id":"s_work_nvlt_48_54","chapterId":"ch_work_nvlt_48","text":"晉諸公贊曰：司馬珪，時多令望，早歷顯職，晉受禪，為尚書左仆射，時年三十七，眾論以為美。","sortOrder":54},
  {"id":"s_work_nvlt_48_55","chapterId":"ch_work_nvlt_48","text":"晉公卿禮秩曰：司馬珪，三十七為尚書仆射，魏晉以來，或置左右，或不置。","sortOrder":55},
  {"id":"s_work_nvlt_48_56","chapterId":"ch_work_nvlt_48","text":"《世說》曰：周顗，字伯仁，過江，積年恒大飲酒，嘗經三日醒，時論謂之三日仆射。","sortOrder":56},
  {"id":"s_work_nvlt_48_57","chapterId":"ch_work_nvlt_48","text":"王隱《晉書》曰：太康元年，以山涛清虛恬簡，轉為仆射。","sortOrder":57},
  {"id":"s_work_nvlt_48_58","chapterId":"ch_work_nvlt_48","text":"齊職儀曰：魏朝以尚書仆射毛玠領選曹。","sortOrder":58},
  {"id":"s_work_nvlt_48_59","chapterId":"ch_work_nvlt_48","text":"晉武以仆射山涛領吏曹，後依擬，至今或領焉。","sortOrder":59},
  {"id":"s_work_nvlt_48_60","chapterId":"ch_work_nvlt_48","text":"沈約《宋書》曰：劉延孫為尚書左仆射，延孫疾病，不任拜起，上使乘船，自青溪至平昌門，入尚書下舍。","sortOrder":60},
  {"id":"s_work_nvlt_48_61","chapterId":"ch_work_nvlt_48","text":"【墓志】梁沈約尚書右仆射范雲墓志銘曰：合契興王，匪勞物色，乘風鬱起，化成龍翼，乃作喉唇，帝猷必舉，乃作铨衡，彝倫有序，北京徂峻，東川回薄，蘊吾名臣，終天靡作。","sortOrder":61},
  {"id":"s_work_nvlt_48_62","chapterId":"ch_work_nvlt_48","text":"【表】宋傅亮讓尚書仆射表曰：自皇基肇創，豫班策勋，纖善微績，未聞朝野，百揆治枢，總貳殷要，誠非庸臣所宜叨擬，臣聞權衡既懸，锱銖靡遁，厲駑習骥，終莫之近，败駕傷錦，備之前誥，必將上增國垢，下招私黷。","sortOrder":62},
  {"id":"s_work_nvlt_48_63","chapterId":"ch_work_nvlt_48","text":"齊王俭讓左仆射表曰：待臣於常均之外，眄臣於代僚之右，親乖其章，乘非其器，霸府方隆，超居元佐，國朝草昧，參贊百揆。","sortOrder":63},
  {"id":"s_work_nvlt_48_64","chapterId":"ch_work_nvlt_48","text":"梁沈約讓仆射表曰：臣聞役壮休老，上典所優，晨行暮息，事身恒分，若夫玄黃未已，非狄駕之衛，筋力為用，豈強飯之時，養老杖乡，抑推前典，服戎告謝，親學匪任，宿肉極其虛憊，歲製防其不辜，寔所以蠲假衰疾，收屏淪暮，梁張缵讓尚書仆射表曰：加以矯心飾貌，酷非所閒，不喜俗人，與之共事，雖复吐言如傷，屈體無骨，動容竊斧，猶成多憾，曾闈如闕，坐客須滿，情態參差，世涂盈虛，薏苡興謗，舍尘見猜，疑似雖分，聖賢致惑，人之包藏，山川非险，况在於臣，焉可證綜。","sortOrder":64},
  {"id":"s_work_nvlt_48_65","chapterId":"ch_work_nvlt_48","text":"陳徐陵讓左仆射初表曰：臣聞七十之歲，楊雄擬經，六十之年，平津對策，若斯彊壮，無叹耆老，臣励［據陳書十七王劢傳當作劢，後同。］則胄華軒冕，才允卿相，出納流譽，朝野具瞻，臣弘正國老儒宗，情尚虛簡，玄風勝業，獨王當年，臣种氣懷沉密，文史優裕，東南貴秀，朝廷親賢，併見壮猷，皆宜左執，若漢武好少，則微臣已老，若周文愛老，則有此群才，伏原天明，更謀梓匠，求其妙選，稱是能官。","sortOrder":65},
  {"id":"s_work_nvlt_48_66","chapterId":"ch_work_nvlt_48","text":"又讓右仆射初表曰：加以言尋盟好，仍屬亂罹，千［漢書蘇武傳作丁。］零盜其牛馬，乌孫竊其印綬，子卿如雪，叔向為國，雖獲東歸，備離此厄，昔李廣遺恨，不值漢初，甯戚自歸，悲逢尧換，臣隨望聖運，實在權舆，時參决勝之筹，頗奏發兵之讖，當涂錫舍，非無董昭之誠，典午禪文，不降張華之賞。","sortOrder":66},
  {"id":"s_work_nvlt_48_67","chapterId":"ch_work_nvlt_48","text":"隋江總讓尚書仆射表曰：藻鏡官方，品裁人物，門驚如市，不慚屋漏，心抱如冰，無欺暗室，但屢淹星乌，每知忝素，世網拘束，事歸黾勉，今此召會，尤增據蒺，竊以端揆副職，官稱師長，革履升降，傳呼寵赫，儀形朝首，冠冕彝倫，兼复戶總衡流，匡佐繁俗，忘膺重责，必踐危機。","sortOrder":67},
  {"id":"s_work_nvlt_48_68","chapterId":"ch_work_nvlt_48","text":"◇吏部尚書","sortOrder":68},
  {"id":"s_work_nvlt_48_69","chapterId":"ch_work_nvlt_48","text":"《魏志》曰：盧毓為侍中，在職三年，多所駮易，詔曰：官人秩才，聖帝所難，必須良佐，進可替否，侍中毓，禀性貞固，心平體正，可謂明试有功，不懈於位者也，其以毓為吏部尚書，使毓自選代，曰：得如卿者乃可，毓舉常侍鄭冲，帝曰：文和吾自知之，更舉吾所未知者，乃舉阮武孫邕，帝於是用邕。","sortOrder":69},
  {"id":"s_work_nvlt_48_70","chapterId":"ch_work_nvlt_48","text":"袁子曰：魏家置吏部尚書，专選天下百官，夫用人人君之所司，不可以假人者也，使治亂製在一人之手，權重而人才難得，居此職，稱此才者，未有一也。","sortOrder":70},
  {"id":"s_work_nvlt_48_71","chapterId":"ch_work_nvlt_48","text":"王隱《晉書》曰：山涛為太常，遭母丧，手植松柏，詔曰：今風俗凌遲，豈宜镇以退讓，山太常雖在谅陰，古人亦墨绖從戎，其以涛為吏部尚書，涛用人，皆先密啟，然後公奏。","sortOrder":71},
  {"id":"s_work_nvlt_48_72","chapterId":"ch_work_nvlt_48","text":"又曰：邓攸遷吏部尚書，牧馬於家庭，妻自素食，不受一飯於人。","sortOrder":72},
  {"id":"s_work_nvlt_48_73","chapterId":"ch_work_nvlt_48","text":"《世說》曰：王濬冲裴叔則二人，總角詣鍾士季，須臾去，後客問向二童是誰，曰：裴王，客何如，鍾曰：裴楷清通，王戎簡要，後二十年，此賢當為吏部尚書，冀爾時天下無复滯才。","sortOrder":73},
  {"id":"s_work_nvlt_48_74","chapterId":"ch_work_nvlt_48","text":"《語林》曰：袁真為監軍，范去［《太平御覽》二百十四作玄，此訛。］平作吏部尚書，大坐語袁，卿此叚還，不失護軍，袁曰：卿何事人中作市井。","sortOrder":74},
  {"id":"s_work_nvlt_48_75","chapterId":"ch_work_nvlt_48","text":"百官表註曰：吏部尚書一人，秩六百石，掌選舉斋祠。","sortOrder":75},
  {"id":"s_work_nvlt_48_76","chapterId":"ch_work_nvlt_48","text":"晉諸公贊曰：李胤為吏部尚書，正身率職不桡，故能行其所見，遂刊定選例，而著於令。","sortOrder":76},
  {"id":"s_work_nvlt_48_77","chapterId":"ch_work_nvlt_48","text":"沈約《宋書》曰：蔡廓為吏部尚書，廓因傅隆問傅亮，選事若悉以見付不論，不然，不能拜，亮以語錄尚書徐羨之曰：黃門以下，悉以委蔡，自此上，宜共參同異，廓曰：我不能為徐幹木署紙尾，遂不拜，幹木，羨之小字也，選案錄尚書與吏部尚書連名，故廓雲紙尾。","sortOrder":77},
  {"id":"s_work_nvlt_48_78","chapterId":"ch_work_nvlt_48","text":"又曰：江湛為吏部尚書，家甚貧約，不營求利，餉饋盈門，一無所受，無兼衣餘食，常為上所召，值澣衣，稱疾經日，衣成後起。","sortOrder":78},
  {"id":"s_work_nvlt_48_79","chapterId":"ch_work_nvlt_48","text":"又曰：顏竣為吏部尚書，留心選舉，自強不息，任遇既隆，奏無不可，後謝莊代竣，意多不行，竣容貌嚴毅，莊風姿甚美，賓客喧訴，常懽笑答之，時人語曰：顏竣嗔而與人官，謝莊笑而不與人官。","sortOrder":79},
  {"id":"s_work_nvlt_48_80","chapterId":"ch_work_nvlt_48","text":"【箴】晉傅玄吏部尚書箴曰：明明王軌，製為九秩，君執常道，臣有定職，各有攸司，非用不慝，昔舜舉皋陶，而俊乂在官，夔龍出入朕命，周仲山甫，亦允內言。","sortOrder":80},
  {"id":"s_work_nvlt_48_81","chapterId":"ch_work_nvlt_48","text":"【诔】齊丘遲侍中吏部尚書何府君诔曰：遠量夷雅，淹姿英茂，進德方新，循名以舊，分鑣先達，爭驅俊秀，匪直羽儀，實惟領袖，知人斯哲，在帝之難，佥謂往諧，是則能官，園阿望幣，釣屿投竿，金張之貴，允茲七侍，有美一人，柔貂三珥，服冕乘軒，鳴玉飛翠，不貪為寶，貴而能貧，唯靜是悅，惟寂是珍，履信茲從，積善方慶，如何斯德，曾是知命，彼高者天，與人焉詠，眇望周行，式瞻林壑，洒汰紛埃，擯扬流俗，言必玄遠，神惟珠玉，色恬喜慍，心豈榮辱。","sortOrder":81},
  {"id":"s_work_nvlt_48_82","chapterId":"ch_work_nvlt_48","text":"宋謝莊讓吏部尚書表曰：招才琴釣之上，取士歌牧之中，終能克夷景命，榮懷萬宇，豈容先私首曲，近有經過，且不習冠製，趙客興鑒，未閒統馭，鄭臣有規，匪痗身譏。","sortOrder":82},
  {"id":"s_work_nvlt_48_83","chapterId":"ch_work_nvlt_48","text":"後魏溫子升廣楊［魏書十八作陽。］王讓吏部尚書表曰：假势風雲，非由羽翮，徒得推遷就列，黾勉當官，曾無辟雍議禮之名，詎有銅爵獻賦之敏，而政本寔繁，司會攸切，抑扬智地，用舍時流，實當年之准的，乃一世之權衡，得其人則分職之任隆，非其才則曠官之失起。","sortOrder":83},
  {"id":"s_work_nvlt_48_84","chapterId":"ch_work_nvlt_48","text":"梁任昉為范雲讓散騎常侍吏部尚書霄城侯表曰：夫铨衡務重，闕語［明本作關治，文選三十八，《初學記》十二作關諸。］隆替，遠惟則哲，在帝猶輕，［《文選》、《初學記》作難。］漢魏以降，遠識經軌，雅俗所歸，唯稱許郭，齊季凌遲，官方淆亂，草創惟始，議存改作，恭己南面，责成斯在，豈宜妄加寵私，以乏王事，附蝉之飾，空成寵章，求之公私，授受交失，近世侯者，功緒參差，或足食關中，或成軍河內，或盛德如卓茂，或師道如桓榮，四姓傳祠，已無定紀，五侯外戚，且非舊章，而臣之所附，唯在恩泽，且去歲冬初，國學之老博士耳，今茲首夏，將亚冢司，雖千秋之一日九遷，荀奭［《文選》作爽。］之十旬遠至，方之微臣，未為速達。","sortOrder":84},
  {"id":"s_work_nvlt_48_85","chapterId":"ch_work_nvlt_48","text":"梁沈約為褚炫讓吏部尚書表曰：竊惟玄素未辯，必谬朱紫之察，規矩或昧，理丧方圓之功，東西兩漢，左雄孤絕於前，南北二晉，山涛莫嗣於後，良由性藏於貌，才隱乎心，楚越無以况其迥殊，山川未足方其险阻，雖复拂暗為明，免過生智，亦何以登奇牧異，離渭分涇。","sortOrder":85},
  {"id":"s_work_nvlt_48_86","chapterId":"ch_work_nvlt_48","text":"梁張缵讓吏部尚書表曰：漢革民曹，魏仍東掾，毛孝先以清公見美，盧子加以貞固任職，降及晉代，希睹其人，樂彦辅雍容自守，當時恨其寡譽，山巨源意存賞拔，不免與世浮沉，邓攸牧馬家庭，何益心競之操，卞壸如金丸在右，未聞檢裁之功。","sortOrder":86},
  {"id":"s_work_nvlt_48_87","chapterId":"ch_work_nvlt_48","text":"梁王筠為弟六叔讓重除吏部尚書表曰：臣聞剸犀截雁，必俟崑吾之鋒，逐日追風，信資伯樂之駿，未有驂駑騫足，而方騁遙涂，采蓺鉛刀，而求其斷割，伏惟則哲為體，事艱歷代，明別攸奇，義重前王，必使玉石薰莸，區別靡雜，涇渭玄黃，條流不爽，自非伯豪之天下稱能，仲子之時人歸德，孝先之拔真抑伪，巨源之黜惡舉善，然後可以铨鏡流品，平均衡石。","sortOrder":87},
  {"id":"s_work_nvlt_48_88","chapterId":"ch_work_nvlt_48","text":"隋江總讓吏部尚書表曰：竊以漢置五曹，方今六尚，魏隆八凯，擬古六卿，延喻喉舌，遠膺枢斗，至如東京許郭，西晉裴王，仰首伸眉，可得論列此矣，但臣門基世緒，晉宋已來，內侍帷扆，入尸衡尺，或年甫將立，或歲未強仕，是以退思弱冠，追傷畴昔，早尘華位，見知名辈，常謂忝竊，匪朝伊夕，豈期梁室多故，有志無時，平生意氣，飒爾零落，特由邀奉嘉運，千載一時，惟奋寵靈，遂臻於此。","sortOrder":88},
  {"id":"s_work_nvlt_48_89","chapterId":"ch_work_nvlt_48","text":"又為沈尚書君理讓右仆射領吏部表曰：辛香［疑訛。］以來，安石以後，遵其軌躅，必大厦之棟梁，總其寄任，亦巨川之舟楫，未有綿力薄材，輕膺此舉。","sortOrder":89},
  {"id":"s_work_nvlt_48_90","chapterId":"ch_work_nvlt_48","text":"◇尚書","sortOrder":90},
  {"id":"s_work_nvlt_48_91","chapterId":"ch_work_nvlt_48","text":"應劭《漢官儀》曰：尚書，唐虞官也，書曰：龍，命汝作納言，朕命惟允。","sortOrder":91},
  {"id":"s_work_nvlt_48_92","chapterId":"ch_work_nvlt_48","text":"又曰：漢明帝詔曰：尚書蓋古之納言，出納朕命，機事不密則害成，可不慎欤。","sortOrder":92},
  {"id":"s_work_nvlt_48_93","chapterId":"ch_work_nvlt_48","text":"韦昭辯《釋名》曰：尚，上也，言最在上，總領之也，辯雲，尚猶奉也，百官言事，當省案平處奉之，故曰尚，尚食尚方亦然。","sortOrder":93},
  {"id":"s_work_nvlt_48_94","chapterId":"ch_work_nvlt_48","text":"《漢書》：百官表曰：成帝罢中書官，初置尚書員五人，如淳曰：主天子文書曰尚書，如主婿曰尚主。","sortOrder":94},
  {"id":"s_work_nvlt_48_95","chapterId":"ch_work_nvlt_48","text":"《桓子新論》曰：昔尧言［《太平御覽》二百十二作试。］舜於大麓者，錄天下事，如今之尚書官矣，宜得大賢智，乃使處議持平焉。","sortOrder":95},
  {"id":"s_work_nvlt_48_96","chapterId":"ch_work_nvlt_48","text":"謝承《後漢書》曰：朱穆為尚書，谠言正直。","sortOrder":96},
  {"id":"s_work_nvlt_48_97","chapterId":"ch_work_nvlt_48","text":"華峤《漢書》曰：韦彪上疏曰：欲急民所務，當先除其患，其原在尚書，典枢機，天下事一决之，不可不察。","sortOrder":97},
  {"id":"s_work_nvlt_48_98","chapterId":"ch_work_nvlt_48","text":"《東觀漢記》曰：章帝東巡，過任城，乃幸鄭均舍，敕賜尚書祿，以終其身，故時人號為白衣尚書，《續漢書》曰：李固上疏曰：陛下之有尚書，猶天之有北斗，北斗為天喉舌，尚書為陛下喉舌。","sortOrder":98},
  {"id":"s_work_nvlt_48_99","chapterId":"ch_work_nvlt_48","text":"《魏志》曰：陳群為尚書，製九品為官人之法，群所建也。","sortOrder":99},
  {"id":"s_work_nvlt_48_100","chapterId":"ch_work_nvlt_48","text":"王昶考課事曰：尚書侍中考課，一曰掌建六材，以考官人，二曰綜理萬機，以考庶績，三曰進视惟允，以掌谠言，四曰出納王命，以考賦政，五曰罰法，以考典刑，《會稽典錄》曰：鄭弘拜尚書郎，舊典，科滿補縣長，令史為丞尉，弘奏以為台職位尊而賞薄，人無樂者，諸［《太平御覽》二百十二作請。］使郎補縣令，令史為長，上從其議，自此為始。","sortOrder":100},
  {"id":"s_work_nvlt_48_101","chapterId":"ch_work_nvlt_48","text":"齊職儀曰：尚書六人，品第三，秩六百石，進賢兩梁冠，納言帻，絳朝服，佩水蒼玉，執笏負荷。","sortOrder":101},
  {"id":"s_work_nvlt_48_102","chapterId":"ch_work_nvlt_48","text":"沈約《宋書》曰：顧琛傳曰：寺門有製，八座以下，門生隨入者有差，不得雜以人士，琛以宗人顧硕顧，［宋書八十一顧琛傳作頭。］寄尚書張茂度聞［○宋書作門。］名，而去［宋書作與。］硕頭同席坐遣出，凡尚書官，大罪則免，小罪則遣出，出者百日無代人，聽還本職。","sortOrder":102},
  {"id":"s_work_nvlt_48_103","chapterId":"ch_work_nvlt_48","text":"【箴】漢楊雄尚書箴曰：允敕百工，命作斋栗，龍惟納言，是機是密，出入王命，王之喉舌，獻善宣美，而讒說是折，我视雲明，我聽雲聰，載夙載夜，惟允惟恭，故君子在室，出言如風。","sortOrder":103},
  {"id":"s_work_nvlt_48_104","chapterId":"ch_work_nvlt_48","text":"【诔】晉潘嶽庾尚書诔曰：宽而能懷，威而不猛，化行如形，民應如影，曀曀虛坐，翩翩玄幕，幾筵生尘，空馆寥廓。","sortOrder":104},
  {"id":"s_work_nvlt_48_105","chapterId":"ch_work_nvlt_48","text":"晉盧湛尚書武強侯盧府君诔曰：湛罪重五嶽，衅深四海，身不灰滅，延於家門，方今斬焉在疚，死已無日，大懼先意遺烈，將墜乎地，罔極之哀，終不宣寫，是以忍在草土之中，撰述平素之跡，篤生我君，天挺賢俊，弘闡大風，光隆洪胤，蔚矣其姿，綽乎其韻，天不予晉，厄運時臻，陽九之會，雖聖莫振，君實振惶，國難是圖，跋履山川，東征西徂，方协遐任，言复皇舆，不見楚申，致命郢都，往古來今，自遠及近，凡在丧親，猶思俱殒，况我荼毒，靡經不盡，日月逾邁，寒暑代遷，恩慈弥遠，窮思日纏，撰述遺跡，臨文煩冤。","sortOrder":105},
  {"id":"s_work_nvlt_48_106","chapterId":"ch_work_nvlt_48","text":"隋江總度支尚書陆君诔曰：陆公國士之眷，惠好之深，臨丧能诔，久原搖筆，時事迍邅，不惶削藁，梁季適越，未戢幹戈，陳世入仕，累牵物役，杼抽於懷，三十餘載，隋开皇九年，於長安致仕，懸車以洎，就木何幾，但東海成田，南冠承縶，龟山更徙，空想吹笛之哀，馬角徒生，絕望通波之水，呜呼哀哉，於是攬涕操觚，乃為诔曰：雁行攸序，龍作間才，讓珠不拜，錫劍恩來，世故天禍，臣悲主辱，露盡朝陽，風驚夜燭，悠悠世路，辛苦艱虞，尋戈滿道，曝骨交衢，家無半菽，地絕飛刍，念群桑梓，零落彫枯，傷君井邑，了盤崎嶇，凄涼故友，擗树遺孤，臨穴別野，撫榇窮涂。","sortOrder":106},
  {"id":"s_work_nvlt_48_107","chapterId":"ch_work_nvlt_48","text":"梁張缵故左氏尚書忠子沈憎旻墓志銘曰：漸東振古，龟組三袭，政若解繩，吏如燥濕，十升龍管，四至九卿，居高首暎，比德腰明。","sortOrder":107},
  {"id":"s_work_nvlt_48_108","chapterId":"ch_work_nvlt_48","text":"【表】梁沈約讓五兵尚書表曰：臣聞百舍之趙，非宿舂所資，千里之越，豈一苇能溯，何者，裝輕適於路遠，舟弱疲於濟深，丑貌悴容，不藉鑒於淄水，駑足蹇步，終取踬於鹽車。","sortOrder":108},
  {"id":"s_work_nvlt_48_109","chapterId":"ch_work_nvlt_48","text":"梁丘遲為范尚書拜表曰：昔滕公移晷於泗亭，陳遂留懽於博進，祿止一守，官窮九列，臣獲照秋陽，取沃淮海，發蒙去吝，已若松乔，匪富伊榮，須臾至此，賞參十亂，躬越五水，歷覽前載，孰與為匹。","sortOrder":109},
  {"id":"s_work_nvlt_48_110","chapterId":"ch_work_nvlt_48","text":"梁萧子范為兄宗正讓都官尚書表曰：納言之授，皇命所由，五星懸曜，差池紫宮之曲，百官根本，聯曹建禮之內，孔蔡詣博，垂芳於兩京，陳鍾令才，比肩於魏世，逖望前英，俯修薄義，無尸素禮，而絕祗奉。","sortOrder":110},
  {"id":"s_work_nvlt_48_111","chapterId":"ch_work_nvlt_48","text":"隋徐陵讓五兵尚書表曰：臣聞仲尼大聖，猶雲書不盡言，士衡高才，當［本集作常］稱文不逮意，臣比衰痾日積，思緒茫然，頻讬朋遊，為裁章表，雖复陳琳健筆，未盡愚懷，孫惠辭人，頗加煩飾，所以高天緬邈，弗降昭回，瞻拜絲纶，更增忧憊，臣雖不敏，弱冠登朝，伊言承華，豫遊多士，晚逢興運，爰濫寵私，爾時四郊多壘，七雄分爭，國家製度，日不暇給，趙宮論受命之宜，高邑奏升壇之禮，而參聞秘計，弗解单於之兵，飛箭馳書，未動聊城之將，不期枚乘老叟，忽降特恩，冯唐暮年，見申明主，擢宰京邑，朝坐棘林，遂致洛陽無雨，非止長安多盜，其宜屏錮，用寘嚴科，猶處名僚，久為叨竊，但著書天祿，雖如劉向，朔望登朝，轉同王隱，於其朽劣，尚可從容，司會文昌，邈然非據。","sortOrder":111},
  {"id":"s_work_nvlt_48_112","chapterId":"ch_work_nvlt_48","text":"◇吏部郎","sortOrder":112},
  {"id":"s_work_nvlt_48_113","chapterId":"ch_work_nvlt_48","text":"《郭子》曰：許允妻，阮德如妹，允為吏部郎，多用其乡里，帝遣虎贲收允，婦出閤戒允曰：明主可以理奪，難以情求，允至，明帝核之，允答曰：舉爾所知，臣之乡人，臣所知也，原陛下檢校，為稱職與不，若不稱職，臣宜受其罪，既檢校，皆其人，於是乃釋，允舊服败坏，詔賜新衣，初被收，舉家號哭，允新婦自雲無忧，尋還，作粟粥待之，須臾允至。","sortOrder":113},
  {"id":"s_work_nvlt_48_114","chapterId":"ch_work_nvlt_48","text":"《魏志》曰：諸葛誕為吏部郎，有屬讬，則顯其言而承用之，後有當否，則雲議其得失，自是群僚莫不慎其所舉。","sortOrder":114},
  {"id":"s_work_nvlt_48_115","chapterId":"ch_work_nvlt_48","text":"山涛啟事曰：人才既自難知，中人以下，情伪又難，吏部郎與碎事日夜相接，非但當正己，乃當能正人。","sortOrder":115},
  {"id":"s_work_nvlt_48_116","chapterId":"ch_work_nvlt_48","text":"王隱《晉書》曰：李胤為吏部郎，精慎選舉，號為廉平，山涛為吏部郎，文帝與書曰：足下在事清明，絜操邁時，念多所乏，今致錢二十萬，絲百斤，穀二百斛。","sortOrder":116},
  {"id":"s_work_nvlt_48_117","chapterId":"ch_work_nvlt_48","text":"又曰：王戎名位清賞，二十四為吏部郎。","sortOrder":117},
  {"id":"s_work_nvlt_48_118","chapterId":"ch_work_nvlt_48","text":"《晉中興書》曰：畢卓，字茂世，新蔡人，少亦放達，泰興末，為吏部郎，常飲酒废職，比舍郎酿熟，卓因醉，夜至其瓮間取酒飲，掌酒者不察，執而縛之，郎往视之，乃畢吏部也，遽釋其縛，卓遂引主人宴於瓮侧，取醉而去，卓常謂人曰：右手持酒卮，左手持蟹螫，拍浮酒池中，便足了一生。","sortOrder":118},
  {"id":"s_work_nvlt_48_119","chapterId":"ch_work_nvlt_48","text":"又曰：阮放與從弟孚齊名，在铨管之任，甚有稱譽，性清俭，終不治產業，為吏部郎，不免飢乏，王导庾亮，以其名士，給衣食，放由是得立。","sortOrder":119},
  {"id":"s_work_nvlt_48_120","chapterId":"ch_work_nvlt_48","text":"王蘊別傳曰：蘊字叔仁，為吏部郎，欲使時無屈滯，曾下鼓急出，日迭乃至家，去台數里，高褰車帷，先後與語，不得進也，一官缺者，求者十辈，蘊連状呈宰錄曰：某人有地，某人有才，不得者甘心無怨。","sortOrder":120},
  {"id":"s_work_nvlt_48_121","chapterId":"ch_work_nvlt_48","text":"《世說》曰：吏部缺，文帝問其人於鍾會，會曰：裴楷清通，王戎簡要，皆其選也，於是用裴。","sortOrder":121},
  {"id":"s_work_nvlt_48_122","chapterId":"ch_work_nvlt_48","text":"又曰：山公舉阮鹹為吏部郎，曰：情真寡欲，萬物不能移也。","sortOrder":122},
  {"id":"s_work_nvlt_48_123","chapterId":"ch_work_nvlt_48","text":"沈約《宋書》曰：王微，字景玄，吏部尚書江湛，舉微為吏部郎，微與湛書曰：君平生雲，［宋書王微傳作雲生，此倒。］我名者殺我身，天爵猶滅名，安用吏部郎哉，其舉可陋，其事不經，非獨搢紳者不道，仆妾皆笑之。","sortOrder":123},
  {"id":"s_work_nvlt_48_124","chapterId":"ch_work_nvlt_48","text":"【表】梁陆倕拜吏部郎表曰：铨衡庶品，歷選賓僚，阮盛真素，屢荐未登，陆亮忠心，裁居败職，自非季重清識，季文恬正，可以區分管库，式鑒胥吏。","sortOrder":124},
  {"id":"s_work_nvlt_48_125","chapterId":"ch_work_nvlt_48","text":"梁王僧孺吏部郎表曰：臣生輕飛箨，品細疏壤，寂寞州闾，取淪窐窦，不自求於善管，寧許人以能官，從班隨牒，自安疏遠，豈望翰飛，終知跡滯，一逢浸漉，幾聞昭晉，假拙為心，变奇成偶，寧為天覆地長，复與雨露相滋，秋成春發，必如暄寒無爽，自变况［全梁文五十一作泥。］涂，多超嵩邓，屢考固其比越，在累誠於可聞，方愧朱紫，永懵鈞衡，固惟許李，終非王畢，取其清尚，固所經企，求之碎密，寧可庶幾。","sortOrder":125},
  {"id":"s_work_nvlt_48_126","chapterId":"ch_work_nvlt_48","text":"梁任昉數［疑訛。］吏部郎表曰：郎官之重，千金非譬，爰在前世，實光選造，清通為首，終遂弗居，深識為度，累荐無獲，承乏攝官，顧知其望，方今皇明御宇，昇長鹹亨，涇渭搢紳，無谬衡石，抑扬庶品，亦俟能官，顧已循涯，孰用祗荷，唯知死所，未識所報。","sortOrder":126},
  {"id":"s_work_nvlt_48_127","chapterId":"ch_work_nvlt_48","text":"【啟】梁陆倕遷吏部郎啟曰：臣器均濩落，材同擁肿，效非積山，勤乖附地，自叨榮秩列，裁移氣序，而坐延曲私，遂被洪造，自非割蚌識珠，睹石知玉，寧可以獲名理俗，見操敦教。","sortOrder":127},
  {"id":"s_work_nvlt_48_128","chapterId":"ch_work_nvlt_48","text":"梁王僧孺除吏部郎啟曰：自一遇休明，多逢渥泽，出斯溝壤，置之霄漢，清涂華轍，叨廁累仍，顯職名階，俄來倏至，而智效必其無取，尤怠忽焉已彰，不意涵養更滋，雱霈愈此，始職枢華，紛體恒選，知非腆族，必待俊民，何言賤劣。所或叨假，循涯测限，生所不勝，瞻恩奉德，死何能報。","sortOrder":128},
  {"id":"s_work_nvlt_48_129","chapterId":"ch_work_nvlt_48","text":"◇侍中","sortOrder":129},
  {"id":"s_work_nvlt_48_130","chapterId":"ch_work_nvlt_48","text":"環濟要略曰：侍中，古官也，或曰：風後為黃帝侍中，周時號常伯者，言其道德可常遵也，秦始皇复古，［《太平御覽》二百十九作故。］冠貂蝉，漢因而不改，此內官，侍帷幄，受顧問，拾遺於左右，出則負玺以從，秩二千石。","sortOrder":130},
  {"id":"s_work_nvlt_48_131","chapterId":"ch_work_nvlt_48","text":"《漢舊儀》曰：侍中無員，或列侯將軍衛尉光祿大夫為侍郎，［《太平御覽》二百十九作為之。］得舉非法。","sortOrder":131},
  {"id":"s_work_nvlt_48_132","chapterId":"ch_work_nvlt_48","text":"又曰：侍中左右近臣，見皇後，如見帝，見婕妤，行則對壁，坐則伏茵也。","sortOrder":132},
  {"id":"s_work_nvlt_48_133","chapterId":"ch_work_nvlt_48","text":"應劭《漢官》曰：侍中，周官也，金蝉有貂，金取堅刚，百煉不耗，蝉居高食絜，目在掖下，貂內劲悍而外溫润，侍中便繁左右，與帝升降，卒思近對，拾遺補闕，百僚之中，莫密於茲，秦始皇破趙，得其冠，以賜侍中。","sortOrder":133},
  {"id":"s_work_nvlt_48_134","chapterId":"ch_work_nvlt_48","text":"《漢書》曰：桑弘羊，雒陽贾人子，以心計，年十二為侍中。","sortOrder":134},
  {"id":"s_work_nvlt_48_135","chapterId":"ch_work_nvlt_48","text":"又曰：霍去病，以皇後姊子，年十八為侍中，善騎射。","sortOrder":135},
  {"id":"s_work_nvlt_48_136","chapterId":"ch_work_nvlt_48","text":"又曰：留侯子張辟強，為侍中，年十五。","sortOrder":136},
  {"id":"s_work_nvlt_48_137","chapterId":"ch_work_nvlt_48","text":"又曰：孝惠時，侍中皆冠鵕鸃，貝帶，傅脂粉。","sortOrder":137},
  {"id":"s_work_nvlt_48_138","chapterId":"ch_work_nvlt_48","text":"又曰：張安世子孫，自宣元以來為侍中。","sortOrder":138},
  {"id":"s_work_nvlt_48_139","chapterId":"ch_work_nvlt_48","text":"又曰：元帝以史丹為侍中，出則陪乘。","sortOrder":139},
  {"id":"s_work_nvlt_48_140","chapterId":"ch_work_nvlt_48","text":"又曰：侍中金敞，與劉更生拾遺左右，萧望之周堪四人，同心辅政。","sortOrder":140},
  {"id":"s_work_nvlt_48_141","chapterId":"ch_work_nvlt_48","text":"又曰：衛尉金敞病甚，成帝拜子涉為侍中，使绿車載送衛尉府，［載以皇孫車，寵之。］","sortOrder":141},
  {"id":"s_work_nvlt_48_142","chapterId":"ch_work_nvlt_48","text":"《三辅故事》曰：金日磾忠勤守節，七世為侍中。","sortOrder":142},
  {"id":"s_work_nvlt_48_143","chapterId":"ch_work_nvlt_48","text":"《魏志》曰：蘇則拜侍中，與董昭同寮，昭常枕則膝臥，則推之曰：蘇則之膝，非佞人之枕。","sortOrder":143},
  {"id":"s_work_nvlt_48_144","chapterId":"ch_work_nvlt_48","text":"又曰：陳群為侍中，領丞相東西曹掾。","sortOrder":144},
  {"id":"s_work_nvlt_48_145","chapterId":"ch_work_nvlt_48","text":"《華陽國志》曰：谯隆為上林令，武帝欲廣上林苑，隆言尧舜至治廣德，不務林苑，帝後思其言，徵為侍中。","sortOrder":145},
  {"id":"s_work_nvlt_48_146","chapterId":"ch_work_nvlt_48","text":"《益部耆舊傳》曰：蜀郡張宽，漢武帝時為侍中，從祀甘泉，至渭桥，有女子浴於渭水，乳長七尺，上怪其異，遣問之，女曰：帝後第七車知我所來，時宽在第七車，對曰：天星主祭祀者，斋戒不嚴則女人見。","sortOrder":146},
  {"id":"s_work_nvlt_48_147","chapterId":"ch_work_nvlt_48","text":"《文士傳》曰：張衡拜侍中，恒居帏幄，儀容諷議，拾遺左右。","sortOrder":147},
  {"id":"s_work_nvlt_48_148","chapterId":"ch_work_nvlt_48","text":"挚虞决疑要註曰：漢末丧亂，絕無玉珮，侍中王粲識舊珮，始复作之，今之玉珮，受法自於王粲也。","sortOrder":148},
  {"id":"s_work_nvlt_48_149","chapterId":"ch_work_nvlt_48","text":"王隱《晉書》：韦誕以能書，留補侍中，魏氏寶器銘題，皆誕書也。","sortOrder":149},
  {"id":"s_work_nvlt_48_150","chapterId":"ch_work_nvlt_48","text":"七賢傳曰：山涛，太始七年為侍中，詔書曰：涛清風淳履，思心通遠，宜侍帏幄，盡規左右。","sortOrder":150},
  {"id":"s_work_nvlt_48_151","chapterId":"ch_work_nvlt_48","text":"顏含別傳曰：顏髡，字君道，儀状嚴整，風貌端美，大司馬桓公叹曰：廊廟之望，喉舌機要。","sortOrder":151},
  {"id":"s_work_nvlt_48_152","chapterId":"ch_work_nvlt_48","text":"《續搜神記》曰：程鹹，字延休，其母始懷鹹，老公授藥與之，服此當生貴子，晉武帝時，歷位至侍中，有名於世。","sortOrder":152},
  {"id":"s_work_nvlt_48_153","chapterId":"ch_work_nvlt_48","text":"《語林》曰：晉孝武好與虞嘯父飲酒，不醉不出，後臨出拜，殆不复起，帝因呼人扶上殿，虞［《太平御覽》二百十九虞上有扶字。］侍中，嘯父答曰：臣位未及扶，醉未及亂，非分之賜，所不敢當，帝美之，敕左右疏其語。","sortOrder":153},
  {"id":"s_work_nvlt_48_154","chapterId":"ch_work_nvlt_48","text":"相書占氣雜要曰：氣如連珠入闕門，為侍中。","sortOrder":154},
  {"id":"s_work_nvlt_48_155","chapterId":"ch_work_nvlt_48","text":"沈約宋書，陆仲元者，晉太尉玩曾孫也，為侍中，吳郡太守，自玩至仲元，四世為侍中，時人方之金張二族。","sortOrder":155},
  {"id":"s_work_nvlt_48_156","chapterId":"ch_work_nvlt_48","text":"又曰：殷景仁遷侍中，與王華王曇首劉湛四人，併時為侍中，皆以風力局幹，冠冕一時，同升之美，近代莫及。","sortOrder":156},
  {"id":"s_work_nvlt_48_157","chapterId":"ch_work_nvlt_48","text":"又曰：王僧綽遷為侍中，任以機密，時年二十九，始興王濬，嘗問其年，僧綽自嫌早達，逡巡良久乃答，其謙虛自退若此。","sortOrder":157},
  {"id":"s_work_nvlt_48_158","chapterId":"ch_work_nvlt_48","text":"【碑】晉裴希聲侍中嵇侯碑曰：夫君親之重，非名教之謂也，愛敬出於自然，而忠孝之道畢矣，朴散真離，背生殉利，禮法之興，於斯為薄，悲夫，晉弋陽子嵇紹，字延祖，資乾刚之純粹，體中和之淑虛，少有清劭之風，長懷弘仁之度，加以通朗淹濟，靡才不經，學為儒宗，庶績光被，弱冠登朝，則敷文秘閣，晚節強仕，則納言枢極，太安之初，權臣擅命，皇舆親征，次於荡陰，六軍奔攻，兵交御輦，紹俨然端冕，正色以扞鋒刃，遂殒命於御侧，忠誠感人神，義聲震四海，銘曰：二儀肇建，君臣攸序，峨峨侍中，應期作辅，外播仁風，內舉心膂，執慈弗勇，靡仁不武，見危授命，背生殉主，確乎其操，邈乎其崇，矯矯王臣，憲慈遺風，在親成孝，於敬成忠。","sortOrder":158},
  {"id":"s_work_nvlt_48_159","chapterId":"ch_work_nvlt_48","text":"宋傅亮侍中王公碑曰：體亚黃中，道及微管，元勋盛德，光於晉載，於時運距無妄，陵夷有漸，至於兵纏象魏，壘結四郊，公以民望晉朝，居疑間之际，懷方履順，處艱以貞，顛沛不能回其操，彊御無以荡其守，鑠矣公侯，乘和挺生，識深冬潭，文艳春榮，爰初素履，好是冲默，亦既端委，振風育德。","sortOrder":159},
  {"id":"s_work_nvlt_48_160","chapterId":"ch_work_nvlt_48","text":"【墓志】宋孝武故侍中司徒建平王宏墓志曰：含榮幼耀，膺和早慧，徘徊天人，優遊經藝，鸿沴才流，皇根中絕，體孝盡性，懷追孝烈，反我宸居，毀網更結，管機凝務，端朝贊契，召辉才融，士穎風折，秘路長陰，昭涂永滅。","sortOrder":160},
  {"id":"s_work_nvlt_48_161","chapterId":"ch_work_nvlt_48","text":"梁元帝侍中新渝侯墓志銘曰：爰始降神，誕茲初載，方琮有燭，圓珠無颣，義若聯朅，文同藻繪，三分竹使，再徙建旟，朱帷自舉，白鹿隨車，武實威邊，文能懷遠，乍歌去速，時謠來晚，昔我往矣，千驷連辀，今茲旋旆，双雁隨舟，山回素旐，水导丹旒，寂寥原野，搖落徂秋。","sortOrder":161},
  {"id":"s_work_nvlt_48_162","chapterId":"ch_work_nvlt_48","text":"又侍中吳平光侯墓志曰：惟嶽降神，表山甫之德，敬如君所，顯成季之徵，絜靜精微，岐嶷天挺，學兼義府，談均理窟，歷太子洗馬，八人掌藉，為崇賢之領袖，五日來朝，冠承華之楷模，遷豫章內史，洪井鸞峰，甘露歲下，萧崖鶴嶺，連理成陰，徵為太子左衛率，遘疾薨於道，頗類陶基，民號夫比，取譬羊祜，巷哭荆南，副君早垂隆眄，悯其石火，瞻斯翠蓋，忽变丹旒，方使桓侯石椁，載銘盛夏，滕令嘉誠，式镌韶濩。","sortOrder":162},
  {"id":"s_work_nvlt_48_163","chapterId":"ch_work_nvlt_48","text":"隋江總故侍中沈钦墓志曰：早結南陽之親，致興沛市之役，四埏多難，三江屢梗，君敦淳化，以励浇風，庶涤清流，以荡濁俗，早遘紫雲，遂濡碧海，奋里闬之寵，躍車馬之貴，哂窦氏之青山，恥郭家之金穴。","sortOrder":163},
  {"id":"s_work_nvlt_48_164","chapterId":"ch_work_nvlt_48","text":"【诔】魏陳王曹植侍中王粲诔曰：維建安二十三年，侍中王君薨，皇穹神察，哲人足恃，如何靈祇，殲我吉士，誰謂不痛，早世即冥，誰謂不傷，華孕中零，存已分流，天墜同期，朝聞夕没，先民所思，何以诔德，表之素旟，何以赠終，哀以送之，強記洽聞，幽贊微言，文若春華，思若涌泉，發言成詠，下筆成篇，予與夫［原訛失，據冯校本改。］子，義貫丹青，庶幾遐年，携手同征，如何奄忽，弃我宿零。","sortOrder":164},
  {"id":"s_work_nvlt_48_165","chapterId":"ch_work_nvlt_48","text":"【表】梁任孝恭為羊侍中讓表曰：摶風扇翮，不覺高升，击水扬鬐，遂迷遠大，猶原長城巨防，射魯仲之書，白羽朱旗，振武安之幾，深入五千，張空拳以報主，橫行十萬，勒燕嶺而酬君。","sortOrder":165},
  {"id":"s_work_nvlt_48_166","chapterId":"ch_work_nvlt_48","text":"梁丘遲為范［《太平御覽》二百十九作范，按梁書十三范雲傳雲卒，追赠衛將軍。當作范。］衛軍讓梁台侍中表曰：是以懷鉛早歲，不以陨獲累心，躡屦晚坐，豈以充诎在念，易農伊泰，仕焉已幸，遂复分竹九嶷，擁旄百越，值天地中开，神武再廓，麻絲是蓄，菅蒯靡遺，今霸運肇基，四海明目，枢捷規獻，寔在得人，况處庸微，何用膺荷。","sortOrder":166},
  {"id":"s_work_nvlt_48_167","chapterId":"ch_work_nvlt_48","text":"又為何尚書重讓侍中領驍騎表曰：臣擢自散辈之中，寘彼周行之上，既慚伯豪，使天下慎選。又乖平叔，令內外得人，且玉壶獨掌，見榮昌期，當尺可參，必簡英俊。","sortOrder":167},
  {"id":"s_work_nvlt_48_168","chapterId":"ch_work_nvlt_48","text":"梁王筠為從兄讓侍中表曰：至如元勋奋儒之胄，積德累仁之基，九世七葉之華，相韓事漢之貴，不然則子駿之學洞古今，平子之思侔造化，仲宣之言，［《初學記》十二言字無。］辯識無滯，次重之解經不窮，然後可以喻旨公卿，問對帷扆，陪六尺之身，通四方之意，求之微臣，此涂頓隔。","sortOrder":168},
  {"id":"s_work_nvlt_48_169","chapterId":"ch_work_nvlt_48","text":"梁任昉為王思遠讓侍中表曰：行則六尺之內，陪接天光，語則親玺甲［《初學記》十二作申］命，誠信區宇，獻可替否，出納惟幾，敷表日［二字初學記作奏。］於聲華之上，進讓於玉堂之下，金遷七貴之茂，玉粲二公之孫，雖复仲蔚孤緒，元卿末名，不階民譽，妄承典私者也。","sortOrder":169},
  {"id":"s_work_nvlt_48_170","chapterId":"ch_work_nvlt_48","text":"北齊邢子才為彭城王韶讓侍中表曰：貂鼴［《太平御覽》二百十九作鼲。］暎首，日月在前，冠蓋庶僚，跨躡多士，雖智慚量力，明闕自知，在梁之譏，無得喧華之議，素餐之责，豈須噂〈口沓〉之口，何悟天之情眷，复延今寵，遂總錄百揆，寅亮萬機，文昌治本，得失所系，用才長短，隆替［《御覽》替下有以之二字。］何容以斯豈得，［御覽作寡薄。］用膺茲忝。","sortOrder":170},
  {"id":"s_work_nvlt_48_171","chapterId":"ch_work_nvlt_48","text":"【啟】梁陆倕張侍中啟曰：陳力就列，不能者止，實欲強飯據鞍，自窮心力，濡足磨顶，少報洪私，徒課虛無，空延鍾箭，不悟爰降曲慈，复叨清顯，職司近切，任掌總纶，魏選異才，漢求高德，官次恪居，鮮非民譽，仰瞻內省，無一可階。","sortOrder":171},
  {"id":"s_work_nvlt_48_172","chapterId":"ch_work_nvlt_48","text":"◇黃門侍郎","sortOrder":172},
  {"id":"s_work_nvlt_48_173","chapterId":"ch_work_nvlt_48","text":"漢書百官表曰：中黃門有給事黃門，位從將軍大夫，皆秦製。","sortOrder":173},
  {"id":"s_work_nvlt_48_174","chapterId":"ch_work_nvlt_48","text":"《漢書》曰：張禹為太傅，有疾，成帝臨视，拜於床下，禹有少子在侧，目之，帝知其意，於前拜黃門侍郎。","sortOrder":174},
  {"id":"s_work_nvlt_48_175","chapterId":"ch_work_nvlt_48","text":"又曰：劉向，字子政，宣帝時，以中郎為給事黃門侍郎。","sortOrder":175},
  {"id":"s_work_nvlt_48_176","chapterId":"ch_work_nvlt_48","text":"又曰：董賢，字聖卿，雲陽人，為太子舍人，隨太子官，為郎二歲為，［漢書董賢傳作餘。］賢傳漏在殿下，為人美麗白皙，哀帝望見，悅其儀貌，識而問之曰：是舍人董賢耶，因引上與語，拜為黃門侍郎。","sortOrder":176},
  {"id":"s_work_nvlt_48_177","chapterId":"ch_work_nvlt_48","text":"又曰：楊雄，成帝時為郎，至平帝，猶黃門侍郎。","sortOrder":177},
  {"id":"s_work_nvlt_48_178","chapterId":"ch_work_nvlt_48","text":"《漢舊儀》曰：黃門郎，日暮入對青璅門，名曰夕郎。","sortOrder":178},
  {"id":"s_work_nvlt_48_179","chapterId":"ch_work_nvlt_48","text":"三辅訣錄曰：杜恕，字務伯，拜黃門侍郎，每宣省閤，威儀矜嚴。","sortOrder":179},
  {"id":"s_work_nvlt_48_180","chapterId":"ch_work_nvlt_48","text":"又曰：卓茂，字子康，元帝時，遊學長安，以儒行為給事黃門郎。","sortOrder":180},
  {"id":"s_work_nvlt_48_181","chapterId":"ch_work_nvlt_48","text":"又曰：馬後志在克己辅王，不以私家幹朝廷，兄為虎贲中郎將，弟為黃門郎，訖永平世不遷。","sortOrder":181},
  {"id":"s_work_nvlt_48_182","chapterId":"ch_work_nvlt_48","text":"《魏略》曰：董遇，字季直，為黃門侍郎，旦夕侍講，為天子所愛信。","sortOrder":182},
  {"id":"s_work_nvlt_48_183","chapterId":"ch_work_nvlt_48","text":"《魏略》曰：王粲，字仲宣，山陽人，年十七，司徒辟，詔除黃門侍郎，以西京扰亂，皆不就。","sortOrder":183},
  {"id":"s_work_nvlt_48_184","chapterId":"ch_work_nvlt_48","text":"又曰：夏侯玄，字太初，少知名，弱冠為散騎常侍黃門侍郎，嘗進見，與皇後弟毛曾併坐，玄恥之，不悅，形之於色，明德［《太平御覽》二百二十一作帝］恨之，左遷為羽林監。","sortOrder":184},
  {"id":"s_work_nvlt_48_185","chapterId":"ch_work_nvlt_48","text":"又曰：鍾毓，年十四，拜散騎侍郎，遷黃門郎。","sortOrder":185},
  {"id":"s_work_nvlt_48_186","chapterId":"ch_work_nvlt_48","text":"《英雄記》曰：曹純，字子和，年十六，為黃門侍郎。","sortOrder":186},
  {"id":"s_work_nvlt_48_187","chapterId":"ch_work_nvlt_48","text":"任嘏別傳曰：嘏字昭先，魏文帝以嘏為黃門郎，每納中言，辄手坏其本，自在禁省，歸不書封，帝嘉其淑慎。","sortOrder":187},
  {"id":"s_work_nvlt_48_188","chapterId":"ch_work_nvlt_48","text":"王隱《晉書》曰：張華為黃門侍郎，博覽圖籍，四海之內，若指諸掌，世祖問華，長安千門萬戶，畫地便成。","sortOrder":188},
  {"id":"s_work_nvlt_48_189","chapterId":"ch_work_nvlt_48","text":"齊職儀曰：給事黃門侍郎四人，秩六百硕，武冠，絳朝服，漢有中黃門，位從諸大夫，秦製也，與侍中掌奏文案，贊相威儀，典署其事。","sortOrder":189},
  {"id":"s_work_nvlt_48_190","chapterId":"ch_work_nvlt_48","text":"沈約《宋書》曰：給事黃門侍郎，秦官也，有事郊廟，則一人持蓋，與侍中俱管門下眾事。","sortOrder":190},
  {"id":"s_work_nvlt_48_191","chapterId":"ch_work_nvlt_48","text":"【墓志】梁元帝黃門侍郎劉孝綽墓志銘曰：蔡墨攸陳，有草有茵，梁荆世樻，或魏或秦，積善餘慶，時惟俊民，孝乎惟孝，其德有鄰，曰風曰雅，文章動神，鶴开阮瑀，鵬翥楊循，身茲惟屈，扶搖未申，人罔石火，山有楸椿，佳城無曙，寒野方春。","sortOrder":191},
  {"id":"s_work_nvlt_48_192","chapterId":"ch_work_nvlt_48","text":"【诔】宋謝莊黃門侍郎劉琨之诔曰：秋風散兮涼葉稀，出吳州兮謝江幾，瞻國門兮耸雲路，睇舊里兮驚客衣，魂終朝而三奪，心一夜而九飛，過建春兮背闕庭，歷承明兮去城輦，旌徘徊而北系，轜逶遲而不轉，挽掩隧而辛嘶，骥含愁而鳴俯，顧物色之共傷，見車徒之相泫。","sortOrder":192},
  {"id":"s_work_nvlt_48_193","chapterId":"ch_work_nvlt_48","text":"◇散騎常侍","sortOrder":193},
  {"id":"s_work_nvlt_48_194","chapterId":"ch_work_nvlt_48","text":"應劭《漢書》曰：秦官，及漢，置散騎及中常侍各一人，獻可替否也。","sortOrder":194},
  {"id":"s_work_nvlt_48_195","chapterId":"ch_work_nvlt_48","text":"華峤集曰：散騎，以從容侍從，承答顧問為職。又掌贊詔命，平處文籍，故前世多參用言語文學之士。","sortOrder":195},
  {"id":"s_work_nvlt_48_196","chapterId":"ch_work_nvlt_48","text":"王隱《晉書》曰：鄭默為散騎常侍，世祖祀南郊，侍中已陪乘，詔曰：使鄭常侍默，曰：卿之何以得參乘，昔州內舉卿相辈，常愧有累清談。","sortOrder":196},
  {"id":"s_work_nvlt_48_197","chapterId":"ch_work_nvlt_48","text":"七賢傳曰：阮籍，高貴乡［按乡下當脱公字。］以為散騎常侍，非其好也。","sortOrder":197},
  {"id":"s_work_nvlt_48_198","chapterId":"ch_work_nvlt_48","text":"《晉中興書》曰：庾闡有文章才義，議者以為宜綜國史，於是召為散騎常侍。","sortOrder":198},
  {"id":"s_work_nvlt_48_199","chapterId":"ch_work_nvlt_48","text":"又曰：謝萬，升平五年詔曰：前西中郎萬，才義簡亮，宜居獻替，其為散騎常侍。","sortOrder":199},
  {"id":"s_work_nvlt_48_200","chapterId":"ch_work_nvlt_48","text":"【墓志】梁元帝散騎常侍裴子野墓志銘曰：幾原博聞，裁為典墳，比良班馬，等麗卿雲，董籍既別，涇渭以分，聖皇御極，钦賢盱顧，储後特聖，降情文苑，既匹嚴朱，复同徐阮，如何不慭，卜期斯遠。","sortOrder":200},
  {"id":"s_work_nvlt_48_201","chapterId":"ch_work_nvlt_48","text":"【诔】晉潘嶽散騎常侍夏侯湛诔曰：英英夫子，灼灼其俊，飛辯摛藻，華繁玉振，畴昔之遊，二紀於茲，斑白携手，何歡如之，居吾語爾，眾不勝悲，人惡俊異，世疵文雅，執戟疲扬，長沙役贾，無位爾高，恥居物下，子乃洗然，变化易容，慨然叹曰：道固不同，為仁由己，匪我求蒙，誰毀誰譽，何去何從，莫涅匪緇，莫磨匪磷，子獨正色，居屈志申，我聞積善，神降之吉，宜享遐紀，長保天秩，如何斯人，而有斯疾，曾未知命，中年殒卒。","sortOrder":201},
  {"id":"s_work_nvlt_48_202","chapterId":"ch_work_nvlt_48","text":"晉劉琨散騎常侍劉府君诔曰：爰自上葉，帝尧之胤，堂堂漢祖，豁豁高韻，茂載孝景，克紹前訓，穆矣靖王，开國作镇，惟祖惟父，乃光有晉，積行累仁，世篤忠順，是用感和，誕育奇俊，淑质英挺，金聲玉振，嗟乎君侯，仍寢斯疾，命不可延，中年殒卒，冲飆摧華，阆風彫實，如可贖兮，人百其质，存若燭龍衔曜，没若庭燎俱滅，搢紳頹范於高模，邦國弥悴於陨哲。","sortOrder":202},
  {"id":"s_work_nvlt_48_203","chapterId":"ch_work_nvlt_48","text":"【表】陳徐陵讓散騎常侍表曰：臣聞五十知命，宗師之格言，六百辭滿，通賢之高槩，昔墨子諸生，褰裳求楚，魯連隱士，高論却秦，况乎谬蒙知己，寧無感激，洪私過誤，寘以通班，司憲文昌，遂偕常伯，今者崑吳［本集作吾］小器，諦视不見玄黃，均天併奏，靜聽能［本集能下有聞字。］鍾鼓，雖神農分藥，歧伯提針，冥眾因緣，難可匡救，陛下嗣臨寶歷，光闡大猷，屬意铨衡，留情槱棫，燕台裝玉，傥不精真，齊客吹竽，谅宜澄簡，南郊奉乘，當求部黜之才，西省文辭，應用羅含之學。","sortOrder":203},
  {"id":"s_work_nvlt_48_204","chapterId":"ch_work_nvlt_48","text":"◇給事中","sortOrder":204},
  {"id":"s_work_nvlt_48_205","chapterId":"ch_work_nvlt_48","text":"東方朔記曰：東方朔為中郎，賜帛百匹，拜給事中。","sortOrder":205},
  {"id":"s_work_nvlt_48_206","chapterId":"ch_work_nvlt_48","text":"《漢書》曰：萧望之，元帝詔，望之傅朕八年，可賜爵關內侯，給事中。","sortOrder":206},
  {"id":"s_work_nvlt_48_207","chapterId":"ch_work_nvlt_48","text":"漢書百官表曰：給事中，亦加官，或大夫博士議郎，掌顧問應對，位次中常侍。","sortOrder":207},
  {"id":"s_work_nvlt_48_208","chapterId":"ch_work_nvlt_48","text":"胡廣曰：給事中，常侍從左右，無員，位次侍中之下，常侍，或名儒，或國親。","sortOrder":208},
  {"id":"s_work_nvlt_48_209","chapterId":"ch_work_nvlt_48","text":"《漢書》曰：劉向，字子政，諫議大夫，給事。","sortOrder":209},
  {"id":"s_work_nvlt_48_210","chapterId":"ch_work_nvlt_48","text":"《魏略》曰：邯鄲淳，字子淑，黃初初，為博士，給事中。","sortOrder":210},
  {"id":"s_work_nvlt_48_211","chapterId":"ch_work_nvlt_48","text":"束晳集曰：員外侍郎及給事冗從，皆是帝室茂親，或貴遊子弟。","sortOrder":211},
  {"id":"s_work_nvlt_48_212","chapterId":"ch_work_nvlt_48","text":"晉武帝詔，燕上臨［《初學記》十二。］《太平御覽》二百二十一作王師，陳劭，清貞廉絜，博通六籍，宜在左右，以敦儒訓，可給事中。","sortOrder":212},
  {"id":"s_work_nvlt_48_213","chapterId":"ch_work_nvlt_48","text":"荀綽兖州記曰：袁淮，字孝尼，有俊才，太始中，為給事中。","sortOrder":213},
  {"id":"s_work_nvlt_48_214","chapterId":"ch_work_nvlt_48","text":"【诔】宋顏延之給事中楊［《文選》五十七作陽，下同。］瓒诔曰：瓒少禀志節，資性忠淳，永初之末，佐守滑台，獯虜間衅，剂［《文選》作劘。］剝司兖，［原訛袞，據冯校本改。］瓒立乎將帥之間，以緝華裔之眾，疲困相保，堅守四旬，兵盡器竭，毙於旗下，非夫貞壮之氣，勇烈之志，豈能臨死殉義，以死偿節者哉，之子間，［按間下有脱文，文選作之子之生，下簡兵授才句，衍一生字，疑當作之子間生，誤衍在彼。］立績宋皇，如彼竹柏，負雪懷霜，如彼騑驷，親驂衡驤，邊兵丧律，王略未恢，函陝湮阻，纏路蒿萊，朔馬東驚，胡風吹埃，帝圖斯難，簡生丘［《文選》生字無，丘作兵。］授才，實命楊子，佐師危台，過矣獯虜，乘障犯威，鳴骥厲霜，羽鏑高翚，軼我河縣，俘我洛畿，攒鋒成林，投鞍為围，師老变形，地孤援闊，卒無菽麥，馬乏刍秣，烈烈楊子，在困弥達，力雖可窮，氣不可奪，義立邊疆，身終鋒楯。","sortOrder":214},
  {"id":"s_work_nvlt_48_215","chapterId":"ch_work_nvlt_48","text":"◇中書令","sortOrder":215},
  {"id":"s_work_nvlt_48_216","chapterId":"ch_work_nvlt_48","text":"《漢書》曰：馬遷既被刑之後，為中書令，尊寵在職。","sortOrder":216},
  {"id":"s_work_nvlt_48_217","chapterId":"ch_work_nvlt_48","text":"臧榮緒《晉書》曰：潘尼性澹退，唯以著述為事，永興末，為中書令。","sortOrder":217},
  {"id":"s_work_nvlt_48_218","chapterId":"ch_work_nvlt_48","text":"晉諸公贊曰：陳准為中書令，張華為監，准與華俱處機密，而准崇之，每至宣日，有詔書，無大小，辄先示華，了不厝意，華得詔書，不以示准。","sortOrder":218},
  {"id":"s_work_nvlt_48_219","chapterId":"ch_work_nvlt_48","text":"又曰：懷帝以缪播為中書令，朝事莫不谘之，人君之所取信於臣下，無以尚也。","sortOrder":219},
  {"id":"s_work_nvlt_48_220","chapterId":"ch_work_nvlt_48","text":"《晉中興書》曰：肅祖以溫峤為散騎常侍，侍講，大寧初，手詔曰：卿既以令望中允之懷，著於周旋，且文清而旨遠，宜居深密，今欲以卿為中書令，朝論亦鹹以為宜。","sortOrder":220},
  {"id":"s_work_nvlt_48_221","chapterId":"ch_work_nvlt_48","text":"又曰：顯宗加王洽中書令，帝曰：敬和清裁貴重，昔為中書郎，吾尚小，數呼見，意甚親之，今以為中書令，欲共講文章之事也。","sortOrder":221},
  {"id":"s_work_nvlt_48_222","chapterId":"ch_work_nvlt_48","text":"又曰：褚裒授衛將軍中書令，以中書铨管詔命，不宜以親居之，固讓。","sortOrder":222},
  {"id":"s_work_nvlt_48_223","chapterId":"ch_work_nvlt_48","text":"檀道鸞［《初學記》十一，《太平御覽》二百二十鸞下有晉字。］陽秋曰：溫峤為中書令，詔曰：中書之職，酬對多方，斟酌禮宜，非唯文疏而已，非望士良才，何可妄居。","sortOrder":223},
  {"id":"s_work_nvlt_48_224","chapterId":"ch_work_nvlt_48","text":"王导表曰：臣乞得除中書監，专壹所司，竭誠保傅，惟力是视，詔曰：昔荀公曾從中書監為尚書令，人贺之，乃發恚雲，奪我鳳皇池，卿諸人贺我耶，原足下處之勿疑。","sortOrder":224},
  {"id":"s_work_nvlt_48_225","chapterId":"ch_work_nvlt_48","text":"王珉別傳曰：珉字季琰，詔曰：新除侍中王珉，才學廣贍，理識清通，宜處機近，以參時務，其以珉為長兼中書令。","sortOrder":225},
  {"id":"s_work_nvlt_48_226","chapterId":"ch_work_nvlt_48","text":"沈約《宋書》曰：傅亮，永初元年，為太子詹事中書令，专典詔命，以亮任總國權，聽於省中見客，神虎門外，每旦車嘗數兩。","sortOrder":226},
  {"id":"s_work_nvlt_48_227","chapterId":"ch_work_nvlt_48","text":"世語曰：司馬景王，令尚書令虞松作表，辄不可意，令更定，松思竭，不能改，鍾會為定五字，松悅服焉。","sortOrder":227},
  {"id":"s_work_nvlt_48_228","chapterId":"ch_work_nvlt_48","text":"【墓志】梁簡文帝中書令臨汝靈侯墓志銘曰：若太祖時，其惟宣武，講道开天，儀嵩作辅，是曰邢弟，籍規承矩，如康嗣衛，以禽居魯，息辔巖隈，涂窮夜台，靈簷永阒，松路方开，草茂故轍，松插新枚，月明泉暗，暑往寒來。","sortOrder":228},
  {"id":"s_work_nvlt_48_229","chapterId":"ch_work_nvlt_48","text":"梁元帝中書令庾肩吾墓志曰：荆山萬重，地產卞和之玉，隨流千仞，水出靈蛇之珠，故能胤茲屈景，育斯唐宋，掌庚［按當作庾。］命族，世濟琳琅，遂昌开國，蝉聯冠冕，父易高尚其道，遁肥貞吉，關吏早逢，威［按當作恒。］表真人之氣，少微晚映，還彰隱士之星，肩吾氣識淹通，風神閒逸，鍾鼓辭林，笙簧文苑，入為度支尚書，任同北斗，錫韓稜之劍，朝此南宮，識鄭崇之履，餘以其為人也，瑚璉之器，無慚垂棘，杞梓之材，有均廊廟，故赠散騎常侍中書令，蓋旌賢也。","sortOrder":229},
  {"id":"s_work_nvlt_48_230","chapterId":"ch_work_nvlt_48","text":"梁張缵中書令萧子顯墓志曰：君状貌丘墟，風神磊落，閒贍動於容止，英弈發於流眄，筆鋒席上，皆如素蓄，切問近思，見稱閒敏，帝嘗顧謂君曰：我撰通史若成，眾史可废，乃答，詔雲，仲尼贊易道，黜八索，述職方，除九丘，聖製符同，复在茲日，储君毓德少陽，情协陳阮，親□妙思，式表玄右。","sortOrder":230},
  {"id":"s_work_nvlt_48_231","chapterId":"ch_work_nvlt_48","text":"【表】宋謝莊讓中書令表曰：伏惟陛下，登取震維，臨齊璿政，泽與風翔，恩從雲動，臣聞壁門天邃，鳳沼神深，絲纶王言，出內帝命，自非望允當時，譽宣庠塾，未有谬垂曲寵，空席茲榮，在於平壮，猶不可勉，况今綿痼，百志俱淪。","sortOrder":231},
  {"id":"s_work_nvlt_48_232","chapterId":"ch_work_nvlt_48","text":"◇中書侍郎","sortOrder":232},
  {"id":"s_work_nvlt_48_233","chapterId":"ch_work_nvlt_48","text":"《魏志》曰：明帝舉中書郎，謂吏部尚書盧毓曰：得其人與不得其人，在盧生爾，選舉莫取有名，如畫地作餅，不可啖也，毓舉韓暨，敦篤至行，帝乃用也。","sortOrder":233},
  {"id":"s_work_nvlt_48_234","chapterId":"ch_work_nvlt_48","text":"王隱《晉書》曰：華表子簡，字奉駿，有智器文藻，官至中書郎。","sortOrder":234},
  {"id":"s_work_nvlt_48_235","chapterId":"ch_work_nvlt_48","text":"又曰：陳寿舉孝廉，為著作郎，與張華友善，華垂當啟轉中書郎，荀勖党疾寿，華語吏部，出為長廣太守。","sortOrder":235},
  {"id":"s_work_nvlt_48_236","chapterId":"ch_work_nvlt_48","text":"臧榮緒《晉書》曰：夏侯孝若為野王令，居邑累年，朝野多叹其屈，除中書郎。","sortOrder":236},
  {"id":"s_work_nvlt_48_237","chapterId":"ch_work_nvlt_48","text":"曹嘉之《晉紀》曰：汝南史曜，為山涛所知，曜字季茂，父為征南府小吏，乡人周浚，一見曜而友之，配之妹，官至中書郎。","sortOrder":237},
  {"id":"s_work_nvlt_48_238","chapterId":"ch_work_nvlt_48","text":"沈約《晉書》曰：裴潛風神高邁，為中書郎，出入禁門，見者皆肅然改容。","sortOrder":238},
  {"id":"s_work_nvlt_48_239","chapterId":"ch_work_nvlt_48","text":"《晉中興書》曰：范甯為臨淮太守，徵拜中書郎，专掌西省，以職在機近，固辭不許，多所獻替，有益治道。","sortOrder":239},
  {"id":"s_work_nvlt_48_240","chapterId":"ch_work_nvlt_48","text":"晉起居註，詔曰：今之士大夫，多不樂出宰牧，而好內官，今皆先經外郡，治民著績，然後入為常伯中書郎。","sortOrder":240},
  {"id":"s_work_nvlt_48_241","chapterId":"ch_work_nvlt_48","text":"沈約《宋書》曰：王微與弟綽書曰：阖門皆蒙時私，吾高臥家巷，遂至中書郎，此足以阖棺也。","sortOrder":241},
  {"id":"s_work_nvlt_48_242","chapterId":"ch_work_nvlt_48","text":"王濛別傳曰：濛為中書郎，在職四年，首尾如一人，難與比肩故也。","sortOrder":242},
  {"id":"s_work_nvlt_48_243","chapterId":"ch_work_nvlt_48","text":"【詩】齊卞伯玉赴中書詩曰：大方信苞容，優泥遂不以，躍鱗經鳳池，揮翰紫宸里。","sortOrder":243},
  {"id":"s_work_nvlt_48_244","chapterId":"ch_work_nvlt_48","text":"【表】梁庾肩吾為寧國公讓中書表曰：臣聞陟彼太行，伯後之車屢怠，望慈吳坂，少遊之馬體進，是知美非流水，立致摧轅，駿靡浮雲，便其頓辔，起登天漢，寧陪九萬之風，坐濟星桥，非使千年之翼，豈有功稱辨慧，足對元禮，弱摽後穎，能嘲子叔，玉重組長，空見休寵，深宮邃宇，孰知懷忧。","sortOrder":244},
  {"id":"s_work_nvlt_48_245","chapterId":"ch_work_nvlt_48","text":"◇驃騎將軍［位次丞相］","sortOrder":245},
  {"id":"s_work_nvlt_48_246","chapterId":"ch_work_nvlt_48","text":"《漢書》曰：武帝以霍去病為嫖姚校尉，征匈奴，累有功，寵冠群臣，始置驃騎將軍，秩與大將軍同。","sortOrder":246},
  {"id":"s_work_nvlt_48_247","chapterId":"ch_work_nvlt_48","text":"韦昭辨《釋名》曰：驃騎將軍，車騎將軍，秩皆比三公，辨雲，此三將軍，秩本二千石。","sortOrder":247},
  {"id":"s_work_nvlt_48_248","chapterId":"ch_work_nvlt_48","text":"百官表註曰：驃騎將軍，漢官也，長史司馬各［《太平御覽》二百三十八，各下有一字。］人，金章紫綬，五時朝［御覽朝下有服字。］武冠，佩山玄玉，光武中興，諸將皆稱大，後天子［御覽作下。］既定，武官悉省。","sortOrder":248},
  {"id":"s_work_nvlt_48_249","chapterId":"ch_work_nvlt_48","text":"《東觀漢記》曰：其將軍不常置，比公者。又有驃騎將軍，建武二十年，复置驃騎將軍，位次公，有長史一人。","sortOrder":249},
  {"id":"s_work_nvlt_48_250","chapterId":"ch_work_nvlt_48","text":"又曰：光武以景丹為驃騎將軍。","sortOrder":250},
  {"id":"s_work_nvlt_48_251","chapterId":"ch_work_nvlt_48","text":"又曰：明帝詔曰：東平王蒼，宽博有謀，可以讬六尺之孤，臨大節而不可奪，其以蒼為驃騎將軍。","sortOrder":251},
  {"id":"s_work_nvlt_48_252","chapterId":"ch_work_nvlt_48","text":"又曰：永平二十五年，左中郎將劉隆，為驃騎將軍，即日行大司馬事。","sortOrder":252},
  {"id":"s_work_nvlt_48_253","chapterId":"ch_work_nvlt_48","text":"《魏志》曰：王昶距毌丘俭，進位驃騎將軍，世說曰：何驃騎弟五，以高情避世，而驃騎勸令仕，對曰：然弟五之稱，何必驃騎。","sortOrder":253},
  {"id":"s_work_nvlt_48_254","chapterId":"ch_work_nvlt_48","text":"【诔】晉張華魏劉驃騎诔曰：昔在殷周，惟伊惟呂，穆穆公侯，紹茲勋緒，如何上天，殲我鼎辅，金刚玉润，水絜冰清，鬱鬱文彩，煥若朝榮，功遂身退，致仕懸舆，志邈留侯，心邁二疏，風凛凛以翼衡，雲霏霏以承蓋，旐聯翩以飄銅，旌繽紛以奄薄。","sortOrder":254},
  {"id":"s_work_nvlt_48_255","chapterId":"ch_work_nvlt_48","text":"【表】梁簡文帝讓驃騎扬州刺史表曰：常原親侯就列，希同特進之班，角弓還地，不競龍驤之賞，天泽無涯，名器總集，竊以驃騎之官，既為上將，神州之重，實號中士，［《太平御覽》二百三十八作土中。］故以彈麾六戎，冠冕九牧，豈止司隸絳節，金吾提騎，况复任總皇畿，位重連率，何則，驃騎之號，歷選為重，元狩之中，始自去病，永平之建，特授劉蒼，齊憲［御覽作獻。］為公主所申，吳漢因群臣之舉。","sortOrder":255},
  {"id":"s_work_nvlt_48_256","chapterId":"ch_work_nvlt_48","text":"《藝文類聚》　唐·欧陽詢","sortOrder":256},
  {"id":"s_work_nvlt_49_1","chapterId":"ch_work_nvlt_49","text":"卷四十九職官部五據明本補","sortOrder":1},
  {"id":"s_work_nvlt_49_2","chapterId":"ch_work_nvlt_49","text":"○騎太常衛尉太仆廷尉鸿臚司農將作光祿大夫太子詹事太子中庶子太子舍人","sortOrder":2},
  {"id":"s_work_nvlt_49_3","chapterId":"ch_work_nvlt_49","text":"◇太常","sortOrder":3},
  {"id":"s_work_nvlt_49_4","chapterId":"ch_work_nvlt_49","text":"《尚書》曰：伯夷秩宗，典朕三禮。","sortOrder":4},
  {"id":"s_work_nvlt_49_5","chapterId":"ch_work_nvlt_49","text":"《周官》曰：春官宗伯，掌天神地祇。","sortOrder":5},
  {"id":"s_work_nvlt_49_6","chapterId":"ch_work_nvlt_49","text":"《漢書》曰：太常，秦官，掌宗廟禮儀。","sortOrder":6},
  {"id":"s_work_nvlt_49_7","chapterId":"ch_work_nvlt_49","text":"漢官典職曰：惠帝政［《太平御覽》二百二十八作改。］太常為奉常，景帝复太常，蓋周官宗伯也。","sortOrder":7},
  {"id":"s_work_nvlt_49_8","chapterId":"ch_work_nvlt_49","text":"漢官解詁曰：太常社稷郊畤，事重職尊，故在九卿之首。","sortOrder":8},
  {"id":"s_work_nvlt_49_9","chapterId":"ch_work_nvlt_49","text":"衛宏古文官書曰：太常主导贊助祭，皆平冕七旒，玄上纁下，畫華虫七章，漢陵屬三辅，太常月一行。","sortOrder":9},
  {"id":"s_work_nvlt_49_10","chapterId":"ch_work_nvlt_49","text":"《史記》曰：叔孫通為奉常，賜金五百斤，通因進言曰：諸弟子儒生，隨臣久矣，與共為儀，原陛下官之，高帝悉以為郎，通出，皆以五百斤金賜諸生，諸生曰：叔孫生聖人也，知當世務。","sortOrder":10},
  {"id":"s_work_nvlt_49_11","chapterId":"ch_work_nvlt_49","text":"《漢書》曰：武帝元鼎二年，廣安侯任越人為太常，坐廟酒醉論。","sortOrder":11},
  {"id":"s_work_nvlt_49_12","chapterId":"ch_work_nvlt_49","text":"又曰：武帝元封四年，酂侯萧寿成為太常，坐犧牲不如令論。","sortOrder":12},
  {"id":"s_work_nvlt_49_13","chapterId":"ch_work_nvlt_49","text":"又曰：孝武帝元朔元年，孔臧為太常，坐南陵桥坏，衣冠道絕，免。","sortOrder":13},
  {"id":"s_work_nvlt_49_14","chapterId":"ch_work_nvlt_49","text":"《續漢書》曰：太常卿，每祭祀，先奏其禮儀，及行事賞罰，天子每選试博士，奏其能否。","sortOrder":14},
  {"id":"s_work_nvlt_49_15","chapterId":"ch_work_nvlt_49","text":"華峤《後漢書》曰：劉恺為太常，論議常引正大義，諸儒為之語曰：難經伉伉劉太常。","sortOrder":15},
  {"id":"s_work_nvlt_49_16","chapterId":"ch_work_nvlt_49","text":"《東觀漢記》曰：桓榮為太常，上幸太常府，榮東面坐，設九賓會，子鬱，以明經，复為太常。","sortOrder":16},
  {"id":"s_work_nvlt_49_17","chapterId":"ch_work_nvlt_49","text":"應劭《漢官》曰：周泽為太常，斋有疾，其妻怜其年老被病，闚內問之，泽大怒，以為幹斋，掾吏爭之不聽，遂收送詔獄，併自劾謝，論者譏其激發不實。又諺曰：居世不諧，為太常妻，一歲三百六十日，三百五十九日斋，一日不斋醉如泥。","sortOrder":17},
  {"id":"s_work_nvlt_49_18","chapterId":"ch_work_nvlt_49","text":"《益部耆舊傳》曰：趙典為太常，雖身處上卿，而布被瓦器。","sortOrder":18},
  {"id":"s_work_nvlt_49_19","chapterId":"ch_work_nvlt_49","text":"齊職儀曰：太常卿一人，品第三，秩中二千石，銀章青綬，進賢兩梁冠，絳朝服，佩水蒼玉，王朗雲，西京太常行陵，赤車千乘。","sortOrder":19},
  {"id":"s_work_nvlt_49_20","chapterId":"ch_work_nvlt_49","text":"【贊】晉潘嶽故太常任府君畫贊曰：堂堂我君，鑒象开慶，逸德宣猷，含真履素，味道無悶，守終純固，弓舆爰集，撫翼清舉，翰飛公庭，龍升天路，初掌方國，流化千里，遂管秘籍，辯章舊史，入登常伯，出作卿士，外內惟允，庶績鹹理，中節日新，令問不已，濟濟儒林，翼翼國子。","sortOrder":20},
  {"id":"s_work_nvlt_49_21","chapterId":"ch_work_nvlt_49","text":"晉孫綽太常碑贊曰：海岱协靈，育此多士，瓘瓘君侯，東國之紀，金德發耀，英風劭起，文齊遊夏，行儔魯史，有邈其升，令問不已，人亦有言，德崇譽高，束帛既言，旌節仍招，儀形朝堂，流風丹霄，將振華袞，永［原訛冰，據冯校本改。］涣皇朝，上帝靡監，曾不遐齡，衛霍頹镇，哲人其傾，邦國殄瘁，搢紳丧情，仰邦高范，永播休聲。","sortOrder":21},
  {"id":"s_work_nvlt_49_22","chapterId":"ch_work_nvlt_49","text":"【箴】漢楊雄［《初學記》十二作崔骃。］太常箴曰：翼翼太常，寔為宗伯，穆穆靈祗，寢廟弈弈，稱秩元祀，班於群臣，我粢孔蠲，［原訛觸，據冯校本改。］匪愆匪忒，君子攸宜，無曰我［原訛象，據冯校本改。］材，輕身恃巫，［原訛博坐，據冯校本改。］東鄰之犧牛，不如西鄰之麥魚，秦殒望夷，隱弊鍾靈，常臣司宗，敢告執書。","sortOrder":22},
  {"id":"s_work_nvlt_49_23","chapterId":"ch_work_nvlt_49","text":"【墓志】梁元帝太常卿陆倕墓志銘曰：如金有鑛，如竹有筠，體二方擬，知十可鄰，兩升鳳詔，三侍龍樓，南皮朝宴，西園夜遊，詞峰飆竖，逸氣雲浮，日往月來，暑流寒袭，東耀方遠，北芒已及，墜露晓团，悲風暮急。","sortOrder":23},
  {"id":"s_work_nvlt_49_24","chapterId":"ch_work_nvlt_49","text":"梁沈約太常卿任昉墓志銘曰：天才俊逸，文雅弘備，心為學府，辭同錦肆，含華振藻，鬱焉高政，［按據用韻，疑當作致。］川谿望歸，巖阿待闕，幽光忽斷，窮燈黯滅，爾有令問，蘭薰無絕。","sortOrder":24},
  {"id":"s_work_nvlt_49_25","chapterId":"ch_work_nvlt_49","text":"【表】梁陆倕為王光祿轉太常讓表曰：昔者楚德方盛，孫淑濯衣，漢道克隆，王陽結綬，故拜命無辭，受爵不讓，况宗卿清重，歷選所難，漢晉已降，莫非素范，辭爵則張奋，讓封則丁鸿，劉恺潘尼之文雅深純，華表之從容退嘿，自此迄茲，風流繼軌，以臣况之，曾無等級。","sortOrder":25},
  {"id":"s_work_nvlt_49_26","chapterId":"ch_work_nvlt_49","text":"陳沈蜅為周弘［原脱，據《太平御覽》二百二十八弘下有正字，此脱。］讓太常表曰：臣聞玉為彫楹，不數材於蟠木，丹成繡黼，豈袭冕於萝薜，何則，適用各有所宜，朝野不可一指，叔孫之分定禮儀，倍資典實，刁协之躬為唱引，豈易其儀，賓主闕對，封禪失儀，责以司存，雲誰之咎，况南史執簡，轉見违才，君舉必書，尤輕妄冒。","sortOrder":26},
  {"id":"s_work_nvlt_49_27","chapterId":"ch_work_nvlt_49","text":"【傳】梁王僧孺太常敬子任府君傳曰：恥一物之不知，惜寸陰之徒靡，下帷閉戶，投斧想梁，雖玄晏書淫，文勝經溢，康成之忽忘所往，公叔之顛墜硎岸，無以異也，若夫天才卓爾，動稱絕妙，辭賦極其清深，筆記尤盡典實，若聞金石，似註河海，少孺速［原訛迷，據冯校本改。］而未工，長卿工而未速，孟堅辭不逮理，平子意不及文，孔璋傷於健，仲宣病於弱，其有集論借書，窮文质之敏，駐馬停信，極亹亹之功，莫尚於斯焉，君職等曹張，聲高左陆，時乃高辟雪宮，廣开雲殿，秋窗春戶，冬燠夏凊，九醞斯浮，百羞併荐，雲銷月朗，聿茲遊客，朋來旅見，辭人才子，辯圃學林，莫不含毫咀思，爭高競敏，乃整袂端襟，翰飛紙落，豪人貴仕，先達後進，莫不心服貌慚，袖氣將盡，顧餘不敏，廁夫君子之末，可稱冥契，是為神交，二三君子，唯以從遊日暮，亭號昭仁，庶子雲咫尺，康成斯在，借此嘉言，將無絕乎千載。","sortOrder":27},
  {"id":"s_work_nvlt_49_28","chapterId":"ch_work_nvlt_49","text":"◇衛尉","sortOrder":28},
  {"id":"s_work_nvlt_49_29","chapterId":"ch_work_nvlt_49","text":"《漢書》曰：衛尉，秦官，掌宮門衛屯兵，景帝初，更名中大夫，後元年，复為衛尉。","sortOrder":29},
  {"id":"s_work_nvlt_49_30","chapterId":"ch_work_nvlt_49","text":"漢官解詁曰：衛尉，主宮闕之內，衛士於垣下為庐，各有員部，凡居宮中者，皆施藉於門，案其姓名，若有医巫僦人當入者，本官長吏為封，啟傅，［初學記十二，《太平御覽》二百三十作傳。］審其印信，然後內之，人未定。又有藉，皆复有符，符用木，長二寸，以當所屬官兩子［《初學記》，御覽作字。］為鐵印，亦太卿炙符，當出入者，案籍畢，复齒符，乃引內之也，其有官位得出入者，令執御者官，傳呼前後以相通，從昏至晨，分部行夜，夜有行者，辄前曰：誰，誰，若此不解，終歲更始，所以重慎宿衛也。","sortOrder":30},
  {"id":"s_work_nvlt_49_31","chapterId":"ch_work_nvlt_49","text":"《東觀漢記》曰：光武二十三年，太尉鮑昱兼衛尉，永元二年，司徒丁鸿兼衛尉。","sortOrder":31},
  {"id":"s_work_nvlt_49_32","chapterId":"ch_work_nvlt_49","text":"《魏志》曰：辛毗為衛尉，清平，與徐邈胡质，皆忧國忘私，不營產業，賜穀二千斛，錢三十萬，布告天下。","sortOrder":32},
  {"id":"s_work_nvlt_49_33","chapterId":"ch_work_nvlt_49","text":"又曰：田豫為併［原訛升，據冯校本改。］州刺史，徵為衛尉，屢乞遜位，司馬宣王以豫克壮，書豫［《太平御覽》二百二十九作諭。］未聽，豫書答曰：年過七十，而以居位，譬由鍾鳴漏盡，夜行不休，是罪人也，遂引疾，拜太中大夫。","sortOrder":33},
  {"id":"s_work_nvlt_49_34","chapterId":"ch_work_nvlt_49","text":"沈約《宋書》曰：南郡王義宣子恢，為侍中，領衛尉，晉氏過江，不置衛尉，世祖欲重城禁，故复置衛尉，自恢始也。","sortOrder":34},
  {"id":"s_work_nvlt_49_35","chapterId":"ch_work_nvlt_49","text":"【箴】漢楊雄衛尉箴曰：茫茫上天，崇高其居，設置山险，盡為防御，重根里垓，以難不深，［《初學記》十二作律。］闕為城衛，以待暴卒，國以有固，人民有內，各保其守，永修不败。","sortOrder":35},
  {"id":"s_work_nvlt_49_36","chapterId":"ch_work_nvlt_49","text":"【碑】後漢孔融衛尉張俭碑銘曰：其先張仲，實以孝友，左右周室，晉主夏盟，而張老延君譽於四方，君禀乾綱之正性，蹈高世之殊軌，冰絜淵清，介然特立，雖史魚之励操，叔向之正色，未足比焉，中常侍同郡侯覽，专權王命，豺虎肆虐，威震天下，君以西都［全後漢文八十三作部。］督郵，上覽禍亂凶國之罪，鞠没賦奸，以巨萬計，俄而製書案验部党，君為覽所陷，亦章名捕逐，當世英雄，受命殒身，以籍濟君厄者，蓋數十人，故克免斯艱，旋宅舊宇，眾庶懷其德，王公慕其聲，州宰爭命，辟大將軍幕府，公車特就家拜少府，皆不就也，复以衛尉徵，明詔嚴切，敕州郡，乃不得已而就之，銘曰：桓桓我君，應天淑靈，皓素其质，允迪忠貞，肆志直道，進不為榮，赴戟驕臣，發如震霆，凌刚摧堅，视危如寧。","sortOrder":36},
  {"id":"s_work_nvlt_49_37","chapterId":"ch_work_nvlt_49","text":"◇太仆","sortOrder":37},
  {"id":"s_work_nvlt_49_38","chapterId":"ch_work_nvlt_49","text":"《漢書·百官表》曰：太仆掌舆馬，屬官有大廄未央廄象［漢書百官公卿表作家。］馬三令。又，車府路辂騎馬四令。又，龍馬橐泉騊駼承華五監長丞。又邊郡六牧師苑令各三丞。","sortOrder":38},
  {"id":"s_work_nvlt_49_39","chapterId":"ch_work_nvlt_49","text":"又牧橐崑蹄令丞皆屬焉，武帝太初元年，更名家馬為酮馬，駐乳，［駐乳二字冯校本作駐音乳，漢書註作主乳馬三字。］取其汁酮治之，味酢可飲，因以名官也，文類［按疑當作穎。］曰：所主總酮雜合，非上選所別異之馬也，筩晉洞，［句有訛。］晉疑當作音，主乳馬，韦革為夹兜，受數升，盛馬乳，酮取其上肥，因名酮馬，令［漢書註作今。］梁州亦名馬骆為酒馬，［漢書註作馬酒。］","sortOrder":39},
  {"id":"s_work_nvlt_49_40","chapterId":"ch_work_nvlt_49","text":"《漢舊儀》曰：太仆帥諸苑三十六所，分布北邊，以郎為苑監，官奴婢三萬人，分養馬三十萬頭，擇取給六廄牛羊無數，以給犧牲。","sortOrder":40},
  {"id":"s_work_nvlt_49_41","chapterId":"ch_work_nvlt_49","text":"《漢書》曰：灌婴自上初起沛，常為太仆，竟高祖世，以太仆事惠帝，惠帝崩，以太仆事高後，高後崩，代王之來，婴與東牟侯入清宮，以天子駕迎代王，共立文帝，後為太仆，《東觀漢記》曰：祭肜，字次孫，旅力過人，常貫三百斤弓，入為太仆，從至魯廟，［原作會明，據冯校本改。］帝指子路室曰：此太仆室也。","sortOrder":41},
  {"id":"s_work_nvlt_49_42","chapterId":"ch_work_nvlt_49","text":"《續漢書》曰：趙岐，字台卿，獻帝以為太仆，持節安慰天下。","sortOrder":42},
  {"id":"s_work_nvlt_49_43","chapterId":"ch_work_nvlt_49","text":"王隱《晉書》曰：武帝以羊琇為太仆卿，遜位，加特進。","sortOrder":43},
  {"id":"s_work_nvlt_49_44","chapterId":"ch_work_nvlt_49","text":"晉諸公贊曰：郭展為太仆，留心於養生，是以廄馬充丁，［《太平御覽》二百三十作牣。］其後征吳，得以濟事。","sortOrder":44},
  {"id":"s_work_nvlt_49_45","chapterId":"ch_work_nvlt_49","text":"帝王世記曰：穆王即位，命伯婴為太仆，今尚書君牙伯冏二篇是也。","sortOrder":45},
  {"id":"s_work_nvlt_49_46","chapterId":"ch_work_nvlt_49","text":"【箴】漢楊雄太仆箴曰：肅肅太仆，車馬是供，锵锵和鸞，駕彼時龍，昔在上帝，巡狩西宅，王用三驅，前禽是射，廄多肥馬，野有饿殕，仆臣司駕，數［○《初學記》十二作敢。］告執帛，［《初學記》作皂。］","sortOrder":46},
  {"id":"s_work_nvlt_49_47","chapterId":"ch_work_nvlt_49","text":"【诔】晉傅玄永寧太仆庞侯诔曰：蒸蒸孝敬，行著閨庭，如蘭之芳，如金之貞，在亂不回，處暗斯明，仁象春日，威配秋霜，慈恩雨施，惠化風扬，嘉善獻親，疾惡若讎，品定人倫，清濁異流，將繼四祖，世據削足，［原作定，據冯校本改。］天假其年，主優其祿，等勋伊呂，比寿東嶽。","sortOrder":47},
  {"id":"s_work_nvlt_49_48","chapterId":"ch_work_nvlt_49","text":"◇廷尉","sortOrder":48},
  {"id":"s_work_nvlt_49_49","chapterId":"ch_work_nvlt_49","text":"韦昭辯《釋名》曰：廷尉，縣尉，皆古官也，以尉尉民心也。","sortOrder":49},
  {"id":"s_work_nvlt_49_50","chapterId":"ch_work_nvlt_49","text":"《尚書》曰：帝曰皋陶，蠻夷猾夏，寇賊奸宄，汝作士。","sortOrder":50},
  {"id":"s_work_nvlt_49_51","chapterId":"ch_work_nvlt_49","text":"《文子》曰：皋陶喑而為大理，天下無虐刑，有貴乎言者也。","sortOrder":51},
  {"id":"s_work_nvlt_49_52","chapterId":"ch_work_nvlt_49","text":"《韓詩外傳》曰：晉文公使李離為大理，過聽殺人，自拘廷尉，請死於君，君曰：官有貴賤，罰有輕重，下吏有罪，非子之罪也，李離曰：法失則刑，［太平御覽二百三十一刑下有失字。］刑失則死，遂伏劍死。","sortOrder":52},
  {"id":"s_work_nvlt_49_53","chapterId":"ch_work_nvlt_49","text":"《漢書》曰：廷尉，秦官，掌刑辟，有正左右監，景帝中六年，更名大理，武帝建元四年，复廷尉。","sortOrder":53},
  {"id":"s_work_nvlt_49_54","chapterId":"ch_work_nvlt_49","text":"又曰：下邳翟公，為廷尉，賓客填門，及罢，門外可設雀羅，後复為廷尉，乃署其門曰：一死一生，乃知交情，一貴一賤，交情乃見，一貧一富，乃知交態。","sortOrder":54},
  {"id":"s_work_nvlt_49_55","chapterId":"ch_work_nvlt_49","text":"又曰：張釋之為廷尉，上行出中渭桥，有一人從桥下走，乘舆馬驚，於是使騎捕之，屬廷尉，釋之奏，此人犯跸，當罰金，上怒，釋之曰：廷尉天下之平也，一傾，天下用法皆為之輕重，民安得错其手足，上良久曰：廷尉當是也。","sortOrder":55},
  {"id":"s_work_nvlt_49_56","chapterId":"ch_work_nvlt_49","text":"又曰：於定國為廷尉，朝廷稱之曰：張釋之為廷尉，天下無冤民，於定國為廷尉，民自以不冤。","sortOrder":56},
  {"id":"s_work_nvlt_49_57","chapterId":"ch_work_nvlt_49","text":"又曰：朱博遷廷尉，恐為官屬所誣，召見正監典法掾吏，謂曰：廷尉本起於武吏，不通法律，然廷尉治斷獄以來，且二十年，亦獨目剽日久，三尺律令，人事出其中，掾吏试與正監，共撰前世决事吏議難知者數十事，特以問廷尉，得為諸君意覆之，正監即共條白博，博皆召掾吏，為平處其輕重，十中八九，官屬鹹服。","sortOrder":57},
  {"id":"s_work_nvlt_49_58","chapterId":"ch_work_nvlt_49","text":"又曰：文帝初立，河間守吳公，治天下第一，故與李斯同邑，乃徵吳公為廷尉。","sortOrder":58},
  {"id":"s_work_nvlt_49_59","chapterId":"ch_work_nvlt_49","text":"華峤《後漢書》曰：河間吳雄，以明法律，桓帝時自廷尉致位司徒，雄子訢，孫恭，三世為廷尉，以法為名家。","sortOrder":59},
  {"id":"s_work_nvlt_49_60","chapterId":"ch_work_nvlt_49","text":"又曰：郭躬為廷尉正，遷廷尉，家世掌法，凡郭氏為廷尉者七人。","sortOrder":60},
  {"id":"s_work_nvlt_49_61","chapterId":"ch_work_nvlt_49","text":"《新序》曰：楚昭王有士曰石奢，公正而好義，［原缺，據冯校本補。］王使為理，於是廷尉，有殺人者，石奢追之，則其父也，及於廷尉曰：以父成政，不孝也，不行君法，不忠也，弛罪法而伏其辜，仆之所守也，君曰：庸有罪乎，子其治事矣，石奢曰：不私其父，非孝也，不行君法，非忠也，匡不敢失法，下之行也，遂不離斧质，刎頸而死。","sortOrder":61},
  {"id":"s_work_nvlt_49_62","chapterId":"ch_work_nvlt_49","text":"《東觀漢記》曰：永平六年，以廷尉皆曹吏強為廷尉，以明用達法理，超遷非次。","sortOrder":62},
  {"id":"s_work_nvlt_49_63","chapterId":"ch_work_nvlt_49","text":"又曰：陳寵為廷尉，有疑獄，辄手筆作議，所活者甚多。","sortOrder":63},
  {"id":"s_work_nvlt_49_64","chapterId":"ch_work_nvlt_49","text":"《魏志》曰：高文惠，明帝時為廷尉，時法甚峻，而宜陽典農劉龟，竊於禁內射兔，收龟付獄，文惠表請告者，曰：廷尉天下平也，安得以至尊喜怒而毀法乎。","sortOrder":64},
  {"id":"s_work_nvlt_49_65","chapterId":"ch_work_nvlt_49","text":"《會稽典錄》曰：盛吉拜廷尉，吉性多仁恩，務在哀矜，每至冬月，罪囚當斷，其妻執燭，吉［原訛百，據冯校本改。］手丹筆，夫妻相向垂泣。","sortOrder":65},
  {"id":"s_work_nvlt_49_66","chapterId":"ch_work_nvlt_49","text":"挚虞新禮議曰：故事，祀皋陶於廷尉寺，新禮移祀於律寺，以同祭先聖於太學也。又故事，祀以社日，新禮改以孟秋之月，以應秋政，臣虞謹案，皋陶作士，惟明克允，國重其功，人思其當，是以獄官祀其神，系者致其祭，律非正署，废興無常，宜如舊禮。","sortOrder":66},
  {"id":"s_work_nvlt_49_67","chapterId":"ch_work_nvlt_49","text":"《晉中興書》曰：王彪之遷廷尉，時扬州刺史殷浩，劾永嘉太守謝毅，付廷尉，彪之執法不受，發詔，彪之又上疏執據，時人雲，張釋之以來，复見斯事。","sortOrder":67},
  {"id":"s_work_nvlt_49_68","chapterId":"ch_work_nvlt_49","text":"【箴】漢楊雄廷尉箴曰：天降五刑，惟夏之績，亂茲平民，不困不僻，昔在蚩尤，爰作淫刑，延於苗民，夏氏不寧，穆王耄荒，［原訛老巟，據冯校本改。］甫侯伊謀，周輕其製，秦繁其辜，故有國者，無雲可謂，是刖是劓，無雲何害，是剝是剖，殷以刑顛，秦以酷败，獄臣司理，敢告執謁。","sortOrder":68},
  {"id":"s_work_nvlt_49_69","chapterId":"ch_work_nvlt_49","text":"◇鸿臚","sortOrder":69},
  {"id":"s_work_nvlt_49_70","chapterId":"ch_work_nvlt_49","text":"韦昭辯《釋名》曰：腹前肥者曰臚，此主王侯及蕃國，言以京師為心體，王侯外國為腹臚，以養之也，辯雲，鸿臚本故典客，掌禮，鸿，大也，臚，陳序也，欲大以禮陳序賓客。","sortOrder":70},
  {"id":"s_work_nvlt_49_71","chapterId":"ch_work_nvlt_49","text":"《漢書》曰：典客，秦官，掌諸侯歸義蠻夷，景帝六年，更名大行，今武帝太初元年，更名大鸿臚。","sortOrder":71},
  {"id":"s_work_nvlt_49_72","chapterId":"ch_work_nvlt_49","text":"漢雜事曰：萧由為陳留太守，入為鸿臚卿，不任賓贊，乃還官。","sortOrder":72},
  {"id":"s_work_nvlt_49_73","chapterId":"ch_work_nvlt_49","text":"《東觀漢記》曰：大鸿臚，漢舊官，建武元年复置，屬官有治禮員三十七人，主齊亻寶贊。又有中都官，升［《東觀漢記》作斗。］食以下，功次相補。","sortOrder":73},
  {"id":"s_work_nvlt_49_74","chapterId":"ch_work_nvlt_49","text":"《續漢書》曰：大鸿臚卿一人，中二千石，諸王入朝，當郊迎，典其禮儀，及郡國上計併屬焉，皇子拜王贊授，及拜諸侯諸侯嗣子四方夷狄封者，鸿臚召拜之。","sortOrder":74},
  {"id":"s_work_nvlt_49_75","chapterId":"ch_work_nvlt_49","text":"《魏略》曰：常林性既清白，當入官又嚴，少府寺與鸿臚對門，時崔林為鸿臚，性闊達，不與林同，數數聞林楇人吏聲，不以為可，林當夜楇吏，吏不勝其痛，嚾呼嗷嗷，其明，崔出門，與林語曰：聞卿為廷尉爾耶，林不覺，答曰：不也，崔曰：卿不為廷尉，昨夜何故考囚乎，林慚笑。","sortOrder":75},
  {"id":"s_work_nvlt_49_76","chapterId":"ch_work_nvlt_49","text":"又曰：韓宣，明帝時為大鸿臚，如［《太平御覽》二百三十二作始。］南陽韓暨，以宿德，在宣前為大鸿臚，鸿臚中為之語曰：大鸿臚，小鸿臚，前後治行相曷如。","sortOrder":76},
  {"id":"s_work_nvlt_49_77","chapterId":"ch_work_nvlt_49","text":"襄陽耆舊傳曰：習鬱為侍中時，從光武幸黎丘，與帝通夢見蘇山神，光武嘉之，拜大鸿臚，錄其前後功，封襄陽侯，使立蘇嶺祠，刻二石鹿，俠神道，百姓謂之鹿門廟，或呼蘇嶺山為鹿門山。","sortOrder":77},
  {"id":"s_work_nvlt_49_78","chapterId":"ch_work_nvlt_49","text":"山涛啟事曰：鸿臚職主胡事，前後給之，率多不善，［原訛差，據冯校本改。］今當選御史丞，力收舊人，不審於宜爾不。","sortOrder":78},
  {"id":"s_work_nvlt_49_79","chapterId":"ch_work_nvlt_49","text":"【箴】漢楊雄大鸿臚箴曰：荡荡唐虞，經通垓極，畫為上下，該羅百職，文不可武，武不可文，大小上下，不可奪倫，鸿臣司爵，敢告在鄰。","sortOrder":79},
  {"id":"s_work_nvlt_49_80","chapterId":"ch_work_nvlt_49","text":"漢邯鄲淳鸿臚鍾紀碑銘曰：內苞九德，外兼百行，川深淪於不测，胆智應於無方，弘裕足以容眾，矜嚴足以正世，然後研機道藝，涉覽文學，凡前言往行，竹帛所載，靡不悉該，於穆上德，時惟我君，固天縱之，允鍾厥純，命世作則，實紹斯文，遭险龍潛，抗志浮雲，所貴在己，樂存事親，雖處畎畝，天子屢聞。","sortOrder":80},
  {"id":"s_work_nvlt_49_81","chapterId":"ch_work_nvlt_49","text":"◇司農","sortOrder":81},
  {"id":"s_work_nvlt_49_82","chapterId":"ch_work_nvlt_49","text":"《漢書》曰：治粟內史，秦官，武帝太初元年，更名大司農。","sortOrder":82},
  {"id":"s_work_nvlt_49_83","chapterId":"ch_work_nvlt_49","text":"應劭《漢官》曰：大司農，古官也，□［《太平御覽》二百三十二作唐。］虞分命羲和四子，敬授民時，高祖受命，徵秦之弊，與民休息，逮到文景，國家無事，家給人足，京師之錢，累百巨萬，貫朽而不校，太仓之粟，陳陳相因，充溢露積，腐败而不食。","sortOrder":83},
  {"id":"s_work_nvlt_49_84","chapterId":"ch_work_nvlt_49","text":"《史記》曰：韓信歸漢，漢以為治粟內史。","sortOrder":84},
  {"id":"s_work_nvlt_49_85","chapterId":"ch_work_nvlt_49","text":"《漢書》曰：武帝天漢元年，以桑弘羊為大司農，置丞數十，部於郡國。","sortOrder":85},
  {"id":"s_work_nvlt_49_86","chapterId":"ch_work_nvlt_49","text":"又曰：宣帝地節四年，北海太守朱邑，以治行第一，入為大司農。","sortOrder":86},
  {"id":"s_work_nvlt_49_87","chapterId":"ch_work_nvlt_49","text":"《東觀漢記》曰：辛融，字子優，為大司農，性明達，［原訛進，據冯校本改。］稱為名卿。","sortOrder":87},
  {"id":"s_work_nvlt_49_88","chapterId":"ch_work_nvlt_49","text":"又曰：高詡以儒學徵，拜大司農，在朝以清白方正稱。","sortOrder":88},
  {"id":"s_work_nvlt_49_89","chapterId":"ch_work_nvlt_49","text":"《魏志》曰：梁習為併州，二十餘年，政治為天下最，乃徵拜為大司農。","sortOrder":89},
  {"id":"s_work_nvlt_49_90","chapterId":"ch_work_nvlt_49","text":"沈約《宋書》曰：大司農卿一人，稱［《太平御覽》二百三十二稱上有書字。］弃後稷，其職也。","sortOrder":90},
  {"id":"s_work_nvlt_49_91","chapterId":"ch_work_nvlt_49","text":"齊職儀曰：司農卿，耕籍則掌其禮儀。","sortOrder":91},
  {"id":"s_work_nvlt_49_92","chapterId":"ch_work_nvlt_49","text":"【箴】漢楊雄大司農箴曰：厥庶僚後，實均實羸，［《初學記》十二作嬴。］有無相易，性［《初學記》作惟。］都作程，旁求衣食，厥民攸生，上稽二帝，下开三王，什一而征，為民作常，蓋近貢篚，百姓不忘，帝王之盛，盛在農殖，季周烂熳，而東作不敕，膏腴不獲，庶物併荒，府藏单虛，靡積靡仓。","sortOrder":92},
  {"id":"s_work_nvlt_49_93","chapterId":"ch_work_nvlt_49","text":"晉張華大司農箴曰：在周之室，不虔政首，弃稷弗修，不籍千畝，匮神乏祀，用败於戎丑，啬臣司農，敢告左右。","sortOrder":93},
  {"id":"s_work_nvlt_49_94","chapterId":"ch_work_nvlt_49","text":"【墓志】隋江總司農陳暄墓志銘曰：其文〈骨夭〉骪，其筆縱橫，背碑即誦，據馬俄成，誹諧見賞，調笑忘情，兩宮寵官，四主恩榮，萬事休息，一朝追送，畴昔命觴，文可吟諷，今日酹酒，長悲且恸。","sortOrder":94},
  {"id":"s_work_nvlt_49_95","chapterId":"ch_work_nvlt_49","text":"【诔】後漢張衡大司農鮑德诔曰：昔君烈祖，平顯弈世，敬叔生牙，美管交賴，至於中葉，种德以邁，种德伊何，去虛適參，建旄屯留，其茂如林，降及我君，總角有聲，遺蒙萬穀，寵祿斯丁，守約勤學，克勞其形，濬哲之資，日就月成，業業學徒，童蒙求我，舍厥往著，去風即雅，濟濟京河，寔為西魯，昔我南都，惟帝舊乡，同於郡國，殊於表章，命親如公，弁冕鳴橫，若惟允之，寔耀其光，导以仁惠，教以義方，習射矍相，饗老虞庠，羌髡作虐，艱我西鄰，君斯整旅，耀武月頻，蠢蠢戎虜，是慴是震，知德者鮮，惟君克舉，既厭帝心，將處台辅，命有不永，時不我與，天寔為之，孰其能御，股肱或毀，何痛如之，國丧遺愛，如何無思。","sortOrder":95},
  {"id":"s_work_nvlt_49_96","chapterId":"ch_work_nvlt_49","text":"◇將作","sortOrder":96},
  {"id":"s_work_nvlt_49_97","chapterId":"ch_work_nvlt_49","text":"《漢書》曰：將作，秦官，掌治宮室。","sortOrder":97},
  {"id":"s_work_nvlt_49_98","chapterId":"ch_work_nvlt_49","text":"應劭《漢官》曰：世祖中興，以謁者領其官，章帝建初元年，乃置真，位次河南尹，永元七年，大匠應慎上言，百郡付［《太平御覽》二百三十六作計。］史，觀國之光，而舍逆旅，崎嶇斯馆，貢篚之物，朽濕曝露，昔晉國霸之盟主耳，舍諸侯於隸人，鄭子產以為大譏，况今四海之大，而可無乎，和帝嘉納之，即創業焉。","sortOrder":98},
  {"id":"s_work_nvlt_49_99","chapterId":"ch_work_nvlt_49","text":"《漢書》曰：將作大匠乘馬延年，勤苦，賜秩二千石。","sortOrder":99},
  {"id":"s_work_nvlt_49_100","chapterId":"ch_work_nvlt_49","text":"《漢舊儀》曰：將作大匠，改作少府，景帝中六年更名也。","sortOrder":100},
  {"id":"s_work_nvlt_49_101","chapterId":"ch_work_nvlt_49","text":"《續漢書》曰：將作大匠，掌木功之工，併树桐梓之類，列於道侧。","sortOrder":101},
  {"id":"s_work_nvlt_49_102","chapterId":"ch_work_nvlt_49","text":"華峤《漢書》曰：劉寵拜會稽太守，除省煩苛，徵為將作大匠，有老叟五六人，人赍一百錢送寵，寵為一人受一文大錢，《魏志》曰：陽［《太平御覽》二百三十六作楊。］阜為大匠卿，治發充後庭，阜上疏，欲省宮人諸人不見幸者，乃召御府史，問後宮人數，吏守舊令，對曰：禁密，不約［御覽作得。］宣露，阜怒，杖吏一百，數之曰：國家不以九卿為密，反與小吏為密乎，帝聞而愈敬憚。","sortOrder":102},
  {"id":"s_work_nvlt_49_103","chapterId":"ch_work_nvlt_49","text":"《汝南先賢傳》曰：應仲［原訛仰，據冯校本改。］華為將作大匠，發擿奸伏，除藻飾，割浮費，凡所省息七亿餘萬。","sortOrder":103},
  {"id":"s_work_nvlt_49_104","chapterId":"ch_work_nvlt_49","text":"【箴】漢楊雄將作大匠箴曰：侃侃將作，經構宮室，牆以御風，宇以蔽日，寒暑攸除，鳥鼠攸去，王有宮殿，民有宅居，昔在帝世，茅茨土階，夏卑宮觀，在彼溝池，桀作瑤台，紂為璇室，人力不堪，而帝業不卒，詩詠宣王，由俭改奢，春秋譏刺，書彼泉台，兩觀雉門，而魯以不恢，或作長府，而闵子以仁。","sortOrder":104},
  {"id":"s_work_nvlt_49_105","chapterId":"ch_work_nvlt_49","text":"◇光祿大夫","sortOrder":105},
  {"id":"s_work_nvlt_49_106","chapterId":"ch_work_nvlt_49","text":"漢書百官表曰：光祿勋屬官有大夫，掌論議。","sortOrder":106},
  {"id":"s_work_nvlt_49_107","chapterId":"ch_work_nvlt_49","text":"漢官解詁曰：武帝以中大夫為光祿大夫，與博士俱［原訛慎，據冯校本改。］以儒雅之選，異官通職，周官所謂聯者也，溫故知新，率由舊章，皆能分明古今，辯舊聞者也。","sortOrder":107},
  {"id":"s_work_nvlt_49_108","chapterId":"ch_work_nvlt_49","text":"《漢官儀》曰：光祿大夫，秩比二千石，不言屬光祿，光祿勋門外特施行馬，以旌別之。","sortOrder":108},
  {"id":"s_work_nvlt_49_109","chapterId":"ch_work_nvlt_49","text":"百官表註曰：光祿大夫，古官也，銀章青綬，詩雲，三事大夫，莫不夙夜，職掌言議，毗亮論道，獻可替不，贊扬德化，《漢書》曰：杜陵王仲翁，出入蒼頭庐兒，傳呼甚寵。","sortOrder":109},
  {"id":"s_work_nvlt_49_110","chapterId":"ch_work_nvlt_49","text":"又曰：元帝以少傅周堪為光祿大夫，秩中二千石，領尚書事。","sortOrder":110},
  {"id":"s_work_nvlt_49_111","chapterId":"ch_work_nvlt_49","text":"又曰：穀永既為大將軍鳳說，能實最高，由是擢為光祿大夫。","sortOrder":111},
  {"id":"s_work_nvlt_49_112","chapterId":"ch_work_nvlt_49","text":"《東觀漢記》曰：張湛為光祿大夫，數陳政，常乘白馬，光武每有異政，辄曰：白馬生且复諫矣。","sortOrder":112},
  {"id":"s_work_nvlt_49_113","chapterId":"ch_work_nvlt_49","text":"《魏志》曰：黃初四年，光祿大夫楊彪，詔給吏卒，門施行馬。","sortOrder":113},
  {"id":"s_work_nvlt_49_114","chapterId":"ch_work_nvlt_49","text":"樊英別傳曰：詔書告南陽太守曰：五官中郎將樊英，委榮辭祿，不降其節，今以英為光祿大夫，賜歸家，所在縣穀千斛，常以八月，致牛一頭，酒三斛。","sortOrder":114},
  {"id":"s_work_nvlt_49_115","chapterId":"ch_work_nvlt_49","text":"【表】梁丘遲為柳仆射讓光祿表曰：竊聞敬孫以規獻為職，彝品常貴，飛翠鳴玉，升降禁門，臣以痁疾，豈伊或忝，匪稱其服，終朝三褫，近取諸身，皎日非喻，臣之庸薄，文尘物論，假以克壮，報效無階，而婴離沉痼，日月滋甚，聖朝留簪履之舊愍，降帷蓋之餘矜，榮不徒行，事存寵渥。","sortOrder":115},
  {"id":"s_work_nvlt_49_116","chapterId":"ch_work_nvlt_49","text":"【詩】魏陳王曹植光祿大夫荀侯诔曰：如冰之清，如玉之絜，法而不威，和而不亵，百寮士庶，歔欷霑纓，機女投杼，農夫輟耕，輪給辄而不轉，馬悲鳴而倚衡。","sortOrder":116},
  {"id":"s_work_nvlt_49_117","chapterId":"ch_work_nvlt_49","text":"◇太子詹事","sortOrder":117},
  {"id":"s_work_nvlt_49_118","chapterId":"ch_work_nvlt_49","text":"漢書百官表曰：太子詹事，掌皇後太子家，丞屬諸官皆屬焉，成帝鸿嘉三年，省詹事，屬大長秋。","sortOrder":118},
  {"id":"s_work_nvlt_49_119","chapterId":"ch_work_nvlt_49","text":"應劭《漢官》曰：詹事，秦官，詹，省也，給也，秩二千石。","sortOrder":119},
  {"id":"s_work_nvlt_49_120","chapterId":"ch_work_nvlt_49","text":"《漢書》曰：窦婴乃太後兄子，景帝即位，為詹事，帝母弟梁孝王，太後愛之，孝王朝，因燕酒酣，上曰：千秋萬歲後，傳位於王，婴引卮進上曰：天下高祖之天下，父子相傳，漢之約也，上何得傳王，太後因憎婴，婴亦薄其官，因病免也。","sortOrder":120},
  {"id":"s_work_nvlt_49_121","chapterId":"ch_work_nvlt_49","text":"又曰：孔光父霸，宣帝時，以經授太子，為詹事。","sortOrder":121},
  {"id":"s_work_nvlt_49_122","chapterId":"ch_work_nvlt_49","text":"又曰：孝哀元寿元年，馬宮為詹事。","sortOrder":122},
  {"id":"s_work_nvlt_49_123","chapterId":"ch_work_nvlt_49","text":"又曰：漢文以鄭當時為景帝詹事。","sortOrder":123},
  {"id":"s_work_nvlt_49_124","chapterId":"ch_work_nvlt_49","text":"又曰：昭帝元鳳中，以韦賢為詹事。","sortOrder":124},
  {"id":"s_work_nvlt_49_125","chapterId":"ch_work_nvlt_49","text":"王珉答徐邈書曰：詹事彈肅一宮，如尚書令中丞矣。","sortOrder":125},
  {"id":"s_work_nvlt_49_126","chapterId":"ch_work_nvlt_49","text":"晉公卿禮秩曰：太始中，立詹事，掌宮事。","sortOrder":126},
  {"id":"s_work_nvlt_49_127","chapterId":"ch_work_nvlt_49","text":"齊職儀曰：詹事，品第三，茂陵書，秩二千石，銀章紫綬，局擬尚書令，位视領護將軍。","sortOrder":127},
  {"id":"s_work_nvlt_49_128","chapterId":"ch_work_nvlt_49","text":"沈約《宋書》曰：詹事一人，初領官屬，成帝時，悉屬少府，魏氏更置詹事，總眾職，晉初又屬二傅，鹹寧复置詹事。","sortOrder":128},
  {"id":"s_work_nvlt_49_129","chapterId":"ch_work_nvlt_49","text":"《俗說》曰：江夷［《太平御覽》二百四十五夷下有為字。］右仆射，主上欲用其領詹事，語王准，［御覽作淮，下同。］卿可觅比例，准對曰：臣當出外尋訪，准後見主上，問近所道事，卿已得例未，准曰：謝琰右仆射領詹事，琰即謝［原訛謂，據冯校本改。］公之子，恐夷非其例，事遂不行。","sortOrder":129},
  {"id":"s_work_nvlt_49_130","chapterId":"ch_work_nvlt_49","text":"【表】齊孔稚珪讓詹事表曰：皇［原脱，據冯校本補。］太子霞騫青殿，日光春官，駕紫穀之英，振洛笙之响，自非器上白雲，韻同明月，何以延芳芝苑，插羽琼條，窦婴戚貴於西京，陆晔風素於東國，伊人之美，方曰可舉，臣亦何斯，而敢參冒也。","sortOrder":130},
  {"id":"s_work_nvlt_49_131","chapterId":"ch_work_nvlt_49","text":"梁陆倕除詹事免讓表曰：中陽白水，徒庇微軀，送珥抱薪，未聞成績，陳席不弃，故劍無遺，遂宣時髦，升降清顯，尊官厚秩，無因而至，陋巷荜門，鬱成爽垲，储端華重，實異恒司，南章馬宮，已擇儒雅，窦婴許商，爰取姻戚，自茲已降，名器日隆，歷選才賢，若何叨越也。","sortOrder":131},
  {"id":"s_work_nvlt_49_132","chapterId":"ch_work_nvlt_49","text":"隋江總謝宮為製讓詹事表曰：如攀珠树，徒仰照車之辉，若踐玉田，不知照庑之价，芙蓉之水，亟奉北園，迷迭之文，屬陪南馆，久降噓枯之旨，許賜凌雲之筆，清夜宴斯，謂言善戲，黃金然诺，併遂殊寵，年齊柏寢，豈報恩榮，紙罄蘭台，未書悚戴。","sortOrder":132},
  {"id":"s_work_nvlt_49_133","chapterId":"ch_work_nvlt_49","text":"【啟】隋江總除詹事謝宮啟曰：庇身脩德，濫跡端形，陳萝故葛，攀附不涯，解角蜕鱗，超逾非次，方辭玺會，觊收渥泽。","sortOrder":133},
  {"id":"s_work_nvlt_49_134","chapterId":"ch_work_nvlt_49","text":"◇太子中庶子","sortOrder":134},
  {"id":"s_work_nvlt_49_135","chapterId":"ch_work_nvlt_49","text":"漢書百官表曰：太子中庶子，如侍中。","sortOrder":135},
  {"id":"s_work_nvlt_49_136","chapterId":"ch_work_nvlt_49","text":"又曰：太子太傅屬官，有庶子。","sortOrder":136},
  {"id":"s_work_nvlt_49_137","chapterId":"ch_work_nvlt_49","text":"又曰：王商，涿郡人，少為太子中庶子，以肅敬厚稱。","sortOrder":137},
  {"id":"s_work_nvlt_49_138","chapterId":"ch_work_nvlt_49","text":"環濟要略曰：庶子，謂官中諸吏之適子及支庶在版籍者也，行其秩叙，作其徒役，授八次八舍之職，以徼候。","sortOrder":138},
  {"id":"s_work_nvlt_49_139","chapterId":"ch_work_nvlt_49","text":"《漢書》曰：欧陽地餘為中庶子，授皇太子經，元帝即位，遷侍中。","sortOrder":139},
  {"id":"s_work_nvlt_49_140","chapterId":"ch_work_nvlt_49","text":"《魏志》曰：鮑勋為中庶子。","sortOrder":140},
  {"id":"s_work_nvlt_49_141","chapterId":"ch_work_nvlt_49","text":"又曰：王昶，字文舒，為中庶子。","sortOrder":141},
  {"id":"s_work_nvlt_49_142","chapterId":"ch_work_nvlt_49","text":"文章叙曰：應貞，晉室為中庶子。","sortOrder":142},
  {"id":"s_work_nvlt_49_143","chapterId":"ch_work_nvlt_49","text":"晉齊王攸與山涛書曰：中庶子東宮顯職，加侍接右，［《太平御覽》二百四十五右上有左字。］誠宜得篤粹有行檢六［御覽作之］人，想悉在尊意，必允眾望也。","sortOrder":143},
  {"id":"s_work_nvlt_49_144","chapterId":"ch_work_nvlt_49","text":"《晉中興書》曰：溫峤拜中庶子，在東宮，甚見嘉寵，僚屬莫與為比，數規諫諷議。又獻侍臣箴，甚有補益，太子時起西池樓觀，頗多勞費，峤口疏切諫，太子納焉。","sortOrder":144},
  {"id":"s_work_nvlt_49_145","chapterId":"ch_work_nvlt_49","text":"沈約《宋書》曰：中庶子，漢置，古者世祿，卿大夫之子，既為副倅，謂之國子，天子諸侯子，必有庶子官，以掌教之。","sortOrder":145},
  {"id":"s_work_nvlt_49_146","chapterId":"ch_work_nvlt_49","text":"【墓志】梁簡文帝庶子王規墓志銘曰：玉挺藍田，珠润隋水，价重連城，聲同垂棘，偶應龍之籥影，等威鳳之羽儀，名理超於荀王，博洽［原作治，據冯校本改。］侔於終贾，稍遷侍中，佩玉玺於文昌，珥金貂於武帳，文雅與綺縠相宣，逸氣併雲霞俱遠，副君取敬杜夷，時回晉储之駕，追嗟徐幹，亦降魏兩之書，爰發睿辭，為銘雲爾，七略百家，三藏九部，成誦其心，談天其口，勝氣無儔，高尘誰偶，榮珪掩采，靈劍摧鋒，宋郊淪鼎，洛水沉鍾，玄扉不晝，幽夜恒冬。","sortOrder":146},
  {"id":"s_work_nvlt_49_147","chapterId":"ch_work_nvlt_49","text":"◇太子舍人","sortOrder":147},
  {"id":"s_work_nvlt_49_148","chapterId":"ch_work_nvlt_49","text":"《漢書》曰：文帝使晁错詣伏生，受尚書，還拜太子舍人。","sortOrder":148},
  {"id":"s_work_nvlt_49_149","chapterId":"ch_work_nvlt_49","text":"漢雜事曰：鄭當時，景帝時為太子舍人，每五日沐洗，常置驿馬長安，請諸賓客，夜以繼日，常恐不遍。","sortOrder":149},
  {"id":"s_work_nvlt_49_150","chapterId":"ch_work_nvlt_49","text":"《魏略》曰：張茂上便宜，擢為太子舍人。","sortOrder":150},
  {"id":"s_work_nvlt_49_151","chapterId":"ch_work_nvlt_49","text":"山涛啟事曰：臣近舉汜源為太子舍人，源見稱有德素，久沉滯，舉為大臣，欲以尉後聞之士。","sortOrder":151},
  {"id":"s_work_nvlt_49_152","chapterId":"ch_work_nvlt_49","text":"晉諸公贊曰：張華博識多聞，無物不知，盧浮高朗經傳，有美於華，起家為太子舍人。","sortOrder":152},
  {"id":"s_work_nvlt_49_153","chapterId":"ch_work_nvlt_49","text":"【墓志】梁簡文帝太子舍人萧特墓志銘曰：威鳳五色，朝陽千仞，孫枝發响，將雏流韻，馥哉若蘭，頌矣懷態，瑾既誕子，恒乃懽胤，銀鉤之巧，重世遹雋，况此臨池，蝉輕露润，丹旐輕飛，哀歌徐引，垅水春帷，山雲晚陣。","sortOrder":153},
  {"id":"s_work_nvlt_49_154","chapterId":"ch_work_nvlt_49","text":"《藝文類聚》　唐·欧陽詢","sortOrder":154},
  {"id":"s_work_nvlt_50_1","chapterId":"ch_work_nvlt_50","text":"卷五十職官部六據明本補","sortOrder":1},
  {"id":"s_work_nvlt_50_2","chapterId":"ch_work_nvlt_50","text":"○刺史尹太守令長","sortOrder":2},
  {"id":"s_work_nvlt_50_3","chapterId":"ch_work_nvlt_50","text":"◇刺史","sortOrder":3},
  {"id":"s_work_nvlt_50_4","chapterId":"ch_work_nvlt_50","text":"《漢書》曰：武帝時，田叔以壮勇刺舉三河，奏事稱意。","sortOrder":4},
  {"id":"s_work_nvlt_50_5","chapterId":"ch_work_nvlt_50","text":"又雲，王遵遷益州刺史，先是琅邪王陽為益州刺史，行部至九折坂，叹曰：奉先人遺體，奈何數乘此险，後以病去，及遵為刺史，至其坂，問吏曰：此王陽所畏道邪，吏對曰：是，遵叱其馭曰：驅之，王陽為孝子，王遵為忠臣。","sortOrder":5},
  {"id":"s_work_nvlt_50_6","chapterId":"ch_work_nvlt_50","text":"又曰：朱博遷冀州刺史，博本武吏，不更文法，及為刺史，行部，吏民數百人，遮道自言，博駐車决遣，五六百人皆罢去，如神，吏驚，不意博臨事乃至於此。","sortOrder":6},
  {"id":"s_work_nvlt_50_7","chapterId":"ch_work_nvlt_50","text":"又曰：何武為扬州刺史，行部，必先即學宮，見諸生，试其誦論得失，然後入傳舍，問墾田頃畝，五穀美惡。","sortOrder":7},
  {"id":"s_work_nvlt_50_8","chapterId":"ch_work_nvlt_50","text":"司馬彪《續漢書》曰：郭伋拜併州刺史，行部至西河美稷，百小兒各騎竹馬，迎伋拜，伋問曰：兒何自遠來，對曰：聞使君到喜，故來迎，伋曰：苦諸兒，复送到郭外，問使君何日當還，伋謂從事，計日告之，行部還，入美稷先期一日，伋念負諸兒，即止野，須期乃往。","sortOrder":8},
  {"id":"s_work_nvlt_50_9","chapterId":"ch_work_nvlt_50","text":"又曰：周舉為併州刺史，太原舊俗，以介子推焚骸，有龍忌之禁，辄一月寒食，莫敢煙爨，老小不堪，歲歲多死者，舉既到州，乃作弔書，以置子推之廟，言盛冬去火，殘損人命，非賢者之意，以宣示愚民，使還溫食。","sortOrder":9},
  {"id":"s_work_nvlt_50_10","chapterId":"ch_work_nvlt_50","text":"又曰：皇甫嵩領冀州牧，奏請一年租赈飢民，民歌之曰：天下亂兮市為墟，母不保子兮妻失夫，賴得皇甫兮复安居。","sortOrder":10},
  {"id":"s_work_nvlt_50_11","chapterId":"ch_work_nvlt_50","text":"又曰：种暠為益州刺史，在職三年，宣恩遠夷，开晓殊俗，岷山雜落，皆懷服漢德，其白狼槃木諸國併貢，前刺史卒後遂絕，暠至，乃复向化，永昌太守鑄黃金為文蛇，以獻梁冀，暠糾發追捕，馳傳上言，冀由是衔怒。","sortOrder":11},
  {"id":"s_work_nvlt_50_12","chapterId":"ch_work_nvlt_50","text":"《東觀漢記》曰：李珣為兖州刺史，所种小麥胡蒜，悉付從事，一［原脱，據冯校本補。］無所留，清約率下，席羊皮布被。","sortOrder":12},
  {"id":"s_work_nvlt_50_13","chapterId":"ch_work_nvlt_50","text":"又曰：段穎起於徒中，為併州刺史，有功，後徵還京師，穎乘輕車，介士鼓吹，曲蓋朱旗騎馬，殷天蔽日，連騎相繼數十里。","sortOrder":13},
  {"id":"s_work_nvlt_50_14","chapterId":"ch_work_nvlt_50","text":"謝承《後漢書》曰：王閎遷冀州刺史，閎性刻，不發私書，不交豪族賓客，號曰王獨坐。","sortOrder":14},
  {"id":"s_work_nvlt_50_15","chapterId":"ch_work_nvlt_50","text":"又曰：李寿為青州刺史，發玺書於本縣傳舍，乘法駕，騑驂朱軒就路，奏免四郡相，百城怖懼，悉豫弃官。","sortOrder":15},
  {"id":"s_work_nvlt_50_16","chapterId":"ch_work_nvlt_50","text":"先時交趾屯兵，及有司舉贾琮為刺史，即移書告示，使其安資業，百姓歌之曰：贾父來晚，使我先反，今見清平，吏不敢飯，乃以琮為冀州刺史，舊典，驂駕乘亦帷裳，迎於州界，及琮之部，升車，言刺史當遠视廣聽，糾察美惡，何有反垂帷裳，以自掩塞乎，乃命御者褰之，百城聞風，自然悚震。","sortOrder":16},
  {"id":"s_work_nvlt_50_17","chapterId":"ch_work_nvlt_50","text":"又曰：百里嵩為徐州刺史，州境遭旱，嵩行部，傳車所經，甘雨辄註，東海金乡祝其兩縣，僻在山間，嵩傳驷不往，二縣獨不雨，老父幹請，嵩曲路到二縣，入界即雨。","sortOrder":17},
  {"id":"s_work_nvlt_50_18","chapterId":"ch_work_nvlt_50","text":"又曰：巴祗為扬州刺史，帻毀坏，不复改易，以水渗曝用之，處暝暗之中，不燃官燭。","sortOrder":18},
  {"id":"s_work_nvlt_50_19","chapterId":"ch_work_nvlt_50","text":"《華陽國志》曰：趙琰為青州刺史，有貴要屬讬，琰於廳事前置大器水，發書，悉投置水中，無有所報。","sortOrder":19},
  {"id":"s_work_nvlt_50_20","chapterId":"ch_work_nvlt_50","text":"又曰：郭贺為荆州刺史，百姓歌之曰：厥德仁明郭乔卿，明帝到南陽巡狩，賜三公服，去襜露冕，使百姓見之，以彰有德。","sortOrder":20},
  {"id":"s_work_nvlt_50_21","chapterId":"ch_work_nvlt_50","text":"《三辅决錄》曰：蘇章為冀州刺史，行部，有故人為清河太守，案得其好货，乃請太守設酒，接以溫顏，太守喜曰：人各有一天，我獨有二天，章曰：今夕蘇孺文與故人歡飲，私恩也，明日冀州刺史白奏事，公法也，遂舉正其罪。","sortOrder":21},
  {"id":"s_work_nvlt_50_22","chapterId":"ch_work_nvlt_50","text":"又曰：韦康代父為涼州刺史，父出上傳，康入官，時人榮之。","sortOrder":22},
  {"id":"s_work_nvlt_50_23","chapterId":"ch_work_nvlt_50","text":"《魏志》雲：劉馥為扬州刺史，馥既受命，单馬造合肥空城，建立州治，貢獻相繼，數年恩化大行。","sortOrder":23},
  {"id":"s_work_nvlt_50_24","chapterId":"ch_work_nvlt_50","text":"《晉陽秋》曰：胡质為荆州刺史，子威，自洛陽至荆州定省，家貧，自驅驢单行，見父，停十餘日，臨歸，质賜絹一匹為道糧，威跪曰：大人清高，不審安得此，质曰：吾俸祿之餘，故以為卿糧爾，晉武帝問威曰：卿孰與卿父清，威曰：臣不如也，帝曰：何以為不如，威曰：臣父清，畏人知之，臣清，畏人不知之。","sortOrder":24},
  {"id":"s_work_nvlt_50_25","chapterId":"ch_work_nvlt_50","text":"《魏志》曰：徐邈為涼州刺史，進善黜惡，風化大行，百姓歸心焉，西域流通，荒戎入貢，皆邈勋也。","sortOrder":25},
  {"id":"s_work_nvlt_50_26","chapterId":"ch_work_nvlt_50","text":"又曰：田豫護匈奴中郎將，領併州刺史，胡聞其威名，相率來獻，州界寧肅，百姓懷之。","sortOrder":26},
  {"id":"s_work_nvlt_50_27","chapterId":"ch_work_nvlt_50","text":"又曰：陳泰為併州刺史，懷柔民夷，去有威惠，京邑貴人，多寄寶货，因泰市奴婢，泰皆掛之於壁，不發其封，及徵為尚書，悉付還之。","sortOrder":27},
  {"id":"s_work_nvlt_50_28","chapterId":"ch_work_nvlt_50","text":"又曰：張既為雍州刺史，太祖謂既曰：還君本州，可謂衣繡晝行矣。","sortOrder":28},
  {"id":"s_work_nvlt_50_29","chapterId":"ch_work_nvlt_50","text":"又曰：贾逵為豫州刺史，其二千石以下，阿縱不如法者，皆舉奏免之，帝曰：逵真刺史矣，布告天下，當以豫州為法。","sortOrder":29},
  {"id":"s_work_nvlt_50_30","chapterId":"ch_work_nvlt_50","text":"《魏略》曰：裴潛為兖州時，嘗作一胡床，及去，留以掛柱。","sortOrder":30},
  {"id":"s_work_nvlt_50_31","chapterId":"ch_work_nvlt_50","text":"王隱《晉書》曰：羊祜都督荆州諸軍事，招携以禮，懷遠以德，吳人悅服，稱為羊公。","sortOrder":31},
  {"id":"s_work_nvlt_50_32","chapterId":"ch_work_nvlt_50","text":"又曰：山涛轉為冀州刺史，自涛居州，甄拔隱屈，搜求賢才，旌命所加，三十餘人，皆顯名當世，冀州之士，於是為盛。","sortOrder":32},
  {"id":"s_work_nvlt_50_33","chapterId":"ch_work_nvlt_50","text":"又曰：杜預為镇南大將軍，都督荆州諸軍事，南土美而謠之曰：後世無叛有杜翁，孰識智名與勇功。","sortOrder":33},
  {"id":"s_work_nvlt_50_34","chapterId":"ch_work_nvlt_50","text":"又曰：陶侃為都督荆雍益梁四州諸軍事，是時荆州大飢，百姓多饿死，侃至，秋熟辄籴，至飢，复价粜之，士庶歡悅，鹹蒙濟賴。","sortOrder":34},
  {"id":"s_work_nvlt_50_35","chapterId":"ch_work_nvlt_50","text":"又曰：庾冰為中書監扬州刺史，乃心夙夜，情存治道，賓禮朝資，升擢後進，由是朝野註心，鹹曰賢相。","sortOrder":35},
  {"id":"s_work_nvlt_50_36","chapterId":"ch_work_nvlt_50","text":"又曰：庾翼都督江荆益三州刺史，製度規模，每出於人，數年之中，軍國充實，人情翕然，稱其才明，由是自河以南，皆懷歸附。","sortOrder":36},
  {"id":"s_work_nvlt_50_37","chapterId":"ch_work_nvlt_50","text":"又曰：吳隱之為廣州刺史，州界有水，名貪泉，父老雲，飲此者，皆使廉士变貪，隱之始踐境，先到水所，酌而飲，因賦詩曰：古人雲此水，一歃重千金，若使夷齊飲，終當不易心。","sortOrder":37},
  {"id":"s_work_nvlt_50_38","chapterId":"ch_work_nvlt_50","text":"曹嘉之晉紀雲，羊暨為青州刺史，暨牛產犢，及遷，以官舍所生，遺之而去。","sortOrder":38},
  {"id":"s_work_nvlt_50_39","chapterId":"ch_work_nvlt_50","text":"【詩】梁元帝後臨荆州詩曰：擁旄去京縣，褰帷辭未央，弱冠從王役，從容遊豈涨，［句有訛。］不學胡威絹，寧掛裴潛床，所冀方留犢，行當息飲羊，戲蝶時飄粉，風花乍落香，高欄來蕙氣，疏帘度晚光，綺錢臨仄宇，阿閤繞長廊。","sortOrder":39},
  {"id":"s_work_nvlt_50_40","chapterId":"ch_work_nvlt_50","text":"又示民吏詩曰：闕里尚捴謙，厲乡裁知足，咨餘再分陝，少思宜寡欲，霞出浦流紅，苔生岸泉绿，方令江漢士，变為邹魯俗。","sortOrder":40},
  {"id":"s_work_nvlt_50_41","chapterId":"ch_work_nvlt_50","text":"又別荆州吏民詩曰：玉節居分陝，金貂總上流，麾軍時舉扇，作賦且登樓，年光遍原隰，春色滿汀洲，日華三翼舸，風轉七星遊，向解青絲纜，將移丹桂舟。","sortOrder":41},
  {"id":"s_work_nvlt_50_42","chapterId":"ch_work_nvlt_50","text":"梁劉孝綽和湘東王理訟詩曰：冯翊亂京兆，廣漢欲兼治，豈若兼邦牧，朱輪褰素帷，淮海封畿地，雜俗良在茲，禁奸擿銖兩，馭黠震豺狸。","sortOrder":42},
  {"id":"s_work_nvlt_50_43","chapterId":"ch_work_nvlt_50","text":"【碑】後漢蔡邕荆州刺史庾侯碑曰：君資天地之正氣，含太極之純精，明絜鮮於白珪，貞操厲乎寒松，视鑒出於自然，英風發乎天骨，事親以孝，則行侔於曾闵，結交以信，則契明於黃石，溫溫然弘裕虛引，落落然高風起世，信荆山之良寶，靈川之明珠也，爰在弱冠，英風固以扬於四海矣，拜為荆州刺史，杖冲靜以臨民，施仁義以接物，恩惠著於萬里，誠信畅於殊俗，由是撫亂以治，缓扰以靜也，帝嘉其功，錫以車服，方將扫除寇逆，清一宇宙，廓天步之艱難，寧陵夷之屯否。","sortOrder":43},
  {"id":"s_work_nvlt_50_44","chapterId":"ch_work_nvlt_50","text":"晉潘嶽荆州刺史東武戴侯扬使君碑曰：君誕保靈和，繼期載德，宣哲清朗，直道高尚，若乃嘉號推賢，博愛濟眾，邦党服其義，而縉［原作緒，據冯校本改。］紳慕其風，於時文後，歷數在躬，相國幕府，實允華夏，九德鹹事，俊乂在官，成君名器，納字參軍，宏略被於南國，美化行乎江漢，西陵之役，懸軍深入，親薄寇壘，躬行天誅，既而救兵不進，糧盡道窮，君乃怃然回慮，殿其眾而返，雖為法受黜，勋庸未崇，而天下伏其勇，世主思其忠。","sortOrder":44},
  {"id":"s_work_nvlt_50_45","chapterId":"ch_work_nvlt_50","text":"晉潘尼益州刺史楊恭侯碑曰：君乾靈之醇德，挺高世之殊量，禀天然不渝之操，體蘭石芳堅之质，夫其器膺弘濟，智能周達，窮不怨否，顯不矜泰，履行則為模楷，吐言則成隱括，德實充於內，而光華發乎外也，君發跡州國，委质明主，自景皇帝攝政，文皇帝繼業，值天下多虞，疆埸未靜，以君先帝所拔，懷寶後時，而深達遠識，有經國之量，故為腹心謀臣，而監度政事焉，君出則簡練熊羆，職司是圖，入則從容諷議，盡規帷幄，其所以進可替否，决疑定策者，皆言效於既往，而事簡於帝心，君再臨司官，三撫名郡，方將宣文德以來遠，建武功於所牧，銘曰：天生蒸民，有類有則，誕育恭表，應期秀特，文兼六行，武備七德，忠肅弘毅，柔嘉溫克，機事無瑕，臨疑不惑，我謀既精，我化既清，泽流河朔，勋著王庭，西南未夷，侯其是寧，上天不惠，早世潛靈。","sortOrder":45},
  {"id":"s_work_nvlt_50_46","chapterId":"ch_work_nvlt_50","text":"北齊邢子才冀州刺史封隆之碑曰：公世載儒雅之風，家傳鍾鼎之業，出三代而克阜，歷兩都而盛轉，五世［原作出，據冯校本改。］祖遊，遊子孚，恥斯鳥獸，狹此且［全北齊文三作丘。］壑，濡足焚首，念在一匡，委质中山，併充袞闕，故已援墜拯溺，大庇生民，祖定功業，建旆懷藩，扬旌冀部，耳目相接，歌詠獨存，文［按隆之父回，卒赠司空，謚孝宣，是文當作父。］司空孝宣公，禀润玉府，承華桂簿，望振鷺而齊舉，軼歸鸿而併運，以茲一德，光事三主，七登九伯之重，再處八元之任，必有餘慶，事屬才子，莫之與京，理歸世祿，非因原隰之氣，詎待河嶽之靈，發純粹而成址，禀中和而树质，神體秀異，志識間爽，幼體成人，弱不好弄，同鳳皇之五色，非豫章之七年，太昌初，平洛，除侍中驃騎大將軍，密勿枢功，逶迤袞職，貂蝉承弁，華藻披衣，鳴双璜於峻陛，驅六辔於廣路，升華輦以弼一人，踐太階而平天下。","sortOrder":46},
  {"id":"s_work_nvlt_50_47","chapterId":"ch_work_nvlt_50","text":"周王褒故陝州刺史冯章碑曰：其先陶唐氏之苗裔，尧少子，生而手有冯字，因以為氏，俾侯於魯，義等房心之地，餘與之廣，事符河汾之邑，使君禀靈河嶽，此［全北周文七作比。］德璁珩，閨門和美，譽聖开宗，握文命氏，濁水北流，秦關東徙，巖险襟帶，山河枕倚，陆離組甲，從容青紫。","sortOrder":47},
  {"id":"s_work_nvlt_50_48","chapterId":"ch_work_nvlt_50","text":"周庾信少保幽州刺史豆盧府君碑曰：本姓慕容，燕文帝晃之後也，其先保姓受氏，初存柳城之功，开國承家，始靜遼陽之亂，尚書府君，改姓豆盧，筮仕於魏，公資忠履孝，蘊義懷仁，直幹百尋，澄波千頃，留心職仕，愛玩圖籍，官曹案牍，未嘗煩擁，戎馬交馳，不妨殊俗，兄弟公侯，國朝親戚，宜春有湯沐之盛，濯龍無流水之譏，渭南千畝之竹，尚懼盈滿，池陽三頃之田，常思止足，銘曰：朝鮮稱國，孤竹為君，地稱高柳，山名密雲，遼陽趙列，武遂秦分，寶珪世胄，雕戈舊勋，名稱實賓，言謂身文，朝傾地镇，夜落台星，石壇承祀，丰碑頌靈，渭城高柏，昌陵下亭，須知地布，為讀山銘。","sortOrder":48},
  {"id":"s_work_nvlt_50_49","chapterId":"ch_work_nvlt_50","text":"【墓志】梁王僧孺豫州墓志曰：自姬發系，因魏傳緒，留路在趙，名賢世袭，相秦將漢，英雄系踵，忘寵辱，無慍喜，靡矜夸，慎嗜欲，其行軍用武，勋合奇正，乃治邊御眾，威裕兼行，常懍懍然以中原為己任，或欲十萬而橫行，乍思五千而深入，克反舊京，飲馬函渭，然後高臥間帷，晤言空穀，思魯連之辭賞，慕田畴之高跪，［句有訛。］而火傳川逝，長涂已迫，雖景鍾良史，有功必書，刻板鏤石，宜兼不朽，銘曰：高勋藹藹，長旌高旆，入作牙爪，出司襟帶，民謠不息，王言有會，功為上等，正稱九最，日隆寵秩，方登遠大，羲辔難留，濛水易收，秘丘玄戶，杳杳悠悠。","sortOrder":49},
  {"id":"s_work_nvlt_50_50","chapterId":"ch_work_nvlt_50","text":"陳徐陵裴使君墓志銘曰：君五音之候，兼其方牧，八陣之圖，窮其巧变，用能戰必勝，攻必取，督稱無難，兵號解煩，朝飛火箭，夜耸雲梯，燧象從奔，聯狼已合，於是厥［本集作嚴。］顏不桡，極咍諸戎，庞德高聲，肆言群逆，胡夷總至，猶持子路之纓，鋒刃相交，終荷溫生之節，每以财輕篻箨，義重嵩衡，割宅字貧友之孤，开門延故人之殯，篤好朋遊，居常滿席，每至鮮雲藹藹，披王安之衣，明月团团，似班姬之扇，日帶花以如笑，風鳴條而若歌，傍列絲桐，對扬文酒，一石之後，逾能斷獄，五斗之量，猶未解醒，嗟乎潘嶽之詩，致哀周密，莊公之诔，用愍相责，［本集作遺。］","sortOrder":50},
  {"id":"s_work_nvlt_50_51","chapterId":"ch_work_nvlt_50","text":"陳江總廣州刺史欧陽頠墓志曰：公家習尚書，少府孺高於漢册，世居渤海，太守文重乎晉原，中原丧亂，避地南徒，公孝敬純深，友悌惇睦，家積遺财，併讓諸季，兼周同壤，公含率內映，遠識沈通，窒嗜欲，謹言行，資貞幹，事廉隅，梁室不造，凶羯凭凌，公被銳執凶，有志匡复，梁孝元帝授散騎常侍東衡州刺史始興縣侯，而犬戎弒逆，宗社播遷，陳纂揖讓，攸歸高祖，恩加惟舊，橫使持節，都督南衡二十二州諸軍事廣州刺史，進為开府儀同三司山陽郡公，進號征南將軍，加鼓吹一部，巫山遠曲，喧騎吹於日南，芳树清音，肅軍容於海截，追赠車騎將軍司空，公涉獵六經，優遊百氏，宽徭省賦，化伯越之歸心，撫寒投醪，感三軍之死力，在室如賓，寧慚屋漏，不貪為寶，每畏人知，殺青無兼兩之疑，薏苡豈懷珠之謗，如羊如粟，不改夷齊之心，遺慶遺風，方留豹產之德。","sortOrder":51},
  {"id":"s_work_nvlt_50_52","chapterId":"ch_work_nvlt_50","text":"【表】魏武帝謝領兖州牧表曰：入司兵校，出總符任，臣以累葉受恩，膺荷洪施，不敢顧命，是以將戈帥甲，順天行誅，雖戮夷覆亡不暇，臣愧以興隆之秩，功無所執，以伪假實，條不勝華，竊感譏請，蓋以惟穀。","sortOrder":52},
  {"id":"s_work_nvlt_50_53","chapterId":"ch_work_nvlt_50","text":"梁簡文帝為武陵王讓扬州表曰：臣延首青冥，傾心紫府，言非東里，誠譬北辰，而滔滔雲漢，不被霈然之泽，鬱鬱仙居，方隔下臣之奏，周任量力，請固所陳，明主理奪，伏冀照許，臣聞系風捕影，涉求之路靡階，玉馬金舟，適遠之資無讬。","sortOrder":53},
  {"id":"s_work_nvlt_50_54","chapterId":"ch_work_nvlt_50","text":"南康王會理讓湘州表曰：絲言自天而忽委，玉刻披雲而下墜，浮舟千仞，呂梁之畅已深，總辔萬尋，懸車之懼非淺。","sortOrder":54},
  {"id":"s_work_nvlt_50_55","chapterId":"ch_work_nvlt_50","text":"梁劉孝儀安成王讓江州表曰：臣聞失晨之雞，雖不忘於改旦，败駕之馬，終取忸於衔鑣，臣昔牧淮岱，皇風咫尺，一变至道，易以為政，而亂政莫理，美錦徒傷，豈可复宣六條，闡化千里。","sortOrder":55},
  {"id":"s_work_nvlt_50_56","chapterId":"ch_work_nvlt_50","text":"又曰：臣聞六辔沃若，不策玄黃之馬，九成輪奐，無求擁肿之材，何則，跳跼之路已窮，梁棟之用斯闕。","sortOrder":56},
  {"id":"s_work_nvlt_50_57","chapterId":"ch_work_nvlt_50","text":"南平王讓徐州表曰：竊以淮岱務殷，事乖坐嘯，枌榆望重，非可臥治，臣綿頓枕席，動移旬晦，恒恐尺波易流，寸陰難保，寧可复冒此寵，膺茲恩榮。","sortOrder":57},
  {"id":"s_work_nvlt_50_58","chapterId":"ch_work_nvlt_50","text":"臨川王解扬州表曰：臣自馳傳斗牛，作牧淮海，政刑兩空，璿璣六運，既昧弛張之要，尤慚大小之獄，故以結詠濡翼，取愧能官，每一進思，無忘退食，誠复恩私可凭，而彝倫難紊，敢恃慈弘，冒披心款，乞解州任，少弭素餐。","sortOrder":58},
  {"id":"s_work_nvlt_50_59","chapterId":"ch_work_nvlt_50","text":"又為鄱陽嗣王初讓雍州表曰：臣大邦維屏，既慚宗子之詩，思樂泮宮，有缺僖公之頌，特以周开元伯，錫壤參墟，漢啟三倕，分珪舊楚，身私家慶，總集微躬，雍部襟帶，跨製數州，西距峣關，南逾邓塞，雖复呼韓來朝，瑽街納质，二虜尋戈，四郊無警，猶如王戎雅識，羊祜尚義，臣求諸己，無或宴安，進思盡忠，歸乎犯謁。","sortOrder":59},
  {"id":"s_work_nvlt_50_60","chapterId":"ch_work_nvlt_50","text":"李扬州舅讓表曰：人心彼此，盡為敵國，金柝夜警，和門晝閉，加以淮水淼漫，危同三坂，懷山之势已成，為魚之期可見，若使身死可以益國，城没足用報恩，雖葬魚鱉，其甘如荠，政以朽耄無庸，心負恩寄，恥辱之甚，非止老臣。","sortOrder":60},
  {"id":"s_work_nvlt_50_61","chapterId":"ch_work_nvlt_50","text":"【啟】梁陆倕敕使行江州事啟曰：封畛遐曠，纏井奧實，陆海神皋，偏屬茲境，兼以茂親明德，淮翰作镇，宣述條教，匡贊盛猷，自非問望兼弘，寧可擢膺嘉舉。","sortOrder":61},
  {"id":"s_work_nvlt_50_62","chapterId":"ch_work_nvlt_50","text":"【教】齊謝朓為錄公拜扬州恩教曰：昔召南分陝，流甘棠之德，平陽好道，深獄市之寄，吾忝屬負荷，任總侯伯，受餞元戎，作牧中甸，此地五都雜會，四方是則，而向隅之矜斯積，納隍之叹猶繁，興念下車，無忘待旦，有齊禮导德，致之仁寿，弘漏網之宽，申在宥之泽。","sortOrder":62},
  {"id":"s_work_nvlt_50_63","chapterId":"ch_work_nvlt_50","text":"梁簡文帝罢雍州恩教曰：折以片言，事關往聖，寄之勿扰，傳彼昔賢，故剋木不對，畫獄無入，吾自之雍，矜懷圄犴，幸得天無虛旱，地歇怪虫，今軸車行涂，舟艎且戒，植柳官度，尚或依然，寄飯曹僖，猶思恩宥，况義化君民，節離寒暑，悯茲歧路，宜留惠泽。","sortOrder":63},
  {"id":"s_work_nvlt_50_64","chapterId":"ch_work_nvlt_50","text":"臨雍州原减民間資教曰：誠欲投軀决堤，曝身求雨，九伐方弘，三驅未息，役爨之忧，兵家斯急，師興之費，日用弥廣，今春流既長，舻舳爭前，轉漕相追，饋糧不闕，義存矜急，無俟多費。","sortOrder":64},
  {"id":"s_work_nvlt_50_65","chapterId":"ch_work_nvlt_50","text":"臨雍州革貪惰教曰：壮夫疲於擐甲，匹婦勞於轉输，藜藿難充，轉死溝壑，春蠶不暖寒肌，冬收不周夏飽，胡寧斯忍，复加裒削，傷盜抵罪，遂為十一之資，金作贖刑，翻成润屋之產。","sortOrder":65},
  {"id":"s_work_nvlt_50_67","chapterId":"ch_work_nvlt_50","text":"應劭《漢官》曰：河南，先所理周地也，秦兼天下，置三川守，洛陽尹也，漢更名河南，孝武皇帝增雲太守，世祖中興，徙都雒陽，改號為尹，尹，正也。","sortOrder":67},
  {"id":"s_work_nvlt_50_68","chapterId":"ch_work_nvlt_50","text":"王隱《晉書》曰：樂廣為河南尹，郡中多怪，無敢數在廳事者，唯廣處之。","sortOrder":68},
  {"id":"s_work_nvlt_50_69","chapterId":"ch_work_nvlt_50","text":"《晉中興書》曰：晉太興元年，改丹陽內史為丹陽尹。","sortOrder":69},
  {"id":"s_work_nvlt_50_70","chapterId":"ch_work_nvlt_50","text":"又曰：劉隗為長兼侍中，出補丹陽尹，隗雖在外，而萬機秘密，皆豫聞之。","sortOrder":70},
  {"id":"s_work_nvlt_50_71","chapterId":"ch_work_nvlt_50","text":"《語林》曰：許玄度出都，詣劉真長，先不識，至便造之，一面留連摽，［○句有脱文。］劉［原字坏，據明活字本補。］貴略無造詣，遂九十日一詣許，［按世說寵禮篇註作九日十一詣之，此有倒訛。］語曰：卿為不去，家將成輕薄京尹。","sortOrder":71},
  {"id":"s_work_nvlt_50_72","chapterId":"ch_work_nvlt_50","text":"【詩】梁元帝去丹陽尹尹荆州詩曰：驂駕乘驷馬，謁帝朝承明，分符莅閩越，終然慚励精。","sortOrder":72},
  {"id":"s_work_nvlt_50_73","chapterId":"ch_work_nvlt_50","text":"又曰：副君垂奖眄，仁慈穆且敦，終朝陪北閣，清夜侍西園，降貴深知己，寧思食椹恩，未嘗辭晝室，誰忍去轘轅。","sortOrder":73},
  {"id":"s_work_nvlt_50_74","chapterId":"ch_work_nvlt_50","text":"梁萧琛和元帝詩曰：妙善有兼姿，群材成大厦，弈弈工辭賦，翩翩富文雅，麗藻若龍雕，洪才類河泻，案牍時多暇，優遊閱典墳，儒墨自玄解，文史更區分，平台禮申穆，兔苑接卿雲，軒蓋荫馳道，珠履忽成群，德音高下被，英聲遠近聞。","sortOrder":74},
  {"id":"s_work_nvlt_50_75","chapterId":"ch_work_nvlt_50","text":"梁徐勉和元帝詩曰：敬愛良是賢，謙恭寔所務，尊賢遺道德，重學嚴師傅，六藝誠為敏，三雍稱有裕，覆被唯仁義，吐納必珪璋，壮思如泉涌，逸藻似雲翔，夙有匡時調，早懷經世方，留心在庶績，厲精思治綱。","sortOrder":75},
  {"id":"s_work_nvlt_50_76","chapterId":"ch_work_nvlt_50","text":"【表】梁劉孝儀晉安王讓丹陽尹表曰：臣聞盈尺径寸，易取琢磨，南箕北斗，難為簸挹，何則，良工质美，在器成珍，假名责實，涉求必殆。","sortOrder":76},
  {"id":"s_work_nvlt_50_77","chapterId":"ch_work_nvlt_50","text":"梁邵陵王讓丹陽尹初表曰：臣進非民譽，退異宗英，尸居戎號，已紊彝典，况京兆五守，西漢難追，河南二尹，東京罕繼，審己循涯，自知莫可，街談巷議，尤見不勝。","sortOrder":77},
  {"id":"s_work_nvlt_50_78","chapterId":"ch_work_nvlt_50","text":"梁庾肩吾為南康王讓丹陽尹表曰：臣聞劍鏤七星，非有司天之用，帘圖五嶽，寧識崇朝之雲，是知策彼泥龍，不能令其逐日，乘斯流馬，安可使其奔電，方今振鷺盈庭，白駒空穀，惟帝念功，惟明克允，君子之國，幸聞其讓，石門之水，獲免於貪。","sortOrder":78},
  {"id":"s_work_nvlt_50_79","chapterId":"ch_work_nvlt_50","text":"【序】梁元帝丹陽尹傳序曰：傳曰：大夫受郡，《漢書》曰：尹者正也，及其用人，實難授受，廣漢和顏接下，子高自辅經術，孫寶行嚴霜之誅，袁安留冬日之愛，自二京版荡，五馬南渡，固乃上燭天文，下應地理，爾其地势，可得而言，東以赤山為城皋，南以長淮為伊洛，北以鍾山為卓阜，西以大江為黃河，既变淮海為神州，亦即丹陽為京尹，雖得仁之盛，頗愧前賢，而眄遇之深，多用宰辅，皇上受圖負扆，寶歷惟新，製禮以告成功，作樂以彰治定，豈直四三皇，六五帝，孕夏陶周而已哉，若夫位以德叙，德以位成，每念忝莅京河，茲焉四載，以入安石之門，思勤王之政，坐真長之室，想清談之風，求瘼餘晨，頗多夏景，今缀采英賢，為丹陽尹傳。","sortOrder":79},
  {"id":"s_work_nvlt_50_80","chapterId":"ch_work_nvlt_50","text":"◇太守","sortOrder":80},
  {"id":"s_work_nvlt_50_81","chapterId":"ch_work_nvlt_50","text":"《漢書》曰：郡守，秦官，掌理其郡，秩二千石，景帝中二年，更名太守。","sortOrder":81},
  {"id":"s_work_nvlt_50_82","chapterId":"ch_work_nvlt_50","text":"又曰：季布為河東太守，孝文時，人有言其賢，召欲以為御史大夫，人又言其勇使酒，至，留邸一月罢，布曰：臣待罪河東，陛下無故召臣，此人必有欺陛下者，夫以一人譽召臣，一人毀去臣，恐天下有識聞之，以窥陛下，上曰：河東吾股肱郡，故時召君爾。","sortOrder":82},
  {"id":"s_work_nvlt_50_83","chapterId":"ch_work_nvlt_50","text":"又曰：文翁，庐江人，少好學，景帝末，為蜀郡守，修起學馆於成都，招下縣子弟，以為學官僮子，得教令，吏民見而榮之，由是大化蜀地，學於京師者，比齊魯焉。","sortOrder":83},
  {"id":"s_work_nvlt_50_84","chapterId":"ch_work_nvlt_50","text":"又曰：黃霸，字次翁，為潁川太守，戶口歲增，治為天下第一，徵守京兆尹，是時鳳皇神雀數集郡國，潁川尤多，天子以霸治行終長者，下詔賜爵關內侯，黃金百斤。","sortOrder":84},
  {"id":"s_work_nvlt_50_85","chapterId":"ch_work_nvlt_50","text":"又曰：哀帝時，南郡多盜賊，授萧育為太守，上以育耆舊名臣，乃以三公使車載育，入殿中受策，加賜黃金二十斤，育至南郡，盜賊斷跡。","sortOrder":85},
  {"id":"s_work_nvlt_50_86","chapterId":"ch_work_nvlt_50","text":"《韓子》曰：李悝為魏文侯上地守，而欲民之善射，乃下令雲，民有狐疑之訟者，令之射狗，中之者勝，不中者負，民皆習射，日夜不休，與秦戰，大败之，以民之善射也。","sortOrder":86},
  {"id":"s_work_nvlt_50_87","chapterId":"ch_work_nvlt_50","text":"《東觀漢記》曰：冯勤曾祖扬，宣帝時為弘農太守，生八男，［原訛勇，據冯校本改。］皆典郡，趙魏號為冯萬石。","sortOrder":87},
  {"id":"s_work_nvlt_50_88","chapterId":"ch_work_nvlt_50","text":"又雲，趙喜，字伯陽，為平原太守，後青州大蝗，入平原界辄死，歲屢有年，百姓歌之。","sortOrder":88},
  {"id":"s_work_nvlt_50_89","chapterId":"ch_work_nvlt_50","text":"又曰：朱暉，字文季，再遷臨淮太守，吏民畏愛，為之歌曰：強直自遂，南陽朱季，吏畏其威，民懷其惠。","sortOrder":89},
  {"id":"s_work_nvlt_50_90","chapterId":"ch_work_nvlt_50","text":"又曰：張堪，字君淑，试守蜀郡太守，遷漁陽太守，开治稻田八千餘頃，教民种田，百姓以殷富，童謠歌雲，桑無附枝，麥穗兩岐，張君為政，樂不可為，视事八年，匈奴不敢犯塞。","sortOrder":90},
  {"id":"s_work_nvlt_50_91","chapterId":"ch_work_nvlt_50","text":"又曰：廉范，字叔度，為蜀郡太守，成都邑宇逼侧，舊製禁民夜作以防火，而更相隱蔽，燒者日日相屬，范乃毀削前令，但嚴使储水，百姓為便，乃歌之雲，廉叔度，來何暮，不禁火，民安堵，昔無襦，今五袴。","sortOrder":91},
  {"id":"s_work_nvlt_50_92","chapterId":"ch_work_nvlt_50","text":"又曰：王阜為益州太守，神馬四出，镇河中，甘露降，白乌見，連有瑞應，世謂其用法平正宽慈，惠化所致。","sortOrder":92},
  {"id":"s_work_nvlt_50_93","chapterId":"ch_work_nvlt_50","text":"《三辅决錄》曰：馬援誡兄子書，庞伯高，敦篤周慎，口無擇言，吾愛重之，原汝曹效之，世祖見援書，即擢為零陵太守，在郡四年，甚有治化。","sortOrder":93},
  {"id":"s_work_nvlt_50_94","chapterId":"ch_work_nvlt_50","text":"張璠《漢書》曰：宋登，字叔陽，出為潁川太守，市無豫价，路不拾遺，病免，卒於家，汝陰人配社祀之。","sortOrder":94},
  {"id":"s_work_nvlt_50_95","chapterId":"ch_work_nvlt_50","text":"沈約《宋書》曰：羊玄保為黃門郎，善弈棋，棋品第三，太祖亦好弈，數蒙引見，與太祖赌郡，戲勝，以補宣城太守。","sortOrder":95},
  {"id":"s_work_nvlt_50_96","chapterId":"ch_work_nvlt_50","text":"【詩】宋謝靈運去永嘉郡詩曰：野曠沙岸靜，天高秋日明，憩石挹飛泉，攀林搴落英。","sortOrder":96},
  {"id":"s_work_nvlt_50_97","chapterId":"ch_work_nvlt_50","text":"梁簡文帝罢丹陽郡往與吏民別詩曰：久歸從事麥，非留故吏錢，柳栽今尚在，棠陰君詎怜。","sortOrder":97},
  {"id":"s_work_nvlt_50_98","chapterId":"ch_work_nvlt_50","text":"梁沈約去東陽與吏民別詩曰：微薄叨今幸，忝荷非昔期，唐風豈異世，欲明重在茲，飾驂去關辅，分竹入河淇，下車如昨日，曳組忽弥期，霜載凋秋草，風三動春旗，無以招臥轍，寧望後相思。","sortOrder":98},
  {"id":"s_work_nvlt_50_99","chapterId":"ch_work_nvlt_50","text":"【碑】晉孫楚雁門太守牵府君碑曰：君體德允直，才量高杰，明鑒達於世变，弘毅足以致遠，聿振鸿翼於袞尘之表，卓爾先覺於擬議之前，遷雁門太守，教民耕戰，聽斷以情，信賞必罰，下服其命，是以夷狄窘迫，罔知所安，譬秋枯之陨晨風，激雹之不及掩耳目也，伐叛柔服，威震沙漠，遺种遠跡，萬里無煙，烈烈君侯，文武允崇，少兼七德，翰飛撫戎，名扬河朔，威震漢中，臨危運奇，在難匪從，回旌束麾，撫司徐青，截彼隆賊，海岱以平，剖符千里，為國扞城。","sortOrder":99},
  {"id":"s_work_nvlt_50_100","chapterId":"ch_work_nvlt_50","text":"晉孫綽潁州府君碑曰：君天縱杰邁，奇逸卓荦，茂才亮拔，雅度恢廓，通理遠鑒之識，禮樂飾身之具，固以足之於天仞，冠之於搢紳，出匡南位，功深於爵，金龟三曜，冲壤再發，道光古賢，風改彫伪，允可謂明德宏猷，贊世之伟器者矣，矯矯秀姿，卓卓英韻，他人之高，及肩而已，邀命有數，讬生皇代，所忝之至，人知其幸，况在懷情，而無自識，但親勤末效，违離已及，低徊房禁，攀恋罔遺。","sortOrder":100},
  {"id":"s_work_nvlt_50_101","chapterId":"ch_work_nvlt_50","text":"【表】梁范雲除始興郡表曰：臣被沐恩靈，栖息榮幸，貶貌兢视，挺襟軫慮，徒誓蠡管之誠，終沈熒爝之用，不悟懸景麗天，通涇润下，月緒未交，鎔光再鑠，脩鞠慚疑，驩不及抃，且地鄰舊越，甸分故楚，厥壤惟腴，寔邦斯大，將何以再宣王猷，陶奉惠渥。","sortOrder":101},
  {"id":"s_work_nvlt_50_102","chapterId":"ch_work_nvlt_50","text":"梁萧子范為蔡令樽讓吳郡表曰：全［原訛今，據冯校本改。］吳奧區，地迫都輦，壁被［冯校本作彼，則上壁字當作譬。］四京，則扶風冯翊，方之洛下，則潁川河內，自非時雨之政，解繩之才，寧可奉共理之言，承河润之旨，邓攸廉白，乃著不留之歌，贺邵沈靜，猶致題門之责。","sortOrder":102},
  {"id":"s_work_nvlt_50_103","chapterId":"ch_work_nvlt_50","text":"陳徐陵為始興王讓琅邪二郡太守表曰：甫離懷袖，裁脱綺紈，適贺隆私，使膺珪組，執玉不起，抠衣未勝，自甘泉通大，［本集作火。］細柳屯兵，旁帶戎尘，頗同疆埸，言瞻漢草，乃曰中州，遙望胡桑，已成邊郡，誠复居藩體國，應思馬駿之功，論地維親，宜慕萧［本集作曹。］彰之勇。","sortOrder":103},
  {"id":"s_work_nvlt_50_104","chapterId":"ch_work_nvlt_50","text":"隋江總為衡陽王讓吳郡表曰：芝泥馳印，發命开函，穎之誠，［句有脱文。］夏霜易霣，兢惶之至，春冰可涉，臨辎面軾，即事何取，廣川無聲，頗知自匹。","sortOrder":104},
  {"id":"s_work_nvlt_50_105","chapterId":"ch_work_nvlt_50","text":"【教】梁簡文帝复臨丹陽教曰：昔越張脩猛，用弘美績，邊延善政，寔著民謠，吾冲弱寡能，未明理道，猥以庸薄，作守京河，將恐五袴無謠，兩岐難頌，思立恩惠，微宣風范。","sortOrder":105},
  {"id":"s_work_nvlt_50_106","chapterId":"ch_work_nvlt_50","text":"梁丘遲永嘉郡教曰：貴郡控帶山海，利兼水陆，實東南之沃壤，一都之巨會，而曝背拘牛，屢空於畎畝，績麻治絲，無聞於窐巷，其有耕灌不脩，桑榆靡树，遨遊鄽里，酣酺卒歲，越伍乖鄰，流宕忘返，才異相如，而四壁獨立，高慚仲蔚，而三径没人，雖謝文翁之正俗，庶幾龚遂之移風。","sortOrder":106},
  {"id":"s_work_nvlt_50_107","chapterId":"ch_work_nvlt_50","text":"梁任昉為齊竟陵王世子臨會稽郡教曰：富室兼併，前史共蠹，大姓侵威，往哲攸嫉，而權豪之族，擅割林池，势富之家，专利山海，至乃水稱峻巖，嚴我君後，［按全梁文四十二雲，嚴我君後以下十句，當是碑頌之文，誤跳在此。］崇墉增仞，內通神明，出符大順，火炎崑岡，神嶽崩潰，蘭艾同燼，玉石俱碎，哲人遭命，哀有餘慨。","sortOrder":107},
  {"id":"s_work_nvlt_50_108","chapterId":"ch_work_nvlt_50","text":"【碑】桓宣城碑曰：君器量高濬，神氣披朗，商略雅俗，隱括真伪，擢奇取異，不軌常流，固以准的當時，擬議郭許矣，處身立朝，不峻功名，俯仰顯默之际，優遊可否之間，跡埤而道不污，身屈而志不屑矣，銘曰：於穆我後，禀茲純爽，虛豁高畅，萧條邁上，風任外舒，卓鑒內朗，神栖冲慎，形同俯仰，將登槐棘，宏振綱網，令儀早徂，德音永响。","sortOrder":108},
  {"id":"s_work_nvlt_50_109","chapterId":"ch_work_nvlt_50","text":"【銘】晉傅玄江夏任君銘曰：君讳倏，承洪苗之高胄，禀岐嶷之上姿，质美珪璋，志邈雲霄，景行足以作儀范，柱石足以慮安危，弱冠而英名播乎遐邇，拜江夏太守，內平五教，外運六奇，邦國人安，飄尘不作，銘曰：瓘瓘任君，應和秀生，如山之峙，如海之淳，才行闡茂，文武是經，群後利德，泊然弗營，宜享景福，光辅上京，如何夙逝，不延百齡。","sortOrder":109},
  {"id":"s_work_nvlt_50_110","chapterId":"ch_work_nvlt_50","text":"宋傅亮故安成太守傅府君銘曰：爰自漢季，以及晉朝，高名遠德，系軌於時，貞風亮節，流聲累葉，君承世德之芳流，荡二象之淑靈，含章蘊粹，佩蘭蕙，［○句有脱文。］韦帶飯蔬，朝不及夕，不以栖遲改其間，不以隱約回其操，楊生所為，夕幽而不改隨和之德者，其斯之謂欤，栖心古烈，擬踵前修，淹流孔老，［原訛若，據冯校本改。］宛然內求，於言中倫，庸行歸周，神之聽之，匪明匪幽。","sortOrder":110},
  {"id":"s_work_nvlt_50_111","chapterId":"ch_work_nvlt_50","text":"【章】梁簡文帝為王規拜吳郡太守章曰：臣今原斂衽後恩，循牆所忝，示山河而形勝，顧浮桥而不見，蒼鷹一遊，望仙掌而逮然，方當駕吉祥之車，入句吳之地，驅緹扇之馬，撫奉德之乡，製錦何階，棼絲方始。","sortOrder":111},
  {"id":"s_work_nvlt_50_112","chapterId":"ch_work_nvlt_50","text":"梁陆倕授潯陽太守章曰：鏤水雕脂，不見大龍之象，課虛叩寂，寧聞駕辯之音，徒荷客蓋，空班推擇，不能使府庭生梓，橫閤誦經，俯睨朱辎，仰瞻繒蓋，漏上嚴辨，伏軾多慚。","sortOrder":112},
  {"id":"s_work_nvlt_50_113","chapterId":"ch_work_nvlt_50","text":"【表】宋顏延之拜永嘉太守辭東宮表曰：抗志絕操，芼陆謝刍，代食賓士，何獨匪民。","sortOrder":113},
  {"id":"s_work_nvlt_50_114","chapterId":"ch_work_nvlt_50","text":"又為齊景靈王世子臨會稽郡表曰：此郡歌風蹈雅，既仿佛於淹中，春誦夏絃，實依俙於河上，頃者以來，稍有訛替，可推擇明經，式寄儒職，使琢玉成器，無爽昔談，鑄金待价，有符舊說。","sortOrder":114},
  {"id":"s_work_nvlt_50_115","chapterId":"ch_work_nvlt_50","text":"【教】梁陆倕未至潯陽郡教曰：第五倫之臨會稽，躬斬馬草，邓伯道之莅吳郡，自運家糧，故能使吏作頌歌，民胥興詠，太守薄德，谬叨龟組，竊原巴祗闇坐接客，思匹吳隱被絮對賓，常藥自隨，式瞻無遠，单車入境，竊所庶幾，舊須發民治道及戍邏揄樵采，［句有脱文。］諸如此類，一皆省息。","sortOrder":115},
  {"id":"s_work_nvlt_50_116","chapterId":"ch_work_nvlt_50","text":"又雲，太守家本諸生，伏膺典記，光武靈台之籍，较涉根基，張華聚土之書，略見庭戶，貴郡圖載，其具存方策，校以山經，參諸括象，原野城寺，宛在心目，龍泉鶴嶺，不易窮登，所撰郡圖，可勿親用，公孫陛戟，既似井蛙，延寿執戈，實同兒戲。","sortOrder":116},
  {"id":"s_work_nvlt_50_117","chapterId":"ch_work_nvlt_50","text":"◇令長","sortOrder":117},
  {"id":"s_work_nvlt_50_118","chapterId":"ch_work_nvlt_50","text":"《左傳》曰：子皮使尹何［原訛問，據冯校本改。］為邑，子產曰：少，未知可否，子皮曰：使夫往而學焉，夫亦愈知治矣，子產曰：不可，人之愛人，求利之也，今吾子愛人則以政，猶未能操刀而使割也，其傷實多，子之愛人，傷之而已。","sortOrder":118},
  {"id":"s_work_nvlt_50_119","chapterId":"ch_work_nvlt_50","text":"《晏子春秋》曰：景公使晏子為阿宰，三年而毀聞於國，公不悅，召而免之，婴謝曰：婴知過矣，請复阿，三年而譽必聞於國，公召而賞之，辭而不受，公問其故，對曰：昔者婴之所治當賞，而今所以治當誅，是故不敢受。","sortOrder":119},
  {"id":"s_work_nvlt_50_120","chapterId":"ch_work_nvlt_50","text":"《說苑》曰：宓子賤治单父，彈琴，身不下堂，单父治，巫馬期亦治单父，以星出，以星入，日夜不處，以身親之，而单父亦治，巫馬期問其故，宓子曰：我之謂任人，子之謂任力，任力者勞，任人者佚。","sortOrder":120},
  {"id":"s_work_nvlt_50_121","chapterId":"ch_work_nvlt_50","text":"又曰：晉平公問趙武曰：中牟三國之股肱，邯鄲之肩髀也，寡人欲其良令也，其令空，誰使而可，趙武曰：邢子可，公曰：邢子非子之讎邪，對曰：私讎不入公門。又問曰：中府之令空，誰使而可，趙武曰：臣子可，故外舉不避讎，內舉不避子。","sortOrder":121},
  {"id":"s_work_nvlt_50_122","chapterId":"ch_work_nvlt_50","text":"《新序》曰：昔子奇年十八，齊君使之治阿，既行矣，悔之，使使追之，未到阿，及之還之，已到，勿還也，使者及之而不還，君問其故，對曰：臣見所以共載者白首也，夫以老者之智，以少者决之，必能治阿矣，是以不還。","sortOrder":122},
  {"id":"s_work_nvlt_50_123","chapterId":"ch_work_nvlt_50","text":"《史記》曰：西門豹為鄴令，會長老，問民所疾苦，禁巫祝為河伯取民之女為婦，凿渠十二，灌溉民田，到今皆得水利。","sortOrder":123},
  {"id":"s_work_nvlt_50_124","chapterId":"ch_work_nvlt_50","text":"《漢書》曰：焦延，字子貢，為小黃令，以伺候先知，奸邪盜賊不得發，愛養利民，當遷，三老官屬上書，原留延，有詔許之。","sortOrder":124},
  {"id":"s_work_nvlt_50_125","chapterId":"ch_work_nvlt_50","text":"又曰：萧育為茂陵令，會課，育第六，而陳令郭舜殿，見责問，育為之請，扶風怒曰：君課第六，裁自脱，何暇為之左右，及罢，傳召茂陵令詣後曹，當以職事對，育径出，曹書佐隨牵育，育按佩刀曰：萧育杜陵男子，何能詣曹也，遂趨出，欲去官，明旦，詔召入，拜為司隸校尉，育過扶風府門，官屬掾吏數百人，拜謁車下。","sortOrder":125},
  {"id":"s_work_nvlt_50_126","chapterId":"ch_work_nvlt_50","text":"又曰：召信臣以明經甲科為郎，出補穀陽令，舉高第，選上蔡長，其治视民如赤子，所居見稱述。","sortOrder":126},
  {"id":"s_work_nvlt_50_127","chapterId":"ch_work_nvlt_50","text":"司馬彪《續漢書》曰：牟融舉茂才，為丰令，视事三年，政化流行，縣無獄訟，吏畏而愛之，治有異跡，為州郡最。","sortOrder":127},
  {"id":"s_work_nvlt_50_128","chapterId":"ch_work_nvlt_50","text":"又曰：卓茂遷密令，其治民，舉善而教，不能則勸，口不出惡言，勞心忧念，吏民知其有缓急，以恩信待吏，吏畏而愛之，不忍欺也，元始中，天下蝗，河南二十縣蝗，獨不入密界，督郵書言，太守大怒，自出案行密界中，實然，乃驚。","sortOrder":128},
  {"id":"s_work_nvlt_50_129","chapterId":"ch_work_nvlt_50","text":"又曰：魯恭為中牟令，导民以孝，推誠而治，建初中，郡國螟傷稼，犬牙緣界，不入中牟，河南尹袁安，疑其不實，遣仁恕掾肥親往察验之，恭隨行阡陌，俱坐桑下，有雉止其傍，有童兒，親曰：何不击之，兒曰：雉方將雏，親矍然而起，與恭訣曰：所以來者，欲察治之善惡爾，今虫不犯境，此一異也，化及鳥獸，此二異也，竖子有仁心，此三異也，久留徒扰賢者，可［《太平御覽》二百六十七作耳，當屬上為句。］還府，以状白安，美其治，以励屬縣。","sortOrder":129},
  {"id":"s_work_nvlt_50_130","chapterId":"ch_work_nvlt_50","text":"又曰：孔奋守姑臧長，治有異道，時天下扰亂，河西獨安，而姑臧市日四合，為河西富縣，每前長居官數月，辄致赀產，奋在姑臧積四歲，财產不增，奋素孝，自來為長時，供養至謹，在姑臧，唯母極膳，妻子飲食但葱韭。","sortOrder":130},
  {"id":"s_work_nvlt_50_131","chapterId":"ch_work_nvlt_50","text":"又曰：蔡肜除偃師長，视事五年，縣無盜賊，州課第一，遷襄贲令，時盜賊抄掠，肜到官，誅奸猾，縣界清靜，詔書增秩一等，賜缣百疋，册書勉励。","sortOrder":131},
  {"id":"s_work_nvlt_50_132","chapterId":"ch_work_nvlt_50","text":"又曰：劉寵除東平陵令，是時民俗奢泰，寵到官躬俭，訓民以禮，上下有序，都鄙有章，视事數年，以母病弃官歸，百姓士女，攀車距輪，充塞道路，車不得前，乃輕服潛遁。","sortOrder":132},
  {"id":"s_work_nvlt_50_133","chapterId":"ch_work_nvlt_50","text":"又曰：劉騊［《太平御覽》二百六十七作劉駼騊，按當作劉騊駼。］為涢［御覽作湞。］陽長，政化大行，道不拾遺，以病去官，童謠歌曰：悒然不樂，思我劉君，何時复來，安此下民。","sortOrder":133},
  {"id":"s_work_nvlt_50_134","chapterId":"ch_work_nvlt_50","text":"又曰：虞詡為朝歌長，故舊皆弔，詡曰：難者不避，易者不從，不遇盤根错節，何以別其利器乎。","sortOrder":134},
  {"id":"s_work_nvlt_50_135","chapterId":"ch_work_nvlt_50","text":"又曰：公孫述補清水長，太守以其能，使兼治五縣，政事循理，奸盜不發，郡中謂有神明。","sortOrder":135},
  {"id":"s_work_nvlt_50_136","chapterId":"ch_work_nvlt_50","text":"又曰：虞延除細陽令，每至歲時伏腊，休遣徒系，各使還家，併感其恩，應期歸，有一囚，於家被病，自載詣獄，既至城門而死。","sortOrder":136},
  {"id":"s_work_nvlt_50_137","chapterId":"ch_work_nvlt_50","text":"又曰：董宣為洛陽令，寧平公主乳母奴，白日殺人，因匿主家，吏不能得，及主出行，以奴驂乘，宣於太［《太平御覽》二百六十六作大。］夏門亭候之，乃駐車叩馬，以刀畫數主失者三，叱奴下車，格殺之，主即馳車入宮，上大怒，召宣，令欲死乎，宣叩頭曰：臣奉法之吏，不敢縱法，不欲死也，上曰：捶之，宣曰：原一言，死無恨，上曰：何言，宣曰：陛下聖德中興，而縱奴殺良民，以奴殺臣，臣死之後，陛下何以治天下，捶殺臣，不如臣自殺，即以頭撑楹，流血被面，上令小黃門持之，曰：癡令，叩頭謝主，宣不從，上頓癡令頭，宣兩手據地，不肯低頭，上敕強項令出，詣太官賜食，［事具公主部。］","sortOrder":137},
  {"id":"s_work_nvlt_50_138","chapterId":"ch_work_nvlt_50","text":"又曰：鄭弘為縣令，政化大行，民王逢，得路遺寶物，縣於衢道，求主還之。","sortOrder":138},
  {"id":"s_work_nvlt_50_139","chapterId":"ch_work_nvlt_50","text":"又曰：胡紹為河內懷令，三日一视事，十日一詣仓［《太平御覽》二百六十七仓下有受字。］俸米，於閤外炊作乾飯食之，不設釜竈，得一彊盜，問其党與，得數百人，皆誅之，［原作奸，據冯校本改。］政教清平，為三河表。","sortOrder":139},
  {"id":"s_work_nvlt_50_140","chapterId":"ch_work_nvlt_50","text":"又曰：劉崑除江陵令，時縣連火灾，崑辄向火叩頭，多能降雨止風，具火部。","sortOrder":140},
  {"id":"s_work_nvlt_50_141","chapterId":"ch_work_nvlt_50","text":"《益部耆舊傳》曰：阎憲為綿竹令，有男子杜成，夜行，於路得遺裝，开视有錦二十疋，明早送詣吏曰：縣有明府君，犯此則慚。","sortOrder":141},
  {"id":"s_work_nvlt_50_142","chapterId":"ch_work_nvlt_50","text":"風俗通雲，俗說，孝明帝時，尚書郎河東王乔，遷為鄴令，乔有神，每月朔，常詣台朝，明帝怪其來數而無車騎，密令太子［風俗通子字無。］史候望，言臨至時，常有双凫從東南來，因伏伺，見凫舉羅，但得一只菭，使尚方識视，四年中所賜尚書郎屬履也，［事具神仙部。］","sortOrder":142},
  {"id":"s_work_nvlt_50_143","chapterId":"ch_work_nvlt_50","text":"魯國先賢傳曰：孔翊為洛陽令，置水庭前，得嘱讬書，皆投水中，一無所發。","sortOrder":143},
  {"id":"s_work_nvlt_50_144","chapterId":"ch_work_nvlt_50","text":"【詩】晉潘嶽懷縣詩曰：小國寡人民，終日寂無事，白水過庭激，绿槐夹門植，信美非吾土，秪搅懷歸志，眷然顧巩洛，山川邈離異，原言還舊乡，畏此簡書忌。","sortOrder":144},
  {"id":"s_work_nvlt_50_145","chapterId":"ch_work_nvlt_50","text":"晉河陽令潘安仁詩曰：密生化单父，子奇莅東阿，桐乡建遺勋，武城播絃歌，逸骥騰夷路，潛龍躍海波，弱冠步鼎铉，既立宰三河，徒美天姿茂，豈謂人爵多。","sortOrder":145},
  {"id":"s_work_nvlt_50_146","chapterId":"ch_work_nvlt_50","text":"陳陰铿罢故章縣詩曰：秩滿三秋暮，舟虛一水濱，漫漫遵歸道，凄凄對別津，晨風下散葉，岐路起飛尘，長岑舊知遠，萊芜本自貧，被里恒客吏，正朝不系民，唯當有一犢，留持赠後人。","sortOrder":146},
  {"id":"s_work_nvlt_50_147","chapterId":"ch_work_nvlt_50","text":"【頌】後漢蔡邕陳留太守行小黃縣頌曰：大顥為政，建時春陽，我君勸止，戾茲小黃，濟濟群吏，攝齊升堂，乃訓乃厲，示之憲方，原罪以心，察獄以情，钦於刑濫，惟務求輕，有辜小罪，放死從生，玄化洽矣，黔首用寧，惟以作頌，式昭德聲。","sortOrder":147},
  {"id":"s_work_nvlt_50_148","chapterId":"ch_work_nvlt_50","text":"又考城縣頌曰：暧暧玄路，北至考城，勸茲穡民，東作是營，農桑之業，為國之經，我君勤心，德音邈成，率爾苗民，慎不敬聽，女執伊筐，男執其耕，申戒群僚，務在宽平，罪人赦宥，囹圄用清，晉江伟襄邑令傅浑頌曰：君禀二儀之醇粹，履元亨之貞和，比德金玉，而堅白不磨，自處戶庭，而名稱家邦，不出門庭，而聲播諸華矣，弱冠而應式叙，起家而君斯民，其為政也，同励秋霜，等惠春仁，刑不濫疏，賞不僣親，儀天地之簡易，則大道之清純，是以其道易行，其教易遵也，凡我士民，襁老携幼，惴惴而懷君之恩，顒顒而恋君之德，相與援衡軒而雨涕，若赤子於父母也，明明君侯，臨下有赫，克隆有光，惠我咫尺，於以具瞻，有觀其宅，乃冰其清，乃玉其白，風抗其高，雲垂其泽，宛荆未清，淮夷孔炽，春日萋萋，我車既備，光光我君，爰登其司，微微襄魯，有坰［原作〈土四〉，據冯校本改。］斯記，君有遺愛，民有餘思，敢扬斯頌，垂之來志。","sortOrder":148},
  {"id":"s_work_nvlt_50_149","chapterId":"ch_work_nvlt_50","text":"【贊】晉孫綽孔松楊象贊曰：君德器純固，基宇高邃，荆玉不及喻其溫，南金未能方其励，夫其溫恭篤誠，善誘勤勸，外身崇物，非躬厚人，指捴必謙，動靜克讓，允有古賢之風流，乃祖之遺人矣，肇階方尺，臨政弊邑，絜齊冬冰，泽侔春露，於穆我後，含和體純，行范乃祖，德冠搢紳，降跡垂化，泽侔三春，超然遐舉，遺愛在民。","sortOrder":149},
  {"id":"s_work_nvlt_50_150","chapterId":"ch_work_nvlt_50","text":"晉孫楚梁令孫侯頌曰：於穆君侯，英才宣朗，神鑒將來，思通既往，受佐陝西，臨我邦壤，聲之所振，下應如响，明斷决疑，易於指掌，野有寇盜，惟侯屏之，我有田畴，惟侯辟之，古人慎獄，惟侯平之，凡此三惠，如何勿思。","sortOrder":150},
  {"id":"s_work_nvlt_50_151","chapterId":"ch_work_nvlt_50","text":"【啟】梁任孝恭辭縣啟曰：但以執笏丹墀，累飛庭葉，垂纓禁里，屢改欄花，顧慕階墀，不原违奉，不使恋主之心，施於犬馬，傾日之志，偏在葵藿。","sortOrder":151},
  {"id":"s_work_nvlt_50_152","chapterId":"ch_work_nvlt_50","text":"梁劉孝儀除建康令謝啟曰：所恐長安少年，易為操彈，渭城遊徼，矜其獨勇，清路道奴，固知難摺，輕綏飛駕，且見為榮。","sortOrder":152},
  {"id":"s_work_nvlt_50_153","chapterId":"ch_work_nvlt_50","text":"《藝文類聚》　唐·欧陽詢","sortOrder":153},
  {"id":"s_work_nvlt_51_1","chapterId":"ch_work_nvlt_51","text":"卷五十一封爵部據明本補","sortOrder":1},
  {"id":"s_work_nvlt_51_2","chapterId":"ch_work_nvlt_51","text":"○總載封爵親戚封功臣封遜讓封外戚封婦人封尊賢繼絕封","sortOrder":2},
  {"id":"s_work_nvlt_51_3","chapterId":"ch_work_nvlt_51","text":"◇總載封爵","sortOrder":3},
  {"id":"s_work_nvlt_51_4","chapterId":"ch_work_nvlt_51","text":"《周官》曰：王畿，其外方五百里，曰侯服。又其外方五百里，曰甸服。又其外方五百里，曰男服。又其外方五百里，曰采服。又其外方五百里，曰衛服。又其外方五百里，曰蠻服。又其外方五百里，曰夷服。又其外方五百里，曰镇服。又其外方五百里，曰蕃服。","sortOrder":4},
  {"id":"s_work_nvlt_51_5","chapterId":"ch_work_nvlt_51","text":"《呂氏春秋》曰：太公望封於齊，周公旦封於魯，二君者甚相善也，相謂曰：何以治國，太公望曰：尊賢上功，周公曰：親親上恩，太公曰：魯自此削矣，周公曰：魯雖削，有齊者亦必非呂氏也，其後齊日以大，至於霸，二十四世而田氏有齊國，魯日以削，至於仅，四十四世亡。","sortOrder":5},
  {"id":"s_work_nvlt_51_6","chapterId":"ch_work_nvlt_51","text":"《史記》曰：殷以前尚矣，周封五等，公侯伯子男，然封伯禽康叔於魯衛，地各四百，親親之義，褒有德也，太公兼五侯地，尊勤勞也，武王成康，所封數百，而同姓五十，地土［《太平御覽》一百九十八作上。］不過百里，下三十，以辅衛王室。","sortOrder":6},
  {"id":"s_work_nvlt_51_7","chapterId":"ch_work_nvlt_51","text":"又曰：騶忌見威王，王說之，三月而受相印，淳於髡見之曰：善說，既有愚志，原陳諸前，髡說畢，趨出，至門而面其仆曰：是人者，吾語之徵［太平御覽一百九十八作微。］言五，其應我若响之應聲，是必封不久矣。","sortOrder":7},
  {"id":"s_work_nvlt_51_8","chapterId":"ch_work_nvlt_51","text":"《漢書》曰：李廣與望氣王朔語曰：漢击匈奴，廣未嘗不在其中，而諸妄校尉已下，材能不及中人，以軍功取侯者數十人，廣不為後人，然終無尺寸功以得封邑者，何也，豈吾相不當侯耶，朔曰：將軍自念，豈嘗有所恨者乎，廣曰：吾為隴西太守，羌嘗反，吾誘降八百餘人，诈而同日殺之，至今恨獨此爾，朔曰：禍莫大殺已降，此乃將軍所以不得侯也。","sortOrder":8},
  {"id":"s_work_nvlt_51_9","chapterId":"ch_work_nvlt_51","text":"漢雜事曰：天子太社，以五色為壇，封諸侯者，取其土，苴以白茅，授之，各以所封方之色，以立社於其國，故謂之受茅土，漢興，唯皇子封為王者得茅土，其他臣，以戶賦租入為節，不受茅土，不立社。","sortOrder":9},
  {"id":"s_work_nvlt_51_10","chapterId":"ch_work_nvlt_51","text":"《東觀漢記》曰：上封功臣，皆為列侯，大國四縣，［原訛絲，據冯校本改。］餘各有差，博士丁恭等議，古帝王封諸侯，不過百里，故利以建侯，取法於雷，上曰：古之亡國，皆以無道，未嘗封功臣地多而滅者也，乃遣謁者，即授印綬。","sortOrder":10},
  {"id":"s_work_nvlt_51_11","chapterId":"ch_work_nvlt_51","text":"又曰：冯勤使典諸侯封事，勤差量功次輕重，國土遠近，地势丰王，不相逾越，莫不厭服焉，自是封爵之製，非勤不定","sortOrder":11},
  {"id":"s_work_nvlt_51_12","chapterId":"ch_work_nvlt_51","text":"《白虎通》曰：受命之王，致太平之美，群臣上下之功，故盡封之，及中興征伐，大功皆封，盛德之士亦封之，以德封者，必试之為附庸，三年有功，因而封之五十里，元士有功者，亦為附庸也，其位大夫有功，成封五十里，卿成封七十里，公成封百里。","sortOrder":12},
  {"id":"s_work_nvlt_51_13","chapterId":"ch_work_nvlt_51","text":"又曰：王者即位，先封賢者，忧民之急也，故列土分疆，非為諸侯，張官設府，非為卿大夫，皆為民也。","sortOrder":13},
  {"id":"s_work_nvlt_51_14","chapterId":"ch_work_nvlt_51","text":"《鹽鐵論》曰：昔太公封營丘之墟，辟草萊而居焉，地薄人少，於是通利末之道，極女工之功，是以鄰國交於齊，财畜货殖，世為彊國，管仲相桓公，袭先君業，輕重之变，南服彊楚，而霸諸侯，袁子曰：今有卿相之才，居三公之位，修其治政，以寧國家，未必封侯也，今軍政之法，斬一牙門將者封侯，夫斬一將之功，孰與安寧天下者乎，夫斬一將之功者封侯，失封賞之意也。","sortOrder":14},
  {"id":"s_work_nvlt_51_15","chapterId":"ch_work_nvlt_51","text":"《相書》曰：天中容半印，封侯。","sortOrder":15},
  {"id":"s_work_nvlt_51_16","chapterId":"ch_work_nvlt_51","text":"又曰：天中正舀如刀者，封侯。","sortOrder":16},
  {"id":"s_work_nvlt_51_17","chapterId":"ch_work_nvlt_51","text":"《周易》曰：我有好爵，吾與爾靡之。","sortOrder":17},
  {"id":"s_work_nvlt_51_18","chapterId":"ch_work_nvlt_51","text":"《左傳》曰：齊莊公為勇爵，殖倬郭最欲與焉，州綽曰：東闾之役，臣左驂迫，還於門中，識其枚數，其可以與乎，公曰：子為晉君也，對曰：臣為隸新。","sortOrder":18},
  {"id":"s_work_nvlt_51_19","chapterId":"ch_work_nvlt_51","text":"《管子》曰：爵不尊，祿不重者，不與圖難犯危，以其道為未可以求之也，是故先王製軒冕，足以著貴賤，不求其美，設爵祿，足以守其服，不求其親，使君子食於道，小人食於力。","sortOrder":19},
  {"id":"s_work_nvlt_51_20","chapterId":"ch_work_nvlt_51","text":"《孟子》曰：有天爵，有人爵，仁義忠信，樂善不倦，此天爵也，公卿大夫，此人爵也，古之人，脩其天爵，而人爵從之，脩其天爵，以要人爵，既得人爵，而弃其天爵，則惑之甚者也。","sortOrder":20},
  {"id":"s_work_nvlt_51_21","chapterId":"ch_work_nvlt_51","text":"《商君書》曰：明主之所貴唯爵，爵賞不榮，其民不急，列爵不顯，則民不事，爵易得，則民不貴祿，賞不道，則民不以死爭位也。","sortOrder":21},
  {"id":"s_work_nvlt_51_22","chapterId":"ch_work_nvlt_51","text":"又曰：凡人主之所以勸民者，官爵也，國之所以興者，農戰也，今民求官爵，皆不農戰，而以功言虛道，此謂勞民者，其國必削。","sortOrder":22},
  {"id":"s_work_nvlt_51_23","chapterId":"ch_work_nvlt_51","text":"周官禮曰：諸公之地，封疆方五百里，其食者半。","sortOrder":23},
  {"id":"s_work_nvlt_51_24","chapterId":"ch_work_nvlt_51","text":"又曰：公執桓圭。","sortOrder":24},
  {"id":"s_work_nvlt_51_25","chapterId":"ch_work_nvlt_51","text":"又曰：諸侯之地，封疆方四百里，其食者三之一。","sortOrder":25},
  {"id":"s_work_nvlt_51_26","chapterId":"ch_work_nvlt_51","text":"又曰：諸侯諸伯七命，其國家宮室，車旗衣服禮儀，皆以七為節。","sortOrder":26},
  {"id":"s_work_nvlt_51_27","chapterId":"ch_work_nvlt_51","text":"又曰：侯用信圭。","sortOrder":27},
  {"id":"s_work_nvlt_51_28","chapterId":"ch_work_nvlt_51","text":"又曰：諸伯之地，封疆方三百里，其食者四之一。","sortOrder":28},
  {"id":"s_work_nvlt_51_29","chapterId":"ch_work_nvlt_51","text":"又曰：伯用躬圭。","sortOrder":29},
  {"id":"s_work_nvlt_51_30","chapterId":"ch_work_nvlt_51","text":"又曰：諸子之地，封疆方二百里，其食者四之一。","sortOrder":30},
  {"id":"s_work_nvlt_51_31","chapterId":"ch_work_nvlt_51","text":"又曰：子男五命，其國家宮室，車旌衣服禮儀，皆以五為節。","sortOrder":31},
  {"id":"s_work_nvlt_51_32","chapterId":"ch_work_nvlt_51","text":"又曰：子執穀璧。","sortOrder":32},
  {"id":"s_work_nvlt_51_33","chapterId":"ch_work_nvlt_51","text":"又曰：諸男之地，封疆方百里，其食者四之一。","sortOrder":33},
  {"id":"s_work_nvlt_51_34","chapterId":"ch_work_nvlt_51","text":"又曰：男執蒲璧。","sortOrder":34},
  {"id":"s_work_nvlt_51_35","chapterId":"ch_work_nvlt_51","text":"百官表註曰：五等諸公，周官，金章朱綬，朱质四采玄文，織百四十首，廣尺四寸，長一丈六尺，朝服，進賢三梁冠，官品第二，地方七十五里，位视三公班次，邑三千八百戶，國秩絹千八百匹，妾六人，車前司馬十四人，旅贲五十人。","sortOrder":35},
  {"id":"s_work_nvlt_51_36","chapterId":"ch_work_nvlt_51","text":"又曰：縣侯，漢官也，自縣侯而下，通號列侯，金章紫綬，朝服，進賢三梁冠，官品第三，光武中興論功，封大功臣吳漢邓禹各四縣，贾复朱浮三縣，耿弇等二十九人，［句有脱文。］","sortOrder":36},
  {"id":"s_work_nvlt_51_37","chapterId":"ch_work_nvlt_51","text":"又，縣侯有家丞庶子之官，列侯皆亦如之。","sortOrder":37},
  {"id":"s_work_nvlt_51_38","chapterId":"ch_work_nvlt_51","text":"漢官解詁曰：列侯，金印紫綬，以賞其有功，功大者食縣邑，小者食乡亭，得臣其所食吏民，本為彻侯，避武帝讳曰通侯，舊時文書，或爵通侯是也，後更曰列侯，今俗人或都言諸侯，乃王爾，非此也，列侯歸國，不受茅土，不立宮室，各隨貧富。","sortOrder":38},
  {"id":"s_work_nvlt_51_39","chapterId":"ch_work_nvlt_51","text":"環濟要略曰：爵有五等，公者無人［疑當作晻。］也，故文比么［疑當作北晻。］為公。","sortOrder":39},
  {"id":"s_work_nvlt_51_40","chapterId":"ch_work_nvlt_51","text":"又曰：伯，把也，持政事也。","sortOrder":40},
  {"id":"s_work_nvlt_51_41","chapterId":"ch_work_nvlt_51","text":"又曰：子猶孳孳，恤下之稱也。","sortOrder":41},
  {"id":"s_work_nvlt_51_42","chapterId":"ch_work_nvlt_51","text":"又曰：男，任也，任治事，受王命為君也。","sortOrder":42},
  {"id":"s_work_nvlt_51_43","chapterId":"ch_work_nvlt_51","text":"《周書》曰：能移於眾，與百姓同，謂之公。","sortOrder":43},
  {"id":"s_work_nvlt_51_44","chapterId":"ch_work_nvlt_51","text":"又曰：能树名生物，與天道俱，謂之侯。","sortOrder":44},
  {"id":"s_work_nvlt_51_45","chapterId":"ch_work_nvlt_51","text":"謚法曰：執應八方曰侯。","sortOrder":45},
  {"id":"s_work_nvlt_51_46","chapterId":"ch_work_nvlt_51","text":"《孝經援神契》曰：侯候也，所以守蕃也。","sortOrder":46},
  {"id":"s_work_nvlt_51_47","chapterId":"ch_work_nvlt_51","text":"【詔】梁任昉初封諸功臣詔曰：草昧權舆，事深締構，康俗成務，義在庇民，自非群才併軌，文武宣翼，將何以啟茲景祚，弘此帝圖，或運筹帷帳，經啟王業，或攻城略野，殉義忘生，或股心爪牙，折冲御侮，忠勤茂德，夷险一致，併宜建國开宇，蕃屏王室，山河之誓，永永無窮。","sortOrder":47},
  {"id":"s_work_nvlt_51_48","chapterId":"ch_work_nvlt_51","text":"【論】後魏王粲爵論曰：依律有奪爵之法，此謂古者爵行之時，民賜爵則喜，奪爵則懼，故可以奪賜而法也，今爵事废矣，民不知爵者何也，奪之民亦不懼，賜之民亦不喜，是空設文書而無用也，今誠循爵，則上下不失實，而功勞者勸，得古之道，合漢之法，以货财為賞者，不可供，以复除為賞者，租稅損减，以爵為賞者，民勸而費省者，故古人重爵也。","sortOrder":48},
  {"id":"s_work_nvlt_51_49","chapterId":"ch_work_nvlt_51","text":"晉陆機五等論曰：五等之製，始於黃唐，郡縣之治，創自秦漢，得失成败，備在典謨，是以其詳可得而言，夫先王知帝業至重，天下至廣，廣不可以偏製，重不可以獨任，任重必於借力，製廣終乎因人，於是乎立其封疆之典，财其親疏之宜，使萬國相維，以成盤石之固，宗庶雜居，而定維城之業，知其為人不如厚己，利物不如圖身，安上在於悅下，為己在乎利人，是以分天下以厚樂，而己得與之同忧，饗天下以丰利，而我得與之共害，故諸侯享食土之實，萬國受世及之祚，夫然，則南面之君，各務其治，世治足以敦風，道衰足以御暴，故彊毅之國，不能擅一時之势，雄俊之民，無所寄霸王之志，降及亡秦，弃道任術，懲周之失，自矜其得，尋斧始於所庇，製國昧於弱下，國慶獨饗其利，主忧莫與共害，雖速亡趣亂，不必一道，顛沛之衅，實由孤立，是蓋思五等之小怨，忘經國之大德，知陵夷之可患，闇土崩之為痛，漢矯秦枉，大啟侯王，境土逾溢，不遵舊典，是以諸侯阻其國家之富，凭其士民之力，势足者反疾，土狹者逆遲，六臣犯其弱綱，七子冲其漏網，皇祖夷於黥徒，西京疾於東帝，是蓋過正之灾，而非建侯之累也。","sortOrder":49},
  {"id":"s_work_nvlt_51_50","chapterId":"ch_work_nvlt_51","text":"◇親戚封","sortOrder":50},
  {"id":"s_work_nvlt_51_51","chapterId":"ch_work_nvlt_51","text":"《左氏傳》曰：太上以德撫民，其次親親，以相及也，昔周公弔二叔之不鹹，故封親戚，以蕃屏周，管蔡郕霍，魯衛毛聃，郜雍魯滕，畢原酆郇，文之昭也，邗晉應韓，武之穆也，凡將邢茅胙祭，周公之胤也。","sortOrder":51},
  {"id":"s_work_nvlt_51_52","chapterId":"ch_work_nvlt_51","text":"《毛詩》曰：乃命魯公，俾侯於東，錫之山川，土田附庸。","sortOrder":52},
  {"id":"s_work_nvlt_51_53","chapterId":"ch_work_nvlt_51","text":"又曰：奄有龟蒙，遂荒大東，至於海邦，淮夷來同。","sortOrder":53},
  {"id":"s_work_nvlt_51_54","chapterId":"ch_work_nvlt_51","text":"《史記》曰：成王與叔虞戲，削桐葉為珪，予虞，曰：以唐封汝，史佚因言，請擇日立叔虞，成王曰：吾與之戲耳，史佚曰：天子無戲言，言則史書之，禮成之，樂歌之，於是遂封叔虞於唐。","sortOrder":54},
  {"id":"s_work_nvlt_51_55","chapterId":"ch_work_nvlt_51","text":"《漢書》曰：漢興之初，尊王子弟，大啟九國，京師內史，凡十五郡，公主列侯，頗邑其中，蕃國大者，跨州兼郡，連城數十，宮室百官，同製京師，諸呂之難，賴於諸侯也。","sortOrder":55},
  {"id":"s_work_nvlt_51_56","chapterId":"ch_work_nvlt_51","text":"《孟子》曰：象至不仁，封諸有庳，仁人之於其弟也，不藏怒焉，不宿怒焉，親愛之而已矣，親之欲其貴，愛之欲其富也，封之有庳者，富貴之也，身為天子，弟為匹夫，可謂親愛之乎。","sortOrder":56},
  {"id":"s_work_nvlt_51_57","chapterId":"ch_work_nvlt_51","text":"【詔】魏明帝詔曰：古之帝王，封建諸侯，所以蕃屏王室也，詩不雲乎，懷德惟寧，宗子維城，秦漢繼周，或強或弱，俱失厥中，大魏創業，諸王开國，隨時之宜，未有定製，非所以永為後法也，其改封諸王，皆以郡為國，梁任昉武帝追封永陽王詔曰：亡兄德履濘粹，識業深通，徽聲善譽，風流籍甚，道長世短，清尘緬邈，感惟既往，永慕恸心，可追封永陽郡王。","sortOrder":57},
  {"id":"s_work_nvlt_51_58","chapterId":"ch_work_nvlt_51","text":"又追封丞相長沙王詔曰：夫褒崇名器，率由舊章，光昭德祀，永世作則，亡兄道被如仁，功深微管，懸諸日月，久而弥新，故能拯龟玉於已毀，导涸源於將塞，今理運惟新，賢戚併建，感惟永遠，觸目崩心，可追封長沙郡王。","sortOrder":58},
  {"id":"s_work_nvlt_51_59","chapterId":"ch_work_nvlt_51","text":"又追封衡陽王桂陽王詔曰：亡弟畅，風摽秀物，器體淹弘，朱方之役，盡勤王事，策出無方，物惟不賞，亡弟融，業行清簡，風度閒綽，蚤優名辈，夙廣令聞，朕應天紹命，君臨萬寓，祚啟郇滕，感興魯衛，事往運來，永懷傷切，畅可追封衡陽郡王，融可南陽郡王。","sortOrder":59},
  {"id":"s_work_nvlt_51_60","chapterId":"ch_work_nvlt_51","text":"又封臨川安興建安等五王詔曰：神州帝城，冠冕列嶽，渚宮樊邓，形勝是歸，居中作衛，翼宣戎重，隆茲寵號，寔允舊章，併非親勿居，惟賢斯授，宏朕之介弟，早富德譽，董一蕃政，緝是嘉庸，國禮家情，瞻寄隆重，季風穎俊邁，誠業摽簡，任居蕃翰，政以化成，伟體韻淹穆，神宇凝正，經纶夷险，參贊王業。","sortOrder":60},
  {"id":"s_work_nvlt_51_61","chapterId":"ch_work_nvlt_51","text":"陳徐陵始興王詔曰：漢祖天倫，伯叔追封，晉元世系，琅邪傳國，仰惟二後重光，率由前典，朕昔因蕃次，蒙繼本宗，分在要荒，久離寒燠，天嘉紹祚，別命皇枝，歸自崤函，禮隔登獻，每至霜庭可履，矚垣寢而懷悲，風树鳴條，望章陵而增感，今嗣王乖德，獲罪慈訓，永言主奠，宜自朕躬，但國步時艱，皇基務切，复奉家業，升纂帝圖，重违情禮，言深哽恸，可以第二皇子升陵為始興王。","sortOrder":61},
  {"id":"s_work_nvlt_51_62","chapterId":"ch_work_nvlt_51","text":"【策】漢武帝使御史大夫策諸子立閎為齊王曰：於戲小子閎，受茲青社，朕承祖考，道惟稽古，建爾國家，封於東土，世為漢蕃辅，於戲念哉，共朕之詔，唯命不於常，人之好德，克明顯光，義之丕圖，俾為君子，無怠爾心，允執其中。","sortOrder":62},
  {"id":"s_work_nvlt_51_63","chapterId":"ch_work_nvlt_51","text":"又立子旦為燕王曰：小子旦，受茲玄社，建爾國家，封於北土。","sortOrder":63},
  {"id":"s_work_nvlt_51_64","chapterId":"ch_work_nvlt_51","text":"又立子胥為廣陵王曰：小子胥，受茲赤社，建爾國家，封於南土，戰戰兢兢，乃惠乃慎，無侗好佚，無邇小人。","sortOrder":64},
  {"id":"s_work_nvlt_51_65","chapterId":"ch_work_nvlt_51","text":"【章】魏陳王曹植改封陳王謝恩章曰：臣既弊陋，守國無效，自分削黜，以彰眾誡，不意天恩滂霈，润泽橫流，猥蒙加封，茅土既優，爵賞必重，非臣虛淺，所宜奉受，非臣灰身，所能報塞。","sortOrder":65},
  {"id":"s_work_nvlt_51_66","chapterId":"ch_work_nvlt_51","text":"又封二子為公謝恩章曰：詔書寺臣息男苗為高陽乡公，志為穆乡公，臣伏自惟，文無升堂廟勝之助，武無推鋒接刃之效，天時運幸，得生貴門，遇以親戚，少荷光寵，竊位列侯，榮曜當世，顧影慚形，流汗反侧，洪恩罔極，雲雨增加，既榮本幹，枝葉併蒙，苗志小竖，既顽且稚，猥荷列爵，併佩金紫，施崇一門，惠及父子。","sortOrder":66},
  {"id":"s_work_nvlt_51_67","chapterId":"ch_work_nvlt_51","text":"齊謝朓為宣城公拜章曰：惟天為大，日星度其象，謂地蓋厚，河嶽宣其氣，斯冕旒所以貞觀，袞職所以代終，慚下穆而上尊，豈南征而北怨，何以克詠九歌，載宣七德，銘彼旗裳，勒斯鍾鼎。","sortOrder":67},
  {"id":"s_work_nvlt_51_68","chapterId":"ch_work_nvlt_51","text":"【表】陳思王曹植謝初封安乡侯表曰：臣抱罪即道，忧惶恐怖，不知刑罪，當所限齊，陛下哀愍臣身，不聽有司所執，待之過厚，即日於延津受安乡侯印綬，奉詔之日，且懼且悲，懼於始违憲法，悲於不慎，速此貶退，上增陛下垂念，下遺大後見忧，臣自知罪深责重，受恩無量，精魂飛散，忘軀殒命，雲雲。","sortOrder":68},
  {"id":"s_work_nvlt_51_69","chapterId":"ch_work_nvlt_51","text":"又謝朓［字衍。］封甄［魏志曹植傳作鄄。］城王表曰：臣愚駑垢秽，才质疪下，過受陛下日月之恩，不能摧身碎首，以答陛下厚德，而狂悸發露，始幹天憲，自分放弃，抱罪終身，苟貪视息，無复睎幸，不悟聖恩，爵以非望，枯木生葉，白骨更肉，非臣罪戾，所當宜蒙，俯仰慚惶，五內戰悸，奉詔之日，悲喜參至，雖因拜章，陳答聖恩，下情未展。","sortOrder":69},
  {"id":"s_work_nvlt_51_70","chapterId":"ch_work_nvlt_51","text":"又轉封東阿王謝表曰：奉詔，太皇太後念雍丘下濕少桑，欲轉東阿，當合王意，可遣人按行，知可居否，奉詔之日，伏增悲喜，臣以無功，虛荷國恩，爵尊祿厚，用無益於時，脂車秣馬，志在黜放，［原訛於，據冯校本改。］不圖陛下，天父之恩，猥宣皇太後慈母之念遷之，陛下幸為久長計，聖旨惻隱，恩過天地，臣在雍丘，劬勞五年，左右罢怠，居業同定，園果萬株，枝條始茂，私情區區，實所重弃，然桑田無業，左右貧窮，食财餬口，形有裸露，臣聞古之仁君，必有弃國，以為百姓，况乃轉居沃土，人從蒙福，江海所流，無地不润，雲雨所加，無物不茂，若陛下念臣入從五年之勤，少見佐助，此枯木生華，白骨更肉，非臣之敢望也，飢者易食，寒者易衣，臣之謂矣。","sortOrder":70},
  {"id":"s_work_nvlt_51_71","chapterId":"ch_work_nvlt_51","text":"吳胡綜請立諸王表曰：受命之主，系天而王，建化垂統，為一代製，雖禮有損益，事有质文，至於崇建懿親，列土封爵，內蕃國朝，外镇天下，古今同契，其揆一也，周室之興，寵秩子第，姬姓之國，五十有五，諸王子受國者漸多，光武中興，四海扰攘，眾諸製度未遍，而九子受國，明章即位，男則封王，女為公主，故詩曰：既受帝祉，施於子孫，陛下踐阼以來，十有二載，皇後無號，公主無邑，臣下叹息，遠近失望，是以屢獻愚懷，依據典禮，庶請具陳，足寤聖心，深辭固拒，不蒙進納，恐天下有識之士，將謂吳臣闇於禮製，不知陛下謙以失之也，加今仰夏，盛德在上，大吳之慶，於是乎始，开國建號，吉莫大焉，唯陛下割謙謙之德，副兆民之望，留臣祐許，天下幸甚。","sortOrder":71},
  {"id":"s_work_nvlt_51_72","chapterId":"ch_work_nvlt_51","text":"晉孫毓贺封諸侯王表曰：臣聞軒轅二十五宗，黃祚以繁，姬姓建國七十，周過其歷，故御侮莫如同德，伏惟陛下，聖哲钦明，稽乾作則，超五越三，與靈协契，天祚明德，克昌祚胤，秦王楚王淮南王，光濟硕美，冠於群後，改建大國，分镇方嶽，皇太子皇孫，併啟土宇，培敦潼索，製弘往代，內翰皇畿，外蕃九服，群生仰德，向風懷義，率土臣妾，莫不稱慶。","sortOrder":72},
  {"id":"s_work_nvlt_51_73","chapterId":"ch_work_nvlt_51","text":"梁任昉為萧侍中拜袭封表曰：詔書拜臣袭封竟陵郡王，臣以凡庸，素乏才植，皇朝尚德，詔爵惟賢，遂复出脩職貢，人頒卿士，但有道之守，海外重扃，蕃篱近甸，無勞击柝，仰閱舊章，俯增私感，報國承家，豈雲萬一。","sortOrder":73},
  {"id":"s_work_nvlt_51_74","chapterId":"ch_work_nvlt_51","text":"【奏】宋傅亮尚書八座封諸皇弟皇子奏曰：臣聞懿親廣树，聖王所先，明德併建，古之休典，所以維城皇代，盤石帝基，內衛畿服，外綏四海者也，第某皇弟皇子等，神姿穎哲，大成俱茂，地均魯衛，德兼庸賢，顯進徽號，啟建疆宇，弘道作屏，光翰邦家，併可封郡王。","sortOrder":74},
  {"id":"s_work_nvlt_51_75","chapterId":"ch_work_nvlt_51","text":"宋謝莊為尚書八座封皇子郡王奏曰：臣聞桐珪睦親，書河汾之策，賜帶懷賢，敬東平之祚，谅以訓經終始，義洽垣墉，第某皇弟等，器彩明敏，令識穎悟，併宜憲章前典，光啟祚宇，作屏王室，式雍帝載，臣等參議，可封郡王。","sortOrder":75},
  {"id":"s_work_nvlt_51_76","chapterId":"ch_work_nvlt_51","text":"◇功臣封《周官》曰：司勋，掌六乡賞地之法，以等其功，王功曰勋，國功曰功，事功曰勞，治功曰力，戰功曰多，凡有功者，銘書於王之太常。","sortOrder":76},
  {"id":"s_work_nvlt_51_77","chapterId":"ch_work_nvlt_51","text":"《史記》曰：古之人臣，功有五品，以德立宗廟，定社稷，曰勋，以言勞用力曰功，明其等曰伐，積曰閱。","sortOrder":77},
  {"id":"s_work_nvlt_51_78","chapterId":"ch_work_nvlt_51","text":"又曰：武王克紂，太公之謀居多，於是武王封尚父於齊營丘，成王少時，管蔡作亂，淮夷叛周，乃使召康公命太公，東至海，西至河，南至穆陵，北至無棣，五侯九伯，實得征之，齊由此征伐，大於諸國。","sortOrder":78},
  {"id":"s_work_nvlt_51_79","chapterId":"ch_work_nvlt_51","text":"又曰：召公奭，與周同姓，武王之滅紂，封召公於燕，其在成王時，自陝以西，召公主之，自陝而東，周公主之。","sortOrder":79},
  {"id":"s_work_nvlt_51_80","chapterId":"ch_work_nvlt_51","text":"又曰：鬻熊事周文王，早卒，當成王之時，舉文武勤勞之嗣，乃封其後熊繹於楚。","sortOrder":80},
  {"id":"s_work_nvlt_51_81","chapterId":"ch_work_nvlt_51","text":"又曰：晉獻公伐霍耿魏，滅之，因以魏封畢萬為大夫，卜偃曰：畢萬之後必大，萬，盈數也，魏，大名也，以是始賞，天啟之也。","sortOrder":81},
  {"id":"s_work_nvlt_51_82","chapterId":"ch_work_nvlt_51","text":"又曰：陳完奔齊，懿仲欲妻之，卜之吉，曰：是謂鳳皇於飛，和鳴锵锵，有妫之後，將育於薑，五世其昌，併於正卿，八世之後，莫之與京，卒妻之，完卒，謚為敬仲，六世而至田常，田常弒簡公，立簡公弟為平公，乃割齊安平以東，為己封邑，始大於齊。","sortOrder":82},
  {"id":"s_work_nvlt_51_83","chapterId":"ch_work_nvlt_51","text":"《漢書》曰：漢五年，剋項，天下乃平，始論功，侯者百四十有三人，時人民散亡，大侯不過萬戶，封爵之誓曰：使黃河如帶，太山如砺，於是申以丹書之信，重以白馬之盟，藏諸宗廟，副在有司。","sortOrder":83},
  {"id":"s_work_nvlt_51_84","chapterId":"ch_work_nvlt_51","text":"又曰：陳平凡六出奇計，辄益封，凡六益家。","sortOrder":84},
  {"id":"s_work_nvlt_51_85","chapterId":"ch_work_nvlt_51","text":"又曰：高祖封項伯等四人為列侯，賜姓劉氏。","sortOrder":85},
  {"id":"s_work_nvlt_51_86","chapterId":"ch_work_nvlt_51","text":"又曰：項羽曰：吾聞漢購我頭千金，邑萬戶，吾為公得之，乃自刭，［原訛钊，據冯校本改。］王翳取其頭，扬喜呂馬童郎中呂勝楊武，各得一體，故分其地以封五人，皆列侯。","sortOrder":86},
  {"id":"s_work_nvlt_51_87","chapterId":"ch_work_nvlt_51","text":"《東觀漢記》曰：上謂耿丹曰：今關東故王國，雖數，［《太平御覽》二百數下有縣字。］不過櫟陽萬戶邑，夫富貴不歸故乡，如衣繡夜行，故以封卿爾。","sortOrder":87},
  {"id":"s_work_nvlt_51_88","chapterId":"ch_work_nvlt_51","text":"又封窦融曰：率厲五郡積［《東觀漢記》作精。］兵，羌胡畢至，兵不血刃，而虜土崩瓦解，功既大矣，篤意分明，斷之不疑，吾甚嘉之，其以六安［《東觀漢記》二字無。］安丰陽泉蓼安風四縣，封融為安丰侯。","sortOrder":88},
  {"id":"s_work_nvlt_51_89","chapterId":"ch_work_nvlt_51","text":"又曰：三辅豪杰，入長安，攻未央宮，庚戌，殺莽於漸台，東海公賓就得其首，傳詣宛，封滑侯。","sortOrder":89},
  {"id":"s_work_nvlt_51_90","chapterId":"ch_work_nvlt_51","text":"又曰：班超定西域五十餘國，乃封超為定遠侯。","sortOrder":90},
  {"id":"s_work_nvlt_51_91","chapterId":"ch_work_nvlt_51","text":"《魏志》曰：夏侯惇，文帝追思惇功，欲使子孫畢侯，分邑千戶，賜惇七十二孫，皆關內侯，惇弟廉，及子楙，素列侯。","sortOrder":91},
  {"id":"s_work_nvlt_51_92","chapterId":"ch_work_nvlt_51","text":"又，曹真，字子丹，以功封邵陵侯，曹真少與宗人曹遵，乡人朱贊，併事太祖，早亡，真愍之，乞分食邑，封遵等子，曰：大司馬有叔向撫孤之仁，晏平久要之分，聽分賜遵等子爵關內侯，及真薨，明帝悉封真五子皆列侯。","sortOrder":92},
  {"id":"s_work_nvlt_51_93","chapterId":"ch_work_nvlt_51","text":"又曰：太祖表封荀彧為萬歲亭侯，太祖又與彧書曰：君之相匡弼，君之相為舉人，君之相與建計，君之相密謀，亦已多矣，大功未必野戰也，十二年，复增邑，合二千戶。","sortOrder":93},
  {"id":"s_work_nvlt_51_94","chapterId":"ch_work_nvlt_51","text":"又曰：大祖表封荀攸曰：前後剋敵，皆攸之謀也，於是封攸陵树亭侯。又曰：太祖自柳城還，過攸舍，稱攸前後謀曰：昔高祖使張子房，自擇齊三萬戶，今孤亦欲君自擇所封。","sortOrder":94},
  {"id":"s_work_nvlt_51_95","chapterId":"ch_work_nvlt_51","text":"又曰：郭嘉，字奉孝，冀州平，封洧陽亭侯，及薨，太祖表曰：良策未决，嘉軌成之，平定天下，謀功為高宜增邑，併前千戶。","sortOrder":95},
  {"id":"s_work_nvlt_51_96","chapterId":"ch_work_nvlt_51","text":"又曰：任峻，字伯遠，為典農中郎，大興屯田，軍國致饒，大祖以峻功高，表封都亭侯。","sortOrder":96},
  {"id":"s_work_nvlt_51_97","chapterId":"ch_work_nvlt_51","text":"又曰：朱靈，字文博，封鄃侯，文帝曰：將軍佐命先帝，威過方邵，平王所志，原勿難言，靈謝曰：高唐宿所原，乃更封高唐侯。","sortOrder":97},
  {"id":"s_work_nvlt_51_98","chapterId":"ch_work_nvlt_51","text":"【詔】後漢獻帝詔，敕镇東將軍領兖州牧費亭侯故特進，顯授上將，鈇鉞之任，复食舊土，双金之寵，董統一州，委成之重，榮曜昭示，亦以優崇，投節效命，自百之秋也。","sortOrder":98},
  {"id":"s_work_nvlt_51_99","chapterId":"ch_work_nvlt_51","text":"又詔書拜镇東將軍袭費亭侯曹操，業履忠貞，辅幹王室，頃遭凶暴，海內離析，操執義讨截黃巾，為國出命，夫祿以賞恭，罰以絀否，今以操為镇東將軍，領兖州牧，袭父費亭侯嵩爵，併印綬符策。","sortOrder":99},
  {"id":"s_work_nvlt_51_100","chapterId":"ch_work_nvlt_51","text":"魏文帝册孫權太子登為東中郎封侯文曰：蓋河洛寫天意，符讖述聖心，昭晰著明，與天談也，故易曰：河出圖，洛出書，聖人則之，孫將軍歸心國朝，忠亮之節，同功佐命，而其子當為魏將軍，著在圖讖，猶漢光武受命，李氏為辅，王梁孫鹹，併見符緯也，斯乃皇天啟祐大魏，永令孫氏仍世為佐，其以登為東中郎將，封縣侯萬戶，昔周嘉公旦，祚流七胤，漢禮萧何，一門十侯，今孫將軍亦當如斯，若夫長平之榮，安丰之寵，方斯蔑如，陳徐陵進武帝為長城公詔曰：德懋懋官，功懋懋賞，皇王盛則，所謂元龟，司空公南徐州刺史長城縣开國侯讳，志懷夤亮，風度弘遠，體文經武，明允篤誠，曩者率五嶺之彊兵，誅四海之讎敵，固以勒功彝鼎，書勋太常，克定京師，勤勞自重，自镇撫枌榆，永寧丰沛，東涼既息，北蔡無歸，代馬燕犀，氣雄天下，裹糧坐甲，固敵是求，方欲大讨於秦崤，敦脩於與睦，葉謀上相，爰納朕躬，思所以敬答忠勋，用申朝典，可進爵為長城縣公。","sortOrder":100},
  {"id":"s_work_nvlt_51_101","chapterId":"ch_work_nvlt_51","text":"【表】宋謝靈運謝封康樂侯表曰：昔強互［按當作氐。］暴虐，恃僣歷紀，既噬五都，志吞六合，遂陷没西河，傾覆南漢，凌籍紀郢，跨越淮泗，於時策盡惟疑，地险已謝，鹹懼君臣同泯，有生無餘，亡祖奉國威靈，董符戎重，盡心所事，剋黜禍亂，功參盤鼎，胙土南服，逮至臣身，值遭泰路，日月改暉，榮落代運，输稅唐化，生幸無已，不悟天道下濟，鸿均曲成，乃眷遐績，式是興徵，分虎钿［疑當作紐。］龟，复顯茅土，鳴玉拖绂，班景元勋，泽洽往德，恩覃來胤，永惟先蹤，遠感崩結，豈臣尫弱，所當忝承，臣聞至公無私，甄善則一，皇恩遠被，殊代可侔，是以信陵之賢，簡在高祖之心，望諸之道，复獲隆漢之封，觀史叹古，钦茲盛美，豈謂榮渥，近霑微躬，傾宗殒元，心識其會，酬恩答厚，罔知所由。","sortOrder":101},
  {"id":"s_work_nvlt_51_102","chapterId":"ch_work_nvlt_51","text":"宋顏延之謝子竣封建城侯表曰：伏見策書，降錫息竣开國建城縣侯，爵逾三等，戶越兼千，生邀洪禮，身茂盛世，阖宗革聽，盡室改觀，誠慚末品，誤參其泰，臣聞子之能仕，父教之忠，忠教善信，臣實負其前誥，能仕志政，竣固暗於明试，徒以數遇會昌，消忧啟聖，幸與靈祚福德，共從義勋分賞，執珪登朝，析金受邑，慶重慮愆，恩往懼積，非臣耄蔽，所任圖報，豈竣庸薄，所能奉服。","sortOrder":102},
  {"id":"s_work_nvlt_51_103","chapterId":"ch_work_nvlt_51","text":"梁沈約謝封建昌侯表曰：陛下投袂萬里，拯厥涂炭，臣雖心不吠尧，而跡淪桀犬，此則王業始基，臣所不與，徒荷日月之私，竟無蒸燭之用，天命玄鳥，非止今日，受命作周，其來久矣，雖复備數樂推，與同謳頌，而誠微弱草，效闕纖尘，遂班山河之誓，叨佐命之賞，亦何以慰悅帷帳，酬報爪牙。","sortOrder":103},
  {"id":"s_work_nvlt_51_104","chapterId":"ch_work_nvlt_51","text":"◇遜讓封","sortOrder":104},
  {"id":"s_work_nvlt_51_105","chapterId":"ch_work_nvlt_51","text":"《左氏傳》曰：會於戚，讨曹成公也，諸侯將見子臧於王而立之，子臧曰：前志有之曰：聖達節，次守節，下失節，為君非吾節也，遂逃奔宋。","sortOrder":105},
  {"id":"s_work_nvlt_51_106","chapterId":"ch_work_nvlt_51","text":"又曰：吳諸樊既除丧，將立季札，季札辭曰：曹宣公之卒，諸侯不義曹君，將立子臧，子臧去之，君子曰：能守節也，誰敢奸君，有國非吾節也，弃其室而耕。","sortOrder":106},
  {"id":"s_work_nvlt_51_107","chapterId":"ch_work_nvlt_51","text":"《韓子》曰：楚莊王既勝晉於河雍，歸而賞孫叔敖，叔敖請漢間之地，沙石之處，楚國之法，祿臣再世收，唯叔敖獨存九世，而祀不絕。","sortOrder":107},
  {"id":"s_work_nvlt_51_108","chapterId":"ch_work_nvlt_51","text":"《漢書》曰：韦賢薨，子玄成當為嗣，心知非賢，即乃佯狂，妄語笑，既葬，當袭爵，玄成素有名，疑其欲讓兄，遂奏劾之，玄成不得已，乃受侯爵。","sortOrder":108},
  {"id":"s_work_nvlt_51_109","chapterId":"ch_work_nvlt_51","text":"《東觀漢記》曰：窦融數辭爵位。又上疏曰：臣有一子，质性顽钝何况乃當傳以連城廣土，享諸侯之國哉，他日會見，遞［東觀漢記作迎。］詔曰：欲讓職還土，今相見，不宜論也。","sortOrder":109},
  {"id":"s_work_nvlt_51_110","chapterId":"ch_work_nvlt_51","text":"又曰：桓榮卒，子鬱當袭爵，讓於兄子，顯宗不許，不得已受封，而悉以租入與之。","sortOrder":110},
  {"id":"s_work_nvlt_51_111","chapterId":"ch_work_nvlt_51","text":"又曰：丁綝從上渡河，及封功臣，上今各言所樂，謂綝曰：諸將皆欲縣，子獨求乡，何也，綝曰：昔孫叔敖敕其子受封，必求蛇尧確之地，今綝能薄功微，得乡厚矣，上從之，封為定陵新安乡侯，後徙封陵陽侯。","sortOrder":111},
  {"id":"s_work_nvlt_51_112","chapterId":"ch_work_nvlt_51","text":"又曰：張純臨終，謂家丞曰：吾無功於時，猥蒙爵土，身死之後，勿議傳國爵，子奋，上詔奋嗣爵，奋稱純遺旨，固不肯受，帝以奋违詔，收下獄，奋乃袭封。","sortOrder":112},
  {"id":"s_work_nvlt_51_113","chapterId":"ch_work_nvlt_51","text":"又曰：帝欲封樊［《東觀漢記》作陰。］興，置印綬於前，興固讓曰：臣未有先登陷陣之功，而一家數人，併蒙爵土，今［《東觀漢記》，《太平御覽》二百零一作令。］天下觖望，上嘉興之讓，不奪其志。","sortOrder":113},
  {"id":"s_work_nvlt_51_114","chapterId":"ch_work_nvlt_51","text":"又曰：上欲封諸舅，馬太後辄斷絕曰：計之熟矣，有疑至孝之行，安親為上，今遭变異，穀价數倍，忧惶晝夜，不安坐臥，而欲封爵，违逆慈母之拳拳，吾素刚急，有胸中氣，不可不慎，穰歲之後，唯子之志，吾但當含飴弄孫，不能复知政。","sortOrder":114},
  {"id":"s_work_nvlt_51_115","chapterId":"ch_work_nvlt_51","text":"《魏志》曰：田畴從太祖入盧龍塞，太祖獨欲侯之，畴素與夏侯惇善，太祖語惇曰：且往以情喻之，答曰：豈可賣盧龍塞以易賞祿哉，縱國私畴，畴獨不愧於心乎，涕泣橫流，惇具答太祖，太祖喟然，知不可屈，乃拜為議郎。","sortOrder":115},
  {"id":"s_work_nvlt_51_116","chapterId":"ch_work_nvlt_51","text":"晉《起居註》曰：故南城侯羊祜，固辭歷年，志不可奪，身没讓存，遺操益厲，此亦夷齊所稱賢也，今聽复本封，以彰厥美。","sortOrder":116},
  {"id":"s_work_nvlt_51_117","chapterId":"ch_work_nvlt_51","text":"【表】齊謝朓為齊明帝讓封宣城公表曰：如其懸旌灞浐，刷馬伊穀，洒酒望屬車之尘，整笏侍升平之禮，陛下訏謨玄覽，钦若宏圖，鑒臣匪躬，共申彝訓，雖量能之請，近遂微躬，則弘長之風，足軌來世。","sortOrder":117},
  {"id":"s_work_nvlt_51_118","chapterId":"ch_work_nvlt_51","text":"梁簡文帝為子心［按心上當有大字。］讓當陽公表曰：月蚀之餘，無黃童之對，荷戟入榛，異子乌之辯，遂复早建茅社，夙开井賦，爵列五等，綬參四色。又帝為子大款讓石城公表曰：诡對鶴書，俯羞鹈翼，臣生處深宮，未觌焦原之险，不出戶庭，豈觀砥柱之峻，臣聞坳塘汎水，豈議大渎之流，覆匮為峰，終乖小魯之說。","sortOrder":118},
  {"id":"s_work_nvlt_51_119","chapterId":"ch_work_nvlt_51","text":"又為長子大器讓宣城王表曰：襄野之辯，尚對軒君，弘羊之計，猶幹漢主，徒以結慶璿源，乘荫霄極，一日千里，困騏骥之馳，高陰百尺，藉雲崖之遠，熙祖流聰慧之稱，方建臨淮之國，元仲表岐嶷之姿，［原訛妾，據冯校本改。］乃啟平原之封，南郡奧部，春穀名區，民化仲翔之俗，山峻陵陽之嶺，而绿車赤綬，交映相暉，金玺銀券，炤灼光彩。","sortOrder":119},
  {"id":"s_work_nvlt_51_120","chapterId":"ch_work_nvlt_51","text":"梁江淹為齊高帝讓進爵為王表曰：昔虞思勤夏，不別殊物之錫，晉叔臣周，豈頒上公之典，魯蕃懿親，裁蒙袞齊之榮，梁國戚屬，方忝旌旗之貴。","sortOrder":120},
  {"id":"s_work_nvlt_51_121","chapterId":"ch_work_nvlt_51","text":"梁任昉為齊明帝讓宣城郡公表曰：臣本庸才，智力淺短，太祖高皇帝，篤猶子之愛，降家人之慈，世祖武皇帝，情等布衣，寄深同氣，武皇大漸，實奉話言，雖自見之明，庸近所蔽，愚夫至此，已實不忍，自固於缀衣之辰，推违於玉幾之侧，遂荷原［疑當作顧。］讬，道扬末命，雖嗣君弃常，獲罪宣德，王室不造，職臣之由，何者，親則東牟，任惟博陆，徒懷子孟社稷之對，何救昌邑爭臣之譏，四海之議，於何逃责，且陵土未乾，訓誓在耳，家國之事，一至於斯，非臣之尤，誰任其咎，將何以肅拜高寢，虔奉武園，悼心失圖，泣血待旦，寧容复徼榮於愧恥，晏安於國危，且虛飾寵章，委成御侮，臣知不愜物，誰謂攸［冯校本作鹹。］宜，命輕鸿毛，责重山嶽，存没同歸，毀譽一貫，辭一官不减身累，增一職已黷朝經，便當自同體國，不為飾讓，至於功均一匡，賞同千里，光宅近甸，奄有全邦，殒越為期，弗敢聞命，亦原曲留降鑒，即垂順許，乃君臣之道，綽有餘裕，苟曰易照，敢守難奪。","sortOrder":121},
  {"id":"s_work_nvlt_51_122","chapterId":"ch_work_nvlt_51","text":"梁沈約為柳世隆讓封公表曰：臣聞懸旌玉塞，貳師尚黜其功，伐鼓炎州，伏波猶懼其賞，徒以兼委之施，或難固辭，抽心之情，必無双奪，是故俯容青閣，原還慈於裂壤，竊步丹墀，希收寵於开賦，昔竄命窮雉，難迫势孤，沈板未難，負戶非切，及顧溫青［全梁文二十七作清。］之馆，懼結尊慈之懷，累葉喁喁，舉門惴惴，臣事逼君親，理非外奖，實賴朝謨謹肅，宰略遐震，奔鯨外剿，臣何力焉，幸得扶老携弱，重出幽堵，還軸歸驂，再踐乡路，豈可資國眚以邀其功，因豕［全梁文作眾。］功而饗其報，遂使甘霜受電之心，有同於飾請，皎日大河之志，匪殊於濬謁。","sortOrder":122},
  {"id":"s_work_nvlt_51_123","chapterId":"ch_work_nvlt_51","text":"【書】魏武帝上書讓增封曰：無非常之功，而受非常之福，是用忧結比章，歸聞天慈無已，未即聽許，臣雖不敏，猶知讓不過三，所以仍布腹心，至於四五，上欲陛下爵不失實，下為臣身免於苟取。","sortOrder":123},
  {"id":"s_work_nvlt_51_124","chapterId":"ch_work_nvlt_51","text":"又上書讓封曰：臣誅除暴逆，克定二州，四方來貢，以為臣之功，萧相國以關中之勞，一門受封，邓禹以河北之勤，連城食邑，考功效實，非臣之勋，臣祖父中常侍侯，時但從輦，扶翼左右，既非首謀。又不奋戟，併受爵封，暨臣三葉，臣聞易豫卦曰：利建侯，行師有功，乃當進立以為諸侯也。又訟卦六三曰：食舊德，或從王事，謂先祖有大德，若從王事有功者，子孫乃得食其祿也，伏惟陛下，垂乾坤之仁，降雲雨之润，遠錄先臣扶掖之節，采臣在戎犬馬之用，優策褒崇，光曜顯量，非臣尫顽，所能克堪。","sortOrder":124},
  {"id":"s_work_nvlt_51_125","chapterId":"ch_work_nvlt_51","text":"又上書讓費亭侯曰：臣伏讀前後策命，既錄臣庸才微功，乃复追［原訛退，據冯校本改。］述先臣，幽贊顯扬，見得思義，屏營怖懼，未知首領，所當所授，故古人忠臣或有連城而不辭，或有一邑而违命，所以然者，欲必正其名也。又禮製，諸侯國土以絕，子孫有功者，當更受封，不得增袭，其有所增者，謂國未絕也，或有所袭者，謂先祖功大也，數未極，無故斷絕，故追紹之也，臣自三省，先臣雖有扶輦微勞，不應受爵，豈逮臣三葉，若錄臣關東微功，皆祖宗之靈祐，陛下之聖德，豈臣愚陋，何能克堪。","sortOrder":125},
  {"id":"s_work_nvlt_51_126","chapterId":"ch_work_nvlt_51","text":"又上書讓增封武平侯及費亭侯曰：伏自三省，姿质顽素，材志鄙下，進無匡辅之功，退有拾遺之美，雖有犬馬微勞，非獨臣力，皆由部曲將校之助，陛下前追念先臣微功，使臣續袭爵土，祖考蒙光照之榮，臣受不赀之分，未有絲發，以自報效，昔齊侯欲更晏婴之宅，婴曰：臣之先容焉，臣不足以繼之，卒违公命，以成私志，臣自顧省，不克負荷，食舊為幸，雖上德在弘，下有因割，臣三葉累寵，皆統極位，義在殒越，豈敢飾辭。","sortOrder":126},
  {"id":"s_work_nvlt_51_127","chapterId":"ch_work_nvlt_51","text":"◇外戚封","sortOrder":127},
  {"id":"s_work_nvlt_51_128","chapterId":"ch_work_nvlt_51","text":"《史記》曰：武帝衛後弟青，封長平侯，四子皆封侯，貴震天下，天下歌曰：生男無喜，生女勿怒，獨不見衛青子夫霸天下。","sortOrder":128},
  {"id":"s_work_nvlt_51_129","chapterId":"ch_work_nvlt_51","text":"《漢書》曰：漢興，外戚與定天下，侯者三人，後父據春秋襃紀之美，帝舅緣大雅申伯之恩，浸廣博矣。","sortOrder":129},
  {"id":"s_work_nvlt_51_130","chapterId":"ch_work_nvlt_51","text":"又曰：高祖封呂後父呂公為臨泗侯，兄泽為周呂侯。","sortOrder":130},
  {"id":"s_work_nvlt_51_131","chapterId":"ch_work_nvlt_51","text":"又曰：文帝封後弟薄昭為轵侯。又封齊淮南王舅驷鈞等二人為侯。","sortOrder":131},
  {"id":"s_work_nvlt_51_132","chapterId":"ch_work_nvlt_51","text":"又曰：景帝封太後弟侄窦廣國為章武侯，窦彭祖為南皮侯，窦婴以破吳楚功，封魏其侯，後弟王信為益靜侯。","sortOrder":132},
  {"id":"s_work_nvlt_51_133","chapterId":"ch_work_nvlt_51","text":"又，河平二年，上悉封舅谭為平阿侯，商成都侯，根曲陽侯，逢時高平侯，立紅陽侯，五人同日封，故世謂之五侯。","sortOrder":133},
  {"id":"s_work_nvlt_51_134","chapterId":"ch_work_nvlt_51","text":"又曰：武帝封太後同母弟田蚡為武安侯，勝周陽侯，皇後姊子［原訛乎，據冯校本改。］霍去病，伐匈奴，封冠軍侯。","sortOrder":134},
  {"id":"s_work_nvlt_51_135","chapterId":"ch_work_nvlt_51","text":"《東觀漢記》曰：馬防兄弟三人，各六千戶，防為穎陽侯，特以前參医藥勤勞，綏定西羌，以襄城羹亭一千二百戶增防，防身帶三綬，寵貴至盛。","sortOrder":135},
  {"id":"s_work_nvlt_51_136","chapterId":"ch_work_nvlt_51","text":"又，光武封新野王［後漢書五邓晨傳作主。］子邓泛為吳［後漢書吳下有房字，此脱。］侯，伯父皇皇考姊子周均為富波侯，追封外祖樊重為寿張侯，重子丹為射陽侯，孫茂為平望侯，彝［《東觀漢記》作尋。］乡［《東觀漢記》乡上有元字，此脱。］侯，從子冲更父侯，後父陰隆，［《東觀漢記》作睦。］宣陽侯，子識原鹿侯，就為信陽侯，皇考女弟子來歙征羌侯，弟由宜西侯，以寧平公主子李雄為新市侯，後父郭昌為陽安侯，子氵充綿曼侯，兄子竟新郪侯，匡發幹侯，以姨子冯邯為鍾離侯。","sortOrder":136},
  {"id":"s_work_nvlt_51_137","chapterId":"ch_work_nvlt_51","text":"又曰：明帝封太後弟陰興為鮦陽侯，子傅隱強侯，陰盛為無錫侯，楚王舅子許昌龍舒侯。","sortOrder":137},
  {"id":"s_work_nvlt_51_138","chapterId":"ch_work_nvlt_51","text":"又曰：邓訓自中興後，累世寵貴，凡侯者二十九人，東京莫比，《魏志》曰：文帝欲追封太後母父，尚書傅群議，自古無婦人分王命爵之製，秦违古法，漢氏因之，非先王之令典也，帝曰：此議是也。","sortOrder":138},
  {"id":"s_work_nvlt_51_139","chapterId":"ch_work_nvlt_51","text":"【表】晉庾亮讓封公表曰：觀聖賢之於名爵，敬戒之甚重，豈先哲宜重之於古，而聖朝可輕之於今耶，譬猶回太陽以消湛露，運沧海以灌燎火，其功易成，其事易立。","sortOrder":139},
  {"id":"s_work_nvlt_51_140","chapterId":"ch_work_nvlt_51","text":"◇婦人封","sortOrder":140},
  {"id":"s_work_nvlt_51_141","chapterId":"ch_work_nvlt_51","text":"《左傳》曰：晉败齊師，齊侯遂自徐關入，見保者曰：勉之，齊師败矣，嬖子女子曰：君免乎，曰：免，銳司徒免乎，曰：免矣，苟君與吾父免矣，可若何，乃奔，齊侯以為有禮，既而問之，辟司徒之妻也，封之石窌。","sortOrder":141},
  {"id":"s_work_nvlt_51_142","chapterId":"ch_work_nvlt_51","text":"陳留風俗傳曰：封丘者，高祖與項氏戰，厄於延乡，有翟母者免其難，故以延乡為封丘縣，以封翟母焉。","sortOrder":142},
  {"id":"s_work_nvlt_51_143","chapterId":"ch_work_nvlt_51","text":"【表】魏陳王曹植謝妻改封表曰：玺書今以東阿王妃為陳王妃，併下印，綬因故，上前所假印，以其拜授書以即日到，臣辄奉詔拜，其才质底下，谬同受私，遇寵素餐，臣為其首，陛下體乾坤育物之德，東海含容之大，乃後隨例，顯封大國，光扬章灼，非臣負薪之才，所宜克當，非臣秽衅，所宜蒙獲，夙夜忧叹，念報罔極，洪施遂隆，既榮枝幹，猥复正臣妃為陳妃，熠燿宣朗，非妾婦憃愚，所當蒙被，葵藿草物，猶感恩養，况臣含氣，衔佩弘惠，没而後已，誠非翰墨屢辭，所能報答。","sortOrder":143},
  {"id":"s_work_nvlt_51_144","chapterId":"ch_work_nvlt_51","text":"梁沈約謝母封建昌國太夫人表曰：伏見詔書，以臣母封為建昌國太夫人，慶溢蓬門，榮流素族，恭荷屏營，罔識攸窴，臣禀訓私閨，志涂靡立，勉以為義，誠有由然，输力致身，曾無萬一，天慈罔已，至德弥光，探其私志，降此洪泽，榮親之至，始自微臣，率斯道也，方流萬物，草卉輕命，固莫雲酬。","sortOrder":144},
  {"id":"s_work_nvlt_51_145","chapterId":"ch_work_nvlt_51","text":"又為長城公主謝表曰：奉策書，封妾為長城縣公主，徽命降臨，慚腆妄窴，妾膺靈禀氣，育景璇閨，弱志易淪，柔德難树，雖复式脩姆保，莫敢或遑，而肅雍不著，秾華蓋闕，不悟宸暉曲漸，彝章夙贲，籍此恩加，遽延典策，湯沐光啟，珩绲昭被。","sortOrder":145},
  {"id":"s_work_nvlt_51_146","chapterId":"ch_work_nvlt_51","text":"梁王僧孺為南平王妃拜改封表曰：拜妾為南平王妃，奉命震慚，有灼丹寸，妾瞻絲望帨，且或多慚，鏡史觀圖，是焉知愧，以茲眇薄，有俪蕃儀，紃組不聞，饘酡蓋闕，不悟玄造曲被，徽渥愈臻，改服遞名，事華品貴，恩深外邸，榮照下庭，豈期輶弱，所能勝荷。","sortOrder":146},
  {"id":"s_work_nvlt_51_147","chapterId":"ch_work_nvlt_51","text":"【表】宋謝莊為尚書八座改封郡長公主奏曰：臣聞爵厚懿戚，國之恒典，景祚既新，禮與時渥，永興等七公主，可封郡長公主。","sortOrder":147},
  {"id":"s_work_nvlt_51_148","chapterId":"ch_work_nvlt_51","text":"◇尊賢繼絕封","sortOrder":148},
  {"id":"s_work_nvlt_51_149","chapterId":"ch_work_nvlt_51","text":"《禮記》曰：天子存二代之後，猶尊賢，尊賢不過二代，武王克殷，未及下車，而封黃帝之後於蓟，而封夏後氏之後於杞，殷之後於宋。","sortOrder":149},
  {"id":"s_work_nvlt_51_150","chapterId":"ch_work_nvlt_51","text":"《左傳》曰：鄭子產曰：昔虞過［左傳襄二十五年作閼。］父為陶正，以服事我先王，先王賴其利器用，與其神明之後也，庸以元女太姬配胡公，而封諸陳，以備三恪。","sortOrder":150},
  {"id":"s_work_nvlt_51_151","chapterId":"ch_work_nvlt_51","text":"《史記》曰：高帝過趙，問樂毅有後乎，得樂臣叔，封之嚣乡，號華成君，成君毅之孫也。","sortOrder":151},
  {"id":"s_work_nvlt_51_152","chapterId":"ch_work_nvlt_51","text":"《漢書》曰：自古受命及中興之君，必興滅繼絕，修废舉逸，然後天下歸仁，四方之政行焉，傳稱武王克殷，追存賢聖，至乎不及下車，世代雖殊，其揆一也，高祖拨亂，日不暇給，然猶脩祀六國，求［原訛永，據冯校本改。］聘四皓，過魏則寵無忌之墓，適趙則封樂毅之後，孝武畴咨前代，初得周後，复知［漢書十八作加。］爵邑，元成之間，晚得殷世，以備賓位。","sortOrder":152},
  {"id":"s_work_nvlt_51_153","chapterId":"ch_work_nvlt_51","text":"又曰：武帝還過洛陽，二三代邈遠，以其三十里地，封周後為周子南君。","sortOrder":153},
  {"id":"s_work_nvlt_51_154","chapterId":"ch_work_nvlt_51","text":"又曰：高祖功臣侯者，子孫驕逸，多陷法禁，訖於孝武，靡有孑遺，於是成帝复紹萧何，而哀平之世，曹參周勃之後。","sortOrder":154},
  {"id":"s_work_nvlt_51_155","chapterId":"ch_work_nvlt_51","text":"又曰：元康四年，立靳翕夏侯婴陳平張良周勃等一百一十八人後，紹爵复家也。","sortOrder":155},
  {"id":"s_work_nvlt_51_156","chapterId":"ch_work_nvlt_51","text":"又，漢武元狩中，复以酂戶二千四百，封萧何曾孫慶為酂侯，布告天下，令明知朕報以萧相國德慶厚也。","sortOrder":156},
  {"id":"s_work_nvlt_51_157","chapterId":"ch_work_nvlt_51","text":"《東觀漢記》曰：高祖功臣，萧曹為首，有傳世不絕之誼，曹相國後容城侯無嗣，朕甚愍焉，望長陵東門，見二臣之墓，生既有節，終不遠身，誼臣受寵，古今所同，遣使者以中牢祷，大鸿臚悉求近親，宜為嗣者，頃［《東觀漢記》作須。］景風［原訛夙，據冯校本改。］紹封，以彰厥功。","sortOrder":157},
  {"id":"s_work_nvlt_51_158","chapterId":"ch_work_nvlt_51","text":"《晉陽秋》曰：夏侯惇，魏之元功，勋書竹帛，昔庭堅不祀，［原訛死，據冯校本改。］猶或悼之，况朕受終於魏，而可忘其功臣哉，其擇惇近屬封之。","sortOrder":158},
  {"id":"s_work_nvlt_51_159","chapterId":"ch_work_nvlt_51","text":"《晉中興書》曰：泰元二年，興滅繼絕後，故陳騫後浩之為高平公，裴秀後球為鉅鹿公，王沉後朴之為博陵公，荀勖後軌為濟北侯，何曾後闡為朗陵侯，羊祜後法興為鉅平侯。","sortOrder":159},
  {"id":"s_work_nvlt_51_160","chapterId":"ch_work_nvlt_51","text":"又曰：元帝紹封魏後曹励為陳留王。","sortOrder":160},
  {"id":"s_work_nvlt_51_161","chapterId":"ch_work_nvlt_51","text":"【表】魏武帝謝袭費亭侯表曰：不悟陛下，乃尋臣祖父廁豫功臣，克定寇逆，援立孝順皇帝，謂操不忘，獲封茅土，聖恩明發，遠念桑梓，日以臣為忠孝之苗，不复量臣材之丰否，既勉袭爵邑，忝厥祖考，复寵上將鈇鉞之任，兼領大州萬里之憲，內比鼎臣，外參二伯，身荷兼绂之榮，本枝賴無窮之祚也，昔大彭辅殷，崑吾翼夏，功成事就，乃備爵錫臣，束脩無稱，統御無績，比荷殊寵，策命褒績，未盈一時，三命交至，双金重紫，顯以方任，雖不識義，庶知所尤，［冯校本作死。］","sortOrder":161},
  {"id":"s_work_nvlt_51_162","chapterId":"ch_work_nvlt_51","text":"又郭嘉有功早［原作臣，據冯校本改。］死宜追赠封表曰：臣聞褒忠示寵，未必當身，念功惟績，恩隆後嗣，是以楚宗孫叔敖，顯封厥子，岑彭既没，爵及枝庶，誠賢君殷勤於清良，聖祖敦篤於明勋也，故軍祭酒洧陽亭侯潁川郭嘉，立身著行，稱成乡邦，與臣參事，盡節為國，臣今日所以免戾，嘉與其功，方將表顯，使賞足以報效，薄命天陨，不終美志，上為陛下悼借［疑當作惜。］良臣，下自毒恨，丧失奇佐，昔霍去病蚤死，孝武為之咨嗟，祭遵不究功業，世祖望柩悲恸，仁恩降下，念發五內，今嘉陨命，誠足怜傷。","sortOrder":162},
  {"id":"s_work_nvlt_51_163","chapterId":"ch_work_nvlt_51","text":"梁任昉為褚蓁代兄袭封表曰：一日被司徒符印，稱詔二日許臣兄贲所請，以臣紹封南康郡公，臣世屬啟聖，運偶時來，尚德畴庸，先錫土宇，臣贲載世承家，兄居長德，而量己夙退，內事園蔬，以臣行達幽明，早酷荼苦，贲天倫冥至，友愛淳深，非直引塉推溫，故能逃跡讓位，鞠育提養，以及人次，事死讓生，尚均脱屣，取信十室，本若锱銖，乃遠谬推恩，近霑庸薄，能以國讓，弘義有歸，匹夫難奪，守以勿二，昔武始迫家臣之策，陵陽感鮑子之言，張以誠請，丁為理屈，且大宗絕緒，命臣出缵傍統，禀承在昔，理絕終天，永懷情事，觸感崩裂，伏惟陛下，俯權孤門哀榮之重，爰奪臣贲一至之輕，察其丹款，特賜停絕，至公允穆，微臣剋幸。","sortOrder":163},
  {"id":"s_work_nvlt_51_164","chapterId":"ch_work_nvlt_51","text":"又表曰：近冒披款，庶蒙哀亮，奉被還詔，未垂矜允，伏讀周遑，罔寘心誠，臣本凡劣，身名不限，摽一善不足以验風流，存小讓不足以弘進止，若乃富埒千驷，貴有邦家，二者之來，不期而至，中人猶其趑趄，凡近固宜勉勖，直以門緒有歸，長德無二，若使贲高延陵之風，臣忘子臧之節，是废德舉，豈曰能賢，陛下留心孤門，特深追遠，故臣窮必呼天，凭威咫尺，贲婴疾沉固，公私废禮，逢不世之恩，遂良己之志，確然難奪，有理存焉，臣既承先旨，出缵傍統，受命有資，反身何奉，叙心感悼，免義迫躬，誠贲息霁，［句有脱文。］年將志學，禮及趨拜，且私門世適，二三攸序，若天眷無已，必降殊私，乞以臣霁奉膺珪社，伏原陛下聖慈，曲垂矜慎，如蒙哀允，施重含育。","sortOrder":164},
  {"id":"s_work_nvlt_51_165","chapterId":"ch_work_nvlt_51","text":"周庾信功臣不死王事請門袭封表曰：臣聞以法施民，必傳祀典，以勞定國，必有承家，孫叔敖祭酹無聞，有傷良相，汝叔齊胤嗣絕没，實貶賢臣，謹案大統十六年格，先有封爵，死於王事絕嗣者，聽以支子繼袭，非死王事，不許承封，前牒五等功臣，皆是勤勞王室，身當患難，扞御灾禍，翼贊大猷，一日遇疾，身捐馆舍，不幸無胤，享祀便絕，於禮則不足，於義則有傷，未求上林之獵，已削其侯，不服襜褕之衣，先除其國，伏惟皇帝，崇德旌庸，興亡繼絕，聞鼓鼙而思將帥，畫雲台而念舊臣，豈有功存社稷，而無後可守，事盡忠貞，而無祠可祭，周於蕃屏為約，事在世功，漢以山河為誓，義存長久，臣聞存人之國，大於救人之灾，立人之後，重於封人之墓，竊以殷朝繼及，無废小宗，周室興亡，貴存身後，紹高密者累葉，豈专邓萬［本集作禹。］之正胤，嗣平陽者重世，何必曹參之嫡孫，愚謂生有其勞，死非王事，雖在支庶，併聽承袭，幸使伯有之魂，不能為厲，若敖之鬼，其無餒而，幽顯對扬，人神咫尺。","sortOrder":165},
  {"id":"s_work_nvlt_51_166","chapterId":"ch_work_nvlt_51","text":"《藝文類聚》　唐·欧陽詢","sortOrder":166},
  {"id":"s_work_nvlt_52_1","chapterId":"ch_work_nvlt_52","text":"卷五十二治政部上據明本補","sortOrder":1},
  {"id":"s_work_nvlt_52_2","chapterId":"ch_work_nvlt_52","text":"○論政善政赦宥","sortOrder":2},
  {"id":"s_work_nvlt_52_3","chapterId":"ch_work_nvlt_52","text":"◇論政","sortOrder":3},
  {"id":"s_work_nvlt_52_4","chapterId":"ch_work_nvlt_52","text":"《釋名》曰：政，正也，下所取正也。","sortOrder":4},
  {"id":"s_work_nvlt_52_5","chapterId":"ch_work_nvlt_52","text":"《禮記》曰：聖人南面而聽天下，所宜先者五，一曰治親，二曰報功，三曰舉賢，四曰使能，五曰存愛，［察有仁愛者也。］五者一得於天下，民無不足不贍者。","sortOrder":5},
  {"id":"s_work_nvlt_52_6","chapterId":"ch_work_nvlt_52","text":"《大戴禮》曰：德法者，御民之衔勒也，吏者辔也，刑者策也，天子御者，內史太史，左右手也，古者以法為衔勒，以官為辔，以刑為策，以人為手，故御天下數百年而不解惰。","sortOrder":6},
  {"id":"s_work_nvlt_52_7","chapterId":"ch_work_nvlt_52","text":"《管子》曰：國有四維，一維絕則傾，二維絕則危，三維絕則覆，四維絕則滅，傾可正，危可安，覆可起，滅不可得复也，四維，一曰禮，二曰義，三曰廉，四曰恥。","sortOrder":7},
  {"id":"s_work_nvlt_52_8","chapterId":"ch_work_nvlt_52","text":"又曰：尧舜之民，非生而治，桀紂之民，非生而亂，故治亂在上。","sortOrder":8},
  {"id":"s_work_nvlt_52_9","chapterId":"ch_work_nvlt_52","text":"又曰：聖君設度量，置儀治，如天地之堅，如列星之固，如日月之明，如四時之信，然正令往，而民從之。","sortOrder":9},
  {"id":"s_work_nvlt_52_10","chapterId":"ch_work_nvlt_52","text":"《晏子》曰：景公問治國何患，對曰：患社鼠，社有鼠，不可灌，人君之左右，出則賣重寒熱，入則矯謁收利。","sortOrder":10},
  {"id":"s_work_nvlt_52_11","chapterId":"ch_work_nvlt_52","text":"《老子》曰：治大國，若烹小鮮。","sortOrder":11},
  {"id":"s_work_nvlt_52_12","chapterId":"ch_work_nvlt_52","text":"《書》曰：懍乎若朽索之馭六馬。","sortOrder":12},
  {"id":"s_work_nvlt_52_13","chapterId":"ch_work_nvlt_52","text":"《商君書》曰：凡人主所以勸民者，官爵也，國之所興者，農戰也，令民求官爵，皆不以農戰，而以巧言虛道也，此為勞民，勞民者，其國必無力，無力者其國必削。","sortOrder":13},
  {"id":"s_work_nvlt_52_14","chapterId":"ch_work_nvlt_52","text":"又曰：善治者，使盜跖可信，不能治者，使伯夷可疑。","sortOrder":14},
  {"id":"s_work_nvlt_52_15","chapterId":"ch_work_nvlt_52","text":"《韓子》曰：夫尧生在上位，雖十桀紂不能亂者，势治也，桀紂亦生在上，雖有十尧舜而不能治者，势亂也。","sortOrder":15},
  {"id":"s_work_nvlt_52_16","chapterId":"ch_work_nvlt_52","text":"《史記》曰：齊威王召即墨大夫而語之曰：自子之居即墨也，毀日至，然吾使人视即墨，田野辟，民人給，官無留事，是子不事吾左右，以求譽也，封之萬家，召阿大夫語之曰：自子之守阿，譽日聞矣，然使使视阿，田野不辟，民貧，若是子以幣享吾左右，以求譽也，是日烹阿大夫，及左右嘗譽者，於是齊國震懼，人不敢飾非。","sortOrder":16},
  {"id":"s_work_nvlt_52_17","chapterId":"ch_work_nvlt_52","text":"陆贾《新語》曰：君子為治也，混然無事，寂然無聲，官府若無人，亭落若無吏，郵無夜行之卒，乡無夜召之正，耆老甘味於堂，丁男耕芸於野。","sortOrder":17},
  {"id":"s_work_nvlt_52_18","chapterId":"ch_work_nvlt_52","text":"《淮南子》曰：治國者，若耨田，去害苗而已，今沐者墮發，而猶為之不已，以其所去者少，所利者多也。","sortOrder":18},
  {"id":"s_work_nvlt_52_19","chapterId":"ch_work_nvlt_52","text":"又曰：盛國之道，工無伪事，農無遺力，士無諂行，官無失法，譬若設網者，引其綱而萬目張。","sortOrder":19},
  {"id":"s_work_nvlt_52_20","chapterId":"ch_work_nvlt_52","text":"又曰：張琴瑟者，小絃镮而大絃缓，镮［者急也。］立事者，賤者勞而貴者逸也，禹［淮南泰族篇作舜。］為天下，彈五絃之琴，歌南風之詩，周公肴膳不撤於前，鐘鼓不解於懸，而四夷服，嬴秦正晝决獄，夜理書，［正，秦始皇名也。］御史冠蓋相接於道，戍五嶺以備越，［五嶺，鐔城之嶺，九疑之塞，番禺之都，南野之界，射(淮南人間篇作餘。)幹之水。］桀［泰族篇作筑。］修城以守胡，然奸邪萌生，而亂愈滋。","sortOrder":20},
  {"id":"s_work_nvlt_52_21","chapterId":"ch_work_nvlt_52","text":"又曰：太清之始，天覆以德，地載以樂，四時不失其序，風雨不降其虛，日月淑清而扬光，五星循軌而不失行，鳳麟至，蓍龟兆，甘露下，竹實滿，流黃出，朱草生，［滿，成也，流黃，土精也，朱草生於庭，皆瑞應也。］逮至衰世，松柏箘簵，宛而夏槁，江河三川，絕而不流，夷羊在牧，［夷羊，土神也，殷之將亡，見於商郊也。］飛蛩滿野，［蛩，蝉蔑蒙屬。］","sortOrder":21},
  {"id":"s_work_nvlt_52_22","chapterId":"ch_work_nvlt_52","text":"又曰：楚王問詹何曰：治國奈何，詹何曰：何明於治身，不明於治國，楚王曰：寡人得奉宗廟社稷，原學所以守之，詹何對曰：臣未嘗聞身亂而國治者也，故本身不敢對以末，楚王曰：善。","sortOrder":22},
  {"id":"s_work_nvlt_52_23","chapterId":"ch_work_nvlt_52","text":"《說苑》曰：政有三品，王者之政化之，霸者之政威之，強國之政胁之，夫此三者，各有所施，而化之為貴矣，化之不变，而後威之，威之不变，而後刑之，夫［原訛尖，據冯校本改。］至於刑，則非王者之所貴也。","sortOrder":23},
  {"id":"s_work_nvlt_52_24","chapterId":"ch_work_nvlt_52","text":"《新序》曰：臧孫行猛政，子貢非之曰：夫政猶張琴瑟也，大絃急則小絃絕矣，是以位尊者，德不可以薄，宮大者，治不可以小，地廣者，製不可以狹，民眾者，政不可以苛，獨不聞，子產相鄭乎，其掄材推賢，抑惡而扬善，故有大略者，不問其所短，有德厚者，不非其小疵，其牧民之道，養之以仁，教之以禮，因其所欲而與之，從其所好而勸之，賞之疑者從重，罰之疑者從輕。","sortOrder":24},
  {"id":"s_work_nvlt_52_25","chapterId":"ch_work_nvlt_52","text":"【議】晉潘嶽九品議曰：天生蒸民，而树之君，使司牧之，勿失其性，君不獨治，於是乎建牧立監，陳其辅佐，故曰天工人其代之，然則高官厚祿，非明崇賢，所以興治，卑位下役，非為鄙愚，所以供職，雖或开榮辱之門，有爭競之弊，而百王莫之能易者，此道不可以二故也，方今天下隆平，四海攸同，荐賢達善，各以類進，夫觀民宣化，為治之本，雖實小邑，猶須其人。又中正之身，優劣懸殊，苟知人者智，則不知者谬矣，莫如達官，各舉其屬，萬嶽九列，朝所取信，郡守雖輕，有刺史存，舉之當否，實司其事，考績累名，施黜陟焉，進賢受賞，不進賢甘戮，沮勸既明，為人自為謀，庶公道大行，而私謁息矣。","sortOrder":25},
  {"id":"s_work_nvlt_52_26","chapterId":"ch_work_nvlt_52","text":"【論】後漢崔寔政論曰：自尧舜之帝，湯武之王，皆賴明哲之佐，博物之臣，故皋陶陳謀，而唐虞以興，伊箕作訓，而殷周以隆，及繼體之君，欲立中興之功者，曷嘗不賴賢哲之謀乎，凡天下之所以不治者，常疾世主承平之日久，俗漸弊而不寤，政浸衰而不改，是以受命之君，每辄創製，中興之主，亦匡時失，俗人拘文牵古，不達推製，奇伟所聞，簡忽所見，焉可與論國家之大事哉，孝宣皇帝，明於君人之道，審於為政之原，故嚴刑峻法，破奸宄之胆，海內清肅，天下謐如，嘉瑞併集，屢獲丰年，荐勋祖廟，享號中宗，筭計見效，優於孝文，元帝即位，果行宽政，卒以墮損，威權始奪，遂為漢室基禍之主，治國之道，得失之理，於斯可以鑒矣，昔孔子作春秋，襃齊桓，懿晉文，叹管仲之功，夫豈不美文武之道哉，誠達權救之理也，故聖人能與世推移，而俗士苦不知变，以為結繩之初，可复治亂秦之緒，幹戚之舞，足以解平城之围，文帝乃重刑，非輕之也，以嚴致平，非以宽致太平也。","sortOrder":26},
  {"id":"s_work_nvlt_52_27","chapterId":"ch_work_nvlt_52","text":"後漢王符潛夫論曰：夫為國者，以富民為本，以正學為基，民富乃可以教，學正乃得義，民貧則背善，學淫則诈伪，明君之法，務此二者，以為太平之基，致休徵之隆，夫富民者，以農桑為本，以遊業為末，百工者，以致用為本，以巧飾為末，商贾者，以通乏為本，以鬻货為末，三者守本，則民興富，國之所以為國者，以民也，治國之日舒以長，故其民間暇而力有餘，亂國之日促以短，故其民困務而力不足，所謂治國之日舒以長者，非能請羲和而令安行也，乃若明察而百官理，民安靜而力有餘，故视日長也，所謂亂國之日促以短者，非能謁羲和而令疾驅也，乃君暗則百官亂而奸宄興，細民懷賄而趨走，故视日短也。","sortOrder":27},
  {"id":"s_work_nvlt_52_28","chapterId":"ch_work_nvlt_52","text":"魏王粲［原訛桀，據冯校本改。］儒吏論曰：士同風於朝，農同業於野，雖官職務殊，地氣異宜，然其致功成利，未有相害而不通者也，至乎末世，則不然矣，執法之吏，不闚先王之典，搢紳之儒，不通律令之要，彼刀筆之吏，豈生而察刻哉，起於幾案之下，長於官曹之間，無溫裕文雅以自润，雖欲無察刻，弗能得矣，竹帛之儒，豈生而迂缓也，起於講堂之上，遊於乡校之中，無嚴猛斷割以自裁，雖欲不迂缓，弗能得矣，先王見其如此也，是以博陳其教，辅和民性，達其所壅，袪其所蔽，吏服訓雅，儒通文法，故能宽猛相濟，刚柔自［原作百，據冯校本改。］克也。","sortOrder":28},
  {"id":"s_work_nvlt_52_29","chapterId":"ch_work_nvlt_52","text":"【表】魏武帝陳損益表曰：陛下即祚，复蒙试用，遂受上將之任，統領二州，內參機事，實所不堪，昔韓非闵韓之削弱，不務富國強兵，用賢任能，臣以驅驅之质，而當鐘鼎之任，以闇钝之才，而奉明明之政，顧恩念责，亦臣竭節投命之秋也，謹條遵奉舊訓，權時之宜十四事，奏如左，庶以蒸螢，增明太陽，言不足采。","sortOrder":29},
  {"id":"s_work_nvlt_52_30","chapterId":"ch_work_nvlt_52","text":"魏陳王曹植降江東表曰：臣聞士之羨永生者，非徒以甘食麗服，宰割萬物而已，將有以補益群生，尊主惠民，使功存於竹帛，名光於後嗣，今臣文不昭於俎豆，武不習於幹戈，而竊位藩王，尸祿東夏，消損天日，無益聖朝，淮南尚有山竄之賊，吳會猶有潛江之虜，使戰士未獲歸於農畝，五兵未得戢於武库，蓋善論者不恥謝，善戰者不羞走，夫凌雲者泥蟠者也，後申者先屈者也，是以神龍以為德，尺蠖以昭義，昔湯事葛，文王事犬夷，固仁者能以大事小，若陛下遣明哲之使，繼能陆贾之蹤者，使之江南，發恺悌之詔，張日月之信，开以降路，權必奉聖化，斯不疑也。","sortOrder":30},
  {"id":"s_work_nvlt_52_31","chapterId":"ch_work_nvlt_52","text":"◇善政","sortOrder":31},
  {"id":"s_work_nvlt_52_32","chapterId":"ch_work_nvlt_52","text":"《禮記》曰：哀公問政，子曰：文武之政，布在方策，其人存，則其政舉，其人亡，則其政息。","sortOrder":32},
  {"id":"s_work_nvlt_52_33","chapterId":"ch_work_nvlt_52","text":"《左氏傳》曰：鄭人遊於乡校，以論執政，然明謂子產，毀乡校如何，子產曰：何為，夫人朝進夕退而遊焉，以議執政之善否，其所善者，吾則行之，其所惡者，吾則改之，是吾師也。","sortOrder":33},
  {"id":"s_work_nvlt_52_34","chapterId":"ch_work_nvlt_52","text":"又曰：子產知然明，問為政焉，曰：视民如子，見不仁者誅之，如鷹鹯之逐鳥雀也，子產喜，以語子大叔，且曰：他日吾見篾之面而已，今吾見其心矣，子太叔問政於子產，子產曰：政如農功，日夜思之，思其始而成其終，其過鮮矣。","sortOrder":34},
  {"id":"s_work_nvlt_52_35","chapterId":"ch_work_nvlt_52","text":"又曰：鄭子產有疾，謂子太叔，我死，子必為政，唯有德者，能以宽服民，其次莫如猛，夫火烈，民望而畏之，故鮮死者，水懦，民狎而玩之，則多死焉，疾數月而卒，太叔為政，不忍猛而宽，鄭國多盜，聚於雚蒲之泽，太叔徒兵攻雚蒲之盜，盡殺之，仲尼曰：善哉，政宽則民慢，慢則糾之以猛，猛則民殘，殘則施之以宽，宽以濟猛，猛以濟宽，政是以和。","sortOrder":35},
  {"id":"s_work_nvlt_52_36","chapterId":"ch_work_nvlt_52","text":"《論語》曰：子貢問政，子曰：足食足兵，民信之矣，子貢曰：必不得已而去，於斯二者何先，曰：去食，自古皆有死，民無信不立。","sortOrder":36},
  {"id":"s_work_nvlt_52_37","chapterId":"ch_work_nvlt_52","text":"又曰：季康子問政於孔子，孔子對曰：政者正也，子帥以正，孰敢不正。","sortOrder":37},
  {"id":"s_work_nvlt_52_38","chapterId":"ch_work_nvlt_52","text":"又曰：季康子問政於孔子，曰：如殺無道以就有道，何如，孔子曰：子為政，焉用殺，子欲善而民善矣，君子之德風，小人之德草，草上之風必偃。","sortOrder":38},
  {"id":"s_work_nvlt_52_39","chapterId":"ch_work_nvlt_52","text":"又曰：或謂孔子曰：子奚不為政，子曰：書雲，孝乎惟孝，友於兄弟，施於有政，是亦為政，奚其為為政。","sortOrder":39},
  {"id":"s_work_nvlt_52_40","chapterId":"ch_work_nvlt_52","text":"《家語》曰：子路治蒲，三年，孔子過之，入其境，曰：善哉由乎，恭敬以信矣，入其邑，曰：善哉由乎，忠信以宽矣，至其庭，曰：善哉由乎，明察以斷矣，子貢問曰：夫子未見由之政，而三稱其善，可得聞乎，孔子曰：入其境，田畴治，草萊辟，溝洫深，此恭敬以信，故其民盡力也，入其邑，牆屋完固，树木甚茂，此其忠信而宽，故其民不偷也，至其庭，甚清閒，諸下用命，此其明察以斷矣。","sortOrder":40},
  {"id":"s_work_nvlt_52_41","chapterId":"ch_work_nvlt_52","text":"又曰：哀公問政於孔子，孔子對曰：政之急者，莫大乎使民富且寿也，公曰：為之奈何，孔子曰：省力役，薄賦斂，則民富矣，敦禮教，遠罪戾，則民寿矣，公曰：寡人欲行夫子之言，恐吾國貧，孔子曰：詩雲，恺悌君子，民之父母，未有其子富而父母貧也。","sortOrder":41},
  {"id":"s_work_nvlt_52_42","chapterId":"ch_work_nvlt_52","text":"又曰：衛靈公問孔子曰：有語寡人為國家者，謹之於廟堂之上，則政治矣，何如，孔子曰：其可也，愛人者則人愛之，惡人者則人惡之。","sortOrder":42},
  {"id":"s_work_nvlt_52_43","chapterId":"ch_work_nvlt_52","text":"又曰：哀公問於孔子曰：寡人欲國小則能守，大則能攻，其道何如，孔子曰：使君朝庭有禮，上下和親，天下百姓，皆君之民也，將誰攻焉，苟违此道，民叛如歸，皆君之讎也，將誰與守，公曰：善哉，於是废泽梁之禁，以惠百姓。","sortOrder":43},
  {"id":"s_work_nvlt_52_44","chapterId":"ch_work_nvlt_52","text":"《管子》曰：凡為國之道，必先富民，民富則易治也，貧則難治也，奚以知然，民富則安乡，安乡則重家，重家則敬上畏罪，敬上畏罪，則易治也，貧則危乡，危乡則輕家，輕家則凌上犯禁，凌上犯禁，則難治也，昔者七十九代之君，法製不一，號令不同，然而俱王天下，何也，必國富而粟多也。","sortOrder":44},
  {"id":"s_work_nvlt_52_45","chapterId":"ch_work_nvlt_52","text":"又曰：政之所行，在順民心，政之所废，在逆民心，民惡忧勞，我佚樂之，民惡貧賤，我富貴之，民惡危墜，我存安之，民惡滅絕，我生育之。","sortOrder":45},
  {"id":"s_work_nvlt_52_46","chapterId":"ch_work_nvlt_52","text":"又曰：凡牧民者，欲民之正，欲民之正也，則微邪不可不禁也，微邪者，大邪之所生也，微邪不禁，而求大邪之亡傷，固不可得也。","sortOrder":46},
  {"id":"s_work_nvlt_52_47","chapterId":"ch_work_nvlt_52","text":"《邓析書》曰：夫水濁則無掉尾之魚，政苛則無逸樂之士。","sortOrder":47},
  {"id":"s_work_nvlt_52_48","chapterId":"ch_work_nvlt_52","text":"《孟子》曰：為高必因丘陵，為下必因川泽，為政必因先王之道。","sortOrder":48},
  {"id":"s_work_nvlt_52_49","chapterId":"ch_work_nvlt_52","text":"《莊子》曰：至德之世，山無蹊隧，泽無舟梁，乌□之巢，可攀援而闚也。","sortOrder":49},
  {"id":"s_work_nvlt_52_50","chapterId":"ch_work_nvlt_52","text":"《孫卿子》曰：夫一仞之牆，民不能逾，百仞之山，童子升而遊焉，凌遲故也，今仁義之凌遲久矣，能謂民弗逾焉。","sortOrder":50},
  {"id":"s_work_nvlt_52_51","chapterId":"ch_work_nvlt_52","text":"《商君書》曰：古者民聚生而群處，故求有上也，然則天下之樂有上，將以為治也，今有主而無法，其害與無主同，有法而不勝其亂，與無法同也。","sortOrder":51},
  {"id":"s_work_nvlt_52_52","chapterId":"ch_work_nvlt_52","text":"《韓子》曰：故善毛嫱而西施之美，無益吾［原作君，據冯校本改。］面，用脂泽粉黛，則倍其初，言先王仁義，無益於治，必賞罰則國治，賞罰法度者，國之脂泽粉黛。","sortOrder":52},
  {"id":"s_work_nvlt_52_53","chapterId":"ch_work_nvlt_52","text":"又曰：势者，君之馬也，威者，君之輪也，势固則舆安，威定則策劲，臣從則馬良，民和則輪利，為國有失於此，覆舆奔馬，折策败輪矣，舆覆馬奔，策折輪败，載者安得不危。","sortOrder":53},
  {"id":"s_work_nvlt_52_54","chapterId":"ch_work_nvlt_52","text":"《新序》曰：魯君使密子賤為单父宰，子賤辭去，因請善書者，使書憲法，魯君與之，至单父，使書，子賤從旁引其肘，書丑則怒之，欲好書則又引之，書者患之，辭去，歸以告魯君，魯君曰：子賤苦吾扰之，使不得施其善政也，乃命有司，無得擅徵發单父，单父大理，［事具巧藝部書篇。］","sortOrder":54},
  {"id":"s_work_nvlt_52_55","chapterId":"ch_work_nvlt_52","text":"【碑】梁裴子野丹陽尹湘東王善政碑曰：皇上建顯號，垂鸿名，廣大配乎天地，光華象乎日月，長駕遠撫，橫逸乎都外，策鏡區域，充塞乎無垠，上冠九垓，旁濟八表，製禮以告成功，作樂以彰治定，福應允臻，祥慶符合，六府孔脩，九官鹹事，於往歲也，有司奏以湘東王為宣惠將軍丹陽尹，既而下車為政，振民育德，循名责實，舉無遺慮，若夫據饋累起，求賢如不及，卑身折節，用人若由己，玉帛旅於丘園，辟書交乎涂路，求餘論於故府，想遺風於舊哲，延儒生於東閤，命文學於後車，重門洞啟，列筵廣置，四民總至，獄訟殷集，王兼而治之，綽有餘裕，上弘其禮，下悅其風，虛往實歸，人得所至，由是百吏仰成，具僚斂衽，千里之間，有懷必亮，躬親勸課，賦政授時，辨相物宜，務盡地利，由是仍歲有秋，餘糧栖畝，是以縉紳先生，愀然相顧，遂造象魏，拜而陳之，有詔報曰：纖介之善，春秋必書，吏民歸美，難用抑絕，於是二三君子，歡得所奏，乃擇工良匠，追石名山，撰德選辭，興事篆刻，俾萬代之下，知斯文之在斯，銘曰：茫茫禹跡，經啟萬方，平秩肇定，曰若我皇，併苞九域，畫野分疆，猗欤帝子，日就月將，疏爵分品，奄有瀟湘，君王先啟，既表南國，肇允神童，翻飛上德，导達玄微，優遊翰墨，行成師范，文為麗則，帝曰爾詣，出康庶績，勿替敬典，大猷允迪，我王顯允，洵美且麗，夙夜乾乾，有隆無替，光贊大朝，庇民濟世，京邑翼翼，永承嘉惠。","sortOrder":55},
  {"id":"s_work_nvlt_52_56","chapterId":"ch_work_nvlt_52","text":"陳徐陵為司空徐州刺史侯安都德政碑曰：巖巖天柱，大矣周山之峰，桓桓地軸，壮哉崑崙之阜，三光懸而不墜，九土镇以無疆，承乾合德之君，則天體元之後，所以併咨四镇，鹹建五臣，業配蒼祗，功成宇縣，至於流名雅頌，著美風詩，年代悠然，寂寥無紀，其能繼茲歌詠者，司空侯使君乎，自文昭武穆，祚土开家，濮水盛其衣簪，滎波分其緒秩，仁義之道，夷門美於大梁，儒雅之風，司徒重於強漢，自通人許劭，讬命於江湖，高士袁忠，寄身於交越，俱违建安之難，獨處衡山之陽，祖天資秀杰，世載雄豪，卓富擬於公侯，班佃必於旌鼓，父光祿大夫，邑里开通德之門，州乡無抗禮之客，自茫茫禹跡，赫赫宗周，家滅驪戎，國亡夷羿，我高祖武皇帝，迎河圖於浪泊，括地象於炎洲，南興涿鹿之師，北問共工之罪，天生宰辅，尧年致白虎之祥，神賜英賢，殷帝感蒼龍之杰，公亦觀時佇聖，嘯咤風雲，跪开黃石之書，高詠玄池之野，沉吟梁甫，自比管仲之才，惆怅華［○本集作莘。］郊，久負伊生之叹，自羯虜侵華，群蠻縱軼，衡［原訛後，據冯校本改。］皋桂部之地，四戰五達之郊，郡境賢豪，將謀御難，長者佥論，推公主盟，義士雄民，星羅霧集，公既膺五聘，方啟六韜，率是驍徒，仍开嶺峤，自大讨瀟湘，同茲樊郦，下軍违命，上策不宣，败我王師，受拘勍盜，大陳格於文祖，鹹秩具神，率土依風，群靈禀朔，公亦忠為令德，天纂之謀，吳帳斯开，衛門無擁，雖复季孫還魯，隨武濟河，國慶民歡，相儔匪若，即授使持節开府儀同三司丹陽尹，昔光武不尤於冯異，穆公深禮於孟明，終報王官之師，遂舉鹹陽之地，斯乃聖主之宏略，而名臣之遠圖者焉，皇帝以陶唐啟國，致玉版於河宗，颛頊承家，佐金天於江水，經纶草昧，定鼎之業居多，締構權舆，斷鼇之功相半，固以英聲馳於海外，信義感於寰中，主器攸歸，當璧斯在，公於是抗表長信，清宮未央，從亿兆以同心，引公卿而定策，馳輕軒於軨轕，奉待駕於中都，七廟之基，於焉永固，萬邦之本，由此克寧，乃授司空公南徐州刺史，於是镇之以清靜，安之以惠和，望杏敦耕，瞻蒲勸穡，室歌千耦，家喜萬鍾，陌上成陰，桑中可詠，春鹒始啭，必具籠筐，秋蟀載吟，竟鳴機杼，或肅拜靈祀，躬瞻舞雩，去駕擁於風尘，還旌阻於飄沐，京坻歲積，非勞楚堰之泉，仓廪年丰，無用秦渠之水，雖复東過小縣，夏雨逐其輕輪，南渡沧江，秋涛弭其張蓋，固不得同年而語矣，若夫聽采民訟，昏晓必通，召引軒櫺，躬親辯决，立受符於前案，無留詣於後曹，接務高城之中，非異甘棠之下，欣欣美俗，濟濟都尘，以贾琮郭贺之風，行建武永平之化，於是州民散騎常侍王珝等，拜表宮闕，請扬茲美化，树彼高碑，民欲天從，允彰絲誥，銘曰：鬱鬱三象，茫茫九州，綿天惨沴，浃地虔劉，赫矣高祖，爰清國讎，元勋佐命，力牧風侯，亦既旋歸，邦家有暉，宮亭蠡浦，奋翅高飛，雷卷勍寇，風行國威，文身被發，作貢來綏，我皇纂武，攀號東序，謁渭同周，迎門惟呂，流矢為暴，攙槍斯舉，喋喋蒼黎，危危刀俎，自我徂征，妖氛克平，爰驅大彘，實剪長鯨，北震巢浦，南俘灌城，青羌卷介，赤狄回兵，蹈舞難逾，歌謠靡宣，曰我黎庶，俱祈上玄，山移兩越，海变三田，公為上相，复倍斯年。","sortOrder":56},
  {"id":"s_work_nvlt_52_57","chapterId":"ch_work_nvlt_52","text":"又廣州刺史欧陽顧［本集作頠。］德政碑曰：弱水导其洪源，軒台表其增殖，懿哉少府，師储皇於二京，盛矣司徒，傳儒宗於九世，廣陵邕邕，族擅江右，勃海赫赫，名重洛陽，若夫嶽镇龍璠，星懸鶉火，衡山誕其高德，相［本集作湘。］水降其清辉，千仞孤摽，萬頃無度，年當小學，志冠成童，因孝為心，欲仁成體，屯騎府君，早弃榮祿，易箦之日，幾將毀終，不杖之言，深非通製，遺赀巨萬，富擬猗頓，裁变槐榆，併貶［本集作赈。］宗戚，南茨大麓，北眺清湘，得性於橘洲之間，披書於杏壇之上，三冬文史，五經縱橫，頻致嘉招，確乎難拔，既而帝啟黃枢，神亡赤伏，天地崩霣，川冢沸騰，群亻旱酋豪，更為禍亂，朝披羽檄，夜炤爟烽，浴鐵蔽於山原，摐金駭於樓堞，公疲兵屢出，獨據胡床，勍賊重围，尚凭書幾，扬灰既散，駕棒將揮，鹹剋凶梁，以保衡服，常以二主蒙尘，三光掩曜，出入逾於嘗胆，殷忧獨其撫心，不治第宅，深符去病，志枭群丑，弥同越石，自禹珪既錫，尧玉已傳，物变謳謠，風移笙管，商周之际，孤竹尚其哀歌，曹劉之間，蘇子猶其狂哭，况番禺連帥，寔謂宗枝，迷我天機，自窥梁鼎，以公威名本重，逼統前軍，乾數難违，剝象終悔，高祖永言惟舊，弥念奇功，即訓皇家，深弘朝綱，槛車才至，舆衬已焚，祝史祅於夷吾，壇場延於井伯，綢缪安樂，造次訐謀，爰珥丰貂，允光金蟪，但八柱之土，蠻夷不賓，九疑之陽，兵凶歲積，以公昔在衡皋，深留風愛，仁恩可以懷猛［原訛猶，據冯校本改。］獸，威名可以懼啼兒，乃授持節散騎常侍衡州刺史，我皇帝從唐侯以胤國，屈啟筮而登家，一恭寶祚，开定江沔，三改璇衡，苞羅湘峡，昔中宗屈申於處仲，高祖遺恨於平城，漢武承基，方通沙塞，晉明紹運，裁平姑熟，［本集作孰。］方其盛業，綽有光前，踐祚之初，進公位征南將軍廣州刺史。又都督東衡州二十州諸軍事宜，公乃務是民天，敦其分地，火耕水耨，弥互原野，賊盜皆偃，工贾競臻，鬻米商鹽，盈衢滿肆，新垣既筑外戶無扃，脂脯豪家，鍾鼎為樂，扬袪洒汗，振雨流風，市有千金之租，田多萬箱之詠，僧釋慧羨等，來朝終闕，備啟丹誠，乞於大路康莊，式刊丰琰，庶樊卿寶鼎，复述台司之功，羊叟高碑，更紀征南之德，於是跪开黃素，爰登紫泥，鑒此誠祈，皆如所奏，乃詔庸臣，為其銘曰：赫赫宗陳，桓桓鼎臣，千乘建學，五典攸因，盛德斯遠，公門日新，嵩高惟嶽，貺甫生申，去衡移廣，遷征自镇，悠悠銅界，藐藐金鄰，莫遠非督，無思不賓，三江靡浪，五嶺奚尘，式歌式舞，仁哉至仁，公其饗福，於萬斯春。","sortOrder":57},
  {"id":"s_work_nvlt_52_58","chapterId":"ch_work_nvlt_52","text":"又晉陵太守王励德政碑曰：若夫睢陵世傳，已詳載德之華，徐州先賢，亦著清風之美，伟哉文獻，光啟中興，郭茎表其深源，何筹慚其遠慶，豈惟桓氏之鳴玉，張家之珥貂，袁姓之朱衣，楊宗之華轂。又有似［本集作佽。］飛遮列，班弓夹門，濯龍俯望，緹騎盈道，奕世如此，何其盛哉，君以藍田美玉，大海明珠，灼灼美其聲芳，英英照其符彩，風神雅淡，識量宽和，既有崔琰之須眉，非無鄭玄之腰帶，烂烂如高巖下電，骚骚若長松里風，势利無扰於焜衿，行藏不槩於懷抱，家門雍睦，孝友為風，上交不諂，下交不渎，脱貂救厄，情靡矜吝，釋馬窮途，唯濟危殆，至於網羅圖籍，脂粉藝文，學侣揖其精微，詞宗稱其妙絕，出為仁武將軍晉陵太守，五雞三彘，勤恤有方，問羊知馬，鉤距兼設，濟北移树，累政之所未治，汝南爭水，連年之所無斷，一朝明决，曾不留滯，四民商販，鹹用殷阜，康哉寶運，美矣良臣，胄自澧水，源於洛濱，公侯世及，宰辅相因，曰我民秀，山川降神，風情穆穆，孝友恂恂，學則經笥，文為世珍，高風遠矣，曠代難倫，鼎铉虛職，台階未臻，安知霜霰，遽夭松椿，碣石斯表，民情既陳，徒然下拜，何報陽春。","sortOrder":58},
  {"id":"s_work_nvlt_52_59","chapterId":"ch_work_nvlt_52","text":"周王褒上庸公陆騰勒功碑曰：在昔洞庭彭蠡，三苗有遠竄之君，太室陽城，九州無同姓之國，是知周衛設险，所務非山川，河嶽作固，所寶惟休德，至於三峡蹇產，九折峥嵘，高峰尋雲，深穀無景，秦开漢閉，雖阻荷戟之虞，魏塞晉通，終因束馬之利，我大周开辟宇宙，混同文軌，御六氣於天枢，頓八絃於地絡，彭濮未恭，邛笮不讨，外凭劍道之難，內負銅梁之阨，大將軍上庸公，仗國威靈，奉辭伐罪，長戟萬队，巨艦千舳，板楯酋豪，斯榆君長，歷稔逋寇，累代稽誅，廓清江源，荡涤巴濮，若夫荆門千里，蜀置永安之宮，巴水三回，吳阻夷陵之縣，巫峡使君之滩，淪波洽没，建平督郵之道，栈径威紆，路阻蠻陬，途橫夷落，擅強专险，輕法侮吏，天子爰詔有司，公奉命天讨，星言載涂，指日遄邁，册授公大將軍信州刺史，韓信召拜，軍中致設壇之禮，衛青出征，臨河聞後距之令，夫鍾鼎大禮之器，昭德必書，金石不朽之质，庸勋斯树，某等乃建碑於某地，敢作頌雲，遐觀命氏，眇求世祿，龍圖紀河，鸿漸於陆，霸楚傳姓，命吳啟族，君子篤生，降靈惟嶽，朝陽擢彩，荆山曜璞，巴庸自擅，彭濮稱王，南泊僰道，西通夜郎，內凭玉壘，外阻銅梁，介视荒服，斗絕邊疆，赫赫南仲，堂堂方叔，天子命我，遐征越逐，窦氏車騎，去病冠軍，封山刊石，镌名剋勋，遠隔年代，懸感風雲，盛德必祀，千載斯文。","sortOrder":59},
  {"id":"s_work_nvlt_52_60","chapterId":"ch_work_nvlt_52","text":"隋江總吳興郡庐陵王德政碑曰：卓爾吾王，天人可擬，早成夙智，謙懷虛己，偃息流略，翱翔文史，三雍雅對，九師名理，好古如斯，學兼之矣，睢陽肇構，碣石初开，賜田待士，榜道求材，剖符彭國，述職琅台，去謠曙鼓，留歌暮來。","sortOrder":60},
  {"id":"s_work_nvlt_52_61","chapterId":"ch_work_nvlt_52","text":"【表】梁劉孝儀為雍州柳津請留刺史晉安王表曰：楚備寶臣，秦兵不入，齊多君子，魏〈王未〉恥昭，足使文公懼而侧席，孟軻叹而废寢，敢緣借寇之原，切望申耿之恩，陛下昔在潛龍，因茲或躍，固以陋膴々於周原，包怱怱之佳氣，昔次君出撫，近駕班輪，乔卿在政，遙授袞服焉，冯熊軾而督盜，御龍章而行部，無虧燮理，有光司牧。","sortOrder":61},
  {"id":"s_work_nvlt_52_62","chapterId":"ch_work_nvlt_52","text":"【教】梁簡文帝圖雍州賢能刺史教曰：冀州表朱穆之象，太丘有陳寔之畫，或有留愛士氓，或有傳芳史籍，昔越王鎔金，尚思范蠡，漢軍染畫，猶高贾彪，矧彼前賢，寧忘景慕，可併圖象廳事，以旌厥善。","sortOrder":62},
  {"id":"s_work_nvlt_52_63","chapterId":"ch_work_nvlt_52","text":"◇赦宥","sortOrder":63},
  {"id":"s_work_nvlt_52_64","chapterId":"ch_work_nvlt_52","text":"《易》曰：雷雨作解，君子以赦過宥罪。","sortOrder":64},
  {"id":"s_work_nvlt_52_65","chapterId":"ch_work_nvlt_52","text":"《周官》曰：國君過市，刑人赦。","sortOrder":65},
  {"id":"s_work_nvlt_52_66","chapterId":"ch_work_nvlt_52","text":"《尚書》曰：象以典刑，流宥五刑，鞭作官刑，朴作教刑，眚灾肆赦，怙終賊刑。","sortOrder":66},
  {"id":"s_work_nvlt_52_67","chapterId":"ch_work_nvlt_52","text":"又曰：五刑之疑有赦，五罰之疑有赦。","sortOrder":67},
  {"id":"s_work_nvlt_52_68","chapterId":"ch_work_nvlt_52","text":"《論語》曰：赦小過，舉賢才，《管子》曰：凡赦者，小利而大害也，久而不勝其禍，無赦者，小害而大利也，久而不勝其福，故赦者，饹馬之委辔也。","sortOrder":68},
  {"id":"s_work_nvlt_52_69","chapterId":"ch_work_nvlt_52","text":"《漢書》曰：宣帝元年詔曰：乃者鳳皇集泰山陳留，甘露降未央宮，其赦天下。","sortOrder":69},
  {"id":"s_work_nvlt_52_70","chapterId":"ch_work_nvlt_52","text":"《史記》曰：陶朱公中子殺人，囚於楚，朱公曰：殺人死，職也，使少子往视之，裝黃金千镒，長男請行，公不許，長男曰：長子家督也，今不遣，是吾不肖，欲自殺，不得已，乃為一封書及金，令遺故所善莊生，莊生乃見王曰：某星犯某宿，宜以德報，王乃使使封三錢之府，長男為王當赦，弟固當出，見莊生曰：弟今自赦，固辭去，乃取金，莊生恥為兒子所賣，乃入見王曰：陶朱公子多賂王左右，今赦，恐失望，王遂殺之，載丧而歸。","sortOrder":70},
  {"id":"s_work_nvlt_52_71","chapterId":"ch_work_nvlt_52","text":"《東觀漢記》曰：吳漢疾篤，車駕親臨，問所欲言，對曰：臣愚無所識知，唯原慎無赦而已。","sortOrder":71},
  {"id":"s_work_nvlt_52_72","chapterId":"ch_work_nvlt_52","text":"謝承《後漢書》曰：學中諸生，與李膺等更相褒重，莫不思其貶議，時河內張成，善說風角，推占當赦，遂教子殺人，李膺為河南尹，督之，促收捕，既而逢宥獲免，膺愈憤，竟案殺之，初成以方伎交通宦官，帝亦頗訊其占，成弟子牢脩，因上書誣告膺等，多養太學遊士，交結諸郡生徒，更相驅馳，共為部党，於是天子震怒，班下郡國，逮捕党人。","sortOrder":72},
  {"id":"s_work_nvlt_52_73","chapterId":"ch_work_nvlt_52","text":"《續漢書》曰：建武二年，詔曰：其赦天下，惟殘賊用刑戮深刻，獄多冤人，朕甚愍之，自今已後，有犯者，將正厥辜。","sortOrder":73},
  {"id":"s_work_nvlt_52_74","chapterId":"ch_work_nvlt_52","text":"袁崧《後漢書》曰：贾彪，字伟節，遊京師，與郭林宗等為談論之首，一言一行，天下以為准的，党事起，彪謂同志曰：吾不西行，大難不解，即入關，設方略，天子為之大赦。","sortOrder":74},
  {"id":"s_work_nvlt_52_75","chapterId":"ch_work_nvlt_52","text":"《華陽國志》曰：諸葛亮時，有言公惜赦者，亮答曰：治世以大德，不以小惠，故匡衡吳漢，不原為赦，先帝亦言，吾周旋陳元方鄭康成間，每見啟告治亂之道悉矣，曾不語赦也，若劉景叔［《太平御覽》六百五十二作升。］父子，歲歲赦宥，何益於治。","sortOrder":75},
  {"id":"s_work_nvlt_52_76","chapterId":"ch_work_nvlt_52","text":"《蜀志》曰：孟光，字孝裕，延熙九年秋，大赦，光眾责大將軍贾［太平御覽六百五十二作費。］禕曰：夫赦者，偏枯之物，非明世所宜有也，衰弊窮極，必不得已，然後乃可權而行之爾。","sortOrder":76},
  {"id":"s_work_nvlt_52_77","chapterId":"ch_work_nvlt_52","text":"《裴頠集》曰：臣聞感神以政，應变以誠，故桑穀之異，以勉己而消，漢末屢赦，猶凌不反，由此言之，上协宿度，下寧萬國，唯在賢能，慎厥庶政，殆非孤赦所能增損也。","sortOrder":77},
  {"id":"s_work_nvlt_52_78","chapterId":"ch_work_nvlt_52","text":"《郭子》曰：孫秀降晉，武帝厚存寵之，妻以姨妹蒯氏，室家甚穆，妻嘗妒秀，乃骂為貉子，秀大不平之，遂出不复入，蒯氏自悔责，請救於帝，時大赦，群臣鹹見，既出，帝獨留秀，從容言曰：天下曠荡，蒯夫人可得從其例不，秀免冠謝，遂為夫婦如初，［事具人部妒篇。］","sortOrder":78},
  {"id":"s_work_nvlt_52_79","chapterId":"ch_work_nvlt_52","text":"風角書曰：春甲寅日，風高去地三四丈，鳴條以上，常從申上來，為大赦，期六十日。","sortOrder":79},
  {"id":"s_work_nvlt_52_80","chapterId":"ch_work_nvlt_52","text":"【賦】後漢崔寔大赦賦曰：惟漢之十一年四月，大赦，涤惡弃秽，與海內為始，亹亹乎恩［《初學記》二十作思。］隆平之進［《初學記》作道。］也，寔就而賦焉，以為五帝異製，三王殊事，然其承天據地，興設法製，一也，陛下以苞天之大，承前聖之跡，朝乾乾於萬機，夕處敬以厲惕，然猶痛刑之未错，厥將大赦，所以創太平之跡，旌頌聲之期，新邦家而更始，垂祉羨乎將來，此誠不可奪也，方將披玄雲，照景星，獲嘉禾於疆畝，數蓂荚於階庭，拦麒麟之肉角，聆鳳皇之和鳴，農夫歡於時雨，工女樂於機聲，雖皇羲之神化，尚何斯之太寧。","sortOrder":80},
  {"id":"s_work_nvlt_52_81","chapterId":"ch_work_nvlt_52","text":"【詔】後魏溫子昇孝莊帝殺爾朱榮詔曰：蓋天道忌盈，人倫疾惡，疏而不漏，刑之無舍，是以呂霍之門，禍譴所伏，梁董之家，咎徵斯在，爾朱榮爰自晉陽，同忧王室，義旗之建，大會孟津，與其樂推，其成鸿業，論其所由，乃有勋效，但致遠恐泥，終之寔難，習未崇朝，豺聲已露，既位極宰衡，地逾齊魯，容養之至，豈复是過，但心如猛火，山林無以供其暴，意等漏卮，江河無以充其溢，既見金革稍寧，方隅漸泰，不推天功，謂為己力，與奪任情，臧否肆意，無君之跡，日月已甚，乃有裂冠毀冕之心，將為拔本塞源之事，天既厭亂，人亦悔禍，將而有聞，罪無攸縱，是而可懷，孰不可忍，併以伏辜，自貽伊戚，元惡既除，人神慶泰，便可大赦天下。","sortOrder":81},
  {"id":"s_work_nvlt_52_82","chapterId":"ch_work_nvlt_52","text":"又遷都拜廟鄴宮赦文曰：建國所先，理屬於宗廟，立事為大，禮歸於禋祀，大丞相渤海王，神武命世，重匡頹歷，导塞源於將竭，扶神器於已傾，立天地之大功，成人臣之重義，朕以冲昧，猥當樂推，關路多虞，衿帶難固，瞻言往事，取則前脩，乃袭去酆，用追遷亳，定鼎鄴都，卜世惟永，民用子來，功成不日，今清廟初興，閟宮始就，靈祗萃止，祖考來格，神光夜照，香氣朝聞，令月吉辰，躬展誠敬，時和氣婉，景麗雲柔，四表來庭，萬國在位，哀樂相交，感慶兼集，固宜觀象雷雨，布宽大之恩，取類泽風，申肆眚之令，可大赦天下。","sortOrder":82},
  {"id":"s_work_nvlt_52_83","chapterId":"ch_work_nvlt_52","text":"北齊邢子才為受禪登極赦詔曰：無德而稱，化刑以禮，不言而信，先春後秋，故知惻隱之心，天地一揆，弘宥之道，今古同風，朕以寡薄，功烈無紀，昔先獻武王，值魏世不造，四海幅裂，九鼎行出，祭器無歸，乃驅御侯伯，大號燕趙，拯厥顛墜，俾亡若存，父襄王，外挺武功，內資明德，纂戎先業，辟土服遠，年逾二紀，世歷兩都，獄訟有適，謳歌斯在，魏帝俯遵歷數，念在褰裳，遠取唐虞，終同脱屣，實幽忧未已，志在陽城，而群公卿士，誠守逾切，遂屬代終，居於民上，如涉深冰，有倦終朝，始發晉陽，九尾呈瑞，升壇告天，赤雀效祉，惟爾文武不二之臣，股肱爪牙之將，左右先王，光隆大業，永言誠烈，共茲休慶，然三皇存教，非易可免，七名改咒，庸可庶幾，思共亿兆，同始茲日。","sortOrder":83},
  {"id":"s_work_nvlt_52_84","chapterId":"ch_work_nvlt_52","text":"【教】梁陆倕豫章王拜後赦教曰：夫議獄缓死，著自令圖，疑罪惟輕，聞諸雅誥，是以虞經惻隱，流涕冬决，鍾意垂仁，哀矜寒送，吾以虛薄，夙頒寵章，光宅襟险，奄有全粵，非有沛獻矜嚴，空紆青組，東平智思，徒舉赤帷，思所以仰述皇猷，导扬弘泽，遵彼下車，譬茲解網。","sortOrder":84},
  {"id":"s_work_nvlt_52_85","chapterId":"ch_work_nvlt_52","text":"《藝文類聚》　唐·欧陽詢","sortOrder":85},
  {"id":"s_work_nvlt_53_1","chapterId":"ch_work_nvlt_53","text":"卷五十三治政部下據明本補","sortOrder":1},
  {"id":"s_work_nvlt_53_2","chapterId":"ch_work_nvlt_53","text":"○錫命荐舉奉使","sortOrder":2},
  {"id":"s_work_nvlt_53_3","chapterId":"ch_work_nvlt_53","text":"◇錫命","sortOrder":3},
  {"id":"s_work_nvlt_53_4","chapterId":"ch_work_nvlt_53","text":"周官，九儀之命，正邦國之位，一命受職，再命受服，三命受位，四命受器，五命賜則，六命賜官，七命賜國，八命作牧，九命作伯。","sortOrder":4},
  {"id":"s_work_nvlt_53_5","chapterId":"ch_work_nvlt_53","text":"《韓詩外傳》曰：諸侯之有德，天子錫之，一錫車馬，再錫衣服，三錫虎贲，四錫樂器，五錫納陛，六錫朱戶，七錫弓矢，八錫鈇鉞，九錫秬鬯，謂曰九錫。","sortOrder":5},
  {"id":"s_work_nvlt_53_6","chapterId":"ch_work_nvlt_53","text":"《易》曰：王三錫命懷萬邦也。","sortOrder":6},
  {"id":"s_work_nvlt_53_7","chapterId":"ch_work_nvlt_53","text":"《尚書》曰：平王錫晉文侯秬鬯圭瓒，作文侯之命。","sortOrder":7},
  {"id":"s_work_nvlt_53_8","chapterId":"ch_work_nvlt_53","text":"《左傳》曰：王命尹氏策晉文公為侯伯，錫之大辂之服，戎辂之服，彤弓一，彤矢百，玈弓矢千，秬鬯一滷，虎贲三百人。","sortOrder":8},
  {"id":"s_work_nvlt_53_9","chapterId":"ch_work_nvlt_53","text":"范晔《後漢書》曰：董昭等欲共進曹操爵國公，九錫備物，密以訪荀彧，彧曰：曹公本興義兵，以匡振漢朝，雖勋德崇著，猶禀忠貞之節，君子愛人以德，不宜如此，事遂寢，操心不能平，會南征孫權，彧勞軍於谯，表辄留彧。","sortOrder":9},
  {"id":"s_work_nvlt_53_10","chapterId":"ch_work_nvlt_53","text":"《晉中興書》曰：烈宗冲幼，桓溫威震外內，人情噂〈口沓〉，互生同異，謝安與王坦之，盡忠匡翼，諷朝廷為九錫，使驍騎將軍袁宏具草，時溫已疾篤，宏以呈安，安视，辄雲不好，更勾改之，使弥歷旬日，至於溫薨，錫命遂寢。","sortOrder":10},
  {"id":"s_work_nvlt_53_11","chapterId":"ch_work_nvlt_53","text":"【文】後漢潘勖策魏武帝九錫命文曰：朕以不德，少遭愍凶，越自西土，遷於唐衛，當此之時，危若缀旒然，宗廟乏主，社稷無位，群凶觊觎，連城帶邑，一人尺土，朕無獲焉，即我高祖之命，將墜於地，朕用夙興假寐，震悼於厥心，乃誘天衷，誕育丞相，保乂我皇家，弘濟於艱難，朕實賴之，今將授君典禮，其敬聽朕命，昔者董卓初興國艱，群後釋位，以謀王室，君則攝進，首啟戎行，此君之忠於本朝也，後乃黃巾反易天常，侵我三州，延於平民，君又讨之，翦除其跡，以寧東夏，此又君之功也，君有定天下之功，重之以明德，班叙海內，宣美風俗，旁施勸教，恤慎刑獄，敦崇帝族，援繼絕世，舊德前功，罔不鹹秩，雖伊尹格於皇天，周公光於四海，方之蔑如也，朕聞先王併建明德，祚之以土，分之以民，崇其寵章，備其禮物，所以蕃衛王室，左右厥世也，其在周成，管蔡不靜，懲難念功，乃使邵康公錫齊太公履，東至於海，西至於河，南至於穆陵，北至於無棣，五侯九伯，實得征之，爰及襄王，亦有楚人不供王職。又命晉文，登為侯伯，錫以二辂，虎贲鈇鉞，秬鬯弓矢，大啟南陽，世作盟主，故周室之不坏，繄二國是賴，今君稱丕顯明德，［魏志一，文選三十五作德明，此倒。］保朕，［《魏志》：文選朕下有躬字，此脱。］奉答天命，导扬弘烈，綏爰九域，莫不率俾，功高於伊周，而賞卑乎齊晉，朕甚恧焉，今以十郡，封君為魏公，錫君玄土，苴以白茅，爰契爾龟，用建冢祖，昔在周室，畢公毛公，入為卿佐，周召師保，出為二伯，外內之任，君實宜之，其以丞相領冀州牧如故。又加君九錫，其敬聽朕命，魏國置丞相以下，群卿百寮，皆如漢初諸侯之製，君往钦哉，敬服朕命，簡恤爾眾，時亮庶功，用終爾顯德，對扬我高祖之休命。","sortOrder":11},
  {"id":"s_work_nvlt_53_12","chapterId":"ch_work_nvlt_53","text":"魏文帝策命孫權九錫文曰：蓋聖王之法，以德詔爵，以功製祿，勞大者祿厚，德盛者禮丰，故叔旦有夹辅之勋，太公有鷹扬之功，併啟土宇，併受備物，所以表章元功，殊異賢哲也，朕以不德，承運革命，思齊先代，坐而待旦，惟君天姿忠亮，命世作佐，深睹歷數，達見废興，遠遣行人，浮於潛漢，望風景附，抗疏稱蕃，忠肅內發，款誠外照，信著金石，義蓋山河，朕甚嘉馬，［吳志二作焉，此訛。］今封君為吳王，使持節高平侯，其授君玺綬策書，以大將軍使持節都督交州領荆益州牧事，錫君青土，苴以白茅，對扬朕命，以君東夏，今又加君九錫，其敬聽後命。","sortOrder":12},
  {"id":"s_work_nvlt_53_13","chapterId":"ch_work_nvlt_53","text":"宋傅亮作宋武帝九錫文曰：朕以寡昧，仰缵洪業，夷羿乘衅，荡覆王室，越在南鄙，至於九江，宗祀絕饗，人神無位，提挈群凶，寄命江介，則我祖宗之烈，奄墜於地，七百之祚，翦焉莫嗣，天未絕晉，誕育英辅，振厥綱維，再造區夏，興亡繼絕，俾昏作明，元勋至德，朕實賴焉，今將授公典策，其敬聽朕命，乃者桓玄肆僣，滔天泯夏，拔本塞源，顛倒六位，庶僚俯首，四方莫恤，公精貫朝日，氣凌虹霓，奋其靈武，大殲群丑，剋复皇邑，奉帝歆神，此公之大節也［宋書二無也字。］始於勤王者也，授律群後，沂流長鶩，薄伐峥嵘，獻捷南夏，大憝折首，群逆夷殄，三光旋照，舊物反正，此又公之功也，公有康宇內之勋，重之以明德，爰初發跡，則奇謨冠世，電击彊妖，則鋒無前對，聿寧東夏，大造黔首，辨方正位，納之軌度，蠲削煩苛，较若畫一，淳風美化，盈塞區宇，雖文命之東漸西被，咎繇之邁於种德，何以尚茲，朕聞先王之宰世也，庸勋尊賢，建侯胙土，褒以寵章，崇其徽物，所以夹辅皇室，外隆蕃屏，故曲阜光啟，遂荒徐宅，營丘表海，四履有聞，其在襄王，亦賴匡霸。又命晉文，備物九錫，惟公道冠前烈，勋高振古，而殊典未加，朕甚瞢焉，今進授相國。","sortOrder":13},
  {"id":"s_work_nvlt_53_14","chapterId":"ch_work_nvlt_53","text":"【表】魏武帝讓九錫表曰：臣功小德薄，忝寵已過，進爵益土，非臣所宜，九錫大禮，臣所不稱，惶悸征營，心如炎灼，歸情寫實，冀蒙聽省，不悟陛下，复詔襃誘，喻以伊周，未見哀許，臣聞事君之道，犯而勿欺，量能處位，計功受爵，苟所不堪，有損無從，加臣待罪上相，民所具瞻，而自過谬，其謂臣何。","sortOrder":14},
  {"id":"s_work_nvlt_53_15","chapterId":"ch_work_nvlt_53","text":"梁江淹為齊高帝讓相國齊公九錫表曰：臣聞日月權舆，二儀所以克靈，君臣設極，三統所以式固，惟生與位，謂之大寶，是以二周之始，珪河逾廣，兩漢之初，封賞弥盛，然表東海者，實牧野之日，瞻魯邦者，乃負圖之辰，若乃衣裳之會，九合一匡，猶慚於斯禮也，臣實鄙才，靡識大體，徒以忠貞為槩，而勞不足銘，雖以丹素為誠，而功無可勒。","sortOrder":15},
  {"id":"s_work_nvlt_53_16","chapterId":"ch_work_nvlt_53","text":"又表曰：御龍勤夏，未聞冠俗之爵，大彭翼商，豈見超世之典，况呂梁不凿，而器重玄圭，越裳未獻，而賦擬千乘，鏡前脩而慚形，觌往德而耸慮也。","sortOrder":16},
  {"id":"s_work_nvlt_53_17","chapterId":"ch_work_nvlt_53","text":"◇荐舉","sortOrder":17},
  {"id":"s_work_nvlt_53_18","chapterId":"ch_work_nvlt_53","text":"《禮記》曰：趙文子所舉於晉國，管库之士，七十有餘家，生不交利，死不屬其子焉。","sortOrder":18},
  {"id":"s_work_nvlt_53_19","chapterId":"ch_work_nvlt_53","text":"《尸子》曰：人知用賢之利也，不能得賢，其何故也，夫買馬不論足力，以白黑為儀，必無走馬矣，買玉不論美惡，以大小為儀，必無良寶矣，舉士不論才，而以貴势為儀，則伊尹管仲不為臣矣。","sortOrder":19},
  {"id":"s_work_nvlt_53_20","chapterId":"ch_work_nvlt_53","text":"《說苑》曰：楚令尹虞丘子，舉孫叔敖，［說苑至公篇敖下有少焉虞丘子家幹法八字。］執而戮之，虞丘子喜，入見於王，言孫叔敖果可使持政，奉國法而不党，施刑戮而不亂，可不謂公乎，莊王曰：夫子之賜也。","sortOrder":20},
  {"id":"s_work_nvlt_53_21","chapterId":"ch_work_nvlt_53","text":"《呂氏春秋》曰：百里奚之未遇時，飯牛於秦，傅鬻以五羊之皮，公孫枝得之，獻諸缪公，三日，請屬事焉，公曰：買之五羊之皮而屬事，無乃為天下笑乎，枝曰：信賢而任之，君之明也，讓賢而下之，臣之志也，境內將服，夫誰暇笑哉，遂用之，謀無不當，舉必有功。","sortOrder":21},
  {"id":"s_work_nvlt_53_22","chapterId":"ch_work_nvlt_53","text":"《史記》曰：王稽使於魏，問鄭安平，魏有賢人可與俱西乎，安平曰：臣里中有張祿先生，欲見君，言天下事，王稽知其是范睢也，乃載以入秦。","sortOrder":22},
  {"id":"s_work_nvlt_53_23","chapterId":"ch_work_nvlt_53","text":"《漢書》曰：韓安國為人多大略，所推舉皆廉士，賢於己者。","sortOrder":23},
  {"id":"s_work_nvlt_53_24","chapterId":"ch_work_nvlt_53","text":"又曰：薛宣知翟方進有宰相器，深結之，方進竟代宣為丞相，免二歲，方進荐宣明習文法，上徵宣，复爵。","sortOrder":24},
  {"id":"s_work_nvlt_53_25","chapterId":"ch_work_nvlt_53","text":"又曰：何武為人仁厚，好進士，稱人之善，為楚內史，厚兩龚，在沛郡，厚兩唐，為公卿，荐之朝廷，此人顯於世者，何侯力也。","sortOrder":25},
  {"id":"s_work_nvlt_53_26","chapterId":"ch_work_nvlt_53","text":"漢雜事曰：辛慶忌為酒泉太守，大將軍王鳳，荐慶忌正直仁勇，通於兵事，柱國石臣，鳳不宜久處其右，上乃复徵為光祿大夫執金吾。","sortOrder":26},
  {"id":"s_work_nvlt_53_27","chapterId":"ch_work_nvlt_53","text":"《東觀漢記》曰：東平王蒼，荐吏吳良，上章以示公卿曰：萧何［東觀漢記何下有舉字，此脱。］韓信，設壇即拜，不复考试，以良為議郎。","sortOrder":27},
  {"id":"s_work_nvlt_53_28","chapterId":"ch_work_nvlt_53","text":"又曰：杜林，字伯山，為侍御史，先與鄭興同寓隴右，乃荐之，上徵興為大中大夫。","sortOrder":28},
  {"id":"s_work_nvlt_53_29","chapterId":"ch_work_nvlt_53","text":"又曰：陳寵，字昭公，為尚書，寵性純淑，周密重慎，時有所表荐，辄自手書削草。","sortOrder":29},
  {"id":"s_work_nvlt_53_30","chapterId":"ch_work_nvlt_53","text":"《續漢書》曰：桥玄為司空，轉司徒，素與南陽太守陳球有隙，及在公位，而荐球為廷尉。","sortOrder":30},
  {"id":"s_work_nvlt_53_31","chapterId":"ch_work_nvlt_53","text":"又曰：虞詡以左雄有忠節，上疏，荐之曰：伏見議郎左雄，數上封事，實有王臣謇謇之節，宜擢在喉舌之官，必有匡弼之益，由是拜雄尚書。","sortOrder":31},
  {"id":"s_work_nvlt_53_32","chapterId":"ch_work_nvlt_53","text":"《吳越春秋》曰：孫子者，吳人，名武，善為兵法，僻隱幽居，世人莫知其能，子胥明於識人，乃荐孫子，吳王問以兵法，每陳一篇，王不覺口之稱善，［事具人部嘯篇。］《三辅决錄》曰：遊子殷為郡功曹，有童子張既為書佐，殷察異之，具設賓饌，以子楚讬之，後魏王以既為雍州，時漢興郡闕，王以問既，既稱楚文武兼才，遂以為漢興太守。","sortOrder":32},
  {"id":"s_work_nvlt_53_33","chapterId":"ch_work_nvlt_53","text":"《魏志》曰：潁川盧志才，筹畫士也，早卒，太祖與荀彧書曰：自志才亡後，莫可與計事者，汝潁固多奇才，誰可以繼，彧荐郭嘉，召見，論天下事，太祖曰：使孤成大業者，必此人也，表為司，空軍祭酒。","sortOrder":33},
  {"id":"s_work_nvlt_53_34","chapterId":"ch_work_nvlt_53","text":"《吳志》曰：劉繇字正禮，兄岱，字公山，平原陶丘洪荐，欲令舉茂才，刺史曰：前年舉公山，奈何复舉正禮乎，洪曰：若明使君用公山於前，擢正禮於後，所謂御二龍於長涂，騁騏骥於千里，不亦可乎。","sortOrder":34},
  {"id":"s_work_nvlt_53_35","chapterId":"ch_work_nvlt_53","text":"王隱《晉書》曰：杜夷隱身不仕，镇東軍司顧榮等，荐夷於相國府，元帝以為儒林祭酒。","sortOrder":35},
  {"id":"s_work_nvlt_53_36","chapterId":"ch_work_nvlt_53","text":"徐廣《晉紀》曰：張華少自牧羊，而篤志好學，初為縣吏，盧钦奇其才，數稱荐之。","sortOrder":36},
  {"id":"s_work_nvlt_53_37","chapterId":"ch_work_nvlt_53","text":"【詔】魏明帝詔曰：世之质文，隨教而变，兵亂已來，經學废絕，後生進趨，不由典謨，豈朕訓导未洽，將進用者不以德顯乎，其令郎吏學通一經，才任牧民，博士策试，擢其高第者亟用，其浮華不務道本者，皆罢退之。","sortOrder":37},
  {"id":"s_work_nvlt_53_38","chapterId":"ch_work_nvlt_53","text":"梁任昉求荐士詔曰：夫進賢茂賞，蔽善明罰，前王盛則，鹹必由之，朕纂統鸿業，夤畏大寶，思用俊異，协贊雍熙，歷聽九工，物色舆皂，而白駒盈穀，長楚未刈，所以臨朝永叹，日昃伊佇，便可博詢卿士，各舉所知，將量才授能，擢以不次，庶同則哲之明，稱朕急賢之旨。","sortOrder":38},
  {"id":"s_work_nvlt_53_39","chapterId":"ch_work_nvlt_53","text":"隨江總舉士詔曰：尧施諫鼓，禹拜昌言，求之異等，久著前册，舉以滯淹，复聞昔典，斯乃治道之深規，帝王之切務，朕以寡昧，丕承洪緒，未明虛己，日旰興懷，萬機多紊，四聰弗達，思聞謇諤，采其默語，王公以下，各荐所知，傍詢管库，爰及舆皂，一介有能，片言可用，朕親加聽覽，佇茲啟沃。","sortOrder":39},
  {"id":"s_work_nvlt_53_40","chapterId":"ch_work_nvlt_53","text":"【表】後漢班固為第五倫荐謝夷吾表曰：夷吾才兼四科，行包九德，奉法智察，有召公之風，居俭履約，紹公儀之操，雖密勿在公，身出心隱，不徇名以求譽，不馳骛以要寵，誠社稷之蓍龟，大漢之甍棟，宜當拔擢，使登鼎司，原乞骸骨，更授夷吾。","sortOrder":40},
  {"id":"s_work_nvlt_53_41","chapterId":"ch_work_nvlt_53","text":"後漢蔡邕荐皇甫規表曰：昔孝文慍匈奴之事，思李牧於前代，孝宣忿奸猾之不散，舉張敞於亡命，論其武勞，則漢室之扞城，課其文德，則皇家之腹心。","sortOrder":41},
  {"id":"s_work_nvlt_53_42","chapterId":"ch_work_nvlt_53","text":"後漢孔融荐祢衡表曰：衡淑质貞亮，英才卓荦，初涉藝文，升堂睹奧，目所一見，辄誦於口，耳所暫聞，不忘於心，性與道［原訛通，據冯校本改。］合，思若有神，忠果正直，志懷霜雪，見善若驚，疾惡若讎，鷙鳥累百，不如一鹗，飛辯騁辭，溢氣坌涌，解疑釋結，臨敵有餘，昔贾誼求试屬國，诡系单於，終軍欲以長纓，牵致劲越，弱冠慷恺，前世美之，女［《文選》三十七作如，此訛。］睹得龍躍天衢，振翼雲漢，扬聲紫微，垂光虹霓，鈞天廣樂，必有奇麗之觀，帝室皇居，必畜非常之寶。","sortOrder":42},
  {"id":"s_work_nvlt_53_43","chapterId":"ch_work_nvlt_53","text":"魏陳思王曹植自试表曰：士之生世，入則事父，出則事君，事父尚於榮親，事君貴於興國，故慈父不能愛無益之子，仁君不能畜無用之臣，夫論德而授官者，成功之君也，量能而受爵者，畢命之臣也，故君無虛授，臣無虛受，虛授謂之谬舉，虛受謂之尸祿，昔二虢不辭兩國之任，其德厚也，旦奭不讓燕魯之封，其功大也，今臣無德可述，無功可紀，上慚玄冕，俯愧朱绂，西有违命之蜀，東有不臣之吳，使邊境未得脱甲，謨士未得高枕，而高鳥未絓於輕繳，潛魚未懸於鉤餌者，恐釣射之術，或未盡也，夫君之寵臣，欲除患興利，臣之事君，必殺身靜亂，以功報主也，如微才弗试，没世無聞，徒榮其軀而丰其體，生無益於事，死無損於數，虛荷上位，而忝重恩，禽息鳥视，終於白首也，常恐先朝露，填溝壑，墳土未乾，而身名併滅，冀以尘霧之微，補益山海，螢燭末光，增辉日月。","sortOrder":43},
  {"id":"s_work_nvlt_53_44","chapterId":"ch_work_nvlt_53","text":"又表曰：五帝之世非皆智，三季之末非皆愚，用與不用，知與不知也，夫相者文德昭者也，將者武功烈者也，文德昭則可以匡國朝，叙百揆，稷契夔龍是矣，武功烈則可以征不庭，廣邦境，南仲方叔是矣，昔伊尹之為媵臣，至賤也，呂尚之處屠釣，至陋也，及其見舉於湯文，誠道合志同，豈复假近習之荐，因左右之介哉，昔騏骥之於吳坂，可謂困矣，及其伯樂相之，孫子御之，形體不勞，而坐取千里，伯樂善御馬，明君善御臣，誠任賢使能之明效也，昔段幹木修德於闾阎，秦軍為之輟攻，而文侯以安，穰苴授節於邦境，燕晉為之退師，而景公無患，皆簡德尊賢之所致也，原陛下垂高宗傅巖之明，以顯中興之功。","sortOrder":44},
  {"id":"s_work_nvlt_53_45","chapterId":"ch_work_nvlt_53","text":"魏殷褒荐朱倫表曰：蓋聞虞書非俊乂無以光帝載，西伯非髦士無以开王業，是故高世之主，必廣登命之禮，有為之君，務通賢者之路，所以成大治也，切見同郡朱倫，字文信，天真清亮，雅性忠篤，純粹足以激清源，美行足以廣風俗，當仁不讓，見德思義，疏達之才，強記博聞，飛辭抗論，骆驿奇逸，誠當世之俊異，一時之秀出也，如得毗佐铨衡，翼亮右曹，濟濟之觀，足用華國。","sortOrder":45},
  {"id":"s_work_nvlt_53_46","chapterId":"ch_work_nvlt_53","text":"晉庾亮荐翟陽［按當作湯，郭翻表曰：蓋聞舉逸拔幽，帝王之高士，旌德禮賢，治道之所先，是以西伯摽渭濱之伏，而帝基以隆，漢高延商洛之隱，而王道以固，仄陋無明敭之稱，空穀废白駒之詠，恐千里之足，屈於槽櫪之下，贊世之才，委於垄畝之間，若解其巾褐，服以纓冕，必能翼贊皇極，敷訓彝倫。］］","sortOrder":46},
  {"id":"s_work_nvlt_53_47","chapterId":"ch_work_nvlt_53","text":"梁元帝荐鮑幾表曰：旌蒲出魯，贲帛歸齊，頌聲既興，盛業斯在，幾忠公抗直，出宰廉平，將齊毛玠古人之服，實同吳隱酌水之廉，臣才非往哲，識愧前修，輕陳聽覽，伏待鈇鉞。","sortOrder":47},
  {"id":"s_work_nvlt_53_48","chapterId":"ch_work_nvlt_53","text":"梁沈約荐劉粲表曰：陛下則天开業，冠帶要荒，輶軒韦轂，交軫於遐路，舍筑投竽，相望於魏闕，或以开坼未采，管库遺賢，執戟忘疲，倚辀不息。","sortOrder":48},
  {"id":"s_work_nvlt_53_49","chapterId":"ch_work_nvlt_53","text":"梁劉孝儀為江仆射禮荐士表曰：陛下緝禮裁樂，化俗移風，當扆思治，分宵夢相，枯岸之珠既論，润山之玉已荐，伏見兼太學博士會稽贺玚，字德璉，幼能斧藻，長則琢磨，結卷就賢，擔簦來學，乡塾染其丹采，朋友扣其洪鍾，聲無愧於東筠，材有逾乎西杞，如使聯事宗伯，握蘭建禮，庶用得其才，人知自勖，臣鑒非止水，職豫搜扬，前竭諛聞，先自乡曲。","sortOrder":49},
  {"id":"s_work_nvlt_53_50","chapterId":"ch_work_nvlt_53","text":"又為江侍中荐士表曰：臣聞天道不言，資寒暑而成歲，宸居垂拱，寄守宰以宣風，若夜魚不欺，朝琴在奏，則殘殺自去，汾射可追，伏見镇北府水曹參軍濟陽江興，字休恭，立身貞白，操業清廉，頗涉書記，弥閒刀筆，前攝縣沮漳，無傷錦製，巡行淮海，不忝繡衣，若處以百里之邑，使导一乡之賦，必能治文無害，迄用有成，臣舉不避族，非欲異姓居後，知人為難，寔緣所悉而荐。","sortOrder":50},
  {"id":"s_work_nvlt_53_51","chapterId":"ch_work_nvlt_53","text":"北齊邢子才為李衛軍疾以國子祭酒讓東平王表曰：臣聞運舟歸於積水，致遠在於逸足，未有涓澮之流，可成奔飛之用，駑蹇之乘，而有滅没之功，既列趙衰先人之敏，請同虞丘退身之義，具官臣某，民望時宗，聲實攸在，斧藻川流，雕篆霞蔚，蕉蒲既茂，枝葉寔繁，故以學窮齊魯，聲高梁魏，詔美司朝，佥諧允在，伏原回恩徙授，以答具瞻。","sortOrder":51},
  {"id":"s_work_nvlt_53_52","chapterId":"ch_work_nvlt_53","text":"【箋】魏應璩荐和慮則箋曰：璩聞唐尧因群士以興治，齊桓假眾能以定業，是故八元進則太平之化成，六賢用則九合之功立，切見同郡和模，字慮則，质性純粹，體度貞正，履仁蹈義，動循軌禮，方今海內企踵，欣慕捉發之德，山林投褐，思望旌弓之招，寔英奇叙用之時，貢達進致之良秋也，令夜光之璧，顯价於和氏之肆，千里之足，定功於伯樂之庭，庶有以宣明大道，光益時化。","sortOrder":52},
  {"id":"s_work_nvlt_53_53","chapterId":"ch_work_nvlt_53","text":"又荐費禕箋曰：璩聞景雲浮則應龍翔，治道明則俊乂臻，是故良哉之歌，興於唐尧之世，多士之頌，起於周文之朝。","sortOrder":53},
  {"id":"s_work_nvlt_53_54","chapterId":"ch_work_nvlt_53","text":"晉孫楚荐傅長虞箋曰：楚聞騏骥不遺能於伯樂，良寶不藏耀於卞和，是以辉光夜射，价連秦趙，飛驷絕影，終朝千里，物尚有之，士亦宜然。","sortOrder":54},
  {"id":"s_work_nvlt_53_55","chapterId":"ch_work_nvlt_53","text":"晉庾闡荐唐箋曰：蓋桂林生於五嶺，杞梓出於南荆，夫以卉木之盛，猶載在方志，况千里之朝，懷其良彦，而使人滯於常流，莫登於龍津者乎，郡功［原訛公，據冯校本改。］曹史泉陵唐，永延，［句有脱文。］履道敏素，和而有正，立身持操，行著一邦，若得驂軌鸞衡，服襄駿足，則機石之良選，可以對扬萬里者也。","sortOrder":55},
  {"id":"s_work_nvlt_53_56","chapterId":"ch_work_nvlt_53","text":"【啟】齊王融求试效啟曰：臣聞春鹒秋蟀，集候相悲，露木風螢，臨年共悅，夫惟動植，且或有心，况在生靈，而能無感，夫君道含弘，臣術無隱，翁歸乃居中自是，充國曰莫若老臣，切慕前修，敢蹈輕節，雖冒不媒之鄙，式罄奉公之誠，抑又唐尧在上，不參二八，管夷吾恥之，臣亦恥之。","sortOrder":56},
  {"id":"s_work_nvlt_53_57","chapterId":"ch_work_nvlt_53","text":"梁元帝啟東宮荐石門侯啟曰：切以鳳鳴朝陽，必資藍田之寶，龍門點額，亦俟堂溪之珍，是以紫玉見稱，黃金為貴，文傳夢鳥，學重靈蛇，點漆凝脂，事逾衛玠，浑金璞玉，才疋山涛，昔翟湯隱逸，見稱庾亮，陳平器局，被荐無知，以人废言，誠增竦詟，進賢上賞，伏待慈照。","sortOrder":57},
  {"id":"s_work_nvlt_53_58","chapterId":"ch_work_nvlt_53","text":"梁丘遲答舉秀才啟曰：方今八友盈庭，五承在幄，七教畢脩，九攻具舉，猶乃物色關屠，夢想巖釣，故已天不愛寶，野無遺賢，辄仰宣皇猷，俯罄愚蔽，觇察衡阎，詢事茅草，如有片言入善，一介可題，謹聞絳闕，恭奏青蒲。","sortOrder":58},
  {"id":"s_work_nvlt_53_59","chapterId":"ch_work_nvlt_53","text":"【教】宋孝武臨徐兖二州搜扬教曰：徐方地兼梁楚，秀士攸出，兖土樂頌所流，風禮自古，豈不異人比肩，鸿才世及，或疏散山林，不聞進達，或栖息闾阎，懷寶待耀，孝性義門，明經善政者，所在搜扬舉進，鹹用名聞。","sortOrder":59},
  {"id":"s_work_nvlt_53_60","chapterId":"ch_work_nvlt_53","text":"梁王僧孺至南海郡求士教曰：是以文舉下車，寤夢於根雉，長孫入境，明發於龍丘，此境三閩奧壤，百越舊都，漢开吳別，分星畫部，風序泱泱，衣簪斯盛，其川嶽所產，豈直明珠大貝，桂蠹翠羽而已哉，孝實人經，則有羅威唐頌，學惟業本。又聞陳元士燮，至於高尚獨往，相望於〈山其〉巖，懷仁抱義，繼蹤於前史。","sortOrder":60},
  {"id":"s_work_nvlt_53_61","chapterId":"ch_work_nvlt_53","text":"【書】漢張敞與朱邑書曰：明主遊心太古，廣延茂士，此誠忠臣竭思之時也，值敞遠守剧郡，馭於繩墨，焜臆約結，固無奇矣，足下以清明之德，掌周稷之官，昔陳平雖賢，須魏倩而後進，韓信雖奇，賴萧何而後信，故士各達其時之英雋，若必伊尹呂望而後荐之，則此人不因足下而進矣，邑感敞言，荐賢士大夫，多得其助者。","sortOrder":61},
  {"id":"s_work_nvlt_53_62","chapterId":"ch_work_nvlt_53","text":"魏阮籍與晉文王荐盧景宣書曰：是以八士歸周，周道以隆，虞舜登庸，元凯鹹事，誠以邓林崑吾，翔鳳所栖，懸黎和肆，垂棘所集，伏見鄙州別駕盧播，字景宣，耽道悅禮，伏義依仁，研精墳典，升堂睹奧，若得佐時理物，則政事之器，衔命聘享，則专對之才，潛心圖籍，文學之宗，敷藻載述，良史之表。","sortOrder":62},
  {"id":"s_work_nvlt_53_63","chapterId":"ch_work_nvlt_53","text":"◇奉使","sortOrder":63},
  {"id":"s_work_nvlt_53_64","chapterId":"ch_work_nvlt_53","text":"《周官》曰：使適四方，朝觐宗遇會同，君之禮也，存觐覜省聘問，臣之禮也。","sortOrder":64},
  {"id":"s_work_nvlt_53_65","chapterId":"ch_work_nvlt_53","text":"《毛詩》曰：四牡，勞使臣之來也，有功而見知則說矣，四牡騑騑，周道逶遲。豈不懷歸，王事靡盬，我心傷悲。","sortOrder":65},
  {"id":"s_work_nvlt_53_66","chapterId":"ch_work_nvlt_53","text":"又曰：皇皇者華，君遣使臣也，送之以禮樂，言遠而有光華也，皇皇者華，於彼原隰，駪々征夫，每懷靡及。","sortOrder":66},
  {"id":"s_work_nvlt_53_67","chapterId":"ch_work_nvlt_53","text":"《左傳》曰：齊侯以諸侯之師侵蔡，蔡潰，遂伐楚，楚子使與師言曰：君處北海，寡人處南海，惟是風馬牛不相及也，不虞君之涉吾地也何故，管仲曰：昔召康公命我先君太公曰：五侯九伯，汝實征之，爾貢苞茅不入，王祭不供，無以縮酒，寡人是徵，昭王南征而不复，寡人是問，對曰：貢之不入，寡君之罪也，敢不供給，昭王之不复，君其問諸水濱。","sortOrder":67},
  {"id":"s_work_nvlt_53_68","chapterId":"ch_work_nvlt_53","text":"《穀梁傳》曰：季孫行父禿，晉郄克眇，衛孫良夫跛，同時而聘於齊，齊使禿者迓禿者，眇者迓眇者，跛者迓跛者，萧同叔子處台上而笑之，聞於客，客不說而去，相與立胥闾而語，移日不解，齊人有知之者曰：齊之患自此始也。","sortOrder":68},
  {"id":"s_work_nvlt_53_69","chapterId":"ch_work_nvlt_53","text":"《論語》曰：蘧伯玉使人於孔子，孔子與之坐而問焉，曰：夫子何為，對曰：夫子欲寡其過而未能也，使者出，子曰：使乎使乎，為使之難，不辱君命。","sortOrder":69},
  {"id":"s_work_nvlt_53_70","chapterId":"ch_work_nvlt_53","text":"《晏子》曰：晏子短，使楚，楚為小門而延晏子，晏子不入，曰：使狗國者從狗門入，而臣使楚，不當從狗門入，［事具人部嘲戲篇。］","sortOrder":70},
  {"id":"s_work_nvlt_53_71","chapterId":"ch_work_nvlt_53","text":"《史記》曰：趙平原君使於春申君，趙使欲夸楚，為玳瑁簪，刀劍悉以珠飾之，春申君客三千餘人，上客皆躡珠履，以見趙使，趙使大慚。","sortOrder":71},
  {"id":"s_work_nvlt_53_72","chapterId":"ch_work_nvlt_53","text":"又曰：陆贾，楚人，以客從高祖定天下，名有口辯，居左右，常使諸侯，時中國初定，尉他平南越，因王之，高祖使贾賜他印，為南越王，贾至，尉他魁結箕踞見贾，贾因說他曰：足下中國之人，親戚崑弟墳墓在真定，今足下欲以區區之越，與天子抗衡為敵國，禍且及身矣，他乃蹶然起坐，謝贾曰：居蠻夷之中久，殊失禮儀。","sortOrder":72},
  {"id":"s_work_nvlt_53_73","chapterId":"ch_work_nvlt_53","text":"【詩】北齊裴讓之公馆宴詶南使徐陵詩曰：嵩山表京邑，鍾嶺對江津，方域殊風壤，分野居星辰，出境君圖事，尋盟我恤鄰，有才稱竹箭，無用忝絲纶，列樂歌鍾响，張旃玉帛陳，皇華徒受命，延譽本無因，韓宣將聘楚，申胥欲去秦，方期飲河朔，翻屬臥漳濱，禮酒盈三獻，賓筵盛八珍，歲稔鳴銅雀，兵戢坐金人，雲來朝起蓋，日落晚催輪，異國猶兄弟，相知無舊新。","sortOrder":73},
  {"id":"s_work_nvlt_53_74","chapterId":"ch_work_nvlt_53","text":"北齊裴讷之鄴馆公宴詩曰：晉楚敦，盟好，乔禮［文苑英華作侨札。］同心賞，禮成樽俎陳，樂和金石响，朝雲駕馬進，晓日乘龍上，双闕表皇居，三台映仙掌，當階篁筱密，約岸荷蕖長，束帶盡欣娱，誰言骛歸兩。","sortOrder":74},
  {"id":"s_work_nvlt_53_75","chapterId":"ch_work_nvlt_53","text":"周庾信將命至鄴詩曰：大國脩聘禮，親鄰自此敦，張旃事原隰，負扆報成言，西過犯風露，北指度轘轅，交歡值公子，展禮觌王孫，何以譽嘉树，徒欣賦采蘩，四牢盈折俎，三獻滿罍樽，人臣無境外，何由欣此言，風俗既险阻，山河不复論，無因旅南馆，空欲祭西門，眷然惟此別，夙期幸共存。","sortOrder":75},
  {"id":"s_work_nvlt_53_76","chapterId":"ch_work_nvlt_53","text":"又酬祖正員詩曰：我皇臨九有，聲教洎無隄，興文盛禮樂，偃武息民黎，承乏驅騏馬，旌旃事鼓鞞，古碑文字盡，荒城年代迷，被隴文瓜熟，交塍香穗低，投琼實有意，報李更無蹊。","sortOrder":76},
  {"id":"s_work_nvlt_53_77","chapterId":"ch_work_nvlt_53","text":"隋盧思道赠司馬幼之南聘詩曰：故交忽千里，輶車莅遠盟，幽人重離別，握手送行行，晚霞浮極浦，落景照長亭，拂霧扬龍節，乘風溯鳥旌，楚山百重映，吳江萬仞清，夏雲樓閣起，秋涛帷蓋生，陆侯持寶劍，終子系長纓，前脩亦何遠，君其勖令名。","sortOrder":77},
  {"id":"s_work_nvlt_53_78","chapterId":"ch_work_nvlt_53","text":"隋虞世基接北使詩曰：會玉二崤至，瑞節三秦歸，林蝉疏欲盡，江雁斷還飛，牆垣崇客馆，旌蓋入王畿，共此敦封植，方欣篤纻衣。","sortOrder":78},
  {"id":"s_work_nvlt_53_79","chapterId":"ch_work_nvlt_53","text":"【論】梁元帝鄭眾論曰：漢世衔命匈奴，困而不辱者，二人而已，子卿手持漢節，臥伏冰霜，仲師固無下拜，隔絕水火，况复風生稽落，日隱龍堆，翰海飛沙，皋蘭走雪，豈不酸鼻痛心，憶雒陽之宮陛，屑泣橫悲，想長安之城闕，直以為臣之道，義不為生，事君之節，生為義盡，豈望拔幽泉，出重仞，經長樂，抵未央，及還望塞亭，來依候火，傍觀上郡，侧眺雲中，雖在己之原自隆，而於時之報未盡。","sortOrder":79},
  {"id":"s_work_nvlt_53_80","chapterId":"ch_work_nvlt_53","text":"【書】後漢孔融與韦林甫書曰：使君足下，懷遠垂勋，西戎即叙，前別意恨，甚多不悉，辛從事至，承獲所訊，喜而起居，不恙而到也，雲便結驷，径至舊治，西土之人，宗服令德，解仇崇好，以順風化，萬里雍穆，如樂之和，雖為國家威靈感應，亦實士縠堪事之效也，昔伯安由幽都而登上司，子琰以豫州而取宰相，近事未遠，當勉功業，以丰此慶耳，聞僻疾動，不得复與足下，岸帻廣坐，舉杯相於，［冯校本作扢。］以為邑邑，前日元［原訛光，據冯校本改。］將來，雅度弘毅，伟［魏志十荀彧傳註，伟下有世字，此脱。］之器也，昨仲將复來，文敏篤誠，保家之主也，不意双珠，近出老蚌，甚珍貴之，遣書通心。","sortOrder":80},
  {"id":"s_work_nvlt_53_81","chapterId":"ch_work_nvlt_53","text":"梁任孝恭為李慶州孟堅使與覃無名書曰：昔陆贾皇華，定交知於南越，長卿披繡，通夷险於夜郎，故傳美於往書，流芳於篆素，足下南中盛族，嶺表豪門，籍譽既深，承芳已舊，但道曠風雲，論平生而是即，江山間阻，衔杯酌以何因，空想神魂，徒勞夢寐，仆世禀威儀，門勒鍾鼎，提戈海嶽，推轂數千，逮我不才，無兼文武，鸿私弗替，應茲阃外，麾蓋所臨，寔宣慈造，足下刺舉一隅，同奉家國，進止之宜，寔俟高筭。","sortOrder":81},
  {"id":"s_work_nvlt_53_82","chapterId":"ch_work_nvlt_53","text":"梁劉孝儀北使還與永丰侯書曰：足踐寒地，身犯朔風，暮宿客亭，晨灼謁舍。飄飖辛苦，迄屆氈乡，雜种覃化，頗慕中國，兵傳李緒之法，樓擬衛律所治，而毳幕難淹，酪漿易餍，王程有限，時及玉關，射鹿胡奴，乃共歸國，刻龍漢節，還持入塞，馬衔苜蓿，嘶立故墟，人獲蒲萄，歸种舊里，稚子出迎，善鄰相勞，倦握蟹螯，亟覆虾碗，未改朱顏，略多自醉，用此終日，亦以自娱。","sortOrder":82},
  {"id":"s_work_nvlt_53_83","chapterId":"ch_work_nvlt_53","text":"《藝文類聚》　唐·欧陽詢","sortOrder":83},
  {"id":"s_work_nvlt_54_1","chapterId":"ch_work_nvlt_54","text":"卷五十四刑法部","sortOrder":1},
  {"id":"s_work_nvlt_54_2","chapterId":"ch_work_nvlt_54","text":"○刑法","sortOrder":2},
  {"id":"s_work_nvlt_54_3","chapterId":"ch_work_nvlt_54","text":"◇刑法","sortOrder":3},
  {"id":"s_work_nvlt_54_4","chapterId":"ch_work_nvlt_54","text":"《爾雅》曰：律，法也。","sortOrder":4},
  {"id":"s_work_nvlt_54_5","chapterId":"ch_work_nvlt_54","text":"又，律法铨也，［易坎卦，主法律，铨衡輕重也。］","sortOrder":5},
  {"id":"s_work_nvlt_54_6","chapterId":"ch_work_nvlt_54","text":"《管子》曰：正月之朔，百吏在朝，君乃出令，布憲於國，五乡五師五屬大夫，皆受憲於君矣。","sortOrder":6},
  {"id":"s_work_nvlt_54_7","chapterId":"ch_work_nvlt_54","text":"又曰：法者所以興功懼暴，律者所以定分止爭也。","sortOrder":7},
  {"id":"s_work_nvlt_54_8","chapterId":"ch_work_nvlt_54","text":"又曰：凡國無法，則眾不知所為，無度則事無儀，有法不正，有度不直，則治僻，治僻則國亂，故曰：正法直度，罪殺無赦，殺戮必信，民畏而懼，武威既明，令不再行。","sortOrder":8},
  {"id":"s_work_nvlt_54_9","chapterId":"ch_work_nvlt_54","text":"又曰：法者，天地之位，象四時之行，以治天下，四時之行，有寒有暑，聖人法之，故有文有武，天地之位，有前有後，有左有右，聖人法之，以建經紀，春生於左，秋殺於右，夏長於前，冬藏於後，生長之事文也，收藏之事武也，是故文事在左，武事在右，聖人法之，以行法令，以治事理也。","sortOrder":9},
  {"id":"s_work_nvlt_54_10","chapterId":"ch_work_nvlt_54","text":"《申子》曰：君必有明法正義，若懸權衡以稱輕重，所以一群臣也。","sortOrder":10},
  {"id":"s_work_nvlt_54_11","chapterId":"ch_work_nvlt_54","text":"又曰：尧之治也，善明法察令而已，聖君任法而不任智，任數而不任說，黃帝之治天下，置法而不变，使民而安不安，［《太平御覽》六百三十八二字無。］樂其法也。","sortOrder":11},
  {"id":"s_work_nvlt_54_12","chapterId":"ch_work_nvlt_54","text":"又曰：昔七十九代之君，法製不一，號令不同，然而俱王天下，何也，必當國富而粟多也。","sortOrder":12},
  {"id":"s_work_nvlt_54_13","chapterId":"ch_work_nvlt_54","text":"《家語》曰：孔子初仕，為中都宰，［中都，魯邑。］製為養生送死之節，長幼異食，強弱異任，男女別涂，路不拾遺，器不雕伪，市不二价，行之一年，而四方諸侯皆則焉，定公謂孔子曰：學子之法，以治魯國，何如，孔子對曰：雖天下可，何但魯國而已矣。","sortOrder":13},
  {"id":"s_work_nvlt_54_14","chapterId":"ch_work_nvlt_54","text":"《韓子》曰：治大國而數变法，則民苦之，是以有道之君，貴虛靜而重变法。","sortOrder":14},
  {"id":"s_work_nvlt_54_15","chapterId":"ch_work_nvlt_54","text":"又曰：聖人立法，賞足以勸善，威足以勝暴，備足以必完。","sortOrder":15},
  {"id":"s_work_nvlt_54_16","chapterId":"ch_work_nvlt_54","text":"又曰：釋法術而心治，尧不能正一國，使中主守法術，拙匠執規矩尺寸，則萬不失一。","sortOrder":16},
  {"id":"s_work_nvlt_54_17","chapterId":"ch_work_nvlt_54","text":"又曰：董安於行石阜山中，見深涧峭如牆，深百仞，因問其乡左右曰：人嘗有入者乎，對曰：無有，安於喟然叹曰：吾能治矣，使吾法之無赦，猶入涧之必死也，則民莫之犯，何為不治，［事具水部涧篇。］","sortOrder":17},
  {"id":"s_work_nvlt_54_18","chapterId":"ch_work_nvlt_54","text":"又曰：越王問於大夫种曰：吾欲伐吳，可乎，對曰：可矣，君賞厚而信，罰嚴而必，君欲知之，何不试焚宮室，於是遂焚宮室，民莫救火，乃下令曰：人救火而死者，比敵死之賞，勝火而死者，比勝敵之賞，不救火，若比降北之罪，民之涂其體，被濡衣，走火者，左三千人，右三千人，此知必勝之势也。","sortOrder":18},
  {"id":"s_work_nvlt_54_19","chapterId":"ch_work_nvlt_54","text":"《文子》曰：文子問老子，法安所生，曰：法生於義，義生於眾，適合乎人心，此治之要也，法非從天下，非從地出，發於人間，及己自正。","sortOrder":19},
  {"id":"s_work_nvlt_54_20","chapterId":"ch_work_nvlt_54","text":"《申子》曰：君子之所以尊者令，令不行，是無君也，故明君慎令。","sortOrder":20},
  {"id":"s_work_nvlt_54_21","chapterId":"ch_work_nvlt_54","text":"《慎子》曰：尧為匹夫，不能鄰家至，西南面而王，則令行禁止，由此觀之，賢未足以服不肖，而势位足以屈賢也。","sortOrder":21},
  {"id":"s_work_nvlt_54_22","chapterId":"ch_work_nvlt_54","text":"又曰：法之功，莫大使私不行，君之功，莫大使民不爭，今立法而行私，是與法爭，其亂甚於無法，立君而尊賢，是賢與君爭，其亂甚於無君，故有道之國，法立則私善不行，君立則賢者不尊，民一於君，斷於法，國之大道也。","sortOrder":22},
  {"id":"s_work_nvlt_54_23","chapterId":"ch_work_nvlt_54","text":"又曰：故治國無其法則亂，守法而不变則衰，有法而行私，謂之不法，以力役法者，百姓也，以死守法者，有司也，以道变法者，君長也。","sortOrder":23},
  {"id":"s_work_nvlt_54_24","chapterId":"ch_work_nvlt_54","text":"《漢書》曰：漢興，高祖初入關，約法三章，曰：殺人者死，傷人及盜抵罪，蠲削煩苛，兆民大說，其後四夷未附，兵革未息，三章之法，不足以御奸，於是相國萧何，捃摭秦法，取宜於時者作律。","sortOrder":24},
  {"id":"s_work_nvlt_54_25","chapterId":"ch_work_nvlt_54","text":"又曰：杜周為廷尉，其治獄仿張湯，而善伺候，上所欲挤者，因而陷之，上所欲釋，久系待問，而微見其冤状，客有謂周曰：君為天下决平，不修三尺法，［以三尺簡書法律也。］专以人主意指為獄，獄者固如是也，周曰：三尺安出哉，前主所以著為律，後主所是疏為今［《太平御覽》六三七作令。］當時為是，何古之法。","sortOrder":25},
  {"id":"s_work_nvlt_54_26","chapterId":"ch_work_nvlt_54","text":"又曰：時上方向文學，張湯决大獄，欲傅古議，乃請博士弟子治尚書春秋，補廷尉使，［漢書五十九張湯傳作史。］平疑法，奏谳疑，事必奏，先為上分別其原，上所是，受而著谳法，廷尉挈令，扬主之明。","sortOrder":26},
  {"id":"s_work_nvlt_54_27","chapterId":"ch_work_nvlt_54","text":"《東觀漢記》曰：陳寵曾祖父鹹，成哀間，以明律令，為侍御史，王莽篡位，父子相將歸乡里，閉門不出入，收家中律令文書，壁藏之，以俟明王，鹹常敕戒子孫，為人議法，當依輕，雖有百金之利，無與人重比，故世謂陳氏持法宽。","sortOrder":27},
  {"id":"s_work_nvlt_54_28","chapterId":"ch_work_nvlt_54","text":"范晔《後漢書》曰：鄭弘，建初初，為尚書令，舊製，尚書郎限滿，補縣長，令史報丞尉，弘奏以為台職雖尊，而酬賞甚薄，至於關選，多無樂者，謂使郎補千戶，［後漢書六十三鄭弘傳作石。］令史為長，帝從其議，弘前後所陳，有補益王政者，著之南宮，以為故事。","sortOrder":28},
  {"id":"s_work_nvlt_54_29","chapterId":"ch_work_nvlt_54","text":"《說文》曰：科，程也，程，品也，十發為程，十程為寸。","sortOrder":29},
  {"id":"s_work_nvlt_54_30","chapterId":"ch_work_nvlt_54","text":"楊雄剧秦美新論曰：金科玉條，［科條謂所施也，律金玉，當珍之。］","sortOrder":30},
  {"id":"s_work_nvlt_54_31","chapterId":"ch_work_nvlt_54","text":"《鹽鐵論》曰：昔秦法繁於秋荼，而密於凝脂，然上下相趨，奸伪萌生。","sortOrder":31},
  {"id":"s_work_nvlt_54_32","chapterId":"ch_work_nvlt_54","text":"又曰：夫善言天者，合之於人，善言古者，考之於今，二尺四寸之律，古今一也。","sortOrder":32},
  {"id":"s_work_nvlt_54_33","chapterId":"ch_work_nvlt_54","text":"《風俗通》曰：咎陶謨虞，始造律，萧何成九章，此關諸百王，不易之道也，時所製曰令，漢書著於甲令，夫吏者治也，當先自正，然後正人，故文書下如律令，言當承憲履繩動，不失律令也。","sortOrder":33},
  {"id":"s_work_nvlt_54_34","chapterId":"ch_work_nvlt_54","text":"王隱《晉書》曰：荀勖與贾充，共定律令，班下施用，各加祿賜。","sortOrder":34},
  {"id":"s_work_nvlt_54_35","chapterId":"ch_work_nvlt_54","text":"【詩】周庾信正旦上司憲詩曰：詰旦啟門欄，繁辭擁筆端，蒼鷹下獄吏，獬豸飾刑官，司朝引玉節，盟載捧珠盤，孟門久失路，扶搖忽上摶，栖乌還得府，弃馬复歸欄，榮華名義重，慮薄報恩難，枚乘還起疾，貢禹遂彈冠，方乘莲葉劍，未用竹根丹，一知懸象法，誰思垂釣竿。","sortOrder":35},
  {"id":"s_work_nvlt_54_36","chapterId":"ch_work_nvlt_54","text":"【賦】晉傅鹹明意賦曰：侍御史傅鹹，奉詔治獄，作賦用明意雲，舍控款以弥載，令栖遲以淹留，吏砥身以存公，古有死而無柔，彼背正以從邪，我没世而是尤，敷腎腸以為效兮，豈文飾之足脩，感恩输命，心口自滅，加我數年，竭力效節，春秋既不吾與，日月忽其不屈，周道兮如砥，言人兮是由，材曲兮枉桡，朽木兮難抽。","sortOrder":36},
  {"id":"s_work_nvlt_54_37","chapterId":"ch_work_nvlt_54","text":"晉傅玄釋法篇曰：釋法任情，奸佞在下，多疑少决，譬執腐索，以御奔馬，专任刑名，民不聊生，通儒達道，政乃升平，浩浩大海，百川歸之，洋洋聖化，九服仰之，春風畅物，秋霜肅殺，同則相濟，異若胡越。","sortOrder":37},
  {"id":"s_work_nvlt_54_38","chapterId":"ch_work_nvlt_54","text":"【贊】梁昭明太子爾雅製法則贊曰：惟斯法則，信如四時，嚴此刑政，刑輕罪疑，霜威已振，民不敢欺。","sortOrder":38},
  {"id":"s_work_nvlt_54_39","chapterId":"ch_work_nvlt_54","text":"後漢李尤鞠城銘曰：員鞠方牆，仿象陰陽，法月衡對，二六相當，建長立平，其列有常，不以親疏，不有阿私，端心平意，莫怨其非，鞠政由然，况乎執機。","sortOrder":39},
  {"id":"s_work_nvlt_54_40","chapterId":"ch_work_nvlt_54","text":"【令】魏陳王曹植黃初五年令曰：夫遠不可知者天也，近不可知者人也，傳曰：知人則哲，尧猶病諸，諺曰：人心不同，若其面焉，唯女子與小人為難養也，近之則不遜，遠之則怨，詩雲，忧心悄悄，慍於群小，自世間人，或受寵而背恩，或無故而叛，［本集叛上有入字。］违顧左右，曠然無信，大嚼者咋斷其舌，右手執斧，左手執鉞［文馆詞林六百九十五二字無。］傷夷，一身之中，尚有不可信，况於人乎，唯無深瑕潛衅，隱過匿愆，乃可以為人，諺曰：穀千駑，不如養一驢，［文馆詞林作骥。］又曰：穀駑養虎，大無益也，乃知韓昭使藏弊袴，良有以也，使臣有三品，有可以仁義化者，有可以恩惠驅者，不足以导之，則當以刑罰使之，刑罰复不足以率之，則明所以不畜，故唐尧至仁，不能容無益之子，湯武至聖，不能養無益之臣，九折臂知為良医，吾知所以待下矣，諸吏各敬爾在位，孤推一槩之平，功之宜賞，於疏必與，罪之宜戮，在親不赦，此令之行，有若皎日，於戲群司，其覽之哉。","sortOrder":40},
  {"id":"s_work_nvlt_54_41","chapterId":"ch_work_nvlt_54","text":"又黃初六年令曰：身輕於鸿毛，而謗重於泰山，賴蒙帝主天地之仁，违百寮之典議，赦三千之首戾，反我舊居，袭我初服，雲雨之施，焉有量哉，孤以何功，而納斯貺，富而不吝，寵至不驕者，則周公其人也，孤小人爾，深更以榮為戚，何者，將恐簡易之尤，出於細微，脱爾之愆，一朝复露也，故欲修吾往業，守吾初志，欲使皇帝恩在摩天，使孤心常存入地，將以全陛下厚德，究孤犬馬之年，此難能也，然固欲行眾之難，詩曰：德輶如毛，鮮克舉之，此之［自九六八頁一一行禁止二字起，至此止，宋本缺，據明本補。］謂。","sortOrder":41},
  {"id":"s_work_nvlt_54_42","chapterId":"ch_work_nvlt_54","text":"【難】漢張敞議入穀贖罪，萧望之難曰：國兵在外，軍以夏發，隴西以北，安定以西，吏民併給轉输，田事頗废，素無餘積，雖羌虜以破，來春必乏，窮僻之處，買無所得，縣官穀度不足以振之，原令諸有罪非盜受财殺人及犯法不得赦者，得以差入穀，此八郡贖罪，務益致穀，以豫備百姓之急，事下有司，望之與少府李疆議，以為民含陰陽之氣，有仁義欲利之心，在教化之所助，雖尧在上，不能去民欲利之心，而能令其欲利不勝其好義也，雖桀在上，不能去民好義之心，能令其好義不勝其欲利也，故尧桀之分，在於義利而已，导民不可不慎也，今欲令民量粟以贖罪，如此則富者得生，貧者獨死，是貧富異刑，而法不一也，人情貧窮，父兄囚執，聞出财得以生活，為人子弟者，將不顧死亡之患，败亂之行，以赴财利，求親戚一人得生，十人以死，如此，伯夷之行坏，公綽之名滅，政教一傾，雖有周召之佐，恐不能复，古者藏於民，不足則取，有餘則予，詩曰：爰及矜人，哀此鳏寡，上惠下也。","sortOrder":42},
  {"id":"s_work_nvlt_54_43","chapterId":"ch_work_nvlt_54","text":"【議】後漢孔融肉刑議曰：古者敦厖，善否區別，吏端刑清，治無過失，百姓有罪，皆自取之，末世陵遲，風俗坏亂，政撓俗替，法害其民，故曰：上失其道，民散久矣，而欲繩之以古刑，投之以殘弃，非所謂與時消息也，紂斮朝涉之胫，天下謂之無道，夫九牧之地，千八百君，若刖一人，是天下常有千八百刖也，求世休和，弗可得已，且被刑之人，慮不念生，志在思死，類多趨惡，莫复歸止，夙沙亂齊，伊戾禍宋，趙高英布，為世大患，不能止其源，遂為非也，雖忠如鬻拳，信如卞和，智如孫臏，冤如巷伯，才如史遷，達如子政，一罹刀鋸，没世不齒，漢开改惡之路，凡為此也，故明德之君，遠度深惟，弃短就長，不苟革其政者也，魏傅幹肉刑議曰：蓋禮樂所以导民，刑罰所以威之，是故君子忌禮，而小人畏刑，雖湯武之隆，成康之盛，不专用禮樂，亦陳肉刑之法，而康哉之歌興，清廟之頌作，由此推之，肉刑之法，不當除一也，經有墨劓剕割之製，至於凿顛抽胁，烹煮之刑。衛鞅所述為，非咎陶所造，呂侯所述，據經按傳，肉刑不當除有五验，請言其理，荀卿論之備矣，太古质簡，製事朴略，故耒耜未用於牛，而弧矢不加筋鐵，智非闇也，不識事宜，以為聖人純一之教，不如賢者支離之術，鄭衛可以易鹹池，激楚可以陵韶武耶，斯不足复難矣。","sortOrder":43},
  {"id":"s_work_nvlt_54_44","chapterId":"ch_work_nvlt_54","text":"晉曹志議曰：嚴刑以殺，犯之者寡，刑輕易犯，蹈惡者多，臣謂玩常苟免，犯法乃眾，黥刖鄣罪，而民甚恥，且創製墨刖，見者知禁，彰罪表惡，聞者多服，假使惡多，尚不至死，無妨產育，苟能殺以止殺，為惡縱寡，積而不已，將至無人，天無以神，君無以尊矣，故古人寧過不殺，是以為上，寧宽得眾，不寧急積殺，若及於張聽訟，刑以止刑，可不革舊，過此以往，肉刑是宜，假令漢文於張，承大亂之後，創基七十，國寡民稀，止禁刑書，鞭杖為治也。","sortOrder":44},
  {"id":"s_work_nvlt_54_45","chapterId":"ch_work_nvlt_54","text":"晉程鹹女適人不從坐［原訛出，據冯校本改。］議曰：夫司寇作典，建三等之製，甫侯修刑，通輕重之法，叔世多变，秦併重辟，漢因循之，大魏承袭，未革其弊，大逆之誅，不差已出之女者，誠欲絕惡類於一族，然法貴得中，刑慎過製，臣以為女人有三從之義，無自专之道，出適他族，還丧父母，降其服紀，所以明外成之節，異在室之恩，父母有罪，追刑已出之女，夫党見誅。又隨異姓之戮，一人之身，內外受辟，男不衍禍於他族，女獨婴罰於二門，非所以哀矜蒙弱，立法之本分也，今女既嫁，則為異姓之妻，如或產育，則為他族之母，此為元惡之所輕忽，戮無辜之所重，於恩則傷孝子之心，而興嫌怨之路，臣以為在室之女，宜從父族之誅，既醮之婦，使就夫家之罰，宜定齊科，以為永製。","sortOrder":45},
  {"id":"s_work_nvlt_54_46","chapterId":"ch_work_nvlt_54","text":"【表】晉盧諶理劉司空表曰：臣聞經國之體，在於崇明典刑，立政之務，在於固慎开塞，典刑不明，則人情歷措，开塞乏慎，則逆節滋萌，竊見故司空廣武侯琨，在東［疑當作惠。］皇帝扰攘之际，值群臣鼎沸之難，戮力皇家，義誠弥厲，躬統華夷，親受矢石，王弥授首於河南，呂朗面縛於滎陽，社稷克寧，鑾舆反旆，奉迎之勋，琨效忠之一验也，琨授併州，屬承其弊，到官之日，遺戶無幾，荆棘茂於街里，豺狼居於府舍，既無句［原訛白，據冯校本改。］踐甲［原訛里，據冯校本改。］楯之卒。又無衛文共滕之民，當易危之势，處難濟之中，鳩集傷夷，撫和戎狄，會遭京都失守，孝懷版荡，群逆縱逸，充斥王畿，鹹以為併州之地，四塞為固，東阻井陉，西限藍穀，前有太行之嶺，後有句註之關，琨抗辭厲聲，忠亮奋發，以為天子沉辱，而不陨身死節，言情則非所能安，言罪則不容於誅，遂乃鞠誓百姓，修繕甲兵，跋履山川，東征西讨，以丧氣之眾，當天下嚴敵，虮蝨生於甲胄，燕雀巢於帷幕，雖不能摧殄聰勒，且得據其心腹，琨破家為國之二验也，琨乃稽民神之旨，通天下之意，唱上尊號，歸重聖躬，令南北萬里，若合符契，此又琨乃心本朝之三验也，比未遇害，知匹磾必有禍心，唯恨不能效節於一方，上不得歸誠於陛下，辭旨［原作上日二字，據冯校本改。］慷慨，動於左右，聽其言者，莫能仰视，昔子囊垂終，道言城郢，古人稱之，以為忠貞，琨匪躬之操，義實茂之，此琨没不忘國之四验也，取亂侮亡，仲虺之遺言也，兼弱攻昧，隨季之善經也，匹磾之狹謀，踴躍一隅，無以自展，精卒劲騎，不得致力，以一人之身，妨一國之用，當今二賊未殄，方難尚殷，而使殊俗彊國，懷怨自相疑懼，非國家靜難之遠術也，伏惟陛下，以淑聖之姿，隆中興之緒，方將平章典刑，以序萬邦，而琨受害，悲哀冤痛已甚也，未聞朝廷有以甄論，昔壶關三老，訟衛太子之罪，穀永劉向，辯陳湯之功，下足以明功罪之分，上足以寤主上之懷。","sortOrder":46},
  {"id":"s_work_nvlt_54_47","chapterId":"ch_work_nvlt_54","text":"晉殷仲文罪衅解尚書表曰：臣聞洪波振壑，川無活［《文選》三十八作恬。］麟，驚飆拂野，林無靜柯，何者，势弱則受製於人，力微則無以自保，於理雖昧，可得而言，於臣寔非所敢論，桓玄之世，誠复驅迫者眾，於微臣罪實深矣，進不能見危授命，亡身殉國，退不能辭粟首陽，拂衣高謝，遂乃宴安昏寵，叨昧伪封，錫文篡事，曾莫獨固，名義以之俱淪，情節自茲兼桡，宜其極法，以判忠邪，镇軍臣裕，匡复社稷，大弘善貸，纾一戮於微命，由［《文選》作申。］三驅於大信，既惠之以首領，後［《文選》作复。］引之以縶維，於時皇舆否隔，天人未泰，用忘進退。唯力是视，是以黾勉從事，自同全人，今宸極反政，惟新告始，憲章既明，品物思舊，臣亦胡顏之厚，何以顯居榮次，乞解斯職，待罪私門，违謝闕庭，乃心愧恋。","sortOrder":47},
  {"id":"s_work_nvlt_54_48","chapterId":"ch_work_nvlt_54","text":"宋傅亮為劉毅軍败自解表曰：遂令犬羊內侮，兵纏紫極，聖朝肝胆，社稷幾殆，稽之典刑，罪不容宥，賴天祚有底，冢宰靈武，長蛇翦毒，丑類宵遯，今畿甸告寧，四封有截，臣元衅大责，既積朝野，桑榆之效。又無與立，而聖恩含宥，弛其徽墨，偏私之譏，既彰民聽，况可重荷嶽牧之任，复當推轂之重，宋趙伯符以息舊犯罪乞解侍中讓軍表曰：臣識慚羊媪，慮闕日磾，致咎猖狂，初不自悟，形影相弔，心情丧恧，無宜复管司喉唇，作統連率。","sortOrder":48},
  {"id":"s_work_nvlt_54_49","chapterId":"ch_work_nvlt_54","text":"齊孔稚珪上新定法律表曰：臣聞匠萬物者，以繩墨為政，馭大國者，以法理為本，故定國釋之，聲著漢台，元常文慧，績應魏閣，則皋陶之謨，指掌可致，杜鄭之業，鬱焉何遠，然後奸人無所逃其刑，惡吏無所窮其诈，如身手之相驅，絃括之相接矣。","sortOrder":49},
  {"id":"s_work_nvlt_54_50","chapterId":"ch_work_nvlt_54","text":"梁任昉為梁公請刊改律令表曰：臣聞淳源既遠，天讨是因，畫衣象服，以致刑厝，草纓艾韠，民不能犯，及淳德下衰，運距浇季，湯刑禹政，不足禁奸，九法三章，無以息訟，所以赭衣塞路，圄犴成市，凝脂已疏，秋荼非苦，奸吏為市，生殺併用，可為恸哭，豈徒一緒，夫肖貌天地，禀靈川嶽，受體愛敬，發膚為重，流矢影風，顧有忧色，而當妄加刳斮，金木為伍，且夫刻木不對，畫地不入，畏避若是，而動貽非命，王道為虧，良在於此，法开二門，為政之蠹，生殺多緒，誰其適政。","sortOrder":50},
  {"id":"s_work_nvlt_54_51","chapterId":"ch_work_nvlt_54","text":"【書奏】漢杜钦奏記於王鳳曰：切見令曰：吏二千石告，過長安，謁，不分別千［《太平御覽》六百三十四作予。］賜，今有司以為予告得歸，告不，［御覽作賜告不得歸，此有脱文。］賜告詔恩也，今告則得，詔恩不得，失輕重之差。又二千石病，賜告得歸，有故事，不得去郡，已亡者著令，［漢書七十九冯野王傳作不得去郡無著令，此已者二字疑衍。］傳曰：賞疑從予，所以廣恩勸功也，罰疑從去，所以慎刑，闕難知也，今釋令與故事，而假不敬之法，甚违闕疑從去之意，即以二千石守千里之地，任兵馬之重，不宜去都，將以製刑，為後法者，則冯野王之罪，在未製，賞罰大信，不可不慎，鳳不聽，竟免野王，郡國二千石病，賜告不得歸家，自此始也。","sortOrder":51},
  {"id":"s_work_nvlt_54_52","chapterId":"ch_work_nvlt_54","text":"漢貢禹上書曰：孝文皇帝時，貴廉絜，賤貪汙，贾人赘婿及吏坐贓者，禁固不得為吏，無贖罪之法，故令行禁止，海內大化，武帝始臨天下，尊賢用士，自見功大，遂從嗜欲，乃行一時之变，使犯法者贖罪，入穀者補吏，是以官亂民貧，盜賊併起，故俗皆曰：何以孝悌為，财多而官榮，使黥劓髡鉗者，猶复攘臂為政，俗之坏败，乃至於此，今欲興至治，致太平，宜除贖罪之法。","sortOrder":52},
  {"id":"s_work_nvlt_54_53","chapterId":"ch_work_nvlt_54","text":"漢［按當作後漢。］張俊上書曰：臣辜恩負義，自陷重刑，情斷意訖，無所复望，廷尉鞠遣，欧刀在前，棺絮在後，魂魄飛扬，形容已枯，陛下聖泽，以臣嘗在近密，識其状貌，傷其眼目，留心曲慮，特加偏覆，丧車复還，白骨更肉，披棺發椁，起見白日，天地父母，能生臣俊，不能使臣俊當死复生，陛下德過天地，恩重父母，誠非臣俊破碎骸骨，舉宗肉烂，所報萬一。","sortOrder":53},
  {"id":"s_work_nvlt_54_54","chapterId":"ch_work_nvlt_54","text":"魏鍾繇上書曰：大魏受命，繼蹤虞夏，孝文革法，不合古道，先帝聖德，固天所縱，墳典之業，一以貫之，是以繼世仍發明詔，思复古刑，為一代法，連有軍事，遂未施行，陛下遠追二祖遺意，惜斬趾可以禁惡，恨入死之無辜，使明習律令，與群臣共議，出本當右趾而入大辟者，复行此刑，書雲，皇帝清問下民，有辭於苗，此言尧當除蚩尤有苗之刑，先審問於下民之有辭者也，若今弊獄之時，訊問三槐九棘，群吏萬民，如孝景之令，其當弃市欲斬右趾者，許之，其黥劓左趾，宮刑者，自如孝文易以髡笞，能有奸者，率年二十至四五十，雖斬其足，猶任生育，今天下人少於孝文之世，下計所全，歲三千人，張蒼除肉刑，所殺歲以萬計，臣欲复肉刑，歲生三千人，子貢問，能濟民可謂仁乎，孔子曰：何事於仁，必也聖乎，尧舜其猶病諸。","sortOrder":54},
  {"id":"s_work_nvlt_54_55","chapterId":"ch_work_nvlt_54","text":"又曰：仁遠乎哉，我欲仁，斯仁至矣，若试行之，斯民永濟。","sortOrder":55},
  {"id":"s_work_nvlt_54_56","chapterId":"ch_work_nvlt_54","text":"晉劉頌上書曰：古者刑以止刑，及今民於此，以刑生刑，以徒生徒，諸犯重亡者髡，過三寸，辄重髡之，此以刑生刑，加［原訛如，據冯校本改。］作一歲，此以徒生徒也，亡者積多，系囚猥畜，議者因曰：不可殺，复從而赦之，此為刑不製罪，法不勝奸，民知法之不勝，相聚而謀為不軌，月異而歲不同，故自頃以來，奸惡愛暴，漸以滋蔓，日積不已，弊將所歸，識者不深思此故，曰：肉刑於名忤聽，忤聽孰與賊盜不禁，聖主製肉刑，還有深理，其事所［《太平御覽》六百四十八作可。］得而言，非徒懲其畏剝割之痛而不為也，乃去其為惡之具，使夫奸民無用复肆其志，止奸絕本，理之盡也，亡者刖之，無所用复亡，盜者截其手，無所用复盜，淫者割其势，理亦如之，除惡塞源，莫善於此。又非徒然也，此等已刑之後，便各歸家，父母妻子，共相養恤，不流離於涂路，創愈可役，上准古製，隨宜業作，雖以刑殘，不為虐弃，而所患都塞。又生育繁阜之道自若也，晉杜豫奏事曰：古之刑書，銘之鼎鍾，鑄之金石，斯所以遠塞異端，絕異理也，法出一門，然後人知恒禁，吏無淫巧，政明於上，民安於下。","sortOrder":56},
  {"id":"s_work_nvlt_54_57","chapterId":"ch_work_nvlt_54","text":"晉劉頌刑獄奏曰：君臣之分，各有所司，法欲必奉，故令主者守文，理有窮塞，故使大臣釋滯，事有時，故人主權斷，主者守文，若釋之執犯跸之卒也，大臣釋滯，公孫弘斷郭解之獄也，人主權斷，若漢祖戮丁公之為也，天下萬事，自非斯格，不得以出意妄議，其餘皆以律令從事，然後法信於下，民聽不惑，吏不容奸，可以言理，人主執斯格以责群下，大臣小吏，其局則法一矣，上古議事以製，不為刑辟，夏殷及周，書法象魏，三代之君，鹹弃典常之妙鑒，而任微文之直准，非聖有殊，所遇異也，今論時孰弊，不及中古，而執平者，欲適情之所安，自讬於議事以製，臣切以為聽言則美，論理則遠，至如非常之斷，出法賞罰，若漢祖戮楚臣之私己，封趙氏之無功，唯人主专之，非奉職之臣，所得擬議，然後情求傍請之跡絕，似是而非之奏塞，此蓋齊法之大准也。","sortOrder":57},
  {"id":"s_work_nvlt_54_58","chapterId":"ch_work_nvlt_54","text":"晉郭璞奏曰：臣聞上古象刑而民不犯，中古明刑，以致刑措，故立刑以禁刑，立殺以去殺，重之以死，所以求其生，峻之以刑，所以輕其死，死由於法輕，生存乎法重，此亡防之成摽也，然則刑無輕重，用之唯平，非平法之為難，思在斷之為難，是以子皇行戮，刖者忘痛，釋之典刑，民無怨色，何者，積之於誠也，按癸酉詔書之旨，专為邊成，［疑當作戍。］實之裔土，濟當時一切之用，非為經遠之法，亦是中夏全平之時，威御足指控製，故可得行之矣，欲役無賴子弟，驅不逞之人，聚之於空荒四維之地，將以扞固牧圉，未見其利也，且濱接鯨猾，密邇奸藪，退未絕其丘窟之顧，進無以塞其逋逃之門，五流三居，誠古之犯刑，論之於今，事實難行，且律令以跨三代，歷載所遵，未易輕改者也，是以刑法不专，則名幸者興，政令骤变，則人志無系，子產患其如此，故矯先正議事之製，而立刑書之辟，皆所以弼民心而正群惑者也。","sortOrder":58},
  {"id":"s_work_nvlt_54_59","chapterId":"ch_work_nvlt_54","text":"【啟】梁簡文帝啟囚徒配役事啟曰：伏以明慎三典，宽簡八刑，宸鑒每以垂心，國誥是焉攸切，臣比時奉敕旨，權视京師雜事，切見南北郊等處，併啟請四五歲以下輕囚，助充使役，優令聽獄官詳其可否，侮文之路自此而生，將恐玉科重輕，全關墨綬，金書去取，更由丹筆，愚謂宜詳五條，製以為永准。","sortOrder":59},
  {"id":"s_work_nvlt_54_60","chapterId":"ch_work_nvlt_54","text":"又謝邵陵王禁錮啟曰：臣纶習近宵人，不能改過，屢犯明憲，三入刑科，昔缪彤掩扉，曹議著論，布衣兄弟，且相誡勖，以臣居長，終慚勸励，仰負慈嚴，心顏戰詟。","sortOrder":60},
  {"id":"s_work_nvlt_54_61","chapterId":"ch_work_nvlt_54","text":"梁任昉為王金紫謝齊武帝未［全梁文四十二作示。］皇太子律序啟曰：臣聞化澄上業，草纓垂典，教清中世，艾服懲刑，自禮失宗周，俗反炎漢，張冯导其跡，贾杜浚其流，仲舒之得情，孔子之博約，故以義該往哲，盡美前王，而年世浸遠，篇牍訛誤，朽編落簡，見誣前淑，侮文擅議，取弊後崑，立不倚衡，遂均鸿毛之殒，傷足居忧，忘貽發膚之痛，豈所以臨河永叹，合育最靈者也，伏惟陛下，施博天地，泽深禹湯，溫舒之策，優遊虛授，衛展之議，寧失弗經，削秋荼之法，解凝脂之網。","sortOrder":61},
  {"id":"s_work_nvlt_54_62","chapterId":"ch_work_nvlt_54","text":"陳徐陵謝兒報坐事付治中啟曰：夫拾金樵路，高士所羞，整冠李下，君子斯慎，兒報不能謹絜，敢觸嚴綱，右趾鐵系，事允法科，左校論输，實由恩宥，老臣過庭之訓，多謝古賢，折笄之杖，有愧前達。","sortOrder":62},
  {"id":"s_work_nvlt_54_63","chapterId":"ch_work_nvlt_54","text":"晉叔向與鄭子產書曰：昔先王議事以製，不為刑辟，懼民之有事心，是故閒之以義，糾之以政，行之以禮，守之以信，奉之以仁，製為祿位，以勸其從，嚴斷刑罰，以威其淫，［原訛涇，據冯校本改。］懼其未也，故誨之以忠，耸之以行，教之以務，使之以和，臨之以敬，莅之以彊，斷之以刚，猶求聖哲之主，明察之官，忠信之長，慈惠之師，民於是乎可任［原訛住，據冯校本改。］使也，而不生禍亂，民知有辟，則不忌於上，併有爭心，以懲於書，而徼倖以成之，不可為矣，三辟之興，皆叔世也，今吾子相鄭國，作封洫，立謗政，製參辟，鑄刑書，將以靜民，不亦難乎，民知爭端矣，將弃禮而徵於書，錐刀之末，將盡爭之，亂獄茲丰，賄賂併行，終子之世，鄭其败乎。","sortOrder":63},
  {"id":"s_work_nvlt_54_64","chapterId":"ch_work_nvlt_54","text":"【序】晉杜豫律序曰：律以正罪名，令以存事製，二者相須為用。","sortOrder":64},
  {"id":"s_work_nvlt_54_65","chapterId":"ch_work_nvlt_54","text":"晉張斐律序曰：律令者，政事之經，萬機之緯。","sortOrder":65},
  {"id":"s_work_nvlt_54_66","chapterId":"ch_work_nvlt_54","text":"又曰：鄭鑄刑書，晉作執秩，趙製國律，楚造仆區，併述法律之名，申韓之徒，各自立製。","sortOrder":66},
  {"id":"s_work_nvlt_54_67","chapterId":"ch_work_nvlt_54","text":"【論】魏丁儀刑《禮論》曰：天垂象，聖人則之，天之為歲也，先春而後秋，君之為治也，先禮而後刑，春以生長為德，秋以殺戮為功，禮以教訓為美，刑以威嚴為用，故先生而後殺，天之為歲，先教而後罰，君之為治也，天不以久遠更其春冬，而人也得以古今改其禮刑哉，太古之世，民故质朴，质朴之民，宜其易化，是以中古之君子，或結繩以治，或象刑惟明，夏後肉辟，民轉奸诈，刑弥滋繁，禮亦如之，由斯言之，古之刑省，禮亦宜略，今所論辨，雖出傳記之前，天［疑當作夫。］流東源不得西，景正形不得傾，自然之势也，後世禮刑，俱失於前，先後之宜，故自有常，今夫先刑者，用其末也，曰［原作由，據冯校本改。］禮禁未然之前，謂難明之禮，古人不能行也，按如所雲禮嫂叔不親之屬也，非太古之禮也，所雲禮者，豈此也哉，古者民少而獸多，未有所爭，民無患則無所思，故未有君焉，後民禍多，強暴弱，於是有賢人焉，平其多少，均其有無，推逸取勞，以身先之，民獲其利，歸而樂之，樂之得為君焉，夫刑之記君也，［句有訛文。］精其［原作具，據冯校本改。］筋力，民畏其強而不敢校，得為君也，恐上古未具刑罪之品，設逋亡之法，懼彼為我，而以勇力侵暴，於已能與則校，不能歸奉之，明矣，且上古之時賊耳，非所謂君也，上古雖质，宜所以為君，會當先別男女，定夫婦，分土地，班食物，此先以禮也，夫婦定而後禁淫焉，货物正而後止竊，此後刑也。","sortOrder":67},
  {"id":"s_work_nvlt_54_68","chapterId":"ch_work_nvlt_54","text":"魏曹羲肉刑論曰：夫言肉刑之濟治者，荀卿所唱，班固所述，隆其趣，則曰像天地，為之惟明，察其用，則曰死刑重而生刑輕，其所馳騁，極於此矣，治則刑重，亂則刑輕。","sortOrder":68},
  {"id":"s_work_nvlt_54_69","chapterId":"ch_work_nvlt_54","text":"又曰：殺人者死，傷人者刑，是百王之所同，固未達夫用刑之本矣，夫死刑者，不唯殺人，妖逆是除，天地之道也，傷人者不改，斯亦妖逆之類也，如其可改，此則無取於肉刑也，且傷人殺人，皆非人性之自然也，必有由然者也，夫有由而然者，激之則淫，敦之則一，激之也者，動其利路，敦之也者，篤其质朴，故在上者議茲本要，不營奇思，行之以簡，守之以靜，大則其隆足以侔天地，中則其理可以厚民萌，下則刑罰可以無殘虐，民靜理則其化，為惡之尤者，眾之所弃，眾之所弃，則無改之验著矣，夫死之可以有生，而欲增淫刑以利暴刑，暴刑所加，雖雲懲慢之由興，有使之然，謂之宜生，生之可也，舍死析骸。又何辜耶，猶稱以滿堂而飲，有向隅哀泣，則一堂為之不樂，在上者洗濯其心，靜而民足，各得其性，何懼乎奸之不勝，乃欲斷截防轉而入死乎。","sortOrder":69},
  {"id":"s_work_nvlt_54_70","chapterId":"ch_work_nvlt_54","text":"晉楊乂刑《禮論》曰：覽眾所抵，精思構微，迭為先後，文若榮繁，翩然相反，豈彼系未存厥中，嘗试稽之天地，考之人事，旁貫品物，綜覈彝倫，而刑禮之旨，可略言也，蓋刑禮之本，經緯陰陽，擬則乾坤，先王所以化民理物，興國濟治也，或者取證於春秋，有意乎尋本以綜末，然猶未離於先後，亦速難之始也，夫陰陽異製，化物則鈞，萬物本一，变而殊形，故王者去彼而適此，於此［二字據冯校本補。］為生，而於彼為死，夫死者去此而適彼，於此為死，而於彼為生矣，禮生於讓，刑生於爭，讓者割己以與人，是刑加於己，而禮加於人也，爭者奪人以崇己，是刑施於人，而禮施於己也，由此言之，讓非純禮，爭非純刑也，慶賞以勸善，而為惡者懲，如有所懲，刑亦存矣，刑罰以懲惡，而為善者勸，如有所勸，禮亦存矣，故亡刑則禮不獨施，大道废焉，則刑禮俱错，大道行焉，則刑禮俱興，不合而成，未之有也，［自九七三頁一行刖見者三字以下至此止，宋本缺，據明本補。］","sortOrder":70},
  {"id":"s_work_nvlt_54_71","chapterId":"ch_work_nvlt_54","text":"《藝文類聚》　唐·欧陽詢","sortOrder":71},
  {"id":"s_work_nvlt_55_1","chapterId":"ch_work_nvlt_55","text":"卷五十五雜文部一","sortOrder":1},
  {"id":"s_work_nvlt_55_2","chapterId":"ch_work_nvlt_55","text":"○經典談講讀書史傳集序","sortOrder":2},
  {"id":"s_work_nvlt_55_3","chapterId":"ch_work_nvlt_55","text":"◇經典","sortOrder":3},
  {"id":"s_work_nvlt_55_4","chapterId":"ch_work_nvlt_55","text":"《釋名》曰：經，径也，如五路無所不通，可常用也。","sortOrder":4},
  {"id":"s_work_nvlt_55_5","chapterId":"ch_work_nvlt_55","text":"又曰：三墳，墳，分也，論三材，分天地人之始分也，其體有三也，五典，典，镇也，製教法，所以镇定上下，差等有五也，八索，玉法，［《釋名》六作著素王之法，此有脱訛。］若孔子者，聖而不至，［《釋名》作王。］製此法者有八也，九丘，丘［《釋名》丘下有區也二字。］區別九州土氣教化所宜者也，此皆三玉，［《釋名》作王。］以前，上至羲皇時書也，唯尧典存。","sortOrder":5},
  {"id":"s_work_nvlt_55_6","chapterId":"ch_work_nvlt_55","text":"《禮》曰：孔子曰：入其國，其教可知也，其為人也，溫柔敦厚，詩教也，疏通知遠，書教也，廣博易良，樂教也，絜靜精微，易教也，恭俭莊敬，禮教也，屬辭比事，春秋教也。","sortOrder":6},
  {"id":"s_work_nvlt_55_7","chapterId":"ch_work_nvlt_55","text":"《春秋說題［題字原脱，據冯校本補。］辭》曰：六經所以明君父之尊，天地之开辟，皆有教也。","sortOrder":7},
  {"id":"s_work_nvlt_55_8","chapterId":"ch_work_nvlt_55","text":"《尚書璇璣鈐》曰：尚書篇題號，尚者上也，上天垂文象，布節度書也，如天行也。","sortOrder":8},
  {"id":"s_work_nvlt_55_9","chapterId":"ch_work_nvlt_55","text":"《博物志》曰：聖人製作曰經。","sortOrder":9},
  {"id":"s_work_nvlt_55_10","chapterId":"ch_work_nvlt_55","text":"楊雄《法言》曰：或問周官，曰立事，左氏傳，曰品藻。","sortOrder":10},
  {"id":"s_work_nvlt_55_11","chapterId":"ch_work_nvlt_55","text":"又曰：書不經，非書也。","sortOrder":11},
  {"id":"s_work_nvlt_55_12","chapterId":"ch_work_nvlt_55","text":"劉向《七略》曰：孔子三見哀公，作三朝記七篇，今在大戴禮。","sortOrder":12},
  {"id":"s_work_nvlt_55_13","chapterId":"ch_work_nvlt_55","text":"《漢書》曰：昔宓羲仰觀象於天，俯觀法於地，觀鳥獸之文，與土地之宜，近取諸身，遠取諸物，於是始畫八卦，以通神明之德，以類萬物之情，文王重易六爻，作上下篇，孔子為之彖象系文言序卦之屬十篇，故曰：易道深矣，人更三聖，世歷三古。","sortOrder":13},
  {"id":"s_work_nvlt_55_14","chapterId":"ch_work_nvlt_55","text":"又曰：誦其言謂之詩，詠其聲謂之歌，古者采詩之官，王者所以觀風俗，知得失，自考正也。","sortOrder":14},
  {"id":"s_work_nvlt_55_15","chapterId":"ch_work_nvlt_55","text":"又曰：帝王质文，世有損益，至周，曲為之防，事為之製，故曰禮經三百，威儀三千。","sortOrder":15},
  {"id":"s_work_nvlt_55_16","chapterId":"ch_work_nvlt_55","text":"又曰：六藝之文，樂以和神，詩以正言，禮以明體。","sortOrder":16},
  {"id":"s_work_nvlt_55_17","chapterId":"ch_work_nvlt_55","text":"《廣雅》曰：昔在周公，製禮以导天下，爾雅以釋其意義。","sortOrder":17},
  {"id":"s_work_nvlt_55_18","chapterId":"ch_work_nvlt_55","text":"鄭玄別傳曰：任城何休，好公羊學，遂著公羊墨守，左氏膏育，穀梁废疾，玄乃發墨守，針膏育，起废疾。","sortOrder":18},
  {"id":"s_work_nvlt_55_19","chapterId":"ch_work_nvlt_55","text":"周官，外史掌三皇五帝之書。","sortOrder":19},
  {"id":"s_work_nvlt_55_20","chapterId":"ch_work_nvlt_55","text":"《春秋說題辭》［辭字原脱，據冯校本補。］曰：尚書者，二帝之跡，三王之義，明天下情，帝王之功，尚，上也，上帝之書。","sortOrder":20},
  {"id":"s_work_nvlt_55_21","chapterId":"ch_work_nvlt_55","text":"又曰：禮，體也，禮得則天下鹹得厥宜。","sortOrder":21},
  {"id":"s_work_nvlt_55_22","chapterId":"ch_work_nvlt_55","text":"又曰：詩天人之精，皇後之度，故詩為言志。","sortOrder":22},
  {"id":"s_work_nvlt_55_23","chapterId":"ch_work_nvlt_55","text":"【詩】晉傅鹹孝經詩曰：立身行道，始於事親，上下無怨，不敢惡人，孝無終始，不離其身，三者備矣，以臨其民，［其一。］以孝事君，不離令名，進思盡忠，不議則爭，匡救其惡，灾害不生，孝悌之至，通於神明，［其二。］","sortOrder":23},
  {"id":"s_work_nvlt_55_24","chapterId":"ch_work_nvlt_55","text":"又論語詩曰：守死善道，磨而不磷，直哉史魚，可謂大臣，見危授命，能致其身，［其一。］克己复禮，學優則仕，富貴在天，為仁由己，以道事君，死而後已，［其二。］","sortOrder":24},
  {"id":"s_work_nvlt_55_25","chapterId":"ch_work_nvlt_55","text":"又毛詩詩曰：無［自九八三頁四行釋名曰三字起，至此止，宋本缺，據明本補。］將六［《初學記》二十一作大。］車，惟尘冥冥，濟濟多士，文王以寧，顯允君子，大猶是經，［其一。］聿脩厥德，令終有淑，勉爾遯思，我言惟服，盜言孔甘，其何能淑，讒人罔極，有靦面目，［其二。］","sortOrder":25},
  {"id":"s_work_nvlt_55_26","chapterId":"ch_work_nvlt_55","text":"又周易詩曰：卑以自牧，謙尊而光，進德脩業，既有典常，辉光日新，照於四方，小人勿用，君子道長，［其一。］","sortOrder":26},
  {"id":"s_work_nvlt_55_27","chapterId":"ch_work_nvlt_55","text":"又周官詩曰：惟王建國，設官分職，進賢興功，取諸易直，除其不蠲，無敢反侧，以德詔爵，允臻其極，［其一。］辨其可任，以告於正，掌其戒禁，治其政令，各修乃職，以聽王命，［其二。］","sortOrder":27},
  {"id":"s_work_nvlt_55_28","chapterId":"ch_work_nvlt_55","text":"梁武帝撰孔子正言竟述懷詩曰：志學恥傳習，弱冠闕師友，愛悅夫子道，正言思善誘，删次起實沉，殺青在建酉，孤陋乏多聞，獨學少击叩，仲冬寒氣嚴，霜風折細柳，白水凝涧溪，黃落散堆阜，康哉信股肱，惟聖歸元首，獨叹予一人，端然無四友。","sortOrder":28},
  {"id":"s_work_nvlt_55_29","chapterId":"ch_work_nvlt_55","text":"梁昭明太子詠書秩詩曰：擢影兔園池，抽茎淇水侧，幸雜絪囊用，聊因班女織。","sortOrder":29},
  {"id":"s_work_nvlt_55_30","chapterId":"ch_work_nvlt_55","text":"【賦】後漢杜篤書扌扈賦曰：惟書扌扈而麗容，象君子之淑德，載方矩而履規，加文藻之脩飾，能屈伸以和禮，體清净而坐立，承尊者之至意，惟高下而消息，雖轉旋而屈桡，時傾斜而反侧，抱六藝而卷舒，敷五經之典式。","sortOrder":30},
  {"id":"s_work_nvlt_55_31","chapterId":"ch_work_nvlt_55","text":"【贊】晉王凝之妻謝氏論語贊曰：衛靈問陣於孔子，孔子對曰：俎豆之事，則嘗聞之，軍旅之事，未之學也，庶則大矣，比德中庸，斯言之善，莫不歸宗，粗者乖本，妙極令終，嗟我懷矣，興言攸同，孔子曰：民之於仁也，甚於水火，水火吾見蹈而死者，未見蹈仁而死者矣。","sortOrder":31},
  {"id":"s_work_nvlt_55_32","chapterId":"ch_work_nvlt_55","text":"【銘】後漢李尤經桡銘曰：瞻之在前，忽焉在後，進新習故，不舍於口，子在川上，逝者如斯，及年廣學，無問不知。","sortOrder":32},
  {"id":"s_work_nvlt_55_33","chapterId":"ch_work_nvlt_55","text":"宋謝靈運書帙銘曰：懷幽卷赜，戢妙抱密，用舍以道，舒卷不失，亮惟勤玩，無或暇逸。","sortOrder":33},
  {"id":"s_work_nvlt_55_34","chapterId":"ch_work_nvlt_55","text":"【表】梁沈約上宋書表曰：若不觀風唐世，無以見帝妫之美，自非睹亂秦餘，何用知漢祖之業，是以掌言未記，爰動天情，曲詔史官，追述大典，若夫英主啟基，名臣建績，極［《初學記》二十一作拯。］世夷難之功，配天光宅之運，亦足以勒銘鍾鼎，昭被方策，臣遠愧南董，近謝遷固，以闾阎小才，述一代盛典。","sortOrder":34},
  {"id":"s_work_nvlt_55_35","chapterId":"ch_work_nvlt_55","text":"【啟】齊謝朓隨王賜左傳啟曰：思勸挟策，慈勖下帷，朓未窥山笥，早懵河籍，業謝专門，說非章句，庶得既因［《初學記》二十一作困。］而學，括羽瑩其蒙心，家藏賜書，籝金遺其貽厥。","sortOrder":35},
  {"id":"s_work_nvlt_55_36","chapterId":"ch_work_nvlt_55","text":"梁劉孝綽謝為東宮奉經啟曰：皇太子四術夙知，三善非學，猶复旁求儒雅，應物稽疑，業光夏校，德茂周序，諸侯宋魯，於焉觀則，參陪盛禮，莫匪國華，臣雖職典經圖，而同官不一，推擇而舉，尚多髦俊，寵光曲被，獨在選中，他日朝聞，猶甘夕死，况茲恩重，弥見生輕。","sortOrder":36},
  {"id":"s_work_nvlt_55_37","chapterId":"ch_work_nvlt_55","text":"【書】後漢孔融答虞仲翔書曰：示所著易傳，自商瞿以來，舛错多矣，去聖弥遠，眾說騁辭，曩聞延陵之理樂，今睹吾君之治易，知東南之美者，非但會稽之竹箭焉。又觀象雲物，察應寒溫，本［吳志十二虞翻傳作原其，此有脱文。］禍福，與神會契，可謂探赜窮道者已，方世清，聖上求賢者，梁丘以卦筮寧世，劉向以洪范昭名，想當來翔，追蹤前烈，相見乃盡，不复多陳。","sortOrder":37},
  {"id":"s_work_nvlt_55_38","chapterId":"ch_work_nvlt_55","text":"◇談講","sortOrder":38},
  {"id":"s_work_nvlt_55_39","chapterId":"ch_work_nvlt_55","text":"《論語》曰：德之不脩，學之不講，是吾忧也。","sortOrder":39},
  {"id":"s_work_nvlt_55_40","chapterId":"ch_work_nvlt_55","text":"《韓子》曰：夫耕之用力也勞，而民為之者何，得以富，戰之為事也危，而民為之者何，得以貴，今脩文學，習談論，則無耕之勞，而有富之實，無戰之危，而有貴之尊，則人孰不為也。","sortOrder":40},
  {"id":"s_work_nvlt_55_41","chapterId":"ch_work_nvlt_55","text":"《戰國策》曰：蘇秦說李兑，抵掌而談，兑送秦明月之珠，和氏之璧。","sortOrder":41},
  {"id":"s_work_nvlt_55_42","chapterId":"ch_work_nvlt_55","text":"《史記》曰：齊宣王時，稷下复盛。","sortOrder":42},
  {"id":"s_work_nvlt_55_43","chapterId":"ch_work_nvlt_55","text":"《漢書》曰：董仲舒下帷，講論讀誦，弟子以文［漢書五十六，董仲舒傳作久。］次相授業，或莫見其面。","sortOrder":43},
  {"id":"s_work_nvlt_55_44","chapterId":"ch_work_nvlt_55","text":"又夏侯勝每講，常謂弟子曰：士病不明經，經術苟明，其取青紫，如俯拾地芥爾，學不明，不如歸耕。","sortOrder":44},
  {"id":"s_work_nvlt_55_45","chapterId":"ch_work_nvlt_55","text":"又曰：諸儒為之語曰：五鹿嶽嶽，朱雲折其角。","sortOrder":45},
  {"id":"s_work_nvlt_55_46","chapterId":"ch_work_nvlt_55","text":"《東觀漢記》曰：朱祜，字仲先，初上學長安時，過朱祜，祜常留上講，竟乃談語，及車駕幸祜家，上謂祜曰：主人得無去我講乎。","sortOrder":46},
  {"id":"s_work_nvlt_55_47","chapterId":"ch_work_nvlt_55","text":"漢書［按本條見後漢書一百鄭太傳，此脱後字。］曰：鄭太說董卓雲，孔公謂［後漢書作緒。］能清談高論，噓拓［後漢書作枯。］吹笙，［後漢書作生。］","sortOrder":47},
  {"id":"s_work_nvlt_55_48","chapterId":"ch_work_nvlt_55","text":"《典略》曰：漢樊准為郎中令，乃上疏曰：方今學者約少，遠方又甚，博士倚席不講，大學多治產業。","sortOrder":48},
  {"id":"s_work_nvlt_55_49","chapterId":"ch_work_nvlt_55","text":"謝承《後漢書》曰：戴冯，字次仲，拜郎中，正旦朝贺，帝令群臣說經義，有不通者，辄奪其席，以益通者，冯重五十席，京師議曰：解經不窮戴侍中。","sortOrder":49},
  {"id":"s_work_nvlt_55_50","chapterId":"ch_work_nvlt_55","text":"《管辂別傳》曰：冀州刺史裴徽，召文學從事，一相見，清談終日，不覺罢倦，再相見，轉為鉅鹿從事，三相見，轉為治中，四相見，轉為別駕，至前十日，舉為秀才。","sortOrder":50},
  {"id":"s_work_nvlt_55_51","chapterId":"ch_work_nvlt_55","text":"魏文帝［按本條本書六十三，《太平御覽》六百十五作魏書，此脱書名。］集諸儒於肅城［御覽作成。］門內，講論大義，侃侃無倦。","sortOrder":51},
  {"id":"s_work_nvlt_55_52","chapterId":"ch_work_nvlt_55","text":"張載別傳曰：張載文章殊妙，嘗為濛汜池賦，傅玄見之，叹息稱妙，以車迎載，言談終日。","sortOrder":52},
  {"id":"s_work_nvlt_55_53","chapterId":"ch_work_nvlt_55","text":"殷氏《世傳》曰：殷亮，建武中，徵拜博士，諸儒講論，勝者賜席，亮重至八九。","sortOrder":53},
  {"id":"s_work_nvlt_55_54","chapterId":"ch_work_nvlt_55","text":"《竹林七賢論》曰：王濟嘗解禊洛水，明日，或問王濟曰：昨日又有何論議，濟曰：張華善說史漢，裴逸人叙前言往行，袞袞可聽，安丰侯道子房季札之間，超然玄著。","sortOrder":54},
  {"id":"s_work_nvlt_55_55","chapterId":"ch_work_nvlt_55","text":"《抱朴子》曰：王充所著論衡，北方都未有得之者，蔡伯喈常到江東，得之，叹為高文，恒愛玩而獨秘之，及還中國，諸儒覺其談更遠，搜求其帳中，果得論衡。","sortOrder":55},
  {"id":"s_work_nvlt_55_56","chapterId":"ch_work_nvlt_55","text":"《郭子》曰：范汪，［原訛註，據冯校本改。］字玄平，在簡文坐談，欲屈，引長史［王仲祖也。］曰：卿助我，王曰：此非拔山之力所能助。","sortOrder":56},
  {"id":"s_work_nvlt_55_57","chapterId":"ch_work_nvlt_55","text":"《語林》曰：劉真長與桓宣武共聽講《禮記》：桓公雲，時有入心處，便咫尺玄門。","sortOrder":57},
  {"id":"s_work_nvlt_55_58","chapterId":"ch_work_nvlt_55","text":"又曰：劉真長謂許玄度曰：卿為不去，我將成輕薄京尹，世說曰：宋處宗甚有思理，嘗買得一長鳴雞，籠盛著，遂作人語，與處宗談論，宗因此功大進。","sortOrder":58},
  {"id":"s_work_nvlt_55_59","chapterId":"ch_work_nvlt_55","text":"又曰：何晏為吏部尚書，時談客盈坐，王弼未弱冠，往見，晏因條向者勝理語弼曰：此理仆以為極，可得复難不，弼便作難，坐人便以為屈，於是弼為客主數番，皆一坐所不及。","sortOrder":59},
  {"id":"s_work_nvlt_55_60","chapterId":"ch_work_nvlt_55","text":"又曰：孝武時，將講孝經，謝太傅與諸人私逆講習，車武子謂曰：不問則德音有遺，多問則重勞二謝，袁曰：必無此嫌，車曰：何以知爾，袁曰：何當見明鏡於古照，泛清流於惠風，［按世說言語篇作何嘗見明鏡疲於屢照，清流憚於惠風，此有脱訛。］","sortOrder":60},
  {"id":"s_work_nvlt_55_61","chapterId":"ch_work_nvlt_55","text":"《晉書》曰：郭象如懸河，惟新既新爾史既辯爾疑［按惟新以下十字，系自下竄入，應删。］","sortOrder":61},
  {"id":"s_work_nvlt_55_62","chapterId":"ch_work_nvlt_55","text":"范晔《後漢書》曰：楊震，字伯起，賓客於朝，不答州郡禮命，有鸛雀衔三鳣魚，集講堂前。都講曰：鳣者卿大夫服之，象三台，先生自此升矣，位至太尉。","sortOrder":62},
  {"id":"s_work_nvlt_55_63","chapterId":"ch_work_nvlt_55","text":"【詩】晉潘嶽於贾謐坐講漢書詩曰：治道在儒，弘儒由人，顯允魯侯，文质彬彬，筆下摛藻，席上敷珍，前疑惟辨，舊史惟新，惟新爾史，既辨爾疑，延我寮友，講此微辭。","sortOrder":63},
  {"id":"s_work_nvlt_55_64","chapterId":"ch_work_nvlt_55","text":"梁任昉厲吏民講學詩曰：暮燭迫西榆，將落誡南畝，曰餘本疏惰，頹暮積榆柳，踐境渴師臣，臨政飢益友，旰食原橫經，終朝思擁帚，雖欣辨蘭艾，何用辟蒿莠。","sortOrder":64},
  {"id":"s_work_nvlt_55_65","chapterId":"ch_work_nvlt_55","text":"【碑】梁元帝皇太子講學碑曰：皇太子洊雷种德，重離作兩，業觀孟侯，道高上嗣，宮壇累仞，高山仰止，承華之闼，更似通德之門，博望之園，反類華陰之市，家丞庶子，併入四科，洗馬後車，俱通六學，轉金路而下壁雍，晬王裕［《初學記》二十一作容。］而經槐市，詳其懸鏡高堂，衢樽待酌，瞻後思前，博文約禮，將使東極長男之宮，不獨銘於銀榜，南皮太子之序，豈徒擅於金碑。","sortOrder":65},
  {"id":"s_work_nvlt_55_66","chapterId":"ch_work_nvlt_55","text":"隋江總皇太子太學講碑曰：我大陳之御天下，若水涣其長澜，瑤星踵其永歷，重華誕宥，興於大鹿之野，敬仲繼業，盛矣鳴鳳之占，兼以鸿才海富，逸思泉泻，含毫落紙，動八阕之歌謠，只句片言，諧五聲之節奏，雲飛風起，追壓漢帝之辭，高觀華池，遠跨魏皇之什，爰复建藏書之册，开獻書之路，帷帳丛殘，家壁遺逸，紫台秘典，绿帙奇文，羽陵蠹跡，嵩山落簡，外史所掌，廣內所司，靡不飾以鉛椠，彫以緗素，此文教之修也。","sortOrder":66},
  {"id":"s_work_nvlt_55_67","chapterId":"ch_work_nvlt_55","text":"【表】梁簡文帝請右將軍朱異奉述製旨易義表曰：臣聞仰觀俯察，定八卦之宗，河圖洛書，符三易之教，譬彼影圭，居四方之中極，猶彼黃鍾，總六律之殊氣，疑關永辟，逾弘農之洞啟，辭河既吐，邁龍門之已凿，臣以庸蔽，竊尚名理，鑽仰幾深，伏惟舞蹈，冒欲請侍中右衛將臣異，於玄圃宣猷堂，奉述製旨易義，弘闡聖作，垂裕蒙求，謹以表聞，伏原垂允。","sortOrder":67},
  {"id":"s_work_nvlt_55_68","chapterId":"ch_work_nvlt_55","text":"又請尚書左丞贺琛奉述製旨毛詩義表曰：臣聞樂由陽來，性情之本，詩以言志，政教之基，故能使天地鹹亨，人倫敦序，故東魯夢周，窮茲删采，西河邵魏，著彼缵述，葉星辰而建詩，觀斗儀而命禮，以為陳徐雅頌，膏肓匪一，燕韓篇什，痼疾多端，北海鄭君，徒逢箋釋，南郡太守，空為異序，庶令中和永播，硕學知宗，大胥負師，國子鹹紹，孝敬之德，化洽天下，多識之風，道行比屋。","sortOrder":68},
  {"id":"s_work_nvlt_55_69","chapterId":"ch_work_nvlt_55","text":"陳周弘正請梁武帝釋乾坤二系義表曰：自非含徽體極，盡化窮神，豈能通志成務，探赜致遠，而宣尼比之桎梏，絕韦編於沴宇，軒轅之所聽瑩，遺玄珠於赤水，至若爻畫之包於六經，文辭之窮於兩系，名儒剧談以歷載，鸿生指掌以終年，自製旨降談彖繇，裁成易道，析至微於秋毫，涣曾冰於幽穀。","sortOrder":69},
  {"id":"s_work_nvlt_55_70","chapterId":"ch_work_nvlt_55","text":"【啟】梁簡文帝謝敕赍中庸講疏啟曰：若睹玄圭，如觀金版，洽日九披，流光照灼，慶雲五色，垂采氤氲，天經地義之宗，出忠入孝之道，實立教之關鍵，德行之指歸，自非千年有聖，得奉皇門，無以識九經之倫，禀二門之致，竊以周發上聖，問五行於箕子，宣尼照極，訪六舞於萇弘，未有懸鏡獨晓，仰均神鑒，方知始畫八卦，風羲有慚，正名百物，軒轅為陋。","sortOrder":70},
  {"id":"s_work_nvlt_55_71","chapterId":"ch_work_nvlt_55","text":"梁王僧孺謝齊竟陵王使撰眾書啟曰：伏惟殿下，銅爵始成，早摛從後之句，柏梁初構，首屬驂駕之辭，楚史所受，曾不雲述，沛獻斯陳，良未足采，徒以原讬後車，以望西園之客，攝齊下坐，有糅南皮之遊，谬服同於魯儒，竊吹等乎齊樂。","sortOrder":71},
  {"id":"s_work_nvlt_55_72","chapterId":"ch_work_nvlt_55","text":"【書】後漢孔臧與子琳書曰：告琳，須［連丛子作頃。］來聞汝諸友生講肄［原訛肆，據冯校本改。］書傳，孜孜晝夜，衎衎不怠，善矣，人之進道，唯問其志，取必以漸，勤則得多，山涧至柔，石為之穿，蝎虫至弱，木為之弊，然而能以微脆之形，陷堅刚之體，豈非漸之致乎。","sortOrder":72},
  {"id":"s_work_nvlt_55_73","chapterId":"ch_work_nvlt_55","text":"◇讀書","sortOrder":73},
  {"id":"s_work_nvlt_55_74","chapterId":"ch_work_nvlt_55","text":"《墨子》曰：周公朝讀百篇，夕見七十士。","sortOrder":74},
  {"id":"s_work_nvlt_55_75","chapterId":"ch_work_nvlt_55","text":"《莊子》曰：臧與穀，相與牧羊，俱亡其羊，問臧奚事，挟策讀書，問穀奚事，博塞以遊。","sortOrder":75},
  {"id":"s_work_nvlt_55_76","chapterId":"ch_work_nvlt_55","text":"《尚書大傳》曰：子夏讀書畢，見夫子，夫子問之，何為於書，子夏曰：書之論事，昭昭如日月之代明，離離如參辰之错行，商所受於夫子者，志之於心，不敢忘也。","sortOrder":76},
  {"id":"s_work_nvlt_55_77","chapterId":"ch_work_nvlt_55","text":"《史記》曰：孔子晚喜易，讀之韦編三絕。","sortOrder":77},
  {"id":"s_work_nvlt_55_78","chapterId":"ch_work_nvlt_55","text":"《漢書》曰：劉向精专經術，晝誦書傳，夜觀星宿。又，班遊以選受詔，進讀群書。","sortOrder":78},
  {"id":"s_work_nvlt_55_79","chapterId":"ch_work_nvlt_55","text":"《東觀漢記》曰：章帝詔黃香，令詣閤東觀，讀所未嘗見書，謂諸生曰：此日下無双，江夏黃童也。","sortOrder":79},
  {"id":"s_work_nvlt_55_80","chapterId":"ch_work_nvlt_55","text":"又曰：曹襃寢則懷鉛筆，行則誦詩書。","sortOrder":80},
  {"id":"s_work_nvlt_55_81","chapterId":"ch_work_nvlt_55","text":"又曰：高鳳讀書，夜不絕聲，妻之田曝麥，以竿授鳳，令護雞，天暴雨而意不在，不覺流麥。","sortOrder":81},
  {"id":"s_work_nvlt_55_82","chapterId":"ch_work_nvlt_55","text":"謝承《後漢書》曰：王充，字仲任，家貧無書，至京師市讀書，一見辄誦憶。","sortOrder":82},
  {"id":"s_work_nvlt_55_83","chapterId":"ch_work_nvlt_55","text":"又曰：應世叔讀書，五行俱下。","sortOrder":83},
  {"id":"s_work_nvlt_55_84","chapterId":"ch_work_nvlt_55","text":"《漢書》曰：匡衡凿壁，引鄰家火光，孔中讀書。","sortOrder":84},
  {"id":"s_work_nvlt_55_85","chapterId":"ch_work_nvlt_55","text":"孫卿，有子惡臥，而焠其掌。","sortOrder":85},
  {"id":"s_work_nvlt_55_86","chapterId":"ch_work_nvlt_55","text":"《西京記》曰：魯國陳正，字叔方，為太官令，進御食，發貫炙，光武欲斬正，正曰：臣當死者三，臣朗月書章奏，侧光讀書，不見發，三也。","sortOrder":86},
  {"id":"s_work_nvlt_55_87","chapterId":"ch_work_nvlt_55","text":"《物理論》曰：里語，白能絲，可讀詩。","sortOrder":87},
  {"id":"s_work_nvlt_55_88","chapterId":"ch_work_nvlt_55","text":"《魏略》曰：侍中董遇好學，避難采薪負販，常挟經書，投閒習誦，人從學者，遇不肯教之，雲先讀百遍，而義自見。","sortOrder":88},
  {"id":"s_work_nvlt_55_89","chapterId":"ch_work_nvlt_55","text":"又曰：贾逵，字梁道，好春秋，及為牧守，常自課之，月一遍。","sortOrder":89},
  {"id":"s_work_nvlt_55_90","chapterId":"ch_work_nvlt_55","text":"《吳志》曰：阚泽，字德润，好學居貧，常從人賃書寫，寫既畢，誦亦遍。","sortOrder":90},
  {"id":"s_work_nvlt_55_91","chapterId":"ch_work_nvlt_55","text":"《上党記》曰：太行山箐有射熊，於巖間見諸生讀書，往觅不知處，傳以為仙人。","sortOrder":91},
  {"id":"s_work_nvlt_55_92","chapterId":"ch_work_nvlt_55","text":"《晉書》曰：王歡，字君厚，专精讀書，不營產業，家無升斗，妻患，或毀其書。後為通儒。","sortOrder":92},
  {"id":"s_work_nvlt_55_93","chapterId":"ch_work_nvlt_55","text":"《宋書》曰：車胤，字武子，少勤學，家貧無燈，夏月乃聚螢照讀，冬曾聚雪，仕至司徒。","sortOrder":93},
  {"id":"s_work_nvlt_55_94","chapterId":"ch_work_nvlt_55","text":"《晉書》曰：劉寔，字子真，平原人，家貧好學，織牛衣以賣而自給，仕至侍中。遷司徒。","sortOrder":94},
  {"id":"s_work_nvlt_55_95","chapterId":"ch_work_nvlt_55","text":"《漢書》曰：朱買臣，字翁子，會稽人，少家貧，勤學不事產業，位至本郡太守。","sortOrder":95},
  {"id":"s_work_nvlt_55_96","chapterId":"ch_work_nvlt_55","text":"《後漢書》曰：孫敬，字文质，好學，閉戶讀書，不堪其睡，乃以繩懸之屋梁，人曰閉戶先生。","sortOrder":96},
  {"id":"s_work_nvlt_55_97","chapterId":"ch_work_nvlt_55","text":"又曰：倪宽與人佣力，帶經書耕鉏，仕至丞相。","sortOrder":97},
  {"id":"s_work_nvlt_55_98","chapterId":"ch_work_nvlt_55","text":"【詩】宋陶潛讀山海經詩曰：既耕亦已种，且還讀我書，汎覽周王傳，流觀山海圖，俯仰終宇宙，不樂复何如。","sortOrder":98},
  {"id":"s_work_nvlt_55_99","chapterId":"ch_work_nvlt_55","text":"宋謝惠連讀書詩曰：贲園奚足慕，下帷故宜遵，山成由一簣，崇積始微尘，虞軒雖眇莽，顏隰亦何人。","sortOrder":99},
  {"id":"s_work_nvlt_55_100","chapterId":"ch_work_nvlt_55","text":"齊王融抄眾書應司徒教詩曰：說禮固多才，惇詩信為善，巖笥發仙華，金縢开碧篆。","sortOrder":100},
  {"id":"s_work_nvlt_55_101","chapterId":"ch_work_nvlt_55","text":"【賦】晉束晳讀書賦曰：耽道先生，澹泊閒居，藻練精神，呼吸清虛，抗志雲表，戢形陋庐，垂帷帳以隱幾，被紈素而讀書，抑扬嘈囋，或疾或徐，優遊蘊藉，亦卷亦舒，頌卷耳則忠臣喜，詠蓼莪則孝子悲，稱硕鼠則貪民去，唱白駒而賢士歸，是故重華詠詩以終已，仲尼讀易於身中，原憲潛吟而忘賤，顏回精勤以輕貧，倪宽口誦而芸耨，買臣行吟而負薪，賢聖其猶孳孳，况中才與小人。","sortOrder":101},
  {"id":"s_work_nvlt_55_102","chapterId":"ch_work_nvlt_55","text":"【贊】庾信高鳳讀書不知流麥贊曰：高鳳好學，专心不回，留連經笥，對玩書台，石門雲度，銅梁雨來，麥流雖遠，書卷猶开。","sortOrder":102},
  {"id":"s_work_nvlt_55_103","chapterId":"ch_work_nvlt_55","text":"【銘】後漢李尤讀書枕銘曰：聽政理事，怠則覽書，傾倚偃息，隨體興居，寤心起意，由愈宴娱。","sortOrder":103},
  {"id":"s_work_nvlt_55_104","chapterId":"ch_work_nvlt_55","text":"【書】後漢冯衍說邓禹書曰：衍聞昔者先王學大道以觀於政，夫為君而不明於道，上無所承天，下無以化民，為臣而不明於道，進無以事君，退無以修身，聖朝天然之資，將軍純茂之德，誠少遊神乎經書之林，馳情乎玄妙之中，明照於日月，而智溢於四海，聖朝享尧舜之榮，將軍荷稷契之烈，自然理也。","sortOrder":104},
  {"id":"s_work_nvlt_55_105","chapterId":"ch_work_nvlt_55","text":"後漢孔融與宗從弟書曰：知晚節豫學既美，大弟因而能寤。又合先君加我之義，豈唯仁弟，實专承之，凡我宗族，猶或賴焉。","sortOrder":105},
  {"id":"s_work_nvlt_55_106","chapterId":"ch_work_nvlt_55","text":"◇史傳","sortOrder":106},
  {"id":"s_work_nvlt_55_107","chapterId":"ch_work_nvlt_55","text":"《釋名》曰：傳，傳也，以傳示後人。","sortOrder":107},
  {"id":"s_work_nvlt_55_108","chapterId":"ch_work_nvlt_55","text":"《博物志》曰：賢者著行曰傳。","sortOrder":108},
  {"id":"s_work_nvlt_55_109","chapterId":"ch_work_nvlt_55","text":"《漢書》曰：古之王者，世有史官，君舉必書，所以慎言行，昭法戒也，左史記言，右史記事，事為春秋，言為尚書。","sortOrder":109},
  {"id":"s_work_nvlt_55_110","chapterId":"ch_work_nvlt_55","text":"【詩】魏阮瑀詩曰：誤哉秦穆公，身没從三良，忠臣不達命，隨驅就死亡，低頭闚壙戶，仰视日月光，誰謂此可處，恩義不可忘，路人為流涕，黃鳥鳴高桑。","sortOrder":110},
  {"id":"s_work_nvlt_55_111","chapterId":"ch_work_nvlt_55","text":"又詩曰：燕丹養勇士，荆軻為上賓，圖擢盡匕首，長驅西入秦，素車駕白馬，相送易水津，漸離击筑歌，悲聲感路人，舉坐同咨嗟，叹氣若青雲。","sortOrder":111},
  {"id":"s_work_nvlt_55_112","chapterId":"ch_work_nvlt_55","text":"宋陶潛詠荆軻詩曰：惜哉劍術疏，奇功遂不成，其人久已没，千載有餘情。","sortOrder":112},
  {"id":"s_work_nvlt_55_113","chapterId":"ch_work_nvlt_55","text":"陳周弘直賦得荆軻詩曰：荆卿欲報燕，衔恩弃百年，市中傾別酒，水上击離絃，匕首光陵日，長虹氣燭天，留言與宋意，悲歌非自怜。","sortOrder":113},
  {"id":"s_work_nvlt_55_114","chapterId":"ch_work_nvlt_55","text":"陳楊縉賦得荆軻詩曰：函關使不通，燕將重深功，長虹貫白日，易水急寒風，壮發危冠下，匕首地圖中，琴聲不可識，遺恨没秦宮。","sortOrder":114},
  {"id":"s_work_nvlt_55_115","chapterId":"ch_work_nvlt_55","text":"晉袁宏詩曰：周昌梗槩臣，辭達不為讷，汲黯社稷器，棟梁表天骨，陆贾厭解紛，時與酒梼杌，婉轉將相門，一言和平勃，趨舍各有之，俱令道不没。","sortOrder":115},
  {"id":"s_work_nvlt_55_116","chapterId":"ch_work_nvlt_55","text":"又詩曰：無名困蝼蚁，有名世所疑，中庸難為體，狂狷不及時，楊惲非忌貴，知及有餘辭，躬耕南山下，芜秽不遑治，趙瑟奏哀音，秦聲歌新詩，吐音非凡唱，負此欲何之。","sortOrder":116},
  {"id":"s_work_nvlt_55_117","chapterId":"ch_work_nvlt_55","text":"陳阮卓賦詠得魯連詩曰：魯連有高趣，意氣本相求，笑罢秦軍却，書成燕將愁，聊弃南金賞，方從沧海遊，寄言人世客，非君能見留。","sortOrder":117},
  {"id":"s_work_nvlt_55_118","chapterId":"ch_work_nvlt_55","text":"晉左思詠史詩曰：被褐出閶阖，高步追許由，振衣千仞岡，濯足萬里流。","sortOrder":118},
  {"id":"s_work_nvlt_55_119","chapterId":"ch_work_nvlt_55","text":"吾希段幹木，偃息蕃魏君，吾慕魯仲連，談笑却秦軍，當世貴不羁，遭難能解紛，功成恥受賞，高節卓不群。又詠史詩曰：鬱鬱涧底松，離離山上苗，以彼径寸茎，荫此百尺條，世胄躡高位，英俊沉下僚，地势使之然，由來非一朝，金張籍舊業，七葉弭漢貂，冯公豈不伟，白首不見招。","sortOrder":119},
  {"id":"s_work_nvlt_55_120","chapterId":"ch_work_nvlt_55","text":"又詠史詩曰：主父宦不達，骨肉還相薄，買臣困樵采，伉俪不安宅，陳平無產業，歸來翳負郭，長卿還成都，壁立何寥廓，四賢豈不伟，遺烈光篇籍，當其未遇時，忧在填溝壑，英雄有屯邅，由來自古昔，何世無奇才，遺之在草泽。","sortOrder":120},
  {"id":"s_work_nvlt_55_121","chapterId":"ch_work_nvlt_55","text":"晉張协詠史詩曰：昔在西京時，朝野多歡娱，藹藹東都門，群公祖二疏，朱軒曜金城，供帳臨長衢，達人知止足，遺榮忽如無，抽簪解朝衣，散發歸海隅。","sortOrder":121},
  {"id":"s_work_nvlt_55_122","chapterId":"ch_work_nvlt_55","text":"宋孝武詠史詩曰：聂政凭驍氣，荆軻擅美風，孤刃駭韓庭，獨步震秦宮，懷音豈若始，捐驅在命終，雄姿列往志，流聲固無窮。","sortOrder":122},
  {"id":"s_work_nvlt_55_123","chapterId":"ch_work_nvlt_55","text":"宋鮑昭詠史詩曰：五都矜财雄，三川養聲利，百金不市死，明經有高位，京城十二衢，飛甍各鱗次，仕子飄華纓，遊客竦輕辔，明星辰未晞，軒蓋已雲至，賓御紛飒沓，鞍馬光照地，寒暑在一時，繁華及春媚，君平獨寂漠，身势兩相弃。","sortOrder":123},
  {"id":"s_work_nvlt_55_124","chapterId":"ch_work_nvlt_55","text":"陳張正見賦得韓信詩曰：淮陰總漢兵，燕齊擅遠聲，沉沙擁急水，拔幟上危城，野有千金報，朝稱三杰名，所悲雲夢泽，空傷狡兔情。","sortOrder":124},
  {"id":"s_work_nvlt_55_125","chapterId":"ch_work_nvlt_55","text":"陳劉删賦得蘇武詩曰：奉使窮沙漠，抆淚上河梁，食雪天山近，思歸海路長，系書秋待雁，握節暮看羊，因思李都尉，還漢不相忘。","sortOrder":125},
  {"id":"s_work_nvlt_55_126","chapterId":"ch_work_nvlt_55","text":"陳祖孫登賦得司馬相如詩曰：雍容文雅深，王吉共追尋，當壚應酤酒，讬意且彈琴，上林能作賦，長門得賜金，唯當有漢主，知懷封禪心。","sortOrder":126},
  {"id":"s_work_nvlt_55_127","chapterId":"ch_work_nvlt_55","text":"隋王由禮賦得馬援詩曰：二帝已馳聲，五溪還總兵，受詔金鞍動，論功銅馬成，唯稱聚米势，無慚薏苡情，雖謝雲台影，猶傳千載名。","sortOrder":127},
  {"id":"s_work_nvlt_55_128","chapterId":"ch_work_nvlt_55","text":"【志】後漢班固述五行志曰：河圖命宓，洛書賜禹，八卦成列，九畴追叙，世代是寶，光演文武，春秋之占，各徵是舉。","sortOrder":128},
  {"id":"s_work_nvlt_55_129","chapterId":"ch_work_nvlt_55","text":"又藝文志述曰：伏羲畫卦，書契後作，虞夏商周，孔纂其業，纂書删詩，缀禮正樂，彖系大易，因史立法，六學既登，遭世罔弘，群言紛亂，諸子相騰，秦人是滅，漢循其缺，劉向司籍，九流區別。","sortOrder":129},
  {"id":"s_work_nvlt_55_130","chapterId":"ch_work_nvlt_55","text":"【銘】宋顏延之家傳銘曰：曠彼琅邪，實唯海宇，誰其來遷，時聞遠祖，青州隱秀，爰始貞居，內辭鼎府，外秉邦闾，建節中平，分竹黃初，刑清齊石，［○《初學記》二十一作右。］政偃營區，葛嶧明懿，平陽聰理，式荐公庭，或登宰士，列美霸朝，双風千里，華萼之茂，於昭不已。","sortOrder":130},
  {"id":"s_work_nvlt_55_131","chapterId":"ch_work_nvlt_55","text":"【表】梁簡文帝上昭明太子集別傳等表曰：臣聞無懷有巢之前，書契未作，尊盧赫胥之氏，墳典不傳，昭明太子，禀仁聖之姿，縱生知之量，孝敬兼極，溫恭在躬，明月西流，幼有文章之敏，羽籥東序，長備元良之德，蘊茲三善，弘此四聰，地尊虢嗣，外陽之術無徽，［昭明太子集首作徵。］位比周储，缑山之駕不反，無以歈扬盛軌，宣記德音，請備之延閣，藏諸廣內，丞彰茂實，式表洪徽。","sortOrder":131},
  {"id":"s_work_nvlt_55_132","chapterId":"ch_work_nvlt_55","text":"【傳】梁江淹自序傳曰：淹字文通，濟陽考成人，為建安吳興令，地在東南峤外，閩越之舊境也，爰有碧水丹山，珍木靈草，皆淹平生所至愛，不覺行路之遠也，山中無事，专與道書為偶，及悠然獨往，或日夕忘歸，放浪之际，頗著文章自娱，常原卜居筑宇，絕弃人事，苑以丹林，池以渌水，左倚郊甸，右帶洒泽，青春受謝，則梜弋平皋，素秋澄景，則獨酌虛室，侍姬三四，趙女數人，不則逍遙經紀，彈琴詠詩，朝露幾間，忽忘老之將至雲爾，淹之學盡此而已矣。","sortOrder":132},
  {"id":"s_work_nvlt_55_133","chapterId":"ch_work_nvlt_55","text":"【論】宋范晔宦者論曰：宦人之在王朝者，其來舊矣，將以其體非全氣，意志专良，通關中人，易以役養乎，漢仍袭秦製，置中常侍官，然引用士人，以參其選，皆銀璫左貂，給事殿省，中興之初，宦者悉用閹人，不复雜調他士，和帝即祚幼弱，而窦憲兄弟，专總權威，內外臣僚，莫由親接，所與居者，唯閹官而已，故鄭眾得专謀禁中，終除大憝，遂享分王之封，超登公卿之位，於是中官始盛焉，改以金璫右貂，兼領卿署之位，邓後以女主臨政，而萬機殷遠，帷幄製令，不出房闈之間，不得不委刑人，寄之國命，其後孫程定立順之功，曹騰參建桓之策，跡因公正，恩固主心，故中外服從，上下屏氣，雖時有忠公，而競見排斥，舉動回山海，呼吸变霜露，阿旨曲求，則光寵三族，直情忤意，參夷五宗，漢之綱紀大亂矣。","sortOrder":133},
  {"id":"s_work_nvlt_55_134","chapterId":"ch_work_nvlt_55","text":"梁沈約王僧達顏峻傳論曰：世祖弱歲臨蕃，遊道未曠，披胸解帶，義止賓僚，及運鍾傾波，身危慮切，擢胆抽肝，猶患言未盡已也，至於凭玉負扆，威行萬物，有欲必從，事無暫反，既而忧歡異日，甘苦变心，主挟今情，臣追昔款，宋昌之報，上賞已行，同舟之慮，下望愈結，嫌怨既萌，誅责自起，竣之取衅於世，蓋由此乎，為人臣者，若能事主而損其私，立功而忘其報，雖求顛陷，不可得也。","sortOrder":134},
  {"id":"s_work_nvlt_55_135","chapterId":"ch_work_nvlt_55","text":"◇集序","sortOrder":135},
  {"id":"s_work_nvlt_55_136","chapterId":"ch_work_nvlt_55","text":"孔安國尚書序曰：序者，所以序作者之意。","sortOrder":136},
  {"id":"s_work_nvlt_55_137","chapterId":"ch_work_nvlt_55","text":"魏陳王曹植文章序曰：故君子之作也，俨乎若高山，勃乎若浮雲，质素也如秋蓬，摛藻也如春葩，汜乎洋洋，光乎〈月高〉々，與雅頌爭流可也，餘少而好賦，其所尚也，雅好慷慨，所著繁多，雖觸類而作，然芜秽者眾，故删定別撰，為前錄七十八篇。","sortOrder":137},
  {"id":"s_work_nvlt_55_138","chapterId":"ch_work_nvlt_55","text":"梁昭明太子文選序曰：夫椎輪為大路之始，大路寧有椎輪之质，增冰為積水所成，積水微增冰之凛，何哉，蓋有踵其事而增華，变其本而加麗，物既有之，文亦宜然，隨時变改，難可詳悉，眾製鋒起，源流間出，譬陶匏異品，併為入耳之娱，黼黻不同，俱為悅目之玩，作者之致，蓋雲備矣。","sortOrder":138},
  {"id":"s_work_nvlt_55_139","chapterId":"ch_work_nvlt_55","text":"梁簡文帝臨安公主集序曰：四德之美，戚里仰以為風，七行之奇，濯龍規以為則，若夫讬句陳之貴，出玉台之尊，鳳儀閒润，神姿照朗，愛敬之道夙彰，柔娴之才必備，鳳桐遐遠，清管遼亮，湘川寂寞，淚筱葳蕤，北渚之句尚傳，仙靈之典不泯，况复文同積玉，韻比風飛，謹求散逸，貽厥於後。","sortOrder":139},
  {"id":"s_work_nvlt_55_140","chapterId":"ch_work_nvlt_55","text":"梁元帝職貢圖序曰：竊聞職方氏掌天下之圖，四夷八蠻，七閩九貉，其所由來久矣，漢氏以來，南羌旅距，西域凭陵，創金城，开玉關，絕夜郎，讨日逐，睹犀申則建朱崖，聞蒲陶則通大宛，以德懷遠，異乎是哉，皇帝君臨天下之四十載，垂衣裳而賴兆民，坐巖廊而彰萬國，梯山航海，交臂屈膝，占雲望日，重譯至焉，自塞以西，萬八千里，路之峡者，尺有六寸，高山尋雲，深穀絕景，雪無冬夏，與白雲而共色，水無早晚，與素石而俱貞，逾空桑而歷崑吾，度青丘而跨丹穴，灾風弱水，不革其心，身熱頭痛，不改其節，故以明珠翠羽之珍，細而弗有，龍文汗血之骥，却而不乘，尼丘乃聖，猶有圖人之法，晉帝君臨，寔聞樂賢之象，甘泉寫閼氏之形，後宮玩单於之圖，臣以不佞，推轂上遊，夷歌成章，胡人遙集，款开蹶角，沿溯荆門，瞻其容貌，訴其風俗，如有來朝京輦，不涉漢南，別加訪采，以廣聞見，名為貢職圖雲爾。","sortOrder":140},
  {"id":"s_work_nvlt_55_141","chapterId":"ch_work_nvlt_55","text":"梁任昉齊王俭集序曰：公之生也，誕授命世，體三才之茂，踐得二之機，信乃昴宿垂芒，德精降祉，有一於此，蔚為帝師，若乃金版玉匮之書，海上名山之旨，沉鬱澹雅之思，離堅合異之談，莫不總製清衷，遞為心極，斯固通人之所包，非虛明之絕境，不可窮者，其唯神用者乎，時司徒袁粲，有高世之度，脱落風尘，見公弱齡，便望風推服，叹曰：衣冠禮樂，盡在是矣，時粲位亚台司，公始弱冠，年势不侔，公與之抗禮，因赠粲詩，要以歲暮之期，申以止足之誡，時聖武定業，肇基王命，寤寐風雲，寔資人杰，是以宸居膺列宿之表，圖緯著王佐之符，俄遷長史，齊台既建，以公為尚書右仆射，領吏部，時年二十八，宋末艱虞，百王浇季，禮紊舊宗，樂傾恒軌，自朝章國紀，典彝備物，奏議符策，文辭表記，素意所不蓄，前古所未行，皆取定俄頃，神無滯用，公在物斯厚，居身以約，玩好絕於耳目，布素形於造次，室無姬薑，門多長者，立言必雅，未嘗顯其所長，持論從容，未嘗言人所短，弘奖風流，許與氣類，造理常若可幹，臨事每不可奪，約己不以庶物，弘量不以容非，攻乎異端，歸之義正，昉行無異操，才無異能，得奉名節，迄將一紀，一言之譽，東陵侔於西山，一眄之榮，鄭璞逾於周寶，士感知己，懷此何極，出入禮闈，朝夕舊馆，瞻棟宇而興慕，撫身名而悼恩，公自幼及長，述作不倦，固以理窮言行，事該軍國，豈直彫章縟采而已哉。","sortOrder":141},
  {"id":"s_work_nvlt_55_142","chapterId":"ch_work_nvlt_55","text":"梁王僧孺臨海伏府君集序曰：袁粲領袖一時，儀形物右，聲逾裴樂，譽出王劉，士有懷道蘊義，望尘而趨者，或三年而未識，乍四旬而一見，與君道合神遇，投分披衿，敷文研理，匪晨伊暮，至於神經怪諜，绿笥丹筒，金版玉箱，錦文緹帙，併藏諸靈府，秘在瑤台，而君莫不遍探冥赜，具閱局檢，常以前賢往學，亟與聖违，贾馬盧鄭，非無紕越，荀郭何王，弥多踳谬，二義可辨，未值高卿之疑，九事非難，不逢五叔之問，其詩賦銘诔，所作尤多。","sortOrder":142},
  {"id":"s_work_nvlt_55_143","chapterId":"ch_work_nvlt_55","text":"又詹事徐府君集序曰：君禀靈川嶽，懸精辰象，早照珪璋，夙表岐嶷，孝睦天禀，友愛冥深，故以事顯家庭，聲著同族，年十八，見召為國子生，曳裾持卷，寔華庠璧，有均閉戶，靡因餘竈，每攝齊函丈，左右屬目，蓄以鄰幾之性，加以入神之資，聞一知二，師逸功倍，遊魏闕而不殊江海，入朝廷而靡異山林，未嘗捉刺權門，驅車戚里，遨遊梁董，去來贾郭，時春秋猶少，人爵未崇，而清風嘉譽，震灼朝野，非直俯致貴仕，故可坐享通侯，而緤馬懸車，閉門高枕，聊為诡遇，識此行藏，及皇運聿興，重氛載廓，君藏器待時，合猶符契，陵扶搖而高骛，排閶阖而容與，故位隨德顯，任與事隆，重以姿儀端润，趨眄淹華，寶佩鳴風，丰貂映日，從容帷扆，綽有餘辉，自綢缪軒陛，十有餘載，溫树靡答，露事不詶，省中之言無漏，席下之跡不疑，故以主聖臣賢，應同廛玺，以石投水，如鱗縱壑，行稱表缀，言成模楷，猶复忘彼丰愉，安茲素薄，衣同屢補，食等三杯，車服不事鮮明，室宇畏其彫奐，九德無遺，百行備舉，至於专心六典，精赜必深，汎遊群籍，菁華無弃，搦札含毫，必弘靡麗，摛綺縠之思，鬱風霞之情，质不傷文，麗而有體。","sortOrder":143},
  {"id":"s_work_nvlt_55_144","chapterId":"ch_work_nvlt_55","text":"陳劉師知侍中沈府君序集曰：陳亢有雲，趨庭學詩。又聞君子毛萇亦曰：登高能賦，可為大夫，言其善觀民風，則與圖王政，若沈恭子者，斯乃當世才焉，至如敦厚之詞，足以吟詠情性，身之文也，貞固之節，可以宣被股肱，邦之光也，然此者君之小道，猶曰餘行，何則，德之所本，教之所由，實乃孝篤天倫，義感殊類，有美於斯，鬱為高士，則餘與夫子，古所謂世親者欤，亦所謂友益者欤，畴昔一面，朅來二紀，自總角而接清尘，蒙長者之嘉釂，屯险骤更，懽娱中阻，班超既反，盛憲猶存，春秋美景，朝遊夕宴，酒酣得意，賦詩聯章，顧餘不肖，齒義懸絕，降德忘年，交情弥至，增榮廣价，知己難忘，南浦之送未淹，北印之辭仍及，於時屬有烽燧，方勤帷扆，遂使褐裘莫計，寶劍無追，痛此生刍，同茲宿草，九原方遠，百身寧購，若乃帳懸秋月，一雁孤飛，落花春風，數湋爭弄，伯牙之絃，寂寥長絕，山陽之管，惆怅徒聞，夫盛烈清徽，便傳乎帝載，遺文餘論，被在乎民謠者，斯所以没而猶彰，死且不朽，今乃撰西還所著文章，名為後集。","sortOrder":144},
  {"id":"s_work_nvlt_55_145","chapterId":"ch_work_nvlt_55","text":"陳徐陵玉台新詠序曰：陵雲槩日，由餘之所未窥，千門萬戶，張衡之所曾賦，周王璧台之上，漢帝金屋之中，玉树以珊瑚作枝，珠帘以玳瑁為押，其中有麗人焉，其人也五陵豪族，充選掖庭，四姓良家，馳名永巷，說詩明禮，豈東鄰之自媒，婉約風流，異西施之被教，兄弟协律，生小學歌，少長河陽，由來能舞，琵琶新曲，無待石崇，箜篌雜句，非關曹植，傳鼓瑟於楊家，得吹箫於秦女，寵聞長樂，陳後知而不平，畫出天仙，閼氏覽而遙妒，陪遊馺娑，騁纖腰於結風，張樂鴛鸞，奏新聲於度曲，裝鳴蝉之薄鬢，照墮馬之垂鬟，反插金莲，橫抽寶树，南都石黛，最發双娥，北地燕脂，偏开兩靨，亦有嶺上仙童，分丸魏帝，腰中寶鳳，授歷軒轅，金星與婺女爭華，麝月與姮娥競爽，驚鸞冶袖，時飄韓掾之香，飛燕長裙，宜結陳王之珮，雖非圖畫，入甘泉而不分，言異神仙，戲陽台而無別，加以天情开朗，逸思雕華，妙解文章，尤工詩賦，清文滿箧，非唯芍藥之花，新製連篇，寧止蒲桃之树，九月登高，時有緣情之作，萬年公主，非無累德之詞，既而椒房婉轉，柘馆陰岑，木鶴晨嚴，銅梁晝靖，優遊少讬，寂寞多閒，厭長樂之疏鐘，勞中宮之缓箭，身輕無力，怯南陽之捣衣，生長深宮，笑扶風之織錦，雖复投壶玉女，為歡盡於百娇，爭博齊姬，心賞窮於六著，無怡神於暇景，唯屬意於新詩，但往世名篇，當今巧製，分封麟閣，散在鸿都，不籍連章，無由披覽，於是燃脂暝寫，弄墨晨書，撰錄艳歌，凡為十卷，曾無參於雅頌，亦靡濫於風人，涇渭之間，若斯而已也，至如青牛帳里，餘曲未終，朱鳥窗前，新妆已竟，方當开茲縹帙，散此縚繩，永對玩於書帷，長循環於纖丰。","sortOrder":145},
  {"id":"s_work_nvlt_55_146","chapterId":"ch_work_nvlt_55","text":"隋江總陶貞白先生集序曰：昔劉向通古今之學，馬融見天下之書，京房察風雨之占，裴［按下雲公矩才免極誅，襄楷字公矩，是裴當作襄。］楷晓陰陽之術，子政傷於簡易，季長敝於驕侈，君明遂不旋踵，公矩才免極誅，鮮有盡美之跡，罕聞克終之譽，若夫德行博敏，孔室四科，經術深長，鄭門六藝，丹陽陶先生備斯矣，至如紫台青簡，绿帙丹經，玉版秘文，瑤壇怪牒，靡不貫彼精微，殫其旨趣，蓋非常之絕伎，命世之異人焉，文集缺亡，未有編錄，門人補辑，若逢遼東之本，好事研搜，如誦河西之箧，奉敕校之鉛墨，緘以緹緗，藏彼鸿都，副在延閣。","sortOrder":146},
  {"id":"s_work_nvlt_55_147","chapterId":"ch_work_nvlt_55","text":"周庾信趙國公集序曰：竊聞平陽击石，山穀為之調，大禹吹筠，風雲為之動，與夫含吐性靈，抑扬詞氣，曲变陽春，光回白日，豈得同年而語哉，柱國公發言為論，下筆成章，逸態橫生，新情掞起，風雨爭飛，魚龍各变，方之珪璧，涂山之會萬重，譬似雲霞，赤城之巖千丈，文參歷象，即入天官之書，韻涉絲桐，鹹歸總章之觀，論其壮也，則鵬起半天，語其細也，則鹪巢蚊睫，豈直熊熊旦上，增城抱日月之光，焰焰霄飛，南斗觸蛟龍之氣，昔者屈原宋玉，始於哀怨之深，蘇武李陵，生於別離之世，自魏建安之末，晉太康以來，彫虫篆刻，其體三变，人人自謂握靈蛇之珠，抱荆山之玉矣，公斟酌雅頌，諧和律呂，若使言乖節目，則曲台不顧，聲止操缦，則成均無取，遂得棟梁文囿，冠冕詞林，大雅扶輪，小生承蓋。","sortOrder":147},
  {"id":"s_work_nvlt_55_148","chapterId":"ch_work_nvlt_55","text":"《藝文類聚》　唐·欧陽詢","sortOrder":148},
  {"id":"s_work_nvlt_56_1","chapterId":"ch_work_nvlt_56","text":"卷五十六雜文部二","sortOrder":1},
  {"id":"s_work_nvlt_56_2","chapterId":"ch_work_nvlt_56","text":"○詩賦","sortOrder":2},
  {"id":"s_work_nvlt_56_4","chapterId":"ch_work_nvlt_56","text":"《毛詩序》曰：詩者，志之所之也，在心為志，發言為詩。","sortOrder":4},
  {"id":"s_work_nvlt_56_5","chapterId":"ch_work_nvlt_56","text":"《春秋說題辭》曰：在事為詩，未發為謀。","sortOrder":5},
  {"id":"s_work_nvlt_56_6","chapterId":"ch_work_nvlt_56","text":"《漢書》曰：誦其言謂之詩。","sortOrder":6},
  {"id":"s_work_nvlt_56_7","chapterId":"ch_work_nvlt_56","text":"《文章流別論》曰：書雲，詩言志，歌永言，言其志謂之詩，古有采詩之官，王者以知得失，史記曰：古詩三千餘篇，孔子删取三百五篇，皆絃歌，以合韶武之音。","sortOrder":7},
  {"id":"s_work_nvlt_56_8","chapterId":"ch_work_nvlt_56","text":"《左傳》曰：昔周穆王欲肆其心，周行天下，將必有車轍馬跡，祭公謀父，作祈招以止王心，其詩曰：祈招之愔愔，式招德音，思我王度，式如玉，式如金。","sortOrder":8},
  {"id":"s_work_nvlt_56_9","chapterId":"ch_work_nvlt_56","text":"《論語》曰：小子何莫學夫詩，詩可以興，可以觀，可以群，可以怨，邇之事父，遠之事君，多識於鳥獸草木之名。","sortOrder":9},
  {"id":"s_work_nvlt_56_10","chapterId":"ch_work_nvlt_56","text":"《詩緯含神霧》曰：詩者，天地之心，君德之祖，百福之宗，萬物之戶也。","sortOrder":10},
  {"id":"s_work_nvlt_56_11","chapterId":"ch_work_nvlt_56","text":"《穆天子傳》曰：至於黃竹，天子乃休，日中大寒，北風雨雪，天子作詩我徂黃竹三章，以哀民。","sortOrder":11},
  {"id":"s_work_nvlt_56_12","chapterId":"ch_work_nvlt_56","text":"《漢武帝集》曰：奉車子集［《太平御覽》五百九十二作侯。］暴病，一日死，上甚悼之，乃自為歌詩。","sortOrder":12},
  {"id":"s_work_nvlt_56_13","chapterId":"ch_work_nvlt_56","text":"《列子》曰：尧微服遊於康衢，聞兒童謠曰：立我蒸民，莫匪爾極，不識不知，順帝之則，尧問曰：孰教爾為此言，童兒曰：我聞之大夫，問大夫，大夫曰：古詩。","sortOrder":13},
  {"id":"s_work_nvlt_56_14","chapterId":"ch_work_nvlt_56","text":"《漢書》曰：匡衡，字稚珪，好學，家貧，佣作以供資用，尤精詩，力過絕人，諸儒為之語曰：無說詩，匡鼎來，［應劭曰：鼎，方也，張晏曰：匡衡少時字鼎。］匡說詩，解人颐。","sortOrder":14},
  {"id":"s_work_nvlt_56_15","chapterId":"ch_work_nvlt_56","text":"又曰：益州刺史王襄，欲宣風化眾庶，聞王褒有俊才，使褒作中和樂職宣布詩，選好事者習而歌之，時汜乡侯何武為童子，選在歌中，久之，武等學長安，歌大學下，轉而上聞，宣帝召武等觀之，皆賜帛，謂曰：此盛德之事，吾何足以當之。","sortOrder":15},
  {"id":"s_work_nvlt_56_16","chapterId":"ch_work_nvlt_56","text":"又曰：古者諸侯卿大夫，交接鄰國，以微言相感，當揖讓之時，必稱詩以喻其志，蓋以別賢不肖而觀盛衰，故孔子曰：不學詩無以言也。","sortOrder":16},
  {"id":"s_work_nvlt_56_17","chapterId":"ch_work_nvlt_56","text":"趙書曰：徐光，字季武，頓丘人，年十四五，為將軍王陽秣馬，光但書馬柳［《太平御覽》五百八十六作枊，此訛。］屋柱為詩，不親馬事。","sortOrder":17},
  {"id":"s_work_nvlt_56_18","chapterId":"ch_work_nvlt_56","text":"《世說》曰：夏侯湛作周詩成，以示潘嶽，曰：此文非徒溫雅，乃別見孝悌之性，潘因此遂作家風詩。","sortOrder":18},
  {"id":"s_work_nvlt_56_19","chapterId":"ch_work_nvlt_56","text":"又曰：郭景純詩雲，林無靜树，川無停流，阮遙集雲，泓峥箫瑟，實不可言，每讀此，辄覺神超形越。","sortOrder":19},
  {"id":"s_work_nvlt_56_20","chapterId":"ch_work_nvlt_56","text":"漢孝武皇帝元封三年作柏梁台，詔群臣二千石，有能為七言者，乃得上坐，皇帝曰：日月星辰和四時，梁王曰：驂駕驷馬從梁來，大司馬曰：郡國士馬羽林才，丞相曰：總領天下誠難治，大將軍曰：和撫四夷不易哉，御史大夫曰：刀筆之吏臣執之，太常曰：撞鐘击鼓聲中詩，宗正曰：宗室廣大日益滋，衛尉曰：周衛交戟禁不時，光祿勋曰：總領從官柏梁台，廷尉曰：平理請谳决嫌疑，太仆曰：循飾舆馬待駕來，大鸿臚曰：郡國吏功差次之，少府曰：乘舆御物主治之，大司農曰：陳粟萬硕楊以箕，執金吾曰：徼道宮下隨讨治，左冯翊曰：三辅盜賊天下尤，右扶風曰：盜阻南山為民灾，京兆尹曰：外家公主不可治，詹事曰：椒房率更領其财，典屬國曰：蠻夷朝贺常會期，大匠曰：柱枅薄栌相枝持，太官令曰：枇杷橘栗桃李梅，上林令曰：走狗逐兔張罝罘，郭舍人曰：齧妃女唇甘如飴，東方朔曰：迫窘詰屈幾窮哉。","sortOrder":20},
  {"id":"s_work_nvlt_56_21","chapterId":"ch_work_nvlt_56","text":"宋孝武帝華林都亭曲水聯句效柏梁體，九宮盛事予旒纊，宋孝武帝，三辅務根誠難亮，楊州刺史江夏王臣義恭，策拙枌乡慚恩望，南徐州刺史竟陵王臣誕，折衡莫效興民謗，領軍將軍臣元景，侍禁衛储恩逾量，太子右率臣畅，臣谬叨寵九流曠，吏部尚書臣莊，喉唇废職方思讓，侍中臣偃，明筆直繩天威谅，御史中丞臣顏師伯。","sortOrder":21},
  {"id":"s_work_nvlt_56_22","chapterId":"ch_work_nvlt_56","text":"梁武帝清暑殿聯句柏梁體，居中負扆寄纓绂，［梁武帝。］言慚輻凑政無術，［新安太守任昉。］至德無恨愧违弼，［侍中徐勉。］燮贊京河豈微物，［丹陽丞劉汎。］竊侍兩宮慚枢密，［黃門侍郎柳憕。］清通簡要臣豈汨，［吏部郎中謝覽。］出入帷扆濫榮秩。［侍中張卷。］複道龍樓歌楙實，［太子中庶子王峻。］空班獨坐慚羊质，［御史中丞陆果，○按當作杲。］嗣以書記臣敢匹，［右軍主簿陆倕。］谬參和鼎講畫一，［司徒主簿劉洽。］鼎味參和臣多匮，［司徒左西屬江葺。］","sortOrder":22},
  {"id":"s_work_nvlt_56_23","chapterId":"ch_work_nvlt_56","text":"梁元帝宴清言殿作柏梁體，玉衡七政轉璇璣，［梁元帝。］升降端揆而才非，［侍中尚書仆射臣裒。］澄鏡朱紫眇難追，［吏部尚書臣穀。］","sortOrder":23},
  {"id":"s_work_nvlt_56_24","chapterId":"ch_work_nvlt_56","text":"後漢孔融離合詩，郡姓名詩曰：漁父屈節，水潛匿方，與時進止，出行施張，呂公飢釣，阖口渭旁，九域有聖，無土不王，好是正直，女固予匡，海外有截，隼逝鷹扬，六翮不奋，羽儀未彰，龍蛇之蟄，俾也可忘，玖璇隱曜，美玉韜光，無名［二字原脱，據冯校本補。］無譽，放言深藏，按辔安行，誰謂路長，［魯國孔融文舉。］","sortOrder":24},
  {"id":"s_work_nvlt_56_25","chapterId":"ch_work_nvlt_56","text":"梁元帝離合詩曰：泬寥雲物净，水木備春光，龛定方無遠，合浦不難航，［○原訛抗，據冯校本改，寵。］","sortOrder":25},
  {"id":"s_work_nvlt_56_26","chapterId":"ch_work_nvlt_56","text":"梁萧巡離合詩，赠尚書令何敬容曰：枝能本無取，支葉复单貧，柯條谬承日，木石豈知晨，狗馬誠難盡，犬羊非賜馴，效嚬既不似，學步孰能真，寔由紊朝典，是曰蠹彝倫，俗化於茲鄙，人涂自此分。","sortOrder":26},
  {"id":"s_work_nvlt_56_27","chapterId":"ch_work_nvlt_56","text":"陳沈蜅離合詩，赠江藻曰：开門枕芳野，井上發紅桃，林中藤茑［原訛{艹馬}，據冯本改。］秀，木末風雲高，屋室何寥廓，志士隱蓬蒿，故知人外賞，文酒易陶陶，朋友足諧晤。又此盛詩骚，朗月同携手，良景共含毫，栾巴有妙術，言是神仙曹，百年肆偃仰，一理詎相勞，［閒居有樂。］","sortOrder":27},
  {"id":"s_work_nvlt_56_28","chapterId":"ch_work_nvlt_56","text":"晉潘嶽離合詩曰：佃漁始化，人民穴處，意守醇朴，音應律呂，桑梓被源，卉木在野，錫鸞未設，金石拂舉，害咎蠲消，吉德流普，谿穀可安，奚作棟宇，嫣然以憙，焉懼外侮，熙神委命，已求多祜，叹彼季末，口出擇語，誰能墨誠，言丧厥所，垄畝之諺，龍潛巖阻，鮮義崇亂，少長失叙，［思楊容姬難堪。］","sortOrder":28},
  {"id":"s_work_nvlt_56_29","chapterId":"ch_work_nvlt_56","text":"宋何長瑜離合詩曰：宜然悅今會，且怨明晨別，肴蔌不能甘，有難不可雪，［網。］","sortOrder":29},
  {"id":"s_work_nvlt_56_30","chapterId":"ch_work_nvlt_56","text":"宋孝武離合詩曰：霏雲起兮汎濫，雨霭昏而不消，意氣悄以無樂，音尘寂而莫交，守邊境以臨敵，寸心厲於戎昭，閣盈圖記，門滿賓僚，仲秋始戒，中園初凋，池育秋莲，水滅寒漂，旨歸涂以易感，日月逝而難要，分中心而誰寄，人懷念而必謠，［悲客他方。］","sortOrder":30},
  {"id":"s_work_nvlt_56_31","chapterId":"ch_work_nvlt_56","text":"宋謝惠連離合詩曰：放棹遵遙涂，方與情人別，嘯歌亦何言，肅爾凌霜節，［穀。］","sortOrder":31},
  {"id":"s_work_nvlt_56_32","chapterId":"ch_work_nvlt_56","text":"又曰：夫人皆薄離，二友獨懷古，思篤子衿詩，山川何足苦，［念。］又夜集作離合詩曰：四坐宴嘉賓，一客自遠臻，九言何所戒，十善故宜遵，［此。］","sortOrder":32},
  {"id":"s_work_nvlt_56_33","chapterId":"ch_work_nvlt_56","text":"宋謝靈運作離合詩曰：古人怨信次，十日眇未央，加我懷繾綣，口詠情亦傷，剧哉歸遊客，處子勿相忘。［別。］","sortOrder":33},
  {"id":"s_work_nvlt_56_34","chapterId":"ch_work_nvlt_56","text":"宋贺道慶離合詩曰：促席宴閒夜，足歡不覺疲，詠歌無餘原，永言終在斯。［信。］","sortOrder":34},
  {"id":"s_work_nvlt_56_35","chapterId":"ch_work_nvlt_56","text":"齊石道慧離合詩曰：好仇華良夜，子歡我亦欣，昊穹出明月，一坐感良晨。［娱。］","sortOrder":35},
  {"id":"s_work_nvlt_56_36","chapterId":"ch_work_nvlt_56","text":"齊王融離合詩曰：冰容慚遠鑒，水质謝明暉，是照相思夕，早望行人歸。［火。］","sortOrder":36},
  {"id":"s_work_nvlt_56_37","chapterId":"ch_work_nvlt_56","text":"又回文詩曰：枝大柳塞北，葉暗榆關東，垂條逐絮轉，落蕊散花丛，池莲照晓月，幔錦拂朝風，晓吹纶雜羽，薄粉艳妆紅，離情隔遠道，叹結深閨中。","sortOrder":37},
  {"id":"s_work_nvlt_56_38","chapterId":"ch_work_nvlt_56","text":"又後園作回文詩曰：斜峰繞径曲，耸石帶山連，花餘拂戲鳥树密隱鳴蝉。","sortOrder":38},
  {"id":"s_work_nvlt_56_39","chapterId":"ch_work_nvlt_56","text":"梁簡文帝和湘東王後園回文詩曰：枝雲間石峰，脈水侵山岸，池清戲鵠聚，树秋飛葉散。","sortOrder":39},
  {"id":"s_work_nvlt_56_40","chapterId":"ch_work_nvlt_56","text":"梁劭陵王萧纶回文詩曰：燭華臨靜夜，香氣入重帷，曲度聞歌遠，繁絃覺舞遲。","sortOrder":40},
  {"id":"s_work_nvlt_56_41","chapterId":"ch_work_nvlt_56","text":"周庾信和回文詩曰：旱莲生竭镬，嫩菊養秋鄰，滿池留浴鳥，分桥上戲人。","sortOrder":41},
  {"id":"s_work_nvlt_56_42","chapterId":"ch_work_nvlt_56","text":"梁定襄侯和回文詩曰：危台出岫回，曲涧上桥斜，池莲隱弱芰，径筱落藤花。","sortOrder":42},
  {"id":"s_work_nvlt_56_43","chapterId":"ch_work_nvlt_56","text":"宋鮑昭建除詩曰：建旗出敦煌，西讨屬國羌，除去徒舆騎，戰車羅萬箱，滿山又填穀，投鞍合營牆，平原亘千里，旌鼓轉相望，定舍後未休，候騎前敕裝，執戈無暫頓，弯弧不解張，破滅西零國，生虜郅支王，危亂悉平荡，萬里置關梁，成車入王門，女獻玉壶漿，收功在一時，歷世荷餘光，开壤袭朱绂，左右佩金章，閉帷草太玄，茲事殆愚狂。","sortOrder":43},
  {"id":"s_work_nvlt_56_44","chapterId":"ch_work_nvlt_56","text":"梁宣帝建除詩曰：建國惟神業，十世本靈長，除奇逾漢祖，徯後類殷湯，滿盈既虧度，否運理還康，平階今复睹，德星行見祥，定寇資雄略，靜亂屬賢良，執訊窮郢魯，弔伐遍徐楊，破敵勋佣盛，佩紫且懷黃，危苗既已竄，妖沴亦雲亡，成功勒雲社，治定禮要荒，收戟歸農器，牧馬恣刍場，开山接梯路，架海擬山梁，閉欲同彭老，延寿等東皇。","sortOrder":44},
  {"id":"s_work_nvlt_56_45","chapterId":"ch_work_nvlt_56","text":"梁范雲建除詩曰：建國負東海，衣冠成營丘，除道梁淄水，結驷登之罘，滿座鹹嘉友，蘋藻絕時羞，平望極聊攝，直视盡姑尤，定交無恒所，同志互相求，執手歡高宴，舉白窮獻酬，破琴豈重賞，臨豪寧再儔，危生一朝露，蝼蚁將見謀，成功退不處，為名自此收，收名弃車馬，单步反蜗牛，开渠納秋水，相土播春畴，閉門謝世人，何欲复何求。","sortOrder":45},
  {"id":"s_work_nvlt_56_46","chapterId":"ch_work_nvlt_56","text":"陳沈炯建除詩曰：建章連鳳闕，藹藹入雲煙，除庭發槐柳，冠劍似神仙，滿衢飛玉轪，夹道躍金鞭，平明尘霧合，薄暮風雲褰，定交大學里，射策雲台邊，執事一朝谬，朝市忽崩遷，破家徒徇國，力弱不扶顛，危機空履虎，击惡豈如鹯，成師凿門去，败績裹尸旋，收魂不入斗，抱景問穹玄，开顏何所說，空憶平生前，閉門窮巷里，靜扫詠歸田。","sortOrder":46},
  {"id":"s_work_nvlt_56_47","chapterId":"ch_work_nvlt_56","text":"又六甲詩曰：甲拆开眾果，萬物具敷榮，乙飛上危幕，雀乳出空城，丁翼陳詩罢，公綏作賦成，戊巢花已秀，滿塘草自生，已乃忘懷客，榮樂尚开情，庚庚聞鳥啭，肅肅望凫征，辛酸多悯测，寂寞少逢迎，壬蒸懷太古，覆妙佇無名，癸巳空施位，詎以召幽貞。","sortOrder":47},
  {"id":"s_work_nvlt_56_48","chapterId":"ch_work_nvlt_56","text":"又十二屬詩曰：鼠跡生尘案，牛羊暮下來，虎嘯坐空穀，兔月向窗开，龍隰遠青翠，蛇柳近徘徊，馬蘭方遠摘，羊負始春栽，猴栗羞芳果，雞砧引清杯，狗其懷物外，猪蠡窅悠哉。","sortOrder":48},
  {"id":"s_work_nvlt_56_49","chapterId":"ch_work_nvlt_56","text":"又六府詩曰：水廣南山暗，杖策出蓬門，火炬村前發，林煙树下昏，金花散黃蕊，蕙草雜芳荪，木蘭露漸落，山芝風屢翻，土高行已冒，抱瓮憶中園，穀城定若近，當終黃石言。","sortOrder":49},
  {"id":"s_work_nvlt_56_50","chapterId":"ch_work_nvlt_56","text":"陳孔魚和六府詩曰：金門朱軌躅，吾子盛簪裾，木舌無時用，蓱流复在餘，水乡訪松石，蘭泽侣樵漁，火洲方可至，地肺即為居，土牛自知止，貞心達毀譽，穀稼有時隙，乘植望白榆。","sortOrder":50},
  {"id":"s_work_nvlt_56_51","chapterId":"ch_work_nvlt_56","text":"古兩頭纖纖詩曰：兩頭纖纖月初生，半白半黑眼中精，腷々膊々雞初鳴，磊磊落落向曙星。","sortOrder":51},
  {"id":"s_work_nvlt_56_52","chapterId":"ch_work_nvlt_56","text":"齊王融代兩頭纖纖詩曰：兩頭纖纖綺上文，半白半黑燕翔群，腷々膊々鳥迷曛，磊磊落落玉石分。","sortOrder":52},
  {"id":"s_work_nvlt_56_53","chapterId":"ch_work_nvlt_56","text":"藁砧詩曰：藁砧今何在，山上复有山，何當大刀頭，破鏡飛上天。","sortOrder":53},
  {"id":"s_work_nvlt_56_54","chapterId":"ch_work_nvlt_56","text":"齊王融代藁砧詩曰：花蒂今何在，不是林下生，何當垂兩髻，团扇雲間明。","sortOrder":54},
  {"id":"s_work_nvlt_56_55","chapterId":"ch_work_nvlt_56","text":"又曰：鏡台今何在，寸身正相隨，何當碎聯玉，雲上璧已虧。","sortOrder":55},
  {"id":"s_work_nvlt_56_56","chapterId":"ch_work_nvlt_56","text":"古五雜組詩曰：五雜組，岡頭草，往复還，車馬道，不獲已，人將老。","sortOrder":56},
  {"id":"s_work_nvlt_56_57","chapterId":"ch_work_nvlt_56","text":"齊王融代五雜組詩曰：五雜組，慶雲發，往复還，經天月，不獲已，生胡越。","sortOrder":57},
  {"id":"s_work_nvlt_56_58","chapterId":"ch_work_nvlt_56","text":"梁范雲擬古五雜組詩曰：五雜組，會涂山，往复還，兩崤關，不得已，孀與鳏。","sortOrder":58},
  {"id":"s_work_nvlt_56_59","chapterId":"ch_work_nvlt_56","text":"宋王微四氣詩曰：蘅若首春華，梧楸當夏翳，鳴笙起秋風，置酒飛冬雪，齊王融四色詩曰：赤如城霞起，青如松霧澈，黑如幽都雲，白如瑤池雪。","sortOrder":59},
  {"id":"s_work_nvlt_56_60","chapterId":"ch_work_nvlt_56","text":"梁范雲四色詩曰：折柳青門外，握蘭翠疏中，绿蘋騁春日，碧渚澹時風。","sortOrder":60},
  {"id":"s_work_nvlt_56_61","chapterId":"ch_work_nvlt_56","text":"又曰：差池朱燕去，繽翻赤雁歸，瀺灂丹魚聚，聯翩血鳥飛。","sortOrder":61},
  {"id":"s_work_nvlt_56_62","chapterId":"ch_work_nvlt_56","text":"又曰：素鱗颺北渚，白水杜南宛，獻環润玉塞，歸珠照琼轅。","sortOrder":62},
  {"id":"s_work_nvlt_56_63","chapterId":"ch_work_nvlt_56","text":"又曰：乌林葉將霣，墨池水就乾，玄豹藏暮雨，黑豹凌夜寒。","sortOrder":63},
  {"id":"s_work_nvlt_56_64","chapterId":"ch_work_nvlt_56","text":"又擬古四色詩曰：丹如桓公廟，青如夕郎門，黑如南巖〈石肅〉，白如來山猿。","sortOrder":64},
  {"id":"s_work_nvlt_56_65","chapterId":"ch_work_nvlt_56","text":"宋鮑昭謎字詩曰：二形一體，四支八頭，四八一八，飛泉仰流，［井。］頭如刀，尾如鉤，中央橫廣，四角六抽，右面負兩刃，左邊双屬牛，［龟。］乾之一九，從立無偶，巛之二六，宛然双宿，［土。］","sortOrder":65},
  {"id":"s_work_nvlt_56_66","chapterId":"ch_work_nvlt_56","text":"宋謝莊自尋陽至都集道里名為詩曰：山經函旋覽，水牒倦敷尋，稽榭誠淹流，煙台信遐臨，翔州凝寒氣，秋浦結清陰，眇眇高湖曠，遙遙南陵深，青溪如委黛，黃沙似舒金，觀道雷池侧，訪德茅堂陰，魯顯闕微跡，秦良滅芳音，訊遠博望崖，采賦梁山岑，崇馆非陳宇，茂苑豈舊林。","sortOrder":66},
  {"id":"s_work_nvlt_56_67","chapterId":"ch_work_nvlt_56","text":"宋鮑昭數名詩曰：一身仕關西，家族滿山東，二年從車駕，斋祭甘泉宮，三朝國慶畢，休沐還舊邦，四牡曜長路，輕蓋若飛鸿，五侯相餞送，高會集新丰，六樂陳廣坐，組帳扬春風，七盤起長袖，庭下列歌鍾，八珍盈彫俎，綺肴紛错重，九族鹹瞻遲，賓友仰徽容，十載學無就，善官一朝通。","sortOrder":67},
  {"id":"s_work_nvlt_56_68","chapterId":"ch_work_nvlt_56","text":"齊虞羲數名詩曰：一去濠水陽，連翩遠為客，二毛飒已垂，家貧無所擇，三径日荒疏，徭人心不怿，四豪不降意，何事黃金百，五日來歸者，朱輪竟長陌，六郡輕薄兒，追隨窮日夕，七發動音容，賓從紛弈弈，八表服英嚴，光光滿墳籍，九流意何以，守玄遂成白，十載職不移，來歸落松柏。","sortOrder":68},
  {"id":"s_work_nvlt_56_69","chapterId":"ch_work_nvlt_56","text":"梁范雲數名詩曰：一鼓有餘氣，趫勇正紛紜，二廣無遺略，雄虎自為群，三河尚扰攘，循橹起橨榅，四巡駐青跸，瘞玉曠亭雲，五十又舒旆，旗幟日繽紛，六郡良家子，慕義輕從軍，七獲美前載，克俊嘉昔聞，八音佇繁律，將以安司勋，九命既斯复，金壁固宜分，十難康有道，延首望卿雲。","sortOrder":69},
  {"id":"s_work_nvlt_56_70","chapterId":"ch_work_nvlt_56","text":"齊王融奉和竟陵王郡縣名詩曰：追芳承荔浦，揖道訊虛丘，升裾臨廣牧，從望盡平洲，曾山陵翠坂，方渠緬清流，陽台翻早茂，陰馆懷名秋，歲晏東光弭，景仄西華收，端溪慚昔彦，测水謝前脩，往食曲阜盛，今屬平台遊，燕棠缺初雅，鄭袞息遺謳，久傾信都美，乃結茂陵儔，河間誠可詠，南海果難遊。","sortOrder":70},
  {"id":"s_work_nvlt_56_71","chapterId":"ch_work_nvlt_56","text":"梁范雲奉和齊竟陵王郡縣名詩曰：撫戈金城外，解珮玉門中，白馬騰遠雪，蒼松壮寒風，臨涇方辯渭，安夷始和戎，取禾廣田北，驅獸飛狐東，新城多雉堞，故市絕商工，海西舟楫斷，雲南煙霧通，罄節畴盛德，宣力照武功，還飲漁陽水，歸轉杜陵蓬。","sortOrder":71},
  {"id":"s_work_nvlt_56_72","chapterId":"ch_work_nvlt_56","text":"梁沈約奉和竟陵王郡縣名詩曰：西都富軒冕，南宮溢才彦，高闕連朱雉，方渠漸遊殿，廣川肆河濟，長岑繞崤汧，曲梁濟危渚，平皋騁悠眄，青淵皎澄澈，曾山鬱葱蒨，陽泉濯春藻，陰丘聚寒霰，西華不可留，東光促奔箭，望都遊子懷，臨戎征馬倦，既豫平台集，复齒南皮宴，一窥長安城，羞言杜陵掾。","sortOrder":72},
  {"id":"s_work_nvlt_56_73","chapterId":"ch_work_nvlt_56","text":"梁元帝縣名詩曰：長陵新市北，鄭衛好容儀，先過上蘭苑，還牵高柳枝，薄妆宜入鏡，舒花堪照池，蒲洲涵水色，椒壁雜風吹，此時方夜飲，平台傳羽卮。","sortOrder":73},
  {"id":"s_work_nvlt_56_74","chapterId":"ch_work_nvlt_56","text":"梁范雲州名詩曰：司春命初铎，青耦肆中樊，逸豫誠何事，稻粱复宜敦，徐步遵廣隰，冀以寫忧源，楊柳垂場圃，荆棘生庭門，交情久所見，益友能孰存。","sortOrder":74},
  {"id":"s_work_nvlt_56_75","chapterId":"ch_work_nvlt_56","text":"梁簡文帝卦名詩曰：櫛比園花滿，径复水流新，離禽時入袖，旅俗乍依蘋，丰壶要上客，鵠鼎命嘉賓，車由泰夏闼，馬散鹹陽尘，莲舟雖未濟，分密已同人。","sortOrder":75},
  {"id":"s_work_nvlt_56_76","chapterId":"ch_work_nvlt_56","text":"梁簡文帝藥名詩曰：朝風動春草，落日照橫塘，重台荡子妾，黃昏獨自傷，燭映合歡被，帷飄蘇合香，石墨聊書賦，鉛華试作妆，徒令惜萱草，蔓延滿空房。","sortOrder":76},
  {"id":"s_work_nvlt_56_77","chapterId":"ch_work_nvlt_56","text":"梁元帝藥名詩曰：戍客恒山下，常思衣錦歸，况看春草歇，還見雁南飛，〈虫葛〉燭凝花影，重台閉綺扉，風吹竹葉袖，網缀流黃機，詎信金城里，繁露晓霑衣。","sortOrder":77},
  {"id":"s_work_nvlt_56_78","chapterId":"ch_work_nvlt_56","text":"梁庾肩吾奉和藥名詩曰：英王牧荆楚，聽訟出池台，督郵稱蝗去，亭長說乌來，行塘朱鷺响，當道赤帷开，馬鞭聊寫賦，竹葉暫傾杯。","sortOrder":78},
  {"id":"s_work_nvlt_56_79","chapterId":"ch_work_nvlt_56","text":"梁沈約奉和齊竟陵王藥名詩曰：丹草秀朱翘，重台架危{巳山}，木蘭露易飲，射幹枝可結，陽隰采新夷，寒山望積雪，玉泉亟周流，雲華乍明滅，合歡葉暮卷，爵林聲夜切，垂景迫連桑，思仙慕雲埒，荆實部丹瓶，龍刍汗奔血，照握乃夜光，盈車非玉屑，細柳空葳蕤，水萍終萎絕，黃符若可挹，長生永昭晢。","sortOrder":79},
  {"id":"s_work_nvlt_56_80","chapterId":"ch_work_nvlt_56","text":"梁元帝姓名詩曰：征人習水戰，辛苦配戈船，夜城隨偃月，朝軍逐避年，龍吟澈水度，虹光入夜圓，涛來如陣起，星上似烽燃，經時事南越，還复讨朝鮮。","sortOrder":80},
  {"id":"s_work_nvlt_56_81","chapterId":"ch_work_nvlt_56","text":"梁沈約和陆慧晓百姓名詩曰：建都望淮海，树闕表衡稽，井幹風雲出，柏梁星漢齊，皇王臨萬宇，惠化覃黔黎，吉士服仁義，宿昔秉華圭，庸賢起幽穀，钦言非象犀，端委康國步，偃息召邦携，舉政方分策，易紀粲金泥，伊餘沐嘉幸，由是別園畦，曾微涓露答，光景遂雲西，方隨煉丹子，薄暮矯行迷。","sortOrder":81},
  {"id":"s_work_nvlt_56_82","chapterId":"ch_work_nvlt_56","text":"梁元帝相名詩曰：仙人賣玉杖，乘鹿去山林，浮杯度池曲，摩鏡往河陰，井內書銅板，竈里化黃金，妻搖五明扇，妾弄一絃琴，暫遊忽千里，中天那可尋。","sortOrder":82},
  {"id":"s_work_nvlt_56_83","chapterId":"ch_work_nvlt_56","text":"梁元帝鳥名詩曰：方舟去鳷鵲，鵠引欲相要，晨凫移去舸，飛燕動歸桡，雞人怜夜刻，鳳女念吹箫，雀釵照輕幌，翠的繞纖腰，复聞朱鷺曲，鉦管雜回潮。","sortOrder":83},
  {"id":"s_work_nvlt_56_84","chapterId":"ch_work_nvlt_56","text":"梁元帝獸名詩曰：豹韜求秘術，虎略選良臣，水涉黃牛浦，山過白馬津，推鋒上狐塞，畫像入麒麟，果下新花落，桃枝芳树春，王孫及公子，熊席复橫陳。","sortOrder":84},
  {"id":"s_work_nvlt_56_85","chapterId":"ch_work_nvlt_56","text":"梁元帝歌曲名詩曰：啼乌怨別鶴，曙鳥憶離家，石闕題書字，金鐙飄落花，東方晓星度，西山晚日斜，縠衫回廣袖，团扇掩輕紗，暫借青驄馬，來送黃牛車。","sortOrder":85},
  {"id":"s_work_nvlt_56_86","chapterId":"ch_work_nvlt_56","text":"梁元帝龟兆名詩曰：土膏春氣生，倡女协春情，魚遊連北水，鵠作遼東鳴，折梅還插鬢，荡柱更移聲，銀燭含朱火，金爐對寶笙，百枝凝夕焰，却月隱高城。","sortOrder":86},
  {"id":"s_work_nvlt_56_87","chapterId":"ch_work_nvlt_56","text":"梁元帝斜{宀兒}名詩曰：金推五百里，日晚唱歸來，車轉承光殿，步上通天台，釵臨曲池影，扇拂玉堂梅，先取中庭入，罢逐步廊回，下關那早閉，人迎已复开。","sortOrder":87},
  {"id":"s_work_nvlt_56_88","chapterId":"ch_work_nvlt_56","text":"梁元帝將軍名詩曰：虎旅皆成陣，龍騎盡能〈足甫〉，鳴鞭俱破虜，决勝往長榆，細柳浮輕暗，大树繞栖乌，樓船寫退鹢，樯鳥狎飛凫，度河還自許，偏與功名俱。","sortOrder":88},
  {"id":"s_work_nvlt_56_89","chapterId":"ch_work_nvlt_56","text":"梁元帝宮殿名詩曰：杏［原作杯，據冯校本改。］間花欲燃，竹径露初圓，斗雞東道上，走馬北場邊，合歡依暝巷，蒲萄向日鮮，旗亭觅張放，香車迎董賢，定隔天淵水，相思夜不眠。","sortOrder":89},
  {"id":"s_work_nvlt_56_90","chapterId":"ch_work_nvlt_56","text":"梁元帝屋名詩曰：梁園氣色和，斗酒共相過，玉柱調新曲，畫扇掩餘歌，深潭影菱菜，絕壁掛輕萝，木莲恨花晚，薔薇嫌刺多，含情戲芳節，徐步待金波。","sortOrder":90},
  {"id":"s_work_nvlt_56_91","chapterId":"ch_work_nvlt_56","text":"梁元帝車名詩曰：長墟帶江轉，連甍映日分，佳人坐椒屋，接膝對蘭薰，繞砌萦流水，邊梁圖畫雲，錦色懸殊眾，衣香遙出群，日暮輕帷下，黃金妾赠君。","sortOrder":91},
  {"id":"s_work_nvlt_56_92","chapterId":"ch_work_nvlt_56","text":"梁元帝船名詩曰：天暝浮雲飛，三翼自相追，池模白鵠舞，簷知青雀歸，華淵通轉巉，伏槛跨相磯，松涧流星影，桂窗斜月暉，思君此無極，高樓淚染衣。","sortOrder":92},
  {"id":"s_work_nvlt_56_93","chapterId":"ch_work_nvlt_56","text":"梁元帝树名詩曰：趙李競追隨，輕杉露弱枝，杏梁始東照，柘火未西馳，香因玉钏動，佩逐金衣移，柳葉生眉上，珠璫搖鬢垂，逢君桂枝馬，車下觅新知。","sortOrder":93},
  {"id":"s_work_nvlt_56_94","chapterId":"ch_work_nvlt_56","text":"梁元帝草名詩曰：胡王迎娉主，涂經蓟北遊，金錢買含笑，銀棋影梳頭，初控遊龍馬，仍移卷柏舟，中江離思切，蓬鬢不堪秋，况度蒲昌海，落月似懸鉤。","sortOrder":94},
  {"id":"s_work_nvlt_56_95","chapterId":"ch_work_nvlt_56","text":"陳沈炯八音詩曰：金屋貯阿娇，樓閣起迢迢，石頭足年少，大道跨河桥，絲桐無缓節，羅綺自飄飄，竹煙生薄晚，花色亂春朝，匏瓜詎無匹，神女嫁蘇韶，土地多妍冶，乡里足尘嚣，革年未相識，聲論動風飆，木桃堪底用，寄以答琼瑤。","sortOrder":95},
  {"id":"s_work_nvlt_56_96","chapterId":"ch_work_nvlt_56","text":"又和蔡黃門口字詠絕句曰：嚣嚣宮閣路，靈靈穀口闾，誰知名器品，語哩各崎嶇。","sortOrder":96},
  {"id":"s_work_nvlt_56_98","chapterId":"ch_work_nvlt_56","text":"《毛詩序》曰：詩有六義，其二曰賦。","sortOrder":98},
  {"id":"s_work_nvlt_56_99","chapterId":"ch_work_nvlt_56","text":"《釋名》曰：賦，敷也，敷布其義，謂之賦也。","sortOrder":99},
  {"id":"s_work_nvlt_56_100","chapterId":"ch_work_nvlt_56","text":"《漢書》曰：不歌而誦謂之賦，登高能賦，可以為大夫，言感物造端，材智深美，可以與圖政事，故可以為列大夫也，春秋之後，周道浸坏，聘問歌詠，不行於列國，而賢人失志之賦作矣，孫卿及楚臣屈原，離讒忧國，皆作賦以風諭，成［《太平御覽》五百八十七作鹹。］有則［御覽作惻。］隱古訓之義，其後宋玉唐勒，漢興，枚乘司馬相如，下及楊子雲，競為侈麗閎廣之語，設其諷諭之義，是以楊子稱之曰：詩人之賦麗以則，辭人之賦麗以淫，如孔氏之門用賦也，則贾誼登堂，相如入室矣。","sortOrder":100},
  {"id":"s_work_nvlt_56_101","chapterId":"ch_work_nvlt_56","text":"又曰：上令王襃與張子侨等併待詔，數從遊獵，所幸宮馆，辄為歌頌，第其高下，以差賜帛，議者多以為淫靡不急，上曰：不有博弈者乎，為之猶賢乎已，辭大者與古詩同義，小者辨麗可嘉，譬如女工有綺縠，音樂有鄭衛，今世俗猶皆以此娱悅耳目，辭賦比娱耳悅目，有仁義風諭鳥獸草木多聞之觀，賢於倡優博弈遠矣。","sortOrder":101},
  {"id":"s_work_nvlt_56_102","chapterId":"ch_work_nvlt_56","text":"又曰：枚皋上書北闕，自陳枚乘之子，上得大喜，召入見，待詔，皋因賦殿中，詔使賦平樂馆，善之，拜為郎，皋不通經術，談笑類徘倡，為賦頌好慢戲，以故得渫渎貴幸，比東方朔郭舍人等，武帝春秋三十九，乃得皇太子，群臣喜，故皋與東方朔作皇太子生賦，皋為文疾，受詔辄成，司馬相如善為文而遲，故所作少。","sortOrder":102},
  {"id":"s_work_nvlt_56_103","chapterId":"ch_work_nvlt_56","text":"《漢書》曰：成帝趙昭儀，方大幸，每上往甘泉宮，常從在屬車間豹尾中，故楊雄盛言車騎之眾，參麗之駕，非所以感動天地，逆釐三辰。又言屏玉女，却宓妃，以懲齊戒之事，賦成奏之，天子異焉，先是時，蜀有司馬相如，作賦甚弘麗溫雅，雄心壮之，每作賦，常擬以為式。","sortOrder":103},
  {"id":"s_work_nvlt_56_104","chapterId":"ch_work_nvlt_56","text":"《東觀漢記》曰：班固，字孟堅，九歲能作賦頌，固數入讀書禁中，每行巡狩，辄獻賦頌。","sortOrder":104},
  {"id":"s_work_nvlt_56_105","chapterId":"ch_work_nvlt_56","text":"《桓子新論》曰：餘少時，見楊子雲麗文高論，不量年少，猥欲逮及，常作小賦，用精思大剧，而立感動發病，子雲亦言成帝上甘泉，詔使作賦，為之卒暴，倦臥，夢其五藏出地，及覺大少氣，病一歲，餘素好文，見子雲工為賦，欲從之學，子雲曰：能讀千賦，則善為之矣。","sortOrder":105},
  {"id":"s_work_nvlt_56_106","chapterId":"ch_work_nvlt_56","text":"《祢衡別傳》曰：黃射大會賓客，人有獻鸚鵡者，射舉卮酒於衡曰：原先生賦之，以娱嘉賓，衡攬筆而作，文不加點，辭彩甚麗。","sortOrder":106},
  {"id":"s_work_nvlt_56_107","chapterId":"ch_work_nvlt_56","text":"《魏略》曰：十蘭獻賦，贊述太子德美，太子報曰：作者不虛其辭，受者必當其實，蘭此者，豈吾實哉，昔吾丘寿王陳寶何武等，徒以歌頌，猶金帛之賜，蘭事雖不谅，義足嘉也，今賜牛一頭。","sortOrder":107},
  {"id":"s_work_nvlt_56_108","chapterId":"ch_work_nvlt_56","text":"又曰：邯鄲淳作投壶賦千餘言，奏之，文帝以為工，賜帛十疋。","sortOrder":108},
  {"id":"s_work_nvlt_56_109","chapterId":"ch_work_nvlt_56","text":"《魏志》曰：陳思王曹植，字子建，善屬文，太祖嘗视其文，謂植曰：汝倩人耳，植曰：言出為論，下筆成章，原當面试，奈何倩人，時鄴，［原訛業，據冯本改。］都銅爵台新成，太祖悉將諸子登台，使各為賦，植援筆立成，太祖甚異之。","sortOrder":109},
  {"id":"s_work_nvlt_56_110","chapterId":"ch_work_nvlt_56","text":"王隱《晉書》曰：張華，字茂先，阮籍見華鹪鹩賦，以為王佐之才，中書郎成公綏，亦推華文義勝己。","sortOrder":110},
  {"id":"s_work_nvlt_56_111","chapterId":"ch_work_nvlt_56","text":"《文士傳》曰：何楨，字元幹，青龍元年，天子特詔曰：楊州別駕何楨，有文章才識，使作許都賦成，封上，不得令人見，楨遂造賦表上。","sortOrder":111},
  {"id":"s_work_nvlt_56_112","chapterId":"ch_work_nvlt_56","text":"又曰：潘尼曾與同僚飲，主人有琉璃碗，客使賦之，尼於坐立成。","sortOrder":112},
  {"id":"s_work_nvlt_56_113","chapterId":"ch_work_nvlt_56","text":"《世說》曰：孫興公作天台賦成，以示范榮期，雲，卿试掷置地，要作金石聲，范曰：恐子之金石，非宮商中聲，然每至佳句，皆辄雲，應是我辈語。","sortOrder":113},
  {"id":"s_work_nvlt_56_114","chapterId":"ch_work_nvlt_56","text":"【賦】晉陆機文賦曰：餘每觀才士之作，竊有以得其用心，夫其放言遣辭，良多变矣，妍蚩好惡，可得而言，每每自屬文，尤見其情，恒患意不稱物，文不逮意，非知之難，能之難也，故作文賦，以述先士之盛藻，因論作文之利害所由，他日逮可謂曲盡其妙，佇中區以玄覽，颐情志於典墳，遵四時以叹逝，瞻萬物而思紛，悲落葉於劲秋，喜柔條於芳春，心凛凛以懷霜，志眇眇而臨雲，詠世德之俊烈，誦先人之清芬，慨投篇而援筆，聊宣之乎斯文，其始也，皆收视反聽，耽思旁訊，精骛八極，心遊萬仞，其致也，情曈昽而弥鮮，物昭晢而互進，傾群言之瀝液，漱六藝之芳润，收百世之闕文，采千載之遺韻，謝朝華於已披，啟夕秀於未振，觀古今於須臾，撫四海於一瞬，然後選義按部，考辭就班，藏景者鹹叩，懷响者必彈，或因枝以振葉，或緣波而讨源，或妥帖而易施，或齟齬而不安，籠天地於形內，挫萬物於筆端，伊茲事之可樂，固聖賢之所钦，課虛無以责有，叩寂寞而求音，函綿邈於尺素，吐滂霈乎寸心，言恢之而弥廣，思按之而愈深，播芳蕤之馥馥，發清條之森森，粲風飛而飆竖，鬱雲起乎翰林，故夫夸目者尚奢，愜心者貴當，言窮者無隘，論達者唯曠，詩緣情而綺靡，賦體物而瀏亮，碑披文以相质，诔纏綿而凄怆，銘博約而溫润，箴頓挫而清壮，頌優遊以彬蔚，論精微而朗畅，奏平彻以閒雅，說煒晔而譎誑，雖區分之在茲，亦禁邪而製放，要辭達而理舉，故無取乎冗長，其為體也屢遷，其會意也尚巧，其遣言也貴妍，暨音聲之迭代，若五色之相宣，或仰偪於先條，或俯侵於後章，或辭害而理比，或言順而義妨，離之則双美，合之則兩傷，考殿最於锱銖，定去留於毫芒，立片言以居要，乃一篇之警策，雖眾辭之有條，必待茲而效績，或藻思綺合，清麗阡眠，烂若縟繡，凄若繁絃，必所擬之不殊，乃闇合乎曩篇，雖杼軸於予懷，怵他人之我先，石韞玉而山辉，水懷珠而川媚，彼榛楛之勿翦，亦蒙榮而集翠，若夫丰約之裁，俯仰之形，因宜適变，曲有微情，或言拙而諭巧，或理朴而辭輕，或袭故而弥新，或沿濁而更清，或覽之而必察，或妍之而後精，譬循舞者趁節以投袂，歌者應絃而遣聲，若夫應感之會，通塞之紀，來不可遏，去不可止，藏若影滅，行猶响起，思風發於焜臆，言泉流於唇齒，紛葳蕤以馺遝，唯豪素之所擬，文徽徽以溢目，音泠泠而盈耳，及其六情底滯，志往神留，兀若枯木，豁若涸流，覽營魂以探赜，頓精爽而自求，理翳翳而愈伏，思軋軋而若抽，是故或竭情而多悔，或率意而寡尤，伊茲文之為用，固眾理之所因，配霑润於雲雨，象变化乎鬼神，被金石而德廣，流管絃而日新。","sortOrder":114},
  {"id":"s_work_nvlt_56_115","chapterId":"ch_work_nvlt_56","text":"漢楊雄反骚曰：雄每讀屈原離骚，未嘗不流涕也，乃作書往往摭離骚文而反之，自岷山投諸江流，以弔屈原，有周氏之蝉嫣，或鼻祖於汾隅，靈宗初諜伯侨子，［漢書八十七楊雄傳作兮。］流於未［漢書作末。］之楊侯，惟夫軌之不辟，何純絜而離分，漢十世之扬翔，［漢書作陽朔。］招搖紀於周正，正皇天之清則，度後土之方貞，鳳皇翔於蓬渚，豈駕鹅之能捷，騁驊骝於曲叹，［漢書作畑。］驢連騫而齊足，衿荷芰之繡衣，被芙蓉之朱裳，芳酷烈而莫聞，不如襞而幽之離房，精琼靡與秋菊，將以延夫天年，臨汨羅而自陨，何怨日薄於西山，累既攀夫傅說，奚不信而遂行，徒恐鷤窸之將鳴，顧先百草為不榮。","sortOrder":115},
  {"id":"s_work_nvlt_56_116","chapterId":"ch_work_nvlt_56","text":"後漢班彪悼離骚曰：夫華植之有零茂，故陰陽之度也，聖哲之有窮達，亦命之故也，惟達人進止得時，行以遂伸，否則诎而坼蠖，體龍蛇以幽潛。","sortOrder":116},
  {"id":"s_work_nvlt_56_117","chapterId":"ch_work_nvlt_56","text":"晉挚虞愍骚曰：蓋明哲之處身，固度時以進退，泰則摅志於宇宙，否則澄神於幽昧，摛之莫究其外，函之罔識其內，順陰陽以潛躍，豈凝滯乎一概。","sortOrder":117},
  {"id":"s_work_nvlt_56_118","chapterId":"ch_work_nvlt_56","text":"魏陳王曹植九詠曰：芙蓉車兮掛衡，結萍蓋兮翠旌，四蒼虬兮翼轂，駕陵魚兮驂鯨，菌荐兮苉席，蕙帱兮苓床，抗南箕兮簸琼蕊，挹天河兮涤玉觴，靈既降兮泊靜默，登文階兮坐紫房，服春榮兮猗摩，雲裾繞兮容裔，冠北辰兮岌瓘，帶冕虹兮陵厲，蘭肴御兮玉俎陳，雅音奏兮文虞羅，感漢［本集漢下有廣字，此脱。］兮羨遊女，楊激楚兮詠湘娥，臨回風兮浮漢渚，目牵牛兮眺織女，交有际兮會有期，嗟痛吾兮來不時，來無見兮進無聞，泣下雨兮叹成雲，先後悔其靡及，冀後王之一寤，猶搦辔而繁策，馳覆車之危路，群乘舟而無楫，將何川而能度，何世俗之蒙昧，悼邦國之未靜，任椒蘭其望治，由倒裳而求領，尋湘漢之長流，采芳岸之靈芝，遇遊女於水裔，探菱華而結辭，野萧條以極望，曠千里以無人，民生期於必死，何自苦以終身，寧作清水之汙泥，不為濁路之飛尘。","sortOrder":118},
  {"id":"s_work_nvlt_56_119","chapterId":"ch_work_nvlt_56","text":"梁元帝擬秋氣搖落曰：秋風起兮寒雁歸，寒蝉鳴兮秋草腓，蓱清兮水澈，葉落兮林稀。","sortOrder":119},
  {"id":"s_work_nvlt_56_120","chapterId":"ch_work_nvlt_56","text":"梁張缵擬古有人兮曰：若有人兮傍巖石，新莆衣兮杜蘅席，表幽居兮翠微上，臨春風兮聊騁望，日已暮兮夕雲飛，懷君王兮未能歸。","sortOrder":120},
  {"id":"s_work_nvlt_56_121","chapterId":"ch_work_nvlt_56","text":"梁武帝賦體曰：草回風以照春，木承雲以含化，芳競飛於陽和，花爭开於日夜，樂萬類之得所，豈此心之雲舍，欣分竹其厲精，慚戎車之屢駕。","sortOrder":121},
  {"id":"s_work_nvlt_56_122","chapterId":"ch_work_nvlt_56","text":"梁任昉賦體曰：俶征侣兮舣行舟，奉君命兮不俟駕，屬軒軌之易循，值尧民之可化，慚孺雉之聲朝，惡細魚之在夜，奉玉檢之陆離，待金罍之雲舍。","sortOrder":122},
  {"id":"s_work_nvlt_56_123","chapterId":"ch_work_nvlt_56","text":"梁王僧孺賦體曰：雜沓兮翠旌，容與兮龍駕，新桐兮始華，乳雀兮初化，思治兮終朝，求人兮仄夜，竟大德之未德［德字疑衍。］詶，何飛光之徒舍。","sortOrder":123},
  {"id":"s_work_nvlt_56_124","chapterId":"ch_work_nvlt_56","text":"陆倕賦體曰：奉钦明之睿後，沐隆平之玄化，參振鷺之充庭，侍長徒之曾舍，冀無恨於終南，豫告成於芝駕，雖就列而陳力，終胡顏於長夜。","sortOrder":124},
  {"id":"s_work_nvlt_56_125","chapterId":"ch_work_nvlt_56","text":"梁柳憕賦體曰：飛辔竦兮不停陰，徂川逝兮無暫舍，白日出兮烁晚辰，春雷奋兮動蘭夜，竊匪服於储闈，叨鸿恩於良駕，何眇身之多幸，濯微纓於唐化。","sortOrder":125},
  {"id":"s_work_nvlt_56_126","chapterId":"ch_work_nvlt_56","text":"【論】魏文帝《典論》曰：夫文人相輕，自古而然，傅毅之於班固，伯仲之間爾，而固小之，夫人善於自見，而文非一體，鮮能備善，是以各以所長，相輕所短，今之文人，孔融陳琳王粲徐幹阮瑀應玚劉楨，斯七人者，於學無所遺，於辭無所假，鹹自以騁騄骥於千里，仰齊足而併馳，以此相服，亦良難矣，蓋君子審己以度人，故能免於斯累，乃作論文，王粲長於詞賦，徐幹時有逸氣，然粲匹也，陳琳阮瑀之章表書記，今之俊也，應玚和而不壮，劉楨壮而不密，孔融體氣高妙，有過人者，然不能持論，理不勝辭，至於雜以嘲戲，及其時有所善，楊班畴也，夫文本同而末異，蓋奏議宜雅，書論宜理，銘诔尚實，詩賦欲麗，文以氣為主，氣之清濁有體，不可力強而致，古之作者，寄身於翰墨，見意於篇籍，不假良史之辭，不讬飛馳之势，而聲名自傳於後，故西伯幽而演易，周旦顯而製禮，不以隱約而弗務，不以康樂而加思，夫然，則古人賤尺璧而重寸陰，懼乎時之過已，而人多不強力，貧賤則慑於飢寒，富貴則流於逸樂，遂營目前之務，而遺千載之功，日月逝於上，體貌衰於下，忽然與萬物遷化，斯志士所大痛也。","sortOrder":126},
  {"id":"s_work_nvlt_56_127","chapterId":"ch_work_nvlt_56","text":"晉挚虞《文章流別論》曰：文章者，所以宣上下之象，明人倫之叙，窮理盡性，以究萬物之宜者也，王泽流而詩作，成功臻而頌興，德勋立而銘著，嘉美終而诔集，祝史陳辭，官箴王闕，周禮太師，掌教六詩，曰風，曰賦，曰比，曰興，曰雅，曰頌，言一國之事，系一人之本，謂之風，言天下之事，形四方之風，謂之雅，頌者美盛德之形容，賦者敷陳之稱也，比者喻類之言也，興者有感之辭也，後世之為詩者多矣，其功德者謂之頌，其餘則總謂之詩，頌，詩之美者也，古者聖帝明王，功成治定而頌聲興，於是奏於宗廟，告於鬼神，故頌之所美者，聖王之德也，古之作詩者，發乎情，止乎禮義，情之發，因辭以形之，禮義之指，須事以明之，故有賦焉，所以假象盡辭，敷陳其志，古詩之賦，以情義為主，以事類為佐，今之賦，以事形為本，以義正為助，情義為主，則言省而文有例矣，事形為本，則言富而辭無常，文之煩省，辭之险易，蓋由於此，夫假象過大，則與類相遠，逸辭過壮，則與事相违，辯言過理，則與義相失，麗靡過美，則與情相悖，此四過者，所以背大體而害政教，是以司馬遷割相如之浮說，楊雄疾辭人之賦麗以淫，詩之流也，有三言四言五言六言七言九言，古詩率以四言為體，而時有一句兩句雜在四言之間，後世演之遂以為篇，古詩之三言者，振振鷺，鷺於飛之屬是也，五言者，誰謂雀無角，何以穿我屋之屬是也，六言者，我姑酌金罍之屬是也，七言者，交交黃鳥止於桑之屬是也，九言者，泂酌彼行潦挹彼註茲之屬是也，夫詩雖以情志為本，而以成聲為節，然則雅音之韻，四言為言，［全晉文七十七作正。］其餘雖備曲折之體，而非音之正也。","sortOrder":127},
  {"id":"s_work_nvlt_56_128","chapterId":"ch_work_nvlt_56","text":"《藝文類聚》　唐·欧陽詢","sortOrder":128},
  {"id":"s_work_nvlt_57_1","chapterId":"ch_work_nvlt_57","text":"卷五十七雜文部三","sortOrder":1},
  {"id":"s_work_nvlt_57_2","chapterId":"ch_work_nvlt_57","text":"○七連珠","sortOrder":2},
  {"id":"s_work_nvlt_57_4","chapterId":"ch_work_nvlt_57","text":"傅玄七謨序曰：昔枚乘作七發，而屬文之士，若傅毅劉廣世崔骃李尤桓麟崔琦劉梁之徒，承其流而作之者紛焉，七激七興七依七疑七說七蠲七舉之篇，通儒大才，馬季長，張平子，亦引其源而廣之，馬作七厲，張造七辯，非張氏至恩，［《太平御覽》五百九十作思。］比之七激，未為劣也，七釋佥曰妙焉，吾無間矣，若七激七依之卓轹一技，七辯之纏綿精巧，七啟之奔逸壮麗，七釋之情密閒理，亦近代之所希也，挚虞《文章流別論》曰：七發造於枚乘，借吳楚以為客主，先言出舆入輦，蹶痿之損，深宮洞房，寒暑之疾，靡漫美色，宴安之毒，厚味暖服，淫躍之害，宜聽世之君子，要言妙道，以疏神导體，蠲淹滯之累，既設此辭，以顯明去就之路，而後說以聲色逸遊之樂，其說不入，乃陳聖人辯士講論之娱，而霍然疾瘳，此固膏粱之常疾，以為匡勸，雖有甚泰之辭，而不没其諷諭之義也，其流遂廣，其義遂变，率有辭人淫麗之尤矣，崔骃既作七依，而假非有先生之言曰：呜呼楊雄有言，童子雕虫篆刻，俄而曰：壮夫不為也，孔子疾小言破道，斯文之族，豈不謂義不足而辯有餘者乎，賦者將以諷，吾恐其不免於勸也，傅子集古今七而論品之，署曰七林。","sortOrder":4},
  {"id":"s_work_nvlt_57_5","chapterId":"ch_work_nvlt_57","text":"漢枚乘七發曰：楚太子有疾，吳客往問之曰：伏聞太子玉體不安，亦少間乎，今夫貴人之子，必宮居而閨處，飲食則溫淳甘膬，衣則雜遝曼暖，雖有金石之堅，將猶銷鑠而挺解也，况其在筋骨之間乎，且夫出舆入輦，命曰蹶痿之幾，洞房清宮，命曰寒熱之媒，皓齒蛾眉，命曰伐性之斧，甘脆肥醲，命曰腐腸之藥，今太子膚色靡曼，四支委隨，筋骨挺解，越女侍前，齊姬奉後，往來遊宴，縱恣乎曲房隱間之中，此甘餐毒藥，戲猛獸之爪牙也，雖令扁鵲治內，巫鹹治外，尚何及哉，客曰：太子之病，可以要言妙道說而去也，不欲聞之乎，太子曰：仆原聞之。客曰：龍門之桐，高百尺而無枝，中鬱結之輪囷，根扶疏以分離，上有千仞之峰，下臨百丈之谿，湍流溯波。又淡淡之，其根半死半生，冬則烈風漂霰飛雪之所激也，夏則雷霆霹靂之所撼也，朝則鸝黃鳱鴠鳴焉，暮則羁雌迷鳥宿焉，獨鵠晨號乎其上，鵾雞哀鳴，翔乎其下，於是背秋涉冬，使班爾斫斬以為琴，野茧之絲以為絃，使師堂操張，伯牙為之歌，歌曰：麥秀{艹漸}兮雉朝飛，向虛壑兮背乔槐，依絕區兮臨回池，飛鳥聞之，翕翼而不能去，野獸聞之，垂耳而不能行，蚑蟜蝼蛾聞之，柱喙而不能前，此亦天下之至悲也，太子能強起而聽之乎，［雲雲。］客曰：犓牛之腴，菜以筍蒲，肥狗之和，冒以山膚，楚苗之食，安胡之飯，摶之不解，一啜而散，於是伊尹煎熬，易牙調和，熊蹯之臑，勺藥之醬，秋黃之蘇，白露之茹，蘭英之酒，酌以涤口，山梁之餐，豢豹之首，小飲大歠，如湯沃雪，此亦天下之至美也，太子能起嘗之乎，客曰：鍾岱之牡，齒至之車，前似飛鳥，後似駏驢，伯樂相其前後，王良造父為之御，秦缺樓秀［《文選》三十四作季。］為之右，於是使射千镒之重，爭千里之逐，此亦天下之至駿也，太子能強乘乎，客曰：既登景夷之台，南望荆山，北望汝海，左江右湖，其樂無有，乃下置酒於娱懷之宮，連廊四註，紛紜玄绿，輦道邪交，黃池紆曲，溷章白鷺，鴛鴦鶤鵠，鵷雏鵁鶄，翠鬛紫纓，女桑河柳，素葉紫茎，松柏豫樟，條上造天，梧桐栟榈，極望成林，乃發激楚之結風，扬鄭衛之皓齒，雜裾垂髾，目窈心與，榆流波，雜杜若，蒙清尘，被蘭泽，嬿服而御。此亦天下靡麗皓侈廣博之樂也，太子能起強遊乎，客曰：將為太子馴騏骥之馬，駕飛軨之舆，乘牡駿之乘，右夏服之劲箭，左乌號之雕弓，周馳兮蘭泽，弭節乎江潯，掩青蘋，遊清風，陶陽氣，荡春心，逐狡獸，集輕禽，於是極犬馬之才，困野獸之足，此校獵之至壮也，太子能強遊乎，客曰：榛林深泽，煙雲暗漠，兕獸併行，毅武孔猛，袒裼身博，收獲掌功，賞賜金帛，旨酒嘉肴，羞包脍炙，以御賓客，貞信之色，形以金石，高歌陳唱，萬歲無斁，能起強遊之乎，太子曰：仆甚原從，直恐為諸大夫累耳，客曰：將以八月之望，往觀涛乎廣陵之曲江，足以駭矣，恍兮惚兮，憀兮栗兮，虹洞兮仓天，極慮兮崖涘，汩乘流而下降，或不知其所止，當是之時，雖有淹病滯疾，將傴申起蹶，發瞽披聋而觀望也，况直眇小煩懣，酲醲病酒之徒哉，太子曰：善，然則涛何氣哉，客曰：聞於師曰：其始起也，淋淋焉若白鷺之下翔，其少進也，浩浩溰溰，如素車白馬帏蓋之張，其波涌而雲亂。扰扰焉如三軍之騰裝，其旁作而奔起也，飄飄焉如輕車之勒兵，太子能起觀乎，客曰：將為太子奏方術之士，有資略者，若莊周魏牟楊朱墨翟詹何之倫，使之論天下之精微，理萬物之是非，孔老覽觀，孟子持筹而筭之，萬不失一，此亦天下要言妙道也，太子豈欲聞之乎，於是太子據幾而起曰：涣乎一聽聖人辯士之言，霍然病已。","sortOrder":5},
  {"id":"s_work_nvlt_57_6","chapterId":"ch_work_nvlt_57","text":"後漢傅毅七激曰：徒華公子，讬病幽處，遊心於玄妙，清思乎黃老，於是玄通子聞而往屬曰：仆聞君子當世而光跡，因時以舒志，必將銘勒功勋，懸著隆高，今公子削跡藏體，當年陆沉，变度易趣，违拂雅心，挟六經之指，守偏塞之術，意亦有所蔽與，何圖身之谬也，仆將為公子論天下之至妙，列耳目之通好，原情心之性理，綜道德之弥奧，豈欲聞之乎，公子曰：仆雖不敏，固原聞之，玄通子曰：洪梧幽生，生於遐荒，陽春後榮，涉秋先彫，晨飆飛砾，孫禽相求，積雪涐々，中夏不流，於是乃使夫遊宦失势，窮擯之士，泳溺水，越炎火，窮林薄，歷隱深，三秋乃獲，斷之高岑，梓匠摹度，擬以斧斤，然後背洞壑，臨絕谿，聽迅波，望曾崖，大師奏操，榮期清歌，歌曰：陟景山兮采芳苓，哀不惨傷，樂不流聲，彈羽躍水，叩角奋榮，沉微玄穆，感物寤靈，此亦天下之妙音也，子能強起而聽之乎，玄通子曰：单極滋味，嘉旨之膳，刍豢常珍，庶差異饌，涔養之魚，脍其鯉鲂，分毫之割，纖如發芒，散如絕穀，積如委紅，殊芳異味，厥和不同，既食日晏，乃進夫雍州之梨，出於麗陰，下生芷隰，上讬桂林，甘露润其葉，醴泉漸其根，脆不抗齒，在口流液，握之摧沮，批之離坼，可以解煩，悁悅心意，子能起而食之乎，玄通子曰：骥騄之乘，龍驤超摅，騰虛鳥踴，莫能執御，於是乃使王良理辔，操以術教，踐路促節，機登飆驅，前不可先，後不可追，逾埃絕影，倏忽若飛，日不轉曜，窮遠旋歸，此蓋天下之駿馬，子能強起而乘之乎，玄通子曰：三時既逝，季冬暮歲，玄冥終統，庶卉零悴，王在靈囿，講戎簡旅，於是驷骥騄，乘輕軒，麾旄旗，鳴八鸞，陳眾車於廣隰，散列騎乎平原，屬罘網以弥野，連罻羅以營山，部曲周匝，風動雲旋，合团促陣，禽獸駭殫，仆不暇起，窮不及旋，击不待刃，骨解肉離，摧牙碎首，分其文皮，流血丹野，羽毛翳日，於是下蘭皋，臨流泉，觀通穀，望景山，酌旨酒，割芳鮮，此天下之至娱也，子能強起而觀之乎，玄通子曰：當馆侈飾，洞房華屋，楹桷雕藻，文以朱绿，曾台百仞，臨望博見，俯视雲霧，騁目窮觀，園藪平夷，沼池漫衍，禽獸群交，芳草華蔓，於是賓友所歡，近覽從容，詹公沉餌，蒲且飛紅，纶不虛出，矢不徒降，投鉤必獲，控絃加双，俯盡深潛，仰殫輕翼，日移怠倦，然後宴息，列觴酌醴，妖靡侍侧，被華文，曳綾縠，弭隨珠，佩琚玉，紅顏呈素，蛾眉不畫，唇不施朱，發不加泽，升龍舟，浮華池，紆帷翳而永望，鏡形影於玄流，偏滔滔以南北，似漢女之神遊，笑比目之双躍，樂偏禽之匹嬉，此亦天下之歡也，子能強起而與之遊乎。玄通子曰：漢之盛世，存乎永平，太和协畅，萬機穆清，於是群俊學士，雲集辟雍，含詠聖術，文质發曚，達犧農之妙旨，照虞夏之典墳，遵孔氏之憲則，投顏闵之高跡，推義窮類，靡不博觀，光润嘉美，世宗其言，公子瞿然而興曰：至乎，主得聖道，天基允臧，明哲用思，君子所常，自知沉溺，久蔽不悟，請誦斯語，仰子法度。","sortOrder":6},
  {"id":"s_work_nvlt_57_7","chapterId":"ch_work_nvlt_57","text":"後漢劉廣世七興曰：子康子有疾，王先生往焉，曰：駿壮之馬，慉不征路，其荷衡也，曜似驚禽，其即行也，翚若遊鷹，飆駭風逝，電發波騰，影不及形，尘不暇興。","sortOrder":7},
  {"id":"s_work_nvlt_57_8","chapterId":"ch_work_nvlt_57","text":"後漢崔骃七依曰：客曰：乃导玄山之梁，不周之稻，砻以絺绤，砥以柔韦，洞庭之鲋，灌水之鰩，滋以陽扑之薑，蔌以寿木之華，鹾以大夏之壃，酢以越裳之梅，反宇垂阿，洞門金鋪，丹柱雕楹，飛閣曾樓，於是置酒乎宴遊之堂，張樂乎長娱之台，酒酣樂中，美人進以承宴，調歡欣以解容，回顧百萬，一笑千金，振飛縠以長舞袖，裊細腰以務抑扬，當此之時，孔子傾於阿穀，柳下忽而更婚，老聃遺其虛靜，楊雄失其太玄，此天下之逸豫，宴樂之至盤也，公子豈能興乎，客曰：彭蠡之鳥，萬萬而群，荆山之獸，亿亿而屯，雲合風散，隱隱震震，乃命長狄使驅獸，夷羿作虞人，騰句喙以追飛，騁韓盧以逐奔，弓彈交错，把弧控絃，弯繁弱，鼓千鈞，死獸藉藉，聚如山，［句有脱文。］選取上鮮，獻之庖人。","sortOrder":8},
  {"id":"s_work_nvlt_57_9","chapterId":"ch_work_nvlt_57","text":"後漢李尤七款曰：奇宮閒馆，回庭洞門，井幹廣望，重閣相因，夏屋渠渠，嵯峨合連，前臨都街，後據流川，梁王青黎，盧橘是生，白華绿葉，扶疏各榮，與時代序，孰不墮零，黃景炫炫，眩林曜封，金衣素里，班白內充，副以芋柘，丰弘誕節，纖液玉津，旨於飲蜜。","sortOrder":9},
  {"id":"s_work_nvlt_57_10","chapterId":"ch_work_nvlt_57","text":"後漢桓麟七說曰：香萁為飯，雜以粳菰，散如細蚯，搏似凝膚，河黿之羹，齊以蘭梅，芳芬甘旨，未咽先滋，椅梧與梓，生乎曾崖，上仰貫天之山，下臨洞地之谿，飛霜厲其末，飆風激其崖，孤琴径其根，雜鳥集其枝，王良柏［全後漢文二十七作相。］其左，造父驂其右，揮沫扬鑣，倏忽長驅，輪不暇轉，足不及骤，騰虛逾浮，瞥若飆霧，追慌忽，逐無形，速疾影之超表，捷飛响之應聲，超絕壑，逾懸阜，馳猛禽，射劲鳥，騁不失蹤，滿不空發，彈輕翼於高冥，窮疾足於方外。","sortOrder":10},
  {"id":"s_work_nvlt_57_11","chapterId":"ch_work_nvlt_57","text":"後漢崔琦七蠲曰：寒門丘子有疾，玄野子謂之曰：藍沼清池，素波朱澜，金鉤芳餌，纖繳華竿，缗沉魚浮，荐以香蘭，幽室洞房，絕槛垂軒，紫閣青台，綺错相連，結實布葉，與波邪傾，從風離合，澹淡交併，紫蒂黃葩，翳水吐榮，紅顏溢坐，美目盈堂，姿喻春華，橾越秋霜，從容微眄，流曜吐芳，巧笑在侧，顧眄傾城，玄野子曰：爰有梧桐，產乎玄谿，傳根朽壤，讬陰生危，激水澡其下，孤鳥集其枝，罔双偶而特立，獨飄飖而单離，匠石摧肩，公输折首，目眩肌戰，製以為琴，子野調操，鍾期聽音，子能聽之乎。","sortOrder":11},
  {"id":"s_work_nvlt_57_12","chapterId":"ch_work_nvlt_57","text":"後漢劉梁七舉曰：丹楹縹壁，紫柱虹梁，桷榱朱绿，藻棁玄黃，鏤以金碧，雜以夜光，鸿台百層，幹雲參差，仰觀八極，遊目無涯，玉树青葱，鸞鶴併栖，隨珠明月，照曜其陂。","sortOrder":12},
  {"id":"s_work_nvlt_57_13","chapterId":"ch_work_nvlt_57","text":"後漢張衡七辯曰：無為先生，祖述列仙，背世絕俗，唯誦道篇，形虛年衰，志猶不遷，於是七辯謀焉，曰：無為先生，淹在幽隅，藏聲隱景，刬跡窮居，抑其不韙，盍往辯諸，乃階而就之，虛然子曰：樂國之都，設為閒馆，工输製匠，譎诡煥烂，重屋百層，連閣周漫，應門锵锵，華闕双建，彫虫肜绿，螭虹蜿蜒，於是彈比翼，落鸝黃，加双鶤，經鴛鴦，然後擢雲舫，觀中流，搴芙蓉，集芳洲，縱文身，摶潛鱗，探水玉，拔琼根，收明月之照曜，玩赤瑕之璘豳，此宮室之麗也，子盍歸而處之乎，雕華子曰：玄清白醴，蒲陶醲〈酉盧〉，嘉肴雜醢，三臡七菹，荔支黃甘，寒梨乾榛，沙餳石蜜，遠國储珍，於是乃有刍豢腯牲，麋麛豹胎，飛凫栖鷩，養之以時，審其齊和，適其辛酸，芳以薑椒，拂以桂蘭，會稽之菰，冀野之梁，珍羞雜遝，灼烁芳香，此滋味之麗也，子盍歸而食之，安存子曰：淮南清歌，燕餘材舞，列乎前堂，遞奏代叙，結鄭衛之遺風，扬流哇而脈激，楚鼙鼓吹，竽籁應律，金石合奏，妖冶邀會，觀者交目，衣解忘帶，於是樂中日晚，移即昏庭，美人妖服，变曲為清，改賦新詞，轉歌流聲，此音樂之麗也，子盍歸而聽諸，闕丘子曰：西施之徒，姿容脩嫮，弱顏回植，妍夸閒暇，形似削成，腰如束素，淑性窈窕，秀色美艳，鬢發玄髻，光可以鑒，靨辅巧笑，清眸流眄，皓齒朱唇，的皪粲練，於是紅華曼理，遺芳酷烈，侍夕先生，同茲宴，假明蘭燈，指圖觀列，蝉綿宜愧，夭紹紆折，此女色之麗也，子盍歸而從之，空桐子曰：交阯緅絺，筒中之纻，京城阿縞，譬之蝉羽，製為時服，以適寒暑，驷秀騏之駮駿，載軨獵之輶車，建采虹之長旃，系雌霓而為旗，逸駭飆於青丘，超廣漢而永逝，此舆服之麗也，子盍歸而乘之，依衛子曰：若夫赤松王乔，羨門安期，噓吸沆瀣，飲醴茹芝，駕應龍，戴行雲，桴弱水，越炎氛，覽八極，度天垠，上遊紫宮，下栖崑崙，此神仙之麗也，子盍行而求之，先生乃興而言曰：吁美哉，吾子之誨，穆如清風，啟乃嘉猷，寔慰我心，矯然仰首，邪睨玄圃，軒臂矯翼，將飛未舉，仿無子曰：在我聖皇，躬勞至思，參天兩地，匪怠厥司，率由舊章，遵彼前謀，正邪理谬，靡有所疑，旁窥八索，仰鏡三墳，講禮習樂，儀則彬彬，是以英人底材，不賞而勸，學而不厭，教而不倦，於是二八之儔，列乎帝庭，揆事施教，地平天成，然後建明堂而班辟雍，和邦國而悅遠人，化明如日，下應如神，漢雖舊邦，其政惟新，而先生乃翻然回面曰：君子一言，於是觀智，先民有言，談何容易，予雖蒙蔽，不敏指趣，敬授教命，敢不是務。","sortOrder":13},
  {"id":"s_work_nvlt_57_14","chapterId":"ch_work_nvlt_57","text":"魏陳王曹植七啟曰：玄微子隱於大荒之庭，飛遯離俗，澄神定靈，輕祿傲貴，與物無營，於是鏡機子聞而將往說焉，駕超野之驷，乘追風之舆，入乎泱漭之野，遂屆玄微子之所居，其居也，左激水，右高岑，背洞壑，對芳林，志飄飄焉，峣峣焉，似若狹六合，隘九州，若將飛而未逝，舉翼而中留，於是鏡機子順風而稱曰：予聞君子不遁世以遺名，智士不背時而滅勋，今子弃道藝之華，遺仁義之英，譬猶畫形於無象，造响於無聲，鏡機子曰：芳菰精稗，霜蓄露葵，玄熊素膚，肥豢脓肌，蝉翼之割，剖纖析微，累如叠縠，離若散雪，輕隨風飛，刃不轉切，山鵽斥鷃，珠翠之珍，搴芳莲之巢龟，鱠西海之飛鱗，臛江東之潛鼍，〈目巂〉漢南之鳴鶉，乃有春清縹酒，康狄所營，應化即变，感氣而成，於是盛以翠鐏，酌以雕觴，浮虮鼎沸，酷烈馨香，可以和神，可以娱腸，此肴饌之妙也，子能從我而食之乎，鏡機子曰：步光之劍，采藻繁縟，飾以文犀，彫以翠绿，缀以驪龍之珠，错以荆山之玉，陆斷犀象，未足稱俊，隨波截鸿，水不漸刃，佩則結绿懸黎，寶之妙微，符彩煥烂，流景扬暉，黼黻之服，羅縠之裳，金華之舄，動趾遺光，此容飾之妙也，子能從我而服之乎，鏡機子曰：駕雲龍之飛驷，飾玉露之繁纓，垂宛虹之長綏，抗招搖之華旌，於是曳文狐，掩狡兔，梢鷫鹴，拂振鷺，當軌見藉，值足遇踐，飛軒電逝，獸隨輪轉，騰山赴壑，風厲飆舉，形不抗手，骨不隱拳，野無毛類，林無羽群，積獸如陵，飛翮成雲，於是駭鍾鳴鼓，收旌弛旆，駿騄齊驤，扬鑾飛沬，俯倚金较，仰撫翠蓋，雍容暇預，娱志方外，此羽獵之妙也，子能隨我而觀之乎，鏡機子曰：彤軒紫柱，文榱華梁，綺井含葩，金墀玉箱，溫房則冬服絺绤，清室則中夏含霜，華閣緣雲，飛陛陵虛，俯视流星，仰觀八隅，升龍攀而不逮，眇天际而高居，素水盈沼，丛木成林，飛翮陵高，鱗甲隱深，乃使任子垂釣，魏氏發機，芳餌沉水，輕繳弋飛，落翳雲之翔鳥，援九淵之靈龟，然後采菱華，擢水蘋，弄珠蚌，戲鲛人，諷漢廣之所詠，觌遊女於水濱，燿神景於中沚，被輕縠之纖羅，遺芳烈而靖步，抗皓手而清歌，歌曰：望雲际兮有好仇，天路長兮往無由，佩蘭蕙兮為誰脩，此宮觀之妙也，子能從我而居之乎，鏡機子曰：既遊觀中原，逍遙閒宮，情放志荡，淫樂未終，亦將有才人妙妓，遺世超俗，扬北里之流聲，紹陽阿之妙曲，爾乃御文軒，臨彤庭，琴瑟交彈，左篪右笙，然後姣人，乃被文縠之華袿，振輕綺之飄飖，戴金搖之熠烁，扬翠羽之双翘，翻爾鸿翥，濈然凫没，縱輕軀以迅赴，影追形而不逮，為歡未泄，白日西頹，樂散变飾，微步中閨，玄眉弛兮鉛華落，收亂發兮拂蘭泽，紅顏既笑，睇盻流光，時與吾子，携手同行，踐飛除，即閒房，華燭烂，羅帱張，動朱唇，發清商，九秋之夕，為歡未央，此聲色之妙也，子能從我而遊之乎，鏡機子曰：餘聞君子樂奋節以顯義，列士甘危軀以成仁，重氣輕命，感分忘身，故田光伏劍於北燕，公叔畢命於西秦，辭未終而玄。微子曰：善，鏡機子曰：此乃遊俠之徒耳，若夫田文無忌之畴，乃上古之俊公子也，皆飛仁扬義，騰躍道藝，遊心無方，抗志雲际，凌轹諸侯，驅馳當世，揮袂則九野生風，慷慨則氣成虹蜺，吾子當此之時，豈能從我而友之乎，鏡機子曰：時有聖宰，翼帝霸世，同量乾坤，等明日月，玄化參辰，與靈合契，越隆平於殷周，踵羲皇而齊泰，顯朝惟清，皇道遐均，民望如草，我泽如春，是以俊乂來仕，觀國之光，故甘露紛而晨降，景星宵而舒光，觀遊龍於神淵，聆鳴鳳於高岡，然主上猶以沉恩之未廣，懼聲教之未厲，采英奇於仄陋，宣皇明於巖穴，此甯子商歌之秋，而呂望所以投纶而逝也，於是玄微子攘袂而興曰：伟哉言乎，令予廓然，身輕若飛，原反初服，從子而歸。","sortOrder":14},
  {"id":"s_work_nvlt_57_15","chapterId":"ch_work_nvlt_57","text":"魏徐幹七喻曰：有逸俗先生者，耦耕乎巖石之下，栖遲乎穹穀之岫，萬物不幹其志，王公不易其好，寂然不動，莫之能懼，賓曰：大宛之犧，三江之魚，雲鸧水鵠，禽蹯豹胎，黼帱施於宴室，華蓐布乎象床，懸明珠於長韜，燭宵夜而為陽，玄鬢擬於雲霧，艳色過乎芙蓉，扬蛾眉而微睇，雖毛施其不當。","sortOrder":15},
  {"id":"s_work_nvlt_57_16","chapterId":"ch_work_nvlt_57","text":"魏王粲七釋曰：潛虛丈人，违世遁俗，恬淡清玄，浑沌淳朴，薄禮愚學，無為無欲，均同死生，混齊榮辱，於是大夫聞而叹曰：蓋聞君子不以志易道，不以身後時，進德脩業，與世同理，今子深藏其身，高栖其志，外無所營，內無所事，邯鄲才女，三齊巧士，名唱秘舞，承閒併理，七盤陳於廣庭，畴人俨其齊俟，翩飄微霍，亂精荡神，巴渝代起，鞞铎响振，農功既登，玄陰戒寒，及致眾庶，大獵中原，植旌柎表，班授行曲，镮網連罝，弥山跨穀，絃不虛控，矢不徒往，僵禽連積，陨鳥若雨，麗才美色，希世特立，丰膚曼肌，弱骨纖形，鬒發玄鬢，脩項秀頸，紅顏照曜，晔若苕榮，戴明中之羽雀，雜華鑷之葳蕤，珥照夜之双璫，煥鯶爚以垂暉，聖人在位，時邁其德，先天弗违，稽若古則，叡哲文明，允恭玄塞，登俊乂於垄畝，舉賢才於仄微，置彼周行，列於邦畿，九德鹹事，百僚師師，於是四海之內，鹹变時雍，普天率土，比屋可封，是以栖林隱穀之夫，逸跡放言之士，鑒乎有道，貧賤是恥。","sortOrder":16},
  {"id":"s_work_nvlt_57_17","chapterId":"ch_work_nvlt_57","text":"魏劉邵七華曰：玄休先生，弃世遁名，藏身於虛廓，絕影於無形，榮時子聞而往焉，曰：仆聞至人之生世也，必承天地之時势，統萬物之紘綱，生有九鼎之秩，没有祀典之常，仆將為先生陳天下之遠圖，論品物之弘式，規人事之榮華，傳情志之所極，榮時子曰：追風之馬，出自遐裔，状若逸虬，莫能羁製，踐路躡節，迅驅機發，後不可及，前不可越，尋越逸响，追晷逐□，榮時子曰：三時既畢，玄冬效節，木落草弊，鳥竄獸穴，爾乃駕六虬，乘雕軒，載金鉦，鳴玉鑾，鼓與雷起，野火電延，聲與天屬，熛與霓連，榮時子曰：洞庭之鱄，出於江崏，紅腴青鱸，朱尾碧鱗，金光鏡野，旌旗曜天，雷辎翳路，風馬如雲，於是三辰增曜，大明重光，醴泉波流，芝圃扬芳，毛群率舞，羽族回翔，聆九韶之聲变，儀矩步之蹌蹌，感神人而懷異物，寧九有而綏八荒。","sortOrder":17},
  {"id":"s_work_nvlt_57_18","chapterId":"ch_work_nvlt_57","text":"晉張协七命曰：冲漠公子，含華隱曜，嘉遁龍盤，越世高蹈，絕景乎大荒之遐阻，答响乎幽山之窮奧，於是殉華大夫，聞而造焉，乃整雲辂，參飛黃，越奔沙，輾流霜，天清冷而無霞，野曠朗而無尘，臨重岫而攬辔，顧石室而回輪，於是登絕巘，溯長風，陳辯惑之辭，命公子於巖中，大夫曰：寒山之桐，出自大冥，含黃鐘以吐幹，據蒼岑而孤生，晞三春之溢露，溯九秋之鳴飆，零雪泻其根，霏霜封其條，木既繁而後绿，草未素而先凋，營匠斫其朴，伶倫均其聲，若乃龍火西頹，暄風初收，飛霜迎節，高風送秋，羁旅懷土之徒，流宕百罹之儔，撫促柱則酸鼻，揮危絃則涕流，大夫曰：應門八袭，璇台九重，表以百常之闕，圖以萬雉之墉，峣树迎風，秀出中天，翠觀青岑，雕閣霞連，長翼臨雲，飛陛陵山，望玉繩而結極，承倒景而开軒，重殿叠起，交綺對幌，幽堂晝密，明室夜朗，焦螟飛而生風，尺蠖動而成响，大夫曰：若乃白商素節，時既授衣，天凝地閉，風厲霜飛，柔條夕劲，密葉晨稀，將因氣以效殺，臨金郊而講師，內無疏蹊，外無漏跡，叩鉦數校，舉麾贊獲，大夫曰：范公之鱗，出自九溪，赪尾丹腮，紫翼青髯，爾乃命支離，飛霜鍔，紅肌綺散，素膚雪落，娄子之豪，不能廁其細，秋蝉之翼，不足擬其薄，大夫曰：楚之陽劍，區冶所營，耶溪之鋌，赤山之精，銷逾羊頭，鍱越鍛成，流綺星連，浮彩艳發，光如散電，质如濯雪，指鄭則三軍白首，麾晉則千里流血，形震薛燭，光駭風湖，或馳名傾秦，或夜飛去吳，大夫曰：乃有荆南乌程，豫北竹葉，浮虮星沸，飛華萍接，玄石嘗其味，儀氏進其法，傾罍一朝，可以流湎千日，单醪投川，可使三軍告捷，斯又神人之所歆羨，觀聽之所煒晔。","sortOrder":18},
  {"id":"s_work_nvlt_57_19","chapterId":"ch_work_nvlt_57","text":"晉陆機七徵曰：玄虛子耽性冲素，雍容玄泊，弃時俗而弗徇，甘魚釣於一壑，乃有通微大夫，怨皇居之失寶，傷鸿誓之後聞，榮玄黃於榛险，凭穴巖而放言，通微大夫曰：奇膳玉食，窮滋致丰，簡犧羽族，考生毛宗，俯出沉鲔，仰落歸鸿，剖柔胎於孕豹，宰潛肝乎豢龍，拾朝陽之遺卵，納丹穴之飛凰，神宰奇稌，嘉禾之穗，含滋發馨，素穎玉銳，灼若皓雪之頹玄雲，皎若明珠之積緇匮，素虮踴而瀺灂，滋芬溢而相徽，味雖浓而弗爽，氣既惠而复，［本集复下有奇字。］介景福於眉寿，裕溫克乎齊聖，子能饗之乎，通微大夫曰：丰屋華殿，奇構磊落，高宇雲覆，千楹林错，仰綏瑰木，俯積萩石，敷延袤之廣庑，矯陵霄之高閣，秀清暉乎雲表，騰藻荫之弈弈，珍觀清榭，嶽立連行，雲階飛陛，仰陟穹蒼，耸浮柱而虬立，施飛簷以龍翔，回房旋室，缀琳袭玉，圖畫神仙，延祐承福，懸闼高達，長廊回屬，於是登漸台，理俊音，鏡玄沚，望長林，逐狡獸，弋輕禽，覽壮藝以悅觀，聆和樂而怡心，子能居之乎，通微大夫曰：金石諧而齊响，埙篪协而和鳴，於是才人進羽籥，玄弁被藻袭，俯萦領以鸿歸，仰矯首而鶴立，激長歌於丹唇，發铿锵乎柔木，合清商以絕節，揮流徵而赴曲，奏南荆之高叹，詠易水之清角，爾乃睹蛾眉之群麗，羌既都而又閒，矯纖腰以逐節，頓皓足於鼓盤，舒妍暉以妖韶，若陵危之未安，通微大夫曰：蓋聞沬北有采唐之思，淇上有送子之勤，關雎以寤寐為慼，溱洧以謔浪為歡，若夫妖嫔艳女，蒐群擢俊，穆藻儀於令表，茂當年之柔嫚。罄妍規之約綽，體每变而增閒，秀紅蕤其愉愉，若餘穎之可餐，若夫靈晷潛，祖顏退，羽觴升，清琴厲，因清明以宣誠，流微睇而授愛，纖手揮而鳴佩铿，華衿被則芳尘萃，子其納之乎，通微大夫曰：涂有殊而一致，業有殊而名約，各因姿以效績，期寄响於天人也，孰與顯奇蹤於萬邦，撫六辔而高遊，瞰八宇以摅眄，濟清風乎諸侯，言成否泰，氣作溫涼，弭侵略於彊暴，綜墜紀乎危邦，子豈不原斯之雍容乎，通微大夫曰：明主應期，撫民以德，配仁風於黃唐，齊威靈乎宸極，彝倫幸序，庶績鹹乂，荡流風於雍俗，給天民乎齊泰，是以玄靈感而表應，嘉神繁而畢觌，舞唐庭之來儀，鳴岐陽之鸑鷟，膺天監之休命，荷神聽之介福，然聖主達持盈之寶術，寤經國之在賢，各畢榮於分局，期贊化於大鈞，吾子豈不欲縻好爵於天宇，顯列業乎帝臣欤，玄虛子作而曰：甚哉，鄙人之惑也，猶窮繩自逸於井幹，凭河盜本於黃川，钦至論，敷蔽衽，謹聞命於王孫，晉湛方生七歡曰：有巖栖先生者，學道養生，離親絕俗，漱清泉，荫茂木，慕赤松之清尘，乃餐霞而絕穀，朝隱大夫，尋條援葛，往而問之曰：營中都以起馆，指土圭以正宮，宅既平而土沃，寔商旅之所通，究精巧之妙思，盡土木之所窮，南軒高馆，北連脩堂，左亘東序，右列西厢，飛甍雲構，軒軒锵锵，連棟抗榱，若飛若翔，幽籠納响，素壁流光，乃有傾城之色，玉质鳳章，手習清弄，心達宮商，子能從我而玩之乎，大夫曰：歲季月除，大蠟始節，繁霜朝氛，凄風夕發，策龍驷以偕逝，問虞人於中林，審蹊径之所由，之此泽之多禽，前批猛獸，後拉黃羆，聲不得發，爪不暇施，此遊獵之壮觀，子能從我而觀之乎，大夫曰：青陽开運，和氣流人，天無纖翳，地無飛尘，五湖靜波，四渎凝津，命向方之嘉友，聊汎舟以遊春，此舟楫之駿遊，子能從我而乘之乎，大夫曰：有嶧山之孤桐，生千仞之峻峤，乘危巖以讬根，間丹霞而竦標，苦嚴霜之凄切，困寒風之萧條，若乃清秋遙夜，器朗絃彻，閒心理氣，臨流鏡月，伯牙揮爪以清弄，鍾期中曲而撫節，子能從我而聽之乎，大夫曰：良畴沃壤，傍山之阿，靈泽津其根，春露染其禾，上荫玄雲輕霭，下流石泉清波，含山泽之清润，結玉實於秋霜，簡嘉穗以精微，璀冰散而珠光，酿縹醪於九秋，蘊二日於三陽，米望麹而冰消，瓮未啟而流芳，此五穀之精液，子能從我而嘗之乎，大夫曰：生乎三季之世，隔乎大國之間，戎馬生於郊畿，英雄森以比肩，意氣冠宇宙，豪势扼丘山，強虜元師，懸首大白，勋勒王府，功刊金石，此不世之奇功，子能從我而立之乎，大夫曰：蓋聞至道以無主員應，橐籥以內虛無窮，陰陽以煙煴鹹化，五行之守分相攻，是以撫往運而長揖，因歸風而回軒，掛長纓於朱闕，反素褐於丘園，靡閒風於林下，鏡洋流之清澜，仰濁酒以箕踞，間絲竹而晤言。","sortOrder":19},
  {"id":"s_work_nvlt_57_20","chapterId":"ch_work_nvlt_57","text":"宋顏延之七繹曰：北嶽孤生，刬跡埋聲，名歇事盡，道畜山扃，東國進士，谬與遇焉，其居也，依隱嵁陰，結架清深，巖屋桥構，澄道相臨，寒榮隴首，繑飲江潯，客曰：周以巖廊，匝以采房，木寫雲氣，土秘群芳，既旋天而倒井。又斫員而鏤方，松上箭渚，藥苑香林，梁涧道以高濟，栈巖墱而上尋，客曰：若夫丹山之奧，金門而秘，地首岷銅，川上汶泗，裁石成音，調金為器，故列真玩其微鳴，辭人賦其清懿，若乃梓漆簡聲，麗容呈才，陳舞態，开吹台，獵悲風，溯秋埃，既而昵賓獻寿，中人奉膳，有悄者顏，弗怡高殿，视華鼓之繁桴，聽邊笳之嘶啭，飛朱鷺以首引，逮玄雲而終变，然後簪珥搖暉，莊服流湎，抗妍歌以跕鵕，扬輕袖而翳面，雜紛披於巾拂，遞間關乎槃扇。","sortOrder":20},
  {"id":"s_work_nvlt_57_21","chapterId":"ch_work_nvlt_57","text":"齊竟陵王賓僚七要曰：松既煙而接漢，竹緣嶺而負筠，哀過鸿於月晓，悲夜猿於霜旻，乃鶴駕之非遠，信羽車之可鄰，鸿池廣象，太液染華，势含五水，氣疏九河，既百尋而照底，亦千丈而分沙，故乘流以神王，或鼓地而目多，豈能從我，汎此安波。","sortOrder":21},
  {"id":"s_work_nvlt_57_22","chapterId":"ch_work_nvlt_57","text":"梁萧子范七誘曰：幽遁公子，不遊義路，不入禮門，人主焉得為臣，公侯難以為容，有暴势大夫，驅美泽之車，策千里之馬，乃至公子之所居，大夫曰：收苗山之鋌，采邪溪之銅，既雲時吉，亦曰天中，金英內曜，銀精外通，均如屈楊之舒彩，粲若芙蓉之始紅，七星布而成列，五色变而無窮，寶兼千萬，聲重二都，邁茲巨闕，超彼鹿盧，呈形薛燭，表质風湖，大夫曰：玉饌方丈，蕙肴果器，法罄吳章，妙窮伊挚，若乃豹胎之貴，鳳卵之珍，常山之果，醴水之鱗，大夫曰：訪幼女於蔡邕，選佳人於趙都，或拾翠於神渚，或采桑於城隅，見者忘鋤而留矚，行者下簷而踟蹰，女乃歌曰：井上李兮隨風摽，垂翠帷兮夜難晓，獨處廓兮心悄悄，懷素縷之双針，原因之於三鳥，大夫曰：若乃帝思啟土，命將朔方，守邊鄙而擁角節，集兵旅而馳牙璋，或埋輪於絕域，或縶馬於遐疆，功格宇宙，威振蠻荒，大夫曰：逸態之赤兔，駿足之驪駒，龍文重於漢廄，魚目貴於西都，若乃似鹿之體，如龍之姿，韁以紫縷，系以青絲，大夫曰：冬斬陽木，夏伐陰材，剞劂之功鹹至，鉤繩之妙併來，擬天文而特建，象地戶而高开，麗前脩之金屋，陋曩日之璜台，若乃緹錦遍室，丹青被土，白珠之帘，水精之柱，綺井鏤而重葩，華桶煥而相距，文石之井，珊瑚之树，紫複峻而連天，青綺高而幹霧，大夫曰：自五氣初運，二靈始分，蛇身之帝，牛首之君，焉足道哉，若乃聖皇之馭國，得附枝而居位，陋重華之聰明，蔑放勋之文思，通犀文甲之獻，相繼於天府，金湋銀鳥之錫，不絕於史書，當此之日，子能佩玉而侍乎，公子竦然曰：前靡靡之數說，皆非鄙性之所娱，如今之善誘，請就列於康衢。","sortOrder":22},
  {"id":"s_work_nvlt_57_23","chapterId":"ch_work_nvlt_57","text":"◇連珠","sortOrder":23},
  {"id":"s_work_nvlt_57_24","chapterId":"ch_work_nvlt_57","text":"傅玄叙連珠，所謂連珠者，興於漢章帝之世，班固贾逵傅毅三子，受詔作之，而蔡邕張華之徒又廣焉，其文體辭麗而言約，不指說事情，必假喻以達其旨，而賢者微悟，合於古詩勸興之義，欲使歷歷如貫珠，易睹而可悅，故謂之連珠也，班固喻美辭壮，文章弘麗，最得其體，蔡邕似論，言质而辭碎，然旨篤矣，贾逵儒而不艳，傅毅有文而不典。","sortOrder":24},
  {"id":"s_work_nvlt_57_25","chapterId":"ch_work_nvlt_57","text":"漢楊雄連珠曰：臣聞明君取士，貴拔眾之所遺，忠臣不荐，善废格而所排，是以巖穴無隱，而侧陋章顯也。","sortOrder":25},
  {"id":"s_work_nvlt_57_26","chapterId":"ch_work_nvlt_57","text":"漢班固擬連珠曰：臣聞公输愛其斧，故能妙其巧，明主貴其士，故能成其治。","sortOrder":26},
  {"id":"s_work_nvlt_57_27","chapterId":"ch_work_nvlt_57","text":"臣聞良匠度見材而成大厦，明主器其士而建功業。","sortOrder":27},
  {"id":"s_work_nvlt_57_28","chapterId":"ch_work_nvlt_57","text":"臣聞聽决价而資玉者，無楚和之名，因近習而取士者，無伯玉之功，故玙璠之為寶，非駔儈之術也，伊呂之佐，非左右之舊。","sortOrder":28},
  {"id":"s_work_nvlt_57_29","chapterId":"ch_work_nvlt_57","text":"臣聞鸞鳳養六翮以凌雲，帝王乘英雄以濟民，易曰：鸿漸於陆，其羽可以為儀。","sortOrder":29},
  {"id":"s_work_nvlt_57_30","chapterId":"ch_work_nvlt_57","text":"臣聞馬伏阜而不用，則駑與良而為群，士齊僚而不職，則賢與愚而不分。","sortOrder":30},
  {"id":"s_work_nvlt_57_31","chapterId":"ch_work_nvlt_57","text":"後漢潘勖擬連珠曰：臣聞媚上以布利者，臣之常情，主之所患，忘身以忧國者，臣之所難，主之所原，是以忠臣背利而脩所難，明主排患而獲所原。","sortOrder":31},
  {"id":"s_work_nvlt_57_32","chapterId":"ch_work_nvlt_57","text":"魏文帝連珠曰：蓋聞琴瑟高張則哀彈發，節士抗行則榮名至，是以申胥流音於南極，蘇武扬聲於朔裔，蓋聞四節異氣以成歲，君子殊道以成名，故微子奔走而顯，比幹剖心而榮。","sortOrder":32},
  {"id":"s_work_nvlt_57_33","chapterId":"ch_work_nvlt_57","text":"蓋聞駑蹇服御，良樂咨嗟，鉛刀剖截，區冶叹息，故少師幸而季梁懼，宰嚭任而伍員忧。","sortOrder":33},
  {"id":"s_work_nvlt_57_34","chapterId":"ch_work_nvlt_57","text":"魏王粲仿連珠曰：臣聞明主之舉也，不待近習，聖君用人，不拘毀譽，故呂尚一見而為師，陳平乌集而為辅。","sortOrder":34},
  {"id":"s_work_nvlt_57_35","chapterId":"ch_work_nvlt_57","text":"臣聞記功志過，君臣之道也，不念舊惡，賢人之業也，是以齊用管仲而霸功立，秦任孟明而晉恥雪。","sortOrder":35},
  {"id":"s_work_nvlt_57_36","chapterId":"ch_work_nvlt_57","text":"臣聞振鷺雖材，非六翮無以翔四海，帝王雖賢，非良臣無以濟天下。","sortOrder":36},
  {"id":"s_work_nvlt_57_37","chapterId":"ch_work_nvlt_57","text":"臣聞觀於明鏡，則疵瑕不滯於軀，聽於直言，則過行不累乎身。","sortOrder":37},
  {"id":"s_work_nvlt_57_38","chapterId":"ch_work_nvlt_57","text":"晉陆機演連珠曰：臣聞日薄星回，穹天所紀物，山盈川冲，厚地所以播氣，五行错而致用，四時违而成歲，是以百官恪居，以赴八音之離，明君執契，以要克諧之會。","sortOrder":38},
  {"id":"s_work_nvlt_57_39","chapterId":"ch_work_nvlt_57","text":"臣聞髦俊之才，世所希乏，丘園之秀，因時則扬，是以大人基命，不擢才於後土，明主幸與，不降佐於昊蒼。","sortOrder":39},
  {"id":"s_work_nvlt_57_40","chapterId":"ch_work_nvlt_57","text":"臣聞祿放於寵，非隆家之舉，官私於親，非興邦之選，是以三卿世及，東國多衰弊之政，五侯併軌，西京有陵夷之運。","sortOrder":40},
  {"id":"s_work_nvlt_57_41","chapterId":"ch_work_nvlt_57","text":"臣聞靈暉朝覯，稱物納照，時風夕洒，程形賦音，是以至道之行，萬類取足於世，大化既洽，百姓無匮於心。","sortOrder":41},
  {"id":"s_work_nvlt_57_42","chapterId":"ch_work_nvlt_57","text":"臣聞鑒之積也無厚，而照有重泉之深，目之察也有畔，而眡周天壤之际，何則，應事以精不以形，造物以神不以器，是以萬邦凯樂，非悅鍾鼓之娱，天下歸仁，非感玉帛之惠。","sortOrder":42},
  {"id":"s_work_nvlt_57_43","chapterId":"ch_work_nvlt_57","text":"臣聞智周通塞，不為時窮，才經夷险，不為势屈，是以凌霄之羽，不求反風，曜夜之目，不思倒日。","sortOrder":43},
  {"id":"s_work_nvlt_57_44","chapterId":"ch_work_nvlt_57","text":"臣聞利眼臨雲，不能垂照，朗璞蒙垢，不能吐辉，是以明哲之君，時有蔽壅之累，俊乂之臣，屢抱後時之悲。","sortOrder":44},
  {"id":"s_work_nvlt_57_45","chapterId":"ch_work_nvlt_57","text":"臣聞因雲洒润，則芳泽易流，垂風載响，則音徽自遠，是以德教俟物而濟，榮名緣時而顯。","sortOrder":45},
  {"id":"s_work_nvlt_57_46","chapterId":"ch_work_nvlt_57","text":"臣聞絃有常音，故曲終則改，鏡無畜影，故觸形則照，是以虛己應物，必究千变之容，挟情適事，不觀萬殊之妙。","sortOrder":46},
  {"id":"s_work_nvlt_57_47","chapterId":"ch_work_nvlt_57","text":"臣聞目無常音之察，耳無照景之神，故在乎我者，不殊之於己，存乎物者，不求備於人。","sortOrder":47},
  {"id":"s_work_nvlt_57_48","chapterId":"ch_work_nvlt_57","text":"臣聞觸非其類，雖疾弗應，感以其方，雖微則順，是以商飆漂山，不興盈尺之雲，穀風垂條，必降弥天之润，故闇於理者，唱繁而和寡，審乎物者，力約而功峻。","sortOrder":48},
  {"id":"s_work_nvlt_57_49","chapterId":"ch_work_nvlt_57","text":"宋謝惠連連珠曰：蓋聞獻技者易忽，養德者難致，是以子張重趼，不獲哀公之祿，幹木偃息，不受文侯之位。","sortOrder":49},
  {"id":"s_work_nvlt_57_50","chapterId":"ch_work_nvlt_57","text":"蓋聞機心難湛，不接異類，淳德易孚，可狎殊方，是以高羅舉而雲鳥降，海人萃而水禽翔。","sortOrder":50},
  {"id":"s_work_nvlt_57_51","chapterId":"ch_work_nvlt_57","text":"蓋聞春蘭早芳，實忌鳴窸，秋菊晚秀，無憚繁霜，何則，榮乎始者易悴，貞乎末者難傷，是以傅長沙而志沮，登金馬而名扬。","sortOrder":51},
  {"id":"s_work_nvlt_57_52","chapterId":"ch_work_nvlt_57","text":"蓋聞脩己知足，慮德其逸，竟榮昧進，志忘其審，是以飲河滿腸，而求安愈泰，緣木務高，而畏下滋甚。","sortOrder":52},
  {"id":"s_work_nvlt_57_53","chapterId":"ch_work_nvlt_57","text":"宋顏延之范連珠曰：蓋聞夫履順則天地不违一物，投誠則神明可交，事有微而逾著，理有闇而必昭，是以魯陽傾首，離光為之反舍，有鳥拂波，河伯為之不潮。","sortOrder":53},
  {"id":"s_work_nvlt_57_54","chapterId":"ch_work_nvlt_57","text":"齊王俭畅連珠曰：蓋聞王佐之才雖遠，豈必見采於當世，陵雲之氣徒盛，無以自致於雲間，是故魏人指玉於外野，和氏泣血於荆山。","sortOrder":54},
  {"id":"s_work_nvlt_57_55","chapterId":"ch_work_nvlt_57","text":"梁武帝連珠曰：蓋聞水鏡不以妍蚩殊照，芝蘭寧為貴賤異芳，是以弘道歸於兼濟，至德由乎兩忘。","sortOrder":55},
  {"id":"s_work_nvlt_57_56","chapterId":"ch_work_nvlt_57","text":"蓋聞一眚不足以掩德，五刑非可以妄加，是以径寸之珍，有時而颣，盈尺之寶，不能無瑕。","sortOrder":56},
  {"id":"s_work_nvlt_57_57","chapterId":"ch_work_nvlt_57","text":"蓋聞理漸其萌，豈須拔嶽之力，物有易傷，不待凌雲之繳，是以微照積而山飄，虛絃動而隼落。","sortOrder":57},
  {"id":"s_work_nvlt_57_58","chapterId":"ch_work_nvlt_57","text":"梁宣帝連珠曰：常聞盈虛之道，雖脩平而必陂，損益之由，在至象而無蠲，是以謂地之厚，而東南缺，唯天為大，而西北懸。","sortOrder":58},
  {"id":"s_work_nvlt_57_59","chapterId":"ch_work_nvlt_57","text":"常聞山有藏玉，則卉草常榮，林有猛獸，則丛枝莫采，是以漢儀重見，皇王之跡有真，周禮猶存，龟蒙之田無改。","sortOrder":59},
  {"id":"s_work_nvlt_57_60","chapterId":"ch_work_nvlt_57","text":"梁沈約連珠曰：臣聞烈風雖震，不斷蔓草之根，朽壤誠微，遂霣崇山之峭，是以一夫不佳，威於赫怒，千乘必致，亡於巧笑。","sortOrder":60},
  {"id":"s_work_nvlt_57_61","chapterId":"ch_work_nvlt_57","text":"臣聞鳴籁受响，非有志於要風，涓流長邁，寧厝心於歸海，是以萬竅怒號，不叩而鹹應，百川是納，用卑而為宰。","sortOrder":61},
  {"id":"s_work_nvlt_57_62","chapterId":"ch_work_nvlt_57","text":"梁吳筠連珠曰：蓋聞艳麗居身，而以蛾眉入妒，貞華炤物，而以絕等見猜，是以班姬辭寵，非無妖冶之色，陽子寂寞，豈乏炫曜之才。","sortOrder":62},
  {"id":"s_work_nvlt_57_63","chapterId":"ch_work_nvlt_57","text":"蓋聞義夫投節，未必識君，烈士赴危，非期要利，是以墨子萦帶，不蒙肉食之謀，申胥泣血，非有執圭之位。","sortOrder":63},
  {"id":"s_work_nvlt_57_64","chapterId":"ch_work_nvlt_57","text":"梁劉孝儀探物作艳體連珠曰：妾聞洛妃高髻，不姿於芳泽，玄妻長發，無籍於金钿，故雲名由於自美，蝉稱得於天然，是以梁妻獨其妖艳，衛姬专其可怜。","sortOrder":64},
  {"id":"s_work_nvlt_57_65","chapterId":"ch_work_nvlt_57","text":"妾聞芳性深情，雖欲忘而不歇，薰芬動慮，事逾久而更思，是以津亭掩馥，秖結秦婦之恨，爵台餘妒，追生魏妾之悲。","sortOrder":65},
  {"id":"s_work_nvlt_57_66","chapterId":"ch_work_nvlt_57","text":"【表】梁沈約註製旨連珠表曰：竊尋連珠之作，始自子雲，放易象論，動模經誥，班固謂之命世，桓谭以為絕倫，連珠者，蓋謂辭句連續，互相發明，若珠之結排也，雖复金鑣互騁，玉轪併馳，妍蚩優劣，參差相間，翔禽伏獸，易以心威，守株膠瑟，難與適变，水鏡芝蘭，隨其所遇，明珠燕石，貴賤相懸。","sortOrder":66},
  {"id":"s_work_nvlt_57_67","chapterId":"ch_work_nvlt_57","text":"《藝文類聚》　唐·欧陽詢","sortOrder":67},
  {"id":"s_work_nvlt_58_1","chapterId":"ch_work_nvlt_58","text":"卷五十八雜文部四","sortOrder":1},
  {"id":"s_work_nvlt_58_2","chapterId":"ch_work_nvlt_58","text":"○書檄移紙筆砚","sortOrder":2},
  {"id":"s_work_nvlt_58_4","chapterId":"ch_work_nvlt_58","text":"《廣雅》曰：書記曰書。","sortOrder":4},
  {"id":"s_work_nvlt_58_5","chapterId":"ch_work_nvlt_58","text":"《漢書》曰：蘇武使匈奴，被留，昭帝即位，求武等，匈奴言武已死，後漢使至匈奴，教者謂单於，言天子射上林中，雁足有系帛書，言武等在某泽中，单於顧左右而驚，謝漢使曰：武等實在，於是遣還，［事具鳥部雁篇。］","sortOrder":5},
  {"id":"s_work_nvlt_58_6","chapterId":"ch_work_nvlt_58","text":"《漢書》曰：陳遵為河南太守，既至官，遣從吏，乃召善書吏十人於前，治私書，謝京師故人，遵凭幾口授書吏，且省官事，數百封親疏各有意。","sortOrder":6},
  {"id":"s_work_nvlt_58_7","chapterId":"ch_work_nvlt_58","text":"又曰：穀永，字子雲，便於筆札，故時人雲，穀子雲之筆札，樓君卿之唇舌。","sortOrder":7},
  {"id":"s_work_nvlt_58_8","chapterId":"ch_work_nvlt_58","text":"《吳錄》曰：王宏為冀州刺史，不發私書，不交豪族，號曰王獨坐。","sortOrder":8},
  {"id":"s_work_nvlt_58_9","chapterId":"ch_work_nvlt_58","text":"《典略》曰：太祖嘗使阮瑀作書與韓遂，於馬上具草，書成呈之，太祖覽［○《太平御覽》五百九十五作攬。］筆欲有所定，而竟不能增損。","sortOrder":9},
  {"id":"s_work_nvlt_58_10","chapterId":"ch_work_nvlt_58","text":"嵇康與山涛書曰：素不便書，不憙作書，而人間多事，堆案盈幾，不相酬答，則犯教傷義，欲自勉強，則不能久堪。","sortOrder":10},
  {"id":"s_work_nvlt_58_11","chapterId":"ch_work_nvlt_58","text":"《蜀志》曰：王平，字子均，生長戎旅，手不能書，所識不過十字，而占授作書皆有意，使人讀史漢諸書聽之，通知其義，往往論說，不失其旨。","sortOrder":11},
  {"id":"s_work_nvlt_58_12","chapterId":"ch_work_nvlt_58","text":"《魯國先賢志》曰：孔翊為洛陽令，置器水於前庭，得私書，皆投其中，一無所發，彈治貴戚，無所回避。","sortOrder":12},
  {"id":"s_work_nvlt_58_13","chapterId":"ch_work_nvlt_58","text":"張華別傳曰：大駕西征鍾會，至長安，華兼中書侍郎，從行，掌軍事中書疏表檄，文帝善之。","sortOrder":13},
  {"id":"s_work_nvlt_58_14","chapterId":"ch_work_nvlt_58","text":"《語林》曰：殷洪乔作豫章郡，臨去，人寄百餘函書，既至石頭，悉掷水中，因咒之曰：沉者自沉，浮者自浮，殷洪乔不能作達書郵。","sortOrder":14},
  {"id":"s_work_nvlt_58_15","chapterId":"ch_work_nvlt_58","text":"沈約《宋書》曰：劉穆之朱齡石，併便尺牍，嘗於高祖坐，與齡石共答書，自旦至日中，穆之得百函，齡石得八十函，而穆之應對無废。","sortOrder":15},
  {"id":"s_work_nvlt_58_16","chapterId":"ch_work_nvlt_58","text":"【書】漢邹陽上書梁王曰：昔者荆軻慕燕丹之義，白虹貫日，太子畏之，衛先生為秦畫長平之事，太白食昴，昭王疑之，夫精变天地，而信不諭兩主，豈不哀哉，昔玉人獻寶，楚王誅之，李斯竭忠，胡亥極刑，是以箕子佯狂，接舆避世，語曰：白頭如新，傾蓋如故，蘇秦相燕，人惡之於燕王，燕王按劍而怒，食以駃騠。白圭顯於中山，人惡之於魏文侯，文侯投以夜光之璧，女無美惡，入宮見妒，士無賢不肖，入朝見嫉，故百里奚乞食於道，缪公委之以政，甯戚飯牛車下，桓公任之以國，此二者，豈素官於朝，借譽左右，然後二主用之哉，昔魯聽季孫之說，逐孔子，宋信子舟之計，囚墨翟，夫以孔墨之辯，不能自免於讒諛，而二國以危，何則，眾口鑠金，積毀消骨也，今人主誠能去驕傲之心，懷可報之意，則桀之狗可使吠尧，跖之客可使刺由，况因萬乘之權，假聖王之資乎，臣聞明月之珠，夜光之璧，以闇投人於道，眾莫不按劍相眄者，何則，無因而至前也，蟠木根柢，輪囷離奇，而為萬乘器者，以左右先為之容也。","sortOrder":16},
  {"id":"s_work_nvlt_58_17","chapterId":"ch_work_nvlt_58","text":"後漢班固上書東平王曰：必有非常之人，然後有非常之事，有非常之事，然後有非常之功，將軍膺千年之任，躡先王之蹤，體弘懿之資，據高明之势，昔卞和獻寶，以罹折趾，屈子納忠，終於沉身，已而和氏之璧，千載垂光，屈子之篇，萬世弥章。","sortOrder":17},
  {"id":"s_work_nvlt_58_18","chapterId":"ch_work_nvlt_58","text":"齊陆厥與沈約書問聲韻曰：長門上林，殆非一家之賦，洛神池雁，便成二體之作，孟堅精整，詠史無虧於東主，平子恢富，羽獵不累於凭虛，王粲初征，他文未能稱是，楊脩敏捷，暑賦弥日不獻，率意寡尤，則從事乎一日，医医［南齊書五十二陆厥傳作翳翳。］愈伏，而理賒於七步，一人之思，遲速天懸，一家之文，工拙壤隔，何獨宮商律呂，必责其一人也。","sortOrder":18},
  {"id":"s_work_nvlt_58_19","chapterId":"ch_work_nvlt_58","text":"梁簡文帝答張缵謝示集曰：缵好文章，於今二十五載矣，竊嘗論之，日月參辰，火龍黼黻，尚且著於玄象，章乎人事，而况文辭可止，詠歌可輟乎，不為壮夫，楊雄實小言破道，非謂君子，曹植亦小辯破言，論之科刑，罪在不赦，至如春庭落景，轉蕙承風，秋雨旦晴，簷梧初下，浮雲生野，明月入樓，時命親賓，乍動嚴駕，車渠屢酌，鸚鵡骤傾，伊昔三邊，久留四戰，胡霧連天，征旗拂日，時聞坞笛，遙聽塞笳，或乡思凄然，或雄心憤薄，是以沉吟短翰，補缀庸音，寓目寫心，因事而作。","sortOrder":19},
  {"id":"s_work_nvlt_58_20","chapterId":"ch_work_nvlt_58","text":"又答新渝侯和詩書曰：垂示三首，風雲吐於行間，珠玉生於字里，跨躡曹左，含超潘陆，双鬢向光，風流已絕，九梁插花，步搖為古，高樓懷怨，結眉表色，長門下泣，破粉成痕，复有影里細腰，令與真類，鏡中好面，還將盡［全梁文十一作畫。］等，此皆性情卓絕，親致英奇，故知吹萧入秦，方識來鳳之巧，鳴瑟向趙，始睹駐雲之曲，手持口誦，喜荷交併。","sortOrder":20},
  {"id":"s_work_nvlt_58_21","chapterId":"ch_work_nvlt_58","text":"梁元帝答劉縮求述製旨義書曰：學山學海，未臻其極，為龍為光，或從王事，所賴昔經陝服，頗足良書，凭幾據梧，靜供遊目，枕中之記，即用為枕，帷前之秩，仍可為帷，對此自娱，敬而待命，叩而必應，已謝懸鍾，汲而無竭，复乖井養。","sortOrder":21},
  {"id":"s_work_nvlt_58_22","chapterId":"ch_work_nvlt_58","text":"梁沈約與范述曾論竟陵王賦書曰：夫眇汎沧流，則不識涯涘，雜陳鍾石，則莫辯宮商，雖复吟誦環回，編離字滅，終無所辯，仰酬睿旨，微表寸長。","sortOrder":22},
  {"id":"s_work_nvlt_58_23","chapterId":"ch_work_nvlt_58","text":"梁劉孝綽答梁元帝書曰：伏承自辭皇邑，爰至荆台，未勞刺舉，且摛高麗，近雖預觀寸錦，而不睹金玉，昔臨渦辭賦，悉與楊循，［全梁文六十作修。］未殫寶笥，顧慚先哲。","sortOrder":23},
  {"id":"s_work_nvlt_58_24","chapterId":"ch_work_nvlt_58","text":"梁江淹詣宋建平王上書曰：昔者賤臣叩心，飛霜击於燕地，庶女告天，振風袭於齊台，下官蓬戶桑枢之民，布衣麻帶之士，谬得升降承明之闕，出入金華之殿，何嘗不局影凝嚴，侧身扃禁者乎，寧當爭分寸之末，競錐刀之利，積毀消金，積讒摩骨，遠則直生取疑於盜金，近則伯魚被名於不義。","sortOrder":24},
  {"id":"s_work_nvlt_58_25","chapterId":"ch_work_nvlt_58","text":"梁劉之遴與劉孝標書曰：間聞足下作類苑，括綜百家，馳騁千載，弥纶天地，纏絡萬品，撮道略之英華，搜群言之隱赜，鉛摘既畢，殺青已就，義以類聚，事以群分，述征之妙，楊班儔也，擅此博物，何快如之，雖复子野調聲，寄知音於後世，文信構覽，懸百金於當時，居然無以相尚，自非沉鬱澹雅之思，安能閉志經年，勤成若此，吾嘗聞為之者勞，觀之者逸，足下已勞於精力，宜令吾見異書。","sortOrder":25},
  {"id":"s_work_nvlt_58_26","chapterId":"ch_work_nvlt_58","text":"梁劉孝標答劉之遴借類苑書曰：九冬有隙，三餘暇時，多遊書圃，代树萱蘇，若夫采亹亹於緗紈，閱微言於殘竹，嗢飫膏液，咀嚼英華，不知地之為舆，天之為蓋，靡测回塘，莫辯舆馬，乌足以言乎，是用周流墳素，詳觀圖諜，搦管聯册，纂茲英奇，蛩蛩之謀，止於善草，周周之計，利在衔翼，故鳩集斯文，蓋自缀其漏耳，豈冀藏山之石，播於士大夫哉。","sortOrder":26},
  {"id":"s_work_nvlt_58_28","chapterId":"ch_work_nvlt_58","text":"《說文》曰：檄，二尺書也，從木敫聲。","sortOrder":28},
  {"id":"s_work_nvlt_58_29","chapterId":"ch_work_nvlt_58","text":"《釋名》曰：檄，激也，下官所以激迎其上之書文也。","sortOrder":29},
  {"id":"s_work_nvlt_58_30","chapterId":"ch_work_nvlt_58","text":"《漢書》曰：申屠嘉為丞相，邓通居上旁，怠慢，嘉為檄召通曰：不來且斬，通恐，入言於上，上曰：速往，吾令召汝，通至丞相府，免冠徒跣頓首謝。","sortOrder":30},
  {"id":"s_work_nvlt_58_31","chapterId":"ch_work_nvlt_58","text":"《東觀漢記》曰：光武數召諸將，置酒賞賜，坐席之間，以要其死力，當此之時，賊檄日以百數，忧不可勝，上猶以餘間講經藝。","sortOrder":31},
  {"id":"s_work_nvlt_58_32","chapterId":"ch_work_nvlt_58","text":"又曰：隗嚣，故宰府掾吏，善為文書，每上書移檄，士大夫莫不諷誦。","sortOrder":32},
  {"id":"s_work_nvlt_58_33","chapterId":"ch_work_nvlt_58","text":"又曰：庐江毛義，少時家貧，以孝行稱，南陽張奉慕其義，往候之，坐定而府檄適至，以義守令，義奉檄而入，喜動顏色。","sortOrder":33},
  {"id":"s_work_nvlt_58_34","chapterId":"ch_work_nvlt_58","text":"《典略》曰：張儀，魏人，常從楚相飲，楚相亡璧，意儀盜之，掠笞數百，既相秦，為檄告楚相曰：吾從汝飲，不盜汝璧，善守汝國，我且盜汝城。","sortOrder":34},
  {"id":"s_work_nvlt_58_35","chapterId":"ch_work_nvlt_58","text":"又曰：陳琳作諸書及檄草成，呈太祖，太祖先苦頭風，是日疾發，臥讀琳所製，翕然而起曰：此愈我病，數加厚賜。","sortOrder":35},
  {"id":"s_work_nvlt_58_36","chapterId":"ch_work_nvlt_58","text":"《魏志》曰：孫放善為書檄，三祖谘命招喻，多放所為。","sortOrder":36},
  {"id":"s_work_nvlt_58_37","chapterId":"ch_work_nvlt_58","text":"李充《起居戒》曰：軍書羽檄，非儒者之事，且家奉道法，言不及殺，語不虛誕，而檄不切厲則敵心陵，言不夸壮則軍容弱，請姑舍之，以擬能者。","sortOrder":37},
  {"id":"s_work_nvlt_58_38","chapterId":"ch_work_nvlt_58","text":"《續晉陽秋》曰：何無忌母，劉牢之姊也，無忌與高祖謀，夜於屏風里製檄文，母潛登屏風上窥，既知其謀，大喜曰：汝能如此，吾讎恥雪矣。","sortOrder":38},
  {"id":"s_work_nvlt_58_39","chapterId":"ch_work_nvlt_58","text":"【檄文】漢司馬相如喻巴蜀檄文曰：夫邊郡之士，聞烽舉燧，皆攝弓而馳，荷兵而走，流汗相屬，唯恐居後，觸白刃，冒流矢，議不反顧，計不旋踵，彼豈樂死惡生，而巴蜀異主哉，計深慮遠，急國家之難，而樂盡人臣之道也，故有剖符之封，折珪而爵，終則遺顯號於後世，傳土地於子孫，名聲施於無窮，功烈著於不滅，是以賢人君子，肝腦涂中原，膏泽润野草，而不辭也，今奉幣役至南夷，即自賊殺，或亡逃抵誅，身死無名，謚為至愚，恥及父母，為天下笑，人之度量，相越豈不遠哉。","sortOrder":39},
  {"id":"s_work_nvlt_58_40","chapterId":"ch_work_nvlt_58","text":"魏陳琳為袁紹檄豫州曰：操父嵩，乞丐携養，因贓假位，舆金攒璧，输货權門，竊盜鼎司，傾覆重器，續遇董卓，侵官暴國，於是收羅英雄，弃瑕取用，故遂與操，同谘合謀，操遂承資跋扈，肆行凶慝，割剝元良，殘賢害善，爵賞由心，刑戮在口，所愛光五宗，所惡滅三族。又特置發丘中郎，摸金校尉，所過墮突，無骸不露，乃欲摧桡棟梁，孤弱漢室，除滅忠正，专為枭雄，某俯奉漢威靈，折冲宇宙，長戟百萬，胡騎千群，奋虎贲育獲之士，騁良弓劲弩之势，併州越太行而角其前，荆州下宛葉而掎其後，若舉炎火以爇飛蓬，覆沧海以沃熛炭，有何不消滅者。","sortOrder":40},
  {"id":"s_work_nvlt_58_41","chapterId":"ch_work_nvlt_58","text":"又檄吳將校曰：孫權小子，未辯菽麥，要領不足以膏萧斧，名字不足以汙簡墨，謂為舟楫足以拒皇威，江湖可以逃嚴誅，不知天網設張，以在綱目，爨镬之魚，期於消烂也，若使水而可恃，則洞庭無三苗之墟，子陽無荆門之败，朝鮮之壘不刊，兩越之旌不拔也，丞相衔奉國威，為民除害，元惡大憝，必當枭夷，蓋鳳鳴高岡，以遠罻羅，聖賢之德也，鸋窸之鳥，巢於苇苕，苕折子破，下愚之惑也，今江東之地，無異苇苕，諸賢處之，信亦危矣。","sortOrder":41},
  {"id":"s_work_nvlt_58_42","chapterId":"ch_work_nvlt_58","text":"魏鍾會檄蜀文曰：今主上聖德钦明，紹隆前緒，宰辅忠肅，明允劬勞，王室布政垂惠，而萬邦协和，施德百蠻，而肅慎致貢，悼彼巴蜀，獨為匪民，是以命授六師，恭行天罰，今邊境乂清，方內無事，蓄力待時，併兵一向，而以蜀一州之眾，分張守備，難以御天下之師，比年以來，曾無寧歲，征人勤瘁，難以當子來之民，此皆諸賢所共親見，誠能鑒茲成败，邈然高蹈，投跡微子之蹤，橫身陳平之軌，則福同古人，慶流來裔。","sortOrder":42},
  {"id":"s_work_nvlt_58_43","chapterId":"ch_work_nvlt_58","text":"晉孫惠為東海王讨成都王檄文曰：穎禀性強暗，增崇位號，阿比奄官，专任孟玫，遂使恣睢，殺活由己，疾諫好讒，小人滿侧，官以賄成，位以錢獲，囚以货生，獄以幣解，百官卷舌，朝野隱伏，案穎之罪，書記未有，禍甚叔帶，逆隆魯桓，為子則不孝，為臣則不忠，為弟則不順，為主則不仁，四惡具矣，豺狼之性，有甚無悛。","sortOrder":43},
  {"id":"s_work_nvlt_58_44","chapterId":"ch_work_nvlt_58","text":"晉庾闡為郄鑒檄青州文曰：蓋天地有盈虛之期，皇代有盛衰之會，姬文至聖，猶西患崑夷，周室哲王，而北難獫玁，天步禍亂，有自來矣，是以石勒因曩者之弊，遇皇綱暫弛，遂陵跨神州，剪覆上國，二十餘載，毒流四海，人神含憤，天誅自滅，而石虎窮凶，袭其餘業，內肆豺狼之暴，外有無辜之禍，念諸文武百姓，同為和氣之民，而不蒙太陽之施，奔波於海岱之間，逼迫於寇戎之手，行者窮征役，居者困重賦，死生契闊，良難為心。","sortOrder":44},
  {"id":"s_work_nvlt_58_45","chapterId":"ch_work_nvlt_58","text":"又檄李势曰：告巴蜀士民，夫昏明代運，否終則泰，賢哲睹機以知变，不肖滅亡以取禍，昔者皇運中消，乾綱暫弛，耀［按當作曜，謂劉曜。］勒窮凶，肆暴神州，李劉啟逆，竊逼岷川，翼以不才，任符分陝，未能仰宣皇恩，招携以禮，而使三巴之民，製於犬羊之群，元元之命，懸於豺狼之口，所以假寐永叹，疾疢如首者也，凡百黎萌，秋毫不犯，檄到勉思良圖，自求多福，無使蘭艾同焚，永作鑒誡，信誓之明，有如皎日。","sortOrder":45},
  {"id":"s_work_nvlt_58_46","chapterId":"ch_work_nvlt_58","text":"又為檄石虎文曰：石勒因衅，剪覆舊京，窮凶極逆，伪號累祀，百姓受灰没之酷，王室有黍離之哀，不有少康之隆，孰能祀夏，不有宣王之興，誰剋舊物，羯帥石虎，僣袭凶葉，負恃其眾，陆梁河朔，每念忠順之士，懷仁抱義，含胆飲血，離其禍酷，心存倒戈，而力不能奋，今遣使持節荆州刺史都亭侯翼，高旗連雲，組練映日，運孫吳之筹，按尚甫之略，莫不張胆咀鐵，人思自百，以此眾戰，其猶烈火之燔秋蓬，衡飆之扫落葉也。","sortOrder":46},
  {"id":"s_work_nvlt_58_47","chapterId":"ch_work_nvlt_58","text":"晉桓溫檄胡文曰：胡賊石勒，暴肆華夏，齊民涂炭，煎困讎孽，至使六合殊風，九鼎乖越，每惟國難，不遑啟處，撫劍北顧，慨叹盈懷，寡人不德，忝荷戎重，師次安陆，經營舊邑，瞻望華夏，暫成楚越，登丘凄覽，征夫憤慨，昔叔孫絕粒，義不同惡，龚生守節，恥存莽朝，歷既逋僣，一朝荡定，拯撫黎民，即安本大，訓之以德禮，润之以玄泽，信感荒外，武扬八極，先順者獲賞，後伏者前誅，德刑既明，隨才攸叙，此之風范，想所聞也。","sortOrder":47},
  {"id":"s_work_nvlt_58_48","chapterId":"ch_work_nvlt_58","text":"梁元帝伐侯景檄文曰：粵若梁興五十餘載，平一宇內，德惠攸長，仁育群生，義征不服，建翠鳳之旗，則六龍驤首，击靈鼍之鼓，則百神警肅，風牧方邵之賢，衛霍辛趙之將，叱咤則風雲興起，鼓動則嵩華倒拔，葉和萬邦，平章百姓，十尧九舜，曷足雲也，賊臣侯景，匈奴叛臣，鳴鏑餘噍，冒於货賄，不知其極，敢興逆亂，梗我王畿，賊臣正德，阻兵安忍者，結怨江幹，遠適单於，虔劉我人民，離散我兄弟，臧獲之人，五宗及賞，搢紳之士，三族見誅，南山之竹，未足言其愆，西山之兔，不足書其罪，雷震風駭，直指建鄴，按劍而叱，江水為之倒流，抽戈而揮，皎日為之還舍，如驷馬之載鸿毛，奔牛之觸魯縞。","sortOrder":48},
  {"id":"s_work_nvlt_58_49","chapterId":"ch_work_nvlt_58","text":"梁裴子野喻虜檄文曰：天生蒸民，树之以君，所以對越三才，司牧黔首，蠲其苛慝，除其患難，肇自遂古，以迄皇王，經世字民，鹹由此作，朕拨亂反正，君臨亿兆，休牛放馬，載戢幹戈，思與一世之民，跻之仁寿之域，昔者晉失其序，天篤降丧，而四夷交侵，小雅盡缺，宋之初載，實有武功，秦晉之墟，頻枭僣伪，末葉陵遲，遂亡淮濟，曠日長久，莫能克复，朕爰初創業，思閒寧靜，保大定功，未遑遠略，而狡虜遊魂，不式王命，朕謂其君是惡，其民何罪，矜此涂炭，用寢兵革，今戎丑數亡，自相吞噬，重以亢旱弥年，穀价騰踴，丁壮死於軍旅，婦女疲於轉输，虐政惨刑，曾無懲改，四方同集，九服齊契，譬猶翻東海以註螢爝，倒崑崙以壓蝼蚁，其身縻烂，豈假多力，爾二周故老，六辅大姓，蒙恥俯首，有自來矣，濯身明目，今也其時，昔由餘入秦，禮以卿佐，日磾降漢，華豹七葉，苟有其才，豈無大位，梁任孝恭為汝南王檄魏文曰：夫大盜移國，終繼枭翦之誅，凶狡凭凌，必致殲夷之戮，所以董卓稱亂，徒藉群雄之手，王莽偷安，卒成光武之業，故市耀脐燈，府傳飲器，我有魏今臨一境，卜世相承，保乂黔黎，事逾年祀，爾朱榮胡貊遺种，邊塞是居，奸宄妄才，凶愚丑類，茹血餐腥，本非人品，依隨水草，取類馬牛，而包藏禍圖，竊懷反噬，遂長驅种落，用袭我周南，率彼酋豪，侵凌我河縣，所以流離播越，亟淹星紀，仰慕園陵，俯傷黎庶，遂得式仰唐朝，宣奉舜闕，梁大皇帝，功逾五帝，道邁三皇，負扆當軒，平章百姓，垂拱而治，协和萬邦，今遣同州刺史范遵等，董率前鋒，扬旌致讨，先取滑台，鼓行金穀，關東英俊，河北雄才，痛桑梓淪芜，室家顛殒，飲氣吞聲，志申讎怨，士各懷歸，民思父母，表里符契，神靈响集，王者之師，有征無戰，鋒刃所裁，幸勿罹染。","sortOrder":49},
  {"id":"s_work_nvlt_58_50","chapterId":"ch_work_nvlt_58","text":"後魏魏收檄梁文［全北齊文五據文苑英華六百四十五，通鑒一百六十作杜弼文。］曰：夫辰象麗天，山嶽镇地，方以類聚，物以群分，建之以邦國，树之以君長，日月於是莫貳，帝王所以總一，雖五運相推，百王革命，此道所行，孰雲能易，而皇家承統，光配彼天，義洽幽明，化周動植，崇文德以來遠，修禮讓以止訟，舞幹戚於兩階，執玉帛於萬國，玄功潛運，至德旁通，百姓日用而不知，兆民受賜而無跡，唯彼吳越，獨阻聲教，侯景竖子，本無土業，以金陵逋逃之藪，江南流離之地，甘辭卑體，進孰［英華，通鑒作熟。］圖身，而伪朝大小，幸灾忘義，主荒於上，臣蔽於下，人而無禮，其能國乎，亦既失信，不亡何待，今帝道休明，皇猷允塞，雖有賊臣去國，亡卒出境，何異一毛之落牛體，双凫之飛海濱，彼既連結奸惡，斷絕鄰好，追兵保境，縱盜侵國，蓋物無定方，事無常势，是以吳侵齊境，遂致句踐之師，趙納韓地，終有上［英華，通鑒作長。］平之役，矧乃鞭撻疲民，侵軼徐部，筑壘擁川，舍信邀利，此而可忍，孰不可懷，貞陽以猶子之親，當戎首之任，非但力屈道窮，亦將路無還蜀，兼复狹子垂翅，俱在籠樊，雖复貪利苟得，背同即異，獲一人而失一國，見黃雀而忘深井，智者所不為，仁者所不向，誠既往之難逮，猶將來之可追，侯景以鄙里之夫，遭風雲之會，位登三事，邑啟萬家，揣身量分，久當止足，彼乃示之以利器，誨之以慢藏，使其势得容奸，令其時堪乘便，計雖非孫吳猛將，燕趙精兵，猶是久涉行陣，曾習軍旅，拒此則作氣不足，攻彼則為势有餘，呼之則返速而衅小，不懲則叛遲而禍大，但恐楚國忘猿，禍延林木，城門失火，殃及池魚，橫使江黃士子，荆楊人物，死亡矢石之下，夭折露霧之中，人人厭苦，家家思亂，將险躁之風俗，任輕薄之子孫，朋党路开，兵權在外，必將禍生骨肉，難起腹心，強孥［英華，通鑒作弩。］冲城，長戟指闕，徒探雀鷇，無用府藏之虛，空請熊蹯，詎延漏刻之命，外崩中潰，今實其時，鷸蚌相扼，我乘其弊，方使鍾山渡江，青蓋入洛，荆棘生於建業之宮，麋鹿遊於姑蘇之馆，但恐革車之所轥轹，劍騎之所蹂踐，椅梓於焉傾折，竹箭以此摧殘，若吳之王孫，蜀之公子，順時以動，見機而作，歸款軍門，委命下吏，當使焚榇而出，拂席相俟，必以楚材，終為晉用也。","sortOrder":50},
  {"id":"s_work_nvlt_58_51","chapterId":"ch_work_nvlt_58","text":"陳徐陵檄周文曰：主上恭膺寶歷，嗣奉瑤圖，既禀聖人之材，兼富神武之略，乂安兆庶，共靖戎華，同戢幹戈，永銷鋒鏑，况复追惟在楚，無忘玉帛之言，軫念過曹，猶感盤餐之惠，年馳玉節之使，歲降銀車之恩，庶彼懷音，微悟知感，而反其藏匿，招我叛臣，翊從瀟湘，空竭關垄，荆梁左右，漢沔東西，籥地呼天，望停哀救，夫一人掩泣，猶怆滿堂，百姓為心，弥切宸扆，大都督吳明彻，台司上將，德茂勋高，威著荆湘，化聞庸蜀，叱咤而平宿豫，吹噓而定寿陽，席卷江淮，無淹絃望。","sortOrder":51},
  {"id":"s_work_nvlt_58_53","chapterId":"ch_work_nvlt_58","text":"范晔《後漢書》曰：韓馥見民情歸袁紹，忌方得眾，恐將圖己，常遣從事守紹門，不聽發兵，乔〈王胃〉［《太平御覽》五百九十七作瑁。］乃诈三公移書，傳驿州郡，說董卓罪惡，企望義兵，以釋國難，馥於是方聽紹舉兵。","sortOrder":53},
  {"id":"s_work_nvlt_58_54","chapterId":"ch_work_nvlt_58","text":"王隱《晉書》曰：毛寶據邾城陷，寶尸沉江不出，戴詳移告河伯諸神，使出寶尸，十餘日乃出。","sortOrder":54},
  {"id":"s_work_nvlt_58_55","chapterId":"ch_work_nvlt_58","text":"《典略》曰：衛襄，字叔遼，修行至孝，州郡嘉之，時有白波賊眾數萬人，官兵誅讨不能平，而使襄要我原解散，於是襄為書移，即平定。","sortOrder":55},
  {"id":"s_work_nvlt_58_56","chapterId":"ch_work_nvlt_58","text":"【移文】漢劉歆讓太常博士移文曰：歆欲建立左氏春秋毛詩逸禮古文尚書，習［漢書三十六劉歆傳作皆。］列學官，哀帝令歆與五經博士講論其義，諸儒博士或不肯置對，歆因移書责讓之曰：往者缀學之士，不思废絕之關，［漢書作闕。］苟因陋就寡，分文析字，信口說而背傳記，是末師而非往古，至於國家將有大事，若立辟雍封禪巡狩之儀，則幽冥而莫知其源，猶欲保殘守缺，挟恐見破之私意，而亡從善服義之公心，或懷疾妒，不考情實，雷同相從，隨聲是非，抑此三學，皆以尚書為不備，謂左氏為不傳春秋，豈不哀哉，夫子曰［按子曰二字衍。］可與樂成，難與慮始，此乃眾庶之所為耳，非所望於士君子也。","sortOrder":56},
  {"id":"s_work_nvlt_58_57","chapterId":"ch_work_nvlt_58","text":"梁簡文帝答穰城求和移文曰：屬彼數及侮亡，運逢瓦解，石言水斗，實验地凶，飛絮雨粟，還符天怪，故淪俗駿奔，遺黎南請，所以皇略北征，臨［臨字疑衍。］事同拯溺，愍百姓之未安，傷一物之失所，故餘民襁負，扫［原訛揥，據冯校本改。］地來王，而向化之党，怱覽今移，鹹以陶茲禮樂，重睹衣冠，已变伊川之發，兼削呼韓之衽，寧當生入玉關，死歸建業，民情若此，匪我求蒙，行人遠屆，實亦勞止，想近察時機，遠詳圖緯，早去中原，遽反桑梓，旋地脈［原訛〈月末〉，據冯校本改。］而北移，越天渠而南指，然後三姓二賢，可存十半，如其遂固守株，不達玄象，將恐衛將之師，复有狼居之戰，侯應之讨，更睹陰山之哭。","sortOrder":57},
  {"id":"s_work_nvlt_58_58","chapterId":"ch_work_nvlt_58","text":"梁任孝恭答魏初和移文曰：蓋軒轅五十二戰，義在拯民，湯武二十七征，本惟靜難，明異時而同致，信殊政而一拨，［全梁文六十七作揆。］我皇屈茲上聖，承彼百王，卷六合而包容，弘二儀而覆載，照高日月，泽富雲雨，值魏氏紛纶，亟離星晷，競尋幹戈，爭以興废，王無卒歲，相不浃辰，只馬泣師，月陳庭闕，裹糧請救，日款關扉，故屢動雲旗，再驅蒼兕，同小白之存亡，等任好之繼絕，匹婦是讎，尺土非利，然百戰百勝，猶苦四民，九拒九攻，終勞萬姓，納皇之念，無忘日昃，李陵失律，暫摧羽鱗，同孟明之反秦，似荀罃之歸晉，併赉來移，聞之委曲，知彼當壁得人，兆龟有主，欲偃兵戈，式敦雅好，鶴鳴九皋，戾天已响，出其言善，良以欣然，辄勒緣邊屯戍，各息烽警，旌旗盡卷，刁斗夜停，混雞犬於四鄰，接桑麻［原訛床，據冯校本改。］於二境，陳徐陵為護軍長史王质移文曰：比金風已劲，玉露方团，宜及窮秋，幸逾高塞，當使孤旌不反，只騎無還，非止湯羅，豈知尧德，其承比年民墊，仍歲蘊隆，粒粟貴於隨珠，分糜乏於齊鼎，且氐羌旅拒，已跨伊瀍，胡羯凭陵，方逾汾潞，刺虎之势，時則卞生，拾蚌之機，弥验蘇子，但國家體茲明信，有同皎日，豈唯風雨之旦，猶救匹夫，宵夢之言，無欺幽壤，賊華皎，近以臨蕃有譴，作牧無章，既懼槛車之徵，便忧齊斧之戮，遂乃治兵楚夢，竊戴幹戈，傍引西戎，共謀東夏，伪周遣其衛國公宇文直等，總統獯獫，為其羽翼，丑徒濟岸，來攻郢城，逆竖浮舟，同趣夏浦，王師舣棹，素在中流，群帥爭驅，應時殲荡，羌胡寶馬，縱橫七泽之中，荆楚樓船，弥滿三江之上，浮禽所獲，水陆無遺，華皎擢自刍微，叨居蕃翰，情慚犬馬，罔顧恩靈，翻執幹戈，自圖家國，聞諸間諜，具彼鄰謀，乃授冬官，即為乡导，雖傷仁義之俗，非敢有私，期和與之情，猶冀無失。","sortOrder":58},
  {"id":"s_work_nvlt_58_59","chapterId":"ch_work_nvlt_58","text":"又移齊曰：獲去月二十日移，承羯寇平殄，同懷慶悅，眷言鄰穆，深副情佇，夫天綱之大，固無微而不擒，神武之師，本無征而不克，至如戎王傾其部落，逆竖道其乡關，非厥英圖，殆難堪戮，况复洞庭遐曠，丘食殷阜，西窮版屋，北罄氈庐，聲冠符姚，势兼聰勒，庸蜀寶馬，弥山不窮，巴漢樓船，陵波無际，我之元戎上將，协力同心，承禀朝謩，致行明罰，為風為火，殪彼蒙冲，如霆如雷，击其舟艦，羌兵楚賊，赴水沉沙，弃甲則兩岸同奔，橫尸則千里相枕，江川盡滿，譬睢水之無流，原隰窮胡，等陰山之長哭，於是黑山叛邑，諸城洞开，白虜連群，投戈請命，長沙鵩鳥，靡复為妖，湘川石燕，自然還舞，克翦無筭，缧禽不赀，欲計軍俘，終難巧歷，所獲其龍駒骥子，百□千蓬，［本集作百千其群。］更开苜蓿之園。方廣騊駼之廄，於是衛霍甘陳，虬髭瞋目，心馳垄路，志飲河源，乘勝長驅，未知所限，豈如桓溫不武，弃彼關中，殷浩無能，長茲羌賊，方且西逾酒郡，抵我境而置邊亭，東略鹽池，為齊朝而反侵地，此改［本集作政。］亦翦妖氛，未窮巢窟，便聞慶捷，愧佩良深。","sortOrder":59},
  {"id":"s_work_nvlt_58_61","chapterId":"ch_work_nvlt_58","text":"《東觀漢記》曰：黃門蔡倫，典作上方，作紙，所謂蔡侯紙也。","sortOrder":61},
  {"id":"s_work_nvlt_58_62","chapterId":"ch_work_nvlt_58","text":"董巴記雲，東京有蔡侯祗［《太平御覽》六百零五作紙。］即倫也，故麻名麻紙，木皮名榖紙，故［御覽故下有魚網作紙，名五字，此脱。］網紙也。","sortOrder":62},
  {"id":"s_work_nvlt_58_63","chapterId":"ch_work_nvlt_58","text":"《三辅决錄》曰：韦誕奏，蔡邕自矜能兼斯善［書斷作喜。］之法，非流紈素，不妄下筆，夫欲善其事，必先利其器，罔［《太平御覽》七百四十七作用。］張芝筆，古［御覽作左。］伯紙，及臣黑，［御覽作墨。］皆古法，兼此三具。又得巨［御覽作臣。］手，然後可以盡径丈［原訛經文，據冯校本改。］之势，方寸之言。","sortOrder":63},
  {"id":"s_work_nvlt_58_64","chapterId":"ch_work_nvlt_58","text":"王隱《晉書》曰：陳寿卒，詔下河南，遣吏贲紙筆，就寿門下，寫取國志。","sortOrder":64},
  {"id":"s_work_nvlt_58_65","chapterId":"ch_work_nvlt_58","text":"渚宮舊事曰：皇太子初拜，給赤紙縹紅紙麻紙敕紙法紙，各一百。","sortOrder":65},
  {"id":"s_work_nvlt_58_66","chapterId":"ch_work_nvlt_58","text":"《抱朴子》曰：洪家貧，伐薪賣之，以給紙筆，晝營園田，夜以柴火寫書，坐此之故，不得早涉藝文，常乏紙，每所寫，皆反覆有字，人少能讀。","sortOrder":66},
  {"id":"s_work_nvlt_58_67","chapterId":"ch_work_nvlt_58","text":"《文士傳》曰：楊脩為魏武主簿，嘗白事，知必有反覆教，豫為答數紙，以次牒之而行，告其守者曰：向白事，每有教出，相反覆，若案此弟連答之，已而有風，吹紙亂，遂错誤，公怒推問，脩慚懼，以實答。","sortOrder":67},
  {"id":"s_work_nvlt_58_68","chapterId":"ch_work_nvlt_58","text":"《晉陽秋》曰：劉弘為荆州刺史，每有興發，手書郡國，丁寧款密，故莫不感悅，顛倒恭赴，鹹曰：公一紙書，賢於十部從事也。","sortOrder":68},
  {"id":"s_work_nvlt_58_69","chapterId":"ch_work_nvlt_58","text":"《語林》曰：王右軍為會稽令，謝公就乞箋紙，捡挍库中，有九萬箋紙，悉以乞謝公。","sortOrder":69},
  {"id":"s_work_nvlt_58_70","chapterId":"ch_work_nvlt_58","text":"沈約《宋書》曰：張永善隸書。又有巧思，紙及墨，皆自營造，上每得永表啟，辄玩咨嗟，自叹供御者不之及也。","sortOrder":70},
  {"id":"s_work_nvlt_58_71","chapterId":"ch_work_nvlt_58","text":"【賦】晉傅鹹紙賦曰：蓋世有质文，則治有損益，故禮隨時变，而器與事易，既作契以代繩兮。又造紙以當策，夫其為物，厥美可珍，廉方有則，體絜性真，含章蘊藻，實好斯文，取彼之弊，以為此新攬之則舒，舍之則卷，可屈可伸，能幽能顯。","sortOrder":71},
  {"id":"s_work_nvlt_58_72","chapterId":"ch_work_nvlt_58","text":"【啟】梁劉孝威謝赉宮紙啟曰：臣與謝嘏，俱慚其聖，神［《初學記》二十一作臣。］之冲梯，實愧魯般之巧，嘏之城壘，特無禽子之守，攻弱侮亡，其勞甚薄，策勋行賞，為渥過隆，雖复業［《初學記》作鄴。］殿鳳衔，漢朝魚網，平淮桃花，中宮榖树，固以彀慚茲靡滑，謝此鮮光。","sortOrder":72},
  {"id":"s_work_nvlt_58_74","chapterId":"ch_work_nvlt_58","text":"《博物志》曰：蒙恬造筆。","sortOrder":74},
  {"id":"s_work_nvlt_58_75","chapterId":"ch_work_nvlt_58","text":"《釋名》曰：筆，述也，述事而書之也。","sortOrder":75},
  {"id":"s_work_nvlt_58_76","chapterId":"ch_work_nvlt_58","text":"《韓詩外傳》曰：趙簡子有臣曰周舍，立於門下，三日三夜，簡子問其故，對曰：臣為君諤諤之臣，墨筆執牍，從君之後，伺君過而書之。","sortOrder":76},
  {"id":"s_work_nvlt_58_77","chapterId":"ch_work_nvlt_58","text":"《列仙傳》曰：李仲甫，潁川人，漢桓帝時，賣筆遼東市上，一筆三錢，有錢亦與筆，無錢亦與筆。","sortOrder":77},
  {"id":"s_work_nvlt_58_78","chapterId":"ch_work_nvlt_58","text":"《漢書》曰：張安世持橐簪筆，［橐，挈橐也，近臣負橐筆，從備顧問，或有記。］事孝武帝數十年，見謂忠謹。","sortOrder":78},
  {"id":"s_work_nvlt_58_79","chapterId":"ch_work_nvlt_58","text":"華峤《後漢書》曰：班超投筆叹曰：大丈夫安能久事筆耕乎，［事具人部。］謝承《後漢書》曰：王充於宅內，門戶壚柱，各置筆砚簡牍，見事而作，著論衡八十五篇。","sortOrder":79},
  {"id":"s_work_nvlt_58_80","chapterId":"ch_work_nvlt_58","text":"《漢官儀》曰：尚書令仆丞郎，月給赤管大筆双，篆題曰：北工作楷，於頭上，象牙寸半著筆下。","sortOrder":80},
  {"id":"s_work_nvlt_58_81","chapterId":"ch_work_nvlt_58","text":"《廣志》曰：漢諸郡獻兔毫，書鸿門題，唯趙國毫中用。","sortOrder":81},
  {"id":"s_work_nvlt_58_82","chapterId":"ch_work_nvlt_58","text":"《典略》曰：王粲才既高，辯論應機，鍾繇王朗等，雖各為魏卿相，至於朝廷奏議，皆閣筆，不敢措手。","sortOrder":82},
  {"id":"s_work_nvlt_58_83","chapterId":"ch_work_nvlt_58","text":"《魏略》曰：王思為大司徒，性急，嘗執筆作書，蠅集筆端，驅去复來，如是再三。思怒，自起逐蠅，不能去，［去字原缺，據冯校本補。］還取筆掷地，蹹坏之。","sortOrder":83},
  {"id":"s_work_nvlt_58_84","chapterId":"ch_work_nvlt_58","text":"《魏志》曰：甄後九歲，憙書，用諸兄筆，或非之，後曰：古賢女皆覽前世成败，不知書，何由見之。","sortOrder":84},
  {"id":"s_work_nvlt_58_85","chapterId":"ch_work_nvlt_58","text":"魏末傳曰：夏侯太初見召，還洛陽，絕人道，不畜筆砚。","sortOrder":85},
  {"id":"s_work_nvlt_58_86","chapterId":"ch_work_nvlt_58","text":"傳［《太平御覽》六百零五作傅。］子曰：漢末，一筆之押，雕以黃金，飾以和璧，缀以隨珠，發以翡翠，此筆非文犀之植，必象齒之管，丰狐之柱，秋兔之翰，用之者必被朱繡之衣，踐雕玉之履矣。","sortOrder":86},
  {"id":"s_work_nvlt_58_87","chapterId":"ch_work_nvlt_58","text":"《東宮舊事》曰：皇太子初拜，給漆筆四枝，銅博山筆床副。","sortOrder":87},
  {"id":"s_work_nvlt_58_88","chapterId":"ch_work_nvlt_58","text":"【詩】梁簡文帝詠筆格詩曰：仰出寫含花，橫插學仙掌，行因提拾用，遂廁旋台賞。","sortOrder":88},
  {"id":"s_work_nvlt_58_89","chapterId":"ch_work_nvlt_58","text":"梁徐擒詠筆詩曰：纖端奉積润，弱质散芳煙，直寫飛蓬牒，橫承落繡篇，一逢提握重，寧憶仲升捐。","sortOrder":89},
  {"id":"s_work_nvlt_58_90","chapterId":"ch_work_nvlt_58","text":"【賦】後漢蔡邕筆賦曰：惟其翰之，所生，於季冬之狡兔，性精亟以摽悍，體遄近以騁步，削文竹以為管，加漆系之纏束，形調摶以直端，染玄墨以定色，書乾坤之陰陽，贊三皇之洪勋，叙五帝之休德，扬荡荡之典文，紀三王之功代兮，表八百之肆勤，傳六經而輟百氏兮，建皇極而序彝倫，綜人事於晻昧兮，贊幽冥於神明，象類多喻，靡施不协，上刚下柔，乾坤之位也，新故代謝，四時之次也，圓和正直，規矩之極也，玄首黃管，天地之色也。","sortOrder":90},
  {"id":"s_work_nvlt_58_91","chapterId":"ch_work_nvlt_58","text":"晉傅玄筆賦曰：簡脩毫之奇兔，選珍皮之上翰，濯之以清水，芬之以幽蘭，嘉竹翠色，彤管含丹，於是班匠竭巧，名工逞術，纏以素枲，納以玄漆，染芳松之淳煙，寫文象於紈素，動應手而從心，煥光流而星布。","sortOrder":91},
  {"id":"s_work_nvlt_58_92","chapterId":"ch_work_nvlt_58","text":"晉成公綏故筆賦曰：有仓頡之奇生，列四目而兼明，慕羲氏之畫卦，載萬物於五行，乃發慮於書契，采秋毫之類芒，加膠漆之綢缪，結三束而五重，建犀角之玄管，屬象齒於纖鋒，染青松之微煙，著不泯之永蹤，則象神仙，人皇九頭，式范群生，異體怪軀，註玉度於七經，訓河洛之讖緯，書日月之所躔，別列宿之舍次，乃皆是筆之勋，人日用而不寤，［自一零四七頁三行第十字(將字)起，至此止，宋本缺，據明本補。］仡盡力於萬機，卒見弃於行路。","sortOrder":92},
  {"id":"s_work_nvlt_58_93","chapterId":"ch_work_nvlt_58","text":"梁吳筠筆格賦曰：幽山之桂树，恒萦風而抱霧，葉委鬱而陆離，根縱橫而盤互，爾其負霜含液，枝翠心赤，翦其片條，為此筆格，趺則巖巖方爽，似華山之孤上，管則員員峻逸，若九疑之爭出，長對坐而衔煙，永臨窗而储筆。","sortOrder":93},
  {"id":"s_work_nvlt_58_94","chapterId":"ch_work_nvlt_58","text":"【贊】晉郭璞筆贊曰：上古結繩，易以書契，經緯天地，错綜群藝，日用不知，功蓋萬世。","sortOrder":94},
  {"id":"s_work_nvlt_58_95","chapterId":"ch_work_nvlt_58","text":"【銘】後漢李尤筆銘曰：筆之強志，庶事分別，七術雖眾，猶可解說，投足擇言，驷不及舌，筆之過誤，愆尤不滅。","sortOrder":95},
  {"id":"s_work_nvlt_58_96","chapterId":"ch_work_nvlt_58","text":"魏傅選筆銘曰：昔在上古，結繩而誓，降及後載，易以書契，書契之興，興自頡皇，肇建一體，浸遂繁昌，弥纶群事，通遠達幽，垂訓紀典，匪筆靡脩，寔為心盡，臧否斯由，厥美弘大，置類鮮畴，德興之著，惟道是扬，苟逞其违，禍亦無方。","sortOrder":96},
  {"id":"s_work_nvlt_58_97","chapterId":"ch_work_nvlt_58","text":"晉王隱筆銘曰：豈作其筆，必兔之毫，調利難禿，亦有鹿毛。","sortOrder":97},
  {"id":"s_work_nvlt_58_98","chapterId":"ch_work_nvlt_58","text":"【啟】梁元帝謝宮［全梁文十六宮上有東字。］賜白牙鏤管筆啟曰：春坊漆管，曲降深恩，北宮象牙，猥蒙霑逮，雕镌精巧，似遼東之仙物，圖寫奇麗，笑蜀郡之儒生，故知嵇賦非工，王銘未善，昔伯偕致赠，才屬友人，葛龚所酬，止聞通識，豈若遠降鸿慈，曲覃庸陋，方覺琉璃無昬，隨珠過侈，但有羨卜商，無因則削，徒懷曹植，恒原執鞭。","sortOrder":98},
  {"id":"s_work_nvlt_58_99","chapterId":"ch_work_nvlt_58","text":"梁庾肩吾謝赉銅砚筆格啟曰：煙磨青石，已賤孔氏之壇，管撫銅龍，還笑王生之璧，西域胡人，臥織成之金簟，遊仙童子，隱芙蓉之行鄣，莫不併出梁園，來頒狹室。","sortOrder":99},
  {"id":"s_work_nvlt_58_101","chapterId":"ch_work_nvlt_58","text":"太公《金匮》曰：砚之書曰：石墨相著，邪心讒言，無得汙白。","sortOrder":101},
  {"id":"s_work_nvlt_58_102","chapterId":"ch_work_nvlt_58","text":"《漢書》曰：宣帝時，中郎將張彭祖，少與帝微時同席砚書，及帝即位，彭祖以舊恩，封陽都侯，出常參乘。","sortOrder":102},
  {"id":"s_work_nvlt_58_103","chapterId":"ch_work_nvlt_58","text":"又曰：薛宣為左冯翊，性密靜有思，省吏職，求其便安，下至财用筆砚，皆為設方略，利用之，省費，吏民稱之。","sortOrder":103},
  {"id":"s_work_nvlt_58_104","chapterId":"ch_work_nvlt_58","text":"崔寔《四民月令》曰：正月砚冻釋，命童幼入小學篇章，十一月砚冻，幼童讀孝經論語。","sortOrder":104},
  {"id":"s_work_nvlt_58_105","chapterId":"ch_work_nvlt_58","text":"《東觀漢記》曰：蘇竟與劉歆子恭書雲，前世以磨研編簡之才，與國右史［○右史二字衍。］公從事出入。","sortOrder":105},
  {"id":"s_work_nvlt_58_106","chapterId":"ch_work_nvlt_58","text":"魏武帝上雜物疏曰：御物有純銀參帶台砚一枚，純銀參帶員砚，大小各一枚。","sortOrder":106},
  {"id":"s_work_nvlt_58_107","chapterId":"ch_work_nvlt_58","text":"《陳留志》曰：范乔年兩歲，祖父馨卒，臨終，撫其手曰：恨不見汝成人，以吾所用砚與之，始五歲，祖母以此言告乔，乔便執砚涕泣。","sortOrder":107},
  {"id":"s_work_nvlt_58_108","chapterId":"ch_work_nvlt_58","text":"《東宮舊事》曰：皇太子初拜，給漆石砚一枚。","sortOrder":108},
  {"id":"s_work_nvlt_58_109","chapterId":"ch_work_nvlt_58","text":"陆雲與兄機書曰：君苗能作文，見兄文，辄雲欲燒筆砚。","sortOrder":109},
  {"id":"s_work_nvlt_58_110","chapterId":"ch_work_nvlt_58","text":"《從征記》曰：夫子床前有石砚一枚，作甚古朴，蓋孔子生平時物也。","sortOrder":110},
  {"id":"s_work_nvlt_58_111","chapterId":"ch_work_nvlt_58","text":"【賦】晉傅玄砚賦曰：采陰山之潛朴，簡眾材之攸宜，節方圓以定形，鍛金鐵以為池，設上下之剖判，配法象乎二儀，木貴其能软，石美其润堅，加采漆之膠固，含冲德之清玄。","sortOrder":111},
  {"id":"s_work_nvlt_58_112","chapterId":"ch_work_nvlt_58","text":"【贊】魏繁钦贊曰：班采散色，漚润毫芒，點黛文字，曜明典章，施而不德，吐惠無疆，漸渍甘液，吸受流芳。","sortOrder":112},
  {"id":"s_work_nvlt_58_113","chapterId":"ch_work_nvlt_58","text":"【銘】魏王粲砚銘曰：昔在皇頡，爰初書契，以代結繩，民察官理，庶績誕興，在世季末，華藻流淫，文不寫行，書不盡心，淳朴浇散，俗以崩沉，墨運翰藻，榮辱是若，念茲在茲，惟玄是宅，梁武帝砚銘。","sortOrder":113},
  {"id":"s_work_nvlt_58_114","chapterId":"ch_work_nvlt_58","text":"音橫德寫","sortOrder":114},
  {"id":"s_work_nvlt_58_115","chapterId":"ch_work_nvlt_58","text":"假墨圖心","sortOrder":115},
  {"id":"s_work_nvlt_58_116","chapterId":"ch_work_nvlt_58","text":"梁丘遲砚銘。","sortOrder":116},
  {"id":"s_work_nvlt_58_117","chapterId":"ch_work_nvlt_58","text":"圖水平","sortOrder":117},
  {"id":"s_work_nvlt_58_119","chapterId":"ch_work_nvlt_58","text":"壁─┼─跡","sortOrder":119},
  {"id":"s_work_nvlt_58_121","chapterId":"ch_work_nvlt_58","text":"明理宣","sortOrder":121},
  {"id":"s_work_nvlt_58_122","chapterId":"ch_work_nvlt_58","text":"《藝文類聚》　唐·欧陽詢","sortOrder":122},
  {"id":"s_work_nvlt_59_1","chapterId":"ch_work_nvlt_59","text":"卷五十九武部","sortOrder":1},
  {"id":"s_work_nvlt_59_2","chapterId":"ch_work_nvlt_59","text":"○將帥戰伐","sortOrder":2},
  {"id":"s_work_nvlt_59_3","chapterId":"ch_work_nvlt_59","text":"◇將帥","sortOrder":3},
  {"id":"s_work_nvlt_59_4","chapterId":"ch_work_nvlt_59","text":"《春秋元命苞》曰：上天一星為郎將。","sortOrder":4},
  {"id":"s_work_nvlt_59_5","chapterId":"ch_work_nvlt_59","text":"《六韜》曰：將冬不服裘，夏不操扇，天雨不張蓋，出隘塞，犯泥涂，將必下步，士卒皆定，將乃就舍，炊者皆飽，將乃敢食。","sortOrder":5},
  {"id":"s_work_nvlt_59_6","chapterId":"ch_work_nvlt_59","text":"《左傳》曰：晉侯之弟楊幹，亂行於曲梁，魏絳戮其仆，《周官》曰：凡製軍，萬有二千五百人為軍，王六軍，大國三軍，次國二軍，小國一軍。","sortOrder":6},
  {"id":"s_work_nvlt_59_7","chapterId":"ch_work_nvlt_59","text":"《史記》曰：魏文侯問，吳起何如人，李克曰：其用兵，司馬穰苴弗能過也，於是魏文侯以為將，击秦，拔五城。","sortOrder":7},
  {"id":"s_work_nvlt_59_8","chapterId":"ch_work_nvlt_59","text":"又曰：齊景公召穰苴，與語兵事，大說之，以為將軍，穰苴曰：原得君之寵臣，國中所尊，以臨軍，乃可，於是景公使莊贾往，穰苴與約會，日中於軍門，穰苴先馳至軍，立表下漏，待贾，暮時，莊贾乃至，召軍正問曰：軍法期而後者雲何，曰：當斬，斬莊贾，以徇三軍，三軍之士皆震。","sortOrder":8},
  {"id":"s_work_nvlt_59_9","chapterId":"ch_work_nvlt_59","text":"又曰：吳起之為將，與士卒最下者同衣食，臥不設席，行不騎乘，親羸糧與士卒分勞。","sortOrder":9},
  {"id":"s_work_nvlt_59_10","chapterId":"ch_work_nvlt_59","text":"又曰：文帝六年，匈奴大入邊，乃以宗正劉禮為將軍，軍灞上，祝茲侯徐厲，軍棘門，以河內守周亚夫為將軍，軍細柳，帝自勞軍，至灞上及棘門軍，直馳入，將軍下騎送迎，已而之細柳軍，士吏被甲，彀弓持滿，先驅至，不得入，驅曰：天子且至，軍門都尉曰：軍中但聞將軍令，不聞天子詔，於是上使詔軍將，亚夫乃傳言开壁，壁开，士吏曰：軍中不得驅馳，於是天子乃按辔徐行，將軍亚夫，將兵揖曰：介胄之士不拜，請以軍禮見，天子為動色改容，使人稱皇帝敬勞將軍，成禮而去，既出軍門，文帝曰：此真將軍矣，曩者灞上棘門軍，兒戲爾，其將固可袭而虜也，至亚夫，可得而犯耶，稱善久之。","sortOrder":10},
  {"id":"s_work_nvlt_59_11","chapterId":"ch_work_nvlt_59","text":"孫子曰：凡用兵之法，將受令於君，涂有所不由，軍有所不击，城有所不攻，地有所不爭，君命有所不受，故將通於九变之利者，知用兵矣。","sortOrder":11},
  {"id":"s_work_nvlt_59_12","chapterId":"ch_work_nvlt_59","text":"《韓子》曰：吳起為魏將，而攻中山，軍人有病疽者，吳起自吮其脓，傷者母立而泣，人曰：將軍於若子如是，何為泣乎，對曰：吳子吮其父之傷，而殺之涇水之上，今安知不殺是子乎。","sortOrder":12},
  {"id":"s_work_nvlt_59_13","chapterId":"ch_work_nvlt_59","text":"黃石公三略曰：良將之軍也，恕己治人，推惠施恩，士力日新，戰如風發，攻如河决。","sortOrder":13},
  {"id":"s_work_nvlt_59_14","chapterId":"ch_work_nvlt_59","text":"軍讖曰：軍無财，士不來，軍無賞，士不往，故良餌之下有懸魚，重賞之下有勇夫。","sortOrder":14},
  {"id":"s_work_nvlt_59_15","chapterId":"ch_work_nvlt_59","text":"《淮南子》曰：凡國有難，君自宮召將，詔之曰：社稷之命將［《太平御覽》二百七十四將上有在字，此脱。］軍身，今國有難，原子將而應之，主親操鉞授將軍曰：此上至天者，將軍製之，辭而行，乃爪鬋，設明衣，凿凶門而出，乘將軍，［御覽軍下有車字。］建鼓旗，載斧鉞，臨敵攻戰而領，［御覽作不顧二字。］必死無有二心。","sortOrder":15},
  {"id":"s_work_nvlt_59_16","chapterId":"ch_work_nvlt_59","text":"《列女傳》曰：楚子反攻秦軍，絕糧，使人請於王，因問其母，母問使者曰：士卒無恙乎，使者曰：士卒分菽粒而食之。又問將軍無恙乎，對曰：將軍朝夕刍豢黍粱，子反破秦軍而歸，母閉門不內，使數之曰：子不聞越王句踐之伐吳耶，客有獻醇酒一器者，王使人註上流，使士卒飲下流，味不加喙而卒戰自五也，異日又有獻一囊糧者，王又使以賜軍士，分而食之，甘不逾嗌而戰自十也，今士卒分菽粒而食之，子獨朝夕刍豢何也。","sortOrder":16},
  {"id":"s_work_nvlt_59_17","chapterId":"ch_work_nvlt_59","text":"《漢書》曰：韓信亡，萧何追還，漢王曰：以為大將，何曰：王素慢無禮，今拜大將，如召小兒，此乃信所以去也，王必欲拜之，宜擇日斋戒，設壇場，具禮乃可，王許之，諸將皆喜，人人各自以為得大將，至拜，乃韓信也，一軍皆驚。","sortOrder":17},
  {"id":"s_work_nvlt_59_18","chapterId":"ch_work_nvlt_59","text":"又曰：冯唐對文帝曰：天下之將，獨有廉頗李牧耳，上曰：嗟乎，吾獨不得廉頗李牧為將，唐對曰：臣聞上古王者遣將也，跪而推轂曰：闑以內，寡人製之，闑以外，將軍製之，軍功爵賞，皆决於外。","sortOrder":18},
  {"id":"s_work_nvlt_59_19","chapterId":"ch_work_nvlt_59","text":"又曰：霍去病為驃騎將軍，為人少言有氣，上嘗欲教之孫吳兵法，對曰：顧方略何如爾，不至學古兵法，上為治第，令视之，對曰：匈奴不滅，無以家為。","sortOrder":19},
  {"id":"s_work_nvlt_59_20","chapterId":"ch_work_nvlt_59","text":"又曰：西羌反，時趙充國年七十餘，上老之，使問誰可將者，充國對曰：無逾於老臣者矣，上遣焉。","sortOrder":20},
  {"id":"s_work_nvlt_59_21","chapterId":"ch_work_nvlt_59","text":"《東觀漢記》曰：吳漢當出師，朝受詔，夕即引道，初無辦嚴之日，故能常任職，以功名終。","sortOrder":21},
  {"id":"s_work_nvlt_59_22","chapterId":"ch_work_nvlt_59","text":"又曰：赤眉入長安，邓禹乘勝獨克，而師行有紀，皆望風相携以迎降者，以千數，眾號百萬。","sortOrder":22},
  {"id":"s_work_nvlt_59_23","chapterId":"ch_work_nvlt_59","text":"又曰：武威將軍劉尚，击武陵五溪蠻夷，深入軍没，馬援因复請行，時年六十二，帝愍其老，未許之，援自請曰：臣尚能被甲，帝令试之，援據鞍顧眄，以示可用，帝笑曰：矍鑠哉是翁也，遂遣援。","sortOrder":23},
  {"id":"s_work_nvlt_59_24","chapterId":"ch_work_nvlt_59","text":"又曰：祭遵為將軍，取士皆用儒術，對酒設樂，必雅歌投壶，在軍旅，不忘俎豆，［事具巧藝部投壶篇。］","sortOrder":24},
  {"id":"s_work_nvlt_59_25","chapterId":"ch_work_nvlt_59","text":"《魏志》曰：曹仁，字子孝，少時不脩行檢，及長為將，嚴整奉法，常置科於左右，案以從事。","sortOrder":25},
  {"id":"s_work_nvlt_59_26","chapterId":"ch_work_nvlt_59","text":"又曰：贾逵，字梁道，自為兒童戲弄，常設部伍，祖父習異之曰：汝大必為將帥，口授兵法數萬言。","sortOrder":26},
  {"id":"s_work_nvlt_59_27","chapterId":"ch_work_nvlt_59","text":"又曰：庞德讨關羽，親與羽交戰，射羽中額，時德常乘白馬，羽軍謂之白馬將。","sortOrder":27},
  {"id":"s_work_nvlt_59_28","chapterId":"ch_work_nvlt_59","text":"《蜀志》曰：邓艾為大將，三十餘年，賞罰明，善恤卒伍，身之衣食，資仰於官，不為苟素俭，然終不治私，妻子不免飢寒。","sortOrder":28},
  {"id":"s_work_nvlt_59_29","chapterId":"ch_work_nvlt_59","text":"《吳書》曰：魯肅為人節俭，不務俗好，治軍整頓，禁令必行，在軍陣，手不釋書。又善談論，能屬文辭，有過人之明，周瑜之後，肅為之冠。","sortOrder":29},
  {"id":"s_work_nvlt_59_30","chapterId":"ch_work_nvlt_59","text":"《抱朴子》曰：大將民之司命，社稷存亡，於是乎在。","sortOrder":30},
  {"id":"s_work_nvlt_59_31","chapterId":"ch_work_nvlt_59","text":"【詩】晉張華命將出征詩曰：重華隆帝道，戎蠻或來賓，徐夷興有周，鬼方亦违殷，今在盛明世，寇虐動西垠，单醪豈無味，挟纊感至仁。","sortOrder":31},
  {"id":"s_work_nvlt_59_32","chapterId":"ch_work_nvlt_59","text":"梁吳筠古意詩曰：匈奴數欲盡，仆在玉門關，莲花穿劍鍔，秋月掩刀環，春機思窈窕，夏鳥鳴綿蠻，中人坐相望，狂夫終不還。","sortOrder":32},
  {"id":"s_work_nvlt_59_33","chapterId":"ch_work_nvlt_59","text":"又邊城將詩曰：塞外何紛紛，胡騎欲成群，爾時始應募，來投霍冠軍，刀含四尺影，劍抱七星文，袖間血洒地，車中旌拂雲，輕軀如未殯，終當厚報君。","sortOrder":33},
  {"id":"s_work_nvlt_59_34","chapterId":"ch_work_nvlt_59","text":"又邊城將詩曰：仆本邊城將，馳射靈關下，箭衔雁門石，氣振武安瓦，勋輕賞發兵，名高拜橫野，留書應凿楹，傳功須勒社，徒傾七尺命，酬恩終自寡。","sortOrder":34},
  {"id":"s_work_nvlt_59_35","chapterId":"ch_work_nvlt_59","text":"又邊城詩曰：聞君報一餐，遠送出平野，玉摽丹霞劍，金絡艳光馬，高旗入漢飛，長鞭匿地寫，曙星海中出，晓月山頭下，歲晏坐論功，自有思臣者。","sortOrder":35},
  {"id":"s_work_nvlt_59_36","chapterId":"ch_work_nvlt_59","text":"又邊城詩曰：臨淄重蹴踘，西城好击刺，不要身後名，专騁眼前智，君看班定遠，立功不負義，掣拽二丈旗，踯躅双凫騎，但問相知否，死生無险易。","sortOrder":36},
  {"id":"s_work_nvlt_59_37","chapterId":"ch_work_nvlt_59","text":"【贊】晉孫楚白起贊曰：烈烈桓桓，時維武安，神機電斷，氣濟師然，南折劲楚，走魏禽韓，北摧馬服，凌川成丹，應侯無良，蘇子入關，噭々讒口，火燎於原，遂焚杜郵，與萧俱燔，惟其没矣，古今所叹。","sortOrder":37},
  {"id":"s_work_nvlt_59_38","chapterId":"ch_work_nvlt_59","text":"又韓信贊曰：淮陰屈節，盤於幽賤，秦失其鹿，英雄交戰，踐楚知亡，撫戈從漢，遂寤明主，超然虎奋，威震趙魏，擒項平難，割據山川，稱孤南面，惜哉遘疑，一朝書叛。","sortOrder":38},
  {"id":"s_work_nvlt_59_39","chapterId":"ch_work_nvlt_59","text":"又樂毅贊曰：樂生誕節，寔立弘度，丹旄電麾，秦韓景附，威震濟西，齊愍失據，惠之不敏，翻然高翥，栖遲一丘，以保皓素。","sortOrder":39},
  {"id":"s_work_nvlt_59_40","chapterId":"ch_work_nvlt_59","text":"【表】後魏溫子昇廣陽王北征請大將表曰：今四郊多壘，三軍申發，率土之濱，莫敢寧晏，况忝末屬，复董元戎，臣不盡心，誰將竭力，豈容飾讓，苟违戎重，但以軍旅之事，實所未學，求得重將，隨方指麾，臣請先驅，被堅督戰，若使旗鼓相望，埃尘相接，决機兩陣之間，不辭萬死之地，脱獨委臣，专總戎旅，兵術靡常，軍機屢变，以臣當之，必所未達，雖奉廣筭，有均膠柱。","sortOrder":40},
  {"id":"s_work_nvlt_59_41","chapterId":"ch_work_nvlt_59","text":"【論】魏何晏韓白論曰：此兩將者，殆蚩尤之敵對，开辟所希有也，何者勝，或曰：白起功多，前史以為出奇無窮，欲窥沧海，白起為勝，若夫韓信，斷幡以覆軍，拔旗以流血，其以取勝，非复人力也，亦可謂奇之又奇者哉，白起破趙軍，诈奔而斷其糧道，取勝之術，皆此類也，所謂可奇於不奇之間矣，安得比其奇之又奇者哉。","sortOrder":41},
  {"id":"s_work_nvlt_59_42","chapterId":"ch_work_nvlt_59","text":"宋范晔二十八將論曰：二十八將者，前世所為上應二十八宿，未之詳也，然鹹能感會風雲，奋其智勇，議者多非光武，不以功臣任職，至使英姿茂績，委而勿用，然原夫良圖遠筭，固將有以焉爾，若乃王道既衰，降及霸德，猶能受授惟庸，勋賢兼序，如管隰之迭升桓世，先趙之同列文朝，可謂兼通矣，降自秦漢，世資戰力，至於翼夫王運，皆武人屈起，亦有鬻繒盜狗，輕猾之徒，或崇以連城之賞。或任以阿衡之地，故势疑則隙生，力侔則亂起，萧樊且猶缧绁，信越終見菹戮，不其然乎，因茲以降，迄於孝武，宰辅五世，莫非公侯，遂使搢紳道塞，賢能蔽擁，故光武監前事之违，存矯枉之志，雖寇邓之高勋，耿贾之鸿烈，分土不過大縣數四，所加特進朝請而已，觀其治平臨政，課職责咎，將謂导之以法，齊之以刑者乎，永平中，顯宗追感前世功臣，乃圖畫二十八將於南宮雲台，其外又有王常李通窦融卓茂，合三十二人，叙其本第，系之篇末。","sortOrder":42},
  {"id":"s_work_nvlt_59_43","chapterId":"ch_work_nvlt_59","text":"◇戰伐","sortOrder":43},
  {"id":"s_work_nvlt_59_44","chapterId":"ch_work_nvlt_59","text":"《尚書大傳》曰：戰者，憚驚之也。","sortOrder":44},
  {"id":"s_work_nvlt_59_45","chapterId":"ch_work_nvlt_59","text":"《春秋說題辭》曰：伐人者，國內行威，有所斬坏，伐之為言败也。","sortOrder":45},
  {"id":"s_work_nvlt_59_46","chapterId":"ch_work_nvlt_59","text":"太公《金匮》曰：武王伐殷，丁侯不朝，尚父乃畫丁侯射之，丁侯病，遣使請臣，尚父乃以甲乙日拔其頭箭，丙丁日拔目箭，戊己日拔腹箭，庚辛日拔股箭，壬癸日拔足箭，丁侯病乃愈，四夷聞乃懼，越裳氏獻白雉。","sortOrder":46},
  {"id":"s_work_nvlt_59_47","chapterId":"ch_work_nvlt_59","text":"《尚書》曰：今予發，惟恭行天之罰，今日之事，弗愆於六步七步，乃止齊焉，夫子勖哉，弗愆於四伐五伐，六伐七伐，乃止齊焉。","sortOrder":47},
  {"id":"s_work_nvlt_59_48","chapterId":"ch_work_nvlt_59","text":"又曰：帝曰：咨禹，惟茲有苗弗率，汝徂征，禹乃會群後，誓於師曰：濟濟有眾，鹹聽朕命，蠢茲有苗，昏迷不恭，侮慢自賢，反道败德，君子在野，小人在位，民弃不保，天降之咎，肆予以爾眾士，奉辭伐罪。","sortOrder":48},
  {"id":"s_work_nvlt_59_49","chapterId":"ch_work_nvlt_59","text":"《禮記》曰：天子將出征，類乎上帝，宜乎社，造乎祢，禡於所征之地。","sortOrder":49},
  {"id":"s_work_nvlt_59_50","chapterId":"ch_work_nvlt_59","text":"《大戴禮》曰：明主之所征也，誅其君，改其政，率其民而不奪其财也，故曰：明主之征也，猶時雨也，至則民悅矣。","sortOrder":50},
  {"id":"s_work_nvlt_59_51","chapterId":"ch_work_nvlt_59","text":"《左傳》曰：衛大旱，甯《莊子》曰：周飢，克殷而年丰，天其或者欲使衛讨邢乎，從之，師興而雨，［事具天部雨篇。］","sortOrder":51},
  {"id":"s_work_nvlt_59_52","chapterId":"ch_work_nvlt_59","text":"又曰：晉侯复假道於虞以伐虢，宮之奇諫曰：虢，虞之表也，虢亡，虞必從之，諺所謂辅車相依，唇亡齒寒，虞虢之謂也，虞公不聽，後遂為晉所滅。","sortOrder":52},
  {"id":"s_work_nvlt_59_53","chapterId":"ch_work_nvlt_59","text":"春秋佐易［《太平御覽》三百三十九作助。］期曰：太尉主甲卒神，名辯會，曰库兵動，鼓自鳴，得諸侯象也。","sortOrder":53},
  {"id":"s_work_nvlt_59_54","chapterId":"ch_work_nvlt_59","text":"《管子》曰：桓公北伐山戎，以升布天下。","sortOrder":54},
  {"id":"s_work_nvlt_59_55","chapterId":"ch_work_nvlt_59","text":"又曰：桓公北伐孤竹，未至卑耳之谿十里，援弓而射，未敢發也，謂左右曰：見前人乎，對曰：不見，公曰：寡人見人長尺，而人物具焉，冠冠，右袪衣，馬前疾走，寡人其不濟乎，管仲曰：袪衣示前有水也，右示涉也，至卑耳之谿，從左涉，深及冠，從右涉，方深至膝，已涉大濟，公拜曰：仲父之聖若此也。","sortOrder":55},
  {"id":"s_work_nvlt_59_56","chapterId":"ch_work_nvlt_59","text":"又曰：代出狐白皮，狐應陽之变，六月而一見，公貴買之，代人臣難得，喜其貴价，必相率而求之，令齊載金錢之代穀，求狐白皮，代王聞之，果去其農，處山林求狐，二十四月，不得一狸皮，齊聞而伐之，代王即將其國士卒服於齊，［事具獸部四狐屬篇。］","sortOrder":56},
  {"id":"s_work_nvlt_59_57","chapterId":"ch_work_nvlt_59","text":"《韓子》曰：秦穆公以女樂三人遺戎王，戎王大悅，聽樂終歲不還，舉兵伐之，开地千里。","sortOrder":57},
  {"id":"s_work_nvlt_59_58","chapterId":"ch_work_nvlt_59","text":"《史記》曰：樂毅併獲趙楚韓魏燕之兵，以伐齊，破之，追至於臨淄，齊惛王走保於莒，樂毅獨留徇齊，攻臨淄，盡取齊寶财物祭器输之燕，昭王大悅，親至濟上勞軍，行賞饗士，封毅於昌國，號為昌國君。","sortOrder":58},
  {"id":"s_work_nvlt_59_59","chapterId":"ch_work_nvlt_59","text":"《韓詩外傳》曰：武王伐紂，到邢丘，軛折為三，天雨三日不休，武王懼，召太公而問之曰：紂未可伐乎，太公曰：不然，軛折為三者，軍當分介為三也，天雨三日者，欲洒吾兵也。","sortOrder":59},
  {"id":"s_work_nvlt_59_60","chapterId":"ch_work_nvlt_59","text":"《淮南子》曰：人有伐國之志，雄雞夜鳴，库兵動而戎馬驚。","sortOrder":60},
  {"id":"s_work_nvlt_59_61","chapterId":"ch_work_nvlt_59","text":"《漢書》曰：武帝末年，悔伐之事，乃封丞相為富民侯。","sortOrder":61},
  {"id":"s_work_nvlt_59_62","chapterId":"ch_work_nvlt_59","text":"又曰：武王［按當作帝。］南伐越，以牡荆曰：［漢書郊祀志作畫。］北升［漢書作斗。］登龍，以象天［漢書作太。］一，命曰靈旗，以指所伐。","sortOrder":62},
  {"id":"s_work_nvlt_59_63","chapterId":"ch_work_nvlt_59","text":"《論衡》曰：太公陰謀書，武王伐殷，兵至牧野，晨舉脂燭，推掩不備。","sortOrder":63},
  {"id":"s_work_nvlt_59_64","chapterId":"ch_work_nvlt_59","text":"《魏志》曰：景元四年，邓艾伐蜀，自陰平，行無人之地七佰餘里，凿山通道，作桥閣，山高穀深，至有艱险，艾以旗自裹，推轉而下，將士皆攀木緣崖，魚貫而進。","sortOrder":64},
  {"id":"s_work_nvlt_59_65","chapterId":"ch_work_nvlt_59","text":"挚虞新禮議曰：漢魏故事，遣將出征，符節郎授鉞於朝堂，新禮遣將，御臨軒，尚書授節鉞，古兵書跪而推轂之義也。","sortOrder":65},
  {"id":"s_work_nvlt_59_66","chapterId":"ch_work_nvlt_59","text":"挚虞决疑要註曰：古者帝王，征以齊車，載遷廟之主以行，故尚書甘誓曰：用命賞於祖，不用命戮於社。","sortOrder":66},
  {"id":"s_work_nvlt_59_67","chapterId":"ch_work_nvlt_59","text":"王隱《晉書》曰：鹹康元年，督護王隨，領三千人，讨寧州賊，吹三角皆裂，軍人惡之，隨曰：裂者破也，當破賊而得土地也。","sortOrder":67},
  {"id":"s_work_nvlt_59_68","chapterId":"ch_work_nvlt_59","text":"【詩】後漢崔骃安封侯詩曰：戎馬鳴兮金鼓震，壮士激兮忘身命，破光甲兮跨良馬，揮長戟兮廓強弩。","sortOrder":68},
  {"id":"s_work_nvlt_59_69","chapterId":"ch_work_nvlt_59","text":"魏文帝於黎陽作詩曰：千騎隨風靡，萬騎正龍驤，金鼓震上下，幹戚紛縱橫，白旄若素霓，丹旗發朱光，追思大王德，胥宇識足臧，經歷萬歲林，行行到黎陽。","sortOrder":69},
  {"id":"s_work_nvlt_59_70","chapterId":"ch_work_nvlt_59","text":"又詩曰：朝發鄰［按當作鄴。］城，夕宿韓陵，霖雨讖涂，與人困窮，載馳載驅，沐雨櫛風，舍我高殿，何為泥中，在昔周武，爰暨公旦，載主而征，救民涂炭，彼此一時，唯天所贊，我獨何人，餘不靜亂。","sortOrder":70},
  {"id":"s_work_nvlt_59_71","chapterId":"ch_work_nvlt_59","text":"又詩曰：殷殷其雷，濛濛其雨，我徒我車，涉此艱阻，遵彼洹湄，言刈其楚，班之中路，涂潦是御，辚辚大車，載低載昂，嗷嗷仆夫，載仆載僵，蒙涂冒雨，霑衣濡裳。","sortOrder":71},
  {"id":"s_work_nvlt_59_72","chapterId":"ch_work_nvlt_59","text":"又詩曰：奉辭罰罪遐征，晨過黎山〈山完〉峥，東濟黃河金營，北觀故宅頓傾，中有高樓亭亭，荆棘繞蕃丛生，南望果園青青，霜露惨凄宵零，彼桑梓兮傷情。","sortOrder":72},
  {"id":"s_work_nvlt_59_73","chapterId":"ch_work_nvlt_59","text":"又至廣陵於馬上作詩曰：觀兵臨江水，水流何湯湯，霜矛成山林，玄甲曜日光，誰雲江水廣，一苇可以航，不戰屈敵虜，兵記稱賢良。","sortOrder":73},
  {"id":"s_work_nvlt_59_74","chapterId":"ch_work_nvlt_59","text":"魏王粲從軍詩曰：從軍有苦樂，但問所從誰，所從神且武，焉得久勞師，相公征關右，赫怒震天威，軍中多飫饒，人馬皆溢肥，徒行兼乘還，空出有餘資，拓地三千里，往反速若飛，歌舞入鄴城，所原獲無违。","sortOrder":74},
  {"id":"s_work_nvlt_59_75","chapterId":"ch_work_nvlt_59","text":"又從軍詩曰：原風厲秋節，司典告詳刑，我君順時發，桓桓東南征，汎舟蓋長川，陳卒被隰坰，征夫懷親戚，誰能無此情，哀彼東山人，喟然感鸛鳴。","sortOrder":75},
  {"id":"s_work_nvlt_59_76","chapterId":"ch_work_nvlt_59","text":"又詩曰：從軍征遐路，讨彼東南夷，方舟順廣川，薄暮未安坻，白日半西山，桑梓有餘暉，蟋蟀夹岸鳴，孤鳥翩翩飛，征夫心兩懷，凄怆令吾悲。","sortOrder":76},
  {"id":"s_work_nvlt_59_77","chapterId":"ch_work_nvlt_59","text":"又詩曰：率彼東南路，將定一舉勋，筹策運帷幄，一由我聖君，限我無時謀，譬諸具官臣，鞠躬中竖內，微畫無所陳，許歷為完士，一言猶败秦，我有素餐责，誠愧伐檀人，雖無鉛刀用，庶幾奋薄身。","sortOrder":77},
  {"id":"s_work_nvlt_59_78","chapterId":"ch_work_nvlt_59","text":"宋文帝北伐詩曰：季文鑒禍先，辛生識機始，崇眷非無徵，興废要有以，自昔論中畿，倏焉盈百祀，不睹南雲陰，但見胡尘起，亂極治方形，涂泰由積否，方欲徐遣氣，矧乃秽邊鄙，眷言悼斯民，納隍良在己，逝將振宏羅，一麾同文軌。","sortOrder":78},
  {"id":"s_work_nvlt_59_79","chapterId":"ch_work_nvlt_59","text":"宋孝武帝北伐詩曰：表里跨原隰，左右御川梁，月羽皎素魄，星旗赩赤光。","sortOrder":79},
  {"id":"s_work_nvlt_59_80","chapterId":"ch_work_nvlt_59","text":"宋謝莊江都平解嚴詩曰：肅旗蘭廟律，耸鉞畅乾靈，朝晏推物泰，通渥抃身寧，击轅歌至世，撫壤頌惟馨。","sortOrder":80},
  {"id":"s_work_nvlt_59_81","chapterId":"ch_work_nvlt_59","text":"又從駕頓上詩曰：中權臨楚路，前茅望吳雲，冀馬依風蹀，邊箫當夜聞。","sortOrder":81},
  {"id":"s_work_nvlt_59_82","chapterId":"ch_work_nvlt_59","text":"宋傅亮從武帝平閩中詩曰：鞠旅扬城，大蒐徐方，旅旌首路，元戎啟行，弭楫洪河，總辔崇芒。","sortOrder":82},
  {"id":"s_work_nvlt_59_83","chapterId":"ch_work_nvlt_59","text":"又從征詩曰：息徒西楚，佇挹舊乡，止猶嶽立，動則雲翔，烈烈群師，星言啟行，汎舟掩河，秣馬登芒。","sortOrder":83},
  {"id":"s_work_nvlt_59_84","chapterId":"ch_work_nvlt_59","text":"齊虞羲霍將軍北伐詩曰：擁旄為漢將，汗馬出長城，長城地势险，萬里與雲平，窮秋八九月，虜騎入幽併，飛狐白日晚，瀚海愁雲生，乘墉揮寶劍，蔽日引高旌，雲屯七萃士，魚麗六郡兵，胡笳關下思，羌笛隴頭鳴，天長地自久，人道有虧盈，未窮激楚樂，已見高台傾。","sortOrder":84},
  {"id":"s_work_nvlt_59_85","chapterId":"ch_work_nvlt_59","text":"齊王融從武帝琅邪城講武應詔詩曰：治兵聞魯策，訓旅見周篇，教民良不弃，任智理恒全，白日映丹羽，赪霞文翠旃，凌山炫組甲，帶衣被戎船，凝葭鬱摧怆，清管乍聯綿，早逢文化洽，复屬武功宣，原陪玉鑾右，一舉扫燕然。","sortOrder":85},
  {"id":"s_work_nvlt_59_86","chapterId":"ch_work_nvlt_59","text":"梁武帝宴詩曰：止殺心自詳，勝殘道未遍，四主漸懷音，九夷稍革面，世治非去兵，國安豈忘戰，釣台聞史籍，歧陽書記傳。","sortOrder":86},
  {"id":"s_work_nvlt_59_87","chapterId":"ch_work_nvlt_59","text":"梁簡文帝和武帝詩曰：校尉开疏勒，將軍定月支，南通新息柱，北屆武陽碑，豫遊戲馬馆，教戰崑明池，銀塘寫清渭，銅鉤引直漪，常從良家子，命中幽併兒，金鞍飾紫珮，玉燕帖青驪，車書今已共，原奏雲亭儀。","sortOrder":87},
  {"id":"s_work_nvlt_59_88","chapterId":"ch_work_nvlt_59","text":"又詩曰：祭壶今息鼓，董案成开帷，聊舉青龍陣，正取絳宮時，犒兵隨後拒，軷祭逐前師，軍門初露節，步陳始分旗。","sortOrder":88},
  {"id":"s_work_nvlt_59_89","chapterId":"ch_work_nvlt_59","text":"梁元帝蕃難未靜述懷詩曰：玉節威雲夢，金鉦韻渚宮，霜戈臨漸白，日羽映流紅，单醪結猛將，芳餌引群雄，箭擁淇園竹，劍聚若溪銅，亟睹周王駿，多逢鮑氏驄，謀出河南贾，威寄隴西冯，溪雲連陣合，却月半山空，樓前飄密柳，井上落疏桐，差營逢霪雨，立壘掛長虹。","sortOrder":89},
  {"id":"s_work_nvlt_59_90","chapterId":"ch_work_nvlt_59","text":"又和王僧辯從軍詩曰：山虛和鐃管，水靜寫樓船，連雞隨火度，燧象帶烽然，洞庭晓風急，瀟湘夜月圓，荀令多文藻，臨戎賦雅篇。","sortOrder":90},
  {"id":"s_work_nvlt_59_91","chapterId":"ch_work_nvlt_59","text":"梁吳筠戰城南詩曰：蹀躞青驪馬，往救城南畿，五歷魚麗陣，三尺九重围，為君意已重，無功終不歸。","sortOrder":91},
  {"id":"s_work_nvlt_59_92","chapterId":"ch_work_nvlt_59","text":"又詩曰：前有濁樽酒，忧思亂紛紛，小來重意氣，學劍不學文，忽值明關靜，匈奴遂兩分，天山已半出，龍城無片雲，漢世平如此，何用李將軍。","sortOrder":92},
  {"id":"s_work_nvlt_59_93","chapterId":"ch_work_nvlt_59","text":"又詩曰：陌上何喧喧，匈奴围塞垣，黑雲藏趙树，黃尘埋隴垠，天子羽書勞，將軍在玉門。","sortOrder":93},
  {"id":"s_work_nvlt_59_94","chapterId":"ch_work_nvlt_59","text":"又詩曰：雜虜冠銅鞮，征役去三齊，扶山翦疏勒，傍海扫沉黎，劍光揮夜電，馬汗晝成泥，何當見天子，畫地取關西。","sortOrder":94},
  {"id":"s_work_nvlt_59_95","chapterId":"ch_work_nvlt_59","text":"又征客詩曰：公卿來怅別，葭聲在狹斜，玉樽浮雲蓋，朱輪流水車，鞚中懸明月，劍杪照莲花。","sortOrder":95},
  {"id":"s_work_nvlt_59_96","chapterId":"ch_work_nvlt_59","text":"梁沈約正陽堂宴勞旋詩曰：凯入同高宴，飲至均多祜，昔往歌采薇，今來歡杕杜，善戰惟我皇，勝之不窥戶，推轂授神謨，餘壮終能贾，浩荡金罍溢，周流玉觴傳。","sortOrder":96},
  {"id":"s_work_nvlt_59_97","chapterId":"ch_work_nvlt_59","text":"又出重围和傅昭詩曰：魯連扬一策，陳平出六奇，邯鄲風雨散，白登煙霧維，排雲出九地，陵定振五卮。","sortOrder":97},
  {"id":"s_work_nvlt_59_98","chapterId":"ch_work_nvlt_59","text":"梁庾肩吾被使從渡江詩曰：八陣引佳兵，三河總舻舳，絳天扬遠旆，雷野驅長轂，夜劍動星芒，秋潮驚箭服。","sortOrder":98},
  {"id":"s_work_nvlt_59_99","chapterId":"ch_work_nvlt_59","text":"梁劉孝義從軍行詩曰：冠軍親俠射，長平自合围，木落彫弓燥，氣秋征馬肥，賢王皆屈膝，幕府复申威，何謂從軍樂，往反速如飛。","sortOrder":99},
  {"id":"s_work_nvlt_59_100","chapterId":"ch_work_nvlt_59","text":"北齊祖孝徵從北征詩曰：翠旗臨塞道，靈鼓出桑乾，祁山斂雰霧，澣海息波澜，戍亭秋雨急，开門朔氣寒，方系单於頸，歌舞入長安。","sortOrder":100},
  {"id":"s_work_nvlt_59_101","chapterId":"ch_work_nvlt_59","text":"北齊裴讓之從北征詩曰：沙漠胡尘起，關山烽燧驚，皇威奋武略，上將總神兵，高台朔風馳，絕野寒雲生，匈奴定遠近，壮士欲橫行。","sortOrder":101},
  {"id":"s_work_nvlt_59_102","chapterId":"ch_work_nvlt_59","text":"周庾信從駕觀講武詩曰：校戰出長扬，兵欄入斗場，置陣橫雲起，开營雁翼張，落星奔骥騄，浮雲上驌骦，急風吹戰鼓，高尘擁具裝，駭猨時落木，驚鸿屢斷行。","sortOrder":102},
  {"id":"s_work_nvlt_59_103","chapterId":"ch_work_nvlt_59","text":"又和平鄴應詔絕句詩曰：天策弘神兵，風飛扫鄴城，陣雲千里散，黃河一代清。","sortOrder":103},
  {"id":"s_work_nvlt_59_104","chapterId":"ch_work_nvlt_59","text":"陳伏知道從軍五更啭五首，詩曰：一更刁斗鳴，校尉逴連城，遙聞射雕騎，懸憚將軍名。","sortOrder":104},
  {"id":"s_work_nvlt_59_105","chapterId":"ch_work_nvlt_59","text":"二更愁未央，高城寒夜長，试將弓學月，聊持劍比霜。","sortOrder":105},
  {"id":"s_work_nvlt_59_106","chapterId":"ch_work_nvlt_59","text":"三更夜驚新，橫吹獨吟春，強聽梅落花，誤憶柳園人。","sortOrder":106},
  {"id":"s_work_nvlt_59_107","chapterId":"ch_work_nvlt_59","text":"四更星漢低，落月與雲齊，依俙北風里，胡笳雜鳥嘶。","sortOrder":107},
  {"id":"s_work_nvlt_59_108","chapterId":"ch_work_nvlt_59","text":"五更催送筹，晓色映山頭，城乌初起堞，更人悄下樓。","sortOrder":108},
  {"id":"s_work_nvlt_59_109","chapterId":"ch_work_nvlt_59","text":"陳蘇子卿南征詩曰：一朝遊桂水，萬里別長安，故乡夢中近，邊愁酒上宽，劍鋒但須利，戎衣不畏单，南中地氣暖，少婦早愁寒。","sortOrder":109},
  {"id":"s_work_nvlt_59_110","chapterId":"ch_work_nvlt_59","text":"陳沈炯從鳴駕送軍詩曰：惟尧稱乃武，軒後號神兵，弔民資智勇，治亂屬師貞，我君膺寶業，歷駕视前英，蒲海方無浪，夷山有未平，星光下結旆，劍氣上舒精，雲开萬里彻，日麗百川明，撫鼓山靈應，詔跸水祇驚。","sortOrder":110},
  {"id":"s_work_nvlt_59_111","chapterId":"ch_work_nvlt_59","text":"陳張正見從軍詩曰：胡兵屯蓟北，漢將起山西，故人輕百戰，聊欲定三齊，風前喷畫角，雲上舞飛梯，雁塞秋聲遠，龍沙雲路迷，燕然自可勒，函穀詎須泥。","sortOrder":111},
  {"id":"s_work_nvlt_59_112","chapterId":"ch_work_nvlt_59","text":"又從軍詩曰：將軍定朔邊，刁斗出祁連，高柳橫長塞，榆關接遠天，井泉含陣竭，烽火映山然，欲知客心斷，旄旌萬里懸。","sortOrder":112},
  {"id":"s_work_nvlt_59_113","chapterId":"ch_work_nvlt_59","text":"【賦】後漢崔骃大將軍西征賦曰：主簿骃言，愚聞昔在上世，義兵所克，工歌其詩，具陳其頌，書之庸器，列在明堂，所以顯武功也，於是袭孟秋而西征，跨雍梁而遠蹤，陟隴阻之峻城，升天梯以高翔，旗旐翼如遊風，羽毛紛其覆雲，金光皓以奪日，武鼓铿而雷震。","sortOrder":113},
  {"id":"s_work_nvlt_59_114","chapterId":"ch_work_nvlt_59","text":"魏文帝述征賦曰：建安之十三年，荆楚傲而弗臣，命元司以簡旅，予原奋武乎南鄴，伐靈鼓之硼隱兮，建長旗之飄飖，曜甲卒之皓旰，馳萬騎之瀏瀏，扬凯悌之丰惠兮，仰乾威之靈武，伊皇衢之遐通兮，維天納［全三國文四作綱。］之畢舉，南野之舊都，［句有脱文。］聊弭節而容與，遵往初之舊跡，順歸風以長邁，镇江漢之遺民，靜南畿之遐裔。","sortOrder":114},
  {"id":"s_work_nvlt_59_115","chapterId":"ch_work_nvlt_59","text":"魏陳王曹植東征賦曰：建安十九年，王師東征吳寇，餘典禁兵，衛官省，然神武一舉，東夷必克，想見振旅之盛，故作賦一篇，登城隅之飛觀兮，望六師之所營，幡旗轉而心思兮，舟楫動而傷情，顧身微而任顯兮，愧责重而命輕，嗟我愁其何為兮，心遙思而懸旌，師旅凭皇穹之靈祐兮，亮元勋之必舉，揮朱旗以東指兮，橫大江而莫御。","sortOrder":115},
  {"id":"s_work_nvlt_59_116","chapterId":"ch_work_nvlt_59","text":"魏應玚撰征賦曰：奋皇佐之丰烈，將親戎乎幽鄰，飛龍以雲曜，披廣路而北巡，崇殿鬱其嵯峨，華宇烂而舒光，摛雲藻之雕飾，流辉采之浑黃，辭曰：烈烈征師，尋遐庭兮，悠悠萬里，臨長城兮，周覽郡邑，思既盈兮，嘉想前哲，遺風聲兮，魏徐幹西征賦曰：奉明辟之渥德，與遊軫而西伐，過京邑以釋駕，觀帝居之舊製，伊吾儕之挺劣，獲載筆而從師，無嘉謀以雲補，徒荷祿而蒙私，非小人之所幸，雖身安而心危，庶區宇之今定，入告成乎後皇，登明堂而飲至，銘功烈乎帝裳。","sortOrder":116},
  {"id":"s_work_nvlt_59_117","chapterId":"ch_work_nvlt_59","text":"又序征賦曰：餘因茲以從邁兮，聊畅目乎所經，觀庶士之缪殊，察風流之濁清，沿江浦以左轉，涉雲夢之無陂，從青冥以極望，上連薄乎天維，刊梗林以廣涂，填沮洳以高蹊，攬循環其萬艘，亘千里之長湄，行兼時而易節，迄玄氣之消微，道蒼神之受謝，逼鶉鳥之將栖，慮前事之既終，亦何為乎久稽，乃振旅以复蹤，溯朔風而北歸，及中區以釋勤，超栖遲而無依。","sortOrder":117},
  {"id":"s_work_nvlt_59_118","chapterId":"ch_work_nvlt_59","text":"魏王粲初征賦曰：违世難以迥折兮，超遙集於蠻楚，逢屯否而底滯兮，忽長幼以羁旅，賴皇華之茂功，清四海之疆宇，超南荆之北境，踐周豫之末畿，野萧條而騁望，路周達而平夷，春風穆其和畅兮，庶卉煥以敷蕤，行中國之舊壤，實吾原之所依，當短景之炎陽，犯隆暑之赫曦，薰風溫溫以增熱，體燁燁其若焚，魏阮瑀紀征賦曰：仰天民之高衢兮，慕在昔之遐軌，希篤聖之崇綱兮，惟弘哲而為紀，同天工而人代兮，匪賢智其能使，五材陳而併序，靜亂由乎幹戈，惟蠻荆之作讎，將治兵而濟河，遂臨河而就濟，瞻禹績之茫茫，距疆泽以潛流，經崑崙之高岡，目幽蒙以廣衍，遂霑濡而難量。","sortOrder":118},
  {"id":"s_work_nvlt_59_119","chapterId":"ch_work_nvlt_59","text":"魏陳琳武軍賦曰：赫赫哉，烈烈矣，於此武軍，當天符之佐運，承斗刚而曜震，漢季世之不辟，青龍紀乎大荒，熊狼競以拏攫，神寶播乎鎬京，於是武臣赫然，颺炎天之隆怒，叫諸夏而號八荒，爾乃擬北落而树表，晞壘壁以結營，百校羅時，千部列陳，弥方城，掩平原，於是啟明戒旦，長庚告昏，火烈具舉，鼓角併震，千徒從唱，亿夫求和，聲訇隱而動山，光赫弈以燭夜，其刃也則楚金越冶，棠谿名工，清堅皓鍔，脩刺銳鋒，陆陷蕊犀，水截輕鸿，鎧則東胡闕巩，百煉精刚，函師振旅，韦人製縫，弩則幽都筋骨，恒山檿幹，通肌畅骨，崇缊曲煙，其弓則乌號越耗，繁弱角端，象弭繡质，哲拊文身，矢則申息肅慎，箘簵空疏，焦銅毒鐵，麗轂撻辀，馬則飛雲絕景，直鬐騧骝，驳龍紫鹿，文的〈足間〉魚，若乃清道整列。按節徐行，龍姿鳳峙，灼有遺英。","sortOrder":119},
  {"id":"s_work_nvlt_59_120","chapterId":"ch_work_nvlt_59","text":"又神武賦曰：建安十有二年，大司空武平侯曹公，東征乌丸，六軍被介，雲辎萬乘，治兵易水，次於北平，可謂神武弈弈，有征無戰者已，佇盤桓以淹次，乃申命而後征，觐狄民之故土，追大晉之遐蹤，惡先縠之懲寇，善魏絳之和戎，受金石而弗伐，蓋禮樂而思終，陵九城而上濟，起齊軌乎玉繩，車軒辚於雷室，騎浮厲乎雲宮，暉曜連乎白日，旂旐繼於電光，旆既軼乎白狼，殿未出乎盧龍，威凌天地，势括十冲，单鼓未伐，虜已潰崩，克俊折馘首，［句有衍文。］枭其魁雄，爾乃總辑朅珍，茵氈幕幄，攘瓔帶佩，不飾彫琢，華璫玉瑤，金麟互琢，文貝紫瑛，縹碧玄绿，黼錦缋組，罽毼皮服。","sortOrder":120},
  {"id":"s_work_nvlt_59_121","chapterId":"ch_work_nvlt_59","text":"魏繁钦征天山賦曰：素甲玄焰，皓旰流光，左骈雄戟，右攒幹將，彤玈朱增。丹羽絳房，望之妒火，焰奪朝陽，華旗翳雲霓，聚刃曜日铓，於是轒辒雲趨，威弧雨發，鉦鼓雷鳴，猛火風烈，躍刃霧散，虜鋒摧折，呼吸無聞，丑類剝滅。","sortOrder":121},
  {"id":"s_work_nvlt_59_122","chapterId":"ch_work_nvlt_59","text":"魏楊脩出征賦曰：嗟夫吳之小夷，負川阻而不廷，肇天子之命公，總九伯而是征，整三軍而飭戒，殄征夫而叛驚，舫翼華以鱗集，蒼鷹雜以星陳，塞川原而上下，敝城隍而無垠，於是州牧覆舟，水衡戒事，飾師就部，乃講乃试，信大海之可橫，焉江河之足忌，公命臨淄，守於鄴都，侯懷大舜，乃號乃謩，茂國事之是勉兮，叹經時而離居，企觀愛之偏處兮，獨搔首於城隅。","sortOrder":122},
  {"id":"s_work_nvlt_59_123","chapterId":"ch_work_nvlt_59","text":"晉陆士龍南征賦曰：大安二年八月，奸臣羊玄之皇甫商，敢行稱亂，大將軍敷命群後，同恤社稷，四方之會，眾以百萬，粵十月，軍次於朝歌，講武治戎，以觀兵於殿墟，桓桓先征，在河之涘，順彼長道，懸旌千里，美王師之遵時，茂七德而發止，爾乃稅駕殷墟，我徒既閒，順時講武，薄狩於原，紛同方而類聚，煥製翼而明分，祗明形以誓眾，習運攻於舊聞，若溟海之引回流，岱靈之吐行雲。","sortOrder":123},
  {"id":"s_work_nvlt_59_124","chapterId":"ch_work_nvlt_59","text":"宋傅亮征思賦曰：逢休明之餘祐，讬菲薄於末暉，既致戎於皇幄，亦彼已於宰闈，傷鹈梁以載扬，詠伐檀而屢思，和風翕以首節，零雨鬱而四漾，津雲暧以合體，墳衍杳其無封，羨歸飛之能矯，樂湍流之自東，想和鑾之北徂，企雲旗之西舉，洒三川之積尘，廓二崤之重阻，觌高掌於華陽，聆鳴鳳於洛浦。","sortOrder":124},
  {"id":"s_work_nvlt_59_125","chapterId":"ch_work_nvlt_59","text":"宋謝靈運撰征賦曰：相國宋公，兵於京甸，次師於汴上，曾不逾月，二方獻捷，天子感東山之劬勞，使臣遵於原隰，餘攝官承乏，谬充殊役，遂寫集聞見，作賦撰征，惟上相之叡哲，當草昧而經纶，總九流以貞觀，协五材而平分，龟筮允臧，人鬼同情，順天行誅，司典詳刑，迅二翼以魚麗，襄兩服而雁逝，陣未列於都甸，威以振於秦蓟，詔微臣以勞問，奉王命於河湄，夕飲餞以俶裝，旦出宿而言辭，冒沉雲之晻藹，迎素雪之紛霏，眷轉蓬之辭根，悼朔雁之起越，彼微物之疚情，此思心而可歇。","sortOrder":125},
  {"id":"s_work_nvlt_59_126","chapterId":"ch_work_nvlt_59","text":"梁沈約悯國賦曰：餘生平之無立，徒跅弛以自閒，處围城之惵惵，得無用於行間，對僚友而不怡，鹹悄顏而相顧，畏高冲之比擬，壮激矢之南度，駭潛師之夜過，驚躍馬之晨呼，矛森森而密竖，旗落落而疏布，時難紛其未已，歲功迫其將徂，育素虮於玄胄，垂葆發於缦胡。","sortOrder":126},
  {"id":"s_work_nvlt_59_127","chapterId":"ch_work_nvlt_59","text":"【頌】漢楊雄趙充國頌曰：明靈惟宣，戎有先零，先零猖狂，侵漢西疆，既臨其域，喻以威德，有守矜功，謂之弗剋，請奋其旅，於罕之羌，天子命我，從之鮮陽，營平守節，屢奏封章，料敵製勝，威謀靡亢，遂剋西戎，還師於京，鬼方賓服，罔有不庭。","sortOrder":127},
  {"id":"s_work_nvlt_59_128","chapterId":"ch_work_nvlt_59","text":"漢史岑出師頌曰：茫茫上天，降祚有漢，兆基开業，人神攸贊，五曜宵映，素靈夜叹，昔在孟津，惟師尚父，素旄一麾，混齊天宇，蒼生更始，朔風变楚，我出我師，於彼四疆，天子餞我，辂車乘黃，言念伯舅，恩深渭陽。","sortOrder":128},
  {"id":"s_work_nvlt_59_129","chapterId":"ch_work_nvlt_59","text":"後漢班固窦將軍北征頌曰：於是雷震九里，電曜高闕，金光鏡野，武旗冒日，雲黯長霓，鹿走黃碛，輕選四縱，所從英敵。","sortOrder":129},
  {"id":"s_work_nvlt_59_130","chapterId":"ch_work_nvlt_59","text":"後漢傅毅窦將軍北征頌曰：建［全後漢文四十三作逮。］漢祖之龍興，荷天符而用師，曜神武於幽冀，遇白登之重围，何獯鬻之桀虐，自上世而不羁，哀昏戾之習性，阻廣漢之荒垂，命窦侯之征讨，躡衛霍之遺風，奉聖皇之明策，奋無前之嚴鋒，采伊吾之城壁，蹈天山而遙降，曝名烈於禹跡，奉旗鼓而來旋，聖上嘉而裒寵，典禁旅之戎兵，內雍容以詢謨，外折冲於無形，惟倜傥以弘遠，委精慮於朝廷。","sortOrder":130},
  {"id":"s_work_nvlt_59_131","chapterId":"ch_work_nvlt_59","text":"晉張載平吳頌曰：聞之前志，尧有丹水之陣，舜有三苗之誅，此聖帝明王，平暴靜亂，未有不用兵而製之也，夫太上成功，非頌不顯，情動於中，非言不彰，獫玁既攘，出車以興，淮夷既平，江漢用作，斯故先典之明志，不刊之美事，乌可闕欤，遂作頌曰：上哉仁聖，曰惟皇晉，光泽四表，繼天垂胤，帝道煥於唐尧，義聲邈乎虞舜，蠢爾鯨吳，凭山阻水，肆虐播毒，而作豺虺，菁茅闕而不貢，越裳替其白雉，正九伐之明典，申號令之舊章，布亘地之長羅，振天網之脩綱，製征期於一朝，併箕驅而慕張，爾乃拔丹陽之峻壁，屠西陵之高墉，日不移晷，群丑率從，望會稽而振铎，臨吳地而奋旅，眾軍競趣，烽飆具舉，挫其輕銳，走其守御。","sortOrder":131},
  {"id":"s_work_nvlt_59_132","chapterId":"ch_work_nvlt_59","text":"【表】北齊邢子才百官贺平石頭表曰：大江設隘，實限夷華，前魏觀涛而退，後魏登山而反，聲教不通，多歷年代，今蒼雉奉職，靈鼍自梁，折苇為舟，凭刀可渡，始知德通於物，孟門失险，道清將順，劍閣自开，行舉洞庭之樂，放畜長洲之苑，會玉帛於涂山，树桐柱於南極。","sortOrder":132},
  {"id":"s_work_nvlt_59_133","chapterId":"ch_work_nvlt_59","text":"梁劉孝儀臨川王奉詔班師表曰：臣自受服廟堂，申威塞表，既驅熊羆之眾，兼禀帷幄之謀，登濟河山，夷滅趙魏，將系轵在之頸，且屈渭桥之膝，而玄陰屆節，祁寒方始，降此慈弘，愍茲介胄，使燕然之石，原勒而不刊，函穀之士，［○疑當作土。］將封而莫遂，雖荷杕杜之恩，終慚采薇之旨。","sortOrder":133},
  {"id":"s_work_nvlt_59_134","chapterId":"ch_work_nvlt_59","text":"周庾信慶平鄴表曰：臣聞太山梁甫以來，即有七十二代，龍圖龟書之後。又已三千餘年，雖复製法树司，禮殊樂異，至於天篱武落，剡木絃弧，席卷天下之心，苞吞八荒之志，其揆一焉，政須東南一尉，立於北景之南，西北一候，置於交河之北。","sortOrder":134},
  {"id":"s_work_nvlt_59_135","chapterId":"ch_work_nvlt_59","text":"【啟】齊王融答敕撰漢武北伐圖賦啟曰：臣聞情蓄自中，事符則感，象構於始，機動斯彰，但九祀一逢，休明難再，常原待詔朱闕，俯對青蒲，澄瀚海之恒流，扫狼山之積霧，系单於之頸，屈左賢之膝，然後天移雲動，升封岱宗，减五登三，追蹤七十。","sortOrder":135},
  {"id":"s_work_nvlt_59_136","chapterId":"ch_work_nvlt_59","text":"又勸高帝北伐啟曰：雖窮鳥必啄，固等命於良鶉，困獸斯驚，終併懸於厨鹿，若籍巫漢之歸師，騁士卒之餘憤，取函河如反掌，凌關塞若摧枯。","sortOrder":136},
  {"id":"s_work_nvlt_59_137","chapterId":"ch_work_nvlt_59","text":"梁簡文帝慶洛陽平啟曰：自函洛榛曠，獯獫荐食，久絕正朔之風，不睹輶軒之使，乘此戰心，負斯戎足，每興燔燧之驚，常勞守障之民，自非聖略弘宣，天網遐頓，豈能使漢地盡收，名王爭入，方令九服大同，萬邦齊軌，亭塞寢兵，關候罢柝，臣誠兼家國，倍深歡慶。","sortOrder":137},
  {"id":"s_work_nvlt_59_138","chapterId":"ch_work_nvlt_59","text":"梁劉孝綽求豫北伐啟曰：或以臣素無飛將之目，未從嫖姚之伍，言易行難，收功理絕，然桓冲稱謝安無將略，文靖公遂破符堅，山涛謂羊祜不強，建成侯卒平孫皓，微臣之譬兩賢，誠無等級，小虜之方二寇，势逾枯朽。","sortOrder":138},
  {"id":"s_work_nvlt_59_139","chapterId":"ch_work_nvlt_59","text":"【箋】晉陆機至洛與成都王箋曰：王室多故，禍難荐有，羊玄之乘寵凶竖，专記朝政，奸臣賊子，是為比周，皇甫商同惡相求，共為亂階，至令天子飄飖，甚於赘瘤，伏惟明公，匡濟之舉，義命方宣，先戎既啟，威風電赫，機以駑暗，文武寡施，猥蒙橫授，委任外梱，辄承嚴教，董率諸軍，唯力是视。","sortOrder":139},
  {"id":"s_work_nvlt_59_140","chapterId":"ch_work_nvlt_59","text":"晉桓溫與撫軍箋曰：北胡肆逆，四十餘載，傾覆社稷，毀辱陵廟，遇其可亡之會，實是君子竭誠，小人盡力之日也，江東雖為未丰，方之古人，复為未俭，少康以一旅之眾，興复祖宗，光武奋發，中興漢室，况以大晉之祚，树德長久，兼百越沃野之資，據江漢山海之利，鹽鐵寶帛之饒，角竿羽毛之用，收英賢之略，盡兵民之力，賦之強也，猶复遵養時晦，及其毙也，不齊力扫滅，則犬賊何由而自平，大恥焉得而自雪，臨紙惆怅，慨叹盈懷。","sortOrder":140},
  {"id":"s_work_nvlt_59_141","chapterId":"ch_work_nvlt_59","text":"【書】魏陳思王曹植與司馬仲達書曰：今賊徒欲保江表之城，守區區之吳爾，無有爭雄於宇內，角勝於平原之志也，故其俗蓋以洲渚為營壁，江淮為城巉而已，若可得挑致，則吾一旅之卒，足以敵之矣，蓋弋鳥者矯其矢，釣魚者理其纶，此皆度彼為膚，因象設宜者也，今足下曾無矯矢理纶之謀，徒欲候其離舟，伺其登陆，乃圖併吳會之地，收陳野之民，恐非主上授節將之心也。","sortOrder":141},
  {"id":"s_work_nvlt_59_142","chapterId":"ch_work_nvlt_59","text":"梁簡文帝答湘東王慶州牧書曰：雖心慕子文，申威涿郡，意存士雅，慷慨臨江，而不能遂封狼居之山，永空幕南之地，逐北聊城，追奔瀚海，必欲卷綬避賢，辭病收跡。","sortOrder":142},
  {"id":"s_work_nvlt_59_143","chapterId":"ch_work_nvlt_59","text":"【論】漢吾丘寿王驃騎論功論曰：驃騎將軍霍去病，征匈奴，立克勝之功，寿王作士大夫之論，稱武帝之德曰：士或問於大夫曰：侧聞強秦之用兵也，南不逾五嶺，北不渡大河，海內愁怨，以丧其國，漢興六十餘載矣，命將帥以抗憤，用幹戈於四荒，南排朱崖，北建朔方，東越沧海，西極河源，拓地萬里，海內晏然，鄙人不識，敢問其蹤，大夫曰：昔秦之得天下也，以力而不以德，以诈而不以誠，內用商鞅李斯之謀，外用白起王剪之兵，窥間伺隙，既併海內之後，以威力為至道，以權诈為要術，遂非唐笑虞，絕滅舊章，防禁文學，行是古之戮，嚴誹謗之誅，十餘年，遂滂沱而盈溢，是故皇天疾滅，更命大漢，反秦政，務在敦厚，至今六世，可謂富安，天子文明，四夷向風，徒觀朝廷下僚，門戶之士，謀如涌泉，動如駭機，皆能安中國，吞四夷，君臣若茲，何慮而不成，何征而不剋，雖拔泰山填沧海可也。","sortOrder":143},
  {"id":"s_work_nvlt_59_144","chapterId":"ch_work_nvlt_59","text":"魏王粲三辅論曰：湘潛先生，江濱逸老，將集論雲夢，玄公豫焉，先生稱曰：蓋聞戎不可動，兵不可扬，今劉牧建德垂芳，名烈既彰矣，曷乃稱兵舉眾，殘我濊零，逸老曰：是何言與，天生五材，金作明威，長沙不軌，敢作亂违，我牧睹其然，乃赫爾發憤，且上征下戰，去暴舉順，州牧之兵，建拂天之旌，鳴振地之鼓，玄胄曜日，犀甲如堵，以此眾戰，孰能婴御，劉牧之懿，子又未聞乎，履道懷智，休跡顯光，洒扫群虜，艾拨秽荒，走袁術於西境，馘射貢乎武當，遏孫堅於漢南，追楊定於析商。","sortOrder":144},
  {"id":"s_work_nvlt_59_145","chapterId":"ch_work_nvlt_59","text":"《藝文類聚》　唐·欧陽詢","sortOrder":145},
  {"id":"s_work_nvlt_60_1","chapterId":"ch_work_nvlt_60","text":"卷六十軍器部","sortOrder":1},
  {"id":"s_work_nvlt_60_2","chapterId":"ch_work_nvlt_60","text":"○牙劍刀匕首鋏弓箭弩彈槊","sortOrder":2},
  {"id":"s_work_nvlt_60_4","chapterId":"ch_work_nvlt_60","text":"《兵書》曰：牙旗者，將軍之精，凡始竖牙，必以刚日，刚日者，謂上剋下也，立牙之日，吉氣來應，大勝之徵，《黃帝出軍决》曰：始立牙之日，旗幡指敵，或從風而舉，暉暉絕［《太平御覽》三百三十九作終。］日，不絕［御覽作繞。］竿，勇氣奔逸。","sortOrder":4},
  {"id":"s_work_nvlt_60_5","chapterId":"ch_work_nvlt_60","text":"又曰：將軍出兵，有所讨伐，引兵出城門，望見白雲及白水者，舉白牙旗，五色牙旗，隨天氣四時。","sortOrder":5},
  {"id":"s_work_nvlt_60_6","chapterId":"ch_work_nvlt_60","text":"《魏志》曰：典韦初為張邈士屬，趙寵牙門長大，莫能勝，韦一手建之，寵異才力。","sortOrder":6},
  {"id":"s_work_nvlt_60_7","chapterId":"ch_work_nvlt_60","text":"《吳志》曰：陆遜為右部督，會丹陽賊帥費栈，扇動山越，權遣遜讨栈，栈支党多，所往兵少，遜乃益施牙幢，分付鼓角，夜潛出穀間，鼓譟而前，應即破散。","sortOrder":7},
  {"id":"s_work_nvlt_60_8","chapterId":"ch_work_nvlt_60","text":"《抱朴子》曰：軍所始舉牙立旗，風氣和調，幡校飄飄，終日不息者，其軍有功。","sortOrder":8},
  {"id":"s_work_nvlt_60_9","chapterId":"ch_work_nvlt_60","text":"【賦】吳胡綜大牙賦曰：黃初八年，黃龍見夏口，孫權稱號，因瑞改元，作黃龍大牙，常在軍中，進退视其所向，命綜為賦曰：狼狐［《初學記》二十二作弧。］垂蒙，［《初學記》作象，《太平御覽》三百三十九作曜。］實惟兵精，聖人觀法，是效是營，始作器械，爰求厥成，明明大吳，實天生德，仍律天時，製其神軍，取象太一，五將三門，疾則如電，遲則如雲，進止有度，約而不煩，四靈既布，黃龍處中，周製日月，實曰太常，杰然特立，六軍四望。","sortOrder":9},
  {"id":"s_work_nvlt_60_10","chapterId":"ch_work_nvlt_60","text":"【祭文】後漢滕辅祭牙文曰：恭羌太守，［《初學記》二十二作恭脩太牢，太平御覽三百三十九作恭羞太牢，此訛。］絜荐遐靈，推轂之任，實讨不庭，天道助順，正直聰明。","sortOrder":10},
  {"id":"s_work_nvlt_60_11","chapterId":"ch_work_nvlt_60","text":"晉袁宏祭牙文曰：天生五材，治道所司，废一不可，靜亂辅時。","sortOrder":11},
  {"id":"s_work_nvlt_60_12","chapterId":"ch_work_nvlt_60","text":"晉顧恺之祭牙文曰：維某年某月日，錄尚書事豫章公裕，敢告黃帝蚩尤五兵之靈，兩儀有政，四海有王，奉命在天，世德重光，烈烈高牙，闐闐伐鼓，白氣經天，簡扬神武。","sortOrder":12},
  {"id":"s_work_nvlt_60_13","chapterId":"ch_work_nvlt_60","text":"宋王誕伐廣固祭牙文曰：敬建崇牙，顯茲威靈，使鳴金輟衅，無戰有寧，皇風幽被，凯旆歸旌。","sortOrder":13},
  {"id":"s_work_nvlt_60_14","chapterId":"ch_work_nvlt_60","text":"宋鄭鮮祭牙文曰：絜牲先事，荐茲敬祭，崇牙既建，義鋒增厲，人鬼一揆，三才同契，惟茲靈鑒，庶必有察，逆順幽辯，忠孝顯節，使凶丑時殲，主寧臣悅，振旅上京，凯歸西蕃，神器增暉，四境永安。","sortOrder":14},
  {"id":"s_work_nvlt_60_16","chapterId":"ch_work_nvlt_60","text":"《釋名》曰：劍，檢也，所以防檢非常也。","sortOrder":16},
  {"id":"s_work_nvlt_60_17","chapterId":"ch_work_nvlt_60","text":"《韻集》曰：鐔，劍口也。","sortOrder":17},
  {"id":"s_work_nvlt_60_18","chapterId":"ch_work_nvlt_60","text":"《字林》曰：瑑，劍鼻也。","sortOrder":18},
  {"id":"s_work_nvlt_60_19","chapterId":"ch_work_nvlt_60","text":"《龍魚河圖》曰：流州在西海中，上多積石，名為崑吾石，治其石成鐵，作劍，光明四照，洞如水精，［事具地部石篇。］","sortOrder":19},
  {"id":"s_work_nvlt_60_20","chapterId":"ch_work_nvlt_60","text":"又曰：劍名飛扬，《管子》曰：葛天盧之山，發而出金，蚩尤受而製之，以為劍鎧矛戟。","sortOrder":20},
  {"id":"s_work_nvlt_60_21","chapterId":"ch_work_nvlt_60","text":"《山海經註》曰：汲郡冢中，得銅劍一枚，長三尺五寸，今所名幹將劍，明古者通以錫銅為兵器。","sortOrder":21},
  {"id":"s_work_nvlt_60_22","chapterId":"ch_work_nvlt_60","text":"又曰：君子之國，其人衣冠帶劍，［事具人部讓篇。］","sortOrder":22},
  {"id":"s_work_nvlt_60_23","chapterId":"ch_work_nvlt_60","text":"《周官》曰：鄭之刀，宋之斤，魯之削，吳越之劍，遷乎其地而不能為良，地氣然也。","sortOrder":23},
  {"id":"s_work_nvlt_60_24","chapterId":"ch_work_nvlt_60","text":"《管子》曰：羽劍珠飾者，斬生之斧也。","sortOrder":24},
  {"id":"s_work_nvlt_60_25","chapterId":"ch_work_nvlt_60","text":"《吳越春秋》曰：越王允常，聘區冶子作名劍五枚，一曰純鉤，二曰湛盧，三曰豪曹，或曰盤郢，四曰魚腸，五曰巨闕，秦客薛燭善相劍，王取純鉤示之，薛燭矍然望之曰：沉沉如芙蓉始生於湖，觀其文，如列星之行，觀其光，如水之溢塘，觀其文色，涣涣如冰將釋，見日之光，王曰：客有賣此劍者，有市之乡三十，駿馬千疋，千戶之都二，其可與乎，薛燭曰：不可，臣聞王之造此劍，赤堇之山，破而出錫，若耶之溪，涸而出銅，吉日良時，雨師洒道，雷公發鼓，蛟龍捧爐，天帝壮炭，太一下觀，於是區冶子因天地之精，造為此劍，取湛盧视之，薛燭曰：善哉，衔金鐵之英，奇［《初學記》二十二作寄。］氣讬靈，服此劍者，可以折冲伐敵，人君有逆謀則去之，允常以魚腸湛盧豪曹獻吳王僚，後阖闾為一女，殺生以送死，湛盧之劍惡其無道，乃去如楚，昭王寐而得之，召風胡子問之，此劍直幾何，對曰：赤堇之山已合，若耶之溪，深而不测，群神一［《太平御覽》三百四十三作上。］天，區冶子已死，雖有傾城量金珠玉，猶不可與，况駿馬萬戶之都乎。","sortOrder":25},
  {"id":"s_work_nvlt_60_26","chapterId":"ch_work_nvlt_60","text":"《越絕書》曰：楚王召風湖子而問之曰：寡人聞吳有幹將，越有區冶子，寡人原請此二人作鐵劍，乃令風湖子之吳，見區冶子幹將，使之作為鐵劍，曰泰阿，晉鄭聞而求之，不得，興師围楚，於是王引泰阿之劍，登城而麾之，三軍破败，士卒迷惑，流血千里，江水抑扬，折晉鄭之頭畢日，［《太平御覽》三百四十三作白。］《列子》曰：衛孔周，其祖得殷帝之寶劍，童子服之，却三軍之眾，其一曰含光，视之不可見，運之不知其所觸，泯然無际，經物而物不覺，二曰承影，將旦昧爽之交，日夕昏明之际，北面察之，淡焉若有物在，莫識其状，其觸物也，寂無有聲，而物不疾，三曰霄練，方晝，見其影，不見光，驢［字衍。］騞然而過，隨合，覺疾而不血刃，此三寶傳之十三世矣。","sortOrder":26},
  {"id":"s_work_nvlt_60_27","chapterId":"ch_work_nvlt_60","text":"又曰：宋王有蘭子者，以技幹宋元君，弄七劍，迭躍之，五劍常在空中，元君大驚，立賜金帛。","sortOrder":27},
  {"id":"s_work_nvlt_60_28","chapterId":"ch_work_nvlt_60","text":"又曰：周穆王征西戎，西戎獻崑吾之劍，赤刃，切玉如泥。","sortOrder":28},
  {"id":"s_work_nvlt_60_29","chapterId":"ch_work_nvlt_60","text":"《莊子》曰：昔趙文王喜劍，《莊子》曰：臣聞大王喜劍，臣有三劍，惟王所用，有天子劍，有諸侯劍，有庶人劍，天子之劍，以燕谿石城為鋒，齊代為鍔，晉衛為脊，周宋為鐔，韓魏為鋏，統以渤海，帶以常山，此劍一用，匡諸侯，天下服矣，諸侯之劍，以智勇士為鋒，以精廉士為鍔，以賢良士為脊，以忠聖士為鐔，以豪杰為鋏，此劍一用，如雷霆之震也，庶人之劍，蓬頭突鬢，垂冠曼胡之纓，短後之衣，瞋目而語難，相击於前，此無異斗雞，一旦命以絕矣，今大王有天子之位，而好庶人之劍，臣竊為大王薄之。","sortOrder":29},
  {"id":"s_work_nvlt_60_30","chapterId":"ch_work_nvlt_60","text":"《孫卿子》曰：桓公之慈，太公之闕，文王之琢，莊君之忽，阖闾子幹將莫耶，巨闕辟闾，皆古良劍也。","sortOrder":30},
  {"id":"s_work_nvlt_60_31","chapterId":"ch_work_nvlt_60","text":"《尸子》曰：水试斷鵠雁，陆试斷牛馬，所以觀良劍也。","sortOrder":31},
  {"id":"s_work_nvlt_60_32","chapterId":"ch_work_nvlt_60","text":"《呂氏春秋》曰：楚人有涉江者，其劍自舟中墜於水，遂刻其舟曰：是吾劍之所從墜也，舟止，從其所契刻者入水求之，舟已行矣，而劍不行，求劍若此，不亦惑乎。","sortOrder":32},
  {"id":"s_work_nvlt_60_33","chapterId":"ch_work_nvlt_60","text":"又曰：荆有佽飛者，得寶劍於江幹，遂還反，涉江至於中流，而兩蛟夹繞其舡，佽飛攘臂袪衣，拔寶劍赴江，刺蛟殺之，荆王聞之，仕以執圭。","sortOrder":33},
  {"id":"s_work_nvlt_60_34","chapterId":"ch_work_nvlt_60","text":"《史記》曰：吳季札之初使，北過徐，徐君好季札劍，口不敢言，季札知之，為使上國，未獻，還至徐，徐君已死，乃解其寶劍，系徐君冢树而去。","sortOrder":34},
  {"id":"s_work_nvlt_60_35","chapterId":"ch_work_nvlt_60","text":"又曰：秦昭王臨朝叹息，應侯進曰：臣聞主忧臣辱，主辱臣死，今大王中朝而忧，臣敢請其罪，王曰：吾聞楚之鐵劍利而倡優拙，夫鐵劍利則士勇，倡優拙則思慮遠矣，以遠思慮而御勇士，恐楚之圖秦。","sortOrder":35},
  {"id":"s_work_nvlt_60_36","chapterId":"ch_work_nvlt_60","text":"又曰：高祖送徒驪山，到丰而夜，径泽中，令一人行前，行前者還報曰：前有大蛇當径，原還，高祖曰：壮士行何畏，乃前拔劍斬蛇，蛇分為兩，道开，［事具帝王部。］","sortOrder":36},
  {"id":"s_work_nvlt_60_37","chapterId":"ch_work_nvlt_60","text":"又曰：高祖击英布時，為流矢所中，高祖問医，曰：病可治，於是高祖慢骂之曰：吾從布衣，提三尺劍，取天下，此非天命乎，命乃在天，雖扁鵲何益。","sortOrder":37},
  {"id":"s_work_nvlt_60_38","chapterId":"ch_work_nvlt_60","text":"又曰：陳平間行杖劍，亡渡河，舡人見其美丈夫獨行，疑其亡將，腰中有金寶，因之欲殺平，平恐，解衣佐刺舡，舡人知其無，乃止。","sortOrder":38},
  {"id":"s_work_nvlt_60_39","chapterId":"ch_work_nvlt_60","text":"《說苑》曰：經侯往過魏太子，左帶玉具劍，右帶環佩，左光照右，右光照左，［事具衣冠部觖佩篇。］《異苑》曰：晉惠帝元康三年，武库火，燒孔子履高祖斬白蛇之劍，鹹見此劍，穿屋飛去，莫知所向。","sortOrder":39},
  {"id":"s_work_nvlt_60_40","chapterId":"ch_work_nvlt_60","text":"《漢書》曰：雋不疑，字曼倩，帝使暴勝之為直指使者，素聞不疑賢，遣吏請與相見，不疑冠進賢冠，帶衤畾具劍，［衤畾磊落壮大之濬。］","sortOrder":40},
  {"id":"s_work_nvlt_60_41","chapterId":"ch_work_nvlt_60","text":"又曰：陆贾常乘安車驷馬，從歌鼓琴瑟侍者十人，寶劍直百金，其遊漢庭，名聲藉甚，［言狼藉其盛。］","sortOrder":41},
  {"id":"s_work_nvlt_60_42","chapterId":"ch_work_nvlt_60","text":"《漢武內傳》曰：西王母帶分景之劍，上元夫人帶流黃擇精之劍。","sortOrder":42},
  {"id":"s_work_nvlt_60_43","chapterId":"ch_work_nvlt_60","text":"《東觀漢記》曰：世祖時，有獻名馬寶劍，直百金，馬以駕鼓車，劍以賜騎士。","sortOrder":43},
  {"id":"s_work_nvlt_60_44","chapterId":"ch_work_nvlt_60","text":"《吳越春秋》曰：伍子胥過江，解其劍與漁父曰：此劍中有七星北斗，其直百金。","sortOrder":44},
  {"id":"s_work_nvlt_60_45","chapterId":"ch_work_nvlt_60","text":"《典論》曰：建安二十四年二月壬午，魏太子丕造百辟寶劍，長四尺二寸，淬以清漳，厲以蛇監諸，飾以文玉，表以通犀，光似流星，名曰飛景。","sortOrder":45},
  {"id":"s_work_nvlt_60_46","chapterId":"ch_work_nvlt_60","text":"雷次宗豫章記曰：吳未亡，恒有紫氣見牛斗之間，張華聞雷孔章妙達緯象，乃要宿，問天文，孔章曰：惟牛斗之間有異氣，是寶物也，精在豫章丰城，張華遂以孔章為丰城令，至縣，掘深二丈，得玉匣，長八尺，开之，得二劍，其夕斗牛氣不复見，孔章乃留其一匣，而進之，劍至，光曜煒晔，煥若電發，後張華遇害，此劍飛入襄城水中，孔章臨亡，戒其子，恒以劍自隨，後其子為建安從事，經淺瀨，劍忽於腰間躍出，遂视，見二龍相隨焉。","sortOrder":46},
  {"id":"s_work_nvlt_60_47","chapterId":"ch_work_nvlt_60","text":"《文士傳》曰：魏文帝愛楊脩才，脩誅後，追憶脩，脩曾以寶劍與文帝，帝後佩之，告左右曰：此楊脩劍也。","sortOrder":47},
  {"id":"s_work_nvlt_60_48","chapterId":"ch_work_nvlt_60","text":"沈約《宋書》曰：初世祖賜謝莊寶劍，莊以與豫州刺史魯爽，別後，爽反叛，世祖因宴集，問劍所在，答曰：昔以與魯爽別，竊為陛下杜郵之賜，上甚悅，當時以為知言。","sortOrder":48},
  {"id":"s_work_nvlt_60_49","chapterId":"ch_work_nvlt_60","text":"【詩】宋鮑昭詩曰：双劍將別離，先在匣中鳴，雌沉吳江里，雄飛入楚城，吳江深無底，楚闕有崇扃，一為天地別，豈直限幽明，神物終不隔，千祀傥還併。","sortOrder":49},
  {"id":"s_work_nvlt_60_50","chapterId":"ch_work_nvlt_60","text":"梁吳筠詠寶劍詩曰：我有一寶劍，出自崑吾溪，照人如照水，切玉如切泥，鍔邊霜凛凛，匣上風凄凄，寄語張公子，何當來見携。","sortOrder":50},
  {"id":"s_work_nvlt_60_51","chapterId":"ch_work_nvlt_60","text":"【銘】後漢士孫瑞劍銘曰：天生五材，金德惟刚，從革庚辛，含景吐商，辯物利用，勋伐弥彰，暨彼良工，區冶幹將，爰造寶劍，巨闕墨陽，精通皓靈，獲茲休祥，剖山竭川，虹蜺消亡，曜威燿武，震動遐荒，楚以定霸，越以取強。","sortOrder":51},
  {"id":"s_work_nvlt_60_52","chapterId":"ch_work_nvlt_60","text":"晉裴景聲文身劍銘曰：器以利顯，實以名舉，長劍耿介，體文經武，陆斷玄犀，水截輕羽，九功斯像，七德是辅。","sortOrder":52},
  {"id":"s_work_nvlt_60_53","chapterId":"ch_work_nvlt_60","text":"晉張协太阿劍銘曰：太阿之劍，世載其美，淬以清波，砺以越砥，如玉斯曜，若影在水，不運自肅，率土從軌。","sortOrder":53},
  {"id":"s_work_nvlt_60_54","chapterId":"ch_work_nvlt_60","text":"【啟】梁簡文帝謝敕赉方諸劍等啟曰：才發紫函，彫奇溢目，始开泥檢，麗飾交陳，已匹丹霞之暉，乍比青雲之製，身文且貴，器用惟宜，寒暑兼華，左右相照。","sortOrder":54},
  {"id":"s_work_nvlt_60_55","chapterId":"ch_work_nvlt_60","text":"梁沈約為東宮謝敕賜孟嘗君劍啟曰：田文重氣徇名，四豪莫及，寶劍雄身，故能威陵秦楚，人高事遠，遺物足奇，謹加玩服，以深存古之懷。","sortOrder":55},
  {"id":"s_work_nvlt_60_57","chapterId":"ch_work_nvlt_60","text":"《字林》曰：琫，佩刀下飾也，天子以玉，諸侯以金，琕，佩刀上飾也。","sortOrder":57},
  {"id":"s_work_nvlt_60_58","chapterId":"ch_work_nvlt_60","text":"《太公兵法》曰：刀子之神，名曰脱光。","sortOrder":58},
  {"id":"s_work_nvlt_60_59","chapterId":"ch_work_nvlt_60","text":"《禮記》曰：割刀之用，鸞刀之貴，貴其義也。","sortOrder":59},
  {"id":"s_work_nvlt_60_60","chapterId":"ch_work_nvlt_60","text":"《論語》曰：子之武城，聞絃歌之聲，夫子莞爾而笑曰：割雞焉用牛刀，［事具人部笑篇。］","sortOrder":60},
  {"id":"s_work_nvlt_60_61","chapterId":"ch_work_nvlt_60","text":"《楚辭》曰：鉛刀進御，遙弃太阿。","sortOrder":61},
  {"id":"s_work_nvlt_60_62","chapterId":"ch_work_nvlt_60","text":"《孔丛子》曰：秦王得西戎利刀，以之割玉，如割木焉，《漢書》曰：龚遂為渤海太守，民有帶持刀劍者，使賣劍買牛，賣刀買犢，何為帶牛而佩犢。","sortOrder":62},
  {"id":"s_work_nvlt_60_63","chapterId":"ch_work_nvlt_60","text":"班固與弟超書曰：窦侍中遺仲叔，楚滕陵错橫刀玉〈王戚〉早削一枚，金错半垂刀一枚。","sortOrder":63},
  {"id":"s_work_nvlt_60_64","chapterId":"ch_work_nvlt_60","text":"《東觀漢記》曰：馬嚴為陳留太守，建初中，嚴病，遣功曹，史李龚，奉章詣闕，上召見龚，問疾病形状，以黃金十斤，葛縛佩刀書刀革帶付龚，賜嚴。","sortOrder":64},
  {"id":"s_work_nvlt_60_65","chapterId":"ch_work_nvlt_60","text":"又曰：賜邓遵金對［東觀漢記作刚。］鮮卑绲帶一具，金错［東觀漢記，《太平御覽》三百四十五下有刀字，此脱。］五十，辟把刀墨再屈環橫刀金鏡［○《東觀漢記》、《御覽》作错。］屈尺八佩刀各一。","sortOrder":65},
  {"id":"s_work_nvlt_60_66","chapterId":"ch_work_nvlt_60","text":"魏武帝令曰：往歲作百辟刀五枚，適成，先以一與五官將，其餘四，吾諸子中有不好武而好文學，將以次與之。","sortOrder":66},
  {"id":"s_work_nvlt_60_67","chapterId":"ch_work_nvlt_60","text":"《典論》曰：昔者周魯寶赤刀孟勞。","sortOrder":67},
  {"id":"s_work_nvlt_60_68","chapterId":"ch_work_nvlt_60","text":"又曰：平造百辟寶刀，名靈寶，其二采似丹霞，名曰含章，其三铿似崩霜，名曰素质。","sortOrder":68},
  {"id":"s_work_nvlt_60_69","chapterId":"ch_work_nvlt_60","text":"費袆別傳曰：孫權以手中常所執寶刀赠之。","sortOrder":69},
  {"id":"s_work_nvlt_60_70","chapterId":"ch_work_nvlt_60","text":"《蜀志》曰：初孫權以妹妻先主，妹才捷刚猛，有諸兄風，侍婢百餘人，皆親執刀侍立，先主每入，心常栗栗。","sortOrder":70},
  {"id":"s_work_nvlt_60_71","chapterId":"ch_work_nvlt_60","text":"《物理論》曰：古有阮師之刀，天下之所寶貴也，初阮之作刀，受法於金精之靈，七月庚辛，見金神於冶監之門，其人光色煒燿，向而再拜，神執其手曰：子可教也，既致之，閒宴設饌而問焉，神教以水火之齊，五精之陶，用陰陽之候，取刚软之和。","sortOrder":71},
  {"id":"s_work_nvlt_60_72","chapterId":"ch_work_nvlt_60","text":"陆機《晉書》曰：王濬之在郡也，夢懸四刀於其上，甚惡之，濬主簿李穀，拜贺曰：夫三刀為州，而見四，益一也，明府其臨益州乎。","sortOrder":72},
  {"id":"s_work_nvlt_60_73","chapterId":"ch_work_nvlt_60","text":"聖證論曰：昔國家有優曰史利，漢氏舊優也，雲梁冀有火浣布切玉刀，一朝以為誕而不信也，正始初，得火浣布，乃信。","sortOrder":73},
  {"id":"s_work_nvlt_60_74","chapterId":"ch_work_nvlt_60","text":"《晉中興書》曰：初魏徐州刺史呂虔，有佩刀，工相之，以為必三公可服此刀，虔謂別駕王祥曰：苟非其人，刀或為害，卿有公辅之量，故以相與。","sortOrder":74},
  {"id":"s_work_nvlt_60_75","chapterId":"ch_work_nvlt_60","text":"蒲元傳曰：君性多奇思，於斜穀，為諸葛亮鑄刀三千口，刀成，自言漢水钝弱，不任淬用，蜀江爽烈，是謂大金之元精，天分其野，乃命人於成都取江水，君以淬刀，言雜涪水，不可用，取水者捍言不雜，君以刀畫水，言雜八升，取水者叩頭雲，於涪津覆水，遂以涪水八升益之，以竹筒內鐵珠滿中，舉刀斷之，應手虛落，因曰神刀，金屈耳環者，乃是其遺范。","sortOrder":75},
  {"id":"s_work_nvlt_60_76","chapterId":"ch_work_nvlt_60","text":"【賦】魏陳王曹植寶刀賦曰：建安中，魏王命有司造寶刀五枚，以龍熊鳥雀為識，太子得一，餘及餘弟饒陽侯，各得一焉，有皇漢之明後，思潛達而玄通，飛文義而博致，扬武備以御凶，然後砺以五方之石，鑒以中黃之壤，規圓景以定環，摅神功而造像，陆斬犀象，水斷龍舟，輕击浮截，刃不瀸流，逾南越之巨闕，超西楚之太阿，寔真精之攸御，永天祿而是荷。","sortOrder":76},
  {"id":"s_work_nvlt_60_77","chapterId":"ch_work_nvlt_60","text":"【銘】後漢冯敬通刀陽銘曰：脩爾甲兵，用戒不虞，見危致命，臨事而懼，文不可匿，武不可黷，文武孔純，荷天子祿。","sortOrder":77},
  {"id":"s_work_nvlt_60_78","chapterId":"ch_work_nvlt_60","text":"又刀陰銘曰：溫溫穆穆，配天之威，苗裔無疆，福報永綏。","sortOrder":78},
  {"id":"s_work_nvlt_60_79","chapterId":"ch_work_nvlt_60","text":"後漢李尤错佩刀銘曰：佩之有错，抑武扬文，豈為麗好，將戒有身。又金馬書刀銘曰：巧冶煉刚，金讬於刑，［《初學記》二十二，《太平御覽》三百四十六作金馬讬形。］黃又［御覽作文。］错鏤，兼勒工名。","sortOrder":79},
  {"id":"s_work_nvlt_60_80","chapterId":"ch_work_nvlt_60","text":"魏文帝露陌刀銘曰：於鑠良刀，胡煉亶時，譬諸麟角，靡所任茲，不逢不若，永世寶持。","sortOrder":80},
  {"id":"s_work_nvlt_60_81","chapterId":"ch_work_nvlt_60","text":"魏陳王曹植寶刀銘曰：造茲寶刀，既砻既砺，匪以尚武，予身是衛，麟角匪獨，鸞距匪蹶。","sortOrder":81},
  {"id":"s_work_nvlt_60_82","chapterId":"ch_work_nvlt_60","text":"魏王粲刀銘曰：相時陰陽，製茲利兵，和諸色刳，考諸濁清，陆剸犀兕，水截鲵鯨，君子服之，式章威靈。","sortOrder":82},
  {"id":"s_work_nvlt_60_83","chapterId":"ch_work_nvlt_60","text":"魏何晏斫猛獸刀銘曰：徒摶不兵，作戒宣丘，用造斯器，螭獸是劉，製禽允良，昏明亶時，永釐厥後，蠲民之灾。","sortOrder":83},
  {"id":"s_work_nvlt_60_84","chapterId":"ch_work_nvlt_60","text":"晉張协文身刀銘曰：寶刀既成，窮理盡妙，繁文波回，流光電照。","sortOrder":84},
  {"id":"s_work_nvlt_60_85","chapterId":"ch_work_nvlt_60","text":"又把刀銘曰：弈弈名金，崑吾遺璞，裁為把刀，利亚切玉，時文斯偃，含精內燭，威助雖化，武不可黷。","sortOrder":85},
  {"id":"s_work_nvlt_60_86","chapterId":"ch_work_nvlt_60","text":"晉裴景聲文身刀銘曰：良金百煉，乙名［《太平御覽》三百四十六作名工。］展巧，寶刀既成，理［御覽作窮。］理盡妙，文繁波流，回光電照，在我皇世，戢而不耀。","sortOrder":86},
  {"id":"s_work_nvlt_60_87","chapterId":"ch_work_nvlt_60","text":"【啟】梁簡文帝謝敕赉善勝威勝刀啟曰：冰鍔含采，雕琰表飾，名均素质，神號脱光，五寶初成，曹丕先荷其一，二勝今造，愚臣總被其恩，錫韓非之書，未足為比，給博山之筆，方此更輕。","sortOrder":87},
  {"id":"s_work_nvlt_60_88","chapterId":"ch_work_nvlt_60","text":"梁劉孝儀為晉安王謝東宮賜玉環刀啟曰：苗峰珍鋌，利極鉤铓，謹當擁以雄身，藉而安體，不令北海小雍，孤擅穿滕之寄，庐江佩刀，獨表不欺之验。","sortOrder":88},
  {"id":"s_work_nvlt_60_89","chapterId":"ch_work_nvlt_60","text":"◇匕首","sortOrder":89},
  {"id":"s_work_nvlt_60_90","chapterId":"ch_work_nvlt_60","text":"《通俗文》曰：匕首，劍屬，其頭類匕，故曰匕首，短而便用。","sortOrder":90},
  {"id":"s_work_nvlt_60_91","chapterId":"ch_work_nvlt_60","text":"《說苑》曰：秦王以五十里封鄢陵之君，辭不受，使唐且謝秦，秦王怒曰：嘗見天子之怒乎，一怒伏尸百萬，流血千里，唐且曰：大王嘗聞布衣韦帶之士怒乎，一怒伏尸二人，流血五步，即按其匕首起曰：今將是矣，王变色曰：先生就坐，寡人喻矣，秦破韓滅魏，鄢陵獨以五十里存者，徒用先生故也。","sortOrder":91},
  {"id":"s_work_nvlt_60_92","chapterId":"ch_work_nvlt_60","text":"諸葛故事曰：成都作匕首五百枚，以給騎士。","sortOrder":92},
  {"id":"s_work_nvlt_60_93","chapterId":"ch_work_nvlt_60","text":"《典論》曰：昔周魯寶雍狐之戟，屈盧之矛，孤父之戈，徐氏匕首，凡斯皆上世名器，君子雖有文事，必有武備矣。","sortOrder":93},
  {"id":"s_work_nvlt_60_94","chapterId":"ch_work_nvlt_60","text":"又曰：魏太子造百辟匕首二，其一理似堅冰，名曰清刚，其二曜似朝日，名曰扬文。","sortOrder":94},
  {"id":"s_work_nvlt_60_95","chapterId":"ch_work_nvlt_60","text":"《神仙傳》曰：有書生姓張，就李仲文學隱術，久無所得，患之，張懷匕首斫之，仲文笑曰：我寧可殺。","sortOrder":95},
  {"id":"s_work_nvlt_60_96","chapterId":"ch_work_nvlt_60","text":"【銘】晉張載匕首銘曰：元民造製，戒豫惟謹，匕首之設，應速用近，既不忽備，亦無輕忿，利以形彰，切以道隱。","sortOrder":96},
  {"id":"s_work_nvlt_60_98","chapterId":"ch_work_nvlt_60","text":"《戰國策》曰：冯谖為孟嘗客，彈劍鋏而歌曰：長鋏歸來乎食無魚。","sortOrder":98},
  {"id":"s_work_nvlt_60_99","chapterId":"ch_work_nvlt_60","text":"【銘】晉張协長鋏銘曰：五才併建，金作明威，長鋏陆離，弭凶防违，素刃霜厲，溢景橫飛。","sortOrder":99},
  {"id":"s_work_nvlt_60_100","chapterId":"ch_work_nvlt_60","text":"又短鋏銘曰：器用多品，诡製殊觀，亦有短鋏，清暉載烂，昔在先朝，戢兵靜亂，惟皇寶之，優而弗玩。","sortOrder":100},
  {"id":"s_work_nvlt_60_102","chapterId":"ch_work_nvlt_60","text":"《釋名》曰：弓，穹也，張之穹隆然，其末曰箫，言箫稍，［原訛邪，據冯校本改。］又謂之弭，以骨為之，滑弭弭也，中央曰弣，弣，撫也，所撫持也。","sortOrder":102},
  {"id":"s_work_nvlt_60_103","chapterId":"ch_work_nvlt_60","text":"《山海經》曰：少皞生股，是始弓矣，［世本雲，牟夷作矢，揮作弓，弓矢一器，作者兩人，於義有疑，此言股作之是也。］","sortOrder":103},
  {"id":"s_work_nvlt_60_104","chapterId":"ch_work_nvlt_60","text":"《世本》曰：揮作弓，［揮，黃帝臣。］","sortOrder":104},
  {"id":"s_work_nvlt_60_105","chapterId":"ch_work_nvlt_60","text":"《龍魚河圖》曰：弓之神，名曰曲張。","sortOrder":105},
  {"id":"s_work_nvlt_60_106","chapterId":"ch_work_nvlt_60","text":"《爾雅》曰：弓有緣謂之弓，無緣者謂之弭，以金者謂之铣，以蜃者謂之珧，以玉者謂之圭。","sortOrder":106},
  {"id":"s_work_nvlt_60_107","chapterId":"ch_work_nvlt_60","text":"《方言》曰：弓藏謂之鞬，式謂之韇。","sortOrder":107},
  {"id":"s_work_nvlt_60_108","chapterId":"ch_work_nvlt_60","text":"《說文》曰：角端獸，状似豕，角善為弓，出胡休夕［《太平御覽》三百四十七作胡尸國，註雲一曰出休尸國，按說文作胡休多國。］國。","sortOrder":108},
  {"id":"s_work_nvlt_60_109","chapterId":"ch_work_nvlt_60","text":"《易》曰：絃木為弧，剡木為矢，弧矢之利，以威天下。","sortOrder":109},
  {"id":"s_work_nvlt_60_110","chapterId":"ch_work_nvlt_60","text":"《廣雅》曰：繁弱鉅黍弓也。","sortOrder":110},
  {"id":"s_work_nvlt_60_111","chapterId":"ch_work_nvlt_60","text":"《周官》曰：司弓，掌六弓四弩八矢之法，辨其名物，而掌其守藏，與其出入，中春獻弓弩，中秋獻矢箙，［箙，盛矢器。］天子之弓，合九而成規，諸侯合七而成規，大夫合五而成規，士合三而成規。","sortOrder":111},
  {"id":"s_work_nvlt_60_112","chapterId":"ch_work_nvlt_60","text":"又曰：弓人為弓，取六材，必以其時，六材既聚，巧者和之，幹者以為遠也，角者以為疾也，筋者以為深也，膠者以為和也，絲者以為固也，漆者以為受霜露也，凡取幹之道七，柘為上，檍次之，檿桑次之，橘次之，木瓜次之，荆次之，竹為下。","sortOrder":112},
  {"id":"s_work_nvlt_60_113","chapterId":"ch_work_nvlt_60","text":"《毛詩》曰：彤弓，天子賜有功諸侯也。","sortOrder":113},
  {"id":"s_work_nvlt_60_114","chapterId":"ch_work_nvlt_60","text":"《左傳》曰：顏高之弓六鈞，［顏高，魯人也，三十斤為鈞。］","sortOrder":114},
  {"id":"s_work_nvlt_60_115","chapterId":"ch_work_nvlt_60","text":"又曰：分魯公以大路大旂，夏後氏之璜，封父之繁弱。","sortOrder":115},
  {"id":"s_work_nvlt_60_116","chapterId":"ch_work_nvlt_60","text":"郭璞毛詩拾遺曰：象弭魚服，毛雲，弭弓反末，以象骨為之，蓋俗說之誤也，《左傳》曰：左執鞭弭，弭者弓之別名，謂以象牙為弓，今西方有以犀角及鹿角為弓者。","sortOrder":116},
  {"id":"s_work_nvlt_60_117","chapterId":"ch_work_nvlt_60","text":"《列子》曰：紀昌學射於飛衛，飛衛曰：爾先學不瞬而後能。又使學视小如大，紀昌以氂懸蝨於牖，南面而望之，三年之後如輪，睹物皆山丘也，乃以燕角之弧，朔蓬之幹射之，貫蝨之心，而懸不絕。","sortOrder":117},
  {"id":"s_work_nvlt_60_118","chapterId":"ch_work_nvlt_60","text":"《楚辭》曰：帶長劍，挟秦弓。","sortOrder":118},
  {"id":"s_work_nvlt_60_119","chapterId":"ch_work_nvlt_60","text":"《孫卿子》曰：天子彫弓，諸侯彤弓，大夫黑弓，禮也。","sortOrder":119},
  {"id":"s_work_nvlt_60_120","chapterId":"ch_work_nvlt_60","text":"《戰國策》曰：楚人有好以弱弓微繳加歸雁之上者，頃襄王聞而召問之，對曰：見鳥六双，王何不以聖人為弓，以勇士為繳，時張而射之，此六双者，可得而囊載也。","sortOrder":120},
  {"id":"s_work_nvlt_60_121","chapterId":"ch_work_nvlt_60","text":"《家語》曰：楚共王出遊，亡其乌號之弓，［乌號，良弓名也。］左右請求之，王曰：楚人失弓，楚人得之。又何求焉。","sortOrder":121},
  {"id":"s_work_nvlt_60_122","chapterId":"ch_work_nvlt_60","text":"《孔丛子》曰：楚王張繁弱之弓，載忘歸之矢，以射蛟兕於雲夢。","sortOrder":122},
  {"id":"s_work_nvlt_60_123","chapterId":"ch_work_nvlt_60","text":"《列女傳》曰：晉平公使工為弓，三年乃成，射不穿一札，公怒，將殺工，其妻見公曰：妾之夫造此弓，亦勞矣，幹生太山之阿，一日三睹陰三睹陽，傅以燕牛之角，纏以荆麋之筋，糊以河魚之膠，此四者天下之選也，而不穿一札，是君不能射也，妾聞射之道，左手如拒，右手如附支，右手發，左手不知，公以其儀而穿七札，弓工立得出，賜金三镒。","sortOrder":123},
  {"id":"s_work_nvlt_60_124","chapterId":"ch_work_nvlt_60","text":"闕子曰：宋景公使弓工為弓，九年來見，公曰：為弓亦遲，對曰：臣不得見公矣，曰：臣之精盡於弓矣，獻弓而歸，三日而死，公張弓登台，東西而射，矢逾孟霜之山，集彭城之東，其餘力逸劲，飲羽於石梁。","sortOrder":124},
  {"id":"s_work_nvlt_60_125","chapterId":"ch_work_nvlt_60","text":"《淮南子》曰：淇衛箘簵，［箘簵，箭竹也，出於淇地，衔箭羽。］飾以金銀錫，雖有薄縞之幨，然獨不能穿也，若假之筋角之力，弓弩之势，則貫兕甲而經於革楯矣。","sortOrder":125},
  {"id":"s_work_nvlt_60_126","chapterId":"ch_work_nvlt_60","text":"《新序》曰：楚熊渠夜行，見寢石，弯弓射之，没矢飲羽，下视知石也，却复射之。矢摧無跡，［事具地部石篇。］","sortOrder":126},
  {"id":"s_work_nvlt_60_127","chapterId":"ch_work_nvlt_60","text":"《東觀漢記》曰：蓋延，字巨卿，身長八尺，弯弓三百斤。","sortOrder":127},
  {"id":"s_work_nvlt_60_128","chapterId":"ch_work_nvlt_60","text":"張璠《漢記》曰：陳球為零陵太守，州兵朱蓋等反，球守城，絃大木為弓，羽矛為矢，機發之，遠射千餘人，［《太平御覽》三百四十七作步。］斬朱蓋等。","sortOrder":128},
  {"id":"s_work_nvlt_60_129","chapterId":"ch_work_nvlt_60","text":"《風俗通》曰：乌號弓者，柘桑之枝，枝條畅茂，乌登其上，乘下著地，乌適飛去，從後拨殺，取以為弓，因為乌號耳。","sortOrder":129},
  {"id":"s_work_nvlt_60_131","chapterId":"ch_work_nvlt_60","text":"《釋名》曰：矢，指也，其有所指向迅疾也。又謂之箭，箭，進也，其本曰足，矢形似木，木以下為本，以根為足，其末曰括，括，會也，與絃相會也。","sortOrder":131},
  {"id":"s_work_nvlt_60_132","chapterId":"ch_work_nvlt_60","text":"《說文》曰：矢，弓弩矢也，象鏑括羽之形。","sortOrder":132},
  {"id":"s_work_nvlt_60_133","chapterId":"ch_work_nvlt_60","text":"《世本》曰：夷牟作矢也。","sortOrder":133},
  {"id":"s_work_nvlt_60_134","chapterId":"ch_work_nvlt_60","text":"《太公兵法》曰：箭之神，名續長。","sortOrder":134},
  {"id":"s_work_nvlt_60_135","chapterId":"ch_work_nvlt_60","text":"《易》曰：絃木為弧，剡木為矢也。","sortOrder":135},
  {"id":"s_work_nvlt_60_136","chapterId":"ch_work_nvlt_60","text":"《周官》曰：庭氏，掌射國中之妖鳥，若不見其鳥獸，則以救日之弓，救月之矢，夜射之。","sortOrder":136},
  {"id":"s_work_nvlt_60_137","chapterId":"ch_work_nvlt_60","text":"《禮記》曰：故男子生，桑弧蓬矢六，以射天地四方，天地四方者，男子之所有事也，故必先有志於其所有事。","sortOrder":137},
  {"id":"s_work_nvlt_60_138","chapterId":"ch_work_nvlt_60","text":"《六韜》曰：陷堅陣，败強敵，大黃參連弩，飛凫電影自副，飛凫赤茎白羽，以鐵為首，電影青茎赤羽，以銅為首。","sortOrder":138},
  {"id":"s_work_nvlt_60_139","chapterId":"ch_work_nvlt_60","text":"《國語》曰：仲尼在陳，有隼集於陳侯之庭而死，楛矢貫之，石弩，其長尺有咫，陳惠公使人以隼如仲尼之馆問之，仲尼曰：此肅慎之矢也，昔武王克商，通道於九夷八蠻，肅慎氏貢楛矢石弩，以分大姬，配虞胡公，而封諸侯於陳。","sortOrder":139},
  {"id":"s_work_nvlt_60_140","chapterId":"ch_work_nvlt_60","text":"《孟子》曰：矢人豈不仁於函人哉，矢人唯恐不傷人，函人唯恐傷人。","sortOrder":140},
  {"id":"s_work_nvlt_60_141","chapterId":"ch_work_nvlt_60","text":"魯連子曰：齊田单破燕軍，复齊城，唯聊城不下，燕將守數月，魯仲連乃為書，著之於矢，以射城中，遺燕，［《太平御覽》三百五十燕下有將字。］燕將得書，泣三日，乃自殺。","sortOrder":141},
  {"id":"s_work_nvlt_60_142","chapterId":"ch_work_nvlt_60","text":"《韓子》曰：智伯將伐趙，趙襄子召張孟談曰：奈無箭何，孟談曰：董安於之治晉陽，公宮之垣，皆以楛楚，其楛高十尺，於是登而试之，其堅則幹之劲不能適也，君曰：奈無金何，孟談曰：董安於之治晉陽，宮舍之堂，皆以銅為柱质，君登而用之，有餘金矣。","sortOrder":142},
  {"id":"s_work_nvlt_60_143","chapterId":"ch_work_nvlt_60","text":"《淮南子》曰：楚王有白猿，王自射之，則摶矢而阜，［《太平御覽》三百五十作熙。］使養由基射之，始調弓矯矢，未發，而猿擁柱號矣。","sortOrder":143},
  {"id":"s_work_nvlt_60_144","chapterId":"ch_work_nvlt_60","text":"又曰：水激則旱，矢激則遠，夫淇衛箘簵，飾以銀錫，雖有薄縞之襜，然猶不能穿也，若假之弓弩之势，則貫兕甲革楯也。","sortOrder":144},
  {"id":"s_work_nvlt_60_145","chapterId":"ch_work_nvlt_60","text":"《漢書》曰：李陵击匈奴，一日五十萬矢皆盡，虜攻急，陵叹曰：复人數十矢，足以脱矣。","sortOrder":145},
  {"id":"s_work_nvlt_60_146","chapterId":"ch_work_nvlt_60","text":"《東觀漢記》曰：耿弇與張步戰，矢中弇眼，［《太平御覽》三百四十九作股。］以佩刀摧之，左右無知者。","sortOrder":146},
  {"id":"s_work_nvlt_60_147","chapterId":"ch_work_nvlt_60","text":"三齊略記曰：城東南五十里，有蒲台，高八丈，秦始皇所頓處，時在台下，萦蒲系馬，夹道數百步，到今蒲生猶萦，蒲似水楊而劲，堪為箭也。","sortOrder":147},
  {"id":"s_work_nvlt_60_148","chapterId":"ch_work_nvlt_60","text":"【贊】梁昭明太子弓矢贊曰：弓用筋角，矢製良工，亦以觀德，非止臨戎，傷葉命中，猿隨張空。","sortOrder":148},
  {"id":"s_work_nvlt_60_149","chapterId":"ch_work_nvlt_60","text":"【銘】後漢李尤弧矢銘曰：絃木為弧，剡木為矢，弧矢协併，八極同紀。","sortOrder":149},
  {"id":"s_work_nvlt_60_150","chapterId":"ch_work_nvlt_60","text":"晉嵇含木弓銘曰：乌號之朴，丰條足理，絃鳴走括，截飛駭止，射隼高牆，出有擬議，既用御武，亦以招士。","sortOrder":150},
  {"id":"s_work_nvlt_60_151","chapterId":"ch_work_nvlt_60","text":"晉李充良弓銘曰：弓矢之作，爰自曩時，乡射載禮，招命在詩，力稱顏高，功發由基，不爭之美，亦以詳疑。","sortOrder":151},
  {"id":"s_work_nvlt_60_152","chapterId":"ch_work_nvlt_60","text":"【啟】齊王融謝武陵王賜弓啟曰：殿下摛藻蕙樓，畅藝蘭苑，敷缋玉於風筵，叠連珠於月［《初學記》二十二下有的字，此脱。］兔園掩秀，鄴水慚奇，融揖讓未工，濫升飲之賞，操弧反矢，奉招賢之錫，文韜鏤景，逸幹梢雲，玩溢百齡，佩流千載。","sortOrder":152},
  {"id":"s_work_nvlt_60_154","chapterId":"ch_work_nvlt_60","text":"尚書帝今［《太平御覽》三百四十八作命。］验曰：玉弩發，驚天下。","sortOrder":154},
  {"id":"s_work_nvlt_60_155","chapterId":"ch_work_nvlt_60","text":"《釋名》曰：弩，怒也，有势怒之，鉤絃者牙以［御覽作似。］齒牙也，牙外曰郭，為牙郭也，含括之口曰機，言機之巧也，亦言如門戶之枢機，开阖有節。","sortOrder":155},
  {"id":"s_work_nvlt_60_156","chapterId":"ch_work_nvlt_60","text":"《史記》曰：庞涓追孫臏，臏量其暮當至馬陵，馬陵道狹，可伏兵，乃斫大树，白而書之曰：庞涓死此下，令萬弩夹道而伏，期曰：暮見火舉而俱發，庞涓夜至斫木，見白書，乃鑽火燭之，齊君萬弩俱發，庞涓自知智窮，乃自刎曰：遂成竖子之名。","sortOrder":156},
  {"id":"s_work_nvlt_60_157","chapterId":"ch_work_nvlt_60","text":"《史記》曰：項羽伏弩，射中漢王，傷焜，乃扪足曰：虜中吾指。","sortOrder":157},
  {"id":"s_work_nvlt_60_158","chapterId":"ch_work_nvlt_60","text":"古史考曰：黃帝作弩。","sortOrder":158},
  {"id":"s_work_nvlt_60_159","chapterId":"ch_work_nvlt_60","text":"《戰國策》曰：蘇秦為楚合從，元戎以鐵為矢，長八寸，一弩十矢俱發，［○按元戎以下系魏氏春秋文，見《太平御覽》三百四十八引，此有脱文。］","sortOrder":159},
  {"id":"s_work_nvlt_60_160","chapterId":"ch_work_nvlt_60","text":"《吳志》曰：甘寧招合輕薄少年，為之渠帥，群聚相隨，挟持弓弩，負毦帶鈴，民聞鈴聲，即知是寧也。","sortOrder":160},
  {"id":"s_work_nvlt_60_161","chapterId":"ch_work_nvlt_60","text":"《晉陽秋》曰：初高祖勒兵闕下，經曹爽門，爽帳下督嚴世，引弩將射高祖，孫謙止之曰：事未可知，三註三止，高祖車乃過。","sortOrder":161},
  {"id":"s_work_nvlt_60_162","chapterId":"ch_work_nvlt_60","text":"日南傳曰：南越王尉他［《太平御覽》三百四十八他下有攻字。］安陽王，有神人皋通，［御覽通下有為字。］安陽王治神弩一張，一發大［御覽作萬人二字。］死，三發殺三萬人。","sortOrder":162},
  {"id":"s_work_nvlt_60_163","chapterId":"ch_work_nvlt_60","text":"《華陽國志》曰：邓芝征涪陵，見玄猿抱子在树上，引弩射之，中猿母，其子為拔箭，以木葉塞創，芝乃叹曰：吾违物之性，其將死矣，投弩水中。","sortOrder":163},
  {"id":"s_work_nvlt_60_164","chapterId":"ch_work_nvlt_60","text":"《會稽典錄》曰：鍾離牧謂朱育曰：大皇帝以中國多騎，欲得騎而當之，然吳神鋒弩，射三里，貫洞三四馬，騎敢近之乎。","sortOrder":164},
  {"id":"s_work_nvlt_60_165","chapterId":"ch_work_nvlt_60","text":"《南越志》曰：龍川當［《太平御覽》三百四十八作嘗。］有銅弩牙流出水，皆所［御覽作以。］銀黃雕鏤，取之者祀而後得，父老雲，越王弩營處也。","sortOrder":165},
  {"id":"s_work_nvlt_60_166","chapterId":"ch_work_nvlt_60","text":"《太公兵法》曰：弩之神，名遠望。","sortOrder":166},
  {"id":"s_work_nvlt_60_167","chapterId":"ch_work_nvlt_60","text":"《文子》曰：狡兔得而獵犬死，高鳥得而強弩藏。","sortOrder":167},
  {"id":"s_work_nvlt_60_168","chapterId":"ch_work_nvlt_60","text":"《風俗通》曰：波［《太平御覽》三百四十八作汲。］令應郴，請主簿宣，賜酒，北壁上懸赤弩，照於杯中，其形如蛇，宣畏惡之，然不敢不飲，因得病，郴後知之，思惟必懸弩所為也，使致宣，於故處設酒，杯中猶有蛇，因謂曰：此壁上弩影耳，非有他怪，宣意解，病即愈，［事具方術部疾篇一。］","sortOrder":168},
  {"id":"s_work_nvlt_60_169","chapterId":"ch_work_nvlt_60","text":"蔡邕幽州刺史議曰：幽州突騎冀州弩，天下精兵，國家贍核，四方有事，未嘗不取辨不［字衍。］於二州也。","sortOrder":169},
  {"id":"s_work_nvlt_60_170","chapterId":"ch_work_nvlt_60","text":"【銘】後漢李尤弩銘曰：放自近古，發意所睹，前聖製弓，後世建弩，機牙發矢，執破丑虜，充獲雖屢，猶不可常，忘戰者危，極武者傷。","sortOrder":170},
  {"id":"s_work_nvlt_60_172","chapterId":"ch_work_nvlt_60","text":"《韓詩外傳》曰：楚莊王將興師伐晉，敢諫者罪至死，孫叔敖進諫曰：臣之國中有榆，其上有蝉，蝉方奋翼悲鳴，欲飲清露，不知螳螂在後，螳螂方欲食蝉，而又不知黃雀在後，黃雀方欲食螳螂，不知童子挟彈丸在榆下，童子欲彈黃雀，不知前有深坑，後有掘株也，皆貪前之利，不顧後害也，楚國不征，而晉國以寧，孫叔敖之力也。","sortOrder":172},
  {"id":"s_work_nvlt_60_173","chapterId":"ch_work_nvlt_60","text":"《左傳》曰：晉靈公從台上彈人，觀其避丸也。","sortOrder":173},
  {"id":"s_work_nvlt_60_174","chapterId":"ch_work_nvlt_60","text":"《吳越春秋》曰：陳音對越王雲，弩生於弓，弓生於彈，彈生於古之孝子，古者人民质朴，死裹以白茅，投之中野，孝子不忍父母為禽獸所食，則作彈以守之，故古人歌之，斷竹屬木，飛土逐害。","sortOrder":174},
  {"id":"s_work_nvlt_60_175","chapterId":"ch_work_nvlt_60","text":"張璠《漢記》曰：班超使於外，原將三十六人，以為蒿矢彈丸之用。","sortOrder":175},
  {"id":"s_work_nvlt_60_176","chapterId":"ch_work_nvlt_60","text":"《東方朔記》曰：東方朔對驃騎難曰：以珠彈，不如泥丸，各有所用也。","sortOrder":176},
  {"id":"s_work_nvlt_60_177","chapterId":"ch_work_nvlt_60","text":"《太玄經》曰：明珠彈於飛害，其复［《太平御覽》三百五十作得。］不复。","sortOrder":177},
  {"id":"s_work_nvlt_60_178","chapterId":"ch_work_nvlt_60","text":"《世說》曰：前辈人忌日，惟不飲酒作樂，王世將以忌日送客，至新亭，主人欲作音樂，王便起去，持彈往衛洗馬墓下彈鳥。","sortOrder":178},
  {"id":"s_work_nvlt_60_179","chapterId":"ch_work_nvlt_60","text":"萧子顯《齊書》曰：桓崇祖善彈，彈鳥毛盡而鳥不死，海鵠群翔，崇祖登城樓彈之，無不折翅。","sortOrder":179},
  {"id":"s_work_nvlt_60_180","chapterId":"ch_work_nvlt_60","text":"【詩】晉桓玄南林彈詩曰：散帶躡良驷，揮彈出長林，歸翮赴舊栖，乔木轉翔禽，落羽尋絕响，屢中轉應心。","sortOrder":180},
  {"id":"s_work_nvlt_60_181","chapterId":"ch_work_nvlt_60","text":"【賦】晉夏侯孝若繳彈賦曰：張弱弓，理繁繳，望大群以送丸，審遣放而必獲。","sortOrder":181},
  {"id":"s_work_nvlt_60_182","chapterId":"ch_work_nvlt_60","text":"【銘】後漢李尤彈銘曰：昔之造彈，起意絃木，以丸為矢，合竹為朴，漆飾以霑，不用筋角，丸彈之利，以弋凫鶩，晉靈驕悖，群臣是彈，樂其如躍，趨如避丸。","sortOrder":182},
  {"id":"s_work_nvlt_60_184","chapterId":"ch_work_nvlt_60","text":"《通俗文》曰：矛丈八者謂之槊。","sortOrder":184},
  {"id":"s_work_nvlt_60_185","chapterId":"ch_work_nvlt_60","text":"《後魏書》曰：於栗磾筑壘於河上，親自守焉，裕甚憚之，遺栗磾書，假道西上，題書曰黑槊公麾下，栗磾以聞太宗，太宗因授黑槊將軍。","sortOrder":185},
  {"id":"s_work_nvlt_60_186","chapterId":"ch_work_nvlt_60","text":"《靈鬼志》曰：河間王顒，既败於關中，有給使陳安者，常乘一赤馬，俊快非常，双持二刀，皆長七尺，馳馬運刀，所向披靡，關西為之歌曰：垄上健兒字陳安，頭細面狹腸中宽，丈八大槊左右盤。","sortOrder":186},
  {"id":"s_work_nvlt_60_187","chapterId":"ch_work_nvlt_60","text":"【詩】晉傅玄詩曰：弯我繁弱弓，弄我丈八槊，一舉覆三軍，再舉殄戎貊。","sortOrder":187},
  {"id":"s_work_nvlt_60_188","chapterId":"ch_work_nvlt_60","text":"【書】晉庾翼與燕王書曰：今致朱漆銏三十張，絳碧書幡黑眊副也。","sortOrder":188},
  {"id":"s_work_nvlt_60_189","chapterId":"ch_work_nvlt_60","text":"【序】梁簡文帝馬槊譜序曰：馬槊為用，雖非遠法，近代相傳，槊已成藝，邓蔍榮［《太平御覽》三百五十四作蔗萦。］魏後之逢，［御覽作庭。］武而猶质，种［御覽作桓。］馬入丹陽之寺，雄而未巧，聊以餘暇，复撰斯法，援操抑扬，斟酌煩簡，至春亭落景，秋皋晚靜，嚴霜盡降，密雨初暗，［御覽作晴。］纖驪沃若，天馬半盼，［御覽作漢。］叹［御覽作盼。］金精而轉態，交流汗血，愛連乾而自息，不畏衣，［御覽衣下有春字。］鏤衢與白刃暉，［御覽暉上有爭字，此脱。］翠眊與紅尘俱動，足使武夫憤氣，觀者冲冠，巴童留玩，不待輕舟之楫，越女踟蹰，無假如皋之箭。","sortOrder":189},
  {"id":"s_work_nvlt_60_190","chapterId":"ch_work_nvlt_60","text":"《藝文類聚》　唐·欧陽詢","sortOrder":190},
  {"id":"s_work_nvlt_61_1","chapterId":"ch_work_nvlt_61","text":"卷六十一居處部一","sortOrder":1},
  {"id":"s_work_nvlt_61_2","chapterId":"ch_work_nvlt_61","text":"○總載居處","sortOrder":2},
  {"id":"s_work_nvlt_61_3","chapterId":"ch_work_nvlt_61","text":"◇總載居處","sortOrder":3},
  {"id":"s_work_nvlt_61_4","chapterId":"ch_work_nvlt_61","text":"《易》曰：上古穴居而野處，後世聖人，易之以宮室，上棟下宇，以待風雨。","sortOrder":4},
  {"id":"s_work_nvlt_61_5","chapterId":"ch_work_nvlt_61","text":"《楚辭》曰：像設居室靜閒安，高堂邃宇槛層軒，層台累榭臨高山，網戶朱缀刻方連，冬有突夏［《太平御覽》一百七十四作奧突，後同。］夏室寒，經堂入奧朱尘筵，［承尘筵席也。］砥室翠翘掛曲琼，蒻阿拂壁羅帱張，翠帷翠帱飾高堂，紅壁沙板玄玉梁，仰觀刻桷畫龍蛇，坐堂伏槛臨曲池，芙蓉始發雜芰荷，紫茎屏風文绿波。","sortOrder":5},
  {"id":"s_work_nvlt_61_6","chapterId":"ch_work_nvlt_61","text":"又曰：筑室兮水中，葺之兮以荷蓋，荃壁兮紫壇，播芳椒兮成堂，桂棟兮蘭橑，辛夷楣兮藥房。","sortOrder":6},
  {"id":"s_work_nvlt_61_7","chapterId":"ch_work_nvlt_61","text":"《鹽鐵論》曰：貴人之家，梓匠斫巨為小，以圓為方，上成雲氣，下成山林。","sortOrder":7},
  {"id":"s_work_nvlt_61_8","chapterId":"ch_work_nvlt_61","text":"《漢武故事》曰：上起神屋，鑄銅為柱，黃金涂之，赤玉為階，椽亦以金，刻玳瑁為禽獸，以薄其上，椽首皆作龍首，衔鈴，流蘇懸之，鑄銅如竹，以赤白石脂為泥，椒汁和之，以火齊薄其上，扇屏悉以白琉璃作之，光照洞彻，以白珠為帘薄，玳瑁壓之，以象牙為床，以琉璃珠玉明月夜光，雜错天下珍寶為甲帳，其次為乙帳，甲以居神，乙上自御之，前庭植玉树，珊瑚為枝，以碧玉為葉，或青或赤，悉以珠玉為之，子皆空其中，如小鈴，鎗鎗有聲，甍摽作鳳皇，軒翥若飛状。","sortOrder":8},
  {"id":"s_work_nvlt_61_9","chapterId":"ch_work_nvlt_61","text":"《漢書》曰：趙皇後娣為昭儀，居昭陽舍，其中庭彤采，而砌皆銅沓黃金涂，白玉階，壁帶往往為黃金棋函，藍田璧明珠翠羽飾之。","sortOrder":9},
  {"id":"s_work_nvlt_61_10","chapterId":"ch_work_nvlt_61","text":"又曰：五侯大治第宅，起土山漸台，洞門高廓［漢書九十八元後傳作廊。］閣道，百姓歌之曰：五侯初起，曲陽家［漢書作最。］怒，坏决高都，［决高都，使水入長安城，高都在城西。］連竟外杜，［杜陵也。］成都侯商嘗病，欲避暑，從上借明光宮。又穿長安城，引內漕水以行舡，立羽蓋，張周帷，楫擢越歌，上幸商第，見赤墀青琐。","sortOrder":10},
  {"id":"s_work_nvlt_61_11","chapterId":"ch_work_nvlt_61","text":"又曰：梁孝王筑東苑，方三百里，廣睢陽城七十里，大治宮室，為複道，自宮連屬於平台，三十餘里。","sortOrder":11},
  {"id":"s_work_nvlt_61_12","chapterId":"ch_work_nvlt_61","text":"《東觀漢記》曰：琅邪孝王京就國都，雅好宮室，窮極技巧，壁帶玉飾以金銀。","sortOrder":12},
  {"id":"s_work_nvlt_61_13","chapterId":"ch_work_nvlt_61","text":"張璠《漢記》曰：山陽督郵張俭，奏中常侍侯覽，起第十六區，皆高樓四周，連閣洞門，文井莲華，璧柱采畫，魚池台苑，擬諸宮闕。","sortOrder":13},
  {"id":"s_work_nvlt_61_14","chapterId":"ch_work_nvlt_61","text":"《董生書》曰：禮，天子之宮在清廟，左涼室，右明堂，後路寢，四室者，足以避寒暑而不高大也，夫高近陽，廣室多陰，故室適形而正。","sortOrder":14},
  {"id":"s_work_nvlt_61_15","chapterId":"ch_work_nvlt_61","text":"仲長《昌言》曰：今為宮室者，崇台數十層，長階十百仞，延袤臨浮雲，上树九丈旗，珠玉翡翠以為飾，連帷為城，構帳為宮，起台树則高數百丈，壁帶珠玉，土被緹錦。","sortOrder":15},
  {"id":"s_work_nvlt_61_16","chapterId":"ch_work_nvlt_61","text":"曹植表曰：詔使周觀，初玩雲盤，北觀疏圃，遂步九華，神明特處，譎诡天然，誠可謂帝室皇居者矣，雖崑崙阆風之麗，文昌之居，不是過也。","sortOrder":16},
  {"id":"s_work_nvlt_61_17","chapterId":"ch_work_nvlt_61","text":"羅含別傳曰：桓宣武以含為別駕，以官廨寺喧扰，非靜默所處，乃於城西池小洲上，立茅茨之屋，竹果荫宇，戕木之床，織苇為席，布衣蔬食，晏若有餘。","sortOrder":17},
  {"id":"s_work_nvlt_61_18","chapterId":"ch_work_nvlt_61","text":"【詩】陳孔奐名都一何綺詩曰：京洛信名都，佳麗擬蓬壶，九華彫玳瑁，百福上椒涂，黃金絡騕褭，莲花裝鹿盧，鹹言儀服盛，無勝執金吾，陳沈蜅名都一何綺詩曰：名都一何綺，春日吐光辉，高樓雲母扇，複殿琉璃扉，昭儀同輦出，高安連騎歸，欲知天子貴，千門應紫微。","sortOrder":18},
  {"id":"s_work_nvlt_61_19","chapterId":"ch_work_nvlt_61","text":"陳周弘正詩曰：名都宮觀綺，金壁藻華璫，吹台望鳷鵲，舞殿接披香，繡轂遊丹水，彫輦出平陽，陆離徒照眼，何解忧人傷。","sortOrder":19},
  {"id":"s_work_nvlt_61_20","chapterId":"ch_work_nvlt_61","text":"【賦】漢楊雄蜀都賦曰：蜀都之地，古曰梁州，禹治其江，渟皋弥望，鬱乎青葱，丹鳳青龍，石亸水螭，於近則有瑕英菌芝，玉石江珠，於遠則有銀鉛錫碧，馬犀象僰，西有鹽泉鐵冶，橘林銅陵，其傍則有期牛光旄，金馬碧雞，其竹則宗生族攒，俊茂丰美，夹江緣山，尋卒而起，其深則有猵獭沉鱔，水豹蛟蛇，其都門二九，四百餘闾，兩江飾其市，九桥帶其流，苴竹浮流，龟鱉碛石，風胎雨鷇，眾物駭目，百華投春，隆急芳芬，螭燭若揮，錦布繡望，芒芒兮無幅，其布則筩中黃润，一端數金，雕鏤鉛器，百技千工，上乃使有伊之徒，調夫五味，甘甜之和，勺藥之羹，江東鲐鮑，隴西牛羊，五肉七菜，朦厭腥臊，若其吉日嘉會，期於倍春之陰，迎夏之陽，置酒於榮川之間宅，設坐於華都之高堂，延帷扬幕，接帳連岡，郄［《文選》四蜀都賦劉逵註作郤。］公之徒，相與如平［○《文選》四南都賦註作乎。］陽氵潁［南都賦註作瀕。］臣詔，［蜀都賦劉註作巨野。］羅車百乘，期會投宿，觀者方防，行舡競逐也。","sortOrder":20},
  {"id":"s_work_nvlt_61_21","chapterId":"ch_work_nvlt_61","text":"後漢班固西都賦曰：賦者古詩之流，或以抒下情而通諷諭，或以宣上德而盡忠孝，雍容揄扬，亦雅頌之亚也，西土耆老，有陋洛邑之議，故臣作兩都之賦，漢之西都，在乎雍州，左據函穀二崤之阻，表以太華終南之山，右界褒斜隴首之险，帶以洪河涇渭之川，披三條之廣路，立十二之通門，英俊之域，绂冕所興，冠帶如雲，七相五公，其陽則崇山隱天，幽林空穀，陆海珍藏，藍田美玉，其陰則冠以九嵕，陪以甘泉，下有鄭白之沃，衣食之源，提封五萬，疆埸綺分，溝塍刻鏤，原隰龍鱗，决渠降雨，荷锸成雲，離宮別馆，神池靈沼，其中則有九真之鱗，大宛之馬，黃支之犀，條枝之鳥，其宮室也，體象乎天地，經緯乎陰陽，树中天之華闕，丰冠山之朱堂，因朅材而究奇，抗應龍之虹梁，列棼橑以布翼，荷棟桴而高驤，彫玉瑱以居楹，裁金璧以飾璫，左墄［仓勒反，階級也。］右平，重軒三階，閨房周通，門闼洞开，列鍾虡於中庭，立金人於端闈，增盤崔嵬，登降炤烂，殊形诡製，每各異觀，乘茵步輦，唯所息宴，後宮則有掖庭椒房後妃之室，茝若椒風，披香發越，蘭林蕙草，鴛鸞飛翔之列，昭陽特盛，隆乎孝成，隨侯明月，错落其間，金棋衔璧，是為列錢，翡翠火齊，流燿含英，珊瑚碧树，周阿而生，後宮之號，十有四位，窈窕繁華，更盛迭貴。又有天祿石渠典籍之府，講論乎六藝，稽合乎異同，周以鉤陳之位，衛以嚴更之署，周庐千列，徼道綺错，輦路經營，脩途飛閣，堎墱道而超西墉，混建章而連外屬，神明［台名也。］鬱其特起，遂偃蹇而上跻，軼雲雨於太半，虹霓回帶於棼楣，攀井幹而未半，目眩轉而意迷，靈草冬華，神木丛生，抗仙掌以承露，擢双立之金茎，爾乃盛娱遊之壮觀，曜威靈而講武事，命荆州使起鳥，詔梁野而驅獸，毛群肉填，飛羽上覆，列卒周匝，星羅雲布，矢不单殺，中必叠双，風毛雨血，洒野蔽天，於是天子乃登屬玉之馆，歷長楊［上林也。］之榭，陳輕騎以行炰，騰酒車以斟酌，割鮮野饗，舉烽命爵，大辂鳴鑾，容與徘徊，集乎豫章之宇，臨乎崑明之池，左牵牛而右織女，似雲漢之無涯。茂树陰蔚，芳草被隄，若摛錦與布繡，燭燿乎其陂，玄鶴白鷺，凫鹥鸿雁，沉浮往來，雲集霧散，鬱鬱相望，邑邑相屬，國籍十世之基，家承百年之業。","sortOrder":21},
  {"id":"s_work_nvlt_61_22","chapterId":"ch_work_nvlt_61","text":"又東都賦曰：王莽作逆，漢祚中缺，於是聖皇握乾符，辟坤珍，披皇圖，稽帝文，赫然發憤，應若興雲，遂超大河，跨北嶽，立號高邑，建都河洛，系唐統，接漢緒，茂育群生，恢复彊宇，若乃順時節而蒐狩，簡車徒以講武，歷騶虞，覽驷鐵，嘉車攻，采吉日，禮官整儀，乘舆乃出，於是發鯨魚，铿華鍾，登玉辂，乘時龍，元戎竟野，戈鋋彗雲，羽毛扫蜺，旌旗拂天，然後舉烽伐鼓，申令三驅，輕車霆激，驍騎電骛，指顧倏忽，獲車已實，樂不極般，殺不盡物，於是荐三犧，效五牲，禮神祇，懷百靈，觐明堂，臨辟雍，登靈台，考休徵，列百僚而贊群後，究皇儀而展帝容。","sortOrder":22},
  {"id":"s_work_nvlt_61_23","chapterId":"ch_work_nvlt_61","text":"明堂詩曰：於昭明堂，明堂孔陽，聖皇宗祀，穆穆煌煌。","sortOrder":23},
  {"id":"s_work_nvlt_61_24","chapterId":"ch_work_nvlt_61","text":"辟雍詩曰：乃流辟雍，辟雍湯湯，聖皇莅止，造舟為梁。","sortOrder":24},
  {"id":"s_work_nvlt_61_25","chapterId":"ch_work_nvlt_61","text":"靈台詩曰：三光宣精，五行布序，習習祥風，祁祁甘雨。","sortOrder":25},
  {"id":"s_work_nvlt_61_26","chapterId":"ch_work_nvlt_61","text":"寶鼎詩曰：嶽脩貢兮川效珍，吐金景兮敲浮雲，寶鼎見兮色紛紜，煥其炳兮被龍文。","sortOrder":26},
  {"id":"s_work_nvlt_61_27","chapterId":"ch_work_nvlt_61","text":"白雉詩曰：啟靈篇兮披瑞圖，獲白雉兮效素乌，嘉祥阜兮集皇都，發皓羽兮奋翘英。","sortOrder":27},
  {"id":"s_work_nvlt_61_28","chapterId":"ch_work_nvlt_61","text":"後漢張衡西京賦曰：昔班固睹世祖遷都於洛邑，懼將必逾溢製度，不能遵先聖之正法也，故假西都賓盛稱長安舊製，有陋洛邑之議，而為東都主人折禮衷以答之，張平子薄而陋之，故更造焉，有凭虛公子者，［無此公子，但依凭言之。］言於安處先生曰：［亦無此先生也。］秦據雍而強，周即豫而弱，高祖都西而泰，光武處東而約，先生獨不聞西秦之事欤，漢氏初都，在渭之涘，秦里其朔，寔為鹹陽，［里，居，朔，北也，高帝六年，改曰長安。］左有崤函重险，桃林之塞，缀以二華，巨靈贔屃，高掌遠蹠，以流河曲，厥跡猶存，右有隴坻之隘，隔閡華戎，岐梁汧雍，［皆山名。］陳寶鳴雞在焉，於前則終南大一，隆嚬崔崒，隱辚鬱律，連岡兮嶓冢，爰有藍田珍玉，是之自出，於後則高陵平原，據渭踞涇，其遠則九嵕甘泉，固陰沍寒，日北至而含冻，此焉清暑，寔為地之奧區神皋，昔者太帝悅秦穆公而觐之，饗以鈞天廣樂，帝有醉焉，乃為金策，錫用此土，而剪諸鶉首，自我高祖之始入也，乃覽秦製，跨周法，正紫宮於未央，表峣闕於閶阖，疏龍首以抗殿。状嵬瓘以岌嶪，蒂倒茄於藻井，披紅葩之狎獵，飾華榱與璧璫，流景曜之暐晔，彫楹玉磶，繡栭雲楣，三階重軒，鏤槛文〈媲\"女改木\"〉，右平左墄，青琐丹墀，仰福帝居，陽曜陰藏，洪鍾萬鈞，猛虡趪々，負筍業而餘怒，乃奋翅而騰驤，若夫長年神仙，宣室玉堂，麒麟朱鳥，龍興含章，正殿路寢，用朝群辟，嘉木树庭，芳草如積，高門有闶，列坐金狄，［秦時長狄見於臨洮，鑄銅作其象。］後宮則昭陽飛翔，增成合歡，蘭林披香，鳳皇鴛鴦，［皆後宮殿名。］故其馆室次舍，采飾纖縟，總以藻繡，文以朱绿，翡翠火齊，絡以美玉，流懸黎之夜光，缀隨珠以為燭，於是鉤陳之外，閣道穹隆，屬長樂與明光，径北通乎桂宮，恣意所幸，下輦成燕，窮年忘歸，猶不能遍，覛［音脈。］往昔之遺馆，獲林光於秦餘，處甘泉之爽垲，乃隆崇而弘敷，既新作於迎風，增露寒與储胥，通天眇以竦峙，径百常而茎擢，翔鵾仰而不建，［《文選》二西京賦作逮。］况青鳥與黃雀，伏櫺槛而俯聽，聞雷霆之相激，柏梁既灾，越巫陳方，建章是經，用厭火祥，圜闕竦以造天，若双碣之相望，鳳騫翥於甍標，鹹溯風而欲翔，幹雲霧而上達，状亭亭以迢迢，神明嚬其特起，井幹叠而百層，上飛闼而仰眺，正睹瑤光與玉繩，列瀛洲與方丈，夹蓬萊而骈羅，長風激於別島，起洪涛而颺波，海若遊於玄渚，鯨魚失流而蹉跎，立脩茎之仙掌，承雲表之清露，屑琼蕊以朝餐，必性命之可度，爾乃廓开九市，通闤帶阓，旗亭五重，俯察百隧，［隧，列肆道也。］上林禁苑，跨穀弥阜，東至鼎湖，邪界細柳，掩長扬而聯五柞，繞黃山而款牛首，乃有崑明靈沼，黑水玄沚，周以金隄，树以柳杞，豫章珍馆，揭焉中跱，牵牛立其左，織女處其右，日月於是乎出入，象扶桑與濛汜，其魚則鲔鲵鲿魦，脩額短項，大口折鼻，诡類殊种，鳥則鷫鹴鴰鴇，鴐鹅鸿鶤，南翔衡陽，北栖雁門，於是孟冬作陰，寒風肅殺，雨雪飄飖，冰霜惨烈，天子乃駕雕軫，六駿駮，戴翠帽，倚金较，華蓋承辰，天罼先驅，千乘雷動，萬騎龍趨。縱獵徒，赴長莽，迾卒清候，武士赫怒，河渭為之波荡，吳嶽為之阤堵，百禽忄夌遽，骙瞿奔觸，丧精亡魂，失歸忘趣，矢不虛舍，鋋不苟躍，當足見蹍，值輪被轹，乃使迅羽輕足，尋景追括，鳥不暇舉，獸不得發，青骹挚於韝下，韓盧噬於緤末。於是鳥獸殫，目觀窮，遷延邪睨，集乎長楊之間，酒車酌醴，方駕授邕，升觴舉燧，既釂鳴鍾，儴佯乎五柞之馆，旋憩乎崑明之池，浮鹢首，翳雲芝，垂翟葆，建羽旗，齊栧女，縱棹歌，奏淮南，度陽阿，大駕幸乎平樂，張甲乙而袭翠被，臨回註之廣場，程角抵之妙戲，乌獲扛鼎，都盧尋橦，冲狹燕濯，焜突銛鋒，跳丸劍之揮霍，走索上而相逢，度曲未終，雲起雪飛，巨獸百尋，是為曼延，神山崔嵬，欻從背見，白象行孕，垂鼻辚囷，海鱗变而成龍，状蜿蜿以蝹々，［於雲反，龍形貌。］含利［獸名，性，○《文選》二西京賦註性下有吐金二字。］颬々，化為仙車，驪駕四鹿，芝蓋九葩，奇幻倏忽，易濬分形，吞刀吐火，雲霧杳冥，畫地成川，流渭通涇，百馬同辔，騁足併馳，撞末之妓，態不可弥，秘舞更奏，妙材騁妓，始徐進而羸形，似不任乎羅綺，紛縱體而迅赴，若驚鶴之群羆，要紹修態，麗服颺菁，昭邈流盼，一顧傾城，列爵十四，競媚取榮，盛衰無常，唯愛所丁，衛後興於鬒發，飛燕寵於輕體。又東京賦曰：是時也，七雄併爭，競相高以奢麗，楚筑章華於前，趙建丛台於後，秦政利觜長距，終得擅場，思专其侈，以莫己若也，乃構阿房，起甘泉，結雲閣，觀南山，百姓不能忍，是用息肩於大漢，高祖應錄受圖，順天行誅，扫項軍於垓下，绁子婴於轵途，因秦宮業，據其府库，且夫天子有道，狩在海外，守位以仁，不恃隘害，秦負阻於二關，卒开項而受沛，彼偏據而規小，豈若宅中而圖大，昔先王之經邑也，掩觀九隩，靡地不營，土圭测影，不縮不盈，總風雨之所交，然後以建王城，審曲面势，溯洛背河，左伊右瀍，西阻九阿，盟津達其後，大穀通其前，回行道乎伊闕，斜径捷乎轘轅，太室作镇，揭以熊耳，厎柱輟流，鐔以大岯，漢初弗之宅也，故宗緒中圮，巨猾間衅，竊弄神器，歷載三六，偷安天位，我世祖忿之，乃龍飛白水，鳳翔參墟，授鉞四七，共工是除，區宇乂寧，思和求中，睿哲玄覽，都茲洛宮，逮至顯宗，六合殷昌，既新崇德，遂作德陽，昭仁惠於崇賢，抗義聲於金商，建象魏之兩觀，旌六典之舊章，濯龍芳林，九穀八谿，芙蓉覆水，秋蘭被涯，永安離宮，修竹冬青，陰池幽流，玄泉冽清，鵯鶋秋栖。鶻雕春鳴，鵙鳩鸝黃，關關嘤嘤，於南則前殿雲台，和懽安福，謻門曲榭，斜阻城洫，奇树珍果，鉤盾所職，於東則洪池清篽，渌水澹澹，內阜川禽，外丰葭菼，其西則平樂都場，示遠之觀，龍雀蟠蜿，天馬半漢，乃營三宮，布政頒常，複廟重屋，於斯胥洎，龍辂充庭，雲旗拂蜺，夏正三朝，庭燎晢晢，［章列反。］春日載陽，合射辟雍，設業設虡，宮懸金镛，鼖［音汾。］鼓路鼗，［音桃。］树羽幢幢，張大侯，製五正，設三乏，厞［音翡。］司旌，天子乃撫玉辂，時承六龍，發鯨魚，铿華鍾，攝提運衡，徐至於射宮，禮事展，樂物具，王夏阕，騶虞奏，决拾既次，彫弓斯彀，［古侯反。］達餘萌於暮春，昭誠心以遠喻，三農之隙，耀威中原，歲惟仲冬，大閱西園，乃馭小戎，撫輕軒，戈矛若林，牙旗繽翻，迄乎上林，結徒為營，叙和树表，司铎授鉦，坐作進退，節以軍聲，火烈具舉，武士星敷，鹅鸛魚麗，箕張翼舒，馭不诡遇，射不翦毛，升獻六禽，時膳四膏，成禮三驅，解罘放麟，不窮樂以訓俭，不殫物以昭仁，爾乃卒歲大傩，驅除群癘，侲子萬童，丹首玄製，桃弧棘矢，所發無臬，飛砾雨散，刚瘅必毙，煌火馳而星流，逐赤疫於四裔。","sortOrder":28},
  {"id":"s_work_nvlt_61_29","chapterId":"ch_work_nvlt_61","text":"又南都賦曰：於顯樂都，既麗且康，陪京之南，居漢之陽，剖周楚之丰壤，跨荆豫而為疆，其寶利珍怪，則金采玉璞，隋珠夜光，太一餘糧，中黃瑴玉，松子神陂，赤靈解角，耕父扬光於清泠之泉，遊女弄珠於漢皋之曲，其水虫則有蠳龟鳴蛇，潛龍伏螭，其鳥則有鴛鴦鵠鹥，鸿鴇鴐鹅，嘤嘤和鳴，澹澹隨波，其香草則薜荔蕙若，{艹糜}芜荪萇，晻暧蓊蔚，含芬吐芳，酒則九醞甘醴，十旬兼清，醪敷径寸，浮虮若萍，其甘不爽，醉而不酲，獻酢既交，率禮無违，彈琴析籥，流風徘徊，於是暮春之禊，元巳之辰，方軌齊軫，祓［音弗。］於陽濱，朱帷連網，曜野映雲，脩岫繞缭而滿庭，羅穇躡蹀而容與，翩綿綿其若絕，眩將墜而复舉，於是群士放逐，馳乎沙場，俯貫鲂鱮，仰落双鸧，魚不及竄，鳥不暇翔，車雷震而風厲，馬鹿超而龍驤，夕暮而歸，其樂難忘。","sortOrder":29},
  {"id":"s_work_nvlt_61_30","chapterId":"ch_work_nvlt_61","text":"後漢杜篤論都賦曰：天命有聖，讬之大漢，大漢开基，高祖有勋，斬白蛇，屯黑雲，蹈沧海，跨崑崙，劉敬建策，初都長安，太宗承流，守之以文，孝武因其餘财，府帑之畜，深入匈奴，割裂三庭，連缓耳，鎖雕題，摧天竺，拏象犀，沃野千里，原隰弥望，保植五穀，桑麻條畅，濱據南山，帶以涇渭，號曰陆海，蠢生萬類，城池百尺，阨塞要害，一人奋戟，三軍沮败，於時聖帝，赫然申威，南禽公孫，北胁強胡，西平隴冀，東據洛都，今天下新定，矢石之勤始瘳，未遑於論都，而遺思雍州。","sortOrder":30},
  {"id":"s_work_nvlt_61_31","chapterId":"ch_work_nvlt_61","text":"後漢崔骃反都賦曰：漢歷中絕，京師為墟，光武受命，始遷洛都，客有陳西土之富，雲洛邑褊小，故略陳禍败之機，不在险也，建武龍興，奋旅西驅，虜赤眉，讨高胡，斬銅馬，破骨都，收翡翠之駕，據天下之圖，上聖受命，將昭其烈，潛龍初九，真人乃發，上貫紫宮，徘徊天闕，握狼狐，蹈參伐，陶以乾坤，始分日月，觀三代之餘烈，察殷夏之遺風，背崤函之固，即周洛之中，興四郊，建三雍，禪梁父，封岱宗。","sortOrder":31},
  {"id":"s_work_nvlt_61_32","chapterId":"ch_work_nvlt_61","text":"後漢傅毅洛都賦，惟漢元之運會，世祖受命而弭亂，體神武之聖姿，握天人之契贊，尋往代之規兆，仍险塞之自然，被崑崙之洪流，據伊洛之双川，挟成皋之嚴阻，扶二崤之崇山，分畫經緯，开正涂軌，序立廟祧，面朝後市，叹息起雰霧，奋袂生風雨，覽正殿之體製，承日月之皓精，騁流星於突陋，追歸雁於軒軨，帶螭龍之疏鏤，垂菡萏之敷榮，顧濯龍之台觀，望永安之園藪，渟清沼以汎舟，浮翠虬與玄武，桑宮茧馆，區製有矩，後帥九嫔，躬敕工女，近則明堂辟雍靈台之列，宗祀扬化，雲物是察，其後則有長岡芒阜，屬以首山，通穀岌岢，石瀨寒泉，於是乘舆鳴和，按節發轫，列翠蓋，方龍辀，備五路之時副，槛三辰之旗斿，傅說作仆，羲和奉時，千乘雷駭，萬騎星鋪，絡驿相屬，揮沫扬鑣，群仙列於中庭，發魚龍之巨伟，羨門拊鼓，偓佺操麾，講武農隙，校獵因田，搜幽林以集禽，激通川以御獸，跨乘黃，射遊麋，絃不虛控，目不徒睎，解腋分心，應箭殪夷，然後弭節容與，渌水之濱，垂芳餌於清流，出旋瀨之潛鱗。","sortOrder":32},
  {"id":"s_work_nvlt_61_33","chapterId":"ch_work_nvlt_61","text":"魏徐幹齊都賦曰：齊國實坤德之膏腴，而神州之奧府，其川渎則洪河洋洋，發源崑崙，驚波沛厲，浮沫扬奔，南望無垠，北顧無鄂，蒹葭蒼蒼，莞菰沃若，瑰禽異鳥，群萃乎其間，戴華蹈縹，披紫垂丹，應節往來，翕習翩翻，靈芝生乎丹石，發翠華之煌煌，其寶玩則玄蛤抱璣，駮〈虫半〉含璫，構厦殿以宏覆，起層榭以高驤，龍楹螭桷，山{巳山}雲牆，其後宮內庭，嫔妾之馆，眾伟所施，極巧窮变，然後脩龍榜，遊洪池，折珊瑚，破琉璃，日既仄而西舍，乃反宮而栖遲，歡幸在侧，便嬖侍隅，含清歌以詠志，流玄眸而徵眄，竦長袖以合節，紛翩翻其輕迅，王乃乘華玉之辂，駕玄駮之駿，武騎星散，鉦鼓雷動，旌旂虹亂，盈乎靈圃之中，於是羽族鹹興，毛群盡起，上蔽穹庭，下被皋藪。","sortOrder":33},
  {"id":"s_work_nvlt_61_34","chapterId":"ch_work_nvlt_61","text":"魏劉楨魯都賦曰：昔大廷氏肇建厥居，少昊受命，亦都茲焉，山則連岡屬嶺，曀〈鬼分〉峡北，紫金扬暉於鸿崖，水精潛光乎雲穴，岱宗邈其層秀，幹氣霧以高越，其木則赤桋青松，文茎蕙棠，洪幹百围，高径穹皇，竹則填彼山垠，陔弥阪域，夏簜攒包，劲條併殖，翠實離離，鳳皇攸食，水產眾夥，各有彝倫，頒首華尾，丰顱重龂，戴兵挟刃，盤甲曲鱗，且觀其時謝節移，和族綏宗，招歡合好，肅戒友朋，蛾眉清眸，顏若雪霜，插曜日之珍笄，珥明月之珠璫，舞人就列，整飾容華，和顏扬眸，眄風長歌，飄乎猋發，身如轉波，尋虛騁跡，顧與節和，縱脩袖以終曲，若奔星之赴河，及其素秋二七，天漢指隅，民胥祓禊，國於水遊，緹帷弥津，丹帳覆洲，蓋如飛鶴，馬如遊魚，應門巖巖，朱扉含光，路殿巋其隆崇，文陛巘其高驤，聽迅雷於長除，若有聞而复亡，其園囿苑沼，骈田接連，渌池分浪，以帶石垠，文隅琼岸，華玉依津，邦乃大狩，振扬炎威，教民即戎，講習興師，落幕包括，連結營围，毛群陨殪，羽族殲剝，填崎塞畎，不可勝錄。","sortOrder":34},
  {"id":"s_work_nvlt_61_35","chapterId":"ch_work_nvlt_61","text":"魏劉邵趙都賦曰：且敝邑者，固靈州之敞宇，而天下之雄國，南則有洪川巨渎，黃水濁河，發河積石，径拂太華，洒為九流，入於玄波，其東則有天浪水府，百川是鍾，包絡坤維，連薄太濛，其北則有陶林玄壇，增冰冱寒，其西則有靈丘平圃，邪接崑崙，其近則有天井句註，飛壶太行，璀错蛇累硌，屬阜連岡，龍首嵯峨以岪鬱，羊坂崙〈山囷〉以〈山厷〉嵣，清漳發源濁滏汨越，湯泉涫沸，洪波漂厲，爾乃都城萬雉，百里周回，九衢交错，三門旁开，層樓疏閣，連棟結階，峙華爵以表甍，若翔鳳之將飛，正殿俨其造天，朱櫺赫以舒光，盤虬螭之蜿蜒，承雄虹之飛梁，結雲閣於南宇，立丛台於少陽，及至暮秋涉冬，則風烈寒猛，豺鷙攫，［句有脱文。］鷹隼奋翰，國乃講武，狩於清源，駕骛冥之駿驳，抗冲天之旌旃，北連昭餘，南屬呼池，西眄太陵，東結缭河，然後嵠子放機，戈矛亂發，决班鬐，破文頞，當手毙僵，應絃倒越，爾乃進夫中山名倡，襄國妖女，狄鞮妙音，邯鄲才舞，六八骈羅，遞奏迭舉，體凌浮雲，聲哀激楚，其珍玩服物，則崑山美玉，玄珠曲環，輕绡啟繒，纖纊綈紈，其器用良馬，則六弓四弩，绿沉黃間，堂嵠魚腸，丁令角端，飛兔奚斯，常驪紫燕，丰鬒確顱，龍身鵠頸，目如黃金，蘭筋參精，迅躡飛浮，軼响追聲，若乃至季春元巳，辰火炽光，挺新赠往，祓於水陽，朱幕蔽野，采帷連岡，妖冶呈飾，顏如春英。","sortOrder":35},
  {"id":"s_work_nvlt_61_36","chapterId":"ch_work_nvlt_61","text":"晉左思蜀都賦曰：夫蜀都者，蓋兆基於上世，开國於中古，廓靈關而為門，包玉壘而為宇，帶二江之双流，抗峨眉之重阻，於前則跨躡犍〈牜羊〉，枕倚交趾，經涂所亘，五千餘里，於是乎邛竹緣嶺，菌桂臨崖，旁挺龍目，侧生荔枝，布绿葉之萋萋，結朱實之離離，孔翠群翔，犀象競馳，白雉朝雊，猩猩夜啼，金馬騁先而絕影，碧雞倏忽而曜儀，火井沉熒於幽泉，高爓飛煽於天垂，於後則却背華容，北指崑崙，緣以劍閣，阻以石門，流漢湯湯，驚浪雷奔，望之天回，即之雲昏，水物殊品，鱗介異族，或藏蛟螭，或隱碧玉，其树則有木蘭梫［七林反。］桂，杞櫹椅桐，楩柟幽藹於穀底，松柏蓊蔚於山峰，棹脩幹，竦長條，扇飛雲，拂輕霄，羲和假道於峻岐，陽乌回翼乎高摽，於東則左綿巴中，百濮所充，外負銅梁宕渠，內函要害於膏腴，丹砂赩炽出其坂，蜜房都鬱被其阜，山圖采而得道，赤斧服而不朽，交壤［《文選》四蜀都賦作讓。］所植，蹲鴟所伏，百藥灌丛，寒卉冬馥，其中則有青珠黃環，碧砮芒消，或丰绿荑，或蕃丹椒，紅葩紫飾，柯葉漸苞，敷蕊葳蕤，落英飄飖，溝洫脈散，疆里綺错，黍稷油油，粳稻漠漠，指渠口以為雲門，洒滮池而為陆泽，爾乃邑居隱軫，夹江傍山，家有鹽泉之井，戶有橘柚之園，百果甲坼，異色同榮，朱櫻春就，素柰夏成，若乃大火流，涼風厲，白露凝，微霜結，紫藜津润。樼栗罅發，蒲萄亂潰，石留競裂，晨凫旦至，候雁衔芦，木落南翔，冰泮北徂，雲飛水宿，哢吭［胡浪反。］清渠，其深則有鳣鲔鳟鲂，鮷鱧魦鲿，差鱗次色。錦质報章，辟二九之通門，畫方軌之廣涂，營新宮於爽垲，擬承明而起庐，結陽城之延閣，飛觀榭乎雲中，开高軒以臨山，列綺窗以瞰江，內則宣化之闼，崇禮之闈，華闕双邈，重門洞开，金鋪交映，玉題相暉，亚以少城，接乎其西，列隧百重，羅肆巨千，賄货山積，纖麗星繁，都人士，［《文選》士下有女字。］袨服靓［才性反。］莊，布有橦華，面有桄榔，邛竹傳節於大夏之邑，蒟醬流味於番隅之乡，闤阓之里，伎巧之家，百室離房，機杼相和，貝錦斐成，濯色江波，若夫王孫之屬，郤公之倫，從禽於外，巷無居人，併乘骥子，俱服魚文，西逾金隄，東越玉津，戟食鐵之獸，射噬毒之鹿，拍犭區氓於葽草，彈言鳥於森木，拔象齒，戾［歷結反。］犀角，乌鎩翮，獸废足，殆而朅，來相與，第如滇［丁田反。］池，集於江洲，试水客，漾輕舟，娉江妃，與神遊，將饗獠者，張弈幕，會平原，酌醪酤，割芳鮮，飲御酣，賓旅旋，車馬雷駭，轟轟闐闐，近則江漢炳靈，世載其英，蔚若相如，皭若君平，王褒煒燁而秀發，扬雄含章而挺生，幽思絢道德，摛藻掞天庭。","sortOrder":36},
  {"id":"s_work_nvlt_61_37","chapterId":"ch_work_nvlt_61","text":"又吳都賦曰：東吳王孫，辴々［忍反，大笑也。］然而咍曰：夫上圖景宿。辯於天文者也，下料物土，析於地理者也，鳥策篆素，玉諜石記，乌聞梁岷有陟方之馆，行宮之基欤，而吾子獨未聞大吳之壮麗乎，且有吳之开國也，造自泰伯，宣於延陵，固其經略，上當星紀，拓土畫疆，指衡嶽以镇野，同龍川而帶埛，百川泒別，歸海而會，控清引濁，混涛併瀨，濆薄沸騰，寂寥長邁，出乎大荒之中，行乎東極之外，於是乎長鯨吞航，脩鲵吐浪，躍龍騰蛇，蛟鯔琵琶，溯洄順流，噞喁沉浮，鳥則鵾雞鸀〈火霍〉，鹴［音霜。］鵠鷺鸿，鶢鶋避風，候雁造江，湛淡羽儀，隨波參差，理翮整翰，容與自玩，彫啄蔓藻，刷荡漪澜，蚌蛤珠胎，與月虧全，巨鼇贔屃，首冠靈山，大鵬繽翻，翼若垂天，洪桃盤屈，丹桂灌丛，琼枝抗茎而敷蕊，珊瑚幽茂而玲瓏，增岡重阻，列真之宇，江妃於是往來，海童於是宴語，草則藿蒳豆蔻，薑匯非一，石帆水松，東風扶留，布濩皋泽，蝉聯陵丘，寅緣山嶽之{巳山}，［音節。］幂［音觅。］棡［煙貌。］江海之流，木則平仲君遷，松梓古度，楠榴之木，相思之树，宗生高岡，族茂幽阜，擢本千尋，垂荫萬畝，與風飖颺，〈風幼〉瀏颼飗，鳴條畅律，飛音响亮，蓋象琴筑併奏，笙竽俱唱，其竹則篔簹林箊，［音於。］桂箭射筒，柚梧有篁，篻簩有丛，苞筍抽節，往往萦結，绿葉翠茎，冒霜停雪，梢雲無以逾，嶰穀不能連，鸑鷟食其實，鵷雏扰其間，其果則丹橘餘甘，荔枝之林，槟榔無柯，椰葉無陰，其琛賂則琨瑤之阜，銅锴［白鐵也。］之垠，火齊之寶，駭雞之珍，赪丹明璣，金華銀朴，紫貝流黃，縹碧素玉，其荒陬譎诡，則有龍穴內蒸，雲雨所储，陵鯉若獸，浮石若桴，双則比目，片則王餘，窮陆飲木，極沉水居，泉室潛織而卷绡，淵客慷慨而泣珠，象耕鳥耘，此之自改，煮海為鹽，采山鑄錢，國稅再熟之稻，乡貢八蠶之綿，造姑蘇之高台，臨四遠而特建，帶朝夕之濬池，佩長洲之茂苑，闚東山之府，則朅寶溢目，〈麗見〉海陵之仓，則紅粟流衍，彫栾鏤楶，［音節。］青鎖丹楹，圖以雲氣，畫以仙靈，高闈有闶，洞門方軌，朱闕双立，馳道如砥，树以青槐，亘以渌水，桃笙象簟，韜於筒中，蕉葛升越，弱於羅紈，命官師而擁铎，將校獵兮具區，吳王乃巾玉辂，轺驌骦，羽毛扬蕤，雄戟燿芒，貝胄象弭，織文鳥章，六軍袀服，四騏龍驤，猩猩啼而就擒，狒狒［扶沸切。］笑而被格，屠巴蛇，出象骼，斬鵬翼，掩廣泽，結輕舟而競逐，迎潮水而振緍，精衛衔石而遇繳，文鰩夜飛而觸纶，指包山以為期，集洞庭而掩留，數軍實乎桂林之苑，饗戎旅乎落星之樓。","sortOrder":37},
  {"id":"s_work_nvlt_61_38","chapterId":"ch_work_nvlt_61","text":"又魏都賦曰：魏國先生，有睟其容，乃盱衡而誥曰：異乎交益之士，劍閣雖嶛，［嶛，险也。］凭之者蹶，洞庭雖濬，負之者北，且魏土者，畢昴之所應，虞夏之餘人，先王之桑梓，烈聖之遺尘，爾其彊域，則旁極齊秦，結凑冀道，开胸殷衛，跨躡燕趙，墨井鹽池，玄滋素液，厥田惟中，厥壤惟白，思重爻，摹大壮，覽荀卿，采萧相，枌橑複結，栾栌叠施，丹梁虹申以併亘，朱桷林布而支離，綺井列疏以懸蒂，華莲重葩而倒披，於前宣明顯陽，順德崇禮，重闈洞出，锵锵濟濟，於後椒鶴文石，永巷壶術，楸梓木蘭，次舍甲乙，增構瓘瓘，清尘剽剽，雲雀踶甍而矯首，壮翼摛鏤於青霄，雷雨杳冥於未半，曒日籠光於綺寮，硕果灌丛，围木竦尋，篁筱懷風，蒲萄結陰，丹藕凌波而的皪，绿芰汎涛而浸潭，羽翮頡颃，鱗介浮沉，磴流十二，同原異口，蓄為屯雲，泄為行雨，內則街衢輻凑，朱闕結嵎，石槓［槓，桥，也。］飛梁，出控漳渠，疏通溝以濱路，萝青槐以荫途。","sortOrder":38},
  {"id":"s_work_nvlt_61_39","chapterId":"ch_work_nvlt_61","text":"晉庾闡楊都賦曰：子未聞楊都之巨伟也，左沧海，右岷山，龟鳥津其落，江漢演其源，碣金摽乎象浦，註桐柏乎玄川，昔句吳端委，延州俪臧，高讓殆於庶幾，英風亚乎穎陽，土映黃旗之景，峦吐紫蓋之祥，巖栖赤松之馆，岫啟縉雲之堂，龍符涣而夏德興，群神萃而玉帛昌也，天包龍軫，地奄衡霍，玄聖所遊，陟方所讬，我皇晉之中興，而駿命是廓，靈運啟於中宗，天網振其絕絡，於是乎源泽浩瀁，林阜隱薈，彭蠡吞江，荆牙吐瀨，赴三峡之隘，洞九川之會，泮五嶺而分流，鼓沱潛而碎沛，漨渤氵鬱滃，潢漾擁涌，驚波霆激，駭浪川動，東註尾闾，呼吸洞庭，茫若雲漢，窈若青城，其山則重岡峨屼，峻嶺嵦崿，陽侯鱗萃，龍涛綺错，嵭〈山弗〉磊砢，嵬峞鄱薄，旁帶千溪，下同萬壑，木則灌以杞梓，被以沙裳，結根九疑，布葉天柱，林為五嶽之苑，材為八都之府，扫飛虹，虧陽景，拂白雪而增翠，凌廣莫而敷穎，竹則{⺮聆}風箘簵，筱簜林箊，单棘箜{⺮杪}，蓊蔚萧疏，貞條梢風，劲節集霧，望之猗猗，即之倩倩，蒼浪之竿，東南之箭，其林可遊，其芳可荐，草則陵苔海藻，山英江蓠，纶組菁茅，繁露卷施，獸則騊駼狻猊，鋸牙披蹄，登重巘。蹲嶪嶬，噫氣則風生，喷沫則雨洒，其間則有騰猿夭峤，閃儵柯杪，風母杲然，星流電遷，或陵虛赴絕，或缭繞希聞，鳥則鹪鵬孔翠，丹穴之羽，鳴鳳自歌，翔鸞自舞，魚則鲛鳣〈魚朁〉鲔，比目鲿魦，脩鯤橫海，徵鯨偃波，其中則有靈蛟白黿之族，种繁六眸，類丰三足，鸚螺蜕骨，寄居負敖，餘泉如輪，文蚳如琢，果則黃甘朱橙，楊桃琵琶，林蔚八桂之丛，色燿三珠之華，爾其寶怪，則有瑤琨琅玕，青碧素珉，陽珠散火，陰甲潛珍，雲英水玉，错燿龍鱗，煥若金膏，晃若燭銀，琉璃冰朗而外映，珊瑚觸石而構翘，牙簟裂文於象齒，火布濯秽於炎焱，西岨石城，則丹車之所混併，東盡金塘，則方駕之所連箱，其中則有龍坻華屋，晨凫之舸，青雀飛舻，餘皇鼓施，鹢首鋪於黃宮，盤蛟纏於赤馬，爰有蘭堂華室，高門重構，羅鼎玉食，絲竹併奏，龍骥汗血於廣涂，朱輪击轂而輻凑。","sortOrder":39},
  {"id":"s_work_nvlt_61_40","chapterId":"ch_work_nvlt_61","text":"晉傅玄正都賦曰：撫琴瑟，陳鍾虡，吹鳴箫，击靈鼓，奏新聲，理秘舞，乃有材童妙妓，都盧迅足，緣脩竿而上下，形既变而景屬，忽跟掛而倒絕，若將墜而复續，虬萦龍蜿，委隨紆曲，杪竿首而腹旋，承嚴節之繁促，於是神嶽双立，岡巖岑崟，靈草蔽崖，嘉木成林，東父翳青蓋而遐望，西母使三足之靈禽，丹蛟吹笙，文豹鼓琴，素女撫瑟而安歌，聲可意而入心，偓佺企而鶴立，和清响而哀吟。","sortOrder":40},
  {"id":"s_work_nvlt_61_41","chapterId":"ch_work_nvlt_61","text":"《藝文類聚》　唐·欧陽詢","sortOrder":41},
  {"id":"s_work_nvlt_62_1","chapterId":"ch_work_nvlt_62","text":"卷六十二居處部二","sortOrder":1},
  {"id":"s_work_nvlt_62_2","chapterId":"ch_work_nvlt_62","text":"○宮闕台殿坊","sortOrder":2},
  {"id":"s_work_nvlt_62_4","chapterId":"ch_work_nvlt_62","text":"《世本》曰：禹作宮。","sortOrder":4},
  {"id":"s_work_nvlt_62_5","chapterId":"ch_work_nvlt_62","text":"《釋名》曰：宮，穹也，屋見垣上穹隆也。","sortOrder":5},
  {"id":"s_work_nvlt_62_6","chapterId":"ch_work_nvlt_62","text":"《方言》曰：吳有馆娃之宮。","sortOrder":6},
  {"id":"s_work_nvlt_62_7","chapterId":"ch_work_nvlt_62","text":"《禮記》曰：儒有一畝之宮，環堵之室。","sortOrder":7},
  {"id":"s_work_nvlt_62_8","chapterId":"ch_work_nvlt_62","text":"《大戴禮》曰：周時德泽和洽，蒿茂大，以為宮柱者，名曰蒿宮。","sortOrder":8},
  {"id":"s_work_nvlt_62_9","chapterId":"ch_work_nvlt_62","text":"《毛詩》曰：定之方中，作於楚宮，揆之以日，作於楚室。","sortOrder":9},
  {"id":"s_work_nvlt_62_10","chapterId":"ch_work_nvlt_62","text":"又曰：鼓鍾於宮，聲聞於外。","sortOrder":10},
  {"id":"s_work_nvlt_62_11","chapterId":"ch_work_nvlt_62","text":"《管子》曰：黃帝有合宮，以聽政。","sortOrder":11},
  {"id":"s_work_nvlt_62_12","chapterId":"ch_work_nvlt_62","text":"《穆天子傳》曰：天子升於崑崙之丘，以觀帝之宮。","sortOrder":12},
  {"id":"s_work_nvlt_62_13","chapterId":"ch_work_nvlt_62","text":"《越絕書》曰：美人宮周五百九十步，土城者，句踐所習教美人西施鄭旦宮室。","sortOrder":13},
  {"id":"s_work_nvlt_62_14","chapterId":"ch_work_nvlt_62","text":"《列子》曰：周穆王時，西胡國有化人來，王執化人之袪，騰而上天，暨化人之宮，構以金銀，絡以珠玉，出雲雨之上，實為清都紫微也。","sortOrder":14},
  {"id":"s_work_nvlt_62_15","chapterId":"ch_work_nvlt_62","text":"《孟子》曰：齊宣王見孟子於雪宮。","sortOrder":15},
  {"id":"s_work_nvlt_62_16","chapterId":"ch_work_nvlt_62","text":"《呂氏春秋》曰：武王勝殷，靖箕子之宮。","sortOrder":16},
  {"id":"s_work_nvlt_62_17","chapterId":"ch_work_nvlt_62","text":"《楚辭》曰：鱗屋兮龍堂，紫貝闕兮朱宮。","sortOrder":17},
  {"id":"s_work_nvlt_62_18","chapterId":"ch_work_nvlt_62","text":"《史記》曰：騶子之燕，昭王擁篲先驅，請列弟子之座而受業，筑碣石室，［《太平御覽》一百七十三作宮。］親往師之。","sortOrder":18},
  {"id":"s_work_nvlt_62_19","chapterId":"ch_work_nvlt_62","text":"《神異經》曰：東方有宮，青石為牆，高三仞，左右闕高百丈，畫以五色，門有銀榜，以青石碧鏤，題曰天地長男之宮，西方有宮，白石為牆，五色黃門，有金榜而銀鏤，題曰天地少女之宮，西南方有宮，以金為牆，門有金榜，以銀，［《太平御覽》一百七十三銀下有鏤字。］題曰天皇之宮，南方有宮，以赤石為牆，赤銅為門，有銀榜，題曰天地中女之宮，北方有宮，以黑石為牆，題曰天地中男之宮，東南有宮，以黃石為牆，以黃碧鏤，題曰天地少男之宮，西南有宮，以黃銅為牆，題曰地皇之宮。","sortOrder":19},
  {"id":"s_work_nvlt_62_20","chapterId":"ch_work_nvlt_62","text":"《十洲記》曰：青丘山上有紫宮，天真仙女，多遊於此。","sortOrder":20},
  {"id":"s_work_nvlt_62_21","chapterId":"ch_work_nvlt_62","text":"又曰：方丈山上有琉璃宮。","sortOrder":21},
  {"id":"s_work_nvlt_62_22","chapterId":"ch_work_nvlt_62","text":"《列仙傳》曰：鉤翼夫人，齊人也，右手拳，望色者雲，東方有貴人氣，及到，姿色甚伟，帝披其手，得一鉤，手尋下不拳，故名其宮曰鉤翼宮。","sortOrder":22},
  {"id":"s_work_nvlt_62_23","chapterId":"ch_work_nvlt_62","text":"《說苑》曰：楚使使聘齊，齊王享之梧宮，使者曰：大哉梧乎，王曰：江海之魚吞舟，况大國之树也。","sortOrder":23},
  {"id":"s_work_nvlt_62_24","chapterId":"ch_work_nvlt_62","text":"《漢武帝故事》曰：上起明光宮，發燕趙美女二千人充之，建章未央長樂三宮，皆輦道相屬，懸棟飛閣，不由径路。","sortOrder":24},
  {"id":"s_work_nvlt_62_25","chapterId":"ch_work_nvlt_62","text":"《漢書》曰：武帝六年，冬，幸雍回中，春作首山宮。","sortOrder":25},
  {"id":"s_work_nvlt_62_26","chapterId":"ch_work_nvlt_62","text":"又曰：上祠神人於郊［《太平御覽》一百七十三作交。］門宮，若有向坐拜者，作交門之歌。","sortOrder":26},
  {"id":"s_work_nvlt_62_27","chapterId":"ch_work_nvlt_62","text":"又曰：幸河東之明年，正月，鳳皇集，設祠於所集處，得玉寶，起步寿宮。","sortOrder":27},
  {"id":"s_work_nvlt_62_28","chapterId":"ch_work_nvlt_62","text":"又曰：柏梁灾，越巫勇之乃曰：越俗，有火灾，复起屋，必以火，［太平御覽一百七十三作大。］用勝服之，於是起建章宮，為千門萬戶。","sortOrder":28},
  {"id":"s_work_nvlt_62_29","chapterId":"ch_work_nvlt_62","text":"又曰：秦倚曲台之宮，懸衡天下，［衡，秤也，言懸法度於其上也。］","sortOrder":29},
  {"id":"s_work_nvlt_62_30","chapterId":"ch_work_nvlt_62","text":"三辅故事曰：桂宮周匝十里，內有光明殿，走狗台，土山萦複道，橫北度，從宮中西上城，至神明台。","sortOrder":30},
  {"id":"s_work_nvlt_62_31","chapterId":"ch_work_nvlt_62","text":"《三辅黃圖》曰：有夜光宮望遠宮照台宮蒲萄宮棠梨宮資陽宮長平宮五柞宮。","sortOrder":31},
  {"id":"s_work_nvlt_62_32","chapterId":"ch_work_nvlt_62","text":"漢宮闕名曰：長安有長樂宮未央宮長門宮鼓簧宮承光宮林光宮宜，春宮池陽宮長平宮黃山宮望仙宮長楊宮集靈宮萬歲宮延寿宮初［《太平御覽》一百七十三作祈。］年宮通天宮馺婆［御覽作娑。］宮。","sortOrder":32},
  {"id":"s_work_nvlt_62_33","chapterId":"ch_work_nvlt_62","text":"《東觀漢記》曰：帝遺单於饗賜作樂百戲，上幸離宮臨觀。","sortOrder":33},
  {"id":"s_work_nvlt_62_34","chapterId":"ch_work_nvlt_62","text":"《魏略》曰：大秦國城中有五宮，相去各五十里，宮室皆以水精為柱，食器亦然。","sortOrder":34},
  {"id":"s_work_nvlt_62_35","chapterId":"ch_work_nvlt_62","text":"王隱《晉書》曰：高堂隆刻鄴宮屋材雲，後若幹年，當有天子居此宮，惠帝止鄴宮，治屋者土剝更泥，始見刻字，計年正合。","sortOrder":35},
  {"id":"s_work_nvlt_62_36","chapterId":"ch_work_nvlt_62","text":"【詩】梁簡文帝新成安樂宮詩曰：遙看雲霧中，刻角映丹虹，珠帘通晓日，金花拂夜風，欲知絃管處，來過安樂宮。","sortOrder":36},
  {"id":"s_work_nvlt_62_37","chapterId":"ch_work_nvlt_62","text":"周明帝過舊宮詩曰：玉燭調秋氣，金舆歷舊宮，還如過白水，更似入新丰，秋潭渍晚菊，寒井落疏桐，舉杯延故老，今聞歌大風。","sortOrder":37},
  {"id":"s_work_nvlt_62_38","chapterId":"ch_work_nvlt_62","text":"陳陰铿新成安樂宮詩曰：新宮實壮哉，雲里望樓台，迢遞翔鵾仰，連翩贺雀來，重簷寒露宿，丹井夏莲开，砌石披新錦，梁花畫早梅，欲知安樂盛，歌管雜尘埃。","sortOrder":38},
  {"id":"s_work_nvlt_62_39","chapterId":"ch_work_nvlt_62","text":"【賦】漢劉歆甘泉宮賦曰：軼陵陰之地室，過陽穀之秋城，回天門而鳳舉，躡黃帝之明庭，冠高山而為居，乘崑崙而為宮，按軒轅之舊處，居北辰之閎中，背共工之幽都，向炎帝之祝融，封峦為之東序，緣石闕之天梯，桂木雜而成行，芳盻乡之依依，翡翠孔雀，飛而翱翔，鳳皇止而集栖，甘醴涌於中庭兮，激清流之沴沴，黃龍遊而蜿蟺兮，神龟沉於玉泥，離宮特觀，樓比相連，雲起波駭，星布弥山，高峦峻阻，臨眺曠衍，深林蒲苇，涌水清泉，芙蓉菡萏，菱荇蘋蘩，豫章雜木，梗松柞棫，女貞乌勃，桃李棗檍。","sortOrder":39},
  {"id":"s_work_nvlt_62_40","chapterId":"ch_work_nvlt_62","text":"魏卞蘭許昌宮賦曰：入南端以北眺，望景福之嵯峨，飛棟列以山峙，長途邈以委他，見栾栌之交错，睹陽馬之承阿，轉挟臈以相因，若流風之扬波，木無小而不蹐，材靡隱而不華，懿采色而發越，玮巧飾之繁多，双轅承枌，丹梁端直，明窗列布，綺井崱嶷，其陰則有望舒涼室，羲和溫房，隆冬御絺，盛夏重裳，同一宇之深邃，致寒暑於陰陽，脩欄荫於階砌，崇棟拂乎旻蒼，綺組發華，翡翠生光，丹草周隅，靈木成行，非窈窕之至貴，孰能升於斯堂，坐金人於闈闼，列鍾虡於廣庭，天鹿軒翥以扬怒，師子鬱拂而負楨，珍果敷華，蘭芷垂榮，百璧照曜，飛响應聲，扣角則春氣至，彈商則秋風征，歷神芝之峻觀，幸安昌之巍巍，進鼓舞之秘妓，絕世俗而入微，興七盤之遞奏，觀輕捷之翾翾，或遲或速，乍止乍旋，似飛凫之迅疾，若翔龍之遊天，趙女撫琴，楚媛清謳，秦筝慷慨，齊舞絕殊，眾妓併奏，捔巧騁奇，千变萬化，不可勝知，樂戲阕，遊觀足，登承光，坐華幄，論稽古，反流俗，退虛伪，進敦朴，寶賢良，賤珠玉，豈必世而後仁，在時主之所欲。","sortOrder":40},
  {"id":"s_work_nvlt_62_41","chapterId":"ch_work_nvlt_62","text":"魏楊脩許昌宮賦曰：於是儀北極以遘撩，希形製乎太微，結雲閣之崔嵬，植神木與靈草，紛蓊蔚以參差，爾乃置天台於辰角，列執法於西南，筑舊章之兩觀，缀長廊之步欄，重閨禁之窈窕，造華蓋之幽深，俭則不陋，奢則不盈，黎民子來，不督自成，於是天子乃具法服，戒群僚，鍾鼓隱而雷鳴，警跸嘈而响起，晻藹低佪，天行地止，以入乎新宮，臨南軒而向春方，負黼黻之屏風，凭玉幾而按圖書，想往昔之興隆。","sortOrder":41},
  {"id":"s_work_nvlt_62_42","chapterId":"ch_work_nvlt_62","text":"北齊邢子才新宮賦曰：擬二儀而構路寢，法三山而起翼室，何大厦之眈眈，而斯幹之秩秩，豈西京之足伟，故東都之所匹，爾其状也，則朅譎屈奇，澜漫陆離，嵯峨崔嵬，巉巖參差，若密雲之乍舉，似鵬翼之中垂，布菱華之與莲蒂，鹹反植而倒施，若承露而將轉，似含風而欲披，土成黼黻，木化蛟螭，布紅紫之融泄，間朱黃之赫曦，獸狂顧而猶動，鳥將騫而中疲，木神水怪，海若山祇，千变萬化，殊形異宜，陰梁北註，陽鳥南施，百楹列倚，千栌代支，或據险而形固，或居安而势危。","sortOrder":42},
  {"id":"s_work_nvlt_62_43","chapterId":"ch_work_nvlt_62","text":"【頌】漢王褒甘泉宮頌曰：甘泉山，天下顯敞之名處也，前接大荆，後臨北極，左撫仁乡，右望素域，其宮室也，仍〈山截〉嶭而為觀，攘抗岸以為階，壅波澜而鱗坻，馳道列以曲遠，覽除閣之麗靡，覺堂殿之巍巍，径落莫以差错，編玳瑁之文〈媲\"女改木\"〉，鏤螭龍以造牖，采雲氣以為楣，神星羅於題鄂，虹蜺往往而繞榱，缦倏忽其無垠，意能了之者誰，竊想聖主之優遊，時娱神而款縱，坐鳳皇之堂，聽和鸞之弄，臨麒麟之域，验符瑞之貢，詠中和之歌，讀太平之頌。","sortOrder":43},
  {"id":"s_work_nvlt_62_44","chapterId":"ch_work_nvlt_62","text":"宋孝武帝巡幸舊宮頌曰：惟皇敬眷，永慕徐京，列裝青野，動斬丹廷，榮和首律，景泽开年，林坰發色，川郊列泉，沿溯遙衍，登陟回懸，踐域負外，即宮臨山，思甲陵寢，歡結枌都，眇懷沛濟，勤念宛吾，納寿遺老，設飲先居，堂序朝秀，廷［全宋文六廷上有充字。］集闾。","sortOrder":44},
  {"id":"s_work_nvlt_62_45","chapterId":"ch_work_nvlt_62","text":"梁沈約齊朝丹徒故宮頌曰：聖祖神杰，尧蹤漢烈，嶽峻雄圖，天張武節，墜命既升，霸略將騁，清渭走烽，濁河獻警，特峭劍關，凭深桂嶺，彝章委闕，禮樂沉河，極壓傾構，引溺危波，盡物稱瑞，窮靈委和，玄精翼日，丹羽巢阿。","sortOrder":45},
  {"id":"s_work_nvlt_62_46","chapterId":"ch_work_nvlt_62","text":"【銘】後漢李尤永安宮銘曰：合歡黃堂，中和是遵，舊庐懷本，新果畅春，候台集道，俾司星辰，丰業廣德，以协天人，萬福來眇，嘉娱永欣。","sortOrder":46},
  {"id":"s_work_nvlt_62_47","chapterId":"ch_work_nvlt_62","text":"【表】梁沈約為柳兖州世隆上舊宮表曰：舊宮蘊靈千古，合祥百代，萬祇相祉，八神警室，事超齊甸，義邁谯宮，故能屬輦道於天階，命帝闕於霄路，實宜树闕疏壤，寫極上穹，克播徽尘，永光盛烈。","sortOrder":47},
  {"id":"s_work_nvlt_62_49","chapterId":"ch_work_nvlt_62","text":"《廣雅》曰：象魏，闕也。","sortOrder":49},
  {"id":"s_work_nvlt_62_50","chapterId":"ch_work_nvlt_62","text":"《釋名》曰：闕，闕也，在門兩旁，中央闕然為道也。","sortOrder":50},
  {"id":"s_work_nvlt_62_51","chapterId":"ch_work_nvlt_62","text":"《周官》曰：太宰以正月懸治法於象魏。","sortOrder":51},
  {"id":"s_work_nvlt_62_52","chapterId":"ch_work_nvlt_62","text":"《禮記》曰：昔者仲尼與於蠟賓，事畢，出遊於觀之上，喟然而叹，仲尼之叹，蓋叹魯也，［鄭言觀闕也。］","sortOrder":52},
  {"id":"s_work_nvlt_62_53","chapterId":"ch_work_nvlt_62","text":"《左傳》曰：哀公三年，司铎火，逾公宮，季桓子至，命藏象魏，曰舊章不可忘，［象魏，門闕也，法令懸之，故謂其書為象魏也。］","sortOrder":53},
  {"id":"s_work_nvlt_62_54","chapterId":"ch_work_nvlt_62","text":"《文子》曰：老子雲，身處江海之上，心在魏闕之下。","sortOrder":54},
  {"id":"s_work_nvlt_62_55","chapterId":"ch_work_nvlt_62","text":"《史記》曰：蓬萊方丈瀛洲，此三山在海中，諸仙人不死藥皆在焉，黃金白銀為闕。","sortOrder":55},
  {"id":"s_work_nvlt_62_56","chapterId":"ch_work_nvlt_62","text":"又曰：建章宮東鳳闕，高二十丈。","sortOrder":56},
  {"id":"s_work_nvlt_62_57","chapterId":"ch_work_nvlt_62","text":"《神異經》曰：東南有石井，其方百丈，上有二石闕，俠東南面，上有蹲熊，有榜著闕，題曰地戶。","sortOrder":57},
  {"id":"s_work_nvlt_62_58","chapterId":"ch_work_nvlt_62","text":"又曰：東北大荒中，有金闕，高百丈，上有明月珠，径三丈，光照千里，中有金階，西北入兩闕中，名天門。","sortOrder":58},
  {"id":"s_work_nvlt_62_59","chapterId":"ch_work_nvlt_62","text":"《十洲記》曰：崑崙山有水精闕。","sortOrder":59},
  {"id":"s_work_nvlt_62_60","chapterId":"ch_work_nvlt_62","text":"《列仙［《太平御覽》一百七十九作女，此訛。］傳》曰：衛靈公與夫人夜坐，聞車聲辚辚，至闕而止，過闕复有聲，公問夫人曰：知此為誰，夫人曰：此蘧伯玉也，公曰：何以知之，夫人曰：妾聞禮下公門，式路馬，今蘧伯玉衛之賢大夫也，敬於事上，必不闇昧废禮，是以知之，公使人视之，果伯玉也。","sortOrder":60},
  {"id":"s_work_nvlt_62_61","chapterId":"ch_work_nvlt_62","text":"《三辅舊事》曰：未央宮東有蒼龍闕，北有玄武闕。","sortOrder":61},
  {"id":"s_work_nvlt_62_62","chapterId":"ch_work_nvlt_62","text":"應劭《漢官儀》曰：高祖既登帝位，鮦陽固始細陽歲遣雞鳴歌士，常謳於闕下。","sortOrder":62},
  {"id":"s_work_nvlt_62_63","chapterId":"ch_work_nvlt_62","text":"漢官典職曰：偃師去宮三十五里，望朱雀闕，其上鬱朴與天連。","sortOrder":63},
  {"id":"s_work_nvlt_62_64","chapterId":"ch_work_nvlt_62","text":"《魏志》曰：明帝作凌霄闕。","sortOrder":64},
  {"id":"s_work_nvlt_62_65","chapterId":"ch_work_nvlt_62","text":"《蜀志》曰：谯周嘗聞杜琼曰：昔周徵君群，以為當涂高者，魏也，其義何也，琼答曰：魏，闕名也，當涂言高，聖人取類言爾。","sortOrder":65},
  {"id":"s_work_nvlt_62_66","chapterId":"ch_work_nvlt_62","text":"《關中記》曰：未央宮東有青龍闕，北有玄武闕，漢書所謂北闕者也，建章宮圓闕，臨北道，鳳在上，故曰鳳闕也，閶阖門內東出，有折風闕，一名別風闕。","sortOrder":66},
  {"id":"s_work_nvlt_62_67","chapterId":"ch_work_nvlt_62","text":"王隱《晉書》曰：漢末，博士敦煌侯瑾，善內學，語弟子曰：涼州城西有泉水當竭，當有双闕起其上，魏嘉平中，武威太守起學舍，筑闕於此。","sortOrder":67},
  {"id":"s_work_nvlt_62_68","chapterId":"ch_work_nvlt_62","text":"賴［《太平御覽》一百七十九作瀨，下同。］乡記曰：老子廟前有兩石闕，大闕高九尺八寸，下三重石墌，闕邊各有子闕。","sortOrder":68},
  {"id":"s_work_nvlt_62_69","chapterId":"ch_work_nvlt_62","text":"山謙之《丹陽記》曰：太興中，議者皆言漢司徒許彧墓闕，可徙施之，王茂弘弗欲，後陪乘出宣陽門，南望牛頭山兩峰，曰：天闕也，豈煩改作，帝然之。","sortOrder":69},
  {"id":"s_work_nvlt_62_70","chapterId":"ch_work_nvlt_62","text":"邓德明《南康記》曰：南康縣歸義山，去縣七百里，下有石城，高數丈，遠望嵯峨，靈闕騰空，故老謂之神闕。","sortOrder":70},
  {"id":"s_work_nvlt_62_71","chapterId":"ch_work_nvlt_62","text":"【詩】隋江總詠双闕詩曰：象闕連馳道，反宇照方疏，刻鳳栖清漢，圖龍入紫虛，屢逢膏露洒，幾遇祥煙初，競言百尺麗，寧方萬丈餘。","sortOrder":71},
  {"id":"s_work_nvlt_62_72","chapterId":"ch_work_nvlt_62","text":"【賦】魏繁钦建章鳳闕賦曰：筑双鳳之崇闕，表大路以遐通，上規圜以穹隆，下矩折而繩直，長楹森以骈停，修桷揭以舒翼，象玄圃之層樓，肖華蓋之麗天，當蒸暑之暖赫，步北楹而周旋，鹪鵬振而不及，豈歸雁之能翔，抗神鳳以甄甍，似虞庭之锵锵，栌六翮以撫跱，俟高風之清涼，華鍾金獸，列在南廷，嘉树蓊薆，奇鳥哀鳴，台榭臨池，萬种千名，周朓輦道，屈繞紆萦。","sortOrder":72},
  {"id":"s_work_nvlt_62_73","chapterId":"ch_work_nvlt_62","text":"【銘】後漢李尤闕銘曰：皇上尊嚴，萬姓載依，國都攸處，建設端闈，表树兩觀，双闕巍巍，梁陆倕石闕銘曰：昔舜格文祖，禹至神宗，周变商俗，湯黜夏政，雖革命殊乎因袭，揖讓異於幹戈，而晷緯冥合，天人啟基，［《文選》五十六作惎。］克明俊德，大庇生民，其揆一也，在齊之季，昏虐君臨，威侮五行，怠弃三正，蹐地無歸，瞻乌靡讬，我皇帝拯之，乃操斗極，把鉤陳，翼百神，提萬福，指麾而四海隆平，下車而天下大定，以為象闕之製，其來已遠，春秋設舊章之教，經禮垂布憲之文，戴記顯遊觀之言，周史書树闕之夢，北荒明月，西極流精，海嶽黃金，河廷紫貝，蒼龍玄武之製，銅爵鐵鳳之工，或以聽窮省冤，或以布治懸法，或表正王居，或光崇帝里，晉氏浸弱，宋歷威夷，禮經舊典，寂寥無記，鸿規盛烈，堙没罕稱，乃假双闕於牛頭，讬遠圖於博望，有欺耳目，無補憲章，惟帝建國，正位辨方，周營洛涘，漢啟岐梁，居因業盛，文以化光，爰有象闕，是惟舊章，青蓋南洎，黃旗東指，懸法無聞，藏書不紀，大人造物，龍德休否，建此百常，興茲双起，伟哉偃蹇，状矣巍巍，傍映重叠，上連翠微，布教方顯，挟日初暉，懸書有附，委箧如歸。","sortOrder":73},
  {"id":"s_work_nvlt_62_74","chapterId":"ch_work_nvlt_62","text":"【表】梁沈約上建闕表曰：恭惟哲後，舊章必修，眇矚前王，後古為貴，伏惟陛下，钦咨故實，率由令典，昔在有晉，經創江左，邦訓莫釐，遠國多缺，萬雉之外，兩觀弗興，空指南峰，懸法無所，世歷三代，年將二百，非所以經世成務，垂業後崑，天德圓應，憲章自遠，詔匠人建茲象闕，俯藉愛禮之心，以申子來之原，式表端闈，儀刑萬國，使觀風而至，复聞正歲之典，遐想之士，少寄懷古之目。","sortOrder":74},
  {"id":"s_work_nvlt_62_76","chapterId":"ch_work_nvlt_62","text":"《爾雅》曰：四方而高曰台，［積土四方者。］","sortOrder":76},
  {"id":"s_work_nvlt_62_77","chapterId":"ch_work_nvlt_62","text":"《山海經》曰：西王母之山，有軒轅台，射者不敢西向，畏軒轅之台，歸藏曰：昔者夏後啟葬，享神於晉之墟，作為璿台，於水之陽。","sortOrder":77},
  {"id":"s_work_nvlt_62_78","chapterId":"ch_work_nvlt_62","text":"《左傳》曰：夏後啟，有釣台之饗，［在河南陽翟縣。］","sortOrder":78},
  {"id":"s_work_nvlt_62_79","chapterId":"ch_work_nvlt_62","text":"又曰：楚子成章華之台，以與諸侯落之。","sortOrder":79},
  {"id":"s_work_nvlt_62_80","chapterId":"ch_work_nvlt_62","text":"《老子》曰：九層之台，起於累土。","sortOrder":80},
  {"id":"s_work_nvlt_62_81","chapterId":"ch_work_nvlt_62","text":"《穆天子傳》曰：盛姬，盛伯之子也，［盛國名。］天子賜之上姬之長，乃為之台，是曰重璧之台。","sortOrder":81},
  {"id":"s_work_nvlt_62_82","chapterId":"ch_work_nvlt_62","text":"《贾子》曰：翟王使使者之楚，楚王欲夸之，饗客章華之台，三休，乃至於上。","sortOrder":82},
  {"id":"s_work_nvlt_62_83","chapterId":"ch_work_nvlt_62","text":"《呂氏春秋》曰：有娀氏有二佚女，為九成台，飲食必以鼓。","sortOrder":83},
  {"id":"s_work_nvlt_62_84","chapterId":"ch_work_nvlt_62","text":"王孫子曰：昔衛公坐重華之台，侍御數百，隨珠照日，羅衣從風。","sortOrder":84},
  {"id":"s_work_nvlt_62_85","chapterId":"ch_work_nvlt_62","text":"《史記》曰：漢武帝起柏梁台，高數十丈。","sortOrder":85},
  {"id":"s_work_nvlt_62_86","chapterId":"ch_work_nvlt_62","text":"又曰：寡婦清，其先得丹穴而擅其利，清寡婦也，能守其業，用财自衛，秦始皇以為貞婦而客之，為筑女懷清台。","sortOrder":86},
  {"id":"s_work_nvlt_62_87","chapterId":"ch_work_nvlt_62","text":"陆贾《新語》曰：楚靈王作乾谿之台，百仞之高，欲登浮雲，窥天文。","sortOrder":87},
  {"id":"s_work_nvlt_62_88","chapterId":"ch_work_nvlt_62","text":"《新序》曰：魏王將欲為中天之台，許綰負插而入曰：聞大王將為中天之台，原加一力，臣聞天與地相去萬九千里，其趾當方一千里，盡王之地，不足為台趾，王默然，罢筑者。","sortOrder":88},
  {"id":"s_work_nvlt_62_89","chapterId":"ch_work_nvlt_62","text":"《三辅故事》曰：龍台高六丈，去丰水縣五里。","sortOrder":89},
  {"id":"s_work_nvlt_62_90","chapterId":"ch_work_nvlt_62","text":"《漢書》曰：文帝嘗欲作露台，召工計之，直百金，曰：百金中民十家之產，吾奉先帝宮室，常恐羞之，何以台為。","sortOrder":90},
  {"id":"s_work_nvlt_62_91","chapterId":"ch_work_nvlt_62","text":"《三辅宮殿簿》曰：長樂宮有臨華台，神仙台。","sortOrder":91},
  {"id":"s_work_nvlt_62_92","chapterId":"ch_work_nvlt_62","text":"《博物志》曰：江陵有台甚大，而唯有一柱，眾梁皆共此柱。","sortOrder":92},
  {"id":"s_work_nvlt_62_93","chapterId":"ch_work_nvlt_62","text":"《魏志》曰：黃初六年，筑東巡台，七年，筑九華台。","sortOrder":93},
  {"id":"s_work_nvlt_62_94","chapterId":"ch_work_nvlt_62","text":"晉宮闕名曰：鄴有銅雀台織室台。","sortOrder":94},
  {"id":"s_work_nvlt_62_95","chapterId":"ch_work_nvlt_62","text":"陳留風俗傳曰：浚儀有師曠仓頡城，城上有列仙吹台。","sortOrder":95},
  {"id":"s_work_nvlt_62_96","chapterId":"ch_work_nvlt_62","text":"《鄴中記》曰：鄴城西北立台，皆因城為基趾，中央名銅雀台，北則冰井台。","sortOrder":96},
  {"id":"s_work_nvlt_62_97","chapterId":"ch_work_nvlt_62","text":"又曰：西台高六十七丈，上作銅鳳，窗皆銅籠，疏雲母幌，日之初出，乃流光照曜。","sortOrder":97},
  {"id":"s_work_nvlt_62_98","chapterId":"ch_work_nvlt_62","text":"嵩高山記曰：山有玉女台，雲漢武帝見三仙玉女，因以名台。","sortOrder":98},
  {"id":"s_work_nvlt_62_99","chapterId":"ch_work_nvlt_62","text":"《益州記》曰：雁桥東，有嚴君平卜處，土台高數丈也。","sortOrder":99},
  {"id":"s_work_nvlt_62_100","chapterId":"ch_work_nvlt_62","text":"荆州圖記曰：江陵縣東有天井台，飛軒光映，背邑面河，寔郊鄽遊憩之佳處也。","sortOrder":100},
  {"id":"s_work_nvlt_62_101","chapterId":"ch_work_nvlt_62","text":"《幽明錄》曰：海中有金台，出水百丈，結構巧麗，窮盡神工，橫光巖渚，竦曜星漢。","sortOrder":101},
  {"id":"s_work_nvlt_62_102","chapterId":"ch_work_nvlt_62","text":"吳地記曰：吳王阖闾十一年，起台於姑蘇山，因山為名，西南去國三十五里，春夏遊焉，後夫差复高而飾之，越伐吳，遂見焚，太史公雲，餘登姑蘇，望五湖，五湖去此台二十餘里。","sortOrder":102},
  {"id":"s_work_nvlt_62_103","chapterId":"ch_work_nvlt_62","text":"戴延之《西征記》曰：官度台，去青口泽六十里，魏武所造也，破袁紹於此。","sortOrder":103},
  {"id":"s_work_nvlt_62_104","chapterId":"ch_work_nvlt_62","text":"楊龍驤洛陽記曰：陵雲台高二十三丈，登之見孟津。","sortOrder":104},
  {"id":"s_work_nvlt_62_105","chapterId":"ch_work_nvlt_62","text":"邓德明《南康記》曰：雩都君山上，有玉台，方廣數丈，周回盡是白石柱，柱自然石覆，如屋形也，四面多松杉，遙眺峨峨，乡像羽人之馆，風雨之後，景氣明净，頗聞山上有鼓吹之聲，山都木客，為舞唱之節。","sortOrder":105},
  {"id":"s_work_nvlt_62_106","chapterId":"ch_work_nvlt_62","text":"《廣州記》曰：尉他立台，以朝漢室，圓基千步，直峭百丈，螺道登進，顶上三畝，朔望升拜，號為朝台。","sortOrder":106},
  {"id":"s_work_nvlt_62_107","chapterId":"ch_work_nvlt_62","text":"伏琛齊地記曰：秦始皇二十八年，至琅邪，大樂之，留三月，作琅邪台，台亦孤山也，然高顯出於眾山之上。","sortOrder":107},
  {"id":"s_work_nvlt_62_108","chapterId":"ch_work_nvlt_62","text":"【詩】晉陆機擬古詩曰：高台一何峻，迢迢峻而安，綺窗出尘冥，飛階躡雲端，佳人撫瑤瑟，纖手清且閒，芳音隨風結，哀响馥若蘭，玉容誰能顧，傾城在一彈。","sortOrder":108},
  {"id":"s_work_nvlt_62_109","chapterId":"ch_work_nvlt_62","text":"梁簡文帝琴台詩曰：芜階踐昔径，复愁鳴琴遊，音容萬春態，高名千載留，弱枝生古树，舊石染新流，由來遞相叹，逝川終不收。","sortOrder":109},
  {"id":"s_work_nvlt_62_110","chapterId":"ch_work_nvlt_62","text":"梁庾肩吾過建昌故台詩曰：魯國觀遺殿，韓城想舊台，仲宣原隰滿，子建悲風來，夏莲猶反植，秋窗尚左开，圖雲仍溜雨，畫水即生苔，及君歡四望，知餘悲七哀。","sortOrder":110},
  {"id":"s_work_nvlt_62_111","chapterId":"ch_work_nvlt_62","text":"陳祖孫登宮殿名登高台詩曰：獨有相思意，聊敞鳳皇台，莲披香梢上，日明光正來，離鶴將雲散，飛花似雪回，遙思竹林友，前窗夜夜开。","sortOrder":111},
  {"id":"s_work_nvlt_62_112","chapterId":"ch_work_nvlt_62","text":"【賦】魏文帝登台賦序曰：建安十七年，春遊西園，登銅雀台，命餘兄弟併作，其詞曰：登高台以騁望，好靈雀之麗娴，飛閣嚬其特起，層樓俨以承天，步逍遙以容與，聊遊目於西山，溪穀紆以交错，草木鬱其相連，風飄飄而吹衣，鳥飛鳴而過前，申踌躇以周覽，臨城隅之通川。","sortOrder":112},
  {"id":"s_work_nvlt_62_113","chapterId":"ch_work_nvlt_62","text":"魏陳王曹植登台賦曰：從明後而嬉遊，聊登台以娱情，見太府之廣开，觀聖德之所營，建高殿之嵯峨，浮双闕乎太清，立冲天之華觀，連飛閣乎西城，臨漳川之長流，望眾果之滋榮，仰春風之和穆，聽百鳥之悲鳴，天工坦其既立，家原得而獲呈，扬仁化於宇內，盡肅恭於上京，唯桓文之為盛，豈足方乎聖明，休矣美矣，惠泽遠扬，翼佐皇家，寧彼四方，同天地之矩量，齊日月之辉光。","sortOrder":113},
  {"id":"s_work_nvlt_62_114","chapterId":"ch_work_nvlt_62","text":"晉陆雲登台賦曰：永寧中，巡幸鄴宮三台，登高有感，乃作賦雲，爾乃佇眄瑤軒，流目綺寮，中原方華，绿葉振翘，歷玉陛而容與，步蘭堂以逍遙，曲房萦而窈眇，長廊邈而萧條，於是聊樂近遊，薄言儴佯，綺疏列於東序，朱戶立乎西厢，感舊物之鹹存，悲昔人之雲亡，凭虛槛而遠想，審歷命於斯堂，於是精疲遊倦，白日藏辉，鄙春登之有情，惡荆台之忘歸，聊弭節而駕言，帳將逝而徘徊。","sortOrder":114},
  {"id":"s_work_nvlt_62_115","chapterId":"ch_work_nvlt_62","text":"晉孫楚韓王台賦曰：酸棗寺門外，夹道左右，有兩故台，訪諸故老，雲韓王聽訟觀也，望韓王之故台，尋往代之所營，双闕碣以峻峙，貫雲氣而上征，歷千載而特立，顯妙觀於太清，薄邯鄲之丛台，陋楚國之章華，邈岧峣以亢極，豈岑樓之能加，至乃宮觀弘敞，增台隱天，伐文梓於萬仞，發玉石於三泉，優倡角乌乌之聲，蛾眉戲白雪之舞，紛淫衍以低仰，翳脩袖而容與，晉盧諶登鄴台賦曰：顯陽隗其顛隧，文昌鞠而為墟，銅爵陨於台侧，洪鍾寢於兩除，奚帝王之靈宇，為狐兔之攸居。","sortOrder":115},
  {"id":"s_work_nvlt_62_116","chapterId":"ch_work_nvlt_62","text":"【銘】後漢李尤雲台銘曰：周氏舊居，惟漢袭因，崇台嶒峻，上擬蒼雲，垂示亿載，俾率舊章，人修其行，而國其昌。","sortOrder":116},
  {"id":"s_work_nvlt_62_118","chapterId":"ch_work_nvlt_62","text":"秦始皇本紀曰：始皇作前殿阿房，東西五百步，南北五十丈，上可以坐萬人，下可以建五丈旗。","sortOrder":118},
  {"id":"s_work_nvlt_62_119","chapterId":"ch_work_nvlt_62","text":"《漢書》曰：宣帝幸河東之明年，鳳皇集上林，乃作鳳皇殿，以答嘉瑞。","sortOrder":119},
  {"id":"s_work_nvlt_62_120","chapterId":"ch_work_nvlt_62","text":"又曰：班伯少受詩於師丹，大將軍王鳳荐伯，召見，宴昵殿中，誦說有法，拜為中常侍，時上方向學，鄭宽中張禹，朝夕入說尚書論語於金華殿中，詔伯受焉。","sortOrder":120},
  {"id":"s_work_nvlt_62_121","chapterId":"ch_work_nvlt_62","text":"三辅宮殿名曰：未央宮有麒麟殿椒房殿。","sortOrder":121},
  {"id":"s_work_nvlt_62_122","chapterId":"ch_work_nvlt_62","text":"又曰：長樂宮前殿宣德殿通光殿高明殿。","sortOrder":122},
  {"id":"s_work_nvlt_62_123","chapterId":"ch_work_nvlt_62","text":"漢宮閣名曰：長安有臨華殿神仙殿高門殿朱鳥殿曾城殿宣室殿永明殿鳳皇殿飛雲殿昭陽殿鴛鴦殿釣台殿合歡殿，萧何曹參韓信併有殿。","sortOrder":123},
  {"id":"s_work_nvlt_62_124","chapterId":"ch_work_nvlt_62","text":"《東觀漢記》曰：明帝欲起北宮，尚書仆射鍾離意上書諫，出為魯相，後起德陽殿，殿成，百官大會，上謂公卿曰：鍾離尚書若在，不得成此殿。","sortOrder":124},
  {"id":"s_work_nvlt_62_125","chapterId":"ch_work_nvlt_62","text":"范晔《後漢書》曰：中平三年，复修玉堂殿。","sortOrder":125},
  {"id":"s_work_nvlt_62_126","chapterId":"ch_work_nvlt_62","text":"《風俗通》曰：殿堂象東井形，刻作荷菱，菱水物也，所以厭火。","sortOrder":126},
  {"id":"s_work_nvlt_62_127","chapterId":"ch_work_nvlt_62","text":"漢官典職曰：德陽殿，周旋容萬人，激洛水於殿下。","sortOrder":127},
  {"id":"s_work_nvlt_62_128","chapterId":"ch_work_nvlt_62","text":"《魏志》曰：青龍三年秋，洛陽崇華殿灾，改名九龍殿。","sortOrder":128},
  {"id":"s_work_nvlt_62_129","chapterId":"ch_work_nvlt_62","text":"《魏略》曰：青龍三年，起太極殿。","sortOrder":129},
  {"id":"s_work_nvlt_62_130","chapterId":"ch_work_nvlt_62","text":"洛陽故諸宮名曰：洛陽南宮，有却非殿銅馬殿敬法殿清涼殿鳳皇殿嘉德殿黃龍殿竹殿。","sortOrder":130},
  {"id":"s_work_nvlt_62_131","chapterId":"ch_work_nvlt_62","text":"楊龍驤洛城記曰：顯陽殿北有雲氣殿。","sortOrder":131},
  {"id":"s_work_nvlt_62_132","chapterId":"ch_work_nvlt_62","text":"《洛陽宮殿簿》曰：明光徽音式乾暉章含章建始仁寿宣光嘉福百福芙蓉九華流圃華光崇光，［併殿名。］","sortOrder":132},
  {"id":"s_work_nvlt_62_133","chapterId":"ch_work_nvlt_62","text":"戴延之《西征記》曰：太極殿上有金井欄，金博山，金轆轳，蛟龍負山於井上。又有金師子，在龍下。","sortOrder":133},
  {"id":"s_work_nvlt_62_134","chapterId":"ch_work_nvlt_62","text":"挚虞决疑要註曰：凡大殿乃有陛，堂則有階無陛也，左墄右平者，以文砖相亚次，墄者為階級也，九錫之禮，納陛以登，謂受此陛以上。","sortOrder":134},
  {"id":"s_work_nvlt_62_135","chapterId":"ch_work_nvlt_62","text":"【賦】後漢李尤德陽殿賦曰：开三階而參會，错金銀於兩楹，入青陽而窥總章，歷戶牖之所經，連璧組之润漫，雜虬文之蜿蜒，爾乃周閣回匝，峻樓臨門，朱闕巖巖，嵯峨槩雲，青琐禁門，廊庑翼翼，華虫诡異，密采珍縟，達蘭林以西通，中方池而特立，果竹鬱茂以蓁蓁，鸿雁沛裔而來集，德陽之北，斯曰濯龍，蒲萄安石，蔓延蒙籠，橘柚含桃，甘果成丛，文曜水，光映煌煌。","sortOrder":135},
  {"id":"s_work_nvlt_62_136","chapterId":"ch_work_nvlt_62","text":"後漢王延寿，魯靈光殿賦序曰：魯靈光殿者，蓋景帝程姬之子恭王餘之所立也，遭漢中微，自西京未央建章之殿，盜賊奔突，皆見隳坏，而靈光巋然獨存。意者豈非神明依凭支持，以保漢室也，賦曰：瞻彼靈光之為状也，則嵯峨嶵{山隗}巋巍，吁可畏乎其駭人也，岧峣倜傥，丰盈麗博，〈山果〉{山累}敞洞，膠葛兮其無垠也。於是乃歷夫大階，以造其堂，俯仰顧眄，東西周章，彤彩之飾，澔々涆々，飛流烂漫，素璧暠曜以月照，丹柱翕赩而電烻，鸿壙幌以爣阆，瑟萧條以清泠，動滴瀝而成响，音雷應其若驚，耳嘈嘈以失聽，目矎々而丧精，骈密石與琅玕，齊玉璫與璧瑛，於是詳察其棟宇，觀其結構，規矩應天，上憲觜陬，崛佹雲起，嵚岑離娄，三間四表，八維九隅，萬楹丛倚，磊砢相扶，爾乃懸棟結阿，天窗綺疏，發秀吐榮，菡萏披敷，绿圓淵井，反植荷蕖，秀房紫的，窋咤垂珠，雲楶藻棁，龍桷雕鏤，飛禽走獸，因木生姿，朱鳥舒翼以峙衡，騰蛇蟉虬而繞榱，白鹿子蜺於欂栌。蟠螭宛轉而承楣，狡兔跧伏於拊侧，猿猴攀椽而相追，胡人遙集於上楹，俨雅跽而相對，神仙諤諤於棟間，玉女窥窗而下照，圖畫天地，品類群生，雜物奇怪，山神海靈，寫載其状，讬之丹青，千变萬化，事各缪形，隨色象類，曲得其情，上紀开辟邃古之初，五龍比翼，人皇九頭，伏羲麟身，女媧蛇軀，洪荒朴略，厥状睢盱，漸台臨池，增曲九城，屹然特立，的爾殊形，高經華蓋，仰看天庭，飛陛揭孽，绿雲上征，中坐垂景，俯视流星，千門相似，萬戶如一，巖突洞出，逶迤詰屈，周行數里，仰不見日。","sortOrder":136},
  {"id":"s_work_nvlt_62_137","chapterId":"ch_work_nvlt_62","text":"魏何晏景福殿賦曰：立景福之秘殿，備皇居之製度，爾乃丰層覆之眈眈，建高基之堂堂，羅疏柱之汨越，肅坻鄂之锵锵，飛簷翼以軒翥，反宇〈車獻〉以高驤，遠而望之，若摛朱霞而燿天文，近而察之，若仰崇山而載垂雲，爾乃开南端之豁達，張筍虡之輪豳，華鍾杌其高懸，悍獸仡其俪陳，爾其結構則修梁彩製，下褰上奇，枅梧複叠，势合形離，赩如蜿虹，赫如奔螭，皎皎白間，離離列錢，晨光內照，流景外烻，金楹齊列，玉舄承跋，青琐銀鋪，是為閨闼，溫房承其東序，涼室據其西遍，开建陽則朱炎艳，啟金光則清風臻，清露瀼瀼，渌水浩浩树以嘉木，植以芳草，悠悠玄黃，皚皚白鳥，爾乃文以朱绿，飾以碧丹，點以銀黃，烁以琅玕，清風萃而成响，朝日曜而增鮮。","sortOrder":137},
  {"id":"s_work_nvlt_62_138","chapterId":"ch_work_nvlt_62","text":"魏韦誕景福殿賦曰：瞻大厦之穹崇，結增構而高驤，脩棟迪以虹指，飛甍竦而鳳翔，榱桷骈逼以星羅，軒槛曼延而悠長，伏應龍於反宇，乘流蘇以飄扬，於是周覽升降，流目詳觀，丛楹負極，飛槛承栾，桁梧綺错，楶棁鱗攒，芙蓉侧植，藻井懸川，望舒涼室，羲和溫房，玄冬則暖，炎夏則涼，總寒暑於區宇，製天地之陰陽。又有外城金狄，诡貌殊姿，列於應門，肅有容威，若乃離殿別馆，粲如列星，安昌延休，清宴永寧，美百號之特居，嘉休祥之令名，步雕輦以逍遙，時容與於蘭庭。又有教坊講肆，才士布列，新詩变聲，曲調殊別，吟清商之激哇，發角徵與白雪，音感靈以動物，超世俗以獨絕，然後御龍舟兮翳翠蓋，吳姬擢歌，越女鼓枻，詠采菱之清謳，奏渌水之繁會。","sortOrder":138},
  {"id":"s_work_nvlt_62_139","chapterId":"ch_work_nvlt_62","text":"魏夏侯惠景福殿賦曰：周步堂宇，東西眷眄，采色光明，粲烂流延，素壁〈目高〉瀁，赫弈倩練，爾乃察其奇巧，觀其微形，嵚崟紆曲，盤牙欹傾，或夭矯而雲起，或詰屈而镮萦，眾木附枝以連註，栾梧倚亚而相經，若乃仰觀綺窗，周覽菱荷，流彩的皪，微秀發華，纖茎葳蕤，順風扬波，含光內燿，婀裊紛葩，曾栌外周，榱桷內附，或因势以連接，或邪诡以盤構，於是乎飛閣連延，馳道四周，高樓承雲，列觀若浮，挹朝露之華精，漱醴泉之清流。","sortOrder":139},
  {"id":"s_work_nvlt_62_140","chapterId":"ch_work_nvlt_62","text":"宋孝武華林清暑殿賦曰：若夫瑤榭未清，琼室流炎，熏風夕烈，炽景晨嚴，高峦废駕，遊衢輟驂，思延寒於夏室，豈徒聞於遺籍，伊涼燠之可变，粵在今之猶昔，密盻林梁，侧眺池篽，起北阜而置懸湖，沿西原而殿清暑，編茅树基，采椽成宇，轉流環堂，浮清浃室，辟西櫺而鑒斜月，高東軒而望初日，粵乃炎精待戒，青祇將畢，濯禊在辰，風光明密，婉祥鱗於石沼，儀瑞羽於林術，浮觴無屆，展樂有時，惟歡洽矣，含歌受辭，歌曰：山懷風兮穀吐泉，清潭邃兮遠氣宣，符深情兮應遙心，促千里兮测雲天。","sortOrder":140},
  {"id":"s_work_nvlt_62_141","chapterId":"ch_work_nvlt_62","text":"宋江夏王劉義恭華林清暑殿賦曰：構御暑之清宮，傍测景之西岑，列乔梧以蔽日，树長楊以結陰，醴泉涌於椒室，迅波經於蘭庭，業芳芝以爭馥，合百草以競馨，飾丹壤以和璧，加疏楯以連城，至於朱明在運，鬱夕嚣晨，寒堂涼結，清觀風臻，覽茲宇之靈緯，啟聖情以寤神，豈宣曲之妄擬，焉甘泉之足陳。","sortOrder":141},
  {"id":"s_work_nvlt_62_142","chapterId":"ch_work_nvlt_62","text":"宋何尚之華林清暑殿賦曰：逞綿亘之虹梁，列雕刻之華榱，網戶翠錢，青軒丹墀，若乃奧室曲房，深沉冥密，始如易修，終然難悉，動微物而風生，踐椒涂而芳质，觴遇成宴，暫遊累日，却倚危石，前臨濬穀，終始萧森，激清引濁，涌泉灌於基扈，遠風生於楹曲，暑雖殷而不炎，氣方清而含育，哀鵠唳暮，悲猿啼晓，靈芝被崖，仙華覆沼。","sortOrder":142},
  {"id":"s_work_nvlt_62_143","chapterId":"ch_work_nvlt_62","text":"【銘】後漢李尤德陽殿銘曰：皇穹垂象，以示帝王，紫微之則，弘誕弥光，大漢體天，承以德陽，崇弘高麗，苞受萬方，內綜朝貢，外俟遐荒，陳徐陵太極殿銘曰：夫紫蓋黃旗，扬都之王氣長久，虎踞龍蟠，金陵之地體貞固，天居爽垲，大寢尊嚴，高應瑞門，仰模營室，歸於有德，譬彼河圖，傳我休明，義同商鼎，太極殿者，法互［《初學記》二十四作氐。］象冗，［《初學記》作亢。］王者之位以尊，左平右墄，天子之堂為貴，往朝煨燼，多歷年所，世道隆平，宜其休复，監軍邹子度啟稱，即日忽有一大梓柱，從流來泊，在後渚岸，嵯峨容與，若漢水之仙槎，搖漾波涛，似新亭之龍刹，孤拔靈山，允彰天貺，昔梁氏承聖，將圖繕修，東虜窥江，西胡犯畢，定之方中，亟興師旅，揆之以日，辄有灾故，是知秦人所止，實漢祖而為宮，吳都佳氣，乃元皇而斯宅，千栌赫弈，萬栱崚層，植绿芰而動微風，舒丹莲而製流火，甘泉遠望，睹正殿之峥嵘，函穀遙看，美皇居之佳麗，信可以齊三光而示宇宙，會萬國而朝諸侯，爰命微臣，乃為銘曰：雍畤相望，參差未央，偃師回顧，崔嵬德陽，高扪太一，正睹瑤光，瓘瓘靈柱，赫赫流樟，美矣宮室，嘉哉令日，御扆垂旒，當朝靖跸，樂備韶夏，禮兼文质，帝旅無喧，王旗斯謐，肅肅卿士，邕邕承弼，漢座雕屏，周人槛櫺，城隅有勒，殿省皆銘，况复皇寢，宜昭國經，方流典訓，永树天廷。","sortOrder":143},
  {"id":"s_work_nvlt_62_144","chapterId":"ch_work_nvlt_62","text":"陳沈蜅太極殿銘曰：臣聞在天成象，紫宮所以昭著，在地成形，赤縣居其區宇，太極殿者，資兩儀之意焉，大壮顯其全模，土圭测其正影，周曰路寢，漢稱前殿，雖名號參差，其實一也，主上未明求衣，日旰忘食，隳樂坏禮，造次留神，漢陛秦除，莫不葺复，而此殿興造，累歲未成，外遘戎機，內忧民力，劬勞深慮，荏苒移時，至陳永定，六合既清，五禮稍備，雕楹玉舄，華榱璧璫，揆之有日，而猶一柱，楩楠豫章，地淪外寇，楚材晉用，非复我求，既而新亭前江，有流查甚壮，盤根错節，枝葉葱蒨，津人以聞，正堪時用，於是將作受詔，冬官奉職，百工併作，屢降乘舆，匠石磨砻，必經天旨，俭而不固，泰而不奢，亿兆填填而樂成也，曾未數旬，煥然雲構，昔晉朝繕造，文杏有闕，梅梁瑞至，畫以摽花，自是迄今。又獲神物，即樟树焉，殿之某間即某柱是也，銘曰：軒轅狹堂，夏後卑宮，文來质往，蹇產弥崇，體製八都，开茲萬戶，灼烁雄梁，徘徊大庑，璧月霄懸，卿雲晝聚，豈伊开陽，飛來應柱，嘉辰令月，新寢告成，青槐赤棘，郎將思兵，翠被負扆，百辟公卿，鍾鼓八佾，箫韶九成，庸臣再拜，天子萬齡。","sortOrder":144},
  {"id":"s_work_nvlt_62_145","chapterId":"ch_work_nvlt_62","text":"【表】梁王筠上太極殿表曰：四海為家，義存威重，萬國來朝，事惟壮觀，憲北辰之居所，正南面之尊貴，繡栭鏤槛，延曜光暉，虬柱虹梁，杳冥雲霧，非許鄴之敢倫，豈雍豫之能擬，且工徒樂業，庶民自競，不勞永逸，不日而成，信可以宴饗百神，朝觐群後者矣，臣過荷寵榮，祿秩優润，謹率丹款，上夫一千，不足微申凫躍，伏深慚竦。","sortOrder":145},
  {"id":"s_work_nvlt_62_147","chapterId":"ch_work_nvlt_62","text":"漢宮闕名曰：洛陽故北宮，有九子坊。","sortOrder":147},
  {"id":"s_work_nvlt_62_148","chapterId":"ch_work_nvlt_62","text":"晉宮闕名曰：洛陽宮有顯昌坊修成坊綏福坊延祿坊休徵坊承慶坊桂芬坊椒房坊舒蘭坊藝文坊。","sortOrder":148},
  {"id":"s_work_nvlt_62_149","chapterId":"ch_work_nvlt_62","text":"王隱《晉書》曰：東宮坊有醉相殺者，中丞奏郎官從事孫鑠杖一百，鑠奏，東宮是行馬內，而推行馬外官，為违法令，詔中丞令史各一百。","sortOrder":149},
  {"id":"s_work_nvlt_62_150","chapterId":"ch_work_nvlt_62","text":"王珉答徐邈書曰：見傅鹹彈孫詹事，或雲是宮，或雲坊，或雲寺，此東宮中別有坊。又中庶子稱坊，詹事稱寺，寺同於九卿耳，坊是通名，如天朝之稱台者也。","sortOrder":150},
  {"id":"s_work_nvlt_62_151","chapterId":"ch_work_nvlt_62","text":"【賦】梁萧子范直坊賦曰：餘以天監六年，為洗馬，十七年，复直中舍之坊，感恩懷舊，凄然而作，歲惟奄茂，清明送風，承恩從官，自府遊宮，信吾生之多幸，遭六合之大同，何坊禁之寥阒，對長庭之芜永，門幽幽而重閉，室愔愔而內靜，應晓刻而坐朝，聽鳴鍾而自警，雖生風於蟭螟，終罕曜於陽景，頗留連於九思，恒殷勤於三省，於時也，春果餘英，夏條垂實，殿穹隆而起陰，槐連拳而負日，傍高墉之逦迤，觀層扉之鬱律，寫學宮於洛都，模畫堂於漢室，台榭千名，仙靈間出。","sortOrder":151},
  {"id":"s_work_nvlt_62_152","chapterId":"ch_work_nvlt_62","text":"《藝文類聚》　唐·欧陽詢","sortOrder":152},
  {"id":"s_work_nvlt_63_1","chapterId":"ch_work_nvlt_63","text":"卷六十三居處部三","sortOrder":1},
  {"id":"s_work_nvlt_63_2","chapterId":"ch_work_nvlt_63","text":"○門樓橹觀堂城馆","sortOrder":2},
  {"id":"s_work_nvlt_63_4","chapterId":"ch_work_nvlt_63","text":"《釋名》曰：門，扪也，在外為扪，幕障衛也。","sortOrder":4},
  {"id":"s_work_nvlt_63_5","chapterId":"ch_work_nvlt_63","text":"《爾雅》曰：閍謂之門，正門謂之應門。","sortOrder":5},
  {"id":"s_work_nvlt_63_6","chapterId":"ch_work_nvlt_63","text":"《易》曰：重門击柝，以待暴客。","sortOrder":6},
  {"id":"s_work_nvlt_63_7","chapterId":"ch_work_nvlt_63","text":"《周官》曰：掌舍，掌王會同之舍，設梐枑再重，設車宮轅門，為壇壝宮棘門，為帷宮，設旌門，無宮則供人門。","sortOrder":7},
  {"id":"s_work_nvlt_63_8","chapterId":"ch_work_nvlt_63","text":"《毛詩》曰：衡門之下，可以栖遲。","sortOrder":8},
  {"id":"s_work_nvlt_63_9","chapterId":"ch_work_nvlt_63","text":"又曰：乃立皋門，皋門有闶，乃立應門，應門锵锵。","sortOrder":9},
  {"id":"s_work_nvlt_63_10","chapterId":"ch_work_nvlt_63","text":"《詩義問》曰：橫一木作門，而上無屋，謂之衡門。","sortOrder":10},
  {"id":"s_work_nvlt_63_11","chapterId":"ch_work_nvlt_63","text":"《左傳》曰：楚子囊鄭子耳，围於桐門。","sortOrder":11},
  {"id":"s_work_nvlt_63_12","chapterId":"ch_work_nvlt_63","text":"又曰：王叔之宰曰：荜門圭窦之人，而皆凌其上，其難為上矣。","sortOrder":12},
  {"id":"s_work_nvlt_63_13","chapterId":"ch_work_nvlt_63","text":"又曰：鄭大水，龍斗於時門之外。","sortOrder":13},
  {"id":"s_work_nvlt_63_14","chapterId":"ch_work_nvlt_63","text":"魯連子曰：先生見孟嘗君於杏唐之門。","sortOrder":14},
  {"id":"s_work_nvlt_63_15","chapterId":"ch_work_nvlt_63","text":"《楚辭》曰：望長楸而太息，涕淫淫其若霰，過夏首而西浮，顧龍門而不見。","sortOrder":15},
  {"id":"s_work_nvlt_63_16","chapterId":"ch_work_nvlt_63","text":"《越絕書》曰：楚門，春申君時造，楚人從入，故號楚門。","sortOrder":16},
  {"id":"s_work_nvlt_63_17","chapterId":"ch_work_nvlt_63","text":"《史記》曰：金馬門者，宦者署門也，門傍有銅馬，故謂之曰金馬門。","sortOrder":17},
  {"id":"s_work_nvlt_63_18","chapterId":"ch_work_nvlt_63","text":"《贾誼書》曰：天子宮門曰司馬門。","sortOrder":18},
  {"id":"s_work_nvlt_63_19","chapterId":"ch_work_nvlt_63","text":"又曰：高帝瓜分天下，以王有功之臣，擇良日，立諸侯洛陽上東門之外。","sortOrder":19},
  {"id":"s_work_nvlt_63_20","chapterId":"ch_work_nvlt_63","text":"《說苑》曰：於公筑治庐舍，謂匠人曰：為我高門，我治獄未嘗有冤，後世必有封侯者，令容高蓋驷馬，及後果封為西平侯。","sortOrder":20},
  {"id":"s_work_nvlt_63_21","chapterId":"ch_work_nvlt_63","text":"《漢書》曰：元帝為太子，謹慎，初居桂宮，上急召太子，出龍樓門，不敢絕馳道。","sortOrder":21},
  {"id":"s_work_nvlt_63_22","chapterId":"ch_work_nvlt_63","text":"又曰：太液池南有璧門。","sortOrder":22},
  {"id":"s_work_nvlt_63_23","chapterId":"ch_work_nvlt_63","text":"又曰：陳平家貧，以席為門，然門外多長者車轍。","sortOrder":23},
  {"id":"s_work_nvlt_63_24","chapterId":"ch_work_nvlt_63","text":"《吳越春秋》曰：子胥為吳造大城，陵門八，象天八風，水門八，法地八窗。","sortOrder":24},
  {"id":"s_work_nvlt_63_25","chapterId":"ch_work_nvlt_63","text":"范晔《後漢書》曰：孔融雲，鄭君里門，四方所由觀禮，其廣令容高車結驷，名為通德門。","sortOrder":25},
  {"id":"s_work_nvlt_63_26","chapterId":"ch_work_nvlt_63","text":"漢宮殿名曰：長安有宣平門覆盎門萬秋門橫門東都門宣德門元成門青綺門章義門仁寿門〈石巽〉［《太平御覽》一百八十三作慈。］石門。","sortOrder":26},
  {"id":"s_work_nvlt_63_27","chapterId":"ch_work_nvlt_63","text":"魏書曰：文帝初在東宮，集諸儒，於朝肅城［《太平御覽》六百十五作成。］門內，講論大義，侃侃無倦。","sortOrder":27},
  {"id":"s_work_nvlt_63_28","chapterId":"ch_work_nvlt_63","text":"古今地名曰：河南有鼎門，九鼎所定。","sortOrder":28},
  {"id":"s_work_nvlt_63_29","chapterId":"ch_work_nvlt_63","text":"《華陽國志》曰：蜀城十里，有升遷桥，送客觀，司馬相如初入長安，題其門曰：不乘赤車驷馬，不過汝下。","sortOrder":29},
  {"id":"s_work_nvlt_63_30","chapterId":"ch_work_nvlt_63","text":"吳地記曰：閶阖門者，吳王阖闾所作也，名為閶阖門，高樓閣道，後由此出伐楚，改曰破楚門。","sortOrder":30},
  {"id":"s_work_nvlt_63_31","chapterId":"ch_work_nvlt_63","text":"《世說》曰：楊脩為魏武主簿，作相國門，始構榱桷，魏武自看，使人題門作活字，便去，楊脩見，即令坏之，既竟，曰：門中活闊字，王嫌門大也。","sortOrder":31},
  {"id":"s_work_nvlt_63_32","chapterId":"ch_work_nvlt_63","text":"【銘】後漢李尤門銘曰：門之設張，為宅表會，納善閉邪，击柝防害。","sortOrder":32},
  {"id":"s_work_nvlt_63_33","chapterId":"ch_work_nvlt_63","text":"又中東門銘曰：中東處仲，月值當昴，仓庚有聲，隼鷹匿爪，除去桎梏，獄訟勿考。","sortOrder":33},
  {"id":"s_work_nvlt_63_34","chapterId":"ch_work_nvlt_63","text":"又關陽城門銘曰：關陽在孟，位月惟巳，清明冠節，大陽進起。","sortOrder":34},
  {"id":"s_work_nvlt_63_35","chapterId":"ch_work_nvlt_63","text":"又津城門銘曰：津名自定，位月在未，溫風鬱暑，鷹鳥習鷙。","sortOrder":35},
  {"id":"s_work_nvlt_63_36","chapterId":"ch_work_nvlt_63","text":"又廣陽門銘曰：廣陽位孟，厥月在申，涼風從時，白露已分。","sortOrder":36},
  {"id":"s_work_nvlt_63_37","chapterId":"ch_work_nvlt_63","text":"又雍城門銘曰：雍門處中，位月在酉，盲風寒濁，燕歸山阜。","sortOrder":37},
  {"id":"s_work_nvlt_63_38","chapterId":"ch_work_nvlt_63","text":"又夏城門銘曰：夏門值孟，位月在亥，陰陽不通，蝃蝀匿彩，迎冬北壇，從陰所在。","sortOrder":38},
  {"id":"s_work_nvlt_63_39","chapterId":"ch_work_nvlt_63","text":"又穀城門銘曰：穀門北中，位當於子，太陰主刑，殺伐為首。","sortOrder":39},
  {"id":"s_work_nvlt_63_40","chapterId":"ch_work_nvlt_63","text":"晉挚虞門銘曰：祿無常家，福無定門，人謀鬼謀，道在則尊。","sortOrder":40},
  {"id":"s_work_nvlt_63_41","chapterId":"ch_work_nvlt_63","text":"【文】後魏溫子昇閶阖門上梁祝文曰：維王建國，配彼太微，大君有命，高門啟扉，良辰是簡，穆卜無违，雕梁乃架，綺翼斯飛，八龍杳杳，九龍巍巍，居宸納祐，就日垂衣，一人有慶，四海爰歸。","sortOrder":41},
  {"id":"s_work_nvlt_63_43","chapterId":"ch_work_nvlt_63","text":"《爾雅》曰：狹而修曲曰樓。","sortOrder":43},
  {"id":"s_work_nvlt_63_44","chapterId":"ch_work_nvlt_63","text":"《說文》曰：樓，重屋也，樔，泽中守竹樓也。","sortOrder":44},
  {"id":"s_work_nvlt_63_45","chapterId":"ch_work_nvlt_63","text":"黃帝占軍氣决曰：諸將軍氣如城樓。","sortOrder":45},
  {"id":"s_work_nvlt_63_46","chapterId":"ch_work_nvlt_63","text":"《史記》曰：方士言武帝曰：黃帝為五城十二樓，以候神人，帝乃立神明台井幹樓，高五十丈，輦道相屬。","sortOrder":46},
  {"id":"s_work_nvlt_63_47","chapterId":"ch_work_nvlt_63","text":"《十洲記》曰：崑崙山有十二玉樓。","sortOrder":47},
  {"id":"s_work_nvlt_63_48","chapterId":"ch_work_nvlt_63","text":"《漢書》曰：甘延寿，少以良家子，善騎射，嘗超逾羽林亭樓，由是遷為郎。","sortOrder":48},
  {"id":"s_work_nvlt_63_49","chapterId":"ch_work_nvlt_63","text":"《吳越春秋》曰：范蠡為句踐立飛翼樓，以象天門。","sortOrder":49},
  {"id":"s_work_nvlt_63_50","chapterId":"ch_work_nvlt_63","text":"《東觀漢記》曰：上至廣阿，止城門樓上，披舆地圖，指示邓禹曰：天下郡國如是，我乃始得一處，卿言天下不足定何也。","sortOrder":50},
  {"id":"s_work_nvlt_63_51","chapterId":"ch_work_nvlt_63","text":"《吳志》曰：劉基美容姿，孫權愛敬之，權暑時，嘗於舡中宴樓上，作雷雨，權以蓋自覆。又命覆基，餘人不得也。","sortOrder":51},
  {"id":"s_work_nvlt_63_52","chapterId":"ch_work_nvlt_63","text":"《虞氏家記》曰：吳小城白門，蓋吳王阖闾所作也，至秦始皇，守宮吏燭燕窟，失火燒宮，而此樓故存。","sortOrder":52},
  {"id":"s_work_nvlt_63_53","chapterId":"ch_work_nvlt_63","text":"《晉宮閣名》曰：總章觀，儀風樓一所，在觀上，廣望觀之南。又別有翔鳳樓。","sortOrder":53},
  {"id":"s_work_nvlt_63_54","chapterId":"ch_work_nvlt_63","text":"《賴乡記》曰：老子廟有皇天樓九柱樓靜念樓，皆畫仙人雲氣。","sortOrder":54},
  {"id":"s_work_nvlt_63_55","chapterId":"ch_work_nvlt_63","text":"袁彦伯羅山疏曰：仰望石樓，眇然在雲中。","sortOrder":55},
  {"id":"s_work_nvlt_63_56","chapterId":"ch_work_nvlt_63","text":"《世說》曰：凌雲台樓觀極精巧，先稱平眾材，輕重當宜，然後造構，乃無锱銖相負揭，台雖高崚，恒隨風搖動，魏明帝登台，懼其势危，別以大材扶持之，樓即便頹坏，論者謂輕重力偏故也。","sortOrder":56},
  {"id":"s_work_nvlt_63_57","chapterId":"ch_work_nvlt_63","text":"《幽明錄》曰：鄴城鳳陽門五層樓，去地二十丈，長四十丈，廣二十丈，安金鳳皇二頭於其上，一頭飛入漳河，清浪［《太平御覽》一百七十六作朗。］見在水底，一頭今猶存。","sortOrder":57},
  {"id":"s_work_nvlt_63_58","chapterId":"ch_work_nvlt_63","text":"述異傳曰：荀朅，字叔伟，寓居江陵，憩江夏黃鵠樓上，望西南，有物飄然，降自雲漢，俄頃已至，乃駕鶴之賓也，鶴止戶侧，仙者就席，羽衣虹裳，賓主歡對，辭去，跨鶴騰空，眇然煙滅。","sortOrder":58},
  {"id":"s_work_nvlt_63_59","chapterId":"ch_work_nvlt_63","text":"【詩】古詩曰：西北有高樓，上與浮雲齊，交疏結綺窗，阿閣三重階。","sortOrder":59},
  {"id":"s_work_nvlt_63_60","chapterId":"ch_work_nvlt_63","text":"宋文帝登景陽樓詩曰：崇堂臨萬雉，曾樓跨九成，瑤軒籠翠幌，組幕翳雲屏，階上晓露絜，林下夕風清，蔓藻嬛绿葉，芳蘭媚紫茎，極望周天险，留察浃神京，交渠紛綺错，列植發華英。","sortOrder":60},
  {"id":"s_work_nvlt_63_61","chapterId":"ch_work_nvlt_63","text":"梁武帝登北顧樓詩曰：歇駕止行警，回舆暫遊識，清道巡丘壑，缓步肆登陟，雁行上差池，羊腸轉相逼，歷覽窮天步，曬矚盡地域，南城連地险，北顧臨水侧，深潭下無底，高岸長不测，舊屿石若構，新洲花如織。","sortOrder":61},
  {"id":"s_work_nvlt_63_62","chapterId":"ch_work_nvlt_63","text":"梁簡文帝奉和登北顧樓詩曰：舂陵佳氣地，濟水鳳皇宮，况此徐方域，川嶽邁同沣，皇情愛歷覽，遊陟擬崆峒，聊驅式道候，無勞襄野童，霧崖开早日，晴天歇晚虹，去帆入雲里，遙星出海中。","sortOrder":62},
  {"id":"s_work_nvlt_63_63","chapterId":"ch_work_nvlt_63","text":"又登烽火樓詩曰：耸樓排树出，却堞帶江清，陟峰试遠望，鬱鬱盡郊京，萬邑王畿曠，三條綺陌平，亘原橫地险，孤屿派流生，悠悠歸棹入，眇眇去帆驚，水煙浮岸起，遙禽逐霧征。","sortOrder":63},
  {"id":"s_work_nvlt_63_64","chapterId":"ch_work_nvlt_63","text":"又水中樓影詩曰：水底罘罳出，萍間反宇浮，風生色不坏，浪去影恒留。","sortOrder":64},
  {"id":"s_work_nvlt_63_65","chapterId":"ch_work_nvlt_63","text":"梁沈約登玄畅樓詩曰：危峰帶北阜，圓鼎出南岑，中有凌風树，回望川之陰，涯心，落岸每增减，湍平互淺深，水流本三派，台高乃四臨，上有離群客，客有慕歸暉映長浦，煥景燭中尋，雲生嶺乍黑，日下溪半陰，信美非吾土，何事不抽簪。","sortOrder":65},
  {"id":"s_work_nvlt_63_66","chapterId":"ch_work_nvlt_63","text":"梁劉孝綽登陽雲樓詩曰：吾土陽台上，非夢高台客，回首望長安，千里懷三益，顧惟慚入楚，降私等申白，西沮水潦收，昭丘霜露積，龍門不可見，空慕凌霜柏。","sortOrder":66},
  {"id":"s_work_nvlt_63_67","chapterId":"ch_work_nvlt_63","text":"梁王台卿詠水中樓影詩曰：飄飖似雲度，亭亭如蓋浮，熟看波不動，還是映高樓。","sortOrder":67},
  {"id":"s_work_nvlt_63_68","chapterId":"ch_work_nvlt_63","text":"【賦】魏王粲登樓賦曰：登茲樓以四望，聊暇日以銷忧，覽斯宇之所處，實顯敞而寡仇，接清漳之通浦，倚曲阻之長洲，北弥陶牧，西接昭丘，雖信美而非吾土，曾何足以少留，凭軒槛以遙望，向北風而开襟，平原遠而目極，蔽荆山之高岑，路逶迤而脩回，川既漾而濟深，昔尼父之在陳，有歸欤之叹音，鍾儀幽而楚奏，莊舄顯而越吟，人情同於懷土，豈窮達之異心，惟日月之逾邁，俟河清其何極，冀王道之一平，假高衢而騁力，步栖遲而徙倚，白日忽其西匿，風萧瑟而併興，天惨惨而無色，獸狂顧以求群，鳥相鳴而鼓翼，原野阒其無人，征夫行而未息，循階除而下降，氣交憤於焜臆，夜參半而不寐，怅盤桓以反侧。","sortOrder":68},
  {"id":"s_work_nvlt_63_69","chapterId":"ch_work_nvlt_63","text":"晉孫楚登樓賦曰：有都城之百雉，加曾樓之五尋，從明王之登遊，聊暇日以娱心，鳴鳩拂羽於桑榆，遊凫濯翅於素波，牧竖吟嘯於行陌，舟人鼓枻而扬歌，百僚雲集，促坐華台，嘉肴滿俎，旨酒盈杯，談三墳而詠五典，釋聖哲之所裁。","sortOrder":69},
  {"id":"s_work_nvlt_63_70","chapterId":"ch_work_nvlt_63","text":"晉棗據登樓賦曰：懷離客之遠思，情惨悯而惆怅，登茲樓而逍遙，聊因高以遐望，感斯州之厥域，寔帝王之舊疆，挹呼沱之濁河，懷通川之清漳，原隰开辟，荡臻夷藪，桑麻被野，黍稷盈畝，禮儀既度，民繁财阜，懷桑梓之舊愛，信古今之同情，鍾儀惨而南音，莊舄感而越聲，豈吾人之狹隘，能去心而無營，情戚戚於下國，意乾乾於上京。","sortOrder":70},
  {"id":"s_work_nvlt_63_71","chapterId":"ch_work_nvlt_63","text":"晉郭璞登百尺樓賦曰：在青陽之季月，登百尺以高觀，嘉斯遊之可娱，乃老氏之所叹，撫凌槛以遙想，乃極目而肆運，情眇然以思遠，怅自失而潛慍，瞻禹台之隆嚬，奇巫鹹之孤峙，美鹽池之滉汙，蒸紫雰而霞起，異傅巖之幽人，神介山之伯子，揖首陽之二老，招鬼穀之隱士，嗟王室之蠢蠢，方構怨而極武，哀神器之遷浪，指缀旒以譬主，雄戟列於廊技，戎馬鳴乎講柱，寤苕華而增怪，叹飛驷之過戶，陟茲樓以曠眺，情慨爾而懷古。","sortOrder":71},
  {"id":"s_work_nvlt_63_72","chapterId":"ch_work_nvlt_63","text":"【銘】宋鮑昭凌煙樓銘曰：瞰列江楹，望景延除，積清風路，含彩煙途，俯窥淮海，俯眺荆吳，我王結駕，藻思神居，宜此萬春，脩靈所扶。","sortOrder":72},
  {"id":"s_work_nvlt_63_74","chapterId":"ch_work_nvlt_63","text":"《釋名》曰：橹，露上無覆屋也。","sortOrder":74},
  {"id":"s_work_nvlt_63_75","chapterId":"ch_work_nvlt_63","text":"孫子兵法曰：攻城之法，修橹枌榅，其器械三月而後成。","sortOrder":75},
  {"id":"s_work_nvlt_63_76","chapterId":"ch_work_nvlt_63","text":"陆機洛陽記曰：洛陽城，周公所製，東西十里，南北十三里，城上百步有一樓橹，外有溝渠。","sortOrder":76},
  {"id":"s_work_nvlt_63_77","chapterId":"ch_work_nvlt_63","text":"【賦】晉欧陽建登橹賦曰：登茲橹以遐眺，辟曾軒以高盻，仰天涂之綿邈，俯平原之曠衍，嘉蒼春之令節，悅和風之微扇，傍觀八隅，周覽四垂，面孤丘之峻峙，岨曲岸之脩崖，植榆楸以成列，插垂柳之差差，寓目忽以終日，情亹亹而忘疲。","sortOrder":77},
  {"id":"s_work_nvlt_63_79","chapterId":"ch_work_nvlt_63","text":"《釋名》曰：觀者，於上觀望也。","sortOrder":79},
  {"id":"s_work_nvlt_63_80","chapterId":"ch_work_nvlt_63","text":"《列子》曰：岱舆山上台觀，皆金玉，仙聖飛相來往。","sortOrder":80},
  {"id":"s_work_nvlt_63_81","chapterId":"ch_work_nvlt_63","text":"《史記》曰：公孫卿謂武帝曰：仙人好樓居，於是上令長安作飛廉桂觀，甘泉則作延寿觀。","sortOrder":81},
  {"id":"s_work_nvlt_63_82","chapterId":"ch_work_nvlt_63","text":"《漢書》曰：甘露二年，冬十二月，上幸蒷陽宮屬玉觀。","sortOrder":82},
  {"id":"s_work_nvlt_63_83","chapterId":"ch_work_nvlt_63","text":"又曰：孝成皇帝，元帝太子也，生甲觀畫堂。","sortOrder":83},
  {"id":"s_work_nvlt_63_84","chapterId":"ch_work_nvlt_63","text":"三辅皇圖曰：武帝起鳷鵲觀，神明觀，集靈觀，陽祿觀。","sortOrder":84},
  {"id":"s_work_nvlt_63_85","chapterId":"ch_work_nvlt_63","text":"漢宮殿名曰：長安有臨仙觀，渭桥觀，仙人觀，霸昌觀，蘭池觀，平樂觀，九華觀，豫章觀，三章觀，崑明觀，走馬觀，華光觀，封峦觀，走狗觀，天梯觀，瑤台觀，氵不渠觀，相思觀，長平觀，宜春觀，華池觀，射熊觀，迎風觀，露寒觀。","sortOrder":85},
  {"id":"s_work_nvlt_63_86","chapterId":"ch_work_nvlt_63","text":"《魏志》曰：明帝置崇文觀，徵善屬文者以充之。","sortOrder":86},
  {"id":"s_work_nvlt_63_87","chapterId":"ch_work_nvlt_63","text":"陆機洛陽地記曰：宮中有臨高，陵雲，宣曲，廣望，阆風，萬世，修齡，總章，聽訟，凡九觀，皆高十六七丈，以雲母著窗里，日曜之，煒煒有光辉，華延俊洛陽記曰：洛陽城十八觀，皆施玄槛鐵籠，疏雲母幌。","sortOrder":87},
  {"id":"s_work_nvlt_63_88","chapterId":"ch_work_nvlt_63","text":"華山記曰：南嶺東巖北面，有二小山，一山有双石竖生，號曰石門，一山石孤崖特秀，上有客觀，涉之，遠者眺十里。","sortOrder":88},
  {"id":"s_work_nvlt_63_89","chapterId":"ch_work_nvlt_63","text":"【詩】隋江總侍宴玄武觀詩曰：詰晓三春暮，新雨百花朝，星宮移渡漢，天驷動行鑣，旆轉蒼龍闕，尘飛飲馬桥，翠觀迎斜照，丹樓望落潮，鳥聲雲里出，树彩浪中搖，歌吟奉天詠，未必待聞韶。","sortOrder":89},
  {"id":"s_work_nvlt_63_90","chapterId":"ch_work_nvlt_63","text":"【賦】後漢崔骃大將軍臨洛觀賦曰：濱曲洛而立觀，營高壤而作庐，處崇顯以間敞，超絕鄰而特居，列阿閣以環匝，表高台而起樓，步輦道以周流，臨軒槛以觀魚，於是迎夏之首，末春之垂，桃枝夭夭，楊柳猗猗，既乃日垂西陽，中曜內光，弛衔縱策，逸如奔颺。","sortOrder":90},
  {"id":"s_work_nvlt_63_91","chapterId":"ch_work_nvlt_63","text":"後漢李尤平樂觀賦曰：乃設平樂之顯觀，章秘玮之奇珍，習禁武以講捷，厭不羁之遐鄰，徒觀平樂之製，鬱崔嵬以離娄，赫巖巖其崟峉，紛電影以盤盱，弥平原之博敞，處金商之維陬，大厦累而鱗次，承岧峣之翠樓，過洞房之轉闼，歷金環之華鋪，南切洛濱，北陵仓山，龟池泱漭，果林榛榛，天馬沛艾，鬛尾布分，爾乃大和隆平，萬國肅清，殊方重譯，絕域造庭，四表交會，抱珍遠併，雜遝歸誼，集於春正，玩屈奇之神怪，顯逸才之捷武，百僚於時，各命所主，方曲既設，秘戲連叙，逍遙俯仰，節以鞀鼓，戲車高橦，馳騁百馬，連翩九仞，離合上下，或以馳騁，覆車顛倒，乌獲扛鼎，千鈞若羽，吞刃吐火，燕躍乌跱，陵高履索，踴躍旋舞，飛丸跳劍，沸渭回扰，巴渝隈一，逾肩相受，有仙駕雀，其形蚴虬，騎驢馳射，狐兔驚走，侏儒巨人，戲謔為耦，禽鹿六駮，白象朱首，魚龍曼延，嵔〈山延〉山阜，龟螭蟾蜍，挈琴鼓缶。","sortOrder":91},
  {"id":"s_work_nvlt_63_92","chapterId":"ch_work_nvlt_63","text":"又東觀賦曰：敷華實於雍堂，集幹质於東觀，東觀之藝，孽孽洋洋，上承重閣，下屬周廊，步西蕃以徙倚，好绿树之成行，歷東厓之敞坐，庇蔽茅之甘棠，前望雲台，後匝德陽，道無隱而不顯，書無闕而不陳，覽三代而采宜，包鬱鬱之周文。","sortOrder":92},
  {"id":"s_work_nvlt_63_93","chapterId":"ch_work_nvlt_63","text":"魏陳王曹植遊觀賦曰：靜閒宮而無事，將遊目以自娱，登北觀而啟路，涉雲路之飛除，從熊羆之武士，荷長戟而先驅，罢若雲歸，會如霧聚，車不及回，尘不獲舉，奋袂成風，揮汗如雨。","sortOrder":93},
  {"id":"s_work_nvlt_63_94","chapterId":"ch_work_nvlt_63","text":"又臨觀賦曰：登高墉兮望四泽，臨長流兮送遠客，春風畅兮氣通靈，草含幹兮木交茎，丘陵窟兮松柏青，南園薆兮果戴榮，樂時物之逸豫，悲予志之長违，叹東山以愬勤，歌式微以詠歸，進無路以效公，退無隱以營私，俯無鱗以遊遁，仰無翼以翻飛。","sortOrder":94},
  {"id":"s_work_nvlt_63_95","chapterId":"ch_work_nvlt_63","text":"【銘】後漢李尤東觀銘曰：周氏舊區，皇漢寔循，房闼內布，疏綺外陳，升降三除，貫啟七門，是謂東觀，書籍林泉，列侯弘雅，治掌藝文。","sortOrder":95},
  {"id":"s_work_nvlt_63_97","chapterId":"ch_work_nvlt_63","text":"《說文》曰：堂，殿也。","sortOrder":97},
  {"id":"s_work_nvlt_63_98","chapterId":"ch_work_nvlt_63","text":"《釋名》曰：堂猶堂堂，高顯貌也。","sortOrder":98},
  {"id":"s_work_nvlt_63_99","chapterId":"ch_work_nvlt_63","text":"《禮記》曰：堂上不趨，堂上接武，堂下布武。","sortOrder":99},
  {"id":"s_work_nvlt_63_100","chapterId":"ch_work_nvlt_63","text":"又曰：觐禮，天子不下堂而見諸侯，下堂見諸侯，天子之失禮也，由夷王以下。","sortOrder":100},
  {"id":"s_work_nvlt_63_101","chapterId":"ch_work_nvlt_63","text":"《莊子》曰：覆杯水於坳堂之上，則芥為之舟，置杯焉則膠，水淺而舟大也。","sortOrder":101},
  {"id":"s_work_nvlt_63_102","chapterId":"ch_work_nvlt_63","text":"《楚辭》曰：魚鱗屋兮龍堂。","sortOrder":102},
  {"id":"s_work_nvlt_63_103","chapterId":"ch_work_nvlt_63","text":"《十洲記》曰：崑崙山有光碧之堂。","sortOrder":103},
  {"id":"s_work_nvlt_63_104","chapterId":"ch_work_nvlt_63","text":"《說苑》曰：聖人於天下，譬猶一堂之上也，今有滿堂飲酒者，有一人猶向隅而泣，則一堂之人皆為之不樂。","sortOrder":104},
  {"id":"s_work_nvlt_63_105","chapterId":"ch_work_nvlt_63","text":"《漢武內傳》曰：上元夫人言，西王母有六甲之術，用之可以遊景雲之宮，登流霞之堂。","sortOrder":105},
  {"id":"s_work_nvlt_63_106","chapterId":"ch_work_nvlt_63","text":"《漢武故事》曰：玉堂去地十二丈，基階皆用玉也。","sortOrder":106},
  {"id":"s_work_nvlt_63_107","chapterId":"ch_work_nvlt_63","text":"《漢書》曰：玉堂在太液池南。","sortOrder":107},
  {"id":"s_work_nvlt_63_108","chapterId":"ch_work_nvlt_63","text":"《續漢書》曰：中平二年，造萬金堂於西園。","sortOrder":108},
  {"id":"s_work_nvlt_63_109","chapterId":"ch_work_nvlt_63","text":"《論衡》曰：王者之堂，墨子稱尧舜堂高三尺，儒家以為卑下，假使之然，高三尺之堂，蓂荚生於階下，須臨堂察之，起视堂下之荚，孰與懸，日歷於扆坐，顧辄見之也。","sortOrder":109},
  {"id":"s_work_nvlt_63_110","chapterId":"ch_work_nvlt_63","text":"《風俗通》曰：殿堂象東井形，刻作荷菱，荷菱水物也，所以厭火。","sortOrder":110},
  {"id":"s_work_nvlt_63_111","chapterId":"ch_work_nvlt_63","text":"《晉宮閣名》曰：洛陽宮有則百堂，螽斯堂，休徵堂，延祿堂，承慶堂，仁寿堂，綏福堂，含芳堂，樂昌堂，椒華堂，芳音堂，永光堂。","sortOrder":111},
  {"id":"s_work_nvlt_63_112","chapterId":"ch_work_nvlt_63","text":"挚虞决疑要註曰：殿堂之上，唯天子居床，其餘皆幅席，席前設筵，禮，天子之殿，東西九筵，南北七筵，故曰度堂以筵，度室以幾。","sortOrder":112},
  {"id":"s_work_nvlt_63_113","chapterId":"ch_work_nvlt_63","text":"《華陽國志》曰：文翁立講堂，作石室一，曰玉堂，在城南，初堂遇火，太守更修立。又增二石室。","sortOrder":113},
  {"id":"s_work_nvlt_63_114","chapterId":"ch_work_nvlt_63","text":"《虞氏家記》曰：虞潭，右衛將軍，太夫人年高，求解職，被詔不聽，特假百日，迎母東歸，起堂養親，親集會，作詩言志。","sortOrder":114},
  {"id":"s_work_nvlt_63_115","chapterId":"ch_work_nvlt_63","text":"齊地記曰：臨淄城西門外，有古講堂，基柱猶存，齊宣王修文學處也。","sortOrder":115},
  {"id":"s_work_nvlt_63_116","chapterId":"ch_work_nvlt_63","text":"【詩】梁庾肩吾詠疏圃堂詩曰：北堂多暇豫，時駕總鸞鑣，疏靜繁葭澈，輪輕羽蓋飄，臨空坐飛觀，回首望浮桥，風長旦鍾近，地迥洛城遙，疏林不得日，涸浦暫通潮，徒然等賓從，併作愧群僚。","sortOrder":116},
  {"id":"s_work_nvlt_63_117","chapterId":"ch_work_nvlt_63","text":"【賦】陳江總雲堂賦曰：覽黃圖之棟宇，規紫宸於太清，何面势之膠葛，信不日之經營，仰一時之壮麗，跨萬古之威靈，吐觸石之奇色，混高堂之舊名，若乃三階八戶，百栱千楹，瑩以玉琇，飾以金英，绿芰懸插，紅蕖倒生，於時木葉聲寒，壶人唱靜，承露擎虛，相風照迥，天子乃下輦开宴，出豫娱神，文懸日月，思革風尘，是負鳳之多幸，愧屠龍之不真。","sortOrder":117},
  {"id":"s_work_nvlt_63_118","chapterId":"ch_work_nvlt_63","text":"【頌】晉庾闡樂賢堂頌曰：瓘瓘隆構，岌岌其峻，階延白屋，寢登髦俊，神心所寄，莫往非順，靈圖表像，平敷玉润，遊虬一壑，栖鸞一丛，川澄華沼，树拂椅桐，林有晨風，翮有西雍，高觀回雲，疏猋綺窗，洋洋帝猷，恢恢天造，思樂雲基，克配祖考，仰瞻崑丘，俯懷明聖，玄珠雖朗，離人莫映，清風徘徊，微言絕詠，有邈高構，永廓靈命。","sortOrder":118},
  {"id":"s_work_nvlt_63_119","chapterId":"ch_work_nvlt_63","text":"【銘】後漢李尤堂銘曰：因邑製宅，爰興殿堂，夏屋渠渠，高敞清涼，家以師禮，修奉蒸嘗，延賓西階，主近東厢，宴樂嘉客，吹笙鼓簧。","sortOrder":119},
  {"id":"s_work_nvlt_63_121","chapterId":"ch_work_nvlt_63","text":"《淮南子》曰：鯀作九仞之城。","sortOrder":121},
  {"id":"s_work_nvlt_63_122","chapterId":"ch_work_nvlt_63","text":"《說文》曰：城，以盛民也，墉，城垣也。","sortOrder":122},
  {"id":"s_work_nvlt_63_123","chapterId":"ch_work_nvlt_63","text":"《博物志》曰：禹作城，彊者攻，弱者守，敵者戰，城郭自禹始也。","sortOrder":123},
  {"id":"s_work_nvlt_63_124","chapterId":"ch_work_nvlt_63","text":"《周書》曰：周公作大邑成周於土中，立城，方千六百二十丈，郛方七十二里，南系於洛水，北因於陝山。","sortOrder":124},
  {"id":"s_work_nvlt_63_125","chapterId":"ch_work_nvlt_63","text":"公羊傳曰：城雉者何，五板而堵，五堵而雉，百雉而城。","sortOrder":125},
  {"id":"s_work_nvlt_63_126","chapterId":"ch_work_nvlt_63","text":"《史記》曰：秦二世欲漆城，優旃曰：善哉，漆城荡荡，寇來不得上，固難為荫屋爾，二世乃止。","sortOrder":126},
  {"id":"s_work_nvlt_63_127","chapterId":"ch_work_nvlt_63","text":"《淮南子》曰：崑崙山有曾城九重。","sortOrder":127},
  {"id":"s_work_nvlt_63_128","chapterId":"ch_work_nvlt_63","text":"《列女傳》曰：齊人杞梁，袭莒戰而死，其妻無所歸，乃枕夫尸於城下而哭之，七日而城崩，妻遂投淄水而死，《太康地記》曰：梁孝王筑睢陽城，方十二里，以鼓唱節杵而後下，和之者稱睢陽，因以為名。","sortOrder":128},
  {"id":"s_work_nvlt_63_129","chapterId":"ch_work_nvlt_63","text":"《漢書》曰：神農之教曰：有石城十仞，湯池百步，帶甲百萬，而無粟不能守也。","sortOrder":129},
  {"id":"s_work_nvlt_63_130","chapterId":"ch_work_nvlt_63","text":"又曰：膠東前國王，治膠河，水分流繞城下，故號膠河，［按本條見漢書九十六西域傳，作車師前國王治交河城，河水分流繞城下，故號交河，此有訛誤，《太平御覽》一百九十二引不誤。］","sortOrder":130},
  {"id":"s_work_nvlt_63_131","chapterId":"ch_work_nvlt_63","text":"《風俗通》曰：眾心成城，《俗說》曰：眾人同心者，可共筑起一城，同心共飲，雒陽酒可盡也，《關中記》曰：長安城皆黑壤，城今赤如火，堅如石，父老所傳，盡凿龍首山土為城。又諸台闕亦爾。","sortOrder":131},
  {"id":"s_work_nvlt_63_132","chapterId":"ch_work_nvlt_63","text":"王隱《晉書》曰：涼州城有臥龍形，故名臥龍城，南北七十里，東西三十里，本匈奴所筑也。","sortOrder":132},
  {"id":"s_work_nvlt_63_133","chapterId":"ch_work_nvlt_63","text":"《襄陽耆舊記》曰：庞德公在沔水上，至老不入襄陽城。","sortOrder":133},
  {"id":"s_work_nvlt_63_134","chapterId":"ch_work_nvlt_63","text":"《丹陽記》曰：石頭城，因山為城，江以為池，地形险固，尤省奇势。","sortOrder":134},
  {"id":"s_work_nvlt_63_135","chapterId":"ch_work_nvlt_63","text":"《秦州記》曰：金城郡，漢元始六年置，應劭曰：初筑城，得金，故曰金城。","sortOrder":135},
  {"id":"s_work_nvlt_63_136","chapterId":"ch_work_nvlt_63","text":"盛弘之《荆州記》曰：樊城西北有尤阝城，西百餘里，有鼓城，鼓伯綏之國，城門有石人焉，刊其腹雲，摩兜鞬，摩兜鞬，慎莫言，疑此亦周太廟金人緘口銘背之流也。","sortOrder":136},
  {"id":"s_work_nvlt_63_137","chapterId":"ch_work_nvlt_63","text":"荆州圖經曰：江夏郡所治夏口城，其西南角，因磯為高墉，枕流，上則回眺山川，下則激浪崎嶇，是曰黃鵠磯，寔乃舟人之所艱也。","sortOrder":137},
  {"id":"s_work_nvlt_63_138","chapterId":"ch_work_nvlt_63","text":"《益州記》曰：益州城，張儀所筑，錦城在州南，蜀時故宮也，處號錦里。","sortOrder":138},
  {"id":"s_work_nvlt_63_139","chapterId":"ch_work_nvlt_63","text":"齊地記曰：不夜城，在陽廷東南，蓋古有日夜出此城，以不夜名，異之也。","sortOrder":139},
  {"id":"s_work_nvlt_63_140","chapterId":"ch_work_nvlt_63","text":"【詩】梁簡文帝從頓還城詩曰：漢渚水初渌，江南草复黃，日照蒲心暖，風吹梅枝香，征舻舣湯巉，歸騎息金隍，舞觀衣恒襞，歌台絃未張，持此橫行去，誰念守空床。","sortOrder":140},
  {"id":"s_work_nvlt_63_141","chapterId":"ch_work_nvlt_63","text":"又登城詩曰：日影半東簷，靖念空杼柚，小堂倦縹書，華池厭脩竹，寂寞既寡悰，登城望原陆，遙山半吐雲，嚴飆時响穀，靡靡見虛煙，森森视寒木，落霞乍續斷，晚浪時回复，遠矚既濡翰，徒自勞心目，短歌雖可裁，緣情非霧縠。","sortOrder":141},
  {"id":"s_work_nvlt_63_142","chapterId":"ch_work_nvlt_63","text":"又登城北望詩曰：登樓傳昔賦，出蓟表前聞，霸陵忽回首，河隄徒望軍，茲焉聊回眺，極目杳難分，一水斜开岸，双城遙共雲。","sortOrder":142},
  {"id":"s_work_nvlt_63_143","chapterId":"ch_work_nvlt_63","text":"梁江淹登紀南城詩曰：恭承前嘉惠，末官至南荆，斂衽承光彩，端笏奉仁明，再逢绿草合，重見翠雲生，江甸知禮富，漢渚聞教清，君王澹以思，树羽望楚城，年積衣劍滅，地遠宮馆平。","sortOrder":143},
  {"id":"s_work_nvlt_63_144","chapterId":"ch_work_nvlt_63","text":"【賦】魏文帝登城賦曰：孟春之月，惟歲權舆，和風初畅，有穆其舒，駕言東道，陟彼城樓，逍遙遠望，乃欣以娱，平原博敞，中田辟除，嘉麥被垄，緣路帶衢，流茎散葉，列倚相扶，水幡幡其長流，魚裔裔而東馳，風飄飖而既臻，日掩薆而西移，望舊馆而言旋，永優遊而無為。","sortOrder":144},
  {"id":"s_work_nvlt_63_145","chapterId":"ch_work_nvlt_63","text":"晉孫楚登城賦曰：有都城之百雉，加層樓之五尋，從明王以登極，聊暇日以娱心，涇渭汨以徂邁，卉木鬱而成林，晞朝陽之素暉，羨绿竹之茂陰，望秦墳於驪山。睹八陵於北岑，營巷基峙，列宅萬區，黎民布野，商旅充衢，杞柳綢缪，芙蓉吐芳。俯依青川，仰翳朱楊，體象濛汜，幽若扶桑，白日為之晝昏，鳥禽為之頡颃。","sortOrder":145},
  {"id":"s_work_nvlt_63_146","chapterId":"ch_work_nvlt_63","text":"宋鮑昭芜城賦曰：崒若斷岸，矗似長雲，製磁石以御冲，糊赪壤以飛文，觀基扃之固護，將萬杞而一君，出入三代，五百餘載，竟瓜割而豆分，至若白楊早落，塞草前衰，稜稜霜氣，蔌蔌風威，孤蓬自振，驚沙坐飛，通池既已夷，峻隅又已頹，直视千里外，唯見起黃埃，若夫藻扃黼帳，歌台舞閣之基，璇淵碧树，弋林釣渚之馆，吳蔡齊秦之聲，魚龍爵馬之玩，皆薰歇燼滅，光沉响絕，東都妙姬，南國佳人，蕙心紈质，玉貌絳唇，莫不埋魂幽石，委骨窮尘，豈憶同輦之愉樂，離宮之苦辛，歌曰：邊風起兮城上寒，井径滅兮丘垄殘，千齡兮萬代，共盡兮何言。","sortOrder":146},
  {"id":"s_work_nvlt_63_147","chapterId":"ch_work_nvlt_63","text":"梁吳筠吳城賦曰：古树荒煙，幾百千年，雲是吳王所筑，越王所遷，東有鑄劍殘水，西有舞鶴故壥，萦具區之廣泽，帶姑蘇之遠山，仆本蓄怨，千悲憶恨，况复荆棘萧森，丛萝弥蔓，亭梧百尺，皆歷地而生枝，階筠萬丈，或至杪而無葉，不見春荷夏堇，唯聞秋蝉冬蝶，木魅晨走，山鬼夜驚，不知九州四海，乃复有此吳城。","sortOrder":147},
  {"id":"s_work_nvlt_63_148","chapterId":"ch_work_nvlt_63","text":"【銘】後漢李尤京師城銘曰：天险匪登，地险丘陵，帝王設险，乾坤是承。","sortOrder":148},
  {"id":"s_work_nvlt_63_150","chapterId":"ch_work_nvlt_63","text":"《說文》曰：馆，客舍也。","sortOrder":150},
  {"id":"s_work_nvlt_63_151","chapterId":"ch_work_nvlt_63","text":"《周禮》曰：五十里有市，市有候馆，候馆有積，以待朝聘之官也。","sortOrder":151},
  {"id":"s_work_nvlt_63_152","chapterId":"ch_work_nvlt_63","text":"《戰國策》曰：燕昭王見郭隗曰：齊因孤國之亂，而袭破燕，對曰：帝者與師處，王者與友處，古者人君，以千金求千里馬者，三年不得，涓人請求之，三月，得千里馬，馬已死，買其首五百金，反以報君，君大怒，對曰：死馬尚市，况生馬乎，期年，千里馬至者二，王欲士，先從隗，隗且見事，况賢於隗者乎，昭王乃筑馆而師之，樂毅邹衍剧辛，皆爭走燕，遂以破齊。","sortOrder":152},
  {"id":"s_work_nvlt_63_153","chapterId":"ch_work_nvlt_63","text":"《漢書》曰：元帝幸長楊射熊馆，布車騎大獵，扬雄作賦以諫。","sortOrder":153},
  {"id":"s_work_nvlt_63_154","chapterId":"ch_work_nvlt_63","text":"又曰：公孫弘起徒步，數十年至宰相，封侯，於是起客馆，开東閤，以延賢人，與參謀議，弘身食一肉脱粟之飯，故人賓客仰衣食，俸祿皆以給之，家無所餘，弘年八十終，後李蔡嚴青翟趙周石慶公孫贺劉屈氂，繼踵為丞相者，客馆丘墟而已，至贺屈氂時，坏已為馬廄車库奴婢室矣。","sortOrder":154},
  {"id":"s_work_nvlt_63_155","chapterId":"ch_work_nvlt_63","text":"《魏志》曰：管寧，字幼安，與同縣邴原相友，俱遊學於異國，聞公孫度令行於海外，遂與平原王烈等，至於遼東，度虛馆以候之。","sortOrder":155},
  {"id":"s_work_nvlt_63_156","chapterId":"ch_work_nvlt_63","text":"《世說》曰：魏明帝為外祖母筑馆於甄氏，既成，謂左右曰：馆當何以為名，侍中缪袭曰：陛下聖思齊於哲王，罔極過於曾闵，此馆之興，情鍾舅氏，宜以渭陽之名。","sortOrder":156},
  {"id":"s_work_nvlt_63_157","chapterId":"ch_work_nvlt_63","text":"荆州圖副曰：襄陽縣南有桃林馆，是則餞行送歸之所萃也。","sortOrder":157},
  {"id":"s_work_nvlt_63_158","chapterId":"ch_work_nvlt_63","text":"【詩】晉袁宏擬古詩曰：高馆百餘仞，迢遞虛中亭，文幌曜琼扇，碧疏映綺櫺。","sortOrder":158},
  {"id":"s_work_nvlt_63_159","chapterId":"ch_work_nvlt_63","text":"【賦】晉張协玄武馆賦曰：爾乃地势夷敞，既膏且腴，環以翠林，帶以赤渠。尋厥先之攸基，寔張氏之舊墟，何魏後之周覽，遂筑馆而起庐，既號玄武，是曰石樓，於是崇墉四匝，丰厦诡譎，烂若丹霞，皎如素雪，璀璨皓〈白幹〉，華璫四垂，接棟連阿，崥嶱參差，朱戶青鋪，幽闼秘閨，於是高樓特起，竦峙岧峣，飛甍四註。上概浮霄，直亭亭以孤立，迎千里之清飆，陽扉南啟，陰軒北達，春牖左开，秋窗右豁，仰视雲根，俯臨天末，木則楸梓夹路，蓊蔚如林，洪幹十围，脩枝百尋。","sortOrder":159},
  {"id":"s_work_nvlt_63_160","chapterId":"ch_work_nvlt_63","text":"晉潘尼東武馆賦曰：東武馆者，蓋東武陽侯之馆也，嘉大雅之弘操，美明哲之保身，懲都邑之迫险，餍里巷之嚣尘，慕古公之胥宇，羨孟氏之審鄰，將遷居於爽垲，乃投跡於里仁，前則行旅四凑，通衢交會，水泛輕舟，陆方羽蓋，後則崇山崔嵬，茂林幽藹，弥望遠覽，滉瀁夷泰，表里山河，出入襟帶，若乃潛流旁註，飛渠脈散，芙蓉映渚，靈芝蔽岸，於是逍遙靈沼，遊豫華林，弯弓撫彈，娱志荡心，括不空縱，纶不苟沉，遊鱗双躍，落羽相尋，膳夫進俎，虞人獻鮮，春醴九醞，嘉豆百笾，隨波溯流，乍往乍旋。","sortOrder":160},
  {"id":"s_work_nvlt_63_161","chapterId":"ch_work_nvlt_63","text":"【銘】後漢李尤高安馆銘曰：巍巍高安，明聖是修，嶕峣麗馆，窗闼列周，長除臨起，櫺槛相承，聖朝明察，同保休徵。","sortOrder":161},
  {"id":"s_work_nvlt_63_162","chapterId":"ch_work_nvlt_63","text":"又平樂馆銘曰：乃興平樂，弘敞麗光，層樓通閣，禁闼洞房，棼梁照曜，朱華飾璫，騁武舒秘，以示幽荒，加榮普覆，然後來王。","sortOrder":162},
  {"id":"s_work_nvlt_63_163","chapterId":"ch_work_nvlt_63","text":"《藝文類聚》　唐·欧陽詢","sortOrder":163},
  {"id":"s_work_nvlt_64_1","chapterId":"ch_work_nvlt_64","text":"卷六十四居處部四","sortOrder":1},
  {"id":"s_work_nvlt_64_2","chapterId":"ch_work_nvlt_64","text":"○宅舍庭壇室斋庐道路","sortOrder":2},
  {"id":"s_work_nvlt_64_3","chapterId":"ch_work_nvlt_64","text":"◇宅舍","sortOrder":3},
  {"id":"s_work_nvlt_64_4","chapterId":"ch_work_nvlt_64","text":"《晏子》曰：景公使更晏子之宅，曰：子之宅近市，湫隘嚣尘不可居，請更子宅，曰：臣之先臣，居此宅焉，臣不足以代之。","sortOrder":4},
  {"id":"s_work_nvlt_64_5","chapterId":"ch_work_nvlt_64","text":"《漢書》曰：萧何買田宅，必居窮僻處，不治垣舍，曰：令後世賢，師吾俭，不賢，無為势家所奪。","sortOrder":5},
  {"id":"s_work_nvlt_64_6","chapterId":"ch_work_nvlt_64","text":"又曰：魯共王坏孔子舊宅，以廣宮室，聞鍾磬琴瑟之聲，遂不敢坏，复於其壁中得古經傳。","sortOrder":6},
  {"id":"s_work_nvlt_64_7","chapterId":"ch_work_nvlt_64","text":"《續漢書》曰：吳漢嘗出征，妻子在後買田業，漢還，讓之曰：軍師在外，吏士不足，何多買田宅乎，遂盡分以與崑弟外家。","sortOrder":7},
  {"id":"s_work_nvlt_64_8","chapterId":"ch_work_nvlt_64","text":"裴楷別傳曰：楷營新宅，基宇甚麗，當移住，與兄共遊行，床帳俨然，櫺軒疏朗，兄心甚原之，而口不言，楷心知其意，便使兄住。","sortOrder":8},
  {"id":"s_work_nvlt_64_9","chapterId":"ch_work_nvlt_64","text":"王隱《晉書》曰：魏舒少孤為外家甯氏所養，甯起宅，相者雲，當出貴外生，舒曰：當為外家成此宅相。","sortOrder":9},
  {"id":"s_work_nvlt_64_10","chapterId":"ch_work_nvlt_64","text":"《漢舊儀》曰：高皇帝家在丰中陽里，為沛泗上亭長，及為天子，立沛廟，祠丰故宅。","sortOrder":10},
  {"id":"s_work_nvlt_64_11","chapterId":"ch_work_nvlt_64","text":"《風俗通》曰：宅不西益，俗說西者為上，上益宅者，妨家長也，原其所以西益者，《禮記》曰：南向北向，西方為上，《爾雅》曰：西南隅謂之奧，尊長之處也，不西益者，難動搖之爾，審西益有害，增廣三面，豈能獨吉乎。","sortOrder":11},
  {"id":"s_work_nvlt_64_12","chapterId":"ch_work_nvlt_64","text":"《三辅决錄》曰：郭詳為太尉長史，起大宅，在高陵城西，世稱曰長史宅。","sortOrder":12},
  {"id":"s_work_nvlt_64_13","chapterId":"ch_work_nvlt_64","text":"《吳志》曰：周瑜與孫策同年，相友善，瑜推道南大宅以舍策，升堂拜母，有無通共。","sortOrder":13},
  {"id":"s_work_nvlt_64_14","chapterId":"ch_work_nvlt_64","text":"又曰：陳表家财，盡於養士，死之日，妻子露立，太子登為起居宅。","sortOrder":14},
  {"id":"s_work_nvlt_64_15","chapterId":"ch_work_nvlt_64","text":"娄承先傳曰：娄玄到廣州，遂徘徊踯躅於仲翔宅故處，哀咽凄怆，不能自勝。","sortOrder":15},
  {"id":"s_work_nvlt_64_16","chapterId":"ch_work_nvlt_64","text":"《搜神記》曰：魏郡張本富，忽衰死财散，賣宅與程應，應舉家疾病，賣與何文，文先獨持大刀，暮入北堂梁上，一更中，有一人長丈餘，高冠赤帻，呼曰：細腰，細腰應诺，何以有人氣，答無，便去，文因呼細腰，問向赤衣冠是誰，答曰金也，在西壁下，問君是誰，答雲，我杵也，今在竈下，文掘得金三百斤，燒去杵，由此大富，宅遂清寧。","sortOrder":16},
  {"id":"s_work_nvlt_64_17","chapterId":"ch_work_nvlt_64","text":"□□［《太平御覽》一百八十作抱朴。］子曰：葛庐有大功，受爵，立宅舍於博望里，於今基兆石蛇楚在焉。","sortOrder":17},
  {"id":"s_work_nvlt_64_18","chapterId":"ch_work_nvlt_64","text":"又曰：臨汜［《太平御覽》九百八十五作沅。］縣有廖氏，世老寿，後移，子孫辄殘折，他人居其故宅，复累世寿，乃知是宅所為，不知其何故，疑井水赤，乃掘井左右，得古人埋丹沙數十斛，丹汁入井，是以飲水而得寿。","sortOrder":18},
  {"id":"s_work_nvlt_64_19","chapterId":"ch_work_nvlt_64","text":"《襄陽記》曰：李衡每欲治家，妻辄不聽，後密遣客十人，於武陵龍陽洲上作宅。种橘千树，臨死，敕兒曰：汝母每惡吾治家，故窮如是，吾州里有千頭木奴，不用汝衣食，歲上一匹絹，亦當足用爾，亡後二十餘日，兒白母，母曰：此當种柑橘也，汝家失十戶客七八年，必汝父遣為宅，晉鹹康中，其宅上枯树猶存。","sortOrder":19},
  {"id":"s_work_nvlt_64_20","chapterId":"ch_work_nvlt_64","text":"范汪《荆州記》曰：宛有三女樓，作子胥宅。","sortOrder":20},
  {"id":"s_work_nvlt_64_21","chapterId":"ch_work_nvlt_64","text":"又曰：義陽六縣安昌里，有光武宅，枕白水陂，所謂龍飛白水也。","sortOrder":21},
  {"id":"s_work_nvlt_64_22","chapterId":"ch_work_nvlt_64","text":"庾仲雍《荆州記》曰：秭歸縣有屈原宅伍胥廟，捣衣石猶存。","sortOrder":22},
  {"id":"s_work_nvlt_64_23","chapterId":"ch_work_nvlt_64","text":"《賴乡記》曰：老子祠在賴乡曲仁里，谯城西出五十里，老子平生時，教化學仙故處也，漢桓帝修建屋宇，為老子廟，廟北二里，李夫人祠，是老子舊生宅也。","sortOrder":23},
  {"id":"s_work_nvlt_64_24","chapterId":"ch_work_nvlt_64","text":"劉楨京口記曰：糖頹山，山周回二里餘，山南隅，隔路得郄鑒故宅，五十餘畝。","sortOrder":24},
  {"id":"s_work_nvlt_64_25","chapterId":"ch_work_nvlt_64","text":"戴延之《西京記》曰：東陽門外道北，吳蜀二主第宅，去城二里，墟墓猶存。","sortOrder":25},
  {"id":"s_work_nvlt_64_26","chapterId":"ch_work_nvlt_64","text":"又曰：潼關北去蒲坂城六十里，中有舜廟，城外有宅井，及二妃壇，南去城二十里，有山，舜所耕山，上亦有山。","sortOrder":26},
  {"id":"s_work_nvlt_64_27","chapterId":"ch_work_nvlt_64","text":"《述征記》曰：丰圻，丰水西九十里，有漢高祖宅。","sortOrder":27},
  {"id":"s_work_nvlt_64_28","chapterId":"ch_work_nvlt_64","text":"又曰：山陽縣城東北二十里，魏中散大夫嵇康園宅，今悉為田墟，而父老猶謂嵇公竹林地，以時有遺竹也。","sortOrder":28},
  {"id":"s_work_nvlt_64_29","chapterId":"ch_work_nvlt_64","text":"盛弘之《荆州記》曰：新野郡西七里，有梅溪，源出紫山，南流註淯，故老傳溪西有百里奚宅。","sortOrder":29},
  {"id":"s_work_nvlt_64_30","chapterId":"ch_work_nvlt_64","text":"【詩】齊竟陵王萧子良行宅詩曰：餘禀性端疏，屬愛閒外，往歲羁役浙東，備歷江山之羨，名都勝境，極盡登臨，山原石道，步步新情，回池絕涧，往往舊識，以吟以詠，聊用述心，訪宇北山阿，卜居西野外，幼賞悅禽魚，早性羨蓬艾。","sortOrder":30},
  {"id":"s_work_nvlt_64_31","chapterId":"ch_work_nvlt_64","text":"陳江總歲暮還宅詩曰：悒然想泉石，驅駕出城台，玩竹春前筍，驚花雪後梅，青山殊可對，黃卷复時开，長繩豈系日，濁酒傾一杯。","sortOrder":31},
  {"id":"s_work_nvlt_64_32","chapterId":"ch_work_nvlt_64","text":"又南還尋草市宅詩曰：紅顏辭巩洛，白首入轘轅，乘春還故里，徐步采芳荪，径毀悲嵇仲，林殘憶巨原，見桐猶識井，看柳尚知門，花落空難遍，湋啼靜易喧，無人訪語默，何處叙寒溫，百年獨如此，傷心豈复論。","sortOrder":32},
  {"id":"s_work_nvlt_64_33","chapterId":"ch_work_nvlt_64","text":"【賦】魏陳王曹植閒居賦曰：何吾人而介特，去朋匹而無儔，出靡時以娱志，入無樂以銷忧，何歲月之若骛，复民生之無常，感陽春之發節，聊輕駕而遠翔，登高丘以延企，時薄暮而起予，仰歸雲以載奔，過蘭蕙之長圃，冀芬芳之可服，結春蘅以延佇，入虛廓之閒馆，步生風之廣庑，踐密邇之脩除，即蔽景之玄宇，翡鳥翔於南枝，玄鶴鳴於北野，青魚躍於東沼，白鳥戲於西渚，遂乃背通穀，對绿波，藉文茵，翳春華，丹轂更馳，羽騎相過。","sortOrder":33},
  {"id":"s_work_nvlt_64_34","chapterId":"ch_work_nvlt_64","text":"晉潘嶽閒居賦曰：嶽讀汲黯傳，至司馬安四至九卿，而良史書之，題以巧宦之目，未曾不慨然废書而叹曰：嗟乎，巧誠有之，拙亦宜然，於是覽止足之分，庶浮雲之志，池沼足以漁釣，舂稅足以代耕，灌園鬻蔬，供朝夕之膳，牧羊酤酪，俟伏臈之費，此亦拙者之為政也，乃作閒居之賦，於是退而閒居洛水之涘，身齊逸民，名缀下士，背京溯伊，面郊後市，浮梁黝以径度，靈台桀而高峙，窥天文之秘奧，究人事之終始，爰定我居，筑室穿池，長楊映沼，芳枳树篱，遊鱗瀺灂，菡萏敷披，竹木蓊鬱，靈果參差，張公大穀之梨，梁侯乌椑之柿，周文弱枝之棗，房陵朱仲之李，靡不畢植，三桃表櫻胡之別，二柰曜丹白之色，石榴蒲萄之珍，磊落漫衍乎其侧，梅杏鬱棣之屬，繁榮藻麗之飾，華實照烂，言所，不能極也，菜則葱若韭蒜芋，青筍紫薑，蘘荷依荫，時藿向陽，绿葵含露，白薤負霜，柳垂陰，車結軌，陆摘紫房，水掛赪鯉，或宴於林，或禊於汜。","sortOrder":34},
  {"id":"s_work_nvlt_64_35","chapterId":"ch_work_nvlt_64","text":"晉庾闡閒居賦曰：於是宅鄰京郊，宇接華郭，聿來忘懷，茲焉是讬，鳥栖庭林，燕巢子幕，既乃青陽結荫，木瑾开榮，森條霜重，绿葉雲傾，陰興則暑退，風來則氣清，前臨塘中，眇目長洲，晨渠吐溜，歸潮夕流，顧有崇台高觀，凌虛遠遊，若夫左瞻天宮，右盻西嶽，甍飛彤素，嶺敷翠绿，朝霞時清，沧浪靡濁，黃綺絜其雲栖，漁父欣其濯足，至於體散玄風，神陶妙象，靜因虛來，動率化往，萧然忘覽，豁爾遺想，榮悴靡期，孰测幽朗，故細無形骸之狹，巨非天地之廣，音興於萬韻，理絕乎一响。","sortOrder":35},
  {"id":"s_work_nvlt_64_36","chapterId":"ch_work_nvlt_64","text":"晉束晳近遊賦曰：世有逸民，在乎田畴，宅弥五畝，志狹九州，安窮賦於下里，寞玄淡而無求，乘荜辂之偃蹇，駕蘭单之疲牛，連搥索以為鞅，結斷梗而作鞦，攀荜門而高蹈，朅徘徊而近遊，井則兩家共一，園必去舍百步，貫雞〈穀中\"禾改卵\"〉於歲首，收縘缡於牣互，其男女服飾，衣裳之製，名號诡異隨迭，設系襦以御冬。胁汗衫以當熱，帽引四角之縫，裙為素條之殺，書兒啼於客堂，設杜門以避吏，婦皆卿夫，子呼父字，及至三農間隙，遘結婚姻，老公戴合歡之帽，少年著蕞角之巾。","sortOrder":36},
  {"id":"s_work_nvlt_64_37","chapterId":"ch_work_nvlt_64","text":"梁沈約郊居賦曰：惟至人之非己，固物我而自忘，自中智以下愚，鹹得性以為場，伊吾人之褊志，無經世之大方，思依林而羽戢，原讬水而鱗藏，值龍顏之鬱起，乃凭風而矯翼，指皇邑而南轅，駕脩衢以騁力，餘平生而耿介，實有心於獨往，思幽人而軫念，望東皋而長想，本忘情於徇物，徒羁绁於人壤，應屬叹於牵幽，陆興言於世網，爾乃傍窮野，指荒郊，編霜菼，葺寒茅，構栖噪之所集，筑町甿之所交，因犯簷而刊树，由妨基而翦巢，織宿楚而成門，藉外靡而為戶，既取陰於庭樾。又因篱於芳杜，草則蘋萍芡芰，菁藻蒹菰，石衣海發，黃荇绿蒲，動紅荷於輕浪，覆碧葉於澄湖，其陆卉則紫{艹龟}绿葹，天菁山韭，雁齒鹿舌，牛唇彘肩，若乃園宅殊製，田圃異區，李衡則橘林千树，石崇則雜果萬株，併豪情之所侈，非俭志之所娱，欲令紛披蓊鬱，吐绿攒朱，开丹房以四照，舒翠葉而九衢，其林鳥則翻泊頡颃，遺音下上，楚雀多名，流湋雜响，或班尾而綺翼，或绿衿而絳顙，好葉隱而枝藏，乍間關而來往，其水禽則大鸿小雁，天駒泽虞，秋鹥寒鹥，修鹢短凫，翅碎流而起沫，翼鼓浪而成珠，其魚則赤鯉青鲂，纖鯈巨鳠，碧鱗朱尾，脩顱偃嵒，小則戲渚成文，大則喷流楊白，惟鍾巖之隱鬱，表皇都而作峻，蓋望秩之所宗，含風雲而起润，孤隥橫插，洞穴斜經，千丈萬仞，三袭九成，亘繞州邑，款跨郊坰，素煙晚帶，白霧晨萦，近循則一巖異色，遠望則百嶺俱青，時言歸於陋宇，聊暇日以翱翔，獸依庭而莫駭，魚何沼而不綱，晚树开花，初英落蕊，異林而分丹素，因風而雜紅紫，紫莲夜發，紅荷晓舒，輕風微動，芬芳袭餘，冰懸埳而帶坻，雪萦松而被野，鸭屯飛而不散，雁高翔而欲下，傷餘情之頹暮，忧與愁其相溢，悲異軫而同歸，歡殊方而併失，時复讬情魚鳥，歸閒蓬荜，旁闕吳娃，前無趙瑟，唯以天地之恩不報，書事之官不述，徒重於高門之地，不載於良史之筆，長太息以何言，羞愧心之非一。","sortOrder":37},
  {"id":"s_work_nvlt_64_38","chapterId":"ch_work_nvlt_64","text":"【銘】晉習凿齒諸葛武侯宅銘曰：達人有作，振此頹風，彫薄蔚采，鴟阑惟丰，義范蒼生，道格時雄，自昔爰止，於焉盤桓，躬耕西畝，永嘯東峦，跡逸中林，神凝巖端，罔窥其奧，誰测斯歡，堂堂伟匠，婉翮扬朝，傾巖搜寶，高羅九霄，慶雲集矣，鸞駕亦招。","sortOrder":38},
  {"id":"s_work_nvlt_64_39","chapterId":"ch_work_nvlt_64","text":"【啟】梁元帝謝敕賜第啟曰：竊以漢賜五倫，寔雲清吏，魏寵衛臻，用旌庸直，未如靈光輪奐，睢陽爽垲，北連城闕，有似甄侯之舍，東望市鄽，榮深豫章之圃，昔狼望未平，冠軍辭宅，馬池猶隔，雍丘讓邸，臣慚霍曹遠志，但識君命無违，再思庸陋，九殒非答。","sortOrder":39},
  {"id":"s_work_nvlt_64_40","chapterId":"ch_work_nvlt_64","text":"梁劉孝儀為王儀同謝宅啟曰：昔晏婴湫隘，齊景營其爽垲，孫歷無家，晉武為之筑馆，或功高千載，德重一時，故蒙考室之榮，以降葺宇之泽，併辭而處，傳芳前載，臣才愧昔人，恩同往哲，豈宜妄荷，重增疵吝，但匈奴未滅，遽當輪奐之美，環堵為室，遂得歌哭於斯。","sortOrder":40},
  {"id":"s_work_nvlt_64_41","chapterId":"ch_work_nvlt_64","text":"又為武陵王謝賜第啟曰：竊以南望朱鳥，北距蒼龍，右帶御溝，左回青路，畢晏婴之湫隘，同潘嶽之閒居，臣幼自宮掖，長遊城府，雖輪奐之美多門，而馆第之私未暇，今輕舟將反，高門遽錫，遂葺宇筑室，百堵皆興，雲屋連甍，一朝弘敞。","sortOrder":41},
  {"id":"s_work_nvlt_64_42","chapterId":"ch_work_nvlt_64","text":"梁庾肩吾謝東宮賜宅啟曰：肩吾居異道南，才非巷北，流寓建春之外，寄息靈台之下，豈望地無湫隘，里號乘軒，巷轉幡旗，門容幰蓋，况乃交垂五柳，若元亮之居，夹石双槐，似安仁之縣，却瞻鍾阜，前枕洛桥，池通西舍之流，窗映東鄰之棗，來歸高里，翻成侍封之門，夜坐書台，非复通燈之壁，才下應王，禮加溫阮，官成名立，無事非恩。","sortOrder":42},
  {"id":"s_work_nvlt_64_43","chapterId":"ch_work_nvlt_64","text":"【表】晉陆雲聞起西園第宜遵節俭之製表曰：臣聞有國者，不患宮室之不崇，患在令名之不立，是以賢人之在富貴，莫不卑身節欲，損己挹情，用能保其國家，令聞百世，歷觀古今，以約失之者實寡，以奢失之者蓋多，世祖武皇帝，富有四海，貴為天子，居無離宮之馆，身御家人之服，先帝豈欲以此道止於治身而已者哉，固將必欲遺訓百世，貽燕子孫，此固殿下所宜祗奉也。","sortOrder":43},
  {"id":"s_work_nvlt_64_44","chapterId":"ch_work_nvlt_64","text":"【議】晉潘嶽上客舍議曰：謹按客舍逆旅之設，其所由來遠也，行者賴以頓止，居者薄收其直，交易貿遷，各得其所，因民成利，惠加百姓，語曰：許由辭帝尧之命，而舍於逆旅，外傳曰：晉陽處父，遇甯戚於逆旅，魏武帝亦以為宜，其詩曰：逆旅整設，以通商贾，然則自唐到於今，未有不得客舍之法，唯商鞅有之，此固非聖世之所言也，方今四海會同，九服納貢，八方翼翼，公私滿路，近畿入輳，客舍亦稠，刍秣成行，器用取給。又諸劫盜，皆起於迥絕，而止乎人眾，十里萧條，則奸宄生心，連陌接馆，則寇情震慑，且聞聲有救，［原訛赦，據冯校本改。］已發有追，不救有罪，不追有戮，禁暴捕亡，恒有司存，凡此皆客舍之益，道路之要，奸吏所植也，率歷代之舊俗，獲行留之歡心，使客舍洒扫以待，征旅擇家而息，豈非眾庶顒顒之望。","sortOrder":44},
  {"id":"s_work_nvlt_64_46","chapterId":"ch_work_nvlt_64","text":"《左傳》曰：初楚恭王無冢適，有寵子五人，無適立焉，既乃與巴姬密埋璧於太室之庭，使五人斋而入拜，平王弱，抱而入，再拜皆厭紐。","sortOrder":46},
  {"id":"s_work_nvlt_64_47","chapterId":"ch_work_nvlt_64","text":"羅含別傳曰：含致仕還家，庭中忽自生蘭，此德行幽感之應。","sortOrder":47},
  {"id":"s_work_nvlt_64_48","chapterId":"ch_work_nvlt_64","text":"《語林》曰：謝太傅問諸子侄曰：子弟何豫人事，正欲使其佳，［原訛往，據冯校本改。］諸人莫有言，車騎答曰：譬如芝蘭玉树，欲使其生庭階也。","sortOrder":48},
  {"id":"s_work_nvlt_64_49","chapterId":"ch_work_nvlt_64","text":"【賦】陳沈蜅幽庭賦曰：矧幽庭之閒趣，具春物之芳華，轉洞房而引景，偃飛閣而藏霞，筑山川於戶牖，帶林苑於東家，草纖纖而垂绿，树搔搔而落花，於是秦人清歌，趙女鼓筑，嗟光景之遲暮，詠群飛之栖宿，顧留情於君子，豈含姿於娇淑，於是起而長謠曰：故年花落今复新，新年一故成故人，那得長繩系落日，年年月月但如春。","sortOrder":49},
  {"id":"s_work_nvlt_64_51","chapterId":"ch_work_nvlt_64","text":"《管子》曰：桓公即壇而立，甯戚鮑叔隰朋賓須無，皆差肩而立。","sortOrder":51},
  {"id":"s_work_nvlt_64_52","chapterId":"ch_work_nvlt_64","text":"《莊子》曰：孔子遊乎淄帷之林，休坐於杏壇之上，弟子讀書，孔子絃歌鼓琴，奏曲未終，有漁父者，下舡而來，左手據膝，右手持颐以聽，曲終而招子貢子路二人俱對，客指孔子曰：彼何為者，子路曰：魯之君子也。","sortOrder":52},
  {"id":"s_work_nvlt_64_53","chapterId":"ch_work_nvlt_64","text":"《新序》曰：秦欲伐楚，使者往觀楚王之寶器，楚王聞之，召昭奚恤問焉，恤對曰：此觀吾國之得失而圖之，寶器［《太平御覽》六百二十一器下有在字。］於賢臣，夫珠玉玩好之物，非國之重寶也，遂使恤發精兵三百人，陳於西門之內，為東面之壇一，為西面之壇一，秦使者至，恤曰：貴客也，請就上位。","sortOrder":53},
  {"id":"s_work_nvlt_64_54","chapterId":"ch_work_nvlt_64","text":"徐靈期南嶽記曰：南嶽山上有飛壇，懸水激石，飛湍百仞，即孫溫伯所丧身處也。又有曲水壇，水行石上，成溝渎，如世人臨河壇也，三月三日，時來逍遙，《梁州記》曰：沔陽城，先沔陽縣所治也，在漢水南，舊萧何所筑也，劉備為漢王，權住此城，盟於城下，今門外有盟壇猶存。","sortOrder":54},
  {"id":"s_work_nvlt_64_55","chapterId":"ch_work_nvlt_64","text":"【銘】周庾信尧登壇銘曰：登壇洛汭，沉玉河湄，丹圖馭馬，練甲乘龟，榮光上幕，休氣連帷，雖存尧讓，終見文思。","sortOrder":55},
  {"id":"s_work_nvlt_64_57","chapterId":"ch_work_nvlt_64","text":"《毛詩》曰：斯幹，宣王考室也，筑室百堵，西南其戶。","sortOrder":57},
  {"id":"s_work_nvlt_64_58","chapterId":"ch_work_nvlt_64","text":"《老子》曰：凿戶牖以為室，當其無，有室之用。","sortOrder":58},
  {"id":"s_work_nvlt_64_59","chapterId":"ch_work_nvlt_64","text":"楚辭九歌曰：糜何食兮庭中，蛟，何為兮水裔，朝馳餘馬兮江皋，夕濟兮西澨，聞佳人兮召餘，將騰駕兮皆逝，筑室兮水中，葺之兮以荷蓋。","sortOrder":59},
  {"id":"s_work_nvlt_64_60","chapterId":"ch_work_nvlt_64","text":"《管子》曰：尧有衢室之問者，下聽於民也。","sortOrder":60},
  {"id":"s_work_nvlt_64_61","chapterId":"ch_work_nvlt_64","text":"《晏子》曰：景公謂《晏子》曰：寡人欲朝夕相見，為夫子筑室於閨內，可乎，對曰：臣聞之，隱而顯，近而結，唯至賢耳，如臣者，飾其容止以待命，猶恐罪戾也，今君近之，是遠之也。","sortOrder":61},
  {"id":"s_work_nvlt_64_62","chapterId":"ch_work_nvlt_64","text":"又曰：景公問《晏子》曰：吾欲服聖人之服，居聖人之室，如此則諸侯其至乎，對曰：法其節俭則可，法其服室，無益。","sortOrder":62},
  {"id":"s_work_nvlt_64_63","chapterId":"ch_work_nvlt_64","text":"《楚辭》曰：凿山楹而為室，下披衣於水渚，霧濛濛其晨降兮，雲依斐而成宇。","sortOrder":63},
  {"id":"s_work_nvlt_64_64","chapterId":"ch_work_nvlt_64","text":"又曰：網戶朱缀刻方連，冬有突夏夏室寒。","sortOrder":64},
  {"id":"s_work_nvlt_64_65","chapterId":"ch_work_nvlt_64","text":"《尚書大傳》曰：子夏讀書畢，見夫子，夫子問焉，子何為於書，對曰：書之論事，昭昭若日月之明，離離若參辰之错行，上有尧舜之道，下有三王之義，商所受於夫子者，志之不敢忘也，雖退而窮思河濟之間，深山之中，壤室編蓬為戶，於中彈琴，詠先王之道，則可發憤慷慨矣。","sortOrder":65},
  {"id":"s_work_nvlt_64_66","chapterId":"ch_work_nvlt_64","text":"《神異經》曰：西北荒有石室，有二十人同居，齊寿千二百歲。","sortOrder":66},
  {"id":"s_work_nvlt_64_67","chapterId":"ch_work_nvlt_64","text":"《十洲記》曰：崑崙山上有琼華之室。","sortOrder":67},
  {"id":"s_work_nvlt_64_68","chapterId":"ch_work_nvlt_64","text":"《淮南子》曰：西方有金室。","sortOrder":68},
  {"id":"s_work_nvlt_64_69","chapterId":"ch_work_nvlt_64","text":"《列仙傳》曰：彭祖，殷大夫也，歷夏至商末，號七百歲，歷陽有彭祖仙室。","sortOrder":69},
  {"id":"s_work_nvlt_64_70","chapterId":"ch_work_nvlt_64","text":"《漢書》曰：文帝徵贾誼入見，上方受釐，坐宣室，因感鬼神事，與誼言之。","sortOrder":70},
  {"id":"s_work_nvlt_64_71","chapterId":"ch_work_nvlt_64","text":"《三辅黃圖》曰：明堂有十二室，法十二月。","sortOrder":71},
  {"id":"s_work_nvlt_64_72","chapterId":"ch_work_nvlt_64","text":"謝承《後漢書》曰：陳蕃家貧，不好扫室，客怪之者，或曰：可一扫乎，蕃曰：大丈夫當為國扫除天下，豈徒室中乎。","sortOrder":72},
  {"id":"s_work_nvlt_64_73","chapterId":"ch_work_nvlt_64","text":"楊龍驤洛陽記曰：顯陽殿北有避雷室，西有御龍室。","sortOrder":73},
  {"id":"s_work_nvlt_64_74","chapterId":"ch_work_nvlt_64","text":"雷次宗豫章記曰：望秦縣有一石室，入室十餘里，有水廣數十步，清淺，遊者伐竹為筏以過水，幽邃無極，莫能究其源，出好鍾乳。","sortOrder":74},
  {"id":"s_work_nvlt_64_75","chapterId":"ch_work_nvlt_64","text":"盛弘之《荆州記》曰：始興機山東，有兩巖相向，如鴟尾，石室數十所，經過時聞有金石絲竹之聲。","sortOrder":75},
  {"id":"s_work_nvlt_64_76","chapterId":"ch_work_nvlt_64","text":"嵩高山記曰：山下巖中有石室，中有自然經書，自然飲食。","sortOrder":76},
  {"id":"s_work_nvlt_64_77","chapterId":"ch_work_nvlt_64","text":"漢宮殿名曰：神明台，武帝造，高五丈，上有九室，今人謂之九天台，武帝求神仙，恒置九天道士百人。","sortOrder":77},
  {"id":"s_work_nvlt_64_78","chapterId":"ch_work_nvlt_64","text":"洛陽宮殿名曰：洛陽有望舒涼室含章鞠室靈芝鞠室清暑涼室","sortOrder":78},
  {"id":"s_work_nvlt_64_79","chapterId":"ch_work_nvlt_64","text":"【詩】宋吳邁遠遊庐山觀道士石室詩曰：蒙葺眾山里，往來行跡稀，尋嶺達仙居，道士披雲歸，似著周時冠，状披漢時衣，安知世代積，服古人不衰，得我宿昔情，知我道無為。","sortOrder":79},
  {"id":"s_work_nvlt_64_80","chapterId":"ch_work_nvlt_64","text":"齊王融移席琴室應司徒教詩曰：雪崖似留月，萝径若披雲，潺湲石溜寫，綿峦山雨聞，梁任豫夏潦省宅詩曰：風棹出天街，星言指沈室，頓楫俄毀垣，惻然悼窮陌，春為發大道，夏為溆潮折，貴者陋懷居，鄙人安朝夕，生長數十載，幸祐見衰白，堂遺孤孩音，庭餘笄龀跡，入似聚族慰，出為里仁惜。","sortOrder":80},
  {"id":"s_work_nvlt_64_81","chapterId":"ch_work_nvlt_64","text":"【賦】晉潘嶽狹室賦曰：歷甲第以遊觀，旋陋巷而言歸，伊餘馆之褊狹，良窮弊而極微，閣了戾以互掩，門崎嶇而外扉，室侧戶以攒楹，簷接秬而交榱，當祝融之御節，炽朱明之隆暑，沸體惄其如鑠，珠汗揮其如雨，若乃重陰晦冥，天威震曜，潢潦沸騰，丛溜奔激，臼竈為之沉溺，器用為之浮漂，彼處貧而不怨，嗟生民之攸難，匪廣厦之足榮，有切［原訛功，據冯校本改。］身之近患，青陽萌而畏暑，白藏兆而懼寒，獨味道而不悶，喟然向其時叹。","sortOrder":81},
  {"id":"s_work_nvlt_64_82","chapterId":"ch_work_nvlt_64","text":"晉庾闡狹室賦曰：居不必阨，食不求箪，豈獨蓬蓼可永，而隆棟招患，奚必膏粱非美，而飲疏以餐，醪俎可以充性，不極欲以析龍肝，清室可以遊暑，不冽泳而興夏寒，於時融火炎炎，鶉精共耀，南羲炽暑，夕陽傍照，爾乃登通扉，辟櫺幌，絺幕褰，閒堂敞，微飆凌閨而直激，清氣乘虛以曲荡，溫房悄凄以興涼，軒槛寥豁以外朗。","sortOrder":82},
  {"id":"s_work_nvlt_64_84","chapterId":"ch_work_nvlt_64","text":"王孚安成記曰：太和中，陳郡殷府君，引水入城穿池，殷仲堪又於池北立小屋讀書，百姓於今呼曰讀書斋。","sortOrder":84},
  {"id":"s_work_nvlt_64_85","chapterId":"ch_work_nvlt_64","text":"【詩】晉湛方生後斋詩曰：解纓复褐，辭朝歸藪，門不容軒，宅不盈畝，茂草籠庭，滋蘭拂牖，撫我子侄，携我親友，茹彼園蔬，飲此春酒，开櫺攸瞻，坐對川阜，心焉孰讬，讬心非有，素構易抱，玄根難朽，即之匪遠，可以長久。","sortOrder":85},
  {"id":"s_work_nvlt_64_86","chapterId":"ch_work_nvlt_64","text":"梁簡文帝山斋詩曰：玲瓏繞竹涧，間關通槿蕃，缺岸新成浦，危石久為門，北榮下飛桂，南柯吟夜猿，暮流澄錦碛，晨冰照采鸞。","sortOrder":86},
  {"id":"s_work_nvlt_64_87","chapterId":"ch_work_nvlt_64","text":"梁庾肩吾和竹斋詩曰：百栱橫筇節，千栌跨篻竿，回龍仍作柱，置笛且成栾，向嶺分花径，隨階轉藥欄，蜂歸怜蜜熟，燕入重巢乾，欲仰天庭掞，終知學步艱，陳徐陵奉和簡文帝山斋詩曰：架嶺承金闕，飛桥對石梁，竹密山斋冷，荷开水殿香，山花臨舞席，水影照歌床。","sortOrder":87},
  {"id":"s_work_nvlt_64_88","chapterId":"ch_work_nvlt_64","text":"【賦】宋謝靈運山居賦曰：上古巢居穴處曰巖栖，居山曰山居，在林野曰丘園，在郊郭曰城傍，四者不同，可以理推，昔仲長原言，流水高山，應叟作書，邙阜洛川，势有偏侧，地闕周員，至若鳳丛二台，雲夢青丘，漳渠淇園，橘林長洲，雖千乘之珍苑，孰嘉遁之所遊，覽明達之撫運，乘機感而理默，悼三闾之浮江，矜望諸之去國，仰前哲之遺訓，俯性情之所便，奉微軀以宴息，保息事以乘閒，爰初經略，杖策孤征，入涧涉水，登嶺山行，紆顶不息，窮泉不停，櫛風沐雨，犯露乘星，研其淺思，罄其短規，非龟非筮，擇良選奇，剪榛开径，尋石觅崖，四山周回，双流逶迤，陵名山而屢止，過巖室而披情，雖未偕於至道，且緬絕於世纓，若乃南北兩居，水通陆阻，觀風瞻雲，方知厥所，九泉別涧，五穀異巘，抗北顶以葺馆，瞰南峰以啟軒，羅層崖於戶里，鏡清澜於窗前，修竹葳蕤以翳薈，灌木森丛以蒙茂，萝茑蔓延以攀援，香花芬薰而媚秀，日月投光於柯間，風露披清於嵔岫，夏涼寒燠，隨時取適，此焉卜寢，玩水弄石，及其二川合流，異源同口，赴隘入险，俱會山首，瀨排沙以積岸，島倚渚以超阜，畦町劚藝，含蕊藉芳，绿葵春節以懷露，白薤感時而負霜，伊昔龆龀，寶愛斯文，援紙握管，會性通神，詩以言志，賦以敷陳，爰暨山栖，弥歷年祀，幸多暇日，自求諸己。","sortOrder":88},
  {"id":"s_work_nvlt_64_89","chapterId":"ch_work_nvlt_64","text":"【贊】宋顏延年新喻侯茅斋贊曰：輦草作壮，采茅昭俭，哲人素節，貴而能貶，羁結茨危，瞰臨涯隒。","sortOrder":89},
  {"id":"s_work_nvlt_64_90","chapterId":"ch_work_nvlt_64","text":"【銘】隋江總永陽王斋後山亭銘曰：丛台造日，淄馆連雲，錦牆列缋，繡地成文，吾王卓爾，逸趣不群，梅梁蕙閣，桂棟蘭枌，竹深蓋雨，石暗迎曛，激流疑疏，構峰似削，苔滑危磴，藤攀耸崿，树影搖窗，池光動幕，月澄遙溆，風清近壑，雪岸難銷，花園易落，高桐百尺，垂楊五株，开榮九畹，結秀三珠，山條紫的，水葉紅須，抽芳繞霤，接翠分衢，亭讙旅鶴，浦噪驚凫，前列牧馬，後招郇伯，諷誦楚詩，精微沛易，丛桂留賞，散金匪惜，不羨睢陽，還蚩碣石，馳聲終古，服義無斁。","sortOrder":90},
  {"id":"s_work_nvlt_64_92","chapterId":"ch_work_nvlt_64","text":"《周官》曰：凡國野之道，十里有庐，庐有飲食。","sortOrder":92},
  {"id":"s_work_nvlt_64_93","chapterId":"ch_work_nvlt_64","text":"《漢書》曰：武帝詔嚴助，居厭承明之庐。","sortOrder":93},
  {"id":"s_work_nvlt_64_94","chapterId":"ch_work_nvlt_64","text":"《東觀漢記》曰：耿純率宗族歸光武，時郡國多降邯鄲，純兄歸燒宗家庐舍，上以問純，純曰：恐宗人賓客，卒有不同，故焚燒庐舍，絕其反顧之望，上大笑。","sortOrder":94},
  {"id":"s_work_nvlt_64_95","chapterId":"ch_work_nvlt_64","text":"又曰：承宮少孤，年八歲，為人牧猪，乡里徐子明春秋，授諸生數百人，宮過其庐下，見諸生講，好之，因亡其猪而聽經，猪主怪其不還，行求索，見宮，欲笞之，門下生共禁，乃止，《魏志》曰：管寧聞公孫度令行於海外，遂至遼東，度虛馆以俟之，既往見度，乃庐於山下，時避難者多居郡南，而寧居北，示無遷志。","sortOrder":95},
  {"id":"s_work_nvlt_64_96","chapterId":"ch_work_nvlt_64","text":"皇甫謐《高士傳》曰：世莫知焦先所出，或言生漢末，無父母兄弟，見漢衰，乃不言，常結草為庐，冬夏袒露，垢汙如泥，後野火燒其庐，先因露寢，遭大雪，先袒臥不移，人以為死，就视如故。","sortOrder":96},
  {"id":"s_work_nvlt_64_97","chapterId":"ch_work_nvlt_64","text":"洛陽故宮名曰：侍中庐，在南宮中。","sortOrder":97},
  {"id":"s_work_nvlt_64_98","chapterId":"ch_work_nvlt_64","text":"【碑】後漢張超靈帝河間舊庐碑曰：赫赫在上，陶唐是承，繼德二祖，四宗是凭，上納鑒乎羲農，中結軌乎夏商，元首既明，股肱惟良，乃因舊宇，福德所基，修飾經構，農隙得時，树中天之双闕，崇冠山之華堂，通樓閒道，丹階紫房，金窗鬱律，玉璧內璫，青蒲充庖，朱草栖箱，川魚踴躍，雲鳥舞翔，煌煌大漢，含德乾綱，體效日月，验化陰陽，格於上下，震畅八荒，三光宣曜，四靈效祥，天其嘉享，丰年穰穰，騶虞奏樂，鹿鳴荐觴，二祝致告，福祿來將，永保萬國，南山無量。","sortOrder":98},
  {"id":"s_work_nvlt_64_99","chapterId":"ch_work_nvlt_64","text":"◇道路","sortOrder":99},
  {"id":"s_work_nvlt_64_100","chapterId":"ch_work_nvlt_64","text":"《楚辭》曰：心不怡之長久，忧與忧之相接，惟郢路之遼遠，江與夏之不可涉。","sortOrder":100},
  {"id":"s_work_nvlt_64_101","chapterId":"ch_work_nvlt_64","text":"《史記》曰：文帝行至灞陵，是時慎夫人從，上示慎夫人新丰曰：此走邯鄲道也。","sortOrder":101},
  {"id":"s_work_nvlt_64_102","chapterId":"ch_work_nvlt_64","text":"《三辅故事》曰：桂宮周迊十里，內有複道，橫北［原訛此，據冯校本改。］渡，西至神明台。","sortOrder":102},
  {"id":"s_work_nvlt_64_103","chapterId":"ch_work_nvlt_64","text":"《漢書》曰：惠帝為東朝長樂宮，作複道，方筑高帝廟南，叔孫通曰：陛下筑複道，高帝寢衣冠，月出遊高廟，子孫奈何宗廟道上行哉，惠帝懼，曰：急坏之，通曰：人主無過舉，今已作，百姓皆知矣，原陛下益廣宗廟，大孝本也，帝從之。","sortOrder":103},
  {"id":"s_work_nvlt_64_104","chapterId":"ch_work_nvlt_64","text":"又曰：元帝即位，成帝為太子，上嘗召太子，出龍樓門，不敢絕馳道，直至城門得絕，乃度，上遲之，問其故，以状對，上乃令太子得絕馳道。","sortOrder":104},
  {"id":"s_work_nvlt_64_105","chapterId":"ch_work_nvlt_64","text":"《東觀漢記》曰：逢萌被徵上道，迷不知東西，雲朝所徵我者，為聰明叡智，有益於政，方面不知，安能濟政，即駕而歸，《博物志》曰：文王以太公為灌壇令，期年，風不鳴條，文王夢一婦人甚麗，當道而哭，問其故，曰：我太山之女，嫁為西海婦，欲歸，灌壇令當道有德，吾不敢以乘風雨過。","sortOrder":105},
  {"id":"s_work_nvlt_64_106","chapterId":"ch_work_nvlt_64","text":"任豫《益州記》曰：江曲由［《太平御覽》一百九十五作江油，此有衍文。］左擔道，按圖在陰平縣北，於城都為西，［其道至险，自北來者，擔在左肩，不得度擔也。］邓艾束馬懸車之處。","sortOrder":106},
  {"id":"s_work_nvlt_64_107","chapterId":"ch_work_nvlt_64","text":"【碑】陳徐陵丹陽上庸路碑曰：臣聞在天成象，鹹池屬於五潢，在地成形，沧海環於四渎，國险者固其金湯，储蓄者因於轉漕，货财為禮，专俟會通，厥田為上，皆資渗漉，大矣哉，坎德之為用也，是以握圖之主，财以利民，御斗之君，因之顯教，上哉少昊，初命水官，逖矣高陽，爰重冥職，舜為太尉，於是九泽載疏，禹作司空，然後百川鹹导，开華山於高掌，凿靈沼於周原，莫匪神功，皆由聖德，我大梁之受天明命，勞己濟民，有道稱皇，無為曰帝，若夫雲雷草創，翦商黜夏之勋，鑄寶鼎於崑吾，安能紀勒，陳鳴鍾於丰嶽，豈議揄扬，斯固名言之所絕也，及乎膺斯寶運，大拯橫流，屈至道於汾陽，勞凝神於{艹狼}［本集作姑，疑此當作藐。］射，聖人作樂，箫韶備以九成，盡禮春官，總於三代，豈止金門桴竹，玉尺調鍾，公帶獻明堂之圖，匡衡建後土之議，若斯而已矣，天降丹鳥，既序孝經，河出應龍，乃弘周易，若夫固天將聖，垂意藝文，五色相宣，八音繁會，不移漏刻，才命口占，御紙風飛，天章海溢，皆紫庭黃竹之詞，晨露卿雲之藻，漢之兩帝，徒有詠歌，魏之三祖，空雲詩賦，以為彭老之教，終没愛河，儒墨之宗，方難火宅，豈如五時八會之殊文天上人中之妙典，雪山羅漢，爭造論門，鷲嶺名僧，俱傳經藏，香象之力，特所未勝，秋兔之毫，書而莫盡，忠信為寶，禳祈免於白駒，明德惟馨，山川舍於骍犢，至如月離金虎，泥染石午，［本集作牛。］薈蔚朝興，滂沱晚註，而清跸才動，纖羅不搖，高闬將臨，油雲自辟，陽乌馭日，寧懼武贲之弓，飛雨門［本集作弥。］天，無待期門之蓋，震維舉德，非曰尚年，若發居酆，猶莊在漢，涛如白馬，既礙廣陵之江，山曰金牛，用险梅湖之路，专州典郡，青凫赤馬之舡，皇子天孫，鳴鳳飛龍之乘，莫不欣斯利涉，玩此脩渠，乍擁楫而長歌，乃摐金而鳴籁，斯實曠世之奇功，無疆之鸿烈者也，銘曰：後王降德，於眾兆民，高文象緯，妙義幾神，業冠遷夏，功逾入秦，時惟大畜，世久同人，慧雨方霤，禪枝獨春，帝德惟厚，皇恩甚深，觀乎禹跡，見我尧心。","sortOrder":107},
  {"id":"s_work_nvlt_64_108","chapterId":"ch_work_nvlt_64","text":"《藝文類聚》　唐·欧陽詢","sortOrder":108},
  {"id":"s_work_nvlt_65_1","chapterId":"ch_work_nvlt_65","text":"卷六十五產業部上","sortOrder":1},
  {"id":"s_work_nvlt_65_2","chapterId":"ch_work_nvlt_65","text":"○農田園圃蠶織針市","sortOrder":2},
  {"id":"s_work_nvlt_65_4","chapterId":"ch_work_nvlt_65","text":"《管子》曰：先王者，為民興利除害，故天下之民歸之，所謂興利者，利農事也，所謂除害者，禁害農者也，《尸子》曰：有虞氏身有南畝，妻有桑田，神農併耕而王，所以勸耕也。","sortOrder":4},
  {"id":"s_work_nvlt_65_5","chapterId":"ch_work_nvlt_65","text":"《韓子》曰：歷山農者侵畔，舜往耕，期年讓畔。","sortOrder":5},
  {"id":"s_work_nvlt_65_6","chapterId":"ch_work_nvlt_65","text":"《史記》曰：弃為兒時，好种树麻菽，麻菽美，及為成人，遂好耕農，相地之宜，宜穀者耕稼穡之，民皆法則之。","sortOrder":6},
  {"id":"s_work_nvlt_65_7","chapterId":"ch_work_nvlt_65","text":"《漢書》曰：洪范八政，一曰食，二曰货，食謂農殖嘉穀，可食之物。","sortOrder":7},
  {"id":"s_work_nvlt_65_8","chapterId":"ch_work_nvlt_65","text":"又曰：楊季，官至庐江太守，漢元鼎間避仇，後溯江上，處岷山之陽，曰郫，有田一壥，有宅一區，世世以農桑為業。","sortOrder":8},
  {"id":"s_work_nvlt_65_9","chapterId":"ch_work_nvlt_65","text":"《東觀漢記》曰：樊重世善農稼，好货殖。","sortOrder":9},
  {"id":"s_work_nvlt_65_10","chapterId":"ch_work_nvlt_65","text":"【賦】晉束晳勸農賦曰：惟百里之置吏，各區別而異曹，考治民之賤職，美莫當乎勸農，专一里之權，擅百家之势，及至青幡，禁乎遊惰，田賦度乎頃畝，與奪在己，良薄决口，受饒在於肥脯，得力在於美酒，若場功畢，租输至，錄社長，召闾師，條牒所領，註列名讳，則豚雞爭下，壶榼橫至，遂乃定一以為十，拘五以為二，蓋由熱啖紆其腹，而杜康咥其胃。","sortOrder":10},
  {"id":"s_work_nvlt_65_11","chapterId":"ch_work_nvlt_65","text":"◇田《家語》曰：虞芮二國，爭田而訟，連年不决，乃相謂曰：西伯仁人也，盍往质焉，入其境，則耕者讓畔，行者讓路，入其朝，則士讓為大夫，大夫讓為卿，虞芮之君曰：嘻，吾儕小人，不可以入君子之朝，遂以其所爭為間田。","sortOrder":11},
  {"id":"s_work_nvlt_65_12","chapterId":"ch_work_nvlt_65","text":"《漢書》曰：陳平少時家貧，好讀書，治黃帝老子之術，有田三十畝，與伯居，伯常耕，縱平使遊學。","sortOrder":12},
  {"id":"s_work_nvlt_65_13","chapterId":"ch_work_nvlt_65","text":"又曰：貢禹上書曰：臣禹年老貧，家資不滿萬錢，妻子糠豆不贍，短褐不完，有田百三十畝，陛下過意徵臣，臣賣田百畝，以供車馬。","sortOrder":13},
  {"id":"s_work_nvlt_65_14","chapterId":"ch_work_nvlt_65","text":"又曰：張禹為人謹厚，內殖货财，及富貴，多買田，至四百頃，皆涇渭溉灌，極膏腴。","sortOrder":14},
  {"id":"s_work_nvlt_65_15","chapterId":"ch_work_nvlt_65","text":"又曰：太始二年，趙中大夫白公，奏穿渠，引涇水，首起穀口，尾入櫟陽江［《太平御覽》八百二十一作涇。］渭中，溉四千五百餘頃，因名白渠，民歌之曰：田於何所，池陽穀口，鄭國在前，白渠起後，舉插為雲，决渠為雨，涇水一石，其泥數斗，且溉且粪，長我禾黍。","sortOrder":15},
  {"id":"s_work_nvlt_65_16","chapterId":"ch_work_nvlt_65","text":"華峤《後漢書》曰：周燮专精禮易，不讀非聖之書，不修贺問之好，有先人草庐，結於岡畔，下有陂田，常肆勤以自給，非身所耕漁不食。","sortOrder":16},
  {"id":"s_work_nvlt_65_17","chapterId":"ch_work_nvlt_65","text":"《晉中興書》曰：郭翻少有志操，居貧無業，起往古荒田，先立表題，經年無主，然後乃作，將熟，有認之者，翻悉推與之。","sortOrder":17},
  {"id":"s_work_nvlt_65_18","chapterId":"ch_work_nvlt_65","text":"萧廣濟《孝子傳》曰：原平墓下有數十畝田，不屬原平，每農月，耕者恒裸，原平不欲使慢其墳墓，乃歸賣家資，買此田，三農之月，辄束帶垂泣，躬自耕墾。","sortOrder":18},
  {"id":"s_work_nvlt_65_19","chapterId":"ch_work_nvlt_65","text":"【詩】宋陶潛雜詩曰：种豆南山下，草盛豆苗稀，晨興理荒秽，帶月荷鋤歸。","sortOrder":19},
  {"id":"s_work_nvlt_65_20","chapterId":"ch_work_nvlt_65","text":"梁劉孝綽報王永興觀田詩曰：重門寂已暮，案牍罢嚣尘，輕涼生筍席，微風起扇輪，浮瓜聊可貴，溢酒亦成珍，复有寒泉井，兼以瑩心神，睠彼忘言客，閒居伊洛濱，顧已慚困地，徒知薑桂辛，但原崇明德，無謂德無鄰。","sortOrder":20},
  {"id":"s_work_nvlt_65_21","chapterId":"ch_work_nvlt_65","text":"【議】晉陆機大田議曰：臣聞隆名之主，不改法而下治，陵夷之世，不易術而民怠，夫商人逸而利厚，農人勞而報薄，导農以利則耕夫勤，節商以法則遊子歸。","sortOrder":21},
  {"id":"s_work_nvlt_65_22","chapterId":"ch_work_nvlt_65","text":"【論】魏王粲務本論曰：古者之理國也，以本為務，八政之於民也，以食為首，是以黎民時雍，降福孔皆也，故仰司星辰，以審其時，俯耕籍田，以率其力，封祀農稷，以神其事，祈穀報年，以寵其功，設農師以監之，置田畯以董之，黍稷茂則喜而受賞，田不墾則怒而加罰，都不得有伏民，室不得有懸秬，野積逾冬，奪者無罪，場功過限，竊者不刑，所以競之於閉藏也，先王藉田以力，任力以夫，議其老幼，度其遠近，种有常時，耘有常節，收有常期，此賞罰之本，种不當時，耘不及節，收不應期者，必加其罰，苗實逾等，必加其賞也，農益地辟，則吏受大賞也，農損地狹，則吏受重罰，天火之焚人也，甚於怠農，慎火之力也，輕於秬秐，通邑大都，有嚴令則火稀，無嚴令則燒者數，非賞罰不能齊也。","sortOrder":22},
  {"id":"s_work_nvlt_65_24","chapterId":"ch_work_nvlt_65","text":"《易》曰：贲於丘園。","sortOrder":24},
  {"id":"s_work_nvlt_65_25","chapterId":"ch_work_nvlt_65","text":"《詩》曰：樂彼之園。","sortOrder":25},
  {"id":"s_work_nvlt_65_26","chapterId":"ch_work_nvlt_65","text":"又曰：園有桃。","sortOrder":26},
  {"id":"s_work_nvlt_65_27","chapterId":"ch_work_nvlt_65","text":"又曰：無逾我園。","sortOrder":27},
  {"id":"s_work_nvlt_65_28","chapterId":"ch_work_nvlt_65","text":"又曰：遊於北園。","sortOrder":28},
  {"id":"s_work_nvlt_65_29","chapterId":"ch_work_nvlt_65","text":"子建詩曰：清夜遊西園。","sortOrder":29},
  {"id":"s_work_nvlt_65_30","chapterId":"ch_work_nvlt_65","text":"古詩曰：鬱鬱園中柳。","sortOrder":30},
  {"id":"s_work_nvlt_65_31","chapterId":"ch_work_nvlt_65","text":"《說文》曰：树果曰園，树菜曰圃。","sortOrder":31},
  {"id":"s_work_nvlt_65_32","chapterId":"ch_work_nvlt_65","text":"《莊子》曰：漢陰丈人灌園，凿隧而入井。","sortOrder":32},
  {"id":"s_work_nvlt_65_33","chapterId":"ch_work_nvlt_65","text":"《韓子》曰：昔弥子瑕有寵於衛，與君遊於果園，食桃而甘，以其半啖君，君曰。愛我哉。","sortOrder":33},
  {"id":"s_work_nvlt_65_34","chapterId":"ch_work_nvlt_65","text":"《史記》曰：公儀休相魯，拔園葵，去織婦。","sortOrder":34},
  {"id":"s_work_nvlt_65_35","chapterId":"ch_work_nvlt_65","text":"又曰：董仲舒下帷講誦，三年不觀於舍園。","sortOrder":35},
  {"id":"s_work_nvlt_65_36","chapterId":"ch_work_nvlt_65","text":"《漢書》曰：和帝詔有司，自京師果園，悉假與貧人。","sortOrder":36},
  {"id":"s_work_nvlt_65_37","chapterId":"ch_work_nvlt_65","text":"《國語》曰：趙簡子田於蝼，蝼園名。","sortOrder":37},
  {"id":"s_work_nvlt_65_38","chapterId":"ch_work_nvlt_65","text":"《三秦記》曰：漢武有名園曰樊川，一名御宿，有大梨如五升，名含消。","sortOrder":38},
  {"id":"s_work_nvlt_65_39","chapterId":"ch_work_nvlt_65","text":"《漢書》［案本條，本書九十八，《初學記》二，《太平御覽》十二，八七二引作魏明帝與東阿王植詔，疑漢當作魏。］曰：明帝詔，先帝時靈芝生芳林園中，自吾建成承露已來，甘露复降芳林園。","sortOrder":39},
  {"id":"s_work_nvlt_65_40","chapterId":"ch_work_nvlt_65","text":"《淮南子》曰：夫臨江之乡，其人汲水以溉其園，江水弗减也。","sortOrder":40},
  {"id":"s_work_nvlt_65_41","chapterId":"ch_work_nvlt_65","text":"又曰：山有猛獸，林木為之不斬，園有螫虫，藜藿為之不采。","sortOrder":41},
  {"id":"s_work_nvlt_65_42","chapterId":"ch_work_nvlt_65","text":"謝承《後漢書》曰：法真隱居大泽，講論術藝，歷年不問園圃。","sortOrder":42},
  {"id":"s_work_nvlt_65_43","chapterId":"ch_work_nvlt_65","text":"又曰：吳祐遷膠東侯相，時濟北戴宏父為縣丞，宏年十六，從在丞舍，祐每行園，常聞諷讀之音，甚奇之，與為友，宏卒成儒宗，知名東夏，為河間相，因自免歸家，不复仕，灌園蔬，以經書教授，年九十八卒。","sortOrder":43},
  {"id":"s_work_nvlt_65_44","chapterId":"ch_work_nvlt_65","text":"《華陽國志》曰：何隨家養竹園，人盜其筍，隨行遇見，恐盜者覺怖走，竹傷其足，挈履徐步而歸。","sortOrder":44},
  {"id":"s_work_nvlt_65_45","chapterId":"ch_work_nvlt_65","text":"桂陽先賢記曰：蘇纟冗嘗除門廷，有眾賓來，纟冗告母曰：人招纟冗去，已种藥著後園梅树下，可治百疾，一葉愈一人，賣此藥過，足供養。","sortOrder":45},
  {"id":"s_work_nvlt_65_46","chapterId":"ch_work_nvlt_65","text":"《魏志》曰：明帝起景陽山於芳林園中。","sortOrder":46},
  {"id":"s_work_nvlt_65_47","chapterId":"ch_work_nvlt_65","text":"又曰：京城內有園，患無水，傅玄先生［按本條見魏志二十九杜夔傳註傅玄叙馬鈞事，傅文中稱馬鈞為先生，此衍傅玄二字。］乃作翻車，令童轉之，灌水更入，其功百倍。","sortOrder":47},
  {"id":"s_work_nvlt_65_48","chapterId":"ch_work_nvlt_65","text":"向秀別傳曰：秀常與呂安灌園於山陽，收其利以供酒食之費。","sortOrder":48},
  {"id":"s_work_nvlt_65_49","chapterId":"ch_work_nvlt_65","text":"晉宮闕名曰：洛陽宮有琼圃園靈芝園石祠園，鄴有鳴鵠園蒲萄園華林園，世說曰：簡文入華林園，顧謂左右曰：會心處不必在遠，翳然林水，便自有濠濮間想，覺鳥獸禽魚，自來親人。","sortOrder":49},
  {"id":"s_work_nvlt_65_50","chapterId":"ch_work_nvlt_65","text":"又曰：王子敬入會稽，經吳門，顧辟強有名園，先不識主人，遙往其家，值顧方集賓友，酣燕園中，而王遊歷既畢，指麾好惡，傍若無人，顧勃然曰：不足齒之伧爾，使驅其左右出門，王獨坐舆上，展轉顧望，而仆從不至，遂移時。","sortOrder":50},
  {"id":"s_work_nvlt_65_51","chapterId":"ch_work_nvlt_65","text":"又曰：管寧華歆，園中鋤菜，見地有片金，管揮鋤與瓦石不異，華捉而掷之。","sortOrder":51},
  {"id":"s_work_nvlt_65_52","chapterId":"ch_work_nvlt_65","text":"法顯記曰：舍衛精舍東北六百里，毗舍佉母作精舍，請佛及借此處，故在秖洹舍大園落，有二門，一門東向，一北向，此園即須達長者布金錢買地處也，精舍當中央，佛住此處最久，說法度人，經行坐處，亦盡起塔，皆有名字。","sortOrder":52},
  {"id":"s_work_nvlt_65_53","chapterId":"ch_work_nvlt_65","text":"又曰：拘夷那竭城東行，到毗舍離城北，有大林，重閣精舍，佛住處，及阿難半身塔，其城里本菴婆羅女家，為佛起塔，今故在城南三里道西，菴婆羅女以園施佛住處。","sortOrder":53},
  {"id":"s_work_nvlt_65_54","chapterId":"ch_work_nvlt_65","text":"【詩】宋陶潛雜詩曰：开荒南野际，守拙歸園田，方泽十餘畝，草屋八九間，榆竹荫後簷，桃李羅堂前，結庐在人境，而無車馬喧，問君何能爾，心遠地自偏，采菊東篱下，悠然望南山，秋菊有佳色，總露掇其英，汎此忘忧物，遠我達世情。","sortOrder":54},
  {"id":"s_work_nvlt_65_55","chapterId":"ch_work_nvlt_65","text":"宋謝靈運還舊園詩曰：浮舟千仞壑，總辔萬尋顛，流沫不足险，石林豈為艱，夫子昭情素，探懷授往篇。","sortOrder":55},
  {"id":"s_work_nvlt_65_56","chapterId":"ch_work_nvlt_65","text":"宋謝莊北宅秘園詩曰：夕天霁晚氣，輕霞澄暮陰，微風清幽幌，餘日照青林，收光漸窗歇，窮園自荒深，绿池翻素景，秋槐响寒音，伊人傥同愛，絃酒共栖尋。","sortOrder":56},
  {"id":"s_work_nvlt_65_57","chapterId":"ch_work_nvlt_65","text":"齊竟陵王遊後園詩曰：讬性本禽魚，栖情閒物外，萝径轉連綿，松軒方杳藹，丘壑每淹留，風雲多賞會。","sortOrder":57},
  {"id":"s_work_nvlt_65_58","chapterId":"ch_work_nvlt_65","text":"齊王俭春日家園詩曰：徙倚未雲暮，陽光忽已收，羲和無停晷，壮士豈淹留，苒苒老將至，功名竟不修，稷契匡虞夏，伊呂翼商周，撫躬謝先哲，解绂歸山丘。","sortOrder":58},
  {"id":"s_work_nvlt_65_59","chapterId":"ch_work_nvlt_65","text":"梁簡文帝遊韦黃門園詩曰：息車冠蓋里，停辔仲長園，簷疏遠興積，賓至羽觴繁。","sortOrder":59},
  {"id":"s_work_nvlt_65_60","chapterId":"ch_work_nvlt_65","text":"又夜遊北園詩曰：星芒侵嶺树，月晕隱城樓，暗花舒不覺，明波動見流。","sortOrder":60},
  {"id":"s_work_nvlt_65_61","chapterId":"ch_work_nvlt_65","text":"又臨後園詩曰：隱淪遊少海，神仙入太華，我有逍遙趣，中園复可嘉，千株同落葉，百尺共尋霞。","sortOrder":61},
  {"id":"s_work_nvlt_65_62","chapterId":"ch_work_nvlt_65","text":"梁元帝遊後園詩曰：暮春多淑氣，斜景落高舂，日照池光淺，雲歸山望浓，入林迷曲径，度渚躍危峰。","sortOrder":62},
  {"id":"s_work_nvlt_65_63","chapterId":"ch_work_nvlt_65","text":"又晚景遊後園詩曰：高軒聊騁望，煥景入川梁，波橫山渡影，雨罢葉生光，日移花色異，風散水文長。","sortOrder":63},
  {"id":"s_work_nvlt_65_64","chapterId":"ch_work_nvlt_65","text":"梁沈約宿東園詩曰：槿篱疏复密，荆扉新且故，树顶鳴風飆，草根積霜露，驚纴去不息，征鳥時返顧，茅棟嘯愁鴟，平岡走寒兔，夕陰帶層阜，長煙引輕素。","sortOrder":64},
  {"id":"s_work_nvlt_65_65","chapterId":"ch_work_nvlt_65","text":"又行園詩曰：寒瓜方臥垅，秋菰亦滿陂，紫茄紛烂漫，绿芋鬱參差，初菘向堪把，時韭日離離。","sortOrder":65},
  {"id":"s_work_nvlt_65_66","chapterId":"ch_work_nvlt_65","text":"【賦】漢枚乘梁王兔園賦曰：脩竹檀栾，夹池水旋，兔園併馳，鹯鹗鷂雕，翡翠鸲鹆，巢枝穴藏，被塘臨穀，聲音相聞，啄尾離屬，於是晚春早夏，邯鄲襄國，相與雜沓而往款焉，高冠扁焉，長劍閒焉，左挟彈焉，右執鞭焉，日移樂衰，遊觀西園，從容安步，斗雞走兔，俯仰釣射，煎熬炰炙，極樂到暮，若夫采桑之婦，連袖方路。","sortOrder":66},
  {"id":"s_work_nvlt_65_67","chapterId":"ch_work_nvlt_65","text":"齊謝朓遊後園賦曰：積芳兮選木，幽蘭兮翠竹，上芜芜兮陰景，下田田兮被穀，左蕙畹兮弥望，右芝原兮寫目，山霞起而削成，水積明以經复，於是敞風闼之藹藹，耸雲馆之迢迢，周步簷以升降，對玉堂之泬寥，爾乃日栖榆柳，霞照夕陽，孤蝉已散，去鳥成行，惠氣湛兮帷殿肅，清陰起兮池馆涼。","sortOrder":67},
  {"id":"s_work_nvlt_65_68","chapterId":"ch_work_nvlt_65","text":"梁裴子野遊華林園賦曰：谅無庸於殿省，且栖遲而不事，譬籠鳥與池魚，本山川而有思，伊暇日而容與，時遨遊以荡志，正殿則華光弘敞，重台則景陽秀出，赫弈翚煥，陰臨鬱律，絕尘霧而上征，尋雲霞而蔽日，經增城而斜趣，有空垅之石室，在盛夏之方中，曾匪風而自栗，溪穀則沱潛泒別，峭峡則险難壁立，積峻窦溜，阑幹草石，苔藓駮荦，丛攒既而，登望徙倚，臨遠凭空，廣觀逖聽，靡有不通。","sortOrder":68},
  {"id":"s_work_nvlt_65_69","chapterId":"ch_work_nvlt_65","text":"梁江淹梁王兔園賦曰：或重古輕今者，仆曰：何為其然哉，無知音則已矣，聊為古賦體，以奋枚叔之製雲，於是金塘緬演，绿竹被陂，缭繞青翠，若近复遠，水鳥鴐鹅，雏鴟鴇雁，上飛衡陽，下宿沔漢，十十五五，忽合而复散，於是大夫之徒，稱詩而歸，春陽始晚，未華未稀，卒逢邯鄲之女，蕙色玉质，綺裳下見，錦衣上出。","sortOrder":69},
  {"id":"s_work_nvlt_65_70","chapterId":"ch_work_nvlt_65","text":"周庾信小園賦曰：若夫一枝之上，巢甫得安巢之所，一壶之中，壶公有容身之地，豈必連闼洞房，南陽樊重之第，绿墀青琐，西漢王公之宅，餘有數畝弊庐，寂寞人外，聊以擬伏臈，聊以避風霜，雖复晏婴近市，不求朝夕之利，潘嶽面城，且見閒居之樂，爾乃窟室徘徊，聊同凿坏，琴號珠柱，書名玉杯，有棠梨而無馆，足酸棗而非台，猶得欹侧八九丈，從斜數十步，榆柳三兩行，梨桃百餘树，拨蒙密兮見窗，行欹斜兮得路，蝉有蓊兮不鳴，雉無羅兮何懼，草树混淆，枝格相交，山為匮覆，水有堂坳，崎嶇兮狹室，穿漏兮茅茨，簷直倚而妨帽，戶平行而礙眉，坐帳無鶴，支床有龟，鳥多閒暇，花隨四時，心則歷陵枯木，發則睢陽亂絲，一寸二寸之魚，三竿兩竿之竹，離披落格之藤，烂熳無丛之菊，落葉半床，狂花滿屋，名為野人之家，是謂愚公之穀，誠偃息於茂林，乃久羨於抽簪，雖有門而長閉，實無水而恒沉，草無忘忧之意，花無長樂之心，鳥何事而逐酒，魚何情而聽琴，薄晚閒閨，老幼相携，蓬頭王霸之子，椎髻梁鸿之妻，树搔搔而風急，天惨惨而雲低，聚空仓而雀噪，驚嬾婦而蝉啼，昔早濫於吹噓，藉文言而慶餘，門有通德，家藏賜書，遂山崩川竭，水碎瓦裂，關山則風月凄怆，隴水則肝腸斷絕，百齡兮倏忽，菁華兮已晚，不雪雁門之羁，先念房陵之遠，非淮海兮可变，非金丹兮能轉，不曝骨兮龍門，終低頭兮馬阪。","sortOrder":70},
  {"id":"s_work_nvlt_65_71","chapterId":"ch_work_nvlt_65","text":"【頌】晉潘尼後園頌曰：芒芒在昔，悠悠結繩，大朴未散，玄化霑凝，羲皇繼踵，三代相承，五德更王，文质迭興，天命匪諶，祐謙辅信，乃眷我皇，光有大晉，應期納祚，天人是順，和氣四充，惠泽旁润，神祇告祥，四靈效质，遊龍升雲，儀鳳翳日，甘露晨流，醴泉涌溢，華夏既寧，八荒靜謐，人亦有言，吾何以休，乃延卿士，從皇以遊，長筵遠布，廣幕四周，嘉肴惟芳，旨酒思柔，巖巖峻嶽，湯湯玄流，翔鳥鼓翼，遊魚載浮，明明天子，肅肅庶官，文士濟濟，武夫桓桓，講藝華林，肆射後園，威儀既具，弓矢斯閒，恂恂謙德，穆穆聖顏，賜以宴飲，詔以話言，黍稷既登，货财既丰，仁風潛運，皇化弥隆，征夫釋甲，戰士罢戎，遐夷慕義，絕域望風，無或慢易，在始慮終，無或安逸，在盈思冲。","sortOrder":71},
  {"id":"s_work_nvlt_65_72","chapterId":"ch_work_nvlt_65","text":"【引】謝莊懷園引曰：鸿飛從萬里，飛飛河岱起，辛勤越霜霧，聯翩溯江汜，去舊國，违舊乡，舊海悠且長，回首瞻東路，延翮向秋方，登楚都，入楚關，楚地萧瑟楚山寒，歲去冰未已，春來雁不還，風肅幌兮露濡庭，漢水初绿柳葉青，朱光霭霭雲英英，離禽喈喈又晨鳴，菊有秀兮松有蕤，忧來年去容發衰，流陰逝景不可追，臨堂危坐怅欲悲，试讬意兮向芳荪，心綿綿兮屬荒樊，想绿蘋兮既冒沼，念幽蘭兮已盈園，夭桃晨暮發，春湋旦夕喧，青苔芜石路，宿草尘蓬門。","sortOrder":72},
  {"id":"s_work_nvlt_65_73","chapterId":"ch_work_nvlt_65","text":"【詠】晉湛方生遊園詠曰：谅茲境之可懷，究川阜之奇势，水窮清以澈鑒，山鄰天而無际，乘初霁之新景，登北馆以悠矚，對荆門之孤阜，傍漁陽之秀嶽，乘夕陽而含詠，杖輕策以行遊，袭秋蘭之流芬，幕長猗之森脩，任缓步以升降，歷丘墟而四周，智無涯而難恬，性有方而易適，差一豪而遽乖，徒理存而事隔，故羁馬思其華林，籠雉想其皋泽，矧流客之歸思，豈可忘於畴昔。","sortOrder":73},
  {"id":"s_work_nvlt_65_74","chapterId":"ch_work_nvlt_65","text":"【啟】梁張缵謝東宮赉園啟曰：性愛山泉，頗樂閒曠，雖复伏膺尧門，情存魏闕，至於一丘一壑，自謂出處無辨，常原卜居幽僻，屏避喧尘，傍山臨流，面郊負郭，依林結宇，憩桃李之夏陰，對径开軒，采橘柚之秋實，而王畿陆海，畝號一金，涇渭土膏，豪杰所競，徙居好畤，必待使越之裝，別馆河陽，亦資牧荆之富，此園左帶平湖，修陂千頃，右臨長薄，清潭百仞，前逼逸陌，朝夕爽垲，後望鍾阜，表里煙霞，每賸春迎夏，華卉競發，背秋向冬，雲物澄霁，窥瞰戶牖，不異登臨，升降階墀，已窮歷覽，舟楫所屆，累日不能究其源，魚鳥之丰，山泽不能逾其美。","sortOrder":74},
  {"id":"s_work_nvlt_65_76","chapterId":"ch_work_nvlt_65","text":"《毛詩》曰：折柳樊圃。","sortOrder":76},
  {"id":"s_work_nvlt_65_77","chapterId":"ch_work_nvlt_65","text":"又曰九月筑場圃。","sortOrder":77},
  {"id":"s_work_nvlt_65_78","chapterId":"ch_work_nvlt_65","text":"傳曰：晉侯取蒍氏之圃以為囿。","sortOrder":78},
  {"id":"s_work_nvlt_65_79","chapterId":"ch_work_nvlt_65","text":"《論語》曰：樊遲請學為圃，子曰：吾不如老圃。","sortOrder":79},
  {"id":"s_work_nvlt_65_80","chapterId":"ch_work_nvlt_65","text":"《列子》曰：三畝之圃不能耘。","sortOrder":80},
  {"id":"s_work_nvlt_65_81","chapterId":"ch_work_nvlt_65","text":"《楚辭》曰：忽死蘭圃，楚有蕙圃。","sortOrder":81},
  {"id":"s_work_nvlt_65_82","chapterId":"ch_work_nvlt_65","text":"《山海經》曰：槐江之山，實惟帝之平圃，［即懸圃也。］","sortOrder":82},
  {"id":"s_work_nvlt_65_83","chapterId":"ch_work_nvlt_65","text":"《淮南子》曰：崑崙山有曾城九重，其高萬一千里，懸圃涼風在崑崙之中，是其疏圃，疏圃之池，滿足潢水。","sortOrder":83},
  {"id":"s_work_nvlt_65_84","chapterId":"ch_work_nvlt_65","text":"《穆天子傳》曰：舂山之泽，清水出泉，溫和無風，飛鳥百獸之所飲，先王之所謂懸圃。","sortOrder":84},
  {"id":"s_work_nvlt_65_85","chapterId":"ch_work_nvlt_65","text":"【詩】梁庾肩吾從皇太子出玄圃詩曰：春光起麗谯，屣履步山椒，閣影臨飛蓋，湋鳴入洞箫，水還登故渚，树長荫前桥，绿荷生倚葉，丹藤上細苗，顧循慚振藻，何用擬琼瑤。","sortOrder":85},
  {"id":"s_work_nvlt_65_86","chapterId":"ch_work_nvlt_65","text":"【銘】隋江總玄圃石室銘曰：仙山石〈口呙〉，仙宇石牆，地雲正域，道示修羊，紫煙碧露，絳雪玄霜，廣成不踐，王烈未翔，移華甲觀，徙構震方，遠跨飛梁，俯臨倒景，琼蕊珠树，金階玉井，映日分暉，搖風共影，岫浓翠合，林虛桂靜，朔去偷桃，董來货杏，簷非刻削，戶恣登臨，迎春花近，避暑涼深，秋雲卷闇，冬霰停陰，桐栖鳳采，竹化龍吟，輕飛亂色，激溜成音，天縱储睿，生知作兩，絃誦餘隙，仁智為賞，河曲停遊，洛濱息往，祥梨吐秀，瑞燕流响，一物或镌，萬國斯仰。","sortOrder":86},
  {"id":"s_work_nvlt_65_88","chapterId":"ch_work_nvlt_65","text":"《禮記》曰：古者天子諸侯，必有公桑，蠶室近川而為之，卜三宮之夫人世婦之吉者，使入蠶室，奉种浴於川，桑於公桑。","sortOrder":88},
  {"id":"s_work_nvlt_65_89","chapterId":"ch_work_nvlt_65","text":"又曰：季春之月，後妃齊戒親桑，以勸蠶事，蠶事既登，分茧稱絲，以供郊廟之服。","sortOrder":89},
  {"id":"s_work_nvlt_65_90","chapterId":"ch_work_nvlt_65","text":"《東觀漢記》曰：明德馬後，置織室，蠶於濯龍中，數往來觀视，內以為娱樂，外以先女功。","sortOrder":90},
  {"id":"s_work_nvlt_65_91","chapterId":"ch_work_nvlt_65","text":"《續漢書》曰：貴人助蠶，玳瑁釵，加簪珥。","sortOrder":91},
  {"id":"s_work_nvlt_65_92","chapterId":"ch_work_nvlt_65","text":"又曰：光武建武二年，野蠶成茧，野民收其絮。","sortOrder":92},
  {"id":"s_work_nvlt_65_93","chapterId":"ch_work_nvlt_65","text":"《玄中記》曰：大月氏有牛，名曰日及，割取肉一二斤，明日瘡愈，漢人入國，示之以為珍異，漢人曰：吾國有虫，大如小指，名曰蠶，食桑葉，為人吐絲，外國复不信有之。","sortOrder":93},
  {"id":"s_work_nvlt_65_94","chapterId":"ch_work_nvlt_65","text":"《古今註》曰：元帝永元四年，東萊郡東牟山，有野蠶為茧，茧生蛾，蛾生卵，卵著石，收得萬餘石，民以為蠶絮。","sortOrder":94},
  {"id":"s_work_nvlt_65_95","chapterId":"ch_work_nvlt_65","text":"【賦】晉楊泉蠶賦曰：惟陰陽之產物，氣陶化而播流，物受氣而含生皆纏綿而自周，伊夫蠶之為物，功巨大而弘優，成天子之袞冕，著皇後之盛服，昭五色之玄黃，作四時之单複，是以王者貴此功焉，使皇後命三宮之夫人。又世婦之吉者，親桑於北宮，二月初吉，遂布令於天下，百辟兆民，使鹹務焉，是以仲春之月，吉日庚午，既差我馬，惟蠶之祖，編使童男，作以童女，溫室既調，蠶母入處，陳布說种，柔和得所，晞用清明，浴用穀雨，爰求柔桑，切若細縷，起止得時，燥濕是候，逍遙偃仰，進止自如，仰似龍騰，伏似虎趺，員身方腹，列足双俱，昏明相推，日時不居，粵召役夫，筑室於房，於房伊何，在庭之東，東受日景，西望餘陽，既酌以酒。又挹以漿，壶餐在侧，敷修在旁，我鄰我党，我助我康，於是乎蠶事畢矣，大務時成，閣紆卷薄，洒扫宮庭，蠶母須飾，從容自寧，至於再宿三日，乃开阖啟房，是瞻是觀，方者四張，員者紆盤，縱者相屬，橫者交連，分薪柴而解著，茧系互而相攀，競以挐攫，再笑再言，惰者悅而忘解，劣者勉以增勤，是月也，天子以太牢之禮，獻茧於寢廟，皇後親繰三盆，然後辨於夫人世婦，至於百辟卿士，下及兆民，鹹趨繰事，爾乃絲如凝膏，其白伊雪，以為衣裳，冠冕服飾，禮神納賓，各有分職，以給百禮，罔不斯服，夫功也起於綿，綿成於翼，翼頌之難，周論之罔極，殷斯勤斯，如何勿憶。","sortOrder":95},
  {"id":"s_work_nvlt_65_97","chapterId":"ch_work_nvlt_65","text":"《毛詩》曰：跂彼織女，終日七襄，雖則七襄，不成報章。","sortOrder":97},
  {"id":"s_work_nvlt_65_98","chapterId":"ch_work_nvlt_65","text":"《魏志》曰：中山恭王裒，徙封濮陽，太和二年就國，尚俭約，敕妃妾紡績織纴，習為家人之事。","sortOrder":98},
  {"id":"s_work_nvlt_65_99","chapterId":"ch_work_nvlt_65","text":"《博物志》曰：近世有居海渚者，每年八月，有浮查來，此人乃立於查上，忽忽不覺晝，奄至一處，有城郭屋舍，望室中多見織婦，見一丈夫牵牛，渚次飲之，驚問此何處，答曰：君可詣蜀，問嚴君平。","sortOrder":99},
  {"id":"s_work_nvlt_65_100","chapterId":"ch_work_nvlt_65","text":"《搜神記》曰：南海之外有鲛人，水居如魚，不废績織。","sortOrder":100},
  {"id":"s_work_nvlt_65_101","chapterId":"ch_work_nvlt_65","text":"【詩】古詩曰：迢迢牵牛星，皎皎河漢女，纖纖濯素手，札札弄機杼。","sortOrder":101},
  {"id":"s_work_nvlt_65_102","chapterId":"ch_work_nvlt_65","text":"梁簡文帝詠中婦織流黃詩曰：翻花滿階砌，愁人獨上機，浮雲西北起，孔雀東南飛，調絲時繞腕，易躡乍牵衣，鳴梭逐動钏，紅妆映落暉。","sortOrder":102},
  {"id":"s_work_nvlt_65_103","chapterId":"ch_work_nvlt_65","text":"梁劉孝威在郄縣遇見人織寄婦詩曰：妖姬含怨情，織緯起秋聲，度梭環玉動，踏躡珮珠明，經稀疑杼涩，緯斷恨絲輕，蒲萄始欲罢，鴛鴦猶未成，雲棟共徘徊，紗窗相向开，窗疏眉語度，紗輕眼笑來，昽昽隔淺沙，的的見妆華，鏤玉同心藕，雜寶連枝花，紅巾向後結，金篸臨鬢斜，機顶掛流蘇，機傍垂結珠，青絲引伏兔，黃金繞鹿盧，艳采裙邊出，芳脂口上渝，百城交問遺，五馬共踟蹰，直為閨中人，守故不要新，夢啼渍花枕，覺淚濕羅巾，獨眠真自難，重衾猶覺寒，玄憶凝脂缓，弥想橫尘歡，行驅金絡騎，歸就城南端，南端稍有期，想子亦勞思，羅襦久應罢，花釵堪更治，新妆不點黛，餘還自畫眉。","sortOrder":103},
  {"id":"s_work_nvlt_65_104","chapterId":"ch_work_nvlt_65","text":"陳徐陵詠織婦詩曰：纖纖運玉指，脈脈正蛾眉，振躡开交縷，停梭續斷絲，簷前初月照，洞戶未垂帷，弄機行掩淚，弥令織素遲。","sortOrder":104},
  {"id":"s_work_nvlt_65_105","chapterId":"ch_work_nvlt_65","text":"陳萧詮賦婀娜當軒織詩曰：東南初日照秦樓，西北織婦正娇羞，綺窗猶垂翡翠幌，珠帘半上珊瑚鉤，新妆入機映春牖，弄杼鳴梭挑纖手，何曾織素讓新人，不掩流蘇推中婦，三日五匹未言遲，衫長腕弱繞輕絲，綾中轉躡成離鵠，錦上回文作別詩，不惜紈素同霜雪，更傷秋扇箧中辭。","sortOrder":105},
  {"id":"s_work_nvlt_65_106","chapterId":"ch_work_nvlt_65","text":"【賦】後漢王逸機賦曰：帝軒龍躍，庶業是昌，俯覃聖恩，仰覽三光，爰製布帛，始垂衣裳，於是取衡山之孤桐，南嶽之洪樟，結靈根於盤石，讬九層於巖傍，性條畅以端直，貫雲表而剀仓，儀鳳晨鳴翔其上，怪獸群萃而陆梁，於是乃命匠人，潛江奋驤，逾五嶺，越九岡，斬伐剖析，擬度短長，勝复回轉，剋像乾形，大匡淡泊，擬短則川平，光為日月，蓋取昭明，三軸列布，上法台星，兩骥齊首，俨若將征，方圓綺错，微妙窮奇，虫禽品獸，物有其宜，兔耳跧伏，若安若危，猛犬相守，竄身匿蹄，高樓双峙，下臨清池，遊魚衔餌，瀺灂其陂，鹿盧併起，纖繳俱垂，一往一來，匪勞匪疲，於是暮春代謝，朱明達時，蠶人告訖，舍罢獻絲，或黃或白，蜜〈虫葛〉凝脂，纖纖靜女，經之絡之，爾乃窈窕淑媛，美色貞怡，解鳴珮，釋羅衣，披華幕，登神機，乘輕杼，覽床帷，動搖多容，俯仰生姿。","sortOrder":106},
  {"id":"s_work_nvlt_65_107","chapterId":"ch_work_nvlt_65","text":"晉楊泉織機賦曰：伊百工之為伎，莫機巧之最長，似人君之列位，象百官之設張，立匡郭之製度，如城隔之員方，應萬機以布错，實变態之有章，是以孟秋之月，首殺庶物，工民呈材，取彼椅梓，楨幹脩枝，名匠騁工，美乎利器，心畅體通，膚合理同，規矩盡法，因事作容，好無不媚，事無不供，於是乎女工就，素絲輕，貫綜紀，簡奸清，織女扬翚，美乎如芒，麗姿妍雅，動有令光，足閒蹈躡，手習槛匡，節奏相應，五聲激扬，濁者含宮，清者應商，和聲成柔，慷慨成刚，屈申舒縮，沉浮抑扬，开以厭間，阖以高梁，進以懸魚，退以俠彊，氣变相應，陰感乎陽，黾勉不及，進却頡颃，事物之宜，法天之常，既合利用，得道之方。","sortOrder":107},
  {"id":"s_work_nvlt_65_109","chapterId":"ch_work_nvlt_65","text":"《吳書》曰：虞翻年十二，有客詣翻兄，不遇之，翻乃與客書曰：磁石不受曲針。","sortOrder":109},
  {"id":"s_work_nvlt_65_110","chapterId":"ch_work_nvlt_65","text":"【賦】楚荀况針賦曰：有物於此，生於山阜，處於室堂，無知無功，善治衣裳，不盜不竊，穿窬而行，日夜合離，以成文章，已能合從。又善連橫，下覆百姓，上飾帝王。","sortOrder":110},
  {"id":"s_work_nvlt_65_111","chapterId":"ch_work_nvlt_65","text":"漢曹大家針縷賦曰：鎔秋金之刚精，形微妙而直端，性通遠而漸進，博庶物而一貫，惟針縷之列跡，信廣博而無原，退逶迤以補過，似素絲之羔羊，何斗筲之足筭，鹹勒石而升堂。","sortOrder":111},
  {"id":"s_work_nvlt_65_113","chapterId":"ch_work_nvlt_65","text":"《列子》曰：昔齊人有欲金者，清旦衣冠而之市，適鬻金者所，因攫其金而去，吏捕問之，對曰：取金之時，不見人，徒見金。","sortOrder":113},
  {"id":"s_work_nvlt_65_114","chapterId":"ch_work_nvlt_65","text":"魯連子曰：孟嘗君逐於齊，谭子曰：富貴則就，貧賤則去，此物之必至，而理固然也，原君忽怨，請以市論，市朝則盈，夕則虛，非朝愛而夕則憎之也，势使然。","sortOrder":114},
  {"id":"s_work_nvlt_65_115","chapterId":"ch_work_nvlt_65","text":"《漢書》曰：楚王戊與吳通，申公白公二人諫，不聽，衣之赭衣，使杵臼椎舂於市。","sortOrder":115},
  {"id":"s_work_nvlt_65_116","chapterId":"ch_work_nvlt_65","text":"又曰：刺繡文，不如倚市門，此言末業貧者之資。","sortOrder":116},
  {"id":"s_work_nvlt_65_117","chapterId":"ch_work_nvlt_65","text":"又曰：司隸校尉解光，奏王根曰：縱橫恣意，大治室第，中立土山，而立兩市，殿上赤墀，戶下青璅。","sortOrder":117},
  {"id":"s_work_nvlt_65_118","chapterId":"ch_work_nvlt_65","text":"《東觀漢記》曰：樊重治家產業，起庐舍高樓連閣，陂池灌註，竹木成林，閉門成市。","sortOrder":118},
  {"id":"s_work_nvlt_65_119","chapterId":"ch_work_nvlt_65","text":"華峤《後漢書》曰：宋登為汝陰令，為政明能，號稱神父，出為潁川太守，市無二价，道不拾遺。","sortOrder":119},
  {"id":"s_work_nvlt_65_120","chapterId":"ch_work_nvlt_65","text":"《漢名臣奏》曰：太尉屬應劭等議，以為鮮卑隔在漠北，犬羊為群，無君長帥，庐落之居。又其天性，貪而無信，故自漢興於茲，數犯障塞，且無寧歲，吏民創禁，不與交關，唯至胡市，乃成靡服，非畏威懷德，實玩中國珍異之故耳。","sortOrder":120},
  {"id":"s_work_nvlt_65_121","chapterId":"ch_work_nvlt_65","text":"戴延之《西征記》曰：洛陽舊有二市，一曰金市，在宮西大城內。","sortOrder":121},
  {"id":"s_work_nvlt_65_122","chapterId":"ch_work_nvlt_65","text":"【詩】梁庾肩吾看放市詩曰：旗亭出御道，遊目暫回車，既非隨舞鵠，聊自入看書，懸龟識季主，榜酒見相如，日中人已合，黃昏故未疏。","sortOrder":122},
  {"id":"s_work_nvlt_65_123","chapterId":"ch_work_nvlt_65","text":"陳張正見賦得日中市朝滿詩曰：雲閣綺霞生，旗亭麗日明，尘飛三市路，蓋入九重城，竹葉當爐滿，桃花帶綬輕，唯見爭名利，安知大隱情。","sortOrder":123},
  {"id":"s_work_nvlt_65_124","chapterId":"ch_work_nvlt_65","text":"【教】梁簡文帝移市教曰：臨淮作守，白鹿隨而忘反，萧令解綬，黃雀從而不歸，况复衛卒遮車，追民擁榜，瞻言前古，眇愧弘多，吾旅泊冬川，阻茲涸水，日中總會，交貿遷移，雖樊無外取，晏得所求，而旗亭舊體，自有常處，不容近违孔奋，遠逐曹參，正恐舊肆盈虛，或成彫废。","sortOrder":124},
  {"id":"s_work_nvlt_65_125","chapterId":"ch_work_nvlt_65","text":"周庾信答移市教曰：昔張楷硕儒，尚移弘農之市，宜官［原訛宮，據冯校本改。］妙篆，猶致酒壚之客，况复德總郇周，聲高梁楚，希風慕義之士，舉袂成帷，臥轍反車之流，磨肩相接，遂使王充閱市之處，遠出荒郊，石苞販鐵之所，翻臨涯岸，聖德謙虛，未忘喧湫，欲令吹箫舞鶴，還反舊鄽，賣卜屠羊，請辭新阓，而交貿之党好留，豳岐之眾難遣。","sortOrder":125},
  {"id":"s_work_nvlt_65_126","chapterId":"ch_work_nvlt_65","text":"《藝文類聚》　唐·欧陽詢","sortOrder":126},
  {"id":"s_work_nvlt_66_1","chapterId":"ch_work_nvlt_66","text":"卷六十六產業部下","sortOrder":1},
  {"id":"s_work_nvlt_66_2","chapterId":"ch_work_nvlt_66","text":"○田獵釣錢","sortOrder":2},
  {"id":"s_work_nvlt_66_3","chapterId":"ch_work_nvlt_66","text":"◇田獵","sortOrder":3},
  {"id":"s_work_nvlt_66_4","chapterId":"ch_work_nvlt_66","text":"《禮記》曰：天子諸侯，無事則歲三田，一曰乾豆，二曰賓客，三曰充君之庖，［三田者，夏不田。］無事而不田曰不敬，田不以禮曰暴天物，天子不合围，諸侯不掩群，天子殺則下大綏，諸侯殺則下小綏，［綏當為緌，有虞氏之旗也。］大夫殺則止佐車，佐車止則百姓田獵，［佐車，驅逆之車。］又曰：獭祭魚，然後虞人入泽梁，豺祭獸，然後田獵，鳩化為鷹，然後設罻羅，草木零落，然後入山林，崑虫未蟄，不以火田，不麛不卵，不覆巢。","sortOrder":4},
  {"id":"s_work_nvlt_66_5","chapterId":"ch_work_nvlt_66","text":"《毛詩》曰：騶虞，鵲巢之應也，鵲巢之化行，人倫既正，朝廷既治，天下純被文王之化，庶類蕃殖，蒐田以時，仁如騶虞，則王道成也。","sortOrder":5},
  {"id":"s_work_nvlt_66_6","chapterId":"ch_work_nvlt_66","text":"《六韜》曰：文王卜田於渭陽，將大得，非熊非羆，天遺汝師，以之佐昌，施及三王。大吉，王乃斋三日，乘田車，駕田馬，於渭之陽，見呂尚坐以漁，文王勞而問焉。","sortOrder":6},
  {"id":"s_work_nvlt_66_7","chapterId":"ch_work_nvlt_66","text":"《穆天子傳》曰：天子獵於渗泽，得白狐玄貉，以祭河宗。","sortOrder":7},
  {"id":"s_work_nvlt_66_8","chapterId":"ch_work_nvlt_66","text":"《晏子》曰：景公田，十有八日不反，晏子往見，而衣冠不正，公望見晏子下車，急曰：夫子何遽，得無有故乎，對曰：國人皆謂君安野而好獸，無乃不可乎，公曰：寡人有吾子，猶心之有四支也，有四支故心有佚，寡人有吾子，故寡人佚，《晏子》曰：若心有四支而得佚，則可令四支無心乎，公乃罢田而歸。","sortOrder":8},
  {"id":"s_work_nvlt_66_9","chapterId":"ch_work_nvlt_66","text":"《莊子》曰：梁君出獵，見白雁群，下彀弩欲射之，道有行者，梁君謂行者止，行者不止，白雁群駭，梁君怒，欲射行者，其御公孫龍止之，梁君怒曰：龍不與其君，而顧他人，對曰：昔宋景公時大旱，卜之，必以人祠乃雨，景公下堂頓首曰：吾所以求雨，為民也，今必使吾以人祠乃雨，將自當之，言未卒而大雨，何也，為有德於天而惠於民也，君以白雁故而欲射殺人，主君譬人無異於豺狼也，梁君乃與龍上車歸，呼萬歲，曰：樂哉，人獵皆得禽獸，吾獵得善言而歸。","sortOrder":9},
  {"id":"s_work_nvlt_66_10","chapterId":"ch_work_nvlt_66","text":"《韓子》曰：孟孫獵，得麑，使西秦［《太平御覽》八百三十二作秦西，下同。］巴持之，其母隨而呼之，西秦巴不忍，而與其母，孟孫適至，求麑，對曰：餘不忍而與其母，孟孫大怒，逐之，居三月，复召為其子傅，曰：夫子不忍麑。又且忍吾子乎。","sortOrder":10},
  {"id":"s_work_nvlt_66_11","chapterId":"ch_work_nvlt_66","text":"《戰國策》曰：魏文侯與虞人期獵，具，以飲酒樂，天雨，文侯將出，左右曰：今日飲酒樂，天雨，君將焉之，文侯曰：吾與虞人期獵，雖樂，豈不一會期哉，乃往自罢之，魏於是始強。","sortOrder":11},
  {"id":"s_work_nvlt_66_12","chapterId":"ch_work_nvlt_66","text":"《史記》曰：田叔為魯相，魯王好獵，相常從苑中，王辄休相就馆舍，相出，常暴坐待王苑外，王數使人請相休，終不休，曰：我王暴露苑中，我獨何為就舍，魯王聞之，不大出遊。","sortOrder":12},
  {"id":"s_work_nvlt_66_13","chapterId":"ch_work_nvlt_66","text":"《魏志》曰：文帝將出獵，鮑勋上疏諫，帝手毀其疏而竟行，中道頓息，問侍臣曰：獵之為樂，何與八音也，侍中劉晔對曰：獵勝於樂，勋抗辭曰：夫樂上通神明，下和人理，隆治致化，萬邦鹹乂，故移風易俗，莫善於樂，况獵暴華蓋於原野，因奏晔佞諛不忠。","sortOrder":13},
  {"id":"s_work_nvlt_66_14","chapterId":"ch_work_nvlt_66","text":"《江表傳》曰：曹公與孫權書雲，近者奉辭伐罪，旌麾南指，劉琮束手，今水軍八十萬眾，方與將軍會獵於吳。","sortOrder":14},
  {"id":"s_work_nvlt_66_15","chapterId":"ch_work_nvlt_66","text":"王隱《晉書》曰：魏舒少工射，著韦衣，入山泽，每獵大獲。","sortOrder":15},
  {"id":"s_work_nvlt_66_16","chapterId":"ch_work_nvlt_66","text":"《世說》曰：孫盛為庾公記室參軍，從獵，將其第三兒齊莊俱行，庾公不知，忽於獵場見莊，時年七八歲，庾公謂曰：君兒亦复來乎，應聲答曰：所謂無小無大，從公於邁。","sortOrder":16},
  {"id":"s_work_nvlt_66_17","chapterId":"ch_work_nvlt_66","text":"吳地記曰：長洲在姑蘇南，太湖北岸，阖闾所遊獵處也，吳先主使徐詳至魏，魏太祖謂詳曰：孤原越橫江之津，與孫將軍遊姑蘇之上，獵長洲之苑，吾志足矣。","sortOrder":17},
  {"id":"s_work_nvlt_66_18","chapterId":"ch_work_nvlt_66","text":"【詩】周王褒和張侍中看獵詩曰：上林冬狩反，回中講射歸，還登宣曲觀，更獵黃山围，嚴冬桑柘惨，寒霜馬騎肥，緤盧隨兔起，高鷹接雉飛，獨嗟來遠客，辛苦倦邊衣。","sortOrder":18},
  {"id":"s_work_nvlt_66_19","chapterId":"ch_work_nvlt_66","text":"陳張正見和諸葛覽從軍遊詩曰：治兵耀武節，縱獵駭畿封，迅鹢馳千里，高罝起百重，騰｛鹿加｝毙馬足，飢鼯落劍鋒，雲根飛燒火，鳥道絕禽蹤，方羅四海俊，聊以習軍容。","sortOrder":19},
  {"id":"s_work_nvlt_66_20","chapterId":"ch_work_nvlt_66","text":"【賦】漢司馬相如子虛上林賦曰：楚使子虛使於齊，齊王悉發境內之士，備車騎之眾，與使者出田，田罢，子虛過詫乌有先生，而亡是公存焉，先生曰：今日田樂乎，子虛曰：樂，獲多乎，曰：少，然則何樂，曰：仆樂王之欲夸仆以車騎之眾，而仆答以雲夢之事，曰：可得聞乎，子虛曰：可，王駕車千乘，選徒萬騎，田於海濱，列卒滿泽，罘網弥山，掩兔辚鹿，射麋腳驎，骛於鹽浦，割鮮染輪，射中獲多，矜而自功，顧謂仆曰：楚王之獵，孰與寡人，仆對曰：臣聞楚有七泽，嘗睹其一，未見其餘也，臣之所見，蓋特小小者耳，名曰雲夢，雲夢者，方九百里，其中有山焉，其山則盤紆岪鬱，岑崟參差，日月蔽虧，交错糾紛，上幹青雲，其東則有蕙圃蘅蘭，茝若射幹，芎藭菖蒲，茳蓠{艹糜}芜，其高燥則生箴菥苞荔，薜莎青薠。其卑濕則生藏莨蒹葭，東牆彫胡，其西則有涌泉清池，激水推移，外發芙蓉菱華，內隱巨石白沙，其北則有陰林巨树，楩柟豫章，桂椒木蘭，檗離朱楊，其上則有鵷雏孔鸞，騰遠射幹，楚王乃駕馴驳之驷，乘雕玉之舆，靡魚須之桡旃，曳明月之珠旗，陽子驂乘，奷阿為御，按節未舒，即凌狡獸，蹴蛩蛩，辚駏驉，軼野馬，湜騊駼，乘遺風，射遊騏，射不虛發，中必决眦，洞焜達腋絕乎心系，於是鄭女曼姬，被阿緆，投纻縞，雜纖羅，垂霧縠，飛襳垂髾，扶舆倚靡，错翡翠之葳蕤。缪繞玉綏，眇眇忽忽，若神仙之仿佛，於是乃相與獠於蕙圃，掩翡翠，射鵕鸃，怠而後發，遊於清池，浮文鹢，扬旌枻，張翠帷，建羽蓋，網玳瑁，鉤紫貝，摐金鼓，吹鳴籁，榜人歌，聲流喝，涌泉起，奔物［漢書司馬相如傳，文選七作扬。］會，磊石相击，蛇良蛇良潏潏，若雷霆之聲，聞乎數百里之外，於是楚王登陽雲之台，泊乎無為，澹乎自持，不若大王，終日馳騁，曾不下舆，臣竊觀之，齊殆不如，乌有先生曰：是何言之過也，且齊東渚巨海，南有琅邪，觀乎成山，射乎之罘，浮渤澥，遊孟諸，邪與肅慎為鄰，右以湯穀為界，秋田乎青丘，傍偟乎海外，吞若雲夢者八九，於其焜中，曾不蒂芥，然在諸侯之位，不敢言遊戲之樂，苑囿之大，先生又見客，是以王詞不复，何為亡以應哉。","sortOrder":20},
  {"id":"s_work_nvlt_66_21","chapterId":"ch_work_nvlt_66","text":"上林賦，亡是公子［子字衍。］聽然而笑曰：楚則失矣，而齊亦未為得也，且齊楚之事。又焉足道乎，君未睹夫巨麗也，獨不聞乎天子之上林乎，左蒼梧，右西極，丹水更其南，紫淵径其北，終始灞浐，出入涇渭，沣鎬潦潏，紆徐逶迤，經營乎其內，荡荡乎八川，分流相背而異態，於是乎蛟龍赤螭，〈魚亘〉亸漸離，鰅騄鰬魠，禺禺魼鳎，揵鬐掉尾，振鱗奋翼，潛處乎深巖，明月珠子，的皪江靡，蜀石黃碝，水玉磊砢，鸿鷫鵠鴇，鴐鹅禜鳿，沉浮乎其上，沈淫汎濫，隨風澹澹，與波搖荡，掩薄水渚，深林巨木，巉巖參差，九嵕〈山截〉嶭，南山峨峨，掩以绿蕙，被以茳蓠，糅以蘪芜，雜以留夷，布結縷，攒{艹戾}莎，揭車蘅蘭，本射幹，茈薑蘘荷，箴橙若荪，鮮支黃砾，蒋芋青薠，布護閎泽，延蔓太原，於是離宮別馆，弥山跨穀，高廊四註，重坐曲閣，華榱璧璫，輦道逦屬，步朓周流，長途中宿，俯杳眇而亡見，仰攀緣而扪天，奔星更於閨闼，冤虹杝於楯軒，於是乎盧橘夏熟，黃甘橙榛，枇杷橪柿，樗棗楊梅，櫻桃蒲陶，隱夫鬱棣，扬翠葉，抗紫茎，發紅華，秀朱榮，煌煌扈扈，燭燿巨野，背秋涉冬，天子校獵，乘鏤象，六玉虬，扡蜺旌，靡雲旗，前皮軒，後道遊，孫叔奉辔，衛公驂乘，江河為阹，太山為橹，車騎雷起，殷天動地，生貔豹，摶豺狼，手熊羆，足野羊，箭不苟害，解脰陷腦，弓不虛發，應聲而倒，然後侵淫促節，倏敻遠去，流離輕禽，蹴履狡獸，擇肉後發，先中命處，拂鹥鳥，捎鳳皇，捷鴛雏，掩鹪鵬，蹶石關，歷封峦，過鳷鵲，望露寒，下棠梨，息宜春，西馳宣曲，濯鹢牛首，登龍台，掩細柳，於是遊戲懈怠，置酒乎顥天之台，張樂乎膠葛之宇，撞千石之鍾，立萬石之虡，建翠華之旗，树靈鼍之鼓，奏陶唐氏之舞，聽葛天氏之歌，千人唱，萬人和，巴俞宋蔡，淮南千遮，文成顛歌，族居遞奏，金鼓迭起，铿鎗闛鞳，洞心駭耳，荆吳鄭衛之聲，韶濩武象之樂，陰淫移衍之音，鄢郢繽紛，激楚結風，若夫青琴宓妃之徒，絕殊離俗，妖冶閒都，靓妆刻飾，妩媚奷弱，皓齒燦烂，宜笑的皪，色授魂與，心愉於侧，酒中樂酣，天子曰：嗟乎此太奢侈，於是歷吉日以斋戒，袭朝衣，乘法駕，建華旗，鳴玉鸞，遊於六藝之囿，馳骛仁義之途，脩容乎禮園，翱翔乎書圃。","sortOrder":21},
  {"id":"s_work_nvlt_66_22","chapterId":"ch_work_nvlt_66","text":"漢楊雄羽獵賦曰：武帝廣开上林，東南至宜春鼎湖，御宿崑吾，傍南山，西至長楊五柞，北繞黃山，濱渭而東，周袤數百里，聊因校獵以風，玄冬季月，天地隆冽，乃詔虞人典泽，東延崑鄰，西馳閶阖，储積共偫，戎卒夹道，斬丛棘，夷野草，御自汧渭，經營酆鎬，營合围會，先置乎長楊之南，崑明靈沼之東，荷垂天之罼，張竟埜之罘，靡日月之朱竿，曳彗星之飛旗，涣若天星之羅，浩如涛水之波，淫淫與與，前後要遮，立歷天之旗，曳梢星之旃，霹靂列缺，吐火施鞭，車騎雲會，登降闇藹，泰華為旗，熊耳為缀，木仆山還，漫若天外，於是鳥不及飛，獸不得過，軍驚師駭，刮野扫地，禽殫中衰，相與集於靖冥之馆，以臨珍池，灌以岐梁，溢以江河，東瞰目盡，西畅亡涯，隨珠［《文選》珠下有和字，此脱。］氏，焯烁其波，方椎夜光之流離，剖明月之珠胎，於茲乎鸿生巨儒，修唐典，匡雅頌，揖讓於前，昭光振耀，响忽如神，仁聲惠於北狄，武誼動於南鄰。","sortOrder":22},
  {"id":"s_work_nvlt_66_23","chapterId":"ch_work_nvlt_66","text":"後漢張衡羽獵賦曰：皇上感天威之缪烈，思太昊之觀虞，虞人表林麓而廓菜藪，翦荆梓而夷榛株，於是鳳皇獻歷，太仆駕具，蚩尤先驅，雨師清路，山靈護陣，方神跸御，羲和奉辔，弭節西征，翠蓋葳蕤，鸞鳴蹐蛇令，山穀為之澹淡，丘陵為之簸傾，於是皇舆綢缪，遷延容與，抗天津於伊洛，敻遙集乎南圃，大詔獵者，竟逐長驅，輕車飆厲，羽騎電骛，霧合雲集，波流雨註，馬蹂麋鹿，輪辚雉兔，弓不妄弯，弩不虛舉，鳥驚絓羅，獸與矢遇。","sortOrder":23},
  {"id":"s_work_nvlt_66_24","chapterId":"ch_work_nvlt_66","text":"魏文帝校獵賦曰：長鎩糾霓，飛旗拂天，部曲按列，什伍相連，跱如丛林，動若崩山，超崇岸之曾崖，厲障澨之双川，列翠星陳，戎車方轂，風回雲轉，埃連飆屬，雷响震天地，譟聲荡川嶽，遂躪封豨，籍麈鹿，梢飛鳶，接鸑鷟，聚者成丘陵，散者闐溪穀，流血赫其丹野，羽毛紛其翳日，考功效績，班賜有叙，授甘炰，［句有脱文。］飛酌清酤，割鮮野享，舉爵鳴鼓，鑾舆促節，騁辔回翔，望爵台而增舉，涉幽巉之花梁。","sortOrder":24},
  {"id":"s_work_nvlt_66_25","chapterId":"ch_work_nvlt_66","text":"魏王粲羽獵賦曰：相公乃乘輕軒，駕四辂，駙流星，屬繁弱，選徒命士，鹹與竭作，旌旗雲桡，鋒刃林错，扬暉吐火，曜野蔽泽，山川於是搖荡，草木為之摧拨，禽獸振駭，魂亡氣奪，興頭觸系，搖足遇橽，陷心裂胃，潰腦破顙，鷹犬競逐，弈弈霏霏，下韝窮緤，摶肉噬肌，墜者若抵，清野涤原，莫不殲夷。","sortOrder":25},
  {"id":"s_work_nvlt_66_26","chapterId":"ch_work_nvlt_66","text":"魏應玚西狩賦曰：伊炎漢之建安，飛龍耀乎天衢，皇宰弈而陶運，树匡翼而大摹，荡無妄之氛秽，扬威靈乎八區，开九土之舊跡，暨聲教於海隅，時霜凄而淹野，寒風肅而川逝，草木紛而搖荡，鷙鳥別而高厲，既乃揀吉日，練嘉辰，清風矢戒，屏翳收尘，於是魏公乃乘彫辂，驷飛黃，擁箫鉦，建九，［句有脱文。］按辔清途，飒沓風翔，於是围網周合，雷鼓天震，千乘長羅，萬表星陳，双翼伉旌，八校祖分，長燧電舉，高煙蔽雲，爾乃徒舆併興，方軌連质，驚飆四駭，冲禽驚溢，騁獸塞野，飛鳥蔽日，爾乃赴玄穀，陵崇峦，俯掣奔猴，仰捷飛猿，雲幕被於廣野，京燎照乎平原，醴炰充給，洪施普宣。","sortOrder":26},
  {"id":"s_work_nvlt_66_27","chapterId":"ch_work_nvlt_66","text":"又馳射賦曰：於是陽春嘉日，講肆餘暇，將逍遙於郊野，聊娱遊於騁射，延賓鞠旅，星言夙駕，树應鞞於路左，建丹旗於表路，群駿籠於衡首，鹹皆騕褭與飛葂。爾乃結翻仵，齊倫匹，良樂授馬，孫臏調驷，筹筭克明，班次均壹，左攬繁弱。右接湛衛，控滿流睇，應絃飛碎，旝動鼓震，譟聲雷潰，重破累〈石暴〉，流景倏忽，紛紜絡驿，次授二八，驊骝激騁，神足奔越，終節三驅，矢不虛發，進截飛乌，顧摧月支，須紆六鈞，口弯七規，觀者併氣而傾竦，鹹侧仚{人山}而騰移，爾乃萦回盤厲，按節和旋，翩翩神厲，體若飛仙，弈弈骍牡，既佶且閒，扬驪沛艾，蠖略相連。","sortOrder":27},
  {"id":"s_work_nvlt_66_28","chapterId":"ch_work_nvlt_66","text":"晉夏侯湛獵兔賦曰：爾乃乘露箱，御良馬，循又接於廣漠，弓矢連於曠野，端眺蒿萊，摘盱榛秽，落目攒慨，傍窥蓊薈，视毚兔之所隱，乃精望而審發，絃絕箭激，驚伏併毙，搜鱗危险，觅歷岡阜，留罾掛於重林，疏罝結於通藪，密驚视於草間，暫見之於蒙，［句有脱文。］擬以銳殳，規以良弓，睹毫末而放鏃，乃殪之於窟中，或紛欻{艹亦}以驚骛，影跳竦而扬白，擢輕足之茕茕，振遊形之躍躍，弓不暇弯，罝不及幕，爾乃鷹鷂翻以飄扬，劲翼謖而下猘，馬釋椌以長騁，鬱騰虛而陵厲，翕習於回阻之間，繞缭於山泽之际，盤迂遊田，其樂泄泄，心既倦兮日遷，命舆駕兮將還，息徒蘭圃，秣骥華田，目送歸波，手揮五絃，優哉遊哉，聊以永年。","sortOrder":28},
  {"id":"s_work_nvlt_66_29","chapterId":"ch_work_nvlt_66","text":"晉潘嶽射雉賦曰：涉青林以遊覽，樂羽族之群飛，伟彩毛之英麗，有五色之名翚，厲耿介之专心，張猛毅之雄姿，於時青陽告謝，朱明肇授，靡木弗滋，無草不茂，天英英以垂雲，泉涓涓而吐霤，麥漸漸以擢芒，雉鷕鷕而朝雊，鬱軒翥以餘怒，思長鳴以效態，爾乃俟扇舉而清叫，野聞聲而應媒，樆朱冠之赩{艹亦}，敷藻翰之陪鰓，或蹶或啄，時行時止，班尾扬翘，双魚特起，應叱愕立，擢身竦待，捧黃間以密彀，屬刚掛以潛擬，山鷩悍害，猋迅以甚，鯨牙低鏃，心平望審，毛體摧落，霍若碎錦，逸群之俊，擅場挟兩，櫟雌妒異，倏來忽往，於是筭分銖，商遠近，揆懸刀，騁絕伎，當咮值焜，裂素破觜，若乃耽盤遊道，放心不移，樂而無節。端操或虧，此老氏之所戒，而君子所不為。","sortOrder":29},
  {"id":"s_work_nvlt_66_30","chapterId":"ch_work_nvlt_66","text":"【啟】梁沈約為皇太子謝賜御所射雉啟曰：輕鑾微動，密翳徐張，黃間所彀。矢無虛發，南皮之獲，未足稱工，臣任惟守器，事隔陪奉，天慈曲降，賜物頒禽。","sortOrder":30},
  {"id":"s_work_nvlt_66_32","chapterId":"ch_work_nvlt_66","text":"《呂氏春秋》曰：太公釣於滋泉，文王得而王。","sortOrder":32},
  {"id":"s_work_nvlt_66_33","chapterId":"ch_work_nvlt_66","text":"《說苑》曰：呂望年七十，釣於渭渚，三日三夜，魚無食者，與農人言，農人者，古之老賢人也，謂望曰：子將复釣，必細其纶，芳其餌，徐徐而投之，無令魚駭，望如其言，初下得鲋，次得鯉，刳腹得書，書文曰：呂望封於齊，望知當貴。","sortOrder":33},
  {"id":"s_work_nvlt_66_34","chapterId":"ch_work_nvlt_66","text":"《毛詩》曰：其釣維何，維絲伊缗，齊侯之子，平王之孫。","sortOrder":34},
  {"id":"s_work_nvlt_66_35","chapterId":"ch_work_nvlt_66","text":"《論語》曰：釣而不綱，弋不射宿。","sortOrder":35},
  {"id":"s_work_nvlt_66_36","chapterId":"ch_work_nvlt_66","text":"《墨子》曰：釣者之恭，非為魚也，餌鼠以肉，非愛之也。","sortOrder":36},
  {"id":"s_work_nvlt_66_37","chapterId":"ch_work_nvlt_66","text":"《楚辭》曰：以直針而為鉤，維河魚之能得。","sortOrder":37},
  {"id":"s_work_nvlt_66_38","chapterId":"ch_work_nvlt_66","text":"《呂氏春秋》曰：善釣者，引魚於千仞之下，餌香也。","sortOrder":38},
  {"id":"s_work_nvlt_66_39","chapterId":"ch_work_nvlt_66","text":"【詩】陳陰铿觀釣詩曰：澄江息晚浪，釣侣枻輕舟，垂絲遙溅水，沧浪終滯遊。","sortOrder":39},
  {"id":"s_work_nvlt_66_40","chapterId":"ch_work_nvlt_66","text":"【賦】晉潘尼釣賦曰：抗餘志於浮雲，樂餘身於蓬庐，尋渭濱之遠跡，且遊釣以自娱，左援脩竹，右縱飛纶，金鉤厲鉅，甘餌垂芬，眾鯤奔涌，遊鱗橫集，觸餌見擒，值鉤被執，長繳繽紛，輕竿翕熠，雲往飆馳，光飛電入，曜靈未及驚策，蓋以獲其數十，且夫燔炙之鮮，煎熬之味，百品千变，殊芳異氣，隨心適好，不可勝記，乃命宰夫，脍此潛鱗，電割星流，芒散縷解，隨風離鍔，連翩雪累，西戎之蒜，南夷之薑，酸鹹調適，齊和有方，和神安體，易思難忘。","sortOrder":40},
  {"id":"s_work_nvlt_66_42","chapterId":"ch_work_nvlt_66","text":"《漢書》曰：凡贽，［《太平御覽》八百三十五作货。］金錢布泉之用，夏殷以前，其詳靡記，太公為周立九府圓法，［圓即錢也。］","sortOrder":42},
  {"id":"s_work_nvlt_66_43","chapterId":"ch_work_nvlt_66","text":"《六韜》曰：武王入殷，散鹿台之金錢，以與殷民。","sortOrder":43},
  {"id":"s_work_nvlt_66_44","chapterId":"ch_work_nvlt_66","text":"《史記》曰：初蘇秦之燕，貸百錢為資，及貴，以百金偿之，遍報諸所嘗見德者，其從者一人，獨未得報，乃前自言，蘇秦曰：我非忘子，子之與我至燕，再三欲去我易水之上，方是時我困，故望子深，是以後子，子今亦得矣。","sortOrder":44},
  {"id":"s_work_nvlt_66_45","chapterId":"ch_work_nvlt_66","text":"又曰：高祖以吏繇鹹陽，吏皆送奉錢三，［或三百，或五百。］萧何獨以五，侯［《太平御覽》八百三十五作後。］益封二千戶，以獨贏二錢。","sortOrder":45},
  {"id":"s_work_nvlt_66_46","chapterId":"ch_work_nvlt_66","text":"又曰：单父人呂公，善沛令，避仇從之客，因家焉，沛中豪杰吏，聞令有客，皆往贺，萧何為主吏，主進，令諸大夫曰：不滿千錢，坐之堂下，高祖為亭長，素易諸吏，乃绐為謁者曰：贺錢萬，實不持一錢，謁入，呂公大驚，起迎之門。呂公者，好相人，見高祖状貌，因重敬之，引入座，萧何曰：劉季故多大言者矣。","sortOrder":46},
  {"id":"s_work_nvlt_66_47","chapterId":"ch_work_nvlt_66","text":"又曰：上使善相者相邓通，曰：當貧饿死，文帝曰：能富通者在我，何謂貧，於是賜通蜀嚴道銅山，得自鑄錢，號邓氏錢，布天下，［見寵幸篇。］","sortOrder":47},
  {"id":"s_work_nvlt_66_48","chapterId":"ch_work_nvlt_66","text":"又曰：漢興七十餘年之間，國家無事，廪庾皆滿，而库府餘货财，京師之錢，累百巨萬，貫朽而不可校。","sortOrder":48},
  {"id":"s_work_nvlt_66_49","chapterId":"ch_work_nvlt_66","text":"又曰：安息國以銀為錢，錢如王面。","sortOrder":49},
  {"id":"s_work_nvlt_66_50","chapterId":"ch_work_nvlt_66","text":"《漢書》曰：武帝時，公卿請令京師鑄官錢，赤仄，［以赤銅為其郛。］一當五，官用非赤仄，不得行，［俗所謂紫绀錢。］","sortOrder":50},
  {"id":"s_work_nvlt_66_51","chapterId":"ch_work_nvlt_66","text":"又曰：東方朔雲，侏儒長三尺餘，奉一囊粟，錢二百三十，臣朔長九尺餘，亦一囊粟，錢二百四十。","sortOrder":51},
  {"id":"s_work_nvlt_66_52","chapterId":"ch_work_nvlt_66","text":"又曰：張安世父子封侯，在位太盛，乃辭不受祿，詔都內別藏張氏無名錢，以百萬數，［都安(《太平御覽》八百三十五作內。)主藏官。］","sortOrder":52},
  {"id":"s_work_nvlt_66_53","chapterId":"ch_work_nvlt_66","text":"《東觀漢記》曰：光祿勋杜林，與馬援乡里親厚，援南方還時，林馬適死，援遣子持一匹馬遺林，曰：朋友有車之饋，可以修［《太平御覽》八百三十五作備。］之，居數月，林遣子奉書曰：將軍內施九族，外有賓客，望恩者多，林父子食祿，祿出常有盈，今奉錢五萬，援受之，謂兒曰：當以此為法，林所以勝我者也。","sortOrder":53},
  {"id":"s_work_nvlt_66_54","chapterId":"ch_work_nvlt_66","text":"又曰：馬援在隴西，上書曰：富民之本，在於食货，宜如舊鑄五銖錢，天下賴其便。","sortOrder":54},
  {"id":"s_work_nvlt_66_55","chapterId":"ch_work_nvlt_66","text":"又曰：鄭均兄為縣遊击，受禮遺，均數諫止，不聽，即脱身出作，歲餘，得數萬錢，歸以與兄，曰：錢盡可复得，為吏坐贓，終身捐弃，兄感其語，遂有廉絜稱。","sortOrder":55},
  {"id":"s_work_nvlt_66_56","chapterId":"ch_work_nvlt_66","text":"《汝南先賢傳》曰：平舆阚敞，為郡五官掾，太守弟五常被徵，以奉錢百三十萬寄敞，敞埋置堂上，後常舉家患死，唯有孤孫九歲，臨死語雲，吾有錢三十萬，寄掾阚敞，孫長大來求敞，敞見之悲喜，取錢盡還之，孫曰：祖唯言三十萬爾，今乃百三十萬，誠不敢當，敞曰：府君疾困，谬言爾，郎君無疑。","sortOrder":56},
  {"id":"s_work_nvlt_66_57","chapterId":"ch_work_nvlt_66","text":"《郭子》曰：王夷甫雅尚玄遠。又疾其婦貪，口未嘗言錢，婦欲试之，夜令婢以錢繞床，不得行，夷甫晨起，見錢閡之，命婢舉阿堵物。","sortOrder":57},
  {"id":"s_work_nvlt_66_58","chapterId":"ch_work_nvlt_66","text":"《世說》曰：王武子移第近北芒，於時人多地貴，武子好馬射，買地作埒，編錢布地竟埒，時號金溝。","sortOrder":58},
  {"id":"s_work_nvlt_66_59","chapterId":"ch_work_nvlt_66","text":"《地鏡圖》曰：錢銅之氣，望之如青雲。","sortOrder":59},
  {"id":"s_work_nvlt_66_60","chapterId":"ch_work_nvlt_66","text":"【書】後漢劉騊駼上書諫鑄錢事曰：夫食者乃有國之大寶，生民之至貴也，見比年以來，良苗盡於蝗螟之口，杼柚空於公私之求，野無青草，室如懸磬，所急朝夕之餐，所患靡盬之事，豈謂錢之鍥薄，銖兩輕重哉，就使當令土砾化為南金，瓦滷变為和玉，沙石悉成隨珠，犬羊盡作狐白，絳繡盈堂，文綺缦野，使百姓渴無所飲，飢無所食，雖犧皇之純德，大禹之勤勞，周文之不暇，猶不能以保萧牆之內。","sortOrder":60},
  {"id":"s_work_nvlt_66_61","chapterId":"ch_work_nvlt_66","text":"【啟】梁簡文帝謝敕賜解講錢啟曰：無勞磁石之火，金货猥臻，非遊玉壘之川，銅山可見，舒王濟之埒，猶覺有餘，假劉寔之繩，穿而不盡，慧輪究竟，爰降曲私，福田成滿，仰由慈被，榮光獨照，自均若木，負恩知重，竊譬蓬萊。","sortOrder":61},
  {"id":"s_work_nvlt_66_62","chapterId":"ch_work_nvlt_66","text":"又謝賜錢啟曰：殊泽隆厚，造次被蒙，重彼八銖，珍斯九法，赤仄成采，出自水衡之藏，绀文委貫，忽積銅扇之里，謹長充放生，用濟含識，發弘誓原，等供無邊，效彼薄拘，均茲流水，方使怖鴿獲安，窮魚永樂。","sortOrder":62},
  {"id":"s_work_nvlt_66_63","chapterId":"ch_work_nvlt_66","text":"梁劉孝威婚謝晉安王賜錢啟曰：孝威問吉已通，請期有日，而賢夫之譽，多愧張耳，非婿之才，偶同王粲，睠言前事，良以自羞，曲降隆慈，俯垂珍錫，便使禽贽獲舉，纁幣有資，佩服寵靈，殒越非報。","sortOrder":63},
  {"id":"s_work_nvlt_66_64","chapterId":"ch_work_nvlt_66","text":"梁任孝恭謝赉錢治宅啟曰：繩枢斷續，薄雨已傾，席戶穿阑，微風自卷，不悟恩隆問舍，降自天造，事深更宅，乃被庸微，跪條可授，毀垣再筑，遂得窗臨上路，戶望東家，人悅爽垲，里驚輪奐，門學於公，逆容驷馬，巷均王濬，豫擬幡旗。","sortOrder":64},
  {"id":"s_work_nvlt_66_65","chapterId":"ch_work_nvlt_66","text":"【論】晉魯褒錢神論曰：有司空公子，富貴不齒，盛服而遊京邑，駐駕乎市里，顧見綦毌先生，班白而徒行，公子曰：嘻，子年已長矣，徒行空手，將何之乎，先生曰：欲之貴人，公子曰：學詩乎，曰：學矣，學禮乎，曰：學矣，學易乎，曰：學矣，公子曰：詩不雲乎，幣帛筐篚，以將其厚意，然後忠臣嘉賓，得盡其心，禮不雲乎，男贽玉帛禽鳥，女贽榛栗棗脩，易不雲乎，隨時之義大矣哉，吾视子所以，觀子所由，豈隨世哉，雖曰已學，吾必謂之未也，先生曰：吾將以清談為筐篚，以機神為幣帛，所謂禮雲禮雲，玉帛雲乎哉者已，公子拊髀大笑曰：固哉子之雲也，既不知古。又不知今，當今之急，何用清談，時易世变，古今異俗，富者榮貴，貧者賤辱，而子尚质，而子守實，無異於遺劍刻舡，膠柱調瑟，貧不離於身名，譽不出乎家室，固其宜也，昔神農氏没，黃帝尧舜，教民農桑，以幣帛為本，上智先學变通之，乃掘銅山，俯视仰觀，鑄而為錢，故使內方象地，外員象天，錢之為體，有乾有坤，其積如山，其流如川，動靜有時，行藏有節，市井便易，不患耗折，難朽象寿，不匮象道，故能長久，為世神寶，親愛如兄，字曰孔方，失之則貧弱，得之則富強，無翼而飛，無足而走，解嚴毅之顏，开難發之口，錢多者處前，錢少者居後，詩雲，哿矣富人，哀哉茕獨，豈是之謂乎，錢之為言泉也，百姓日用，其源不匮，無遠不往，無深不至，京邑衣冠，疲勞講肆，厭聞清談，對之睡寐，見我家兄，莫不驚视，錢之所祐，吉無不利，何必讀書，然後富貴，由是論之，可謂神物，無位而尊，無势而熱，排朱門，入紫闼，錢之所在，危可使安，死可使活，錢之所去，貴可使賤，生可使殺，是故忿諍辯訟，非錢不勝，孤弱幽滯，非錢不拔，怨仇嫌恨，非錢不解，令問笑談，非錢不發，諺曰：錢無耳，可闇使，豈虛也哉。","sortOrder":65},
  {"id":"s_work_nvlt_66_66","chapterId":"ch_work_nvlt_66","text":"又曰：有錢可使鬼，而况於人乎，子夏雲，死生有命，富貴在天，吾以死生無命，富貴在錢，何以明之，錢能轉禍為福，因败為成，危者得安，死者得生，性命長短，相祿貴賤，皆在乎錢，天何與焉，天有所短，錢有所長，四時行焉，百物生焉，錢不如天，達窮开塞，振貧濟乏，天不如錢，若臧武仲之智，卞莊子之勇，冉求之藝，文之以成人矣，今之成人者何必然，唯孔方而已，夫錢窮者使通達，富者能使溫暖，貧者能使勇悍，故曰：君無财則士不來，君無賞則士不往，諺曰：官無中人，不如歸田，雖有中人，而無家兄，何異無足而欲行，無翼而欲翔，使才如顏子，容如子張，空手掉臂，何所希望，不如早歸，廣修農商，舟車上下，役使孔方，凡百君子，同尘和光，上交下接，名譽益彰。","sortOrder":66},
  {"id":"s_work_nvlt_66_67","chapterId":"ch_work_nvlt_66","text":"《藝文類聚》　唐·欧陽詢","sortOrder":67},
  {"id":"s_work_nvlt_67_1","chapterId":"ch_work_nvlt_67","text":"卷六十七衣冠部","sortOrder":1},
  {"id":"s_work_nvlt_67_2","chapterId":"ch_work_nvlt_67","text":"○衣冠貂蝉玦珮巾帽衣裳袍裙襦裘帶","sortOrder":2},
  {"id":"s_work_nvlt_67_3","chapterId":"ch_work_nvlt_67","text":"◇衣冠","sortOrder":3},
  {"id":"s_work_nvlt_67_4","chapterId":"ch_work_nvlt_67","text":"《墨子》曰：昔齊桓公，高冠博帶，以治其國，楚莊王鮮冠組纓，絳衣博袍，以治其國。","sortOrder":4},
  {"id":"s_work_nvlt_67_5","chapterId":"ch_work_nvlt_67","text":"《莊子》曰：曾子居衛，正冠而纓絕，斂襟而肘見。","sortOrder":5},
  {"id":"s_work_nvlt_67_6","chapterId":"ch_work_nvlt_67","text":"《楚辭》曰：餘幼好此奇服兮，年既老而不衰，帶長鋏之陆離兮，冠青雲之崔嵬。","sortOrder":6},
  {"id":"s_work_nvlt_67_7","chapterId":"ch_work_nvlt_67","text":"《漢書》曰：終軍上書，請受大冠長纓，以羁南越王而致之闕下，乃使越王，越王請舉國內屬。","sortOrder":7},
  {"id":"s_work_nvlt_67_8","chapterId":"ch_work_nvlt_67","text":"又曰：秦獄法吏，冠柱後惠文冠，及張敞弟武為梁相，敞遣使送之曰：何以治梁，武曰：馭黠馬，利其冲［《初學記》二十六，《太平御覽》六百八十五作衔。］策，當以柱後惠文蝉［御覽作彈。］治之爾，［惠，蝉也，冠細如蝉翅，今御史冠。］","sortOrder":8},
  {"id":"s_work_nvlt_67_9","chapterId":"ch_work_nvlt_67","text":"劉向別錄曰：鶡冠子常居深山，以鶡為冠，故號鶡冠子。","sortOrder":9},
  {"id":"s_work_nvlt_67_10","chapterId":"ch_work_nvlt_67","text":"《漢武內傳》曰：上元夫人，戴九星靈芝夜光之冠。","sortOrder":10},
  {"id":"s_work_nvlt_67_11","chapterId":"ch_work_nvlt_67","text":"胡廣說曰：趙武靈王效胡服，以璫飾首，前搖貂尾，秦滅趙，以其君冠賜近臣，建武時，匈奴內屬，世祖賜南单於常侍惠文冠。","sortOrder":11},
  {"id":"s_work_nvlt_67_12","chapterId":"ch_work_nvlt_67","text":"《東觀漢記》曰：楊賜患罢，居無何，拜太常，詔賜所服冠帻綬帶。","sortOrder":12},
  {"id":"s_work_nvlt_67_13","chapterId":"ch_work_nvlt_67","text":"又曰：武冠俗謂之大冠。","sortOrder":13},
  {"id":"s_work_nvlt_67_14","chapterId":"ch_work_nvlt_67","text":"【詩】晉陆機赠潘正叔詩曰：過蒙時來運，與爾遊承華，執笏崇賢內，振纓曾城阿。","sortOrder":14},
  {"id":"s_work_nvlt_67_15","chapterId":"ch_work_nvlt_67","text":"晉郭璞詩曰：杞梓生南荆，奇才應世出，擢穎蓋漢陽，鸿聲駭皇室，遂應四科運，朱衣耀玉质。","sortOrder":15},
  {"id":"s_work_nvlt_67_16","chapterId":"ch_work_nvlt_67","text":"【表】魏武帝讓還司空印綬表曰：臣文非師尹之佐，武非折冲之任，遭天之幸，幹竊重授，內踵伯禽司空之職，外承呂尚膺扬之事，斗筲處之，民其瞻觀，水土不平，奸宄未靜，臣常媿辱，忧為國累，臣無智勇，以助萬一，夙夜慚懼，若集冰火，未知何地，可以陨越。","sortOrder":16},
  {"id":"s_work_nvlt_67_17","chapterId":"ch_work_nvlt_67","text":"梁江淹為齊王謝冕旒諸法服表曰：軒冕雲跸，既非常之飾，宮懸玉戚，乃配天之禮，昔大啟營丘，未脩树羽之賞，光宅曲阜，始兼龍旂之貴，况臣道狹慶隆，身薄器尊，粉繡爭暉，藻火競曜。","sortOrder":17},
  {"id":"s_work_nvlt_67_18","chapterId":"ch_work_nvlt_67","text":"【啟】梁陆倕為息缵謝敕賜朝服啟曰：玄冕素帶，出自禁财，朱绂青緺，降於皇府，辉燭鄰党，震耀街衢，姻族移聽，朋儕改矚，非臣璅弱，所能陳報。","sortOrder":18},
  {"id":"s_work_nvlt_67_19","chapterId":"ch_work_nvlt_67","text":"◇貂蝉","sortOrder":19},
  {"id":"s_work_nvlt_67_20","chapterId":"ch_work_nvlt_67","text":"應劭《漢官儀》曰：侍中左蝉右貂，金取堅刚，百陶不耗，蝉居高食絜，目在腋下，豹內劲悍而外溫润。","sortOrder":20},
  {"id":"s_work_nvlt_67_21","chapterId":"ch_work_nvlt_67","text":"【賦】隋江總華貂賦曰：領軍新安殿下，以副貂乘錫，仰銘恩泽，謹題小賦，貴丰貂於挹娄，飾惠文而見求，標侍臣之密設，曜毛彩之溫柔，拜文〈媲\"女改木\"〉而影度，陪武帳而香浮，隨玉珩之近遠，共金璫之去留，仰太山之千仞，开穀中之鄙吝，撤君子之寶飾，榮小人之蓬鬢，蔑置醴之殊私，夸賜田之薄润，顧朽拙之微躬，早遊藝而不工，逢河間之好古，自隗始而恩隆，谅維鹈之有媿，庶懷音而克終。","sortOrder":21},
  {"id":"s_work_nvlt_67_22","chapterId":"ch_work_nvlt_67","text":"【啟】梁元帝謝東宮赉貂蝉啟曰：挹娄之毳，曲降鸿恩，麗水之珍，复蒙殊奖，東平紫貂之賜，非聞暖嵒，中山黃金之賜，豈曰附蝉，坐变仲宣之容，增暉允南之貌。","sortOrder":22},
  {"id":"s_work_nvlt_67_23","chapterId":"ch_work_nvlt_67","text":"◇玦珮","sortOrder":23},
  {"id":"s_work_nvlt_67_24","chapterId":"ch_work_nvlt_67","text":"《世本》曰：舜時，西王母獻白環及玦。","sortOrder":24},
  {"id":"s_work_nvlt_67_25","chapterId":"ch_work_nvlt_67","text":"《楚辭》曰：損［《初學記》二十六作捐。］餘玦兮江中，遺予珮兮澧浦。","sortOrder":25},
  {"id":"s_work_nvlt_67_26","chapterId":"ch_work_nvlt_67","text":"又曰：虛［《太平御覽》六百九十二作雲。］衣兮披披，玉珮兮陆離。","sortOrder":26},
  {"id":"s_work_nvlt_67_27","chapterId":"ch_work_nvlt_67","text":"《孔丛子》曰：子產死，鄭人丈夫舍玦珮，婦人舍珠玉。","sortOrder":27},
  {"id":"s_work_nvlt_67_28","chapterId":"ch_work_nvlt_67","text":"《說苑》曰：經侯過魏太子，左帶玉具劍，右帶環珮，左光照右，右光照左，太子不视。又不問，經侯曰：魏國亦有寶乎，太子曰：主信臣忠，百姓戴之，此魏之寶也，經侯解劍珮委之，趨而出，上車去，太子使騎操劍珮與侯曰：此寒不可衣，飢不可食，無遺我賊也。","sortOrder":28},
  {"id":"s_work_nvlt_67_29","chapterId":"ch_work_nvlt_67","text":"《典略》曰：孔子返衛，衛夫人南子，使人謂之曰：四方君子之來者，必見寡小君，孔子不得已見之，夫人在錦帷中，孔子北面稽首，夫人自帷中再拜，環珮之聲璆然。","sortOrder":29},
  {"id":"s_work_nvlt_67_30","chapterId":"ch_work_nvlt_67","text":"晉公卿禮秩曰：特進珮水蒼玉，尚書令仆射中書監令，皆佩水蒼玉。","sortOrder":30},
  {"id":"s_work_nvlt_67_31","chapterId":"ch_work_nvlt_67","text":"【賦】魏文帝玉玦賦曰：有崑山之妙璞，產曾城之峻崖，嗽丹水之炎波，荫瑤树之玄枝，包黃中之純氣，抱虛靜而無為，應九德之淑懿，體五材之表儀。","sortOrder":31},
  {"id":"s_work_nvlt_67_32","chapterId":"ch_work_nvlt_67","text":"【銘】後漢崔瑗遺葛龚珮銘曰：禹湯罪己，仲尼多誨，盤盂有銘，幾杖有誡，天為刚德，猶不幹時，君子妄怒，厥亦生灾，晉厲好虐，栾書作亂，荀瑤峻戾，韓魏致難，慷恺憤激，動腸傷氣，久生百疾，歷年不遂，俯覽斯珮，柔韦是貴。","sortOrder":32},
  {"id":"s_work_nvlt_67_33","chapterId":"ch_work_nvlt_67","text":"【啟】梁簡文帝謝敕賜玉珮啟曰：昉田麗彩，槐水鏤文，飾以金闕之珠，製以魯班之巧，故以裾端照色，影外生光，恩發內府，猥垂霑賜，臣方溫謝德，比振慚聲。","sortOrder":33},
  {"id":"s_work_nvlt_67_34","chapterId":"ch_work_nvlt_67","text":"【書】魏文帝與鍾繇書曰：南陽宋惠叔，稱君侯昔有美玦，聞之驚喜，笑與抃會，當自白書，恐傳言未審，是以令舍弟子建，因荀仲茂，時從容喻鄙旨，乃不忽遺，鄴騎既到，寶玦初至，捧匣跪發，五內震駭，繩窮匣开，烂然滿目，猥以蒙鄙之姿，得觀希世之寶，不煩一介之使，不損連城之价，既有秦昭章台之觀，而無蔺生诡奪之誑，嘉貺益腆，敢不钦承。","sortOrder":34},
  {"id":"s_work_nvlt_67_35","chapterId":"ch_work_nvlt_67","text":"◇巾帽","sortOrder":35},
  {"id":"s_work_nvlt_67_36","chapterId":"ch_work_nvlt_67","text":"《魏略》曰：夫餘國以金銀飾帽。","sortOrder":36},
  {"id":"s_work_nvlt_67_37","chapterId":"ch_work_nvlt_67","text":"又曰：管寧在家，恒著皂帽。","sortOrder":37},
  {"id":"s_work_nvlt_67_38","chapterId":"ch_work_nvlt_67","text":"又曰：裴潛為代郡太守，撫之以靜，单於脱帽稽顙。","sortOrder":38},
  {"id":"s_work_nvlt_67_39","chapterId":"ch_work_nvlt_67","text":"郭林宗別傳曰：林宗常行陳梁之間，遇雨，故其巾一角霑而折，二國學士著巾，莫不折其角，雲作林宗巾，其見儀則如此。","sortOrder":39},
  {"id":"s_work_nvlt_67_40","chapterId":"ch_work_nvlt_67","text":"《語林》曰：諸葛武侯與宣皇，在渭濱，將戰，宣皇戎服莅事，使人视武侯，乘素舆，葛巾毛扇，指麾三軍，皆隨其進止，宣皇聞而叹曰：可謂名士矣。","sortOrder":40},
  {"id":"s_work_nvlt_67_41","chapterId":"ch_work_nvlt_67","text":"沈約《宋書》曰：陶潛在家，郡將侯潛，值其酒熟，取頭上葛巾漉酒，漉酒畢，复還著之。","sortOrder":41},
  {"id":"s_work_nvlt_67_42","chapterId":"ch_work_nvlt_67","text":"【啟】陳周弘正謝敕赉乌紗帽等啟曰：雖复魏宣二端，豈能比今茲賜，廣微四縫，未足方其華飾，既受非望之恩，方貽匪服之誚。","sortOrder":42},
  {"id":"s_work_nvlt_67_43","chapterId":"ch_work_nvlt_67","text":"◇衣裳","sortOrder":43},
  {"id":"s_work_nvlt_67_44","chapterId":"ch_work_nvlt_67","text":"《毛詩》曰：摻摻女手，可以縫裳。","sortOrder":44},
  {"id":"s_work_nvlt_67_45","chapterId":"ch_work_nvlt_67","text":"《楚辭》曰：製芰荷以為衣，集芙蓉以為裳。","sortOrder":45},
  {"id":"s_work_nvlt_67_46","chapterId":"ch_work_nvlt_67","text":"《漢書》曰：邓通以擢船為黃頭郎，［施其黃髦於舡頭，因以其名其郎曰黃頭也。］文帝夢上天不能，有一黃頭郎推之，顧見其衣後穿，覺而以夢中陰自求推者郎，見邓通衣，其後穿，是夢中所見，因而甚見幸。","sortOrder":46},
  {"id":"s_work_nvlt_67_47","chapterId":"ch_work_nvlt_67","text":"魏書曰：文帝詔與朝臣雲，三世長者知被服，五世長者知飲食，此言被服飲食難晓也，夫珍玩必中國，總［全三國文六總上有夏則缣三字。］绡繐，其白如雪，羅紈綺縠，未聞衣布服葛也。","sortOrder":47},
  {"id":"s_work_nvlt_67_48","chapterId":"ch_work_nvlt_67","text":"又曰：甄皇後生，每寢，家中人仿佛見如有人持玉衣覆其上者。","sortOrder":48},
  {"id":"s_work_nvlt_67_49","chapterId":"ch_work_nvlt_67","text":"《魏志》曰：文帝欲徙冀州一十萬戶實河內，侍中辛毗諫，帝怒，起入內，毗隨而引帝裾，帝奋衣不回，良久，帝乃出曰：怪卿持我何太急。","sortOrder":49},
  {"id":"s_work_nvlt_67_50","chapterId":"ch_work_nvlt_67","text":"《吳書》曰：顧悌每得父書，洒扫正衣服拜跪。","sortOrder":50},
  {"id":"s_work_nvlt_67_51","chapterId":"ch_work_nvlt_67","text":"王隱《晉書》曰：董威輦，每得殘碎繒，辄結以為衣，號曰百結。","sortOrder":51},
  {"id":"s_work_nvlt_67_52","chapterId":"ch_work_nvlt_67","text":"【詩】魏曹毗夜聽捣衣詩曰：寒興御紈素，佳人治衣襟，冬夜清且永，皓月照堂陰，纖手叠輕素，朗杵叩鳴碪，清風流繁節，回飆洒微吟，嗟此嘉運速，悼彼幽滯心，二物感餘懷，豈但聲與音。","sortOrder":52},
  {"id":"s_work_nvlt_67_53","chapterId":"ch_work_nvlt_67","text":"宋謝惠連捣衣詩曰：衡紀無淹度，晷運倏如催，白露滋園菊，秋風落庭槐，肅肅莎雞羽，冽冽寒覅啼，夕陰結空幕，宵月皓空閨，美人戒裳服，端飾相招携，簪玉出北房，鳴金步南階，簷高碪响發，楹長杵聲哀，微芳發兩袖，輕汙染双題。","sortOrder":53},
  {"id":"s_work_nvlt_67_54","chapterId":"ch_work_nvlt_67","text":"梁柳惲捣衣詩曰：孤衾引思緒，獨枕怅忧端，深庭秋草绿，高門白露寒，思君起清夜，促柱奏幽蘭，不怨飛蓬苦，徒傷蕙草殘，行役滯風波，遊人淹不歸，亭皋木葉下，隴首秋蓬飛，鶴鳴勞永叹，采绿傷時暮，念君方遠遊，賤妾理紈素，秋風吹渌潭，明月懸高树，軒高夕杵散，氣爽夜碪鳴，瑤華隨步响，幽蘭逐袂生。","sortOrder":54},
  {"id":"s_work_nvlt_67_55","chapterId":"ch_work_nvlt_67","text":"梁劉孝威賦得香出衣詩曰：香出衣，步近氣逾飛，博山登高用鄴錦，含情動靨比洛妃，香纓麝帶逢金縷，琼花玉勝缀珠徽，蘇合故年微恨歇，都梁路遠恐非新，猶賢漢君芳十里，尚笑荀令止三旬。","sortOrder":55},
  {"id":"s_work_nvlt_67_56","chapterId":"ch_work_nvlt_67","text":"周庾信夜聽捣衣詩曰：秋夜捣衣聲，飛度長門城，今夜長門月，應如晝日明，小鬟宜粟縝，圓要韻織成，秋碪調急節，亂杵变新聲，石燥砧逾响，桐虛杵絕鳴，鳴石出華陰，虛桐采鳳林，北堂細腰杵，南市女郎砧，併結連支縷，双穿長命針，倡樓驚別怨，征客動愁心。","sortOrder":56},
  {"id":"s_work_nvlt_67_57","chapterId":"ch_work_nvlt_67","text":"又曰：捣衣明月下，靜夜秋風飄，錦石平砧面，莲房接杵腰，急節迎秋韻，新聲入手調，寒衣須及早，將寄霍嫖姚。","sortOrder":57},
  {"id":"s_work_nvlt_67_58","chapterId":"ch_work_nvlt_67","text":"梁費昶華光省中夜聽城外捣衣詩曰：阖闾下重關，丹墀吐明月，秋氣城中冷，秋砧城外發，浮聲繞雀台，飄响度龍闕，宛轉何藏摧，當從上路來，藏摧方未已，定自乘軒里，乘軒盡世家，佳麗似朝霞，員璫耳上照，方繡領間斜，衣燻百和屑，鬢插九枝花，昨暮庭槐落，今朝羅綺薄，拂席卷鴛鴦，开缊舒龟鵠，金波正容與，玉步依砧杵，紅袖往還萦，素腕參差舉，徒聞不得見，獨夜空愁佇。","sortOrder":58},
  {"id":"s_work_nvlt_67_59","chapterId":"ch_work_nvlt_67","text":"梁王僧孺詠捣衣詩曰：足傷金管遽，多怆緹光促，露团池上紫，風飄庭里绿，散度廣陵音，［參鹿憾，○明本作测。］寫漁陽曲，別鵠悲不已，離鸞斷還續，尺素在魚腸，寸心凭雁足。","sortOrder":59},
  {"id":"s_work_nvlt_67_60","chapterId":"ch_work_nvlt_67","text":"【啟】梁庾肩吾謝東宮赉內人春衣啟曰：階邊細草，猶推綟葉之光，戶前桃树，反訝藍花之色，遂得裾飛合燕，領斗分鸞，试顧采薪，皆成留客。","sortOrder":60},
  {"id":"s_work_nvlt_67_62","chapterId":"ch_work_nvlt_67","text":"《史記》曰：秦相范睢，與魏人須贾有隙，及贾使秦，睢自稱張祿先生，往詣贾。贾見其寒，取一綈袍以賜之，及睢數贾罪，曰：爾得不死者，以綈袍恋恋，有故人之意也。","sortOrder":62},
  {"id":"s_work_nvlt_67_63","chapterId":"ch_work_nvlt_67","text":"《漢武內傳》曰：上元夫人降武帝，服赤霜袍，雲采亂色，非錦非繡，不可得名。","sortOrder":63},
  {"id":"s_work_nvlt_67_64","chapterId":"ch_work_nvlt_67","text":"袁山松《後漢書》曰：靈帝欲羊續為太尉，時拜三公者，输東園禮錢千萬，令中使督之，續乃坐使者於单席，舉缊袍以示之，臣之所資，唯斯而已，故不登公位。","sortOrder":64},
  {"id":"s_work_nvlt_67_65","chapterId":"ch_work_nvlt_67","text":"【賦】隋江總山水納袍賦曰：皇储監國餘辰，勞謙終宴，有令以納袍降賜，何以奉扬恩德，因題此賦，濫時來之寵沐，振長纓以祗肅，奉性與之文章，侍相娱之絲竹，解女萝之山帶，佩流霞之羽服，裁縫則萬壑萦體，針縷則千巖映目，圖島屿之削成，寫淪涟之径复，埒符采於雕煥，併芬芳於蘭菊，悯四選之徂遷，軫百慮之回邅，霜飛空而浸霧，雁照月而猜絃，聽風鍾之易近，對冰霤之疏懸，若董衣之百結，同衛服之十年，嗟班鬢之已飒，愧冶袖之為妍，謝衔珠之有報，荷墜屦之無捐。","sortOrder":65},
  {"id":"s_work_nvlt_67_66","chapterId":"ch_work_nvlt_67","text":"【箋】晉劉謐之與天公箋曰：體戰身噤，脱衣冻坐，賴公借袍，南越送火。","sortOrder":66},
  {"id":"s_work_nvlt_67_67","chapterId":"ch_work_nvlt_67","text":"【啟】陳周弘正謝東宮賜縠袍啟曰：或儔名麗辭，等质輕霧，或色華少海，用寶丛台，或粲彼三英，縫茲五緎，品頒歲袭，绿奪春耕，蒿席可充，缊袍易足。","sortOrder":67},
  {"id":"s_work_nvlt_67_68","chapterId":"ch_work_nvlt_67","text":"◇裙襦","sortOrder":68},
  {"id":"s_work_nvlt_67_69","chapterId":"ch_work_nvlt_67","text":"《漢書》曰：班伯容貌甚麗，誦說有法，時上方向文學，鄭宽中張禹等，朝夕入說尚書《論語》：於金華殿中，詔伯受焉，數年，金華之業絕，班出與王許子弟為群，在於綺紈襦袴之中，非其好也。","sortOrder":69},
  {"id":"s_work_nvlt_67_70","chapterId":"ch_work_nvlt_67","text":"《東觀漢記》曰：梁鸿乡皇［東觀漢記作里。］孟氏女，容貌丑而有節操，多求之，不肯，父母問其所欲，曰：得賢婿如梁鸿者，鸿聞之，乃求之，女布襦裾，鸿曰：此真梁鸿妻也。","sortOrder":70},
  {"id":"s_work_nvlt_67_71","chapterId":"ch_work_nvlt_67","text":"《漢書》曰：廉范為蜀郡太守，百姓歌之曰：廉叔度，來何暮，昔日無襦今五袴。","sortOrder":71},
  {"id":"s_work_nvlt_67_72","chapterId":"ch_work_nvlt_67","text":"【啟】梁沈約謝齊竟陵王赉母赫國雲氣黃綾裙襦啟曰：竊以積絲成采，散茧騰花，巧擅易水之間，价貴丛台之下，民受祿為養，霑荷弥深，聖恩曲漸，自葉流根，複袖缊裾，豈伊恒飾，榮新之寵，固難輕報。","sortOrder":72},
  {"id":"s_work_nvlt_67_73","chapterId":"ch_work_nvlt_67","text":"梁任孝恭謝裙襦啟曰：加以庭闕桑麻，室空機杼，床無暖席，桁靡懸衣，值蓬卷北郊，雁飛南浦，雪闇河陰，冰生海岸，而繩帶屢盡，苦風霜之切，弊履恒穿，踐泥沙之冻，自怜袖短，雖內手而猶寒，每恨衣輕，徒斂襟而弥怆。","sortOrder":73},
  {"id":"s_work_nvlt_67_75","chapterId":"ch_work_nvlt_67","text":"《墨子》曰：江河之水，非一水之源，千镒之裘，非一狐之白。","sortOrder":75},
  {"id":"s_work_nvlt_67_76","chapterId":"ch_work_nvlt_67","text":"《戰國策》曰：蘇秦說秦王書，十二上而說不行，黑貂之裘弊。","sortOrder":76},
  {"id":"s_work_nvlt_67_77","chapterId":"ch_work_nvlt_67","text":"又曰：齊襄王立，田单相之，過魯，有老人涉淄而寒，出而不行，坐沙中，单見其寒，解裘而衣之，襄王曰：田单之惠施，欲以取我國乎，有貫珠者，襄王呼而問之，對曰：王不如因賞，下令曰：寡人忧人之寒，单解裘而衣之，稱寡人之意焉。","sortOrder":77},
  {"id":"s_work_nvlt_67_78","chapterId":"ch_work_nvlt_67","text":"《說苑》曰：千金之裘，非一狐之皮也，廊廟之榱，非一木之枝也，王法非一士之知也。","sortOrder":78},
  {"id":"s_work_nvlt_67_79","chapterId":"ch_work_nvlt_67","text":"晉鹹寧《起居註》曰：大医司馬程據，上雉頭裘一領，詔據，此裘非常衣服，消費功用，其於殿前燒之，敕外內有造異服，依禮治罪。","sortOrder":79},
  {"id":"s_work_nvlt_67_80","chapterId":"ch_work_nvlt_67","text":"《十洲記》曰：漢武帝天漢三年，西國王獻吉光毛裘，裘色黃，蓋神馬之類，入水經日不沉，入火不燋，帝厚謝使者。","sortOrder":80},
  {"id":"s_work_nvlt_67_81","chapterId":"ch_work_nvlt_67","text":"《東觀漢記》曰：東平王蒼來朝，章帝以王觸寒涉道，賜王乘舆貂裘。","sortOrder":81},
  {"id":"s_work_nvlt_67_82","chapterId":"ch_work_nvlt_67","text":"【啟】齊王融謝敕賜御裘等啟曰：雲衣降授，仙裾曲委，榮振素里，泽駭蓬心，昔漢帝解裘，不獨前寵，曹王褫帶，复降今恩。","sortOrder":82},
  {"id":"s_work_nvlt_67_83","chapterId":"ch_work_nvlt_67","text":"又謝竟陵王賜納裘啟曰：降飾自尊，垂榮及賤，玄玉不純，曾波奪采，南陆方永，北風日壮，無衣無褐，發念聖衷，而挟纊之問每流，解裘之賜偏委。","sortOrder":83},
  {"id":"s_work_nvlt_67_84","chapterId":"ch_work_nvlt_67","text":"梁簡文帝謝東宮賜裘啟曰：物華雉毳，名高燕羽，才慚齊相，愧白狐之飾，德謝漢蕃，均黑貂之賜，地卷朔風，庭流花雪，故以裾生惠氣，袖起陽春。","sortOrder":84},
  {"id":"s_work_nvlt_67_86","chapterId":"ch_work_nvlt_67","text":"《穆天子傳》曰：天子征至赤乌之人，赤乌氏先，出自宗周，乃賜貝帶五十具。","sortOrder":86},
  {"id":"s_work_nvlt_67_87","chapterId":"ch_work_nvlt_67","text":"《戰國策》曰：魯仲連謂田单曰：將軍東有夜邑之奉，西有淄上之娱，黃金橫帶，而騁乎淄渑之間，有生之［二字原脱，據冯校本補。］樂，無死之心，所以不勝狄也。","sortOrder":87},
  {"id":"s_work_nvlt_67_88","chapterId":"ch_work_nvlt_67","text":"《史記》曰：帝遺匈奴黃金飾貝帶一具。","sortOrder":88},
  {"id":"s_work_nvlt_67_89","chapterId":"ch_work_nvlt_67","text":"《魏略》曰：疏勒王獻大秦赤石帶一枚。","sortOrder":89},
  {"id":"s_work_nvlt_67_90","chapterId":"ch_work_nvlt_67","text":"《吳書》曰：陆遜破曹休，帝脱御金帶以賜遜。又親以帶之。","sortOrder":90},
  {"id":"s_work_nvlt_67_91","chapterId":"ch_work_nvlt_67","text":"《吳錄》曰：鉤落者，革帶也，世名為鉤落帶。","sortOrder":91},
  {"id":"s_work_nvlt_67_92","chapterId":"ch_work_nvlt_67","text":"【啟】梁劉孝儀謝晉安王賜銀裝絲帶啟曰：雕鏤新奇，織製精絜，越中玉女，不得關思，上方名匠，莫能議巧，人情駭觀，如見買臣之綬，望貌移姿，似逢子訓之術。","sortOrder":92},
  {"id":"s_work_nvlt_67_93","chapterId":"ch_work_nvlt_67","text":"《藝文類聚》　唐·欧陽詢","sortOrder":93},
  {"id":"s_work_nvlt_68_1","chapterId":"ch_work_nvlt_68","text":"卷六十八儀飾部","sortOrder":1},
  {"id":"s_work_nvlt_68_2","chapterId":"ch_work_nvlt_68","text":"○節黃鉞鼓吹相風漏刻","sortOrder":2},
  {"id":"s_work_nvlt_68_4","chapterId":"ch_work_nvlt_68","text":"《禮記》曰：凡君召以三節，二節以走，一節以趨。","sortOrder":4},
  {"id":"s_work_nvlt_68_5","chapterId":"ch_work_nvlt_68","text":"《呂氏春秋》曰：墨者田鳩，欲見秦惠王，留三年而不得見，客有言之於楚王，乃往見楚王，王悅之，與將軍之節以如秦，至而得見，出而告人曰：吾不識秦之道，乃當由楚也，物固有近之而遠，遠之而近。","sortOrder":5},
  {"id":"s_work_nvlt_68_6","chapterId":"ch_work_nvlt_68","text":"《漢書》曰：蘇武使匈奴，单於欲降之，幽武，置大窖中，絕飲食，天雨雪，武臥齧雪，與旃毛併咽之，數日不死，匈奴以為神，乃徙武北海上無人處，使牧羊，武杖漢節牧羊，臥起操持節，節毛盡落，積五六年。","sortOrder":6},
  {"id":"s_work_nvlt_68_7","chapterId":"ch_work_nvlt_68","text":"又曰：建元三年，閩越舉兵围東甌，東甌告急，上遣嚴助，以節發兵會稽，會稽太守欲不為發兵，助乃斬一司馬，遂發兵，浮海救東甌。","sortOrder":7},
  {"id":"s_work_nvlt_68_8","chapterId":"ch_work_nvlt_68","text":"又曰：張騫使月氏，匈奴得之，留騫十餘歲，與妻有子，然騫持漢節不失。","sortOrder":8},
  {"id":"s_work_nvlt_68_9","chapterId":"ch_work_nvlt_68","text":"又曰：諸葛丰特立刚直，元帝擢為司隸校尉，刺舉無所避，侍中許章，以外屬貴幸奢淫，賓客犯事，與章相連，丰按劾章，欲奏其事，適逢許侍中私出，丰駐車，舉節語章曰：下，欲收之，章馳車去，丰追之，許因得入宮門，自歸於上，丰亦上奏，於是收丰節，司隸去節，自丰始。","sortOrder":9},
  {"id":"s_work_nvlt_68_10","chapterId":"ch_work_nvlt_68","text":"又曰：漢使王焉等窥匈奴，匈奴法，漢使不去節，不以墨黥其面，不得入穹庐，王焉北地人，習胡俗，去其節，黥面，入穹庐，单於受之。","sortOrder":10},
  {"id":"s_work_nvlt_68_11","chapterId":"ch_work_nvlt_68","text":"《東觀漢記》曰：永平中，遣鄭眾使北匈奴，眾因上書，言臣前奉使，不為匈奴拜，单於悉恨，故兵围臣，今复衔命，必凌折臣，臣誠不忍將大漢節，對氈裘拜，如令匈奴遂能服臣，將有損大漢之強，上不聽，眾不得已既行，後果為匈奴所殺。","sortOrder":11},
  {"id":"s_work_nvlt_68_12","chapterId":"ch_work_nvlt_68","text":"《獻帝春秋》曰：太傅馬日磾，假節循撫州郡，袁術在寿春，借節觀之，因奪不還，日磾失節，忧恚而死。","sortOrder":12},
  {"id":"s_work_nvlt_68_13","chapterId":"ch_work_nvlt_68","text":"【表】梁元帝遷荆州输江州節表曰：周有掌節之職，漢有符節之令，所以子孫慷慨，忠肅勤王，無絕終古，有高前載，臣自擁旄鶴塞，執茲龍節，幸逢銀山自溢，玉燭調年，雖免茂弘之譏，竟微辛毗之勇。","sortOrder":13},
  {"id":"s_work_nvlt_68_14","chapterId":"ch_work_nvlt_68","text":"◇黃鉞","sortOrder":14},
  {"id":"s_work_nvlt_68_15","chapterId":"ch_work_nvlt_68","text":"《尚書》曰：武王左杖黃鉞，右執白旄。","sortOrder":15},
  {"id":"s_work_nvlt_68_16","chapterId":"ch_work_nvlt_68","text":"《淮南子》曰：至精之感，無所不通，昔武王度孟津，而陽侯之波，逆流而击，疾風晦冥，武王舉黃鉞，瞋目而麾之曰：予在，天下誰敢害吾，於是風去而波罢，遂得濟。","sortOrder":16},
  {"id":"s_work_nvlt_68_17","chapterId":"ch_work_nvlt_68","text":"《吳錄》曰：假陆遜黃鉞，吳王親執鞭以見之矣。","sortOrder":17},
  {"id":"s_work_nvlt_68_18","chapterId":"ch_work_nvlt_68","text":"《晉中興書》曰：會稽王道子，進位丞相，牧楊州，假黃鉞。","sortOrder":18},
  {"id":"s_work_nvlt_68_19","chapterId":"ch_work_nvlt_68","text":"《世說》曰：諸葛亮之次渭濱也，關中震動，魏明帝深懼晉宣王戰，乃遣辛毗為軍司馬，宣王既與亮對渭而陣，亮設誘，诡譎萬方，宣王果大忿憤，將應以重兵，亮遣聞［世說方正篇作間。］諜觇之，還曰：有一老夫，毅然杖黃鉞，當軍門立，軍不得出，亮曰：必辛佐治也。","sortOrder":19},
  {"id":"s_work_nvlt_68_20","chapterId":"ch_work_nvlt_68","text":"【銘】蔡邕黃鉞銘曰：帝命將軍，執茲黃鉞，威靈震耀，如火之烈，公之莅止，群狄斯柔，齊聲罔設，介士斯休。","sortOrder":20},
  {"id":"s_work_nvlt_68_21","chapterId":"ch_work_nvlt_68","text":"◇鼓吹","sortOrder":21},
  {"id":"s_work_nvlt_68_22","chapterId":"ch_work_nvlt_68","text":"《漢書》曰：韓延寿在東郡，植羽葆鼓車吹車。","sortOrder":22},
  {"id":"s_work_nvlt_68_23","chapterId":"ch_work_nvlt_68","text":"又曰：秦始皇末，班懿避地樓煩，致馬牛羊數千群，值漢初定，與民無禁，當孝惠高後時，以财雄邊，出入弋獵，旌旗鼓吹。","sortOrder":23},
  {"id":"s_work_nvlt_68_24","chapterId":"ch_work_nvlt_68","text":"《東觀漢記》曰：段穎起於徒中，為併州刺史，有功，徵還京師，穎乘輕車，介士鼓吹曲蓋。","sortOrder":24},
  {"id":"s_work_nvlt_68_25","chapterId":"ch_work_nvlt_68","text":"又曰：建初八年，稱班超為將兵長史，假鼓吹幢麾。","sortOrder":25},
  {"id":"s_work_nvlt_68_26","chapterId":"ch_work_nvlt_68","text":"應劭《漢官儀》曰：鼓吹為國盤娱，御侮爪牙。","sortOrder":26},
  {"id":"s_work_nvlt_68_27","chapterId":"ch_work_nvlt_68","text":"《吳志》曰：孫權拜諸葛恪撫越將軍，領丹陽太守，授棨戟，武騎三百，拜畢，令恪備威儀，作鼓吹，导引歸家。","sortOrder":27},
  {"id":"s_work_nvlt_68_28","chapterId":"ch_work_nvlt_68","text":"《吳质別傳》曰：质為北中郎將，朝京師，上歡喜其到，比至家，問訊相續，詔將軍列滷簿，作鼓吹，望闕而止。","sortOrder":28},
  {"id":"s_work_nvlt_68_29","chapterId":"ch_work_nvlt_68","text":"《吳歷》曰：曹公出濡須口，吳王乃自乘船，從濡須口入，曹公嚴兵待之，乃作鼓吹回還，曹公見吳舟船器仗，法伍整肅，乃叹曰：養兒當如孫會稽，劉表子直是豚犬耳。","sortOrder":29},
  {"id":"s_work_nvlt_68_30","chapterId":"ch_work_nvlt_68","text":"《江表傳》曰：周秦［吳志十周泰傳註作泰，下同。］為濡須督，統諸將，諸將以秦本出賤微，鹹輕傲之，孫權乃入秦營，於都巷中張缦，大請官僚，使秦脱衣帻，見其瘡痍匝體，指瘡而問，何地戰傷，秦具對，權把其臂流涕曰：卿為孤兄弟，戰不惜命，身如刻漆，孤何心而不待卿以骨肉之恩，使秦以兵馬导從出，作鼓吹。","sortOrder":30},
  {"id":"s_work_nvlt_68_31","chapterId":"ch_work_nvlt_68","text":"又曰：孫策賜周瑜鼓吹，赠賜莫與為比，策令曰：周公瑾英俊異才，與孤有總角之好，骨肉之分，前在丹陽，發眾及船糧，以濟大事，論德酬功，此未足以報也。","sortOrder":31},
  {"id":"s_work_nvlt_68_32","chapterId":"ch_work_nvlt_68","text":"《荆州先賢傳》曰：羅獻以太始三年，進位冠軍，假節，給大車，增鼓吹棨戟。","sortOrder":32},
  {"id":"s_work_nvlt_68_33","chapterId":"ch_work_nvlt_68","text":"《俗說》曰：桓玄作詩，思不來，辄作鼓吹，既而思得，雲鳴鵠响長阜，叹曰：鼓吹固自來人思。","sortOrder":33},
  {"id":"s_work_nvlt_68_34","chapterId":"ch_work_nvlt_68","text":"《語林》曰：陆士衡為河北督，已被間構，內懷忧懣，聞眾軍警角鼓吹，謂其司馬曰：我今聞此，不如華亭鶴鳴。","sortOrder":34},
  {"id":"s_work_nvlt_68_35","chapterId":"ch_work_nvlt_68","text":"【賦】晉陆機鼓吹賦曰：原鼓吹之攸始，蓋禀命於黃軒，播威靈於茲樂，亮聖器而成文，騁逸氣而憤壮，繞煩手乎曲折，舒飄飖以遐洞，卷徘徊其如結，及其悲唱流音，怏惶依违，含歡嚼弄，乍數乍稀，音踯躅於唇吻，若將舒而复回，鼓砰砰以輕投，箫嘈嘈而微吟，詠悲翁之流思，怨高台之難臨，顧穹穀以含哀，仰歸雲而落音，節應氣以舒卷，响隨風而浮沉，馬頓跡而增鳴，士嚬顣而霑襟，若乃巡郊泽，戲野坰，奏君馬，詠南城，惨巫山之遐险，歡芳树之可榮。","sortOrder":35},
  {"id":"s_work_nvlt_68_36","chapterId":"ch_work_nvlt_68","text":"【表】魏陳王曹植謝鼓吹表曰：許以箫管之樂，榮以田遊之嬉，陛下仁重有虞，恩過周旦，濟世安宗，寔在聖德。","sortOrder":36},
  {"id":"s_work_nvlt_68_37","chapterId":"ch_work_nvlt_68","text":"梁簡文帝讓鼓吹表曰：宽博為善，不飾被於聲明，緣寵成功，未增榮於鐃管，豈宜响芳树於西河，鳴朝飛於黑水，彼己之譏何懼，尸素之誡知慚。","sortOrder":37},
  {"id":"s_work_nvlt_68_38","chapterId":"ch_work_nvlt_68","text":"梁江淹為齊高帝讓前部羽葆鼓吹表曰：臣聞國容軍禮，旌羽昭其華，車騎品第，鑾蕤藹其飾，世教以之垂采，民聽以之流文，故勒岫銘海之功，鞞革寫其詠，戡難夷邦之業，管竹凝其聲，朱露玄雲，既錫上德，巫山芳树，以被奇勋。","sortOrder":38},
  {"id":"s_work_nvlt_68_39","chapterId":"ch_work_nvlt_68","text":"隋江總謝敕給鼓吹表曰：略尋近古，逖聽前事，王文憲匡佐革命，沈隱侯經纶始運，騎吹之榮，猶難忝冒，以臣况此，寔非倫辈，豈可更崇文物，重假名器，高台迢遰，未朱夏而登臨，芳树華滋，非青春而奏曲。","sortOrder":39},
  {"id":"s_work_nvlt_68_40","chapterId":"ch_work_nvlt_68","text":"◇相風","sortOrder":40},
  {"id":"s_work_nvlt_68_41","chapterId":"ch_work_nvlt_68","text":"《晉令》曰：車駕出入，相風前引。","sortOrder":41},
  {"id":"s_work_nvlt_68_42","chapterId":"ch_work_nvlt_68","text":"【賦】晉傅玄相風賦曰：昔之造相風者，知其自然之極乎，其達变通之理乎，觀妙之微，神明可通，夫能立成器以占吉凶之先見者，莫精乎此，乃構相風，因象設形，蜿盤獸以為趾，建修竿之亭亭，體正直之無桡，度經高而不傾，栖神乌於竿首，俟祥風之來征。","sortOrder":42},
  {"id":"s_work_nvlt_68_43","chapterId":"ch_work_nvlt_68","text":"晉張華相風賦曰：蓋在先聖，道濟生人，擬議天地，错綜明神，在璿璣以齊七政，象浑儀於陶鈞，考古旁於六氣，仰貞觀於三辰，爰在保章，世序其職，辯風候方，必立准極，循物致用，器不假飾，眇脩幹之迢迢，凌高墉而茎植，玄鳥偏其增翥，晞雲霄而矯翼，嘉創製之窮理，谅器淺而事深，步元氣於尋木，寄先識於茲禽，既在高而思危。又戒险而自箴，雖回易之無常，終守正而不淫，永恪立以弥世，志淹滯而愈新，超無返而特存，差偶景而為鄰。","sortOrder":43},
  {"id":"s_work_nvlt_68_44","chapterId":"ch_work_nvlt_68","text":"晉潘嶽相風賦曰：混元恍其初判，二氣变而無窮，動靡微而不兆，象有始而必終，思先天而不违，立成器以相風，栖靈乌於帝庭，似月離乎紫宮，飛輕羽於竿杪，若鸞翔乎雲中，廣漠興而習坎，景風發而溯離，閶阖扬而西指，明庶起而東移。","sortOrder":44},
  {"id":"s_work_nvlt_68_45","chapterId":"ch_work_nvlt_68","text":"晉陶侃相風賦曰：乃有相風之為形也，終日九征，桀然特立，不邪不傾，擬雲閣以秀出，晞峻嶺於層城，直南端以基趾，双崇魏之峣峥，象建木於都廣，邈不群而獨榮，朴雖小而不巨，何物鮮而功大，眇翩翩以高翔，象離鵾於雲际，擢孤茎而特挺，若芙蓉於水裔，若乃華蓋警乘，奉引先驅，豹飾在後，葳蕤清路，百僚允則，彰我皇度。","sortOrder":45},
  {"id":"s_work_nvlt_68_46","chapterId":"ch_work_nvlt_68","text":"晉孫楚相風賦曰：伊聖皇之高烈，美治道之穆清，兼乾坤之普覆，齊三光之朗明，猶恭己以勞謙，迄日昃而不寧，慮聽政之有闕，誡禍福於無形，建殊才於辰極，树相風於紫庭，爾乃神獸盤其根，靈乌據其顛，羽族翩飄羅其侧，翔風萧聊出其間。","sortOrder":46},
  {"id":"s_work_nvlt_68_47","chapterId":"ch_work_nvlt_68","text":"◇漏刻","sortOrder":47},
  {"id":"s_work_nvlt_68_48","chapterId":"ch_work_nvlt_68","text":"《說文》曰：漏以銅盛水，刻節，晝夜百刻。","sortOrder":48},
  {"id":"s_work_nvlt_68_49","chapterId":"ch_work_nvlt_68","text":"《周官》曰：挈壶氏，掌壶，皆以水火守之，分以日夜。","sortOrder":49},
  {"id":"s_work_nvlt_68_50","chapterId":"ch_work_nvlt_68","text":"《東觀漢記》曰：樊梵，每當直事，常晨駐車待漏。","sortOrder":50},
  {"id":"s_work_nvlt_68_51","chapterId":"ch_work_nvlt_68","text":"《吳錄》曰：吳范，善占候，知風氣，關羽將降，孫權問范，范曰：期明日中，權立表下漏以待之，及中不至，權問其故，范曰：未正中，頃之，有風動帷，范曰：羽至矣，外稱萬歲，傳言得羽矣。","sortOrder":51},
  {"id":"s_work_nvlt_68_52","chapterId":"ch_work_nvlt_68","text":"【賦】晉陆機漏刻賦曰：伟聖人之製器，妙萬物而為基，形罔隆而弗包，理何遠而不之，既窮神以盡化。又設漏以考時，爾乃挈金壶以南羅，藏幽水而北戢，擬洪殺於編鍾，順卑高而為級，激懸泉以遠射，跨飛涂而遙集，伏陰虫以承波，吞恒流其如挹，是故來象神造，去猶鬼幻，因势相引，乘靈自荐，口納焜吐，水無滯咽，形微獨茧之緒，逝若垂天之電，籠八極於千分，度晝夜乎一箭，抱百刻以駿浮，仰胡人而利見，夫其體也簡，而效績也誠，其假物也粗，而致用也精，積水不過一鍾，导流不過一筳，而用天者因其敏，分地者賴其平，微聽者假其察，貞觀者借其明，考計歷之潛慮，惻日月之幽情。","sortOrder":52},
  {"id":"s_work_nvlt_68_53","chapterId":"ch_work_nvlt_68","text":"宋鮑昭觀漏賦曰：歷玉階而升隩，訪金壶之盈闕，觀騰波之吞泻，视驚箭之登設，謹戶牖而知命，掩雲霧而测暉，創百齡於纖隱，積千里於空微，彼峥峥而行溢，此冉冉而逾衰，撫寸心而未改，指分光而永违，貫古今而併念，信寡易而多難，時不留乎激矢，生乃急於走丸，神怵迫而忘慮，心坎懍而鮮歡，望天涯而佇念，棹雄劍而長叹，嗟生民之永迷，躬與後而皆恤，死零落而無二，生差池而非一。","sortOrder":53},
  {"id":"s_work_nvlt_68_54","chapterId":"ch_work_nvlt_68","text":"【銘】後漢李尤漏刻銘曰：昧旦丕顯，敬聽漏音，思我王度，如玉如金。","sortOrder":54},
  {"id":"s_work_nvlt_68_55","chapterId":"ch_work_nvlt_68","text":"晉孫綽漏刻銘曰：二儀貞運，聖鑒通玄，數以微器，理以象宣，乃製妙漏，挈壶是铨，近取諸物，遠贊自然，川滿則盈，乘虛赴下，靈虬吐註，陰虫承寫，昏明無隱其晷度，陰陽是效其屈伸，不下堂而天地理得，設一器而萬事同倫。","sortOrder":55},
  {"id":"s_work_nvlt_68_56","chapterId":"ch_work_nvlt_68","text":"梁元帝漏刻銘曰：玉衡稱物，金壶博施，司南司火，未符茲義，帝曰钦哉，納隍斯譬，實惟簡在，窮神體智，宮槐晚合，月桂宵暉，清台莫爽，解穀胥依，七分六日，五祀三微，事齊幽贊，乃會通幾，碧海有乾，絳川猶竭，飛流五色，涓涓靡絕，龍首傍註，仙衣俯裂，箭不停晷，聲無暫輟，用天之貞，分地之平，如絃斯直，如渭斯清。","sortOrder":56},
  {"id":"s_work_nvlt_68_57","chapterId":"ch_work_nvlt_68","text":"梁陆倕新漏刻銘曰：微若抽茧，逝如激電，耳不輟音，眼無留眄，銅史司刻，金徒抱箭，履薄非兢，臨深罔戰，授受靡愆，登降弗爽，惟精惟一，可法可象，月不遁來，日無藏往，分似符契，至猶影响，合昏暮卷，蓂荚晨生，尚辯天意，猶测地情，况我神造，通幽洞靈。","sortOrder":57},
  {"id":"s_work_nvlt_68_58","chapterId":"ch_work_nvlt_68","text":"周王褒漏刻銘曰：竊以混元开辟，天回地旋，歷象運行，暑來寒往，二分同道，乌靈正其昏夕，兩至相遇，表圭测其長短，雖則晦朔先後，失於公羊之說，次舍盈縮，惑於丘明之傳，至乎出卯入酉，黃道青绿，季孟相推，啟閉從序，挈壶掌分數之令，太史陳立成之法，軍將以之懸井，壶郎以之趍奏，百王垂訓，千祀餘烈者焉，銘曰：玄儀西運，逝水東流，甘川浴日，深壑藏舟，测茲秘象，是曰神謀，正震治歷，下武惟周，忽微以测，積空成數，圭表弗差，光陰斯赴，箭水無絕，靈虬長註，經寸日輪，四分天度，器遵昔典，景移新刻，荆山既镌，崑吾且勒，以福眉寿，百王垂則。","sortOrder":58},
  {"id":"s_work_nvlt_68_59","chapterId":"ch_work_nvlt_68","text":"李尤刻漏銘曰：昔在先聖，配天垂則，仰釐七曜，俯順坤德，乃建日官，俾立漏刻，昏明既序，景曜不忒，唐命羲和，敬授人時，懸象著明，帝以崇熙，季末不虔，德衰於茲，挈壶失節，刺流在詩。","sortOrder":59},
  {"id":"s_work_nvlt_68_60","chapterId":"ch_work_nvlt_68","text":"《藝文類聚》　唐·欧陽詢","sortOrder":60},
  {"id":"s_work_nvlt_69_1","chapterId":"ch_work_nvlt_69","text":"卷六十九服飾部上","sortOrder":1},
  {"id":"s_work_nvlt_69_2","chapterId":"ch_work_nvlt_69","text":"○帳屏風幔簟荐席案幾杖扇麈尾","sortOrder":2},
  {"id":"s_work_nvlt_69_4","chapterId":"ch_work_nvlt_69","text":"《史記》曰：沛公入秦宮，宮室帷帳，狗馬重寶婦女以千數，意欲留居之，樊哙諫沛公出舍，沛公不聽，張良諫，乃止。","sortOrder":4},
  {"id":"s_work_nvlt_69_5","chapterId":"ch_work_nvlt_69","text":"又曰：項王軍壁垓下，夜聞漢軍四面楚歌，乃大驚曰：漢皆已得楚乎，夜飲帳中。","sortOrder":5},
  {"id":"s_work_nvlt_69_6","chapterId":"ch_work_nvlt_69","text":"又曰：丞相公孫弘燕見，上或時不冠而見，上嘗坐武帳中，汲黯前奏事，上不冠，望見黯，避帳中，使人可其奏事，其見敬禮如此。","sortOrder":6},
  {"id":"s_work_nvlt_69_7","chapterId":"ch_work_nvlt_69","text":"《漢武故事》曰：西王母感上區區之誠，暮必神降，上乃盛施帷帳，燒兜沬香，香聞數百里。","sortOrder":7},
  {"id":"s_work_nvlt_69_8","chapterId":"ch_work_nvlt_69","text":"又曰：上以琉璃珠玉，明月夜光，雜错天下珍寶為甲帳，其次為乙帳，甲以居神，乙以自居。","sortOrder":8},
  {"id":"s_work_nvlt_69_9","chapterId":"ch_work_nvlt_69","text":"《漢書》曰：東方朔雲，陛下誠能用臣朔之計，推甲乙之帳，［甲乙，帳名也，瓒曰：興造乙(漢書六十五東方朔傳註乙上有甲字。)之帳，落以隨珠和璧，天子袭翠被，為(漢書註作凭。)玉幾，而處其中。］燔之於四通之衢。","sortOrder":9},
  {"id":"s_work_nvlt_69_10","chapterId":"ch_work_nvlt_69","text":"《三辅舊事》：秦時奢泰，渭水貫都，以象天河，橫桥南渡，以象牵牛，後宮列女，萬有餘人，婦人之氣，上冲於天，缣帳綺帷，木衣綈繡，土被朱紫。","sortOrder":10},
  {"id":"s_work_nvlt_69_11","chapterId":"ch_work_nvlt_69","text":"《東觀漢記》曰：桓榮常寢病，太子朝夕遣中人問疾，賜以帷帳奴婢，曰：如有不讳，無忧家室也，後病愈，入复侍講。","sortOrder":11},
  {"id":"s_work_nvlt_69_12","chapterId":"ch_work_nvlt_69","text":"《漢舊儀》曰：祭天有绀幄帳。","sortOrder":12},
  {"id":"s_work_nvlt_69_13","chapterId":"ch_work_nvlt_69","text":"《馬融別傳》曰：馬融為儒，教養諸生，常有千數，善鼓琴，好吹笛，達生任性，不拘儒者之節，居宇器服，多存侈飾，常坐高堂，施絳紗帳，前授生徒，後列女樂，弟子以次相傳，鮮有入其室者。","sortOrder":13},
  {"id":"s_work_nvlt_69_14","chapterId":"ch_work_nvlt_69","text":"《益部耆舊傳》曰：翟酺上事雲，漢文帝連上書囊以為帳，惡聞紈素之聲。","sortOrder":14},
  {"id":"s_work_nvlt_69_15","chapterId":"ch_work_nvlt_69","text":"傅子曰：太祖武皇帝，恐嫁娶之僣上，公主適人，不過帛帳，從婢十人而已。","sortOrder":15},
  {"id":"s_work_nvlt_69_16","chapterId":"ch_work_nvlt_69","text":"【詩】梁沈約詠帳詩曰：甲帳垂和壁，螭雲張桂宮，隨珠既吐曜，翠被复含風。","sortOrder":16},
  {"id":"s_work_nvlt_69_17","chapterId":"ch_work_nvlt_69","text":"◇屏風","sortOrder":17},
  {"id":"s_work_nvlt_69_18","chapterId":"ch_work_nvlt_69","text":"《京兆舊事》曰：杜陵萧彪，子伯文，為巴郡太守，以父老，歸供養，父有客，常立屏風後，自應使命。","sortOrder":18},
  {"id":"s_work_nvlt_69_19","chapterId":"ch_work_nvlt_69","text":"《東觀漢記》曰：宋弘嘗燕見，御坐新施屏風，畫烈女，帝數顧视之，弘正容言曰：未見好德如好色者，上即為撤之，時上姊胡陽公主新寡，上與共論朝臣，微觀其意，主曰：宋公威容德器，群臣莫及，上曰：方且圖之，後弘見上，令主坐屏風後，因謂弘曰：諺言，貴易交，富易妻，人情乎，弘曰：臣聞貧賤之交不可忘，糟糠之妻不下堂，上顧謂主曰：事不諧矣。","sortOrder":19},
  {"id":"s_work_nvlt_69_20","chapterId":"ch_work_nvlt_69","text":"謝承《後漢書》曰：鄭弘，為太尉時，舉弟五倫為司空，班次在下，每正朔朝見，弘曲躬自卑，上問知其故，遂聽置雲母屏風，分隔其間，由此為故事，［事具職官部。］","sortOrder":20},
  {"id":"s_work_nvlt_69_21","chapterId":"ch_work_nvlt_69","text":"《三辅决錄》曰：何敞為汝南太守，章帝南巡過郡，有雕鏤屏風，為帝設之，命侍中黃香銘之曰：古典務農，彫鏤傷民，忠在竭節，義在脩身。","sortOrder":21},
  {"id":"s_work_nvlt_69_22","chapterId":"ch_work_nvlt_69","text":"《魏志》曰：太祖平柳城，班所獲器物，特以素屏風素幾賜毛玠，曰：君有古人之風，故賜君古人之服。","sortOrder":22},
  {"id":"s_work_nvlt_69_23","chapterId":"ch_work_nvlt_69","text":"《吳錄》曰：景帝時，紀亮為尚書令，子骘為中書令，每朝會，詔以御屏風隔其座焉。","sortOrder":23},
  {"id":"s_work_nvlt_69_24","chapterId":"ch_work_nvlt_69","text":"又曰：曹不興善畫屏風，誤落筆點素，因就以作蠅，權以為生蠅，舉手彈之。","sortOrder":24},
  {"id":"s_work_nvlt_69_25","chapterId":"ch_work_nvlt_69","text":"《語林》曰：滿城武秋［《太平御覽》七百零一作滿奋字武秋，此有訛脱。］體羸惡風，侍坐晉武帝，屢顧看雲母幌，武帝笑之，武雲，北窗琉璃屏風，實密似疏，帝有難色。","sortOrder":25},
  {"id":"s_work_nvlt_69_26","chapterId":"ch_work_nvlt_69","text":"【詩】周庾信詠屏風詩曰：昨夜鳥聲春，驚啼動四鄰，今朝梅树下，定有詠花人，流星浮酒泛，粟钿繞杯唇，何勞一片雨，唤作陽台神。","sortOrder":26},
  {"id":"s_work_nvlt_69_27","chapterId":"ch_work_nvlt_69","text":"又曰：逍遙遊桂苑，寂絕想桃源，狹石分花迳，長桥映水門，管聲驚百鳥，人衣香一園，定知懽未足，橫琴坐树根。","sortOrder":27},
  {"id":"s_work_nvlt_69_28","chapterId":"ch_work_nvlt_69","text":"又曰：高閣千尋起，長廊四註連，歌聲上扇月，舞影入聞絃，涧水繞窗外，山花即眼前，但顧［本集作原。］長歡樂，從今一百年。","sortOrder":28},
  {"id":"s_work_nvlt_69_29","chapterId":"ch_work_nvlt_69","text":"又曰：捣衣明月下，靜夜秋風飄，錦石平砧面，莲房接杵腰，急節迎秋韻，新聲入手調，寒衣須及早，將寄霍嫖姚。","sortOrder":29},
  {"id":"s_work_nvlt_69_30","chapterId":"ch_work_nvlt_69","text":"又曰：今朝好風日，園苑足芳菲，竹動蝉爭散，莲搖魚暫飛，面紅新著酒，風晚細吹衣，跂石多時望，莲船始复歸。","sortOrder":30},
  {"id":"s_work_nvlt_69_31","chapterId":"ch_work_nvlt_69","text":"【賦】漢淮南王屏風賦曰：惟斯屏風，出自幽穀，根深枝茂，號曰乔木，孤性陋弱，畏金彊族，移根易土，委伏溝渎，飄飖危殆，靡安厝足，天啟我心，遭遇微祿，中郎善治，收拾捐朴，大匠治之，彫刻削斫，等化器類，庇荫尊屋，賴蒙成濟，其恩弘篤，不逢仁人，永為枯木。","sortOrder":31},
  {"id":"s_work_nvlt_69_32","chapterId":"ch_work_nvlt_69","text":"【啟】梁簡文帝謝赉棋子屏風啟曰：極班馬之巧，兼曹史之慮，均天台之翠璧，雜水葉之嘉名，電母之窗，慚其麗色，琉璃之扇，愧其含影。","sortOrder":32},
  {"id":"s_work_nvlt_69_33","chapterId":"ch_work_nvlt_69","text":"梁劉孝威謝敕赉畫屏風啟曰：昔紀亮所隔，唯珍雲母，武秋所顧，上貴琉璃，豈若寫帝台之基，拂崑山之碧，畫巧吳筆，素逾魏賜，冯商莫能賦，李尤誰敢銘。","sortOrder":33},
  {"id":"s_work_nvlt_69_34","chapterId":"ch_work_nvlt_69","text":"陳周弘正謝梁元帝赉春秋糊屏風啟曰：昔琉璃見重，雲母稱珍，雖盡華麗，有傷真朴，豈若三體五例，對玩前史，一字褒貶，坐臥箴規，無复楚台之風，得同邹穀之暖。","sortOrder":34},
  {"id":"s_work_nvlt_69_35","chapterId":"ch_work_nvlt_69","text":"【銘】後漢李尤屏風銘曰：舍則潛避，用則設張，立必端直，處必廉方，雍閼風雅，霧露是抗，奉上蔽下，不失其常。","sortOrder":35},
  {"id":"s_work_nvlt_69_36","chapterId":"ch_work_nvlt_69","text":"【書】梁簡文帝答萧子雲上飛白書屏風書曰：得所送飛白書缣屏風十牒，冠六書而獨美，超二篆而擅奇，乍寫星區，時圖鳥翅，非觀觸石，已覺雲飛，豈待金璫，便睹蝉翼，間諸衣帛，前哲未巧，懸彼帳中，昔賢掩色。","sortOrder":36},
  {"id":"s_work_nvlt_69_38","chapterId":"ch_work_nvlt_69","text":"《六韜》曰：將冬不服裘，夏不操扇，天雨不張幔蓋，名曰禮，將不知禮，無以知士卒寒暑也。","sortOrder":38},
  {"id":"s_work_nvlt_69_39","chapterId":"ch_work_nvlt_69","text":"《東觀漢記》曰：岑彭與吳漢围隗嚣，嚣壅穀水，以缣幔盛土，為堤灌城。","sortOrder":39},
  {"id":"s_work_nvlt_69_40","chapterId":"ch_work_nvlt_69","text":"《軍令》曰：戰時，皆取舡上布幔布衣渍水中，積聚之，賊有炬火火箭，以掩滅之。","sortOrder":40},
  {"id":"s_work_nvlt_69_41","chapterId":"ch_work_nvlt_69","text":"《蜀志》曰：張松勸劉璋絕曹公，交通先主，璋率步騎三萬餘人，車乘帳幔，精光耀日，往就與會。","sortOrder":41},
  {"id":"s_work_nvlt_69_42","chapterId":"ch_work_nvlt_69","text":"《秦記》曰：符永固以太常韦逞母宋，傳其父業，得周官義旨，乃就來宋家〈匚文〉［明本作互，冯校本作〈匚文〉。］講，書生百人，隔絳紗幔而受書焉。","sortOrder":42},
  {"id":"s_work_nvlt_69_43","chapterId":"ch_work_nvlt_69","text":"《世說》曰：庾太尉亮，風儀伟長，時皆以為美，亮有大兒，年數歲，雅量之质，便自如此，溫太真嘗隱幔视［《太平御覽》六百九十九作怛。］之，此兒神色恬然，乃徐跪曰：君侯何以為，論者乃謂不减亮。","sortOrder":43},
  {"id":"s_work_nvlt_69_44","chapterId":"ch_work_nvlt_69","text":"【詩】齊王融詠幔詩曰：幸得與珠缀，幂歷君之楹，月暎不辭卷，風來辄自輕，每聚金爐氣，時駐玉琴聲，但原致樽酒，蘭棋當夜明。","sortOrder":44},
  {"id":"s_work_nvlt_69_46","chapterId":"ch_work_nvlt_69","text":"《說文》曰：簟，竹席也。","sortOrder":46},
  {"id":"s_work_nvlt_69_47","chapterId":"ch_work_nvlt_69","text":"《釋名》曰：簟［《太平御覽》七百零八簟下有簟字。］也，布之覃然正平也。","sortOrder":47},
  {"id":"s_work_nvlt_69_48","chapterId":"ch_work_nvlt_69","text":"《禮記》曰：夫不在，斂枕簟席，韣器而藏之。","sortOrder":48},
  {"id":"s_work_nvlt_69_49","chapterId":"ch_work_nvlt_69","text":"又曰：莞簟之安，｛巩言｝秸之設也。","sortOrder":49},
  {"id":"s_work_nvlt_69_50","chapterId":"ch_work_nvlt_69","text":"《方言》曰：簟，宋魏之間謂之笙，［今江東乃言笙也。］《毛詩》曰：下莞上簟，乃安斯寢。","sortOrder":50},
  {"id":"s_work_nvlt_69_51","chapterId":"ch_work_nvlt_69","text":"《孫卿子》曰：輕暖平簟，而體不知其安。","sortOrder":51},
  {"id":"s_work_nvlt_69_52","chapterId":"ch_work_nvlt_69","text":"《淮南子》曰：席之上，先萑簟，樽之上，先玄酒，先王貴之，先本而後用末也。","sortOrder":52},
  {"id":"s_work_nvlt_69_53","chapterId":"ch_work_nvlt_69","text":"漢獻帝傳曰：尚書令王允奏曰：太史令王立，說孝經六隱事，能消却奸邪，常以良日，允與立入，為帝誦孝經一章，以丈二竹簟，畫九宮其上，隨日時而出入焉，及允被害，乃不复行也。","sortOrder":53},
  {"id":"s_work_nvlt_69_54","chapterId":"ch_work_nvlt_69","text":"晉公卿禮秩曰：太宰何曾遜位，賜簟褥一具。","sortOrder":54},
  {"id":"s_work_nvlt_69_55","chapterId":"ch_work_nvlt_69","text":"王隱《晉書》曰：車永為廣州刺史，永子溢，多使工作象牙細簟，工患之，乃共舉出永。","sortOrder":55},
  {"id":"s_work_nvlt_69_56","chapterId":"ch_work_nvlt_69","text":"《東宮舊事》曰：太子納妃，有乌韜赤花双文簟。","sortOrder":56},
  {"id":"s_work_nvlt_69_57","chapterId":"ch_work_nvlt_69","text":"【啟】梁劉孝儀謝始興王賜花紈簟啟曰：麗兼桃象，周洽昏明，便覺夏室已寒，冬裘可袭，雖九日煎沙，香粉猶弃，三旬沸海，团扇可捐。","sortOrder":57},
  {"id":"s_work_nvlt_69_58","chapterId":"ch_work_nvlt_69","text":"【書】梁簡文帝答定襄侯餉臥簟書曰：筠篁多品，筱簜雜名，校色比奇，獨此為貴，自舍蒼紫，似久暴於柯亭，乍舒黝素，若屢霑於湖水，三伏餘炎，九折成用，便可旅食南馆，高臥北窗。","sortOrder":58},
  {"id":"s_work_nvlt_69_59","chapterId":"ch_work_nvlt_69","text":"又答南平嗣王餉舞簟書曰：濯龍之木，文罽飾壇，淮南之台，紫羅為荐，未若五離九折，出桃枝之翠筍，綺烂霞舒，製雲母之修竹，南湘點淚，喻也未奇，東宮赤花，擬之非妙。","sortOrder":59},
  {"id":"s_work_nvlt_69_60","chapterId":"ch_work_nvlt_69","text":"◇荐席","sortOrder":60},
  {"id":"s_work_nvlt_69_61","chapterId":"ch_work_nvlt_69","text":"《釋名》曰：荐，所以自荐藉也，席，釋也，可卷可舒也。","sortOrder":61},
  {"id":"s_work_nvlt_69_62","chapterId":"ch_work_nvlt_69","text":"《說文》曰：蒻，蒲子也，可為荐。","sortOrder":62},
  {"id":"s_work_nvlt_69_63","chapterId":"ch_work_nvlt_69","text":"《六韜》曰：桀紂之時，婦女坐以文綺之席，衣以綾紈之衣。","sortOrder":63},
  {"id":"s_work_nvlt_69_64","chapterId":"ch_work_nvlt_69","text":"《毛詩》曰：我心匪席，不可卷也。","sortOrder":64},
  {"id":"s_work_nvlt_69_65","chapterId":"ch_work_nvlt_69","text":"《禮記》曰：群居五人，則長者必異席，夫為人子者，居不主奧，坐不中席。","sortOrder":65},
  {"id":"s_work_nvlt_69_66","chapterId":"ch_work_nvlt_69","text":"又曰：奉席如桥衡，請席何乡，請衽何趾，席南乡北乡，以西方為上，東乡西乡，以南方為上，若非飲食之客，則布席，席間函丈，主人跪正席，客跪撫席而辭，客彻重席，主人固辭，客踐席乃坐。","sortOrder":66},
  {"id":"s_work_nvlt_69_67","chapterId":"ch_work_nvlt_69","text":"又曰：哀公命席，孔子曰：儒有席上之珍以待聘。","sortOrder":67},
  {"id":"s_work_nvlt_69_68","chapterId":"ch_work_nvlt_69","text":"《大戴禮》曰：武王踐阼，席前左端之銘曰：安樂必敬，前右端之銘曰：無行可悔，後左端之銘曰：民一反一侧，爾不可不志，後右端之銘曰：所鑒不遠，视爾之所代。","sortOrder":68},
  {"id":"s_work_nvlt_69_69","chapterId":"ch_work_nvlt_69","text":"《左傳》曰：大路越席，昭其俭也。","sortOrder":69},
  {"id":"s_work_nvlt_69_70","chapterId":"ch_work_nvlt_69","text":"又曰：臧文仲不仁者三，妾織蒲，［家人販席，與民爭利也。］","sortOrder":70},
  {"id":"s_work_nvlt_69_71","chapterId":"ch_work_nvlt_69","text":"論語曰：席不正不坐，君賜食，必正席先嘗之。","sortOrder":71},
  {"id":"s_work_nvlt_69_72","chapterId":"ch_work_nvlt_69","text":"《家語》曰：明王之守也，則必折冲千里之外，其征也還師衽席之上，故曰內修七教而士不勞，外行三至而财不匮，此之謂明王之道。","sortOrder":72},
  {"id":"s_work_nvlt_69_73","chapterId":"ch_work_nvlt_69","text":"《楚辭》曰：瑤席兮玉镇。","sortOrder":73},
  {"id":"s_work_nvlt_69_74","chapterId":"ch_work_nvlt_69","text":"《呂氏春秋》曰：衛靈公天寒凿池，宛春諫曰：天寒起土，恐傷民，公曰：天寒乎，宛春曰：公衣狐裘，坐熊席，陬隅有竈，是以不寒，［事具寒部。］","sortOrder":74},
  {"id":"s_work_nvlt_69_75","chapterId":"ch_work_nvlt_69","text":"曾子曰：不勞不費之為明，可得而聞乎。","sortOrder":75},
  {"id":"s_work_nvlt_69_76","chapterId":"ch_work_nvlt_69","text":"孔子曰：昔者帝舜，左禹，右皋繇，不下席而天下治。","sortOrder":76},
  {"id":"s_work_nvlt_69_77","chapterId":"ch_work_nvlt_69","text":"《晏子》曰：景公獵休，坐地而食，晏子後至，滅葭而坐，公不悅，子獨席何也，對曰：臣聞介胄坐不席，獄訟不席，獄戶不席，三者皆忧也，臣故不敢以忧侍坐，公曰：善，令人下席，曰：大夫皆席，寡人亦席。","sortOrder":77},
  {"id":"s_work_nvlt_69_78","chapterId":"ch_work_nvlt_69","text":"子思曰：舜不降席而天下治，桀紂不降席而天下亂也。","sortOrder":78},
  {"id":"s_work_nvlt_69_79","chapterId":"ch_work_nvlt_69","text":"《莊子》曰：申徒嘉，兀者也，與鄭子產，同師合堂，同席而坐。","sortOrder":79},
  {"id":"s_work_nvlt_69_80","chapterId":"ch_work_nvlt_69","text":"魯連子曰：君所察者三，不可以不知，不知時與不時，譬猶春不耕也，不知行與不行，譬以方為輪也，不知宜與不宜，譬以錦緣荐也。","sortOrder":80},
  {"id":"s_work_nvlt_69_81","chapterId":"ch_work_nvlt_69","text":"《韓子》曰：趙簡子謂左右曰：車席泰美，夫冠雖惡，必戴之，履雖善，必履之，今車如此其大美也，吾將何以履之，且夫美而耗上，妨義之道。","sortOrder":81},
  {"id":"s_work_nvlt_69_82","chapterId":"ch_work_nvlt_69","text":"又曰：孟懿伯相魯，食不二味，坐不重席。","sortOrder":82},
  {"id":"s_work_nvlt_69_83","chapterId":"ch_work_nvlt_69","text":"《史記》曰：陳平以弊席為門。","sortOrder":83},
  {"id":"s_work_nvlt_69_84","chapterId":"ch_work_nvlt_69","text":"又曰：蘇秦激張儀，令相秦，以馬鞯席坐之。","sortOrder":84},
  {"id":"s_work_nvlt_69_85","chapterId":"ch_work_nvlt_69","text":"又曰：任安與田仁，俱為衛將軍舍人，居門下，衛將軍從此兩人過平陽公主家。令兩人與騎奴同席而食，此二子拔刀裂斷席，別坐，主家皆怪而惡之，莫敢問也。","sortOrder":85},
  {"id":"s_work_nvlt_69_86","chapterId":"ch_work_nvlt_69","text":"《漢武故事》曰：帝斋於尋真台，設紫羅荐。","sortOrder":86},
  {"id":"s_work_nvlt_69_87","chapterId":"ch_work_nvlt_69","text":"《東觀漢記》曰：更始至長安，止前殿，郎吏以次侍，更始愧恧，俯刮席，與小常侍語。","sortOrder":87},
  {"id":"s_work_nvlt_69_88","chapterId":"ch_work_nvlt_69","text":"又曰：王常與橫野大將軍位次，與諸將絕席。","sortOrder":88},
  {"id":"s_work_nvlt_69_89","chapterId":"ch_work_nvlt_69","text":"又曰：黃香家素貧，躬執勤苦，盡心供養，暑則扇床枕，寒則自溫席。","sortOrder":89},
  {"id":"s_work_nvlt_69_90","chapterId":"ch_work_nvlt_69","text":"又曰：張禹為太傅尚書，邓太後以殇帝初育，欲令重臣居禁內，乃詔禹與三公絕席。","sortOrder":90},
  {"id":"s_work_nvlt_69_91","chapterId":"ch_work_nvlt_69","text":"又曰：宣帝，［《太平御覽》七百零九，作秉，此訛。］建武元年拜御史中丞，上特詔御史中丞與司隸校尉尚書令，會同併专席而坐，故京師號曰三獨坐。","sortOrder":91},
  {"id":"s_work_nvlt_69_92","chapterId":"ch_work_nvlt_69","text":"謝承《後漢書》曰：戴凭徵博士，詔公卿大會，群臣皆就席，凭獨立，世祖問其意，對曰：博士說經，皆不如臣，而坐居臣上，是以不得就席，帝令與諸儒難說，帝善之，後正旦朝贺，令群臣說經，更相難詰，義有不通，辄奪其席以益通者，凭遂重坐五十餘席，故京師語曰：解經不窮戴侍中。","sortOrder":92},
  {"id":"s_work_nvlt_69_93","chapterId":"ch_work_nvlt_69","text":"又曰：許敬，字鸿卿，其吏有誣君者，會於縣令坐，敬拔刀斷其席曰：敬不忍與惡人同席。","sortOrder":93},
  {"id":"s_work_nvlt_69_94","chapterId":"ch_work_nvlt_69","text":"盧毓冀州論曰：常山為林，大陆為泽，蒹葭蒲苇，雲母御席。","sortOrder":94},
  {"id":"s_work_nvlt_69_95","chapterId":"ch_work_nvlt_69","text":"《汝南先賢傳》曰：鄭敬以蒹葭為席，常隨杞柳之陰。","sortOrder":95},
  {"id":"s_work_nvlt_69_96","chapterId":"ch_work_nvlt_69","text":"《雜記》曰：吳議郎張純，詣镇南將軍朱據，據曰：為賦一物，然後乃坐，純賦曰：席為冬設，簟為夏施，揖讓而坐，君子攸宜。","sortOrder":96},
  {"id":"s_work_nvlt_69_97","chapterId":"ch_work_nvlt_69","text":"皇甫謐《高士傳》曰：老萊子親没，隱蒙山之陽，枝木為床，艾為席。","sortOrder":97},
  {"id":"s_work_nvlt_69_98","chapterId":"ch_work_nvlt_69","text":"《世說》曰：管寧與華歆同席讀書，有軒冕過門者，寧讀書如故，歆废書出看，寧割席分坐，曰：子非吾友也。","sortOrder":98},
  {"id":"s_work_nvlt_69_99","chapterId":"ch_work_nvlt_69","text":"《說苑》曰：孔子困於陳蔡之間，居環堵之內，坐三經之席。","sortOrder":99},
  {"id":"s_work_nvlt_69_100","chapterId":"ch_work_nvlt_69","text":"【詩】齊謝朓詠席詩曰：本生朝夕池，落景照參差，河洲蔽杜若，幽渚奪江離，遇君時采撷，玉坐奉金卮，但原羅衣拂，無使素尘弥。","sortOrder":100},
  {"id":"s_work_nvlt_69_101","chapterId":"ch_work_nvlt_69","text":"梁柳惲詠席詩曰：照日汀洲际，搖風渌潭侧，雖無獨茧輕，幸有青袍色，羅袖少輕尘，象床多麗飾，原君夜阑飲，佳人時安息。","sortOrder":101},
  {"id":"s_work_nvlt_69_102","chapterId":"ch_work_nvlt_69","text":"【銘】後漢李尤席銘曰：施席接賓，士無過賢，直時所有，何必羊豚。","sortOrder":102},
  {"id":"s_work_nvlt_69_104","chapterId":"ch_work_nvlt_69","text":"《說文》曰：案，幾屬也。","sortOrder":104},
  {"id":"s_work_nvlt_69_105","chapterId":"ch_work_nvlt_69","text":"《燕太子》曰：太子常與荆軻等案而食。","sortOrder":105},
  {"id":"s_work_nvlt_69_106","chapterId":"ch_work_nvlt_69","text":"《史記》曰：漢七年，高祖過趙，趙王張敖，自持案進食，禮甚恭，高祖箕踞骂之。","sortOrder":106},
  {"id":"s_work_nvlt_69_107","chapterId":"ch_work_nvlt_69","text":"《楚漢春秋》曰：項王使武涉說淮陰侯，信曰：臣事項王，位不過中郎，官不過執戟，乃去項歸漢，漢王賜臣玉案之食，玉具之劍，臣背叛之，內愧於心。","sortOrder":107},
  {"id":"s_work_nvlt_69_108","chapterId":"ch_work_nvlt_69","text":"《烈士傳》曰：魏公子方食，有鳩飛入其案下，公子怪之，此有何急，來歸無忌耶，使人於殿下视之，左右顧望，一鷂在屋上而飛。","sortOrder":108},
  {"id":"s_work_nvlt_69_109","chapterId":"ch_work_nvlt_69","text":"《鹽鐵論》曰：良民文杯畫案，婢妾衣紈履絲，匹庶粺飯肉食，所以亂治也。","sortOrder":109},
  {"id":"s_work_nvlt_69_110","chapterId":"ch_work_nvlt_69","text":"《漢書》曰：萬石君石奋，子孫為小吏，歸謁，萬石君必朝服見之，不名，子孫有過失，不誚讓，為便坐，對案不食，然後諸子相责，因長老肉袒謝罪，改之乃許。","sortOrder":110},
  {"id":"s_work_nvlt_69_111","chapterId":"ch_work_nvlt_69","text":"又曰：上欲封傅太後從弟商，鄭崇諫，持詔案起，薄［漢書七十七鄭崇傳作傅。］太後大怒曰：何有為天子，反為一臣所製耶。","sortOrder":111},
  {"id":"s_work_nvlt_69_112","chapterId":"ch_work_nvlt_69","text":"又曰：朱博為御史大夫，為人廉，不好酒色之宴，自微賤至富貴，食不重味，案上不過三杯。","sortOrder":112},
  {"id":"s_work_nvlt_69_113","chapterId":"ch_work_nvlt_69","text":"《漢武故事》曰：武帝時，東郡獻短人，長五寸，上疑其山精，常令案上行，東方朔問曰：巨靈，汝何以叛，阿母健不。","sortOrder":113},
  {"id":"s_work_nvlt_69_114","chapterId":"ch_work_nvlt_69","text":"《東觀漢記》曰：更始韓夫人，尤嗜酒，每侍飲，見常侍奏事，辄怒曰：帝方對我，正用此時持事來乎，起抵破書案。","sortOrder":114},
  {"id":"s_work_nvlt_69_115","chapterId":"ch_work_nvlt_69","text":"又曰：尹敏與班彪相厚，每相與語，嘗屏案不食。","sortOrder":115},
  {"id":"s_work_nvlt_69_116","chapterId":"ch_work_nvlt_69","text":"又曰：梁鸿適吳，依大家皋伯通庑下，為人賃舂，妻為具食，不敢於鸿前仰视，舉案齊眉，伯通異之曰：彼佣賃能使其妻敬之如此，非凡人也。","sortOrder":116},
  {"id":"s_work_nvlt_69_117","chapterId":"ch_work_nvlt_69","text":"《神仙傳》曰：茅君當受神靈之職，眾賓皆至，忽然自有青缣帳，於屋下，數重白氈，金案玉杯，人皆飽醉。","sortOrder":117},
  {"id":"s_work_nvlt_69_118","chapterId":"ch_work_nvlt_69","text":"《江表傳》曰：曹公平荆州，仍欲伐吳，張昭等皆勸迎曹公，唯周瑜魯肅諫拒之，孫權拔刀斫前奏案曰：諸將复有言迎北軍者，與此案同。","sortOrder":118},
  {"id":"s_work_nvlt_69_119","chapterId":"ch_work_nvlt_69","text":"【銘】梁簡文帝書案銘曰：刻香鏤彩，纖銀卷足，照色黃金，回花青玉，漆華映紫，畫製舒绿，性廣知平，文雕非曲，廁质錦帷，承芳綺縟，敬客禮賢，恭思俨束，披古通今，察奸理俗，仁義可安，忠貞自燭，鑒矣勒銘，知微敬勖。","sortOrder":119},
  {"id":"s_work_nvlt_69_121","chapterId":"ch_work_nvlt_69","text":"《莊子》曰：南郭子綦，隱幾而坐，仰天而噓，嗒焉似丧其偶，顏成子遊，立侍乎前，曰：何居乎，形固可使如槁木，心固可使如死灰乎，今之隱幾者，非昔之隱幾也，［子綦昔隱幾不然乎，今何故更然。］","sortOrder":121},
  {"id":"s_work_nvlt_69_122","chapterId":"ch_work_nvlt_69","text":"《戰國策》曰：郭隗謂燕昭王，隱幾據杖，眄视相使，則厮役之人至。","sortOrder":122},
  {"id":"s_work_nvlt_69_123","chapterId":"ch_work_nvlt_69","text":"《左傳》曰：諸侯之師，久於偪陽，荀偃士匄，請於荀罃曰：水潦將降，懼不能歸，請班師，智伯怒，［智伯，荀罃也。］投之以幾，出於其間。","sortOrder":123},
  {"id":"s_work_nvlt_69_124","chapterId":"ch_work_nvlt_69","text":"《漢書》曰：朱博遷琅邪太守，齊郡舒缓養名，博奋髯抵［抵音紙。］幾曰：觀齊兒欲以此為俗耶，乃召見諸曹史書佐及縣太史，［漢書八十三朱博傳作大吏。］選其可用者。","sortOrder":124},
  {"id":"s_work_nvlt_69_125","chapterId":"ch_work_nvlt_69","text":"又曰：平帝詔太師孔光曰：聖人之後，先師之子，德行純淑，道術通明，居四辅，辅导於帝，今年耆有疾，俊乂大臣，惟國之重，書曰：母遺耇老，國之將興，尊師而重傅，其令太師，每朝十日一賜餐，賜太師靈寿杖，令為太師省坐置幾，太師省中用杖。","sortOrder":125},
  {"id":"s_work_nvlt_69_126","chapterId":"ch_work_nvlt_69","text":"《續漢書》曰：大將軍何進，辟鄭玄，玄以進辟權戚，不敢违意，不得已而詣之，進為設幾杖，待之甚優，玄不受朝服，而以幅巾見，一宿逃去。","sortOrder":126},
  {"id":"s_work_nvlt_69_127","chapterId":"ch_work_nvlt_69","text":"《九州春秋》曰：孔融為北海太守，為袁谭所攻，流矢雨集，矛戟內接，然融凭幾安坐，讀書論義自若也。","sortOrder":127},
  {"id":"s_work_nvlt_69_128","chapterId":"ch_work_nvlt_69","text":"【詩】齊謝朓詠乌皮隱幾詩曰：蟠木生附枝，刻削豈無施，取則龍文鼎，三趾獻光儀，勿言素韦絜，白沙尚推移，曲躬奉微用，聊承終宴疲。","sortOrder":128},
  {"id":"s_work_nvlt_69_130","chapterId":"ch_work_nvlt_69","text":"《史記》曰：張騫曰：臣在大夏時，見邛竹杖蜀布，問曰：安得此，大夏國人曰：吾贾人往市之身毒國，身毒國在大夏東南，可數千里。","sortOrder":130},
  {"id":"s_work_nvlt_69_131","chapterId":"ch_work_nvlt_69","text":"魯連子曰：連却秦軍，平原君欲封之，終不肯受，平原君乃置酒，酒酣起前，以千金為寿，先生笑曰：所貴天下之士者，為排患釋難，解人之締結，即是有取，商贾之事，連不忍也，遂杖策而去。","sortOrder":131},
  {"id":"s_work_nvlt_69_132","chapterId":"ch_work_nvlt_69","text":"《呂氏春秋》曰：孔子之弟子，從遠方來者，孔子荷杖而問之曰：子之父不有恙乎，摶杖而問之曰：子之母不有恙乎，置杖而問之曰：子之兄弟不有恙乎，杖步而陪之，問曰：子之妻子不有恙乎，故孔子六尺之杖，論貴賤之禮，辯親疏之義。","sortOrder":132},
  {"id":"s_work_nvlt_69_133","chapterId":"ch_work_nvlt_69","text":"《韓子》曰：周王下令，索曲杖，吏求之不得，使私求，得之，乃曰：吾知吏不事他事也，杖甚易得，而不能得，我令人求，不移日得之，豈謂忠哉。","sortOrder":133},
  {"id":"s_work_nvlt_69_134","chapterId":"ch_work_nvlt_69","text":"【詩】梁到溉餉任新安班竹杖因赠詩曰：邛竹藉舊聞，靈寿資前識，复有冒霜筠，寄生桂潭侧，文彩既班烂，质性甚綢直，所以夭天真，為有乘危力，未嘗以過投，屢經芸苗植。","sortOrder":134},
  {"id":"s_work_nvlt_69_135","chapterId":"ch_work_nvlt_69","text":"梁任昉答到建安餉杖詩曰：故人有所赠，稱以冒霜筠，定是湘妃淚，潛洒遂鄰彬，扶危复防咽，事歸薄暮人，勞君尚齒意，矜此杖乡辰，复資後生彦，候餘方欠伸，獻君千里笑，纾我百忧嚬，坐適雖有器，臥遊苦無津，何由乘此竹，直見平生親。","sortOrder":135},
  {"id":"s_work_nvlt_69_136","chapterId":"ch_work_nvlt_69","text":"【賦】晉張翰杖賦曰：惟萬物之品分，何利人之獨貴，中神性之極妙，豈給口之至味，雖至味之御內，乃靡失乎身外，舍少壮之自然，假扶我之攸賴，良工登乎曾峦，妙匠鑒乎林阿，顧眄乎晞陽之條，投刃乎直理之柯，方圓適意，洪細可手，足畜蠋旦夕，欲與永久，儀製财於一尋，假飾存乎尾首，瑩牙為其眉嵒，朗金為其觜距。","sortOrder":136},
  {"id":"s_work_nvlt_69_137","chapterId":"ch_work_nvlt_69","text":"周庾信竹杖賦曰：桓宣武平荆州，外白有人稱楚丘先生，來詣門下，桓公曰：名父之子，流離江漢，孤之责矣，及令引進，乃曰：噫子老矣，鶴發雞皮，蓬頭櫪齒，乃是江漢英靈，荆衡杞梓，雖有聞於十室，幸無求於千里，寡人有銅環靈寿，銀角桃枝，开木瓜而未落，養莲花而不萎，迎仙容於錦市，送遊龍於葛陂，先生將以養老，將以扶危，先生笑而言曰：中國明於禮義，暗於知人，心之忧矣，唯我生民，雖复疏條劲柘，促節貞筠，枝端刻鳥，角首圖麟，豈念相餘有疾，將餘此身，餘此衰矣，雖然有以，非鬼非蜮，乃心忧矣，未見從心，先求順耳，伯玉何嗟，丘明唯恥，別有九棘厖眉，三槐暮齒，孔光謝疾，袁逢致仕，明公此赠，或非乖理。","sortOrder":137},
  {"id":"s_work_nvlt_69_138","chapterId":"ch_work_nvlt_69","text":"【頌】王粲靈寿杖頌曰：茲杖靈木，以介眉寿，奇幹貞正，不待矯輮，據貞斯直，杖之爰茂。","sortOrder":138},
  {"id":"s_work_nvlt_69_139","chapterId":"ch_work_nvlt_69","text":"【贊】晉郭璞桃杖贊曰：丛薄幽薈，從風蔚猗，簟以寧寢，杖以扶危。","sortOrder":139},
  {"id":"s_work_nvlt_69_140","chapterId":"ch_work_nvlt_69","text":"【銘】漢劉向杖銘曰：歷危乘险，匪杖不行，年耆力竭，匪杖不彊，有杖不任，顛跌誰怨，有士不用，害何足言，都蔗雖甘，殆不可杖，佞人悅己，亦不可相，杖必取便，不必用味，士必任賢，何必取貴。","sortOrder":140},
  {"id":"s_work_nvlt_69_141","chapterId":"ch_work_nvlt_69","text":"後漢李尤靈寿杖銘曰：亭亭奇幹，寔曰靈寿，甘泉润根，清露流茎，乃製為杖，扶危定傾，既凭其實，亦貴其名。","sortOrder":141},
  {"id":"s_work_nvlt_69_142","chapterId":"ch_work_nvlt_69","text":"後漢冯衍杖銘曰：杖莫如信，行莫如仁，惠而無實，怨及爾身，趙武之珍，子罕之寶，二子之跡，蓋近於道。","sortOrder":142},
  {"id":"s_work_nvlt_69_143","chapterId":"ch_work_nvlt_69","text":"晉蘇彦邛竹杖銘曰：安不忘危，任在所杖，秀矣雲竹，劲直筱簜，節高质貞，霜雪弥亮，圓以應物，直以居當，妙巧無功，奇不待匠，君子是扶，逍遙神王。","sortOrder":143},
  {"id":"s_work_nvlt_69_144","chapterId":"ch_work_nvlt_69","text":"晉殷允杖銘曰：二老晨征，匪杖不遠，四皓降趾，匪杖不反，翼德扶耆，舍杖焉資，辅相天地，匪賢而誰，荃蕙雖秀，才非貞质，異端雖美，道無玄術，杖必不撓，無取苒弱，人貴一德，勿惑穿凿。","sortOrder":144},
  {"id":"s_work_nvlt_69_145","chapterId":"ch_work_nvlt_69","text":"晉傅鹹邛竹杖銘曰：嘉茲奇竹，质劲體直，立比高節，示世於式。","sortOrder":145},
  {"id":"s_work_nvlt_69_146","chapterId":"ch_work_nvlt_69","text":"晉劉柔妻王氏靈寿杖銘曰：籊々鮮幹，秀彼崇氵急，下泽蘭液，上瑩芳霄，貞劲內固，鮮粲外昭，耀质靈薈，作珍華朝，杖之身安，越齡松乔。","sortOrder":146},
  {"id":"s_work_nvlt_69_147","chapterId":"ch_work_nvlt_69","text":"梁簡文帝錫杖銘曰：妙飾嘉光，遊聖振灼，排空霧轉，騰雲鳳躍，永異玉神，長逾金错。","sortOrder":147},
  {"id":"s_work_nvlt_69_149","chapterId":"ch_work_nvlt_69","text":"《春秋繁露》曰：美事召美類，惡事召惡類，類之相應而起也，如馬鳴則馬應之，故以龍致雨，以扇逐暑，軍之所處，生以棘楚，美惡皆有從來也。","sortOrder":149},
  {"id":"s_work_nvlt_69_150","chapterId":"ch_work_nvlt_69","text":"《淮南子》曰：夫夏日不披裘者，非愛之也，暖有餘於身也，冬日不用翣者，非簡之也，清有餘於適也。","sortOrder":150},
  {"id":"s_work_nvlt_69_151","chapterId":"ch_work_nvlt_69","text":"又曰：炎火凿池，披裘而扇，不能救也。","sortOrder":151},
  {"id":"s_work_nvlt_69_152","chapterId":"ch_work_nvlt_69","text":"《語林》曰：庾廙為荆州都督，以毛扇上成帝，帝疑是故物，侍中劉劭曰：柏梁雲構，工匠先居其下，管絃繁奏，夔牙先聆其音，廙之此扇，以好不以新。","sortOrder":152},
  {"id":"s_work_nvlt_69_153","chapterId":"ch_work_nvlt_69","text":"《續晉陽秋》曰：謝安賞袁宏機對辯速，後宏出為東陽郡，時賢祖道治［世說新語言語篇註作冶。］亭，安起執宏手，顧就左右，取一扇授雲，聊以赠行，宏應聲答曰：辄當奉扬仁風，慰彼黎庶，合座稱其率而當。","sortOrder":153},
  {"id":"s_work_nvlt_69_154","chapterId":"ch_work_nvlt_69","text":"【詩】晉許詢竹扇詩曰：良工眇芳林，妙思觸物騁，蔑疑秋翼蝉，团取望舒景。","sortOrder":154},
  {"id":"s_work_nvlt_69_155","chapterId":"ch_work_nvlt_69","text":"齊丘巨源詠七寶团扇詩曰：裁状白玉璧，縫似明月輪，表里鏤七寶，中衔駭雞珍，畫作景山树，圖為河洛神，生風長袖际，晞華紅柳津，拂盼迎娇意，隱映含歌人。","sortOrder":155},
  {"id":"s_work_nvlt_69_156","chapterId":"ch_work_nvlt_69","text":"梁簡文帝賦得白羽扇詩曰：可怜白羽扇，却暑复來氛，終無顧庶子，誰為一揮軍。","sortOrder":156},
  {"id":"s_work_nvlt_69_157","chapterId":"ch_work_nvlt_69","text":"梁何遜詠扇詩曰：如珪信非玷，學月且為輪，搖風入素手，召曲掩丹唇。","sortOrder":157},
  {"id":"s_work_nvlt_69_158","chapterId":"ch_work_nvlt_69","text":"梁庾肩吾賦得轉歌扇詩曰：团紗映似月，蝉翼望如空，回持掩曲態，轉作送聲風。","sortOrder":158},
  {"id":"s_work_nvlt_69_159","chapterId":"ch_work_nvlt_69","text":"梁高爽詠畫扇詩曰：細絲本自輕，弱采何足眄，直為發紅顏，谬成幄中扇，乍奉長門泣，時承柏梁宴，思妆开已掩，歌容隱而見，但畫双黃鵠，莫作孤飛燕。","sortOrder":159},
  {"id":"s_work_nvlt_69_160","chapterId":"ch_work_nvlt_69","text":"陳許倪詠破扇詩曰：蔽日無全影，搖風有半涼，不堪鄣巧笑，猶足動衣香。","sortOrder":160},
  {"id":"s_work_nvlt_69_161","chapterId":"ch_work_nvlt_69","text":"漢班婕妤扇詩曰：新裂齊紈素，鮮絜如霜雪，裁成合歡扇，团团似明月，出入君懷袖，動搖微風發，常恐秋節至，涼梠奪炎熱，弃捐箧笥中，恩情中道絕。","sortOrder":161},
  {"id":"s_work_nvlt_69_162","chapterId":"ch_work_nvlt_69","text":"漢班固竹扇詩曰：供時有度量，異好有团方，來風堪避暑，靜夜致清涼。","sortOrder":162},
  {"id":"s_work_nvlt_69_163","chapterId":"ch_work_nvlt_69","text":"【賦】魏陳王曹植九華扇賦曰：昔吾先君常侍，得幸漢桓帝，帝賜尚方竹扇，不方不圓，其中結成文，名曰九華，其辭曰：有神區之名竹，生不周之高岑，對渌水之素波，背玄涧之重深，體虛畅以立幹，播翠葉以成秋，形五離而九折，蔑氂解而縷分，效虬龍之蜿蜒，法虹蜺之煙煴，因形致好，不常厥儀，方不應矩，圓不中規，隨皓腕以徐轉，發惠風之微寒，時氣清以芳厲，紛飄動乎綺紈。","sortOrder":163},
  {"id":"s_work_nvlt_69_164","chapterId":"ch_work_nvlt_69","text":"吳闵鸿羽扇賦曰：惟羽扇之攸興，乃鳴鸿之嘉容，產九華之中泽，邁雍喈之天聰，表高義於太易，著詩人之雅章，賴茲翮以內飛，曜羽儀於外扬，於時祝融持運，朱明發暉，奔陽冲布，飛炎赫曦，同煴隆於雲漢，鹹惨毒於中懷，爾乃登爽垲，臨甘泉，漱清流，荫玄雲，運輕翮以容與，激清風於自然，披绡衽而入懷，飛羅纓之繽紛，眾坐侃以怡怿，鹹俯節以齊歡，感蕙風之荡懷，詠棘心之所歡，於是暑氣雲消，獻酬乃設，停神靜思，且以永日，妍羽詳回，清風盈室，動靜扬暉，嘉好越逸，翻翻弈弈，飛景曜日，同曒素於凝霜，豈振露之能匹。","sortOrder":164},
  {"id":"s_work_nvlt_69_165","chapterId":"ch_work_nvlt_69","text":"晉張載扇賦曰：有翔雲之素鳥，體自然之至絜，飄縞羽於清霄，擬妙姿於白雪，俯濯素於河漢，仰晞光於日月，双趾蹶而騰虛，六翮揮而風厲，於是傲世公子，俶傥踔跞，遺物獨出，樂此天爵，飛蒲氏之修蟠，榮子餘之纖繳，弋翔冥之鵾雞，連王子之白鶴，裁輕翼以為扇，發清風於劲翮，若乃搜奇選妙，絕色寡双，皓质曒鮮，玄的點鋒，修短雖異，而光彩齊同，故易稱可以為儀，詩美肅肅之容，是以停之如栖鵠，揮之如驚鸿，飄纓蕤於軒幌，發暉曜於群龍，夫裂素製圓，剖竹為方，五明起於名都，九華興於上京。","sortOrder":165},
  {"id":"s_work_nvlt_69_166","chapterId":"ch_work_nvlt_69","text":"晉傅鹹羽扇賦曰：吳人截鳥翼而搖風，既勝於方圓二扇，而中國莫有生意，滅吳之後，翕然貴之，其辭曰：鳳皇於飛，翙翙其羽，况靈體以遐翔，匪六翮其焉舉，感扇扬之興風，宜收之以清暑，彼安眾之雲妙，差剖篾於毫縷，體荏苒以輕弱，侔縞素於齊魯，此因資以為用，不假裁於規矩，雖靡飾於容好，亦差池而有序，上比列於南箕，下等美於箑甫。","sortOrder":166},
  {"id":"s_work_nvlt_69_167","chapterId":"ch_work_nvlt_69","text":"又扇賦曰：天道行而不息，四節代以相尋，背青春之令月，踐朱夏於斯今，熱融融以太甚，孰赫赫之可任，汗珠陨以外流，氣鬱結而內沉，庶凯風之自南，競清嘯而啟衿，怨微飄之不興，恨乔木之無陰，搖輕扇之冉弱，手才動而〈忄盡〉心，心取〈忄盡〉於卷握，尚何希乎北林，下濟亿兆，上寧侯王，是曰安眾，清暑作涼，蒙貴幸於斯時，無日夜而有忘，謂洪恩之可固，終靡弊於君旁，火星忽以西流，悲風起乎金商，秋日凄凄，白露為霜，體斂然以思暖，御輕裘於溫房，猥弃我其若遺，去玉手而潛藏，君背故而向新，非餘身之無良，哀徒勞而靡報，獨懷怨於一方。","sortOrder":167},
  {"id":"s_work_nvlt_69_168","chapterId":"ch_work_nvlt_69","text":"晉陆機羽扇賦曰：昔楚襄王會於章台之上，山西與河右諸侯在焉，大夫宋玉唐勒侍，皆操白鶴之羽以為扇，諸侯掩麈尾而笑，襄王不悅，宋玉趨而進曰：敢問諸侯何笑，昔者武王玄覽，造扇於前，而五明安眾，世繁於後，各有讬於方圓，蓋受則於箑甫，舍茲器而不用，顧奚取於鳥羽，宋玉曰：夫創始者恒朴，而飾終者必妍，是故烹飪起於熱石，玉辂基於椎輪，安眾方而氣散，五明圓而風煩，未若茲羽之為麗，固體後而用鮮，於是鏤巨獸之齒，裁奇木之幹，憲靈朴於造化，審貞則而妙觀，諸侯曰：善，宋玉遂言曰：伊茲羽之駿敏，似南箕之啟扉，垂皓曜之弈弈，含鮮風之微微，襄王仰而拊節，諸侯伏而引非，皆委扇於楚庭，執鳥羽而言歸，屬唐勒而為之亂曰：伊鮮禽之令羽，夫何翩翩與眇眇，反寒暑於一堂之末，回八風乎六翮之杪。","sortOrder":168},
  {"id":"s_work_nvlt_69_169","chapterId":"ch_work_nvlt_69","text":"晉江逌扇賦曰：惟羽類之攸出，生東南之遐嵎，育庶族於雲夢，散宗儔於具區，色非一采，或素或玄，肌平理畅，琼泽冰鮮，戢之則藏，奋之則舉，舍之以寒，用之以暑，製舒疾於一掌，引長風乎焜衿，荡煩垢於體外，流妙氣於中心。","sortOrder":169},
  {"id":"s_work_nvlt_69_170","chapterId":"ch_work_nvlt_69","text":"梁昭明太子扇賦曰：匠人之巧製，女工之妙織，九折翠竹之枝，直截飛禽之翼，雖复草木燋枯，金沙銷鑠，火山炽，寒泉涸，能使凄兮似秋，隆暑斯却。","sortOrder":170},
  {"id":"s_work_nvlt_69_171","chapterId":"ch_work_nvlt_69","text":"梁江淹扇上采畫賦曰：臨淄之稚女，宋鄭之妙工，織素麗於日月，傳畫明於采虹，洛陽之伎極，江南之巧窮，故飾以赤野之玉，文以紫山之金，粉則南陽之鉛泽，墨則上党之松心，玉琴兮珠徽，素女兮錦衣，促織兮始鳴，秋蛾兮初飛，識桂茎之就罢，知蘭葉之行衰。","sortOrder":171},
  {"id":"s_work_nvlt_69_172","chapterId":"ch_work_nvlt_69","text":"梁周興白鶴羽扇賦曰：衔明珠以報德，訪在陰而陽止，既來集於衛軒，亦傾舞於吳市，骈瑤剪雪，盈華寫絜，通脊似介，點首如翳，萦吹動發，環涼入衣，凄兮若秋之暮，懍兮如雪之飛。","sortOrder":172},
  {"id":"s_work_nvlt_69_173","chapterId":"ch_work_nvlt_69","text":"【頌】晉劉臻妻五時畫扇頌曰：炎後飛軌，引曜丹逵，蕤賓應律，融精协曦，五象列位，品物以垂，兑降素獸，震升青螭，日月澄暉，仙童來儀，仰憩翠巖，俯映蘭池，靈柯幽藹，神卉參差，如山之寿，如松之猗，永錫難老，與時推移。","sortOrder":173},
  {"id":"s_work_nvlt_69_174","chapterId":"ch_work_nvlt_69","text":"【贊】宋謝惠連白羽扇贊曰：唯茲白羽，體此皎絜，涼齊清風，素同白雪，揮之衿袖，以御炎熱。","sortOrder":174},
  {"id":"s_work_nvlt_69_175","chapterId":"ch_work_nvlt_69","text":"【銘】梁庾肩吾团扇銘曰：武王玄覽，造扇於前，班生贍博，白綺仍傳，裁筠比霧，裂素輕蝉，片月內掩，重規外圓，炎隆火正，石鑠沙煎，清逾蘋末，瑩等寒泉，思深難恃，愛極則遷，秋風飒至，箧笥長捐，勒銘華扇，敢荐夏筵。","sortOrder":175},
  {"id":"s_work_nvlt_69_176","chapterId":"ch_work_nvlt_69","text":"梁簡文帝紗扇銘曰。","sortOrder":176},
  {"id":"s_work_nvlt_69_177","chapterId":"ch_work_nvlt_69","text":"發曜光","sortOrder":177},
  {"id":"s_work_nvlt_69_179","chapterId":"ch_work_nvlt_69","text":"風─┼─空","sortOrder":179},
  {"id":"s_work_nvlt_69_181","chapterId":"ch_work_nvlt_69","text":"霜照月","sortOrder":181},
  {"id":"s_work_nvlt_69_182","chapterId":"ch_work_nvlt_69","text":"【啟】齊王融謝竟陵王示扇啟曰：竊以六翮風流，五明氣重，若此圓绡，有兼玩實，輕逾雪羽，絜併霜文，子淑賞其如規，班姬俪之明月，豈直魏王九華，漢臣百綺，况复動製聖衷，垂言炯戒，載摹聽皃，式范枢機。","sortOrder":182},
  {"id":"s_work_nvlt_69_183","chapterId":"ch_work_nvlt_69","text":"◇麈尾","sortOrder":183},
  {"id":"s_work_nvlt_69_184","chapterId":"ch_work_nvlt_69","text":"《世說》曰：康法畅造庾公，捉麈尾甚佳，公曰：麈尾過麗，何以得在，答曰：廉者不取，貪者不與，故得在耳。","sortOrder":184},
  {"id":"s_work_nvlt_69_185","chapterId":"ch_work_nvlt_69","text":"【詩】梁宣帝詠麈尾詩曰：匣上生光影，豪际起風流，本持談妙理，寧是用摧牛。","sortOrder":185},
  {"id":"s_work_nvlt_69_186","chapterId":"ch_work_nvlt_69","text":"【銘】晉王导麈尾銘曰：道無常貴，所適惟理，勿謂质卑，御於君子，拂秽清暑，虛心以俟。","sortOrder":186},
  {"id":"s_work_nvlt_69_187","chapterId":"ch_work_nvlt_69","text":"宋張悅玳瑁麈尾銘曰：移珍西嶽，費藻南濆，凝華淡景，搖采爭雲，夷心似鏡，色象斯分。","sortOrder":187},
  {"id":"s_work_nvlt_69_188","chapterId":"ch_work_nvlt_69","text":"陳徐陵麈尾銘曰：爰有妙物，窮茲巧製，員上天形，平下地势，靡靡絲垂，綿綿縷細，入貢宜吳，出先陪楚，壁懸石拜，帳中王舉，既落天花，亦通神語，用動舍默，出處隨時，扬斯雅論，釋此繁疑，拂靜尘暑，引飾妙詞，誰雲质賤，左右宜之。","sortOrder":188},
  {"id":"s_work_nvlt_69_189","chapterId":"ch_work_nvlt_69","text":"【啟】梁湘東王謝東宮賜麈尾錦帔团扇等啟曰：楊雄口讷，本貴談端，田蚡貌寢，終於麗飾，始興之扇，方斯非擬，鄴中之錦，匹此為輕，方原弘此仁風，既動承華之氣，服茲懷袖，复比文若之香。","sortOrder":189},
  {"id":"s_work_nvlt_69_190","chapterId":"ch_work_nvlt_69","text":"《藝文類聚》　唐·欧陽詢","sortOrder":190},
  {"id":"s_work_nvlt_70_1","chapterId":"ch_work_nvlt_70","text":"卷七十服飾部下","sortOrder":1},
  {"id":"s_work_nvlt_70_2","chapterId":"ch_work_nvlt_70","text":"○枕被縟如意胡床火籠香爐步搖釵梳枇囊鏡襪","sortOrder":2},
  {"id":"s_work_nvlt_70_4","chapterId":"ch_work_nvlt_70","text":"《毛詩》曰：角枕粲兮。","sortOrder":4},
  {"id":"s_work_nvlt_70_5","chapterId":"ch_work_nvlt_70","text":"《禮記》曰：父母舅姑之枕幾不傳。","sortOrder":5},
  {"id":"s_work_nvlt_70_6","chapterId":"ch_work_nvlt_70","text":"又曰：凡內外，雞初鳴，鹹盥漱，斂枕簟。","sortOrder":6},
  {"id":"s_work_nvlt_70_7","chapterId":"ch_work_nvlt_70","text":"《越絕書》曰：越王問范子曰：寡人已聞陰陽之事，穀之貴賤，可得而聞乎，曰：陽者主貴，陰者主賤，故當寒而溫者，穀為之暴貴，當溫而寒者，穀為之暴賤，王曰：善，書之帛，置之枕中，以為國寶。","sortOrder":7},
  {"id":"s_work_nvlt_70_8","chapterId":"ch_work_nvlt_70","text":"《史記》曰：黥布反，上乃見薛公，薛公對曰：布不足怪也，使布出上計，山東非漢之有，出中計，未可知，出下計，陛下安枕而臥矣，《神仙傳》曰：泰山父者，時漢武帝東巡，見父鋤於道，頭上白光高數尺，呼問之，對曰：有道士教臣作神枕，枕有三十二竅，二十四竅應二十四氣，八竅應八風，臣行之轉少，齒生。","sortOrder":8},
  {"id":"s_work_nvlt_70_9","chapterId":"ch_work_nvlt_70","text":"【賦】後漢張紘朅材枕賦曰：有卓爾之殊朅，超诡異之邈絕，且其材色也，如芸之黃，其為香也，如蘭之芳，其文彩也，如霜地而金茎，紫葉而紅榮，有若蒲陶之蔓延，或如兔絲之煩萦，有若嘉禾之垂穎。又似靈芝之吐英，其似木者，有類桂枝之阑幹，或象灌木之丛生，其似鳥者，若驚鶴之径逝，或類鸿鶤之上征，有若孤雌之無咮，或效鴛鴦之交頸，紛雲興而氣蒸，般星羅而流精，何眾文之冏朗，灼儵爚而發明，曲有所方，事有所成，每則異姿，動各殊名，眾夥［○此有脱文。］不可殫形，製為方枕，四角正端，會緻密固，絕际無間，形妍體法，既麗且閒，高卑得適，辟堅每安，不屑珠碧之飾助，不煩錐鋒之镌鏤，無丹漆之彤朱，罔筦象之佐副，较程形而靈露真，［句有衍文。］眾妙該而悉備，珪璋特達，玙璠富也，美梓逡巡，不敢與併，相思庶幾，晞風於末列，神龍之姿，眾鱗相絕，昔詩人稱角枕之粲，季世加以錦繡之飾，皆比集異物，費日勞力，傷财害民，有損於德，豈如茲朅，既剖既斫，斯須速成，一材而已，莫與混併，纖微無加，而美晔春榮。","sortOrder":9},
  {"id":"s_work_nvlt_70_10","chapterId":"ch_work_nvlt_70","text":"【銘】蔡邕警枕銘曰：應龍蟠蟄，潛德保靈，製器象物，示有其形，哲人降鑒，居安聞傾。","sortOrder":10},
  {"id":"s_work_nvlt_70_11","chapterId":"ch_work_nvlt_70","text":"晉蘇彦楠榴枕銘曰：珍木之奇，文树理鮮，〈木廉〉槾方正，密滑貞堅，朝景西翳，夕舒映天，書倦接引，酣樂流連，繼以高詠，研精上玄，颐神靖魄，須以寧眠，寢貴無想，氣和體平，御心以道，閒邪以誠，色空無著，故能忘情。","sortOrder":11},
  {"id":"s_work_nvlt_70_12","chapterId":"ch_work_nvlt_70","text":"【箴】張紘朅材枕箴曰：彧彧其文，馥馥其芬，出自幽阻，升於氈茵，允朅允麗，惟淑惟珍，安安文枕，貳彼弁冠，冠御於晝，枕式於昏，代作充用，榮己寧身，興寢有節，適性和神。","sortOrder":12},
  {"id":"s_work_nvlt_70_13","chapterId":"ch_work_nvlt_70","text":"【啟】梁元帝謝東宮赉寶枕啟曰：泰山之藥，既使延齡，長生之枕，能令益寿，黃金可化，豈直劉向之書，陽燧含火，方得葛洪之說，况复重安玳瑁，獨勝瑰材，芳松非匹，柟榴未擬。","sortOrder":13},
  {"id":"s_work_nvlt_70_15","chapterId":"ch_work_nvlt_70","text":"《楚辭》曰：翡翠珠被烂齊光。","sortOrder":15},
  {"id":"s_work_nvlt_70_16","chapterId":"ch_work_nvlt_70","text":"《史記》曰：汲黯雲，公孫弘位在三公，俸祿甚厚，為布被，此诈也，上問弘，弘謝曰：有之，夫九卿與臣善者，無過黯，然今日廷詰弘，誠忠，夫以三公為布被，飾诈以釣名，且臣聞管仲相齊，有三歸，侈擬於君，桓公以霸，晏婴相景公，食不重肉，妾不衣絲，齊國亦治，今臣位為御史大夫，而為布被，自九卿下至小吏無差，誠如黯言，且無汲黯忠，陛下安聞此言，天子以為謙讓，愈厚善之。","sortOrder":16},
  {"id":"s_work_nvlt_70_17","chapterId":"ch_work_nvlt_70","text":"《東觀漢記》曰：上嘗召見諸郡計吏，問其風土，及前後守令能否，蜀郡計掾樊顯進曰：漁陽太守張堪，昔在蜀，其仁以惠下，威能讨奸，前公孫述破時，珍寶山積，卷握之物，足富十世，而堪去職之日，乘折轅車，布被囊而已，上聞叹息。","sortOrder":17},
  {"id":"s_work_nvlt_70_18","chapterId":"ch_work_nvlt_70","text":"又曰：王良為大司徒，在位恭俭，妻子不之官舍，布被瓦器，時司徒史鮑恢，以事到東海，過候其家，而良妻布裙曳柴，從田中歸，恢告曰：我司徒吏，故來受書，欲見夫人，妻曰：妾是也，恢乃下拜，叹息而還。","sortOrder":18},
  {"id":"s_work_nvlt_70_19","chapterId":"ch_work_nvlt_70","text":"謝承《後漢書》曰：朱寵為太尉，家貧，臥布被，朝廷賜錦被，不敢當。","sortOrder":19},
  {"id":"s_work_nvlt_70_20","chapterId":"ch_work_nvlt_70","text":"《列女傳》曰：江夏孟宗，少遊學，與同學共處，母為作十二幅被，其鄰婦怪問之。母曰：小兒無異操，懼朋類之不顧，故大其被，以招貧生之臥，庶聞君子之言耳。","sortOrder":20},
  {"id":"s_work_nvlt_70_21","chapterId":"ch_work_nvlt_70","text":"《東觀漢記》曰：祭遵奉公賞賜與士卒，家無私财，身衣布衣，臥布被，夫人裳不加采。","sortOrder":21},
  {"id":"s_work_nvlt_70_22","chapterId":"ch_work_nvlt_70","text":"《郭子》曰：殷浩作楊州，尹［世說新語政事篇，《太平御覽》七百零七尹上有劉字，此脱。］行，日小暮，便命左右取被，仆人問其故，答曰：刺史嚴，不敢夜行。","sortOrder":22},
  {"id":"s_work_nvlt_70_23","chapterId":"ch_work_nvlt_70","text":"【啟】梁劉孝威謝赉錦被啟曰：色艳蒲桃，采逾聯璧，鄂君慚繡，楚侍羞珠。雖复帝賜鶴綾，客赠鴛綺，高懸麗藻，遠謝鮮明，漢老悅其怪文，魏馬驚其香氣。","sortOrder":23},
  {"id":"s_work_nvlt_70_25","chapterId":"ch_work_nvlt_70","text":"《釋名》曰：縟，人所坐亵辱也。","sortOrder":25},
  {"id":"s_work_nvlt_70_26","chapterId":"ch_work_nvlt_70","text":"張璠《漢記》曰：荀爽為三公，食不過一肉，脱粟飯，坐皮縟。","sortOrder":26},
  {"id":"s_work_nvlt_70_27","chapterId":"ch_work_nvlt_70","text":"《魏武帝本紀》曰：上俭率，茵縟取质，無有緣飾。","sortOrder":27},
  {"id":"s_work_nvlt_70_28","chapterId":"ch_work_nvlt_70","text":"《吳志》曰：張昭非魯肅，頗毀訾之，孫權不以介意，賜肅母帷帳氈縟。","sortOrder":28},
  {"id":"s_work_nvlt_70_29","chapterId":"ch_work_nvlt_70","text":"《世說》曰：晉孝武年十三四，時冬天，晝日不著複衣，夜則累茵縟，謝公雲，體宜令有常，陛下晝過冷，夜過熱，恐非攝養之術，帝曰：夜宜靜，謝公出，叹之。","sortOrder":29},
  {"id":"s_work_nvlt_70_30","chapterId":"ch_work_nvlt_70","text":"【啟】梁元帝謝敕賜縟啟曰：昔漢後錫貂，魏君送縟，未有玄兔來王，黃龍作貢，便覺肅蜰非遙，挹娄無遠。","sortOrder":30},
  {"id":"s_work_nvlt_70_31","chapterId":"ch_work_nvlt_70","text":"◇如意","sortOrder":31},
  {"id":"s_work_nvlt_70_32","chapterId":"ch_work_nvlt_70","text":"胡綜《別傳》曰：時有掘地得銅匣，長二尺七寸，开之，得白玉如意，所執處，皆刻螭蝉等形，時人莫知其由，吳大帝以綜多識，乃問之，綜答雲，昔秦始皇東遊，以金陵有王者氣，乃凿諸山岗，處處埋寶物，以當王者之氣，此抑是乎。","sortOrder":32},
  {"id":"s_work_nvlt_70_33","chapterId":"ch_work_nvlt_70","text":"《語林》曰：石崇與王恺爭豪，窮極綺麗，以飾車服，晉武帝恺甥也，每助恺，以珊瑚高二尺許，枝柯扶疏，世間罕比，恺以示崇，崇视訖，以鐵如意击之，應手瓦碎。","sortOrder":33},
  {"id":"s_work_nvlt_70_34","chapterId":"ch_work_nvlt_70","text":"《石崇本事》曰：崇有珊瑚如意，長三尺二寸。","sortOrder":34},
  {"id":"s_work_nvlt_70_35","chapterId":"ch_work_nvlt_70","text":"【啟】梁簡文帝謝敕赉水犀如意啟曰：白玉照采，方斯非貴，珊瑚挺质，匹此未珍，謹仰承威神，陳謝講座，方使歡喜羅漢，懷弃鉢之嗟，王式名儒，析驪駒之辯，熊飾寶刀，子桓恧其大赉，旄牛輕拂，張敞慚其舊儀。","sortOrder":35},
  {"id":"s_work_nvlt_70_36","chapterId":"ch_work_nvlt_70","text":"◇胡床","sortOrder":36},
  {"id":"s_work_nvlt_70_37","chapterId":"ch_work_nvlt_70","text":"《曹瞞傳》曰：操與馬超戰，將過河，前队適渡，超等掩至，操恚，猶坐胡床不起，張郃等見事急，引操入舡，得渡。","sortOrder":37},
  {"id":"s_work_nvlt_70_38","chapterId":"ch_work_nvlt_70","text":"《魏略》曰：裴潛為兖州刺史時，嘗作一胡床，及其去也，留以掛柱。","sortOrder":38},
  {"id":"s_work_nvlt_70_39","chapterId":"ch_work_nvlt_70","text":"《晉中興書》曰：王猛少貧賤，鬻畚為事，常至洛陽货畚，有一人於市貴買其畚，雲家近在此，可隨我去取直，猛隨去，忽至深山中，語猛且住树下，當先通府君，須臾猛進，見一公據胡床，頭鬢悉白，侍從十許人，有一人引猛雲，大司馬公可進，猛因拜老公，公曰：王公何緣拜，即十陪酬畚直，遣人送猛出，既出顧视，乃嵩高山也。","sortOrder":39},
  {"id":"s_work_nvlt_70_40","chapterId":"ch_work_nvlt_70","text":"《郭子》曰：謝萬嘗詣王恬，既至，坐少時，王便入內，謝殊有喜色，謂必厚供，待良久，沐頭散發而出，亦复不坐，乃據胡床，在中庭曬頭，神氣慨然，了無相酬對意。","sortOrder":40},
  {"id":"s_work_nvlt_70_41","chapterId":"ch_work_nvlt_70","text":"《語林》曰：謝镇西著紫羅襦，據胡床，在大市佛圖門樓上彈琵琶，作大道曲。","sortOrder":41},
  {"id":"s_work_nvlt_70_42","chapterId":"ch_work_nvlt_70","text":"《世說》曰：庾大尉在武昌，時秋夜，氣景甚佳，諸佐吏殷浩王胡之之徒，共登城南樓理詠，音調甚遒，俄而庾公率左右步來，諸賢欲起避之，公曰：小住，老子於此處，亦复不淺，因便據胡床，與諸賢士談謔竟坐。","sortOrder":42},
  {"id":"s_work_nvlt_70_43","chapterId":"ch_work_nvlt_70","text":"【詩】梁庾肩吾賦得詠胡床詩曰：傳名乃外域，入用信中京，足欹形已正，文斜體自平，臨堂對遠客，命旅誓初征，何如淄馆下，淹留奉盛明。","sortOrder":43},
  {"id":"s_work_nvlt_70_44","chapterId":"ch_work_nvlt_70","text":"◇火籠","sortOrder":44},
  {"id":"s_work_nvlt_70_45","chapterId":"ch_work_nvlt_70","text":"《東宮舊事》曰：太子納妃，有漆畫手巾薰籠二七，大被薰籠三，衣薰籠三。","sortOrder":45},
  {"id":"s_work_nvlt_70_46","chapterId":"ch_work_nvlt_70","text":"【詩】齊謝朓詠竹火籠詩曰：庭雪亂如花，井冰粲成玉，因炎入貂袖，懷溫奉芳蓐，體密用宜通，文斜性非曲，暫承君王指，請謝陽春旭。","sortOrder":46},
  {"id":"s_work_nvlt_70_47","chapterId":"ch_work_nvlt_70","text":"梁范靜妻沈詠五彩竹火籠詩曰：可怜润霜质，纖剖复毫分，織作回風莒，製為萦綺文，含芳出珠被，耀绿接緗裙，徒嗟今麗飾，豈念昔凌雲。","sortOrder":47},
  {"id":"s_work_nvlt_70_48","chapterId":"ch_work_nvlt_70","text":"【啟】梁簡文帝謝敕赉織竹火籠啟曰：池水始浮，庭雪向飛，慈泽無涯，時錫香被，製此蕑枝，彫斯罕節，文華九折，用美十爐。","sortOrder":48},
  {"id":"s_work_nvlt_70_49","chapterId":"ch_work_nvlt_70","text":"◇香爐","sortOrder":49},
  {"id":"s_work_nvlt_70_50","chapterId":"ch_work_nvlt_70","text":"魏武上雜物疏曰：御物三十种，有純金香爐一枚，下盤自副，貴人公主有純銀香爐四枚，皇太子有純銀香爐四枚，西園貴人銅香爐三十枚。","sortOrder":50},
  {"id":"s_work_nvlt_70_51","chapterId":"ch_work_nvlt_70","text":"《襄陽記》曰：劉季和性愛香，嘗上廁還，過香爐上，主簿張坦曰：人名公作俗人，不虛也，季和曰：荀令君至人家，坐處三日香，為我如何令君，而惡我愛好也，坦曰：古有好婦人，患而捧心嚬眉，見者皆以為好，其鄰丑婦法之，見者走，公便欲使下官遁走耶，季和大笑，以是知坦。","sortOrder":51},
  {"id":"s_work_nvlt_70_52","chapterId":"ch_work_nvlt_70","text":"《東宮舊事》曰：皇太子初拜，有銅博山香爐一枚。","sortOrder":52},
  {"id":"s_work_nvlt_70_53","chapterId":"ch_work_nvlt_70","text":"集異記曰：吳郡吳泰，能筮，會稽盧氏失博山香爐，使泰筮之，泰曰：此物质雖為金，其象實山，有树非林，有孔非泉，阖闾興見發青煙，此香爐也，語其主處，求即得。","sortOrder":53},
  {"id":"s_work_nvlt_70_54","chapterId":"ch_work_nvlt_70","text":"南嶽記曰：衡山之岗有石室，有古人住處，有刀鋸銅銚，及瓦香爐。","sortOrder":54},
  {"id":"s_work_nvlt_70_55","chapterId":"ch_work_nvlt_70","text":"【詩】古詩曰：四坐且莫喧，原聽歌一言，請說銅爐器，崔嵬象南山，上枝似松柏，下根據銅盤，雕文各異類，離娄自相連，誰能為此器，公输與魯班，朱火然其中，青煙颺其間，順風入君懷，四坐莫不歡，香風難久居，空令蕙草殘。","sortOrder":55},
  {"id":"s_work_nvlt_70_56","chapterId":"ch_work_nvlt_70","text":"齊劉繪詠博山香爐詩曰：蔽野千种树，出没萬重山，上鏤秦王子，駕鶴乘紫煙，下刻蟠龍势，矯首半衔莲，傍為伊水麗，芝蓋出巖間，复有漢遊女，拾羽弄餘妍，榮色何雜纟柔，縟繡更相鮮，纴麚或騰倚，林薄香千眠，掩華終不發，含薰未肯然，風生玉階树，露湛曲池莲，寒虫飛夜室，秋雲没晓天。","sortOrder":56},
  {"id":"s_work_nvlt_70_57","chapterId":"ch_work_nvlt_70","text":"【賦】梁昭明太子銅博山香爐賦曰：禀至精之純质，產靈嶽之幽深，經般倕之妙旨，運公输之巧心，有蕙帶而巖隱，亦霓裳而升仙，寫嵩山之巃鹢，象邓林之阡眠，於時青煙司寒，紅光翳景，翠帷已低，蘭膏未屏，炎熒內曜，苾芬外扬，似慶雲之程色，若景星之舒光，信名嘉而用美，永為玩於華堂。","sortOrder":57},
  {"id":"s_work_nvlt_70_58","chapterId":"ch_work_nvlt_70","text":"【銘】漢劉向薰爐銘曰：嘉此正器，嶄巖若山，上貫太華，承以銅盤，中有蘭綺，朱火青煙。","sortOrder":58},
  {"id":"s_work_nvlt_70_59","chapterId":"ch_work_nvlt_70","text":"梁孝元帝香爐銘曰：蘇合氤氲，非煙若雲，時秾更薄，乍聚還分，火微難盡，風長易聞，孰雲道力，慈悲所薰。","sortOrder":59},
  {"id":"s_work_nvlt_70_60","chapterId":"ch_work_nvlt_70","text":"◇步搖","sortOrder":60},
  {"id":"s_work_nvlt_70_61","chapterId":"ch_work_nvlt_70","text":"《釋名》曰：皇後首飾曰副，副，覆也，亦言副貳，兼用眾物成其飾，上有垂珠步搖。","sortOrder":61},
  {"id":"s_work_nvlt_70_62","chapterId":"ch_work_nvlt_70","text":"《東觀漢記》曰：邓太後賜馬貴人步搖一具。","sortOrder":62},
  {"id":"s_work_nvlt_70_63","chapterId":"ch_work_nvlt_70","text":"《續漢書》曰：太後入廟，為花勝，上為鳳，以翡翠為毛羽，步搖以黃金為山題，貫白珠，桂枝相糾。","sortOrder":63},
  {"id":"s_work_nvlt_70_64","chapterId":"ch_work_nvlt_70","text":"【詩】梁范靖妻沈詠步搖花詩曰：珠華萦翡翠，寶葉間金琼，剪荷不似製，為花如自生，低枝拂繡領，微步動瑤琼。","sortOrder":64},
  {"id":"s_work_nvlt_70_66","chapterId":"ch_work_nvlt_70","text":"《釋名》曰：叉，枝也，因形名之也。","sortOrder":66},
  {"id":"s_work_nvlt_70_67","chapterId":"ch_work_nvlt_70","text":"《續漢書》曰：貴人助蠶，戴玳瑁釵。","sortOrder":67},
  {"id":"s_work_nvlt_70_68","chapterId":"ch_work_nvlt_70","text":"《華陽國志》曰：涪陵山有大龟，其甲可卜，其緣可作釵，世號靈釵。","sortOrder":68},
  {"id":"s_work_nvlt_70_69","chapterId":"ch_work_nvlt_70","text":"【詩】梁湯僧濟泄井得金釵詩曰：昔日倡家女，摘花露井邊，摘花還自比，插映還自怜，窥窥終不罢，笑笑自成妍，寶釵於此落，從來非一年，翠羽成泥去，金色尚如鮮，此人今何在，此物今空傳。","sortOrder":69},
  {"id":"s_work_nvlt_70_70","chapterId":"ch_work_nvlt_70","text":"【賦】晉夏侯湛雀釵賦曰：覽嘉藝之機巧，持精思於雀釵，收泉珍於八極，納朅異以表奇，布太陽而擬法，妙团团而應規，於是妍姿英妙之徒，相與競嬖飛寵，［句有衍文。］併脩敕，理桂襟，整服飾，黛玄眉之琰琰，收紅顏而發色，流眄閒步，輕袂翼翼，恃炫艳以相邈，常逍遙而侍侧，昔先王與道立教，崇冲讓以致賢，不留志於華好。","sortOrder":70},
  {"id":"s_work_nvlt_70_71","chapterId":"ch_work_nvlt_70","text":"【銘】後漢崔瑗三子釵銘曰：元正上日，百福孔靈，鬢發如雲，乃象眾星，三珠璜釵，攝媛贊靈。","sortOrder":71},
  {"id":"s_work_nvlt_70_72","chapterId":"ch_work_nvlt_70","text":"【啟】梁元帝謝東宮赉花釵啟曰：苣亂九衢，花含四照，田文之珥，慚於寶葉，王粲之詠，恧此乘莲，九宮之璫，豈直黃香之賦，三珠之釵，敢高崔瑗之說，况以麗玉澄暉，遠過玳瑁之飾，精金曜首，高踐翡翠之名。","sortOrder":72},
  {"id":"s_work_nvlt_70_73","chapterId":"ch_work_nvlt_70","text":"◇梳枇","sortOrder":73},
  {"id":"s_work_nvlt_70_74","chapterId":"ch_work_nvlt_70","text":"《說文》曰：櫛，梳枇總名也。","sortOrder":74},
  {"id":"s_work_nvlt_70_75","chapterId":"ch_work_nvlt_70","text":"《釋名》曰：梳言其齒疏也，枇言其相比也。","sortOrder":75},
  {"id":"s_work_nvlt_70_76","chapterId":"ch_work_nvlt_70","text":"《禮記》曰：男女不同巾櫛。","sortOrder":76},
  {"id":"s_work_nvlt_70_77","chapterId":"ch_work_nvlt_70","text":"《左傳》曰：晉太子為质於秦，將逃歸，謂嬴氏曰：與子歸乎，對曰：子晉太子而辱於秦，子之欲歸，不亦宜乎，寡君使婢子侍執巾櫛，以固子也，從子而歸，弃君之命，不敢從，亦不敢言。","sortOrder":77},
  {"id":"s_work_nvlt_70_78","chapterId":"ch_work_nvlt_70","text":"十洲記［《初學記》五，《太平御覽》五十一作盛弘之荆州記。］曰：臨海［按晉書地理志興安縣屬臨贺郡，海當作贺。］興安縣東界，去郡八十里，縣邊有平石，其上有石櫛，俗雲越王渡溪，墮櫛於此。","sortOrder":78},
  {"id":"s_work_nvlt_70_79","chapterId":"ch_work_nvlt_70","text":"《續漢書》曰：李文德素善延篤，謂公卿曰：延篤有王佐之才，欲令引進之，篤聞，為書止文德曰：吾常昧爽櫛梳，坐於客堂，朝則誦虞夏之書，歷公旦之典禮，覽仲尼春秋，當時之時，不知天之為蓋，地之為舆，慎勿迷其本，弃其生也。","sortOrder":79},
  {"id":"s_work_nvlt_70_80","chapterId":"ch_work_nvlt_70","text":"《新序》曰：楚莊王罢朝而晏，樊姬問其故，莊王曰：今旦與賢相語，不知日晏也，樊姬曰：賢相為誰，王曰：虞丘子，樊姬掩口而笑，王問其故，曰：妾得執巾櫛以侍王，非不欲专寵擅愛也，以為傷王之義，故進與妾同位者數人矣，今虞丘子未聞進一人，未知其賢。","sortOrder":80},
  {"id":"s_work_nvlt_70_81","chapterId":"ch_work_nvlt_70","text":"【賦】晉傅鹹櫛賦曰：我嘉茲櫛，惡亂好理，一發不順，實以為恥，雖日用而匪懈，不告勞而自已，苟以理而委任，期竭力而没齒。","sortOrder":81},
  {"id":"s_work_nvlt_70_83","chapterId":"ch_work_nvlt_70","text":"《史記》曰：秦围邯鄲，趙使平原君求救於楚，與門下二十人偕，得十九人，餘無可取者，毛遂自進於平原君，君曰：夫賢士之處世也，譬若錐之處囊，其末立見，今先生處勝門下，三年於此矣，左右未有所稱，遂曰：臣乃今日請處囊中耳，使遂早得處囊中，乃穎脱而出，非特其末見而已也。","sortOrder":83},
  {"id":"s_work_nvlt_70_84","chapterId":"ch_work_nvlt_70","text":"《漢書》曰：陆贾使尉他，留飲數月，他曰：越中無足與語，至生來，令我日聞所不聞，賜贾囊中裝，直千金。","sortOrder":84},
  {"id":"s_work_nvlt_70_85","chapterId":"ch_work_nvlt_70","text":"【詩】後漢趙一客秦詩曰：文籍徒滿腹，不如一囊錢。","sortOrder":85},
  {"id":"s_work_nvlt_70_86","chapterId":"ch_work_nvlt_70","text":"魏繁钦定情詩曰：何以致區區，目中双明珠，何以致叩叩，香囊系肘後。","sortOrder":86},
  {"id":"s_work_nvlt_70_87","chapterId":"ch_work_nvlt_70","text":"【賦】梁簡文帝眼明囊賦序曰：俗之婦人，八月旦，多以錦翠珠寶為眼明囊，因競凌晨取露以拭目，聊為此賦，爾乃裁茲金鏤，製此妖飾，緝濯錦之龍光，剪輕羁之蝉翼，雜花勝而成疏，依步搖而相通，明金亂雜，細寶交陳，義同厭勝，欣此節新，擬椒花於歲首，學夭桃於暮春。","sortOrder":87},
  {"id":"s_work_nvlt_70_89","chapterId":"ch_work_nvlt_70","text":"《莊子》曰：至人之用心也若鏡，不將不迎，應而不藏，故勝物而無傷。","sortOrder":89},
  {"id":"s_work_nvlt_70_90","chapterId":"ch_work_nvlt_70","text":"《韓子》曰：古之人，目短於自見，故以鏡觀面，智短於自知，故以道正己，鏡無見疵之罪，道無明過之惡，目失鏡，無以正鬢眉，身失道，無以知迷惑。","sortOrder":90},
  {"id":"s_work_nvlt_70_91","chapterId":"ch_work_nvlt_70","text":"《戰國策》曰：邹忌身體逸麗，朝服衣冠，謂其妻曰：我孰與城北徐公美，妻曰：君美甚。又問妾及客，皆曰：徐公不如，明日徐公來，忌窥鏡自视，知不如徐公遠矣，忌入朝見王曰：臣美不如徐公，臣妻妾客皆雲臣勝，妻私臣，妾畏臣，客求臣也，今齊方千里，百二十城，宮婦莫不私王，朝臣莫不畏王，四境莫不求王，由此觀之，親蔽甚矣，王乃令群臣進諫，諸侯皆朝齊。","sortOrder":91},
  {"id":"s_work_nvlt_70_92","chapterId":"ch_work_nvlt_70","text":"《列女傳》曰：梁寡高行者，榮於色，敏於行，梁王聞而聘之，乃援鏡割鼻，梁王高其行，號曰梁高行。","sortOrder":92},
  {"id":"s_work_nvlt_70_93","chapterId":"ch_work_nvlt_70","text":"蜀王本紀曰：武都丈夫化為女，顏色美好，蓋山精也，蜀王娶以為夫人，無幾物故，蜀王於武都簷土，於成都葬之，蓋地三畝，號曰武簷，以石作鏡一枚，表其墓。","sortOrder":93},
  {"id":"s_work_nvlt_70_94","chapterId":"ch_work_nvlt_70","text":"海內玉品子［《太平御覽》七百十七作海內士品。］曰：徐孺子常事江夏黃公，公卒，孺子往會葬，無資自以致，赍摩鏡具自隨，每所在，賃摩鏡取資，然後得前，既至，祭畢而退。","sortOrder":94},
  {"id":"s_work_nvlt_70_95","chapterId":"ch_work_nvlt_70","text":"《抱朴子》曰：或問知將來吉凶為有道乎，答曰：用明鏡九寸自照，有所思存，七日則見神仙，知千里外事也，明鏡或用一，或用二，謂之四規鏡。","sortOrder":95},
  {"id":"s_work_nvlt_70_96","chapterId":"ch_work_nvlt_70","text":"《符子》曰：心善知人者，看如明鏡，鏡以耀明，故鑒人也。","sortOrder":96},
  {"id":"s_work_nvlt_70_97","chapterId":"ch_work_nvlt_70","text":"潯陽記曰：石鏡在山東，有一团石懸崖，明净照人。","sortOrder":97},
  {"id":"s_work_nvlt_70_98","chapterId":"ch_work_nvlt_70","text":"《異苑》曰：山雞愛其毛羽，映水則舞，魏武時，南方獻之，公子蒼舒，令以大鏡其前，雞鑒形而舞，不知止，遂乏死。","sortOrder":98},
  {"id":"s_work_nvlt_70_99","chapterId":"ch_work_nvlt_70","text":"【詩】梁簡文帝詠鏡詩曰：□銖恒在侧，誰言覽鏡稀，如冰不見水，似扇長含暉，全开玳瑁匣，併卷織成衣，脱入相如手，疑言趙璧歸。","sortOrder":99},
  {"id":"s_work_nvlt_70_100","chapterId":"ch_work_nvlt_70","text":"周庾信詠鏡詩曰：玉匣聊开鏡，輕灰暫拭尘，光如一片水，影照兩邊人，月生無有桂，花开不逐春，试掛淮南竹，堪能見四鄰。","sortOrder":100},
  {"id":"s_work_nvlt_70_101","chapterId":"ch_work_nvlt_70","text":"梁高爽詠鏡詩曰：初上鳳皇墀，此鏡照蛾眉，言照長相守，不照長相思，虛心會不采，貞明空自欺，無言此故物，更复對新期，梁何遜詠鏡詩曰：珠帘旦初卷，停機晨未織，玉匣开覽形，寶台臨净飾，對影獨含笑，看光時轉侧，聊為出茧眉，试染夭桃色，羽釵如可間，金钿畏相逼，荡子行未歸，啼妆坐相憶。","sortOrder":101},
  {"id":"s_work_nvlt_70_102","chapterId":"ch_work_nvlt_70","text":"梁朱超道詠鏡詩曰：折花須自插，不用暫臨池，當猶可怜面，偏與鏡相宜，安釵钏獨响，刷鬢袖俱移，唯餘心里恨，影中恒不知，梁王孝禮詠鏡詩曰：可怜不自識，終須因鏡中，分眉一等翠，對面兩邊紅，轉身先見動，含笑逆相同，猶嫌鏡里促，看人未好通。","sortOrder":102},
  {"id":"s_work_nvlt_70_103","chapterId":"ch_work_nvlt_70","text":"【賦】梁劉缓鏡賦曰：夜筹已竭，晓鍾將絕，窗外明來，帷前影滅，階邊就水，盤中先映，訝宿妆之猶調，笑殘黃之不正，欲开奁而更飾，乃當窗而取鏡，世間好鏡自無多，唯聞一个比姮娥，曾經玉女照，屢被仙人磨，光明粉可怜，論時不假著，法用自應須，夏天金薄漠，秋日寶茱萸，銀纏辟鬼咒，翠厄護身符，空處宜應插，非是畏釵梳。","sortOrder":103},
  {"id":"s_work_nvlt_70_104","chapterId":"ch_work_nvlt_70","text":"周庾信鏡賦曰：天河漸没，日輪將起，燕噪吳王，乌驚御史，玉花簟上，金莲帳里，始摺屏風，新开戶扇，朝光晃眼，早風吹面，臨桁下而牵衫，就箱邊而著钏，宿鬟尚卷，殘妆已薄，無复唇珠，才餘眉萼，靨上星稀，黃中月落，鏡台銀帶，本出魏宮，能橫却月，巧掛回風，龍垂匣外，鳳倚花中，鏡乃照胆照心，難逢難值，鏤五色之盤龍，刻千年之古字，山雞看而獨舞，海鳥見而孤鳴，臨水則池中月出，照日則壁上菱生，暫設妆奁，還抽鏡屉，競學生情，爭怜今世，鬢齊故略。眉平猶剃，飛花摶子，次第須安，朱开錦蹹，黛黈油檀，脂和甲煎，泽渍香蘭，量髻鬢之長短，度安花之相去，懸媚子於搔頭，拭釵梁於粉絮，梳頭新罢照著衣，還從妆處取將歸，暫看絃系，懸知缬缦，衫正身長，裙斜假襻，真成个鏡特相宜，不能片時藏匣里，暫出園中也自隨。","sortOrder":104},
  {"id":"s_work_nvlt_70_105","chapterId":"ch_work_nvlt_70","text":"晉傅鹹鏡賦曰：清邈明水，景若朝陽，不將不迎，應物無方，不有心於妍丑，而眾形其必詳，猗猗淑媛，峨峨後妃，眷春榮之零華，懼玉顏之有衰，盼清陽以自鏡，競崇姱以相辉。","sortOrder":105},
  {"id":"s_work_nvlt_70_106","chapterId":"ch_work_nvlt_70","text":"【銘】梁簡文帝鏡銘曰：金精石英，冰辉沼清，高堂懸影，仁寿摛聲，雲开月見，水净珠明。","sortOrder":106},
  {"id":"s_work_nvlt_70_107","chapterId":"ch_work_nvlt_70","text":"江總方鏡銘曰：此鏡以照著衣，鏡背圖刻八卦二十八宿，仁寿殿前，無以加斯彫麗也，玄枵命巧，仲呂呈祥，金镌石漢，銅鑄丹陽，价珍負局，影麗高堂，圖星擬蓋，寫卦隨方，明齊水止，照與天長，增辉兔苑，永侍龍光。","sortOrder":107},
  {"id":"s_work_nvlt_70_108","chapterId":"ch_work_nvlt_70","text":"漢李尤鏡銘曰：鑄銅為鑒，整飾容顏，修爾法服，正爾衣冠。","sortOrder":108},
  {"id":"s_work_nvlt_70_110","chapterId":"ch_work_nvlt_70","text":"《漢書》曰：景帝時，王生嘗召居庭中，公卿盡會，張釋之為廷尉，王生顧曰：吾襪解，為我結襪，釋之跪而結之，既已，人或讓之，王生獨奈何庭辱張廷尉如此，王生曰：吾老且賤，自度終無益於張廷尉，廷尉方天下名臣，吾故使跪結襪，欲以重之，諸公聞之，賢王生而重釋之。","sortOrder":110},
  {"id":"s_work_nvlt_70_111","chapterId":"ch_work_nvlt_70","text":"《東觀漢記》曰：和帝召諸儒，侍中贾逵尚書令黃香等，相難數事，罢朝，特賜履襪。","sortOrder":111},
  {"id":"s_work_nvlt_70_112","chapterId":"ch_work_nvlt_70","text":"《會稽典錄》曰：贺劭為人美容止，瞻视動靜有常，與人交，久益敬之，至在官府，左右莫見其洗沐，坐嘗著襪，希見其足。","sortOrder":112},
  {"id":"s_work_nvlt_70_113","chapterId":"ch_work_nvlt_70","text":"【銘】後漢崔骃襪銘曰：機衡建子，萬物含滋，黃鍾育化，以養元基，長履景福，至於亿年，皇靈既祐，祉祿來臻，本枝百世，子子孫孫。","sortOrder":113},
  {"id":"s_work_nvlt_70_114","chapterId":"ch_work_nvlt_70","text":"【頌】魏曹植冬至獻襪頌曰：玉趾既御，履和蹈貞，行與祿邁，動以福併，南闚北戶，西巡王城，翱翔萬域，聖體浮輕。","sortOrder":114},
  {"id":"s_work_nvlt_70_115","chapterId":"ch_work_nvlt_70","text":"《藝文類聚》　唐·欧陽詢","sortOrder":115},
  {"id":"s_work_nvlt_71_1","chapterId":"ch_work_nvlt_71","text":"卷七十一舟車部","sortOrder":1},
  {"id":"s_work_nvlt_71_2","chapterId":"ch_work_nvlt_71","text":"○舟車","sortOrder":2},
  {"id":"s_work_nvlt_71_4","chapterId":"ch_work_nvlt_71","text":"《易》曰：刳木為舟，剡木為楫，舟楫之利，以濟不通。","sortOrder":4},
  {"id":"s_work_nvlt_71_5","chapterId":"ch_work_nvlt_71","text":"《世本》曰：共鼓货狄作舟，［共鼓货狄，黃帝二臣。］","sortOrder":5},
  {"id":"s_work_nvlt_71_6","chapterId":"ch_work_nvlt_71","text":"《爾雅》曰：舫，舟也，天子造舟，諸侯維舟，大夫方舟，士特舟，庶人乘柎，［造，比舡為桥也，維，連四舡也，方，併兩舡也，特，单舡也，柎，編木以為渡也。］","sortOrder":6},
  {"id":"s_work_nvlt_71_7","chapterId":"ch_work_nvlt_71","text":"韻集曰：鹢首，天子舡也，舡，船也，艘，海大舡也。","sortOrder":7},
  {"id":"s_work_nvlt_71_8","chapterId":"ch_work_nvlt_71","text":"《山海經》曰：番禺始為舟。","sortOrder":8},
  {"id":"s_work_nvlt_71_9","chapterId":"ch_work_nvlt_71","text":"又曰：有大人之國，坐而削舟。","sortOrder":9},
  {"id":"s_work_nvlt_71_10","chapterId":"ch_work_nvlt_71","text":"《墨子》曰：弃作舟。","sortOrder":10},
  {"id":"s_work_nvlt_71_11","chapterId":"ch_work_nvlt_71","text":"《廣雅》曰：艦，大舡也，舫，艕舡也，蒙冲艑〈舟句〉〈舟庶〉舸舼艇艋，舟也。","sortOrder":11},
  {"id":"s_work_nvlt_71_12","chapterId":"ch_work_nvlt_71","text":"《釋名》曰：船，循也，循水而行也。","sortOrder":12},
  {"id":"s_work_nvlt_71_13","chapterId":"ch_work_nvlt_71","text":"又曰：舟言周也，船上屋曰庐，象舍也，其上重室曰飛庐，在上故曰飛也。又在其上曰翟室，於中候望，若鳥雀人［《太平御覽》七百六十八作之。］驚视也。","sortOrder":13},
  {"id":"s_work_nvlt_71_14","chapterId":"ch_work_nvlt_71","text":"又曰：船三百斛曰刀，刀，貂也，短也，江南所為名，短而廣安，不傾危也，二百斛已下曰艇，其形径艇，一人二人所乘行也。","sortOrder":14},
  {"id":"s_work_nvlt_71_15","chapterId":"ch_work_nvlt_71","text":"又曰：外狹而長曰艨冲，以突敵曰船，自關而東，或謂之舟，方舟或謂之航，南楚江湘，凡船大者謂之舸，小舸謂之艖。","sortOrder":15},
  {"id":"s_work_nvlt_71_16","chapterId":"ch_work_nvlt_71","text":"《說文》曰：舫，併船也。","sortOrder":16},
  {"id":"s_work_nvlt_71_17","chapterId":"ch_work_nvlt_71","text":"《毛詩》曰：柏舟，共薑自誓也，衛世子共伯早死，其妻守義，父母欲奪而嫁之，誓而弗許，故作是詩以絕之也，汎彼柏舟，在彼中河。","sortOrder":17},
  {"id":"s_work_nvlt_71_18","chapterId":"ch_work_nvlt_71","text":"又曰：二子乘舟，思伋寿也，衛宣公之二子，爭相為死，國人傷而思之，而作是詩也，二子乘舟，汎汎其景，原言思子，中心養養。","sortOrder":18},
  {"id":"s_work_nvlt_71_19","chapterId":"ch_work_nvlt_71","text":"又曰：汎汎楊舟，載沉載浮，既見君子，我心則休。","sortOrder":19},
  {"id":"s_work_nvlt_71_20","chapterId":"ch_work_nvlt_71","text":"又曰：誰謂河廣，曾不容刀。","sortOrder":20},
  {"id":"s_work_nvlt_71_21","chapterId":"ch_work_nvlt_71","text":"《左傳》曰：秦伯伐晉，濟河焚舟，取王官及郊，晉人不出，遂自茅津濟，封殽尸而還。","sortOrder":21},
  {"id":"s_work_nvlt_71_22","chapterId":"ch_work_nvlt_71","text":"又曰：先軫朝問秦囚，公曰：夫人請之，吾舍之矣，先軫怒曰：武夫力而拘諸原，婦人暫而免諸國，隳軍實而長寇讎，亡無日矣，不顧而唾，公使陽處父追之，及諸河，則在舟中矣。","sortOrder":22},
  {"id":"s_work_nvlt_71_23","chapterId":"ch_work_nvlt_71","text":"又曰：齊侯與蔡姬，乘舟於囿，荡公，公懼变色，禁之不可，公怒歸之，未之絕也，蔡人嫁之，齊侯以諸侯之師侵蔡，蔡潰。","sortOrder":23},
  {"id":"s_work_nvlt_71_24","chapterId":"ch_work_nvlt_71","text":"又曰：吳伐楚，陽丐為令尹，卜戰不吉，司馬子魚曰：我得上流，何故不吉。楚故司馬令龟，我請改卜，令曰：鲂也以其屬死之，楚師繼之，尚大克之，吉，戰於長岸，子魚先，楚師繼之，大败吳，獲其乘舟餘皇。","sortOrder":24},
  {"id":"s_work_nvlt_71_25","chapterId":"ch_work_nvlt_71","text":"又曰：冬，晉荐飢，使乞籴於秦，秦输粟於晉，自雍及絳相繼，命之曰汎舟之役。","sortOrder":25},
  {"id":"s_work_nvlt_71_26","chapterId":"ch_work_nvlt_71","text":"又曰：晉楚將戰，趙婴齊使其徒，先具舟於河，故败而先濟也。","sortOrder":26},
  {"id":"s_work_nvlt_71_27","chapterId":"ch_work_nvlt_71","text":"太公《六韜》曰：殷君喜為酒池，回船牛飲者三千人。","sortOrder":27},
  {"id":"s_work_nvlt_71_28","chapterId":"ch_work_nvlt_71","text":"又曰：武王伐殷，先出於河，呂尚為後將，以四十七艘船濟於河。","sortOrder":28},
  {"id":"s_work_nvlt_71_29","chapterId":"ch_work_nvlt_71","text":"《周書》曰：周成王時，於越獻舟。","sortOrder":29},
  {"id":"s_work_nvlt_71_30","chapterId":"ch_work_nvlt_71","text":"文字曰：舟浮江海，不為莫乘而沉，君子行道，不為莫知而止。","sortOrder":30},
  {"id":"s_work_nvlt_71_31","chapterId":"ch_work_nvlt_71","text":"《邓析書》曰：同舟涉海，中流遇風，救患若一，所忧同也。","sortOrder":31},
  {"id":"s_work_nvlt_71_32","chapterId":"ch_work_nvlt_71","text":"《家語》曰：舟非水不行，水入則舟没，君非民不治，民犯上則君危，［事具人部鑒戒篇。］","sortOrder":32},
  {"id":"s_work_nvlt_71_33","chapterId":"ch_work_nvlt_71","text":"《莊子》曰：藏舟於壑，藏山於泽，謂之固矣，然則夜半有力者負之而走，昧者不知也。","sortOrder":33},
  {"id":"s_work_nvlt_71_34","chapterId":"ch_work_nvlt_71","text":"又曰：水之積也不厚，則負其大舟也無力，覆杯水於坳堂之上，則芥為之舟，置杯焉則膠，水淺而舟大也。","sortOrder":34},
  {"id":"s_work_nvlt_71_35","chapterId":"ch_work_nvlt_71","text":"《楚辭》曰：美要妙兮宜脩，沛吾乘兮桂舟。","sortOrder":35},
  {"id":"s_work_nvlt_71_36","chapterId":"ch_work_nvlt_71","text":"又曰：桂棹兮蘭枻，斫冰兮積雪。","sortOrder":36},
  {"id":"s_work_nvlt_71_37","chapterId":"ch_work_nvlt_71","text":"《呂氏春秋》曰：荆有次非者，得寶劍，涉江至中流，有兩蛟夹繞其船，次非拔劍赴江，刺蛟殺之，舟中之人皆活，荆王聞之，仕以執圭，［事具軍器部劍篇。］","sortOrder":37},
  {"id":"s_work_nvlt_71_38","chapterId":"ch_work_nvlt_71","text":"又曰：伍員如吳，過於荆，至江上，欲涉，見一丈人刺小船，方將漁，從而請焉，丈人渡之。","sortOrder":38},
  {"id":"s_work_nvlt_71_39","chapterId":"ch_work_nvlt_71","text":"《淮南子》曰：乌號之弓，谿子之弩，不能無絃而射，越舲蜀艇，不能無水而浮。","sortOrder":39},
  {"id":"s_work_nvlt_71_40","chapterId":"ch_work_nvlt_71","text":"又曰：湯武聖主也，而不能與越人乘舲舟而浮於江湖。","sortOrder":40},
  {"id":"s_work_nvlt_71_41","chapterId":"ch_work_nvlt_71","text":"又曰：楚人有乘船而遇大風者，波至而恐，自投於水，非不貪生而畏死也，惑於死而反忘生也。","sortOrder":41},
  {"id":"s_work_nvlt_71_42","chapterId":"ch_work_nvlt_71","text":"又曰：龍舟鹢首，浮吹以虞，此遊於水也。","sortOrder":42},
  {"id":"s_work_nvlt_71_43","chapterId":"ch_work_nvlt_71","text":"又曰：公孫龍在趙時，謂弟子曰：人而無能者，龍弗能與遊，有客衣褐帶素而見曰：臣能呼，公孫龍顧謂弟子曰：門下故有能呼者，對曰：無，公孫龍曰：與之弟子之籍，後數日，往說燕王，至於河上，而航在水汜，使善呼者呼之而航來。","sortOrder":43},
  {"id":"s_work_nvlt_71_44","chapterId":"ch_work_nvlt_71","text":"《說苑》曰：襄城君始封之日，衣翠衣，帶玉劍，履縞舄，立乎流水之上，大夫莊辛過而說之曰：原把君之手，其可乎，襄城作色不言，莊辛遷延稱曰：君獨不聞鄂君之遇越人乎，鄂君方汎舟於新波之上，乘青翰之舟，張翠羽之蓋，會鼓鍾之音，越人擁楫而歌曰：今夕何夕兮，褰州水流，今日何日，得與王子同舟，山有木兮木有枝，心悅君兮君不知，於是鄂君揄袂而擁之，舉繡被而覆之，襄城乃奉手進之。","sortOrder":44},
  {"id":"s_work_nvlt_71_45","chapterId":"ch_work_nvlt_71","text":"《列女傳》曰：趙簡子南击荆，至河津，津吏醉臥，不能渡，簡子怒，將殺之，津吏之女，乃持楫而前走曰：妾父聞君王將渡，恐風波之起，水神動駭，故祷祀九江三淮之神，不勝杯杓餘瀝，醉於此，君命誅之，原以微軀易父之死，簡子將渡，用楫少一人，操楫曰：妾居河濟之間，習舟楫之事，原備員持楫，簡子遂與操度，中流奏河激之歌，簡子乃聘為夫人，［事具水部津篇。］","sortOrder":45},
  {"id":"s_work_nvlt_71_46","chapterId":"ch_work_nvlt_71","text":"郭林宗別傳曰：林宗遊洛陽，始見河南尹李膺，膺大奇之，遂相友善，於是名震京師，後歸乡曲，衣冠諸儒，送至河上，車數千兩，林宗唯與李膺同舟而濟。眾賓望之，以為神仙焉。","sortOrder":46},
  {"id":"s_work_nvlt_71_47","chapterId":"ch_work_nvlt_71","text":"枹朴子曰：琼艘瑤楫，無涉川之用，金弧玉絃，無激矢之能，是以介絜而無政事者，非拨亂之器，儒雅而乏治略者，非翼亮之士。","sortOrder":47},
  {"id":"s_work_nvlt_71_48","chapterId":"ch_work_nvlt_71","text":"又曰：欲以弊藥必規升騰者，何異策蹇驢而欲尋追風，棹藍舟而欲濟大川。","sortOrder":48},
  {"id":"s_work_nvlt_71_49","chapterId":"ch_work_nvlt_71","text":"《韓子》曰：千鈞得舡則浮，锱銖失舡則沉，非千鈞輕而锱銖重也，有势之與無势也。","sortOrder":49},
  {"id":"s_work_nvlt_71_50","chapterId":"ch_work_nvlt_71","text":"《孫卿子》曰：君者舟也，庶人者水也，水則載舟，水則覆舟。","sortOrder":50},
  {"id":"s_work_nvlt_71_51","chapterId":"ch_work_nvlt_71","text":"冲波傳曰：孔子使子貢，久而不來，孔子謂弟子占之，遇鼎，皆言無足不來，顏回掩口而笑，子曰：回也哂，謂賜來也，曰：無足者，乘舟而來至矣，清旦朝，子貢朝至，验如顏回之言。","sortOrder":51},
  {"id":"s_work_nvlt_71_52","chapterId":"ch_work_nvlt_71","text":"《漢書》曰：薛廣德為御史大夫，秋，上祭宗廟，出東便門，欲御樓船，廣德當乘舆車，免冠頓首諫，宜從桥，詔曰：大夫冠，廣德曰：陛下不聽臣，臣自刎，以血污車輪，上不悅，先驅光祿大夫張猛進曰：臣聞主聖臣直，乘船危，就桥安，聖主不乘危，御史大夫言可聽，上曰：晓人不當如是耶，乃從桥。","sortOrder":52},
  {"id":"s_work_nvlt_71_53","chapterId":"ch_work_nvlt_71","text":"《物理論》曰：夫工匠經涉河海，為〈舟向〉［按集韻，當作〈舟句〉。］〈舟鹿〉以浮大川，皆成乎巧手，出乎聖意。","sortOrder":53},
  {"id":"s_work_nvlt_71_54","chapterId":"ch_work_nvlt_71","text":"楊子《法言》曰：舍舟航而濟乎渎者，末矣，舍五經而濟乎道者，末矣，乘國者其如乘航乎，航安則民斯安矣。","sortOrder":54},
  {"id":"s_work_nvlt_71_55","chapterId":"ch_work_nvlt_71","text":"《東觀漢記》曰：第五倫為會稽守，為事徵，百姓攀轅扣馬呼曰：舍我何之，第五倫密委去，百姓聞之，乘船追之，交错水中，其得民心如此。","sortOrder":55},
  {"id":"s_work_nvlt_71_56","chapterId":"ch_work_nvlt_71","text":"張璠《漢記》曰：梁冀第池中舡，無故自覆，問掾朱穆，曰：舟所以濟渡萬物，不施遊戲也，而今覆者，天戒將軍當濟渡萬民，不可長念樂遊而已。","sortOrder":56},
  {"id":"s_work_nvlt_71_57","chapterId":"ch_work_nvlt_71","text":"《華陽國志》曰：初楚頃襄王時，遣將莊蹻，從沅水伐夜郎，將軍至且蘭，椓船於岸而步戰，既滅夜郎，因留王滇池，以且蘭有椓船牂牁處，乃改其名為牂牁。牂牁地多雨潦，俗好巫鬼禁忌。","sortOrder":57},
  {"id":"s_work_nvlt_71_58","chapterId":"ch_work_nvlt_71","text":"《魏志》曰：邓哀王冲，字仓舒，少聰察歧嶷，生五六歲，智意所及，有若成人，孫權曾致象，太祖欲知其斤重，訪之群下，鹹莫能出其理，冲曰：置象大船之上，而刻其所至，稱物以載之，則立可知矣，太祖大悅，即施行。","sortOrder":58},
  {"id":"s_work_nvlt_71_59","chapterId":"ch_work_nvlt_71","text":"《吳書》曰：陆遜破曹休，當還西陵，公卿併會，為遜祖道，上賜遜御船一舫，繒采舟梁。","sortOrder":59},
  {"id":"s_work_nvlt_71_60","chapterId":"ch_work_nvlt_71","text":"王隱《晉書》曰：顧榮徵侍中，見王路塞絕，便乘舡而還，過下邳，遂解舫為单舸，一日一夜，行五六百里，遂得免。","sortOrder":60},
  {"id":"s_work_nvlt_71_61","chapterId":"ch_work_nvlt_71","text":"《吳志》曰：周瑜逆曹公，部將黃蓋，取蒙冲斗艦十艘，實以薪草，膏灌其中，裹以帷幕，上建牙旗，同時發火，時風猛火盛，延燒岸上營，曹公軍退败。","sortOrder":61},
  {"id":"s_work_nvlt_71_62","chapterId":"ch_work_nvlt_71","text":"又曰：呂蒙袭關羽，至尋陽，盡伏精兵於構慁中，使舡中搖橹作商贾服，晝夜兼行，故羽不聞知，遂到南郡。","sortOrder":62},
  {"id":"s_work_nvlt_71_63","chapterId":"ch_work_nvlt_71","text":"又曰：董袭讨黃祖，祖橫兩蒙冲，夹守沔口，以栟榈大绁，系石為矴，袭與陵統，俱為前部，各將敢死百人，人被兩鎧，乘大舸，突入蒙冲里，身以刀斷兩绁，蒙冲乃橫流，大兵遂進。","sortOrder":63},
  {"id":"s_work_nvlt_71_64","chapterId":"ch_work_nvlt_71","text":"又曰：將軍贺齊，性奢，所乘船，雕刻丹鏤，青蓋絳襜，蒙冲斗艦之屬，望之若山。","sortOrder":64},
  {"id":"s_work_nvlt_71_65","chapterId":"ch_work_nvlt_71","text":"又曰：甘寧厨下兒有過，走投呂蒙，蒙出還寧，寧許蒙不殺，還舡，縛置桑树，自射殺之，敕舡人更增舸纜，解衣臥舡中，蒙怒，欲攻寧，蒙母諫乃止。","sortOrder":65},
  {"id":"s_work_nvlt_71_66","chapterId":"ch_work_nvlt_71","text":"晉宮閣記曰：池中有紫宮舟升進舟曜陽舟飛龍舟射獵舟，靈芝池有鳴鶴舟指南舟，合利池有雲母舟無極舟，都亭池有常安舟。","sortOrder":66},
  {"id":"s_work_nvlt_71_67","chapterId":"ch_work_nvlt_71","text":"杜蘭香別傳曰：香降張硕，硕既成婚，香便去，絕不來，年餘，硕船行，忽見香乘車於山际，硕不勝驚喜，遙往造香，見香悲喜，香亦有悅色，言語頃時，硕欲登其車，其婢舉扞之，嶷然山立，硕复欲車前上，車奴攘臂排之，於是遂退。","sortOrder":67},
  {"id":"s_work_nvlt_71_68","chapterId":"ch_work_nvlt_71","text":"《晉中興書》曰：建興九［按當作元。］年冬，左將軍王敦，遣振威將軍周［《太平御覽》七百七十周下有訪字，此脱。］廣武將軍趙誘，受陶侃節度，征蜀賊杜弢，大戰，蜀賊以結槔打没侃二十餘艘，人皆投水。","sortOrder":68},
  {"id":"s_work_nvlt_71_69","chapterId":"ch_work_nvlt_71","text":"義熙起居註曰：盧循新作八槽艦九枚，起四層，高十餘丈。","sortOrder":69},
  {"id":"s_work_nvlt_71_70","chapterId":"ch_work_nvlt_71","text":"荆州土地記曰：桓宣穆遣人尋庐山，上有一湖，中有败艑。","sortOrder":70},
  {"id":"s_work_nvlt_71_71","chapterId":"ch_work_nvlt_71","text":"《江表傳》曰：劉備進駐鄂縣之樊口，諸葛亮詣吳未還，備聞曹公軍下，恐懼，日遣邏吏於水次候權軍，吏望見周瑜船，馳還白備，備曰：何以知非青徐軍耶，吏對曰：以船知之，備遣人慰勞瑜，瑜曰：有軍任，不得委署，傥能屈威，副其所望，備謂張飛關羽曰：彼欲致我，我今自讬於東而不往，非同盟之意也，乃乘单舸往見瑜，問曰：今拒曹公，深為得計，戰卒有幾，瑜曰：三萬人，備曰：恨少，瑜曰：此自足用，豫州但觀瑜破之。","sortOrder":71},
  {"id":"s_work_nvlt_71_72","chapterId":"ch_work_nvlt_71","text":"沈約《宋書》曰：垣護之隨王玄謨入河，玄謨攻滑台，護之三百舸為前鋒，進據右濟，右濟在滑台西南百二十里，玄謨败退，不暇報護之，及護之間知，而虜悉已牵玄謨水軍大艚，連以鐵钅巢三重，欲以絕護之還路，護之中流而下，每至鐵钅巢，辄以長柯斧斷之，虜不能禁，唯失一舸。","sortOrder":72},
  {"id":"s_work_nvlt_71_73","chapterId":"ch_work_nvlt_71","text":"宋元嘉起居註曰：有司奏，初楊州刺史王弘上會稽，從事韦詣解列，先風間［《太平御覽》七百七十一作聞。］餘姚令何玢之，造作平床一，乘船舴艋一艘，精麗過常，用功兼倍，請免玢今官，詔可其奏。","sortOrder":73},
  {"id":"s_work_nvlt_71_74","chapterId":"ch_work_nvlt_71","text":"《異苑》曰：檀道濟，元嘉中，镇尋陽，入伏誅，道濟未下少時，有人施罟於柴桑江，收之，得大船，孔凿若新，使匠作舴艋，勿如折斧，［四字《太平御覽》七百七十一作勿斫二字。］工人誤截兩頭，以為不祥，殺三巧手，欲以塞愆，匠违約加斫，凶兆先遘矣。","sortOrder":74},
  {"id":"s_work_nvlt_71_75","chapterId":"ch_work_nvlt_71","text":"《臨海記》曰：白鵠山有湖，湖中有一石舴艋。","sortOrder":75},
  {"id":"s_work_nvlt_71_76","chapterId":"ch_work_nvlt_71","text":"【詩】梁江祿津渚败船詩曰：可愛木蘭資，可怜丹桂质，逐浪徒言是，乘風還自失，草蔓〈舟習〉長埋，沙巨舷難出，陆沉成許去，無复乘流日。","sortOrder":76},
  {"id":"s_work_nvlt_71_77","chapterId":"ch_work_nvlt_71","text":"梁王筠詠輕利舡應臨汝侯教詩曰：君侯飾輕利，搖荡邁飛雲，凌波漾鹢采，映水煥蛟文，電流已冠絕，鳥逝复超群，倏忽方千里，恋茲歧路分。","sortOrder":77},
  {"id":"s_work_nvlt_71_78","chapterId":"ch_work_nvlt_71","text":"陳張正見後湖汎舟詩曰：上苑奢行樂，沧池聊薄遊，汎荷分蘭棹，沉槎觸桂舟，殘虹收度雨，缺岸上新流，欲知有高趣，長楊送麥秋。","sortOrder":78},
  {"id":"s_work_nvlt_71_79","chapterId":"ch_work_nvlt_71","text":"又別韦谅賦得江湖汎別舟詩曰：千里尋陽岸，三翼木蘭船，鹢汎青凫後，雞鳴白鷺前，涵花没淺纜，帶葉動深船，不言朝夕水，獨自限神仙。","sortOrder":79},
  {"id":"s_work_nvlt_71_80","chapterId":"ch_work_nvlt_71","text":"又與錢玄智汎舟詩曰：高門事休沐，朝野恣逢迎，還乘金穀水，俱望洛陽城，舟移津女渡，楫動渭桥橫，風高雁已落，雨霁水還清，葉盡桐門净，花秋菊岸明，欲奏江南曲，聊習棹歌行。","sortOrder":80},
  {"id":"s_work_nvlt_71_81","chapterId":"ch_work_nvlt_71","text":"【賦】晉棘［《初學記》二十五，《太平御覽》七百七十作棗。］據船賦曰：嘉聖主之神化，理通微而達幽，棹民氓之隔塞，愍王教之不周，立成器以備用，明垂象以造舟，濟渡汲之絕軌，越巨川之玄流，運重固之滯质，雖載沉而必浮，且論器而比象，似君子之淑清，外质朴而無飾，內空虛以受盈，不辭勞而惡動，不偷安以自寧，且其行無轍跡，止無所根，不疾而速，忽若馳奔。","sortOrder":81},
  {"id":"s_work_nvlt_71_82","chapterId":"ch_work_nvlt_71","text":"【贊】晉王叔之舟贊曰：涂則騁車，水惟用舟，弱楫輕棹，利涉濟求，緬彼漁人，鼓枻清謳。","sortOrder":82},
  {"id":"s_work_nvlt_71_83","chapterId":"ch_work_nvlt_71","text":"【銘】後漢李尤舟楫銘曰：舟楫之利，譬猶舆馬，載重歷遠，以濟天下，相風视波，窮究川野，安審懼慎，終無不可。","sortOrder":83},
  {"id":"s_work_nvlt_71_85","chapterId":"ch_work_nvlt_71","text":"春秋《命歷序》曰：人皇九頭，駕六提羽，乘雲車，使風雨。","sortOrder":85},
  {"id":"s_work_nvlt_71_86","chapterId":"ch_work_nvlt_71","text":"《禮斗威儀》曰：山車垂句，山車者，自然之車也，句者曲也，不揉治而自員曲，故言垂句。","sortOrder":86},
  {"id":"s_work_nvlt_71_87","chapterId":"ch_work_nvlt_71","text":"《孝經援神契》曰：德至山陵，則山出根車，［根車，應載養萬物也。］","sortOrder":87},
  {"id":"s_work_nvlt_71_88","chapterId":"ch_work_nvlt_71","text":"括地圖曰：奇肱民能為車，從風遠行，湯時西風久，奇肱車至於豫州，去玉門四萬里，［事具天部風篇。］","sortOrder":88},
  {"id":"s_work_nvlt_71_89","chapterId":"ch_work_nvlt_71","text":"《管子》曰：奚仲之為車也，方圜曲直，皆中規矩鉤繩，故機捉相得，成器堅固，主猶奚仲也，言詞動作，皆中術數，故眾理相當，上下相親，巧者奚仲之所以為器也，主之所以為治也，斫削者斤刀也，故曰奚仲之巧非斫削。","sortOrder":89},
  {"id":"s_work_nvlt_71_90","chapterId":"ch_work_nvlt_71","text":"古史考曰：黃帝作車，引重致遠，少昊時，略加牛，禹時，奚仲加馬。","sortOrder":90},
  {"id":"s_work_nvlt_71_91","chapterId":"ch_work_nvlt_71","text":"《釋名》曰：車古者曰車，聲如居，言行所以居人也，今曰車，車，舍也，行者所以若居舍也。","sortOrder":91},
  {"id":"s_work_nvlt_71_92","chapterId":"ch_work_nvlt_71","text":"《史記》曰：封禪為蒲輪車，惡傷土石草木。","sortOrder":92},
  {"id":"s_work_nvlt_71_93","chapterId":"ch_work_nvlt_71","text":"《尚書大傳》曰：古之帝王者，必有命民，民能敬長怜孤，取舍好讓，舉事力者，君命，然後得乘飾車骈馬文錦，未有命者，不得衣，不乘車，車衣者有罰。","sortOrder":93},
  {"id":"s_work_nvlt_71_94","chapterId":"ch_work_nvlt_71","text":"《淮南子》曰：見飛蓬轉而為車，以類取之也。","sortOrder":94},
  {"id":"s_work_nvlt_71_95","chapterId":"ch_work_nvlt_71","text":"《贾誼書》曰：古之為路舆也，蓋圜以象天，二十八橑，以象列星，軫方以象地，三十輻以象月，故仰則觀天文，俯則察地理，前規睹則鸞和之响，四時之運，此乃舆教之道也。","sortOrder":95},
  {"id":"s_work_nvlt_71_96","chapterId":"ch_work_nvlt_71","text":"應劭漢儀曰：天子法駕，所乘曰金根車，駕六龍，以御天下也，有五色安車，有五色立車，各一，皆駕四馬，是為五時副車。","sortOrder":96},
  {"id":"s_work_nvlt_71_97","chapterId":"ch_work_nvlt_71","text":"《風俗通》曰：車一兩，謂兩兩相與體也，原其所以言兩者，箱裝及輪，兩兩而耦，故稱兩爾。","sortOrder":97},
  {"id":"s_work_nvlt_71_98","chapterId":"ch_work_nvlt_71","text":"《大戴禮》曰：王升車則聞鸞和之聲，是以非僻之心，無自入也，在衡為鸞，在軾為和，馬行而鸞鳴，鸞鳴而和應，其聲曰和，和則敬，此御之節也。","sortOrder":98},
  {"id":"s_work_nvlt_71_99","chapterId":"ch_work_nvlt_71","text":"《周書·王會》曰：成王時，白州獻比闾者，其葉若羽，伐其木以為車，終日行。","sortOrder":99},
  {"id":"s_work_nvlt_71_100","chapterId":"ch_work_nvlt_71","text":"漢雜事曰：古諸侯貳車九乘，秦滅九國，兼其服，故大駕屬車八十一乘，尚書御史乘之，最後一車懸豹尾，以前皆似省中。","sortOrder":100},
  {"id":"s_work_nvlt_71_101","chapterId":"ch_work_nvlt_71","text":"《白虎通》曰：製車以步，故立乘，天子大路，路，大也，道也，正也，君至尊，製度大，所以行道德之正也，諸侯路車，大夫軒車，士飾車。","sortOrder":101},
  {"id":"s_work_nvlt_71_102","chapterId":"ch_work_nvlt_71","text":"《禮記》：有若曰：晏子一狐裘三十年，遣車一乘，國君七个，遣車七乘，大夫五个，遣車五乘，晏子焉知禮。","sortOrder":102},
  {"id":"s_work_nvlt_71_103","chapterId":"ch_work_nvlt_71","text":"又曰：兵車不式，武車緌旌，德車結旌。","sortOrder":103},
  {"id":"s_work_nvlt_71_104","chapterId":"ch_work_nvlt_71","text":"《左傳》曰：齊鄭盟於石門，尋盧之盟也，鄭伯之車僨於濟。","sortOrder":104},
  {"id":"s_work_nvlt_71_105","chapterId":"ch_work_nvlt_71","text":"又曰：公孫閼與穎考叔爭車，穎考叔挟辀而走。","sortOrder":105},
  {"id":"s_work_nvlt_71_106","chapterId":"ch_work_nvlt_71","text":"又曰：天王使家父求車，非禮也，諸侯不貢車服，天子不私求财。","sortOrder":106},
  {"id":"s_work_nvlt_71_107","chapterId":"ch_work_nvlt_71","text":"又曰：狄人滅衛，齊侯使公子無虧戍曹，［曹，衛下邑。］歸公乘馬，祭服五稱，歸夫人魚軒。","sortOrder":107},
  {"id":"s_work_nvlt_71_108","chapterId":"ch_work_nvlt_71","text":"又曰：奚仲為夏車正。","sortOrder":108},
  {"id":"s_work_nvlt_71_109","chapterId":"ch_work_nvlt_71","text":"又曰：晉侯使張骼辅跞致楚師，求御於鄭，鄭人卜，宛射犬吉，子太叔戒之曰：大國之人，不可與也，對曰：無有眾寡，其上一也，太叔曰：培塿無松柏，二子在幄，坐射犬於外，既食而後食之，使御廣車而行，已皆乘乘車，將及楚師，而後從之乘，皆踞轉而鼓琴，近，不告而馳之。","sortOrder":109},
  {"id":"s_work_nvlt_71_110","chapterId":"ch_work_nvlt_71","text":"又曰：慶封來奔，獻車於季武子，美泽可以鑒，展莊叔見之曰：車甚泽，人必瘁，宜其亡也。","sortOrder":110},
  {"id":"s_work_nvlt_71_111","chapterId":"ch_work_nvlt_71","text":"又曰：針適晉，其車千乘，書曰：秦伯之弟針出奔晉，罪秦伯也。","sortOrder":111},
  {"id":"s_work_nvlt_71_112","chapterId":"ch_work_nvlt_71","text":"《論語》曰：升車必正立執綏，車中不內顧，不疾言，不親指。","sortOrder":112},
  {"id":"s_work_nvlt_71_113","chapterId":"ch_work_nvlt_71","text":"《家語》：孔子曰：自南敬叔之乘我車也，而道加行。","sortOrder":113},
  {"id":"s_work_nvlt_71_114","chapterId":"ch_work_nvlt_71","text":"又曰：孔子適衛，子矯仆，靈公與夫人南子同車出，令官者雍渠驂乘，使孔子為次車，遊過市，孔子恥之。","sortOrder":114},
  {"id":"s_work_nvlt_71_115","chapterId":"ch_work_nvlt_71","text":"《孔丛子》曰：孔子使宰予於楚，楚昭王以安車象飾遺孔子，宰予曰：夫子無以為也，王曰：何，對曰：臣自侍衛夫子已來，竊見其言不離道，動不遺仁，貴義尚德，清素好俭，妻不服采，妾不衣帛，車器不雕，馬不食粟，若夫觀物之麗靡，窈妙之浮音，夫子過之弗聽也，故臣知夫子之不用車也。","sortOrder":115},
  {"id":"s_work_nvlt_71_116","chapterId":"ch_work_nvlt_71","text":"《晏子》曰：齊人好击轂相犯以為樂，禁之不止，晏子為新車良馬出，與其人相犯，曰：击轂者不祥，下車而去之，然後國人不為。","sortOrder":116},
  {"id":"s_work_nvlt_71_117","chapterId":"ch_work_nvlt_71","text":"《尸子》曰：文軒六駃，是［《太平御覽》七百七十三作題。］無四寸之鍵，則車不行，小亡則大者不成也。","sortOrder":117},
  {"id":"s_work_nvlt_71_118","chapterId":"ch_work_nvlt_71","text":"《莊子》曰：秦王有疾，召医，破痈潰痤者，得車一乘，舐痔者得車五乘，所治愈多。","sortOrder":118},
  {"id":"s_work_nvlt_71_119","chapterId":"ch_work_nvlt_71","text":"蔡邕《獨斷》曰：凡乘舆車，皆［原訛背，據冯校本改。］羽蓋金華。又黃屋左翿金飐，黃屋者，蓋以黃為里也，左翿者，以旄牛尾為之，大如斗，在左騑馬頭上，金飐者，馬冠也。","sortOrder":119},
  {"id":"s_work_nvlt_71_120","chapterId":"ch_work_nvlt_71","text":"【詩】梁戴嵩車馬詩曰：巩洛風尘處，冠蓋相喷噎，多稱魏其冷，競隨田蚡熱，輪趣白虎第，珂聚黃金穴，獻酒悉蒲陶，詶言盡飛鐵，東都蛇已鑄，西山綬應結，朝集類蒸煙，晚至如吹雪，子雲爾何事，門巷無車轍。","sortOrder":120},
  {"id":"s_work_nvlt_71_121","chapterId":"ch_work_nvlt_71","text":"【銘】後漢冯衍車銘曰：乘車必護輪，治國必愛民，車無輪安處，國無民誰與。","sortOrder":121},
  {"id":"s_work_nvlt_71_122","chapterId":"ch_work_nvlt_71","text":"後漢崔骃車左銘曰：虞夏作車，取象機衡，君子建左，法天之陽，正位受綏，車不內顧，尘不出軌，鸞以節步，彼言不疾，彼指不躬，玄覽於道，永思厥中。又車右銘曰：擇御卜右，采德用良，詢納耆老，於我是匡，惟賢是師，惟道是式，箴闕旅贲，內顧自敕，匪望其度，匪愆其則，越戒敦俭，禮以華國。","sortOrder":122},
  {"id":"s_work_nvlt_71_123","chapterId":"ch_work_nvlt_71","text":"又車後銘曰：敬其在路，體貌思恭，望衡顧轂，允慎茲容，無或好失，匪盤於遊，顧省厥遺，虎尾斯求，昭德塞违，抑盈以無，雖有三晉，鹹然若虛。","sortOrder":123},
  {"id":"s_work_nvlt_71_124","chapterId":"ch_work_nvlt_71","text":"後漢李尤小車銘曰：員蓋象天，方舆則地，輪法陰陽，動不相離，合之嗛噓，疏達开通，兩辎障邪，尊卑是從，輗軏之用，信義所同。","sortOrder":124},
  {"id":"s_work_nvlt_71_125","chapterId":"ch_work_nvlt_71","text":"又天軿車銘曰：奚氏本造，後裔飾雍，輪以代步，屏以從容，輪軿併合，出入周通，追仁赴義，惟禮是恭。","sortOrder":125},
  {"id":"s_work_nvlt_71_126","chapterId":"ch_work_nvlt_71","text":"《藝文類聚》　唐·欧陽詢","sortOrder":126},
  {"id":"s_work_nvlt_72_1","chapterId":"ch_work_nvlt_72","text":"卷七十二食物部","sortOrder":1},
  {"id":"s_work_nvlt_72_2","chapterId":"ch_work_nvlt_72","text":"○食餅肉脯醬鮓酪蘇米酒","sortOrder":2},
  {"id":"s_work_nvlt_72_4","chapterId":"ch_work_nvlt_72","text":"《禮記》曰：古者未有火化，食草木之實，鳥獸之肉。","sortOrder":4},
  {"id":"s_work_nvlt_72_5","chapterId":"ch_work_nvlt_72","text":"《禮含文嘉》曰：燧人氏始炮生為熟。","sortOrder":5},
  {"id":"s_work_nvlt_72_6","chapterId":"ch_work_nvlt_72","text":"《易》曰：君子以飲食宴樂。","sortOrder":6},
  {"id":"s_work_nvlt_72_7","chapterId":"ch_work_nvlt_72","text":"又曰：君子慎言語，節飲食。","sortOrder":7},
  {"id":"s_work_nvlt_72_8","chapterId":"ch_work_nvlt_72","text":"尚書，洪范，三八政，一曰食。","sortOrder":8},
  {"id":"s_work_nvlt_72_9","chapterId":"ch_work_nvlt_72","text":"又大傳曰：八政何竟先食，食者，萬物之始，人之所本者也。","sortOrder":9},
  {"id":"s_work_nvlt_72_10","chapterId":"ch_work_nvlt_72","text":"《周禮》曰：王齊則玉府供玉食。","sortOrder":10},
  {"id":"s_work_nvlt_72_11","chapterId":"ch_work_nvlt_72","text":"又曰：食医，掌和王之六食六飲六膳，百羞百醬，八珍之齊，凡和，春多酸，夏多苦，秋多辛，冬多鹹，調以滑甘，凡會膳食之宜，牛宜稌，羊宜黍，豕宜稷，犬宜粱，雁宜麥，魚宜菰，凡君子之食，嘗放焉。","sortOrder":11},
  {"id":"s_work_nvlt_72_12","chapterId":"ch_work_nvlt_72","text":"《莊子》曰：巧者勞而智者忧，無能者無所求，飽食者遨遊，汎若不系之舟。","sortOrder":12},
  {"id":"s_work_nvlt_72_13","chapterId":"ch_work_nvlt_72","text":"《史記》曰：韓信常數從其下乡南昌亭長寄食，數月，亭長患之，乃晨炊蓐食，信食時往，不為具食，信亦知其怒，竟絕，乃釣城下，諸母漂，有一母見信飢，為設食，信謂漂母曰：吾必有以重報母，母怒曰：丈夫不能自食，吾哀王孫而進食，豈望報乎。","sortOrder":13},
  {"id":"s_work_nvlt_72_14","chapterId":"ch_work_nvlt_72","text":"《說苑》曰：子思居於衛，缊袍無里，二旬九食。","sortOrder":14},
  {"id":"s_work_nvlt_72_15","chapterId":"ch_work_nvlt_72","text":"《漢書》曰：萬石君時，賜食於家，必稽首俯伏，而如在上前，子孫有過，對案不食也。","sortOrder":15},
  {"id":"s_work_nvlt_72_16","chapterId":"ch_work_nvlt_72","text":"《東觀漢記》曰：汝鬱，年五歲，母疾，不能飲食，鬱亦不肯食，母怜之，強為之餐飯，欺言愈，鬱视母色未平，辄不食。","sortOrder":16},
  {"id":"s_work_nvlt_72_17","chapterId":"ch_work_nvlt_72","text":"又曰：梁鸿少孤，以童幼，詣太學受業，治禮詩春秋，常獨坐止，不與人同食。","sortOrder":17},
  {"id":"s_work_nvlt_72_18","chapterId":"ch_work_nvlt_72","text":"王隱《晉書》曰：何曾食，日近萬錢，猶曰無下箸處也。","sortOrder":18},
  {"id":"s_work_nvlt_72_19","chapterId":"ch_work_nvlt_72","text":"又曰：皇甫謐姑子梁抑，為城陽太守，或勸謐送，謐曰：抑為布衣過吾，送迎不出門，食不過鹽菜，貧不以酒肉為禮也，今作郡而送，豈古人之道哉。","sortOrder":19},
  {"id":"s_work_nvlt_72_20","chapterId":"ch_work_nvlt_72","text":"【啟】梁劉孝威謝東宮賜聖僧餘饌啟曰：齊桓柏寢之器，周穆軒宮之寶，乳糜香飯，素〈米奈〉糗漿，五杏七桃，靈瓜仙棗，莫不氣馥上天，薰流下界，石崇芳果，金穀仅於萬株，陳湯木滋，杜陵幾於千树，猶自高謝珍奇，多慚品族。","sortOrder":20},
  {"id":"s_work_nvlt_72_21","chapterId":"ch_work_nvlt_72","text":"又謝東宮賜净饌啟曰：糜獻牛牧，飯出龍宮，千品甘露之食，百花珍藥之果，餅兼髓乳，漿苞蔗愔，雕盤流其滋旨，寶器委其包香，足使五世長者，羞彼識味，一角仙人，恥其咒術，微物多幸，叨奉曲恩，性命可捐，殊私難答。","sortOrder":21},
  {"id":"s_work_nvlt_72_22","chapterId":"ch_work_nvlt_72","text":"陳徐陵謝敕賜祀三皇五帝餘饌啟曰：竊以甘泉之殿，舊禮羲軒，長樂之宮，本圖尧舜，自東京晚世，曠代無聞，西漢盛儀，复睹今日，金壶流十旬之氣，玉案備千品之羞，昔絳羅為荐，既延王母，紫蓋為壇，允招太一，同斯美號，理致眾皇，臣以餘年，豫聞清祀，如陪瑤席，遂飲琼漿。","sortOrder":22},
  {"id":"s_work_nvlt_72_23","chapterId":"ch_work_nvlt_72","text":"【移】梁吳筠移曰：月光離畢，風氣入箕，細雨如網，細柳如絲，離隔東西之怨，眺望山川之阻，企龍門而不見，覽桂枝而延佇，此乃方寸之恒情，羌難得而覼縷也，亦有鮑叔分财，華歆讓位，乃相知於平生，實忘懷於寤寐，雞有呼群之德，鹿有食苹之美，在微物其尚然，况仁義之君子哉，今足下，居則廣夏高堂，連闼洞房，綺窗半卷，屏風角張，指天地如一指，安知故人之可傷，一死一生，乃知交情，一貴一賤，交情乃見，謂古昔之恒談，在今日而方見，呜呼如何，忘我實多，辄欲彈琴縱酒，於首陽之阿，君有厨中腐肉，而仆不厭糟糠，君有雁鶩之食，而餘不得一嘗，原以小人之腹，為君子之腸，何如哉，今欲君之餘，江皋绿葹之筍，洞庭紫鬛之魚，崑山龍胎之脯，玄圃鳳足之菹，千里莼羹，萬丈名脍，氣馨若蘭，色美如艾，扶南甘蔗，一丈三節，白日炙便銷，清風吹即折，安定之梨，皮薄味厚，一歲三花，一枚二升，凡厥上味，惟君能施，君若不施，成君深累，於神為不祥，於人為愆義。","sortOrder":23},
  {"id":"s_work_nvlt_72_25","chapterId":"ch_work_nvlt_72","text":"《漢書》曰：宣帝微時，每買餅，所從買家，辄大售，亦以自怪。","sortOrder":25},
  {"id":"s_work_nvlt_72_26","chapterId":"ch_work_nvlt_72","text":"《三辅舊事》曰：太上不樂關中，高祖徙丰沛屠兒沽酒賣餅商人，立為新丰縣，故一縣多小人。","sortOrder":26},
  {"id":"s_work_nvlt_72_27","chapterId":"ch_work_nvlt_72","text":"《三辅决錄》曰：趙歧避難至北海，於市中販胡餅，孫嵩乘犢車入市，見歧，疑非常人，問曰：自有餅耶，曰：販之，嵩曰：買幾錢，賣幾錢，歧曰：買三十，賣亦三十，嵩曰：视處士之状，非賣餅者，乃开車後，載還家。","sortOrder":27},
  {"id":"s_work_nvlt_72_28","chapterId":"ch_work_nvlt_72","text":"【賦】晉束晳餅賦曰：玄冬猛寒，清晨之會，涕冻鼻中，霜凝口外，充虛解戰，湯餅為最，弱似春綿，白若秋練，氣勃鬱以扬布，香飛散而遠遍，行人失涎於下風，童仆空噍而斜眄，擎器者舐唇，立侍者乾咽。","sortOrder":28},
  {"id":"s_work_nvlt_72_29","chapterId":"ch_work_nvlt_72","text":"【說】梁吳均餅說曰：宋公至長安，得姚泓時故太官丞程季者，了了人也，公曰：今日之食，何者最先，季曰：仲秋御景，離蝉欲靜，燮燮晓風，凄凄夜冷，臣當此景，唯能說餅，公曰：善，季乃稱曰：安定曀鳩之麥，洛陽董德之磨，河東長若之葱，隴西舐背之犢，抱罕赤髓之羊，張掖北門之豉，然以銀屑，煎以金銚，洞庭負霜之橘，仇池連蒂之椒，調以濟北之鹽，剉以新丰之雞，細如華山之玉屑，白如梁甫之銀泥，既聞香而口悶，亦見色而心迷，公曰：善。","sortOrder":29},
  {"id":"s_work_nvlt_72_31","chapterId":"ch_work_nvlt_72","text":"《左傳》曰：晉侯與齊侯投壶，晉侯曰：有酒如川，有肉如坻，寡人中此，為諸侯師。","sortOrder":31},
  {"id":"s_work_nvlt_72_32","chapterId":"ch_work_nvlt_72","text":"《戰國策》曰：晚食以當肉，安行以當車。","sortOrder":32},
  {"id":"s_work_nvlt_72_33","chapterId":"ch_work_nvlt_72","text":"《漢書》曰：伏日，詔賜從官肉，太官丞日晏不來，東方朔獨拔劍割肉，謂其同官曰：伏日當早歸，請受賜，即懷肉去，太官奏之，朔入，上曰：昨賜肉，不待詔，以劍割肉而去，何也，朔免冠謝，上曰：先生起自责也，朔再拜曰：朔來朔來，受賜不待詔，何無禮也，拔劍割肉，一何壮也，割之不多。又何廉也，歸遺細君。又何仁也，上笑曰：使先生自责，乃反自譽，賜酒一石，肉百斤，歸遺細君。","sortOrder":33},
  {"id":"s_work_nvlt_72_34","chapterId":"ch_work_nvlt_72","text":"又曰：鮑宣雲，公奈何獨私養外親，與幸臣董賢，多賞賜，賓客漿酒藿肉，［视酒如漿，视肉如藿。］","sortOrder":34},
  {"id":"s_work_nvlt_72_35","chapterId":"ch_work_nvlt_72","text":"桓谭《新論》曰：關東鄙語曰：人聞長安樂，出門向西笑，知肉味美，則對屠門而嚼。","sortOrder":35},
  {"id":"s_work_nvlt_72_36","chapterId":"ch_work_nvlt_72","text":"【啟】梁劉孝綽謝安成王赉祭孤石廟胙肉啟曰：味過瀹鳳，珍越屠龍，故使屏翳收風，冯夷净浪，神居鹢首，獨汎安流，民幸同附，得徵遘迕，复等受釐，預頒純嘏，恩靈所降，信次委積，報生以死，竊聞斯義。","sortOrder":36},
  {"id":"s_work_nvlt_72_38","chapterId":"ch_work_nvlt_72","text":"《呂氏春秋》曰：趙宣孟之絳，見骫桑之下，有臥饿人，宣孟與脯二朐，拜受而不敢食，問其故，曰：臣有母，持以遺之，宣孟更賜之脯二束而去。","sortOrder":38},
  {"id":"s_work_nvlt_72_39","chapterId":"ch_work_nvlt_72","text":"《尚書大傳》曰：散宜生閎夭南宮括，三子者，學乎太公，太公見三子之為賢人，遂酌酒切脯，約為朋友。","sortOrder":39},
  {"id":"s_work_nvlt_72_40","chapterId":"ch_work_nvlt_72","text":"《漢書》曰：蜀氏以賣脯而連騎，張里以馬医而击鍾。","sortOrder":40},
  {"id":"s_work_nvlt_72_41","chapterId":"ch_work_nvlt_72","text":"《論衡》曰：儒者言泰平時，萐莆生於厨中，厨中自生肉脯，薄如萐形。","sortOrder":41},
  {"id":"s_work_nvlt_72_42","chapterId":"ch_work_nvlt_72","text":"《神仙傳》曰：王遠至蔡經家，與麻姑共設肴膳，擗脯而行，雲是麟脯。","sortOrder":42},
  {"id":"s_work_nvlt_72_43","chapterId":"ch_work_nvlt_72","text":"又曰：左慈詣劉表，雲有薄禮，原以犒軍，表使取之，有酒一器，有脯一盤，千餘人共舉，不能勝，慈自取之，引入，求書刀，削脯投地，百人接酒及脯，賜兵人人酒三杯，酒如故，脯亦不减。","sortOrder":43},
  {"id":"s_work_nvlt_72_44","chapterId":"ch_work_nvlt_72","text":"【啟】梁劉孝威謝東宮赉鹿脯等啟曰：上林絕胡人之搏，禁地無張京之犯，而猶有班超遊獵，李廣馳射，遠歸於厨吏，入貢於腊人，形圖三事之車，影入九仙之鏡。","sortOrder":44},
  {"id":"s_work_nvlt_72_46","chapterId":"ch_work_nvlt_72","text":"《論語》曰：不得其醬不食。","sortOrder":46},
  {"id":"s_work_nvlt_72_47","chapterId":"ch_work_nvlt_72","text":"《漢書》曰：劉歆謂楊雄曰：今學有祿利，然尚不能明易。又如玄何，吾恐後人覆醬瓿，［瓿音部，水罌名也。］","sortOrder":47},
  {"id":"s_work_nvlt_72_48","chapterId":"ch_work_nvlt_72","text":"《風俗通》曰：醬成於鹽，而鹹於鹽，夫物之变，有時而重。","sortOrder":48},
  {"id":"s_work_nvlt_72_49","chapterId":"ch_work_nvlt_72","text":"【啟】梁劉孝儀謝晉安王赉虾醬啟曰：龍醬傳甘，退成可陋，蚳醢稱貴，追覺失言，上聖聞雷，未之能覆，嘉賓流歠，羞無辭窭。","sortOrder":49},
  {"id":"s_work_nvlt_72_51","chapterId":"ch_work_nvlt_72","text":"《列異傳》曰：費長房又能縮地脈，坐客在家，至市買鮓，一日之間，人見之千里外者數處。","sortOrder":51},
  {"id":"s_work_nvlt_72_52","chapterId":"ch_work_nvlt_72","text":"列女後傳曰：吳光祿勋孟宗，為監魚池司馬，罢職，道作兩器鮓，以歸奉母，母怒之曰：吾老為母，戒言唯聽飲彼水，何吾言之不從也，宗曰：於道作之，非池魚也，母曰：汝為主魚吏，而獲鮓以歸，豈可家至戶告耶，乃還鮓於宗，宗伏謝罪，遂沉鮓於江。","sortOrder":52},
  {"id":"s_work_nvlt_72_53","chapterId":"ch_work_nvlt_72","text":"《世說》曰：有人遺張華鮓者，華見之，謂客曰：此龍肉鮓也，鮓中則有五采光，试之，果如言，後問其主，雲於茅積下得白魚所作也。","sortOrder":53},
  {"id":"s_work_nvlt_72_54","chapterId":"ch_work_nvlt_72","text":"又曰：陶侃少時，作魚梁吏，嘗以一坩鮓餉母，母封鮓及書责侃曰：汝為吏，以官物見餉，非唯不能益吾，乃以增吾忧也。","sortOrder":54},
  {"id":"s_work_nvlt_72_55","chapterId":"ch_work_nvlt_72","text":"【啟】齊王融謝司徒賜紫鮓啟曰：東越水羞，寔罄乘時之美，南荆任土，方揖鮓魚之最。","sortOrder":55},
  {"id":"s_work_nvlt_72_56","chapterId":"ch_work_nvlt_72","text":"陳周弘正謝敕赉紫鮓啟曰：珍韜江浦，味越茗川，昔聞八駿東征，上收黑水之麥，七華西讨，才獲苦山之菜，豈如兩階幹舞，四方來格，臨朝拱默，任土爭貢。","sortOrder":56},
  {"id":"s_work_nvlt_72_57","chapterId":"ch_work_nvlt_72","text":"◇酪蘇","sortOrder":57},
  {"id":"s_work_nvlt_72_58","chapterId":"ch_work_nvlt_72","text":"《釋名》曰：酪，泽也，乳汁所作，使人肥泽也。","sortOrder":58},
  {"id":"s_work_nvlt_72_59","chapterId":"ch_work_nvlt_72","text":"《漢武內傳》曰：西王母雲，仙次藥，有太玄之酪。","sortOrder":59},
  {"id":"s_work_nvlt_72_60","chapterId":"ch_work_nvlt_72","text":"晉大康起居註曰：詔雲，尚書令荀勖，既久羸毀，可賜乳酪，太官隨日給之。","sortOrder":60},
  {"id":"s_work_nvlt_72_61","chapterId":"ch_work_nvlt_72","text":"《西河舊事》曰：祁連山，冬夏寒涼，宜牧，牛羊充肥，乳酪好。","sortOrder":61},
  {"id":"s_work_nvlt_72_62","chapterId":"ch_work_nvlt_72","text":"《郭子》曰：陆機詣王武子，武子有數斛羊酪，指以示陆，卿東吳何以敵此，陆雲，有千里莼羹，未下鹽豉。","sortOrder":62},
  {"id":"s_work_nvlt_72_63","chapterId":"ch_work_nvlt_72","text":"《笑林》曰：吳人至京，為設食者，有酪蘇，來［《太平御覽》八百五十八作未。］知是何物也，強而食之，歸吐，遂至困頓，謂其子曰：與伧人同死，亦無所恨，然汝故宜慎之。","sortOrder":63},
  {"id":"s_work_nvlt_72_64","chapterId":"ch_work_nvlt_72","text":"【啟】梁沈約謝司徒賜北蘇啟曰：曠阻陰山之外，眇絕蒲海之東，自非神力所引，莫或輕至，聖慈普洽，遍刍薇，［句有脱文。］停鑣懼喘，既弘道於世務，方駕四衢。又興言於俗表。","sortOrder":64},
  {"id":"s_work_nvlt_72_66","chapterId":"ch_work_nvlt_72","text":"古史考曰：神農時，民食穀，釋米加燒石上而食之。","sortOrder":66},
  {"id":"s_work_nvlt_72_67","chapterId":"ch_work_nvlt_72","text":"《家語》曰：子路見孔子曰：由也事二親之時，常食藜藿之實，而為親負米百里之外，親没之後南遊，從車百乘，積粟萬鍾，重茵而坐，列鼎而食，原欲藜藿，為親負米，而不可得复也。","sortOrder":67},
  {"id":"s_work_nvlt_72_68","chapterId":"ch_work_nvlt_72","text":"荀卿子曰：仁義禮智之於人也，譬之若货财米粟之於家也，多有之者富，少有之者貧，至無者窮。","sortOrder":68},
  {"id":"s_work_nvlt_72_69","chapterId":"ch_work_nvlt_72","text":"《漢書》曰：宣曲任氏，其先為督道仓，秦败，豪杰爭取金玉，任氏獨窖仓粟，楚漢相距滎陽，民不得耕种，米石萬，而豪杰金玉盡歸任氏，任氏以此起富。","sortOrder":69},
  {"id":"s_work_nvlt_72_70","chapterId":"ch_work_nvlt_72","text":"又曰：贾捐之雲，武帝元狩六年，太仓粟紅腐不可食。","sortOrder":70},
  {"id":"s_work_nvlt_72_71","chapterId":"ch_work_nvlt_72","text":"又曰：東方朔雲，如以臣言無可用，則宜捐弃，無空索長安之米。","sortOrder":71},
  {"id":"s_work_nvlt_72_72","chapterId":"ch_work_nvlt_72","text":"《東觀漢記》曰：馬援勸光武伐隗嚣，聚米為山川地势，上曰：虜在吾目中矣。","sortOrder":72},
  {"id":"s_work_nvlt_72_73","chapterId":"ch_work_nvlt_72","text":"又曰：第五倫性節俭，作會稽郡，雖為二千石，臥布被，自養馬，妻炊爨，受俸祿，常求赤米，與小吏受等，财留一月俸，餘皆賤粜與民飢羸者。","sortOrder":73},
  {"id":"s_work_nvlt_72_74","chapterId":"ch_work_nvlt_72","text":"《九州春秋》曰：臧洪為青州刺史，為袁紹所围，糧食盡，厨有米三斗，主簿啟進內，稍以為糜粥，洪叹曰：吾獨食此何味，命使為薄粥，與眾共歠之。","sortOrder":74},
  {"id":"s_work_nvlt_72_75","chapterId":"ch_work_nvlt_72","text":"《吳志》曰：魯肅以振窮士為務，甚得邑人歡心，周瑜為居巢長，將數百人故過候肅，併告資糧，肅家有囷米，各三千斛，乃指一囷與瑜，瑜益知其奇也，遂相親結，定侨札之分。","sortOrder":75},
  {"id":"s_work_nvlt_72_76","chapterId":"ch_work_nvlt_72","text":"又曰：全琮父，使琮赍米數斛到吳，有所市具，琮至，皆散，空船而還，父大怒，琮頓首曰：愚以所市非急，而士大夫方有倒懸之患，故便振贍，不及啟報，父便以奇之。","sortOrder":76},
  {"id":"s_work_nvlt_72_77","chapterId":"ch_work_nvlt_72","text":"《語林》曰：陳寿將為國志，謂丁梁州曰：若可觅千斛米見借，當為尊公作佳傳，丁不與米，遂以無傳。","sortOrder":77},
  {"id":"s_work_nvlt_72_78","chapterId":"ch_work_nvlt_72","text":"《世說》曰：郄嘉賓餉釋道安米千斛，道安答，直雲損米愈覺有待之煩。","sortOrder":78},
  {"id":"s_work_nvlt_72_79","chapterId":"ch_work_nvlt_72","text":"【啟】齊王融謝敕賜米啟曰：臣無王陽之術，計然之智，不能負粟百里，分地一廛，上虧溫養，自取飢切，豈悟外恩橫集，天私妄委。","sortOrder":79},
  {"id":"s_work_nvlt_72_80","chapterId":"ch_work_nvlt_72","text":"梁簡文帝謝敕赉長生米啟曰：尧禾五尺，未足稱珍，漢苗九穗，方斯非擬，如隨瑞鹿，若降神乌，暮律向遊，獻春方始，食乃民天之貴，粒有延齡之名，藉此資身，因斯養性。","sortOrder":80},
  {"id":"s_work_nvlt_72_81","chapterId":"ch_work_nvlt_72","text":"梁庾肩吾謝東宮赉米啟曰：滍水鳴蝉，香聞七里，琼山合穎，租歸十縣，肩吾人慚振藻，徒降雲涧之松，職濫便繁，空撤家承之俸，成珠委地，事重逢仙，遊玉為糧，珍逾入楚，雖复激水沧流，不待濫河之說，春風扫地，方誚文學之篇。","sortOrder":81},
  {"id":"s_work_nvlt_72_82","chapterId":"ch_work_nvlt_72","text":"又謝湘東王赉米啟曰：竊以月滿則虧，恩來無爽，海潮雖大，萬江恒註，遂使連箱委地，不殊陽翟，盈仓接宇，寧異海陵。","sortOrder":82},
  {"id":"s_work_nvlt_72_83","chapterId":"ch_work_nvlt_72","text":"周庾信謝趙王赉米啟曰：比陋巷箪瓢，櫛風沐雨，剝榆皮於秋塞，掘蟄燕於寒山，仰費國租，遂开尘甑，非丹竈而流珠，異荆台而炊玉，東方朔之俸米，既息長飢，西門豹之墾田，方慚此赉。","sortOrder":83},
  {"id":"s_work_nvlt_72_85","chapterId":"ch_work_nvlt_72","text":"古史考曰：古有醴酪，禹時儀狄作酒。","sortOrder":85},
  {"id":"s_work_nvlt_72_86","chapterId":"ch_work_nvlt_72","text":"《毛詩》曰：為此春酒，以介眉寿。","sortOrder":86},
  {"id":"s_work_nvlt_72_87","chapterId":"ch_work_nvlt_72","text":"《禮記》曰：先王為酒醴，一獻之禮，賓主百拜，終日飲酒，而不得醉焉，此先王之所以備酒禍也。","sortOrder":87},
  {"id":"s_work_nvlt_72_88","chapterId":"ch_work_nvlt_72","text":"《左傳》曰：鄭伯有嗜酒，為窟室而夜飲酒，击鍾焉。","sortOrder":88},
  {"id":"s_work_nvlt_72_89","chapterId":"ch_work_nvlt_72","text":"王孫子《新書》曰：楚莊王攻宋，厨有臭肉，樽有败酒，將軍子重諫曰：今君厨肉臭而不可食，樽酒败而不可飲，而三軍之士皆有飢色，欲以勝敵，不亦難乎，莊王曰：請有酒投之士，有食饋之賢。","sortOrder":89},
  {"id":"s_work_nvlt_72_90","chapterId":"ch_work_nvlt_72","text":"《楚辭》曰：蕙有肴兮蘭藉，奠桂酒兮椒漿。","sortOrder":90},
  {"id":"s_work_nvlt_72_91","chapterId":"ch_work_nvlt_72","text":"《呂氏春秋》曰：肥肉厚酒，務以自強，命曰明［《太平御覽》八百四十五作烂。］腸之食。","sortOrder":91},
  {"id":"s_work_nvlt_72_92","chapterId":"ch_work_nvlt_72","text":"黃石公記曰：昔者良將用兵，人有饋一单醪者，使投之於河，令將士迎流而飲之，夫单醪不能味一河水，三軍思為之死，非滋味及之也。","sortOrder":92},
  {"id":"s_work_nvlt_72_93","chapterId":"ch_work_nvlt_72","text":"《史記》曰：晉击秦，缪公傷，於是歧下食善馬者三百人，馳冒晉軍围，遂脱缪公而返，生得晉君，初缪公亡善馬，歧下野人，共得而食之者，三百餘人，逐得，欲法之，公曰：君子不以畜害人，吾聞食善馬肉，不飲酒傷人，乃皆賜酒而赦之。","sortOrder":93},
  {"id":"s_work_nvlt_72_94","chapterId":"ch_work_nvlt_72","text":"又曰：高帝除秦苛法，為簡易，群臣飲酒爭功，高帝患之，叔孫通知上益厭也，說上，原以諸弟子共起朝儀，後七年，長樂宮成，群臣皆朝十月，复置法酒，諸侍坐殿上，皆伏，尊卑次起上寿，觴九行，諸［《太平御覽》八百四十三作謁。］者言罢酒，御史執法，舉不如儀者，辄引去，竟朝置酒，無敢失禮者，高帝乃曰：吾今日知為皇帝之貴也。","sortOrder":94},
  {"id":"s_work_nvlt_72_95","chapterId":"ch_work_nvlt_72","text":"《漢書》曰：百米旨酒，［百日之米酒也，味或作米。］布蘭生，［芬布列，若蘭之生也。］","sortOrder":95},
  {"id":"s_work_nvlt_72_96","chapterId":"ch_work_nvlt_72","text":"又曰：於定國飲酒，至數石不亂，飲益精明，《神異經》曰：西北海外有人，長二千里，兩腳中間，相去千里，腹围一千六百里，但日飲天酒五斗，［天酒，甘露也。］不食五穀魚肉，唯飲天酒，忽有飢時，向天乃飽，好遊山海間，不犯百姓，不幹萬物，與天地同生。","sortOrder":96},
  {"id":"s_work_nvlt_72_97","chapterId":"ch_work_nvlt_72","text":"又曰：西北荒中有酒泉，人飲此酒，酒美如肉，清如鏡，其上有玉樽，取一樽，复一樽出，與天地同休，無乾時，飲此酒人，不死長生。","sortOrder":97},
  {"id":"s_work_nvlt_72_98","chapterId":"ch_work_nvlt_72","text":"東方朔別傳曰：武帝幸甘泉，長平坂道中有虫，赤如肝，頭目口齒悉具，先驅馳還以報，上使视之，莫知也，時朔在屬車中，令往视焉，朔曰：此謂怪氣，是必秦獄處也，上使按地圖，果秦獄地，上問朔何以知之，朔曰：夫積忧者，得酒而解，乃取虫置酒中，立消，賜朔帛百匹，後屬車上盛酒，為此也。","sortOrder":98},
  {"id":"s_work_nvlt_72_99","chapterId":"ch_work_nvlt_72","text":"《十洲記》曰：瀛洲有玉膏，如酒味，名曰玉酒，飲數升辄醉，乃令人長生。","sortOrder":99},
  {"id":"s_work_nvlt_72_100","chapterId":"ch_work_nvlt_72","text":"《孔丛子》曰：平原君與子高飲，強子高酒，曰：昔有遺諺，尧舜千鍾，孔子百觚，子路尚飲百榼，古之賢聖，無不能飲，吾子何辭焉，《續漢書》曰：盧植能飲一石不醉。","sortOrder":100},
  {"id":"s_work_nvlt_72_101","chapterId":"ch_work_nvlt_72","text":"崔寔《四民月令》曰：正月旦，進椒酒，降神畢，各舉椒酒於其家長，［事具椒篇。］","sortOrder":101},
  {"id":"s_work_nvlt_72_102","chapterId":"ch_work_nvlt_72","text":"《魏略》曰：大祖禁酒，而人竊飲之，故難言酒，以白酒為賢者，清酒為聖人。","sortOrder":102},
  {"id":"s_work_nvlt_72_103","chapterId":"ch_work_nvlt_72","text":"《博物志》曰：西域有蒲桃酒，積年不败，彼俗傳雲，可至十年，欲飲之醉，弥日乃解。","sortOrder":103},
  {"id":"s_work_nvlt_72_104","chapterId":"ch_work_nvlt_72","text":"幹寶《晉紀》曰：杜豫作河桥成，武帝幸桥宴，舉觴勸豫曰：非卿，此功不能就，豫曰：自非陛下之聖明，則臣無所施其愚巧也，［事具桥篇。］","sortOrder":104},
  {"id":"s_work_nvlt_72_105","chapterId":"ch_work_nvlt_72","text":"晉中興書曰：畢卓嘗謂人曰：右手執酒杯，左手執蟹螯，拍浮酒池中，便足了一生。","sortOrder":105},
  {"id":"s_work_nvlt_72_106","chapterId":"ch_work_nvlt_72","text":"《語林》曰：劉靈，字伯倫，飲酒一石，至酲，复飲五斗，其妻责之，靈曰：卿可致酒五斗，吾當斷之，妻如其言，靈咒曰：天生劉靈，以酒為名，一飲一石，五斗解酲，婦人之言，慎莫可聽。","sortOrder":106},
  {"id":"s_work_nvlt_72_107","chapterId":"ch_work_nvlt_72","text":"【詩】宋陶潛飲酒詩曰：既醉之後，辄以數句自娱，紙墨遂多，別辭無次，聊命故人書之，以為談笑也，有客常同止，趣舍邈異景，一士長獨醉，一夫終年醒，醒醉還相笑，發言各不領。","sortOrder":107},
  {"id":"s_work_nvlt_72_108","chapterId":"ch_work_nvlt_72","text":"周庾信報趙王賜酒詩曰：梁王修竹園，冠蓋風尘喧，行人忽枉道，直進桃花源，稚子還羞出，驚妻到閉門，始聞傳上命，定是賜中樽，野爐然树葉，山杯捧竹根，風池還更暖，寒穀遂長暄，未知稻粱雁，何時報君恩。","sortOrder":108},
  {"id":"s_work_nvlt_72_109","chapterId":"ch_work_nvlt_72","text":"又正旦蒙趙王赉酒詩曰：正旦辟惡酒，新年長命杯，柏葉隨銘至，椒花逐頌來，流星向碗落，浮蚁對春开，成都已救火，蜀使何時回。","sortOrder":109},
  {"id":"s_work_nvlt_72_110","chapterId":"ch_work_nvlt_72","text":"又中山公許乞酒一車未送詩曰：細柳望蒲台，長河始一回，秋葉幾回落，春蚁未曾开，瑩角非難馭，椎輪稍可摧，只言千日飲，舊逐中山來。","sortOrder":110},
  {"id":"s_work_nvlt_72_111","chapterId":"ch_work_nvlt_72","text":"又就蒲州刺史乞酒詩曰：萧瑟風聲摻，蒼茫雲貌愁，鳥寒栖不定，池凝聚未流，蒲城桑葉落，灞岸菊花秋，原持河朔飲，分勸東陵侯。","sortOrder":111},
  {"id":"s_work_nvlt_72_112","chapterId":"ch_work_nvlt_72","text":"又答王襃餉酒詩曰：今日小園中，桃花數树紅，开君一壶酒，細酌對春風，未能扶畢卓，猶足舞王戎，仙人一捧露，判不及杯中。","sortOrder":112},
  {"id":"s_work_nvlt_72_113","chapterId":"ch_work_nvlt_72","text":"【賦】漢楊雄酒賦曰：子猶瓶矣，觀瓶之居，居井之湄，處高臨深，動常近危，酒醪不入口，藏水滿懷，不得左右，牵於纏徽，自用如此，不如鴟夷，鴟夷滑稽，腹大如壶，盡日盛酒，人复藉酤，常為國器，讬於屬車，出入兩宮，經營公家，由是言之，酒何過乎。","sortOrder":113},
  {"id":"s_work_nvlt_72_114","chapterId":"ch_work_nvlt_72","text":"魏陳王曹植酒賦曰：餘覽楊雄酒賦，辭甚瑰玮，頗戲而不雅，聊作酒賦，粗究其終始，嘉儀氏之造思，亮茲美之獨珍，仰酒旗之景曜，协嘉號於天辰，穆生失禮而辭楚，侯嬴感爵而輕身，其味有宜成醪醴，蒼梧縹清，或秋藏冬發，或春醞夏成，或雲沸川涌，或素蚁如萍，爾乃王孫公子，遊俠翱翔，將承歡以接意，會陵雲之朱堂，獻酬交错，宴笑無方，於是飲者併醉，從橫讙譁，或扬袂屢舞，或扣劍清歌，或嚬蹴辭觴，或奋爵橫飛，或叹驪駒既駕，或稱朝露未晞，於斯時也，质者或文，刚者或仁，卑者忘賤，窭者忘貧，於是矯俗先生，聞之而叹曰：噫，夫言何容易，此乃淫荒之源，非作者之事，若耽於觴酌，流情縱佚，先王所禁，君子所失。","sortOrder":114},
  {"id":"s_work_nvlt_72_115","chapterId":"ch_work_nvlt_72","text":"魏王粲酒賦曰：帝女儀狄，旨酒是獻，苾芬享祀，人神式宴，辯其五齊，節其三事，醍沉盎泛，清濁各異，章文德於廟堂，协武義於三軍，致子弟之孝養，糾骨肉之睦親，成朋友之懽好，贊交往之主賓，既無禮而不入。又何事而不因，賊功業而败事，毀名行以取誣，遺大恥於載籍，滿簡帛而見書，孰不飲而羅茲，罔非酒而惟事，昔在公旦，極茲話言，濡首屢舞，談易作難，大禹所忌，文王是艱。","sortOrder":115},
  {"id":"s_work_nvlt_72_116","chapterId":"ch_work_nvlt_72","text":"晉張載酃酒賦曰：惟聖賢之興作，貴垂功而不泯，嘉康狄之先識，亦應天而順民，擬酒旗於玄象，造甘醴以怡神，雖賢愚而同好，似大化之齊均，物無往而不变，獨居舊而弥新，經盛衰而無废，歷百代而作珍，若乃中山冬啟，醇酎秋發，長安春御，樂浪夏設，縹蚁蓱布，芬香酷烈，垂嘉稱於百代，信人神之所悅，故為其酒也，殊功絕倫，三事既節，五齊必均，造酿以秋，告成以春，備味滋和，體淳色清，宣御神志，导氣養形，遺忧消患，適性順情，於是糾合同好，以遨以遊，嘉賓雲會，矩坐四周，設罍樽於南楹，酌浮觴以旋流，備鮮肴之綺错，進時膳之珍羞，禮儀攸序，是獻是酬，鹹得志以自足，原栖遲於一丘，於是歡樂既洽，日薄西隅，主稱湛露，賓歌驪駒，仆夫整駕，言旋其居，乃凭軾以回軌，騁輕驷於通衢，及衡門以隱跡，覽前聖之典謨，感夏禹之防微，悟儀氏之見疏，鑒往事而作誡，罔非酒而惟愆，哀秦穆之見谬，惜三良之殲賢，嘉衛武之能悔，著屢舞於初筵，察成败於往古，垂將來於茲篇。","sortOrder":116},
  {"id":"s_work_nvlt_72_117","chapterId":"ch_work_nvlt_72","text":"【頌】魏劉伶酒德頌曰：有大人先生，以天地為一朝，萬期為須臾，日月為牖戶，八荒為庭衢，行無轍跡，居無室庐，幕天席地，縱意所如，止則操卮執觚，動則挈榼提壶，唯酒是務，焉知其餘，有貴介公子，搢紳處士，聞吾風聲，議其所以，乃奋袂攘衿，怒目切齒，陳說禮法，是非鋒起，先生於是捧罌承槽，衔杯歠醪，奋鬢箕踞，枕麹藉糟，無思無慮，其樂陶陶。","sortOrder":117},
  {"id":"s_work_nvlt_72_118","chapterId":"ch_work_nvlt_72","text":"【引】梁朱異田飲引曰：卜田宇兮京之陽，面清洛兮背脩邙，屬風林之萧瑟，值寒野之蒼茫，鵬紛紛而聚散，鸿冥冥而遠翔，酒沉兮俱發，雲沸兮波扬，豈味薄於東魯，鄙蜜甜於南湘，於是客有不速，朋自遠方，臨清池而涤器，辟山牖而飛觴，促膝兮道故，久要兮不忘，聞談希夷之理，或賦連翩之章。","sortOrder":118},
  {"id":"s_work_nvlt_72_119","chapterId":"ch_work_nvlt_72","text":"【戒】晉庾闡斷酒戒曰：蓋神明智惠，人之所以靈也，好惡情Q欲Y，人之所以生也，明智運於常厓，好惡安於自然，吾固以窮智之害性，任欲之丧真也，於是椎金罍，碎玉碗，破兕觥，捐觚瓒，遺舉白，废引滿，使巷無行榼，家無停壶，剖樽折杓，沈炭銷爐，屏神州之竹葉，絕縹醪乎華都，言未及盡，有一醉夫，勃然作色曰：蓋空桑珍味，始於無情，靈和陶醞，奇液特生，聖賢所美，百代同營，故醴泉涌於上世，懸象煥乎列星，斷蛇者以興霸，折獄者以流聲，是以達人畅而不壅，抑其小節，而濟大通，子獨區區，捡情自封，無或口閉其味，而心馳其聽者乎，庾生曰：爾不聞先哲之言乎，人生而靜，天之性也，感物而動，性之欲也，物之感人無窮，而情之好惡無節，故不見可欲，使心不亂，是以惡跡止步，滅影即陰，形情絕於所讬，萬感無累乎心，心靜則樂非外唱，樂足則欲無所淫，唯味作戒，其道弥深，賓曰唯唯，敬承德音。","sortOrder":119},
  {"id":"s_work_nvlt_72_120","chapterId":"ch_work_nvlt_72","text":"【啟】梁劉孝儀謝東宮赉酒啟曰：異五齊之甘，非九醞之法，屬車未曾載，油囊不得酤，试儔仙树，葛玄泥首，才比蒲桃，孟他衔璧，固知讬之養性，妙解怡神，擬彼聖人，羞得連類。","sortOrder":120},
  {"id":"s_work_nvlt_72_121","chapterId":"ch_work_nvlt_72","text":"【書】後漢孔融難魏武帝禁酒書曰：公初當來，邦人鹹抃舞踴躍，以望我後，亦既至止，酒禁施行，天垂酒旗之曜，地列酒泉之郡，人有旨酒之德，尧非千鍾，無以建太平，孔非百觚，無以堪上聖，樊哙解厄鸿門，非彘肩卮酒，無以奋其怒，趙之厮養，東迎其王，非引卮酒，無以激其氣，高祖非醉斬白蛇，無以扬其靈，袁盎非醇醪之力，無以服其命，定國非酣飲一斛，無以决法令，故郦生以高陽酒徒，著功於漢，屈原以餔糟歠醨，身困於楚，猶是觀之，酒何負於治者哉。","sortOrder":121},
  {"id":"s_work_nvlt_72_122","chapterId":"ch_work_nvlt_72","text":"《藝文類聚》　唐·欧陽詢","sortOrder":122},
  {"id":"s_work_nvlt_73_1","chapterId":"ch_work_nvlt_73","text":"卷七十三雜器物部","sortOrder":1},
  {"id":"s_work_nvlt_73_2","chapterId":"ch_work_nvlt_73","text":"○鼎鎗鉢塸盤樽卮杯碗","sortOrder":2},
  {"id":"s_work_nvlt_73_4","chapterId":"ch_work_nvlt_73","text":"《說文》曰：鼎，三足兩耳，和五味之彝器也，昔禹貢九牧之金，鑄鼎荆山之下，以入山林川泽，魑魅魍魉，莫能逢之。","sortOrder":4},
  {"id":"s_work_nvlt_73_5","chapterId":"ch_work_nvlt_73","text":"又曰：鼎，大上下小。","sortOrder":5},
  {"id":"s_work_nvlt_73_6","chapterId":"ch_work_nvlt_73","text":"《爾雅》曰：鼎絕大謂之鼐，圓弇上謂之鼒，鼒，子鼎，附耳外謂之翼。","sortOrder":6},
  {"id":"s_work_nvlt_73_7","chapterId":"ch_work_nvlt_73","text":"《周易》曰：鼎象也，九四曰：鼎折足，覆公餗，六五，鼎黃耳，金铉，利貞，上九，玉铉，大吉。","sortOrder":7},
  {"id":"s_work_nvlt_73_8","chapterId":"ch_work_nvlt_73","text":"《禮記》曰：崇鼎貫鼎，大黃封父龟，天子之器。","sortOrder":8},
  {"id":"s_work_nvlt_73_9","chapterId":"ch_work_nvlt_73","text":"《毛詩》曰：絲衣其紑，載弁俅俅，自堂徂基，自羊徂牛，鼐鼎及鼒。","sortOrder":9},
  {"id":"s_work_nvlt_73_10","chapterId":"ch_work_nvlt_73","text":"三禮鼎器圖曰：牛鼎，受一斛，天子飾以黃金，諸侯白金，有鼻目，以銅為之，三足。","sortOrder":10},
  {"id":"s_work_nvlt_73_11","chapterId":"ch_work_nvlt_73","text":"《左傳》曰：宋華督已殺孔父而弒殇公，召莊公於鄭而立之，以郜大鼎賂公，夏四月，取郜大鼎於宋，納於太廟，非禮也。","sortOrder":11},
  {"id":"s_work_nvlt_73_12","chapterId":"ch_work_nvlt_73","text":"又曰：楚子伐陆浑之戎，遂至於離宮，王使王孫滿勞楚子，楚子問鼎之大小輕重，對曰：在德不在鼎，昔夏之方有德也，遠方圖物，貢金九牧，鑄鼎象物，桀有昏德，鼎遷於商，商紂暴虐，鼎遷於周，德之休明，雖小重也，其奸回昏亂，雖大輕也，周德雖衰，天命未改，鼎之輕重，未可問也，［事具祥瑞部鼎篇。］","sortOrder":12},
  {"id":"s_work_nvlt_73_13","chapterId":"ch_work_nvlt_73","text":"又曰：徐子及郯人莒人，會齊侯，盟於蒲隧，賂以甲父之鼎。","sortOrder":13},
  {"id":"s_work_nvlt_73_14","chapterId":"ch_work_nvlt_73","text":"《墨子》曰：巫馬子問《墨子》曰：鬼神孰與聖人明智，《墨子》曰：鬼神明於聖人，猶聰明耳目之與聋盲也，若夏後开使飛廉折金於山，以鑄鼎於崑吾，使翁難乙灼目若之龟，成曰：鼎成四足而方，不灼自成，不舉自藏，不遷自行，乙又言繇曰：逢逢白雲，一南一北，一西一東，九鼎既成，而遷三國，此知必千年，無聖之智，豈能知哉。","sortOrder":14},
  {"id":"s_work_nvlt_73_15","chapterId":"ch_work_nvlt_73","text":"《史記》曰：伊尹欲幹湯而無由，乃為有莘媵臣，負鼎俎，以滋味說湯，致於王道。","sortOrder":15},
  {"id":"s_work_nvlt_73_16","chapterId":"ch_work_nvlt_73","text":"又曰：秦武王與孟說舉龍文赤鼎，絕臏死。","sortOrder":16},
  {"id":"s_work_nvlt_73_17","chapterId":"ch_work_nvlt_73","text":"又曰：漢武時，汾陰巫錦，為民祠魏睢後土，得鼎，鼎大，異於眾鼎，乃以禮祠迎鼎至甘泉，從行，上荐之，至中山，山有黃雲蓋焉，有鹿過，上自射之，因以祭，至長安，公卿大夫皆議，請尊寶鼎，有司皆曰：黃帝作寶鼎三，象天地人也，禹收九牧之金，鑄九鼎，今鼎至甘泉，承休無疆，中山有黃白雲降蓋，而帝者心知其意，而合德焉，鼎宜見於祖祢，藏於帝庭，以合明應，製曰：可。","sortOrder":17},
  {"id":"s_work_nvlt_73_18","chapterId":"ch_work_nvlt_73","text":"《淮南子》曰：阖闾伐楚，五戰入郢，燒高府之粟，破九龍之鼎，［高府，大仓也，形九龍於鼎以為名，言大鼎也。］鞭平王之墓，舍昭王之宮。","sortOrder":18},
  {"id":"s_work_nvlt_73_19","chapterId":"ch_work_nvlt_73","text":"《說苑》曰：湯時大旱七年，煎沙烂石，於是使人三足鼎祝山川，教之祝曰：政不節耶，使民疾耶，苞苴行耶，讒夫昌耶，宮室營耶，女謁成耶，何不雨之極也，言未已，天大雨，《東觀漢記》曰：永平六年，庐江太守貢寶鼎。","sortOrder":19},
  {"id":"s_work_nvlt_73_20","chapterId":"ch_work_nvlt_73","text":"《吳越春秋》曰：吳王阖闾，葬女於郭西昌門外，凿地為池，積土為山，文石為椁，金鼎玉杯，銀樽珠襦之寶，皆以送之。","sortOrder":20},
  {"id":"s_work_nvlt_73_21","chapterId":"ch_work_nvlt_73","text":"南越書曰：熙安縣山下，有神鼎，天清水澄則見鼎，刺史劉道錫，常使系其耳而牵之，耳脱而鼎潛，既而執纼者莫不疾耳，蓋尉他之鼎。","sortOrder":21},
  {"id":"s_work_nvlt_73_22","chapterId":"ch_work_nvlt_73","text":"又曰：永城縣江前有神鼎，圓數里，耳高五六丈，葛稚川雲，赤松子陶金丹鼎。","sortOrder":22},
  {"id":"s_work_nvlt_73_23","chapterId":"ch_work_nvlt_73","text":"《晉中興書》曰：神鼎見，鼎者仁器也，能息能行，不灼而沸，不汲而盈，煙煴之氣，自然所生也，亂則藏於深山，文明應運而至，故禹鑄鼎以擬之，［事具祥瑞部鼎篇。］","sortOrder":23},
  {"id":"s_work_nvlt_73_24","chapterId":"ch_work_nvlt_73","text":"【銘】後漢崔瑗窦大將軍鼎銘曰：大禹鑄鼎，象物百神，饗帝養賢，命錫宗臣，三距金铉，公德配焉，雉膏之灾，鹹在擇人，惟王建國，分之彝器，鼎為元寶，君臣享位，足勝其任，鬻保寶器，持盈若冲，滿而不溢，黃耳不革，玉铉終吉，禹鏤其鼎，湯刻其盤，紀功申戒，貽則後人。","sortOrder":24},
  {"id":"s_work_nvlt_73_25","chapterId":"ch_work_nvlt_73","text":"後漢李尤鼎銘曰：五鼎大和，滋味集具，雖快其口，損之為務。","sortOrder":25},
  {"id":"s_work_nvlt_73_26","chapterId":"ch_work_nvlt_73","text":"古鼎銘曰：王命尸臣，官此拘邑，賜爾和鸞，黼黻琱弋，尸臣拜手，曰：敢對扬天子丕顯休命。","sortOrder":26},
  {"id":"s_work_nvlt_73_27","chapterId":"ch_work_nvlt_73","text":"後漢崔骃仲山父鼎銘曰：鼎耳革，其行塞，雉膏不食，方雨虧悔，終吉有福，足勝其任，公餗乃珍，於高思危，在滿戒溢，可以永年，天之大律。","sortOrder":27},
  {"id":"s_work_nvlt_73_28","chapterId":"ch_work_nvlt_73","text":"梁周舍鼎銘曰：天下寧康，異方同軌，九牧作貢，百司鹹理，范金鑄器，戒镇階所，波圓月鏡，傳之無已。","sortOrder":28},
  {"id":"s_work_nvlt_73_30","chapterId":"ch_work_nvlt_73","text":"《東宮舊事》曰：皇太子初拜，給銅龍頭鎗。","sortOrder":30},
  {"id":"s_work_nvlt_73_31","chapterId":"ch_work_nvlt_73","text":"《笑林》曰：太原人夜失火，出物，欲出銅鎗，誤出熨貐，便大驚惋，語其兒曰：異事，火未至，鎗已被燒失腳。","sortOrder":31},
  {"id":"s_work_nvlt_73_32","chapterId":"ch_work_nvlt_73","text":"【詩】梁吳筠以服散鎗赠殷鈞詩曰：玉铉布交文，金丹煥仙說，九沸翻成缓，七轉良為切，執以代疏麻，長貽故人別。","sortOrder":32},
  {"id":"s_work_nvlt_73_34","chapterId":"ch_work_nvlt_73","text":"浮圖澄傳曰：澄以鉢盛水，燒香咒之，須臾，鉢中生青莲華。","sortOrder":34},
  {"id":"s_work_nvlt_73_35","chapterId":"ch_work_nvlt_73","text":"西域傳曰：諸國志曰：佛鉢在乾紘越國，青玉也，受三斗許，彼國寶之，供養原終日花香不滿，則如言也，原一把滿，亦隨言也。","sortOrder":35},
  {"id":"s_work_nvlt_73_36","chapterId":"ch_work_nvlt_73","text":"交州雜事曰：太康四年，刺史陶璜，表送臨邑王花然［《太平御覽》七百五十九作范熊，此訛。］所獻銀鉢一口，水精鉢一口。","sortOrder":36},
  {"id":"s_work_nvlt_73_37","chapterId":"ch_work_nvlt_73","text":"支僧載外國事曰：佛鉢在大月氏國，一名佛律婆越國，是天子之都也，起浮圖，浮圖高四丈，七層，四壁里有金銀佛像，像悉如人高，鉢處中央，在第二層上，作金絡絡鉢，钅巢懸鉢，鉢是石也，其色青。","sortOrder":37},
  {"id":"s_work_nvlt_73_38","chapterId":"ch_work_nvlt_73","text":"又曰：摩竭提國，在迦維越之南，相去四十由旬，貝多树去摩竭提三十里，一名毗波梨，佛唯在此一树下坐，滿六年，長者女以金鉢盛牛乳糜上佛，佛得乳糜，往尼連禪河浴，浴竟，於水邊啖糜，啖糜竟，掷鉢水中，逆流可百步許，然後鉢复流河中，架梨那龍王接取鉢，在宮中供養。","sortOrder":38},
  {"id":"s_work_nvlt_73_39","chapterId":"ch_work_nvlt_73","text":"法顯記曰：弗樓沙國，有佛鉢，昔月氏王大興眾，來伐此國，欲取佛鉢，既服此國已，月氏王篤信佛法，欲持鉢去去，乃校飾大象，置鉢其上，象便伏地，不能得進，更作四輪車載鉢，八象共牵，复不能進，王知與鉢無緣，深自愧叹，即於此處起塔，及僧伽藍。","sortOrder":39},
  {"id":"s_work_nvlt_73_40","chapterId":"ch_work_nvlt_73","text":"【啟】齊王融謝安陆王賜銀鉢啟曰：素人之貴，有訪仙經，镌刻可奇，見符神鼎，撤膳器於珍羞之席，降寶玩於箪瓢之門。","sortOrder":40},
  {"id":"s_work_nvlt_73_41","chapterId":"ch_work_nvlt_73","text":"梁劉孝儀謝鄱陽王賜銀鉢啟曰：珍窮货貢，製極范金，用貴寶樽，文包龍鼎，雕鏤海籍，圖載山經，閱眾靈於器中，弄神奸於掌里，足令任後所欲，遠慚漢世，少君有觌，遙羌齊寢。","sortOrder":41},
  {"id":"s_work_nvlt_73_43","chapterId":"ch_work_nvlt_73","text":"《抱朴子》曰：取金液及水銀，以黃土塸盛，置之猛火上，皆化為丹，以此丹金為盤碗，食其中，令人長生，袁彦伯羅山疏曰：善道門［《太平御覽》七百五十九作善道开，按當作单道开。］尸，在石室北壁下，形骸朽坏，止有白骨在，昔成都識此道士，聞之使人慨然，其業行殊異，冀當蝉蜕解骨耳，石室中先有塸盛香，得便扫除燒香。","sortOrder":43},
  {"id":"s_work_nvlt_73_44","chapterId":"ch_work_nvlt_73","text":"【啟】梁皇太子謝敕赉廣門塸等啟曰：淮南承月之杯，豈均符采，西國浮雲之碗，非謂瑰奇，臣南珍靡究，未讀奏曹之表，方物罕逢，不識議郎之畫。","sortOrder":44},
  {"id":"s_work_nvlt_73_46","chapterId":"ch_work_nvlt_73","text":"《周官》曰：玉府，掌王之金玉，若合諸侯，則供珠盤玉敦。","sortOrder":46},
  {"id":"s_work_nvlt_73_47","chapterId":"ch_work_nvlt_73","text":"《禮記》曰：湯之盤銘，德日新。又日新。","sortOrder":47},
  {"id":"s_work_nvlt_73_48","chapterId":"ch_work_nvlt_73","text":"康誥曰：作新民，詩雲，周雖舊邦，其命惟新，是故君子無所不用其極，［盤銘，刻戒於盤，極猶盡也，君子新其德，盡其心力，不有餘也。］","sortOrder":48},
  {"id":"s_work_nvlt_73_49","chapterId":"ch_work_nvlt_73","text":"《左傳》曰：莒人伐我東鄙，围台，季武子救台，遂入鄆，取其鍾，以為公盤。","sortOrder":49},
  {"id":"s_work_nvlt_73_50","chapterId":"ch_work_nvlt_73","text":"《史記》曰：毛遂謂楚王之左右，取雞狗馬之血來，毛遂奉銅盤血而跪進之楚王曰：王當唼盟而定從，次者吾君，次者遂，定從於殿上，遂右手持盤，而左手招十九人曰：公相與唼此血於堂下，公等碌碌，所謂因人成事者也。","sortOrder":50},
  {"id":"s_work_nvlt_73_51","chapterId":"ch_work_nvlt_73","text":"《孫卿子》曰：君者盤也，水者民也，盤圓則水圓，盤方則水方。","sortOrder":51},
  {"id":"s_work_nvlt_73_52","chapterId":"ch_work_nvlt_73","text":"《神異經》曰：西北有金樓，上有銀盤，廣五十丈。","sortOrder":52},
  {"id":"s_work_nvlt_73_53","chapterId":"ch_work_nvlt_73","text":"《漢武內傳》曰：西王母以七月七日降帝宮，命侍女索桃，須臾，以玉盤盛桃七枚，大如鸭卵，形圓色青，以呈王母，王母以四枚與帝，自食三枚矣。","sortOrder":53},
  {"id":"s_work_nvlt_73_54","chapterId":"ch_work_nvlt_73","text":"應劭《漢官儀》曰：封禪壇南有玉盤，盤中有玉龟。","sortOrder":54},
  {"id":"s_work_nvlt_73_55","chapterId":"ch_work_nvlt_73","text":"《風土記》曰：越俗，飲宴即鼓盤以為樂，取大素圜盤，以廣尺六者，抱以著腹，以右手五指更彈之，以為節，舞者應節而舉。","sortOrder":55},
  {"id":"s_work_nvlt_73_56","chapterId":"ch_work_nvlt_73","text":"【詩】梁沈約詠竹槟榔盤詩曰：梢風有劲质，景用道非一，平織方以文，穿成圓且密。","sortOrder":56},
  {"id":"s_work_nvlt_73_57","chapterId":"ch_work_nvlt_73","text":"【賦】魏毌丘俭承露盤賦曰：树根芳林，濯景天池，嘉木靈草，绿葉素枝，飛閣鱗接而從連，層台偃蹇以橫施，龟龍怪獸，嬉遊乎其中，诡類壮觀，雜遝眾多，若乃肇製模鎔，應变入神，窮數極理，究盡物倫，命班爾，召淳均，撰蘭藉，簡良辰，采名金於崑丘，斬扶桑以為薪，詔燭龍使吐火，運混元以陶甄，殴陰陽而役神物，豈取力於烝民，用能弗營，不日而成，匪雕匪斫，天挺之靈，雄幹碣以高立，幹雲霧而上征，蓋取象於蓬萊，實神明之所凭，峻極過於阆風，鳳高翔而弗升，遠而望之，若紫霓下鄰，双鵾集焉，即而视之，若璆琳之柱，華蓋在端，上际辰極，下通九原，仙掌仙掌，既平且安，越古今而無匹，信奇異之可觀。又能致休徵以辅性，豈徒虛設於芳園，采和氣之精液，承清露於飛雲。","sortOrder":57},
  {"id":"s_work_nvlt_73_58","chapterId":"ch_work_nvlt_73","text":"【銘】後漢李尤盤銘曰：或以承觴，或以受物，既舉清觴。又成口實。","sortOrder":58},
  {"id":"s_work_nvlt_73_59","chapterId":"ch_work_nvlt_73","text":"魏毌丘俭承露盤銘曰：赫赫聖魏，紹天惟則，承露瑰生，爰詔懿德，下有蛟龍，偃蹇虬紛，上有層盤，厲彼青雲，脩茎擢擢，高弗可及，仙掌岧岧，零露是集，有直其體，有固斯基，休徵攸降，神明攸持，少昊惟好，我後斯同，以近眉寿，以保萬邦。","sortOrder":59},
  {"id":"s_work_nvlt_73_60","chapterId":"ch_work_nvlt_73","text":"魏陳王曹植承露盤銘曰：岧岧承露，峻極大清，神石蛇畾蛇鬼，洪基嶽停，下潛醴泉，上受雲英，和氣四充，翔鳳所經，匪我明後，孰能經營，近歷闡度，三光朗明，殊俗歸義，祥瑞混併，鸞鳳晨栖，甘露宵零，神明攸挟，高而不傾，奉戴巍巍，恭統神器，固若露盤，長存永貴，賢聖繼跡，弈世明德，不忝先功，保茲皇極，垂祚亿兆，永荷天秩。","sortOrder":60},
  {"id":"s_work_nvlt_73_61","chapterId":"ch_work_nvlt_73","text":"晉殷仲堪酒盤銘曰。","sortOrder":61},
  {"id":"s_work_nvlt_73_62","chapterId":"ch_work_nvlt_73","text":"節有宜藥惑最","sortOrder":62},
  {"id":"s_work_nvlt_73_64","chapterId":"ch_work_nvlt_73","text":"禮─┼─體狂─┼─觴","sortOrder":64},
  {"id":"s_work_nvlt_73_66","chapterId":"ch_work_nvlt_73","text":"為酒悅醉德惡","sortOrder":66},
  {"id":"s_work_nvlt_73_68","chapterId":"ch_work_nvlt_73","text":"《爾雅》曰：彝卣罍，器也，小罍謂之坎，卣，中樽也。","sortOrder":68},
  {"id":"s_work_nvlt_73_69","chapterId":"ch_work_nvlt_73","text":"《禮記》曰：廟堂之上，罍樽在阼，犧樽在西。","sortOrder":69},
  {"id":"s_work_nvlt_73_70","chapterId":"ch_work_nvlt_73","text":"又曰：泰有虞氏之樽也，山罍夏後氏之樽，著殷樽，犧象周樽。","sortOrder":70},
  {"id":"s_work_nvlt_73_71","chapterId":"ch_work_nvlt_73","text":"《莊子》曰：百年之木，破為犧樽，青黃以文之，其斷在溝中，比犧樽於溝中之斷，則美惡有聞［《太平御覽》七百六十一作間。］矣，其於失性，一也。","sortOrder":71},
  {"id":"s_work_nvlt_73_72","chapterId":"ch_work_nvlt_73","text":"《淮南子》曰：聖人之道，猶中衢而設樽耶，過者斟酌，各得其宜，［事具人部聖篇。］","sortOrder":72},
  {"id":"s_work_nvlt_73_73","chapterId":"ch_work_nvlt_73","text":"又曰：夫奉一爵酒，不知於邑，［言其輕也。］挈萬石樽，則曰汗交，［言其重也。］又况羸［淮南子脩務篇作贏。］天下之忧，而任海內之事者乎，二者重於樽亦遠矣，［遠猶多也。］","sortOrder":73},
  {"id":"s_work_nvlt_73_74","chapterId":"ch_work_nvlt_73","text":"《漢書》曰：成都侯商子邑，為大司空，貴重，商故人皆敬之，事邑，唯樓護自安舊節，邑亦事之，不敢有闕，時請召賓客，邑居樽下，稱賤子上寿，坐百數，皆離席伏，護獨東向正坐。","sortOrder":74},
  {"id":"s_work_nvlt_73_75","chapterId":"ch_work_nvlt_73","text":"《東觀漢記》曰：劉文及蘇茂易［東觀漢記作臣於二字。］永，上遣王霸讨之，霸至，遂閉門堅守，勞賜吏士，作冒［《太平御覽》七百六十一作倡。］樂，賦［賦字御覽無，疑衍。］賊懽呼，雨射營中，中霸前酒樽。","sortOrder":75},
  {"id":"s_work_nvlt_73_76","chapterId":"ch_work_nvlt_73","text":"孔融別傳曰：融常叹曰：坐上客恒滿，樽中酒不空，吾無忧矣，［事具人部叙志篇。］","sortOrder":76},
  {"id":"s_work_nvlt_73_77","chapterId":"ch_work_nvlt_73","text":"【詩】魏文帝詩曰：良辰啟初節，高會構懽娱，明爵浮象樽，珍膳盈豆區。","sortOrder":77},
  {"id":"s_work_nvlt_73_78","chapterId":"ch_work_nvlt_73","text":"【銘】後漢崔骃樽銘曰：惟歲之元，朝贺奉樽，金罍犧象，嘉禮具存，獻酬交错，萬國鹹歡。","sortOrder":78},
  {"id":"s_work_nvlt_73_79","chapterId":"ch_work_nvlt_73","text":"後漢蔡邕酒樽銘曰：酒以成禮，弗繼以淫，德將無荒，過則荒沉，盈而不冲，古人所箴，尚鑒茲器，茂勖厥心。","sortOrder":79},
  {"id":"s_work_nvlt_73_80","chapterId":"ch_work_nvlt_73","text":"後漢李尤樽銘曰：樽設在堂，以俟俊乂，三山共承，雕瑑错帶。","sortOrder":80},
  {"id":"s_work_nvlt_73_81","chapterId":"ch_work_nvlt_73","text":"晉孫綽樽銘曰：大匠體物，妙思入神，儀彼靈禽，製器為人，虛以含有，文以飾身，湛此玄醴，延我嘉賓，興懷寄詠，聊以摽設，詳觀茲器，妙巧奇絕，酌焉則註，受滿則侧，吐寫適會，未見其竭，與之無若，施而有節，玄應忘知，切存不伐，王公擬之，德齊上哲。","sortOrder":81},
  {"id":"s_work_nvlt_73_82","chapterId":"ch_work_nvlt_73","text":"宋何偃常滿樽銘曰：貞明麗象，昃食中望，唯茲奇器，神絕莫尚，斟酌賦受，不逾其量，凫鹥之詩，豈伊異况。","sortOrder":82},
  {"id":"s_work_nvlt_73_84","chapterId":"ch_work_nvlt_73","text":"《韓子》曰：棠谿空見昭侯曰：今有白玉卮而無當，瓦器有當，君渴，將何以飲，曰：以瓦器，空曰：白玉卮美而君不［《太平御覽》七百六十一不下有以飲者三字。］以其無當耶，曰：然，空曰：為人君漏泄群臣語，猶玉卮無當也，空每見出，昭侯必獨臥，唯恐夢言泄妻妾。","sortOrder":84},
  {"id":"s_work_nvlt_73_85","chapterId":"ch_work_nvlt_73","text":"《戰國策》曰：昭陽為楚伐魏，覆軍殺將，得八城，移師而攻齊，陳軫為齊王使，見昭陽，再拜謝，贺戰勝，起而曰：臣竊譬，楚有祠者，賜其舍人酒一卮，舍人相謂曰：數人飲之不足，一人飲之有餘，請畫地為蛇，蛇先成者飲酒，一人蛇先成，引酒且飲之，乃左手持卮，右手畫蛇，曰：吾能為之足，足未成，一人蛇成，奪其卮，曰：蛇固無足，子安能為之足，遂飲酒，［具遊說篇。］","sortOrder":85},
  {"id":"s_work_nvlt_73_86","chapterId":"ch_work_nvlt_73","text":"《鹽鐵論》曰：川源不能實漏卮。","sortOrder":86},
  {"id":"s_work_nvlt_73_87","chapterId":"ch_work_nvlt_73","text":"《漢書》曰：高祖奉玉卮，為太上皇寿。","sortOrder":87},
  {"id":"s_work_nvlt_73_88","chapterId":"ch_work_nvlt_73","text":"又曰：初何武為郡吏時，事太守何寿，寿知武有宰相器，故厚之，後寿為大司農，其兄子為庐江長史，時武為楊州刺史，奏事在邸，春寿兄子適長安，寿為具，召武弟顯及故人，酒酣，見其兄子曰：此子楊州長史，材能駑下，未曾省見，顯等甚慚，退以謂武，武曰：刺史古之方伯，上所以委任，一州表率也，職在進善退惡，吏治行有茂異，民有隱逸，乃當召見，不可以所私問，顯強之，不得已召見，賜卮酒。","sortOrder":88},
  {"id":"s_work_nvlt_73_89","chapterId":"ch_work_nvlt_73","text":"【賦】晉傅鹹汙卮賦曰：人有遺餘琉璃卮者，小兒竊弄，墮之不絜，意既惜之。又感物之汙辱，乃丧其所以為寶，况君子行身，而可以有玷乎，有金商之玮寶，禀乾刚之淳精，叹春暉之定色，越冬冰之至清，爰甄陶以成器，逞異域之殊形，猥陷身於丑秽，豈厥美之不惜，與觴杓之長辭，曾瓦匜之不若。","sortOrder":89},
  {"id":"s_work_nvlt_73_90","chapterId":"ch_work_nvlt_73","text":"【頌】後漢崔骃漢明帝頌曰：帝乃負扆，執冒覆珪，運斗杓以酬酢，酌酒旗之玉卮。","sortOrder":90},
  {"id":"s_work_nvlt_73_92","chapterId":"ch_work_nvlt_73","text":"《山海經》曰：犬戎國有一女子，方跪進玉杯食。","sortOrder":92},
  {"id":"s_work_nvlt_73_93","chapterId":"ch_work_nvlt_73","text":"《禮記》曰：父母没而杯圈不能飲焉，口泽之氣存焉爾，［孝子見親之器物哀，則不忍用也，圈，屈木所為也，卮，匜之屬也。］","sortOrder":93},
  {"id":"s_work_nvlt_73_94","chapterId":"ch_work_nvlt_73","text":"《管子》曰：桓公管仲鮑叔牙甯戚四人飲，公曰：盍不為寡人寿，叔牙奉杯而起。","sortOrder":94},
  {"id":"s_work_nvlt_73_95","chapterId":"ch_work_nvlt_73","text":"《文子》曰：清之為明，杯水見眸子，濁之言闇，河水不見太山。","sortOrder":95},
  {"id":"s_work_nvlt_73_96","chapterId":"ch_work_nvlt_73","text":"《韓子》曰：紂為象著而箕子怖，以為象著必不加於土［原訛上，據冯校本改。］形，［《太平御覽》七百五十九作钅刑。］必將犀玉之杯，象著玉杯，必不羹菽藿，則必荐豹胎。","sortOrder":96},
  {"id":"s_work_nvlt_73_97","chapterId":"ch_work_nvlt_73","text":"又曰：樂羊為魏文侯攻中山，其子在中山，中山之君，烹其子而遺之，樂羊坐於幕下而饗之，盡一杯。","sortOrder":97},
  {"id":"s_work_nvlt_73_98","chapterId":"ch_work_nvlt_73","text":"《淮南子》曰：夫江河之腐胔，不可勝數也，然祭者用，大也，一杯酒，甘蠋潰其中，匹夫不嘗，小也。","sortOrder":98},
  {"id":"s_work_nvlt_73_99","chapterId":"ch_work_nvlt_73","text":"《十洲記》曰：周穆王時，西域獻夜光常滿杯，杯容三升，是白玉之精，光明照彻，夜以杯於庭中以向天，比旦而水汁滿中，汁甘而香美，斯實靈器。","sortOrder":99},
  {"id":"s_work_nvlt_73_100","chapterId":"ch_work_nvlt_73","text":"《漢書》曰：有盜高廟座前玉環，得盜，文帝怒，下廷尉治，按盜宗廟服御物者為奏，當弃市，上大怒曰：吾屬廷尉者，欲致族之，而君以法奏之，非所以奉宗廟意也，釋之免冠頓首謝曰：法如是足矣，假令愚民取長陵一杯土，［不欲指言，故以取土喻之。］陛下何以加其法乎，文帝與太後言之，乃許之。","sortOrder":100},
  {"id":"s_work_nvlt_73_101","chapterId":"ch_work_nvlt_73","text":"又曰：元帝徵貢禹為諫議大夫，禹奏，臣當從之東宮，見賜杯案，盡金銀飾，非當所以食臣下也。","sortOrder":101},
  {"id":"s_work_nvlt_73_102","chapterId":"ch_work_nvlt_73","text":"又曰：王嘉為丞相，數上事，言不宜封董賢，上怒，有詔收［漢書八十六王嘉傳作假。］謁者即，［漢書作節。］召丞相詣廷尉詔獄，掾吏涕泣，共和藥進嘉曰：將相不對強吏陳冤，君侯宜引决，嘉引藥杯以击地，謂官屬曰：丞相幸得備位三公，奉職負國，伏刑都市，以示萬眾，豈兒女子耶，何謂咀藥而死。","sortOrder":102},
  {"id":"s_work_nvlt_73_103","chapterId":"ch_work_nvlt_73","text":"又曰：朱博為御史大夫，為人廉俭，食不重味，案上不過三杯，夜寢早起，妻子希見其面。","sortOrder":103},
  {"id":"s_work_nvlt_73_104","chapterId":"ch_work_nvlt_73","text":"謝承《後漢書》曰：豫章宋叔平，為定陵令，素杯，食麥飯。","sortOrder":104},
  {"id":"s_work_nvlt_73_105","chapterId":"ch_work_nvlt_73","text":"《論衡》曰：河東須［《太平御覽》七百五十九作項。］曼都好道，去家三年而反，曰：去時有數仙人將上天，離月數里而止，月之旁甚寒凄怆，飢欲食，辄飲我流霞一杯，每飲數月不飢。","sortOrder":105},
  {"id":"s_work_nvlt_73_106","chapterId":"ch_work_nvlt_73","text":"《王逸子》曰：顏淵之箪瓢，則勝慶封玉杯，何者，德行高遠，能絕殊也。","sortOrder":106},
  {"id":"s_work_nvlt_73_107","chapterId":"ch_work_nvlt_73","text":"陶侃《故事》曰：侃上成帝螺杯一枚。","sortOrder":107},
  {"id":"s_work_nvlt_73_108","chapterId":"ch_work_nvlt_73","text":"《南州異物志》曰：鸚鵡螺，状似霞，杯形如鳥，頭向其腹，视似鸚鵡，故以為名。","sortOrder":108},
  {"id":"s_work_nvlt_73_109","chapterId":"ch_work_nvlt_73","text":"《南越志》曰：南海以虾頭為杯，須長數尺，金銀鏤，晉康［《太平御覽》七百五十九作廣。］州刺史，常以杯獻，簡文用以盛藥，未及飲，無故酒躍於外，時庐江太守曲安遠，頗解術數，即令筮之，安遠曰：即三旬，後庭將有喜慶者。","sortOrder":109},
  {"id":"s_work_nvlt_73_110","chapterId":"ch_work_nvlt_73","text":"【銘】後漢冯敬通杯銘曰：樂則思舊，燕則思懽，民之失德，乾餱以愆。","sortOrder":110},
  {"id":"s_work_nvlt_73_111","chapterId":"ch_work_nvlt_73","text":"後漢李尤杯銘曰：小之為杯，大之為聞，杯聞之用，無施不可，以飲以享，慎其得正，用公之美，驕吝為病。","sortOrder":111},
  {"id":"s_work_nvlt_73_112","chapterId":"ch_work_nvlt_73","text":"梁陆倕蠡杯銘曰：用邁羽杯，珍愈渠碗，實同蠡测，形均朴滿，伊我疲病，獨居無伴，所不此挹，誰誚誰缓。","sortOrder":112},
  {"id":"s_work_nvlt_73_113","chapterId":"ch_work_nvlt_73","text":"《方言》曰：楚魏宋之間，碗謂之盂。","sortOrder":113},
  {"id":"s_work_nvlt_73_114","chapterId":"ch_work_nvlt_73","text":"《說文》曰：碗，小盂也。","sortOrder":114},
  {"id":"s_work_nvlt_73_115","chapterId":"ch_work_nvlt_73","text":"《吳志》曰：曹公出濡須，甘寧為前部督，受敕斫敵前營，孫權特賜米酒眾肴，寧乃以銀碗酌酒，自飲兩碗，乃酌與其都督，督伏，不肯時持，寧引自削置膝上，呵之曰：卿見知於至尊，孰與甘寧，甘寧尚不惜死，卿何以獨惜死乎，都督却起拜，持酒通次酌，共各一銀碗，至更時，衔枚出斫敵，敵驚動，遂退，寧益貴重。","sortOrder":115},
  {"id":"s_work_nvlt_73_116","chapterId":"ch_work_nvlt_73","text":"鹹康起居註曰：詔使遼東使叚遼等琉璃碗。","sortOrder":116},
  {"id":"s_work_nvlt_73_117","chapterId":"ch_work_nvlt_73","text":"【賦】魏陳王曹植車渠碗賦曰：惟斯碗之所生，於涼風之峻湄，采金光以定色，擬朝陽而發煇，丰玄素之暐晔，帶朱榮之葳蕤，缊絲纶以肆采，藻繁布以相追，翩飄飖而浮景，若驚鵠之双飛，隱神璞於西野，弥百葉而莫希，於時乃有明篤神後，廣彼仁聲，夷慕義而重使，獻茲寶於斯庭，命公输使製匠，窮而麗之殊形，華色燦烂，文若點成，鬱蓊雲蒸，蜿蜒龍征，光如激電，影若浮星，何神怪之巨伟，信一覽而九敬，雖離朱之聰目，由炫燿而失精，何明麗之可悅，超群寶而特章，俟君子之閒宴，酌甘醴於斯觴，既娱情而可貴，故求御而不忘。","sortOrder":117},
  {"id":"s_work_nvlt_73_118","chapterId":"ch_work_nvlt_73","text":"魏應玚車渠碗賦曰：惟茲碗之珍玮，誕靈嶽而奇生，扇不周之芳烈，浸琼露以润形，荫碧條以納曜，吸朝霞而發榮，紛玄黃以肜裔，晔豹变而龍華，象蜿虹之辅體，中含曜乎雲波，若其眾色鱗聚，卓度诡常，絪缊雜错，乍圓乍方，蔚術繁興，散列成章，楊丹流縹，碧玉飛黃，華氣承朗，內外齊光。","sortOrder":118},
  {"id":"s_work_nvlt_73_119","chapterId":"ch_work_nvlt_73","text":"魏徐幹車渠碗賦曰：圜德應規，巽從易安，大小得宜，客如可觀，盛彼清醴，承以琱盤，因歡接口，媚於君顏。","sortOrder":119},
  {"id":"s_work_nvlt_73_120","chapterId":"ch_work_nvlt_73","text":"晉潘尼琉璃碗賦曰：覽方貢之彼珍，玮茲碗之獨奇，濟流沙之絕险，越葱嶺之峻危，其由來也阻遠，其所讬也幽深，據重峦之亿仞，臨洪溪之萬尋，接玉树與琼瑤，鄰沙棠與碧林，瞻阆風之崔嵬，顧玄圃之萧參，光映日曜，圓成月盈，纖瑕罔麗，飛尘靡停，灼烁旁燭，表里相形，舉茲碗以酬賓，榮密坐之曲宴，流景蜅晃以內澈，清醴瑤琰而外見。","sortOrder":120},
  {"id":"s_work_nvlt_73_121","chapterId":"ch_work_nvlt_73","text":"隋江總馬腦碗賦曰：翠羽流霞之杯，谅無聞於玮麗，豈匹此之奇朅，爰睹殊特，臻自西國，状驚鶴之點潰，似遊龍之割刻，士衡譬之雲采，中郎羞其馬勒，於時北園清夏，東閣浮涼，山交枝而影雜，水沉葉而流香，蝉無風而吲短，鷺出迥而飛長，副君海渟嶽峙，紙落金锵，獲阿［疑當作河。］宗之美寶，命河朔之名觴，寶出崑崙之仙阜，觴即玄洲之玉酒，酒既醉而還年，碗稍酌而延寿，仰天縱之體物，銘欹器兮何有。","sortOrder":121},
  {"id":"s_work_nvlt_73_122","chapterId":"ch_work_nvlt_73","text":"【書】秦嘉妻與嘉書曰：分奉金错碗一枚，可以盛書水，琉璃碗一枚，可以服藥酒。","sortOrder":122},
  {"id":"s_work_nvlt_73_123","chapterId":"ch_work_nvlt_73","text":"【表】梁諸葛恢表曰：詔雲，行當別離，以為怅罔，分致氍〈叟毛〉一，劍一，琉璃碗一，貴達心領錄之，天恩望極天地，施鈞不異遠近。","sortOrder":123},
  {"id":"s_work_nvlt_73_124","chapterId":"ch_work_nvlt_73","text":"《藝文類聚》　唐·欧陽詢","sortOrder":124},
  {"id":"s_work_nvlt_74_1","chapterId":"ch_work_nvlt_74","text":"卷七十四巧藝部","sortOrder":1},
  {"id":"s_work_nvlt_74_2","chapterId":"ch_work_nvlt_74","text":"○射書畫围棋彈棋博樗蒲投壶塞藏鉤四維象戲","sortOrder":2},
  {"id":"s_work_nvlt_74_4","chapterId":"ch_work_nvlt_74","text":"《世本》曰：逢蒙作射。","sortOrder":4},
  {"id":"s_work_nvlt_74_5","chapterId":"ch_work_nvlt_74","text":"《山海經》曰：軒轅國，在窮山际，其不寿者八百歲，人面蛇身，尾交首，不敢西射，畏軒轅之丘。","sortOrder":5},
  {"id":"s_work_nvlt_74_6","chapterId":"ch_work_nvlt_74","text":"《禮記》曰：士使之射，不能則辭以疾，懸弧之義。","sortOrder":6},
  {"id":"s_work_nvlt_74_7","chapterId":"ch_work_nvlt_74","text":"又曰：射有似乎君子，失諸正鵠，反求諸其身。","sortOrder":7},
  {"id":"s_work_nvlt_74_8","chapterId":"ch_work_nvlt_74","text":"又曰：孔子射於矍相之圃，蓋觀者如堵。","sortOrder":8},
  {"id":"s_work_nvlt_74_9","chapterId":"ch_work_nvlt_74","text":"《左傳》曰：晉將戰，潘尫之党與養由基蹲甲而射之，彻七札焉。","sortOrder":9},
  {"id":"s_work_nvlt_74_10","chapterId":"ch_work_nvlt_74","text":"《列子》曰：甘蠅古之善射者，彀弓而獸伏鳥下。","sortOrder":10},
  {"id":"s_work_nvlt_74_11","chapterId":"ch_work_nvlt_74","text":"《尸子》曰：荆莊王命養由基射蜻蛉，王曰：吾欲得之，養由基援弓射之，拂左翼，王大喜。","sortOrder":11},
  {"id":"s_work_nvlt_74_12","chapterId":"ch_work_nvlt_74","text":"又曰：鸿鵠在上，鞟弩以待，若發善否，問二五弗知，非二五難計也，欲鸿之心亂也。","sortOrder":12},
  {"id":"s_work_nvlt_74_13","chapterId":"ch_work_nvlt_74","text":"《莊子》曰：以十鈞射者，見天而不見雲，以七鈞射者，見鵠而不見鸧，以五鈞射者，見鸧而不見雀。","sortOrder":13},
  {"id":"s_work_nvlt_74_14","chapterId":"ch_work_nvlt_74","text":"《老子》曰：天之道，其猶張弓乎，高者抑之，下者舉之，有餘者損之，不足者與之。","sortOrder":14},
  {"id":"s_work_nvlt_74_15","chapterId":"ch_work_nvlt_74","text":"《韓詩外傳》曰：楚熊渠子夜行，見寢石，以為伏虎，弯弓射之，没金飲羽，下视知其石也，因复射石，矢摧無跡，渠子見其誠心，金石為之开，而况於人乎。","sortOrder":15},
  {"id":"s_work_nvlt_74_16","chapterId":"ch_work_nvlt_74","text":"《史記》曰：李廣為右北平太守，出獵，見草中石，以為虎而射之，中，没鏃，视之石，因复射之，終不复入，廣所居郡，聞有虎，自射之，及居右北平，射虎，虎騰傷廣，廣亦竟射殺之，廣為人長猿臂，其善射亦天性也，雖子他人學者，莫能及。","sortOrder":16},
  {"id":"s_work_nvlt_74_17","chapterId":"ch_work_nvlt_74","text":"又曰：匈奴大入上郡，天子使中貴人從，勒習兵击匈奴，中貴人將騎從，見匈奴三人與戰，三人還，射傷中貴人，殺其騎將盡，中貴人走廣，廣曰：是必射雕者也。","sortOrder":17},
  {"id":"s_work_nvlt_74_18","chapterId":"ch_work_nvlt_74","text":"《淮南子》曰：越人學遠參天，而發鏑在五步內，今學者欲學古而不知变，是越人射也。","sortOrder":18},
  {"id":"s_work_nvlt_74_19","chapterId":"ch_work_nvlt_74","text":"《漢書》曰：匈奴畏郅都之威，刻木象都之状，交弓射之，莫之能一中。","sortOrder":19},
  {"id":"s_work_nvlt_74_20","chapterId":"ch_work_nvlt_74","text":"魏書曰：文帝共上常獵，為虎所逐，顧射，應聲而倒，太祖壮其挚勇，使將武騎。","sortOrder":20},
  {"id":"s_work_nvlt_74_21","chapterId":"ch_work_nvlt_74","text":"《吳志》曰：太史慈，猿臂善射，絃不虛發，嘗從孫策讨麻保賊，賊緣上樓上行骂，以手持樓棼，慈引弓射之，矢貫手著棼，围外萬人，莫不稱善，其妙如此。","sortOrder":21},
  {"id":"s_work_nvlt_74_22","chapterId":"ch_work_nvlt_74","text":"《典論》曰：文帝自序曰：少好弓馬，逐禽辄十里，射出百步，後濊犭百貢良弓，代獻名馬，時歲暮春，和風扇物，弓燥手柔，草淺獸肥，於鄴西獵，終日，獲獐鹿九，雉兔二十。","sortOrder":22},
  {"id":"s_work_nvlt_74_23","chapterId":"ch_work_nvlt_74","text":"【詩】梁元帝落日射羆詩曰：促宴引枚邹，中園觀獸侯，日度堋陰廣，風橫旗影浮，移竿標入箭，叠鼓送爭筹，附枝時可息，言從清夜遊。","sortOrder":23},
  {"id":"s_work_nvlt_74_24","chapterId":"ch_work_nvlt_74","text":"周庾信北園射堂詩曰：軒堂聊可習，仙的不難登，轉箭初辟竿，橫弓先望堋，驚心一雁落，連臂兩猿騰，直知王濟巧，誰見魏舒能，空心不死树，無葉未枯藤，擇賢方至此，傳卮欣得朋。","sortOrder":24},
  {"id":"s_work_nvlt_74_26","chapterId":"ch_work_nvlt_74","text":"《淮南子》曰：昔仓頡作書，而天雨粟，鬼夜哭，［事具百穀部。］","sortOrder":26},
  {"id":"s_work_nvlt_74_27","chapterId":"ch_work_nvlt_74","text":"家語曰：宓子賤仕魯，為单父宰，恐君聽用讒人，使己不得行其政，故請君近吏二人，與俱至官，令二吏書，辄掣其肘，書不善，則從而怒之，二吏患焉，辭歸魯，宓子曰：書甚不善，勉而歸矣，二吏歸報於君曰：宓子使臣書，而掣搖臣肘，書惡而又怒臣，邑吏皆笑，所以去之而來也，君以問孔子，孔子曰：宓子齊君子也，其才任霸王之佐，屈節治单父，將以自试，意者其以此諫乎，公悟，太息叹曰：寡人亂宓子之政，而责其善者數矣。","sortOrder":27},
  {"id":"s_work_nvlt_74_28","chapterId":"ch_work_nvlt_74","text":"《漢書》曰：元帝多才藝，善史書，［應劭曰：周宣王太史史藉(漢書元帝紀註作籀。)所作大篆也。］鼓琴瑟，吹洞箫。","sortOrder":28},
  {"id":"s_work_nvlt_74_29","chapterId":"ch_work_nvlt_74","text":"又曰：宣帝時，中郎將張彭祖，少與帝微時同席砚書，及帝即尊位，彭祖以舊恩，封陽都侯，［事具文部砚篇。］","sortOrder":29},
  {"id":"s_work_nvlt_74_30","chapterId":"ch_work_nvlt_74","text":"又曰：陳遵大率常醉，然事亦不废，長八尺餘，長頭大鼻，容貌甚伟，略涉傳記，贍於文辭，性善書，與人尺牍，主皆藏去，以為之榮。","sortOrder":30},
  {"id":"s_work_nvlt_74_31","chapterId":"ch_work_nvlt_74","text":"《後漢書》曰：張奐長子芝，字伯玉［玉字衍。］英，最知名，芝及弟昶，善草書，至今稱之。","sortOrder":31},
  {"id":"s_work_nvlt_74_32","chapterId":"ch_work_nvlt_74","text":"又曰：顯宗問班固，卿弟子安在，固對與官寫書受直，以養老母，帝乃除超為蘭台令史。","sortOrder":32},
  {"id":"s_work_nvlt_74_33","chapterId":"ch_work_nvlt_74","text":"《三辅决錄》曰：趙袭敦煌太守，先是杜伯度崔子玉，以工草書稱於前世，袭與羅暉，亦以能草，頗自矜夸，故張伯英書與袭同郡太仆朱賜書曰：上比崔杜不足，下方羅趙有餘。","sortOrder":33},
  {"id":"s_work_nvlt_74_34","chapterId":"ch_work_nvlt_74","text":"王隱《晉書》曰：索靖，敦煌人，靖草法，武帝愛之，時尚書令衛瓘，世號得伯英之筋，一台二妙，天下為希。","sortOrder":34},
  {"id":"s_work_nvlt_74_35","chapterId":"ch_work_nvlt_74","text":"【賦】晉陽［按當作楊。］泉草書賦曰：惟六書之為體，美草法之最奇，杜垂名於古昔，皇著法乎今斯，字要妙而有好，势奇綺而分馳，解隸體之細微，散委曲而得宜，乍楊柳而奋發，似龍鳳之騰儀，應神靈之变化，象日月之盈虧，書蹤竦而值立，衡平體而均施，或斂束而相抱，或婆娑而四垂，或攒翦而齊整，或上下而參差，或陰岑而高舉，或落擇而自披，其布好施媚，如明珠之陆離，發翰摅藻，如春華之楊枝，提墨縱體，如美女之長眉，其滑泽肴易，如長溜之分歧，其骨梗強壮，如柱蛇楚之不基，斷除弓盡，如工匠之盡規，其芒角吟牙，如嚴霜之傅枝，眾巧百態，無盡不奇，宛轉翻覆，如絲相持。","sortOrder":35},
  {"id":"s_work_nvlt_74_36","chapterId":"ch_work_nvlt_74","text":"齊王僧虔書賦曰：情凭虛而测有，思沿想而圖空，心經於則，目像其容，手以心麾，毫以手從，風搖挺氣，妍孊深功，爾其隸明敏婉，蠖絢蒨趍，將摛文匪縟，讬韻笙簧，儀春等愛，麗景依光，沉若雲鬱，輕若蝉扬，稠必昂萃，約實箕張，垂端整曲，栽邪製方，或具美於片巧，或双兢於兩傷，形綿靡而多態，氣陵厲其如芒，故其委貌也必妍，獻體也貴壮，跡乘規而騁势，志循檢而懷放。","sortOrder":36},
  {"id":"s_work_nvlt_74_37","chapterId":"ch_work_nvlt_74","text":"【势】後漢蔡邕篆書势曰：體有六篆，妙巧入神，或象龟文，或比龍鱗，紆體放尾，長翅短身，扬波震激，鷹跱鳥震，延頸胁翼，势似凌雲。","sortOrder":37},
  {"id":"s_work_nvlt_74_38","chapterId":"ch_work_nvlt_74","text":"晉衛恒四體書势曰：弘農張伯英，轉精其巧，家之衣帛，必先書後染，臨池學書，池水盡黑，下筆必為楷則，號怱怱不暇草，寸紙不遺，仲將謂之草聖。","sortOrder":38},
  {"id":"s_work_nvlt_74_39","chapterId":"ch_work_nvlt_74","text":"晉索靖書势曰：蓋草聖之為状也，婉若銀鉤，漂若驚鸞，舒翼未發，若舉复安，虫蛇蚴虬，或往或還，頹阿那以羸形，欻奋亹而桓桓，及其逸遊眄乡，乍正乍邪，騏骥暴怒逼其辔，海水窊隆扬其波，玄熊對路於山嶽，飛燕相追而差池，舉而察之。又似和風吹林，偃草扇树，枝條從風，轉相比附，窈娆廉苫，隨體散布，紛扰扰以綺靡，中持疑而猶豫，玄螭狡獸嬉其間，騰猿飛鼬相奔趣，陵魚奋尾，駭龍反據，投空自竄，張設牙距。","sortOrder":39},
  {"id":"s_work_nvlt_74_40","chapterId":"ch_work_nvlt_74","text":"晉劉邵飛白書势曰：鳥魚龍蛇，龟獸仙人，蛟腳偃波，楷隸八分，世施常妙，索草鍾真，爰有飛白之麗，貌艳势珍，若乃敷坼毫芒，纖手和會，素幹冰解，蘭墨電掣，直准箭馳，屈擬蠖势，繁節參谭，綺靡循殺，有若煙雲拂蔚，交紛刻繼，韓盧接飛，宋鵲遊逝。","sortOrder":40},
  {"id":"s_work_nvlt_74_41","chapterId":"ch_work_nvlt_74","text":"【啟】梁庾肩吾謝東宮古跡啟曰：竊以仙巖遺轉，入握成尘，孔壁藏文，隨开已蠹，石書有暗，厨盡猶飛，豈有跡經四代，年逾十紀，芝英雲氣之巧，未損松鉛，鵲反鸞驚之势，不侵蒲竹，必使酒肆來人，池流色变，將損北海之續，還代西河之簡。","sortOrder":41},
  {"id":"s_work_nvlt_74_42","chapterId":"ch_work_nvlt_74","text":"梁元帝上東宮古跡啟曰：師宜八分之巧，元帝三體之妙，史籀李斯之篆，梁鸿曹喜之書，莫不總華桂宮，盈滿甲馆，竊以鸞驚之势，既聞之於索靖，鷹跱之巧。又顯之於蔡邕，是以遊霧重雲，傳敬禮之法，鳥鴶魚颃，表楊泉之賦，頗好六文，多慚三禮，尚方大篆，既其牢落，柱下方書，何曾仿佛，空慕河間之聚書，竟徵東平之獻表，齊攸尺牍，顧已缺然，北海楷隸，終成難擬。","sortOrder":42},
  {"id":"s_work_nvlt_74_43","chapterId":"ch_work_nvlt_74","text":"【書】梁簡文帝答湘東王上王羲之書曰：试筆成文，臨池染墨，疏密俱巧，真草皆得，似望城扉，如瞻星石，不營雲飛之散，何待曲辱之丹，方當奉彼廷中，置之帳里，乍楷銅鉤，時懸欹案，戢意之深，良不能已。","sortOrder":43},
  {"id":"s_work_nvlt_74_45","chapterId":"ch_work_nvlt_74","text":"《韓子》曰：客為齊王畫者，問之，畫孰最難，對曰：狗馬最難，孰最易，曰：鬼魅最易，狗馬人所知也，旦暮於前，不可類之，故難，鬼魅無形，無形者不可睹，故易。","sortOrder":45},
  {"id":"s_work_nvlt_74_46","chapterId":"ch_work_nvlt_74","text":"《漢書》曰：上至平城，為匈奴所围，七日乏食，陳平使畫工圖美女，間遣人遺閼氏，雲漢有美女，姿质若是，將欲獻单於，閼氏以為然，從容言於单於，乃始得出。","sortOrder":46},
  {"id":"s_work_nvlt_74_47","chapterId":"ch_work_nvlt_74","text":"又曰：甘露三年，单於始入朝，上忽思股肱之美，圖畫其人於麒麟閣。","sortOrder":47},
  {"id":"s_work_nvlt_74_48","chapterId":"ch_work_nvlt_74","text":"又曰：金日磾母，教誨二子，甚有法度，上聞而嘉之，病死，詔圖畫於甘泉宮，曰休屠王閼氏，日磾見畫嘗拜，向之涕泣。","sortOrder":48},
  {"id":"s_work_nvlt_74_49","chapterId":"ch_work_nvlt_74","text":"又曰：元帝宮人既多，乃令畫工圖之，欲有呼者，辄披圖召焉，其中常者，悉皆行货賂，王昭君姿容甚麗，志不可苟求，工遂毀其状，後匈奴來和，求美女於帝，帝以昭君充行，既召見而惜之，名字已去，不欲中改，於是遂行。","sortOrder":49},
  {"id":"s_work_nvlt_74_50","chapterId":"ch_work_nvlt_74","text":"范晔《後漢書》曰：永平初，馬援女立為皇後，顯宗圖畫建武中名臣列將於雲台，以椒房故，獨不及援，東平王蒼觀圖，言於帝曰：何故不圖伏波像，帝笑而不言。","sortOrder":50},
  {"id":"s_work_nvlt_74_51","chapterId":"ch_work_nvlt_74","text":"《風俗通》曰：門戶鋪首，謹案百家書雲，公输班之水，見蠡，曰：見汝形，蠡適出頭，般以足畫圖之，蠡引閉其戶，終不可得开，般遂施之門戶，雲人閉藏如是，固周密矣。","sortOrder":51},
  {"id":"s_work_nvlt_74_52","chapterId":"ch_work_nvlt_74","text":"陳思王畫贊序曰：蓋畫者，鳥書之流，昔明德馬後，美於色，厚於德，帝用嘉之，嘗從觀畫，過虞舜廟，見娥皇女英，帝指之戲後曰：恨不得如此為妃。又前見陶唐之像，後指尧曰：嗟乎，群臣百僚，恨不得為君如是，帝顧而笑，故夫畫所見多矣。","sortOrder":52},
  {"id":"s_work_nvlt_74_53","chapterId":"ch_work_nvlt_74","text":"《世說》曰：晉陵顧恺，善畫絕世，好寫起人形，欲圖殷荆州堪，曰：我形惡，卿不煩爾，恺曰：明府正當為眼耳，若明點童子，飛白拂上，使如輕雲之蔽月。","sortOrder":53},
  {"id":"s_work_nvlt_74_54","chapterId":"ch_work_nvlt_74","text":"又曰：顧長康畫人，或數年不點目睛，人問何事如此，曰：四體妍蚩，本無關於妙處，傳神寫照，正在阿堵中。","sortOrder":54},
  {"id":"s_work_nvlt_74_55","chapterId":"ch_work_nvlt_74","text":"又曰：顧恺畫裴叔則，頰上益三毛，看畫者定覺，益毛有神明，殊勝向未安時，顧［世說巧藝篇顧下有長康畫三字，此蒙上條，當脱畫字。］謝幼舆在巖里，人問所以，顧［世說顧下有曰謝二字。］雲，一丘一壑，自謂過人，此子自宜置於丘壑之中。","sortOrder":55},
  {"id":"s_work_nvlt_74_56","chapterId":"ch_work_nvlt_74","text":"又曰：顧長康道畫，雲手揮五絃易，目送歸鸿難。","sortOrder":56},
  {"id":"s_work_nvlt_74_57","chapterId":"ch_work_nvlt_74","text":"【賦】晉傅鹹畫像賦曰：先畫卞和之像者，雖具其事在素，定見其泣血殘刖之刑，情以凄然，辭曰：惟年命之遒短，速流光之有經，疾没世而不稱，貴立身而扬名，既銘勒於鍾鼎。又圖像於丹青，覽光烈之攸畫，睹卞子之容形，泣泉流以雨下，洒血面而瀸纓，痛兩趾之双刖，心惻凄以傷情，雖發膚之不毀，覺害仁以偷生，向厥趾之不刖，孰夜光之見明，人之不同，爰自在昔，臧知柳而不進，和殘軀以證璧。","sortOrder":57},
  {"id":"s_work_nvlt_74_58","chapterId":"ch_work_nvlt_74","text":"【贊】梁元帝職貢圖贊曰：北通玄兔，南漸朱鳶，交河悠遠，合浦回邅，茲海無际，陰山接天，遐哉鳥穴，永矣雞田。","sortOrder":58},
  {"id":"s_work_nvlt_74_59","chapterId":"ch_work_nvlt_74","text":"【啟】梁元帝謝上畫蒙敕褒賞啟曰：臣簿領餘暇，竊愛丹青，雲台之像，終微仿佛，宣室之圖，更難議擬，成蠅罕術，畫馬疏工，人非世將，恩深晉帝之賞，跡愧景山，寵逾魏皇之詔。","sortOrder":59},
  {"id":"s_work_nvlt_74_60","chapterId":"ch_work_nvlt_74","text":"又謝東宮赉陆探微畫啟曰：工逾畫馬，巧邁圖龍，试映玉池，即看魚動，還傍金屏，复疑蠅集，史遷暫睹，懸識留侯之貌，漢帝一瞻，便見王嫱之像。","sortOrder":60},
  {"id":"s_work_nvlt_74_61","chapterId":"ch_work_nvlt_74","text":"◇围棋","sortOrder":61},
  {"id":"s_work_nvlt_74_62","chapterId":"ch_work_nvlt_74","text":"《左傳》曰：太叔文子謂甯喜曰：视君不如弈棋，其何以免乎，弈者舉棋不定，不勝其耦，而况置君而弗定乎。","sortOrder":62},
  {"id":"s_work_nvlt_74_63","chapterId":"ch_work_nvlt_74","text":"《博物志》曰：尧造围棋，丹朱善棋。","sortOrder":63},
  {"id":"s_work_nvlt_74_64","chapterId":"ch_work_nvlt_74","text":"《說文》曰：弈，围棋也。","sortOrder":64},
  {"id":"s_work_nvlt_74_65","chapterId":"ch_work_nvlt_74","text":"尹《文子》曰：以智力求者，喻如弈，弈進退取與，攻劫放舍，在我者也。","sortOrder":65},
  {"id":"s_work_nvlt_74_66","chapterId":"ch_work_nvlt_74","text":"《蜀志》曰：魏軍次於興平，假費禕節，率眾往御，光祿大夫來敏至禕許別，求围棋，於時羽檄交馳，嚴駕已訖，禕與敏留意對戲，色無厭倦，敏曰：聊觀试君耳，信可人，必能辨賊者，禕至，敵遂退。","sortOrder":66},
  {"id":"s_work_nvlt_74_67","chapterId":"ch_work_nvlt_74","text":"《魏志》曰：王粲觀人围棋，局坏，粲复為之，棋者不信，以袍蓋局，使更以他局為之，用相比校，不誤一道。","sortOrder":67},
  {"id":"s_work_nvlt_74_68","chapterId":"ch_work_nvlt_74","text":"《博物志》曰：桓谭蔡邕善音樂，冯翊山子道王九真郭酆等，善棋，太祖皆與爭能。","sortOrder":68},
  {"id":"s_work_nvlt_74_69","chapterId":"ch_work_nvlt_74","text":"《晉中興書》曰：陶侃為荆州，見佐史博弈戲具，投之於江，曰：围棋尧舜以教愚子，博殷紂所造，諸君併國器，何以此為。","sortOrder":69},
  {"id":"s_work_nvlt_74_70","chapterId":"ch_work_nvlt_74","text":"《語林》曰：王中郎以围棋是坐隱，支公以棋為手談。","sortOrder":70},
  {"id":"s_work_nvlt_74_71","chapterId":"ch_work_nvlt_74","text":"《俗說》曰：殷仲堪在都，嘗往看棋，諸從在瓦官寺前宅上，於時袁羌與人共在窗下围棋，仲堪在里，問袁易義，袁應答如流，围棋不輟，袁意傲然，殊有餘地，殷撰辭致難，每有往复。","sortOrder":71},
  {"id":"s_work_nvlt_74_72","chapterId":"ch_work_nvlt_74","text":"【賦】後漢馬融围棋賦曰：略觀围棋，法於用兵，三尺之局，為戰斗場，陳聚士卒，兩敵相當，怯者無功，貪者先亡，先據四道，守角依傍，緣邊遮列，往往相望，離離馬目，連連雁行，踔度間置，徘徊中央，收取死卒，無使相迎，當食不食，反受其殃，離亂交错，更相度越，守規不固，為所唐突，深入貪地，殺亡士卒，狂攘相救，先後併没，計功相除，以時早訖，事留变生，拾棋欲疾，營或窘乏，無令诈出，深念遠慮，勝乃可必。","sortOrder":72},
  {"id":"s_work_nvlt_74_73","chapterId":"ch_work_nvlt_74","text":"晉曹摅围棋賦曰：昔班固造弈旨之論，馬融有围棋之賦，擬軍政以為本，引兵家以為喻，蓋宣尼之所以稱美，而君子之所以遊慮也，既好其事，而壮其辭，聊因翰墨，述而賦焉，其辭曰：局則邓林之木，魯班所造，雉方砥平，素质玄道，犀角象牙，是错是砺，內含光润，形亦應製，於是二敵交行，星羅宿列，雲會中區，網布四裔，合围促陣，交相侵伐，用兵之象，六軍之际也，張甄設伏，挑敵誘寇，縱败先鋒，要勝後复，尋道為場，頻戰累斗，夫保角依邊，處山營也，隔道相望，夹水兵也，二斗共生，皆目併也，持棋合，［句有脱文。］連理形也，覽斯戲以廣思，儀群方之妙理，訝奇变之可嘉，思孫吳與白起，世既平而功絕，局告成而巧止，當無為之餘日，差見玩於君子。","sortOrder":73},
  {"id":"s_work_nvlt_74_74","chapterId":"ch_work_nvlt_74","text":"晉蔡洪围棋賦曰：命班爾之妙手，製朝陽之柔木，取坤象於四方，位將軍乎五嶽，然後畫路表界，立质朱文，曲直有正，方而不圓，筭涂授卒，三百惟群，任巧於無主，譬采菽乎中原，於是摅妙思，奋玄筹，玩服色，尚骍駒，旅進旅退，二騎迭驅，翻翻馬合，落落星敷，各嘯歌以發憤，運变化以相符，乍似戲鶴之幹霓。又類狡兔之繞丘，散象乘虛之飛電，聚類絕貫之積珠，然後枕以大羅，繕以城郭，缀以懸险，經以絕落，眇望翼舒，翱翔容弈，弯掌南指，情實西射，楊尘奄跡，雖動詳悉，或臨局寂然，惟棋是陳，靜昧無聲，潛來若神，抑舒之役，成子之賢也，或聲手俱發，喧哗譟扰，色類不定，次措無已，再衰三竭，銳氣已朽，登軾望軼，其亂可取也，爾乃心斗饹競，势使揮謙，携手詆欺，朱顏相嫌，然局不弘席，子不盈卷，秉二儀之極要，握眾巧之至權，若八卦之初兆，遂消息乎天文，屈則尺蠖，舒則龍翻，崔嵬雲起，巃鹢浪傳，崟岑山結，沓如霧分，靜若清夜之列宿，動若流彗之互奔，殿未結而筭了，隸首不得窥其門，局覆亂而不惑，研桑不足識其源，或設死而稱枉，皋陶不能治其怨，或巧逸以樂胥，後夔不足以之贊，我雲势貌多以，孰能究傳，遠求近取，予一以貫。","sortOrder":74},
  {"id":"s_work_nvlt_74_75","chapterId":"ch_work_nvlt_74","text":"梁武帝围棋賦曰：围奁象天，方局法地，抨則廣羊文犀，子則白瑤玄玉，方眼無斜，直道不曲，爾乃建將軍，布將士，列兩陣，驅双軌，徘徊鶴翔，差池燕起，用忿兵而不顧，亦凭河而必危，癡無成術而好斗，非智者之所為，運疑心而猶豫，志無成而必虧，今一棋之出手，思九事而為防，敵謀斷而計屈，欲侵地而無方，不失行而致寇，不助彼而為強，不讓他以增地，不失子而雲亡，落重围而計窮，欲佻巧而行促，剧疏勒之屯邅，甚白登之困辱，或龍化而超絕，或神变而獨悟，勿膠柱以調瑟，专守株而待兔，或有少棋，已有活形，失不為悴，得不為榮，若其苦戰，未必能平，用折雄威，致損令名，故城有所不攻，地有所不爭，東西馳走，左右周章，善有翻覆，多致败亡，雖畜銳以將取，必居謙以自牧，譬猛獸之將击，亦俯耳而固伏，若局势已勝，不宜過輕，禍起於所忽，功墜於垂成，至如玉壶銀台，車厢井欄，既見知於曩日，亦在今之可觀，或非劫非時，兩懸兩生，局有眾势，多不可名，或方四聚五，花六持七，雖涉戲之近事，亦臨局而應悉，或取結角，或營邊鄙，或先點而亡，或先撇而死，故君子以之遊神，先達以之安思，盡有戲之要道，窮情理之奧秘。","sortOrder":75},
  {"id":"s_work_nvlt_74_76","chapterId":"ch_work_nvlt_74","text":"梁宣帝围棋賦曰：引如征鸿赴沼，布若群鵲依枝，類林麓之隱隱，匹星漢之離離，蜂起百涂，從橫萬製，或無厭而反失，或先羸而後濟。","sortOrder":76},
  {"id":"s_work_nvlt_74_77","chapterId":"ch_work_nvlt_74","text":"【弈旨】後漢班固弈旨曰：北方之人，謂棋為弈，弘之說之舉大略，局必方正，象地則也，道必正直，神明德也，棋有白黑，陰陽分也，骈羅列布，效天文也，四象既陳，行之在人，蓋王政也，或虛設豫置，以自衛護，蓋象庖犧網罟之製，隄防周起，障塞漏决，有似夏後治水之势，一孔有闕，坏頹不振，有似瓠子汎濫之败，作伏設诈，突围橫行，田单之奇，要厄相劫，割地取賞，蘇張之姿，參分有勝而不誅，周文之德，逡巡儒行，保角依旁，却自補續，雖败不亡，缪公之智，中庸之方，上有天地之象，次有帝王之治，中有五霸之權，下有戰國之事，覽其得失，古今略備。","sortOrder":77},
  {"id":"s_work_nvlt_74_78","chapterId":"ch_work_nvlt_74","text":"【弈势】魏應玚弈势曰：蓋棋弈之製所尚矣，有像軍戎戰陣之紀，旌旗既列，權慮蜂起，骆驿雨集，魚鱗雁峙，奋維闡翼，固衛邊鄙，或飾遁伪旋，卓轹軿列，羸師延敵，一乘虛絕，歸不得合，兩見擒滅，淮陰之謨，拔旗之势也，或匡設無常，尋变應危，寇動北壘，備在南麾，中棋既捷，四表自虧，亚夫之智，耿弇之奇也，或假道四布，周爰繁昌，雲合星羅，侵逼郊場，師弱眾寡，臨據孤亡，披扫彊御，廣略土疆，崑陽之威，官渡之方也，挑誘既戰，見欺敵對，紛拏相救，不量進退，群聚俱陨，力行唐突，瞋目恚憤，覆局崩潰，項將之咎，楚懷之悖也，時或失谬，收奔攝北，還自保固，完聚補塞，見可而進，先負後剋，燕昭之賢，齊頃之德也，長驅馳逐，見利忘害，輕敵寡備，所丧弥大，臨疑猶豫，筭慮不詳，苟貪少獲，不知所亡，當斷不斷，還為所謀，項羽之失，吳王之尤也，持棋相守，莫敢先動，由楚漢之兵，相拒索巩也。","sortOrder":78},
  {"id":"s_work_nvlt_74_79","chapterId":"ch_work_nvlt_74","text":"【銘】後漢李尤围棋銘曰：詩人幽憶，感物則思，志之空閒，玩弄遊竟，局為憲矩，棋法陰陽，道為經緯，方错列張。","sortOrder":79},
  {"id":"s_work_nvlt_74_80","chapterId":"ch_work_nvlt_74","text":"【啟】梁任孝恭謝示围棋啟曰：隱雷自天，崑虫已聽，浮陰在漢，柱蛇楚先霑，笑古人不工，知前事之已拙，既妙藉手傳，乃事因辭見，微而能顯，婉以成章，孝恭人實下愚，才歸末品，效嚬丑友，學步蹇歸，文業未彰，武功已墜，內愧齊竽，外羞魯服，濫出簪纓，非增後車之數，谬頒計食，空貴長安之米。","sortOrder":80},
  {"id":"s_work_nvlt_74_81","chapterId":"ch_work_nvlt_74","text":"【序】梁沈約棋品序曰：弈之時義大矣哉，體希微之趣，舍奇正之情，靜則合道，動必適变，若夫入神造極之靈，經武緯文之德，故可與和樂等妙，上藝齊工，支公以為手談，王生謂之坐隱，是以漢魏名賢，高品間出，晉宋盛士，逸思爭流，雖复理生於數，研求之所不能涉，義出乎幾，爻彖未之或盡，聖上聽朝之餘，因日之暇，回景紆情，降臨小道，以為凝神之性難限，入玄之致不窮，今撰錄名氏，隨品詳書，俾粹理深情，永垂芳於來葉。","sortOrder":81},
  {"id":"s_work_nvlt_74_82","chapterId":"ch_work_nvlt_74","text":"◇彈棋","sortOrder":82},
  {"id":"s_work_nvlt_74_83","chapterId":"ch_work_nvlt_74","text":"魏文帝《典論》曰：餘於他戲弈之事，少所嘉，唯彈棋略盡其功，乃為之賦曰：昔［《太平御覽》七百五十五昔下有京字。］師先工，有馬合乡侯東方世安張公子，予嘗恨不得與彼數子者對。","sortOrder":83},
  {"id":"s_work_nvlt_74_84","chapterId":"ch_work_nvlt_74","text":"《世說》曰：彈棋始自魏，宮內裝奁［原訛器，據冯校本改。］戲也，文帝於此技亦特好，用手巾拂之，無不中，有客自雲能，帝使為之，客著葛巾拂棋，妙逾於帝。","sortOrder":84},
  {"id":"s_work_nvlt_74_85","chapterId":"ch_work_nvlt_74","text":"【詩】周王襃彈棋詩曰：投壶生電影，六博值仙人，何如鏡奁上自有拂輕巾，隔涧疑將別，隴頭如望秦，握筆徒思賦，辭短竟無陳。","sortOrder":85},
  {"id":"s_work_nvlt_74_86","chapterId":"ch_work_nvlt_74","text":"【賦】後漢蔡邕彈棋賦曰：榮華灼烁，萼不韡韡，於是列象棋，雕華麗，丰腹斂邊，中隱四企，輕利調博，易使騁馳，然後栰掣，兵棋夸驚，或風飄波動，若飛若浮，不遲不疾，如行如留，放一弊六，功無與儔。","sortOrder":86},
  {"id":"s_work_nvlt_74_87","chapterId":"ch_work_nvlt_74","text":"魏文帝彈棋賦曰：惟彈棋之嘉巧，邈超絕其無儔，苞上智之弘略，允貫微而洞幽，局則荆山妙璞，發藻扬暉，丰腹高隆，庳根四頹，平如砥砺，滑若柔荑，棋則玄木北幹，素树西枝，洪纖若一，脩短無差，象筹列植，一據双螭，滑石霧散，雲布四垂，然後直叩先縱，二八次舉，緣邊間造，長邪迭取，爾乃詳觀夫变化之理，屈伸之形，聯翩靃繹，展轉盤萦，或暇豫安存，或窮困侧傾，或接党連興，或孤據偏停，於時觀者，莫不虛心竦踴，鹹侧息而延行，或雷抃以大噱，或戰悸而不能語。","sortOrder":87},
  {"id":"s_work_nvlt_74_88","chapterId":"ch_work_nvlt_74","text":"魏丁廙彈棋賦曰：文石為局，金碧齊精，隆中夷外，緻理肌平，卑高得適，既安且貞，棋則象齒選乎南藩，禮身重，［句有脱文。］腹隱頭騫，驍悍說敏，不輕不軒，列數二六，取象官軍，微章采列，烂焉可觀，於是二物既設，主人延賓，粉石霧散，六師列陳，跡行王首，左右相親，成列告誓，三令五申，事中軍政，言含禮文，號令既通，兵棋啟路，運若回飆，疾似飛兔，前中却舞，贾其餘怒，風馳火燎，令牟取五，恍哉忽兮，誠足慕也，若夫氣竭力殘，弱胆怯心，進不及敵，中路為擒，仁而不武，春秋所箴，刚優劲勇，忿速輕急，推敵阻隧，我废彼立，君子去是，過猶不及。","sortOrder":88},
  {"id":"s_work_nvlt_74_89","chapterId":"ch_work_nvlt_74","text":"晉夏侯惇彈棋賦曰：嬿深宇以舒情，遘眾藝以廣娱，觀奇巧之朅麗，伟彈棋之妙殊，局則崑山之寶，華陽之石，或煩蜿龍藻，或分帶班駮，或發色玄黃，或皦的鱗白，悉魯匠之精能，傾工心於雕错，形方隆而應矩，焜煜霞以倏鑠，爾乃延良人，洽坐际，隆局施，輕棋列，徐正控往來，必有中而告憩，相形投巧，左撫右拔，揮纖指以長邪，［原訛耶，據冯校本改。］因偃掌而發八，陵超逾落，歸趣援势，紛交務而踖合，乘流密以遙曳，若乃釋正彈，循亂扬，［原訛場，據冯校本改。］滑石周散势縱橫，畀拨捶撇應無方，侈若天星之列，閃若流電之光，或擗柏散烂，揮霍便娟，或奋振唐唐，頹水參連，棋单局匮，等分紀殘，勝者含和，負者丧顏，惜情娱之未遂，恨白日之微遄，實機藝之端首，固君子之所歡也。","sortOrder":89},
  {"id":"s_work_nvlt_74_90","chapterId":"ch_work_nvlt_74","text":"【序】梁簡文帝彈棋論序曰：觀夫模穹蒼而挺质，寫博厚而成形，峙五嶽而摽奇，停四海而為量，协日月之數，應律呂之期，總玄黃之武略，校孫吳之應变，語其用心，壮哉之戲也，爾乃觀壮士之出師，望兵棋之式道，上昇則摶翼穹天，赴下則建瓴高屋，乘危則栈山航海，歷险則束馬懸車，完五憶霸國之勋，全六想陳平之智，反八均高陽之數，四角思漢後之歌，飛幾同晉侯之琴，徘徊異鄴中之輦，牵牛覺乘槎之來，織女擬雲軿之去，故古人或言之禮樂，或比之仁讓，或喻以修身，或齊諸道德，良有旨也。","sortOrder":90},
  {"id":"s_work_nvlt_74_91","chapterId":"ch_work_nvlt_74","text":"【啟】梁元帝謝東宮賜彈棋局啟曰：繹本慚遊藝，弥愧拂巾，鳳峙鷹扬，信難議擬，鳥跂星懸，曾何仿佛，莲花未易，玉屑不工，緣邊之法，庶遵細柳之陣，徘徊之势，方希明月之樓，子桓有錫，聞於遂古，季緒蒙賜，即事可傳。","sortOrder":91},
  {"id":"s_work_nvlt_74_93","chapterId":"ch_work_nvlt_74","text":"《說文》曰：博局戲六著十二棋也，古者乌曹作博。","sortOrder":93},
  {"id":"s_work_nvlt_74_94","chapterId":"ch_work_nvlt_74","text":"《山海經》曰：休與之山，其上有石焉，名曰帝台之棋，五色而文，状如鶉卵，［事具山部。］","sortOrder":94},
  {"id":"s_work_nvlt_74_95","chapterId":"ch_work_nvlt_74","text":"《穆天子傳》曰：天子與井公博，三日而决。","sortOrder":95},
  {"id":"s_work_nvlt_74_96","chapterId":"ch_work_nvlt_74","text":"《列子》曰：虞氏者，梁之富人，置高樓大路，設酒击博樓上，［事具人部遊俠篇。］","sortOrder":96},
  {"id":"s_work_nvlt_74_97","chapterId":"ch_work_nvlt_74","text":"尹《文子》曰：博盡關塞之宜，得周通之路，而不能製齒之大小，在遇者也。","sortOrder":97},
  {"id":"s_work_nvlt_74_98","chapterId":"ch_work_nvlt_74","text":"《家語》曰：哀公問孔子曰：吾聞君子不博，有之，孔子曰：有之，為其兼行惡道也。","sortOrder":98},
  {"id":"s_work_nvlt_74_99","chapterId":"ch_work_nvlt_74","text":"《說苑》曰：晉靈公驕奢，造九層之台，謂左右，敢諫者斬，孫息聞之，求見，公曰：子何能，孫息曰：臣能累十二棋，加九雞子其上，公曰：吾少學，未嘗見也，子為寡人作之，孫息即正顏色，定志意，以棋子置上，加雞子其上，左右慴息，靈公俯伏，氣息不續，公曰：危哉，孫息曰：公為九層之台，三年不成，危甚於此，［事具人部諫篇。］","sortOrder":99},
  {"id":"s_work_nvlt_74_100","chapterId":"ch_work_nvlt_74","text":"【論】吳韦昭博弈論曰：蓋聞君子恥當年而功不立，疾没世而名不稱，故曰：學如不及，猶恐失之，是以勉精厲操，晨興夜寐，不遑寧處，若甯越之勤，董生之篤，漸清德義之淵，栖遲道藝之域，且以西伯之聖，姬公之才，猶有日昃待旦之勞，况在臣庶，而可以已乎，歷觀古今功名之士，皆積累殊異之跡，勞神苦體，契闊勤思，平居不墮其業，窮困不易其素，是以卜式立志於耕牧，黃霸受道於囹圄，終有榮顯之福，以成不朽之名，今世之人，不務經術，好習博弈，废事弃業，忘寢與食，窮日盡明，繼以脂燭，當以臨局交爭，雌雄未决，人事曠而不修，賓旅闕而不接，雖有太牢之饌，韶夏之樂，不暇存也，然其所志不出一枰之上，所務不過方罫［古買。］之間，勝敵無封爵之賞，獲地無兼土之實，伎非六藝，用非經國，立身者不階其術，徵進者不由其道，求之於戰，則非孫吳之倫，考之於道藝，則非孔氏之門，以变诈之務，則非忠信之事，以劫殺為名，則非仁者之意，而空妨日废業，終無補益，何異設木而击之，置石而投之哉，且君子之居室也，勤身以致養，其在朝也，竭命以納忠，故老［《文選》五十二作孝。］友之行立，貞純之名彰，方今聖朝乾乾，務在得人，博選良才，旌簡旄俊，設呈［《文選》作程。］试之科，垂金爵之賞，誠千載之嘉會，百世之良遇也。","sortOrder":100},
  {"id":"s_work_nvlt_74_101","chapterId":"ch_work_nvlt_74","text":"◇樗蒲","sortOrder":101},
  {"id":"s_work_nvlt_74_102","chapterId":"ch_work_nvlt_74","text":"《異苑》曰：昔有人乘馬山行，遙岫里有二老翁，相對樗蒲，遂下馬，以策拄地而觀之，自謂俄頃，视其馬鞭，漼然已烂，顧瞻其馬，鞍骸枯朽，既還至家，無复親屬，一恸而絕。","sortOrder":102},
  {"id":"s_work_nvlt_74_103","chapterId":"ch_work_nvlt_74","text":"《博物志》曰：老子入胡，作樗蒲。","sortOrder":103},
  {"id":"s_work_nvlt_74_104","chapterId":"ch_work_nvlt_74","text":"庾翼集，參軍於瓒，陳節戲事曰：夫嬉戲都名動相剝，非為治之本，自今樗蒲〈木鄭〉馬，諸不急戲，宜一斷之，翼答曰：今唯許其围棋，餘悉斷。","sortOrder":104},
  {"id":"s_work_nvlt_74_105","chapterId":"ch_work_nvlt_74","text":"【賦】後漢馬融樗蒲賦曰：昔有玄通先生，遊於京都，道德既備，好此樗蒲，伯陽入戎，以斯消忧，抨則素旃紫罽，出乎西鄰，緣以缋繡，紩以綺文，杯則搖木之幹，出自崑山，矢則藍田之石，卞和所工，含精玉润，不細不洪，馬則玄犀象牙，是磋是砻，杯為上將，木為君副，齒為號令，馬為翼距，筹為策動，矢法卒數，於是芬葩貴戚，公侯之儔，坐華榱之高殿，臨激水之清流，排五木，散九齒，勒良馬，取道里，是以戰無常勝，時有逼遂，臨敵攘围，事在將帥，見利電發，紛纶滂沸，精誠一叫，入盧九雉，磊落踸踔，併來猥至，先名所射，應聲粉潰，勝貴歡悅，負者沉悴。","sortOrder":105},
  {"id":"s_work_nvlt_74_106","chapterId":"ch_work_nvlt_74","text":"◇投壶","sortOrder":106},
  {"id":"s_work_nvlt_74_107","chapterId":"ch_work_nvlt_74","text":"《禮記》曰：投壶之禮，主人奉矢，司射奉中，使人執壶，主人謂曰：某有枉矢哨壶，請以樂賓。","sortOrder":107},
  {"id":"s_work_nvlt_74_108","chapterId":"ch_work_nvlt_74","text":"《神仙傳》曰：玉女投壶，天為之笑。","sortOrder":108},
  {"id":"s_work_nvlt_74_109","chapterId":"ch_work_nvlt_74","text":"《東觀漢記》曰：祭遵薨，博士范升上疏曰：遵為將軍，取士皆用儒術，對酒娱樂，必雅歌投壶。又建為孔子立後，奏置五經大夫，雖在軍旅，不忘俎豆。","sortOrder":109},
  {"id":"s_work_nvlt_74_110","chapterId":"ch_work_nvlt_74","text":"《魏略》曰：邯鄲淳，字淑，［魏志王粲傳註作子叔，《太平御覽》七百五十三作元淑。］作投壶賦千餘言，奏之，文帝以為工，賜帛十匹。","sortOrder":110},
  {"id":"s_work_nvlt_74_111","chapterId":"ch_work_nvlt_74","text":"古歌曰：上金殿者，玉樽延貴客，入門黃金堂，東厨，具肴膳，椎牛烹猪羊，主人前進酒，琴瑟為清商，投壶對彈棋，博弈併复行，何劭作王弼傳曰：弼性好弘理，樂遊宴，解音律，善投壶。","sortOrder":111},
  {"id":"s_work_nvlt_74_112","chapterId":"ch_work_nvlt_74","text":"【賦】魏邯鄲淳投壶賦曰：古者諸侯間於天子之事，則相朝也，以正班爵，講禮獻功，於是乃崇其威儀，恪其容貌，繁登降之節，盛揖拜之數，機設而弗倚，酒澄而弗舉，肅肅濟濟，其惟敬焉，敬不可久，禮成於飫，乃設大射，否則投壶，植茲華壶，凫氏所鑄，厥高二尺，盤腹脩頸，飾以金銀，文以彫鏤，象物必具，距筵七尺，杰焉植駐，矢維二四，或柘或棘，丰本纖末，調劲且直，執算奉中，司射是職，曾孫侯氏，與之乎皆得，然後觀夫投者，閒習察妙，巧之所極，骆驿聯翩，爰爰兔發，翻翻隼集，不盈不縮，應壶順入，何其善也，每投不空，四矢退效，既入躍出，荏苒偃仰，黾勉趨下，餘势振掉。又足樂也，擬議於此，命中於彼，動之如志，靡有违也，譬諸為政，群職罔弛，左右畢投，效奇數鈞，列置功算。稱善告賢，三載考績，幽明始分也，比投不釋，增是自遂，雖往有功，義所不貴，春秋貶翚，亦猶是類也，若乃撮矢作驕，累掇聯取，一往之納二，巧無與耦，斯乃絕倫之才，尤異之首也，柯列葩布，匪罕匪綢，雖就置猶弗然，矧迥絕之所投，惟茲巧之妙麗，亦希世之寡儔，調心術於混冥，適容體於便安，紛縱奇於施舍，顯必中以微觀，悅與坐之耳目，樂眾心而不倦，朅玮百变，惡可窮贊。","sortOrder":112},
  {"id":"s_work_nvlt_74_114","chapterId":"ch_work_nvlt_74","text":"《說苑》曰：塞，行棋相塞，謂之塞也。","sortOrder":114},
  {"id":"s_work_nvlt_74_115","chapterId":"ch_work_nvlt_74","text":"《管子》曰：秋行五政，一曰秋禁，二曰博塞。","sortOrder":115},
  {"id":"s_work_nvlt_74_116","chapterId":"ch_work_nvlt_74","text":"《穆天子傳》曰：天子與井公塞也。","sortOrder":116},
  {"id":"s_work_nvlt_74_117","chapterId":"ch_work_nvlt_74","text":"《莊子》曰：臧與穀相與牧羊，問臧奚事，挟策讀書，問穀奚事，博塞以遊，事業不同，亡羊均也，伯夷死於首陽之下，盜跖死於東陵之上，所死不同，殘生均也。","sortOrder":117},
  {"id":"s_work_nvlt_74_118","chapterId":"ch_work_nvlt_74","text":"《漢書》曰：吾丘寿王，以格五召待詔，［孟康曰：乘五閣不得行，故雲格五也。］","sortOrder":118},
  {"id":"s_work_nvlt_74_119","chapterId":"ch_work_nvlt_74","text":"【賦】後漢邊孝先塞賦曰：可以代博弈者，曰塞其次也，试習其術，以驚睡救寐，免晝寢之譏而已，然而徐核其因通之極，乃亦精妙而足美也，故書其较略，舉其指歸，以明博弈無以尚焉，曰：始作塞者，其明哲乎，故其用物也約，其為樂也大，猶土鼓塊枹，空桑之瑟，质朴之化，上古所耽也，然本其規模，製作有式，四道交正，時之則也，棋有十二，律呂極也，人操厥半，六爻列也，赤白色者，分陰陽也，乍亡乍存，像日月也，行必正直，合道中也，趨隅方折，禮之容也，迭往迭來，刚柔通也，周則复始，乾行健也，局平以正，坤德順也，然則塞之為義，盛矣大矣，廣矣博矣，质象於天，陰陽在焉，取則於地，刚柔分焉，施於人，仁義載焉，考之古今，王霸備焉，覽其成败，為法式焉。","sortOrder":119},
  {"id":"s_work_nvlt_74_120","chapterId":"ch_work_nvlt_74","text":"◇藏鉤","sortOrder":120},
  {"id":"s_work_nvlt_74_121","chapterId":"ch_work_nvlt_74","text":"《風土記》曰：義陽臈日飲祭之後，叟嫗兒童，為藏鉤之戲，分為二曹，以效勝負，若人偶即敵對，人奇即人為遊附，或屬上曹，或屬下曹，名為飛乌，以齊二曹人數，一鉤藏在數手中，曹人當射知所在，一藏為一筹，三筹為一都。","sortOrder":121},
  {"id":"s_work_nvlt_74_122","chapterId":"ch_work_nvlt_74","text":"辛氏《三秦記》曰：昭帝母鉤弋夫人，手拳而有國色，先帝寵之，世人藏鉤法此也，［事具居處部宮殿篇。］","sortOrder":122},
  {"id":"s_work_nvlt_74_123","chapterId":"ch_work_nvlt_74","text":"【賦】晉庾闡藏鉤賦曰：叹近夜之藏鉤，复一時之戲望，以道生為元帥，以子仁為佐相，思蒙籠而不啟，目蜅泠而不畅，多取决於公長，乃不咨於大匠，鉤運掌而潛流，手乘虛而密放，示微跡於可嫌，露疑似之情状，辄爭材以先叩，各銳志於所向，意有往而必乖，策靡陳而不丧，退怨叹於獨見，慨相顧於惆怅，夜景煥烂，流光西驿，同明［疑當作朋。］誨其夙退，對者催其連射，攘袂以發奇，探意外而求跡，奇未發而妙待，意愈求而累僻，疑空拳之可取，手含珍而不摘，督猛炬而增明，從因朗而心隔，壮顏变成衰容，神材比為愚策。","sortOrder":123},
  {"id":"s_work_nvlt_74_124","chapterId":"ch_work_nvlt_74","text":"◇四維","sortOrder":124},
  {"id":"s_work_nvlt_74_125","chapterId":"ch_work_nvlt_74","text":"【賦】東晉李秀四維賦曰：四維戲者，衛尉挚侯所造也，畫紙為局，截木為棋，取象元，一分而為二，准陰陽之位，擬刚柔之策，而变動雲為，成乎其中，世有哲人，黃中通理，探赜索隱，开物建始，造四維之妙戲，邈眾藝之特奇，盡盈尺之局，乃擬象乎兩儀，立太極之正統，班五常之列位，刚柔異而作配，趍舍同而從類，或盤紆詰屈，連延骆驿，或間不容息，舍棋則獲，围成未合，驕棋先出，九道併列，专都獨畢。","sortOrder":125},
  {"id":"s_work_nvlt_74_126","chapterId":"ch_work_nvlt_74","text":"◇象戲","sortOrder":126},
  {"id":"s_work_nvlt_74_127","chapterId":"ch_work_nvlt_74","text":"周武帝造象戲。","sortOrder":127},
  {"id":"s_work_nvlt_74_128","chapterId":"ch_work_nvlt_74","text":"王襃為象經序曰：一曰天文，以觀其象，天日月星，是也，二曰地理，以法其形，地水木金土，是也，三曰陰陽，以順其本，陽數為先，本於天，陰數為先，本於地，是也，四時，［句有脱文。］以正其序，東方之色青，其餘三色，例皆如之，是也，五曰筭數，以通其变，俯仰則為天地日月星，变通則為水火金木土，是也，六曰律呂，以宣其氣，在子取未，在午取丑，是也，七曰八卦，以定其位，至震取兑，至離取坎，是也，八曰忠孝，以惇其教，出則盡忠，入則盡孝，是也，九曰君臣，以事其禮，不可以貴凌賤，直而為曲，不可以卑畏尊，隱而無犯，是也，十曰文武，以成其務，武論七德，文表四教，是也，十一曰禮儀，以製其則，居上不驕，為下盡敬，進退有度可法，是也，十二曰觀德，以考其行，定而後求，義而後取，時然後言，樂然後笑，是也，或升進以報德，義以遷善，或黜退以貶過，事在懲惡，或以沉審為貴，正其瞻视，或以徇齊為功，明其糾察，得失表於隆替，在賤必申，怠敬彰於勸沮，處尊思屈，片言崇於拱璧，一德逾於華袞。","sortOrder":128},
  {"id":"s_work_nvlt_74_129","chapterId":"ch_work_nvlt_74","text":"【賦】周庾信象戲賦曰：觀夫造作權舆，皇王厥初，法凝陰於厚德，仰冲氣於清虛，於［於下疑脱是字。］绿簡既开，丹局直正，理洞研幾，原窮作聖，若叩洪鍾，如懸明鏡，白鳳遙臨，黃雲高映，可以变俗移風，可以莅官行政，是以局取諸乾，仍圖上玄，月輪新滿，日晕初圓，模羽林之華蓋，寫明堂之璧泉，坤以為舆，刚柔卷舒，若方鏡而無影，似空城而未居，促成文之畫，亡靈龟之圖，馬麗千金之馬，符明六甲之符，於是搢笏當次，依辰就席，回地理於方珪，轉天文於圓璧，分荆山之美玉，數藍田之珉石，南行赤水之符，北使玄山之策，居東道而龍青，出西關而馬白，既舒玄象，聊定金抨，昭日月之光景，乘風雲之性靈，取四方之正色，用五德之相生，從月建而左轉，起黃鍾而順行，陰翻則顧兔先出，陽变則靈乌獨明，况乃豫遊仁寿，行樂徽音，水影搖日，花光照林，乍披圖而久玩，或开經而熟尋，雖复成之於手，終須得之於心，乃有龍燭衔花，金爐浮氣，月落桂垂，星斜柳墜，猶豫枢機，嫌疑涇渭，顧望回惑，心情怖畏，應對坎而冲離，忽當申而取未。","sortOrder":129},
  {"id":"s_work_nvlt_74_130","chapterId":"ch_work_nvlt_74","text":"《藝文類聚》　唐·欧陽詢","sortOrder":130},
  {"id":"s_work_nvlt_75_1","chapterId":"ch_work_nvlt_75","text":"卷七十五方術部","sortOrder":1},
  {"id":"s_work_nvlt_75_2","chapterId":"ch_work_nvlt_75","text":"○養生卜筮相疾医","sortOrder":2},
  {"id":"s_work_nvlt_75_3","chapterId":"ch_work_nvlt_75","text":"◇養生","sortOrder":3},
  {"id":"s_work_nvlt_75_4","chapterId":"ch_work_nvlt_75","text":"《易》曰：天地之大德曰生。","sortOrder":4},
  {"id":"s_work_nvlt_75_5","chapterId":"ch_work_nvlt_75","text":"《文子》曰：太上養神，其次養形，神清意平，百節皆寧，養生之本也，肥肌膚，充腸胃，閉嗜欲，養生之末也。","sortOrder":5},
  {"id":"s_work_nvlt_75_6","chapterId":"ch_work_nvlt_75","text":"《莊子》曰：吹吁呼吸，吐故納新，此导引之士，養形之人也，彭祖寿考者之所好也。","sortOrder":6},
  {"id":"s_work_nvlt_75_7","chapterId":"ch_work_nvlt_75","text":"《韓子》曰：神不註於外則身全，身全之謂得，得者得身也。","sortOrder":7},
  {"id":"s_work_nvlt_75_8","chapterId":"ch_work_nvlt_75","text":"華他別傳曰：他嘗語吳普，人體欲得勞動，但不當自使極爾，體常動搖，穀氣得消，血脈流通，疾則不生，卿見戶枢，雖用易腐之木，朝暮开閉動搖，遂最晚朽，是以古之仙者，赤松彭祖之為导引，蓋取於此也。","sortOrder":8},
  {"id":"s_work_nvlt_75_9","chapterId":"ch_work_nvlt_75","text":"《抱朴子》曰：爾乃咀吸寶華，穀神太清，外珍五耀，內守九精。","sortOrder":9},
  {"id":"s_work_nvlt_75_10","chapterId":"ch_work_nvlt_75","text":"又曰：城陽郄俭，少時行獵，墮空冢中，飢饿，見冢中先有大龟，數數回轉，所向無常，張口吞氣，或俯或仰，俭素亦聞龟能导引，乃试隨龟所為，遂不复飢，百餘日，頗苦極，後人有偶窥冢中，見俭而出之，後竟能咽氣斷穀，魏王召置土室中，閉试之，一年不食，顏色悅泽，氣力自若。","sortOrder":10},
  {"id":"s_work_nvlt_75_11","chapterId":"ch_work_nvlt_75","text":"【論】魏嵇康養生論曰：世或有謂神仙可以學得，不死可以力致者，或雲上寿一百二十，古今所同，過此以往，莫非妖妄，此皆兩失其情，粗试論之，夫神仙雖不目見，然記籍所載，前史所傳，较而論之，其有必矣，似持受異氣，禀之自然，非積學所能致也，至於导養得理以盡命，上獲千餘歲，下可數百年，而世不精，故莫能得之，豆令人重，榆令人瞑，合歡蠲忿，萱草忘忧，愚智所知也，薰辛害目，豚魚不養，常世所識也，蝨處頭而黑，麝食柏而香，頸處险而癭，齒居晉而黃，推此而言，凡所食之氣，蒸性染身，莫不相應，豈唯蒸之使重而無所輕，害之使闇而無所明，染之使黃而無使延哉，故神農曰：上藥性者，［《文選》五十三作上藥養命，中藥養性者，此有脱文。］誠知性命之理，因辅養以通也。","sortOrder":11},
  {"id":"s_work_nvlt_75_12","chapterId":"ch_work_nvlt_75","text":"◇卜筮","sortOrder":12},
  {"id":"s_work_nvlt_75_13","chapterId":"ch_work_nvlt_75","text":"《禮記》曰：龟為卜，筴為筮。","sortOrder":13},
  {"id":"s_work_nvlt_75_14","chapterId":"ch_work_nvlt_75","text":"又曰：昔三代明王，皆事天地之神明，無非卜筮之用，不敢以其私亵事上帝，［言動任卜筮也。］是故不犯日月，不违卜筮。","sortOrder":14},
  {"id":"s_work_nvlt_75_15","chapterId":"ch_work_nvlt_75","text":"《尚書》曰：立卜筮人。","sortOrder":15},
  {"id":"s_work_nvlt_75_16","chapterId":"ch_work_nvlt_75","text":"古史考曰：庖犧氏作，始有筮，其後殷時巫鹹善筮。","sortOrder":16},
  {"id":"s_work_nvlt_75_17","chapterId":"ch_work_nvlt_75","text":"《穆天子傳》曰：天子筮獵萃泽，其卦遇訟，逢公占之曰：藪泽蒼蒼，其宜正公，戎事則從。","sortOrder":17},
  {"id":"s_work_nvlt_75_18","chapterId":"ch_work_nvlt_75","text":"《左傳》曰：邾文公卜遷於繹，史曰：利於民而不利於君，邾子曰：苟利於民，孤之利也，天生民而树之君，以利之也，民既利矣，孤必與焉。","sortOrder":18},
  {"id":"s_work_nvlt_75_19","chapterId":"ch_work_nvlt_75","text":"《史記》曰：卜者以法天地，象四時，於民仁義，分策定卦，旋式正綦，而後言天地利害，事之成败，昔先王定國，必先龟筴日月，而乃敢代，正時日，乃後入，家產子，必先占吉凶，後乃育之，伏犧作八卦，為三百八十四爻，而天下治，句踐放文王八卦，以破敵國，霸天下。","sortOrder":19},
  {"id":"s_work_nvlt_75_20","chapterId":"ch_work_nvlt_75","text":"【論】晉庾闡蓍龟論曰：夫物生而後有象，象而後有數，有數而後吉凶存焉，蓍者尋數之主，非神明之所存，龟者啟兆之质，非靈照之所生，何以明之，夫求物於闇室，夜鑒者得之，無夜鑒之朗。又以火得之，得之功同也，致功之跡異也，不可見目因火鑒，便謂火為目，神凭蓍通。又謂蓍為神也，由此言之，神明之道，則大賢之闇室，蓍龟之用，豈非顏子之龍燭耶，蓍龟之運，亦所以感興卦兆，求通逆數。又非爻象之體，擬議之極者也，安得超登仙而含靈獨備哉，且殊方之卜，或责象草木，或取類瓦石，而吉凶之應，不異蓍龟，此為神通之主，自有妙會，不由形器，尋理之器，或因他方，不系蓍龟，然經有天生神物，不載圓神之說，言者所由也，直稱神之美，以及其跡，亦猶筌雖得魚，筌非魚也，蹄雖得兔，蹄非兔也，是以象以求妙，妙得則象，忘蓍以求神，神窮則蓍废。","sortOrder":20},
  {"id":"s_work_nvlt_75_21","chapterId":"ch_work_nvlt_75","text":"【箴】宋顏延之大筮箴曰：餘因讀易，偶意蓍龟，友人有請决遊宦務志，卦有咎占，故作大箴以悟焉，先王設筮，大人盡慮，卦遭同人，变而之豫，先號後笑，初睽末遇，時至運來，當在三五，功畢官成，幾乎衍數，慶在坤宮，灾在坎路，不出戶庭，獨立無懼，违此而動，投足失步，無惰爾儀，靈骨有知，無曰餘逆，神筴不豫，南人司箴，敢告馳骛。","sortOrder":21},
  {"id":"s_work_nvlt_75_22","chapterId":"ch_work_nvlt_75","text":"【序】梁元帝洞林序曰：蓋聞玄枵之野，鬼方難测，朱鳥之舍，神道莫知，而緹幔晓披，即辯黃鍾之氣，靈台夕望，便知玉井之色，复以談乎天者，雖絕名言之外，存乎我者，還居稱謂之中，餘幼學星文，多歷歲稔，海中之書，略皆尋究，巫鹹之說，偏得研求，雖紫微迢遞，如觀掌握，青龍顯晦，易乎窥覽，羨門五將，亟經玩習，韓終六壬，常所寶愛，至如周王白雉之筮，殷人飛燕之卜，蓍名聚雪，非關地極之山，卦有密雲，能擁西郊之氣，爻通七聖，世經三古，山陽王氏，直解談玄，河東郭生，才能射覆，兼而兩之，竊自許矣。","sortOrder":22},
  {"id":"s_work_nvlt_75_24","chapterId":"ch_work_nvlt_75","text":"《孫卿子》曰：古者姑布子卿，今之世有唐舉，相人形状顏色，而知其吉凶，世俗稱之，相形不如論心，論心不如擇術，形不勝心，心不勝術，術正而心從之，則形相惡而心術善，無害為君子也，形相雖善，而心術惡，無害為小人也。","sortOrder":24},
  {"id":"s_work_nvlt_75_25","chapterId":"ch_work_nvlt_75","text":"又曰：［按本條前有脱條，文亦有脱訛。］許負唐舉邓通條侯，此四公皆善相。","sortOrder":25},
  {"id":"s_work_nvlt_75_26","chapterId":"ch_work_nvlt_75","text":"《史記》［按此褚少孫補見史記九十六張丞相傳。］曰：韦賢至大鸿臚，有相工相之，當至丞相，賢有男四人。又使相之，至第二子玄成，曰：此子貴，亦當為丞相，賢曰：我若為丞相，有長子在，是安得為之，賢後竟為丞相，既死而長子有罪，乃立玄成，［事具職官部丞相篇。］","sortOrder":26},
  {"id":"s_work_nvlt_75_27","chapterId":"ch_work_nvlt_75","text":"《東觀漢記》曰：孝順梁後，永建三年，選入掖庭，相工萊通見，矍然驚駭，却再拜贺曰：此所謂日角偃月，相之極貴，臣所未嘗見也。","sortOrder":27},
  {"id":"s_work_nvlt_75_28","chapterId":"ch_work_nvlt_75","text":"又曰：班超行詣相者，曰：布衣諸生爾，當封侯萬里之外，超問其状，相者曰：生燕頷，飛而食肉，此萬里侯相也。","sortOrder":28},
  {"id":"s_work_nvlt_75_29","chapterId":"ch_work_nvlt_75","text":"【論】魏陳王曹植相論曰：世人固有身瘠而志立，體小而名高者，於聖則否，是以尧眉八采，舜目重瞳，禹耳參漏，文王四乳，然則世亦有四乳者，此則駑馬一毛似骥耳。","sortOrder":29},
  {"id":"s_work_nvlt_75_30","chapterId":"ch_work_nvlt_75","text":"又曰：宋臣有公孫呂者，長七尺，面長三尺，廣三寸，名震天下，若此之状，蓋遠代而求，非一世之異也，使形殊於外，道合其中，名震天下，不亦宜乎，語雲，無忧而戚，忧必及之，無慶而歡，樂必還之，此心有先動，而神有先知，則色有先見也，故扁鵲見桓公，知其將亡，申叔見巫臣，知其竊妻而逃也，荀子曰：以為天不知人事耶，則周公有風雷之灾，宋景有三次之福，以為知人事乎，則楚昭有弗禜之應，邾文無延期之報，由是言之，則天道之與相占，可知而疑，不可得而無也。","sortOrder":30},
  {"id":"s_work_nvlt_75_31","chapterId":"ch_work_nvlt_75","text":"魏王朗相論曰：然仲尼之門，童冠之群，不言相形之事，抑者亦難據故也，古之人，固有懷不副其貌，行不稱其聲者，是故夫子以言信行，失之於宰予，以貌度性，失之於子羽，聖人之於聽察精矣，然猶或有所不得，以此推之，則彼度表扪骨，指色摘理，不常中必矣，若夫周之叔服，漢之許負，各以善相稱於前世，而書专記其效验之尤著者，不過公孫氏之二子，與夫周氏之條侯而已。","sortOrder":31},
  {"id":"s_work_nvlt_75_32","chapterId":"ch_work_nvlt_75","text":"【贊】周庾信以蔡泽就唐生相贊曰：蔡泽羁旅，唐生决疑，無勞神策，不問靈龟，富貴自取，年寿須期，雖雲異相，會待逢時。","sortOrder":32},
  {"id":"s_work_nvlt_75_33","chapterId":"ch_work_nvlt_75","text":"【序】梁陶弘景相經序曰：相者，蓋性命之著乎形骨，吉凶之表乎氣貌，亦猶事先謀而後動，心先動而後應，表里相感，莫知所以然，且富貴寿夭，各值其數，董賢甫在弱冠，便位過三公，赀半於國，而裁出世，身摧家破，冯唐袴穿郎署，楊雄壁立高閣，而併至白首，或垂老玉食，而宦不過尉史，或穎惠若神，仅至龆龀，或不辯菽麥，更保黃耇，此又明其偏有得也。","sortOrder":33},
  {"id":"s_work_nvlt_75_34","chapterId":"ch_work_nvlt_75","text":"梁劉孝標相經序曰：夫命之與相，猶聲之與响，聲動乎幾，响窮乎應，雖寿夭參差，賢愚不一，其間大较，可得聞矣，若乃生而神睿，弱而能言，八采光眉，四瞳麗目，斯實天姿之特達，聖人之符表，洎乎日角月偃之奇，龍樓虎踞之美，地靜镇於城纏，天關運於掌策，金搥玉枕，磊落相望，伏犀起蓋，隱辚交映，井宅既兼，食匮已實，抑亦帝王卿相之明效也，及其深目長頸，頹顏慼齃，蛇行鷙立，猳喙鳥咮，筋不束體，血不華色，手無春荑之柔，發有寒蓬之悴，或先吉而後凶，或少長乎窮乏，不其悲欤，至如姬公凝負圖之容，孔父眇栖遑之跡，丰本知其有後，黃中明其可貴，其間或躍馬膳珍，或飛而食肉，或皂隸晚侯，初形未正，銅巖無以飽生，玉饌終乎饿死，因斯以觀，何事非命。","sortOrder":34},
  {"id":"s_work_nvlt_75_36","chapterId":"ch_work_nvlt_75","text":"《史記》曰：陳軫適至秦，惠王曰：子去寡人之楚，亦思寡人否，軫對曰：王聞越人莊舄乎，王曰：弗聞，軫曰：莊舄仕楚執珪，有頃而疾，為越聲，楚王曰：舄故越之鄙細人也，今仕楚執珪，貴極矣，亦思越不，或對曰：凡人思故，在其疾也，彼思越，即越聲，不思越，即楚聲，使人往聽之，猶尚越聲也，今臣雖弃逐之楚，豈能無秦聲哉。","sortOrder":36},
  {"id":"s_work_nvlt_75_37","chapterId":"ch_work_nvlt_75","text":"《漢書》曰：司馬相如疾甚，上曰：可往悉取其書，使往而相如已死，家無遺書，問其妻，對曰：長卿未嘗有書也，時時著書，人又取去，長卿未死時，為一卷書，曰：有使來求書，奏之，其遺札言封禪事，所司奏焉，天子異之。","sortOrder":37},
  {"id":"s_work_nvlt_75_38","chapterId":"ch_work_nvlt_75","text":"桓谭《新論》曰：餘歸沛道疾，蒙絮被絳罽裾，乘骍馬，宿東亭，亭長疑是賊，發卒夜來，餘令吏勿斗，乃相問而去。","sortOrder":38},
  {"id":"s_work_nvlt_75_39","chapterId":"ch_work_nvlt_75","text":"又曰：餘少時，見楊子雲之麗文高論，不自量年少新進，而猥欲逮及，嘗激一事，而作小賦，用精思太剧，而立發疹，子雲亦言成帝上甘泉，詔召作賦，卒暴，及倦臥，夢其五藏出在地，以手收內，及覺，大少氣，疾一歲而亡。","sortOrder":39},
  {"id":"s_work_nvlt_75_40","chapterId":"ch_work_nvlt_75","text":"《東觀漢記》曰：王良以疾歸，一歲，复徵至滎陽，疾篤，不任進道，乃過其友人，友人不肯見，曰：不有忠言奇謀，而取大位，何其往來屑屑不憚煩也，遂拒之，良慚，自後連徵，辄稱疾。","sortOrder":40},
  {"id":"s_work_nvlt_75_41","chapterId":"ch_work_nvlt_75","text":"《三辅决錄》曰：趙岐初名嘉，年三十餘，有重疾，臥蓐七年，自慮奄忽，乃為遺令，敕兄子，可立一員石於吾墓前，刻之曰：漢有逸民，姓趙名嘉，有志無時，命也奈何，其後疾瘳。","sortOrder":41},
  {"id":"s_work_nvlt_75_42","chapterId":"ch_work_nvlt_75","text":"《風俗通》曰：無恙，俗說疾也，凡人相見及書問者，曰：無疾耶，按上古之時，草居路宿，恙噬虫也，食人心，凡相勞問者曰：無恙乎，非為疾也。","sortOrder":42},
  {"id":"s_work_nvlt_75_43","chapterId":"ch_work_nvlt_75","text":"又曰：予之祖郴，為汲令，以夏至日，請主簿杜宣，賜酒，時北壁上有懸赤弩，照於杯中，其形如蛇，宣惡之，然不敢不飲，其日便得疾，雲蛇入腹，後郴使宣於故處設酒，杯中复有蛇，因謂宣，此乃壁上弩影耳，非有他怪，宣意遂解，甚怡怿。","sortOrder":43},
  {"id":"s_work_nvlt_75_44","chapterId":"ch_work_nvlt_75","text":"【詩】梁簡文帝臥疾詩曰：沉痾類弩影，積弊似河魚，詎逢龍子浴，空叹楚王菹。","sortOrder":44},
  {"id":"s_work_nvlt_75_45","chapterId":"ch_work_nvlt_75","text":"又喜疾瘳詩曰：朝窗猶掩扇，宿幔未懸鉤，逍遙臨四註，兼持散九愁，雖同衛子憊，聊喜挚生瘳，灾星夜出境，鳴禽晚去樓，蠲邪無贾服，祅氣息梁牛，隔帘荫翠，映水含珠榴，丹經蘊玉笥，玄水出長洲，結友尋方嶽，采藥訪圓丘，神隨七星变，貌逐五雲留，飛鸿若可駕，輕簪必易抽。","sortOrder":45},
  {"id":"s_work_nvlt_75_46","chapterId":"ch_work_nvlt_75","text":"梁劉孝威和簡文帝臥疾詩曰：玉躬耗寒暑，群望崇珪璧，仁祀盛黃缣，禮壇優绀席，憊均楚疾愈，俄同宋年益，豈勞誦賦臣，寧用觀涛客。","sortOrder":46},
  {"id":"s_work_nvlt_75_47","chapterId":"ch_work_nvlt_75","text":"梁朱超道歲晚沉痾詩曰：風將夜共靜，空與月俱明，燭滴龍猶伏，爐开鳳欲驚。葉飛林失影，冰合涧無聲，太息興床念，寧敢離衣行，唯畏殘藤盡，不聞桴鼓鳴。","sortOrder":47},
  {"id":"s_work_nvlt_75_48","chapterId":"ch_work_nvlt_75","text":"【賦】晉挚虞疾愈賦曰：餘體氣不和，飲食漸損，旬有餘日，眾疾併除，饋食纖纖而日鮮，體貌廉廉而轉損，校朝夕其未殊，验朔望而减本，形容消而憔悴，體质憊而狼狽，內忧深而慮遠，乃量餐而度帶，講和缓之餘論，尋越人之遺方，考異同以求中，稽眾術而簡良，會異端於妙門，乃歸奇於涉廛，惟茲藥之攸造，寶明中之窅堅，丸以三七為剂，服以四獻為程，势終朝而始發，景未仄而身輕，食信宿而異量，體涉旬而告平。","sortOrder":48},
  {"id":"s_work_nvlt_75_49","chapterId":"ch_work_nvlt_75","text":"梁裴子野臥疾賦曰：旅閨禁以永久，迫衰老而殷忧，無筋力以為禮，聊臥疾以來休，是時冻雨洒尘，涼陰滿室，風索索而傍起，雲霏霏而四密，爾乃高歌莫和，旨酒時傾，洗然尚想，何慮何營。","sortOrder":49},
  {"id":"s_work_nvlt_75_50","chapterId":"ch_work_nvlt_75","text":"【表】梁簡文帝在州羸疾自解表曰：昔违紫複，曾不弱冠，今夢青蒲，逝將已立，原歸之謁，不逮宸矜，民請之書，遽降天允，屬上党之雄，山西宣將，五校失道，八尉驕貪，一箭而解重围，更成戎阻，九戰而絕甬道，翻就丧師，雖王郭不追，朱買難嗣，實以褰襜明目，日夜厲精，地雜黠羌，民多獷俗，人非公孝，欲使任類汝南，勋異伯宗，必須榮逾戊己，州牧良才，實屬多士，無令菲薄，徒積妨賢。","sortOrder":50},
  {"id":"s_work_nvlt_75_51","chapterId":"ch_work_nvlt_75","text":"【書】梁簡文帝答湘東王書曰：暮春美景，風雲韶麗，蘭葉堪把，沂川可浴，弟邵南寡訟，時輟甘棠之陰，冀州為法，暫止褰襜之務，唐景荐大言之賦，安汰述連環之辯，盡遊玩之美，致足樂乎，吾春初臥疾，極成委弊，雖西山白鹿，懼不能愈，子預赤丸，尚忧未振，高臥六安，每思扁鵲之問，靜然四屋，念絕脩都之香，皇上慈被率土，甘露聿宣，鳴銀鼓於寶坊，轉金輪於香地，法雷警夢，惠日暉朝，道俗輻凑，遠近畢集，獨以疾障，致隔聞道，豈止楊仆有關外之傷，周南起留滯之恨。","sortOrder":51},
  {"id":"s_work_nvlt_75_52","chapterId":"ch_work_nvlt_75","text":"【序】梁陶景肘後百一方序曰：夫生民之所為大患，莫急乎疾疹，疾疹而弗治，猶救火不以水也，今輦掖左右，師藥易尋，郊郭之外，已自難值，况窮村迥陌，遙山絕浦，其間夭枉，焉可勝言，方術之書，卷秩徒繁，拯濟蓋寡，就欲披覽，回惑多端，抱朴此製，實為深益，然尚有闕漏，未盡其善，辄采集補闕，凡一百一首，葛氏序雲，可以施於貧家野居，然亦不止如此，今搢紳君子，若常處閒佚，乃可師藥有方，脱從祿外邑，將命遠途，或祗直禁闈，晨宵閉隔，或羁束戎陣，城壘嚴阻，忽驚急蒼卒，唯拱手相看，孰若便探之枕笥，則可庸竖成医，故備論節度，使晓然無滯。","sortOrder":52},
  {"id":"s_work_nvlt_75_54","chapterId":"ch_work_nvlt_75","text":"《左傳》曰：晉侯求医於秦，秦伯使医缓為之，［為猶治也。］未至，公夢二竖子曰：彼良医也，懼傷我，焉逃之，其一曰：居肓之上，膏之下，若我何，［肓，鬲也，心下為膏。］医至曰：疾不可為也，在肓之上，膏之下，攻之不可達，針之不及，藥不至焉，公曰：良医也，厚禮而歸之。","sortOrder":54},
  {"id":"s_work_nvlt_75_55","chapterId":"ch_work_nvlt_75","text":"《列子》曰：龍叔謂文挚曰：吾有疾，子能已乎，文挚即命龍叔背明而立，曰：嘻吾見子之心矣，子心穴孔流通，一孔不達，今聖智為疾者，或由此乎，［事具人部聖篇。］","sortOrder":55},
  {"id":"s_work_nvlt_75_56","chapterId":"ch_work_nvlt_75","text":"《史記》曰：扁鵲，姓秦，名越人，時舍客長桑君，遇而奇之，知非常人，及呼扁鵲與語，我有禁方，年老，欲傳與公，公無泄，乃出懷中藥與扁鵲。","sortOrder":56},
  {"id":"s_work_nvlt_75_57","chapterId":"ch_work_nvlt_75","text":"又曰：趙簡子疾，五日不知人，召扁鵲，扁鵲入视疾，出曰：昔秦穆公嘗如此，七日而寤，居二日半而簡子寤。","sortOrder":57},
  {"id":"s_work_nvlt_75_58","chapterId":"ch_work_nvlt_75","text":"《魏志》曰：華佗遊學徐土，兼晓養性之術，年且百歲，而猶有壮容，時人以為仙，沛相陳珪舉孝廉，太尉黃琬辟，皆不就，精於方藥，處剂不過數种，心識分銖，不假稱量，針亦不過數處，若疾結於內，針藥所不能及者，乃先令以酒服麻沸散，既醉，無所覺，因刳破腹背，抽割積聚，若在腸胃，則斷截湔洗，除去疾秽，既而縫合，傅以神膏，四五日創愈，一月之間，皆平复。","sortOrder":58},
  {"id":"s_work_nvlt_75_59","chapterId":"ch_work_nvlt_75","text":"【賦】晉嵇含寒食散賦曰：餘晚有男兒，既生十朔，得吐下積，日羸困危殆，决意與寒食散，未至三旬，幾於平复，何矜孺子之坎軻，在孩抱而婴疾，既正方之備陳，亦旁求於眾術，窮萬道以弗損，漸丁寧而積日，爾乃酌醴操散，商量部分，進不訪舊，旁無顧問，伟斯藥之入神，建殊功於今世，起孩孺於重困，還精爽於既繼。","sortOrder":59},
  {"id":"s_work_nvlt_75_60","chapterId":"ch_work_nvlt_75","text":"《藝文類聚》　唐·欧陽詢","sortOrder":60},
  {"id":"s_work_nvlt_76_1","chapterId":"ch_work_nvlt_76","text":"卷七十六內典上","sortOrder":1},
  {"id":"s_work_nvlt_76_2","chapterId":"ch_work_nvlt_76","text":"○內典","sortOrder":2},
  {"id":"s_work_nvlt_76_3","chapterId":"ch_work_nvlt_76","text":"◇內典","sortOrder":3},
  {"id":"s_work_nvlt_76_4","chapterId":"ch_work_nvlt_76","text":"《後漢書》曰：明帝夢金人，長丈餘，頭有光明，以問群臣，或曰：西方有神，名曰佛，其形丈六尺，而黃金色，帝於是遣［後漢書一百十八西域傳，遣下有使字。］天竺，問佛道法，遂於國中圖畫形象焉。","sortOrder":4},
  {"id":"s_work_nvlt_76_5","chapterId":"ch_work_nvlt_76","text":"《續漢書》曰：天竺國，一名身毒，在大月氏東南，修浮圖佛道以成俗，不殺伐。","sortOrder":5},
  {"id":"s_work_nvlt_76_6","chapterId":"ch_work_nvlt_76","text":"釋道安西域志曰：波羅奈斯國，佛轉法輪處，在此國也。","sortOrder":6},
  {"id":"s_work_nvlt_76_7","chapterId":"ch_work_nvlt_76","text":"又曰須剌國，有五百沙弥真人寺，望晦日，寺前有方青石，大人來下石上。","sortOrder":7},
  {"id":"s_work_nvlt_76_8","chapterId":"ch_work_nvlt_76","text":"又曰摩诃賴國，有阿耨達山，王舍城在山東南角，竹園精舍在城西。又有佛浴所，六年苦行處。","sortOrder":8},
  {"id":"s_work_nvlt_76_9","chapterId":"ch_work_nvlt_76","text":"支僧載外國事曰：和诃條國，在大海之中，地方二萬里，國有大山，山有石井，井中生千葉白莲花，井邊青石上，有四佛足跡，合有八跡，月六斋日，弥勒菩薩，與諸天神，禮佛变竟，便飛去，浮圖講堂皆七寶，國王長者，常作金树銀花，銀树金花，供養佛。","sortOrder":9},
  {"id":"s_work_nvlt_76_10","chapterId":"ch_work_nvlt_76","text":"又曰：維那國，去舍衛國五十由旬，由旬者晉言四十里，維摩詰家在城內，基井尚存。","sortOrder":10},
  {"id":"s_work_nvlt_76_11","chapterId":"ch_work_nvlt_76","text":"又曰：迦維羅越國，今屬播黎越國，猶有優婆塞，姓釋，可二十餘家，是白靜王之苗裔，昔太子生時，有二龍王，一吐冷水，一吐暖水，今有池，尚一冷一暖。","sortOrder":11},
  {"id":"s_work_nvlt_76_12","chapterId":"ch_work_nvlt_76","text":"又曰：鳩留佛姓迦葉，生那诃維國。","sortOrder":12},
  {"id":"s_work_nvlt_76_13","chapterId":"ch_work_nvlt_76","text":"又曰：弥勒佛當生波羅奈國，在迦維羅越南。","sortOrder":13},
  {"id":"s_work_nvlt_76_14","chapterId":"ch_work_nvlt_76","text":"又曰：罽賓國在舍衛之西，國王民人，悉奉佛，道人及沙門，到冬，未中前飲少酒，過中不复飯。","sortOrder":14},
  {"id":"s_work_nvlt_76_15","chapterId":"ch_work_nvlt_76","text":"又曰：佛在拘私那竭國般泥洹，欲泥洹時，自然有寶床從地出，有八萬四千國王，爭將佛歸，神妙天人曰：佛應就此土，那竭王乃作金棺椱［《太平御覽》七百九十七作柟。］檀車，送丧佛，［御覽作佛丧。］積薪不燒自燃，王將舍利歸宮，八萬四千國，興兵爭舍利，婆羅門分之，用金升量舍利，得八斛四貐，諸國各得，還立浮圖。","sortOrder":15},
  {"id":"s_work_nvlt_76_16","chapterId":"ch_work_nvlt_76","text":"宋元嘉起居註曰：阿羅单國王毗沙跋摩，遣使雲，諸佛世尊，常樂安隱，處雪山陰，雪水流註，百川洋溢，以味清净，周回屈曲，從趣大海，一切眾生，鹹得受用。","sortOrder":16},
  {"id":"s_work_nvlt_76_17","chapterId":"ch_work_nvlt_76","text":"又曰：師子王國，遣使奉獻，詔答雲，此小乘經甚少，彼國所有，皆可寫送。","sortOrder":17},
  {"id":"s_work_nvlt_76_18","chapterId":"ch_work_nvlt_76","text":"扶南記曰：頓遜國，屬扶南，西出海中，國主名崑崙，有天竺胡五百家，兩佛圖婆羅門千餘人，頓遜人敬奉其道，以香花自洗，精進不舍晝夜，香有區拨摩花，冬夏不衰，日載數千車货之，燥更香好。","sortOrder":18},
  {"id":"s_work_nvlt_76_19","chapterId":"ch_work_nvlt_76","text":"《南州異物志》曰：天竺國地方三萬里，佛道所上，其國王城郭宮室，皆雕文刻鏤。","sortOrder":19},
  {"id":"s_work_nvlt_76_20","chapterId":"ch_work_nvlt_76","text":"【詩】秦鳩摩羅什法師十喻詩曰：十喻以喻空，空必待此喻，借言以會意，意盡無會處，既得出長羅，住此無所住，若能映斯照，萬象無來去。","sortOrder":20},
  {"id":"s_work_nvlt_76_21","chapterId":"ch_work_nvlt_76","text":"宋謝靈運石壁立招提精舍詩曰：四城有頓踬，三世無極已，浮歡昧眼前，沉照貫終始，壮齡缓前期，頹年迫暮齒，揮霍夢幻頃，飄忽風電起，良緣迨未謝，時逝不可俟，敬擬靈鷲山，尚想祇洹軌，絕溜飛庭前，高林映窗里，禪室栖空觀，講宇折［本集作析。］妙理。","sortOrder":21},
  {"id":"s_work_nvlt_76_22","chapterId":"ch_work_nvlt_76","text":"又過瞿溪石室飯僧詩曰：清霄颺浮煙，空林响法鼓，庶乘四等觀，永拔三界苦。","sortOrder":22},
  {"id":"s_work_nvlt_76_23","chapterId":"ch_work_nvlt_76","text":"宋謝莊八月侍華林曜靈殿八關斋詩曰：玉桴乘夕遠，金枝終夜舒，澄淳玄化闡，希微寂理孚，梁武帝十喻幻詩曰：揮霍变三有，恍惚隨六尘，蘭園种五果，雕案出八珍，對見不可信，熟视事非真，空生四嶽想，徒勞七識神，著幻是幻者，知幻非幻人。","sortOrder":23},
  {"id":"s_work_nvlt_76_24","chapterId":"ch_work_nvlt_76","text":"又如炎詩曰：亂念矚長原，例見望遙炯，逶迤似江漢，汎濫若沧溟，金波扬素沬，銀浪翻绿萍，遠思如可取，近至了無形，熱緣熱惚逼，渴愛渴心生。","sortOrder":24},
  {"id":"s_work_nvlt_76_25","chapterId":"ch_work_nvlt_76","text":"又靈空詩曰：物情異所異，世心同所同，状如薪遇火，亦似草行風，迷惑三界里，顛倒六趣中，五愛性洞遠，十相法靈冲，皆從妄所妄，無非空對空。","sortOrder":25},
  {"id":"s_work_nvlt_76_26","chapterId":"ch_work_nvlt_76","text":"又乾闼婆詩曰：靈海自已極，沧流去無邊，蜃蛤生異氣，闼婆鬱中天，青城接丹霄，金樓帶紫煙，皆從望見起，非是物理然，因彼凡俗喻，此中玄中玄。","sortOrder":26},
  {"id":"s_work_nvlt_76_27","chapterId":"ch_work_nvlt_76","text":"又夢詩曰：甘寢隨四坐，蓋睡依五眾，违從競分諍，美惡相戲弄，出家為上首，入仕作梁棟，色已非真實，聞見皆靈洞，長眼出長夜，大覺和大夢。","sortOrder":27},
  {"id":"s_work_nvlt_76_28","chapterId":"ch_work_nvlt_76","text":"又會三教詩曰：少時學周孔，弱冠窮六經，中复觀道書，有名與無名，妙術鏤金版，真言隱上清，密行貴陰德，顯證表長齡，晚年开釋卷，猶日映眾星，苦集始覺知，因果乃方明，示教唯平等，至理歸無生。","sortOrder":28},
  {"id":"s_work_nvlt_76_29","chapterId":"ch_work_nvlt_76","text":"又遊鍾山大愛敬寺詩曰：才性之方便，智力非善權，叹逝比愆稔，交臂乃奢年，從流既難及，溺丧謂不然，三苦恒追隨，五毒自燒燃，貪癡養忧畏，熱惱坐燋煎，道心理歸終，信首故宜先，駕言追善友，回與尋勝緣，面势周大地，萦帶極長川，稜層叠嶂遠，逦迤磴道懸，朝日照花林，光風起香山，瑟居超七净，梵住逾八禪，始得展身敬，方乃遠心虔，菩提聖种子，十萬良福田，正趣果上果，歸依天中天，以我初覺意，貽爾後來賢。","sortOrder":29},
  {"id":"s_work_nvlt_76_30","chapterId":"ch_work_nvlt_76","text":"又和太子忏悔詩曰：玉泉漏向盡，金門光未成，缭繞聞天樂，周流扬梵聲，蘭湯浴身垢，忏悔净心靈，萎草獲再鮮，落華蒙重榮。","sortOrder":30},
  {"id":"s_work_nvlt_76_31","chapterId":"ch_work_nvlt_76","text":"梁簡文帝十空如幻詩曰：漢安設大响，周穆置高台，三里生雲霧，瞬息起冰雷。空持生識縛，徒用長心灾，慧人恒弃舍，庸識屢邅回，六尘俱不實，三界信悠哉。","sortOrder":31},
  {"id":"s_work_nvlt_76_32","chapterId":"ch_work_nvlt_76","text":"又水月詩曰：圓輪既照水，初生亦映流，溶溶如渍璧，的的似沉鉤，非關顧兔没，豈是桂枝浮，空令誰雅識，還用喜騰猴，萬累若消荡，一相何更求。","sortOrder":32},
  {"id":"s_work_nvlt_76_33","chapterId":"ch_work_nvlt_76","text":"又如响詩曰：叠嶂迥參差，連峰鬱相拒，遠聞如句味，遙應成言語，竟無五聲實，誰謂八音所，空或顛倒群，徒迷尘縛侣，愍哉火宅中，茲心良可去。","sortOrder":33},
  {"id":"s_work_nvlt_76_34","chapterId":"ch_work_nvlt_76","text":"又如夢詩曰：秘駕良難辨，司夢併成虛，未验周為蝶，安知人作魚，空聞延寿賦，徒勞岐伯書，潛令六識扰，安能二惑除，當須耳應滿，然後會真如。","sortOrder":34},
  {"id":"s_work_nvlt_76_35","chapterId":"ch_work_nvlt_76","text":"又如影詩曰：朝光照皎皎，夕漏轉骎骎，晝花斜色去，夜树有輕陰，併能興眼入，俱持動惑心，息形影方止，逐物慮恒侵，若悟假名淺，方知實相深。","sortOrder":35},
  {"id":"s_work_nvlt_76_36","chapterId":"ch_work_nvlt_76","text":"又鏡象詩曰：精金宛成器，懸鏡在高堂，後掛七龍網，前發四珠光，迥望疑垂月，傍瞻譬璧璫，仁寿含萬類，淮南辯四乡，終歸一忘有，何關至道場。","sortOrder":36},
  {"id":"s_work_nvlt_76_37","chapterId":"ch_work_nvlt_76","text":"又蒙豫忏悔詩曰：皇情矜幻俗，聖德愍重昏，製書开攝受，絲纶廣慧門，時英滿君囿，法侣盛天園，俱消五道縛，共荡四生冤，三循祛愛馬，六念靜心猿，庭深仗采艳，地寂伎聲喧，上風吹法鼓，垂齡鳴晝軒，新梅含未發，落桂聚還翻，早燈藏石磴，寒潮浸水門，一期蒙誘善，方原遣籠樊。","sortOrder":37},
  {"id":"s_work_nvlt_76_38","chapterId":"ch_work_nvlt_76","text":"又往虎窟山寺詩曰：細松斜繞径，峻嶺半藏天，古树無枝葉，荒郊多野煙，分花出黃鳥，桂石下新泉，蓊鬱均双树，清靈類八禪，栖神紫台上，縱意白雲邊，徒然嗟小藥，何由齊大年。","sortOrder":38},
  {"id":"s_work_nvlt_76_39","chapterId":"ch_work_nvlt_76","text":"又侍講詩曰：物善渥深慈，監撫宣王事，英邁八解心，高超七花意。","sortOrder":39},
  {"id":"s_work_nvlt_76_40","chapterId":"ch_work_nvlt_76","text":"又旦出興業寺講詩曰：沐芳肅朝帶，駕言祗净宮，羽旗承去影，鐃吹雜還風，吳戈忧服箭，骥馬绿沉弓，水照柳初碧，煙含桃半紅，見鶴徒知谬，察象理難同，方知惡四辯，奚用語三空。","sortOrder":40},
  {"id":"s_work_nvlt_76_41","chapterId":"ch_work_nvlt_76","text":"又和會三教詩曰：聚沫多緣假，摽空非色香，漢君雖啟夢，晉後徒降祥，玄機昔未辯，洞鑒資我皇。","sortOrder":41},
  {"id":"s_work_nvlt_76_42","chapterId":"ch_work_nvlt_76","text":"又夜望浮圖上相輪絕句詩曰：光中辯垂帶，霧里見飛鸞，定用方諸水，持添承露盤。","sortOrder":42},
  {"id":"s_work_nvlt_76_43","chapterId":"ch_work_nvlt_76","text":"又望同泰寺浮圖詩曰：遙看官佛圖，帶璧复垂珠，燭銀逾漢汝，寶铎邁崑吾，日起光芒散，風吟宮徵殊，露落盤恒滿，桐生鳳不雏，飛幡雜晚虹，音絳，晝鳥狎晨凫，梵世臨空下，應真蔽景趨，帝馬鹹千辔，天衣使六銖，意樂开長表，多寶現金軀，能令苦海渡，复使慢山逾，頭能周四忍，長當出五居。","sortOrder":43},
  {"id":"s_work_nvlt_76_44","chapterId":"ch_work_nvlt_76","text":"梁元帝和劉尚書侍講五明集詩曰：汲引留宸鑒，舟航動睿情，法王惟一法，無生信不生，日宮佳氣滿，月殿善風清，綺錢敞西觀，緹幔卷南榮。","sortOrder":44},
  {"id":"s_work_nvlt_76_45","chapterId":"ch_work_nvlt_76","text":"梁昭明太子玄圃講詩曰：试欲遊寶山，庶攸信根立，雖娱慧有三，終寡聞知十。","sortOrder":45},
  {"id":"s_work_nvlt_76_46","chapterId":"ch_work_nvlt_76","text":"鍾山解講詩曰：輪動文學乘，笳鳴賓從靜，瞰出嵒隱光，月落林餘影，情理既已詳，玄言亦兼逞。","sortOrder":46},
  {"id":"s_work_nvlt_76_47","chapterId":"ch_work_nvlt_76","text":"東斋聽講詩曰：庶茲祛八倒，冀此遣六尘，良思大車道，方原寶舡津，既餐甘露旨，方欲書諸紳。","sortOrder":47},
  {"id":"s_work_nvlt_76_48","chapterId":"ch_work_nvlt_76","text":"又參講席將訖詩曰：八水润焦牙，三明啟群目，寶铎且參差，名香晚芬鬱，輻舍六龍驚，微祛二鼠蹙，意树發空花，心莲吐輕馥。","sortOrder":48},
  {"id":"s_work_nvlt_76_49","chapterId":"ch_work_nvlt_76","text":"又同大僧正講詩曰：放光聞鷲嶽，金牒秘香城，窮原絕有际，雜照歸無名，若人聆至寂，寄說表真冥，能令梵志遣，亦使群魔驚，今聞大林聚，净土接承明，掖影連高塔，法鼓亂嚴更，雷聲芳树長，月出地芝生，已生法味樂，复悅玄言清，何因動飛辔，暫使尘勞輕。","sortOrder":49},
  {"id":"s_work_nvlt_76_50","chapterId":"ch_work_nvlt_76","text":"又开善寺法會詩曰：茲地信开寂，清曠唯道場，玉树琉璃水，羽帳鬱金床，紫柱珊瑚地，神幢明月璫，牵萝下石磴，攀桂陟松梁，涧斜日欲隱，煙生樓半藏，千祀終何邁，百代歸我皇，神功照不極，睿鏡湛無方，法輪明智日，慧海度慈航，尘根夕未洗，希霑垂露光。","sortOrder":50},
  {"id":"s_work_nvlt_76_51","chapterId":"ch_work_nvlt_76","text":"梁宣帝奉迎舍利詩曰：釋迦稱散體，多寶號金軀，白玉誠非比，黃金良莫逾，变見絕言象，端異乃冥符，靈知雖隱顯，妙色豈榮枯，唯當千劫後，方成無价珠。","sortOrder":51},
  {"id":"s_work_nvlt_76_52","chapterId":"ch_work_nvlt_76","text":"梁沈約八關斋詩曰：因戒倦輪飄，習障從尘染，四衢道難辟，八正扉猶掩，得理未易期，失路方知险，迷涂既已复，豁悟非無漸。","sortOrder":52},
  {"id":"s_work_nvlt_76_53","chapterId":"ch_work_nvlt_76","text":"又四城門詩曰：六龍既驚軫，二鼠复馳光，衰齡難慎辅，暮质易凋傷。又和王衛軍解講詩曰：妙輪輟往駕，寶树未开音，甘露為誰演，得二摽道心，眇眇玄涂曠，高義總成林，七花屏尘相，八解濯芳襟。","sortOrder":53},
  {"id":"s_work_nvlt_76_54","chapterId":"ch_work_nvlt_76","text":"梁庾肩吾和太子重雲殿受戒詩曰：皇明執東曜，帝扆居北辰，小乘开治道，大覺拯蒼民，殊涂同義路，分流合智津，傳香引上德，列伎進名臣，連閣翻如畫，圖雲更似真，鏡山衔殿影，梅梁落梵尘，苑桂恒留雪，天花不待春，萬年逢瑞應，千生值法身，天衣初拂石，豆火欲然薪，重善終無報，輕毛庶有因。","sortOrder":54},
  {"id":"s_work_nvlt_76_55","chapterId":"ch_work_nvlt_76","text":"又詠同泰寺浮圖詩曰：望園臨奈苑，王城對鄴宮，還從飛閣內，遙見崛山中，天衣疑拂石，鳳翅欲凌空，雲甍猶帶雨，莲井不生桐，盤承雲表露，鈴搖天上風，月出琛含水，天晴幡帶虹，周星疑更落，漢夢似今通，我後懷初照，不與伊川同，方應捧馬出，永得離尘蒙。","sortOrder":55},
  {"id":"s_work_nvlt_76_56","chapterId":"ch_work_nvlt_76","text":"梁劉孝綽和昭明太子鍾山解講詩曰：御鶴翔伊水，攀馬出王田，停鑾對寶坐，辯論說人天，淹尘資海適，照暗仰燈燃，法明一已散，笳劍俨將旋。","sortOrder":56},
  {"id":"s_work_nvlt_76_57","chapterId":"ch_work_nvlt_76","text":"梁劉孝儀和昭明太子鍾山解講詩曰：詔樂臨東序，時駕出西園，雖窮禮遊盛，終為尘俗喧，豈如弘七覺，扬鸞啟四門，夜氣清箫管，晓陣烁郊原，山風亂采毦，初景麗文轅，林开前騎騁，遙曲羽旄屯，煙壁浮青翠，石瀨响飛奔，回舆下重閣，降道訪真源，談空匹泉涌，缀藻邁弥繁，輕生逢遇誤，併作輦龍鵷。","sortOrder":57},
  {"id":"s_work_nvlt_76_58","chapterId":"ch_work_nvlt_76","text":"梁釋慧令和受戒詩曰：泬寥秋氣爽，搖落寒林疏，風散飛廉雀，浪動崑明魚，是日何為盛，證戒奉皇储，原陪升自在，神通任卷舒。","sortOrder":58},
  {"id":"s_work_nvlt_76_59","chapterId":"ch_work_nvlt_76","text":"梁王筠和太子忏悔詩曰：習惡歸禮忏，有過稱能改，聖德及群生，唱說信兼采，翘心荡十惡，邈誠銷五罪，三縛解智門，六尘清法海，超然故無著，逍遙新有待。","sortOrder":59},
  {"id":"s_work_nvlt_76_60","chapterId":"ch_work_nvlt_76","text":"梁王台卿和望同泰寺浮圖詩曰：朝光正晃朗，涌塔標千丈，儀鳳異靈鳥，金盤代仙掌，積栱承雕桷，高簷掛珠網，寶地若池沙，風鈴如树响，刻削生千变，丹青圖萬象，煙霞時出没，神仙乍來往，晨霧半層生，飛幡接雲上。","sortOrder":60},
  {"id":"s_work_nvlt_76_61","chapterId":"ch_work_nvlt_76","text":"周庾信和同泰寺浮圖詩曰：岧岧陵太清，照殿比東京，長影臨双闕，高層出九城，栱積行雲礙，幡搖度鳥驚，鳳飛如始泊，莲合似初生，輪重對月滿，铎韻擬鸞聲，晝水流全住，圖雲色半輕，露晚盤猶滴，珠朝火更明，雖連博望苑，還接銀沙城，天香下桂殿，仙梵入伊笙，庶聞八解樂，方遣六尘情。","sortOrder":61},
  {"id":"s_work_nvlt_76_62","chapterId":"ch_work_nvlt_76","text":"又詠闡弘二教詩曰：五明教已設，三元法复开，魚出［本集作山。］將鶴嶺，清梵兩邊來，香煙聚成塔，花雨積為台，空心論佛性，真氣辯仙才。","sortOrder":62},
  {"id":"s_work_nvlt_76_63","chapterId":"ch_work_nvlt_76","text":"又登雲居寺塔詩曰：重峦千仞塔，隥九層台，跗下雲峰出，窗前風洞开，躡嶺鍾聲度，中天梵响來。","sortOrder":63},
  {"id":"s_work_nvlt_76_64","chapterId":"ch_work_nvlt_76","text":"陳陰铿开善寺詩曰：鷲嶺春光遍，王城野望通，登臨情不極，萧散趣無窮，湋隨入戶树，花逐下山風，棟里歸雲白，窗外落暉紅，古石何年臥，枯树幾春空，淹留惜未及，幽桂有芳丛。","sortOrder":64},
  {"id":"s_work_nvlt_76_65","chapterId":"ch_work_nvlt_76","text":"又遊巴陵空寺詩曰：日宮朝絕磬，月殿夕無扉，網交双树葉，輪斷七燈辉，香盡奁猶馥，幡尘畫漸微，借問將何見，風氣動天衣。","sortOrder":65},
  {"id":"s_work_nvlt_76_66","chapterId":"ch_work_nvlt_76","text":"陳張正見陪衡陽王遊耆阇寺詩曰：甘棠聽訟罢，福宇试登臨，兔苑移飛蓋，王城列玳簪，階荒猶累玉，地古尚填金，龍桥丹桂偃，鷲嶺白雲深，秋窗被旅葛，夏戶响山禽，清風吹麥垄，細雨濯梅林。","sortOrder":66},
  {"id":"s_work_nvlt_76_67","chapterId":"ch_work_nvlt_76","text":"【頌】宋謝靈運無量寿佛頌曰：法藏長王宮，懷道出國城，原言四十八，弘誓拯群生，净士一何妙，來者皆清英，頹年欲安寄，乘化好晨征。","sortOrder":67},
  {"id":"s_work_nvlt_76_68","chapterId":"ch_work_nvlt_76","text":"齊王融净住子歸信門頌曰：生浮命舛，識罔情违，業雲結影，慧日潛暉，委蛇循途，極夜無歸，登山小魯，汎海難沂，參珉見璧，辯砾知璣，迷甘未遠，匪正何依。","sortOrder":68},
  {"id":"s_work_nvlt_76_69","chapterId":"ch_work_nvlt_76","text":"又忏悔三業門頌曰：樂田生滅，患以身全，業資意造，事假言筌，利名相倚，榮辱茲纏，燕骥匪躡，銅锴徒镌，惑端風緒，愛境旌懸，不勤一至，何階四禪。","sortOrder":69},
  {"id":"s_work_nvlt_76_70","chapterId":"ch_work_nvlt_76","text":"又出家善門頌曰：澡身浴德，晦跡埋名，將安寶地，誰留化城，道場曠謐，禪迳閒清，風飄弗响，震辄徒聲，嘯傲焉慮，脱落何營，長捐有結，永寘無生。","sortOrder":70},
  {"id":"s_work_nvlt_76_71","chapterId":"ch_work_nvlt_76","text":"又在家善門頌曰：處尘貴不染，被褐重懷珠，美玉耀幽石，曾蘭夕丛刍，四民亦為之，三界豈能渝，谅茲親愛沫，寧以财利拘，煩流舍智寶，榛路坦夷衢，萬品竟何匹，烈火树紅趺。","sortOrder":71},
  {"id":"s_work_nvlt_76_72","chapterId":"ch_work_nvlt_76","text":"又法門頌曰：出不自戶將何由，行不以法欲焉修，之燕入楚待騣足，凌河越海寄輕舟，通明洞燭煥曾景，深凝廣润湛川流，翼善开賢敷教義，昭蒙啟惑涤煩忧，功成弗有居無著，淡然無執與化遊。","sortOrder":72},
  {"id":"s_work_nvlt_76_73","chapterId":"ch_work_nvlt_76","text":"梁簡文帝大法頌曰：若夫眇夢華胥，怡然如射，服齊宮於玄扈，想至理於汾陽，輕九鼎於褰裳，视萬乘如脱屣，斯蓋示至公之要道，未臻於出世也，至於藏金玉於川岫，弃琴瑟於大壑，卑宮菲食，茨堂土階，彤車非巧，粗裘靡飾，斯蓋示物以俭，亦未偕於出世也，解網放禽，穿泉掩胔，起泣辜之泽，行扇暍之慈，推溝之念，有如不足，納隍之心，無忘宿寤，善所以示，物以為仁，亦未偕乎出世也，甘泉啟太一之壇，嵩山置奉高之邑，碣石刻羨門之誓，不夜作交門之歌，斯蓋止愛久齡，事存諸己，篤而為論，弥有未弘，豈若燃智慧之炬，照生死之闇，出五陰之聚，升六度之舟，浮眾得之海，踐不至之岸，驅彼眾生，同跻仁寿，引茲具縛，俱入大乘，九有傾心，十方草靡。","sortOrder":73},
  {"id":"s_work_nvlt_76_74","chapterId":"ch_work_nvlt_76","text":"玄圃園講頌曰：七辯懸流，双因俱啟，情遊彼岸，理愜祇園，於時藏秋仲節，麗景好晨，氣含金扇，霜浮玉管，鳥〈亢鳥〉於琼音，树藏蕤於妙葉，液水穿流，蓬山寫状，風生月殿，日照槐煙，辭曰：析論冥空，玄幾入道，密宇清幽，重關相藻，日暎金雲，風搖銀草。","sortOrder":74},
  {"id":"s_work_nvlt_76_75","chapterId":"ch_work_nvlt_76","text":"【贊】宋謝靈運聚幻贊曰：幻工作同異，誰复謂非真，一從遊物過，既往亦何陳，谬者疑久近，遠者皆自賓，勿起離合情，會無百代人。","sortOrder":75},
  {"id":"s_work_nvlt_76_76","chapterId":"ch_work_nvlt_76","text":"又聚沫泡合贊曰：水性本無泡，激流遂聚沫，即異成貌状，消散歸虛壑，君子識根本，安事勞與奪，愚俗駭变化，橫复生欣怛。","sortOrder":76},
  {"id":"s_work_nvlt_76_77","chapterId":"ch_work_nvlt_76","text":"又影响合贊曰：影响順聲色，資物故生理，一旦揮霍去，何因得象似，群有靡不然，昧漠乎自已，四色尚無本，八微欲安恃。","sortOrder":77},
  {"id":"s_work_nvlt_76_78","chapterId":"ch_work_nvlt_76","text":"隋江總香贊曰：海岸相傳，香流大千，不吹自轉，將銷更燃，萦空雜霧，散迥飛煙，還符戒品，薰修福田。","sortOrder":78},
  {"id":"s_work_nvlt_76_79","chapterId":"ch_work_nvlt_76","text":"又花贊曰：池中寶花，葉覆金沙，逆風氣亂，映水光斜，散由天女，賣乃王家，若生心树，原結因牙。","sortOrder":79},
  {"id":"s_work_nvlt_76_80","chapterId":"ch_work_nvlt_76","text":"又燈贊曰：寶燈夜开，影遍花台，煙抽細焰，燼落輕灰，珠慚色併，月恥光來，一明暗室，若遣尘埃。","sortOrder":80},
  {"id":"s_work_nvlt_76_81","chapterId":"ch_work_nvlt_76","text":"又幡贊曰：金幡化成，搖荡相明，留無定影，散乃俱輕，光分绀殿，采掛香城，恒知自轉，福與之生。","sortOrder":81},
  {"id":"s_work_nvlt_76_82","chapterId":"ch_work_nvlt_76","text":"【碑】梁元帝荆州長沙寺阿育王像碑曰：蓋聞璇璣玉衡，穹昊所以紀物，金版玉文，淳精所以播氣，何則，鹹秩社首，義盡於寰中，鑄鼎冯翊，未窮於系表，况复道冠萬靈，理超千聖，智周十地，行圓四等，变海成蘇，移山入芥，鉢鋒廣說，藕絲見道，惠音八种，面門五色，組鉢生華，入青樓而吐曜，金床照采，出紫殿而相辉，才度莲河，即處天冠之寺，始遊羅衛，便居堅固之林，斯蓋俯應阎浮，未臻常樂，降情誘接，豈窮妄相，若乃境無引汲，智生淺深，明同一體，惑起十重，七地初刃，方稱变易，三達後心，因窮智种，然俱冥四德，脱屣双林，示表金棺，現焚檀椁，浩浩焉不可知已，却望五津，距青莲之洞，傍臨三峡，帶明月之流。","sortOrder":82},
  {"id":"s_work_nvlt_76_83","chapterId":"ch_work_nvlt_76","text":"梁劉孝儀雍州金像寺無量寿佛像碑曰：昔尧乃則天，莫能名其聖，丘才譬日，無德稱其道，况复欲宣五品，將叹三法，固使迦葉恥其無智，龍树羞其非辯，猶聞獻蓋長者，頌以七言，無學比丘，陳其百句，至有九辈性生，一身補處，尘洗玉池，神聞金葉，树聲繁會，趙簡於是未聞，地寶焜煌，周穆之所不見，昔者出城石轉，還林現疾，夢树既沉，梵花獨反，猶有香杖叠衣，紅爪绀發，可得崇以妙利，顯用珍函，彼弥紘感化殊攝，日輪照曜，月面從容，毫散珠辉，唇开果色，似含微笑，俱註目於瞻仰，如出软言，鹹傾耳於諦聽，像复以其夕，出住寺門，始則映顯巖間，猶對鷲山之禮，末又徘徊阃外，似救毗城之疾，空中生树，豈曰難思，火內披莲，未為多有，銘曰：奄有净國，實應多祉，葉產梵童，花开釋子，玉莲交映，銀荷遞起，伊尹慚桑，伯陽羞李。","sortOrder":83},
  {"id":"s_work_nvlt_76_84","chapterId":"ch_work_nvlt_76","text":"梁劉勰剡縣石城寺弥勒石像碑銘曰：夫道源虛寂，冥機通其感，神理幽深，玄德司其契，是以四海將寧，先入感鳳之寶，九河方导，已致應龍之畫，况种智圓照，等覺遍知，扬萬化於大千，摛亿形於法界，其靈起攝誘之權，影現戲遊之力，可勝言者哉，自優曇發華，而金姿誕應，娑羅变葉，而塔像代興，月喻論其跡隱，鏡象譬其常照，律師應法似流，宣化如渴，楊舲遊水，馳錫禹山，於是扪虛梯漢，構立栈道，状奇肱之飛車，類似叟之懸閣，體高圖范，冠采虹蜺，推凿响於霞上，剖石洒於雲表，信命世之壮觀，曠代之鸿作也，青艧與丹粟競采，白金共紫铣爭辉，梵王四鶴，徘徊而不去，帝釋千馬，踯躅而忘歸。","sortOrder":84},
  {"id":"s_work_nvlt_76_85","chapterId":"ch_work_nvlt_76","text":"【寺碑】齊王巾頭紘寺碑銘曰：蓋聞抱［《文選》五十九作挹。］朝夕之池者，無以测其淺深，仰蒼蒼之色者，不足知其遠近，况视聽之外，若存若亡。","sortOrder":85},
  {"id":"s_work_nvlt_76_86","chapterId":"ch_work_nvlt_76","text":"梁簡文帝善覺寺碑銘曰：蓋聞在天成象，倬彼雲漢，在地成形，嵩高惟嶽，蒼蒼斡運，靈槎猶且去來，巖巖峻極，巫鹹可以升降，穆貴嫔宿植遠因，已於恒沙佛所，經受記莂，有绿［全梁文十四作緣。］娑婆，降跡斯土，行邁英皇，德降華附，河南望浮雲之瑞，新野表升天之祥，光前絕後，建茲福地，乃於建康之太清里，建善覺寺焉，大通元年，龍集己酉，有令使立碑文，未獲構撰，居諸不息，寒暑推移，軒曜夙傾，前星次掩，歲在诹訾，始得補輟，何言之陋，何事之隆，竊等仲由，空悲負粟之哽，复異桓良，終無維山之日，永言纏纂，獨咽丹心，銘曰：效彼毗城，建斯福舍，四柱浮懸，九城靈架，重栾交峙，回廊逢迓，掩映花台，崔嵬蘭榭，陽燧暉朝，青莲开夜。","sortOrder":86},
  {"id":"s_work_nvlt_76_87","chapterId":"ch_work_nvlt_76","text":"又神山寺碑序曰：天地始終，愆長不極，劫數沙尘，寂寥誰辯，雖鐵界銅围，如影如約，補石擎金，隨生焰滅，獨有鷲嶽靈境，净土不燒，螺髻金质，聲聞難睹，故發塔喜園，流名天上，耆山鵠苑，布跡人中，自非莊嚴妙土，吉祥福地，何以標茲净域，置此伽藍，皇太子殿下，幾圓上聖，智周物外，澄明離日，照影春星，長歌安勝，表察書之獨見，馳道回車，鶩班輪而不絕。","sortOrder":87},
  {"id":"s_work_nvlt_76_88","chapterId":"ch_work_nvlt_76","text":"梁簡文帝慈覺寺碑序曰：竊以易表含貞，記稱厚載，龍星啟曜，璧月儀天，是以河外黃雲，沙傍崩鹿，故能發緯伊緒，重闡劉系，亦有觀津美於西漢，扶風盛彼東京，未若樊污［疑當作沔。］之邦，宛葉之境，休祥茂祉，獨繁前跡，莊姬流譽之所，烈後業興之地，南陽稱其何氏，新野猶曰邓家，逖彼遐蹤，复履今慶，貴嫔金聲早振，淑范增徽，才實母師，行為女楷，窮茲四德，洞彼六經，溫明內湛，慈慧天發，君缀慶璇枝，聯休紫漢，幸得愆無負斧，任重束蕃，實以契闊言提，綢缪善誘，事其從居，義深則盼，而叨恩作牧，衅結幽祗，一訣椒慈，長违寶幄，風枝弗靜，陟屺何期，祗奉储訓，谬茲刊撰，夫道長業大，遺范事隆，嗟油素之可捐，懼故老之難述。","sortOrder":88},
  {"id":"s_work_nvlt_76_89","chapterId":"ch_work_nvlt_76","text":"又相宮寺碑曰：真人西滅，洎羅漢東遊，五明盛士，併宣北門之教，四姓小臣，稍罢南宮之學，超洙泗之濟濟，比舍衛之洋洋，是以高簷三丈，乃為祀神之舍，連閣四周，併非中宮之宅，雪山忍辱之草，天宮紘树之花，四照芬吐，五衢異色，能令枎解說法，果出妙衣，鹿苑豈殊，祇林何遠，皇太子萧緯，自昔蕃邸，便結善緣，雖銀藏蓋寡，金地多闕，有慚四事，久立五根，泗川出鼎，尚刻之罘之石，崏峨作镇，猶銘劍壁之山，矧伊福界，寧無镌刻，銘曰：洛陽白馬，帝釋天冠，开基紫陌，峻極雲端，實惟爽垲，栖心之地，譬若靜土，長為佛事，銀鋪曜色，玉蛇楚金光，塔如仙掌，樓疑鳳皇，珠生月魄，鍾應秋霜，鳥依交露，幡承杏梁，窗舒意蕊，室度心香，天琴夜下，绀馬朝翔，生滅可度，離苦獲常，相續有盡，歸乎道場。","sortOrder":89},
  {"id":"s_work_nvlt_76_90","chapterId":"ch_work_nvlt_76","text":"又梁元帝善覺寺碑曰：金盤上疏，非求承露，玉寫前臨，寧資润蛇楚，飛軒絳屏，若丹氣之為霞，綺井绿錢，如青雲之入呂，寶繩交映，無慚紫绀之宮，花台照日，有跡白林之地，銘曰：聿遵勝業，代彼天工，四園枝翠，八水池紅，花疑鳳翼，殿若龍宮，銀城映沼，金齡响風，露台含月，珠幡拂空。","sortOrder":90},
  {"id":"s_work_nvlt_76_91","chapterId":"ch_work_nvlt_76","text":"又鍾山飛流寺碑曰：清梵夜聞，風傳百常之觀，寶鈴朝响，聲扬千秋之宮，同符上隴，望長安之城闕，有類偃師，瞻洛陽之台殿，瞰連甍而如綺，雜木而成帷。銘曰：雲聚峰高，風清鍾彻，月如秋扇，花疑春雪，極目千里，平原〈艹迢〉遰。","sortOrder":91},
  {"id":"s_work_nvlt_76_92","chapterId":"ch_work_nvlt_76","text":"又曠野寺碑曰：雲楣膠葛，桂棟陰峰，刻虬龍於洞房，倒莲花於綺井，月殿朗而相暉，雪宮穆以華壮，〈車獻〉々璇題，虹梁生於暮雨，嶪嶪銀榜，飛觀入乎雲中，銘曰：圓璫旦暉，方諸夜朗，金盤曜色，寶鈴成响。","sortOrder":92},
  {"id":"s_work_nvlt_76_93","chapterId":"ch_work_nvlt_76","text":"又郢州晉安寺碑銘曰：鳳皇之嶺，芊綿映色，莲花之洞，照曜增辉，山雲，黃鶴，疑聞天之夜响，城稱却月，似輕雲之霄蔽，銘曰：虹梁紫柱，螭桷丹牆，綺井飛棟，華榱壁璫，應龍若動，威鳳疑翔，玉舄霄润，金池夕光，朱城却棁，紫陌潛通，堑柳朝绿，江暉暝紅，落霞將暮，鮮雲夕布，峰下陽乌，林生陰兔，分珮隔浦，皇樯隱霧，俱聽法鍾，同觀寶聚。","sortOrder":93},
  {"id":"s_work_nvlt_76_94","chapterId":"ch_work_nvlt_76","text":"又楊州梁安寺碑序曰：竊以陽之有宗者，莫擬於靈乌，夜之有光者，孰逾於陰兔，故以日門見羲和之色，月殿望奔娥之象，而合璧迢遰，丈尺猶且莫量，朗鏡悠遠，積空之所不筭，复有紫川青龍之水，却月朝霞之山，白珪玄璧，餞瑤池之上，銀闕金宮，出瀛洲之下，空台四柱，隨仙衣而俱颺，寶堑三重，映瑞園而涵影，旃檀散馥，無复圓覺之風，地涌神龛，皆成多寶之塔。","sortOrder":94},
  {"id":"s_work_nvlt_76_95","chapterId":"ch_work_nvlt_76","text":"又攝山栖霞寺碑曰：金池無底，已通實堑之侧，玉树生風，傍臨采舡之上，七重欄楯，七寶莲花，通風承露，含香映日，銘曰：苔依翠屋，树隱丹楹，涧浮山影，山傳涧聲，風來露歇，日度霞輕，三灾不毀，得一而貞。","sortOrder":95},
  {"id":"s_work_nvlt_76_96","chapterId":"ch_work_nvlt_76","text":"又歸來寺碑曰：幡影颺於絳台，梵聲依於應塔，三相不留，萧蠶終坏，八苦遐長，燈蛾未已，銘曰：鈴隨風振，盤依露泫，丹桂無枝，朱楊自翦，九苑萌枯，三昧葉卷，疏树搖落，翻流清淺。","sortOrder":96},
  {"id":"s_work_nvlt_76_97","chapterId":"ch_work_nvlt_76","text":"梁沈約法王寺碑曰：昔周師集於孟津，漢兵至於垓下，翦商肇乎茲地，殪楚由乎斯域，慧雲匪由觸石，法雨起乎悲心，驅之仁寿，度之彼岸，濟方割於有頃，扑既燎於無邊，陆旗風靡，水陣雲披，萦山為堞，失其九天之险，負疑為隍，曾無一苇之閡，昏師反接，伪牧泥首，掬指則河舟尚虛，委甲則熊嶺非峻，乃按兵江漢，誓眾商郊，因斯而運斗枢，自茲而廓天步，業隆放夏，功高伐殷，濟橫流而臣九服，握乾網而子萬姓，眷言四海，莫不來王，此惟餘宅，寧止西顧，臨朝夕之濬池，帶長洲之茂苑，藉離宮於漢舊，因林光於秦餘，回廊敞匝，複殿重起，連房極睇，周堵如雲，銘曰：往却將謝，灾難孔多，炎炎烈火，淼淼洪波，聚為丘嶽，散成江河，俗緣浮诡，真諦遐長，匪因希向，曷寄舟梁，標功顯德，事歸道場，祁祁法眾，同茲無我，振錫經行，祇林宴坐，或斯寂滅，或念薪火，惆怅三明，徘徊四果。","sortOrder":97},
  {"id":"s_work_nvlt_76_98","chapterId":"ch_work_nvlt_76","text":"梁陆倕天光寺碑曰：法雲旦聚，則浸润被乎重沙，慧日晨登，則暉光燭於有頃，皇帝乃把神珠，握靈鏡，击天鼓，橦地鍾，驅日月之師，勒星辰之陣，九流外籍，五明內典，鳥策餘文，龍宮遺教，莫不神遊房奧，跡遍門牆，思洞希微，言窮名象，珉陛凌虛，琼篱鬱起，可使龍城愧飾，雁塔慚珍，日宇奪暉，月宮掩麗，昔者姬水寿丘，載紀山川之目，丹陵負夏，仅傳乡党之名，歌酒故邑，賜覆窮乎身世，埙篪舊里，高會止於當年，銘曰：被物如露，偃民猶草，解髻傳珠，抽衣受寶，化违宅火，功超河岸，舍我神居，興茲靈馆，八袭丰殿，四柱高廊，併陳金璧，旁建玉厢，蹤橫雜树，間廁眾芳。","sortOrder":98},
  {"id":"s_work_nvlt_76_99","chapterId":"ch_work_nvlt_76","text":"梁王筠开善寺碑曰：妙門關鍵，辟之者既難，法海波澜，遊之者未易，是以軒稱俊聖，尧曰钦明，韶護有美善之風，文武致時雍之業，地平天成，惟事即世，移風易俗，匪止今身，至如訪道峒山，乘風獨遠，疑神汾水，杳［原訛肯，據冯校本改。］然自丧，或宗仰黃老之淡，景慕神仙之術，斯蓋不度群生，事局諸己，篤而為論，道有未弘，薰風遹露，散馥流甘，璧月珠星，聯華颺葉，脩幡繞於雲根，和鈴响於天外，玉池動而扬文，寶树搖而成樂，銘曰：亭亭功漢，耿介凌煙，層甍霞耸，飛棟星懸。","sortOrder":99},
  {"id":"s_work_nvlt_76_100","chapterId":"ch_work_nvlt_76","text":"梁張綰龍樓寺碑曰：蓋聞井魚之不識巨海，夏虫之不見冬冰，故知局於泥甃者，未测沧溟之浩汗，篤於一時者，寧信寒暑之推移，何異乎玩即世而弗悟於生死之流，耽假樂而迷於真覺之觀，銘曰：識相裁萌，無明重蔽，五住次起，四生無际，苦海倒流，業風橫厲，彼岸何遠，津航絕濟，輕毛易轉，花水難留，寔逢象正，悟彼生修，照曜真法，逍遙寶舟，占彼勝地，胥宇攸宅，遙川萦帶，峻矩盤桓，霞生莲堞，風起長澜，冬室停燠，夏台增寒。","sortOrder":100},
  {"id":"s_work_nvlt_76_101","chapterId":"ch_work_nvlt_76","text":"周王襃善行寺碑曰：蓋聞在天成象，群星仰於北辰，在地成形，百川起於東海，是知璿璣盈縮，併運天枢，江漢所宗，爭環地軸，尘沙日月，同渤澥之輪回，百亿鑯围，等阎浮之數量，章亥步骤，豈盡世界之邊，隸首忽微，寧窮却海之筭，乌牛桷力，方十行之偕梯，{少兔}馬渡河，譬三乘之等級，定水坏須弥之山。智炬燃金刚之际，敬表六和，現沙門之進止，衣乘四寸，示聲聞之律儀，至於千叠火然，鵠林变色，四禪灾起，鴿影傳辉，羽林出使，漢开濯龍之祀，桑門傳譯，晉處洛陽之拜。","sortOrder":101},
  {"id":"s_work_nvlt_76_102","chapterId":"ch_work_nvlt_76","text":"京師突厥寺碑曰：夫六合之內，存乎方册，四天之下，聞諸象教，百亿阎浮，尘沙筭而不盡，三千日月，世界數而無邊，至於周星夕陨，漢宮宵夢，身高梵世，力减須弥，應現十方，分身百佛，上極天中，下窮地际，轉法輪於稔國，留妙象於罽賓，至於善見神通，瓶沙瑞相，波斯鑄金，優填雕木，莫不歸依等覺，回向佛乘，弃形骸而入道，舍國城而離俗，突厥大伊尼溫木汗，夏後餘基，惟天所置，威加窮發，兵歷無革，小大當戶，左右賢王，麟膠角觸之弓，鷲羽射雕之箭，跨葱嶺之酋豪，靡不從化，逾天山之君長，鹹皆賓屬，人敦信契，國寶親鄰，太祖文皇帝，道被寰中，化覃無外，提群品於萬福，濟蒼生於六道，大冢宰晉國公，功高夤亮，位隆光辅，命司空而度地，監匠人而置臬，帶三條之逸陌，面九市之通鄽，圖木緹錦，雕楹砻密，香隨微雨，自麗風尘，幡雜天花，常調絲竹，四禪大患，净界無毀，六珠芬盡，法身常住，銘曰：七華妙覺，三空勝境，意树已彫，心猿斯靜，靈城偃色，空衣滅影，索隱窮源，振衣提領。","sortOrder":102},
  {"id":"s_work_nvlt_76_103","chapterId":"ch_work_nvlt_76","text":"陳徐陵齊國宋司徒寺碑曰：無色之外，方為化城，非想之中，猶稱火宅，若夫眾生無盡，世界無窮，芬若披莲，遠如散墨，善才童子，南行未窥，目連沙門，北遊不見，一一刹土，皆由業緣，萬萬僧祇，終非常樂，天宮蹇產，猶傾四大之風，魔殿崔嵬，終懼三灾之火，朱樓寶塔，辉煥爭華，既義畅中土，道流遐域，顯默同歸，華夷俱慕，自棁石瀨流，始終一槩，恬智交養，三十餘年，春秋八十三，古人雲，道存人亡，法師之謂，凡我門徒，感風徽之緬邈，傷谘悟之永滅，敢以淺見，扬德金石，銘曰：九流依真，三乘歸佛，道往絕跡，慈還接物，孰是發蒙，昭我慧日，攝亂以定，辟邪以律，秦皇雄感，蔽理通情，王孫遍解，遠死滯生，夫子之悟，萬劫獨明，寒暑遞易，悲欣皋壤，秋蓬四轉，春鸿五响，孤松獨秀，德音長往，節有推遷，情無遺想。","sortOrder":103},
  {"id":"s_work_nvlt_76_104","chapterId":"ch_work_nvlt_76","text":"梁元帝莊嚴寺僧旻法師碑曰：夫宏才妙物，雲液之所降生，獨振孤標，倫類之所遠絕，是故隨光燭魏，非折水之恒珍，和璧入秦，豈润山之常寶，僧旻法師，蓋天地之淳精，宇宙之朅器，本姓孫氏，有吳开國大皇帝其先也，法師道藹二儀，德充四海，含春夏之生長，抱日月之貞明，辭旨清新，置言閒遠，千門萬戶，必臻其奧，九部五時，若指諸掌，坦然夷易，豁爾洞开，故緇素結轍，華戎延道，晨風之鬱北林，龍魚之趣深泽，哲人雲逝，指南誰屬，銘曰：永離百非，聞之寂滅，苟雲未树，共歸今轍，方墳結構，伽藍罢設，朱火一潛，青松長列。","sortOrder":104},
  {"id":"s_work_nvlt_76_105","chapterId":"ch_work_nvlt_76","text":"又光宅寺大僧正法師碑曰：昂昂千里，孰辯騏麟之蹤，汪汪萬傾，誰测波澜之际，望之若披雲霧，睹之如觀日月，至乃耆年宿望，蓄思構疑，懸鍾無盡，短兵有倦，猶若分旦望景，履冰待日，莫不傾河註燭，虛往實歸，皇帝革命受圖，補天纫地，轉金輪於忍土，策绀馬於阎浮，逸融方超，圖南輟軌，豈直盡茲相府，署彼義年，方當高步仙階，永編金牒，繁霜凝而且委，松風凄而暮來，悲馬鳴之不反，望龍树而心哀，銘曰：澄月夜虧，清氛且卷，曾峦遠岸，蒼江傍緬。","sortOrder":105},
  {"id":"s_work_nvlt_76_106","chapterId":"ch_work_nvlt_76","text":"梁王筠國師草堂寺智者約法師碑曰：結宇山椒，疏壤幽岫，蓄雲泄雨，霭映房栊，浴日涵星，翻光池沼，震居暇豫，留思幽微，研精經藏，探求法寶，香城實相之談，金河常樂之說，究竟微妙，洞達幽玄，掖庭為道心之宮，華林構重雲之殿，師子之座，高廣於燈王，聽法之筵，眾多於方丈，开寶函之奧典，闡金字之微言，顯證一乘，宣扬三慧，辯才無閡，遊戲神通，莫不皆悟無生，鹹知妄想，隨類得解，俱會真如，銘曰：形在江湖，心超祇鷲，思协風雲，量包宇宙，軒瞰蒼波，窗承翠嶺，須枕煙露，掔持光景。","sortOrder":106},
  {"id":"s_work_nvlt_76_107","chapterId":"ch_work_nvlt_76","text":"梁沈約比丘尼僧敬法師碑曰：立言道往，標情妙覺，置想依空，練心成學，缊日悠長，疏年緬邈，風遷電改，斯理莫违，神有殊適，形無異歸，臨泉結恸，有怆徂暉，松飆轉蓋，山雨披衣，載刊貞軌，永播餘徽。","sortOrder":107},
  {"id":"s_work_nvlt_76_108","chapterId":"ch_work_nvlt_76","text":"梁王僧孺栖玄寺雲法師碑銘曰：眇眇大家，茫茫真朴，多淪愛有，莫辯尘濁，猗欤息心，言高理邈，居之匪絢，得之靡學，刻情幾种，厲想玄覺，且說且定，以披以握，來遵北渚，至依西嶽，西嶽瓘瓘，北渚回波，庭栖弱羽，簷掛輕萝，甘粗衣惡，弃厚安薄，滅意嚣湫，寄心寥廓。","sortOrder":108},
  {"id":"s_work_nvlt_76_109","chapterId":"ch_work_nvlt_76","text":"陳徐陵東陽双林寺傅大士碑曰：自脩禪遠豁，絕粒長斋，非服流霞，若食朝沆，薑原所履，天步可以為儔，河流大屐，神足宜其相比，夫以連城之寶，照庑之珍，野老怪而相捐，工人迷而不識，昔漢皇受道，栾大不臣，魏祖優賢，楊叟如客，河上之老，輕舉臨於孝文，台下之人，高尚加於光武，五胡內贔，蒼鹅之兆未萌，四海橫流，夷羊之牧匪見，滴海未盡其辭，懸河不窮其義，伯陽之德貞，桓紀於瀨乡，仲尼之道高，碑書於魯縣，亦有扬雄弟子，鄭玄門人，俱述清猷，載刊玄石，銘曰：來儀上國，抗禮承明，妙辯無相，深言不生，撞鍾比說，击鼓慚英，樂論天口，誰其與京，乍見仙掌，爰標神足，色艳浮檀，香逾詹匐，噭噭門人，承師若親，寧焚软叠，弗燎香薪，合窟為定，方墳以墟，須弥巨海，变炭扬尘，净土無坏，靈儀自真，何時踴塔，复睹令身。","sortOrder":109},
  {"id":"s_work_nvlt_76_110","chapterId":"ch_work_nvlt_76","text":"隋江總明慶寺尚禪師碑銘曰：百世之上，百世之下，含章隱璞，明真照假，空行已無，希音和寡，不有耆德，誰其繼者，朗月靈懸，高風獨寫。","sortOrder":110},
  {"id":"s_work_nvlt_76_111","chapterId":"ch_work_nvlt_76","text":"又建初寺琼法師碑曰：夫智慧精進，皆曰第一，妙德净名，併稱不二，若乃斡五欲之泥，解六情之網，御寶車之跡，面香城之路，荷持像法，汲引人倫，惟此法師，心力備矣，東山北山之部，貫花散花之句，併編柳成簡，題蒲就業，學非全朔，無待冬書，師夢尹儒，自知秋駕，銘曰：屑屑人世，茫茫大千，欲流心火，意树身田，老驚靈籥，孔惜逝川，三空莫辯，二諦何詮，佛日初昭，慈雲不偏，秋露寂滅，莫系悠然。","sortOrder":111},
  {"id":"s_work_nvlt_76_112","chapterId":"ch_work_nvlt_76","text":"《藝文類聚》　唐·欧陽詢","sortOrder":112},
  {"id":"s_work_nvlt_77_1","chapterId":"ch_work_nvlt_77","text":"卷七十七內典下","sortOrder":1},
  {"id":"s_work_nvlt_77_2","chapterId":"ch_work_nvlt_77","text":"○寺碑","sortOrder":2},
  {"id":"s_work_nvlt_77_3","chapterId":"ch_work_nvlt_77","text":"◇寺碑","sortOrder":3},
  {"id":"s_work_nvlt_77_4","chapterId":"ch_work_nvlt_77","text":"後魏溫子昇寒陵山寺碑序曰：昔晉文尊周，績宣於踐土，齊桓霸世，威著於邵陵，併道冠諸侯，勋高天下，衣裳會同之所，兵車交合之處，寂寞銷沉，荒涼磨滅，言談者空知其名，遙遇者不識其地，然則树銅表跡，刊石記功，有道存焉，可不尚與，永安之季，數鍾百六，天灾流行，人倫交丧，爾朱氏既絕，彼天網，斷茲地紐，祿去王室，政出私門，銅馬競馳，金虎亂噬，九婴暴起，十日併出，破璧毀珪，人物既盡，頭會箕斂，杼柚其空，大丞相渤海王，命世作宰，惟機成務，標格千刃，崖岸萬里，運鼎阿於襟抱，納山嶽於焜懷，擁玄雲以上騰，負青天而高引，鍾鼓嘈囋，上聞於天，旌旗繽紛，下盤於地，壮士懍以爭先，義夫憤而競起，兵接刃於斯場，車错轂於此地，轟轟隱隱，若轉石之墜高崖，蛇良蛇良潏潏，如激水之投深穀，俄而霧卷雲除，冰離葉散，靡旗蔽日，亂轍滿野，楚師之败於柏舉，新兵之退自崑陽，以此方之，未可同日，既考茲沃壤，建此精庐，砥石砺金，瑩珠琢玉，經始等於佛功，製作同於造化，息心是歸，净行攸處，神異畢臻，靈仙總萃，鳴玉鑾以來遊，帶霓裳而至止，翔鳳紛已相嚾，飛龍蜿而俱躍，雖复高天銷於猛炭，大地淪於積水，固以傳之不朽，終亦記此無忘。","sortOrder":4},
  {"id":"s_work_nvlt_77_5","chapterId":"ch_work_nvlt_77","text":"又印山寺碑曰：自結繩運往，觀象代興，禮樂相因，詩書間出，喻是非於一指，論道德於二篇，九流之義遂开，百家之言併作，皆以賦命有遭隨，攝養致夭寿，愛惠起於吉凶，情伪動於利害，雖改張羅之咒，未易衅鍾之牲，因果之業未申，感應之途猶蔽，是以脩短有命，子夏論之而未詳，報施在天，史遷言之而未悟，大丞相渤海王，膺嶽渎之靈，感辰象之氣，直置與蘭桂齊芳，自然共珪璋比絜，加以體備百行，智周萬象，道兼語嘿，思極天人，固以兆雲非虎，自懷公辅之德，世稱臥龍，實在王佐之器，道足以濟天下，行足以通神明，表立人之上才，含廣途之大量，永安之末，時各異謀，蜂蠆有毒，豺狼反噬，彀弩臨城，抽戈犯跸，世道交丧，海水群飛，既而蒼龍入隱，白虎出見，命世有期，匡時作宰，拯沉溺以援手，涉波澜而濡足，懸曒日於焜懷，起大風於衿袖，動之以仁義，行之以忠貞，附之者影從，應之者响起。","sortOrder":5},
  {"id":"s_work_nvlt_77_6","chapterId":"ch_work_nvlt_77","text":"又大覺寺碑曰：維天地开辟，陰陽轉運，明則有日月，幽則有鬼神，初地遼遠，末路悠長，自始及終，從凡至聖，積骨成山，祗劫莫數，垂衣拂石，恒河難計，及冠日示夢，蒙羅見謁，應世降神，感物开化，顏如滿月，心若盈泉，體道獨悟，含靈自晓，居三殿以長想，出四門而永慮，聲色莫之留，榮位不能屈，道成树下，光屬天上，变化靡窮，神通無及，置須弥於葶苈，納世界於微尘，辟慈悲之門，开仁寿之路，殛煩惱於三涂，濟苦難於五濁，非但化及天龍，教被人鬼，固亦福霑行雁，道洽遊魚，但群生無感，獨尊罢應，雜色照烂，諸山搖動，布金沙而弗受，建寶蓋而未留，遂上微妙之台，永升智慧之殿，而天人慕德，像法興靈，圖影西山，承光東壁，主上乃據地圖，攬天鏡，乘六龍，朝萬國，牢籠宇宙，襟帶江山，道濟橫流，德昌頹歷，四門穆穆，百僚師師，乘法舡以径度，駕天輪而高舉，神功寶業，既被無邊，鸿名懋實，方在不朽，祗掌措言，雖不盡意，執筆書事，其能已乎。","sortOrder":6},
  {"id":"s_work_nvlt_77_7","chapterId":"ch_work_nvlt_77","text":"又定國寺碑序曰：蓋兩儀交運，萬物併生，始自苦空，終於常樂，而緣障未开，業尘猶擁，漂淪欲海，顛墜邪山，雖复光華併於日月，術數窮於天地，有扶危定傾之力，為濟世夷難之功，登涂山而未歸，遊建木而不反，併馳於苦樂之境，皆入於生死之門，幽隱長夜，未睹山北之燭，沉迷遠路，詎見司南之機，昔日先民，雖雲善誘，尚習蓋纏，未能解脱，至如八卦成象，示之以吉凶，百藥為医，导之以利害，衣食有業，民免飢寒之忧，水土既平，人無墊溺之患，斯誠事周於世用，功濟於生民，不論過去之因緣，詎辯未來之果報，惟無上大覺，獨悟玄機，應現讬生，方便开教，聖靈之至，無复等級，威神之力，不可思議，動三乘之駕，汎八解之流，引諸子於火宅，渡群生於海岸，自一音輟响，双树潛神，智慧雖徂，象法猶在，光照金盤，言留石室，遍諸世界，鹹用歸仰。","sortOrder":7},
  {"id":"s_work_nvlt_77_8","chapterId":"ch_work_nvlt_77","text":"梁王僧孺中寺碑曰：夫玉律追天，故躔次之期不变，緹室候景，則發斂之氣罔逾，是以忘言种覺，絕累於後心，寄像聲形，啟機於前教，兼真假之双燭，均空有而兩忘，蘊三明而過十地，圓萬行而包四等，道周百亿，化起大千，奖导群有，滋濡萬類，是用發廣大心，吐微妙理，將同商主，取喻医王，开方便門，示真實相，固以濯之慈水，銷以慧刀，永言六趣，用均一子，中寺者，晉太元五年，會稽王司馬道子之所立也，斜出旗亭，事非湫隘，傍超壁水，望異狹斜，天監十五年，上座僧慈等，更楑日禘架，赫然霞立，信以填金可埒，引繩斯擬，寫妙金樓，模麗琼闕，岧峣偃蹇，故三休而可至，窈窕周流，方中宿而斯盡，萬楹百栱，合沓相持，繡棁王題，分光爭映，燭龍夭矯，將舉复宛，威鳳铿锵，如鳴更戢，旁攀鏤槛，斜登钿砌，煜爚金鋪，玲瓏綺欂，無風自响，不拂而净，〈目冗〉々肅肅，信息心之勝地，穆穆愔愔，固忘想之嘉所，銘曰：玄黃雖弭，權舆未测，生滅相輪，成坏不極，箧蛇爭赴，藤鼠無息，情尘莫舍，心火方赫，是用三明，寔开五力，湛寂無方，示現多所，踟蹰吉树，殷勤禪渚，斯道誰匡，蒸哉我王，施逾寶鉢，供等檀床，萧宮改構，梵宇方壮，階飛瑞采，地起泥香，日流閃烁，風度清锵，道逾厥極，固與天長。","sortOrder":8},
  {"id":"s_work_nvlt_77_9","chapterId":"ch_work_nvlt_77","text":"梁任孝恭多寶寺碑銘曰：寶傳茲日，法像斯時，瞻風候景，石陛开基，准繩秋子，取則迦夷，業隆千載，道盛一期，上當星紀，下接莲峰，還瞻朱閣，却背青松，朝雲暧暧，夕霧溶溶，階通獸跡，径有禽蹤，衣移峻嶽，錫叩飛泉，土木綈錦，玉石雕镌，寶階雲構，綺壁霞鮮，莲舒藻井，芰繞蘭椽，法堂每喧，禪室恒靜，藏韜仙說，台含佛影，葉下秋林，煙生春嶺。","sortOrder":9},
  {"id":"s_work_nvlt_77_10","chapterId":"ch_work_nvlt_77","text":"梁劉孝綽栖隱寺碑曰：开方便門，示真實相，置甘露室，遵甘露津，苦語软言，隨方弘訓，俯心降跡，逐物重輕，中枝小葉，各隨業根，愍其四流五結，有來而不散，八慢九邪，一淪而莫晓，如彼医王，等之藥树，去聖茲遠，思聖茲深，誠敬所先，是歸龛廟，自妙法東註，寶化西漸，公卿貴仕，賢哲伟人，莫不嚴事招提，歸仰慧覺，欲使法燈永傳，勝因長久，銘曰：給孤焚荡，善勝崩淪，堂堂宗匠，克紹慧因，地雖舊域，其宇惟新，召棠且思，羊碑猶泣，况我仁祠，義逾生立，遺愛伊何，形於南邑，亦有庶民，經始攸急，珠殿連雲，金層辉景，衢交達巷。門臨树屏，五居推妙，三空愧靜，銘施柱侧，記法窟前，孰雲千載，餘跡方傳，敢宣重說，敬勤雕镌，芬域未滅，斯文在旃。","sortOrder":10},
  {"id":"s_work_nvlt_77_11","chapterId":"ch_work_nvlt_77","text":"北齊邢子才景明寺碑曰：九土殊方，四生舛類，昏識異受，脩短共時，德表生民，不救太山之朽壤，義同列辟，豈濟栾水之淪胥，漂滷倒戈之势，浮江架海之力，孰不曠息相催，飛馳共盡，泡沫不足成喻，風電詎可為言，而皆遷延愛欲，馳逐生死，眷彼深尘，迷茲大夜，坐積薪於火宅，負沉石於苦海，結習靡倦，忧畏延長，身世其猶夢想，榮名譬諸幻化，未能照彼因緣，體茲空假，袪洗累惑，擯落尘埃，苦器易彫，危城難久，自發跡有生，會道無上，劫代緬邈，朕跡遐長，草木不能况，尘沙莫之比，及日晷停流，星光輟運，香雨旁註，甘露上懸，降靈迦衛，擁跡忍土，智出須弥，德逾大地，道尊世上，義重天中，銘曰：大道何名，至功不器，理有罔適，法無殊致，能自讬生，降體凡位，士覺如遠，一念斯至，德尊三界，神感四天，川流自斷，火室不燃，衣生寶树，座踴芳莲，智固有極，道畅無邊。","sortOrder":11},
  {"id":"s_work_nvlt_77_12","chapterId":"ch_work_nvlt_77","text":"又併州寺碑曰：夫至道密微，無跡可睹，神功感應，有理斯存，雖慧日已照，而大夜莫晓，香雨時流，而深尘未息，曠劫悠緬，歷代遐長，眇眇世羅，無能免其一目，汎汎欲網，孰敢解其三面，自大教遷流，行於中土，希向之士，煙踴波屬，洹沙未足為言，積尘所不能喻，皆去出没生死之河，浮沉愛育之海，未有矯然獨悟，脱落身名，望彼岸而攸往，汎寶舡而利涉。","sortOrder":12},
  {"id":"s_work_nvlt_77_13","chapterId":"ch_work_nvlt_77","text":"陳徐陵孝義寺碑曰：臣聞道階八地，猶見後妃，原生千佛，無匪賢聖，汲引之義雖同，隨機之感非一，至如妫汭有禮，皇源所以前興，周女斯歸，陳宗所以流慶，大矣哉，神基帝系，淑聖重光者也，慈訓太後，德佐初九，道暉上六，居天上天中之極，處大任大姒之尊，蘋藻之化斯深，葛覃之風弥遠，皇帝膺茲上聖，契彼援神，愛敬在乎一人，德教形乎四海，是以明星皎皎，流半月之光，甘露团团，洒如飴之味，嘉禾自秀，浪井恒清，天降徵祥，日聞書府，自大明紹運，神武應期，至道傍通，無思不格，戊己校尉，西關玉門，伏波將軍，南表銅柱，方使三千世界，百亿須弥，同望飛輪，共禀玄德，元嘉三年正月二十一日詔旨，仰惟聖德，方被兆民，乃敕有司，改東成里為孝義里，昔岱山徙號，重華著其受終，德水移名，秦人表其嘉運，豈若盡在舆地，書茲里門，仰述天經，光臨父母，臣陵稽首，乃作銘曰：原此良因，宜資貴親，三乘併策，四梵為賓，绀殿安坐，莲花養神，燈前禮佛，地後邊身，併濟含識，鹹歸至真，國家隆盛，同响遐慶，謹勒丰碑，陳其舞詠。","sortOrder":13},
  {"id":"s_work_nvlt_77_14","chapterId":"ch_work_nvlt_77","text":"隋江總大莊嚴寺碑曰：蓋聞僧伽水濱，波斯創以禪地，醍醐山顶，舍那肇其梵域，此乃往劫之勝因，上方之妙范，於是俯察地势，懸之以水，仰惟星極，揆之以日，百堵鹹作，千坊洞啟，前望則紅尘四合，見三市之盈虛，後睇則紫閣九重，連双闕之耸峭，加以園習歡喜，水成功德，池溢甘露，不因玉掌，树搖音樂，無待金奏，薰爐夜爇，遙來海岸之香，法鼓晨讙，非動泗濱之石，擢金茎表，跨八萬之俱成，界道銀繩，面四衢而拓製，廁壁缀珠，凌丹霞而結宇，雕光鏤采，望紫極而开軒，俯看驚電，影彻琉璃之道，遙拖宛虹，光遍水精之域，層楹刻桶，［疑當作桷。］風伯走而未升，靈橑飛甍，雨師攀而不逮，銘曰：灼烁金茎，崔嵬銀表，翔鶤仰翥，威鳳靈矯，木密聯綿，香泥缭繞，日圖簷外，荷披棟杪，翠落陰虬，珠填陽鳥，高僧累萃，硕學滋多，弘宣方等，博綜围紘，皆傷寸晷，併悟尺波，式旌鏤碣，無待雕戈，礻票年刹土，比數洹河。","sortOrder":14},
  {"id":"s_work_nvlt_77_15","chapterId":"ch_work_nvlt_77","text":"【放生碑】梁元帝荆州放生亭碑曰：魚從流水，本在桃花之源，龍處大林，恒捻浮雲之路，豈謂陵陽垂鉤，失雲失水，莊子懸竿，吞鉤吞餌，雖复玄龟夜夢，終見取於宋王，朱鷺晨飛，尚張羅於漢後，譬如黃雀伺蝉，不知隨彈應至，青鹯逐兔，詎識槓鼎方前，北海之餐鸚鵡，未始非人，西王之使傳信，誰雲賤鳥，故知魚鳥一觀，俱在好生，欲使金床之雁，更及衡陽之侣，雪山之鹿，不充食苹之宴。","sortOrder":15},
  {"id":"s_work_nvlt_77_16","chapterId":"ch_work_nvlt_77","text":"【眾食碑】陳徐陵長幹寺眾食碑曰：昔炎皇肇訓，稷正脩官，信矣民天之言，誠哉國寶之義，自非道登正覺，安住於大般涅槃，行在真空，深入於無為般若，則菩薩應化，鹹同色身，諸佛净土，皆為揣食，證常住者，爰訖乳糜，補尊位者，猶假香飯，亦有三心未滅，七反餘生，應會天宮，就斋龍海，况复才居地轉，或憩珠庭，固以皆种仙禾，併資靈粟者矣，法師常原以智慧火，燒煩惱薪，普施眾生，同餐甘露，况复安居自恣，硕學高年，或次第於王城，猶栖遑於貧里，迦留乞餅，苦用神通，須提請飯，致貽詞貴，於是思營眾業，原造坊厨，庶使應供之僧，皆同自然之食，升堂濟濟，無勞四辈之類，高廪瓘瓘，恒有千食之備，其外鐵市銅街，青樓紫陌，辛家黑白之里，甲第王侯之門，莫不供施相高，資储轉眾，法師善巧方便，漚和舍羅，教授滋生，隨年增長，假使桑林不雨，瓠水扬波，猶厭稻粱，永無飢乏，加以五鹽具足，七菜芳软，餅類天厨，果同香树，羹鼎之大，殷王未逢，糜镬之深，齊都非擬，崑吾在次，皆鳴鷲嶺之鍾，暘穀初升，同洗龍池之鉢。","sortOrder":16},
  {"id":"s_work_nvlt_77_17","chapterId":"ch_work_nvlt_77","text":"【銘】梁簡文帝釋迦文佛像銘曰：至矣調御，行備智周，滿月為面，青莲在眸。","sortOrder":17},
  {"id":"s_work_nvlt_77_18","chapterId":"ch_work_nvlt_77","text":"又弥紘佛像銘曰：玉莲水开，銀花树落，惟聖降神，拯彼沉漠。","sortOrder":18},
  {"id":"s_work_nvlt_77_19","chapterId":"ch_work_nvlt_77","text":"又維衛佛像銘曰：灼灼金容，巍巍滿月，永被人天，常留花窟。","sortOrder":19},
  {"id":"s_work_nvlt_77_20","chapterId":"ch_work_nvlt_77","text":"又式佛像銘曰：影生千葉，花成四柱，塔象单留，龛童双舞。","sortOrder":20},
  {"id":"s_work_nvlt_77_21","chapterId":"ch_work_nvlt_77","text":"又迦葉佛像銘曰：慧雨自垂，仁風永扇，照曜白毫，半容月面，惡因有滅，善燈無变。","sortOrder":21},
  {"id":"s_work_nvlt_77_22","chapterId":"ch_work_nvlt_77","text":"又釋迦文佛像銘曰：心珠可瑩，智流方普，永变身田，長無沙滷。","sortOrder":22},
  {"id":"s_work_nvlt_77_23","chapterId":"ch_work_nvlt_77","text":"梁安寺釋迦文佛像銘曰：帝為知仰，皆規面象，敬模螺發，式圖輪掌，信根有五，覺枝雲七，仰福靈祇，上生兜率。","sortOrder":23},
  {"id":"s_work_nvlt_77_24","chapterId":"ch_work_nvlt_77","text":"吳郡石像銘曰：七盤員鼓，先奏盛唐之歌，百味椒漿，屢上東皇之曲，於時微風送棹，淑景浮波，雲舒蓋而未移，浪开華而不喷。","sortOrder":24},
  {"id":"s_work_nvlt_77_25","chapterId":"ch_work_nvlt_77","text":"梁元帝梁安寺刹下銘曰：阿閣峞｛山羅｝，洞房窈窕，似靈光之金扇，類景福之銀鋪，垂琬琰之文璫，飾琅玕之仙寶，神童戾止，亟連翩於威鳳，薩埵來遊，屢徘徊於绀馬，有識之所虔仰，無著之所招提，觀慧樓而下拜，望天街而興善，辭曰：尘沙無始，造色無先，飛蛾不息，萦蠶自纏，箧蛇未斷，藤鼠方緣，苦流長汎，愛火恒燃，髻珠孰晓，懷寶詎宣，挺茲靈覺，時惟天仙，真籍表聖，化乳稱權，寶刹千道，高翻四懸，鳳樓含日，龍台吐煙，紫山翠羽，紅水青莲，雪宮月殿，晨暉夜圓，宵長梵响，風遠鍾傳，仙衣有拂，靈刹無遷。","sortOrder":25},
  {"id":"s_work_nvlt_77_26","chapterId":"ch_work_nvlt_77","text":"梁沈約光宅寺刹下銘曰：聖心留愛閒素，遷負南郭，義等去酆，事均從鎬，及克濟橫流，膺斯寶運，命帝閽以廣辟，即太微而為宇，既等漢高，留連於丰沛，亦同光武，眷恋於南陽，所以永留聖跡，垂之不朽，皇帝乃啟閶阖，造舟淮涘，接神飆而動驂，越浮梁而径度，芝蓋容與，翠華葳蕤，下輦停跸，躬展誠敬，辭曰：八紘悠闊，九有荒茫，靈聖底止，鹹表厥祥，寿丘叆叆，電繞枢光，周原膴膴，五緯入房，自茲遐敻，名在處亡，安知若水，莫辨窮桑，自天攸縱，於惟我皇，即基昔兆，為世舟航，重簷累構，迥刹高驤，土為净國，地即金刚。","sortOrder":26},
  {"id":"s_work_nvlt_77_27","chapterId":"ch_work_nvlt_77","text":"瑞石像銘曰：素毫月舉，騰光於梵室，妙趾神行，布武於椒殿。","sortOrder":27},
  {"id":"s_work_nvlt_77_28","chapterId":"ch_work_nvlt_77","text":"梁劉孝儀平等刹下銘曰：香薪已燎，花叠盡然，頻果絕其软言，綿毫收其廣照，绀鉢遺采，讬慕所依，紅爪餘暉，申悲是寄，因使金表爭構，玉刹競脩，豈止天界飾其四園，龍宮陳其七寶，树似菴林，峰疑鷲色，孕吐仙霧，涌瀨靈泉，燕室緣雲，精庐切製，漢兼秘殿，宋美御房，羲和假道於罘罳，翔鸞回翼於飛棟，建章厭勝，未及雕砻，甘泉避暑，豈窮輪奐，槛缀玫瑰，階填粟玉，絡以如意，飾用沉檀，火齊勝明，燭銀颺采，釋梵奪其身光，日車貶其輪照，辭曰：惟茲寶塔，妙跡可傳，盤稱鄴境，樓美湆川，双龍虛繞，九鳳徒懸，豈如神刹，耿介凌煙，珠含魄月，幡垂净天，寶铎夜响，銀地朝鮮，簷栖迥霧，砌卷香莲，翻蠡下梵，墜鶴歸仙，恒沙扰扰，世界綿綿，踐茲勝影，祛彼蓋纏。","sortOrder":28},
  {"id":"s_work_nvlt_77_29","chapterId":"ch_work_nvlt_77","text":"陳虞荔梁同泰寺刹下銘曰：戒香芬馥，氣勝懷蘭，智劍陆離，威逾交軋，敞慧日於重雲，凌法流於巨海，嚴此三駕，用拔畏涂，漾彼六舟，拯諸淪溺，但以一人入道，波旬之宮已震，十地弘心，毒龍之灾競起，重栾布護，積栱崚嶒，神仙嶽嶽，俯雕槛於霞外，寶铎锵锵，韻釣天於雲表，雷雨杳冥而未半，扶桑光朏而先明，迨亭峻極，特立千刃，灼烁峥嵘，光鏡八表，若日殿之燭大空，似星宮之構辰極，辭曰：層台複陆，廣殿穹崇，涂金钿玉，映日疏風。","sortOrder":29},
  {"id":"s_work_nvlt_77_30","chapterId":"ch_work_nvlt_77","text":"陳徐陵四元［全陳文十作無。］畏寺刹下銘曰：皇帝升乾行於九五，辟世界於三千，神人开錦石之山，小國獻栴檀之柱，乃命將作，脩成梵宮，複殿重軒，凌霄負漢，慈訓宮朝文母，［句有脱文。］协道方祇，鍾愛東平，更逾燕後，若夫外家問訊，遙疑緣構，［疑當作绿褠。］御者衣服，曾無采繡，鹹傾寶飾，用構支提，僧若檀林，寺同祗苑，辭曰：寶蓋王子，金輪讬生，皇家茂戚，抑有齊名，業水餘润，灾風所驚，徒悲馬角，孰獻雞鳴，柰苑初筑，菴園重成，金台日麗，玉殿雲平，梵眾朝禮，天歌夜清，蜂疑畫壁，雀避雕楹，福履斯大，皇基永禎。眾生不盡，寶刹無傾。","sortOrder":30},
  {"id":"s_work_nvlt_77_31","chapterId":"ch_work_nvlt_77","text":"又報德寺刹下銘曰：昔者明王大孝，感動神祇，助月致景星之祥，非煙流慶雲之色，然而嚴敬之道，惟事盡於配天，明發之懷，誠不過於饗帝，豈如以梵宮之樂，資乎廟堂，净土之因，歸於圓寢，雖复青雲谯郡之境，碧泉舂陵之乡，上幼懷凝重，未曾遊陟，年將志學，即事登庸，宣力淮潯，屬有嘉夢，其夢也，畢陌弘敝，桥山屈盤，氣象靈長，風煙騰溥，使队双表，其高百尋，左則青龍蟠蜿，右則白虎蹲踞，軒轅之駕，譬婉婉而多慚，吳王之墳，状耽耽而非擬，有人指其地雲，此是國陵，自爾迄永定初，其間二十有餘年，至歲紀頻移，崇塋乃作，觀其山川形势，王相徵圖，瞻拜高峦，宛如前夢，大矣哉，孝悌之至，通於神明者欤，銘曰：壮矣金表，傍依壖垣，高連采霓，極睇翔鶤，梵妓宵唱，雲花晝翻，三心斷縛。六道除怨，趙夢天樂，秦遊帝閽，王靈在上，巨勝奚論，福被群品，俱排大昏，皇家七百，於萬維孫。","sortOrder":31},
  {"id":"s_work_nvlt_77_32","chapterId":"ch_work_nvlt_77","text":"陳江總懷安寺刹下銘曰：四聰睿後，萬行了因，運光玉鏡，道茂金輪，爰構靈刹。地跡重闉，迎風雲表，承露天津，飛甍〈山截〉〈山薛〉，累棟嶙峋，護持七眾，警衛百神，筹銷草木，劫盡沙尘，支提永固，福業恒新，变易東海，長久北辰。","sortOrder":32},
  {"id":"s_work_nvlt_77_33","chapterId":"ch_work_nvlt_77","text":"鍾銘曰：凫氏之匠，狃陽之銅，圖栾鑄鑮，刻獸镌虫，聲飛雪里，韻切唇中，遙符玉律，遠雜金風，朝驚鷲嶺，夜動龍宮，冀凭慧業，冥感神功，百非洗荡，萬善招通，長如五净，永證三空。","sortOrder":33},
  {"id":"s_work_nvlt_77_34","chapterId":"ch_work_nvlt_77","text":"鍾銘曰：篆間鎔刻，栾上雕镌，聲齊法鼓，响逸鳴楗，舟移巨壑，火坏初禪。","sortOrder":34},
  {"id":"s_work_nvlt_77_35","chapterId":"ch_work_nvlt_77","text":"優填像銘曰：如花譬象，若火疑龍，毫光此遇，法相今逢，眸雲齒雪，月貌金容，大仙下降，避席為恭。","sortOrder":35},
  {"id":"s_work_nvlt_77_36","chapterId":"ch_work_nvlt_77","text":"北齊邢子才文襄王帝金象銘曰：妙形難象，至理希詮，形之所及，理亦在焉，悟茲空假，勞此蓋纏，式圖往秘，用結來緣，丹青併飾，金玉同镌，神儀內瑩，寶相外宣，圓光照耀，映被無邊，靈應盻响，感發大千，鍾福旒纊，其永如天，歸慶怙恃，寿等南山，凡厥親類，宜其永年，歸誠妙覺，標志上玄，讬銘斯在，曠劫方傳。","sortOrder":36},
  {"id":"s_work_nvlt_77_37","chapterId":"ch_work_nvlt_77","text":"獻武皇帝寺銘曰：惟睿作聖，有縱自天，匡國庇民，再造區夏，功高伊呂，道邁桓文，雖住止域中，而神遊方外，影响妙法，咫尺天人，晓夜自分，不勞雞鶴之助，六時靡惑，非待壶箭之功，永寄將來，傳之不朽，辭曰：用分行坐，以敦戒行，苦罪祈福，傲很成敬，萬國鹹亨，一人有慶，方傳自久，是用成詠。","sortOrder":37},
  {"id":"s_work_nvlt_77_38","chapterId":"ch_work_nvlt_77","text":"【墓志】梁簡文帝同泰寺故功德正智寂師墓志銘曰：峰頹朽壤，波逝江潭，山川若此，人何以堪，亦生亦滅，如壑如舟，千齡俱盡，萬古誰留，惟茲大士，才敏學優，幼捐蹈火，早去吞鉤，法雷能响，懸河必詶，辯才可匹，妙德難儔。","sortOrder":38},
  {"id":"s_work_nvlt_77_39","chapterId":"ch_work_nvlt_77","text":"宋姬寺慧念法師墓志銘曰：電逝生危，舟沉道滅，石折亡儒，星开殒哲，是曰人龍，亦號僧象，慧氣素昭，英賢夙上，善渡愛河，能褰欲網，如彼高山，法徒斯仰，如彼澄波，不测深廣。","sortOrder":39},
  {"id":"s_work_nvlt_77_40","chapterId":"ch_work_nvlt_77","text":"甘露鼓寺敬脱法師墓志銘曰：岌岌緣假，昏昏大夢，六尘遠飛，四流長控，猗嗟大士，慧舟法棟，早擅人龍，夙摽威鳳，善堂間構，燈王布席，辯河流水，辭峰積石，寂寥兩树，悠漫三泉，神明何讬，暗石空傳。","sortOrder":40},
  {"id":"s_work_nvlt_77_41","chapterId":"ch_work_nvlt_77","text":"湘宮寺智蒨法師墓志銘曰：嗟爾名德，超然有暉，五尘夙離，三脩九依，戒珠靡缺，忍鎧無违，智燈含影，慧駕馳騑，若韜山金，如苞海寶，德邁西河，聲逾東道，伊昔傾蓋，於彼朱方，不期而遇，襄水之陽，掩此方墳，悠哉泉下，鬱鬱翠微，遼遼平野，薪盡火滅，歸真息假。","sortOrder":41},
  {"id":"s_work_nvlt_77_42","chapterId":"ch_work_nvlt_77","text":"净居寺法昂墓志銘曰：筱簜含耸，蘭荪表质，甘露已凝，智泉斯溢，頃辔中衢，息棹脩渚，隙陋白駒，藤緣黑鼠，同志酸傷，交朋哀楚。","sortOrder":42},
  {"id":"s_work_nvlt_77_43","chapterId":"ch_work_nvlt_77","text":"梁邵陵王楊州僧正智寂法師墓志銘曰：緣城虛假，欲海漂深，三相難久，八風易侵，寔惟上德，為龍為光，凝情內瑩，神采外扬，微言折角，精義解颐，有同商主，譬彼名医，妙法方永，慧水停滋，五通軫慕，四眾增悲。","sortOrder":43},
  {"id":"s_work_nvlt_77_44","chapterId":"ch_work_nvlt_77","text":"梁陆倕志法師墓志銘曰：法師自說姓朱，名保志，其生緣桑梓，莫能知之，齊故特進吳人張緒，興皇寺僧釋法義，併見法師於宋太始初，出入鍾山，往來都邑，年可五六十歲，未知其異也，齊宋之交，稍顯靈跡，被發徒跣，負杖挟鏡，或徵索酒肴，或數日不食，豫言未兆，懸識他心，一時之中，分身數處，天監十三年，即化於華林園之佛堂，先是忽移寺之金刚像，出置戶外，語僧眾雲，菩薩當去，爾後旬日，無疾而殒，沉舟之痛，有切皇心，殯葬資須，事丰供厚，望方墳而陨涕，瞻白帳而拊心，爰詔有司，式刊景行，辭曰：欲化毗城，金粟降靈，猗欤大士，權跡帝京，緒胄莫詳，邑居罕見，譬彼涌出，猶如空現，哀茲景像，愍此風電，將导舟梁，假我方便，形煩心寂，外荒內辯，觀往测來，睹微知顯，動足墟立，發言風偃，業窮難詔，因謝弗援，慧雲晝歇，慈燈夜昏。","sortOrder":44},
  {"id":"s_work_nvlt_77_45","chapterId":"ch_work_nvlt_77","text":"【表】梁簡文帝上大法頌表曰：臣聞至理隆而德音闡，成功臻而頌聲作，天上天下，妙覺之理獨圓，三千大千，無緣之慈普被，慧舟匪隔，法力無根，泽雨無偏，心田受润，具以九围共溺，併識歸涯，萬國均夢，一日俱晓。","sortOrder":45},
  {"id":"s_work_nvlt_77_46","chapterId":"ch_work_nvlt_77","text":"【啟】齊王融謝竟陵王示法製啟曰：翔慧燭於昏涂，洒法水於尘路，至夫澄心洗累之規，莊情束影之製，解網出界之訓，滅惑净照之旨，固已行首霜威，字端風厲，信可以糟滓五書，糠芬百氏，升罩聃周，筲竽尼旦，所謂窥七泽而狹潢汙，登太山而小天下。","sortOrder":46},
  {"id":"s_work_nvlt_77_47","chapterId":"ch_work_nvlt_77","text":"法門頌啟曰：伏以迦文啟聖，道冠百靈，常住置言，理高萬乘，神儀挺發，非望雲就日所追，睿識獨尊，豈生明弱言能企，鹿苑金輪，弘汲引以濟俗，鶴林双树，顯究竟以开氓，惜乎祇園滅影，鷲嶽淪光，微辭既遙，大義如缀，自不宣遊十地，擁接九區，豈有导覺水之塞源，拯法雲於落仞，明公覽四諦之必空，悟三業之暫有，應務屈己，則仁兼旦奭，隨方申道，則慧一净名，驅率土於福林，入蒼黔於正術。","sortOrder":47},
  {"id":"s_work_nvlt_77_48","chapterId":"ch_work_nvlt_77","text":"梁昭明太子謝敕赍銅造善覺寺塔露盤啟曰：燥濕無变，九布見奇，寒暑是宜，六律成用，况复神龍負子，光斯極妙，金鳥衔帶，飾慈高表，函穀恥其詠歌，臨淄惡其祥應，陽燧含影，還避日輪，甘露入盤，足稱天酒。","sortOrder":48},
  {"id":"s_work_nvlt_77_49","chapterId":"ch_work_nvlt_77","text":"梁簡文帝敕聽從舍利入殿禮拜啟曰：臣緯啟，不生羽翼，無假神通，身升净土，高排閶阖，足踐莲花，方茲非喻，行躡寶梯，比斯未重。","sortOrder":49},
  {"id":"s_work_nvlt_77_50","chapterId":"ch_work_nvlt_77","text":"答同泰寺立刹啟曰：竊以寶塔天飛，神龛地踴，豈惟昔代，复見茲辰，嘉彼百靈，欣斯十善，雖复紫煙旦聚，比此未儔，朱光夜上，方今知陋。","sortOrder":50},
  {"id":"s_work_nvlt_77_51","chapterId":"ch_work_nvlt_77","text":"東宮上掘得慈覺寺鍾啟曰：竊以白亭舊室，絕顯禎祥之氣，闕里故堂，暫聞鍾石之响，猶复存諸良史，汗彼篆素，豈如杏梁遺飾，回成绀殿，椒墀昔處，仍構寶階，啟彝鍾於殊里，記靈文於福地，雖魏廟出玺，魯祠現璧，固以推茲孝感，惡此禎契，將郭令鄙其开金，羊田陋其產玉，豈宜季武庭树，愧韓起之譽，蜀相宅基，慚孝安之碣，伏惟覽啟增思，撫瑞深悲，恸切视奁，哀逾封箧。","sortOrder":51},
  {"id":"s_work_nvlt_77_52","chapterId":"ch_work_nvlt_77","text":"梁元帝謝敕送齊王瑞像還啟曰：臣聞非晦非明，法身凝寂，有感有見，渴仰赴幾，伏惟陛下，百姓為心，宜觀种覺，十方皆見，普照王畿，將使化行南國，乃睠西顧，江水安流，大川利涉，鮮雲叆叇，暫掩晨離，甘雨霏微，猶藏宿霧，高明可仰，與天花而俱落，清梵騰空，雜埙篪以相韻，顶禮最勝，敬謁法王，瞻彼堵牆，不足為喻，立處針鋒，弗雲易擬，臣身持净戒，心抃法流，接足道周，膜拜路左，得未曾有，喜躍充遍。","sortOrder":52},
  {"id":"s_work_nvlt_77_53","chapterId":"ch_work_nvlt_77","text":"梁邵陵王答皇太子示大法頌啟曰：茲鋒鬱壮，妙辯縱橫，慧舍雨雪，智包三藏，故五時之說既陳，七處之禮斯聚，啗般若之妙源，顯無生之真諦，心註八流，意含五忍，能使六地震動，四花普雨，折木蓋鱗，开羅散翮，香鳥步花，馴遊於雲圃，瑞雀飛環，翔舞於風前，高門洞啟，不因銅馬之飾，寶殿霞开，寧假鳳皇之瑞，雖复長卿壮辭，曾何足數，子雲妙句，比此蔑如，梁沈約上錢隨喜光宅寺啟曰：伏惟中陽故里，舂陵舊居，夷漫涤荡，曾無遺筑，若使人教早流，法尊二代，开塔白水，树刹枌榆，可以傳美垂跡，迄今不朽。","sortOrder":53},
  {"id":"s_work_nvlt_77_54","chapterId":"ch_work_nvlt_77","text":"送育王像併上錢燭等啟曰：竊以無名無色，理絕應感，不身即身，猶觀原力，惟原燈明道成，長為八喜之侣，菩提無上，永廁千子之蹤。","sortOrder":54},
  {"id":"s_work_nvlt_77_55","chapterId":"ch_work_nvlt_77","text":"臨終勸加篤信啟曰：抱疾弥留，迄今未化，形神欲離，窮楚盡毒，據刀坐劍，比此為輕，仰惟深入法門，厲茲苦節，內矜外恕，寔本天懷，伏原复留聖心，重加推廣，微臣臨涂，無复遺恨，雖慚也善，庶等哀鳴。","sortOrder":55},
  {"id":"s_work_nvlt_77_56","chapterId":"ch_work_nvlt_77","text":"謝齊竟陵王示華嚴瓔珞啟曰：竊以六詩雨散，百氏雲興，或事止襃刺，或義单小辯，莫不雕風煙之氣状，流日月之英華，明公該玄體妙，凝神宙表，荫法雲於六合，扬慧日於九天，因果悟其初心，菩提證其後業，陟無生之遠岸，汎正水之安流，爰建三遠十號之尊，崇四辯八聲之妙，極法身與金刚齊固，常住與至理俱存。","sortOrder":56},
  {"id":"s_work_nvlt_77_57","chapterId":"ch_work_nvlt_77","text":"【序】梁武帝小，［高僧傳八作寶。］亮法師涅槃疏序曰：非言無以寄，言即無言之累，累言則可以息言，言息則諸見競起，所以如來，乘本原以讬生，現慈力以應化，離文字以設教，忘心相以通道，欲使珉玉累价，涇渭分流，佛性开其本有之源，涅槃明其歸極之宗，非因非果，不起不作。","sortOrder":57},
  {"id":"s_work_nvlt_77_58","chapterId":"ch_work_nvlt_77","text":"梁元帝法寶聯璧序曰：竊以觀乎天文，日月所以貞麗，觀乎人文，藻火所以昭發，况复玉毫朗照，出天人之表，金牒解空，生文章之外，雖境智宜焉，言語斯絕，詩歌作焉，可略談矣，粵乃書稱湯語，篇陳夢說，昔則王畿居毫，今則帝業惟扬，功施天下，我之自出。","sortOrder":58},
  {"id":"s_work_nvlt_77_59","chapterId":"ch_work_nvlt_77","text":"梁沈約內典序曰：尚矣哉，群生之始也，義隱三藏之外，事非二乘所窥，自併識同饹，隨緣受業，人天異軌，翾動殊貫，苦樂翻回，愚智相袭，莫不火宅輪鶩，人寿飆遷，以寸陰之短晷，馳永劫之延路，情靈起伏，萬緒千名，能仁權跡四門，既非悟道之始，假滅双树，寧有薪盡之實，而天人瞻慕，仿佛興情，范金琢玉，圖容寫状，靈姿炫日，寶刹凌雲，或設鬼神之功，或資體腦之力，製非人匠，寶以合成，莫不龍章八彩，琼華九包，墳典丘素，域中之史策，本起下生，方外之紀傳，統而為言，未始或異也，而經記繁廣，條流舛散，一事始末，衰［○疑當作袠。］異卷分，或辭義離斷，或文字片出，甫涉後條，已昧前覽，尋源讨流，未知攸適，雖精理瑩心，止乎句偈，而觸物未悟，學致迷惑，是故曲辯情靈，栖心妙典，伏膺空有之說，博綜兼忘之書，該括群流，集成茲典，事以例分，義隨理合，論功約廣，尚於斯矣。","sortOrder":59},
  {"id":"s_work_nvlt_77_60","chapterId":"ch_work_nvlt_77","text":"【書】梁簡文帝與廣信侯書曰：伏承净名法席，親承金口，辭珍鹿苑，理愜鷲山，微妙密藏，於斯既隆，莊嚴道場，自茲弥闡，豈止心燈夜執，亦乃意絮晨飛，每憶華林勝集，亦叨末位，終朝竟夜，沐浴妙言，至於席罢日餘，退休旁省，携手登臨，兼展談笑，仰望九層，俯窥百尺，金池動月，玉树含風，當於此時，足稱法樂。","sortOrder":60},
  {"id":"s_work_nvlt_77_61","chapterId":"ch_work_nvlt_77","text":"答湘東王和受试詩書曰：時有效謝康樂裴鸿臚文者，亦頗有惑焉，謝故巧不可階，裴亦质不宜慕，玉暉金铣，及［梁書四十九庾肩吾傳作反。］為拙目所蚩，巴人下俚，更合郢中之聽，陽春高而不和，妙聲絕而不尋，竟不精讨锱銖，挍量文质，有異巧拙，終媿丑妍，是以握瑜懷玉之士，入鄭邦而知退，章甫翠履之人，望閩乡而叹息。","sortOrder":61},
  {"id":"s_work_nvlt_77_62","chapterId":"ch_work_nvlt_77","text":"《藝文類聚》　唐·欧陽詢","sortOrder":62},
  {"id":"s_work_nvlt_78_1","chapterId":"ch_work_nvlt_78","text":"卷七十八靈異部上","sortOrder":1},
  {"id":"s_work_nvlt_78_2","chapterId":"ch_work_nvlt_78","text":"○仙道","sortOrder":2},
  {"id":"s_work_nvlt_78_3","chapterId":"ch_work_nvlt_78","text":"◇仙道","sortOrder":3},
  {"id":"s_work_nvlt_78_4","chapterId":"ch_work_nvlt_78","text":"《史記》曰：蓬萊仙［《初學記》二十三，《太平御覽》六百六十三作方。］丈瀛洲，此三神山者，在渤海中，蓋嘗有至者，諸仙人及不死藥生焉，其物禽盡白，而黃金白銀為宮闕，未至，望之如雲，及到，三神山反居水下，欲到則風引舡而去，終莫能至。","sortOrder":4},
  {"id":"s_work_nvlt_78_5","chapterId":"ch_work_nvlt_78","text":"又曰：黃帝采首山銅，鑄鼎於荆山之下，鼎既成，有龍垂胡髯，下迎黃帝，黃帝上騎，群臣後宮從上者，七十餘人，小臣不得上，乃悉持龍髯，龍髯拔，墮黃帝弓。百姓仰空望，帝既上，乃抱其弓與胡髯，故後世因名其處曰鼎胡，其弓曰乌號。","sortOrder":5},
  {"id":"s_work_nvlt_78_6","chapterId":"ch_work_nvlt_78","text":"《漢書》曰：梅福居家，常讀書，性少為事，至元始中，王莽专政，福一朝弃妻子，去九江，至今傳以為仙人，其後人有見福者於會稽，变為吳市門卒。","sortOrder":6},
  {"id":"s_work_nvlt_78_7","chapterId":"ch_work_nvlt_78","text":"《晉中興書》曰：葛洪，字稚川，亡時年八十一，视其貌如平生，體亦软弱，舉尸入棺，其輕如空衣，時鹹以為尸解得仙。","sortOrder":7},
  {"id":"s_work_nvlt_78_8","chapterId":"ch_work_nvlt_78","text":"《莊子》曰：藐姑射之山，有神人居焉，肌膚若冰雪，綽約若處子，不食五穀，吸風飲露，乘雲氣，馭飛龍，遊於四海之外。","sortOrder":8},
  {"id":"s_work_nvlt_78_9","chapterId":"ch_work_nvlt_78","text":"又曰：黃帝立為天子，十九年，聞廣成子在於崆峒之上，故往見之曰：我聞吾子達於至道，敢問至道之精，廣成子曰：自而治天下，雲氣不待族而雨，草木不待黃而落，日月之光，益以荒矣。又奚足以語至道，黃帝退居三月，复往邀之，廣成子南首而臥，黃帝從下風，膝行而進，再拜稽首問曰：聞吾子達於至道，敢問治身，奈何而可以長久，廣成子蹶然而起曰：善哉問乎，吾語汝至道，至道之精，窈窈冥冥，至道之極，昏昏默默，無视無聽，抱神以靜，形將自正，心靜神清，無勞汝形，無搖汝精，乃可以長生。","sortOrder":9},
  {"id":"s_work_nvlt_78_10","chapterId":"ch_work_nvlt_78","text":"《淮南子》曰：盧遨遊乎北海，經乎太陰，入乎玄闕，至蒙穀之上，見處士者，深目而喉，渠頭［渠，大也。］而鳶肩，丰上殺下，軒軒方迎風而舞，顧見盧遨，翻然下其臂，遯逃乎崥下，遨就觀之，方卷龟遨［《太平御覽》九百四十二作壳。］而食合藜，遨與之語，若士嚣然笑曰：嘻，子中州之人，不宜而遠至此，猶光乎日月，而載乎列星。","sortOrder":10},
  {"id":"s_work_nvlt_78_11","chapterId":"ch_work_nvlt_78","text":"《列仙傳》曰：萧史，秦缪公時，善吹箫，能致白鵠孔雀，公女字弄玉，好之，以妻焉，遂教弄玉作鳳鳴，居數十年，鳳皇來止其屋，為作鳳台，夫婦止其上，不下數年，一旦皆隨鳳皇飛去，故秦氏作鳳女祠，雍宮世有箫聲。","sortOrder":11},
  {"id":"s_work_nvlt_78_12","chapterId":"ch_work_nvlt_78","text":"又曰：陶公六安冶師，數行火，火一旦散上，紫色冲天，公伏冶下求哀，須臾朱雀止冶曰：安公安公，冶與天通，七月七日，迎汝以赤龍，至時，安公騎之東南上，城邑數萬人，豫祖安送之，皆辭訣。","sortOrder":12},
  {"id":"s_work_nvlt_78_13","chapterId":"ch_work_nvlt_78","text":"又曰：呂尚，冀州人，生而內智，豫知存亡，避紂亂，隱遼東三十年，西適，隱於南山，釣於卞谿，三年不獲魚，問曰：可以止矣，尚曰：非爾所及也，果得大鯉，有兵鈐在腹中，服泽芝地衣石髓，二百年而告亡，葬之無尸，唯有玉鈐六篇，在棺中。","sortOrder":13},
  {"id":"s_work_nvlt_78_14","chapterId":"ch_work_nvlt_78","text":"又曰：江妃二女，不知何許人，出遊江湄，逢鄭交甫，不知其神人也，女遂解珮與之，交甫悅愛珮，去數十步，空懷無珮，女亦不見。","sortOrder":14},
  {"id":"s_work_nvlt_78_15","chapterId":"ch_work_nvlt_78","text":"又曰：漢淮南王劉安，言神仙黃白之事，名為鸿寶萬畢三卷，論变化之道，於是八公乃詣王，授丹經及三十六水方，俗傳安之臨仙去，餘藥器在庭中，雞犬舐之，皆得飛升。","sortOrder":15},
  {"id":"s_work_nvlt_78_16","chapterId":"ch_work_nvlt_78","text":"又曰：赤松子，神農時雨師，服水玉，教神農，能入火自燒，至崑崙山西王母石室，隨風雨上下，炎帝少女追之，亦得仙俱去，高辛時為雨師。","sortOrder":16},
  {"id":"s_work_nvlt_78_17","chapterId":"ch_work_nvlt_78","text":"又曰：偓佺，采藥父也，好食松實，體毛數寸，能飛行，逐走馬，以松子遺尧，尧不服，時受服者，皆三百歲。","sortOrder":17},
  {"id":"s_work_nvlt_78_18","chapterId":"ch_work_nvlt_78","text":"又曰：安期生，琅耶阜乡人，賣藥海邊，時人皆言千歲公，秦始皇請見，與語三日三夜，賜金璧數萬，出於阜乡亭皆置去，留書，以赤玉菭一量為報，曰：复千歲，來求我於蓬萊山下，始皇遣使者數人入海，未至蓬萊山，辄風波而還，立祠阜乡亭，海邊十處。","sortOrder":18},
  {"id":"s_work_nvlt_78_19","chapterId":"ch_work_nvlt_78","text":"又曰：負局先生，語似燕代間人，因摩鏡，辄問主人得無有疾苦者，若有，辄出紫丸赤藥與之，莫不愈，數十年後，大疫，每到戶與藥，愈者萬計，不取一錢，後止吳山絕崖，世世懸藥與人，曰：吾欲還蓬萊山，為汝曹下神水，崖頭一旦有水白色，從石間來下，服之多所愈，立祠十餘年。","sortOrder":19},
  {"id":"s_work_nvlt_78_20","chapterId":"ch_work_nvlt_78","text":"《神仙傳》曰：董威輦，不知何許人，晉武末，在洛陽白社中寢息，身上藍縷，衣不蔽形，恒吞一石子，經日不食，或市乞佣作，人或往觀之，亦不與言，時或著詩，莫知所終。","sortOrder":20},
  {"id":"s_work_nvlt_78_21","chapterId":"ch_work_nvlt_78","text":"又曰：漢期門郎程伟妻者，能通神变化，伟嘗從出，而無時衣，甚愁，妻即為致兩缣，無故至前，伟好黃白，連時不成，妻乃出囊中藥，以少投其已煎水銀，須臾成銀，伟欲從授方，終不可得，雲伟骨相不應得之，逼之不已，妻死，尸解去。","sortOrder":21},
  {"id":"s_work_nvlt_78_22","chapterId":"ch_work_nvlt_78","text":"又曰：葛玄，字孝先，從左元放受九丹液［太平廣記七十一液上有金字。］仙經，與客對食，併言及变化之事，客曰：食畢，先生作一事特戲者，玄曰：君得無促促欲有所見乎，乃嗽口飯，盡成大蜂數百，皆集客身，亦不螫人，食久，玄乃張口，蜂皆飛入口都畢，玄嚼食之，是故飯也，玄指床使行，指虾蟆及諸行虫飛燕雀龟之屬使舞，絃節如人也，玄以冬為客設生瓜棗，夏致冰雪。又以數十錢，使人散投井中，玄以一器，於井上呼錢出，於是錢一一飛從井出，皆向所投也。","sortOrder":22},
  {"id":"s_work_nvlt_78_23","chapterId":"ch_work_nvlt_78","text":"又曰：為客設酒，無人傳之，杯自至前，如或不盡，杯不去也，帝問曰：百姓思雨，寧可得乎，玄曰：雨易得耳，乃書符著社中，一時之間，天地晦冥，大雨流潦。","sortOrder":23},
  {"id":"s_work_nvlt_78_24","chapterId":"ch_work_nvlt_78","text":"又曰：老子，姓李，名耳，字伯陽，楚國苦縣賴乡人也，其母感大星而有娠，雖受氣於天，然生於李家，猶以李為姓。又雲，其母懷之八十一歲乃生，生時，剖其母左腋出，出而白首，故謂之老子，雲母到李树下生老子，生而能言，指李树曰：以此為我姓。又有老聃之號，老子黃色美眉，廣顙長耳，大目疏齒，方口厚唇，額有參牛［《太平御覽》三百六十三作午。］達理，日角月庭，鼻骨双柱，耳有三門，足蹈三［御覽作二。］五，手把十文，以周武王時為柱下史，時俗見其久寿，故號之老子，所出度世之法，九丹八石，玉醴金液，治鬼養性，絕穀变化，役使鬼之法。","sortOrder":24},
  {"id":"s_work_nvlt_78_25","chapterId":"ch_work_nvlt_78","text":"又曰：彭祖，讳铿，帝颛頊玄孫，至殷之末世，年已七百餘歲而不衰，少好恬靜，惟以養神治生為事，王聞之，以為大夫，稱疾不與政事，善於補导之術，併服水桂雲母粉麋角，常有少容，采女乘辎軿，往問道於彭祖，采女具受諸要以教王，王试為之有验，欲秘之，彭祖知之，乃去，不知所如，其後七十餘年，門人於流沙西見之。","sortOrder":25},
  {"id":"s_work_nvlt_78_26","chapterId":"ch_work_nvlt_78","text":"又曰：王烈，字長休，邯鄲人也，烈入河東抱犢山中，得一石室，室中有兩卷素書，烈讀不知其字，不敢取，頗谙十數字形體，歸書作以示嵇叔夜，叔夜盡知其字，烈喜，乃將叔夜往識其經，分明了了，往至失石室所在，烈竊語弟子曰：叔夜不應得道故也。","sortOrder":26},
  {"id":"s_work_nvlt_78_27","chapterId":"ch_work_nvlt_78","text":"又曰：栾巴者，蜀郡人也，正朝大會，巴獨後到。又不飲而南噀，有司奏巴大不敬，有詔問巴，巴頓首謝曰：臣乡里以臣能治鬼護病，為臣生立廟，今旦耆老皆入臣廟，不可委之，是以頗有酒色，臣適來，本縣成都市上失火，臣故噀酒為雨以滅火，非敢不敬，罪當可坐，詔原复坐，即驿書問成都，成都答言，正旦失火，食時有大雨從東北來，火乃息，雨皆作酒臭。","sortOrder":27},
  {"id":"s_work_nvlt_78_28","chapterId":"ch_work_nvlt_78","text":"又曰：河上公，莫知姓名也，漢孝景［太平廣記十作文。］帝時，結草為菴於河湄，嘗讀老子經，景帝好老子之言，有所不知數事，莫能通者，聞人說河上公讀老子，乃遣人谘所不解事以問之，河上公曰：道尊德貴，非可遙問也，帝即駕而從之，公以素書二卷與帝，曰：熟省此，則皆疑了，不事多言言也，勿以示非人，言畢失其所在，須臾雲霧晦冥，天地斗合，論者為景帝好老子之言，一世不能盡通之，故神人將下教之便去也。","sortOrder":28},
  {"id":"s_work_nvlt_78_29","chapterId":"ch_work_nvlt_78","text":"又曰：封君達，隴西人，初服黃連五十餘年，入鳥鼠山。又於中服水銀百餘年，還乡，年如二十者。","sortOrder":29},
  {"id":"s_work_nvlt_78_30","chapterId":"ch_work_nvlt_78","text":"關令內傳曰：關令尹喜，周之大夫也，母氏嘗晝寢，夢天下絳绡，流繞其身，見長人語，令咽之，既覺，口有盈味，及真人生時，有双光若日，飛遊其侧，室內皆明，良久不知所在，其家陆地自生莲華，光色鮮盛，眼有日精，姿形長雅，垂臂下膝，堂堂有天人之貌，少好學墳素，善於天文秘緯，仰看俯察，莫不洞彻，雖鬼神無以匿其真状，老子感焉，未至九十日，關令登樓四望，見東極有紫氣西邁，喜曰：夫陽氣盡九，星宿值合，歲月併王，复九十日之外，法應有聖人經過京邑，至期，乃斋戒，其日果見老子。","sortOrder":30},
  {"id":"s_work_nvlt_78_31","chapterId":"ch_work_nvlt_78","text":"真人周君傳曰：紫陽真人周義山，字委通，汝陰人也，聞有栾先生，得道在蒙山，能讀龍峤經，乃追尋之，入蒙山，遇羨門子，乘白鹿，執羽蓋，佩青毛之節，侍從十餘玉女，君乃再拜叩頭，乞長生要訣，羨門子曰：子名在丹台玉室之中，何忧不仙，遠越江河來，登此何索。","sortOrder":31},
  {"id":"s_work_nvlt_78_32","chapterId":"ch_work_nvlt_78","text":"《漢武內傳》曰：李少君，字雲翼，齊國臨淄人，好道，入泰山采藥，修絕穀全身之術，遇安期生，少君疾困，叩頭乞活，安期以神樓散一匕與服之，即愈，乃以方幹上，言臣能凝澒成白銀，飛丹沙成黃金，金成服之，白日升天，身生朱陽之翼，艳備員光之異，竦則凌天，伏入無間，控飛龍而八遐遍，乘白鸿而九陔周，冥海之棗大如瓜，鍾山之李大如瓶，臣以食之，遂生奇光，師安期授臣口訣，是以保萬物之可成也，於是上甚尊敬，為立屋第。","sortOrder":32},
  {"id":"s_work_nvlt_78_33","chapterId":"ch_work_nvlt_78","text":"《漢武故事》曰：上巡狩，過河聞，［按當作間。］見青紫氣，自地屬天，望氣者以為其下有奇女，必天子之祥，求之，見一女子在空馆中，姿貌殊絕，兩手皆拳，上令开其手，數百人擘莫能开，上自披，手即申，由是得幸，為拳夫人，進為婕妤，居鉤弋宮，解黃帝素女之術，大有寵，有身，十四月，產昭帝，上曰：尧十四月而生，鉤弋亦然，乃命其門曰尧母門。","sortOrder":33},
  {"id":"s_work_nvlt_78_34","chapterId":"ch_work_nvlt_78","text":"《搜神記》曰：遼東城門有華表柱，忽有一白鶴集柱頭，時有少年，舉弓欲射之，鶴乃飛，徘徊空中而言曰：有鳥有鳥丁令威，去家千歲今來歸，城郭如故人民非，何不學仙冢壘壘，遂高上冲天，今遼東諸丁，雲其先世有升仙者，不知名字。","sortOrder":34},
  {"id":"s_work_nvlt_78_35","chapterId":"ch_work_nvlt_78","text":"又曰：蓟子訓，不知所來，到洛，見公卿數十處，皆持斗酒片脯候之，曰：遠來無所有，示致微意，坐上數百人，飲啖終日不盡，去後，數十處皆白雲起，從旦至暮，時有百歲公，說小兒時，見訓賣藥會稽市，顏色如此，訓不樂住洛，遂遁去，正始中，長安東霸城中，有見之者，與一老公，摩娑銅人曰：適見鑄此，已近五百歲。","sortOrder":35},
  {"id":"s_work_nvlt_78_36","chapterId":"ch_work_nvlt_78","text":"《神異經》曰：崑崙有柱焉，其高入天，所謂天柱也，围三千里，圓如削，下有仙人九府治，與天地同休息。","sortOrder":36},
  {"id":"s_work_nvlt_78_37","chapterId":"ch_work_nvlt_78","text":"《十洲記》曰：聚窟洲，在西海中，洲上有大树，與楓木相似而材芳，華葉香聞數百里，名此為反魂，叩其树，树亦能自聲，聲如群牛吼，聞之者皆心震神駭，伐其根心，玉釜中煮取汁，更微火熟煎之，如飴，令可丸，名曰驚精香，或名之振靈丸，或名之為反生香。","sortOrder":37},
  {"id":"s_work_nvlt_78_38","chapterId":"ch_work_nvlt_78","text":"又曰：崑崙山三角，一角正幹北辰星辉，名曰阆風嶺，其一角正西，曰玄圃台，其一角正東，曰崑崙宮，其一處有積金，為天墉城，面千里，城安金台。","sortOrder":38},
  {"id":"s_work_nvlt_78_39","chapterId":"ch_work_nvlt_78","text":"又曰：鍾山在北海之子地，仙家數十萬，耕田种芝草，課計頃畝，風俗通曰：孝明帝時，尚書郎河東王乔，遷為葉縣令，乔月朔，常詣台朝明帝，帝怪其來數而無車騎，密令太史候望，言其臨至時，常有双凫從東南飛來，因伏伺見凫，舉羅但得一只舄，使尚方識，乃四年所賜尚書官履也，每朝，葉門下鼓，不击自鳴，聞於京師，後天下一玉棺於廳事前，乔曰：天帝獨欲召我，沐浴寢其中，蓋便上覆，葬於城東，土自成墳，人無知之者，百姓為立祠，號葉君祠。","sortOrder":39},
  {"id":"s_work_nvlt_78_40","chapterId":"ch_work_nvlt_78","text":"《異苑》曰：陶侃，字士衡，微時，遭父艱，有人長九尺，端悅，通刺子，字不可識，心怪非常，出庭拜送，此人告侃曰：吾是王子晉，君有巨相，故來相看，於是脱衣帢，服仙羽，升鵠而騰颺。","sortOrder":40},
  {"id":"s_work_nvlt_78_41","chapterId":"ch_work_nvlt_78","text":"【詩】魏文帝遊仙詩曰：西山一何高，高高殊無極，上有兩仙童，不飲亦不食，與我一丸藥，光曜有五色，服藥四五日，焜臆生羽翼，輕舉生風雲，倏忽行萬亿，流覽觀四海，茫茫非所識。","sortOrder":41},
  {"id":"s_work_nvlt_78_42","chapterId":"ch_work_nvlt_78","text":"魏陳王曹植遊仙詩曰：人生不滿百，戚戚少歡娱，意欲奋六翮，排霧陵紫虛，蝉蜕同松乔，翻跡登鼎湖，翱翔九天上，騁辔遠行遊，東觀扶桑曜，西臨弱水流，北極登玄渚，南翔陟丹丘。","sortOrder":42},
  {"id":"s_work_nvlt_78_43","chapterId":"ch_work_nvlt_78","text":"又五遊詠曰：九州不足步，原得凌雲翔，逍遙八紘外，遊目歷遐荒，披我丹霞衣，袭我素霓裳，華蓋紛菴藹，六龍仰天驤，曜靈未移景，倏忽造昊仓，閶阖啟丹扉，双闕曜朱光，徘徊文昌殿，登陟太微堂，上帝伏西櫺，群後集東厢，帶我琼瑤佩，嗽我沆瀣漿，踟蹰玩靈芝，徙倚弄華芳，王子奉仙藥，羨門進奇方，服食享遐紀，延寿保無疆。","sortOrder":43},
  {"id":"s_work_nvlt_78_44","chapterId":"ch_work_nvlt_78","text":"又遠遊詩曰：靈鼇戴方丈，神嶽俨嵯峨，仙人翔其隅，玉女戲其阿，琼蕊可療飢，仰首嗽朝霞，崑崙本吾宅，中州非我家。","sortOrder":44},
  {"id":"s_work_nvlt_78_45","chapterId":"ch_work_nvlt_78","text":"晉何劭遊仙詩曰：羨昔王子乔，友道發伊洛，迢遞陵峻嶽，連翩御飛鶴。","sortOrder":45},
  {"id":"s_work_nvlt_78_46","chapterId":"ch_work_nvlt_78","text":"晉張协遊仙詩曰：峥嵘玄圃深，嵯峨天嶺峭，亭馆籠雲構，脩梁流三曜，蘭葩蓋嶺披，清風緣隙嘯。","sortOrder":46},
  {"id":"s_work_nvlt_78_47","chapterId":"ch_work_nvlt_78","text":"晉郭璞遊仙詩曰：京華豪俠窟，山林隱遁栖。","sortOrder":47},
  {"id":"s_work_nvlt_78_48","chapterId":"ch_work_nvlt_78","text":"又曰：登嶽采五芝，涉涧將六草，散發荡玄溜，終年不華浩。","sortOrder":48},
  {"id":"s_work_nvlt_78_49","chapterId":"ch_work_nvlt_78","text":"又曰：青谿千餘仞，中有一道士。","sortOrder":49},
  {"id":"s_work_nvlt_78_50","chapterId":"ch_work_nvlt_78","text":"又曰：中有冥寂士，靜嘯撫清絃。","sortOrder":50},
  {"id":"s_work_nvlt_78_51","chapterId":"ch_work_nvlt_78","text":"又曰：四渎流如淚，五嶽羅若垤，尋我青雲友，永與時人絕。","sortOrder":51},
  {"id":"s_work_nvlt_78_52","chapterId":"ch_work_nvlt_78","text":"又曰：靜叹亦何念，悲此妙齡逝，在世無千月，命如秋葉蒂，蘭生蓬芭間，榮曜常幽翳。","sortOrder":52},
  {"id":"s_work_nvlt_78_53","chapterId":"ch_work_nvlt_78","text":"又曰：吞舟踴海底，高浪駕蓬萊。","sortOrder":53},
  {"id":"s_work_nvlt_78_54","chapterId":"ch_work_nvlt_78","text":"又曰：登仙撫龍驷，迅駕乘奔雷，鱗裳逐電曜，雲蓋隨風回，手頓羲和辔，足逾閶阖开，東海猶蹄涔，崑崙若蚁堆。","sortOrder":54},
  {"id":"s_work_nvlt_78_55","chapterId":"ch_work_nvlt_78","text":"又曰：縱酒濛汜濱，結駕尋木末，翘手攀金梯，飛步登玉闕，左顧擁方目，右眷極朱發。","sortOrder":55},
  {"id":"s_work_nvlt_78_56","chapterId":"ch_work_nvlt_78","text":"又曰：璇台冠崑嶺，西海濱招搖，琼林籠藻映，碧树疏英翘，丹泉漂朱沫，黑水鼓玄涛，尋仙萬餘日，今乃見子乔，振發見翠霞，解褐被絳绡，總辔臨少廣，盤虬舞雲轺。","sortOrder":56},
  {"id":"s_work_nvlt_78_57","chapterId":"ch_work_nvlt_78","text":"晉成公綏仙詩曰：盛年無幾時，奄忽行欲老，那得赤松子，從學渡世道，西入華陰山，求得神芝草，珠玉猶戴土，何惜千金寶，但原寿無窮，與君長相保。","sortOrder":57},
  {"id":"s_work_nvlt_78_58","chapterId":"ch_work_nvlt_78","text":"晉庾闡遊仙詩曰：神嶽竦丹霄，玉堂臨雪嶺，上采琼树華，下挹瑤泉井。","sortOrder":58},
  {"id":"s_work_nvlt_78_59","chapterId":"ch_work_nvlt_78","text":"又曰：南海納朱涛，玄波洒北溟，仰盻燭龍曜，俯步朝廣庭。","sortOrder":59},
  {"id":"s_work_nvlt_78_60","chapterId":"ch_work_nvlt_78","text":"又曰：功疏煉石髓，赤松漱水玉，凭煙眇封子，流浪揮玄俗，空峒臨北戶，崑吾眇南陆，曾霄映紫芝，潛涧汎丹菊，崑崙涌五河，八流萦地軸。","sortOrder":60},
  {"id":"s_work_nvlt_78_61","chapterId":"ch_work_nvlt_78","text":"又曰：三山羅如粟，巨壑不容刀，白龍騰子明，朱鱗運琴高，輕舉觀沧海，眇邈去瀛洲，玉泉出靈凫，琼草被神丘。","sortOrder":61},
  {"id":"s_work_nvlt_78_62","chapterId":"ch_work_nvlt_78","text":"又曰：熒熒丹桂紫芝，結根雲山九疑，鮮榮夏馥冬熙，誰與薄采松期。","sortOrder":62},
  {"id":"s_work_nvlt_78_63","chapterId":"ch_work_nvlt_78","text":"又曰：赤松霞霧乘煙，封子煉骨凌仙，沧漱水玉心玄，故能靈化自然。","sortOrder":63},
  {"id":"s_work_nvlt_78_64","chapterId":"ch_work_nvlt_78","text":"又曰：乘彼六氣渺茫，辎駕赤水崑陽，遙望至人玄堂，心與罔象俱忘。","sortOrder":64},
  {"id":"s_work_nvlt_78_65","chapterId":"ch_work_nvlt_78","text":"又曰：朝嗽雲英玉蕊，夕挹玉膏石髓，瑤台藻構霞綺，鱗裳羽蓋級纚。","sortOrder":65},
  {"id":"s_work_nvlt_78_66","chapterId":"ch_work_nvlt_78","text":"又曰：玉树標雲翠蔚，靈崖獨拔奇卉，芳津蘭瑩珠隧，碧葉灌清鱗萃。","sortOrder":66},
  {"id":"s_work_nvlt_78_67","chapterId":"ch_work_nvlt_78","text":"又曰：玉房石〈木翕〉磊砢，燭龍衔辉吐火，朝采石英涧左，夕翳琼葩巖下。","sortOrder":67},
  {"id":"s_work_nvlt_78_68","chapterId":"ch_work_nvlt_78","text":"晉張華詠萧史詩曰：萧史愛長年，嬴女老童顏，火粒原排弃，霞霧好登攀，龍飛竟天路，鳳起出秦關，身去長不反，箫聲時往還。","sortOrder":68},
  {"id":"s_work_nvlt_78_69","chapterId":"ch_work_nvlt_78","text":"又遊仙詩曰：雲霓垂藻旒，羽掛扬輕裾，飄登清雲間，論道神皇庐，箫史登鳳音，王後吹鳴竽，守精味玄妙，逍遙無為墟。","sortOrder":69},
  {"id":"s_work_nvlt_78_70","chapterId":"ch_work_nvlt_78","text":"又曰：玉佩連浮星，輕冠結朝霞，列坐王母堂，丰餐琼瑤華，湘妃詠涉江，漢女奏陽阿。","sortOrder":70},
  {"id":"s_work_nvlt_78_71","chapterId":"ch_work_nvlt_78","text":"又曰：乘雲去中夏，隨風濟江湘，亹亹陟高陵，遂升玉峦陽，雲娥荐琼石，神妃侍衣裳。","sortOrder":71},
  {"id":"s_work_nvlt_78_72","chapterId":"ch_work_nvlt_78","text":"晉湛方生庐山神仙詩併序曰：尋陽有庐山者，盤基彭蠡之西，其崇標峻極，辰光隔辉，幽涧澄深，積清百仞，若乃絕阻重险，非人跡之所遊，窈窕冲深，常含霞而貯氣，真可謂神明之區域，列真之苑囿矣，太元十一年，有樵采之陽者，於時鮮霞褰林，傾暉映岫，見一沙門，披法服，獨在巖中，俄頃振裳揮錫，凌崖直上，排丹霄而輕舉，起九折而一指，既白雲之可乘，何帝乡之足遠哉，窮目蒼蒼，翳然滅跡，詩曰：吸風玄圃，飲露丹霄，室宅五嶽，賓友松乔。","sortOrder":72},
  {"id":"s_work_nvlt_78_73","chapterId":"ch_work_nvlt_78","text":"齊袁彖遊仙詩曰：羽客宴瑤宮，旌蓋乍舒設，王子洛浦來，湘娥洞庭發，長引逐清風，高歌送奔月，併馭排帝闼，連吹入天闕，萬古一方春，千霜豈二發。","sortOrder":73},
  {"id":"s_work_nvlt_78_74","chapterId":"ch_work_nvlt_78","text":"又曰：白玉三重階，黃金九層路，采煙拂紫甍，芳風搖碧树。","sortOrder":74},
  {"id":"s_work_nvlt_78_75","chapterId":"ch_work_nvlt_78","text":"齊陆慧晓遊仙詩曰：旌翻玉華晦，袖轉雲光移，袭舄黃山下，投佩朱路歧，梁簡文帝仙客詩曰：漆水豈難变，桐刀乍可揮，青書長命箓，紫水芙蓉衣，高翔五嶽小，低望九河微，穿池聽龍長，叱石待羊歸，酒阑時節久，桃生歲月稀。","sortOrder":75},
  {"id":"s_work_nvlt_78_76","chapterId":"ch_work_nvlt_78","text":"梁元帝和鮑常侍龍川馆詩曰：珍台接閒馆，迢遞山之旁，多解三真術，俱善四明方，玉題書仙篆，金榜燭神光，桂影侵簷進，藤枝繞槛長，苔文隨溜轉，梅氣入風香。","sortOrder":76},
  {"id":"s_work_nvlt_78_77","chapterId":"ch_work_nvlt_78","text":"梁沈約華山馆為國家營功德詩曰：沐芳祷靈嶽，稽首恭上玄，帝昔祈萬寿，臣今請亿年，丹方緘洞府，河清時一傳，錦書飛雲字，玉簡黃金編。","sortOrder":77},
  {"id":"s_work_nvlt_78_78","chapterId":"ch_work_nvlt_78","text":"又和竟陵王遊仙詩曰：天蟜乘絳仙，螭衣方陆離，玉鑾隱雲霧，溶溶紛上馳，瑤台風不息，赤水正涟漪，峥嵘玄圃上，聊攀琼树枝。","sortOrder":78},
  {"id":"s_work_nvlt_78_79","chapterId":"ch_work_nvlt_78","text":"又曰：朝止閶阖宮，暮宴清都闕，騰蓋隱奔星，低鑾避行月，九疑紛相從，虹旌乍升没，青鳥去复還，高唐雲不歇，若華有餘照，淹留且晞發。","sortOrder":79},
  {"id":"s_work_nvlt_78_80","chapterId":"ch_work_nvlt_78","text":"又曰：陶先生登樓不复下詩曰：侧聞上士說，尺木乃騰霄，雲軿不展地，仙居多麗谯，臥待三芝秀，坐對百神朝，衔書必青鳥，嘉客信龍鑣，非止靈桃實，方見大椿凋。","sortOrder":80},
  {"id":"s_work_nvlt_78_81","chapterId":"ch_work_nvlt_78","text":"又赤松涧詩曰：松子排煙去，英靈眇難测，惟有清涧流，潺湲終不息，神丹在茲化，雲軿於此陟，原受金液方，片言生羽翼，渴就華池飲，飢向朝霞食，何時當來還，延佇清巖侧。","sortOrder":81},
  {"id":"s_work_nvlt_78_82","chapterId":"ch_work_nvlt_78","text":"又和劉中書仙詩曰：殊庭不可及，風熛多異色，霞衣不待縫，雲錦不須織。","sortOrder":82},
  {"id":"s_work_nvlt_78_83","chapterId":"ch_work_nvlt_78","text":"又，清旦發玄洲，日暮宿丹丘，崑山西北映，流泉東南流，霓裳拂流電，雲車委輕霰，峥嵘上不睹，寥廓下無見。","sortOrder":83},
  {"id":"s_work_nvlt_78_84","chapterId":"ch_work_nvlt_78","text":"又沈道士馆詩曰：秦王御宇宙，漢帝恢武功，歡娱人世盡，情性猶未充，銳意三山上，讬慕九霄中，既表祈年觀，复立望仙宮，寧為心好道，直由意無窮，曰餘知止足，是原不須丰，遇可淹留處，便欲息微躬，山嶂遠重叠，竹树近蒙籠，开襟濯寒水，解帶臨清風，所累非物外，為念在玄蹤，朋來挹石髓，賓至駕飛鸿，都令人径絕，惟使雲路通，一舉陵倒景，無事適華嵩，寄言賞心客，歲暮爾來同。","sortOrder":84},
  {"id":"s_work_nvlt_78_85","chapterId":"ch_work_nvlt_78","text":"梁王筠東南射山詩曰：還丹改容质，握髓駐留年，口含千里霧，掌流五色煙，琼漿汎金鼎，瑤池溉玉田，倏忽整龍駕，相遇鳳台前。","sortOrder":85},
  {"id":"s_work_nvlt_78_86","chapterId":"ch_work_nvlt_78","text":"梁庾肩吾道馆詩曰：仙人白鹿上，隱士潛溪邊，试取西山藥，來觀東海田。","sortOrder":86},
  {"id":"s_work_nvlt_78_87","chapterId":"ch_work_nvlt_78","text":"陳周弘正和庾肩吾詩曰：石桥有舊路，靈室俨眾仙，菊潭溜餘水，丹竈起殘煙，桃花經作實，海水屢成田，逆愁歸舊里，追問斧柯年。","sortOrder":87},
  {"id":"s_work_nvlt_78_88","chapterId":"ch_work_nvlt_78","text":"周王襃過臧矜道馆詩曰：松古無年月，鵠去复來歸，石壁藤為路，山窗雲作扉。","sortOrder":88},
  {"id":"s_work_nvlt_78_89","chapterId":"ch_work_nvlt_78","text":"周庾信和趙王遊仙詩曰：藏山還采藥，有道得從師，京兆陳安世，成都李意其，玉魚傳相鶴，太一受飛龟，白日香薪寺，青泥美熟芝，山精逢照鏡，樵客值围棋，石文如碎錦，藤苗似亂絲，蓬萊在何處，漢後欲遙祠。","sortOrder":89},
  {"id":"s_work_nvlt_78_90","chapterId":"ch_work_nvlt_78","text":"又道士步虛詞曰：洞靈尊上德，虞石會明真，要妙思玄絕，虛無養穀神，丹丘乘翠鳳，玄圃馭班麟，移梨付苑吏，种杏乞山人，自此逢何世，從今复幾春，海無三尺水，山成數寸尘。","sortOrder":90},
  {"id":"s_work_nvlt_78_91","chapterId":"ch_work_nvlt_78","text":"又曰：東明九芝蓋，北燭五雲車，飄飖入倒景，出没上煙霞，春泉下玉霤，青鳥向金華，漢帝看桃核，齊侯問棗花，上元應送酒，來在蔡經家。","sortOrder":91},
  {"id":"s_work_nvlt_78_92","chapterId":"ch_work_nvlt_78","text":"又曰：歸心遊太極，回向入無名，五香芬紫府，千燈照赤城，鳳林采桐實，春山种玉榮，夏簧三舌响，春鍾九乳鳴，絳河應遠別，黃鵠來相迎。","sortOrder":92},
  {"id":"s_work_nvlt_78_93","chapterId":"ch_work_nvlt_78","text":"又曰：北閣臨玄水，南宮坐絳雲，龍泥印玉策，天火練真文，上元風雨散，中天歌吹分，靈駕千尋上，空香萬里聞。","sortOrder":93},
  {"id":"s_work_nvlt_78_94","chapterId":"ch_work_nvlt_78","text":"又曰：地鏡階基遠，天窗影跡深，碧玉成双树，空青為迥林，鵲巢堪煉石，蜂房得煮金，漢武多娇慢，淮南不小心，蓬瀛入海底，何處可追尋。","sortOrder":94},
  {"id":"s_work_nvlt_78_95","chapterId":"ch_work_nvlt_78","text":"又曰：麟州一海闊，玄圃半天高，浮丘迎子晉，若士避盧遨，經餐林慮李，舊食綏山桃，成丹須竹節，刻髓用芦刀，無妨隱士去，即是賢人逃。","sortOrder":95},
  {"id":"s_work_nvlt_78_96","chapterId":"ch_work_nvlt_78","text":"周萧捴和梁武陵王遙望道馆詩曰：神境流精闕，仙居紫翠房，今有尋真地，逦迤麗通莊，九柱含虬重，三台飾夜光，金辉碧海桃，玉笈紫書方，拂筵青鳥集，吹箫白鳳翔，履歸堪是燕，石在詎非羊，煙霞四照蕊，風月五名香，於茲喜臨眺，原得假霓裳。","sortOrder":96},
  {"id":"s_work_nvlt_78_97","chapterId":"ch_work_nvlt_78","text":"陳張正見遊匡山簡寂馆詩曰：三梁涧本絕，千仞路猶通，即此神山內，銀榜映仙宮，鏡似臨峰月，流如飲涧虹，幽桂無斜影，深松有劲風，惟當遠人望，知在白雲中。","sortOrder":97},
  {"id":"s_work_nvlt_78_98","chapterId":"ch_work_nvlt_78","text":"陳陰铿遊始興道馆詩曰：紫台高不極，清溪千仞餘，壇邊逢藥銚，洞里閱仙書，庭舞經［《初學記》二十三經下有乘字，此脱。］鶴，池遊被控魚，稍昏蕙葉斂，欲暝槿花疏，徒交斧柯烂，會自不凌虛。","sortOrder":98},
  {"id":"s_work_nvlt_78_99","chapterId":"ch_work_nvlt_78","text":"又賦詠得神仙詩曰：羅浮銀是殿，瀛洲玉作堂，朝遊雲暫起，夕餌菊恒香，聊持履成燕，戲以石為羊，洪崖與松子，乘羽就周王。","sortOrder":99},
  {"id":"s_work_nvlt_78_100","chapterId":"ch_work_nvlt_78","text":"【賦】漢司馬相如大人賦曰：相如拜為孝文園令，見上好仙，乃遂奏大人賦，其辭曰：世有大人，在乎中州，宅弥萬里，曾不足以少留，悲世俗之迫隘，朅輕舉而遠遊，垂絳幡之素霓，戴雲氣而上浮，建格泽之脩竿，總光曜之采旄，垂旬始以為幓，曳彗星而為髾，絕少陽而登大陰，與真人乎相求，屯餘車而萬乘，翠雲蓋而树華旗，歷唐尧於崇山，遇虞舜於九疑，朅度九江，越五河，時若暧暧將混濁，召屏翳，誅風伯，刑雨師，排閶阖而入帝宮，載玉女而與之歸，登阆風而遙集，飛鳥騰而一止，吾乃今日睹西王母，皓然白首，戴勝而穴處，亦幸有三足乌為之使，遣屯騎玄闕，軼先驅於寒門，下峥嵘而無地，上寥廓而無天，视眩泯而無見，聽敞怳而無聞，乘虛無而上假，超無反而獨存。","sortOrder":100},
  {"id":"s_work_nvlt_78_101","chapterId":"ch_work_nvlt_78","text":"後漢桓君山仙賦曰：餘少時為中郎，從孝成帝出祠甘泉河東，見郊先置華陰集靈宮，宮在華山下，武帝所造，欲以懷集仙者王乔赤松子，故名殿為存仙，端門南向山，署曰望仙門，竊有樂高妙之志，即書壁為小賦，以頌美曰：夫王乔赤松，呼則出故，翕則納新，夭矯經引，積氣關元，精神周洽，鬲塞流通，乘凌虛無，洞達幽明，諸物皆見，玉女在旁，仙道既成，神靈攸迎，乃驂駕青龍，赤騰為歷，躇玄厲之擢嶵，有似乎鸞鳳之翔飛，集於膠葛之宇，泰山之台，吸玉液，食華芝，漱玉漿，飲金醪，出宇宙，與雲浮，洒輕霧，濟傾崖，觀仓川而升天門，馳白鹿而從麒麟，周覽八極，還崦華壇，氾氾乎濫濫，隨天轉璇，容容無為，寿極乾坤。","sortOrder":101},
  {"id":"s_work_nvlt_78_102","chapterId":"ch_work_nvlt_78","text":"後漢黃香九宮賦曰：伊黃靈之典度，存文昌之會宮，握璇璣而布政，總四七而持綱，和日月之光曜，均節度以運行，經閶阖而出玉房，謁五嶽而朝六宗，蹠崑崙而跪碣石，蹈底柱而跨太行，肘熊耳而據桐柏，分嶓冢而持外方，使織女驂乘，王良為之御，三台執兵而奉張，軒轅乘駏驉而先驅，左青龍而右觜携，前七星而後騰蛇。","sortOrder":102},
  {"id":"s_work_nvlt_78_103","chapterId":"ch_work_nvlt_78","text":"晉陆機列仙賦曰：夫何列仙玄妙，超攝生乎世表，因自然以為基，仰造化而聞道，性冲虛以易足，年緬邈其難老，爾乃呼翕九陽，抱一含元，引新吐故，雲飲露餐，违品物以長盻，妙群生而為言，爾其嘉會之仇，息宴遊栖，則昌客［疑當作容。］弄玉，洛宓江妃，觀百化於神區，觐天皇於紫微，過太華以息駕，越流沙而來歸。","sortOrder":103},
  {"id":"s_work_nvlt_78_104","chapterId":"ch_work_nvlt_78","text":"又陵霄賦曰：挟至道之容微，狹流俗之紛泹，颺餘節以遠模，風扶搖而相予，削陋跡於分丘，省遊仙而投軌，凯情累以遂濟，豈時俗之雲阻，判煙雲之騰躍，半天步而無旅，詠陵霄之飄飄，永終焉而弗悔，昊蒼煥而運流，日月翻其代序，下霄房之靡迄，卜良辰而复舉，陟瑤台以投辔，步玉除而容與。","sortOrder":104},
  {"id":"s_work_nvlt_78_105","chapterId":"ch_work_nvlt_78","text":"梁陶弘景水仙賦曰：淼漫八海，汯汨九河，中天起浪，分地寫波，東卷長桑日窟，西斡龍筑月阿，乃者潼關不壅，石門已开，导江出漢，浮濟達淮，漳渠水府，包山洞台，娀英之所遊往，琴冯是焉去來，於是碧巖無霧，绿水不風，飛軒纼鳳，遊軒駕鸿，上朝紫殿，還觐青宮，進麾八老，顧拂四童，酌丹穴之酎，荐麟洲之肴，錦旌麗日，羽衣拂霄，亦有先覺之秀，獨往之英，窥若士於蒙縠，求呂梁於石城，從霧光於底柱，索龍威於洞庭，迎九玄於金闕，謁三素於玉清，更天地而弥固，終逍遙以長生。","sortOrder":105},
  {"id":"s_work_nvlt_78_106","chapterId":"ch_work_nvlt_78","text":"又雲上之仙風賦曰：縹緲遙裔，亘碧海而颺朝霞，凌青煙而溥天际，出龍門而激水，度葱關以飛雪，於是漢區動御，月軌驚文，浮虛入景，登空汎雲，一舉萬里，曾不浃辰，此列子有待之風也，若乃綿括宇宙，苞絡天維，周流八極，回環四時，氣值節而動律，位涉巽而離箕，徒見去來之緒，莫测終始之期，此太虛無為之風也。","sortOrder":106},
  {"id":"s_work_nvlt_78_107","chapterId":"ch_work_nvlt_78","text":"梁江淹丹砂可學賦曰：或曰：黃金可鑄，仆不信，试為此辭，乘河漢之光氣，騎列星之采色，輟陰陽於形有，傳变化於心識，既而暧碧台之错落，曜金宮之玲瓏，沼莲華於繡閣，化蒲陶於錦屏，奏神鼓於玉袂，舞靈衣於金裾，韻踯躅而易变，律參差而難圖，非南風之能擬，詎濮水之敢模。","sortOrder":107},
  {"id":"s_work_nvlt_78_108","chapterId":"ch_work_nvlt_78","text":"【頌】魏陳王曹植玄俗頌曰：玄俗妙識，飢餌神穎，在陰倏逝，即陽無景，逍遙北嶽，凌霄引領，揮霧昊天，舍神自靜。","sortOrder":108},
  {"id":"s_work_nvlt_78_109","chapterId":"ch_work_nvlt_78","text":"晉牵秀老子頌曰：深哉伯陽，誕此靈姿，研精玄奧，幽贊神微，抱质懷素，蘊寶藏辉，述而好古，儀聖作師，周衰道废，厥猷匪宣，龍潛初九，亢志皓然，於邈高風，徽音永傳。","sortOrder":109},
  {"id":"s_work_nvlt_78_110","chapterId":"ch_work_nvlt_78","text":"又彭祖頌曰：於休彭公，應運特生，窮神知化，妙物通靈，挹之不冲，滿之不盈，韜光隱曜，混沌玄清，確乎其摻，邈乎其度，含真荡秽，離俗遺務，讬神玄妙，遊心泰素，享年七百，寶降其祚，惠我無疆，倫道作故。","sortOrder":110},
  {"id":"s_work_nvlt_78_111","chapterId":"ch_work_nvlt_78","text":"又王乔赤松頌曰：妙哉松乔，禀此殊姿，含精握氣，靈德是綏，藏器華圃，允首騰飛，齊跡風雲，超遠姿微，乃翔靈墳，鳥像人聲，低徊舊土，眷此平生，惠而不谅，凋我素形，神儀既陨，翻飛而征，遨遊八維，跨騰九冥，應慶罔極，與道虛盈。","sortOrder":111},
  {"id":"s_work_nvlt_78_112","chapterId":"ch_work_nvlt_78","text":"【贊】晉陆機王子乔贊曰：遺形靈嶽，顧景忘歸，乘雲倏忽，飄飖紫微。","sortOrder":112},
  {"id":"s_work_nvlt_78_113","chapterId":"ch_work_nvlt_78","text":"晉湛方生老子贊曰：教由嚴宗，化必有資，深矣若人，乃作皇師，亦參儒訓，道實希夷，恂恂孔父，是敬是祗。","sortOrder":113},
  {"id":"s_work_nvlt_78_114","chapterId":"ch_work_nvlt_78","text":"晉郭璞冯夷贊曰：禀華之精，食惟八石，乘龍隱淪，往來海客，若是水仙，號曰河伯。","sortOrder":114},
  {"id":"s_work_nvlt_78_115","chapterId":"ch_work_nvlt_78","text":"又曰：水土冰鱗，潛映洞川，赤松是服，靈蜕乘煙，吐納六氣，升降九天。","sortOrder":115},
  {"id":"s_work_nvlt_78_116","chapterId":"ch_work_nvlt_78","text":"宋孝武帝洞井贊曰：絳紀山瑞，紫志川靈，金膏溢曜，玉树含英，端巖毓泉，挹祥吐禎，彪彬仙牒，揮翕诡經。","sortOrder":116},
  {"id":"s_work_nvlt_78_117","chapterId":"ch_work_nvlt_78","text":"梁江淹王子乔贊曰：子乔好輕舉，不待煉銀丹，控鶴上窈窕，學鳳對巑岏，山無一春草，穀有千年蘭，雲衣不踯躅，龍駕何時還。","sortOrder":117},
  {"id":"s_work_nvlt_78_118","chapterId":"ch_work_nvlt_78","text":"又陰長生贊曰：陰君惜靈骨，珪璧詎為寶，日夜名山侧，果得金丹道，忧傷永不至，光顏如碧草，若渡西海時，致意三青鳥。","sortOrder":118},
  {"id":"s_work_nvlt_78_119","chapterId":"ch_work_nvlt_78","text":"又白雲贊曰：紫煙世不觌，赤鱗庖所捐，白雲亦海外，葐蒀起三山，箫瑟玉池上，容裔帝台前，欲知清都里，乘此乃登天。","sortOrder":119},
  {"id":"s_work_nvlt_78_120","chapterId":"ch_work_nvlt_78","text":"又秦女贊曰：青琴既曠世，绿珠亦絕群，猶不及秦女，十五乘采雲，璧质人不見，琼光俗詎聞，使洛靈脩往，為我道奇芬。","sortOrder":120},
  {"id":"s_work_nvlt_78_121","chapterId":"ch_work_nvlt_78","text":"【碑】齊孔稚珪玄馆碑曰：夫朋白兔而侣青鳥，啟銀函而講金字者，有道存焉，故能大叩玄宗，鬱為物范，則天地，正六合，照日月而导蒼生，神道無門，陰陽不测，是故赤松家石室之下，神農行弟子之敬，廣成在崆峒之上，軒轅禀順風之禮，洛浦笙飛之秀，關山駕鳳之英，凡此之儔，希世間出，皆雍容以沐鹹池，或萧洒而开閶阖。","sortOrder":121},
  {"id":"s_work_nvlt_78_122","chapterId":"ch_work_nvlt_78","text":"梁簡文帝招真馆碑［王鏊姑蘇志三十作梁昭明太子虞山招真治記。］曰：夫東瀛渌水，三变成田，西嶽靈桃，千載未子，尚以星起牵牛，苛［姑蘇志作蔀。］首迢遞，律生甲子，氣數杳冥，沈［姑蘇志作况。］复上遊玉清，損之又損，高排金闕，玄之又玄，豈言象之能筌，非時節之所辯，高巖鬱起，帶青雲而作峰，瀑水懸流，雜天河而俱洒，雖日門采藥之地，楚望懷椒之歌，陽反流沙之魂，錦識汾陰之鼎，無以喻書，銘曰：玉龟二始，金書八會，道浃地心，功浮天外，故帝可小，推真能大，德起同尘，善生塞兑，保物自然，人符交泰，掩映绿羅，穹隆紫蓋，仙冶［姑蘇志作治。］之美，此焉為最，雄柱千步，陽台百丈，水均下矚，山逾高掌，野寂雲興，禽繁山响，升虹［音絳。］夕栖，丰雷朝上，書藏玉柙，藥蘊銀筒，燒鉛雜鯉，折桂和葱，斧柯雖朽，碑石無窮。","sortOrder":122},
  {"id":"s_work_nvlt_78_123","chapterId":"ch_work_nvlt_78","text":"梁元帝南嶽衡山九真馆碑曰：箫鼓騰空，煙霞相接，星辰奪采，燈燭非明，風牖雲梁，千門萬戶，樓施九柱，已同賴乡之地，山帶五城，复類玄洲之所，玉版之經猶蘊，金丹之處存焉，上月台而遺愛，登景雲而忘老，欣欣然不知所以而然，日暉石瓦，東眺靈寿之峰，月荫玉床，西瞻華蓋之嶺，竹類黃金，既葳蕤而防露，木似紅莲，且芬披而拂日，杯傳九醞，隱淪之車晨至，堂开四扇，西楹之鍾夜响。","sortOrder":123},
  {"id":"s_work_nvlt_78_124","chapterId":"ch_work_nvlt_78","text":"又青溪山馆碑曰：原夫法象莫過於天地，著明莫過於日月，鼓之以雷電，润之以風雨，鹹秩無文，所以名山致祭，峻極於天，青溪山者，荆南之中嶽也，隱隱幹霄，亭亭無际，雲蓋三層，如在帝台之侧，桂林八树，非異景山之傍，輕霞亘起，影落照於陽溪，清風遠至，响猿鳴於巫峡，西臨百丈之穴，南帶千仞之水，洪源湛淡，長波萦复。","sortOrder":124},
  {"id":"s_work_nvlt_78_125","chapterId":"ch_work_nvlt_78","text":"梁沈約善馆碑曰：至道玄妙，無跡可尋，寄言立稱，已乖宗極，神宇靈房，於義非取，九仙緬邈，等級參差，或藏形洞府，或栖志靈嶽，達人獨往之事，志非易立，餐松飲涧之情，理難輕树，止欲漸去喧嚣，稍離尘雜，於是既加整葺，營建堂宇，北負崇嶽，南枕脩衢，回讬人表，雞犬相絕，庭流松响，戶接雲根，指琼树而朝餐，就瑤台而一息，霓裳不反，凫舄忘歸，朝九星，謁群帝，悠哉邈乎，與天地相畢矣。","sortOrder":125},
  {"id":"s_work_nvlt_78_126","chapterId":"ch_work_nvlt_78","text":"又桐柏山金庭馆碑曰：若夫上玄奧遠，言象斯絕，金簡玉字之書，玄霜絳雪之寶，俗士所不能窥，學徒不敢輕慕，非天禀上才，未易可擬，自惟凡劣，識鑒鮮方，早尚幽栖，屏弃情累，留愛林壑，讬分鳥魚，既遠出天台，定居茲嶺，所朅之山，實惟桐柏，仰出星河，上參倒景，高崖萬仞，邃涧千回，翘心屬念，晚臥晨起，采三芝而延佇，飛九丹而宴息，乘凫輕舉，留舄忘歸，銘曰：日為車馬，芝成宮觀，虹旌拂月，龍辀漸漢，萬春方華，千齡始旦。","sortOrder":126},
  {"id":"s_work_nvlt_78_127","chapterId":"ch_work_nvlt_78","text":"梁陶弘景許長史舊馆壇碑曰：悠哉曠矣，宇宙之靈也，固非言象所傳，文跡可記，嘿然則後之人奚聞乎，銘曰：昔在西漢，三茅來賓，爰暨東晉，二許懷真，裁其浚井，栖道接神，允膺辅聖，錫茲符震，勝殿密响，泻瓶楊芬，瑤宮碧簡，絢采垂文，琼函玉檢，綺席繡巾，蘭棋烈耀，金爐颺薰。","sortOrder":127},
  {"id":"s_work_nvlt_78_128","chapterId":"ch_work_nvlt_78","text":"又茅山長沙馆碑曰：夫萬象森羅，不離兩儀所育，百法紛凑，無越三教之境，搢绂之士，飾禮容於闈閤，耿介之夫，扬旌麾於門裔，銘曰：至哉乾元，萬物資始，皇王受命，三才乃理，惟聖感神，惟神降祉，德被歌鍾，名昭圖史，友於兄弟，敬惟西宣，言追茂實，用表遺先，敢巡舊製，有革雜章，刊字弗朽，弈代留芳。","sortOrder":128},
  {"id":"s_work_nvlt_78_129","chapterId":"ch_work_nvlt_78","text":"又太平山日門馆碑曰：日門馆者，東霞啟暉，开巖引燭，以為名也，先是吳郡杜徵君，聲高兩代，德冠四區，教義宣流，播乎數郡，拓宇太平之東，結架菁山之北，爰以此處幽奇，別就基構，栖集有道，多歷世年。","sortOrder":129},
  {"id":"s_work_nvlt_78_130","chapterId":"ch_work_nvlt_78","text":"陳沈蜅林屋馆記曰：夫玄之又玄，處眾妙之極，可乎不可，成道行之致，斯蓋寂寥窅冥，希微恍惚，故非淮南八仙之圖，賴乡九井之記，至若崑山平圃，銀榜相暉，蓬阆仙宮，金台崛起，南瞰胥台，傍連飛閣，桂柱星羅，琼軒雲構，銘曰：大道既隱，眾聖無門，悠悠大極，誰見玄根，祈年立秦，望仙表漢，仿佛神靈，依俙宮觀，峨峨林屋，輪奐徘徊，庭羅花鳥，室靜尘埃。","sortOrder":130},
  {"id":"s_work_nvlt_78_131","chapterId":"ch_work_nvlt_78","text":"陳徐陵天台山馆徐則法師碑曰：夫海水扬尘，幾千年而可見，天衣拂石，幾萬歲而應平，至人者，譬彼晨昏，方乎晷刻，固非俗士之所能言，寰中之所能量者也，至如不死之草，猶稱南裔，長生之树，尚挺西崑，百紀遊龟，皆登莲葉，千齡寿鶴，或舞松枝，假矣生民，何其夭脆，譬彼風電，同諸泡沫，琢火之叹，聞諸往賢，逝水之悲，嗟乎前聖，樵人看博，信未始乎淹留，仙客彈琴，固不移於俄頃，然而子孫皆其數世，乡党鹹為草萊，是以志士名賢，飄然長鶩，臊膻榮利，〈厭心〉〈足歲〉風尘，服冕乘軒，其猶桎梏，朱庭紫閤，事甚籠樊，隱淪巖洞，餐餌芝髓，忽矣身輕，俄然羽化，金繩玉版，受謁帝之符，龍駕霓裳，處仙宮之箓，法師萧然道氣，卓矣仙才，千仞孤摽，萬頃無度，所以伊川控鶴，葉縣乘凫，靈化無方，去還斯在，銘曰：來去三鳥，賓遊二童，然香雨上，击磬雲中，玉粒雖软，金膏未鎔，方流道業，濟彼昏蒙。","sortOrder":131},
  {"id":"s_work_nvlt_78_132","chapterId":"ch_work_nvlt_78","text":"【銘】梁陶弘景茅山曲林馆銘曰：層嶺外峙，邃宮內映，仄穴旁通，榮泉遠鏡，尚德依仁，祈生翊命，且天且地，若凡若聖，連甍比棟，各謂知道，參差經術，跌宕辭藻，孰曰曲林，獨為劲好，奄跡韜功，守茲偕老。","sortOrder":132},
  {"id":"s_work_nvlt_78_133","chapterId":"ch_work_nvlt_78","text":"周王裒靈壇銘併序曰：悠悠五緯，乃钦若於尧典，茫茫九州，爰致功於禹跡，猶以天步懸遠，隸首筭而弗窮，地載遐荒，章亥馳而未極，浩庭霄度，吐納天和，崑阆沧溟，胞胎元一，九靈之府，神液所以降祥，五英之闕，蓂華以之昭應，推劫運之短長，校河源之廣狹，穀永上書，譬流風之不系，桓谭作論，明弱水之難航，豈知回天金簡，惟傳上聖，洞神玉策，尚隔中仙，於時金風戒辰，三光澄曜，香雨乘空，天花入室，帝乃升法座，說玄言，肴覆洞微，闡扬眾妙，洪鍾應叩，衢樽待酌，銘曰：鍾鳴上界，梵响玄宮，紫辰濯水，青树搖風，八覺修行，七教弘通，神機詣理，秋毫坼空，函席廣开，法輪徐轉，入神精義，談天勝辯，逐境晦明，逗機深淺，或照盛業，方圖雲篆。","sortOrder":133},
  {"id":"s_work_nvlt_78_134","chapterId":"ch_work_nvlt_78","text":"又馆銘曰：雲桥啟馆，景曜开扉，明庭朝禮，仙宮羽衣，燕履霄去，凫菭晨歸，練石三轉，燒丹七飛，崑吾陶鑄，丹楊鋈铣，盡寫龍文，圖开彫篆，聲隨地氣，調均天辯，九宮方應，萬靈稱善。","sortOrder":134},
  {"id":"s_work_nvlt_78_135","chapterId":"ch_work_nvlt_78","text":"【書】梁沈約與陶弘景書曰：先生糠秕俗流，超然獨遠，烈霓羽帶，總辔雲霞，方當名書絳簡，身遊玄闕，凭星夕臥，望日朝餐，而至理深微，曖焉難睹，惟欲下風問道，未知厥路，若夫栖遲閒遠，咀咽琼芝，出入清都，師友靈聖，循崖反跡，無缺惟心。","sortOrder":135},
  {"id":"s_work_nvlt_78_136","chapterId":"ch_work_nvlt_78","text":"梁陶弘景答朝士訪仙佛兩法體《相書》曰：某等曰：嘗竊觀仙書，辄嗟欣忘倦，徒羨其文，莫测其理，尋七尺之體，既同禀太始，俱服五常，以何因緣，獨超青雲而弊金石者乎，先生領袖玄門，學窮仙苑，必有以竭其川岸，請略聞雅說，隱居答曰：至哉嘉訊，豈蒙生所辯，雖然，试言之，若直推竹柏之匹桐柳者，此本性有殊，非今日所論，若引庖刀湯稼，從養溉之功者，此又止其所從，終無永固之期，夫得仙者，併有異乎此，但斯族复有數种，今且談其正體，凡质像所結，不過形神，形神合時，則是人是物，形神若離，則是靈是鬼，其非離非合，佛法所攝，亦離亦合，仙道所依，今問以何能而致此，仙是鑄練之事極，感变之理通也，當埏埴以為器之時，是土而異於土，雖燥未燒，遇濕猶坏，燒而未熟，不久尚毀，火力既足，表里堅固，河山可盡，此形無滅，假令為仙者，以藥石練其形，以精靈瑩其神，以和氣濯其质，以善德解其纏，眾法共通，無礙無滯，欲合則乘雲駕龍，欲離則尸解化质，不離不合，則或存或亡，於是各隨所業，脩道進學，漸階無窮，教功令滿，亦畢竟寂滅矣。","sortOrder":136},
  {"id":"s_work_nvlt_78_137","chapterId":"ch_work_nvlt_78","text":"【論】魏陳王曹植辯道論曰：世有方士，吾王悉所招致，甘陵有甘始，庐江有左慈，陽城有郄俭，始能行氣导引，慈晓房中之術，［冯校本術上有玄字。］俭善辟穀，悉號數百歲，所以集之魏國者，誠恐此人之徒，接奸诡以欺眾，行妖惡以惑民，豈复欲觀神山於瀛洲，求安期於邊海，釋金辂而顧雲舆，弃文骥而羨飛龍哉，夫帝者位殊萬國，富有天下，威尊彰明，齊光日月，宮殿闕庭，等耀紫微，何顧乎王母之宮，崑崙之域哉，夫三乌備役，不如百官之美也，素女姮娥，不若椒房之麗也，雲衣羽裳，不若黼黻之飾也，駕螭載霓，不若乘舆之盛也，琼蕊玉華，不若玉圭之絜也，而顧為匹夫所罔，納虛妄之辭，信眩惑之說，隆禮以招弗臣，傾產以供虛求，散王爵以榮之，清閒馆以居之，經年累稔，終無一验，雖复誅其身，滅其族，紛然足為天下笑矣，若夫玄黃所以娱目，铿鎗所以樂耳，媛妃所以紹先，刍豢所以悅口也，何必甘無味之味，聽無聲之樂，觀無采之色乎。","sortOrder":137},
  {"id":"s_work_nvlt_78_138","chapterId":"ch_work_nvlt_78","text":"晉庾闡列仙論曰：夫無怪物之所以，然後可以通於命，以達变化之情者，不怪诡於異端，测自然之根者，不猖狂於一物，故形骸雖細，推之愈廣，天地雖巨，別之弥狹，然則形骸華岱之秋毫，太虛天地之掌握耳。又何足以言其变化哉。又若秦皇漢武，體無靈骨，雖懷奇化，絳［疑當作終。］於尸没，傾天下之資，忽萬乘之位，方士輻凑，萬端鱗萃，無救於頹年，終無補於一至，若天［疑當作夫。］禀分有方，［雲雲。］","sortOrder":138},
  {"id":"s_work_nvlt_78_139","chapterId":"ch_work_nvlt_78","text":"《藝文類聚》　唐·欧陽詢","sortOrder":139},
  {"id":"s_work_nvlt_79_1","chapterId":"ch_work_nvlt_79","text":"卷七十九靈異部下","sortOrder":1},
  {"id":"s_work_nvlt_79_2","chapterId":"ch_work_nvlt_79","text":"○神夢魂魄","sortOrder":2},
  {"id":"s_work_nvlt_79_4","chapterId":"ch_work_nvlt_79","text":"《左傳》曰：有神降於莘，惠王問諸內史過曰：是何故也，對曰：國之將興，明神降之，監其德也，將亡，神又降之，觀其惡也，故有得神以興，亦有以亡，虞夏商周皆有之。","sortOrder":4},
  {"id":"s_work_nvlt_79_5","chapterId":"ch_work_nvlt_79","text":"《山海經》曰：西海水赤，有章尾山，有神人面蛇身而赤，身長千尺，其眠乃晦，其视乃明，不食不寢，風雨是謁，［能請致風雨。］是謂燭龍。","sortOrder":5},
  {"id":"s_work_nvlt_79_6","chapterId":"ch_work_nvlt_79","text":"又曰：蚩尤作兵，犯黃帝，黃帝乃令應龍攻於冀州之野，蚩尤謂［太平御覽八百八十二作請。］風伯，所從大風雨，黃帝乃下天女妖，止雨，遂殺蚩尤，妖不得复上，故所居不雨。","sortOrder":6},
  {"id":"s_work_nvlt_79_7","chapterId":"ch_work_nvlt_79","text":"三齊略記曰：始皇作石桥，欲過海觀日出處，於時有神人，能驅石下海，城陽一山石，盡起立，嶷嶷東傾，状似相隨而去，雲石去不速，神人辄鞭之，盡流血，石莫不悉赤，至今猶爾。","sortOrder":7},
  {"id":"s_work_nvlt_79_8","chapterId":"ch_work_nvlt_79","text":"又曰：始皇於海中作石桥，非人功所建，海神為之竖柱，始皇感其惠，通敬其神，求與相見，海神答曰：我形丑，莫圖我形，當與帝會，乃從石塘上入海三十餘里相見，左右莫動手，巧人潛以腳畫其状，神怒曰：帝負我約，速去，始皇轉馬還，前腳猶立，後腳隨崩，仅得登岸，畫者溺於海，眾山之石皆住，今猶岌岌，無不東趣。","sortOrder":8},
  {"id":"s_work_nvlt_79_9","chapterId":"ch_work_nvlt_79","text":"《史記》曰：伍子胥死，吳人怜之，為立祠於江上，因名曰胥山。","sortOrder":9},
  {"id":"s_work_nvlt_79_10","chapterId":"ch_work_nvlt_79","text":"又曰：始皇西南渡淮，之衡山南郡，浮江至湘山祠，逢大風，幾不得渡，上問博士曰：湘君何神，對曰：聞尧女舜之妻也，而葬於此，於是始皇大怒，使刑徒三千人，伐湘山树，赭其山上。","sortOrder":10},
  {"id":"s_work_nvlt_79_11","chapterId":"ch_work_nvlt_79","text":"《列女傳》曰：舜陟方，死於蒼梧，二妃葬於江湘之間，俗謂之湘君。","sortOrder":11},
  {"id":"s_work_nvlt_79_12","chapterId":"ch_work_nvlt_79","text":"《搜神記》曰：蒋子文者，廣陵人也，嗜酒好色，常自謂己骨清，死當為神，漢末為秣陵尉，逐賊至於鍾山之下，賊击傷額，因解綬以縛之，有頃遂死，及吳先主之初，其吏見文於道，乘白馬，執白羽扇，侍從如平生，文曰：我當為此土地神也，為吾立祠，不爾，使虫入耳為灾，吳主以為妖言，後果有虫入人耳，皆死，医不能治。又雲，不祠我，將有大火，是歲數有大火，吳主患之，封為都中侯，加印綬，立廟堂，改鍾山為蒋山，以表其靈也。","sortOrder":12},
  {"id":"s_work_nvlt_79_13","chapterId":"ch_work_nvlt_79","text":"又曰：濟北絃超，嘉平中，夜夢神女從之，自稱天上玉女，東郡人，姓成公，字智琼，早失母，天帝哀其孤苦，令得下嫁從夫，當其夢也，嘉喜非常，覺寤钦想，如此三夕四旦，顯然來遊，駕辎軿車，從八婢，服綾羅綺繡，状若飛仙，自言年十七，遂為夫婦，赠詩曰：飄飖浮勃述，敖曹雲石滋，神仙豈虛降，應運來相之。","sortOrder":13},
  {"id":"s_work_nvlt_79_14","chapterId":"ch_work_nvlt_79","text":"又杜蘭香別傳曰：杜蘭香，自稱南陽人，以建興四年春，數詣張傳，傳年十七，望見其車在門外，婢通言，阿母所生，遣授配君，君可不敬從，傳先改名硕，硕呼女前，视可十八九，說事邈然久遠，有婦子二人，大者萱支，小者松支，钿車青牛，上飲食皆備，作詩曰：阿母處靈嶽，時遊雲霄际，眾女侍羽儀，不出墉宮外，飄輪送我來，豈复恥尘秽，從我與福俱，嫌我與禍會，至其年八月旦來，复作詩曰：逍遙雲霧間，呼嗟發九嶷，流汝不稽路，弱水何不之，出署豫子三枚，大如雞子，雲，食此，令君不畏風波，辟寒溫，硕食二，欲留一，不肯，令硕盡食，言本為君作妻，情無曠遠，以年命未合，其小乖，太歲東方卯，當還求君。","sortOrder":14},
  {"id":"s_work_nvlt_79_15","chapterId":"ch_work_nvlt_79","text":"王隱《晉書》曰：镇南劉弘，以故刺史王毅子衡陽太守矩為廣州，矩至長沙，見一人長大，著布单衣，自持奏在岸上，矩省奏雲，京兆杜靈之，仍入舡共語，稱叙希闊，矩問君京兆人，何時發來，答曰：朝發，矩怪京兆去此數千，那得朝發今到，杜答雲，仆天上京兆，去此乃數萬，何止數千乎。","sortOrder":15},
  {"id":"s_work_nvlt_79_16","chapterId":"ch_work_nvlt_79","text":"《異苑》曰：衡陽山九嶷，皆有舜廟，漢世零陵文學姓奚，於泠道縣舜祠下，得笙玉管，舜時西王母獻。","sortOrder":16},
  {"id":"s_work_nvlt_79_17","chapterId":"ch_work_nvlt_79","text":"又曰：陆機初入洛，次河南之郾師，時夕，望道左若有民居，因往逗宿，見一年少，神姿端達，與機言玄門妙物，機心伏其能，無以詶抗，機提緯古今，總验名實，此年少不堪欣解，既晓便去，機稅驂逆旅，逆旅嫗曰：此東數十里無村落，止有山陽王家墓耳，機乃怪，怅然，還睇昨路，空野霾雲，栱木蔽日，知所遇者信王弼墓也。","sortOrder":17},
  {"id":"s_work_nvlt_79_18","chapterId":"ch_work_nvlt_79","text":"又曰：吳相伍員廟，永嘉中，吳郡人叔父為台郎，在洛，值京都傾覆，歸涂阻塞，當濟江，南風不得進，既投奏，即日得渡。","sortOrder":18},
  {"id":"s_work_nvlt_79_19","chapterId":"ch_work_nvlt_79","text":"又曰：長沙羅縣，有屈原自投之川，山水明净，異於常處，民為立廟，在汨潭之西，岸侧盤石，馬跡尚存，相傳雲，原投川之日，乘白骥而來。","sortOrder":19},
  {"id":"s_work_nvlt_79_20","chapterId":"ch_work_nvlt_79","text":"《幽明錄》曰：王辅嗣註易，辄笑鄭玄為儒，雲老奴無意，王時夜分，忽然聞外閤有著屐聲，須臾進，自雲鄭玄，责之曰：君年少，何以輕穿文凿句，而妄譏誚老子耶，極有忿色，言竟便退，辅嗣心生畏惡，少年遇厲疾而卒。","sortOrder":20},
  {"id":"s_work_nvlt_79_21","chapterId":"ch_work_nvlt_79","text":"【詩】梁簡文帝祠伍員廟詩曰：去國資孝本，循忠全令名，舟里多奇計，芦中复吐誠，偃月交吳艦，魚麗入楚營，光功摧妙筭，手載籍餘聲，洪涛猶鼓怒，靈廟尚凄清，行潦承椒奠，按歌雜鳳笙，無勞晉後璧，詎用楚臣纓，密树臨寒水，疏扉望遠城，窗寮野霧入，衣帳積苔生，惟有三青鳥，斂翅時逢迎。","sortOrder":21},
  {"id":"s_work_nvlt_79_22","chapterId":"ch_work_nvlt_79","text":"梁劉遵和簡文帝赛漢高帝廟詩曰：分蛇纶霸跡，提劍滅雄威，空餘清祀處，無复瑞雲飛，仙車照丹穴，霓裳影翠微，投玦要漢女，吹管召湘妃，幸逢懷精日，豫奉沐休歸。","sortOrder":22},
  {"id":"s_work_nvlt_79_23","chapterId":"ch_work_nvlt_79","text":"梁徐陵和詩曰：山宮類牛首，漢寢若龍川，玉碗無秋酎，金燈滅夜煙，丹帷迫靈嶽，绀席下群仙，堂空沛筑响，釵低戚舞妍，何殊後廟里，子建作華篇。","sortOrder":23},
  {"id":"s_work_nvlt_79_24","chapterId":"ch_work_nvlt_79","text":"梁劉孝儀和詩曰：珪幣崇明祀，牲樽禮貴神，風驚如集廟，光至似來陳，徘徊靈駕入，叫咷倡歌新，將言非為己，致敬乃祈民，多才與多事，今古獨為鄰。","sortOrder":24},
  {"id":"s_work_nvlt_79_25","chapterId":"ch_work_nvlt_79","text":"梁王台卿和詩曰：沐芳事椒糈，駕言遵寿宮，瑤台斜接岫，玉殿上凌空，树出垂巖影，竹引帶山風，階長霧難歇，窗高雲易通，所悲樽俎撤，按歌曲未終。","sortOrder":25},
  {"id":"s_work_nvlt_79_26","chapterId":"ch_work_nvlt_79","text":"梁王僧孺湘夫人詩曰：桂棟承薜帷，眇眇川之湄，白蘋徒可望，绿芷竟空滋，日暮思公子，衔意嘿無辭。","sortOrder":26},
  {"id":"s_work_nvlt_79_27","chapterId":"ch_work_nvlt_79","text":"【賦】楚宋玉高唐賦曰：楚襄王與宋玉遊於雲夢之台，望高唐之觀，其上獨有雲氣，崒兮直上，忽兮改容，須臾之間，变化無窮，王問玉曰：此何氣也，玉對曰：所謂朝雲者也，昔者先王嘗遊高唐，怠而晝寢，夢婦人曰：妾巫山之女也，為高唐之客，聞君遊高唐，原荐枕席，王因幸之，去辭曰：妾在巫山之陽，高丘之阻，旦為朝雲，暮為行雨，朝朝暮暮，陽台之下，朝视之如言，故為立廟，號曰朝雲，始出状若何，玉對曰：其少進也，晢兮若妖姬扬袂障日而望所思，忽兮改容，偈兮若駕驷馬而建羽旗，湫兮如風，凄兮如雨，風止雨霁，雲無處所，惟高唐之大體，殊無物類之可儀比，巫山赫其無畴，道互折而曾累，遇天雨之新霁，觀百穀之俱集，濞汹汹其無聲，潰淡淡而併入，中阪遙望，玄木冬榮，煌煌晔晔，奪人目精，烂兮若列星，曾不可殫形，绿葉紫裹，朱茎白蒂，纖條悲鳴，聲似竽籁，清濁相和，五变四會，感心動耳，回腸傷氣，長吏隳官，賢士失志，愁思無已，叹息垂淚，王乃乘玉舆，驷蒼螭，於是乃縱獵者，基趾如星，傳言羽獵，衔枚無聲，蜺為旌，翠為蓋，風起雨止，千里而逝。","sortOrder":27},
  {"id":"s_work_nvlt_79_28","chapterId":"ch_work_nvlt_79","text":"又神女賦曰：楚襄王與宋玉進於雲夢之浦，使玉賦曰：高唐之事，其夜王寢，夢與神女遇，其状甚麗，王異之，明日以白玉曰：其始來也，曜乎若白日初出照屋梁，其少進也，皎若明月舒其光，須臾之間，美貌橫生，燁乎如華，溫乎如瑩，五色併施，不可殫形，振繡衣，被袿裳，醲不短，纖不長，步裔裔兮曜殿堂，忽兮改容，婉若遊龍，乘雲翔，何神女之妖麗，合陰陽之渥飾，被華藻之可好，若翡翠之奋翼，毛嫱障袂，不足程式，西施掩面，比之無色，望餘帷而延视，若流波之將澜，奋長袖以正衽，立踯躅以不安，意似近而既遠，若將來而复旋，褰餘帱而請御，顧女師，命大傅，歡情未接，將辭而去，遷延引身，不可親附。","sortOrder":28},
  {"id":"s_work_nvlt_79_29","chapterId":"ch_work_nvlt_79","text":"魏陳王曹植《洛神賦》曰：黃初三年，餘朝京師，還濟洛川，古人有言，斯水之神，名曰宓妃，感宋玉對楚王說神女之事，其辭曰：餘從京域，言歸東藩，背伊闕，越轘轅，經通穀，凌景山，稅駕乎蘅皋，秣驷乎芝田，容與乎楊林，流盻乎洛川，於是精移神駭，忽焉思散，俯則未察，仰以殊觀，睹一麗人，於巖之畔，其形也翩若驚鸿，婉若遊龍，榮曜秋菊，華茂春松，仿佛兮若輕雲之蔽月，飄飖兮若流風之回雪，遠而望之，皎若太陽升朝霞，迫而察之，灼若芙蕖出绿波，浓纖得衷，脩短合度。","sortOrder":29},
  {"id":"s_work_nvlt_79_30","chapterId":"ch_work_nvlt_79","text":"魏陳琳神女賦曰：漢三七之建安，荆野蠢而作仇，贊皇師以南假，濟漢川之清流，感詩人之攸叹，想神女之來遊，儀營魄於仿佛，讬嘉夢以通精，望陽侯而瀇瀁，睹玄麗之軼靈，文絳虬之弈弈，鳴玉鸞之嘤嘤，答玉质於苕華，擬艳姿於蕣榮，感仲春之和節，叹鳴雁之噰々，申握椒以貽予，請同宴乎奧房，苟好樂之嘉合，永絕世而獨昌，既叹爾以艳采。又悅我之長期，順乾坤以成性，夫何若而有辭。","sortOrder":30},
  {"id":"s_work_nvlt_79_31","chapterId":"ch_work_nvlt_79","text":"魏王粲神女賦曰：惟天地之普化，何產氣之淑真，陶陰陽之休液，育夭麗之神人，禀自然以絕俗，超希世而無群，體纖約而才足，膚柔曼以丰盈，發似玄鑒，鬢類刻成，戴金羽之首飾，珥昭夜之珠璫，袭羅綺之黼衣，曳縟繡之華裳，错繽紛以雜袿，佩熠爚而焜煌，退变容而改服，冀致態以相移，稅衣裳兮免簪笄，施華的兮結羽儀，扬娥微盻，懸藐流離，婉約綺媚，舉動多宜，稱詩表志，安氣和聲，探懷授心，發露幽情，彼佳人之難遇，真一遇而長別，顧大罰之淫愆，亦終身而不滅，心交戰而貞勝，乃回意而自絕。","sortOrder":31},
  {"id":"s_work_nvlt_79_32","chapterId":"ch_work_nvlt_79","text":"魏楊脩神女賦曰：惟玄媛之逸女，育明曜乎皇庭，吸朝霞之芬液，澹浮遊乎太清，餘執義而潛厲，乃感夢而通靈，盛容飾之本艳，奐龍采而鳳榮，翠黼翚裳，纖縠文袿，順風揄扬，乍合乍離，飄若興動，玉趾未移，詳觀玄妙，與世無双，華面玉粲，韡若芙蓉，膚凝理而琼絜，體鮮弱而柔鸿，回肩襟而動合，何俯仰之妍工，嘉今夜之幸遇，獲帷裳乎期同，情沸踴而思進，彼嚴厲而靜恭，微諷說而宣諭，色歡怿而我從。","sortOrder":32},
  {"id":"s_work_nvlt_79_33","chapterId":"ch_work_nvlt_79","text":"晉張敏神女賦曰：世之言神仙者多矣，然未之或验也，至如絃氏之婦，則近信而有證者，夫鬼魅之下人也，無不羸病損瘦，今義起平安無恙，而與神女飲宴寢處，縱情極意，豈不異哉，餘覽其歌詩，辭旨清伟，故為之作賦，皇覽餘之純德，步朱闕之峥嵘，靡飛除而入秘殿，侍太極之穆清，帝愍餘之勤肅，將休餘於中州，讬玄靜以自處，寔應夫子之好仇，於是主人怃然而問之曰：爾豈是周之褒姒，齊之文薑，孽婦淫鬼，來自藏乎，傥亦漢之遊女，江之娥皇，厭真愆，倦仙侍乎，於是神女乃斂袂正襟而對曰：我實貞淑，子何猜焉，且辯言知禮，恭為令則，美姿天挺，盛飾表德，以此承歡，君有何惑，爾乃敷茵席，垂組帳，嘉旨既設，同牢而饗，微聞芳泽，心荡意放，於是尋房中之至嬿，極長夜之懽情，心眇眇以忽忽，想北里之遺聲，賦斯時之要妙，進伟服之紛敷，俯撫衽而告辭，仰長叹以欷吁，乘雲霧而变化，遙弃我其焉如。","sortOrder":33},
  {"id":"s_work_nvlt_79_34","chapterId":"ch_work_nvlt_79","text":"晉楊該三公山下神祠賦曰：南極鬱紆，飛龍在天，太一白石，巨靈據山，二後殊位，惟公在焉，下則歸雲縫勃，绿水流離，爭湍趣戾，冲石會谿，高岸為穀，峣〈山兒〉阻〈危支〉，梗林柰條，逼涂迮蹊，行者息駕，步趾於斯，陟大〈山錄〉，登岑岡，逾爽垲，歷朝陽，晔華殿之顯敞，睹應門之嶈々，神木鬱蓊，百堵周乎洞房，進排閶阖，顧盻靈堂，聚楹列峙，丹飾煌煌，千栌浮跂，夭蹻騰驤，累層岌嶪，齊載長梁，敷山藻於前棁，缀榱槁以采章，文綺雘其紛鱗，洪葩晔之披楊，爾乃逡巡降趾，遊坐東厢，日不逮昏，炎燎已光，縣宰致祀，嘉旨備詳，陰祚顯應，偏泽圻疆，普此士女，樂彼丰穰。","sortOrder":34},
  {"id":"s_work_nvlt_79_35","chapterId":"ch_work_nvlt_79","text":"宋謝靈運江妃賦曰：招魂定情，洛神清思，单曩日之敷陳，盡古來之妍媚。矧今日之逢逆，邁前世之靈異，姿非定容，服無常度，兩宜歡嚬，俱適華素，於時升月隱山，落日映岐，收霞斂色，回飆拂渚，每馳情於晨暮，矧良遇之莫叙，投明瑱以申赠，顗色授而魂與，况分岫湘岸，延情蒼陰，隔山川之表里，判天地之浮沉，承嘉約於往昔，寧更貳於在今，傥借訪於交甫，知斯言之可諶，蘭音未吐，紅顏若辉，留盻光溢，動袂芳菲，散雲辔之絡驿，按靈辎而徘徊，建羽旌而逶迤，奏情管之依微，慮一別之長絕，眇天末而永违。","sortOrder":35},
  {"id":"s_work_nvlt_79_36","chapterId":"ch_work_nvlt_79","text":"梁江淹水上神女賦曰：江上丈夫，遊宦荆吳，首衛國，望燕路，歷秦關，出宋都，遍覽下蔡之女，且說淇上之姝，乃造南中，度炎州，經玉涧，越金流，路逶迤而無軌，野忽漠而鮮儔，既而精飛视亂，意去心移，倚靡{艹陵}蓋，怅望蕙枝，一麗女子，碧渚之崖，冶異絕俗，奇麗不常，青琴羞艳，素女慚光，恨精影之不滯，悼光晷之難借，閱有無於俄頃，验变化於咫尺，野田田而虛翠，水湛湛而空碧，乃唱桂棹，陵冲波，背橘浦，向椒阿，苟懸天子有命，永離訣其若何。","sortOrder":36},
  {"id":"s_work_nvlt_79_37","chapterId":"ch_work_nvlt_79","text":"【碑】梁簡文帝吳興楚王神廟碑曰：昔者武王詢於太公，五神之禮正，伊陟贊於巫鹹，三篇之義作，抑又玄矩司於坎宮，漢興北畤，黃蛇感於通夢，秦作西郊，幽則鬼神，其來已尚，楚王既弘茲釋教，併止獻車牛，既舍黃駒，安俟骍角，掌击無左涤之勞，牧人止楅衡之務，周房殷俎，惟有玄涧芳芝，玉斝瑤樽，止陳丹桂清酌，漸符不殺之教，方行大士之心，比夫黃树赤光，紫衣朱葛，蔑矣哉，王製雲，山川神祇，有不舉者，為不敬，太守元景仲，稽諸古典，於茲往烈，永傳不朽，式树高碑，翠石勒文，事偕神掌，靈龟負字，還擬洛書。","sortOrder":37},
  {"id":"s_work_nvlt_79_38","chapterId":"ch_work_nvlt_79","text":"【祭文】齊謝朓祭文［文字疑衍。］大雷周何二神文曰：大過在運，小雅盡缺，琼鏡曰淪，金車未晢，周生電斷，神謨英冠，正因部奇，風斂雲散，晉德如毀，功資葉贊，山無猛鷙，時曠忠賢，流王於彘，龟鼎忽焉，忠肅布衣，君親自然，驅狐上國，斬鲵中川，紛纶凯入，氛氲配天。","sortOrder":38},
  {"id":"s_work_nvlt_79_39","chapterId":"ch_work_nvlt_79","text":"梁邵陵王祀魯山神文曰：敬奠魯君之靈，竊以首山鬱律，表二叔之清風，趙國隱淪，擅三公之靈跡，北坂祠城，流光夜起，東嶺丛室，甘雨晝零，故能徵應不褰，介福無爽，金壇玉宇，是眾妙之遊遨，丹崖翠幄，信靈人之响像，霓裳孔蓋，轉日車而競前，駕象乘豹，載靈旗而總集，江妃漢女，含睇來趨，湘娥洛嫔，宜言在侧，鳴璆撫劍，俠席徘徊，絳節陳竽，滿堂繁會，奠椒懷糈之歡，傳已代舞之樂，桂醑溢於羽樽，蕙肴盈於蘭藉，既醉既飽，景福攸同，不震不騰，神保是格，炰胾之荐已畢，慶報之泽攸先，原化昌而俗阜，俾多祐之在旃，同匪石之無轉，欣滯穗之有年，惟東皇兮戾止，等南山而不騫。","sortOrder":39},
  {"id":"s_work_nvlt_79_40","chapterId":"ch_work_nvlt_79","text":"梁沈約赛蒋山廟文曰：我皇體天御宇，望日表尊，備樂变乎笙镛，鬱禮華於俎豆，邇無不懷，遠無不肅，鳥革玄素之容，草移丹绿之状，泉露改味，日月重光，仰惟大王，年逾二百，世兼四代，扬玉桴，布瑤席，秦梁楚趙之巫，把琼茅而延佇，燕衛宋鄭之音，結流風而成曲，九疑之來蔽日，三山之駕若雲。","sortOrder":40},
  {"id":"s_work_nvlt_79_42","chapterId":"ch_work_nvlt_79","text":"《周書》曰：大姒夢見商之庭產棘，太子發取周庭之梓树於闕，梓化為松柏棫柞，寐覺，以告文王，文王乃召太子發，占之於明堂，王及太子發，併拜吉夢，受商之大命於皇天上帝。","sortOrder":42},
  {"id":"s_work_nvlt_79_43","chapterId":"ch_work_nvlt_79","text":"《東觀漢記》曰：諸將勸光武立，乃召冯異，上曰：我夢乘龍上天，覺悟，心中動悸，異因下席再拜贺曰：此天命發於精神，心中動悸，大王重慎之性也，異遂與諸將定議，上尊號。","sortOrder":43},
  {"id":"s_work_nvlt_79_44","chapterId":"ch_work_nvlt_79","text":"又曰：和憙皇後，常夢扪天，體荡荡正青，滑有若鍾乳，後仰吸之，以訊占夢，言尧夢攀天而上，湯夢反［東觀漢記作及。］天舐之，此皆聖王之夢。","sortOrder":44},
  {"id":"s_work_nvlt_79_45","chapterId":"ch_work_nvlt_79","text":"《莊子》曰：宋元君夜夢人披發，雲，予為清江使河伯之所，漁者豫且得予，元君覺，使人占之，曰：此神龟也，君曰：漁者有豫且乎，左右曰：有，明日，豫且朝，君曰：漁何得，對曰：且之網得白龟，圓五尺，君曰：獻若之龟，龟至，君再欲殺，再欲活，心疑，卜之曰：殺龟以卜吉，乃刳龟，七十鑽而無遺筴，仲尼曰：神能夢於元君，而不能避豫且之網，智能七十鑽無遺筴，不能避刳腸之患，如是則智有所困，神有所不及。","sortOrder":45},
  {"id":"s_work_nvlt_79_46","chapterId":"ch_work_nvlt_79","text":"《呂氏春秋》曰：孔子窮乎陳蔡之間，藜羹不糝，七日不嘗粒，晝寢，顏回索米得而來，爨之幾熟，孔子望見回，攫其甑中而飯之，食熟，謁孔子而進之，孔子起曰：今者夢見先君，食絜欲饋，顏回對曰：不可，乡食埃煤入甑中，弃食不祥，因攫而飯之，埃煤，煙尘煤也。","sortOrder":46},
  {"id":"s_work_nvlt_79_47","chapterId":"ch_work_nvlt_79","text":"又曰：尹儒學御，三年，而無得焉，夜夢受秋駕於師，明日往朝其師，而謂之曰：吾非愛道也，恐子之未可予也，今日將教子以秋駕，［秋駕，御法。］尹儒反走，北面再拜曰：今昔臣夢受之，先為其師言所夢，固秋駕也。","sortOrder":47},
  {"id":"s_work_nvlt_79_48","chapterId":"ch_work_nvlt_79","text":"謝承《後漢書》曰：范式，字巨卿，與張元伯為友，式仕郡為功曹，後夢元伯，玄冠垂纓屣，呼曰：我死，當以時葬，永歸黃泉，子不我忘，豈能奔丧，式便馳往赴之。","sortOrder":48},
  {"id":"s_work_nvlt_79_49","chapterId":"ch_work_nvlt_79","text":"袁宏漢紀曰：溫序為護羌校尉，為隗嚣所殺，世祖詔洛陽城傍為冢，長子寿為印［後漢紀五作邹。］平侯，［後漢紀侯下有相字。］夜夢序告之曰：久客思乡，寿即弃官，上書歸葬。","sortOrder":49},
  {"id":"s_work_nvlt_79_50","chapterId":"ch_work_nvlt_79","text":"皇甫謐《高士傳》曰：桓帝好老子之書，夜夢見老子，乃詔陳相為老子立祠。","sortOrder":50},
  {"id":"s_work_nvlt_79_51","chapterId":"ch_work_nvlt_79","text":"范晔《後漢書》曰：蔡茂，夢見太極殿上有三穗禾，茂跳取之，得其中穗，辄复失之，以問主簿郭贺，贺因離席慶曰：大殿者，宮府之形像也，極而有禾，人臣之上祿也，取其中穗者，是台之位，於字禾失為秩也，旬月而茂徵焉，乃辟贺為掾。","sortOrder":51},
  {"id":"s_work_nvlt_79_52","chapterId":"ch_work_nvlt_79","text":"《續漢書》曰：鄭玄夢孔子造之曰：起起，今年歲在辰，來年歲在巳，既寤，以讖言合之，知命當終，有頃，寢疾而卒。","sortOrder":52},
  {"id":"s_work_nvlt_79_53","chapterId":"ch_work_nvlt_79","text":"辛氏《三秦記》曰：崑明池，漢武帝之習水戰，中有靈沼神池，雲尧時洪水訖，停舡此池，池通白鹿原，人釣魚於原，纶絕而去，魚夢於武帝，求去其鉤，明日，帝戲於池，見大魚衔索，帝曰：豈非昨所夢乎，取魚，去其鉤而放之。","sortOrder":53},
  {"id":"s_work_nvlt_79_54","chapterId":"ch_work_nvlt_79","text":"陆機《晉書》曰：王濬夢懸四刀於其壁上，濬問主簿李毅，毅拜曰：夫三刀為州，而今益一，明府其臨益州乎，［事具軍器部。］","sortOrder":54},
  {"id":"s_work_nvlt_79_55","chapterId":"ch_work_nvlt_79","text":"王隱《晉書》曰：陶侃，字士衡，鄱陽人，少漁於雷泽，夢背上生翅，飛入天門，見門非常，不敢入而下。","sortOrder":55},
  {"id":"s_work_nvlt_79_56","chapterId":"ch_work_nvlt_79","text":"【賦】後漢王延寿夢賦曰：餘夜寢息，乃有非恒之夢，其為夢也，悉睹鬼神之变怪，則蛇頭而四角，魚首而鳥身，三足而六眼，龍形而似人，群行而辈搖，忽來到吾前，申臂而舞手，意欲相引牵，於是夢中驚怒，腷臆紛紜曰：吾含天地之純和，何妖孽之敢臻，乃揮手振拳，雷發電舒，戢遊光，軒猛跣，［句有訛，全後漢文五十八，據萬歷本作斬猛猪，亦臆補。］狒〈豸殳〉，［明本作毅，句亦有脱訛。］斫鬼魑，捎魍魉，荆諸渠，撞縱目，打三頭，扑〈鬼召〉〈戞下\"戈改犬\"〉，扶［全後漢文作抶。］夔魋，博睥睨，蹴睢盱，爾乃三三四四，相隨踉〈足旁〉而歷僻，隆隆潏潏，精氣充布，輷々犭翏々，鬼驚魅怖，或盤跚而欲走，或拘挛而不能步，或中創而婉轉，或捧痛而號呼，奄霧消而光蔽，寂不知其何故，嗟妖邪之怪物，豈幹真人之正度，耳聊嘈而外朗，忽屈申而覺寤，亂曰：齊桓夢物，而亦以霸，武丁夜感，而得賢佐，周夢九齡克百慶，晉文盬腦國以競，老子役鬼為神將，傳禍為福永無恙。","sortOrder":56},
  {"id":"s_work_nvlt_79_57","chapterId":"ch_work_nvlt_79","text":"◇魂魄","sortOrder":57},
  {"id":"s_work_nvlt_79_58","chapterId":"ch_work_nvlt_79","text":"《淮南子》曰：天氣為魂，地氣為魄。","sortOrder":58},
  {"id":"s_work_nvlt_79_59","chapterId":"ch_work_nvlt_79","text":"《易》曰：精氣為物，遊魂為变。","sortOrder":59},
  {"id":"s_work_nvlt_79_60","chapterId":"ch_work_nvlt_79","text":"《白虎通》曰：魂者何謂也，魂猶伝々也，行不休也，動於外，主於情，魄者白也，猶著人者也，主於性。","sortOrder":60},
  {"id":"s_work_nvlt_79_61","chapterId":"ch_work_nvlt_79","text":"《韓詩外傳》曰：溱與洧，謂鄭國之俗，三月上巳，於兩水之上，招魂續魄，拂不祥也。","sortOrder":61},
  {"id":"s_work_nvlt_79_62","chapterId":"ch_work_nvlt_79","text":"《禮記》曰：延陵季子適齊，長子死於嬴博之間，既封左袒，右還其封，曰：若魂氣則無不之。","sortOrder":62},
  {"id":"s_work_nvlt_79_63","chapterId":"ch_work_nvlt_79","text":"又曰：作其祝號，玄酒以祭，君與夫人交獻，以嘉魂魄，是謂合莫。","sortOrder":63},
  {"id":"s_work_nvlt_79_64","chapterId":"ch_work_nvlt_79","text":"又曰：氣也者，神之盛也，魂也者，鬼之盛也。","sortOrder":64},
  {"id":"s_work_nvlt_79_65","chapterId":"ch_work_nvlt_79","text":"《左傳》曰：子產雲，人生始化曰魄，既生魄陽曰魂，用物精多，則魂魄彊。又曰：樂祁雲，心之精爽，是謂魂魄。","sortOrder":65},
  {"id":"s_work_nvlt_79_66","chapterId":"ch_work_nvlt_79","text":"《越絕書》曰：越王問於范子曰：寡人聞人失其魂魄者死，得其魂魄者生，物皆有之，人亦有之，范子曰：人有之，萬物亦然，天地之間，人為貴，物之生，穀為貴，以生人，與魂魄無異也。","sortOrder":66},
  {"id":"s_work_nvlt_79_67","chapterId":"ch_work_nvlt_79","text":"《離骚》曰：［按本條及下條非離骚。］百年信荏苒，何為苦心魂。","sortOrder":67},
  {"id":"s_work_nvlt_79_68","chapterId":"ch_work_nvlt_79","text":"又曰：隱淪駐精魄。","sortOrder":68},
  {"id":"s_work_nvlt_79_69","chapterId":"ch_work_nvlt_79","text":"又曰：望孟夏之短夜，何晦朔之若歲，惟郢路之脩遠兮，魂一夕而九逝。","sortOrder":69},
  {"id":"s_work_nvlt_79_70","chapterId":"ch_work_nvlt_79","text":"又招魂篇曰：招魂者，宋玉之所作也，玉怜哀屈原，忠而斥弃，忧愁山泽，魂魄放逸，厥命將落，故作招魂，欲以复其精神，延其年寿，外陳四方之惡，內崇楚國之美，以諷諫懷王，冀其覺悟而還之也，朕幼清以廉絜，身服義而不沫。","sortOrder":70},
  {"id":"s_work_nvlt_79_71","chapterId":"ch_work_nvlt_79","text":"《史記》曰：高祖謂沛父兄曰：遊子悲故乡，吾雖都關中，萬歲後，吾魂魄樂思乡也。","sortOrder":71},
  {"id":"s_work_nvlt_79_72","chapterId":"ch_work_nvlt_79","text":"《淮南子》曰：魂問於魄曰：道何以為體，曰：以無有為體，魄曰：無有有形乎，魂曰：無有，魄曰：無有何得而問也，魂曰：吾直遇之耳，视之無形，聽之無聲，謂之幽冥，幽冥者，所以喻道，非吾道也。","sortOrder":72},
  {"id":"s_work_nvlt_79_73","chapterId":"ch_work_nvlt_79","text":"《抱朴子》曰：師言欲求長生，當對服大藥，欲得通神，當水火分形，分形則自見其身三魂七魄，而天靈祇皆可接，山川之神皆可役也。","sortOrder":73},
  {"id":"s_work_nvlt_79_74","chapterId":"ch_work_nvlt_79","text":"《襄陽耆舊記》曰：羊公與騶［《太平御覽》八百八十六作邹。］润甫，登峴山，垂泣曰：我百年後，魂魄猶當登此山也。","sortOrder":74},
  {"id":"s_work_nvlt_79_75","chapterId":"ch_work_nvlt_79","text":"【賦】梁沈蜅歸魂賦曰：古語稱收魂升極，周易有歸魂卦，屈原著招魂篇，故知魂之可歸，其日已久，餘自長安反，乃作魂歸賦，其辭曰：伊吾人之陋宗，資玄聖而雲始，肇邵閟之靈源，分昌發之世祀，實聞之乎家記。又孚之於惇史，亢宗貴而博古，四史成乎一身，怪日月之遼遠，而承袭之相因，豈少賤之能察，非末學之知津也，若夫風流退讓，在秦作相，越江以東，惟戎及酆，出忠出孝，且卿且公，世歷十五，爰逮餘躬，值天地之幅裂，遭日月之雰虹，去父母之邦國，理形影於胡戎，絕君臣而辭骨鐎，蹐厚地而跼蒼穹，抱北思之胡馬，望南飛之夕鸿，泣霑襟而雜露，悲微吟而帶風，昔休明之雲始，餘播弃於天地，自太學而遊承明，出書生而從下吏，身豫封禪之官，名入南宮之記，登玉墀之深眇，出金門之崇邃，受北狄之奉書，禮東夷之獻使，實不嘗至屈膝遜言，［句有訛衍。］以殊方降意，嗟五十之逾年，忽流離於凶忒，值中軍之失權，而大盜之移國，何赤沴之四起，豈黃霧之雲塞，祈瘦弟於赤眉，乞老親於剧賊，免伏质以解衣，遂窘身而就勒，既而天道禍淫，否終斯泰，靈聖奋發，風雲乡會，扫欃搶之星，斬蚩尤之旆，餘拔逆而效從，遂妻誅而子害，雖分珪而祚土，迄長河之如帶，肌膚之痛何泯，潛翳之悲無忕，我國家之沸騰，我天下之匡复，我何辜於上玄，我何負於鄰睦，背盟書而我欺，圖信神而我戮，彼孟冬之雲季，總官司而就绁，讬馬首之西暮，隨槛車而回轍，履瓘瓘之曾水，面飗飗之巖雪，去莫敖之所縊，過臨江之軸折，矧今古之悲涼，併攒心而霑袂，渡狹石之欹危，跨清津之幽咽，鳥虛弓而自陨，猿號子而腹裂，歷沔漢之逶迤，及楚郡之參差，望隆中之大宅，映峴首之沉碑，既缧然而就鞅，非造次之能窥，至若高祖武皇帝之基天下也，岐周景亳之地，龟圖雀書之秘，醒醉之歌咮絕，讓畔之田鱗次，餘既長於克民，覺何從而掩泗，洧水兮深且清，宛水兮澄复明，昔南陽之穰縣，今百雉之都城，我太宗之威武，遏宛洧而陳兵，百萬之虜，俄成魚鱉，千仞之阜，倏似沧瀛，雖德刑成於赦服，故蠻狄震乎雄名，乃尋浙而歷商，遂經秦而至洛，覺高蹈之清遠，具風雲之倏烁，其山也則嵚岑嶵嵬，巖髇婆紘，或孤峰而秀聚，或逸出而橫羅，千歲之木生嶺表，百丈之石枕溪阿，其水則碎訇瀄汩，或宽或疾，击萬瀨而相奔，聚千流而同出，何武關之狹隘，而漢祖之英雄，山萬里而仰雲雨，水百仞而寫蜿虹，若一夫而守隘，豈萬眾之能攻，去青泥而逾白鹿，越渥水而到青門，長卿之賦可想，邵平之跡不存，咄嗟驪山之阜，惆怅灞陵之園，文恭俭而無隙，嬴發掘其何言，訪轵道之長組，舍藍田之玙璠，無故老之可訊，併膴々之空原，登未央之北闕，望長樂之基趾，伊太後之所居，筑旗亭而成市，槐路鬱以三條，方涂坦而九軌，觀阡陌之遺蹤，實不乖乎前史，傍直城而北轉，臨橫門而左趨，南則董卓之坞，北則符堅所居，即二賊之壚壘，為彼主之庭除，終南巃鹢，太一嵯峨，九顒堀起，八壘連河，汩涇泥之混濁，盥渭渚之清波，指鹹陽而長望，何趙李而經過，息甘泉而避暑，猶爽垲而清和，爾乃背長夏，涉素秋，臥寒野，坐林陬，霜微凝而侵骨，树栽動而風遒，思我親戚之顏貌，寄夢寐而魂求，察故乡之安否，但望斗而觀牛，稚子夭於鄭穀，勉励愧乎延州，聞愛妾之長叫，引寒風而入楸，何精靈以堪此，乃縱酒以陶忧，至誠可以感鬼，秉信可以祈天，何精殒而魄散，忽魂歸而氣旋，解龍驂而見送，走郵驿於亭傳，出向來之大道，反初入之山川，受繞朝之赠策，報李陵之別篇，淚未悲而自墮，語未咽而無宣，於時和風四起，具物初榮，草極野而舒翠，花分丛而落英，魚則潛波涣濯，鳥則應嶺俱鳴，隨六合之开朗，與風雲而自輕，其所涉也，州則二雍三荆，昌歡江併，唐安浙洛，巴郢雲平，其水則淮江漢洧，隋浩汙沣，潦浐潏河，涇渭相亂，或浮深而揭淺，或凌波而沿岸，每日夕而靡依，常一步而三叹，蠻蜒之與荆吳，玄狄之與羌胡，言語之所不通，嗜欲之所不同，莫不叠足斂手，低眉曲躬，豈論生平與意氣，止望首丘於南風，悲城邑之毀撤，憙風水之渺扬，既盡地而謁帝，乃懷橘而升堂，何神仙之足學，此即雲衣而虹裳也。","sortOrder":75},
  {"id":"s_work_nvlt_79_76","chapterId":"ch_work_nvlt_79","text":"《藝文類聚》　唐·欧陽詢","sortOrder":76},
  {"id":"s_work_nvlt_80_1","chapterId":"ch_work_nvlt_80","text":"卷八十火部","sortOrder":1},
  {"id":"s_work_nvlt_80_2","chapterId":"ch_work_nvlt_80","text":"○火烽燧燈燭庭燎竈薪炭灰煙","sortOrder":2},
  {"id":"s_work_nvlt_80_4","chapterId":"ch_work_nvlt_80","text":"《釋名》曰：火，化物也，亦言毀也，物入即皆毀坏也。","sortOrder":4},
  {"id":"s_work_nvlt_80_5","chapterId":"ch_work_nvlt_80","text":"《山海經》曰：厭火國，獸身黑色，火出其口中，［言能吐火。］易曰：離為火。","sortOrder":5},
  {"id":"s_work_nvlt_80_6","chapterId":"ch_work_nvlt_80","text":"又曰：燥萬物者，莫熯乎火。","sortOrder":6},
  {"id":"s_work_nvlt_80_7","chapterId":"ch_work_nvlt_80","text":"又曰：火就燥。","sortOrder":7},
  {"id":"s_work_nvlt_80_8","chapterId":"ch_work_nvlt_80","text":"《尚書》曰：藻火粉米，［火為火字也。］","sortOrder":8},
  {"id":"s_work_nvlt_80_9","chapterId":"ch_work_nvlt_80","text":"又曰：洪范，五行，二曰火，火曰炎上，炎上作苦。","sortOrder":9},
  {"id":"s_work_nvlt_80_10","chapterId":"ch_work_nvlt_80","text":"又曰：火炎崑岡，玉石俱焚，［言火逸而害玉也。］天吏逸德，烈於猛火。又曰：若火之燎於原，不可乡邇，其猶可扑滅，［火炎不可向近，尚可扑滅，浮言不可信用，尚可刑戮也。］","sortOrder":10},
  {"id":"s_work_nvlt_80_11","chapterId":"ch_work_nvlt_80","text":"《禮記》：月令曰：孟夏之月，盛德在火。","sortOrder":11},
  {"id":"s_work_nvlt_80_12","chapterId":"ch_work_nvlt_80","text":"《左傳》曰：火龍黼黻。","sortOrder":12},
  {"id":"s_work_nvlt_80_13","chapterId":"ch_work_nvlt_80","text":"又曰：郯子曰：炎帝以火紀，故為火師而火名。","sortOrder":13},
  {"id":"s_work_nvlt_80_14","chapterId":"ch_work_nvlt_80","text":"又曰：古之火正，或食於心，或食於咮，以出內火，是故咮為鶉火，心為大火，［謂火正之官，配食於火星也，建辰之月，鶉火星昏見南方，則令民放火，建戌之月，火星伏在日下，夜不得見，則令民內火，禁放火者也。］","sortOrder":14},
  {"id":"s_work_nvlt_80_15","chapterId":"ch_work_nvlt_80","text":"又曰：陶唐氏之火正閼伯，居商丘，《春秋考異郵》曰：火者，陽之精也。","sortOrder":15},
  {"id":"s_work_nvlt_80_16","chapterId":"ch_work_nvlt_80","text":"白泽圖曰：火之精宋無忌。","sortOrder":16},
  {"id":"s_work_nvlt_80_17","chapterId":"ch_work_nvlt_80","text":"《禮含文嘉》曰：燧人始鑽木取火。","sortOrder":17},
  {"id":"s_work_nvlt_80_18","chapterId":"ch_work_nvlt_80","text":"《尸子》曰：燧人上觀星辰，下察五木，以為火。","sortOrder":18},
  {"id":"s_work_nvlt_80_19","chapterId":"ch_work_nvlt_80","text":"《家語》曰：尧火帝而王，尚赤。","sortOrder":19},
  {"id":"s_work_nvlt_80_20","chapterId":"ch_work_nvlt_80","text":"《地鏡圖》曰：黃金之見為火。","sortOrder":20},
  {"id":"s_work_nvlt_80_21","chapterId":"ch_work_nvlt_80","text":"括地圖曰：神丘有火穴，光照千里。","sortOrder":21},
  {"id":"s_work_nvlt_80_22","chapterId":"ch_work_nvlt_80","text":"孫子兵法曰：凡火攻有五，一曰火人，二曰火積，三曰火辎，四曰火库，五曰火隧。","sortOrder":22},
  {"id":"s_work_nvlt_80_23","chapterId":"ch_work_nvlt_80","text":"《莊子》曰：指窮於為薪，火傳也，［為薪猶薪(御覽八百六十九薪上有前薪也前四字，此脱。)以指，指盡前薪之理，故火傳而不滅，必得納養之中，故命續而不絕。］","sortOrder":23},
  {"id":"s_work_nvlt_80_24","chapterId":"ch_work_nvlt_80","text":"《戰國策》曰：楚王遊雲夢，野火之起也，若雲蜺。","sortOrder":24},
  {"id":"s_work_nvlt_80_25","chapterId":"ch_work_nvlt_80","text":"《呂氏春秋》曰：伊尹說湯五味，九沸九变，火為之紀。","sortOrder":25},
  {"id":"s_work_nvlt_80_26","chapterId":"ch_work_nvlt_80","text":"《韓子》曰：魯燒積泽，天北風，火南倚，恐燒國，哀公懼，自將眾趣救火，救火者左右無人，盡逐獸，不救火，乃召問仲尼，仲尼曰：夫逐獸者樂而無罰，救火者苦而無賞，此火所以不救也，事急不及以罰，救火者盡賞之，則舉國不足以賞於民，請從行罰，乃下令曰：不救火者，比降北之罪，令下未遍，火以滅矣。","sortOrder":26},
  {"id":"s_work_nvlt_80_27","chapterId":"ch_work_nvlt_80","text":"又曰：越王問於大夫种曰：吾欲伐吳，可乎，對曰：可矣，何不试焚宮室，於是遂焚宮室，民莫能救火，乃下令曰：民之救火而死者，比死敵之賞，民之涂其體，被濡衣走火者，左二千人，右三千人，［事具刑法部。］","sortOrder":27},
  {"id":"s_work_nvlt_80_28","chapterId":"ch_work_nvlt_80","text":"韓詩外傳曰：晉平公藏寶之台燒，救火三日三夜，乃勝之，公子晏束帛而贺曰：臣聞王者藏於天下，諸侯藏於百姓，農夫藏於囷庾，今百姓乏於外，而賦斂無已，昔桀紂殘賊，為天下戮，今皇天降灾於藏台，此是君之福也。","sortOrder":28},
  {"id":"s_work_nvlt_80_29","chapterId":"ch_work_nvlt_80","text":"《史記》曰：庞涓追孫臏，臏量其行，暮當至馬陵，乃伏兵斫树，白而書之曰：庞涓死此下，於是令齊軍萬弩夹道，暮火舉而俱發，涓夜至，見白書，乃鑽火燭讀之，未畢，萬弩俱發，庞涓大败。","sortOrder":29},
  {"id":"s_work_nvlt_80_30","chapterId":"ch_work_nvlt_80","text":"又曰：騎劫攻即墨，田单取牛千頭，衣以五采，束刀其角，結火其尾。","sortOrder":30},
  {"id":"s_work_nvlt_80_31","chapterId":"ch_work_nvlt_80","text":"《漢書》曰：項王西屠鹹陽，殺秦降王子婴，焚其宮室，火三月不滅。","sortOrder":31},
  {"id":"s_work_nvlt_80_32","chapterId":"ch_work_nvlt_80","text":"《三辅黃圖》曰：秦始皇帝，葬驪山，六年之間，為項王所發，牧兒墮羊冢中，燃火求羊，燒其椁藏。","sortOrder":32},
  {"id":"s_work_nvlt_80_33","chapterId":"ch_work_nvlt_80","text":"《淮南子》曰：陽遂見日，則然而為火，［陽遂金也，取金〈木孟〉無緣者，執日高三四丈時，以向，持燥艾承之寸餘，有頃焦之，吹之則然，得火。］","sortOrder":33},
  {"id":"s_work_nvlt_80_34","chapterId":"ch_work_nvlt_80","text":"《列女傳》曰：梁姑姊，其室失火，兄子與二子在內，欲取兄子，辄得其子，火盛不得复入，婦人曰：梁豈可戶告人晓耶，被不義之名，何面見兄弟國人哉，遂赴火而死。","sortOrder":34},
  {"id":"s_work_nvlt_80_35","chapterId":"ch_work_nvlt_80","text":"《列仙傳》曰：甯封子，黃帝陶正，掌火，能作五色煙，［事具煙部。］","sortOrder":35},
  {"id":"s_work_nvlt_80_36","chapterId":"ch_work_nvlt_80","text":"又曰：陶安公，六安冶師也，數行火，火一旦散上，紫色冲天，須臾朱雀止冶上，曰：安公安公，冶與天通，［事具仙部。］","sortOrder":36},
  {"id":"s_work_nvlt_80_37","chapterId":"ch_work_nvlt_80","text":"《東觀漢記》曰：郅惲為長沙，有義士古初，遭父丧，未葬，鄰人火起，及初舍，棺不可移，初冒火伏棺上，會火滅。","sortOrder":37},
  {"id":"s_work_nvlt_80_38","chapterId":"ch_work_nvlt_80","text":"又曰：廉范為蜀郡，成都地迫屋狹，百姓夜作，以供衣食。又禁火，民复弊之，失火者日屬，范令夜作，但使储水，百姓皆悅，［事具職官太守篇。］","sortOrder":38},
  {"id":"s_work_nvlt_80_39","chapterId":"ch_work_nvlt_80","text":"又曰：梁鸿，牧豕長安上林苑中，失火，延人家，問所燒财物，悉推豕偿之，其主言少，鸿原以身作，躬執其勤。","sortOrder":39},
  {"id":"s_work_nvlt_80_40","chapterId":"ch_work_nvlt_80","text":"《樊英別傳》曰：英隱於壶山，常有黑風從西方起，英謂學者曰：成都市火甚盛，因含水西向漱之，乃令記其日，後有從蜀來者，雲是日大火，黑雲平旦從東起，須臾大雨，火遂得滅。","sortOrder":40},
  {"id":"s_work_nvlt_80_41","chapterId":"ch_work_nvlt_80","text":"《汝南先賢傳》曰：郭慮，［《太平御覽》八百六十八作憲。］從南郊，含酒東北三噀，雲齊失火，以厭之，後齊果上火事。","sortOrder":41},
  {"id":"s_work_nvlt_80_42","chapterId":"ch_work_nvlt_80","text":"又曰：蔡君仲與人有至孝之心，母向終，棺在堂，西舍失火，火將至，君仲伏尸號哭，火越向東家。","sortOrder":42},
  {"id":"s_work_nvlt_80_43","chapterId":"ch_work_nvlt_80","text":"《玄中記》曰：南方有炎山焉，在扶南國之東，加營國之北，諸薄國之西，山從四月而火生，十二月火滅，正月二月火不然，山上但出雲氣，而草木生葉枝條，至四月火然，草木葉落，如中國寒時，草木葉落也，行人以正月二月三月行，過此山下，取柴以為薪，燃之無盡時，取其皮績之，為火浣布。","sortOrder":43},
  {"id":"s_work_nvlt_80_44","chapterId":"ch_work_nvlt_80","text":"《十洲記》曰：炎洲，在南海中，地方二千里，去崖九萬里，上有風生獸，似豹青色，大如狸，張取之，積薪數車以燒之，薪盡而此獸在火中，燃其毛不燋，斫刺不入，打之如皮囊，以鐵椎鍛其頭數十下，乃死，以其口向風，須臾便活而起，以石上菖蒲塞其鼻，即死，取其腦，菊花服之，盡十斤，得寿五百歲。","sortOrder":44},
  {"id":"s_work_nvlt_80_45","chapterId":"ch_work_nvlt_80","text":"又曰：有火林山，山中有火獸，大如鼠，毛長三四寸，或曰：山可百里許，取其獸毛，績以為布，名曰火澣布，國人衣服之，此布垢洿，以水浣濯之，終日不絜，以火燒布，兩食久許出，其垢即去，白如雪。","sortOrder":45},
  {"id":"s_work_nvlt_80_46","chapterId":"ch_work_nvlt_80","text":"《廣志》曰：火洲在南海中，火燃洲，其木不死更鮮。","sortOrder":46},
  {"id":"s_work_nvlt_80_47","chapterId":"ch_work_nvlt_80","text":"《抱朴子》曰：南海之中，萧丘之中，有自生之火，常以春起而秋滅，丘方千里，當火起時，此丘上純生一种木，火起正著此木，木雖為火所著，但小燋黑，人或以為薪者，如常薪，但不成炭，炊熟則灌滅之，後复更用，如此無窮。又夷人取木華，績以為火浣布，木皮亦剝，以灰煮為布，但不及華細好耳。","sortOrder":47},
  {"id":"s_work_nvlt_80_48","chapterId":"ch_work_nvlt_80","text":"又曰：有白鼠，大者重數斤，毛長三寸，居空木中，其毛亦可績為布，故火浣布有三种焉。","sortOrder":48},
  {"id":"s_work_nvlt_80_49","chapterId":"ch_work_nvlt_80","text":"又曰：吳世有姚光，有火術，吳主積荻千束，火焚荻了盡，光恬坐灰中，振衣而起，［事具草部荻篇。］","sortOrder":49},
  {"id":"s_work_nvlt_80_50","chapterId":"ch_work_nvlt_80","text":"《神仙傳》曰：栾巴為尚書，正旦會，得酒，西南漱，雲成都市失火，漱酒作雨，驿至，果如其言，［事具仙部。］","sortOrder":50},
  {"id":"s_work_nvlt_80_51","chapterId":"ch_work_nvlt_80","text":"《吳越春秋》曰：越王思報吳，冬則抱冰，夏則握火。","sortOrder":51},
  {"id":"s_work_nvlt_80_52","chapterId":"ch_work_nvlt_80","text":"《陳留耆舊傳》曰：劉崑為江陵令，民有火灾，崑向火叩頭，即霈然下雨，詔問反風滅火，虎北渡河，何以致此，崑曰：偶然，帝曰：此長者之言也。","sortOrder":52},
  {"id":"s_work_nvlt_80_53","chapterId":"ch_work_nvlt_80","text":"《風俗通》曰：城門失火，禍及池中魚，按百家書，宋城門失火，自汲池中水以沃之，魚悉露見，但就把之，［事具魚部。］","sortOrder":53},
  {"id":"s_work_nvlt_80_54","chapterId":"ch_work_nvlt_80","text":"魏武帝明罰令曰：聞太原上党西河雁門，冬至之後，百有五日，皆絕火寒食，雲為介子推。","sortOrder":54},
  {"id":"s_work_nvlt_80_55","chapterId":"ch_work_nvlt_80","text":"《英雄記》曰：周瑜镇江夏，曹操欲從赤壁渡江南，無舡，乘簰從漢水下，住浦口，未即渡，瑜夜密使輕舡走舸百所艘，艘有五十人移棹，人持炬火，火燃則回舡走去，去复還燒者，須臾燒數千簰，火大起，光上照天，操夜去。","sortOrder":55},
  {"id":"s_work_nvlt_80_56","chapterId":"ch_work_nvlt_80","text":"《博物志》曰：積紬萬匹，則自然生火，秦［《太平御覽》八百六十九作泰。］始中，武库火，積紬所致也。","sortOrder":56},
  {"id":"s_work_nvlt_80_57","chapterId":"ch_work_nvlt_80","text":"《異苑》曰：臨邛有火井，漢室隆則炎赫弥炽，桓靈之际，火势漸微，［事具水部井篇。］","sortOrder":57},
  {"id":"s_work_nvlt_80_58","chapterId":"ch_work_nvlt_80","text":"又曰：晉惠帝元康三年，武库火，燒孔子履，漢高斬白蛇劍，王莽頭等，［事具劍部。］","sortOrder":58},
  {"id":"s_work_nvlt_80_59","chapterId":"ch_work_nvlt_80","text":"《晉中興書》曰：殷浩北伐，江逌為長史，取數百雞，以長繩連腳，皆系火，一時驅放，飛過巉，集羌營，營皆然。","sortOrder":59},
  {"id":"s_work_nvlt_80_60","chapterId":"ch_work_nvlt_80","text":"《搜神記》曰：麋竺常從洛歸，未至家數十里，見路次有好新婦，從竺求寄載，行二十餘里，新婦謝去，謂竺曰：我天使，去當往燒東海麋家，感君見載，故以相語，竺因請之，曰：不可，不得不燒，君快去，我缓來，日中必火發，竺乃急行達家，便出财物，日中而火大發。","sortOrder":60},
  {"id":"s_work_nvlt_80_61","chapterId":"ch_work_nvlt_80","text":"《笑林》曰：某甲夜暴疾，命門人鑽火，其夜陰暝，未得火，催之急，門人忿然曰：君责之亦大無道理，今闇如漆，何以不把火照我，我當得觅鑽火具。","sortOrder":61},
  {"id":"s_work_nvlt_80_62","chapterId":"ch_work_nvlt_80","text":"【詩】梁庾肩吾遠看放火詩曰：風前細煙起，月里黑煙生，入焰看桥木，侵光識遠城。","sortOrder":62},
  {"id":"s_work_nvlt_80_63","chapterId":"ch_work_nvlt_80","text":"【賦】晉潘尼火賦曰：覽天人之至周，嘉火德之為貴，含太陽之靈暉，體淳刚之正氣，先聖仰觀，通神悟靈，窮物盡數研機至精，鑽燧造火，陶冶群形，协和五味。革变膻腥，爾乃狄牙典膳，百品既陳，和羹酋醳，旨酒醲醇，享黿煮鼍，灼龟臛鱗，若乃流金化石，鑠鐵融銅，造製戎器，以戒不恭，砥煉兵械，整飾軍容，四海康乂，邊境無寇，韜弓戢劍，解甲釋胄，銷鏑為耒，鑄戈為耨，戰士反於耕農，戎馬放乎外廄，及至焚野燎原，陆火赫羲，林木摧拉，沙粒併麋，騰光絕覽，雲散霓披，去若風驅，疾若電逝，芬輪紆轉，倏忽橫厲，震响達乎八冥，流光燭乎四裔。","sortOrder":63},
  {"id":"s_work_nvlt_80_64","chapterId":"ch_work_nvlt_80","text":"◇烽燧","sortOrder":64},
  {"id":"s_work_nvlt_80_65","chapterId":"ch_work_nvlt_80","text":"玄女戰經曰：諸見舉烽火煙火，傳言虜且欲起，欲知審來不，以言者時所加之，得陽者不來，得陰者為來法。","sortOrder":65},
  {"id":"s_work_nvlt_80_66","chapterId":"ch_work_nvlt_80","text":"《墨子》曰：烽火已舉，言寇所從來多少。","sortOrder":66},
  {"id":"s_work_nvlt_80_67","chapterId":"ch_work_nvlt_80","text":"甘氏天文占曰：權舉烽表，遠近沉浮，權四星，在軒轅尾西，邊地警備，烽候相望，虜至則舉，烽火十文，［《太平御覽》三百三十五作丈。］如今井桔槔，火［御覽作大。］錘其頭，若警備急，燃火其頭，放之，權重，本低則末仰，見烽火。","sortOrder":67},
  {"id":"s_work_nvlt_80_68","chapterId":"ch_work_nvlt_80","text":"《史記》曰：褒姒不好笑，幽王欲其笑，為烽燧火鼓，似有寇至，舉烽火，諸侯悉至，至而無寇，褒姒乃大笑。","sortOrder":68},
  {"id":"s_work_nvlt_80_69","chapterId":"ch_work_nvlt_80","text":"《漢書》曰：軍臣单於立四歲，匈奴复絕和親，大入上都［《太平御覽》三百三十五作郡。］雲中，烽火通於甘泉。","sortOrder":69},
  {"id":"s_work_nvlt_80_70","chapterId":"ch_work_nvlt_80","text":"《東觀漢記》曰：廉范為雲中太守，始到，烽火日通，故事，虜出度五千人，乃移書旁郡求助，吏白，今虜兵度出五千，請移警檄，范不聽，遂選精兵，自將出至近縣，令老弱城守而追之。","sortOrder":70},
  {"id":"s_work_nvlt_80_71","chapterId":"ch_work_nvlt_80","text":"又曰：馬成善治障塞，自西河至渭桥，河上至安邑，太原至井陉，中山至鄴，皆筑保壁，起烽燧，十里一候。","sortOrder":71},
  {"id":"s_work_nvlt_80_72","chapterId":"ch_work_nvlt_80","text":"又曰：郭伋為併州，伋知盧芳夙［原訛風，據冯校本改。］賊，難卒以力製，常嚴烽候，明購賞。","sortOrder":72},
  {"id":"s_work_nvlt_80_73","chapterId":"ch_work_nvlt_80","text":"蔡邕徙朔方上書曰：既到徙所，乘塞守烽，職在望候，忧怖焦灼，無心复能操筆成草，致章闕庭。","sortOrder":73},
  {"id":"s_work_nvlt_80_74","chapterId":"ch_work_nvlt_80","text":"庾闡楊都賦註曰：燧火，以炬置孤山頭，皆緣江相望。","sortOrder":74},
  {"id":"s_work_nvlt_80_75","chapterId":"ch_work_nvlt_80","text":"《述征記》曰：戲水註渭，東有周幽王壘，昔幽王亟舉烽以悅褒姒，遂犬戎伐周，諸侯玩而弗至，戰败死於斯地。","sortOrder":75},
  {"id":"s_work_nvlt_80_76","chapterId":"ch_work_nvlt_80","text":"【書】晉蔡謨與弟書曰：軍中耳目，當用鼓烽，烽可遙見，鼓可遙聞，形聲相傳，須臾百里，非人所及，想得先知耳，近別菽麥者，皆當解之，而王苟諸人，癡顽之甚，乃至於是，常令人怪之，然烽鼓之法，當豫敕諸軍，見烽聞鼓便嚴，而此間恒舉烽之後，須文書上言，乃符遊軍，遊軍須被符，乃當嚴，昔年石頭夜半舉烽，至明日食時，台中乃知，弟在石頭時，隅中舉烽，至下脯，遊軍故未嚴，此即是苟希［按當作晞。］等覆車之軌也。","sortOrder":76},
  {"id":"s_work_nvlt_80_78","chapterId":"ch_work_nvlt_80","text":"《說文》曰：錠謂之燈。","sortOrder":78},
  {"id":"s_work_nvlt_80_79","chapterId":"ch_work_nvlt_80","text":"《韻集》曰：\"無足曰燈，有足曰錠。\"","sortOrder":79},
  {"id":"s_work_nvlt_80_80","chapterId":"ch_work_nvlt_80","text":"《離骚》［按本條非離骚。］曰：吳酒不废沉日夜，蘭膏明燭華銅错。［言燈錠盡銅，琢禽獸，有華英也。］","sortOrder":80},
  {"id":"s_work_nvlt_80_81","chapterId":"ch_work_nvlt_80","text":"《說苑》曰：楚莊王賜群臣酒，日暮，燈燭滅，乃有人引美人衣者，美人挽絕其冠纓，［事具人部報恩篇。］","sortOrder":81},
  {"id":"s_work_nvlt_80_82","chapterId":"ch_work_nvlt_80","text":"劉向《別傳》曰：待詔冯商作燈賦。","sortOrder":82},
  {"id":"s_work_nvlt_80_83","chapterId":"ch_work_nvlt_80","text":"《漢書》曰：金枝秀華，庶旄翠旌，［金枝，銅燈，百二十枝，秀華，中主有光華也。］","sortOrder":83},
  {"id":"s_work_nvlt_80_84","chapterId":"ch_work_nvlt_80","text":"又曰：武帝思念李夫人不已，方士齊人少翁，言能致其神，乃夜設燈燭帷幄，而令帝居他帳，遙望見好女，如李夫人之貌，而不得就视。","sortOrder":84},
  {"id":"s_work_nvlt_80_85","chapterId":"ch_work_nvlt_80","text":"《漢武內傳》曰：西王母遣使謂帝曰：七月七日，我當暫來，帝至日，扫除宮內，燃九光之燈。","sortOrder":85},
  {"id":"s_work_nvlt_80_86","chapterId":"ch_work_nvlt_80","text":"《荀采傳》曰：荀采，爽女，為陰瑜妻，而夫早亡，爽逼嫁與太原郭弈，采入郭氏室，暮乃去其帷帳，建四燈，斂色正坐，郭氏不敢逼。","sortOrder":86},
  {"id":"s_work_nvlt_80_87","chapterId":"ch_work_nvlt_80","text":"《風俗通》曰：郅伯夷宿亭，止樓上，燃數燈，夜有魅來，伯夷趣之，以燈照，乃老狸也。","sortOrder":87},
  {"id":"s_work_nvlt_80_88","chapterId":"ch_work_nvlt_80","text":"《東宮舊事》曰：宮有銅鸭頭燈二，銅侍燈三，供戶外用，夕供油七合，太子納妃，有金涂四尺長燈一，金涂連盤短燈二，金涂連盤鸭燈一。","sortOrder":88},
  {"id":"s_work_nvlt_80_89","chapterId":"ch_work_nvlt_80","text":"《鄴中記》曰：石虎正旦會於殿前，設百二十枝燈。","sortOrder":89},
  {"id":"s_work_nvlt_80_90","chapterId":"ch_work_nvlt_80","text":"【詩】晉習凿齒詩曰：煌煌閒夜燈，脩脩树間亮，燈隨風煒燁，風與燈升降。","sortOrder":90},
  {"id":"s_work_nvlt_80_91","chapterId":"ch_work_nvlt_80","text":"齊謝朓詠燈詩曰：發翠斜溪里，蓄實宕山峰，抽茎類仙掌，衔光似燭龍，飛蛾再三繞，輕花四五重，孤對相思夕，空照舞衣縫。","sortOrder":91},
  {"id":"s_work_nvlt_80_92","chapterId":"ch_work_nvlt_80","text":"梁簡文帝詠籠燈絕句詩曰：動焰翠帷里，散影羅帳前，花心生复落，明銷君詎怜。","sortOrder":92},
  {"id":"s_work_nvlt_80_93","chapterId":"ch_work_nvlt_80","text":"梁紀少瑜詠殘燈絕句曰：殘燈猶未滅，將盡更扬暉，惟餘一兩爓，［原訛烂，據冯校本改。］裁得解羅衣。","sortOrder":93},
  {"id":"s_work_nvlt_80_94","chapterId":"ch_work_nvlt_80","text":"梁王筠詠燈擎詩曰：百華曜九枝，鳴鶴映冰池，末［原訛未，據冯校本改。］光本內照，丹花复外垂，流暉悅嘉客，翻影泣生離，自銷良不悔，明白原君知。","sortOrder":94},
  {"id":"s_work_nvlt_80_95","chapterId":"ch_work_nvlt_80","text":"梁吳筠燈詩曰：昔在鳳皇闕，七采莲花茎，陆離看寶帳，烂熳照文屏，簷艳煙光轉，氛氲霧里輕，能方三五夜，桂树月中生。","sortOrder":95},
  {"id":"s_work_nvlt_80_96","chapterId":"ch_work_nvlt_80","text":"梁范靖妻沈氏詠燈詩曰：綺筵日已暮，羅帳月未歸，开花散鶴彩，含光出九微，風軒動丹焰，水宇淡清辉，不吝輕蛾繞，唯恐晓蠅飛。","sortOrder":96},
  {"id":"s_work_nvlt_80_97","chapterId":"ch_work_nvlt_80","text":"【賦】漢劉子駿燈賦曰：惟茲蒼鶴，修麗以奇，身體剼削，頭頸委蛇，負斯明燭，躬含冰池，明無不見，照察纖微，以夜繼晝，烈者所依。","sortOrder":97},
  {"id":"s_work_nvlt_80_98","chapterId":"ch_work_nvlt_80","text":"魏殷臣［按當作巨，本書八十五布篇同。］鯨魚燈賦曰：橫海之魚，厥號惟鯨，普彼鱗族，莫之與京，大秦美焉，乃觀乃詳，寫載其形，讬於金燈，隆脊矜尾，鬐甲舒張，垂首挽视，蟠於華房，状欣欣以竦峙，若將飛而未翔，懷蘭膏於焜臆，明製節之謹度，伊工巧之奇密，莫尚美於斯器，因綺麗以致用，設機变而罔匮，匪雕文之足玮，差利事之為貴，永作式於將來，跨千載而弗墜。","sortOrder":98},
  {"id":"s_work_nvlt_80_99","chapterId":"ch_work_nvlt_80","text":"晉夏侯湛棋燈賦曰：乃珠珍寶器，奇像妙工，取光藏煙，致巧金銅，融冶甄流，陶形定容，爾乃隱以金翳，疏以華籠，融素膏於回槃，發朱辉於綺窗，宣耀蘭堂，騰明廣宇，焰煜爚於茵筵，煥炤〈火折〉乎屏組。","sortOrder":99},
  {"id":"s_work_nvlt_80_100","chapterId":"ch_work_nvlt_80","text":"晉孫惠百枝燈賦曰：晔若雲停，烂已星布。","sortOrder":100},
  {"id":"s_work_nvlt_80_101","chapterId":"ch_work_nvlt_80","text":"范堅〈虫葛〉燈賦曰：爾乃旋閒房，升玉榻，列華槃，鑠凝〈虫葛〉，浮炷穎其始燃，秘闈於是乃阖，旁映文楹，仰暉丹桷，赫如燭龍吐辉，烂若翳陽复旭。","sortOrder":101},
  {"id":"s_work_nvlt_80_102","chapterId":"ch_work_nvlt_80","text":"梁簡文帝列燈賦曰：何解冻之嘉月，值蓂荚之盡开，草含春而動色，雲飛采而輕來，九微間吐，百枝交布，聚類炎洲，跡同大榭，競紅蕊之晨舒，蔑丹螢之昏骛，蘭膏馥氣，芬炷擎心，寒生色淺，露染光沉。","sortOrder":102},
  {"id":"s_work_nvlt_80_103","chapterId":"ch_work_nvlt_80","text":"梁江淹燈賦曰：淮南王，信自葬，命婇女，餌丹砂，餌丹砂，學鳳音，紫霞没，白日沉，掛明燈，散玄陰，顧謂小山儒士，斯可賦乎，於是泛瑟而言曰：若大王之燈也，銅華金擎，错质鏤形，碧為雲氣，玉為仙靈，双碗百枝，艳帳充庭，照錦池之丈席，映繡柱之鳴筝，若庶人之燈者，非銀非珠，無藻無縟，心不貴麗，器窮於朴。","sortOrder":103},
  {"id":"s_work_nvlt_80_104","chapterId":"ch_work_nvlt_80","text":"周庾信燈賦曰：九龍將暝，三爵行栖，琼鉤半上，弱木全低，乃有百枝同树，四照連槃，香添燃蜜，氣雜燒蘭，燼長霄久，光青夜寒，秀帳掩映，魭膏照灼，動鱗甲於鯨魚，〈魚炎〉光芒於鳴鶴，蛾飄則碎花亂下，風起則流星細落，况复上蘭深夜，中山醑清，楚妃留客，韓娥合聲，但歌著節，遊絃絕鳴，辉辉朱燼，焰焰紅榮，乍九光而連影，或双花而併明，寄言蘇季子，應知餘照情。","sortOrder":104},
  {"id":"s_work_nvlt_80_105","chapterId":"ch_work_nvlt_80","text":"【贊】晉支曇諦燈贊曰：既明遠理，亦弘近教，千燈同辉，百枝併曜，飛煙清夜，流光洞照，見形悅景，悟旨测妙。","sortOrder":105},
  {"id":"s_work_nvlt_80_106","chapterId":"ch_work_nvlt_80","text":"【銘】後漢李尤金羊燈銘曰：賢哲勉務，惟日不足，金羊載耀，作明以續。","sortOrder":106},
  {"id":"s_work_nvlt_80_108","chapterId":"ch_work_nvlt_80","text":"周官，司烜氏，掌以燧取火於日，以供祭祀之明燭，［日火，陽之絜氣也，明燭以炤饌。］凡邦之大事，供蕡燭，［贲燭，麻燭，贲，大也。］","sortOrder":108},
  {"id":"s_work_nvlt_80_109","chapterId":"ch_work_nvlt_80","text":"《禮記》曰：侍坐，燭至起，［異晝夜也。］燭不見跋，［跋，本也，燭盡則去之，嫌若燼多，有厭倦也。］","sortOrder":109},
  {"id":"s_work_nvlt_80_110","chapterId":"ch_work_nvlt_80","text":"又曰：孔子曰：嫁女之家，三夜不息燭，思離親也，［事具禮部婚姻篇。］","sortOrder":110},
  {"id":"s_work_nvlt_80_111","chapterId":"ch_work_nvlt_80","text":"《尚書大傳》曰：晉平公問師曠曰：吾年七十，欲學，恐已暮，師曠曰：臣聞老而學者，如執燭之明，執燭之明，孰與昧行，公曰：善，［事具禮部學篇。］","sortOrder":111},
  {"id":"s_work_nvlt_80_112","chapterId":"ch_work_nvlt_80","text":"《文子》曰：鳴铎以聲自毀，蘭膏以明自銷。","sortOrder":112},
  {"id":"s_work_nvlt_80_113","chapterId":"ch_work_nvlt_80","text":"《韓子》曰：鄭人有遺燕相國書者，夜書，謂持燭者曰：舉燭，而誤書舉燭，燕相受書曰：舉燭高明，高明者，舉賢而任之，［事具赠答部。］","sortOrder":113},
  {"id":"s_work_nvlt_80_114","chapterId":"ch_work_nvlt_80","text":"《列女傳》曰：齊女徐吾者，東海上貧婦人，其鄰婦李吾之屬，合燭夜績，吾最貧而燭不屬，李吾曰：徐吾燭數不屬，請無與夜，徐吾曰：妾以貧故，起常先，去常後，扫陳席以待來者，坐常處下，為貧故也，今一室之中，益一人，燭不為益明，去一人，燭不為益闇，何愛東壁餘光，莫之能應，遂复與夜，績。","sortOrder":114},
  {"id":"s_work_nvlt_80_115","chapterId":"ch_work_nvlt_80","text":"《史記》曰：始皇冢中，以人魚膏為燭。","sortOrder":115},
  {"id":"s_work_nvlt_80_116","chapterId":"ch_work_nvlt_80","text":"謝承《後漢書》曰：巴祗為楊州刺史，與客坐闇暝之中，不燃官燭，［事具職官部刺史篇。］","sortOrder":116},
  {"id":"s_work_nvlt_80_117","chapterId":"ch_work_nvlt_80","text":"玄晏春秋曰：計君又授與司馬相如傳，遂涉《漢書》：讀匈奴傳，不識棠梨孤涂之字，有胡奴執燭，顧而問之，奴曰：棠梨天子也，言匈奴之號单於，猶漢人有天子也，予於是乎曠然發寤。","sortOrder":117},
  {"id":"s_work_nvlt_80_118","chapterId":"ch_work_nvlt_80","text":"《地鏡圖》曰：相玉，見美女子，載燭行壇陰，從其所出入處，石中有玉矣。","sortOrder":118},
  {"id":"s_work_nvlt_80_119","chapterId":"ch_work_nvlt_80","text":"《世說》曰：王君夫飴糖澳釜，石季倫以〈虫葛〉燭灼炊。","sortOrder":119},
  {"id":"s_work_nvlt_80_120","chapterId":"ch_work_nvlt_80","text":"【詩】齊謝朓詠燭詩曰：杏梁賓未散，桂宮明欲沉，暧色輕帷里，低光照寶琴，徘徊雲髻影，灼烁綺疏金，恨君秋月夜，遺我洞房陰。","sortOrder":120},
  {"id":"s_work_nvlt_80_121","chapterId":"ch_work_nvlt_80","text":"梁孝元帝詠池中燭影詩曰：魚燈且滅燼，鶴焰暫停辉，自有衔龍燭，青火入朱扉，映水疑三燭，翻池類九微，入林如燐影，度渚若螢飛，河仾扇月落，霧上珠星稀，章華終宴所，飛蓋且相追。","sortOrder":121},
  {"id":"s_work_nvlt_80_122","chapterId":"ch_work_nvlt_80","text":"又古意詠燭詩曰：花中燭，焰焰動帘風，不見來人影，回光持向空。","sortOrder":122},
  {"id":"s_work_nvlt_80_123","chapterId":"ch_work_nvlt_80","text":"梁簡文帝和詩曰：花中燭，似將人意同，憶啼流膝上，燭焰落花中。","sortOrder":123},
  {"id":"s_work_nvlt_80_124","chapterId":"ch_work_nvlt_80","text":"梁庾肩吾燭影詩曰：垂爓垂花比芳树，風吹水動俱難住，春枝拂岸影上來，還杯繞客光中度。","sortOrder":124},
  {"id":"s_work_nvlt_80_125","chapterId":"ch_work_nvlt_80","text":"梁劉孝威和帘里燭詩曰：开關帘影出，參差風焰斜，浮光燭綺帶，凝滴汙垂花。","sortOrder":125},
  {"id":"s_work_nvlt_80_126","chapterId":"ch_work_nvlt_80","text":"又禊飲嘉樂殿詠曲水中燭影詩曰：火浣花心猶未長，金枝密焰已流芳，芙蓉池畔涵停影，桃花水脈引行光。","sortOrder":126},
  {"id":"s_work_nvlt_80_127","chapterId":"ch_work_nvlt_80","text":"【賦】晉傅鹹燭賦曰：餘治獄至長安，在遠多懷，與同行夜飲，以忘愁□，顧帷燭之自焚以致用，亦猶殺身以成仁矣，蓋泰清垂象，匪日不光，向晦入冥，匪火不彰，故六龍衔燭於北極，九日登曜於扶桑，日中則昃，月虧於望，時邁靡停，晝不幹常，背三接之昭昭，即厥开之有傷，何遠宇之多懷，患冬夜之悠長，獨耿耿而不寐，待雞鳴之未央，徒伏枕以展轉，起燃燭於閒房，扬丹辉之煒燁，炽朱焰之煌煌，俾幽夜而作晝，繼列景乎朝陽，慨顧景以增叹，孰斯愁之可忘，嘉湛露之愔愔，遂命樽而設觴，爾乃延僚屬，酌醇清，講三墳，論五經，高談既倦，引滿行盈，樂飲今夕，寔慰我情。","sortOrder":127},
  {"id":"s_work_nvlt_80_128","chapterId":"ch_work_nvlt_80","text":"梁簡文帝對燭賦曰：雲母窗中含花氈，茱萸幔里鋪錦筵，照夜明珠且莫取，金羊燈火不須燃，下絃三更未有月，甲夜繁星徒衣天，於是搖同心之明燭，施雕金之麗槃，眠龍傍繞，倒鳳双安，菖蒲傳酒坐欲阑，碧玉舞罢羅衣单，影度臨長枕，煙生向果盤，回照金屏里，脈脈兩相看。","sortOrder":128},
  {"id":"s_work_nvlt_80_129","chapterId":"ch_work_nvlt_80","text":"梁元帝對燭賦曰：月似金波初映空，雲如玉葉半從風，恨九重兮夕掩，怨三秋兮不同，爾乃傳芳醁，扬清曲，長袖留賓待華燭，燭燼落，燭華明，花抽珠漸落，珠懸花更生，風來香轉散，風度焰還輕，本知龍燭應無偶，复訝魚燈有舊名，燭火燈光一双炷，詎照誰人兩處情。","sortOrder":129},
  {"id":"s_work_nvlt_80_130","chapterId":"ch_work_nvlt_80","text":"周庾信對燭賦曰：龍沙雁塞早應寒，天山月坂客衣单，燈前行衣疑不亮，月下穿針覺最難，剩取燈花持炷燭，還却燈擎下燭槃，傍垂細溜，上繞飛蛾，光清寒入，焰暗風過，楚人纓脱盡，燕君書誤多，晓星没，芳無歇，還持照夜遊，詎减西園月。","sortOrder":130},
  {"id":"s_work_nvlt_80_131","chapterId":"ch_work_nvlt_80","text":"【啟】陳徐陵謝敕赉燭監賞答齊國移文啟曰：昔班彪草移，阮瑀裁書，馳譽當年，遂無加賞，非常大赉，始自今恩，雖贾逵之頌神雀，窦攸之對鼫鼠，漢臣射覆之言，魏士投壶之賦，方其寵錫，獨有光前，官燭斯燃，更慚良吏，霄光可學，乃會耆年，臣職居南史，身典東觀，謹述私榮，傳之方策。","sortOrder":131},
  {"id":"s_work_nvlt_80_132","chapterId":"ch_work_nvlt_80","text":"◇庭燎","sortOrder":132},
  {"id":"s_work_nvlt_80_133","chapterId":"ch_work_nvlt_80","text":"《說文》曰：庭燎，大燭也。","sortOrder":133},
  {"id":"s_work_nvlt_80_134","chapterId":"ch_work_nvlt_80","text":"《禮記》曰：庭燎之百，自齊桓公始也。","sortOrder":134},
  {"id":"s_work_nvlt_80_135","chapterId":"ch_work_nvlt_80","text":"《毛詩》曰：庭燎，美宣王，因以箴之，夜如何其，夜未央，庭燎之光，君子，至止，鸞聲锵锵。","sortOrder":135},
  {"id":"s_work_nvlt_80_136","chapterId":"ch_work_nvlt_80","text":"《說苑》曰：齊桓公設庭燎，為士之欲造見者，期年而士不至，東野鄙人，有以九九之術見者，桓公曰：九九足以見乎，對曰：臣非以九九為足以見也，臣聞主君設庭燎以待士，期年而不至，夫士所以不至者，君天下賢君也，四方之士，皆自論不及君，故不至也，夫九九薄能耳，而君猶禮之，况賢於九九者，桓公曰：善，禮之，期月而士至。","sortOrder":136},
  {"id":"s_work_nvlt_80_137","chapterId":"ch_work_nvlt_80","text":"晉《起居註》曰：成帝鹹和八年十二月，有司奏，庭燎在止車門外，今更集議，舊在端門內施，詔曰：尚書奏，九年庭燎，當在端門內，元明帝時，在公車門內，可依舊，安司徒錄公命，當率由舊章，宜在端門內。","sortOrder":137},
  {"id":"s_work_nvlt_80_138","chapterId":"ch_work_nvlt_80","text":"《晉中興書》曰：哀帝興寧元年，詔庭燎树端門內。","sortOrder":138},
  {"id":"s_work_nvlt_80_139","chapterId":"ch_work_nvlt_80","text":"《鄴中記》曰：石虎正會，殿庭中，端門外，閶阖前，設庭燎，皆二合，六處皆六丈。","sortOrder":139},
  {"id":"s_work_nvlt_80_140","chapterId":"ch_work_nvlt_80","text":"趙書曰：石勒造庭燎於橦末，高十丈，上盤置燎，下盤安人以侍燎，艑繳上下。","sortOrder":140},
  {"id":"s_work_nvlt_80_141","chapterId":"ch_work_nvlt_80","text":"【詩】晉傅玄庭燎詩曰：元正始朝亨，萬國執珪璋，枝燈若火树，庭燎繼天光。","sortOrder":141},
  {"id":"s_work_nvlt_80_142","chapterId":"ch_work_nvlt_80","text":"【表】魏王朗冬臈不得朝表曰：拘守留職，曠離車駕，况乃踐長於至，迎始於臈，履端於正，連歷天人三朝之元慶，而無緣祗奉玉爵，以獻萬寿，霄夢庭燎之光，晨想百華之耀。","sortOrder":142},
  {"id":"s_work_nvlt_80_144","chapterId":"ch_work_nvlt_80","text":"《釋名》曰：竈，造也，創食物也。","sortOrder":144},
  {"id":"s_work_nvlt_80_145","chapterId":"ch_work_nvlt_80","text":"《淮南子》曰：炎帝作火，死而為竈神。","sortOrder":145},
  {"id":"s_work_nvlt_80_146","chapterId":"ch_work_nvlt_80","text":"《禮記》：月令曰：孟夏之月，其祀竈。","sortOrder":146},
  {"id":"s_work_nvlt_80_147","chapterId":"ch_work_nvlt_80","text":"又曰：竈者，老婦之祭，盛於盆，尊於瓶。","sortOrder":147},
  {"id":"s_work_nvlt_80_148","chapterId":"ch_work_nvlt_80","text":"《墨子》曰：竈必為屏，心突高出屋四尺，慎無失火，失火者斬。","sortOrder":148},
  {"id":"s_work_nvlt_80_149","chapterId":"ch_work_nvlt_80","text":"魯連子曰：竈五突，分煙者眾也。","sortOrder":149},
  {"id":"s_work_nvlt_80_150","chapterId":"ch_work_nvlt_80","text":"《莊子》曰：仲尼讀書，老聃倚竈觚而聽之，曰：是何書也，曰：春秋也。","sortOrder":150},
  {"id":"s_work_nvlt_80_151","chapterId":"ch_work_nvlt_80","text":"《呂氏春秋》曰：燕雀處一屋之下，自以為安，竈突决，火上棟宇，燕雀不知禍將至也，［事具雀部。］","sortOrder":151},
  {"id":"s_work_nvlt_80_152","chapterId":"ch_work_nvlt_80","text":"《戰國策》曰：智伯攻晉陽而水之，城不没者三版，臼竈生蛙，人馬相食。","sortOrder":152},
  {"id":"s_work_nvlt_80_153","chapterId":"ch_work_nvlt_80","text":"《史記》曰：武帝時，李少君以祀竈辟穀却老方見上，少君言上曰：祠竈則致物，致物而丹砂可化以為黃金，黃金成，以為飲食器，則益寿，益寿則仙者可見，於是天子始親祠竈。","sortOrder":153},
  {"id":"s_work_nvlt_80_154","chapterId":"ch_work_nvlt_80","text":"《淮南子》曰：孔子無黔突，墨子無暖席。","sortOrder":154},
  {"id":"s_work_nvlt_80_155","chapterId":"ch_work_nvlt_80","text":"桓谭《新論》曰：淳於髡至鄰家，見其竈突之直，而積薪在傍，謂曰：此且有火，使為曲突而徙薪，鄰家不聽，後果焚其屋，鄰家救火乃滅，烹羊具酒，謝救火者，不肯呼髡，智士譏之曰：曲突徙薪無恩泽，燋頭烂額為上客，蓋傷其賤本而貴末也。","sortOrder":155},
  {"id":"s_work_nvlt_80_156","chapterId":"ch_work_nvlt_80","text":"《東觀漢記》曰：初陰氏世奉管仲之祀於邑，謂之相君子，至子方，以累積恩德，為神所饗，臈日，晨炊於竈，神見，再拜受慶，時有黃羊，因以祠之，自是富殖百萬，田至七百頃，後世子孫，常以臈日，奉祠竈神以黃羊。","sortOrder":156},
  {"id":"s_work_nvlt_80_157","chapterId":"ch_work_nvlt_80","text":"又曰：周泽為渑池令，克身俭約，妻子自親釜竈。","sortOrder":157},
  {"id":"s_work_nvlt_80_158","chapterId":"ch_work_nvlt_80","text":"謝承《後漢書》曰：李南，少明風角，女亦晓家術，為卷縣民妻，晨詣爨室，卒有暴風，婦便上堂，從姑求歸，辭其二親，姑不許，乃跪而泣曰：蒙傳術，疾風卒起，先吹竈突及井，此禍為女婦主爨者，妾將亡之應，因著其亡日。","sortOrder":158},
  {"id":"s_work_nvlt_80_159","chapterId":"ch_work_nvlt_80","text":"《續漢書》曰：虞詡為武都太守，羌欲邀遮詡，詡密令吏，人作兩竈，日增倍之，羌不敢逼，或問曰：孫臏减竈，而君增之，兵法，日行不過三十里，以戒不虞，而今且二百里，何也，詡曰：虜多，吾兵少，徐行則易為所及，速進則彼所不惻，虜見吾竈日增，必謂郡兵來迎，眾行速，必憚進追我，孫臏見弱，吾今示彊。","sortOrder":159},
  {"id":"s_work_nvlt_80_160","chapterId":"ch_work_nvlt_80","text":"茅君內傳曰：在名山深壑，無人跡之處，臨水上，作神竈屋，屋長四丈，廣二丈，起基四尺。又當先掘基下土，令必無故陷井家［疑當作冢。］瘞之處所也，开南戶西戶東戶，三也，立竈於屋中央，口向西，竈四邊，令去釜九寸也，以砖及細土構立之，亦勿令穿坼，神竈之法畢矣。","sortOrder":160},
  {"id":"s_work_nvlt_80_161","chapterId":"ch_work_nvlt_80","text":"《抱朴子·內篇》曰：竈之神，每月晦日，辄上天言人罪状，大者奪紀，紀者三百日也，小者奪筭，筭者一日也。","sortOrder":161},
  {"id":"s_work_nvlt_80_162","chapterId":"ch_work_nvlt_80","text":"《異苑》曰：卞伯玉作東陽郡，竈正炽火，有雞遙從口入，良久，乃於突而出，毛羽不燋，鳴啄如故，伯玉尋病殒。","sortOrder":162},
  {"id":"s_work_nvlt_80_163","chapterId":"ch_work_nvlt_80","text":"《雜五行書》曰：作竈法，當辰巳間隙地取土，先掘去上五寸，以水美酒一升，合和泥之，以癸亥日脩之，此日安竈自如也，作竈法，廣四尺，長五尺，欲安兩釜，長七尺，子孫富貴，作竈餘泥，不可泥井，井餘土，不可泥竈，大凶，勿以壬癸庚辛，反支九空，血忌破危，閉建寅日，皆凶，竈君名禪，字子郭，衣黃衣，披發，從竈中出，知其名呼之，可得除凶惡贾市，不知其名，見之死，猪肝泥竈，令婦孝，竈君以壬子日死，不用此日治竈，常以五月辰日，猪頭祭竈，令人治生萬倍，用人故竈凶败，雞毛入竈中，致非禍，犬骨入竈，出狂子，正月己丑日，白雞祠竈，宜蠶，五月巳丑卯，祠竈吉，四月丁巳日，祠竈百倍。","sortOrder":163},
  {"id":"s_work_nvlt_80_164","chapterId":"ch_work_nvlt_80","text":"夢書曰：夢見竈者，忧求婦嫁女，何以言之，井竈女執使之象。","sortOrder":164},
  {"id":"s_work_nvlt_80_165","chapterId":"ch_work_nvlt_80","text":"【銘】後漢李尤竈銘曰：燧人造火，竈能以興，五行接備，陰陽相乘。","sortOrder":165},
  {"id":"s_work_nvlt_80_166","chapterId":"ch_work_nvlt_80","text":"晉挚虞竈屋銘曰：大孝養志，厥次養形，事親以敬，美過三牲。","sortOrder":166},
  {"id":"s_work_nvlt_80_167","chapterId":"ch_work_nvlt_80","text":"【箴】魏王朗雜箴曰：家人有嚴君焉，井竈之謂也，俾冬作夏，非竈孰能，俾夏作冬，非井孰言。","sortOrder":167},
  {"id":"s_work_nvlt_80_168","chapterId":"ch_work_nvlt_80","text":"◇薪炭灰","sortOrder":168},
  {"id":"s_work_nvlt_80_169","chapterId":"ch_work_nvlt_80","text":"《易》曰：古之死者，厚衣之以薪，葬之中野。","sortOrder":169},
  {"id":"s_work_nvlt_80_170","chapterId":"ch_work_nvlt_80","text":"《左傳》曰：厥父啗薪，其子弗克負荷。","sortOrder":170},
  {"id":"s_work_nvlt_80_171","chapterId":"ch_work_nvlt_80","text":"又曰：晉楚戰於城濮，楚左師潰，狐毛設二旆而退之，栾枝使舆曳薪柴而伪遁，楚師馳之，原軫郗凑以中軍公族橫击之，楚左師潰。","sortOrder":171},
  {"id":"s_work_nvlt_80_172","chapterId":"ch_work_nvlt_80","text":"《禮記》曰：問士之子長幼，長曰能負薪，幼曰未能負薪。","sortOrder":172},
  {"id":"s_work_nvlt_80_173","chapterId":"ch_work_nvlt_80","text":"又曰：季秋，乃命伐薪為炭，［事具炭部。］","sortOrder":173},
  {"id":"s_work_nvlt_80_174","chapterId":"ch_work_nvlt_80","text":"《毛詩》曰：折薪如之何，匪斧不克，取妻如之何，匪媒不得。","sortOrder":174},
  {"id":"s_work_nvlt_80_175","chapterId":"ch_work_nvlt_80","text":"《管子》曰：周容子夏，以侈靡見桓公，桓公曰：侈靡可以為天下乎，子夏曰：可，夫雕橑然後炊之，雕卯［按當作卵。］然後瀹之，所發積藏，散萬物也。","sortOrder":175},
  {"id":"s_work_nvlt_80_176","chapterId":"ch_work_nvlt_80","text":"《晏子》曰：景公遊寿宮，睹耆年負薪，有飢色，公喟然，令吏養之。","sortOrder":176},
  {"id":"s_work_nvlt_80_177","chapterId":"ch_work_nvlt_80","text":"《邓析書》曰：譬猶拯溺而硾之以石，救火而投之以薪。","sortOrder":177},
  {"id":"s_work_nvlt_80_178","chapterId":"ch_work_nvlt_80","text":"又曰：抱薪爇火，燥者先著。","sortOrder":178},
  {"id":"s_work_nvlt_80_179","chapterId":"ch_work_nvlt_80","text":"《戰國策》曰：蘇秦之楚，三日乃得見王，說卒辭行，楚王曰：先生不遠千里而臨寡人，曾弗肯留，原聞其說，對曰：楚國食貴於玉，薪貴於桂，謁者難見於鬼，王難見於帝，今令臣食玉炊桂，因鬼見帝，其可得乎。","sortOrder":179},
  {"id":"s_work_nvlt_80_180","chapterId":"ch_work_nvlt_80","text":"《漢書》曰：汲黯謂武帝曰：陛下之於群臣，如積薪，後來者居上。","sortOrder":180},
  {"id":"s_work_nvlt_80_181","chapterId":"ch_work_nvlt_80","text":"又曰：朱買臣，字翁子，吳人，家貧，好讀書，不治產業，刈薪樵出賣，以給食，簷束薪，行且誦書矣。","sortOrder":181},
  {"id":"s_work_nvlt_80_182","chapterId":"ch_work_nvlt_80","text":"范晔《漢書》曰：戴封拜議郎，遷西華令，大旱，封祷無獲，乃積薪坐其上，自焚，火起而大雨至，遠近嗟叹。","sortOrder":182},
  {"id":"s_work_nvlt_80_183","chapterId":"ch_work_nvlt_80","text":"《搜神記》曰：涼辅，廣漢人也，時旱，以五家［本書一百卷作官，此訛。］掾出祷，積薪柴自焚，須臾而雨作，［事具旱部。］","sortOrder":183},
  {"id":"s_work_nvlt_80_184","chapterId":"ch_work_nvlt_80","text":"《玄中記》曰：南方有炎山焉，行人以正月二月三月行過此山，取山下木以為薪，燃之無盡，取其皮，績之為火浣布，［神異經雲，玄山長四十里，生不盡木，已具布部。］","sortOrder":184},
  {"id":"s_work_nvlt_80_185","chapterId":"ch_work_nvlt_80","text":"《論衡》曰：或伐薪於山，輕小之木，合而束之，至於大木，十围以上，引之不能動，推之不能移，則委之於山林，收所束之小木而去，由此以論，知能之大者，其猶十围以上木也，人力不能舉荐，其猶薪者推引大木也，孔子周流，無所留止，非聖材不明，道難行，人不能用也。","sortOrder":185},
  {"id":"s_work_nvlt_80_186","chapterId":"ch_work_nvlt_80","text":"《神仙傳》曰：焦先日入山伐薪以布施，先從村頭一家起，周而复始。","sortOrder":186},
  {"id":"s_work_nvlt_80_187","chapterId":"ch_work_nvlt_80","text":"《晉中興書》曰：范汪，家貧好學，燃薪寫書，寫書既畢，誦讀亦竟。","sortOrder":187},
  {"id":"s_work_nvlt_80_188","chapterId":"ch_work_nvlt_80","text":"《世說》曰：荀公曾在晉武帝坐賜食，荀進飯，即謂坐人曰：此是勞薪炊也，坐者未之信，帝密遣問外，答雲，實是故車腳。","sortOrder":188},
  {"id":"s_work_nvlt_80_189","chapterId":"ch_work_nvlt_80","text":"《吳越春秋》曰：季札去徐而歸，行道逢男子，五月被裘，采薪於道，旁有委金，季札見之，謂薪者曰：子來取此金，薪者曰：君舉止何高，视何下也，五月被裘采薪，寧是拾金者乎，［事具隱逸部。］","sortOrder":189},
  {"id":"s_work_nvlt_80_190","chapterId":"ch_work_nvlt_80","text":"《汝南先賢傳》曰：蔡順以至孝稱，順少孤，養母，嘗出求薪，有客卒至，母望順不還，乃噬其指，順即心動，弃薪馳歸，恐問其故，母曰：有急客來，吾噬指以悟汝耳。","sortOrder":190},
  {"id":"s_work_nvlt_80_191","chapterId":"ch_work_nvlt_80","text":"又曰：侯瑾甚孤貧，依宋人居，晝為人佣賃，暮辄燃柴薪以讀書，［事具文部讀書篇。］","sortOrder":191},
  {"id":"s_work_nvlt_80_192","chapterId":"ch_work_nvlt_80","text":"後漢張奐報崔子玉書曰：今月三日，舉家居來此，本非所規，貪突賊陣。","sortOrder":192},
  {"id":"s_work_nvlt_80_193","chapterId":"ch_work_nvlt_80","text":"《魏略》曰：文钦為庐江太守，為都督王陵所奏，钦訴曹爽，爽謂曰：陵责卿載谭［疑當作燂。］灰兩舡，何為乎，聞足下起染舍，故作此灰耳。","sortOrder":193},
  {"id":"s_work_nvlt_80_194","chapterId":"ch_work_nvlt_80","text":"【詩】隋岑德润詠灰詩曰：圖規晕不缺，氣改律還虛，欲燃愁獄吏，弃道畏刑書，未得逢彊陣，輕舉欲焉如。","sortOrder":194},
  {"id":"s_work_nvlt_80_196","chapterId":"ch_work_nvlt_80","text":"《說文》曰：煙，火氣也，焆々然也。","sortOrder":196},
  {"id":"s_work_nvlt_80_197","chapterId":"ch_work_nvlt_80","text":"《列子》曰：趙襄子狩於山中，藉芿燔林，熻赫百里，有一人從石壁中出，隨煙燼上下，眾謂之鬼物，察之則人焉。","sortOrder":197},
  {"id":"s_work_nvlt_80_198","chapterId":"ch_work_nvlt_80","text":"《春秋繁露》曰：人之言榼去煙，此奇怪也，非人所意也，禍福利害，無有奇怪乎。","sortOrder":198},
  {"id":"s_work_nvlt_80_199","chapterId":"ch_work_nvlt_80","text":"《淮南子》曰：冬至甲子受製，木用事，火煙青，七十二日，戊子受製，土用事，火煙黃，七十二日，庚子受製，金用事，火煙黑。","sortOrder":199},
  {"id":"s_work_nvlt_80_200","chapterId":"ch_work_nvlt_80","text":"又曰：哭之發於口，涕之出於目，此憤於中而形於外也，譬水之下流，煙之上尋火，［按尋火二字，疑當作燅。］徒南反，［三字疑系燅字音切，當双行小註。］夫又孰推之。","sortOrder":200},
  {"id":"s_work_nvlt_80_201","chapterId":"ch_work_nvlt_80","text":"又曰：以束薪為鬼，以火煙為氣，惑也。","sortOrder":201},
  {"id":"s_work_nvlt_80_202","chapterId":"ch_work_nvlt_80","text":"《列仙傳》曰：寧封子，黃帝時人，為陶正，有神人過之，為其掌火，能令火出五色煙。","sortOrder":202},
  {"id":"s_work_nvlt_80_203","chapterId":"ch_work_nvlt_80","text":"又曰：教封子積薪自燒，而隨煙氣上，猶有骨，時人葬之。","sortOrder":203},
  {"id":"s_work_nvlt_80_204","chapterId":"ch_work_nvlt_80","text":"謝承《後漢書》曰：吳郡徐相，為長沙太守，常食乾飯，不發煙爨。","sortOrder":204},
  {"id":"s_work_nvlt_80_205","chapterId":"ch_work_nvlt_80","text":"許邁別傳曰：邁有道術，燒香皆五色煙出，後莫知所在。","sortOrder":205},
  {"id":"s_work_nvlt_80_206","chapterId":"ch_work_nvlt_80","text":"【詩】梁簡文帝詠煙詩曰：浮空覆雜影，含露密花藤，乍如洛霞發，頗似巫雲登，映光飛百仞，從風散九層，欲持翡翠色，時吐鯨魚燈。","sortOrder":206},
  {"id":"s_work_nvlt_80_207","chapterId":"ch_work_nvlt_80","text":"《藝文類聚》　唐·欧陽詢","sortOrder":207},
  {"id":"s_work_nvlt_81_1","chapterId":"ch_work_nvlt_81","text":"卷八十一藥香草部上","sortOrder":1},
  {"id":"s_work_nvlt_81_2","chapterId":"ch_work_nvlt_81","text":"○藥空青芍藥百合兔絲女萝款冬天門冬芣苡薯預菖蒲術草［香附出］蘭菊杜若蕙蘼芜鬱金迷迭芸香藿香鹿葱蜀葵薔薇藍慎火卷施","sortOrder":2},
  {"id":"s_work_nvlt_81_4","chapterId":"ch_work_nvlt_81","text":"《本草經》曰：太一子曰：凡藥上者養命，中者養性，下者養病。","sortOrder":4},
  {"id":"s_work_nvlt_81_5","chapterId":"ch_work_nvlt_81","text":"《禮記》曰：君有疾，飲藥，臣先嘗之，親有疾，飲藥，子先嘗之，医不三世，不服其藥。","sortOrder":5},
  {"id":"s_work_nvlt_81_6","chapterId":"ch_work_nvlt_81","text":"《左傳》曰：臧孫曰：季孫之愛我，疾疹也，孟孫之惡我，藥石也，美疹不如惡石。","sortOrder":6},
  {"id":"s_work_nvlt_81_7","chapterId":"ch_work_nvlt_81","text":"《尚書》曰：若藥弗瞑眩，厥疾弗瘳。","sortOrder":7},
  {"id":"s_work_nvlt_81_8","chapterId":"ch_work_nvlt_81","text":"《論語》曰：康子饋藥，拜而受之曰：丘未達，不敢嘗。","sortOrder":8},
  {"id":"s_work_nvlt_81_9","chapterId":"ch_work_nvlt_81","text":"墨子南遊，見楚惠王，穆贺謂《墨子》曰：子言誠善矣，王無乃曰：賤人所為，不用子，《墨子》曰：譬若藥焉，夫子食之，以療其疾，豈曰一草之本，而不食哉。","sortOrder":9},
  {"id":"s_work_nvlt_81_10","chapterId":"ch_work_nvlt_81","text":"《戰國策》曰：有獻不死之藥於荆王者，謁者操以入，中射之士問曰：可食乎，曰：可，因奪而食之，王怒，使人殺中射之士，中射之士使人說王曰：臣問謁者，謁者曰可食，臣故食之，是臣無罪，罪在謁者也，且客獻不死之藥，臣食之而王殺臣，是死藥也，王乃不殺。","sortOrder":10},
  {"id":"s_work_nvlt_81_11","chapterId":"ch_work_nvlt_81","text":"《史記》曰：長桑公與扁鵲藥，服之，三十日見人五藏。","sortOrder":11},
  {"id":"s_work_nvlt_81_12","chapterId":"ch_work_nvlt_81","text":"東方朔記曰：武帝好方士，朔曰：陛下所使取神藥者，皆天地之間藥，不能使人不死，獨使取神藥天上藥，能使人不死耳，上曰：天何可上，朔曰：臣能上天，既辭去，出殿門，复還曰：今臣上天，似謾誕者，原得一人為信验，上即遣方士與朔俱，期三十日而返，朔等辭而行，日日過諸侯傳飲，方士晝臥，朔遽呼之曰：若極久不應我何耶，今者屬從天上來，方士大驚，乃具以聞，上問朔，朔曰：誦天上之物，不可稱原，上以為面欺，詔朔下獄問之，左右方提去，朔啼泣對曰：使須幾死者再，上曰：何也，朔對曰：天公問臣，下方人何衣，臣對曰：衣虫，虫何若，臣對曰：虫喙〈舟頁〉々類馬，色邠邠類虎，天公大怒，以臣為謾，使使下問，還報，名曰蠶，天公乃出臣，今陛下苟以為诈，原使人上天問之，上大驚曰：善，欲以喻我止方士也。","sortOrder":12},
  {"id":"s_work_nvlt_81_13","chapterId":"ch_work_nvlt_81","text":"《淮南子》曰：羿請不死之藥於西王母，姮娥竊以奔月。","sortOrder":13},
  {"id":"s_work_nvlt_81_14","chapterId":"ch_work_nvlt_81","text":"《列仙傳》曰：負局先生者，負摩鏡局，循吳市中，得一錢便磨，辄問主人，得無有疾苦，若有，辄出紫丸藥以與之，得莫不愈。","sortOrder":14},
  {"id":"s_work_nvlt_81_15","chapterId":"ch_work_nvlt_81","text":"又曰：崔文子賣黃散，發疫死者萬計，服皆愈，愈者亦萬計。","sortOrder":15},
  {"id":"s_work_nvlt_81_16","chapterId":"ch_work_nvlt_81","text":"《漢武內傳》曰：西王母謂武帝曰：其太上之藥，乃有風實雲子，玉津金漿，冥陵驎胆，炎山夜日，東掇扶桑之丹椹，俯采長河之文藻，大真紅芝，九色鳳腦，有得食之，後天而老，此太上之所服，非眾仙之所寶也，次藥有班龍黑胎，阆風石髓，蒙山白鳳之，靈丘蒼鸞之血，有得服之，後天而逝，此天帝之所服，非下仙之所逮也，其次藥有丸丹金液，紫華紅芝，五雲之漿，玄霜絳雪，若得食之，白日升天，此飛仙之所服，非地仙之所見，其下藥有松柏之膏，山術［按本部術篇引，吳氏本草術一名山薑，此術字疑衍。］薑沉精，菊草泽寫，苟杞茯苓，菖蒲麥門冬，巨勝黃精，草類煩多，若有數千，子得服之，可以延年。","sortOrder":16},
  {"id":"s_work_nvlt_81_17","chapterId":"ch_work_nvlt_81","text":"《漢書》曰：灌夫击吳，身中大鎗十餘，適有萬金良藥，故得不死。","sortOrder":17},
  {"id":"s_work_nvlt_81_18","chapterId":"ch_work_nvlt_81","text":"《東觀漢記》曰：上嘗與朱祐［東觀漢記作祜，下同。］共買蜜合藥，上追念之，即賜祐白蜜一石，問何如在長安時共買蜜乎。","sortOrder":18},
  {"id":"s_work_nvlt_81_19","chapterId":"ch_work_nvlt_81","text":"曹毗《杜蘭香傳》曰：神女蘭香降張硕，硕問祷祀何如，香曰：消摩自可愈疾，淫祀無益，香以藥為消摩。","sortOrder":19},
  {"id":"s_work_nvlt_81_20","chapterId":"ch_work_nvlt_81","text":"邴原別傳曰：魏太子為五官郎將，原為長史，太子宴會，眾賓客數十人，太子建議曰：君父各［原訛冬，據冯校本改。］有篤疾，有藥一丸，可救一人，當救君耶，父耶，眾人紛葩，或君或父，時原在坐，不與此論，太子谘之於原，原勃然對曰：父也，太子亦不复難。","sortOrder":20},
  {"id":"s_work_nvlt_81_21","chapterId":"ch_work_nvlt_81","text":"《魏志》曰：太祖性嚴，掾屬公事，往往加杖，何夔常蓄毒藥，誓死無辱，是以終不見及。","sortOrder":21},
  {"id":"s_work_nvlt_81_22","chapterId":"ch_work_nvlt_81","text":"皇甫謐《高士傳》曰：韓康，字伯休，京兆灞陵人，常采藥名山，賣於長安市，口不二价，三十餘年，時女子從康買藥，康守价不移，女子怒曰：公是韓伯休耶，乃不二价，康叹曰：我本避名，今女子皆知有我，何用藥為，乃遁入灞陵山中。","sortOrder":22},
  {"id":"s_work_nvlt_81_23","chapterId":"ch_work_nvlt_81","text":"《晉陽秋》曰：吳陆抗與晉羊祜，推侨札之好，抗嘗遺祜酒，祜飲之不疑，抗有疾，祜饋之藥，抗亦推心而服之。","sortOrder":23},
  {"id":"s_work_nvlt_81_24","chapterId":"ch_work_nvlt_81","text":"《異苑》曰：魏武北征逾［《太平御覽》五百五十九作蹹。］頓，升嶺眺矚，見一岗不生百草，王粲曰：是古冢，此人在世服礬石死，而石生熱，蒸出外，故卉木燋滅，即令凿看，果得大墓，有礬石滿塋，仲宣博識強記，皆此類也，一說，粲在荆州，從劉表登彰山，見此異，按魏武之平乌丸，粲猶在荆南，此言為譎。","sortOrder":24},
  {"id":"s_work_nvlt_81_25","chapterId":"ch_work_nvlt_81","text":"沈約《宋書》曰：張袆，字少微，袆少有操行，歷官為琅琊王國郎中令，王還京都，高祖封酒一罌付袆，使密加王酖毒，袆受命既還，於道自飲藥酒而卒。","sortOrder":25},
  {"id":"s_work_nvlt_81_26","chapterId":"ch_work_nvlt_81","text":"【詩】古詩曰：仙人騎白鹿，發短耳何長，來至主人門，奉藥一玉箱，主人服此藥，身體日康強，發白复更黑，延年寿命長。","sortOrder":26},
  {"id":"s_work_nvlt_81_27","chapterId":"ch_work_nvlt_81","text":"宋鮑昭遇銅山采藥詩曰：土昉閟中經，術芝韜內策，寶餌缓童年，命藥駐衰歷，銅溪晝森沉，乳窦夜瀝滴，蹀蹀寒葉離，淙淙秋水積，松色隨野深，月露依草白。","sortOrder":27},
  {"id":"s_work_nvlt_81_28","chapterId":"ch_work_nvlt_81","text":"梁沈約憩郊園和約法師采藥詩曰：郭外三十畝，欲以貿朝饘，繁蔬既綺布，密果亦星懸。","sortOrder":28},
  {"id":"s_work_nvlt_81_29","chapterId":"ch_work_nvlt_81","text":"梁吳筠采藥大布山詩曰：我本北山北，緣涧采山麻，九茎日反照，三葉長生花，可用蠲忧疾，聊持駐景斜，景斜不可駐，年來果如駈，安得崑崙山，偃蹇三珠树，三珠始結荄，絳葉，凌朱台，玉台白鳳〈目弗〉，金鼎青龍胎，韓眾及王子，何世無仙才，安期傥欲顧，相見在蓬萊。","sortOrder":29},
  {"id":"s_work_nvlt_81_30","chapterId":"ch_work_nvlt_81","text":"陳劉删采藥遊名山詩曰：名山本鬱盤，道士貴黃冠，獨馭千年鶴，來尋五色丸，石床新溜乳，金竈欲成丹，定知無二价，非复在長安。","sortOrder":30},
  {"id":"s_work_nvlt_81_31","chapterId":"ch_work_nvlt_81","text":"【啟】梁劉孝綽謝給藥啟曰：一物之微，遂留亭育，名医上藥，爰自城府，雖巫鹹视诊，岐伯下針，松子玉漿，衛卿雲液，比妙競珍，實雲多愧。","sortOrder":31},
  {"id":"s_work_nvlt_81_32","chapterId":"ch_work_nvlt_81","text":"◇空青","sortOrder":32},
  {"id":"s_work_nvlt_81_33","chapterId":"ch_work_nvlt_81","text":"《本草經》曰：空青生山穀，久服輕身延年，能化銅鉛作金，生益州。","sortOrder":33},
  {"id":"s_work_nvlt_81_34","chapterId":"ch_work_nvlt_81","text":"范子《計然》曰：空青出巴郡，白青曾青出弘農，豫章白青出新淦，青色者善。","sortOrder":34},
  {"id":"s_work_nvlt_81_35","chapterId":"ch_work_nvlt_81","text":"《博物志》曰：徐公時，令人於西平青山，采取空青。","sortOrder":35},
  {"id":"s_work_nvlt_81_36","chapterId":"ch_work_nvlt_81","text":"江乘地記曰：樵采者，常於山上得空青，此山一朝出雲，零雨必降，民人以為常占。","sortOrder":36},
  {"id":"s_work_nvlt_81_37","chapterId":"ch_work_nvlt_81","text":"【賦】梁江淹空青賦曰：夫赤琼以照燎為光，碧石以葳蕤為色，鹹見珍於東國，併被貴於西極，况空青之麗寶，挺山海之不测，於是寫雲圖氣，學靈状仙，寶波麗水，華峰艳山，湯穀之树，崦嵫之泉，西海之草，炎州之煙，有曲帳畫屏，素女采扇，錦色雰鬱，綺质蔓延，點拂浓薄，如隱如見，山水萬象，丹青四变，鹹百溢而可珍，亦千金而不賤。","sortOrder":37},
  {"id":"s_work_nvlt_81_38","chapterId":"ch_work_nvlt_81","text":"◇芍藥","sortOrder":38},
  {"id":"s_work_nvlt_81_39","chapterId":"ch_work_nvlt_81","text":"《本草經》曰：芍藥一名白犬，生山穀及中嶽。","sortOrder":39},
  {"id":"s_work_nvlt_81_40","chapterId":"ch_work_nvlt_81","text":"《古今註》：芍藥一名可離。","sortOrder":40},
  {"id":"s_work_nvlt_81_41","chapterId":"ch_work_nvlt_81","text":"《毛詩》曰：惟士與女，伊其相謔，赠之以芍藥。","sortOrder":41},
  {"id":"s_work_nvlt_81_42","chapterId":"ch_work_nvlt_81","text":"【賦】宋王徽芍藥華賦曰：原夫神區之麗草兮，凭厚德而挺授，翕光液而發藻兮，颺風暉而振秀。","sortOrder":42},
  {"id":"s_work_nvlt_81_43","chapterId":"ch_work_nvlt_81","text":"【頌】晉傅統妻芍藥花頌曰：晔晔芍藥，植此前庭，晨润甘露，晝晞陽靈，曾不逾時，荏苒繁茂，绿葉青葱，應期秀吐，緗蕊攒挺，素華菲敷，光譬朝日，色艳芙蕖，媛人是采，以廁金翠，發彼妖容，增此婉媚，惟昔風人，抗茲榮華，聊用興思，染翰作歌。","sortOrder":43},
  {"id":"s_work_nvlt_81_44","chapterId":"ch_work_nvlt_81","text":"◇百合","sortOrder":44},
  {"id":"s_work_nvlt_81_45","chapterId":"ch_work_nvlt_81","text":"吳氏《本草》曰：百合一名重邁，一名中庭，一名重匡，生宛朐及荆山。","sortOrder":45},
  {"id":"s_work_nvlt_81_46","chapterId":"ch_work_nvlt_81","text":"【詩】梁宣帝詠百合詩曰：接葉有多重，开花無異色，含露或低垂，從風時偃抑。","sortOrder":46},
  {"id":"s_work_nvlt_81_47","chapterId":"ch_work_nvlt_81","text":"◇兔絲","sortOrder":47},
  {"id":"s_work_nvlt_81_48","chapterId":"ch_work_nvlt_81","text":"《爾雅》曰：唐蒙女萝，女萝兔絲。","sortOrder":48},
  {"id":"s_work_nvlt_81_49","chapterId":"ch_work_nvlt_81","text":"《呂氏春秋》曰：或謂兔絲無根也，其根不屬地，茯苓是也。","sortOrder":49},
  {"id":"s_work_nvlt_81_50","chapterId":"ch_work_nvlt_81","text":"《史記·龟策傳》曰：下有茯苓，上有兔絲。","sortOrder":50},
  {"id":"s_work_nvlt_81_51","chapterId":"ch_work_nvlt_81","text":"《淮南子》曰：兔絲無根而生，茯苓抽，兔絲死。","sortOrder":51},
  {"id":"s_work_nvlt_81_52","chapterId":"ch_work_nvlt_81","text":"《抱朴子》曰：按仙方中，自有合離草，一名獨搖，一名離母，所以謂之合離，離母者小草，為物下根如芋魁，有遊子十二枚，周環之，去大魁數尺，雖相須而實不連，但以氣相屬耳，如兔絲之草，下有伏兔之根，無此兔在下，則絲不得生於上，然實不屬也。","sortOrder":52},
  {"id":"s_work_nvlt_81_53","chapterId":"ch_work_nvlt_81","text":"又內篇雲，兔絲初生之根，其形似兔，掘取，剖其血以和丹，服之立变化，任意所作。","sortOrder":53},
  {"id":"s_work_nvlt_81_54","chapterId":"ch_work_nvlt_81","text":"【詩】齊謝朓兔絲詩曰：輕絲既難理，細縷竟無織，澜漫已萬條，連綿复一色，安根不可知，萦心終不测。","sortOrder":54},
  {"id":"s_work_nvlt_81_55","chapterId":"ch_work_nvlt_81","text":"◇女萝","sortOrder":55},
  {"id":"s_work_nvlt_81_56","chapterId":"ch_work_nvlt_81","text":"《廣雅》曰：女萝，松萝也，免絲也。","sortOrder":56},
  {"id":"s_work_nvlt_81_57","chapterId":"ch_work_nvlt_81","text":"《毛詩》曰：茑與女萝，施於松上。","sortOrder":57},
  {"id":"s_work_nvlt_81_58","chapterId":"ch_work_nvlt_81","text":"【詩】齊王融詠女萝詩曰：幂歷女萝草，蔓衍旁松枝，含煙黃且绿，因風卷复垂。","sortOrder":58},
  {"id":"s_work_nvlt_81_59","chapterId":"ch_work_nvlt_81","text":"陳劉删賦松上輕萝詩曰：葉繞千年蓋，條依百尺枝，屬與松風動，時將薜影垂，學帶非難結，為衣或易披，山河若近遠，獨自楚人知。","sortOrder":59},
  {"id":"s_work_nvlt_81_60","chapterId":"ch_work_nvlt_81","text":"◇款冬","sortOrder":60},
  {"id":"s_work_nvlt_81_61","chapterId":"ch_work_nvlt_81","text":"《本草經》曰：款冬一名顆冬，一名菟爰，生常山。","sortOrder":61},
  {"id":"s_work_nvlt_81_62","chapterId":"ch_work_nvlt_81","text":"《爾雅》曰：菟爰顆冬，［生水中，茎紫赤。］","sortOrder":62},
  {"id":"s_work_nvlt_81_63","chapterId":"ch_work_nvlt_81","text":"范子曰：款冬花出三辅。","sortOrder":63},
  {"id":"s_work_nvlt_81_64","chapterId":"ch_work_nvlt_81","text":"吳氏曰：款冬十二月花，花黃白。","sortOrder":64},
  {"id":"s_work_nvlt_81_65","chapterId":"ch_work_nvlt_81","text":"《述征記》曰：洛水至歲凝厲，則款冬茂悅曾冰之中。","sortOrder":65},
  {"id":"s_work_nvlt_81_66","chapterId":"ch_work_nvlt_81","text":"【賦】晉傅鹹款冬賦曰：惟茲奇卉，款冬而生，原厥初之載育，禀淳粹之至精，用能讬體固陰，利此堅貞，惡采紫之相奪，患居眾之易傾，在萬物之併作，故韜華而弗逞，遠皆死以枯槁，獨保质而全形。","sortOrder":66},
  {"id":"s_work_nvlt_81_67","chapterId":"ch_work_nvlt_81","text":"【贊】晉郭璞款冬贊曰：吹萬不同，陽煦陰蒸，款冬之生，擢穎堅冰，物體所安，焉知涣凝。","sortOrder":67},
  {"id":"s_work_nvlt_81_68","chapterId":"ch_work_nvlt_81","text":"◇天門冬","sortOrder":68},
  {"id":"s_work_nvlt_81_69","chapterId":"ch_work_nvlt_81","text":"《本草經》曰：天門冬一名顛勒，味苦，殺三虫。","sortOrder":69},
  {"id":"s_work_nvlt_81_70","chapterId":"ch_work_nvlt_81","text":"《爾雅》曰：薔靡葳冬。","sortOrder":70},
  {"id":"s_work_nvlt_81_71","chapterId":"ch_work_nvlt_81","text":"《山海經》曰：條穀山草多葳冬。","sortOrder":71},
  {"id":"s_work_nvlt_81_72","chapterId":"ch_work_nvlt_81","text":"《列仙傳》曰：赤項子食天門冬，齒落更生，細發复出。","sortOrder":72},
  {"id":"s_work_nvlt_81_73","chapterId":"ch_work_nvlt_81","text":"《抱朴子》曰：杜子微服天門冬，御十八妾，有子百四十人，日行三百里。","sortOrder":73},
  {"id":"s_work_nvlt_81_74","chapterId":"ch_work_nvlt_81","text":"又內篇曰：天門冬或名地門冬，或名筵門冬，或名顛棘。","sortOrder":74},
  {"id":"s_work_nvlt_81_75","chapterId":"ch_work_nvlt_81","text":"《神仙傳》曰：甘始者，太原人，服天門冬，在人間三百餘年。","sortOrder":75},
  {"id":"s_work_nvlt_81_76","chapterId":"ch_work_nvlt_81","text":"《建康記》曰：建康出天門冬，極精妙。","sortOrder":76},
  {"id":"s_work_nvlt_81_77","chapterId":"ch_work_nvlt_81","text":"《名山略記》曰：鬱州出天門冬。","sortOrder":77},
  {"id":"s_work_nvlt_81_78","chapterId":"ch_work_nvlt_81","text":"【啟】梁簡文帝謝敕赉益州天門冬啟曰：遠自星桥，見珍玉壘，本草稱其輕身，延寿實為上藥，姬晉之重丹桂，曹丕之愛落英，一家恩錫，竊幸往代。","sortOrder":78},
  {"id":"s_work_nvlt_81_79","chapterId":"ch_work_nvlt_81","text":"◇芣苡","sortOrder":79},
  {"id":"s_work_nvlt_81_80","chapterId":"ch_work_nvlt_81","text":"《爾雅》曰：芣苡，馬舄，馬舄，車前。","sortOrder":80},
  {"id":"s_work_nvlt_81_81","chapterId":"ch_work_nvlt_81","text":"《毛詩》曰：采采芣苡，薄言采之。","sortOrder":81},
  {"id":"s_work_nvlt_81_82","chapterId":"ch_work_nvlt_81","text":"【贊】晉郭璞芣苡贊曰：車前之草，別名芣苡，王會之雲，其實如李，名之相亂，在乎疑似。","sortOrder":82},
  {"id":"s_work_nvlt_81_83","chapterId":"ch_work_nvlt_81","text":"◇署預","sortOrder":83},
  {"id":"s_work_nvlt_81_84","chapterId":"ch_work_nvlt_81","text":"《本草經》曰：署預一名山芋，益氣力，長肌肉，除邪氣，久服輕身，耳目聰明，不飢延年，生嵩高山。","sortOrder":84},
  {"id":"s_work_nvlt_81_85","chapterId":"ch_work_nvlt_81","text":"吳氏曰：署預一名諸署。","sortOrder":85},
  {"id":"s_work_nvlt_81_86","chapterId":"ch_work_nvlt_81","text":"《湘中記》曰：永和初，有采藥衡山者，道迷糧盡，過息巖下，見一老公，四五年少，對執書，告之以飢，與其食物，如署預，指教所去，六日至家，而不复飢。","sortOrder":86},
  {"id":"s_work_nvlt_81_87","chapterId":"ch_work_nvlt_81","text":"《異苑》曰：署預入藥。又复可食，野人謂之土藷，若欲掘取，嘿然則獲，唱名者便不可得，人有植者，隨所种之物而像之也。","sortOrder":87},
  {"id":"s_work_nvlt_81_88","chapterId":"ch_work_nvlt_81","text":"【頌】梁江淹署預頌曰：華不可炫，葉不足怜，微根傥餌，弃劍為仙，黃金共寿，青艧爭年，君謂無妄，我验衡山。","sortOrder":88},
  {"id":"s_work_nvlt_81_89","chapterId":"ch_work_nvlt_81","text":"◇菖蒲","sortOrder":89},
  {"id":"s_work_nvlt_81_90","chapterId":"ch_work_nvlt_81","text":"《春秋運斗枢》曰：玉衡星散為菖蒲，遠雅頌，著倡優，則玉衡不明，菖蒲冠環。","sortOrder":90},
  {"id":"s_work_nvlt_81_91","chapterId":"ch_work_nvlt_81","text":"《山海經》曰：［按本條疑當移下羅浮山記一寸二十節句下，誤竄此。］菖蒲一十九節，韓終王興所服併然，而此過之，有足珍也。","sortOrder":91},
  {"id":"s_work_nvlt_81_92","chapterId":"ch_work_nvlt_81","text":"《左傳》曰：王使周公閱來聘饗，有昌歜。","sortOrder":92},
  {"id":"s_work_nvlt_81_93","chapterId":"ch_work_nvlt_81","text":"《孝經援神契》曰：菖蒲益聰。","sortOrder":93},
  {"id":"s_work_nvlt_81_94","chapterId":"ch_work_nvlt_81","text":"《抱朴子》曰：韓終服菖蒲十三年，身生毛。","sortOrder":94},
  {"id":"s_work_nvlt_81_95","chapterId":"ch_work_nvlt_81","text":"吳氏《本草》曰：菖蒲一名尧菲，一名昌陽。","sortOrder":95},
  {"id":"s_work_nvlt_81_96","chapterId":"ch_work_nvlt_81","text":"《神仙傳》曰：王興者，陽城人，漢武帝上嵩高，忽見有仙人，長二丈，耳出頭，下垂肩，帝禮而問之，仙人曰：吾九疑人也，聞中嶽有石上菖蒲，一寸九節，食之可以長生，故來采之，忽然不見，帝謂侍臣曰：彼非欲服食者，以此喻朕耳。","sortOrder":96},
  {"id":"s_work_nvlt_81_97","chapterId":"ch_work_nvlt_81","text":"《羅浮山記》曰：羅浮山中菖蒲，一寸二十節。","sortOrder":97},
  {"id":"s_work_nvlt_81_98","chapterId":"ch_work_nvlt_81","text":"【詩】梁江淹石上菖蒲詩曰：琼琴久芜没，金鏡废不看，不見空閨里，從橫愁思端，缓步遵汀渚，楊枻泛春澜，電至煙流綺，水绿桂涵丹，凭酒意未悅，半景方自叹，每為忧見及，杜若詎能宽，冀采石上草，得以駐餘顏。","sortOrder":98},
  {"id":"s_work_nvlt_81_99","chapterId":"ch_work_nvlt_81","text":"【頌】梁江淹菖蒲頌曰：藥實靈品，爰乃辅性，除痾衛福，蠲邪養正，縹色外妍，金光內映，草經所珍，山圖是詠。","sortOrder":99},
  {"id":"s_work_nvlt_81_101","chapterId":"ch_work_nvlt_81","text":"《本草經》曰：術一名山筋，久服不飢，輕身延年，生鄭山。","sortOrder":101},
  {"id":"s_work_nvlt_81_102","chapterId":"ch_work_nvlt_81","text":"《山海經》曰：首山之陰，多術，女幾之山，其草多術。","sortOrder":102},
  {"id":"s_work_nvlt_81_103","chapterId":"ch_work_nvlt_81","text":"吳氏《本草》曰：術一名山連，一名山芥，一名天蘇，一名山薑。","sortOrder":103},
  {"id":"s_work_nvlt_81_104","chapterId":"ch_work_nvlt_81","text":"范子曰：術出三辅，黃白色者善。","sortOrder":104},
  {"id":"s_work_nvlt_81_105","chapterId":"ch_work_nvlt_81","text":"《列仙傳》曰：涓子餌術，接食其精，三百年乃見於齊。","sortOrder":105},
  {"id":"s_work_nvlt_81_106","chapterId":"ch_work_nvlt_81","text":"崔寔《四民月令》曰：二月采術。","sortOrder":106},
  {"id":"s_work_nvlt_81_107","chapterId":"ch_work_nvlt_81","text":"《神仙傳》曰：陳子皇得餌術要方，服之得仙，入霍山去，其妻薑疲病，念其婿采術之法，服之，病自愈，至三百七歲，登山取術，簷而歸，不息不極，顏色氣力，如二十時。","sortOrder":107},
  {"id":"s_work_nvlt_81_108","chapterId":"ch_work_nvlt_81","text":"《抱朴子·內篇》曰：南陽文氏，其先祖漢中人，值亂，逃華山中，飢困欲死，有二人教之食術，雲，遂不飢，數十年，乃來還乡里，顏色更少，氣力轉勝，故術一名山精。","sortOrder":108},
  {"id":"s_work_nvlt_81_109","chapterId":"ch_work_nvlt_81","text":"《神藥經》曰：必欲長生，當服山精。","sortOrder":109},
  {"id":"s_work_nvlt_81_110","chapterId":"ch_work_nvlt_81","text":"《廣州記》曰：彰平縣偏饒術。","sortOrder":110},
  {"id":"s_work_nvlt_81_111","chapterId":"ch_work_nvlt_81","text":"《建康記》曰：建康出精術。","sortOrder":111},
  {"id":"s_work_nvlt_81_112","chapterId":"ch_work_nvlt_81","text":"《異術》曰：術草者，山之精也，結陰陽之精氣，服之令人長生絕穀，致神仙。","sortOrder":112},
  {"id":"s_work_nvlt_81_113","chapterId":"ch_work_nvlt_81","text":"【啟】梁庾肩吾答陶隱居赉術煎啟曰：竊以绿葉抽條，生於首峰之侧，紫花摽色，出自鄭巖之下，百邪外御，六府內充，山精見書，華神在箓，術榮火謝，盡采撷之難，啟旦移申，窮淋漉之剂，故能競爽雲珠，爭奇水玉，自非身疲掌砚，役倦攀桃，豈可立致還年，坐生羽翼，臨洗［疑當作沅。］丹井，方覺可捐，郦縣菊泉，無勞复汲，庶得遨遊海岸，追涓子之尘，馳骛霍山，共陳生為侣，謠俗輕施，尚曰難酬，出世鸿恩，寧知上報。","sortOrder":113},
  {"id":"s_work_nvlt_81_114","chapterId":"ch_work_nvlt_81","text":"又答陶隱居赉術蒸啟曰：味重金漿，芳逾玉液，足使芝慚明，［句有脱文。］丹愧芙蓉，坐致延生，伏深銘戴。","sortOrder":114},
  {"id":"s_work_nvlt_81_115","chapterId":"ch_work_nvlt_81","text":"◇草［香附出。］","sortOrder":115},
  {"id":"s_work_nvlt_81_116","chapterId":"ch_work_nvlt_81","text":"《爾雅》曰：卉，百草，總［名也。］草謂之榮，榮而實謂之英，荄，根也。","sortOrder":116},
  {"id":"s_work_nvlt_81_117","chapterId":"ch_work_nvlt_81","text":"《方言》曰：蘇芬莽草也，江淮南楚之間曰蘇，自關西曰草，或曰莽，南楚江湘之間，謂之莽。","sortOrder":117},
  {"id":"s_work_nvlt_81_118","chapterId":"ch_work_nvlt_81","text":"《周書》曰：霜降之日，草木黃落。","sortOrder":118},
  {"id":"s_work_nvlt_81_119","chapterId":"ch_work_nvlt_81","text":"《周官》曰：薙氏掌殺草，春始生而萌之，夏日至而夷之，秋繩而芟之，冬日至而耜之，［含實曰繩。］","sortOrder":119},
  {"id":"s_work_nvlt_81_120","chapterId":"ch_work_nvlt_81","text":"《毛詩》曰：無草不死，無木不萎。","sortOrder":120},
  {"id":"s_work_nvlt_81_121","chapterId":"ch_work_nvlt_81","text":"又曰：野有蔓草，零露团兮。","sortOrder":121},
  {"id":"s_work_nvlt_81_122","chapterId":"ch_work_nvlt_81","text":"又曰：湛湛露斯，在彼丰草。","sortOrder":122},
  {"id":"s_work_nvlt_81_123","chapterId":"ch_work_nvlt_81","text":"《大戴禮》曰：孟春冰泮，百草權舆。","sortOrder":123},
  {"id":"s_work_nvlt_81_124","chapterId":"ch_work_nvlt_81","text":"《師曠占》曰：黃帝問師曠曰：吾欲知苦樂善惡，可知否，對曰：歲欲丰，甘草先生，甘草荠也，歲欲苦，苦草先生，苦草亭苈也，歲欲惡，惡草先生，惡草水藻也，歲欲旱，旱草先生，旱草蒺藜也，歲欲疫病，病草先生，病草艾也。","sortOrder":124},
  {"id":"s_work_nvlt_81_125","chapterId":"ch_work_nvlt_81","text":"《博物志》曰：黃帝問天老曰：天地所生，豈有食之令人不死者乎，天老曰：太陽之草，名黃精，餌之可以長生，太陰之草，名曰鉤吻，不可食之，入口立死，人信鉤吻之殺人，不信黃精之益寿，不亦惑乎。","sortOrder":125},
  {"id":"s_work_nvlt_81_126","chapterId":"ch_work_nvlt_81","text":"【序】嵇含懷香賦序曰：餘以太蔟之月，登於歷山之陽，仰眺崇峦，俯察幽坂，及睹懷香，生蒙楚之間，曾見斯草，植於廣厦之庭，或被帝王之圃，怪其遐弃，遂遷而树於中唐，華麗則珠采婀娜，芳實則可以藏書。又感其弃本高崖，委身階庭，似傅說顯殷，四叟歸漢，故因事義賦之。","sortOrder":126},
  {"id":"s_work_nvlt_81_127","chapterId":"ch_work_nvlt_81","text":"【詩】古詩曰：四顧何茫茫，東風搖百草。","sortOrder":127},
  {"id":"s_work_nvlt_81_128","chapterId":"ch_work_nvlt_81","text":"又詩曰：新树蘭蕙葩，雜用杜衡草，終朝采其華，日暮不盈抱，采之欲遺誰，所思在遠道。","sortOrder":128},
  {"id":"s_work_nvlt_81_129","chapterId":"ch_work_nvlt_81","text":"又曰：穆穆清風至，吹我羅裳裾，青袍似春草，長條從風舒。","sortOrder":129},
  {"id":"s_work_nvlt_81_130","chapterId":"ch_work_nvlt_81","text":"又曰：青青陵中草，傾葉晞朝日，陽春被惠泽，枝葉可攬結。","sortOrder":130},
  {"id":"s_work_nvlt_81_131","chapterId":"ch_work_nvlt_81","text":"魏劉楨詩曰：青青女萝草，上依高松枝，幸蒙庇養恩，分惠不可赀，風雨雖急疾，根株不傾移。","sortOrder":131},
  {"id":"s_work_nvlt_81_132","chapterId":"ch_work_nvlt_81","text":"梁元帝細草詩曰：依階疑绿癬，傍渚若青苔，漫生雖欲遍，人跡會應开。","sortOrder":132},
  {"id":"s_work_nvlt_81_133","chapterId":"ch_work_nvlt_81","text":"梁丘遲玉階春草詩曰：發溜始參差，扶階方沃若，雜葉半藏蜻，丛花未隱雀，葳蕤亂碧紫，蒼黃間浓薄。","sortOrder":133},
  {"id":"s_work_nvlt_81_134","chapterId":"ch_work_nvlt_81","text":"陳劉删詠青草詩曰：雨沐三春葉，風傳十步香，映袍怜色重，臨書喜帶長。","sortOrder":134},
  {"id":"s_work_nvlt_81_135","chapterId":"ch_work_nvlt_81","text":"【賦】晉傅玄紫華賦曰：紫華一名長樂華，舊生於蜀，其東界特饒，中國奇而种种，餘嘉其華純耐久，可歷冬而服，故與友生，各為之賦，有遐方之奇草，禀二氣之純精，仰紫微之景曜，因令色以定名，刚茎劲立，纖條繁列，從回風以搖動，紛蘭畅而蕙絜，蔚青葱以增茂，併含華而未發，於是散绿葉，秀紫榮，蘊若芝草之始敷，灼若百枝之在庭，獨參差以炤燿，何光麗之雜形，涣涣昱昱，奪人目精，下無物以借喻，上取象於朝霞，妙萬物而比艳，莫茲草之可嘉。","sortOrder":135},
  {"id":"s_work_nvlt_81_136","chapterId":"ch_work_nvlt_81","text":"梁萧子暉冬草賦曰：有閒居之蔓草，獨幽隱而羅生，對離披之苦節，反葳蕤而有情，若夫火山滅焰，湯泉沸泻，日悠扬而少色，天陰霖而四下，於時直木先摧，曲蓬多陨，眾芳漼而萎絕，百卉飒以徂盡，未若茲草，凌霜自保，挺秀色於冰涂，厲貞心於寒道，已矣哉，徒撫心其何益，但使萬物之後凋，夫何獨知於松柏。","sortOrder":136},
  {"id":"s_work_nvlt_81_137","chapterId":"ch_work_nvlt_81","text":"梁沈約愍衰草賦曰：愍衰草，衰草無容色，憔悴荒径中，寒荄不可識，昔時兮春日，昔日兮春風，衔華兮佩實，垂绿兮散紅，巖陬兮海岸，冰多兮霰積，布綿密於寒皋，吐纖疏於危石，彫芳卉之九衢，霣靈茅之三脊，風急崤道難，秋至客衣单，既傷簷下菊，复悲池上蘭，飄落逐風盡，方知歲早寒，流螢暗明燭，雁聲斷裁續，霜奪茎上紫，風銷葉中绿，秋鸿兮疏引，寒乌兮聚飛，径荒寒草合，草長荒径微，園庭漸芜没，霜露日霑衣。","sortOrder":137},
  {"id":"s_work_nvlt_81_138","chapterId":"ch_work_nvlt_81","text":"【贊】卞敬宗懷香贊曰：有卉惟翠，因實製名，濛濛菉葉，荏荏弱茎，寄芬微風，寓秀閒庭，懷而芳之，為玩於情。","sortOrder":138},
  {"id":"s_work_nvlt_81_139","chapterId":"ch_work_nvlt_81","text":"宋謝惠連仙人草贊曰：餘之中園，有仙人草焉，春穎其苗，夏秀其英，秋有貞實，冬無雕色，可謂貫四時而不改者也，既嘉其名，而美其质，染筆作詠，庶以摅述雲，園有嘉草，名曰仙人，晔晔煒煒，莫莫臻臻，穎發炎暑，苗秀和春，奇爾靈质，乃植中鄰。","sortOrder":139},
  {"id":"s_work_nvlt_81_141","chapterId":"ch_work_nvlt_81","text":"《說文》曰：蘭，香草也。","sortOrder":141},
  {"id":"s_work_nvlt_81_142","chapterId":"ch_work_nvlt_81","text":"《易》曰：同心之言，其臭如蘭，［蘭，芳也。］","sortOrder":142},
  {"id":"s_work_nvlt_81_143","chapterId":"ch_work_nvlt_81","text":"《禮記》曰：婦人或賜之茝蘭，則受，獻諸舅姑，《左傳》曰：鄭文公有賤妾，曰燕姞，夢天使與己蘭，曰：餘為伯儵，餘而祖也，以是為而子，以蘭有國香，人服媚之，文公與之蘭而御之，辭曰：妾不才，幸而有子，將不信，敢徵蘭乎，公曰：诺，生穆公，名之曰蘭。","sortOrder":143},
  {"id":"s_work_nvlt_81_144","chapterId":"ch_work_nvlt_81","text":"《家語》曰：芝蘭生於深林，不以無人而不芳，君子修道立德，不為困窮而改節。","sortOrder":144},
  {"id":"s_work_nvlt_81_145","chapterId":"ch_work_nvlt_81","text":"《文子》曰：日月欲明，浮雲蓋之，丛蘭脩發，秋風败之。","sortOrder":145},
  {"id":"s_work_nvlt_81_146","chapterId":"ch_work_nvlt_81","text":"又曰：蘭芷不為莫服而不芳，君子行道，不為莫知而止。","sortOrder":146},
  {"id":"s_work_nvlt_81_147","chapterId":"ch_work_nvlt_81","text":"《離骚》曰：□［離骚作餘。］既滋蘭之九畹兮，畹，畦也。","sortOrder":147},
  {"id":"s_work_nvlt_81_148","chapterId":"ch_work_nvlt_81","text":"又曰：纫秋蘭以為佩。","sortOrder":148},
  {"id":"s_work_nvlt_81_149","chapterId":"ch_work_nvlt_81","text":"又曰：秋蘭兮糜芜，羅生兮堂下，绿葉兮素茎，芳菲兮袭予，秋蘭兮青青，绿葉兮紫茎。","sortOrder":149},
  {"id":"s_work_nvlt_81_150","chapterId":"ch_work_nvlt_81","text":"《孫卿子》曰：民之好我芬若椒蘭。","sortOrder":150},
  {"id":"s_work_nvlt_81_151","chapterId":"ch_work_nvlt_81","text":"《琴操》曰：猗蘭操者，孔子所作也，孔子聘諸侯，莫能任，自衛反魯，隱穀之中。見香蘭獨茂，喟然叹曰：夫蘭當為王者香，今乃獨茂，與眾草為伍，乃止車，援琴鼓之，自傷不逢時，讬辭於香蘭雲。","sortOrder":151},
  {"id":"s_work_nvlt_81_152","chapterId":"ch_work_nvlt_81","text":"《蜀志》曰：先主殺張裕，諸葛亮救之，先主曰：芳蘭當門，不得不鋤。","sortOrder":152},
  {"id":"s_work_nvlt_81_153","chapterId":"ch_work_nvlt_81","text":"《語林》曰：謝太傅問諸子侄曰：子弟何預人事，而政欲使其佳，［原訛往，據冯校本改。］諸人莫有言者，車騎答曰：譬如芝蘭玉树，欲使生於階庭。","sortOrder":153},
  {"id":"s_work_nvlt_81_154","chapterId":"ch_work_nvlt_81","text":"【詩】後漢郦炎蘭詩曰：靈芝生河洲，動搖因洪波，秋蘭榮何晚，嚴霜悴其柯，哀哉二芳草，不植太山阿。","sortOrder":154},
  {"id":"s_work_nvlt_81_155","chapterId":"ch_work_nvlt_81","text":"晉傅玄詠秋蘭詩曰：秋蘭荫玉池，池水清其芳，双魚自踴躍，兩鳥時回翔。","sortOrder":155},
  {"id":"s_work_nvlt_81_156","chapterId":"ch_work_nvlt_81","text":"【賦】陳周弘讓山蘭賦曰：爰有奇特之草，產於空崖之地，仰鳥路而裁通。视行蹤而莫至，挺自然之高介，豈眾情之服媚，寧纫結之可求，兆延佇之能洎，禀造化而均育，與卉木而齊致，入坦道而銷聲，屏山幽而靜異，獨見識於琴台，竊逢知於綺季。","sortOrder":156},
  {"id":"s_work_nvlt_81_158","chapterId":"ch_work_nvlt_81","text":"《爾雅》曰：菊，治廧，［今之秋華菊也。］","sortOrder":158},
  {"id":"s_work_nvlt_81_159","chapterId":"ch_work_nvlt_81","text":"《山海經》曰：女幾之山，其草多菊。","sortOrder":159},
  {"id":"s_work_nvlt_81_160","chapterId":"ch_work_nvlt_81","text":"《禮記》曰：季秋之月，菊有黃花。","sortOrder":160},
  {"id":"s_work_nvlt_81_161","chapterId":"ch_work_nvlt_81","text":"《楚辭》曰：朝飲木蘭之墜露兮，夕餐秋菊之落英。","sortOrder":161},
  {"id":"s_work_nvlt_81_162","chapterId":"ch_work_nvlt_81","text":"又曰：春蘭兮秋菊，長無絕兮終古。","sortOrder":162},
  {"id":"s_work_nvlt_81_163","chapterId":"ch_work_nvlt_81","text":"《風俗通》曰：南陽郦縣，有甘穀，穀水甘美，雲其山上大有菊，水從山上流下，得其滋液，穀中有三十餘家，不复穿井，悉飲此水，上寿百二三十，中百餘，下七八十者，名之大夭，菊華輕身益氣故也，司空王畅太尉劉宽太尉袁隗為南陽太守，聞有此事，令郦縣月送水二十斛，用之飲食，諸公多患風眩，皆得瘳。","sortOrder":163},
  {"id":"s_work_nvlt_81_164","chapterId":"ch_work_nvlt_81","text":"崔寔月令，九月九日，可采菊花。","sortOrder":164},
  {"id":"s_work_nvlt_81_165","chapterId":"ch_work_nvlt_81","text":"盛弘之《荆州記》曰：郦縣菊水，太尉胡廣，久患風羸，恒汲飲此水，後疾遂瘳，年近百歲，非唯天寿，亦菊延之，此菊甘美，廣後收此菊實，播之京師，處處傳埴。","sortOrder":165},
  {"id":"s_work_nvlt_81_166","chapterId":"ch_work_nvlt_81","text":"《神仙傳》曰：康風子，服甘菊花柏實散得仙。","sortOrder":166},
  {"id":"s_work_nvlt_81_167","chapterId":"ch_work_nvlt_81","text":"《抱朴子》曰：劉生丹法，用白菊花汁莲汁樗汁，和丹蒸之，服一年，寿五百歲。","sortOrder":167},
  {"id":"s_work_nvlt_81_168","chapterId":"ch_work_nvlt_81","text":"又曰：菊花與薏花相似，直以甘苦別之耳，菊甘而薏苦諺所謂苦如薏者也，今所有真菊，但為少耳。","sortOrder":168},
  {"id":"s_work_nvlt_81_169","chapterId":"ch_work_nvlt_81","text":"《續晉陽秋》曰：陶潛無酒，坐宅邊菊丛中，采摘盈把，望見王弘遣送酒，即便就酌。","sortOrder":169},
  {"id":"s_work_nvlt_81_170","chapterId":"ch_work_nvlt_81","text":"【詩】晉袁山松菊詩曰：靈菊植幽崖，擢穎凌寒飆，春露下染色，秋霜不改條。","sortOrder":170},
  {"id":"s_work_nvlt_81_171","chapterId":"ch_work_nvlt_81","text":"梁王筠摘園菊赠謝仆射舉詩曰：靈茅挺三脊，神芝曜九明，菊花偏可憙，碧葉媚金英，重九惟嘉節，抱一應元貞，泛酌宜長久，聊荐野人誠。","sortOrder":171},
  {"id":"s_work_nvlt_81_172","chapterId":"ch_work_nvlt_81","text":"【賦】魏鍾會菊花賦，何秋菊之奇兮，獨華茂乎凝霜，挺葳蕤於蒼春兮，表壮觀乎金商，延蔓蓊鬱，緣坂被岗，縹幹绿葉，青柯紅芒，芳實離離，暉藻煌煌，微風扇動，照曜垂光，於是季秋初九，日數將併，置酒華堂，高會娱情，百卉彫瘁，芳菊始榮，紛葩韡晔，或黃或青，乃有毛嫱西施，荆姬秦嬴，妍姿妖艳，一顧傾城，擢纖纖之素手，宣皓腕而露形，仰撫雲髻，俯弄芳榮。","sortOrder":172},
  {"id":"s_work_nvlt_81_173","chapterId":"ch_work_nvlt_81","text":"又雲，夫菊有五美焉，黃華高懸，准天極也，純黃不雜，後土色也，早植晚登，君子德也，冒霜吐穎，象劲直也，流中輕體，神仙食也。","sortOrder":173},
  {"id":"s_work_nvlt_81_174","chapterId":"ch_work_nvlt_81","text":"晉孫楚菊花賦曰：彼芳菊之為草兮，禀自然之醇精，當青春而潛翳兮，迄素秋而敷榮，於是和樂公子，雍容無為，翱翔華林，駿足交馳，薄言采之，手折纖枝，飛金英以浮旨酒，掘翠葉以振羽儀，伟茲物之珍麗兮，超庶類而神奇。","sortOrder":174},
  {"id":"s_work_nvlt_81_175","chapterId":"ch_work_nvlt_81","text":"晉潘尼秋菊賦曰：垂采煒於芙蓉，流芳越乎蘭林，遊女望榮而巧笑，鵷雏遙集而弄音，若乃真人采其實，王母接其葩，或充虛而養氣，或增妖而楊娥，既延期以永寿。又蠲疾而弭痾。","sortOrder":175},
  {"id":"s_work_nvlt_81_176","chapterId":"ch_work_nvlt_81","text":"晉盧湛菊花賦曰：浸三泉而結根，晞九陽而擢茎，若乃翠葉雲布，黃蕊星羅。","sortOrder":176},
  {"id":"s_work_nvlt_81_177","chapterId":"ch_work_nvlt_81","text":"晉傅玄菊賦曰：布濩河洛，縱橫齊秦，掇以纖手，承以輕巾，服之者長寿，食之者通神。","sortOrder":177},
  {"id":"s_work_nvlt_81_178","chapterId":"ch_work_nvlt_81","text":"齊卞伯玉菊賦曰：佇寒丘以弥望，觌中霜之软菊，肇三春而懷芬，陵九秋以愈馥，不履苦而淪操不在同而表淑，傷眾花之飄落，嘉滋卉之能靈，振劲朔以楊渌，含凝露而吐英。","sortOrder":178},
  {"id":"s_work_nvlt_81_179","chapterId":"ch_work_nvlt_81","text":"【銘】晉王淑之蘭菊銘曰：蘭既春敷，菊又秋榮，芳薰百草，色艳群英，孰是芳质，在幽愈馨。","sortOrder":179},
  {"id":"s_work_nvlt_81_180","chapterId":"ch_work_nvlt_81","text":"晉嵇含菊花銘曰：煌煌丹菊，翠葉紫茎，诜诜仙神，徒餐落英。","sortOrder":180},
  {"id":"s_work_nvlt_81_181","chapterId":"ch_work_nvlt_81","text":"晉成公綏菊花銘曰：數在二九，時惟斯生。","sortOrder":181},
  {"id":"s_work_nvlt_81_182","chapterId":"ch_work_nvlt_81","text":"【頌】晉成公綏菊花頌曰：先民有作，詠茲秋菊，绿葉黃花，菲菲彧彧，芳逾蘭蕙，茂過松竹，其茎可玩，其葩可服，味之不已，松乔等福。","sortOrder":182},
  {"id":"s_work_nvlt_81_183","chapterId":"ch_work_nvlt_81","text":"晉傅統妻菊花頌曰：英英麗草，禀氣靈和，春茂翠葉，秋曜金華，布濩高原，蔓衍陵阿，陽芳吐馥，載芬載葩，爰采爰拾，投之醇酒，御於王公，以介眉寿，服之延年，佩之黃耇，文園賓客，乃用不朽。","sortOrder":183},
  {"id":"s_work_nvlt_81_184","chapterId":"ch_work_nvlt_81","text":"爾雅圖贊曰：菊名日精，布華玄月，仙客薄采，何忧華發。","sortOrder":184},
  {"id":"s_work_nvlt_81_185","chapterId":"ch_work_nvlt_81","text":"◇杜若","sortOrder":185},
  {"id":"s_work_nvlt_81_186","chapterId":"ch_work_nvlt_81","text":"《爾雅》曰：杜若土滷，［香草也。］","sortOrder":186},
  {"id":"s_work_nvlt_81_187","chapterId":"ch_work_nvlt_81","text":"《廣雅》曰：楚，蘅也。","sortOrder":187},
  {"id":"s_work_nvlt_81_188","chapterId":"ch_work_nvlt_81","text":"《本草經》曰：杜若一名杜蘅，味辛微溫，久服益氣輕身，范子《計然》曰：杜若出南郡漢中。","sortOrder":188},
  {"id":"s_work_nvlt_81_189","chapterId":"ch_work_nvlt_81","text":"《山海經》曰：天帝之山，有草焉，状如葵，臭如蘼芜，名曰杜蘅，可以走馬，［帶香草，令人便馬，或曰：馬得之健走。］","sortOrder":189},
  {"id":"s_work_nvlt_81_190","chapterId":"ch_work_nvlt_81","text":"《離骚》曰：采芳洲兮杜若，將以遺兮下女。","sortOrder":190},
  {"id":"s_work_nvlt_81_191","chapterId":"ch_work_nvlt_81","text":"又曰：雜杜蘅與芳芷。","sortOrder":191},
  {"id":"s_work_nvlt_81_192","chapterId":"ch_work_nvlt_81","text":"又曰：山中人兮芳杜若，飲石泉兮荫松柏。","sortOrder":192},
  {"id":"s_work_nvlt_81_193","chapterId":"ch_work_nvlt_81","text":"【詩】梁沈約詠杜若詩曰：生在窮絕地，豈與世相親，不顧逢采撷，本欲芳幽人。","sortOrder":193},
  {"id":"s_work_nvlt_81_194","chapterId":"ch_work_nvlt_81","text":"【賦】齊謝朓杜若賦曰：冯瑤圃而宣遊，籍幽蘭而夷與，覽茲榮之苑茂，紛為芳於清篽，觀夫結根擢色，發曜垂英，緣春峦以纖布，荫涼潭而影清。","sortOrder":194},
  {"id":"s_work_nvlt_81_195","chapterId":"ch_work_nvlt_81","text":"【頌】梁江淹杜若頌曰：山中杜若，嘉爾翠质，不奇不俗，栽華栽實，同衔夕露，共蜅朝日，夷陂無二，沉冥如一。","sortOrder":195},
  {"id":"s_work_nvlt_81_197","chapterId":"ch_work_nvlt_81","text":"《廣志》曰：蕙草绿葉紫花，魏武帝以為香燒之。","sortOrder":197},
  {"id":"s_work_nvlt_81_198","chapterId":"ch_work_nvlt_81","text":"《離骚》曰：川穀径复流潺湲，光風轉蕙汜崇蘭。","sortOrder":198},
  {"id":"s_work_nvlt_81_199","chapterId":"ch_work_nvlt_81","text":"又曰：树蕙之百畝。","sortOrder":199},
  {"id":"s_work_nvlt_81_200","chapterId":"ch_work_nvlt_81","text":"又曰：薜荔拍兮蕙綢，［薜荔，香草，拍，榑壁也，綢，縛束也，詩雲，綢缪束楚。］","sortOrder":200},
  {"id":"s_work_nvlt_81_201","chapterId":"ch_work_nvlt_81","text":"《山海經》曰：天帝之山，其下多蕙，外山之下，其草蕙。","sortOrder":201},
  {"id":"s_work_nvlt_81_202","chapterId":"ch_work_nvlt_81","text":"【詩】漢繁钦詠蕙詩曰：蕙草生山北，讬身失所依，植根陰崖侧，夙夜懼危頹，寒泉浸我根，凄風常徘徊，三光照八極，獨不蒙餘暉，葩葉永彫悴，凝露不暇晞，百卉皆含榮，已獨失時姿，比我英芳發，鶗窸鳴已哀。","sortOrder":202},
  {"id":"s_work_nvlt_81_203","chapterId":"ch_work_nvlt_81","text":"◇蘼芜","sortOrder":203},
  {"id":"s_work_nvlt_81_204","chapterId":"ch_work_nvlt_81","text":"《廣志》曰：薇芜香草，魏武帝以藏衣中。","sortOrder":204},
  {"id":"s_work_nvlt_81_205","chapterId":"ch_work_nvlt_81","text":"《楚辭》曰：秋蘭兮蘼芜，羅生兮堂下，绿葉兮素枝，芳菲兮袭予，《管子》曰：五沃之土，生蘼芜。","sortOrder":205},
  {"id":"s_work_nvlt_81_206","chapterId":"ch_work_nvlt_81","text":"《本草經》曰：蘼芜一名薇芜，味辛。","sortOrder":206},
  {"id":"s_work_nvlt_81_207","chapterId":"ch_work_nvlt_81","text":"【詩】古詩曰：上山采蘼芜，下山逢故夫。","sortOrder":207},
  {"id":"s_work_nvlt_81_208","chapterId":"ch_work_nvlt_81","text":"【贊】郭璞贊曰：蘼芜善草，亂之蛇床，不陨其實，自列以芳，佞人似智，巧言如簧。","sortOrder":208},
  {"id":"s_work_nvlt_81_209","chapterId":"ch_work_nvlt_81","text":"◇鬱金","sortOrder":209},
  {"id":"s_work_nvlt_81_210","chapterId":"ch_work_nvlt_81","text":"《說文》曰：鬱金芳草也，十葉為貫，百二十貫，采以煮之為鬯，一曰：鬱鬯百草之華，遠方所貢芳物，合而酿之以降神。","sortOrder":210},
  {"id":"s_work_nvlt_81_211","chapterId":"ch_work_nvlt_81","text":"《魏略》曰：大秦國出鬱金。","sortOrder":211},
  {"id":"s_work_nvlt_81_212","chapterId":"ch_work_nvlt_81","text":"【賦】漢朱公叔鬱金賦曰：歲朱明之首月兮，步南園以迥眺，覽草木之紛葩兮，美斯華之英妙，布绿葉而挺心，吐芳榮而發曜，眾華烂以俱發，鬱金邈其無双，比光榮於秋菊，齊英茂乎春松，遠而望之，粲若羅星出雲垂，近而觀之，晔若丹桂曜湘涯，赫乎扈扈，萋兮猗猗，清風逍遙，芳越景移，上灼朝日，下映蘭池，睹茲榮之瑰異，副歡情之所望，折英華以飾首，耀靜女之儀光，瞻百草之青青，羌朝榮而夕零，美鬱金之純伟，獨弥日而久停，晨露未晞，微風肅清，增妙容之美麗，發朱顏之熒熒，作椒房之珍玩，超眾葩之獨靈。","sortOrder":212},
  {"id":"s_work_nvlt_81_213","chapterId":"ch_work_nvlt_81","text":"晉傅玄鬱金賦曰：葉萋萋以翠青，英蘊蘊而金黃，树菴藹以成荫，氣芳馥而含芳，凌蘇合之珠珍，豈艾網之足方，榮耀帝寓，香播紫宮，吐芬楊烈，萬里望風。","sortOrder":213},
  {"id":"s_work_nvlt_81_214","chapterId":"ch_work_nvlt_81","text":"【頌】晉左九嫔鬱金頌曰：伊此奇草，名曰鬱金，越自殊域，厥珍來尋，芬香酷烈，悅目欣心，明德惟馨，淑人是钦，窈窕妃媛，服之褵衿，永垂名實，曠世弗沉。","sortOrder":214},
  {"id":"s_work_nvlt_81_215","chapterId":"ch_work_nvlt_81","text":"◇迷迭","sortOrder":215},
  {"id":"s_work_nvlt_81_216","chapterId":"ch_work_nvlt_81","text":"《廣志》曰：迷迭出西域。","sortOrder":216},
  {"id":"s_work_nvlt_81_217","chapterId":"ch_work_nvlt_81","text":"【詩】樂府歌詠詩曰：氍〈登瓦〉五水［《太平御覽》九百八十二作味。］香，迷迭艾網及都良。","sortOrder":217},
  {"id":"s_work_nvlt_81_218","chapterId":"ch_work_nvlt_81","text":"【賦】魏文帝迷迭賦曰：坐中堂以遊觀兮，覽芳草之树庭，垂妙葉於纖枝兮，楊脩幹而結茎，承靈露以润根兮，嘉日日而敷榮，隨回風以搖動兮，吐芳氣之穆清，薄西夷之秽俗兮，越萬里而來征，豈眾卉之足方兮，信希世而特生。","sortOrder":218},
  {"id":"s_work_nvlt_81_219","chapterId":"ch_work_nvlt_81","text":"魏陳王曹植迷迭香賦曰：播西都之麗草兮，應青春而發暉，流翠葉於纖柯兮，結微根於丹墀，信繁華之速實兮，弗見彫於嚴霜，芳暮秋之幽蘭兮，麗崑崙之芝英，既經時而收采兮，遂幽殺以增芳，去枝葉而特御兮，入绡縠之霧裳，附玉體以行止兮，順微風而舒光。","sortOrder":219},
  {"id":"s_work_nvlt_81_220","chapterId":"ch_work_nvlt_81","text":"魏王粲迷迭賦曰：惟遐方之珍草兮，產崑崙之極幽，受中和之正氣兮，承陰陽之靈休，扬丰馨於西裔兮，布和种於中州，去原野之侧陋兮，植高宇之外庭，布萋萋之茂葉兮，挺苒苒之柔茎，色光润而采發兮，以孔翠之扬精。","sortOrder":220},
  {"id":"s_work_nvlt_81_221","chapterId":"ch_work_nvlt_81","text":"魏應玚迷迭賦曰：列中堂之嚴宇，跨階序而骈羅，建茂茎以竦立，擢脩幹而承阿，燭白日之炎陽，承翠碧之繁柯，朝敷條以誕節，夕結秀而垂華，振纖枝之翠粲，動采葉之莓莓，舒芳香之酷烈，乘清風以徘徊。","sortOrder":221},
  {"id":"s_work_nvlt_81_222","chapterId":"ch_work_nvlt_81","text":"魏陳琳迷迭賦曰：立碧茎之婀娜，鋪采條之蜿蟺，下扶疏以布濩，上綺错而交紛，匪荀方之可樂，實來儀之麗閒，動容飾而微發，穆斐斐以承顏。","sortOrder":222},
  {"id":"s_work_nvlt_81_223","chapterId":"ch_work_nvlt_81","text":"◇芸香","sortOrder":223},
  {"id":"s_work_nvlt_81_224","chapterId":"ch_work_nvlt_81","text":"《禮記月令》曰：仲春之月，芸始生。［香草。］","sortOrder":224},
  {"id":"s_work_nvlt_81_225","chapterId":"ch_work_nvlt_81","text":"《仓頡解詁》曰：芸蒿似邪蒿，香可食。","sortOrder":225},
  {"id":"s_work_nvlt_81_226","chapterId":"ch_work_nvlt_81","text":"《洛陽宮殿簿》曰：顯陽殿前芸香一株，徽音殿前芸香二株，含章殿前芸香二株。","sortOrder":226},
  {"id":"s_work_nvlt_81_227","chapterId":"ch_work_nvlt_81","text":"《晉室閣名》曰：太極殿前，芸香四畦，式乾殿前，芸香八畦。","sortOrder":227},
  {"id":"s_work_nvlt_81_228","chapterId":"ch_work_nvlt_81","text":"【賦】晉傅鹹芸香賦曰：携昵友以逍遙兮，覽伟草之敷英，慕君子之弘覆兮，超讬軀於朱庭，俯引泽於丹壤兮，仰吸润乎泰清，繁茲绿蕊，茂此翠茎，葉芟苁以纖折兮，枝婀娜以回萦，象春松之含曜兮，鬱蓊蔚以葱青。","sortOrder":228},
  {"id":"s_work_nvlt_81_229","chapterId":"ch_work_nvlt_81","text":"晉成公綏芸香賦曰：美芸香之循絜，禀陰陽之淑精，去原野之芜秽，植廣夏之前庭，茎類秋竹，葉象春柽。","sortOrder":229},
  {"id":"s_work_nvlt_81_230","chapterId":"ch_work_nvlt_81","text":"晉傅玄賦序曰：月令，仲春之月，芸始生，鄭玄雲，香草也，世人种之中庭。","sortOrder":230},
  {"id":"s_work_nvlt_81_231","chapterId":"ch_work_nvlt_81","text":"◇藿香","sortOrder":231},
  {"id":"s_work_nvlt_81_232","chapterId":"ch_work_nvlt_81","text":"《南州異物志》曰：藿香出海邊國，形如都梁，可著衣服中。","sortOrder":232},
  {"id":"s_work_nvlt_81_233","chapterId":"ch_work_nvlt_81","text":"吳時《外國傳》曰：都崑在扶南南三千餘里，出藿香。","sortOrder":233},
  {"id":"s_work_nvlt_81_234","chapterId":"ch_work_nvlt_81","text":"劉欣期《交州記》曰：藿香似蘇。","sortOrder":234},
  {"id":"s_work_nvlt_81_235","chapterId":"ch_work_nvlt_81","text":"【頌】梁江淹藿香頌曰：桂以過烈，麝以太芬，摧沮天寿，夭抑人文，誰及藿草，微馥微薰，攝靈百仞，養氣青雲。","sortOrder":235},
  {"id":"s_work_nvlt_81_236","chapterId":"ch_work_nvlt_81","text":"◇鹿葱","sortOrder":236},
  {"id":"s_work_nvlt_81_237","chapterId":"ch_work_nvlt_81","text":"《風土記》曰：宜男，草也，高六七尺，花如莲，宜懷妊婦人佩之，必生男。","sortOrder":237},
  {"id":"s_work_nvlt_81_238","chapterId":"ch_work_nvlt_81","text":"【詩】梁元帝詠宜男草詩曰：可愛宜男草，垂采暎倡家，何時如此葉，結實复含花。","sortOrder":238},
  {"id":"s_work_nvlt_81_239","chapterId":"ch_work_nvlt_81","text":"梁沈約詠鹿葱詩曰：野馬不任騎，菟絲不任織，既非中野華，無堪麕食。","sortOrder":239},
  {"id":"s_work_nvlt_81_240","chapterId":"ch_work_nvlt_81","text":"嵇含賦序曰：宜男多植幽皋曲隰，或寄華林玄圃，荆楚之士，號曰鹿葱。","sortOrder":240},
  {"id":"s_work_nvlt_81_241","chapterId":"ch_work_nvlt_81","text":"【賦】晉傅玄宜男花賦曰：猗猗令草，生於中方，花白宜男，號應禎祥，遠而望之，煥若三辰之麗天，近而察之，晃若芙蓉之鑒泉，於是狡童媛女，以時來征，結九秋之永思，含春風以娱情。","sortOrder":241},
  {"id":"s_work_nvlt_81_242","chapterId":"ch_work_nvlt_81","text":"晉夏侯湛宜男花賦曰：淑大邦之奇草兮，應則百之休祥，禀至真之靈氣兮，顯嘉名以自彰，冠眾卉而挺生兮，承木德於少陽，體柔性刚，蕙絜蘭芳，結纖根以立本兮，靈渥液於清雲，順陰陽以滋茂兮，笑含章之有文，遠而望之，灼若丹霞照青天，近而觀之，煒若芙蓉鑒渌泉，萋萋翠葉，灼灼朱華，晔若珠玉之树，煥如景宿之羅，充後妃之盛飾兮，登紫微之內庭，回日月之辉光兮，隨天運以虛盈。","sortOrder":242},
  {"id":"s_work_nvlt_81_243","chapterId":"ch_work_nvlt_81","text":"【頌】魏陳思王曹植宜男花頌曰：草號宜男，既晔且貞，厥貞伊何，惟乾之嘉，其晔伊何，绿葉丹花，光采晃曜，配彼朝日，君子躭樂，好和琴瑟，固作螽斯，微立孔臧，福齊大姒，永世克昌。","sortOrder":243},
  {"id":"s_work_nvlt_81_244","chapterId":"ch_work_nvlt_81","text":"◇蜀葵","sortOrder":244},
  {"id":"s_work_nvlt_81_245","chapterId":"ch_work_nvlt_81","text":"《爾雅》曰：菺，戎葵，［今蜀葵也，如木槿花。］","sortOrder":245},
  {"id":"s_work_nvlt_81_246","chapterId":"ch_work_nvlt_81","text":"晉傅玄蜀葵賦序曰：其苗似瓜瓠，既大而絜鮮，紫色曜日。","sortOrder":246},
  {"id":"s_work_nvlt_81_247","chapterId":"ch_work_nvlt_81","text":"【賦】虞繁蜀葵賦曰：惟茲珍草，懷芬吐榮，挺河渭之膏壤，吸昴井之玄精，繞銅爵而疏植，暎崑明而羅生，作妙觀於神州，扇令名於東京，馳驿命而遠致，攒華林而麗庭，申脩翘之冉冉，播員葉之青青。","sortOrder":247},
  {"id":"s_work_nvlt_81_248","chapterId":"ch_work_nvlt_81","text":"梁王筠蜀葵花賦曰：惟此奇草，遷花西道，凌金坂之威夷，跨玉津之浩浩，值油雲之廣臨，屬光風之長扫，仰椒屋而敷榮，植蘭房而舒藻，邁眾芳而秀出，冠雜卉而當闈，既扶疏而雲蔓，亦灼烁而星微，布護交加，蓊茸紛葩，疏茎密葉，翠萼丹華。","sortOrder":248},
  {"id":"s_work_nvlt_81_249","chapterId":"ch_work_nvlt_81","text":"【贊】宋顏延之蜀葵贊曰：井維降精，崏絡升靈，物微氣麗，夫草之英，渝艳眾蒍，冠冕群榮，類麻能直，方葵不傾。","sortOrder":249},
  {"id":"s_work_nvlt_81_250","chapterId":"ch_work_nvlt_81","text":"◇薔薇","sortOrder":250},
  {"id":"s_work_nvlt_81_251","chapterId":"ch_work_nvlt_81","text":"《本草經》曰：薔薇一名牛棘。","sortOrder":251},
  {"id":"s_work_nvlt_81_252","chapterId":"ch_work_nvlt_81","text":"又曰：一名牛勒，一名山棗，一名薔蘼。","sortOrder":252},
  {"id":"s_work_nvlt_81_253","chapterId":"ch_work_nvlt_81","text":"葛洪治金創方曰：用薔薇炭末一方寸匕，日三服之。","sortOrder":253},
  {"id":"s_work_nvlt_81_254","chapterId":"ch_work_nvlt_81","text":"【詩】齊謝朓詠薔薇詩曰：低枝詎勝葉，輕香幸自通，發萼初攒紫，餘采尚霏紅，新花對白日，故蕊逐行風。","sortOrder":254},
  {"id":"s_work_nvlt_81_255","chapterId":"ch_work_nvlt_81","text":"梁簡文帝詠薔薇詩曰：燕來枝益软，風飄花轉光，氛氲不肯去，還來階上香。","sortOrder":255},
  {"id":"s_work_nvlt_81_256","chapterId":"ch_work_nvlt_81","text":"又賦得詠薔薇詩曰：石榴珊瑚蕊，木槿懸星葩，豈如茲草麗，逢春始發花，回風舒紫萼，照日吐新芽。","sortOrder":256},
  {"id":"s_work_nvlt_81_257","chapterId":"ch_work_nvlt_81","text":"梁元帝看摘薔薇詩曰：倡女卷春裾，迎風戲玉除，近丛看影密，隔树望釵疏。橫枝斜綰袖，嫩葉下牵裾，牆高攀不及，花新摘未舒，莫疑插鬢少，分人猶有餘。","sortOrder":257},
  {"id":"s_work_nvlt_81_258","chapterId":"ch_work_nvlt_81","text":"梁劉缓看美人摘薔薇花詩曰：新花臨曲池，佳麗复相隨，鮮紅同暎水，輕香共逐吹，繞架尋多處，窥丛見好枝，今新猶恨少，將故复嫌萎，釵邊烂熳插，無處不相宜。","sortOrder":258},
  {"id":"s_work_nvlt_81_259","chapterId":"ch_work_nvlt_81","text":"梁鮑泉詠薔薇詩曰：經植宜春馆，靃靡上蘭宮，片舒猶帶紫，半卷未全紅，葉疏難蔽日，花密易傷風，佳麗新妆罢，含笑折芳丛。","sortOrder":259},
  {"id":"s_work_nvlt_81_260","chapterId":"ch_work_nvlt_81","text":"梁柳惲詠薔薇詩曰：當戶种薔薇，枝葉太葳蕤，不搖香已亂，無風花自飛，春閨不能靜，开匣理明妃，曲池浮采采，斜岸列依依，或聞好音度，時見衔泥歸，且對清酤湛，其餘任是非。","sortOrder":260},
  {"id":"s_work_nvlt_81_262","chapterId":"ch_work_nvlt_81","text":"《禮記月令》曰：仲夏之月，令民無刈藍以染。［為陽長也。］","sortOrder":262},
  {"id":"s_work_nvlt_81_263","chapterId":"ch_work_nvlt_81","text":"《毛詩》曰：終朝采藍，不盈一襜。","sortOrder":263},
  {"id":"s_work_nvlt_81_264","chapterId":"ch_work_nvlt_81","text":"《孫卿子》曰：青出於藍而青於藍。","sortOrder":264},
  {"id":"s_work_nvlt_81_265","chapterId":"ch_work_nvlt_81","text":"《續漢書》曰：楊震种植藍以供養母，諸生嘗有助种藍者，辄拔更种，以距其後。","sortOrder":265},
  {"id":"s_work_nvlt_81_266","chapterId":"ch_work_nvlt_81","text":"秦子曰：常問作人當如園圃之藍，不異眾草，染而後朗，然不如唐棣之華，灼灼自顯。","sortOrder":266},
  {"id":"s_work_nvlt_81_267","chapterId":"ch_work_nvlt_81","text":"【賦】後漢趙岐藍賦曰：餘就医偃師，道經陳留，此境人皆以种藍染绀為業，藍田弥望，黍稷不植，慨其遺本念末，遂作賦曰：同丘中之有麻，似麥秀之油油。","sortOrder":267},
  {"id":"s_work_nvlt_81_268","chapterId":"ch_work_nvlt_81","text":"◇慎火","sortOrder":268},
  {"id":"s_work_nvlt_81_269","chapterId":"ch_work_nvlt_81","text":"《南越志》曰：廣州有树，可以御火，山北謂之慎火，或謂戒火，多种屋上，以防火也，但南中無霜雪，故成树。","sortOrder":269},
  {"id":"s_work_nvlt_81_270","chapterId":"ch_work_nvlt_81","text":"【詩】梁范筠詠慎火詩曰：茲卉信丛丛，微榮未足奇，何期糅香草，遂得繞花池，忘忧雖無用，止焰或有施，早得建章立，幸爇柏梁垂。","sortOrder":270},
  {"id":"s_work_nvlt_81_271","chapterId":"ch_work_nvlt_81","text":"◇卷施","sortOrder":271},
  {"id":"s_work_nvlt_81_272","chapterId":"ch_work_nvlt_81","text":"《爾雅》曰：卷施草，拔心不死，［宿莽草也。］","sortOrder":272},
  {"id":"s_work_nvlt_81_273","chapterId":"ch_work_nvlt_81","text":"《離骚》曰：多［離骚作夕。］攬華洲之宿莽。","sortOrder":273},
  {"id":"s_work_nvlt_81_274","chapterId":"ch_work_nvlt_81","text":"《南越志》曰：寧乡縣草多卷施，拔心不死，江淮間謂之宿莽。","sortOrder":274},
  {"id":"s_work_nvlt_81_275","chapterId":"ch_work_nvlt_81","text":"【贊】晉郭璞卷施贊曰：卷施之草，拔心不死，屈平嘉之，諷詠以比，取類雖邇，興有遠旨。","sortOrder":275},
  {"id":"s_work_nvlt_81_276","chapterId":"ch_work_nvlt_81","text":"《藝文類聚》　唐·欧陽詢","sortOrder":276},
  {"id":"s_work_nvlt_82_1","chapterId":"ch_work_nvlt_82","text":"卷八十二草部下","sortOrder":1},
  {"id":"s_work_nvlt_82_2","chapterId":"ch_work_nvlt_82","text":"○芙蕖菱蒲萍苔菰荻蓍茗茅蓬艾藤菜蔬葵荠葱蓼","sortOrder":2},
  {"id":"s_work_nvlt_82_3","chapterId":"ch_work_nvlt_82","text":"◇芙蕖","sortOrder":3},
  {"id":"s_work_nvlt_82_4","chapterId":"ch_work_nvlt_82","text":"《爾雅》曰：荷，芙蕖，其茎茄，其葉葭，其本蔤，其花菡萏，其實莲，其根藕，其中的，［的，子也。］的中薏，［子中心也。］的莲實。","sortOrder":4},
  {"id":"s_work_nvlt_82_5","chapterId":"ch_work_nvlt_82","text":"《廣雅》曰：菡萏，芙蓉也。","sortOrder":5},
  {"id":"s_work_nvlt_82_6","chapterId":"ch_work_nvlt_82","text":"《周書》曰：藪泽已竭，即莲藕掘。","sortOrder":6},
  {"id":"s_work_nvlt_82_7","chapterId":"ch_work_nvlt_82","text":"《毛詩》曰：彼泽之陂，有蒲與荷。","sortOrder":7},
  {"id":"s_work_nvlt_82_8","chapterId":"ch_work_nvlt_82","text":"又曰：隰有荷花。","sortOrder":8},
  {"id":"s_work_nvlt_82_9","chapterId":"ch_work_nvlt_82","text":"《說文》曰：芰，菱也。","sortOrder":9},
  {"id":"s_work_nvlt_82_10","chapterId":"ch_work_nvlt_82","text":"《管子》曰：五沃之土生莲。","sortOrder":10},
  {"id":"s_work_nvlt_82_11","chapterId":"ch_work_nvlt_82","text":"真人關令尹喜傳曰：真人遊時，各各坐莲花之上，一花辄径十丈。","sortOrder":11},
  {"id":"s_work_nvlt_82_12","chapterId":"ch_work_nvlt_82","text":"《楚辭》曰：集芙蓉以為裳。","sortOrder":12},
  {"id":"s_work_nvlt_82_13","chapterId":"ch_work_nvlt_82","text":"又曰：因芙蓉而為媒，憚褰衣而濡足。","sortOrder":13},
  {"id":"s_work_nvlt_82_14","chapterId":"ch_work_nvlt_82","text":"又曰：搴芙蓉兮木末。","sortOrder":14},
  {"id":"s_work_nvlt_82_15","chapterId":"ch_work_nvlt_82","text":"又曰：披荷稠之炅炅。","sortOrder":15},
  {"id":"s_work_nvlt_82_16","chapterId":"ch_work_nvlt_82","text":"又曰：製芰荷以為衣。","sortOrder":16},
  {"id":"s_work_nvlt_82_17","chapterId":"ch_work_nvlt_82","text":"又曰：荷衣兮蕙帶。","sortOrder":17},
  {"id":"s_work_nvlt_82_18","chapterId":"ch_work_nvlt_82","text":"又曰：芙蓉始發雜芰荷，紫茎屏風文绿波。","sortOrder":18},
  {"id":"s_work_nvlt_82_19","chapterId":"ch_work_nvlt_82","text":"洛神賦，灼若芙蓉出绿波。","sortOrder":19},
  {"id":"s_work_nvlt_82_20","chapterId":"ch_work_nvlt_82","text":"《文選》：芙蓉散其華。","sortOrder":20},
  {"id":"s_work_nvlt_82_21","chapterId":"ch_work_nvlt_82","text":"又曰：神飆自遠至，左右芙蓉披。","sortOrder":21},
  {"id":"s_work_nvlt_82_22","chapterId":"ch_work_nvlt_82","text":"又曰：菡萏溢金塘。","sortOrder":22},
  {"id":"s_work_nvlt_82_23","chapterId":"ch_work_nvlt_82","text":"又曰：魚戲新荷動。","sortOrder":23},
  {"id":"s_work_nvlt_82_24","chapterId":"ch_work_nvlt_82","text":"又曰：神蔡止荷心。","sortOrder":24},
  {"id":"s_work_nvlt_82_25","chapterId":"ch_work_nvlt_82","text":"《毛詩義疏》曰：的可磨以為散，輕身益氣，令人強健。","sortOrder":25},
  {"id":"s_work_nvlt_82_26","chapterId":"ch_work_nvlt_82","text":"《拾遺記》曰：漢昭帝遊柳池，有芙蓉，紫色，大如斗，花素葉甘，可食，芬氣聞車之內，莲實如珠，宋起居註曰：泰始二年，嘉莲一双，骈花併實，合树同茎。","sortOrder":26},
  {"id":"s_work_nvlt_82_27","chapterId":"ch_work_nvlt_82","text":"《宋書》曰：臧质，字文含，［宋書七十四臧质傳作含文。］兵败，走入南湖，無食，啖莲，追至，质絡頸沈，出鼻，兵見，斬首傳京。","sortOrder":27},
  {"id":"s_work_nvlt_82_28","chapterId":"ch_work_nvlt_82","text":"《搜神記》曰：王敦在武昌，鈴下儀仗生莲花，五六日而落。","sortOrder":28},
  {"id":"s_work_nvlt_82_29","chapterId":"ch_work_nvlt_82","text":"又曰：無錫上湖陂，陂吏丁初，雨止，見一少婦人，著青衣，戴伞，呼之不得，自投陂中，是大蒼獭，衣伞皆是荷花。","sortOrder":29},
  {"id":"s_work_nvlt_82_30","chapterId":"ch_work_nvlt_82","text":"《萬歲歷》曰：太和二年，乌程縣閤下生莲花。","sortOrder":30},
  {"id":"s_work_nvlt_82_31","chapterId":"ch_work_nvlt_82","text":"顧啟期《娄地記》曰：娄門東南有華墩，陂中生千葉莲花，其荷與眾莲荷無異，菡萏色白，豈佛經所載者也。","sortOrder":31},
  {"id":"s_work_nvlt_82_32","chapterId":"ch_work_nvlt_82","text":"王歆之《神境記》曰：九疑山過半路，皆行竹松下狹路，有清涧，涧中有黃色莲花，芳氣竟穀。","sortOrder":32},
  {"id":"s_work_nvlt_82_33","chapterId":"ch_work_nvlt_82","text":"《浮圖澄傳》曰：澄咒鉢中青莲花生。","sortOrder":33},
  {"id":"s_work_nvlt_82_34","chapterId":"ch_work_nvlt_82","text":"《古今註》曰：一名水且，一名水芝，一名泽芝，一名水花。","sortOrder":34},
  {"id":"s_work_nvlt_82_35","chapterId":"ch_work_nvlt_82","text":"《華山記》曰：山顶有池，池中生千葉莲花，服之羽化，因名華山。","sortOrder":35},
  {"id":"s_work_nvlt_82_36","chapterId":"ch_work_nvlt_82","text":"【詩】江南可采莲，荷葉何田田，魚戲荷葉東，魚戲荷葉西，魚戲荷葉南，魚戲荷葉北。","sortOrder":36},
  {"id":"s_work_nvlt_82_37","chapterId":"ch_work_nvlt_82","text":"古詩曰：涉江采芙蓉，蘭泽多芳草，采之欲遺誰，所思在遠道。","sortOrder":37},
  {"id":"s_work_nvlt_82_38","chapterId":"ch_work_nvlt_82","text":"晉傅玄歌詩曰：度江南，采莲花，芙蓉增敷，晔若星羅，绿葉映長波，回風容與動纖柯。","sortOrder":38},
  {"id":"s_work_nvlt_82_39","chapterId":"ch_work_nvlt_82","text":"又曰：煌煌芙蕖，從風芬葩，照以皎日，灌以清波，陰結其實，陽發其花，金房绿葉，素株翠柯。","sortOrder":39},
  {"id":"s_work_nvlt_82_40","chapterId":"ch_work_nvlt_82","text":"晉陆筠芙蕖詩曰：绿房含青實，金條懸白璆，俯仰隨風傾，煒燁照清流。","sortOrder":40},
  {"id":"s_work_nvlt_82_41","chapterId":"ch_work_nvlt_82","text":"晉張華荷詩曰：荷生绿泉中，碧葉齊如規，回風荡流霧，珠水逐條垂，照灼此金塘，藻曜君玉池，不愁世賞絕，但畏盛明移。","sortOrder":41},
  {"id":"s_work_nvlt_82_42","chapterId":"ch_work_nvlt_82","text":"梁簡文帝詠芙蓉詩曰：圓花一蒂卷，交葉半心开，影前光照曜，香里蝶徘徊，欣隨玉露點，不逐秋風摧。","sortOrder":42},
  {"id":"s_work_nvlt_82_43","chapterId":"ch_work_nvlt_82","text":"又采莲詩曰：晚日照空磯，采莲承晚暉，風起湖難度，莲多摘未稀，棹動芙蓉落，船移白鷺飛，荷絲傍繞腕，菱角遠牵衣。","sortOrder":43},
  {"id":"s_work_nvlt_82_44","chapterId":"ch_work_nvlt_82","text":"梁朱超詠同心芙蓉詩曰：青山麗朝景，玄峰朗夜光，未及清池上，紅蕖併出房，日分双帶影，風合兩花香，魚驚畏莲折，龟上礙荷長，雲雨留輕润，草木應嘉祥，徒歌涉江曲，誰見緝為裳。","sortOrder":44},
  {"id":"s_work_nvlt_82_45","chapterId":"ch_work_nvlt_82","text":"梁劉缓詠江南可采莲詩曰：春初北岸涸，夏月南湖通，卷荷舒欲倚，芙蓉生即紅，楫小宜回迳，船輕好入丛，釵光逐影亂，衣香隨逆風，江南少許地，年年情不窮。","sortOrder":45},
  {"id":"s_work_nvlt_82_46","chapterId":"ch_work_nvlt_82","text":"梁劉孝威和采莲詩曰：金锵木蘭船，戲采江南莲，莲香隔浦渡，荷葉［原訛芙，據冯校本改。］滿江鮮，房垂易入手，柄曲自臨盤，露花時濕钏，風茎乍拂钿。","sortOrder":46},
  {"id":"s_work_nvlt_82_47","chapterId":"ch_work_nvlt_82","text":"梁吳筠采莲詩曰：錦帶雜花钿，羅衣垂绿川，問子今何去，出采江南莲，遼西三千里，欲寄無因緣，原君早旋反，及此荷花鮮。","sortOrder":47},
  {"id":"s_work_nvlt_82_48","chapterId":"ch_work_nvlt_82","text":"梁沈約詠芙蓉詩曰：微風搖紫□，輕露拂朱房，中池所以绿，待我汎紅光。","sortOrder":48},
  {"id":"s_work_nvlt_82_49","chapterId":"ch_work_nvlt_82","text":"又詠新荷應詔曰：勿言草卉賤，幸宅天地中，微根才出浪，短幹未搖風，寧知寸心里，蓄紫复含紅。","sortOrder":49},
  {"id":"s_work_nvlt_82_50","chapterId":"ch_work_nvlt_82","text":"梁江洪詠荷詩曰：泽陂有微草，能花复能實，碧葉憙翻風，紅英宜照日，移居玉池上，讬根庶非失，如何霜露交，應與飛蓬匹。","sortOrder":50},
  {"id":"s_work_nvlt_82_51","chapterId":"ch_work_nvlt_82","text":"陳祖孫登詠城巉中荷詩曰：白水麗金肩，青荷承日暉，葉似〈王還〉城蓋，香亂上桥衣，岸高知水落，影合見菱稀，猶疑涉江處，空望采莲歸。","sortOrder":51},
  {"id":"s_work_nvlt_82_52","chapterId":"ch_work_nvlt_82","text":"又賦得涉江采芙蓉詩曰：浮照滿川涨，芙蓉承落光，人來間花影，衣渡得荷香，桂舟輕不定，菱歌引更長，埰采嗟離別，無暇緝為裳。","sortOrder":52},
  {"id":"s_work_nvlt_82_53","chapterId":"ch_work_nvlt_82","text":"隨殷英童詠采莲詩曰：荡舟無數伴，解纜自相催，汗粉無佣拭，風裙［原字坏，據冯校本補。］隨意开，棹移浮荇亂，船進倚荷來，藕絲牵作縷，莲葉捧成杯。","sortOrder":53},
  {"id":"s_work_nvlt_82_54","chapterId":"ch_work_nvlt_82","text":"【賦】後漢闵鸿芙蓉賦曰：乃有芙蓉靈草，載育中川，竦脩幹以陵波，建绿葉之規圓，灼若夜光之在玄岫，赤若太陽之映朝雲，乃有陽文脩嫮，傾城之色，楊桂枻而來遊，玩英華乎水侧，納嘉實兮傾筐，珥紅葩以為飾，盛桃夭而歌詩，申關雎以自敕，嗟留夷與蘭芷，聽鶗窸而不鳴，嘉芙蓉之殊伟，讬皇居以發英。","sortOrder":54},
  {"id":"s_work_nvlt_82_55","chapterId":"ch_work_nvlt_82","text":"魏陳王曹植芙蓉賦曰：覽百卉之英茂，無斯華之獨靈，結脩根於重壤，泛清流以擢茎，其始榮也，皎若夜光尋扶桑，其扬暉也，晃若九陽出暘穀，芙蓉蹇產，菡萏星屬，絲條垂珠，丹榮加绿，焜焜韡韡，烂若龍燭，觀者終朝，情猶未足，於是狡童媛女，相與同遊，擢素手於羅袖，接紅葩於中流。","sortOrder":55},
  {"id":"s_work_nvlt_82_56","chapterId":"ch_work_nvlt_82","text":"吳蘇彦芙蕖賦曰：伟芙蓉之菡萏，耀煒燁之丹花，舒紅采於绿沼，映的皪於朱霞。","sortOrder":56},
  {"id":"s_work_nvlt_82_57","chapterId":"ch_work_nvlt_82","text":"晉孫楚莲花賦曰：有自然之麗草，育靈沼之清瀨，結根低於重壤，森蔓延以騰邁，爾乃紅花電發，暉光燁燁，仰曜朝霞，俯照绿水，潛緗房之奧密兮，含珍藕之甘腴，攒聚星列，纖離相扶。","sortOrder":57},
  {"id":"s_work_nvlt_82_58","chapterId":"ch_work_nvlt_82","text":"晉潘嶽莲花賦曰：伟玄泽之普衍，嘉植物之併敷，遊莫美於春台，華莫盛於芙蕖，於是惠風動，冲氣和，眄清池，玩莲花，舒绿葉，挺纖柯，結绿房，列紅葩，仰含清液，俯濯素波，脩柯婀娜，柔茎苒弱，流風徐轉，回波微激，其望之也，晔若皦日燭崑山，其節之也，晃若盈尺映藍田。","sortOrder":58},
  {"id":"s_work_nvlt_82_59","chapterId":"ch_work_nvlt_82","text":"晉夏侯湛芙蓉賦曰：臨清池以遊覽，觀芙蓉之麗華，潛靈藕於玄泉，擢脩茎乎清波，煥然荫沼，灼爾星羅，若乃回萦外散，菡萏內離，的出艳發，葉恢花披，绿房翠蒂，紫飾紅敷，黃螺圓出，垂蕤散舒，纓以金牙，點以素珠，固陂池之麗觀，尊終世之特殊，爾乃采淳葩，摘圓质，析碧皮，食素實，味甘滋而清美，同嘉異乎橙橘，參嘉果以作珍，長充御乎口實。","sortOrder":59},
  {"id":"s_work_nvlt_82_60","chapterId":"ch_work_nvlt_82","text":"晉潘嶽芙蓉賦曰：荫蘭池之丰沼，育沃野之上腴，課眾榮而比觀，煥卓荦而獨殊，狎獦雲布，窋咤星羅，光擬燭龍，色奪朝霞，丹煇拂紅，飛鬢垂的，斐披赩赫，散煥熠爚，流芬賦采，風靡雲旋，布濩磊落，蔓衍夭閒，發清陽而增媚，润白玉而加鮮。","sortOrder":60},
  {"id":"s_work_nvlt_82_61","chapterId":"ch_work_nvlt_82","text":"宋傅亮芙蓉賦曰：考庶卉之珍麗，寔總美於芙蕖，潛幽泉以育藕，披翠莲而挺敷，汎輕荷以冒沼，列紅葩而曜除，徼旭露以滋采，靡朝風而肆芳，表麗觀於中沚，播鬱烈於蘭堂，在龍見而萌秀，於火中而結房，豈呈芬於芷蕙，將越味於沙棠，詠三闾之披服，美蘭佩而荷裳，伊玄匠之有瞻，悅嘉卉於中渠，既暉映於丹墀，亦納芳於綺疏。","sortOrder":61},
  {"id":"s_work_nvlt_82_62","chapterId":"ch_work_nvlt_82","text":"宋鮑昭芙蓉賦曰：感衣裳於楚賦，詠夏思於陳詩，訪群英之艳絕，摽高名於泽芝，青房兮規接，紫的兮圖羅，树妖遙之弱幹，散菡萏之輕柯，上星光而倒景，下龍鱗而隱波，戲錦鱗而夕映，濯繡羽而景過，結遊童之湘吹，起艕妾之□［○本集作吳。］歌，被碧塘之周流，繞金渠之空曲，排積霧而楊芬，鏡洞泉而含绿，葉折水而為珠，條集露而成玉，润蓬山之琼膏，暉葱河之銀燭，冠五華於仙草，超四照於靈木。","sortOrder":62},
  {"id":"s_work_nvlt_82_63","chapterId":"ch_work_nvlt_82","text":"梁簡文帝采莲賦曰：望江南兮清且空，對荷華兮丹复紅，臥莲葉而覆水，亂高房而出丛，楚王暇日之歡，麗人妖艳之质，且弃垂釣之魚，未論芳苹之實，唯欲回渡輕船，共采新莲，傍斜山而屢轉，乘橫流而不前，於是素腕舉，紅袖長，回巧笑，墮明璫，荷稠刺密，亟牵衣而綰裳，人喧水溅，惜虧朱而坏妆，物色雖晚，徘徊未反，畏風多而榜危，驚舟移而花遠，歌曰：常聞蕖可愛，采撷欲為裙，葉滑不留綖，心忙無假薰，千春誰與樂，唯有妾隨君。","sortOrder":63},
  {"id":"s_work_nvlt_82_64","chapterId":"ch_work_nvlt_82","text":"梁元帝采莲賦曰：紫茎兮文波，紅莲兮芰荷，绿房兮翠蓋，素實兮黃螺，於時妖童媛女，荡舟心許，鹢首徐回，兼傳羽杯，棹將移而藻掛，船欲動而萍开，爾其纖腰束素，遷延顧步，夏始春餘，葉嫩花初，恐沾裳而淺笑，畏傾船而斂裾，故以水溅蘭桡，芦侵羅衤廌，菊泽未反，梧台迥見，荇濕霑衫，菱長繞钏，泛柏舟而容與，歌采莲於枉渚，歌曰：碧玉小家女，來嫁汝南王，莲花亂脸色，荷葉雜衣香，因持荐君子，原袭芙蓉裳。","sortOrder":64},
  {"id":"s_work_nvlt_82_65","chapterId":"ch_work_nvlt_82","text":"梁昭明太子芙蓉賦曰：色兼列采，體繁眾號，初榮夏芬，晚花秋曜，興泽陂之徽章，結江南之流調。","sortOrder":65},
  {"id":"s_work_nvlt_82_66","chapterId":"ch_work_nvlt_82","text":"梁江淹莲花賦曰：蕊金光而池色，藕冰折而玉清，戴紅莲以吐秀，披終華以舒英，故河北棹歌之姝，江南采菱之女，春水廣兮楫潺湲，秋風駃兮舟容與，看縹芰兮出波，攬緗莲兮映渚。","sortOrder":66},
  {"id":"s_work_nvlt_82_67","chapterId":"ch_work_nvlt_82","text":"【頌】顏延之碧芙蓉頌曰：泽芝芳艳，擅奇水屬，練氣紅荷，比符縹玉，棹麗沧池，飛映雲屋，實紀仙方，名書靈躅。","sortOrder":67},
  {"id":"s_work_nvlt_82_68","chapterId":"ch_work_nvlt_82","text":"【贊】晉郭璞芙蓉贊曰：芙蓉麗草，一曰泽芝，泛葉雲布，映波赮熙，伯陽是食，饗比靈期。","sortOrder":68},
  {"id":"s_work_nvlt_82_69","chapterId":"ch_work_nvlt_82","text":"【表】晉范寧為豫章郡守，新淦縣聽事前陆地，生一莲花，入冬花，十六年，更生四枚，今年复生二十六枚，鮮明可愛。","sortOrder":69},
  {"id":"s_work_nvlt_82_70","chapterId":"ch_work_nvlt_82","text":"【啟】劉表［按當作孝。］威謝東宮赉藕啟曰：色華玉树，味奪琼漿，根出楊池，聞之僮約，子為靈散，得自莊篇，楚後江萍，秦公海棗，凡厥水羞，莫敢相辈。","sortOrder":70},
  {"id":"s_work_nvlt_82_72","chapterId":"ch_work_nvlt_82","text":"《說文》曰：菱，{艹陵}也。","sortOrder":72},
  {"id":"s_work_nvlt_82_73","chapterId":"ch_work_nvlt_82","text":"《廣志》曰：鉅野大於常{艹陵}，淮漢以南，凶年以菱為蔬，猶以橡為資也。","sortOrder":73},
  {"id":"s_work_nvlt_82_74","chapterId":"ch_work_nvlt_82","text":"《周官》曰：冬食{艹陵}藕棗栗杼實。","sortOrder":74},
  {"id":"s_work_nvlt_82_75","chapterId":"ch_work_nvlt_82","text":"《國語》曰：屈到嗜芰，有疾，召其宗老而屬之曰：祭我必以芰，［屈到，楚卿也，宗老，家臣也，屬，讬也。］《楚辭》曰：製芰荷以為衣。","sortOrder":75},
  {"id":"s_work_nvlt_82_76","chapterId":"ch_work_nvlt_82","text":"《呂氏春秋》曰：杜厲叔事莒公，自以為不見知，居於海上，夏食菱芡，冬食橡栗，莒公有難，將死之，其友曰：不知故去，今往死之，是知與不知無別也，厲叔曰：吾將以丑後世人主不知其臣者也。","sortOrder":76},
  {"id":"s_work_nvlt_82_77","chapterId":"ch_work_nvlt_82","text":"《幽明錄》曰：東平呂球，丰财美貌，乘船至曲阿湖，值風不得行，泊菰际，見一少女，乘船采菱，舉體皆衣荷葉，因問姑非鬼耶，衣服何至如此，女則有懼色，答雲，子不聞荷衣兮蕙帶，倏而來兮忽而逝乎，然有懼容，回舟理棹，逡巡而去，球遙射之，即獲一獭，向者之船，皆是蘋蘩蕰藻之葉，見老母立岸侧，如有所候望，見船過，因問雲，君向來，不見湖中采菱女子耶，球雲近在後，尋射，复獲老獭，居湖次者，鹹雲，湖中常有采菱女，容色過人，有時至人家，結好者甚眾。","sortOrder":77},
  {"id":"s_work_nvlt_82_78","chapterId":"ch_work_nvlt_82","text":"【詩】梁簡文帝采菱詩曰：菱花落复含，桑女罢新蠶，桂棹浮星艇，徘徊莲葉南。","sortOrder":78},
  {"id":"s_work_nvlt_82_79","chapterId":"ch_work_nvlt_82","text":"梁費昶采菱詩曰：妾家五湖口，采菱五湖侧，玉面不關妆，双眉本翠色，日斜天欲暮，風生浪未息。","sortOrder":79},
  {"id":"s_work_nvlt_82_80","chapterId":"ch_work_nvlt_82","text":"梁江淹采菱詩曰：秋日心容與，涉水望碧莲，紫菱亦可采，试以缓愁年，參差萬葉下，泛漾百流前，高采溢通壑，香氛麗廣川，歌出棹女曲，舞入江南絃。","sortOrder":80},
  {"id":"s_work_nvlt_82_81","chapterId":"ch_work_nvlt_82","text":"梁陆罩采菱詩曰：參差雜荇枝，田田競荷密，轉葉任香風，舒花影流日，戲鳥波中荡，遊魚菱下出，不與文王嗜，羞持比萍實。","sortOrder":81},
  {"id":"s_work_nvlt_82_82","chapterId":"ch_work_nvlt_82","text":"梁江洪采菱詩曰：風生绿葉聚，波動紫茎开，含花复含實，正待佳人來。","sortOrder":82},
  {"id":"s_work_nvlt_82_83","chapterId":"ch_work_nvlt_82","text":"又曰：白日和清風，輕雲雜高树，忽然當此時，采菱复相遇。","sortOrder":83},
  {"id":"s_work_nvlt_82_84","chapterId":"ch_work_nvlt_82","text":"【啟】梁庾肩吾謝赉菱啟曰：上林紫水，雜蕰藻而俱浮，雲夢清池，間芙蓉而外發，珍逾百味，來荐晝盤，恩重千金，遂沾菲席，凌霜朱橘，愧此开顏，含露蒲桃，慚其不饣肙。","sortOrder":84},
  {"id":"s_work_nvlt_82_86","chapterId":"ch_work_nvlt_82","text":"《山海經》曰：孟於之山，其上多蒲。","sortOrder":86},
  {"id":"s_work_nvlt_82_87","chapterId":"ch_work_nvlt_82","text":"《爾雅》曰：莞，符離，其上蒚，［今水中莞蒲，可作席也。］","sortOrder":87},
  {"id":"s_work_nvlt_82_88","chapterId":"ch_work_nvlt_82","text":"《毛詩》曰：彼泽之陂，有蒲與菅。","sortOrder":88},
  {"id":"s_work_nvlt_82_89","chapterId":"ch_work_nvlt_82","text":"又曰：魚在在藻，依於其蒲。","sortOrder":89},
  {"id":"s_work_nvlt_82_90","chapterId":"ch_work_nvlt_82","text":"《左傳》曰：齊侯泽之雚蒲，舟鲛守之，不與民共。","sortOrder":90},
  {"id":"s_work_nvlt_82_91","chapterId":"ch_work_nvlt_82","text":"又曰：臧文仲妾織蒲。","sortOrder":91},
  {"id":"s_work_nvlt_82_92","chapterId":"ch_work_nvlt_82","text":"古歌曰：蒲葉何離離。","sortOrder":92},
  {"id":"s_work_nvlt_82_93","chapterId":"ch_work_nvlt_82","text":"《離骚》曰：抽蒲兮陳坐，援英兮為蓋。","sortOrder":93},
  {"id":"s_work_nvlt_82_94","chapterId":"ch_work_nvlt_82","text":"《文選》：新蒲含紫茸。","sortOrder":94},
  {"id":"s_work_nvlt_82_95","chapterId":"ch_work_nvlt_82","text":"又曰：新蒲節轉促。","sortOrder":95},
  {"id":"s_work_nvlt_82_96","chapterId":"ch_work_nvlt_82","text":"《史記》，［冯校本雲，史記不書獻蒲事，今見文選潘安仁西征賦野蒲变而為脯註。］趙高將為亂，先設验，獻蒲以為脯，惑二世，有言蒲者，誅之。","sortOrder":96},
  {"id":"s_work_nvlt_82_97","chapterId":"ch_work_nvlt_82","text":"《漢書》：路溫舒父為里監門，使溫舒牧羊，乃取泽中蒲，截以為牒，編用寫書。","sortOrder":97},
  {"id":"s_work_nvlt_82_98","chapterId":"ch_work_nvlt_82","text":"又曰：元帝疾，時史丹以親密侍疾，唯上獨寢，直入臥內，頓首伏青蒲上，［青，绿，蒲，席也。又以蒲青為席，鋪地也。］《東觀漢記》曰：劉宽遷南陽太守，溫仁多恕，吏民有過，但用蒲鞭罰之，示辱而已。","sortOrder":98},
  {"id":"s_work_nvlt_82_99","chapterId":"ch_work_nvlt_82","text":"《秦記》曰：符洪之先，居武都，家生蒲，長五丈，状如竹，鹹異之，謂之蒲家，因以氏焉，洪後以讖文草付應王，遂改姓苻［原訛符，據冯校本改。］氏。","sortOrder":99},
  {"id":"s_work_nvlt_82_100","chapterId":"ch_work_nvlt_82","text":"《續述征記》曰：乌常沉湖［齊人謂湖為沉。］中，有九十台，皆生結蒲，雲秦始皇遊此台，結蒲系馬，自此蒲生則結。","sortOrder":100},
  {"id":"s_work_nvlt_82_101","chapterId":"ch_work_nvlt_82","text":"《幽明錄》曰：河東常丑奴，將一小兒，湖邊拔蒲，暮恒宿空田舍中，時日向暝，見一少女子，姿容極美，乘小船，載莼，迳前投丑奴舍寄住，因臥，覺有臊氣，女已知人意，便求出戶，变為獭。","sortOrder":101},
  {"id":"s_work_nvlt_82_102","chapterId":"ch_work_nvlt_82","text":"【詩】古詩曰：青蒲绿蒂，生我池中。","sortOrder":102},
  {"id":"s_work_nvlt_82_103","chapterId":"ch_work_nvlt_82","text":"齊謝朓詠蒲詩曰：離離水上蒲，結水散為珠，初萌實雕俎，暮蕊雜椒涂，所嗟堂上曲，遂鑠黃金軀。","sortOrder":103},
  {"id":"s_work_nvlt_82_104","chapterId":"ch_work_nvlt_82","text":"梁元帝賦得蒲生我池中詩曰：池中种蒲葉，葉影荫池濱，未好中宮荐，行堪隱士輪，為書聊可截，匹柳复宜春，瑞葉生符苑，鏤璧獻周人。","sortOrder":104},
  {"id":"s_work_nvlt_82_106","chapterId":"ch_work_nvlt_82","text":"《爾雅》曰：苹，萍也，其大者曰蘋。","sortOrder":106},
  {"id":"s_work_nvlt_82_107","chapterId":"ch_work_nvlt_82","text":"《周禮》曰：穀雨一日，萍始生，萍不生，陰氣增盈。","sortOrder":107},
  {"id":"s_work_nvlt_82_108","chapterId":"ch_work_nvlt_82","text":"《秋官》曰：萍氏，掌禁川遊者，萍草無根，取名不沈溺。","sortOrder":108},
  {"id":"s_work_nvlt_82_109","chapterId":"ch_work_nvlt_82","text":"《異術》曰：萬年血為萍。","sortOrder":109},
  {"id":"s_work_nvlt_82_110","chapterId":"ch_work_nvlt_82","text":"古詩曰：泛泛江漢萍，漂荡水無根。","sortOrder":110},
  {"id":"s_work_nvlt_82_111","chapterId":"ch_work_nvlt_82","text":"《江賦》曰：萍實時出而漂泳。","sortOrder":111},
  {"id":"s_work_nvlt_82_112","chapterId":"ch_work_nvlt_82","text":"《東都賦》：發蘋藻潛魚。","sortOrder":112},
  {"id":"s_work_nvlt_82_113","chapterId":"ch_work_nvlt_82","text":"《風賦》：起青蘋之末。","sortOrder":113},
  {"id":"s_work_nvlt_82_114","chapterId":"ch_work_nvlt_82","text":"何晏詩曰：原為绿蘋草，讬身寄清池。","sortOrder":114},
  {"id":"s_work_nvlt_82_115","chapterId":"ch_work_nvlt_82","text":"劉靈曰：俯觀萬物，扰扰焉如水之載浮萍。","sortOrder":115},
  {"id":"s_work_nvlt_82_116","chapterId":"ch_work_nvlt_82","text":"王逸曰：自比如萍，隨水浮遊。","sortOrder":116},
  {"id":"s_work_nvlt_82_117","chapterId":"ch_work_nvlt_82","text":"《本草經》曰：水萍一名水華，味辛寒，治暴熱，身痒下水，乌鬢發，久服輕身，一名水帘。","sortOrder":117},
  {"id":"s_work_nvlt_82_118","chapterId":"ch_work_nvlt_82","text":"《毛詩》曰：於以采蘋，南涧之濱。","sortOrder":118},
  {"id":"s_work_nvlt_82_119","chapterId":"ch_work_nvlt_82","text":"《禮記月令》曰：季春之月，萍始生。","sortOrder":119},
  {"id":"s_work_nvlt_82_120","chapterId":"ch_work_nvlt_82","text":"《呂氏春秋》曰：菜之美者，崑崙之蘋。","sortOrder":120},
  {"id":"s_work_nvlt_82_121","chapterId":"ch_work_nvlt_82","text":"《家語》曰：楚昭王渡江，江中有物，大如斗，圓而赤，直觸王舟，舟人取之，問群臣，莫能識之，使問孔子，孔子曰：此謂萍實，可剖而食之，吉祥也，唯霸者能獲焉，王遂食，大美。又遣問孔子，何以知之，子曰：吾昔過陳，聞童謠曰：楚王渡江得萍實，大如斗，赤如日，剖而食之甜如蜜，吾是以知之。","sortOrder":121},
  {"id":"s_work_nvlt_82_122","chapterId":"ch_work_nvlt_82","text":"《淮南子》曰：夫萍树根於水，木树根於土。","sortOrder":122},
  {"id":"s_work_nvlt_82_123","chapterId":"ch_work_nvlt_82","text":"【詩】晉司馬彪萍詩曰：汎汎江漢萍，飄荡永無根。","sortOrder":123},
  {"id":"s_work_nvlt_82_124","chapterId":"ch_work_nvlt_82","text":"梁庾肩吾賦得池萍詩曰：風翻乍青紫，浪起時疏密，本欲叹無根，還驚能有實。","sortOrder":124},
  {"id":"s_work_nvlt_82_125","chapterId":"ch_work_nvlt_82","text":"【賦】晉夏侯湛浮萍賦曰：步長渠以遊目，覽隨波之微草，既紛潎以澄茂，羌孤生於靈沼，罔纖根以自滋，乃逸荡乎波表，散圓葉以舒形，發翠采以含縹，荫脩魚之華鱗，翳蘭池之清潦，既澹淡以順流。又雍容以隨風，有纏薄於崖侧，或回滯乎湍中，紛上下而靡常，漂往來其無窮，停不安處，行無定軌，流息則寧，涛扰則動，浮輕善移，势危易荡。","sortOrder":125},
  {"id":"s_work_nvlt_82_126","chapterId":"ch_work_nvlt_82","text":"晉蘇彦浮萍賦曰：餘嘗汎舟遊觀，鼓楫川湖，睹浮萍之飄浪，乃觸水而自居，體任適以應會，亦隨遇而靡構，伊弱卉之無心，合至理之冥符。","sortOrder":126},
  {"id":"s_work_nvlt_82_127","chapterId":"ch_work_nvlt_82","text":"【贊】郭璞萍贊曰：萍之在水，猶卉植地，靡見其布，漠爾鱗被，物無常讬，孰知所寄。","sortOrder":127},
  {"id":"s_work_nvlt_82_128","chapterId":"ch_work_nvlt_82","text":"【論】晉杜恕篤論曰：夫萍與菱之浮，相似也，菱植根，萍隨波，是以尧舜叹巧言亂德，仲尼惡紫之奪朱。","sortOrder":128},
  {"id":"s_work_nvlt_82_130","chapterId":"ch_work_nvlt_82","text":"《爾雅》曰：藫，石衣也。","sortOrder":130},
  {"id":"s_work_nvlt_82_131","chapterId":"ch_work_nvlt_82","text":"《說文》曰：苔，水衣也。","sortOrder":131},
  {"id":"s_work_nvlt_82_132","chapterId":"ch_work_nvlt_82","text":"《淮南子》曰：窮穀之污，生青苔。","sortOrder":132},
  {"id":"s_work_nvlt_82_133","chapterId":"ch_work_nvlt_82","text":"《風土記》曰：石發，水衣也，青绿色，皆生於石。","sortOrder":133},
  {"id":"s_work_nvlt_82_134","chapterId":"ch_work_nvlt_82","text":"遊名山志曰：石篢［《太平御覽》一千作箦，按據御覽四十七引贺循會稽記，當作簣。］山，緣崖而上，高百許丈，里悉青苔，無別草木。","sortOrder":134},
  {"id":"s_work_nvlt_82_135","chapterId":"ch_work_nvlt_82","text":"《古今註》：苔或紫或青，一名員藓，一名绿錢，一名绿藓。","sortOrder":135},
  {"id":"s_work_nvlt_82_136","chapterId":"ch_work_nvlt_82","text":"《拾遺記》曰：晉武帝時，租梨園［《太平御覽》一千作祖梨國。］獻蔓苔，亦曰金苔，亦曰夜明苔。","sortOrder":136},
  {"id":"s_work_nvlt_82_137","chapterId":"ch_work_nvlt_82","text":"江文通詩曰：青苔日夜黃。","sortOrder":137},
  {"id":"s_work_nvlt_82_138","chapterId":"ch_work_nvlt_82","text":"江賦，绿苔鬖髿乎研上，［研，石也。］","sortOrder":138},
  {"id":"s_work_nvlt_82_139","chapterId":"ch_work_nvlt_82","text":"江淹青苔賦，凿山楹為室，有老苔焉。","sortOrder":139},
  {"id":"s_work_nvlt_82_140","chapterId":"ch_work_nvlt_82","text":"天台山賦，踐莓苔之滑石。","sortOrder":140},
  {"id":"s_work_nvlt_82_141","chapterId":"ch_work_nvlt_82","text":"古詩，青苔依空牆。","sortOrder":141},
  {"id":"s_work_nvlt_82_142","chapterId":"ch_work_nvlt_82","text":"【詩】梁沈約詠青苔詩曰：緣階已漠漠，汎水复綿綿，微根知欲斷，輕絲似更聯。","sortOrder":142},
  {"id":"s_work_nvlt_82_143","chapterId":"ch_work_nvlt_82","text":"梁庾肩吾新苔詩曰：隨潮染岸石，逐脈聚浮查，徒令阿穀麗，停筐不汰沙。","sortOrder":143},
  {"id":"s_work_nvlt_82_144","chapterId":"ch_work_nvlt_82","text":"【賦】江淹青苔賦曰：嗟青苔之依依，無色類而可方，必居閒而就寂，似幽意而深傷，故其處石則松栝交陰，泉雨長註，橫涧俯视，崩壁仰顧，若其在水，則鏡帶湖沼，綿匝池林，春塘秀色，陽乌好音，乃生水而搖荡，遂出波而沉淫。","sortOrder":144},
  {"id":"s_work_nvlt_82_146","chapterId":"ch_work_nvlt_82","text":"《說文》曰：蒋，菰也。","sortOrder":146},
  {"id":"s_work_nvlt_82_147","chapterId":"ch_work_nvlt_82","text":"《廣雅》曰：蒋菰，其米謂之彫胡。","sortOrder":147},
  {"id":"s_work_nvlt_82_148","chapterId":"ch_work_nvlt_82","text":"《廣志》曰：菰可以為席，溫於蒲，生南方。","sortOrder":148},
  {"id":"s_work_nvlt_82_149","chapterId":"ch_work_nvlt_82","text":"《莊子》曰：孔子之楚，舍於蚁丘之蒋。","sortOrder":149},
  {"id":"s_work_nvlt_82_150","chapterId":"ch_work_nvlt_82","text":"《禮記》曰：十月收水泽之賦。","sortOrder":150},
  {"id":"s_work_nvlt_82_151","chapterId":"ch_work_nvlt_82","text":"江賦曰：泛泛之遊蒋。","sortOrder":151},
  {"id":"s_work_nvlt_82_152","chapterId":"ch_work_nvlt_82","text":"吳都賦，菰穗彫胡，菰子作餅。","sortOrder":152},
  {"id":"s_work_nvlt_82_153","chapterId":"ch_work_nvlt_82","text":"宋玉之，［《太平御覽》九百九十九作賦曰二字。］主人女為炊彫胡飯。","sortOrder":153},
  {"id":"s_work_nvlt_82_154","chapterId":"ch_work_nvlt_82","text":"【詩】梁沈約詠菰詩曰：結根布洲渚，垂葉滿皋泽，匹彼露葵羹，可以留上客。","sortOrder":154},
  {"id":"s_work_nvlt_82_156","chapterId":"ch_work_nvlt_82","text":"《爾雅》曰：菼，薍也，［似苇而小。］","sortOrder":156},
  {"id":"s_work_nvlt_82_157","chapterId":"ch_work_nvlt_82","text":"《毛詩》曰：蒹葭蒼蒼，白露為霜。","sortOrder":157},
  {"id":"s_work_nvlt_82_158","chapterId":"ch_work_nvlt_82","text":"《詩疏義》曰：薍或謂之荻，至秋堅成，謂之雚也。","sortOrder":158},
  {"id":"s_work_nvlt_82_159","chapterId":"ch_work_nvlt_82","text":"焦贛《易林》：剝之坤曰：從風縱火，荻芝俱死。","sortOrder":159},
  {"id":"s_work_nvlt_82_160","chapterId":"ch_work_nvlt_82","text":"《漢書》曰：董偃見寵馆陶公主，安陵袁叔謂偃曰：顧成廣遠，無宿宮。又有荻竹藉田，足下何不白主，獻長門園於上，此上所欲也。","sortOrder":160},
  {"id":"s_work_nvlt_82_161","chapterId":"ch_work_nvlt_82","text":"《抱朴子》曰：吳世有姚光者，有火術，吳主身臨试之，積荻數千束，光坐其上。又以數千束荻累之，因猛風燔之，火盡，光端坐灰中，振衣而起。","sortOrder":161},
  {"id":"s_work_nvlt_82_162","chapterId":"ch_work_nvlt_82","text":"晉中興書徵祥說曰：童謠雲，官家養芦化成荻，芦生不止自成積，是時盧循竊據廣州，國未能讨，因而用之，是官養之芦也，荻猶敵也。","sortOrder":162},
  {"id":"s_work_nvlt_82_163","chapterId":"ch_work_nvlt_82","text":"《毛詩》：敦彼行苇，牛羊勿踐履。","sortOrder":163},
  {"id":"s_work_nvlt_82_164","chapterId":"ch_work_nvlt_82","text":"又曰：誰謂河廣，一苇航之。","sortOrder":164},
  {"id":"s_work_nvlt_82_165","chapterId":"ch_work_nvlt_82","text":"又曰：有漼者淵，雚苇淠淠。","sortOrder":165},
  {"id":"s_work_nvlt_82_166","chapterId":"ch_work_nvlt_82","text":"《禮記》曰：七月納材苇。","sortOrder":166},
  {"id":"s_work_nvlt_82_167","chapterId":"ch_work_nvlt_82","text":"《呂氏春秋》：季秋之月，命虞人材苇供國。","sortOrder":167},
  {"id":"s_work_nvlt_82_168","chapterId":"ch_work_nvlt_82","text":"搜神記，朽苇化蛩也。","sortOrder":168},
  {"id":"s_work_nvlt_82_169","chapterId":"ch_work_nvlt_82","text":"《毛詩》曰：毳衣如菼，［菼，芦荻也。］","sortOrder":169},
  {"id":"s_work_nvlt_82_170","chapterId":"ch_work_nvlt_82","text":"又八月雚苇。","sortOrder":170},
  {"id":"s_work_nvlt_82_171","chapterId":"ch_work_nvlt_82","text":"《異苑》曰：盧龍將攻京師，謠曰：十丈瓦屋，芦作柱，薤作欄。","sortOrder":171},
  {"id":"s_work_nvlt_82_172","chapterId":"ch_work_nvlt_82","text":"郭璞奏曰：不宜禁荻地，禮雲，名山大泽不封，蓋欲以民通财共利，不獨专之也。","sortOrder":172},
  {"id":"s_work_nvlt_82_173","chapterId":"ch_work_nvlt_82","text":"【詩】梁元帝賦得春荻詩曰：翠菼玉池前，遙映江南莲，非秋無有眊，未燒不生煙。","sortOrder":173},
  {"id":"s_work_nvlt_82_174","chapterId":"ch_work_nvlt_82","text":"【詔】宋武帝詔曰：少府前歲所封諸洲芦荻，可开以利民。","sortOrder":174},
  {"id":"s_work_nvlt_82_176","chapterId":"ch_work_nvlt_82","text":"《逸禮》曰：天子之蓍九尺炁諸侯七尺，大夫五尺，士三尺，蓍千歲三百茎者，先知也。","sortOrder":176},
  {"id":"s_work_nvlt_82_177","chapterId":"ch_work_nvlt_82","text":"《史記》曰：天下和平，蓍茎長一丈，其聚生百茎，共根，今世取蓍，八十茎，長八尺，即難得矣，得六十茎，長八尺，即可用。","sortOrder":177},
  {"id":"s_work_nvlt_82_178","chapterId":"ch_work_nvlt_82","text":"洪范五行曰：蓍之言為耆也，百年一本生百茎，此草木之寿，亦知吉凶者，聖人以問鬼神。","sortOrder":178},
  {"id":"s_work_nvlt_82_179","chapterId":"ch_work_nvlt_82","text":"《淮南子》曰：上有丛蓍，下有伏龟。","sortOrder":179},
  {"id":"s_work_nvlt_82_180","chapterId":"ch_work_nvlt_82","text":"【詩】梁范筠詠蓍詩曰：數奇不可偶，性直誰能紆，禎蔡伏靈異，祥雲降溫腴。","sortOrder":180},
  {"id":"s_work_nvlt_82_181","chapterId":"ch_work_nvlt_82","text":"【賦】晉傅玄蓍賦曰：春邁衡德於青陽，混百卉而萌生，逮朱夏而修茂，暨商秋而堅貞，雖離霜而未彫，與潛龟乎通靈，於是原極以道，極形以度，以類萬物之情，以通天下之故，豈唯終始於事業，乃參天而倚數，弃原野之萧條，升雲階而內御，運茲茎於掌握，爻象形而星布，信鉤深而致遠，實开物而成務。","sortOrder":181},
  {"id":"s_work_nvlt_82_183","chapterId":"ch_work_nvlt_82","text":"《爾雅》曰：槚，苦茶，［早采者為茶，晚采者為茗。］","sortOrder":183},
  {"id":"s_work_nvlt_82_184","chapterId":"ch_work_nvlt_82","text":"《吳志》曰：孫皓每饗宴坐席，無能否，每率以七升為限，雖不悉入口，皆浇灌取盡，韦曜飲酒不過二升，初見禮異，密賜茶茗以當酒。","sortOrder":184},
  {"id":"s_work_nvlt_82_185","chapterId":"ch_work_nvlt_82","text":"吳興記曰：乌程縣西有溫山，出御荈。","sortOrder":185},
  {"id":"s_work_nvlt_82_186","chapterId":"ch_work_nvlt_82","text":"《續搜神記》曰：晉孝武帝世，宣城人秦精，嘗入武昌山中采茗，忽見一人，身長一丈，通體皆毛，精見之大怖，毛人径牵其臂，將至山曲大丛茗處，放之便去，須臾复來，乃探懷中橘與精，精甚怖，負茗而歸。","sortOrder":186},
  {"id":"s_work_nvlt_82_187","chapterId":"ch_work_nvlt_82","text":"《異苑》曰：剡縣陳務妻，少寡，與二兒為居，宅中先有古冢，每日作茗摶，辄先以著墳上，二子患之，曰：古墓何知，徒以勞意，欲掘除之，母苦禁乃止，夜即夢見一人，自說没來三百餘年，谬蒙惠泽，賢二子恒欲見毀，相賴保護，雖潛壤與朽骨，敢忘翳桑之報，明日晨興，於外屋得錢十萬，似久埋者，而貫皆新，提還告其兒，併有慚色，自是設饌愈謹。","sortOrder":187},
  {"id":"s_work_nvlt_82_188","chapterId":"ch_work_nvlt_82","text":"【賦】晉杜育荈賦曰：靈山惟嶽，奇產所鍾，厥生荈草，弥穀被岗，承丰壤之滋润，受甘靈之霄降，月惟初秋，農功少休，結偶同旅，是采是求，水則〈山氏〉方之註，挹彼清流，器泽陶簡，出自東隅，酌之以匏，取式公劉，惟茲初成，沬沉華浮，煥如積雪，晔若春敷。","sortOrder":188},
  {"id":"s_work_nvlt_82_190","chapterId":"ch_work_nvlt_82","text":"《爾雅》曰：蔌杜，茅也。","sortOrder":190},
  {"id":"s_work_nvlt_82_191","chapterId":"ch_work_nvlt_82","text":"《說文》曰：菅，茅也。","sortOrder":191},
  {"id":"s_work_nvlt_82_192","chapterId":"ch_work_nvlt_82","text":"《易》曰：拔茅連茹，以其匯，征吉。","sortOrder":192},
  {"id":"s_work_nvlt_82_193","chapterId":"ch_work_nvlt_82","text":"茅苹一名茹子。","sortOrder":193},
  {"id":"s_work_nvlt_82_194","chapterId":"ch_work_nvlt_82","text":"又曰：藉用白茅，無咎，天官甸師，祭祀供萧茅。","sortOrder":194},
  {"id":"s_work_nvlt_82_195","chapterId":"ch_work_nvlt_82","text":"《尚書·禹貢》曰：荆州包匦菁茅。","sortOrder":195},
  {"id":"s_work_nvlt_82_196","chapterId":"ch_work_nvlt_82","text":"《毛詩》曰：白華菅兮，白茅束兮。","sortOrder":196},
  {"id":"s_work_nvlt_82_197","chapterId":"ch_work_nvlt_82","text":"又曰：野有死麕，白茅苞之。","sortOrder":197},
  {"id":"s_work_nvlt_82_198","chapterId":"ch_work_nvlt_82","text":"又曰：晝爾於茅，宵爾索綯。","sortOrder":198},
  {"id":"s_work_nvlt_82_199","chapterId":"ch_work_nvlt_82","text":"《左傳》曰：齊侯伐楚，謂楚曰：爾貢苞茅不入，王祭不供，無以縮酒，寡人是徵。","sortOrder":199},
  {"id":"s_work_nvlt_82_200","chapterId":"ch_work_nvlt_82","text":"典錄曰：武王伐殷，微子啟肉袒面縛，牵羊把茅，膝行而前。","sortOrder":200},
  {"id":"s_work_nvlt_82_201","chapterId":"ch_work_nvlt_82","text":"《六韜》曰：呂尚坐茅而漁。","sortOrder":201},
  {"id":"s_work_nvlt_82_202","chapterId":"ch_work_nvlt_82","text":"尹《文子》曰：尧為天子，土階三尺，茅茨不翦。","sortOrder":202},
  {"id":"s_work_nvlt_82_203","chapterId":"ch_work_nvlt_82","text":"《尸子》曰：殷湯救旱，素車白馬，身婴白茅，以身為牲。","sortOrder":203},
  {"id":"s_work_nvlt_82_204","chapterId":"ch_work_nvlt_82","text":"《莊子》曰：小巫見大巫，拔茅而弃，此其所以終身弗如。","sortOrder":204},
  {"id":"s_work_nvlt_82_205","chapterId":"ch_work_nvlt_82","text":"《離骚》曰：索靈茅以蓬莼。","sortOrder":205},
  {"id":"s_work_nvlt_82_206","chapterId":"ch_work_nvlt_82","text":"又曰：蘭芷变而不芬兮，荃蕙化而為茅。","sortOrder":206},
  {"id":"s_work_nvlt_82_207","chapterId":"ch_work_nvlt_82","text":"《史記·封禪書》曰：管仲說桓公雲，古之封禪，江淮間，一茅三節，所以為藉也。","sortOrder":207},
  {"id":"s_work_nvlt_82_208","chapterId":"ch_work_nvlt_82","text":"吳錄《地理志》曰：桂陽郴縣，有菁茅，可染布，零陵有香茅，任土貢之。","sortOrder":208},
  {"id":"s_work_nvlt_82_209","chapterId":"ch_work_nvlt_82","text":"沈約《宋書》曰：有三脊茅，生石頭西岸，江夏王義恭，累表勸封禪，上甚悅。","sortOrder":209},
  {"id":"s_work_nvlt_82_210","chapterId":"ch_work_nvlt_82","text":"【詩】梁簡文帝香茅詩曰：銅律與鳴琴，俱稱類君子，豈若江淮間，發葉超眾美，珍同自牧歸，茅因匯征起，豈獨邁秦蘅，方知蔑沅芷。","sortOrder":210},
  {"id":"s_work_nvlt_82_211","chapterId":"ch_work_nvlt_82","text":"梁定襄侯萧祗詠香茅詩曰：鶗窸芳不歇，霜繁绿更滋，擢本同三脊，流芳有四時，粗根縮酒易，結解舞蠶遲，終當入楚貢，豈羨詠陳詩。","sortOrder":211},
  {"id":"s_work_nvlt_82_213","chapterId":"ch_work_nvlt_82","text":"《毛詩》曰：彼茁者蓬。","sortOrder":213},
  {"id":"s_work_nvlt_82_214","chapterId":"ch_work_nvlt_82","text":"又曰：首如飛蓬。","sortOrder":214},
  {"id":"s_work_nvlt_82_215","chapterId":"ch_work_nvlt_82","text":"芜城賦，蔌蔌風威，孤蓬自振，驚沙坐飛。","sortOrder":215},
  {"id":"s_work_nvlt_82_216","chapterId":"ch_work_nvlt_82","text":"《列子》曰：見百歲髑髏，搴蓬而指之。","sortOrder":216},
  {"id":"s_work_nvlt_82_217","chapterId":"ch_work_nvlt_82","text":"《曾子》曰：蓬生麻中，不扶自直，白沙在泥，與之皆黑。","sortOrder":217},
  {"id":"s_work_nvlt_82_218","chapterId":"ch_work_nvlt_82","text":"《商君書》曰：今夫飛蓬，飄風而行千里，乘風之势也。","sortOrder":218},
  {"id":"s_work_nvlt_82_219","chapterId":"ch_work_nvlt_82","text":"《禮》曰：桑弧蓬矢。","sortOrder":219},
  {"id":"s_work_nvlt_82_220","chapterId":"ch_work_nvlt_82","text":"《莊子》曰：斥鷃翱翔蓬蒿之間。","sortOrder":220},
  {"id":"s_work_nvlt_82_221","chapterId":"ch_work_nvlt_82","text":"古詩，轉蓬離本根，飄之畏長風。","sortOrder":221},
  {"id":"s_work_nvlt_82_222","chapterId":"ch_work_nvlt_82","text":"又曰：孤蓬轉霜根。","sortOrder":222},
  {"id":"s_work_nvlt_82_223","chapterId":"ch_work_nvlt_82","text":"《離骚》：蓬艾親人，御於茅［《太平御覽》九百九十七作第。］兮。","sortOrder":223},
  {"id":"s_work_nvlt_82_224","chapterId":"ch_work_nvlt_82","text":"魯哀公失國，［按本條《太平御覽》九百九十七作晏子，此脱書名。又按哀晏子春秋作昭。］走齊，公問焉，曰：子之年甚少矣，道至於此乎，吾少之時，多愛我者，吾體［御覽作禮。］不親，人多諫者，吾忘［御覽作忌。］不能用，是內無弼，外無辅，辅弼無人，諂諛甚眾，譬之猶秋蓬也，孤其根本，密其枝葉。","sortOrder":224},
  {"id":"s_work_nvlt_82_225","chapterId":"ch_work_nvlt_82","text":"《尚書大傳》曰：子夏作壤室，編蓬戶，彈琴瑟其中，以歌先王之風，淮南子曰：見飛蓬轉而知為車。","sortOrder":225},
  {"id":"s_work_nvlt_82_226","chapterId":"ch_work_nvlt_82","text":"《三辅决錄》曰：張仲蔚，平陵人也，與同郡魏景卿，俱隱身不仕，所居蓬蒿没人。","sortOrder":226},
  {"id":"s_work_nvlt_82_227","chapterId":"ch_work_nvlt_82","text":"【詩】魏曹植詩曰：轉蓬離本根，飄飖隨長風，何意回飆舉，吹我入雲中，高高上無極，天路安可窮，類此流宕子，捐軀遠從戎，毛褐不掩形，薇藿常不充，去去莫复道，沉忧令人老。","sortOrder":227},
  {"id":"s_work_nvlt_82_228","chapterId":"ch_work_nvlt_82","text":"晉司馬彪詩曰：百草應節生，含氣有深淺，秋蓬獨何辜，飄飖隨風轉，長飆台飛薄，吹我之四遠，搔首望故株，邈然無由反。","sortOrder":228},
  {"id":"s_work_nvlt_82_230","chapterId":"ch_work_nvlt_82","text":"《爾雅》曰：艾，冰台也。","sortOrder":230},
  {"id":"s_work_nvlt_82_231","chapterId":"ch_work_nvlt_82","text":"《毛詩》曰：彼采艾兮，一日不見，如三歲兮。","sortOrder":231},
  {"id":"s_work_nvlt_82_232","chapterId":"ch_work_nvlt_82","text":"《莊子》曰：越王子搜，逃乎丹穴，越國無君，求王子搜不得，從之丹穴，不肯出，越人薰之以艾。","sortOrder":232},
  {"id":"s_work_nvlt_82_233","chapterId":"ch_work_nvlt_82","text":"崔寔月令曰：三月可采艾。","sortOrder":233},
  {"id":"s_work_nvlt_82_234","chapterId":"ch_work_nvlt_82","text":"博物志，削冰至圓以向日，以艾於後承其影，得火。","sortOrder":234},
  {"id":"s_work_nvlt_82_235","chapterId":"ch_work_nvlt_82","text":"《孟子》曰：七年之病，求三年之艾。","sortOrder":235},
  {"id":"s_work_nvlt_82_236","chapterId":"ch_work_nvlt_82","text":"《楚辭》曰：萧艾於箧笥，謂蕙芷而不香。","sortOrder":236},
  {"id":"s_work_nvlt_82_237","chapterId":"ch_work_nvlt_82","text":"《離骚》曰：扈服艾以盈腰兮，謂幽蘭其不可佩。","sortOrder":237},
  {"id":"s_work_nvlt_82_238","chapterId":"ch_work_nvlt_82","text":"又曰：何昔日之芳草兮，今直為此艾。","sortOrder":238},
  {"id":"s_work_nvlt_82_239","chapterId":"ch_work_nvlt_82","text":"漢武內傳，西王母神仙次藥，有靈丛艾。","sortOrder":239},
  {"id":"s_work_nvlt_82_240","chapterId":"ch_work_nvlt_82","text":"【賦】孔璠之艾賦曰：良藥弗達，妙針莫宣，奇艾急病，靡身挺煙，治匪君臣，得用神火，振淹固於一烂，氣絕息乎無假，淳建投而招祟，鉗椒梼而貽禍，伊茲艾之淑粹，仍索质於中野，嗟乎貞灰與邪燼迭御，芳煙與苦蘭競薰，是以艾正而賤，蘭妖而珍，故言尧則桀對，舉蘭則艾因。","sortOrder":240},
  {"id":"s_work_nvlt_82_241","chapterId":"ch_work_nvlt_82","text":"【贊】孔璠之艾贊曰：藹藹靈艾，蔚彼脩坂，混區群卉，理深用遠。","sortOrder":241},
  {"id":"s_work_nvlt_82_243","chapterId":"ch_work_nvlt_82","text":"《爾雅》曰：諸慮，山櫐，［今江東呼櫐為藤，藤似葛而粗大也。］","sortOrder":243},
  {"id":"s_work_nvlt_82_244","chapterId":"ch_work_nvlt_82","text":"廣雅曰：藟，藤也。","sortOrder":244},
  {"id":"s_work_nvlt_82_245","chapterId":"ch_work_nvlt_82","text":"《毛詩》曰：南有樛木，葛藟累之。","sortOrder":245},
  {"id":"s_work_nvlt_82_246","chapterId":"ch_work_nvlt_82","text":"《山海經》曰：卑山其上多櫐，［今狸豆之屬。］","sortOrder":246},
  {"id":"s_work_nvlt_82_247","chapterId":"ch_work_nvlt_82","text":"南方草物状曰：浮沉藤，生子大如齏甌，正月華色，仍連著實，十月臈月熟，色赤，生食之甜酢，生交阯九真，含蘭子藤，生緣树木，正二月花色，四五月熟，實如{莉木}，赤如雄雞冠，取生食之，味淡泊，出交阯合浦，野聚藤，緣树木，二月花色，仍連著實，五六月熟，子大如羹甌。俚民煮食，其味甜酢，出蒼梧，{艹椒}藤生金封山，俚人往往賣之，其色正赤，出興古。","sortOrder":247},
  {"id":"s_work_nvlt_82_248","chapterId":"ch_work_nvlt_82","text":"裴氏《廣州記》曰：土人伐船為業，隨树所在，就以成槽，皆去水難遠，動有數里，山生草，名為膏藤，津汁软滑，無物能比，以此导地，牵之如流，亦五六丈舡，數人便運。","sortOrder":248},
  {"id":"s_work_nvlt_82_249","chapterId":"ch_work_nvlt_82","text":"《臨海異物志》曰：鍾藤，附树作根，软弱，須緣树而作，藤既纏裹，树便死，且有惡汁，尤令速朽也，藤盛成树，若木自然，大者或至十围。","sortOrder":249},
  {"id":"s_work_nvlt_82_250","chapterId":"ch_work_nvlt_82","text":"又曰：{艹椒}藤，围數寸，重於竹，可以為杖蔑，以縛船，及以為席，勝於竹也。","sortOrder":250},
  {"id":"s_work_nvlt_82_251","chapterId":"ch_work_nvlt_82","text":"王歆始興記曰：晉中朝，有质子將歸，忽有人寄其書，告曰：吾家在觀亭，亭廟石間有懸藤，君至叩藤，家人自出，歸者如其言，果有二人出水取書，併曰：江伯令君前，入水，見屋舍甚麗，今俗鹹言觀亭有江伯神也。","sortOrder":251},
  {"id":"s_work_nvlt_82_252","chapterId":"ch_work_nvlt_82","text":"顧微《廣州記》曰：{艹椒}［《太平御覽》九百九十五作科。］藤，如栟闾，葉疏破，皮青，多棘刺，高五六丈者，如五六寸竹，小者如筆管竹，類有十許种，續遊，［御覽作斷。］草藤也，一曰诺藤，二［御覽作一。］曰水藤，山行渴，則斷取汁飲之，治人體有損絕，沐則長發，去地一丈斷之，辄更生根至地，永不死。","sortOrder":252},
  {"id":"s_work_nvlt_82_253","chapterId":"ch_work_nvlt_82","text":"《異苑》曰：永陽縣有山，壁立千仞，巖上有石室，路右名為神農窟，窟前百藥，丛茂，莫不畢備。又別有異藤，花形似菱菜，朝紫，中绿，晡黃，暮青，夜赤，五色迭耀。","sortOrder":253},
  {"id":"s_work_nvlt_82_254","chapterId":"ch_work_nvlt_82","text":"【詩】梁簡文帝詠藤詩曰：纖條寄乔木，弱影掣風斜，標春抽晓翠，出霧掛懸花。","sortOrder":254},
  {"id":"s_work_nvlt_82_255","chapterId":"ch_work_nvlt_82","text":"◇菜蔬","sortOrder":255},
  {"id":"s_work_nvlt_82_256","chapterId":"ch_work_nvlt_82","text":"《毛詩》曰：其蔌維何，惟筍及蒲。","sortOrder":256},
  {"id":"s_work_nvlt_82_257","chapterId":"ch_work_nvlt_82","text":"又曰：我有旨蓄，亦以御冬。","sortOrder":257},
  {"id":"s_work_nvlt_82_258","chapterId":"ch_work_nvlt_82","text":"《爾雅》曰：菜謂之蔬，不熟曰饉。","sortOrder":258},
  {"id":"s_work_nvlt_82_259","chapterId":"ch_work_nvlt_82","text":"周禮，春官曰：春入學，舍采合舞。","sortOrder":259},
  {"id":"s_work_nvlt_82_260","chapterId":"ch_work_nvlt_82","text":"《禮記》曰：仲秋之月，乃命有司，趣民務蓄菜。","sortOrder":260},
  {"id":"s_work_nvlt_82_261","chapterId":"ch_work_nvlt_82","text":"《論語》曰：雖蔬食，菜羹瓜祭，必斋如也。","sortOrder":261},
  {"id":"s_work_nvlt_82_262","chapterId":"ch_work_nvlt_82","text":"《孔丛子》曰：菜謂之蔬。","sortOrder":262},
  {"id":"s_work_nvlt_82_263","chapterId":"ch_work_nvlt_82","text":"《莊子》曰：顏回不茹葷三月。","sortOrder":263},
  {"id":"s_work_nvlt_82_264","chapterId":"ch_work_nvlt_82","text":"《呂氏春秋》曰：菜之美者，寿木之華，赤木之葉，餘瞀之南，有菜名嘉树，其色若碧。","sortOrder":264},
  {"id":"s_work_nvlt_82_265","chapterId":"ch_work_nvlt_82","text":"漢書西域傳曰：罽賓地溫和，冬食生菜。","sortOrder":265},
  {"id":"s_work_nvlt_82_266","chapterId":"ch_work_nvlt_82","text":"《魏志》曰：倭國地溫和，冬夏食生菜。","sortOrder":266},
  {"id":"s_work_nvlt_82_267","chapterId":"ch_work_nvlt_82","text":"《漢武內傳》曰：西王母曰：仙之上藥，有碧海之琅菜。","sortOrder":267},
  {"id":"s_work_nvlt_82_268","chapterId":"ch_work_nvlt_82","text":"王充《論衡》曰：董仲舒讀春秋，三年不窥園菜。","sortOrder":268},
  {"id":"s_work_nvlt_82_269","chapterId":"ch_work_nvlt_82","text":"《孝子傳》曰：洛陽公輦水作漿，兼以給過者，公補屩，不取其直，天神化為書生，問公何不种菜，曰：無种，即遺數升，公种之，化為白璧，餘皆為錢，公得以娶婦。","sortOrder":269},
  {"id":"s_work_nvlt_82_270","chapterId":"ch_work_nvlt_82","text":"大夫有汙猪之宮，雖有美菜，有義之士不食。","sortOrder":270},
  {"id":"s_work_nvlt_82_271","chapterId":"ch_work_nvlt_82","text":"莊子，宣尼窮於陳蔡之間，顏回擇菜。","sortOrder":271},
  {"id":"s_work_nvlt_82_272","chapterId":"ch_work_nvlt_82","text":"《文選》：野有菜蔬之色。","sortOrder":272},
  {"id":"s_work_nvlt_82_273","chapterId":"ch_work_nvlt_82","text":"《儀禮》曰：婚禮，舅姑既没，則婦三月乃奠菜蔬，蓋用待告。","sortOrder":273},
  {"id":"s_work_nvlt_82_274","chapterId":"ch_work_nvlt_82","text":"《漢書》：張竦曰：古叛逆之國，潴其宮室，以為汙池，名曰凶墟，雖生菜蔬而民不食。","sortOrder":274},
  {"id":"s_work_nvlt_82_275","chapterId":"ch_work_nvlt_82","text":"菜之美者，具區之菁。","sortOrder":275},
  {"id":"s_work_nvlt_82_276","chapterId":"ch_work_nvlt_82","text":"范宣挑菜，傷指，大啼曰：身體發膚，不敢毀傷，故啼。","sortOrder":276},
  {"id":"s_work_nvlt_82_277","chapterId":"ch_work_nvlt_82","text":"蜀都賦，五肉七菜，勝掩腥臊。","sortOrder":277},
  {"id":"s_work_nvlt_82_278","chapterId":"ch_work_nvlt_82","text":"《廣州先賢傳》：丁密，蒼梧人，非家織布不衣，非己耕种菜果不食。","sortOrder":278},
  {"id":"s_work_nvlt_82_279","chapterId":"ch_work_nvlt_82","text":"杜蘭香別傳曰：香降張硕，赍瓦榼酒，七子樏，樏多菜而無他味，亦有世間常菜，辄有三种色，或丹或紫，一物與海蛤相象，併有非時菜，硕雲，食之亦不甘，然一食七八日不飢。","sortOrder":279},
  {"id":"s_work_nvlt_82_280","chapterId":"ch_work_nvlt_82","text":"【啟】梁皇太子謝敕赉河南菜啟曰：海水無波，來因九譯，周原泽洽，味備百羞，尧韭未儔，姬歜非喻。","sortOrder":280},
  {"id":"s_work_nvlt_82_281","chapterId":"ch_work_nvlt_82","text":"又謝敕赉大菘啟曰：吳愧千里之莼，蜀慚七菜之賦，是知泮宮采茆，空入魯詩，流火烹葵，徒傳豳曲。","sortOrder":281},
  {"id":"s_work_nvlt_82_283","chapterId":"ch_work_nvlt_82","text":"《說文》曰：葵，菜也。","sortOrder":283},
  {"id":"s_work_nvlt_82_284","chapterId":"ch_work_nvlt_82","text":"七啟曰：芳孤精擇，［《文選》三十四作粺。］霜蓄霜葵。","sortOrder":284},
  {"id":"s_work_nvlt_82_285","chapterId":"ch_work_nvlt_82","text":"《文選》：青青園中葵，凝露待日晞。","sortOrder":285},
  {"id":"s_work_nvlt_82_286","chapterId":"ch_work_nvlt_82","text":"又言，譬如後園葵，有葉待秋霜。","sortOrder":286},
  {"id":"s_work_nvlt_82_287","chapterId":"ch_work_nvlt_82","text":"又曰：無以肉食資，取笑葵與藿。","sortOrder":287},
  {"id":"s_work_nvlt_82_288","chapterId":"ch_work_nvlt_82","text":"豳風曰：七月烹葵及菽。","sortOrder":288},
  {"id":"s_work_nvlt_82_289","chapterId":"ch_work_nvlt_82","text":"《左傳》：仲尼曰：鮑莊子之智不如葵，葵猶能衛其足，［莊子居亂，不能危行言遜，以致刖足。］","sortOrder":289},
  {"id":"s_work_nvlt_82_290","chapterId":"ch_work_nvlt_82","text":"《師曠占》曰：黃帝問師曠，曰：欲知牛馬貴賤，秋葵下小葵生，牛馬貴，大葵不虫，牛馬賤。","sortOrder":290},
  {"id":"s_work_nvlt_82_291","chapterId":"ch_work_nvlt_82","text":"《史記》曰：公儀休為魯相，食葵而美，拔其園葵弃之。","sortOrder":291},
  {"id":"s_work_nvlt_82_292","chapterId":"ch_work_nvlt_82","text":"《韓詩外傳》曰：魯監門女婴，相從績，中夜泣曰：衛世子不肖，是以泣，其偶問其故，曰：宋司馬得罪於宋，出奔於魯，馬佚，食吾園葵，是歲亡利一半，由是觀之，禍福相及也。","sortOrder":292},
  {"id":"s_work_nvlt_82_293","chapterId":"ch_work_nvlt_82","text":"《列女傳》曰：魯漆室女倚柱而嘯，鄰婦曰：欲嫁乎，曰：吾忧魯君老而太子少也，婦曰：此魯大夫之忧，女曰：昔晉客舍吾家，系馬於園，馬佚，踐吾園葵，使吾終歲不厭葵味。","sortOrder":293},
  {"id":"s_work_nvlt_82_294","chapterId":"ch_work_nvlt_82","text":"《列仙傳》曰：丁次都，不知何許人，為遼東丁氏作人，丁氏常使買葵，冬得生葵，問何得此葵，雲從日南買來。","sortOrder":294},
  {"id":"s_work_nvlt_82_295","chapterId":"ch_work_nvlt_82","text":"《異苑》曰：符堅將欲南師，夢葵生城內，明以問婦，婦曰：若征軍遠出，難為將也。","sortOrder":295},
  {"id":"s_work_nvlt_82_296","chapterId":"ch_work_nvlt_82","text":"《博物志》曰：陳葵子微炒，令爆吒，散著熟地中，遍踏之，朝种暮生，遠不過宿。","sortOrder":296},
  {"id":"s_work_nvlt_82_297","chapterId":"ch_work_nvlt_82","text":"北齊彭城王攸在郡，王氏种葵三畝，被人盜之，王密令書葵葉，明旦市看之，遂得偷者。","sortOrder":297},
  {"id":"s_work_nvlt_82_298","chapterId":"ch_work_nvlt_82","text":"【詩】古詩，采葵莫傷根，傷根葵不生，結友莫羞貧，羞貧友不成。","sortOrder":298},
  {"id":"s_work_nvlt_82_299","chapterId":"ch_work_nvlt_82","text":"晉陆機園葵詩曰：种葵北園中，葵生鬱萋萋，朝榮東北傾，夕穎西南晞，靈露垂鮮泽，朗日耀其暉，時逝和風戢，歲暮傷飆飛，曾露無溫液，嚴霜有凝威，幸蒙高墉德，玄景荫素蕤，丰條併春盛，落葉後秋衰，慶彼晚彫福，忘此孤生悲。","sortOrder":299},
  {"id":"s_work_nvlt_82_300","chapterId":"ch_work_nvlt_82","text":"又詩曰：翩翩晚彫葵，孤生寄北蕃，被蒙覆露惠，微軀後時殘，庇足同一智，生理各萬端，不若聞道易，但傷知命難。","sortOrder":300},
  {"id":"s_work_nvlt_82_302","chapterId":"ch_work_nvlt_82","text":"《爾雅》曰：{艹折}蓂，大荠，［似荠，葉細。］","sortOrder":302},
  {"id":"s_work_nvlt_82_303","chapterId":"ch_work_nvlt_82","text":"又曰：蒫，荠實。","sortOrder":303},
  {"id":"s_work_nvlt_82_304","chapterId":"ch_work_nvlt_82","text":"《說文》曰：荠草可食也。","sortOrder":304},
  {"id":"s_work_nvlt_82_305","chapterId":"ch_work_nvlt_82","text":"《毛詩》曰：誰謂荼苦，其甘如荠。","sortOrder":305},
  {"id":"s_work_nvlt_82_306","chapterId":"ch_work_nvlt_82","text":"《禮記》曰：孟夏之月，靡草死，［荠，亭歷之屬也。］","sortOrder":306},
  {"id":"s_work_nvlt_82_307","chapterId":"ch_work_nvlt_82","text":"《淮南子》曰：荠夌［《太平御覽》九百八十作麥，下條同。］冬生而夏死。","sortOrder":307},
  {"id":"s_work_nvlt_82_308","chapterId":"ch_work_nvlt_82","text":"《抱朴子》曰：荠夌大{艹秝}，仲夏而枯。","sortOrder":308},
  {"id":"s_work_nvlt_82_309","chapterId":"ch_work_nvlt_82","text":"【賦】夏侯湛賦曰：寒冬之日，餘登乎城，跬步北園，睹眾草之萎悴，覽林果之零殘，悲纖條之槁摧，愍枯葉之飄殫，見芳荠之時生，被畦畴而獨繁，鑽重冰而挺茂，蒙嚴霜以發鮮，舍盛陽而弗萌，在太陰而斯育，永安性於猛寒，羌無寧乎暖燠，齊精氣於款冻，均貞固乎松竹。","sortOrder":309},
  {"id":"s_work_nvlt_82_310","chapterId":"ch_work_nvlt_82","text":"齊卞伯玉荠賦曰：終風扫於暮節，霜露交於杪秋，有萋萋之绿荠，方滋繁於中丘，《禮記》曰：凡進食之禮，葱渫處末。","sortOrder":310},
  {"id":"s_work_nvlt_82_311","chapterId":"ch_work_nvlt_82","text":"又曰：脍春用葱，脂用葱，為君子擇葱薤，如［《太平御覽》九百七十七作必。］絕其本末。","sortOrder":311},
  {"id":"s_work_nvlt_82_312","chapterId":"ch_work_nvlt_82","text":"《爾雅》茖，山葱，細茎大葉。","sortOrder":312},
  {"id":"s_work_nvlt_82_313","chapterId":"ch_work_nvlt_82","text":"劉向別傳［《太平御覽》九百八十作錄。］曰：都尉有种葱書，曹公既與先生言，細人觇之，見其拔葱，［按曹公以下，《太平御覽》九百七十七引，作華陽國志，當另條。］","sortOrder":313},
  {"id":"s_work_nvlt_82_314","chapterId":"ch_work_nvlt_82","text":"《莊子》曰：徐無鬼見武侯曰：先生居山林，厭葱韭，今老欲甘酒肉之味耶。","sortOrder":314},
  {"id":"s_work_nvlt_82_315","chapterId":"ch_work_nvlt_82","text":"又曰：春月飲酒加葱，以通五臟。","sortOrder":315},
  {"id":"s_work_nvlt_82_316","chapterId":"ch_work_nvlt_82","text":"《春秋元命包》曰：天門山上有葱，所种畦泷悉著，行人拔取者悉絕，若精神而求，即不拔自出，奇異辛香。","sortOrder":316},
  {"id":"s_work_nvlt_82_317","chapterId":"ch_work_nvlt_82","text":"《漢書》：龚遂勸民，令人一口，种五十本葱，一畦韭，百本薤。","sortOrder":317},
  {"id":"s_work_nvlt_82_318","chapterId":"ch_work_nvlt_82","text":"《西河舊事》曰：葱嶺在敦煌西八十里，其山高大，上生葱，故曰葱嶺。","sortOrder":318},
  {"id":"s_work_nvlt_82_319","chapterId":"ch_work_nvlt_82","text":"《列仙傳》曰：阮丘，蛆山上种葱百餘年，乃去。","sortOrder":319},
  {"id":"s_work_nvlt_82_320","chapterId":"ch_work_nvlt_82","text":"《晉令》曰：居洛陽內，園菜欲課以當［三字《太平御覽》九百七十七作以當課，此倒。］者，耳［御覽作聽，此訛。］其引長流，灌紫葱，丁各三畝。","sortOrder":320},
  {"id":"s_work_nvlt_82_321","chapterId":"ch_work_nvlt_82","text":"《東觀漢記》曰：孔奋，字君魚，為姑臧長，時天下亂，河西獨安，臧長居數月，辄致資產，奋在姑臧四年，财物不增，唯老母妻子但菜食，或謂奋曰：置脂膏中，亦不能自润。","sortOrder":321},
  {"id":"s_work_nvlt_82_322","chapterId":"ch_work_nvlt_82","text":"《漢武內傳》曰：西王母曰：仙人上藥，有玄都綺葱。","sortOrder":322},
  {"id":"s_work_nvlt_82_323","chapterId":"ch_work_nvlt_82","text":"邵信臣曰：臣太官种冬葱，生不時之物，有傷於人也。","sortOrder":323},
  {"id":"s_work_nvlt_82_325","chapterId":"ch_work_nvlt_82","text":"《爾雅》曰：薔虞蓼，［虞泽蓼也。］","sortOrder":325},
  {"id":"s_work_nvlt_82_326","chapterId":"ch_work_nvlt_82","text":"《詩》曰：予又集於蓼，［言辛苦也。］《離骚》曰：蓼虫不能從乎葵菜。","sortOrder":326},
  {"id":"s_work_nvlt_82_327","chapterId":"ch_work_nvlt_82","text":"吳氏《本草》曰：蓼實一名天蓼，一名野蓼，一名泽蓼。","sortOrder":327},
  {"id":"s_work_nvlt_82_328","chapterId":"ch_work_nvlt_82","text":"《禮記》曰：鶉雞羹鴽酿之蓼。","sortOrder":328},
  {"id":"s_work_nvlt_82_329","chapterId":"ch_work_nvlt_82","text":"劉向別錄曰：尹都尉書，有种蓼篇，《吳越春秋》曰：越王念吳，欲复怨，非一旦也，苦思勞心，夜以接日，臥則切之以蓼。","sortOrder":329},
  {"id":"s_work_nvlt_82_330","chapterId":"ch_work_nvlt_82","text":"魏《文子》曰：蓼虫在蓼則生，在芥則死，非蓼仁而芥賊也，本不可失。","sortOrder":330},
  {"id":"s_work_nvlt_82_331","chapterId":"ch_work_nvlt_82","text":"古詩曰：蘇蓼出溝渠。","sortOrder":331},
  {"id":"s_work_nvlt_82_332","chapterId":"ch_work_nvlt_82","text":"【賦】漢孔臧蓼虫賦曰：季夏既望，暑往涼還，逍遙諷誦，遂居東園，周旋覽觀，憩乎南蕃，睹茲芪蓼，紛葩吐榮，猗那隨風，绿葉厲茎，爰有蠕虫，厥状似螟，群聚其間，食之以生，於是寤物讬事，推况乎人，幼長斯蓼，莫或知辛，膏粱之子，豈曰不雲，苟非德義，不以為家，安逸無心，如禽獸何，逸必致驕，驕必致亡，匪唯辛苦，乃丁大殃。","sortOrder":332},
  {"id":"s_work_nvlt_82_333","chapterId":"ch_work_nvlt_82","text":"《藝文類聚》　唐·欧陽詢","sortOrder":333},
  {"id":"s_work_nvlt_83_1","chapterId":"ch_work_nvlt_83","text":"卷八十三寶玉部上","sortOrder":1},
  {"id":"s_work_nvlt_83_2","chapterId":"ch_work_nvlt_83","text":"○寶金銀玉珪","sortOrder":2},
  {"id":"s_work_nvlt_83_4","chapterId":"ch_work_nvlt_83","text":"《爾雅》曰：琛，寶也，［美寶為琛。］","sortOrder":4},
  {"id":"s_work_nvlt_83_5","chapterId":"ch_work_nvlt_83","text":"《禮記》曰：南宮敬叔反，必載寶而朝，［敬叔，魯卿，失位去魯，得反載其寶以朝君。］","sortOrder":5},
  {"id":"s_work_nvlt_83_6","chapterId":"ch_work_nvlt_83","text":"夫子曰：如是其货也，丧不如速貧之愈也。","sortOrder":6},
  {"id":"s_work_nvlt_83_7","chapterId":"ch_work_nvlt_83","text":"《左傳》曰：晉荀息請以屈產之乘，垂棘之璧，假道於虞以伐虢，公曰：是吾寶也，對曰：若得道於虞，猶外府也。","sortOrder":7},
  {"id":"s_work_nvlt_83_8","chapterId":"ch_work_nvlt_83","text":"又曰：宋人得玉，獻諸子罕曰：以示玉人，玉人以為寶也，故敢獻之，子罕曰：我以不貪為寶，爾以玉為寶，若以與我，皆丧寶也，不若人有其寶。","sortOrder":8},
  {"id":"s_work_nvlt_83_9","chapterId":"ch_work_nvlt_83","text":"公羊傳曰：虞公貪而好寶，及為晉所滅，抱寶牵馬而去。","sortOrder":9},
  {"id":"s_work_nvlt_83_10","chapterId":"ch_work_nvlt_83","text":"又曰：盜竊寶玉大弓。","sortOrder":10},
  {"id":"s_work_nvlt_83_11","chapterId":"ch_work_nvlt_83","text":"《穆天子傳》曰：西征至陽紆之山，河伯冯夷所都，是惟河宗雲，［太平御覽八百零二作氏。］天子［御覽作乃至。］崑崙之山丘，舂［御覽舂上有觀字。］山之寶玉，《管子》曰：玉起於禺氏，金起於汝漢，珠起於赤野，先王為其從遠，其至之難，故讬用於其重，以珠玉為上幣，黃金為中幣，刀布為下幣。","sortOrder":11},
  {"id":"s_work_nvlt_83_12","chapterId":"ch_work_nvlt_83","text":"《史記》曰：梁惠王與齊威王田於郊，威王問曰：王亦有寶乎，惠王曰：若寡人國小，尚有径寸之珠，照車前後各十二乘者十枚，奈何以萬乘之國，而無寶乎，威王曰：寡人以為寶與王異，吾臣有檀子者，使守南城，則楚人不敢為寇，東取泗上，十二諸侯皆來朝，吾臣有盼子者，使守高唐，則趙人不敢東漁，吾吏有黔夫者，使守徐州，則燕人祭北門，趙人祭西門，［齊之北門西門也，言燕趙之人，畏見侵伐，故祭以求福。］徙而從者七千餘家，吾臣有种首者，使備盜賊，則的不拾遺，將以照千里，豈特十二匪哉，梁惠王堆，不怿而去。","sortOrder":12},
  {"id":"s_work_nvlt_83_13","chapterId":"ch_work_nvlt_83","text":"《淮南子》曰：夫夏後氏之璜，不能無考，考，瑕亹也，明月之珠，不能無颣，［颣，絲結也。］其小惡不足以妨大美也，今志人所短，忘人所長，而求得賢乎天下，則難矣。","sortOrder":13},
  {"id":"s_work_nvlt_83_14","chapterId":"ch_work_nvlt_83","text":"謝承《漢書》曰：鄹人王逢，得路遺寶物，懸衢道，求主還。","sortOrder":14},
  {"id":"s_work_nvlt_83_15","chapterId":"ch_work_nvlt_83","text":"晉安帝紀曰：桓玄尤愛珍寶，常玩弄珠玉，不離於手。","sortOrder":15},
  {"id":"s_work_nvlt_83_16","chapterId":"ch_work_nvlt_83","text":"《地鏡圖》曰：凡觀金玉寶劍銅鐵，皆以辛之日，待雨止，明日平旦，亦黃昏夜半觀之，所見光白者玉也，赤者金，黃者銅，黑者鐵。","sortOrder":16},
  {"id":"s_work_nvlt_83_18","chapterId":"ch_work_nvlt_83","text":"《爾雅》曰：黃金謂之荡，［荡音。］其美者謂之鎦，［留音。］","sortOrder":18},
  {"id":"s_work_nvlt_83_19","chapterId":"ch_work_nvlt_83","text":"尚書洪范，五行，四曰金，金曰從革，從革作辛，［孔安國，金可改庚，辛，金氣也。］《穆天子傳》曰：披圖视天子之寶，黃金之膏。","sortOrder":19},
  {"id":"s_work_nvlt_83_20","chapterId":"ch_work_nvlt_83","text":"《晏子》曰：景公為履，黃金之綦。","sortOrder":20},
  {"id":"s_work_nvlt_83_21","chapterId":"ch_work_nvlt_83","text":"《孝經援神契》曰：石润苞玉，丹精生金，翠羽扬也，［三物合和氣，故能变通易色也。］","sortOrder":21},
  {"id":"s_work_nvlt_83_22","chapterId":"ch_work_nvlt_83","text":"又曰：四夷賓服，則金勝土。","sortOrder":22},
  {"id":"s_work_nvlt_83_23","chapterId":"ch_work_nvlt_83","text":"孫氏《瑞應圖》曰：王者不藏金玉，則黃金見深山。","sortOrder":23},
  {"id":"s_work_nvlt_83_24","chapterId":"ch_work_nvlt_83","text":"《禮斗威儀》曰：君乘金而王，其政平，則黃金見深山。","sortOrder":24},
  {"id":"s_work_nvlt_83_25","chapterId":"ch_work_nvlt_83","text":"《列子》曰：齊人有欲金者，清旦衣冠之市，適鬻金者之所，因攫其金而去，吏捕之，問曰：人皆在焉，子攫人之金何故，對曰：取金之時，不見人，徒見金。","sortOrder":25},
  {"id":"s_work_nvlt_83_26","chapterId":"ch_work_nvlt_83","text":"魯連子曰：秦師围趙而退，平原君以千金欲為魯連先生寿，連笑曰：所貴天下士者，為人釋難，解人締結，若即有取，商贾之事，連不忍為也。","sortOrder":26},
  {"id":"s_work_nvlt_83_27","chapterId":"ch_work_nvlt_83","text":"《韓子》曰：荆南麗水之中生金。","sortOrder":27},
  {"id":"s_work_nvlt_83_28","chapterId":"ch_work_nvlt_83","text":"《燕丹子》曰：太子自喜得荆軻，永無忧秦，後日與軻之東宮，臨池而觀，軻拾瓦投蛙，太子令人奉盤金，軻用祇，［《太平御覽》四百七十五作抵。］賜金复進，軻曰：非為太子愛金也，但臂痛耳。","sortOrder":28},
  {"id":"s_work_nvlt_83_29","chapterId":"ch_work_nvlt_83","text":"《史記》曰：秦獻公十八年，雨金櫟陽，公自以得金瑞，故作畦畤於櫟陽，祀白帝。","sortOrder":29},
  {"id":"s_work_nvlt_83_30","chapterId":"ch_work_nvlt_83","text":"又曰：秦始皇葬於驪山，以黃金為凫雁。","sortOrder":30},
  {"id":"s_work_nvlt_83_31","chapterId":"ch_work_nvlt_83","text":"《韓詩外傳》曰：楚襄王遣使者，持金千片，白璧百双，聘莊子，欲以為相，莊固辭而不許，使者曰：黃金白璧，寶之至也，卿相尊位也，先生辭不受何也。","sortOrder":31},
  {"id":"s_work_nvlt_83_32","chapterId":"ch_work_nvlt_83","text":"《吳越春秋》曰：延陵季子出遊於齊，見路有遺金，有披裘采薪者，季呼薪者，取彼地金，薪者曰：吾當夏五月，披裘而薪，豈取金者哉。","sortOrder":32},
  {"id":"s_work_nvlt_83_33","chapterId":"ch_work_nvlt_83","text":"《列仙傳》曰：安期先生，始皇請見之，賜金璧數千萬。","sortOrder":33},
  {"id":"s_work_nvlt_83_34","chapterId":"ch_work_nvlt_83","text":"《列女傳》曰：秋胡子既宦於陳，五年乃歸，未至，見路傍有一美婦人，方采桑，秋胡子下車謂之曰：吾有金，原與夫人，婦笑曰：嘻，夫采桑以作，紡績經織，以供衣食，奉二親，養夫子而已矣，吾不原人之金。","sortOrder":34},
  {"id":"s_work_nvlt_83_35","chapterId":"ch_work_nvlt_83","text":"《漢書》曰：武帝行幸回中，詔曰：往者朕郊見上帝，泰山見金，宜更黃金為麟趾褭蹄，以协瑞焉，［獲白麟有瑞，故鑄金如麟馬，以协嘉祉也，古有駿馬，名腰褭，赤喙黑身，日行萬五千里也。］","sortOrder":35},
  {"id":"s_work_nvlt_83_36","chapterId":"ch_work_nvlt_83","text":"又曰：梁孝王未死時，金以巨萬計，不可勝數，及死，藏府餘黃金，尚四十餘萬斤，他财物稱是。","sortOrder":36},
  {"id":"s_work_nvlt_83_37","chapterId":"ch_work_nvlt_83","text":"又曰：季布為任俠，有名，楚人諺曰：得黃金百斤，不如得季布一诺。","sortOrder":37},
  {"id":"s_work_nvlt_83_38","chapterId":"ch_work_nvlt_83","text":"又曰：直不疑為郎，事文帝，其同舍有告歸者，誤持同舍郎金，主覺亡，意不疑，不疑謝之，買金偿之，後告歸者來而歸金，前郎亡金者大慚。","sortOrder":38},
  {"id":"s_work_nvlt_83_39","chapterId":"ch_work_nvlt_83","text":"又曰：韦賢傳曰：鄹魯諺雲，遺子黃金滿籝，不如教子一經。","sortOrder":39},
  {"id":"s_work_nvlt_83_40","chapterId":"ch_work_nvlt_83","text":"又曰：疏廣徙為太傅，頃之，兄子受為少傅，父子併為師傅，俱乞骸骨，上以其年老，皆許之，加賜黃金二十斤，皇太子赠以五十斤。","sortOrder":40},
  {"id":"s_work_nvlt_83_41","chapterId":"ch_work_nvlt_83","text":"又曰：秦幣，黃金方寸而重一斤，以镒為名，《漢武故事》曰：帝年數歲，長公主遍指侍者曰：與子作婦，好否，皆不用，後指陳後，帝曰：若得阿娇，當作金屋貯之。","sortOrder":41},
  {"id":"s_work_nvlt_83_42","chapterId":"ch_work_nvlt_83","text":"《續漢書》曰：扬震為東萊太守，道經昌邑，初震為荆州，舉茂才王密，密時為昌邑令，謁見，至夜，懷金十斤以遺震，震曰：故人知君，君不知故人何也，密曰：暮夜無知者，震曰：天知神知，子知我知，何謂無知，密愧而出。","sortOrder":42},
  {"id":"s_work_nvlt_83_43","chapterId":"ch_work_nvlt_83","text":"《庐江七賢傳》曰：陳翼到藍乡，見道邊有馬，傍有一病人，呼曰：我長安魏公卿，聞庐江樂來遊，今病不能前，翼迎歸養之，病困，曰：有金十餅，素二十匹，死則賣以殯斂，餘謝主人，既死，翼賣素買棺衣衾，以金置棺下，騎馬出入，後其兄長公見馬，告吏捕翼，翼具言之，棺下得金，長公叩頭謝，以金十餅投其門中，翼送長安還之，翼後為魯陽尉，號魯陽金行。","sortOrder":43},
  {"id":"s_work_nvlt_83_44","chapterId":"ch_work_nvlt_83","text":"《漢書》曰：王陽好車馬衣服，及遷徙，其載不過囊衣，不畜餘财，天下服其廉而怪其奢，故風俗傳雲，王陽能作黃金。","sortOrder":44},
  {"id":"s_work_nvlt_83_45","chapterId":"ch_work_nvlt_83","text":"邴原別傳曰：原以丧亂方炽，遂到遼東，時同郡劉攀，亦俱在焉，遼東人圖奪太守公孫度，度覺之，捕其家，而攀得免，度曰：有藏劉攀，同誅，攀窘逼，歸原，曰：窮鳥入懷，原曰：焉知斯懷之可入，遂匿之月餘，東萊太守太史子義，素有義節，原欲以攀付之，攀臨去，以其手所杖劍金三餅與原，原受金辭劍，還謂度曰：將軍平日與攀無郄，而欲殺之者，但恐其為蜂蠆耳，今攀以去，而尚拘閉其家，以情推之，其念為毒螫，必滋甚矣，度從之，即出攀家，原以金還之。","sortOrder":45},
  {"id":"s_work_nvlt_83_46","chapterId":"ch_work_nvlt_83","text":"曹操別傳曰：操別入碭，發梁孝王冢，破棺，收金寶數萬斤，天子聞之哀泣。","sortOrder":46},
  {"id":"s_work_nvlt_83_47","chapterId":"ch_work_nvlt_83","text":"《英雄記》曰：董卓坞有金二三萬斤。","sortOrder":47},
  {"id":"s_work_nvlt_83_48","chapterId":"ch_work_nvlt_83","text":"《益部耆舊傳》曰：王忳詣師，於客舍，見諸生病甚困，謂忳雲，腰下有金十斤，原以相與，收藏尸骸，未問姓名而絕，忳賣金一斤，以給棺殓，九斤置生腰下，後署太度亭長，到亭日，有大馬一匹入亭中，其日大風，有一繡被隨風而來，後乘馬突入金彦門，彦父見曰：真盜矣，忳說状。又取被示之，怅然曰：此我子也，以被馬歸彦父，彦父不受，遣迎彦丧，金具存。","sortOrder":48},
  {"id":"s_work_nvlt_83_49","chapterId":"ch_work_nvlt_83","text":"《錄異傳》曰：隗炤者，汝陰鸿寿亭民，善於易，臨終，書板授其妻曰：吾亡後，當大荒窮，雖爾，而慎莫賣宅也，到後五年春，當有詔使來頓此亭，姓龚，此人負吾金，卿以此板往责之，勿违言也，亡後果大困，欲賣宅者數矣，憶夫言辄止，到期日，有龚使者果上亭中，妻遂赍板往责使者，使者執板不知所言，曰：我平生不踐此，何緣爾耶，使者沉吟良久，謂曰：賢夫何能，妻曰：夫善易，而未嘗為人卜，使者曰：可知矣，乃顧命侍者，取蓍而筮之，卦成，扺掌叹曰：妙哉隗炤生，含明隱跡，而莫之聞，可謂鏡窮達而洞吉凶者也，於是告炤妻曰：吾不相負金，賢夫自有金，乃知亡後當蹔窮，故藏金以待泰平，所以不告兒婦者，恐金盡而困無已也，吾善易，故書板以寄意耶，金有五百斤，盛以青甒，覆以銅柈，埋在堂屋東頭，去壁一丈，入地九尺，妻還掘之，皆如卜焉，《搜神記》曰：郭巨兄弟三人，早丧父，禮畢，二弟求分，以錢二千萬，二弟各取千萬，巨獨與母出居客舍，夫婦佣賃，以給供養，居有頃，妻產男，巨念與兒妨事親［按親下疑脱一字。］也，老人得食，憙分兒孫，减饌二也，乃於野凿地，欲埋兒，得石蓋，下有金一釜，中有丹書曰：孝子郭巨，黃金一釜，以用賜汝，於是名振天下。","sortOrder":49},
  {"id":"s_work_nvlt_83_50","chapterId":"ch_work_nvlt_83","text":"《世說》曰：管寧華歆，鋤菜見金，管揮鋤與瓦石不異，華提而掷去。","sortOrder":50},
  {"id":"s_work_nvlt_83_51","chapterId":"ch_work_nvlt_83","text":"《異物志》曰：狼〈月荒〉民與漢人交關，常夜為市，以鼻嗅金，知其好惡。","sortOrder":51},
  {"id":"s_work_nvlt_83_52","chapterId":"ch_work_nvlt_83","text":"扶南傳曰：毗騫國食器，皆以金為之。","sortOrder":52},
  {"id":"s_work_nvlt_83_53","chapterId":"ch_work_nvlt_83","text":"《幽明錄》曰：淮牛渚津水極深，無可筭計，人見一金牛，形甚瑰壮，以金為鎖绊。","sortOrder":53},
  {"id":"s_work_nvlt_83_54","chapterId":"ch_work_nvlt_83","text":"又曰：巴丘縣自金岗以上二十里，名黃金潭，莫测其深，上有瀨，亦名黃金瀨，古有釣於此潭，獲一金鎖，引之，遂滿一舡，有金牛出，聲奔壮，釣人波駭，牛因奋勇，躍而還潭，鎖將乃盡，釣人以刀斫得數尺，潭瀨因此取名。","sortOrder":54},
  {"id":"s_work_nvlt_83_55","chapterId":"ch_work_nvlt_83","text":"《異苑》曰：永康王曠，井上有一洗石，時見赤氣，後有二胡人寄宿，忽求買之，未及度錢，子婦孫氏，睹二黃鳥斗於石上，疾往掩取，变成黃金。","sortOrder":55},
  {"id":"s_work_nvlt_83_57","chapterId":"ch_work_nvlt_83","text":"《爾雅》曰：白金謂之銀，其美者謂之鐐，［遼。］","sortOrder":57},
  {"id":"s_work_nvlt_83_58","chapterId":"ch_work_nvlt_83","text":"《史記·封禪書》曰：殷得金德，銀自山溢。","sortOrder":58},
  {"id":"s_work_nvlt_83_59","chapterId":"ch_work_nvlt_83","text":"《漢書》曰：益州榼町山出銀，贲古亦出銀。","sortOrder":59},
  {"id":"s_work_nvlt_83_60","chapterId":"ch_work_nvlt_83","text":"又曰：無雷國出銀。","sortOrder":60},
  {"id":"s_work_nvlt_83_61","chapterId":"ch_work_nvlt_83","text":"又曰：黃金一斤，直錢萬，朱提銀八兩為流，直一千五百八十，他銀一流，直千，是為銀货二品。","sortOrder":61},
  {"id":"s_work_nvlt_83_62","chapterId":"ch_work_nvlt_83","text":"東方朔《神異經》曰：西南有銀山焉，長五十餘里，廣四五里，高百餘丈，皆悉白金，不雜土石，不生草木。","sortOrder":62},
  {"id":"s_work_nvlt_83_63","chapterId":"ch_work_nvlt_83","text":"列異記曰：故司隸校尉上党鮑子都，少時上計掾，於道中遇一書生，獨行無伴，卒得心痛，子都下車為按摩，奄忽亡，不知姓名，有素書一卷，銀十餅，即賣一餅以殯斂，餘銀以坑之，素書著腹上，哭之，謂曰：若子魂靈有智，當令子家知子在此，今奉使命，不獲久留，遂辭而去，《抱朴子》曰：銀但不及金玉，餌可以地仙。","sortOrder":63},
  {"id":"s_work_nvlt_83_64","chapterId":"ch_work_nvlt_83","text":"《南越志》曰：遂成縣任山，有銀大銀山，［《太平御覽》八百十二作銀沙自出。］","sortOrder":64},
  {"id":"s_work_nvlt_83_65","chapterId":"ch_work_nvlt_83","text":"《地鏡圖》曰：銀之氣，夜正白，流散在地，拨之隨手散复合，此是也，山有葱，下有銀，光隱隱正白，山有磁石，下有銅若金。","sortOrder":65},
  {"id":"s_work_nvlt_83_66","chapterId":"ch_work_nvlt_83","text":"又曰：白銀見為雄雞。","sortOrder":66},
  {"id":"s_work_nvlt_83_67","chapterId":"ch_work_nvlt_83","text":"【贊】晉郭璞金銀贊曰：惟金三品，扬越作貢，五材之珍，是謂國用，務經軍農，爰及雕弄。","sortOrder":67},
  {"id":"s_work_nvlt_83_68","chapterId":"ch_work_nvlt_83","text":"◇玉《爾雅》曰：西方之美者，霍山之珠玉焉。","sortOrder":68},
  {"id":"s_work_nvlt_83_69","chapterId":"ch_work_nvlt_83","text":"又曰：璆，美玉也，治玉謂之琢，亦謂之雕。","sortOrder":69},
  {"id":"s_work_nvlt_83_70","chapterId":"ch_work_nvlt_83","text":"《廣志》曰：白玉美者，可以照面，出交州，青玉出倭國，赤玉出夫餘，瑜玉玄玉水蒼玉皆佩用。","sortOrder":70},
  {"id":"s_work_nvlt_83_71","chapterId":"ch_work_nvlt_83","text":"《尚書》曰：惟辟玉食。","sortOrder":71},
  {"id":"s_work_nvlt_83_72","chapterId":"ch_work_nvlt_83","text":"《山海經》曰：黃帝乃取密之玉榮，而投鍾山之陰陽，瑾瑜之玉，润泽而有光，五色發作，以和景周，［《太平御覽》八百零五作柔刚。］天地鬼神，是食是饗，君子服之，以御不祥。","sortOrder":72},
  {"id":"s_work_nvlt_83_73","chapterId":"ch_work_nvlt_83","text":"《周官》曰：以玉作六器，以禮天地四方，以蒼璧禮天，以黃琮禮地，以青珪禮東方，以赤璋禮南方，以白琥禮西方，以玄璜禮北方。","sortOrder":73},
  {"id":"s_work_nvlt_83_74","chapterId":"ch_work_nvlt_83","text":"《禮記》曰：笏天子以球玉。","sortOrder":74},
  {"id":"s_work_nvlt_83_75","chapterId":"ch_work_nvlt_83","text":"又曰：執玉爵者不揮。","sortOrder":75},
  {"id":"s_work_nvlt_83_76","chapterId":"ch_work_nvlt_83","text":"又曰：受珠玉者以掬。","sortOrder":76},
  {"id":"s_work_nvlt_83_77","chapterId":"ch_work_nvlt_83","text":"又曰：玉不琢，不成器，人不學，不知道。","sortOrder":77},
  {"id":"s_work_nvlt_83_78","chapterId":"ch_work_nvlt_83","text":"又曰：子貢問於孔子曰：敢問君子貴玉而賤珉何也，為玉之寡而珉之多耶，子曰：昔君子比德於玉焉，溫润而泽，仁也，縝密而栗，知也，廉而不刿，義也，垂之如墜，禮也，叩之，其聲清越以長，其終诎然，樂也，瑕不掩瑜，瑜不掩瑕，忠也，孚尹旁達，信也，氣若白虹，天也，精神見於山川，地也，珪璋特達，德也，天下莫不貴者，道也，詩雲，言念君子，溫其如玉，故君子貴之也。","sortOrder":78},
  {"id":"s_work_nvlt_83_79","chapterId":"ch_work_nvlt_83","text":"《大戴禮》曰：玉在山而木润，川生珠而岸不枯，珠者陰中之陽也，故勝水，玉者陽中之陰也，故勝木。","sortOrder":79},
  {"id":"s_work_nvlt_83_80","chapterId":"ch_work_nvlt_83","text":"《左傳》曰：初虞叔有玉，虞公求旃，弗獻，既而悔之曰：周諺有之，匹夫無罪，懷璧其罪，吾焉用此，其以贾害也，乃獻之。","sortOrder":80},
  {"id":"s_work_nvlt_83_81","chapterId":"ch_work_nvlt_83","text":"《禮斗威儀》曰：君乘金而王，則紫玉見於深山，《周書》曰：武王俘商，得寶玉萬四千，佩有八萬。","sortOrder":81},
  {"id":"s_work_nvlt_83_82","chapterId":"ch_work_nvlt_83","text":"《尚書·中候》曰：文王至磻谿，呂尚釣，王趨稱曰：望公七年，今見光景，答曰：望釣得玉璜，刻曰：姬受命，呂佐捡，［捡，相也。］","sortOrder":82},
  {"id":"s_work_nvlt_83_83","chapterId":"ch_work_nvlt_83","text":"《孝經援神契》曰：神靈滋液，則有玉英，［英，華也。］","sortOrder":83},
  {"id":"s_work_nvlt_83_84","chapterId":"ch_work_nvlt_83","text":"《穆天子傳》曰：披圖视典，用觀天子寶器，玉果，［石似美玉，可謂玉果。］璿珠，燭銀黃金之膏，［五玉膏皆有精也。］又曰：天子北征東還，乃循黑水，至於群玉之山，四彻中繩，［皆平直也。］先王之所謂策府。","sortOrder":84},
  {"id":"s_work_nvlt_83_85","chapterId":"ch_work_nvlt_83","text":"《列子》曰：周穆王征西戎，西戎獻崑吾之劍，赤刀，切玉如切泥。","sortOrder":85},
  {"id":"s_work_nvlt_83_86","chapterId":"ch_work_nvlt_83","text":"《孔丛子》曰：秦王得西戎利刀，割玉如割木。","sortOrder":86},
  {"id":"s_work_nvlt_83_87","chapterId":"ch_work_nvlt_83","text":"尹《文子》曰：魏田父有耕於野者，得玉径尺，不知其玉也，以告鄰人，鄰人诈之曰：此怪石也，畜之弗利其家，田父雖疑，猶豫以歸，置於庑下，其玉明照一室，大怖，遽而弃之於遠野，鄰人取之，以獻魏王，魏王召玉工相之，玉工望之，再拜贺曰：大王得天下之寶，臣所未嘗見，王問其价，玉工曰：此無价以當之，五城之都，仅可一觀，魏王賜獻玉者千金，長食上大夫之祿。","sortOrder":87},
  {"id":"s_work_nvlt_83_88","chapterId":"ch_work_nvlt_83","text":"又曰：鄭人謂玉未理者為璞，周人謂鼠未腊者為璞，周人懷璞，問鄭贾曰：欲買璞乎，鄭曰：欲之，出其璞视之，乃鼠也，因謝不取。","sortOrder":88},
  {"id":"s_work_nvlt_83_89","chapterId":"ch_work_nvlt_83","text":"鬼穀子曰：鄭人之取玉也，必載司南之車，為其不惑也。","sortOrder":89},
  {"id":"s_work_nvlt_83_90","chapterId":"ch_work_nvlt_83","text":"紀年曰：桀伐珉山，珉山莊王女於桀二女，曰琬曰琰，桀受二女，無子，斷［《太平御覽》八十二作斫。］其名於苕華之玉，苕是琬，華是琰也。","sortOrder":90},
  {"id":"s_work_nvlt_83_91","chapterId":"ch_work_nvlt_83","text":"《呂氏春秋》曰：人不愛崑山之玉，江漢之珠，而愛己之蒼璧小璣，蒼璧石多玉少。","sortOrder":91},
  {"id":"s_work_nvlt_83_92","chapterId":"ch_work_nvlt_83","text":"珠玉圖曰：璣，碎珠。","sortOrder":92},
  {"id":"s_work_nvlt_83_93","chapterId":"ch_work_nvlt_83","text":"《戰國策》曰：周有砥，宋有結绿，梁有懸犁，楚有和璞，此四寶者，天下名器，獨不足以厚國家乎。","sortOrder":93},
  {"id":"s_work_nvlt_83_94","chapterId":"ch_work_nvlt_83","text":"又曰：蘇秦謂楚王曰：楚國食貴於玉，薪貴於桂，《尚書大傳》曰：尧致舜天下，赠以苕華之玉。","sortOrder":94},
  {"id":"s_work_nvlt_83_95","chapterId":"ch_work_nvlt_83","text":"《春秋繁露》曰：公侯贽用玉，玉润而不汙，至清絜也，故君子比之於玉，玉有瑕秽，必見於外，故君子不隱所短。","sortOrder":95},
  {"id":"s_work_nvlt_83_96","chapterId":"ch_work_nvlt_83","text":"《韓詩外傳》曰：良玉度尺，雖有十仞之土，不能掩其光，良珠度寸，雖有百仞之水，不能掩其辉。","sortOrder":96},
  {"id":"s_work_nvlt_83_97","chapterId":"ch_work_nvlt_83","text":"《淮南子》曰：水圓折者有珠，方折者有玉，［圓，陽也，珠陰中之陽也，方，陰也，玉陽中之陰，皆以其類生也。］","sortOrder":97},
  {"id":"s_work_nvlt_83_98","chapterId":"ch_work_nvlt_83","text":"又曰：崑崙山中有曾城九重，上有珠树玉树。","sortOrder":98},
  {"id":"s_work_nvlt_83_99","chapterId":"ch_work_nvlt_83","text":"又曰：琬琰之玉，在污泥之中，雖廉者釋。","sortOrder":99},
  {"id":"s_work_nvlt_83_100","chapterId":"ch_work_nvlt_83","text":"又曰：譬若鍾山崑崙之玉，炊爐炭，三日三夜而色泽不变，得天地之精也。","sortOrder":100},
  {"id":"s_work_nvlt_83_101","chapterId":"ch_work_nvlt_83","text":"又曰：白玉不雕，美珠不文，质有餘也。","sortOrder":101},
  {"id":"s_work_nvlt_83_102","chapterId":"ch_work_nvlt_83","text":"《十洲記》曰：周穆王時，西胡獻玉杯，是百玉之精，明夜照夕，以杯於庭中，比明旦而水滿於杯中，汁甘而香美，斯靈器也。","sortOrder":102},
  {"id":"s_work_nvlt_83_103","chapterId":"ch_work_nvlt_83","text":"《鹽鐵論》曰：崑山之傍，以玉璞抵乌鵲。","sortOrder":103},
  {"id":"s_work_nvlt_83_104","chapterId":"ch_work_nvlt_83","text":"《列仙傳》曰：赤松子，神農時雨師，服水玉。","sortOrder":104},
  {"id":"s_work_nvlt_83_105","chapterId":"ch_work_nvlt_83","text":"《漢書》曰：宣帝幸河東，鳳皇集，得玉寶，乃起萬寿宮。","sortOrder":105},
  {"id":"s_work_nvlt_83_106","chapterId":"ch_work_nvlt_83","text":"《漢武故事》曰：上起神屋，前庭植玉树，以珊瑚為枝，碧玉為葉，華子青赤，以珠玉為之，空其中如小鈴，鎗鎗有聲。","sortOrder":106},
  {"id":"s_work_nvlt_83_107","chapterId":"ch_work_nvlt_83","text":"《琴操》曰：卞和者，楚野民，得玉獻懷王，懷王使樂正子占之，言玉，［○句有脱文。］王以為欺謾，斬其一足，懷王死，子平王立，和复獻之，平王又以為欺，斬其一足，平王死，子立為荆王，和复欲獻之，恐复見害，乃抱其玉而哭，晝夜不止，涕盡續之以血，荆王遣問之，於是和隨使獻王，王使剖之，中果有玉，乃封和為陵陽侯，卞和辭不就而去，作退怨之歌曰：悠悠沂水經荆山，精氣鬱泱穀巖巖，中有神寶灼明明，穴山采玉難為功，於何獻之楚先王，遇王闇昧信讒言，斷截兩足離餘身，俯仰嗟叹心摧傷，紫之亂朱粉墨同，空山歔欷涕龍鍾，天鑒孔明竟以彰，沂水滂沛流於汶，進寶得刑足離分，斷者不續豈不怨。","sortOrder":107},
  {"id":"s_work_nvlt_83_108","chapterId":"ch_work_nvlt_83","text":"王逸正部論曰：或問玉符，曰：赤如雞冠，黃如蒸栗，白如猪肪，黑如純漆，玉之符也。","sortOrder":108},
  {"id":"s_work_nvlt_83_109","chapterId":"ch_work_nvlt_83","text":"《續漢書》曰：三老五更玉杖。","sortOrder":109},
  {"id":"s_work_nvlt_83_110","chapterId":"ch_work_nvlt_83","text":"又曰：袁逢為三老，賜玉杖。","sortOrder":110},
  {"id":"s_work_nvlt_83_111","chapterId":"ch_work_nvlt_83","text":"《魏略》曰：大秦國出五色玉。","sortOrder":111},
  {"id":"s_work_nvlt_83_112","chapterId":"ch_work_nvlt_83","text":"魏書曰：文帝甄皇後，光和中生，每寢寐，家中仿佛見有人持玉衣覆其上者，常共怪之。","sortOrder":112},
  {"id":"s_work_nvlt_83_113","chapterId":"ch_work_nvlt_83","text":"《文士傳》曰：劉楨嘗預魏文帝坐，見甄後，不伏，武帝大怒，收付作部，使摩石，武帝常輦至尚方，觀作者，見楨，楨摩石不仰，帝問曰：石何如，楨因得喻己自理，跪對曰：石出自荆山，外有五色之章，內含和氏之珍，磨之不加瑩，雕之不增文，禀氣堅貞，受茲自然，顧其理枉屈紆繞，猶不得申，武帝顧左右大笑，赦楨，复署吏。","sortOrder":113},
  {"id":"s_work_nvlt_83_114","chapterId":"ch_work_nvlt_83","text":"胡琮別傳曰：吳時掘地，得銅匣，以琉璃為蓋，布雲母於其上，开之，得白玉如意，大皇帝以問琮，對曰：秦始皇以金陵有天子氣，處處埋寶物以當王土之氣，此抑是乎。","sortOrder":114},
  {"id":"s_work_nvlt_83_115","chapterId":"ch_work_nvlt_83","text":"《神仙傳》曰：沈羲為仙人所迎，見老君，以金桉玉盤賜之。","sortOrder":115},
  {"id":"s_work_nvlt_83_116","chapterId":"ch_work_nvlt_83","text":"《搜神記》曰：羊公雍伯，雒陽人，性篤孝，父母亡，葬無終山，遂家焉．山高無水，公汲作義漿於坂頭，行者皆飲之，三年，有一人就飲，以一斗石子與之，雲玉當生其中。又語雲，後當得以婦，言畢不見，乃种其石，數歲，時時望视，見玉子生石，北平徐氏女，甚有行，人多求不許，公乃试求焉，徐氏笑以為狂，乃戲雲，得白璧一双來，當為婚，公至所种石中，得五双以聘，徐氏遂以女妻之，天子異之，拜為大夫，於种玉處，四角作大石柱，各一丈，中央一頃地，名曰玉田。","sortOrder":116},
  {"id":"s_work_nvlt_83_117","chapterId":"ch_work_nvlt_83","text":"《涼州記》曰：呂慕［本書八十四馬腦篇，《太平御覽》五百八十一作纂。］鹹寧二年，有盜發張駿陵，得白玉樽玉箫玉笛。","sortOrder":117},
  {"id":"s_work_nvlt_83_118","chapterId":"ch_work_nvlt_83","text":"《異苑》曰：晉東瀛王騰镇鄴，遊常山，天時大雪，融液不積，掘得玉馬。","sortOrder":118},
  {"id":"s_work_nvlt_83_119","chapterId":"ch_work_nvlt_83","text":"又曰：弘農楊子陽，聞土中有聲，掘得玉豚，長可尺許，屋棟間仍自漏秫米，如此三年，晝夜不息，米墜既止，忽有一青蛇，長數尺，住在梁上，每落粪，辄成碎銀，子陽獲銀米，遂為富兒，鍛銀作器，货賣倍售，餘家市者，隨以破滅。","sortOrder":119},
  {"id":"s_work_nvlt_83_120","chapterId":"ch_work_nvlt_83","text":"白泽圖曰：玉之精名曰委然，如美女，衣青衣，見之以桃戈刺之，而呼其名，則可得也，夜行見女，戴燭入石，石中有玉也。","sortOrder":120},
  {"id":"s_work_nvlt_83_121","chapterId":"ch_work_nvlt_83","text":"【詩】晉司馬彪詩曰：玉出阆風侧，珠生南海濱，奕奕不周阪，蘇桂扬其芬。","sortOrder":121},
  {"id":"s_work_nvlt_83_122","chapterId":"ch_work_nvlt_83","text":"【賦】晉傅鹹玉賦曰：易稱乾為玉，玉之美與天合德，其在玉藻，仲尼論之備矣，非复鄙文所可稱述，萬物資生，玉禀其精，體乾之刚，配天之清，故能珍嘉在昔，實用罔極，夫豈君子之是比，蓋乃王度之所式，其為美也若此，當其潛光荆野，抱璞未理，眾视之以為石，獨見知於卞子，曠千載以遐弃，倏一旦而見齒，為有國之伟寶，禮神祇於明祀，豈連城之足雲，嘉遭遇乎知己，知己之不可遇，譬河清之難俟，既已若此誰，亦泣血而刖趾。","sortOrder":122},
  {"id":"s_work_nvlt_83_123","chapterId":"ch_work_nvlt_83","text":"【贊】晉庾肅之玉贊曰：圓璧月鏡，璆琳星羅，結秀藍田，辉真荆和，玄珪特達，瑜不掩瑕，质鮮器润，流映滂沱。","sortOrder":123},
  {"id":"s_work_nvlt_83_124","chapterId":"ch_work_nvlt_83","text":"郭璞瑾瑜玉贊曰：鍾山之寶，爰有玉華，光采流映，氣如虹霞，君子是佩，象德閒邪。","sortOrder":124},
  {"id":"s_work_nvlt_83_126","chapterId":"ch_work_nvlt_83","text":"《說文》曰：玠，大珪也，珽，大珪也，長三尺，抒上終葵首。","sortOrder":126},
  {"id":"s_work_nvlt_83_127","chapterId":"ch_work_nvlt_83","text":"《爾雅》曰：珪大尺二寸謂之玠。","sortOrder":127},
  {"id":"s_work_nvlt_83_128","chapterId":"ch_work_nvlt_83","text":"《白虎通》曰：珪以為信而見何也，珪者銳上，象物始生見於上也，信莫著於見，故以之，萬物之始，莫不自絜，珪之為言珪也，上銳陽也，下方陰也。","sortOrder":128},
  {"id":"s_work_nvlt_83_129","chapterId":"ch_work_nvlt_83","text":"《山海經》曰：羭山之神，祠之白圭。","sortOrder":129},
  {"id":"s_work_nvlt_83_130","chapterId":"ch_work_nvlt_83","text":"《易》曰：告公用圭。","sortOrder":130},
  {"id":"s_work_nvlt_83_131","chapterId":"ch_work_nvlt_83","text":"尚書，禹貢曰：禹錫玄圭，告厥成功，［玄，天色，禹功聞於四海，故尧錫玄圭，以旌顯之。］","sortOrder":131},
  {"id":"s_work_nvlt_83_132","chapterId":"ch_work_nvlt_83","text":"周官禮曰：以玉作六瑞，以等邦國，王晉大圭，執镇圭，繅藉五采五就，以朝日，［繅有五采文，所以荐玉，木為中幹，用韦衣而畫之，就，成也，王朝日者，示有所尊，訓民事君也，大圭長三赤，杼上終葵首，镇圭長赤有二寸，謂安镇四方，以四镇之山為琢飾。］公執桓圭，［二王之後，及王之上公，双植曰桓，宮室之象，所以安其上也，圭長九寸。］侯執信圭，伯執躬圭，繅皆三采三就，［皆象以人形為瑑飾，義取其慎行以保身，圭皆長七寸。］子執穀璧，男執蒲璧，繅皆二采再就，［義取安養於人，二玉或以穀或蒲文為瑑飾，璧皆径五寸。］四圭有邸，以祀天，旅上帝，［為於中央為璧，圭著四面，一玉俱成，邸，本也，圭本著於璧，圭末四出故也。］圭璧以祀日月星辰，青圭禮東方，穀圭天子以娉女，［穀，善也，其娉女則以納徵。］琬圭以治德結好，琰圭以易行除慝，［有鋒芒，併征伐誅讨之象。］土圭以致四時，［以度景致日，長五寸。］瑑圭以覜聘，牙璋以起軍治兵，［若今以銅虎符發兵。］","sortOrder":132},
  {"id":"s_work_nvlt_83_133","chapterId":"ch_work_nvlt_83","text":"《禮記》曰：諸侯以龟為寶，以圭為瑞，家不寶龟，不藏圭。","sortOrder":133},
  {"id":"s_work_nvlt_83_134","chapterId":"ch_work_nvlt_83","text":"又曰：禮有以素為貴者，大圭不瑑，［大圭長三尺，抒上終葵首。］","sortOrder":134},
  {"id":"s_work_nvlt_83_135","chapterId":"ch_work_nvlt_83","text":"又曰：大夫執圭而使，所以申信也，《毛詩》：白圭之玷，尚可磨也，斯言之玷，不可為也。","sortOrder":135},
  {"id":"s_work_nvlt_83_136","chapterId":"ch_work_nvlt_83","text":"《左傳》曰：鄭驷帶伐伯有，伯有死，遊吉如晉還，聞難不入，八月奔晉，驷帶追之，及酸棗，與子上盟，而用珪质於河，已复歸。","sortOrder":136},
  {"id":"s_work_nvlt_83_137","chapterId":"ch_work_nvlt_83","text":"又曰：王子朝用成周之寶珪於河，津人得諸河上，陰不佞以溫之人南，［不佞，敬王大夫，晉以溫兵助敬王南侵子朝也。］拘得玉者，取其賣之，則為石，王定而獻之。","sortOrder":137},
  {"id":"s_work_nvlt_83_138","chapterId":"ch_work_nvlt_83","text":"《論語》曰：執圭，鞠躬如也，如不勝。","sortOrder":138},
  {"id":"s_work_nvlt_83_139","chapterId":"ch_work_nvlt_83","text":"《穆天子傳》曰：天子賓於西王母，［如人，蓬發戴勝，善嘯。］乃執白珪玄璧，以見西王母。","sortOrder":139},
  {"id":"s_work_nvlt_83_140","chapterId":"ch_work_nvlt_83","text":"《墨子》曰：申徒狹［《太平御覽》八百零六作狄。］曰：周之靈珪，出於土石，楚之明月，出於蚌蜃。","sortOrder":140},
  {"id":"s_work_nvlt_83_141","chapterId":"ch_work_nvlt_83","text":"《莊子》曰：楚昭王延屠羊以三珪之位，［諸侯上卿皆執圭。］","sortOrder":141},
  {"id":"s_work_nvlt_83_142","chapterId":"ch_work_nvlt_83","text":"《楚詞》曰：接径千里出若雲，［言楚國境界，任路交接，方千餘里，中有隱士，暮已來出，集聚若雲也。］三珪重侯［三圭，公侯伯。］聽類神，察篤夭隱孤寡存。［言三圭之君，不但知賢愚之類，亦察知篤疾早夭孤寡，振贍乏。］","sortOrder":142},
  {"id":"s_work_nvlt_83_143","chapterId":"ch_work_nvlt_83","text":"《古今註》曰：章帝建初七年，玉珪出弘農華陰。","sortOrder":143},
  {"id":"s_work_nvlt_83_144","chapterId":"ch_work_nvlt_83","text":"【贊】晉郭璞珪贊曰：玉作五瑞，辯章有國，君子鳴佩，亦以表德，永觀厥祭，時惟文則。","sortOrder":144},
  {"id":"s_work_nvlt_83_145","chapterId":"ch_work_nvlt_83","text":"《藝文類聚》　唐·欧陽詢","sortOrder":145},
  {"id":"s_work_nvlt_84_1","chapterId":"ch_work_nvlt_84","text":"卷八十四寶玉部下","sortOrder":1},
  {"id":"s_work_nvlt_84_2","chapterId":"ch_work_nvlt_84","text":"○璧珠貝馬瑙琉璃車渠玳瑁銅","sortOrder":2},
  {"id":"s_work_nvlt_84_4","chapterId":"ch_work_nvlt_84","text":"《白虎通》曰：方中圓外曰璧，璧之為言積也，內方象地，外圓象天。","sortOrder":4},
  {"id":"s_work_nvlt_84_5","chapterId":"ch_work_nvlt_84","text":"《爾雅》曰：璧大六寸謂之瑄，肉倍好謂之璧，好倍肉謂之瑗，肉好若一謂之環。","sortOrder":5},
  {"id":"s_work_nvlt_84_6","chapterId":"ch_work_nvlt_84","text":"《尚書·中候》曰：尧沉璧於河。","sortOrder":6},
  {"id":"s_work_nvlt_84_7","chapterId":"ch_work_nvlt_84","text":"《周官禮》曰：子執穀璧，男執蒲璧，以蒼璧禮天。","sortOrder":7},
  {"id":"s_work_nvlt_84_8","chapterId":"ch_work_nvlt_84","text":"《左傳》曰：周諺有之，匹夫無罪，懷璧其罪。","sortOrder":8},
  {"id":"s_work_nvlt_84_9","chapterId":"ch_work_nvlt_84","text":"又曰：晉荀息請以垂棘之璧假道於虞，以伐虢。","sortOrder":9},
  {"id":"s_work_nvlt_84_10","chapterId":"ch_work_nvlt_84","text":"又曰：初衛莊公自城上見己氏之妻發美，使髧之，以為呂薑髢，既出奔而入焉，示之璧，曰：活我，吾與汝璧，己氏曰：殺汝，璧其焉往，遂殺之，而取其璧。","sortOrder":10},
  {"id":"s_work_nvlt_84_11","chapterId":"ch_work_nvlt_84","text":"又曰：秋楚子围許，蔡穆侯將許僖公以見楚子於武城，許男面縛衔璧，大夫縗绖，士舆榇，楚子問諸逢伯，對曰：昔武王克殷，微子啟如是，武王親釋其縛，受其璧而祓之，［祓，除凶之禮也。］","sortOrder":11},
  {"id":"s_work_nvlt_84_12","chapterId":"ch_work_nvlt_84","text":"又曰：初楚恭王無冢適，有寵子五人，無適立焉，乃有大事於群望，而祈請神擇於五人者，使主社稷，乃遍以璧見於群望曰：當璧而拜者，神所立也，乃埋璧於太室之庭，使五人斋而長入拜，康王跨之，靈王肘加焉，平王弱，抱而入，再拜皆壓紐。","sortOrder":12},
  {"id":"s_work_nvlt_84_13","chapterId":"ch_work_nvlt_84","text":"《穆天子傳》曰：天子賓於西王母，乃執白珪璧以見之。","sortOrder":13},
  {"id":"s_work_nvlt_84_14","chapterId":"ch_work_nvlt_84","text":"《莊子》曰：孔子問子桑雩曰：吾見逐於魯，伐树於宋，親交益疏何也，對曰：子獨不聞假之亡與，［假，國名也。］林回弃千金之璧，負赤子而趨，彼以利合者，迫窮相弃也，天屬者，迫窮相收也，《孫卿子》曰：聘人以珪，問士以璧。","sortOrder":14},
  {"id":"s_work_nvlt_84_15","chapterId":"ch_work_nvlt_84","text":"《呂氏春秋》曰：魯郄成子聘於晉，過衛，右宰穀臣觴之，陳樂而不樂，乃送之以璧，成子曰：觴我以酒，懽我也，陳樂不樂，告我忧也，送我以璧，寄讬之也，衛其有亂乎，背衛三十里，聞甯殖之難作，右宰穀臣死之，乃使人迎其妻子，隔宅居之，分祿食之，其子長而反其璧。","sortOrder":15},
  {"id":"s_work_nvlt_84_16","chapterId":"ch_work_nvlt_84","text":"《戰國策》曰：齊欲伐魏，魏使謂淳於髡曰：弊邑有寶璧二双，文馬二驷，請致之，髡入請說齊王曰：魏，齊之與國也，伐之名丑而實危，齊王乃止，客謂齊王曰：髡受魏璧馬，王問髡曰：先生有諸乎，曰：有之，伐魏之事便魏，雖刺髡，於王何益，若誠不便，魏雖封臣，於王何損，百姓無被兵之患，髡有璧馬之寶，於王何傷。","sortOrder":16},
  {"id":"s_work_nvlt_84_17","chapterId":"ch_work_nvlt_84","text":"又曰：張儀為秦破從連橫，說楚王，楚王遣使車百乘，獻夜光之璧。","sortOrder":17},
  {"id":"s_work_nvlt_84_18","chapterId":"ch_work_nvlt_84","text":"《史記》曰：張儀嘗從楚相飲，已而楚相亡璧，門下意儀，掠笞不服，儀謂妻曰：视吾舌存否，妻曰：存，曰：足矣。","sortOrder":18},
  {"id":"s_work_nvlt_84_19","chapterId":"ch_work_nvlt_84","text":"又曰：虞卿躡屩簷簦，一見趙王，賜白璧一双，黃金百镒。","sortOrder":19},
  {"id":"s_work_nvlt_84_20","chapterId":"ch_work_nvlt_84","text":"又曰：趙惠王得楚和氏璧，秦昭王聞之，使人遺王書曰：原以十五城，請易璧，王召見蔺相如，遂遣奉璧西入秦，秦王大喜，相如视秦王無意偿趙城，乃前曰：璧有瑕，請指示王，王授璧，相如因持璧却立倚柱，怒發上冲冠，謂秦王曰：趙王斋戒五日，使臣奉璧，今大王見臣甚倨，得璧傳之美人，以為戲弄，無偿趙王城色，故臣复取璧，王必欲急臣，臣頭與璧俱碎於柱矣，王恐其破璧，乃辭謝，固請舍相如廣成傳，相如使人從他道，以璧還趙。","sortOrder":20},
  {"id":"s_work_nvlt_84_21","chapterId":"ch_work_nvlt_84","text":"《韓詩外傳》曰：楚襄王遣使持金十斤，白璧百双，聘莊子以為相，莊子固辭。","sortOrder":21},
  {"id":"s_work_nvlt_84_22","chapterId":"ch_work_nvlt_84","text":"《列士傳》曰：秦召魏公子無忌，無忌不行，使朱亥奉璧一双，秦王大怒，將朱亥著猛獸圈中，亥瞋目视之，眦裂血出，溅猛獸，猛獸終不敢動。","sortOrder":22},
  {"id":"s_work_nvlt_84_23","chapterId":"ch_work_nvlt_84","text":"《漢書》曰：沛公見項羽鸿門，步從間道走去軍，使張良留謝羽，羽問沛公安在，良曰：聞將軍有意咎過之，脱身去，間至軍矣，［脱身逃還其軍。］故使臣獻璧，羽受之。","sortOrder":23},
  {"id":"s_work_nvlt_84_24","chapterId":"ch_work_nvlt_84","text":"《東觀漢記》曰：驃騎將軍東平王蒼，辟朱暉為掾，正月旦，將軍當奉璧贺，故事，少府給璧，時陰就為少府，吏甚驕慢，求不可得，暉遙見就主簿持璧，謂曰：我數聞璧，未嘗見，借觀之，主簿授暉，暉授令使，主簿遽白，就曰：朱掾義士，勿求之，蒼罢朝，謂暉曰：掾自视孰與蔺相如。","sortOrder":24},
  {"id":"s_work_nvlt_84_25","chapterId":"ch_work_nvlt_84","text":"《續漢書》曰：大秦國有夜光璧。","sortOrder":25},
  {"id":"s_work_nvlt_84_26","chapterId":"ch_work_nvlt_84","text":"《鍾離意傳》曰：意為魯相，省视孔子授堂，男子張伯刬草階下，土中得璧七枚，懷藏其一，以六白意，意曰：瓮中素書文曰：後世脩吾書，董仲舒，璧有七，張伯取其一，意召問之，伯叩頭出之。","sortOrder":26},
  {"id":"s_work_nvlt_84_27","chapterId":"ch_work_nvlt_84","text":"《物理論》曰：語曰：士非玉璧，談者為价。","sortOrder":27},
  {"id":"s_work_nvlt_84_28","chapterId":"ch_work_nvlt_84","text":"《抱朴子》曰：安期生賣藥海邊，始皇異之，賜以金璧，直數千萬，安期生去而置之於阜乡亭，以赤玉菭為報，留書曰：後千歲，求我於蓬萊山。","sortOrder":28},
  {"id":"s_work_nvlt_84_29","chapterId":"ch_work_nvlt_84","text":"又曰：餘聞唐尧之為君也，捐金於山，虞舜之承禪也，抵璧於穀。","sortOrder":29},
  {"id":"s_work_nvlt_84_30","chapterId":"ch_work_nvlt_84","text":"中興徵祥說曰：王者不隱過則玉璧見。","sortOrder":30},
  {"id":"s_work_nvlt_84_31","chapterId":"ch_work_nvlt_84","text":"戴延之《西征記》曰：宋公谘議參軍王智先，停柏穀，遣騎送道人惠義疏雲，有金璧之瑞，公遣迎取，軍進次於崤東，金璧至，脩壇拜受之。","sortOrder":31},
  {"id":"s_work_nvlt_84_32","chapterId":"ch_work_nvlt_84","text":"又雲，冀州博陵郡王次寺道人法稱，告其弟子普嚴曰：嵩高皇帝語吾，言江東有劉將軍，是漢家苗裔，受天命，吾以三十二璧金一餅與之，璧數是劉氏卜世之數也，惠義以義熙十三年入嵩高山，即得璧金獻焉。","sortOrder":32},
  {"id":"s_work_nvlt_84_33","chapterId":"ch_work_nvlt_84","text":"【表】魏陳王曹植獻璧表曰：臣聞玉不隱瑕，臣不隱情，伏知所進非和氏之璞，萬國之幣，璧為元貢。","sortOrder":33},
  {"id":"s_work_nvlt_84_34","chapterId":"ch_work_nvlt_84","text":"梁范筠謝示璧表曰：非郊禋有日，禮天之寶胥降，學校且興，圓水之符已集，絳玉玄珪，未足雲譬。","sortOrder":34},
  {"id":"s_work_nvlt_84_35","chapterId":"ch_work_nvlt_84","text":"【檄】梁吳筠檄江神责周穆王璧曰：昔穆王南巡，自郢徂閩，遺我文璧，佥曰此津，貫緯百紀，荐歷千春，念茲文璧，故問水濱，江漢勖之，自求多益，反我名瑞，躍此華璧，則富有漢川，世為江伯，如有負秽心迷，懷衅情戚，藏玉泥中，匿珪魚腹，使公孫躡波而長呼，子羽濟川而怒目，佽飛舞劍而東臨，菑丘躍馬而南逐，打素蛤而為粉，碎紫貝其如粥。又有川人勇俊，處乎閩濮，水居百里，泥行萬宿，右睨而河傾，左咤而海覆，乃把崑吾之銅，純鈞之鐵，被魚鱗之衣，赴螺蚌之穴，引澍東隅，移燋北島，使蓬萊之根，鬱而生尘，瀛洲之足，净而可扫，按驪龍取其頷下之珠，搦鯨魚拔其眼中之寶，皇恩所被，繁枯润涸，威之所加，窮河絕漠，原子三思，反此明玉。","sortOrder":35},
  {"id":"s_work_nvlt_84_37","chapterId":"ch_work_nvlt_84","text":"《爾雅》曰：西方之美者，有霍山之多珠玉焉，［霍山，今在平陽永安縣東北。］","sortOrder":37},
  {"id":"s_work_nvlt_84_38","chapterId":"ch_work_nvlt_84","text":"《廣志》曰：莫難珠，其色黃，生東夷，有明珠，稱夜光，有大珠径寸，或围二寸已上，出黃支，有至圓珠，置之平地，終日不停。","sortOrder":38},
  {"id":"s_work_nvlt_84_39","chapterId":"ch_work_nvlt_84","text":"《山海經》曰：开明北有珠树文玉树。","sortOrder":39},
  {"id":"s_work_nvlt_84_40","chapterId":"ch_work_nvlt_84","text":"《尚書》曰：淮夷蠙珠洎魚，［淮夷二水，出蠙珠美魚。］","sortOrder":40},
  {"id":"s_work_nvlt_84_41","chapterId":"ch_work_nvlt_84","text":"《大戴禮》曰：川生珠而岸不枯。","sortOrder":41},
  {"id":"s_work_nvlt_84_42","chapterId":"ch_work_nvlt_84","text":"《穆天子傳》曰：天子北征，舍於珠泽，珠泽之藪，方三十里。","sortOrder":42},
  {"id":"s_work_nvlt_84_43","chapterId":"ch_work_nvlt_84","text":"《晏子》曰：景公為履，黃金之綦，連以珠，良玉之句，其長尺，冰月服之以聽朝，晏子朝，公迎之，履重，仅能舉足，《晏子》曰：古者聖人製服，冬輕而暖，夏輕而凊，今金玉之履，冰月服之，是重寒也。","sortOrder":43},
  {"id":"s_work_nvlt_84_44","chapterId":"ch_work_nvlt_84","text":"《莊子》曰：黃帝遊乎赤水之北，登於崑崙之丘，遺其玄珠，使智索之而弗得，使離朱索之而弗得也，使契溝索之而不得，乃使象罔，象罔得之，黃帝曰：異哉，象罔乃可以得之乎。又河上有人家貧窮，其子没川，得千金之珠，謂其子取石來鍛之，曰：夫珠必在驪龍頷下，子遭其睡也，使而寤，子尚奚微哉。","sortOrder":44},
  {"id":"s_work_nvlt_84_45","chapterId":"ch_work_nvlt_84","text":"又曰：儒以詩禮發冢，大儒臚傳曰：［從上語下曰臚傳。］東方作矣，事久何若，小儒曰：未解裙襦，口中有珠，詩固有之曰：青青之夌，［本書八十五麥部，《太平御覽》八百零三作麥。］生陵之陂，生不布施，死何含珠為，接其鬢，擫［接。］其顪，［啄。］而以金推控其颐，徐別其頰，無傷口中珠。","sortOrder":45},
  {"id":"s_work_nvlt_84_46","chapterId":"ch_work_nvlt_84","text":"王孫子曰：昔衛靈公坐重華之台，侍女數百，隨珠照日，羅衣從風，仲叔御入諫，靈公下席再拜曰：寡人過矣。","sortOrder":46},
  {"id":"s_work_nvlt_84_47","chapterId":"ch_work_nvlt_84","text":"《呂氏春秋》曰：宋桓司馬有寶珠，抵罪出亡，王使人問珠之所在，曰：投之池中，於是竭池而求之，魚盡死焉，此言禍福之相及也。-","sortOrder":47},
  {"id":"s_work_nvlt_84_48","chapterId":"ch_work_nvlt_84","text":"又曰：以隨侯之珠，彈千仞之雀，世必笑之，何也，所用重，所要輕也。","sortOrder":48},
  {"id":"s_work_nvlt_84_49","chapterId":"ch_work_nvlt_84","text":"《韓子》曰：楚人賣珠於鄭，為木蘭之〈木匮〉，薰以桂椒，缀以珠玉，飾以瑰玉，緝以翡翠，鄭人買其〈木匮〉，還其珠，可謂善賣〈木匮〉，不可謂善鬻珠也。","sortOrder":49},
  {"id":"s_work_nvlt_84_50","chapterId":"ch_work_nvlt_84","text":"又曰：子胥出走，邊候得之，子胥曰：上求我也，以我有美珠也，今我已亡之矣，且曰子取之，邊候忧而釋之。","sortOrder":50},
  {"id":"s_work_nvlt_84_51","chapterId":"ch_work_nvlt_84","text":"《戰國策》曰：張丑為质於燕，燕王欲殺之，走出境，境吏得丑，丑曰：燕王所欲殺我者，人言我有寶珠也，王欲得之，我今已亡之矣，而王不信，今子且致我，我且言子奪我珠而吞之，燕王必且殺子，刳子之腹，反子之賸矣，吾要且死，子之賸亦且寸絕矣，境吏恐而放之。","sortOrder":51},
  {"id":"s_work_nvlt_84_52","chapterId":"ch_work_nvlt_84","text":"《淮南子》曰：明月之珠，不能無颣。","sortOrder":52},
  {"id":"s_work_nvlt_84_53","chapterId":"ch_work_nvlt_84","text":"又，楚王亡其猿，而林木為之殘，宋王亡其珠於池中，而魚為之殫。","sortOrder":53},
  {"id":"s_work_nvlt_84_54","chapterId":"ch_work_nvlt_84","text":"東方朔《神異經》曰：西北荒中，有二金闕，高百丈，上有明月珠，径三丈，光照千里。","sortOrder":54},
  {"id":"s_work_nvlt_84_55","chapterId":"ch_work_nvlt_84","text":"《漢書》曰：武帝時，使人入海市明月大珠，至围二寸已下。","sortOrder":55},
  {"id":"s_work_nvlt_84_56","chapterId":"ch_work_nvlt_84","text":"又曰：昭帝上官太後，被珠襦，废少帝為昌邑王。","sortOrder":56},
  {"id":"s_work_nvlt_84_57","chapterId":"ch_work_nvlt_84","text":"《列仙傳》曰：朱仲者，會稽市販珠人，漢高後時，募市三寸珠，乃詣闕上之，賜金五百，魯元公主私以七百金，從仲求之，仲獻四寸珠而去，不知所之，漢武故事曰：帝起神屋堂，以白玉為帘，玳瑁為押。","sortOrder":57},
  {"id":"s_work_nvlt_84_58","chapterId":"ch_work_nvlt_84","text":"《漢書》曰：董偃與母賣珠為業，偃年十三，隨母入馆陶公主家，左右言其夭，好，召見曰：吾為母養之，因得幸。","sortOrder":58},
  {"id":"s_work_nvlt_84_59","chapterId":"ch_work_nvlt_84","text":"《東觀漢記》曰：顯宗時，鍾離意為尚書，交趾太守坐贓千金，徵還伏法，詔以資物班賜群臣，意得珠璣，悉以委地，而不拜賜，上怪問其故，對曰：臣聞孔子忍渴於盜泉之水，曾參回車於勝母之間，惡其名也，此贓秽之寶，誠不敢拜受，帝嗟叹曰：清乎尚書之言，乃更以库錢三十萬賜之。","sortOrder":59},
  {"id":"s_work_nvlt_84_60","chapterId":"ch_work_nvlt_84","text":"謝承《後漢書》曰：孟嘗為合浦太守，郡境舊采珠，以易米食，先時二千石貪秽，使民采珠，積以自入，珠忽徙去，合浦無珠，饿死者盈路，孟嘗行化，一年之間，去珠复還。","sortOrder":60},
  {"id":"s_work_nvlt_84_61","chapterId":"ch_work_nvlt_84","text":"又曰：汝南李敬，為趙相，奴於鼠穴中得系珠，璫珥相連，以問主簿，對曰：前相夫人，昔亡三珠，疑子婦竊之，因其去婦，敬乃送珠付前相，相慚，追去婦還。","sortOrder":61},
  {"id":"s_work_nvlt_84_62","chapterId":"ch_work_nvlt_84","text":"《續漢書》曰：扶風人王［《太平御覽》八百零二作士。］孫奋，居富而性吝，梁冀自以馬乘具遺之，從貸錢五千萬，奋以五百萬與之，冀大怒，乃告郡縣，劾奋母為其守藏婢，雲盜白珠十斛，紫金千斤以叛，遂收考奋兄弟，死於獄中，悉没資财，亿七千餘萬。","sortOrder":62},
  {"id":"s_work_nvlt_84_63","chapterId":"ch_work_nvlt_84","text":"《三辅故事》曰：秦始皇葬驪山，起陵高五十丈，下以水銀為泉，以明月珠為日月。","sortOrder":63},
  {"id":"s_work_nvlt_84_64","chapterId":"ch_work_nvlt_84","text":"《魏略》曰：大秦國出明珠夜光珠真白珠，夫餘出珠，珠大如酸棗。","sortOrder":64},
  {"id":"s_work_nvlt_84_65","chapterId":"ch_work_nvlt_84","text":"《魏志》曰：文帝問蘇則曰：前破酒泉張掖，西域通使敦煌，獻径寸大珠，可复求市益得不，則對曰：若陛下化洽中國，德流沙漠，即不求自至，求而得之，不足貴也，帝嘿然。","sortOrder":65},
  {"id":"s_work_nvlt_84_66","chapterId":"ch_work_nvlt_84","text":"《蜀志》曰：宋豫使吳，孫權遺豫大珠一斛。","sortOrder":66},
  {"id":"s_work_nvlt_84_67","chapterId":"ch_work_nvlt_84","text":"《搜神記》曰：南海之外，有鲛人，水居如魚，不废緝績，其人能泣珠。","sortOrder":67},
  {"id":"s_work_nvlt_84_68","chapterId":"ch_work_nvlt_84","text":"又曰：隨侯行，見大蛇傷，救而治之，其後蛇衔珠以報之，径盈寸，純白而夜光，可以燭堂，故歷世稱焉。","sortOrder":68},
  {"id":"s_work_nvlt_84_69","chapterId":"ch_work_nvlt_84","text":"又曰：吳王夫差女名玉，死亡，童子韓重，至冢前哭祭之，女乃見形，將重入冢，遺径寸明珠。","sortOrder":69},
  {"id":"s_work_nvlt_84_70","chapterId":"ch_work_nvlt_84","text":"又曰：有玄鶴為弋人所射，窮而歸哙參，參收養，療治瘡，瘡愈而放之，後鶴夜到門外，參執燭视之，鶴雌雄双至，各衔明珠以報參焉。","sortOrder":70},
  {"id":"s_work_nvlt_84_71","chapterId":"ch_work_nvlt_84","text":"《三秦記》曰：崑明池，昔有人釣魚，纶絕而去，遂通夢於漢武帝，求去釣，帝明日戲於池，見大魚衔索，帝曰：豈夢所見耶，取而放之，間三日，池邊得明珠一双，帝曰：豈非魚之報耶。","sortOrder":71},
  {"id":"s_work_nvlt_84_72","chapterId":"ch_work_nvlt_84","text":"萬震《南州異物志》曰：合浦民善遊，采珠兒年十餘歲，便教入水，官禁民采珠，巧盜者，蹲水底，刮蚌得好珠，吞而出，裴氏《廣州記》曰：鯨鲵目，即明月珠，故死不見有目精。","sortOrder":72},
  {"id":"s_work_nvlt_84_73","chapterId":"ch_work_nvlt_84","text":"《幽明錄》曰：漢武帝幸河渚，聞絃歌之音，俄而有老公及年少數人出，皆長八九寸，為帝奏樂飲酒，老公顧命取洞穴之寶，一人受命，下没川底，得一大珠，径數寸，明耀絕世，上問東方朔，朔曰：河底有一穴，深數百丈，中有赤蚌，生此珠焉。","sortOrder":73},
  {"id":"s_work_nvlt_84_74","chapterId":"ch_work_nvlt_84","text":"又曰：王敦召吳猛，猛至江口，入水中，命船人併進，船至大雷，見猛行水上，從東北還逆船，弟子問其故，猛雲，水神數興波浪，賊害行旅，蹔過約敕，以真珠一握為信。","sortOrder":74},
  {"id":"s_work_nvlt_84_75","chapterId":"ch_work_nvlt_84","text":"【賦】梁吳筠碎珠賦曰：明珠碎矣，於川之隈，视圓流而失轉，見折水之亡回，謝驪宮之瑞飾，粉靈蚌之神胎，若有人兮聲茫昧，芳徽斷兮明珠碎，明珠碎兮怆何宣，珠兮珠兮不复全。","sortOrder":75},
  {"id":"s_work_nvlt_84_76","chapterId":"ch_work_nvlt_84","text":"【銘】晉江統真珠銘曰：嗣茲陰景，系晷太陽，嘉彼令生，廉聲以章。","sortOrder":76},
  {"id":"s_work_nvlt_84_78","chapterId":"ch_work_nvlt_84","text":"《說文》曰：貝，海介虫也，古者货貝而寶龟，至周而有泉，到秦废貝行泉。","sortOrder":78},
  {"id":"s_work_nvlt_84_79","chapterId":"ch_work_nvlt_84","text":"《爾雅》曰：貝居陆焱，在水蜬，［音含。］大者〈魚冗〉，［音沉。］小者鰿，［積音，今之細貝，亦有紫色者，出日南。］玄貝胎貝，［黑色者。］餘蚳黃白文，［音治，黃质白文。］餘泉白黃文，［白质黃文也，詩成是貝錦，則紫貝也，紫貝以紫為质，黑為文點也。］蚆［葩］博而頯，［匡軌反，中廣，兩頭銳。］蜠囷大而俭，责小而惰，［惰狹而長。］","sortOrder":79},
  {"id":"s_work_nvlt_84_80","chapterId":"ch_work_nvlt_84","text":"《本草經》曰：貝子一名貝齒，生東海。","sortOrder":80},
  {"id":"s_work_nvlt_84_81","chapterId":"ch_work_nvlt_84","text":"《山海經》曰：陽山濁洛之水，註於蕃之泽，中多文貝。","sortOrder":81},
  {"id":"s_work_nvlt_84_82","chapterId":"ch_work_nvlt_84","text":"又曰：陰山漁水，中多文貝。","sortOrder":82},
  {"id":"s_work_nvlt_84_83","chapterId":"ch_work_nvlt_84","text":"又曰：邽山濛水，多黃貝。","sortOrder":83},
  {"id":"s_work_nvlt_84_84","chapterId":"ch_work_nvlt_84","text":"又曰：赤水之東，蒼梧之野，有文貝。","sortOrder":84},
  {"id":"s_work_nvlt_84_85","chapterId":"ch_work_nvlt_84","text":"《歸藏》曰：有人將來，遺我货貝，以至則彻，以求則得，有喜將至。","sortOrder":85},
  {"id":"s_work_nvlt_84_86","chapterId":"ch_work_nvlt_84","text":"《毛詩》曰：萋兮斐兮，成是貝錦。","sortOrder":86},
  {"id":"s_work_nvlt_84_87","chapterId":"ch_work_nvlt_84","text":"《毛詩義疏》曰：貝，鼊龟屬。又有紫貝，其白质如玉，紫點為文，皆行列相當，大者有径一尺六寸，今九真交阯以為杯盤，寶物也。","sortOrder":87},
  {"id":"s_work_nvlt_84_88","chapterId":"ch_work_nvlt_84","text":"《春秋運斗枢》曰：搖光得江吐大貝。","sortOrder":88},
  {"id":"s_work_nvlt_84_89","chapterId":"ch_work_nvlt_84","text":"太公《六韜》曰：商王拘西伯昌於羑里，太公謂散宜生，求珍物以免君罪，之九江，得大貝百冯，［詩作百朋］","sortOrder":89},
  {"id":"s_work_nvlt_84_90","chapterId":"ch_work_nvlt_84","text":"楚辭九歌曰：魚鱗屋兮龍堂，紫貝闕兮朱宮，［河伯以魚鱗蓋屋，畫龍文，紫貝作闕，朱丹其宮。］","sortOrder":90},
  {"id":"s_work_nvlt_84_91","chapterId":"ch_work_nvlt_84","text":"《尚書大傳》曰：文王囚於羑里，散宜生之江淮之浦，而得大貝，如車渠，以獻紂。","sortOrder":91},
  {"id":"s_work_nvlt_84_92","chapterId":"ch_work_nvlt_84","text":"《鹽鐵論》曰：教與民改，弊與世易，夏後以玄貝，周人以紫石也。","sortOrder":92},
  {"id":"s_work_nvlt_84_93","chapterId":"ch_work_nvlt_84","text":"《漢書》曰：文帝賜南越王尉他書及衣，他因使者，獻紫貝五百。","sortOrder":93},
  {"id":"s_work_nvlt_84_94","chapterId":"ch_work_nvlt_84","text":"又曰：王莽時，大貝四寸八分已上，二枚為一朋，直二百一十六，牡貝三寸六分已上，一朋直五十，么貝二寸四分已上，一朋直三十，小貝寸二分已上，一朋直十，不盈寸二分，不得為朋，每枚直錢三，是為货貝五品，貝不盈六分，不得為货。","sortOrder":94},
  {"id":"s_work_nvlt_84_95","chapterId":"ch_work_nvlt_84","text":"廣州志曰：凡有八，紫貝最其美者，出交州，大貝出巨延州，與行贾质易。","sortOrder":95},
  {"id":"s_work_nvlt_84_96","chapterId":"ch_work_nvlt_84","text":"萬震《南州異物志》曰：乃有大貝，奇姿難儔，［大貝，文貝也，交阯以南海中皆有之。］素质紫飾，文若羅珠，不磨不瑩，采耀光流，思雕莫加，欲琢靡逾，在昔姬伯，用免其拘。","sortOrder":96},
  {"id":"s_work_nvlt_84_97","chapterId":"ch_work_nvlt_84","text":"徐衷南方記曰：班貝羸大者，围之得六寸，小者围之得五寸，在於海邊，捕魚時時有得之者，大貝出諸薄巨延州，土地采賣之，以易絳青。","sortOrder":97},
  {"id":"s_work_nvlt_84_98","chapterId":"ch_work_nvlt_84","text":"劉欣期交州記曰：大貝出日南，如酒杯，小貝，貝齒也，善治毒，俱有紫色。","sortOrder":98},
  {"id":"s_work_nvlt_84_99","chapterId":"ch_work_nvlt_84","text":"《南州異物志》曰：交阯北，南海中，有大文貝，质白而文紫，天姿自然，不假雕琢，磨瑩而光色煥烂，相貝經曰：相貝經，朱仲受之於琴高，琴高乘魚，浮於海河，水產必究，仲學仙於高，而得其法。又獻珠於漢武，去不知所之，嚴助為會稽太守，仲又出，遺助以径尺之貝，併致此文於助曰：皇帝唐尧夏禹三代之貞瑞，靈奇之秘寶，其有次此者，貝盈尺，状如赤電黑雲，謂之紫貝，素质紅黑，謂之朱貝，青地绿文，謂之綬貝，黑文黃晝，謂之霞貝，紫愈疾，朱明目，綬消氣鄣，霞伏蛆虫，雖不能延齡增寿，其御害一也，复有下此者，鷹喙蝉脊，以逐溫去水，無奇功，貝大者如輪，文王請大秦貝，径半尋，穆王得其壳，懸於昭觀，秦穆公以遺燕晁，可以明目遠察，宜玉宜金，南海貝如珠砾，或白駮，其性寒，其味甘，止水毒，浮貝使人寡，無以近婦人，黑白各半是也，濯貝使人善驚，無以親童子，黃唇點齒有赤駮是也，雖貝使病疟，黑鼻無皮是也，嚼貝使胎消，勿以示孕婦，赤帶通脊是也，慧貝使人善忘，勿以近人，赤炽內壳赤絡是也，醟貝使童子愚，女人淫，有青唇赤鼻是也，碧貝使童子盜，脊上有縷句唇是也，雨則重，霁則輕，委貝使人志強，夜行伏迷鬼狼豹百獸，赤中圓是也，雨則輕，霁則重。","sortOrder":99},
  {"id":"s_work_nvlt_84_100","chapterId":"ch_work_nvlt_84","text":"【贊】晉郭璞貝贊曰：先民有作，龟貝為货，貴以文采，贾以小大，簡則易資，犯而不過。","sortOrder":100},
  {"id":"s_work_nvlt_84_101","chapterId":"ch_work_nvlt_84","text":"◇馬瑙","sortOrder":101},
  {"id":"s_work_nvlt_84_102","chapterId":"ch_work_nvlt_84","text":"《廣雅》曰：馬瑙，石次玉。","sortOrder":102},
  {"id":"s_work_nvlt_84_103","chapterId":"ch_work_nvlt_84","text":"《廣志》曰：馬瑙出西南諸國。","sortOrder":103},
  {"id":"s_work_nvlt_84_104","chapterId":"ch_work_nvlt_84","text":"《玄中記》曰：馬瑙出月氏國。","sortOrder":104},
  {"id":"s_work_nvlt_84_105","chapterId":"ch_work_nvlt_84","text":"《魏略》曰：大秦國多馬瑙。","sortOrder":105},
  {"id":"s_work_nvlt_84_106","chapterId":"ch_work_nvlt_84","text":"《涼州記》曰：呂纂鹹寧二年，盜發張駿陵，得馬瑙鍾榼。","sortOrder":106},
  {"id":"s_work_nvlt_84_107","chapterId":"ch_work_nvlt_84","text":"【賦】魏文帝馬瑙勒賦曰：馬瑙玉屬也，出自西域，文理交错，有似馬瑙，故其方人因以名之，命夫良工，是剖是镌，追形逐好，從宜索便，乃加砥砺，刻方為圓，沈光內照，浮景外鮮，繁文縟藻，交采接連，嘉鏤錫之盛美，感戎馬之首飾，圖茲物之攸宜，信君子之所服，爾乃藉彼朱罽，華勒用成，骈居別趾，煥若羅星。","sortOrder":107},
  {"id":"s_work_nvlt_84_108","chapterId":"ch_work_nvlt_84","text":"魏王粲馬瑙勒賦曰：遊大國以廣觀，覽希世之伟寶，總眾材而課美，信莫臧於馬瑙，被文采之華飾，雜朱绿與蒼阜，於是乃命工人，裁以飾勒，因姿象形，匪雕匪刻，厥容應規，厥性順德，御世嗣之駿服，表騄骥之儀則。","sortOrder":108},
  {"id":"s_work_nvlt_84_109","chapterId":"ch_work_nvlt_84","text":"◇琉璃","sortOrder":109},
  {"id":"s_work_nvlt_84_110","chapterId":"ch_work_nvlt_84","text":"《廣雅》曰：琉璃，珠也。","sortOrder":110},
  {"id":"s_work_nvlt_84_111","chapterId":"ch_work_nvlt_84","text":"韻集曰：琉璃，火齊珠也。","sortOrder":111},
  {"id":"s_work_nvlt_84_112","chapterId":"ch_work_nvlt_84","text":"《廣志》曰：琉璃出黃支斯調大秦日南諸國。","sortOrder":112},
  {"id":"s_work_nvlt_84_113","chapterId":"ch_work_nvlt_84","text":"《十洲記》曰：方丈山上有琉璃宮。","sortOrder":113},
  {"id":"s_work_nvlt_84_114","chapterId":"ch_work_nvlt_84","text":"《漢書》曰：武帝時，使人入海市琉璃。","sortOrder":114},
  {"id":"s_work_nvlt_84_115","chapterId":"ch_work_nvlt_84","text":"《魏略》曰：大秦國出赤白黑黃青绿绀縹紅紫十种琉璃。","sortOrder":115},
  {"id":"s_work_nvlt_84_116","chapterId":"ch_work_nvlt_84","text":"《吳歷》曰：黃武四年，扶南諸外國來獻琉璃。","sortOrder":116},
  {"id":"s_work_nvlt_84_117","chapterId":"ch_work_nvlt_84","text":"諸葛恢集，詔答恢，今致琉璃碗一。","sortOrder":117},
  {"id":"s_work_nvlt_84_118","chapterId":"ch_work_nvlt_84","text":"《南州異物志》曰：琉璃本质是石，欲作器，以自然灰治之，自然灰状如黃灰，生南海濱，亦可浣衣，用之不須淋，但投之中，滑如苔石，不得此灰，則不可釋。","sortOrder":118},
  {"id":"s_work_nvlt_84_119","chapterId":"ch_work_nvlt_84","text":"《世說》曰：滿奋畏風，在武帝琉璃窗內坐，實密似疏，奋有疑，帝問之，答曰：臣猶吳牛，見光而喘。","sortOrder":119},
  {"id":"s_work_nvlt_84_120","chapterId":"ch_work_nvlt_84","text":"又曰：武帝嘗降王武子，供饌盤悉用琉璃器。","sortOrder":120},
  {"id":"s_work_nvlt_84_121","chapterId":"ch_work_nvlt_84","text":"又曰：王敦尚主，至石崇舍，如廁畢，婢擎金澡盤，盛水，琉璃碗，盛澡豆，王取豆著水中飲之，謂之乾飯。","sortOrder":121},
  {"id":"s_work_nvlt_84_122","chapterId":"ch_work_nvlt_84","text":"【賦】晉潘尼琉璃碗賦曰：濟流沙之絕险，越葱嶺之峻危，於是遊西極，望大蒙，歷鍾山，闚燭龍，觐王母，訪仙童，取琉璃之攸華，詔曠世之良工，纂玄儀以取象，准三辰以定容，光映日曜，圓盛月盈，纖瑕罔麗，飛尘靡停，灼爚旁燭，表里相形，凝霜不足方其絜，澄水不能喻其清，刚過金石，劲励琼玉，磨之不磷，涅之不濁。","sortOrder":122},
  {"id":"s_work_nvlt_84_123","chapterId":"ch_work_nvlt_84","text":"◇車渠","sortOrder":123},
  {"id":"s_work_nvlt_84_124","chapterId":"ch_work_nvlt_84","text":"《廣雅》曰：車渠，石次玉也。","sortOrder":124},
  {"id":"s_work_nvlt_84_125","chapterId":"ch_work_nvlt_84","text":"《廣志》曰：車渠出大秦國及西域諸國。","sortOrder":125},
  {"id":"s_work_nvlt_84_126","chapterId":"ch_work_nvlt_84","text":"《玄中記》曰：車渠出天竺國。","sortOrder":126},
  {"id":"s_work_nvlt_84_127","chapterId":"ch_work_nvlt_84","text":"蘇子曰：車渠馬瑙，出於荒外，今冀州之土，曾未得其奇也。","sortOrder":127},
  {"id":"s_work_nvlt_84_128","chapterId":"ch_work_nvlt_84","text":"【賦】魏文帝車渠碗賦曰：車渠玉屬也，多纖理縟文，生於西國，其俗寶之，惟二儀之普育，何萬物之殊形，料珍怪之上美，無茲碗之獨靈，苞華文之光麗，發符采而扬榮，理交错以連屬，似將離而复併，或若朝雲浮高山，忽似飛鳥厲蒼天，夫其方者如矩，圓者如規，稠希不谬，洪纖有宜。","sortOrder":128},
  {"id":"s_work_nvlt_84_129","chapterId":"ch_work_nvlt_84","text":"魏王［《太平御覽》八百零八王下有粲字。］車渠碗賦曰：侍君子之宴坐，覽車渠之妙珍，挺英才於山嶽，含陰陽之淑真，飛輕縹與浮白，若驚風之飄雲，光清朗以內曜，泽溫润而外津，體貞刚而不撓，理脩達而有文，兼五德之上美，起［御覽作超。］眾寶而絕倫。","sortOrder":129},
  {"id":"s_work_nvlt_84_130","chapterId":"ch_work_nvlt_84","text":"◇玳瑁","sortOrder":130},
  {"id":"s_work_nvlt_84_131","chapterId":"ch_work_nvlt_84","text":"《廣志》曰：玳瑁形似龟，出南海巨延州。","sortOrder":131},
  {"id":"s_work_nvlt_84_132","chapterId":"ch_work_nvlt_84","text":"《周書·王會》曰：伊尹謂湯曰：請以玳瑁為獻。","sortOrder":132},
  {"id":"s_work_nvlt_84_133","chapterId":"ch_work_nvlt_84","text":"《史記》曰：趙使於春申君，欲夸楚，為玳瑁簪，劍器悉飾以玳瑁。","sortOrder":133},
  {"id":"s_work_nvlt_84_134","chapterId":"ch_work_nvlt_84","text":"續漢書舆服志曰：貴人助蠶，玳瑁釵。","sortOrder":134},
  {"id":"s_work_nvlt_84_135","chapterId":"ch_work_nvlt_84","text":"高文惠與婦書曰：今致玳瑁梳一枚。","sortOrder":135},
  {"id":"s_work_nvlt_84_136","chapterId":"ch_work_nvlt_84","text":"《南州異物志》曰：玳瑁如龟，生南方海中，大者如蘧蒢，背上有鱗，大如扇，發取其鱗，因見其文，欲以作器，則煮之，因以刀截，任意所作，冷乃以枭魚皮错治之，後以枯條木葉瑩之，乃有光耀。","sortOrder":136},
  {"id":"s_work_nvlt_84_137","chapterId":"ch_work_nvlt_84","text":"魏繁钦詩曰：何以表別離，耳後玳瑁釵。","sortOrder":137},
  {"id":"s_work_nvlt_84_138","chapterId":"ch_work_nvlt_84","text":"【賦】晉潘尼玳瑁碗賦曰：有玳瑁之奇寶，亦同旅於介虫，下法川以矩夷，上擬乾而規隆，或步趾於清源，或掉尾於泥中，隨陰陽以潛躍，與龟龍乎齊風，包神藏智，備體兼才，高下斯處，水陆皆能，文若綺波，背負逢萊，爾乃遐夷效珍，越裳貢職，橫海萬里，逾嶺千亿，挺璞荒蠻，摛藻辰極，光曜炫晃，昭烂熻赩，嘉斯寶之兼美，料眾珍而靡對，文不煩於错鏤，采不假乎藻缋，豈翡翠之足俪，胡犀象之能逮。","sortOrder":138},
  {"id":"s_work_nvlt_84_139","chapterId":"ch_work_nvlt_84","text":"【箋】後漢班固與窦憲箋曰：明將軍賜固玳瑁簪。","sortOrder":139},
  {"id":"s_work_nvlt_84_141","chapterId":"ch_work_nvlt_84","text":"《尚書》曰：淮海惟楊州，厥貢惟金三品，［金銀銅。］","sortOrder":141},
  {"id":"s_work_nvlt_84_142","chapterId":"ch_work_nvlt_84","text":"《左傳》曰：鄭伯朝楚，楚子與之金，曰：無以為兵，使鑄三鍾，《越絕書》曰：鄞山破而出錫，若耶涸而出銅，欧冶因為純鈞之劍。","sortOrder":142},
  {"id":"s_work_nvlt_84_143","chapterId":"ch_work_nvlt_84","text":"《史記》曰：秦始皇鑄天下兵器為十二金人，重各千斤。","sortOrder":143},
  {"id":"s_work_nvlt_84_144","chapterId":"ch_work_nvlt_84","text":"《漢書》曰：凡律度量衡用銅者，所以同天下，齊風俗也，銅為物至精，不為燥濕寒暑变其節，不為風雨曝露改其形，似於士君子之行，是以用銅也，用竹為引者，事之宜也，［竹長十丈，高一丈，唯竹篾软而堅，宜為之也。］","sortOrder":144},
  {"id":"s_work_nvlt_84_145","chapterId":"ch_work_nvlt_84","text":"又曰：吳有章郡銅山，即招致天下人亡命者，盜鑄錢，以故土賦而國用饒。","sortOrder":145},
  {"id":"s_work_nvlt_84_146","chapterId":"ch_work_nvlt_84","text":"又曰：上使善相相邓通，曰：當貧饿死，文帝曰：能富通在我，何謂貧，於是賜通蜀東道銅山鑄錢。","sortOrder":146},
  {"id":"s_work_nvlt_84_147","chapterId":"ch_work_nvlt_84","text":"華峤《漢書》曰：靈帝時，遂使鉤盾令宋典，繕治南宮。又使掖庭令畢岚，鑄銅人四，列於蒼龍玄武闕外。又鑄四鍾，皆受二千斛，懸於堂及雲台殿，殿前又鑄天祿虾蟆，吐水渴乌，施於桥西，用洒南北郊路，以省百姓洒道之費。","sortOrder":147},
  {"id":"s_work_nvlt_84_148","chapterId":"ch_work_nvlt_84","text":"《魏略》曰：明帝徙長安諸鍾虡骆駝銅人，承露盤折，銅人不可致，留住霸城。又列坐於司馬門外，晉諸公贊曰：司馬摸居關中，鑄朅銅人爐虡為金器，以易穀。","sortOrder":148},
  {"id":"s_work_nvlt_84_149","chapterId":"ch_work_nvlt_84","text":"世語曰：太康八年，凌雲台上生銅。","sortOrder":149},
  {"id":"s_work_nvlt_84_150","chapterId":"ch_work_nvlt_84","text":"林邑記曰：林邑王范文，鑄銅屋。","sortOrder":150},
  {"id":"s_work_nvlt_84_151","chapterId":"ch_work_nvlt_84","text":"【贊】晉郭璞赤銅贊曰：崑吾之山，名銅所在，切玉如泥，火炎其采，尸子所叹，验之汲宰。","sortOrder":151},
  {"id":"s_work_nvlt_84_152","chapterId":"ch_work_nvlt_84","text":"【表】梁沈約為柳世隆上銅表曰：夫幣以周務，货以赈民，阜國康治，莫尚乎此，周氏致平，始於圓法，漢世幾厝，資於貫朽，名爐化金，良工盡藝，方將盈金中藏，收功上苑，南楚陋其方府，西京鄙其部內。","sortOrder":152},
  {"id":"s_work_nvlt_84_153","chapterId":"ch_work_nvlt_84","text":"《藝文類聚》　唐·欧陽詢","sortOrder":153},
  {"id":"s_work_nvlt_85_1","chapterId":"ch_work_nvlt_85","text":"卷八十五百穀部、布帛部","sortOrder":1},
  {"id":"s_work_nvlt_85_2","chapterId":"ch_work_nvlt_85","text":"○穀禾稻粳黍粟豆麻麥","sortOrder":2},
  {"id":"s_work_nvlt_85_3","chapterId":"ch_work_nvlt_85","text":"○素錦絹綾羅布","sortOrder":3},
  {"id":"s_work_nvlt_85_5","chapterId":"ch_work_nvlt_85","text":"《爾雅》曰：中有岱嶽，五穀魚鹽生焉，穀不熟為飢，仍飢為荐，［言太山有魚鹽之饒也，不熟，五穀不成，荐，連歲不熟。］","sortOrder":5},
  {"id":"s_work_nvlt_85_6","chapterId":"ch_work_nvlt_85","text":"《周官》曰：楊州荆州宜稻，豫州宜种麥，青州宜稻麥，兖州宜三种，雍州宜黍稷，幽州三种，冀州宜黍稷，併州宜五种，［五种，黍稷菽麥稻，三种，黍稷稻。］","sortOrder":6},
  {"id":"s_work_nvlt_85_7","chapterId":"ch_work_nvlt_85","text":"太宰，九職任萬民，一曰三農，生九穀，［黍稷秫稻麻大小麥。］","sortOrder":7},
  {"id":"s_work_nvlt_85_8","chapterId":"ch_work_nvlt_85","text":"《禮記》曰：孟春，天子乃以元日祈穀於上帝，［謂以上辛郊天也，郊祀後稷，以祈農事，故蟄而郊，郊而後耕，上帝太微之帝。］","sortOrder":8},
  {"id":"s_work_nvlt_85_9","chapterId":"ch_work_nvlt_85","text":"傳曰：夫郊祀後稷，以祈農事，故啟蟄而郊，郊而後耕。","sortOrder":9},
  {"id":"s_work_nvlt_85_10","chapterId":"ch_work_nvlt_85","text":"又曰：孟秋，農乃登穀，天子嘗新，先荐寢廟，［黍稷之屬，於是始荐。］命百官始收斂，［候秋氣始收斂。］","sortOrder":10},
  {"id":"s_work_nvlt_85_11","chapterId":"ch_work_nvlt_85","text":"《穀梁傳》曰：一穀不升曰嗛，二穀不升曰飢，三穀不升曰饉，四穀不升曰康，五穀不升曰大侵，大侵則君食不兼味，台榭不涂，百官布而不製，鬼神祷而不祠。","sortOrder":11},
  {"id":"s_work_nvlt_85_12","chapterId":"ch_work_nvlt_85","text":"《墨子》曰：一穀不收謂之饉，二穀不收謂之旱，三穀不收謂之凶，四穀不收謂之餽，五穀不收謂之飢饉，五穀不熟，謂之大侵，則大夫以下損祿五分之一，旱則二，凶則三，餽則四，飢大侵則盡祿，廪食而已。","sortOrder":12},
  {"id":"s_work_nvlt_85_13","chapterId":"ch_work_nvlt_85","text":"范子《計然》曰：五穀者，萬民之命，國之重寶也，是故無道之君，及無道之民，皆不能積其盛有餘之時，以待其衰不足也，《師曠占》曰：黃帝問師曠，曰：杏多實不虫者，來年秋善，五木者，五穀之先，欲知五穀，但视五木，擇其木盛者，來年益种之。","sortOrder":13},
  {"id":"s_work_nvlt_85_14","chapterId":"ch_work_nvlt_85","text":"京房《易逆刺》曰：天雨穀，歲大熟。","sortOrder":14},
  {"id":"s_work_nvlt_85_15","chapterId":"ch_work_nvlt_85","text":"《東觀漢記》曰：建武二年，天下野穀旋［東觀漢記作旅。］生，麻菽尤盛。","sortOrder":15},
  {"id":"s_work_nvlt_85_16","chapterId":"ch_work_nvlt_85","text":"又曰：欲征匈奴，與窦固等議，皆以為塞外草美，馬可不須穀，按軍出塞，無穀馬故事，馬防言，當與穀，［事具馬篇。］","sortOrder":16},
  {"id":"s_work_nvlt_85_17","chapterId":"ch_work_nvlt_85","text":"《論衡》曰：建武三十一年，陳留雨穀蔽地，视穀形若粢而黑，此夷狄地生穀也，夷狄不食穀，生於草野，成熟委於地，遭疾風，與之俱飛，風衰，穀集中國，中國見之，謂天雨穀也。","sortOrder":17},
  {"id":"s_work_nvlt_85_18","chapterId":"ch_work_nvlt_85","text":"《風俗通》曰：牛乃耕農之本，百姓所仰，為用最大，國家之為強弱也，建武之初，軍役亟動，牛亦損耗，農業頗废，米石萬錢，天愛斯民，扶助聖主，事有徵應，於是旅穀弥望，野茧被山。","sortOrder":18},
  {"id":"s_work_nvlt_85_19","chapterId":"ch_work_nvlt_85","text":"《曹瞞傳》曰：太祖嘗賦廪穀不足，私謂主者曰：如何，主者曰：以小斛量之，太祖曰：善，後軍中言太祖欺眾，太祖謂主者，特當借汝死以厭眾，不然事不解，乃取問曰：行小斛，盜官穀，斬之軍門。","sortOrder":19},
  {"id":"s_work_nvlt_85_20","chapterId":"ch_work_nvlt_85","text":"王肅《丧服要記》曰：昔者魯哀公祖載其父，孔子問曰：寧設五穀囊乎，公曰：不也，五穀囊者，起伯夷叔齊，不食周粟，而饿死首陽山，恐魂之飢，故作五穀囊，吾父食味含哺而死，何用此為。","sortOrder":20},
  {"id":"s_work_nvlt_85_21","chapterId":"ch_work_nvlt_85","text":"《魏志》曰：袁涣，字曜卿，為魏國郎中令，及卒，太祖為之流涕，賜穀二千斛，一敖［《太平御覽》八百三十七作教，下同。］以太仓穀千斛，賜郎中令家，一敖以垣下穀千斛，與曜卿家，外不解其意，教曰：以太仓穀者，官法也，垣下穀者，親舊也。","sortOrder":21},
  {"id":"s_work_nvlt_85_22","chapterId":"ch_work_nvlt_85","text":"《江表傳》曰：諸葛亮聞恪伐徐詳，書與陆遜曰：家兄年老而恪性疏，今使典主糧穀，糧穀軍之要最，仆雖在遠，竊用不安，足下特為啟至尊轉之。","sortOrder":22},
  {"id":"s_work_nvlt_85_23","chapterId":"ch_work_nvlt_85","text":"王隱《晉書》曰：邓攸為吳郡，吳人飢荒，攸辄出台仓赈之，被劾辄出穀，攸叹曰：善不可為也。","sortOrder":23},
  {"id":"s_work_nvlt_85_24","chapterId":"ch_work_nvlt_85","text":"《幽明錄》曰：琅琊諸葛氏兄弟二人，寓居晉陵，家甚貧耗，常假乞自給，穀在圌中，計日用未應盡，而早以空罄，始者故謂是家中相竊盜，故复封捡題識，而耗如初，後有宿客遠來，至巷口，見數人簷穀從門出，客借問諸葛在不，答雲，悉在，客進語訖，因問卿何得大粜穀，主人雲，告乞充口，雲何粜之，客雲，吾向來逢見人簷穀出，為是何事，主人兄弟相视，竊自疑怪，人看封題，俨然如故，试开圌量视，無十許斛，知前後所失，非人為之也。","sortOrder":24},
  {"id":"s_work_nvlt_85_25","chapterId":"ch_work_nvlt_85","text":"【謳】魏陳王曹植魏德論謳曰：於穆聖皇，仁畅惠渥，辭獻减膳，以服鳏獨，和氣致祥，時雨渗漉，野草萌变，化成嘉穀。","sortOrder":25},
  {"id":"s_work_nvlt_85_26","chapterId":"ch_work_nvlt_85","text":"【啟】梁元帝上穀充軍糧啟曰：臣聞金城十仞，必資守粟，革車千乘，其在饋實，原武車綏旌，列飛鸿之行陳，奉辭受脤，揜挚獸於貙虎，贾逵渠水，雖曰難蹤，梁習勸農，竊知自勉。","sortOrder":26},
  {"id":"s_work_nvlt_85_28","chapterId":"ch_work_nvlt_85","text":"《說文》曰：禾，嘉穀也，以二月而种，八月始熟，得時之中，故謂之禾。","sortOrder":28},
  {"id":"s_work_nvlt_85_29","chapterId":"ch_work_nvlt_85","text":"《山海經》曰：崑崙墟上，有木禾，禾長五尋，［木禾，穀類。］","sortOrder":29},
  {"id":"s_work_nvlt_85_30","chapterId":"ch_work_nvlt_85","text":"《尚書》曰：唐叔得禾，異畝同穎，獻諸天子，王命歸周公於東，作歸禾，［畝，垅也，穎，穗也，禾各生一垅，而共為一穗，天下禾同之象，周公德所以致，故歸之。］","sortOrder":30},
  {"id":"s_work_nvlt_85_31","chapterId":"ch_work_nvlt_85","text":"《左傳》曰：鄭祭足帥師，取成周之禾。","sortOrder":31},
  {"id":"s_work_nvlt_85_32","chapterId":"ch_work_nvlt_85","text":"《孝經援神契》曰：德下至地，則嘉禾生。","sortOrder":32},
  {"id":"s_work_nvlt_85_33","chapterId":"ch_work_nvlt_85","text":"《呂氏春秋》曰：飯之美者，玄山之禾。","sortOrder":33},
  {"id":"s_work_nvlt_85_34","chapterId":"ch_work_nvlt_85","text":"《史記》曰：管仲說桓公曰：古之封禪者，北里之禾，所以為盛，［北里，地名。］","sortOrder":34},
  {"id":"s_work_nvlt_85_35","chapterId":"ch_work_nvlt_85","text":"《淮南子》曰：後稷辟土墾草，而不能使禾冬生。","sortOrder":35},
  {"id":"s_work_nvlt_85_36","chapterId":"ch_work_nvlt_85","text":"《東觀漢記》曰：光武生於濟陽縣，是歲有嘉禾，一茎九穗，［事具帝王部。］又曰：淳於恭，有盜刈恭禾者，恭見之，念其愧，因自伏草中，盜去乃起，［事具人部讓篇。］","sortOrder":36},
  {"id":"s_work_nvlt_85_37","chapterId":"ch_work_nvlt_85","text":"《續漢書》曰：承宮，琅耶人也，常在蒙山中耕种禾黍，臨熟，人認之，宮便推與而去，由是發名，［事具人部讓篇。］","sortOrder":37},
  {"id":"s_work_nvlt_85_38","chapterId":"ch_work_nvlt_85","text":"《古今註》曰：和帝元年，嘉禾生濟陰城陽，一茎九穗，安帝延光二年，嘉禾生九真，百五十六本，七百六十八穗。","sortOrder":38},
  {"id":"s_work_nvlt_85_39","chapterId":"ch_work_nvlt_85","text":"《吳志》曰：赤乌七年，宛陵言嘉禾生。","sortOrder":39},
  {"id":"s_work_nvlt_85_40","chapterId":"ch_work_nvlt_85","text":"又曰：會稽言嘉禾生，改年為嘉禾。","sortOrder":40},
  {"id":"s_work_nvlt_85_41","chapterId":"ch_work_nvlt_85","text":"晉《起居註》曰：武帝世，嘉禾三生，元帝世，嘉禾三生，其茎七穗。","sortOrder":41},
  {"id":"s_work_nvlt_85_42","chapterId":"ch_work_nvlt_85","text":"《續搜神記》曰：庐陵巴丘人□晃者，世以田作為業，年常田數十頃，家漸富，晉太元初，秋收已過，獲刈都畢，明旦至田，禾悉复滿，湛然如先，即便更獲盈仓，於此遂巨富。","sortOrder":42},
  {"id":"s_work_nvlt_85_43","chapterId":"ch_work_nvlt_85","text":"夢書曰：禾稼為财，田之所出，夢見禾稼，言财氣生。","sortOrder":43},
  {"id":"s_work_nvlt_85_44","chapterId":"ch_work_nvlt_85","text":"【謳】魏陳王曹植魏德論謳曰：猗猗嘉禾，惟穀之精，其洪盈箱，协穗殊茎，昔生周朝，今植魏庭，獻之廟堂，以昭祖靈。","sortOrder":44},
  {"id":"s_work_nvlt_85_45","chapterId":"ch_work_nvlt_85","text":"【贊】宋孝武帝清暑殿甍嘉禾贊曰：維殷粵周，有穗表禎，祥乎合矣，超瑞高甍，非原非泽，乃瑞乃靈，庶藉天貺，廣茲化清。","sortOrder":45},
  {"id":"s_work_nvlt_85_47","chapterId":"ch_work_nvlt_85","text":"《爾雅》曰：稌，稻也，［《說文》曰：稻，稌也。］","sortOrder":47},
  {"id":"s_work_nvlt_85_48","chapterId":"ch_work_nvlt_85","text":"《廣雅》曰：稻穗謂之禾。","sortOrder":48},
  {"id":"s_work_nvlt_85_49","chapterId":"ch_work_nvlt_85","text":"《廣志》曰：有紫芒稻赤穬稻白米稻，南方有蝉鳴稻。","sortOrder":49},
  {"id":"s_work_nvlt_85_50","chapterId":"ch_work_nvlt_85","text":"《禮記》曰：祭宗廟之禮，稻曰嘉蔬。","sortOrder":50},
  {"id":"s_work_nvlt_85_51","chapterId":"ch_work_nvlt_85","text":"《吳志》曰：鍾離牧，山陰人，少居永興，自墾田种二十餘畝，臨熟而縣民認取之，牧曰：本以田荒，故墾之耳，遂以稻與民。","sortOrder":51},
  {"id":"s_work_nvlt_85_52","chapterId":"ch_work_nvlt_85","text":"《江表傳》曰：孫亮五鳳元年，交阯稗草化為稻，《會稽典錄》曰：夏香，有盜刈稻者，香助收之，盜者慚，送以還香，香不受。","sortOrder":52},
  {"id":"s_work_nvlt_85_53","chapterId":"ch_work_nvlt_85","text":"【贊】晉湛方生庭前植稻苗贊曰：蒨蒨嘉苗，離離階侧，弱葉繁蔚，圓朱疏植，清流津根，輕露濯色。","sortOrder":53},
  {"id":"s_work_nvlt_85_55","chapterId":"ch_work_nvlt_85","text":"《說文》曰：粳，稻屬也。","sortOrder":55},
  {"id":"s_work_nvlt_85_56","chapterId":"ch_work_nvlt_85","text":"《廣雅》曰：秈，粳也。","sortOrder":56},
  {"id":"s_work_nvlt_85_57","chapterId":"ch_work_nvlt_85","text":"《廣志》曰：稉有乌粳黑穬。","sortOrder":57},
  {"id":"s_work_nvlt_85_58","chapterId":"ch_work_nvlt_85","text":"鄭氏婚禮謁文贊曰：粳米馥芬，婚禮之珍。","sortOrder":58},
  {"id":"s_work_nvlt_85_59","chapterId":"ch_work_nvlt_85","text":"魏文帝與朝臣書曰：江表唯長沙名有好米，何時此［《初學記》二十七作得比。］新成［《初學記》、《太平御覽》八百三十九作城。］稉稻邪，上風炊之，五里聞香。","sortOrder":59},
  {"id":"s_work_nvlt_85_60","chapterId":"ch_work_nvlt_85","text":"表［北堂書鈔一百四十二作袁。］准觀殊俗曰：河內青稻，新成［書鈔作城。］白稉。","sortOrder":60},
  {"id":"s_work_nvlt_85_61","chapterId":"ch_work_nvlt_85","text":"【啟】梁庾肩吾謝赉粳米啟曰：出梁國租，［句有脱文。］兼水陆之殊品，伊尹說而不至，石崇豪所未及，遇處嘿之得賓，同朗之舉著，［句有脱文。］長河可塞，上德無訓。","sortOrder":61},
  {"id":"s_work_nvlt_85_62","chapterId":"ch_work_nvlt_85","text":"又謝湘東王赉米啟曰：味重新城，香逾涝水，連舟入浦，似彦伯之南歸，積地為山，疑馬援之西至，不待候沙，同新渝之再熟，無勞拜石，均遼仓之重滿，前恩未遠，次渥仍流，墨翟假以故書，裴楷慚其國賜。","sortOrder":62},
  {"id":"s_work_nvlt_85_63","chapterId":"ch_work_nvlt_85","text":"又答湘東王赉稉米啟曰：竊以農夫力耕，時逢俭歲，疏賤時泽，必取丰年，椓斛泻珠，嘉聞陶量，翻庭委玉，欣見馬圌。","sortOrder":63},
  {"id":"s_work_nvlt_85_65","chapterId":"ch_work_nvlt_85","text":"《爾雅》曰：秬，黑黍，秠，一稃二米，［漢和帝時，任城生黑黍，或三四實也。］","sortOrder":65},
  {"id":"s_work_nvlt_85_66","chapterId":"ch_work_nvlt_85","text":"《說文》曰：以大暑而种，故謂之黍。","sortOrder":66},
  {"id":"s_work_nvlt_85_67","chapterId":"ch_work_nvlt_85","text":"《山海經》曰：廣都之野，後稷葬焉，爰有膏黍膏稷。","sortOrder":67},
  {"id":"s_work_nvlt_85_68","chapterId":"ch_work_nvlt_85","text":"《禮記》曰：仲夏之月，農乃登黍。","sortOrder":68},
  {"id":"s_work_nvlt_85_69","chapterId":"ch_work_nvlt_85","text":"《毛詩》曰：黍離，闵宗周也，彼黍離離，彼稷之苗。","sortOrder":69},
  {"id":"s_work_nvlt_85_70","chapterId":"ch_work_nvlt_85","text":"又曰：今適南畝，或耘或耔，黍稷薿薿，［耔，耘苗，薿薿，盛濬也。］又曰：薿薿［《初學記》二十七作芃芃。］黍苗，陰雨膏之。","sortOrder":70},
  {"id":"s_work_nvlt_85_71","chapterId":"ch_work_nvlt_85","text":"《呂氏春秋》曰：飯之美者，南海之秬，［秬，黑黍。］","sortOrder":71},
  {"id":"s_work_nvlt_85_72","chapterId":"ch_work_nvlt_85","text":"《韓子》曰：韓昭侯之時，黍种嘗貴，鮮有，昭侯令人覆廪，廪吏果竊黍种而粜之。","sortOrder":72},
  {"id":"s_work_nvlt_85_73","chapterId":"ch_work_nvlt_85","text":"又曰：孔子侍坐於魯哀公，設桃具黍，哀公曰：請用，仲尼先飯黍而後啖桃，左右皆掩口失笑，公曰：黍者非飯之也，以先桃之也，仲尼對曰：丘知之矣，夫黍者五穀之長也，祭先王以為上盛，果有六，而桃為下，祭先王不得入於廟，丘聞之也，君子以賤雪貴，不聞以貴雪賤，今以五穀之長，雪果蓏之下，是侵上忽下也。","sortOrder":73},
  {"id":"s_work_nvlt_85_74","chapterId":"ch_work_nvlt_85","text":"《史記·封禪書》曰：管仲說桓公曰：古之封禪，鄗王黍所以為盛，［鄗上名山。］","sortOrder":74},
  {"id":"s_work_nvlt_85_75","chapterId":"ch_work_nvlt_85","text":"《淮南子》曰：渭水多力而宜黍。","sortOrder":75},
  {"id":"s_work_nvlt_85_76","chapterId":"ch_work_nvlt_85","text":"《東觀漢記》曰：承宮將妻子入華蓋蒙陰山穀，耕种禾黍，［已具禾篇。］","sortOrder":76},
  {"id":"s_work_nvlt_85_77","chapterId":"ch_work_nvlt_85","text":"《古今註》曰：宣帝元康四年，長安雨黑黍粟，和帝元興元年，黑黍穗，一禾二實，或三四實，生任城，得粟三升［《太平御覽》八百四十二作斛。］八升，［御覽作斗。］以荐宗廟。","sortOrder":77},
  {"id":"s_work_nvlt_85_78","chapterId":"ch_work_nvlt_85","text":"【賦】晉稽含孤黍賦曰：餘慎終屋之南榮，有孤黍生焉，因泥之濕，遭雨之润，宿昔牙蘗，滋茂甚速，涂燥根淺，忽然萎殒，深感此黍，不韜种以待時，貪榮弃本，寄身非所，自取彫枯，不亦宜乎。","sortOrder":78},
  {"id":"s_work_nvlt_85_80","chapterId":"ch_work_nvlt_85","text":"《爾雅》曰：{艹舋}，赤苗，芑，白苗，［{艹舋}，赤粱粟也，芑，白粱粟也。］","sortOrder":80},
  {"id":"s_work_nvlt_85_81","chapterId":"ch_work_nvlt_85","text":"又曰：粢稷，［今江東呼粟為粢也，孫炎曰：稷，粟也。］","sortOrder":81},
  {"id":"s_work_nvlt_85_82","chapterId":"ch_work_nvlt_85","text":"《說文》曰：粟，嘉穀實也，粟之為言續也。","sortOrder":82},
  {"id":"s_work_nvlt_85_83","chapterId":"ch_work_nvlt_85","text":"《周書》曰：神農之時，天雨粟，神農耕而种之，作陶冶斤斧，破木為秬，［《太平御覽》八百四十作耜。］鉏耨以墾草莽，然後五穀興，以助果蓏之實。","sortOrder":83},
  {"id":"s_work_nvlt_85_84","chapterId":"ch_work_nvlt_85","text":"《左傳》曰：鄭飢而未及麥，民病，子皮以子展之命，饩國人粟，戶八鍾。","sortOrder":84},
  {"id":"s_work_nvlt_85_85","chapterId":"ch_work_nvlt_85","text":"又曰：冬，晉荐飢，乞籴於秦，秦伯输粟於晉，自雍及絳相繼，命之曰汎舟之役，《論語》曰：子華使於齊，冉子為其母請粟，子曰：與之釜，［子華，孔子弟子公西赤之字也，六斗四升曰釜也。］請益，曰：與之庾，六斛四斗曰庾。","sortOrder":85},
  {"id":"s_work_nvlt_85_86","chapterId":"ch_work_nvlt_85","text":"子曰：赤之適齊也，乘肥馬，衣輕裘，吾聞君子周急不繼富，［非冉有與之太多。］","sortOrder":86},
  {"id":"s_work_nvlt_85_87","chapterId":"ch_work_nvlt_85","text":"又曰：原思為之宰，與之粟九百，辭，［讓不受也。］子曰：無，以與爾鄰里乡党乎，［無，止其讓之辭。］","sortOrder":87},
  {"id":"s_work_nvlt_85_88","chapterId":"ch_work_nvlt_85","text":"雒書說禾曰：仓帝起，天雨粟，青雲扶日。","sortOrder":88},
  {"id":"s_work_nvlt_85_89","chapterId":"ch_work_nvlt_85","text":"《六韜》曰：發巨桥之粟，散鹿台之金錢，以與殷民，［事具帝王部。］","sortOrder":89},
  {"id":"s_work_nvlt_85_90","chapterId":"ch_work_nvlt_85","text":"晏子曰：北郭骚見晏子，讬以養母，晏子分仓粟府金以遺之，骚辭金受粟。","sortOrder":90},
  {"id":"s_work_nvlt_85_91","chapterId":"ch_work_nvlt_85","text":"春秋說題辭［《初學記》二十六，《太平御覽》八百五十作運斗枢。又《初學記》二十七，御覽八百四十作說題辭，同此。］曰：粟五变，生為苗，秀為禾，三变而祭［《初學記》二十六，御覽八百四十作粲。］謂之粟，四变曰米，［《初學記》，御覽作入臼米出甲。］五变而蒸飯可食，［禀受五行氣而成，故五变乃成可食。］","sortOrder":91},
  {"id":"s_work_nvlt_85_92","chapterId":"ch_work_nvlt_85","text":"孔丛子，公儀曰：子思居貧，其友有饋之粟者，受二車焉，或獻樽酒束脩，子思曰：為費而無當也，或曰：子取人粟而辭酒，是辭少而受多也，於義無名，於分則不全，行之何也，子思曰：然，仍［孔丛子作伋。］不幸而貧，至及困乏，將絕先人之祀，夫所以受粟，為周之也，酒脯則所飲宴也，方之於食，而乃飲燕，非義也，吾豈以為分哉，度義而行之。","sortOrder":92},
  {"id":"s_work_nvlt_85_93","chapterId":"ch_work_nvlt_85","text":"又曰：季桓子以粟十鍾饩夫子，受而班門人之無者，子貢曰：季孫以夫子貧，故致粟，今而施人，無乃乖彼意乎，子曰：吾受而不辭，為季孫之惠，受不為富，惠於一人，豈若數百人哉。","sortOrder":93},
  {"id":"s_work_nvlt_85_94","chapterId":"ch_work_nvlt_85","text":"《莊子》曰：莊周往貸粟於監河侯，監河侯曰：诺，我將得邑金，貸子三百金，可乎，周忿然曰：若乃言此，不如早索我枯魚之肆，［事具人部貧篇。］","sortOrder":94},
  {"id":"s_work_nvlt_85_95","chapterId":"ch_work_nvlt_85","text":"商君書曰：金一兩生境內，粟一十二石死於境外，粟十二石生於境內，金一兩死於境外，國好生金於境內，則金粟兩死，府库兩虛，國弱，好生粟於境內，金粟兩生，仓府兩實，國強。","sortOrder":95},
  {"id":"s_work_nvlt_85_96","chapterId":"ch_work_nvlt_85","text":"《呂氏春秋》曰：飯美者不周之粟。","sortOrder":96},
  {"id":"s_work_nvlt_85_97","chapterId":"ch_work_nvlt_85","text":"《史記》曰：伯夷叔齊，聞西伯善養老，往歸焉，值武王東伐紂，叩馬諫，左右欲刃之，太公曰：此義人也，扶而去之，武王平殷亂，天下宗周，伯夷叔齊恥之，義不食周粟而饿死。","sortOrder":97},
  {"id":"s_work_nvlt_85_98","chapterId":"ch_work_nvlt_85","text":"又曰：宣曲任氏之先，為督道仓吏，秦之败，豪桀皆爭取金玉，而任氏獨窖仓粟，楚漢相距滎陽，民不得耕种，米至貴，乃而豪桀金玉盡歸任氏，以此起富。","sortOrder":98},
  {"id":"s_work_nvlt_85_99","chapterId":"ch_work_nvlt_85","text":"又曰：漢興七十餘年，大仓之粟，陳陳相因，充溢露積於外，至腐败不可食也。","sortOrder":99},
  {"id":"s_work_nvlt_85_100","chapterId":"ch_work_nvlt_85","text":"《贾誼書》曰：邹穆公有令，食凫雁者，必以秕，無敢以粟，於是仓無秕，而求易於民，二石粟得一石秕，吏以請曰：秕食凫雁，為無費也，今求秕於民，二石粟而易一石秕，食雁則費甚矣，請以粟食之，穆公曰：去，非爾知也，夫百姓餉牛而耕，暴背而耘，勤而不敢墮者，豈為鳥獸哉，粟米人上食也，奈何其以養鳥，且汝知小小計，而不知大害，［新序又載。］","sortOrder":100},
  {"id":"s_work_nvlt_85_101","chapterId":"ch_work_nvlt_85","text":"《漢書》曰：東方朔曰：侏儒長三尺餘，俸一囊粟，錢二百四十，臣朔長九尺餘，亦一囊粟，錢二百四十，侏儒飽欲死，臣朔飢欲死。","sortOrder":101},
  {"id":"s_work_nvlt_85_102","chapterId":"ch_work_nvlt_85","text":"《淮南子》曰：黃帝治天下，力牧太山稽辅之，狗彘吐菽粟於道路，而無分爭之心。","sortOrder":102},
  {"id":"s_work_nvlt_85_103","chapterId":"ch_work_nvlt_85","text":"又曰：昔者仓頡作書而天雨粟，［仓頡，始视鳥跡之文而造書者也，有書契則作伪萌生，生則去本趣末，弃耕作之業，而務錐刀之利，天知其將饿，故為雨粟。］","sortOrder":103},
  {"id":"s_work_nvlt_85_104","chapterId":"ch_work_nvlt_85","text":"《說苑》曰：高平王遣使者從魏文侯貸粟，文侯曰：須吾租收邑粟至，乃得也，使者曰：臣初來時，見渎中有魚，張口謂臣曰：吾窮水魚，命在呼吸，可得灌乎，臣謂之曰：待吾南見河堤之君，决江淮之水，灌汝口，魚曰：為命在須臾，及須决淮之水，比至還，必求吾於枯魚之肆，今高平貧窮，故遣臣詣君貸粟，乃須租收粟至者，大王必求臣死人之墓。","sortOrder":104},
  {"id":"s_work_nvlt_85_105","chapterId":"ch_work_nvlt_85","text":"《古今註》曰：武帝建元四年，天雨粟，宣帝地節三年，長安雨黑粟，竟寧元年，南陽山都縣雨粟，色青黑，味苦，大者如小豆，小者如麻子。","sortOrder":105},
  {"id":"s_work_nvlt_85_106","chapterId":"ch_work_nvlt_85","text":"《風俗通》曰：燕太子丹仰叹，天為雨粟，桂陽先賢書贊曰：成丁，郴人，能達鳥鳴，為郡主簿，與眾人俱坐，聞雀鳴而笑曰：東市輦粟車覆，雀相呼往食之，眾人遣视，信然，［益部耆舊又載。］","sortOrder":106},
  {"id":"s_work_nvlt_85_107","chapterId":"ch_work_nvlt_85","text":"《氾勝之書》曰：神農之教，雖有石城湯池，帶甲百萬，而無粟者，弗能守也，夫穀帛實天下之命，衛尉前上蠶法，今上農事，人所忽略，衛尉勤之，可謂忠國忧民之至。","sortOrder":107},
  {"id":"s_work_nvlt_85_108","chapterId":"ch_work_nvlt_85","text":"【書】漢晁错上書曰：利民欲者，莫如用爵致粟矣，能以粟拜爵者，皆民之有餘者也，取有餘以給塞下之食，則富人有爵，而貧民損益於征賦矣，此以有餘補不足，而貧富之民各得其原也。","sortOrder":108},
  {"id":"s_work_nvlt_85_110","chapterId":"ch_work_nvlt_85","text":"《物理論》曰：菽者，眾豆之總名。","sortOrder":110},
  {"id":"s_work_nvlt_85_111","chapterId":"ch_work_nvlt_85","text":"《龍魚河圖》曰：歲暮夕，四更中，取二七豆子，二七麻子，家人頭少許發，合麻子豆著井中，祝敕井吏，其家竟年不遭傷寒，辟五溫鬼。","sortOrder":111},
  {"id":"s_work_nvlt_85_112","chapterId":"ch_work_nvlt_85","text":"《管子》曰：桓公北伐山戎，以戎菽遍布於天下，［事具武部征讨篇。］","sortOrder":112},
  {"id":"s_work_nvlt_85_113","chapterId":"ch_work_nvlt_85","text":"鶡冠子曰：兩葉蔽目，不見太山，双豆塞耳，不聞雷霆，［事具天部雷篇。］","sortOrder":113},
  {"id":"s_work_nvlt_85_114","chapterId":"ch_work_nvlt_85","text":"史記曰：弃為兒時，好种树麻菽麥。","sortOrder":114},
  {"id":"s_work_nvlt_85_115","chapterId":"ch_work_nvlt_85","text":"《東觀漢記》曰：闵仲叔，太原人也，與周党相友，党每過仲叔，共唅菽飲水，無菜茹。","sortOrder":115},
  {"id":"s_work_nvlt_85_116","chapterId":"ch_work_nvlt_85","text":"又曰：劉平嘗為饿賊所劫，叩頭曰：老母飢，少氣力，待平為命，原得還飯食母，馳來就死，涕泣發於肝胆，賊即遣去，乃摭三升豆，以謝賊恩。","sortOrder":116},
  {"id":"s_work_nvlt_85_117","chapterId":"ch_work_nvlt_85","text":"《古今註》曰：宣帝元康四年，南陽雨豆。","sortOrder":117},
  {"id":"s_work_nvlt_85_118","chapterId":"ch_work_nvlt_85","text":"《吳志》曰：趙達善筭，使人取小豆數升，播之席上，立知其數。","sortOrder":118},
  {"id":"s_work_nvlt_85_119","chapterId":"ch_work_nvlt_85","text":"王隱《晉書》曰：時王浚稱製邊垂，潛使人問霍原，原不答，浚既衔之。又有遼東內從三百餘人，依山為賊，意欲劫原為王，亦未能行，時有謠曰：天子在何許，近在豆田中，豆者為霍，浚遂害原，懸其首，諸生悲哭其中。","sortOrder":119},
  {"id":"s_work_nvlt_85_120","chapterId":"ch_work_nvlt_85","text":"《鄴中記》曰：石勒讳胡，胡物皆改名，胡餅曰麻餅，胡綏曰香綏，胡豆曰國豆。","sortOrder":120},
  {"id":"s_work_nvlt_85_121","chapterId":"ch_work_nvlt_85","text":"《笑林》曰：有人弔丧，併欲赍物助之，問人，可與何等物，人答曰：錢布穀帛，任卿所有耳，困［太平廣記二百六十二作因。］赍大豆一斛相與，孝子哭唤奈何，已以為問豆，答曰：可作飯，孝子哭复唤窮，已曰：適得便窮，自當更送一斛。","sortOrder":121},
  {"id":"s_work_nvlt_85_122","chapterId":"ch_work_nvlt_85","text":"《雜五行書》曰：常以正月旦，亦用月半，以麻子七枚，赤豆二七枚，著井中，辟溫病，甚神效，［與龍魚河圖語小異，故重取。］","sortOrder":122},
  {"id":"s_work_nvlt_85_123","chapterId":"ch_work_nvlt_85","text":"【賦】張翰豆羹賦曰：乃有孟秋嘉菽，垂枝挺英，是刈是獲，充箪盈箧，香鑠和調，周疾赴急，時御一杯，下咽三叹，時在下邑，頗多艱難，空匮之厄，固不缀懽，追念昔日，啜菽永安。","sortOrder":123},
  {"id":"s_work_nvlt_85_125","chapterId":"ch_work_nvlt_85","text":"《爾雅》曰：枲麻，黂枲實，［黂，麻子也。］黂字［爾雅釋草作茡。］麻母，［直(爾雅註作苴。)麻，麻之有子也。］","sortOrder":125},
  {"id":"s_work_nvlt_85_126","chapterId":"ch_work_nvlt_85","text":"《廣雅》曰：黂，麻也。","sortOrder":126},
  {"id":"s_work_nvlt_85_127","chapterId":"ch_work_nvlt_85","text":"《毛詩》曰：丘中有麻。","sortOrder":127},
  {"id":"s_work_nvlt_85_128","chapterId":"ch_work_nvlt_85","text":"又曰：東門之池，可以漚麻。","sortOrder":128},
  {"id":"s_work_nvlt_85_129","chapterId":"ch_work_nvlt_85","text":"又曰：麻麥懞々，［懞々，茂也。］","sortOrder":129},
  {"id":"s_work_nvlt_85_130","chapterId":"ch_work_nvlt_85","text":"《禮記》曰：仲秋之月，天子乃以犬嘗麻，先荐寢廟，［麻新黂。］","sortOrder":130},
  {"id":"s_work_nvlt_85_131","chapterId":"ch_work_nvlt_85","text":"《淮南子》曰：汾水濛濁而宜麻。","sortOrder":131},
  {"id":"s_work_nvlt_85_132","chapterId":"ch_work_nvlt_85","text":"《東觀漢記》曰：闵仲叔，太原人也，與周党友，嘗遺其生麻，仲叔叹曰：我欲省煩耳，受而不食。","sortOrder":132},
  {"id":"s_work_nvlt_85_133","chapterId":"ch_work_nvlt_85","text":"《風俗通》曰：蓬生麻中，不扶自直。","sortOrder":133},
  {"id":"s_work_nvlt_85_134","chapterId":"ch_work_nvlt_85","text":"【贊】晉郭璞麻贊曰：草皮之良，莫貴於麻，用無不給，服無不加，至物在邇，求之好遐。","sortOrder":134},
  {"id":"s_work_nvlt_85_136","chapterId":"ch_work_nvlt_85","text":"《毛詩》曰：爰采麥矣，沬之北矣。","sortOrder":136},
  {"id":"s_work_nvlt_85_137","chapterId":"ch_work_nvlt_85","text":"《左傳》曰：夏四月，鄭祭足帥師，取溫之麥，［溫，周也，蘇氏邑。］","sortOrder":137},
  {"id":"s_work_nvlt_85_138","chapterId":"ch_work_nvlt_85","text":"又曰：晉侯夢大厲，公覺，召桑田巫，巫曰：不食新矣，［言公不得及食新麥也。］六月，晉侯欲麥，［周六月，今四月，麥始熟。］使甸人獻麥，饋人為之，召桑田巫，雲［《太平御覽》八百三十八作示。］而殺之，將食，張如廁，陷而卒。","sortOrder":138},
  {"id":"s_work_nvlt_85_139","chapterId":"ch_work_nvlt_85","text":"《家語》曰：宓子賤為单父宰，百姓化之，齊人攻魯，道由单父，单父父老請曰：麥已熟矣，今齊寇至，不及人人自收其麥，請放民皆使出獲麥，可以益糧，且不資寇，三請而宓子賤不聽，俄而齊寇逮乎麥，季孫聞之怒，使人讓曰：民寒耕熱芸，曾不得食，可不哀哉，猶可有告，而子不聽，非所以也，宓子槅然曰：今茲無麥，明年可树，若使不耕者得穫，是使民樂有寇也，且单父得一歲之麥，於魯不加強，丧之不加弱，使民有自取之心，其創必數世不息，季孫聞之，赧然媿曰：地若可入，吾豈忍見宓子哉，［《贾誼書》同。］","sortOrder":139},
  {"id":"s_work_nvlt_85_140","chapterId":"ch_work_nvlt_85","text":"《莊子》曰：儒以禮詩發冢，小儒曰：中有珠，詩曰：青青之麥，生陵之陂，生不施，死何含珠為，［事具珠部。］史記曰：箕子朝周，過故殷墟，見禾黍，箕子傷之，欲哭則不可，欲泣為其近婦人，乃作麥秀之詩，以歌詠之，其詩曰：麥秀漸漸兮，黍禾油油。","sortOrder":140},
  {"id":"s_work_nvlt_85_141","chapterId":"ch_work_nvlt_85","text":"《漢書》曰：武帝外事四夷，而民去本，董仲舒說上曰：春秋他穀不書，至於麥禾不成則書之，以此見聖人五穀最重粟麥。","sortOrder":141},
  {"id":"s_work_nvlt_85_142","chapterId":"ch_work_nvlt_85","text":"《東觀漢記》曰：高鳳，南陽人，誦讀晝夜不絕，妻嘗之田，曝麥於庭，以竿授鳳，令護雞，受竿誦經如故，天大雷，暴雨流淹，鳳留意在經史，忽不视麥，麥隨水漂去。","sortOrder":142},
  {"id":"s_work_nvlt_85_143","chapterId":"ch_work_nvlt_85","text":"又曰：張堪為漁陽太守，勸民耕种，以致殷富，百姓歌曰：桑無附枝，麥穗兩岐，張君為政，樂不可支，［事具職官部刺史篇。］","sortOrder":143},
  {"id":"s_work_nvlt_85_144","chapterId":"ch_work_nvlt_85","text":"《續漢書》曰：桓帝時童謠曰：小麥青青大麥枯，誰當獲者婦與姑，丈夫何在西击胡。","sortOrder":144},
  {"id":"s_work_nvlt_85_145","chapterId":"ch_work_nvlt_85","text":"《曹瞞傳》曰：太祖嘗行經麥中，令士卒無败麥，犯者死，騎士皆下馬持麥以相付，時太祖馬騰入麥中，敕主簿議罪，主簿對以春秋之義，罰不加於尊，太祖曰：製法而自犯之，何以率下，然孤為軍師，［《太平御覽》八百三十八作帥。］不可殺，謂自刑，因援劍割發以置地。","sortOrder":145},
  {"id":"s_work_nvlt_85_146","chapterId":"ch_work_nvlt_85","text":"諸葛恪別傳曰：孫權嘗饗蜀使費袆，袆停食餅，索筆作麥賦，恪亦請筆作磨賦，鹹稱善焉。","sortOrder":146},
  {"id":"s_work_nvlt_85_147","chapterId":"ch_work_nvlt_85","text":"《博物志》曰：近世有田夫，至巧而不自覺也，其婦稱之，猶不自信，乃削木為麥，入市粜之，籴者無疑，歸磨，乃覺非麥。","sortOrder":147},
  {"id":"s_work_nvlt_85_148","chapterId":"ch_work_nvlt_85","text":"《晉中興書》曰：符健，洪弟三弟，健陰圖關中，陽使其徒种麥，示無西意。","sortOrder":148},
  {"id":"s_work_nvlt_85_149","chapterId":"ch_work_nvlt_85","text":"秦子曰：孔文舉為北海相，有遭父丧，哭泣墓侧，色無憔悴，文舉殺之。又有母病瘥，思食新麥，家無，乃盜鄰熟麥而進之，文舉聞之，特賞曰：無有來謝，勿复盜也，盜而不罪者，以為勤於母飢，哭而見殺者，以為形慈而實否。","sortOrder":149},
  {"id":"s_work_nvlt_85_150","chapterId":"ch_work_nvlt_85","text":"【奏】魏黃觀曰：今年麥苗雖好，臨熟多雨，而悉复偃坏，小麥略盡，惟穬麥大麥，頗得半收耳。","sortOrder":150},
  {"id":"s_work_nvlt_85_152","chapterId":"ch_work_nvlt_85","text":"《釋名》曰：素，楪素也，已織則供用，不复飾也。","sortOrder":152},
  {"id":"s_work_nvlt_85_153","chapterId":"ch_work_nvlt_85","text":"《毛詩》曰：素衣朱繡。","sortOrder":153},
  {"id":"s_work_nvlt_85_154","chapterId":"ch_work_nvlt_85","text":"《禮記》曰：天子素帶朱里。","sortOrder":154},
  {"id":"s_work_nvlt_85_155","chapterId":"ch_work_nvlt_85","text":"范子《計然》曰：白素出三辅。","sortOrder":155},
  {"id":"s_work_nvlt_85_156","chapterId":"ch_work_nvlt_85","text":"楊雄答劉歆書曰：天下上計孝廉，及內郡街卒會者，雄常把三寸弱翰筆，赍油素三尺，以問其異語，歸即以鉛擿次之鉛椠，二十七歲於今矣，［事具雄文部。］《東觀漢記》曰：鄭據守正盡節，賜據素六十匹，由是顯名。","sortOrder":156},
  {"id":"s_work_nvlt_85_157","chapterId":"ch_work_nvlt_85","text":"班固與弟超書曰：今赍白素三匹，欲以市月氏馬蘇合香闟登。","sortOrder":157},
  {"id":"s_work_nvlt_85_158","chapterId":"ch_work_nvlt_85","text":"《鹽鐵論》曰：縞素不能自分其緇墨，賢聖不能自治其亂也。","sortOrder":158},
  {"id":"s_work_nvlt_85_159","chapterId":"ch_work_nvlt_85","text":"【詩】古詩曰：新人工織缣，故人工織素，織缣日一匹，織素五丈餘，以缣持比素，新人不如故。","sortOrder":159},
  {"id":"s_work_nvlt_85_160","chapterId":"ch_work_nvlt_85","text":"【賦】漢班婕妤捣素賦曰：若乃廣储懸月，暉木流清，桂露朝滿，涼衿夕輕，改容飾而相命，卷霜帛而下庭，曳羅裙之綺靡，振琼珮之精鳴，若乃盼睞生姿，動容多製，弱態含羞，妖風靡麗，於是投香杵，叩玟砧，擇鸞聲，爭鳳音，格沿虛而調遠，掛田貞而响沉，散繁輕而浮捷，節疏亮而清深，調非常律，聲無定本，任落手之參差，從風飆之近遠，或連躍而更投，或蹔舒而長斂，侈長袖於妍袂，缀半月於蘭襟，表纖手於微縫，庶見跡而知心，計脩路之遐敻，恐芬芳之易泄，書既封而重題，笥已緘而更結。","sortOrder":160},
  {"id":"s_work_nvlt_85_162","chapterId":"ch_work_nvlt_85","text":"《說文》曰：錦，金也，作之用功重，其价如金，故製字帛與金也。","sortOrder":162},
  {"id":"s_work_nvlt_85_163","chapterId":"ch_work_nvlt_85","text":"《毛詩》曰：角枕粲兮，錦衾烂兮。","sortOrder":163},
  {"id":"s_work_nvlt_85_164","chapterId":"ch_work_nvlt_85","text":"又曰：巷伯，刺幽王也，寺人傷於讒而作是詩也，萋兮斐兮，成是貝錦，［萋菲，文相助也。］彼谮人者，亦以太甚。","sortOrder":164},
  {"id":"s_work_nvlt_85_165","chapterId":"ch_work_nvlt_85","text":"《左傳》曰：狄滅衛，齊侯使公子無虧戍曹，歸公乘馬，夫人魚軒，［魚軒，夫人車，以魚皮為飾。］重錦三十兩，［重錦，錦之熟細者，以二丈双行，故曰兩，三十匹。］","sortOrder":165},
  {"id":"s_work_nvlt_85_166","chapterId":"ch_work_nvlt_85","text":"又曰：子皮欲使尹何為邑，子產曰：少，未知可居否，［尹何年少。］子皮曰：使夫往而學焉，夫亦愈知矣，子產曰：不可，子有美錦，不使人學製焉，大官大邑，身之所庇，而使學者製焉，其為美錦，不亦多乎，［言官邑之重，重於美錦。］","sortOrder":166},
  {"id":"s_work_nvlt_85_167","chapterId":"ch_work_nvlt_85","text":"《墨子》曰：古之人未知為衣服，衣皮毛，今則厚斂百姓，以為錦繡文采靡曼之衣。","sortOrder":167},
  {"id":"s_work_nvlt_85_168","chapterId":"ch_work_nvlt_85","text":"《說苑》曰：魏文侯與田子方語，有兩童子，衣錦而侍於前，田子曰：此君之寵子乎，文侯曰：非也，此子父死於戰，以其幼孤也，寡人收之，子方曰：臣以君之賊心為足矣，今滋甚也，君之寵此子也。又且以誰之父殺之乎。","sortOrder":168},
  {"id":"s_work_nvlt_85_169","chapterId":"ch_work_nvlt_85","text":"《漢書》曰：韓生說項羽曰：關中阻山河四塞，地肥饒可都，羽見秦皆已燒殘，則乃懷思東歸，曰：富貴不歸故乡，如衣錦夜行，韓生曰：人謂楚人沐猴而冠，果然。","sortOrder":169},
  {"id":"s_work_nvlt_85_170","chapterId":"ch_work_nvlt_85","text":"又曰：宣帝時，呼韓邪单於來朝，賜錦帛九十匹。","sortOrder":170},
  {"id":"s_work_nvlt_85_171","chapterId":"ch_work_nvlt_85","text":"《漢武內傳》曰：帝見西王母巾器中，有一卷小書，盛以紫錦之囊。","sortOrder":171},
  {"id":"s_work_nvlt_85_172","chapterId":"ch_work_nvlt_85","text":"漢官典職曰：尚書郎入直，中官供錦被。","sortOrder":172},
  {"id":"s_work_nvlt_85_173","chapterId":"ch_work_nvlt_85","text":"魏文帝詔群臣曰：前後每得蜀錦，殊不相似。","sortOrder":173},
  {"id":"s_work_nvlt_85_174","chapterId":"ch_work_nvlt_85","text":"《魏志》曰：景初中，賜倭女王絳地蛟龍錦五匹。","sortOrder":174},
  {"id":"s_work_nvlt_85_175","chapterId":"ch_work_nvlt_85","text":"《蜀志》曰：先主平益州，賜諸葛亮法正張飛關羽錦，各千匹。","sortOrder":175},
  {"id":"s_work_nvlt_85_176","chapterId":"ch_work_nvlt_85","text":"環氏吳記曰：蜀遣使吳，赍重錦千端。","sortOrder":176},
  {"id":"s_work_nvlt_85_177","chapterId":"ch_work_nvlt_85","text":"《異物志》曰：錦鳥，文章如丹地錦，而藻缋采文，俗人見其端正似錦，因謂之錦鳥。","sortOrder":177},
  {"id":"s_work_nvlt_85_178","chapterId":"ch_work_nvlt_85","text":"《神仙傳》曰：淮南王為八公，張錦綺之帳，燔百和之香。","sortOrder":178},
  {"id":"s_work_nvlt_85_179","chapterId":"ch_work_nvlt_85","text":"《世說》：石崇錦步鄣四十里。","sortOrder":179},
  {"id":"s_work_nvlt_85_180","chapterId":"ch_work_nvlt_85","text":"【詩】古詩曰：錦衾遺洛浦，同袍與我违。","sortOrder":180},
  {"id":"s_work_nvlt_85_181","chapterId":"ch_work_nvlt_85","text":"【啟】梁皇太子謝敕赉魏國所獻錦等啟曰：山羊之毳，東燕之席尚傳，登高之文，北鄴之錦猶見，胡綾織大秦之草，戎布紡玄菟之花。","sortOrder":181},
  {"id":"s_work_nvlt_85_182","chapterId":"ch_work_nvlt_85","text":"梁元帝為妾夏王丰謝東宮赉錦啟曰：舒將併石，堪來暮雨，萦持結纜，剩可荡舟，秦川書字，□能八體，鄴縣登高，真堪九日，宋姬赠馬，未足為榮，冯媛乘車，方茲非寵。","sortOrder":182},
  {"id":"s_work_nvlt_85_183","chapterId":"ch_work_nvlt_85","text":"又謝東宮赉辟邪子錦白褊等啟曰：江波可濯，豈藉成都之水，登高為艳，取映鳳皇之文，至如鮮絜齊紈，聲高趙縠，色方藍浦，光譬靈山，试以照花，含燭銀之状，將持比月，亂含璧之暉。","sortOrder":183},
  {"id":"s_work_nvlt_85_185","chapterId":"ch_work_nvlt_85","text":"《廣雅》曰：繁繐，鮮支縠絹也。","sortOrder":185},
  {"id":"s_work_nvlt_85_186","chapterId":"ch_work_nvlt_85","text":"華峤《後漢書》曰：陳寔在乡闾，平心率物，有盜夜入其家，止於梁上，寔陰見之，乃自整拂，命子孫，正色訓之曰：夫人不可不自勉，不善之人，未必本惡，習與性成耳，如梁上君子者是矣，盜大驚，自投於地，寔徐譬之曰：视君状貌，不似惡人，然當由貧困，今遺絹二疋，自是一縣無复盜竊。","sortOrder":186},
  {"id":"s_work_nvlt_85_187","chapterId":"ch_work_nvlt_85","text":"《魏略》曰：文帝在東宮，嘗從曹洪貸絹百疋，洪不稱，［魏志九註稱下有意字。］及洪犯法，自分必死，既得原，上書謝。","sortOrder":187},
  {"id":"s_work_nvlt_85_188","chapterId":"ch_work_nvlt_85","text":"孔舒元在窮記曰：賊來入門，時家見在絹布三千餘疋，及衣被器物，皆令婢使輦出，著庭中，恣其所取，由是皆競取财物，不暇复見殺。","sortOrder":188},
  {"id":"s_work_nvlt_85_189","chapterId":"ch_work_nvlt_85","text":"晉公卿禮秩曰：品第一者，春賜絹百疋，秋賜二百疋，王隱《晉書》曰：王尼見太傅越曰：公負尼物，越答初不識此事，尼曰：昔楚人失布，謂令尹盜者，以令尹執政，賊盜公行，是與自盜無異也，今君左右有屋舍，尼獨窮困，是亦明公負尼物也，越意解，大笑，與尼絹五十疋。","sortOrder":189},
  {"id":"s_work_nvlt_85_190","chapterId":"ch_work_nvlt_85","text":"《晉陽秋》曰：胡威少有志尚，厲操清白，父质，為荆州，威自京都省之，家貧，無車馬童仆，威自驅驢单行，拜見父，停廄中十餘日，告歸，臨辭，质賜其絹一疋，為道路糧，威跪曰：大人清高，不審於何得此絹，质曰：是吾俸祿之餘，故以為汝糧耳，［事具官職部刺史能。］","sortOrder":190},
  {"id":"s_work_nvlt_85_191","chapterId":"ch_work_nvlt_85","text":"又曰：桓溫入蜀，聞有善星者，夜執其手，於星下問國祚脩短，星人曰：太微紫微文昌三宮氣候，决無虞，五十年外不論耳，溫不悅，送絹一疋，錢五千與之，星人詣主簿習凿齒曰：今受旨自裁，乞命為摽揭棺木，問其故，曰：賜絹令仆自絞，乞錢以買棺，故知之耳，凿齒曰：君幾誤死，君聞子知星宿有不覆之義乎，絹以戲君，錢供資糧，是聽君去耳，星人喜，以言詣溫，溫笑曰：君三十年看儒書，不如一詣習主簿也。","sortOrder":191},
  {"id":"s_work_nvlt_85_192","chapterId":"ch_work_nvlt_85","text":"趙書曰：石勒參軍周雅，為馆陶令，盜官絹數百疋，下獄，後每設大會，使與俳兒，著介帻，絹单衣，優問曰：汝為何官，在我俳中，曰：本馆陶令，計二十數单衣，曰：政坐耳，是故入辈中，以為大笑。","sortOrder":192},
  {"id":"s_work_nvlt_85_193","chapterId":"ch_work_nvlt_85","text":"【表】梁沈約謝立皇太子賜絹表曰：臣聞重離在天，八紘之所共仰，明兩作貳，萬國所以鹹寧，太子體岐弱載，表睿冲茂，典册既升，休祚方遠，率土含歡，遐邇均抃，天情載洽，慶賜必周，幣帛嘉貺，猥班庸劣。","sortOrder":193},
  {"id":"s_work_nvlt_85_194","chapterId":"ch_work_nvlt_85","text":"【啟】梁沈約謝賜軫調絹等啟曰：霜紈雪委，霧縠冰鮮，昔劉氏歸國，未聞漢储之禮，曹植還蕃，非降魏兩之賜，恩愈枉道，贲深束帛。","sortOrder":194},
  {"id":"s_work_nvlt_85_195","chapterId":"ch_work_nvlt_85","text":"又謝安出門宮賜絹綺獨啟曰：桓室金縷，本非所議，孟姬作具，獨若未周，慈泽曲臨，珍華兼重，製為美服，只綺易儔，舉而不息，三夜有待。","sortOrder":195},
  {"id":"s_work_nvlt_85_196","chapterId":"ch_work_nvlt_85","text":"又謝敕賜絹葛啟曰：素采冰華，絺文霜絜，变溽暑於閨閤，起涼風於襟袖。","sortOrder":196},
  {"id":"s_work_nvlt_85_197","chapterId":"ch_work_nvlt_85","text":"梁庾肩吾答武陵王赉絹啟曰：清河之珍，丘園慚其束帛，關東之妙，潛織陋其卷绡，遂使鶴露霄凝，輕絺立变，雁風朝急，冶服成溫。","sortOrder":197},
  {"id":"s_work_nvlt_85_198","chapterId":"ch_work_nvlt_85","text":"周王褒謝赉絹啟曰：似逐安車之徵，如輕殿中之對，臣善識山川，應圖方丈，脱能臨水，必不弃書。","sortOrder":198},
  {"id":"s_work_nvlt_85_200","chapterId":"ch_work_nvlt_85","text":"《釋名》曰：綾者，其文望之似冰綾之理也。","sortOrder":200},
  {"id":"s_work_nvlt_85_201","chapterId":"ch_work_nvlt_85","text":"太公《六韜》曰：夏殷桀紂之時，婦人錦繡文綺之坐席，衣以綾紈，常三百人。","sortOrder":201},
  {"id":"s_work_nvlt_85_202","chapterId":"ch_work_nvlt_85","text":"漢武帝內傳曰：西王母侍女，服绀綾之袿。","sortOrder":202},
  {"id":"s_work_nvlt_85_203","chapterId":"ch_work_nvlt_85","text":"漢官典職儀曰：尚書郎直，供青綾白綾被。","sortOrder":203},
  {"id":"s_work_nvlt_85_204","chapterId":"ch_work_nvlt_85","text":"《魏略》曰：大秦國有金縷繡雜色綾，其國利得中國絲素，解以為胡綾。","sortOrder":204},
  {"id":"s_work_nvlt_85_205","chapterId":"ch_work_nvlt_85","text":"符丕答謝玄書曰：今往大文綾羅各五十疋。","sortOrder":205},
  {"id":"s_work_nvlt_85_206","chapterId":"ch_work_nvlt_85","text":"《世說》曰：武帝嘗降王武子，供饌槃，悉用琉璃器，婢子百餘人，皆綾羅袴褶，以手擎飲食。","sortOrder":206},
  {"id":"s_work_nvlt_85_207","chapterId":"ch_work_nvlt_85","text":"荀勖為晉文王與孫皓書曰：今餉雜色綾千端。","sortOrder":207},
  {"id":"s_work_nvlt_85_208","chapterId":"ch_work_nvlt_85","text":"《晉令》曰：第六品已，［句有脱文。］已下當脱下字，不得服今縝綾錦，有私織者，錄付尚方。","sortOrder":208},
  {"id":"s_work_nvlt_85_209","chapterId":"ch_work_nvlt_85","text":"鹹康起居註曰：詔臨邑王使，主范柳所貢物多，降［《太平御覽》八百十六作絳。］綾是其所珍，可筹量增賜。","sortOrder":209},
  {"id":"s_work_nvlt_85_210","chapterId":"ch_work_nvlt_85","text":"【啟】梁庾肩吾謝武陵王赉白綺綾啟曰：圖雲緝鶴，鄴市稀逢，寫霧傳花，丛台罕遇，雖复馬均騁思，比巧猶慚，虞卿受金，方恩未重，此□扁舟獨反，燕路有心，載寶言歸，衔珠無日。","sortOrder":210},
  {"id":"s_work_nvlt_85_211","chapterId":"ch_work_nvlt_85","text":"【書】梁庾肩吾答餉綾絞書曰：絜同雪霜，華逾纻綺，長裾可曳，無愧王門之賓，廣袖將裁，翻有城中之製。","sortOrder":211},
  {"id":"s_work_nvlt_85_213","chapterId":"ch_work_nvlt_85","text":"《釋名》曰：羅，文羅疏也。","sortOrder":213},
  {"id":"s_work_nvlt_85_214","chapterId":"ch_work_nvlt_85","text":"太山黃庭經曰：黃庭為不死之道，受者齊九日，金蘭鳳文之羅四十疋。","sortOrder":214},
  {"id":"s_work_nvlt_85_215","chapterId":"ch_work_nvlt_85","text":"范子曰：羅出齊郡。","sortOrder":215},
  {"id":"s_work_nvlt_85_216","chapterId":"ch_work_nvlt_85","text":"《燕丹子》曰：荆軻左手把秦王袖，右手椹其焜，秦王曰：今日之事，從子計耳，乞聽琴聲而死，召姬人鼓琴，琴曰：羅縠单衣，可裂而絕，八尺屏風，可超而越，鹿盧之劍，可負而伏，［《太平御覽》三百四十四作拔。］秦王乃奋地而起，遂殺軻。","sortOrder":216},
  {"id":"s_work_nvlt_85_217","chapterId":"ch_work_nvlt_85","text":"《淮南子》曰：齊俗有诡文繁繡，弱錫羅紈。","sortOrder":217},
  {"id":"s_work_nvlt_85_218","chapterId":"ch_work_nvlt_85","text":"王孫子曰：隨珠耀日，羅衣從風。","sortOrder":218},
  {"id":"s_work_nvlt_85_219","chapterId":"ch_work_nvlt_85","text":"雍門子說孟嘗君曰：今足下，下羅帷，來清風，［事具樂部。］","sortOrder":219},
  {"id":"s_work_nvlt_85_220","chapterId":"ch_work_nvlt_85","text":"世說曰：武帝嘗降王武子，婢百餘人，皆綾羅袴褶，手擎飲食，［事具綾部。］","sortOrder":220},
  {"id":"s_work_nvlt_85_221","chapterId":"ch_work_nvlt_85","text":"【啟】周庾信謝趙王赉皂羅袍袴啟曰：懸機巧緤，变躡奇文，鳳不去而恒飛，花雖寒而不落，披千金之暫暖，弃百結之長寒，永無黃葛之嗟，方見青綾之重，對天山之積雪，尚得开衿，冒廣厦之長風，猶當揮汗，白龟報主，終自無期，黃雀謝恩，竟知何日。","sortOrder":221},
  {"id":"s_work_nvlt_85_223","chapterId":"ch_work_nvlt_85","text":"《禮記》曰：仲夏月，毋暴布，［不以荫切幹太陽事。］","sortOrder":223},
  {"id":"s_work_nvlt_85_224","chapterId":"ch_work_nvlt_85","text":"又曰：布帛精粗不中數，幅尺廣狹不中量，不鬻於市。","sortOrder":224},
  {"id":"s_work_nvlt_85_225","chapterId":"ch_work_nvlt_85","text":"《左傳》曰：諸侯攻偪陽，主人懸布，堇父登之，及堞而絕之，［偪陽人懸布以外，试勇者也。］墜則又懸之，蘇而复上者三，主人辭焉，乃退。","sortOrder":225},
  {"id":"s_work_nvlt_85_226","chapterId":"ch_work_nvlt_85","text":"《晏子》曰：景公謂《晏子》曰：東海中有水而赤，有棗華而不實，何也，晏子曰：昔秦缪公乘龍理天下，以黃帝布裹蒸棗，至海而投其棗布，故水赤，蒸棗，故華而不實，公曰：吾佯問子，對曰：婴聞佯問者亦佯對之，［事具棗部。］","sortOrder":226},
  {"id":"s_work_nvlt_85_227","chapterId":"ch_work_nvlt_85","text":"呂氏春秋曰：戎人見暴布者，問曰：何以為此莽莽也，指麻而示之，怒曰：孰灌灌可為莽莽也，［莽莽，長濬，灌灌，丛濬。］","sortOrder":227},
  {"id":"s_work_nvlt_85_228","chapterId":"ch_work_nvlt_85","text":"《韓子》曰：衛人有夫妻祷而祝曰：使我無故得百束布，其夫曰：何必少也，妻曰：益則子將取妾矣。","sortOrder":228},
  {"id":"s_work_nvlt_85_229","chapterId":"ch_work_nvlt_85","text":"《史記·張騫傳》曰：臣在大夏時，見邛竹杖蜀賨布。","sortOrder":229},
  {"id":"s_work_nvlt_85_230","chapterId":"ch_work_nvlt_85","text":"又曰：公儀休相魯，見布好而疾，出家婦，燔其機。","sortOrder":230},
  {"id":"s_work_nvlt_85_231","chapterId":"ch_work_nvlt_85","text":"又曰：货殖傳曰：通邑大都，布千鈞，比千乘家。","sortOrder":231},
  {"id":"s_work_nvlt_85_232","chapterId":"ch_work_nvlt_85","text":"《神異經》曰：南方有火山，長四十里，生不燼之木，晝夜火然，得暴風不炽，猛雨不滅，火中有鼠，重百斤，毛長二尺餘，細如絲，恒在火中，不出外而色白，以水逐沃之，即死，取其毛，織以作布，用之若垢汙，以火燒之，即清絜也，［事具火部。］","sortOrder":232},
  {"id":"s_work_nvlt_85_233","chapterId":"ch_work_nvlt_85","text":"《列女傳》曰：楚江乙母者，楚大夫江乙之母也，當恭王之時，乙為郢大夫，［郢，楚都，今南郡江陵。］有入王宮盜者，令尹以罪乙，請於王而黜之，處家無幾，其母亡布八尋，言令尹盜之，王方在小曲台，令尹侍焉，王謂母曰：令尹信盜也，寡人不為其富貴不行法焉，若不盜而誣之，楚國有常法，［常法，謂誣罪人，其罪罪之。］母曰：令尹非身盜之也，乃使人盜之，王曰：奈何，對曰：昔孫叔敖之為令尹也，道不拾遺，民不關閉，而盜賊自禁，今令尹之法治也，耳目不明，盜賊從橫，是故盜妾之布，是與使之何異，王曰：令尹在上，寇盜在下，令尹不知，有何罪焉，母曰：昔日妾子為郢大夫，人盜王宮中之物，妾子坐而黜之，妾子亦豈知之乎，終然坐之，令尹獨何以不坐，是為過也，王曰：善，非徒譏令尹。又譏寡人，令吏偿母之布，因賜金十镒，讓金布曰：妾豈貪货而幹王哉，王乃召江乙而用之。","sortOrder":233},
  {"id":"s_work_nvlt_85_234","chapterId":"ch_work_nvlt_85","text":"《漢書》曰：文帝徙淮南王長，道死，時民謠曰：一斗粟，尚可舂，一尺布，尚可縫，兄弟二人，不能相容。","sortOrder":234},
  {"id":"s_work_nvlt_85_235","chapterId":"ch_work_nvlt_85","text":"又曰：成帝許皇後上疏曰：妾夸布服糲食。","sortOrder":235},
  {"id":"s_work_nvlt_85_236","chapterId":"ch_work_nvlt_85","text":"又曰：太公以布為货，廣二尺二寸為幅，長四丈為疋。","sortOrder":236},
  {"id":"s_work_nvlt_85_237","chapterId":"ch_work_nvlt_85","text":"華峤《漢書》曰：王允與呂布及士孫瑞謀誅董卓，有人書呂字於布上，負而於市歌曰：布乎布乎，有告，卓不悟，三年四月，帝疾愈，卓入市，布持矛刺卓，兵士趣斬之。","sortOrder":237},
  {"id":"s_work_nvlt_85_238","chapterId":"ch_work_nvlt_85","text":"《吳越春秋》曰：越王允常，使民男女入山采葛，作黃絲布，獻之吳王。","sortOrder":238},
  {"id":"s_work_nvlt_85_239","chapterId":"ch_work_nvlt_85","text":"《先賢行状》曰：國中有盜牛者，牛主得盜者，曰：我邂逅迷惑，從今以後將改過，子既已宥，幸無使王烈聞之，人有以告烈者，烈以布一端遺之，曰：是知恥惡，知恥則善心將生，故與勸為善也。","sortOrder":239},
  {"id":"s_work_nvlt_85_240","chapterId":"ch_work_nvlt_85","text":"《典略》曰：蘇秦如趙，逢其鄰子於易水之上，從貸一疋布，約偿千金，鄰子不與。","sortOrder":240},
  {"id":"s_work_nvlt_85_241","chapterId":"ch_work_nvlt_85","text":"《廣志》曰：桐木，其華有白毳，取其毳淹織，緝以為布。","sortOrder":241},
  {"id":"s_work_nvlt_85_242","chapterId":"ch_work_nvlt_85","text":"聖證論曰：梁冀時，布有垢，則洗之於火。","sortOrder":242},
  {"id":"s_work_nvlt_85_243","chapterId":"ch_work_nvlt_85","text":"裴氏《廣州記》曰：蠻夷不蠶，采木綿為絮，皮圓當竹，剝古绿藤，績以為布。","sortOrder":243},
  {"id":"s_work_nvlt_85_244","chapterId":"ch_work_nvlt_85","text":"《燕書》曰：宋該，字宣弘，為右長史，太祖會群僚，以該性貪，故賜布百餘疋，令負而歸，重不能勝，乃至僵頓，以愧辱之。","sortOrder":244},
  {"id":"s_work_nvlt_85_245","chapterId":"ch_work_nvlt_85","text":"《俗說》曰：桓豹奴善乘騎，亦有極快馬，有一諸葛郎，自雲能走，與馬等，桓車騎以百疋布置埒，令豹奴乘馬，諸葛競走，先至者得布，便俱走，諸葛桓［○《太平御覽》八百二十作恒。］與馬齊，欲至埒頭，去布三尺許，諸葛一透坐布上，遂得之。","sortOrder":245},
  {"id":"s_work_nvlt_85_246","chapterId":"ch_work_nvlt_85","text":"《笑林》曰：沈珩弟峻，字叔山，有名譽，而性俭吝，張溫使蜀，峻入內良久，出語溫曰：向擇一端布，欲以送卿，而無粗者，溫嘉其能顯非。","sortOrder":246},
  {"id":"s_work_nvlt_85_247","chapterId":"ch_work_nvlt_85","text":"【賦】晉殷巨奇布賦曰：惟泰康二年，安南將軍廣州牧騰［按當作滕。］侯，作镇南方，餘時承乏，忝備下僚，俄而大秦國奉獻琛，來經於州，眾寶既麗，火布尤奇，乃作賦曰：伊荒服之外國，逮大秦以為名，仰皇風而悅化，超重譯而來庭，貢方物之綺麗，亦受氣於妙靈，美斯布之出類，禀太陽之純精，越常品乎意外，獨诡異而特生，森森丰林，在海之洲，煌煌烈火，禁焉靡休，天性固然，滋殖是由，牙萌炭中，類發燼隅，葉因焰絜，翘與炎敷，猋榮華寶，焚灼萼珠，丹辉電近，彤炯星流，飛耀冲霄，光赫天區，惟造化之所陶，理萬端而難察，燎無烁而不燋，在茲林而獨昵，火焚木而弗枯，木吐火而無竭，同五行而併在，與大椿其相率，乃采乃啗，是紡是績，每以為布，不盈數尺，以為布帊，服之無斁，既垢既汙，以焚為濯，投之朱爐，載燃載赫，停而泠之，皎絜凝白。","sortOrder":247},
  {"id":"s_work_nvlt_85_248","chapterId":"ch_work_nvlt_85","text":"【啟】梁劉孝綽謝越布啟曰：比納方绡，既輕且麗，珍邁龍水，妙越鳥夷。","sortOrder":248},
  {"id":"s_work_nvlt_85_249","chapterId":"ch_work_nvlt_85","text":"《藝文類聚》　唐·欧陽詢","sortOrder":249},
  {"id":"s_work_nvlt_86_1","chapterId":"ch_work_nvlt_86","text":"卷八十六果部上","sortOrder":1},
  {"id":"s_work_nvlt_86_2","chapterId":"ch_work_nvlt_86","text":"○李桃梅梨甘橘櫻桃石榴柿楂柰","sortOrder":2},
  {"id":"s_work_nvlt_86_4","chapterId":"ch_work_nvlt_86","text":"《春秋運斗枢》曰：玉衡星散為李。","sortOrder":4},
  {"id":"s_work_nvlt_86_5","chapterId":"ch_work_nvlt_86","text":"《爾雅》曰：休無實李，［一名趙李。］","sortOrder":5},
  {"id":"s_work_nvlt_86_6","chapterId":"ch_work_nvlt_86","text":"《毛詩》：投我以木李，報之以琼玖。","sortOrder":6},
  {"id":"s_work_nvlt_86_7","chapterId":"ch_work_nvlt_86","text":"又曰：何彼秾矣，華如桃李。","sortOrder":7},
  {"id":"s_work_nvlt_86_8","chapterId":"ch_work_nvlt_86","text":"《韓詩外傳》曰：子质仕魏文侯，獲罪而北遊，謂簡主曰：吾所树堂上之士半，朝廷之大夫半，邊境之人亦半，今堂之人惡我於君，朝廷之士危我於法，邊境之人劫我矣，簡主曰：夫春树桃李，夏得荫其下，秋得食其實，春树蒺梨，夏不得采其葉，秋得其刺焉，今子所树，非其人也。","sortOrder":8},
  {"id":"s_work_nvlt_86_9","chapterId":"ch_work_nvlt_86","text":"東方朔占曰：朔與弟子俱行，朔渴，令弟子叩道邊家門，不知室主姓名，呼不應，朔复往，見博勞飛集其家李树上，朔謂弟子曰：主人當姓李名博，汝呼當應，室中人果有姓李名博出，與朔相見，即入取飲與之。","sortOrder":9},
  {"id":"s_work_nvlt_86_10","chapterId":"ch_work_nvlt_86","text":"魯安生別傳，李少君曰：鍾山之李大如瓶。","sortOrder":10},
  {"id":"s_work_nvlt_86_11","chapterId":"ch_work_nvlt_86","text":"《神仙傳》曰：老子之母，適到李树之下，生老子，老子生而能言，指李树曰：以此為我姓。","sortOrder":11},
  {"id":"s_work_nvlt_86_12","chapterId":"ch_work_nvlt_86","text":"《抱朴子》曰：五原蔡綖，入山而還，其［《太平御覽》九百六十八其上有欺字。］家人雲，到崑崙山，有玉李，形如世間者，但光明洞澈而堅，以玉井水洗之，便软而可食。","sortOrder":12},
  {"id":"s_work_nvlt_86_13","chapterId":"ch_work_nvlt_86","text":"《廣志》曰：車下李，車上李。","sortOrder":13},
  {"id":"s_work_nvlt_86_14","chapterId":"ch_work_nvlt_86","text":"又曰：麥李細小，有溝道，有青李馬肝李赤李房陵李。","sortOrder":14},
  {"id":"s_work_nvlt_86_15","chapterId":"ch_work_nvlt_86","text":"《世說》曰：王戎年七歲，嘗與諸小兒遊，睹看道邊李树，有子折枝，諸小兒競走取之，惟戎不動，人問之，答曰：树在道邊而多子，此必苦李也，取之信然。","sortOrder":15},
  {"id":"s_work_nvlt_86_16","chapterId":"ch_work_nvlt_86","text":"又曰：王安丰有好李，常賣之，恐人得种，常鑽其核。","sortOrder":16},
  {"id":"s_work_nvlt_86_17","chapterId":"ch_work_nvlt_86","text":"《列子》曰：師門，嘯父弟子，食桃李葩。","sortOrder":17},
  {"id":"s_work_nvlt_86_18","chapterId":"ch_work_nvlt_86","text":"孟子，匡章曰：陳仲子豈不誠廉士哉，居於陵，三日不食，耳目無聞見，井上有李，螬食實者過半，陳仲子匍匐往食之，三咽而後耳有聞，眼有見也，李虫食之過半。","sortOrder":18},
  {"id":"s_work_nvlt_86_19","chapterId":"ch_work_nvlt_86","text":"傅玄李賦，潛實內結，丰彩外盈，翠质朱变，形隨運成。","sortOrder":19},
  {"id":"s_work_nvlt_86_20","chapterId":"ch_work_nvlt_86","text":"閒居賦，房陵朱仲之李。","sortOrder":20},
  {"id":"s_work_nvlt_86_21","chapterId":"ch_work_nvlt_86","text":"左傳［按本條非《左傳》：《太平御覽》九百六十八作左思齊都賦曰露桃霜李。又王逸荔支賦曰房陵縹李，此有脱訛。］曰：齊都露霜李，房陵縹李。","sortOrder":21},
  {"id":"s_work_nvlt_86_22","chapterId":"ch_work_nvlt_86","text":"《詩》曰：丘中有李，彼留之子，北山有李，投我以桃，報之以李。","sortOrder":22},
  {"id":"s_work_nvlt_86_23","chapterId":"ch_work_nvlt_86","text":"《西京雜記》：漢武修上林苑，群臣各獻其果树，有合枝李、朱李、黃李、青房李、燕李、獲李、沉朱李、浮素李。","sortOrder":23},
  {"id":"s_work_nvlt_86_24","chapterId":"ch_work_nvlt_86","text":"《洞冥記》：琳國去長安九萬里，生玉葉李，色如碧玉，數十歲一熟，味酸，昔韓眾嘗餌此李，因名韓眾李。","sortOrder":24},
  {"id":"s_work_nvlt_86_25","chapterId":"ch_work_nvlt_86","text":"《禮》：食棗桃李，弗致於核。","sortOrder":25},
  {"id":"s_work_nvlt_86_26","chapterId":"ch_work_nvlt_86","text":"魏文帝與吳质書，沉朱李於寒水。","sortOrder":26},
  {"id":"s_work_nvlt_86_27","chapterId":"ch_work_nvlt_86","text":"《荆州記》：房陵有好李。","sortOrder":27},
  {"id":"s_work_nvlt_86_28","chapterId":"ch_work_nvlt_86","text":"《列異傳》：度索君謂南海君曰：昔庐山共食白李，未久，已三千載。","sortOrder":28},
  {"id":"s_work_nvlt_86_29","chapterId":"ch_work_nvlt_86","text":"《風土記》曰：南郡有細李，有青皮李。","sortOrder":29},
  {"id":"s_work_nvlt_86_30","chapterId":"ch_work_nvlt_86","text":"《文選》：南國有佳人，容華若桃李。","sortOrder":30},
  {"id":"s_work_nvlt_86_31","chapterId":"ch_work_nvlt_86","text":"【詩】古歌詞曰：桃生露井上，李生桃树傍，虫來齧桃根，李树代桃僵，树木身相代，骨肉還相忘。","sortOrder":31},
  {"id":"s_work_nvlt_86_32","chapterId":"ch_work_nvlt_86","text":"梁沈約詠李詩曰：青玉冠西海，碧石弥外區，化為中園實，其下成路衢，色润房陵縹，味奪寒水朱。","sortOrder":32},
  {"id":"s_work_nvlt_86_33","chapterId":"ch_work_nvlt_86","text":"隋江總詠李詩曰：嘉树春風早，春風花落新，但見成蹊處，幾得正冠人，當知露井侧，复與妖桃鄰。","sortOrder":33},
  {"id":"s_work_nvlt_86_34","chapterId":"ch_work_nvlt_86","text":"【賦】晉傅玄李賦曰：潛實內結，丰彩外盈，翠质未变，形隨運成，种別類分，或朱或黃，甘酸得適，美逾蜜房，浮采點駮，赤者如丹，入口流溅，逸味難原。","sortOrder":34},
  {"id":"s_work_nvlt_86_36","chapterId":"ch_work_nvlt_86","text":"《春秋運斗枢》曰：玉衡星散為桃。","sortOrder":36},
  {"id":"s_work_nvlt_86_37","chapterId":"ch_work_nvlt_86","text":"《本草經》曰：枭桃在树不落，殺百鬼。","sortOrder":37},
  {"id":"s_work_nvlt_86_38","chapterId":"ch_work_nvlt_86","text":"武王克商後，放牛馬於桃林之野。","sortOrder":38},
  {"id":"s_work_nvlt_86_39","chapterId":"ch_work_nvlt_86","text":"《禮記月令》曰：仲春之月，桃始華。","sortOrder":39},
  {"id":"s_work_nvlt_86_40","chapterId":"ch_work_nvlt_86","text":"《毛詩》曰：何彼秾矣，華如桃李。","sortOrder":40},
  {"id":"s_work_nvlt_86_41","chapterId":"ch_work_nvlt_86","text":"又曰：園有桃，其實之殽。","sortOrder":41},
  {"id":"s_work_nvlt_86_42","chapterId":"ch_work_nvlt_86","text":"又曰：桃之夭夭，灼灼其華，桃之夭夭，其葉蓁蓁。","sortOrder":42},
  {"id":"s_work_nvlt_86_43","chapterId":"ch_work_nvlt_86","text":"又曰：投我以木桃，報之以琼瑤。","sortOrder":43},
  {"id":"s_work_nvlt_86_44","chapterId":"ch_work_nvlt_86","text":"《易通卦验》：驚蟄曰大壮，初九，桃不花，仓库多火。","sortOrder":44},
  {"id":"s_work_nvlt_86_45","chapterId":"ch_work_nvlt_86","text":"東海有山，名度索山，有大桃树，屈盤三千里，曰蟠桃，［按本條嚴可均校本，《初學記》二十八作山海經。］","sortOrder":45},
  {"id":"s_work_nvlt_86_46","chapterId":"ch_work_nvlt_86","text":"《漢書》曰：漢惠帝五年，十月桃花。","sortOrder":46},
  {"id":"s_work_nvlt_86_47","chapterId":"ch_work_nvlt_86","text":"《孫卿子》曰：桃李蒨粲於一，時至乃殺。","sortOrder":47},
  {"id":"s_work_nvlt_86_48","chapterId":"ch_work_nvlt_86","text":"《離骚》［《太平御覽》九百六十七作楚辭。］：斬伐橘柚，列树苦，［○御覽作苦桃，此有脱訛。］","sortOrder":48},
  {"id":"s_work_nvlt_86_49","chapterId":"ch_work_nvlt_86","text":"《文選》曰：南國有佳人，容華若桃李。","sortOrder":49},
  {"id":"s_work_nvlt_86_50","chapterId":"ch_work_nvlt_86","text":"桃生露井上。","sortOrder":50},
  {"id":"s_work_nvlt_86_51","chapterId":"ch_work_nvlt_86","text":"又，艳陽桃李節，山桃發紅萼。","sortOrder":51},
  {"id":"s_work_nvlt_86_52","chapterId":"ch_work_nvlt_86","text":"《拾遺記》曰：螃螗山去扶桑五萬里，日所不及，地寒則桃树千围，其花青黑色，萬歲一實。","sortOrder":52},
  {"id":"s_work_nvlt_86_53","chapterId":"ch_work_nvlt_86","text":"漢明帝時，常山獻巨桃核，其桃霜下花，至暑方熟，使植園林，［本條《太平御覽》九百六十七作王子年拾遺記。］","sortOrder":53},
  {"id":"s_work_nvlt_86_54","chapterId":"ch_work_nvlt_86","text":"《西京雜記》：漢武初修上林苑，群臣各獻果，有緗核桃紫文桃金城桃。","sortOrder":54},
  {"id":"s_work_nvlt_86_55","chapterId":"ch_work_nvlt_86","text":"《歲時記》：桃者五行之精，壓伏邪氣，製百鬼。","sortOrder":55},
  {"id":"s_work_nvlt_86_56","chapterId":"ch_work_nvlt_86","text":"《鹽鐵論》：桃李之實多者，來歲之穰。","sortOrder":56},
  {"id":"s_work_nvlt_86_57","chapterId":"ch_work_nvlt_86","text":"有桃花坞。","sortOrder":57},
  {"id":"s_work_nvlt_86_58","chapterId":"ch_work_nvlt_86","text":"桃花綬，典術曰：桃者五木之精也，今之作桃符著門上，壓邪氣，此仙木也。","sortOrder":58},
  {"id":"s_work_nvlt_86_59","chapterId":"ch_work_nvlt_86","text":"《周書》：秦吏趙凯之，私恨告國民吳旦生盜食宗廟御桃，旦生對曰：民不敢食也，王曰：剖其腹，出其桃，史記惡而書之曰：食桃之肉，當有遺核，王不知此，而剖人腹以求桃，非理也，［本條《太平御覽》九百六十七作鍾離意別傳。］《晏子》曰：公孫捷田开疆古冶子，事景公，勇而無禮，晏子言於公，餽之二桃，曰：三子計功而食桃，公孫曰：吾再拜隱［晏子春秋二作搏乳。］虎，功可以食，田曰：吾杖兵而御三軍者再，功可以食，古冶子曰：吾嘗濟河，黿衔左驂，冶潛行水底，逆流百步，從流九里，得黿頭，功可以食，二子曰：吾勇不若子，功不逮子，取桃不讓，是貪也，然而不死，無勇也，刎頸而死，冶曰：二子死之，冶獨不逮。又刎頸而死。","sortOrder":59},
  {"id":"s_work_nvlt_86_60","chapterId":"ch_work_nvlt_86","text":"《韓子》曰：昔者弥子瑕有寵於衛君，與君遊於果園，食桃而甘，以其半啖君，君曰：忠乎，□忘其口而啖寡人，及弥子瑕色衰愛弛，得罪於君，君曰：是故嘗啖我以餘桃。","sortOrder":60},
  {"id":"s_work_nvlt_86_61","chapterId":"ch_work_nvlt_86","text":"又曰：孔子侍坐於魯哀公，哀公賜之桃與黍，仲尼先飯黍而後啖桃，哀公曰：黍以雪桃也，對曰：丘知之矣，夫黍五穀之長，而桃為下，君子以賤雪貴，不聞以貴雪賤也。","sortOrder":61},
  {"id":"s_work_nvlt_86_62","chapterId":"ch_work_nvlt_86","text":"莊子：插桃枝於戶，連灰其下，童子入不畏，而鬼畏之，是鬼智不如童子也。","sortOrder":62},
  {"id":"s_work_nvlt_86_63","chapterId":"ch_work_nvlt_86","text":"《戰國策》曰：孟嘗君將入秦，蘇秦往見之，孟嘗曰：人事者，吾以知之，所未聞者，獨鬼事耳，秦曰：臣之來，固且以鬼事見君矣，臣來過淄上，有土偶人焉，與桃梗相與語，桃梗謂土偶人曰：子西岸之土也，埏子以為人，至歲八月，降雨下，淄水至，則子殘矣，曰：不然，吾西岸之土，殘則复西岸耳，子東園之桃梗也，刻削子以為人，降雨下，淄水至，流子而去，則子漂漂者將何如矣，今秦四塞之國，譬如虎口，而君入之，則臣不知君所如矣，孟嘗乃止。","sortOrder":63},
  {"id":"s_work_nvlt_86_64","chapterId":"ch_work_nvlt_86","text":"《史記》曰：桃李不言，下自成蹊。","sortOrder":64},
  {"id":"s_work_nvlt_86_65","chapterId":"ch_work_nvlt_86","text":"淮南《萬畢術》曰：孤桃枝之券，令雞夜鳴，［取孤桃南北行，枝長三尺，折以為券，涂以三歲雄雞血，夜居栖下則鳴。］","sortOrder":65},
  {"id":"s_work_nvlt_86_66","chapterId":"ch_work_nvlt_86","text":"《漢武故事》曰：東郡獻短人，呼東方朔，朔至，短人因指朔謂上曰：西王母种桃，三千歲一為子，此兒不良也，已三過偷之矣，後西王母下，出桃七枚，母因啖二，以五枚與帝，帝留核著前，母問曰：用此何，上曰：此桃美，欲种之，母笑曰：此桃三千年一著子，非下土所植也。","sortOrder":66},
  {"id":"s_work_nvlt_86_67","chapterId":"ch_work_nvlt_86","text":"《風俗通》曰：黃帝書，稱上古之時，有兄弟二人，荼與鬱律，度朔山上桃树下，簡百鬼，妄禍人，則縛以苇索，執以食虎，於是縣官以腊除夕，飾桃人，垂苇索，畫虎於門，效前事也。","sortOrder":67},
  {"id":"s_work_nvlt_86_68","chapterId":"ch_work_nvlt_86","text":"《山海經》曰：桃树屈蟠三千里，［按本條已見前。］","sortOrder":68},
  {"id":"s_work_nvlt_86_69","chapterId":"ch_work_nvlt_86","text":"《列仙傳》曰：葛由，羌人，好剋木作羊賣之，騎羊入蜀，蜀中王侯貴人追之，上綏山，皆得仙，故里喭曰：得綏山一桃，雖不能仙，亦足以豪，［事具獸部。］","sortOrder":69},
  {"id":"s_work_nvlt_86_70","chapterId":"ch_work_nvlt_86","text":"尹喜內傳曰：老子西遊，省太真王母，共食碧桃紫梨。","sortOrder":70},
  {"id":"s_work_nvlt_86_71","chapterId":"ch_work_nvlt_86","text":"《玄中記》曰：木子之大者，有積石山之桃實焉，大如十斛籠。","sortOrder":71},
  {"id":"s_work_nvlt_86_72","chapterId":"ch_work_nvlt_86","text":"《神仙傳》曰：樊夫人與劉刚，俱有道術，各自言勝，中庭有大桃树，夫妻各咒其一，桃便斗相击，良久，所咒桃走出篱外。","sortOrder":72},
  {"id":"s_work_nvlt_86_73","chapterId":"ch_work_nvlt_86","text":"又曰：張陵，沛人也，弟子趙升，就陵受學，陵以七事试之，弟七试者，陵與諸弟子登雲台山，絕巖上有一桃树，旁生石壁，下臨不测，去三四丈，有桃大實，陵謂諸弟子曰：得此桃者，當告以道要，弟子皆流汗，無敢视者，升曰：神人所護，何险之有，乃從上自掷，正投桃树上，取桃滿懷，而石壁峻峭，不能得還，乃掷桃树上二百二枚，陵分桃賜諸弟子，餘二枚，陵自食一，留一以待升，陵乃申手引升，升忽已還，乃以向一桃與升。","sortOrder":73},
  {"id":"s_work_nvlt_86_74","chapterId":"ch_work_nvlt_86","text":"又曰：高丘公服餌桃膠得仙。","sortOrder":74},
  {"id":"s_work_nvlt_86_75","chapterId":"ch_work_nvlt_86","text":"晉《起居註》曰：鹹和六年，寧州上言，甘露降城北園林桃李等树。","sortOrder":75},
  {"id":"s_work_nvlt_86_76","chapterId":"ch_work_nvlt_86","text":"陶潛桃花源記曰：晉太康［《太平御覽》九百六十七作元。］中，武陵人捕魚，從溪而行，忽逢桃花林，夹兩岸數百步，無雜木，芳華芬暧，落英繽紛，漁人異之，前行窮林，林盡見山，山有小口，仿佛有光，便舍舡步入，初極狹，行四五十步，豁然开朗，邑室連接，雞犬相聞，男女被發，怡然併足，見漁人大驚，問所從來，要還，為設酒食，雲先世避秦難，率妻子來此，遂與外隔絕，不知有漢，不論魏晉也，既出，白太守，太守遣人隨而尋之，迷不复得路。","sortOrder":76},
  {"id":"s_work_nvlt_86_77","chapterId":"ch_work_nvlt_86","text":"甄異傳曰：谯郡夏侯文規，亡後見形還家，經庭前桃树邊過，曰：此桃我昔所种，子乃美好，其婦曰：人言亡者畏桃，君何不畏耶，答曰：桃東南枝長二尺八寸向日者，憎之，或亦不畏也。","sortOrder":77},
  {"id":"s_work_nvlt_86_78","chapterId":"ch_work_nvlt_86","text":"《世說》曰：桓玄素輕桓崖，桓崖在京，京下有好桃，玄連就求，遂不辯得佳者，玄與殷仲文書，比為嗤笑，雲德之休明，肅慎貢其楛矢，如其不爾，篱壁間物，亦不可得。","sortOrder":78},
  {"id":"s_work_nvlt_86_79","chapterId":"ch_work_nvlt_86","text":"《鄴中記》曰：石虎苑中有勾鼻桃，重二斤半。","sortOrder":79},
  {"id":"s_work_nvlt_86_80","chapterId":"ch_work_nvlt_86","text":"《晉宮閣名》曰：華林園桃，七百三十八株，白桃三株，侯桃三株。","sortOrder":80},
  {"id":"s_work_nvlt_86_81","chapterId":"ch_work_nvlt_86","text":"《南康記》曰：南康王［《太平御覽》九百六十七作玉。］山有石桃，故老雲，古有寒桃，生於嶺巔，隱淪之士，將大取其實，因变成石焉。","sortOrder":81},
  {"id":"s_work_nvlt_86_82","chapterId":"ch_work_nvlt_86","text":"妒女記曰：武歷陽女，嫁阮宣武，絕忌，家有一桃树，華葉灼耀，宣叹美之，即便大怒，使婢取刀斫树，摧折其華。","sortOrder":82},
  {"id":"s_work_nvlt_86_83","chapterId":"ch_work_nvlt_86","text":"【詩】梁簡文帝詠初桃詩曰：初桃麗新采，照地吐其芳，枝間留紫燕，葉里發輕香，飛花入露井，交榦拂華堂，若暎窗前柳，懸疑紅粉妆。","sortOrder":83},
  {"id":"s_work_nvlt_86_84","chapterId":"ch_work_nvlt_86","text":"梁任昉詠池邊桃詩曰：已謝西王苑，复揖綏山枝，聊逢賞者愛，栖趾傍莲池，开紅春灼灼，結實夏離離。","sortOrder":84},
  {"id":"s_work_nvlt_86_85","chapterId":"ch_work_nvlt_86","text":"【賦】晉傅玄桃賦曰：華落實結，與時刚柔，既甘且脆，入口消流，亦有冬桃，冷侔冰霜，和神適意，咨口所嘗。","sortOrder":85},
  {"id":"s_work_nvlt_86_86","chapterId":"ch_work_nvlt_86","text":"宋伍辑之園桃賦曰：嗟王母之奇果，特華實兮兼副，既陶照之夏成。又凌寒而冬就，嗟異殖兮難拔，亦晚枯兮先葳，農黃品其味，漢帝驚其珍，林休反耕之牛，宅树同惡之神，景毙勇於不足，弥增罪於甘分，雖無言兮成蹊，叵充肴於魏君，時令載始，周南申章，瞻擇有製，藥齊惟良，魯拂柩以悔荆，楚供弧以事王。","sortOrder":86},
  {"id":"s_work_nvlt_86_87","chapterId":"ch_work_nvlt_86","text":"陳張正見衰桃賦曰：巖巖秀峰，吐桂榮松，獨夭桃之灼灼，輕擢采於寒蹤，爾乃萬株成錦，千林似翼，苔畫波文，花然树色，發秦源而逸氣，飄漢綬而流芳，譬蘭棋之夜炷，似明鏡之朝妆，成蹊迾迳，光崖艳氾，間真定之蒼梨，雜房陵之縹李，芬芳難歇，照曜無儔，舒若霞光欲起，散似電采將收，既而風落新枝，霜飛故葉，叹垂釣之妖童，怨傾城之麗妾。","sortOrder":87},
  {"id":"s_work_nvlt_86_88","chapterId":"ch_work_nvlt_86","text":"【頌】梁江淹山桃頌曰：惟園有肴，惟山有丛，丹蒍擎露，紫榮繞風，引霧如電，暎煙成虹，伊春之秀，乃華之宗。","sortOrder":88},
  {"id":"s_work_nvlt_86_90","chapterId":"ch_work_nvlt_86","text":"《尚書》曰：若作和羹，爾惟鹽梅。","sortOrder":90},
  {"id":"s_work_nvlt_86_91","chapterId":"ch_work_nvlt_86","text":"《大戴禮》曰：夏小正曰：五月煮梅為豆實。","sortOrder":91},
  {"id":"s_work_nvlt_86_92","chapterId":"ch_work_nvlt_86","text":"毛詩召南曰：摽有梅，男女及時也，被文王之化。","sortOrder":92},
  {"id":"s_work_nvlt_86_93","chapterId":"ch_work_nvlt_86","text":"又，摽有梅，其實七兮。","sortOrder":93},
  {"id":"s_work_nvlt_86_94","chapterId":"ch_work_nvlt_86","text":"《東方朔傳》曰：朔門生三人俱行，乃見一鳩，一生曰：今當得酒，一生曰：其酒必酸，一生曰：雖得酒，不得飲也，三生皆到，須臾，主人出酒，即安樽於地而覆之，訖不得酒，乃問其故，曰：出門見鳩飲水，故知得酒，鳩飛集梅树，故知酒酸，鳩飛去，所集枝折，故知不得飲之，《神異經》曰：橫公魚，長七八尺，形状如鯉而目赤，晝在湖中，夜化為人，刺之不入，煮之不死，以乌梅二七煮之，即熟，食之治邪病。","sortOrder":94},
  {"id":"s_work_nvlt_86_95","chapterId":"ch_work_nvlt_86","text":"《語林》曰：范任［北堂書鈔一百三十五，《太平御覽》七百十七，九百七十，事類賦註二十六作汪。］能啖梅，人常致一斛奁，留信食之，須臾而盡。","sortOrder":95},
  {"id":"s_work_nvlt_86_96","chapterId":"ch_work_nvlt_86","text":"五［《太平御覽》九百七十作伍。］端休江陵記曰：洪亭村下有梅回村，舊雲是梅槐合生成树，是以詔之，今音訛，謂之梅槐，［御覽作回。］","sortOrder":96},
  {"id":"s_work_nvlt_86_97","chapterId":"ch_work_nvlt_86","text":"述異記，嘉興縣朱休之，有一弟，宋元嘉中，兄弟對坐，家有一犬來，向休之蹲，遍视二人，遂搖頭而笑曰：言我不能歌，聽我歌梅花，今年故复可，柰汝明年何，其家驚懼，斬犬，榜首路侧，至來歲梅花時，兄弟相斗，弟奋戟傷兄，官收治，併被囚系，經歲得免，至夏，舉家時疾，母及兄弟皆死。","sortOrder":97},
  {"id":"s_work_nvlt_86_98","chapterId":"ch_work_nvlt_86","text":"《詩》曰：山有嘉卉，侯栗侯梅。","sortOrder":98},
  {"id":"s_work_nvlt_86_99","chapterId":"ch_work_nvlt_86","text":"《淮南子》曰：梅以為百人酸不足一梅不足為一人之，［句有脱，淮南說林篇作百梅足以為百人酸，一梅不足以為一人和。］喻眾能濟。","sortOrder":99},
  {"id":"s_work_nvlt_86_100","chapterId":"ch_work_nvlt_86","text":"《選》曰：今朝梅树下，定有詠花人。","sortOrder":100},
  {"id":"s_work_nvlt_86_101","chapterId":"ch_work_nvlt_86","text":"本草，梅核能益氣不飢。","sortOrder":101},
  {"id":"s_work_nvlt_86_102","chapterId":"ch_work_nvlt_86","text":"上林有双梅紫梅同心梅粗枝梅，［《太平御覽》九百七十作《西京雜記》曰：］疏，［本條《初學記》二十八作詩義疏。］梅曝乾為腊，〈月隺〉韭中。又可以含之，口香。","sortOrder":102},
  {"id":"s_work_nvlt_86_103","chapterId":"ch_work_nvlt_86","text":"【詩】梁簡文帝雪里觅梅花詩曰：絕訝梅花晚，爭來雪里窥，下枝低可見，高處遠難知，定須還翦采，學作兩三枝。","sortOrder":103},
  {"id":"s_work_nvlt_86_104","chapterId":"ch_work_nvlt_86","text":"梁元帝詠梅詩曰：梅含今春树，還臨光日池，人懷前歲憶，花發故年枝。","sortOrder":104},
  {"id":"s_work_nvlt_86_105","chapterId":"ch_work_nvlt_86","text":"梁鮑泉詠梅花詩曰：可怜階下梅，飄荡逐風回，度帘拂羅幌，萦窗落梳台，乍隨纖手去，還因插鬢來，客心屢看此，愁眉斂詎开。","sortOrder":105},
  {"id":"s_work_nvlt_86_106","chapterId":"ch_work_nvlt_86","text":"梁何遜詠早梅詩曰：兔園摽物序，驚時最是梅，衔霜當路發，映雪擬寒开，枝橫却月觀，花繞凌風台，知應早飄落，故逐上春來。","sortOrder":106},
  {"id":"s_work_nvlt_86_107","chapterId":"ch_work_nvlt_86","text":"陳陰铿詠雪里梅詩曰：春近寒雖轉，梅舒雪尚飄，從風還共落，照日不俱銷，葉开隨足影，花多助重條，今來漸異昨，向晚判勝朝。","sortOrder":107},
  {"id":"s_work_nvlt_86_108","chapterId":"ch_work_nvlt_86","text":"陳謝燮早梅詩曰：迎春故早發，獨自不疑寒，畏落眾花後，無人別意看。","sortOrder":108},
  {"id":"s_work_nvlt_86_109","chapterId":"ch_work_nvlt_86","text":"隋江總梅花落詩，臈月正月早驚春，眾花未發梅花新，梅花芬芳臨玉台，朝攀晚折還复开，滿酌金卮催玉柱，落梅树下宜歌舞，金穀萬株連綺甍，梅花隱處隱娇湋，桃李佳人欲相照，摘蕊牵花來併笑，楊柳條青樓上輕，梅花色白雪中明，橫笛短箫凄复咽，誰知柏梁聲不絕。","sortOrder":109},
  {"id":"s_work_nvlt_86_110","chapterId":"ch_work_nvlt_86","text":"【賦】梁簡文帝梅花賦曰：梅花特早，偏能識春，或承陽而發金，乍雜雪而被銀，摽半落而飛空，香隨風而遠度，掛靡靡之遊絲，雜霏霏之晨霧，爭樓上之落粉，奪機中之織素，乍开華而傍巘，或含影而臨池，向玉階而結采，拂網戶而低枝，七言表柏梁之詠，三軍傳魏武之奇，於是重閨佳麗，濬婉心閒，怜早花之驚節，訝春光之遣寒，顧影丹墀，弄此娇姿，春風吹梅畏落盡，賤妾為此斂娥眉，花色持相比，恒愁恐失時。","sortOrder":110},
  {"id":"s_work_nvlt_86_111","chapterId":"ch_work_nvlt_86","text":"陳暄食梅賦曰：魏無林而止渴，范留信而前嘗，賜一時之名果，遂懷核而矜莊，昔詠酸棗之台，今食酸味之梅，眼同曹瞞之見形，異韦誕之聞雷，焜既咽而思鳩杖，悶欲死而相仙杯，非投壶而天笑，等王孫而客咍。","sortOrder":111},
  {"id":"s_work_nvlt_86_113","chapterId":"ch_work_nvlt_86","text":"《莊子》曰：三王五帝之禮義法度不同，譬其猶楂梨橘柚耶，其味相反，而皆可於口。","sortOrder":113},
  {"id":"s_work_nvlt_86_114","chapterId":"ch_work_nvlt_86","text":"《神異經》曰：東方有树，高百丈，敷張自轉，［《太平御覽》九百六十九作辅。］葉長一丈，廣六尺，名曰梨，其子径三尺，剖之白如素，食之地仙，可入水火。","sortOrder":114},
  {"id":"s_work_nvlt_86_115","chapterId":"ch_work_nvlt_86","text":"《漢武內傳》曰：太上之藥，果有玄光梨。","sortOrder":115},
  {"id":"s_work_nvlt_86_116","chapterId":"ch_work_nvlt_86","text":"神仙傳，介象為吳主所徵，在武昌，連求去不許，象言病，帝以美梨一奁賜之，象死，殯而埋之，以日中時死，其晡時到建業，以所賜梨付守苑吏种之。","sortOrder":116},
  {"id":"s_work_nvlt_86_117","chapterId":"ch_work_nvlt_86","text":"《幽明錄》曰：成彪兄丧，晝哭夜泣，兄提二升酒，一盤梨，就之，引酌相歡，彪問略答，彪悲咽，問兄今在天上，福多苦多。又弗應，肅然無言，泻餘酒著甌中，挈罌而去。","sortOrder":117},
  {"id":"s_work_nvlt_86_118","chapterId":"ch_work_nvlt_86","text":"《曹瞞傳》曰：王自漢中至洛陽，起建始殿，使工蘇越，徙美梨，掘之，根盡血出，越白状，王躬自视之，以為不祥，還遂寢疾。","sortOrder":118},
  {"id":"s_work_nvlt_86_119","chapterId":"ch_work_nvlt_86","text":"何晏《九州論》曰：安平好棗，中山好栗，魏郡好杏，河內好稻，真定好梨。","sortOrder":119},
  {"id":"s_work_nvlt_86_120","chapterId":"ch_work_nvlt_86","text":"《文士傳》：孔融年四歲，與諸兄食梨，辄取其小者，人問其故。答曰：小兒法當取小者。","sortOrder":120},
  {"id":"s_work_nvlt_86_121","chapterId":"ch_work_nvlt_86","text":"《尹喜內傳》曰：老子西遊，省太真王母，共食紫梨。","sortOrder":121},
  {"id":"s_work_nvlt_86_122","chapterId":"ch_work_nvlt_86","text":"段龟龍《涼州記》曰：呂光時，敦煌太守獻同心梨。","sortOrder":122},
  {"id":"s_work_nvlt_86_123","chapterId":"ch_work_nvlt_86","text":"《三秦記》曰：漢武帝園，一名樊川，一名御宿，有大梨，如五升瓶，落地則破，其主取者，以布囊承之，名含消梨。","sortOrder":123},
  {"id":"s_work_nvlt_86_124","chapterId":"ch_work_nvlt_86","text":"魏文詔曰：真定郡梨，甘若蜜，脆若凌，可以解煩飴。","sortOrder":124},
  {"id":"s_work_nvlt_86_125","chapterId":"ch_work_nvlt_86","text":"永嘉記曰：青田村人多种梨，有一株名曰官梨，一围五寸，以供獻，名御梨。","sortOrder":125},
  {"id":"s_work_nvlt_86_126","chapterId":"ch_work_nvlt_86","text":"武［按前引作漢武內傳。］太上之果，有玄光梨，王瓒梨頌，太康十一年，梨树四枝，與中枝合生於囿，皇太子令侍中頌。","sortOrder":126},
  {"id":"s_work_nvlt_86_127","chapterId":"ch_work_nvlt_86","text":"《廣志》：郡集［《初學記》二十八，《太平御覽》九百六十九作廣都。］梨重六斤，常山真定山陽鉅野新丰箭穀，皆多梨也。","sortOrder":127},
  {"id":"s_work_nvlt_86_128","chapterId":"ch_work_nvlt_86","text":"敦煌太守獻同心梨。","sortOrder":128},
  {"id":"s_work_nvlt_86_129","chapterId":"ch_work_nvlt_86","text":"老子西遊，太真王母共食碧梨紫梨，［本條桃篇引作尹喜內傳，碧梨作碧桃。］","sortOrder":129},
  {"id":"s_work_nvlt_86_130","chapterId":"ch_work_nvlt_86","text":"潘嶽閒居賦，張公大穀之梨。","sortOrder":130},
  {"id":"s_work_nvlt_86_131","chapterId":"ch_work_nvlt_86","text":"《洞冥記》雲：涂山之背，梨大如升，色紫，千年一花，亦曰紫輕梨。","sortOrder":131},
  {"id":"s_work_nvlt_86_132","chapterId":"ch_work_nvlt_86","text":"南康歸山，［本條《太平御覽》九百六十六作異苑，歸下有美字。］石城內有梨熟，人食其實，任意取足，持歸家，人啖辄病，或顛仆失径亡命，燀［○明本作味。］似秋梨。","sortOrder":132},
  {"id":"s_work_nvlt_86_133","chapterId":"ch_work_nvlt_86","text":"【詩】梁沈約西地梨詩曰：列茂河陽苑，蓄紫濫觴隈，翻黃秋沃若，落素春徘徊。","sortOrder":133},
  {"id":"s_work_nvlt_86_134","chapterId":"ch_work_nvlt_86","text":"梁劉孝綽詠梨花應令詩曰：玉壘稱津润，金穀訪芳菲，詎疋龍樓下，素蕊暎朱扉，雜雨疑露落，因風似蝶飛，豈不怜飄墜，原入九重闈。","sortOrder":134},
  {"id":"s_work_nvlt_86_135","chapterId":"ch_work_nvlt_86","text":"【頌】晉王贊梨树頌曰：嘉木時生，瑞我皇祚，脩榦外扬，隆枝內附，翌翌皇储，克光其敬，神啟其和，人隆其盛，降自玄圃，合體連性，時惟令月，躬親北林，樂在同人，如蘭如金，木之期應，乃同其心，同心之生，啟自神明，在心斯動，於言斯形，先民有則，稱詩表情，惟永作歌，以休厥靈。","sortOrder":135},
  {"id":"s_work_nvlt_86_136","chapterId":"ch_work_nvlt_86","text":"【贊】宋孝武帝梨花贊曰：沃瘠異壤，舒惨殊時，惟氣在春，具物含滋，嘉树之生，於彼山基，开榮布采，不離尘緇。","sortOrder":136},
  {"id":"s_work_nvlt_86_137","chapterId":"ch_work_nvlt_86","text":"【啟】齊謝朓謝隋王賜紫梨啟曰：味出靈關之陰，旨玠玉津之澨，豈徒真定歸美，大穀慚滋，將恐帝台妙棠，安期靈棗，不得孤擅玉盤，獨甘仙席，雖秦君傳器，漢後推餐，望古可儔，於今何答。","sortOrder":137},
  {"id":"s_work_nvlt_86_138","chapterId":"ch_work_nvlt_86","text":"梁庾肩吾謝赉梨啟曰：睢陽東苑，子围三尺，新丰箭穀，枝懸六斤，未有生因粉水，產自桐丘，影連邓橘，林交苑柿，遠廌中厨，爰頒下室，事同靈棗，有原還年，恐似仙桃，無因留核。","sortOrder":138},
  {"id":"s_work_nvlt_86_140","chapterId":"ch_work_nvlt_86","text":"《神異經》曰：東方裔外有建春山，其上多甘。","sortOrder":140},
  {"id":"s_work_nvlt_86_141","chapterId":"ch_work_nvlt_86","text":"謝承《後漢書》曰：丹陽張盤，字子石，為庐江太守，尋陽令嘗餉一奁甘，其小男年七歲，就取一枚，盤奪不［《太平御覽》九百六十六作取。］付外，卒以兩枚與之，盤奪兒甘，鞭卒曰：何故行賂於吾子。","sortOrder":141},
  {"id":"s_work_nvlt_86_142","chapterId":"ch_work_nvlt_86","text":"崔寔正論曰：橘柚之實，尧舜所不常御，山龍華虫，帝王不以為亵服，今之臣妾，皆餘黃甘而餍文繡，蓋以萬數矣。","sortOrder":142},
  {"id":"s_work_nvlt_86_143","chapterId":"ch_work_nvlt_86","text":"《風土記》曰：甘橘之屬，滋味甜美特異者也，有黃者，有赪者，謂之胡甘。","sortOrder":143},
  {"id":"s_work_nvlt_86_144","chapterId":"ch_work_nvlt_86","text":"《襄陽記》曰：李衡於武陵龍陽洲上，种甘千树，曰千頭木奴。","sortOrder":144},
  {"id":"s_work_nvlt_86_145","chapterId":"ch_work_nvlt_86","text":"【詩】梁徐陵詠甘詩曰：朱實挺荆南，苞品擅珍淑，上林雜嘉树，江浦間脩竹，萬室擬封家，千株挺荆國，绿葉萋以布，素萦芬且鬱。","sortOrder":145},
  {"id":"s_work_nvlt_86_146","chapterId":"ch_work_nvlt_86","text":"【賦】晉胡濟黃甘賦曰：惟江南之奇果，資天地之正陽，生殊方之妙域，植朱鳥之遐乡，處漢之南，背江之陰，左协蘭皋，右接桂林，帶激水之清流，向崇山之高岑，三秋迭運，初寒履霜，照曜原隰，荫映林荒，若菱華之繡綺井，燭龍之衔金璫。","sortOrder":146},
  {"id":"s_work_nvlt_86_147","chapterId":"ch_work_nvlt_86","text":"宋謝惠連甘賦曰：嘉寒園之麗木，美獨有此貞芳，质萎蕤而懷風，性耿介而凌霜，擬夕霞以表色，指朝景以齊圓，悴萍實乎江介，超玉英於崑山。","sortOrder":147},
  {"id":"s_work_nvlt_86_148","chapterId":"ch_work_nvlt_86","text":"【贊】晉王升之甘橘贊曰：節重履险，操貴有恒，二树保榮，四運齊能，在质惟美，於味斯弘，異分南域，北則枳橙。","sortOrder":148},
  {"id":"s_work_nvlt_86_149","chapterId":"ch_work_nvlt_86","text":"【啟】梁劉孝儀謝晉安王賜甘啟曰：便得削彼金衣，咽茲玉液，甘逾萍實，冷亚水圭，立消煩饣肙，頓除酩酊，追嗤齊相，進不剖之實，遠笑魏君，逢裂牙之味。","sortOrder":149},
  {"id":"s_work_nvlt_86_150","chapterId":"ch_work_nvlt_86","text":"梁庾肩吾謝湘東王赉甘啟曰：傳名地理，遠自武陵之洲，族茂神經，遙聞建春之嶺，王逸為賦，取對荔枝，張衡製辭，用連石蜜，足使萍實非甜，蒲萄猶饣肙。","sortOrder":150},
  {"id":"s_work_nvlt_86_151","chapterId":"ch_work_nvlt_86","text":"王羲之諸君子孫遊觀，有一味甘，剖而分之，以娱目前，［按本條脱書名，與下四條，當移前類事中。］","sortOrder":151},
  {"id":"s_work_nvlt_86_152","chapterId":"ch_work_nvlt_86","text":"《古今註》曰：甘實形如石榴者，亦謂之壶甘。","sortOrder":152},
  {"id":"s_work_nvlt_86_153","chapterId":"ch_work_nvlt_86","text":"《廣志》曰：有甘，一核，有成都平蒂甘，大如升，色蒼黃。","sortOrder":153},
  {"id":"s_work_nvlt_86_154","chapterId":"ch_work_nvlt_86","text":"陽由為成都郡文學掾，忽風起，太守問由，由雲，有獻甘橘數苞，［按本條橘部作益部耆舊傳，此脱書名。］","sortOrder":154},
  {"id":"s_work_nvlt_86_155","chapterId":"ch_work_nvlt_86","text":"吳有餘甘，金衣包品之，［按本條脱書名，句亦有訛脱。］","sortOrder":155},
  {"id":"s_work_nvlt_86_156","chapterId":"ch_work_nvlt_86","text":"【贊】厥苞甘［本書八十七柚部作橘。］柚，精者曰甘，［按本條太平御覽九百六十六作郭璞柚贊，此脱題目。］","sortOrder":156},
  {"id":"s_work_nvlt_86_157","chapterId":"ch_work_nvlt_86","text":"削彼金衣，咽茲玉液，甘逾萍實，冷亚冰圭，近嗤齊相，進不剖之實，遠笑魏君，逢裂牙之味，［按削彼以下，系前劉孝儀啟文，重出應删。］頌曰宗炳［按本條《太平御覽》九百六十六作宗炳甘頌，此有訛倒。］煌煌嘉實，磊如景星，南金其形隋珠，［御覽作南金其色，隋珠厥形。］","sortOrder":157},
  {"id":"s_work_nvlt_86_158","chapterId":"ch_work_nvlt_86","text":"《述異記》曰：南陽［《初學記》二十八，《太平御覽》九百六十六作康。］郡東望山，有甘正熟，三人共食致飽訖，懷二枚去，以示人，聞雲中語雲，放双甘，乃聽汝去，［按本條亦當入前類事中。］","sortOrder":158},
  {"id":"s_work_nvlt_86_160","chapterId":"ch_work_nvlt_86","text":"尚書，禹貢曰：淮海惟扬州，厥苞橘柚，錫貢，［小曰橘，大曰柚。］","sortOrder":160},
  {"id":"s_work_nvlt_86_161","chapterId":"ch_work_nvlt_86","text":"周禮曰：橘逾淮而北為枳，此地氣然也。","sortOrder":161},
  {"id":"s_work_nvlt_86_162","chapterId":"ch_work_nvlt_86","text":"晏子使楚，楚王曰：齊人善盜乎，子對曰：婴聞江南之橘，生於淮北則為枳，今民生於齊不盜，入楚則盜，得無楚使民善盜邪。","sortOrder":162},
  {"id":"s_work_nvlt_86_163","chapterId":"ch_work_nvlt_86","text":"《離骚》［按本條見九章橘頌。］曰：後［後土也。］皇［皇也。］嘉树橘采服，［服，習也。］受命不遷生南國，《淮南子》曰：夫橘树之江北，化而為橙。","sortOrder":163},
  {"id":"s_work_nvlt_86_164","chapterId":"ch_work_nvlt_86","text":"魏文帝詔群臣曰：飲食之物，南方有橘，酢正裂人牙，時有甜耳。","sortOrder":164},
  {"id":"s_work_nvlt_86_165","chapterId":"ch_work_nvlt_86","text":"《吳志》曰：陆績年六歲，於九江見袁術，術出橘，績懷三枚去，拜辭墮地，術謂曰：陆郎作賓客而懷橘乎，績跪答曰：欲歸遺母，術大奇之。","sortOrder":165},
  {"id":"s_work_nvlt_86_166","chapterId":"ch_work_nvlt_86","text":"《益部耆舊傳》曰：楊由為成都文學掾，少治易，晓占候，忽有風起，太守問由，由曰：南方有荐木實者，色黃赤，頃之，五官掾獻橘數苞。","sortOrder":166},
  {"id":"s_work_nvlt_86_167","chapterId":"ch_work_nvlt_86","text":"璇枢星散為橘，［運斗枢。］","sortOrder":167},
  {"id":"s_work_nvlt_86_168","chapterId":"ch_work_nvlt_86","text":"蜀漢江陵千树橘，此人與千戶侯等，［本條明本作史記。］","sortOrder":168},
  {"id":"s_work_nvlt_86_169","chapterId":"ch_work_nvlt_86","text":"《吳錄》：朱光［《太平御覽》九百六十六光下有祿字。］為建安太守，有橘，冬月树上覆裹之，至明年春夏，色变青黑，味尤酸，正裂人牙，絕美，盧橘夏熟，蓋近是乎。","sortOrder":169},
  {"id":"s_work_nvlt_86_170","chapterId":"ch_work_nvlt_86","text":"搜神記［本條《太平御覽》九百六十六作續搜神記。］曰：秦精入武昌山采茗，見一人，長丈餘，授懷中橘二十枚精，［御覽精上有與字。］","sortOrder":170},
  {"id":"s_work_nvlt_86_171","chapterId":"ch_work_nvlt_86","text":"進橘併食，王曰：當剖之，曰：賜人主前，瓜桃不削，橘柚不剖，［本條《太平御覽》九百六十六作晏子，此有脱文。］","sortOrder":171},
  {"id":"s_work_nvlt_86_172","chapterId":"ch_work_nvlt_86","text":"武帝平百越，以為園圃，民獻橘柚，［本條明本作西京雜記。］","sortOrder":172},
  {"id":"s_work_nvlt_86_173","chapterId":"ch_work_nvlt_86","text":"《異物志》曰：橘白華赤實，皮馨香有味，交趾有橘官長一人，秩二百石，主貢御橘。","sortOrder":173},
  {"id":"s_work_nvlt_86_174","chapterId":"ch_work_nvlt_86","text":"韓子，夫树柤梨橘，食之美，嗅之則香。","sortOrder":174},
  {"id":"s_work_nvlt_86_175","chapterId":"ch_work_nvlt_86","text":"梁太清［原訛實，據冯校本改。］元年，將軍王僧辯家，有橘三十子一蒂，以獻。","sortOrder":175},
  {"id":"s_work_nvlt_86_176","chapterId":"ch_work_nvlt_86","text":"建武故事曰：平西將軍庾亮，送橘，十二實共同一蒂，為瑞異，群臣畢贺。","sortOrder":176},
  {"id":"s_work_nvlt_86_177","chapterId":"ch_work_nvlt_86","text":"宋躬《孝子傳》曰：王虛［《太平御覽》九百六十六作靈。］之，十三丧母，三十三丧父，二十年鹽醋不入口，病著床，忽有一人來問疾，謂之曰：君尋差，俄而不見，庭中橘树，隆冬而實，病果尋愈，鹹以至孝所感。","sortOrder":177},
  {"id":"s_work_nvlt_86_178","chapterId":"ch_work_nvlt_86","text":"【詩】古詩曰：橘柚垂嘉實，乃在深山侧，聞君好我甘，竊獨自雕飾。","sortOrder":178},
  {"id":"s_work_nvlt_86_179","chapterId":"ch_work_nvlt_86","text":"張華詩曰：橘生湘水侧，菲陋人莫傳，逢君金華宴，得在玉機前。","sortOrder":179},
  {"id":"s_work_nvlt_86_180","chapterId":"ch_work_nvlt_86","text":"齊虞義［按當作羲。］橘詩曰：冲飆發隴首，朔雪度炎洲，摧折江南桂，離披漢北楸，獨有凌霜橘，榮麗在中州，從來自有節，歲暮將何忧。","sortOrder":180},
  {"id":"s_work_nvlt_86_181","chapterId":"ch_work_nvlt_86","text":"梁簡文帝詠橘詩曰：萎蕤暎庭树，枝葉凌秋芳，故條雜新實，金翠共含霜，攀枝折縹幹，甘旨若琼漿，無假存雕飾，玉盤餘自嘗。","sortOrder":181},
  {"id":"s_work_nvlt_86_182","chapterId":"ch_work_nvlt_86","text":"梁徐摛詠橘詩曰：麗树摽江浦，結翠似芳蘭，焜煌玉衡散，照曜金衣丹，愧以無雕飾，徒然登玉盤。","sortOrder":182},
  {"id":"s_work_nvlt_86_183","chapterId":"ch_work_nvlt_86","text":"【賦】魏陳王曹植橘賦曰：有朱橘之珍树，於鶉火之遐乡，禀太陽之烈氣，嘉杲日之休光，體天然之素分，不遷徙於殊方，播萬里而遙植，列銅爵之園庭，背江川之暖氣，處玄朔之肅清，邦換壤殊，爰用丧生，處彼不雕，在此先零，仰凯風以傾葉，冀炎氣之可懷，颺鳴條以流响，晞越鳥之來栖。","sortOrder":183},
  {"id":"s_work_nvlt_86_184","chapterId":"ch_work_nvlt_86","text":"晉潘嶽橘賦曰：餘斋前橘树，冬夏再熟，聊為賦雲爾，嗟嘉卉之芳華，信氛氲而芬馥，既蓊茸而萎蕤，且參差而橚矗，已鬱鬱而冬茂，亦離離而夏熟，至如廣命賓客，歷覽遊觀，三清既設，百味星烂，炫熀乎玉案，照曜於金盤，故成都美其家園，江陵重其千树，既見稱於陆言，亦摽名乎馬賦。","sortOrder":184},
  {"id":"s_work_nvlt_86_185","chapterId":"ch_work_nvlt_86","text":"宋謝惠連橘賦曰：園有嘉树，橘柚煌煌，圓丹可玩，□氣芬芳，受以玉盤，升君子堂，味既滋而事美，實厥苞之最良。","sortOrder":185},
  {"id":"s_work_nvlt_86_186","chapterId":"ch_work_nvlt_86","text":"梁吳筠橘賦曰：增枝之木，既稱英於绿地，金衣之果，亦委體於玉盤，見雲夢之千树，笑江陵之十蘭，葉葉之雲，共琉璃而併碧，枝枝之日，與金輪而共丹，若乃秋夜初露，長郊欲素，風赍寒而北來，雁衔霜而南渡，方散藻於年深，遂凝貞於冬暮。","sortOrder":186},
  {"id":"s_work_nvlt_86_187","chapterId":"ch_work_nvlt_86","text":"【頌】宋孝武芳春琴堂橘連理頌曰：列訪神秘，詳觀瑞策，通柯竦秀，寔靈所錫，離條別幹，奄一榮戚，道被遐夷，承我正歷。","sortOrder":187},
  {"id":"s_work_nvlt_86_188","chapterId":"ch_work_nvlt_86","text":"【啟】梁皇太子謝敕赉城邊橘啟曰：結根龍首，垂陰陽巉，甘逾石蜜，味重金衣，暉章縹李，豈止稱於晉世，上林美棗，非獨高於漢日。","sortOrder":188},
  {"id":"s_work_nvlt_86_189","chapterId":"ch_work_nvlt_86","text":"梁劉孝儀謝宮賜城傍橘啟曰：多置守民，晉為厚秩，坐入缣素，漢譬封君，固以俯疋穰橙，俯聯楚柚，寧似魏瓜，借清泉而得冷，豈如蜀食，待飴蜜而成甜，重似倒影陽池，垂華金堞，信可珍若榴於式乾，貴蒲萄於別馆。","sortOrder":189},
  {"id":"s_work_nvlt_86_190","chapterId":"ch_work_nvlt_86","text":"梁庾肩吾謝赉橘啟曰：光分璇宿，影接銅峰，去青馬之迢遞，服朱闉之爽垲，楚原洪筆，頌記不遷，陳王麗藻，賦稱遙植，昔朝歌季重，才賜海魚，大理元常，止蒙秋菊。","sortOrder":190},
  {"id":"s_work_nvlt_86_191","chapterId":"ch_work_nvlt_86","text":"◇櫻桃","sortOrder":191},
  {"id":"s_work_nvlt_86_192","chapterId":"ch_work_nvlt_86","text":"《禮記月令》曰：仲夏之月，天子羞以含桃，先荐寢廟。","sortOrder":192},
  {"id":"s_work_nvlt_86_193","chapterId":"ch_work_nvlt_86","text":"《漢書》曰：惠帝出離宮，叔孫通曰：古者春嘗果，方今櫻桃熟可獻，原陛下出，因取櫻桃獻宗廟，上許之。","sortOrder":193},
  {"id":"s_work_nvlt_86_194","chapterId":"ch_work_nvlt_86","text":"《博物志》：櫻桃者或如彈丸。","sortOrder":194},
  {"id":"s_work_nvlt_86_195","chapterId":"ch_work_nvlt_86","text":"《晉宮閣名》曰：式乾殿前，櫻桃二株，含章殿前，櫻桃一株，華林園櫻桃二百七十株。","sortOrder":195},
  {"id":"s_work_nvlt_86_196","chapterId":"ch_work_nvlt_86","text":"宋江夏王劉義恭啟曰：手敕猥賜華林櫻桃，為树則多陰，百果則先熟，故种之於廳事之前，有蝉鳴焉，顧命黏取以弄，［本條櫻桃以下，本書九十七蝉篇，太平御覽九百六十九作傅鹹粘蝉賦，嚴可均校本，《初學記》二十八，與此同，當從本書九十七及御覽。］","sortOrder":196},
  {"id":"s_work_nvlt_86_197","chapterId":"ch_work_nvlt_86","text":"王僧達詩：初櫻動時艳，蝉噪灼辉芳，緗葉未开蕊，紅葩已發光。","sortOrder":197},
  {"id":"s_work_nvlt_86_198","chapterId":"ch_work_nvlt_86","text":"《爾雅》楔，荆桃，今之櫻桃。","sortOrder":198},
  {"id":"s_work_nvlt_86_199","chapterId":"ch_work_nvlt_86","text":"《廣志》曰：櫻桃有大八分者，白色多肥者，凡三［嚴校本，《初學記》二十八，《太平御覽》九百六十九作二。］种，有白色者，［四字《初學記》，御覽無。］","sortOrder":199},
  {"id":"s_work_nvlt_86_200","chapterId":"ch_work_nvlt_86","text":"《吳氏本草》：櫻桃一名朱茱，［《太平御覽》九百六十九作桃。］一名麥英，甘酣，主調中，益脾氣，令人好顏色，美志氣。","sortOrder":200},
  {"id":"s_work_nvlt_86_201","chapterId":"ch_work_nvlt_86","text":"後漢明帝於月夜宴群臣於照園，太官進櫻桃，以赤瑛為盤，賜群臣，月下视之，盤與桃同色，群臣皆笑，雲是空盤，［本條《太平御覽》九百六十九作拾遺錄。］","sortOrder":201},
  {"id":"s_work_nvlt_86_202","chapterId":"ch_work_nvlt_86","text":"【詩】梁簡文帝皇太子奉答南平王赉朱櫻詩曰：倒流暎碧丛，點露擎朱實，花茂蝶爭來，枝浓鳥相失，已麗金釵瓜，兼美玉盤橘，寧以梅似丸，不羨萍如日。","sortOrder":202},
  {"id":"s_work_nvlt_86_203","chapterId":"ch_work_nvlt_86","text":"【啟】梁庾肩吾謝蒙赉朱櫻啟曰：成丛殿侧，猶連製賦之條，結實西園，非复黏蝉之树，異合浦之歸來，疑藏朱實，同秦人之逐彈，似得金丸。","sortOrder":203},
  {"id":"s_work_nvlt_86_204","chapterId":"ch_work_nvlt_86","text":"◇石榴","sortOrder":204},
  {"id":"s_work_nvlt_86_205","chapterId":"ch_work_nvlt_86","text":"《廣雅》曰：若榴，石榴也。","sortOrder":205},
  {"id":"s_work_nvlt_86_206","chapterId":"ch_work_nvlt_86","text":"陆機與弟雲書曰：張騫為漢使外國十八年，得涂林安熟［《太平御覽》九百七十作石。］榴也。","sortOrder":206},
  {"id":"s_work_nvlt_86_207","chapterId":"ch_work_nvlt_86","text":"【詩】梁元帝賦得詠石榴詩曰：涂林未應發，春暮轉相催，然燈疑夜火，連珠勝早梅，西域移根至，南方酿酒來，葉翠如新翦，花紅似故栽，還憶河陽縣，暎水珊瑚开。","sortOrder":207},
  {"id":"s_work_nvlt_86_208","chapterId":"ch_work_nvlt_86","text":"梁沈約詠山榴詩曰：靈圓同佳稱，幽山有奇质，停采久弥鮮，含華豈期實，長原微名隱，無使孤株出。","sortOrder":208},
  {"id":"s_work_nvlt_86_209","chapterId":"ch_work_nvlt_86","text":"【賦】晉潘尼安石榴賦曰：安石榴者，天下之奇树，九州之名果，是以屬文之士，或叙而賦之，蓋感時而騁思，睹物而興辭，餘遷舊宇，爰造新居，前臨曠泽，却背清渠，實有斯树，植於堂隅，華實併麗，滋味亦殊，可以樂志，可以充虛，朱芳赫弈，紅萼參差，含英吐秀，乍合乍披，遙而望之，煥若隋珠燿重川，詳而察之，灼若列宿出雲間，湘涯二後，漢川遊女，携類命畴，逍遙避暑，讬斯树以栖遲，溯祥風而容與，爾乃擢纖手兮舒皓腕，羅袖靡兮流芳散，披绿葉於脩條，輟朱華乎弱幹，豈金翠之足珍，寔茲葩之可玩，商秋授氣，收華斂實，滋味浸液，馨香流溢。","sortOrder":209},
  {"id":"s_work_nvlt_86_210","chapterId":"ch_work_nvlt_86","text":"晉張載安石榴賦曰：有若榴之奇树，肇結根於西海，仰青春以啟萌，晞朱夏以發采，揮光垂绿，擢幹曜鮮，熻若群翡俱栖，烂若百枝併然，煥乎鬱鬱，焜乎煌煌，仰暎清霄，俯燭蘭堂，似西極之若木，譬東穀之扶桑，於是天回節移，龍火西夕，流風晨激，行露朝白，紫房既熟，赪膚自拆，部之則珠散，含之則冰釋。","sortOrder":210},
  {"id":"s_work_nvlt_86_211","chapterId":"ch_work_nvlt_86","text":"晉張协安石榴賦曰：考草木於方志，覽華實於園畴，窮陆產於苞貢，差莫奇於若榴，耀靈葩於三春，缀霜滋於九秋，爾乃飛龍啟節，扬飆扇埃，含和泽以滋生，鬱敷萌以挺栽，傾柯遠擢，沉根下盤，繁茎筱密，丰幹林攒，揮長枝以扬绿，披翠葉以吐丹，流暉俯散，回葩仰照，烂若柏枝併燃，殢如烽燧俱燎，曒如朝日，晃若龍燭，晞絳采於扶桑，接朱光於若木，爾乃赪萼挺蒂，金牙承蕤，荫佳人之玄髻，發窈窕之素姿，遊女一顧傾城，無鹽化為南威，於是天漢西流，辰角南傾，芳實壘落，月滿虧盈，爰采爰收，乃剖乃折，內怜幽以含紫，外滴瀝以霞赤，柔膚冰絜，凝光玉瑩，漼如冰碎，泫若珠迸，含清冷之溫润，信和神以理性。","sortOrder":211},
  {"id":"s_work_nvlt_86_212","chapterId":"ch_work_nvlt_86","text":"晉應貞安石榴賦曰：餘往日職在中書時，直庐前有安石榴树，枝葉既盛，華實甚茂，為之作賦，挹微露以鮮采，承輕風而動葩，南拂陰簷，北扇陽阿，其傍則有大厦崇房，重廊高庑，皇籍帝典，圖書之府，時移節变，大火西旋，丹葩結秀，朱實星懸，膚拆理阻，烂若珠骈。","sortOrder":212},
  {"id":"s_work_nvlt_86_213","chapterId":"ch_work_nvlt_86","text":"晉潘嶽河陽庭前安石榴賦曰：雖小縣陋馆，聊可以遊賞，有嘉木曰安石榴，脩條外畅，榮幹內樛，扶疏偃蹇，冉弱紛柔，於是暮春告謝，孟夏戒初，新茎擢润，膏葉垂腴，丹暉缀於朱房，緗的點乎紅須，煌煌煒煒，熠烁入蕊，似長離之栖邓林，若珊瑚之暎绿水，既乃攒乎狹庭，載阨載褊，土階無等，肩牆惟淺，壁衣蒼苔，瓦被駮藓，處悴而榮，在幽弥顯，其華可玩，其實可珍，羞於王公，荐於鬼神，豈伊仄陋，用渝厥真，果猶如之，而况於人。","sortOrder":213},
  {"id":"s_work_nvlt_86_214","chapterId":"ch_work_nvlt_86","text":"晉夏侯湛若石榴賦曰：接翠萼於绿葉，冒紅芽於丹須，赩然含蕤，漼爾散珠，雪酲解饣肙，怡神實氣，冠百品以奇仰，邁眾果而特貴。","sortOrder":214},
  {"id":"s_work_nvlt_86_215","chapterId":"ch_work_nvlt_86","text":"晉傅玄安石榴賦曰：鳥宿中而纖條結，龍辰升而丹華繁，其在晨也，灼若旭日遷扶桑，其在昏也，奭若燭龍吐潛光，苞玄黃之烈辉，紛煒晔而焜煌，發朱榮於绿葉，時從風而飄扬。","sortOrder":215},
  {"id":"s_work_nvlt_86_216","chapterId":"ch_work_nvlt_86","text":"晉庾儵石榴賦曰：於時仲春垂泽，華葉甚茂，炎夏既戒，忽乎零落，是以君子居安思危，在盛慮衰，可無慎哉，乃作斯賦，绿葉翠條，紛乎葱青，丹華照烂，晔晔熒熒，遠而望之，粲若摛缋被山阿，迫而察之，赫若龍燭，辉耀绿波。","sortOrder":216},
  {"id":"s_work_nvlt_86_217","chapterId":"ch_work_nvlt_86","text":"晉范堅安石榴賦曰：萦紅根以磐峙，擢脩幹而扶疏，荑應春以吐绿，葩涉夏而扬朱。","sortOrder":217},
  {"id":"s_work_nvlt_86_218","chapterId":"ch_work_nvlt_86","text":"宋顏测山石榴賦曰：風觸枝而翻蒍，雨淋條而殒芬，環青軒而燧列，繞翠波而星分，视栖翡之失榮，顧彫霞之無文。","sortOrder":218},
  {"id":"s_work_nvlt_86_219","chapterId":"ch_work_nvlt_86","text":"【頌】梁江淹山石榴頌曰：縹葉翠萼，紅華絳采，炤烈泉石，芬披山海，奇麗不移，霜雪空改。","sortOrder":219},
  {"id":"s_work_nvlt_86_221","chapterId":"ch_work_nvlt_86","text":"《說文》曰：柿，赤實果也。","sortOrder":221},
  {"id":"s_work_nvlt_86_222","chapterId":"ch_work_nvlt_86","text":"《晉宮閣名》曰：華林園柿六十七株，暉章殿前，柿一株。","sortOrder":222},
  {"id":"s_work_nvlt_86_223","chapterId":"ch_work_nvlt_86","text":"義熙起居註曰：吳令顧脩期言，縣西乡有柿树，殊本合條，依舊集駕，［《太平御覽》九百七十一作贺。］詔停。","sortOrder":223},
  {"id":"s_work_nvlt_86_224","chapterId":"ch_work_nvlt_86","text":"【詩】梁庾仲容詠柿詩曰：發葉臨層槛，翻英糅花藥，風生树影移，露重新枝弱，苑朱正葱翠，梁乌未銷鑠。","sortOrder":224},
  {"id":"s_work_nvlt_86_225","chapterId":"ch_work_nvlt_86","text":"【啟】宋江夏王劉義恭謝柿啟曰：垂赉華林糒柿，味滋殊絕。","sortOrder":225},
  {"id":"s_work_nvlt_86_226","chapterId":"ch_work_nvlt_86","text":"梁簡文帝謝東宮賜柿啟曰：懸霜照采，凌冬挺润，甘清玉露，味重金液，雖复安邑秋獻，靈關晚實，無以疋此嘉名，方茲擅美。","sortOrder":226},
  {"id":"s_work_nvlt_86_228","chapterId":"ch_work_nvlt_86","text":"《禮》：［本條《太平御覽》九百六十九作爾雅。］楂梨曰鑽之。","sortOrder":228},
  {"id":"s_work_nvlt_86_229","chapterId":"ch_work_nvlt_86","text":"楂梨薑桂，梨之鹹者，皆人君羞，以梨也，［本條御覽九百六十九作禮記。又梨之上有楂字，鹹作不藏，以爾雅郭註作似。］","sortOrder":229},
  {"id":"s_work_nvlt_86_230","chapterId":"ch_work_nvlt_86","text":"張敷［本條當是引用俗說，見本書二十九別部及《太平御覽》六百三十四，此有脱文。］","sortOrder":230},
  {"id":"s_work_nvlt_86_231","chapterId":"ch_work_nvlt_86","text":"平丘有甘楂，［本條御覽作山海經。］","sortOrder":231},
  {"id":"s_work_nvlt_86_232","chapterId":"ch_work_nvlt_86","text":"呂箕山之東有甘楂，［本條御覽作呂氏春秋。］","sortOrder":232},
  {"id":"s_work_nvlt_86_233","chapterId":"ch_work_nvlt_86","text":"洞庭之上，其木多楂，［本條御覽作山海經。］","sortOrder":233},
  {"id":"s_work_nvlt_86_234","chapterId":"ch_work_nvlt_86","text":"甘楂列於崑崙，［本條御覽作傅玄瓜賦。］","sortOrder":234},
  {"id":"s_work_nvlt_86_236","chapterId":"ch_work_nvlt_86","text":"《廣志》曰：〈木柰〉有白青赤三种，張掖有白柰，酒泉有赤柰。","sortOrder":236},
  {"id":"s_work_nvlt_86_237","chapterId":"ch_work_nvlt_86","text":"《漢武內傳》：仙藥之次者，有圓丘紫柰。","sortOrder":237},
  {"id":"s_work_nvlt_86_238","chapterId":"ch_work_nvlt_86","text":"《晉鹹和起居註》曰：六年，寧州上言，甘露降城北園柰桃树等。","sortOrder":238},
  {"id":"s_work_nvlt_86_239","chapterId":"ch_work_nvlt_86","text":"《晉太始起居註》曰：二年六月，嘉柰一蒂十五實，生於酒泉。","sortOrder":239},
  {"id":"s_work_nvlt_86_240","chapterId":"ch_work_nvlt_86","text":"萧廣濟《孝子傳》：王祥後母庭中有柰树，始著子，使祥守视，晝驅鳥雀，夜驚虫鼠，時雨總至，祥抱树至曙，母見之惻然。","sortOrder":240},
  {"id":"s_work_nvlt_86_241","chapterId":"ch_work_nvlt_86","text":"【詩】梁楮湮［《初學記》二十八作褚澐。］柰詩曰：成都貴素质，酒泉稱白麗，紅紫奪夏藻，芬芳掩春蕙，誰謂重三珠，終焉競八桂。","sortOrder":241},
  {"id":"s_work_nvlt_86_242","chapterId":"ch_work_nvlt_86","text":"【表】魏曹植謝柰表曰：即夕，殿中宣詔，賜臣冬柰，詔使溫啖，夜非食時，而賜見及，奈以夏熟，今則冬至，物以非時為珍，恩以絕口為厚。","sortOrder":242},
  {"id":"s_work_nvlt_86_243","chapterId":"ch_work_nvlt_86","text":"《論》［《太平御覽》九百七十作杜恕篤論。］曰：□［御覽作日給。］之華與柰之華相次，［御覽作似。］柰結實而日洽［御覽作給。］零落，虛伪之與真實相似，虛伪败而真實成。","sortOrder":243},
  {"id":"s_work_nvlt_86_244","chapterId":"ch_work_nvlt_86","text":"太冲嗟其夏成，子建畅其寒熟。［按太冲以下見後劉孝儀啟，重出應删。］","sortOrder":244},
  {"id":"s_work_nvlt_86_245","chapterId":"ch_work_nvlt_86","text":"《洞冥記》：有紫柰大如斗，甘如蜜，核紫花青。","sortOrder":245},
  {"id":"s_work_nvlt_86_246","chapterId":"ch_work_nvlt_86","text":"《蜀都賦》：素柰夏成。","sortOrder":246},
  {"id":"s_work_nvlt_86_247","chapterId":"ch_work_nvlt_86","text":"潘尼《武馆賦》：投素柰於青渠。","sortOrder":247},
  {"id":"s_work_nvlt_86_248","chapterId":"ch_work_nvlt_86","text":"閒居賦，二柰曜丹白之色。","sortOrder":248},
  {"id":"s_work_nvlt_86_249","chapterId":"ch_work_nvlt_86","text":"濟北楊愔，字遵彦，四代同居，崑季就學者三十餘人，學庭前有柰树，實落於地，群就爭之，愔頹然而坐，季父睇，大嗟異之，［本條明本作北齊書。又按自杜篤正論條至此，當移前類事中。］","sortOrder":249},
  {"id":"s_work_nvlt_86_250","chapterId":"ch_work_nvlt_86","text":"【啟】梁劉孝儀謝始興王賜柰啟曰：酒泉之實，稱於王賦，瓜州之味，記自張文，亦有太冲嗟其夏成，子建畅其寒熟，潘園曜白，孫井浮朱，併見重於昔時，而霑恩於茲日。","sortOrder":250},
  {"id":"s_work_nvlt_86_251","chapterId":"ch_work_nvlt_86","text":"《藝文類聚》　唐·欧陽詢","sortOrder":251},
  {"id":"s_work_nvlt_87_1","chapterId":"ch_work_nvlt_87","text":"卷八十七果部下","sortOrder":1},
  {"id":"s_work_nvlt_87_2","chapterId":"ch_work_nvlt_87","text":"○棗杏栗胡桃林檎甘藷沙棠椰枇杷燕薁檖蒟子枳椇柚木瓜杜梨芋楊梅蒲萄槟榔荔支益智椹芭蕉甘蔗瓜","sortOrder":2},
  {"id":"s_work_nvlt_87_4","chapterId":"ch_work_nvlt_87","text":"《爾雅》曰：棗，壶棗，［今江東呼棗大而銳上者為壶棗，猶瓠也。］邊要棗，［子細要者。］","sortOrder":4},
  {"id":"s_work_nvlt_87_5","chapterId":"ch_work_nvlt_87","text":"《禮記》曰：婦人之贽，椇榛脯脩棗栗，《毛詩》曰：八月剝棗，十月獲稻。","sortOrder":5},
  {"id":"s_work_nvlt_87_6","chapterId":"ch_work_nvlt_87","text":"《晏子》曰：景公謂《晏子》曰：東海之中，有水而赤，其中有棗，華而不實，何也，《晏子》曰：昔者秦缪公乘龍理天下，以黃布裹蒸棗，至海而投其布，故水赤，蒸棗，故華而不實，公曰：吾徉問子耳，對曰：婴聞之，徉問者，亦徉對。","sortOrder":6},
  {"id":"s_work_nvlt_87_7","chapterId":"ch_work_nvlt_87","text":"《孟子》曰：曾晳嗜羊棗，而曾子不忍食之。","sortOrder":7},
  {"id":"s_work_nvlt_87_8","chapterId":"ch_work_nvlt_87","text":"《韓子》曰：秦饿，應侯謂王曰：五苑之棗栗，請發與之。","sortOrder":8},
  {"id":"s_work_nvlt_87_9","chapterId":"ch_work_nvlt_87","text":"《史記》曰：李少君以却老方見上，少君曰：臣嘗遊海上，見安期生，食巨棗，大如瓠。","sortOrder":9},
  {"id":"s_work_nvlt_87_10","chapterId":"ch_work_nvlt_87","text":"真人關令尹喜內傳曰：尹喜共老子西遊，省太真王母，共食玉門之棗，其實如瓶。","sortOrder":10},
  {"id":"s_work_nvlt_87_11","chapterId":"ch_work_nvlt_87","text":"《神異經》曰：北方荒中，有棗林焉，其高五丈，敷張枝條一里餘，子長六七寸，围過其長，熟赤如朱，乾之不縮，氣味甘润，殊於常棗，食之可以安軀，益氣力。","sortOrder":11},
  {"id":"s_work_nvlt_87_12","chapterId":"ch_work_nvlt_87","text":"《東方朔傳》曰：武帝時，上林獻棗，上以枝击未央前殿槛，呼朔曰：叱來叱來，先生知此箧中何物，朔曰：上林獻棗四十九枚，上曰：何以知之，朔曰：呼朔者，上也，以枝击槛，兩木林也，曰朔來朔來者，棗也，叱叱者四十九，上大笑，賜帛十疋。","sortOrder":12},
  {"id":"s_work_nvlt_87_13","chapterId":"ch_work_nvlt_87","text":"《漢書》曰：王吉少時學問，居長安，其東家有棗树，垂吉庭中，吉婦取棗以啖吉，吉後知之，乃去婦，東家聞而欲伐其树，鄰里共止之，因固請吉，令還婦，里中為之語曰：東家棗树，王陽婦去，東家棗完，去婦复還。","sortOrder":13},
  {"id":"s_work_nvlt_87_14","chapterId":"ch_work_nvlt_87","text":"《漢武內傳》曰：七月七日，西王母當下，帝設玉門之棗。","sortOrder":14},
  {"id":"s_work_nvlt_87_15","chapterId":"ch_work_nvlt_87","text":"劉根別傳曰：今年春，當有病，可服棗核中仁二七枚，能常服之，百邪不复幹也。","sortOrder":15},
  {"id":"s_work_nvlt_87_16","chapterId":"ch_work_nvlt_87","text":"《風俗通》曰：鮑焦耕田而食，穿井而飲，於山中食棗，或曰：此棗子所殖耶，遂強欧吐而死也。","sortOrder":16},
  {"id":"s_work_nvlt_87_17","chapterId":"ch_work_nvlt_87","text":"魏文帝詔群臣曰：南方有龍眼荔枝，寧比西國蒲萄石蜜乎，酢且不如中國凡棗味，莫言安邑御棗也。","sortOrder":17},
  {"id":"s_work_nvlt_87_18","chapterId":"ch_work_nvlt_87","text":"馬明生別傳曰：安期生仙人見神女，設厨膳，安期曰：昔與女郎遊息於西海之际，食棗異美，此間棗小，不及之，憶此棗味久，已二千年矣，神女雲，吾昔與君共食一枚，乃不盡，此間小棗，那可相比耶。","sortOrder":18},
  {"id":"s_work_nvlt_87_19","chapterId":"ch_work_nvlt_87","text":"王隱《晉書》：傅虞為鄱陽內史，勸厲學業，宽裕簡素，風化大行，白乌集郡庭棗树上。","sortOrder":19},
  {"id":"s_work_nvlt_87_20","chapterId":"ch_work_nvlt_87","text":"《晉宮閣名》曰：華林園棗六十二株，王母棗十四株。","sortOrder":20},
  {"id":"s_work_nvlt_87_21","chapterId":"ch_work_nvlt_87","text":"《異苑》曰：太元中，南郡州陵縣有棗树，一年忽生桃李棗三种花子。","sortOrder":21},
  {"id":"s_work_nvlt_87_22","chapterId":"ch_work_nvlt_87","text":"《世說》曰：魏文帝忌弟任城［原訛成，據冯校本改。］王驍壮，因在卞太後所，共围棋，併啖棗，文帝以毒著諸棗蒂中，自選可食者，而王不悟，遂雜進之，既中毒，太後索水救之，帝豫敕毀器，太後徒跣趨井，無以汲之，須臾遂卒。","sortOrder":22},
  {"id":"s_work_nvlt_87_23","chapterId":"ch_work_nvlt_87","text":"又曰：大將軍王敦，初尚武帝舞陽公主，如廁，見漆箱中盛棗，本以塞鼻，王謂廁上下果，遂食之，群婢莫不笑之。","sortOrder":23},
  {"id":"s_work_nvlt_87_24","chapterId":"ch_work_nvlt_87","text":"《左傳》：御孫曰：女贽不過榛栗棗脩以告虔。","sortOrder":24},
  {"id":"s_work_nvlt_87_25","chapterId":"ch_work_nvlt_87","text":"鄴中記，石季龍園中有羊角棗，三子一尺。","sortOrder":25},
  {"id":"s_work_nvlt_87_26","chapterId":"ch_work_nvlt_87","text":"《史》，楚莊王愛一馬，啖棗脯。","sortOrder":26},
  {"id":"s_work_nvlt_87_27","chapterId":"ch_work_nvlt_87","text":"夏取棗杏之火，［本條《太平御覽》九百六十五作邹子，後同。］","sortOrder":27},
  {"id":"s_work_nvlt_87_28","chapterId":"ch_work_nvlt_87","text":"【詩】晉傅玄詩曰：飢食野棗實。","sortOrder":28},
  {"id":"s_work_nvlt_87_29","chapterId":"ch_work_nvlt_87","text":"後秦趙整詩曰：北園有一树，布葉垂重陰，外雖多棘刺，內實有赤心。","sortOrder":29},
  {"id":"s_work_nvlt_87_30","chapterId":"ch_work_nvlt_87","text":"梁簡文帝賦詠棗曰：風搖羊角树，日映雞心枝，已聞安邑美，永茂玉門垂。","sortOrder":30},
  {"id":"s_work_nvlt_87_31","chapterId":"ch_work_nvlt_87","text":"【啟】陳周弘正謝梁元帝赉玉門棗啟曰：安期舊美，安息高名，臣金馬之榮，未獲趨奉，方朔之賜，遽降洪恩。","sortOrder":31},
  {"id":"s_work_nvlt_87_33","chapterId":"ch_work_nvlt_87","text":"《神仙傳》曰：董奉居庐山，為治病，重者种杏五株，輕者一株，於林中所在，箪食一器，是換一穀，少者虎逐之，乃以穀赈貧窮，號董仙杏林。","sortOrder":33},
  {"id":"s_work_nvlt_87_34","chapterId":"ch_work_nvlt_87","text":"《師曠占》曰：梅桃杏實多者，來年謂之穰。","sortOrder":34},
  {"id":"s_work_nvlt_87_35","chapterId":"ch_work_nvlt_87","text":"晉宮關［《太平御覽》九百六十八作閣。］記曰：明光殿，杏八株。","sortOrder":35},
  {"id":"s_work_nvlt_87_36","chapterId":"ch_work_nvlt_87","text":"九州論，魏郡好杏。","sortOrder":36},
  {"id":"s_work_nvlt_87_37","chapterId":"ch_work_nvlt_87","text":"燧人夏取棗杏之火。","sortOrder":37},
  {"id":"s_work_nvlt_87_38","chapterId":"ch_work_nvlt_87","text":"《西京雜記》曰：上林苑有文杏，謂有文彩也。","sortOrder":38},
  {"id":"s_work_nvlt_87_39","chapterId":"ch_work_nvlt_87","text":"典術曰：杏者東方歲星之精也。","sortOrder":39},
  {"id":"s_work_nvlt_87_40","chapterId":"ch_work_nvlt_87","text":"《山海經》曰：靈山之下，其木多杏。","sortOrder":40},
  {"id":"s_work_nvlt_87_41","chapterId":"ch_work_nvlt_87","text":"盧毓冀州論曰：魏郡好杏，地產不為珍。","sortOrder":41},
  {"id":"s_work_nvlt_87_42","chapterId":"ch_work_nvlt_87","text":"《師曠占》曰：杏多實不虫者，來年秋善。","sortOrder":42},
  {"id":"s_work_nvlt_87_43","chapterId":"ch_work_nvlt_87","text":"南嶽夫人傳曰：仙人有三玄紫杏，《西京雜記》曰：上林苑有蓬萊杏，東海都尉於台，獻杏一株，花雜五色，六出，雲是仙人所食者。","sortOrder":43},
  {"id":"s_work_nvlt_87_44","chapterId":"ch_work_nvlt_87","text":"《氾勝之書》曰：杏花如何，可耕白沙。","sortOrder":44},
  {"id":"s_work_nvlt_87_45","chapterId":"ch_work_nvlt_87","text":"玄晏春秋曰：衛倫過予，言及於味，稱魏故侍中劉子陽，食餅知鹽生，精味之至也，予曰：師曠識勞薪，易牙別淄渑，子陽今之妙也，定之何難，倫因命仆取糧糗以進，予嘗之曰：麥也，有杏李柰味，三果之熟也不同，子焉得兼之，倫笑而不言，退告人曰：士安之識過劉氏，吾將來家實多，故杏時將發，糅以杏汁，李柰將發。又糅以李柰汁，故兼三味。","sortOrder":45},
  {"id":"s_work_nvlt_87_46","chapterId":"ch_work_nvlt_87","text":"《述異記》曰：杏園洲在南海中，多杏，雲仙人种杏處，漢時嘗有人舟行遇風，泊此洲五六月，日食杏，故免死。又雲洲中有冬杏。","sortOrder":46},
  {"id":"s_work_nvlt_87_47","chapterId":"ch_work_nvlt_87","text":"嵩高山記曰：嵩山東北有牛山，其山多杏，至五月，烂然黃茂，自中國丧亂，百姓飢饉，皆資此為命，人人充飽，而杏不盡。","sortOrder":47},
  {"id":"s_work_nvlt_87_48","chapterId":"ch_work_nvlt_87","text":"《洛陽宮殿簿》曰：含章殿前，杏四株，顯陽殿前，杏六株。","sortOrder":48},
  {"id":"s_work_nvlt_87_49","chapterId":"ch_work_nvlt_87","text":"《地理志》曰：范蠡宅在湖中，有海杏，大如拳也。","sortOrder":49},
  {"id":"s_work_nvlt_87_50","chapterId":"ch_work_nvlt_87","text":"朱超石與兄書曰：光武墳邊杏甚美，今奉送其核。","sortOrder":50},
  {"id":"s_work_nvlt_87_51","chapterId":"ch_work_nvlt_87","text":"王逸荔枝賦曰：魏土送西山之杏。","sortOrder":51},
  {"id":"s_work_nvlt_87_52","chapterId":"ch_work_nvlt_87","text":"《述異記》曰：賴乡老子祠有縹杏。","sortOrder":52},
  {"id":"s_work_nvlt_87_53","chapterId":"ch_work_nvlt_87","text":"《莊子》曰：孔子遊淄濰之林，休坐杏壇之上，弟子讀書，絃歌鼓琴。","sortOrder":53},
  {"id":"s_work_nvlt_87_54","chapterId":"ch_work_nvlt_87","text":"後《周書》曰：張元性廉絜，南鄰有杏兩树，杏熟，多落元園中，元悉以還主。","sortOrder":54},
  {"id":"s_work_nvlt_87_55","chapterId":"ch_work_nvlt_87","text":"《管子》曰：五沃之土，其木宜杏。","sortOrder":55},
  {"id":"s_work_nvlt_87_56","chapterId":"ch_work_nvlt_87","text":"四民月令曰：三月杏花盛，可播白沙輕土之田。","sortOrder":56},
  {"id":"s_work_nvlt_87_57","chapterId":"ch_work_nvlt_87","text":"潘嶽閒居賦曰：梅杏鬱棣，華實照烂。","sortOrder":57},
  {"id":"s_work_nvlt_87_58","chapterId":"ch_work_nvlt_87","text":"又司馬相如長門賦曰：飾文杏以為梁。","sortOrder":58},
  {"id":"s_work_nvlt_87_59","chapterId":"ch_work_nvlt_87","text":"【詩】周庾信詠杏花詩曰：春色方盈野，枝枝綻翠英，依俙暎村坞，烂熳开山成，好折待賓侣，金盤儭紅琼。","sortOrder":59},
  {"id":"s_work_nvlt_87_61","chapterId":"ch_work_nvlt_87","text":"《山海經》曰：南山其上多栗，葛山銅山，其木多栗。","sortOrder":61},
  {"id":"s_work_nvlt_87_62","chapterId":"ch_work_nvlt_87","text":"《毛詩》曰：树之榛栗。","sortOrder":62},
  {"id":"s_work_nvlt_87_63","chapterId":"ch_work_nvlt_87","text":"又雲，版有漆，隰有栗。","sortOrder":63},
  {"id":"s_work_nvlt_87_64","chapterId":"ch_work_nvlt_87","text":"《韓詩》曰：東門之栗，有靜［靜，善也。］家室，［言東門之栗树之下，有善人，可以為室家也。］","sortOrder":64},
  {"id":"s_work_nvlt_87_65","chapterId":"ch_work_nvlt_87","text":"《韓子》曰：秦饿，應侯謂王曰：五苑之果蔬橡棗栗，足以活民，請發之，王曰：今發五苑以活民，是使有功與無功互爭取也，人生而亂，不如死而治。","sortOrder":65},
  {"id":"s_work_nvlt_87_66","chapterId":"ch_work_nvlt_87","text":"《廣志》曰：栗有侯栗，關中大如雞子。","sortOrder":66},
  {"id":"s_work_nvlt_87_67","chapterId":"ch_work_nvlt_87","text":"《三秦記》曰：漢武帝果園，大栗十五枚一斗。","sortOrder":67},
  {"id":"s_work_nvlt_87_68","chapterId":"ch_work_nvlt_87","text":"《魏志》曰：東夷韓國出大栗，如梨。","sortOrder":68},
  {"id":"s_work_nvlt_87_69","chapterId":"ch_work_nvlt_87","text":"何晏《九州論》曰：中山好栗。","sortOrder":69},
  {"id":"s_work_nvlt_87_70","chapterId":"ch_work_nvlt_87","text":"袁准《觀殊俗》曰：索蘭枝而不得，見巨房之大栗。","sortOrder":70},
  {"id":"s_work_nvlt_87_71","chapterId":"ch_work_nvlt_87","text":"《袁子正書》曰：歲比不登，唯得賣棗栗瓜梨。","sortOrder":71},
  {"id":"s_work_nvlt_87_72","chapterId":"ch_work_nvlt_87","text":"盧諶《祭法》曰：春秋冬祠，皆用栗。","sortOrder":72},
  {"id":"s_work_nvlt_87_73","chapterId":"ch_work_nvlt_87","text":"《禮》曰：栗欀之。","sortOrder":73},
  {"id":"s_work_nvlt_87_74","chapterId":"ch_work_nvlt_87","text":"漢［《太平御覽》九百六十四作漢書。］燕秦千树栗，此人與千戶侯等。","sortOrder":74},
  {"id":"s_work_nvlt_87_75","chapterId":"ch_work_nvlt_87","text":"黃侔蒸栗，［本條御覽作魏略。］","sortOrder":75},
  {"id":"s_work_nvlt_87_76","chapterId":"ch_work_nvlt_87","text":"魏氏，［本條魏志四註作魏氏春秋，此有脱文。］許元［魏志註作允。］因司馬昭辭，欲殺之，帝方食栗，優人雲午等唱曰：青頭雞，青頭雞者，鸭也，帝懼不敢發。","sortOrder":76},
  {"id":"s_work_nvlt_87_77","chapterId":"ch_work_nvlt_87","text":"莊子，古者獸多民少，皆巢居以避之，晝拾橡栗，暮栖树上，故命曰有巢氏。","sortOrder":77},
  {"id":"s_work_nvlt_87_78","chapterId":"ch_work_nvlt_87","text":"梁州獻栗，径寸半。","sortOrder":78},
  {"id":"s_work_nvlt_87_79","chapterId":"ch_work_nvlt_87","text":"《西京雜記》曰：上林苑有魁栗双栗楒栗榛栗。","sortOrder":79},
  {"id":"s_work_nvlt_87_80","chapterId":"ch_work_nvlt_87","text":"《史》，蘇秦說燕文侯曰：此有棗栗之科，此謂天府也，民雖不級而足也。","sortOrder":80},
  {"id":"s_work_nvlt_87_81","chapterId":"ch_work_nvlt_87","text":"選蜀都，榛栗罅發。","sortOrder":81},
  {"id":"s_work_nvlt_87_82","chapterId":"ch_work_nvlt_87","text":"王逸荔枝賦，北燕荐朔濱之巨栗。","sortOrder":82},
  {"id":"s_work_nvlt_87_83","chapterId":"ch_work_nvlt_87","text":"侯國出栗，大如雞子。","sortOrder":83},
  {"id":"s_work_nvlt_87_84","chapterId":"ch_work_nvlt_87","text":"桂陽有栗，丛生，大如柿子。","sortOrder":84},
  {"id":"s_work_nvlt_87_85","chapterId":"ch_work_nvlt_87","text":"越中出如拳之栗。","sortOrder":85},
  {"id":"s_work_nvlt_87_86","chapterId":"ch_work_nvlt_87","text":"哀公問社於宰我，宰我對曰：夏後氏以松，殷人以柏，周人以栗，［本條《太平御覽》九百六十四作論語。］","sortOrder":86},
  {"id":"s_work_nvlt_87_87","chapterId":"ch_work_nvlt_87","text":"【賦】後漢蔡邕傷故栗賦曰：人有折蔡氏祠前栗者，故作斯賦，树遐方之嘉木，於靈宇之前庭，形猗猗以艳懋，似碧玉之精明，何根茎之丰美，將蕃炽以悠長，遇禍賊之灾人，嗟夭折以摧傷。","sortOrder":87},
  {"id":"s_work_nvlt_87_88","chapterId":"ch_work_nvlt_87","text":"【啟】梁庾堅吾謝東宮赉栗啟，查或火成，鑽以為屑，柰稱煎用，曝而成糗，未若北燕巨實，用奪榮枯，南國脯山，翻慚齒决，承恩踴躍，對聞喜之河，念報屏營，問知來之鳥。","sortOrder":88},
  {"id":"s_work_nvlt_87_89","chapterId":"ch_work_nvlt_87","text":"◇胡桃","sortOrder":89},
  {"id":"s_work_nvlt_87_90","chapterId":"ch_work_nvlt_87","text":"《廣志》曰：陳仓胡桃，薄皮多肌，陰平胡桃，大而皮脆，急捉則碎。","sortOrder":90},
  {"id":"s_work_nvlt_87_91","chapterId":"ch_work_nvlt_87","text":"《博物志》曰：張騫使西域還，得胡桃。","sortOrder":91},
  {"id":"s_work_nvlt_87_92","chapterId":"ch_work_nvlt_87","text":"《晉宮閣名》曰：華林園胡桃八十四株。","sortOrder":92},
  {"id":"s_work_nvlt_87_93","chapterId":"ch_work_nvlt_87","text":"荀氏春秋祠製曰：常設用胡桃。","sortOrder":93},
  {"id":"s_work_nvlt_87_94","chapterId":"ch_work_nvlt_87","text":"吳時外國志曰：大秦國有棗榛胡桃，莲藕雜果。","sortOrder":94},
  {"id":"s_work_nvlt_87_95","chapterId":"ch_work_nvlt_87","text":"【啟】梁沈約為柳世隆謝賜樂遊胡桃啟曰：挺自禁園，味逾井絡，動物回祇，在微必應，此乃胡羯奔逃，吉之先見者也。","sortOrder":95},
  {"id":"s_work_nvlt_87_96","chapterId":"ch_work_nvlt_87","text":"【書】後漢孔融與諸卿書曰：多惠胡桃，深知篤意。","sortOrder":96},
  {"id":"s_work_nvlt_87_97","chapterId":"ch_work_nvlt_87","text":"晉鈕滔母答吳國書曰：胡桃本生西羌，外刚朴，內柔甘，质似古賢，欲以奉貢。","sortOrder":97},
  {"id":"s_work_nvlt_87_98","chapterId":"ch_work_nvlt_87","text":"◇林檎","sortOrder":98},
  {"id":"s_work_nvlt_87_99","chapterId":"ch_work_nvlt_87","text":"《廣志》曰：林檎似赤柰，亦名黑檎，廣黑檎似赤柰，一名林檎似赤柰，［○本條訛脱複重，明本一名林檎以下作一名來禽，言味甘熟則來禽也。］","sortOrder":99},
  {"id":"s_work_nvlt_87_100","chapterId":"ch_work_nvlt_87","text":"劉楨京口記曰：南國多林檎。","sortOrder":100},
  {"id":"s_work_nvlt_87_101","chapterId":"ch_work_nvlt_87","text":"【書】梁劉孝威謝赉林檎書曰：勇聞齊國，止錫二桃，遠至仙方，裁蒙數棗。豈如恩丰漢箧，賜廣魏奁，〈女毛〉女數而仅通，筭郎計而方得，生於玉井之侧，出自金膏之地，上靈所貴，下土希逢。","sortOrder":101},
  {"id":"s_work_nvlt_87_102","chapterId":"ch_work_nvlt_87","text":"【啟】梁庾肩吾謝赉林檎啟曰：丹徒故苑，歲綿長而不見，岷山雖植，路重阻而來難，未有徙核圓丘，移根阆坂，仙厨始摘，猶青玉之盤，［句有脱文。］下賤爰頒，遂入抽蒲之座。","sortOrder":102},
  {"id":"s_work_nvlt_87_103","chapterId":"ch_work_nvlt_87","text":"◇甘藷","sortOrder":103},
  {"id":"s_work_nvlt_87_104","chapterId":"ch_work_nvlt_87","text":"似竽，［本條《太平御覽》九百七十四作陳祈畅異物志。］亦有［亦有下有巨魁二字。］剝去皮，肥［肥作肌。］肉白，南方以當米穀，賓客亦設之，出交北。","sortOrder":104},
  {"id":"s_work_nvlt_87_105","chapterId":"ch_work_nvlt_87","text":"◇沙棠","sortOrder":105},
  {"id":"s_work_nvlt_87_106","chapterId":"ch_work_nvlt_87","text":"如棠，味如李，無核。","sortOrder":106},
  {"id":"s_work_nvlt_87_107","chapterId":"ch_work_nvlt_87","text":"《呂氏春秋》：果之美者棠實。","sortOrder":107},
  {"id":"s_work_nvlt_87_109","chapterId":"ch_work_nvlt_87","text":"《神異經》曰：東南荒中，高二十丈餘，葉如甘瓜，二子成［《太平御覽》九百七十二作百歲。］落，生幸，［御覽作華。］椰如甘瓜，如兩眼，謂之萼，［御覽作華如甘瓜華，華盡落而生萼，此有訛衍。］萼越王頭［越王頭三字御覽無。］下生子，三成［御覽作歲。］而熟，形如寒瓜。","sortOrder":109},
  {"id":"s_work_nvlt_87_110","chapterId":"ch_work_nvlt_87","text":"《廣志》曰：高六七尺者，無枝條，葉如［《太平御覽》九百七十二如下有束蒲二字，蒲下有二十九字，此脱。］美如蜜，核中有白膚，厚半寸，味似胡桃，出交北。","sortOrder":110},
  {"id":"s_work_nvlt_87_111","chapterId":"ch_work_nvlt_87","text":"選曰吳，［按本條見文選吳都賦，此有脱文。］椰葉無陰。","sortOrder":111},
  {"id":"s_work_nvlt_87_112","chapterId":"ch_work_nvlt_87","text":"七命曰：剖椰子之壳。","sortOrder":112},
  {"id":"s_work_nvlt_87_113","chapterId":"ch_work_nvlt_87","text":"◇枇杷","sortOrder":113},
  {"id":"s_work_nvlt_87_114","chapterId":"ch_work_nvlt_87","text":"仲長統《昌言》曰：今人主不思甘露零，醴泉涌，而患枇杷荔支之腐，亦鄙矣。","sortOrder":114},
  {"id":"s_work_nvlt_87_115","chapterId":"ch_work_nvlt_87","text":"荆州土地記曰：宜都出大枇杷。","sortOrder":115},
  {"id":"s_work_nvlt_87_116","chapterId":"ch_work_nvlt_87","text":"《廣州記》曰：枇杷若榴，參乎京都。","sortOrder":116},
  {"id":"s_work_nvlt_87_117","chapterId":"ch_work_nvlt_87","text":"華山記曰：華山講堂西頭，有枇杷園。","sortOrder":117},
  {"id":"s_work_nvlt_87_118","chapterId":"ch_work_nvlt_87","text":"《晉宮閣名》曰：華林園枇杷四株。","sortOrder":118},
  {"id":"s_work_nvlt_87_119","chapterId":"ch_work_nvlt_87","text":"【賦】宋周祗枇杷賦曰：昔魯季孫有嘉树，韓宣子賦譽之，屈原離骚，亦著橘賦，至枇杷树，寒暑無变，負雪扬華，餘殖庭圃，遂賦之雲，名同音器，质貞松竹，四序一采，素華冬馥，霏雪润其绿蕤，商風埋其劲條，望之冥濛，即之疏寥。","sortOrder":119},
  {"id":"s_work_nvlt_87_120","chapterId":"ch_work_nvlt_87","text":"宋謝瞻安成郡庭枇杷树賦曰：伊南國之佳木，伟邦庭而延树，禀金秋之清條，抱東陽之和煦，肇寒葩於結霜，成炎果乎纖露，高臨甍首，傍拂階露。","sortOrder":120},
  {"id":"s_work_nvlt_87_121","chapterId":"ch_work_nvlt_87","text":"◇燕薁","sortOrder":121},
  {"id":"s_work_nvlt_87_122","chapterId":"ch_work_nvlt_87","text":"《毛詩》曰：六月食鬱及薁。","sortOrder":122},
  {"id":"s_work_nvlt_87_123","chapterId":"ch_work_nvlt_87","text":"魏都，萸梅及楊李留鬱，［《太平御覽》九百七十四作曹毗魏都賦曰英梅楊李，若留鬱棣，此有訛脱。］俗謂燕鬱。","sortOrder":123},
  {"id":"s_work_nvlt_87_125","chapterId":"ch_work_nvlt_87","text":"《詩》曰：隰有树檖，疏，赤羅或名山梨，今謂楊檖，树實如梨，但小耳，一名鹿梨，一名鼠梨。","sortOrder":125},
  {"id":"s_work_nvlt_87_126","chapterId":"ch_work_nvlt_87","text":"《爾雅》曰：檖，羅。","sortOrder":126},
  {"id":"s_work_nvlt_87_127","chapterId":"ch_work_nvlt_87","text":"◇蒟子","sortOrder":127},
  {"id":"s_work_nvlt_87_128","chapterId":"ch_work_nvlt_87","text":"树如桑，取其實為醬，漢音范，［本條《太平御覽》九百七十三作漢書註，范作矩，此有脱訛。］","sortOrder":128},
  {"id":"s_work_nvlt_87_129","chapterId":"ch_work_nvlt_87","text":"廣［御覽作廣志。］薆［御覽作蔓。］生依树也。","sortOrder":129},
  {"id":"s_work_nvlt_87_130","chapterId":"ch_work_nvlt_87","text":"◇枳椇","sortOrder":130},
  {"id":"s_work_nvlt_87_131","chapterId":"ch_work_nvlt_87","text":"《詩》曰：南山有枸，疏，枳椇树似白楊，子著枝端，為之木蜜，從令人酒薄，以為屋柱，酒皆薄。","sortOrder":131},
  {"id":"s_work_nvlt_87_132","chapterId":"ch_work_nvlt_87","text":"《禮》曰：婦人之贽，椇榛脯脩棗栗。","sortOrder":132},
  {"id":"s_work_nvlt_87_133","chapterId":"ch_work_nvlt_87","text":"廣志，以［《太平御覽》九百七十四作子似］珊瑚树，乾者益之矣。［御覽作益美。］","sortOrder":133},
  {"id":"s_work_nvlt_87_135","chapterId":"ch_work_nvlt_87","text":"《爾雅》曰：柚，條也，［似橙，實醋。］出江南。","sortOrder":135},
  {"id":"s_work_nvlt_87_136","chapterId":"ch_work_nvlt_87","text":"《廣志》曰：成都有柚，大如斗。","sortOrder":136},
  {"id":"s_work_nvlt_87_137","chapterId":"ch_work_nvlt_87","text":"《尚書》曰：楊州厥苞橘柚。","sortOrder":137},
  {"id":"s_work_nvlt_87_138","chapterId":"ch_work_nvlt_87","text":"《離骚》［《太平御覽》九百七十三作楚辭。］曰：斥逐鸿鵠，乃近鴟枭，斬伐橘柚，列树苦桃。","sortOrder":138},
  {"id":"s_work_nvlt_87_139","chapterId":"ch_work_nvlt_87","text":"《呂氏春秋》曰：果之美者，雲夢之柚。","sortOrder":139},
  {"id":"s_work_nvlt_87_140","chapterId":"ch_work_nvlt_87","text":"《月令》曰：食橘柚。","sortOrder":140},
  {"id":"s_work_nvlt_87_141","chapterId":"ch_work_nvlt_87","text":"《列傳》［御覽九百七十三作列子。］曰：吳越之間，有木焉，其名曰柚，树碧而冬青，實丹而味酸，度淮北為杞。","sortOrder":141},
  {"id":"s_work_nvlt_87_142","chapterId":"ch_work_nvlt_87","text":"【贊】晉郭璞柚贊曰：厥苞橘柚，精者曰甘，實染繁霜，葉鮮翠藍，屈生嘉叹，以為美談。","sortOrder":142},
  {"id":"s_work_nvlt_87_143","chapterId":"ch_work_nvlt_87","text":"◇木瓜","sortOrder":143},
  {"id":"s_work_nvlt_87_144","chapterId":"ch_work_nvlt_87","text":"《爾雅》曰：楙，木瓜也。","sortOrder":144},
  {"id":"s_work_nvlt_87_145","chapterId":"ch_work_nvlt_87","text":"《廣志》曰：木瓜子可藏，枝為杖，號一尺百二十節。","sortOrder":145},
  {"id":"s_work_nvlt_87_146","chapterId":"ch_work_nvlt_87","text":"《毛詩》曰：木瓜，美齊桓公也，衛為翟人败之，出處於漕，桓公救而封之，遺之車馬器服焉，衛人思之，欲厚報之，投我以木瓜，報之以琼琚，匪報也，永以為好也。","sortOrder":146},
  {"id":"s_work_nvlt_87_147","chapterId":"ch_work_nvlt_87","text":"《晉宮閣名》曰：華林園木瓜五株。","sortOrder":147},
  {"id":"s_work_nvlt_87_148","chapterId":"ch_work_nvlt_87","text":"【賦】宋何承天木瓜賦曰：美中州之佳树，表閒冶之麗姿，結靈根以誕秀，傾朝日以扬暉，擢丛柯之冉冉，布翠葉而蕤葳，惟茲木之在林，亦超類而獨劭，方朝華而繁實，比沙棠而有耀，當大夏之方隆，愧微幹之纖撓，豈隱扑以幸全。固呈才而不效，離眾用而獲寧，永端己以厲操，原佳人之弔投，思同歸以讬好，顧衛風之攸珍，雖琼琚而匪報。","sortOrder":148},
  {"id":"s_work_nvlt_87_149","chapterId":"ch_work_nvlt_87","text":"◇杜梨","sortOrder":149},
  {"id":"s_work_nvlt_87_150","chapterId":"ch_work_nvlt_87","text":"《爾雅》曰：杜，甘棠也，杜，赤棠，白者棠。","sortOrder":150},
  {"id":"s_work_nvlt_87_151","chapterId":"ch_work_nvlt_87","text":"《毛詩》曰：蔽芾甘棠，勿翦勿伐。","sortOrder":151},
  {"id":"s_work_nvlt_87_152","chapterId":"ch_work_nvlt_87","text":"又曰：有杕之杜，［杕，獨也。］","sortOrder":152},
  {"id":"s_work_nvlt_87_153","chapterId":"ch_work_nvlt_87","text":"《韓詩外傳》曰：邵伯在朝，有司請召民，邵伯曰：不勞一身而勞百姓，大非吾先君文王之志也，於是庐於棠树之下，百姓大悅，詩人見而歌焉。","sortOrder":153},
  {"id":"s_work_nvlt_87_154","chapterId":"ch_work_nvlt_87","text":"【賦】晉孫楚杕杜賦曰：家弟以虞氏梨賦見示，餘謂豈以梨有用之為貴，杜無用之為賤，故用獲全，所以為貴，有用獲殘，所以為賤，故賦雲之，惟有杕之為杜，齊萬物而併生，其质菲薄，既不施於器用，華葉疏悴，靡休荫之茂榮，昔在邵伯，聽訟述職，甘棠作頌，垂之罔極。","sortOrder":154},
  {"id":"s_work_nvlt_87_156","chapterId":"ch_work_nvlt_87","text":"援神契曰：仲冬昴星中，收莒芋，亦芋也。","sortOrder":156},
  {"id":"s_work_nvlt_87_157","chapterId":"ch_work_nvlt_87","text":"《說文》曰：齊人為莒。","sortOrder":157},
  {"id":"s_work_nvlt_87_158","chapterId":"ch_work_nvlt_87","text":"漢［《太平御覽》九百七十五作漢書。］汝南有鸿隙大陂，翟方［御覽方下有進字。］為丞相，秦［御覽作奏。］破之，郡中追焉，［御覽作怨。］童謠曰：懷我陂，［御覽作坏陂誰。］翟子威，飯我食，［御覽食上有豆字。］羹芋魁。","sortOrder":158},
  {"id":"s_work_nvlt_87_159","chapterId":"ch_work_nvlt_87","text":"秦破翟，［本條御覽九百七十五作《漢書》：翟作趙。］卓氏曰：吾聞岷山之下，沃野，有陰蹲鴟，至死不飢，乃求遠遷，致之於臨邛。","sortOrder":159},
  {"id":"s_work_nvlt_87_160","chapterId":"ch_work_nvlt_87","text":"《廣志》曰：有君子芋，大如斗魁，青邊芋淡善芋，大如瓶，少子，葉如彻蓋，緗色紫茎。","sortOrder":160},
  {"id":"s_work_nvlt_87_161","chapterId":"ch_work_nvlt_87","text":"本草，芋土芝。","sortOrder":161},
  {"id":"s_work_nvlt_87_162","chapterId":"ch_work_nvlt_87","text":"選蜀都，間蹲鴟之沃野，則以為世濟陽九，註，濟人飢也，葉似蹲鴟。","sortOrder":162},
  {"id":"s_work_nvlt_87_163","chapterId":"ch_work_nvlt_87","text":"◇楊梅","sortOrder":163},
  {"id":"s_work_nvlt_87_164","chapterId":"ch_work_nvlt_87","text":"《郭子》曰：楊氏子年九歲，孔君平詣其父，設果有楊梅，孔指示兒曰：此貴君家果，兒應聲答曰：未聞孔雀是夫子家禽。","sortOrder":164},
  {"id":"s_work_nvlt_87_165","chapterId":"ch_work_nvlt_87","text":"《臨海異物志》曰：楊梅，其子大如彈丸，正赤，五月中熟，熟時似梅，其味甜酸。","sortOrder":165},
  {"id":"s_work_nvlt_87_166","chapterId":"ch_work_nvlt_87","text":"裴氏《廣州記》曰：庐山顶有湖，楊梅山桃繞其际，海人時登采拾，正得於上飽，不得持下。","sortOrder":166},
  {"id":"s_work_nvlt_87_167","chapterId":"ch_work_nvlt_87","text":"《博物志》曰：地有章名，則生楊梅，無章名亦有耳，有章名無之也。","sortOrder":167},
  {"id":"s_work_nvlt_87_168","chapterId":"ch_work_nvlt_87","text":"吳興記曰：故章縣北有石郭山，上生楊梅，常以貢御。","sortOrder":168},
  {"id":"s_work_nvlt_87_169","chapterId":"ch_work_nvlt_87","text":"《南越志》曰：熙安縣多楊梅。","sortOrder":169},
  {"id":"s_work_nvlt_87_170","chapterId":"ch_work_nvlt_87","text":"【頌】梁江淹楊梅頌曰：懷蕊挺實，涵黃糅丹，鏡曰繡壑，炤霞綺峦。","sortOrder":170},
  {"id":"s_work_nvlt_87_171","chapterId":"ch_work_nvlt_87","text":"◇蒲萄","sortOrder":171},
  {"id":"s_work_nvlt_87_172","chapterId":"ch_work_nvlt_87","text":"《廣志》曰：蒲萄有黃白黑三种。","sortOrder":172},
  {"id":"s_work_nvlt_87_173","chapterId":"ch_work_nvlt_87","text":"《本草》曰：蒲萄益氣強志，令人肥健少飢，延年輕身。","sortOrder":173},
  {"id":"s_work_nvlt_87_174","chapterId":"ch_work_nvlt_87","text":"《史記》曰：大宛以蒲萄為酒，富人藏酒至萬餘石，久者數十歲不败。","sortOrder":174},
  {"id":"s_work_nvlt_87_175","chapterId":"ch_work_nvlt_87","text":"《漢書》曰：且末國無雷國罽賓國，皆有蒲萄。","sortOrder":175},
  {"id":"s_work_nvlt_87_176","chapterId":"ch_work_nvlt_87","text":"《漢武內傳》曰：西王母常下，帝設蒲萄酒。","sortOrder":176},
  {"id":"s_work_nvlt_87_177","chapterId":"ch_work_nvlt_87","text":"《續漢書》曰：敦煌張氏家傳曰：扶風孟他，以蒲萄酒一升遺張讓，即稱涼州刺史。","sortOrder":177},
  {"id":"s_work_nvlt_87_178","chapterId":"ch_work_nvlt_87","text":"《博物志》曰：西域蒲萄酒，傳雲可至十年。","sortOrder":178},
  {"id":"s_work_nvlt_87_179","chapterId":"ch_work_nvlt_87","text":"又曰：張騫使西域還，得蒲萄。","sortOrder":179},
  {"id":"s_work_nvlt_87_180","chapterId":"ch_work_nvlt_87","text":"《晉宮閣名》曰：華林園蒲萄百七十八株。","sortOrder":180},
  {"id":"s_work_nvlt_87_181","chapterId":"ch_work_nvlt_87","text":"魏文帝詔群臣曰：且說蒲萄，醉酒宿醒，掩露而食，甘而不饣肙，酸而不脆，冷而寒，味長汁多，除煩解饣肙。又酿以為酒，甘於麹米，善醉而易醒，道之固以流涎咽唾，况親食之耶，他方之果，寧有匹之者。","sortOrder":181},
  {"id":"s_work_nvlt_87_182","chapterId":"ch_work_nvlt_87","text":"《秦州記》曰：秦野多蒲萄。","sortOrder":182},
  {"id":"s_work_nvlt_87_183","chapterId":"ch_work_nvlt_87","text":"《博物志》曰：以為刍荛。","sortOrder":183},
  {"id":"s_work_nvlt_87_184","chapterId":"ch_work_nvlt_87","text":"杜恕篤［《太平御覽》九百七十二作杜篤。］邊論，漢匈［御覽匈上有征字。］奴，取胡麻蒲萄，□［御覽作稗。］麥苜蓿，示廣地。","sortOrder":184},
  {"id":"s_work_nvlt_87_185","chapterId":"ch_work_nvlt_87","text":"龟茲國胡人奢侈，家有至千斛蒲萄，漢使取實來，離宮別馆傍盡种。","sortOrder":185},
  {"id":"s_work_nvlt_87_186","chapterId":"ch_work_nvlt_87","text":"北齊李元忠，赠世宗蒲萄一盤，世宗以報白缣，遺書曰：忽惠蒲萄，良深愧仰，聊因絹百疋，以酬清德。","sortOrder":186},
  {"id":"s_work_nvlt_87_187","chapterId":"ch_work_nvlt_87","text":"漢李廣［本條《太平御覽》九百七十二作《漢書》：廣下有利字。］為二師將軍，破大宛，得蒲萄种歸漢。","sortOrder":187},
  {"id":"s_work_nvlt_87_188","chapterId":"ch_work_nvlt_87","text":"【賦】魏都，皇筱懷風，蒲萄結陰。","sortOrder":188},
  {"id":"s_work_nvlt_87_189","chapterId":"ch_work_nvlt_87","text":"魏鍾會蒲萄賦曰：美乾道之廣覆兮，佳陽泽之至淳，覽遐方之殊伟兮，無斯果之獨珍，讬靈根之玄圃，植崑山之高垠，绿葉蓊鬱，暧若重陰，翳羲和，秀房陆離，混若紫英乘素波，仰承甘液之靈露，下歙丰润於醴泉，總眾和之淑美，體至氣於自然，珍味允備，與物無儔，清濁外畅，甘旨內遒，滋醳膏润，入口散流。","sortOrder":189},
  {"id":"s_work_nvlt_87_190","chapterId":"ch_work_nvlt_87","text":"晉荀勖蒲萄賦曰：靈運宣流，休祥允淑，懿彼秋方，乾元是畜，有蒲萄之珍伟奇，［句有衍文。］應淳和而延育。","sortOrder":190},
  {"id":"s_work_nvlt_87_191","chapterId":"ch_work_nvlt_87","text":"◇槟榔","sortOrder":191},
  {"id":"s_work_nvlt_87_192","chapterId":"ch_work_nvlt_87","text":"周成雜字曰：槟榔，果也，似螺，可食。","sortOrder":192},
  {"id":"s_work_nvlt_87_193","chapterId":"ch_work_nvlt_87","text":"李當之藥錄曰：槟榔一名槟門。","sortOrder":193},
  {"id":"s_work_nvlt_87_194","chapterId":"ch_work_nvlt_87","text":"《廣志》曰：木實曰槟榔，树無枝，略如柱，其顛生穟而秀，生棘針，重叠其下，彼方珍之，以為口實，亦出交趾。","sortOrder":194},
  {"id":"s_work_nvlt_87_195","chapterId":"ch_work_nvlt_87","text":"林邑記曰：槟榔树高十餘丈，皮似青桐，節如桂竹，下森秀無柯，端顶有葉，葉似甘蕉，條派开破，仰望眇眇，如锸丛蕉於竹杪，風至獨動，似舉羽扇之扫天，葉下系數房，房缀數十子，家有數百树。","sortOrder":195},
  {"id":"s_work_nvlt_87_196","chapterId":"ch_work_nvlt_87","text":"《異物志》曰：槟榔树若筍竹生竿，近上未［《太平御覽》九百七十一作末。］五六尺間，洪覃洪肿起如瘣木焉，因拆裂出，若黍秀也，無華而為實，大如桃李，天生棘重累其下，所以御衛其實也，剖其上皮，煮其膚熟而貫之，堅如乾棗，以夫留古贲併食，則滑美下氣，及宿食消穀。","sortOrder":196},
  {"id":"s_work_nvlt_87_197","chapterId":"ch_work_nvlt_87","text":"《南中八郡志》曰：槟榔土人以為貴，婚族客必先進，若邂逅不設，用相嫌恨。","sortOrder":197},
  {"id":"s_work_nvlt_87_198","chapterId":"ch_work_nvlt_87","text":"顧徽《廣州記》曰：山槟榔形小，而大於蒳子，蒳子土人亦呼為槟榔。","sortOrder":198},
  {"id":"s_work_nvlt_87_199","chapterId":"ch_work_nvlt_87","text":"【詩】梁劉孝綽詠有人乞牛舌乳不付因餉槟榔詩曰：陳乳何能貴，烂舌不成珍，空持渝浩齒，非但汙丹唇，別有無枝實，曾要湛上人，羞比朱櫻就，詎易紫梨津，莫言蒂中久，當看心里新，微芳雖不足，含咀原相親。","sortOrder":199},
  {"id":"s_work_nvlt_87_200","chapterId":"ch_work_nvlt_87","text":"周庾信詠槟榔詩曰：绿房千子熟，紫穗百花开，莫言行萬里，曾經相識來。","sortOrder":200},
  {"id":"s_work_nvlt_87_201","chapterId":"ch_work_nvlt_87","text":"【啟】梁王孺謝賜於紘利所獻槟榔啟曰：竊以文軌一覃，充仞斯及，入侍請朔，航海梯山，獻琛奉，［句有脱文。］充庖盈府，故其取題左賦，多述瑜書，萍實非甘，荔葩慚美。","sortOrder":201},
  {"id":"s_work_nvlt_87_202","chapterId":"ch_work_nvlt_87","text":"梁庾肩吾謝赉槟榔啟曰：形均绿竹，詎扫山壇，色譬青桐，不生空井，事逾紫柰，用兼芳菊，方為口實，永以蠲痾。","sortOrder":202},
  {"id":"s_work_nvlt_87_203","chapterId":"ch_work_nvlt_87","text":"又謝東宮赉槟榔啟曰：無勞朱實，兼荔支之五滋，能發紅顏，類芙蓉之十酒，登玉案而上陳，出珠盤而下逮，泽深溫柰，恩均含棗。","sortOrder":203},
  {"id":"s_work_nvlt_87_204","chapterId":"ch_work_nvlt_87","text":"【箋】喻益期箋曰：槟榔信南越之可觀，子既非常，木亦特異，大者三围，高者九丈，葉聚树端，房構葉下，華秀房中，子結房外，其擢穗似禾，其缀實似穀，其皮似桐而厚，其節似竹而穊，其中空，其外劲，本不大，末不小，上不傾，下不邪，調直亭亭，千百若一，步其林則寥朗，庇其陰則萧條，信可以長吟，可以遠想矣，性不耐霜，不得北殖，必當遐树海南，遼然萬里，弗遇長者之目，自令恨深。","sortOrder":204},
  {"id":"s_work_nvlt_87_205","chapterId":"ch_work_nvlt_87","text":"◇荔支","sortOrder":205},
  {"id":"s_work_nvlt_87_206","chapterId":"ch_work_nvlt_87","text":"《廣志》曰：荔支树高五六丈，大如桂树，绿葉蓬蓬，冬夏榮茂，青華朱實，大如雞子，核黃黑，似熟莲子，實白如昉，甘而多汁，似安石榴，有甜醋者，至日將中，翕然俱赤，則可食也，一树下子百斛。","sortOrder":206},
  {"id":"s_work_nvlt_87_207","chapterId":"ch_work_nvlt_87","text":"《東觀漢記》曰：单於來朝，賜橙橘龍眼荔支。","sortOrder":207},
  {"id":"s_work_nvlt_87_208","chapterId":"ch_work_nvlt_87","text":"謝承《後漢書》曰：汝南唐羌，為臨武長，縣接交州，州舊貢荔支及生犀獻之，羌上書諫，乃止。","sortOrder":208},
  {"id":"s_work_nvlt_87_209","chapterId":"ch_work_nvlt_87","text":"《吳錄》曰：蒼梧多荔支，生山中，人家亦种之。","sortOrder":209},
  {"id":"s_work_nvlt_87_210","chapterId":"ch_work_nvlt_87","text":"魏文帝詔群臣曰：南方有龍眼荔支，寧比西園［《太平御覽》九百七十一作國。］蒲萄石蜜。","sortOrder":210},
  {"id":"s_work_nvlt_87_211","chapterId":"ch_work_nvlt_87","text":"竺法真登羅山疏曰：荔支似冬青，夏至日子赤，可食。","sortOrder":211},
  {"id":"s_work_nvlt_87_212","chapterId":"ch_work_nvlt_87","text":"《南中八郡志》曰：犍為僰道縣出荔支。","sortOrder":212},
  {"id":"s_work_nvlt_87_213","chapterId":"ch_work_nvlt_87","text":"【詩】梁劉霁詠荔支詩曰：叔師貴其珍，武仲稱斯美，良由自遠致，含滋不留齒。","sortOrder":213},
  {"id":"s_work_nvlt_87_214","chapterId":"ch_work_nvlt_87","text":"【賦】後漢王逸荔支賦曰：暧若朝雲之興，森如橫天之彗，湛若大厦之容，鬱如峻嶽之势，脩幹紛错，绿葉臻臻，灼灼若朝霞之暎日，離離如繁星之著天，皮似丹罽，膚若明璫，润侔和璧，奇喻五黃，仰叹麗表，俯嘗嘉味，口含甘液，心受芳氣，兼五滋而無常主，不知百和之所出，卓絕類而無儔，超眾果而獨貴。","sortOrder":214},
  {"id":"s_work_nvlt_87_215","chapterId":"ch_work_nvlt_87","text":"【啟】齊孔稚珪謝賜生荔支啟曰：绿葉雲舒，朱實星映，離離昔聞，晔晔今睹，信西〈山氏〉之佳珍，谅東鄙之未識。","sortOrder":215},
  {"id":"s_work_nvlt_87_216","chapterId":"ch_work_nvlt_87","text":"王逸賦，［已見上。］角卯興而靈華敷，大火中而朱實繁，灼灼丹華吐日，離離繁星著天。","sortOrder":216},
  {"id":"s_work_nvlt_87_217","chapterId":"ch_work_nvlt_87","text":"七命，坼龍眼之房也。","sortOrder":217},
  {"id":"s_work_nvlt_87_218","chapterId":"ch_work_nvlt_87","text":"◇益智","sortOrder":218},
  {"id":"s_work_nvlt_87_219","chapterId":"ch_work_nvlt_87","text":"《廣志》曰：益智葉似丛［《太平御覽》九百七十二作襄，按當作蘘。］荷，長丈餘，其根有小枝，高者八九寸，無葉萼，其子丛生著之，大如棗，中辨黑皮白，核小者曰益智，含之攝泛［《太平御覽》九百七十二作涎。］濊，出萬寿，亦生交趾。","sortOrder":219},
  {"id":"s_work_nvlt_87_220","chapterId":"ch_work_nvlt_87","text":"南方草物状曰：益智子如筆毫，長七八分，二月華，色似莲，著實五六月熟，味辛，雜五味，中芬芳，亦可鹽曝，出交趾合浦。","sortOrder":220},
  {"id":"s_work_nvlt_87_221","chapterId":"ch_work_nvlt_87","text":"顧徽《廣州記》曰：益智葉如蘘荷，茎如竹箭，子從心出，一枝有十子，子肉白滑，四破去之，取外皮，蜜煮為粽，味辛。","sortOrder":221},
  {"id":"s_work_nvlt_87_222","chapterId":"ch_work_nvlt_87","text":"周景式庐山記曰：山果有益智蒲萄。","sortOrder":222},
  {"id":"s_work_nvlt_87_223","chapterId":"ch_work_nvlt_87","text":"三十六國春秋曰：安帝元年，盧循為廣州刺史，循遺裕益智粽，裕乃答以續命湯。","sortOrder":223},
  {"id":"s_work_nvlt_87_224","chapterId":"ch_work_nvlt_87","text":"【詩】梁劉孝勝詠益智詩曰：挺芳銅嶺上，擢穎石門端，連丛去本葉，雜和委雕盤，寧推不迷草，詎滅聰明丸，傥逢公子宴，方永厭夜歡。","sortOrder":224},
  {"id":"s_work_nvlt_87_225","chapterId":"ch_work_nvlt_87","text":"【書】慧遠法師答盧循書曰：損餉六种，深抱情至，益智乃是一方異味，即於僧中行之。","sortOrder":225},
  {"id":"s_work_nvlt_87_227","chapterId":"ch_work_nvlt_87","text":"《古今註》曰：椹，桑實也。","sortOrder":227},
  {"id":"s_work_nvlt_87_228","chapterId":"ch_work_nvlt_87","text":"《詩》曰：食我桑椹，懷我好音，於嗟鳩兮，無食桑椹。","sortOrder":228},
  {"id":"s_work_nvlt_87_229","chapterId":"ch_work_nvlt_87","text":"武［本條《太平御覽》九百七十三作漢武內傳，此有脱文。］藥有扶桑丹椹。","sortOrder":229},
  {"id":"s_work_nvlt_87_230","chapterId":"ch_work_nvlt_87","text":"魏略，楊沛［楊沛下有脱文，見御覽九百七十三。］","sortOrder":230},
  {"id":"s_work_nvlt_87_231","chapterId":"ch_work_nvlt_87","text":"《世說》：張天錫為晉孝武，［《太平御覽》九百七十三武下有所器二字。］問北方何物可貴，對曰：桑椹香食，人無嫉心。","sortOrder":231},
  {"id":"s_work_nvlt_87_232","chapterId":"ch_work_nvlt_87","text":"北方白椹，長數寸，甚美，［本條御覽九百七十三作異苑。］","sortOrder":232},
  {"id":"s_work_nvlt_87_233","chapterId":"ch_work_nvlt_87","text":"東方有八十丈桑，上有椹，長三尺五寸，圓與長等，［本條御覽九百七十三作東方朔神異記。］","sortOrder":233},
  {"id":"s_work_nvlt_87_234","chapterId":"ch_work_nvlt_87","text":"王甲以北方椹比江東黃甘，於是引甲為賓客，初謝公為甲妄言，甲乃買駿馬，投椹熟時，致十枚，［本條御覽九百七十三作《世說》：此有脱文。］","sortOrder":234},
  {"id":"s_work_nvlt_87_235","chapterId":"ch_work_nvlt_87","text":"◇芭蕉","sortOrder":235},
  {"id":"s_work_nvlt_87_236","chapterId":"ch_work_nvlt_87","text":"《廣志》曰：芭蕉一曰芭苴，或曰甘蕉茎如荷芋，重皮相裹，大如盂斗，葉廣尺，長一丈，有角子，長六七寸四五寸二三寸，兩兩共對，若相抱形，剝其上皮，色黃白，味似蒲萄，甜而脆，亦飽人，其茎解散如絲，績以為葛，謂之蕉葛，雖脆而好，色黃白，不如葛赤色也，出交趾建安。","sortOrder":236},
  {"id":"s_work_nvlt_87_237","chapterId":"ch_work_nvlt_87","text":"《南州異物志》曰：甘蕉草類，望之如树株，大者一围餘，葉長一丈，或七八尺餘，二尺許，華大如酒杯，形色如芙蓉，著茎末，百餘子大，名為房，根似芋塊，大者如車轂，實隨華長，每華一阖，各有六子，先後相次，子不俱生，華不俱落，此蕉有三种，一种子大如手拇指長而銳，有似羊角，名羊角蕉，味最甘好，一种子大如雞卵，有似羊乳，名牛乳蕉，微滅［《太平御覽》九百七十五作减。］羊角，一种大如藕，長六七寸，形正方，少甘，最不好也，取其阖，以灰練之，績以為采。","sortOrder":237},
  {"id":"s_work_nvlt_87_238","chapterId":"ch_work_nvlt_87","text":"《異物志》曰：芭蕉茎如芋，取镬煮之如絲，可紡績為絺绤。","sortOrder":238},
  {"id":"s_work_nvlt_87_239","chapterId":"ch_work_nvlt_87","text":"南方草物状曰：蕉树子房相連累，甜美，亦可蜜藏。","sortOrder":239},
  {"id":"s_work_nvlt_87_240","chapterId":"ch_work_nvlt_87","text":"遊名山志曰：赤巖山，水石之間，唯有甘蕉林，高者十丈。","sortOrder":240},
  {"id":"s_work_nvlt_87_241","chapterId":"ch_work_nvlt_87","text":"《晉宮閣名》曰：華林園有芭蕉二株。","sortOrder":241},
  {"id":"s_work_nvlt_87_242","chapterId":"ch_work_nvlt_87","text":"顧徽《廣州記》曰：甘蕉與蕉，花實根葉不異，直是江［《太平御覽》九百七十五作南。］土暖，不紅［御覽作經。］霜冻，四時花葉，展其熟耳，未熟時亦苦涩。","sortOrder":242},
  {"id":"s_work_nvlt_87_243","chapterId":"ch_work_nvlt_87","text":"【詩】梁沈約詠甘蕉詩曰：抽葉固盈丈，擢本信兼围，流甘揜椰實，弱縷冠絺衣。","sortOrder":243},
  {"id":"s_work_nvlt_87_244","chapterId":"ch_work_nvlt_87","text":"【賦】梁徐摛冬蕉卷心賦曰：拔殘心於孤翠，植晚玩於冬餘，枝橫風而碎色，葉渍雪而傍枯。","sortOrder":244},
  {"id":"s_work_nvlt_87_245","chapterId":"ch_work_nvlt_87","text":"【贊】宋謝靈運芭蕉贊曰：生分本多端，芭蕉知不一，合萼不結核，敷華何由實，至人善取譬，無宰誰能律，莫昵緣合時，當视分散日。","sortOrder":245},
  {"id":"s_work_nvlt_87_246","chapterId":"ch_work_nvlt_87","text":"宋卞敬宗甘蕉贊曰：扶疏似树，质則非木，高舒垂荫，異秀延矚，厥實惟甘，味之無足。","sortOrder":246},
  {"id":"s_work_nvlt_87_247","chapterId":"ch_work_nvlt_87","text":"【文】梁沈約脩竹彈甘蕉文曰：長兼淇園貞幹臣脩竹稽首，臣聞芟荑蘊崇，農夫之善法，無使滋蔓，翦惡之良圖，未有蠹苗害稼，不加窮伐者也，切尋蘇台前甘蕉一丛，宿漸雲露，荏苒歲月，擢本盈尋，垂荫含丈，階緣寵渥，鈴衡百卉，而與奪乖爽，高下在心，每叨天功，以為己力，風聞籍聽，非复一涂，猶謂愛憎異說，所以掛乎嚴網，今月某日，有台西階泽蘭萱草，到園同訴，自稱雖慚杞梓，頗異蒿蓬，陽景所臨，由來無隔，今月某日，巫岫斂雲，臻樓开照，乾光弘普，罔幽不矚，而甘蕉攒茎布影，獨見鄣蔽，雖處台隅，遂同幽穀，臣謂偏辭難信，敢察以情，登攝甘蕉左近杜若江離，依源辨覆，兩草各處，異列同款，既有證據，羌非風聞，切尋甘蕉出自藥草，本無芬馥之香，柯條之任，非有松柏後彫之心，蓋闕葵藿傾陽之識，冯籍慶會，稽絕倫等，而得人之譽靡即，稱平之聲寂寞，遂使言树之草，忘忧之用莫施，無絕之芳，當門之弊斯在，妨賢败政，孰過於此，而不除戮，憲章安用，請以見事，徙根翦葉，斥出台外，庶懲彼將來，謝此眾屈。","sortOrder":247},
  {"id":"s_work_nvlt_87_248","chapterId":"ch_work_nvlt_87","text":"◇甘蔗","sortOrder":248},
  {"id":"s_work_nvlt_87_249","chapterId":"ch_work_nvlt_87","text":"《說文》曰：諸蔗也。","sortOrder":249},
  {"id":"s_work_nvlt_87_250","chapterId":"ch_work_nvlt_87","text":"《廣志》曰：幹蔗其餳為石蜜。","sortOrder":250},
  {"id":"s_work_nvlt_87_251","chapterId":"ch_work_nvlt_87","text":"《神異經》曰：南方荒內，有盰睹林焉，其高百丈，围三丈八尺，促節多汁，甜如蜜。","sortOrder":251},
  {"id":"s_work_nvlt_87_252","chapterId":"ch_work_nvlt_87","text":"魏文帝《典論》曰：常與平虜將軍劉勋奋威邓展等共飲，宿聞展有手臂，晓五兵，餘與論劍良久，謂餘言，將軍法非也，求與餘對，酒酣耳熱，方食幹蔗，便以為杖，下殿數交，三中其臂，左右大笑。","sortOrder":252},
  {"id":"s_work_nvlt_87_253","chapterId":"ch_work_nvlt_87","text":"《江表傳》曰：孫亮使黃門，以銀碗併蓋，就中藏吏取交州所獻甘蔗餳，黃門先恨藏吏，以鼠矢投餳中，啟言吏不謹亮呼吏持餳器入，問曰：此器既蓋之，有油覆，無緣有此，黃門將有恨汝耶，吏叩頭曰：嘗從某求官莞席，席有數，不敢與，亮曰：必是此也，問之具服。","sortOrder":253},
  {"id":"s_work_nvlt_87_254","chapterId":"ch_work_nvlt_87","text":"《南中八郡志》曰：交阯有甘蔗，围數寸，長丈餘，頗似竹，斷而食之，甚甘，笮取汁，曝數時成飴，入口消釋，彼人謂之石蜜。","sortOrder":254},
  {"id":"s_work_nvlt_87_255","chapterId":"ch_work_nvlt_87","text":"沈約《宋書》曰：魏主致意安北，遠來疲乏，若有甘蔗及酒，可見分惠，世祖遣人答曰：知行路多乏，今付酒二器，甘蔗百挺也，《漢書》：百味旨酒布蘭生，太尊柘漿析醒，［《太平御覽》九百七十四，醒上有朝字。］","sortOrder":255},
  {"id":"s_work_nvlt_87_256","chapterId":"ch_work_nvlt_87","text":"骚，臑鱉炮焦有柘漿。","sortOrder":256},
  {"id":"s_work_nvlt_87_257","chapterId":"ch_work_nvlt_87","text":"《世說》曰：顧凯之為虎頭將軍，每食蔗，自尾至本，人或問，曰：漸入佳境。","sortOrder":257},
  {"id":"s_work_nvlt_87_258","chapterId":"ch_work_nvlt_87","text":"又曰：扶南蔗一丈三節，見日即消，風吹即折。","sortOrder":258},
  {"id":"s_work_nvlt_87_259","chapterId":"ch_work_nvlt_87","text":"【詩】魏陳王曹植詩曰：都蔗雖甘，杖之必折，巧言雖美，用之必滅。","sortOrder":259},
  {"id":"s_work_nvlt_87_260","chapterId":"ch_work_nvlt_87","text":"【賦】晉張协都蔗賦曰：若乃九秋良朝，玄酎初出，黃華浮觴，酣飲累日，挫斯蔗而療渴，若嗽醴而含蜜，清滋津於紫梨，流液丰於朱橘，擇蘇妙而不逮，何况沙棠與椰實。","sortOrder":260},
  {"id":"s_work_nvlt_87_262","chapterId":"ch_work_nvlt_87","text":"《爾雅》曰：瓞瓝其紹瓞，［郭註，俗呼瓝為瓞紹者，瓜蔓緒亦著子，但小耳。］","sortOrder":262},
  {"id":"s_work_nvlt_87_263","chapterId":"ch_work_nvlt_87","text":"《廣志》曰：瓜之所出，以遼東庐江敦煌之种為美，有魚瓜，狸頭瓜，蜜筩瓜，女臂瓜，羊核瓜，如［《太平御覽》九百七十八如上有又有魚瓜犬瓜六字。］斛，出涼州，舊陽城御瓜，有青登瓜，大如三斗魁，有桂枝瓜，長二尺餘，蜀地溫，食瓜至冬熟。","sortOrder":263},
  {"id":"s_work_nvlt_87_264","chapterId":"ch_work_nvlt_87","text":"《禮記》曰：為天子削瓜者，副之，巾以絺，為國君者華之，［華，中列之巾以绤。］為大夫累之，［裸也，不巾覆也。］士疐之，庶人龁之。","sortOrder":264},
  {"id":"s_work_nvlt_87_265","chapterId":"ch_work_nvlt_87","text":"《毛詩》曰：綿綿瓜瓞，民之初生。","sortOrder":265},
  {"id":"s_work_nvlt_87_266","chapterId":"ch_work_nvlt_87","text":"《左傳》曰：齊侯使連稱管至父戍葵丘，瓜時而往，曰：及瓜而代。","sortOrder":266},
  {"id":"s_work_nvlt_87_267","chapterId":"ch_work_nvlt_87","text":"《龍魚河圖》曰：瓜有兩鼻者殺人。","sortOrder":267},
  {"id":"s_work_nvlt_87_268","chapterId":"ch_work_nvlt_87","text":"古文琐語曰：初刑史子臣謂宋景公曰：從今以往五祀日，臣死，自臣死後五年，五月丁亥，吳亡，以後五祀，八月辛巳，君薨，刑史子臣至死日，朝見景公，夕而死，後吳亡，景公懼，思刑史子臣之言，將死日，乃逃於瓜圃，遂死焉，求得，以虫矣。","sortOrder":268},
  {"id":"s_work_nvlt_87_269","chapterId":"ch_work_nvlt_87","text":"《家語》曰：曾子芸瓜而誤斬其根，曾晳怒，大杖击其背，曾子仆地，有頃乃蘇，孔子聞之，告門弟子曰：參來勿內也，曾子使人請孔子，子曰：舜之事瞽叟，得小捶則受，大杖則走，今參事父，委身以待暴怒，身死陷父於不義，不孝孰大焉。","sortOrder":269},
  {"id":"s_work_nvlt_87_270","chapterId":"ch_work_nvlt_87","text":"《贾誼書》曰：梁大夫宋就為邊縣令，與楚鄰界，梁楚邊亭皆种瓜，梁亭劬力數灌，其瓜美，楚人窊而希灌，其瓜惡，楚令以梁瓜之美怒，因往夜竊搔梁瓜，梁覺之，欲往報搔楚瓜，宋就曰：是構怨之道也，乃令人夜往，竊為楚灌瓜，楚旦生，［《太平御覽》九百七十八作往。］則已灌瓜，伺而察之，則梁亭為也，楚令大悅，因具聞楚王，楚王乃謝以重幣，故梁楚之驩，由宋就也。","sortOrder":270},
  {"id":"s_work_nvlt_87_271","chapterId":"ch_work_nvlt_87","text":"古文奇字曰：秦始皇密令人种瓜於驪山硎穀中溫處，瓜實成，使人上書曰：瓜冬有實，有詔下博士諸生說之，人人各異，則皆使往视之，而為伏機，諸儒生皆至，方相難不决，因發機，從上填之以土，皆壓死。","sortOrder":271},
  {"id":"s_work_nvlt_87_272","chapterId":"ch_work_nvlt_87","text":"《續漢書》曰：安帝時，有瓜異本共生，時以為嘉瓜。","sortOrder":272},
  {"id":"s_work_nvlt_87_273","chapterId":"ch_work_nvlt_87","text":"《漢武內傳》曰：西王母仙上藥，有空同靈瓜。","sortOrder":273},
  {"id":"s_work_nvlt_87_274","chapterId":"ch_work_nvlt_87","text":"又曰：西王母謂上元夫人曰：後造火朱［內傳作朱火。］山陵，食靈瓜，其味甚好，憶此味久，已七千歲矣。","sortOrder":274},
  {"id":"s_work_nvlt_87_275","chapterId":"ch_work_nvlt_87","text":"《吳越春秋》曰：吳王夫差，為越所败，遁而去，得自生之瓜食之也。","sortOrder":275},
  {"id":"s_work_nvlt_87_276","chapterId":"ch_work_nvlt_87","text":"《吳錄》曰：姚俊常种瓜菜，灌園以供衣食，時人或餉，一無所受。","sortOrder":276},
  {"id":"s_work_nvlt_87_277","chapterId":"ch_work_nvlt_87","text":"《吳志》曰：步骘避難江南，单身窮困，种瓜自給。","sortOrder":277},
  {"id":"s_work_nvlt_87_278","chapterId":"ch_work_nvlt_87","text":"《博物志》曰：人以冷水自渍至膝，可頓啖數十枚瓜，渍至腰，啖轉多，至頸，可啖百餘枚，所渍水又皆作瓜氣瓜味。","sortOrder":278},
  {"id":"s_work_nvlt_87_279","chapterId":"ch_work_nvlt_87","text":"《神仙傳》曰：葛玄冬為客及［《太平御覽》九百七十八作設。］生棗及生瓜晉錄曰鹹寧中嘉瓜同蒂生於成都，《抱朴子》曰：五原蔡誕，入山而還，欺家人，雲至崑崙，崑崙山有玉瓜，光明洞澈而堅，須以玉井水洗之，便软而可食。","sortOrder":279},
  {"id":"s_work_nvlt_87_280","chapterId":"ch_work_nvlt_87","text":"《搜神記》曰：時有徐光，常行術於市里，從人乞瓜，其主勿與，便從索瓣，扙地而种之，俄而瓜生蔓延，生花成實，乃取食之，因賜觀者，鬻者反视所出賣，皆亡耗矣。","sortOrder":280},
  {"id":"s_work_nvlt_87_281","chapterId":"ch_work_nvlt_87","text":"曹娥父溺死，娥見瓜浮，得尸，［出幽明錄。］","sortOrder":281},
  {"id":"s_work_nvlt_87_282","chapterId":"ch_work_nvlt_87","text":"孫鍾，富春人，與母居，至孝篤信，种瓜為業，忽有三年少來乞瓜，為鍾定墓地，出門悉化為白鶴，［孫權祖也。］","sortOrder":282},
  {"id":"s_work_nvlt_87_283","chapterId":"ch_work_nvlt_87","text":"《毛詩》曰：文王之興，本由大王也，綿綿瓜瓞，瓜瓞唪唪，民之初生，自土漆沮，王化之本。","sortOrder":283},
  {"id":"s_work_nvlt_87_284","chapterId":"ch_work_nvlt_87","text":"神仙傳，有青登瓜，大如三斗魁，玄表丹里，呈素含紅，攬之者寿，食之者仙。","sortOrder":284},
  {"id":"s_work_nvlt_87_285","chapterId":"ch_work_nvlt_87","text":"地官曰：委人，掌畜聚物瓜瓠芋葵。","sortOrder":285},
  {"id":"s_work_nvlt_87_286","chapterId":"ch_work_nvlt_87","text":"《禮》曰：仲冬行秋令，則天雨汁，瓜瓠不成，［雨雪雜下。］","sortOrder":286},
  {"id":"s_work_nvlt_87_287","chapterId":"ch_work_nvlt_87","text":"《論語》曰：吾豈匏瓜也哉，焉能系而不食。","sortOrder":287},
  {"id":"s_work_nvlt_87_288","chapterId":"ch_work_nvlt_87","text":"《史記》曰：邵平故秦東陵侯，秦滅後，為布衣，种瓜長安城東，种瓜有五色，甚美，故世謂之東陵瓜。又雲青門瓜，青門東陵也。","sortOrder":288},
  {"id":"s_work_nvlt_87_289","chapterId":"ch_work_nvlt_87","text":"武［《太平御覽》九百七十八作漢武內傳。］仙山［御覽作之。］上藥，有雲［御覽作空同二字。］靈瓜，四劫不實。","sortOrder":289},
  {"id":"s_work_nvlt_87_290","chapterId":"ch_work_nvlt_87","text":"後魏，［《太平御覽》九百七十八作後魏書。］郭祚領太子少師，肅宗幼弱，祚懷一黃〈扁瓜〉，出奉肅宗，時趙桃子深為世宗所信，祚私事之，人號為桃弓仆射，黃瓜少師。","sortOrder":290},
  {"id":"s_work_nvlt_87_291","chapterId":"ch_work_nvlt_87","text":"《列仙傳》曰：漢［《太平御覽》九百七十八作溪人。］者，南郡偏人，居山門，仙人從買瓜，教之練瓜，與附子桂實，共藏春花服之，一年飛登山入水，聞往來海邊諸洞中，仙人博赌瓜，黃瓜數千頃，令暝耳，乃上方丈山。","sortOrder":291},
  {"id":"s_work_nvlt_87_292","chapterId":"ch_work_nvlt_87","text":"《本草經》曰：水芝者，是白瓜甘瓜也。","sortOrder":292},
  {"id":"s_work_nvlt_87_293","chapterId":"ch_work_nvlt_87","text":"晉［《太平御覽》九百七十八作晉書。］桑虞，字子深，家園有瓜熟，有人逾盜之，虞見，以園篱多棘刺，使人為开道，及盜負出，見道通，知虞使除之，乃送瓜，叩頭請罪，虞與之。","sortOrder":293},
  {"id":"s_work_nvlt_87_294","chapterId":"ch_work_nvlt_87","text":"齊，［《太平御覽》九百七十八作沈約齊記。］韓虞［御覽作靈。］敏兄靈珍，早孤，併有孝性，家貧，無以營凶，共种半畝瓜，朝采暮又生，遂辦葬事。","sortOrder":294},
  {"id":"s_work_nvlt_87_295","chapterId":"ch_work_nvlt_87","text":"劉揮，字茂謙，從明帝射雉於野，渴倦，得早春瓜，與上树剖而食之，上懷其舊德，意所良厚，至是一歲三遷，轉御史中丞。","sortOrder":295},
  {"id":"s_work_nvlt_87_296","chapterId":"ch_work_nvlt_87","text":"梁［《太平御覽》九百七十八作梁書。］任昉，字彦升，死，高祖方食四苑纖瓜，聞之投瓜，悲不自勝。","sortOrder":296},
  {"id":"s_work_nvlt_87_297","chapterId":"ch_work_nvlt_87","text":"《洞冥記》曰：有龍肝瓜，長一尺，花紅葉素，生於冰穀，所謂冰穀素葉瓜，霍山下有洞台，司命君府也，中有神盤瓜靈瓜，食之者至玄也。","sortOrder":297},
  {"id":"s_work_nvlt_87_298","chapterId":"ch_work_nvlt_87","text":"《莊子》曰：朽瓜化為魚，物之变。","sortOrder":298},
  {"id":"s_work_nvlt_87_299","chapterId":"ch_work_nvlt_87","text":"《文選》曰：魏文帝與吳质書，沉甘瓜於清泉。","sortOrder":299},
  {"id":"s_work_nvlt_87_300","chapterId":"ch_work_nvlt_87","text":"劉楨瓜賦曰：［按見後。］三心在隅，溫風節暮，杭翘放藤，流美遠布，黃花炳晔，潛實獨著，丰細異形，圓方殊務。","sortOrder":300},
  {"id":"s_work_nvlt_87_301","chapterId":"ch_work_nvlt_87","text":"晉太康八年，王濬園生嘉瓜，二茎一實。","sortOrder":301},
  {"id":"s_work_nvlt_87_302","chapterId":"ch_work_nvlt_87","text":"【詩】晉阮籍詩，昔聞東陵瓜，近在青門外，連畛距阡陌，子母相拘帶，五色曜朝日，嘉賓四面會。","sortOrder":302},
  {"id":"s_work_nvlt_87_303","chapterId":"ch_work_nvlt_87","text":"【賦】魏劉楨瓜賦曰：丰細異形，圓方殊務，扬暉發藻，九采雜糅，厥初作苦。終然允甘，應時湫熟，含蘭吐芳，藍皮密理，素肌丹瓤，乃命圃師，貢其最良。投諸清流，一浮一藏，折以金刀，四剖三離，承之以雕盤，幂之以纖絺，甘逾蜜房，冷亚冰圭。","sortOrder":303},
  {"id":"s_work_nvlt_87_304","chapterId":"ch_work_nvlt_87","text":"晉陆機瓜賦曰：發金榮於秀翘，結玉實於宗柯，蔽翠景以因育，缀脩茎而星羅。夫其种族類數，則有括樓定桃，黃〈扁瓜〉白傳，金叉蜜筩，小青大班，玄骭素碗，狸首虎蹯，東陵出於秦穀，桂髓起於巫山，五色比象，殊形異端，或摅文以抱绿。或披素而懷丹，氣洪細而俱芬，體脩短而必圓，芳鬱烈其充堂，味窮理而不饣肙，德弘濟於飢渴，道殊流於貴賤，若夫擢以寒水，淬以夏凌，越氣外斂，溫液密凝，體猶握虛，離若剖冰。","sortOrder":304},
  {"id":"s_work_nvlt_87_305","chapterId":"ch_work_nvlt_87","text":"晉嵇含瓜賦曰：世雲三芝，瓜處一焉，故植根玉巖，润葉飛泉，攬之者寿，食之者仙，是謂雲芝，芙蕖振采濯茎，玄瀨葩映，莫此為最，是謂水芝，甘瓜普植，用荐神祇，其名既贍，其味亦奇，是謂土芝，乃剖甘瓜，既淳且馨，荒者饗之，忘困解酲，流味通其五藏，冷氣反其迷精。","sortOrder":305},
  {"id":"s_work_nvlt_87_306","chapterId":"ch_work_nvlt_87","text":"晉張載瓜賦曰：羊骹虎掌，桂枝蜜筩，或玄表丹里，程素含紅，丰膚外伟，绿瓤內醲，甘柤夏熟，丹〈木柰〉含芳，朱李零於桂圃，蒲萄潰於椒床，雖茲肴之孤起，莫斯瓜之允臧，超椰子於南海，越橘柚於衡陽，若乃槟榔椰實，龍眼荔支，徒以希珍，難致為奇，論實比德，孰大於斯。","sortOrder":306},
  {"id":"s_work_nvlt_87_307","chapterId":"ch_work_nvlt_87","text":"晉傅玄瓜賦曰：應運俟時，負甲徐生，次落英之密葉，交萎私之脩茎，重簡其珍，沉之清源，披之吳刀，承以朱盤，中剖四破，雖分若濬，［《初學記》二十八作完。］质兼五味，氣美芳蘭，愈得冷而益甘，颐神爽而解煩，細肌密理，多瓤少瓣，丰指絕異，食之不饣肙。","sortOrder":307},
  {"id":"s_work_nvlt_87_308","chapterId":"ch_work_nvlt_87","text":"梁張缵瓜賦曰：惟茲瓜之實茂，體太素之純精，翕玄润於浮霄，含皇泽於夏庭，於是蒼春發歲，天地交和，乃啟沃壤，是殖是播，納佳种於畦畹，應時運而剖牙，揮萌散孽，栽葉負柯，蓊茸鬱薈，莽｛艹尊｝婆娑，晞慶雲以吐蕤，仰旭日之敷花，朝希重陽，夕承朗月，清露湛而宵降，翔風穆以晨發，振柯翘之繞若，顧惠氣以滋悅，感靈化而絪缊，睹佳實之併結，始懷徵而苦發，終感宮而甘通，信不和而自馨，與九鼎乎齊功，蔓草是藉，密葉是蔽，潛湫獨熟，墮茎落蒂，芬馥酷烈，氣畅雲际，申狄不能詳其味，隸首不能為之計，昔東陵之甘瓜，美顯名於中古，彼服闾之攸簷，乃眾仙之所睹，美人神之同好，何厥用之弘普，惟令實於無窮，永可殖於靈圃。","sortOrder":308},
  {"id":"s_work_nvlt_87_309","chapterId":"ch_work_nvlt_87","text":"【啟】梁帝謝東宮赉瓜啟曰：金榮始荐，琼蕊載珍，味奪蔗漿，甘逾石蜜。","sortOrder":309},
  {"id":"s_work_nvlt_87_310","chapterId":"ch_work_nvlt_87","text":"《藝文類聚》　唐·欧陽詢","sortOrder":310},
  {"id":"s_work_nvlt_88_1","chapterId":"ch_work_nvlt_88","text":"卷八十八木部上","sortOrder":1},
  {"id":"s_work_nvlt_88_2","chapterId":"ch_work_nvlt_88","text":"○木［花葉附］松柏槐桑榆桐","sortOrder":2},
  {"id":"s_work_nvlt_88_4","chapterId":"ch_work_nvlt_88","text":"《春秋元命苞》曰：木之為言觸也，氣動躍也。","sortOrder":4},
  {"id":"s_work_nvlt_88_5","chapterId":"ch_work_nvlt_88","text":"《易》曰：巽為木，坎，其於木也為堅多心，艮，其於木也為堅多節，離，其於木也為科上槁，［堅多心謂刚中也，山木堅直，故多節也，陰含氣，故曰科，科，空也，為日所乾，故上槁。］","sortOrder":5},
  {"id":"s_work_nvlt_88_6","chapterId":"ch_work_nvlt_88","text":"又曰：地中生木升，君子以積小成高大。","sortOrder":6},
  {"id":"s_work_nvlt_88_7","chapterId":"ch_work_nvlt_88","text":"《爾雅》曰：木族生為灌，灌木，丛木也。","sortOrder":7},
  {"id":"s_work_nvlt_88_8","chapterId":"ch_work_nvlt_88","text":"《尚書》曰：兖州厥木惟條，［長也。］楊州厥木惟乔，［高也。］","sortOrder":8},
  {"id":"s_work_nvlt_88_9","chapterId":"ch_work_nvlt_88","text":"又曰：三曰木，木曰曲直，曲直作酸。","sortOrder":9},
  {"id":"s_work_nvlt_88_10","chapterId":"ch_work_nvlt_88","text":"《禮記》：孟春之月，盛德在木，孟春之月，無伐大树，［妨農故也。］","sortOrder":10},
  {"id":"s_work_nvlt_88_11","chapterId":"ch_work_nvlt_88","text":"毛詩曰：黃鳥於飛，集於灌木。","sortOrder":11},
  {"id":"s_work_nvlt_88_12","chapterId":"ch_work_nvlt_88","text":"又曰：樛木，後妃逮下也。","sortOrder":12},
  {"id":"s_work_nvlt_88_13","chapterId":"ch_work_nvlt_88","text":"又曰：南有乔木，不可休息。","sortOrder":13},
  {"id":"s_work_nvlt_88_14","chapterId":"ch_work_nvlt_88","text":"又曰：伐木丁丁，鳥鳴嘤嘤。","sortOrder":14},
  {"id":"s_work_nvlt_88_15","chapterId":"ch_work_nvlt_88","text":"《禮斗威儀》曰：君乘木而王者，其政升平，則草木丰盛。","sortOrder":15},
  {"id":"s_work_nvlt_88_16","chapterId":"ch_work_nvlt_88","text":"《春秋孔演圖》曰：麟，木精也。","sortOrder":16},
  {"id":"s_work_nvlt_88_17","chapterId":"ch_work_nvlt_88","text":"《六韜》曰：冬冰可折，夏條可結。","sortOrder":17},
  {"id":"s_work_nvlt_88_18","chapterId":"ch_work_nvlt_88","text":"《莊子》曰：南伯子綦遊於商之丘，見木焉，有異，結驷千乘，隱將庇其類，子綦曰：此何木也，然必異材，從而视其細枝，則拳曲而不可以為棟，俯而视其木根，不可以為棺椁，舐其葉則舌烂，嗅之則使人狂醒，子綦曰：此果不材之木，以至其大矣。","sortOrder":18},
  {"id":"s_work_nvlt_88_19","chapterId":"ch_work_nvlt_88","text":"《慎子》曰：廊廟之材，蓋非一木之枝也。","sortOrder":19},
  {"id":"s_work_nvlt_88_20","chapterId":"ch_work_nvlt_88","text":"《尸子》曰：木之精氣為必方。","sortOrder":20},
  {"id":"s_work_nvlt_88_21","chapterId":"ch_work_nvlt_88","text":"《孫卿子》曰：玉在山而木润。","sortOrder":21},
  {"id":"s_work_nvlt_88_22","chapterId":"ch_work_nvlt_88","text":"《玄中記》曰：百歲之树，其汁赤如血，千歲之树，精為青羊，萬歲之树，精為青牛。","sortOrder":22},
  {"id":"s_work_nvlt_88_23","chapterId":"ch_work_nvlt_88","text":"又曰：大树之山西，則有采華之树，服之則通萬國之言，《博物志》曰：員丘土有不死树，食之乃寿。","sortOrder":23},
  {"id":"s_work_nvlt_88_24","chapterId":"ch_work_nvlt_88","text":"《十洲記》曰：聚窟洲，海中申未地，上有大树，與楓木相似，而花葉香聞數百里，名為反魂树，於玉釜中煮取，汁如黑飴，名之為反生香，香氣聞數百里，死尸在地，聞氣仍活。","sortOrder":24},
  {"id":"s_work_nvlt_88_25","chapterId":"ch_work_nvlt_88","text":"《漢書》：晁错上書曰：夫胡貉之地，積陰之處也，木皮三寸，［地寒故也。］《淮南子》曰：凡幹木生鹿木根枝木者生於鹿木，凡見葉落而知歲暮，故葉落而長年悲，［長年人忌木黃，善時。］","sortOrder":25},
  {"id":"s_work_nvlt_88_26","chapterId":"ch_work_nvlt_88","text":"謝承《後漢書》曰：方储幼丧父，事母終日，負土成墳，种奇树千株。","sortOrder":26},
  {"id":"s_work_nvlt_88_27","chapterId":"ch_work_nvlt_88","text":"洪范，五行曰：三曰木。","sortOrder":27},
  {"id":"s_work_nvlt_88_28","chapterId":"ch_work_nvlt_88","text":"聲子曰：深根固蒂。","sortOrder":28},
  {"id":"s_work_nvlt_88_29","chapterId":"ch_work_nvlt_88","text":"《書》曰：木從繩則正。","sortOrder":29},
  {"id":"s_work_nvlt_88_30","chapterId":"ch_work_nvlt_88","text":"《詩》曰：出自幽穀，遷於乔木，荏苒柔木，君子树之。","sortOrder":30},
  {"id":"s_work_nvlt_88_31","chapterId":"ch_work_nvlt_88","text":"稽命錄［《太平御覽》九百五十二作徵。］曰：出號施令合民心，作樂製禮得天心，則草木有益於人者長，以養民，王者得禮之製，泽穀中生赤木。","sortOrder":31},
  {"id":"s_work_nvlt_88_32","chapterId":"ch_work_nvlt_88","text":"又，宗廟生木。","sortOrder":32},
  {"id":"s_work_nvlt_88_33","chapterId":"ch_work_nvlt_88","text":"又，夫子墳方一里，弟子各以四方奇木來植之。","sortOrder":33},
  {"id":"s_work_nvlt_88_34","chapterId":"ch_work_nvlt_88","text":"又，萬木細為杪。","sortOrder":34},
  {"id":"s_work_nvlt_88_35","chapterId":"ch_work_nvlt_88","text":"傳曰：慈母之恕其子折木，鳥能擇木。","sortOrder":35},
  {"id":"s_work_nvlt_88_36","chapterId":"ch_work_nvlt_88","text":"《陰符》曰：火生於木，禍發必剋。","sortOrder":36},
  {"id":"s_work_nvlt_88_37","chapterId":"ch_work_nvlt_88","text":"《國語》：伐木不自其本，必有後生，塞水不自其源，必有後流，除禍不自其本，必有後亂。","sortOrder":37},
  {"id":"s_work_nvlt_88_38","chapterId":"ch_work_nvlt_88","text":"人之有孝也，猶树之有枝葉，猶庇荫之，况君子乎。","sortOrder":38},
  {"id":"s_work_nvlt_88_39","chapterId":"ch_work_nvlt_88","text":"魏管辂過毌丘俭墓，［原訛武丘山险暮，據冯校本改。］林木雖茂，無形可久，碑诔惟美，無复可守，玄武藏頭，蒼龍無足，白虎衔尸，朱雀悲哭，四危以備，法當滅族。","sortOrder":39},
  {"id":"s_work_nvlt_88_40","chapterId":"ch_work_nvlt_88","text":"子路曰：二親之寿，怱若尘過隙，草木長，霜露不息，使賢者欲養二親，其道不行。","sortOrder":40},
  {"id":"s_work_nvlt_88_41","chapterId":"ch_work_nvlt_88","text":"《老子》曰：草木之生也柔脆，其死也枯槁。","sortOrder":41},
  {"id":"s_work_nvlt_88_42","chapterId":"ch_work_nvlt_88","text":"又曰：合抱之木，生於毫末。","sortOrder":42},
  {"id":"s_work_nvlt_88_43","chapterId":"ch_work_nvlt_88","text":"呂令［《太平御覽》九百五十二作呂氏春秋。］曰：夫蜦蝉者，精在乎明其火，振其树而已，火不明，雖振何益，明不獨在乎火，在闇，當今之世，闇則甚矣，人主有明其德者，天下之士其歸也，若蝉之走明火矣。","sortOrder":43},
  {"id":"s_work_nvlt_88_44","chapterId":"ch_work_nvlt_88","text":"又曰：木方盛，終日采之而复生，秋風下霜，一夕而零。","sortOrder":44},
  {"id":"s_work_nvlt_88_45","chapterId":"ch_work_nvlt_88","text":"欲鳥者先树木。","sortOrder":45},
  {"id":"s_work_nvlt_88_46","chapterId":"ch_work_nvlt_88","text":"人之有民，如木之有根，根深則本固。","sortOrder":46},
  {"id":"s_work_nvlt_88_47","chapterId":"ch_work_nvlt_88","text":"《文選》：树木者忧其蠹，根杇則葉危。","sortOrder":47},
  {"id":"s_work_nvlt_88_48","chapterId":"ch_work_nvlt_88","text":"《淮南子》曰：直木先伐，甘泉先竭。","sortOrder":48},
  {"id":"s_work_nvlt_88_49","chapterId":"ch_work_nvlt_88","text":"撗海有魚，抱大树能語，精名靈陽，午日稱仙人者，老树也，［本條太平御覽九百五十二作抱朴子。］","sortOrder":49},
  {"id":"s_work_nvlt_88_50","chapterId":"ch_work_nvlt_88","text":"《山海經》曰：少室山上有木，名帝休，黃花黑葉，服之不怒。","sortOrder":50},
  {"id":"s_work_nvlt_88_51","chapterId":"ch_work_nvlt_88","text":"仙序，王［《太平御覽》九百五十二王下有須字。］少年入學，家最遠，往來先，流辈怪之，常見如提一木三尺餘，至則柱屋間，流辈知取者，後不見。","sortOrder":51},
  {"id":"s_work_nvlt_88_52","chapterId":"ch_work_nvlt_88","text":"《禮》曰：入山行木，無有斬伐。","sortOrder":52},
  {"id":"s_work_nvlt_88_53","chapterId":"ch_work_nvlt_88","text":"《離骚》曰：一夫九首，拔木九千。","sortOrder":53},
  {"id":"s_work_nvlt_88_54","chapterId":"ch_work_nvlt_88","text":"裊裊兮秋風，洞庭波兮木脱，［《太平御覽》九百五十三作木葉下。］","sortOrder":54},
  {"id":"s_work_nvlt_88_55","chapterId":"ch_work_nvlt_88","text":"罾何為兮木上。","sortOrder":55},
  {"id":"s_work_nvlt_88_56","chapterId":"ch_work_nvlt_88","text":"搴芙蓉於木末。","sortOrder":56},
  {"id":"s_work_nvlt_88_57","chapterId":"ch_work_nvlt_88","text":"《論語》：朽木不可雕也。","sortOrder":57},
  {"id":"s_work_nvlt_88_58","chapterId":"ch_work_nvlt_88","text":"【詩】魏劉楨詩曰：昔君错畦畤，東土有素木，條柯不盈尋，一尺再三曲，隱生寘翳林，控偬自迫速，得讬芳蘭苑，列植高山足。","sortOrder":58},
  {"id":"s_work_nvlt_88_59","chapterId":"ch_work_nvlt_88","text":"周庾信詠树詩曰：交柯乍百傾，擢本或千尋，楓子留為式，桐孫待作琴，殘核移桃种，空花植棗林，幽居對蒙密，蹊迳轉深沉。","sortOrder":59},
  {"id":"s_work_nvlt_88_60","chapterId":"ch_work_nvlt_88","text":"陳李爽賦得芳树詩曰：芳树千株發，搖荡三陽時，氣软來風易，枝繁度鳥遲，春至花如錦，夏近葉成帷，欲寄邊城客，路遠詎能持。","sortOrder":60},
  {"id":"s_work_nvlt_88_61","chapterId":"ch_work_nvlt_88","text":"陳贺循賦得庭中有奇树詩曰：三春節物始芳菲，遊絲細草動春暉，香風飄舞花間度，好鳥和鳴枝上飛，臨池間竹偏增绿，依階映雪遠如玉，溫室庭前竟不言，鼓吹樓中能作曲，曾聞遠別舊難思，攀折會取赠佳期，長條本自堪為帶，密葉由來好作帷，星稀漢轉月輪明，徘徊夜鵲屢相驚，欲識幽人蘭杜迳，山窗芳桂复丛生。","sortOrder":61},
  {"id":"s_work_nvlt_88_62","chapterId":"ch_work_nvlt_88","text":"梁何遜詠雜花詩曰：井上發新花，誰言不經染，已如薄紫拂，复以浓紅點，状錦無裁縫，依霞有舒斂。","sortOrder":62},
  {"id":"s_work_nvlt_88_63","chapterId":"ch_work_nvlt_88","text":"梁萧子范落花詩曰：绿葉生半長，繁英早自香，因風亂胡蝶，未落隱鸝黃，飛來入斗帳，吹去上牙床，非是迎冬质，寧可值秋霜。","sortOrder":63},
  {"id":"s_work_nvlt_88_64","chapterId":"ch_work_nvlt_88","text":"梁劉孝威望隔牆花詩曰：隔牆花半隱，猶見動花枝，當由美人摘，詎止春風吹。","sortOrder":64},
  {"id":"s_work_nvlt_88_65","chapterId":"ch_work_nvlt_88","text":"周庾信詠園花詩曰：蹔往春園傍，聊過看果行，枝繁類金穀，花雜映河陽，自紅無暇染，真白不須妆，燕送歸菱井，蜂衔上蜜房，非是金爐氣，何關柏殿香，總衣偏定好，應持奉魏王。","sortOrder":65},
  {"id":"s_work_nvlt_88_66","chapterId":"ch_work_nvlt_88","text":"周明帝和王褒詠摘花詩曰：玉碗承花落，花落碗中芳，酒浮花不没，花含酒更香。","sortOrder":66},
  {"id":"s_work_nvlt_88_67","chapterId":"ch_work_nvlt_88","text":"陳張正見賦得岸花臨水發詩曰：奇树滿春洲，落蕊映紅浮，影間莲花石，光涵濯錦流，漾色隨桃水，飄香入桂舟，別有仙潭菊，含芳獨向秋。","sortOrder":67},
  {"id":"s_work_nvlt_88_68","chapterId":"ch_work_nvlt_88","text":"梁劉孝威詠翦采花詩曰：葉舒非漸大，花發是家开，無論人訝似，蜂見也爭來。","sortOrder":68},
  {"id":"s_work_nvlt_88_69","chapterId":"ch_work_nvlt_88","text":"梁朱超詠翦采花詩曰：淺深依树色，舒卷聽人裁，假令春已度，終住手中开。","sortOrder":69},
  {"id":"s_work_nvlt_88_70","chapterId":"ch_work_nvlt_88","text":"梁鮑泉詠翦采花詩曰：花生翦刀里，從來訝逼真，風動雖難落，蜂飛欲向人，不知今日後，誰能逆作春。","sortOrder":70},
  {"id":"s_work_nvlt_88_71","chapterId":"ch_work_nvlt_88","text":"梁豫章王萧綜悲落葉詩曰：悲落葉，聯翩下重叠，重叠落且飛，從橫去不歸，長枝交荫昔何密，黃鳥關關動相失，夕蕊雜凝露，朝花翻亂日，亂春日，起春風，春風春日此時同，一霜兩霜猶可當，五晨六旦飒已黃，乍逐驚風舉，高下任飄颺，悲落葉，落葉何時還，夙昔共根本，無复一相關，各隨灰土去，高枝難重攀。","sortOrder":71},
  {"id":"s_work_nvlt_88_72","chapterId":"ch_work_nvlt_88","text":"【賦】晉劉柔妻王氏春花賦曰：千葩粲其昭晰兮，百卉蒨而同榮，蘭圃翘以含芳兮，芝薄振而沉馨，翠穎競臻，眾條頻英，或異色同形，或齊芳殊製，自然神香，不可勝計，烂若羅宿之垂光，灼若隋珠之宵列，爽若翡翠之群翔，練若珊瑚之映月，詩人詠以讬諷，良喻美而光德，工女准於妙規，飾王後之首則。","sortOrder":72},
  {"id":"s_work_nvlt_88_73","chapterId":"ch_work_nvlt_88","text":"周庾信枯树賦曰：殷仲文風流儒雅，海內知名，世異時移，為東陽太守，常忽忽不樂，顧庭槐而叹曰：此树婆娑，生意盡矣，至白鹿貞松，青牛文梓，根祇盤魄，山崖表里，桂何事而銷亡，桐何為而半死，昔之三河徙植，九畹移根，开花建始之殿，落實睢陽之園，聲含嶰穀，曲抱雲門，將雏集鳳，比翼巢鴛，臨風亭而唳鶴，對月峡而吟猿，乃有拳曲擁肿，盤坳反覆，節树山連，文橫水蹙，匠石驚视，公输眩目，雕镌始就，剞劂仍加，重重碎錦，片片真花，若夫松子古度，平仲君遷，森梢百頃，槎枿千年，秦則大夫受職，漢則將軍坐焉，莫不苔埋菌壓，鳥剝虫穿，低垂於霜露，撼頓於風煙，東海有白木之廟，西河有枯桑之杜，北陆以楊葉為關，南陵以梅根作冶，小山則丛桂留人，扶風則長松［原訛杜，據冯校本改。］系馬，豈獨城臨細柳之上，塞落桃林之下，若乃山河阻絕，飄零離別，拔本垂淚，傷根流血，火入空心，膏流斷節，木魅〈目皋〉睒，山精妖孽，橫洞口而欹臥，頓山腰而半折，戴癭冲瘤，藏穿抱穴，况复風雲不感，羁旅無歸，既傷搖落，弥嗟变衰，淮南雲，木葉落，長年悲，斯之謂矣，乃為歌曰：建章二月火，黃河千里槎，若非金穀滿園树，即是河陽一縣花，桓大司馬聞而叹曰：昔年移柳，依依漢南，今看搖落，凄怆江潭，树猶如此，人何以堪。","sortOrder":73},
  {"id":"s_work_nvlt_88_74","chapterId":"ch_work_nvlt_88","text":"晉庾闡浮查賦曰：有幽巖之巨木，邈結根乎千仞，體洪佣以秀直，枕朅奇而特俊，冠岑嶺以高栖，獨雍容於嵒峻，混全朴於不才，倬凌霄而絕韻，故能紆餘盤骫，森萧頹靡，陽飄飆結，華裂水洒，遺美贾於翠璧，蹶懸根於朽壤，曳洪波於海湄，鼓長風而飄荡，旦馺波而乘飛潦，夕舉浪而赴奔潮，吹雲霧而出洞穴，灌炎石而過沃焦，江河不俄晷，萬里不一朝。","sortOrder":74},
  {"id":"s_work_nvlt_88_75","chapterId":"ch_work_nvlt_88","text":"【贊】晉郭璞甘水聖木贊曰：醴泉睿木，養齡盡性，增氣之和，祛神之冥，何必生知，然後為聖。","sortOrder":75},
  {"id":"s_work_nvlt_88_76","chapterId":"ch_work_nvlt_88","text":"又不死树贊曰：萬物暫見，人生如寄，不死之树，寿蔽天地，請藥西姥，焉得如羿。","sortOrder":76},
  {"id":"s_work_nvlt_88_77","chapterId":"ch_work_nvlt_88","text":"【啟】梁元帝為妾弘夜姝謝東宮赉合心花釵啟曰：未得投壶，先應含笑，不因鸞鳳，自能歌舞，夜姝昔往陽台，雖逢四照，曾遊澧浦，慣識九衢，未有仍代爵釵，還勝翠羽，飾以南金，裝茲麗玉，脩靡夫人，本分章華之里，中山孺子，獨荷春宮之恩，有志當熊，無期投閣。","sortOrder":77},
  {"id":"s_work_nvlt_88_79","chapterId":"ch_work_nvlt_88","text":"《毛詩》：徂來［山名。］之松。","sortOrder":79},
  {"id":"s_work_nvlt_88_80","chapterId":"ch_work_nvlt_88","text":"又曰：松桶［《太平御覽》九百五十三作桷。］有舄，路寢孔硕。","sortOrder":80},
  {"id":"s_work_nvlt_88_81","chapterId":"ch_work_nvlt_88","text":"又曰：陟彼景山，松柏丸丸，松柏有挺，旅楹有閒，寢成孔安。","sortOrder":81},
  {"id":"s_work_nvlt_88_82","chapterId":"ch_work_nvlt_88","text":"《禮記》曰：其在人也，如松柏之有心也，故貫四時不改柯易葉。","sortOrder":82},
  {"id":"s_work_nvlt_88_83","chapterId":"ch_work_nvlt_88","text":"《左傳》曰：晉侯使張骼附跞致楚師，求御於鄭，鄭人卜，宛射犬吉，子太叔戒之曰：大國之人，不可與也，對曰：世無有眾寡，其上一也，太叔曰：不然，培塿［塿，小阜也。］無松柏。","sortOrder":83},
  {"id":"s_work_nvlt_88_84","chapterId":"ch_work_nvlt_88","text":"又曰：楚夹敖即位，王子围為令尹，［康王弟也。］鄭行人子羽曰：是謂不宜，必代之昌，松柏之下，其草不殖，［言楚君弱，令尹強，物不兩盛也。］《論語》曰：歲寒然後知松柏之後凋也。","sortOrder":84},
  {"id":"s_work_nvlt_88_85","chapterId":"ch_work_nvlt_88","text":"又曰：夏後氏以松。","sortOrder":85},
  {"id":"s_work_nvlt_88_86","chapterId":"ch_work_nvlt_88","text":"《禮斗威儀》曰：君乘木而王，則松為常生也。","sortOrder":86},
  {"id":"s_work_nvlt_88_87","chapterId":"ch_work_nvlt_88","text":"《穆天子傳》曰：天子升長松之墱，［墱坂有長松也。］","sortOrder":87},
  {"id":"s_work_nvlt_88_88","chapterId":"ch_work_nvlt_88","text":"《尸子》曰：荆有長松文梓。","sortOrder":88},
  {"id":"s_work_nvlt_88_89","chapterId":"ch_work_nvlt_88","text":"《呂氏春秋》曰：故百仞之松，本傷於下，而末槁於上。","sortOrder":89},
  {"id":"s_work_nvlt_88_90","chapterId":"ch_work_nvlt_88","text":"《列仙傳》曰：仇生赤，當湯時，為木正，常食松脂，自作石室，周武王祠之。","sortOrder":90},
  {"id":"s_work_nvlt_88_91","chapterId":"ch_work_nvlt_88","text":"又曰：偓佺好食松實，能飛行逮走馬，以松子遺尧，尧不能服，松者，樠松也。","sortOrder":91},
  {"id":"s_work_nvlt_88_92","chapterId":"ch_work_nvlt_88","text":"《漢書》曰：贾山言治亂曰：秦東窮燕齊，南極吳楚，江湖之上，瀕海之觀畢至，道廣五十步，三丈而树，厚筑其外，隱以金椎，［作壁如甬道，隱，筑也，以鐵椎筑之。］树以青松，為馳道之麗，至於此也。","sortOrder":92},
  {"id":"s_work_nvlt_88_93","chapterId":"ch_work_nvlt_88","text":"焦贛《易林》曰：溫山松柏，鸞鳳以庇。","sortOrder":93},
  {"id":"s_work_nvlt_88_94","chapterId":"ch_work_nvlt_88","text":"《漢官儀》曰：秦始皇上封太山，逢疾風暴雨，賴得松树，因复其道，封為大夫松也。","sortOrder":94},
  {"id":"s_work_nvlt_88_95","chapterId":"ch_work_nvlt_88","text":"聖賢冢墓記曰：東平思王歸國，思京師，後薨，葬東平，其冢上松柏皆西靡。","sortOrder":95},
  {"id":"s_work_nvlt_88_96","chapterId":"ch_work_nvlt_88","text":"張勃《吳錄》曰：丁固夢松树生其腹上，人謂曰：松字十八公也，後十八年，其為公乎。","sortOrder":96},
  {"id":"s_work_nvlt_88_97","chapterId":"ch_work_nvlt_88","text":"《廣州先賢傳》曰：猗頓至孝，母丧，猗獨立墳，歷年乃成，居丧逾製，种松柏成行。","sortOrder":97},
  {"id":"s_work_nvlt_88_98","chapterId":"ch_work_nvlt_88","text":"《晉書》曰：山涛遭母丧，歸乡里，涛雖年老，居丧過禮，手植松柏。","sortOrder":98},
  {"id":"s_work_nvlt_88_99","chapterId":"ch_work_nvlt_88","text":"嵩高山記曰：嵩嶽有大树松，或百歲千歲，其精变為青牛，或為伏龟，采食其實，得長生。","sortOrder":99},
  {"id":"s_work_nvlt_88_100","chapterId":"ch_work_nvlt_88","text":"《抱朴子》曰：天陵偃蓋之松，太穀倒生之松，［本書柏篇及《太平御覽》九百五十三作柏。］王羲之遊四郡記曰：永寧縣界海中，有松門，西岸及屿上皆生松，故名松門。","sortOrder":100},
  {"id":"s_work_nvlt_88_101","chapterId":"ch_work_nvlt_88","text":"周景式庐山記曰：石門北巖，即松林也，南臨石門涧，涧中仰视之，離離如骈麈尾，號麈尾松。","sortOrder":101},
  {"id":"s_work_nvlt_88_102","chapterId":"ch_work_nvlt_88","text":"《玄中記》曰：松脂淪入地中，千歲為伏苓。","sortOrder":102},
  {"id":"s_work_nvlt_88_103","chapterId":"ch_work_nvlt_88","text":"神境記曰：滎［按當作營。］陽郡南有石室，室後有孤松千丈，常有双鶴，晨必接翮，夕辄偶影，傳曰：昔有夫婦二人，俱隱此室，年既數百，化成双鶴。","sortOrder":103},
  {"id":"s_work_nvlt_88_104","chapterId":"ch_work_nvlt_88","text":"夢書曰：松為人君，夢見松者，見人君也。","sortOrder":104},
  {"id":"s_work_nvlt_88_105","chapterId":"ch_work_nvlt_88","text":"《毛詩》曰：南有乔松，隰有遊龍。","sortOrder":105},
  {"id":"s_work_nvlt_88_106","chapterId":"ch_work_nvlt_88","text":"又，茑與女萝，施於松柏。","sortOrder":106},
  {"id":"s_work_nvlt_88_107","chapterId":"ch_work_nvlt_88","text":"又，桧楫松舟。","sortOrder":107},
  {"id":"s_work_nvlt_88_108","chapterId":"ch_work_nvlt_88","text":"《離骚》曰：山中人兮芳杜若，飲泉石兮荫松柏。","sortOrder":108},
  {"id":"s_work_nvlt_88_109","chapterId":"ch_work_nvlt_88","text":"又［明本作古詩。］曰：嘉树生朝陽，凝霜封其條，［嘉树，松柏也。］先聖本紀曰：許由欲觀帝意，曰：帝坐華堂，面双闕，君之榮，顧亦得矣，餘坐華堂，森然有松生於戶，雲生於牖，雖面双闕，異乎鸞之榮崑崙，餘安知其所以取榮哉，帝美由，師之。","sortOrder":109},
  {"id":"s_work_nvlt_88_110","chapterId":"ch_work_nvlt_88","text":"玉策雲，千載松柏树，枝葉上杪不長，望如偃蓋，其中有物，如青牛剃佗青人，服皆萬歲。","sortOrder":110},
  {"id":"s_work_nvlt_88_111","chapterId":"ch_work_nvlt_88","text":"謝混與從子靈運齊名，時人謂混風韻為高日望葵，萧如寒風振松，康樂凛凛如霜台籠日。","sortOrder":111},
  {"id":"s_work_nvlt_88_112","chapterId":"ch_work_nvlt_88","text":"孫興公前种一株松，枝高势遠，鄰居曰：松树非不楚楚可怜，但恐無棟梁用耳，楓柳雖合抱，亦何所施，［本條《太平御覽》九百五十三作世說。］","sortOrder":112},
  {"id":"s_work_nvlt_88_113","chapterId":"ch_work_nvlt_88","text":"張湛好於斋前种松柏，時人曰：張湛屋下陳尸，［本條《太平御覽》九百五十三作齊書。］符堅平鄴，糧竭，馬無草，削松木而食之。","sortOrder":113},
  {"id":"s_work_nvlt_88_114","chapterId":"ch_work_nvlt_88","text":"《魏志》：孫權自將軍至合肥新城，魏使滿寵赴之，募壮士數十，日折松為炬，從上風放火燒，賊退。","sortOrder":114},
  {"id":"s_work_nvlt_88_115","chapterId":"ch_work_nvlt_88","text":"《國語》曰：松柏之地，其土不肥。","sortOrder":115},
  {"id":"s_work_nvlt_88_116","chapterId":"ch_work_nvlt_88","text":"泰山記，岱宗小天門，有秦時五大夫松在。","sortOrder":116},
  {"id":"s_work_nvlt_88_117","chapterId":"ch_work_nvlt_88","text":"《史記》：松柏為百木長也，而守宮闕。","sortOrder":117},
  {"id":"s_work_nvlt_88_118","chapterId":"ch_work_nvlt_88","text":"《本草經》曰：松脂一名松肪，渴［《太平御覽》九百五十三作溫。］中，久服輕身延年。","sortOrder":118},
  {"id":"s_work_nvlt_88_119","chapterId":"ch_work_nvlt_88","text":"周太似夢周梓化為松，［本條《太平御覽》九百五十八作周書，似作姒。］《莊子》曰：天寒既至，霜雪既降，吾是知松柏之茂。","sortOrder":119},
  {"id":"s_work_nvlt_88_120","chapterId":"ch_work_nvlt_88","text":"漢武內傳，藥有松柏之膏，服之可延年。","sortOrder":120},
  {"id":"s_work_nvlt_88_121","chapterId":"ch_work_nvlt_88","text":"青［按青下當脱青字。］陵上松，亭亭南山柏，光寒冬夏茂，根蒂無凋落。","sortOrder":121},
  {"id":"s_work_nvlt_88_122","chapterId":"ch_work_nvlt_88","text":"尚書，岱畎絲枲鉛松怪石。","sortOrder":122},
  {"id":"s_work_nvlt_88_123","chapterId":"ch_work_nvlt_88","text":"【詩】魏劉公幹詩曰：亭亭山上松，瑟瑟穀中風，風聲一何盛，松枝一何劲，風霜正惨凄，終歲恒端正，豈不羅霜雪，松柏有本性。","sortOrder":123},
  {"id":"s_work_nvlt_88_124","chapterId":"ch_work_nvlt_88","text":"晉傅玄詩曰：飛蓬隨飄起，芳草摧山泽，世有千年松，人生詎能百。","sortOrder":124},
  {"id":"s_work_nvlt_88_125","chapterId":"ch_work_nvlt_88","text":"晉許詢詩曰：青松凝素髓，秋菊落芳英。","sortOrder":125},
  {"id":"s_work_nvlt_88_126","chapterId":"ch_work_nvlt_88","text":"晉袁宏詩曰：森森千丈松，磊砢非一節，雖無榱桷麗，较為梁棟桀。","sortOrder":126},
  {"id":"s_work_nvlt_88_127","chapterId":"ch_work_nvlt_88","text":"晉張華詩曰：松生垅坂上，百尺下無枝，東南望河尾，西北隱崑崖，網風振山籁，朋鳥夜驚離，悲涼貫年節，葱翠恒若斯，安得草木心，不怨寒暑移。","sortOrder":127},
  {"id":"s_work_nvlt_88_128","chapterId":"ch_work_nvlt_88","text":"晉王凝之妻謝氏擬嵇中散詩曰：遙望山上松，隆冬不能彫，原想遊下憩，瞻彼萬仞條，騰躍未能升，頓足俟王乔，時哉不我與，大運所飄飖。","sortOrder":128},
  {"id":"s_work_nvlt_88_129","chapterId":"ch_work_nvlt_88","text":"梁范雲詠寒松詩曰：脩條拂層漢，密葉帳天潯，凌風知劲節，負霜見直心。","sortOrder":129},
  {"id":"s_work_nvlt_88_130","chapterId":"ch_work_nvlt_88","text":"【賦】齊王俭和竟陵王高松賦曰：山有乔松，峻極青葱，既抽榮於岱嶽，亦擢穎於荆峰，若乃朔窮幹紀，歲亦暮止，隆冰峨峨，飛雪千里，嗟萬有之必衰，獨貞華之無已，積皓霰而爭光，延微飆而响起。","sortOrder":130},
  {"id":"s_work_nvlt_88_131","chapterId":"ch_work_nvlt_88","text":"齊謝朓高松賦曰：若夫脩幹垂荫，乔柯飛穎，望肅肅而既閒，即微微而方靜，懷風音而送聲，當月路而留影，乃阡眠於廣隰，亦迢遞於孤嶺，青春爰謝，靈物含明，江皋绿草，暧然已平，凌翠山而如翦，施懸萝而共輕，至於星回窮紀，沙雁相飛，同雲泱其無色，陽光沉而滅暉，豈雕貞於寒暮，不受令於霜威。","sortOrder":131},
  {"id":"s_work_nvlt_88_132","chapterId":"ch_work_nvlt_88","text":"梁沈約高松賦曰：鬱彼高松，栖根得地，讬北園於上邸，依平台而養翠，若夫蟠株耸幹之懿，含星漏月之奇，經千霜而得拱，仰百仞而方枝，朝吐輕煙薄霧，夜宿迷鳥羁雌，露雖滋而不润，風未動而先知，既梢雲於清漢，亦倒景於華池，輕陰蒙密，乔柯布護，葉斷禽蹤，枝通猿路，聽骚骚於既晓，望隱隱於將暮，暧平湖而漾青绿，拂增綺而籠丹素，於時風急垄首，寒浮塞天，流蓬不息，明月孤懸，檀栾之竹可詠，鄹枚之客存焉，清都之念方遠，姑射之想悠然，擢柔情於蕙圃，涌寶思於珠泉，豈徒為善之小樂，離繳之短篇，若此而已乎。","sortOrder":132},
  {"id":"s_work_nvlt_88_133","chapterId":"ch_work_nvlt_88","text":"【贊】宋謝惠連松贊曰：松惟靈木，擬心雲端，跡絕玉除，刑寄青峦，子欲我知，求之歲寒。","sortOrder":133},
  {"id":"s_work_nvlt_88_134","chapterId":"ch_work_nvlt_88","text":"戴逵松竹贊曰：猗屿松竹，獨蔚山皋，肅肅脩竿，森森長條。","sortOrder":134},
  {"id":"s_work_nvlt_88_136","chapterId":"ch_work_nvlt_88","text":"《山海經》曰：白於之山，其上多柏，土山多柏。","sortOrder":136},
  {"id":"s_work_nvlt_88_137","chapterId":"ch_work_nvlt_88","text":"又曰：三株树生赤水，其為树如柏，葉皆為珠。","sortOrder":137},
  {"id":"s_work_nvlt_88_138","chapterId":"ch_work_nvlt_88","text":"《尚書》曰：荆州貢杶幹栝柏。","sortOrder":138},
  {"id":"s_work_nvlt_88_139","chapterId":"ch_work_nvlt_88","text":"《毛詩》曰：新甫之柏，［新甫山名。］","sortOrder":139},
  {"id":"s_work_nvlt_88_140","chapterId":"ch_work_nvlt_88","text":"《漢武故事》曰：柏梁台高二十丈，悉以柏，香聞數十里，《列士傳》曰：延陵季子，解寶劍帶徐君墓柏树。","sortOrder":140},
  {"id":"s_work_nvlt_88_141","chapterId":"ch_work_nvlt_88","text":"《列仙傳》曰：赤松子好食柏實，齒落更生。","sortOrder":141},
  {"id":"s_work_nvlt_88_142","chapterId":"ch_work_nvlt_88","text":"《三辅黃圖》曰：漢文帝霸陵，不起山陵，稠种柏。","sortOrder":142},
  {"id":"s_work_nvlt_88_143","chapterId":"ch_work_nvlt_88","text":"《東觀漢記》曰：李恂，遭父母丧六年，躬自負土树柏，常住冢下。","sortOrder":143},
  {"id":"s_work_nvlt_88_144","chapterId":"ch_work_nvlt_88","text":"謝承後《漢書》：陳留虞延，為郡督郵，光武巡狩，至外黃，問延園陵柏树株數，延悉晓之，由是見知。","sortOrder":144},
  {"id":"s_work_nvlt_88_145","chapterId":"ch_work_nvlt_88","text":"王隱《晉書》：王褒痛父不以命終，絕世不仕，立屋墓侧，旦夕常至墓前朝拜，辄悲號斷絕，墓前一柏树，襃常所攀，涕泣所著，树色與凡树不同。","sortOrder":145},
  {"id":"s_work_nvlt_88_146","chapterId":"ch_work_nvlt_88","text":"《晉宮閣名》曰：華林園柏二株。","sortOrder":146},
  {"id":"s_work_nvlt_88_147","chapterId":"ch_work_nvlt_88","text":"《泰山記》曰：山南有太山廟，种柏树千株，大者十五六围，長老傳雲，漢武所种。","sortOrder":147},
  {"id":"s_work_nvlt_88_148","chapterId":"ch_work_nvlt_88","text":"《從征記》曰：泰山廟中柏，皆二十餘围，俠兩階，赤眉嘗斫一树，見血而止，今斧瘡猶在。","sortOrder":148},
  {"id":"s_work_nvlt_88_149","chapterId":"ch_work_nvlt_88","text":"《陳留耆舊傳》曰：李充丧父，父冢侧有夜盜斫充柏树者，充手刃之。","sortOrder":149},
  {"id":"s_work_nvlt_88_150","chapterId":"ch_work_nvlt_88","text":"《述征記》曰：柏穀，穀名也，漢武帝微行所至，長泬賓於柏穀者也，穀中無回車地，夹以高原，柏林荫藹，窮日幽暗，殆弗睹陽景。","sortOrder":150},
  {"id":"s_work_nvlt_88_151","chapterId":"ch_work_nvlt_88","text":"《毛詩》：邶柏舟，衛頃公之詩也。","sortOrder":151},
  {"id":"s_work_nvlt_88_152","chapterId":"ch_work_nvlt_88","text":"又，鄘柏舟，共薑自誓也。","sortOrder":152},
  {"id":"s_work_nvlt_88_153","chapterId":"ch_work_nvlt_88","text":"《文選》：青青陵上柏。","sortOrder":153},
  {"id":"s_work_nvlt_88_154","chapterId":"ch_work_nvlt_88","text":"松柏轉萧瑟，瞻彼陵上柏。","sortOrder":154},
  {"id":"s_work_nvlt_88_155","chapterId":"ch_work_nvlt_88","text":"麝食柏而香。","sortOrder":155},
  {"id":"s_work_nvlt_88_156","chapterId":"ch_work_nvlt_88","text":"漢，［《太平御覽》九百五十四作漢書。］朱博為御史大夫，府中列柏，有野乌數千栖其上。","sortOrder":156},
  {"id":"s_work_nvlt_88_157","chapterId":"ch_work_nvlt_88","text":"窦武上表曰：今茲大寒，過節城旁，以柏為傷絕。","sortOrder":157},
  {"id":"s_work_nvlt_88_158","chapterId":"ch_work_nvlt_88","text":"後漢方储，字聖明，遭母忧，負土成墳，松柏數十株，鸞乌栖其上，白兔遊其下。","sortOrder":158},
  {"id":"s_work_nvlt_88_159","chapterId":"ch_work_nvlt_88","text":"《晉書》曰：庾蹇，字升襃，或有斬其父墓柏者，莫知其誰，乃召鄰人，於墓自责，叩頭涕泣，謝祖祢，自後人莫之犯。","sortOrder":159},
  {"id":"s_work_nvlt_88_160","chapterId":"ch_work_nvlt_88","text":"郭璞以王丞相為卦，雲有震厄，公命駕西步數里，得一柏树，截如公長，置常寢臥處，果震柏粉碎。","sortOrder":160},
  {"id":"s_work_nvlt_88_161","chapterId":"ch_work_nvlt_88","text":"宋書，魯郡孔子舊廟，有柏树二十四株，歷漢晉，其大連抱，土人崇敬之，莫犯也。","sortOrder":161},
  {"id":"s_work_nvlt_88_162","chapterId":"ch_work_nvlt_88","text":"孫卿子，柏經冬而不凋，蒙霜不变，可謂得其真也。","sortOrder":162},
  {"id":"s_work_nvlt_88_163","chapterId":"ch_work_nvlt_88","text":"《抱朴子》曰：大國［前松篇引作穀，此訛。］倒生之柏，皆為天齊其長，地等其久。","sortOrder":163},
  {"id":"s_work_nvlt_88_164","chapterId":"ch_work_nvlt_88","text":"《三辅舊事》曰：漢諸陵皆屬太常，有人盜者弃市。","sortOrder":164},
  {"id":"s_work_nvlt_88_165","chapterId":"ch_work_nvlt_88","text":"《文選》曰：寒露拂陵苕，女萝辭松柏。","sortOrder":165},
  {"id":"s_work_nvlt_88_166","chapterId":"ch_work_nvlt_88","text":"松柏隆冬瘁，然後知歲寒。","sortOrder":166},
  {"id":"s_work_nvlt_88_167","chapterId":"ch_work_nvlt_88","text":"廣雅，一名汁柏。","sortOrder":167},
  {"id":"s_work_nvlt_88_168","chapterId":"ch_work_nvlt_88","text":"《國語》：高山峻原，不生草木，松柏之地，其土不肥。","sortOrder":168},
  {"id":"s_work_nvlt_88_169","chapterId":"ch_work_nvlt_88","text":"《齊書》曰：王俭，字仲寶，司徒袁粲叹曰：宰相之門也，栝柏豫章，雖小，已有棟梁之器。","sortOrder":169},
  {"id":"s_work_nvlt_88_170","chapterId":"ch_work_nvlt_88","text":"《列仙傳》：須子食柏實，齒落更生。","sortOrder":170},
  {"id":"s_work_nvlt_88_171","chapterId":"ch_work_nvlt_88","text":"柏台，御史台也。","sortOrder":171},
  {"id":"s_work_nvlt_88_172","chapterId":"ch_work_nvlt_88","text":"《禮》：如松柏之有心。","sortOrder":172},
  {"id":"s_work_nvlt_88_173","chapterId":"ch_work_nvlt_88","text":"【歌】古歌曰：平陵東，松柏桐，不知何人劫義公。","sortOrder":173},
  {"id":"s_work_nvlt_88_174","chapterId":"ch_work_nvlt_88","text":"古艳歌曰：南山石嵬嵬，松柏何離離，上枝拂青雲，中心十數围，洛陽發中梁，松树竊自悲，斧鋸截是松，松树東西摧，持作四輪車，載至洛陽宮，觀者莫不叹，問是何山材，誰能刻鏤此，公输與魯班，被之用丹漆，薰用蘇合香，本自南山松，今為宮殿梁。","sortOrder":174},
  {"id":"s_work_nvlt_88_175","chapterId":"ch_work_nvlt_88","text":"又歌曰：行行隨道，經歷山陂，馬啖柏葉，人啖柏脂，不可常飽，聊可遏飢。","sortOrder":175},
  {"id":"s_work_nvlt_88_176","chapterId":"ch_work_nvlt_88","text":"【賦】晉左九嫔松柏賦曰：何奇树之英蔚，讬峻嶽之嵯峨，被玄涧之逶迤，帶绿水之素波，布秀葉之葱蒨，列疏實之離離，馥幽藹而永馨，紛翕習以披離，赤松遊其下而得道，文賓餐其實而長生，詩人歌其榮蔚，齊南山以永寧。","sortOrder":176},
  {"id":"s_work_nvlt_88_178","chapterId":"ch_work_nvlt_88","text":"春秋說曰：槐木者，虛星之精。","sortOrder":178},
  {"id":"s_work_nvlt_88_179","chapterId":"ch_work_nvlt_88","text":"《爾雅》曰：守宮槐葉，晝聂宵炕。","sortOrder":179},
  {"id":"s_work_nvlt_88_180","chapterId":"ch_work_nvlt_88","text":"周官，面三槐，三公位焉，［槐之言懷也。］","sortOrder":180},
  {"id":"s_work_nvlt_88_181","chapterId":"ch_work_nvlt_88","text":"《春秋元命包》曰：树槐，聽訟其下。","sortOrder":181},
  {"id":"s_work_nvlt_88_182","chapterId":"ch_work_nvlt_88","text":"《左傳》曰：趙宣子骤諫，公患之，使鉏麑賊之，晨往，寢門辟矣，盛服將朝，尚早，坐而假寐，麑退而叹曰：不忘恭敬，民之主也，賊民之主不忠，弃君之命不信，有一於此，不如死也，觸槐而死。","sortOrder":182},
  {"id":"s_work_nvlt_88_183","chapterId":"ch_work_nvlt_88","text":"太公《金匮》曰：武王問太公曰：天下神來甚眾，恐有试者，何以待之，太公曰：請树槐於王門內，有益者入，無益者距之。","sortOrder":183},
  {"id":"s_work_nvlt_88_184","chapterId":"ch_work_nvlt_88","text":"《晏子春秋》曰：齊景公有所愛槐，使人守之，令曰：犯槐者刑，傷槐者死，有醉而傷槐者，且加刑焉。","sortOrder":184},
  {"id":"s_work_nvlt_88_185","chapterId":"ch_work_nvlt_88","text":"《莊子》曰：槐之生也，入季春五日而兔目，十日而鼠耳。","sortOrder":185},
  {"id":"s_work_nvlt_88_186","chapterId":"ch_work_nvlt_88","text":"《三辅黃圖》曰：元始四年，起明堂辟雍，為博士舍三十區，為會市，但列槐树數百行，諸生朔望會此市，各持其郡所出物及經書，相與買賣，雍雍揖讓，論議树下，侃侃訚訚。","sortOrder":186},
  {"id":"s_work_nvlt_88_187","chapterId":"ch_work_nvlt_88","text":"槐大葉而黑，江東有树，與此相返，名合昏槐，［本條《太平御覽》九百五十四作郭璞爾雅註，返作反。］","sortOrder":187},
  {"id":"s_work_nvlt_88_188","chapterId":"ch_work_nvlt_88","text":"管子，立沃土，［《太平御覽》九百五十四作五沃之土。］其木宜槐。","sortOrder":188},
  {"id":"s_work_nvlt_88_189","chapterId":"ch_work_nvlt_88","text":"沈約宋書，孔子夜夢三槐之間，丰沛之祁，［《太平御覽》九百五十四作邦。］有赤煙氣，驅車對楚西北觀之，見刍兒敵鹿，［御覽作麟。］傷其左足，薪而覆之。","sortOrder":189},
  {"id":"s_work_nvlt_88_190","chapterId":"ch_work_nvlt_88","text":"秦符堅時，關隴人歌曰：長安大街，兩邊树槐，下走朱輪，上有鸞栖，［本條《太平御覽》九百五十四作晉書。］","sortOrder":190},
  {"id":"s_work_nvlt_88_191","chapterId":"ch_work_nvlt_88","text":"《淮南子》曰：老槐生久，［《太平御覽》九百五十四作火。］血為燐。","sortOrder":191},
  {"id":"s_work_nvlt_88_192","chapterId":"ch_work_nvlt_88","text":"槐市學也，以［《太平御覽》九百五十四以上有树字。］青槐。","sortOrder":192},
  {"id":"s_work_nvlt_88_193","chapterId":"ch_work_nvlt_88","text":"燧人秋取槐檀之火。","sortOrder":193},
  {"id":"s_work_nvlt_88_194","chapterId":"ch_work_nvlt_88","text":"天所覆，地所載，六合所包，陰陽所煦，雨露所扶，此皆於父母所關［御覽作闕。］於一利［御覽作和。］也，父天母地，故槐榆與橘柚合五兒［二字御覽作而，五字疑衍。］為兄弟，有苗與三危通而一家。","sortOrder":194},
  {"id":"s_work_nvlt_88_195","chapterId":"ch_work_nvlt_88","text":"老槐生火人不怪。","sortOrder":195},
  {"id":"s_work_nvlt_88_196","chapterId":"ch_work_nvlt_88","text":"隋高穎，字昭玄，一名敏，領新都大監，每坐槐棠树下以聽事，至不依行列，有司伐之，上特令勿去，以示後人，［本條《太平御覽》九百五十四作隋書，下祖士雄條同。］","sortOrder":196},
  {"id":"s_work_nvlt_88_197","chapterId":"ch_work_nvlt_88","text":"祖士雄庐侧，其庭前有槐树，先榮茂，及雄居丧，亦枯死，服阕還茂，高祖嘉之，名其里為累德里。","sortOrder":197},
  {"id":"s_work_nvlt_88_198","chapterId":"ch_work_nvlt_88","text":"晉大司馬府，有老槐树，殷仲堪對而叹曰：此树婆娑，生意盡矣，［本條《太平御覽》九百五十四作晉書。］","sortOrder":198},
  {"id":"s_work_nvlt_88_199","chapterId":"ch_work_nvlt_88","text":"魏陳王曹植魏德論曰：武帝執政日，白雀集於庭槐。","sortOrder":199},
  {"id":"s_work_nvlt_88_200","chapterId":"ch_work_nvlt_88","text":"魏都賦曰：槐以荫途。","sortOrder":200},
  {"id":"s_work_nvlt_88_201","chapterId":"ch_work_nvlt_88","text":"晉挚虞連理頌曰：東宮正德之內，承華之外，槐树二枝，連理而生，二幹一心，以蕃本根。","sortOrder":201},
  {"id":"s_work_nvlt_88_202","chapterId":"ch_work_nvlt_88","text":"庾信枯槐賦，开花建始之殿，結實睢陽之園。","sortOrder":202},
  {"id":"s_work_nvlt_88_203","chapterId":"ch_work_nvlt_88","text":"【賦】晉傅選槐賦曰：華葉扶疏，參林萧蔱，松萝寄生，綿連摽末，延袤千畝，蓊鬱晻藹。","sortOrder":203},
  {"id":"s_work_nvlt_88_204","chapterId":"ch_work_nvlt_88","text":"魏文帝槐賦曰：文昌殿中槐树，盛暑之時，餘數遊其下，美而賦之，王粲直登賢門小閣外，亦有槐树，乃就使賦焉，有大邦之美树，惟令质之可佳，讬靈根於丰壤，被日月之光華，周長廊而开趾，夹通門而骈羅，承文昌之邃宇，望迎風之曲阿，脩幹紛其漼错，绿葉萋而重陰，上幽藹而雲覆，下茎立而擢心，伊暮春之既替，即首夏之初期，鸿雁遊而送節，凯風翔而迎時，天清和而溫润，氣恬淡以安治，违隆暑而適體，誰謂此之不怡。","sortOrder":204},
  {"id":"s_work_nvlt_88_205","chapterId":"ch_work_nvlt_88","text":"魏陳王曹植賦曰：治冯［《初學記》二十八作凭，上治字衍。］文昌之華殿，森列峙乎端門，觀朱榱以振條，據文陛而結根，楊沉陰以博覆，似明後之垂恩，在季春以初茂，踐朱夏而乃繁，覆陽精之炎景，散流耀以增鮮。","sortOrder":205},
  {"id":"s_work_nvlt_88_206","chapterId":"ch_work_nvlt_88","text":"魏王粲槐树賦曰：惟中唐之奇树，禀天然之淑姿，超畴畝而登殖，作階庭之華暉，形禕禕以畅條，色采采而鮮明，丰茂葉之幽藹，履中夏而敷榮，既立本於殿省，植根柢其弘深，鳥取栖而投翼，人望庇而披衿。","sortOrder":206},
  {"id":"s_work_nvlt_88_207","chapterId":"ch_work_nvlt_88","text":"晉挚虞槐賦曰：覽坤元之產殖，莫茲槐之為貴，爰表庭而树門，膺論道而正位，爾乃觀其誕状，察其攸居，丰融湛｛雨對｝，蓊鬱扶疏，上拂華宇，下臨脩渠，凑以夷迳，帶以通衢，鼓柯命風，振葉致涼，开明過於八闼兮，重陰逾乎九房。","sortOrder":207},
  {"id":"s_work_nvlt_88_208","chapterId":"ch_work_nvlt_88","text":"晉庾儵大槐賦曰：餘去許都，將歸洛京，舍於嵩嶽之下，而植斯树焉，遂作大槐之賦曰：有殊世之奇树，生中嶽之重阿，承蒼昊之純氣，吸後土之柔嘉，若夫赤松王乔冯夷之倫，逍遙茂荫，濯纓其濱，望輕霞而增舉，垂高畅之清尘，若其含真抱朴，曠世所希，降夏後之卑室，作唐虞之茅茨，絜昭俭以驕奢，成三王之懿資，故能著英聲於來世，超群侣而垂暉，仰瞻重幹，俯察其陰，逸葉橫被，流枝萧森，下覆靈沼，上蔽高岑，孫鵠徘徊，寡雀悲吟，清風時至，惻怆傷心，將騁軌以輕邁，安久留而涕淫。","sortOrder":208},
  {"id":"s_work_nvlt_88_210","chapterId":"ch_work_nvlt_88","text":"《爾雅》曰：女桑桋桑，［桋音荑，長條者為女桑，檿桑山桑。］","sortOrder":210},
  {"id":"s_work_nvlt_88_211","chapterId":"ch_work_nvlt_88","text":"《山海經》曰：宣山上有桑，大五十尺，其枝四衢，［支交四出。］葉大尺，赤理青華，名之曰帝女之桑。","sortOrder":211},
  {"id":"s_work_nvlt_88_212","chapterId":"ch_work_nvlt_88","text":"又曰：陽穀上有扶桑，十日所浴。","sortOrder":212},
  {"id":"s_work_nvlt_88_213","chapterId":"ch_work_nvlt_88","text":"《毛詩》曰：蠶月條桑，［條桑，被落枝，采其葉。］","sortOrder":213},
  {"id":"s_work_nvlt_88_214","chapterId":"ch_work_nvlt_88","text":"又曰：猗彼女桑，［少枝長條不落，束而采之。］","sortOrder":214},
  {"id":"s_work_nvlt_88_215","chapterId":"ch_work_nvlt_88","text":"又曰：肅肅鴇行，集於包桑。","sortOrder":215},
  {"id":"s_work_nvlt_88_216","chapterId":"ch_work_nvlt_88","text":"《禮記儀》註曰：後妃斋戒，將夫人世婦出采桑。","sortOrder":216},
  {"id":"s_work_nvlt_88_217","chapterId":"ch_work_nvlt_88","text":"《左傳》曰：晉公子重耳出奔，及齊，齊桓公妻之，將行，舅犯等謀於桑下，蠶妾在上聞之，以告薑氏，薑氏殺之，［薑氏，重耳妻也。］謂公子曰：子有四方之志，其聞之者，吾殺之矣。","sortOrder":217},
  {"id":"s_work_nvlt_88_218","chapterId":"ch_work_nvlt_88","text":"又曰：趙宣子田於首山，舍於翳桑，見靈辄饿，曰：不食三日矣，為之箪食與肉，寘諸櫜以與之，既而與為公介，［介，田(《太平御覽》九百五十五作甲。)士也。］倒戟以御公徒而免之，問何故，曰：翳桑之饿人也。","sortOrder":218},
  {"id":"s_work_nvlt_88_219","chapterId":"ch_work_nvlt_88","text":"《春秋孔演圖》曰：孔子母徵在，遊大冢之陂，睡，夢黑帝使請與已交，語曰：女乳必於空桑之中，覺則若感，生丘於空桑之中，［乳，生也。］穆天子傳曰：甲寅，天子作居范宮，［離宮別名。］以觀桑者，乃飲於桑中，桑林之中，天子命桑虞出桑者，用禁暴民，［虞，主桑者也，不得令民暴犯桑。］","sortOrder":219},
  {"id":"s_work_nvlt_88_220","chapterId":"ch_work_nvlt_88","text":"《列子》曰：晉文公會欲伐衛，公子鉏仰而笑，公問何笑，曰：臣之鄰人，有送其妻適私家者，道見桑婦，悅而與言，然顧视其妻，亦有招之者矣，臣竊笑此，公悟其言，乃止，引師還，未至而有伐其北鄙者。","sortOrder":220},
  {"id":"s_work_nvlt_88_221","chapterId":"ch_work_nvlt_88","text":"《離骚》［《太平御覽》九百五十五作楚辭。］曰：路室女之方桑，［路室，客舍也。］孔子遇之以自待，［以其貞信自待。］","sortOrder":221},
  {"id":"s_work_nvlt_88_222","chapterId":"ch_work_nvlt_88","text":"《呂氏春秋》曰：伊尹之母，居伊水之上，孕。夢有神告之曰：臼出水而東走，無顧。明日视臼出水，告其鄰，東走，顧其邑盡為水，身因化為桑，有侁氏采桑，得婴兒空桑之中，獻之於君，君令乳之，命曰伊尹。","sortOrder":222},
  {"id":"s_work_nvlt_88_223","chapterId":"ch_work_nvlt_88","text":"《史記》曰：吳公子光伐楚，拔居巢鍾離，初楚邊邑卑氏之處女，與吳邊邑之女爭桑，二女家相怒，喧兩國邊邑，邊邑長聞之怒，而攻滅吳之邊邑，吳王怒，故遂伐楚兩都。","sortOrder":223},
  {"id":"s_work_nvlt_88_224","chapterId":"ch_work_nvlt_88","text":"又，货殖傳曰：齊魯千畝桑，其人與千戶侯等。","sortOrder":224},
  {"id":"s_work_nvlt_88_225","chapterId":"ch_work_nvlt_88","text":"《典術》曰：桑木者，箕星之精神，木虫食葉為文章，人食之，老翁為小童。","sortOrder":225},
  {"id":"s_work_nvlt_88_226","chapterId":"ch_work_nvlt_88","text":"《列女傳》：齊宿瘤女者，初闵王遊東郭，百姓盡觀，宿瘤女采桑如故。王怪，召問之，對曰：妾受父母教采桑，不受教觀大王，王曰：此奇女也，娉迎之。","sortOrder":226},
  {"id":"s_work_nvlt_88_227","chapterId":"ch_work_nvlt_88","text":"又曰：陳辨女者，陳國采桑之女也，晉大夫解君甫使於宋，道過陳，過采桑之女，止而戲之曰：女為我歌，吾將舍女，女乃歌曰：墓門有棘，斧以斫之，夫也不良，國人知之。","sortOrder":227},
  {"id":"s_work_nvlt_88_228","chapterId":"ch_work_nvlt_88","text":"《東觀漢記》曰：蔡君仲，汝南人，至孝，王莽亂，人相食，君仲取桑椹，赤黑異器，賊問所以，雲黑與母，赤自食，賊義之，遺鹽二斗。","sortOrder":228},
  {"id":"s_work_nvlt_88_229","chapterId":"ch_work_nvlt_88","text":"謝承《後漢書》曰：張堪為漁陽太守，勸民耕种，百姓歌曰：桑無附枝，麥穗兩歧，張君為政，樂不可支。","sortOrder":229},
  {"id":"s_work_nvlt_88_230","chapterId":"ch_work_nvlt_88","text":"《蜀志》曰：先主舍東南角篱上，有桑树生，高五丈餘，遙望憧憧，如小車蓋。往來者皆怪此树非凡，或謂當出貴人。先主少時，與宗中諸兒，於树下戲，言吾必當乘此羽葆車蓋。","sortOrder":230},
  {"id":"s_work_nvlt_88_231","chapterId":"ch_work_nvlt_88","text":"《益部耆舊傳》曰：何祗，夢桑生井中，趙直占曰：桑非井中之物，桑字四十八，君寿恐不過此，祗年四十八而卒。","sortOrder":231},
  {"id":"s_work_nvlt_88_232","chapterId":"ch_work_nvlt_88","text":"《搜神記》曰：舊說有人遠征，家有一女，馬一疋。女思父，乃戲馬曰：爾能為我迎得父，吾將嫁汝。馬乃頓韁而去，迎得父來。後馬見女辄怒，父問之，女具以告。父乃殺馬，曝皮於庭。女之皮所曰：爾馬也，而欲人為婦，自取屠剝何如。言未竟，蹶然忽起，卷女而行。父失女後，於大桑树枝間，得女及皮，盡化為蠶。績树上，其茧厚大異常。鄰婦取養之，其收亦倍。今世謂蠶為女兒，古之遺語也。","sortOrder":232},
  {"id":"s_work_nvlt_88_233","chapterId":"ch_work_nvlt_88","text":"《易》曰：系於苞桑。","sortOrder":233},
  {"id":"s_work_nvlt_88_234","chapterId":"ch_work_nvlt_88","text":"《尚書·禹貢》曰：厥貢檿絲，《毛詩》曰：桑之落矣，其黃而陨。","sortOrder":234},
  {"id":"s_work_nvlt_88_235","chapterId":"ch_work_nvlt_88","text":"又曰：無折我桑。","sortOrder":235},
  {"id":"s_work_nvlt_88_236","chapterId":"ch_work_nvlt_88","text":"《禮記》：古者天子諸侯，必有公桑蠶室，近川而為之，《春秋元命苞》曰：薑嫄遊閟宮，其地扶桑，履大人跡，生稷。","sortOrder":236},
  {"id":"s_work_nvlt_88_237","chapterId":"ch_work_nvlt_88","text":"陳留申屠蟠，恥郡無義士，遂閉門養志，蓬戶萊室，依大桑树，以為棟梁，［本條《太平御覽》九百五十五作謝承後漢書。］","sortOrder":237},
  {"id":"s_work_nvlt_88_238","chapterId":"ch_work_nvlt_88","text":"又曰：汝南尹崑，為汝陰縣功曹，令新到官，問曰：園中有桑，以食蠶，何如，崑曰：非初至所務。","sortOrder":238},
  {"id":"s_work_nvlt_88_239","chapterId":"ch_work_nvlt_88","text":"崔晃［《太平御覽》九百五十五作鸿。］三十國春秋，後燕錄曰：初晃之遷於龍城，植松為社主，及秦滅燕，大風吹拔，後數年，度社處，忽有桑二根生焉，先是遼川無桑，及廆通於晉，求种江南，平州之桑，息［御覽作悉。］由晃來。","sortOrder":239},
  {"id":"s_work_nvlt_88_240","chapterId":"ch_work_nvlt_88","text":"《晉令》曰：丞尉以官舍有桑果，皆給之，其無桑及不滿三百株，皆使吏卒隨間，於官舍种桑，滿三百株。","sortOrder":240},
  {"id":"s_work_nvlt_88_241","chapterId":"ch_work_nvlt_88","text":"《山海經》曰：東北海外，赤水在圓丘南，有三桑，無枝，皆高百仞。","sortOrder":241},
  {"id":"s_work_nvlt_88_242","chapterId":"ch_work_nvlt_88","text":"《神異經》曰：東方有树焉，高八十丈，敷張自辅，葉長一丈，廣六尺，名曰扶桑，有椹焉，長三尺五寸。","sortOrder":242},
  {"id":"s_work_nvlt_88_243","chapterId":"ch_work_nvlt_88","text":"《述異記》曰：桓仲［《太平御覽》九百五十五作冲。］為江州刺史，遣人周行庐山，冀睹靈異，既陟崇巘，有一湖，生桑树，有败艑赤鱗魚，使者渴極，欲往飲水，赤鱗張鰭向之，使者不敢飲。","sortOrder":243},
  {"id":"s_work_nvlt_88_244","chapterId":"ch_work_nvlt_88","text":"列女傳，秋胡子納妻五日而婦采桑，［此有脱文。］自投河死，［事具金部。］","sortOrder":244},
  {"id":"s_work_nvlt_88_245","chapterId":"ch_work_nvlt_88","text":"《十洲記》曰：扶桑在碧海中，上有天帝宮，東王所治，有椹树，長數千丈，二千围，同根更相依倚，故曰扶桑，仙人食根，［《太平御覽》九百五十五作椹。］體作紫色，其树雖大，椹如中夏桑也，九千歲一生實，味甘香。","sortOrder":245},
  {"id":"s_work_nvlt_88_246","chapterId":"ch_work_nvlt_88","text":"括地圖曰：化民食桑，二十七年，化而身里，九年生翼，十年而死。","sortOrder":246},
  {"id":"s_work_nvlt_88_247","chapterId":"ch_work_nvlt_88","text":"《孟子》曰：五畝之宅，树之以桑。","sortOrder":247},
  {"id":"s_work_nvlt_88_248","chapterId":"ch_work_nvlt_88","text":"《禮》曰：鳴鳩拂羽，戴勝降桑。","sortOrder":248},
  {"id":"s_work_nvlt_88_249","chapterId":"ch_work_nvlt_88","text":"《氾勝之書》曰：五种桑，因取椹著水中濯洗，取子陰乾之，治肥田十畝荒久不耕者，先好耕治之，黍椹子各三升，合种之，黍桑俱生，鉏之，桑令疏條適，黍熟獲之，放火燒之，當逆風起火，桑至春生，一畝食三簿蠶。","sortOrder":249},
  {"id":"s_work_nvlt_88_250","chapterId":"ch_work_nvlt_88","text":"《本草經》曰：桑根旁行出土上者，名伏蛇，治心痛。","sortOrder":250},
  {"id":"s_work_nvlt_88_251","chapterId":"ch_work_nvlt_88","text":"伊陟相太戊，亳有祥桑穀，共生於朝，［本條《太平御覽》九百五十五引作書曰。］","sortOrder":251},
  {"id":"s_work_nvlt_88_252","chapterId":"ch_work_nvlt_88","text":"《詩》曰：桑之未落，其葉沃若，春日載陽，爰求柔桑。","sortOrder":252},
  {"id":"s_work_nvlt_88_253","chapterId":"ch_work_nvlt_88","text":"交交黃鳥，止於桑。","sortOrder":253},
  {"id":"s_work_nvlt_88_254","chapterId":"ch_work_nvlt_88","text":"星言夙駕，稅於桑田。","sortOrder":254},
  {"id":"s_work_nvlt_88_255","chapterId":"ch_work_nvlt_88","text":"烝在桑野，禮曰：季春之月，命野虞，無伐桑柘。","sortOrder":255},
  {"id":"s_work_nvlt_88_256","chapterId":"ch_work_nvlt_88","text":"桑弧蓬矢。","sortOrder":256},
  {"id":"s_work_nvlt_88_257","chapterId":"ch_work_nvlt_88","text":"衡山多桑。","sortOrder":257},
  {"id":"s_work_nvlt_88_258","chapterId":"ch_work_nvlt_88","text":"山海經，定山帝女之桑，湯穀有扶桑，十日所沐浴。","sortOrder":258},
  {"id":"s_work_nvlt_88_259","chapterId":"ch_work_nvlt_88","text":"《穆天子傳》曰：居范宮，以觀桑。","sortOrder":259},
  {"id":"s_work_nvlt_88_260","chapterId":"ch_work_nvlt_88","text":"贾後废愍懷太子，時桑生於西厢，長數日枯，十二月，後生太子，［本條《太平御覽》九百五十五作《晉書》：後生作後废。］","sortOrder":260},
  {"id":"s_work_nvlt_88_261","chapterId":"ch_work_nvlt_88","text":"枯桑知天風，［《太平御覽》九百五十五作古詩。］","sortOrder":261},
  {"id":"s_work_nvlt_88_262","chapterId":"ch_work_nvlt_88","text":"齊太祖宅在武進，宅南有桑树，擢本三丈，橫出四枝如車蓋，上年數歲，遊於下，從兄敬宗謂曰：此树為汝生也，［本條《太平御覽》九百五十五作齊書。］","sortOrder":262},
  {"id":"s_work_nvlt_88_263","chapterId":"ch_work_nvlt_88","text":"【詩】後漢宋子侯董娇饒詩曰：洛陽城東路，桃李生路旁，花花自相對，葉葉自相當，春風東北起，花葉正低昂，不知誰家子，提籠行采桑，纖手折其枝，花落何飄颺，請謝彼姝子，何為見損傷，高秋八九月，白露变為霜，終年會飄墮，安得久馨香，秋時自零落，春月复芬芳，何如盛年去，歡如永相忘，吾欲竟此曲，此曲愁人腸，歸來酌美酒，挟琴上高堂。","sortOrder":263},
  {"id":"s_work_nvlt_88_264","chapterId":"ch_work_nvlt_88","text":"魏陳王曹植艳歌曰：出自蓟北門，遙望湖池桑，枝枝自相植，葉葉自相當。","sortOrder":264},
  {"id":"s_work_nvlt_88_265","chapterId":"ch_work_nvlt_88","text":"梁簡文帝采桑詩曰：春色暎空來，先發院邊梅，細萍重叠長，新花歷亂开，連珂往淇上，接幰至丛台，丛台可怜妾，當窗望飛蝶，忌趺行衫領，熨斗成褫俵，寄語采桑伴，訝今春日短，枝高攀不及，葉細籠難滿。","sortOrder":265},
  {"id":"s_work_nvlt_88_266","chapterId":"ch_work_nvlt_88","text":"梁吳筠采桑詩曰：賤妾思不堪，采桑渭城南，帶减連枝繡，發亂鳳皇篸，花舞依長薄，蛾飛愛绿潭，無由報君信，流涕向春蠶。","sortOrder":266},
  {"id":"s_work_nvlt_88_267","chapterId":"ch_work_nvlt_88","text":"又陌上桑詩曰：裊裊陌上桑，荫陌复垂塘，長條暎白日，細葉隱鸝黃，蠶飢妾复思，拭淚且提筐。","sortOrder":267},
  {"id":"s_work_nvlt_88_268","chapterId":"ch_work_nvlt_88","text":"梁劉邈萬山見采桑人詩曰：倡女不勝愁，結束下青樓，逐伴西蠶路，相携南陌頭，葉盡時移树，枝高乍易鉤，絲繩掛且脱，金籠寫复收，蠶飢日已暝，詎為使君留。","sortOrder":268},
  {"id":"s_work_nvlt_88_269","chapterId":"ch_work_nvlt_88","text":"梁王台卿詠陌上桑詩曰：令月开和景，處處動春心，桂筐須葉滿，息惓重枝陰。","sortOrder":269},
  {"id":"s_work_nvlt_88_270","chapterId":"ch_work_nvlt_88","text":"陳徐伯陽賦得日出東南隅詩曰：朱城壁日啟朱扉，青樓含照本暉暉，遠暎陌上春桑葉，斜入秦家緗綺衣，羅敷妆粉能佳麗，鏡前新梳倭墮髻，圓籠裊裊掛青絲，鐵鉤冉冉勝丹桂，蠶飢日晚蹔生愁，忽逢使君南陌頭，五馬停珂遣借問，双脸含娇特好羞，妾婿府中輕小吏，即今來往专城里，欲識東方千騎歸，藹藹日暮紅尘起。","sortOrder":270},
  {"id":"s_work_nvlt_88_271","chapterId":"ch_work_nvlt_88","text":"【賦】魏繁钦桑賦曰：上似華蓋，紫極比形，下象鳳闕，萬桷一楹，丛枝互出，乃错乃併，晔晔隆暑，涼風自生，微條纖繞，隨風浮沉，陽蜩鳴其南枝，寒蝉噪其北陰，秋氣忽其將來，鹹感節而悲吟，玩庇荫之厚惠，情眷眷而愛深。","sortOrder":271},
  {"id":"s_work_nvlt_88_272","chapterId":"ch_work_nvlt_88","text":"晉陆機桑賦曰：皇太子便坐，蓋本將軍直庐也，初世祖武皇帝為中壘將軍，植桑一株，世更二代，年漸三紀，扶疏丰衍，抑有瑰異焉，夫何佳树之洪麗，超讬居乎紫庭，羅萬根以下洞，矯千條而上征，豈民黎之能植，乃世武之所營，故其形瑰族類，體艳眾木，黃中爽理，滋榮煩縟，绿葉興而盈尺，崇條蔓而曾尋，希太極以延峙，暎承明而廣臨，華飛鴞之流响，想鳴鳥之遺音，惟歷數之有紀，恒依物以表德，豈神明之所相，將我皇之先識，跨百世而勿翦，超長年以永植。","sortOrder":272},
  {"id":"s_work_nvlt_88_273","chapterId":"ch_work_nvlt_88","text":"晉潘尼桑树賦曰：從明储以省膳，憩便房以偃息，觀茲树之特玮，感先皇之攸植，蔚萧森以四射，邈洪佣而端直，爾乃徘徊周覽，俯仰逍遙，俯睨靈根，上眺脩條，洞芳泉於九壤，含溢露於清霄，倚增城之飛觀，拂綺窗之疏寮，下迢遞以極望，上扶疏而參差，匪眾鳥之攸萃，相皇鸞之羽儀，理有微而至顯，道有隱而應期，豈皇晉之貞瑞，兆先見而啟茲，起尋抱於纖毫，崇萬匮於始基。","sortOrder":273},
  {"id":"s_work_nvlt_88_274","chapterId":"ch_work_nvlt_88","text":"晉傅鹹桑树賦曰：世祖昔為中壘將軍，於直庐种桑一株，迄今三十餘年，其茂盛不衰，皇太子入朝，以此庐為便坐，伊茲树之僥倖，蒙生生之渥惠，降皇躬以斯植，遂弘茂於聖世，厥茂伊何，其大連尋，脩柯遠扬，洪條梢椮，布簟枝之沃若，播密葉以垂陰，荫華宇而作涼，清隆暑之難任，以厥树之巨伟，登九日於朝陽，且積小以高大，生合抱於毫芒，猶帝道之將升，亦累德以弥光，湯躬祷於斯林，用獲雨而興商，惟皇晉之基命，爰於斯而發祥，從皇储於斯馆，物無改於平生，心惻切以興思，思有感於聖明，步旁遑以周覽，庶仿佛於儀形。","sortOrder":274},
  {"id":"s_work_nvlt_88_275","chapterId":"ch_work_nvlt_88","text":"【贊】晉郭璞帝女桑贊曰：爰有洪桑，生濱淪潭，厥围五丈，枝相交參，園客是采，帝女所蠶。","sortOrder":275},
  {"id":"s_work_nvlt_88_277","chapterId":"ch_work_nvlt_88","text":"《爾雅》曰：藲{艹至}，［詩雲，山有枢，今之刺榆也。］無姑，其實夷，［姑榆也，生山中，葉圓厚，剝取皮，合渍之，味辛香，所謂無夷是也。］","sortOrder":277},
  {"id":"s_work_nvlt_88_278","chapterId":"ch_work_nvlt_88","text":"《說文》曰：榆，白枌也，榆有刺荚，為芜荑。","sortOrder":278},
  {"id":"s_work_nvlt_88_279","chapterId":"ch_work_nvlt_88","text":"《毛詩》曰：山有枢，隰有榆。","sortOrder":279},
  {"id":"s_work_nvlt_88_280","chapterId":"ch_work_nvlt_88","text":"周官，司烜氏，四時变國火，［春取榆柳(原訛所，據冯校本改。)之火。］","sortOrder":280},
  {"id":"s_work_nvlt_88_281","chapterId":"ch_work_nvlt_88","text":"《禮記》：內則曰：槿荁枌榆兔藁滫髓以滑之。","sortOrder":281},
  {"id":"s_work_nvlt_88_282","chapterId":"ch_work_nvlt_88","text":"《春秋元命苞》曰：三月榆荚落。","sortOrder":282},
  {"id":"s_work_nvlt_88_283","chapterId":"ch_work_nvlt_88","text":"《管子》曰：五沃之土，其榆條長。","sortOrder":283},
  {"id":"s_work_nvlt_88_284","chapterId":"ch_work_nvlt_88","text":"《史記·天官書》曰：凡望雲氣，平望在桑榆上，餘二千里。","sortOrder":284},
  {"id":"s_work_nvlt_88_285","chapterId":"ch_work_nvlt_88","text":"《莊子》曰：鵲上高城之垝，而巢於高榆之顛，城坏巢折，凌風而起，故君子之居世也，得時則義行，失時則鵲起。","sortOrder":285},
  {"id":"s_work_nvlt_88_286","chapterId":"ch_work_nvlt_88","text":"《韓詩外傳》曰：楚莊王將伐晉，敢諫者死，孫叔敖進諫王曰：臣園中有榆，榆上有蝉，蝉方奋翼悲鳴，飲清露，不知螗螂之在後也。","sortOrder":286},
  {"id":"s_work_nvlt_88_287","chapterId":"ch_work_nvlt_88","text":"《漢書》：郊祀志雲，高祖祷丰枌榆社，［在丰東北十五里也。］","sortOrder":287},
  {"id":"s_work_nvlt_88_288","chapterId":"ch_work_nvlt_88","text":"又，天文志曰：成帝河平元年，旱，傷麥，民食榆皮。","sortOrder":288},
  {"id":"s_work_nvlt_88_289","chapterId":"ch_work_nvlt_88","text":"又，循吏傳曰：龚遂為渤海太守，勸民務農桑，令种榆，一口一树。","sortOrder":289},
  {"id":"s_work_nvlt_88_290","chapterId":"ch_work_nvlt_88","text":"桓谭《新論》曰：劉子駿信方士虛言，為神仙可學，餘見其庭下有大榆树，久老剝折，指謂曰：彼树無情，然猶朽蠹，人雖欲愛養，何能使之不衰。","sortOrder":290},
  {"id":"s_work_nvlt_88_291","chapterId":"ch_work_nvlt_88","text":"崔寔《四民月令》曰：榆荚成者，收乾以為旨蓄，色变白，將落，收為醬，隨節早晚，勿失其適，《魏志》曰：鄭浑為魏郡太守，課百姓乏材木，乃課种榆為篱。","sortOrder":291},
  {"id":"s_work_nvlt_88_292","chapterId":"ch_work_nvlt_88","text":"嵇康養生論曰：豆令人重，榆令人眠，愚智所知也。","sortOrder":292},
  {"id":"s_work_nvlt_88_293","chapterId":"ch_work_nvlt_88","text":"《博物志》曰：食枌榆則眠不欲覺。","sortOrder":293},
  {"id":"s_work_nvlt_88_294","chapterId":"ch_work_nvlt_88","text":"晉宮闕名曰：華林園榆十九株。","sortOrder":294},
  {"id":"s_work_nvlt_88_295","chapterId":"ch_work_nvlt_88","text":"《雜五行書》曰：舍北种榆九株，蠶大得。","sortOrder":295},
  {"id":"s_work_nvlt_88_296","chapterId":"ch_work_nvlt_88","text":"《毛詩義疏》曰：駮駮馬，梓榆，駮荦，遙视似駮馬。","sortOrder":296},
  {"id":"s_work_nvlt_88_297","chapterId":"ch_work_nvlt_88","text":"趙書曰：從幽州大道呼沱河，造浮桥，植行榆五十里，署行宮。","sortOrder":297},
  {"id":"s_work_nvlt_88_298","chapterId":"ch_work_nvlt_88","text":"《廣志》曰：有姑榆，有郎榆，郎榆無荚，村人［《太平御覽》九百五十六作材又。］任車用，至善，蠶［御覽作青蠡二字。］者，出渤海東光，以供官。","sortOrder":298},
  {"id":"s_work_nvlt_88_299","chapterId":"ch_work_nvlt_88","text":"石虎《鄴中記》曰：襄國鄴路，千里之中，夹道种榆，盛暑之月，人行其下。","sortOrder":299},
  {"id":"s_work_nvlt_88_300","chapterId":"ch_work_nvlt_88","text":"《幽明錄》曰：虎［《太平御覽》九百六十作虞。］晚家有皂荚树，有神，隔路有大榆树，古傳曰：是雌雄，晚被斫，此树枯死。","sortOrder":300},
  {"id":"s_work_nvlt_88_301","chapterId":"ch_work_nvlt_88","text":"范子《計然》曰：芜荑出地赤心者善。","sortOrder":301},
  {"id":"s_work_nvlt_88_302","chapterId":"ch_work_nvlt_88","text":"《淮南子萬畢術》曰：八月榆檽，令人不飢。","sortOrder":302},
  {"id":"s_work_nvlt_88_303","chapterId":"ch_work_nvlt_88","text":"《氾勝之書》曰：种木無期，因地為時，三月榆荚雨時，高地強土可种木。","sortOrder":303},
  {"id":"s_work_nvlt_88_304","chapterId":"ch_work_nvlt_88","text":"《風俗通》曰：桑車榆轂聞聲之，［句有訛文。］","sortOrder":304},
  {"id":"s_work_nvlt_88_305","chapterId":"ch_work_nvlt_88","text":"夢書曰：榆為人君，德至仁也，夢采榆葉，受賜恩也，夢居树上，得貴官也。","sortOrder":305},
  {"id":"s_work_nvlt_88_306","chapterId":"ch_work_nvlt_88","text":"【詩】古詩曰：天上何所有，歷歷种白榆。","sortOrder":306},
  {"id":"s_work_nvlt_88_307","chapterId":"ch_work_nvlt_88","text":"【書】魏應璩與庞惠恭書曰：頻見所上利民之術，植濟南之榆，栽漢中之漆。","sortOrder":307},
  {"id":"s_work_nvlt_88_309","chapterId":"ch_work_nvlt_88","text":"《爾雅》曰：榮，桐木，［梧桐也。］","sortOrder":309},
  {"id":"s_work_nvlt_88_310","chapterId":"ch_work_nvlt_88","text":"《尚書》曰：嶧陽孤桐。","sortOrder":310},
  {"id":"s_work_nvlt_88_311","chapterId":"ch_work_nvlt_88","text":"《禮》曰：季春之月，桐始華。","sortOrder":311},
  {"id":"s_work_nvlt_88_312","chapterId":"ch_work_nvlt_88","text":"《毛詩》曰：梧桐生矣，於彼朝陽。","sortOrder":312},
  {"id":"s_work_nvlt_88_313","chapterId":"ch_work_nvlt_88","text":"又曰：椅桐梓漆，爰伐琴瑟。","sortOrder":313},
  {"id":"s_work_nvlt_88_314","chapterId":"ch_work_nvlt_88","text":"《詩義疏》曰：有青桐赤桐白桐，白桐宜琴瑟，今雲南牂牁人，績以為布。","sortOrder":314},
  {"id":"s_work_nvlt_88_315","chapterId":"ch_work_nvlt_88","text":"《周書》曰：清明之日，桐始華，不始華，歲大寒。","sortOrder":315},
  {"id":"s_work_nvlt_88_316","chapterId":"ch_work_nvlt_88","text":"《禮斗威儀》曰：君乘火而王，其政平，梧桐為常生。","sortOrder":316},
  {"id":"s_work_nvlt_88_317","chapterId":"ch_work_nvlt_88","text":"《莊子》曰：外乎子之神，勞乎子之精，倚树而吟，據梧而暝。","sortOrder":317},
  {"id":"s_work_nvlt_88_318","chapterId":"ch_work_nvlt_88","text":"又曰：鴛雏發南海，而飛到北海，非梧桐不止，非竹實不食。","sortOrder":318},
  {"id":"s_work_nvlt_88_319","chapterId":"ch_work_nvlt_88","text":"《呂氏春秋》曰：成王與唐叔虞燕居，援梧葉以翦珪，以告曰：以此封汝，虞喜，以告周公，周公請封虞，王曰：餘與虞戲，周公曰：臣聞之，天子無戲言，於是遂封叔虞於晉。","sortOrder":319},
  {"id":"s_work_nvlt_88_320","chapterId":"ch_work_nvlt_88","text":"邹山記曰：邹山古之嶧陽，魯穆公改為邹，今邹山嶧陽，猶多桐树。","sortOrder":320},
  {"id":"s_work_nvlt_88_321","chapterId":"ch_work_nvlt_88","text":"齊地記曰：城北十五里，有桐台，即梧宮。","sortOrder":321},
  {"id":"s_work_nvlt_88_322","chapterId":"ch_work_nvlt_88","text":"《異苑》曰：晉武帝世，吳郡臨平岸出一石，打之無聲，以問張華，華雲，取蜀中桐材，刻作魚形，扣之則鳴矣，於是如言，音聞數里。","sortOrder":322},
  {"id":"s_work_nvlt_88_323","chapterId":"ch_work_nvlt_88","text":"又，句章吳平，州門前忽生一株青桐树，上有謠歌之聲，平惡而斫殺，平隨軍北虜，首尾三載，死桐欻自還立於故根上，聞聲树巔，空中歌曰：死树今更青，吳平尋當歸，適聞殺此树，已复有光辉，平尋歸，如鬼謠。","sortOrder":323},
  {"id":"s_work_nvlt_88_324","chapterId":"ch_work_nvlt_88","text":"祖後怪［《太平御覽》九百五十六作祖台之志怪。］曰：騫保坐［御覽作至。］檀近［御覽作丘。］坞，上北樓宿，暮鼓二中，有人著黃練单衣，白恰，［御覽作帢。］得［御覽作將。］人持炬火上樓，保懼，藏壁中，須臾，有二婢上帳，使迎一女子上，與白恰人入帳宿，未明，白恰辄先去，保因入帳中，問侍女子，向去者誰，答曰：桐郎，道東廟树是，至暮［御覽暮下有鼓字。］二中，桐郎复來，保乃斫取之，縛著樓柱，明日视之，形如人，長三尺餘，槛送詣丞相，渡江未半，風浪起，桐郎得投入水，風波乃息。","sortOrder":324},
  {"id":"s_work_nvlt_88_325","chapterId":"ch_work_nvlt_88","text":"《秦記》曰：初長安謠雲，鳳皇止阿房，符堅遂於阿房城植桐數萬株，以至慕容冲入阿房而居，冲小字鳳皇。","sortOrder":325},
  {"id":"s_work_nvlt_88_326","chapterId":"ch_work_nvlt_88","text":"《廣志》曰：梧桐有白者，異［《太平御覽》九百五十六作剽。］國有白木，其葉有白毳，取其毳淹清湑，績織以為布也。","sortOrder":326},
  {"id":"s_work_nvlt_88_327","chapterId":"ch_work_nvlt_88","text":"遜山［《初學記》二十八，《太平御覽》九百五十六作遊名山記。］曰：吹台有高桐，皆百围，嶧陽孤桐，方此為劣。","sortOrder":327},
  {"id":"s_work_nvlt_88_328","chapterId":"ch_work_nvlt_88","text":"王孚安成記曰：府君讳保，如今树梧於苞兩邊，［句有衍訛。］柯葉菴藹，炎暑為之清涼，百姓列宅其間。","sortOrder":328},
  {"id":"s_work_nvlt_88_329","chapterId":"ch_work_nvlt_88","text":"《管子》曰：五沃之土，其木宜桐。","sortOrder":329},
  {"id":"s_work_nvlt_88_330","chapterId":"ch_work_nvlt_88","text":"《莊子》曰：空門未［《太平御覽》九百五十六作來。］風，桐乳致巢，［司馬彪註曰：門戶空，風葉而生其葉自箕曰投之也，桐子似乳，著鳥之巢，○御覽作門戶空，風喜投之，桐子似乳，著葉而生，鳥喜巢之，此有訛倒。］","sortOrder":330},
  {"id":"s_work_nvlt_88_331","chapterId":"ch_work_nvlt_88","text":"淮南子曰：智有所不足，故桐不可與為弓。","sortOrder":331},
  {"id":"s_work_nvlt_88_332","chapterId":"ch_work_nvlt_88","text":"淮南《萬畢術》曰：桐木成雲，［取十石瓮滿中三四日氣水置桐蓋之，三日如雲形，○《太平御覽》九百五十六作取十石瓦罌，滿中水，置桐蓋之，三四日氣如雲作，此有訛倒。］","sortOrder":332},
  {"id":"s_work_nvlt_88_333","chapterId":"ch_work_nvlt_88","text":"董仲舒請雨書曰：秋以桐魚九枚。","sortOrder":333},
  {"id":"s_work_nvlt_88_334","chapterId":"ch_work_nvlt_88","text":"遁甲，梧桐不生則九州異。","sortOrder":334},
  {"id":"s_work_nvlt_88_335","chapterId":"ch_work_nvlt_88","text":"《王逸子》曰：木有状［《太平御覽》九百五十六作扶。］桑梧桐松柏，皆受氣淳矣，異於群類者。","sortOrder":335},
  {"id":"s_work_nvlt_88_336","chapterId":"ch_work_nvlt_88","text":"新論曰：神農皇［《太平御覽》九百五十六作黃。］帝，削桐為琴。","sortOrder":336},
  {"id":"s_work_nvlt_88_337","chapterId":"ch_work_nvlt_88","text":"崔琦七蠲雲，爰有梧桐，玄子［《太平御覽》九百五十六作生於。］玄谿，傳根朽壤，讬险生危。","sortOrder":337},
  {"id":"s_work_nvlt_88_338","chapterId":"ch_work_nvlt_88","text":"枚乘七發曰：龍門之桐，百尺無枝，其中鬱結〈王崙〉菌，扶疏以分離，其根半死半生，冬則風漂霰雪飛。","sortOrder":338},
  {"id":"s_work_nvlt_88_339","chapterId":"ch_work_nvlt_88","text":"張协七命曰：寒山桐，出自大冥，含黃鍾以吐幹，據蒼岑以孤生。","sortOrder":339},
  {"id":"s_work_nvlt_88_340","chapterId":"ch_work_nvlt_88","text":"《孟子》曰：今有場師，舍其梧槚，養其楫［《太平御覽》九百五十六作樲。］棗，則為賤場師矣，［弃大取小。］","sortOrder":340},
  {"id":"s_work_nvlt_88_341","chapterId":"ch_work_nvlt_88","text":"蘇子曰：夫人生一世，若晓露之讬桐葉耳，其興幾何。","sortOrder":341},
  {"id":"s_work_nvlt_88_342","chapterId":"ch_work_nvlt_88","text":"《古今註》：昭帝丹鳳三年，冯翊人獻桐枝，長六尺，九枚，三葉也。","sortOrder":342},
  {"id":"s_work_nvlt_88_343","chapterId":"ch_work_nvlt_88","text":"【詩】魏明帝詩曰：双桐生空井，枝葉自相加，通泉浸其根，玄雨润其柯。","sortOrder":343},
  {"id":"s_work_nvlt_88_344","chapterId":"ch_work_nvlt_88","text":"晉司馬彪與山巨原［按當作源。］詩曰：苕苕椅桐树，寄生於南嶽，上陵青雲霓，下臨千仞穀，處身孤且危，於何讬餘足，昔也植朝陽，傾枝俟鸞鷟，今者絕世用，倥偬見迫束，班匠不我顧，牙曠不我錄，焉得成琴瑟，何由扬妙曲，卞和潛幽巖，誰能證奇璞，冀望神龍來，扬光已見燭。","sortOrder":344},
  {"id":"s_work_nvlt_88_345","chapterId":"ch_work_nvlt_88","text":"宋伏系之詠椅桐詩曰：亭亭椅桐，鬱茲庭圃，翠條疏風，绿柯荫宇。","sortOrder":345},
  {"id":"s_work_nvlt_88_346","chapterId":"ch_work_nvlt_88","text":"宋鮑昭山行見孤桐詩曰：桐生丛穀里，根孤地寒陰，未霜葉已肅，不風條自吟，不原見彫斫，為君堂上琴。","sortOrder":346},
  {"id":"s_work_nvlt_88_347","chapterId":"ch_work_nvlt_88","text":"齊謝朓遊東堂詠桐詩曰：孤桐北窗外，高枝百丈餘，枝生既婀娜，葉落更扶疏，無華复無實，何以赠離居，裁為珪與璋，足可命參墟。","sortOrder":347},
  {"id":"s_work_nvlt_88_348","chapterId":"ch_work_nvlt_88","text":"梁簡文帝賦得双桐生空井詩曰：季月双桐井，新枝雜舊株，晚葉藏遷鳳，朝花拂曙乌。","sortOrder":348},
  {"id":"s_work_nvlt_88_349","chapterId":"ch_work_nvlt_88","text":"梁王筠奉酬從兄臨川桐树詩曰：伊昔擅羽儀，待价龍門垂，優遊清露點，徽穆惠風吹，月上陰陽幹，雲覆死生枝，公子存高尚，聊用影華池，栖鸞既不重，舞鶴复何施，方同散木{亠爨}，清响竟誰知。","sortOrder":349},
  {"id":"s_work_nvlt_88_350","chapterId":"ch_work_nvlt_88","text":"梁沈約詠梧桐詩曰：秋還遽已落，春晓猶未荑，微葉雖可賤，一翦或成珪。","sortOrder":350},
  {"id":"s_work_nvlt_88_351","chapterId":"ch_work_nvlt_88","text":"【賦】晉傅鹹梧桐賦曰：美詩人之攸貴兮，覽梧桐乎朝陽，蔚菶々以萋萋兮，鬱株列而成行，夹二門以骈羅，作馆宇之表章。","sortOrder":351},
  {"id":"s_work_nvlt_88_352","chapterId":"ch_work_nvlt_88","text":"晉夏侯湛愍桐賦曰：有南國之陋寢，植嘉桐乎前庭，闡洪根以誕茂，丰脩幹以繁生，納穀風以疏葉，含春雨以濯茎，濯茎夭夭，布葉藹藹，蔚童童以重茂，荫蒙接而相蓋，蔽陰澹之南表，覆陽阿之北外，於是詰朝之暇，步趾前庑，春以遊目，夏以清暑，昔詩人之所稱，美厥生之攸奇，植匪岗其不滋，鳳非條其不儀。","sortOrder":352},
  {"id":"s_work_nvlt_88_353","chapterId":"ch_work_nvlt_88","text":"宋袁淑桐賦曰：越眾木之薰徇，勝雜树之藻縟，信爽幹以弱枝，實里素而表绿，若乃根荑條茂，跡曠心冲，貞觀於曾山之陽，抽景於少泽之東，被籍兮煙霞，懷珮兮星虹，儀丹丘之瑞羽，栖清都之仙宮。","sortOrder":353},
  {"id":"s_work_nvlt_88_354","chapterId":"ch_work_nvlt_88","text":"齊王融應竟陵王教桐树賦曰：梧桐生矣，於邸岫之曾隈，儀龍門而插幹，佇鳳羽以抽枝，蹤楚宮而留稱，籍溜馆以翻聲，直不繩而特秀，圓匪規而天成，同歲草以委暮，共辰物而滋榮，豈违心於自外，寧有志於孤貞。","sortOrder":354},
  {"id":"s_work_nvlt_88_355","chapterId":"ch_work_nvlt_88","text":"梁沈約桐賦曰：龍門之桐，遠望青葱，专巖擅嶺，或孤或丛，枝封暮雪，葉暎書紅，抗蘭橑以栖龍，拂雕窗而团露，喧密葉於鳳晨，宿高枝於鸞暮，合影陽崖，摽峰東陆，俯結玄陰，仰成翠屋，乍仿佛於行雨，時徘徊於丹轂，繞齊采於碧林，豈慚光於若木。","sortOrder":355},
  {"id":"s_work_nvlt_88_356","chapterId":"ch_work_nvlt_88","text":"又八詠悲落桐曰：悲落桐，悲落桐早霜露，燕至葉未抽，鸿來枝已素，幽根未蟠結，孤株复危絕，初不照光景，終年負霜雪，勿言草木賤，徒照君末光，末光不徒照，為君含噭咷，陽柯绿水絃，陰枝苦寒蜩，厚德非所任，不敢虛其心，若逢陽春至，吐绿照清潯。","sortOrder":356},
  {"id":"s_work_nvlt_88_357","chapterId":"ch_work_nvlt_88","text":"【贊】郭璞梧桐贊曰：桐寔嘉木，鳳凰所栖，爰伐琴瑟，八音克諧，歌以永言，噰々喈喈。","sortOrder":357},
  {"id":"s_work_nvlt_88_358","chapterId":"ch_work_nvlt_88","text":"宋孝武孤桐贊曰：珍無隱德，產有必甄，資此孤幹，獻枝楚山，梢星雲界，衍葉炎廛，名列貢寶，器贊虞絃。","sortOrder":358},
  {"id":"s_work_nvlt_88_359","chapterId":"ch_work_nvlt_88","text":"《藝文類聚》　唐·欧陽詢","sortOrder":359},
  {"id":"s_work_nvlt_89_1","chapterId":"ch_work_nvlt_89","text":"卷八十九木部下","sortOrder":1},
  {"id":"s_work_nvlt_89_2","chapterId":"ch_work_nvlt_89","text":"○楊柳柽椒梓桂楓豫章無患朱树君子枞桧茱萸柟柞楸櫟楛靈寿女貞長生木槿樗木蘭夫栘橚若木合歡杉併闾荆棘黃莲栀子竹","sortOrder":2},
  {"id":"s_work_nvlt_89_3","chapterId":"ch_work_nvlt_89","text":"◇楊柳","sortOrder":3},
  {"id":"s_work_nvlt_89_4","chapterId":"ch_work_nvlt_89","text":"《爾雅》曰：旄，泽柳，［生泽中也。］楊，蒲柳。","sortOrder":4},
  {"id":"s_work_nvlt_89_5","chapterId":"ch_work_nvlt_89","text":"《詩》曰：楊柳依依。","sortOrder":5},
  {"id":"s_work_nvlt_89_6","chapterId":"ch_work_nvlt_89","text":"《左傳》曰：董泽之蒲。","sortOrder":6},
  {"id":"s_work_nvlt_89_7","chapterId":"ch_work_nvlt_89","text":"《莊子》：支離叔觀於冥伯之丘，崑崙之墟，黃帝之所休，俄而柳生其左肘。","sortOrder":7},
  {"id":"s_work_nvlt_89_8","chapterId":"ch_work_nvlt_89","text":"《戰國策》曰：楚有養由基，善射，去楊葉百步而射之，百發百中。","sortOrder":8},
  {"id":"s_work_nvlt_89_9","chapterId":"ch_work_nvlt_89","text":"《漢書》曰：昭帝時，上林苑中大柳树斷，臥地，一朝起生枝葉，有虫蚀其葉為字，曰公孫病已立，及昭帝崩，亡嗣，大臣迎立昌邑王，王即位，淫亂失道，霍光废之，更立昭帝兄衛太子之孫，是為宣帝，帝本名病已雲。","sortOrder":9},
  {"id":"s_work_nvlt_89_10","chapterId":"ch_work_nvlt_89","text":"《文士傳》曰：嵇康性絕巧，能鍛，家有一柳树，乃激水以圜之，夏天甚涼，居其下遨戲及鍛。","sortOrder":10},
  {"id":"s_work_nvlt_89_11","chapterId":"ch_work_nvlt_89","text":"陶潛曰：五柳先生，不知何許人，亦不詳姓字，宅邊有五柳，因以為號。","sortOrder":11},
  {"id":"s_work_nvlt_89_12","chapterId":"ch_work_nvlt_89","text":"許慎淮南子註曰：展禽之家，树柳行惠德，因號柳下惠，一曰邑名。","sortOrder":12},
  {"id":"s_work_nvlt_89_13","chapterId":"ch_work_nvlt_89","text":"《琴操》曰：其思革子尹文子叔儋子，相與為友，聞楚成王賢，俱往見之，至嵚巖之間，卒逢飄風暴雨，共伏於空柳之下，衣寒糧乏，自度不能俱活，以革子為賢，乃併衣糧與之，二子遂冻饿而死，革子見楚王，楚王知其賢，陳酒設鍾鼓而樂之，革子操琴而作別散之音，楚王賜其百金，以葬二子。","sortOrder":13},
  {"id":"s_work_nvlt_89_14","chapterId":"ch_work_nvlt_89","text":"《易大過卦》曰：枯楊生梯，［註(原訛洼，據冯校本改。)生華。］老夫得其女妻。","sortOrder":14},
  {"id":"s_work_nvlt_89_15","chapterId":"ch_work_nvlt_89","text":"焦贛《易林》：豫之晉曰，鵲巢柳树，鳩奪其處，任力劣薄，天命不祐。","sortOrder":15},
  {"id":"s_work_nvlt_89_16","chapterId":"ch_work_nvlt_89","text":"《毛詩》：東方未明曰：折柳樊圃，［柳，弱枙(《太平御覽》九百五十六作脆。)之木，樊，藩也，折柳為藩，無益於禁。］","sortOrder":16},
  {"id":"s_work_nvlt_89_17","chapterId":"ch_work_nvlt_89","text":"《毛詩義疏》曰：蒲柳之木二种，一种皮正白，可為箭竿，傳曰：董泽之蒲，今人以為其雚，可為矢。","sortOrder":17},
  {"id":"s_work_nvlt_89_18","chapterId":"ch_work_nvlt_89","text":"《詩義疏》曰：树杞，杞柳也，生水旁，树如柳，葉粗而白，木理微赤，今人以為轂，《大戴禮》曰：正月柳梯，梯者發葉也。","sortOrder":18},
  {"id":"s_work_nvlt_89_19","chapterId":"ch_work_nvlt_89","text":"《爾雅》曰：柽，河柳。","sortOrder":19},
  {"id":"s_work_nvlt_89_20","chapterId":"ch_work_nvlt_89","text":"《說文》曰：楊，薄柳也，從木昜聲，柽，河柳也，從木聖聲，柳，小楊也，從木卯聲也。","sortOrder":20},
  {"id":"s_work_nvlt_89_21","chapterId":"ch_work_nvlt_89","text":"《晉中興書》曰：陶侃明識過人，武昌道种柳，人有竊之，植於其家，侃見而識之，問何以盜官柳种，於時以為神。","sortOrder":21},
  {"id":"s_work_nvlt_89_22","chapterId":"ch_work_nvlt_89","text":"沈約《宋書》曰：萧惠开為少府，不得志，寺內斋前香草蕙蘭悉铲除，列种白柳。","sortOrder":22},
  {"id":"s_work_nvlt_89_23","chapterId":"ch_work_nvlt_89","text":"《續搜神記》曰：上虞魏金，家在縣北，忽有一人，著孝子服，皂笠，手巾掩口，來詣金家，語曰：居有錢一千萬，銅器亦如之，大柳树錢在其下，取錢當得耳，書居大不吉，仆尋為君作此，便去，自爾出三十年，遂不复來，金亦不取錢。","sortOrder":23},
  {"id":"s_work_nvlt_89_24","chapterId":"ch_work_nvlt_89","text":"盛弘之《荆州記》曰：緣城堤邊，悉植細柳，绿條散風，清陰交陌。","sortOrder":24},
  {"id":"s_work_nvlt_89_25","chapterId":"ch_work_nvlt_89","text":"三齊略記曰：台城東南，有蒲台，高八丈，始皇所頓處，在台下萦馬，至今蒲生猶萦，似水楊而堪為箭。","sortOrder":25},
  {"id":"s_work_nvlt_89_26","chapterId":"ch_work_nvlt_89","text":"孔氏志怪記曰：會稽盛逸，嘗晨興，路未有行人，見門內柳树上，有一人，長二尺，衣朱衣冠冕，俯以舌舐树葉上露，良久，忽見逸，神意如驚，遽即隱不見。","sortOrder":26},
  {"id":"s_work_nvlt_89_27","chapterId":"ch_work_nvlt_89","text":"《管子》曰：五沃之土宜柳。","sortOrder":27},
  {"id":"s_work_nvlt_89_28","chapterId":"ch_work_nvlt_89","text":"《孟子》曰：性猶杞柳，義猶柸棬。","sortOrder":28},
  {"id":"s_work_nvlt_89_29","chapterId":"ch_work_nvlt_89","text":"崔寔《四民月令》曰：三月三日，以及上除，采柳絮，柳絮愈瘡。","sortOrder":29},
  {"id":"s_work_nvlt_89_30","chapterId":"ch_work_nvlt_89","text":"夢書曰：楊為使者。","sortOrder":30},
  {"id":"s_work_nvlt_89_31","chapterId":"ch_work_nvlt_89","text":"《本草經》曰：柳花一名絮。","sortOrder":31},
  {"id":"s_work_nvlt_89_32","chapterId":"ch_work_nvlt_89","text":"《論語》曰：鑽燧改火，春取柳榆木。","sortOrder":32},
  {"id":"s_work_nvlt_89_33","chapterId":"ch_work_nvlt_89","text":"《毛詩》曰：昔我往矣，楊柳依依。","sortOrder":33},
  {"id":"s_work_nvlt_89_34","chapterId":"ch_work_nvlt_89","text":"又曰：東門之楊，其葉牂牂。","sortOrder":34},
  {"id":"s_work_nvlt_89_35","chapterId":"ch_work_nvlt_89","text":"又曰：東門之楊，刺時也，婚姻失時，男女多违。","sortOrder":35},
  {"id":"s_work_nvlt_89_36","chapterId":"ch_work_nvlt_89","text":"又曰：北山有柳。","sortOrder":36},
  {"id":"s_work_nvlt_89_37","chapterId":"ch_work_nvlt_89","text":"又曰：菀彼柳斯，鳴蜩嘒嘒。","sortOrder":37},
  {"id":"s_work_nvlt_89_38","chapterId":"ch_work_nvlt_89","text":"又曰：菀柳，［篇名。］刺幽王也，暴虐而刑罰不中，有菀者柳，不尚息焉。","sortOrder":38},
  {"id":"s_work_nvlt_89_39","chapterId":"ch_work_nvlt_89","text":"楊之水，不流束蒲，［蒲柳可以為矢。］","sortOrder":39},
  {"id":"s_work_nvlt_89_40","chapterId":"ch_work_nvlt_89","text":"《文選》曰：閒居賦，長楊映碧沼，脩楊夹廣津。","sortOrder":40},
  {"id":"s_work_nvlt_89_41","chapterId":"ch_work_nvlt_89","text":"又曰：細柳夹道生。","sortOrder":41},
  {"id":"s_work_nvlt_89_42","chapterId":"ch_work_nvlt_89","text":"又，高楊拂地垂。","sortOrder":42},
  {"id":"s_work_nvlt_89_43","chapterId":"ch_work_nvlt_89","text":"又，二月楊花滿路飛。","sortOrder":43},
  {"id":"s_work_nvlt_89_44","chapterId":"ch_work_nvlt_89","text":"春林本自奇，楊柳最相宜。","sortOrder":44},
  {"id":"s_work_nvlt_89_45","chapterId":"ch_work_nvlt_89","text":"又曰：長楊荫清沼。","sortOrder":45},
  {"id":"s_work_nvlt_89_46","chapterId":"ch_work_nvlt_89","text":"鬱鬱園中柳。","sortOrder":46},
  {"id":"s_work_nvlt_89_47","chapterId":"ch_work_nvlt_89","text":"潘嶽又曰：柳條恒著地，弱柳荫脩衢。","sortOrder":47},
  {"id":"s_work_nvlt_89_48","chapterId":"ch_work_nvlt_89","text":"古樂府有折柳曲。","sortOrder":48},
  {"id":"s_work_nvlt_89_49","chapterId":"ch_work_nvlt_89","text":"一齊，［《太平御覽》九百五十七作齊書。］劉悛之為益州刺史，獻蜀柳數株，條甚長，状若絲縷，武帝植於太昌雲和殿前，常玩嗟之，曰：楊柳風流可愛，似張緒常，［御覽作當時二字。］見賞如此。","sortOrder":49},
  {"id":"s_work_nvlt_89_50","chapterId":"ch_work_nvlt_89","text":"晉，［《太平御覽》九百五十六作《晉書》：下桓溫條同。］王恭，字孝伯，美姿容，人多悅之，或目之濯濯如春月之柳。","sortOrder":50},
  {"id":"s_work_nvlt_89_51","chapterId":"ch_work_nvlt_89","text":"桓溫自江陵北行，往少時所，种柳處，皆十围，慨然叹曰：木猶如此，人何以堪，攀枝執條，泫然流涕。","sortOrder":51},
  {"id":"s_work_nvlt_89_52","chapterId":"ch_work_nvlt_89","text":"顧恺之，字長康，癡信小術，桓玄嘗以一葉柳诒之，曰：此蝉翳葉也，以自蔽，人不見己，恺之引葉自蔽，玄就溺焉，恺之信不見，以珍重之，俗傳恺之有三絕，此癡之一絕。","sortOrder":52},
  {"id":"s_work_nvlt_89_53","chapterId":"ch_work_nvlt_89","text":"《山海經》曰：沃民之國有白柳。","sortOrder":53},
  {"id":"s_work_nvlt_89_54","chapterId":"ch_work_nvlt_89","text":"《戰國策》曰：夫楊橫树之則生，倒树之亦生，折而树之又生，然十人拊之，一人拔之，則無楊矣，且以十人眾拊易生之初，然而不勝一人者何也，拊之難而去之易故也。","sortOrder":54},
  {"id":"s_work_nvlt_89_55","chapterId":"ch_work_nvlt_89","text":"《古今註》曰：楊員華弱蒂，微風則大搖，［雲雲。］一名高飛，一名燭搖。","sortOrder":55},
  {"id":"s_work_nvlt_89_56","chapterId":"ch_work_nvlt_89","text":"先賢傳曰：鄭敬以弟［按當作茅。］葭為席，隨杞柳之陰。","sortOrder":56},
  {"id":"s_work_nvlt_89_57","chapterId":"ch_work_nvlt_89","text":"又曰：有細柳營。","sortOrder":57},
  {"id":"s_work_nvlt_89_58","chapterId":"ch_work_nvlt_89","text":"【詩】古詩曰：白楊初生時，乃在豫章山，上葉拂青雲，下根通黃泉。","sortOrder":58},
  {"id":"s_work_nvlt_89_59","chapterId":"ch_work_nvlt_89","text":"梁簡文帝詠柳詩曰：垂陰滿上路，結草早知春，花絮時隨鳥，風枝屢拂尘，欲散依依采，時要歌吹人。","sortOrder":59},
  {"id":"s_work_nvlt_89_60","chapterId":"ch_work_nvlt_89","text":"又折楊柳詩曰：楊柳亂成絲，攀折上春時，葉密鳥飛礙，風輕花落遲，城高短箫發，林空畫角悲，曲中無別意，併是為相思。","sortOrder":60},
  {"id":"s_work_nvlt_89_61","chapterId":"ch_work_nvlt_89","text":"又和湘東王陽雲樓簷柳詩曰：暧暧陽雲台，春柳發新梅，柳枝無極软，春風隨意來，潭拖青帷閉，玲瓏朱扇开，佳人有所望，車聲非是雷。","sortOrder":61},
  {"id":"s_work_nvlt_89_62","chapterId":"ch_work_nvlt_89","text":"梁元帝詠陽雲樓簷柳詩曰：楊柳非花树，依樓自覺春，枝邊通粉色，葉里映吹纶，帶日交帘影，因吹扫席尘，拂簷應有意，偏宜桃李人。","sortOrder":62},
  {"id":"s_work_nvlt_89_63","chapterId":"ch_work_nvlt_89","text":"又折楊柳詩曰：巫山巫峡長，垂柳复垂楊，同心宜同折，故人懷故乡，山似莲花艳，流如明月光，寒夜猿鳴澈，遊子淚沾裳。","sortOrder":63},
  {"id":"s_work_nvlt_89_64","chapterId":"ch_work_nvlt_89","text":"又渌柳詩曰：長條垂拂地，輕花上逐風，露霑疑染渌，葉小未鄣空。","sortOrder":64},
  {"id":"s_work_nvlt_89_65","chapterId":"ch_work_nvlt_89","text":"梁劉邈折楊柳詩曰：高樓十載別，楊柳濯絲枝，摘葉驚开駛，攀枝恨久離，年年阻音息，月月减容儀，春來誰不思，想思君自知。","sortOrder":65},
  {"id":"s_work_nvlt_89_66","chapterId":"ch_work_nvlt_89","text":"梁沈約玩庭柳詩曰：輕陰拂建章，夹道連未央，因風結复解，霑露柔且長，楚妃思欲絕，班女淚成行，留人未應去，為此還故乡。","sortOrder":66},
  {"id":"s_work_nvlt_89_67","chapterId":"ch_work_nvlt_89","text":"陳祖孫登詠柳詩曰：馳道藏乌日，鬱鬱正翻風，抽翠爭連影，飛綿亂上空，高葉臨朝塞，長枝拂漢宮，欲验傷攀折，三春橫笛中。","sortOrder":67},
  {"id":"s_work_nvlt_89_68","chapterId":"ch_work_nvlt_89","text":"【賦】魏文帝柳賦，昔建安五年，上與袁紹戰於官渡時，餘始植斯柳，自彼迄今，十有五載矣，感物傷懷，乃作斯賦，曰：伊中域之伟木，瑰姿妙其可珍，彼庶卉之未動，固肇萌而先辰，應隆時而繁育，扬翠葉之青純，脩幹偃蹇以虹指，柔條阿那而蛇伸，上扶疏而孛散，下交错而龍鱗，在餘年之二七，植斯柳乎中庭，始围寸而高尺，今連拱而九成，嗟日月之逝邁，忽亹亹以遄征，昔周遊而處此，今倏忽而弗形，感遺物而懷故，俯惆怅以傷情。","sortOrder":68},
  {"id":"s_work_nvlt_89_69","chapterId":"ch_work_nvlt_89","text":"魏應玚楊柳賦曰：赴陽春之和節，植纖柳以承涼，摅丰節而廣布，紛鬱勃以敷陽，三春倏其奄過，景日赫其垂光，振鸿條而遠寿，回雲蓋於中唐。","sortOrder":69},
  {"id":"s_work_nvlt_89_70","chapterId":"ch_work_nvlt_89","text":"魏繁钦柳賦曰：有寄生之孤柳，讬餘寢之南隅，順肇陽以吐牙，因春風以扬敷，交绿葉而重葩，轉紛错以扶疏，鬱青青以畅茂，紛冉冉以陆離，浸朝露之清液，曜華采之猗猗。","sortOrder":70},
  {"id":"s_work_nvlt_89_71","chapterId":"ch_work_nvlt_89","text":"魏王粲柳賦曰：昔我君之定武，改天屆而徂征，元子從而撫軍，植佳木於茲庭，歷春秋以逾紀，行复出於斯乡，覽茲树之丰茂，紛旖旎以脩長，枝扶疏而覃布，茎森梢以奋扬。","sortOrder":71},
  {"id":"s_work_nvlt_89_72","chapterId":"ch_work_nvlt_89","text":"晉成公綏柳賦曰：宅京宇之西偏，濱犢鼻之清渠，啟橫門於大路，臨九達之通衢，愍行旅之靡休，树双柳於道隅，弥年載而成陰，紛憚援而扶疏。","sortOrder":72},
  {"id":"s_work_nvlt_89_73","chapterId":"ch_work_nvlt_89","text":"晉伍辑之柳花賦曰：步江皋兮騁望，感春柳之依依，垂柯葉而雲布，扬零華而雪飛，或風回而遊薄，或霧亂而飆零，野净秽而同降，物均色而齊明。","sortOrder":73},
  {"id":"s_work_nvlt_89_74","chapterId":"ch_work_nvlt_89","text":"晉傅玄柳賦曰：無邦壤而不植兮，象乾道之屢遷，紛猗靡以從風兮，若將往而复旋。","sortOrder":74},
  {"id":"s_work_nvlt_89_75","chapterId":"ch_work_nvlt_89","text":"【序】魏陳王曹植柳頌序曰：餘以閒暇，駕言出遊，過友人楊德祖之家，视其屋宇廖廓，庭中有一柳树，聊戲刊其枝葉，故著斯文，表之遺翰，遂因辭势，以譏當今之士。","sortOrder":75},
  {"id":"s_work_nvlt_89_77","chapterId":"ch_work_nvlt_89","text":"《爾雅》曰：柽，河柳，［河旁赤茎小楊也。］","sortOrder":77},
  {"id":"s_work_nvlt_89_78","chapterId":"ch_work_nvlt_89","text":"《南越志》曰：綏南縣多連山柽松杞梓。","sortOrder":78},
  {"id":"s_work_nvlt_89_79","chapterId":"ch_work_nvlt_89","text":"【詩】梁簡文帝詠柽詩曰：凌寒競貞節，負雪固難虧，無慚雲母桂，詎减珊瑚枝。","sortOrder":79},
  {"id":"s_work_nvlt_89_80","chapterId":"ch_work_nvlt_89","text":"【頌】梁江淹柽頌曰：碧葉菴藹，赪柯翕赩，方陋筠槚，遠笑荆棘。","sortOrder":80},
  {"id":"s_work_nvlt_89_82","chapterId":"ch_work_nvlt_89","text":"《春秋運斗枢》曰：玉衡星散為椒。","sortOrder":82},
  {"id":"s_work_nvlt_89_83","chapterId":"ch_work_nvlt_89","text":"《爾雅》{毀木}，大椒也，［今椒實大者名{毀木}也。］","sortOrder":83},
  {"id":"s_work_nvlt_89_84","chapterId":"ch_work_nvlt_89","text":"《山海經》曰：琴鼓之山，其木多椒，景山多秦椒。","sortOrder":84},
  {"id":"s_work_nvlt_89_85","chapterId":"ch_work_nvlt_89","text":"《毛詩》曰：椒聊之實。","sortOrder":85},
  {"id":"s_work_nvlt_89_86","chapterId":"ch_work_nvlt_89","text":"范子《計然》曰：蜀椒出武都，赤色者善，秦椒出天水隴西，細者善。","sortOrder":86},
  {"id":"s_work_nvlt_89_87","chapterId":"ch_work_nvlt_89","text":"《離骚》曰：雜申椒與菌桂，［申，重也。］","sortOrder":87},
  {"id":"s_work_nvlt_89_88","chapterId":"ch_work_nvlt_89","text":"又，播椒芳兮成堂，［布香椒於堂上。］","sortOrder":88},
  {"id":"s_work_nvlt_89_89","chapterId":"ch_work_nvlt_89","text":"又，奠桂酒兮椒漿。","sortOrder":89},
  {"id":"s_work_nvlt_89_90","chapterId":"ch_work_nvlt_89","text":"《孫卿子》曰：民之视我，驩若父母，其好我，芬若椒蘭。","sortOrder":90},
  {"id":"s_work_nvlt_89_91","chapterId":"ch_work_nvlt_89","text":"應劭《漢官儀》曰：皇後稱椒房，取其實曼延盈升，以椒涂室，亦取其溫暖。","sortOrder":91},
  {"id":"s_work_nvlt_89_92","chapterId":"ch_work_nvlt_89","text":"張璠《漢記》曰：桓帝窦皇後崩，中常侍曹節王甫，欲以貴人禮葬，太尉李固，自抉［《太平御覽》九百五十八作扶。］舆起，捣椒自隨，謂妻子曰：若太後不得配桓帝，吾不生還矣。","sortOrder":92},
  {"id":"s_work_nvlt_89_93","chapterId":"ch_work_nvlt_89","text":"崔寔《四民月令》曰：正月之旦，進酒降神畢，室家無大小，次坐先祖之前，子孫各上椒酒於其家長，稱舉白。","sortOrder":93},
  {"id":"s_work_nvlt_89_94","chapterId":"ch_work_nvlt_89","text":"《魏氏春秋同異》曰：鍾繇嬖庶子會之母，黜其夫人，文帝命繇复焉，繇恚忿，餐椒致禁，帝乃止。","sortOrder":94},
  {"id":"s_work_nvlt_89_95","chapterId":"ch_work_nvlt_89","text":"《世說》：石崇以椒為泥，泥屋，王君夫以赤石脂泥壁。","sortOrder":95},
  {"id":"s_work_nvlt_89_96","chapterId":"ch_work_nvlt_89","text":"《援神契》：椒薑御溫，蒲益聰。","sortOrder":96},
  {"id":"s_work_nvlt_89_97","chapterId":"ch_work_nvlt_89","text":"《博物志》曰：外國豉法，以酒浸，令極乾，以麻油蒸之，後曝三日，筛椒屑，以意多少合投之，胡椒酒方，以好酒五升，乾薑一兩，胡椒七十枚，末好石榴五枚，管收計［句有訛。］著中下氣。","sortOrder":97},
  {"id":"s_work_nvlt_89_98","chapterId":"ch_work_nvlt_89","text":"《毛詩》曰：貽我握椒，男女結情好也。","sortOrder":98},
  {"id":"s_work_nvlt_89_99","chapterId":"ch_work_nvlt_89","text":"《文選》曰：大王之風，徘徊椒桂之間。","sortOrder":99},
  {"id":"s_work_nvlt_89_100","chapterId":"ch_work_nvlt_89","text":"【頌】晉劉臻妻元日獻椒花頌曰：美哉靈葩，爰采爰獻，聖容映之，永寿於萬。","sortOrder":100},
  {"id":"s_work_nvlt_89_101","chapterId":"ch_work_nvlt_89","text":"蜀椒久服之，頭不白，令寒者熱，熱者輕，輕者重，出武都，赤色者，［按本條見本草經，末句下有脱文。］","sortOrder":101},
  {"id":"s_work_nvlt_89_102","chapterId":"ch_work_nvlt_89","text":"《離骚》：荃壁兮紫壇，芳椒兮成堂，［按此與上條，當移前藝類中。］","sortOrder":102},
  {"id":"s_work_nvlt_89_103","chapterId":"ch_work_nvlt_89","text":"【銘】晉成公綏椒華銘曰：嘉哉芳椒，載繁其實，厥味惟珍，蠲除百疾，肇惟歲始，月正元日，永介眉寿，以祈初吉。","sortOrder":103},
  {"id":"s_work_nvlt_89_104","chapterId":"ch_work_nvlt_89","text":"【贊】晉郭璞椒贊曰：椒之灌植，實繁有榛，薰林烈薄，馞其芬辛，服之不已，洞見通神。","sortOrder":104},
  {"id":"s_work_nvlt_89_106","chapterId":"ch_work_nvlt_89","text":"大傳曰：伯禽康叔見周公，三見而三笞，商子曰：二三子觀乎南山之陰，見梓，晉然實而俯，［晉，肅貌。］二子見商子，曰：梓者，子道也，二子入門而趨，登堂而跪，周公拂其首，勞而食之。","sortOrder":106},
  {"id":"s_work_nvlt_89_107","chapterId":"ch_work_nvlt_89","text":"《毛詩》曰：惟桑與梓，必恭敬止，椅桐梓漆，爰伐琴瑟，北山有梓。","sortOrder":107},
  {"id":"s_work_nvlt_89_108","chapterId":"ch_work_nvlt_89","text":"秋小葉复，［本條《太平御覽》九百五十八作爾雅曰楸小葉曰榎。］","sortOrder":108},
  {"id":"s_work_nvlt_89_109","chapterId":"ch_work_nvlt_89","text":"《左傳》曰：季孫為已树六槚於蒲圃東門之外，定姒薨，匠慶請蒲圃之槚以為榇，君子曰：多行無禮，必自及也。","sortOrder":109},
  {"id":"s_work_nvlt_89_110","chapterId":"ch_work_nvlt_89","text":"《禮斗威儀》曰：君乘火而王，其政和平，梓為常生。","sortOrder":110},
  {"id":"s_work_nvlt_89_111","chapterId":"ch_work_nvlt_89","text":"《爾雅》曰：楰，鼠梓。","sortOrder":111},
  {"id":"s_work_nvlt_89_112","chapterId":"ch_work_nvlt_89","text":"《史記》曰：子胥告其人曰：必树梓吾墓上。","sortOrder":112},
  {"id":"s_work_nvlt_89_113","chapterId":"ch_work_nvlt_89","text":"漢元帝初光年，皇後曾祖父濟南平陵王伯墓門梓柱，卒生枝葉，上屈，劉向以為王氏代漢之象，是王莽之歲。","sortOrder":113},
  {"id":"s_work_nvlt_89_114","chapterId":"ch_work_nvlt_89","text":"衛子夫入宮，歲餘不得見，涕泣請出，曰：吾昨夢子夫中庭生梓树，出非至告乎，［本條《太平御覽》九百五十八作漢武故事，出非至告乎作豈非天乎。］","sortOrder":114},
  {"id":"s_work_nvlt_89_115","chapterId":"ch_work_nvlt_89","text":"曹子建書曰：斬泗濱之梓，以為筝也。","sortOrder":115},
  {"id":"s_work_nvlt_89_117","chapterId":"ch_work_nvlt_89","text":"《春秋運斗枢》曰：椒桂合刚陽，［椒桂，陽星之精所生也，合猶連體而生也。］","sortOrder":117},
  {"id":"s_work_nvlt_89_118","chapterId":"ch_work_nvlt_89","text":"《山海經》曰：招搖之山，其上多桂，［桂長丈餘，味辛。］皋涂之山，上多桂木。","sortOrder":118},
  {"id":"s_work_nvlt_89_119","chapterId":"ch_work_nvlt_89","text":"桂木［《太平御覽》九百五十七作林。］八树，在贲隅東，［八树成林，言其大也，贲隅，番禺。］","sortOrder":119},
  {"id":"s_work_nvlt_89_120","chapterId":"ch_work_nvlt_89","text":"《禮斗威儀》曰：君乘金而王，其政訟平，芳桂常生。","sortOrder":120},
  {"id":"s_work_nvlt_89_121","chapterId":"ch_work_nvlt_89","text":"《春秋潛潭巴》曰：宮桂鳴，下土諸侯號有聲，［桂好木，植於宮中，猶天子封有聲譽者為諸侯，令(《太平御覽》九百五十七作今。)乃鳴，是乃成聲名於下土之祥也。］","sortOrder":121},
  {"id":"s_work_nvlt_89_122","chapterId":"ch_work_nvlt_89","text":"《楚辭》曰：桂棹兮蘭枻。又，桂棟兮蘭橑。","sortOrder":122},
  {"id":"s_work_nvlt_89_123","chapterId":"ch_work_nvlt_89","text":"又曰：結桂枝兮延佇。","sortOrder":123},
  {"id":"s_work_nvlt_89_124","chapterId":"ch_work_nvlt_89","text":"又，桂树丛生兮山之幽，偃蹇連卷兮枝相缭。","sortOrder":124},
  {"id":"s_work_nvlt_89_125","chapterId":"ch_work_nvlt_89","text":"又曰：麗桂树之冬榮。","sortOrder":125},
  {"id":"s_work_nvlt_89_126","chapterId":"ch_work_nvlt_89","text":"又曰：沛吾乘兮桂舟。","sortOrder":126},
  {"id":"s_work_nvlt_89_127","chapterId":"ch_work_nvlt_89","text":"《呂氏春秋》：伊尹說曰：物之美者，招搖之桂。","sortOrder":127},
  {"id":"s_work_nvlt_89_128","chapterId":"ch_work_nvlt_89","text":"《戰國策》曰：蘇秦謂楚王曰：楚國食貴於玉，薪貴於桂。","sortOrder":128},
  {"id":"s_work_nvlt_89_129","chapterId":"ch_work_nvlt_89","text":"《韓詩外傳》曰：宋玉因其友見楚襄王，襄王待之無以異，讓其友，其友曰：夫薑桂因地而生，不因地而辛，女因媒而嫁，不因媒而親。","sortOrder":129},
  {"id":"s_work_nvlt_89_130","chapterId":"ch_work_nvlt_89","text":"《列仙傳》曰：范蠡好食桂，飲水賣藥，人世世見之。","sortOrder":130},
  {"id":"s_work_nvlt_89_131","chapterId":"ch_work_nvlt_89","text":"又曰：桂父，象林人，常服桂皮葉，以龟腦和之。","sortOrder":131},
  {"id":"s_work_nvlt_89_132","chapterId":"ch_work_nvlt_89","text":"《漢書》：陆贾傳曰：尉他獻桂蠹二器，［桂树之蠹虫也。］","sortOrder":132},
  {"id":"s_work_nvlt_89_133","chapterId":"ch_work_nvlt_89","text":"《廣志》曰：桂出合浦，而生必於高山之巔，冬夏常青，其類自為林，間無雜树，交阯置桂園。","sortOrder":133},
  {"id":"s_work_nvlt_89_134","chapterId":"ch_work_nvlt_89","text":"《神仙傳》曰：離娄公服竹汁，餌桂得仙，許由父，箕山得丹石桂英，今在中嶽。","sortOrder":134},
  {"id":"s_work_nvlt_89_135","chapterId":"ch_work_nvlt_89","text":"《阚子》曰：魯人有好釣者，以桂為餌，黃金為鉤。","sortOrder":135},
  {"id":"s_work_nvlt_89_136","chapterId":"ch_work_nvlt_89","text":"《羅浮山記》曰：羅浮山顶有桂，《山海經》曰：所謂贲禺之桂。","sortOrder":136},
  {"id":"s_work_nvlt_89_137","chapterId":"ch_work_nvlt_89","text":"《臨海記》曰：石山望之如雪，山有湖，傳雲金鹅之所集，八桂之所植。","sortOrder":137},
  {"id":"s_work_nvlt_89_138","chapterId":"ch_work_nvlt_89","text":"《說文》曰：桂江南木，百藥之長。","sortOrder":138},
  {"id":"s_work_nvlt_89_139","chapterId":"ch_work_nvlt_89","text":"《爾雅》曰：梫，木桂，皮厚曰木桂，一树，［二字衍。］","sortOrder":139},
  {"id":"s_work_nvlt_89_140","chapterId":"ch_work_nvlt_89","text":"漢武帝悼李夫人賦曰：氣潛以凄戾兮，桂枝落而銷亡，神茕茕而遙鬼兮，精浮遊而去疆，淮南王安好道，感八公，共登山，少攀桂树，安作詩曰：攀桂树兮聊淹留。","sortOrder":140},
  {"id":"s_work_nvlt_89_141","chapterId":"ch_work_nvlt_89","text":"《異物志》曰：桂之灌生，必粹其族，柯葉不渝，冬夏常绿，匪桂植，［句有脱文。］在乎嵩嶽。","sortOrder":141},
  {"id":"s_work_nvlt_89_142","chapterId":"ch_work_nvlt_89","text":"《文選》曰：秋風生桂枝。","sortOrder":142},
  {"id":"s_work_nvlt_89_143","chapterId":"ch_work_nvlt_89","text":"又，蒼蒼山中桂，团团霜露色，桂枝生自直。","sortOrder":143},
  {"id":"s_work_nvlt_89_144","chapterId":"ch_work_nvlt_89","text":"又，桂树冬榮。","sortOrder":144},
  {"id":"s_work_nvlt_89_145","chapterId":"ch_work_nvlt_89","text":"吳都賦，丹桂灌丛。","sortOrder":145},
  {"id":"s_work_nvlt_89_146","chapterId":"ch_work_nvlt_89","text":"天台賦曰：八桂森挺以凌霜。","sortOrder":146},
  {"id":"s_work_nvlt_89_147","chapterId":"ch_work_nvlt_89","text":"桂椒信芳，而非園林之實。","sortOrder":147},
  {"id":"s_work_nvlt_89_148","chapterId":"ch_work_nvlt_89","text":"《山海經》曰：桂生南隅，拔萃岑嶺，廣熙葩陵，霜秀津穎，氣王百藥，森然雲挺，［按此郭璞桂贊，見下，重出應删。］","sortOrder":148},
  {"id":"s_work_nvlt_89_149","chapterId":"ch_work_nvlt_89","text":"庐山記曰：山有三石梁，廣不盈尺，俯盻者［《太平御覽》九百五十七作杳。］然無底，吳猛將弟子過此梁，見老翁坐桂树下，以玉杯承甘露與猛。","sortOrder":149},
  {"id":"s_work_nvlt_89_150","chapterId":"ch_work_nvlt_89","text":"《世說》曰：客問陳季方曰：足下家君太丘，有何功德，而荷天下重名，答曰：吾家君，譬如桂树生太山之阿，上有萬仞之高，下有不测之泉，上為甘露所霑，下為川泉所润，當斯之時，桂树焉知太山之高，川泉之深，不知有功德欤。","sortOrder":150},
  {"id":"s_work_nvlt_89_151","chapterId":"ch_work_nvlt_89","text":"莊子，桂可食，故斧伐之，夫人生天地之間，猶騁驷而過隙，然在用之，有盈箧爨之不足，食之則厭，一則令人用其身也，若爨之然，故曰不足，若用之於善，則與天地相弊。","sortOrder":151},
  {"id":"s_work_nvlt_89_152","chapterId":"ch_work_nvlt_89","text":"又，春華秋英名曰桂，［按本條尸子文，見下，重出應删。］","sortOrder":152},
  {"id":"s_work_nvlt_89_153","chapterId":"ch_work_nvlt_89","text":"《洞冥記》曰：酆過國，獻能言之龟，青玉匣，朔日惟桂露以飲之，置之於通風之器。","sortOrder":153},
  {"id":"s_work_nvlt_89_154","chapterId":"ch_work_nvlt_89","text":"甘泉宮南，有崑明，中有靈波殿，皆以桂為柱，風來自香，［明本本條作漢武故事，按今見三辅黃圖。］","sortOrder":154},
  {"id":"s_work_nvlt_89_155","chapterId":"ch_work_nvlt_89","text":"《拾遺記》曰：岱名［《太平御覽》九百五十七名字無，此衍。］舆一名浮折，北有玉梁千丈，駕玄流之上，峰旁有丹桂，墨紫白，可為舟。","sortOrder":155},
  {"id":"s_work_nvlt_89_156","chapterId":"ch_work_nvlt_89","text":"始皇起定明台，窮四方木，南得熛有碧，是，［句有脱文。］","sortOrder":156},
  {"id":"s_work_nvlt_89_157","chapterId":"ch_work_nvlt_89","text":"闇河之北，有紫桂成林，群仙餌焉，韓終采藥詩曰：闇河之桂，實大如粟，得而食之，後天而老。","sortOrder":157},
  {"id":"s_work_nvlt_89_158","chapterId":"ch_work_nvlt_89","text":"《離骚》曰：桂树列兮紛敷，吐紫花兮布條，實孤鸞之兩居，今集兮唯鴞。","sortOrder":158},
  {"id":"s_work_nvlt_89_159","chapterId":"ch_work_nvlt_89","text":"又曰：乘赤豹兮從文貍，華移車兮結桂旗。","sortOrder":159},
  {"id":"s_work_nvlt_89_160","chapterId":"ch_work_nvlt_89","text":"又曰：飲菌若之朝露兮，構桂木以為室。","sortOrder":160},
  {"id":"s_work_nvlt_89_161","chapterId":"ch_work_nvlt_89","text":"又曰：桂蠹不知所淹留兮，蓼虫不知死乎葵葉，葛藟累之於桂树，［喻小人在位。］","sortOrder":161},
  {"id":"s_work_nvlt_89_162","chapterId":"ch_work_nvlt_89","text":"《尸子》曰：春華秋英曰桂。","sortOrder":162},
  {"id":"s_work_nvlt_89_163","chapterId":"ch_work_nvlt_89","text":"《選》曰：青霞雜桂旗。","sortOrder":163},
  {"id":"s_work_nvlt_89_164","chapterId":"ch_work_nvlt_89","text":"又，桂棟留夏飆。","sortOrder":164},
  {"id":"s_work_nvlt_89_165","chapterId":"ch_work_nvlt_89","text":"又，矯菌桂以纫蕙。","sortOrder":165},
  {"id":"s_work_nvlt_89_166","chapterId":"ch_work_nvlt_89","text":"【詩】梁范雲詠桂詩曰：南中有八树，繁華無四時，不識風霜苦，安知零落期。","sortOrder":166},
  {"id":"s_work_nvlt_89_167","chapterId":"ch_work_nvlt_89","text":"梁庾肩吾詠桂树詩曰：新丛入望苑，舊幹別層城，倩视今移處，何如月里生。","sortOrder":167},
  {"id":"s_work_nvlt_89_168","chapterId":"ch_work_nvlt_89","text":"周王褒詠定林寺桂树詩曰：歲餘彫晚葉，年至長新围，月輪三五映，乌生八九飛。","sortOrder":168},
  {"id":"s_work_nvlt_89_169","chapterId":"ch_work_nvlt_89","text":"【贊】晉郭璞桂贊曰：桂生南裔，拔萃岑嶺，廣莫熙葩，凌霜津穎，氣王百藥，森然雲挺。","sortOrder":169},
  {"id":"s_work_nvlt_89_171","chapterId":"ch_work_nvlt_89","text":"《山海經》曰：黃帝殺蚩尤，弃其械，化為楓树。","sortOrder":171},
  {"id":"s_work_nvlt_89_172","chapterId":"ch_work_nvlt_89","text":"《離骚·招魂》曰：湛湛江水上有楓，目極千里傷春心。","sortOrder":172},
  {"id":"s_work_nvlt_89_173","chapterId":"ch_work_nvlt_89","text":"《晉宮閣名》曰：華林園楓香三株。","sortOrder":173},
  {"id":"s_work_nvlt_89_174","chapterId":"ch_work_nvlt_89","text":"《南方草木状》曰：楓香树，子大如鸭卵，二月華色，乃連著實，八九月熟，曝乾可燒，惟九真郡有之。","sortOrder":174},
  {"id":"s_work_nvlt_89_175","chapterId":"ch_work_nvlt_89","text":"《異苑》曰：乌傷陳氏，有女未醮，著屐遙上大楓树顛，了無危閡，顧曰：我應為神，今便長去，惟左蒼右黃，當蹔歸耳，家人悉出見之，舉手辭訣，於是飄耸輕越，極睇乃没，既不了蒼黃之意，每春辄以蒼狗，秋黃犬，設祀於树下。","sortOrder":175},
  {"id":"s_work_nvlt_89_176","chapterId":"ch_work_nvlt_89","text":"《爾雅》曰：楓，聂，［之枼反。］天風則鳴，故曰聂，聂树似白楊，葉圓而岐，有脂而香，今之楓者，［《太平御覽》九百五十七作今之楓香是。］","sortOrder":176},
  {"id":"s_work_nvlt_89_177","chapterId":"ch_work_nvlt_89","text":"山名見老［《太平御覽》九百五十七作名山記曰天姥六字，此有脱訛。］山上，長楓千餘丈，肅肅臨涧水。","sortOrder":177},
  {"id":"s_work_nvlt_89_178","chapterId":"ch_work_nvlt_89","text":"《周書》曰：渠州言鳳皇集於楓树，有乌列侍。","sortOrder":178},
  {"id":"s_work_nvlt_89_179","chapterId":"ch_work_nvlt_89","text":"【詩】梁簡文帝賦得詠疏楓詩曰：萎绿映青葭，疏紅分浪白，花葉洒行舟，仍持送遠客。","sortOrder":179},
  {"id":"s_work_nvlt_89_180","chapterId":"ch_work_nvlt_89","text":"◇豫章","sortOrder":180},
  {"id":"s_work_nvlt_89_181","chapterId":"ch_work_nvlt_89","text":"《左傳》曰：白公作亂，殺子西子期，豫章［《太平御覽》九百五十七作子期。］曰：昔者以力事君，不可以［御覽作不。］終，扶［御覽作抉，抉下有豫章二字，此誤竄上。］以殺人而後死。","sortOrder":181},
  {"id":"s_work_nvlt_89_182","chapterId":"ch_work_nvlt_89","text":"莊子，騰猿得事事，［《太平御覽》九百五十七作豫章。］攬蔓而生長其間，便也。","sortOrder":182},
  {"id":"s_work_nvlt_89_183","chapterId":"ch_work_nvlt_89","text":"陳留尉氏年树生迳中酸棗名朔［本條訛倒，不可句。］","sortOrder":183},
  {"id":"s_work_nvlt_89_184","chapterId":"ch_work_nvlt_89","text":"《淮南子》：豫章生七年可知，《荆州記》曰：山陽縣豫章木，径可伐作鼓顙，顙成，便取奔去。","sortOrder":184},
  {"id":"s_work_nvlt_89_185","chapterId":"ch_work_nvlt_89","text":"◇無患","sortOrder":185},
  {"id":"s_work_nvlt_89_186","chapterId":"ch_work_nvlt_89","text":"纂文曰：無患，木名也，實可以去垢，核黑如{殹土}。","sortOrder":186},
  {"id":"s_work_nvlt_89_187","chapterId":"ch_work_nvlt_89","text":"問［本條《太平御覽》九百五十九作崔豹古今註程雅問，此脱書名。］栌木曰無患何也，答曰：昔有神巫曰無患，［御覽作実毦。］此木［二字御覽無。］能作符劾百鬼，則以此木為棒殺之，世人相傳以此木為眾鬼所惡，競取為器，用以厭鬼，故號無患。","sortOrder":187},
  {"id":"s_work_nvlt_89_188","chapterId":"ch_work_nvlt_89","text":"【贊】齊卞敬宗無患枕贊曰：爰茲素朴，名為吉始，匠人斯製，以獻君子。","sortOrder":188},
  {"id":"s_work_nvlt_89_189","chapterId":"ch_work_nvlt_89","text":"◇朱树","sortOrder":189},
  {"id":"s_work_nvlt_89_190","chapterId":"ch_work_nvlt_89","text":"《世說》曰：朱，松柏屬，故類朱赤公也，［句有訛。］","sortOrder":190},
  {"id":"s_work_nvlt_89_191","chapterId":"ch_work_nvlt_89","text":"《山海經》曰：崑崙山上有朱树。","sortOrder":191},
  {"id":"s_work_nvlt_89_192","chapterId":"ch_work_nvlt_89","text":"◇君子","sortOrder":192},
  {"id":"s_work_nvlt_89_193","chapterId":"ch_work_nvlt_89","text":"晉宮閣記曰：華林園中，有君子树三株。","sortOrder":193},
  {"id":"s_work_nvlt_89_195","chapterId":"ch_work_nvlt_89","text":"《爾雅》曰：枞松葉柏身曰枞。","sortOrder":195},
  {"id":"s_work_nvlt_89_196","chapterId":"ch_work_nvlt_89","text":"《尸子》曰：松柏之鼠，不知堂密之有美枞。","sortOrder":196},
  {"id":"s_work_nvlt_89_197","chapterId":"ch_work_nvlt_89","text":"魯連子曰：松枞高千仞而無枝，非夏王室無柱。","sortOrder":197},
  {"id":"s_work_nvlt_89_199","chapterId":"ch_work_nvlt_89","text":"《尚書》曰：杶幹栝柏。","sortOrder":199},
  {"id":"s_work_nvlt_89_200","chapterId":"ch_work_nvlt_89","text":"《爾雅》曰：柏葉松身曰桧。","sortOrder":200},
  {"id":"s_work_nvlt_89_201","chapterId":"ch_work_nvlt_89","text":"祀應記曰：孔子廟列七碑，無象，桧柏猶茂，西北二里，有顏母廟，廟象猶嚴，有脩，［句有脱文。］","sortOrder":201},
  {"id":"s_work_nvlt_89_202","chapterId":"ch_work_nvlt_89","text":"◇茱萸","sortOrder":202},
  {"id":"s_work_nvlt_89_203","chapterId":"ch_work_nvlt_89","text":"《說文》曰：榝似茱萸，出淮南。","sortOrder":203},
  {"id":"s_work_nvlt_89_204","chapterId":"ch_work_nvlt_89","text":"《風土記》曰：茱萸，榝也，九月九日熟，色赤，可采時也。","sortOrder":204},
  {"id":"s_work_nvlt_89_205","chapterId":"ch_work_nvlt_89","text":"洞林曰：郭璞避難至新息，有以茱萸令璞射之，璞曰：子如赤鈴含玄珠，案文言之是茱萸。","sortOrder":205},
  {"id":"s_work_nvlt_89_206","chapterId":"ch_work_nvlt_89","text":"《異苑》曰：庾紹為湘東郡，亡，宗协與紹中表，且服茱萸酒，忽見紹來，仍求酒，執酒柸還置，雲有茱萸氣，协雲，惡之耶，紹雲，上官皆畏之，况我乎。","sortOrder":206},
  {"id":"s_work_nvlt_89_207","chapterId":"ch_work_nvlt_89","text":"荆楚記曰：九月九日，佩茱萸，食蓬餌，飲菊花酒，令人長寿。","sortOrder":207},
  {"id":"s_work_nvlt_89_208","chapterId":"ch_work_nvlt_89","text":"續齊諧記曰：汝南桓景，隨費長房遊學，謂之曰：九月九日，汝南當有灾厄，急令家人縫囊，盛茱萸系臂，登山飲菊酒，此禍可消，景如其言，舉家上山，夕還，見雞犬一時暴死，長房曰：此可代之，今人九月九日登高是也。","sortOrder":208},
  {"id":"s_work_nvlt_89_209","chapterId":"ch_work_nvlt_89","text":"《離骚》曰：椒专佞以慢諂兮，榝又充其佩帏。","sortOrder":209},
  {"id":"s_work_nvlt_89_210","chapterId":"ch_work_nvlt_89","text":"【賦】晉孫楚茱萸賦曰：有茱萸之嘉木，植茅茨之前庭，歷漢女而始育，關百載而長生，森蔓延以盛興，布绿葉於紫茎，鶉火西徂，白藏授節，零露既凝，鷹隼飄厲，攀紫房於纖柯，缀朱實之酷烈，應神農之本草，療生民之疹疾。","sortOrder":210},
  {"id":"s_work_nvlt_89_212","chapterId":"ch_work_nvlt_89","text":"《莊子》曰：騰猿得杉柟，攬蔓枝而生長其間，得便也。","sortOrder":212},
  {"id":"s_work_nvlt_89_213","chapterId":"ch_work_nvlt_89","text":"《山海經》曰：搖碧山，朝歌山，脆山，多柟。","sortOrder":213},
  {"id":"s_work_nvlt_89_214","chapterId":"ch_work_nvlt_89","text":"負霜停翠。","sortOrder":214},
  {"id":"s_work_nvlt_89_216","chapterId":"ch_work_nvlt_89","text":"《詩》曰：陟彼高岗，折其柞薪，其葉湒兮，維柞之枝，其葉蓬蓬，疏，栩今柞，壳為斗，可以染皂，今俗及河內雲杼斗，或橡斗。","sortOrder":216},
  {"id":"s_work_nvlt_89_217","chapterId":"ch_work_nvlt_89","text":"《爾雅》栩，杼。","sortOrder":217},
  {"id":"s_work_nvlt_89_218","chapterId":"ch_work_nvlt_89","text":"《漢書》：五柞宮。","sortOrder":218},
  {"id":"s_work_nvlt_89_219","chapterId":"ch_work_nvlt_89","text":"風土［《太平御覽》九百五十八作周處風土記。］舜所耕多柞树。","sortOrder":219},
  {"id":"s_work_nvlt_89_220","chapterId":"ch_work_nvlt_89","text":"瑟彼柞棫，民所燎矣，柞棫佩矣。","sortOrder":220},
  {"id":"s_work_nvlt_89_222","chapterId":"ch_work_nvlt_89","text":"瑞楸梓常生，［按本條有脱訛，御覽九百五十八作禮斗威儀。］","sortOrder":222},
  {"id":"s_work_nvlt_89_223","chapterId":"ch_work_nvlt_89","text":"潘嶽懷舊賦，望彼楸矣，感於餘思。","sortOrder":223},
  {"id":"s_work_nvlt_89_224","chapterId":"ch_work_nvlt_89","text":"別賦，望青楸之離霜。","sortOrder":224},
  {"id":"s_work_nvlt_89_225","chapterId":"ch_work_nvlt_89","text":"陳思王詩曰：走馬長楸間。","sortOrder":225},
  {"id":"s_work_nvlt_89_226","chapterId":"ch_work_nvlt_89","text":"漢［《太平御覽》九百五十八作漢書。］淮北滎南河齊之間千树楸與千戶侯等。","sortOrder":226},
  {"id":"s_work_nvlt_89_227","chapterId":"ch_work_nvlt_89","text":"小居千重之［按本條有脱訛，不可句。］","sortOrder":227},
  {"id":"s_work_nvlt_89_229","chapterId":"ch_work_nvlt_89","text":"疏，周秦謂柞為櫟，河南謂蓼為櫟。","sortOrder":229},
  {"id":"s_work_nvlt_89_230","chapterId":"ch_work_nvlt_89","text":"《爾雅》曰：其實梂椒之屬，其子房生為梂，［具菊。］","sortOrder":230},
  {"id":"s_work_nvlt_89_231","chapterId":"ch_work_nvlt_89","text":"莊子，匠石之齊，至曲園，見社树，曰：是不才，故若是之寿，杜見夢曰：若此文木也，楂梨橘柚之屬邪，熟則剝，故不終天年。","sortOrder":231},
  {"id":"s_work_nvlt_89_232","chapterId":"ch_work_nvlt_89","text":"◇楛［音戶，切雲木中矢。］","sortOrder":232},
  {"id":"s_work_nvlt_89_233","chapterId":"ch_work_nvlt_89","text":"楛，荆楚中貢簵楛。","sortOrder":233},
  {"id":"s_work_nvlt_89_234","chapterId":"ch_work_nvlt_89","text":"疏，上党人篾以為箱器，屋［《太平御覽》九百五十九作屈。］以為釵，調問婦人，欲质赭不，竈中自有黃土，買釵不，山中自有楛矢，［具前。］","sortOrder":234},
  {"id":"s_work_nvlt_89_235","chapterId":"ch_work_nvlt_89","text":"《詩》曰：瞻彼旱麓，榛楛濟濟。","sortOrder":235},
  {"id":"s_work_nvlt_89_236","chapterId":"ch_work_nvlt_89","text":"《選》曰：彼榛楛之勿箭，［《太平御覽》九百五十九作剪。］亦蒙榮於集萃。","sortOrder":236},
  {"id":"s_work_nvlt_89_237","chapterId":"ch_work_nvlt_89","text":"◇靈寿","sortOrder":237},
  {"id":"s_work_nvlt_89_238","chapterId":"ch_work_nvlt_89","text":"漢哀帝賜霍［本條《太平御覽》九百五十九作《漢書》：霍作孔，此訛。］光靈寿杖。","sortOrder":238},
  {"id":"s_work_nvlt_89_239","chapterId":"ch_work_nvlt_89","text":"◇女貞","sortOrder":239},
  {"id":"s_work_nvlt_89_240","chapterId":"ch_work_nvlt_89","text":"《山海經》曰：太山多貞木。","sortOrder":240},
  {"id":"s_work_nvlt_89_241","chapterId":"ch_work_nvlt_89","text":"鄭氏婚禮謁文贊曰：女貞之树，柯葉冬生，寒涼守節，险不能傾。","sortOrder":241},
  {"id":"s_work_nvlt_89_242","chapterId":"ch_work_nvlt_89","text":"典術曰：女貞木者，少陰之精，冬葉不落。","sortOrder":242},
  {"id":"s_work_nvlt_89_243","chapterId":"ch_work_nvlt_89","text":"《晉宮閣名》曰：華林園女貞一株。","sortOrder":243},
  {"id":"s_work_nvlt_89_244","chapterId":"ch_work_nvlt_89","text":"【頌】晉蘇彦女貞頌曰：昔東阿王作楊柳頌，辭義慷恺，旨在其中，餘今為女貞頌，雖事異於往作，蓋亦以厲冶容之風也，女貞之树，一名冬生，負霜葱翠，振柯凌風，故清士钦其质，而貞女慕其名，或树之於雲堂，或植之於階庭。","sortOrder":244},
  {"id":"s_work_nvlt_89_245","chapterId":"ch_work_nvlt_89","text":"◇長生","sortOrder":245},
  {"id":"s_work_nvlt_89_246","chapterId":"ch_work_nvlt_89","text":"《洛陽宮殿簿》曰：明光殿前，長生二株，含章殿前，長生一株。","sortOrder":246},
  {"id":"s_work_nvlt_89_247","chapterId":"ch_work_nvlt_89","text":"《晉宮閣名》曰：華林園長生六株，萬年殿前，長生二株。","sortOrder":247},
  {"id":"s_work_nvlt_89_248","chapterId":"ch_work_nvlt_89","text":"《鄴中記》曰：金華殿後，有皇後浴室，种双長生树，枝條交於棟上，团团車蓋形，冬日不彫，葉大如掌，至八九月乃生華，華色白，子赤，大如橡子，不中啖也，世人謂之西王母長生树。","sortOrder":248},
  {"id":"s_work_nvlt_89_249","chapterId":"ch_work_nvlt_89","text":"【賦】晉嵇含長生树賦曰：餘婴丁闵凶，靡所定居，老母垂聖善之訓，以為生事愛敬，没則無改，宜居墓次，瞻奉威靈，兼覽藝文，可以不殒先軌，祗奉慈令，遂家於墳左，扫除壇封，种植松柏，松柏之下，不滋非類之草，猥有長生，育於域內，豈老母至行，表徵於嘉木哉，美我親之仁孝，固徵瑞之必招，降祖宗之遺德，振奇木之青條，結根擢幹，載生無漸，弱茎猗猗，绿葉冉冉，處陰冬而愈茂，豈茎葉之有點，感自然以旌賢，谅有道之不掩。","sortOrder":249},
  {"id":"s_work_nvlt_89_250","chapterId":"ch_work_nvlt_89","text":"◇木槿","sortOrder":250},
  {"id":"s_work_nvlt_89_251","chapterId":"ch_work_nvlt_89","text":"《爾雅》曰：椵，木槿，榇，木槿，［別二名也，似李树，花朝生夕落，可食也。］","sortOrder":251},
  {"id":"s_work_nvlt_89_252","chapterId":"ch_work_nvlt_89","text":"《說文》曰：舜，木槿也，朝華暮落。","sortOrder":252},
  {"id":"s_work_nvlt_89_253","chapterId":"ch_work_nvlt_89","text":"《廣志》曰：日及，木槿也。","sortOrder":253},
  {"id":"s_work_nvlt_89_254","chapterId":"ch_work_nvlt_89","text":"《毛詩》曰：有女同車，顏如舜華，［木槿也。］","sortOrder":254},
  {"id":"s_work_nvlt_89_255","chapterId":"ch_work_nvlt_89","text":"《禮記》曰：仲夏之月，木槿榮。","sortOrder":255},
  {"id":"s_work_nvlt_89_256","chapterId":"ch_work_nvlt_89","text":"《成相篇》曰：莊子貴支離，悲木槿，［成相，淮南王所作也。］","sortOrder":256},
  {"id":"s_work_nvlt_89_257","chapterId":"ch_work_nvlt_89","text":"晉宮閣名曰：華林園有三株。","sortOrder":257},
  {"id":"s_work_nvlt_89_258","chapterId":"ch_work_nvlt_89","text":"《外國圖》曰：君子之國，多木槿之華，人民食之，去琅耶三萬里。","sortOrder":258},
  {"id":"s_work_nvlt_89_259","chapterId":"ch_work_nvlt_89","text":"《玄中記》曰：君子之國，地方千里，多木槿之華。","sortOrder":259},
  {"id":"s_work_nvlt_89_260","chapterId":"ch_work_nvlt_89","text":"《羅浮山記》曰：木槿一名赤槿，華甚丹，四時敷榮。","sortOrder":260},
  {"id":"s_work_nvlt_89_261","chapterId":"ch_work_nvlt_89","text":"【賦】晉盧諶朝華賦曰：覽庭隅之嘉永，莫朝華之可玩，俯浸润之泉壤，仰晞影於雲漢，晉傅鹹舜華賦曰：佳其日新之美，故种之前庭而為之賦，覽中唐之奇树，禀冲氣之至清，應青春而敷孽，逮朱夏而誕英，布夭夭之纖枝，發灼灼之殊榮，紅葩紫蒂，翠葉素茎，含暉吐曜，烂若列星，朝陽照灼以舒暉，逸藻采粲而光明，罄天壤而莫俪，何菱華之足營。","sortOrder":261},
  {"id":"s_work_nvlt_89_262","chapterId":"ch_work_nvlt_89","text":"晉羊徽木槿賦曰：有木槿之初榮，藻眾林而間色，在青春而資氣，逮中夏以呈飾，挹宵露以舒采，暉晨景而吸赩。","sortOrder":262},
  {"id":"s_work_nvlt_89_263","chapterId":"ch_work_nvlt_89","text":"晉夏侯湛朝華賦曰：咨神树之脩異，寔積陽之純精，蜿潛根以誕節，據川壤以擢茎，皎日升而朝華，玄景逝而夕零，逮明晨而繁沸，若靜夜之眾星，長茎欑起，柔條列布，濯靈柯於時雨，滋逸采於丰露，灼煌煌以煒煒，獨崇朝而達暮，於是茂树蒼蒼，纖枝翩翩，潛光玉朗，绿葉翠鮮。","sortOrder":263},
  {"id":"s_work_nvlt_89_264","chapterId":"ch_work_nvlt_89","text":"隋江總南越木槿賦曰：日及多名，蕤賓肇生，東方記乎夕死，郭璞贊以朝榮，潘文體其夏盛，嵇賦悯其秋零，此則京華之麗木，非於越之舜英，南中斬草，眾花之寶，雅什未名，骚人失藻，雨來翠润，露歇紅燥，叠萼疑檠，低茎若倒，朝霞映日殊未研，珊瑚照水定非鮮，千葉芙蓉詎相似，百枝燈花复羞燃，蹔欲寄根對沧海，大原移華廁綺錢，井上桃虫難可雜，庭中桂蠹豈見怜，乃為歌曰：啼妆梁冀婦，紅妆荡子家，若持花併笑，宜笑不勝花，趙女垂金珥，燕姬插寶珈，誰知紅槿艳，無因寄狹邪，徒令萬里道，攀折自咨嗟。","sortOrder":264},
  {"id":"s_work_nvlt_89_265","chapterId":"ch_work_nvlt_89","text":"【頌】宋顏延之赤槿頌曰：日御北至，夏德南宣，玉蒸榮心，氣動上玄，華繅間物，受色朱天，是謂珍树，含艳丹間。","sortOrder":265},
  {"id":"s_work_nvlt_89_266","chapterId":"ch_work_nvlt_89","text":"【序】晉蘇彦舜華詩序曰：其為花也，色甚鮮麗，迎晨而榮，日中則衰，至夕而零，莊周載朝菌不知晦朔，况此朝不及夕者乎，苟映采於一朝，燿穎於當時，焉識夭寿之所在哉，餘既玩其葩，而叹其榮不終日。","sortOrder":266},
  {"id":"s_work_nvlt_89_267","chapterId":"ch_work_nvlt_89","text":"晉傅玄朝華賦序曰：朝華，麗木也，晉成公綏日及賦序曰：日及者，華甚鮮茂，榮於仲春，訖於孟秋。","sortOrder":267},
  {"id":"s_work_nvlt_89_268","chapterId":"ch_work_nvlt_89","text":"晉潘尼朝菌賦序曰：朝菌者，蓋朝華而暮落，世謂之木槿，或謂之日及，詩人以為舜華，宣尼以為朝菌，其物向晨而結，逮明而布，見陽而盛，終日而殒，不以其異乎，何名之多也。","sortOrder":268},
  {"id":"s_work_nvlt_89_269","chapterId":"ch_work_nvlt_89","text":"晉嵇含朝生暮落树賦序曰：草木春榮秋悴，此树朝生暮落。","sortOrder":269},
  {"id":"s_work_nvlt_89_270","chapterId":"ch_work_nvlt_89","text":"【書】東方朔與丞相公孫弘借車馬書曰：木槿夕死朝榮，士亦不長貧也。","sortOrder":270},
  {"id":"s_work_nvlt_89_272","chapterId":"ch_work_nvlt_89","text":"《詩》曰：蔽芾其樗。","sortOrder":272},
  {"id":"s_work_nvlt_89_273","chapterId":"ch_work_nvlt_89","text":"又，山有栳，［栳，山樗。］","sortOrder":273},
  {"id":"s_work_nvlt_89_274","chapterId":"ch_work_nvlt_89","text":"又，南山有樗。","sortOrder":274},
  {"id":"s_work_nvlt_89_275","chapterId":"ch_work_nvlt_89","text":"惠子曰：［本條《太平御覽》九百五十九引作莊子，此脱書名。］吾有大树，人謂之樗，其本擁肿，不中繩，小枝拳曲，不中規矩，至於逢匠者不顧，今子之言，大而無用，眾所同去，子曰：何不树之於無何之乡，廣莫之野，逍遙乎寢臥之下。","sortOrder":275},
  {"id":"s_work_nvlt_89_276","chapterId":"ch_work_nvlt_89","text":"◇木蘭","sortOrder":276},
  {"id":"s_work_nvlt_89_277","chapterId":"ch_work_nvlt_89","text":"《離骚》曰：朝搴阰之木蘭，［搴，取也，阰，山名也。］","sortOrder":277},
  {"id":"s_work_nvlt_89_278","chapterId":"ch_work_nvlt_89","text":"《古今註》曰：孝哀帝元嘉元年，芝生後庭木蘭树上。","sortOrder":278},
  {"id":"s_work_nvlt_89_279","chapterId":"ch_work_nvlt_89","text":"《神仙傳》曰：北海於君病癩，見市有賣藥，姓公孫帛，因問之，公曰：明日木蘭树下當教卿，明日往，授素書二卷，以消灾救病，無不愈者。","sortOrder":279},
  {"id":"s_work_nvlt_89_280","chapterId":"ch_work_nvlt_89","text":"《洛陽宮殿簿》曰：顯陽殿前，有木蘭二株。","sortOrder":280},
  {"id":"s_work_nvlt_89_281","chapterId":"ch_work_nvlt_89","text":"《晉宮閣名》曰：華林園木蘭四株。","sortOrder":281},
  {"id":"s_work_nvlt_89_282","chapterId":"ch_work_nvlt_89","text":"戴延之《西征記》曰：顯陽殿前有木蘭。","sortOrder":282},
  {"id":"s_work_nvlt_89_283","chapterId":"ch_work_nvlt_89","text":"【賦】晉成公綏木蘭賦曰：許昌西園中木蘭树，餘往觀之，遂為賦曰：覽眾树之列植，嘉木蘭之殊觀，至於玄冥授節，猛寒嚴烈，峨峨堅冰，霏霏白雪，木應霜而枯零，草隨風而摧折，顧青翠之茂葉，繁旖旎之弱條，谅抗節而矯時，獨滋茂而不雕。","sortOrder":283},
  {"id":"s_work_nvlt_89_284","chapterId":"ch_work_nvlt_89","text":"◇夫栘","sortOrder":284},
  {"id":"s_work_nvlt_89_285","chapterId":"ch_work_nvlt_89","text":"《爾雅》曰：唐棣，栘，［似白楊，江東呼夫栘。］","sortOrder":285},
  {"id":"s_work_nvlt_89_286","chapterId":"ch_work_nvlt_89","text":"《詩》曰：何彼秾矣，唐棣之華。","sortOrder":286},
  {"id":"s_work_nvlt_89_287","chapterId":"ch_work_nvlt_89","text":"又，山有苞棣。","sortOrder":287},
  {"id":"s_work_nvlt_89_288","chapterId":"ch_work_nvlt_89","text":"六月食鬱及薁，［薁，夫栘也，音鬱。］","sortOrder":288},
  {"id":"s_work_nvlt_89_289","chapterId":"ch_work_nvlt_89","text":"夫栘，燕兄弟也，闵管蔡之失道，夫栘之華，萼不煒煒，凡今之人，莫如兄弟。","sortOrder":289},
  {"id":"s_work_nvlt_89_290","chapterId":"ch_work_nvlt_89","text":"《禮記疏》曰：夫栘一名薁李，一名鬱梅，一名車下李，一名鬱。","sortOrder":290},
  {"id":"s_work_nvlt_89_291","chapterId":"ch_work_nvlt_89","text":"◇橚［音肅，木也。］","sortOrder":291},
  {"id":"s_work_nvlt_89_292","chapterId":"ch_work_nvlt_89","text":"《晏子春秋》曰：景公登青堂，見斷橚淮門者，令誅之，晏子諫曰：前冕旒，惡多見也，黈纊塞耳，惡多聞也，人君自生其民，公曰：趨舍之。","sortOrder":292},
  {"id":"s_work_nvlt_89_293","chapterId":"ch_work_nvlt_89","text":"◇若木","sortOrder":293},
  {"id":"s_work_nvlt_89_294","chapterId":"ch_work_nvlt_89","text":"《山海經》曰：灰野之山，有赤树青葉，名曰若木，［生崑崙西附西極，其光華赤炤下也。］","sortOrder":294},
  {"id":"s_work_nvlt_89_295","chapterId":"ch_work_nvlt_89","text":"《離骚》曰：折若木以拂日，《淮南子》曰：若木在建木西，上有十日，其華照下地。","sortOrder":295},
  {"id":"s_work_nvlt_89_296","chapterId":"ch_work_nvlt_89","text":"【贊】晉郭璞若木贊曰：若木之生，崑山是濱，朱華電照，碧葉玉津，食之靈智，為力為仁。","sortOrder":296},
  {"id":"s_work_nvlt_89_297","chapterId":"ch_work_nvlt_89","text":"◇合歡","sortOrder":297},
  {"id":"s_work_nvlt_89_298","chapterId":"ch_work_nvlt_89","text":"《本草經》曰：合歡，味甘平，生川穀，安五臟，和心志，令人歡樂無忧，久服輕身明目，生益州。","sortOrder":298},
  {"id":"s_work_nvlt_89_299","chapterId":"ch_work_nvlt_89","text":"仲長統《昌言》曰：漢哀帝時，有異物生於長樂宮東庑柏树，及永巷南闼合歡树，議者以為芝草也，群臣皆贺受賜，《古今註》曰：知蠲人之忿，則赠以青囊，［《太平御覽》九百六十作裳。］三［御覽作一。］名合歡，則忘忿，枝葉若繁互相交結，每一風來，辄自相解，不相牵缀，嵇康种之舍前。","sortOrder":299},
  {"id":"s_work_nvlt_89_300","chapterId":"ch_work_nvlt_89","text":"《晉宮閣名》曰：華林園合歡四株。","sortOrder":300},
  {"id":"s_work_nvlt_89_301","chapterId":"ch_work_nvlt_89","text":"【詩】晉楊方合歡詩曰：南鄰有奇树，承春挺素華，丰翘被長條，绿葉蔽朱柯，因風吐微音，芳氣入紫霞，我心羨此木，原徙著餘家，夕得遊其下，朝得弄其葩，爾根深且固，餘宅淺且洿，移植良無期，叹息將如何。","sortOrder":301},
  {"id":"s_work_nvlt_89_303","chapterId":"ch_work_nvlt_89","text":"《爾雅》曰：披，煔，［今之杉木。］","sortOrder":303},
  {"id":"s_work_nvlt_89_304","chapterId":"ch_work_nvlt_89","text":"晉鹹康《起居註》曰：侍御史秦武，奏平陵前道東杉树一株萎死，以備預柏栽補之，請收陵令推劾。","sortOrder":304},
  {"id":"s_work_nvlt_89_305","chapterId":"ch_work_nvlt_89","text":"邓德明《南康記》曰：南野巘山，有漢太傅陳蕃，［《太平御覽》九百五十七蕃下有墓字］遙望兩杉树，耸柯出嶺，垂荫覆穀。","sortOrder":305},
  {"id":"s_work_nvlt_89_306","chapterId":"ch_work_nvlt_89","text":"劉欣期交州記曰：合浦東一百里，有一杉树，葉落，隨風入洛陽城內，漢時善相者，雲此休徵，當出王者，故遣二人伐树，役夫多死，三百人坐株上食，過足相容。","sortOrder":306},
  {"id":"s_work_nvlt_89_307","chapterId":"ch_work_nvlt_89","text":"《居名山志》曰：華子岗上，紫杉千仞，被在崖侧。","sortOrder":307},
  {"id":"s_work_nvlt_89_308","chapterId":"ch_work_nvlt_89","text":"又雲，金州山西面杉疏，偏為白猿所凶，竟夕哀鳴，行人所惡。","sortOrder":308},
  {"id":"s_work_nvlt_89_309","chapterId":"ch_work_nvlt_89","text":"【頌】梁江淹杉頌曰：桐梓舊麗，松括稱奇，焉如茲品，獨秀青崖，群木斂望，雜卉不闚，長入煙氛，永驂鸞螭。","sortOrder":309},
  {"id":"s_work_nvlt_89_310","chapterId":"ch_work_nvlt_89","text":"◇併闾","sortOrder":310},
  {"id":"s_work_nvlt_89_311","chapterId":"ch_work_nvlt_89","text":"《廣雅》曰：併闾，椶也。","sortOrder":311},
  {"id":"s_work_nvlt_89_312","chapterId":"ch_work_nvlt_89","text":"《山海經》曰：脆之山，其木多椶，［椶树高二丈許，無枝條，葉大而員，岐生枝頭，美實，皮相重被，一行一皮者為一節，可為索也。］","sortOrder":312},
  {"id":"s_work_nvlt_89_313","chapterId":"ch_work_nvlt_89","text":"《廣志》曰：椶一名併闾，葉似車輪，乃在顛下，有皮纏之，附地起，二旬一采，轉复上生。","sortOrder":313},
  {"id":"s_work_nvlt_89_314","chapterId":"ch_work_nvlt_89","text":"吳錄《地理志》曰：武陵臨沅縣，多併闾木，生山中。","sortOrder":314},
  {"id":"s_work_nvlt_89_315","chapterId":"ch_work_nvlt_89","text":"《晉令》曰：其夷民守護椶皮者，一身不输。","sortOrder":315},
  {"id":"s_work_nvlt_89_316","chapterId":"ch_work_nvlt_89","text":"【頌】梁江淹併闾頌曰：異木之生，疑竹疑草，攒丛石迳，森苁山道，煙岫相珍，雲壑共寶，不錦不縟，何避工巧。","sortOrder":316},
  {"id":"s_work_nvlt_89_318","chapterId":"ch_work_nvlt_89","text":"《春秋運斗枢》曰：玉衡星散為荆。","sortOrder":318},
  {"id":"s_work_nvlt_89_319","chapterId":"ch_work_nvlt_89","text":"《廣志》曰：楚，荆也，牡荆，蔓荆也。","sortOrder":319},
  {"id":"s_work_nvlt_89_320","chapterId":"ch_work_nvlt_89","text":"《廣志》曰：赤茎大實者，名曰牡荆。又有山荆。","sortOrder":320},
  {"id":"s_work_nvlt_89_321","chapterId":"ch_work_nvlt_89","text":"《左傳》曰：伍舉入鄭，聲子將如晉，遇之於鄭郊，班荆相與食，而言复故，［布荆坐地，共議歸楚。］","sortOrder":321},
  {"id":"s_work_nvlt_89_322","chapterId":"ch_work_nvlt_89","text":"《漢書》曰：淮南王安謀反，伍被諫曰：昔子胥諫吳王雲，臣今見麋鹿遊姑蘇之台，臣今亦將見宮中生荆棘，露沾衣也。","sortOrder":322},
  {"id":"s_work_nvlt_89_323","chapterId":"ch_work_nvlt_89","text":"《東觀漢記》曰：尹勤治韓詩，事薛漢，身牧豕，事親至孝，無有交遊，門生荆棘。","sortOrder":323},
  {"id":"s_work_nvlt_89_324","chapterId":"ch_work_nvlt_89","text":"周景式《孝子傳》曰：古有兄弟，忽欲分異，出門見三荆同株，接葉連陰，叹曰：木猶欣聚，况我而殊哉，還為雍和。","sortOrder":324},
  {"id":"s_work_nvlt_89_325","chapterId":"ch_work_nvlt_89","text":"《神仙傳》曰：吳有徐隨，居丹徒，左慈過隋，門下有宿客車六七乘，欺慈，雲徐公不在，慈去，客皆見牛在楊树杪，車轂中皆生荆木，長一二丈，客懼，入報隋，隋曰：此左公，遣追之，客逐慈，叩頭謝，客還，見牛故在地，無复荆木也。","sortOrder":325},
  {"id":"s_work_nvlt_89_326","chapterId":"ch_work_nvlt_89","text":"顧微《廣州記》曰：撫納縣出金荆。","sortOrder":326},
  {"id":"s_work_nvlt_89_327","chapterId":"ch_work_nvlt_89","text":"《禮》弓矢圖：楚燩以荆為之，然以灼，正以荆者，凡木心圓，荆心方也。","sortOrder":327},
  {"id":"s_work_nvlt_89_328","chapterId":"ch_work_nvlt_89","text":"《廣州記》曰：白荆堪為履，紫荆堪為床。","sortOrder":328},
  {"id":"s_work_nvlt_89_329","chapterId":"ch_work_nvlt_89","text":"萬南［《太平御覽》九百五十九作淮南萬畢術。］杜［御覽作牡。］荆指病自愈，節不相當者，月晕時剋之，養病。","sortOrder":329},
  {"id":"s_work_nvlt_89_330","chapterId":"ch_work_nvlt_89","text":"《毛詩》曰：翘翘错薪，言刈其楚，［楚，荆也。］","sortOrder":330},
  {"id":"s_work_nvlt_89_331","chapterId":"ch_work_nvlt_89","text":"又曰：楊之水，不流束楚。","sortOrder":331},
  {"id":"s_work_nvlt_89_332","chapterId":"ch_work_nvlt_89","text":"又曰：綢缪束楚。","sortOrder":332},
  {"id":"s_work_nvlt_89_333","chapterId":"ch_work_nvlt_89","text":"又曰：交交黃鳥，止於楚。","sortOrder":333},
  {"id":"s_work_nvlt_89_334","chapterId":"ch_work_nvlt_89","text":"《老子》曰：師之所處，荆棘生焉。","sortOrder":334},
  {"id":"s_work_nvlt_89_335","chapterId":"ch_work_nvlt_89","text":"《文選》曰：不別荆者，慶雲之惠君也，荒鬱萧森，參天榛之蒙籠。","sortOrder":335},
  {"id":"s_work_nvlt_89_336","chapterId":"ch_work_nvlt_89","text":"《史記》曰：廉頗肉袒負荆，因賓客，至蔺相如門謝。","sortOrder":336},
  {"id":"s_work_nvlt_89_337","chapterId":"ch_work_nvlt_89","text":"【詩】晉陆機樂府歌詩曰：三荆歡同株，四鳥悲異林。","sortOrder":337},
  {"id":"s_work_nvlt_89_338","chapterId":"ch_work_nvlt_89","text":"【頌】梁江淹金荆頌曰：江南之山，連鄣連天，既抱紫霞，亦嗽絳煙，金荆佳树，涵雲宅仙，姱節詎及，幽意誰傳。","sortOrder":338},
  {"id":"s_work_nvlt_89_339","chapterId":"ch_work_nvlt_89","text":"【贊】宋顏峻幾贊序曰：今上在彭城，賜金荆臥幾。","sortOrder":339},
  {"id":"s_work_nvlt_89_341","chapterId":"ch_work_nvlt_89","text":"《周書》，程寤曰：文王在翟，夢南［逸周書作商。］庭生棘，小子發取周庭之梓於闕間，化松柏栻乍，驚以告文王，文王召發於明堂，拜吉夢，受商大命，秋朝士。","sortOrder":341},
  {"id":"s_work_nvlt_89_342","chapterId":"ch_work_nvlt_89","text":"《周禮》曰：左九棘，孤卿大夫位焉，右九棘，公侯伯子男位焉，树棘以為位，取赤心而外刺。","sortOrder":342},
  {"id":"s_work_nvlt_89_343","chapterId":"ch_work_nvlt_89","text":"元命苞曰：树棘聽訟其下者，原心不其赤實也。","sortOrder":343},
  {"id":"s_work_nvlt_89_344","chapterId":"ch_work_nvlt_89","text":"吳都賦曰：亦猶棘林之螢耀，與夫尋木之龍燭。","sortOrder":344},
  {"id":"s_work_nvlt_89_345","chapterId":"ch_work_nvlt_89","text":"魏都賦曰：榮其文身，驕其险棘。","sortOrder":345},
  {"id":"s_work_nvlt_89_346","chapterId":"ch_work_nvlt_89","text":"又曰：尋靡萍於中逵，造木猴於棘刺。","sortOrder":346},
  {"id":"s_work_nvlt_89_347","chapterId":"ch_work_nvlt_89","text":"《春秋繁露》曰：美惡之類，各以類應，故以龍致雨，以扇逐暑，軍之所處，生以棘楚。","sortOrder":347},
  {"id":"s_work_nvlt_89_348","chapterId":"ch_work_nvlt_89","text":"石季龍大饗群臣於大武殿，［本條《太平御覽》九百五十九作晉書。］佛圖澄曰：殿乎殿乎，棘子成林，將坏人衣，龍發下石，果有棘生。","sortOrder":348},
  {"id":"s_work_nvlt_89_349","chapterId":"ch_work_nvlt_89","text":"《陳留耆舊傳》曰：魏尚［《太平御覽》九百五十九尚下有被系二字，(本條亦見本書九十二卷，文有詳略。)］詔獄，棘［御覽棘上有有雀集獄四字。］树上，占曰：夫棘中心赤，外有棘［御覽作刺，下同。］蒙［御覽作象。］我言有棘而赤心之至誠也。","sortOrder":349},
  {"id":"s_work_nvlt_89_350","chapterId":"ch_work_nvlt_89","text":"《離骚》曰：甘棠苦於丰草，荆棘生於中庭。","sortOrder":350},
  {"id":"s_work_nvlt_89_351","chapterId":"ch_work_nvlt_89","text":"《毛詩》曰：凯風自南，吹彼棘心。","sortOrder":351},
  {"id":"s_work_nvlt_89_352","chapterId":"ch_work_nvlt_89","text":"又曰：尸鳩在桑，其子在棘。","sortOrder":352},
  {"id":"s_work_nvlt_89_353","chapterId":"ch_work_nvlt_89","text":"又，肅肅鴇羽，集於苞棘。","sortOrder":353},
  {"id":"s_work_nvlt_89_354","chapterId":"ch_work_nvlt_89","text":"又，湛湛露斯，在彼杞棘。","sortOrder":354},
  {"id":"s_work_nvlt_89_355","chapterId":"ch_work_nvlt_89","text":"又，營營青蠅，止於棘。","sortOrder":355},
  {"id":"s_work_nvlt_89_356","chapterId":"ch_work_nvlt_89","text":"又曰：吹彼棘薪。","sortOrder":356},
  {"id":"s_work_nvlt_89_357","chapterId":"ch_work_nvlt_89","text":"《後漢書》曰：我有枳棘，岑君伐之。","sortOrder":357},
  {"id":"s_work_nvlt_89_358","chapterId":"ch_work_nvlt_89","text":"◇黃莲","sortOrder":358},
  {"id":"s_work_nvlt_89_359","chapterId":"ch_work_nvlt_89","text":"《本草經》曰：黃莲一名王莲，味苦寒，治熱。","sortOrder":359},
  {"id":"s_work_nvlt_89_360","chapterId":"ch_work_nvlt_89","text":"【頌】梁江淹黃莲頌曰：黃莲上草，丹沙之次，御孽辟妖，長靈久视，驂龍行天，馴馬匝地，鸿飛以儀，順道則利。","sortOrder":360},
  {"id":"s_work_nvlt_89_361","chapterId":"ch_work_nvlt_89","text":"◇栀子","sortOrder":361},
  {"id":"s_work_nvlt_89_362","chapterId":"ch_work_nvlt_89","text":"《漢書》曰：栀，茜園，［栀，支子也。］","sortOrder":362},
  {"id":"s_work_nvlt_89_363","chapterId":"ch_work_nvlt_89","text":"《本草經》曰：支子一名木丹。","sortOrder":363},
  {"id":"s_work_nvlt_89_364","chapterId":"ch_work_nvlt_89","text":"《地鏡圖》曰：望氣占人家黃氣者，栀子树也。","sortOrder":364},
  {"id":"s_work_nvlt_89_365","chapterId":"ch_work_nvlt_89","text":"《晉令》曰：諸宮［《太平御覽》九百五十九作官］有秩栀子守護者，置吏一人。","sortOrder":365},
  {"id":"s_work_nvlt_89_366","chapterId":"ch_work_nvlt_89","text":"《晉宮閣名》曰：華林園栀子五株。","sortOrder":366},
  {"id":"s_work_nvlt_89_367","chapterId":"ch_work_nvlt_89","text":"遊名山志曰：樓石山多栀子。","sortOrder":367},
  {"id":"s_work_nvlt_89_368","chapterId":"ch_work_nvlt_89","text":"【詩】齊謝朓牆北栀子树詩曰：有美當階树，霜露未能移，金蕡發朱采，映日以離離，幸賴夕陽下，餘景及四枝，還思照绿水，君階無曲池，餘榮未能已，晚實猶見奇，复留傾筐德，君恩信未赀。","sortOrder":368},
  {"id":"s_work_nvlt_89_369","chapterId":"ch_work_nvlt_89","text":"梁簡文帝詠栀子花詩曰：素華偏可憙，的的半臨池，疑為霜裹葉，复類雪封枝，日斜光隱見，風還影合離。","sortOrder":369},
  {"id":"s_work_nvlt_89_370","chapterId":"ch_work_nvlt_89","text":"【贊】宋顏测栀子贊曰：濯雨時摛素，當飆獨含芬，丰榮殊未紀，銷落竟誰聞。","sortOrder":370},
  {"id":"s_work_nvlt_89_372","chapterId":"ch_work_nvlt_89","text":"《尚書》曰：筱簜既敷，［筱，竹箭也。］","sortOrder":372},
  {"id":"s_work_nvlt_89_373","chapterId":"ch_work_nvlt_89","text":"《山海經》曰：雲山有桂竹，甚毒，傷人必死，［始興小桂縣，出桂竹也。］","sortOrder":373},
  {"id":"s_work_nvlt_89_374","chapterId":"ch_work_nvlt_89","text":"《說文》曰：箭矢竹也。","sortOrder":374},
  {"id":"s_work_nvlt_89_375","chapterId":"ch_work_nvlt_89","text":"《爾雅》曰：東南之美者，有會稽之竹箭焉。","sortOrder":375},
  {"id":"s_work_nvlt_89_376","chapterId":"ch_work_nvlt_89","text":"又曰：桃枝四寸有節。","sortOrder":376},
  {"id":"s_work_nvlt_89_377","chapterId":"ch_work_nvlt_89","text":"《禮記》曰：如竹箭之有筠。","sortOrder":377},
  {"id":"s_work_nvlt_89_378","chapterId":"ch_work_nvlt_89","text":"竹譜曰：桃枝竹，皮滑而黃，可以為席。","sortOrder":378},
  {"id":"s_work_nvlt_89_379","chapterId":"ch_work_nvlt_89","text":"《山海經》曰：嶓冢之山，嚚水之上，多桃枝竹。","sortOrder":379},
  {"id":"s_work_nvlt_89_380","chapterId":"ch_work_nvlt_89","text":"《魏志》曰：倭國有桃枝竹。","sortOrder":380},
  {"id":"s_work_nvlt_89_381","chapterId":"ch_work_nvlt_89","text":"裴氏《廣州記》曰：廣州有桃枝竹。","sortOrder":381},
  {"id":"s_work_nvlt_89_382","chapterId":"ch_work_nvlt_89","text":"永嘉記曰：陽屿有仙石山，顶上有平石，方十餘丈，名仙壇，壇陬辄有一筋竹，凡有四竹，葳蕤青翠，風來動音，自成宮商，石上净絜，初無粗箨，相傳雲，曾有却粒者，於此羽化，故謂之仙石。","sortOrder":382},
  {"id":"s_work_nvlt_89_383","chapterId":"ch_work_nvlt_89","text":"竺法真羅山疏曰：嶺南道無筋竹，惟此山有之，其大尺围，細者色如黃金，堅貞疏節。","sortOrder":383},
  {"id":"s_work_nvlt_89_384","chapterId":"ch_work_nvlt_89","text":"《異苑》曰：東陽留道德家中筋竹林，忽生連理。","sortOrder":384},
  {"id":"s_work_nvlt_89_385","chapterId":"ch_work_nvlt_89","text":"《呂氏春秋》曰：昔黃帝命伶倫為律，伶倫自大夏之西，阮隃山之陰，取竹之嶰穀，斷兩節間，長六寸九分而吹之，為黃鍾之宮，律之本也。","sortOrder":385},
  {"id":"s_work_nvlt_89_386","chapterId":"ch_work_nvlt_89","text":"竹譜曰：邛竹，高節實中，状如人剡，俗謂之扶老竹。","sortOrder":386},
  {"id":"s_work_nvlt_89_387","chapterId":"ch_work_nvlt_89","text":"《漢書》：張騫至大夏，見邛竹枝，問之，雲贾人市之身毒國。","sortOrder":387},
  {"id":"s_work_nvlt_89_388","chapterId":"ch_work_nvlt_89","text":"《丹陽記》曰：江寧縣南三十里，有慈母山，積石臨江，生箫管竹，自伶倫采竹嶰穀，其後惟此簳見珍，故歷代常給樂府，而俗呼鼓吹山，今慈湖戍常禁采之。","sortOrder":388},
  {"id":"s_work_nvlt_89_389","chapterId":"ch_work_nvlt_89","text":"《禮斗威儀》曰：君乘木而王，政太平，蔓竹紫脱，為之常生，《吳越春秋》曰：越王問范蠡用兵，對曰：越有處女，原君王問之，處女北行見王，道逢老人，自稱袁公，跪拔林於［《太平御覽》九百六十二作杪。］竹，末折墮地，處女即捷其末，公操其本而刺處女，處女舉扙击之，公飛上树，变為白猿。","sortOrder":389},
  {"id":"s_work_nvlt_89_390","chapterId":"ch_work_nvlt_89","text":"《博物志》曰：洞庭之山，帝之二女啼，以涕揮竹，竹盡班，今下雋有班皮竹。","sortOrder":390},
  {"id":"s_work_nvlt_89_391","chapterId":"ch_work_nvlt_89","text":"《山海經》曰：長石山之西，有共穀，其中多竹，衛丘之竹山林在焉，大可為舟，［郭璞曰：竹一節間，可為舡也。］","sortOrder":391},
  {"id":"s_work_nvlt_89_392","chapterId":"ch_work_nvlt_89","text":"《易》曰：震為蒼琅竹。","sortOrder":392},
  {"id":"s_work_nvlt_89_393","chapterId":"ch_work_nvlt_89","text":"《穆天子傳》曰：天子西征，休於玄池之上，乃奏廣樂，三日而終，是曰樂池，乃树之竹，是曰竹林。","sortOrder":393},
  {"id":"s_work_nvlt_89_394","chapterId":"ch_work_nvlt_89","text":"《離骚·七諫》曰：便娟之脩竹，寄生於江潭，上葳蕤而防露，下泠泠而來風。","sortOrder":394},
  {"id":"s_work_nvlt_89_395","chapterId":"ch_work_nvlt_89","text":"《史記》曰：汧渭川千畝竹，其人與千戶侯等。","sortOrder":395},
  {"id":"s_work_nvlt_89_396","chapterId":"ch_work_nvlt_89","text":"《韓詩外傳》曰：黃帝時，鳳皇栖帝梧桐，食帝竹實。","sortOrder":396},
  {"id":"s_work_nvlt_89_397","chapterId":"ch_work_nvlt_89","text":"《漢書》曰：高祖為亭長，乃以竹皮為冠，［以竹始生皮作冠，今鵲尾冠是也。］及貴，常冠之。","sortOrder":397},
  {"id":"s_work_nvlt_89_398","chapterId":"ch_work_nvlt_89","text":"又曰：上發卒塞瓠子河，令群臣將軍以下，皆負薪而下淇園之竹，［衛之苑也，多竹筱也。］","sortOrder":398},
  {"id":"s_work_nvlt_89_399","chapterId":"ch_work_nvlt_89","text":"《三辅舊事》曰：窦將軍有青竹田。","sortOrder":399},
  {"id":"s_work_nvlt_89_400","chapterId":"ch_work_nvlt_89","text":"《楚國先賢傳》曰：孟宗母嗜筍，及母亡，冬節將至，筍尚未生，宗入竹哀叹，而筍為之出，得以供祭，至孝之感也。","sortOrder":400},
  {"id":"s_work_nvlt_89_401","chapterId":"ch_work_nvlt_89","text":"《文士傳》曰：蔡邕經會稽高遷亭，見椽竹可以為籥，取用，果有異聲。","sortOrder":401},
  {"id":"s_work_nvlt_89_402","chapterId":"ch_work_nvlt_89","text":"《湘州記》曰：邵陵高平縣有文竹山，上有石床，四面绿竹扶疏，常隨風委拂此床。","sortOrder":402},
  {"id":"s_work_nvlt_89_403","chapterId":"ch_work_nvlt_89","text":"盛弘之《荆州記》曰：臨贺冬山中，有大竹，數十围，高亦數十丈，有小竹生其旁，皆四五围，下有盤石，径四五丈，極方正，青如彈棋局，兩竹屈垂，拂扫石上，初無尘秽，未［《太平御覽》九百六十二未下有至字。］數十里間，風吹此竹，如箫管之音。","sortOrder":403},
  {"id":"s_work_nvlt_89_404","chapterId":"ch_work_nvlt_89","text":"《述征記》曰：山陽縣城東北二十里，魏中散大夫嵇康園宅竹林，時有遺竹也，在白鹿嵒東南。","sortOrder":404},
  {"id":"s_work_nvlt_89_405","chapterId":"ch_work_nvlt_89","text":"荆州厥貢惟箘簵楛，［本條《太平御覽》九百六十二作尚書。］楊州厥貢筱簜既敷，［筱竹箭，簜大竹水去已布生。］","sortOrder":405},
  {"id":"s_work_nvlt_89_406","chapterId":"ch_work_nvlt_89","text":"《毛詩》曰：如竹笣矣。","sortOrder":406},
  {"id":"s_work_nvlt_89_407","chapterId":"ch_work_nvlt_89","text":"籊々竹竿，以釣於淇，竹竿，［篇名。］衛女思歸也，適異國而不見答，思而能以禮也。","sortOrder":407},
  {"id":"s_work_nvlt_89_408","chapterId":"ch_work_nvlt_89","text":"《禮》曰：日短至，則伐木，取竹箭。","sortOrder":408},
  {"id":"s_work_nvlt_89_409","chapterId":"ch_work_nvlt_89","text":"《莊子》曰：鵷雏非練實而不食，［練食，竹實也，取其絜白也。］","sortOrder":409},
  {"id":"s_work_nvlt_89_410","chapterId":"ch_work_nvlt_89","text":"《家語》曰：山南之竹，不搏自直，斬而為箭，射達革。","sortOrder":410},
  {"id":"s_work_nvlt_89_411","chapterId":"ch_work_nvlt_89","text":"【詩】齊虞羲見江邊竹詩曰：挺此貞堅性，來树朝夕池，秋波漱下趾，冬雪封上枝，葳蕤防晓露，葱蒨集羁雌，含風自飒飒，負雪亦猗猗，金明無異状，玉洞良在斯，但恨非嶰穀，伶倫未見知。","sortOrder":411},
  {"id":"s_work_nvlt_89_412","chapterId":"ch_work_nvlt_89","text":"齊謝朓詠竹詩曰：窗前一丛竹，青翠獨言奇，南條交北葉，新筍雜故枝，月光疏已密，風聲起复垂，青扈飛不礙，黃口得相窥，但恨從風箨，根株長別離。","sortOrder":412},
  {"id":"s_work_nvlt_89_413","chapterId":"ch_work_nvlt_89","text":"梁元帝賦得竹詩，嶰穀管新抽，淇園竹复脩，作龍還葛水，為馬向併州，柯亭臨絕涧，桃枝夹細流，冠學芙蓉樣，花堪威鳳遊，邛王若有獻，張騫應拜侯。","sortOrder":413},
  {"id":"s_work_nvlt_89_414","chapterId":"ch_work_nvlt_89","text":"梁沈約詠簷前竹曰：萌开箨已垂，結葉始成枝，繁陰上蓊茸，促節下離離，風動露滴瀝，月照影參差，得生君戶牖，不原夹華池。","sortOrder":414},
  {"id":"s_work_nvlt_89_415","chapterId":"ch_work_nvlt_89","text":"梁江洪和新浦侯斋前竹詩曰：本生出高嶺，移賞入庭蹊，檀栾拂桂撩，蓊葱傍朱閨，夜條風析析，晓葉露凄凄，箨紫春湋思，筠绿寒蛩啼，不惜凌雲茂，遂聽群雀栖，原抽一茎實，试看翔鳳來。","sortOrder":415},
  {"id":"s_work_nvlt_89_416","chapterId":"ch_work_nvlt_89","text":"梁劉孝先竹詩曰：竹生空野外，梢雲耸百尋，無人賞高節，徒自抱貞心，恥染湘妃淚，羞入上宮琴，誰能製長笛，當為吐龍吟。","sortOrder":416},
  {"id":"s_work_nvlt_89_417","chapterId":"ch_work_nvlt_89","text":"梁劉孝威詠枯葉竹詩曰：枯楊猶更绿，臥柳尚還生，勿嫌鳳不至，終當待聖明。","sortOrder":417},
  {"id":"s_work_nvlt_89_418","chapterId":"ch_work_nvlt_89","text":"陳贺循賦得夹池脩竹詩曰：绿竹影參差，葳蕤帶曲池，逢秋葉不落，經寒色詎移，來風韻晚迳，集鳳動春枝，所欣高蹈客，未待伶倫吹。","sortOrder":418},
  {"id":"s_work_nvlt_89_419","chapterId":"ch_work_nvlt_89","text":"陳陰铿賦得夹池竹詩曰：夹池一丛竹，垂翠不驚寒，葉醞宜成酒，皮治薛縣冠，湘川染別淚，衡嶺拂仙壇，欲見凌冬质，當為雪中看。","sortOrder":419},
  {"id":"s_work_nvlt_89_420","chapterId":"ch_work_nvlt_89","text":"陳張正見賦得階前嫩竹詩曰：翠竹梢雲自結丛，輕花嫩筍欲凌空，砌曲橫枝屢解箨，階前疏葉強來風，欲知抱節成龍處，當於山路葛陂中。","sortOrder":420},
  {"id":"s_work_nvlt_89_421","chapterId":"ch_work_nvlt_89","text":"【賦】晉江逌竹賦曰：有嘉生之美竹，挺純姿於自然，含虛中以象道，體圓质以儀天，讬宗爽垲，列族圃田，緣崇嶺，帶回川，薄循隰，衍平原，故能凌驚風，茂寒乡，籍堅冰，負雪霜，振葳蕤，扇芬芳，翕幽液以润本，承清露以擢茎，拂景雲以容與，拊惠風而回萦。","sortOrder":421},
  {"id":"s_work_nvlt_89_422","chapterId":"ch_work_nvlt_89","text":"齊王俭靈丘竹賦應詔曰：靈丘深沉，蔓竹凝陰，神根合拱，楨幹百尋，振芳條乎崑嶽，敷绿采於高岑，沿淮海而蔚映，帶沮漳而萧森，志東南而擅美，在淇衛而流音，方靈寿而均茂，儀菌桂而成林，若乃青春受謝，九野舒榮，绿蘋齊葉，白芷抽萌，{笞心}々而特秀，筱擢穎而垂英，霜曒鏡於原隰，木衰疏於郊阡，翠葉與飛雪爭采，貞柯與曾冰競鮮。","sortOrder":422},
  {"id":"s_work_nvlt_89_423","chapterId":"ch_work_nvlt_89","text":"梁簡文帝脩竹賦曰：玉润桃枝之麗，魚腸雲母之名，日映花美，風動花輕。","sortOrder":423},
  {"id":"s_work_nvlt_89_424","chapterId":"ch_work_nvlt_89","text":"【詔】梁任昉靜思堂秋竹應詔曰：靜思堂，連洞房，臨曲沼，夹脩篁，竹宮丰麗於甘泉之右，竹殿弘敞於神嘉之傍，绿條發丹槛，翠葉映雕梁，入戶扫文石，傍簷拂象床，常生偶蘭桂，結實值鴛皇，逢性與之至道，偶斯文之在茲，歡柏梁之有賦，恨相如之異時。","sortOrder":424},
  {"id":"s_work_nvlt_89_425","chapterId":"ch_work_nvlt_89","text":"【贊】晉謝莊竹贊曰：瞻彼中唐，绿竹猗猗，貞而不介，弱而不虧，杳裊人圃，萧瑟雲崖，推名楚潭，美质梁池。","sortOrder":425},
  {"id":"s_work_nvlt_89_426","chapterId":"ch_work_nvlt_89","text":"【序】晉伏滔長笛賦序曰：餘同僚桓子野，有故長笛，耆老雲，蔡邕之所作也，初邕避難江南，宿於柯亭，柯亭之觀，以竹為椽，邕仰而眄之曰：良竹也，取以為笛，音聲獨絕。","sortOrder":426},
  {"id":"s_work_nvlt_89_427","chapterId":"ch_work_nvlt_89","text":"《藝文類聚》　唐·欧陽詢","sortOrder":427},
  {"id":"s_work_nvlt_90_1","chapterId":"ch_work_nvlt_90","text":"卷九十鳥部上","sortOrder":1},
  {"id":"s_work_nvlt_90_2","chapterId":"ch_work_nvlt_90","text":"○鳥鳳鸞鸿鶴［白鶴黃鵠玄鵠附］雉鶡","sortOrder":2},
  {"id":"s_work_nvlt_90_4","chapterId":"ch_work_nvlt_90","text":"《爾雅》曰：二足而羽謂之禽，生哺鷇，生噣雏。","sortOrder":4},
  {"id":"s_work_nvlt_90_5","chapterId":"ch_work_nvlt_90","text":"又曰：亢鳥咙，［咙，喉也。］其粻嗉，［嗉，受食之處也。］","sortOrder":5},
  {"id":"s_work_nvlt_90_6","chapterId":"ch_work_nvlt_90","text":"尚書曰：日中星鳥，以殷仲春，鳥獸孳尾，日永星火，以正仲夏，鳥獸希革，宵中星虛，以殷仲秋，鳥獸毛毨，日短星卯，以正仲冬，鳥獸氄毛。","sortOrder":6},
  {"id":"s_work_nvlt_90_7","chapterId":"ch_work_nvlt_90","text":"《周官》曰：鳥隼為旟。","sortOrder":7},
  {"id":"s_work_nvlt_90_8","chapterId":"ch_work_nvlt_90","text":"《毛詩》曰：誕寘之寒冰，鳥覆翼之，鳥乃去矣，後稷呱矣，［後稷初生，弃之於冰上，鳥舒翼覆之。］","sortOrder":8},
  {"id":"s_work_nvlt_90_9","chapterId":"ch_work_nvlt_90","text":"又曰：伐木丁丁，鳥鳴嘤嘤，嘤其鳴矣，求其友聲。","sortOrder":9},
  {"id":"s_work_nvlt_90_10","chapterId":"ch_work_nvlt_90","text":"左氏曰：晉侯伐齊，齊師夜遁，師曠曰：鳥乌之聲樂，齊師其遁。","sortOrder":10},
  {"id":"s_work_nvlt_90_11","chapterId":"ch_work_nvlt_90","text":"《禮記》曰：凡生天地之間者，莫不知愛其類，今是大鳥獸，則失丧其匹，越月逾時焉，過其故乡，回翔焉，鳴號焉，蹢躅焉，踟蹰焉，然後乃能去之，小者至於燕雀，猶有啁啾之頃焉，凡有血氣之屬者，莫智於人，故人於其親也，至死不窮。","sortOrder":11},
  {"id":"s_work_nvlt_90_12","chapterId":"ch_work_nvlt_90","text":"《論語》曰：鳥之將死，其鳴也哀。","sortOrder":12},
  {"id":"s_work_nvlt_90_13","chapterId":"ch_work_nvlt_90","text":"又曰：鳥獸不可與同群。","sortOrder":13},
  {"id":"s_work_nvlt_90_14","chapterId":"ch_work_nvlt_90","text":"《春秋孔演圖》曰：鳥化為書，孔子奉以告天，赤雀集書上，化為黃玉，刻曰：孔提命，作應法為赤製，雀集。","sortOrder":14},
  {"id":"s_work_nvlt_90_15","chapterId":"ch_work_nvlt_90","text":"《家語》曰：孔子在衛，顏回侍侧，聞哭聲甚哀，子曰：回汝知此何哭，對曰：此哭非但為死。又為生離，回聞桓山之鳥，生四子焉，羽翼既成，將分四海，悲鳴而送之，哀聲似此，孔子使問之，果父死家貧，賣子以葬。","sortOrder":15},
  {"id":"s_work_nvlt_90_16","chapterId":"ch_work_nvlt_90","text":"《晏子》曰：齊景公使顏涿聚主鳥而亡，公召欲殺之，《晏子》曰：涿聚有三罪，請數之，爾為吾君主鳥而亡之，一罪也，使吾君以鳥殺人，二罪也，諸侯聞之，以吾君重鳥輕士，三罪也，公曰：勿殺之。","sortOrder":16},
  {"id":"s_work_nvlt_90_17","chapterId":"ch_work_nvlt_90","text":"《莊子》曰：上好智而無道，則天下大亂矣，何以知其然耶，弓弩罼弋，機变之智多，則鳥亂於上也。","sortOrder":17},
  {"id":"s_work_nvlt_90_18","chapterId":"ch_work_nvlt_90","text":"《孫卿子》曰：鳥窮則啄，獸窮則攫，人窮則诈。","sortOrder":18},
  {"id":"s_work_nvlt_90_19","chapterId":"ch_work_nvlt_90","text":"《史記》曰：秦仲知百鳥之音，與之語，皆應焉。","sortOrder":19},
  {"id":"s_work_nvlt_90_20","chapterId":"ch_work_nvlt_90","text":"《東方朔傳》曰：武帝問朔，何知鳥之雌雄，對曰：雄左翼加右，聲高，雌右翼加左，聲小。","sortOrder":20},
  {"id":"s_work_nvlt_90_21","chapterId":"ch_work_nvlt_90","text":"謝承《後漢書》曰：楊震，卒，未葬，有大鳥五色，高丈餘，從天飛下，到震棺前，舉頭悲鳴，淚出霑地，至葬日，冲升天上。","sortOrder":21},
  {"id":"s_work_nvlt_90_22","chapterId":"ch_work_nvlt_90","text":"華峤《漢書》曰：當時人，立石鳥象於震前。","sortOrder":22},
  {"id":"s_work_nvlt_90_23","chapterId":"ch_work_nvlt_90","text":"《十洲記》曰：東海中有祖洲，地方五百里，去海岸七萬里，上有不死之草，似瓜苗，秦始皇時，大宛［十洲記作苑。］中多死人橫道，忽有鳥如乌状，衔此草以覆死人面，皆登時起坐，遂活。","sortOrder":23},
  {"id":"s_work_nvlt_90_24","chapterId":"ch_work_nvlt_90","text":"抱朴子軍術曰：眾鳥群飛，徘徊軍上，不過三日，有暴兵至，鳥聚軍中，將軍當賞功增秩，鳥集將軍之旗，將軍增官，鳥集軍中，莫知其名，軍败。","sortOrder":24},
  {"id":"s_work_nvlt_90_25","chapterId":"ch_work_nvlt_90","text":"羅含傳曰：含少時晝臥，忽夢一鳥，文色異常，飛來入口，含因驚起，心焜間如吞物，意甚怪之，叔母謂曰：鳥有文章，汝後必有文章，此吉祥也，含於是才藻日新。","sortOrder":25},
  {"id":"s_work_nvlt_90_26","chapterId":"ch_work_nvlt_90","text":"《搜神記》曰：常山張顥，為梁相，天新雨後，有鳥如山鵲，稍下墮地，民爭取，即化為一圓石，顥椎破之，得一金印，文曰忠孝侯印，顥以聞，上藏之秘府，顥後官至太尉。","sortOrder":26},
  {"id":"s_work_nvlt_90_27","chapterId":"ch_work_nvlt_90","text":"《博物志》曰：子路與子貢過鄭神社，社树有鳥，子路捕鳥，神社牵挛子路，子路子貢悅之，乃止。","sortOrder":27},
  {"id":"s_work_nvlt_90_28","chapterId":"ch_work_nvlt_90","text":"《會稽典錄》曰：夏方，字文正，家遭疫癘，父母伯叔一時死，凡十三丧，方年十四，晝則負土，哀號墓侧，扶棺哭泣，比葬，年十七，乌鳥集聚，猛獸乳其侧。","sortOrder":28},
  {"id":"s_work_nvlt_90_29","chapterId":"ch_work_nvlt_90","text":"【詩】古詩曰：胡馬依北風，越鳥巢南枝。","sortOrder":29},
  {"id":"s_work_nvlt_90_30","chapterId":"ch_work_nvlt_90","text":"梁朱超詠獨栖鳥詩曰：河水聞寒已成冻，塞草愁霜懸自衰，可念無端失林鳥，此夜逆風何處歸，列網遮山不聽度，懸冰繞树滑難依，細石似燕能隨雨，片木作鳶猶解機，但令積風多少便，何患有翼不能飛，寄語故林無數鳥，會入群里比毛衣。","sortOrder":30},
  {"id":"s_work_nvlt_90_31","chapterId":"ch_work_nvlt_90","text":"【賦】漢趙壹窮鳥賦曰：有一窮鳥，戢翼原野，罼網加上，機阱在下，繳彈張右，翼弓彀左，飛丸繳矢，交集於我，思飛不得，欲鳴不可，舉頭畏觸，搖足恐墮，內懷怖急，乍冰乍火，幸賴大賢，我矜我怜，昔濟我南，今振我西，鳥也雖顽，猶識密恩，內以書心，外用告天。","sortOrder":31},
  {"id":"s_work_nvlt_90_32","chapterId":"ch_work_nvlt_90","text":"晉夏侯湛觀飛鳥賦曰：見逸遊之高鳥，邈飄颺而殊逝，擢華毛以迅鶩，回劲翼以扬势，披六翮之聯翩，振輕體之迢遞，遂乃矜形遼廓，冯虛安翔，翩翻徘徊，上下頡颃，動素羽之習習，亂白质於日光，玩流氣以差池，弄長風以抑扬，攝双翅以高舉，舒脩頸以儴徉，目悅妙势，心嘉羽儀，愛惠音之嘤嘤，美弱翰之參差，蹔高凌於景外。又抑身乎雲崖，乍來乍往，若懸若垂，象流星之離天，似圓物之墜危，何斯遊之自得，谅逸豫之可希，苟臨川而羨魚，亦觀翔而樂飛。","sortOrder":32},
  {"id":"s_work_nvlt_90_33","chapterId":"ch_work_nvlt_90","text":"梁沈約天淵水鳥應詔賦曰：天淵池，鳥集水涟漪，单汎姿容與，群飛時合離，將騫复斂翮，回首望驚雌，飄薄出孤屿，未曾宿蘭渚，飛飛忽雲倦，相鳴集池篽，可怜九層樓，光影水上浮，本來蹔止息，遇此遂淹留，若夫侣浴清深，朋翻迥曠，翠鬛紫纓之飾，丹冕绿襟之状，過波兮湛澹，隨風兮回漾，竦臆兮开萍，蹙水兮興浪。","sortOrder":33},
  {"id":"s_work_nvlt_90_34","chapterId":"ch_work_nvlt_90","text":"【序】晉王叔之傷孤鳥詩序曰：偶得二鳥，將欲放之，俄頃而一者死，一者既放，屢顧悲鳴，感微禽之有心，遂為詩以傷之。","sortOrder":34},
  {"id":"s_work_nvlt_90_36","chapterId":"ch_work_nvlt_90","text":"《說文》曰：鳳，神鳥也。","sortOrder":36},
  {"id":"s_work_nvlt_90_37","chapterId":"ch_work_nvlt_90","text":"《山海經》曰：軒轅之丘，鸞自歌，鳳自舞。","sortOrder":37},
  {"id":"s_work_nvlt_90_38","chapterId":"ch_work_nvlt_90","text":"又曰：南禺之山，有鳳皇鵷雏。","sortOrder":38},
  {"id":"s_work_nvlt_90_39","chapterId":"ch_work_nvlt_90","text":"《周書·王會》曰：鳳鳥戴仁抱義。","sortOrder":39},
  {"id":"s_work_nvlt_90_40","chapterId":"ch_work_nvlt_90","text":"《大戴禮》曰：羽虫三百六十，而鳳皇為之長。","sortOrder":40},
  {"id":"s_work_nvlt_90_41","chapterId":"ch_work_nvlt_90","text":"《毛詩》曰：鳳皇於飛，翙翙其羽，亦傅於天。","sortOrder":41},
  {"id":"s_work_nvlt_90_42","chapterId":"ch_work_nvlt_90","text":"又曰：鳳皇鳴矣，於彼高岗，梧桐生矣，於彼朝陽。","sortOrder":42},
  {"id":"s_work_nvlt_90_43","chapterId":"ch_work_nvlt_90","text":"《禮記》曰：麟鳳龟龍，謂之四靈。","sortOrder":43},
  {"id":"s_work_nvlt_90_44","chapterId":"ch_work_nvlt_90","text":"《左傳》曰：陳大夫卜妻敬仲，其妻占之曰：鳳皇於飛，和鳴锵锵，有妫之後，將育於薑。","sortOrder":44},
  {"id":"s_work_nvlt_90_45","chapterId":"ch_work_nvlt_90","text":"《鶡冠子》曰：鳳鶉火禽，陽之精也，德能致之，其精畢至。","sortOrder":45},
  {"id":"s_work_nvlt_90_46","chapterId":"ch_work_nvlt_90","text":"《論語》曰：鳳鳥不至，河不出圖，吾已矣夫。","sortOrder":46},
  {"id":"s_work_nvlt_90_47","chapterId":"ch_work_nvlt_90","text":"宋玉對問曰：鳳皇上击九千里，絕雲霓，負蒼天乎窈冥之中，蕃篱之鷃，豈能與之料天地之高哉。","sortOrder":47},
  {"id":"s_work_nvlt_90_48","chapterId":"ch_work_nvlt_90","text":"《莊子》曰：老子見孔子，從弟子五人，問曰：為誰，對曰：子路為勇，其次子貢為智，曾子為孝，顏回為仁，子張為式，［《太平御覽》九百十五作武。］老子叹曰：吾聞南方有鳥，其名為鳳，所居積石千里，天為生食，其树名琼枝，高百仞，以璆琳琅玕為實，天又為生離珠，一人三頭，遞臥遞起，以伺琅玕，鳳鳥之文，戴聖婴仁，右智左賢。","sortOrder":48},
  {"id":"s_work_nvlt_90_49","chapterId":"ch_work_nvlt_90","text":"《離骚》［《太平御覽》九百十五作楚辭。］曰：為鳳皇作鶉籠，雖翕其不容，［言以鶉鷃之籠，不能容藏鳳之形體也。］","sortOrder":49},
  {"id":"s_work_nvlt_90_50","chapterId":"ch_work_nvlt_90","text":"《漢武內傳》曰：西王母曰：仙之上藥，有九色鳳頸，次藥有蒙山白鳳之肉。","sortOrder":50},
  {"id":"s_work_nvlt_90_51","chapterId":"ch_work_nvlt_90","text":"《十洲記》曰：鳳麟洲在西海之中，四面有弱水繞之，鸿毛不可越也，其上多鳳麟，數萬各為群，上仙之家，以鳳喙麟角，合煎作膠，名為集絃膠，亦名連金泥，能屬連刀劍弓弩絃。","sortOrder":51},
  {"id":"s_work_nvlt_90_52","chapterId":"ch_work_nvlt_90","text":"焦貢《易林》曰：鳳生五雏，長於南郭，君子康寧，身悅榮樂。","sortOrder":52},
  {"id":"s_work_nvlt_90_53","chapterId":"ch_work_nvlt_90","text":"《列仙傳》曰：箫史教弄玉吹箫，作鳳聲，鳳皇來止其屋，秦穆公為作鳳台，一旦皆隨鳳飛去。","sortOrder":53},
  {"id":"s_work_nvlt_90_54","chapterId":"ch_work_nvlt_90","text":"《抱朴子》曰：夫麟鳳以形状為別，聖人以心神為異，古者太平之世，鳳皇常居其國而生乳，至夏後始食卵而鳳去之，此則鳳有种矣。","sortOrder":54},
  {"id":"s_work_nvlt_90_55","chapterId":"ch_work_nvlt_90","text":"楊龍驤洛陽記曰：鳳陽門五層樓，去地三十丈，安金鳳皇二頭，石虎將衰，一頭飛入漳河，今日清朗，見於水中，［事具樓篇。］","sortOrder":55},
  {"id":"s_work_nvlt_90_56","chapterId":"ch_work_nvlt_90","text":"【詩】漢李陵詩曰：鳳皇鳴高岗，有翼不好飛，安知鳳皇德，貴其來見稀。","sortOrder":56},
  {"id":"s_work_nvlt_90_57","chapterId":"ch_work_nvlt_90","text":"魏劉楨詩曰：鳳皇集南嶽，徘徊孤竹根，於心有不厭，奋翅凌紫氛，豈不常勤苦，羞與黃雀群。","sortOrder":57},
  {"id":"s_work_nvlt_90_58","chapterId":"ch_work_nvlt_90","text":"晉棗據詩曰：有鳳適南中，終日無歡娱，自怨梧桐遠，行飛栖桑榆，奋迅振長翼，俯仰向天衢，箫韶逝無聞，朝陽不可須。","sortOrder":58},
  {"id":"s_work_nvlt_90_59","chapterId":"ch_work_nvlt_90","text":"晉王叔之擬古詩曰：客從北方來，言欲到交趾，遠行無他货，唯有鳳皇子，百金我不欲，千金難為市。","sortOrder":59},
  {"id":"s_work_nvlt_90_60","chapterId":"ch_work_nvlt_90","text":"陳張正見賦得威鳳栖梧詩曰：丹山下威鳳，來集帝梧中，欲舞春花落，將飛秋葉空，影照龍門水，聲入洞庭風，別有將雏曲，翻更合絲桐。","sortOrder":60},
  {"id":"s_work_nvlt_90_61","chapterId":"ch_work_nvlt_90","text":"【賦】晉桓玄賦曰：伊品之自品，亦在類而有別，惟羽族之殊誕，獨鸞皇而構桀，邈區宇以超栖，撫朝陽於丹穴，備六德以成暉，奋藻翰之鬱烈，集崑峰而斂翼，翔青雲以遐越。","sortOrder":61},
  {"id":"s_work_nvlt_90_62","chapterId":"ch_work_nvlt_90","text":"晉傅鹹儀鳳賦序曰：鹪鹩賦者，廣武張侯之所造也，以其形微處卑，物莫之害也，而餘以為物生則有害，有害而能免，所以貴乎才智也，夫鹪鹩既無智足貴，亦禍害未免，免乎禍害者，不唯儀鳳也。","sortOrder":62},
  {"id":"s_work_nvlt_90_64","chapterId":"ch_work_nvlt_90","text":"《春秋元命苞》曰：火離為鸞。","sortOrder":64},
  {"id":"s_work_nvlt_90_65","chapterId":"ch_work_nvlt_90","text":"《海外經》曰：軒轅之國，清沃之野，鸞鳥自歌。","sortOrder":65},
  {"id":"s_work_nvlt_90_66","chapterId":"ch_work_nvlt_90","text":"又曰：廣都之野，鸞鳥歌。","sortOrder":66},
  {"id":"s_work_nvlt_90_67","chapterId":"ch_work_nvlt_90","text":"《漢武內傳》曰：西王母曰：神仙次藥，有靈丘蒼鸞。","sortOrder":67},
  {"id":"s_work_nvlt_90_68","chapterId":"ch_work_nvlt_90","text":"焦贛《易林》曰：溫山松柏，常茂不落，鸞鳳以庇，得其歡樂。","sortOrder":68},
  {"id":"s_work_nvlt_90_69","chapterId":"ch_work_nvlt_90","text":"《東觀漢記》曰：王阜為重泉令，鸞鳥集止學宮，阜使掾汝［《太平御覽》九百十六作沙。］叠，為張雅樂，击聲，鳥舉足垂翼，應聲而舞，止縣庭，留十餘日乃去。","sortOrder":69},
  {"id":"s_work_nvlt_90_70","chapterId":"ch_work_nvlt_90","text":"謝承《後漢書》曰：方储，家［《太平御覽》九百十六作字。］聖羽，［○御覽作明。］幼丧名［御覽作父。］事母，母終，自負土成墳，种奇树千株，鸞鳥止其上，白兔遊其下。","sortOrder":70},
  {"id":"s_work_nvlt_90_71","chapterId":"ch_work_nvlt_90","text":"《决錄註》曰：辛繕，字公文，治春秋讖緯，隱居華陰，光武徵不至，有大鳥高五尺，雞頭燕頷，蛇頸魚尾，五色備舉而多青，栖繕槐树，旬時不去，弘農太守以聞，詔問百寮，鹹以為鳳，太史令蔡衡對曰：凡象鳳者有五，多赤色者鳳，多青色者鸞，多黃色者鵷雏，多紫色者鸑鷟，多白色者鵠，今此鳥多青，乃鸞，非鳳也，上善其言，三公聞之，鹹遜位避，繕不起。","sortOrder":71},
  {"id":"s_work_nvlt_90_72","chapterId":"ch_work_nvlt_90","text":"《典略》曰：鸞鳥者，神靈之精，其象五彩，雞形，鳴中五音，肅肅雍雍，喜則舞以樂，常處幽閒，頌聲作則至。","sortOrder":72},
  {"id":"s_work_nvlt_90_73","chapterId":"ch_work_nvlt_90","text":"【詩】魏嵇叔夜赠秀才詩曰：双鸞匿景耀，戢翼太山崖，抗首嗽朝露，晞陽振羽儀，長鳴戲雲里，時下息蘭池。","sortOrder":73},
  {"id":"s_work_nvlt_90_74","chapterId":"ch_work_nvlt_90","text":"魏王粲詩曰：聯翩飛鸞鳥，獨遊無所因，毛羽照野草，哀鳴入青雲，我尚假羽翼，飛睹爾形身，原乃春陽會，交頸遘殷勤。","sortOrder":74},
  {"id":"s_work_nvlt_90_75","chapterId":"ch_work_nvlt_90","text":"宋范泰鸞鳥詩序曰：昔罽賓王結罝峻卯［《太平御覽》九百十六作祁。］之山，獲一鸞鳥，王甚愛之，欲其鳴而不致也，乃飾以金樊，饗以珍羞，對之愈戚，三年不鳴，其夫人曰：嘗聞鳥見其類而後鳴，何不懸鏡以映之，王從其意，鸞睹形悲鳴，哀响中霄，一奋而絕，嗟乎茲禽，何情之深，昔鍾子破琴於百［按當作伯。］牙，匠石韜斤於郢人，蓋悲妙賞之不存，慨神质於當年耳，矧乃一舉而殒其身者哉，悲夫，乃為詩曰：神鸞栖高梧，爰翔霄漢际，軒翼颺輕風，清响中天厲，外患難預謀，高羅掩逸势，明鏡懸高堂，顧影悲同契，一激九霄音，响流形已毙。","sortOrder":75},
  {"id":"s_work_nvlt_90_77","chapterId":"ch_work_nvlt_90","text":"《毛詩》曰：鸿雁，美宣王也。","sortOrder":77},
  {"id":"s_work_nvlt_90_78","chapterId":"ch_work_nvlt_90","text":"《周易》：初六，鸿漸於幹，上九，鸿漸於陆，其羽可用為儀，吉。［鸿，水鳥也，適進之義，始於下而升，故以鸿喻儀可貴也。］","sortOrder":78},
  {"id":"s_work_nvlt_90_79","chapterId":"ch_work_nvlt_90","text":"《禮記》曰：前有車騎，則載飛鸿，［取其飛有行列，舉於旗首，以警眾也。］","sortOrder":79},
  {"id":"s_work_nvlt_90_80","chapterId":"ch_work_nvlt_90","text":"又，孟春之月，鸿雁來，［雁自南方來，將北反其居。］季秋之月，鸿雁來賓，［賓言客止來去。］","sortOrder":80},
  {"id":"s_work_nvlt_90_81","chapterId":"ch_work_nvlt_90","text":"《左傳》：衛獻公誡孫文子寧惠子食，皆服而朝，日旰不召，［敕戒二子，欲共宴食，皆服朝衣待命也。］而射鸿於囿，二子從之，公不釋皮弁而與之言，二子怒，如戚，［戚，孫子邑也。］","sortOrder":81},
  {"id":"s_work_nvlt_90_82","chapterId":"ch_work_nvlt_90","text":"《尸子》曰：虎豹未成文，而有食牛之氣，鸿鵠之鷇，羽翼未全，而有四海之心，賢者之生亦然，《管子》曰：桓公在位，管仲隰朋見，立有間，有二鸿飛過，桓公叹曰：仲父，今彼鸿有時而南，有時而北，四方無遠，所欲至而至焉，惟有羽翼之故，是能通其意於天下乎，寡人之有仲父，猶飛鸿之有我［《太平御覽》九百十六作羽。］翼也。","sortOrder":82},
  {"id":"s_work_nvlt_90_83","chapterId":"ch_work_nvlt_90","text":"《莊子》曰：孔子見老子歸，三日不談，謂弟子曰：人如飛鸿者，吾必矰繳而射之，吾今見龍矣。","sortOrder":83},
  {"id":"s_work_nvlt_90_84","chapterId":"ch_work_nvlt_90","text":"《韓詩外傳》曰：齊使獻鸿於楚，鸿渴，使者於道飲鸿而失之，使者至楚曰：臣欲亡去，為兩使不通，欲絞頸而死，將以吾君賤士貴鸿也，楚王賢之，以為上客。","sortOrder":84},
  {"id":"s_work_nvlt_90_85","chapterId":"ch_work_nvlt_90","text":"《史記》，陳勝叹曰：燕雀安知鸿鵠之志哉。","sortOrder":85},
  {"id":"s_work_nvlt_90_86","chapterId":"ch_work_nvlt_90","text":"楊子《法言》曰：鸿飛冥冥，弋人何慕焉。","sortOrder":86},
  {"id":"s_work_nvlt_90_87","chapterId":"ch_work_nvlt_90","text":"《博物志》曰：鸿鵠千歲者皆胎產。","sortOrder":87},
  {"id":"s_work_nvlt_90_88","chapterId":"ch_work_nvlt_90","text":"【詩】宋顏延之歸鸿詩曰：昧旦濡和風，霑露踐朝暉，萬有皆同奉，鸿雁獨辭歸，相鳴去涧汜，長引發江畿，曒絜登雲侣，連綿千里飛，長懷河朔路，緬與湘漢违。","sortOrder":88},
  {"id":"s_work_nvlt_90_89","chapterId":"ch_work_nvlt_90","text":"【賦】晉成公綏鸿雁賦曰：餘嘗遊乎河泽之間，是時鸿雁應節而群至，望川以奔集，夫鸿漸著羽儀之叹，小雅作於飛之歌，斯乃古人所以假象興物，有取其美也，餘又奇其應氣而知時，故作斯賦，辰火西流，秋風厲起，軒翥鼓翼，抗志萬里，過雲夢以娱遊，投淮湘而中憩，晝顧眺以候遠，夜警循而相衛。","sortOrder":89},
  {"id":"s_work_nvlt_90_90","chapterId":"ch_work_nvlt_90","text":"梁沈約八詠，聽晓鸿篇曰：聽晓鸿，晓鸿度將旦，跨弱水之微澜，發成山之遠岸，無東西之可辨，孰遐邇之能筭，秋蓬飛兮未極，塞草寒兮無容色，吳山高兮高難度，越水深兮深不测，羨明月之馳光，顧征禽之駛翼，夜綿綿而難晓，愁參差而盈臆，孤雁夜南飛，客淚夜霑衣，春鸿旦暮反，客子方未歸。","sortOrder":90},
  {"id":"s_work_nvlt_90_91","chapterId":"ch_work_nvlt_90","text":"【序】晉曹毗双鸿詩序曰：近東野見有養双鸿者，其儀甚美。又善鳴舞，雖志希青翠之遊，身非己有，物之可感，良謂此也。","sortOrder":91},
  {"id":"s_work_nvlt_90_93","chapterId":"ch_work_nvlt_90","text":"韻集曰：鶴，善鳴鳥也。","sortOrder":93},
  {"id":"s_work_nvlt_90_94","chapterId":"ch_work_nvlt_90","text":"《周易》曰：鳴鶴在陰，其子和之。","sortOrder":94},
  {"id":"s_work_nvlt_90_95","chapterId":"ch_work_nvlt_90","text":"《毛詩》曰：鶴鳴，誨宣王也，鶴鳴於九皋，聲聞於天，［言身隱而名著也。］《左傳》曰：狄人伐衛，衛懿公好鶴，鶴有乘軒者，將戰，國人受甲者，皆曰使鶴，鶴實有祿位，餘焉能戰。","sortOrder":95},
  {"id":"s_work_nvlt_90_96","chapterId":"ch_work_nvlt_90","text":"《易通卦验》曰：立夏清風至而鶴鳴。","sortOrder":96},
  {"id":"s_work_nvlt_90_97","chapterId":"ch_work_nvlt_90","text":"《春秋說題辭》曰：鶴知夜半。","sortOrder":97},
  {"id":"s_work_nvlt_90_98","chapterId":"ch_work_nvlt_90","text":"《韓詩外傳》曰：晉平公遊於河而樂，曰：安得賢士與之樂此也，舡人蓋胥跪而對曰：夫珠出於江海，玉出於崑山，無足而至者，猶主君之好也，士有足而不至者，蓋主君無好士之意耳，何患無士乎，公曰：吾食客門左千人，門右千人，朝食不足，夕收市賦，暮食不足，朝收市賦，吾可謂不好士乎，對曰：夫鸿鵠一舉千里，所恃者六翮耳，背上之毛，腹下之毳，益一把，飛不為加高，損一把，飛不加下，今君之食客，門左門右各千人，亦有六翮在其中矣，將皆背上之毛，腹下之毳耶，［新序雲，晉文公遊西河，舟人固桑對也，說苑，趙簡子遊於河，舟人古桑對，凡三書皆同也。］","sortOrder":98},
  {"id":"s_work_nvlt_90_99","chapterId":"ch_work_nvlt_90","text":"列子，詹何曰：聞先大夫之言，蒲且子之弓弱纖繳，垂［《太平御覽》九百十六作乘。］風振之，連双鶴於青雲之际，用心专，動手均也。","sortOrder":99},
  {"id":"s_work_nvlt_90_100","chapterId":"ch_work_nvlt_90","text":"《墨子》曰：禽子問曰：多言有益乎，對曰：虾蟆日夜鳴，口乾而人不聽之，鶴雞時夜而鳴，天下振動，多言何益乎。","sortOrder":100},
  {"id":"s_work_nvlt_90_101","chapterId":"ch_work_nvlt_90","text":"《莊子》曰：凫胫雖短，續之則忧，鶴胫雖長，斷之則悲。","sortOrder":101},
  {"id":"s_work_nvlt_90_102","chapterId":"ch_work_nvlt_90","text":"又曰：老子謂孔子曰：夫鶴不日浴而白，乌不日黔而黑。","sortOrder":102},
  {"id":"s_work_nvlt_90_103","chapterId":"ch_work_nvlt_90","text":"《離骚》曰：緣鵠飾玉，後帝具饗，［後帝謂殷湯也，言伊尹始仕，緣烹鵠鳥之羹，脩飾玉鼎，以事殷湯，湯賢之，遂以為相也。］","sortOrder":103},
  {"id":"s_work_nvlt_90_104","chapterId":"ch_work_nvlt_90","text":"《史記》曰：齊王使淳於髡獻鶴於楚，出邑門，道飛其鶴，徒揭空籠以見楚王，曰：齊王使臣獻鶴，過於水上，不忍鶴渴，出而飲之，飛去，吾欲絞頸而絕，恐人議吾君以鳥故，令士自殺，吾欲買而代之，是不信而欺吾王，欲赴他國，痛吾兩主使不通，故來受罪，楚王曰：善，［說苑，魏文侯使舍人蔡無泽獻鶴於齊，其事同之也。］","sortOrder":104},
  {"id":"s_work_nvlt_90_105","chapterId":"ch_work_nvlt_90","text":"《神異經》曰：西海之外有鶴國，男女皆長寸，為人自然有禮，好經論跪拜，寿三百歲，人行如飛，日千里，百物不敢犯之，惟畏海鵠，鵠過吞之，亦寿三百歲，人在鵠腹中不死，而鵠一舉千里，［張茂先曰：此陳章對桓公也。］","sortOrder":105},
  {"id":"s_work_nvlt_90_106","chapterId":"ch_work_nvlt_90","text":"淮南八公相鶴經曰：鶴，陽鳥也，而遊於陰，蓋羽族之宗長，仙人之騏骥也。","sortOrder":106},
  {"id":"s_work_nvlt_90_107","chapterId":"ch_work_nvlt_90","text":"《東觀漢記》曰：章帝至岱宗，柴望畢，鵠三十從東南來，經祀壇上。","sortOrder":107},
  {"id":"s_work_nvlt_90_108","chapterId":"ch_work_nvlt_90","text":"《竹林七賢論》曰：嵇紹入洛，或謂王戎曰：昨於稠人中始見嵇紹，昂昂然若野鶴之在雞群。","sortOrder":108},
  {"id":"s_work_nvlt_90_109","chapterId":"ch_work_nvlt_90","text":"《琴操》曰：商陵牧子，取妻五年無子，父兄將欲為改娶，妻聞，中夜驚起，倚戶悲嘯，牧子聞，援琴鼓之，痛恩愛之永離，因彈別鶴以舒憤，故曰別鶴操。","sortOrder":109},
  {"id":"s_work_nvlt_90_110","chapterId":"ch_work_nvlt_90","text":"晉《八王故事》曰：陆機為成都王所誅，顧左右而叹曰：今日欲聞華亭鶴唳，不可复得，華亭吳國拳縣郊外之野，機素遊之所。","sortOrder":110},
  {"id":"s_work_nvlt_90_111","chapterId":"ch_work_nvlt_90","text":"《陶侃傳》曰：侃丁母艱，在墓下，忽有二客來弔，不哭而退，儀服鮮絜，知非常人，隨而看之，但見双鵠飛而冲天。","sortOrder":111},
  {"id":"s_work_nvlt_90_112","chapterId":"ch_work_nvlt_90","text":"《抱朴子》曰：周穆王南征，一軍盡化，君子為猿為鶴，小人為虫為沙。","sortOrder":112},
  {"id":"s_work_nvlt_90_113","chapterId":"ch_work_nvlt_90","text":"述異傳曰：荀朅事母孝，好屬文及道術，潛栖却粒，嘗東遊，憩江夏黃鵠樓上，望西南有物飄然，降自霄漢，俄頃已至，乃駕鶴之賓也，鶴止戶侧，仙者就席，羽衣虹裳，賓已歡對，辭去，跨鶴騰雲，眇然煙滅。","sortOrder":113},
  {"id":"s_work_nvlt_90_114","chapterId":"ch_work_nvlt_90","text":"《異苑》曰：魏安釐王觀翔鵠而樂之，曰：寡人得如鵠之飛，视天下如芥也，客有隱遊者聞之，作木雕而獻王，王曰：此有形無用者也，夫作無用之器，世之奸民也，召遊欲加刑焉，遊曰：大王知有用之用，未寤無用之用也，今臣請為大王翔之，乃取而騎焉，遂翻然飛去，莫知所之。","sortOrder":114},
  {"id":"s_work_nvlt_90_115","chapterId":"ch_work_nvlt_90","text":"《世說》曰：僧支道林好鶴，時有遺其双鶴者，翅長欲飛，林意惜之，乃鍛其翮，鶴軒翥不能复起，乃舒翼反頭视之，如似懊惋，道林曰：既有凌霄之姿，何肯為人耳目玩乎，養令翮成，遂放飛去。","sortOrder":115},
  {"id":"s_work_nvlt_90_116","chapterId":"ch_work_nvlt_90","text":"《風土記》曰：鳴鶴戒露，此鳥性警，至八月白露降，流於草上，滴滴有聲，因即高鳴相警，移徙所宿處，慮有变害也。","sortOrder":116},
  {"id":"s_work_nvlt_90_117","chapterId":"ch_work_nvlt_90","text":"◇白鶴","sortOrder":117},
  {"id":"s_work_nvlt_90_118","chapterId":"ch_work_nvlt_90","text":"《漢書》：宣帝即位，尊孝武廟為代宗，所巡狩至郡國皆立廟，告祠代宗廟日，有白鶴集後庭。","sortOrder":118},
  {"id":"s_work_nvlt_90_119","chapterId":"ch_work_nvlt_90","text":"崔顥［按當作焦贛。］《易林》曰：白鶴衔珠。","sortOrder":119},
  {"id":"s_work_nvlt_90_120","chapterId":"ch_work_nvlt_90","text":"《吳越春秋》曰：吳王阖庐有女，王伐楚，與夫人及女會食蒸魚，王嘗半，女怨曰：王食我殘魚，辱我，不忍久生，乃自殺，阖庐痛之，葬於郡西昌門外，凿地為女墳，積土為山，文石為椁，金鼎玉杯，銀樽珠襦之寶，皆以送女，乃舞白鶴於吳市，令萬民隨觀之，遂使與鵠俱入墓門，因塞之以送死。","sortOrder":120},
  {"id":"s_work_nvlt_90_121","chapterId":"ch_work_nvlt_90","text":"《列仙傳》曰：王子乔見桓良曰：待我缑氏山頭，至期，果乘白鶴住山巔，望之不得到。","sortOrder":121},
  {"id":"s_work_nvlt_90_122","chapterId":"ch_work_nvlt_90","text":"《神仙傳》曰：介象死，吳先帝思之，以象所住屋為廟，時時往祭之，有白鶴來，集坐上也。","sortOrder":122},
  {"id":"s_work_nvlt_90_123","chapterId":"ch_work_nvlt_90","text":"《臨海記》曰：郡西北有白鶴山，周回六十里，高三百丈，有泄水懸註，遙望如倒掛白鶴，因以為名，古老相傳雲，此山昔有晨飛鵠，入會稽雷門鼓中，於是雷門鼓鳴，洛陽聞之，孫恩時，斫此鼓，見白鶴飛出，翱翔入雲，此後鼓無复遠聲，永嘉郡記曰：有洙沐溪，野青田九里中，有双白鵠，年年生子，長大便去，只恒餘父母一双在耳，精白可愛，多雲神仙所養。","sortOrder":123},
  {"id":"s_work_nvlt_90_124","chapterId":"ch_work_nvlt_90","text":"華峤《漢書》曰：崔琦作白鶴賦以諷梁冀，冀幽殺之。","sortOrder":124},
  {"id":"s_work_nvlt_90_125","chapterId":"ch_work_nvlt_90","text":"《列仙傳》曰：蘇耽去後，忽有白鶴十數只，夜集郡東門樓上，一只口畫作書字，言曰：是城郭，人民非，三百甲子當复歸，鹹謂是躭。","sortOrder":125},
  {"id":"s_work_nvlt_90_126","chapterId":"ch_work_nvlt_90","text":"《續搜神記》曰：遼東城門有華表柱，忽有一白鶴集，徘徊空中，言曰：有鳥有鳥丁令威，去家千歲今來歸，城郭如故人民非，何不學仙去，空伴冢累累，遂上冲天。","sortOrder":126},
  {"id":"s_work_nvlt_90_127","chapterId":"ch_work_nvlt_90","text":"◇黃鵠","sortOrder":127},
  {"id":"s_work_nvlt_90_128","chapterId":"ch_work_nvlt_90","text":"《離骚》曰：黃鵠之舉兮，知山川之紆曲，再舉兮知天地之圜方。","sortOrder":128},
  {"id":"s_work_nvlt_90_129","chapterId":"ch_work_nvlt_90","text":"《戰國策》曰：莊辛謂楚襄王曰：黃鵠遊於江海，俯喙鰋鯉，仰斷菱藕，奋其六翮，自以為無患，與人無事，不知夫射者大脩弧矢，治矰繳，將加己百仞之上，故晝遊江湖，夕調鼎俎。","sortOrder":129},
  {"id":"s_work_nvlt_90_130","chapterId":"ch_work_nvlt_90","text":"《韓詩外傳》曰：田饒事魯哀公而不見察，謂哀公曰：夫雞有五德，猶曰瀹而食之者，以其所從來近也，夫黃鵠一舉千里，止君園池，喙君稻粱，君猶貴之，以其所從來遠也，故臣將去君，黃鵠舉矣。","sortOrder":130},
  {"id":"s_work_nvlt_90_131","chapterId":"ch_work_nvlt_90","text":"《漢書》曰：黃鵠下建章宮大液池中，公卿上寿，賜諸侯王列侯宗室金錢也。","sortOrder":131},
  {"id":"s_work_nvlt_90_132","chapterId":"ch_work_nvlt_90","text":"《列女傳》曰：魯陶門女者，少寡養姑，紡績為產，魯人欲求之，女乃歌曰：黃鵠早寡，七年不双，宛胫［《太平御覽》九百十六作頸。］獨宿，不與眾同，飛鳥尚然，况於貞良，魯人聞之，遂不复求。","sortOrder":132},
  {"id":"s_work_nvlt_90_133","chapterId":"ch_work_nvlt_90","text":"《古今註》曰：漢惠帝五年七月，黃鵠二，集萧池。","sortOrder":133},
  {"id":"s_work_nvlt_90_134","chapterId":"ch_work_nvlt_90","text":"◇玄鵠","sortOrder":134},
  {"id":"s_work_nvlt_90_135","chapterId":"ch_work_nvlt_90","text":"《瑞應圖》曰：玄鵠者，王者知音樂之節則至。","sortOrder":135},
  {"id":"s_work_nvlt_90_136","chapterId":"ch_work_nvlt_90","text":"又曰：黃帝習樂崑崙，以舞眾神，玄鵠六翔其右。","sortOrder":136},
  {"id":"s_work_nvlt_90_137","chapterId":"ch_work_nvlt_90","text":"《韓子》曰：師涓鼓新聲，平公問師曠，此何聲也，曰：清商，公曰：最悲乎，師曠曰：不如清徵，公曰：可得聞乎，曠曰：古之得聽清徵者，皆有德義之君，公曰：得试之乎，曠不得已，援琴一奏，有玄鶴二八，道南方來，集於郭門之扈，再奏而列，三奏延胫［《太平御覽》九百十六作頸。］而鳴，舒翼而舞，音中宮商，公大悅，提觴起焉，為師曠寿，其後大旱。","sortOrder":137},
  {"id":"s_work_nvlt_90_138","chapterId":"ch_work_nvlt_90","text":"《離骚》曰：煎鸿鸧［鸧，〈雀鳥〉也。］","sortOrder":138},
  {"id":"s_work_nvlt_90_139","chapterId":"ch_work_nvlt_90","text":"《淮南子》曰：鳳皇曾逝萬仞之上，鸿鵠蒼鶴，莫不憚焉。","sortOrder":139},
  {"id":"s_work_nvlt_90_140","chapterId":"ch_work_nvlt_90","text":"《南越志》曰：开寧縣多晨鵠，［晨居也。］","sortOrder":140},
  {"id":"s_work_nvlt_90_141","chapterId":"ch_work_nvlt_90","text":"【詩】古詩曰：飛來白鶴，從西北來，十五十五，邏迾成行，妻卒被病，不能相隨，五里一反顧，六里一徘徊，吾欲衔汝去，口噤不能开，吾欲負汝去，毛羽日摧頹。","sortOrder":141},
  {"id":"s_work_nvlt_90_142","chapterId":"ch_work_nvlt_90","text":"魏陳王曹植詩曰：双鵠俱遨遊，相失東海傍，雄飛竄北朔，雌驚赴南湘，弃我交頸歡，離別各異方，不惜萬里道，但恐天網張。","sortOrder":142},
  {"id":"s_work_nvlt_90_143","chapterId":"ch_work_nvlt_90","text":"魏何晏詩曰：双鶴比翼遊，群飛戲太清，常恐天網羅，忧禍一旦併，豈若集五湖，順流椄浮萍，逍遙放志意，何為怵惕驚。","sortOrder":143},
  {"id":"s_work_nvlt_90_144","chapterId":"ch_work_nvlt_90","text":"晉阮籍詩曰：鸿鵠相隨去，飛飛適荒裔，双翮凌長風，須臾萬里逝，朝餐琅玕實，夕宿西山际，抗身青雲中，網羅孰能製。","sortOrder":144},
  {"id":"s_work_nvlt_90_145","chapterId":"ch_work_nvlt_90","text":"梁簡文帝詠洲聞獨鶴詩曰：遠霧且氛氲，单飛才可分，孤驚宿屿浦，羁淚下江濆，意惑東西水，心迷四面雲，誰知獨辛苦，江上念離群。","sortOrder":145},
  {"id":"s_work_nvlt_90_146","chapterId":"ch_work_nvlt_90","text":"梁江洪和新浦侯詠鶴詩曰：閒園有孤鶴，摧藏信可怜，寧望春皋下，刷羽玩花钿，何時秋海上，照影弄長川，晓鳴動遙怨，夕唳感孀眠，哀咽芳林君，悯默華池邊，猶冀凌雲志，萬里共翩翩。","sortOrder":146},
  {"id":"s_work_nvlt_90_147","chapterId":"ch_work_nvlt_90","text":"梁吳均詠鶴詩曰：本自乘軒者，為君階下禽，槯藏多好兒，清唳有奇音，稻粱惠以重，華池遇亦深，懷恩未忍去，非無江海心。","sortOrder":147},
  {"id":"s_work_nvlt_90_148","chapterId":"ch_work_nvlt_90","text":"陳劉那賦得獨鶴凌雲去詩曰：孤鳴思沧海，矯翮避虞機，怨別凄琴曲，凌風散舞衣，五里雖回顧，千年會欲歸，寄語雷門鼓，無复一双飛。","sortOrder":148},
  {"id":"s_work_nvlt_90_149","chapterId":"ch_work_nvlt_90","text":"陳阮卓賦得黃鵠一遠別詩，霜風秋月映樓明，寡鶴偏栖中夜驚，月下徘徊顧別影，風前凄斷送離聲，離聲一去斷還續，別响時來疏复促，聊看遠客赠綾紋，弥怨閒宵雅琴曲，恒思昔日稻粱恩，理翮整翰上君軒，獨舞輕飛向吳市，孤鳴清唳出雷門，王子吹笙忽相值，自覺飄飄雲里駛，一舉千里未能歸，唯有田饒解深意。","sortOrder":149},
  {"id":"s_work_nvlt_90_150","chapterId":"ch_work_nvlt_90","text":"【賦】魏王粲白鶴賦曰：白翎禀靈龟之脩寿，資儀鳳之純精，接王乔於湯穀，駕赤松於扶桑，餐靈嶽之琼蕊，吸雲表之露漿。","sortOrder":150},
  {"id":"s_work_nvlt_90_151","chapterId":"ch_work_nvlt_90","text":"魏陳王曹植白鶴賦曰：嗟皓麗之素鳥，含奇氣之淑祥，薄幽林以屏處，荫重景之餘光，狹单巢於弱條，懼冲風之難當，承邂逅之僥倖，得接翼於鸞皇，同毛衣之氣類，信休息而同行，傷本規之违忤，怅離群而獨處，恒竄伏以窮栖，獨哀鳴而戢羽，冀大綱之解結，得奋翅而遠遊，聆雅琴之清均，記六翮之末流。","sortOrder":151},
  {"id":"s_work_nvlt_90_152","chapterId":"ch_work_nvlt_90","text":"晉桓玄鶴賦曰：惟茲禽之受命，谅誕生於悠邈，擢高距以自抗，延脩頸以軒矚，分赪玄以發藻，通太素其如玉，縱眇颺於雲裔，豈四海之難局，練妙氣以遒化，孰百年之易促，稅雲駕於三山，抃鸞皇於崑嶽。","sortOrder":152},
  {"id":"s_work_nvlt_90_153","chapterId":"ch_work_nvlt_90","text":"宋臨川康王鶴賦曰：其状也，绀絡頸而成飾，赪點首以表儀，羽凝素而雪映，尾舒玄而參差，趾象虬以振步，形亚鳳以擅奇。","sortOrder":153},
  {"id":"s_work_nvlt_90_154","chapterId":"ch_work_nvlt_90","text":"宋鮑昭舞鶴賦曰：散幽經以验物，伟胎化之仙禽，指蓬壶而翻翰，望崑阆而扬音，匝日域以回鶩，窮天步而高尋，踐神區其既遠，積靈祀而方多，精含丹而星曜，顶凝紫而煙華，叠霜毛而弄影，振玉羽而臨霞，朝戲於芝田，夕飲乎瑤池，厭江海而遊泽，掩雲羅而見羁，唳清响於丹墀，舞飛容於金閣，始連軒以鳳蹌，終宛轉而龍躍，蹢躅徘徊，振迅騰摧，驚身蓬集，矯翅雪飛，將興中止，若往而歸，雖邯鄲其敢倫，豈陽阿之能擬，入衛國而乘軒，出吳都而傾市，守馴養於千齡，結長悲於萬里。","sortOrder":154},
  {"id":"s_work_nvlt_90_155","chapterId":"ch_work_nvlt_90","text":"梁沈約八詠，聞夜鶴篇曰：聞夜鶴，夜鶴叫南池，對此孤明月，臨風振羽儀，伊吾人之菲薄，無賦命之天爵，愍海上之驚凫，傷雲間之離鶴，離鶴昔未離，近發天北垂，忽值疾風起，蹔下崑明池，欲栖不可住，欲去飛已疲，势逐疾風舉，求溫向衡楚，复值南飛鸿，參差共成侣，海上多雲霧，蒼茫失洲屿，自此別故群，獨向瀟湘渚，故群不離散，相依江海畔，夜止羽相切，晝飛影相亂，刷羽共浮沉，湛澹汎清陰，既不經離別，安知慕侣心，九冬負霜雪，六翮非所任，且養凌雲翅，俯仰弄清音。","sortOrder":155},
  {"id":"s_work_nvlt_90_156","chapterId":"ch_work_nvlt_90","text":"【贊】周庾信鶴贊曰：九皋遙集，三山迥歸，華亭別唳，洛浦仙飛，不防離繳，先遭合围，籠摧月羽，弋碎霜衣，塞傳餘號，關承舊名，南遊湘水，東入遼城，雲飛欲舞，露落先鳴，六翮摧折，九關嚴閉，相顧哀鳴，肝心斷絕，松上長悲，琴中永別。","sortOrder":156},
  {"id":"s_work_nvlt_90_157","chapterId":"ch_work_nvlt_90","text":"【文】晉湛方生弔鶴文曰：餘以玄冬脩夜，忽聞階前有孤鶴鳴，溯寒風而清叫，感凄氣而增悲，屬聽未終，餘有感焉，乃為文以弔之，惟海嵎之奇鳥，資秀氣以誕生，擬鸞皇而比翼，超羽族而獨靈，濯冰霜之素质，颺九皋之奇聲，喙荒庭之遺粒，漱絕涧之餘清，望雲舒而息翮，仰朝霞而晨征，輟王子之靈辔，縶虞人之長纓，辭丹穴之神友，與雞鶩而同庭，軒天衢而奔想，顧樊籠而心驚，獨中宵而增思，負清霜而夜鳴，資冲天之俊翮，曾不殊於鳥雀，禀櫺寿之脩期，忽同彫於秋薄，匪一物之足悲，傷有理而橫落。","sortOrder":157},
  {"id":"s_work_nvlt_90_158","chapterId":"ch_work_nvlt_90","text":"【書】晉鈕滔母與從弟孝徵書曰：省爾譏我以養鵠，乃戒以衛懿滅毙之禍，斯言惑矣，吾未之取，彼衛懿之好，民無役車之載，鵠有乘軒之飾，禍败之由，由乎失所，若乃开圃即於靈囿，沃池矩乎神沼，文魚躍於白水，素鳥翔乎神州，豈非周文之德，大雅所脩哉，夫嘉肴旨酒，非不美也，夏禹盛以陶豆，殷紂貯以玉杯，而此聖以興，彼愚以滅，蓋置之失所，如其無失，來難可施乎。","sortOrder":158},
  {"id":"s_work_nvlt_90_159","chapterId":"ch_work_nvlt_90","text":"【序】晉湛方生羁鶴吟序曰：鄰人王氏，有養鵠者，摧翮虞人之手，心悲志丧，後三年，羽翮既生，翻然高逝，有感餘懷，乃為之吟。","sortOrder":159},
  {"id":"s_work_nvlt_90_160","chapterId":"ch_work_nvlt_90","text":"宋范晔詩序曰：客有寄餘双鵠者，其一扬翰皎絜，响逸九皋，其一翅折志衰，自视缺然，餘因叹玩之，遂為之詩。","sortOrder":160},
  {"id":"s_work_nvlt_90_162","chapterId":"ch_work_nvlt_90","text":"《爾雅》曰：鸕，諸雉，［今雉也。］鷩雉，［長尾，走且鳴。］鷂雉，［青质五采。］鳴［爾雅釋鳥作鳪。］雉，［黃色，鳴自呼。］鷩雉，［似山雞而小。］","sortOrder":162},
  {"id":"s_work_nvlt_90_163","chapterId":"ch_work_nvlt_90","text":"《春秋運斗枢》曰：璣星散為雉。","sortOrder":163},
  {"id":"s_work_nvlt_90_164","chapterId":"ch_work_nvlt_90","text":"《山海經》曰：小華之山，其鳥多赤鷩，可以御火，［鷩雉中。］孟山鳥多白雉。","sortOrder":164},
  {"id":"s_work_nvlt_90_165","chapterId":"ch_work_nvlt_90","text":"《易》曰：離為雉，［取其有文章。］","sortOrder":165},
  {"id":"s_work_nvlt_90_166","chapterId":"ch_work_nvlt_90","text":"《尚書》曰：日月星辰，山龍華虫，［華虫，鷩雉也，五色故謂之華虫。］","sortOrder":166},
  {"id":"s_work_nvlt_90_167","chapterId":"ch_work_nvlt_90","text":"《尚書大傳》曰：武丁祭成湯，有雉飛鼎耳而雊，問諸祖己，曰：雉者野鳥也，不當升鼎，升鼎者，欲為用也，遠方將有來朝者乎，武丁思先王之道，辮發重譯至者六國。","sortOrder":167},
  {"id":"s_work_nvlt_90_168","chapterId":"ch_work_nvlt_90","text":"《禮記》：月令曰：孟冬，雉入大水為蜃。","sortOrder":168},
  {"id":"s_work_nvlt_90_169","chapterId":"ch_work_nvlt_90","text":"《周官》曰：巾車，掌王後之五辂，重翟錫面，［重翟，翟雉之扇。］","sortOrder":169},
  {"id":"s_work_nvlt_90_170","chapterId":"ch_work_nvlt_90","text":"儀禮曰：士相見之禮，贽用雉，［取其耿介。］","sortOrder":170},
  {"id":"s_work_nvlt_90_171","chapterId":"ch_work_nvlt_90","text":"《毛詩》曰：有鷕雉鳴。","sortOrder":171},
  {"id":"s_work_nvlt_90_172","chapterId":"ch_work_nvlt_90","text":"《左傳》曰：贾大夫［贾國大夫。］娶妻而美，不言不笑，御以如皋，射雉獲之，其妻忽言而笑。","sortOrder":172},
  {"id":"s_work_nvlt_90_173","chapterId":"ch_work_nvlt_90","text":"又曰：叔孫豹奔齊，庚宗婦人獻以雉，問其姓，曰：予子長矣，能奉雉而從我矣。","sortOrder":173},
  {"id":"s_work_nvlt_90_174","chapterId":"ch_work_nvlt_90","text":"又曰：郯子雲，五雉為五工正，［五雉見爾雅。］","sortOrder":174},
  {"id":"s_work_nvlt_90_175","chapterId":"ch_work_nvlt_90","text":"《論語》曰：山梁雌雉，時哉時哉，子路拱之，三嗅而作。","sortOrder":175},
  {"id":"s_work_nvlt_90_176","chapterId":"ch_work_nvlt_90","text":"尹《文子》曰：楚人握山雉者，路人問何鳥也，欺之曰：鳳皇也，路人曰：我聞鳳皇，今始見矣，汝販之乎，請買，千金弗與，請加倍，乃與之，方欲獻楚王，經宿死，路人不遑惜其金，惟恨不得獻王，王聞之，感其欲獻己，召厚賜之，過買鳥之金十倍。","sortOrder":176},
  {"id":"s_work_nvlt_90_177","chapterId":"ch_work_nvlt_90","text":"《莊子》曰：泽雉十步一啄，百步一飲，不期畜乎樊中。","sortOrder":177},
  {"id":"s_work_nvlt_90_178","chapterId":"ch_work_nvlt_90","text":"《列異傳》曰：秦穆公時，陳仓人掘地得物，若羊非羊，若猪非猪，牵以獻穆公，道逢二童子，童子曰：此名為媪，常在地食死人腦，若欲殺之，以柏插其首，媪复曰：彼二童，名為陳寶，得雄者王，得雌者霸，陳仓人舍媪，逐二童子，童子化為雉，飛入乎林，陳仓人告穆公，穆公發徒大獵，果得雌。又化為石，置之汧渭之間，至文公，為立祠，名陳寶，雄飛南集，今南陽雉縣，其地也，秦欲表其符，故以名縣，每陳仓祠時，有赤光長十餘丈，從雉縣來，入陳仓祠中，有聲如雄雌，［《太平御覽》九百十七作雉。］","sortOrder":178},
  {"id":"s_work_nvlt_90_179","chapterId":"ch_work_nvlt_90","text":"《洪范五行傳》曰：正月雷微而雉雊，雷通氣也。","sortOrder":179},
  {"id":"s_work_nvlt_90_180","chapterId":"ch_work_nvlt_90","text":"楊雄琴清英曰：雉朝飛操者，衛女傅母之所作也，衛侯女嫁於齊太子，中道聞太子死，問傅母曰：何如，傅母曰：且往當丧，丧畢不肯歸，終之以死，傅母悔之，取女所自操琴，於冢上鼓之，忽二雉俱出墓中，傅母撫雉曰：女果為雉耶，言未畢，俱飛而起，忽然不見，傅母悲痛，援琴作操，故曰雉朝飛。","sortOrder":180},
  {"id":"s_work_nvlt_90_181","chapterId":"ch_work_nvlt_90","text":"《琴操》曰：齊獨沐子，年七十無妻，朝出，見飛雉雌雄相隨，感之，撫琴而歌曰：雉朝飛，鳴相和，雄雌群遊於山河。","sortOrder":181},
  {"id":"s_work_nvlt_90_182","chapterId":"ch_work_nvlt_90","text":"《漢武帝故事》曰：上幸梁父，祠地主，上親拜庶羞，以遠方奇禽異獸，及白雉白乌之屬，其日山上有白雲。又呼萬歲者。","sortOrder":182},
  {"id":"s_work_nvlt_90_183","chapterId":"ch_work_nvlt_90","text":"《東觀漢記》曰：魯恭為中牟令，蝗虫不入縣界，河南尹遣郡掾肥親验之，坐树下，雉過止恭侧，旁有小兒，親曰：何不击之，兒言雉將雏，可怜，親叹其三異。","sortOrder":183},
  {"id":"s_work_nvlt_90_184","chapterId":"ch_work_nvlt_90","text":"魏書曰：太祖才力絕人，於南皮，一日射雉，獲六十三頭。","sortOrder":184},
  {"id":"s_work_nvlt_90_185","chapterId":"ch_work_nvlt_90","text":"《魏志》曰：侍中辛毗，從文帝射雉，帝曰：樂哉，毗曰：於陛下甚樂，於群下甚苦，帝默然，為之希出。","sortOrder":185},
  {"id":"s_work_nvlt_90_186","chapterId":"ch_work_nvlt_90","text":"《吳志》曰：孫休銳意於典籍，欲畢覽百家之言，大好射雉，春秋之間，常晨出夜還，惟此時舍書。","sortOrder":186},
  {"id":"s_work_nvlt_90_187","chapterId":"ch_work_nvlt_90","text":"《江表傳》曰：孫權數射雉，潘濬諫權，權曰：時時蹔出耳，不复如往日也，濬曰：天下未定，萬機務多，射雉非急，絃絕括破，皆能為害，濬乃手自撤坏雉翳，權由是遂絕不复射雉，枹朴子曰：白雉有种，南越尤多，按地域圖，今之九德，則古之越裳也，蓋白雉之所出，周成王所以為瑞者，貴其所自來之遠，明其德化所被之廣，非謂此為奇也。","sortOrder":187},
  {"id":"s_work_nvlt_90_188","chapterId":"ch_work_nvlt_90","text":"晉成康［《太平御覽》六百九十四作鹹寧。］起居註曰：大医司馬程據，上雉頭裘，詔於殿前燒之。","sortOrder":188},
  {"id":"s_work_nvlt_90_189","chapterId":"ch_work_nvlt_90","text":"《博物志》曰：翟雉長尾，雨雪惜其尾，栖高树杪，不敢下食，往往饿死。","sortOrder":189},
  {"id":"s_work_nvlt_90_190","chapterId":"ch_work_nvlt_90","text":"萧廣濟《孝子傳》曰：萧芝至孝，除尚書郎，有雉數十頭，飲啄宿止，當上直，送至歧路，下直入門，飛鳴車侧。","sortOrder":190},
  {"id":"s_work_nvlt_90_191","chapterId":"ch_work_nvlt_90","text":"宋略，孝武帝嘗出射雉，值雨，侍中沈懷文諫曰：非止千乘失容，亦乃聖躬櫛沐。","sortOrder":191},
  {"id":"s_work_nvlt_90_192","chapterId":"ch_work_nvlt_90","text":"【詩】宋鮑昭詩曰：雉朝飛，振羽翼，专場俠兩雌，恃強力，媒已驚，翳已逼，黃間潛彀盧矢直，刎繡頸，碎錦臆，絕命君前無怨色。","sortOrder":192},
  {"id":"s_work_nvlt_90_193","chapterId":"ch_work_nvlt_90","text":"梁簡文帝雉朝飛詩曰：晨光照夌畿，平野度春暉，避鷹時耸角，妒垄或斜飛，少年從遠役，有恨意多违，不如隨遊荡，羅袂拂臣衣。","sortOrder":193},
  {"id":"s_work_nvlt_90_194","chapterId":"ch_work_nvlt_90","text":"陳萧有射雉詩曰：二月春翚動，曹王俠妒媒，插翳依花合，芟場向野开，隔田聞雉近，橫溪見影來，絃明青壓碎，箭落錦衣摧，今日如皋路，能將巧笑回。","sortOrder":194},
  {"id":"s_work_nvlt_90_195","chapterId":"ch_work_nvlt_90","text":"【賦】晉王叔之翟雉賦曰：餘在荆楚，見人有養雉翟二鳥者，慨然感之，而為賦之，含野氣於人涂，信多懼而少嘉，雉見质而不陋，翟表文而弗華，映寒條之始绿，發冬秀之餘葩。","sortOrder":195},
  {"id":"s_work_nvlt_90_196","chapterId":"ch_work_nvlt_90","text":"晉傅純雉賦曰：覽飛禽之可貴，伟翔雉之嘉形，應炎離之誕育，包造化之淳精，鮮光皎粲，麗采繁盈，首同暉於昊天，垂玄景之绿青，體等耀於方彩，敷五色之華英。","sortOrder":196},
  {"id":"s_work_nvlt_90_197","chapterId":"ch_work_nvlt_90","text":"晉傅玄雉賦曰：禀炎離之正氣，應朱火之禎祥，播五彩之繁縟，被華文而成章，冠列角之盛儀，翘從風而飄扬，履嚴距之武節，超鸞跱而鳳翔，感天和而貽瑞，進據鼎而祚商，樂周道之方隆，敷皓质於越裳。","sortOrder":197},
  {"id":"s_work_nvlt_90_198","chapterId":"ch_work_nvlt_90","text":"晉孫楚翟賦曰：體冲和之淑质，飾羽儀於茂林，斑五色之文章，扬曒曒之清音，設密網於巖阿，飛輕激之雲浮，上無逃而弗獲，下無隱而不搜，遂戢翼以就養，隨籠栖而言歸，恒逍遙於階庭，荫朝陽之盛暉。","sortOrder":198},
  {"id":"s_work_nvlt_90_199","chapterId":"ch_work_nvlt_90","text":"【表】宋孝武帝在藩上白雉表曰：白體表素彩儀，禀識自扰，陶氣仁風，練色淳露，不蘄一飲之逸，不資三逸之勤。","sortOrder":199},
  {"id":"s_work_nvlt_90_200","chapterId":"ch_work_nvlt_90","text":"【啟】周庾信謝趙王赉雉啟曰：夏翟秋飛，江翚春涧，中牟縣之客，遂得坐觀，贾大夫之妻，已應含笑，仰費中厨，來供下客，山川道遠，口腹知恩。","sortOrder":200},
  {"id":"s_work_nvlt_90_202","chapterId":"ch_work_nvlt_90","text":"《說文》曰：鶡似雉，出上党。","sortOrder":202},
  {"id":"s_work_nvlt_90_203","chapterId":"ch_work_nvlt_90","text":"月令曰：大雪之日，鶡鳥不鳴。","sortOrder":203},
  {"id":"s_work_nvlt_90_204","chapterId":"ch_work_nvlt_90","text":"《列子》曰：黃帝與炎帝戰，以雕鶡為旗幟。","sortOrder":204},
  {"id":"s_work_nvlt_90_205","chapterId":"ch_work_nvlt_90","text":"《漢書》曰：京兆尹張敞舍，鶡雀飛集，丞相霸以為神雀，欲以上聞，敞劾奏之，霸大慚。","sortOrder":205},
  {"id":"s_work_nvlt_90_206","chapterId":"ch_work_nvlt_90","text":"續《漢書》：舆服志曰：虎贲武騎，皆鶡冠，以其斗死乃止，故趙武靈王以表武士焉。","sortOrder":206},
  {"id":"s_work_nvlt_90_207","chapterId":"ch_work_nvlt_90","text":"【賦】魏陳王曹植鶡賦曰：鶡之為禽猛氣，其斗，終無勝負，期於必死，遂賦之焉，美遐圻之伟鳥，生太行之巖阻，體貞刚之烈性，亮金德之所辅，戴毛角之双立，扬玄黃之劲羽，甘沈殒而重辱，有節俠之儀矩，降居檀泽，高處保岑，遊不同嶺，栖必異林，若有翻雄駭逝，孤雌驚翔，則長鳴挑敵，鼓翼专場，逾高越壑，双戰只僵，階侍斯珥，俯曜文墀，成武官之首飾，增庭燎之高暉。","sortOrder":207},
  {"id":"s_work_nvlt_90_208","chapterId":"ch_work_nvlt_90","text":"魏王粲鶡賦曰：惟茲鶡之為鳥，信才勇而劲武，服乾刚之正氣，被淳駹之质羽，愬晨風以群鳴，震聲發乎外宇，厲廉風與猛節，超群類而莫與，惟膏薰之焚銷，固自古之所咨，逢虞人而見獲，遂囚執乎緤累，賴有司之圖功，不开小而漏微，令薄軀以免害，從孔鶴於園湄。","sortOrder":208},
  {"id":"s_work_nvlt_90_209","chapterId":"ch_work_nvlt_90","text":"【贊】晉郭璞鶡贊曰：鶡之為鳥，同群相為，畴類被侵，雖死不避，毛飾武士，兼厲以義。","sortOrder":209},
  {"id":"s_work_nvlt_90_210","chapterId":"ch_work_nvlt_90","text":"《藝文類聚》　唐·欧陽詢","sortOrder":210},
  {"id":"s_work_nvlt_91_1","chapterId":"ch_work_nvlt_91","text":"卷九十一鳥部中","sortOrder":1},
  {"id":"s_work_nvlt_91_2","chapterId":"ch_work_nvlt_91","text":"○孔雀鸚鵡青鳥雁鹅鸭雞山雞鷹鷂","sortOrder":2},
  {"id":"s_work_nvlt_91_3","chapterId":"ch_work_nvlt_91","text":"◇孔雀","sortOrder":3},
  {"id":"s_work_nvlt_91_4","chapterId":"ch_work_nvlt_91","text":"《春秋元命苞》曰：火離為孔雀。","sortOrder":4},
  {"id":"s_work_nvlt_91_5","chapterId":"ch_work_nvlt_91","text":"《周書》曰：成王時，西方人獻孔雀。","sortOrder":5},
  {"id":"s_work_nvlt_91_6","chapterId":"ch_work_nvlt_91","text":"《楚辭》曰：孔蓋兮翠旌。［孔雀之羽為車蓋。］","sortOrder":6},
  {"id":"s_work_nvlt_91_7","chapterId":"ch_work_nvlt_91","text":"《鹽鐵論》曰：南越以孔雀珥門戶，今貴其所饒，非所以厚中國也。","sortOrder":7},
  {"id":"s_work_nvlt_91_8","chapterId":"ch_work_nvlt_91","text":"《神仙傳》曰：萧史吹箫，常致孔雀。","sortOrder":8},
  {"id":"s_work_nvlt_91_9","chapterId":"ch_work_nvlt_91","text":"《漢書》曰：尉佗獻文帝孔雀二双。","sortOrder":9},
  {"id":"s_work_nvlt_91_10","chapterId":"ch_work_nvlt_91","text":"《西域傳》曰：罽賓國出孔雀。","sortOrder":10},
  {"id":"s_work_nvlt_91_11","chapterId":"ch_work_nvlt_91","text":"《續漢書》曰：西南夷曰滇池，出孔雀。","sortOrder":11},
  {"id":"s_work_nvlt_91_12","chapterId":"ch_work_nvlt_91","text":"又雲，西域條支國，出孔雀。","sortOrder":12},
  {"id":"s_work_nvlt_91_13","chapterId":"ch_work_nvlt_91","text":"魏文帝詔朝臣曰：前於闐王山習，所上孔雀尾萬枚，文彩五色，以為金根車蓋，遙望曜人眼。","sortOrder":13},
  {"id":"s_work_nvlt_91_14","chapterId":"ch_work_nvlt_91","text":"《郭子》曰：梁國楊氏子，年九歲，甚聰慧，孔君平詣其父，父不在，乃呼兒出，為設果，有楊梅，孔指以示兒，此貴君家果，兒應聲答曰：未聞孔雀是夫子家禽。","sortOrder":14},
  {"id":"s_work_nvlt_91_15","chapterId":"ch_work_nvlt_91","text":"晉公卿贊曰：世祖時，西域獻孔雀，解人語，馴指，應節起舞。","sortOrder":15},
  {"id":"s_work_nvlt_91_16","chapterId":"ch_work_nvlt_91","text":"楊孝元交州《異物志》曰：孔雀，人拍其尾則舞。","sortOrder":16},
  {"id":"s_work_nvlt_91_17","chapterId":"ch_work_nvlt_91","text":"【賦】魏楊脩孔雀賦曰：魏王園中有孔雀，久在池沼，與眾鳥同列，其初至也。甚見奇伟，而今行者莫眡，臨淄侯感世人之待士，亦鹹如此，故興志而作賦，併見命及，遂作賦曰：有南夏之孔雀，同號稱於火精，寓鶉虛以挺體，含正陽之淑靈，首戴冠以飾貌，爰龟背而鸞頸，徐軒翥以俯仰，動止步而有程。","sortOrder":17},
  {"id":"s_work_nvlt_91_18","chapterId":"ch_work_nvlt_91","text":"魏鍾會孔雀賦曰：有炎方之伟鳥，感靈和而來儀，禀麗精以挺质，生丹穴之南垂，戴翠旄以表弁，垂绿蕤之森纚，戴脩尾之翘翘，若順風而扬麾，五色點註，華羽參差，鱗交綺错，文藻陆離，丹口金辅，玄目素規，或舒翼軒峙，奋迅洪姿，或蹀足踟蹰，鳴嘯鬱咿。","sortOrder":18},
  {"id":"s_work_nvlt_91_19","chapterId":"ch_work_nvlt_91","text":"晉左九嫔孔雀賦曰：戴绿碧之秀毛，棹翠尾之脩茎，飲芳桂之凝露，食秋菊之落英，耀丹紫之倏烁，應晨風以悲鳴。","sortOrder":19},
  {"id":"s_work_nvlt_91_20","chapterId":"ch_work_nvlt_91","text":"◇鸚鵡","sortOrder":20},
  {"id":"s_work_nvlt_91_21","chapterId":"ch_work_nvlt_91","text":"《禮記》曰：鸚鵡能言，不離飛鳥。","sortOrder":21},
  {"id":"s_work_nvlt_91_22","chapterId":"ch_work_nvlt_91","text":"《淮南子》曰：鸚鵡能言，而不可使長言，是得其所言，不得所以言。","sortOrder":22},
  {"id":"s_work_nvlt_91_23","chapterId":"ch_work_nvlt_91","text":"《萬畢術》曰：乾睪一名鸚鵡，斷舌可使言語。","sortOrder":23},
  {"id":"s_work_nvlt_91_24","chapterId":"ch_work_nvlt_91","text":"吳時外國傳曰：扶南東有涨海，海中有洲，出五色鸚鵡，其白者如母雞。","sortOrder":24},
  {"id":"s_work_nvlt_91_25","chapterId":"ch_work_nvlt_91","text":"《異苑》曰：張華有白鸚鵡，華每出行還，辄說僮仆善惡，後寂無言，華問其故，鳥雲，見藏瓮中，何由得知，公复在外，令唤鸚鵡，鸚鵡曰：昨夜夢惡，不宜出戶，公猶強之，至庭，為鹯所搏，教其啄鹯腳，仅而獲免。","sortOrder":25},
  {"id":"s_work_nvlt_91_26","chapterId":"ch_work_nvlt_91","text":"《宣验記》曰：有鸚鵡飛集他山，山中禽辄相愛重，鸚鵡自念，雖樂不可久也，便去，後數月，山中大火，鸚鵡遙見，便入水霑羽飛而洒之，天神言，汝雖有志意，何足雲也，對曰：雖知不能救，然嘗侨居是山，禽獸行善，皆為兄弟，不忍見耳，天神嘉感，即為滅火。","sortOrder":26},
  {"id":"s_work_nvlt_91_27","chapterId":"ch_work_nvlt_91","text":"沈約《宋書》曰：謝莊為太子庶子，時南平王鑠，上赤鸚鵡，普詔群臣為賦，太子左衛率府袁淑，文冠當時，作賦畢，赍以示莊，莊賦亦竟，淑見而叹曰：江東無我，卿當獨秀，我若無卿，亦一時之杰也，遂隱其賦。","sortOrder":27},
  {"id":"s_work_nvlt_91_28","chapterId":"ch_work_nvlt_91","text":"【賦】後漢祢衡鸚鵡賦曰：時黃祖太子射，賓客大會，有獻鸚鵡者，舉酒於衡前曰：今日無以娱賓，竊以此鳥，自遠而至，明慧聰善，原先生為之賦，衡筆不停缀，文不加點。","sortOrder":28},
  {"id":"s_work_nvlt_91_29","chapterId":"ch_work_nvlt_91","text":"魏陳王曹植鸚鵡賦曰：美洲中之令鳥，超眾類之殊名，感陽和而振翼，遁太陰以存形，遇旅人之嚴網，殊六翮而無遺，身掛滯於重緤，孤雌鳴而獨歸，豈餘身之足惜，怜眾雏之未飛，分麋軀以润镬，何全濟之敢希，蒙含育之厚德，奉君子之光辉，怨身輕而施重，恐往惠之中虧，常戢心以懷懼，雖處安其若危，永哀鳴以報德，庶終來而不疲。","sortOrder":29},
  {"id":"s_work_nvlt_91_30","chapterId":"ch_work_nvlt_91","text":"魏應玚鸚鵡賦曰：何翩翩之麗鳥，表眾艳之殊色，被光耀之鮮羽，流玄黃之華飾，苞明哲之弘慮，從陰陽之消息，秋風厲而潛形，蒼神發而動翼。","sortOrder":30},
  {"id":"s_work_nvlt_91_31","chapterId":"ch_work_nvlt_91","text":"魏陳琳鸚鵡賦曰：咨乾坤之兆物，萬品错而殊形，有逸姿之令鳥，含嘉淑之哀聲，抱振鷺之素质，被翠羽之縹精。","sortOrder":31},
  {"id":"s_work_nvlt_91_32","chapterId":"ch_work_nvlt_91","text":"魏王粲鸚鵡賦曰：步籠阿以踯躅，叩眾目之希稠，登衡幹以上千，噭哀鳴而舒忧，聲嘤嘤以高厲。又憀憀而不休，聽乔木之悲風，羨鳴友之相求，日奄藹以西邁，忽逍遙而既冥，就隅角而斂翼，倦獨宿而宛頸。","sortOrder":32},
  {"id":"s_work_nvlt_91_33","chapterId":"ch_work_nvlt_91","text":"魏阮瑀鸚鵡賦曰：惟翩翩之艳鳥，誕嘉類於京都，秽夷風而弗處，慕聖惠而來徂，被坤文之黃色，服離光之朱形，配秋英以離绿，苞天地以耀榮。","sortOrder":33},
  {"id":"s_work_nvlt_91_34","chapterId":"ch_work_nvlt_91","text":"晉傅玄鸚鵡賦曰：奇毛曜體，绿采含英，鳳翔鸞跱，孔质翠榮，發言辄應，若响追聲。","sortOrder":34},
  {"id":"s_work_nvlt_91_35","chapterId":"ch_work_nvlt_91","text":"晉左九嫔賦曰：色則丹喙翠尾，绿翼紫頸，秋敷其色，春耀其榮。","sortOrder":35},
  {"id":"s_work_nvlt_91_36","chapterId":"ch_work_nvlt_91","text":"晉盧諶賦曰：有遐方之奇鳥，產瓜州之舊壤，揮绿翰以運影，啟丹觜以振响。","sortOrder":36},
  {"id":"s_work_nvlt_91_37","chapterId":"ch_work_nvlt_91","text":"晉傅鹹賦曰：有金商之奇鳥，處隴坻之高松，謂崇峻之可固，然以慧而入籠，披丹唇以授音，亦尋响而應聲，眄明眸以承顏，侧聰耳而有聽，口才發而輕和，密晷景而隨形，言無往而不复，似探幽而测冥，自嘉智於君子，足取愛而扬名。","sortOrder":37},
  {"id":"s_work_nvlt_91_38","chapterId":"ch_work_nvlt_91","text":"晉曹毗賦曰：餘在直，見交州獻鸚鵡鳥，嘉其有智，叹其籠樊，乃賦之曰：其形則雉顧鵠眄，鷹跱雁息，丹喙含暎，緗葩煥翼，森森脩尾，蔚蔚紅臆，金采員婴於双眸，朱藻烂暉於首侧。","sortOrder":38},
  {"id":"s_work_nvlt_91_39","chapterId":"ch_work_nvlt_91","text":"晉桓玄鸚鵡賦曰：有遐方之令鳥，超羽族之拔萃，翔清曠之遼朗，栖高松之幽蔚，羅萬里以作貢，婴樊绁以勤瘁，紅腹赪足，玄頷翠顶，革好音以遷善，效言語以自騁，翦羽翮以應用，充戲玩於軒屏。","sortOrder":39},
  {"id":"s_work_nvlt_91_40","chapterId":"ch_work_nvlt_91","text":"宋顏延之白鸚鵡賦曰：雖言禽之末品，妙六氣而剋生，往秘奇於鬼服，來充美於華京，恨儀鳳之無辨，惜晨鹥之徒暄，思受命於黃發，獨含辭而采言，起交河之榮薄，出天山之無垠，既達美於天居，亦俪景於雲阿，漸惠和之方渥，缀風土而未訛，服琐翮於短衿，仰梢雲之曾柯，觊天網之一布，漏微翰於山阿。","sortOrder":40},
  {"id":"s_work_nvlt_91_41","chapterId":"ch_work_nvlt_91","text":"宋謝莊赤鸚鵡賦曰：徒觀其柔儀所踐，赪藻所挺，華景夕映，容光晦鮮，惠性生昭，和機自晓，審國音於寰中，達方聲於裔表，及其雲移霞峙，霰委雪翻，陆離翚漸，容裔鸿軒，躍林飛岫，煥若輕電，溢煙門，集場圃，晔若夭桃被玉園，至於氣淳體净，霧下崖沉，月圖光於绿水，雲寫影於青林，溯還風而耸翮，霑清露而調音。","sortOrder":41},
  {"id":"s_work_nvlt_91_42","chapterId":"ch_work_nvlt_91","text":"梁昭明太子鸚鵡賦曰：有能言之奇鳥，每知來而發聲，乍青质而翠映，或體白而雪明，喙前鉤而趨步，翼高舞而翩翾，足若丹而三布，目如金而双圓。","sortOrder":42},
  {"id":"s_work_nvlt_91_43","chapterId":"ch_work_nvlt_91","text":"【贊】晉郭璞山海圖贊曰：鸚鵡慧鳥，栖林啄蕊，四指中分，行則以觜，自貽伊籠，見幽坐伎。","sortOrder":43},
  {"id":"s_work_nvlt_91_44","chapterId":"ch_work_nvlt_91","text":"◇青鳥","sortOrder":44},
  {"id":"s_work_nvlt_91_45","chapterId":"ch_work_nvlt_91","text":"《山海經》曰：三危之山，有青鳥居之，［青鳥主為西王母取食者，引自栖息於此山也。］","sortOrder":45},
  {"id":"s_work_nvlt_91_46","chapterId":"ch_work_nvlt_91","text":"紀年曰：穆王十三年，西征至於青鳥之所憩。","sortOrder":46},
  {"id":"s_work_nvlt_91_47","chapterId":"ch_work_nvlt_91","text":"《漢武故事》曰：七月七日，上於承華殿斋，正中，忽有一青鳥從西方來，集殿前，上問東方朔，朔曰：此西王母欲來也，有頃，王母至，有二青鳥如乌，俠侍王母旁。","sortOrder":47},
  {"id":"s_work_nvlt_91_48","chapterId":"ch_work_nvlt_91","text":"又曰：鉤弋夫人卒，上為起通靈台，常有一青鳥集台上。","sortOrder":48},
  {"id":"s_work_nvlt_91_49","chapterId":"ch_work_nvlt_91","text":"《晉中興書》曰：顏含嫂病困，須髯蛇胆，不能得，含忧叹累日，忽有一童子，持青裹授含，乃蛇胆也，童子化為青鳥，飛去。","sortOrder":49},
  {"id":"s_work_nvlt_91_50","chapterId":"ch_work_nvlt_91","text":"《神仙傳》曰：東陵聖母，廣陵海陵人杜氏妻也，學劉綱道，坐在立亡，杜公不信，誣言聖母作奸，收付獄，聖母從窗中飛去，於是遠近為立廟，甚有神验，常有一青鳥在祭所，人有失物者，青鳥便飛集物上，路無拾遺。","sortOrder":50},
  {"id":"s_work_nvlt_91_51","chapterId":"ch_work_nvlt_91","text":"【贊】晉郭璞青鳥贊曰：山名三危，青鳥所憩，往來崑崙，王母是隸，穆王西征，旋軫斯地。","sortOrder":51},
  {"id":"s_work_nvlt_91_53","chapterId":"ch_work_nvlt_91","text":"《爾雅》曰：凫雁丑，其足蹼，［腳指間有幕蹼屬相著。］","sortOrder":53},
  {"id":"s_work_nvlt_91_54","chapterId":"ch_work_nvlt_91","text":"《方言》曰：自關而東謂之雁。","sortOrder":54},
  {"id":"s_work_nvlt_91_55","chapterId":"ch_work_nvlt_91","text":"《海內經》曰：雁門山，雁出其間，在高柳北。","sortOrder":55},
  {"id":"s_work_nvlt_91_56","chapterId":"ch_work_nvlt_91","text":"《禮記》曰：季冬之月，雁北向。","sortOrder":56},
  {"id":"s_work_nvlt_91_57","chapterId":"ch_work_nvlt_91","text":"《周書》曰：白露之日，鸿雁來，寒露之日。又來。","sortOrder":57},
  {"id":"s_work_nvlt_91_58","chapterId":"ch_work_nvlt_91","text":"《儀禮》曰：婚禮下達，納采用雁。","sortOrder":58},
  {"id":"s_work_nvlt_91_59","chapterId":"ch_work_nvlt_91","text":"《毛詩》曰：雍雍鳴雁，旭日始旦。","sortOrder":59},
  {"id":"s_work_nvlt_91_60","chapterId":"ch_work_nvlt_91","text":"《莊子》曰：山木以不材，得終其天年，出於山，及邑，舍故人之家，令竖子殺雁烹之，竖子請曰：其一雁能鳴，其一不能鳴，請奚殺，主人曰：殺不能鳴者，弟子問曰：山中之木，以不材得其天年，主人之雁，以不材而死，先生何處焉，莊子笑曰：周將處夫材與不材之間乎。","sortOrder":60},
  {"id":"s_work_nvlt_91_61","chapterId":"ch_work_nvlt_91","text":"《史記》曰：蘇武在匈奴中，昭帝遣使通和，武思歸，乃夜見漢使，教使謂单於曰：天子射上林中，得雁，足有系帛書，言武等在其泽中，使者如其言，单於大驚，乃使武還。","sortOrder":61},
  {"id":"s_work_nvlt_91_62","chapterId":"ch_work_nvlt_91","text":"《淮南子》曰：夫雁從風而飛，以愛氣力，衔芦而翔，似備弋繳。","sortOrder":62},
  {"id":"s_work_nvlt_91_63","chapterId":"ch_work_nvlt_91","text":"《說苑》曰：秦穆公得百里奚，公孫支歸取雁以贺曰：君得社稷之臣，敢贺社稷之福，公不辭，再拜而受。","sortOrder":63},
  {"id":"s_work_nvlt_91_64","chapterId":"ch_work_nvlt_91","text":"《續漢書》曰：陳群父子，併著高名，世號三君，每宰府辟召，常同時旌命，羔雁成群，當世者靡不榮之。","sortOrder":64},
  {"id":"s_work_nvlt_91_65","chapterId":"ch_work_nvlt_91","text":"鄭氏婚禮謁文贊曰：雁候陰陽，待時乃舉，冬南夏北，貴其有所。","sortOrder":65},
  {"id":"s_work_nvlt_91_66","chapterId":"ch_work_nvlt_91","text":"《會稽典錄》曰：虞國少有孝行，為日南太守，常有双雁，宿止廳上，每出行縣，辄飛逐車，既卒於官，雁逐丧還至餘姚，住墓前，歷三年乃去。","sortOrder":66},
  {"id":"s_work_nvlt_91_67","chapterId":"ch_work_nvlt_91","text":"盛弘之《荆州記》曰：雁塞北接梁州汶陽郡，其間東西嶺，屬天無际，雲飛風翥，望崖回翼，唯一處為下，朔雁達塞，矯翮裁度，故名雁塞，同於雁門也。","sortOrder":67},
  {"id":"s_work_nvlt_91_68","chapterId":"ch_work_nvlt_91","text":"邓德明《南康記》曰：平固縣有覆笥山，上有湖，周回數十里，有石雁浮在湖中，每至秋天，石雁飛鳴，如候時也。","sortOrder":68},
  {"id":"s_work_nvlt_91_69","chapterId":"ch_work_nvlt_91","text":"【詩】魏應玚詩曰：朝雁鳴雲中，音响一何哀，問子遊何乡，戢翼正徘徊，言我塞門來，將就衡陽栖，往春翔朔土，今冬客南淮，遠行蒙霜露，毛羽日摧頹，常恐傷肌骨，身陨沈黃泥。","sortOrder":69},
  {"id":"s_work_nvlt_91_70","chapterId":"ch_work_nvlt_91","text":"梁簡文帝賦得隴坻雁初飛詩曰：高翔憚闊海，下去怯虞機，霧闇早相失，沙明還共飛，隴狹朝聲聚，風急暮行稀，雖殄輪台援，未解龍城围，相思不得反，且寄別書歸。","sortOrder":70},
  {"id":"s_work_nvlt_91_71","chapterId":"ch_work_nvlt_91","text":"夜望单飛雁詩曰：天霜河白夜星稀，一雁聲嘶何處歸，早知半路應相失，不如從來本獨飛。","sortOrder":71},
  {"id":"s_work_nvlt_91_72","chapterId":"ch_work_nvlt_91","text":"梁沈約詠湖中雁詩曰：白水滿春塘，旅雁每回翔，唼蓱牵弱藻，斂翮帶餘霜，懸飛竟不下，亂起未成行，刷羽同搖漾，一舉還故乡。","sortOrder":72},
  {"id":"s_work_nvlt_91_73","chapterId":"ch_work_nvlt_91","text":"梁劉孝綽賦得始歸雁詩曰：洞庭春水绿，衡陽旅雁歸，差池高复下，欲向龍門飛。","sortOrder":73},
  {"id":"s_work_nvlt_91_74","chapterId":"ch_work_nvlt_91","text":"梁萧子范夜聽雁詩曰：天月廣夜辉，遊雁犯霜飛，連翩辭朔氣，嘹唳獨南歸，夜長寒复靜，燈光暧欲微，凄凄不可聽，何况觸愁機。","sortOrder":74},
  {"id":"s_work_nvlt_91_75","chapterId":"ch_work_nvlt_91","text":"周王褒詠雁詩曰：伺朝間曙响，妒垄有春翚，豈若雲中雁，秋時塞外歸，河長猶可涉，海闊故難飛，霜多聲轉急，風疏行屢稀，園池若可至，不复怯虞機。","sortOrder":75},
  {"id":"s_work_nvlt_91_76","chapterId":"ch_work_nvlt_91","text":"周庾信賦得集池雁詩曰：逢風時迥度，逐侣乍爭飛，猶憶方塘水，今秋已复歸。","sortOrder":76},
  {"id":"s_work_nvlt_91_77","chapterId":"ch_work_nvlt_91","text":"又詠雁詩曰：南思洞庭水，北想雁門關，稻粱俱可恋，飛去复飛還。","sortOrder":77},
  {"id":"s_work_nvlt_91_78","chapterId":"ch_work_nvlt_91","text":"【賦】魏陳王曹植離繳雁賦曰：餘遊於玄武陂中，有雁離繳，不能复飛，顧命舟人，追而得之，故怜而賦焉，怜孤雁之偏特，情惆焉而內傷，合中和之純氣，赴四節而征行，遠玄冬於南裔，避炎夏乎朔方，掛微軀之輕翼，忽頹落而離群，旅朋驚而鳴逝，徒矯首而莫聞，甘充君之下厨，膏函牛之鼎镬，蒙生全之顧覆，何恩施之隆博，於是縱軀歸命，無慮無求，飢食粱稻，渴飲清流。","sortOrder":78},
  {"id":"s_work_nvlt_91_79","chapterId":"ch_work_nvlt_91","text":"晉羊祜雁賦曰：鳴則相和，行則接武，前不絕貫，後不越序，齊力不期而併至，同趣不要而自聚，當其赴節，則萬里不能足其路，苟泛一壑，則眾物不能易其所，臨空不能頓其翼，扬波不能瀸其羽。","sortOrder":79},
  {"id":"s_work_nvlt_91_80","chapterId":"ch_work_nvlt_91","text":"晉孫楚雁賦曰：有逸豫之俊禽，禀和氣之清冲，候天時以動靜，隨寒暑而污隆，飒同集於曠野，紛群翔於雲中，翳朝陽之景曜，角聲势於晨風，族類阜繁，數則千亿，迎素秋而南遊，背青春而北息，溯長川以鳴號，凌洪波以鼓翼，任自然而相佯，窮天壤於八極。","sortOrder":80},
  {"id":"s_work_nvlt_91_82","chapterId":"ch_work_nvlt_91","text":"《廣志》曰：鴐鹅，野鹅也。","sortOrder":82},
  {"id":"s_work_nvlt_91_83","chapterId":"ch_work_nvlt_91","text":"《列子》曰：黃帝與炎帝戰，以雕鶡鷹雁鹅為旗幟。","sortOrder":83},
  {"id":"s_work_nvlt_91_84","chapterId":"ch_work_nvlt_91","text":"魯連子曰：君鹅鸭有餘食，士不足半菽。","sortOrder":84},
  {"id":"s_work_nvlt_91_85","chapterId":"ch_work_nvlt_91","text":"《秦記》曰：符朗食鹅炙，知黑白之處，人不信，既而试之，果然。","sortOrder":85},
  {"id":"s_work_nvlt_91_86","chapterId":"ch_work_nvlt_91","text":"《臨海記》曰：郡東南有白石山，高三百餘丈，望之如雪，山上有湖，古老相傳雲，金鹅所集，八桂所植，下有溪穀，金光煥然，［事具桂部。］","sortOrder":86},
  {"id":"s_work_nvlt_91_87","chapterId":"ch_work_nvlt_91","text":"幽明錄曰：晉義熙中，羌主姚略，坏洛陽陰溝取砖，得一双雄鹅，併金色，交頸長鳴，聲聞於九皋，養之此溝。","sortOrder":87},
  {"id":"s_work_nvlt_91_88","chapterId":"ch_work_nvlt_91","text":"【賦】宋鮑昭野鹅賦曰：入長羅之逼胁，負高繳之樊萦，邈辭群而別偶，超煙霧而風行，踐菲跡於瑤涂，升弱羽於丹庭，望征雲而延悼，顧委翼而自傷，無青雀之衔命，乏赤雁之嘉祥，空秽君之園池，徒慚君之稻粱。","sortOrder":88},
  {"id":"s_work_nvlt_91_89","chapterId":"ch_work_nvlt_91","text":"【序】晉蘇彦鹅詩序曰：時暫出郡，忽聞鹅鳴聲甚哀急，乃雲野人所致，外吏規為方便，以俟送客，聞之怅然。又感莊生善鳴之雁，若其無音，將充庖厨，豈得放任，矯翮籠樊。","sortOrder":89},
  {"id":"s_work_nvlt_91_90","chapterId":"ch_work_nvlt_91","text":"晉沈充鹅賦序曰：於時有绿眼黃喙，家家有焉，太康中，得大蒼鹅，從喙至足，四尺有九寸，體色丰麗，鳴聲驚人，三年而為暴犬所害，惜其不終，故為之賦雲。","sortOrder":90},
  {"id":"s_work_nvlt_91_92","chapterId":"ch_work_nvlt_91","text":"《廣雅》曰：凫鶩，鸭也。","sortOrder":92},
  {"id":"s_work_nvlt_91_93","chapterId":"ch_work_nvlt_91","text":"《說文》曰：鶩，野凫也。","sortOrder":93},
  {"id":"s_work_nvlt_91_94","chapterId":"ch_work_nvlt_91","text":"《毛詩》曰：將翱將翔，弋凫與雁。","sortOrder":94},
  {"id":"s_work_nvlt_91_95","chapterId":"ch_work_nvlt_91","text":"《左傳》：公膳日双雞，饔人竊更之以鶩，子尾怒。","sortOrder":95},
  {"id":"s_work_nvlt_91_96","chapterId":"ch_work_nvlt_91","text":"《楚辭》曰：寧與騏骥抗軛乎，將與雞鶩爭食乎，寧昂昂若數千里之駒，泛泛若水中之凫。","sortOrder":96},
  {"id":"s_work_nvlt_91_97","chapterId":"ch_work_nvlt_91","text":"魯連子曰：陳無宇謂門客曰：昔荆來伐，無一人死，何國之寡士也，門客對曰：君車衣文繡，士不得以為緣，鹅鸭有餘食，士不足菽稗，堂上有酒池，士不得一嘗，财者君所輕，死者士所重，君不以所輕與人，而欲得人所重，不亦難乎。","sortOrder":97},
  {"id":"s_work_nvlt_91_98","chapterId":"ch_work_nvlt_91","text":"《說苑》曰：鶩無他心，故庶人以為贽。","sortOrder":98},
  {"id":"s_work_nvlt_91_99","chapterId":"ch_work_nvlt_91","text":"《廣志》曰：野鸭，雄者赤頭有距，鶩生百卵，一日再生，有露華鶩，以秋冬生卵，併出蜀，晨凫肥而叵寒，宜為〈月隺〉。","sortOrder":99},
  {"id":"s_work_nvlt_91_100","chapterId":"ch_work_nvlt_91","text":"焦贛《易林》曰：凫舞鼓翼，嘉樂充德。","sortOrder":100},
  {"id":"s_work_nvlt_91_101","chapterId":"ch_work_nvlt_91","text":"《風俗通》曰：王乔為鄴令，每月朔望，常自縣詣台朝，帝怪其來數，而不見車騎，密令太史伺望之，言其臨至，辄有双凫從東南飛來，於是舉羅張之，但得一只舄，是先所賜尚書官屬履也。","sortOrder":101},
  {"id":"s_work_nvlt_91_102","chapterId":"ch_work_nvlt_91","text":"《廣州先賢傳》：頓琦至孝，母丧感慕，哀聲不絕，有飛凫白鳩〈木妻〉庐侧，見人即去，見琦而留。","sortOrder":102},
  {"id":"s_work_nvlt_91_103","chapterId":"ch_work_nvlt_91","text":"又，丁密遭父艱，有飛凫一双，遊密庐旁小池，見人則馴附，如家所畜，後遭母丧，密歸至所居一宿，故双凫复遊戲池中。","sortOrder":103},
  {"id":"s_work_nvlt_91_104","chapterId":"ch_work_nvlt_91","text":"《吳錄》曰：娄縣有石首魚，至秋化為寇凫，凫頭中猶有石也。","sortOrder":104},
  {"id":"s_work_nvlt_91_105","chapterId":"ch_work_nvlt_91","text":"《南越志》曰：化蒙縣祠山上，有池，池中有松凫，如今野凫，栖息松間，故俗謂之松凫。","sortOrder":105},
  {"id":"s_work_nvlt_91_106","chapterId":"ch_work_nvlt_91","text":"【詩】梁簡文帝詠单凫詩曰：衔苔入淺水，刷羽向沙洲，孤飛本欲去，得影更淹留。","sortOrder":106},
  {"id":"s_work_nvlt_91_107","chapterId":"ch_work_nvlt_91","text":"又詠寒凫詩曰：回水浮輕浪，沙場弄羽衣，眇眇隨山没，離離傍海飛。","sortOrder":107},
  {"id":"s_work_nvlt_91_108","chapterId":"ch_work_nvlt_91","text":"隋江總賦得汎汎水中凫詩曰：歸凫沸卉同，亂下方塘中，出没時衔藻，飛鳴忽颺風，浮深或不息，戲廣若乘空，春鸚徒有賦，還笑在金籠。","sortOrder":108},
  {"id":"s_work_nvlt_91_109","chapterId":"ch_work_nvlt_91","text":"【賦】晉蔡洪斗凫賦曰：嘉乾黃之散授，何氣化之有靈，產羽虫之麗鳥，惟斗鸭之最精，禀離午之淑氣，體鸞鳳之妙形，服文藻之華羽，備艳采之翠英，冠葩绿以曜首，缀素色以點纓，性浮捷以輕躁，聲清响而好鳴，感秋商之肅烈，從金氣以出征，招爽敵於戲門，交武势於川庭，爾乃振劲羽，竦六翮，抗嚴趾，望雄敵，忽雷起而電發，赴洪波以奋击。","sortOrder":109},
  {"id":"s_work_nvlt_91_110","chapterId":"ch_work_nvlt_91","text":"宋王徽野鶩賦曰：翾翾双鶩，體蕞羽微，和鳴媿雁，麗采慚翚，仰鵠推高，瞻隼憚威，遵時弄音，假日於飛，爾乃湛淡扬澜，俯仰威畴，心矜遠野，意惕近洲。","sortOrder":110},
  {"id":"s_work_nvlt_91_111","chapterId":"ch_work_nvlt_91","text":"齊謝朓野鶩賦曰：夫何羅人之伎巧，荐江海之逸禽，落摩天之迅羽，絕飛驚之好音，碎文錦之丹臆，納綺绿之翠衿，孤雏喧而靡翼，羁雌叫而莫尋。","sortOrder":111},
  {"id":"s_work_nvlt_91_112","chapterId":"ch_work_nvlt_91","text":"【啟】梁劉孝儀為晉安王謝賜鹅鸭啟曰：形類沈文，經符陶記，晉臣羞筮，吳覡未占，复有背如車蓋，焜垂却月，口疑犀〈木娈〉，腳似魚懸，出九芝之池，去千金之沼。","sortOrder":112},
  {"id":"s_work_nvlt_91_114","chapterId":"ch_work_nvlt_91","text":"《爾雅》曰：雞大者蜀，蜀子鵭，［爾雅釋畜作狖。］絕有力奋，雞三尺為鶤。","sortOrder":114},
  {"id":"s_work_nvlt_91_115","chapterId":"ch_work_nvlt_91","text":"《春秋運斗枢》曰：玉衡星精散為雞。又說題辭曰：雞為積陽，南方之象，［離為日，積陽之象也。］火陽精物，炎上，故陽出雞鳴，以類感也，［日將出，預喜於類，見而鳴也。］","sortOrder":115},
  {"id":"s_work_nvlt_91_116","chapterId":"ch_work_nvlt_91","text":"《易》曰：巽為雞，［雞知時號令之謂。］","sortOrder":116},
  {"id":"s_work_nvlt_91_117","chapterId":"ch_work_nvlt_91","text":"《周官》曰：工商執雞，［取其守時而動。］","sortOrder":117},
  {"id":"s_work_nvlt_91_118","chapterId":"ch_work_nvlt_91","text":"《毛詩》曰：君子於役，不知其期，曷至哉，雞栖於塒，［凿牆而栖曰塒。］","sortOrder":118},
  {"id":"s_work_nvlt_91_119","chapterId":"ch_work_nvlt_91","text":"又曰：雞栖於桀，［栖於弋為桀。］","sortOrder":119},
  {"id":"s_work_nvlt_91_120","chapterId":"ch_work_nvlt_91","text":"又曰：風雨，思君子也，亂世不改其度焉，風雨凄凄，雞鳴喈喈，風雨如晦，雞鳴不已。","sortOrder":120},
  {"id":"s_work_nvlt_91_121","chapterId":"ch_work_nvlt_91","text":"《禮記》曰：子事父母，雞初鳴，鹹盥漱。","sortOrder":121},
  {"id":"s_work_nvlt_91_122","chapterId":"ch_work_nvlt_91","text":"又曰：季冬之月，雉雊雞乳。","sortOrder":122},
  {"id":"s_work_nvlt_91_123","chapterId":"ch_work_nvlt_91","text":"《左傳》曰：季郈之雞斗，［季平子，郈昭伯二家相近，故雞斗。］季氏芥其雞，［捣芥子播其羽。］郈氏為之金距，平子怒，怒其不下己。","sortOrder":123},
  {"id":"s_work_nvlt_91_124","chapterId":"ch_work_nvlt_91","text":"又曰：賓孟適郊，見雄雞自斷其尾，問之侍者，曰：憚為犧也。","sortOrder":124},
  {"id":"s_work_nvlt_91_125","chapterId":"ch_work_nvlt_91","text":"《越絕書》曰：雞山者，句踐以畜雞，將伐吳，以食死士。","sortOrder":125},
  {"id":"s_work_nvlt_91_126","chapterId":"ch_work_nvlt_91","text":"《列子》曰：紀渻子為周宣王養斗雞，十日而問之，雞可斗乎，曰：未也，方虛驕而恃氣，十日又問之，曰：未也，猶疾视而盛氣，十日又問之，曰：幾矣，望之如木雞，其德全矣，異雞無敢應者也。","sortOrder":126},
  {"id":"s_work_nvlt_91_127","chapterId":"ch_work_nvlt_91","text":"《莊子》曰：莊子謂惠子曰：羊溝之雞，［司馬彪曰：羊溝斗雞之處。］三歲為株，［株魁師。］相者视之，則非良雞也，然而數以勝人者，以狸膏涂其頭，［雞畏狸也。］","sortOrder":127},
  {"id":"s_work_nvlt_91_128","chapterId":"ch_work_nvlt_91","text":"又曰：嫗雞搏狸。","sortOrder":128},
  {"id":"s_work_nvlt_91_129","chapterId":"ch_work_nvlt_91","text":"又曰：越雞不能伏鵠卵。","sortOrder":129},
  {"id":"s_work_nvlt_91_130","chapterId":"ch_work_nvlt_91","text":"《燕丹子》曰：燕太子丹质於秦，逃歸，到關，丹為雞鳴，遂得逃歸。","sortOrder":130},
  {"id":"s_work_nvlt_91_131","chapterId":"ch_work_nvlt_91","text":"《呂氏春秋》曰：善學者，若齊王之食雞也，食其蹠，數千而後足。","sortOrder":131},
  {"id":"s_work_nvlt_91_132","chapterId":"ch_work_nvlt_91","text":"《戰國策》曰：秦惠王謂寒泉子曰：蘇秦欺弊邑，欲以一人之智，反覆山東之君，夫諸侯之不可一，猶連雞之不能俱止於栖也。","sortOrder":132},
  {"id":"s_work_nvlt_91_133","chapterId":"ch_work_nvlt_91","text":"《史記》曰：子路性鄙，好勇力，冠雄雞，佩猳豚，殘暴孔子，孔子乃設禮義，稍誘之，子路乃委质，請為弟子。","sortOrder":133},
  {"id":"s_work_nvlt_91_134","chapterId":"ch_work_nvlt_91","text":"又曰：武帝得越巫，立越祀，而以雞卜，上信之。","sortOrder":134},
  {"id":"s_work_nvlt_91_135","chapterId":"ch_work_nvlt_91","text":"《玄中記》曰：東南有桃都山，上有大树，名曰桃都，枝相去三千里，上有天雞，日初出，照此木，天雞即鳴，天下雞皆隨之。","sortOrder":135},
  {"id":"s_work_nvlt_91_136","chapterId":"ch_work_nvlt_91","text":"《韓詩外傳》曰：田饒事魯哀公而不見察，哀公曰：臣將去君，黃鵠舉矣，哀公曰：何謂也，饒曰：君不見夫雞乎，頭戴冠者文也，足搏距者武也，敵在前敢斗者勇也，見食相呼者仁也，守夜不失時者信也，雞雖有五德，君猶曰瀹而食之者何也，以其所從來近，夫鵠一舉千里，止君園池，食君魚鱉，啄君黍粱，無此五德者，君猶貴之，以其所從來者遠也。","sortOrder":136},
  {"id":"s_work_nvlt_91_137","chapterId":"ch_work_nvlt_91","text":"《漢書》曰：王奉光好斗雞，宣帝微時，數與奉光會，後即位，封邛成侯。又，宣帝微時，斗雞於杜鄠之間。","sortOrder":137},
  {"id":"s_work_nvlt_91_138","chapterId":"ch_work_nvlt_91","text":"又曰：龚遂為渤海太守，使民家養五雞。","sortOrder":138},
  {"id":"s_work_nvlt_91_139","chapterId":"ch_work_nvlt_91","text":"又曰：宣帝時，或言益州有金馬碧雞，可醮而致之，於是遣王褒持節求焉，［金形似馬，碧形似雞。］","sortOrder":139},
  {"id":"s_work_nvlt_91_140","chapterId":"ch_work_nvlt_91","text":"《淮南子》曰：雞將知旦，鵠知夜半。","sortOrder":140},
  {"id":"s_work_nvlt_91_141","chapterId":"ch_work_nvlt_91","text":"范晔《後漢書》曰：河南樂羊子妻，不知何氏女，常有他舍雞谬入垣內，姑盜殺食之，妻對雞不食而泣，姑怪問之，妻曰：自傷居貧，使食有他肉，姑竟弃之。","sortOrder":141},
  {"id":"s_work_nvlt_91_142","chapterId":"ch_work_nvlt_91","text":"《論衡》曰：傳言淮南王得道，畜產皆仙，犬吠天上，雞鳴雲中。","sortOrder":142},
  {"id":"s_work_nvlt_91_143","chapterId":"ch_work_nvlt_91","text":"又曰：孟嘗君叛出秦關，雞未鳴，關不开，下座賤客，鼓臂為雞鳴，而群雞和之，乃得出關，夫牛馬以同類相應，而雞人亦以殊音相和，應和之验，未足以效同類也。","sortOrder":143},
  {"id":"s_work_nvlt_91_144","chapterId":"ch_work_nvlt_91","text":"《列仙傳》曰：祝雞公者，雒陽人，居尸乡北山下，養雞百餘年，雞皆有名字，千餘頭，暮栖於树，晝日放散，呼名即种別而至。","sortOrder":144},
  {"id":"s_work_nvlt_91_145","chapterId":"ch_work_nvlt_91","text":"《廣志》曰：雞有胡髯五指金骹，白雞金骹者善奋，併州所獻，吳中送長鳴雞。","sortOrder":145},
  {"id":"s_work_nvlt_91_146","chapterId":"ch_work_nvlt_91","text":"《魏志》曰：馬韓國出細尾雞，其尾長五尺餘，《九州春秋》曰：魏王入漢中，讨劉備，不得進，意欲弃之，乃發令曰：雞肋，疏［《太平御覽》九百十八作官。］屬不知何謂，主簿楊脩曰：夫雞肋，弃之則可惜，啖之無所得，以比漢中，王欲去也，乃白魏王，遂還。","sortOrder":146},
  {"id":"s_work_nvlt_91_147","chapterId":"ch_work_nvlt_91","text":"《吳錄》曰：魏文帝遣使求長鳴短鳴雞，群臣以非禮，欲不與，孫權敕付之。","sortOrder":147},
  {"id":"s_work_nvlt_91_148","chapterId":"ch_work_nvlt_91","text":"《南越志》曰：雞冠四關，［《太平御覽》九百十八作开。］如莲花，鳴聲清澈。","sortOrder":148},
  {"id":"s_work_nvlt_91_149","chapterId":"ch_work_nvlt_91","text":"《江表傳》曰：南郡獻長鳴承露雞。","sortOrder":149},
  {"id":"s_work_nvlt_91_150","chapterId":"ch_work_nvlt_91","text":"吳時外國傳曰：扶南王范尋，以鐵為斗雞假距，與諸將赌戲。","sortOrder":150},
  {"id":"s_work_nvlt_91_151","chapterId":"ch_work_nvlt_91","text":"《博物志》曰：祝雞公養雞法，今世人呼雞雲祝祝，起此也。","sortOrder":151},
  {"id":"s_work_nvlt_91_152","chapterId":"ch_work_nvlt_91","text":"《幽明錄》曰：晉兖州刺史沛國宋處宗，嘗買得一長鳴雞，愛養甚至，恒籠著窗間，雞遂作人語，與處宗談論，極有言智，終日不輟，處宗因此言巧大進。","sortOrder":152},
  {"id":"s_work_nvlt_91_153","chapterId":"ch_work_nvlt_91","text":"《述異記》曰：雩都縣江邊有石室，常有神雞，色如金，出穴，奋翼長鳴，見人辄飛入穴，因號為金雞穴。","sortOrder":153},
  {"id":"s_work_nvlt_91_154","chapterId":"ch_work_nvlt_91","text":"【詩】魏劉楨斗雞詩曰：丹雞被華采，双距如鋒芒，原一扬炎威，會戰此中唐，利爪探玉除，瞋目含火光，長翘驚風起，劲翮正敷張，輕舉奋勾喙，電击复還翔。","sortOrder":154},
  {"id":"s_work_nvlt_91_155","chapterId":"ch_work_nvlt_91","text":"魏陳王曹植斗雞詩曰：遊目極妙伎，清聽厭宮商，主人寂無為，眾賓進樂方，長筵坐戲客，斗雞間觀房，群雄正翕赫，双翘自飛扬，揮羽激流風，悍目發朱光，觜落輕毛散，嚴距往往傷，長鳴入青雲，扇翼獨翱翔，原蒙狸膏助，常得擅此場。","sortOrder":155},
  {"id":"s_work_nvlt_91_156","chapterId":"ch_work_nvlt_91","text":"魏應玚斗雞詩曰：戚戚懷不樂，無以釋勞勤，兄弟遊戲場，命駕迎眾賓，二部分曹伍，群雞煥以陳，双距解長緤，飛踴超敵倫，芥羽張金距，連戰何繽紛，從朝至日夕，勝負尚未分，专場驅眾敵，刚捷逸等群，四坐同休贊，賓主懷悅欣，博弈非不樂，此戲世所珍。","sortOrder":156},
  {"id":"s_work_nvlt_91_157","chapterId":"ch_work_nvlt_91","text":"梁簡文帝斗雞詩曰：玉冠初警敵，芥羽忽猜儔，十日驕既滿，九勝势恒遒，脱使田饒見，堪能說魯侯。","sortOrder":157},
  {"id":"s_work_nvlt_91_158","chapterId":"ch_work_nvlt_91","text":"又雞鳴詩曰：塒雞識將曙，長鳴高树巔，啄葉疑彰羽，排花強欲前，意氣多驚舉，飄颺獨無侣，陳思助斗协狸膏，郈昭妒敵安金距，丹山可愛有鳳皇，金門飛舞有鴛鴦，何如五德美，豈勝千里翔。","sortOrder":158},
  {"id":"s_work_nvlt_91_159","chapterId":"ch_work_nvlt_91","text":"梁劉孝威雞鳴篇曰：丹雞翠翼張，妒敵得专場，翅中含芥粉，距外曜金芒，原賜淮南藥，一使雲間翔。","sortOrder":159},
  {"id":"s_work_nvlt_91_160","chapterId":"ch_work_nvlt_91","text":"周庾信斗雞詩曰：开軒望平子，骤馬看陳王，狸膏燻斗敵，芥粉壒春場，解翅莲花動，猜群錦臆張。","sortOrder":160},
  {"id":"s_work_nvlt_91_161","chapterId":"ch_work_nvlt_91","text":"周王褒看斗雞詩曰：躞蹀始橫行，意氣欲相傾，妒敵金芒起，猜群芥粉生，入場疑挑戰，逐退似追兵，誰知函穀下，人去獨开城。","sortOrder":161},
  {"id":"s_work_nvlt_91_162","chapterId":"ch_work_nvlt_91","text":"陳徐陵斗雞詩曰：季子聊為戲，陳王欲騁才，花冠已冲力，金爪复驚媒，斗鳳羞衣錦，双鸞恥鏡台，陳仓若有信，為觅寶雞來。","sortOrder":162},
  {"id":"s_work_nvlt_91_163","chapterId":"ch_work_nvlt_91","text":"陳周弘正詠老败斗雞詩曰：少壮摧雄敵，眄视生猜忌，一隨年月衰，摧頹落毛駛，閒觀春光滿，東郊草色異，無复先鳴力，空餘擅場意。","sortOrder":163},
  {"id":"s_work_nvlt_91_164","chapterId":"ch_work_nvlt_91","text":"【賦】晉傅玄斗雞賦曰：或踯躅踟蹰，囁喋容與，或杷地俯仰，或撫翼未舉，或狼顧鴟视，或鸞翔鵠舞，或佯背而引敵，或畢命於強御，於是紛紜翕赫，雷合電击，爭奋身而相戟兮，競隼鷙而雕睨，得势者凌九天，失據者淪九地。","sortOrder":164},
  {"id":"s_work_nvlt_91_165","chapterId":"ch_work_nvlt_91","text":"晉陆善長鳴雞賦曰：美南雞之殊伟，察五色之異形，何伺晨之早發，抗長音之逸聲。","sortOrder":165},
  {"id":"s_work_nvlt_91_166","chapterId":"ch_work_nvlt_91","text":"晉習嘏長鳴雞賦曰：嘉鳴雞之令美，智窮神而入靈，審璇璣之回遽，定昏明之至精，應青陽於將旦，忽鵠立而鳳停，乃拊翼以贊時，遂延頸而長鳴，若乃本其形像，詳其羽儀，朱冠玉璫，彤素併施，紛葩赫弈，五色流離，殊姿艳溢，彩耀華披，扇六翮以增暉，舒毳毛而下垂。","sortOrder":166},
  {"id":"s_work_nvlt_91_167","chapterId":"ch_work_nvlt_91","text":"【贊】晉湛方生長鳴雞贊曰：精心妙覺，獨晓冥冥，風雨如晦，不愆其鳴。","sortOrder":167},
  {"id":"s_work_nvlt_91_168","chapterId":"ch_work_nvlt_91","text":"梁劉孝威正旦春雞贊曰：寶雞陳蒼，祠光表神，雄飛帝漢，雌鳴霸秦，排膺激怒，礴翅張瞋，電鞭失焰，雷車折輪，助摽魏教，擅場齊珍，名流晉戟，歌傳漢臣，竊脂善盜，搏穀難馴，绿鸚智淺，蒼鷹害深，兼姿五德，歸於翰音。","sortOrder":168},
  {"id":"s_work_nvlt_91_169","chapterId":"ch_work_nvlt_91","text":"【文】宋袁淑徘諧記，雞九錫文曰：維神雀元年，歲在辛酉，八月己酉朔，十三日丁酉，帝颛頊遣征西大將軍下雉公王鳳，西中郎將白門侯扁鵲，咨爾俊雞山子，維君天姿英茂，乘機晨鳴，雖風雨之如晦，抗不已之奇聲，今以君為使持節金西蠻校尉西河太守，以楊州之會稽，封君為會稽公，以前浚雞山子為湯沐邑，君其祗承予命，使西海之水如帶，浚雞之山如砺，國以永存，爰及苗裔，浚山侍郎丁鸿，舍人凫亭男梁鸿，郎中蘇鵠死罪，伏惟君德著朝野，勋加鵷鷟，故天王鳳皇，特錫位封，今鳳鵲等在栖外，原時拜受，不勝欣豫之情，謹詣栖下以聞。","sortOrder":169},
  {"id":"s_work_nvlt_91_170","chapterId":"ch_work_nvlt_91","text":"◇山雞","sortOrder":170},
  {"id":"s_work_nvlt_91_171","chapterId":"ch_work_nvlt_91","text":"《魏志》曰：平原太守劉邠，取山雞毛著器中，使管辂筮之，辂曰：高嶽巖巖，有鳥朱身，羽翼玄黃，鳴不失晨，此山雞毛也。","sortOrder":171},
  {"id":"s_work_nvlt_91_172","chapterId":"ch_work_nvlt_91","text":"《異苑》曰：山雞愛其毛，映水則舞，魏武時，南方獻之，帝欲其鳴舞而無由，公子蒼舒，令以大鏡著其前，雞鑒形而舞，不知止，遂乏死，韦仲將為之賦，甚美。","sortOrder":172},
  {"id":"s_work_nvlt_91_173","chapterId":"ch_work_nvlt_91","text":"竺法真登羅山疏曰：山海經雲，鷩雉一名山雞，養之禳［原訛攘，據冯校本改。］火灾。","sortOrder":173},
  {"id":"s_work_nvlt_91_174","chapterId":"ch_work_nvlt_91","text":"辛氏《三秦記》曰：陳蒼山在太白之西，上有石雞與山雞，趙時［太平御覽九百十八作高。］差使燒山，山雞飛去，石雞不去，晨鳴山頭，聲聞三十里，或雲是玉雞。","sortOrder":174},
  {"id":"s_work_nvlt_91_175","chapterId":"ch_work_nvlt_91","text":"《南越志》曰：曾城縣多鵕鸃，鵕鸃，山雞也，利距善斗，世以家雞斗之，則可擒也，光色鮮明，五采炫燿。","sortOrder":175},
  {"id":"s_work_nvlt_91_176","chapterId":"ch_work_nvlt_91","text":"【賦】晉傅玄山雞賦曰：惟南州之令鳥，兼坤離而體珍，被黃中之正色，敷文象以飾身，翳景山之竹林，超遊集乎水濱，鑒中流以顧影，晞雲表之清尘。","sortOrder":176},
  {"id":"s_work_nvlt_91_177","chapterId":"ch_work_nvlt_91","text":"宋臨川康王山雞賦曰：形鳳婉而鵠跱，羽袞蔚而緗暉，臨渌湍而映藻，傍青崖而妍飛，不隱燿而貽累，倏見屈於虞機。","sortOrder":177},
  {"id":"s_work_nvlt_91_179","chapterId":"ch_work_nvlt_91","text":"《爾雅》曰：鷹鶆鹴鳩。","sortOrder":179},
  {"id":"s_work_nvlt_91_180","chapterId":"ch_work_nvlt_91","text":"又曰：鷹隼丑，其飛也翚，鼓翅翚翚。","sortOrder":180},
  {"id":"s_work_nvlt_91_181","chapterId":"ch_work_nvlt_91","text":"《廣志》曰：有雉鷹，有菟鷹，一歲為黃鷹，二歲撫鷹，三歲青鷹，胡鷹獲獐。","sortOrder":181},
  {"id":"s_work_nvlt_91_182","chapterId":"ch_work_nvlt_91","text":"春秋緯曰：瑤光星散為鷹。","sortOrder":182},
  {"id":"s_work_nvlt_91_183","chapterId":"ch_work_nvlt_91","text":"《毛詩》曰：維師尚父，時惟鷹扬。","sortOrder":183},
  {"id":"s_work_nvlt_91_184","chapterId":"ch_work_nvlt_91","text":"《周書》曰：驚蟄之日，鷹变為鳩，處暑之日，鷹乃祭鳥。","sortOrder":184},
  {"id":"s_work_nvlt_91_185","chapterId":"ch_work_nvlt_91","text":"《左傳》：郯子雲，少皞氏，爽鳩氏司寇也，［杜謂鷹也。］","sortOrder":185},
  {"id":"s_work_nvlt_91_186","chapterId":"ch_work_nvlt_91","text":"又，子產始知然明，問為政，對曰：视民如子，見不仁者誅之，如鷹鹯之逐鳥雀也。","sortOrder":186},
  {"id":"s_work_nvlt_91_187","chapterId":"ch_work_nvlt_91","text":"《戰國策》曰：唐睢謂秦王曰：要離刺慶忌，蒼鷹击於殿上。","sortOrder":187},
  {"id":"s_work_nvlt_91_188","chapterId":"ch_work_nvlt_91","text":"《京房占》曰：七月鳩化為鷹。","sortOrder":188},
  {"id":"s_work_nvlt_91_189","chapterId":"ch_work_nvlt_91","text":"《漢書》曰：孫寶為京兆尹，請故吏侯文為掾，立秋日，文謂寶曰：今鷹隼始击，當順天氣，成嚴霜之誅。","sortOrder":189},
  {"id":"s_work_nvlt_91_190","chapterId":"ch_work_nvlt_91","text":"《東觀漢記》曰：邓太後臨朝，上林鷹犬，悉斥放之。","sortOrder":190},
  {"id":"s_work_nvlt_91_191","chapterId":"ch_work_nvlt_91","text":"馬融與謝伯世書曰：憤憤愁思，猶不解懷，思在竹間，放狗逐麋，晚秋涉冬，大蒼出籠，黃棘下兔，芼以乾葵，以送餘日，茲樂而已。","sortOrder":191},
  {"id":"s_work_nvlt_91_192","chapterId":"ch_work_nvlt_91","text":"後《幽明錄》曰：楚文王時，有人獻一鷹，俄而雲际有一物，凝翔鮮白，鷹便竦翮而升，須臾羽墮如雪，血下如雨，有大鳥墮地，兩翅廣數十里，眾莫能知，時博物君子曰：此鵬雏也。","sortOrder":192},
  {"id":"s_work_nvlt_91_193","chapterId":"ch_work_nvlt_91","text":"《魏志》：呂布因陳登求徐州牧，不得，布怒，登喻之曰：登見曹公，言待將軍，譬如養虎，當飽其肉，不則噬人，公曰：不如卿言，譬如養鷹，飢則為用，飽則扬去，布乃解。","sortOrder":193},
  {"id":"s_work_nvlt_91_194","chapterId":"ch_work_nvlt_91","text":"【詩】晉張華遊獵篇曰：如黃犭比狡勇，青骹撮飛雉，鵠鷺不盡收，小鳥安足视。","sortOrder":194},
  {"id":"s_work_nvlt_91_195","chapterId":"ch_work_nvlt_91","text":"【賦】晉傅玄鷹賦曰：左看若侧，右视如傾，劲翮二六，機連體輕，勾爪懸芒，足如枯荆，觜利吳戟，目穎星明，雄姿邈世，逸氣橫生。","sortOrder":195},
  {"id":"s_work_nvlt_91_196","chapterId":"ch_work_nvlt_91","text":"晉孫楚鷹賦曰：有金刚之俊鳥，生井陉之巖阻，超萬仞之崇巔，荫青松以靜處，體劲悍之自然，振肅肅之輕羽，擒狡兔於平原，截鶴雁於河渚，且其為相也，疏尾闊臆，高鬐禿顱，深目蛾眉，状似愁胡，曲觜短頸，足若双枯，麾則應機，招則易呼，背碣石以西遊，經馬嶺而南徂，於時商秋既邁，歲在玄冥，風霜激厲，羽毛振驚，爾乃策良骥，服羔裘，韝青骹，戲田畴，萦深穀，繞山丘，定心意，審精眸，獸馳厥足，鳥矯其翼，下赴幽谿，上翔辰極，隨指授以騰踴，因升降以畢力，紛連薄以攫竄，遂陷首以摧臆。","sortOrder":196},
  {"id":"s_work_nvlt_91_198","chapterId":"ch_work_nvlt_91","text":"《爾雅》曰：鹯負雀鷂也。","sortOrder":198},
  {"id":"s_work_nvlt_91_199","chapterId":"ch_work_nvlt_91","text":"《廣雅》曰：籠脱鷂也。","sortOrder":199},
  {"id":"s_work_nvlt_91_200","chapterId":"ch_work_nvlt_91","text":"《周易》曰：公用射隼於高墉之上。","sortOrder":200},
  {"id":"s_work_nvlt_91_201","chapterId":"ch_work_nvlt_91","text":"《毛詩》曰：窎彼飛隼，載飛載扬。","sortOrder":201},
  {"id":"s_work_nvlt_91_202","chapterId":"ch_work_nvlt_91","text":"《詩義問》曰：晨風今之鷂，［餘說併以鹯為晨風。］","sortOrder":202},
  {"id":"s_work_nvlt_91_203","chapterId":"ch_work_nvlt_91","text":"《詩義疏》曰：隼，鷂也，齊人謂之題肩，或曰雀鷹，春化為布穀，此屬數种皆為隼。","sortOrder":203},
  {"id":"s_work_nvlt_91_204","chapterId":"ch_work_nvlt_91","text":"周官，考工曰：鳥旟七斿，［鳥隼為旟。］","sortOrder":204},
  {"id":"s_work_nvlt_91_205","chapterId":"ch_work_nvlt_91","text":"《國語》曰：仲尼在陳，有隼集於庭而死，楛矢貫之，以問仲尼，仲尼曰：昔武王剋商所得也。","sortOrder":205},
  {"id":"s_work_nvlt_91_206","chapterId":"ch_work_nvlt_91","text":"《莊子》曰：鷂為鹯，鹯為布穀，布穀复為鷂，此物变也。","sortOrder":206},
  {"id":"s_work_nvlt_91_207","chapterId":"ch_work_nvlt_91","text":"《列士傳》曰：魏公子無忌方食，有鳩飛入案下，公子使人顧望，見一鷂在屋上飛去，公子乃縱鳩，鷂逐而殺之，公子暮為不食，曰：鳩避患歸無忌，競［○《太平御覽》九百二十六作竟。］為鷂所得，吾負之，為吾捕得此鷂者，無忌無所愛，於是左右宣公子慈聲旁國，左右捕得鷂二百餘頭，以奉公子，公子欲盡殺之，恐有辜，乃自按劍至其籠上曰：誰獲罪無忌者耶，一鷂獨低頭，不敢仰视，乃取殺之，盡放其餘，名聲流布，天下歸焉。","sortOrder":207},
  {"id":"s_work_nvlt_91_208","chapterId":"ch_work_nvlt_91","text":"焦贛《易林》曰：無妄之明夷曰：千雀萬鳩，與鷂為仇，威势不敵，為鷹所击。","sortOrder":208},
  {"id":"s_work_nvlt_91_209","chapterId":"ch_work_nvlt_91","text":"【賦】魏陳王曹植鷂雀賦曰：鷂欲取雀，雀言自雀微賤，身體些小，肌肉痟瘦，所得蓋少，君欲相啖，實不足飽。鷂得雀言，初不取語，頃來轗軻，資糧之［本集作乏。］旅，三日不食，略思死鼠，今日相得，寧复宜汝。雀得鷂言，意甚征營，性命至重，雀鼠貪生，君得一食，我命是傾，皇天是鑒，賢者是聽。鷂得雀言，意甚沮惋，當死弊雀，頭如果蒜，不早首服，列頸大唤，行人聞之，莫不往觀。雀得鷂言，意甚不移，目如擘椒，跳萧二翅，我雖當死，略無可避。鷂乃置雀，良久方去。二雀相逢，似是公嫗，相將入草，共上一树，仍共本末，辛苦相語，向者近出，為鷂所捕，賴我翻捷，體素便附，說我辯語，千條萬句，欺恐舍長，令兒大怖，我之得免，复勝於兔，自今從意，莫复相妒。","sortOrder":209},
  {"id":"s_work_nvlt_91_210","chapterId":"ch_work_nvlt_91","text":"《藝文類聚》　唐·欧陽詢","sortOrder":210},
  {"id":"s_work_nvlt_92_1","chapterId":"ch_work_nvlt_92","text":"卷九十二鳥部下","sortOrder":1},
  {"id":"s_work_nvlt_92_2","chapterId":"ch_work_nvlt_92","text":"○乌鵲雀燕鳩鴟反舌仓庚鹪鹩啄木鴛鴦鵁鶄鸂鶒白鷺鸊鹈鷗鵬精衛翡翠服鳥","sortOrder":2},
  {"id":"s_work_nvlt_92_4","chapterId":"ch_work_nvlt_92","text":"《爾雅》鳶乌丑，其飛也翔。","sortOrder":4},
  {"id":"s_work_nvlt_92_5","chapterId":"ch_work_nvlt_92","text":"又曰：鸀，［濁。］山乌。","sortOrder":5},
  {"id":"s_work_nvlt_92_6","chapterId":"ch_work_nvlt_92","text":"又曰：燕白脰乌。","sortOrder":6},
  {"id":"s_work_nvlt_92_7","chapterId":"ch_work_nvlt_92","text":"《春秋運斗枢》曰：搖星散為乌。","sortOrder":7},
  {"id":"s_work_nvlt_92_8","chapterId":"ch_work_nvlt_92","text":"《廣志》曰：乌有白頸乌。","sortOrder":8},
  {"id":"s_work_nvlt_92_9","chapterId":"ch_work_nvlt_92","text":"《毛詩》曰：具曰予聖，誰知乌之雌雄，［時若臣賢愚，適同如乌也。］","sortOrder":9},
  {"id":"s_work_nvlt_92_10","chapterId":"ch_work_nvlt_92","text":"又曰：瞻乌爰止，於誰之屋，［集富人之屋也。］","sortOrder":10},
  {"id":"s_work_nvlt_92_11","chapterId":"ch_work_nvlt_92","text":"又曰：弁彼鸒斯，歸飛提提，［雅乌，一曰鵯居。］","sortOrder":11},
  {"id":"s_work_nvlt_92_12","chapterId":"ch_work_nvlt_92","text":"《左傳》曰：楚子元以車六百乘伐鄭，諸侯救鄭，楚師夜遁，鄭人將奔桐丘，諜告曰：楚幕有乌，乃止。","sortOrder":12},
  {"id":"s_work_nvlt_92_13","chapterId":"ch_work_nvlt_92","text":"又曰：晉侯伐齊，齊師夜遁，師曠告晉侯曰：乌鳥之聲樂，齊師其遁，［鳥乌得空營，故樂。］","sortOrder":13},
  {"id":"s_work_nvlt_92_14","chapterId":"ch_work_nvlt_92","text":"叔向告晉侯曰：城上有乌，齊師其遁。","sortOrder":14},
  {"id":"s_work_nvlt_92_15","chapterId":"ch_work_nvlt_92","text":"《春秋元命苞》曰：火流為乌，乌孝鳥，何知孝鳥，陽［陽上疑有脱文。］精，陽天之意，乌在日中，從天，以昭孝也。","sortOrder":15},
  {"id":"s_work_nvlt_92_16","chapterId":"ch_work_nvlt_92","text":"太公《六韜》曰：武王登夏台，以臨殷民，周公旦曰：臣聞之，愛其人者，愛其屋上乌，憎其人者，憎其餘胥。","sortOrder":16},
  {"id":"s_work_nvlt_92_17","chapterId":"ch_work_nvlt_92","text":"《燕丹子》曰：燕太子丹质於秦，秦王遇之無禮，不得意，欲歸，秦王不聽，谬言曰：令乌白頭，馬生角，乃可，丹仰天叹，乌即白頭，馬為生角，秦王不得已而遣之。","sortOrder":17},
  {"id":"s_work_nvlt_92_18","chapterId":"ch_work_nvlt_92","text":"《淮南子》曰：尧時十日併出，尧命羿仰射十日，中其九乌。","sortOrder":18},
  {"id":"s_work_nvlt_92_19","chapterId":"ch_work_nvlt_92","text":"謝承《漢書》曰：廣漢儒叔林，為東郡太守，乌巢於廳事屋梁，兔產於床下。","sortOrder":19},
  {"id":"s_work_nvlt_92_20","chapterId":"ch_work_nvlt_92","text":"王隱《晉書》曰：虞溥為鄱陽內史，勸励學業，雖威不猛，宽裕簡素，白乌集郡庭，止棗树，就執不動。","sortOrder":20},
  {"id":"s_work_nvlt_92_21","chapterId":"ch_work_nvlt_92","text":"《抱朴子》曰：熒惑火精，生朱乌。","sortOrder":21},
  {"id":"s_work_nvlt_92_22","chapterId":"ch_work_nvlt_92","text":"《古今註》：所謂赤乌者，朱鳥也，其所居高遠，日中三足乌之精，降而生三足乌，何以三足，陽數奇也，是以有虞至孝，三足集其庭，曾參鋤瓜，三足萃其冠。","sortOrder":22},
  {"id":"s_work_nvlt_92_23","chapterId":"ch_work_nvlt_92","text":"徐整《三五歷》曰：天地之初，有三白乌，主生眾鳥。","sortOrder":23},
  {"id":"s_work_nvlt_92_24","chapterId":"ch_work_nvlt_92","text":"《述征記》曰：長安靈台，有相風銅乌。","sortOrder":24},
  {"id":"s_work_nvlt_92_25","chapterId":"ch_work_nvlt_92","text":"《豫章舊志》曰：太守李儀，臨郡二年，白乌見南昌。","sortOrder":25},
  {"id":"s_work_nvlt_92_26","chapterId":"ch_work_nvlt_92","text":"蜀李雄書曰：武皇帝雄，泰成三年，白乌赤足來翔，帝以問范賢，賢曰：乌有反哺之義，必有遠人懷惠而來，果關中流民請降。","sortOrder":26},
  {"id":"s_work_nvlt_92_27","chapterId":"ch_work_nvlt_92","text":"師覺授《孝子傳》曰：吳叔和，犍為人，母没，負土成墳，有赤乌巢門，甘露降戶。","sortOrder":27},
  {"id":"s_work_nvlt_92_28","chapterId":"ch_work_nvlt_92","text":"王韶《孝子傳》曰：李陶，交阯人，母終，陶居於墓侧，躬自治墓，不受鄰人助，群乌衔塊，助成墳。","sortOrder":28},
  {"id":"s_work_nvlt_92_29","chapterId":"ch_work_nvlt_92","text":"《異苑》曰：東陽顏乌，以純孝著聞，後有群乌衔鼓，集顏所居之村，乌口皆傷，一境以為顏至孝，故慈乌來萃，衔鼓之興，欲令聋者遠聞，即於鼓處立縣，而名為乌傷，王莽改為乌孝，以彰其行跡雲。","sortOrder":29},
  {"id":"s_work_nvlt_92_30","chapterId":"ch_work_nvlt_92","text":"南越記曰：乌賊魚，常自浮水上，乌見以為死，便往啄之，乃卷取乌，故謂乌賊，今雅乌化為之。","sortOrder":30},
  {"id":"s_work_nvlt_92_31","chapterId":"ch_work_nvlt_92","text":"【詩】梁元帝晚栖乌詩曰：日暮連翩翼，俱向上林栖，風多前鳥駛，雲暗後群迷，路遠聲難彻，飛斜行未齊，應從故乡返，幾過入蘭閨，借問倡樓妾，何如荡子啼。","sortOrder":31},
  {"id":"s_work_nvlt_92_32","chapterId":"ch_work_nvlt_92","text":"梁劉孝威乌生八九子篇曰：城上乌，一年生九雏，氄毛不自暖，張翼強相呼，羽成翮備各西東，丁年賦命有窮通，不見高飛帝輦侧，遠讬日輪中，尚逢王吉箭，猶婴唐羿弓，豈如变采救燕质，入夢祚昭公，流聲表師退，集幕示營空，靈台已鑄像，流蘇時候風。","sortOrder":32},
  {"id":"s_work_nvlt_92_33","chapterId":"ch_work_nvlt_92","text":"梁朱超城上乌詩曰：朝飛集帝城，猶帶夜啼聲，近收毛雖暖，聞絃心尚驚。","sortOrder":33},
  {"id":"s_work_nvlt_92_34","chapterId":"ch_work_nvlt_92","text":"隋虞世基晚飛乌詩曰：向日晚飛低，飛飛未得栖，當為歸林遠，恒長侵夜啼。","sortOrder":34},
  {"id":"s_work_nvlt_92_35","chapterId":"ch_work_nvlt_92","text":"【賦】梁何遜窮乌賦曰：嗟窮乌之小鳥，意局促而馴逝，聲遇物而知哀，翮排空而不矯，望絕侣於霞夕，聽翔群於月晓，既滅志疃製霄，遂甘夷於園沼。","sortOrder":35},
  {"id":"s_work_nvlt_92_36","chapterId":"ch_work_nvlt_92","text":"【序】晉成公綏乌賦序曰：有孝鳥集餘之庐，乃喟爾而叹曰：餘無仁惠之德，祥禽曷為而至哉，夫乌之為瑞久矣，以其反哺識養，故為吉乌，是以周書神其流变，詩人尋其所集，望富者瞻其爰止，愛屋者及其增叹，茲蓋古人所以為稱，若乃三足德靈，國有道則見，國無道則隱，斯乃鳳鳥之德，何以加焉，服惡鳥而贾生懼之，乌善禽而吾嘉焉，懼惡而作歌，嘉善而賦之，不亦可乎。","sortOrder":36},
  {"id":"s_work_nvlt_92_38","chapterId":"ch_work_nvlt_92","text":"《爾雅》曰：鵲鵙丑，其飛也〈羽夋〉，［竦翅上下。］","sortOrder":38},
  {"id":"s_work_nvlt_92_39","chapterId":"ch_work_nvlt_92","text":"《說文》曰：鵲知太歲之所在。","sortOrder":39},
  {"id":"s_work_nvlt_92_40","chapterId":"ch_work_nvlt_92","text":"《廣雅》曰：鳱鵲鵲。","sortOrder":40},
  {"id":"s_work_nvlt_92_41","chapterId":"ch_work_nvlt_92","text":"《禮記》曰：季冬之月，鵲始巢。","sortOrder":41},
  {"id":"s_work_nvlt_92_42","chapterId":"ch_work_nvlt_92","text":"《毛詩》曰：鵲巢，夫人之德也。","sortOrder":42},
  {"id":"s_work_nvlt_92_43","chapterId":"ch_work_nvlt_92","text":"《莊子》曰：鵲上高城，危而巢於高枝之巔，城坏巢折，凌風而起，故君子之居世也，得時則義行，失時則鵲起。","sortOrder":43},
  {"id":"s_work_nvlt_92_44","chapterId":"ch_work_nvlt_92","text":"又曰：莊周遊於雕陵之樊，［樊，蕃也，遊於栗園。］睹一異鵲，自南方來，翼七尺，目大運寸，［可回一寸。］感周之顙，而集於栗林。","sortOrder":44},
  {"id":"s_work_nvlt_92_45","chapterId":"ch_work_nvlt_92","text":"《孫卿子》曰：古之王者，其政好生惡殺，乌鵲之巢，可俯而窥。","sortOrder":45},
  {"id":"s_work_nvlt_92_46","chapterId":"ch_work_nvlt_92","text":"《淮南子》曰：鵲巢知風之所起。","sortOrder":46},
  {"id":"s_work_nvlt_92_47","chapterId":"ch_work_nvlt_92","text":"又曰：乾鵲知來而不知往，此脩短之分也。","sortOrder":47},
  {"id":"s_work_nvlt_92_48","chapterId":"ch_work_nvlt_92","text":"《鹽鐵論》曰：中國所鮮，外國賤之，崑山之旁，以玉璞抵乌鵲。","sortOrder":48},
  {"id":"s_work_nvlt_92_49","chapterId":"ch_work_nvlt_92","text":"【詩】魏太祖武帝歌詩曰：月明星稀，乌鵲南飛，繞树三匝，何枝可依，山不厭高，海不厭深，周公吐哺，天下歸心。","sortOrder":49},
  {"id":"s_work_nvlt_92_50","chapterId":"ch_work_nvlt_92","text":"魏曹植魏德論謳曰：鵲之彊彊，詩人取喻，今存聖世，呈质見素，飢食苕華，渴飲清露，異於畴匹，眾鳥是慕。","sortOrder":50},
  {"id":"s_work_nvlt_92_52","chapterId":"ch_work_nvlt_92","text":"《春秋運斗枢》曰：瑤光星散為雀。","sortOrder":52},
  {"id":"s_work_nvlt_92_53","chapterId":"ch_work_nvlt_92","text":"《禮記》曰：季秋，雀入大水，化為蛤。","sortOrder":53},
  {"id":"s_work_nvlt_92_54","chapterId":"ch_work_nvlt_92","text":"《晏子》曰：齊景公探雀鷇，鷇弱，故反之，晏子再拜贺曰：吾君有聖人之道矣，道長幼也，曾禽獸之加焉，而况人乎。","sortOrder":54},
  {"id":"s_work_nvlt_92_55","chapterId":"ch_work_nvlt_92","text":"《莊子》曰：一雀過羿，羿必得之，或曰：以天下為之籠，則雀無所逃，是故殷湯以庖人籠伊尹，秦穆以五羊之皮籠百里奚。","sortOrder":55},
  {"id":"s_work_nvlt_92_56","chapterId":"ch_work_nvlt_92","text":"《呂氏春秋》曰：燕雀處一屋之下，子母相哺，呴呴然其相樂也，自以為安矣，竈突决，火上，棟宇將焚，燕雀顏色不变，不知禍將及也，為人臣免燕雀之智者寡矣。","sortOrder":56},
  {"id":"s_work_nvlt_92_57","chapterId":"ch_work_nvlt_92","text":"《戰國策》曰：莊辛謂楚王曰：夫雀俯啄白糧，仰栖茂树，鼓翅奋翼，自以為無患與人無爭也，不知夫王孫公子，左挟彈，右持攝丸，以加其頸，晝遷乎茂树，夕調酸鹹矣。","sortOrder":57},
  {"id":"s_work_nvlt_92_58","chapterId":"ch_work_nvlt_92","text":"《史記》曰：趙武靈王號主父，废長子章，而傳國於公子何，主父遊沙丘，公子章作亂，與何戰败，章走趨主父，主父开受之，何遂围主父，主父飢，探雀鷇而食之，三月餘，遂饿死沙丘。","sortOrder":58},
  {"id":"s_work_nvlt_92_59","chapterId":"ch_work_nvlt_92","text":"《韓詩外傳》曰：夫鳳皇之初起也，遙遙千里，蕃篱之雀，喔咿而笑之，及其升少陽，一屈一信，輾轉雲間，蕃篱之雀，超然自知不及遠矣。","sortOrder":59},
  {"id":"s_work_nvlt_92_60","chapterId":"ch_work_nvlt_92","text":"《太玄經》曰：明珠彈雀，費不當也。","sortOrder":60},
  {"id":"s_work_nvlt_92_61","chapterId":"ch_work_nvlt_92","text":"《孔丛子》曰：邯鄲民，以正月旦獻雀於趙王，而缀以五采，王大悅，申叔告子從，子從曰：非先王之法，且又不令，申叔曰：何謂不令，曰：夫爵者宜受之於上，不宜取之於下，民非所得製爵也，昔虢公祈神，神賜之土田，是失國而受田之祥也，今以一國之王，受民之爵，何悅乎。","sortOrder":61},
  {"id":"s_work_nvlt_92_62","chapterId":"ch_work_nvlt_92","text":"《漢武內傳》曰：西王母曰：仙次藥，有崑丘神雀。","sortOrder":62},
  {"id":"s_work_nvlt_92_63","chapterId":"ch_work_nvlt_92","text":"《陳留耆舊傳》曰：圉人魏尚，高帝時為太史，有罪系詔獄，有萬頭雀，集獄棘树上，拊翼而鳴，尚占曰：雀者爵命之祥，其鳴即复也，我其复官也，有頃，詔還故官。","sortOrder":63},
  {"id":"s_work_nvlt_92_64","chapterId":"ch_work_nvlt_92","text":"《益部耆舊傳》曰：扬宣為河內太守，行縣，有群雀鳴桑树上，宣謂吏曰：前有覆車粟，此雀相隨，欲往食之，行數里，果如其言。","sortOrder":64},
  {"id":"s_work_nvlt_92_65","chapterId":"ch_work_nvlt_92","text":"張顯折言曰：萬雀不及一鳳皇，眾星不如一月明。","sortOrder":65},
  {"id":"s_work_nvlt_92_66","chapterId":"ch_work_nvlt_92","text":"沙洲記曰：寒嶺去大陽川三十里，有雀鼠同穴，雀亦如家雀，色小白，鼠亦如家鼠，色如黃虺，無尾。","sortOrder":66},
  {"id":"s_work_nvlt_92_67","chapterId":"ch_work_nvlt_92","text":"《異苑》曰：任城魏肇之，初生，有雀飛入其手，占者以為封爵之祥。","sortOrder":67},
  {"id":"s_work_nvlt_92_68","chapterId":"ch_work_nvlt_92","text":"《南越志》曰：曾城縣多白雀，大如鳩，素质疑映。","sortOrder":68},
  {"id":"s_work_nvlt_92_69","chapterId":"ch_work_nvlt_92","text":"羅含傳曰：含在家時，有百雀集堂宇，此德行幽感所致。","sortOrder":69},
  {"id":"s_work_nvlt_92_70","chapterId":"ch_work_nvlt_92","text":"《說苑》曰：吳王欲伐荆，有諫者死，舍人少孺子，懷丸操彈於後園，露霑衣，如是三旦，王曰：子來何霑衣如此，對曰：園有榆，上有蝉，蝉高居，悲鳴飲露，不知螳螂在其後，螳螂之知捕蝉鳴，不知黃雀在其後，臣執彈丸，欲取黃雀，不覺露霑衣。","sortOrder":70},
  {"id":"s_work_nvlt_92_71","chapterId":"ch_work_nvlt_92","text":"袁山松《後漢書》曰：陳弇學尚書，躬自耕种，常有黃雀飛來，隨弇翱翔。","sortOrder":71},
  {"id":"s_work_nvlt_92_72","chapterId":"ch_work_nvlt_92","text":"續齊諧記曰：弘農扬寶，嘗見一黃雀，為鴟枭所搏，墜於树下。又為蝼蚁所困，寶愍之，取置巾箱中養之，唯食黃花，百餘日，毛羽成，放之，朝去暮還，後忽與群雀俱來，哀鳴繞室，數日乃去，爾夕三更，寶讀書未臥，有黃衣童子，向寶再拜曰：我王母使臣，為鴟枭所搏，蒙君拯濟，今當使南海，不得复往，極以悲傷以白環四枚與寶曰：令君子孫絜白，位登三事，於此遂絕，寶生震，震生秉，秉生賜，賜生彪，四世為三公。","sortOrder":72},
  {"id":"s_work_nvlt_92_73","chapterId":"ch_work_nvlt_92","text":"萧廣濟《孝子傳》曰：王祥後母病，欲得黃雀炙，祥自念卒難致，須臾，忽有數千黃雀，飛入其幕。","sortOrder":73},
  {"id":"s_work_nvlt_92_74","chapterId":"ch_work_nvlt_92","text":"《風土記》曰：六月東南長風，海魚化為黃雀。","sortOrder":74},
  {"id":"s_work_nvlt_92_75","chapterId":"ch_work_nvlt_92","text":"《廣志》曰：安息大雀，舉頭高八九尺，張翅丈餘，食大麥，卵如瓮。","sortOrder":75},
  {"id":"s_work_nvlt_92_76","chapterId":"ch_work_nvlt_92","text":"《東觀漢記》曰：永元十三年，安息王獻條支大雀。","sortOrder":76},
  {"id":"s_work_nvlt_92_77","chapterId":"ch_work_nvlt_92","text":"【詩】晉傅玄詩曰：鵲巢丘城侧，雀乳空井中，居不附龍鳳，常畏蛇與虫，依賢義不恐，近暴自當窮，宋鮑昭空城雀操曰：雀乳四鷇，空城之阿，朝拾野粟，夕飲清河，高飛畏鴟鳶，下飛畏網羅，誠不及青雀，遠食玉山禾，猶勝吳宮燕，無罪得焚窠，賦命有厚薄，長叹欲如何。","sortOrder":77},
  {"id":"s_work_nvlt_92_78","chapterId":"ch_work_nvlt_92","text":"梁沈趨詠雀詩曰：肌溥少滋腴，色淺非丹翠，不懼越王羞，寧懷秦後珥，傍簷葺寒草，循場啄餘穗，且欣大厦成，焉須鸿鵠志。","sortOrder":78},
  {"id":"s_work_nvlt_92_79","chapterId":"ch_work_nvlt_92","text":"【賦】後漢曹大家大雀賦曰：大家同產兄西域都護定遠侯班超，獻大雀，詔令大家作賦曰：嘉大雀之所集，生崑崙之靈丘，同小名而大異，乃鳳皇之匹畴，懷有德而歸義，故翔萬里而來遊，集帝庭而止息，樂和氣而優遊，上下协而相親，聽雅頌之雍雍，自東西與南北，鹹思服而來同。","sortOrder":79},
  {"id":"s_work_nvlt_92_81","chapterId":"ch_work_nvlt_92","text":"《爾雅》曰：燕燕乙也。","sortOrder":81},
  {"id":"s_work_nvlt_92_82","chapterId":"ch_work_nvlt_92","text":"《春秋運斗枢》曰：瑤光星散為燕。","sortOrder":82},
  {"id":"s_work_nvlt_92_83","chapterId":"ch_work_nvlt_92","text":"《說文》曰：燕布翅枝尾，作巢，避戊己。","sortOrder":83},
  {"id":"s_work_nvlt_92_84","chapterId":"ch_work_nvlt_92","text":"《廣雅》曰：玄鳥燕也。","sortOrder":84},
  {"id":"s_work_nvlt_92_85","chapterId":"ch_work_nvlt_92","text":"《禮》曰：仲春之月，玄鳥至，至之日，以太牢祠於高禖。","sortOrder":85},
  {"id":"s_work_nvlt_92_86","chapterId":"ch_work_nvlt_92","text":"《毛詩》曰：燕燕，衛莊薑送歸妾也，燕燕於飛，差池其羽，下上其音。","sortOrder":86},
  {"id":"s_work_nvlt_92_87","chapterId":"ch_work_nvlt_92","text":"又曰：天命玄鳥，降而生商，宅殷土茫茫，［大雅。］","sortOrder":87},
  {"id":"s_work_nvlt_92_88","chapterId":"ch_work_nvlt_92","text":"《左傳》曰：郯子雲，少皞時，玄鳥氏司分者也。","sortOrder":88},
  {"id":"s_work_nvlt_92_89","chapterId":"ch_work_nvlt_92","text":"又曰：吳公子札，自衛如晉，將宿於戚，［戚孫文子邑。］聞鍾聲曰：異哉，夫子獲罪於君以在此，［文子時以戚叛。］懼有不足，而又何樂，夫子之在此也，猶燕之巢於幕上也，［言至危。］","sortOrder":89},
  {"id":"s_work_nvlt_92_90","chapterId":"ch_work_nvlt_92","text":"《史記》曰：秦之先，颛頊之苗孫曰女脩，女脩織，玄鳥陨卵，女脩吞之，生大業。","sortOrder":90},
  {"id":"s_work_nvlt_92_91","chapterId":"ch_work_nvlt_92","text":"又曰：臨江闵王榮，坐侵廟壖為宮，上徵榮，榮詣中尉府，中尉郅都责訊王，王恐，自殺，葬藍田，燕數萬，衔土置冢上，百姓怜之。","sortOrder":91},
  {"id":"s_work_nvlt_92_92","chapterId":"ch_work_nvlt_92","text":"《漢書》曰：王莽开哀帝母丁姬冢，有燕數千，衔土投其窟中。","sortOrder":92},
  {"id":"s_work_nvlt_92_93","chapterId":"ch_work_nvlt_92","text":"《淮南子》曰：大厦成而燕雀相贺。","sortOrder":93},
  {"id":"s_work_nvlt_92_94","chapterId":"ch_work_nvlt_92","text":"《列仙傳》曰：簡狄，帝喾次妃，有娀之女也，姊妹浴於玄丘之水，有玄鳥衔卵而墜，五色甚好，相與競取，簡狄得而吞之，而生，［事具符命部。］玄中記曰：千歲之燕，戶北向。","sortOrder":94},
  {"id":"s_work_nvlt_92_95","chapterId":"ch_work_nvlt_92","text":"《九章筭術》曰：五雀六燕，飛集衡，衡適平，［原訛卒，據冯校本改。］一雀一燕，飛而易處，則雀重而燕輕。","sortOrder":95},
  {"id":"s_work_nvlt_92_96","chapterId":"ch_work_nvlt_92","text":"《茅君傳》曰：句曲山上有神芝五种，第三名燕胎芝，其色紫，形如葵葉，上有燕象，如欲飛状，光明洞彻，食一株，拜為太清仙君，正一郎中。","sortOrder":96},
  {"id":"s_work_nvlt_92_97","chapterId":"ch_work_nvlt_92","text":"《晉中興書》曰：中原丧亂，乡人遂共推郄鑒為主，與千餘家俱避難於魯國嶧山，山有重险，百姓飢饉，野無生草，時或掘野鼠蟄燕而食之。","sortOrder":97},
  {"id":"s_work_nvlt_92_98","chapterId":"ch_work_nvlt_92","text":"《湘中記》曰：零陵有石燕，形似燕，得雷風則飛，頡颃如真燕。","sortOrder":98},
  {"id":"s_work_nvlt_92_99","chapterId":"ch_work_nvlt_92","text":"《宣城記》曰：侍中紀昌睦初生，有白燕一双出屋，既表素质，宦途亦通。","sortOrder":99},
  {"id":"s_work_nvlt_92_100","chapterId":"ch_work_nvlt_92","text":"段龟龍《涼州記》曰：呂光大安三年，白燕遊酒泉郡，黑燕列從。","sortOrder":100},
  {"id":"s_work_nvlt_92_101","chapterId":"ch_work_nvlt_92","text":"【詩】古詩曰：思為双飛燕，衔泥巢君屋。","sortOrder":101},
  {"id":"s_work_nvlt_92_102","chapterId":"ch_work_nvlt_92","text":"又曰：翩翩堂前燕，冬藏夏來見，兄弟兩三人，流宕在他縣。","sortOrder":102},
  {"id":"s_work_nvlt_92_103","chapterId":"ch_work_nvlt_92","text":"魏明帝短歌行曰：翩翩春燕，端集餘堂，陰匿陽顯，節運自常，厥貌淑美，玄衣素裳，歸仁服德，雌雄頡颃，執志精专，絜行馴良，衔土繕巢，有式宮房，不規自圓，無矩而方。","sortOrder":103},
  {"id":"s_work_nvlt_92_104","chapterId":"ch_work_nvlt_92","text":"宋鮑昭詠双燕詩曰：双燕戲雲崖，羽翮始差池，出入南閨里，經過北堂陲，意欲巢君幕，層楹不可窥，沉吟芳歲晚，徘徊韶景移，悲歌辭舊愛，衔淚觅所知，梁簡文帝双燕詩曰：双燕有雌雄，照日羽差池，衔花落北戶，逐蝶上南枝，桂棟本曾宿，虹梁早自窥，原得長如此，無令双燕離。","sortOrder":104},
  {"id":"s_work_nvlt_92_105","chapterId":"ch_work_nvlt_92","text":"又詠新燕詩曰：新禽應節歸，俱向吹樓飛，入帘驚钏响，來窗礙舞衣。","sortOrder":105},
  {"id":"s_work_nvlt_92_106","chapterId":"ch_work_nvlt_92","text":"梁吳筠詠燕曰：一燕海上來，一燕高堂息，一朝相逢遇，依然舊相識，問餘來何遲，山川幾紆直，答言海路長，風駛飛無力。","sortOrder":106},
  {"id":"s_work_nvlt_92_107","chapterId":"ch_work_nvlt_92","text":"梁庾肩吾詠簷燕曰：双燕集蘭閨，双飛高复低，向戶疑新箔，登巢識故泥，依朓本相贺，近幕原同栖。","sortOrder":107},
  {"id":"s_work_nvlt_92_108","chapterId":"ch_work_nvlt_92","text":"又和晉安王詠燕曰：可怜幕上燕，差池弄羽衣，夜夜同巢宿，朝朝相背飛，衔泥贍樂善，相贺奉英徽，秋蝉行寂寞，恋此未辭歸。","sortOrder":108},
  {"id":"s_work_nvlt_92_109","chapterId":"ch_work_nvlt_92","text":"陳萧詮詠衔泥双燕詩曰：衔泥金屋外，表瑞玉筐中，學飛疑漢妾，巢幕憚吳宮，爪截還猶短，窠成新尚空，詎併零陵石，飛舞逐春風。","sortOrder":109},
  {"id":"s_work_nvlt_92_110","chapterId":"ch_work_nvlt_92","text":"隋江總詠燕燕於飛應詔詩曰：二月春暉暉，双燕理毛衣，衔花弄靃靡，拂葉隱芳菲，或在堂間戲，多從幕上飛，若作仙人履，應往日南歸。","sortOrder":110},
  {"id":"s_work_nvlt_92_111","chapterId":"ch_work_nvlt_92","text":"隋虞世基《賦得戲燕俱宿》詩：大厦初構與雲齊，歸燕双入正衔泥，欲繞歌梁自舞閣，偶為仙履往蘭閨，千里爭飛會難併，聊向吳宮比翼栖。","sortOrder":111},
  {"id":"s_work_nvlt_92_112","chapterId":"ch_work_nvlt_92","text":"【賦】晉傅鹹燕賦曰：有言燕今年巢在此，明歲故复來者，其將逝，翦爪識之，其後果至焉，燕燕於飛，差池其羽，何詩人之是興，信進止之有序，秋背陰以龍潛，春晞陽而鳳舉，隨時宜以行藏，似君子之出處，惡焚巢之凶丑，患林野之多阻，谅鳥獸之難群，非斯人而誰與，惟里仁［原作人，據冯校本改。］之為美，讬君子之堂寓，逮來春而复旋，意眷眷而懷舊，一委身乃無口，豈改適而更赴。","sortOrder":112},
  {"id":"s_work_nvlt_92_113","chapterId":"ch_work_nvlt_92","text":"晉盧諶燕賦曰：爰集崇宇，依於其榮，布窠巢之列列，孕子鷇之嘤嘤，铨先後而均哺，邁尸鳩之能平，於是族類偕長，雄雌俱逝，頡颃水湄，下上雲际，嘲哳間關，倏忽漂潎，來如隼击，去若凫跇，斗建午而子指，日在戍而後憩。","sortOrder":113},
  {"id":"s_work_nvlt_92_114","chapterId":"ch_work_nvlt_92","text":"晉夏侯湛玄鳥賦曰：觀羽族之群類，美玄鳥之翔集，順陰陽以出處，隨寒暑而遊蟄，擢翾翾之麗容，揮連翩之玄翼，挺參差之羞尾，發緇素之鮮色，及至大火西景，商風授衣，遂匿形於深穴，斂六翮而不飛，含靜泊以充肌，吸至和之精粹，澹恬心以去欲，故保生而不匮，虞眾物之為害，獨弃林而凭人，不驚畏以自疏，永歸馴而附親，有受祥而皇祇，故遺卵而生殷，惟帝皇之嘉美，置高禖以表神，類鸞皇之知德，象君子之安仁，爾乃衔泥構巢，營居傅桷，積一喙而不已，終累泥而成屋，拾柔草以自藉，采懦毛以為蓐，吐清惠之冷音，永吟鳴而自足。","sortOrder":114},
  {"id":"s_work_nvlt_92_115","chapterId":"ch_work_nvlt_92","text":"【贊】晉郭璞燕贊曰：燕燕於飛，瑞娥以卵，玄玉爰發，聖敬日遠，商人是頌，詠之絃管。","sortOrder":115},
  {"id":"s_work_nvlt_92_116","chapterId":"ch_work_nvlt_92","text":"【頌】晉傅統妻辛女燕頌曰：翩翩玄鳥，載飛載扬，頡颃庭宇，遂集我堂，衔泥啄草，造作室房，避彼湫隘，處此高涼，孕育五子，靡夭靡傷，羽翼既就，縱心翱翔，顧影逸豫，其樂難忘。","sortOrder":116},
  {"id":"s_work_nvlt_92_118","chapterId":"ch_work_nvlt_92","text":"《禮記》曰：仲春之月，鷹化為鳩。","sortOrder":118},
  {"id":"s_work_nvlt_92_119","chapterId":"ch_work_nvlt_92","text":"《方言》曰：鳩自關而東，周鄭之郊，韓魏之都，謂之郎睪，其大者謂之鳻鳩。","sortOrder":119},
  {"id":"s_work_nvlt_92_120","chapterId":"ch_work_nvlt_92","text":"《列子》曰：邯鄲之人，以正月之旦，獻鳩於簡子，簡子大愧，［列子說符作悅。］厚賞之。","sortOrder":120},
  {"id":"s_work_nvlt_92_121","chapterId":"ch_work_nvlt_92","text":"《說苑》曰：枭逢鳩，鳩曰：子將安之，枭曰：我將東徙，鳩曰：子改鳴則可，不能改鳴，東徙猶惡子之聲也。","sortOrder":121},
  {"id":"s_work_nvlt_92_122","chapterId":"ch_work_nvlt_92","text":"《續漢禮儀志》曰：仲秋之月，縣道皆案戶比民，年始七十者，授之以玉杖，餔之糜粥，八十九十，禮有加賜，玉杖長九尺，端以鳩為飾，鳩者不噎之鳥也，欲老人不噎，所以愛民也。","sortOrder":122},
  {"id":"s_work_nvlt_92_123","chapterId":"ch_work_nvlt_92","text":"《風俗通》曰：俗說高祖與項羽戰，败於京索，遁丛薄中，羽追求之，時鳩正鳴其上，追者以鳥在無人，遂得脱，及即位，異此鳥，故作鳩杖，以賜老者。","sortOrder":123},
  {"id":"s_work_nvlt_92_124","chapterId":"ch_work_nvlt_92","text":"按，少皞五鳩，鳩者聚，聚民也，周禮羅氏，獻鳩養老，漢無羅氏，故作鳩杖以扶老。","sortOrder":124},
  {"id":"s_work_nvlt_92_125","chapterId":"ch_work_nvlt_92","text":"《琴操》曰：舜耕於歷山，思慕父母，見鳩與母俱飛鳴相哺食，益以感思，乃作歌。","sortOrder":125},
  {"id":"s_work_nvlt_92_126","chapterId":"ch_work_nvlt_92","text":"《會稽典錄》曰：皮延，字叔然，會稽山陰人，養母至孝，居丧，有白鳩巢庐侧，遂以丧終。","sortOrder":126},
  {"id":"s_work_nvlt_92_127","chapterId":"ch_work_nvlt_92","text":"又曰：鄭弘遷臨淮太守，郡人徐憲，在丧致哀，白鳩巢戶侧，弘舉為孝廉，朝庭稱為白鳩郎。","sortOrder":127},
  {"id":"s_work_nvlt_92_128","chapterId":"ch_work_nvlt_92","text":"《廣州先賢傳》曰：頓琦，蒼梧人，至孝，母丧，琦獨身立墳，歷年乃成，居丧逾製，感物通靈，白鳩栖息庐侧，見人辄去，見琦而留。","sortOrder":128},
  {"id":"s_work_nvlt_92_129","chapterId":"ch_work_nvlt_92","text":"《搜神記》曰：京兆長安有張氏，獨處室，有鳩自外入，止於床，張氏祝曰：鳩來，為我禍也，飛上承尘，為我福耶，來入我懷，鳩飛入懷，以手探之，則不知鳩之所在，而得一金帶鉤，是後子孫過盛，有為必偶，赀财萬倍，蜀客贾至長安中，聞之，乃厚賂婢，婢竊鉤以與蜀客，張氏既失鉤，漸漸衰耗，而蜀客亦數罹窮厄，不為己利，或告之曰：天命也，不可以力求，於是赍鉤以反張氏，張氏复昌，故關西稱張氏傳鉤雲。","sortOrder":129},
  {"id":"s_work_nvlt_92_130","chapterId":"ch_work_nvlt_92","text":"又曰：沛國戴文諶，居陽城山，有神降焉，其妻疑是妖魅，神已知之，便去，遂视作一五色鳥，白鳩數十只後，有雲覆之，遂不見。","sortOrder":130},
  {"id":"s_work_nvlt_92_131","chapterId":"ch_work_nvlt_92","text":"【詩】魏王粲詩曰：鷙鳥化為鳩，遠竄江漢邊，遭遇風雲會，讬身鸞鳳間，天姿既否戾，受性又不閒，邂逅見逼迫，俯仰不得言。","sortOrder":131},
  {"id":"s_work_nvlt_92_132","chapterId":"ch_work_nvlt_92","text":"【賦】晉傅鹹班鳩賦曰：集茂树之荫蔚，登弱枝以容與，體鬱鬱以敷文，音邕邕而有序，情钦樂而是悅，遂籠之於前宇，爾乃飲以神泉，食之稻粱，朝憩椒涂，夕宿蘭房，時連翩於庭阿，見飛燕之頡颃，慨感物而哀鳴，聲楚切以懷傷，仰華林而矯翼，紛憎逝而高翔。","sortOrder":132},
  {"id":"s_work_nvlt_92_133","chapterId":"ch_work_nvlt_92","text":"【謳】魏陳王曹植魏德論謳曰：班班者鳩，爰素其质，昔翔殷邦，今為魏出，朱目丹趾，靈姿诡類，載飛載鳴，彰我皇懿。","sortOrder":133},
  {"id":"s_work_nvlt_92_134","chapterId":"ch_work_nvlt_92","text":"【論】魏陳王曹植令禽惡鳥論曰：昔荆之枭，將徙巢於吳，鳩遇之曰：子將安之，枭曰：將巢於吳，鳩曰：何去荆而巢吳乎，枭曰：荆人惡予之聲，鳩曰：子能革子之聲，則無為去荆而巢吳也，如不能革子之聲，則吳楚之民，不異情也，為子計者，莫若宛頸戢翼，終身勿复鳴也。","sortOrder":134},
  {"id":"s_work_nvlt_92_135","chapterId":"ch_work_nvlt_92","text":"【序】晉阮籍鳩賦序曰：嘉平中，得兩鳩子，常食以黍稷，後卒為狗所殺，故作賦。","sortOrder":135},
  {"id":"s_work_nvlt_92_137","chapterId":"ch_work_nvlt_92","text":"《春秋運斗枢》曰：玉衡星散為鴟。","sortOrder":137},
  {"id":"s_work_nvlt_92_138","chapterId":"ch_work_nvlt_92","text":"《爾雅》曰：鳶乌丑，其飛也翔。","sortOrder":138},
  {"id":"s_work_nvlt_92_139","chapterId":"ch_work_nvlt_92","text":"《禮記》曰：前有尘埃，則載鳴鳶，［鳶鳴則將風。］","sortOrder":139},
  {"id":"s_work_nvlt_92_140","chapterId":"ch_work_nvlt_92","text":"《莊子·內篇》：鴟鴉嗜鼠，{即虫}蛆甘螮。","sortOrder":140},
  {"id":"s_work_nvlt_92_141","chapterId":"ch_work_nvlt_92","text":"《鹽鐵論》曰：泰山之鴟，啄腐鼠於窮泽，非有害人也，今有司盜主财而食之，焉得若泰山之鴟乎。","sortOrder":141},
  {"id":"s_work_nvlt_92_142","chapterId":"ch_work_nvlt_92","text":"《列仙傳》曰：季仲甫夜臥床上，或為鴟鳥，後至沓縣巨山上，候北風，當飛度南海，山上有羅鷹者，羅得鴟，视之仲甫也，後留更三年，自雲往崑崙山。","sortOrder":142},
  {"id":"s_work_nvlt_92_143","chapterId":"ch_work_nvlt_92","text":"《東觀漢記》曰：馬援击交趾，下潦上霧，毒氣上蒸，仰视乌鳶，跕跕墮水中。","sortOrder":143},
  {"id":"s_work_nvlt_92_144","chapterId":"ch_work_nvlt_92","text":"《博物志》曰：漢舊事，綦國送鳶卵，給太官。","sortOrder":144},
  {"id":"s_work_nvlt_92_145","chapterId":"ch_work_nvlt_92","text":"【詩】魏劉楨射鳶詩曰：鳴鳶弄双翼，飄飄薄青雲，我後橫怒起，意氣陵神仙，發機如驚焱，三發兩鳶連，流血洒牆屋，飛毛從風旋，庶士同聲贊，君射一何妍。","sortOrder":145},
  {"id":"s_work_nvlt_92_146","chapterId":"ch_work_nvlt_92","text":"◇反舌","sortOrder":146},
  {"id":"s_work_nvlt_92_147","chapterId":"ch_work_nvlt_92","text":"《禮記》曰：仲夏之月，反舌無聲。","sortOrder":147},
  {"id":"s_work_nvlt_92_148","chapterId":"ch_work_nvlt_92","text":"《左傳》曰：郯子雲，少皞祝鳩氏，司徒也。","sortOrder":148},
  {"id":"s_work_nvlt_92_149","chapterId":"ch_work_nvlt_92","text":"《易緯通卦》［《太平御覽》九百二十三卦下有验字。］曰：百舌者，反舌鳥也，能反覆其口，隨百鳥之音。","sortOrder":149},
  {"id":"s_work_nvlt_92_150","chapterId":"ch_work_nvlt_92","text":"《風土記》曰：祝鳩反舌也。","sortOrder":150},
  {"id":"s_work_nvlt_92_151","chapterId":"ch_work_nvlt_92","text":"春秋保乾［《太平御覽》九百二十三乾下有圖字。］曰：江充之害，其萌反舌鳥入殿。","sortOrder":151},
  {"id":"s_work_nvlt_92_152","chapterId":"ch_work_nvlt_92","text":"【詩】梁沈約侍宴詠反舌詩曰：假客不足觀，遺音猶可荐，幸蒙乔树恩，得以聞高殿。","sortOrder":152},
  {"id":"s_work_nvlt_92_153","chapterId":"ch_work_nvlt_92","text":"梁劉孝綽詠百舌詩曰：山人惜春暮，旭旦坐花林，复值懷春鳥，枝間弄好音，遷乔聲迥出，赴穀响幽深，下聽長而短，時聞絕复尋，孤鳴若無對，百啭似群吟，昔聞屢懽昔，今聽忽悲今，聽聞非殊異，遲暮獨傷心。","sortOrder":153},
  {"id":"s_work_nvlt_92_154","chapterId":"ch_work_nvlt_92","text":"梁徐悱妻劉氏聽百舌詩曰：庭树旦新晴，臨鏡出雕楹，風吹桃李氣，過傳春鳥聲，净寫山陽笛，全作洛濱笙，註意歡留聽，誤令妆不成。","sortOrder":154},
  {"id":"s_work_nvlt_92_155","chapterId":"ch_work_nvlt_92","text":"陳〈身甹〉使韦鼎在長安聽百舌詩曰：萬里風煙異，一鳥忽相驚，那能對遠客，還作故乡聲。","sortOrder":155},
  {"id":"s_work_nvlt_92_156","chapterId":"ch_work_nvlt_92","text":"【賦】梁沈約反舌賦曰：咨玄造之大德，播含靈於無小，有反舌之微禽，亦班名於庶鳥，乏嘉容之可玩，因繁聲以自表，其聲也，驚诡遒囋，萦紆離亂，骈浮回合，嵒危琐散，或發曲無漸，或收音雲半，既含意於將晓，亦流妍於始旦，雜沓逶迤，噭跳參差，攒娇動葉，促啭萦枝，分宮析徵，萬矩千規，因風起哢，曳响生奇，對芳辰於此月，屬今餘之遒暮，倦城守之喧疲，愛田郊之閒素，眷春物而懷之，聞好音於庭树。","sortOrder":156},
  {"id":"s_work_nvlt_92_157","chapterId":"ch_work_nvlt_92","text":"梁萧子暉反舌賦曰：彼陶嘉之盛月，氣依遲於池沼，眷霏霏之花落，愛翘翘之令鳥，無榮辱之可固，弄枢機而自表，爾其聲也，嘹唳罥結，鬱抑萦咽，繁音琐碎，眾响攒〈山截〉，或急啭赴機，或缓引趨節，或洪纖共起，或長短俱折，意疑續而更斷，謂當舉而忽垂，聲冯林而逾厲，响因風而益危。","sortOrder":157},
  {"id":"s_work_nvlt_92_158","chapterId":"ch_work_nvlt_92","text":"◇仓庚","sortOrder":158},
  {"id":"s_work_nvlt_92_159","chapterId":"ch_work_nvlt_92","text":"《說文》曰：離黃，仓庚也，鳴即蠶生。","sortOrder":159},
  {"id":"s_work_nvlt_92_160","chapterId":"ch_work_nvlt_92","text":"《禮記》曰：仲春之月，仓庚鳴。","sortOrder":160},
  {"id":"s_work_nvlt_92_161","chapterId":"ch_work_nvlt_92","text":"《毛詩》曰：春日載陽，有鳴仓庚。","sortOrder":161},
  {"id":"s_work_nvlt_92_162","chapterId":"ch_work_nvlt_92","text":"又曰：仓庚於飛，熠燿其羽。","sortOrder":162},
  {"id":"s_work_nvlt_92_163","chapterId":"ch_work_nvlt_92","text":"又曰：黃鳥於飛，集於灌木。","sortOrder":163},
  {"id":"s_work_nvlt_92_164","chapterId":"ch_work_nvlt_92","text":"又，綿蠻黃鳥，止於丘阿。","sortOrder":164},
  {"id":"s_work_nvlt_92_165","chapterId":"ch_work_nvlt_92","text":"又曰：睍睆黃鳥，載好其音。","sortOrder":165},
  {"id":"s_work_nvlt_92_166","chapterId":"ch_work_nvlt_92","text":"又曰：黃鳥，哀三良也，交交黃鳥，止於棘，誰從穆公，子車奄息。","sortOrder":166},
  {"id":"s_work_nvlt_92_167","chapterId":"ch_work_nvlt_92","text":"《詩義疏》曰：黃鳥，鸝鹠也，或謂黃栗留，幽州謂之黃鴦，或謂之黃鳥，一名仓庚，一名商庚，一名鸝黃，一名楚雀，齊人謂之摶黍，關西謂之黃鳥，常椹熟時，來在桑树間，皆應節趣時之鳥，或謂之黃袍。","sortOrder":167},
  {"id":"s_work_nvlt_92_168","chapterId":"ch_work_nvlt_92","text":"【賦】魏文帝鶯賦曰：堂前有籠鶯，晨夜哀鳴，凄若有懷，怜而賦之曰：怨羅人之我困，痛密網而在身，顧窮悲而無告，知時命之將泯，升華堂而進御，奉明後之威神，唯今日之僥倖，得去死而就生，讬幽籠以栖息，厲清風而哀鳴。","sortOrder":168},
  {"id":"s_work_nvlt_92_169","chapterId":"ch_work_nvlt_92","text":"魏王粲鶯賦曰：覽堂隅之籠鳥，獨高懸而背時，雖物微而命輕，心凄怆而愍之，日掩藹以西邁，忽逍遙而既冥，就隅角而斂翼，眷獨宿而宛頸，歷長夜以向晨，聞仓庚之群鳴，春鳴翔於南甍，戴纴集乎東榮，既同時而異忧，實感類而傷情。","sortOrder":169},
  {"id":"s_work_nvlt_92_170","chapterId":"ch_work_nvlt_92","text":"晉王惲妻鍾夫人鶯賦曰：嘉京都之鶯鳥，冠群類之殊形，擢末軀於紫闼，超顯御乎天庭，惟節運之不停，懼龍角之西頹，慕同時之逸豫，怨商風之我催。","sortOrder":170},
  {"id":"s_work_nvlt_92_171","chapterId":"ch_work_nvlt_92","text":"◇鹪鹩","sortOrder":171},
  {"id":"s_work_nvlt_92_172","chapterId":"ch_work_nvlt_92","text":"《爾雅》曰：桃虫鹪，其雌鴱，俗名巧婦。","sortOrder":172},
  {"id":"s_work_nvlt_92_173","chapterId":"ch_work_nvlt_92","text":"又曰：鹪鹩剖苇，［好剖苇皮，食其虫，因名雲，江東呼為芦虎，似雀，青班長尾鹪。］又曰：鴟鴞鸋窸。","sortOrder":173},
  {"id":"s_work_nvlt_92_174","chapterId":"ch_work_nvlt_92","text":"《毛詩》曰：鴟鴞，周公救亂也，鴟鴞鴟鴞，既取我子，無毀我室。","sortOrder":174},
  {"id":"s_work_nvlt_92_175","chapterId":"ch_work_nvlt_92","text":"《詩義疏》曰：鴟鴞似黃雀而小，啄刺如錐，取茅為窠，以麻紩之，刺紩靴懸著树枝，幽州為之鸋窸，或曰巧婦，或曰女匠，關西謂之蔑雀。","sortOrder":175},
  {"id":"s_work_nvlt_92_176","chapterId":"ch_work_nvlt_92","text":"《毛詩》曰：肇允彼桃虫，［今鹪鹩是也，見詩義疏。］故《爾雅》曰：桃虫鹪也，微小黃雀，其雏化為蜩，故俗語曰：鹪鹩生蜩，焦貢《易林》，亦謂桃虫生蜩，或雲布穀生子，鹪鹩養之。","sortOrder":176},
  {"id":"s_work_nvlt_92_177","chapterId":"ch_work_nvlt_92","text":"《莊子》曰：鹪鹩巢林，不過一枝。","sortOrder":177},
  {"id":"s_work_nvlt_92_178","chapterId":"ch_work_nvlt_92","text":"《說苑》曰：孟嘗君寄客於齊王，三年不見用，客反見孟嘗君曰：不知臣罪耶，君之過也，孟嘗君曰：縷因針而入，不因針而急，夫子之才必薄矣，客曰：不然，臣見鹪鹩巢於苇之苕，鸿毛著之，已建之安，工女不能為，可謂完堅矣，大風至則苕折卵破者，其所讬者使然也。","sortOrder":178},
  {"id":"s_work_nvlt_92_179","chapterId":"ch_work_nvlt_92","text":"【賦】晉張華鹪鹩賦曰：何造化之多端，播群形於萬類，惟鹪鹩之微禽，亦攝生而受氣，飛不飄颺，翔不翕習，巢林不過一枝，每食不過數粒。","sortOrder":179},
  {"id":"s_work_nvlt_92_180","chapterId":"ch_work_nvlt_92","text":"◇啄木","sortOrder":180},
  {"id":"s_work_nvlt_92_181","chapterId":"ch_work_nvlt_92","text":"《臨海異物志》曰：啄木大如雀，啄足皆青，毛色正青，翠鳥類也，凡與啄木異种，舌長五寸，杪有刺針。","sortOrder":181},
  {"id":"s_work_nvlt_92_182","chapterId":"ch_work_nvlt_92","text":"【詩】排諧集，左氏詩曰：南山有鳥，自名啄木，飢則啄树，暮則巢宿，無幹於人，唯志所欲，性清者榮，性濁者辱。","sortOrder":182},
  {"id":"s_work_nvlt_92_183","chapterId":"ch_work_nvlt_92","text":"晉傅玄詩曰：啄木高翔鳴喈喈，飄搖林薄著桑槐，犭便猭树間喙如錐，嘤喔嘤喔聲正悲，专為萬物作倡俳，當此之時，樂不可回。","sortOrder":183},
  {"id":"s_work_nvlt_92_184","chapterId":"ch_work_nvlt_92","text":"◇鴛鴦","sortOrder":184},
  {"id":"s_work_nvlt_92_185","chapterId":"ch_work_nvlt_92","text":"《歸藏》曰：有凫鴛鴦，有雁鷫鹴。","sortOrder":185},
  {"id":"s_work_nvlt_92_186","chapterId":"ch_work_nvlt_92","text":"《毛詩》曰：鴛鴦，刺幽王也，思古明王，交於萬物有道，自奉養有節，鴛鴦於飛，畢之羅之，君子萬年，福祿宜之。","sortOrder":186},
  {"id":"s_work_nvlt_92_187","chapterId":"ch_work_nvlt_92","text":"《魏志》：文帝問周宣曰：吾夢殿屋兩瓦墜地，化為鴛鴦，何也，宣對曰：後宮當有暴死者，帝曰：吾诈卿耳，宣曰：夫夢者意耳，苟以形言，便占吉凶，言未卒，黃門令奏宮人相殺。","sortOrder":187},
  {"id":"s_work_nvlt_92_188","chapterId":"ch_work_nvlt_92","text":"鄭氏婚禮謁文贊曰：鴛鴦鳥，雄雌相類，飛止相匹。","sortOrder":188},
  {"id":"s_work_nvlt_92_189","chapterId":"ch_work_nvlt_92","text":"《列異傳》曰：宋康王埋韓冯夫妻，宿夕文梓生，有鴛鴦雌雄各一，恒栖树上，晨夕交頸，音聲感人。","sortOrder":189},
  {"id":"s_work_nvlt_92_190","chapterId":"ch_work_nvlt_92","text":"【詩】古歌辭曰：入門時左顧，但見双鴛鴦，鴛鴦七十二，羅列自成行，音聲何噰々，鶴鳴東西厢。","sortOrder":190},
  {"id":"s_work_nvlt_92_191","chapterId":"ch_work_nvlt_92","text":"晉嵇叔夜詩曰：鴛鴦於飛，肅肅其羽，嗈嗈和鳴，顧眄儔侣。","sortOrder":191},
  {"id":"s_work_nvlt_92_192","chapterId":"ch_work_nvlt_92","text":"又曰：婉彼鴛鴦，戢翼而遊，俯吮绿藻，讬身洪流，朝翔素瀨，夕栖靈洲。","sortOrder":192},
  {"id":"s_work_nvlt_92_193","chapterId":"ch_work_nvlt_92","text":"【賦】梁簡文帝鴛鴦賦曰：朝飛绿岸，夕歸丹屿，顧落日而俱吟，追清風而双舉，時排荇蒂，乍拂菱華，始臨涯而作影，遂蹙水而生花，亦有佳麗自如神，宜羞宜笑复宜嚬，既是金閨新入寵，复是蘭房得意人，見茲禽之栖宿，想君意之相親。","sortOrder":193},
  {"id":"s_work_nvlt_92_194","chapterId":"ch_work_nvlt_92","text":"梁元帝鴛鴦賦曰：青田之鶴，晝夜俱飛，日南之雁，從來共歸，双飛兮不息，自怜兮何極，一別兮經年，相去兮幾千，雄飛入玄兔，雌去往朱鳶，豈如鴛鴦相逐，俱栖俱宿，勝林鳥之同心，邁池魚之比目，朝浮兮浪華，夜集兮江沙，萍隨流而博岸，網因風而缀花，見虹梁之春色，复相鳴而戢翼，蘭渚兮相依，同盛兮同衰，魂上相思之树，文生新市之機，金雞玉鵲不成群，紫鶴紅雉一生分，原學鴛鴦鳥，連翩恒逐君。","sortOrder":194},
  {"id":"s_work_nvlt_92_195","chapterId":"ch_work_nvlt_92","text":"周庾信鴛鴦賦曰：盧姬小來事魏王，自有歌聲足繞梁，何曾織錦，未肯挑桑，終歸薄命，著罢空床，見鴛鴦之相學，還欹眠而淚落，南陽渍粉不复看，京兆新眉遂嬾約，况复双心併翼，馴狎池籠，浮波弄影，刷羽看風，共飛詹幾，全开魏宮，俱栖梓树，堪是韓冯，若乃韓寿欲婚，溫峤原婦，玉台不送，胡香未有，必見此之双飛，覺空床之難守。","sortOrder":195},
  {"id":"s_work_nvlt_92_196","chapterId":"ch_work_nvlt_92","text":"陳徐陵鴛鴦賦曰：飛飛兮海濱，去去兮迎春，炎皇之季女，織素之佳人，未若宋王之小史，含情而死，憶少婦之生離，恨新婚之無子，既交頸於千年，亦相隨於萬里，山雞映水那相得，孤鸞照鏡不成双，天下真成長合會，無勝比翼兩鴛鴦，觀其哢吭浮沉，輕軀瀺灂，拂荇戲而波散，排荷翻而水落，特訝鴛鴦鳥，長情真可念，許處勝人多，何時肯相厭，聞道鴛鴦一鳥名，教人如有逐春情，不見臨邛卓家女，祗為琴中作許聲。","sortOrder":196},
  {"id":"s_work_nvlt_92_197","chapterId":"ch_work_nvlt_92","text":"◇鵁鶄","sortOrder":197},
  {"id":"s_work_nvlt_92_198","chapterId":"ch_work_nvlt_92","text":"《爾雅》曰：鳽，鵁鶄。","sortOrder":198},
  {"id":"s_work_nvlt_92_199","chapterId":"ch_work_nvlt_92","text":"《說文》曰：鵁鶄，鳽也，一曰鵁鸕，［似凫，腳高毛冠，江東人家養之，以厭火灾。］","sortOrder":199},
  {"id":"s_work_nvlt_92_200","chapterId":"ch_work_nvlt_92","text":"《異物志》曰：鵁鶄巢於高树，生子在窟中，未能飛，皆衔其翼飛也。","sortOrder":200},
  {"id":"s_work_nvlt_92_201","chapterId":"ch_work_nvlt_92","text":"【賦】晉挚虞鵁鶄賦曰：有南州之奇鳥，谅殊美而可嘉，生九皋之曠泽，遊江淮之洪波，既翦翼以就養，遂婉娈乎邦家，鵁鶄呈儀，若刻若畫，鸞頸龟背，戴玄珥白，班毛赪膺，駮羽朱掖，青不专绀，纁不擅赤，因宛點註，希稠有適，其在水也，則巧態多姿，調節柔骨，一低一仰，乍浮乍没，或遊或舞，繽翻倏忽，若乃陽故多陰，殊方相求，見水則喜，睹火而忧。","sortOrder":201},
  {"id":"s_work_nvlt_92_202","chapterId":"ch_work_nvlt_92","text":"梁簡文帝鵁鶄賦曰：飲三芝之淳露，食六草之英芳，似金沙之符采，同錦质之報章，紅毛覆臆，翠鬛垂心，浴波泳渚，浮廣戲深，臨高舞翮，映淺弄音，逐餘暉而顧景，乘清吹而微吟。","sortOrder":202},
  {"id":"s_work_nvlt_92_203","chapterId":"ch_work_nvlt_92","text":"◇鸂鶒","sortOrder":203},
  {"id":"s_work_nvlt_92_204","chapterId":"ch_work_nvlt_92","text":"《臨海異物志》曰：鸂鶒水鳥，毛有五色，食短狐，其在溪中，無毒氣。","sortOrder":204},
  {"id":"s_work_nvlt_92_205","chapterId":"ch_work_nvlt_92","text":"【詩】齊謝朓詠鸂鶒詩曰：蕙草含初芳，瑤池暧晚色，得廁鸿鸞影，晞光弄羽翼。","sortOrder":205},
  {"id":"s_work_nvlt_92_206","chapterId":"ch_work_nvlt_92","text":"梁簡文帝詠飛來鸂鶒詩曰：飛從何處來，似出上林隈，口衔長生葉，翅染崑明苔。","sortOrder":206},
  {"id":"s_work_nvlt_92_207","chapterId":"ch_work_nvlt_92","text":"【賦】宋謝惠連鸂鶒賦曰：覽水禽之萬類，信莫麗乎鸂鶒，服昭晰之鮮姿，糅玄黃之美色，命儔旅以翱遊，憩川湄而偃息，超神王以字得，不意虞人之在侧，網羅幕而雲布，摧羽翮於翩翻，乖沉浮之諧豫，宛羁畜於籠樊。","sortOrder":207},
  {"id":"s_work_nvlt_92_208","chapterId":"ch_work_nvlt_92","text":"◇白鷺","sortOrder":208},
  {"id":"s_work_nvlt_92_209","chapterId":"ch_work_nvlt_92","text":"《爾雅》曰：鷺舂鋤。","sortOrder":209},
  {"id":"s_work_nvlt_92_210","chapterId":"ch_work_nvlt_92","text":"《毛詩》：周頌曰：振鷺於飛，於彼西雝。","sortOrder":210},
  {"id":"s_work_nvlt_92_211","chapterId":"ch_work_nvlt_92","text":"《詩義疏》曰：鷺，水鳥也，好而絜白，謂之白鳥，齊魯謂之舂鋤，遼東樂浪吳楊謂之白鷺，楚成王時，有朱鷺，合沓飛翔，复有赤色者，舊鼓吹音樂朱鷺曲是也。","sortOrder":211},
  {"id":"s_work_nvlt_92_212","chapterId":"ch_work_nvlt_92","text":"【賦】宋謝惠連白鷺賦曰：有提樊而見獻，寔振鷺之鮮禽，表弗緇之素质，挺樂水之奇心。","sortOrder":212},
  {"id":"s_work_nvlt_92_213","chapterId":"ch_work_nvlt_92","text":"【詩】陳蘇子卿鼓吹曲朱鷺詩曰：玉山一朱鷺，容與入王畿，欲向天池飲，過繞上林飛，金隄麗羽翮，丹水浴毛衣，非貪葭下食，懷恩自遠歸。","sortOrder":213},
  {"id":"s_work_nvlt_92_214","chapterId":"ch_work_nvlt_92","text":"◇鸊鹈","sortOrder":214},
  {"id":"s_work_nvlt_92_215","chapterId":"ch_work_nvlt_92","text":"《方言》曰：野凫甚小，好没水中，南楚之人，謂之鸊鹈，大者謂之鶻蹄。","sortOrder":215},
  {"id":"s_work_nvlt_92_216","chapterId":"ch_work_nvlt_92","text":"《爾雅》曰：鹈鴮鸅。","sortOrder":216},
  {"id":"s_work_nvlt_92_217","chapterId":"ch_work_nvlt_92","text":"【賦】晉張望鸊鹈賦曰：餘睹鸊鹈之為鳥也，形濬丛蔑，尾翮燋陋，樂水以遊。隨波淪躍，汎然任性，而無患也，惟鸊鹈之小鳥，讬川湖以繁育，翩舒翮以和鳴。匪窘惕於籠畜，瀺灂池沼，容與河洲，翔而不淹，集而不留，值汙則止，遇泽則遊，淪潭里以衔魚，躍浪表而相求，萃不擇渠，娱不擇川，隨風騰起，與涛回旋，沉竄則足拨圓波，浮泳則臆排微涟，率性命以閒放，獨遨逸而獲全。","sortOrder":217},
  {"id":"s_work_nvlt_92_219","chapterId":"ch_work_nvlt_92","text":"《說文》曰：鷗，水鴞也。","sortOrder":219},
  {"id":"s_work_nvlt_92_220","chapterId":"ch_work_nvlt_92","text":"仓頡解詁曰：鹥，鷗也。","sortOrder":220},
  {"id":"s_work_nvlt_92_221","chapterId":"ch_work_nvlt_92","text":"《山海經》曰：玄股國，其人食鷗。","sortOrder":221},
  {"id":"s_work_nvlt_92_222","chapterId":"ch_work_nvlt_92","text":"《列子》曰：海上之人好鷗者，每旦之海上，從鷗鳥遊，鷗鳥之至者，百數而不止，其父曰：吾聞鷗鳥皆從汝好，取來吾玩之，明日之海，鷗鳥舞而不下。","sortOrder":222},
  {"id":"s_work_nvlt_92_223","chapterId":"ch_work_nvlt_92","text":"《南越志》曰：江鷗，一名海鷗，在涨海中，隨潮上下，常以三月風至，乃還洲屿，頗知風雲，若群飛至岸，渡海者以此為候。","sortOrder":223},
  {"id":"s_work_nvlt_92_224","chapterId":"ch_work_nvlt_92","text":"【詩】梁何遜詠白鷗詩曰：可怜双白鷗，朝夕水上遊，何言異栖鳥，雌住雄不留，孤飛出浦溆，獨宿下沧洲，東西從此去，影响絕無由。","sortOrder":224},
  {"id":"s_work_nvlt_92_226","chapterId":"ch_work_nvlt_92","text":"《莊子》曰：北溟有魚，其名曰鯤，化而為鵬，鵬之背不知幾千里也，怒而飛，其翼若垂天之雲，是鳥也，海運將徙於南溟，南溟者，天池也，水击三千里，摶扶搖而上者九萬里。","sortOrder":226},
  {"id":"s_work_nvlt_92_227","chapterId":"ch_work_nvlt_92","text":"《幽明錄》曰：楚文王好獵，有人獻一鷹，王見爪距殊常，故為獵於雲夢，毛群羽族爭噬搏，此鷹瞪目遠瞻雲际，俄有一物，凝翔鮮白，不辨其形，鷹便竦翮而升，矗若飛電，須臾，羽墮如雪，血下如雨，有大鳥墮地，度其兩翅，廣數十里，時有博物君子曰：此大鵬雏也，文王乃厚賞之。","sortOrder":227},
  {"id":"s_work_nvlt_92_228","chapterId":"ch_work_nvlt_92","text":"《異類傳》曰：漢武帝時，西域獻黑鷹，得鵬雏，東方朔識之。","sortOrder":228},
  {"id":"s_work_nvlt_92_229","chapterId":"ch_work_nvlt_92","text":"【賦】晉贾彪鵬賦曰：餘覽張茂先鹪鹩賦，以其质微處藝，而偏於受害，愚以為未若大鵬，栖形遐遠，自育之全也，此固禍福之機，聊賦之雲，叹大鈞之播物，啟塊化於天壤，嘉有鵬之巨鳥，攝元氣之夸象，揭宇內之逼隘，遵四荒以汎荡。","sortOrder":229},
  {"id":"s_work_nvlt_92_230","chapterId":"ch_work_nvlt_92","text":"【贊】晉阮修大鵬贊曰：蹌蹌大鵬，誕自北溟，假精靈鱗，神化以生，如雲之翼，如山之形，海運水击，扶搖上征。","sortOrder":230},
  {"id":"s_work_nvlt_92_231","chapterId":"ch_work_nvlt_92","text":"◇精衛","sortOrder":231},
  {"id":"s_work_nvlt_92_232","chapterId":"ch_work_nvlt_92","text":"《山海經》曰：炎帝之女，名曰女娃，遊於東海，溺而不反，是為精衛，常取西山之木石，以填東海。","sortOrder":232},
  {"id":"s_work_nvlt_92_233","chapterId":"ch_work_nvlt_92","text":"【贊】晉郭璞精衛贊曰：炎帝之女，化為精衛，沉形東海，靈爽西邁，乃衔木石，以填攸害。","sortOrder":233},
  {"id":"s_work_nvlt_92_234","chapterId":"ch_work_nvlt_92","text":"◇翡翠","sortOrder":234},
  {"id":"s_work_nvlt_92_235","chapterId":"ch_work_nvlt_92","text":"《爾雅》曰：翠，鷸也。","sortOrder":235},
  {"id":"s_work_nvlt_92_236","chapterId":"ch_work_nvlt_92","text":"仓頡解詁曰：鷸，翠別名也。","sortOrder":236},
  {"id":"s_work_nvlt_92_237","chapterId":"ch_work_nvlt_92","text":"《說文》曰：翡，赤雀，翠，青雀也。","sortOrder":237},
  {"id":"s_work_nvlt_92_238","chapterId":"ch_work_nvlt_92","text":"《周書》曰：成王時，蒼梧獻翡翠。","sortOrder":238},
  {"id":"s_work_nvlt_92_239","chapterId":"ch_work_nvlt_92","text":"《孝經援神契》曰：神靈滋液，則翠羽曜。","sortOrder":239},
  {"id":"s_work_nvlt_92_240","chapterId":"ch_work_nvlt_92","text":"《離骚》曰：翾飛兮翠曾，［曾舉。］","sortOrder":240},
  {"id":"s_work_nvlt_92_241","chapterId":"ch_work_nvlt_92","text":"又曰：翡帷翠帱。","sortOrder":241},
  {"id":"s_work_nvlt_92_242","chapterId":"ch_work_nvlt_92","text":"《漢書》曰：尉佗獻文帝翠鳥千。","sortOrder":242},
  {"id":"s_work_nvlt_92_243","chapterId":"ch_work_nvlt_92","text":"又曰：燕刺王旦，郎中侍從，貂羽黃金附蝉，［翠羽飾冠。］","sortOrder":243},
  {"id":"s_work_nvlt_92_244","chapterId":"ch_work_nvlt_92","text":"《廣志》曰：翡色赤，翠色绀，皆出交州興古縣。","sortOrder":244},
  {"id":"s_work_nvlt_92_245","chapterId":"ch_work_nvlt_92","text":"吳錄，薛綜上疏曰：日南遠致翡翠，充備寶玩。","sortOrder":245},
  {"id":"s_work_nvlt_92_246","chapterId":"ch_work_nvlt_92","text":"徐廣車服註曰：天子辂金根車翠羽蓋，皇後首飾步搖，八雀九華，加翡翠。","sortOrder":246},
  {"id":"s_work_nvlt_92_247","chapterId":"ch_work_nvlt_92","text":"楊孝元［原訛先，據本書九十一卷孔雀篇改。］交趾《異物志》曰：翠鳥先高作巢，及生子，愛之，恐墮，稍下作巢，子生毛羽，复益愛之。又更下巢也。","sortOrder":247},
  {"id":"s_work_nvlt_92_248","chapterId":"ch_work_nvlt_92","text":"【詩】後漢蔡邕翠鳥詩曰：庭陬有若留，绿葉含丹榮，翠鳥時來集，振翼脩容形，回顧生碧色，動搖扬縹青。","sortOrder":248},
  {"id":"s_work_nvlt_92_249","chapterId":"ch_work_nvlt_92","text":"【賦】梁江淹翡翠賦曰：彼一鳥之奇麗，生金洲與炎山，映銅陵之素氣，灌碧磴之紅泉，斂慧性及馴心，騫赪翼與青羽，終絕命於虞人，充南賝於內府，備寶帳之光儀，登美女之麗飾，雜白玉而成文，糅紫金而為色，专妙采於五都，擅精華於八極。","sortOrder":249},
  {"id":"s_work_nvlt_92_250","chapterId":"ch_work_nvlt_92","text":"【贊】晉郭璞翠贊曰：翠雀麇鳥，越在南海，羽不供用，肉不足宰，懷璧其罪，贾害以采。","sortOrder":250},
  {"id":"s_work_nvlt_92_251","chapterId":"ch_work_nvlt_92","text":"◇服鳥","sortOrder":251},
  {"id":"s_work_nvlt_92_252","chapterId":"ch_work_nvlt_92","text":"盛弘之《荆州記》曰：巫縣有鳥，如雌雞，其名為鴞，楚人謂之服。","sortOrder":252},
  {"id":"s_work_nvlt_92_253","chapterId":"ch_work_nvlt_92","text":"【賦】漢贾誼服鳥賦曰：誼為長沙王傅三年，有服飛入誼舍，止於坐隅，服似鴞，不祥鳥也，誼既以適居長沙，長沙卑濕，誼自傷悼，以為寿不得長，而為賦以自廣，其辭曰：单閼之歲，孟夏庚子，鵩集於舍，止於坐隅，貌甚閒暇，異物來萃，私怪其故，發書占之，讖言其度，曰：野鳥入室，主人將去，請問於鵩，餘去何之，鵩乃叹息，口不能言，請對以臆，曰：萬物变化，固無休息，斡流而遷，或推而還，沕穆無窮，胡可勝言，斯遊遂成，卒被五［原訛正，據冯校本改。］刑，傅說胥靡，乃相武丁，夫禍之與福，何以糾纏，命不可說，孰知其極，雲蒸雨降，糾错相紛，大鈞播物，坱圠無垠，且夫天地為爐，造化為工，陰陽為炭，萬物為銅，合散消息，安有常則。","sortOrder":253},
  {"id":"s_work_nvlt_92_254","chapterId":"ch_work_nvlt_92","text":"漢孔臧鴞賦曰：季夏庚子，思遁靜居，爰有飛鴞，集我屋隅，異物之來，吉凶之符，觀之歡然，覽考經書，在德為祥，弃常為妖，尋氣而應，天道不逾，昔在贾生，有識之士，忌茲服鳥，卒用丧己，咨我令考，信道執真，变怪生家，謂之天神，禍福無門，唯人所求，聽天任命，慎厥所脩，栖遲養志，老氏之畴，時去不索，時來不逆，庶幾中庸，仁義之宅，何思何慮，自令勒剧。","sortOrder":254},
  {"id":"s_work_nvlt_92_255","chapterId":"ch_work_nvlt_92","text":"《藝文類聚》　唐·欧陽詢","sortOrder":255},
  {"id":"s_work_nvlt_93_1","chapterId":"ch_work_nvlt_93","text":"卷九十三獸部上","sortOrder":1},
  {"id":"s_work_nvlt_93_2","chapterId":"ch_work_nvlt_93","text":"○馬騊駼","sortOrder":2},
  {"id":"s_work_nvlt_93_4","chapterId":"ch_work_nvlt_93","text":"《爾雅》曰：馬膝上皆白，惟舁馵，［馵後左膝白者。］四骹皆白驓，［繒音。］四蹢皆白首，［俗呼為踏雪馬。］前足皆白騱，音奚，後足白翑，［音劬。］前左足白啟，［啟，服也。］左白騎，後右足白驤，左馵，［易震為馵足。］骝馬白腹騵，［骝青色，黑毛也。］驪馬白跨驈，［述音。］白州驠，［燕音。］尾本白騴，［晏音。］尾白狼，［從尾勺毛白也。］白達素縣，［素白茎。］面顙皆白惟駹，回毛在膺宜乘，［伯樂相馬法，旋毛在腹下如乳者，千里。］在肘後减陽，［或作腹。］在幹茀方，［幹，胁也。］在背阕廣，［音决光，皆旋毛所在。］逆毛居馻，［音兖，馬毛逆刺者。］牡曰骘，牝曰騇，［黃骝馬。］馬黃脊騝，［乾音。］驪馬黃脊騽，［習音。］青驪類阝驒，［陀音，今連錢驄。］蒼白雜色錐，黃白雜毛駓，［詩有騅有駓，今桃花馬。］彤白雜毛騢，［騢赪白馬。］白馬黑唇駩，［駩一泉，○句有訛。］黑喙騧，［淺黃色者。］一目白〈日間〉，兩目白魚。","sortOrder":4},
  {"id":"s_work_nvlt_93_5","chapterId":"ch_work_nvlt_93","text":"又曰：馬八尺曰駥。","sortOrder":5},
  {"id":"s_work_nvlt_93_6","chapterId":"ch_work_nvlt_93","text":"又曰：絕有力曰戎。","sortOrder":6},
  {"id":"s_work_nvlt_93_7","chapterId":"ch_work_nvlt_93","text":"《說文》曰：〈馬展〉，［張扇。］馬臥土中也。","sortOrder":7},
  {"id":"s_work_nvlt_93_8","chapterId":"ch_work_nvlt_93","text":"《山海經》曰：犬戎之國，有文馬，縞身朱{髟葛}，目若黃金，名曰吉彊，乘之寿千歲。","sortOrder":8},
  {"id":"s_work_nvlt_93_9","chapterId":"ch_work_nvlt_93","text":"又曰：夸父山北有林，名曰桃林，廣圓三百里，其中多馬，［桃林，弘農湖城縣也。］","sortOrder":9},
  {"id":"s_work_nvlt_93_10","chapterId":"ch_work_nvlt_93","text":"又曰：大樂之野，夏後啟於此舞九代馬，白民之國，白身被發，有乘黃，其状如狐，背上有角，乘之寿二千歲，［九代，馬名，舞盤作之，乘黃即飛黃也，《淮南子》曰：黃帝時，飛黃服皂。］","sortOrder":10},
  {"id":"s_work_nvlt_93_11","chapterId":"ch_work_nvlt_93","text":"又曰：天帝之山，有草焉，状如葵，臭如蘼芜，名曰杜蘅，可以走馬，［帶香，令便馬，或曰：馬得之健，能走。］","sortOrder":11},
  {"id":"s_work_nvlt_93_12","chapterId":"ch_work_nvlt_93","text":"《禮記》曰：孟春之月，天子乘蒼龍，［龍者色青。］","sortOrder":12},
  {"id":"s_work_nvlt_93_13","chapterId":"ch_work_nvlt_93","text":"《周官》曰：凡馬八尺以上為龍，七尺以上為騋，六尺為馬，天子十二閒，六种，邦國六閒，四种，家四閒，二种。","sortOrder":13},
  {"id":"s_work_nvlt_93_14","chapterId":"ch_work_nvlt_93","text":"《禮斗威儀》曰：君乘火而王，南海输駮馬。","sortOrder":14},
  {"id":"s_work_nvlt_93_15","chapterId":"ch_work_nvlt_93","text":"《易說卦》曰：乾為馬，為老馬駮馬。","sortOrder":15},
  {"id":"s_work_nvlt_93_16","chapterId":"ch_work_nvlt_93","text":"《毛詩》曰：駉，頌僖公也，僖公能遵伯禽之法，務農重穀，牧於坰野，而史克作是頌，駉駉牧馬，在坰之野，薄言駉者，有驈有皇，有驪有黃，以車彭彭。","sortOrder":16},
  {"id":"s_work_nvlt_93_17","chapterId":"ch_work_nvlt_93","text":"《左傳》曰：宋人以文馬百驷，贖華元於鄭。","sortOrder":17},
  {"id":"s_work_nvlt_93_18","chapterId":"ch_work_nvlt_93","text":"又曰：魯莊公新作延廄，凡馬日中而出，日中而入，［中，分也，春分出之，秋分內之。］","sortOrder":18},
  {"id":"s_work_nvlt_93_19","chapterId":"ch_work_nvlt_93","text":"又曰：晉侯伐齊，齊師夜遁，邢伯告中行伯曰：有班馬之聲，齊師其遁。","sortOrder":19},
  {"id":"s_work_nvlt_93_20","chapterId":"ch_work_nvlt_93","text":"又，唐成公如楚，有兩匹騄骦。","sortOrder":20},
  {"id":"s_work_nvlt_93_21","chapterId":"ch_work_nvlt_93","text":"又曰：冀之北土，馬之所生。","sortOrder":21},
  {"id":"s_work_nvlt_93_22","chapterId":"ch_work_nvlt_93","text":"春秋《穀梁傳》曰：晉獻公將伐虢，荀息請以屈產之乘，假道於虞，以伐虢，後滅虞，荀息牵馬曰：齒加長矣。","sortOrder":22},
  {"id":"s_work_nvlt_93_23","chapterId":"ch_work_nvlt_93","text":"《論語》曰：齊景公有馬千驷，死之日，民無德而稱焉。","sortOrder":23},
  {"id":"s_work_nvlt_93_24","chapterId":"ch_work_nvlt_93","text":"又曰：骥不稱其力，稱其德也。","sortOrder":24},
  {"id":"s_work_nvlt_93_25","chapterId":"ch_work_nvlt_93","text":"《韓詩外傳》曰：昔者田子方出，見老馬於野，喟然有志，問於御者曰：此何馬也，御者曰：故公家畜也，罢而不為用，故出放之，田子方曰：少盡其力，而老弃其身，仁者之不為用也，束帛贖之，窮士聞之，知所歸心焉。","sortOrder":25},
  {"id":"s_work_nvlt_93_26","chapterId":"ch_work_nvlt_93","text":"又曰：顏回望吳門馬，見一疋練，孔子曰：馬也，然則馬之光景，一疋長耳，故後人號馬為一疋。","sortOrder":26},
  {"id":"s_work_nvlt_93_27","chapterId":"ch_work_nvlt_93","text":"《孝經援神契》曰：德至山陵，則泽出神馬，《地鏡圖》曰：銅器之精，見為馬。","sortOrder":27},
  {"id":"s_work_nvlt_93_28","chapterId":"ch_work_nvlt_93","text":"太公《六韜》曰：商王拘周伯昌於羑里，太公與散宜生，以金十镒，求天下珍物，以免君之罪，於是得犬戎氏文馬，毫毛朱{髟葛}，目如黃金，名雞斯之乘，以獻商王。","sortOrder":28},
  {"id":"s_work_nvlt_93_29","chapterId":"ch_work_nvlt_93","text":"《管子》曰：桓公乘馬，虎望見而伏，公問管仲，管仲曰：意者君乘駮馬，公曰：然，仲曰：駮馬食虎豹，故伏焉。","sortOrder":29},
  {"id":"s_work_nvlt_93_30","chapterId":"ch_work_nvlt_93","text":"《列子》曰：秦穆公謂伯樂曰：子之年長矣，子姓有可使求馬乎，伯樂對曰：良馬可以形容筋骨相也，天下之馬者，若滅若没，若亡若失，臣之子皆下才也，臣有所與九方皋，其於馬，非臣之比也，穆公見之，使行求馬，三月而反報曰：已得之，在沙丘，穆公曰：何馬，對曰：牝而黃，使人往取之，牡而驪，公不悅，召伯樂曰：败矣，子之所使求馬者，色物牝牡弗能知。又何馬之能知也，伯樂曰：若皋之所觀，天機也，得其精而忘其粗，在其內而忘其外焉，至，果天下之良馬也。","sortOrder":30},
  {"id":"s_work_nvlt_93_31","chapterId":"ch_work_nvlt_93","text":"《晏子》曰：景公使人養所愛馬，馬病死，公怒，令人殺養馬者，晏子請數之曰：爾有三罪，使汝養馬，殺之，一當死也。又殺公所最善馬，二當死也，使公以一馬之故而殺人，百姓必怨叛，諸侯輕伐吾國，三當死也，公喟然赦之。","sortOrder":31},
  {"id":"s_work_nvlt_93_32","chapterId":"ch_work_nvlt_93","text":"《老子》曰：天下有道，却走馬以粪，天下無道，戎馬生於郊。","sortOrder":32},
  {"id":"s_work_nvlt_93_33","chapterId":"ch_work_nvlt_93","text":"《莊子》曰：馬，蹄可以踐霜雪，毛可以御風寒，龁草飲水，翘尾而隆，［○《太平御覽》八百九十六作陆。］此馬之真性也，雖有儀台路寢，無用之，及至，伯樂曰：我善治馬，燒之剔之，刻之骆之，連之以羁绊，編之以皂栈，馬之死者十二三矣。","sortOrder":33},
  {"id":"s_work_nvlt_93_34","chapterId":"ch_work_nvlt_93","text":"《孫卿子》曰：騏骥一日千里，駑馬十駕，則亦不及之矣。","sortOrder":34},
  {"id":"s_work_nvlt_93_35","chapterId":"ch_work_nvlt_93","text":"《韓子》曰：管仲隰朋，從桓公而伐孤竹，春往而冬返，迷惑失道，管仲曰：老馬之智可用也，乃放老馬而隨之，遂得道焉。","sortOrder":35},
  {"id":"s_work_nvlt_93_36","chapterId":"ch_work_nvlt_93","text":"又曰：兒說，宋人，善辯者也，持白馬之非馬也，服齊稷下之辯者，乘白馬而過關，則顧白馬之賦，故藉空辭則能勝於一國，實按形，不能謗於一人。","sortOrder":36},
  {"id":"s_work_nvlt_93_37","chapterId":"ch_work_nvlt_93","text":"又曰：如耳說衛嗣君，君悅之，左右曰：公何為不相也，公曰：夫馬似鹿者，而有千金，有百金之馬，而無一金之鹿者，何也，馬為人用，而鹿不為人用，今如子雖辯智，亦不為寡人用，吾是以不相也。","sortOrder":37},
  {"id":"s_work_nvlt_93_38","chapterId":"ch_work_nvlt_93","text":"又曰：伯樂教其憎者，相千里馬，教其愛者，相駑馬，以千里馬世一有，其利少，駑馬多，其利多也。","sortOrder":38},
  {"id":"s_work_nvlt_93_39","chapterId":"ch_work_nvlt_93","text":"《呂氏春秋》曰：秦穆公車败，失左驂，自往求焉，見野人殺，將食之，穆公笑曰：食駿馬肉而不飲酒，餘恐其傷性也，遍飲之而去。","sortOrder":39},
  {"id":"s_work_nvlt_93_40","chapterId":"ch_work_nvlt_93","text":"《戰國策》曰：汗明見春申君曰：夫骥之齒至矣，服鹽車而上太行，瀌汗洒地，白汗交流，中坂遷延負轅不能上，伯樂遭之，下車攀而哭之，解綍衣之募之，骥於是俯而喷，仰而鳴，聲造於天，仰［《太平御覽》八百九十六作欣。］見伯樂之知己也。","sortOrder":40},
  {"id":"s_work_nvlt_93_41","chapterId":"ch_work_nvlt_93","text":"《穆天子傳》曰：天子之八駿，赤骥盜驪白義渠黃華骝绿耳。","sortOrder":41},
  {"id":"s_work_nvlt_93_42","chapterId":"ch_work_nvlt_93","text":"《孔丛子》曰：公孫龍以白馬為非馬，或曰：此辯而毀大道，子高適趙，謂龍曰：原受業久矣，所不取先生者，以白馬為非馬耳，誠能去之，則高請為弟子，龍曰：若使去之，無教矣。","sortOrder":42},
  {"id":"s_work_nvlt_93_43","chapterId":"ch_work_nvlt_93","text":"《史記》曰：楚莊王有愛馬，衣以文繡，置華屋下，席以露床，啗以棗脯，馬死，欲以大夫禮葬之，樂人優孟入殿門，大哭曰：請以君禮葬之，以雕玉為棺，文梓為椁，豫章為題凑，發甲卒為壙，老弱負土，諸侯聞之，皆知大王賤人而貴馬也，王曰：為之奈何，曰：請為王言六畜之葬，以籠竈為之椁，銅钅歷為之棺，齊以薑桂，荐以木蘭，衣之以火光，葬人腹中，王乃以馬屬太官無令天下知聞也。","sortOrder":43},
  {"id":"s_work_nvlt_93_44","chapterId":"ch_work_nvlt_93","text":"又曰：項王駿馬名騅，常騎之，及被围於垓下，乃悲歌慷愾，為歌曰：力拔山兮氣蓋世，時不利兮騅不逝，及至乌江，謂亭長曰：吾騎此馬五歲，所當無敵，常一日千里，不忍殺，以賜公。","sortOrder":44},
  {"id":"s_work_nvlt_93_45","chapterId":"ch_work_nvlt_93","text":"又曰：冒頓围高祖於平城，所騎，西方盡白馬，東方盡青龍，北方盡乌驪，南方盡骍馬。","sortOrder":45},
  {"id":"s_work_nvlt_93_46","chapterId":"ch_work_nvlt_93","text":"又曰：大宛有善馬，在二師城，匿不肯與漢使，天子既好宛馬，使壮士持千金及馬，以請宛王善馬，宛國饒漢物，相與謀不肯與，漢使怒，妄言，推金馬而去，宛貴人怒，遮攻漢使，取财物，天子大怒，拜李廣利為貳師將軍，發屬國騎及郡國惡少年數萬人，以伐宛，期至貳師城，取善馬。","sortOrder":46},
  {"id":"s_work_nvlt_93_47","chapterId":"ch_work_nvlt_93","text":"又曰：初天子發書，［易書以卜也。］曰：神馬當從西北來，得乌孫馬好，名天馬，及得大宛汗血馬，益壮，更名乌孫馬曰西極馬，宛馬曰天馬。","sortOrder":47},
  {"id":"s_work_nvlt_93_48","chapterId":"ch_work_nvlt_93","text":"又曰：鄭當時以任俠自憙，為太子舍人，每五日洗沐，常置驿馬長安諸郊，請，賓客，夜以繼日。","sortOrder":48},
  {"id":"s_work_nvlt_93_49","chapterId":"ch_work_nvlt_93","text":"又曰：王遵遷東郡太守，河水盛溢，從浸瓠子金隄，老弱奔走，遵躬率吏民，沉白馬，親執珪璧，使巫策祝請，以身填金隄，因止宿隄上。","sortOrder":49},
  {"id":"s_work_nvlt_93_50","chapterId":"ch_work_nvlt_93","text":"又曰：贾捐之上書曰：孝文皇帝時，有獻千里馬者，詔曰：鸞旗在前，屬車在後，日行五十里，朕乘千里馬，獨先安之，於是還馬，而下詔曰：朕不受獻也，其令四方無來獻也。","sortOrder":50},
  {"id":"s_work_nvlt_93_51","chapterId":"ch_work_nvlt_93","text":"又曰：石建為太仆，奏事下，讀之驚恐，曰：書馬者，與尾而五，今乃四，譴死矣，石慶為太仆，御出，上問車中幾馬，慶舉策數馬畢，對曰：六馬。","sortOrder":51},
  {"id":"s_work_nvlt_93_52","chapterId":"ch_work_nvlt_93","text":"又曰：萬石君謹慎，見路馬必軾。","sortOrder":52},
  {"id":"s_work_nvlt_93_53","chapterId":"ch_work_nvlt_93","text":"又曰：馬高五尺九寸以上，不得出關。","sortOrder":53},
  {"id":"s_work_nvlt_93_54","chapterId":"ch_work_nvlt_93","text":"又，西域傳曰：大宛國多善馬，馬汗血，言其先天馬子也，［大宛國峤山上有馬，不可得，因取五色牝馬置其下，與集生駒，號天馬子。］","sortOrder":54},
  {"id":"s_work_nvlt_93_55","chapterId":"ch_work_nvlt_93","text":"東方朔傳曰：驃騎難諸博士，東方朔對曰：幹將莫耶，天下之利劍也，水斷鵠雁，陆斷馬牛，將以補屩，曾不如一錢之錐，騏骥騄耳，天下之良馬也，將以捕鼠於深堂，曾不如跛猫。","sortOrder":55},
  {"id":"s_work_nvlt_93_56","chapterId":"ch_work_nvlt_93","text":"《神異經》曰：西南大宛宛丘，有良馬，其大二丈，{髟葛}至膝，尾委於地，蹄如汗，［《太平御覽》八百九十七作升。］腕可握，日行千里，至日中而汗血，乘者當以綿絮纏頭腰小腹，以避風病，其國人不纏也。","sortOrder":56},
  {"id":"s_work_nvlt_93_57","chapterId":"ch_work_nvlt_93","text":"《說苑》曰：晉平公出田，見乳虎伏而不動，平公顧謂師曠曰：聞之霸王君出，猛獸伏而不敢起，今者寡人出，乳虎伏而不動，此猛獸乎，師曠對曰：鵲食犭冒，［《太平御覽》八百九十六作猬，下同。］猖食鵕鸃，鵕鸃食駮，駮食虎，夫駮之状，似駮馬，今者吾君當驂駮馬以出乎，平公曰：然。","sortOrder":57},
  {"id":"s_work_nvlt_93_58","chapterId":"ch_work_nvlt_93","text":"《淮南子》曰：免人於難者，其死也，葬之以帷為衾，馬有功猶不可忘。又况人乎。","sortOrder":58},
  {"id":"s_work_nvlt_93_59","chapterId":"ch_work_nvlt_93","text":"又曰：北塞上之人，其馬亡入胡中，人皆弔之，其父曰：此何詎知不為福，居數月，其馬將胡駿馬而歸，人皆贺之，其父曰：此何詎知不為禍，家富馬良，其子好騎，墮而折髀，人皆弔之，其父曰：此又詎知不為福，居一年，胡夷大出，丁壮者皆控絃而戰，［控，張也。］塞上之人，死者十九，［十人戰，九人死。］此子獨以跛故，子父相保，［幽通賦曰：北叟頗識其倚伏。］","sortOrder":59},
  {"id":"s_work_nvlt_93_60","chapterId":"ch_work_nvlt_93","text":"萬畢術曰：馬毛大尾，親友自絕，［取馬毛大尾，置朋友衣中，若夫婦衣中，夫婦自相憎矣。］","sortOrder":60},
  {"id":"s_work_nvlt_93_61","chapterId":"ch_work_nvlt_93","text":"《東觀漢記》曰：光武帝時，名都王國，有獻名馬者，帝以馬駕鼓車。","sortOrder":61},
  {"id":"s_work_nvlt_93_62","chapterId":"ch_work_nvlt_93","text":"又曰：光武初起，無馬騎牛，殺新野尉，乃得馬。","sortOrder":62},
  {"id":"s_work_nvlt_93_63","chapterId":"ch_work_nvlt_93","text":"又曰：聞武帝歌天馬，治［《太平御覽》八百九十四作霑。］赤汗，今親見其然，血從前髆上小孔中出。","sortOrder":63},
  {"id":"s_work_nvlt_93_64","chapterId":"ch_work_nvlt_93","text":"又曰：明帝欲征匈奴，窦固議曰：塞外草美，馬不須穀。","sortOrder":64},
  {"id":"s_work_nvlt_93_65","chapterId":"ch_work_nvlt_93","text":"又，馬防曰：宣帝時，五將出征，其奏言匈奴候騎，得漢馬矢，見其中有粟，即知漢兵出，乃去，以是言之，馬當與穀。","sortOrder":65},
  {"id":"s_work_nvlt_93_66","chapterId":"ch_work_nvlt_93","text":"又曰：明德後曰：吾前過濯龍門，見外家問起居，車如流水馬如龍，亦不譴怒，但絕其歲用，冀以嘿止讙耳。","sortOrder":66},
  {"id":"s_work_nvlt_93_67","chapterId":"ch_work_nvlt_93","text":"又曰：吳漢伐蜀，戰败墮水，緣馬尾得出。","sortOrder":67},
  {"id":"s_work_nvlt_93_68","chapterId":"ch_work_nvlt_93","text":"又曰：桓典為御史，是時宦者執政，典無所回避，常乘驄馬，京師畏憚，為之語曰：行行且止，避驄馬御史。","sortOrder":68},
  {"id":"s_work_nvlt_93_69","chapterId":"ch_work_nvlt_93","text":"又曰：上會諸將，問破賊所得物，唯李忠獨無所掠，上即以所乘大驪馬，及繡被衣物賜之。","sortOrder":69},
  {"id":"s_work_nvlt_93_70","chapterId":"ch_work_nvlt_93","text":"又曰：張湛為光祿勋，帝臨朝，或有惰容，湛辄諫其失，常乘白馬，上每見湛，辄言白馬生且复諫矣。","sortOrder":70},
  {"id":"s_work_nvlt_93_71","chapterId":"ch_work_nvlt_93","text":"又曰：馬援击交阯，謂官屬曰：從弟少遊，常哀吾多大志，曰：士生一世，但取衣食足，乘下泽車，御款段馬，為郡吏，守墳墓，乡里稱善人，斯可矣，求益盈餘，但自苦耳。","sortOrder":71},
  {"id":"s_work_nvlt_93_72","chapterId":"ch_work_nvlt_93","text":"又曰：馬援於交阯鑄銅馬，奏曰：臣聞行天者莫如龍，行地者莫如馬，臣援師事楊子阿，孝武帝時，善相馬者東門京，鑄作銅馬法，獻之，立馬於魯班門外，更名曰金馬門，臣既備數家骨法，以所得骆越銅，鑄以為馬，高二尺五寸，围四尺五寸，謹獻，詔置馬德陽殿下。","sortOrder":72},
  {"id":"s_work_nvlt_93_73","chapterId":"ch_work_nvlt_93","text":"又曰：張奐，字然明，為安定屬國都尉，羌離湳上奐馬二十疋，奐召主簿張祁入，於羌前，以酒酹地曰：使馬如羊，不以入廄，使金如粟，不得入懷，盡還不受。","sortOrder":73},
  {"id":"s_work_nvlt_93_74","chapterId":"ch_work_nvlt_93","text":"又曰：卓茂為丞相史，嘗出，道中有人認茂馬者，茂問失馬幾日，對曰：月餘矣，茂曰：然此馬畜已數年，遂解馬與之，曰：即非所失，幸至丞相府還我，乃步輓車去，後馬主自得馬，慚媿詣茂。","sortOrder":74},
  {"id":"s_work_nvlt_93_75","chapterId":"ch_work_nvlt_93","text":"又曰：廉范奔赴敬陵，時庐江郡掾嚴麟，俱會於路，麟乘小車，涂深馬死，不能自進，范愍之，命從騎下車與之，不告而去，麟事畢，即牵馬造謝而歸之。","sortOrder":75},
  {"id":"s_work_nvlt_93_76","chapterId":"ch_work_nvlt_93","text":"謝承《後漢書》曰：朱震，字伯厚，性刚烈，初為從事，奏濟陰太守单匡贓罪，併連匡兄中常侍車騎將軍超，三府喭曰：車如雞栖馬如狗，疾惡如風朱伯厚，袁宏漢記曰：第五倫為司空，有人與倫千里馬者，倫雖不取，每三公有所選舉，倫心不忘也，然亦終不用。","sortOrder":76},
  {"id":"s_work_nvlt_93_77","chapterId":"ch_work_nvlt_93","text":"《鹽鐵論》曰：騏骥負鹽車，垂頭於太行之坂，屠者持刀睨之。","sortOrder":77},
  {"id":"s_work_nvlt_93_78","chapterId":"ch_work_nvlt_93","text":"桓谭《新論》曰：薛翁者，長安善相馬者也，於邊郡求得駿馬，騎以入市，去來人不見也，後勞問之，因請觀馬，翁曰：諸卿無目，不足示也。","sortOrder":78},
  {"id":"s_work_nvlt_93_79","chapterId":"ch_work_nvlt_93","text":"蔡邕《月令論》曰：問者曰：七騶鹹駕，今曰六騶，何也，曰：本官職者，莫正於周官，天子六馬，种种一騶，故六騶也。","sortOrder":79},
  {"id":"s_work_nvlt_93_80","chapterId":"ch_work_nvlt_93","text":"《三辅决錄》曰：安陵有項仲山，每飲馬渭水，常投三錢。","sortOrder":80},
  {"id":"s_work_nvlt_93_81","chapterId":"ch_work_nvlt_93","text":"《鄹子》曰：董仲舒勤學，三年不窥園，乘馬不知牝牡。","sortOrder":81},
  {"id":"s_work_nvlt_93_82","chapterId":"ch_work_nvlt_93","text":"《論衡》曰：廣漢陽翁伟，能聽鳥獸之音，乘蹇馬之野，而田間有放馬者，相去數里，鳴聲相聞，翁伟謂其御曰：彼放馬目眇，其御曰：何以知之，曰：骂此轅中馬曰蹇馬，蹇馬亦骂之曰眇馬，御者不信，使往视之，馬目竟眇。","sortOrder":82},
  {"id":"s_work_nvlt_93_83","chapterId":"ch_work_nvlt_93","text":"又曰：儒書稱孔子與顏回，俱登魯太山，望吳昌門，謂曰：爾何見，對曰：見一匹練，前有生藍，孔子曰：噫，此白馬芦刍，使人视之，果然。","sortOrder":83},
  {"id":"s_work_nvlt_93_84","chapterId":"ch_work_nvlt_93","text":"又曰：［本條《太平御覽》四百四十八，八百二十作謝承後《漢書》：此前有脱條。］楊璇為零陵太守，時桂陽賊起，璇乃製馬車數十乘，以囊盛石灰於車上，及會戰，從風扬灰向賊陣，因鳴鼓击賊，大破之。","sortOrder":84},
  {"id":"s_work_nvlt_93_85","chapterId":"ch_work_nvlt_93","text":"《風俗通》曰：疲馬不能度繩，俗雲，馬羸不能度繩索，或雲，不能度种菜畦塍也，謹按，齊有渑水，裁廣三四步，言馬之疲，乃不能度此水耳。","sortOrder":85},
  {"id":"s_work_nvlt_93_86","chapterId":"ch_work_nvlt_93","text":"又曰：虾蟆一跳八尺，再丈六，從春至夏，裸袒相逐，無他所作，掉尾肅肅，按虾蟆無尾，當言夏馬，夏馬患蠅蚋，掉尾击之，故肅肅也。","sortOrder":86},
  {"id":"s_work_nvlt_93_87","chapterId":"ch_work_nvlt_93","text":"又曰：殺君馬者路旁兒也，言長吏養馬肥而希出，路邊小兒觀之，却驚致死，按長吏馬肥，觀者快之，乘者喜其言，驅馳不已，至於死。","sortOrder":87},
  {"id":"s_work_nvlt_93_88","chapterId":"ch_work_nvlt_93","text":"又曰：馬一疋，俗說相馬及君子，與人相疋，或曰：馬夜行目明，照前四丈，故曰一疋，或曰度馬縱橫，適得一疋，或說馬死，賣得一疋帛，或雲春秋左氏說，諸侯相赠，乘馬束帛，帛為疋，與馬之相疋耳。","sortOrder":88},
  {"id":"s_work_nvlt_93_89","chapterId":"ch_work_nvlt_93","text":"《符子》曰：齊景公好馬，命使善畫者圖之，訪似者，期年不得，今人君考古籍以求賢，亦不可得也。","sortOrder":89},
  {"id":"s_work_nvlt_93_90","chapterId":"ch_work_nvlt_93","text":"《魏志》曰：朱建平善相馬，文帝出，左右將馬過，平曰：此馬相今日死，及帝乘馬，馬惡帝衣香，齧帝膝，帝怒殺之。","sortOrder":90},
  {"id":"s_work_nvlt_93_91","chapterId":"ch_work_nvlt_93","text":"又曰：秽國出果下馬，漢時恒獻之，［高三尺，乘於果树下行。］","sortOrder":91},
  {"id":"s_work_nvlt_93_92","chapterId":"ch_work_nvlt_93","text":"英雄記曰：公孫瓒每聞邊警，辄厲色作氣，如赴讎，常乘白馬。又揀白馬數十疋，選騎射之士，號為白馬義從，以為左右翼，胡甚畏之，《曹瞞傳》曰：呂布乘馬名赤菟，人語曰：人中有呂布，馬中有赤菟。","sortOrder":92},
  {"id":"s_work_nvlt_93_93","chapterId":"ch_work_nvlt_93","text":"《吳錄》曰：孫堅讨董卓，失利，被創墮馬，臥草中，軍眾分散，馬還營鳴呼，軍人隨馬向草中，乃得堅，扶還營。","sortOrder":93},
  {"id":"s_work_nvlt_93_94","chapterId":"ch_work_nvlt_93","text":"《江表傳》曰：孫權征合肥，馬上津桥，桥見撤丈餘無板，權躍馬超之，得免。","sortOrder":94},
  {"id":"s_work_nvlt_93_95","chapterId":"ch_work_nvlt_93","text":"《世說》曰：劉備之初奔劉表，屯於樊城，表左右欲因會取備，備覺，如廁便出，所乘馬的顱，走墮襄陽城西檀溪水中，溺不得出，備急，謂的顱曰：今日厄，可不努力，的顱達備意，踴三丈得過。","sortOrder":95},
  {"id":"s_work_nvlt_93_96","chapterId":"ch_work_nvlt_93","text":"諸葛亮教曰：昔孫叔敖乘馬三年，不知牝牡，稱其賢也。","sortOrder":96},
  {"id":"s_work_nvlt_93_97","chapterId":"ch_work_nvlt_93","text":"《抱朴子》曰：李南乘赤馬行，逢人乘白馬，白馬先鳴，赤馬應之，南謂從者曰：白馬言汝當見一黃馬，左目盲，是吾子，可令駛行相及也，須臾，果逢盲黃馬，南馬果先鳴，盲馬應之。","sortOrder":97},
  {"id":"s_work_nvlt_93_98","chapterId":"ch_work_nvlt_93","text":"又曰：騰黃之馬，吉光之獸，皆寿三千歲也。","sortOrder":98},
  {"id":"s_work_nvlt_93_99","chapterId":"ch_work_nvlt_93","text":"幹寶《晉紀》曰：桓范出赴曹爽，宣王謂蒋濟曰：智囊往矣，濟曰：范則智矣，駑馬恋短豆，爽必不能用也。","sortOrder":99},
  {"id":"s_work_nvlt_93_100","chapterId":"ch_work_nvlt_93","text":"《搜神記》曰：趙固所乘馬忽死，固甚悲惜之，問郭璞，璞曰：可遣數十人持竹竿，東行三十里，當有丘陵林树，便搅打之，當有一物出，急抱將歸，於是如璞言，果得一物，似猴，入門見死馬，跳梁，走往死馬頭，噓吸其鼻，馬即起，亦不复見猴。","sortOrder":100},
  {"id":"s_work_nvlt_93_101","chapterId":"ch_work_nvlt_93","text":"《怪志》曰：有人與奴俱得心腹病，奴死，剖视之，得一白鱉，取諸藥內口中，不死，後有人乘白馬來，溺溅之，乃縮頭縮腳，试取馬溺灌之，便消為水，病者乃飲一升馬溺，乃差。","sortOrder":101},
  {"id":"s_work_nvlt_93_102","chapterId":"ch_work_nvlt_93","text":"又曰：謝尚所乘馬忽死，尚甚愛惜之，時有夏侯弘，自言見鬼神，與言語，尚初不信，弘曰：我能令馬活，信通神不，乃下床去，良久還曰：廟神愛君馬，今已請得還，須臾，眾人皆見馬從外來，至死馬邊便滅，死馬即活。","sortOrder":102},
  {"id":"s_work_nvlt_93_103","chapterId":"ch_work_nvlt_93","text":"《襄陽記》曰：中庐山有一地穴，漢時嘗有數百疋馬出，遂因名馬穴，吳時陆遜亦知此穴，馬出得數十疋。","sortOrder":103},
  {"id":"s_work_nvlt_93_104","chapterId":"ch_work_nvlt_93","text":"《長沙耆舊傳》曰：南陽太守張忠曰：吾年往志盡，譬如八百錢馬，死生同价。","sortOrder":104},
  {"id":"s_work_nvlt_93_105","chapterId":"ch_work_nvlt_93","text":"《相馬經》曰：馬眼欲紫艳光，口中欲赤色也。","sortOrder":105},
  {"id":"s_work_nvlt_93_106","chapterId":"ch_work_nvlt_93","text":"《庐江七賢傳》曰：陳眾辟州從事，楊州部有賊，击之多死，眾請以威信取之，因单車白馬往，賊束身歸降，遂生為立祠，號曰白馬從事。","sortOrder":106},
  {"id":"s_work_nvlt_93_107","chapterId":"ch_work_nvlt_93","text":"【詩】漢天馬歌曰：太一貺，天馬下，沾赤汗，沫流赭，志俶傥，精摧奇。籋［躡］浮雲，晻上馳，體容與，迣萬里，［迣音逝，超逾也。］今安匹，龍為友。","sortOrder":107},
  {"id":"s_work_nvlt_93_108","chapterId":"ch_work_nvlt_93","text":"又曰：天馬來，從西極，涉流沙，九夷服，天馬來，歷無草，径千里，循東道，天馬來，开遠門，竦予身，逝崑崙，天馬來，龍之媒，遊閶阖，觀玉台。","sortOrder":108},
  {"id":"s_work_nvlt_93_109","chapterId":"ch_work_nvlt_93","text":"古歌詩曰：平陵東，松柏桐，不知何人劫義公，義公在一高堂下，交錢百萬兩走馬。","sortOrder":109},
  {"id":"s_work_nvlt_93_110","chapterId":"ch_work_nvlt_93","text":"晉劉恢詩曰：東皋有一駿，名曰千里駒，絡首纏騣尾，養以甘露刍。","sortOrder":110},
  {"id":"s_work_nvlt_93_111","chapterId":"ch_work_nvlt_93","text":"梁簡文帝西齊行馬詩曰：晨風白金絡，桃花紫玉珂，影斜鞭照曜，尘起足蹉跎，任俠稱六辅，輕薄出三河，風吹鳳皇袖，日映織成靴，遠江舻舳少，遙山煙霧多，雲开馬瑙葉，水净琉璃波，路廣拂青柳，回塘繞碧莎，不效孫吳術，寧須趙李過。","sortOrder":111},
  {"id":"s_work_nvlt_93_112","chapterId":"ch_work_nvlt_93","text":"又《紫骝馬詩》曰：賤妾朝下機，正值良人歸，青絲懸玉蹬，朱汗染香衣，骤急珂弥响，跳多尘亂飛，雕胡幸可荐，故心君莫违。","sortOrder":112},
  {"id":"s_work_nvlt_93_113","chapterId":"ch_work_nvlt_93","text":"又《系馬詩》曰：青驪沉赭汗，绿地懸花蹄，未垂青鞙尾，猶掛紫鄣泥，蹀足绊中憤，搖頭櫪上嘶，紫關如未息，直去取榆溪。","sortOrder":113},
  {"id":"s_work_nvlt_93_114","chapterId":"ch_work_nvlt_93","text":"又《登山馬詩》曰：登山馬，間树識金裝，草合宜纟廌短，影轉見鞭長，何殊八公岫，蹔上淮南王。","sortOrder":114},
  {"id":"s_work_nvlt_93_115","chapterId":"ch_work_nvlt_93","text":"又《和人愛妾換馬詩》曰：功名幸多种，何事苦生離，誰言似白玉，定是愧青驪，必取匣中钏，回作飾金羁，真成恨不已，原得路傍兒。","sortOrder":115},
  {"id":"s_work_nvlt_93_116","chapterId":"ch_work_nvlt_93","text":"梁元帝賦登山馬詩曰：登山馬迳小，迳小［原倒訛作遙遙小小，據冯校本改。］馬才通，汗赭疑霑勒，衣香不逐風，何殊隴頭望，遙識祁連東。","sortOrder":116},
  {"id":"s_work_nvlt_93_117","chapterId":"ch_work_nvlt_93","text":"又後園看騎馬詩曰：良馬出蘭池，連翩驅桂枝，鳴珂隨跼駃，輕尘逐影移，香來知骤近，汗斂覺風吹，遙望黃金絡，懸識幽併兒。","sortOrder":117},
  {"id":"s_work_nvlt_93_118","chapterId":"ch_work_nvlt_93","text":"又《紫骝馬詩》曰：長安美少年，金絡飾連錢，宛轉青絲鞚，照曜珊瑚鞭，依槐复依柳，躞蹀复隨前，方逐幽併去，西北共連翩。","sortOrder":118},
  {"id":"s_work_nvlt_93_119","chapterId":"ch_work_nvlt_93","text":"梁劉孝威《和王竟陵愛妾換馬詩》曰：驄馬出樓蘭，一步九盤桓，小史贖金絡，良工送玉鞍，龍驂來甚易，乌孫去實難，驎膠妾猶有，請為急絃彈。","sortOrder":119},
  {"id":"s_work_nvlt_93_120","chapterId":"ch_work_nvlt_93","text":"梁庾肩吾《以妾換馬詩》曰：渥水出騰駒，湘川實應圖，來從西北道，去逐東南隅，琴聲悲玉匣，山路泣蘼芜，似鹿將含笑，千金會不俱。","sortOrder":120},
  {"id":"s_work_nvlt_93_121","chapterId":"ch_work_nvlt_93","text":"陳劉删《賦得馬詩》曰：獨飲臨寒窟，離群思北風，陳王欲觀舞，御史自隨驄，邊聲陨客淚，果下益桃紅，恒持沛艾影，解向平陵東。","sortOrder":121},
  {"id":"s_work_nvlt_93_122","chapterId":"ch_work_nvlt_93","text":"陳沈蜅賦得邊馬有歸心詩曰：窮秋邊馬肥，向塞甚思歸，連鑣渡蒲海，束舌下金微，已却魚麗陣，將摧鶴翼围，弥憶長楸道，金鞭背落暉。","sortOrder":122},
  {"id":"s_work_nvlt_93_123","chapterId":"ch_work_nvlt_93","text":"陳祖孫登賦得紫骝馬詩曰：候騎柏［冯校本作柏，疑當作迫。］樓蘭，長城迥路難，嘶從風處斷，骨住水中寒，飛尘暗金勒，落淚洒銀鞍，抽鞭上關路，誰念客衣单。","sortOrder":123},
  {"id":"s_work_nvlt_93_124","chapterId":"ch_work_nvlt_93","text":"陳王由禮賦得驄馬詩曰：善馬金羁飾，躡影复凌空，影入長城水，聲隨胡地風，倥斂青門外，珂喧紫陌中，行行若不倦，唯當御史驄。","sortOrder":124},
  {"id":"s_work_nvlt_93_125","chapterId":"ch_work_nvlt_93","text":"【賦】魏應德璉愍骥賦曰：愍良骥之不遇兮，何屯否之弘多，抱天飛之神號兮，悲當世之莫知，赴玄穀之漸涂兮，陟高岗之峻崖，懼仆夫之嚴策兮，載悚栗而奔馳，懷殊姿而困逼兮，原遠跡而自舒，思奋行而驤首兮，叩韁緤之紛拏，牵繁辔而增製兮，心慉結而槃紆，涉通逵而方舉兮，迫舆仆之我拘，抱精誠而不畅兮，鬱神足而不摅，思薛翁於西土兮，望伯氏於東隅，原浮軒於千里兮，曜華軛乎天衢，瞻前軌而促節兮，顧後乘而踟蹰，展心力於知己兮，甘邁遠而忘劬，哀二哲之殊世兮，時不遘乎良造，製衔辔於常御兮，安獲騁於遐道。","sortOrder":125},
  {"id":"s_work_nvlt_93_126","chapterId":"ch_work_nvlt_93","text":"晉曹毗馬射賦曰：奔電無以追其蹤，逸羽不能企其足，状若騰虬而登紫霄，目似晨景之駭扶木，體與機會，動躡驚風，於是抗孫陽之辔，弯繁弱之弓，輕足鬱其雲合，妙手於焉爭雄。","sortOrder":126},
  {"id":"s_work_nvlt_93_127","chapterId":"ch_work_nvlt_93","text":"晉傅玄乘舆馬賦曰：目若曜星，符采橫發，高顛懸日，双璧象月，頭似削成，髦如鬢發，延首高驤，擢足軒跱，氣蓋青雲，势凌萬里，九方不能测其天機，秦公不能究其妙理。","sortOrder":127},
  {"id":"s_work_nvlt_93_128","chapterId":"ch_work_nvlt_93","text":"又馳馬射賦曰：何逸群之奇駿，生濛汜之遐濱，附南方以定位，表天驷於三辰，儀乾行之刚健，凭坤厚以讬身，豈骥德之足慕，晞萬里之清尘。","sortOrder":128},
  {"id":"s_work_nvlt_93_129","chapterId":"ch_work_nvlt_93","text":"宋顏延之赭白馬賦曰：昔帝軒陟位，飛黃服皂，後唐膺箓，赤文侯日，漢道亨而天骥呈才，魏德懋而泽馬效质，伊逸倫之妙足，目前代而間出，併榮光於瑞典，登郊歌乎司律，所以崇衛威神，扶護警跸，双瞳夹鏡，兩權协月，異體峰生，殊相逸發，鑒穆武，憲文光，振民隱，修國章。","sortOrder":129},
  {"id":"s_work_nvlt_93_130","chapterId":"ch_work_nvlt_93","text":"宋謝莊乘舆舞馬賦應詔曰：月晷呈祥，乾維效氣，賦景阿房，承靈天驷，既秣芑以均性。又佩蘅以崇躅，卷雄神於綺文，蓄奔容於帷燭，觀其双璧應范，三封中圖，玄骨滿，燕室虛，陽理競，潛策紆，汗飛赭，沫流朱，至於肆夏已升，采齊既荐，始徘徊而龍俯，終沃若而鸞盻，迎調露於飛鍾，赴承雲於驚箭，寫秦坰之弭尘，状吳門之曳練，夫蹠實之態未卷，凌遠之氣方摅，歷岱野而過碣石，跨沧流而軼姑餘，朝送日於西阪，夕歸風於北都，尋琼宮於倏瞬，望銀台於須臾。","sortOrder":130},
  {"id":"s_work_nvlt_93_131","chapterId":"ch_work_nvlt_93","text":"【頌】魯國黃伯仁為龍馬頌曰：夫龍馬之所出，丁太蒙之荒域，禀神祇之純化。乃大宛而再育，資玄螭之表像，似靈虬之註則，逾騕褭之體势，逸飛菟之高蹤。兼骥騄之美质，豈驊骝之足双，耳如剡筩，目象明星，双璧似月，蘭筋參情。","sortOrder":131},
  {"id":"s_work_nvlt_93_132","chapterId":"ch_work_nvlt_93","text":"【贊】晉郭璞馬贊曰：馬出明精，祖自天驷，十閒六种，各有名類，三才五御，駑駿異辔。","sortOrder":132},
  {"id":"s_work_nvlt_93_133","chapterId":"ch_work_nvlt_93","text":"周庾信秦穆公馬贊曰：駿馬遇盜，秦君不瞋，先傾美酒，翻畏傷人，鄰兵向國，窮寇侵秦，於時大盜，還作功臣。","sortOrder":133},
  {"id":"s_work_nvlt_93_134","chapterId":"ch_work_nvlt_93","text":"【状】宋顏延之天馬状曰：降靈骥子，九方是選，白〈馬羲〉朱文，绿蛇紫燕，水軼驚凫，陆越飛箭，遇山為風，值雲成電。","sortOrder":134},
  {"id":"s_work_nvlt_93_135","chapterId":"ch_work_nvlt_93","text":"【表】魏陳王曹植獻文帝馬表曰：臣於先武皇帝世，得大宛紫骍馬一疋，形法應圖，善持頭尾，教令習拜，今辄已能。又能行與鼓節相應，謹以奉獻。","sortOrder":135},
  {"id":"s_work_nvlt_93_136","chapterId":"ch_work_nvlt_93","text":"【啟】梁元帝謝晉安王賜馬啟曰：繹武媿仲都，遂蒙大驪之錫，儒謝春卿，空頒名馬之赉，故以取方驎友，自疋龍媒，不待景公，婉如齊畫，無勞馬援，翻等漢銅，豈有滅没黑龍，連翩白馬，錢文見重，津名取貴，相彼騏骥，猶深恋主，矧伊伏櫪，弥結懷恩。","sortOrder":136},
  {"id":"s_work_nvlt_93_137","chapterId":"ch_work_nvlt_93","text":"梁邵陵王謝令赉馬啟曰：連翩絕景，沃若追風，超渥水之形，逾大宛之状，荷傳西蕃，將達宮阃，無任城之氣勇，降東平之嘉錫，何以扬名沙漠，仰稱隆慈，恋德銘心，矚恩雨淚。","sortOrder":137},
  {"id":"s_work_nvlt_93_138","chapterId":"ch_work_nvlt_93","text":"梁劉孝威為皇太子謝敕赉功德馬啟曰：伏惟忘我徇物，屈己濟民，該天地而大舍。總日月而為施，既脱屣於金輪。又解驂於绀馬，出餘吾之水，服騊駼之廄，名高夏後之龍，价倍田方之贖，謹當秣以柏葉，飴以丹棗，加之玉鞍，飾之金絡。","sortOrder":138},
  {"id":"s_work_nvlt_93_139","chapterId":"ch_work_nvlt_93","text":"梁劉孝儀謝豫章王賜馬啟曰：出自北冀，來從東道，舞越兩驂，驅同八駿，循坂且厲，無复良樂之鳴，長楸可走，不假幽併之策。","sortOrder":139},
  {"id":"s_work_nvlt_93_140","chapterId":"ch_work_nvlt_93","text":"周庾信謝滕王赉馬啟曰：柳穀未开，翻逢紫燕，臨源猶遠，忽見桃花，流電爭光，浮雲連影，張敞畫眉之暇，直走章台，王濟飲酒之懽，長驅金埒。","sortOrder":140},
  {"id":"s_work_nvlt_93_141","chapterId":"ch_work_nvlt_93","text":"周王褎謝赉馬啟曰：邊城無草，來自東南，塞外饒沙，經從西北，漢時樂府，偏愛權奇，晉世桑門，特怜神駿，黃金作勒，足度西河，白玉為鐙，方傳南國，傥逢漢帝，仍駕鼓車，若值魏王，應驚香氣。","sortOrder":141},
  {"id":"s_work_nvlt_93_142","chapterId":"ch_work_nvlt_93","text":"【書】魏文帝與孫權書曰：前使於禁郭及土，［《太平御覽》八百九十四作去。］所遺吾纖驪馬，本欲使禁自致之，念將軍傥欲速得，今故以付徐奉往，此二馬，朕之常所自乘，甚調良善走，數萬疋之極選者，乘之真可樂也，中國雖饒馬，其知名絕足，亦時有之耳。","sortOrder":142},
  {"id":"s_work_nvlt_93_143","chapterId":"ch_work_nvlt_93","text":"梁元帝答齊國饟馬書曰：名重桂條，形圖柳穀，襄陽地穴，近求未易，滇池水里，遠訪猶難，价疋龍媒，聲齊骥子，河精曜采，似伏波之鑄銅，震象飛文，笑東瀛之刻玉，加以控斯銀勒，利此金衔，鞍揭鏤衢，光含兩月，韁萦紫縷，色麗双絲，方嗤晉後，恒乘鄭國之驷，更鄙曹君，經餉蜀王之馬。","sortOrder":143},
  {"id":"s_work_nvlt_93_144","chapterId":"ch_work_nvlt_93","text":"又《書》曰：於戲，馬之為用，遠矣大矣，斯所以乾為脊馬，震為馵足，有是哉，有是哉，何則，半漢而馳，可以及日，踌躇而蹀，可以追風，赤菜之騰聲，的顱之濟主，陳王有炤羁之說，班生有韁绊之談，抑聞斯美，遠勞此費，懷哉懷哉，老生不雲乎，雖有拱璧，以先驷馬，良用此道，中心藏之，何日忘之。","sortOrder":144},
  {"id":"s_work_nvlt_93_145","chapterId":"ch_work_nvlt_93","text":"◇騊駼","sortOrder":145},
  {"id":"s_work_nvlt_93_146","chapterId":"ch_work_nvlt_93","text":"《爾雅》曰：騊駼，北野之良馬。","sortOrder":146},
  {"id":"s_work_nvlt_93_147","chapterId":"ch_work_nvlt_93","text":"《山海經》曰：北海內有獸焉，状如馬，名曰騊駼。","sortOrder":147},
  {"id":"s_work_nvlt_93_148","chapterId":"ch_work_nvlt_93","text":"《史記》曰：匈奴奇畜則騊駼。","sortOrder":148},
  {"id":"s_work_nvlt_93_149","chapterId":"ch_work_nvlt_93","text":"【贊】晉郭璞騊駼贊曰：騊駼野駿，產自北域，交頸相摩，分背翘陆，雖有孫陽，終不在服。","sortOrder":149},
  {"id":"s_work_nvlt_93_150","chapterId":"ch_work_nvlt_93","text":"《藝文類聚》　唐·欧陽詢","sortOrder":150},
  {"id":"s_work_nvlt_94_1","chapterId":"ch_work_nvlt_94","text":"卷九十四獸部中","sortOrder":1},
  {"id":"s_work_nvlt_94_2","chapterId":"ch_work_nvlt_94","text":"○牛驢骆駞［原訛〈馬犬〉，據冯校本書目錄改。］羊狗豕","sortOrder":2},
  {"id":"s_work_nvlt_94_4","chapterId":"ch_work_nvlt_94","text":"《爾雅》曰：犘牛，［千斤，出巴中，音麻。］犦，［封牛，蒲角反。］犤，［音卑，痺小者。］犩牛，［牛大者，出蜀中。］犝牛，［無角牛。］墨眦牰，［袖音。］黑耳犚，［尉音。］子犢，體長〈牜巿〉，［霈音。］絕有力欣犌，［加音。］《毛詩》曰：爾牛來思，其耳濕濕，［齝而動其耳。］","sortOrder":4},
  {"id":"s_work_nvlt_94_5","chapterId":"ch_work_nvlt_94","text":"《左傳》曰：介葛盧來朝，禮之，加宴好，葛盧聞牛鳴，曰：是生三犧，皆用之矣，其音雲，問之而信。","sortOrder":5},
  {"id":"s_work_nvlt_94_6","chapterId":"ch_work_nvlt_94","text":"又曰：秦師伐鄭，商人絃高將市於周，遇之，以乘韦先牛十二犒師，曰：寡君聞吾子將師涉於弊邑，敢犒從者。","sortOrder":6},
  {"id":"s_work_nvlt_94_7","chapterId":"ch_work_nvlt_94","text":"又曰：鼷鼠食郊牛角，改卜牛，鼷鼠又食其角，乃免牛。","sortOrder":7},
  {"id":"s_work_nvlt_94_8","chapterId":"ch_work_nvlt_94","text":"又曰：楚子為陳夏氏亂故，伐陳，殺夏徵舒，因縣陳，申叔時使於齊，复命，不贺而退，王使讓之，對曰：抑人亦有言曰：牵牛以蹊人之田，而奪之牛，牵牛以蹊者，信有罪矣，而奪之牛，罰已重矣，諸侯之從，讨有罪，今縣陳，貪其富也，無乃不可乎，王曰：善。","sortOrder":8},
  {"id":"s_work_nvlt_94_9","chapterId":"ch_work_nvlt_94","text":"《玄中記》曰：萬歲树精為青牛。","sortOrder":9},
  {"id":"s_work_nvlt_94_10","chapterId":"ch_work_nvlt_94","text":"《漢書》：［《太平御覽》九百作玄中記。］桓帝出遊河上，忽有一青牛從河中出，走踢帝，人皆驚走，太尉公［御覽公上有何字。］時為殿中將軍，有勇力，走逆牛，牛見公，走還河，公以手挽牛左足，右手持斧，斫牛頭而殺之，此青牛者，萬年之木精也。","sortOrder":10},
  {"id":"s_work_nvlt_94_11","chapterId":"ch_work_nvlt_94","text":"《莊子》曰：庖丁為文惠君解牛，曰：臣之刀十九年，所解千牛，而刀刃若新，彼節者有間，而刀刃無厚，以無厚入有間，恢恢乎其於遊刃必有餘地，是以十九年，刀刃如新。","sortOrder":11},
  {"id":"s_work_nvlt_94_12","chapterId":"ch_work_nvlt_94","text":"又曰：或聘莊子，莊子應其使曰：子見夫犧牛乎，衣以文繡，食以刍菽，及其牵而入於太廟，雖欲為孤犢，其可得乎。","sortOrder":12},
  {"id":"s_work_nvlt_94_13","chapterId":"ch_work_nvlt_94","text":"《孟子》曰：齊宣王問曰：齊桓晉文之事，可得聞乎，《孟子》曰：仲尼之徒無道者，未之聞也，臣聞王坐堂上，有牵牛過者，王問之，對曰：將以亹鍾，王曰：吾不忍其觳觫而就死，以羊易之，是見牛，未見羊也，此乃仁術，足以王矣。","sortOrder":13},
  {"id":"s_work_nvlt_94_14","chapterId":"ch_work_nvlt_94","text":"《呂氏春秋》曰：百里奚未遇時，販牛於秦，鬻以五羊之皮，公孫枝得而獻諸缪公，缪公用之，謀無不當，舉必有功。","sortOrder":14},
  {"id":"s_work_nvlt_94_15","chapterId":"ch_work_nvlt_94","text":"又曰：昔葛天氏之樂，三人操牛尾，投足以歌八阕。","sortOrder":15},
  {"id":"s_work_nvlt_94_16","chapterId":"ch_work_nvlt_94","text":"《史記》曰：騎劫攻即墨，田单取牛千頭，衣以五彩，束矛其角，縛火其尾，穿城而出牛，壮士五千，衔枚隨其後，牛出火明，所觸皆死，壮士因击之，城上士大譟，燕師大败，騎劫死，乘勝追北，三戰三剋，遂收齊城。","sortOrder":16},
  {"id":"s_work_nvlt_94_17","chapterId":"ch_work_nvlt_94","text":"蜀王本紀曰：秦惠王欲伐蜀，乃刻五石牛，置金其後，蜀人見之，以為牛能大便金，牛下有養卒，以為此天牛也，能便金，蜀王以為然，即發卒千人，使五丁力士，拖牛成道，致三枚於成都，秦得道通，石牛力也，後遣丞相張儀等，隨石牛道伐蜀。","sortOrder":17},
  {"id":"s_work_nvlt_94_18","chapterId":"ch_work_nvlt_94","text":"《漢武內傳》曰：封君達，少好道，入鳥鼠山，百餘年還乡里，常乘青牛，故謂為青牛道士。","sortOrder":18},
  {"id":"s_work_nvlt_94_19","chapterId":"ch_work_nvlt_94","text":"桓谭《新論》曰：夫畜生賤也，然有尤善者，皆見記識，故馬稱驊骝骥騄，牛譽郭椒丁櫟。","sortOrder":19},
  {"id":"s_work_nvlt_94_20","chapterId":"ch_work_nvlt_94","text":"謝承《後漢書》曰：劉宽嘗行，有人失牛者，乃於路就宽車中認之，宽無所言，下駕步歸，有頃，認者得牛而送還，叩頭謝曰：慚負長者，宽曰：物有相類，事容脱誤，幸勞見歸，何為謝也。","sortOrder":20},
  {"id":"s_work_nvlt_94_21","chapterId":"ch_work_nvlt_94","text":"《風俗通》曰：秦昭王使李冰為蜀守，开成都兩江，溉田萬頃，江神歲取童女二人為婦，冰自以其女與神為婚，往至神祠，勸神酒，杯但淡水，［原作澹淡，據冯校本改。］冰厲聲责之，因忽不見，良久，有兩蒼牛斗於岸旁，有間，冰還，流汗，謂官屬曰：吾斗大極，不當相助，南向腰中正白者，我綬也，主簿乃刺殺北面者，江神遂死，蜀人慕其氣决，凡壮健者，因名冰兒。","sortOrder":21},
  {"id":"s_work_nvlt_94_22","chapterId":"ch_work_nvlt_94","text":"《列異傳》曰：秦文公伐梓树，梓树化為牛，文公遣騎击之，騎墮地被發，牛畏之，入水不出，没丰水中，秦乃立怒特祠。","sortOrder":22},
  {"id":"s_work_nvlt_94_23","chapterId":"ch_work_nvlt_94","text":"《魏略》曰：鉅鹿時苗，為寿春令，始之官，乘牸牛，歲餘，牛生一犢，及去，留其犢，謂主簿曰：令來時，本無此犢，是淮南所生也，吏曰：六畜不識父，自當隨其母，苗不聽。","sortOrder":23},
  {"id":"s_work_nvlt_94_24","chapterId":"ch_work_nvlt_94","text":"《蜀志》曰：蒋琬夜夢，有一牛頭在門前，流血滂沱，意甚惡之，問占夢趙直，直曰：夫見血者，事分明也，牛角及鼻，公字之象，君位當至公，大吉之徵也。","sortOrder":24},
  {"id":"s_work_nvlt_94_25","chapterId":"ch_work_nvlt_94","text":"諸葛亮集曰：木牛者，方腹曲頭，一腳四足，頭入領中，舌著於腹，載多而行少，宜可大用，不可小使，特行者數十，群行二十里也。","sortOrder":25},
  {"id":"s_work_nvlt_94_26","chapterId":"ch_work_nvlt_94","text":"張溫自理［《太平御覽》八百九十九作表。］曰：昔百里奚賢秦缪公，欲幹之，缪公好牛，奚因賃養牛，公出遊，登車以問百里，百里曰：臣之所長，非養牛者也，乃養民也，视牛察士，乃則賢人也，遂與同車而出。","sortOrder":26},
  {"id":"s_work_nvlt_94_27","chapterId":"ch_work_nvlt_94","text":"《博物志》曰：近世有居於海渚，年年八月，有浮槎來，甚大，往反不失於期，此人乃赍糧乘槎而去，忽忽不覺晝夜，奄至一處，有城郭，屋舍宛然，望室中，多見織婦，見一丈夫，牵牛渚次飲之，此人還，以問蜀人嚴君平，君平曰：某月有客星犯牛斗，即此人到天河也。","sortOrder":27},
  {"id":"s_work_nvlt_94_28","chapterId":"ch_work_nvlt_94","text":"曹嘉之《晉紀》曰：羊祜子暨，為青州刺史，牛於州產犢，及暨去職，以官室所生，遺之而去。","sortOrder":28},
  {"id":"s_work_nvlt_94_29","chapterId":"ch_work_nvlt_94","text":"《符子》曰：尧以天下讓巢父，巢父曰：君之牧天下，亦猶餘之牧孤犢，君牧天下，是各有其所牧矣，君焉用惴惴然，以所牧而與餘，餘無用天下為也，於是牵犢而去。","sortOrder":29},
  {"id":"s_work_nvlt_94_30","chapterId":"ch_work_nvlt_94","text":"袁山松宜都山川記曰：自峡口溯江百許里，至黃牛滩，南岸有重山，山顶有石壁，上有人負刀牵黃牛，人跡所絕，莫得究焉。","sortOrder":30},
  {"id":"s_work_nvlt_94_31","chapterId":"ch_work_nvlt_94","text":"竺法真登羅山疏曰：增城縣南有列渚洲，洲南又有牛潭，北岸有石，周員三丈，漁人見金鎖牛，常出水，盤鎖此石上，縣民張安，釣於石上，躡得金鎖數十尋，俄有物從水中引之，力不能禁，以刃斷之，唯得數尺，遂致大富。","sortOrder":31},
  {"id":"s_work_nvlt_94_32","chapterId":"ch_work_nvlt_94","text":"《琴操》曰：甯戚飯牛車下，叩角而商歌曰：南山研，白石〈石阑〉，生不逢尧與舜禪，短布单衣裁至骭，長夜冥冥何時旦，齊桓公聞之，舉以為相。","sortOrder":32},
  {"id":"s_work_nvlt_94_33","chapterId":"ch_work_nvlt_94","text":"【賦】臧道顏駃牛賦曰：若乃豪宗戚胤，公侯王後，乘輕御肥，貂蝉耀首，翟翟華貂，鑠鑠雲母，良牸擢足於双島，名駮叠跡於左右，如貴遊踴躍於絕倫，觀者嗤妍其好丑，遂慕駿駃以相高，精彼奇選之希有，儀體际美．特資高足，名參飛兔，价齊骥騄。","sortOrder":33},
  {"id":"s_work_nvlt_94_34","chapterId":"ch_work_nvlt_94","text":"【贊】梁劉孝威辟厭青牵畫贊曰：泰山怒特，吳渚神牛，氣噓風喷，精回電流，詎牵和鞅，不入裴鞦，狡力難京，肆怒橫行，朗陵瑩角，介葛瞻聲，遁仙讬稱，妖寇冯名，名震菜區，威陵五都，蓄勇槽侧，息憤場堣，仇覽獻豆，滕婴進刍，雄兒揩式，悍士規模，曹興拂采，徐邈成圖。","sortOrder":34},
  {"id":"s_work_nvlt_94_35","chapterId":"ch_work_nvlt_94","text":"【表】魏陳王曹植上牛表曰：臣聞物以洪珍，細亦或貴，故不見僬僥之微，不知泱漭之泰，不見果下之乘，不別龍馬之大，高下相懸，所以致觀也，謹奉牛一頭，不足追遵大小之製，形少有殊，敢不獻上。","sortOrder":35},
  {"id":"s_work_nvlt_94_36","chapterId":"ch_work_nvlt_94","text":"【啟】梁元帝謝東宮赉蒸栗牛啟曰：色似秘府之書，毛類陳王之玉，骍角未奇，瑩蹄非貴。","sortOrder":36},
  {"id":"s_work_nvlt_94_37","chapterId":"ch_work_nvlt_94","text":"梁劉孝儀謝始興王賜車牛啟曰：下官安於躡屩，習以成性，乘堅驅駿，未所厝心，慈渥無涯，每垂奖飾，無复難載之朋，將申共弊之美，濯龍望水，未足儔光，長門聽雷，不能均响。","sortOrder":37},
  {"id":"s_work_nvlt_94_38","chapterId":"ch_work_nvlt_94","text":"又謝豫章王賜牛啟曰：觀其毛角相合，骨像應圖，曳流水而生光，骛高限其如接，遂使上阜輟駕，下泽是驅，冯軾脩途，既獲坐馳之致，馴豢廣庭，方念載忧之勖。","sortOrder":38},
  {"id":"s_work_nvlt_94_39","chapterId":"ch_work_nvlt_94","text":"【書】梁劉孝威謝南康王饟牛書曰：雖复蜀守神牛，秦公怒特，穆王白角，何氏瑩蹄，無以逾其劲力，邁其致遠，直宿九重，獲免疏步，路休三迳，且息徒行，從杞甘泉，方無假於丞相，騎至清廟。又永笑於博陽。","sortOrder":39},
  {"id":"s_work_nvlt_94_41","chapterId":"ch_work_nvlt_94","text":"楚辭，九懷曰：骥垂兩耳，中坂蹉跎，蹇驢服駕，無用日多。","sortOrder":41},
  {"id":"s_work_nvlt_94_42","chapterId":"ch_work_nvlt_94","text":"《吳志》曰：諸葛恪父瑾，長面似驢，孫權大會群臣，使人牵一驢入，長捡其面，題曰：諸葛子瑜，恪跪請筆，益兩字，恪續其下曰之驢，舉坐歡笑，乃以驢賜恪。","sortOrder":42},
  {"id":"s_work_nvlt_94_43","chapterId":"ch_work_nvlt_94","text":"《文士傳》曰：晉文帝大親阮籍，恒與談戲，任其所欲，不迫以職事，籍從容常言，平生曾遊東平，樂其土風，原得為東平太守，文帝大悅，即從其意，籍便騎驢，径到郡，至皆坏府舍諸壁鄣，使內外相望，然教令清當，十餘日，便乘驢去。","sortOrder":43},
  {"id":"s_work_nvlt_94_44","chapterId":"ch_work_nvlt_94","text":"《晉陽秋》曰：胡威少有志尚，厲操清白，父质，為荆州守，威自京都省之，家貧，無車馬僮仆，自驅驢单行，拜見父，停廄中十餘日，辭歸，每至客舍，自放驢，取樵爨食。","sortOrder":44},
  {"id":"s_work_nvlt_94_45","chapterId":"ch_work_nvlt_94","text":"《世說》曰：王仲宣好驢鳴，既葬，魏文帝臨其丧，顧語同遊曰：王好驢鳴，可各作一聲以送之，赴客皆作驢鳴。","sortOrder":45},
  {"id":"s_work_nvlt_94_46","chapterId":"ch_work_nvlt_94","text":"陳武別傳曰：武本休屠胡人，常騎驢牧羊，諸家牧竖十數人，或有和歌者，武遂學太山梁甫吟之屬。","sortOrder":46},
  {"id":"s_work_nvlt_94_47","chapterId":"ch_work_nvlt_94","text":"【文】袁淑排諧，驢山公九錫曰：若乃三軍陆邁，糧艱難，謀臣停筭，武夫吟叹，爾乃長鳴上党，［原訛傥，據冯校本改。］慷慨應邗，崎嶇千里，荷囊致餐，用捷大勋，歷世不刊，斯實爾之功者也，音隨時興，晨夜不默，仰契玄象，俯协漏刻，應更長鳴，豪分不忒，雖挈壶著稱，未足比德，斯又爾之智也，若乃六合昏晦，三辰幽冥，猶憶天時，用不废聲，斯又爾之明也，青脊隆身，長頭廣額，脩尾後垂，巨耳双磔，斯又爾之相也，嘉麥既熟，寔須精面，負磨回衡，迅若轉電，惠我眾庶，神祇獲荐，斯又爾之能也，爾有濟師旅之勋，而加之以眾能，是用遣眾能中大夫闾丘騾，加爾使衔勒大鸿臚班腳大將軍宮亭侯，以楊州之庐江，江州之庐陵，吳國之桐庐，合浦之朱庐，封爾為庐山公。","sortOrder":47},
  {"id":"s_work_nvlt_94_48","chapterId":"ch_work_nvlt_94","text":"◇骆扆","sortOrder":48},
  {"id":"s_work_nvlt_94_49","chapterId":"ch_work_nvlt_94","text":"華峤《漢書》曰：南单於遣使詣闕，奉蕃稱臣，入居於雲中，遣使上書，獻骆扆二頭，文馬十疋。","sortOrder":49},
  {"id":"s_work_nvlt_94_50","chapterId":"ch_work_nvlt_94","text":"《博物志》曰：敦煌西渡流沙，往外國，濟沙千餘里中，無水，時有伏流處，人不能知，骆扆知水脈，過其處，辄停不行，以足踏地，人於所踏處掘之，辄得水。","sortOrder":50},
  {"id":"s_work_nvlt_94_51","chapterId":"ch_work_nvlt_94","text":"洛中記曰：有銅扆二枚，在宮之南四會道，頭高九尺，頭似羊，頸身似馬，有肉鞍兩个相對。","sortOrder":51},
  {"id":"s_work_nvlt_94_52","chapterId":"ch_work_nvlt_94","text":"《異苑》曰：西域苟夷國，山上有石骆扆，腹下出水，以金鐵及手承取，即便對過，唯葫芦盛者，則得飲之，令人身體香净而昇仙，其國神秘，不可數過。","sortOrder":52},
  {"id":"s_work_nvlt_94_53","chapterId":"ch_work_nvlt_94","text":"【贊】晉郭璞橐扆贊曰：扆惟奇畜，肉鞍是被，迅骛流沙，顯功絕地，潛識泉源，微乎其智。","sortOrder":53},
  {"id":"s_work_nvlt_94_55","chapterId":"ch_work_nvlt_94","text":"《爾雅》曰：羚，大羊，［音靈，似羊而大，角員銳，好在山崖間。］羱，如羊，［似羊而大角，出西方。］羊牡羒，［墳音。］牝〈牜羊〉，［〈牜羊〉羊墳首。］夏羊，［黑〈⺶古〉〈⺶歷〉。］牡羭，［羭黑班。］羳羊黃腹，未成羊羜，［音佇，詩雲肥羜，俗雲五月羊。］絕有力奋，羊六尺為羬，［羬羊馬尾，今大月支國有大羊，馬尾，五鹹反，尸子，羊為羬六尺。］","sortOrder":55},
  {"id":"s_work_nvlt_94_56","chapterId":"ch_work_nvlt_94","text":"《說文》曰：羊，祥也，象四足角尾之形，孔子曰：牛羊之字以形舉，咩，［弭音。］羊鳴也，羔，羊子也，羜，五月生羔也，{敄羊}，［犍。］六月生羊也，羍，［恥達反。］七月生羊也，〈⺶兆〉，［兆音。］羊未卒歲也。","sortOrder":56},
  {"id":"s_work_nvlt_94_57","chapterId":"ch_work_nvlt_94","text":"《易》曰：小人用壮，君子用罔，貞厲，羝羊觸藩，羸其角。","sortOrder":57},
  {"id":"s_work_nvlt_94_58","chapterId":"ch_work_nvlt_94","text":"又曰：兑為羊。","sortOrder":58},
  {"id":"s_work_nvlt_94_59","chapterId":"ch_work_nvlt_94","text":"《毛詩》曰：羔羊，鵲巢之功致也，召南之國，化文王之政，在位皆節俭正直，德如羔羊也，羔羊之皮，素絲五紽，退食自公，委蛇委蛇。","sortOrder":59},
  {"id":"s_work_nvlt_94_60","chapterId":"ch_work_nvlt_94","text":"又曰：無羊，宣王考牧也，［厲王時，牧人废，宣王复之。］誰謂爾無羊，三百維群，爾羊來思，其角戢戢，［聚其角而息，戢戢然。］","sortOrder":60},
  {"id":"s_work_nvlt_94_61","chapterId":"ch_work_nvlt_94","text":"《周禮》曰：賓客則羊人供法羊，羊泠毛則毳膻，［法羊，食饔積膳之羊也，泠泠，長結總也。］","sortOrder":61},
  {"id":"s_work_nvlt_94_62","chapterId":"ch_work_nvlt_94","text":"又曰：羊人，掌羊牲，凡祭祀飾羔，祭祀割羊，登其首，［登首，報陽也，升首於室。］凡祈珥供其羊牲，若牧人無牲，則受布於司馬，使其買牲而供之，［布，泉也。］","sortOrder":62},
  {"id":"s_work_nvlt_94_63","chapterId":"ch_work_nvlt_94","text":"鄭氏婚禮謁文贊曰：群而不党，跪乳有家。","sortOrder":63},
  {"id":"s_work_nvlt_94_64","chapterId":"ch_work_nvlt_94","text":"《左傳》曰：華元殺羊食士，其御羊斟不與，及戰，曰：畴昔之羊，子為政，今日之事，我為政，與入鄭師，故败。","sortOrder":64},
  {"id":"s_work_nvlt_94_65","chapterId":"ch_work_nvlt_94","text":"又曰：楚子围鄭，鄭伯肉袒牵羊以逆，曰：孤不天，不能事君，使懷怒以及弊邑，孤之罪也。","sortOrder":65},
  {"id":"s_work_nvlt_94_66","chapterId":"ch_work_nvlt_94","text":"《論語》曰：子貢欲去告朔之饩羊，子曰：賜也，爾愛其羊，我愛其禮。又曰：葉公語孔子曰：吾党有直躬者，其父攘羊其子證之，孔子曰：吾党之直者，異於是，父為子隱，子為父隱，直在其中矣。","sortOrder":66},
  {"id":"s_work_nvlt_94_67","chapterId":"ch_work_nvlt_94","text":"《龍魚河圖》曰：羊有一角，食之殺人。","sortOrder":67},
  {"id":"s_work_nvlt_94_68","chapterId":"ch_work_nvlt_94","text":"《周書》曰：子夏曰：桀德衰，夷羊在牧，飛蛤滿野。","sortOrder":68},
  {"id":"s_work_nvlt_94_69","chapterId":"ch_work_nvlt_94","text":"《家語》曰：季桓子穿井，獲如土缶，其中有羊焉，使問仲尼，曰：吾穿井得羊，［家語辨物作犭苟。］何也，對曰：以丘聞羊也，木石之怪，夔魍魉，水之怪，龍罔象，土之怪，墳羊也。","sortOrder":69},
  {"id":"s_work_nvlt_94_70","chapterId":"ch_work_nvlt_94","text":"《列子》曰：楊朱見梁惠王，言治天下如運諸掌，王曰：先生有一妻一妾而不能治，三畝之園而不能耘，言治天下何也，曰：君見夫牧羊者乎，百羊為群，使五尺童子，荷箠而隨之，欲東而東，欲西而西，使尧牵一羊，舜荷箠而隨之，則不能前也。","sortOrder":70},
  {"id":"s_work_nvlt_94_71","chapterId":"ch_work_nvlt_94","text":"《莊子》曰：臧與穀二人，相與牧羊，而俱亡其羊，問臧奚事，則挟策讀書，問穀奚事，則博塞以遊，二人事業不同，其亡羊均也。","sortOrder":71},
  {"id":"s_work_nvlt_94_72","chapterId":"ch_work_nvlt_94","text":"《孫卿子》曰：仲尼將為魯司寇，沈猶氏不敢朝飲其羊。","sortOrder":72},
  {"id":"s_work_nvlt_94_73","chapterId":"ch_work_nvlt_94","text":"《史記》曰：宋義下令軍中曰：很如羊，貪如狼，不可使者皆斬之。","sortOrder":73},
  {"id":"s_work_nvlt_94_74","chapterId":"ch_work_nvlt_94","text":"又曰：卜式者，河西人，式有少弟，式脱身出分，獨取畜羊百餘，田宅财物盡與弟，式入山牧十餘歲，羊致千餘，上曰：吾有羊在上林中，欲令子牧之，式乃拜為郎，布衣草蹻而牧，歲餘，羊肥息，上過其羊，問之，式曰：非獨羊也，治民亦猶是也，惡者辄去，無令败群，上以式為奇，拜為缑氏令。","sortOrder":74},
  {"id":"s_work_nvlt_94_75","chapterId":"ch_work_nvlt_94","text":"又曰：盧綰與高祖俱學書，相愛，里中贺兩家以羊酒。","sortOrder":75},
  {"id":"s_work_nvlt_94_76","chapterId":"ch_work_nvlt_94","text":"《地鏡圖》曰：金百斤已上，至三百斤，精如羊者。","sortOrder":76},
  {"id":"s_work_nvlt_94_77","chapterId":"ch_work_nvlt_94","text":"《玄中記》曰：千歲之树，精為青羊。","sortOrder":77},
  {"id":"s_work_nvlt_94_78","chapterId":"ch_work_nvlt_94","text":"《春秋繁露》曰：凡贽，卿用羔，羔有角而不用，如好仁者，執之不鳴，殺之不謗，類死義者，羔飲其母，必跪，類知禮者，故羊之為言猶祥，故以為贽。","sortOrder":78},
  {"id":"s_work_nvlt_94_79","chapterId":"ch_work_nvlt_94","text":"《列仙傳》曰：葛由者，羌人，周成王時，好刻木作羊賣之，一旦騎羊而入蜀，蜀中王侯遣人追之，上綏山，山在峨眉山西南，無［《太平御覽》九百零二無上有高字。］極，隨之者不得還，皆得仙道，山上有桃，故里諺曰：得綏山一桃，雖不得仙，亦足以豪，山下立祠。","sortOrder":79},
  {"id":"s_work_nvlt_94_80","chapterId":"ch_work_nvlt_94","text":"昔有攘羊者，以羊頭遺晉叔向，向母埋之不食，後三年，攘羊事發，追捕向家，檢羊，骨肉都盡，唯有舌在，國人異之，遂以羊舌為族。","sortOrder":80},
  {"id":"s_work_nvlt_94_81","chapterId":"ch_work_nvlt_94","text":"《漢書》曰：蘇武往使匈奴，匈奴知武不可降，使北海上無人處牧羝羊，下乳乃得歸，武作海上，廪食不至，乃掘野鼠草荄而食之，武杖漢節牧羊，臥起持節，旄盡落。","sortOrder":81},
  {"id":"s_work_nvlt_94_82","chapterId":"ch_work_nvlt_94","text":"又曰：路溫舒，鉅鹿人，父為里監門，使溫舒牧羊，溫舒取泽中蒲，截以為牒，編用寫書。","sortOrder":82},
  {"id":"s_work_nvlt_94_83","chapterId":"ch_work_nvlt_94","text":"《東觀漢記》曰：甄宇，北海人，建武中，為州從事，徵拜博士，每腊，詔書賜博士羊，羊有大小肥瘦，時博士祭酒議，欲殺羊，稱分其肉，宇曰：不可。又欲投鉤，复恥之，宇因先自取其最瘦者，猶是不复有爭訟，後召會，詔問瘦羊甄博士，京師因以號之。","sortOrder":83},
  {"id":"s_work_nvlt_94_84","chapterId":"ch_work_nvlt_94","text":"《魏志》曰：楊俊同郡王象，孩少孤特，為人仆隸，年十七八，見使牧羊，而私讀書，因獲捶楚，俊美其才质，即贖象著家，娉娶立屋，然後與別，象官至散騎常侍。","sortOrder":84},
  {"id":"s_work_nvlt_94_85","chapterId":"ch_work_nvlt_94","text":"衛玠少時，乘白羊，於洛陽市，市人觀之，鹹曰：誰家璧人，於是家聞州党，遂號曰璧人，［本條《太平御覽》九百零二作衛玠別傳，羊下有車字。］","sortOrder":85},
  {"id":"s_work_nvlt_94_86","chapterId":"ch_work_nvlt_94","text":"博物志曰：胡蕙蜀中本無，洛中人有驅羊入蜀者，胡蕙子著羊毛，蜀人取种，因名曰羊負來。又，外國得胡麻豆，或曰戎菽。","sortOrder":86},
  {"id":"s_work_nvlt_94_87","chapterId":"ch_work_nvlt_94","text":"王隱《晉書》曰：王尼嘗為兵，洛中名士王澄胡母辅之等，赍羊酒詣護軍，門吏請見將軍，澄等先過尼，炙羊飲酒訖，迳去，將軍聞之，與尼長假。","sortOrder":87},
  {"id":"s_work_nvlt_94_88","chapterId":"ch_work_nvlt_94","text":"《神仙傳》曰：皇初平年十五，家使牧羊，有道士見其良謹，便將至金華山石室中，四十餘年，忽然不复念家，其兄初起，行索初平，歷年不得，後見市中有道士，乃問之，道士曰：金華山中有牧羊兒，姓皇字初平，兄乃隨道士與初平相見，語畢，問羊何在，在山東，兄往视，但見白石，不見羊，平曰：羊在耳，兄自不見，平乃往，言叱叱羊起，於是白石皆起成羊數萬頭。","sortOrder":88},
  {"id":"s_work_nvlt_94_89","chapterId":"ch_work_nvlt_94","text":"又曰：曹公收左慈，慈走入群羊中，失慈之所在，追者疑化為羊，乃令人數羊，羊本千口，揀之，長一口，知果化為羊，乃謂曰：若是左公者，但出無苦也，有一羊跪雲，詎如許，追者欲執之，於是群羊皆跪曰：詎如許，追者乃去。","sortOrder":89},
  {"id":"s_work_nvlt_94_90","chapterId":"ch_work_nvlt_94","text":"《搜神記》曰：宣帝時，陰子方者至孝，有二息，嘗腊日晨炊，而竈神形見，子方再拜受慶，家有黃羊，因以祠之，自是暴至巨富，子方常言，我子孫必將強大，至識三世，而遂繁昌，故後常至腊日祠竈，而荐黃羊焉。","sortOrder":90},
  {"id":"s_work_nvlt_94_91","chapterId":"ch_work_nvlt_94","text":"又曰：南陽宗定伯夜行，忽逢一鬼，鬼問伯為誰，伯欺之曰：我亦鬼也，遂為侣，向宛行倦，因相擔，問鬼曰：鬼何畏，曰：鬼唯不喜唾耳，欲至宛，便擔鬼著頭上，詣宛市，鬼化為羊，伯恐其变，遂唾之，因賣得錢千五百，買者將還系之，明旦見繩在，時人語曰：宗定伯賣鬼，得錢千五百。","sortOrder":91},
  {"id":"s_work_nvlt_94_92","chapterId":"ch_work_nvlt_94","text":"《續搜神記》曰：顧霈者，吳之豪士，送客置酒，有一沙門在坐，主人殺羊，羊繩斷，便走來，入道人膝中，穿頭入袈裟下，道人不能救，即將去殺之，既行炙，主人便先割以啖道人，道人食炙，下喉，便自行道人皮中，痛毒不可忍，呼医來針之，以數針貫三炙，猶動搖，乃破出之，是故一脔肉耳，道人於此得病，作羊鳴，少時便死。","sortOrder":92},
  {"id":"s_work_nvlt_94_93","chapterId":"ch_work_nvlt_94","text":"崔豹《古今註》曰：羊一名髯須主簿。","sortOrder":93},
  {"id":"s_work_nvlt_94_94","chapterId":"ch_work_nvlt_94","text":"《幽明錄》曰：洛下有洞穴，不测，有一婦欲殺夫，推夫下，經多時至底，乃得一穴，匍匐行數十里，漸見明曠，郛郭宮馆，金寶為飾，明逾三光，人皆長三丈，被羽衣，如此九處，至最後所，飢，長人指中庭大柏树，近百围，下有一羊，令跪持羊須，捋之得一珠，長人取之，次亦取，後將令啖，即療飢，乃問詣九處名，及求住，答雲，君不得停，還問張華，當知，乃复行，出交州，還洛問華，華曰：九處地仙，名九馆大，羊為螭［法苑珠林四十一大下有夫字，螭作癡。］龍，初一珠，食之與天地等寿，次者延年，後者充飢而已。","sortOrder":94},
  {"id":"s_work_nvlt_94_95","chapterId":"ch_work_nvlt_94","text":"《雜五行書》曰：懸羊頭門上，除盜賊。","sortOrder":95},
  {"id":"s_work_nvlt_94_96","chapterId":"ch_work_nvlt_94","text":"【贊】晉郭璞羊贊曰：月氏之羊，其類在野，厥高六尺，尾亦如馬，何以審之，事見爾雅。","sortOrder":96},
  {"id":"s_work_nvlt_94_97","chapterId":"ch_work_nvlt_94","text":"杜預奏事曰：臣前在南，聞魏興北山有野羊，大者千數百斤，试令求之者，各得一枚，併頭角蹄，按其形不與中土羊相似，然是野獸中所希有。","sortOrder":97},
  {"id":"s_work_nvlt_94_99","chapterId":"ch_work_nvlt_94","text":"《爾雅》曰：犬生三猣，［宗。］二師，一〈犭單斤〉，［旂。］未成毫狗，［狗子未生翰毛。］長喙獫，［力艳。］短喙猲［歇。］獢，［嚣，詩載獫猲獢。］絕有力狣，狣多力，犭尨［尨。］狗也，狗四尺為獒。","sortOrder":99},
  {"id":"s_work_nvlt_94_100","chapterId":"ch_work_nvlt_94","text":"《山海經》曰：蜪犬如犬，青色，食人從首始。","sortOrder":100},
  {"id":"s_work_nvlt_94_101","chapterId":"ch_work_nvlt_94","text":"《易》曰：兑為狗。","sortOrder":101},
  {"id":"s_work_nvlt_94_102","chapterId":"ch_work_nvlt_94","text":"《左傳》曰：晉侯飲趙盾［原作遁，據冯校本改。］下同。］酒，伏甲將攻之，其右提弥明知之，趨登曰：臣侍君宴，過三爵，非禮也，遂扶以下，公嗾夫獓焉，明搏而殺之，盾曰：弃人用犬，雖猛何為，斗且出。","sortOrder":102},
  {"id":"s_work_nvlt_94_103","chapterId":"ch_work_nvlt_94","text":"又曰：國人逐〈廣契〉狗，〈廣契〉狗入於華臣氏，國人從之，華臣懼，遂奔陳，［華臣心不自安，見逐狗而驚去。］","sortOrder":103},
  {"id":"s_work_nvlt_94_104","chapterId":"ch_work_nvlt_94","text":"又曰：取邾師，邾人愬於晉，晉人來讨，叔孫婼如晉，乃馆諸箕，吏人之與叔孫居於箕者，取其吠狗，弗與，及將歸，殺而與之食。","sortOrder":104},
  {"id":"s_work_nvlt_94_105","chapterId":"ch_work_nvlt_94","text":"《穆天子傳》曰：天子之狗走百里，執虎豹，［言筋力猛。］","sortOrder":105},
  {"id":"s_work_nvlt_94_106","chapterId":"ch_work_nvlt_94","text":"《晏子》曰：晏子短，使楚，楚人為門於犬門侧，延晏子，《晏子》曰：使狗國者從狗門入，今使楚王，不當從此門入。","sortOrder":106},
  {"id":"s_work_nvlt_94_107","chapterId":"ch_work_nvlt_94","text":"《列子》曰：楊朱之弟曰布，衣素衣而出，天雨，解素衣，衣黑衣而返，其狗迎而吠之，楊布怒，將朴狗，楊朱曰：子無朴矣，子亦猶是也，乡者使汝狗白而往，黑而來，豈能無怪哉，尹《文子》曰：康衢長者，字僮曰善搏，字犬曰善噬，賓客不過其門三年，長者怪而問之，以實對，於是改之，賓客复往。","sortOrder":107},
  {"id":"s_work_nvlt_94_108","chapterId":"ch_work_nvlt_94","text":"《楚辭》曰：何少康逐犬，而顛陨厥首，［言少康因獵放犬逐獸，於是舍所宿也。］","sortOrder":108},
  {"id":"s_work_nvlt_94_109","chapterId":"ch_work_nvlt_94","text":"又曰：兄有噬犬弟何欲，［兄謂秦伯也，秦伯有犬，弟針欲請。］易之以百兩卒無祿。","sortOrder":109},
  {"id":"s_work_nvlt_94_110","chapterId":"ch_work_nvlt_94","text":"又曰：豈不鬱陶而思君兮，君之門兮九重，猛犬狺狺而迎吠兮，關梁閉而不通。","sortOrder":110},
  {"id":"s_work_nvlt_94_111","chapterId":"ch_work_nvlt_94","text":"《呂氏春秋》曰：齊有好獵者，終日不得獸，入則媿其友，推其所以不得獸，狗惡故也，欲得良狗則家貧，家富則求良狗，得狗則數得獸矣，非獨獵也，百事皆然。","sortOrder":111},
  {"id":"s_work_nvlt_94_112","chapterId":"ch_work_nvlt_94","text":"又曰：昔文王得如黃之狗，宛路之矰，遊於雲夢，三月不反。","sortOrder":112},
  {"id":"s_work_nvlt_94_113","chapterId":"ch_work_nvlt_94","text":"《韓子》曰：宋有酤酒者，斗概甚平，遇客甚謹，為酒甚美，懸幟甚高，然而酒不售，酒酸，怪其故，問所闾長者楊青，青曰：汝狗猛耶，曰：狗猛，狗猛何故不售，曰：人畏焉，或令孺子懷錢挈壶往酤，而狗迎龁之，酒所以酸而不售，夫國亦有猛狗，有道之士懷其術，而欲以明萬乘之主，大臣為猛狗，迎而龁之，此人主所以蔽胁，有道之士所以不用也。","sortOrder":113},
  {"id":"s_work_nvlt_94_114","chapterId":"ch_work_nvlt_94","text":"《史記》曰：范睢說秦昭王曰：夫以秦而治諸侯，譬若縱韓盧而搏蹇兔也，今閉關十五年，不敢闚兵於山東者，是穰侯為秦謀不忠，而大王之計有所失也。","sortOrder":114},
  {"id":"s_work_nvlt_94_115","chapterId":"ch_work_nvlt_94","text":"又曰：高祖詔齊捕蒯通，通至，上曰：若何教淮陰侯反，對曰：然，臣固教之，跖之狗吠尧，尧非不仁，狗固吠非其主，當是時，臣獨知韓信，非知陛下也。","sortOrder":115},
  {"id":"s_work_nvlt_94_116","chapterId":"ch_work_nvlt_94","text":"《戰國策》曰：齊欲伐魏，淳於髡謂齊王曰：韓盧者，天下之壮犬也，東郭兔者，海內之狡兔也，韓盧逐東郭兔，環山者三，騰山者五，兔極於前，犬疲於後，犬兔俱罢死其處，田父獲之，無勞倦之苦，而擅其功，今齊魏久相持，以頓其兵，弊其眾，臣恐強秦大楚承其後，而有田父之功獲，齊王懼，休將士。","sortOrder":116},
  {"id":"s_work_nvlt_94_117","chapterId":"ch_work_nvlt_94","text":"《說苑》曰：梁相死，惠子欲之梁，渡河，遽，墮船，船人救之，曰：子欲何之而遽，曰：梁無相，吾欲往相之，船人曰：子居船楫之間而溺，無我則死矣，何能相梁，惠子曰：居廣艘長楫之間，則我不如子，至於安國家，全社稷，子不比我，子蒙蒙如未视之狗子耳。","sortOrder":117},
  {"id":"s_work_nvlt_94_118","chapterId":"ch_work_nvlt_94","text":"又曰：孟嘗君寄客於齊王，三年不見用，故客反見曰：不知臣之罪耶，君之過也，孟嘗君曰：寡人聞之，縷因針而入，不因針而急，嫁女因媒而成，不因媒而畜，夫子之才必薄矣，當何怨寡人哉，客曰：臣聞韓氏之盧，天下疾狗也，見兔而指屬，則不失兔，望見而放狗，則累世不能得兔，狗非不疾，不能屬者罪也。","sortOrder":118},
  {"id":"s_work_nvlt_94_119","chapterId":"ch_work_nvlt_94","text":"《漢書》曰：樊哙，沛人也，以屠狗為事。","sortOrder":119},
  {"id":"s_work_nvlt_94_120","chapterId":"ch_work_nvlt_94","text":"《漢武故事》曰：公孫卿至東萊，雲見一人，長五丈，牵一黃犬，把一黃雀，欲謁天子，因忽不見。","sortOrder":120},
  {"id":"s_work_nvlt_94_121","chapterId":"ch_work_nvlt_94","text":"《東觀漢記》曰：鮑永少有志操，治欧陽尚書，事後母至孝，妻嘗於母前叱犬，而永即去之。","sortOrder":121},
  {"id":"s_work_nvlt_94_122","chapterId":"ch_work_nvlt_94","text":"《風俗通》曰：桂陽太守汝南韦叔堅，少時為從事，在家，狗人立行於家中，皆言當殺之，叔堅雲，犬馬諭君子，狗見人行，效之何傷，叔堅為縣令還，解冠榻上，狗戴持走，家人驚愕，复雲，誤觸冠，冠纓掛著耳，狗又上竈，家益怪，复雲，兒婦皆在田中，狗何能作怪，遂不肯殺，後數日，狗自暴死，卒無纖芥之異，叔堅至太尉，終於位。","sortOrder":122},
  {"id":"s_work_nvlt_94_123","chapterId":"ch_work_nvlt_94","text":"《魏略》曰：丁謐外似疏濫，而內明慧，雖與何晏邓颺等同列，而皆少之，唯以聲势屈於曹爽，爽亦敬之，言無不從，故於時謗書，謂台中三狗啀喍不可當，一狗冯默作蛆囊，三狗謂何邓丁也，默者爽小字也，其意言三狗皆欲齧人而畜蛆也。","sortOrder":123},
  {"id":"s_work_nvlt_94_124","chapterId":"ch_work_nvlt_94","text":"《華陽國志》曰：雍闿欲降魏，說夷曰：官欲得乌狗三百頭膺前盡黑腦三升，汝能得不，夷皆從闿。","sortOrder":124},
  {"id":"s_work_nvlt_94_125","chapterId":"ch_work_nvlt_94","text":"《玄中記》曰：狗封氏者，高辛氏有美女，未嫁，犬戎為亂，帝曰：有讨之者，妻以美女，封三百戶，帝之狗名槃護，三月而殺犬戎之首來，帝以為不可訓民，乃妻以女，流之會稽東南二萬一千里，得海中土，方三千里而封之，生男為狗，生女為美女。","sortOrder":125},
  {"id":"s_work_nvlt_94_126","chapterId":"ch_work_nvlt_94","text":"《雜五行書》曰：犬生四子，取黃子養之，犬生五子，取青子養之，六子，取赤子養之，七子，取黑養之，八子，取白養之，白犬乌頭，令人得财，白犬黑尾，令人世世乘車，黑犬白耳，犬主畜之，令人富貴，黑犬白前兩足，宜子孫，黃犬白尾，令人世世衣冠。","sortOrder":126},
  {"id":"s_work_nvlt_94_127","chapterId":"ch_work_nvlt_94","text":"孫盛《晉陽秋》曰：王敦败京都之後，夢白犬自天而下噬之。","sortOrder":127},
  {"id":"s_work_nvlt_94_128","chapterId":"ch_work_nvlt_94","text":"《搜神記》曰：東越閩中，有庸嶺，高數十里，下北隰中，有大蛇，長七八丈，大十餘围，常病都尉及長史，下夢巫覡，欲得啖女童，常八月祭送蛇穴，蛇辄吞之，已用九女，時將樂縣李誕，有小女名奇，應募而行，乃請好劍咋蛇犬，作數斛餈，蜜灌之，置穴口，蛇出頭，大如囷，目如二尺鏡，先啖餈灌，奇便放犬咋蛇，以劍斫殺之，得九女髑髏，越王乃娉奇為後。","sortOrder":128},
  {"id":"s_work_nvlt_94_129","chapterId":"ch_work_nvlt_94","text":"又曰：高辛氏有老婦人，居王宮，得耳疾，医為挑治，得一物，大如茧，婦人盛之以瓠，覆之以盤，俄頃而化為犬，其文五色，名盤瓠。","sortOrder":129},
  {"id":"s_work_nvlt_94_130","chapterId":"ch_work_nvlt_94","text":"又曰：漢成帝河清元年，長安男子石良劉晉，相與同居，有如人状在其室，击之為狗，去复至，數人被甲持兵弩來，格之或傷，盡狗也，自二月至六月乃止，其於洪范，皆犬禍，言不從之咎也。","sortOrder":130},
  {"id":"s_work_nvlt_94_131","chapterId":"ch_work_nvlt_94","text":"又曰：成［按成字衍。］山陽王瑚，字孟璉，為東海蘭陵令，夜半時，辄有黑帻白单衣吏，詣縣扣閤，迎之則忽然不見，如此數年，於外伺之，見一老狗，黑頭白軀，至閤便為人，殺之乃絕。","sortOrder":131},
  {"id":"s_work_nvlt_94_132","chapterId":"ch_work_nvlt_94","text":"《續搜神記》曰：會稽句章民張然，滯役在都，經年不得歸，家有少婦，遂與奴私通，然在都，養一狗甚快，名乌龍，後假歸，奴與婦欲謀殺然，作飯食，共坐下食，未得啖，奴當戶倚，張弓栝箭拔刀，然以盤中肉飯與狗，狗不啖，唯註精舐唇视奴，然亦覺之，奴催食轉急，然决計，拍髀大唤曰：乌龍，狗應聲傷奴，奴失刀仗倒地，狗遂咋奴頭，然因取刀斬奴，以婦付官殺之。","sortOrder":132},
  {"id":"s_work_nvlt_94_133","chapterId":"ch_work_nvlt_94","text":"又曰：晉太和中，廣陵人楊生，養狗，甚怜愛之，行止與俱，後生飲酒醉，行大泽草中，眠不能動，時冬月野火起，風又猛，狗周章號唤，生醉不覺，前有一坑水，狗便走往水中還，以身洒生左右，草沽［《太平御覽》九百零五作沾。］水得著地，火尋過去，生醒，方見之，他日又闇行，墮空井中，狗伸［御覽作呻。］吟彻晓，須臾，有人過，怪此狗向井號，往视見生，生曰：君可出我，當厚報君，人曰：以此狗見與，便當相出，生曰：此狗曾活我於已死，不得相與，餘即無惜，人曰：若爾，便不相出，狗因下頭目井，生知其意，乃語路人，以狗相與，人乃出之，系狗而去，後五日，狗夜走歸。","sortOrder":133},
  {"id":"s_work_nvlt_94_134","chapterId":"ch_work_nvlt_94","text":"又曰：休［御覽九百零五作林。］慮山下有亭，每過宿者，或病死，常雲有十許人男女，合［御覽作各。］雜衣，或黑或白，辄來為害，有郅伯夷者，過宿，明燭而坐誦經，至中夜，忽有十餘人來，與伯夷併坐蒲博，伯夷密以鏡照之，乃是群犬，因執燭起，陽誤以燭燒其衣，作燃毛氣，伯夷懷刀，捉一人刺之，初作人唤，遂死成犬，餘悉走去。","sortOrder":134},
  {"id":"s_work_nvlt_94_135","chapterId":"ch_work_nvlt_94","text":"又，晉穆哀之世，領軍司馬濟陽蔡詠家狗，夜辄群眾相吠，往视便伏，後日使人夜伺，有一狗，著黃衣白帢，長五六尺，眾狗共吠之，尋跡定是詠家老黃狗，即打殺之，吠乃止。","sortOrder":135},
  {"id":"s_work_nvlt_94_136","chapterId":"ch_work_nvlt_94","text":"秦氏《三秦記》曰：有白鹿原，周平王時，白鹿出此原，原上有狗枷堡，秦襄公時，有天狗來下其上，有賊，天狗吠而護之，故一堡無懼心。","sortOrder":136},
  {"id":"s_work_nvlt_94_137","chapterId":"ch_work_nvlt_94","text":"《述征記》曰：彭城東岸有一丘，俗謂之狗葬，或雲斯則徐偃王葬後仓者也，未詳，古徐國宮人，娠而生开，［按當作卵。］弃之水濱，有狗名後仓，衔而歸，〈禹弗〉而成人，遂為徐之嗣君，純筋無骨，曰偃王，偃王躬行仁義，眾附之，得朱弓朱矢之瑞，周穆王命楚滅之，後仓將死，生角尾，實黃龍也。","sortOrder":137},
  {"id":"s_work_nvlt_94_138","chapterId":"ch_work_nvlt_94","text":"《述異記》曰：陆機少時，頗好獵，在吳，豪客獻快犬，名曰黃耳，機後仕洛，常將自隨，此犬黠慧，能解人語。又嘗借人三百里外，犬識路自還，一日至家，機羁旅京師，久無家問，因戲語犬曰：我家絕無書信，汝能赍書馳取消息不，犬喜，搖尾作聲應之，機试為書，盛以竹筒，系之犬頸，犬出驿路，走向吳，飢則入草，噬肉取飽，每經大水，辄依渡者，弭毛掉尾向之，其人怜愛，因呼上船，裁近岸，犬即騰上速去，先到機家口，衔筒作聲示之，機家开筒取書，看畢，犬又伺人作聲，如有所求，其家作答書，內筒，复系犬頸，犬既得答，仍馳還洛，計人行程五旬，犬往還裁半月，後犬死，殯之，遣送還葬機村，去機家二百步，聚土為墳，村人呼為黃耳冢。","sortOrder":138},
  {"id":"s_work_nvlt_94_139","chapterId":"ch_work_nvlt_94","text":"又曰：宋元嘉中，石玄度家有黃狗，生白雄子，母孕其子，異於常狗，衔食食之，子大，其狗出獵未反，辄門外望之，後玄度病，辄危困，医為處方湯，須白狗肺，市索卒不能得，乃殺所養白狗，以湯供其用，母向子死處，跳踴嗥呼，倒复起，竟日不息，其家煮狗子肉共食之，投骨於地，母辄衔著窟中。","sortOrder":139},
  {"id":"s_work_nvlt_94_140","chapterId":"ch_work_nvlt_94","text":"【詩】晉張華詩曰：如黃批狡兔，青骹撮飛雉，鵠鷺皆盡收，凫鹥安足视。","sortOrder":140},
  {"id":"s_work_nvlt_94_141","chapterId":"ch_work_nvlt_94","text":"【賦】晉傅玄狗賦曰：何世來貢，作珍皇家，骨相多奇，儀表可嘉，足縣鉤爪，口含素牙，首類驤螭，尾如螣蛇，細頸闊焜，廣前稍後，丰顱促耳，長叉缓口。","sortOrder":141},
  {"id":"s_work_nvlt_94_142","chapterId":"ch_work_nvlt_94","text":"魏贾代宗狗賦曰：餘處大魏之祚，迸在朔陽，越彼西旅，大犬是獲，形體如翦削，像濬如刻畫，毛翰紫艳光，双眉如白璧，爪類刀戈，牙如交戟，盼攀而奋怒，揮霍而振掷，譬若天梁折，地柱劈，倒曳白象挫其腰，齧掣六駮折其脊，爪處如鉤牙，扌杰創似矛刺。","sortOrder":142},
  {"id":"s_work_nvlt_94_144","chapterId":"ch_work_nvlt_94","text":"《爾雅》曰：豕子猪，〈豕隋〉豮，灺幼，［最後生者。］奏者豱，［溫。］豕生三豵，［子公。］二師，一特，［豕生子常多，故取少者名之。］四豴皆白豥，［該。］其跡刻絕有力〈豕厄〉，［枙。］牝豝，［巴。］","sortOrder":144},
  {"id":"s_work_nvlt_94_145","chapterId":"ch_work_nvlt_94","text":"《方言》曰：猪，燕朝鮮之間謂之豭，關東西謂之彘，或謂之豕，南楚謂之豨，其子或謂之豚，或謂犭奚，［奚。］吳陽［《太平御覽》九百零三作楊。］之間，謂之猪子。","sortOrder":145},
  {"id":"s_work_nvlt_94_146","chapterId":"ch_work_nvlt_94","text":"《易》曰：見豕負涂。","sortOrder":146},
  {"id":"s_work_nvlt_94_147","chapterId":"ch_work_nvlt_94","text":"又曰：坎為豕。","sortOrder":147},
  {"id":"s_work_nvlt_94_148","chapterId":"ch_work_nvlt_94","text":"《毛詩》曰：有豕白蹢，蒸涉波矣。","sortOrder":148},
  {"id":"s_work_nvlt_94_149","chapterId":"ch_work_nvlt_94","text":"《論語》曰：陽货欲見孔子，孔子不見，饋孔子豚。","sortOrder":149},
  {"id":"s_work_nvlt_94_150","chapterId":"ch_work_nvlt_94","text":"《墨子》曰：孔子窮陳蔡之間，藜蒸不糂，子路烹豚，孔子不問肉所由來，即食之。","sortOrder":150},
  {"id":"s_work_nvlt_94_151","chapterId":"ch_work_nvlt_94","text":"《史記》曰：子路性鄙，好勇力，冠雄雞，佩猳豚，凌暴孔子，孔子設禮，稍誘子路，子路後服，委质，因門人請為弟子。","sortOrder":151},
  {"id":"s_work_nvlt_94_152","chapterId":"ch_work_nvlt_94","text":"又曰：窦太後好老子書，召袁固，問老子，固曰：此家人言耳，太後怒曰：安得司空城旦書乎，使固下圈击豕，景帝知太後怒，而固直言無罪，乃假固利兵，下圈刺豕，正中其心，應手而倒，太後默然，乃罢之。","sortOrder":152},
  {"id":"s_work_nvlt_94_153","chapterId":"ch_work_nvlt_94","text":"《韓詩外傳》曰：孟子少時，東家嘗殺猪，孟子問其母曰：東家殺猪，何以為，其母曰：欲啖汝，其母悔失言，曰：吾懷妊是子，席不正不坐，割不正不食，胎教之也，今適有知而欺之，是教之不信也，置東家猪肉以食之，明不欺也。","sortOrder":153},
  {"id":"s_work_nvlt_94_154","chapterId":"ch_work_nvlt_94","text":"《漢書》曰：公孫弘，菑川人，少時為獄吏，有罪免，家貧，牧豕海上，四十餘，乃學春秋雜說，年六十，以賢良徵，為博士丞相，封平津侯。","sortOrder":154},
  {"id":"s_work_nvlt_94_155","chapterId":"ch_work_nvlt_94","text":"又曰：郅都，東海人，景帝時為郎，嘗從遊上林，贾姬在廁，野彘入廁，上目都，都不行，上乃欲自持兵救贾姬，都伏上前曰：亡一姬，一姬進，天下所少，寧贾姬耶，陛下縱自輕，奈宗廟太後何，上還，彘亦不傷贾姬。","sortOrder":155},
  {"id":"s_work_nvlt_94_156","chapterId":"ch_work_nvlt_94","text":"《東觀漢記》曰：閩［東觀漢記作闵。］仲叔，居安邑，家貧，不能得錢買肉，安邑令候之，問諸子，何飯食，對曰：但食猪肝，屠者或不肯與之，令出敕市，後嘗買辄得，仲叔怪問，其子道状如此，乃叹曰：叔豈以口腹累安邑耶，遂去之。","sortOrder":156},
  {"id":"s_work_nvlt_94_157","chapterId":"ch_work_nvlt_94","text":"又曰：吳祐，年二十，丧父獨居，家無擔石，而不受贍遺，常牧豕於長垣泽中，行吟經書，遇父故人，謂之曰：卿二千石子，而杖鞭牧豕，縱子無恥，奈君父何，祐辭謝而已，守志如初。","sortOrder":157},
  {"id":"s_work_nvlt_94_158","chapterId":"ch_work_nvlt_94","text":"又曰：梁鸿家貧而尚節，博覽無不通，畢乃牧豕於上林苑中，曾誤遺火，延及他舍，乃尋訪燒者，問所失，悉以豕偿之，其主猶以為少，鸿曰：無他财，原以身居作，主人許，因為執勤不懈，耆老見鸿非恒人，乃共责讓主人，而稱鸿長者，於是始敬異，悉還其豕，鸿不受，乃去。","sortOrder":158},
  {"id":"s_work_nvlt_94_159","chapterId":"ch_work_nvlt_94","text":"《續漢書》曰：曹騰父萌，［魏志一註作節，下同。］以仁厚稱，鄰人有豕者，與萌豕相類，詣門認之，萌不與爭，後所亡豕自還其家，主人大慚，送所認豕，併辭謝萌，萌笑而受之。","sortOrder":159},
  {"id":"s_work_nvlt_94_160","chapterId":"ch_work_nvlt_94","text":"張璠漢紀曰：莎車王殺於闐王，於闐大［《太平御覽》九百零三大下有人字。］都末出城，見野豕，欲搏之，乃人語曰：無殺我，我為汝殺莎車將軍，都末異之，即與兄弟共殺莎車王。","sortOrder":160},
  {"id":"s_work_nvlt_94_161","chapterId":"ch_work_nvlt_94","text":"皇甫謐《高士傳》曰：孫期，濟陰人，少為諸生，治京氏易古文尚書，家貧，事母至孝，牧豕於大泽中，以奉養焉，遠人往從其學者，皆執經垄畔以追之，里落化其仁讓，黃巾賊起，過其里陌，相約不犯孫先生舍，辟舉方正，遣吏赍羊酒請期，期驅豕入草不顧，司徒黃琬特辟，不就，終於家。","sortOrder":161},
  {"id":"s_work_nvlt_94_162","chapterId":"ch_work_nvlt_94","text":"董正別傳曰：司馬徽，字德操，時人呼為水鏡，嘗有人妄認徽猪，徽便推猪以與之，後數日，亡猪者得其猪，既以猪還徽，乃叩頭自责，徽又厚謝之。","sortOrder":162},
  {"id":"s_work_nvlt_94_163","chapterId":"ch_work_nvlt_94","text":"《魏志》曰：〈木邑〉娄在扶餘東北，處山林之間，常穴居，大家深九梯，以多為好，土氣寒於扶餘，其俗好養猪，食其肉，衣其皮，冬以猪膏涂身，厚數分，以御風寒，夏則裸袒，以大布隱其前後也。","sortOrder":163},
  {"id":"s_work_nvlt_94_164","chapterId":"ch_work_nvlt_94","text":"《郭子》曰：劉道真少時，嘗魚釣草泽，善歌嘯，聞者莫不留連，有一老嫗，識其非常人，甚樂其嘯，乃殺〈犭屯〉以進之，道真食〈犭屯〉盡，了不謝，嫗見其不飽。又進一〈犭屯〉。又食半，餘半還之，後道真為吏部郎，嫗兒為小令史，道真乃超用之，兒不知所由。問母而後知之，於是赍牛酒以詣道真，真笑曰：去，無复相報。","sortOrder":164},
  {"id":"s_work_nvlt_94_165","chapterId":"ch_work_nvlt_94","text":"【贊】晉郭璞封豕贊曰：有物貪婪，號曰封豕，荐食無餍，肆其殘毀，羿乃飲羽，獻帝效技。","sortOrder":165},
  {"id":"s_work_nvlt_94_166","chapterId":"ch_work_nvlt_94","text":"又豪彘贊曰：刚鬛之族，號曰豪豨，毛如攒錐，中有激矢，厥體兼資，自為牝牡。","sortOrder":166},
  {"id":"s_work_nvlt_94_167","chapterId":"ch_work_nvlt_94","text":"《藝文類聚》　唐·欧陽詢","sortOrder":167},
  {"id":"s_work_nvlt_95_1","chapterId":"ch_work_nvlt_95","text":"卷九十五獸部下","sortOrder":1},
  {"id":"s_work_nvlt_95_2","chapterId":"ch_work_nvlt_95","text":"○象犀兕駮貔熊鹿獐兔狐猿猕猴果然狌々貂鼠","sortOrder":2},
  {"id":"s_work_nvlt_95_4","chapterId":"ch_work_nvlt_95","text":"《爾雅》曰：南方之美者，有梁山之犀象焉。","sortOrder":4},
  {"id":"s_work_nvlt_95_5","chapterId":"ch_work_nvlt_95","text":"《山海經》曰：巴蛇食象，三歲而出其骨。","sortOrder":5},
  {"id":"s_work_nvlt_95_6","chapterId":"ch_work_nvlt_95","text":"《左傳》曰：象有齒，以焚其身。","sortOrder":6},
  {"id":"s_work_nvlt_95_7","chapterId":"ch_work_nvlt_95","text":"《孟子》曰：周公驅犀象而遠之，天下大悅。","sortOrder":7},
  {"id":"s_work_nvlt_95_8","chapterId":"ch_work_nvlt_95","text":"《萬歲歷》曰：成帝鹹康六年，臨邑王獻象一，知跪拜，御者使從之。","sortOrder":8},
  {"id":"s_work_nvlt_95_9","chapterId":"ch_work_nvlt_95","text":"《吳志》曰：贺齊為新都郡守，孫權出祖道，作樂舞象，權謂齊曰：今定天下，都中國，使殊俗貢珍，百獸率舞，非君而誰。","sortOrder":9},
  {"id":"s_work_nvlt_95_10","chapterId":"ch_work_nvlt_95","text":"《江表傳》曰：孫權遣使詣獻馴象二頭，魏太祖欲知其斤重，鹹莫能出其理，邓王冲尚幼，乃曰：置象大舡上，刻其所至，秤物以載之，校可知也，太祖大悅。","sortOrder":10},
  {"id":"s_work_nvlt_95_11","chapterId":"ch_work_nvlt_95","text":"又曰：魏文帝遣使於吳，求象牙，群臣以非禮，欲不與，孫權敕付之。","sortOrder":11},
  {"id":"s_work_nvlt_95_12","chapterId":"ch_work_nvlt_95","text":"蜀將諸葛亮，讨賊還成都，孫權遣勞問之，送馴象二頭與劉禪。","sortOrder":12},
  {"id":"s_work_nvlt_95_13","chapterId":"ch_work_nvlt_95","text":"吳時外國傳曰：扶南王盤况，少而雄桀，聞山林有大象，辄生捕取之，教習乘騎，諸國聞而伏之，《博物志》曰：昔日南有四象，各有雄雌，其一雌死百有餘日，其雄泥土著身，獨不飲酒食肉，長吏問其所以，辄流涕焉。","sortOrder":13},
  {"id":"s_work_nvlt_95_14","chapterId":"ch_work_nvlt_95","text":"法顯記曰：迦維羅衛國，從佛生處東行五由旬，有國名藍莫，此國王得佛一分舍利，還歸起塔，塔邊有池，池中有龍，常守護此塔，晝夜供養，乃有群象，以鼻取水洒地，取雜花香而供養，諸國道人來，欲禮拜塔，遇象大怖，依树自翳，見象如法供養，道人太息悲感，即舍大戒，還作沙弥，自挽水平治處所，使得净絜。","sortOrder":14},
  {"id":"s_work_nvlt_95_15","chapterId":"ch_work_nvlt_95","text":"《異苑》曰：會稽張茂，嘗夢大象，以問萬推，曰：君當為大郡，而不能善，夫象者大獸，取其音，獸者守也，象以齒焚其身，後必為人所殺，茂永昌中為吳興太守，值王敦問鼎，執正不移，敦遣沈充殺之。","sortOrder":15},
  {"id":"s_work_nvlt_95_16","chapterId":"ch_work_nvlt_95","text":"【贊】晉郭璞贊曰：象實魁梧，體巨貌诡，肉兼十牛，目不逾豕，望頭如尾，動若丘徙。","sortOrder":16},
  {"id":"s_work_nvlt_95_18","chapterId":"ch_work_nvlt_95","text":"《爾雅》曰：犀似豕，［形似牛，猪頭大腹卑腳，腳有三節，黑色，二角，一在顶，一在鼻。］","sortOrder":18},
  {"id":"s_work_nvlt_95_19","chapterId":"ch_work_nvlt_95","text":"《戰國策》曰：張儀為秦破縱連橫，說楚王，楚王遣車百乘，獻駭雞之犀，夜光之璧於秦王。","sortOrder":19},
  {"id":"s_work_nvlt_95_20","chapterId":"ch_work_nvlt_95","text":"《韓詩外傳》曰：太公使南宮適至義渠，得駭雞犀，以獻紂。","sortOrder":20},
  {"id":"s_work_nvlt_95_21","chapterId":"ch_work_nvlt_95","text":"《漢書》曰：元始二年，黃支國獻犀牛。","sortOrder":21},
  {"id":"s_work_nvlt_95_22","chapterId":"ch_work_nvlt_95","text":"又曰：尉他獻文帝犀角十。","sortOrder":22},
  {"id":"s_work_nvlt_95_23","chapterId":"ch_work_nvlt_95","text":"又曰：乌弋國出犀牛。","sortOrder":23},
  {"id":"s_work_nvlt_95_24","chapterId":"ch_work_nvlt_95","text":"蜀王本紀曰：江水為害，蜀守李冰作石犀五枚，二枚在府中，一枚在市桥下，二在水中，以厭水精，因曰石犀里。","sortOrder":24},
  {"id":"s_work_nvlt_95_25","chapterId":"ch_work_nvlt_95","text":"《抱朴子》曰：通天犀有一白［原訛百，據冯校本改。］理如線者，以盛米，置群雞中，雞欲往啄米，至辄驚却，故南人名為駭雞也，得其角一尺以上，刻為魚而衔以入水，水常為开，方三尺，可得氣息水中，以其角為叉导者，得煮毒藥為湯，以此叉导搅之，皆生白沫，無复毒势。","sortOrder":25},
  {"id":"s_work_nvlt_95_26","chapterId":"ch_work_nvlt_95","text":"劉欣期交州記曰：犀出九德縣，其毛如豕，蹄有三甲，頭如馬，有二角，鼻上角長，額上角短。","sortOrder":26},
  {"id":"s_work_nvlt_95_27","chapterId":"ch_work_nvlt_95","text":"《南州異物志》曰：玄犀處自林麓，食惟棘刺，體兼五肉，或有神異，表靈以角，含精吐烈，望若華燭，置之荒野，禽獸莫觸。","sortOrder":27},
  {"id":"s_work_nvlt_95_28","chapterId":"ch_work_nvlt_95","text":"【贊】晉郭璞犀贊曰：犀之為状，形兼牛豕，力無不傾，吻無不靡，以賄婴灾，因乎角椅。","sortOrder":28},
  {"id":"s_work_nvlt_95_29","chapterId":"ch_work_nvlt_95","text":"【序】晉傅鹹犀鉤序曰：世稱雞駭之犀，聞之父常侍曰：犀之美者有光，雞見影而驚，故曰駭雞，有以此鉤見遺者，乃為之銘。","sortOrder":29},
  {"id":"s_work_nvlt_95_31","chapterId":"ch_work_nvlt_95","text":"《爾雅》曰：兕似牛，［一角，肉重千斤。］","sortOrder":31},
  {"id":"s_work_nvlt_95_32","chapterId":"ch_work_nvlt_95","text":"《說文》曰：兕，如野牛，青皮堅厚，可以為鎧，嶓冢之山，其獸多兕。","sortOrder":32},
  {"id":"s_work_nvlt_95_33","chapterId":"ch_work_nvlt_95","text":"《毛詩》曰：酌彼兕觥。","sortOrder":33},
  {"id":"s_work_nvlt_95_34","chapterId":"ch_work_nvlt_95","text":"《戰國策》曰：楚王遊於雲夢，有狂兕忽至，王弯弓而射之，應發而殪，仰天而叹曰：樂矣今日之遊，萬歲千秋之後，誰與樂此。","sortOrder":34},
  {"id":"s_work_nvlt_95_35","chapterId":"ch_work_nvlt_95","text":"《論衡》曰：太師尚父，為周司馬，將師伐紂，到孟津之上，杖鉞把旄，號其眾曰仓兕，夫仓兕水中之獸也，善覆人舡，因神以化，令汝急渡。","sortOrder":35},
  {"id":"s_work_nvlt_95_36","chapterId":"ch_work_nvlt_95","text":"【贊】晉郭璞山海圖贊曰：兕惟壮獸，似牛青黑，力無不傾，自焚以革，皮充武備，角助文德。","sortOrder":36},
  {"id":"s_work_nvlt_95_38","chapterId":"ch_work_nvlt_95","text":"《爾雅》曰：駮如馬，倨牙，食虎豹。","sortOrder":38},
  {"id":"s_work_nvlt_95_39","chapterId":"ch_work_nvlt_95","text":"《山海經》曰：中曲之山，有獸焉，其状如馬，而白身黑尾，一角，虎牙爪，音如鼓，其名曰駮，是食豹，可以御兵。","sortOrder":39},
  {"id":"s_work_nvlt_95_40","chapterId":"ch_work_nvlt_95","text":"【贊】晉郭璞贊曰：駮惟馬類，實畜之英，驤首騰旄，噓天雷鳴，氣無不凌，吞虎辟兵。","sortOrder":40},
  {"id":"s_work_nvlt_95_42","chapterId":"ch_work_nvlt_95","text":"《爾雅》曰：貔白狐，其子豰，［呼鹿反，一名執夷。］","sortOrder":42},
  {"id":"s_work_nvlt_95_43","chapterId":"ch_work_nvlt_95","text":"《說文》曰：貔，豹屬，出貉國。","sortOrder":43},
  {"id":"s_work_nvlt_95_44","chapterId":"ch_work_nvlt_95","text":"《尚書》曰：如虎如貔。","sortOrder":44},
  {"id":"s_work_nvlt_95_45","chapterId":"ch_work_nvlt_95","text":"《禮記》曰：前有挚獸，則載貔貅。","sortOrder":45},
  {"id":"s_work_nvlt_95_46","chapterId":"ch_work_nvlt_95","text":"《毛詩》曰：獻其貔皮，赤豹黃羆。","sortOrder":46},
  {"id":"s_work_nvlt_95_47","chapterId":"ch_work_nvlt_95","text":"【贊】晉郭璞貔贊曰：書稱猛士，如虎如貔，貔蓋豹屬，亦曰執夷，白狐之雲，自是而非。","sortOrder":47},
  {"id":"s_work_nvlt_95_49","chapterId":"ch_work_nvlt_95","text":"《說文》曰：熊獸似豕，山居冬蟄。","sortOrder":49},
  {"id":"s_work_nvlt_95_50","chapterId":"ch_work_nvlt_95","text":"《本草經》曰：熊脂一名熊白，味甘，微溫無毒，止風痺。","sortOrder":50},
  {"id":"s_work_nvlt_95_51","chapterId":"ch_work_nvlt_95","text":"《六韜》曰：文王囚羑里，散宜生得黃熊而獻之於紂。","sortOrder":51},
  {"id":"s_work_nvlt_95_52","chapterId":"ch_work_nvlt_95","text":"《周書》曰：成王時，不屠國獻青熊。","sortOrder":52},
  {"id":"s_work_nvlt_95_53","chapterId":"ch_work_nvlt_95","text":"《毛詩》曰：維熊維羆，男子之祥。","sortOrder":53},
  {"id":"s_work_nvlt_95_54","chapterId":"ch_work_nvlt_95","text":"《詩義疏》曰：熊能攀緣上高树，見人則顛倒投地而下，冬入穴而蟄，始春而出。","sortOrder":54},
  {"id":"s_work_nvlt_95_55","chapterId":"ch_work_nvlt_95","text":"《左傳》曰：晉靈公使宰夫胹熊蹯，不熟，殺之，寘諸畚，載以過朝。","sortOrder":55},
  {"id":"s_work_nvlt_95_56","chapterId":"ch_work_nvlt_95","text":"又曰：鄭子產聘於晉，晉侯有疾，韓宣子曰：寡君寢疾，於今三月，併走群望，有加而無瘳，今夢黃熊入於寢門，其何厲鬼也，對曰：以君之明，子為大政，其何厲之有，昔尧殛鯀於羽山，其神化為黃熊，實為夏郊，三代祀之，晉為盟主，其或者未之祀乎，韓子祀夏，晉侯有間。","sortOrder":56},
  {"id":"s_work_nvlt_95_57","chapterId":"ch_work_nvlt_95","text":"《孟子》曰：生［按生字衍。］魚我所欲，熊掌亦我所欲，我所欲二者不兼，舍魚取熊掌，義者我欲，生亦我欲，二者不得兼，舍生取義。","sortOrder":57},
  {"id":"s_work_nvlt_95_58","chapterId":"ch_work_nvlt_95","text":"《史記》曰：趙簡子病，不知人，五日寤，而曰：我之帝所，見一熊，欲援我，帝命我射之，中熊，熊死，後有當道者，曰：帝令主君滅二卿，熊其祖也。","sortOrder":58},
  {"id":"s_work_nvlt_95_59","chapterId":"ch_work_nvlt_95","text":"《漢書》曰：孝元帝冯昭儀，上幸虎圈斗獸，後宮皆坐，熊出圈，攀槛欲上殿，昭儀乃當熊而立，及左右格殺熊，上問人情驚懼，汝何故前當，昭儀對曰：夫猛獸得人而止，妾恐熊至御座，故身當之耳，帝嗟叹，以此倍敬重之。","sortOrder":59},
  {"id":"s_work_nvlt_95_60","chapterId":"ch_work_nvlt_95","text":"《東觀漢記》曰：安帝永初九年，永昌獻象牙熊子。","sortOrder":60},
  {"id":"s_work_nvlt_95_61","chapterId":"ch_work_nvlt_95","text":"建武故事曰：鹹和七年，左右啟以米飴熊，上曰：此無益而費於穀，且是惡獸，所不宜畜，使遣打殺，以肉賜左右直人。","sortOrder":61},
  {"id":"s_work_nvlt_95_62","chapterId":"ch_work_nvlt_95","text":"《抱朴子》曰：玉策記稱，熊寿五百，五百歲則能化。","sortOrder":62},
  {"id":"s_work_nvlt_95_63","chapterId":"ch_work_nvlt_95","text":"《續搜神記》曰：晉升平中，有人入山射鹿，忽墮一坎，窅然深絕，內有數頭熊子，須臾，有一大熊來入，瞪视此人，人謂必害己，良久，出藏得果栗，分與諸子，末後作一分，以著此人前，人飢久，於是冒死取啖之，既轉相狎習，熊每旦觅食果還，辄分此人，此人賴以支命，後熊子大，其母一一負將出，子既盡，人分死坎中，窮無出路，熊母尋复還入，坐人邊，人解其意，便抱熊之足，於是跳出，遂得無他。","sortOrder":63},
  {"id":"s_work_nvlt_95_64","chapterId":"ch_work_nvlt_95","text":"《異苑》曰：邵陵高平黃秀，以元嘉三年入山，經月不還，其兒根生尋觅，不［不字疑衍。］見秀蹲空树中，從頭至腰，毛色如熊，問其何故，答曰：天譴如此，汝但自去，生哀恸而歸，逾年，伐山人見形盡為熊矣。","sortOrder":64},
  {"id":"s_work_nvlt_95_65","chapterId":"ch_work_nvlt_95","text":"又曰：熊獸藏於山穴，穴里不得見秽及复［《太平御覽》九百零八作傷。］殘，則合［御覽作舍。］穴自死，人欲捕者，便令一人臥其藏內，餘伴執杖，隱在崖侧，熊辄共舆出人，不使傷撻，傍人仍將騁其矛。又有居大树孔中，東土呼熊為子路，以物击树，雲子路可起，於是便下，不呼則不動也。","sortOrder":65},
  {"id":"s_work_nvlt_95_66","chapterId":"ch_work_nvlt_95","text":"【啟】梁劉孝威謝熊白啟，竊以馆有射熊之名，台無走狗之號，上林絕胡人之搏，禁地無張京之犯，而突出羽川，來攀御槛，光逾厚璧，殆惑朱公之价，色麗燭銀，將堪穆王之寶。","sortOrder":66},
  {"id":"s_work_nvlt_95_68","chapterId":"ch_work_nvlt_95","text":"《爾雅》曰：鹿牡麀，其子麛，其跡速，絕有力{鹿弁}，肩。","sortOrder":68},
  {"id":"s_work_nvlt_95_69","chapterId":"ch_work_nvlt_95","text":"《毛詩》曰：野有死鹿。","sortOrder":69},
  {"id":"s_work_nvlt_95_70","chapterId":"ch_work_nvlt_95","text":"又曰：鹿鳴，宴嘉賓也，呦呦鹿鳴，食野之萍。","sortOrder":70},
  {"id":"s_work_nvlt_95_71","chapterId":"ch_work_nvlt_95","text":"《國語》曰：周穆王征犬戎，得四白鹿。","sortOrder":71},
  {"id":"s_work_nvlt_95_72","chapterId":"ch_work_nvlt_95","text":"《穆天子傳》曰：天子賜曹奴之人，黃金之鹿。","sortOrder":72},
  {"id":"s_work_nvlt_95_73","chapterId":"ch_work_nvlt_95","text":"又曰：天子射鹿於林中。","sortOrder":73},
  {"id":"s_work_nvlt_95_74","chapterId":"ch_work_nvlt_95","text":"《韓子》曰：夫馬似鹿者千金。","sortOrder":74},
  {"id":"s_work_nvlt_95_75","chapterId":"ch_work_nvlt_95","text":"《史記》曰：趙高欲為亂，恐群臣不聽，乃先設验，持鹿於二世，曰：馬也，二世笑曰：丞相誤耶，謂鹿為馬，問左右，或言馬以阿趙高，或言鹿者，高因陰中言鹿者以法。","sortOrder":75},
  {"id":"s_work_nvlt_95_76","chapterId":"ch_work_nvlt_95","text":"又曰：高祖詔捕蒯通至，問曰：若教淮陰侯反乎，對曰：然，秦失其鹿，天下共逐之，狗固吠非其主。","sortOrder":76},
  {"id":"s_work_nvlt_95_77","chapterId":"ch_work_nvlt_95","text":"《東方朔傳》曰：武帝時，有殺上林鹿者，下有司收殺之，朔時在旁曰：是故當死者三，陛下以鹿殺人，一當死，天下聞陛下重鹿賤人，二當死，匈奴有急，須鹿觸之，三當死。","sortOrder":77},
  {"id":"s_work_nvlt_95_78","chapterId":"ch_work_nvlt_95","text":"《列仙傳》曰：蘇躭與眾兒俱戲獵，常騎鹿，鹿形如常鹿，遇崄絕之處，皆能超越，眾兒問曰：何得此鹿騎而異常鹿耶，答曰：龍也。","sortOrder":78},
  {"id":"s_work_nvlt_95_79","chapterId":"ch_work_nvlt_95","text":"謝承《後漢書》曰：鄭弘為臨淮太守，行春，有兩白鹿隨車，俠轂而行，弘怪問主簿黃國，鹿為吉凶，國拜贺曰：聞三公車辎畫作鹿，明府當為宰相，弘果為太尉。","sortOrder":79},
  {"id":"s_work_nvlt_95_80","chapterId":"ch_work_nvlt_95","text":"范晔《後漢書》曰：雲南縣有神鹿，兩頭，能食毒草，［華陽國志雲，此鹿出雲南雄仓山。］","sortOrder":80},
  {"id":"s_work_nvlt_95_81","chapterId":"ch_work_nvlt_95","text":"《古今註》曰：明帝永平中，三角鹿出江陵，孝和帝永元中，豫章徐汗，得白鹿，高丈九寸。","sortOrder":81},
  {"id":"s_work_nvlt_95_82","chapterId":"ch_work_nvlt_95","text":"《三辅决錄》曰：辛繕，字公文，少治春秋詩易，隱居弘農華陰，弟子受業者六百餘人，所居旁有白鹿，甚馴，不畏人。","sortOrder":82},
  {"id":"s_work_nvlt_95_83","chapterId":"ch_work_nvlt_95","text":"《魏略》曰：成公英先隨韓約，後降太祖，從行出獵，有三鹿走過公前，命英射之，三發三中，皆應絃而倒。","sortOrder":83},
  {"id":"s_work_nvlt_95_84","chapterId":"ch_work_nvlt_95","text":"《魏志》曰：文帝獵，失鹿，帝大怒，據胡床，拔刀收吏，將欲斬之，蘇則諫，乃止。","sortOrder":84},
  {"id":"s_work_nvlt_95_85","chapterId":"ch_work_nvlt_95","text":"魏末傳曰：初明帝為平原王，王母甄後妒，文帝殺之，故不立為太子，嘗從帝獵，見鹿子母，帝射殺鹿母，語明帝射其子，對曰：陛下既已殺其母，臣不忍复殺其子，因涕泣，帝放弓矢叹曰：此語一何痛哉，由是帝立太子意定矣。","sortOrder":85},
  {"id":"s_work_nvlt_95_86","chapterId":"ch_work_nvlt_95","text":"《抱朴子》曰：鹿寿千歲，滿五百歲則色白。","sortOrder":86},
  {"id":"s_work_nvlt_95_87","chapterId":"ch_work_nvlt_95","text":"《神仙傳》曰：魯女生者，餌術絕穀，入華山，後故人逢女生，乘白鹿，從玉女數十人。","sortOrder":87},
  {"id":"s_work_nvlt_95_88","chapterId":"ch_work_nvlt_95","text":"又曰：沈羲嘗於道路逢白鹿車一乘，龍車一乘，從數十人騎，迎羲。","sortOrder":88},
  {"id":"s_work_nvlt_95_89","chapterId":"ch_work_nvlt_95","text":"《廣州先賢傳》曰：丁茂，字仲慮，交阯人也，至孝，母終，負土治冢，列植松柏，白鹿遊乎左右。","sortOrder":89},
  {"id":"s_work_nvlt_95_90","chapterId":"ch_work_nvlt_95","text":"《瀨乡記》曰：老子乘白鹿，下讬於李母也。","sortOrder":90},
  {"id":"s_work_nvlt_95_91","chapterId":"ch_work_nvlt_95","text":"【序】袁山松白鹿詩序曰：荆門山臨江，皆絕壁峭峙，壁立百餘丈，亘帶激流，禽獸所不能履，北岸有一白鹿，鹿泅過江，行人見之，乘刀競逐，謂至山下必得鹿，忽然若飛，超岡而去，於今此壁謂之白鹿。","sortOrder":91},
  {"id":"s_work_nvlt_95_92","chapterId":"ch_work_nvlt_95","text":"上［疑當作古，按本詩系節古樂府乌生八九子四句，全詩見宋書二十一樂志。］詩曰：白鹿乃在上林西苑中，射工尚复得白鹿哺唶之，黃鵠摩天極高飛，後宮尚得烹煮之。","sortOrder":92},
  {"id":"s_work_nvlt_95_93","chapterId":"ch_work_nvlt_95","text":"【表】魏陳王曹植獵表曰：於七月伏鹿鳴塵，四月五月射雉之际，此正樂獵之時。","sortOrder":93},
  {"id":"s_work_nvlt_95_94","chapterId":"ch_work_nvlt_95","text":"晉殷仲堪上白鹿表曰：巴陵縣清水山，得白鹿一頭，白者正色，鹿者景福嘉義。","sortOrder":94},
  {"id":"s_work_nvlt_95_95","chapterId":"ch_work_nvlt_95","text":"【箋】宋孝武帝在彭城參佐慶獲白鹿箋曰：伏承獲白鹿於彭城之東山，皓质玉映，育性馴和。","sortOrder":95},
  {"id":"s_work_nvlt_95_97","chapterId":"ch_work_nvlt_95","text":"《春秋運斗枢》曰：枢星散為獐。","sortOrder":97},
  {"id":"s_work_nvlt_95_98","chapterId":"ch_work_nvlt_95","text":"《說文》曰：麕，獐也。","sortOrder":98},
  {"id":"s_work_nvlt_95_99","chapterId":"ch_work_nvlt_95","text":"《爾雅》曰：麕牝麜，栗音，其子麆，助音，其跡解，絕有力豜。［育音，○《太平御覽》九百零七作肩。］","sortOrder":99},
  {"id":"s_work_nvlt_95_100","chapterId":"ch_work_nvlt_95","text":"《毛詩》曰：野有死麕，惡無禮也。","sortOrder":100},
  {"id":"s_work_nvlt_95_101","chapterId":"ch_work_nvlt_95","text":"《穆天子傳》曰：天子賜曹奴之鹿，白銀之麕，［今地中得玉勝金大，即古路夷狄质，○穆天子傳二金大作金犭苟，疑此當作犬。又，穆天子傳路作賂，质作货。］","sortOrder":101},
  {"id":"s_work_nvlt_95_102","chapterId":"ch_work_nvlt_95","text":"《呂氏春秋》曰：使麕疾走，馬弗及也，而得之者，時顧也。","sortOrder":102},
  {"id":"s_work_nvlt_95_103","chapterId":"ch_work_nvlt_95","text":"建武故事曰：鹹和六年，計貢合集於樂堂，有野麕走至堂前，左右逐之，於池中而獲之焉。","sortOrder":103},
  {"id":"s_work_nvlt_95_104","chapterId":"ch_work_nvlt_95","text":"《論衡》曰：都尉王子鳳時，麕入府中，其後遷為丹陽太守。","sortOrder":104},
  {"id":"s_work_nvlt_95_105","chapterId":"ch_work_nvlt_95","text":"晉《起居註》曰：鹹寧中，白獐見魏郡，後諸州各送白獐。","sortOrder":105},
  {"id":"s_work_nvlt_95_106","chapterId":"ch_work_nvlt_95","text":"《晉中興書》曰：中興所在獻白麕。","sortOrder":106},
  {"id":"s_work_nvlt_95_107","chapterId":"ch_work_nvlt_95","text":"萧廣濟《孝子傳》曰：萧國遭丧，有鵠遊其庭，至暮而去，獐暮入其門，與犬馬旅，至旦而去。","sortOrder":107},
  {"id":"s_work_nvlt_95_108","chapterId":"ch_work_nvlt_95","text":"【詩】魏文帝詩曰：巾車出鄴宮，校獵東桥津，重罝施密網，罕罼飄如雲，弯弓忽高馳，一發連双麕。","sortOrder":108},
  {"id":"s_work_nvlt_95_109","chapterId":"ch_work_nvlt_95","text":"【表】晉王述上白獐表曰：所領阮藻之江寧縣界，得白獐一頭，毛色絜素於其類，信斯誠之嘉祥也。","sortOrder":109},
  {"id":"s_work_nvlt_95_110","chapterId":"ch_work_nvlt_95","text":"【啟】陳徐陵謝赉麕啟曰：臣昨既陪羽獵，仍宴上林，固謝長卿之文，弥慚子雲之賦，預割鮮禽，已同監浦，頻蒙大脔，更異梁王，詰旦歸來，猶為飽飫，虞衡所獻，复降命恩，賜細君以為歡，非屠門而大嚼。","sortOrder":110},
  {"id":"s_work_nvlt_95_112","chapterId":"ch_work_nvlt_95","text":"《爾雅》曰：兔子嬎，其跡迒，絕有力欣。","sortOrder":112},
  {"id":"s_work_nvlt_95_113","chapterId":"ch_work_nvlt_95","text":"《春秋運斗枢》曰：玉衡星散而為兔。","sortOrder":113},
  {"id":"s_work_nvlt_95_114","chapterId":"ch_work_nvlt_95","text":"又曰：行失瑤光則兔出月，《毛詩》曰：有兔斯首，炰之燔之。","sortOrder":114},
  {"id":"s_work_nvlt_95_115","chapterId":"ch_work_nvlt_95","text":"又曰：肅肅兔罝，施於中逵。","sortOrder":115},
  {"id":"s_work_nvlt_95_116","chapterId":"ch_work_nvlt_95","text":"《周易參同契》曰：燕雀不生鳳，狐兔不乳馬。","sortOrder":116},
  {"id":"s_work_nvlt_95_117","chapterId":"ch_work_nvlt_95","text":"《莊子》曰：蹄者所以在兔，得兔而忘蹄。","sortOrder":117},
  {"id":"s_work_nvlt_95_118","chapterId":"ch_work_nvlt_95","text":"《韓子》曰：宋人有耕者，田中有株，兔走觸，折頸而死，因釋耕守株，冀复得兔，為宋國所笑。","sortOrder":118},
  {"id":"s_work_nvlt_95_119","chapterId":"ch_work_nvlt_95","text":"《史記》曰：李斯出獄，與其中子俱執，顧謂其子曰：吾欲與汝，复牵黃犬，俱出蔡東門，逐狡兔，其可得乎。","sortOrder":119},
  {"id":"s_work_nvlt_95_120","chapterId":"ch_work_nvlt_95","text":"又，范雎謂秦昭王曰：夫以秦而治諸侯，譬若縱韓盧而摶蹇兔也。","sortOrder":120},
  {"id":"s_work_nvlt_95_121","chapterId":"ch_work_nvlt_95","text":"謝承《後漢書》曰：方储幼丧父，負土成墳，种奇树千株，白兔遊其下。","sortOrder":121},
  {"id":"s_work_nvlt_95_122","chapterId":"ch_work_nvlt_95","text":"張璠《漢記》曰：梁冀起兔苑於河南，移檄在所，調發生兔，刻其毛以為識。","sortOrder":122},
  {"id":"s_work_nvlt_95_123","chapterId":"ch_work_nvlt_95","text":"《抱朴子》曰：兔寿千歲，滿五百歲則色白。","sortOrder":123},
  {"id":"s_work_nvlt_95_124","chapterId":"ch_work_nvlt_95","text":"《論衡》曰：儒者言月中有兔，夫月水也，兔在水中則死，夫兔月氣也。","sortOrder":124},
  {"id":"s_work_nvlt_95_125","chapterId":"ch_work_nvlt_95","text":"張衡《靈憲》曰：月者，陰精之宗，積而成獸，象兔蛤。","sortOrder":125},
  {"id":"s_work_nvlt_95_126","chapterId":"ch_work_nvlt_95","text":"【序】晉王廙白兔賦序曰：丞相琅邪王，始受旄節，作镇北方，仁風所被，回面革心，昔周旦翼成，越裳重譯而獻白雉，著在前典，歷代以為美談，今在我王，匡濟皇維，而有白兔之應，可謂重規累矩，不忝先聖也。","sortOrder":126},
  {"id":"s_work_nvlt_95_127","chapterId":"ch_work_nvlt_95","text":"【詩】古歌詩曰：采取神藥山端，白兔捣［《太平御覽》九百零七捣下有成字。］虾蟆丸，奉上陛下一玉柈。","sortOrder":127},
  {"id":"s_work_nvlt_95_128","chapterId":"ch_work_nvlt_95","text":"【頌】張浚白兔頌曰：其毛春素，織毫秋黑，點缀五采，漸染粉墨，蓋久隱時見，應世德也，徐疾備體，達消息也，姿质皓朗，民之則也，被白含文，好無極也，秦失鹿於近郊，晉得兔於遠境。","sortOrder":128},
  {"id":"s_work_nvlt_95_129","chapterId":"ch_work_nvlt_95","text":"【表】晉桓溫贺白兔表曰：臣聞至德通玄，則禎祥降，靈和所感，則異物生，今白兔見於春穀縣，皓质純素，皦然殊觀。","sortOrder":129},
  {"id":"s_work_nvlt_95_130","chapterId":"ch_work_nvlt_95","text":"梁簡文帝上白兔表曰：瑞表丹陵，祥因舊沛，四靈可邁，既验玉衡之精，千歲变采，有符明月之状，豈殊丹岫之羽，不止帝梧，庶比素质之禽，得遊君囿。","sortOrder":130},
  {"id":"s_work_nvlt_95_131","chapterId":"ch_work_nvlt_95","text":"周庾信上白兔表曰：光鮮越雉，色麗秦狐，月德符徵，金精表瑞。","sortOrder":131},
  {"id":"s_work_nvlt_95_133","chapterId":"ch_work_nvlt_95","text":"《山海經》曰：青丘之國，有狐九尾。","sortOrder":133},
  {"id":"s_work_nvlt_95_134","chapterId":"ch_work_nvlt_95","text":"《說文》曰：狐妖獸，鬼所乘也，有三德，其色中和，小前大後，死則丘首，易曰：田獲三狐。","sortOrder":134},
  {"id":"s_work_nvlt_95_135","chapterId":"ch_work_nvlt_95","text":"《毛詩》曰：狐裘逍遙。","sortOrder":135},
  {"id":"s_work_nvlt_95_136","chapterId":"ch_work_nvlt_95","text":"又曰：狐裘豹裒。","sortOrder":136},
  {"id":"s_work_nvlt_95_137","chapterId":"ch_work_nvlt_95","text":"《禮記》曰：天子狐白之裘，諸侯青，卿大夫狐掖。","sortOrder":137},
  {"id":"s_work_nvlt_95_138","chapterId":"ch_work_nvlt_95","text":"《穆天子傳》曰：天子獵於渗泽，得白狐。","sortOrder":138},
  {"id":"s_work_nvlt_95_139","chapterId":"ch_work_nvlt_95","text":"《管子》曰：代出狐白衣之皮裘，狐應陰陽之变，六月而一見，公卿買之，代人忘其難得，喜其貴价，必相率而求之，取此物者，因令齊載金錢買之，代各求狐白皮，代王聞之，果去其農，處山林求狐，二十四月，不得一狐，離支聞而伐之，代王即將其士卒服於齊。","sortOrder":139},
  {"id":"s_work_nvlt_95_140","chapterId":"ch_work_nvlt_95","text":"《慎子》曰：廊廟之材，非一木之枝，狐白之裘，非一狐之皮。","sortOrder":140},
  {"id":"s_work_nvlt_95_141","chapterId":"ch_work_nvlt_95","text":"《韓子》曰：翟人獻狐玄豹之皮於晉文公，文公受皮而叹曰：以皮之美，自為罪也。","sortOrder":141},
  {"id":"s_work_nvlt_95_142","chapterId":"ch_work_nvlt_95","text":"《漢書》曰：陳勝吳廣，次所旁丛祠中，［次人所止處也，丛鬼所冯。］夜構火狐鳴曰：大楚興，陳勝王。","sortOrder":142},
  {"id":"s_work_nvlt_95_143","chapterId":"ch_work_nvlt_95","text":"名山記曰：狐者，先古之淫婦也，其名曰紫，化而為狐，故其怪多自稱阿紫。","sortOrder":143},
  {"id":"s_work_nvlt_95_144","chapterId":"ch_work_nvlt_95","text":"《白虎通》曰：狐死首丘，不忘本也，九德至，則九尾能得其所，子孫繁息，於尾，明後當盛也。","sortOrder":144},
  {"id":"s_work_nvlt_95_145","chapterId":"ch_work_nvlt_95","text":"【贊】晉郭璞九尾狐贊曰：青丘奇獸，九尾之狐，有道祥見，出則衔書，作瑞於周，以摽靈符。","sortOrder":145},
  {"id":"s_work_nvlt_95_147","chapterId":"ch_work_nvlt_95","text":"《山海經》曰：堂庭之山，發爽之山，其上多白猿。","sortOrder":147},
  {"id":"s_work_nvlt_95_148","chapterId":"ch_work_nvlt_95","text":"《呂氏春秋》曰：荆王有神白猿，王自射之，則搏树而熙，使養由基射之，始調弓矯矢，未發，猿擁树而號。","sortOrder":148},
  {"id":"s_work_nvlt_95_149","chapterId":"ch_work_nvlt_95","text":"《淮南子》曰：楚王亡其猿，而林木為之殘。","sortOrder":149},
  {"id":"s_work_nvlt_95_150","chapterId":"ch_work_nvlt_95","text":"《漢書》曰：李廣猿臂善射。","sortOrder":150},
  {"id":"s_work_nvlt_95_151","chapterId":"ch_work_nvlt_95","text":"《吳越春秋》曰：越王問范蠡手戰之術，范蠡曰：臣聞越有處女，國人稱之，原王請問手戰之道，於是王乃請女，女將北見王，道逢老人，自稱袁公，袁公問女，聞子善為劍，原得一觀之，處女曰：妾不敢有所隱也，唯公所试，公即挽林內之竹，似枯槁，未折墮地，女接取其末，袁公操其本而刺處女，處女應即入之，三入，因舉杖击袁公，袁公則飛上树，化為白猿。","sortOrder":151},
  {"id":"s_work_nvlt_95_152","chapterId":"ch_work_nvlt_95","text":"《抱朴子》曰：猿寿五百歲，則变為玃，千歲則变為老人。","sortOrder":152},
  {"id":"s_work_nvlt_95_153","chapterId":"ch_work_nvlt_95","text":"又曰：周穆王南征，一軍皆化，君子為猿為鶴，小人為虫為沙。","sortOrder":153},
  {"id":"s_work_nvlt_95_154","chapterId":"ch_work_nvlt_95","text":"張載論曰：白猿玄豹，藏於櫺槛，何以知其接垂條於千仞。","sortOrder":154},
  {"id":"s_work_nvlt_95_155","chapterId":"ch_work_nvlt_95","text":"宜都山川記曰：峡中猿鳴至清，諸山穀傳其响，泠泠不絕，行者歌之曰：巴東三峡猿鳴悲，猿鳴三聲淚霑衣。","sortOrder":155},
  {"id":"s_work_nvlt_95_156","chapterId":"ch_work_nvlt_95","text":"【詩】梁沈約石塘瀨聽猿詩曰：噭々夜猿鳴，溶溶晨霧合，不知聲遠近，唯見山重沓，既歡東嶺唱，复佇西巖答。","sortOrder":156},
  {"id":"s_work_nvlt_95_157","chapterId":"ch_work_nvlt_95","text":"陳萧詮賦得夜猿啼詩曰：桂月影才通，猿鳴回入風，隔巖還嘯侣，臨潭自响空，掛藤疑欲飲，吟枝似避弓，別有三聲淚，霑裳竟不窮。","sortOrder":157},
  {"id":"s_work_nvlt_95_158","chapterId":"ch_work_nvlt_95","text":"【賦】晉傅玄猿猴賦曰：餘酒酣耳熱，懽顏未伸，遂戲猴而縱猿，何〈環夂〉畋之驚人，戴以赤幩，襪以朱巾，先裝其面。又丹其唇，扬眉蹙額，若愁若瞋，或長眠而抱把［把字明本無。］勒，或嚄咋而齷龂，或顒仰而踟蹰，或悲嘯而吟呻，既似老公。又類胡兒，或低眩而擇飒，或抵掌而胡舞。","sortOrder":158},
  {"id":"s_work_nvlt_95_159","chapterId":"ch_work_nvlt_95","text":"【贊】晉郭璞白猿贊曰：白猿肆巧，由基撫弓，應眄而號，神有先中，數如循環，其妙無窮。","sortOrder":159},
  {"id":"s_work_nvlt_95_160","chapterId":"ch_work_nvlt_95","text":"◇猕猴","sortOrder":160},
  {"id":"s_work_nvlt_95_161","chapterId":"ch_work_nvlt_95","text":"《楚辭》曰：猕［招隱士猕下有猴字。］兮熊羆，慕類兮以悲。","sortOrder":161},
  {"id":"s_work_nvlt_95_162","chapterId":"ch_work_nvlt_95","text":"《韓子》曰：燕王徵巧術人，請以棘刺之端為母猴，母猴成，巧人曰：人主欲觀之，必半歲不入宮，不飲酒食肉，雨霁日出，视之晏陰之間，而刺之之母猴乃可見也，燕王曰：養之，不能觀也。","sortOrder":162},
  {"id":"s_work_nvlt_95_163","chapterId":"ch_work_nvlt_95","text":"《漢書》曰：韓生勸項羽都關中，羽曰：吾聞富貴不還故乡，如衣錦夜行，乃燒宮室，都彭城，韓生曰：人言楚人沐猴而冠，果然。","sortOrder":163},
  {"id":"s_work_nvlt_95_164","chapterId":"ch_work_nvlt_95","text":"又曰：長信少府檀長卿，為沐猴與狗斗，蓋宽饒奏免之。","sortOrder":164},
  {"id":"s_work_nvlt_95_165","chapterId":"ch_work_nvlt_95","text":"【賦】後漢王延寿王孫賦曰：原天地之造化，實神伟之屈奇，道玄微以密妙，信無物而弗為，有王孫之狡獸，形陋觀而丑儀，顏状類乎老公，軀體似乎小兒，眼睚〈目禺〉以〈月穴〉恤，视〈目戢〉睫以〈目夬〉睳，鼻〈鼻圭〉齁以〈鼻及〉〈鼻夹〉，耳聿役以適知。口嗛呥以〈齒佥〉〈齒臽〉，唇〈南皮〉〈口習〉以形〈开皃〉，齒崖崖以齴々。嚼〈口任〉囃而囁唲，储糧食於兩頰，稍委输於胃脾，踡菟蹲而狗踞。聲歷〈口鹿〉而喔咿，或嗝嗝而〈口壳〉々。又〈口適〉嗅其若啼，緣百仞之高木，攀窈褭之長枝，背牢落之峻壑，臨不测之幽谿，尋柯條以宛轉，或捉腐而登危，或犀跳而電透，乍瓜懸而瓠垂，歸琐系於庭廄，觀者吸呷而忘疲。","sortOrder":165},
  {"id":"s_work_nvlt_95_166","chapterId":"ch_work_nvlt_95","text":"晉阮籍猕猴賦曰：夫猕猴直其微者也，猶累於下陳，體多似而匪類，貌乖殊而不純，外察慧而無度，故人面而獸身，性偏凌而幹進，似韓非之囚秦，楊眉頞而骤眒，似巧言而伪真，整衣冠而伟服，懷項王之思歸，躭嗜欲而眄视，有長卿之研姿，沐蘭湯而滋秽，匪宋朝之媚人，終嗤弄而處泄，雖近習而不親。","sortOrder":166},
  {"id":"s_work_nvlt_95_167","chapterId":"ch_work_nvlt_95","text":"◇果然","sortOrder":167},
  {"id":"s_work_nvlt_95_168","chapterId":"ch_work_nvlt_95","text":"吳錄，《地理志》曰：九真胥浦縣，有獸名果然，猿狖類也，色青赤有文，居树上，此郡及日南皆有之。","sortOrder":168},
  {"id":"s_work_nvlt_95_169","chapterId":"ch_work_nvlt_95","text":"南方草物状曰：果然獸，生在山林上，民人以弓毒射之，剝取皮，皮文青赤白色，縫相連作席，出九真日南郡。","sortOrder":169},
  {"id":"s_work_nvlt_95_170","chapterId":"ch_work_nvlt_95","text":"《南州異物志》曰：交州以南，有果然獸，其鳴自呼，身如猿，犬面，通有白色，其體不過三尺，而尾長四尺餘，反尾度身，過其頭，视其鼻，仍見兩孔，作［《太平御覽》九百一十作仰。］向天，其毛長，柔細滑泽，色以白為质，黑為文，视如蒼頭鸭，胁邊班文，集十餘皮，可得一蓐，繁文麗好，細厚溫暖。","sortOrder":170},
  {"id":"s_work_nvlt_95_171","chapterId":"ch_work_nvlt_95","text":"【賦】魏鍾毓果然賦曰：果然似猴象猿，黑頰青身，肉非嘉餚，唯皮為珍。","sortOrder":171},
  {"id":"s_work_nvlt_95_172","chapterId":"ch_work_nvlt_95","text":"【啟】梁張缵謝皇太子赉果然褥啟曰：伏以狐裘熊席，徒負舊名，玄豹青犭軍。未能適體，嚴冰在節，朔飆結宇，吹纶愧暖，挟纊慚溫，但勤非伏寢，恩重夜覆，道媿經明，坐叨重席，仰榮俯媿，進退在顏。","sortOrder":172},
  {"id":"s_work_nvlt_95_174","chapterId":"ch_work_nvlt_95","text":"《山海經》曰：有獸人面，名曰狌々。","sortOrder":174},
  {"id":"s_work_nvlt_95_175","chapterId":"ch_work_nvlt_95","text":"又曰：狌々知人名，其為獸，如豕而人面。","sortOrder":175},
  {"id":"s_work_nvlt_95_176","chapterId":"ch_work_nvlt_95","text":"《爾雅》曰：狌狌小而好啼，［今交阯封溪出，状如獾〈犭屯〉，聲似小兒啼。］","sortOrder":176},
  {"id":"s_work_nvlt_95_177","chapterId":"ch_work_nvlt_95","text":"《禮記》曰：狌々能言，不離禽獸。","sortOrder":177},
  {"id":"s_work_nvlt_95_178","chapterId":"ch_work_nvlt_95","text":"《廣志》曰：狌狌似狟，聲如小兒啼，不聞其言，出交阯封溪縣。","sortOrder":178},
  {"id":"s_work_nvlt_95_179","chapterId":"ch_work_nvlt_95","text":"《孫卿子》曰：狌々能言笑，亦二足無尾，而君子啜其羹，食其胾，故人非以二足無毛，以知禮也。","sortOrder":179},
  {"id":"s_work_nvlt_95_180","chapterId":"ch_work_nvlt_95","text":"《呂氏春秋》：伊［《太平御覽》九百零八伊下有尹字。］說曰：肉之美者，狌々之唇。","sortOrder":180},
  {"id":"s_work_nvlt_95_181","chapterId":"ch_work_nvlt_95","text":"《淮南子萬畢術》曰：歸終知來，狌々知往，［歸終，神獸。］","sortOrder":181},
  {"id":"s_work_nvlt_95_182","chapterId":"ch_work_nvlt_95","text":"《括地圖》曰：狌々人面豕身，知人名。","sortOrder":182},
  {"id":"s_work_nvlt_95_183","chapterId":"ch_work_nvlt_95","text":"《蜀志》曰：封溪縣有獸，曰狌々，體似猪，面似人，音作小兒啼聲，既能人語。又知人名，人以酒取之，狌々覺，初蹔嘗之，得其味甘而飲之，終見羁纓也。","sortOrder":183},
  {"id":"s_work_nvlt_95_184","chapterId":"ch_work_nvlt_95","text":"《華陽國志》曰：永昌郡有狌々，能言，其血可以染朱罽。","sortOrder":184},
  {"id":"s_work_nvlt_95_185","chapterId":"ch_work_nvlt_95","text":"南方草物状曰：狌々之獸，生在野，状如〈犭屯〉子，民人捕取，交阯武平興古有之。","sortOrder":185},
  {"id":"s_work_nvlt_95_186","chapterId":"ch_work_nvlt_95","text":"【贊】晉郭璞狌々贊曰：能言之獸，是謂猩猩，厥状似猴，號音若嘤，自然知往，頗識物情。","sortOrder":186},
  {"id":"s_work_nvlt_95_188","chapterId":"ch_work_nvlt_95","text":"《說文》曰：貂，鼠屬也，而大，黃黑，出丁零國。","sortOrder":188},
  {"id":"s_work_nvlt_95_189","chapterId":"ch_work_nvlt_95","text":"《廣志》曰：貂出扶餘挹娄。","sortOrder":189},
  {"id":"s_work_nvlt_95_190","chapterId":"ch_work_nvlt_95","text":"《東觀漢記》曰：建武二十五年，乌桓獻貂豹皮，詣闕朝贺。","sortOrder":190},
  {"id":"s_work_nvlt_95_191","chapterId":"ch_work_nvlt_95","text":"《魏略》曰：扶餘國出貂豽，［奴骨反。］","sortOrder":191},
  {"id":"s_work_nvlt_95_192","chapterId":"ch_work_nvlt_95","text":"魏書曰：鮮卑有貂鼲子，皮毛柔软，故天下為名裘。","sortOrder":192},
  {"id":"s_work_nvlt_95_193","chapterId":"ch_work_nvlt_95","text":"《魏志》曰：乌丸傳，挹娄國出好貂，今所謂挹娄貂是也。","sortOrder":193},
  {"id":"s_work_nvlt_95_194","chapterId":"ch_work_nvlt_95","text":"《江表傳》曰：遼東太守，遣使詣孫權，送貂皮千枚，欲舉國歸吳。","sortOrder":194},
  {"id":"s_work_nvlt_95_195","chapterId":"ch_work_nvlt_95","text":"【啟】梁簡文謝敕赉貂坐褥席啟曰：東瀛美毳，不著馬彪之儀，北朔文茵，豈問張敞所記，陰炭既重，寒井猶冰，特降殊私，溫華曲被，雖狐白千金，織成千种，李頒漢被，楊降曹氈，不足以仿佛洪慈，連類聖泽。","sortOrder":195},
  {"id":"s_work_nvlt_95_197","chapterId":"ch_work_nvlt_95","text":"《爾雅》曰：鼢鼠，［墳，地中行者。］鼸鼠，鼷鼠，［有毒，螫毒。］鼶鼠，［斯。］鼬鼠，［似龂，赤黃色，大尾，啖鼠，江東呼鼪鼠。］鼩鼠，［劬。］鼭鼠，［時。］鼥鼠，吠，鼫鼠，［石，頭似兔，尾有黃色，好在田中，食穀豆。］鼤［問。］鼠，鼨終，鼠，豹文鼮鼠，［漢武時得此鼠，終軍知之，賜帛百疋，文采如豹。］鼯鼠夷〈由鳥〉，［似蝙蝠，肉翅，飛且乳，亦名飛生，音如人食火煙。］","sortOrder":197},
  {"id":"s_work_nvlt_95_198","chapterId":"ch_work_nvlt_95","text":"方言曰：蝙［邊音。］蝠，［福。］自關而東，謂之服翼，或謂之飛鼠，或謂老鼠，或謂之仙鼠，自關而西，秦隴之間，謂蝙蝠，北燕謂之蟔蟙。","sortOrder":198},
  {"id":"s_work_nvlt_95_199","chapterId":"ch_work_nvlt_95","text":"《說文》曰：鼠，穴虫之總名也，象形，凡鼠之屬皆從鼠，鼨鼠出胡地，可作裘，鼫，五伎鼠也，能飛不能上屋，能緣不能窮木，能浮不能渡穀，能穴不能掩身，能走不能先人。","sortOrder":199},
  {"id":"s_work_nvlt_95_200","chapterId":"ch_work_nvlt_95","text":"《易》曰：艮為鼠。","sortOrder":200},
  {"id":"s_work_nvlt_95_201","chapterId":"ch_work_nvlt_95","text":"《毛詩》曰：相鼠，刺無禮也，隆文公正其群臣，而刺在位不承先君之禮儀也，相鼠有皮，人而無儀，人而無儀，不死何為。","sortOrder":201},
  {"id":"s_work_nvlt_95_202","chapterId":"ch_work_nvlt_95","text":"又曰：硕鼠硕鼠，無食我黍。","sortOrder":202},
  {"id":"s_work_nvlt_95_203","chapterId":"ch_work_nvlt_95","text":"《詩義疏》曰：樊光謂即爾雅鼫鼠也，許慎雲，鼫鼠，五伎鼠也，今之河東有硕鼠，大能人立，前［《太平御覽》九百十一前上有交字。］兩腳於頭上跳舞，善鳴，食人禾稼，逐則走入树空中，亦有五伎，或謂雀鼠，其形大，故叙雲石鼠也，魏今河東河北縣也，詩言其方物，宜謂此鼠，非今大鼠。又不食禾苗，本草又謂蝼蛄為石鼠，亦五伎，古今方土名虫鳥，物異名同，故記也。","sortOrder":203},
  {"id":"s_work_nvlt_95_204","chapterId":"ch_work_nvlt_95","text":"《左傳》曰：齊侯將為臧紇田，紇聞之，見齊侯，與之言伐晉，對曰：多則多矣，抑君似鼠，夫鼠晝伏夜動，不穴於寢廟，畏人故也，今君聞晉之亂而伐焉，寧將事之，非鼠而何，乃弗與田。","sortOrder":204},
  {"id":"s_work_nvlt_95_205","chapterId":"ch_work_nvlt_95","text":"《晏子春秋》曰：景公問晏子治國何患，對曰：社鼠者，不可燻，不可灌，君之左右，出賣寒熱，入則比周，此之謂社鼠也。","sortOrder":205},
  {"id":"s_work_nvlt_95_206","chapterId":"ch_work_nvlt_95","text":"尹《文子》曰：鄭人謂玉未理者為璞，周人謂鼠未腊者為璞。","sortOrder":206},
  {"id":"s_work_nvlt_95_207","chapterId":"ch_work_nvlt_95","text":"《莊子》曰：且鳥高飛以避矰弋之患，鼷鼠深穴於神丘之下，以避薰凿之患。","sortOrder":207},
  {"id":"s_work_nvlt_95_208","chapterId":"ch_work_nvlt_95","text":"又曰：惠子相梁，莊子往見之，或謂惠子曰：莊子欲代子相，於是惠子恐，搜於國中，三日三夜，莊子見之曰：南方有鳥，其名鵷雏，子知之乎，夫鵷雏發南海，飛至北海，非梧桐不止，非竹實不食，非醴泉不飲，於是鴟得腐鼠，鵷雏過之，仰而视之曰：哧，今子欲以梁國哧我耶。","sortOrder":208},
  {"id":"s_work_nvlt_95_209","chapterId":"ch_work_nvlt_95","text":"贾誼書雲，鄙諺曰：欲投鼠而忌器，此善喻也，近器尚憚，况貴大臣之近於帝王乎。","sortOrder":209},
  {"id":"s_work_nvlt_95_210","chapterId":"ch_work_nvlt_95","text":"《列子》曰：虞氏者，梁富人也，登高樓，臨大路，設樂陳酒，击博其上，而遊俠相隨行樓下，博者射中而笑，鳶墮腐鼠而中遊俠，遊俠相與語曰：虞氏富久矣，常有輕人之志，乃辱我以腐鼠，請滅其家，夜乃攻於虞氏，大滅之，此謂類而非我，［《太平御覽》九百十一作也。］","sortOrder":210},
  {"id":"s_work_nvlt_95_211","chapterId":"ch_work_nvlt_95","text":"《淮南子萬畢術》曰：狐目狸腦，鼠去，於其穴，被發向北，咒殺巫鼠。","sortOrder":211},
  {"id":"s_work_nvlt_95_212","chapterId":"ch_work_nvlt_95","text":"《史記》曰：李斯少時為乡中吏，見吏舍中鼠食不絜，人犬數驚之，入仓，見鼠食積粟，居大庑下，無人犬之忧，乃叹曰：人賢不肖如鼠，在所自處耳。","sortOrder":212},
  {"id":"s_work_nvlt_95_213","chapterId":"ch_work_nvlt_95","text":"又曰：張湯，杜陵人也，其父為長安丞，出外，湯為兒守舍，而鼠盜肉，其父還怒，乃笞湯，湯掘，遂得盜鼠及餘肉，劾鼠掠治，傳爰書，［謂傳囚也，爰，易也，以此書易验者。］訊鞫論報，併取鼠與肉，具獄磔堂下，其父見之，视其文辭，如老獄吏。","sortOrder":213},
  {"id":"s_work_nvlt_95_214","chapterId":"ch_work_nvlt_95","text":"東方朔神異記曰：北方有曾冰萬里，厚百丈，有蛇奚鼠，在冰下出焉，其形如鼠，食草木，肉重萬斤，可以作脯，食之已熱，其毛長可八尺，可以為蓐，臥之可以却寒，其皮可以蒙鼓，其聲千里，有美尾，可來鼠，［此尾所在，鼠辄入此聚。］","sortOrder":214},
  {"id":"s_work_nvlt_95_215","chapterId":"ch_work_nvlt_95","text":"京房《易飛候》曰：鼠舞國門，厥咎亡，鼠舞於庭，厥咎誅死。","sortOrder":215},
  {"id":"s_work_nvlt_95_216","chapterId":"ch_work_nvlt_95","text":"《漢書》：左冯翊韓延寿，有罪下獄，楊惲上書，訟延寿，郎中丘常謂惲曰：聞君侯訟韓冯翊，當得活，惲曰：事何容易，蛇巠蛇巠者未必全也，我不能自保，真人所謂鼠不容穴，坐衔窭數也。","sortOrder":216},
  {"id":"s_work_nvlt_95_217","chapterId":"ch_work_nvlt_95","text":"又曰：蘇武使匈奴，匈奴徙武北海上無人處，使牧羝羊，羝羊生乳乃歸，武至海上，廪食不至，乃掘野鼠草實而食之。","sortOrder":217},
  {"id":"s_work_nvlt_95_218","chapterId":"ch_work_nvlt_95","text":"《廣志》曰：白猿長尾白腹，［句疑有訛。］善緣登，若家鼠小異者，鼠，［《太平御覽》九百十一鼠上有鼢字。］深目而短尾，苗鼠者，野鼠也，小而短尾，天鼠以皮為裘，今當名其裘為天鹿裘，黃鼠在田野間為群，害穀麥，凡善走，把不得，唯鼠狼能得之。","sortOrder":218},
  {"id":"s_work_nvlt_95_219","chapterId":"ch_work_nvlt_95","text":"窦氏家傳曰：窦攸治《爾雅》舉孝廉為郎，世祖與百寮大會靈台，得鼠，身如豹文。焚之光泽，世祖異之，問群臣莫知，唯攸對曰：名鼮鼠，詔問何以知之，攸曰：見《爾雅》詔案视書，如攸言，賜帛百疋，詔諸侯子弟，從攸受爾雅。","sortOrder":219},
  {"id":"s_work_nvlt_95_220","chapterId":"ch_work_nvlt_95","text":"《魏略》曰：大秦國出辟毒鼠，《魏志》曰：公子仓舒早惠，時軍國多事，用刑嚴重，太祖馬鞍在库，為鼠所齧，库吏懼罪必死，議欲面縛首罪，猶慮不免，冲謂曰：待三日中，然後自歸，冲於是以刀穿单衣，如鼠齧者，谬為失意，貌有愁色，太祖問之，冲對曰：世俗以為鼠齧衣者，其主不吉，今衣見齧，是以忧戚，太祖曰：此妄言耳，無所苦也，俄而库吏以齧鞍聞太祖，太祖笑曰：兒衣在侧尚齧，况馬鞍懸柱乎，一無所問。","sortOrder":220},
  {"id":"s_work_nvlt_95_221","chapterId":"ch_work_nvlt_95","text":"又曰：臧洪傳曰：洪為袁紹所围，糧乏，乃掘鼠而食。","sortOrder":221},
  {"id":"s_work_nvlt_95_222","chapterId":"ch_work_nvlt_95","text":"《博物志》曰：鼠食巴豆三年，重三十斤。","sortOrder":222},
  {"id":"s_work_nvlt_95_223","chapterId":"ch_work_nvlt_95","text":"《列異傳》曰：中山王周南，正始中，為襄邑長，有鼠衣冠出廳事，語曰：爾某日當死，周南不應，至期复出，冠帻絳衣，語曰：爾日中當死，复不應，入，复更出，日［原訛曰：據冯校本改。］適中，鼠曰：周南汝不應，死我，［太平御覽九百十一作我死，此倒。］复何道，遂顛蹶而死，即失衣冠，视如常鼠也。","sortOrder":223},
  {"id":"s_work_nvlt_95_224","chapterId":"ch_work_nvlt_95","text":"《晉陽秋》曰：太興中，衡陽區純作鼠市，四方丈餘，开四門，門有一木人，縱四五鼠於中，欲出門，木人辄以推推之。","sortOrder":224},
  {"id":"s_work_nvlt_95_225","chapterId":"ch_work_nvlt_95","text":"《抱朴子·內篇》曰：玉策記稱，鼠寿三百歲，滿一百歲者則色白，善凭人而卜，名曰仲，能知一年中吉凶，及千里外事也。","sortOrder":225},
  {"id":"s_work_nvlt_95_226","chapterId":"ch_work_nvlt_95","text":"《晉太康地記》曰：鳥鼠山在隴西首陽縣西南，鼠尾短，形如家鼠，入三四尺，鼠在內，鳥在外，為牝牡。","sortOrder":226},
  {"id":"s_work_nvlt_95_227","chapterId":"ch_work_nvlt_95","text":"《梁州記》曰：聟水北聟乡山，有仙人唐公房祠，有一碑，廟北有大坑，碑雲，是其舊宅處，公房舉宅登仙，故為坑焉，山有易腸鼠一月三吐易其腸，束廣微所謂唐鼠者也，［《博物志》曰：唐房升仙，雞狗併去，唯以鼠惡，不將去，鼠悔，一月三出腸也。］","sortOrder":227},
  {"id":"s_work_nvlt_95_228","chapterId":"ch_work_nvlt_95","text":"劉欣期交州記曰：竹鼠如小狗子，食竹根，出封溪縣。","sortOrder":228},
  {"id":"s_work_nvlt_95_229","chapterId":"ch_work_nvlt_95","text":"《秦州記》曰：乞佛虜乾歸，未移抱罕金城，見鼠有數萬頭，將諸小鼠，各衔馬屎，群移而度洮麗二水，悉止抱罕，自是二年而乾歸徙焉。","sortOrder":229},
  {"id":"s_work_nvlt_95_230","chapterId":"ch_work_nvlt_95","text":"《異苑》曰：西域有鼠王國，鼠大如狗，中者如兔，小者如常鼠，頭悉白，然帶以金枷，商估有經過其國，不先祈祀者，則齧人衣裳，世得沙門咒原，便獲無他，眾僧釋道安昔至西方，親見如此，俗諺雲，鼠得死人目精則為王。","sortOrder":230},
  {"id":"s_work_nvlt_95_231","chapterId":"ch_work_nvlt_95","text":"《幽明錄》曰：吳北寺終祚道人，臥斋中，鼠從坎出，言終祚後數日必當死，終祚呼奴，令買犬，鼠雲，亦不畏此也，但令犬入此戶，必死，須臾犬至，果然，終祚乃下聲語其奴曰：明市雇十簷水來，鼠已逆知之，雲止欲水浇取我，我穴周流，無所不至，競日浇灌，了無所獲，密令奴更借三十餘人，鼠雲，吾上屋居，奈我何，至時處在屋上，奴名周，鼠雲，阿周盜二十萬錢叛，後试开库，實如所言也，奴亦叛去，終祚當為商贾，閉其戶而謂鼠曰：汝欲使我富耳，今遠行，勤守吾房中，勿令有所零失也，時桓玄在南州，禁殺牛甚急，終祚載數萬錢，竊買牛皮，還東货之，得二十萬，還室猶閉，一無所失，怪亦絕，遂大富。","sortOrder":231},
  {"id":"s_work_nvlt_95_232","chapterId":"ch_work_nvlt_95","text":"《述異記》曰：宋南谯王劉義宣，镇荆州，府吏蔡鐵善卜，宣射得一白鼠，置函中，乃召鐵，使卜函中何物，謂中者當厚賞，僻即加重罰，鐵兆成，笑曰：具已知矣，公曰：状之，鐵曰：兑色之鼠背明戶，弯弧射之絕左股，鼠孕三雄而兩雌，若不見信，剖腹而立知，公乃使剖鼠腹，皆如鐵言，即賜錢一萬。","sortOrder":232},
  {"id":"s_work_nvlt_95_233","chapterId":"ch_work_nvlt_95","text":"《地鏡圖》曰：黃金之見，為火及白鼠。","sortOrder":233},
  {"id":"s_work_nvlt_95_234","chapterId":"ch_work_nvlt_95","text":"《風角要占》曰：長吏居官厭盜賊法，七月，以生鼠九枚，置籠中，埋子地，秤九百斤土覆坎，深各二尺五寸，筑之合堅固。","sortOrder":234},
  {"id":"s_work_nvlt_95_235","chapterId":"ch_work_nvlt_95","text":"《雜五行書》曰：停部，取停部地土涂竈，水火盜賊不經，涂屋四角，鼠不食蠶，涂仓{朁虫}，鼠不食稻，以塞埳，百日鼠种絕。","sortOrder":235},
  {"id":"s_work_nvlt_95_236","chapterId":"ch_work_nvlt_95","text":"【贊】晉郭璞鼮鼠贊曰：有鼠豹采，厥號為鼮，漢朝莫知，郎中能名，賞以束帛，雅業遂盛。","sortOrder":236},
  {"id":"s_work_nvlt_95_237","chapterId":"ch_work_nvlt_95","text":"又鼯鼠贊曰：鼯之為鼠，食煙栖林，載飛載乳，乍獸乍禽，皮籍孕婦，人為大任。","sortOrder":237},
  {"id":"s_work_nvlt_95_238","chapterId":"ch_work_nvlt_95","text":"又鼷鼠贊曰：小鼠曰鼷，實有螫毒，乃食郊牛，不恭是告，厥譴惟明，徵乎其覺。","sortOrder":238},
  {"id":"s_work_nvlt_95_239","chapterId":"ch_work_nvlt_95","text":"又鼫鼠贊曰：五能之鼠，伎無所執，應氣而化，翻飛鴽集，詩人歌之，無食我粒。","sortOrder":239},
  {"id":"s_work_nvlt_95_240","chapterId":"ch_work_nvlt_95","text":"又鼠贊曰：或以尾翔，或以髯凌，飛鼠鼓翰，儵然皆騰，用無常所，唯神斯凭。","sortOrder":240},
  {"id":"s_work_nvlt_95_241","chapterId":"ch_work_nvlt_95","text":"《藝文類聚》　唐·欧陽詢","sortOrder":241},
  {"id":"s_work_nvlt_96_1","chapterId":"ch_work_nvlt_96","text":"卷九十六鱗介部上","sortOrder":1},
  {"id":"s_work_nvlt_96_2","chapterId":"ch_work_nvlt_96","text":"○龍蛟蛇龟鱉魚","sortOrder":2},
  {"id":"s_work_nvlt_96_4","chapterId":"ch_work_nvlt_96","text":"《說文》曰：龍，鱗虫之長，春分而登天，秋分而入川。","sortOrder":4},
  {"id":"s_work_nvlt_96_5","chapterId":"ch_work_nvlt_96","text":"《廣雅》曰：有鱗曰蛟龍，有翼曰應龍，有角曰虬龍，無角曰螭龍。","sortOrder":5},
  {"id":"s_work_nvlt_96_6","chapterId":"ch_work_nvlt_96","text":"《山海經》曰：大樂之野，夏後啟於此乘兩龍。","sortOrder":6},
  {"id":"s_work_nvlt_96_7","chapterId":"ch_work_nvlt_96","text":"又曰：鍾山之神，名曰燭龍，视為晝，暝為夜，身長三千里。","sortOrder":7},
  {"id":"s_work_nvlt_96_8","chapterId":"ch_work_nvlt_96","text":"《易》曰：雲行雨施，品物流形，時乘六龍以御天，初九，潛龍勿用，象曰：陽在下也，九二，見龍在田，利見大人，象曰：德施普也，九五，飛龍在天，大人造也。","sortOrder":8},
  {"id":"s_work_nvlt_96_9","chapterId":"ch_work_nvlt_96","text":"又曰：龍戰於野，其血玄黃。","sortOrder":9},
  {"id":"s_work_nvlt_96_10","chapterId":"ch_work_nvlt_96","text":"《左傳》曰：秋，龍見於絳郊，魏獻子問於蔡墨曰：吾聞之，虫莫智於龍，以其不生得也，對曰：人實不知，非龍實智，古者畜龍，故國有豢龍氏，有御龍氏，昔有飂叔安，［飂，古國名，叔安其君名。］有裔子曰董父，實甚好龍，能求其嗜欲，以飲食之，帝舜賜姓曰董，氏曰豢龍，及有夏孔甲，扰於有帝，帝賜之乘龍，河漢各二，有劉累者，能飲食龍，夏後賜氏曰御龍，今水官弃矣，故龍不生得。","sortOrder":10},
  {"id":"s_work_nvlt_96_11","chapterId":"ch_work_nvlt_96","text":"又曰：鄭大水，龍斗於時門之外洧淵，國人請禜焉，子產弗許，曰：我斗，龍不我觌也，龍斗，我獨何觌焉，攘之則彼其室也，吾無求於龍，龍亦無求於我，乃止。","sortOrder":11},
  {"id":"s_work_nvlt_96_12","chapterId":"ch_work_nvlt_96","text":"《河圖》曰：黃金千歲生黃龍，青金千歲生青龍，赤白龍，［句有脱文。］玄金千歲生玄龍。","sortOrder":12},
  {"id":"s_work_nvlt_96_13","chapterId":"ch_work_nvlt_96","text":"《莊子》曰：朱伻漫學屠龍於支離益，殫千金，技成而無所用其巧。","sortOrder":13},
  {"id":"s_work_nvlt_96_14","chapterId":"ch_work_nvlt_96","text":"又曰：子張見魯哀公，不禮焉，去曰：君之好士也，有似葉公子高之好龍，雕文畫之，於是天龍聞而示之，窥頭於牖，拖尾於堂，葉公見之，失其魂魄，五色無主，是葉公非好龍也，好夫似龍非龍也，今君非好士也，好夫似士者。","sortOrder":14},
  {"id":"s_work_nvlt_96_15","chapterId":"ch_work_nvlt_96","text":"又曰：孔子見老聃歸，三日不談，弟子問曰：夫子見老聃何規哉，子曰：人用意如飛鸿者，為弓弩射之，如遊鹿者，走狗而逐之，若遊魚者，釣繳以投之，吾今見龍，合而成體，散而成章，餘口張不能吸，舌出不能言。","sortOrder":15},
  {"id":"s_work_nvlt_96_16","chapterId":"ch_work_nvlt_96","text":"又曰：河上有家貧窮，持緯萧而食者，子没川，得千金珠，謂其子，取石來鍛之，夫千金之珠，必在九重之泉，驪龍頷下，若能得珠者，遭其睡也，如使驪龍寤，子尚奚微之有哉。","sortOrder":16},
  {"id":"s_work_nvlt_96_17","chapterId":"ch_work_nvlt_96","text":"《楚辭》曰：神龍失水而陆居，為蝼蚁之所裁。","sortOrder":17},
  {"id":"s_work_nvlt_96_18","chapterId":"ch_work_nvlt_96","text":"《孫卿子》曰：積水成川，蛟龍生焉。","sortOrder":18},
  {"id":"s_work_nvlt_96_19","chapterId":"ch_work_nvlt_96","text":"《呂氏春秋》曰：晉文公反國，介子推不肯受賞，自為賦詩曰：有龍於飛，周遍天下，五蛇從之，為之承辅，龍反其乡，既得其所，四蛇從之，得其露雨，一蛇羞之，槁死中野。","sortOrder":19},
  {"id":"s_work_nvlt_96_20","chapterId":"ch_work_nvlt_96","text":"括地圖曰：禹誅防風氏，夏後德盛，二龍降之，禹使范氏御之以行，經南方，防風神見禹怒，射之，有迅雷，二龍升去，神懼，以刃自貫其心而死，禹哀之，瘞以不死草，皆生，是名穿焜國。","sortOrder":20},
  {"id":"s_work_nvlt_96_21","chapterId":"ch_work_nvlt_96","text":"又曰：龍池之山，四方高，中央有池，方七百里，群龍居之，多五花树，群龍食之。","sortOrder":21},
  {"id":"s_work_nvlt_96_22","chapterId":"ch_work_nvlt_96","text":"又曰：崑崙山之弱水，非乘龍不得至。","sortOrder":22},
  {"id":"s_work_nvlt_96_23","chapterId":"ch_work_nvlt_96","text":"《淮南子》曰：龍舉而景雲屬。","sortOrder":23},
  {"id":"s_work_nvlt_96_24","chapterId":"ch_work_nvlt_96","text":"公孫弘答東方朔書曰：譬猶龍之未升，與魚鱉為伍，及其升天，鱗不可睹。","sortOrder":24},
  {"id":"s_work_nvlt_96_25","chapterId":"ch_work_nvlt_96","text":"《列仙傳》曰：陵陽子明好釣，於溪得白龍子，解鉤放之，後得白魚，腹中有書，教子明服食，遂采五石脂服之，三年，白龍來迎，止龍陽山上百餘年。","sortOrder":25},
  {"id":"s_work_nvlt_96_26","chapterId":"ch_work_nvlt_96","text":"《說苑》曰：吳王欲從民飲酒，子胥諫曰：不可，昔日白龍下清泠之淵，化為魚，漁者豫且，射中其目，白龍上訴天帝，天帝曰：當是之時，若安置而形，對曰：我化為魚，固人之所射也，豫且何罪，今君弃萬乘之位，而從布衣之士飲酒，臣恐有豫且之患，王乃止。","sortOrder":26},
  {"id":"s_work_nvlt_96_27","chapterId":"ch_work_nvlt_96","text":"《博物志》曰：龍肉以醯渍之，則文章生。","sortOrder":27},
  {"id":"s_work_nvlt_96_28","chapterId":"ch_work_nvlt_96","text":"《抱朴子》曰：案使者甘宗所奏西域事雲，外國方士能神咒者，臨川禹步吹氣，龍即浮出，初出乃長十數丈，方士吹之，一吹則龍辄一縮，至長數寸，乃取著壶中，以少水養之，外國常患旱灾，於是方士聞有旱處，便赍龍往賣之，一龍直金數十斤，舉國會斂以雇之，直畢，乃發壶出龍，著淵中，因复禹步吹之，長數十丈，須臾而雨四集矣。","sortOrder":28},
  {"id":"s_work_nvlt_96_29","chapterId":"ch_work_nvlt_96","text":"齊地記曰：平昌城有井，與荆水通，有神龍出入焉，故名龍城。","sortOrder":29},
  {"id":"s_work_nvlt_96_30","chapterId":"ch_work_nvlt_96","text":"外國事曰：毗呵羅寺有神龍，住米仓中，奴取米，龍辄却後，奴若長取米，龍不與，仓中米若盡，奴向龍拜，仓即盈溢。","sortOrder":30},
  {"id":"s_work_nvlt_96_31","chapterId":"ch_work_nvlt_96","text":"辛氏《三秦記》曰：河津一名龍門，大魚集龍門下數千，不得上，上者為龍，不上者，［句有脱文。］故雲曝鰓龍門。","sortOrder":31},
  {"id":"s_work_nvlt_96_32","chapterId":"ch_work_nvlt_96","text":"又曰：龍首山長六十里，頭入渭水，尾達樊川，頭高二十丈，尾漸下，高五六丈，雲昔有黑龍，從山南出，飲渭水，其行道成土山，故因以為名。","sortOrder":32},
  {"id":"s_work_nvlt_96_33","chapterId":"ch_work_nvlt_96","text":"【賦】晉劉琬神龍賦曰：大哉龍之為德，变化屈伸，隱則黃泉，出則升雲，賢聖其似之乎，惟天神上帝之馬，含胎春夏，房心所作，軒照形，［句有脱字。］角尾規矩。","sortOrder":33},
  {"id":"s_work_nvlt_96_34","chapterId":"ch_work_nvlt_96","text":"【贊】晉郭璞燭龍贊曰：天缺西土，龍衔火精，氣為寒暑，眼作昏明，身長千里，可謂至靈。","sortOrder":34},
  {"id":"s_work_nvlt_96_35","chapterId":"ch_work_nvlt_96","text":"又，龍魚一角，似鯉居陵，俟時而出，神靈攸乘，飛驚九域，乘雲上升。","sortOrder":35},
  {"id":"s_work_nvlt_96_36","chapterId":"ch_work_nvlt_96","text":"【銘】晉傅玄龍銘曰：麗哉神龍，誕應陽精，潛景九淵，飛曜天庭，屈伸從時，变化無形，偃伏汙泥，上凌太清。","sortOrder":36},
  {"id":"s_work_nvlt_96_37","chapterId":"ch_work_nvlt_96","text":"【序】魏缪袭青龍賦序曰：蓋青龍者，火辰之精，木官之瑞。","sortOrder":37},
  {"id":"s_work_nvlt_96_39","chapterId":"ch_work_nvlt_96","text":"《說文》曰：蛟，龍屬也，魚滿三千六百年，蛟為之長，率魚而飛去。","sortOrder":39},
  {"id":"s_work_nvlt_96_40","chapterId":"ch_work_nvlt_96","text":"山海經曰蛟似龍蛇，而小頭細頸，頸有白婴，大者十數围，卵生，子如一二斛瓮，能吞人。","sortOrder":40},
  {"id":"s_work_nvlt_96_41","chapterId":"ch_work_nvlt_96","text":"《易緯通卦验》曰：震東方也，至春分日，出青氣也，出直震，此正氣也，氣出右，萬物半死，氣出左，龍蛟出。","sortOrder":41},
  {"id":"s_work_nvlt_96_42","chapterId":"ch_work_nvlt_96","text":"《楚辭》曰：與汝遊兮九河，冲風起兮橫波，乘水車兮荷蓋，駕兩龍兮驂螭。","sortOrder":42},
  {"id":"s_work_nvlt_96_43","chapterId":"ch_work_nvlt_96","text":"《呂氏春秋》曰：荆有佽飛者，得寶劍，還涉江，有兩蛟夹繞其船，佽飛拔劍赴江，刺蛟殺之，荆王聞之，仕以執珪。","sortOrder":43},
  {"id":"s_work_nvlt_96_44","chapterId":"ch_work_nvlt_96","text":"《韓詩外傳》曰：東海有勇士菑丘訢，過神泉，飲馬，其仆曰：飲馬此者，馬必致死，飲馬果沉，訢拔劍而入，三日三夜，殺二蛟而出，雷神隨而击之，眇其左目。","sortOrder":44},
  {"id":"s_work_nvlt_96_45","chapterId":"ch_work_nvlt_96","text":"《漢書》曰：武帝元封五年，帝自尋陽江親射蛟江中，獲之。","sortOrder":45},
  {"id":"s_work_nvlt_96_46","chapterId":"ch_work_nvlt_96","text":"《尋陽記》曰：城東門通大桥，常有蛟為百姓害，董奉疏一符與水中，少日，見一蛟死，浮出。","sortOrder":46},
  {"id":"s_work_nvlt_96_47","chapterId":"ch_work_nvlt_96","text":"王韶之始興記曰：雲水源有湯泉，下流多蛟害，癘濟者遇之，必笑而没。","sortOrder":47},
  {"id":"s_work_nvlt_96_48","chapterId":"ch_work_nvlt_96","text":"《世說》曰：周處年少時，凶強俠氣，為乡里所患。又義興水中有蛟，山中有虎，併皆犯暴，百姓謂為三橫，而處既刺殺虎。又入水殺蛟，蛟或浮或没，行數十里，處與之俱，三日三夜，乡中皆謂處死，更相慶贺，處竟殺蛟而出，遂自改励，終為忠臣孝子。","sortOrder":48},
  {"id":"s_work_nvlt_96_49","chapterId":"ch_work_nvlt_96","text":"【贊】郭璞蛟贊曰：匪蛟匪龍，鱗采暉煥，騰濯涛波，蜿蜒江漢，漢武飲羽，佽飛叠斷。","sortOrder":49},
  {"id":"s_work_nvlt_96_51","chapterId":"ch_work_nvlt_96","text":"《爾雅》曰：螣，騰蛇，［能興雲霧。］蟒，王蛇，［蛇之最大者。］","sortOrder":51},
  {"id":"s_work_nvlt_96_52","chapterId":"ch_work_nvlt_96","text":"山海經曰：巴蛇吞象，三歲而出骨，君子服之，心［《太平御覽》九百三十三心上有已字。］腹之疾，［今南方〈虫弗〉(御覽作蚺字。)蛇，吞鹿已烂，自絞於树，腹中骨皆穿鱗甲間出。］","sortOrder":52},
  {"id":"s_work_nvlt_96_53","chapterId":"ch_work_nvlt_96","text":"又曰：大同之山，有蛇，名曰長蛇，其毛如彘豪，其音如鼓柝。","sortOrder":53},
  {"id":"s_work_nvlt_96_54","chapterId":"ch_work_nvlt_96","text":"又曰：泰華山有蛇肥遺，六足四翼。","sortOrder":54},
  {"id":"s_work_nvlt_96_55","chapterId":"ch_work_nvlt_96","text":"《毛詩》曰：惟虺惟蛇，女子之祥。","sortOrder":55},
  {"id":"s_work_nvlt_96_56","chapterId":"ch_work_nvlt_96","text":"孫子兵法曰：善用兵者，譬如率然，率然者，常山之蛇也，击其首則尾至，击其尾則首至，击其中身，則首尾俱至，［張茂先雲，會稽多此蛇。］","sortOrder":56},
  {"id":"s_work_nvlt_96_57","chapterId":"ch_work_nvlt_96","text":"楚辭曰：蝮蛇蓁蓁。","sortOrder":57},
  {"id":"s_work_nvlt_96_58","chapterId":"ch_work_nvlt_96","text":"《韓子》曰：鴟夷子皮事田成子，成子去齊，亡之燕，鴟夷子皮負傳而從，至望邑，曰：子獨不聞涸泽之蛇乎，泽涸將徙，小蛇謂大蛇曰：大蛇行，小蛇隨之，人以蛇之行者耳，必殺其子，子不如負我以行，必以我為神也，乃相負，越公道而行，人皆避之，今子美而我惡，以為上客，一乘之君也，以子為使者，萬乘之卿也，不如為我舍人，田成子負傳而隨之，至逆旅，逆旅之君待之甚敬，因獻酒肉。","sortOrder":58},
  {"id":"s_work_nvlt_96_59","chapterId":"ch_work_nvlt_96","text":"《戰國策》曰：昭陽為楚伐魏，移師攻齊，陳軫為齊王使，見昭陽曰：有祠者，賜其舍人酒一卮，舍人相謂曰：數人飲之不足，一人飲之有餘，請畫地為蛇，蛇先成者飲酒，一人蛇先成，引酒且飲，乃左手持酒，右手畫地，曰：吾能為之足，未成，一人蛇成，奪其卮曰：蛇故無足，子安能為，遂飲酒，為蛇足者，終亡其酒，今公攻魏，破軍殺將。又移師攻齊，戰勝不知止，猶為蛇足也，昭陽乃解軍而歸。","sortOrder":59},
  {"id":"s_work_nvlt_96_60","chapterId":"ch_work_nvlt_96","text":"《贾誼書》曰：孫叔敖之為兒，出遊還，忧而不食，其母問其故，泣而對曰：今旦見兩頭蛇，恐死，母曰：今蛇安在，曰：聞見兩頭蛇者死，恐他人复見之也，已殺而埋之，母曰：無忧，汝不死矣，吾聞之，有陰德者，天報以福。","sortOrder":60},
  {"id":"s_work_nvlt_96_61","chapterId":"ch_work_nvlt_96","text":"《淮南子》曰：夫騰蛇，雄鳴上風，雌鳴下風，而化成形，精之至也。","sortOrder":61},
  {"id":"s_work_nvlt_96_62","chapterId":"ch_work_nvlt_96","text":"又曰：豹獸不可使緣木，蝮蛇不可使安足。","sortOrder":62},
  {"id":"s_work_nvlt_96_63","chapterId":"ch_work_nvlt_96","text":"蜀王本紀曰：秦惠王欲伐蜀，蜀王好色，乃獻美女五人，蜀王遣五丁迎女，還至梓潼，見一大蛇入山穴中，一丁引其尾，不能出，五丁共引蛇，山崩，壓五丁，五丁踏蛇而大呼。","sortOrder":63},
  {"id":"s_work_nvlt_96_64","chapterId":"ch_work_nvlt_96","text":"《廣志》曰：蝮蛇與土色相亂，長三四尺，其中人，以牙櫟之，裁斷皮出血，則身盡痛，九竅血出而死。","sortOrder":64},
  {"id":"s_work_nvlt_96_65","chapterId":"ch_work_nvlt_96","text":"《玄中記》曰：東海有蛇丘之地，险多漸茹，眾蛇居之，無人民，蛇或人頭而蛇身。","sortOrder":65},
  {"id":"s_work_nvlt_96_66","chapterId":"ch_work_nvlt_96","text":"又曰：崑崙西北有山，周回三萬里，巨蛇繞之，得三周，蛇為長九萬里，蛇居此山，飲食沧海。","sortOrder":66},
  {"id":"s_work_nvlt_96_67","chapterId":"ch_work_nvlt_96","text":"《風俗通》曰：車騎將軍巴郡冯绲，為議郎，發綬笥，有二赤蛇，可三尺，分南北走，大用忧怖，卜雲，此吉祥也，君後當為邊將，以東為名，後五年，果為大將軍，拜遼東太守。","sortOrder":67},
  {"id":"s_work_nvlt_96_68","chapterId":"ch_work_nvlt_96","text":"陳留風俗傳曰：小黃縣者，宋地黃乡也，沛公起兵野戰，丧皇妣於黃乡，天下平定，乃使使者，以梓宮招魂幽野，於是丹蛇在水自洒濯，入於梓宮，其浴處有遺發，故謚曰昭靈夫人。","sortOrder":68},
  {"id":"s_work_nvlt_96_69","chapterId":"ch_work_nvlt_96","text":"《地鏡圖》曰：金寶化為青蛇。","sortOrder":69},
  {"id":"s_work_nvlt_96_70","chapterId":"ch_work_nvlt_96","text":"《抱朴子》曰：或問隱居山泽，治蛇蝮之道。","sortOrder":70},
  {"id":"s_work_nvlt_96_71","chapterId":"ch_work_nvlt_96","text":"又曰：昔負［御覽九百三十三作員。］丘多大蛇。又生好藥，黃帝將登焉，廣成子教之佩雄黃，而蛇皆去也，今帶武都黃，色如雞冠者五兩，以入山林，則不畏蛇，蛇若中人，以少許末抹之，雄黃入瘡中立愈。","sortOrder":71},
  {"id":"s_work_nvlt_96_72","chapterId":"ch_work_nvlt_96","text":"又曰：蛇類多，唯有蝮蛇，中人至急，一日不治則殺人，若不晓方術，而為此蛇所中，但以刀割瘡肉投地，其肉沸如火炙，須臾燋盡，而人得活也。","sortOrder":72},
  {"id":"s_work_nvlt_96_73","chapterId":"ch_work_nvlt_96","text":"《搜神記》曰：窦武母產武，而併產一蛇，送之林中，後母卒，及葬未窆，有大蛇自榛草而出，径至丧所，以頭击柩，涕血皆流，俯仰詰屈，若哀泣之容，有頃而去，時人知為窦氏之祥。","sortOrder":73},
  {"id":"s_work_nvlt_96_74","chapterId":"ch_work_nvlt_96","text":"又曰：隨侯行，見大蛇傷，救而治之，其後蛇衔珠以報之。","sortOrder":74},
  {"id":"s_work_nvlt_96_75","chapterId":"ch_work_nvlt_96","text":"周景式庐山記曰：安侯世高者，安息國太子，與友人共出家學道，友人恚怒死，受蟒報，為此宮亭湖神，世高於廣州為人所殺，還生安息國，复為王子，年二十。又弃國入吳，未之宮亭，泊船呼友人與語，友人身長數十丈，見世高，向之胡語竟，各分去，暮有一少年，上世高船，跪受咒原因忽不見，世高語同船人曰：向少年即此廟神也，得離惡形矣，蟒既見世高，從山南過，死山北，今柴桑民所居蛇里是也。","sortOrder":75},
  {"id":"s_work_nvlt_96_76","chapterId":"ch_work_nvlt_96","text":"《世說》曰：杜預為荆州刺史，時有宴集，大醉，辄閉斋獨眠，外聞斋中呕吐，其聲甚苦，有小吏开戶看之，止見床上有一蛇，垂頭床邊吐，都不見人，既出，密覺如此。","sortOrder":76},
  {"id":"s_work_nvlt_96_77","chapterId":"ch_work_nvlt_96","text":"《異苑》曰：魯國牟縣蒙山上，有寺廟，今民欲架室者，辄大蛇數十丈出來驚人，故莫得安焉。","sortOrder":77},
  {"id":"s_work_nvlt_96_78","chapterId":"ch_work_nvlt_96","text":"【銘】晉傅玄靈蛇銘曰：嘉茲靈蛇，斷而能續，飛不須翼，行不假足，上騰霄霧，下遊山嶽，進此明珠，預身龍族。","sortOrder":78},
  {"id":"s_work_nvlt_96_79","chapterId":"ch_work_nvlt_96","text":"【贊】晉郭璞長蛇贊曰：長蛇百尋，厥鬛如彘，飛群走類，靡不吞噬，極物之惡，盡毒之厲。","sortOrder":79},
  {"id":"s_work_nvlt_96_80","chapterId":"ch_work_nvlt_96","text":"又騰蛇贊曰：騰蛇配龍，因霧而躍，雖欲昇天，雲龍陆莫，材非所任，難以久讬。","sortOrder":80},
  {"id":"s_work_nvlt_96_81","chapterId":"ch_work_nvlt_96","text":"又巴蛇贊曰：象實巨獸，有蛇吞之，越出其骨，三年為期，厥大何如，屈生是疑。","sortOrder":81},
  {"id":"s_work_nvlt_96_82","chapterId":"ch_work_nvlt_96","text":"又蟒蛇贊曰：蠢蠢萬生，鹹以類長，惟蛇之君，是謂巨蟒，小則數尋，大或百丈。","sortOrder":82},
  {"id":"s_work_nvlt_96_83","chapterId":"ch_work_nvlt_96","text":"又枳首蛇贊曰：夔稱一足，蛇則二首，少不知無，多不覺有，雖資天然，無異骈拇。","sortOrder":83},
  {"id":"s_work_nvlt_96_84","chapterId":"ch_work_nvlt_96","text":"周庾信孫叔敖逢蛇贊曰：叔敖朝出，容悴還家，母氏顧訪，知埋怪蛇，爾有陰德，陽報將加，終為楚相，卒有榮華。","sortOrder":84},
  {"id":"s_work_nvlt_96_86","chapterId":"ch_work_nvlt_96","text":"《爾雅》曰：龟三足曰贲，一曰神龟，二曰靈龟，三曰攝龟，四曰寶龟，五曰文龟，六曰筮龟，七曰山龟，八曰泽龟，九曰水龟，十曰火龟。","sortOrder":86},
  {"id":"s_work_nvlt_96_87","chapterId":"ch_work_nvlt_96","text":"《易》曰：離為龟。","sortOrder":87},
  {"id":"s_work_nvlt_96_88","chapterId":"ch_work_nvlt_96","text":"《尚書》曰：九江納錫大龟。","sortOrder":88},
  {"id":"s_work_nvlt_96_89","chapterId":"ch_work_nvlt_96","text":"《大戴禮》曰：甲之虫三百六十，而神龟為之長。","sortOrder":89},
  {"id":"s_work_nvlt_96_90","chapterId":"ch_work_nvlt_96","text":"《左傳》曰：臧武仲自邾，使告臧贾，具致大蔡焉，曰：紇之不祀，子以大蔡納請，其可，贾再拜受龟。","sortOrder":90},
  {"id":"s_work_nvlt_96_91","chapterId":"ch_work_nvlt_96","text":"《列子》曰：渤海之東，有壑焉，其中有山，無所連著，常隨波上下往還，不得暫峙焉，仙聖毒之，訴於上帝，帝恐流於西極，失群聖之居，使巨龟十五，舉首而戴之，迭為三番，六萬歲一交焉，五山始峙而不動，龍伯之國，有大人，舉足不盈數十步，而暨五山之所，一釣而連六龟，合負而趣歸其國，灼其骨以數焉。","sortOrder":91},
  {"id":"s_work_nvlt_96_92","chapterId":"ch_work_nvlt_96","text":"《莊子》曰：莊子釣於濮水，楚王使大夫二先往焉，曰：原以境內累子，莊子持竿不顧，曰：吾聞楚有神龟，巾笥而藏之廟堂之上，此龟者，寧其為留骨而貴乎，寧其生而曳尾於涂中乎，吾將曳尾於泥中矣。","sortOrder":92},
  {"id":"s_work_nvlt_96_93","chapterId":"ch_work_nvlt_96","text":"又曰：宋元君夜夢有人被發言曰：予自宰路之，［《太平御覽》九百三十一之下有淵字，此脱。］為清江使河伯，漁者豫且得予，元君覺，召占夢者占之，曰：此神龟也，明日，豫且網得白龟，圓五尺，獻，乃殺以卜，七十鑽而無遺策，仲尼聞之曰：神能見夢於元君，而不能避豫且之網，智能七十鑽而無遺策，不能避刳剔之患。","sortOrder":93},
  {"id":"s_work_nvlt_96_94","chapterId":"ch_work_nvlt_96","text":"《史記》曰：餘至江南，聞長老雲，龟千歲，乃遊莲葉之上。","sortOrder":94},
  {"id":"s_work_nvlt_96_95","chapterId":"ch_work_nvlt_96","text":"又，褚先生曰：能得名龟，财物歸之，家必大富，至千萬，一曰北斗龟，二曰南辰龟，三曰五星龟，四曰八風龟，五曰二十八宿龟，六曰月龟，七曰王龟，八曰九州龟，神龟在江南嘉林中，常巢於芳莲之上，南方老人，以龟搘床足，經二十餘歲，老人死，移床，龟尚生，龟能行氣道引，至神若此。","sortOrder":95},
  {"id":"s_work_nvlt_96_96","chapterId":"ch_work_nvlt_96","text":"《說苑》曰：靈龟五色，色似玉，背陰而［《太平御覽》九百三十一作向。］陽，上隆象天，下平法地，轉運應四時，蛇頭龍胫，左睛象日，右睛象月，知存亡吉凶之忧。","sortOrder":96},
  {"id":"s_work_nvlt_96_97","chapterId":"ch_work_nvlt_96","text":"又，龟千歲，能與人言。","sortOrder":97},
  {"id":"s_work_nvlt_96_98","chapterId":"ch_work_nvlt_96","text":"《續搜神記》曰：晉鹹康中，豫州刺史毛寶，戍邾城，有一軍人，於武昌市買得一白龟，長五寸，置瓮中養之，漸大，放江中，後邾城遭石氏败，赴江者莫不沉溺，所養龟人，被甲投水中，覺如墮一石上，須臾视之，乃是先放白龟，既約岸，回顧而去。","sortOrder":98},
  {"id":"s_work_nvlt_96_99","chapterId":"ch_work_nvlt_96","text":"會稽後賢傳曰：孔愉嘗至吳興縣餘幹［《太平御覽》九百三十一作不。］亭，見人籠龟於路，愉求買放之，至水，反顧愉，及封此亭侯而鑄印，龟首回屈，三鑄不正，有似昔龟之顧，靈德應感如此，愉悟，乃取而佩焉。","sortOrder":99},
  {"id":"s_work_nvlt_96_100","chapterId":"ch_work_nvlt_96","text":"《符子》曰：邦人獻燕昭王以大豕者，曰：於今百二十歲，邦人謂之豕仙，其群臣言於昭王曰：是豕無用，王命宰夫膳之，豕既死，乃見夢燕相曰：今仗君之靈而化五［《太平御覽》九百三十一作吾。］生也，始得為魯津之伯，而浮舟者食我以粳糧之珍，而欣君之惠，將報子焉，後燕相遊於魯津，有赤龟衔夜光而獻之。","sortOrder":100},
  {"id":"s_work_nvlt_96_101","chapterId":"ch_work_nvlt_96","text":"抱朴子，巢［按巢上當有玉字。］記曰：千歲之龟，五色具焉，其額上兩骨起，似角，解人言，浮出莲葉之上，或在丛蓍之下。","sortOrder":101},
  {"id":"s_work_nvlt_96_102","chapterId":"ch_work_nvlt_96","text":"《異苑》曰：孫權時，永康有人入山，遇一大龟，即束之歸，龟便言曰：遊不良時。為君所得，人甚怪之，載出，欲上吳王，夜泊越里，纜船於大桑树，霄中，树呼龟曰：勞乎元緒，奚事爾耶，龟曰：我被拘縶，方見烹〈月隺〉，雖盡南山之樵，不能潰我，树曰：諸葛元遜博識，必致相苦，令求如我之徒，計從安薄，龟曰：子明無多辭，禍將及爾，树寂而止，既至，權命煮之，焚柴萬車，語猶如故，諸葛恪曰：燃以老桑乃熟，獻者仍說龟树共言，權登使伐树，煮龟立烂，今烹龟猶多用桑薪，野人故呼龟為元緒。","sortOrder":102},
  {"id":"s_work_nvlt_96_103","chapterId":"ch_work_nvlt_96","text":"【賦】魏曹植神龟賦曰：龟號千歲，時有遺金龟者，數日而死，肌肉消盡，唯甲存焉，餘感而賦之曰：嘉四靈之建德，各潛位乎一方，蒼龍虬於東嶽，白虎嘯於西岗，玄武集於寒門，朱雀栖於南乡，順仁風以消息，應聖時而後翔，餐飛尘以實氣，飲不竭於朝露，步容趾以俯仰，時鸞回而鶴顧，懼沉泥之逢殆，赴芳莲以巢居。","sortOrder":103},
  {"id":"s_work_nvlt_96_104","chapterId":"ch_work_nvlt_96","text":"【詩】北齊趙宗儒詠龟詩曰：有靈堪讬夢，無心自解謀，不能蓍下伏，強從莲上遊，負圖非所冀，支床空見留，傥蒙一曳尾，當為屢回頭。","sortOrder":104},
  {"id":"s_work_nvlt_96_105","chapterId":"ch_work_nvlt_96","text":"【贊】晉郭璞爾雅龟贊曰：天生神物，十朋之龟，或遊於火，或遊於蓍，雖雲類殊，象二一歸，亹亹致用，極數盡幾。","sortOrder":105},
  {"id":"s_work_nvlt_96_107","chapterId":"ch_work_nvlt_96","text":"《爾雅》曰：鱉三足曰能。","sortOrder":107},
  {"id":"s_work_nvlt_96_108","chapterId":"ch_work_nvlt_96","text":"《易》曰：離為鱉。","sortOrder":108},
  {"id":"s_work_nvlt_96_109","chapterId":"ch_work_nvlt_96","text":"《說文》曰：鱉介虫也。","sortOrder":109},
  {"id":"s_work_nvlt_96_110","chapterId":"ch_work_nvlt_96","text":"《周禮》曰：春獻鱉蜃。","sortOrder":110},
  {"id":"s_work_nvlt_96_111","chapterId":"ch_work_nvlt_96","text":"《春秋外傳》曰：公父文伯飲南宮敬叔酒，羞鱉焉。","sortOrder":111},
  {"id":"s_work_nvlt_96_112","chapterId":"ch_work_nvlt_96","text":"《晏子春秋》曰：齊大旱，景公召群臣問曰：寡人欲祠河伯，可乎，《晏子》曰：不可，河伯以水為國，以魚鱉為民，彼獨不欲雨乎，祠之何益。","sortOrder":112},
  {"id":"s_work_nvlt_96_113","chapterId":"ch_work_nvlt_96","text":"《文子》曰：鱉無耳而不可蔽，精於明也。","sortOrder":113},
  {"id":"s_work_nvlt_96_114","chapterId":"ch_work_nvlt_96","text":"《莊子》曰：埳井之蛙，謂東海鱉曰：吾跳梁，奚不時來觀，東海鱉左足未入，而右膝已縶矣。","sortOrder":114},
  {"id":"s_work_nvlt_96_115","chapterId":"ch_work_nvlt_96","text":"《楚辭》曰：驷跛鱉而上山，吾固知其不能升。","sortOrder":115},
  {"id":"s_work_nvlt_96_116","chapterId":"ch_work_nvlt_96","text":"《孫卿子》曰：蛙步而不休，跛鱉千里。","sortOrder":116},
  {"id":"s_work_nvlt_96_117","chapterId":"ch_work_nvlt_96","text":"《淮南子萬畢術》曰：青泥殺鱉，得苋复生。","sortOrder":117},
  {"id":"s_work_nvlt_96_118","chapterId":"ch_work_nvlt_96","text":"又曰：燒黿致鱉，［取黿夜燒之，則鱉至也。］","sortOrder":118},
  {"id":"s_work_nvlt_96_119","chapterId":"ch_work_nvlt_96","text":"《列仙傳》曰：費長房能使社公，汝南有妖，常作太守服，詣府門椎鼓，合郡患之，及長房來，知是魅，乃呵之，即解衣冠，叩頭乞自改，即老鱉也，大如車輪，長房令复太守服，作一札敕葛陂君，叩頭流涕，持札去，遂视以札立陂邊，以頸繞之而死。","sortOrder":119},
  {"id":"s_work_nvlt_96_120","chapterId":"ch_work_nvlt_96","text":"《魏略》曰：高離國王侍婢有身，生子，王欲殺之，婢雲，有氣如雞子來下我，故有身，後生子，捐之於溷中，猪以氣噓之，從馬間，馬以氣噓之，王乃令其母收畜，名曰東明，常令牧馬，東明善射，王恐奪其國，欲殺之，東明走，以弓击水，魚鱉浮為桥，東明得渡，因都王扶餘之地。","sortOrder":120},
  {"id":"s_work_nvlt_96_121","chapterId":"ch_work_nvlt_96","text":"《搜神記》曰：清河宋士宗母，黃初中，夏在室中浴，良久，家人於壁穿中窥之，正見木盆中有一大鱉，先著銀釵，猶在頭上，遂入水去。","sortOrder":121},
  {"id":"s_work_nvlt_96_122","chapterId":"ch_work_nvlt_96","text":"【賦】晉陆機鱉賦曰：皇太子幸於釣台，漁人獻鱉，命侍臣作賦，其状也，穹脊連胁，玄甲四周，遁方圓於規矩，徒廣［本集廣下有狹字。］以妨，［句有脱文。］循盈尺而腳寸。又取具於指掌，鼻嘗氣而忌脂，耳無聽而受响，是以栖居多逼，出處寡便，尾不副首，足不運身，於是從容泽畔，肆志汪洋，朝戲蘭渚，夕息中塘，越高波以魚逸，竄洪流而潛藏，咀蕙蘭之芳荄，翳華藕之垂房。","sortOrder":122},
  {"id":"s_work_nvlt_96_123","chapterId":"ch_work_nvlt_96","text":"晉潘尼鱉賦曰：皇太子遊於玄圃，遂命釣魚，有得鱉而戲之者，令侍臣賦之，翩衔鉤以振掉，吁駭人而可惡，既顛墜於巖岸，方盤跚而雅步，或延首以鶴顧，或頓足而鷹距，或曳尾於泥中，或縮頭於壳里，若乃秋水暴駭，百川沸流，有東海之巨鱉，乃負山而吞舟。","sortOrder":123},
  {"id":"s_work_nvlt_96_125","chapterId":"ch_work_nvlt_96","text":"《詩》曰：南有嘉魚。","sortOrder":125},
  {"id":"s_work_nvlt_96_126","chapterId":"ch_work_nvlt_96","text":"又曰：魚潛在淵。","sortOrder":126},
  {"id":"s_work_nvlt_96_127","chapterId":"ch_work_nvlt_96","text":"又曰：魚在在藻。","sortOrder":127},
  {"id":"s_work_nvlt_96_128","chapterId":"ch_work_nvlt_96","text":"月令，立春，魚上冰。","sortOrder":128},
  {"id":"s_work_nvlt_96_129","chapterId":"ch_work_nvlt_96","text":"莊子與惠子觀魚於濠梁。","sortOrder":129},
  {"id":"s_work_nvlt_96_130","chapterId":"ch_work_nvlt_96","text":"《史記》曰：魏王與龍陽君共舡而釣，龍陽君得千餘魚，而涕下曰：臣之始得魚也，臣甚喜，後得益大，臣欲弃前所得矣，今以臣之凶惡也，而得為王拂枕席，夫四海之內，其美人亦甚多矣，聞臣之得幸於王也，畢褰裳而趨王矣，亦曩臣之所弃前魚也。","sortOrder":130},
  {"id":"s_work_nvlt_96_131","chapterId":"ch_work_nvlt_96","text":"《新序》曰：楚人有獻魚於楚王曰：今獲魚，食之不盡，賣之不售，弃之又惜，故獻之，左右曰：鄙哉辭也，楚王曰：子不知漁者仁人也，蓋聞國粟有餘者，國有饿民，後宮多幽女也，下民多曠夫，皆失君人之道，故厨庖有肥馬，寡人聞之久矣，未能行也，漁者知之，且今行之矣，故漁者獻餘魚，而楚國賴之。","sortOrder":131},
  {"id":"s_work_nvlt_96_132","chapterId":"ch_work_nvlt_96","text":"《說苑》曰：楚王謂淳於髡曰：吾有仇在吳，子寧能為吾報之乎，對曰：臣見來道旁野民，持一頭魚，上田祝曰：高得萬束，下得千斛，臣竊笑之，以為禮薄而望多也。","sortOrder":132},
  {"id":"s_work_nvlt_96_133","chapterId":"ch_work_nvlt_96","text":"《三辅故事》曰：武帝作崑明池，學水戰法，帝崩，昭帝小，不能征讨，於池中養魚，以給諸陵祠，餘給長安市，市魚乃賤。","sortOrder":133},
  {"id":"s_work_nvlt_96_134","chapterId":"ch_work_nvlt_96","text":"《吳越春秋》曰：越王既栖會稽，范蠡等曰：臣竊見會稽之山，有魚池，上下二處，水中有三江四渎之流，九溪六穀之廣，上池宜於君王，下池宜於臣，畜魚三年，其利可以致於萬，越國當富盈。","sortOrder":134},
  {"id":"s_work_nvlt_96_135","chapterId":"ch_work_nvlt_96","text":"《風俗通》曰：城門失火，禍及池中魚，舊說池中魚，人姓李，［《太平御覽》九百三十五作字。］居近城，城門失火，延及其家，仲灾燒死，謹百家書曰：宋城門失火，因汲池水以沃灌之，池中空竭，魚悉露死，喻惡之滋，併中傷量謹也。","sortOrder":135},
  {"id":"s_work_nvlt_96_136","chapterId":"ch_work_nvlt_96","text":"謝承《漢書》曰：會稽陳嚚，少時，於郭外水邊捕魚，人有盜者，嚚見，避於草中，追以魚遺之，盜慚不受，自後無复取焉。","sortOrder":136},
  {"id":"s_work_nvlt_96_137","chapterId":"ch_work_nvlt_96","text":"曹植說疲［疲疑當作疫，《太平御覽》七百四十二曾引曹植說疫氣。］氣曰：鹹水之魚，不遊於江，淡水之魚，不入於海。","sortOrder":137},
  {"id":"s_work_nvlt_96_138","chapterId":"ch_work_nvlt_96","text":"《汝南先賢傳》曰：［《太平御覽》九百三十五作神仙傳。］葛玄見遭大魚者，玄謂暫煩此魚到河伯處，魚主曰：魚已死，玄曰：無苦，以丹書紙內魚口中，掷水中，有頃，魚還躍上岸，吐墨書，青黑色，如木葉而飛。又玄與吳主坐樓上，見作請雨土人，玄曰：雨易得耳，即書符著社中，一時之間，大雨流淹，帝曰：水中有魚乎，玄复書符掷中，須臾有大魚數百頭，使人治之。","sortOrder":138},
  {"id":"s_work_nvlt_96_139","chapterId":"ch_work_nvlt_96","text":"又曰：介象與吳王共論，辎魚為上，乃於殿庭作坎，汲水滿之，併求釣，象起餌之，須臾得辎魚，帝驚喜，乃使厨人切之，象又往蜀市薑，有頃而反。","sortOrder":139},
  {"id":"s_work_nvlt_96_140","chapterId":"ch_work_nvlt_96","text":"《符子》曰：觀於龍門，有一魚，奋鱗鼓鬐而登乎龍門而為龍。又一術士，凌波蹈流而不陷，搖鈴行歌，飄浪於龍門，而終日栖遲而不化，《符子》曰：彼同功而事異，跡一而理二，夫何哉，無乃魚以實應，而人以伪求乎。","sortOrder":140},
  {"id":"s_work_nvlt_96_141","chapterId":"ch_work_nvlt_96","text":"萧廣濟《孝子傳》曰：陳玄，太子也，後母謗之，陳侯令玄自殺，玄投遼水，魚負之以出，玄曰：我罪人也，故求死耳，魚乃去。","sortOrder":141},
  {"id":"s_work_nvlt_96_142","chapterId":"ch_work_nvlt_96","text":"又曰：巴郡杜孝，役在城都，母喜食生魚，於官得生鱗，截竹盛魚二頭，宙水中，曰：我母如得此，婦出渚得之，笑曰：是我婿寄，乃以進母。","sortOrder":142},
  {"id":"s_work_nvlt_96_143","chapterId":"ch_work_nvlt_96","text":"辛氏《三秦記》曰：崑明池人釣魚，纶絕而去，夢於漢武帝，求去其鉤，明日，帝遊於池，見大魚衔索，帝曰：昨所夢也，取而去之，帝後得明珠。","sortOrder":143},
  {"id":"s_work_nvlt_96_144","chapterId":"ch_work_nvlt_96","text":"【賦】晉王慶釣魚賦曰：然後抽纖繳，振脩竿，垂銀鉤，運金丸，懸鲔鲵，掛鸿鸞，連翩雲际，瀺灂漪澜。","sortOrder":144},
  {"id":"s_work_nvlt_96_145","chapterId":"ch_work_nvlt_96","text":"晉挚虞觀魚賦曰：觀鱗族於彪池兮，睨羽群於瀨涯，乃有洧泉之鯉，濯陂之鰋。瀺灂涌躍，投浪赴遠，集於曲崖之隈，逐乎澹淡之深，攒聚輻蹙，或躍或沉，倏烁攸驿，眩目驚心，汎溢爵於通溝，因素波以獻酬，騁微巧於浮觴，競機捷於迅流。","sortOrder":145},
  {"id":"s_work_nvlt_96_146","chapterId":"ch_work_nvlt_96","text":"【詩】梁張騫詠躍魚應詔詩曰：戢鱗隱繁藻，頒首承绿漪，何用遊溟澥，且躍天淵池。","sortOrder":146},
  {"id":"s_work_nvlt_96_147","chapterId":"ch_work_nvlt_96","text":"陳張正見賦得魚躍水花生詩曰：漾色桃花水，相望濯錦流，躍浦疑珠出，依池似鏡浮，凌波衔落蕊，觸餌避沉鉤，方遊莲葉外，詎入武王舟。","sortOrder":147},
  {"id":"s_work_nvlt_96_148","chapterId":"ch_work_nvlt_96","text":"陳阮卓莲下遊魚詩曰：春色映澄陂，涵泳且相隨，未上龍門路，聊戲芙蓉池，觸浪莲看動，乘流葉影披，相忘自有樂，莊惠豈能知。","sortOrder":148},
  {"id":"s_work_nvlt_96_149","chapterId":"ch_work_nvlt_96","text":"隋岑德润魚詩曰：劍影侵波合，珠光帶水新，莲東自可戲，安用上龍津。","sortOrder":149},
  {"id":"s_work_nvlt_96_150","chapterId":"ch_work_nvlt_96","text":"《藝文類聚》　唐·欧陽詢","sortOrder":150},
  {"id":"s_work_nvlt_97_1","chapterId":"ch_work_nvlt_97","text":"卷九十七鱗介部下、虫豸部","sortOrder":1},
  {"id":"s_work_nvlt_97_2","chapterId":"ch_work_nvlt_97","text":"○螺蚌蛤蛤蜊乌賊石劫","sortOrder":2},
  {"id":"s_work_nvlt_97_3","chapterId":"ch_work_nvlt_97","text":"○蝉蠅蚊蜉蝣蛱蝶螢火蝙蝠叩頭虫蛾蜂蟋蟀尺蠖蚁蜘蛛螳螂","sortOrder":3},
  {"id":"s_work_nvlt_97_5","chapterId":"ch_work_nvlt_97","text":"《爾雅》曰：蠃小者蜬。","sortOrder":5},
  {"id":"s_work_nvlt_97_6","chapterId":"ch_work_nvlt_97","text":"《易》曰：離為蠃，［刚在外也。］","sortOrder":6},
  {"id":"s_work_nvlt_97_7","chapterId":"ch_work_nvlt_97","text":"魏書曰：自遭荒亂，率乏糧穀，袁紹河北軍，人仰棗椹，袁術在江淮，取蛤蒲蠃，民人相食，州部萧條。","sortOrder":7},
  {"id":"s_work_nvlt_97_8","chapterId":"ch_work_nvlt_97","text":"《搜神記》曰：晉安謝端，侯官人，少孤，年十八，恭謹自守，後於邑下得一大螺，如斗許，取貯瓮中，每早至野還，見有飲飯湯火，端疑之，於篱外窥，見一少女從瓮中出，至竈下燃火，便入問之，女答曰：妾天漢中白素女，天帝哀卿少孤，使我權相為守舍炊煮，待卿取婦，當還去，今無故相伺，不宜复留，今留此壳貯米穀，可得不乏，忽有風雨而去。","sortOrder":8},
  {"id":"s_work_nvlt_97_9","chapterId":"ch_work_nvlt_97","text":"《南州異物志》曰：扶南海有大螺，如甌，從邊直旁截破，因成杯形，或合而用之，螺體蜿蛇委曲，酒在內自註，傾覆終不盡，以伺誤相罰為樂。","sortOrder":9},
  {"id":"s_work_nvlt_97_10","chapterId":"ch_work_nvlt_97","text":"又曰：鸚鵡螺，状如覆杯，頭如鳥頭，向其腹，视似鸚鵡，故以為名，肉離壳出食，飽則還壳中，若為魚所食，壳乃浮出，人所得，质白而紫，文如鳥形，與觴無異，故因其象鳥，為作兩目兩翼也。","sortOrder":10},
  {"id":"s_work_nvlt_97_11","chapterId":"ch_work_nvlt_97","text":"又曰：寄居之虫，如螺而有腳，形如蜘蛛，本無壳，入空螺壳中，戴以行，觸之縮足如螺閉戶也，火炙之乃出走，始知其寄居也。","sortOrder":11},
  {"id":"s_work_nvlt_97_12","chapterId":"ch_work_nvlt_97","text":"王韶始興記曰：桂陽貞女峡，傳雲，秦世有數女，取螺於此，遇風雨，一女忽化為石人，今形高七尺，状如女子。","sortOrder":12},
  {"id":"s_work_nvlt_97_13","chapterId":"ch_work_nvlt_97","text":"《異苑》曰：鸚鵡螺形似鳥，故以為名，常脱壳而遊，朝出，則有虫類如蜘蛛，入其壳中，螺夕還，則此虫出，庾闡所謂鸚鵡內遊，寄居負壳者也。","sortOrder":13},
  {"id":"s_work_nvlt_97_14","chapterId":"ch_work_nvlt_97","text":"【詩】宋謝惠連詠螺蚌詩曰：輕羽不高翔，自用絃網羅，纖鱗惑芳餌，故為釣所加，螺蚌非有心，沉跡在泥沙，文無雕飾用，味非鼎俎和。","sortOrder":14},
  {"id":"s_work_nvlt_97_16","chapterId":"ch_work_nvlt_97","text":"《易》曰：離為蚌。","sortOrder":16},
  {"id":"s_work_nvlt_97_17","chapterId":"ch_work_nvlt_97","text":"《大戴禮》曰：十一月，雉入淮為蜃，蜃，蒲盧［二字原倒，據冯校本改。］也。","sortOrder":17},
  {"id":"s_work_nvlt_97_18","chapterId":"ch_work_nvlt_97","text":"《呂氏春秋》曰：月者，［者下有脱文。］群陰盈，晦則蚌蛤虛，群陰缺。","sortOrder":18},
  {"id":"s_work_nvlt_97_19","chapterId":"ch_work_nvlt_97","text":"《戰國策》曰：趙且伐燕，蘇代為燕謂趙惠王曰：川蚌方出曝，而鷸啄其肉，蚌合而相［《太平御覽》九百四十一作挟。］其啄，鷸曰：今日不雨，明日不雨，即有蚌脯，蚌亦謂鷸曰：今日不出，明日不出，必見死鷸。","sortOrder":19},
  {"id":"s_work_nvlt_97_20","chapterId":"ch_work_nvlt_97","text":"《淮南子》曰：明月之珠，螺蚌之病，而我之利也，虎爪象牙，禽獸之利，而我之害也。","sortOrder":20},
  {"id":"s_work_nvlt_97_21","chapterId":"ch_work_nvlt_97","text":"徐哀［《太平御覽》九百四十一作衷。］南方記曰：珠蚌壳長三寸，在涨海中。","sortOrder":21},
  {"id":"s_work_nvlt_97_22","chapterId":"ch_work_nvlt_97","text":"盛弘之《荆州記》曰：馬牧城東三里，有蚌城，相傳雲，飢年，民結侣采蚌，止憩其中，故因為名。","sortOrder":22},
  {"id":"s_work_nvlt_97_23","chapterId":"ch_work_nvlt_97","text":"又雲，城隨洲势，上大尖，其形似蚌，故有蚌號。","sortOrder":23},
  {"id":"s_work_nvlt_97_24","chapterId":"ch_work_nvlt_97","text":"《汝南先賢傳》曰：周燮好潛養靖志，唯典籍是樂，有先人草庐，庐於東坑，其下有陂，魚蚌生焉，非身所耕漁，則不食也。","sortOrder":24},
  {"id":"s_work_nvlt_97_25","chapterId":"ch_work_nvlt_97","text":"【贊】晉郭璞蚌贊曰：萬物变蜕，其理無方，雀雉之化，含珠懷璫，與月盈虧，协氣晦望。","sortOrder":25},
  {"id":"s_work_nvlt_97_27","chapterId":"ch_work_nvlt_97","text":"《說文》曰：蛤有三，皆生於海，蛤蠣，千歲鳥所化也，海蛤，百歲燕所化也，〈鬼寸〉蛤，一名复老，服翼所化。","sortOrder":27},
  {"id":"s_work_nvlt_97_28","chapterId":"ch_work_nvlt_97","text":"《本草經》曰：文蛤，表有文。","sortOrder":28},
  {"id":"s_work_nvlt_97_29","chapterId":"ch_work_nvlt_97","text":"又曰：馬刀一曰名蛤。","sortOrder":29},
  {"id":"s_work_nvlt_97_30","chapterId":"ch_work_nvlt_97","text":"《禮記》曰：季冬，雀入水為蛤。","sortOrder":30},
  {"id":"s_work_nvlt_97_31","chapterId":"ch_work_nvlt_97","text":"《漢武內傳》曰：西王母曰：仙藥次有白水靈蛤。","sortOrder":31},
  {"id":"s_work_nvlt_97_32","chapterId":"ch_work_nvlt_97","text":"《南越志》曰：凡蛤之屬，开口聞雷鳴，不复閉口。","sortOrder":32},
  {"id":"s_work_nvlt_97_33","chapterId":"ch_work_nvlt_97","text":"【論】晉裴頠崇有論曰：鳥無胃，［《太平御覽》八百二十五胃下有肺字。］藏，［御覽藏上有蛤無五三字，此脱。］經［御覽經作蛭。］以空中而生，螢，［御覽螢作蠶。］無胃而育。","sortOrder":33},
  {"id":"s_work_nvlt_97_34","chapterId":"ch_work_nvlt_97","text":"【啟】陳徐陵謝赉蛤啟曰：比鸿，［句有脱訛。］雀入猶新，才变秋程，已聞冬獻。","sortOrder":34},
  {"id":"s_work_nvlt_97_35","chapterId":"ch_work_nvlt_97","text":"◇蛤蜊","sortOrder":35},
  {"id":"s_work_nvlt_97_36","chapterId":"ch_work_nvlt_97","text":"《淮南子》曰：若士乃卷龟壳而食蛤蜊。","sortOrder":36},
  {"id":"s_work_nvlt_97_37","chapterId":"ch_work_nvlt_97","text":"《論衡》曰：若士食蛤蜊之肉，乃與民同食，安能升天。","sortOrder":37},
  {"id":"s_work_nvlt_97_38","chapterId":"ch_work_nvlt_97","text":"《抱朴子》曰：蛤蜊各煮炙，凡人所能啖，况君子與士乎。","sortOrder":38},
  {"id":"s_work_nvlt_97_39","chapterId":"ch_work_nvlt_97","text":"臨海土物記曰：蛤蜊壳薄且小。","sortOrder":39},
  {"id":"s_work_nvlt_97_40","chapterId":"ch_work_nvlt_97","text":"【啟】梁元帝謝赉車螯蛤蜊啟曰：車螯，味高食部，名陳物志，蛤蜊，聲重前論，見珍若士，併東海波臣，西王母藥，雀文始化，燕羽猶在，體润珠胎，形隨月减。","sortOrder":40},
  {"id":"s_work_nvlt_97_41","chapterId":"ch_work_nvlt_97","text":"陳徐陵謝東宮赉蛤蜊啟曰：舡俗嚴戈，漁人資設，於彼海童，冒茲水豹，望樓闕之氣，得波潮之下。","sortOrder":41},
  {"id":"s_work_nvlt_97_42","chapterId":"ch_work_nvlt_97","text":"◇乌賊","sortOrder":42},
  {"id":"s_work_nvlt_97_43","chapterId":"ch_work_nvlt_97","text":"《本草經》曰：乌賊魚骨，治寒熱驚氣。","sortOrder":43},
  {"id":"s_work_nvlt_97_44","chapterId":"ch_work_nvlt_97","text":"南越記曰：乌賊魚有矴，遇風浪，便虬前一須，不［《太平御覽》九百三十八作下。］矴而住，腹中血及膳，［御覽作胆。］正黑，中以書也，世謂乌賊懷黑［御覽作墨。］而知禮，故俗雲是海君白事小史，或曰古之諸生，常自浮水上，乌見以為死，便往啄之，乃卷取乌，故謂乌化為之。","sortOrder":44},
  {"id":"s_work_nvlt_97_45","chapterId":"ch_work_nvlt_97","text":"《臨海異物志》曰：乌賊之骨，其大如楯居者，［句有訛。］一枚作鮓滿器，受五升。","sortOrder":45},
  {"id":"s_work_nvlt_97_46","chapterId":"ch_work_nvlt_97","text":"【啟】陳徐陵謝敕赉乌賊啟曰：变逯庸臣，伏增銘悚。","sortOrder":46},
  {"id":"s_work_nvlt_97_47","chapterId":"ch_work_nvlt_97","text":"◇石劫","sortOrder":47},
  {"id":"s_work_nvlt_97_48","chapterId":"ch_work_nvlt_97","text":"【賦】梁江淹石劫賦曰：石劫一名紫{艹嚣}，蚌蛤類也，春而發華，有足翼者，夫海君［本集作若。］之小臣，具品色於沧溟，既爐天而論形，先［本集作光。］避伏而不曜，知理冥而難發，何弱命之不禁，永至於天代，［本集作夭閼。］請去人［本集人上有海字。］之仄陋，充公子之嘉客，傥委身於土［本集作玉。］盤，從風雨其何惜。","sortOrder":48},
  {"id":"s_work_nvlt_97_49","chapterId":"ch_work_nvlt_97","text":"◇蝉［虫豸部］","sortOrder":49},
  {"id":"s_work_nvlt_97_50","chapterId":"ch_work_nvlt_97","text":"《爾雅》曰：蜩，螂蜩，［五采具者。］螗蜩，［俗呼為胡蝉。］{截虫}茅蜩，［似蝉而小青。］蝒馬蜩，［蝉中最大者。］蜺寒蜩，［寒螀也，小，青赤。］","sortOrder":50},
  {"id":"s_work_nvlt_97_51","chapterId":"ch_work_nvlt_97","text":"方言曰：蝉楚謂之蜩，宋衛之間，謂之螗蜩，［今胡蝉也，鳴聲清亮，江南呼螗螂也。］陳鄭之間謂之螂蜩，秦晉之間謂之蝉，海岱之間謂之〈虫奇〉，或謂之蝒馬，其小者謂之麥禮，［小而青。］","sortOrder":51},
  {"id":"s_work_nvlt_97_52","chapterId":"ch_work_nvlt_97","text":"又曰：蛥蚗，［上音祈，下音决。］齊謂之螇螰，［奚音，鹿音。］楚謂之蟪蛄，自關以東，謂之虭［貂。］蟧，［聊。］","sortOrder":52},
  {"id":"s_work_nvlt_97_53","chapterId":"ch_work_nvlt_97","text":"《禮記》曰：仲夏之月，蝉始鳴，季夏之月，寒蝉鳴。","sortOrder":53},
  {"id":"s_work_nvlt_97_54","chapterId":"ch_work_nvlt_97","text":"《毛詩》曰：螓首蛾眉，［螓，青蝉也。］","sortOrder":54},
  {"id":"s_work_nvlt_97_55","chapterId":"ch_work_nvlt_97","text":"《莊子》曰：仲尼適楚，出於林中，見痀僂者承蜩，猶掇之也，仲尼曰：子有道耶，曰：我有道，五六月累二丸而不墜，則失者锱銖，［累二丸於竿頭，是用手停審也，故其承蜩所，不過锱銖之間。］","sortOrder":55},
  {"id":"s_work_nvlt_97_56","chapterId":"ch_work_nvlt_97","text":"又曰：鵬之飛，摶扶搖而上者九萬里，蜩與鶯鳩笑之曰：我决起而槍榆枋，時則不至，而控於地，奚以九萬里而為。","sortOrder":56},
  {"id":"s_work_nvlt_97_57","chapterId":"ch_work_nvlt_97","text":"《楚辭》曰：歲暮兮不自聊，蟪蛄鳴兮啾啾。","sortOrder":57},
  {"id":"s_work_nvlt_97_58","chapterId":"ch_work_nvlt_97","text":"華峤《漢書》曰：蔡邕在陳留，其鄰人有以酒食召邕者，比往而酒已酣焉，客有彈琴者，邕至門潛聽之，曰：嘻，以樂召我而有殺心，何也，遂反，將命者告主人，主人遽自追而問其故，邕具以告，彈琴者曰：我向鼓絃，見螳螂方向鳴蝉，蝉將去，螳螂為之一前一却，吾心唯恐螳螂之失蝉也，此豈為殺心而形於聲者乎，邕笑曰：此足以當之。","sortOrder":58},
  {"id":"s_work_nvlt_97_59","chapterId":"ch_work_nvlt_97","text":"《風土記》曰：七月而蟪蛄鳴於朝，寒螀鳴於夕。","sortOrder":59},
  {"id":"s_work_nvlt_97_60","chapterId":"ch_work_nvlt_97","text":"《搜神記》曰：淮南內史朱誕，給使妻有鬼病，夫疑為奸，密闚，見婦在機中織，望桑树上所笑，見树上有十四五小兒，衣青布褶，青縿頭，乃射之，化為鳴蝉，其大如箕，飛去。","sortOrder":60},
  {"id":"s_work_nvlt_97_61","chapterId":"ch_work_nvlt_97","text":"【詩】古詩曰：庭前有奇树，上有悲鳴蝉。","sortOrder":61},
  {"id":"s_work_nvlt_97_62","chapterId":"ch_work_nvlt_97","text":"陳張正見寒树晚蝉疏詩曰：寒蝉噪楊柳，朔吹犯梧桐，葉迥飛難住，枝殘影共空，聲疏飲露後，唱絕斷絃中，還因搖落處，寂寞盡秋風。","sortOrder":62},
  {"id":"s_work_nvlt_97_63","chapterId":"ch_work_nvlt_97","text":"梁簡文帝聽早蝉詩曰：草歇題鳴初，蝉思花落後，乍飲三危露，時荫五官柳，莊書哂鵬翼，衛賦宜螓首，桂树可淹留，勿謂山中久。","sortOrder":63},
  {"id":"s_work_nvlt_97_64","chapterId":"ch_work_nvlt_97","text":"梁沈約聽蝉鳴應詔詩曰：輕生宅園篽，复得栖嘉树，豈敢擅洪枝，輕條遭所寓，葉密形易扬，風回响難住。","sortOrder":64},
  {"id":"s_work_nvlt_97_65","chapterId":"ch_work_nvlt_97","text":"梁褚澐賦得蝉詩曰：避雀芳枝里，飛空華殿曲，天寒响屢嘶，日暮聲逾促，繁吟欲如盡，長韻還相續，飲露非表清，輕身易知足。","sortOrder":65},
  {"id":"s_work_nvlt_97_66","chapterId":"ch_work_nvlt_97","text":"梁范雲詠早蝉詩曰：生隨春冰薄，质與秋尘輕，端綏挹宵液，飛音承露清。","sortOrder":66},
  {"id":"s_work_nvlt_97_67","chapterId":"ch_work_nvlt_97","text":"隋王由禮賦得高柳鳴蝉詩曰：園柳吟涼久，嘶蝉應序驚，露下綏恒濕，風高翅轉輕，葉疏飛更迥，秋深响自清，何言枝里翳，遂入蔡琴聲。","sortOrder":67},
  {"id":"s_work_nvlt_97_68","chapterId":"ch_work_nvlt_97","text":"陳劉删詠蝉詩曰：聲流上林苑，影入侍臣冠，得飲玄天露，何辭高柳寒。","sortOrder":68},
  {"id":"s_work_nvlt_97_69","chapterId":"ch_work_nvlt_97","text":"隋江總詠蝉詩曰：白露涼風吹，朱明落照移，鳴條譟林柳，流响遍台池，忖聲如易得，尋忽却難知。","sortOrder":69},
  {"id":"s_work_nvlt_97_70","chapterId":"ch_work_nvlt_97","text":"【賦】後漢蔡邕蝉賦曰：白露凄其夜降，秋風肅以晨興，聲嘶嗌以沮败，體枯燥以水凝，雖期運之固然，獨潛類乎太陰，要明年之中夏，复長鳴而扬音。","sortOrder":70},
  {"id":"s_work_nvlt_97_71","chapterId":"ch_work_nvlt_97","text":"後漢曹大家蝉賦曰：伊玄虫之微陋，亦攝生於天壤，當三秋之盛暑，陵高木之流响，融風被而來遊，商焱厲而化往。","sortOrder":71},
  {"id":"s_work_nvlt_97_72","chapterId":"ch_work_nvlt_97","text":"魏陳王曹植蝉賦曰：唯夫蝉之清素，潛厥類於太陰，在炎陽之中夏，始遊豫於芳林，內含和而弗食，與眾物而無求，栖高枝而仰首，漱朝露之清流，隱柔桑之稠葉，快閒居以遁暑，苦黃雀之作害，患螳螂之劲斧，有翩翩之狡童，運徽黏而我纏，委厥體於膳夫，歸炎炭而就燔，狄［本集作秋。］霜紛以霄下，晨風冽其過庭，氣憯怛而薄軀，足攀木而失茎，吟嘶哑以沮败，状枯槁以丧形。","sortOrder":72},
  {"id":"s_work_nvlt_97_73","chapterId":"ch_work_nvlt_97","text":"晉明帝蝉賦曰：尋長枝以凌高，靜無為以自寧，邈焉獨處，弗累於情，在運任時，不慮不營。","sortOrder":73},
  {"id":"s_work_nvlt_97_74","chapterId":"ch_work_nvlt_97","text":"晉溫峤蝉賦曰：飢吸晨風，渴飲朝露。","sortOrder":74},
  {"id":"s_work_nvlt_97_75","chapterId":"ch_work_nvlt_97","text":"晉陆士龍寒蝉賦曰：昔人稱雞有五德，而作者賦焉，至於寒蝉，才齊其美，獨未思之，而莫斯述，夫頭上有蕤，則其文也，含氣飲露，則其清也，黍稷不享，則其廉也，處不巢居，則其俭也，應候守常，則其信也，加以冠冕，取其容也，君子則其操，可以事君，可以立身，豈非至德之虫哉，伊寒蝉之感運，迓嘉時以遊征，含二儀之和氣，禀乾元之清靈，體貞粹之淑质，吐〈口爭〉〈口營〉之哀聲，容麗蜩螗，聲美宮商，飄如飛焱之運驚風，眇如輕雲之麗泰陽，爾乃振脩蕊以表首，舒輕翅以迅翰，挹朝華之墜露，含煙煴以夕飧，望北林以鸞飛，集樛木而龍蟠，若夫歲律雲暮，上天其涼，感運非聲，貧士含傷，或歌我行永久，或哀之乎無裳，原思叹於蓬室，孤竹吟於首陽，不衔草以秽身，不勤身以營巢，志高於鳴鳩，節妙乎鴟鴞，附枯枝以永處，倚峻林之迥條，乃缀以玄冕，增成首飾，映華虫於朱裳，表馨香乎明德。","sortOrder":75},
  {"id":"s_work_nvlt_97_76","chapterId":"ch_work_nvlt_97","text":"晉傅鹹黏蝉賦曰：櫻桃為树則多陰，為果則先熟，有蝉鳴焉，聊命黏取，退惟當蝉之得意於斯树，不知黏之將至，亦猶人之得於富貴，而不虞禍之將來也，有嘉果之珍树，蔚弘覆於我庭，在赫赫之隆暑，獨肅肅而自清，遂寓目以周覽，見鳴蜩於纖枝，翳翠葉以長吟，信厥樂之在斯，苟得意於所歡，曾黏往之莫知，匪爾命之遵薄，坐偷安而忘危，嗟悠悠之躭寵，請茲覽以自規。","sortOrder":76},
  {"id":"s_work_nvlt_97_77","chapterId":"ch_work_nvlt_97","text":"又鳴蜩賦曰：有嘒嘒之鳴蜩，於台府之高槐，物處陰而自惨，奚厥聲之可哀，秋日凄凄兮，感時逝之若頹，曷時逝之是感兮，感年歲之我催，孰知命之不忧，詠梁木之有摧，生世忽兮如寓，求福貴於不回，且明明以在公，唯忠谠之是與，佚履道之坦坦，登高衢以自栖。","sortOrder":77},
  {"id":"s_work_nvlt_97_78","chapterId":"ch_work_nvlt_97","text":"晉孫楚蝉賦曰：惟大化之廣御，何品數之多名，當仲夏而始出，據長條而悲鳴，翼如羅纏，形如枯槁，終日不衔一粒，激哀响之煩扰。","sortOrder":78},
  {"id":"s_work_nvlt_97_79","chapterId":"ch_work_nvlt_97","text":"宋顏延之寒蝉賦曰：始萧瑟以攒吟，終嬋媛而孤引，越客發度障之歌，代馬懷首燕之信，不假蕤於范冠，豈鏤體於人爵，折清飆而下淪，团高木以飄落。","sortOrder":79},
  {"id":"s_work_nvlt_97_80","chapterId":"ch_work_nvlt_97","text":"隋盧思道聽鳴蝉曰：此聽悲無極，群嘶玉树里，回噪金門侧，長風送晚聲，清露供朝食，晚風朝露實多宜，秋日高鳴蝉獨見知，［句有衍文。］輕身蔽數葉，哀鳴抱一枝，流亂罢還續，酸傷更合離，蹔聽別人心即斷，才聞客子淚先垂，故乡已迢忽，空庭正芜没，一夕复一朝，坐見涼秋月，河流帶地從來崄，峭路幹天不可越，紅尘早弊陆生衣，明鏡空悲潘掾發，長安城里帝王州，鳴鍾列鼎自相求，西望漸台臨太液，東瞻甲觀拒龍樓，說客恒持小冠出，越使常懷寶劍遊，學仙未成便尚主，尋源不見已封侯，富貴功名本多豫，繁華輕薄盡無忧，詎念漂姚嗟木梗，誰憶阑单倦土牛，歸去來，青山下，秋菊離離日堪把，獨焚枯宴林野，終成獨校子雲書，何如還驅少遊馬。","sortOrder":80},
  {"id":"s_work_nvlt_97_81","chapterId":"ch_work_nvlt_97","text":"【贊】晉郭璞蝉贊曰：虫之精絜，可貴惟蝉，潛蜕弃歲，飲露恒鮮，萬物皆化，人胡不然。","sortOrder":81},
  {"id":"s_work_nvlt_97_82","chapterId":"ch_work_nvlt_97","text":"梁昭明太子蝉贊曰：茲虫清絜，惟露是餐，寂寞秋序，咽哳夏阑，定伊不美，曜彼華冠。","sortOrder":82},
  {"id":"s_work_nvlt_97_84","chapterId":"ch_work_nvlt_97","text":"《爾雅》曰：蠅丑扇，［好搖翅也。］","sortOrder":84},
  {"id":"s_work_nvlt_97_85","chapterId":"ch_work_nvlt_97","text":"《毛詩》曰：營營青蠅，止於樊，恺悌君子，無信讒言。","sortOrder":85},
  {"id":"s_work_nvlt_97_86","chapterId":"ch_work_nvlt_97","text":"《韓子》曰：以骨去蚁，蚁愈多，以魚驅蠅，蠅愈至。","sortOrder":86},
  {"id":"s_work_nvlt_97_87","chapterId":"ch_work_nvlt_97","text":"《呂氏春秋》曰：以狸致鼠，以冰致蠅。","sortOrder":87},
  {"id":"s_work_nvlt_97_88","chapterId":"ch_work_nvlt_97","text":"焦贛《易林》曰：腐肉所在，青蠅集聚，辨別白黑，败亂邦國。","sortOrder":88},
  {"id":"s_work_nvlt_97_89","chapterId":"ch_work_nvlt_97","text":"《漢書》曰：成帝建始中，有青蠅垂萬數，集未央宮殿中朝者坐，公卿已下朝會坐。","sortOrder":89},
  {"id":"s_work_nvlt_97_90","chapterId":"ch_work_nvlt_97","text":"又曰：昌邑王贺，夢青蠅之矢積西階東，可五六石，以問龚遂，曰：陛下左侧，讒人眾多，原皆放逐之，贺不用其言，卒至於废。","sortOrder":90},
  {"id":"s_work_nvlt_97_91","chapterId":"ch_work_nvlt_97","text":"扬子《法言》曰：或問蒼蠅紅紫，［蒼蠅間乎白黑，紅紫似朱而非朱。］","sortOrder":91},
  {"id":"s_work_nvlt_97_92","chapterId":"ch_work_nvlt_97","text":"謝承《後漢書》曰：郭谅師事杜乔，李固之誅，詣闕上書，乞收斂，不聽，因往守视其丧，扇護蠅虫。","sortOrder":92},
  {"id":"s_work_nvlt_97_93","chapterId":"ch_work_nvlt_97","text":"又，扬章為杜乔所辟，為平原令，弃官還，聞固乔曝尸，星行赴雒，著弊衣赤帻，守其尸，驅護蠅虫，天子嘉其忠義，聽殯斂之。","sortOrder":93},
  {"id":"s_work_nvlt_97_94","chapterId":"ch_work_nvlt_97","text":"《魏略》曰：王思性急，執筆作書，蠅集筆端，驅去复來，思恚怒，自起逐蠅，不能得，還，取筆掷地，踏坏之。","sortOrder":94},
  {"id":"s_work_nvlt_97_95","chapterId":"ch_work_nvlt_97","text":"虞翻別傳曰：翻放逐南方，自恨犯上獲罪，當長没海隅，生無可與語，死以青蠅為弔客，使天下一人知己者，足以不恨。","sortOrder":95},
  {"id":"s_work_nvlt_97_96","chapterId":"ch_work_nvlt_97","text":"《益部耆舊傳》曰：嚴遵為扬州刺史，行部，聞道旁女子哭聲不哀，問之，雲夫遭燒死，遵敕吏舆尸到，令人守尸，曰：當有物自往，吏白有蠅聚頭所，遵令披视，得鐵錐貫，考問，以淫殺夫。","sortOrder":96},
  {"id":"s_work_nvlt_97_97","chapterId":"ch_work_nvlt_97","text":"《異苑》曰：晉明帝嘗欲肆眚，乃屏曲室，去左右，下帷作詔，有大蒼蠅觸帳而入，萃於筆端，有頃皆出，帝竊異焉，令人尋之，即蠅所集處，辄傳有赦，喧然必遍。","sortOrder":97},
  {"id":"s_work_nvlt_97_98","chapterId":"ch_work_nvlt_97","text":"【賦】晉傅鹹青蠅賦曰：幸從容以閒居，日遊心於典經，覽詩人之有造，刺青蠅之營營，無纖介之微用，信作害之不輕，既反白而為黑，恒懷蛆以自盈，秽美厚之鮮絜，虫嘉肴之芬馨，滿堂室之薨薨，孰閨寓之得情。","sortOrder":98},
  {"id":"s_work_nvlt_97_99","chapterId":"ch_work_nvlt_97","text":"【書】漢張敞書曰：夫蒼龍非不神，不能白日升天，飄風雖疾，不以霖雨，不能扬尘，故蒼蠅之飛，不過十步，自讬騏骥之發，乃騰千里之路。","sortOrder":99},
  {"id":"s_work_nvlt_97_100","chapterId":"ch_work_nvlt_97","text":"【論】後漢班固難莊論曰：眾人之逐世利，如青蠅之赴肉汁也，青蠅嗜肉汁而忘溺死，眾人貪世利而陷罪禍。","sortOrder":100},
  {"id":"s_work_nvlt_97_102","chapterId":"ch_work_nvlt_97","text":"《爾雅》曰：鷏蚊母，［俗說此鳥常吐蚊，故名蚊母。］","sortOrder":102},
  {"id":"s_work_nvlt_97_103","chapterId":"ch_work_nvlt_97","text":"《大戴禮》曰：聖人有國，蚊虻不食夭駒。","sortOrder":103},
  {"id":"s_work_nvlt_97_104","chapterId":"ch_work_nvlt_97","text":"《晏子》曰：景公謂《晏子》曰：天下有極小乎，對曰：有虫巢於蚊睫，再乳而飛蚊不為驚，名曰焦螟。","sortOrder":104},
  {"id":"s_work_nvlt_97_105","chapterId":"ch_work_nvlt_97","text":"《列子》曰：江浦之間，生么虫，名曰焦螟，群飛而集於蚊睫，弗相觸也，栖宿去來，蚊弗覺也，見［見字衍。］離朱子羽方晝，拭眦扬眉而望之，弗見其形，師曠方夜，擿耳挽首聽之，弗聞其聲，唯黃帝與容成子居崆峒之上，同斋三月，心死形废，倏以神视，然見之，若嵩山之阿，徐以氣聽，砰然聞之，若雷霆之聲，以有形涉神明之境，嵩山未足喻其巨，以有聲涉空寂之域，雷霆之音未足喻其大。","sortOrder":105},
  {"id":"s_work_nvlt_97_106","chapterId":"ch_work_nvlt_97","text":"《東方朔傳》曰：郭舍人曰：原問朔一事，朔得，臣原榜百，朔窮，臣當賜帛，曰。客從東方來，歌謳且行，不從門入，逾我垣牆，遊戲中庭，上入殿堂，击之柏柏。死者欀々，格斗而死，主人被創，是何物也，朔曰：長喙細身，晝亡夜存，嗜肉惡煙，為掌指所扪，臣朔愚戆，名之曰蚊，舍人辭窮，當复脱褌。","sortOrder":106},
  {"id":"s_work_nvlt_97_107","chapterId":"ch_work_nvlt_97","text":"《莊子》曰：肩吾見狂接舆，接舆曰：中□［《太平御覽》九百四十五作始。］何以語汝，肩吾曰：以己出仁義，民孰敢不聽而化，接舆曰：是欺德也，猶涉海凿河，而使蚊負山也。","sortOrder":107},
  {"id":"s_work_nvlt_97_108","chapterId":"ch_work_nvlt_97","text":"又曰：由天之道，觀惠施之能，其一蚊之勞者耶。","sortOrder":108},
  {"id":"s_work_nvlt_97_109","chapterId":"ch_work_nvlt_97","text":"又曰：孔子見老聃而語仁義，老聃曰：夫播糠眯目，則天地四方易位矣，蚊虻噆膚，則通宵不寐矣。","sortOrder":109},
  {"id":"s_work_nvlt_97_110","chapterId":"ch_work_nvlt_97","text":"《鶡冠子》曰：夫蚊蚊墜乎千仞之谿，乃始翱翔而成其容。","sortOrder":110},
  {"id":"s_work_nvlt_97_111","chapterId":"ch_work_nvlt_97","text":"《孫卿子》曰：空中有人名曰鲛，蚊虻之聲聞，則挫其精。","sortOrder":111},
  {"id":"s_work_nvlt_97_112","chapterId":"ch_work_nvlt_97","text":"《淮南子》曰：雲台之高，墮者折脊碎腦，而蚊虻適足以翾。","sortOrder":112},
  {"id":"s_work_nvlt_97_113","chapterId":"ch_work_nvlt_97","text":"《神異經》曰：方［《太平御覽》九百四十五方上有南字。］蚊翼下有小飛虫焉，生九卵，复成九子，飛而俱去，蚊遂不知。","sortOrder":113},
  {"id":"s_work_nvlt_97_114","chapterId":"ch_work_nvlt_97","text":"《續搜神記》曰：吳舍人名猛，小兒時，在父母膝下，夏日多蚊虻，而終不搖扇，有同宿人覺，問其故，答雲，懼蚊虻去，噆我父母耳。","sortOrder":114},
  {"id":"s_work_nvlt_97_115","chapterId":"ch_work_nvlt_97","text":"萧廣濟《孝子傳》曰：展勤少失父，與母居，佣作供養，天多蚊，臥母床下，以身當之，《漢書》曰：中山靖王朝，天子置酒，聞樂而泣，問其故，靖王對曰：臣聞眾煦漂山，聚蚊成雷，是以文王拘於羑里，孔子厄於陳蔡。","sortOrder":115},
  {"id":"s_work_nvlt_97_116","chapterId":"ch_work_nvlt_97","text":"《論衡》曰：世稱南陽卓公為缑氏令，蝗虫不入界，蓋以賢明至誠，灾虫不入其縣也，此又虛也，夫同類能相知心，然後慕服，蝗虫，蚊虻之類也，何能知卓公之化乎，使賢者處於深野之中，蚊虻不入其舍乎。","sortOrder":116},
  {"id":"s_work_nvlt_97_117","chapterId":"ch_work_nvlt_97","text":"【賦】晉傅選蚊賦曰：水與草其漸茹，育茲孽而蚊□，［明本蚊下空一格，按下無胎卵而化孕生句衍一生字，疑當在此。］〈口雋〉咮銳於秋毫，刺鋸利於芒錐，無胎卵而化孕生，搏物翼而能飛，肇孟夏以明起，迄季秋而不衰，眾繁炽而無數，動群聲而成雷，肆惨毒於有生，乃餐膚體以療飢，妨農功於南畝，废女工於杼機。","sortOrder":117},
  {"id":"s_work_nvlt_97_118","chapterId":"ch_work_nvlt_97","text":"◇蜉蝣","sortOrder":118},
  {"id":"s_work_nvlt_97_119","chapterId":"ch_work_nvlt_97","text":"《爾雅》曰：蜉蝣，渠略，［似天牛而小，有角。］","sortOrder":119},
  {"id":"s_work_nvlt_97_120","chapterId":"ch_work_nvlt_97","text":"《說文》曰：秦晉之間，謂之渠略。","sortOrder":120},
  {"id":"s_work_nvlt_97_121","chapterId":"ch_work_nvlt_97","text":"又曰：〈虫巢〉虫也，一名蜉蝣，蓋朝生暮死。","sortOrder":121},
  {"id":"s_work_nvlt_97_122","chapterId":"ch_work_nvlt_97","text":"《廣志》曰：蜉蝣可燒啖，美於〈虫巢〉，蜉蝣在水中，翕然生，覆水上，尋死隨流。","sortOrder":122},
  {"id":"s_work_nvlt_97_123","chapterId":"ch_work_nvlt_97","text":"《大戴禮》夏小正曰：五月蜉蝣有殷，殷，眾也。","sortOrder":123},
  {"id":"s_work_nvlt_97_124","chapterId":"ch_work_nvlt_97","text":"《毛詩》曰：蜉蝣堀閱，麻衣如雪。","sortOrder":124},
  {"id":"s_work_nvlt_97_125","chapterId":"ch_work_nvlt_97","text":"《詩疏義》曰：樊光雲，是粪中虫，陰雨而為之，朝生夕死。","sortOrder":125},
  {"id":"s_work_nvlt_97_126","chapterId":"ch_work_nvlt_97","text":"《淮南子》曰：龟三千歲，蜉蝣不過三日，人以數離之寿，忧天下之亂，猶忧河水之少，而泣以益之也。","sortOrder":126},
  {"id":"s_work_nvlt_97_127","chapterId":"ch_work_nvlt_97","text":"【賦】晉傅鹹蜉蝣賦曰：有生之薄，是曰蜉蝣，育微微之陋质，羌采采而自脩，不識晦朔，無意春秋，取足一日，尚又何求，戲停淹而委餘，何必江湖而是遊。","sortOrder":127},
  {"id":"s_work_nvlt_97_128","chapterId":"ch_work_nvlt_97","text":"◇蛱蝶","sortOrder":128},
  {"id":"s_work_nvlt_97_129","chapterId":"ch_work_nvlt_97","text":"《列子》曰：鳥足之葉為胡蝶。","sortOrder":129},
  {"id":"s_work_nvlt_97_130","chapterId":"ch_work_nvlt_97","text":"《莊子》曰：昔莊周夢為胡蝶，栩栩然胡蝶，不知周也，俄然覺，則蘧蘧然周也，不知周之夢為胡蝶，胡蝶之為周與，胡［《太平御覽》九百四十五胡上有周與二字，此脱。］蝶，必有分矣，此謂物化。","sortOrder":130},
  {"id":"s_work_nvlt_97_131","chapterId":"ch_work_nvlt_97","text":"【詩】古詩曰：胡蝶胡高飛，暮宿桑树間。","sortOrder":131},
  {"id":"s_work_nvlt_97_132","chapterId":"ch_work_nvlt_97","text":"梁簡文帝詠蛱蝶詩曰：空園暮煙起，逍遙獨未歸，翠鬛藏高柳，紅莲拂水衣，复此從風蝶，双双花上飛，寄語相知者，同心終莫违。","sortOrder":132},
  {"id":"s_work_nvlt_97_133","chapterId":"ch_work_nvlt_97","text":"梁徐防賦得蝶依草詩曰：秋園花落盡，芳菊數來歸，那知不夢作，眠覺也恒飛。","sortOrder":133},
  {"id":"s_work_nvlt_97_134","chapterId":"ch_work_nvlt_97","text":"◇螢火","sortOrder":134},
  {"id":"s_work_nvlt_97_135","chapterId":"ch_work_nvlt_97","text":"《爾雅》曰：螢火，即炤。","sortOrder":135},
  {"id":"s_work_nvlt_97_136","chapterId":"ch_work_nvlt_97","text":"《廣雅》曰：景天，螢火，〈虫粦〉也。","sortOrder":136},
  {"id":"s_work_nvlt_97_137","chapterId":"ch_work_nvlt_97","text":"呂氏《本草》曰：螢火一名夜照，一名熠燿，一名救火，一名景天，一名據火，一名挟火。","sortOrder":137},
  {"id":"s_work_nvlt_97_138","chapterId":"ch_work_nvlt_97","text":"《禮記》曰：季夏之月，腐草為螢，飛虫螢火也。","sortOrder":138},
  {"id":"s_work_nvlt_97_139","chapterId":"ch_work_nvlt_97","text":"《毛詩》曰：町畽鹿場，熠燿宵行。","sortOrder":139},
  {"id":"s_work_nvlt_97_140","chapterId":"ch_work_nvlt_97","text":"《續晉陽秋》曰：車胤字武子，學而不倦，家貧，不常得油，夏日用練囊，盛數十螢火，以夜繼日焉。","sortOrder":140},
  {"id":"s_work_nvlt_97_141","chapterId":"ch_work_nvlt_97","text":"【詩】梁簡文帝詠螢詩曰：本將秋草併，今與夕風輕，騰空類星陨，拂树若花生，井疑神火照，帘似夜珠明。","sortOrder":141},
  {"id":"s_work_nvlt_97_142","chapterId":"ch_work_nvlt_97","text":"梁元帝詠螢火詩曰：著人疑不熱，集草訝無煙，到來燈下暗，翻住雨中然。","sortOrder":142},
  {"id":"s_work_nvlt_97_143","chapterId":"ch_work_nvlt_97","text":"陳楊縉賦得照映秋螢詩曰：秋窗餘照盡，入暗早螢來，忽聚還同色，恒燃詎落灰，飛影黃金散，依帷縹帙开，含明自不息，夜月空徘徊。","sortOrder":143},
  {"id":"s_work_nvlt_97_144","chapterId":"ch_work_nvlt_97","text":"【賦】晉傅鹹螢火賦曰：餘曾獨處，顧見螢火，熱［《太平御覽》九百四十五作執。］以自照，而為之賦，潛空馆之寂寂，意遙遙而靡寧，夜耿耿而不寐，忧悄悄以傷情，感詩人之攸懷，覽熠燿於前庭，不以姿质之鄙薄，欲增暉乎太清，雖無補於日月，期自竭於陋形，不進競於天光，退在晦而能明，谅有似於賢臣，於疏外而盡誠，假乃光而爾賦，庶有表乎忠貞。","sortOrder":144},
  {"id":"s_work_nvlt_97_145","chapterId":"ch_work_nvlt_97","text":"晉潘安仁螢火賦曰：嘉熠燿之精將，與眾類乎超殊，東山感而增叹，行士慨而懷忧，翔太陰之玄昧，抱夜光以清遊，颎若飛焱之宵逝，彗如星移之雲流，動集漂扬，灼如隋珠，熠熠熒熒，若丹英之照葩，飄飄颎颎，若金流之在沙，歃湛露於曠野，庇一葉之垂柯，無幹欲於萬物，豈顧恤於網羅。","sortOrder":145},
  {"id":"s_work_nvlt_97_146","chapterId":"ch_work_nvlt_97","text":"【贊】晉郭璞螢火贊曰：熠燿宵行，虫之微么，出自腐草，煙若散熛，物之相〈口炰〉，［按當作煦。］孰知其陶。","sortOrder":146},
  {"id":"s_work_nvlt_97_147","chapterId":"ch_work_nvlt_97","text":"◇蝙蝠","sortOrder":147},
  {"id":"s_work_nvlt_97_148","chapterId":"ch_work_nvlt_97","text":"《爾雅》曰：蝙蝠服翼。","sortOrder":148},
  {"id":"s_work_nvlt_97_149","chapterId":"ch_work_nvlt_97","text":"《方言》曰：蝙蝠，自關東謂之伏翼，或謂之飛翼，或謂之老鼠。","sortOrder":149},
  {"id":"s_work_nvlt_97_150","chapterId":"ch_work_nvlt_97","text":"吳氏《本草》曰：伏翼或生人家屋間，立夏後陰乾，治目冥，令人夜视有光。","sortOrder":150},
  {"id":"s_work_nvlt_97_151","chapterId":"ch_work_nvlt_97","text":"《春秋運斗枢》曰：行失瑤光，則伏翼兩頭併翔，廣江淮山渎之祠，則瑤光明，伏翼九足。","sortOrder":151},
  {"id":"s_work_nvlt_97_152","chapterId":"ch_work_nvlt_97","text":"《孝經援神契》曰：道德遺遠，蝙蝠伏匿，故夜食。","sortOrder":152},
  {"id":"s_work_nvlt_97_153","chapterId":"ch_work_nvlt_97","text":"《玄中記》曰：百歲伏翼，色赤，止則倒懸，千歲伏翼，色白，得食之，寿萬歲。","sortOrder":153},
  {"id":"s_work_nvlt_97_154","chapterId":"ch_work_nvlt_97","text":"吳娄縣記曰：太湖東邊別小山，名山洞庭，有三穴，中有大蝙蝠，如乌，拂救人火。","sortOrder":154},
  {"id":"s_work_nvlt_97_155","chapterId":"ch_work_nvlt_97","text":"《臨海記》曰：黃石山泄水東南，五峴路口，有鍾乳穴，中伏翼大如鹅鸭。","sortOrder":155},
  {"id":"s_work_nvlt_97_156","chapterId":"ch_work_nvlt_97","text":"【賦】魏陳王曹植蝙蝠賦曰：吁何奸氣，生茲蝙蝠，形殊性诡，每变常式，行不由足，飛不假翼，明伏暗動，晝似鼠形，謂鳥不似，二足為毛，飛而含齒，巢不哺鷇，空不乳子，不容毛群，斥逐羽族，下不蹈陆，上不冯木。","sortOrder":156},
  {"id":"s_work_nvlt_97_157","chapterId":"ch_work_nvlt_97","text":"◇叩頭虫","sortOrder":157},
  {"id":"s_work_nvlt_97_158","chapterId":"ch_work_nvlt_97","text":"《異苑》曰：有小虫，形色如大豆，咒令叩頭。又咒吐血，皆從所教，如似稽顙，故俗呼為叩頭虫。","sortOrder":158},
  {"id":"s_work_nvlt_97_159","chapterId":"ch_work_nvlt_97","text":"【賦】晉傅鹹叩頭虫賦曰：蓋齒以刚克而盡，舌存以其能柔，強梁者不得其死，執雌者物莫之讎，無咎生於惕厲，悔吝來亦有由，仲尼唯诺於陽虎，所以解紛而免尤，韓信非為懦兒，出胯下而不羞，何茲虫之多畏，人才觸而叩頭，犯而不校，誰與為仇，人不我害，我亦無忧，彼螳螂之舉斧，豈患禍之能御，此謙卑以自牧，乃無害之可贾，將斯文之焉貴，貴不遠而取譬，雖不能觸類是長，且書紳以自示，旨一日而三省，恒跼蹐以祗畏，然後可以蒙自天祐之，吉無不利。","sortOrder":159},
  {"id":"s_work_nvlt_97_161","chapterId":"ch_work_nvlt_97","text":"《爾雅》曰：蛾羅，［蠶蛾也。］","sortOrder":161},
  {"id":"s_work_nvlt_97_162","chapterId":"ch_work_nvlt_97","text":"《說文》曰：蛾，蠶化飛虫也。","sortOrder":162},
  {"id":"s_work_nvlt_97_163","chapterId":"ch_work_nvlt_97","text":"《廣志》曰：有蠶蛾，有天蛾，凡草木虫，以蛹化為蛾甚眾，《淮南子》曰：食桑有絲曰蛾，［蠶屬。］","sortOrder":163},
  {"id":"s_work_nvlt_97_164","chapterId":"ch_work_nvlt_97","text":"《漢書》曰：有白蛾，群飛蔽日，從東都門至轵道。","sortOrder":164},
  {"id":"s_work_nvlt_97_165","chapterId":"ch_work_nvlt_97","text":"《古今註》曰：蛾飛廣五六丈。","sortOrder":165},
  {"id":"s_work_nvlt_97_166","chapterId":"ch_work_nvlt_97","text":"洞林曰：東中郎參軍周稚琰，封蠶蛾，令吾射之。","sortOrder":166},
  {"id":"s_work_nvlt_97_167","chapterId":"ch_work_nvlt_97","text":"《符子》曰：不安其昧而樂其明，是猶夕蛾去暗，赴燈而死也。","sortOrder":167},
  {"id":"s_work_nvlt_97_168","chapterId":"ch_work_nvlt_97","text":"【賦】晉支曇諦赴火蛾賦曰：悉達有言曰：愚人貧身，如蛾投火，誠哉斯言，信而有徵也，翔無常宅，集無定栖，類聚群分，尘合電分，因溫風以舒散，乘遊氣以徘徊，於是朱明御節，時在盛陽，天地鬱蒸，日月昏茫，燭曜庭宇，燈朗幽房，紛紛群飛，翩翩來翔，赴飛焰而體燋，投煎膏而身亡。","sortOrder":168},
  {"id":"s_work_nvlt_97_170","chapterId":"ch_work_nvlt_97","text":"《爾雅》曰：蜂丑〈虫欲〉，［□(爾雅釋虫作垂。)其腴也。］土蜂，［在地中作房者。］木蜂，［在树上作房。］","sortOrder":170},
  {"id":"s_work_nvlt_97_171","chapterId":"ch_work_nvlt_97","text":"《廣雅》曰：范，蜂也。","sortOrder":171},
  {"id":"s_work_nvlt_97_172","chapterId":"ch_work_nvlt_97","text":"《禮記》曰：郕人有其兄死而不為縗者，聞子皋將為郕宰，遂為縗，郕人曰：蠶則績而蟹有匡，范則冠而蝉有緌，兄則死子皋為之縗。","sortOrder":172},
  {"id":"s_work_nvlt_97_173","chapterId":"ch_work_nvlt_97","text":"春秋潭潛巴曰：朝有大蜂武士，中蜂赤強，黑不梁，［蜂有刺毒以扞難，武士象也，梁或為良。］《韓詩外傳》曰：以稷蜂不螫，而社鼠不燻，非以稷蜂社鼠之神也，其所讬者然也，故聖人求賢者以自辅。","sortOrder":173},
  {"id":"s_work_nvlt_97_174","chapterId":"ch_work_nvlt_97","text":"《楚辭》曰：玄蜂若壶。","sortOrder":174},
  {"id":"s_work_nvlt_97_175","chapterId":"ch_work_nvlt_97","text":"《博物志》曰：人家養蜂，以木為器，开小孔，以蜜涂器，捕取三兩蜂，內器中，宿昔，蜂飛出，將伴來，作蜜多少，隨歲丰俭。","sortOrder":175},
  {"id":"s_work_nvlt_97_176","chapterId":"ch_work_nvlt_97","text":"葛仙翁別傳曰：仙公與客對食，客曰：食畢，當請先作一奇戲，食未竟，仙公曰：諸君得無邑邑，欲見乎，即吐口中飯，盡成飛蜂，滿屋，或集客身，莫不震肅，但自不螫人耳，良久，仙公乃張口，見蜂皆飛還入口中，成飯食之。","sortOrder":176},
  {"id":"s_work_nvlt_97_177","chapterId":"ch_work_nvlt_97","text":"《抱朴子》曰：雞有摶遷之雄，雉有擅泽之驕，蚁有兼弱之智，蜂有攻寡之計，人相投御亦是耳。","sortOrder":177},
  {"id":"s_work_nvlt_97_178","chapterId":"ch_work_nvlt_97","text":"【詩】梁簡文帝詠蜂詩曰：逐風從汎漾，照日乍依微，知君不留眄，衔花空自飛。","sortOrder":178},
  {"id":"s_work_nvlt_97_179","chapterId":"ch_work_nvlt_97","text":"【賦】晉郭璞蜜蜂賦曰：嗟品物之蠢蠢，惟貞虫之明族，有丛琐之細蜂，亦策名於羽屬，近浮遊於園薈，遠翱翔乎林穀，爰翔爰集蓬轉飆回，紛紜雪亂，混沌雲頹，景翳燿靈，响迅風雷，若乃眩猿之雀，下林天井，青松冠穀，赤萝繡嶺，無花不纏，無隙不省，吮琼液於懸岋，峰赮津乎晨景，於是回鶩林篁，經營堂密，［原訛蜜，據冯校本改。］繁布金房，叠構玉室，咀嚼華滋，酿以為蜜，自然靈化，莫識其術，散似甘露，凝如割肪，冰鮮玉润，髓滑蘭香，百藥須之以芣和，扁鵲得之而術良，爾乃察其所安，视其所讬，恒據中而虞難，營翠微而結落，徽號明於羽族，閽衛國乎管籥，誅戮峻於鈇鉞，招徵速乎羽檄，集不謀而固期，動不安而齊約。","sortOrder":179},
  {"id":"s_work_nvlt_97_180","chapterId":"ch_work_nvlt_97","text":"◇蟋蟀","sortOrder":180},
  {"id":"s_work_nvlt_97_181","chapterId":"ch_work_nvlt_97","text":"《爾雅》曰：蟋蟀，蛩也。","sortOrder":181},
  {"id":"s_work_nvlt_97_182","chapterId":"ch_work_nvlt_97","text":"《方言》曰：楚謂蜻蛚為蟋蟀，或謂之蛩，南楚謂之王孫，即趣織也。","sortOrder":182},
  {"id":"s_work_nvlt_97_183","chapterId":"ch_work_nvlt_97","text":"《禮記》曰：季夏之月，蟋蟀居壁。","sortOrder":183},
  {"id":"s_work_nvlt_97_184","chapterId":"ch_work_nvlt_97","text":"蔡邕《月令章句》曰：蟋蟀虫名，斯螽莎雞之類，世謂之蜻蛚。","sortOrder":184},
  {"id":"s_work_nvlt_97_185","chapterId":"ch_work_nvlt_97","text":"《毛詩》曰：蟋蟀在堂，歲聿雲暮。","sortOrder":185},
  {"id":"s_work_nvlt_97_186","chapterId":"ch_work_nvlt_97","text":"《詩義疏》曰：蟋蟀似蝗而小，正黑，目有光泽，如漆，有角翅，幽州人謂之趣織，督促之言也，里語趣織鳴，嬾婦驚。","sortOrder":186},
  {"id":"s_work_nvlt_97_187","chapterId":"ch_work_nvlt_97","text":"《京房占》曰：七月建申，律為夷則，蟋蟀鳴。","sortOrder":187},
  {"id":"s_work_nvlt_97_188","chapterId":"ch_work_nvlt_97","text":"【賦】晉盧諶蟋蟀賦曰：何茲虫之資生，亦靈和之攸授，享神氣之么草，體含容之微陋，喓喓咧咧，翾翾，［句有脱文。］候日月之代謝，知時運之斡遷。","sortOrder":188},
  {"id":"s_work_nvlt_97_189","chapterId":"ch_work_nvlt_97","text":"◇尺蠖","sortOrder":189},
  {"id":"s_work_nvlt_97_190","chapterId":"ch_work_nvlt_97","text":"《爾雅》曰：蠖，尺蠖。","sortOrder":190},
  {"id":"s_work_nvlt_97_191","chapterId":"ch_work_nvlt_97","text":"《易》曰：尺蠖之屈，以求信也。","sortOrder":191},
  {"id":"s_work_nvlt_97_192","chapterId":"ch_work_nvlt_97","text":"《晏子》曰：絃章謂景公曰：尺蠖食黃即身黃，食蒼即身蒼。","sortOrder":192},
  {"id":"s_work_nvlt_97_193","chapterId":"ch_work_nvlt_97","text":"【賦】宋鮑昭尺蠖賦曰：智哉尺蠖，觀機而作，伸非向厚，诎非令薄，當靜泉停，遇躁風驚，起軒驅以曠跨，伏累氣而併形，故身，不豫讬，地無前期，動靜就觀，於物消息，各隨乎時，從方而應，何慮何思。","sortOrder":193},
  {"id":"s_work_nvlt_97_194","chapterId":"ch_work_nvlt_97","text":"【贊】晉郭璞尺蠖贊曰：貴有可賤，賤有可珍，嗟茲尺蠖，體此屈申，論配龍蛇，見叹聖人。","sortOrder":194},
  {"id":"s_work_nvlt_97_196","chapterId":"ch_work_nvlt_97","text":"《爾雅》曰：蠪朾螘，［赤驳蚍蜉。］螱飛蚁，［有翅者。］其子蚳，［蚁卵。］《山海經》曰：朱蚁，其状如蚁，［蚁蚍蜉也。］在崑崙墟。","sortOrder":196},
  {"id":"s_work_nvlt_97_197","chapterId":"ch_work_nvlt_97","text":"《禮記》曰：暇脩蚳醢。","sortOrder":197},
  {"id":"s_work_nvlt_97_198","chapterId":"ch_work_nvlt_97","text":"《大戴禮》曰：十二月玄駒贲，玄駒者蚁也，贲者走於地中也。","sortOrder":198},
  {"id":"s_work_nvlt_97_199","chapterId":"ch_work_nvlt_97","text":"《抱朴子》曰：蚁有兼弱之智。","sortOrder":199},
  {"id":"s_work_nvlt_97_200","chapterId":"ch_work_nvlt_97","text":"又，周髀家雲，天圓如張蓋，地方如棋局，天旁轉，如推磨而左行，日月右行，隨天右轉，故日月實東行，而天牵之以西没，譬之於蚁行磨之上，磨左旋而蚁右去，磨疾而蚁遲，故不得隨磨左回焉。","sortOrder":200},
  {"id":"s_work_nvlt_97_201","chapterId":"ch_work_nvlt_97","text":"齊諧記曰：富陽董昭之，嘗乘船過錢塘江，中央見有一蚁，著一短芦，芦長二三尺，［原訛尸，據冯校本改。］走一頭回，复向一頭，甚遑遽，昭之曰：此畏死也，欲取著舡，舡中人骂，此是毒螫物，不可長，我當蹹殺之，昭意甚怜此蚁，中夜夢一人，乌衣，從百許人來謝雲，仆不慎墮江，慚君濟活，仆是虫王，君若有急難之日，當見告語，後昭之遇事系獄，蚁領群蚁穴獄，昭遂得免。","sortOrder":201},
  {"id":"s_work_nvlt_97_202","chapterId":"ch_work_nvlt_97","text":"桓公北征孤竹，［本條《太平御覽》九百四十七作韓子。］無水，隰朋曰：蚁冬居山之陽，夏居山之陰，蚁壤守而有水，乃掘，遂得水。","sortOrder":202},
  {"id":"s_work_nvlt_97_203","chapterId":"ch_work_nvlt_97","text":"焦貢［按當作贛，後同。］《易林》曰：震之蹇，蚁封穴戶，大雨相集。","sortOrder":203},
  {"id":"s_work_nvlt_97_204","chapterId":"ch_work_nvlt_97","text":"又曰：蚍蜉戴留，不能上山，却推蹶頓，乃傷其顏。","sortOrder":204},
  {"id":"s_work_nvlt_97_205","chapterId":"ch_work_nvlt_97","text":"《吳錄》曰：九真移風縣，有土赤如膠，人视土知蚁，因墾，以木枝其中，則蚁緣而生漆，堅凝如螳螂子蜱蛸，折漆以染堅凝［二字《太平御覽》九百四十七無。］絮，其色正赤，所謂赤絮，則此膠也。","sortOrder":205},
  {"id":"s_work_nvlt_97_206","chapterId":"ch_work_nvlt_97","text":"《廣志》曰：有飛蚁，有木蚁，古曰玄駒者也。又有黑黃大小數种。","sortOrder":206},
  {"id":"s_work_nvlt_97_207","chapterId":"ch_work_nvlt_97","text":"博物志，蚁知將雨。","sortOrder":207},
  {"id":"s_work_nvlt_97_208","chapterId":"ch_work_nvlt_97","text":"《符子》曰：東海有鼇焉，冠蓬萊而遊於沧海，騰躍而上則幹雲，没而下潛於重泉，有紅蚁者聞而悅，與群蚁相要乎海畔，欲觀鼇之行，月餘未出群作也，數日風止，海中隱淪如{巳山}，其高槩天，或遊而西，群蚁曰：彼之冠山，何異乎我之載粒也，逍遙壤封之巔，歸服乎窟穴之下，此乃物我之適，自已而然，我何用數百里勞形而觀之乎。","sortOrder":208},
  {"id":"s_work_nvlt_97_209","chapterId":"ch_work_nvlt_97","text":"《異苑》曰：桓謙，字敬祖，太元中，忽有人，皆長寸餘，悉被鎧持槊，乘具裝馬，從{巳山}中出，精光耀日，遊走宅上，數百為群，部障指麾，更相撞刺，馬既快，人亦便，能緣機登竈，尋飲食之所，或有切肉，［《太平御覽》九百四十七作肉。］辄來聚力，所遽還入穴，［句有脱文。］蒋山道士朱應子，令作沸湯，浇所入處，寂不复出，因掘之，有斛許大蚁，死在窟中，謙後誅滅。","sortOrder":209},
  {"id":"s_work_nvlt_97_210","chapterId":"ch_work_nvlt_97","text":"【賦】晉郭璞蚍蜉賦曰：惟洪陶之萬殊，賦群形而遍洒，物莫微於崑虫，屬莫賤乎蝼蚁，淫淫奕奕，交错往來，行無遺跡，鶩不動埃，迅雷震而不駭，激風發而不動，虎贲比而不慑，龍劍揮而不恐，乃吞舟而是製，無小大與輕重，因無心以致果，有象乎大勇，出奇膠於九真，流赪液其如血，飾人士之丧具，在四隅而交結，濟濟國［北堂書鈔一百五十八，《太平御覽》九百四十七作濟齊桓。］之窮師，由山東之高垤，感萌陽以潛出，將知水而封穴，伊斯虫之愚昧，乃先識而似悊。","sortOrder":210},
  {"id":"s_work_nvlt_97_211","chapterId":"ch_work_nvlt_97","text":"◇蜘蛛蛸","sortOrder":211},
  {"id":"s_work_nvlt_97_212","chapterId":"ch_work_nvlt_97","text":"《爾雅》曰：蜘蛛，蛛蝥，［北燕謂之毒蝥，齊人呼杜公，江東呼蝃蝥。］","sortOrder":212},
  {"id":"s_work_nvlt_97_213","chapterId":"ch_work_nvlt_97","text":"又曰：〈虫萧〉蛸，長〈虫奇〉。","sortOrder":213},
  {"id":"s_work_nvlt_97_214","chapterId":"ch_work_nvlt_97","text":"又曰土蜘蛛，［在土中布網者。］草蜘蛛，［絡幂草上。］","sortOrder":214},
  {"id":"s_work_nvlt_97_215","chapterId":"ch_work_nvlt_97","text":"《毛詩》曰：〈虫萧〉蛸在戶，［長〈虫奇〉。］","sortOrder":215},
  {"id":"s_work_nvlt_97_216","chapterId":"ch_work_nvlt_97","text":"《廣志》曰：草蜘蛛在草上，色青，土蜘蛛在地上，春行草間，秋系在草，有在器下，有以絲於篱壁間，緣壁捕蠅者，長腳，在壁屋為絡者，則爾雅曰長〈虫奇〉，毛詩之〈虫萧〉蛸也。","sortOrder":216},
  {"id":"s_work_nvlt_97_217","chapterId":"ch_work_nvlt_97","text":"《異苑》曰：陳都［《太平御覽》九百四十八作郡。］殷家養子，名琅，與一婢結好，經年，婢死，後猶來往不絕，心患惛错，其母深察焉，後夕見大蜘蛛緣床就琅，便宴爾怡悅，母取而殺之，琅性理遂解。","sortOrder":217},
  {"id":"s_work_nvlt_97_218","chapterId":"ch_work_nvlt_97","text":"焦貢《易林》曰：未濟之蠱，蜘蛛作網，以伺行旅，青蠅求膏腴，觸我羅城，為網所得，死於網國。","sortOrder":218},
  {"id":"s_work_nvlt_97_219","chapterId":"ch_work_nvlt_97","text":"又曰：井之遯，蜘蛛南北，巡行網罟。","sortOrder":219},
  {"id":"s_work_nvlt_97_220","chapterId":"ch_work_nvlt_97","text":"《符子》曰：公子重耳奔齊，與五臣遊乎大泽之中，見蜘蛛而網，曳繩執豸而食之，公子重耳乃撫仆之手，駐驷而觀之，顧其臣咎犯曰：此虫也，知之德薄矣，而猶役其智布其網，曳其繩執豸以食之，况乎人之智，而不能廓垂天之網，布絡地之繩，以供方丈之御，是曾不如蜘蛛之智，孰不可謂之人乎，咎犯曰：公子慎勿言也，君終行之，則有邦有嗣也。","sortOrder":220},
  {"id":"s_work_nvlt_97_221","chapterId":"ch_work_nvlt_97","text":"【賦】晉成公綏蜘蛛賦曰：獨星懸於浮處，遂設網於四隅，南連大庑，北接華堂，左冯廣厦，右依高廊，吐絲屬絡，布網引綱，鐵羅絡莫，綺错交張，於是蒼蚊夕起，青蠅昏歸，營營群眾，薨薨亂飛，掛翼繞足，鞙絲置围，冲突必獲，犯者無遺。","sortOrder":221},
  {"id":"s_work_nvlt_97_222","chapterId":"ch_work_nvlt_97","text":"◇螳螂","sortOrder":222},
  {"id":"s_work_nvlt_97_223","chapterId":"ch_work_nvlt_97","text":"《爾雅》曰：莫貈，螳螂，蛑，［有斧虫也。］不過螳蠰也，其子蜱蛸，［一名搏耀，螳螂卵。］","sortOrder":223},
  {"id":"s_work_nvlt_97_224","chapterId":"ch_work_nvlt_97","text":"《方言》曰：螳螂謂之髦，或謂之丁，或謂之羊羊。","sortOrder":224},
  {"id":"s_work_nvlt_97_225","chapterId":"ch_work_nvlt_97","text":"《廣雅》曰：芊芊齕肬，螳螂也。","sortOrder":225},
  {"id":"s_work_nvlt_97_226","chapterId":"ch_work_nvlt_97","text":"《禮記》曰：仲夏之月，螳螂生。","sortOrder":226},
  {"id":"s_work_nvlt_97_227","chapterId":"ch_work_nvlt_97","text":"《莊子》曰：螳螂怒臂以拒車轍，不知不勝任也，是才之美者也。","sortOrder":227},
  {"id":"s_work_nvlt_97_228","chapterId":"ch_work_nvlt_97","text":"又曰：莊周遊雕陵之樊，［樊，蕃也。］睹一異鵲，自南方來者，翼廣七尺，目大運寸，［可回一寸。］感［原訛威，據冯校本改，下同。］周之［原訛又，據冯校本改。］顙，而集於栗林，［感，觸也。］莊周曰：此何鳥哉，翼殷不遊，［殷，曲大也。］目大不睹，［不見人者。］褰裳攫步，［疾行也。］執彈而留之，睹一蝉而方得美荫，而忘其身，螳螂執翳，且將捕之，見得而忘其形，異鵲從而利之，見利而忘其真，莊周悚然曰：物固相累，二類相召也，扌良焉而反走，虞人逐之。","sortOrder":228},
  {"id":"s_work_nvlt_97_229","chapterId":"ch_work_nvlt_97","text":"《韓詩外傳》曰：齊莊公出獦，有螳螂舉足，將且轉，［《太平御覽》九百四十六作將搏其輪。］問其御曰：此何虫，對曰：此螳螂也，為虫知進而不量力，其輕執敵，公曰：此為天下勇虫矣，回車避之，勇士歸之焉。","sortOrder":229},
  {"id":"s_work_nvlt_97_230","chapterId":"ch_work_nvlt_97","text":"《禮記》曰：鄭註雲，螳螂，螵蛸母也，王瓒問，曰：爾雅雲，莫貉［太平御覽九百四十六作貈。］螳螂，同類物也，今沛魯以南，謂之螳螂，三河之域，謂之螳蠰，燕趙之际，謂之食眈，［御覽作肬。］齊濟以東，謂之馬敫，然多名其子則同雲螵蛸，是以註雲螳螂螵蛸母也。","sortOrder":230},
  {"id":"s_work_nvlt_97_231","chapterId":"ch_work_nvlt_97","text":"【賦】晉成公綏螳螂賦曰：仰乃茂陰，俯緣條枝，冠角峨峨，足翅岐岐，尋乔木而上缀，從蔓草而下垂，戢翼鷹峙，延頸鵠望，推翳徐翘，舉斧高抗，鳥伏蛇騰，鶴击隼放，俯飛蝉而奋猛，臨蟪蛄而逞壮，距車輪而軒翥，固齊侯之所尚，乃［原訛刀，據冯校本改。］有翩翩黃雀，舉翮高揮，連翔枝幹，或鳴或飛，睹茲螳螂，將以療飢，厲觜胁翼，其往如歸。","sortOrder":231},
  {"id":"s_work_nvlt_97_232","chapterId":"ch_work_nvlt_97","text":"【贊】晉郭璞螳螂贊曰：螳螂飛虫，揮斧奋臂，當轍不回，可踐不避，勇士致毙，厲之以義。","sortOrder":232},
  {"id":"s_work_nvlt_97_233","chapterId":"ch_work_nvlt_97","text":"《藝文類聚》　唐·欧陽詢","sortOrder":233},
  {"id":"s_work_nvlt_98_1","chapterId":"ch_work_nvlt_98","text":"卷九十八祥瑞部上","sortOrder":1},
  {"id":"s_work_nvlt_98_2","chapterId":"ch_work_nvlt_98","text":"○祥瑞慶雲甘露木連理木芝龍麟","sortOrder":2},
  {"id":"s_work_nvlt_98_3","chapterId":"ch_work_nvlt_98","text":"◇祥瑞","sortOrder":3},
  {"id":"s_work_nvlt_98_4","chapterId":"ch_work_nvlt_98","text":"《風角占》曰：福先見曰祥。","sortOrder":4},
  {"id":"s_work_nvlt_98_5","chapterId":"ch_work_nvlt_98","text":"《字林》曰：禎，祥也，福也。","sortOrder":5},
  {"id":"s_work_nvlt_98_6","chapterId":"ch_work_nvlt_98","text":"《禮記》曰：麟鳳龟龍，謂之四靈，四靈以為畜，則獸不狘。","sortOrder":6},
  {"id":"s_work_nvlt_98_7","chapterId":"ch_work_nvlt_98","text":"又曰：聖王用民必順，使無水旱崑虫之灾，民無凶飢妖孽之疾，天不愛其道，地不愛其寶，人不愛其情，是以天降甘露，地出醴泉，山出器車，［山出銀瓮丹甑之器，及人象車也。］河出馬圖，鳳皇麒麟，皆在郊藪，龟龍在宮沼，其餘鳥獸之卵胎，皆可俯而窥也，則是無故，先王能修禮以達義，體信以達順，此順之實也。","sortOrder":7},
  {"id":"s_work_nvlt_98_8","chapterId":"ch_work_nvlt_98","text":"《白虎通》曰：天下太平，符瑞所以來至者，以為王者承天順理，調和陰陽，陰陽和，萬物序，休氣充塞，故符瑞併臻，皆應德而至，德及天，即斗極明，日月光，甘露降，德至地，即嘉禾生，蓂荚起，德至鳥獸，即鳳皇翔，鸞鳥舞，麒麟臻，狐九尾，雉白首，白鹿見，德至山陵，即景雲出，芝實茂，陵出黑丹，山出器車，泽出神馬，德至淵泉，即黃龍見，醴泉涌，河出龍圖，雒出龟書，江出大貝，海出名珠，德至八方，即祥風至，鍾律調，四夷化，越裳來，孝道至，即萐蒲出庖厨，不搖自扇，於飲食清涼，助供養也，繼嗣平，即賓連生於房戶，賓連者，木名也，連累相承，故生於房戶，象繼嗣也，日歷得其分，即蓂荚生於階間，蓂荚者，树名也，月一日一荚生，十五日畢，至十六日，一荚去，故俠階而生，以明日月也，賢不肖位不逾，即平露生於庭，平露者，树名也，官位得其人，即生，不得其人，即死矣，狐九尾何，狐死首丘，不忘本也，明安不忘危也，必九尾者，九配得其所，子孫繁息也，於尾者，明後當盛也，景星者，大星也，月或不見，景星常見，可以夜作者，益於民人也，甘露者，美露也，降則物無不盛，朱草者，赤草也，可以染絳，別尊卑也，醴泉者，美泉也，状如醴酒，可以養老，嘉禾者，大禾也，成王之時，有三苗貫桑而生，同為一穗，大幾盈車，長幾充箱，民有得而上之者，成王召周公而問之，曰：三苗為一穗，意天下其和為一乎，後果有越裳氏重譯而來矣。","sortOrder":8},
  {"id":"s_work_nvlt_98_9","chapterId":"ch_work_nvlt_98","text":"《春秋演孔圖》曰：趣作法，聖没，周姬亡，彗東出，秦政起，胡破術，書記散，孔不絕，［此魯端門血書，十三年冬，有星勃東方，說題曰：麟得之月，天當有血書端門，子夏至期往视，逢一郎，言門有血書，往寫之。］血蜚，鳥化為帛，鳥消書出，署曰演孔圖。","sortOrder":9},
  {"id":"s_work_nvlt_98_10","chapterId":"ch_work_nvlt_98","text":"《東觀漢記》曰：光武中元元年，上幸長安，祠長陵，還洛陽宮，是時醴泉出於京師，郡國飲醴泉者，痼疾皆愈，獨眇蹇者不差。","sortOrder":10},
  {"id":"s_work_nvlt_98_11","chapterId":"ch_work_nvlt_98","text":"又曰：有赤草生於水涯，郡國上甘露降，群臣上言，地祇靈應而朱草萌，宜命太史撰具郡國所上，上遂不聽，是以史官鮮記焉。","sortOrder":11},
  {"id":"s_work_nvlt_98_12","chapterId":"ch_work_nvlt_98","text":"又曰：章帝元和二年，鳳皇三十九，麒麟五十一，白虎二十九，黃龍四，青龍，黃鵠，鸞鳥，神馬，神雀，九尾狐，三足乌，赤乌，白兔，白鹿，白燕，白鵲，甘露，嘉瓜，秬秠，明珠，芝英，華平，朱草，木連理實，日月不絕，載於史官，不可勝紀。","sortOrder":12},
  {"id":"s_work_nvlt_98_13","chapterId":"ch_work_nvlt_98","text":"《論衡》曰：儒者論太平瑞應，皆言氣物卓異，朱草醴泉，祥風甘露，景星嘉禾，萐蒲蓂荚屈軼之屬。又言山出車，泽出馬，男女異路，市無二价，耕者讓畔，班白不題挈，關梁不閉，道不虜掠，風不鳴條，雨不破塊，五日一風，十日一雨，其盛茂者，致黃龍麒麟鳳皇，夫儒者之言，溢於過實，瑞應之物，或無失言，鳳皇麒麟之屬，大瑞较然，不得增飾，其小瑞徵應，恐多不是，夫風氣雨露，本當和適，言其風祥露甘，風不鳴條，雨不破塊可也，言其五日一風，十日一雨，襃之者也。","sortOrder":13},
  {"id":"s_work_nvlt_98_14","chapterId":"ch_work_nvlt_98","text":"《墨子》曰：赤乌衔珪，降周之岐社，曰：命周文王，伐殷有國，河出錄圖，地出乘黃，天錫武王黃鳥之旗。","sortOrder":14},
  {"id":"s_work_nvlt_98_15","chapterId":"ch_work_nvlt_98","text":"《呂氏春秋》曰：凡帝王將興，天先見祥下民，黃帝天先見大蝼螾，黃帝曰：土氣勝，故其色上黃，其事則土，及禹時，天先見草木秋冬不殺，禹曰：木氣勝，木氣勝，故其色上青，其事則木，湯之時，天先見金刃生八水，湯曰：金氣勝，金氣勝，故其色上白，其事則金，文王時，天先見火，赤鳥衔丹書，集於周社，文王曰：火氣勝，火氣勝，故其色上赤，其事則火。","sortOrder":15},
  {"id":"s_work_nvlt_98_16","chapterId":"ch_work_nvlt_98","text":"《淮南子》曰：天覆以德，地載以樂，樂也其時，不失其序，日月淑清而扬光。","sortOrder":16},
  {"id":"s_work_nvlt_98_17","chapterId":"ch_work_nvlt_98","text":"《晉中興書》曰：昔秦始皇東遊，望氣者雲，五百年後，東南金陵之地，有天子氣，於是始皇改為秣陵，巉北山，絕其势，今建康即秣陵西北界，所巉即建康南淮中也，按始皇東遊之歲，至孫權僣號，四百三十七年，考之年數既不合，挍之基宇又非倫，豈應帝王之符，而見兆於上代乎，有晉金行，奄君四海，金陵之祥，其在斯矣，且秦政東遊，至今五百二十六年，所謂五百年後當有王者也。","sortOrder":17},
  {"id":"s_work_nvlt_98_18","chapterId":"ch_work_nvlt_98","text":"【賦】魏劉劭嘉瑞賦曰：乾坤交泰，嘉瑞降靈，皓雉呈其絜质，素威效其仁形，白兔楊其翰耀，黃龍燿其神精，章光列之焞燿，顯休徵之有成，昔聖王之降瑞，或卓爾而弗經，猶著美於篇籍，貽來業而垂名，實明德之所隆，宜允納而是丁，信無思而不服。又何遠之不寧，方將收麒麟於玄圃，栖鳳皇於軒櫺，舞鸞鳥於中唐，聆鸑鷟之和鳴，弄萐蒲之華芳，玩朱草之丹榮，承靈祚而建基，垂遐福於亿齡，超三五而無儔，與泰初乎齊聲。","sortOrder":18},
  {"id":"s_work_nvlt_98_19","chapterId":"ch_work_nvlt_98","text":"【頌】魏何晏瑞頌曰：若稽古帝魏武，哲钦明文思，罄民生之俊德，懿前烈之極休，先天而天弗违，後天而奉天時，聿迪明命，肇啟皇基，夫居高聽卑，乾之紀也，靡德不酬，坤之理也，故靈符頻繁，眾瑞仍章，通政辰脩，玉燭告祥，和風播烈，景星扬光，應龍遊於華泽，鳳鳥鳴於高岡，麒麟依於圃籍，甝虎類於坰疆，鹿之麌々，載素其色，雉之朝雊，亦白其服，交交黃鳥，信我中霤，儵儵嘉苗，吐穎田畴。","sortOrder":19},
  {"id":"s_work_nvlt_98_20","chapterId":"ch_work_nvlt_98","text":"【表】周王襃上祥瑞表曰：明王孝治，嶽渎所以效靈，至人泽及，風雲以之懸感，是以若霧非霧，天道葉至德之符，似煙非煙，觸石表嘉祥之氣，玄黃萧索之辉，丹紫輪囷之状，豈止唐帝沉璧，氣合金方，姬後望河，形如車蓋。","sortOrder":20},
  {"id":"s_work_nvlt_98_21","chapterId":"ch_work_nvlt_98","text":"◇慶雲","sortOrder":21},
  {"id":"s_work_nvlt_98_22","chapterId":"ch_work_nvlt_98","text":"孫氏《瑞應圖》曰：景雲者，太平之應也，一曰慶雲，非氣非煙，五色氛氲，謂之慶雲。","sortOrder":22},
  {"id":"s_work_nvlt_98_23","chapterId":"ch_work_nvlt_98","text":"《孝經援神契》曰：德至山陵，則景雲出。","sortOrder":23},
  {"id":"s_work_nvlt_98_24","chapterId":"ch_work_nvlt_98","text":"《洛書》曰：蒼帝起，青雲扶日，赤帝起，黃雲扶日，有白雲出自蒼梧，入於大梁。","sortOrder":24},
  {"id":"s_work_nvlt_98_25","chapterId":"ch_work_nvlt_98","text":"《尚書·中候》曰：尧沉璧於河，白雲起，成王觀於河，東雲至。","sortOrder":25},
  {"id":"s_work_nvlt_98_26","chapterId":"ch_work_nvlt_98","text":"《禮斗威儀》曰：其君乘水而王，為人黑色大耳，其政和平，時則景雲至。","sortOrder":26},
  {"id":"s_work_nvlt_98_27","chapterId":"ch_work_nvlt_98","text":"《春秋合成圖》曰：尧母慶都，蓋大帝之女，生於斗維之野，常在三河東南，天大雷電，有血流润大石之中，生慶都，長丈，形象大帝，常為黃雲覆蓋之，蔑食不飢，年二十，寄伊長家，無夫，出觀三河，奄然陰雨風，赤龍與慶都合，有娠而生尧也。","sortOrder":27},
  {"id":"s_work_nvlt_98_28","chapterId":"ch_work_nvlt_98","text":"《尚書大傳》曰：於時俊乂百工，相和而歌卿雲，卿雲［二字衍。］帝乃倡之。","sortOrder":28},
  {"id":"s_work_nvlt_98_29","chapterId":"ch_work_nvlt_98","text":"《史記》曰：若煙非煙，若雲非雲，鬱鬱紛紛，萧索輪囷，是謂慶雲，慶雲見，嘉氣也。","sortOrder":29},
  {"id":"s_work_nvlt_98_30","chapterId":"ch_work_nvlt_98","text":"《漢書》：高祖遊芒碭山，上常有雲氣。","sortOrder":30},
  {"id":"s_work_nvlt_98_31","chapterId":"ch_work_nvlt_98","text":"又曰：武帝封泰山，夜有光，晝有白雲起封中。","sortOrder":31},
  {"id":"s_work_nvlt_98_32","chapterId":"ch_work_nvlt_98","text":"又曰：宣帝祠甘泉，紫雲從西北來，散於殿前。","sortOrder":32},
  {"id":"s_work_nvlt_98_33","chapterId":"ch_work_nvlt_98","text":"《漢武故事》曰：上幸梁父，祠地，上親拜，用樂焉，其日上有白雲。又有呼萬歲者，禪肅然，白雲為蓋。","sortOrder":33},
  {"id":"s_work_nvlt_98_34","chapterId":"ch_work_nvlt_98","text":"《魏志》曰：文帝生時，有雲氣青色，圓如車蓋，當其上終日，望氣者以為至貴之證，《春秋演孔圖》曰：黃帝之將興，黃雲升於堂，文命之候，玄龍衔雲，於陽［按當作湯，見本書卷一雲篇。］白雲入房。","sortOrder":34},
  {"id":"s_work_nvlt_98_35","chapterId":"ch_work_nvlt_98","text":"《春秋運斗枢》曰：天枢得則景雲出。","sortOrder":35},
  {"id":"s_work_nvlt_98_36","chapterId":"ch_work_nvlt_98","text":"又曰：天子孝則景雲出遊。","sortOrder":36},
  {"id":"s_work_nvlt_98_37","chapterId":"ch_work_nvlt_98","text":"車頻秦書曰：符堅立，有黃雲五色，回繞台觀，時以為景雲。","sortOrder":37},
  {"id":"s_work_nvlt_98_38","chapterId":"ch_work_nvlt_98","text":"【贊】宋孝武帝景陽樓慶雲贊曰：非煙非雲，曳紫流光，懸華曜藻，奄鬱台堂，粵予不明，震乎珍祥，積慶有文，靈貺無疆。","sortOrder":38},
  {"id":"s_work_nvlt_98_39","chapterId":"ch_work_nvlt_98","text":"◇甘露","sortOrder":39},
  {"id":"s_work_nvlt_98_40","chapterId":"ch_work_nvlt_98","text":"《廣雅》曰：汲汲瀼瀼，湛湛泥泥，露濬也。","sortOrder":40},
  {"id":"s_work_nvlt_98_41","chapterId":"ch_work_nvlt_98","text":"《山海經》曰：軒丘鳳卵，民食之，甘露，民飲之。","sortOrder":41},
  {"id":"s_work_nvlt_98_42","chapterId":"ch_work_nvlt_98","text":"《禮記》曰：聖王所以順而弗悖也，天降甘露，地出醴泉。","sortOrder":42},
  {"id":"s_work_nvlt_98_43","chapterId":"ch_work_nvlt_98","text":"《鶡冠子》曰：聖人之德，上及太清，下及太寧，中及萬靈，則膏露下，呂氏春秋曰：甘露時雨，不私一物。","sortOrder":43},
  {"id":"s_work_nvlt_98_44","chapterId":"ch_work_nvlt_98","text":"又曰：伊尹說湯曰：水之美者，三危之露，其色若紫。","sortOrder":44},
  {"id":"s_work_nvlt_98_45","chapterId":"ch_work_nvlt_98","text":"《論衡》曰：儒者論甘露，言其味甘，必然也，若甘雨，霁而陰翳者，謂之甘雨，謂水味之甘也。","sortOrder":45},
  {"id":"s_work_nvlt_98_46","chapterId":"ch_work_nvlt_98","text":"《三辅故事》曰：漢武以銅作承露盤，高二十丈，七围，上有仙人掌，承露，和玉屑，欲以求仙也。","sortOrder":46},
  {"id":"s_work_nvlt_98_47","chapterId":"ch_work_nvlt_98","text":"《漢武故事》曰：承甘露盤，仙人掌擎玉杯，為取雲表之露。","sortOrder":47},
  {"id":"s_work_nvlt_98_48","chapterId":"ch_work_nvlt_98","text":"《東觀漢記》曰：明帝夜夢見先帝太後，覺，悲不能寐，明旦上陵，树葉有甘露，上令百官采之。","sortOrder":48},
  {"id":"s_work_nvlt_98_49","chapterId":"ch_work_nvlt_98","text":"謝承《後漢書》曰：吳郡陆閎，為潁川太守，致鳳皇甘露之瑞。","sortOrder":49},
  {"id":"s_work_nvlt_98_50","chapterId":"ch_work_nvlt_98","text":"又曰：吳郡沈丰，為零陵太守，到官一年，甘露降泉陵佻陽五縣，流被山林，膏润草木。","sortOrder":50},
  {"id":"s_work_nvlt_98_51","chapterId":"ch_work_nvlt_98","text":"又曰：山陽百里嵩，為濟南相，甘露降於郡，安帝嘉之，徵祥拜大鸿臚。","sortOrder":51},
  {"id":"s_work_nvlt_98_52","chapterId":"ch_work_nvlt_98","text":"又曰：百里嵩為徐州刺史，甘露再降廳事前树。","sortOrder":52},
  {"id":"s_work_nvlt_98_53","chapterId":"ch_work_nvlt_98","text":"《神異經》曰：西北海外，有人長二千里，但日飲天酒，天酒，甘露也。","sortOrder":53},
  {"id":"s_work_nvlt_98_54","chapterId":"ch_work_nvlt_98","text":"《漢書》曰：元康元年，甘露降未央宮，大赦，以甘露連降，改年為甘露。","sortOrder":54},
  {"id":"s_work_nvlt_98_55","chapterId":"ch_work_nvlt_98","text":"《白虎通》曰：甘露，美露也，降則物無不盛。","sortOrder":55},
  {"id":"s_work_nvlt_98_56","chapterId":"ch_work_nvlt_98","text":"《五經通義》曰：和氣津凝為露，露從地生。","sortOrder":56},
  {"id":"s_work_nvlt_98_57","chapterId":"ch_work_nvlt_98","text":"《古今註》曰：光武建武二十年，甘露下日南朱梧，積四十五日。","sortOrder":57},
  {"id":"s_work_nvlt_98_58","chapterId":"ch_work_nvlt_98","text":"《魏略》曰：文帝欲受禪，郡國奏甘露三十七降。","sortOrder":58},
  {"id":"s_work_nvlt_98_59","chapterId":"ch_work_nvlt_98","text":"《晉中興徵祥說》曰：王者德至，天氣感而甘露降，郡縣甘露七十，降谯，降盱眙，方七十五畝。","sortOrder":59},
  {"id":"s_work_nvlt_98_60","chapterId":"ch_work_nvlt_98","text":"《抱朴子》曰：何以知天上不有甘露之淵，須太平而洒之，地中不有醴泉之源，待有道而涌之耶。","sortOrder":60},
  {"id":"s_work_nvlt_98_61","chapterId":"ch_work_nvlt_98","text":"孫氏《瑞應圖》曰：甘露者，神露之精也，其味甘，王者和氣茂，則甘露降於草木，一本曰：食之令人寿，一本曰：耆老得敬，則松柏受甘露，尊賢愛老，不失細微，則竹{⺮韦}受甘露。","sortOrder":61},
  {"id":"s_work_nvlt_98_62","chapterId":"ch_work_nvlt_98","text":"【詩】北齊邢子才應詔甘露詩曰：膏露且漸洽，凝液汭旍旗，草木盡霑被，玉散复珠霏，誰謂穹昊遠，道合若應機。","sortOrder":62},
  {"id":"s_work_nvlt_98_63","chapterId":"ch_work_nvlt_98","text":"【頌】北齊邢子才甘露頌曰：歷選列辟，逖聽前聞，三才易統，五運相君，皇極攸序，庶類以分，乃忠乃敬，或质或文，［其一。］赫矣景命，蒸哉上聖，大德大名，至道無競，川停嶽路，雲臨水鏡，望日齊明，瞻天比映，［其二。］功深微禹，業隆作周，英華內積，文教外修，廣输四海，堤封十洲，紫川北註，赤水南流，［其三。］宸居兩楹，恭己萬國，聖敬日漸，王猷允塞，禮有大成，樂無慚德，用天之道，順帝之則，［其四。］政平民豫，歲稔時和，九功惟叙，九叙惟歌，風輪蹍漢，毛舟沉河，玉龟出沼，鳴鳳在阿，［其五。］休徵屢動，感極回天，流甘委素，玉润冰鮮，蜜房下結，珠琲上懸，布濩林野，洒散旌旃，［其六。］日月已明，宇宙已廓，鼓缶成詠，挹水為樂，以為玄黃，猶參沃若，取慰天壤，用忘溝壑，［其七。］","sortOrder":63},
  {"id":"s_work_nvlt_98_64","chapterId":"ch_work_nvlt_98","text":"魏陳王曹植露盤頌曰：明帝鑄承露盤，茎長十二丈，大十围，上盤径四尺，下盤径五尺，銅龍繞其根，龍身長一丈，背負兩子，自立於芳林園，甘露仍降，使王為頌銘。","sortOrder":64},
  {"id":"s_work_nvlt_98_65","chapterId":"ch_work_nvlt_98","text":"【詔】魏明帝與東阿王詔曰：昔先帝時，甘露盤以來，甘露复降芳林園仁寿殿前。","sortOrder":65},
  {"id":"s_work_nvlt_98_66","chapterId":"ch_work_nvlt_98","text":"【表】晉范汪在東陽郡表曰：瑞日所統長山諸縣，林中木葉上，朝有凝露，其味如蜜，夕乃溜地，耆老鹹謂甘露。","sortOrder":66},
  {"id":"s_work_nvlt_98_67","chapterId":"ch_work_nvlt_98","text":"【議】蔡謨答蘭台議曰：被符宣令贺甘露，至不朝者，天雨不朝，禮也，今不朝，則不應贺。","sortOrder":67},
  {"id":"s_work_nvlt_98_68","chapterId":"ch_work_nvlt_98","text":"【啟】晉翟铿啟庾翼述甘露曰：甘露降學堂柳树，與幹吏共嘗，味極甜，宜表贺，翼答曰：甘露自古佳祥，而頃天下多故，何以致此，且其味尚薄，未知瑞應不，而近得一白兔，尚羸小，且養之，併上。","sortOrder":68},
  {"id":"s_work_nvlt_98_69","chapterId":"ch_work_nvlt_98","text":"◇木連理","sortOrder":69},
  {"id":"s_work_nvlt_98_70","chapterId":"ch_work_nvlt_98","text":"《瑞應圖》曰：木連理，王者德化洽，八方合為一家，則木連理，一本曰：不失小民心則生。","sortOrder":70},
  {"id":"s_work_nvlt_98_71","chapterId":"ch_work_nvlt_98","text":"《孝經援神契》曰：德至於草木，則木連理。","sortOrder":71},
  {"id":"s_work_nvlt_98_72","chapterId":"ch_work_nvlt_98","text":"《禮斗威儀》曰：君乘木而王，其政升平，時則松柏為常生。","sortOrder":72},
  {"id":"s_work_nvlt_98_73","chapterId":"ch_work_nvlt_98","text":"《京房易傳》曰：木同本異枝，其君有慶，鄰邑來附者，吉木生於君屋，上及朝廷，其君聖，子木王而有實，其國有慶，木生於城胁，一围以上，長數丈，此謂城強，其君大昌。","sortOrder":73},
  {"id":"s_work_nvlt_98_74","chapterId":"ch_work_nvlt_98","text":"《東觀漢記》曰：安帝延和［按當依東觀漢記三作光。］三年，衛縣木連理。又其年，定陵縣木連理。","sortOrder":74},
  {"id":"s_work_nvlt_98_75","chapterId":"ch_work_nvlt_98","text":"袁山松《漢書》曰：建和二年，河東木連理。","sortOrder":75},
  {"id":"s_work_nvlt_98_76","chapterId":"ch_work_nvlt_98","text":"《魏略》曰：文帝嗣立為魏王，是歲天下奏醴泉涌，木連理。","sortOrder":76},
  {"id":"s_work_nvlt_98_77","chapterId":"ch_work_nvlt_98","text":"幹寶《晉紀》曰：武帝自鹹寧三年，至太康元年，木連理八生。","sortOrder":77},
  {"id":"s_work_nvlt_98_78","chapterId":"ch_work_nvlt_98","text":"《晉中興徵祥說》曰：王者德泽純洽，八方同一，則木連理，連理者，仁木也，或異枝還合，或兩树共合，建元［湯球辑晉中興書雲當作武。］元年，木連理四，一生膏［湯辑本雲當作嵩。］山，一生武昌，一生汝陰，一生汝陽，泰興元年。又生武昌。","sortOrder":78},
  {"id":"s_work_nvlt_98_79","chapterId":"ch_work_nvlt_98","text":"【頌】湛方生木連理頌曰：相彼神奇，遠見禎祥，同根連柯，本枝俱昌，皇基增構，靈祚惟長，運隆周室，道均三王，丕顯弈世，休風載扬。","sortOrder":79},
  {"id":"s_work_nvlt_98_80","chapterId":"ch_work_nvlt_98","text":"【表】晉范甯為豫章郡表曰：永脩公國相萬主解列，到縣巡行邑治，縣西北出二里，有林，中兩桐树，下根相去一丈，上枝相去丈八，連合成一。","sortOrder":80},
  {"id":"s_work_nvlt_98_81","chapterId":"ch_work_nvlt_98","text":"◇木芝","sortOrder":81},
  {"id":"s_work_nvlt_98_82","chapterId":"ch_work_nvlt_98","text":"《爾雅》曰：菌，芝也。","sortOrder":82},
  {"id":"s_work_nvlt_98_83","chapterId":"ch_work_nvlt_98","text":"《說文》曰：芝，神草也。","sortOrder":83},
  {"id":"s_work_nvlt_98_84","chapterId":"ch_work_nvlt_98","text":"《本草經》曰：赤芝一名丹芝，黃芝一名金芝，白芝一名玉芝，黑芝一名玄芝，紫芝一名木芝。","sortOrder":84},
  {"id":"s_work_nvlt_98_85","chapterId":"ch_work_nvlt_98","text":"《瑞應圖》曰：芝英者，王者親延耆養老，有道則生。","sortOrder":85},
  {"id":"s_work_nvlt_98_86","chapterId":"ch_work_nvlt_98","text":"《離骚》［《太平御覽》九百八十六作九歌。］曰：采三秀兮於山涧。［三秀芝也。］","sortOrder":86},
  {"id":"s_work_nvlt_98_87","chapterId":"ch_work_nvlt_98","text":"《孝經援神契》曰：德至於草木，則芝草生。","sortOrder":87},
  {"id":"s_work_nvlt_98_88","chapterId":"ch_work_nvlt_98","text":"又曰：善養老則芝茂。","sortOrder":88},
  {"id":"s_work_nvlt_98_89","chapterId":"ch_work_nvlt_98","text":"《春秋運斗枢》曰：瑤光得陵山黑芝。","sortOrder":89},
  {"id":"s_work_nvlt_98_90","chapterId":"ch_work_nvlt_98","text":"《漢書》：武帝元封六年詔曰：甘泉宮中產芝九茎，連葉，上帝博臨，不異下房，其赦天下，賜雲陽都百戶牛酒，作芝房之歌。","sortOrder":90},
  {"id":"s_work_nvlt_98_91","chapterId":"ch_work_nvlt_98","text":"又曰：宣帝神雀元年，金芝九茎，產於涵德殿銅池中。","sortOrder":91},
  {"id":"s_work_nvlt_98_92","chapterId":"ch_work_nvlt_98","text":"《淮南子》：巫山之上，從風縱火，紫芝與萧艾俱死。","sortOrder":92},
  {"id":"s_work_nvlt_98_93","chapterId":"ch_work_nvlt_98","text":"《漢武內傳》曰：西王母之仙上藥，有大真紅芝草。","sortOrder":93},
  {"id":"s_work_nvlt_98_94","chapterId":"ch_work_nvlt_98","text":"《東觀漢記》曰：光和四年，郡國上芝英。","sortOrder":94},
  {"id":"s_work_nvlt_98_95","chapterId":"ch_work_nvlt_98","text":"《續漢書》曰：章帝建初五年，零陵獻芝草。","sortOrder":95},
  {"id":"s_work_nvlt_98_96","chapterId":"ch_work_nvlt_98","text":"《論衡》曰：建初三年，零陵泉陵縣女子傳［《太平御覽》八百七十三作愽寧二字，按愽當作傅。］宅內，生芝五本，長者尺四寸，短者七八寸，茎葉紫色，蓋紫芝也，太守沈酆，遣門下掾奉獻，皇帝悅怿，賜錢衣，詔會公卿國上計吏，皆以芝草告示天下。","sortOrder":96},
  {"id":"s_work_nvlt_98_97","chapterId":"ch_work_nvlt_98","text":"《古今註》：章帝元和二年，芝生沛，如人冠，建初五年，芝出潁川，常以六月中生一葉，五歲五重，春青夏紫，秋白冬黑色，十月後，黃氣出上，尺五寸。","sortOrder":97},
  {"id":"s_work_nvlt_98_98","chapterId":"ch_work_nvlt_98","text":"《仲長子》曰：哀帝時，有異物，生於長樂宮延年廄後東庑树，及永巷南園合歡树，議者以為芝草。","sortOrder":98},
  {"id":"s_work_nvlt_98_99","chapterId":"ch_work_nvlt_98","text":"《抱朴子》曰：芝有石芝木芝草芝肉菌芝，各有百許种，如水精，得而末之，以無心草汁和之，須臾成水，服一升，得千歲。","sortOrder":99},
  {"id":"s_work_nvlt_98_100","chapterId":"ch_work_nvlt_98","text":"又曰：石桂英芝，生名山石穴中，似桂树而實石也，木芝者，松脂淪地千歲，化為茯苓，茯苓萬歲，其上有小木，状似莲葉，名曰木威嘉之，［太平御覽九百八十五作喜芝。］夜视有光，持之甚滑，燒之不燋，帶之辟兵。","sortOrder":100},
  {"id":"s_work_nvlt_98_101","chapterId":"ch_work_nvlt_98","text":"又曰：七明九光芝，皆石也，生臨水之高山石崖之間，状如盤梡，不過径尺以還。","sortOrder":101},
  {"id":"s_work_nvlt_98_102","chapterId":"ch_work_nvlt_98","text":"又曰：肉芝者，謂萬歲蟾蜍，頭上有角，頷下有丹書八字再重，以五月五日中時取之，陰乾百日，以其足畫地，即為流水，帶其左手於身，辟兵，若敵人射己者，弓弩矢皆反還自向也。","sortOrder":102},
  {"id":"s_work_nvlt_98_103","chapterId":"ch_work_nvlt_98","text":"又曰：青雲芝生於名山之陰，大青石間，青蓋三重，上有雲氣覆之，味辛甘，以陰乾食之，令人寿千歲不老，能乘雲通天，見鬼神。","sortOrder":103},
  {"id":"s_work_nvlt_98_104","chapterId":"ch_work_nvlt_98","text":"又曰：黃龍芝，生於神山之中，状如黃龍，味辛甘，以四時采，陰乾治，日食一合，寿萬年，令人光泽。","sortOrder":104},
  {"id":"s_work_nvlt_98_105","chapterId":"ch_work_nvlt_98","text":"又，曰金菌芝，生於名山之陰，金石之間，上有水蓋，茎赤，入秋旬求之，飲其中水，寿千歲，耳目聰明。","sortOrder":105},
  {"id":"s_work_nvlt_98_106","chapterId":"ch_work_nvlt_98","text":"又曰：龍仙芝，状似升龍之類，葉為鱗，其根則如蟠龍，服一株，則寿千歲。","sortOrder":106},
  {"id":"s_work_nvlt_98_107","chapterId":"ch_work_nvlt_98","text":"又曰：紫朱芝，其茎黃，其葉赤，其實如李而紫色，二十四枚，辄相連而垂，如貫珠也。","sortOrder":107},
  {"id":"s_work_nvlt_98_108","chapterId":"ch_work_nvlt_98","text":"又曰：朱草芝，九曲，曲有三葉三實。","sortOrder":108},
  {"id":"s_work_nvlt_98_109","chapterId":"ch_work_nvlt_98","text":"又曰：行山中，見小人乘馬車，長七八寸者肉芝，生取服即仙。","sortOrder":109},
  {"id":"s_work_nvlt_98_110","chapterId":"ch_work_nvlt_98","text":"又曰：蒼山岑石之中赤雲芝，下状如人，竖竖如連鼓，其色如泽，以夏采之，陰乾食之，令人乘雲能上天，觀見八極，通見神明，延寿萬年。","sortOrder":110},
  {"id":"s_work_nvlt_98_111","chapterId":"ch_work_nvlt_98","text":"又曰：月芝，生於名山之陰，崑崙之山，大穀源泉，金石之中。","sortOrder":111},
  {"id":"s_work_nvlt_98_112","chapterId":"ch_work_nvlt_98","text":"又曰：山芝者，韓終所食也，與天地相極，延年寿，通神明矣。","sortOrder":112},
  {"id":"s_work_nvlt_98_113","chapterId":"ch_work_nvlt_98","text":"又曰：火芝，常以夏采之，葉上赤，下茎青，赤松子服之，常在西王母前，隨風上下，往來東西。","sortOrder":113},
  {"id":"s_work_nvlt_98_114","chapterId":"ch_work_nvlt_98","text":"又曰：人芝，生名山之陰，青蓋白茎，陰乾治，食日半合，則使人寿，入水可久也。","sortOrder":114},
  {"id":"s_work_nvlt_98_115","chapterId":"ch_work_nvlt_98","text":"又曰：月精芝，秋生山陽石上，茎青上赤，味辛苦，盛以銅物，十月食之，寿萬歲。","sortOrder":115},
  {"id":"s_work_nvlt_98_116","chapterId":"ch_work_nvlt_98","text":"又曰：黑芝，生於山之陰，大穀中，白蓋赤茎，味甘，秋采之，陰乾，日食，令人身輕齒堅，與天地無極。","sortOrder":116},
  {"id":"s_work_nvlt_98_117","chapterId":"ch_work_nvlt_98","text":"又曰：火芝，生於名山之陽，其色黃泽，大如車蓋。","sortOrder":117},
  {"id":"s_work_nvlt_98_118","chapterId":"ch_work_nvlt_98","text":"又曰：金芝生於金石之中，青蓋茎，味甘辛，以秋取，陰乾治食，令人身有光，寿萬歲。","sortOrder":118},
  {"id":"s_work_nvlt_98_119","chapterId":"ch_work_nvlt_98","text":"又曰：萬年芝，令人不老，延年九千。","sortOrder":119},
  {"id":"s_work_nvlt_98_120","chapterId":"ch_work_nvlt_98","text":"又曰：夜光芝，出於名山之陰，大穀源泉中金石間，上有浮雲翔其上，有五色，有目，如兩日。","sortOrder":120},
  {"id":"s_work_nvlt_98_121","chapterId":"ch_work_nvlt_98","text":"又曰：白雲芝，生於名山之陰，白石上，有白雲覆之，白蓋二重，味辛甘，小苦，以秋采之，陰乾治食，令人身輕齒堅。","sortOrder":121},
  {"id":"s_work_nvlt_98_122","chapterId":"ch_work_nvlt_98","text":"又曰：金芝，生於山，無蓋，青茎，陰乾治，食日一合，不中風雷，令人色光泽也。","sortOrder":122},
  {"id":"s_work_nvlt_98_123","chapterId":"ch_work_nvlt_98","text":"又曰：雲母芝，生於名山之陰，青蓋赤茎，味甘，以季秋竹刀采之，陰乾治食，使人身光，寿千萬歲，醮以牛脯。","sortOrder":123},
  {"id":"s_work_nvlt_98_124","chapterId":"ch_work_nvlt_98","text":"又曰：華芝，生於名山之陽，及出央山大穀源泉水中，赤蓋白茎，上有兩葉三實。","sortOrder":124},
  {"id":"s_work_nvlt_98_125","chapterId":"ch_work_nvlt_98","text":"又曰：鬼芝，青蓋長茎，陰乾屑之，日食五合，所見神明，令人長生。","sortOrder":125},
  {"id":"s_work_nvlt_98_126","chapterId":"ch_work_nvlt_98","text":"【詩】梁庾肩吾芝草詩曰：踟蹰玩芝草，淹留攀桂丛，桂丛方偃蹇，芝葉正玲瓏，如龍复如馬，成闕复成宮，黃金九華發，紫蓋六英通，隱士蒼山北，神仙海六東，隨丹聊变水，獨搖不須風。","sortOrder":126},
  {"id":"s_work_nvlt_98_127","chapterId":"ch_work_nvlt_98","text":"【贊】魏缪袭神芝贊曰：青龍元年，神芝產於長平之習陽，其色丹紫，其质光耀，其長尺有八寸五分，其本围三寸有三分，上別為三幹，分為九枝，散為三十六茎，围率一寸九分，葉径二寸七分，其幹洪纖連屬，有似珊瑚之形，其吐柯載葉，祥明蠲絜，考圖案諜，蓋美乎所同於前代者矣，古瑞命記曰：王者慈仁則芝生，而食之則延年不終，與真人同。又神農氏論芝雲，山川雲雨，五行四時，陰陽晝夜之精，以生五色神芝，皆為聖王休祥焉，自漢孝武顯宗，世號隆盛，而元封永平所紀神芝，方斯蔑如也，且其枝幹條茎，本末相承，乃协於天官之數，非神明其孰為此哉，推其類象，則蓂荚之植階庭，萐莆之生庖，屢视四靈矣，［○句有訛。］乃詔御府，匮而藏之，且盡其形，遂以名園為之贊曰：帝德允臻，厨不難致，［句有訛。］煌煌神芝，吐葩扬榮，曩披其圖，今握其形，永章遐紀，載之頌聲。","sortOrder":127},
  {"id":"s_work_nvlt_98_129","chapterId":"ch_work_nvlt_98","text":"《瑞應圖》曰：黃龍者，四龍之長，四方之正色，神靈之精也，能巨細，能幽明，能短能長，乍存乍亡，王者不漉池而漁，則應和氣而遊於池沼。","sortOrder":129},
  {"id":"s_work_nvlt_98_130","chapterId":"ch_work_nvlt_98","text":"又曰：舜東巡狩，黃龍負圖，置舜前。","sortOrder":130},
  {"id":"s_work_nvlt_98_131","chapterId":"ch_work_nvlt_98","text":"又曰：不眾行，不群處，必待風雨而遊乎青氣之中，遊乎天外之野，出入應命，以時上下，有聖則見，無聖則處。","sortOrder":131},
  {"id":"s_work_nvlt_98_132","chapterId":"ch_work_nvlt_98","text":"《龍魚河圖》曰：天授元始，建帝號，黃龍負圖，從河中出，付黃帝，帝令侍臣寫以示天下。","sortOrder":132},
  {"id":"s_work_nvlt_98_133","chapterId":"ch_work_nvlt_98","text":"又曰：黃龍從洛水出，詣虞舜，鱗甲成字，令左右寫文竟，龍去。","sortOrder":133},
  {"id":"s_work_nvlt_98_134","chapterId":"ch_work_nvlt_98","text":"《河圖》曰：舜以太尉即位，與三公臨觀，黃龍五采，負圖出舜前，以黃玉為柙，玉檢金繩，芝為泥，章曰：天黃帝符玺。","sortOrder":134},
  {"id":"s_work_nvlt_98_135","chapterId":"ch_work_nvlt_98","text":"《尚書·中候》曰：舜沉璧於河，榮光休至，黃龍負卷舒圖，出入壇畔。","sortOrder":135},
  {"id":"s_work_nvlt_98_136","chapterId":"ch_work_nvlt_98","text":"又曰：河龍圖出，雒龟書威，［龟負書而出也，威，則。］赤文像字，以授軒轅。","sortOrder":136},
  {"id":"s_work_nvlt_98_137","chapterId":"ch_work_nvlt_98","text":"《詩含神霧》曰：含始吞赤珠，刻曰：玉英生漢皇，後赤龍感女媧，［《史記》八註作媪。］劉季興也。","sortOrder":137},
  {"id":"s_work_nvlt_98_138","chapterId":"ch_work_nvlt_98","text":"《孝經援神契》曰：德至水泉，則黃龍見者，君之象也。","sortOrder":138},
  {"id":"s_work_nvlt_98_139","chapterId":"ch_work_nvlt_98","text":"又曰：左契曰：天子孝，天龍負圖，地龟出書。","sortOrder":139},
  {"id":"s_work_nvlt_98_140","chapterId":"ch_work_nvlt_98","text":"《呂氏春秋》曰：禹南省方，過江，黃龍負舟。舟中之人，五色無主。禹曰：吾受命於天，竭力養人。生，性也；死，命也。何忧龍哉。龍俯而去。","sortOrder":140},
  {"id":"s_work_nvlt_98_141","chapterId":"ch_work_nvlt_98","text":"《史記》曰：高祖常從王媪武［史記武字下有負字。］贳酒，醉臥，武負王媪見其上常有龍。","sortOrder":141},
  {"id":"s_work_nvlt_98_142","chapterId":"ch_work_nvlt_98","text":"又曰：黃帝土德，黃龍見，夏木，青龍生於郊。","sortOrder":142},
  {"id":"s_work_nvlt_98_143","chapterId":"ch_work_nvlt_98","text":"《漢書》曰：文帝十五年，春，黃龍見成紀，上乃詔議郊祀。","sortOrder":143},
  {"id":"s_work_nvlt_98_144","chapterId":"ch_work_nvlt_98","text":"又曰：宣帝甘露九年，黃龍見新丰，因改年應之，周公沉璧，青龍衔出玄甲圓，［《文選》三十九，江淹上建平王書註作圖。］","sortOrder":144},
  {"id":"s_work_nvlt_98_145","chapterId":"ch_work_nvlt_98","text":"《東觀漢記》曰：黃龍見於河，冯異勸上即位，上曰：我昨夜夢騎赤龍上天，覺寤，心中動悸，異等贺曰：此天命發於神明。","sortOrder":145},
  {"id":"s_work_nvlt_98_146","chapterId":"ch_work_nvlt_98","text":"又曰：章帝元和二年，黃龍四見。","sortOrder":146},
  {"id":"s_work_nvlt_98_147","chapterId":"ch_work_nvlt_98","text":"又曰：安帝延光三年，黃龍見歷城。又見諸縣。","sortOrder":147},
  {"id":"s_work_nvlt_98_148","chapterId":"ch_work_nvlt_98","text":"《古今註》曰：高祖五年，黃龍見華陽池十餘日，九年。又見長安，五鳳四年，黃龍出廣漢，甘露元年，黃龍見新丰，二年，龍見上郡，騰躍五色升天，丞相以下上寿，章帝建初三年，黃龍見汝南項氏田庐中，長五丈餘，高二丈，光耀庐舍，及树皆黃，哀帝永元十年，黃龍見潁川定陵民家井中，色黃，目如鏡。又見巴郡宕渠，草木色皆黃。","sortOrder":148},
  {"id":"s_work_nvlt_98_149","chapterId":"ch_work_nvlt_98","text":"《魏略》曰：文帝欲受禪，郡國奏黃龍十三見，明帝鑄銅黃龍，高四尺，置殿前。","sortOrder":149},
  {"id":"s_work_nvlt_98_150","chapterId":"ch_work_nvlt_98","text":"《魏志》曰：漢嘉平五年，黃龍見谯，光祿大夫乔玄曰：太史令单颺曰：其國當有王者興，不及五十年，當伏［魏志二作复。］見，內黃殷登嘿記之，四十五年，登尚在，黃龍此時見谯，登曰：单颺之言，其验茲乎。","sortOrder":150},
  {"id":"s_work_nvlt_98_151","chapterId":"ch_work_nvlt_98","text":"又曰：青龍元年，春正月甲申，青龍見摩陂井中，二月丁酉，幸摩陂觀龍，於是改摩陂為龍陂。","sortOrder":151},
  {"id":"s_work_nvlt_98_152","chapterId":"ch_work_nvlt_98","text":"《吳志》曰：黃龍元年，樊口武昌併言黃龍見，孫權即位，改年為黃龍，孫休夢乘龍上天，顧不見尾，果立為帝而無後。","sortOrder":152},
  {"id":"s_work_nvlt_98_153","chapterId":"ch_work_nvlt_98","text":"又曰：孫權潘夫人父為吏，坐法死，夫人输織室，權見而異之，召充後宮，得幸有娠，夢有以龍頭授己，以蔽膝受之，遂生孫亮。","sortOrder":153},
  {"id":"s_work_nvlt_98_154","chapterId":"ch_work_nvlt_98","text":"漢晉春秋曰：青龍三年，七月，曹叡崇華殿灾，時郡國有龍九見，故改曰九龍殿。","sortOrder":154},
  {"id":"s_work_nvlt_98_155","chapterId":"ch_work_nvlt_98","text":"《晉中興書》曰：孝武太後李氏，以微賤，入為會稽王宮人，夢兩龍抗膝入懷，太祖［按湯球辑晉中興書作宗。］異而召之，生烈宗。","sortOrder":155},
  {"id":"s_work_nvlt_98_156","chapterId":"ch_work_nvlt_98","text":"沈約《宋書》曰：太史奏西方有天子氣，時太祖為宜都王，镇荆州，後入纂大位，在道，有黑龍躍出，負上所乘舟，左右皆失色，上謂王曇首曰：此乃夏禹所以受天命，我何德以堪之。","sortOrder":156},
  {"id":"s_work_nvlt_98_157","chapterId":"ch_work_nvlt_98","text":"【賦】魏劉劭龍瑞賦曰：太和七年春，龍見摩陂，行自許昌，親往臨觀，形状朅麗，光色燭燿，侍衛左右，鹹與睹焉，自載籍所紀，瑞應之致，或翔集於邦國，卓荦於要荒，未有若斯之著明也，惟殷眺之舊式，乃展義而省方，皇舆發於洛邑，遂巡幸於許昌，憲宸極之天居，建正殿以當陽，有蜿之龍，來遊郊甸，應節合義，象德效仁，煥若羅星，蔚若翠雲，光舄弈以外照，水清景而內分，聖上觀之無射，左右察之既精，聊假物以擬身，忽神化而無形，昔太昊之初化，首帝德以表名，暨明後之隆盛。又降見以扬聲，惟玲獸之玄真，實殊異於四靈，信應龍之道扬，將天飛於泰清。","sortOrder":157},
  {"id":"s_work_nvlt_98_158","chapterId":"ch_work_nvlt_98","text":"【表】魏陳王曹植表曰：臣聞鳳皇复見鄴南，黃龍双出於清泉，聖德至理，以致嘉瑞，將栖鳳於林，龍囿於池，為百姓旦夕之觀也。","sortOrder":158},
  {"id":"s_work_nvlt_98_160","chapterId":"ch_work_nvlt_98","text":"孫氏《瑞應圖》曰：一角獸者，六合同歸則至，一本曰：天下太平則至。","sortOrder":160},
  {"id":"s_work_nvlt_98_161","chapterId":"ch_work_nvlt_98","text":"《春秋運斗枢》曰：機星得其所，則麒麟生，和平合萬民。","sortOrder":161},
  {"id":"s_work_nvlt_98_162","chapterId":"ch_work_nvlt_98","text":"春秋感精符曰：麟一角，明海內共一主也，王者不刳胎，不剖卵，則出於郊，一本雲，德及幽隱，不肖斥退，賢者在位則至，明於興衰，武而仁，仁而有慮，禽獸有埳阱，非時張獵則去，一本曰：明王動則有義，靜則有容，乃見。","sortOrder":162},
  {"id":"s_work_nvlt_98_163","chapterId":"ch_work_nvlt_98","text":"《孝經援神契》曰：德至鳥獸，則麒麟臻。","sortOrder":163},
  {"id":"s_work_nvlt_98_164","chapterId":"ch_work_nvlt_98","text":"《尚書·中候》曰：帝軒提像，配永修機，［永長，修從也，黃帝觀慑提，配而行之，以長從升(尚書中候作斗。)機故也。］麒麟在囿，鸞鳳來儀。","sortOrder":164},
  {"id":"s_work_nvlt_98_165","chapterId":"ch_work_nvlt_98","text":"《禮斗威儀》曰：君乘金而王，其政平，麒麟在郊。","sortOrder":165},
  {"id":"s_work_nvlt_98_166","chapterId":"ch_work_nvlt_98","text":"《鶡冠子》曰：麟者玄枵之獸，陰之精也，德能致之，其精畢至。","sortOrder":166},
  {"id":"s_work_nvlt_98_167","chapterId":"ch_work_nvlt_98","text":"《孫卿子》曰：古之王者，其政好生惡殺，麟在郊野。","sortOrder":167},
  {"id":"s_work_nvlt_98_168","chapterId":"ch_work_nvlt_98","text":"《春秋繁露》曰：恩及羽虫，則麒麟至，張網焚林，則麒麟去。","sortOrder":168},
  {"id":"s_work_nvlt_98_169","chapterId":"ch_work_nvlt_98","text":"《說苑》曰：帝王之著，莫不致四靈焉，德盛則以為畜，治平則至矣，麒麟糜身牛尾，圜頭一角，含信懷義，音中律呂，步中規矩，擇土而踐，彬彬然，動則有容儀。","sortOrder":169},
  {"id":"s_work_nvlt_98_170","chapterId":"ch_work_nvlt_98","text":"《漢書》曰：終軍從上幸擁，［《太平御覽》八百八十九作雍。］獲白麟，一角五蹄。又得奇木，支旁出，辄复合，上異之。","sortOrder":170},
  {"id":"s_work_nvlt_98_171","chapterId":"ch_work_nvlt_98","text":"《毛詩義疏》曰：麟纴身馬足牛尾，黃色，圓蹄一角，角端有肉，音中鍾呂，王者至仁則出。","sortOrder":171},
  {"id":"s_work_nvlt_98_172","chapterId":"ch_work_nvlt_98","text":"《東觀漢記》曰：章帝時，麟五十一見。","sortOrder":172},
  {"id":"s_work_nvlt_98_173","chapterId":"ch_work_nvlt_98","text":"又，安帝三年，潁川上言麟見。","sortOrder":173},
  {"id":"s_work_nvlt_98_174","chapterId":"ch_work_nvlt_98","text":"蔡邕《月令章句》曰：凡麟生於火，遊於土，故修其母，致其子，五行之情性也，视明禮修，則麒麟見。","sortOrder":174},
  {"id":"s_work_nvlt_98_175","chapterId":"ch_work_nvlt_98","text":"王隱《晉書》曰：鹹寧五年，白麒麟見平原。","sortOrder":175},
  {"id":"s_work_nvlt_98_176","chapterId":"ch_work_nvlt_98","text":"又曰：泰始元年，白麟見，群獸皆從，改年曰麟嘉。","sortOrder":176},
  {"id":"s_work_nvlt_98_177","chapterId":"ch_work_nvlt_98","text":"《涼州記》曰：呂光時，張掖金泽有麟見，群獸皆從，改年麟嘉。","sortOrder":177},
  {"id":"s_work_nvlt_98_178","chapterId":"ch_work_nvlt_98","text":"【頌】吳薛綜麟頌曰：懿哉麒麟，惟獸之伯，世平觌景，否則戢足，德以衛身，不布牙角，委體大吳，以昭遐福，天祚聖帝，永享萬國。","sortOrder":178},
  {"id":"s_work_nvlt_98_179","chapterId":"ch_work_nvlt_98","text":"【贊】晉郭璞麟贊曰：麟惟靈獸，與纴同體，智在隱蹤，仁表不抵，孰為來哉，宣尼揮涕。","sortOrder":179},
  {"id":"s_work_nvlt_98_180","chapterId":"ch_work_nvlt_98","text":"《藝文類聚》　唐·欧陽詢","sortOrder":180},
  {"id":"s_work_nvlt_99_1","chapterId":"ch_work_nvlt_99","text":"卷九十九祥瑞部下","sortOrder":1},
  {"id":"s_work_nvlt_99_2","chapterId":"ch_work_nvlt_99","text":"○鳳皇鸞比翼乌雀燕鳩雉馬白鹿狐兔騶虞白狼比肩獸龟魚鼎","sortOrder":2},
  {"id":"s_work_nvlt_99_3","chapterId":"ch_work_nvlt_99","text":"◇鳳皇","sortOrder":3},
  {"id":"s_work_nvlt_99_4","chapterId":"ch_work_nvlt_99","text":"《瑞應圖》曰：鳳皇者，仁鳥也，雄曰鳳，雌曰皇，王者不刳胎剖卵則至。","sortOrder":4},
  {"id":"s_work_nvlt_99_5","chapterId":"ch_work_nvlt_99","text":"《山海經》曰：丹穴之山，有鳥，状如鶴，五色而文，名曰鳳，首文曰德，翼文曰順，背文曰義，膺文曰仁，腹文曰信，是鳥自歌自舞，見則天下安寧。","sortOrder":5},
  {"id":"s_work_nvlt_99_6","chapterId":"ch_work_nvlt_99","text":"《孝經援神契》曰：德至鳥獸，鳳皇翔。","sortOrder":6},
  {"id":"s_work_nvlt_99_7","chapterId":"ch_work_nvlt_99","text":"《禮斗威儀》曰：君乘土而王，其政太平，鳳皇集於苑林。","sortOrder":7},
  {"id":"s_work_nvlt_99_8","chapterId":"ch_work_nvlt_99","text":"《尚書·中候》曰：尧即政七十載，鳳皇止庭，巢阿閣讙树。","sortOrder":8},
  {"id":"s_work_nvlt_99_9","chapterId":"ch_work_nvlt_99","text":"又曰：帝舜雲，朕惟不乂，百獸鳳晨，［百獸率舞，鳳皇司晨鳴也。］","sortOrder":9},
  {"id":"s_work_nvlt_99_10","chapterId":"ch_work_nvlt_99","text":"尚書考靈耀曰：通天文者明，審地理者昌，明者天之時也，昌者地之财也，明王之治，鳳皇下之，春秋感精符曰：王者上感皇天，則鸞鳳至。","sortOrder":10},
  {"id":"s_work_nvlt_99_11","chapterId":"ch_work_nvlt_99","text":"春秋合誠圖曰：黃帝遊玄扈雒水上，與大司馬容光等臨觀，鳳皇衔圖置帝前，帝再拜受圖，［玄扈，石室。］","sortOrder":11},
  {"id":"s_work_nvlt_99_12","chapterId":"ch_work_nvlt_99","text":"《春秋元命包》曰：火離為鳳皇，衔書遊文王之都，故武王受鳳書之紀。","sortOrder":12},
  {"id":"s_work_nvlt_99_13","chapterId":"ch_work_nvlt_99","text":"《春秋運斗枢》曰：天枢得則鳳皇翔。","sortOrder":13},
  {"id":"s_work_nvlt_99_14","chapterId":"ch_work_nvlt_99","text":"樂動聲儀曰：镇聲［《太平御覽》九百十五作星。］不逆行，則鳳皇至。","sortOrder":14},
  {"id":"s_work_nvlt_99_15","chapterId":"ch_work_nvlt_99","text":"樂葉圖曰：五音克諧，各得其倫，則鳳皇至，冠類雞頭，燕喙，蛇頸龍形，麟翼魚尾，五采，不啄生虫。","sortOrder":15},
  {"id":"s_work_nvlt_99_16","chapterId":"ch_work_nvlt_99","text":"《楚辭》曰：獨不見鸞鳳之高翔，大皇之野，循四極而周回，見盛德而後下。","sortOrder":16},
  {"id":"s_work_nvlt_99_17","chapterId":"ch_work_nvlt_99","text":"《孫卿子》曰：詩曰：鳳鳥啾啾，其翼若竽，其聲若箫，有皇有鳳，樂帝之心，此聖不蔽福也。","sortOrder":17},
  {"id":"s_work_nvlt_99_18","chapterId":"ch_work_nvlt_99","text":"又曰：古之王者，其政好生惡殺，鳳在列树。","sortOrder":18},
  {"id":"s_work_nvlt_99_19","chapterId":"ch_work_nvlt_99","text":"《韓子》曰：昔者黃帝合鬼於西大山，鳳皇覆上，作為渎［《太平御覽》九百十五作清。］角。","sortOrder":19},
  {"id":"s_work_nvlt_99_20","chapterId":"ch_work_nvlt_99","text":"《淮南子》曰：昔者二皇，鳳至於庭，［二皇，伏犧神農。］三代，鳳至於門，［三代，尧舜禹也。］周室，鳳至於泽，德弥浇，所至弥遠，德弥精，所至弥近。","sortOrder":20},
  {"id":"s_work_nvlt_99_21","chapterId":"ch_work_nvlt_99","text":"《韓詩外傳》曰：黃帝即位，施聖恩，承大明，一道修德，唯仁是行，宇內和平，未見鳳皇，乃召天老而問之曰：鳳象何如，天老對曰：夫鳳象鸿前而麟後，蛇頸而魚尾，龍文而龟身，燕颣而雞喙，首戴德，頸揭義，背負仁，心入信，翼挟義，足履正，尾系武，小音金，大音鼓，延頸奋翼，五色備舉，黃帝曰：於戲允哉，何敢與焉，於是黃帝乃服黃衣，帶黃紳，戴黃冠，齊於殿中，鳳乃蔽日而至，黃帝降於東階，西面，再拜稽首，皇天降祉，不敢不承命，鳳乃止帝東園，集梧树，食竹實，没身不去。","sortOrder":21},
  {"id":"s_work_nvlt_99_22","chapterId":"ch_work_nvlt_99","text":"《漢書》曰：昭帝元始三年，鳳皇集東海，遣使祠其處。","sortOrder":22},
  {"id":"s_work_nvlt_99_23","chapterId":"ch_work_nvlt_99","text":"又曰：宣帝幸河東之明年春，鳳皇集投栩，［漢書郊祀志作祋祤。］於所集處得玉寶，乃下詔赦天下。","sortOrder":23},
  {"id":"s_work_nvlt_99_24","chapterId":"ch_work_nvlt_99","text":"又曰：鳳皇集上林，乃立鳳皇殿，以答嘉瑞。","sortOrder":24},
  {"id":"s_work_nvlt_99_25","chapterId":"ch_work_nvlt_99","text":"又曰：幸甘泉，郊泰畤，改元曰五鳳。","sortOrder":25},
  {"id":"s_work_nvlt_99_26","chapterId":"ch_work_nvlt_99","text":"又曰：本始元年，鳳皇集膠東，十四年，鳳皇集北海，地節二年，鳳集魯，群鳥從之，詔曰：威鳳為寶，神爵四年，鳳皇十一集杜陵。","sortOrder":26},
  {"id":"s_work_nvlt_99_27","chapterId":"ch_work_nvlt_99","text":"又曰：祠帝後土，鸞鳳翱翔。又集長樂宮東園树上，飛下至地，文章五色，吏民併觀之。","sortOrder":27},
  {"id":"s_work_nvlt_99_28","chapterId":"ch_work_nvlt_99","text":"《東觀漢記》曰：光武生於濟陽，先是鳳皇集濟陽，故宮皆盡曰［二字太平御覽九百十五作畫。］鳳皇，聖瑞始於此。","sortOrder":28},
  {"id":"s_work_nvlt_99_29","chapterId":"ch_work_nvlt_99","text":"又曰：建武十七年，鳳皇出，高八尺九寸，毛羽五采，集潁川，群鳥從之，蓋地數傾，章帝時，鳳皇百三十九見，安帝延光三年，鳳皇集濟南台丞霍穆舍树上，賜帛各有差。","sortOrder":29},
  {"id":"s_work_nvlt_99_30","chapterId":"ch_work_nvlt_99","text":"《琴操》曰：周成王時，天下大治，鳳皇來舞於庭，成王乃援琴而歌曰：鳳皇翔兮於紫庭，餘何德兮以感靈。","sortOrder":30},
  {"id":"s_work_nvlt_99_31","chapterId":"ch_work_nvlt_99","text":"《吳歷》曰：太元元年，有鳥集苑中，似雁，高足長尾，毛羽五色，鹹以為鳳皇，改元為鳳皇元年。","sortOrder":31},
  {"id":"s_work_nvlt_99_32","chapterId":"ch_work_nvlt_99","text":"《異苑》曰：東莞劉穆之，字道民，素居京口，晉隆安中，鳳皇集其庭，相人韦藪謂之曰：子必协贊大猷。","sortOrder":32},
  {"id":"s_work_nvlt_99_33","chapterId":"ch_work_nvlt_99","text":"【賦】晉顧凯之鳳賦曰：望太清以抗思，誕儀鳳之逸群，禀鶉火之靈曜，資和氣之煙煴，允雞喙而燕颣，頸蛇蜿而龍文，厲歸昌於漢陽，發明乎聖君，荷義躡正，雞峙鸿前，比翼交揮，五光備宣，與八風而降時雨，音中鍾律，步則規矩，朱冠赫以双翘，靈质翙其高舉，歷黃冠於招搖，陵帝居之懸圃。","sortOrder":33},
  {"id":"s_work_nvlt_99_34","chapterId":"ch_work_nvlt_99","text":"【頌】吳薛綜鳳頌曰：猗欤石磬，金聲玉振，先王搏拊，以正五音，百獸翔感，儀鳳舞麟，在昔尧舜，斯磬乃臻，宗廟致敬，乃胥來顧，贊扬聖德，上下受祚。","sortOrder":34},
  {"id":"s_work_nvlt_99_35","chapterId":"ch_work_nvlt_99","text":"【贊】晉郭璞鳳鳥贊曰：鳳皇靈鳥，實冠羽群，八象其體，五德其文，附翼來儀，應我聖君。","sortOrder":35},
  {"id":"s_work_nvlt_99_37","chapterId":"ch_work_nvlt_99","text":"《說文》曰：鸞，赤神靈之精也，赤色五采，雞形，鳴中五音，頌聲作則至，周成王時，氐羌獻焉。","sortOrder":37},
  {"id":"s_work_nvlt_99_38","chapterId":"ch_work_nvlt_99","text":"《山海經》曰：女床之山有鳥，其状如翟，名曰鸞鳥，見則天下安寧。","sortOrder":38},
  {"id":"s_work_nvlt_99_39","chapterId":"ch_work_nvlt_99","text":"孫氏《瑞應圖》曰：鸞鳥鳳皇之佐，鳴中五音，肅肅雍雍，嘉則鳴舞，人君行步有容，進退有度，祭祠有禮，親疏有序，則至，一本曰：心識鍾律，鍾律調則至，至則鳴舞以和之。","sortOrder":39},
  {"id":"s_work_nvlt_99_40","chapterId":"ch_work_nvlt_99","text":"《春秋運斗枢》曰：天枢得，鸞鳥集。","sortOrder":40},
  {"id":"s_work_nvlt_99_41","chapterId":"ch_work_nvlt_99","text":"《春秋孔演圖》曰：天子官守以賢舉，則鸞在野。","sortOrder":41},
  {"id":"s_work_nvlt_99_42","chapterId":"ch_work_nvlt_99","text":"《孝經援神契》曰：德至鳥獸，則鸞鳥舞。","sortOrder":42},
  {"id":"s_work_nvlt_99_43","chapterId":"ch_work_nvlt_99","text":"《詩含神霧》曰：德化充塞，照润八冥，則鸞臻也。","sortOrder":43},
  {"id":"s_work_nvlt_99_44","chapterId":"ch_work_nvlt_99","text":"《尚書·中候》曰：黃帝鸞鳥來儀。","sortOrder":44},
  {"id":"s_work_nvlt_99_45","chapterId":"ch_work_nvlt_99","text":"又曰：周公歸政於成王，太平製禮，鸞鳥見。","sortOrder":45},
  {"id":"s_work_nvlt_99_46","chapterId":"ch_work_nvlt_99","text":"《海外經》曰：軒轅之國，清沃之野，鸞鳥自歌。","sortOrder":46},
  {"id":"s_work_nvlt_99_47","chapterId":"ch_work_nvlt_99","text":"《漢書》曰：宣帝祀後土，鸞鳳翱翔。又集長樂宮東園園树。","sortOrder":47},
  {"id":"s_work_nvlt_99_48","chapterId":"ch_work_nvlt_99","text":"《抱朴子》曰：崑崙圖曰：鸞鳥似鳳而白纓，聞樂則蹈節而舞，至則國安寧。","sortOrder":48},
  {"id":"s_work_nvlt_99_49","chapterId":"ch_work_nvlt_99","text":"《東觀漢記》曰：王阜為重泉令，鸞鳥集止學廳，阜使掾汝［《太平御覽》九百十六作沙。］叠為張雅樂，击磬，鳥舉足垂翼，應聲而舞，翱翔縣庭，留十餘日乃去。","sortOrder":49},
  {"id":"s_work_nvlt_99_50","chapterId":"ch_work_nvlt_99","text":"【贊】晉郭璞鸞鳥贊曰：鸞翔女床，鳳出丹穴，拊翼相和，以應聖哲，击石靡詠，韶音其絕。","sortOrder":50},
  {"id":"s_work_nvlt_99_51","chapterId":"ch_work_nvlt_99","text":"◇比翼","sortOrder":51},
  {"id":"s_work_nvlt_99_52","chapterId":"ch_work_nvlt_99","text":"《山海經》曰：有鳥，其状如凫，一翼一目，得［《太平御覽》九百二十七得上有相字。］乃飛，名曰蠻，［色青赤。］見則大水，《爾雅》曰：南方有比翼鳥焉，不比不飛，其名曰鶼鶼。","sortOrder":52},
  {"id":"s_work_nvlt_99_53","chapterId":"ch_work_nvlt_99","text":"《瑞應圖》曰：比翼鳥者，王者德及高遠則至，一本曰：王者有孝德則至。","sortOrder":53},
  {"id":"s_work_nvlt_99_54","chapterId":"ch_work_nvlt_99","text":"【贊】晉郭璞比翼鳥贊，鳥有鶼鶼，似凫青赤，雖雲一质，氣同體隔，延頸離鳴，翻能合翮。","sortOrder":54},
  {"id":"s_work_nvlt_99_56","chapterId":"ch_work_nvlt_99","text":"《孝經援神契》曰：德至鳥獸，則白乌下。","sortOrder":56},
  {"id":"s_work_nvlt_99_57","chapterId":"ch_work_nvlt_99","text":"《禮斗威儀》曰：江海不扬波，東海输之蒼乌。","sortOrder":57},
  {"id":"s_work_nvlt_99_58","chapterId":"ch_work_nvlt_99","text":"又曰：君乘木而王，其政升平，南海输以蒼乌。","sortOrder":58},
  {"id":"s_work_nvlt_99_59","chapterId":"ch_work_nvlt_99","text":"《尚書緯》曰：火者陽也，乌者有孝名，武王卒成大業，故乌瑞臻。","sortOrder":59},
  {"id":"s_work_nvlt_99_60","chapterId":"ch_work_nvlt_99","text":"《尚書·中候》曰：周太子發渡孟津，有火自天，止於王屋，為赤乌。","sortOrder":60},
  {"id":"s_work_nvlt_99_61","chapterId":"ch_work_nvlt_99","text":"又曰：有火自上，复於王屋，流為雕，其色赤，其聲魄。","sortOrder":61},
  {"id":"s_work_nvlt_99_62","chapterId":"ch_work_nvlt_99","text":"《春秋運斗枢》曰：維星得則日月光，乌三足，禮儀修，物類合。","sortOrder":62},
  {"id":"s_work_nvlt_99_63","chapterId":"ch_work_nvlt_99","text":"孫氏《瑞應圖》曰：三足乌，王者慈孝，被於萬姓，不好殺生則來。","sortOrder":63},
  {"id":"s_work_nvlt_99_64","chapterId":"ch_work_nvlt_99","text":"又曰：文王時見，蒼乌者，王者孝悌則至，一本曰：賢君帝主，修行孝慈，被於萬姓，不好殺生則來。","sortOrder":64},
  {"id":"s_work_nvlt_99_65","chapterId":"ch_work_nvlt_99","text":"又曰：白乌者，宗廟肅敬則至。","sortOrder":65},
  {"id":"s_work_nvlt_99_66","chapterId":"ch_work_nvlt_99","text":"又曰：赤乌，武王時衔穀米至屋上，兵不血刃而殷服，一本曰：王者不貪天下而重民命，則至。","sortOrder":66},
  {"id":"s_work_nvlt_99_67","chapterId":"ch_work_nvlt_99","text":"《墨子》曰：赤乌衔珪，降周之岐社，曰：命周文王代殷，河出箓圖，地出乘黃，天錫武王黃乌之旗。","sortOrder":67},
  {"id":"s_work_nvlt_99_68","chapterId":"ch_work_nvlt_99","text":"《古今註》曰：成帝河平四年，白乌集孝文廟殿下，黑乌從之，章帝元和二年，三足乌集沛國，三年，代郡高柳，乌子生三足，大如雞，色赤，頭上有角，長寸餘，和帝元興元年，白乌一，見庐江，足皆赤。","sortOrder":68},
  {"id":"s_work_nvlt_99_69","chapterId":"ch_work_nvlt_99","text":"《帝王世紀》曰：丰公家於沛之丰邑中陽里，其妻夢赤乌若龍，戲己而生執嘉，是為太公太上皇。","sortOrder":69},
  {"id":"s_work_nvlt_99_70","chapterId":"ch_work_nvlt_99","text":"《吳歷》曰：吳王為神王表，五［《太平御覽》九百二十作立。］廟蒼龍門外，時有乌巢朱雀門上。","sortOrder":70},
  {"id":"s_work_nvlt_99_71","chapterId":"ch_work_nvlt_99","text":"又曰：有兩足乌，衔一鵲，置神座前，或得神書，說改號之意，乃改赤乌為太元。","sortOrder":71},
  {"id":"s_work_nvlt_99_72","chapterId":"ch_work_nvlt_99","text":"《吳志》曰：赤乌元年八月，武昌麒麟見，集於殿前，朕所親見，若神靈以為嘉祥者，改年宜以赤乌。","sortOrder":72},
  {"id":"s_work_nvlt_99_73","chapterId":"ch_work_nvlt_99","text":"又曰：孫休永安三年，春三月，西陵言赤乌見。","sortOrder":73},
  {"id":"s_work_nvlt_99_74","chapterId":"ch_work_nvlt_99","text":"晉諸公贊曰：世祖時，西域獻三足乌，遂累有赤乌來集此昌陵縣，按昌字重日，乌者日中之乌，有記［《太平御覽》九百二十作讬。］體陽精，應期曜质，以顯至德者也。","sortOrder":74},
  {"id":"s_work_nvlt_99_76","chapterId":"ch_work_nvlt_99","text":"《孝經援神契》曰：王者奉己約俭，台榭不侈，尊事耆老，則白雀見。","sortOrder":76},
  {"id":"s_work_nvlt_99_77","chapterId":"ch_work_nvlt_99","text":"《尚書·中候》曰：赤雀衔丹書入丰，止於昌前，［事具帝王部。］","sortOrder":77},
  {"id":"s_work_nvlt_99_78","chapterId":"ch_work_nvlt_99","text":"又曰：維天降紀，泰伯［《太平御覽》九百二十二作秦。］出狩，至於鹹陽，天震大雷，有火下，化為白雀，衔箓，集於公車。","sortOrder":78},
  {"id":"s_work_nvlt_99_79","chapterId":"ch_work_nvlt_99","text":"《禮稽命徵》曰：祭五嶽四渎，得其宜，則黃雀見，［黃雀，土精。］","sortOrder":79},
  {"id":"s_work_nvlt_99_80","chapterId":"ch_work_nvlt_99","text":"春秋孔演圖曰：鳥化為書，孔子奉以告天，赤雀集書上，化為黃玉，剋曰：孔提命，作應法，為製雀集，［將受命製。］","sortOrder":80},
  {"id":"s_work_nvlt_99_81","chapterId":"ch_work_nvlt_99","text":"《春秋考異郵》曰：黃帝將起，有黃雀，赤頭，立日旁，帝占曰：黃者土精，赤者火熒，雀者賞萌，餘當立。","sortOrder":81},
  {"id":"s_work_nvlt_99_82","chapterId":"ch_work_nvlt_99","text":"《漢書》曰：宣帝元康三年詔曰：前年夏，神雀集雍，［大如鸚雀，黃喉白領黑背，腹斑文。］今春，五色乌以萬數，飛屬縣，翱翔而舞，欲集未下，其令三辅，毋得以春夏樀巢探卵，彈射飛鳥，為令。","sortOrder":82},
  {"id":"s_work_nvlt_99_83","chapterId":"ch_work_nvlt_99","text":"《東觀漢記》曰：永安十七年，公卿以神雀五色，翔集京師，奉觴上寿，上令贾逵作神雀頌。","sortOrder":83},
  {"id":"s_work_nvlt_99_84","chapterId":"ch_work_nvlt_99","text":"謝承《後漢書》曰：琅邪董种，為不其令，赤雀乳廳前桑上，民為作歌頌。","sortOrder":84},
  {"id":"s_work_nvlt_99_85","chapterId":"ch_work_nvlt_99","text":"《瑞應圖》曰：赤雀者，王者動作應天時，則衔書來，一本曰：孔子坐玄扈洛水之上，衔丹書隨至。","sortOrder":85},
  {"id":"s_work_nvlt_99_86","chapterId":"ch_work_nvlt_99","text":"《遁甲》曰：赤雀不見，則國無賢，白雀不降，則無後嗣，［赤雀主衔書，陽精也，白雀主衔錢豢，(《太平御覽》九百二十二作鐵券。)陰精也，不來則國王無後嗣也。］","sortOrder":86},
  {"id":"s_work_nvlt_99_87","chapterId":"ch_work_nvlt_99","text":"《古今註》曰：孝哀帝初元三年，泰畤殿中，有雀五色，頭有冠，長寸餘，大似雀，始到時，鳥環其旁。","sortOrder":87},
  {"id":"s_work_nvlt_99_88","chapterId":"ch_work_nvlt_99","text":"《零陵先賢傳》曰：周不疑，曹公欲以為議郎，不就，時有白雀瑞，儒林併已作頌，授紙筆，立令复作，操奇異之。","sortOrder":88},
  {"id":"s_work_nvlt_99_89","chapterId":"ch_work_nvlt_99","text":"《魏略》曰：文帝欲受禪，白雀十九見。","sortOrder":89},
  {"id":"s_work_nvlt_99_90","chapterId":"ch_work_nvlt_99","text":"《吳志》曰：華覈上孫皓表曰：明珠既觌，白雀繼見。","sortOrder":90},
  {"id":"s_work_nvlt_99_91","chapterId":"ch_work_nvlt_99","text":"《吳錄》曰：景帝永安六年，赤雀見於豫章。","sortOrder":91},
  {"id":"s_work_nvlt_99_92","chapterId":"ch_work_nvlt_99","text":"《豫章舊志》曰：太守孔竺，臨郡三月，白雀出，南昌太守夏侯嵩，臨郡六年，白雀見女萝。","sortOrder":92},
  {"id":"s_work_nvlt_99_93","chapterId":"ch_work_nvlt_99","text":"叚龟龍《涼州記》曰：呂光太安三年，白雀巢陽川令蓋敏室。","sortOrder":93},
  {"id":"s_work_nvlt_99_94","chapterId":"ch_work_nvlt_99","text":"郭璞《洞林》曰：丞相府有雏雞，雀集其背，驅之去复來，如此再三，令璞占之，曰：此晉王即祚之漸也。","sortOrder":94},
  {"id":"s_work_nvlt_99_95","chapterId":"ch_work_nvlt_99","text":"《燕書》曰：愍帝時，有異雀，素质绿首，集於端門東树，栖翔二旬而去，夏四月，以異雀故，大赦，名東園白雀。","sortOrder":95},
  {"id":"s_work_nvlt_99_97","chapterId":"ch_work_nvlt_99","text":"《呂氏春秋》曰：有娥［《太平御覽》九百二十二作娀。］氏有二佚女，為九成之台，帝令燕往夜鳴，二女愛而爭博之，覆以玉筐，少選而视之，燕遺二卵，北飛不返，二女作歌，始遺北音。","sortOrder":97},
  {"id":"s_work_nvlt_99_98","chapterId":"ch_work_nvlt_99","text":"田俅子曰：少昊之時，赤燕一羽而飛，集少昊氏之戶，遺其丹書。","sortOrder":98},
  {"id":"s_work_nvlt_99_99","chapterId":"ch_work_nvlt_99","text":"《漢書·名臣奏》曰：丞相薛宣對曰：茂陵寢上食日，玄鳥來集，吐所含大豆，紫黑色，翱翔殿上，此陛下永與天無極，天下幸甚。","sortOrder":99},
  {"id":"s_work_nvlt_99_100","chapterId":"ch_work_nvlt_99","text":"王威別傳曰：時有白燕來翔，被令為賦。","sortOrder":100},
  {"id":"s_work_nvlt_99_101","chapterId":"ch_work_nvlt_99","text":"宋元嘉起居註曰：元年七月，有白燕集於齊郡，遊翔庭宇，經九月乃去，眾燕翼隨，仅有數千。","sortOrder":101},
  {"id":"s_work_nvlt_99_103","chapterId":"ch_work_nvlt_99","text":"《瑞應圖》曰：鳩成湯時來，王者養耆老，尊道德，不以新失舊，則至，一本曰：成王時來。","sortOrder":103},
  {"id":"s_work_nvlt_99_104","chapterId":"ch_work_nvlt_99","text":"《古今註》曰：平帝元始三年，濟南鳩生白子。","sortOrder":104},
  {"id":"s_work_nvlt_99_105","chapterId":"ch_work_nvlt_99","text":"《吳錄》曰：赤乌十二年八月，白鳩見章安。","sortOrder":105},
  {"id":"s_work_nvlt_99_107","chapterId":"ch_work_nvlt_99","text":"《孝經援神契》曰：周成王時，越裳獻白雉，去京師三萬里，王者祭祀不相逾，宴食衣服有節，則至。","sortOrder":107},
  {"id":"s_work_nvlt_99_108","chapterId":"ch_work_nvlt_99","text":"又曰：德至鳥獸，故雉白首，［妃房不偏，故白雉應。］","sortOrder":108},
  {"id":"s_work_nvlt_99_109","chapterId":"ch_work_nvlt_99","text":"《尚書》曰：高宗肜日，越有雊雉，祖己曰：惟先格王，正厥事，［言至道之王，遭变異，正其事而異自消也。］乃訓於王曰：惟天監下民，典厥義，［祖己既言，遂以道訓諫王也，言天下视民，以義為常也。］春秋感精符曰：王者旁流四表，則白雉見。","sortOrder":109},
  {"id":"s_work_nvlt_99_110","chapterId":"ch_work_nvlt_99","text":"又曰：魯昭公時，雉衔環入，［雉之為言弟也，喻昭公弟為季氏入之為君也。］","sortOrder":110},
  {"id":"s_work_nvlt_99_111","chapterId":"ch_work_nvlt_99","text":"《漢書》：平帝元始元年春，越裳重譯，獻白雉一，黑雉二，詔使三公以荐宗廟。","sortOrder":111},
  {"id":"s_work_nvlt_99_112","chapterId":"ch_work_nvlt_99","text":"《魏略》曰：文帝欲受禪，郡國奏白雉十九見。","sortOrder":112},
  {"id":"s_work_nvlt_99_113","chapterId":"ch_work_nvlt_99","text":"《魏志·文紀》曰：延康元年四月，饒安縣言白雉見。","sortOrder":113},
  {"id":"s_work_nvlt_99_115","chapterId":"ch_work_nvlt_99","text":"《瑞應圖》曰：玉馬者，王者清明尊賢則至，一本曰：玉泽馬者，師曠時來。","sortOrder":115},
  {"id":"s_work_nvlt_99_116","chapterId":"ch_work_nvlt_99","text":"又曰：王者順時而製事，因時而治道，則來。","sortOrder":116},
  {"id":"s_work_nvlt_99_117","chapterId":"ch_work_nvlt_99","text":"騰黃者，神馬也，其色黃，王者德御四方則至，一名吉光，乘之寿三千歲，此馬無死時。","sortOrder":117},
  {"id":"s_work_nvlt_99_118","chapterId":"ch_work_nvlt_99","text":"又曰：乘黃，王者舆服有度則出，騕褭者，神馬也，與飛兔同，以明君有德則至也。","sortOrder":118},
  {"id":"s_work_nvlt_99_119","chapterId":"ch_work_nvlt_99","text":"又曰：飛兔者，行三萬里，禹治水土，勤勞歷年，救民之害，天應其德則至，駃蹄者，後土之獸也，自能言語，王者仁孝於民則出，禹治水有功而來。","sortOrder":119},
  {"id":"s_work_nvlt_99_120","chapterId":"ch_work_nvlt_99","text":"又曰：龍馬者，仁馬，河水之精也，高八尺五寸，長頸，骼上有翼，旁垂毛，鳴聲九音，有明王則見，一本曰：王者不储馬，則龍馬乘黃泽馬朱髦併集。","sortOrder":120},
  {"id":"s_work_nvlt_99_121","chapterId":"ch_work_nvlt_99","text":"《禮斗威儀》曰：君乘火而王者，其政訟平，則南海输以駿［《太平御覽》八百九十三作駮。］馬。","sortOrder":121},
  {"id":"s_work_nvlt_99_122","chapterId":"ch_work_nvlt_99","text":"《尚書·中候》曰：尧時，龍馬衔甲，赤文绿色，臨壇上，甲似龟，廣袤九尺，圓理平上，五色，文有列星之分，斗政之度，帝王錄紀之數，［事具帝王部。］","sortOrder":122},
  {"id":"s_work_nvlt_99_123","chapterId":"ch_work_nvlt_99","text":"周書曰：犬戎文馬，赤鬛白身，目若黃金，名曰古［按當作吉。］黃之乘，成王時來獻也。","sortOrder":123},
  {"id":"s_work_nvlt_99_124","chapterId":"ch_work_nvlt_99","text":"《淮南子》曰：天下有道，飛黃服皂。","sortOrder":124},
  {"id":"s_work_nvlt_99_125","chapterId":"ch_work_nvlt_99","text":"又曰：黃帝時，飛黃服皂也。","sortOrder":125},
  {"id":"s_work_nvlt_99_126","chapterId":"ch_work_nvlt_99","text":"《漢書》曰：武帝元鼎四年，馬出渥洼水中，作天馬之歌。","sortOrder":126},
  {"id":"s_work_nvlt_99_127","chapterId":"ch_work_nvlt_99","text":"◇白鹿","sortOrder":127},
  {"id":"s_work_nvlt_99_128","chapterId":"ch_work_nvlt_99","text":"《孝經援神契》曰：德至鳥獸，則白鹿見。","sortOrder":128},
  {"id":"s_work_nvlt_99_129","chapterId":"ch_work_nvlt_99","text":"《瑞應圖》曰：天鹿者，純善之獸也，道備則白鹿見，王者明惠及下則見。","sortOrder":129},
  {"id":"s_work_nvlt_99_130","chapterId":"ch_work_nvlt_99","text":"《命歷序》曰：皇神駕六飛鹿，值三百歲。","sortOrder":130},
  {"id":"s_work_nvlt_99_131","chapterId":"ch_work_nvlt_99","text":"《禮斗威儀》曰：君乘水而王，其政平，則北海输白鹿。","sortOrder":131},
  {"id":"s_work_nvlt_99_132","chapterId":"ch_work_nvlt_99","text":"《東觀漢書［按當作記。］曰》，章帝元和二年，白鹿見。","sortOrder":132},
  {"id":"s_work_nvlt_99_133","chapterId":"ch_work_nvlt_99","text":"又，安帝延光三年，潁川上言，白鹿見。","sortOrder":133},
  {"id":"s_work_nvlt_99_134","chapterId":"ch_work_nvlt_99","text":"《魏略》曰：文帝欲受禪，郡國奏白鹿十九見。","sortOrder":134},
  {"id":"s_work_nvlt_99_135","chapterId":"ch_work_nvlt_99","text":"晉《起居註》曰：太元十六年，豫章太守范甯，獻白鹿一頭，二十年，荆州送白鹿，晉朝白鹿數見諸郡。","sortOrder":135},
  {"id":"s_work_nvlt_99_137","chapterId":"ch_work_nvlt_99","text":"《瑞應圖》曰：九尾狐者，六合一同則見，文王時，東夷歸之，一本曰：王者不傾於色則至。","sortOrder":137},
  {"id":"s_work_nvlt_99_138","chapterId":"ch_work_nvlt_99","text":"《河圖》曰：白帝生，先致白狐。","sortOrder":138},
  {"id":"s_work_nvlt_99_139","chapterId":"ch_work_nvlt_99","text":"《周書》曰：成王時，青丘獻狐九尾。","sortOrder":139},
  {"id":"s_work_nvlt_99_140","chapterId":"ch_work_nvlt_99","text":"《禮斗威儀》曰：君乘火而王，其政訟平，南海输以文狐，《尚書大傳》曰：文王拘羑里，散宜生之西海之濱，取白狐青翰獻紂，紂大悅，［翰，長毛也，六韜得青狐，班固幽通賦註曰：散宜生至吳，得九尾狐，以獻紂也。］","sortOrder":140},
  {"id":"s_work_nvlt_99_141","chapterId":"ch_work_nvlt_99","text":"春秋運斗枢曰：機星得則狐九尾。","sortOrder":141},
  {"id":"s_work_nvlt_99_142","chapterId":"ch_work_nvlt_99","text":"《潛潭巴》曰：白狐至，國民利，不至，下驕恣。","sortOrder":142},
  {"id":"s_work_nvlt_99_143","chapterId":"ch_work_nvlt_99","text":"《山海經》曰：武都之山，黑水出焉，其上有玄狐，蓬尾，［蓬，大。］","sortOrder":143},
  {"id":"s_work_nvlt_99_144","chapterId":"ch_work_nvlt_99","text":"孝經援神契曰：德至鳥獸，則狐九尾。","sortOrder":144},
  {"id":"s_work_nvlt_99_145","chapterId":"ch_work_nvlt_99","text":"《呂氏春秋》曰：禹年三十未娶，行涂山，恐時暮失嗣，辭曰：吾之娶，必有應也，乃有白狐九尾而造於禹，禹曰：白者，吾服也，九尾者，其證也，於是涂山人歌曰：綏綏白狐，九尾庞庞，成於家室，我都攸昌，於是娶涂山女。","sortOrder":145},
  {"id":"s_work_nvlt_99_146","chapterId":"ch_work_nvlt_99","text":"《東觀漢記》曰：章帝元和二年，九尾狐見。","sortOrder":146},
  {"id":"s_work_nvlt_99_147","chapterId":"ch_work_nvlt_99","text":"《古今註》曰：章帝元和二年，白狐九尾見信都，《魏略》曰：文帝欲受禪，郡國奏九尾狐見於谯陳。","sortOrder":147},
  {"id":"s_work_nvlt_99_149","chapterId":"ch_work_nvlt_99","text":"《瑞應圖》曰：王者恩加耆老，則白兔見，一本曰：王者應事疾則見，赤兔者，王者德茂則見。","sortOrder":149},
  {"id":"s_work_nvlt_99_150","chapterId":"ch_work_nvlt_99","text":"《古今註》曰：成帝建平元年，山陽得白兔，目赤如朱。","sortOrder":150},
  {"id":"s_work_nvlt_99_151","chapterId":"ch_work_nvlt_99","text":"《東觀漢記》曰：章帝元和二年，白兔見。","sortOrder":151},
  {"id":"s_work_nvlt_99_152","chapterId":"ch_work_nvlt_99","text":"又曰：永康元年，西河言白兔見。","sortOrder":152},
  {"id":"s_work_nvlt_99_153","chapterId":"ch_work_nvlt_99","text":"石勒傳曰：莊［《太平御覽》九百零七引晉書作茬。］平民師懽，上黑兔，令曰：按記應白兔為瑞，此黑兔曰祥，外捡典舊，議者以為黑兔見，水德之祥，往公孫臣以為漢家土行，當有黃龍為瑞，後黃龍見於成紀，遂從土德，今大趙革命，以水受金，夫兔陰獸，玄水色，黑色見，以表應行，以推之，黑兔上應。","sortOrder":153},
  {"id":"s_work_nvlt_99_154","chapterId":"ch_work_nvlt_99","text":"◇騶虞","sortOrder":154},
  {"id":"s_work_nvlt_99_155","chapterId":"ch_work_nvlt_99","text":"《瑞應圖》曰：白虎者，仁而不害，王者不暴虐，恩及行苇則見。","sortOrder":155},
  {"id":"s_work_nvlt_99_156","chapterId":"ch_work_nvlt_99","text":"《毛詩》曰：吁嗟乎騶虞，［義獸也，白虎黑文，不食生物，有至信之德，則應之而來。］","sortOrder":156},
  {"id":"s_work_nvlt_99_157","chapterId":"ch_work_nvlt_99","text":"《河圖括地象》曰：令訾野中有玉虎，晨鳴雷聲，聖人感期之興。","sortOrder":157},
  {"id":"s_work_nvlt_99_158","chapterId":"ch_work_nvlt_99","text":"《孝經援神契》曰：德至鳥獸，白虎見。","sortOrder":158},
  {"id":"s_work_nvlt_99_159","chapterId":"ch_work_nvlt_99","text":"春秋演義［按當作孔。］圖曰：湯地七十，內懷聖明，白虎戲朝。","sortOrder":159},
  {"id":"s_work_nvlt_99_160","chapterId":"ch_work_nvlt_99","text":"《春秋元命包》曰：尧為天子，季秋下旬，夢白虎遺吾馬啄［《太平御覽》三百九十七作喙。］子，其母曰扶始，升高丘，睹白虎，上有雲感己，生皋陶，索扶始問之，如尧言，明於刑法，罪次終始，故立皋陶為大理。","sortOrder":160},
  {"id":"s_work_nvlt_99_161","chapterId":"ch_work_nvlt_99","text":"《魏略》曰：文帝欲受禪，郡國上言，白虎二十七見。","sortOrder":161},
  {"id":"s_work_nvlt_99_162","chapterId":"ch_work_nvlt_99","text":"王隱《晉書》曰：太康六年，荆州送兩足虎，時尚書郎索靖，議稱半虎，博令［湯球辑本作士。］王鈐［湯球辑本作铨。］為文曰：般般白虎，觀亹荆楚，孫吳不逞，金皇赫怒。","sortOrder":162},
  {"id":"s_work_nvlt_99_163","chapterId":"ch_work_nvlt_99","text":"中興徵祥說曰：天下太平，則騶虞見，騶虞者，仁獸也，状如白虎而黑文，其尾參倍，昔召公化行陝西之國，而騶虞應。","sortOrder":163},
  {"id":"s_work_nvlt_99_164","chapterId":"ch_work_nvlt_99","text":"又曰：王者仁而不害，則白虎見，白虎状如虎而白色，嘯則風興，皜身如雲，而無雜者是也，近代所謂白虎者，背斑而虎文，爾雅所謂彪虎者也。","sortOrder":164},
  {"id":"s_work_nvlt_99_165","chapterId":"ch_work_nvlt_99","text":"【頌】後漢蔡邕五靈頌曰：大梁乘精，白虎用生，思叡信立，繞於垣坰。","sortOrder":165},
  {"id":"s_work_nvlt_99_166","chapterId":"ch_work_nvlt_99","text":"吳薛綜頌曰：婉婉白虎，優仁是崇，飢不侵暴，困不改容，斂威扬德，恺悌之風，聖德極盛，騶虞乃彰。","sortOrder":166},
  {"id":"s_work_nvlt_99_167","chapterId":"ch_work_nvlt_99","text":"【贊】晉郭璞騶虞贊曰：怪獸五采，尾參於身，矯足千里，儵忽若神，是謂騶虞，詩叹其仁。","sortOrder":167},
  {"id":"s_work_nvlt_99_168","chapterId":"ch_work_nvlt_99","text":"◇白狼","sortOrder":168},
  {"id":"s_work_nvlt_99_169","chapterId":"ch_work_nvlt_99","text":"《瑞應圖》曰：白狼，王者仁德明哲則見，一本曰：王者進退，動准法度則見，周宣王時，白狼見，犬戎滅。","sortOrder":169},
  {"id":"s_work_nvlt_99_170","chapterId":"ch_work_nvlt_99","text":"《山海經》曰：蓋山，獸多白狼。","sortOrder":170},
  {"id":"s_work_nvlt_99_171","chapterId":"ch_work_nvlt_99","text":"《尚書·中候》曰：湯牵白狼，握禹箓。","sortOrder":171},
  {"id":"s_work_nvlt_99_172","chapterId":"ch_work_nvlt_99","text":"田俅子曰：商湯為天子，都於亳，有神手牵白狼，口衔金鉤，而入湯庭。","sortOrder":172},
  {"id":"s_work_nvlt_99_173","chapterId":"ch_work_nvlt_99","text":"【贊】晉郭璞白狼贊曰：矯矯白狼，有道則遊，應符变质，乃衔靈鉤，惟德是適，出殷見周。","sortOrder":173},
  {"id":"s_work_nvlt_99_174","chapterId":"ch_work_nvlt_99","text":"◇比肩","sortOrder":174},
  {"id":"s_work_nvlt_99_175","chapterId":"ch_work_nvlt_99","text":"《瑞應圖》曰：比肩獸者，王者德及幽隱，鳏寡得所則至。","sortOrder":175},
  {"id":"s_work_nvlt_99_176","chapterId":"ch_work_nvlt_99","text":"《爾雅》曰：西方有比肩獸焉，與邛邛岠虛比，為邛邛岠虛齧甘草，即劂有難，邛邛岠虛負而走，其名曰蟨。","sortOrder":176},
  {"id":"s_work_nvlt_99_177","chapterId":"ch_work_nvlt_99","text":"《呂氏春秋》曰：北方有獸，名蟨，鼠前而兔後。","sortOrder":177},
  {"id":"s_work_nvlt_99_178","chapterId":"ch_work_nvlt_99","text":"【贊】晉郭璞比肩獸贊曰：蟨與岠虛，乍兔乍鼠，長短相濟，彼我俱舉，有若自然，同心共膂。","sortOrder":178},
  {"id":"s_work_nvlt_99_180","chapterId":"ch_work_nvlt_99","text":"《龍魚河圖》曰：尧時，與群臣賢智到翠妫之川，大龟負圖來投尧，尧敕臣下寫取，告瑞應，寫畢，龟還水中。","sortOrder":180},
  {"id":"s_work_nvlt_99_181","chapterId":"ch_work_nvlt_99","text":"《黃帝出軍决》曰：帝伐蚩尤，乃睡，夢西王母遣道人，披玄狐之裘，以符授之曰：太一在前，天一備後，河出符信，戰即剋矣，黃帝寤，思其符，不能悉憶，以告風後力牧，風後力牧曰：此兵應也，戰必自勝，力牧與黃帝俱到盛水之侧，立壇，祭以大牢，有玄龟衔符，從水中出，置壇中而去，黃帝再拜稽首，受符视之，乃所夢得符也，廣三寸，表一尺，於是黃帝備之以征，即日禽蚩尤。","sortOrder":181},
  {"id":"s_work_nvlt_99_182","chapterId":"ch_work_nvlt_99","text":"《尚書·中候》曰：尧沉璧於雒，玄龟負書出，背甲赤文成字，止壇。又沉璧於河，黑龟出文題。","sortOrder":182},
  {"id":"s_work_nvlt_99_183","chapterId":"ch_work_nvlt_99","text":"又曰：周公沉璧，玄龟青純仓光，刻背甲，止於壇。","sortOrder":183},
  {"id":"s_work_nvlt_99_184","chapterId":"ch_work_nvlt_99","text":"《禮斗威儀》曰：君乘土而王，則龟被文而見。","sortOrder":184},
  {"id":"s_work_nvlt_99_185","chapterId":"ch_work_nvlt_99","text":"《春秋運斗枢》曰：玉衡星得，百獸率舞，靈龟躍。","sortOrder":185},
  {"id":"s_work_nvlt_99_186","chapterId":"ch_work_nvlt_99","text":"《管子》曰：龟生於水，發之於火，故為南方物，為禍福也。","sortOrder":186},
  {"id":"s_work_nvlt_99_187","chapterId":"ch_work_nvlt_99","text":"《魏略》曰：文帝欲受禪，神龟出於靈池。","sortOrder":187},
  {"id":"s_work_nvlt_99_188","chapterId":"ch_work_nvlt_99","text":"晉《起居註》曰：永嘉六年，玉龟出灞水。","sortOrder":188},
  {"id":"s_work_nvlt_99_189","chapterId":"ch_work_nvlt_99","text":"《孫氏瑞圖》曰：龟者神異之介虫也，玄采五色，上隆象天，下平象地，生三百歲，遊於蕖葉之上，三千歲尚在蓍丛之下，明吉凶，不偏不党，唯義是從，王者無偏無党，尊用耆老，不失故舊，則出，一本曰：德泽湛潰，漁獵從，則出。","sortOrder":189},
  {"id":"s_work_nvlt_99_190","chapterId":"ch_work_nvlt_99","text":"又曰：禹卑宮室則出，文王時亦出。","sortOrder":190},
  {"id":"s_work_nvlt_99_191","chapterId":"ch_work_nvlt_99","text":"【表】吳謝承表曰：伏睹靈龟出於會稽章安，臣聞靈龟告符，五色粲彰，則金則玉，背陰向陽。","sortOrder":191},
  {"id":"s_work_nvlt_99_192","chapterId":"ch_work_nvlt_99","text":"梁劉孝儀為始興王上毛龟表曰：臣聞嘉瑞五靈，既著方策，故休名千載，可得而傳，是以玄蔡赤文，來表軒黃之政，神龟青純，用顯姬公之德，出自江安，寔荷謙夷之慶，甲生□毳，寧非銷□之徵，實皇家之巨瑞，庶民之休幸。","sortOrder":192},
  {"id":"s_work_nvlt_99_193","chapterId":"ch_work_nvlt_99","text":"【啟】梁丘遲為范雲謝示毛龟啟曰：玄甲應於姬渚，青髯符於夏室，翱翔卷耳之陰，浮遊莲葉之上，藏采千載，獻状一朝，斯誠陛下至德動天，窮神為化，故能寶瑞开圖，珍祥映諜，間出蕃畿，繼踵郊甸。","sortOrder":193},
  {"id":"s_work_nvlt_99_194","chapterId":"ch_work_nvlt_99","text":"隋江總上毛龟啟曰：臣聞聖王受命，以代紹興，日月精明之状，煙雲烂漫之采，神鼎出於汾陰，寶玉开於張掖，靈山奧泽，卉木呈祉，靜海澄波，鱗介提福，靡不顯符瑞以固鸿基，肇徵祥以光永世者也，影合四靈，光分五色，懷星抱月，負字衔圖。","sortOrder":194},
  {"id":"s_work_nvlt_99_196","chapterId":"ch_work_nvlt_99","text":"《爾雅》曰：東方有比目魚，不比不行，其名曰〈魚枼〉。","sortOrder":196},
  {"id":"s_work_nvlt_99_197","chapterId":"ch_work_nvlt_99","text":"《帝王世紀》曰：黃帝出遊洛水之上，見大魚，殺五能牲以醮之，天乃甚雨，七日七夜，魚流於海，始得圖書，今河圖帝视萌之篇是也。","sortOrder":197},
  {"id":"s_work_nvlt_99_198","chapterId":"ch_work_nvlt_99","text":"《尚書·中候》曰：桓公欲封泰山，管仲曰：昔者聖王功成道格，符瑞出，乃封泰山，今比目之魚不至，鳳麟不臻，未可封也。","sortOrder":198},
  {"id":"s_work_nvlt_99_199","chapterId":"ch_work_nvlt_99","text":"《瑞應圖》曰：比目魚者，王者明德則見。","sortOrder":199},
  {"id":"s_work_nvlt_99_200","chapterId":"ch_work_nvlt_99","text":"《史記》曰：武王渡河，中流，白魚躍入舟中，［魚者介鱗之物，兵象，白者殷家之政，言以殷之兵眾與周之象也。］武王俯取以祭。","sortOrder":200},
  {"id":"s_work_nvlt_99_201","chapterId":"ch_work_nvlt_99","text":"《漢書》曰：宣帝元康四年，神魚舞河。","sortOrder":201},
  {"id":"s_work_nvlt_99_202","chapterId":"ch_work_nvlt_99","text":"《魏志》曰：文帝欲受禪，赤魚遊於露。","sortOrder":202},
  {"id":"s_work_nvlt_99_203","chapterId":"ch_work_nvlt_99","text":"【贊】晉郭璞比目魚贊曰：比目之鱗，別號王餘，雖有二片，其實一魚，协不能密，離不為疏。","sortOrder":203},
  {"id":"s_work_nvlt_99_204","chapterId":"ch_work_nvlt_99","text":"【表】晉王肅贺瑞應表曰：伏承祖廟文昭廟，魚生於鼎，臣聞易中孚彖曰：信及豚魚，言中和誠信之德，下及豚魚，則無所不及。","sortOrder":204},
  {"id":"s_work_nvlt_99_206","chapterId":"ch_work_nvlt_99","text":"《易》曰：鼎元吉，亨，其彖曰：鼎象也，聖人以享上帝。","sortOrder":206},
  {"id":"s_work_nvlt_99_207","chapterId":"ch_work_nvlt_99","text":"孫氏《瑞應圖》曰：神鼎者，质文精也，知吉凶存亡，能輕能重，能息能行，不灼而沸，不汲自盈，中生五味，昔黃帝作鼎，象太一，禹治水，收天下美銅，以為九鼎，象九州，王者興則出，衰則去。","sortOrder":207},
  {"id":"s_work_nvlt_99_208","chapterId":"ch_work_nvlt_99","text":"歸藏占曰：鼎有黃耳，利得鳣鯉。","sortOrder":208},
  {"id":"s_work_nvlt_99_209","chapterId":"ch_work_nvlt_99","text":"《左傳》曰：楚子伐陆浑之戎，遂至於雒，觀兵於周疆，定王使王孫滿勞楚子，楚子問鼎之大小輕重焉，對曰：在德不在鼎，昔夏之方有德也，遠方圖物，貢金九牧，鑄鼎象物，百物而為之備，使人知神奸，故民入川泽山林，不逢不若，魑魅魍魉，莫能逢之，协於上下，以承天休，桀有昏德，鼎遷於商，載祀六百，商紂暴虐，鼎遷於周，成王定鼎於郏鄏，卜世三十，卜年七百，天所命也，周德雖衰，天命未改，鼎之輕重，未可問也。","sortOrder":209},
  {"id":"s_work_nvlt_99_210","chapterId":"ch_work_nvlt_99","text":"《史記》曰：黃帝采首山銅，鑄鼎於荆山下，鼎既成，有龍垂胡髯，下迎黃帝，黃帝上騎，群臣後宮從上者七十餘人，龍乃上去。","sortOrder":210},
  {"id":"s_work_nvlt_99_211","chapterId":"ch_work_nvlt_99","text":"又曰：漢武帝時，汾陰巫錦，［錦，巫名。］為民祠魏睢後土，營旁，見地如鉤状，棓视得鼎，以禮迎鼎至甘泉，從行，上荐之，至中山，晏溫有黃雲蓋焉，有鹿過，上自射之，因以祭之，至長安，公卿大夫皆議，謂之寶鼎。","sortOrder":211},
  {"id":"s_work_nvlt_99_212","chapterId":"ch_work_nvlt_99","text":"《晉陽春秋》曰：鹹康八年，穀成［《太平御覽》七百五十六作城。］縣民留珪，夜見門內有光，取得玉鼎，一围四寸，庐江太守以獻。","sortOrder":212},
  {"id":"s_work_nvlt_99_213","chapterId":"ch_work_nvlt_99","text":"晉《起居註》曰：鹹和元年，宣成［按當作城。］春穀縣山甿，獲古鼎，可受三斛餘，群臣畢贺。","sortOrder":213},
  {"id":"s_work_nvlt_99_214","chapterId":"ch_work_nvlt_99","text":"【贊】晉郭璞贊曰：九牧貢金，鼎出夏後，和味養賢，以無化有，赫赫三事，鑒於覆蔌。","sortOrder":214},
  {"id":"s_work_nvlt_99_215","chapterId":"ch_work_nvlt_99","text":"【啟】梁劉孝綽送瑞鼎詣相國梁公啟曰：生木遊火之禽，夹階紀朔之華，白環銀瓮之跡，素雉金船之瑞，自天宥祚，不為定於郏鄏，虛其所止，非獨在於汾陰。","sortOrder":215},
  {"id":"s_work_nvlt_99_216","chapterId":"ch_work_nvlt_99","text":"《藝文類聚》　唐·欧陽詢","sortOrder":216},
  {"id":"s_work_nvlt_100_1","chapterId":"ch_work_nvlt_100","text":"卷一百灾異部","sortOrder":1},
  {"id":"s_work_nvlt_100_2","chapterId":"ch_work_nvlt_100","text":"○旱祈雨蝗螟蟊賊蜮","sortOrder":2},
  {"id":"s_work_nvlt_100_4","chapterId":"ch_work_nvlt_100","text":"《春秋考異郵》曰：旱之言悍也，陽驕蹇所致也。","sortOrder":4},
  {"id":"s_work_nvlt_100_5","chapterId":"ch_work_nvlt_100","text":"《山海經》曰：泰華之上，削成而四方，有蛇名曰肥遺，六足四翼，見則天下旱。","sortOrder":5},
  {"id":"s_work_nvlt_100_6","chapterId":"ch_work_nvlt_100","text":"又曰：東荒北隅有山，名土丘，應龍處南極，殺蚩尤夸父，不得复上，故下數旱，旱而作龍應之，乃得大雨。","sortOrder":6},
  {"id":"s_work_nvlt_100_7","chapterId":"ch_work_nvlt_100","text":"《周官》曰：司巫，掌群巫之政令，若國大旱，則率巫而舞雩。","sortOrder":7},
  {"id":"s_work_nvlt_100_8","chapterId":"ch_work_nvlt_100","text":"《禮記》曰：歲旱，穆公召縣子而問焉，曰：天久不雨，吾欲暴尫而奚若，曰：天則不雨，曝人之疾，子毋乃不可乎，然則吾欲曝巫而奚若，曰：天則不雨，而望愚婦人，於己求之，毋乃已疏乎，徙市則奚若，曰：天子崩，巷市七日，諸侯薨，市三日，為之徙市，不亦可乎。","sortOrder":8},
  {"id":"s_work_nvlt_100_9","chapterId":"ch_work_nvlt_100","text":"《毛詩》曰：倬彼雲漢，昭回於天，王曰於乎，何辜今之人，天降丧亂，飢饉荐臻，靡神不舉，靡愛斯牲，圭璧既卒，寧莫我聽，旱既太甚，蘊隆虫虫，不殄禋祀，自郊俎宮，上下奠瘞，靡神不宗，旱既太甚，涤涤山川，旱魃為虐，如炎如焚，我心憚暑，忧心如燻。","sortOrder":9},
  {"id":"s_work_nvlt_100_10","chapterId":"ch_work_nvlt_100","text":"韦曜《毛詩問》曰：雲漢之詩，旱魃為虐，傳曰：魃，天旱鬼也，箋雲，旱氣生魃，天有常神，人死為鬼，不審旱氣生魃奈何，答曰：魃鬼人形，眼在顶上，天生此物，則將旱也，天欲為灾，何所不生，而雲有常神者耶。","sortOrder":10},
  {"id":"s_work_nvlt_100_11","chapterId":"ch_work_nvlt_100","text":"《左傳》曰：鄭大旱，使屠击有事於桑山，斬其木，不雨，子產曰：有事於山，藝山林也，而斬其木，其罪大矣。","sortOrder":11},
  {"id":"s_work_nvlt_100_12","chapterId":"ch_work_nvlt_100","text":"又曰：衛大旱，卜有事於山川，不吉，甯《莊子》曰：昔周飢，克殷而年丰，天其或者欲使衛讨邢乎，從之，師興而雨。","sortOrder":12},
  {"id":"s_work_nvlt_100_13","chapterId":"ch_work_nvlt_100","text":"又曰：夏大旱，公欲焚巫尫，臧文仲曰：非旱備也，修城郭，貶食省用，務穡勸分，此其務也，巫尫何為，天欲殺之，則如勿生，若能為旱，焚之滋甚，公從之，是歲飢而不害。","sortOrder":13},
  {"id":"s_work_nvlt_100_14","chapterId":"ch_work_nvlt_100","text":"《春秋繁露》曰：水幹土則大旱。","sortOrder":14},
  {"id":"s_work_nvlt_100_15","chapterId":"ch_work_nvlt_100","text":"《家語》曰：孔子在齊，齊大旱，春飢，哀公問於孔子曰：旱如之何，孔子曰：凶年則乘駑馬，力役不興，馳道不修，祈以敝涇，［《太平御覽》八百七十九作幣玉。］祭事不懸，祀以下牲，此則賢君自貶以救民之禮也。","sortOrder":15},
  {"id":"s_work_nvlt_100_16","chapterId":"ch_work_nvlt_100","text":"《管子》曰：春不收枯骨於［《太平御覽》三十五作朽。］胔，伐枯木而去之，則夏旱至矣。","sortOrder":16},
  {"id":"s_work_nvlt_100_17","chapterId":"ch_work_nvlt_100","text":"《晏子》曰：齊大旱，公召群臣問曰：天不雨久矣，民且飢色，吾使人卜之，崇在高山廣泽，寡人少賦斂以祠靈山，可乎，群臣皆莫有對者，晏子進曰：不可，祠此無益也，夫靈山固以石為身，以草木為毛發，天久不雨，發將燋，身將熱，彼獨不欲雨乎，祠之何益。","sortOrder":17},
  {"id":"s_work_nvlt_100_18","chapterId":"ch_work_nvlt_100","text":"《莊子》曰：梁君出獵，見白雁群，君欲射之，道有行者駭之，君怒，欲射行者，其御公孫龍，下車撫矢曰：昔先公時，大旱三年，卜之，以人祠乃雨，公下堂頓首曰：吾欲所以求雨，以為民也，當［《太平御覽》四百五十七當上有寡人將自四字，此脱。］之，言未卒而天大雨，方千里者何，為於天而惠於民，今君主以白雁而欲殺人乎。","sortOrder":18},
  {"id":"s_work_nvlt_100_19","chapterId":"ch_work_nvlt_100","text":"《韓子》曰：晉公使師曠奏清徵，師曠曰：清徵不如清角，平公曰：清角可得聞乎，師曠曰：君德薄，不足以聽之，聽之將恐有败，平公曰：寡人老矣，所好者音，原遂聽之，師曠不得已而鼓之，一奏之，有雲從西北方起，再奏之，大風至，大雨隨之，裂帷幕，破俎豆，墮廊瓦，坐者散走，平公恐懼，伏於廊室，晉國大旱，赤地三年，平公之身遂癃病，《洪范五行傳》曰：魯桓公五年，大雩，旱也，先是公弒君而立，有自危之心，而下有悲{封心}之氣，外結大國，娶於齊以為夫人，後比二年，天子使大夫來聘，桓上得天子意，凭大國之心，則有亢陽之意，以御臣下，興州丘之役，以勞百姓，則臣下離心而不從，故應是而秋大旱。","sortOrder":19},
  {"id":"s_work_nvlt_100_20","chapterId":"ch_work_nvlt_100","text":"又曰：旱所謂常陽，不謂常陽而謂旱者，以為灾也，旱之為言乾，萬物傷而乾，不得水也，君持亢陽之節，暴虐於下，興師旅，動眾勞民，以起城邑，臣下悲怨而心不從，故陽氣盛而失度，故旱灾應也。","sortOrder":20},
  {"id":"s_work_nvlt_100_21","chapterId":"ch_work_nvlt_100","text":"《物理論》曰：陽盈而過，故致旱。","sortOrder":21},
  {"id":"s_work_nvlt_100_22","chapterId":"ch_work_nvlt_100","text":"《神農求雨書》曰：春夏雨日而不雨，甲乙命為青龍。又為火龍東方，小童舞之，丙丁不雨，命為赤龍南方，壮者舞之，戊己不雨，命為黃龍，壮者舞之，庚辛不雨，命為白龍。又為火龍西方，老人舞之，壬癸不雨，命為黑龍北方，老人舞之，如此不雨，潛處，阖南門，置水其外，开北門，取人骨埋之，如此不雨，命巫祝而曝之，曝之不雨，神山積薪，击鼓而焚之。","sortOrder":22},
  {"id":"s_work_nvlt_100_23","chapterId":"ch_work_nvlt_100","text":"《黃帝占書》曰：日中三足乌見者，大旱赤地。","sortOrder":23},
  {"id":"s_work_nvlt_100_24","chapterId":"ch_work_nvlt_100","text":"《師曠占》曰：歲欲旱，旱草先生，旱草者，蒺｛艹梨｝也。","sortOrder":24},
  {"id":"s_work_nvlt_100_25","chapterId":"ch_work_nvlt_100","text":"《神異經》曰：南方有人，長二三尺，袒身，而目在顶上，走行如風，名曰魃，所見之國大旱，赤地千里，一名鲗，遇者得之，投溷中乃死，旱灾消也。","sortOrder":25},
  {"id":"s_work_nvlt_100_26","chapterId":"ch_work_nvlt_100","text":"京氏別對灾異曰：久旱何，曰：人君無施泽惠利於下，則致旱也，不救即蝗虫害穀，其救也，省謫罰，行宽大，惠兆民，勞功吏，賜鳏寡，廪不足。","sortOrder":26},
  {"id":"s_work_nvlt_100_27","chapterId":"ch_work_nvlt_100","text":"《孔丛子》曰：子丰拜高第御史，建初元年，歲大旱，乃上疏曰：臣聞為不善而灾報，得其應也，為善而灾至，遭時運也，陛下即位日新，视民如傷，而不幸耗旱，時運之會耳，非政教之所致也，昔成湯遭旱，因自责，减御損膳，而大有年，天意者陛下未為成湯之事焉，天子納其言而從之，三日雨即降，轉拜黃門侍郎，典東觀事。","sortOrder":27},
  {"id":"s_work_nvlt_100_28","chapterId":"ch_work_nvlt_100","text":"《漢書》曰：東海有孝婦，少寡無子，養姑甚謹，姑告鄰人曰：孝婦養我勤苦，哀其無子守寡，我老，久累丁壮奈何，後姑自經死，姑女告吏，婦殺我母，吏捕孝婦，婦誣服，郡掾於公，以為此婦女不殺也，太守不聽，於公爭之弗得，乃抱具獄，哭於府上，因辭疾去，郡中枯旱三年，後太守至，殺牛自祭孝婦冢，因表墓，天立大雨，歲熟，郡中以此大敬重於公。","sortOrder":28},
  {"id":"s_work_nvlt_100_29","chapterId":"ch_work_nvlt_100","text":"《東觀漢記》曰：和憙邓後稱製，京師旱，至五月朔，太後幸雒陽寺，省庶獄，舉冤囚，杜泠不殺人，自誣，被掠羸困，使興見，畏吏，不敢自理，吏將去，微疾舉頸，若欲有言，太後察视，覺之，即呼還問状，遂信，即時收令下獄，抵罪，尹左遷，行未還宮，澍雨大降。","sortOrder":29},
  {"id":"s_work_nvlt_100_30","chapterId":"ch_work_nvlt_100","text":"《會稽典錄》曰：夏香，字曼卿，永興人也。為農夫，香挺然特立，明果獨斷。年十五，縣長葛君，出臨靈星，會客飲宴。時郡遭大旱，香進諫曰：昔殷湯遭旱，以六事自责，而雨泽應澍，成王悔過，偃禾复起。自古先聖，畏懼天異，必思变复，以濟民命。今始罹天灾，縣界獨甚，未聞明達崇殷周之德，臨祭獨歡，百姓枯瘁，神祇有靈，必不享也。百姓不足，君孰與足，宜當還寺，長即罢會，身損俸祿，以贍飢民。","sortOrder":30},
  {"id":"s_work_nvlt_100_31","chapterId":"ch_work_nvlt_100","text":"《汝南先賢傳》曰：袁安為楚相，會楚王英事，互相牵引，拘系者千餘人，三年而獄不决，坐掠幽而死者百餘人，天用炎旱，赤地千里，安受拜，即控辔而行，既到，决獄事，人人具錄其辭状，本非首謀，為王所引，應時理遣，一旬之中，延千人之命，其時甘雨滂霈，歲大丰稔。","sortOrder":31},
  {"id":"s_work_nvlt_100_32","chapterId":"ch_work_nvlt_100","text":"【詩】晉李顒經渦路作詩曰：言歸越東足，逝將反上都，後洫慎中路，改轍修茲衢，旦發石亭境，夕宿桑首墟，劲焱不興润，零雨莫能濡，亢陽弥十旬，涓適未蹔舒，泉流成平陆，結驷可回車，肇允相忘鱗，翻為涸池魚，咫步不能移，白日奄桑榆。","sortOrder":32},
  {"id":"s_work_nvlt_100_33","chapterId":"ch_work_nvlt_100","text":"梁庾肩吾奉和武帝苦旱詩曰：陽山蛇不蟄，如泽鳥猶攒，蹔息流膏雨，將似怨祁寒，文衣夜不臥，疏食晝忘餐，絜誠同望祀，惟馨等浴蘭，江蘋享上帝，荆璧奠高峦，繁雲興嶽立，蒸穴動龍蟠，渭渠還積水，滮池更起澜。","sortOrder":33},
  {"id":"s_work_nvlt_100_34","chapterId":"ch_work_nvlt_100","text":"【頌】漢東方朔旱頌曰：維昊天之大旱，失精和之正理，遙望白雲之酆淳，滃曈曈而妄止，陽風吸習而熇々，群生闵懣而愁愦，隴畝枯槁而允布，壤石相聚而為害，農夫垂拱而無為，釋其耰鉏而下涕，悲壇畔之遭禍，痛皇天之靡濟。","sortOrder":34},
  {"id":"s_work_nvlt_100_35","chapterId":"ch_work_nvlt_100","text":"【啟】梁簡文帝謝敕示苦旱詩啟曰：伏以九年之水，不傷尧政，七載之旱，無類湯朝，歲弘則公田已修，農勤則我庾惟亿，今者亢陽以來，為日未久，將恐督郵不黜，失在汝南之守，曝胔未收，無傷河南之尹，而載勞興居，仰發歌詠，無愛珪璧，有事山川，菲飲食矣，加之以撤膳焉，中夜不寐，加之以申旦焉，此唐虞之所闕如，軒頊之所不逮。","sortOrder":35},
  {"id":"s_work_nvlt_100_36","chapterId":"ch_work_nvlt_100","text":"【書】魏應璩與廣川長岑瑜書曰：頃者炎旱，日更增甚，砂砾銷鑠，草木燋卷，處涼台而有鬱蒸之煩，浴寒水而有烁烂之燥，宇宙雖廣，無陰以憩，雲漢之詩，何以過此，土龍矯首於玄寺，泥人鶴立於闕里，修之歷旬，靜無徵效，明勸教之術，非致雨之備也，知恤下民，躬自曝露，拜起靈壇，勤亦至矣，昔夏禹之解陽旱，殷湯之祷桑林，言未發而水旋流，辭未卒而泽滂霈，今者雲重散而复積，雨垂落而复收，無賢聖殊品，優劣異姿乎。","sortOrder":36},
  {"id":"s_work_nvlt_100_37","chapterId":"ch_work_nvlt_100","text":"【文】魏陳王曹植誥咎文曰：五行致灾，先史鹹以為應政而作，天地之氣，自有变動，未必政治之所興致也，於時大風，發屋拔木，意有感焉，聊假天帝之命，以誥咎祈福，其辭曰：上帝有命，風伯雨師，夫風以動氣，雨以润時，陰陽协和，庶物以滋，亢陽害苗，暴風傷條，伊周是過，在湯斯遭，桑林既祷，慶雲克舉，偃禾之复，姬公走楚，况我皇德，承天統民，禮敬川嶽，祇肅百神，享茲元吉，釐福日新，至若炎旱赫羲，飆風扇發，嘉卉以萎，良木以拔，何穀宜填，何山應伐，何靈宜論，何神宜誥，於是五靈振竦，皇祇赫怒，招搖警法，攙搶奋斧，河伯典泽，屏翳司風，右呵飛廉，顧叱丰隆，息飆遏暴，元敕華嵩，慶雲是興，效厥年丰，遂乃沈陰坱圠，甘泽微微，雨我公田，爰暨予私，黍稷盈畴，芳草依依，靈禾重穗，生彼邦畿，年登歲丰，民無餒飢。","sortOrder":37},
  {"id":"s_work_nvlt_100_38","chapterId":"ch_work_nvlt_100","text":"◇祈雨","sortOrder":38},
  {"id":"s_work_nvlt_100_39","chapterId":"ch_work_nvlt_100","text":"《呂氏春秋》曰：昔者殷湯，克夏而王天下，五年不雨，湯乃以身祷於桑林，於是翦其發，割其爪，以為犧，用祈福於上帝。","sortOrder":39},
  {"id":"s_work_nvlt_100_40","chapterId":"ch_work_nvlt_100","text":"荀卿《大略》曰：湯旱而祷曰：政不節與，使民疾與，宮室榮與，女謁盛與，苞苴行與，讒夫興與，何不雨至斯極也。","sortOrder":40},
  {"id":"s_work_nvlt_100_41","chapterId":"ch_work_nvlt_100","text":"《說苑》雲：湯之時，大旱七年，雒坼川竭，煎沙烂石，於是使人持三足鼎祝山川，教之祝曰：政不節耶，使民疾耶，蓋辭未已，而天下大雨。","sortOrder":41},
  {"id":"s_work_nvlt_100_42","chapterId":"ch_work_nvlt_100","text":"董仲舒曰：廣陵女子諸巫，毋小大，皆相聚，其郭門外，為小壇，以脯酒祭，便移市，市使門者，無內丈夫，丈夫無得相從飲食。又令吏各往视其夫，皆言到即赴，雨澍而已。","sortOrder":42},
  {"id":"s_work_nvlt_100_43","chapterId":"ch_work_nvlt_100","text":"又曰：江都相仲舒，下內史承書從事，其都間吏家在百里內，皆令人故行書告縣，遣妻视夫，賜巫一月租，使巫求雨，复使巫相推擇絜净易教者祭，跪祝曰：天生五穀以養人，今五穀病旱，恐不成，敬進清酒甘羞，再拜請雨。","sortOrder":43},
  {"id":"s_work_nvlt_100_44","chapterId":"ch_work_nvlt_100","text":"又曰：春旱求雨，令縣邑以水曰：［春秋繁露求雨篇作日，後同。］今［○春秋繁露作令。］民祷社，家人祠戶，無斬山林，曝巫聚尫，以玄酒脯，再拜請雨，奉牲祷，以甲乙日為大蒼龍一，長八丈，居中，為小龍七，長各四丈，於東方乡，其間相去八尺，小童八人，皆齊三日，服青衣而舞之，諸里社取五虾蟆，错里社之中，池方八尺，深一尺，置水虾蟆焉，其酒脯祝，齊三日，拜跪陳祝如初，取三歲雄雞，與三歲猳猪，皆燔之於四通神雩。","sortOrder":44},
  {"id":"s_work_nvlt_100_45","chapterId":"ch_work_nvlt_100","text":"又曰：夏求雨，令縣邑以水曰家人祀竈，無舉土功，更水浚井，曝釜甑杵臼於衢，七日，為四通之壇於邑南門之外，方七尺，植赤繒七，其神蚩尤，祭之以赤雄雞七，玄酒清酒祝，斋三日，服赤衣，跪陳祝，如春辭，以丙丁日為赤龍一，長各七尺，斋三日，服赤衣而舞之，司空啬夫，亦斋三日，服赤衣而立之，凿社而通之闾外之溝，取五虾蟆置社之中池，方七尺，深一尺，酒脯祝，齊衣拜跪陳祝，如初，取三歲雄雞豭猪，燔之四通神雩，开陰陽如春。","sortOrder":45},
  {"id":"s_work_nvlt_100_46","chapterId":"ch_work_nvlt_100","text":"又曰：季春［春秋繁露作夏。］祷山陵以助之，令縣邑一［春秋繁露一上有十日二字。］徙市，於邑南門之外，五日，禁男女毋得行入市，家人祠中霤，毋舉土功，聚巫，市旁為四通之壇，於中央植黃幡五，其神後稷，祭之母肫五，玄脯祝，斋三日，衣黃衣，皆如春辭，以戊己日為大黃龍一，長五丈，居中央。又為小龍，長各三丈五尺，土姓五人，皆斋三日，服黃衣而舞之，老者五人，斋三日，衣黃衣而立之，亦通社中於闾外之溝，虾蟆池方五尺，深一尺，皆如前。","sortOrder":46},
  {"id":"s_work_nvlt_100_47","chapterId":"ch_work_nvlt_100","text":"《搜神記》曰：谅辅，字漢儒，廣漢新都人，少給佐史，漿水不交，為從事，大小畢舉，郡縣斂手，夏枯旱，時以五官掾出祷山川，曰：辅為郡股肱，不能進諫納忠，荐賢退惡，和調陰陽，至令天下否滠，萬物燋枯，百姓喁喁，無所告訴，咎盡在辅，太守內省责己，自曝中庭，使辅謝罪，為民祈福，曰無效，令［疑當作今。］敢自誓，至日中雨不降，請以身塞無状，乃積薪柴，將自焚焉，至禺中時，山氣轉起，雷雨大作，一邵霑润也，以稱其至誠。","sortOrder":47},
  {"id":"s_work_nvlt_100_48","chapterId":"ch_work_nvlt_100","text":"【序】晉傅鹹喜雨賦序曰：泰始九年，自春不雨，以涉夏節，草木共然，百姓以尧有九載之水，湯有七年之旱，恐遭斯運，併有懼心，聖皇勞慮，分使祈祷，遍於群臣，餘以太子洗馬兼司徒請雨，百辟莅事，三朝而大雨降，退作斯賦。","sortOrder":48},
  {"id":"s_work_nvlt_100_49","chapterId":"ch_work_nvlt_100","text":"【文】晉曹毗請雨文曰：下邳［原訛血阝，據冯校本改。］內史曹毗，敬告山川諸靈，頃節運错戾，旱亢陰消，川竭穀虛，石流山燋，天無纖雲，野有橫飆，盛夏應暑而或涼，草木無霜而自凋，遑遑農夫，輟耕田畔，悠悠舟人，頓楫川岸，雲根山積而中披，雨足垂零而复散，聖主當膳而减味，牧伯忘餐而過晏，民庶拊心而嚬蹙，搢紳不期而同叹，斯亦忧勤之極情，而明靈之達觀矣。","sortOrder":49},
  {"id":"s_work_nvlt_100_50","chapterId":"ch_work_nvlt_100","text":"梁陆倕請雨赛蒋王文曰：陆周祚胤，鍾嶽降精，聰明正直，得一居貞，無方無體，不疾不行，化馳九縣，位冠百靈，東掩屢愆，西郊已戢，偶龍矯首，泥人鶴立，神聽孔殷，靈應揮霍，儵睹翻伊，俄聞倒洛，樂周神畢，恩洽酒阑，靈談抗袖，鬼笑投拌，惟茲具引，於萬斯懽。","sortOrder":50},
  {"id":"s_work_nvlt_100_51","chapterId":"ch_work_nvlt_100","text":"梁任孝恭赛鍾山蒋帝文曰：嘗聞河南少雨，漢主避其正殿，許下輟润，魏後讨彼尘書，和氣乖违，陰陽舛互，風至若湯，雲生猶火，遂能製茲東井，告彼南箕，水滿畢星，氣冲卯地，使君子有亹亹之心，耕夫無慼慼之念。","sortOrder":51},
  {"id":"s_work_nvlt_100_52","chapterId":"ch_work_nvlt_100","text":"梁簡文帝祭灰人文曰：積註奄旬，祭在灰人，消茲獸炭，焚此桂薪，積如玉屑，聚若遊尘，庶人之風不拂，獄吏之慢寧陳，當令金光小史，侍使玉童，奏雲師於執法，力水伯於天宮，锧星誅於電女，貫索囚於雷公，廓重氛於八極，靜連絲於四空，既曈曈於車蓋。又赫赫於飛盤，且疑威於趙盾，實望近於□□，［明本作長安。］","sortOrder":52},
  {"id":"s_work_nvlt_100_54","chapterId":"ch_work_nvlt_100","text":"《爾雅》曰：食苗心曰螟，食葉曰螣，食根曰蟊，食節曰賊，四蝗虫名也。","sortOrder":54},
  {"id":"s_work_nvlt_100_55","chapterId":"ch_work_nvlt_100","text":"《說文》曰：蝗，螽也。","sortOrder":55},
  {"id":"s_work_nvlt_100_56","chapterId":"ch_work_nvlt_100","text":"《廣雅》曰：螽，蝗也。","sortOrder":56},
  {"id":"s_work_nvlt_100_57","chapterId":"ch_work_nvlt_100","text":"《毛詩》曰：去其螟螣，及其蟊賊。","sortOrder":57},
  {"id":"s_work_nvlt_100_58","chapterId":"ch_work_nvlt_100","text":"《詩義疏》曰：赤螣，蝗也，許慎曰：使乞貸則生螣，舊說螟螣蛑賊，一种虫也，如言寇賊奸宄，內外言之耳，故犍為文學曰：此四种虫皆蝗也，實不同，故分別釋之。","sortOrder":58},
  {"id":"s_work_nvlt_100_59","chapterId":"ch_work_nvlt_100","text":"又曰：蝗也，今謂蝗子為螽，一名蠶螽，兖州人謂之螣，蔡伯喈曰：蝗，螣也，當為灾則生，故水處泽中，數百或數十里，一朝蔽地，而食禾粟，苗盡复移，雖自有种，其為灾，雲是魚子在水中化為之。","sortOrder":59},
  {"id":"s_work_nvlt_100_60","chapterId":"ch_work_nvlt_100","text":"《穀梁傳》曰：雨螽於宋，外灾不書，此何書，灾甚也，奈何，茅茨盡也。","sortOrder":60},
  {"id":"s_work_nvlt_100_61","chapterId":"ch_work_nvlt_100","text":"《洪范五行傳》曰：春秋之螽者，虫灾也，以刑罰暴虐，貪叨無厭，興師動眾，虫為害矣，雨螽於宋，是時宋公暴虐刑重，賦斂無已，故應是而雨螽。","sortOrder":61},
  {"id":"s_work_nvlt_100_62","chapterId":"ch_work_nvlt_100","text":"又曰：介虫有甲，能蜚扬之類，陽氣所生，於春秋為螽，今謂之蝗，皆其類也，旱氣動象至矣，故曰有介虫之孽也。","sortOrder":62},
  {"id":"s_work_nvlt_100_63","chapterId":"ch_work_nvlt_100","text":"《春秋佐助期》曰：螽之為虫，赤頭甲身，而翼飛行，陰中陽也，螽之為言眾，暴眾也。","sortOrder":63},
  {"id":"s_work_nvlt_100_64","chapterId":"ch_work_nvlt_100","text":"《春秋□［按當作漢，後同。］含孳》曰：蝗起於貪，螽者飛而甲為害，故天雨螽則刑法丑。","sortOrder":64},
  {"id":"s_work_nvlt_100_65","chapterId":"ch_work_nvlt_100","text":"《呂氏春秋》曰：匡章，孟子弟子，謂惠子於魏王之前曰：蝗螟，農夫得而殺之奚故，為其害稼也蔽天，状如嚴雪，是歲天下失瓜瓠。","sortOrder":65},
  {"id":"s_work_nvlt_100_66","chapterId":"ch_work_nvlt_100","text":"《漢書》曰：武帝元光五年秋，蝗，四將征南越，元封六年秋，蝗，兩將征朝鮮，太初元年夏，蝗，從東方飛至敦煌，三年秋，复蝗，貳師征大宛，征和三年，蝗，四年夏，蝗，三將征匈奴，貳師七萬人没不還。","sortOrder":66},
  {"id":"s_work_nvlt_100_67","chapterId":"ch_work_nvlt_100","text":"又，五行志曰：劉歆以為蜚，負螽也，性不食穀，食穀為灾，介虫之孽。","sortOrder":67},
  {"id":"s_work_nvlt_100_68","chapterId":"ch_work_nvlt_100","text":"又曰：嚴延年為河南太守，多殺害，時黃霸在潁川，鳳皇下，而河南界中又有蝗虫，延年曰：此蝗豈鳳皇食耶。","sortOrder":68},
  {"id":"s_work_nvlt_100_69","chapterId":"ch_work_nvlt_100","text":"又曰：王莽地節三年夏，蝗，從東方來，飛蔽天，至長安，入未央宮，緣殿。","sortOrder":69},
  {"id":"s_work_nvlt_100_70","chapterId":"ch_work_nvlt_100","text":"《京房易傳》曰：德無節，虫食菜。","sortOrder":70},
  {"id":"s_work_nvlt_100_71","chapterId":"ch_work_nvlt_100","text":"《東觀漢記》曰：馬稜為廣陵太守，郡連有蝗虫，穀价貴，稜奏罢鹽官，振貧羸，薄賦稅，蝗虫飛入海，化為魚虾。","sortOrder":71},
  {"id":"s_work_nvlt_100_72","chapterId":"ch_work_nvlt_100","text":"又曰：永初七年，郡國蝗飛過。","sortOrder":72},
  {"id":"s_work_nvlt_100_73","chapterId":"ch_work_nvlt_100","text":"又曰：宋均為九江太守，建武中，山陽楚郡多蝗蜚，南到九江，辄東西別去，由是名稱。","sortOrder":73},
  {"id":"s_work_nvlt_100_74","chapterId":"ch_work_nvlt_100","text":"又曰：司部灾蝗，台召三府驅之，司空掾梁福曰：普天之下，莫非王土，不審使臣驅蝗何之，灾蝗當以德消，不聞驅逐，時號福為直掾。","sortOrder":74},
  {"id":"s_work_nvlt_100_75","chapterId":"ch_work_nvlt_100","text":"謝承《後漢書》曰：吳郡徐栩，為小黃令，時陳留遭蝗，過小黃，飛逝不集，刺史行部，责栩不治，栩弃官，蝗應聲而至，刺史謝，令還寺舍，蝗即皆去。","sortOrder":75},
  {"id":"s_work_nvlt_100_76","chapterId":"ch_work_nvlt_100","text":"又曰：謝夷吾為寿張令，是時蝗食五穀，野無生草，過寿張界，飛逝不集。","sortOrder":76},
  {"id":"s_work_nvlt_100_77","chapterId":"ch_work_nvlt_100","text":"又曰：許季長為湖令，州郡皆被蝗灾，過湖縣，飛去不入。","sortOrder":77},
  {"id":"s_work_nvlt_100_78","chapterId":"ch_work_nvlt_100","text":"《續漢書》曰：和帝永元四年，蝗，八年五月，河內陳留蝗，九月，京師蝗，九年。蝗，從夏至秋，先是西羌數反，遣將軍將北軍五挍征之，安帝永初四年夏，蝗，是時西羌寇亂，軍眾征距，連十餘年，五年夏，九州蝗，六年三月，去年蝗處，复蝗子生，七年二月，郡國蝗，順帝永建五年，郡國十二蝗，是時鮮卑寇朔方，用眾征之，永和七年，偃師蝗，去年冬，乌桓寇沙南，用眾征之，桓帝永興元年七月，郡國三十二蝗，是時梁冀執政，無謀慮，苟貪作虐，二年六月，京都蝗，永寿三年六月，京都蝗，延喜元年五月，京都蝗，靈帝嘉平六年夏，七州蝗，鮮卑前後三十餘犯塞，是歲，獲乌桓校尉夏育，破鮮卑，中郎將田晏使匈奴中郎將威旻，讨鮮卑，大司農給用不足，畝斂郡國，以給軍糧，三將無功，還者少半，光和元年，詔策問曰：連年蝗虫至，貪苟之所致也，是時百官遷徙，皆私上种［續漢書五行志作禮。］西園，少帝興平元年，夏大蝗，是時天下大亂。","sortOrder":78},
  {"id":"s_work_nvlt_100_79","chapterId":"ch_work_nvlt_100","text":"《論衡》曰：世稱南陽卓公為缑氏令，蝗虫不入界，蓋以賢明至誠，灾虫不入其縣。","sortOrder":79},
  {"id":"s_work_nvlt_100_80","chapterId":"ch_work_nvlt_100","text":"《典論》曰：議郎馬融，以永興中，帝獵廣城，融從，是時北州遭水潦蝗虫，融撰上林頌以諷。","sortOrder":80},
  {"id":"s_work_nvlt_100_81","chapterId":"ch_work_nvlt_100","text":"《魏志》曰：黃［原訛廣，據冯校本改。］初三年七月，冀州大蝗，民飢，使尚書杜畿，持節，开仓廪以振之。","sortOrder":81},
  {"id":"s_work_nvlt_100_82","chapterId":"ch_work_nvlt_100","text":"《吳書》曰：袁術在寿春，穀石百餘萬，載金錢之市求籴，市無米而弃錢去，百姓飢窮，以桑椹蝗虫為乾飯。","sortOrder":82},
  {"id":"s_work_nvlt_100_83","chapterId":"ch_work_nvlt_100","text":"《廣州先賢傳》曰：黃豪，交趾人，除外黃令，豪均己節俭，粗衣蔬食，所得俸秩，悉賜貧民，一縣稱平，當時鄰縣蝗虫為灾，而獨外黃無有，歲皆丰熟，民先流移者，悉歸附之。","sortOrder":83},
  {"id":"s_work_nvlt_100_84","chapterId":"ch_work_nvlt_100","text":"《會稽典錄》曰：鄭弘為鄹令，永平十五年，蝗發太山，郡國被害，過鄹不集，郡以状上，詔書以為不然，自朕治京師，尚不能攘蝗，鄹令何人，而令消弭，遣案验之。","sortOrder":84},
  {"id":"s_work_nvlt_100_85","chapterId":"ch_work_nvlt_100","text":"《陳留耆舊傳》曰：高慎，敦厚少華，子式，至孝，常盡力供養，永初中，蝝蝗為灾，獨不食式麥，圉令周強，以表州郡。","sortOrder":85},
  {"id":"s_work_nvlt_100_86","chapterId":"ch_work_nvlt_100","text":"《益部耆舊傳》曰：任防，蜀郡成都人，父修，字伯慶，為固始侯相，天下大蝗，獨不入界。","sortOrder":86},
  {"id":"s_work_nvlt_100_87","chapterId":"ch_work_nvlt_100","text":"又傳曰：楊琳為茂陵令，比縣連歲蝗灾，曲折不入茂陵。","sortOrder":87},
  {"id":"s_work_nvlt_100_88","chapterId":"ch_work_nvlt_100","text":"《先賢行状》曰：公沙穆為魯相，時有蝗灾，穆躬露坐界上，蝗積疆畔，不為害。","sortOrder":88},
  {"id":"s_work_nvlt_100_89","chapterId":"ch_work_nvlt_100","text":"《晉令》曰：常以蝗向生時，各部吏案行境界，行其所由，勒生苗之內，皆令周遍。","sortOrder":89},
  {"id":"s_work_nvlt_100_90","chapterId":"ch_work_nvlt_100","text":"《晉陽秋》曰：司冀青雍蝗，茅草皆盡，石勒與蝗競取民禾，百姓謂之胡蝗。","sortOrder":90},
  {"id":"s_work_nvlt_100_91","chapterId":"ch_work_nvlt_100","text":"《搜神記》曰：何敞，吳郡人，少好道藝，隱居，重以大旱，民物憔悴，太守慶洪，遣戶曹掾致謁，奉印綬，煩守無錫，敞不受，退叹而言曰：郡界有灾，安能得懷道，因跋涉之縣，駐明星屋中，蝗蝝消死，敞即遁去，後舉方正博士，皆不就，卒於家。","sortOrder":91},
  {"id":"s_work_nvlt_100_92","chapterId":"ch_work_nvlt_100","text":"趙書曰：石勒十四年五月，飛蝗穿地而生，二十日，化如蠶，七八日作虫，四日則飛，周遍河朔，百草無遺，唯不食三豆及麻。","sortOrder":92},
  {"id":"s_work_nvlt_100_93","chapterId":"ch_work_nvlt_100","text":"涼記曰：涼王呂光麟嘉二年，以且渠羅仇為西寧太守，往年蝗虫所到之處，產子地中，是月盡生，或一頃二頃，覆地跳躍，宿昔变異，王乃躬臨扑虫，幸扬川潒水北，大駕所到，虫尋除盡，是以麥苗損耗無幾。","sortOrder":93},
  {"id":"s_work_nvlt_100_94","chapterId":"ch_work_nvlt_100","text":"師覺授《孝子傳》曰：魏連，事父至孝，和帝時，拜昌邑令，百姓不忍欺，大蝗連熟。","sortOrder":94},
  {"id":"s_work_nvlt_100_95","chapterId":"ch_work_nvlt_100","text":"【箋】何禎箋曰：凡言蝗生，此謂見其始生，知其處所，可得言，初上蝗事雲，縣及下部，各不旱見，至今生翅能飛，臣辄躬親扑滅。又雲布在及下部各不旱見，至頃田中，往往十步五步一頭，按其言事，蝗之數枚數，可得而知也。","sortOrder":95},
  {"id":"s_work_nvlt_100_97","chapterId":"ch_work_nvlt_100","text":"《爾雅》曰：食苗心曰螟。","sortOrder":97},
  {"id":"s_work_nvlt_100_98","chapterId":"ch_work_nvlt_100","text":"《說文》曰：螟虫食穀心，吏冥冥犯法，即生螟。","sortOrder":98},
  {"id":"s_work_nvlt_100_99","chapterId":"ch_work_nvlt_100","text":"《禮記》曰：仲春行夏令，則虫螟為害。","sortOrder":99},
  {"id":"s_work_nvlt_100_100","chapterId":"ch_work_nvlt_100","text":"《左傳》曰：哀十二年螟，十三年螟。","sortOrder":100},
  {"id":"s_work_nvlt_100_101","chapterId":"ch_work_nvlt_100","text":"《春秋□含孳》曰：螟應苛剋。","sortOrder":101},
  {"id":"s_work_nvlt_100_102","chapterId":"ch_work_nvlt_100","text":"《呂氏春秋》曰：亂國之妖，有螟集其地，其音凶凶。","sortOrder":102},
  {"id":"s_work_nvlt_100_103","chapterId":"ch_work_nvlt_100","text":"《漢書》曰：劉歆以為，蝝蜫〈虫不〉之有實，食穀為灾，黑眚也，董仲舒劉向以為，蝝螟始生也，是時初稅畝，亂先王之製，故應是而蝝生，屬蠃虫之孽。","sortOrder":103},
  {"id":"s_work_nvlt_100_104","chapterId":"ch_work_nvlt_100","text":"《京房易傳》曰：嬖惡生孽，虫食苗心。","sortOrder":104},
  {"id":"s_work_nvlt_100_105","chapterId":"ch_work_nvlt_100","text":"《東觀漢記》曰：魯恭為中牟令，時郡國螟傷稼，犬牙緣界，不入中牟，河南尹袁安聞之，疑其不實，使仁恕掾肥親往察之，恭隨行阡陌，俱坐桑下，有雉過止其傍，傍有童兒，親曰：何不捕之，兒言雉方將雏，親曰：所以來者，欲察君之治跡耳，今虫不犯境，此一異也，化及鳥獸，此二異也，竖子有仁心，三異也，具以状白安。","sortOrder":105},
  {"id":"s_work_nvlt_100_107","chapterId":"ch_work_nvlt_100","text":"《爾雅》曰：食苗根曰蟊。","sortOrder":107},
  {"id":"s_work_nvlt_100_108","chapterId":"ch_work_nvlt_100","text":"《說文》曰：蟊，食苗根者也，吏抵冒取民财，則生蟊。","sortOrder":108},
  {"id":"s_work_nvlt_100_109","chapterId":"ch_work_nvlt_100","text":"京房易妖占曰：害忠孝，虫食苗根。","sortOrder":109},
  {"id":"s_work_nvlt_100_110","chapterId":"ch_work_nvlt_100","text":"《毛詩義疏》：蟊長而細，或說雲，蟊，蝼蛄也，食苗根而為人患。","sortOrder":110},
  {"id":"s_work_nvlt_100_112","chapterId":"ch_work_nvlt_100","text":"《爾雅》曰：食苗節曰賊。","sortOrder":112},
  {"id":"s_work_nvlt_100_113","chapterId":"ch_work_nvlt_100","text":"《京房易傳》曰：王者與諸侯爭，虫食苗節茎。","sortOrder":113},
  {"id":"s_work_nvlt_100_115","chapterId":"ch_work_nvlt_100","text":"《洪范五行傳》曰：蜮，射人者也，生於南越地，南方謂之短狐者也，毛詩曰：為鬼為蜮，則不可得，其物不可見，蓋氣精也，南越夷狄淫佚處也，其蜮生水泽，地多婦人，其淫色為主，故南越多蜮者，淫女惑亂之所生也，故聖人名之曰蜮，蜮者猶惑也。","sortOrder":115},
  {"id":"s_work_nvlt_100_116","chapterId":"ch_work_nvlt_100","text":"【書】魏應璩與西陽令孔德琰書曰：嘉麥禎祥，惟日未久，不圖飛蝗，一旦至止，知恤蒸庶，念存良苗，親發赫斯，爰整其旅，鲐背之叟，皓首之釐，莫不負戈奔走於道路，旌表曜於白日，黿鼍震於雷動，以此扫敵，必將席卷，况於微虫，能無驚駭，卓茂治密，恭在中牟，時雖有灾，未若斯勤，亦猶子賤鳴琴，巫馬出入，勞逸有殊，立功惟一，重雲比興，不降靈雨，麗此二灾，忧心忡惙，逐蝗之道，謹聞教矣，不審致禳，將以何物，文王修德，以厭地震，湯祷桑林，致克丰雨，宜脩善政，以慰民望。","sortOrder":116},
];

export const nvltOverrides: Record<string, Record<string, [string, string, string]>> = {};
